INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1', '1', '1', '1', '＜ 神 的 创 造 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2', '1', '1', '2', '地 是 空 虚 混 沌 ， 渊 面 黑 暗 ； 神 的 灵 运 行 在 水 面 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3', '1', '1', '3', '神 说 ： “ 要 有 光 ” ， 就 有 了 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4', '1', '1', '4', '神 看 光 是 好 的 ， 就 把 光 暗 分 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5', '1', '1', '5', '神 称 光 为 “ 昼 ” ， 称 暗 为 “ 夜 ” 。 有 晚 上 ， 有 早 晨 ， 这 是 头 一 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6', '1', '1', '6', '神 说 ： “ 诸 水 之 间 要 有 空 气 ， 将 水 分 为 上 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('7', '1', '1', '7', '神 就 造 出 空 气 ， 将 空 气 以 下 的 水 、 空 气 以 上 的 水 分 开 了 。 事 就 这 样 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('8', '1', '1', '8', '神 称 空 气 为 “ 天 ” 。 有 晚 上 ， 有 早 晨 ， 是 第 二 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9', '1', '1', '9', '神 说 ： “ 天 下 的 水 要 聚 在 一 处 ， 使 旱 地 露 出 来 。 ” 事 就 这 样 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10', '1', '1', '10', '神 称 旱 地 为 “ 地 ” ， 称 水 的 聚 处 为 “ 海 ” 。 神 看 着 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11', '1', '1', '11', '神 说 ： “ 地 要 发 生 青 草 和 结 种 子 的 菜 蔬 ， 并 结 果 子 的 树 木 ， 各 从 其 类 ， 果 子 都 包 着 核 。 ” 事 就 这 样 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12', '1', '1', '12', '于 是 地 发 生 了 青 草 和 结 种 子 的 菜 蔬 ， 各 从 其 类 ； 并 结 果 子 的 树 木 ， 各 从 其 类 ； 果 子 都 包 着 核 。 神 看 着 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('13', '1', '1', '13', '有 晚 上 ， 有 早 晨 ， 是 第 三 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('14', '1', '1', '14', '神 说 ： “ 天 上 要 有 光 体 ， 可 以 分 昼 夜 ， 作 记 号 ， 定 节 令 、 日 子 、 年 岁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('15', '1', '1', '15', '并 要 发 光 在 天 空 ， 普 照 在 地 上 。 ” 事 就 这 样 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('16', '1', '1', '16', '于 是 神 造 了 两 个 大 光 ， 大 的 管 昼 ， 小 的 管 夜 ， 又 造 众 星 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17', '1', '1', '17', '就 把 这 些 光 摆 列 在 天 空 ， 普 照 在 地 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18', '1', '1', '18', '管 理 昼 夜 ， 分 别 明 暗 。 神 看 着 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19', '1', '1', '19', '有 晚 上 ， 有 早 晨 ， 是 第 四 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20', '1', '1', '20', '神 说 ： “ 水 要 多 多 滋 生 有 生 命 的 物 ； 要 有 雀 鸟 飞 在 地 面 以 上 ， 天 空 之 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21', '1', '1', '21', '神 就 造 出 大 鱼 和 水 中 所 滋 生 各 样 有 生 命 的 动 物 ， 各 从 其 类 ； 又 造 出 各 样 飞 鸟 ， 各 从 其 类 。 神 看 着 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22', '1', '1', '22', '神 就 赐 福 给 这 一 切 ， 说 ： “ 滋 生 繁 多 ， 充 满 海 中 的 水 ； 雀 鸟 也 要 多 生 在 地 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23', '1', '1', '23', '有 晚 上 ， 有 早 晨 ， 是 第 五 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24', '1', '1', '24', '神 说 ： “ 地 要 生 出 活 物 来 ， 各 从 其 类 ； 牲 畜 、 昆 虫 、 野 兽 ， 各 从 其 类 。 ” 事 就 这 样 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25', '1', '1', '25', '于 是 神 造 出 野 兽 ， 各 从 其 类 ； 牲 畜 ， 各 从 其 类 ； 地 上 一 切 昆 虫 ， 各 从 其 类 。 神 看 着 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26', '1', '1', '26', '神 说 ： “ 我 们 要 照 着 我 们 的 形 像 、 按 着 我 们 的 样 式 造 人 ， 使 他 们 管 理 海 里 的 鱼 、 空 中 的 鸟 、 地 上 的 牲 畜 ， 和 全 地 ， 并 地 上 所 爬 的 一 切 昆 虫 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27', '1', '1', '27', '神 就 照 着 自 己 的 形 像 造 人 ， 乃 是 照 着 他 的 形 像 造 男 造 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28', '1', '1', '28', '神 就 赐 福 给 他 们 ， 又 对 他 们 说 ： “ 要 生 养 众 多 ， 遍 满 地 面 ， 治 理 这 地 ， 也 要 管 理 海 里 的 鱼 、 空 中 的 鸟 ， 和 地 上 各 样 行 动 的 活 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29', '1', '1', '29', '神 说 ： “ 看 哪 ， 我 将 遍 地 上 一 切 结 种 子 的 菜 蔬 和 一 切 树 上 所 结 有 核 的 果 子 全 赐 给 你 们 作 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30', '1', '1', '30', '至 于 地 上 的 走 兽 和 空 中 的 飞 鸟 ， 并 各 样 爬 在 地 上 有 生 命 的 物 ， 我 将 青 草 赐 给 它 们 作 食 物 。 ” 事 就 这 样 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31', '1', '1', '31', '神 看 着 一 切 所 造 的 都 甚 好 。 有 晚 上 ， 有 早 晨 ， 是 第 六 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('32', '1', '2', '1', '天 地 万 物 都 造 齐 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('33', '1', '2', '2', '到 第 七 日 ， 神 造 物 的 工 已 经 完 毕 ， 就 在 第 七 日 歇 了 他 一 切 的 工 ， 安 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('34', '1', '2', '3', '神 赐 福 给 第 七 日 ， 定 为 圣 日 ； 因 为 在 这 日 ， 神 歇 了 他 一 切 创 造 的 工 ， 就 安 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('35', '1', '2', '4', '＜ 伊 甸 园 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('36', '1', '2', '5', '野 地 还 没 有 草 木 ， 田 间 的 菜 蔬 还 没 有 长 起 来 ； 因 为 耶 和 华 神 还 没 有 降 雨 在 地 上 ， 也 没 有 人 耕 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('37', '1', '2', '6', '但 有 雾 气 从 地 上 腾 ， 滋 润 遍 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('38', '1', '2', '7', '耶 和 华 神 用 地 上 的 尘 土 造 人 ， 将 生 气 吹 在 他 鼻 孔 里 ， 他 就 成 了 有 灵 的 活 人 ， 名 叫 亚 当 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('39', '1', '2', '8', '耶 和 华 神 在 东 方 的 伊 甸 立 了 一 个 园 子 ， 把 所 造 的 人 安 置 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('40', '1', '2', '9', '耶 和 华 神 使 各 样 的 树 从 地 里 长 出 来 ， 可 以 悦 人 的 眼 目 ， 其 上 的 果 子 好 作 食 物 。 园 子 当 中 又 有 生 命 树 和 分 别 善 恶 的 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('41', '1', '2', '10', '有 河 从 伊 甸 流 出 来 ， 滋 润 那 园 子 ， 从 那 里 分 为 四 道 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('42', '1', '2', '11', '第 一 道 名 叫 比 逊 ， 就 是 环 绕 哈 腓 拉 全 地 的 。 在 那 里 有 金 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('43', '1', '2', '12', '并 且 那 地 的 金 子 是 好 的 ； 在 那 里 又 有 珍 珠 和 红 玛 瑙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('44', '1', '2', '13', '第 二 道 河 名 叫 基 训 ， 就 是 环 绕 古 实 全 地 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('45', '1', '2', '14', '第 三 道 河 名 叫 底 格 里 斯 ， 流 在 亚 述 的 东 边 。 第 四 道 河 就 是 幼 发 拉 底 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('46', '1', '2', '15', '耶 和 华 神 将 那 人 安 置 在 伊 甸 园 ， 使 他 修 理 ， 看 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('47', '1', '2', '16', '耶 和 华 神 吩 咐 他 说 ： “ 园 中 各 样 树 上 的 果 子 ， 你 可 以 随 意 吃 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('48', '1', '2', '17', '只 是 分 别 善 恶 树 上 的 果 子 ， 你 不 可 吃 ， 因 为 你 吃 的 日 子 必 定 死 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('49', '1', '2', '18', '耶 和 华 神 说 ： “ 那 人 独 居 不 好 ， 我 要 为 他 造 一 个 配 偶 帮 助 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('50', '1', '2', '19', '耶 和 华 神 用 土 所 造 成 的 野 地 各 样 走 兽 和 空 中 各 样 飞 鸟 都 带 到 那 人 面 前 ， 看 他 叫 什 么 。 那 人 怎 样 叫 各 样 的 活 物 ， 那 就 是 它 的 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('51', '1', '2', '20', '那 人 便 给 一 切 牲 畜 和 空 中 飞 鸟 、 野 地 走 兽 都 起 了 名 ； 只 是 那 人 没 有 遇 见 配 偶 帮 助 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('52', '1', '2', '21', '耶 和 华 神 使 他 沉 睡 ， 他 就 睡 了 ； 于 是 取 下 他 的 一 条 肋 骨 ， 又 把 肉 合 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('53', '1', '2', '22', '耶 和 华 神 就 用 那 人 身 上 所 取 的 肋 骨 造 成 一 个 女 人 ， 领 她 到 那 人 跟 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('54', '1', '2', '23', '那 人 说 ： 这 是 我 骨 中 的 骨 ， 肉 中 的 肉 ， 可 以 称 她 为 “ 女 人 ” ， 因 为 她 是 从 “ 男 人 ” 身 上 取 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('55', '1', '2', '24', '因 此 ， 人 要 离 开 父 母 ， 与 妻 子 连 合 ， 二 人 成 为 一 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('56', '1', '2', '25', '当 时 夫 妻 二 人 赤 身 露 体 ， 并 不 羞 耻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('57', '1', '3', '1', '＜ 人 违 背 命 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('58', '1', '3', '2', '女 人 对 蛇 说 ： “ 园 中 树 上 的 果 子 ， 我 们 可 以 吃 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('59', '1', '3', '3', '惟 有 园 当 中 那 棵 树 上 的 果 子 ， 神 曾 说 ： ‘ 你 们 不 可 吃 ， 也 不 可 摸 ， 免 得 你 们 死 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('60', '1', '3', '4', '蛇 对 女 人 说 ： “ 你 们 不 一 定 死 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('61', '1', '3', '5', '因 为 神 知 道 ， 你 们 吃 的 日 子 眼 睛 就 明 亮 了 ， 你 们 便 如 神 能 知 道 善 恶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('62', '1', '3', '6', '于 是 女 人 见 那 棵 树 的 果 子 好 作 食 物 ， 也 悦 人 的 眼 目 ， 且 是 可 喜 爱 的 ， 能 使 人 有 智 慧 ， 就 摘 下 果 子 来 吃 了 ， 又 给 她 丈 夫 ， 她 丈 夫 也 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('63', '1', '3', '7', '他 们 二 人 的 眼 睛 就 明 亮 了 ， 才 知 道 自 己 是 赤 身 露 体 ， 便 拿 无 花 果 树 的 叶 子 为 自 己 编 做 裙 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('64', '1', '3', '8', '天 起 了 凉 风 ， 耶 和 华 神 在 园 中 行 走 。 那 人 和 他 妻 子 听 见 神 的 声 音 ， 就 藏 在 园 里 的 树 木 中 ， 躲 避 耶 和 华 神 的 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('65', '1', '3', '9', '耶 和 华 神 呼 唤 那 人 ， 对 他 说 ： “ 你 在 哪 里 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('66', '1', '3', '10', '他 说 ： “ 我 在 园 中 听 见 你 的 声 音 ， 我 就 害 怕 ； 因 为 我 赤 身 露 体 ， 我 便 藏 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('67', '1', '3', '11', '耶 和 华 说 ： “ 谁 告 诉 你 赤 身 露 体 呢 ？ 莫 非 你 吃 了 我 吩 咐 你 不 可 吃 的 那 树 上 的 果 子 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('68', '1', '3', '12', '那 人 说 ： “ 你 所 赐 给 我 、 与 我 同 居 的 女 人 ， 她 把 那 树 上 的 果 子 给 我 ， 我 就 吃 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('69', '1', '3', '13', '耶 和 华 神 对 女 人 说 ： “ 你 做 的 是 什 么 事 呢 ？ ” 女 人 说 ： “ 那 蛇 引 诱 我 ， 我 就 吃 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('70', '1', '3', '14', '＜ 神 的 宣 判 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('71', '1', '3', '15', '我 又 要 叫 你 和 女 人 彼 此 为 仇 ； 你 的 后 裔 和 女 人 的 后 裔 也 彼 此 为 仇 。 女 人 的 后 裔 要 伤 你 的 头 ； 你 要 伤 他 的 脚 跟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('72', '1', '3', '16', '又 对 女 人 说 ： 我 必 多 多 加 增 你 怀 胎 的 苦 楚 ； 你 生 产 儿 女 必 多 受 苦 楚 。 你 必 恋 慕 你 丈 夫 ； 你 丈 夫 必 管 辖 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('73', '1', '3', '17', '又 对 亚 当 说 ： 你 既 听 从 妻 子 的 话 ， 吃 了 我 所 吩 咐 你 不 可 吃 的 那 树 上 的 果 子 ， 地 必 为 你 的 缘 故 受 咒 诅 ； 你 必 终 身 劳 苦 才 能 从 地 里 得 吃 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('74', '1', '3', '18', '地 必 给 你 长 出 荆 棘 和 蒺 藜 来 ； 你 也 要 吃 田 间 的 菜 蔬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('75', '1', '3', '19', '你 必 汗 流 满 面 才 得 糊 口 ， 直 到 你 归 了 土 ， 因 为 你 是 从 土 而 出 的 。 你 本 是 尘 土 ， 仍 要 归 于 尘 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('76', '1', '3', '20', '亚 当 给 他 妻 子 起 名 叫 夏 娃 ， 因 为 她 是 众 生 之 母 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('77', '1', '3', '21', '耶 和 华 神 为 亚 当 和 他 妻 子 用 皮 子 做 衣 服 给 他 们 穿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('78', '1', '3', '22', '＜ 亚 当 和 夏 娃 被 赶 出 伊 甸 园 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('79', '1', '3', '23', '耶 和 华 神 便 打 发 他 出 伊 甸 园 去 ， 耕 种 他 所 自 出 之 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('80', '1', '3', '24', '于 是 把 他 赶 出 去 了 ； 又 在 伊 甸 园 的 东 边 安 设 基 路 伯 和 四 面 转 动 发 火 焰 的 剑 ， 要 把 守 生 命 树 的 道 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('81', '1', '4', '1', '＜ 该 隐 和 亚 伯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('82', '1', '4', '2', '又 生 了 该 隐 的 兄 弟 亚 伯 。 亚 伯 是 牧 羊 的 ； 该 隐 是 种 地 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('83', '1', '4', '3', '有 一 日 ， 该 隐 拿 地 里 的 出 产 为 供 物 献 给 耶 和 华 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('84', '1', '4', '4', '亚 伯 也 将 他 羊 群 中 头 生 的 和 羊 的 脂 油 献 上 。 耶 和 华 看 中 了 亚 伯 和 他 的 供 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('85', '1', '4', '5', '只 是 看 不 中 该 隐 和 他 的 供 物 。 该 隐 就 大 大 地 发 怒 ， 变 了 脸 色 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('86', '1', '4', '6', '耶 和 华 对 该 隐 说 ： “ 你 为 什 么 发 怒 呢 ？ 你 为 什 么 变 了 脸 色 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('87', '1', '4', '7', '你 若 行 得 好 ， 岂 不 蒙 悦 纳 ？ 你 若 行 得 不 好 ， 罪 就 伏 在 门 前 。 它 必 恋 慕 你 ， 你 却 要 制 伏 它 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('88', '1', '4', '8', '该 隐 与 他 兄 弟 亚 伯 说 话 ； 二 人 正 在 田 间 。 该 隐 起 来 打 他 兄 弟 亚 伯 ， 把 他 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('89', '1', '4', '9', '耶 和 华 对 该 隐 说 ： “ 你 兄 弟 亚 伯 在 哪 里 ？ ” 他 说 ： “ 我 不 知 道 ！ 我 岂 是 看 守 我 兄 弟 的 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('90', '1', '4', '10', '耶 和 华 说 ： “ 你 做 了 什 么 事 呢 ？ 你 兄 弟 的 血 有 声 音 从 地 里 向 我 哀 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('91', '1', '4', '11', '地 开 了 口 ， 从 你 手 里 接 受 你 兄 弟 的 血 。 现 在 你 必 从 这 地 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('92', '1', '4', '12', '你 种 地 ， 地 不 再 给 你 效 力 ； 你 必 流 离 飘 荡 在 地 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('93', '1', '4', '13', '该 隐 对 耶 和 华 说 ： “ 我 的 刑 罚 太 重 ， 过 于 我 所 能 当 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('94', '1', '4', '14', '你 如 今 赶 逐 我 离 开 这 地 ， 以 致 不 见 你 面 ； 我 必 流 离 飘 荡 在 地 上 ， 凡 遇 见 我 的 必 杀 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('95', '1', '4', '15', '耶 和 华 对 他 说 ： “ 凡 杀 该 隐 的 ， 必 遭 报 七 倍 。 ” 耶 和 华 就 给 该 隐 立 一 个 记 号 ， 免 得 人 遇 见 他 就 杀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('96', '1', '4', '16', '于 是 该 隐 离 开 耶 和 华 的 面 ， 去 住 在 伊 甸 东 边 挪 得 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('97', '1', '4', '17', '＜ 该 隐 的 后 代 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('98', '1', '4', '18', '以 诺 生 以 拿 ； 以 拿 生 米 户 雅 利 ； 米 户 雅 利 生 玛 土 撒 利 ； 玛 土 撒 利 生 拉 麦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('99', '1', '4', '19', '拉 麦 娶 了 两 个 妻 ： 一 个 名 叫 亚 大 ， 一 个 名 叫 洗 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('100', '1', '4', '20', '亚 大 生 雅 八 ； 雅 八 就 是 住 帐 棚 、 牧 养 牲 畜 之 人 的 祖 师 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('101', '1', '4', '21', '雅 八 的 兄 弟 名 叫 犹 八 ； 他 是 一 切 弹 琴 吹 箫 之 人 的 祖 师 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('102', '1', '4', '22', '洗 拉 又 生 了 土 八 ． 该 隐 ； 他 是 打 造 各 样 铜 铁 利 器 的 ｛ 或 译 ： 是 铜 匠 铁 匠 的 祖 师 ｝ 。 土 八 ． 该 隐 的 妹 子 是 拿 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('103', '1', '4', '23', '拉 麦 对 他 两 个 妻 子 说 ： 亚 大 、 洗 拉 ， 听 我 的 声 音 ； 拉 麦 的 妻 子 ， 细 听 我 的 话 语 ： 壮 年 人 伤 我 ， 我 把 他 杀 了 ； 少 年 人 损 我 ， 我 把 他 害 了 ｛ 或 译 ： 我 杀 壮 士 却 伤 自 己 ， 我 害 幼 童 却 损 本 身 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('104', '1', '4', '24', '若 杀 该 隐 ， 遭 报 七 倍 ， 杀 拉 麦 ， 必 遭 报 七 十 七 倍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('105', '1', '4', '25', '＜ 塞 特 和 以 挪 士 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('106', '1', '4', '26', '塞 特 也 生 了 一 个 儿 子 ， 起 名 叫 以 挪 士 。 那 时 候 ， 人 才 求 告 耶 和 华 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('107', '1', '5', '1', '＜ 亚 当 的 后 代 （ 代 上   1 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('108', '1', '5', '2', '并 且 造 男 造 女 。 在 他 们 被 造 的 日 子 ， 神 赐 福 给 他 们 ， 称 他 们 为 “ 人 ” 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('109', '1', '5', '3', '亚 当 活 到 一 百 三 十 岁 ， 生 了 一 个 儿 子 ， 形 像 样 式 和 自 己 相 似 ， 就 给 他 起 名 叫 塞 特 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('110', '1', '5', '4', '亚 当 生 塞 特 之 后 ， 又 在 世 八 百 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('111', '1', '5', '5', '亚 当 共 活 了 九 百 三 十 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('112', '1', '5', '6', '塞 特 活 到 一 百 零 五 岁 ， 生 了 以 挪 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('113', '1', '5', '7', '塞 特 生 以 挪 士 之 后 ， 又 活 了 八 百 零 七 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('114', '1', '5', '8', '塞 特 共 活 了 九 百 一 十 二 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('115', '1', '5', '9', '以 挪 士 活 到 九 十 岁 ， 生 了 该 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('116', '1', '5', '10', '以 挪 士 生 该 南 之 后 ， 又 活 了 八 百 一 十 五 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('117', '1', '5', '11', '以 挪 士 共 活 了 九 百 零 五 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('118', '1', '5', '12', '该 南 活 到 七 十 岁 ， 生 了 玛 勒 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('119', '1', '5', '13', '该 南 生 玛 勒 列 之 后 ， 又 活 了 八 百 四 十 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('120', '1', '5', '14', '该 南 共 活 了 九 百 一 十 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('121', '1', '5', '15', '玛 勒 列 活 到 六 十 五 岁 ， 生 了 雅 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('122', '1', '5', '16', '玛 勒 列 生 雅 列 之 后 ， 又 活 了 八 百 三 十 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('123', '1', '5', '17', '玛 勒 列 共 活 了 八 百 九 十 五 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('124', '1', '5', '18', '雅 列 活 到 一 百 六 十 二 岁 ， 生 了 以 诺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('125', '1', '5', '19', '雅 列 生 以 诺 之 后 ， 又 活 了 八 百 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('126', '1', '5', '20', '雅 列 共 活 了 九 百 六 十 二 岁 就 死 了 . 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('127', '1', '5', '21', '以 诺 活 到 六 十 五 岁 ， 生 了 玛 土 撒 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('128', '1', '5', '22', '以 诺 生 玛 土 撒 拉 之 后 ， 与 神 同 行 三 百 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('129', '1', '5', '23', '以 诺 共 活 了 三 百 六 十 五 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('130', '1', '5', '24', '以 诺 与 神 同 行 ， 神 将 他 取 去 ， 他 就 不 在 世 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('131', '1', '5', '25', '玛 土 撒 拉 活 到 一 百 八 十 七 岁 ， 生 了 拉 麦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('132', '1', '5', '26', '玛 土 撒 拉 生 拉 麦 之 后 ， 又 活 了 七 百 八 十 二 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('133', '1', '5', '27', '玛 土 撒 拉 共 活 了 九 百 六 十 九 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('134', '1', '5', '28', '拉 麦 活 到 一 百 八 十 二 岁 ， 生 了 一 个 儿 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('135', '1', '5', '29', '给 他 起 名 叫 挪 亚 ， 说 ： “ 这 个 儿 子 必 为 我 们 的 操 作 和 手 中 的 劳 苦 安 慰 我 们 ； 这 操 作 劳 苦 是 因 为 耶 和 华 咒 诅 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('136', '1', '5', '30', '拉 麦 生 挪 亚 之 后 ， 又 活 了 五 百 九 十 五 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('137', '1', '5', '31', '拉 麦 共 活 了 七 百 七 十 七 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('138', '1', '5', '32', '挪 亚 五 百 岁 生 了 闪 、 含 、 雅 弗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('139', '1', '6', '1', '＜ 人 类 的 邪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('140', '1', '6', '2', '神 的 儿 子 们 看 见 人 的 女 子 美 貌 ， 就 随 意 挑 选 ， 娶 来 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('141', '1', '6', '3', '耶 和 华 说 ： “ 人 既 属 乎 血 气 ， 我 的 灵 就 不 永 远 住 在 他 里 面 ； 然 而 他 的 日 子 还 可 到 一 百 二 十 年 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('142', '1', '6', '4', '那 时 候 有 伟 人 在 地 上 ， 后 来 神 的 儿 子 们 和 人 的 女 子 们 交 合 生 子 ； 那 就 是 上 古 英 武 有 名 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('143', '1', '6', '5', '耶 和 华 见 人 在 地 上 罪 恶 很 大 ， 终 日 所 思 想 的 尽 都 是 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('144', '1', '6', '6', '耶 和 华 就 后 悔 造 人 在 地 上 ， 心 中 忧 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('145', '1', '6', '7', '耶 和 华 说 ： “ 我 要 将 所 造 的 人 和 走 兽 ， 并 昆 虫 ， 以 及 空 中 的 飞 鸟 ， 都 从 地 上 除 灭 ， 因 为 我 造 他 们 后 悔 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('146', '1', '6', '8', '惟 有 挪 亚 在 耶 和 华 眼 前 蒙 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('147', '1', '6', '9', '＜ 挪 亚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('148', '1', '6', '10', '挪 亚 生 了 三 个 儿 子 ， 就 是 闪 、 含 、 雅 弗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('149', '1', '6', '11', '世 界 在 神 面 前 败 坏 ， 地 上 满 了 强 暴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('150', '1', '6', '12', '神 观 看 世 界 ， 见 是 败 坏 了 ； 凡 有 血 气 的 人 在 地 上 都 败 坏 了 行 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('151', '1', '6', '13', '神 就 对 挪 亚 说 ： “ 凡 有 血 气 的 人 ， 他 的 尽 头 已 经 来 到 我 面 前 ； 因 为 地 上 满 了 他 们 的 强 暴 ， 我 要 把 他 们 和 地 一 并 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('152', '1', '6', '14', '你 要 用 歌 斐 木 造 一 只 方 舟 ， 分 一 间 一 间 地 造 ， 里 外 抹 上 松 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('153', '1', '6', '15', '方 舟 的 造 法 乃 是 这 样 ： 要 长 三 百 肘 ， 宽 五 十 肘 ， 高 三 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('154', '1', '6', '16', '方 舟 上 边 要 留 透 光 处 ， 高 一 肘 。 方 舟 的 门 要 开 在 旁 边 。 方 舟 要 分 上 、 中 、 下 三 层 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('155', '1', '6', '17', '看 哪 ， 我 要 使 洪 水 泛 滥 在 地 上 ， 毁 灭 天 下 ； 凡 地 上 有 血 肉 、 有 气 息 的 活 物 ， 无 一 不 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('156', '1', '6', '18', '我 却 要 与 你 立 约 ； 你 同 你 的 妻 ， 与 儿 子 儿 妇 ， 都 要 进 入 方 舟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('157', '1', '6', '19', '凡 有 血 肉 的 活 物 ， 每 样 两 个 ， 一 公 一 母 ， 你 要 带 进 方 舟 ， 好 在 你 那 里 保 全 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('158', '1', '6', '20', '飞 鸟 各 从 其 类 ， 牲 畜 各 从 其 类 ， 地 上 的 昆 虫 各 从 其 类 ， 每 样 两 个 ， 要 到 你 那 里 ， 好 保 全 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('159', '1', '6', '21', '你 要 拿 各 样 食 物 积 蓄 起 来 ， 好 作 你 和 它 们 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('160', '1', '6', '22', '挪 亚 就 这 样 行 。 凡 神 所 吩 咐 的 ， 他 都 照 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('161', '1', '7', '1', '＜ 洪 水 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('162', '1', '7', '2', '凡 洁 净 的 畜 类 ， 你 要 带 七 公 七 母 ； 不 洁 净 的 畜 类 ， 你 要 带 一 公 一 母 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('163', '1', '7', '3', '空 中 的 飞 鸟 也 要 带 七 公 七 母 ， 可 以 留 种 ， 活 在 全 地 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('164', '1', '7', '4', '因 为 再 过 七 天 ， 我 要 降 雨 在 地 上 四 十 昼 夜 ， 把 我 所 造 的 各 种 活 物 都 从 地 上 除 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('165', '1', '7', '5', '挪 亚 就 遵 着 耶 和 华 所 吩 咐 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('166', '1', '7', '6', '当 洪 水 泛 滥 在 地 上 的 时 候 ， 挪 亚 整 六 百 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('167', '1', '7', '7', '挪 亚 就 同 他 的 妻 和 儿 子 儿 妇 都 进 入 方 舟 ， 躲 避 洪 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('168', '1', '7', '8', '洁 净 的 畜 类 和 不 洁 净 的 畜 类 ， 飞 鸟 并 地 上 一 切 的 昆 虫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('169', '1', '7', '9', '都 是 一 对 一 对 地 ， 有 公 有 母 ， 到 挪 亚 那 里 进 入 方 舟 ， 正 如 神 所 吩 咐 挪 亚 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('170', '1', '7', '10', '过 了 那 七 天 ， 洪 水 泛 滥 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('171', '1', '7', '11', '当 挪 亚 六 百 岁 ， 二 月 十 七 日 那 一 天 ， 大 渊 的 泉 源 都 裂 开 了 ， 天 上 的 窗 户 也 敞 开 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('172', '1', '7', '12', '四 十 昼 夜 降 大 雨 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('173', '1', '7', '13', '正 当 那 日 ， 挪 亚 和 他 三 个 儿 子 闪 、 含 、 雅 弗 ， 并 挪 亚 的 妻 子 和 三 个 儿 妇 ， 都 进 入 方 舟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('174', '1', '7', '14', '他 们 和 百 兽 ， 各 从 其 类 ， 一 切 牲 畜 ， 各 从 其 类 ， 爬 在 地 上 的 昆 虫 ， 各 从 其 类 ， 一 切 禽 鸟 ， 各 从 其 类 ， 都 进 入 方 舟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('175', '1', '7', '15', '凡 有 血 肉 、 有 气 息 的 活 物 ， 都 一 对 一 对 地 到 挪 亚 那 里 ， 进 入 方 舟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('176', '1', '7', '16', '凡 有 血 肉 进 入 方 舟 的 ， 都 是 有 公 有 母 ， 正 如 神 所 吩 咐 挪 亚 的 。 耶 和 华 就 把 他 关 在 方 舟 里 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('177', '1', '7', '17', '洪 水 泛 滥 在 地 上 四 十 天 ， 水 往 上 长 ， 把 方 舟 从 地 上 漂 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('178', '1', '7', '18', '水 势 浩 大 ， 在 地 上 大 大 地 往 上 长 ， 方 舟 在 水 面 上 漂 来 漂 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('179', '1', '7', '19', '水 势 在 地 上 极 其 浩 大 ， 天 下 的 高 山 都 淹 没 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('180', '1', '7', '20', '水 势 比 山 高 过 十 五 肘 ， 山 岭 都 淹 没 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('181', '1', '7', '21', '凡 在 地 上 有 血 肉 的 动 物 ， 就 是 飞 鸟 、 牲 畜 、 走 兽 ， 和 爬 在 地 上 的 昆 虫 ， 以 及 所 有 的 人 ， 都 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('182', '1', '7', '22', '凡 在 旱 地 上 、 鼻 孔 有 气 息 的 生 灵 都 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('183', '1', '7', '23', '凡 地 上 各 类 的 活 物 ， 连 人 带 牲 畜 、 昆 虫 ， 以 及 空 中 的 飞 鸟 ， 都 从 地 上 除 灭 了 ， 只 留 下 挪 亚 和 那 些 与 他 同 在 方 舟 里 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('184', '1', '7', '24', '水 势 浩 大 ， 在 地 上 共 一 百 五 十 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('185', '1', '8', '1', '＜ 洪 水 消 退 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('186', '1', '8', '2', '渊 源 和 天 上 的 窗 户 都 闭 塞 了 ， 天 上 的 大 雨 也 止 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('187', '1', '8', '3', '水 从 地 上 渐 退 。 过 了 一 百 五 十 天 ， 水 就 渐 消 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('188', '1', '8', '4', '七 月 十 七 日 ， 方 舟 停 在 亚 拉 腊 山 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('189', '1', '8', '5', '水 又 渐 消 ， 到 十 月 初 一 日 ， 山 顶 都 现 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('190', '1', '8', '6', '过 了 四 十 天 ， 挪 亚 开 了 方 舟 的 窗 户 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('191', '1', '8', '7', '放 出 一 只 乌 鸦 去 ； 那 乌 鸦 飞 来 飞 去 ， 直 到 地 上 的 水 都 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('192', '1', '8', '8', '他 又 放 出 一 只 鸽 子 去 ， 要 看 看 水 从 地 上 退 了 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('193', '1', '8', '9', '但 遍 地 上 都 是 水 ， 鸽 子 找 不 着 落 脚 之 地 ， 就 回 到 方 舟 挪 亚 那 里 ， 挪 亚 伸 手 把 鸽 子 接 进 方 舟 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('194', '1', '8', '10', '他 又 等 了 七 天 ， 再 把 鸽 子 从 方 舟 放 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('195', '1', '8', '11', '到 了 晚 上 ， 鸽 子 回 到 他 那 里 ， 嘴 里 叼 着 一 个 新 拧 下 来 的 橄 榄 叶 子 ， 挪 亚 就 知 道 地 上 的 水 退 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('196', '1', '8', '12', '他 又 等 了 七 天 ， 放 出 鸽 子 去 ， 鸽 子 就 不 再 回 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('197', '1', '8', '13', '到 挪 亚 六 百 零 一 岁 ， 正 月 初 一 日 ， 地 上 的 水 都 干 了 。 挪 亚 撤 去 方 舟 的 盖 观 看 ， 便 见 地 面 上 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('198', '1', '8', '14', '到 了 二 月 二 十 七 日 ， 地 就 都 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('199', '1', '8', '15', '神 对 挪 亚 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('200', '1', '8', '16', '“ 你 和 你 的 妻 子 、 儿 子 、 儿 妇 都 可 以 出 方 舟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('201', '1', '8', '17', '在 你 那 里 凡 有 血 肉 的 活 物 ， 就 是 飞 鸟 、 牲 畜 ， 和 一 切 爬 在 地 上 的 昆 虫 ， 都 要 带 出 来 ， 叫 它 在 地 上 多 多 滋 生 ， 大 大 兴 旺 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('202', '1', '8', '18', '于 是 挪 亚 和 他 的 妻 子 、 儿 子 、 儿 妇 都 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('203', '1', '8', '19', '一 切 走 兽 、 昆 虫 、 飞 鸟 ， 和 地 上 所 有 的 动 物 ， 各 从 其 类 ， 也 都 出 了 方 舟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('204', '1', '8', '20', '＜ 挪 亚 献 祭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('205', '1', '8', '21', '耶 和 华 闻 那 馨 香 之 气 ， 就 心 里 说 ： “ 我 不 再 因 人 的 缘 故 咒 诅 地 （ 人 从 小 时 心 里 怀 着 恶 念 ） ， 也 不 再 按 着 我 才 行 的 灭 各 种 的 活 物 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('206', '1', '8', '22', '地 还 存 留 的 时 候 ， 稼 穑 、 寒 暑 、 冬 夏 、 昼 夜 就 永 不 停 息 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('207', '1', '9', '1', '＜ 神 跟 挪 亚 立 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('208', '1', '9', '2', '凡 地 上 的 走 兽 和 空 中 的 飞 鸟 都 必 惊 恐 ， 惧 怕 你 们 ， 连 地 上 一 切 的 昆 虫 并 海 里 一 切 的 鱼 都 交 付 你 们 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('209', '1', '9', '3', '凡 活 着 的 动 物 都 可 以 作 你 们 的 食 物 。 这 一 切 我 都 赐 给 你 们 ， 如 同 菜 蔬 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('210', '1', '9', '4', '惟 独 肉 带 着 血 ， 那 就 是 它 的 生 命 ， 你 们 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('211', '1', '9', '5', '流 你 们 血 、 害 你 们 命 的 ， 无 论 是 兽 是 人 ， 我 必 讨 他 的 罪 ， 就 是 向 各 人 的 弟 兄 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('212', '1', '9', '6', '凡 流 人 血 的 ， 他 的 血 也 必 被 人 所 流 ， 因 为 神 造 人 是 照 自 己 的 形 像 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('213', '1', '9', '7', '你 们 要 生 养 众 多 ， 在 地 上 昌 盛 繁 茂 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('214', '1', '9', '8', '神 晓 谕 挪 亚 和 他 的 儿 子 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('215', '1', '9', '9', '“ 我 与 你 们 和 你 们 的 后 裔 立 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('216', '1', '9', '10', '并 与 你 们 这 里 的 一 切 活 物 ─ ─ 就 是 飞 鸟 、 牲 畜 、 走 兽 ， 凡 从 方 舟 里 出 来 的 活 物 ─ ─ 立 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('217', '1', '9', '11', '我 与 你 们 立 约 ， 凡 有 血 肉 的 ， 不 再 被 洪 水 灭 绝 ， 也 不 再 有 洪 水 毁 坏 地 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('218', '1', '9', '12', '神 说 ： “ 我 与 你 们 并 你 们 这 里 的 各 样 活 物 所 立 的 永 约 是 有 记 号 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('219', '1', '9', '13', '我 把 虹 放 在 云 彩 中 ， 这 就 可 作 我 与 地 立 约 的 记 号 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('220', '1', '9', '14', '我 使 云 彩 盖 地 的 时 候 ， 必 有 虹 现 在 云 彩 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('221', '1', '9', '15', '我 便 记 念 我 与 你 们 和 各 样 有 血 肉 的 活 物 所 立 的 约 ， 水 就 再 不 泛 滥 、 毁 坏 一 切 有 血 肉 的 物 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('222', '1', '9', '16', '虹 必 现 在 云 彩 中 ， 我 看 见 ， 就 要 记 念 我 与 地 上 各 样 有 血 肉 的 活 物 所 立 的 永 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('223', '1', '9', '17', '神 对 挪 亚 说 ： “ 这 就 是 我 与 地 上 一 切 有 血 肉 之 物 立 约 的 记 号 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('224', '1', '9', '18', '＜ 挪 亚 和 他 的 儿 子 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('225', '1', '9', '19', '这 是 挪 亚 的 三 个 儿 子 ， 他 们 的 后 裔 分 散 在 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('226', '1', '9', '20', '挪 亚 作 起 农 夫 来 ， 栽 了 一 个 葡 萄 园 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('227', '1', '9', '21', '他 喝 了 园 中 的 酒 便 醉 了 ， 在 帐 棚 里 赤 着 身 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('228', '1', '9', '22', '迦 南 的 父 亲 含 看 见 他 父 亲 赤 身 ， 就 到 外 边 告 诉 他 两 个 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('229', '1', '9', '23', '于 是 闪 和 雅 弗 拿 件 衣 服 搭 在 肩 上 ， 倒 退 着 进 去 ， 给 他 父 亲 盖 上 ； 他 们 背 着 脸 就 看 不 见 父 亲 的 赤 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('230', '1', '9', '24', '挪 亚 醒 了 酒 ， 知 道 小 儿 子 向 他 所 做 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('231', '1', '9', '25', '就 说 ： 迦 南 当 受 咒 诅 ， 必 给 他 弟 兄 作 奴 仆 的 奴 仆 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('232', '1', '9', '26', '又 说 ： 耶 和 华 ─ ─ 闪 的 神 是 应 当 称 颂 的 ！ 愿 迦 南 作 闪 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('233', '1', '9', '27', '愿 神 使 雅 弗 扩 张 ， 使 他 住 在 闪 的 帐 棚 里 ； 又 愿 迦 南 作 他 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('234', '1', '9', '28', '洪 水 以 后 ， 挪 亚 又 活 了 三 百 五 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('235', '1', '9', '29', '挪 亚 共 活 了 九 百 五 十 岁 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('236', '1', '10', '1', '＜ 闪 、 含 、 雅 弗 的 后 代 （ 代 上   1 : 5 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('237', '1', '10', '2', '雅 弗 的 儿 子 是 歌 篾 、 玛 各 、 玛 代 、 雅 完 、 土 巴 、 米 设 、 提 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('238', '1', '10', '3', '歌 篾 的 儿 子 是 亚 实 基 拿 、 利 法 、 陀 迦 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('239', '1', '10', '4', '雅 完 的 儿 子 是 以 利 沙 、 他 施 、 基 提 、 多 单 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('240', '1', '10', '5', '这 些 人 的 后 裔 将 各 国 的 地 土 、 海 岛 分 开 居 住 ， 各 随 各 的 方 言 、 宗 族 立 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('241', '1', '10', '6', '含 的 儿 子 是 古 实 、 麦 西 、 弗 、 迦 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('242', '1', '10', '7', '古 实 的 儿 子 是 西 巴 、 哈 腓 拉 、 撒 弗 他 、 拉 玛 、 撒 弗 提 迦 。 拉 玛 的 儿 子 是 示 巴 、 底 但 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('243', '1', '10', '8', '古 实 又 生 宁 录 ， 他 为 世 上 英 雄 之 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('244', '1', '10', '9', '他 在 耶 和 华 面 前 是 个 英 勇 的 猎 户 ， 所 以 俗 语 说 ： “ 像 宁 录 在 耶 和 华 面 前 是 个 英 勇 的 猎 户 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('245', '1', '10', '10', '他 国 的 起 头 是 巴 别 、 以 力 、 亚 甲 、 甲 尼 ， 都 在 示 拿 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('246', '1', '10', '11', '他 从 那 地 出 来 往 亚 述 去 ， 建 造 尼 尼 微 、 利 河 伯 、 迦 拉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('247', '1', '10', '12', '和 尼 尼 微 、 迦 拉 中 间 的 利 鲜 ， 这 就 是 那 大 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('248', '1', '10', '13', '麦 西 生 路 低 人 、 亚 拿 米 人 、 利 哈 比 人 、 拿 弗 土 希 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('249', '1', '10', '14', '帕 斯 鲁 细 人 、 迦 斯 路 希 人 、 迦 斐 托 人 ； 从 迦 斐 托 出 来 的 有 非 利 士 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('250', '1', '10', '15', '迦 南 生 长 子 西 顿 ， 又 生 赫');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('251', '1', '10', '16', '和 耶 布 斯 人 、 亚 摩 利 人 、 革 迦 撒 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('252', '1', '10', '17', '希 未 人 、 亚 基 人 、 西 尼 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('253', '1', '10', '18', '亚 瓦 底 人 、 洗 玛 利 人 、 哈 马 人 ， 后 来 迦 南 的 诸 族 分 散 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('254', '1', '10', '19', '迦 南 的 境 界 是 从 西 顿 向 基 拉 耳 的 路 上 ， 直 到 迦 萨 ， 又 向 所 多 玛 、 蛾 摩 拉 、 押 玛 、 洗 扁 的 路 上 ， 直 到 拉 沙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('255', '1', '10', '20', '这 就 是 含 的 后 裔 ， 各 随 他 们 的 宗 族 、 方 言 ， 所 住 的 地 土 、 邦 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('256', '1', '10', '21', '雅 弗 的 哥 哥 闪 ， 是 希 伯 子 孙 之 祖 ， 他 也 生 了 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('257', '1', '10', '22', '闪 的 儿 子 是 以 拦 、 亚 述 、 亚 法 撒 、 路 德 、 亚 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('258', '1', '10', '23', '亚 兰 的 儿 子 是 乌 斯 、 户 勒 、 基 帖 、 玛 施 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('259', '1', '10', '24', '亚 法 撒 生 沙 拉 ； 沙 拉 生 希 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('260', '1', '10', '25', '希 伯 生 了 两 个 儿 子 ， 一 个 名 叫 法 勒 ｛ 就 是 分 的 意 思 ｝ ， 因 为 那 时 人 就 分 地 居 住 ； 法 勒 的 兄 弟 名 叫 约 坍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('261', '1', '10', '26', '约 坍 生 亚 摩 答 、 沙 列 、 哈 萨 玛 非 、 耶 拉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('262', '1', '10', '27', '哈 多 兰 、 乌 萨 、 德 拉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('263', '1', '10', '28', '俄 巴 路 、 亚 比 玛 利 、 示 巴 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('264', '1', '10', '29', '阿 斐 、 哈 腓 拉 、 约 巴 ， 这 都 是 约 坍 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('265', '1', '10', '30', '他 们 所 住 的 地 方 是 从 米 沙 直 到 西 发 东 边 的 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('266', '1', '10', '31', '这 就 是 闪 的 子 孙 ， 各 随 他 们 的 宗 族 、 方 言 ， 所 住 的 地 土 、 邦 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('267', '1', '10', '32', '这 些 都 是 挪 亚 三 个 儿 子 的 宗 族 ， 各 随 他 们 的 支 派 立 国 。 洪 水 以 后 ， 他 们 在 地 上 分 为 邦 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('268', '1', '11', '1', '＜ 巴 别 塔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('269', '1', '11', '2', '他 们 往 东 边 迁 移 的 时 候 ， 在 示 拿 地 遇 见 一 片 平 原 ， 就 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('270', '1', '11', '3', '他 们 彼 此 商 量 说 ： “ 来 吧 ！ 我 们 要 做 砖 ， 把 砖 烧 透 了 。 ” 他 们 就 拿 砖 当 石 头 ， 又 拿 石 漆 当 灰 泥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('271', '1', '11', '4', '他 们 说 ： “ 来 吧 ！ 我 们 要 建 造 一 座 城 和 一 座 塔 ， 塔 顶 通 天 ， 为 要 传 扬 我 们 的 名 ， 免 得 我 们 分 散 在 全 地 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('272', '1', '11', '5', '耶 和 华 降 临 ， 要 看 看 世 人 所 建 造 的 城 和 塔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('273', '1', '11', '6', '耶 和 华 说 ： “ 看 哪 ， 他 们 成 为 一 样 的 人 民 ， 都 是 一 样 的 言 语 ， 如 今 既 做 起 这 事 来 ， 以 后 他 们 所 要 做 的 事 就 没 有 不 成 就 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('274', '1', '11', '7', '我 们 下 去 ， 在 那 里 变 乱 他 们 的 口 音 ， 使 他 们 的 言 语 彼 此 不 通 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('275', '1', '11', '8', '于 是 耶 和 华 使 他 们 从 那 里 分 散 在 全 地 上 ； 他 们 就 停 工 ， 不 造 那 城 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('276', '1', '11', '9', '因 为 耶 和 华 在 那 里 变 乱 天 下 人 的 言 语 ， 使 众 人 分 散 在 全 地 上 ， 所 以 那 城 名 叫 巴 别 ｛ 就 是 变 乱 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('277', '1', '11', '10', '＜ 闪 的 后 代 （ 代 上   1 : 2 4 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('278', '1', '11', '11', '闪 生 亚 法 撒 之 后 又 活 了 五 百 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('279', '1', '11', '12', '亚 法 撒 活 到 三 十 五 岁 ， 生 了 沙 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('280', '1', '11', '13', '亚 法 撒 生 沙 拉 之 后 又 活 了 四 百 零 三 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('281', '1', '11', '14', '沙 拉 活 到 三 十 岁 ， 生 了 希 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('282', '1', '11', '15', '沙 拉 生 希 伯 之 后 又 活 了 四 百 零 三 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('283', '1', '11', '16', '希 伯 活 到 三 十 四 岁 ， 生 了 法 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('284', '1', '11', '17', '希 伯 生 法 勒 之 后 又 活 了 四 百 三 十 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('285', '1', '11', '18', '法 勒 活 到 三 十 岁 ， 生 了 拉 吴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('286', '1', '11', '19', '法 勒 生 拉 吴 之 后 又 活 了 二 百 零 九 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('287', '1', '11', '20', '拉 吴 活 到 三 十 二 岁 ， 生 了 西 鹿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('288', '1', '11', '21', '拉 吴 生 西 鹿 之 后 又 活 了 二 百 零 七 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('289', '1', '11', '22', '西 鹿 活 到 三 十 岁 ， 生 了 拿 鹤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('290', '1', '11', '23', '西 鹿 生 拿 鹤 之 后 又 活 了 二 百 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('291', '1', '11', '24', '拿 鹤 活 到 二 十 九 岁 ， 生 了 他 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('292', '1', '11', '25', '拿 鹤 生 他 拉 之 后 又 活 了 一 百 一 十 九 年 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('293', '1', '11', '26', '他 拉 活 到 七 十 岁 ， 生 了 亚 伯 兰 、 拿 鹤 、 哈 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('294', '1', '11', '27', '＜ 他 拉 的 后 代 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('295', '1', '11', '28', '哈 兰 死 在 他 的 本 地 迦 勒 底 的 吾 珥 ， 在 他 父 亲 他 拉 之 先 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('296', '1', '11', '29', '亚 伯 兰 、 拿 鹤 各 娶 了 妻 ： 亚 伯 兰 的 妻 子 名 叫 撒 莱 ； 拿 鹤 的 妻 子 名 叫 密 迦 ， 是 哈 兰 的 女 儿 ； 哈 兰 是 密 迦 和 亦 迦 的 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('297', '1', '11', '30', '撒 莱 不 生 育 ， 没 有 孩 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('298', '1', '11', '31', '他 拉 带 着 他 儿 子 亚 伯 兰 和 他 孙 子 哈 兰 的 儿 子 罗 得 ， 并 他 儿 妇 亚 伯 兰 的 妻 子 撒 莱 ， 出 了 迦 勒 底 的 吾 珥 ， 要 往 迦 南 地 去 ； 他 们 走 到 哈 兰 ， 就 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('299', '1', '11', '32', '他 拉 共 活 了 二 百 零 五 岁 ， 就 死 在 哈 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('300', '1', '12', '1', '＜ 神 呼 召 亚 伯 兰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('301', '1', '12', '2', '我 必 叫 你 成 为 大 国 。 我 必 赐 福 给 你 ， 叫 你 的 名 为 大 ； 你 也 要 叫 别 人 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('302', '1', '12', '3', '为 你 祝 福 的 ， 我 必 赐 福 与 他 ； 那 咒 诅 你 的 ， 我 必 咒 诅 他 。 地 上 的 万 族 都 要 因 你 得 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('303', '1', '12', '4', '亚 伯 兰 就 照 着 耶 和 华 的 吩 咐 去 了 ； 罗 得 也 和 他 同 去 。 亚 伯 兰 出 哈 兰 的 时 候 年 七 十 五 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('304', '1', '12', '5', '亚 伯 兰 将 他 妻 子 撒 莱 和 侄 儿 罗 得 ， 连 他 们 在 哈 兰 所 积 蓄 的 财 物 、 所 得 的 人 口 ， 都 带 往 迦 南 地 去 。 他 们 就 到 了 迦 南 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('305', '1', '12', '6', '亚 伯 兰 经 过 那 地 ， 到 了 示 剑 地 方 、 摩 利 橡 树 那 里 。 那 时 迦 南 人 住 在 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('306', '1', '12', '7', '耶 和 华 向 亚 伯 兰 显 现 ， 说 ： “ 我 要 把 这 地 赐 给 你 的 后 裔 。 ” 亚 伯 兰 就 在 那 里 为 向 他 显 现 的 耶 和 华 筑 了 一 座 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('307', '1', '12', '8', '从 那 里 他 又 迁 到 伯 特 利 东 边 的 山 ， 支 搭 帐 棚 ； 西 边 是 伯 特 利 ， 东 边 是 艾 。 他 在 那 里 又 为 耶 和 华 筑 了 一 座 坛 ， 求 告 耶 和 华 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('308', '1', '12', '9', '后 来 亚 伯 兰 又 渐 渐 迁 往 南 地 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('309', '1', '12', '10', '＜ 亚 伯 兰 到 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('310', '1', '12', '11', '将 近 埃 及 ， 就 对 他 妻 子 撒 莱 说 ： “ 我 知 道 你 是 容 貌 俊 美 的 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('311', '1', '12', '12', '埃 及 人 看 见 你 必 说 ： ‘ 这 是 他 的 妻 子 ’ ， 他 们 就 要 杀 我 ， 却 叫 你 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('312', '1', '12', '13', '求 你 说 ， 你 是 我 的 妹 子 ， 使 我 因 你 得 平 安 ， 我 的 命 也 因 你 存 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('313', '1', '12', '14', '及 至 亚 伯 兰 到 了 埃 及 ， 埃 及 人 看 见 那 妇 人 极 其 美 貌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('314', '1', '12', '15', '法 老 的 臣 宰 看 见 了 她 ， 就 在 法 老 面 前 夸 奖 她 。 那 妇 人 就 被 带 进 法 老 的 宫 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('315', '1', '12', '16', '法 老 因 这 妇 人 就 厚 待 亚 伯 兰 ， 亚 伯 兰 得 了 许 多 牛 、 羊 、 骆 驼 、 公 驴 、 母 驴 、 仆 婢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('316', '1', '12', '17', '耶 和 华 因 亚 伯 兰 妻 子 撒 莱 的 缘 故 ， 降 大 灾 与 法 老 和 他 的 全 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('317', '1', '12', '18', '法 老 就 召 了 亚 伯 兰 来 ， 说 ： “ 你 这 向 我 做 的 是 什 么 事 呢 ？ 为 什 么 没 有 告 诉 我 她 是 你 的 妻 子 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('318', '1', '12', '19', '为 什 么 说 她 是 你 的 妹 子 ， 以 致 我 把 她 取 来 要 作 我 的 妻 子 ？ 现 在 你 的 妻 子 在 这 里 ， 可 以 带 她 走 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('319', '1', '12', '20', '于 是 法 老 吩 咐 人 将 亚 伯 兰 和 他 妻 子 ， 并 他 所 有 的 都 送 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('320', '1', '13', '1', '＜ 亚 伯 兰 跟 罗 得 分 手 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('321', '1', '13', '2', '亚 伯 兰 的 金 、 银 、 牲 畜 极 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('322', '1', '13', '3', '他 从 南 地 渐 渐 往 伯 特 利 去 ， 到 了 伯 特 利 和 艾 的 中 间 ， 就 是 从 前 支 搭 帐 棚 的 地 方 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('323', '1', '13', '4', '也 是 他 起 先 筑 坛 的 地 方 ； 他 又 在 那 里 求 告 耶 和 华 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('324', '1', '13', '5', '与 亚 伯 兰 同 行 的 罗 得 也 有 牛 群 、 羊 群 、 帐 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('325', '1', '13', '6', '那 地 容 不 下 他 们 ； 因 为 他 们 的 财 物 甚 多 ， 使 他 们 不 能 同 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('326', '1', '13', '7', '当 时 ， 迦 南 人 与 比 利 洗 人 在 那 地 居 住 。 亚 伯 兰 的 牧 人 和 罗 得 的 牧 人 相 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('327', '1', '13', '8', '亚 伯 兰 就 对 罗 得 说 ： “ 你 我 不 可 相 争 ， 你 的 牧 人 和 我 的 牧 人 也 不 可 相 争 ， 因 为 我 们 是 骨 肉 ｛ 原 文 是 弟 兄 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('328', '1', '13', '9', '遍 地 不 都 在 你 眼 前 吗 ？ 请 你 离 开 我 ： 你 向 左 ， 我 就 向 右 ； 你 向 右 ， 我 就 向 左 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('329', '1', '13', '10', '罗 得 举 目 看 见 约 旦 河 的 全 平 原 ， 直 到 琐 珥 ， 都 是 滋 润 的 ， 那 地 在 耶 和 华 未 灭 所 多 玛 、 蛾 摩 拉 以 先 如 同 耶 和 华 的 园 子 ， 也 像 埃 及 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('330', '1', '13', '11', '于 是 罗 得 选 择 约 旦 河 的 全 平 原 ， 往 东 迁 移 ； 他 们 就 彼 此 分 离 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('331', '1', '13', '12', '亚 伯 兰 住 在 迦 南 地 ， 罗 得 住 在 平 原 的 城 邑 ， 渐 渐 挪 移 帐 棚 ， 直 到 所 多 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('332', '1', '13', '13', '所 多 玛 人 在 耶 和 华 面 前 罪 大 恶 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('333', '1', '13', '14', '＜ 亚 伯 兰 迁 往 希 伯 仑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('334', '1', '13', '15', '凡 你 所 看 见 的 一 切 地 ， 我 都 要 赐 给 你 和 你 的 后 裔 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('335', '1', '13', '16', '我 也 要 使 你 的 后 裔 如 同 地 上 的 尘 沙 那 样 多 ， 人 若 能 数 算 地 上 的 尘 沙 才 能 数 算 你 的 后 裔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('336', '1', '13', '17', '你 起 来 ， 纵 横 走 遍 这 地 ， 因 为 我 必 把 这 地 赐 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('337', '1', '13', '18', '亚 伯 兰 就 搬 了 帐 棚 ， 来 到 希 伯 仑 幔 利 的 橡 树 那 里 居 住 ， 在 那 里 为 耶 和 华 筑 了 一 座 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('338', '1', '14', '1', '＜ 亚 伯 兰 抢 救 罗 得 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('339', '1', '14', '2', '他 们 都 攻 打 所 多 玛 王 比 拉 、 蛾 摩 拉 王 比 沙 、 押 玛 王 示 纳 、 洗 扁 王 善 以 别 ， 和 比 拉 王 ； 比 拉 就 是 琐 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('340', '1', '14', '3', '这 五 王 都 在 西 订 谷 会 合 ； 西 订 谷 就 是 盐 海 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('341', '1', '14', '4', '他 们 已 经 事 奉 基 大 老 玛 十 二 年 ， 到 十 三 年 就 背 叛 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('342', '1', '14', '5', '十 四 年 ， 基 大 老 玛 和 同 盟 的 王 都 来 在 亚 特 律 ． 加 宁 ， 杀 败 了 利 乏 音 人 ， 在 哈 麦 杀 败 了 苏 西 人 ， 在 沙 微 ． 基 列 亭 杀 败 了 以 米 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('343', '1', '14', '6', '在 何 利 人 的 西 珥 山 杀 败 了 何 利 人 ， 一 直 杀 到 靠 近 旷 野 的 伊 勒 ． 巴 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('344', '1', '14', '7', '他 们 回 到 安 ． 密 巴 ， 就 是 加 低 斯 ， 杀 败 了 亚 玛 力 全 地 的 人 ， 以 及 住 在 哈 洗 逊 ． 他 玛 的 亚 摩 利 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('345', '1', '14', '8', '于 是 所 多 玛 王 、 蛾 摩 拉 王 、 押 玛 王 、 洗 扁 王 ， 和 比 拉 王 （ 比 拉 就 是 琐 珥 ） 都 出 来 ， 在 西 订 谷 摆 阵 ， 与 他 们 交 战 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('346', '1', '14', '9', '就 是 与 以 拦 王 基 大 老 玛 、 戈 印 王 提 达 、 示 拿 王 暗 拉 非 、 以 拉 撒 王 亚 略 交 战 ； 乃 是 四 王 与 五 王 交 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('347', '1', '14', '10', '西 订 谷 有 许 多 石 漆 坑 。 所 多 玛 王 和 蛾 摩 拉 王 逃 跑 ， 有 掉 在 坑 里 的 ， 其 余 的 人 都 往 山 上 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('348', '1', '14', '11', '四 王 就 把 所 多 玛 和 蛾 摩 拉 所 有 的 财 物 ， 并 一 切 的 粮 食 都 掳 掠 去 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('349', '1', '14', '12', '又 把 亚 伯 兰 的 侄 儿 罗 得 和 罗 得 的 财 物 掳 掠 去 了 。 当 时 罗 得 正 住 在 所 多 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('350', '1', '14', '13', '有 一 个 逃 出 来 的 人 告 诉 希 伯 来 人 亚 伯 兰 ； 亚 伯 兰 正 住 在 亚 摩 利 人 幔 利 的 橡 树 那 里 。 幔 利 和 以 实 各 并 亚 乃 都 是 弟 兄 ， 曾 与 亚 伯 兰 联 盟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('351', '1', '14', '14', '亚 伯 兰 听 见 他 侄 儿 ｛ 原 文 是 弟 兄 ｝ 被 掳 去 ， 就 率 领 他 家 里 生 养 的 精 练 壮 丁 三 百 一 十 八 人 ， 直 追 到 但 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('352', '1', '14', '15', '便 在 夜 间 ， 自 己 同 仆 人 分 队 杀 败 敌 人 ， 又 追 到 大 马 士 革 北 边 的 何 把 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('353', '1', '14', '16', '将 被 掳 掠 的 一 切 财 物 夺 回 来 ， 连 他 侄 儿 罗 得 和 他 的 财 物 ， 以 及 妇 女 、 人 民 也 都 夺 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('354', '1', '14', '17', '＜ 麦 基 洗 德 祝 福 亚 伯 兰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('355', '1', '14', '18', '又 有 撒 冷 王 麦 基 洗 德 带 着 饼 和 酒 出 来 迎 接 ； 他 是 至 高 神 的 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('356', '1', '14', '19', '他 为 亚 伯 兰 祝 福 ， 说 ： “ 愿 天 地 的 主 、 至 高 的 神 赐 福 与 亚 伯 兰 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('357', '1', '14', '20', '至 高 的 神 把 敌 人 交 在 你 手 里 ， 是 应 当 称 颂 的 ！ ” 亚 伯 兰 就 把 所 得 的 拿 出 十 分 之 一 来 ， 给 麦 基 洗 德 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('358', '1', '14', '21', '所 多 玛 王 对 亚 伯 兰 说 ： “ 你 把 人 口 给 我 ， 财 物 你 自 己 拿 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('359', '1', '14', '22', '亚 伯 兰 对 所 多 玛 王 说 ： “ 我 已 经 向 天 地 的 主 ─ ─ 至 高 的 神 耶 和 华 起 誓 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('360', '1', '14', '23', '凡 是 你 的 东 西 ， 就 是 一 根 线 、 一 根 鞋 带 ， 我 都 不 拿 ， 免 得 你 说 ： ‘ 我 使 亚 伯 兰 富 足 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('361', '1', '14', '24', '只 有 仆 人 所 吃 的 ， 并 与 我 同 行 的 亚 乃 、 以 实 各 、 幔 利 所 应 得 的 分 ， 可 以 任 凭 他 们 拿 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('362', '1', '15', '1', '＜ 神 与 亚 伯 兰 立 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('363', '1', '15', '2', '亚 伯 兰 说 ： “ 主 耶 和 华 啊 ， 我 既 无 子 ， 你 还 赐 我 什 么 呢 ？ 并 且 要 承 受 我 家 业 的 是 大 马 士 革 人 以 利 以 谢 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('364', '1', '15', '3', '亚 伯 兰 又 说 ： “ 你 没 有 给 我 儿 子 ； 那 生 在 我 家 中 的 人 就 是 我 的 后 嗣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('365', '1', '15', '4', '耶 和 华 又 有 话 对 他 说 ： “ 这 人 必 不 成 为 你 的 后 嗣 ； 你 本 身 所 生 的 才 成 为 你 的 后 嗣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('366', '1', '15', '5', '于 是 领 他 走 到 外 边 ， 说 ： “ 你 向 天 观 看 ， 数 算 众 星 ， 能 数 得 过 来 吗 ？ ” 又 对 他 说 ： “ 你 的 后 裔 将 要 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('367', '1', '15', '6', '亚 伯 兰 信 耶 和 华 ， 耶 和 华 就 以 此 为 他 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('368', '1', '15', '7', '耶 和 华 又 对 他 说 ： “ 我 是 耶 和 华 ， 曾 领 你 出 了 迦 勒 底 的 吾 珥 ， 为 要 将 这 地 赐 你 为 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('369', '1', '15', '8', '亚 伯 兰 说 ： “ 主 耶 和 华 啊 ， 我 怎 能 知 道 必 得 这 地 为 业 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('370', '1', '15', '9', '他 说 ： “ 你 为 我 取 一 只 三 年 的 母 牛 ， 一 只 三 年 的 母 山 羊 ， 一 只 三 年 的 公 绵 羊 ， 一 只 斑 鸠 ， 一 只 雏 鸽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('371', '1', '15', '10', '亚 伯 兰 就 取 了 这 些 来 ， 每 样 劈 开 ， 分 成 两 半 ， 一 半 对 着 一 半 地 摆 列 ， 只 有 鸟 没 有 劈 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('372', '1', '15', '11', '有 鸷 鸟 下 来 ， 落 在 那 死 畜 的 肉 上 ， 亚 伯 兰 就 把 它 吓 飞 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('373', '1', '15', '12', '日 头 正 落 的 时 候 ， 亚 伯 兰 沉 沉 地 睡 了 ； 忽 然 有 惊 人 的 大 黑 暗 落 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('374', '1', '15', '13', '耶 和 华 对 亚 伯 兰 说 ： “ 你 要 的 确 知 道 ， 你 的 后 裔 必 寄 居 别 人 的 地 ， 又 服 事 那 地 的 人 ； 那 地 的 人 要 苦 待 他 们 四 百 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('375', '1', '15', '14', '并 且 他 们 所 要 服 事 的 那 国 ， 我 要 惩 罚 ， 后 来 他 们 必 带 着 许 多 财 物 从 那 里 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('376', '1', '15', '15', '但 你 要 享 大 寿 数 ， 平 平 安 安 地 归 到 你 列 祖 那 里 ， 被 人 埋 葬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('377', '1', '15', '16', '到 了 第 四 代 ， 他 们 必 回 到 此 地 ， 因 为 亚 摩 利 人 的 罪 孽 还 没 有 满 盈 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('378', '1', '15', '17', '日 落 天 黑 ， 不 料 有 冒 烟 的 炉 并 烧 着 的 火 把 从 那 些 肉 块 中 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('379', '1', '15', '18', '当 那 日 ， 耶 和 华 与 亚 伯 兰 立 约 ， 说 ： “ 我 已 赐 给 你 的 后 裔 ， 从 埃 及 河 直 到 幼 发 拉 底 大 河 之 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('380', '1', '15', '19', '就 是 基 尼 人 、 基 尼 洗 人 、 甲 摩 尼 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('381', '1', '15', '20', '赫 人 、 比 利 洗 人 、 利 乏 音 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('382', '1', '15', '21', '亚 摩 利 人 、 迦 南 人 、 革 迦 撒 人 、 耶 布 斯 人 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('383', '1', '16', '1', '＜ 夏 甲 和 以 实 玛 利 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('384', '1', '16', '2', '撒 莱 对 亚 伯 兰 说 ： “ 耶 和 华 使 我 不 能 生 育 。 求 你 和 我 的 使 女 同 房 ， 或 者 我 可 以 因 她 得 孩 子 ｛ 得 孩 子 ： 原 文 是 被 建 立 ｝ 。 亚 伯 兰 听 从 了 撒 莱 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('385', '1', '16', '3', '于 是 亚 伯 兰 的 妻 子 撒 莱 将 使 女 埃 及 人 夏 甲 给 了 丈 夫 为 妾 ； 那 时 亚 伯 兰 在 迦 南 已 经 住 了 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('386', '1', '16', '4', '亚 伯 兰 与 夏 甲 同 房 ， 夏 甲 就 怀 了 孕 ； 她 见 自 己 有 孕 ， 就 小 看 她 的 主 母 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('387', '1', '16', '5', '撒 莱 对 亚 伯 兰 说 ： “ 我 因 你 受 屈 。 我 将 我 的 使 女 放 在 你 怀 中 ， 她 见 自 己 有 了 孕 ， 就 小 看 我 。 愿 耶 和 华 在 你 我 中 间 判 断 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('388', '1', '16', '6', '亚 伯 兰 对 撒 莱 说 ： “ 使 女 在 你 手 下 ， 你 可 以 随 意 待 她 。 ” 撒 莱 苦 待 她 ， 她 就 从 撒 莱 面 前 逃 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('389', '1', '16', '7', '耶 和 华 的 使 者 在 旷 野 书 珥 路 上 的 水 泉 旁 遇 见 她 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('390', '1', '16', '8', '对 她 说 ： “ 撒 莱 的 使 女 夏 甲 ， 你 从 哪 里 来 ？ 要 往 哪 里 去 ？ ” 夏 甲 说 ： “ 我 从 我 的 主 母 撒 莱 面 前 逃 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('391', '1', '16', '9', '耶 和 华 的 使 者 对 她 说 ： “ 你 回 到 你 主 母 那 里 ， 服 在 她 手 下 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('392', '1', '16', '10', '又 说 ： “ 我 必 使 你 的 后 裔 极 其 繁 多 ， 甚 至 不 可 胜 数 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('393', '1', '16', '11', '并 说 ： “ 你 如 今 怀 孕 要 生 一 个 儿 子 ， 可 以 给 他 起 名 叫 以 实 玛 利 ｛ 就 是 神 听 见 的 意 思 ｝ ， 因 为 耶 和 华 听 见 了 你 的 苦 情 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('394', '1', '16', '12', '他 为 人 必 像 野 驴 。 他 的 手 要 攻 打 人 ， 人 的 手 也 要 攻 打 他 ； 他 必 住 在 众 弟 兄 的 东 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('395', '1', '16', '13', '夏 甲 就 称 那 对 她 说 话 的 耶 和 华 为 “ 看 顾 人 的 神 ” 。 因 而 说 ： “ 在 这 里 我 也 看 见 那 看 顾 我 的 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('396', '1', '16', '14', '所 以 这 井 名 叫 庇 耳 ． 拉 海 ． 莱 。 这 井 正 在 加 低 斯 和 巴 列 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('397', '1', '16', '15', '后 来 夏 甲 给 亚 伯 兰 生 了 一 个 儿 子 ； 亚 伯 兰 给 他 起 名 叫 以 实 玛 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('398', '1', '16', '16', '夏 甲 给 亚 伯 兰 生 以 实 玛 利 的 时 候 ， 亚 伯 兰 年 八 十 六 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('399', '1', '17', '1', '＜ 割 礼 ─ ─ 立 约 的 记 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('400', '1', '17', '2', '我 就 与 你 立 约 ， 使 你 的 后 裔 极 其 繁 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('401', '1', '17', '3', '亚 伯 兰 俯 伏 在 地 ； 神 又 对 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('402', '1', '17', '4', '“ 我 与 你 立 约 ： 你 要 作 多 国 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('403', '1', '17', '5', '从 此 以 后 ， 你 的 名 不 再 叫 亚 伯 兰 ， 要 叫 亚 伯 拉 罕 ， 因 为 我 已 立 你 作 多 国 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('404', '1', '17', '6', '我 必 使 你 的 后 裔 极 其 繁 多 ； 国 度 从 你 而 立 ， 君 王 从 你 而 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('405', '1', '17', '7', '我 要 与 你 并 你 世 世 代 代 的 后 裔 坚 立 我 的 约 ， 作 永 远 的 约 ， 是 要 作 你 和 你 后 裔 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('406', '1', '17', '8', '我 要 将 你 现 在 寄 居 的 地 ， 就 是 迦 南 全 地 ， 赐 给 你 和 你 的 后 裔 永 远 为 业 ， 我 也 必 作 他 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('407', '1', '17', '9', '神 又 对 亚 伯 拉 罕 说 ： “ 你 和 你 的 后 裔 必 世 世 代 代 遵 守 我 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('408', '1', '17', '10', '你 们 所 有 的 男 子 都 要 受 割 礼 ； 这 就 是 我 与 你 并 你 的 后 裔 所 立 的 约 ， 是 你 们 所 当 遵 守 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('409', '1', '17', '11', '你 们 都 要 受 割 礼 ｛ 原 文 是 割 阳 皮 ； 1 4 ， 2 3 ， 2 4 ， 2 5 节 同 ｝ ； 这 是 我 与 你 们 立 约 的 证 据 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('410', '1', '17', '12', '你 们 世 世 代 代 的 男 子 ， 无 论 是 家 里 生 的 ， 是 在 你 后 裔 之 外 用 银 子 从 外 人 买 的 ， 生 下 来 第 八 日 ， 都 要 受 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('411', '1', '17', '13', '你 家 里 生 的 和 你 用 银 子 买 的 ， 都 必 须 受 割 礼 。 这 样 ， 我 的 约 就 立 在 你 们 肉 体 上 作 永 远 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('412', '1', '17', '14', '但 不 受 割 礼 的 男 子 必 从 民 中 剪 除 ， 因 他 背 了 我 的 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('413', '1', '17', '15', '神 又 对 亚 伯 拉 罕 说 ： “ 你 的 妻 子 撒 莱 不 可 再 叫 撒 莱 ， 她 的 名 要 叫 撒 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('414', '1', '17', '16', '我 必 赐 福 给 她 ， 也 要 使 你 从 她 得 一 个 儿 子 。 我 要 赐 福 给 她 ， 她 也 要 作 多 国 之 母 ； 必 有 百 姓 的 君 王 从 她 而 出 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('415', '1', '17', '17', '亚 伯 拉 罕 就 俯 伏 在 地 喜 笑 ， 心 里 说 ： “ 一 百 岁 的 人 还 能 得 孩 子 吗 ？ 撒 拉 已 经 九 十 岁 了 ， 还 能 生 养 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('416', '1', '17', '18', '亚 伯 拉 罕 对 神 说 ： “ 但 愿 以 实 玛 利 活 在 你 面 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('417', '1', '17', '19', '神 说 ： “ 不 然 ， 你 妻 子 撒 拉 要 给 你 生 一 个 儿 子 ， 你 要 给 他 起 名 叫 以 撒 。 我 要 与 他 坚 定 所 立 的 约 ， 作 他 后 裔 永 远 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('418', '1', '17', '20', '至 于 以 实 玛 利 ， 我 也 应 允 你 ： 我 必 赐 福 给 他 ， 使 他 昌 盛 ， 极 其 繁 多 。 他 必 生 十 二 个 族 长 ； 我 也 要 使 他 成 为 大 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('419', '1', '17', '21', '到 明 年 这 时 节 ， 撒 拉 必 给 你 生 以 撒 ， 我 要 与 他 坚 定 所 立 的 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('420', '1', '17', '22', '神 和 亚 伯 拉 罕 说 完 了 话 ， 就 离 开 他 上 升 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('421', '1', '17', '23', '正 当 那 日 ， 亚 伯 拉 罕 遵 着 神 的 命 ， 给 他 的 儿 子 以 实 玛 利 和 家 里 的 一 切 男 子 ， 无 论 是 在 家 里 生 的 ， 是 用 银 子 买 的 ， 都 行 了 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('422', '1', '17', '24', '亚 伯 拉 罕 受 割 礼 的 时 候 年 九 十 九 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('423', '1', '17', '25', '他 儿 子 以 实 玛 利 受 割 礼 的 时 候 年 十 三 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('424', '1', '17', '26', '正 当 那 日 ， 亚 伯 拉 罕 和 他 儿 子 以 实 玛 利 一 同 受 了 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('425', '1', '17', '27', '家 里 所 有 的 人 ， 无 论 是 在 家 里 生 的 ， 是 用 银 子 从 外 人 买 的 ， 也 都 一 同 受 了 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('426', '1', '18', '1', '＜ 神 应 许 亚 伯 拉 罕 得 儿 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('427', '1', '18', '2', '举 目 观 看 ， 见 有 三 个 人 在 对 面 站 着 。 他 一 见 ， 就 从 帐 棚 门 口 跑 去 迎 接 他 们 ， 俯 伏 在 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('428', '1', '18', '3', '说 ： “ 我 主 ， 我 若 在 你 眼 前 蒙 恩 ， 求 你 不 要 离 开 仆 人 往 前 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('429', '1', '18', '4', '容 我 拿 点 水 来 ， 你 们 洗 洗 脚 ， 在 树 下 歇 息 歇 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('430', '1', '18', '5', '我 再 拿 一 点 饼 来 ， 你 们 可 以 加 添 心 力 ， 然 后 往 前 去 。 你 们 既 到 仆 人 这 里 来 ， 理 当 如 此 。 ” 他 们 说 ： “ 就 照 你 说 的 行 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('431', '1', '18', '6', '亚 伯 拉 罕 急 忙 进 帐 棚 见 撒 拉 ， 说 ： “ 你 速 速 拿 三 细 亚 细 面 调 和 做 饼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('432', '1', '18', '7', '亚 伯 拉 罕 又 跑 到 牛 群 里 ， 牵 了 一 只 又 嫩 又 好 的 牛 犊 来 ， 交 给 仆 人 ， 仆 人 急 忙 预 备 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('433', '1', '18', '8', '亚 伯 拉 罕 又 取 了 奶 油 和 奶 ， 并 预 备 好 的 牛 犊 来 ， 摆 在 他 们 面 前 ， 自 己 在 树 下 站 在 旁 边 ， 他 们 就 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('434', '1', '18', '9', '他 们 问 亚 伯 拉 罕 说 ： “ 你 妻 子 撒 拉 在 哪 里 ？ ” 他 说 ： “ 在 帐 棚 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('435', '1', '18', '10', '三 人 中 有 一 位 说 ： “ 到 明 年 这 时 候 ， 我 必 要 回 到 你 这 里 ； 你 的 妻 子 撒 拉 必 生 一 个 儿 子 。 ” 撒 拉 在 那 人 后 边 的 帐 棚 门 口 也 听 见 了 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('436', '1', '18', '11', '亚 伯 拉 罕 和 撒 拉 年 纪 老 迈 ， 撒 拉 的 月 经 已 断 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('437', '1', '18', '12', '撒 拉 心 里 暗 笑 ， 说 ： “ 我 既 已 衰 败 ， 我 主 也 老 迈 ， 岂 能 有 这 喜 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('438', '1', '18', '13', '耶 和 华 对 亚 伯 拉 罕 说 ： “ 撒 拉 为 什 么 暗 笑 ， 说 ： ‘ 我 既 已 年 老 ， 果 真 能 生 养 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('439', '1', '18', '14', '耶 和 华 岂 有 难 成 的 事 吗 ？ 到 了 日 期 ， 明 年 这 时 候 ， 我 必 回 到 你 这 里 ， 撒 拉 必 生 一 个 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('440', '1', '18', '15', '撒 拉 就 害 怕 ， 不 承 认 ， 说 ： “ 我 没 有 笑 。 ” 那 位 说 ： “ 不 然 ， 你 实 在 笑 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('441', '1', '18', '16', '＜ 亚 伯 拉 罕 为 所 多 玛 祈 求 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('442', '1', '18', '17', '耶 和 华 说 ： “ 我 所 要 做 的 事 岂 可 瞒 着 亚 伯 拉 罕 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('443', '1', '18', '18', '亚 伯 拉 罕 必 要 成 为 强 大 的 国 ； 地 上 的 万 国 都 必 因 他 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('444', '1', '18', '19', '我 眷 顾 他 ， 为 要 叫 他 吩 咐 他 的 众 子 和 他 的 眷 属 遵 守 我 的 道 ， 秉 公 行 义 ， 使 我 所 应 许 亚 伯 拉 罕 的 话 都 成 就 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('445', '1', '18', '20', '耶 和 华 说 ： “ 所 多 玛 和 蛾 摩 拉 的 罪 恶 甚 重 ， 声 闻 于 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('446', '1', '18', '21', '我 现 在 要 下 去 ， 察 看 他 们 所 行 的 ， 果 然 尽 像 那 达 到 我 耳 中 的 声 音 一 样 吗 ？ 若 是 不 然 ， 我 也 必 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('447', '1', '18', '22', '二 人 转 身 离 开 那 里 ， 向 所 多 玛 去 ； 但 亚 伯 拉 罕 仍 旧 站 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('448', '1', '18', '23', '亚 伯 拉 罕 近 前 来 ， 说 ： “ 无 论 善 恶 ， 你 都 要 剿 灭 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('449', '1', '18', '24', '假 若 那 城 里 有 五 十 个 义 人 ， 你 还 剿 灭 那 地 方 吗 ？ 不 为 城 里 这 五 十 个 义 人 饶 恕 其 中 的 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('450', '1', '18', '25', '将 义 人 与 恶 人 同 杀 ， 将 义 人 与 恶 人 一 样 看 待 ， 这 断 不 是 你 所 行 的 。 审 判 全 地 的 主 岂 不 行 公 义 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('451', '1', '18', '26', '耶 和 华 说 ： “ 我 若 在 所 多 玛 城 里 见 有 五 十 个 义 人 ， 我 就 为 他 们 的 缘 故 饶 恕 那 地 方 的 众 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('452', '1', '18', '27', '亚 伯 拉 罕 说 ： “ 我 虽 然 是 灰 尘 ， 还 敢 对 主 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('453', '1', '18', '28', '假 若 这 五 十 个 义 人 短 了 五 个 ， 你 就 因 为 短 了 五 个 毁 灭 全 城 吗 ？ ” 他 说 ： “ 我 在 那 里 若 见 有 四 十 五 个 ， 也 不 毁 灭 那 城 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('454', '1', '18', '29', '亚 伯 拉 罕 又 对 他 说 ： “ 假 若 在 那 里 见 有 四 十 个 怎 么 样 呢 ？ ” 他 说 ： “ 为 这 四 十 个 的 缘 故 ， 我 也 不 做 这 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('455', '1', '18', '30', '亚 伯 拉 罕 说 ： “ 求 主 不 要 动 怒 ， 容 我 说 ， 假 若 在 那 里 见 有 三 十 个 怎 么 样 呢 ？ ” 他 说 ： “ 我 在 那 里 若 见 有 三 十 个 ， 我 也 不 做 这 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('456', '1', '18', '31', '亚 伯 拉 罕 说 ： “ 我 还 敢 对 主 说 话 ， 假 若 在 那 里 见 有 二 十 个 怎 么 样 呢 ？ ” 他 说 ： “ 为 这 二 十 个 的 缘 故 ， 我 也 不 毁 灭 那 城 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('457', '1', '18', '32', '亚 伯 拉 罕 说 ： “ 求 主 不 要 动 怒 ， 我 再 说 这 一 次 ， 假 若 在 那 里 见 有 十 个 呢 ？ ” 他 说 ： “ 为 这 十 个 的 缘 故 ， 我 也 不 毁 灭 那 城 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('458', '1', '18', '33', '耶 和 华 与 亚 伯 拉 罕 说 完 了 话 就 走 了 ； 亚 伯 拉 罕 也 回 到 自 己 的 地 方 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('459', '1', '19', '1', '＜ 所 多 玛 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('460', '1', '19', '2', '说 ： “ 我 主 啊 ， 请 你 们 到 仆 人 家 里 洗 洗 脚 ， 住 一 夜 ， 清 早 起 来 再 走 。 ” 他 们 说 ： “ 不 ！ 我 们 要 在 街 上 过 夜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('461', '1', '19', '3', '罗 得 切 切 地 请 他 们 ， 他 们 这 才 进 去 ， 到 他 屋 里 。 罗 得 为 他 们 预 备 筵 席 ， 烤 无 酵 饼 ， 他 们 就 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('462', '1', '19', '4', '他 们 还 没 有 躺 下 ， 所 多 玛 城 里 各 处 的 人 ， 连 老 带 少 ， 都 来 围 住 那 房 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('463', '1', '19', '5', '呼 叫 罗 得 说 ： “ 今 日 晚 上 到 你 这 里 来 的 人 在 哪 里 呢 ？ 把 他 们 带 出 来 ， 任 我 们 所 为 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('464', '1', '19', '6', '罗 得 出 来 ， 把 门 关 上 ， 到 众 人 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('465', '1', '19', '7', '说 ： “ 众 弟 兄 ， 请 你 们 不 要 做 这 恶 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('466', '1', '19', '8', '我 有 两 个 女 儿 ， 还 是 处 女 ， 容 我 领 出 来 ， 任 凭 你 们 的 心 愿 而 行 ； 只 是 这 两 个 人 既 然 到 我 舍 下 ， 不 要 向 他 们 做 什 么 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('467', '1', '19', '9', '众 人 说 ： “ 退 去 吧 ！ ” 又 说 ： “ 这 个 人 来 寄 居 ， 还 想 要 作 官 哪 ！ 现 在 我 们 要 害 你 比 害 他 们 更 甚 。 ” 众 人 就 向 前 拥 挤 罗 得 ， 要 攻 破 房 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('468', '1', '19', '10', '只 是 那 二 人 伸 出 手 来 ， 将 罗 得 拉 进 屋 去 ， 把 门 关 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('469', '1', '19', '11', '并 且 使 门 外 的 人 ， 无 论 老 少 ， 眼 都 昏 迷 ； 他 们 摸 来 摸 去 ， 总 寻 不 着 房 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('470', '1', '19', '12', '＜ 罗 得 离 开 所 多 玛 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('471', '1', '19', '13', '我 们 要 毁 灭 这 地 方 ； 因 为 城 内 罪 恶 的 声 音 在 耶 和 华 面 前 甚 大 ， 耶 和 华 差 我 们 来 ， 要 毁 灭 这 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('472', '1', '19', '14', '罗 得 就 出 去 ， 告 诉 娶 了 ｛ 或 译 ： 将 要 娶 ｝ 他 女 儿 的 女 婿 们 说 ： “ 你 们 起 来 离 开 这 地 方 ， 因 为 耶 和 华 要 毁 灭 这 城 。 ” 他 女 婿 们 却 以 为 他 说 的 是 戏 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('473', '1', '19', '15', '天 明 了 ， 天 使 催 逼 罗 得 说 ： “ 起 来 ！ 带 着 你 的 妻 子 和 你 在 这 里 的 两 个 女 儿 出 去 ， 免 得 你 因 这 城 里 的 罪 恶 同 被 剿 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('474', '1', '19', '16', '但 罗 得 迟 延 不 走 。 二 人 因 为 耶 和 华 怜 恤 罗 得 ， 就 拉 着 他 的 手 和 他 妻 子 的 手 ， 并 他 两 个 女 儿 的 手 ， 把 他 们 领 出 来 ， 安 置 在 城 外 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('475', '1', '19', '17', '领 他 们 出 来 以 后 ， 就 说 ： “ 逃 命 吧 ！ 不 可 回 头 看 ， 也 不 可 在 平 原 站 住 。 要 往 山 上 逃 跑 ， 免 得 你 被 剿 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('476', '1', '19', '18', '罗 得 对 他 们 说 ： “ 我 主 啊 ， 不 要 如 此 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('477', '1', '19', '19', '你 仆 人 已 经 在 你 眼 前 蒙 恩 ； 你 又 向 我 显 出 莫 大 的 慈 爱 ， 救 我 的 性 命 。 我 不 能 逃 到 山 上 去 ， 恐 怕 这 灾 祸 临 到 我 ， 我 便 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('478', '1', '19', '20', '看 哪 ， 这 座 城 又 小 又 近 ， 容 易 逃 到 ， 这 不 是 一 个 小 的 吗 ？ 求 你 容 我 逃 到 那 里 ， 我 的 性 命 就 得 存 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('479', '1', '19', '21', '天 使 对 他 说 ： “ 这 事 我 也 应 允 你 ； 我 不 倾 覆 你 所 说 的 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('480', '1', '19', '22', '你 要 速 速 地 逃 到 那 城 ； 因 为 你 还 没 有 到 那 里 ， 我 不 能 做 什 么 。 ” 因 此 那 城 名 叫 琐 珥 ｛ 就 是 小 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('481', '1', '19', '23', '＜ 所 多 玛 蛾 摩 拉 的 毁 灭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('482', '1', '19', '24', '当 时 ， 耶 和 华 将 硫 磺 与 火 从 天 上 耶 和 华 那 里 降 与 所 多 玛 和 蛾 摩 拉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('483', '1', '19', '25', '把 那 些 城 和 全 平 原 ， 并 城 里 所 有 的 居 民 ， 连 地 上 生 长 的 ， 都 毁 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('484', '1', '19', '26', '罗 得 的 妻 子 在 后 边 回 头 一 看 ， 就 变 成 了 一 根 盐 柱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('485', '1', '19', '27', '亚 伯 拉 罕 清 早 起 来 ， 到 了 他 从 前 站 在 耶 和 华 面 前 的 地 方 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('486', '1', '19', '28', '向 所 多 玛 和 蛾 摩 拉 与 平 原 的 全 地 观 看 ， 不 料 ， 那 地 方 烟 气 上 腾 ， 如 同 烧 窑 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('487', '1', '19', '29', '当 神 毁 灭 平 原 诸 城 的 时 候 ， 他 记 念 亚 伯 拉 罕 ， 正 在 倾 覆 罗 得 所 住 之 城 的 时 候 ， 就 打 发 罗 得 从 倾 覆 之 中 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('488', '1', '19', '30', '＜ 摩 押 人 和 亚 扪 人 的 起 源 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('489', '1', '19', '31', '大 女 儿 对 小 女 儿 说 ： “ 我 们 的 父 亲 老 了 ， 地 上 又 无 人 按 着 世 上 的 常 规 进 到 我 们 这 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('490', '1', '19', '32', '来 ！ 我 们 可 以 叫 父 亲 喝 酒 ， 与 他 同 寝 。 这 样 ， 我 们 好 从 他 存 留 后 裔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('491', '1', '19', '33', '于 是 ， 那 夜 她 们 叫 父 亲 喝 酒 ， 大 女 儿 就 进 去 和 她 父 亲 同 寝 ； 她 几 时 躺 下 ， 几 时 起 来 ， 父 亲 都 不 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('492', '1', '19', '34', '第 二 天 ， 大 女 儿 对 小 女 儿 说 ： “ 我 昨 夜 与 父 亲 同 寝 。 今 夜 我 们 再 叫 他 喝 酒 ， 你 可 以 进 去 与 他 同 寝 。 这 样 ， 我 们 好 从 父 亲 存 留 后 裔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('493', '1', '19', '35', '于 是 ， 那 夜 她 们 又 叫 父 亲 喝 酒 ， 小 女 儿 起 来 与 她 父 亲 同 寝 ； 她 几 时 躺 下 ， 几 时 起 来 ， 父 亲 都 不 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('494', '1', '19', '36', '这 样 ， 罗 得 的 两 个 女 儿 都 从 她 父 亲 怀 了 孕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('495', '1', '19', '37', '大 女 儿 生 了 儿 子 ， 给 他 起 名 叫 摩 押 ， 就 是 现 今 摩 押 人 的 始 祖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('496', '1', '19', '38', '小 女 儿 也 生 了 儿 子 ， 给 他 起 名 叫 便 ． 亚 米 ， 就 是 现 今 亚 扪 人 的 始 祖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('497', '1', '20', '1', '＜ 亚 伯 拉 罕 和 亚 比 米 勒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('498', '1', '20', '2', '亚 伯 拉 罕 称 他 的 妻 撒 拉 为 妹 子 ， 基 拉 耳 王 亚 比 米 勒 差 人 把 撒 拉 取 了 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('499', '1', '20', '3', '但 夜 间 ， 神 来 ， 在 梦 中 对 亚 比 米 勒 说 ： “ 你 是 个 死 人 哪 ！ 因 为 你 取 了 那 女 人 来 ； 她 原 是 别 人 的 妻 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('500', '1', '20', '4', '亚 比 米 勒 却 还 没 有 亲 近 撒 拉 ； 他 说 ： “ 主 啊 ， 连 有 义 的 国 ， 你 也 要 毁 灭 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('501', '1', '20', '5', '那 人 岂 不 是 自 己 对 我 说 ‘ 她 是 我 的 妹 子 ’ 吗 ？ 就 是 女 人 也 自 己 说 ： ‘ 他 是 我 的 哥 哥 。 ’ 我 做 这 事 是 心 正 手 洁 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('502', '1', '20', '6', '神 在 梦 中 对 他 说 ： “ 我 知 道 你 做 这 事 是 心 中 正 直 ； 我 也 拦 阻 了 你 ， 免 得 你 得 罪 我 ， 所 以 我 不 容 你 沾 着 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('503', '1', '20', '7', '现 在 你 把 这 人 的 妻 子 归 还 他 ； 因 为 他 是 先 知 ， 他 要 为 你 祷 告 ， 使 你 存 活 。 你 若 不 归 还 他 ， 你 当 知 道 ， 你 和 你 所 有 的 人 都 必 要 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('504', '1', '20', '8', '亚 比 米 勒 清 早 起 来 ， 召 了 众 臣 仆 来 ， 将 这 些 事 都 说 给 他 们 听 ， 他 们 都 甚 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('505', '1', '20', '9', '亚 比 米 勒 召 了 亚 伯 拉 罕 来 ， 对 他 说 ： “ 你 怎 么 向 我 这 样 行 呢 ？ 我 在 什 么 事 上 得 罪 了 你 ， 你 竟 使 我 和 我 国 里 的 人 陷 在 大 罪 里 ？ 你 向 我 行 不 当 行 的 事 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('506', '1', '20', '10', '亚 比 米 勒 又 对 亚 伯 拉 罕 说 ： “ 你 见 了 什 么 才 做 这 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('507', '1', '20', '11', '亚 伯 拉 罕 说 ： “ 我 以 为 这 地 方 的 人 总 不 惧 怕 神 ， 必 为 我 妻 子 的 缘 故 杀 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('508', '1', '20', '12', '况 且 她 也 实 在 是 我 的 妹 子 ； 她 与 我 是 同 父 异 母 ， 后 来 作 了 我 的 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('509', '1', '20', '13', '当 神 叫 我 离 开 父 家 、 飘 流 在 外 的 时 候 ， 我 对 她 说 ： ‘ 我 们 无 论 走 到 什 么 地 方 ， 你 可 以 对 人 说 ： 他 是 我 的 哥 哥 ； 这 就 是 你 待 我 的 恩 典 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('510', '1', '20', '14', '亚 比 米 勒 把 牛 、 羊 、 仆 婢 赐 给 亚 伯 拉 罕 ， 又 把 他 的 妻 子 撒 拉 归 还 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('511', '1', '20', '15', '亚 比 米 勒 又 说 ： “ 看 哪 ， 我 的 地 都 在 你 面 前 ， 你 可 以 随 意 居 住 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('512', '1', '20', '16', '又 对 撒 拉 说 ： “ 我 给 你 哥 哥 一 千 银 子 ， 作 为 你 在 合 家 人 面 前 遮 羞 的 ｛ 羞 ： 原 文 是 眼 ｝ ， 你 就 在 众 人 面 前 没 有 不 是 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('513', '1', '20', '17', '亚 伯 拉 罕 祷 告 神 ， 神 就 医 好 了 亚 比 米 勒 和 他 的 妻 子 ， 并 他 的 众 女 仆 ， 她 们 便 能 生 育 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('514', '1', '20', '18', '因 耶 和 华 为 亚 伯 拉 罕 的 妻 子 撒 拉 的 缘 故 ， 已 经 使 亚 比 米 勒 家 中 的 妇 人 不 能 生 育 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('515', '1', '21', '1', '＜ 以 撒 出 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('516', '1', '21', '2', '当 亚 伯 拉 罕 年 老 的 时 候 ， 撒 拉 怀 了 孕 ； 到 神 所 说 的 日 期 ， 就 给 亚 伯 拉 罕 生 了 一 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('517', '1', '21', '3', '亚 伯 拉 罕 给 撒 拉 所 生 的 儿 子 起 名 叫 以 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('518', '1', '21', '4', '以 撒 生 下 来 第 八 日 ， 亚 伯 拉 罕 照 着 神 所 吩 咐 的 ， 给 以 撒 行 了 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('519', '1', '21', '5', '他 儿 子 以 撒 生 的 时 候 ， 亚 伯 拉 罕 年 一 百 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('520', '1', '21', '6', '撒 拉 说 ： “ 神 使 我 喜 笑 ， 凡 听 见 的 必 与 我 一 同 喜 笑 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('521', '1', '21', '7', '又 说 ： “ 谁 能 预 先 对 亚 伯 拉 罕 说 ‘ 撒 拉 要 乳 养 婴 孩 ’ 呢 ？ 因 为 在 他 年 老 的 时 候 ， 我 给 他 生 了 一 个 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('522', '1', '21', '8', '孩 子 渐 长 ， 就 断 了 奶 。 以 撒 断 奶 的 日 子 ， 亚 伯 拉 罕 设 摆 丰 盛 的 筵 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('523', '1', '21', '9', '＜ 夏 甲 和 以 实 玛 利 被 逐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('524', '1', '21', '10', '就 对 亚 伯 拉 罕 说 ： “ 你 把 这 使 女 和 她 儿 子 赶 出 去 ！ 因 为 这 使 女 的 儿 子 不 可 与 我 的 儿 子 以 撒 一 同 承 受 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('525', '1', '21', '11', '亚 伯 拉 罕 因 他 儿 子 的 缘 故 很 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('526', '1', '21', '12', '神 对 亚 伯 拉 罕 说 ： “ 你 不 必 为 这 童 子 和 你 的 使 女 忧 愁 。 凡 撒 拉 对 你 说 的 话 ， 你 都 该 听 从 ； 因 为 从 以 撒 生 的 ， 才 要 称 为 你 的 后 裔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('527', '1', '21', '13', '至 于 使 女 的 儿 子 ， 我 也 必 使 他 的 后 裔 成 立 一 国 ， 因 为 他 是 你 所 生 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('528', '1', '21', '14', '亚 伯 拉 罕 清 早 起 来 ， 拿 饼 和 一 皮 袋 水 ， 给 了 夏 甲 ， 搭 在 她 的 肩 上 ， 又 把 孩 子 交 给 她 ， 打 发 她 走 。 夏 甲 就 走 了 ， 在 别 是 巴 的 旷 野 走 迷 了 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('529', '1', '21', '15', '皮 袋 的 水 用 尽 了 ， 夏 甲 就 把 孩 子 撇 在 小 树 底 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('530', '1', '21', '16', '自 己 走 开 约 有 一 箭 之 远 ， 相 对 而 坐 ， 说 ： “ 我 不 忍 见 孩 子 死 ” ， 就 相 对 而 坐 ， 放 声 大 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('531', '1', '21', '17', '神 听 见 童 子 的 声 音 ； 神 的 使 者 从 天 上 呼 叫 夏 甲 说 ： “ 夏 甲 ， 你 为 何 这 样 呢 ？ 不 要 害 怕 ， 神 已 经 听 见 童 子 的 声 音 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('532', '1', '21', '18', '起 来 ！ 把 童 子 抱 在 怀 中 ｛ 怀 ： 原 文 是 手 ｝ ， 我 必 使 他 的 后 裔 成 为 大 国 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('533', '1', '21', '19', '神 使 夏 甲 的 眼 睛 明 亮 ， 她 就 看 见 一 口 水 井 ， 便 去 将 皮 袋 盛 满 了 水 ， 给 童 子 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('534', '1', '21', '20', '神 保 佑 童 子 ， 他 就 渐 长 ， 住 在 旷 野 ， 成 了 弓 箭 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('535', '1', '21', '21', '他 住 在 巴 兰 的 旷 野 ； 他 母 亲 从 埃 及 地 给 他 娶 了 一 个 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('536', '1', '21', '22', '＜ 亚 伯 拉 罕 跟 亚 比 米 勒 立 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('537', '1', '21', '23', '我 愿 你 如 今 在 这 里 指 着 神 对 我 起 誓 ， 不 要 欺 负 我 与 我 的 儿 子 ， 并 我 的 子 孙 。 我 怎 样 厚 待 了 你 ， 你 也 要 照 样 厚 待 我 与 你 所 寄 居 这 地 的 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('538', '1', '21', '24', '亚 伯 拉 罕 说 ： “ 我 情 愿 起 誓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('539', '1', '21', '25', '从 前 ， 亚 比 米 勒 的 仆 人 霸 占 了 一 口 水 井 ， 亚 伯 拉 罕 为 这 事 指 责 亚 比 米 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('540', '1', '21', '26', '亚 比 米 勒 说 ： “ 谁 做 这 事 ， 我 不 知 道 ， 你 也 没 有 告 诉 我 ， 今 日 我 才 听 见 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('541', '1', '21', '27', '亚 伯 拉 罕 把 羊 和 牛 给 了 亚 比 米 勒 ， 二 人 就 彼 此 立 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('542', '1', '21', '28', '亚 伯 拉 罕 把 七 只 母 羊 羔 另 放 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('543', '1', '21', '29', '亚 比 米 勒 问 亚 伯 拉 罕 说 ： “ 你 把 这 七 只 母 羊 羔 另 放 在 一 处 ， 是 什 么 意 思 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('544', '1', '21', '30', '他 说 ： “ 你 要 从 我 手 里 受 这 七 只 母 羊 羔 ， 作 我 挖 这 口 井 的 证 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('545', '1', '21', '31', '所 以 他 给 那 地 方 起 名 叫 别 是 巴 ｛ 就 是 盟 誓 的 井 的 意 思 ｝ ， 因 为 他 们 二 人 在 那 里 起 了 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('546', '1', '21', '32', '他 们 在 别 是 巴 立 了 约 ， 亚 比 米 勒 就 同 他 军 长 非 各 起 身 回 非 利 士 地 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('547', '1', '21', '33', '亚 伯 拉 罕 在 别 是 巴 栽 上 一 棵 垂 丝 柳 树 ， 又 在 那 里 求 告 耶 和 华 ─ ─ 永 生 神 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('548', '1', '21', '34', '亚 伯 拉 罕 在 非 利 士 人 的 地 寄 居 了 多 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('549', '1', '22', '1', '＜ 神 吩 咐 亚 伯 拉 罕 献 以 撒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('550', '1', '22', '2', '神 说 ： “ 你 带 着 你 的 儿 子 ， 就 是 你 独 生 的 儿 子 ， 你 所 爱 的 以 撒 ， 往 摩 利 亚 地 去 ， 在 我 所 要 指 示 你 的 山 上 ， 把 他 献 为 燔 祭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('551', '1', '22', '3', '亚 伯 拉 罕 清 早 起 来 ， 备 上 驴 ， 带 着 两 个 仆 人 和 他 儿 子 以 撒 ， 也 劈 好 了 燔 祭 的 柴 ， 就 起 身 往 神 所 指 示 他 的 地 方 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('552', '1', '22', '4', '到 了 第 三 日 ， 亚 伯 拉 罕 举 目 远 远 地 看 见 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('553', '1', '22', '5', '亚 伯 拉 罕 对 他 的 仆 人 说 ： “ 你 们 和 驴 在 此 等 候 ， 我 与 童 子 往 那 里 去 拜 一 拜 ， 就 回 到 你 们 这 里 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('554', '1', '22', '6', '亚 伯 拉 罕 把 燔 祭 的 柴 放 在 他 儿 子 以 撒 身 上 ， 自 己 手 里 拿 着 火 与 刀 ； 于 是 二 人 同 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('555', '1', '22', '7', '以 撒 对 他 父 亲 亚 伯 拉 罕 说 ： “ 父 亲 哪 ！ ” 亚 伯 拉 罕 说 ： “ 我 儿 ， 我 在 这 里 。 ” 以 撒 说 ： “ 请 看 ， 火 与 柴 都 有 了 ， 但 燔 祭 的 羊 羔 在 哪 里 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('556', '1', '22', '8', '亚 伯 拉 罕 说 ： “ 我 儿 ， 神 必 自 己 预 备 作 燔 祭 的 羊 羔 。 ” 于 是 二 人 同 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('557', '1', '22', '9', '他 们 到 了 神 所 指 示 的 地 方 ， 亚 伯 拉 罕 在 那 里 筑 坛 ， 把 柴 摆 好 ， 捆 绑 他 的 儿 子 以 撒 ， 放 在 坛 的 柴 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('558', '1', '22', '10', '亚 伯 拉 罕 就 伸 手 拿 刀 ， 要 杀 他 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('559', '1', '22', '11', '耶 和 华 的 使 者 从 天 上 呼 叫 他 说 ： “ 亚 伯 拉 罕 ！ 亚 伯 拉 罕 ！ ” 他 说 ： “ 我 在 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('560', '1', '22', '12', '天 使 说 ： “ 你 不 可 在 这 童 子 身 上 下 手 。 一 点 不 可 害 他 ！ 现 在 我 知 道 你 是 敬 畏 神 的 了 ； 因 为 你 没 有 将 你 的 儿 子 ， 就 是 你 独 生 的 儿 子 ， 留 下 不 给 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('561', '1', '22', '13', '亚 伯 拉 罕 举 目 观 看 ， 不 料 ， 有 一 只 公 羊 ， 两 角 扣 在 稠 密 的 小 树 中 。 亚 伯 拉 罕 就 取 了 那 只 公 羊 来 ， 献 为 燔 祭 ， 代 替 他 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('562', '1', '22', '14', '亚 伯 拉 罕 给 那 地 方 起 名 叫 “ 耶 和 华 以 勒 ” ｛ 就 是 耶 和 华 必 预 备 的 意 思 ｝ ， 直 到 今 日 人 还 说 ： “ 在 耶 和 华 的 山 上 必 有 预 备 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('563', '1', '22', '15', '耶 和 华 的 使 者 第 二 次 从 天 上 呼 叫 亚 伯 拉 罕 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('564', '1', '22', '16', '“ 耶 和 华 说 ： ‘ 你 既 行 了 这 事 ， 不 留 下 你 的 儿 子 ， 就 是 你 独 生 的 儿 子 ， 我 便 指 着 自 己 起 誓 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('565', '1', '22', '17', '论 福 ， 我 必 赐 大 福 给 你 ； 论 子 孙 ， 我 必 叫 你 的 子 孙 多 起 来 ， 如 同 天 上 的 星 ， 海 边 的 沙 。 你 子 孙 必 得 着 仇 敌 的 城 门 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('566', '1', '22', '18', '并 且 地 上 万 国 都 必 因 你 的 后 裔 得 福 ， 因 为 你 听 从 了 我 的 话 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('567', '1', '22', '19', '于 是 亚 伯 拉 罕 回 到 他 仆 人 那 里 ， 他 们 一 同 起 身 往 别 是 巴 去 ， 亚 伯 拉 罕 就 住 在 别 是 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('568', '1', '22', '20', '＜ 拿 鹤 的 后 代 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('569', '1', '22', '21', '长 子 是 乌 斯 ， 他 的 兄 弟 是 布 斯 和 亚 兰 的 父 亲 基 母 利 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('570', '1', '22', '22', '并 基 薛 、 哈 琐 、 必 达 、 益 拉 、 彼 土 利 （ 彼 土 利 生 利 百 加 ） 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('571', '1', '22', '23', '这 八 个 人 都 是 密 迦 给 亚 伯 拉 罕 的 兄 弟 拿 鹤 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('572', '1', '22', '24', '拿 鹤 的 妾 名 叫 流 玛 ， 生 了 提 八 、 迦 含 、 他 辖 ， 和 玛 迦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('573', '1', '23', '1', '＜ 亚 伯 拉 罕 买 坟 地 埋 葬 撒 拉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('574', '1', '23', '2', '撒 拉 死 在 迦 南 地 的 基 列 ． 亚 巴 ， 就 是 希 伯 仑 。 亚 伯 拉 罕 为 她 哀 恸 哭 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('575', '1', '23', '3', '后 来 亚 伯 拉 罕 从 死 人 面 前 起 来 ， 对 赫 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('576', '1', '23', '4', '“ 我 在 你 们 中 间 是 外 人 ， 是 寄 居 的 。 求 你 们 在 这 里 给 我 一 块 地 ， 我 好 埋 葬 我 的 死 人 ， 使 她 不 在 我 眼 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('577', '1', '23', '5', '赫 人 回 答 亚 伯 拉 罕 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('578', '1', '23', '6', '“ 我 主 请 听 。 你 在 我 们 中 间 是 一 位 尊 大 的 王 子 ， 只 管 在 我 们 最 好 的 坟 地 里 埋 葬 你 的 死 人 ； 我 们 没 有 一 人 不 容 你 在 他 的 坟 地 里 埋 葬 你 的 死 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('579', '1', '23', '7', '亚 伯 拉 罕 就 起 来 ， 向 那 地 的 赫 人 下 拜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('580', '1', '23', '8', '对 他 们 说 ： “ 你 们 若 有 意 叫 我 埋 葬 我 的 死 人 ， 使 她 不 在 我 眼 前 ， 就 请 听 我 的 话 ， 为 我 求 琐 辖 的 儿 子 以 弗 仑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('581', '1', '23', '9', '把 田 头 上 那 麦 比 拉 洞 给 我 ， 他 可 以 按 着 足 价 卖 给 我 ， 作 我 在 你 们 中 间 的 坟 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('582', '1', '23', '10', '当 时 以 弗 仑 正 坐 在 赫 人 中 间 。 于 是 ， 赫 人 以 弗 仑 在 城 门 出 入 的 赫 人 面 前 对 亚 伯 拉 罕 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('583', '1', '23', '11', '“ 不 然 ， 我 主 请 听 。 我 送 给 你 这 块 田 ， 连 田 间 的 洞 也 送 给 你 ， 在 我 同 族 的 人 面 前 都 给 你 ， 可 以 埋 葬 你 的 死 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('584', '1', '23', '12', '亚 伯 拉 罕 就 在 那 地 的 人 民 面 前 下 拜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('585', '1', '23', '13', '在 他 们 面 前 对 以 弗 仑 说 ： “ 你 若 应 允 ， 请 听 我 的 话 。 我 要 把 田 价 给 你 ， 求 你 收 下 ， 我 就 在 那 里 埋 葬 我 的 死 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('586', '1', '23', '14', '以 弗 仑 回 答 亚 伯 拉 罕 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('587', '1', '23', '15', '“ 我 主 请 听 。 值 四 百 舍 客 勒 银 子 的 一 块 田 ， 在 你 我 中 间 还 算 什 么 呢 ？ 只 管 埋 葬 你 的 死 人 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('588', '1', '23', '16', '亚 伯 拉 罕 听 从 了 以 弗 仑 ， 照 着 他 在 赫 人 面 前 所 说 的 话 ， 把 买 卖 通 用 的 银 子 平 了 四 百 舍 客 勒 给 以 弗 仑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('589', '1', '23', '17', '于 是 ， 麦 比 拉 、 幔 利 前 、 以 弗 仑 的 那 块 田 和 其 中 的 洞 ， 并 田 间 四 围 的 树 木 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('590', '1', '23', '18', '都 定 准 归 与 亚 伯 拉 罕 ， 乃 是 他 在 赫 人 面 前 并 城 门 出 入 的 人 面 前 买 妥 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('591', '1', '23', '19', '此 后 ， 亚 伯 拉 罕 把 他 妻 子 撒 拉 埋 葬 在 迦 南 地 幔 利 前 的 麦 比 拉 田 间 的 洞 里 。 （ 幔 利 就 是 希 伯 仑 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('592', '1', '23', '20', '从 此 ， 那 块 田 和 田 间 的 洞 就 藉 着 赫 人 定 准 归 与 亚 伯 拉 罕 作 坟 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('593', '1', '24', '1', '＜ 以 撒 娶 妻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('594', '1', '24', '2', '亚 伯 拉 罕 对 管 理 他 全 业 最 老 的 仆 人 说 ： “ 请 你 把 手 放 在 我 大 腿 底 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('595', '1', '24', '3', '我 要 叫 你 指 着 耶 和 华 ─ ─ 天 地 的 主 起 誓 ， 不 要 为 我 儿 子 娶 这 迦 南 地 中 的 女 子 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('596', '1', '24', '4', '你 要 往 我 本 地 本 族 去 ， 为 我 的 儿 子 以 撒 娶 一 个 妻 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('597', '1', '24', '5', '仆 人 对 他 说 ： “ 倘 若 女 子 不 肯 跟 我 到 这 地 方 来 ， 我 必 须 将 你 的 儿 子 带 回 你 原 出 之 地 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('598', '1', '24', '6', '亚 伯 拉 罕 对 他 说 ： “ 你 要 谨 慎 ， 不 要 带 我 的 儿 子 回 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('599', '1', '24', '7', '耶 和 华 ─ ─ 天 上 的 主 曾 带 领 我 离 开 父 家 和 本 族 的 地 ， 对 我 说 话 ， 向 我 起 誓 说 ： ‘ 我 要 将 这 地 赐 给 你 的 后 裔 。 ’ 他 必 差 遣 使 者 在 你 面 前 ， 你 就 可 以 从 那 里 为 我 儿 子 娶 一 个 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('600', '1', '24', '8', '倘 若 女 子 不 肯 跟 你 来 ， 我 使 你 起 的 誓 就 与 你 无 干 了 ， 只 是 不 可 带 我 的 儿 子 回 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('601', '1', '24', '9', '仆 人 就 把 手 放 在 他 主 人 亚 伯 拉 罕 的 大 腿 底 下 ， 为 这 事 向 他 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('602', '1', '24', '10', '那 仆 人 从 他 主 人 的 骆 驼 里 取 了 十 匹 骆 驼 ， 并 带 些 他 主 人 各 样 的 财 物 ， 起 身 往 美 索 不 达 米 亚 去 ， 到 了 拿 鹤 的 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('603', '1', '24', '11', '天 将 晚 ， 众 女 子 出 来 打 水 的 时 候 ， 他 便 叫 骆 驼 跪 在 城 外 的 水 井 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('604', '1', '24', '12', '他 说 ： “ 耶 和 华 ─ ─ 我 主 人 亚 伯 拉 罕 的 神 啊 ， 求 你 施 恩 给 我 主 人 亚 伯 拉 罕 ， 使 我 今 日 遇 见 好 机 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('605', '1', '24', '13', '我 现 今 站 在 井 旁 ， 城 内 居 民 的 女 子 们 正 出 来 打 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('606', '1', '24', '14', '我 向 那 一 个 女 子 说 ： ‘ 请 你 拿 下 水 瓶 来 ， 给 我 水 喝 。 ’ 她 若 说 ： ‘ 请 喝 ！ 我 也 给 你 的 骆 驼 喝 。 ’ 愿 那 女 子 就 作 你 所 预 定 给 你 仆 人 以 撒 的 妻 。 这 样 ， 我 便 知 道 你 施 恩 给 我 主 人 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('607', '1', '24', '15', '话 还 没 有 说 完 ， 不 料 ， 利 百 加 肩 头 上 扛 着 水 瓶 出 来 。 利 百 加 是 彼 土 利 所 生 的 ； 彼 土 利 是 亚 伯 拉 罕 兄 弟 拿 鹤 妻 子 密 迦 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('608', '1', '24', '16', '那 女 子 容 貌 极 其 俊 美 ， 还 是 处 女 ， 也 未 曾 有 人 亲 近 她 。 她 下 到 井 旁 ， 打 满 了 瓶 ， 又 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('609', '1', '24', '17', '仆 人 跑 上 前 去 迎 着 她 ， 说 ： “ 求 你 将 瓶 里 的 水 给 我 一 点 喝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('610', '1', '24', '18', '女 子 说 ： “ 我 主 请 喝 ！ ” 就 急 忙 拿 下 瓶 来 ， 托 在 手 上 给 他 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('611', '1', '24', '19', '女 子 给 他 喝 了 ， 就 说 ： “ 我 再 为 你 的 骆 驼 打 水 ， 叫 骆 驼 也 喝 足 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('612', '1', '24', '20', '她 就 急 忙 把 瓶 里 的 水 倒 在 槽 里 ， 又 跑 到 井 旁 打 水 ， 就 为 所 有 的 骆 驼 打 上 水 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('613', '1', '24', '21', '那 人 定 睛 看 她 ， 一 句 话 也 不 说 ， 要 晓 得 耶 和 华 赐 他 通 达 的 道 路 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('614', '1', '24', '22', '骆 驼 喝 足 了 ， 那 人 就 拿 一 个 金 环 ， 重 半 舍 客 勒 ， 两 个 金 镯 ， 重 十 舍 客 勒 ， 给 了 那 女 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('615', '1', '24', '23', '说 ： “ 请 告 诉 我 ， 你 是 谁 的 女 儿 ？ 你 父 亲 家 里 有 我 们 住 宿 的 地 方 没 有 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('616', '1', '24', '24', '女 子 说 ： “ 我 是 密 迦 与 拿 鹤 之 子 彼 土 利 的 女 儿 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('617', '1', '24', '25', '又 说 ： “ 我 们 家 里 足 有 粮 草 ， 也 有 住 宿 的 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('618', '1', '24', '26', '那 人 就 低 头 向 耶 和 华 下 拜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('619', '1', '24', '27', '说 ： “ 耶 和 华 ─ ─ 我 主 人 亚 伯 拉 罕 的 神 是 应 当 称 颂 的 ， 因 他 不 断 地 以 慈 爱 诚 实 待 我 主 人 。 至 于 我 ， 耶 和 华 在 路 上 引 领 我 ， 直 走 到 我 主 人 的 兄 弟 家 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('620', '1', '24', '28', '女 子 跑 回 去 ， 照 着 这 些 话 告 诉 她 母 亲 和 她 家 里 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('621', '1', '24', '29', '利 百 加 有 一 个 哥 哥 ， 名 叫 拉 班 ， 看 见 金 环 ， 又 看 见 金 镯 在 他 妹 子 的 手 上 ， 并 听 见 他 妹 子 利 百 加 的 话 ， 说 那 人 对 我 如 此 如 此 说 。 拉 班 就 跑 出 来 往 井 旁 去 ， 到 那 人 跟 前 ， 见 他 仍 站 在 骆 驼 旁 边 的 井 旁 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('622', '1', '24', '30', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('623', '1', '24', '31', '便 对 他 说 ： “ 你 这 蒙 耶 和 华 赐 福 的 ， 请 进 来 ， 为 什 么 站 在 外 边 ？ 我 已 经 收 拾 了 房 屋 ， 也 为 骆 驼 预 备 了 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('624', '1', '24', '32', '那 人 就 进 了 拉 班 的 家 。 拉 班 卸 了 骆 驼 ， 用 草 料 喂 上 ， 拿 水 给 那 人 和 跟 随 的 人 洗 脚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('625', '1', '24', '33', '把 饭 摆 在 他 面 前 ， 叫 他 吃 ， 他 却 说 ： “ 我 不 吃 ， 等 我 说 明 白 我 的 事 情 再 吃 。 ” 拉 班 说 ： “ 请 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('626', '1', '24', '34', '他 说 ： “ 我 是 亚 伯 拉 罕 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('627', '1', '24', '35', '耶 和 华 大 大 地 赐 福 给 我 主 人 ， 使 他 昌 大 ， 又 赐 给 他 羊 群 、 牛 群 、 金 银 、 仆 婢 、 骆 驼 ， 和 驴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('628', '1', '24', '36', '我 主 人 的 妻 子 撒 拉 年 老 的 时 候 给 我 主 人 生 了 一 个 儿 子 ； 我 主 人 也 将 一 切 所 有 的 都 给 了 这 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('629', '1', '24', '37', '我 主 人 叫 我 起 誓 说 ： ‘ 你 不 要 为 我 儿 子 娶 迦 南 地 的 女 子 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('630', '1', '24', '38', '你 要 往 我 父 家 、 我 本 族 那 里 去 ， 为 我 的 儿 子 娶 一 个 妻 子 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('631', '1', '24', '39', '我 对 我 主 人 说 ： ‘ 恐 怕 女 子 不 肯 跟 我 来 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('632', '1', '24', '40', '他 就 说 ： ‘ 我 所 事 奉 的 耶 和 华 必 要 差 遣 他 的 使 者 与 你 同 去 ， 叫 你 的 道 路 通 达 ， 你 就 得 以 在 我 父 家 、 我 本 族 那 里 ， 给 我 的 儿 子 娶 一 个 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('633', '1', '24', '41', '只 要 你 到 了 我 本 族 那 里 ， 我 使 你 起 的 誓 就 与 你 无 干 。 他 们 若 不 把 女 子 交 给 你 ， 我 使 你 起 的 誓 也 与 你 无 干 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('634', '1', '24', '42', '“ 我 今 日 到 了 井 旁 ， 便 说 ： ‘ 耶 和 华 ─ ─ 我 主 人 亚 伯 拉 罕 的 神 啊 ， 愿 你 叫 我 所 行 的 道 路 通 达 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('635', '1', '24', '43', '我 如 今 站 在 井 旁 ， 对 哪 一 个 出 来 打 水 的 女 子 说 ： 请 你 把 你 瓶 里 的 水 给 我 一 点 喝 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('636', '1', '24', '44', '她 若 说 ： 你 只 管 喝 ， 我 也 为 你 的 骆 驼 打 水 ； 愿 那 女 子 就 作 耶 和 华 给 我 主 人 儿 子 所 预 定 的 妻 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('637', '1', '24', '45', '我 心 里 的 话 还 没 有 说 完 ， 利 百 加 就 出 来 ， 肩 头 上 扛 着 水 瓶 ， 下 到 井 旁 打 水 。 我 便 对 她 说 ： ‘ 请 你 给 我 水 喝 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('638', '1', '24', '46', '她 就 急 忙 从 肩 头 上 拿 下 瓶 来 ， 说 ： ‘ 请 喝 ！ 我 也 给 你 的 骆 驼 喝 。 ’ 我 便 喝 了 ； 她 又 给 我 的 骆 驼 喝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('639', '1', '24', '47', '我 问 她 说 ： ‘ 你 是 谁 的 女 儿 ？ ’ 她 说 ： ‘ 我 是 密 迦 与 拿 鹤 之 子 彼 土 利 的 女 儿 。 ’ 我 就 把 环 子 戴 在 她 鼻 子 上 ， 把 镯 子 戴 在 她 两 手 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('640', '1', '24', '48', '随 后 我 低 头 向 耶 和 华 下 拜 ， 称 颂 耶 和 华 ─ ─ 我 主 人 亚 伯 拉 罕 的 神 ； 因 为 他 引 导 我 走 合 式 的 道 路 ， 使 我 得 着 我 主 人 兄 弟 的 孙 女 ， 给 我 主 人 的 儿 子 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('641', '1', '24', '49', '现 在 你 们 若 愿 以 慈 爱 诚 实 待 我 主 人 ， 就 告 诉 我 ； 若 不 然 ， 也 告 诉 我 ， 使 我 可 以 或 向 左 ， 或 向 右 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('642', '1', '24', '50', '拉 班 和 彼 土 利 回 答 说 ： “ 这 事 乃 出 于 耶 和 华 ， 我 们 不 能 向 你 说 好 说 歹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('643', '1', '24', '51', '看 哪 ， 利 百 加 在 你 面 前 ， 可 以 将 她 带 去 ， 照 着 耶 和 华 所 说 的 ， 给 你 主 人 的 儿 子 为 妻 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('644', '1', '24', '52', '亚 伯 拉 罕 的 仆 人 听 见 他 们 这 话 ， 就 向 耶 和 华 俯 伏 在 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('645', '1', '24', '53', '当 下 仆 人 拿 出 金 器 、 银 器 ， 和 衣 服 送 给 利 百 加 ， 又 将 宝 物 送 给 她 哥 哥 和 她 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('646', '1', '24', '54', '仆 人 和 跟 从 他 的 人 吃 了 喝 了 ， 住 了 一 夜 。 早 晨 起 来 ， 仆 人 就 说 ： “ 请 打 发 我 回 我 主 人 那 里 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('647', '1', '24', '55', '利 百 加 的 哥 哥 和 她 母 亲 说 ： “ 让 女 子 同 我 们 再 住 几 天 ， 至 少 十 天 ， 然 后 她 可 以 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('648', '1', '24', '56', '仆 人 说 ： “ 耶 和 华 既 赐 给 我 通 达 的 道 路 ， 你 们 不 要 耽 误 我 ， 请 打 发 我 走 ， 回 我 主 人 那 里 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('649', '1', '24', '57', '他 们 说 ： “ 我 们 把 女 子 叫 来 问 问 她 ” ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('650', '1', '24', '58', '就 叫 了 利 百 加 来 ， 问 她 说 ： “ 你 和 这 人 同 去 吗 ？ ” 利 百 加 说 ： “ 我 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('651', '1', '24', '59', '于 是 他 们 打 发 妹 子 利 百 加 和 她 的 乳 母 ， 同 亚 伯 拉 罕 的 仆 人 ， 并 跟 从 仆 人 的 ， 都 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('652', '1', '24', '60', '他 们 就 给 利 百 加 祝 福 说 ： 我 们 的 妹 子 啊 ， 愿 你 作 千 万 人 的 母 ！ 愿 你 的 后 裔 得 着 仇 敌 的 城 门 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('653', '1', '24', '61', '利 百 加 和 她 的 使 女 们 起 来 ， 骑 上 骆 驼 ， 跟 着 那 仆 人 ， 仆 人 就 带 着 利 百 加 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('654', '1', '24', '62', '那 时 ， 以 撒 住 在 南 地 ， 刚 从 庇 耳 ． 拉 海 ． 莱 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('655', '1', '24', '63', '天 将 晚 ， 以 撒 出 来 在 田 间 默 想 ， 举 目 一 看 ， 见 来 了 些 骆 驼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('656', '1', '24', '64', '利 百 加 举 目 看 见 以 撒 ， 就 急 忙 下 了 骆 驼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('657', '1', '24', '65', '问 那 仆 人 说 ： “ 这 田 间 走 来 迎 接 我 们 的 是 谁 ？ ” 仆 人 说 ： “ 是 我 的 主 人 。 ” 利 百 加 就 拿 帕 子 蒙 上 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('658', '1', '24', '66', '仆 人 就 将 所 办 的 一 切 事 都 告 诉 以 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('659', '1', '24', '67', '以 撒 便 领 利 百 加 进 了 他 母 亲 撒 拉 的 帐 棚 ， 娶 了 她 为 妻 ， 并 且 爱 她 。 以 撒 自 从 他 母 亲 不 在 了 ， 这 才 得 了 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('660', '1', '25', '1', '＜ 亚 伯 拉 罕 的 其 他 后 代 （ 代 上   1 : 3 2 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('661', '1', '25', '2', '基 土 拉 给 他 生 了 心 兰 、 约 珊 、 米 但 、 米 甸 、 伊 施 巴 ， 和 书 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('662', '1', '25', '3', '约 珊 生 了 示 巴 和 底 但 。 底 但 的 子 孙 是 亚 书 利 族 、 利 都 是 族 ， 和 利 乌 米 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('663', '1', '25', '4', '米 甸 的 儿 子 是 以 法 、 以 弗 、 哈 诺 、 亚 比 大 ， 和 以 勒 大 。 这 都 是 基 土 拉 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('664', '1', '25', '5', '亚 伯 拉 罕 将 一 切 所 有 的 都 给 了 以 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('665', '1', '25', '6', '亚 伯 拉 罕 把 财 物 分 给 他 庶 出 的 众 子 ， 趁 着 自 己 还 在 世 的 时 候 打 发 他 们 离 开 他 的 儿 子 以 撒 ， 往 东 方 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('666', '1', '25', '7', '＜ 亚 伯 拉 罕 的 死 和 埋 葬 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('667', '1', '25', '8', '亚 伯 拉 罕 寿 高 年 迈 ， 气 绝 而 死 ， 归 到 他 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('668', '1', '25', '9', '他 两 个 儿 子 以 撒 、 以 实 玛 利 把 他 埋 葬 在 麦 比 拉 洞 里 。 这 洞 在 幔 利 前 、 赫 人 琐 辖 的 儿 子 以 弗 仑 的 田 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('669', '1', '25', '10', '就 是 亚 伯 拉 罕 向 赫 人 买 的 那 块 田 。 亚 伯 拉 罕 和 他 妻 子 撒 拉 都 葬 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('670', '1', '25', '11', '亚 伯 拉 罕 死 了 以 后 ， 神 赐 福 给 他 的 儿 子 以 撒 。 以 撒 靠 近 庇 耳 ． 拉 海 ． 莱 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('671', '1', '25', '12', '＜ 以 实 玛 利 的 后 代 （ 代 上   1 : 2 8 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('672', '1', '25', '13', '以 实 玛 利 儿 子 们 的 名 字 ， 按 着 他 们 的 家 谱 记 在 下 面 。 以 实 玛 利 的 长 子 是 尼 拜 约 ， 又 有 基 达 、 亚 德 别 、 米 比 衫 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('673', '1', '25', '14', '米 施 玛 、 度 玛 、 玛 撒 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('674', '1', '25', '15', '哈 大 、 提 玛 、 伊 突 、 拿 非 施 、 基 底 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('675', '1', '25', '16', '这 是 以 实 玛 利 众 子 的 名 字 ， 照 着 他 们 的 村 庄 、 营 寨 ， 作 了 十 二 族 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('676', '1', '25', '17', '以 实 玛 利 享 寿 一 百 三 十 七 岁 ， 气 绝 而 死 ， 归 到 他 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('677', '1', '25', '18', '他 子 孙 的 住 处 在 他 众 弟 兄 东 边 ， 从 哈 腓 拉 直 到 埃 及 前 的 书 珥 ， 正 在 亚 述 的 道 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('678', '1', '25', '19', '＜ 以 扫 和 雅 各 出 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('679', '1', '25', '20', '以 撒 娶 利 百 加 为 妻 的 时 候 正 四 十 岁 。 利 百 加 是 巴 旦 ． 亚 兰 地 的 亚 兰 人 彼 土 利 的 女 儿 ， 是 亚 兰 人 拉 班 的 妹 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('680', '1', '25', '21', '以 撒 因 他 妻 子 不 生 育 ， 就 为 她 祈 求 耶 和 华 ； 耶 和 华 应 允 他 的 祈 求 ， 他 的 妻 子 利 百 加 就 怀 了 孕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('681', '1', '25', '22', '孩 子 们 在 她 腹 中 彼 此 相 争 ， 她 就 说 ： “ 若 是 这 样 ， 我 为 什 么 活 着 呢 ｛ 或 译 ： 我 为 什 么 如 此 呢 ｝ ？ ” 她 就 去 求 问 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('682', '1', '25', '23', '耶 和 华 对 她 说 ： 两 国 在 你 腹 内 ； 两 族 要 从 你 身 上 出 来 。 这 族 必 强 于 那 族 ； 将 来 大 的 要 服 事 小 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('683', '1', '25', '24', '生 产 的 日 子 到 了 ， 腹 中 果 然 是 双 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('684', '1', '25', '25', '先 产 的 身 体 发 红 ， 浑 身 有 毛 ， 如 同 皮 衣 ， 他 们 就 给 他 起 名 叫 以 扫 ｛ 就 是 有 毛 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('685', '1', '25', '26', '随 后 又 生 了 以 扫 的 兄 弟 ， 手 抓 住 以 扫 的 脚 跟 ， 因 此 给 他 起 名 叫 雅 各 ｛ 就 是 抓 住 的 意 思 ｝ 。 利 百 加 生 下 两 个 儿 子 的 时 候 ， 以 撒 年 正 六 十 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('686', '1', '25', '27', '＜ 以 扫 出 卖 长 子 的 名 分 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('687', '1', '25', '28', '以 撒 爱 以 扫 ， 因 为 常 吃 他 的 野 味 ； 利 百 加 却 爱 雅 各 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('688', '1', '25', '29', '有 一 天 ， 雅 各 熬 汤 ， 以 扫 从 田 野 回 来 累 昏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('689', '1', '25', '30', '以 扫 对 雅 各 说 ： “ 我 累 昏 了 ， 求 你 把 这 红 汤 给 我 喝 。 ” 因 此 以 扫 又 叫 以 东 ｛ 就 是 红 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('690', '1', '25', '31', '雅 各 说 ： “ 你 今 日 把 长 子 的 名 分 卖 给 我 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('691', '1', '25', '32', '以 扫 说 ： “ 我 将 要 死 ， 这 长 子 的 名 分 于 我 有 什 么 益 处 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('692', '1', '25', '33', '雅 各 说 ： “ 你 今 日 对 我 起 誓 吧 。 ” 以 扫 就 对 他 起 了 誓 ， 把 长 子 的 名 分 卖 给 雅 各 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('693', '1', '25', '34', '于 是 雅 各 将 饼 和 红 豆 汤 给 了 以 扫 ， 以 扫 吃 了 喝 了 ， 便 起 来 走 了 。 这 就 是 以 扫 轻 看 了 他 长 子 的 名 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('694', '1', '26', '1', '＜ 以 撒 住 在 基 拉 耳 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('695', '1', '26', '2', '耶 和 华 向 以 撒 显 现 ， 说 ： “ 你 不 要 下 埃 及 去 ， 要 住 在 我 所 指 示 你 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('696', '1', '26', '3', '你 寄 居 在 这 地 ， 我 必 与 你 同 在 ， 赐 福 给 你 ， 因 为 我 要 将 这 些 地 都 赐 给 你 和 你 的 后 裔 。 我 必 坚 定 我 向 你 父 亚 伯 拉 罕 所 起 的 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('697', '1', '26', '4', '我 要 加 增 你 的 后 裔 ， 像 天 上 的 星 那 样 多 ， 又 要 将 这 些 地 都 赐 给 你 的 后 裔 。 并 且 地 上 万 国 必 因 你 的 后 裔 得 福 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('698', '1', '26', '5', '都 因 亚 伯 拉 罕 听 从 我 的 话 ， 遵 守 我 的 吩 咐 和 我 的 命 令 、 律 例 、 法 度 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('699', '1', '26', '6', '以 撒 就 住 在 基 拉 耳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('700', '1', '26', '7', '那 地 方 的 人 问 到 他 的 妻 子 ， 他 便 说 ： “ 那 是 我 的 妹 子 。 ” 原 来 他 怕 说 ： “ 是 我 的 妻 子 ” ； 他 心 里 想 ： “ 恐 怕 这 地 方 的 人 为 利 百 加 的 缘 故 杀 我 ” ， 因 为 她 容 貌 俊 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('701', '1', '26', '8', '他 在 那 里 住 了 许 久 。 有 一 天 ， 非 利 士 人 的 王 亚 比 米 勒 从 窗 户 里 往 外 观 看 ， 见 以 撒 和 他 的 妻 子 利 百 加 戏 玩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('702', '1', '26', '9', '亚 比 米 勒 召 了 以 撒 来 ， 对 他 说 ： “ 她 实 在 是 你 的 妻 子 ， 你 怎 么 说 她 是 你 的 妹 子 ？ ” 以 撒 说 ： “ 我 心 里 想 ， 恐 怕 我 因 她 而 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('703', '1', '26', '10', '亚 比 米 勒 说 ： “ 你 向 我 们 做 的 是 什 么 事 呢 ？ 民 中 险 些 有 人 和 你 的 妻 同 寝 ， 把 我 们 陷 在 罪 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('704', '1', '26', '11', '于 是 亚 比 米 勒 晓 谕 众 民 说 ： “ 凡 沾 着 这 个 人 ， 或 是 他 妻 子 的 ， 定 要 把 他 治 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('705', '1', '26', '12', '以 撒 在 那 地 耕 种 ， 那 一 年 有 百 倍 的 收 成 。 耶 和 华 赐 福 给 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('706', '1', '26', '13', '他 就 昌 大 ， 日 增 月 盛 ， 成 了 大 富 户 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('707', '1', '26', '14', '他 有 羊 群 牛 群 ， 又 有 许 多 仆 人 ， 非 利 士 人 就 嫉 妒 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('708', '1', '26', '15', '当 他 父 亲 亚 伯 拉 罕 在 世 的 日 子 ， 他 父 亲 的 仆 人 所 挖 的 井 ， 非 利 士 人 全 都 塞 住 ， 填 满 了 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('709', '1', '26', '16', '亚 比 米 勒 对 以 撒 说 ： “ 你 离 开 我 们 去 吧 。 因 为 你 比 我 们 强 盛 得 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('710', '1', '26', '17', '以 撒 就 离 开 那 里 ， 在 基 拉 耳 谷 支 搭 帐 棚 ， 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('711', '1', '26', '18', '当 他 父 亲 亚 伯 拉 罕 在 世 之 日 所 挖 的 水 井 因 非 利 士 人 在 亚 伯 拉 罕 死 后 塞 住 了 ， 以 撒 就 重 新 挖 出 来 ， 仍 照 他 父 亲 所 叫 的 叫 那 些 井 的 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('712', '1', '26', '19', '以 撒 的 仆 人 在 谷 中 挖 井 ， 便 得 了 一 口 活 水 井 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('713', '1', '26', '20', '基 拉 耳 的 牧 人 与 以 撒 的 牧 人 争 竞 ， 说 ： “ 这 水 是 我 们 的 。 ” 以 撒 就 给 那 井 起 名 叫 埃 色 ｛ 就 是 相 敌 的 意 思 ｝ ， 因 为 他 们 和 他 相 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('714', '1', '26', '21', '以 撒 的 仆 人 又 挖 了 一 口 井 ， 他 们 又 为 这 井 争 竞 ， 因 此 以 撒 给 这 井 起 名 叫 西 提 拿 ｛ 就 是 为 敌 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('715', '1', '26', '22', '以 撒 离 开 那 里 ， 又 挖 了 一 口 井 ， 他 们 不 为 这 井 争 竞 了 ， 他 就 给 那 井 起 名 叫 利 河 伯 ｛ 就 是 宽 阔 的 意 思 ｝ 。 他 说 ： “ 耶 和 华 现 在 给 我 们 宽 阔 之 地 ， 我 们 必 在 这 地 昌 盛 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('716', '1', '26', '23', '以 撒 从 那 里 上 别 是 巴 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('717', '1', '26', '24', '当 夜 耶 和 华 向 他 显 现 ， 说 ： “ 我 是 你 父 亲 亚 伯 拉 罕 的 神 ， 不 要 惧 怕 ！ 因 为 我 与 你 同 在 ， 要 赐 福 给 你 ， 并 要 为 我 仆 人 亚 伯 拉 罕 的 缘 故 ， 使 你 的 后 裔 繁 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('718', '1', '26', '25', '以 撒 就 在 那 里 筑 了 一 座 坛 ， 求 告 耶 和 华 的 名 ， 并 且 支 搭 帐 棚 ； 他 的 仆 人 便 在 那 里 挖 了 一 口 井 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('719', '1', '26', '26', '＜ 以 撒 跟 亚 比 米 勒 立 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('720', '1', '26', '27', '以 撒 对 他 们 说 ： “ 你 们 既 然 恨 我 ， 打 发 我 走 了 ， 为 什 么 到 我 这 里 来 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('721', '1', '26', '28', '他 们 说 ： “ 我 们 明 明 地 看 见 耶 和 华 与 你 同 在 ， 便 说 ， 不 如 我 们 两 下 彼 此 起 誓 ， 彼 此 立 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('722', '1', '26', '29', '使 你 不 害 我 们 ， 正 如 我 们 未 曾 害 你 ， 一 味 地 厚 待 你 ， 并 且 打 发 你 平 平 安 安 地 走 。 你 是 蒙 耶 和 华 赐 福 的 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('723', '1', '26', '30', '以 撒 就 为 他 们 设 摆 筵 席 ， 他 们 便 吃 了 喝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('724', '1', '26', '31', '他 们 清 早 起 来 彼 此 起 誓 。 以 撒 打 发 他 们 走 ， 他 们 就 平 平 安 安 地 离 开 他 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('725', '1', '26', '32', '那 一 天 ， 以 撒 的 仆 人 来 ， 将 挖 井 的 事 告 诉 他 说 ： “ 我 们 得 了 水 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('726', '1', '26', '33', '他 就 给 那 井 起 名 叫 示 巴 ； 因 此 那 城 叫 做 别 是 巴 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('727', '1', '26', '34', '＜ 以 扫 的 外 族 妻 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('728', '1', '26', '35', '她 们 常 使 以 撒 和 利 百 加 心 里 愁 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('729', '1', '27', '1', '＜ 以 撒 祝 福 雅 各 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('730', '1', '27', '2', '他 说 ： “ 我 如 今 老 了 ， 不 知 道 那 一 天 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('731', '1', '27', '3', '现 在 拿 你 的 器 械 ， 就 是 箭 囊 和 弓 ， 往 田 野 去 为 我 打 猎 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('732', '1', '27', '4', '照 我 所 爱 的 做 成 美 味 ， 拿 来 给 我 吃 ， 使 我 在 未 死 之 先 给 你 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('733', '1', '27', '5', '以 撒 对 他 儿 子 以 扫 说 话 ， 利 百 加 也 听 见 了 。 以 扫 往 田 野 去 打 猎 ， 要 得 野 味 带 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('734', '1', '27', '6', '利 百 加 就 对 她 儿 子 雅 各 说 ： “ 我 听 见 你 父 亲 对 你 哥 哥 以 扫 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('735', '1', '27', '7', '‘ 你 去 把 野 兽 带 来 ， 做 成 美 味 给 我 吃 ， 我 好 在 未 死 之 先 ， 在 耶 和 华 面 前 给 你 祝 福 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('736', '1', '27', '8', '现 在 ， 我 儿 ， 你 要 照 着 我 所 吩 咐 你 的 ， 听 从 我 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('737', '1', '27', '9', '你 到 羊 群 里 去 ， 给 我 拿 两 只 肥 山 羊 羔 来 ， 我 便 照 你 父 亲 所 爱 的 给 他 做 成 美 味 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('738', '1', '27', '10', '你 拿 到 你 父 亲 那 里 给 他 吃 ， 使 他 在 未 死 之 先 给 你 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('739', '1', '27', '11', '雅 各 对 他 母 亲 利 百 加 说 ： “ 我 哥 哥 以 扫 浑 身 是 有 毛 的 ， 我 身 上 是 光 滑 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('740', '1', '27', '12', '倘 若 我 父 亲 摸 着 我 ， 必 以 我 为 欺 哄 人 的 ， 我 就 招 咒 诅 ， 不 得 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('741', '1', '27', '13', '他 母 亲 对 他 说 ： “ 我 儿 ， 你 招 的 咒 诅 归 到 我 身 上 ； 你 只 管 听 我 的 话 ， 去 把 羊 羔 给 我 拿 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('742', '1', '27', '14', '他 便 去 拿 来 ， 交 给 他 母 亲 ； 他 母 亲 就 照 他 父 亲 所 爱 的 做 成 美 味 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('743', '1', '27', '15', '利 百 加 又 把 家 里 所 存 大 儿 子 以 扫 上 好 的 衣 服 给 她 小 儿 子 雅 各 穿 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('744', '1', '27', '16', '又 用 山 羊 羔 皮 包 在 雅 各 的 手 上 和 颈 项 的 光 滑 处 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('745', '1', '27', '17', '就 把 所 做 的 美 味 和 饼 交 在 她 儿 子 雅 各 的 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('746', '1', '27', '18', '雅 各 到 他 父 亲 那 里 说 ： “ 我 父 亲 ！ ” 他 说 ： “ 我 在 这 里 。 我 儿 ， 你 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('747', '1', '27', '19', '雅 各 对 他 父 亲 说 ： “ 我 是 你 的 长 子 以 扫 ； 我 已 照 你 所 吩 咐 我 的 行 了 。 请 起 来 坐 着 ， 吃 我 的 野 味 ， 好 给 我 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('748', '1', '27', '20', '以 撒 对 他 儿 子 说 ： “ 我 儿 ， 你 如 何 找 得 这 么 快 呢 ？ ” 他 说 ： “ 因 为 耶 和 华 ─ ─ 你 的 神 使 我 遇 见 好 机 会 得 着 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('749', '1', '27', '21', '以 撒 对 雅 各 说 ： “ 我 儿 ， 你 近 前 来 ， 我 摸 摸 你 ， 知 道 你 真 是 我 的 儿 子 以 扫 不 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('750', '1', '27', '22', '雅 各 就 挨 近 他 父 亲 以 撒 。 以 撒 摸 着 他 ， 说 ： “ 声 音 是 雅 各 的 声 音 ， 手 却 是 以 扫 的 手 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('751', '1', '27', '23', '以 撒 就 辨 不 出 他 来 ； 因 为 他 手 上 有 毛 ， 像 他 哥 哥 以 扫 的 手 一 样 ， 就 给 他 祝 福 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('752', '1', '27', '24', '又 说 ： “ 你 真 是 我 儿 子 以 扫 吗 ？ ” 他 说 ： “ 我 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('753', '1', '27', '25', '以 撒 说 ： “ 你 递 给 我 ， 我 好 吃 我 儿 子 的 野 味 ， 给 你 祝 福 。 ” 雅 各 就 递 给 他 ， 他 便 吃 了 ， 又 拿 酒 给 他 ， 他 也 喝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('754', '1', '27', '26', '他 父 亲 以 撒 对 他 说 ： “ 我 儿 ， 你 上 前 来 与 我 亲 嘴 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('755', '1', '27', '27', '他 就 上 前 与 父 亲 亲 嘴 。 他 父 亲 一 闻 他 衣 服 上 的 香 气 ， 就 给 他 祝 福 ， 说 ： 我 儿 的 香 气 如 同 耶 和 华 赐 福 之 田 地 的 香 气 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('756', '1', '27', '28', '愿 神 赐 你 天 上 的 甘 露 ， 地 上 的 肥 土 ， 并 许 多 五 谷 新 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('757', '1', '27', '29', '愿 多 民 事 奉 你 ， 多 国 跪 拜 你 。 愿 你 作 你 弟 兄 的 主 ； 你 母 亲 的 儿 子 向 你 跪 拜 。 凡 咒 诅 你 的 ， 愿 他 受 咒 诅 ； 为 你 祝 福 的 ， 愿 他 蒙 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('758', '1', '27', '30', '＜ 以 扫 求 以 撒 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('759', '1', '27', '31', '也 做 了 美 味 ， 拿 来 给 他 父 亲 ， 说 ： “ 请 父 亲 起 来 ， 吃 你 儿 子 的 野 味 ， 好 给 我 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('760', '1', '27', '32', '他 父 亲 以 撒 对 他 说 ： “ 你 是 谁 ？ ” 他 说 ： “ 我 是 你 的 长 子 以 扫 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('761', '1', '27', '33', '以 撒 就 大 大 地 战 兢 ， 说 ： “ 你 未 来 之 先 ， 是 谁 得 了 野 味 拿 来 给 我 呢 ？ 我 已 经 吃 了 ， 为 他 祝 福 ； 他 将 来 也 必 蒙 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('762', '1', '27', '34', '以 扫 听 了 他 父 亲 的 话 ， 就 放 声 痛 哭 ， 说 ： “ 我 父 啊 ， 求 你 也 为 我 祝 福 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('763', '1', '27', '35', '以 撒 说 ： “ 你 兄 弟 已 经 用 诡 计 来 将 你 的 福 分 夺 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('764', '1', '27', '36', '以 扫 说 ： “ 他 名 雅 各 ， 岂 不 是 正 对 吗 ？ 因 为 他 欺 骗 了 我 两 次 ： 他 从 前 夺 了 我 长 子 的 名 分 ， 你 看 ， 他 现 在 又 夺 了 我 的 福 分 。 ” 以 扫 又 说 ： “ 你 没 有 留 下 为 我 可 祝 的 福 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('765', '1', '27', '37', '以 撒 回 答 以 扫 说 ： “ 我 已 立 他 为 你 的 主 ， 使 他 的 弟 兄 都 给 他 作 仆 人 ， 并 赐 他 五 谷 新 酒 可 以 养 生 。 我 儿 ， 现 在 我 还 能 为 你 做 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('766', '1', '27', '38', '以 扫 对 他 父 亲 说 ： “ 父 啊 ， 你 只 有 一 样 可 祝 的 福 吗 ？ 我 父 啊 ， 求 你 也 为 我 祝 福 ！ ” 以 扫 就 放 声 而 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('767', '1', '27', '39', '他 父 亲 以 撒 说 ： 地 上 的 肥 土 必 为 你 所 住 ； 天 上 的 甘 露 必 为 你 所 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('768', '1', '27', '40', '你 必 倚 靠 刀 剑 度 日 ， 又 必 事 奉 你 的 兄 弟 ； 到 你 强 盛 的 时 候 ， 必 从 你 颈 项 上 挣 开 他 的 轭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('769', '1', '27', '41', '以 扫 因 他 父 亲 给 雅 各 祝 的 福 ， 就 怨 恨 雅 各 ， 心 里 说 ： “ 为 我 父 亲 居 丧 的 日 子 近 了 ， 到 那 时 候 ， 我 要 杀 我 的 兄 弟 雅 各 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('770', '1', '27', '42', '有 人 把 利 百 加 大 儿 子 以 扫 的 话 告 诉 利 百 加 ， 她 就 打 发 人 去 ， 叫 了 她 小 儿 子 雅 各 来 ， 对 他 说 ： “ 你 哥 哥 以 扫 想 要 杀 你 ， 报 仇 雪 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('771', '1', '27', '43', '现 在 ， 我 儿 ， 你 要 听 我 的 话 ： 起 来 ， 逃 往 哈 兰 、 我 哥 哥 拉 班 那 里 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('772', '1', '27', '44', '同 他 住 些 日 子 ， 直 等 你 哥 哥 的 怒 气 消 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('773', '1', '27', '45', '你 哥 哥 向 你 消 了 怒 气 ， 忘 了 你 向 他 所 做 的 事 ， 我 便 打 发 人 去 把 你 从 那 里 带 回 来 。 为 什 么 一 日 丧 你 们 二 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('774', '1', '27', '46', '＜ 以 撒 打 发 雅 各 到 拉 班 的 家 去 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('775', '1', '28', '1', '以 撒 叫 了 雅 各 来 ， 给 他 祝 福 ， 并 嘱 咐 他 说 ： “ 你 不 要 娶 迦 南 的 女 子 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('776', '1', '28', '2', '你 起 身 往 巴 旦 ． 亚 兰 去 ， 到 你 外 祖 彼 土 利 家 里 ， 在 你 母 舅 拉 班 的 女 儿 中 娶 一 女 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('777', '1', '28', '3', '愿 全 能 的 神 赐 福 给 你 ， 使 你 生 养 众 多 ， 成 为 多 族 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('778', '1', '28', '4', '将 应 许 亚 伯 拉 罕 的 福 赐 给 你 和 你 的 后 裔 ， 使 你 承 受 你 所 寄 居 的 地 为 业 ， 就 是 神 赐 给 亚 伯 拉 罕 的 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('779', '1', '28', '5', '以 撒 打 发 雅 各 走 了 ， 他 就 往 巴 旦 ． 亚 兰 去 ， 到 亚 兰 人 彼 土 利 的 儿 子 拉 班 那 里 。 拉 班 是 雅 各 、 以 扫 的 母 舅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('780', '1', '28', '6', '＜ 以 扫 另 娶 一 妻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('781', '1', '28', '7', '又 见 雅 各 听 从 父 母 的 话 往 巴 旦 ． 亚 兰 去 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('782', '1', '28', '8', '以 扫 就 晓 得 他 父 亲 以 撒 看 不 中 迦 南 的 女 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('783', '1', '28', '9', '便 往 以 实 玛 利 那 里 去 ， 在 他 二 妻 之 外 又 娶 了 玛 哈 拉 为 妻 。 她 是 亚 伯 拉 罕 儿 子 以 实 玛 利 的 女 儿 ， 尼 拜 约 的 妹 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('784', '1', '28', '10', '＜ 雅 各 在 伯 特 利 做 的 梦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('785', '1', '28', '11', '到 了 一 个 地 方 ， 因 为 太 阳 落 了 ， 就 在 那 里 住 宿 ， 便 拾 起 那 地 方 的 一 块 石 头 枕 在 头 下 ， 在 那 里 躺 卧 睡 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('786', '1', '28', '12', '梦 见 一 个 梯 子 立 在 地 上 ， 梯 子 的 头 顶 着 天 ， 有 神 的 使 者 在 梯 子 上 ， 上 去 下 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('787', '1', '28', '13', '耶 和 华 站 在 梯 子 以 上 ｛ 或 译 ： 站 在 他 旁 边 ｝ ， 说 ： “ 我 是 耶 和 华 ─ ─ 你 祖 亚 伯 拉 罕 的 神 ， 也 是 以 撒 的 神 ； 我 要 将 你 现 在 所 躺 卧 之 地 赐 给 你 和 你 的 后 裔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('788', '1', '28', '14', '你 的 后 裔 必 像 地 上 的 尘 沙 那 样 多 ， 必 向 东 西 南 北 开 展 ； 地 上 万 族 必 因 你 和 你 的 后 裔 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('789', '1', '28', '15', '我 也 与 你 同 在 。 你 无 论 往 哪 里 去 ， 我 必 保 佑 你 ， 领 你 归 回 这 地 ， 总 不 离 弃 你 ， 直 到 我 成 全 了 向 你 所 应 许 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('790', '1', '28', '16', '雅 各 睡 醒 了 ， 说 ： “ 耶 和 华 真 在 这 里 ， 我 竟 不 知 道 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('791', '1', '28', '17', '就 惧 怕 ， 说 ： “ 这 地 方 何 等 可 畏 ！ 这 不 是 别 的 ， 乃 是 神 的 殿 ， 也 是 天 的 门 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('792', '1', '28', '18', '雅 各 清 早 起 来 ， 把 所 枕 的 石 头 立 作 柱 子 ， 浇 油 在 上 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('793', '1', '28', '19', '他 就 给 那 地 方 起 名 叫 伯 特 利 ｛ 就 是 神 殿 的 意 思 ｝ ； 但 那 地 方 起 先 名 叫 路 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('794', '1', '28', '20', '雅 各 许 愿 说 ： “ 神 若 与 我 同 在 ， 在 我 所 行 的 路 上 保 佑 我 ， 又 给 我 食 物 吃 ， 衣 服 穿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('795', '1', '28', '21', '使 我 平 平 安 安 地 回 到 我 父 亲 的 家 ， 我 就 必 以 耶 和 华 为 我 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('796', '1', '28', '22', '我 所 立 为 柱 子 的 石 头 也 必 作 神 的 殿 ； 凡 你 所 赐 给 我 的 ， 我 必 将 十 分 之 一 献 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('797', '1', '29', '1', '＜ 雅 各 到 了 拉 班 的 家 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('798', '1', '29', '2', '看 见 田 间 有 一 口 井 ， 有 三 群 羊 卧 在 井 旁 ； 因 为 人 饮 羊 群 都 是 用 那 井 里 的 水 。 井 口 上 的 石 头 是 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('799', '1', '29', '3', '常 有 羊 群 在 那 里 聚 集 ， 牧 人 把 石 头 转 离 井 口 饮 羊 ， 随 后 又 把 石 头 放 在 井 口 的 原 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('800', '1', '29', '4', '雅 各 对 牧 人 说 ： “ 弟 兄 们 ， 你 们 是 哪 里 来 的 ？ ” 他 们 说 ： “ 我 们 是 哈 兰 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('801', '1', '29', '5', '他 问 他 们 说 ： “ 拿 鹤 的 孙 子 拉 班 ， 你 们 认 识 吗 ？ ” 他 们 说 ： “ 我 们 认 识 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('802', '1', '29', '6', '雅 各 说 ： “ 他 平 安 吗 ？ ” 他 们 说 ： “ 平 安 。 看 哪 ， 他 女 儿 拉 结 领 着 羊 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('803', '1', '29', '7', '雅 各 说 ： “ 日 头 还 高 ， 不 是 羊 群 聚 集 的 时 候 ， 你 们 不 如 饮 羊 ， 再 去 放 一 放 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('804', '1', '29', '8', '他 们 说 ： “ 我 们 不 能 ， 必 等 羊 群 聚 齐 ， 人 把 石 头 转 离 井 口 才 可 饮 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('805', '1', '29', '9', '雅 各 正 和 他 们 说 话 的 时 候 ， 拉 结 领 着 她 父 亲 的 羊 来 了 ， 因 为 那 些 羊 是 她 牧 放 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('806', '1', '29', '10', '雅 各 看 见 母 舅 拉 班 的 女 儿 拉 结 和 母 舅 拉 班 的 羊 群 ， 就 上 前 把 石 头 转 离 井 口 ， 饮 他 母 舅 拉 班 的 羊 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('807', '1', '29', '11', '雅 各 与 拉 结 亲 嘴 ， 就 放 声 而 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('808', '1', '29', '12', '雅 各 告 诉 拉 结 ， 自 己 是 她 父 亲 的 外 甥 ， 是 利 百 加 的 儿 子 ， 拉 结 就 跑 去 告 诉 她 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('809', '1', '29', '13', '拉 班 听 见 外 甥 雅 各 的 信 息 ， 就 跑 去 迎 接 ， 抱 着 他 ， 与 他 亲 嘴 ， 领 他 到 自 己 的 家 。 雅 各 将 一 切 的 情 由 告 诉 拉 班 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('810', '1', '29', '14', '拉 班 对 他 说 ： “ 你 实 在 是 我 的 骨 肉 。 ” 雅 各 就 和 他 同 住 了 一 个 月 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('811', '1', '29', '15', '＜ 雅 各 为 拉 结 和 利 亚 服 事 拉 班 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('812', '1', '29', '16', '拉 班 有 两 个 女 儿 ， 大 的 名 叫 利 亚 ， 小 的 名 叫 拉 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('813', '1', '29', '17', '利 亚 的 眼 睛 没 有 神 气 ， 拉 结 却 生 得 美 貌 俊 秀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('814', '1', '29', '18', '雅 各 爱 拉 结 ， 就 说 ： “ 我 愿 为 你 小 女 儿 拉 结 服 事 你 七 年 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('815', '1', '29', '19', '拉 班 说 ： “ 我 把 她 给 你 ， 胜 似 给 别 人 ， 你 与 我 同 住 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('816', '1', '29', '20', '雅 各 就 为 拉 结 服 事 了 七 年 ； 他 因 为 深 爱 拉 结 ， 就 看 这 七 年 如 同 几 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('817', '1', '29', '21', '雅 各 对 拉 班 说 ： “ 日 期 已 经 满 了 ， 求 你 把 我 的 妻 子 给 我 ， 我 好 与 她 同 房 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('818', '1', '29', '22', '拉 班 就 摆 设 筵 席 ， 请 齐 了 那 地 方 的 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('819', '1', '29', '23', '到 晚 上 ， 拉 班 将 女 儿 利 亚 送 来 给 雅 各 ， 雅 各 就 与 她 同 房 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('820', '1', '29', '24', '拉 班 又 将 婢 女 悉 帕 给 女 儿 利 亚 作 使 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('821', '1', '29', '25', '到 了 早 晨 ， 雅 各 一 看 是 利 亚 ， 就 对 拉 班 说 ： “ 你 向 我 做 的 是 什 么 事 呢 ？ 我 服 事 你 ， 不 是 为 拉 结 吗 ？ 你 为 什 么 欺 哄 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('822', '1', '29', '26', '拉 班 说 ： “ 大 女 儿 还 没 有 给 人 ， 先 把 小 女 儿 给 人 ， 在 我 们 这 地 方 没 有 这 规 矩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('823', '1', '29', '27', '你 为 这 个 满 了 七 日 ， 我 就 把 那 个 也 给 你 ， 你 再 为 她 服 事 我 七 年 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('824', '1', '29', '28', '雅 各 就 如 此 行 。 满 了 利 亚 的 七 日 ， 拉 班 便 将 女 儿 拉 结 给 雅 各 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('825', '1', '29', '29', '拉 班 又 将 婢 女 辟 拉 给 女 儿 拉 结 作 使 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('826', '1', '29', '30', '雅 各 也 与 拉 结 同 房 ， 并 且 爱 拉 结 胜 似 爱 利 亚 ， 于 是 又 服 事 了 拉 班 七 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('827', '1', '29', '31', '＜ 雅 各 的 儿 女 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('828', '1', '29', '32', '利 亚 怀 孕 生 子 ， 就 给 他 起 名 叫 吕 便 ｛ 就 是 有 儿 子 的 意 思 ｝ ， 因 而 说 ： “ 耶 和 华 看 见 我 的 苦 情 ， 如 今 我 的 丈 夫 必 爱 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('829', '1', '29', '33', '她 又 怀 孕 生 子 ， 就 说 ： “ 耶 和 华 因 为 听 见 我 失 宠 ， 所 以 又 赐 给 我 这 个 儿 子 ” ， 于 是 给 他 起 名 叫 西 缅 ｛ 就 是 听 见 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('830', '1', '29', '34', '她 又 怀 孕 生 子 ， 起 名 叫 利 未 ｛ 就 是 联 合 的 意 思 ｝ ， 说 ： “ 我 给 丈 夫 生 了 三 个 儿 子 ， 他 必 与 我 联 合 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('831', '1', '29', '35', '她 又 怀 孕 生 子 ， 说 ： “ 这 回 我 要 赞 美 耶 和 华 ” ， 因 此 给 他 起 名 叫 犹 大 ｛ 就 是 赞 美 的 意 思 ｝ 。 这 才 停 了 生 育 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('832', '1', '30', '1', '拉 结 见 自 己 不 给 雅 各 生 子 ， 就 嫉 妒 她 姊 姊 ， 对 雅 各 说 ： “ 你 给 我 孩 子 ， 不 然 我 就 死 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('833', '1', '30', '2', '雅 各 向 拉 结 生 气 ， 说 ： “ 叫 你 不 生 育 的 是 神 ， 我 岂 能 代 替 他 作 主 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('834', '1', '30', '3', '拉 结 说 ： “ 有 我 的 使 女 辟 拉 在 这 里 ， 你 可 以 与 她 同 房 ， 使 她 生 子 在 我 膝 下 ， 我 便 因 她 也 得 孩 子 ｛ 原 文 是 被 建 立 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('835', '1', '30', '4', '拉 结 就 把 她 的 使 女 辟 拉 给 丈 夫 为 妾 ； 雅 各 便 与 她 同 房 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('836', '1', '30', '5', '辟 拉 就 怀 孕 ， 给 雅 各 生 了 一 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('837', '1', '30', '6', '拉 结 说 ： “ 神 伸 了 我 的 冤 ， 也 听 了 我 的 声 音 ， 赐 我 一 个 儿 子 ” ， 因 此 给 他 起 名 叫 但 ｛ 就 是 伸 冤 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('838', '1', '30', '7', '拉 结 的 使 女 辟 拉 又 怀 孕 ， 给 雅 各 生 了 第 二 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('839', '1', '30', '8', '拉 结 说 ： “ 我 与 我 姊 姊 大 大 相 争 ， 并 且 得 胜 ” ， 于 是 给 他 起 名 叫 拿 弗 他 利 ｛ 就 是 相 争 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('840', '1', '30', '9', '利 亚 见 自 己 停 了 生 育 ， 就 把 使 女 悉 帕 给 雅 各 为 妾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('841', '1', '30', '10', '利 亚 的 使 女 悉 帕 给 雅 各 生 了 一 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('842', '1', '30', '11', '利 亚 说 ： “ 万 幸 ！ ” 于 是 给 他 起 名 叫 迦 得 ｛ 就 是 万 幸 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('843', '1', '30', '12', '利 亚 的 使 女 悉 帕 又 给 雅 各 生 了 第 二 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('844', '1', '30', '13', '利 亚 说 ： “ 我 有 福 啊 ， 众 女 子 都 要 称 我 是 有 福 的 ” ， 于 是 给 他 起 名 叫 亚 设 ｛ 就 是 有 福 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('845', '1', '30', '14', '割 麦 子 的 时 候 ， 吕 便 往 田 里 去 ， 寻 见 风 茄 ， 拿 来 给 他 母 亲 利 亚 。 拉 结 对 利 亚 说 ： “ 请 你 把 你 儿 子 的 风 茄 给 我 些 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('846', '1', '30', '15', '利 亚 说 ： “ 你 夺 了 我 的 丈 夫 还 算 小 事 吗 ？ 你 又 要 夺 我 儿 子 的 风 茄 吗 ？ ” 拉 结 说 ： “ 为 你 儿 子 的 风 茄 ， 今 夜 他 可 以 与 你 同 寝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('847', '1', '30', '16', '到 了 晚 上 ， 雅 各 从 田 里 回 来 ， 利 亚 出 来 迎 接 他 ， 说 ： “ 你 要 与 我 同 寝 ， 因 为 我 实 在 用 我 儿 子 的 风 茄 把 你 雇 下 了 。 ” 那 一 夜 ， 雅 各 就 与 她 同 寝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('848', '1', '30', '17', '神 应 允 了 利 亚 ， 她 就 怀 孕 ， 给 雅 各 生 了 第 五 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('849', '1', '30', '18', '利 亚 说 ： “ 神 给 了 我 价 值 ， 因 为 我 把 使 女 给 了 我 丈 夫 ” ， 于 是 给 他 起 名 叫 以 萨 迦 ｛ 就 是 价 值 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('850', '1', '30', '19', '利 亚 又 怀 孕 ， 给 雅 各 生 了 第 六 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('851', '1', '30', '20', '利 亚 说 ： “ 神 赐 我 厚 赏 ； 我 丈 夫 必 与 我 同 住 ， 因 我 给 他 生 了 六 个 儿 子 ” ， 于 是 给 他 起 名 西 布 伦 ｛ 就 是 同 住 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('852', '1', '30', '21', '后 来 又 生 了 一 个 女 儿 ， 给 她 起 名 叫 底 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('853', '1', '30', '22', '神 顾 念 拉 结 ， 应 允 了 她 ， 使 她 能 生 育 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('854', '1', '30', '23', '拉 结 怀 孕 生 子 ， 说 ： “ 神 除 去 了 我 的 羞 耻 ” ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('855', '1', '30', '24', '就 给 他 起 名 叫 约 瑟 ｛ 就 是 增 添 的 意 思 ｝ ， 意 思 说 ： “ 愿 耶 和 华 再 增 添 我 一 个 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('856', '1', '30', '25', '＜ 雅 各 和 拉 班 定 工 价 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('857', '1', '30', '26', '请 你 把 我 服 事 你 所 得 的 妻 子 和 儿 女 给 我 ， 让 我 走 ； 我 怎 样 服 事 你 ， 你 都 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('858', '1', '30', '27', '拉 班 对 他 说 ： “ 我 若 在 你 眼 前 蒙 恩 ， 请 你 仍 与 我 同 住 ， 因 为 我 已 算 定 ， 耶 和 华 赐 福 与 我 是 为 你 的 缘 故 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('859', '1', '30', '28', '又 说 ： “ 请 你 定 你 的 工 价 ， 我 就 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('860', '1', '30', '29', '雅 各 对 他 说 ： “ 我 怎 样 服 事 你 ， 你 的 牲 畜 在 我 手 里 怎 样 ， 是 你 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('861', '1', '30', '30', '我 未 来 之 先 ， 你 所 有 的 很 少 ， 现 今 却 发 大 众 多 ， 耶 和 华 随 我 的 脚 步 赐 福 与 你 。 如 今 ， 我 什 么 时 候 才 为 自 己 兴 家 立 业 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('862', '1', '30', '31', '拉 班 说 ： “ 我 当 给 你 什 么 呢 ？ ” 雅 各 说 ： “ 什 么 你 也 不 必 给 我 ， 只 有 一 件 事 ， 你 若 应 承 ， 我 便 仍 旧 牧 放 你 的 羊 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('863', '1', '30', '32', '今 天 我 要 走 遍 你 的 羊 群 ， 把 绵 羊 中 凡 有 点 的 、 有 斑 的 ， 和 黑 色 的 ， 并 山 羊 中 凡 有 斑 的 、 有 点 的 ， 都 挑 出 来 ； 将 来 这 一 等 的 就 算 我 的 工 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('864', '1', '30', '33', '以 后 你 来 查 看 我 的 工 价 ， 凡 在 我 手 里 的 山 羊 不 是 有 点 有 斑 的 ， 绵 羊 不 是 黑 色 的 ， 那 就 算 是 我 偷 的 ； 这 样 便 可 证 出 我 的 公 义 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('865', '1', '30', '34', '拉 班 说 ： “ 好 啊 ！ 我 情 愿 照 着 你 的 话 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('866', '1', '30', '35', '当 日 ， 拉 班 把 有 纹 的 、 有 斑 的 公 山 羊 ， 有 点 的 、 有 斑 的 、 有 杂 白 纹 的 母 山 羊 ， 并 黑 色 的 绵 羊 ， 都 挑 出 来 ， 交 在 他 儿 子 们 的 手 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('867', '1', '30', '36', '又 使 自 己 和 雅 各 相 离 三 天 的 路 程 。 雅 各 就 牧 养 拉 班 其 余 的 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('868', '1', '30', '37', '雅 各 拿 杨 树 、 杏 树 、 枫 树 的 嫩 枝 ， 将 皮 剥 成 白 纹 ， 使 枝 子 露 出 白 的 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('869', '1', '30', '38', '将 剥 了 皮 的 枝 子 ， 对 着 羊 群 ， 插 在 饮 羊 的 水 沟 里 和 水 槽 里 ， 羊 来 喝 的 时 候 ， 牝 牡 配 合 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('870', '1', '30', '39', '羊 对 着 枝 子 配 合 ， 就 生 下 有 纹 的 、 有 点 的 、 有 斑 的 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('871', '1', '30', '40', '雅 各 把 羊 羔 分 出 来 ， 使 拉 班 的 羊 与 这 有 纹 和 黑 色 的 羊 相 对 ， 把 自 己 的 羊 另 放 一 处 ， 不 叫 他 和 拉 班 的 羊 混 杂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('872', '1', '30', '41', '到 羊 群 肥 壮 配 合 的 时 候 ， 雅 各 就 把 枝 子 插 在 水 沟 里 ， 使 羊 对 着 枝 子 配 合 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('873', '1', '30', '42', '只 是 到 羊 瘦 弱 配 合 的 时 候 就 不 插 枝 子 。 这 样 ， 瘦 弱 的 就 归 拉 班 ， 肥 壮 的 就 归 雅 各 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('874', '1', '30', '43', '于 是 雅 各 极 其 发 大 ， 得 了 许 多 的 羊 群 、 仆 婢 、 骆 驼 ， 和 驴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('875', '1', '31', '1', '＜ 雅 各 逃 离 拉 班 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('876', '1', '31', '2', '雅 各 见 拉 班 的 气 色 向 他 不 如 从 前 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('877', '1', '31', '3', '耶 和 华 对 雅 各 说 ： “ 你 要 回 你 祖 、 你 父 之 地 ， 到 你 亲 族 那 里 去 ， 我 必 与 你 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('878', '1', '31', '4', '雅 各 就 打 发 人 ， 叫 拉 结 和 利 亚 到 田 野 羊 群 那 里 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('879', '1', '31', '5', '对 她 们 说 ： “ 我 看 你 们 父 亲 的 气 色 向 我 不 如 从 前 了 ； 但 我 父 亲 的 神 向 来 与 我 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('880', '1', '31', '6', '你 们 也 知 道 ， 我 尽 了 我 的 力 量 服 事 你 们 的 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('881', '1', '31', '7', '你 们 的 父 亲 欺 哄 我 ， 十 次 改 了 我 的 工 价 ； 然 而 神 不 容 他 害 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('882', '1', '31', '8', '他 若 说 ： ‘ 有 点 的 归 你 作 工 价 ’ ， 羊 群 所 生 的 都 有 点 ； 他 若 说 ： ‘ 有 纹 的 归 你 作 工 价 ’ ， 羊 群 所 生 的 都 有 纹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('883', '1', '31', '9', '这 样 ， 神 把 你 们 父 亲 的 牲 畜 夺 来 赐 给 我 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('884', '1', '31', '10', '羊 配 合 的 时 候 ， 我 梦 中 举 目 一 看 ， 见 跳 母 羊 的 公 羊 都 是 有 纹 的 、 有 点 的 、 有 花 斑 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('885', '1', '31', '11', '神 的 使 者 在 那 梦 中 呼 叫 我 说 ： ‘ 雅 各 。 ’ 我 说 ： ‘ 我 在 这 里 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('886', '1', '31', '12', '他 说 ： ‘ 你 举 目 观 看 ， 跳 母 羊 的 公 羊 都 是 有 纹 的 、 有 点 的 、 有 花 斑 的 ； 凡 拉 班 向 你 所 做 的 ， 我 都 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('887', '1', '31', '13', '我 是 伯 特 利 的 神 ； 你 在 那 里 用 油 浇 过 柱 子 ， 向 我 许 过 愿 。 现 今 你 起 来 ， 离 开 这 地 ， 回 你 本 地 去 吧 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('888', '1', '31', '14', '拉 结 和 利 亚 回 答 雅 各 说 ： “ 在 我 们 父 亲 的 家 里 还 有 我 们 可 得 的 分 吗 ？ 还 有 我 们 的 产 业 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('889', '1', '31', '15', '我 们 不 是 被 他 当 作 外 人 吗 ？ 因 为 他 卖 了 我 们 ， 吞 了 我 们 的 价 值 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('890', '1', '31', '16', '神 从 我 们 父 亲 所 夺 出 来 的 一 切 财 物 ， 那 就 是 我 们 和 我 们 孩 子 们 的 。 现 今 凡 神 所 吩 咐 你 的 ， 你 只 管 去 行 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('891', '1', '31', '17', '雅 各 起 来 ， 使 他 的 儿 子 和 妻 子 都 骑 上 骆 驼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('892', '1', '31', '18', '又 带 着 他 在 巴 旦 ． 亚 兰 所 得 的 一 切 牲 畜 和 财 物 ， 往 迦 南 地 、 他 父 亲 以 撒 那 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('893', '1', '31', '19', '当 时 拉 班 剪 羊 毛 去 了 ， 拉 结 偷 了 他 父 亲 家 中 的 神 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('894', '1', '31', '20', '雅 各 背 着 亚 兰 人 拉 班 偷 走 了 ， 并 不 告 诉 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('895', '1', '31', '21', '就 带 着 所 有 的 逃 跑 。 他 起 身 过 大 河 ， 面 向 基 列 山 行 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('896', '1', '31', '22', '＜ 拉 班 追 赶 雅 各 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('897', '1', '31', '23', '拉 班 带 领 他 的 众 弟 兄 去 追 赶 ， 追 了 七 日 ， 在 基 列 山 就 追 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('898', '1', '31', '24', '夜 间 ， 神 到 亚 兰 人 拉 班 那 里 ， 在 梦 中 对 他 说 ： “ 你 要 小 心 ， 不 可 与 雅 各 说 好 说 歹 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('899', '1', '31', '25', '拉 班 追 上 雅 各 。 雅 各 在 山 上 支 搭 帐 棚 ； 拉 班 和 他 的 众 弟 兄 也 在 基 列 山 上 支 搭 帐 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('900', '1', '31', '26', '拉 班 对 雅 各 说 ： “ 你 做 的 是 什 么 事 呢 ？ 你 背 着 我 偷 走 了 ， 又 把 我 的 女 儿 们 带 了 去 ， 如 同 用 刀 剑 掳 去 的 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('901', '1', '31', '27', '你 为 什 么 暗 暗 地 逃 跑 ， 偷 着 走 ， 并 不 告 诉 我 ， 叫 我 可 以 欢 乐 、 唱 歌 、 击 鼓 、 弹 琴 地 送 你 回 去 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('902', '1', '31', '28', '又 不 容 我 与 外 孙 和 女 儿 亲 嘴 ？ 你 所 行 的 真 是 愚 昧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('903', '1', '31', '29', '我 手 中 原 有 能 力 害 你 ， 只 是 你 父 亲 的 神 昨 夜 对 我 说 ： ‘ 你 要 小 心 ， 不 可 与 雅 各 说 好 说 歹 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('904', '1', '31', '30', '现 在 你 虽 然 想 你 父 家 ， 不 得 不 去 ， 为 什 么 又 偷 了 我 的 神 像 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('905', '1', '31', '31', '雅 各 回 答 拉 班 说 ： “ 恐 怕 你 把 你 的 女 儿 从 我 夺 去 ， 所 以 我 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('906', '1', '31', '32', '至 于 你 的 神 像 ， 你 在 谁 那 里 搜 出 来 ， 就 不 容 谁 存 活 。 当 着 我 们 的 众 弟 兄 ， 你 认 一 认 ， 在 我 这 里 有 什 么 东 西 是 你 的 ， 就 拿 去 。 ” 原 来 雅 各 不 知 道 拉 结 偷 了 那 些 神 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('907', '1', '31', '33', '拉 班 进 了 雅 各 、 利 亚 ， 并 两 个 使 女 的 帐 棚 ， 都 没 有 搜 出 来 ， 就 从 利 亚 的 帐 棚 出 来 ， 进 了 拉 结 的 帐 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('908', '1', '31', '34', '拉 结 已 经 把 神 像 藏 在 骆 驼 的 驮 篓 里 ， 便 坐 在 上 头 。 拉 班 摸 遍 了 那 帐 棚 ， 并 没 有 摸 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('909', '1', '31', '35', '拉 结 对 她 父 亲 说 ： “ 现 在 我 身 上 不 便 ， 不 能 在 你 面 前 起 来 ， 求 我 主 不 要 生 气 。 ” 这 样 ， 拉 班 搜 寻 神 像 ， 竟 没 有 搜 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('910', '1', '31', '36', '雅 各 就 发 怒 斥 责 拉 班 说 ： “ 我 有 什 么 过 犯 ， 有 什 么 罪 恶 ， 你 竟 这 样 火 速 地 追 我 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('911', '1', '31', '37', '你 摸 遍 了 我 一 切 的 家 具 ， 你 搜 出 什 么 来 呢 ？ 可 以 放 在 你 我 弟 兄 面 前 ， 叫 他 们 在 你 我 中 间 辨 别 辨 别 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('912', '1', '31', '38', '我 在 你 家 这 二 十 年 ， 你 的 母 绵 羊 、 母 山 羊 没 有 掉 过 胎 。 你 群 中 的 公 羊 ， 我 没 有 吃 过 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('913', '1', '31', '39', '被 野 兽 撕 裂 的 ， 我 没 有 带 来 给 你 ， 是 我 自 己 赔 上 。 无 论 是 白 日 ， 是 黑 夜 ， 被 偷 去 的 ， 你 都 向 我 索 要 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('914', '1', '31', '40', '我 白 日 受 尽 干 热 ， 黑 夜 受 尽 寒 霜 ， 不 得 合 眼 睡 着 ， 我 常 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('915', '1', '31', '41', '我 这 二 十 年 在 你 家 里 ， 为 你 的 两 个 女 儿 服 事 你 十 四 年 ， 为 你 的 羊 群 服 事 你 六 年 ， 你 又 十 次 改 了 我 的 工 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('916', '1', '31', '42', '若 不 是 我 父 亲 以 撒 所 敬 畏 的 神 ， 就 是 亚 伯 拉 罕 的 神 与 我 同 在 ， 你 如 今 必 定 打 发 我 空 手 而 去 。 神 看 见 我 的 苦 情 和 我 的 劳 碌 ， 就 在 昨 夜 责 备 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('917', '1', '31', '43', '＜ 雅 各 和 拉 班 立 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('918', '1', '31', '44', '来 吧 ！ 你 我 二 人 可 以 立 约 ， 作 你 我 中 间 的 证 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('919', '1', '31', '45', '雅 各 就 拿 一 块 石 头 立 作 柱 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('920', '1', '31', '46', '又 对 众 弟 兄 说 ： “ 你 们 堆 聚 石 头 。 ” 他 们 就 拿 石 头 来 堆 成 一 堆 ， 大 家 便 在 旁 边 吃 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('921', '1', '31', '47', '拉 班 称 那 石 堆 为 伊 迦 尔 ． 撒 哈 杜 他 ， 雅 各 却 称 那 石 堆 为 迦 累 得 ｛ 都 是 以 石 堆 为 证 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('922', '1', '31', '48', '拉 班 说 ： “ 今 日 这 石 堆 作 你 我 中 间 的 证 据 。 ” 因 此 这 地 方 名 叫 迦 累 得 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('923', '1', '31', '49', '又 叫 米 斯 巴 ， 意 思 说 ： “ 我 们 彼 此 离 别 以 后 ， 愿 耶 和 华 在 你 我 中 间 鉴 察 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('924', '1', '31', '50', '你 若 苦 待 我 的 女 儿 ， 又 在 我 的 女 儿 以 外 另 娶 妻 ， 虽 没 有 人 知 道 ， 却 有 神 在 你 我 中 间 作 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('925', '1', '31', '51', '拉 班 又 说 ： “ 你 看 我 在 你 我 中 间 所 立 的 这 石 堆 和 柱 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('926', '1', '31', '52', '这 石 堆 作 证 据 ， 这 柱 子 也 作 证 据 。 我 必 不 过 这 石 堆 去 害 你 ； 你 也 不 可 过 这 石 堆 和 柱 子 来 害 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('927', '1', '31', '53', '但 愿 亚 伯 拉 罕 的 神 和 拿 鹤 的 神 ， 就 是 他 们 父 亲 的 神 ， 在 你 我 中 间 判 断 。 ” 雅 各 就 指 着 他 父 亲 以 撒 所 敬 畏 的 神 起 誓 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('928', '1', '31', '54', '又 在 山 上 献 祭 ， 请 众 弟 兄 来 吃 饭 。 他 们 吃 了 饭 ， 便 在 山 上 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('929', '1', '31', '55', '拉 班 清 早 起 来 ， 与 他 外 孙 和 女 儿 亲 嘴 ， 给 他 们 祝 福 ， 回 往 自 己 的 地 方 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('930', '1', '32', '1', '＜ 雅 各 准 备 迎 见 以 扫 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('931', '1', '32', '2', '雅 各 看 见 他 们 就 说 ： “ 这 是 神 的 军 兵 ” ， 于 是 给 那 地 方 起 名 叫 玛 哈 念 ｛ 就 是 二 军 兵 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('932', '1', '32', '3', '雅 各 打 发 人 先 往 西 珥 地 去 ， 就 是 以 东 地 ， 见 他 哥 哥 以 扫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('933', '1', '32', '4', '吩 咐 他 们 说 ： “ 你 们 对 我 主 以 扫 说 ： ‘ 你 的 仆 人 雅 各 这 样 说 ： 我 在 拉 班 那 里 寄 居 ， 直 到 如 今 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('934', '1', '32', '5', '我 有 牛 、 驴 、 羊 群 、 仆 婢 ， 现 在 打 发 人 来 报 告 我 主 ， 为 要 在 你 眼 前 蒙 恩 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('935', '1', '32', '6', '所 打 发 的 人 回 到 雅 各 那 里 ， 说 ： “ 我 们 到 了 你 哥 哥 以 扫 那 里 ， 他 带 着 四 百 人 ， 正 迎 着 你 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('936', '1', '32', '7', '雅 各 就 甚 惧 怕 ， 而 且 愁 烦 ， 便 把 那 与 他 同 在 的 人 口 和 羊 群 、 牛 群 、 骆 驼 分 做 两 队 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('937', '1', '32', '8', '说 ： “ 以 扫 若 来 击 杀 这 一 队 ， 剩 下 的 那 一 队 还 可 以 逃 避 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('938', '1', '32', '9', '雅 各 说 ： “ 耶 和 华 ─ ─ 我 祖 亚 伯 拉 罕 的 神 ， 我 父 亲 以 撒 的 神 啊 ， 你 曾 对 我 说 ： ‘ 回 你 本 地 本 族 去 ， 我 要 厚 待 你 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('939', '1', '32', '10', '你 向 仆 人 所 施 的 一 切 慈 爱 和 诚 实 ， 我 一 点 也 不 配 得 ； 我 先 前 只 拿 着 我 的 杖 过 这 约 旦 河 ， 如 今 我 却 成 了 两 队 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('940', '1', '32', '11', '求 你 救 我 脱 离 我 哥 哥 以 扫 的 手 ； 因 为 我 怕 他 来 杀 我 ， 连 妻 子 带 儿 女 一 同 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('941', '1', '32', '12', '你 曾 说 ： ‘ 我 必 定 厚 待 你 ， 使 你 的 后 裔 如 同 海 边 的 沙 ， 多 得 不 可 胜 数 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('942', '1', '32', '13', '当 夜 ， 雅 各 在 那 里 住 宿 ， 就 从 他 所 有 的 物 中 拿 礼 物 要 送 给 他 哥 哥 以 扫 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('943', '1', '32', '14', '母 山 羊 二 百 只 ， 公 山 羊 二 十 只 ， 母 绵 羊 二 百 只 ， 公 绵 羊 二 十 只 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('944', '1', '32', '15', '奶 崽 子 的 骆 驼 三 十 只 ─ ─ 各 带 着 崽 子 ， 母 牛 四 十 只 ， 公 牛 十 只 ， 母 驴 二 十 匹 ， 驴 驹 十 匹 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('945', '1', '32', '16', '每 样 各 分 一 群 ， 交 在 仆 人 手 下 ， 就 对 仆 人 说 ： “ 你 们 要 在 我 前 头 过 去 ， 使 群 群 相 离 ， 有 空 闲 的 地 方 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('946', '1', '32', '17', '又 吩 咐 尽 先 走 的 说 ： “ 我 哥 哥 以 扫 遇 见 你 的 时 候 ， 问 你 说 ： ‘ 你 是 哪 家 的 人 ？ 要 往 哪 里 去 ？ 你 前 头 这 些 是 谁 的 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('947', '1', '32', '18', '你 就 说 ： ‘ 是 你 仆 人 雅 各 的 ， 是 送 给 我 主 以 扫 的 礼 物 ； 他 自 己 也 在 我 们 后 边 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('948', '1', '32', '19', '又 吩 咐 第 二 、 第 三 ， 和 一 切 赶 群 畜 的 人 说 ： “ 你 们 遇 见 以 扫 的 时 候 也 要 这 样 对 他 说 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('949', '1', '32', '20', '并 且 你 们 要 说 ： ‘ 你 仆 人 雅 各 在 我 们 后 边 。 ’ ” 因 雅 各 心 里 说 ： “ 我 藉 着 在 我 前 头 去 的 礼 物 解 他 的 恨 ， 然 后 再 见 他 的 面 ， 或 者 他 容 纳 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('950', '1', '32', '21', '于 是 礼 物 先 过 去 了 ； 那 夜 ， 雅 各 在 队 中 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('951', '1', '32', '22', '＜ 雅 各 在 毗 努 伊 勒 摔 跤 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('952', '1', '32', '23', '先 打 发 他 们 过 河 ， 又 打 发 所 有 的 都 过 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('953', '1', '32', '24', '只 剩 下 雅 各 一 人 。 有 一 个 人 来 和 他 摔 跤 ， 直 到 黎 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('954', '1', '32', '25', '那 人 见 自 己 胜 不 过 他 ， 就 将 他 的 大 腿 窝 摸 了 一 把 ， 雅 各 的 大 腿 窝 正 在 摔 跤 的 时 候 就 扭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('955', '1', '32', '26', '那 人 说 ： “ 天 黎 明 了 ， 容 我 去 吧 ！ ” 雅 各 说 ： “ 你 不 给 我 祝 福 ， 我 就 不 容 你 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('956', '1', '32', '27', '那 人 说 ： “ 你 名 叫 什 么 ？ ” 他 说 ： “ 我 名 叫 雅 各 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('957', '1', '32', '28', '那 人 说 ： “ 你 的 名 不 要 再 叫 雅 各 ， 要 叫 以 色 列 ； 因 为 你 与 神 与 人 较 力 ， 都 得 了 胜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('958', '1', '32', '29', '雅 各 问 他 说 ： “ 请 将 你 的 名 告 诉 我 。 ” 那 人 说 ： “ 何 必 问 我 的 名 ？ ” 于 是 在 那 里 给 雅 各 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('959', '1', '32', '30', '雅 各 便 给 那 地 方 起 名 叫 毗 努 伊 勒 ｛ 就 是 神 之 面 的 意 思 ｝ ， 意 思 说 ： “ 我 面 对 面 见 了 神 ， 我 的 性 命 仍 得 保 全 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('960', '1', '32', '31', '日 头 刚 出 来 的 时 候 ， 雅 各 经 过 毗 努 伊 勒 ， 他 的 大 腿 就 瘸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('961', '1', '32', '32', '故 此 ， 以 色 列 人 不 吃 大 腿 窝 的 筋 ， 直 到 今 日 ， 因 为 那 人 摸 了 雅 各 大 腿 窝 的 筋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('962', '1', '33', '1', '＜ 雅 各 和 以 扫 相 见 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('963', '1', '33', '2', '并 且 叫 两 个 使 女 和 她 们 的 孩 子 在 前 头 ， 利 亚 和 她 的 孩 子 在 后 头 ， 拉 结 和 约 瑟 在 尽 后 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('964', '1', '33', '3', '他 自 己 在 他 们 前 头 过 去 ， 一 连 七 次 俯 伏 在 地 才 就 近 他 哥 哥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('965', '1', '33', '4', '以 扫 跑 来 迎 接 他 ， 将 他 抱 住 ， 又 搂 着 他 的 颈 项 ， 与 他 亲 嘴 ， 两 个 人 就 哭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('966', '1', '33', '5', '以 扫 举 目 看 见 妇 人 孩 子 ， 就 说 ： “ 这 些 和 你 同 行 的 是 谁 呢 ？ ” 雅 各 说 ： “ 这 些 孩 子 是 神 施 恩 给 你 的 仆 人 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('967', '1', '33', '6', '于 是 两 个 使 女 和 她 们 的 孩 子 前 来 下 拜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('968', '1', '33', '7', '利 亚 和 她 的 孩 子 也 前 来 下 拜 ； 随 后 约 瑟 和 拉 结 也 前 来 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('969', '1', '33', '8', '以 扫 说 ： “ 我 所 遇 见 的 这 些 群 畜 是 什 么 意 思 呢 ？ ” 雅 各 说 ： “ 是 要 在 我 主 面 前 蒙 恩 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('970', '1', '33', '9', '以 扫 说 ： “ 兄 弟 啊 ， 我 的 已 经 够 了 ， 你 的 仍 归 你 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('971', '1', '33', '10', '雅 各 说 ： “ 不 然 ， 我 若 在 你 眼 前 蒙 恩 ， 就 求 你 从 我 手 里 收 下 这 礼 物 ； 因 为 我 见 了 你 的 面 ， 如 同 见 了 神 的 面 ， 并 且 你 容 纳 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('972', '1', '33', '11', '求 你 收 下 我 带 来 给 你 的 礼 物 ； 因 为 神 恩 待 我 ， 使 我 充 足 。 ” 雅 各 再 三 地 求 他 ， 他 才 收 下 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('973', '1', '33', '12', '以 扫 说 ： “ 我 们 可 以 起 身 前 往 ， 我 在 你 前 头 走 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('974', '1', '33', '13', '雅 各 对 他 说 ： “ 我 主 知 道 孩 子 们 年 幼 娇 嫩 ， 牛 羊 也 正 在 乳 养 的 时 候 ， 若 是 催 赶 一 天 ， 群 畜 都 必 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('975', '1', '33', '14', '求 我 主 在 仆 人 前 头 走 ， 我 要 量 着 在 我 面 前 群 畜 和 孩 子 的 力 量 慢 慢 地 前 行 ， 直 走 到 西 珥 我 主 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('976', '1', '33', '15', '以 扫 说 ： “ 容 我 把 跟 随 我 的 人 留 几 个 在 你 这 里 。 ” 雅 各 说 ： “ 何 必 呢 ？ 只 要 在 我 主 眼 前 蒙 恩 就 是 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('977', '1', '33', '16', '于 是 ， 以 扫 当 日 起 行 ， 回 往 西 珥 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('978', '1', '33', '17', '雅 各 就 往 疏 割 去 ， 在 那 里 为 自 己 盖 造 房 屋 ， 又 为 牲 畜 搭 棚 ； 因 此 那 地 方 名 叫 疏 割 ｛ 就 是 棚 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('979', '1', '33', '18', '雅 各 从 巴 旦 ． 亚 兰 回 来 的 时 候 ， 平 平 安 安 地 到 了 迦 南 地 的 示 剑 城 ， 在 城 东 支 搭 帐 棚 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('980', '1', '33', '19', '就 用 一 百 块 银 子 向 示 剑 的 父 亲 、 哈 抹 的 子 孙 买 了 支 帐 棚 的 那 块 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('981', '1', '33', '20', '在 那 里 筑 了 一 座 坛 ， 起 名 叫 伊 利 ． 伊 罗 伊 ． 以 色 列 ｛ 就 是 神 、 以 色 列 神 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('982', '1', '34', '1', '＜ 底 拿 受 辱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('983', '1', '34', '2', '那 地 的 主 ─ ─ 希 未 人 、 哈 抹 的 儿 子 示 剑 看 见 她 ， 就 拉 住 她 ， 与 她 行 淫 ， 玷 辱 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('984', '1', '34', '3', '示 剑 的 心 系 恋 雅 各 的 女 儿 底 拿 ， 喜 爱 这 女 子 ， 甜 言 蜜 语 地 安 慰 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('985', '1', '34', '4', '示 剑 对 他 父 亲 哈 抹 说 ： “ 求 你 为 我 聘 这 女 子 为 妻 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('986', '1', '34', '5', '雅 各 听 见 示 剑 玷 污 了 他 的 女 儿 底 拿 。 那 时 他 的 儿 子 们 正 和 群 畜 在 田 野 ， 雅 各 就 闭 口 不 言 ， 等 他 们 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('987', '1', '34', '6', '示 剑 的 父 亲 哈 抹 出 来 见 雅 各 ， 要 和 他 商 议 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('988', '1', '34', '7', '雅 各 的 儿 子 们 听 见 这 事 ， 就 从 田 野 回 来 ， 人 人 忿 恨 ， 十 分 恼 怒 ； 因 示 剑 在 以 色 列 家 做 了 丑 事 ， 与 雅 各 的 女 儿 行 淫 ， 这 本 是 不 该 做 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('989', '1', '34', '8', '哈 抹 和 他 们 商 议 说 ： “ 我 儿 子 示 剑 的 心 恋 慕 这 女 子 ， 求 你 们 将 她 给 我 的 儿 子 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('990', '1', '34', '9', '你 们 与 我 们 彼 此 结 亲 ； 你 们 可 以 把 女 儿 给 我 们 ， 也 可 以 娶 我 们 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('991', '1', '34', '10', '你 们 与 我 们 同 住 吧 ！ 这 地 都 在 你 们 面 前 ， 只 管 在 此 居 住 ， 做 买 卖 ， 置 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('992', '1', '34', '11', '示 剑 对 女 儿 的 父 亲 和 弟 兄 们 说 ： “ 但 愿 我 在 你 们 眼 前 蒙 恩 ， 你 们 向 我 要 什 么 ， 我 必 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('993', '1', '34', '12', '任 凭 向 我 要 多 重 的 聘 金 和 礼 物 ， 我 必 照 你 们 所 说 的 给 你 们 ； 只 要 把 女 子 给 我 为 妻 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('994', '1', '34', '13', '雅 各 的 儿 子 们 因 为 示 剑 玷 污 了 他 们 的 妹 子 底 拿 ， 就 用 诡 诈 的 话 回 答 示 剑 和 他 父 亲 哈 抹 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('995', '1', '34', '14', '对 他 们 说 ： “ 我 们 不 能 把 我 们 的 妹 子 给 没 有 受 割 礼 的 人 为 妻 ， 因 为 那 是 我 们 的 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('996', '1', '34', '15', '惟 有 一 件 才 可 以 应 允 ： 若 你 们 所 有 的 男 丁 都 受 割 礼 ， 和 我 们 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('997', '1', '34', '16', '我 们 就 把 女 儿 给 你 们 ， 也 娶 你 们 的 女 儿 ； 我 们 便 与 你 们 同 住 ， 两 下 成 为 一 样 的 人 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('998', '1', '34', '17', '倘 若 你 们 不 听 从 我 们 受 割 礼 ， 我 们 就 带 着 妹 子 走 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('999', '1', '34', '18', '哈 抹 和 他 的 儿 子 示 剑 喜 欢 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1000', '1', '34', '19', '那 少 年 人 做 这 事 并 不 迟 延 ， 因 为 他 喜 爱 雅 各 的 女 儿 ； 他 在 他 父 亲 家 中 也 是 人 最 尊 重 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1001', '1', '34', '20', '哈 抹 和 他 儿 子 示 剑 到 本 城 的 门 口 ， 对 本 城 的 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1002', '1', '34', '21', '“ 这 些 人 与 我 们 和 睦 ， 不 如 许 他 们 在 这 地 居 住 ， 做 买 卖 ； 这 地 也 宽 阔 ， 足 可 容 下 他 们 。 我 们 可 以 娶 他 们 的 女 儿 为 妻 ， 也 可 以 把 我 们 的 女 儿 嫁 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1003', '1', '34', '22', '惟 有 一 件 事 我 们 必 须 做 ， 他 们 才 肯 应 允 和 我 们 同 住 ， 成 为 一 样 的 人 民 ： 就 是 我 们 中 间 所 有 的 男 丁 都 要 受 割 礼 ， 和 他 们 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1004', '1', '34', '23', '他 们 的 群 畜 、 货 财 ， 和 一 切 的 牲 口 岂 不 都 归 我 们 吗 ？ 只 要 依 从 他 们 ， 他 们 就 与 我 们 同 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1005', '1', '34', '24', '凡 从 城 门 出 入 的 人 就 都 听 从 哈 抹 和 他 儿 子 示 剑 的 话 ； 于 是 凡 从 城 门 出 入 的 男 丁 都 受 了 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1006', '1', '34', '25', '到 第 三 天 ， 众 人 正 在 疼 痛 的 时 候 ， 雅 各 的 两 个 儿 子 ， 就 是 底 拿 的 哥 哥 西 缅 和 利 未 ， 各 拿 刀 剑 ， 趁 着 众 人 想 不 到 的 时 候 来 到 城 中 ， 把 一 切 男 丁 都 杀 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1007', '1', '34', '26', '又 用 刀 杀 了 哈 抹 和 他 儿 子 示 剑 ， 把 底 拿 从 示 剑 家 里 带 出 来 就 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1008', '1', '34', '27', '雅 各 的 儿 子 们 因 为 他 们 的 妹 子 受 了 玷 污 ， 就 来 到 被 杀 的 人 那 里 ， 掳 掠 那 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1009', '1', '34', '28', '夺 了 他 们 的 羊 群 、 牛 群 ， 和 驴 ， 并 城 里 田 间 所 有 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1010', '1', '34', '29', '又 把 他 们 一 切 货 财 、 孩 子 、 妇 女 ， 并 各 房 中 所 有 的 ， 都 掳 掠 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1011', '1', '34', '30', '雅 各 对 西 缅 和 利 未 说 ： “ 你 们 连 累 我 ， 使 我 在 这 地 的 居 民 中 ， 就 是 在 迦 南 人 和 比 利 洗 人 中 ， 有 了 臭 名 。 我 的 人 丁 既 然 稀 少 ， 他 们 必 聚 集 来 击 杀 我 ， 我 和 全 家 的 人 都 必 灭 绝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1012', '1', '34', '31', '他 们 说 ： “ 他 岂 可 待 我 们 的 妹 子 如 同 妓 女 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1013', '1', '35', '1', '＜ 神 在 伯 特 利 赐 福 雅 各 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1014', '1', '35', '2', '雅 各 就 对 他 家 中 的 人 并 一 切 与 他 同 在 的 人 说 ： “ 你 们 要 除 掉 你 们 中 间 的 外 邦 神 ， 也 要 自 洁 ， 更 换 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1015', '1', '35', '3', '我 们 要 起 来 ， 上 伯 特 利 去 ， 在 那 里 我 要 筑 一 座 坛 给 神 ， 就 是 在 我 遭 难 的 日 子 应 允 我 的 祷 告 、 在 我 行 的 路 上 保 佑 我 的 那 位 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1016', '1', '35', '4', '他 们 就 把 外 邦 人 的 神 像 和 他 们 耳 朵 上 的 环 子 交 给 雅 各 ； 雅 各 都 藏 在 示 剑 那 里 的 橡 树 底 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1017', '1', '35', '5', '他 们 便 起 行 前 往 。 神 使 那 周 围 城 邑 的 人 都 甚 惊 惧 ， 就 不 追 赶 雅 各 的 众 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1018', '1', '35', '6', '于 是 雅 各 和 一 切 与 他 同 在 的 人 到 了 迦 南 地 的 路 斯 ， 就 是 伯 特 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1019', '1', '35', '7', '他 在 那 里 筑 了 一 座 坛 ， 就 给 那 地 方 起 名 叫 伊 勒 ． 伯 特 利 ｛ 就 是 伯 特 利 之 神 的 意 思 ｝ ； 因 为 他 逃 避 他 哥 哥 的 时 候 ， 神 在 那 里 向 他 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1020', '1', '35', '8', '利 百 加 的 奶 母 底 波 拉 死 了 ， 就 葬 在 伯 特 利 下 边 橡 树 底 下 ； 那 棵 树 名 叫 亚 伦 ． 巴 古 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1021', '1', '35', '9', '雅 各 从 巴 旦 ． 亚 兰 回 来 ， 神 又 向 他 显 现 ， 赐 福 与 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1022', '1', '35', '10', '且 对 他 说 ： “ 你 的 名 原 是 雅 各 ， 从 今 以 后 不 要 再 叫 雅 各 ， 要 叫 以 色 列 。 ” 这 样 ， 他 就 改 名 叫 以 色 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1023', '1', '35', '11', '神 又 对 他 说 ： “ 我 是 全 能 的 神 ； 你 要 生 养 众 多 ， 将 来 有 一 族 和 多 国 的 民 从 你 而 生 ， 又 有 君 王 从 你 而 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1024', '1', '35', '12', '我 所 赐 给 亚 伯 拉 罕 和 以 撒 的 地 ， 我 要 赐 给 你 与 你 的 后 裔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1025', '1', '35', '13', '神 就 从 那 与 雅 各 说 话 的 地 方 升 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1026', '1', '35', '14', '雅 各 便 在 那 里 立 了 一 根 石 柱 ， 在 柱 子 上 奠 酒 ， 浇 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1027', '1', '35', '15', '雅 各 就 给 那 地 方 起 名 叫 伯 特 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1028', '1', '35', '16', '＜ 拉 结 去 世 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1029', '1', '35', '17', '正 在 艰 难 的 时 候 ， 收 生 婆 对 她 说 ： “ 不 要 怕 ， 你 又 要 得 一 个 儿 子 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1030', '1', '35', '18', '她 将 近 于 死 ， 灵 魂 要 走 的 时 候 ， 就 给 她 儿 子 起 名 叫 便 ． 俄 尼 ； 他 父 亲 却 给 他 起 名 叫 便 雅 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1031', '1', '35', '19', '拉 结 死 了 ， 葬 在 以 法 他 的 路 旁 ； 以 法 他 就 是 伯 利 恒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1032', '1', '35', '20', '雅 各 在 她 的 坟 上 立 了 一 统 碑 ， 就 是 拉 结 的 墓 碑 ， 到 今 日 还 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1033', '1', '35', '21', '以 色 列 起 行 前 往 ， 在 以 得 台 那 边 支 搭 帐 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1034', '1', '35', '22', '＜ 雅 各 的 儿 子 们 （ 代 上   2 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1035', '1', '35', '23', '利 亚 所 生 的 是 雅 各 的 长 子 吕 便 ， 还 有 西 缅 、 利 未 、 犹 大 、 以 萨 迦 、 西 布 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1036', '1', '35', '24', '拉 结 所 生 的 是 约 瑟 、 便 雅 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1037', '1', '35', '25', '拉 结 的 使 女 辟 拉 所 生 的 是 但 、 拿 弗 他 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1038', '1', '35', '26', '利 亚 的 使 女 悉 帕 所 生 的 是 迦 得 、 亚 设 。 这 是 雅 各 在 巴 旦 ． 亚 兰 所 生 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1039', '1', '35', '27', '＜ 以 撒 去 世 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1040', '1', '35', '28', '以 撒 共 活 了 一 百 八 十 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1041', '1', '35', '29', '以 撒 年 纪 老 迈 ， 日 子 满 足 ， 气 绝 而 死 ， 归 到 他 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 。 他 两 个 儿 子 以 扫 、 雅 各 把 他 埋 葬 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1042', '1', '36', '1', '＜ 以 扫 的 子 孙 （ 代 上   1 : 3 4 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1043', '1', '36', '2', '以 扫 娶 迦 南 的 女 子 为 妻 ， 就 是 赫 人 以 伦 的 女 儿 亚 大 和 希 未 人 祭 便 的 孙 女 、 亚 拿 的 女 儿 阿 何 利 巴 玛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1044', '1', '36', '3', '又 娶 了 以 实 玛 利 的 女 儿 、 尼 拜 约 的 妹 子 巴 实 抹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1045', '1', '36', '4', '亚 大 给 以 扫 生 了 以 利 法 ； 巴 实 抹 生 了 流 珥 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1046', '1', '36', '5', '阿 何 利 巴 玛 生 了 耶 乌 施 、 雅 兰 、 可 拉 。 这 都 是 以 扫 的 儿 子 ， 是 在 迦 南 地 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1047', '1', '36', '6', '以 扫 带 着 他 的 妻 子 、 儿 女 ， 与 家 中 一 切 的 人 口 ， 并 他 的 牛 羊 、 牲 畜 ， 和 一 切 货 财 ， 就 是 他 在 迦 南 地 所 得 的 ， 往 别 处 去 ， 离 了 他 兄 弟 雅 各 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1048', '1', '36', '7', '因 为 二 人 的 财 物 群 畜 甚 多 ， 寄 居 的 地 方 容 不 下 他 们 ， 所 以 不 能 同 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1049', '1', '36', '8', '于 是 以 扫 住 在 西 珥 山 里 ； 以 扫 就 是 以 东 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1050', '1', '36', '9', '以 扫 是 西 珥 山 里 以 东 人 的 始 祖 ， 他 的 后 代 记 在 下 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1051', '1', '36', '10', '以 扫 众 子 的 名 字 如 下 。 以 扫 的 妻 子 亚 大 生 以 利 法 ； 以 扫 的 妻 子 巴 实 抹 生 流 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1052', '1', '36', '11', '以 利 法 的 儿 子 是 提 幔 、 阿 抹 、 洗 玻 、 迦 坦 、 基 纳 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1053', '1', '36', '12', '亭 纳 是 以 扫 儿 子 以 利 法 的 妾 ； 她 给 以 利 法 生 了 亚 玛 力 。 这 是 以 扫 的 妻 子 亚 大 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1054', '1', '36', '13', '流 珥 的 儿 子 是 拿 哈 、 谢 拉 、 沙 玛 、 米 撒 。 这 是 以 扫 妻 子 巴 实 抹 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1055', '1', '36', '14', '以 扫 的 妻 子 阿 何 利 巴 玛 是 祭 便 的 孙 女 ， 亚 拿 的 女 儿 ； 她 给 以 扫 生 了 耶 乌 施 、 雅 兰 、 可 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1056', '1', '36', '15', '以 扫 子 孙 中 作 族 长 的 记 在 下 面 。 以 扫 的 长 子 以 利 法 的 子 孙 中 ， 有 提 幔 族 长 、 阿 抹 族 长 、 洗 玻 族 长 、 基 纳 斯 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1057', '1', '36', '16', '可 拉 族 长 、 迦 坦 族 长 、 亚 玛 力 族 长 。 这 是 在 以 东 地 从 以 利 法 所 出 的 族 长 ， 都 是 亚 大 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1058', '1', '36', '17', '以 扫 的 儿 子 流 珥 的 子 孙 中 ， 有 拿 哈 族 长 、 谢 拉 族 长 、 沙 玛 族 长 、 米 撒 族 长 。 这 是 在 以 东 地 从 流 珥 所 出 的 族 长 ， 都 是 以 扫 妻 子 巴 实 抹 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1059', '1', '36', '18', '以 扫 的 妻 子 阿 何 利 巴 玛 的 子 孙 中 ， 有 耶 乌 施 族 长 、 雅 兰 族 长 、 可 拉 族 长 。 这 是 从 以 扫 妻 子 ， 亚 拿 的 女 儿 ， 阿 何 利 巴 玛 子 孙 中 所 出 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1060', '1', '36', '19', '以 上 的 族 长 都 是 以 扫 的 子 孙 ； 以 扫 就 是 以 东 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1061', '1', '36', '20', '＜ 西 珥 的 子 孙 （ 代 上   1 : 3 8 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1062', '1', '36', '21', '底 顺 、 以 察 、 底 珊 。 这 是 从 以 东 地 的 何 利 人 西 珥 子 孙 中 所 出 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1063', '1', '36', '22', '罗 坍 的 儿 子 是 何 利 、 希 幔 ； 罗 坍 的 妹 子 是 亭 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1064', '1', '36', '23', '朔 巴 的 儿 子 是 亚 勒 文 、 玛 拿 辖 、 以 巴 录 、 示 玻 、 阿 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1065', '1', '36', '24', '祭 便 的 儿 子 是 亚 雅 、 亚 拿 （ 当 时 在 旷 野 放 他 父 亲 祭 便 的 驴 ， 遇 着 温 泉 的 ， 就 是 这 亚 拿 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1066', '1', '36', '25', '亚 拿 的 儿 子 是 底 顺 ； 亚 拿 的 女 儿 是 阿 何 利 巴 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1067', '1', '36', '26', '底 顺 的 儿 子 是 欣 但 、 伊 是 班 、 益 兰 、 基 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1068', '1', '36', '27', '以 察 的 儿 子 是 辟 罕 、 撒 番 、 亚 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1069', '1', '36', '28', '底 珊 的 儿 子 是 乌 斯 、 亚 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1070', '1', '36', '29', '从 何 利 人 所 出 的 族 长 记 在 下 面 ： 就 是 罗 坍 族 长 、 朔 巴 族 长 、 祭 便 族 长 、 亚 拿 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1071', '1', '36', '30', '底 顺 族 长 、 以 察 族 长 、 底 珊 族 长 。 这 是 从 何 利 人 所 出 的 族 长 ， 都 在 西 珥 地 ， 按 着 宗 族 作 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1072', '1', '36', '31', '＜ 以 东 诸 王 （ 代 上   1 : 4 3 - 5 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1073', '1', '36', '32', '比 珥 的 儿 子 比 拉 在 以 东 作 王 ， 他 的 京 城 名 叫 亭 哈 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1074', '1', '36', '33', '比 拉 死 了 ， 波 斯 拉 人 谢 拉 的 儿 子 约 巴 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1075', '1', '36', '34', '约 巴 死 了 ， 提 幔 地 的 人 户 珊 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1076', '1', '36', '35', '户 珊 死 了 ， 比 达 的 儿 子 哈 达 接 续 他 作 王 ； 这 哈 达 就 是 在 摩 押 地 杀 败 米 甸 人 的 ， 他 的 京 城 名 叫 亚 未 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1077', '1', '36', '36', '哈 达 死 了 ， 玛 士 利 加 人 桑 拉 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1078', '1', '36', '37', '桑 拉 死 了 ， 大 河 边 的 利 河 伯 人 扫 罗 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1079', '1', '36', '38', '扫 罗 死 了 ， 亚 革 波 的 儿 子 巴 勒 ． 哈 南 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1080', '1', '36', '39', '亚 革 波 的 儿 子 巴 勒 ． 哈 南 死 了 ， 哈 达 接 续 他 作 王 ， 他 的 京 城 名 叫 巴 乌 ； 他 的 妻 子 名 叫 米 希 她 别 ， 是 米 ． 萨 合 的 孙 女 ， 玛 特 列 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1081', '1', '36', '40', '从 以 扫 所 出 的 族 长 ， 按 着 他 们 的 宗 族 、 住 处 、 名 字 记 在 下 面 ： 就 是 亭 纳 族 长 、 亚 勒 瓦 族 长 、 耶 帖 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1082', '1', '36', '41', '阿 何 利 巴 玛 族 长 、 以 拉 族 长 、 比 嫩 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1083', '1', '36', '42', '基 纳 斯 族 长 、 提 幔 族 长 、 米 比 萨 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1084', '1', '36', '43', '玛 基 叠 族 长 、 以 兰 族 长 。 这 是 以 东 人 在 所 得 为 业 的 地 上 ， 按 着 他 们 的 住 处 。 〈 所 有 的 族 长 都 是 以 东 人 的 始 祖 以 扫 的 后 代 。 〉');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1085', '1', '37', '1', '＜ 约 瑟 和 他 的 兄 弟 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1086', '1', '37', '2', '雅 各 的 记 略 如 下 。 约 瑟 十 七 岁 与 他 哥 哥 们 一 同 牧 羊 。 他 是 个 童 子 ， 与 他 父 亲 的 妾 辟 拉 、 悉 帕 的 儿 子 们 常 在 一 处 。 约 瑟 将 他 哥 哥 们 的 恶 行 报 给 他 们 的 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1087', '1', '37', '3', '以 色 列 原 来 爱 约 瑟 过 于 爱 他 的 众 子 ， 因 为 约 瑟 是 他 年 老 生 的 ； 他 给 约 瑟 做 了 一 件 彩 衣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1088', '1', '37', '4', '约 瑟 的 哥 哥 们 见 父 亲 爱 约 瑟 过 于 爱 他 们 ， 就 恨 约 瑟 ， 不 与 他 说 和 睦 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1089', '1', '37', '5', '约 瑟 做 了 一 梦 ， 告 诉 他 哥 哥 们 ， 他 们 就 越 发 恨 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1090', '1', '37', '6', '约 瑟 对 他 们 说 ： “ 请 听 我 所 做 的 梦 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1091', '1', '37', '7', '我 们 在 田 里 捆 禾 稼 ， 我 的 捆 起 来 站 着 ， 你 们 的 捆 来 围 着 我 的 捆 下 拜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1092', '1', '37', '8', '他 的 哥 哥 们 回 答 说 ： “ 难 道 你 真 要 作 我 们 的 王 吗 ？ 难 道 你 真 要 管 辖 我 们 吗 ？ ” 他 们 就 因 为 他 的 梦 和 他 的 话 越 发 恨 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1093', '1', '37', '9', '后 来 他 又 做 了 一 梦 ， 也 告 诉 他 的 哥 哥 们 说 ： “ 看 哪 ， 我 又 做 了 一 梦 ， 梦 见 太 阳 、 月 亮 ， 与 十 一 个 星 向 我 下 拜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1094', '1', '37', '10', '约 瑟 将 这 梦 告 诉 他 父 亲 和 他 哥 哥 们 ， 他 父 亲 就 责 备 他 说 ： “ 你 做 的 这 是 什 么 梦 ！ 难 道 我 和 你 母 亲 、 你 弟 兄 果 然 要 来 俯 伏 在 地 ， 向 你 下 拜 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1095', '1', '37', '11', '他 哥 哥 们 都 嫉 妒 他 ， 他 父 亲 却 把 这 话 存 在 心 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1096', '1', '37', '12', '＜ 约 瑟 被 卖 到 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1097', '1', '37', '13', '以 色 列 对 约 瑟 说 ： “ 你 哥 哥 们 不 是 在 示 剑 放 羊 吗 ？ 你 来 ， 我 要 打 发 你 往 他 们 那 里 去 。 ” 约 瑟 说 ： “ 我 在 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1098', '1', '37', '14', '以 色 列 说 ： “ 你 去 看 看 你 哥 哥 们 平 安 不 平 安 ， 群 羊 平 安 不 平 安 ， 就 回 来 报 信 给 我 ” ； 于 是 打 发 他 出 希 伯 仑 谷 ， 他 就 往 示 剑 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1099', '1', '37', '15', '有 人 遇 见 他 在 田 野 走 迷 了 路 ， 就 问 他 说 ： “ 你 找 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1100', '1', '37', '16', '他 说 ： “ 我 找 我 的 哥 哥 们 ， 求 你 告 诉 我 ， 他 们 在 何 处 放 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1101', '1', '37', '17', '那 人 说 ： “ 他 们 已 经 走 了 ， 我 听 见 他 们 说 要 往 多 坍 去 。 ” 约 瑟 就 去 追 赶 他 哥 哥 们 ， 遇 见 他 们 在 多 坍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1102', '1', '37', '18', '他 们 远 远 地 看 见 他 ， 趁 他 还 没 有 走 到 跟 前 ， 大 家 就 同 谋 要 害 死 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1103', '1', '37', '19', '彼 此 说 ： “ 你 看 ！ 那 做 梦 的 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1104', '1', '37', '20', '来 吧 ！ 我 们 将 他 杀 了 ， 丢 在 一 个 坑 里 ， 就 说 有 恶 兽 把 他 吃 了 。 我 们 且 看 他 的 梦 将 来 怎 么 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1105', '1', '37', '21', '吕 便 听 见 了 ， 要 救 他 脱 离 他 们 的 手 ， 说 ： “ 我 们 不 可 害 他 的 性 命 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1106', '1', '37', '22', '又 说 ： “ 不 可 流 他 的 血 ， 可 以 把 他 丢 在 这 野 地 的 坑 里 ， 不 可 下 手 害 他 。 ” 吕 便 的 意 思 是 要 救 他 脱 离 他 们 的 手 ， 把 他 归 还 他 的 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1107', '1', '37', '23', '约 瑟 到 了 他 哥 哥 们 那 里 ， 他 们 就 剥 了 他 的 外 衣 ， 就 是 他 穿 的 那 件 彩 衣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1108', '1', '37', '24', '把 他 丢 在 坑 里 ； 那 坑 是 空 的 ， 里 头 没 有 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1109', '1', '37', '25', '他 们 坐 下 吃 饭 ， 举 目 观 看 ， 见 有 一 伙 米 甸 的 以 实 玛 利 人 从 基 列 来 ， 用 骆 驼 驮 着 香 料 、 乳 香 、 没 药 ， 要 带 下 埃 及 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1110', '1', '37', '26', '犹 大 对 众 弟 兄 说 ： “ 我 们 杀 我 们 的 兄 弟 ， 藏 了 他 的 血 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1111', '1', '37', '27', '我 们 不 如 将 他 卖 给 以 实 玛 利 人 ， 不 可 下 手 害 他 ； 因 为 他 是 我 们 的 兄 弟 ， 我 们 的 骨 肉 。 ” 众 弟 兄 就 听 从 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1112', '1', '37', '28', '有 些 米 甸 的 商 人 从 那 里 经 过 ， 哥 哥 们 就 把 约 瑟 从 坑 里 拉 上 来 ， 讲 定 二 十 舍 客 勒 银 子 ， 把 约 瑟 卖 给 以 实 玛 利 人 。 他 们 就 把 约 瑟 带 到 埃 及 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1113', '1', '37', '29', '吕 便 回 到 坑 边 ， 见 约 瑟 不 在 坑 里 ， 就 撕 裂 衣 服 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1114', '1', '37', '30', '回 到 兄 弟 们 那 里 ， 说 ： “ 童 子 没 有 了 。 我 往 哪 里 去 才 好 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1115', '1', '37', '31', '他 们 宰 了 一 只 公 山 羊 ， 把 约 瑟 的 那 件 彩 衣 染 了 血 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1116', '1', '37', '32', '打 发 人 送 到 他 们 的 父 亲 那 里 ， 说 ： “ 我 们 捡 了 这 个 ； 请 认 一 认 是 你 儿 子 的 外 衣 不 是 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1117', '1', '37', '33', '他 认 得 ， 就 说 ： “ 这 是 我 儿 子 的 外 衣 。 有 恶 兽 把 他 吃 了 ， 约 瑟 被 撕 碎 了 ！ 撕 碎 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1118', '1', '37', '34', '雅 各 便 撕 裂 衣 服 ， 腰 间 围 上 麻 布 ， 为 他 儿 子 悲 哀 了 多 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1119', '1', '37', '35', '他 的 儿 女 都 起 来 安 慰 他 ， 他 却 不 肯 受 安 慰 ， 说 ： “ 我 必 悲 哀 着 下 阴 间 ， 到 我 儿 子 那 里 。 ” 约 瑟 的 父 亲 就 为 他 哀 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1120', '1', '37', '36', '米 甸 人 带 约 瑟 到 埃 及 ， 把 他 卖 给 法 老 的 内 臣 ─ ─ 护 卫 长 波 提 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1121', '1', '38', '1', '＜ 犹 大 和 她 玛 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1122', '1', '38', '2', '犹 大 在 那 里 看 见 一 个 迦 南 人 名 叫 书 亚 的 女 儿 ， 就 娶 她 为 妻 ， 与 她 同 房 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1123', '1', '38', '3', '她 就 怀 孕 生 了 儿 子 ， 犹 大 给 他 起 名 叫 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1124', '1', '38', '4', '她 又 怀 孕 生 了 儿 子 ， 母 亲 给 他 起 名 叫 俄 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1125', '1', '38', '5', '她 复 又 生 了 儿 子 ， 给 他 起 名 叫 示 拉 。 她 生 示 拉 的 时 候 ， 犹 大 正 在 基 悉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1126', '1', '38', '6', '犹 大 为 长 子 珥 娶 妻 ， 名 叫 她 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1127', '1', '38', '7', '犹 大 的 长 子 珥 在 耶 和 华 眼 中 看 为 恶 ， 耶 和 华 就 叫 他 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1128', '1', '38', '8', '犹 大 对 俄 南 说 ： “ 你 当 与 你 哥 哥 的 妻 子 同 房 ， 向 她 尽 你 为 弟 的 本 分 ， 为 你 哥 哥 生 子 立 后 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1129', '1', '38', '9', '俄 南 知 道 生 子 不 归 自 己 ， 所 以 同 房 的 时 候 便 遗 在 地 ， 免 得 给 他 哥 哥 留 后 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1130', '1', '38', '10', '俄 南 所 做 的 在 耶 和 华 眼 中 看 为 恶 ， 耶 和 华 也 就 叫 他 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1131', '1', '38', '11', '犹 大 心 里 说 ： “ 恐 怕 示 拉 也 死 ， 像 他 两 个 哥 哥 一 样 ” ， 就 对 他 儿 妇 她 玛 说 ： “ 你 去 ， 在 你 父 亲 家 里 守 寡 ， 等 我 儿 子 示 拉 长 大 。 ” 她 玛 就 回 去 ， 住 在 她 父 亲 家 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1132', '1', '38', '12', '过 了 许 久 ， 犹 大 的 妻 子 书 亚 的 女 儿 死 了 。 犹 大 得 了 安 慰 ， 就 和 他 朋 友 亚 杜 兰 人 希 拉 上 亭 拿 去 ， 到 他 剪 羊 毛 的 人 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1133', '1', '38', '13', '有 人 告 诉 她 玛 说 ： “ 你 的 公 公 上 亭 拿 剪 羊 毛 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1134', '1', '38', '14', '她 玛 见 示 拉 已 经 长 大 ， 还 没 有 娶 她 为 妻 ， 就 脱 了 她 作 寡 妇 的 衣 裳 ， 用 帕 子 蒙 着 脸 ， 又 遮 住 身 体 ， 坐 在 亭 拿 路 上 的 伊 拿 印 城 门 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1135', '1', '38', '15', '犹 大 看 见 她 ， 以 为 是 妓 女 ， 因 为 她 蒙 着 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1136', '1', '38', '16', '犹 大 就 转 到 她 那 里 去 ， 说 ： “ 来 吧 ！ 让 我 与 你 同 寝 。 ” 他 原 不 知 道 是 他 的 儿 妇 。 她 玛 说 ： “ 你 要 与 我 同 寝 ， 把 什 么 给 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1137', '1', '38', '17', '犹 大 说 ： “ 我 从 羊 群 里 取 一 只 山 羊 羔 ， 打 发 人 送 来 给 你 。 ” 她 玛 说 ： “ 在 未 送 以 先 ， 你 愿 意 给 我 一 个 当 头 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1138', '1', '38', '18', '他 说 ： “ 我 给 你 什 么 当 头 呢 ？ ” 她 玛 说 ： “ 你 的 印 、 你 的 带 子 ， 和 你 手 里 的 杖 。 ” 犹 大 就 给 了 她 ， 与 她 同 寝 ， 她 就 从 犹 大 怀 了 孕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1139', '1', '38', '19', '她 玛 起 来 走 了 ， 除 去 帕 子 ， 仍 旧 穿 上 作 寡 妇 的 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1140', '1', '38', '20', '犹 大 托 他 朋 友 亚 杜 兰 人 送 一 只 山 羊 羔 去 ， 要 从 那 女 人 手 里 取 回 当 头 来 ， 却 找 不 着 她 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1141', '1', '38', '21', '就 问 那 地 方 的 人 说 ： “ 伊 拿 印 路 旁 的 妓 女 在 哪 里 ？ ” 他 们 说 ： “ 这 里 并 没 有 妓 女 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1142', '1', '38', '22', '他 回 去 见 犹 大 说 ： “ 我 没 有 找 着 她 ， 并 且 那 地 方 的 人 说 ： ‘ 这 里 没 有 妓 女 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1143', '1', '38', '23', '犹 大 说 ： “ 我 把 这 山 羊 羔 送 去 了 ， 你 竟 找 不 着 她 。 任 凭 她 拿 去 吧 ， 免 得 我 们 被 羞 辱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1144', '1', '38', '24', '约 过 了 三 个 月 ， 有 人 告 诉 犹 大 说 ： “ 你 的 儿 妇 她 玛 作 了 妓 女 ， 且 因 行 淫 有 了 身 孕 。 ” 犹 大 说 ： “ 拉 出 她 来 ， 把 她 烧 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1145', '1', '38', '25', '她 玛 被 拉 出 来 的 时 候 便 打 发 人 去 见 她 公 公 ， 对 他 说 ： “ 这 些 东 西 是 谁 的 ， 我 就 是 从 谁 怀 的 孕 。 请 你 认 一 认 ， 这 印 和 带 子 并 杖 都 是 谁 的 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1146', '1', '38', '26', '犹 大 承 认 说 ： “ 她 比 我 更 有 义 ， 因 为 我 没 有 将 她 给 我 的 儿 子 示 拉 。 ” 从 此 犹 大 不 再 与 她 同 寝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1147', '1', '38', '27', '她 玛 将 要 生 产 ， 不 料 她 腹 里 是 一 对 双 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1148', '1', '38', '28', '到 生 产 的 时 候 ， 一 个 孩 子 伸 出 一 只 手 来 ； 收 生 婆 拿 红 线 拴 在 他 手 上 ， 说 ： “ 这 是 头 生 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1149', '1', '38', '29', '随 后 这 孩 子 把 手 收 回 去 ， 他 哥 哥 生 出 来 了 ； 收 生 婆 说 ： “ 你 为 什 么 抢 着 来 呢 ？ ” 因 此 给 他 起 名 叫 法 勒 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1150', '1', '38', '30', '后 来 ， 他 兄 弟 那 手 上 有 红 线 的 也 生 出 来 ， 就 给 他 起 名 叫 谢 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1151', '1', '39', '1', '＜ 约 瑟 和 波 提 乏 之 妻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1152', '1', '39', '2', '约 瑟 住 在 他 主 人 埃 及 人 的 家 中 ， 耶 和 华 与 他 同 在 ， 他 就 百 事 顺 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1153', '1', '39', '3', '他 主 人 见 耶 和 华 与 他 同 在 ， 又 见 耶 和 华 使 他 手 里 所 办 的 尽 都 顺 利 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1154', '1', '39', '4', '约 瑟 就 在 主 人 眼 前 蒙 恩 ， 伺 候 他 主 人 ， 并 且 主 人 派 他 管 理 家 务 ， 把 一 切 所 有 的 都 交 在 他 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1155', '1', '39', '5', '自 从 主 人 派 约 瑟 管 理 家 务 和 他 一 切 所 有 的 ， 耶 和 华 就 因 约 瑟 的 缘 故 赐 福 与 那 埃 及 人 的 家 ； 凡 家 里 和 田 间 一 切 所 有 的 都 蒙 耶 和 华 赐 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1156', '1', '39', '6', '波 提 乏 将 一 切 所 有 的 都 交 在 约 瑟 的 手 中 ， 除 了 自 己 所 吃 的 饭 ， 别 的 事 一 概 不 知 。 约 瑟 原 来 秀 雅 俊 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1157', '1', '39', '7', '这 事 以 后 ， 约 瑟 主 人 的 妻 以 目 送 情 给 约 瑟 ， 说 ： “ 你 与 我 同 寝 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1158', '1', '39', '8', '约 瑟 不 从 ， 对 他 主 人 的 妻 说 ： “ 看 哪 ， 一 切 家 务 ， 我 主 人 都 不 知 道 ； 他 把 所 有 的 都 交 在 我 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1159', '1', '39', '9', '在 这 家 里 没 有 比 我 大 的 ； 并 且 他 没 有 留 下 一 样 不 交 给 我 ， 只 留 下 了 你 ， 因 为 你 是 他 的 妻 子 。 我 怎 能 作 这 大 恶 ， 得 罪 神 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1160', '1', '39', '10', '后 来 她 天 天 和 约 瑟 说 ， 约 瑟 却 不 听 从 她 ， 不 与 她 同 寝 ， 也 不 和 她 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1161', '1', '39', '11', '有 一 天 ， 约 瑟 进 屋 里 去 办 事 ， 家 中 人 没 有 一 个 在 那 屋 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1162', '1', '39', '12', '妇 人 就 拉 住 他 的 衣 裳 ， 说 ： “ 你 与 我 同 寝 吧 ！ ” 约 瑟 把 衣 裳 丢 在 妇 人 手 里 ， 跑 到 外 边 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1163', '1', '39', '13', '妇 人 看 见 约 瑟 把 衣 裳 丢 在 她 手 里 跑 出 去 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1164', '1', '39', '14', '就 叫 了 家 里 的 人 来 ， 对 他 们 说 ： “ 你 们 看 ！ 他 带 了 一 个 希 伯 来 人 进 入 我 们 家 里 ， 要 戏 弄 我 们 。 他 到 我 这 里 来 ， 要 与 我 同 寝 ， 我 就 大 声 喊 叫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1165', '1', '39', '15', '他 听 见 我 放 声 喊 起 来 ， 就 把 衣 裳 丢 在 我 这 里 ， 跑 到 外 边 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1166', '1', '39', '16', '妇 人 把 约 瑟 的 衣 裳 放 在 自 己 那 里 ， 等 着 他 主 人 回 家 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1167', '1', '39', '17', '就 对 他 如 此 如 此 说 ： “ 你 所 带 到 我 们 这 里 的 那 希 伯 来 仆 人 进 来 要 戏 弄 我 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1168', '1', '39', '18', '我 放 声 喊 起 来 ， 他 就 把 衣 裳 丢 在 我 这 里 ， 跑 出 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1169', '1', '39', '19', '约 瑟 的 主 人 听 见 他 妻 子 对 他 所 说 的 话 ， 说 “ 你 的 仆 人 如 此 如 此 待 我 ” ， 他 就 生 气 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1170', '1', '39', '20', '把 约 瑟 下 在 监 里 ， 就 是 王 的 囚 犯 被 囚 的 地 方 。 于 是 约 瑟 在 那 里 坐 监 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1171', '1', '39', '21', '但 耶 和 华 与 约 瑟 同 在 ， 向 他 施 恩 ， 使 他 在 司 狱 的 眼 前 蒙 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1172', '1', '39', '22', '司 狱 就 把 监 里 所 有 的 囚 犯 都 交 在 约 瑟 的 手 下 ； 他 们 在 那 里 所 办 的 事 都 是 经 他 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1173', '1', '39', '23', '凡 在 约 瑟 手 下 的 事 ， 司 狱 一 概 不 察 ， 因 为 耶 和 华 与 约 瑟 同 在 ； 耶 和 华 使 他 所 做 的 尽 都 顺 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1174', '1', '40', '1', '＜ 约 瑟 为 囚 犯 解 梦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1175', '1', '40', '2', '法 老 就 恼 怒 酒 政 和 膳 长 这 二 臣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1176', '1', '40', '3', '把 他 们 下 在 护 卫 长 府 内 的 监 里 ， 就 是 约 瑟 被 囚 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1177', '1', '40', '4', '护 卫 长 把 他 们 交 给 约 瑟 ， 约 瑟 便 伺 候 他 们 ； 他 们 有 些 日 子 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1178', '1', '40', '5', '被 囚 在 监 之 埃 及 王 的 酒 政 和 膳 长 二 人 同 夜 各 做 一 梦 ， 各 梦 都 有 讲 解 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1179', '1', '40', '6', '到 了 早 晨 ， 约 瑟 进 到 他 们 那 里 ， 见 他 们 有 愁 闷 的 样 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1180', '1', '40', '7', '他 便 问 法 老 的 二 臣 ， 就 是 与 他 同 囚 在 他 主 人 府 里 的 ， 说 ： “ 你 们 今 日 为 什 么 面 带 愁 容 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1181', '1', '40', '8', '他 们 对 他 说 ： “ 我 们 各 人 做 了 一 梦 ， 没 有 人 能 解 。 ” 约 瑟 说 ： “ 解 梦 不 是 出 于 神 吗 ？ 请 你 们 将 梦 告 诉 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1182', '1', '40', '9', '酒 政 便 将 他 的 梦 告 诉 约 瑟 说 ： “ 我 梦 见 在 我 面 前 有 一 棵 葡 萄 树 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1183', '1', '40', '10', '树 上 有 三 根 枝 子 ， 好 像 发 了 芽 ， 开 了 花 ， 上 头 的 葡 萄 都 成 熟 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1184', '1', '40', '11', '法 老 的 杯 在 我 手 中 ， 我 就 拿 葡 萄 挤 在 法 老 的 杯 里 ， 将 杯 递 在 他 手 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1185', '1', '40', '12', '约 瑟 对 他 说 ： “ 你 所 做 的 梦 是 这 样 解 ： 三 根 枝 子 就 是 三 天 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1186', '1', '40', '13', '三 天 之 内 ， 法 老 必 提 你 出 监 ， 叫 你 官 复 原 职 ， 你 仍 要 递 杯 在 法 老 的 手 中 ， 和 先 前 作 他 的 酒 政 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1187', '1', '40', '14', '但 你 得 好 处 的 时 候 ， 求 你 记 念 我 ， 施 恩 与 我 ， 在 法 老 面 前 提 说 我 ， 救 我 出 这 监 牢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1188', '1', '40', '15', '我 实 在 是 从 希 伯 来 人 之 地 被 拐 来 的 ； 我 在 这 里 也 没 有 做 过 什 么 ， 叫 他 们 把 我 下 在 监 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1189', '1', '40', '16', '膳 长 见 梦 解 得 好 ， 就 对 约 瑟 说 ： “ 我 在 梦 中 见 我 头 上 顶 着 三 筐 白 饼 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1190', '1', '40', '17', '极 上 的 筐 子 里 有 为 法 老 烤 的 各 样 食 物 ， 有 飞 鸟 来 吃 我 头 上 筐 子 里 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1191', '1', '40', '18', '约 瑟 说 ： “ 你 的 梦 是 这 样 解 ： 三 个 筐 子 就 是 三 天 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1192', '1', '40', '19', '三 天 之 内 ， 法 老 必 斩 断 你 的 头 ， 把 你 挂 在 木 头 上 ， 必 有 飞 鸟 来 吃 你 身 上 的 肉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1193', '1', '40', '20', '到 了 第 三 天 ， 是 法 老 的 生 日 ， 他 为 众 臣 仆 设 摆 筵 席 ， 把 酒 政 和 膳 长 提 出 监 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1194', '1', '40', '21', '使 酒 政 官 复 原 职 ， 他 仍 旧 递 杯 在 法 老 手 中 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1195', '1', '40', '22', '但 把 膳 长 挂 起 来 ， 正 如 约 瑟 向 他 们 所 解 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1196', '1', '40', '23', '酒 政 却 不 记 念 约 瑟 ， 竟 忘 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1197', '1', '41', '1', '＜ 约 瑟 为 法 老 解 梦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1198', '1', '41', '2', '有 七 只 母 牛 从 河 里 上 来 ， 又 美 好 又 肥 壮 ， 在 芦 荻 中 吃 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1199', '1', '41', '3', '随 后 又 有 七 只 母 牛 从 河 里 上 来 ， 又 丑 陋 又 干 瘦 ， 与 那 七 只 母 牛 一 同 站 在 河 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1200', '1', '41', '4', '这 又 丑 陋 又 干 瘦 的 七 只 母 牛 吃 尽 了 那 又 美 好 又 肥 壮 的 七 只 母 牛 。 法 老 就 醒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1201', '1', '41', '5', '他 又 睡 着 ， 第 二 回 做 梦 ， 梦 见 一 棵 麦 子 长 了 七 个 穗 子 ， 又 肥 大 又 佳 美 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1202', '1', '41', '6', '随 后 又 长 了 七 个 穗 子 ， 又 细 弱 又 被 东 风 吹 焦 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1203', '1', '41', '7', '这 细 弱 的 穗 子 吞 了 那 七 个 又 肥 大 又 饱 满 的 穗 子 。 法 老 醒 了 ， 不 料 是 个 梦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1204', '1', '41', '8', '到 了 早 晨 ， 法 老 心 里 不 安 ， 就 差 人 召 了 埃 及 所 有 的 术 士 和 博 士 来 ； 法 老 就 把 所 做 的 梦 告 诉 他 们 ， 却 没 有 人 能 给 法 老 圆 解 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1205', '1', '41', '9', '那 时 酒 政 对 法 老 说 ： “ 我 今 日 想 起 我 的 罪 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1206', '1', '41', '10', '从 前 法 老 恼 怒 臣 仆 ， 把 我 和 膳 长 下 在 护 卫 长 府 内 的 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1207', '1', '41', '11', '我 们 二 人 同 夜 各 做 一 梦 ， 各 梦 都 有 讲 解 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1208', '1', '41', '12', '在 那 里 同 着 我 们 有 一 个 希 伯 来 的 少 年 人 ， 是 护 卫 长 的 仆 人 ， 我 们 告 诉 他 ， 他 就 把 我 们 的 梦 圆 解 ， 是 按 着 各 人 的 梦 圆 解 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1209', '1', '41', '13', '后 来 正 如 他 给 我 们 圆 解 的 成 就 了 ： 我 官 复 原 职 ， 膳 长 被 挂 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1210', '1', '41', '14', '法 老 遂 即 差 人 去 召 约 瑟 ， 他 们 便 急 忙 带 他 出 监 ， 他 就 剃 头 ， 刮 脸 ， 换 衣 裳 ， 进 到 法 老 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1211', '1', '41', '15', '法 老 对 约 瑟 说 ： “ 我 做 了 一 梦 ， 没 有 人 能 解 ； 我 听 见 人 说 ， 你 听 了 梦 就 能 解 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1212', '1', '41', '16', '约 瑟 回 答 法 老 说 ： “ 这 不 在 乎 我 ， 神 必 将 平 安 的 话 回 答 法 老 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1213', '1', '41', '17', '法 老 对 约 瑟 说 ： “ 我 梦 见 我 站 在 河 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1214', '1', '41', '18', '有 七 只 母 牛 从 河 里 上 来 ， 又 肥 壮 又 美 好 ， 在 芦 荻 中 吃 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1215', '1', '41', '19', '随 后 又 有 七 只 母 牛 上 来 ， 又 软 弱 又 丑 陋 又 干 瘦 ， 在 埃 及 遍 地 ， 我 没 有 见 过 这 样 不 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1216', '1', '41', '20', '这 又 干 瘦 又 丑 陋 的 母 牛 吃 尽 了 那 以 先 的 七 只 肥 母 牛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1217', '1', '41', '21', '吃 了 以 后 却 看 不 出 是 吃 了 ， 那 丑 陋 的 样 子 仍 旧 和 先 前 一 样 。 我 就 醒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1218', '1', '41', '22', '我 又 梦 见 一 棵 麦 子 ， 长 了 七 个 穗 子 ， 又 饱 满 又 佳 美 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1219', '1', '41', '23', '随 后 又 长 了 七 个 穗 子 ， 枯 槁 细 弱 ， 被 东 风 吹 焦 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1220', '1', '41', '24', '这 些 细 弱 的 穗 子 吞 了 那 七 个 佳 美 的 穗 子 。 我 将 这 梦 告 诉 了 术 士 ， 却 没 有 人 能 给 我 解 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1221', '1', '41', '25', '约 瑟 对 法 老 说 ： “ 法 老 的 梦 乃 是 一 个 。 神 已 将 所 要 做 的 事 指 示 法 老 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1222', '1', '41', '26', '七 只 好 母 牛 是 七 年 ， 七 个 好 穗 子 也 是 七 年 ； 这 梦 乃 是 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1223', '1', '41', '27', '那 随 后 上 来 的 七 只 又 干 瘦 又 丑 陋 的 母 牛 是 七 年 ， 那 七 个 虚 空 、 被 东 风 吹 焦 的 穗 子 也 是 七 年 ， 都 是 七 个 荒 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1224', '1', '41', '28', '这 就 是 我 对 法 老 所 说 ， 神 已 将 所 要 做 的 事 显 明 给 法 老 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1225', '1', '41', '29', '埃 及 遍 地 必 来 七 个 大 丰 年 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1226', '1', '41', '30', '随 后 又 要 来 七 个 荒 年 ， 甚 至 在 埃 及 地 都 忘 了 先 前 的 丰 收 ， 全 地 必 被 饥 荒 所 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1227', '1', '41', '31', '因 那 以 后 的 饥 荒 甚 大 ， 便 不 觉 得 先 前 的 丰 收 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1228', '1', '41', '32', '至 于 法 老 两 回 做 梦 ， 是 因 神 命 定 这 事 ， 而 且 必 速 速 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1229', '1', '41', '33', '所 以 ， 法 老 当 拣 选 一 个 有 聪 明 有 智 慧 的 人 ， 派 他 治 理 埃 及 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1230', '1', '41', '34', '法 老 当 这 样 行 ， 又 派 官 员 管 理 这 地 。 当 七 个 丰 年 的 时 候 ， 征 收 埃 及 地 的 五 分 之 一 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1231', '1', '41', '35', '叫 他 们 把 将 来 丰 年 一 切 的 粮 食 聚 敛 起 来 ， 积 蓄 五 谷 ， 收 存 在 各 城 里 做 食 物 ， 归 于 法 老 的 手 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1232', '1', '41', '36', '所 积 蓄 的 粮 食 可 以 防 备 埃 及 地 将 来 的 七 个 荒 年 ， 免 得 这 地 被 饥 荒 所 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1233', '1', '41', '37', '＜ 约 瑟 被 立 为 埃 及 的 宰 相 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1234', '1', '41', '38', '法 老 对 臣 仆 说 ： “ 像 这 样 的 人 ， 有 神 的 灵 在 他 里 头 ， 我 们 岂 能 找 得 着 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1235', '1', '41', '39', '法 老 对 约 瑟 说 ： “ 神 既 将 这 事 都 指 示 你 ， 可 见 没 有 人 像 你 这 样 有 聪 明 有 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1236', '1', '41', '40', '你 可 以 掌 管 我 的 家 ； 我 的 民 都 必 听 从 你 的 话 。 惟 独 在 宝 座 上 我 比 你 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1237', '1', '41', '41', '法 老 又 对 约 瑟 说 ： “ 我 派 你 治 理 埃 及 全 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1238', '1', '41', '42', '法 老 就 摘 下 手 上 打 印 的 戒 指 ， 戴 在 约 瑟 的 手 上 ， 给 他 穿 上 细 麻 衣 ， 把 金 链 戴 在 他 的 颈 项 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1239', '1', '41', '43', '又 叫 约 瑟 坐 他 的 副 车 ， 喝 道 的 在 前 呼 叫 说 ： “ 跪 下 。 ” 这 样 ， 法 老 派 他 治 理 埃 及 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1240', '1', '41', '44', '法 老 对 约 瑟 说 ： “ 我 是 法 老 ， 在 埃 及 全 地 ， 若 没 有 你 的 命 令 ， 不 许 人 擅 自 办 事 ｛ 原 文 是 动 手 动 脚 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1241', '1', '41', '45', '法 老 赐 名 给 约 瑟 ， 叫 撒 发 那 忒 ． 巴 内 亚 ， 又 将 安 城 的 祭 司 波 提 非 拉 的 女 儿 亚 西 纳 给 他 为 妻 。 约 瑟 就 出 去 巡 行 埃 及 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1242', '1', '41', '46', '约 瑟 见 埃 及 王 法 老 的 时 候 年 三 十 岁 。 他 从 法 老 面 前 出 去 ， 遍 行 埃 及 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1243', '1', '41', '47', '七 个 丰 年 之 内 ， 地 的 出 产 极 丰 极 盛 ｛ 原 文 是 一 把 一 把 的 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1244', '1', '41', '48', '约 瑟 聚 敛 埃 及 地 七 个 丰 年 一 切 的 粮 食 ， 把 粮 食 积 存 在 各 城 里 ； 各 城 周 围 田 地 的 粮 食 都 积 存 在 本 城 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1245', '1', '41', '49', '约 瑟 积 蓄 五 谷 甚 多 ， 如 同 海 边 的 沙 ， 无 法 计 算 ， 因 为 谷 不 可 胜 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1246', '1', '41', '50', '荒 年 未 到 以 前 ， 安 城 的 祭 司 波 提 非 拉 的 女 儿 亚 西 纳 给 约 瑟 生 了 两 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1247', '1', '41', '51', '约 瑟 给 长 子 起 名 叫 玛 拿 西 ｛ 就 是 使 之 忘 了 的 意 思 ｝ ， 因 为 他 说 ： “ 神 使 我 忘 了 一 切 的 困 苦 和 我 父 的 全 家 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1248', '1', '41', '52', '他 给 次 子 起 名 叫 以 法 莲 ｛ 就 是 使 之 昌 盛 的 意 思 ｝ ， 因 为 他 说 ： “ 神 使 我 在 受 苦 的 地 方 昌 盛 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1249', '1', '41', '53', '埃 及 地 的 七 个 丰 年 一 完 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1250', '1', '41', '54', '七 个 荒 年 就 来 了 。 正 如 约 瑟 所 说 的 ， 各 地 都 有 饥 荒 ； 惟 独 埃 及 全 地 有 粮 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1251', '1', '41', '55', '及 至 埃 及 全 地 有 了 饥 荒 ， 众 民 向 法 老 哀 求 粮 食 ， 法 老 对 他 们 说 ： “ 你 们 往 约 瑟 那 里 去 ， 凡 他 所 说 的 ， 你 们 都 要 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1252', '1', '41', '56', '当 时 饥 荒 遍 满 天 下 ， 约 瑟 开 了 各 处 的 仓 ， 粜 粮 给 埃 及 人 ； 在 埃 及 地 饥 荒 甚 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1253', '1', '41', '57', '各 地 的 人 都 往 埃 及 去 ， 到 约 瑟 那 里 籴 粮 ， 因 为 天 下 的 饥 荒 甚 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1254', '1', '42', '1', '＜ 约 瑟 的 哥 哥 们 往 埃 及 买 粮 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1255', '1', '42', '2', '我 听 见 埃 及 有 粮 ， 你 们 可 以 下 去 ， 从 那 里 为 我 们 籴 些 来 ， 使 我 们 可 以 存 活 ， 不 至 于 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1256', '1', '42', '3', '于 是 ， 约 瑟 的 十 个 哥 哥 都 下 埃 及 籴 粮 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1257', '1', '42', '4', '但 约 瑟 的 兄 弟 便 雅 悯 ， 雅 各 没 有 打 发 他 和 哥 哥 们 同 去 ， 因 为 雅 各 说 ： “ 恐 怕 他 遭 害 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1258', '1', '42', '5', '来 籴 粮 的 人 中 有 以 色 列 的 儿 子 们 ， 因 为 迦 南 地 也 有 饥 荒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1259', '1', '42', '6', '当 时 治 理 埃 及 地 的 是 约 瑟 ； 粜 粮 给 那 地 众 民 的 就 是 他 。 约 瑟 的 哥 哥 们 来 了 ， 脸 伏 于 地 ， 向 他 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1260', '1', '42', '7', '约 瑟 看 见 他 哥 哥 们 ， 就 认 得 他 们 ， 却 装 作 生 人 ， 向 他 们 说 些 严 厉 话 ， 问 他 们 说 ： “ 你 们 从 哪 里 来 ？ ” 他 们 说 ： “ 我 们 从 迦 南 地 来 籴 粮 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1261', '1', '42', '8', '约 瑟 认 得 他 哥 哥 们 ， 他 们 却 不 认 得 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1262', '1', '42', '9', '约 瑟 想 起 从 前 所 做 的 那 两 个 梦 ， 就 对 他 们 说 ： “ 你 们 是 奸 细 ， 来 窥 探 这 地 的 虚 实 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1263', '1', '42', '10', '他 们 对 他 说 ： “ 我 主 啊 ， 不 是 的 。 仆 人 们 是 籴 粮 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1264', '1', '42', '11', '我 们 都 是 一 个 人 的 儿 子 ， 是 诚 实 人 ； 仆 人 们 并 不 是 奸 细 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1265', '1', '42', '12', '约 瑟 说 ： “ 不 然 ， 你 们 必 是 窥 探 这 地 的 虚 实 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1266', '1', '42', '13', '他 们 说 ： “ 仆 人 们 本 是 弟 兄 十 二 人 ， 是 迦 南 地 一 个 人 的 儿 子 ， 顶 小 的 现 今 在 我 们 的 父 亲 那 里 ， 有 一 个 没 有 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1267', '1', '42', '14', '约 瑟 说 ： “ 我 才 说 你 们 是 奸 细 ， 这 话 实 在 不 错 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1268', '1', '42', '15', '我 指 着 法 老 的 性 命 起 誓 ， 若 是 你 们 的 小 兄 弟 不 到 这 里 来 ， 你 们 就 不 得 出 这 地 方 ， 从 此 就 可 以 把 你 们 证 验 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1269', '1', '42', '16', '须 要 打 发 你 们 中 间 一 个 人 去 ， 把 你 们 的 兄 弟 带 来 。 至 于 你 们 ， 都 要 囚 在 这 里 ， 好 证 验 你 们 的 话 真 不 真 ， 若 不 真 ， 我 指 着 法 老 的 性 命 起 誓 ， 你 们 一 定 是 奸 细 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1270', '1', '42', '17', '于 是 约 瑟 把 他 们 都 下 在 监 里 三 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1271', '1', '42', '18', '到 第 三 天 ， 约 瑟 对 他 们 说 ： “ 我 是 敬 畏 神 的 ； 你 们 照 我 的 话 行 就 可 以 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1272', '1', '42', '19', '你 们 如 果 是 诚 实 人 ， 可 以 留 你 们 中 间 的 一 个 人 囚 在 监 里 ， 但 你 们 可 以 带 着 粮 食 回 去 ， 救 你 们 家 里 的 饥 荒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1273', '1', '42', '20', '把 你 们 的 小 兄 弟 带 到 我 这 里 来 ， 如 此 ， 你 们 的 话 便 有 证 据 ， 你 们 也 不 至 于 死 。 ” 他 们 就 照 样 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1274', '1', '42', '21', '他 们 彼 此 说 ： “ 我 们 在 兄 弟 身 上 实 在 有 罪 。 他 哀 求 我 们 的 时 候 ， 我 们 见 他 心 里 的 愁 苦 ， 却 不 肯 听 ， 所 以 这 场 苦 难 临 到 我 们 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1275', '1', '42', '22', '吕 便 说 ： “ 我 岂 不 是 对 你 们 说 过 ， 不 可 伤 害 那 孩 子 吗 ？ 只 是 你 们 不 肯 听 ， 所 以 流 他 血 的 罪 向 我 们 追 讨 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1276', '1', '42', '23', '他 们 不 知 道 约 瑟 听 得 出 来 ， 因 为 在 他 们 中 间 用 通 事 传 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1277', '1', '42', '24', '约 瑟 转 身 退 去 ， 哭 了 一 场 ， 又 回 来 对 他 们 说 话 ， 就 从 他 们 中 间 挑 出 西 缅 来 ， 在 他 们 眼 前 把 他 捆 绑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1278', '1', '42', '25', '＜ 约 瑟 的 哥 哥 们 回 迦 南 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1279', '1', '42', '26', '他 们 就 把 粮 食 驮 在 驴 上 ， 离 开 那 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1280', '1', '42', '27', '到 了 住 宿 的 地 方 ， 他 们 中 间 有 一 个 人 打 开 口 袋 ， 要 拿 料 喂 驴 ， 才 看 见 自 己 的 银 子 仍 在 口 袋 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1281', '1', '42', '28', '就 对 弟 兄 们 说 ： “ 我 的 银 子 归 还 了 ， 看 哪 ， 仍 在 我 口 袋 里 ！ ” 他 们 就 提 心 吊 胆 ， 战 战 兢 兢 地 彼 此 说 ： “ 这 是 神 向 我 们 做 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1282', '1', '42', '29', '他 们 来 到 迦 南 地 、 他 们 的 父 亲 雅 各 那 里 ， 将 所 遭 遇 的 事 都 告 诉 他 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1283', '1', '42', '30', '“ 那 地 的 主 对 我 们 说 严 厉 的 话 ， 把 我 们 当 作 窥 探 那 地 的 奸 细 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1284', '1', '42', '31', '我 们 对 他 说 ： ‘ 我 们 是 诚 实 人 ， 并 不 是 奸 细 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1285', '1', '42', '32', '我 们 本 是 弟 兄 十 二 人 ， 都 是 一 个 父 亲 的 儿 子 ， 有 一 个 没 有 了 ， 顶 小 的 如 今 同 我 们 的 父 亲 在 迦 南 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1286', '1', '42', '33', '那 地 的 主 对 我 们 说 ： ‘ 若 要 我 知 道 你 们 是 诚 实 人 ， 可 以 留 下 你 们 中 间 的 一 个 人 在 我 这 里 ， 你 们 可 以 带 着 粮 食 回 去 ， 救 你 们 家 里 的 饥 荒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1287', '1', '42', '34', '把 你 们 的 小 兄 弟 带 到 我 这 里 来 ， 我 便 知 道 你 们 不 是 奸 细 ， 乃 是 诚 实 人 。 这 样 ， 我 就 把 你 们 的 弟 兄 交 给 你 们 ， 你 们 也 可 以 在 这 地 做 买 卖 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1288', '1', '42', '35', '后 来 他 们 倒 口 袋 ， 不 料 ， 各 人 的 银 包 都 在 口 袋 里 ； 他 们 和 父 亲 看 见 银 包 就 都 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1289', '1', '42', '36', '他 们 的 父 亲 雅 各 对 他 们 说 ： “ 你 们 使 我 丧 失 我 的 儿 子 ： “ 约 瑟 没 有 了 ， 西 缅 也 没 有 了 ， 你 们 又 要 将 便 雅 悯 带 去 ； 这 些 事 都 归 到 我 身 上 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1290', '1', '42', '37', '吕 便 对 他 父 亲 说 ： “ 我 若 不 带 他 回 来 交 给 你 ， 你 可 以 杀 我 的 两 个 儿 子 。 只 管 把 他 交 在 我 手 里 ， 我 必 带 他 回 来 交 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1291', '1', '42', '38', '雅 各 说 ： “ 我 的 儿 子 不 可 与 你 们 一 同 下 去 ； 他 哥 哥 死 了 ， 只 剩 下 他 ， 他 若 在 你 们 所 行 的 路 上 遭 害 ， 那 便 是 你 们 使 我 白 发 苍 苍 、 悲 悲 惨 惨 地 下 阴 间 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1292', '1', '43', '1', '＜ 约 瑟 的 哥 哥 们 带 便 雅 悯 到 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1293', '1', '43', '2', '他 们 从 埃 及 带 来 的 粮 食 吃 尽 了 ， 他 们 的 父 亲 就 对 他 们 说 ： “ 你 们 再 去 给 我 籴 些 粮 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1294', '1', '43', '3', '犹 大 对 他 说 ： “ 那 人 谆 谆 地 告 诫 我 们 说 ： ‘ 你 们 的 兄 弟 若 不 与 你 们 同 来 ， 你 们 就 不 得 见 我 的 面 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1295', '1', '43', '4', '你 若 打 发 我 们 的 兄 弟 与 我 们 同 去 ， 我 们 就 下 去 给 你 籴 粮 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1296', '1', '43', '5', '你 若 不 打 发 他 去 ， 我 们 就 不 下 去 ， 因 为 那 人 对 我 们 说 ： ‘ 你 们 的 兄 弟 若 不 与 你 们 同 来 ， 你 们 就 不 得 见 我 的 面 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1297', '1', '43', '6', '以 色 列 说 ： “ 你 们 为 什 么 这 样 害 我 ， 告 诉 那 人 你 们 还 有 兄 弟 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1298', '1', '43', '7', '他 们 回 答 说 ： “ 那 人 详 细 问 到 我 们 和 我 们 的 亲 属 ， 说 ： ‘ 你 们 的 父 亲 还 在 吗 ？ 你 们 还 有 兄 弟 吗 ？ ’ 我 们 就 按 着 他 所 问 的 告 诉 他 ， 焉 能 知 道 他 要 说 ‘ 必 须 把 你 们 的 兄 弟 带 下 来 ’ 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1299', '1', '43', '8', '犹 大 又 对 他 父 亲 以 色 列 说 ： “ 你 打 发 童 子 与 我 同 去 ， 我 们 就 起 身 下 去 ， 好 叫 我 们 和 你 ， 并 我 们 的 妇 人 孩 子 ， 都 得 存 活 ， 不 至 于 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1300', '1', '43', '9', '我 为 他 作 保 ； 你 可 以 从 我 手 中 追 讨 ， 我 若 不 带 他 回 来 交 在 你 面 前 ， 我 情 愿 永 远 担 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1301', '1', '43', '10', '我 们 若 没 有 耽 搁 ， 如 今 第 二 次 都 回 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1302', '1', '43', '11', '他 们 的 父 亲 以 色 列 说 ： “ 若 必 须 如 此 ， 你 们 就 当 这 样 行 ： 可 以 将 这 地 土 产 中 最 好 的 乳 香 、 蜂 蜜 、 香 料 、 没 药 、 榧 子 、 杏 仁 都 取 一 点 ， 收 在 器 具 里 ， 带 下 去 送 给 那 人 作 礼 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1303', '1', '43', '12', '又 要 手 里 加 倍 地 带 银 子 ， 并 将 归 还 在 你 们 口 袋 内 的 银 子 仍 带 在 手 里 ； 那 或 者 是 错 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1304', '1', '43', '13', '也 带 着 你 们 的 兄 弟 ， 起 身 去 见 那 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1305', '1', '43', '14', '但 愿 全 能 的 神 使 你 们 在 那 人 面 前 蒙 怜 悯 ， 释 放 你 们 的 那 弟 兄 和 便 雅 悯 回 来 。 我 若 丧 了 儿 子 ， 就 丧 了 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1306', '1', '43', '15', '于 是 ， 他 们 拿 着 那 礼 物 ， 又 手 里 加 倍 地 带 银 子 ， 并 且 带 着 便 雅 悯 ， 起 身 下 到 埃 及 ， 站 在 约 瑟 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1307', '1', '43', '16', '约 瑟 见 便 雅 悯 和 他 们 同 来 ， 就 对 家 宰 说 ： “ 将 这 些 人 领 到 屋 里 。 要 宰 杀 牲 畜 ， 预 备 筵 席 ， 因 为 晌 午 这 些 人 同 我 吃 饭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1308', '1', '43', '17', '家 宰 就 遵 着 约 瑟 的 命 去 行 ， 领 他 们 进 约 瑟 的 屋 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1309', '1', '43', '18', '他 们 因 为 被 领 到 约 瑟 的 屋 里 ， 就 害 怕 ， 说 ： “ 领 我 们 到 这 里 来 ， 必 是 因 为 头 次 归 还 在 我 们 口 袋 里 的 银 子 ， 找 我 们 的 错 缝 ， 下 手 害 我 们 ， 强 取 我 们 为 奴 仆 ， 抢 夺 我 们 的 驴 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1310', '1', '43', '19', '他 们 就 挨 近 约 瑟 的 家 宰 ， 在 屋 门 口 和 他 说 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1311', '1', '43', '20', '说 ： “ 我 主 啊 ， 我 们 头 次 下 来 实 在 是 要 籴 粮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1312', '1', '43', '21', '后 来 到 了 住 宿 的 地 方 ， 我 们 打 开 口 袋 ， 不 料 ， 各 人 的 银 子 ， 分 量 足 数 ， 仍 在 各 人 的 口 袋 内 ， 现 在 我 们 手 里 又 带 回 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1313', '1', '43', '22', '另 外 又 带 下 银 子 来 籴 粮 。 不 知 道 先 前 谁 把 银 子 放 在 我 们 的 口 袋 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1314', '1', '43', '23', '家 宰 说 ： “ 你 们 可 以 放 心 ， 不 要 害 怕 ， 是 你 们 的 神 和 你 们 父 亲 的 神 赐 给 你 们 财 宝 在 你 们 的 口 袋 里 ； 你 们 的 银 子 ， 我 早 已 收 了 。 ” 他 就 把 西 缅 带 出 来 ， 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1315', '1', '43', '24', '家 宰 就 领 他 们 进 约 瑟 的 屋 里 ， 给 他 们 水 洗 脚 ， 又 给 他 们 草 料 喂 驴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1316', '1', '43', '25', '他 们 就 预 备 那 礼 物 ， 等 候 约 瑟 晌 午 来 ， 因 为 他 们 听 见 要 在 那 里 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1317', '1', '43', '26', '约 瑟 来 到 家 里 ， 他 们 就 把 手 中 的 礼 物 拿 进 屋 去 给 他 ， 又 俯 伏 在 地 ， 向 他 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1318', '1', '43', '27', '约 瑟 问 他 们 好 ， 又 问 ： “ 你 们 的 父 亲 ─ ─ 就 是 你 们 所 说 的 那 老 人 家 平 安 吗 ？ 他 还 在 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1319', '1', '43', '28', '他 们 回 答 说 ： “ 你 仆 人 ─ ─ 我 们 的 父 亲 平 安 ； 他 还 在 。 ” 于 是 他 们 低 头 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1320', '1', '43', '29', '约 瑟 举 目 看 见 他 同 母 的 兄 弟 便 雅 悯 ， 就 说 ： “ 你 们 向 我 所 说 那 顶 小 的 兄 弟 就 是 这 位 吗 ？ ” 又 说 ： “ 小 儿 啊 ， 愿 神 赐 恩 给 你 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1321', '1', '43', '30', '约 瑟 爱 弟 之 情 发 动 ， 就 急 忙 寻 找 可 哭 之 地 ， 进 入 自 己 的 屋 里 ， 哭 了 一 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1322', '1', '43', '31', '他 洗 了 脸 出 来 ， 勉 强 隐 忍 ， 吩 咐 人 摆 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1323', '1', '43', '32', '他 们 就 为 约 瑟 单 摆 了 一 席 ， 为 那 些 人 又 摆 了 一 席 ， 也 为 和 约 瑟 同 吃 饭 的 埃 及 人 另 摆 了 一 席 ， 因 为 埃 及 人 不 可 和 希 伯 来 人 一 同 吃 饭 ； 那 原 是 埃 及 人 所 厌 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1324', '1', '43', '33', '约 瑟 使 众 弟 兄 在 他 面 前 排 列 坐 席 ， 都 按 着 长 幼 的 次 序 ， 众 弟 兄 就 彼 此 诧 异 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1325', '1', '43', '34', '约 瑟 把 他 面 前 的 食 物 分 出 来 ， 送 给 他 们 ； 但 便 雅 悯 所 得 的 比 别 人 多 五 倍 。 他 们 就 饮 酒 ， 和 约 瑟 一 同 宴 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1326', '1', '44', '1', '＜ 失 落 的 杯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1327', '1', '44', '2', '并 将 我 的 银 杯 和 那 少 年 人 籴 粮 的 银 子 一 同 装 在 他 的 口 袋 里 。 ” 家 宰 就 照 约 瑟 所 说 的 话 行 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1328', '1', '44', '3', '天 一 亮 就 打 发 那 些 人 带 着 驴 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1329', '1', '44', '4', '他 们 出 城 走 了 不 远 ， 约 瑟 对 家 宰 说 ： “ 起 来 ， 追 那 些 人 去 ， 追 上 了 就 对 他 们 说 ： ‘ 你 们 为 什 么 以 恶 报 善 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1330', '1', '44', '5', '这 不 是 我 主 人 饮 酒 的 杯 吗 ？ 岂 不 是 他 占 卜 用 的 吗 ？ 你 们 这 样 行 是 作 恶 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1331', '1', '44', '6', '家 宰 追 上 他 们 ， 将 这 些 话 对 他 们 说 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1332', '1', '44', '7', '他 们 回 答 说 ： “ 我 主 为 什 么 说 这 样 的 话 呢 ？ 你 仆 人 断 不 能 做 这 样 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1333', '1', '44', '8', '你 看 ， 我 们 从 前 在 口 袋 里 所 见 的 银 子 ， 尚 且 从 迦 南 地 带 来 还 你 ， 我 们 怎 能 从 你 主 人 家 里 偷 窃 金 银 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1334', '1', '44', '9', '你 仆 人 中 无 论 在 谁 那 里 搜 出 来 ， 就 叫 他 死 ， 我 们 也 作 我 主 的 奴 仆 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1335', '1', '44', '10', '家 宰 说 ： “ 现 在 就 照 你 们 的 话 行 吧 ！ 在 谁 那 里 搜 出 来 ， 谁 就 作 我 的 奴 仆 ； 其 余 的 都 没 有 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1336', '1', '44', '11', '于 是 他 们 各 人 急 忙 把 口 袋 卸 在 地 下 ， 各 人 打 开 口 袋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1337', '1', '44', '12', '家 宰 就 搜 查 ， 从 年 长 的 起 到 年 幼 的 为 止 ， 那 杯 竟 在 便 雅 悯 的 口 袋 里 搜 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1338', '1', '44', '13', '他 们 就 撕 裂 衣 服 ， 各 人 把 驮 子 抬 在 驴 上 ， 回 城 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1339', '1', '44', '14', '犹 大 和 他 弟 兄 们 来 到 约 瑟 的 屋 中 ， 约 瑟 还 在 那 里 ， 他 们 就 在 他 面 前 俯 伏 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1340', '1', '44', '15', '约 瑟 对 他 们 说 ： “ 你 们 做 的 是 什 么 事 呢 ？ 你 们 岂 不 知 像 我 这 样 的 人 必 能 占 卜 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1341', '1', '44', '16', '犹 大 说 ： “ 我 们 对 我 主 说 什 么 呢 ？ 还 有 什 么 话 可 说 呢 ？ 我 们 怎 能 自 己 表 白 出 来 呢 ？ 神 已 经 查 出 仆 人 的 罪 孽 了 。 我 们 与 那 在 他 手 中 搜 出 杯 来 的 都 是 我 主 的 奴 仆 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1342', '1', '44', '17', '约 瑟 说 ： “ 我 断 不 能 这 样 行 ！ 在 谁 的 手 中 搜 出 杯 来 ， 谁 就 作 我 的 奴 仆 ； 至 于 你 们 ， 可 以 平 平 安 安 地 上 你 们 父 亲 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1343', '1', '44', '18', '＜ 犹 大 替 便 雅 悯 哀 求 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1344', '1', '44', '19', '我 主 曾 问 仆 人 们 说 ： ‘ 你 们 有 父 亲 有 兄 弟 没 有 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1345', '1', '44', '20', '我 们 对 我 主 说 ： ‘ 我 们 有 父 亲 ， 已 经 年 老 ， 还 有 他 老 年 所 生 的 一 个 小 孩 子 。 他 哥 哥 死 了 ， 他 母 亲 只 撇 下 他 一 人 ， 他 父 亲 疼 爱 他 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1346', '1', '44', '21', '你 对 仆 人 说 ： ‘ 把 他 带 到 我 这 里 来 ， 叫 我 亲 眼 看 看 他 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1347', '1', '44', '22', '我 们 对 我 主 说 ： ‘ 童 子 不 能 离 开 他 父 亲 ， 若 是 离 开 ， 他 父 亲 必 死 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1348', '1', '44', '23', '你 对 仆 人 说 ： ‘ 你 们 的 小 兄 弟 若 不 与 你 们 一 同 下 来 ， 你 们 就 不 得 再 见 我 的 面 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1349', '1', '44', '24', '我 们 上 到 你 仆 人 ─ ─ 我 们 父 亲 那 里 ， 就 把 我 主 的 话 告 诉 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1350', '1', '44', '25', '我 们 的 父 亲 说 ： ‘ 你 们 再 去 给 我 籴 些 粮 来 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1351', '1', '44', '26', '我 们 就 说 ： ‘ 我 们 不 能 下 去 。 我 们 的 小 兄 弟 若 和 我 们 同 往 ， 我 们 就 可 以 下 去 。 因 为 ， 小 兄 弟 若 不 与 我 们 同 往 ， 我 们 必 不 得 见 那 人 的 面 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1352', '1', '44', '27', '你 仆 人 ─ ─ 我 父 亲 对 我 们 说 ： ‘ 你 们 知 道 我 的 妻 子 给 我 生 了 两 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1353', '1', '44', '28', '一 个 离 开 我 出 去 了 ； 我 说 他 必 是 被 撕 碎 了 ， 直 到 如 今 我 也 没 有 见 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1354', '1', '44', '29', '现 在 你 们 又 要 把 这 个 带 去 离 开 我 ， 倘 若 他 遭 害 ， 那 便 是 你 们 使 我 白 发 苍 苍 、 悲 悲 惨 惨 地 下 阴 间 去 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1355', '1', '44', '30', '我 父 亲 的 命 与 这 童 子 的 命 相 连 。 如 今 我 回 到 你 仆 人 ─ ─ 我 父 亲 那 里 ， 若 没 有 童 子 与 我 们 同 在 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1356', '1', '44', '31', '我 们 的 父 亲 见 没 有 童 子 ， 他 就 必 死 。 这 便 是 我 们 使 你 仆 人 ─ ─ 我 们 的 父 亲 白 发 苍 苍 、 悲 悲 惨 惨 地 下 阴 间 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1357', '1', '44', '32', '因 为 仆 人 曾 向 我 父 亲 为 这 童 子 作 保 ， 说 ： ‘ 我 若 不 带 他 回 来 交 给 父 亲 ， 我 便 在 父 亲 面 前 永 远 担 罪 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1358', '1', '44', '33', '现 在 求 你 容 仆 人 住 下 ， 替 这 童 子 作 我 主 的 奴 仆 ， 叫 童 子 和 他 哥 哥 们 一 同 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1359', '1', '44', '34', '若 童 子 不 和 我 同 去 ， 我 怎 能 上 去 见 我 父 亲 呢 ？ 恐 怕 我 看 见 灾 祸 临 到 我 父 亲 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1360', '1', '45', '1', '＜ 约 瑟 和 兄 弟 相 认 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1361', '1', '45', '2', '他 就 放 声 大 哭 ； 埃 及 人 和 法 老 家 中 的 人 都 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1362', '1', '45', '3', '约 瑟 对 他 弟 兄 们 说 ： “ 我 是 约 瑟 。 我 的 父 亲 还 在 吗 ？ ” 他 弟 兄 不 能 回 答 ， 因 为 在 他 面 前 都 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1363', '1', '45', '4', '约 瑟 又 对 他 弟 兄 们 说 ： “ 请 你 们 近 前 来 。 ” 他 们 就 近 前 来 。 他 说 ： “ 我 是 你 们 的 兄 弟 约 瑟 ， 就 是 你 们 所 卖 到 埃 及 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1364', '1', '45', '5', '现 在 ， 不 要 因 为 把 我 卖 到 这 里 自 忧 自 恨 。 这 是 神 差 我 在 你 们 以 先 来 ， 为 要 保 全 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1365', '1', '45', '6', '现 在 这 地 的 饥 荒 已 经 二 年 了 ， 还 有 五 年 不 能 耕 种 ， 不 能 收 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1366', '1', '45', '7', '神 差 我 在 你 们 以 先 来 ， 为 要 给 你 们 存 留 余 种 在 世 上 ， 又 要 大 施 拯 救 ， 保 全 你 们 的 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1367', '1', '45', '8', '这 样 看 来 ， 差 我 到 这 里 来 的 不 是 你 们 ， 乃 是 神 。 他 又 使 我 如 法 老 的 父 ， 作 他 全 家 的 主 ， 并 埃 及 全 地 的 宰 相 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1368', '1', '45', '9', '你 们 要 赶 紧 上 到 我 父 亲 那 里 ， 对 他 说 ： ‘ 你 儿 子 约 瑟 这 样 说 ：   神 使 我 作 全 埃 及 的 主 ， 请 你 下 到 我 这 里 来 ， 不 要 耽 延 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1369', '1', '45', '10', '你 和 你 的 儿 子 孙 子 ， 连 牛 群 羊 群 ， 并 一 切 所 有 的 ， 都 可 以 住 在 歌 珊 地 ， 与 我 相 近 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1370', '1', '45', '11', '我 要 在 那 里 奉 养 你 ； 因 为 还 有 五 年 的 饥 荒 ， 免 得 你 和 你 的 眷 属 ， 并 一 切 所 有 的 ， 都 败 落 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1371', '1', '45', '12', '况 且 你 们 的 眼 和 我 兄 弟 便 雅 悯 的 眼 都 看 见 是 我 亲 口 对 你 们 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1372', '1', '45', '13', '你 们 也 要 将 我 在 埃 及 一 切 的 荣 耀 和 你 们 所 看 见 的 事 都 告 诉 我 父 亲 ， 又 要 赶 紧 地 将 我 父 亲 搬 到 我 这 里 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1373', '1', '45', '14', '于 是 约 瑟 伏 在 他 兄 弟 便 雅 悯 的 颈 项 上 哭 ， 便 雅 悯 也 在 他 的 颈 项 上 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1374', '1', '45', '15', '他 又 与 众 弟 兄 亲 嘴 ， 抱 着 他 们 哭 ， 随 后 他 弟 兄 们 就 和 他 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1375', '1', '45', '16', '这 风 声 传 到 法 老 的 宫 里 ， 说 ： “ 约 瑟 的 弟 兄 们 来 了 。 ” 法 老 和 他 的 臣 仆 都 很 喜 欢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1376', '1', '45', '17', '法 老 对 约 瑟 说 ： “ 你 吩 咐 你 的 弟 兄 们 说 ： ‘ 你 们 要 这 样 行 ： 把 驮 子 抬 在 牲 口 上 ， 起 身 往 迦 南 地 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1377', '1', '45', '18', '将 你 们 的 父 亲 和 你 们 的 眷 属 都 搬 到 我 这 里 来 ， 我 要 把 埃 及 地 的 美 物 赐 给 你 们 ， 你 们 也 要 吃 这 地 肥 美 的 出 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1378', '1', '45', '19', '现 在 我 吩 咐 你 们 要 这 样 行 ： 从 埃 及 地 带 着 车 辆 去 ， 把 你 们 的 孩 子 和 妻 子 ， 并 你 们 的 父 亲 都 搬 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1379', '1', '45', '20', '你 们 眼 中 不 要 爱 惜 你 们 的 家 具 ， 因 为 埃 及 全 地 的 美 物 都 是 你 们 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1380', '1', '45', '21', '以 色 列 的 儿 子 们 就 如 此 行 。 约 瑟 照 着 法 老 的 吩 咐 给 他 们 车 辆 和 路 上 用 的 食 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1381', '1', '45', '22', '又 给 他 们 各 人 一 套 衣 服 ， 惟 独 给 便 雅 悯 三 百 银 子 ， 五 套 衣 服 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1382', '1', '45', '23', '送 给 他 父 亲 公 驴 十 匹 ， 驮 着 埃 及 的 美 物 ， 母 驴 十 匹 ， 驮 着 粮 食 与 饼 和 菜 ， 为 他 父 亲 路 上 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1383', '1', '45', '24', '于 是 约 瑟 打 发 他 弟 兄 们 回 去 ， 又 对 他 们 说 ： “ 你 们 不 要 在 路 上 相 争 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1384', '1', '45', '25', '他 们 从 埃 及 上 去 ， 来 到 迦 南 地 、 他 们 的 父 亲 雅 各 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1385', '1', '45', '26', '告 诉 他 说 ： “ 约 瑟 还 在 ， 并 且 作 埃 及 全 地 的 宰 相 。 ” 雅 各 心 里 冰 凉 ， 因 为 不 信 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1386', '1', '45', '27', '他 们 便 将 约 瑟 对 他 们 说 的 一 切 话 都 告 诉 了 他 。 他 们 父 亲 雅 各 又 看 见 约 瑟 打 发 来 接 他 的 车 辆 ， 心 就 苏 醒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1387', '1', '45', '28', '以 色 列 说 ： “ 罢 了 ！ 罢 了 ！ 我 的 儿 子 约 瑟 还 在 ， 趁 我 未 死 以 先 ， 我 要 去 见 他 一 面 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1388', '1', '46', '1', '＜ 雅 各 带 家 属 到 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1389', '1', '46', '2', '夜 间 ， 神 在 异 象 中 对 以 色 列 说 ： “ 雅 各 ！ 雅 各 ！ ” 他 说 ： “ 我 在 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1390', '1', '46', '3', '神 说 ： “ 我 是 神 ， 就 是 你 父 亲 的 神 。 你 下 埃 及 去 不 要 害 怕 ， 因 为 我 必 使 你 在 那 里 成 为 大 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1391', '1', '46', '4', '我 要 和 你 同 下 埃 及 去 ， 也 必 定 带 你 上 来 ； 约 瑟 必 给 你 送 终 ｛ 原 文 是 将 手 按 在 你 的 眼 睛 上 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1392', '1', '46', '5', '雅 各 就 从 别 是 巴 起 行 。 以 色 列 的 儿 子 们 使 他 们 的 父 亲 雅 各 和 他 们 的 妻 子 、 儿 女 都 坐 在 法 老 为 雅 各 送 来 的 车 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1393', '1', '46', '6', '他 们 又 带 着 迦 南 地 所 得 的 牲 畜 、 货 财 来 到 埃 及 。 雅 各 和 他 的 一 切 子 孙 都 一 同 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1394', '1', '46', '7', '雅 各 把 他 的 儿 子 、 孙 子 、 女 儿 、 孙 女 ， 并 他 的 子 子 孙 孙 ， 一 同 带 到 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1395', '1', '46', '8', '来 到 埃 及 的 以 色 列 人 名 字 记 在 下 面 。 雅 各 和 他 的 儿 孙 ： 雅 各 的 长 子 是 吕 便 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1396', '1', '46', '9', '吕 便 的 儿 子 是 哈 诺 、 法 路 、 希 斯 伦 、 迦 米 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1397', '1', '46', '10', '西 缅 的 儿 子 是 耶 母 利 、 雅 悯 、 阿 辖 、 雅 斤 、 琐 辖 ， 还 有 迦 南 女 子 所 生 的 扫 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1398', '1', '46', '11', '利 未 的 儿 子 是 革 顺 、 哥 辖 、 米 拉 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1399', '1', '46', '12', '犹 大 的 儿 子 是 珥 、 俄 南 、 示 拉 、 法 勒 斯 、 谢 拉 ； 惟 有 珥 与 俄 南 死 在 迦 南 地 。 法 勒 斯 的 儿 子 是 希 斯 伦 、 哈 母 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1400', '1', '46', '13', '以 萨 迦 的 儿 子 是 陀 拉 、 普 瓦 、 约 伯 、 伸 仑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1401', '1', '46', '14', '西 布 伦 的 儿 子 是 西 烈 、 以 伦 、 雅 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1402', '1', '46', '15', '这 是 利 亚 在 巴 旦 ． 亚 兰 给 雅 各 所 生 的 儿 子 ， 还 有 女 儿 底 拿 。 儿 孙 共 三 十 三 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1403', '1', '46', '16', '迦 得 的 儿 子 是 洗 非 芸 、 哈 基 、 书 尼 、 以 斯 本 、 以 利 、 亚 罗 底 、 亚 列 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1404', '1', '46', '17', '亚 设 的 儿 子 是 音 拿 、 亦 施 瓦 、 亦 施 韦 、 比 利 亚 ， 还 有 他 们 的 妹 子 西 拉 。 比 利 亚 的 儿 子 是 希 别 、 玛 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1405', '1', '46', '18', '这 是 拉 班 给 他 女 儿 利 亚 的 婢 女 悉 帕 从 雅 各 所 生 的 儿 孙 ， 共 有 十 六 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1406', '1', '46', '19', '雅 各 之 妻 拉 结 的 儿 子 是 约 瑟 和 便 雅 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1407', '1', '46', '20', '约 瑟 在 埃 及 地 生 了 玛 拿 西 和 以 法 莲 ， 就 是 安 城 的 祭 司 波 提 非 拉 的 女 儿 亚 西 纳 给 约 瑟 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1408', '1', '46', '21', '便 雅 悯 的 儿 子 是 比 拉 、 比 结 、 亚 实 别 、 基 拉 、 乃 幔 、 以 希 、 罗 实 、 母 平 、 户 平 、 亚 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1409', '1', '46', '22', '这 是 拉 结 给 雅 各 所 生 的 儿 孙 ， 共 有 十 四 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1410', '1', '46', '23', '但 的 儿 子 是 户 伸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1411', '1', '46', '24', '拿 弗 他 利 的 儿 子 是 雅 薛 、 沽 尼 、 耶 色 、 示 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1412', '1', '46', '25', '这 是 拉 班 给 他 女 儿 拉 结 的 婢 女 辟 拉 从 雅 各 所 生 的 儿 孙 ， 共 有 七 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1413', '1', '46', '26', '那 与 雅 各 同 到 埃 及 的 ， 除 了 他 儿 妇 之 外 ， 凡 从 他 所 生 的 ， 共 有 六 十 六 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1414', '1', '46', '27', '还 有 约 瑟 在 埃 及 所 生 的 两 个 儿 子 。 雅 各 家 来 到 埃 及 的 共 有 七 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1415', '1', '46', '28', '＜ 雅 各 和 家 属 在 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1416', '1', '46', '29', '约 瑟 套 车 往 歌 珊 去 ， 迎 接 他 父 亲 以 色 列 ， 及 至 见 了 面 ， 就 伏 在 父 亲 的 颈 项 上 ， 哭 了 许 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1417', '1', '46', '30', '以 色 列 对 约 瑟 说 ： “ 我 既 得 见 你 的 面 ， 知 道 你 还 在 ， 就 是 死 我 也 甘 心 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1418', '1', '46', '31', '约 瑟 对 他 的 弟 兄 和 他 父 的 全 家 说 ： “ 我 要 上 去 告 诉 法 老 ， 对 他 说 ： ‘ 我 的 弟 兄 和 我 父 的 全 家 从 前 在 迦 南 地 ， 现 今 都 到 我 这 里 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1419', '1', '46', '32', '他 们 本 是 牧 羊 的 人 ， 以 养 牲 畜 为 业 ； 他 们 把 羊 群 牛 群 和 一 切 所 有 的 都 带 来 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1420', '1', '46', '33', '等 法 老 召 你 们 的 时 候 ， 问 你 们 说 ： ‘ 你 们 以 何 事 为 业 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1421', '1', '46', '34', '你 们 要 说 ： ‘ 你 的 仆 人 ， 从 幼 年 直 到 如 今 ， 都 以 养 牲 畜 为 业 ， 连 我 们 的 祖 宗 也 都 以 此 为 业 。 ’ 这 样 ， 你 们 可 以 住 在 歌 珊 地 ， 因 为 凡 牧 羊 的 都 被 埃 及 人 所 厌 恶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1422', '1', '47', '1', '约 瑟 进 去 告 诉 法 老 说 ： “ 我 的 父 亲 和 我 的 弟 兄 带 着 羊 群 牛 群 ， 并 一 切 所 有 的 ， 从 迦 南 地 来 了 ， 如 今 在 歌 珊 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1423', '1', '47', '2', '约 瑟 从 他 弟 兄 中 挑 出 五 个 人 来 ， 引 他 们 去 见 法 老 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1424', '1', '47', '3', '法 老 问 约 瑟 的 弟 兄 说 ： “ 你 们 以 何 事 为 业 ？ ” 他 们 对 法 老 说 ： “ 你 仆 人 是 牧 羊 的 ， 连 我 们 的 祖 宗 也 是 牧 羊 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1425', '1', '47', '4', '他 们 又 对 法 老 说 ： “ 迦 南 地 的 饥 荒 甚 大 ， 仆 人 的 羊 群 没 有 草 吃 ， 所 以 我 们 来 到 这 地 寄 居 。 现 在 求 你 容 仆 人 住 在 歌 珊 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1426', '1', '47', '5', '法 老 对 约 瑟 说 ： “ 你 父 亲 和 你 弟 兄 到 你 这 里 来 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1427', '1', '47', '6', '埃 及 地 都 在 你 面 前 ， 只 管 叫 你 父 亲 和 你 弟 兄 住 在 国 中 最 好 的 地 ； 他 们 可 以 住 在 歌 珊 地 。 你 若 知 道 他 们 中 间 有 什 么 能 人 ， 就 派 他 们 看 管 我 的 牲 畜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1428', '1', '47', '7', '约 瑟 领 他 父 亲 雅 各 进 到 法 老 面 前 ， 雅 各 就 给 法 老 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1429', '1', '47', '8', '法 老 问 雅 各 说 ： “ 你 平 生 的 年 日 是 多 少 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1430', '1', '47', '9', '雅 各 对 法 老 说 ： “ 我 寄 居 在 世 的 年 日 是 一 百 三 十 岁 ， 我 平 生 的 年 日 又 少 又 苦 ， 不 及 我 列 祖 在 世 寄 居 的 年 日 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1431', '1', '47', '10', '雅 各 又 给 法 老 祝 福 ， 就 从 法 老 面 前 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1432', '1', '47', '11', '约 瑟 遵 着 法 老 的 命 ， 把 埃 及 国 最 好 的 地 ， 就 是 兰 塞 境 内 的 地 ， 给 他 父 亲 和 弟 兄 居 住 ， 作 为 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1433', '1', '47', '12', '约 瑟 用 粮 食 奉 养 他 父 亲 和 他 弟 兄 ， 并 他 父 亲 全 家 的 眷 属 ， 都 是 照 各 家 的 人 口 奉 养 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1434', '1', '47', '13', '＜ 饥 荒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1435', '1', '47', '14', '约 瑟 收 聚 了 埃 及 地 和 迦 南 地 所 有 的 银 子 ， 就 是 众 人 籴 粮 的 银 子 ， 约 瑟 就 把 那 银 子 带 到 法 老 的 宫 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1436', '1', '47', '15', '埃 及 地 和 迦 南 地 的 银 子 都 花 尽 了 ， 埃 及 众 人 都 来 见 约 瑟 ， 说 ： “ 我 们 的 银 子 都 用 尽 了 ， 求 你 给 我 们 粮 食 ， 我 们 为 什 么 死 在 你 面 前 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1437', '1', '47', '16', '约 瑟 说 ： “ 若 是 银 子 用 尽 了 ， 可 以 把 你 们 的 牲 畜 给 我 ， 我 就 为 你 们 的 牲 畜 给 你 们 粮 食 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1438', '1', '47', '17', '于 是 他 们 把 牲 畜 赶 到 约 瑟 那 里 ， 约 瑟 就 拿 粮 食 换 了 他 们 的 牛 、 羊 、 驴 、 马 ； 那 一 年 因 换 他 们 一 切 的 牲 畜 ， 就 用 粮 食 养 活 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1439', '1', '47', '18', '那 一 年 过 去 ， 第 二 年 他 们 又 来 见 约 瑟 ， 说 ： “ 我 们 不 瞒 我 主 ， 我 们 的 银 子 都 花 尽 了 ， 牲 畜 也 都 归 了 我 主 。 我 们 在 我 主 眼 前 ， 除 了 我 们 的 身 体 和 田 地 之 外 ， 一 无 所 剩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1440', '1', '47', '19', '你 何 忍 见 我 们 人 死 地 荒 呢 ？ 求 你 用 粮 食 买 我 们 和 我 们 的 地 ， 我 们 和 我 们 的 地 就 要 给 法 老 效 力 。 又 求 你 给 我 们 种 子 ， 使 我 们 得 以 存 活 ， 不 致 死 亡 ， 地 土 也 不 致 荒 凉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1441', '1', '47', '20', '于 是 ， 约 瑟 为 法 老 买 了 埃 及 所 有 的 地 ， 埃 及 人 因 被 饥 荒 所 迫 ， 各 都 卖 了 自 己 的 田 地 ； 那 地 就 都 归 了 法 老 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1442', '1', '47', '21', '至 于 百 姓 ， 约 瑟 叫 他 们 ， 从 埃 及 这 边 直 到 埃 及 那 边 ， 都 各 归 各 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1443', '1', '47', '22', '惟 有 祭 司 的 地 ， 约 瑟 没 有 买 ， 因 为 祭 司 有 从 法 老 所 得 的 常 俸 。 他 们 吃 法 老 所 给 的 常 俸 ， 所 以 他 们 不 卖 自 己 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1444', '1', '47', '23', '约 瑟 对 百 姓 说 ： “ 我 今 日 为 法 老 买 了 你 们 和 你 们 的 地 ， 看 哪 ， 这 里 有 种 子 给 你 们 ， 你 们 可 以 种 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1445', '1', '47', '24', '后 来 打 粮 食 的 时 候 ， 你 们 要 把 五 分 之 一 纳 给 法 老 ， 四 分 可 以 归 你 们 做 地 里 的 种 子 ， 也 做 你 们 和 你 们 家 口 孩 童 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1446', '1', '47', '25', '他 们 说 ： “ 你 救 了 我 们 的 性 命 。 但 愿 我 们 在 我 主 眼 前 蒙 恩 ， 我 们 就 作 法 老 的 仆 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1447', '1', '47', '26', '于 是 约 瑟 为 埃 及 地 定 下 常 例 ， 直 到 今 日 ： 法 老 必 得 五 分 之 一 ， 惟 独 祭 司 的 地 不 归 法 老 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1448', '1', '47', '27', '＜ 雅 各 最 后 的 吩 咐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1449', '1', '47', '28', '雅 各 住 在 埃 及 地 十 七 年 ， 雅 各 平 生 的 年 日 是 一 百 四 十 七 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1450', '1', '47', '29', '以 色 列 的 死 期 临 近 了 ， 他 就 叫 了 他 儿 子 约 瑟 来 ， 说 ： “ 我 若 在 你 眼 前 蒙 恩 ， 请 你 把 手 放 在 我 大 腿 底 下 ， 用 慈 爱 和 诚 实 待 我 ， 请 你 不 要 将 我 葬 在 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1451', '1', '47', '30', '我 与 我 祖 我 父 同 睡 的 时 候 ， 你 要 将 我 带 出 埃 及 ， 葬 在 他 们 所 葬 的 地 方 。 ” 约 瑟 说 ： “ 我 必 遵 着 你 的 命 而 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1452', '1', '47', '31', '雅 各 说 ： “ 你 要 向 我 起 誓 。 ” 约 瑟 就 向 他 起 了 誓 ， 于 是 以 色 列 在 床 头 上 ｛ 或 译 ： 扶 着 杖 头 ｝ 敬 拜 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1453', '1', '48', '1', '＜ 雅 各 祝 福 以 法 莲 和 玛 拿 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1454', '1', '48', '2', '有 人 告 诉 雅 各 说 ： “ 请 看 ， 你 儿 子 约 瑟 到 你 这 里 来 了 。 ” 以 色 列 就 勉 强 在 床 上 坐 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1455', '1', '48', '3', '雅 各 对 约 瑟 说 ： “ 全 能 的 神 曾 在 迦 南 地 的 路 斯 向 我 显 现 ， 赐 福 与 我 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1456', '1', '48', '4', '对 我 说 ： ‘ 我 必 使 你 生 养 众 多 ， 成 为 多 民 ， 又 要 把 这 地 赐 给 你 的 后 裔 ， 永 远 为 业 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1457', '1', '48', '5', '我 未 到 埃 及 见 你 之 先 ， 你 在 埃 及 地 所 生 的 以 法 莲 和 玛 拿 西 这 两 个 儿 子 是 我 的 ， 正 如 吕 便 和 西 缅 是 我 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1458', '1', '48', '6', '你 在 他 们 以 后 所 生 的 就 是 你 的 ， 他 们 可 以 归 于 他 们 弟 兄 的 名 下 得 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1459', '1', '48', '7', '至 于 我 ， 我 从 巴 旦 来 的 时 候 ， 拉 结 死 在 我 眼 前 ， 在 迦 南 地 的 路 上 ， 离 以 法 他 还 有 一 段 路 程 ， 我 就 把 她 葬 在 以 法 他 的 路 上 〈 以 法 他 就 是 伯 利 恒 〉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1460', '1', '48', '8', '以 色 列 看 见 约 瑟 的 两 个 儿 子 ， 就 说 ： “ 这 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1461', '1', '48', '9', '约 瑟 对 他 父 亲 说 ： “ 这 是 神 在 这 里 赐 给 我 的 儿 子 。 ” 以 色 列 说 ： “ 请 你 领 他 们 到 我 跟 前 ， 我 要 给 他 们 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1462', '1', '48', '10', '以 色 列 年 纪 老 迈 ， 眼 睛 昏 花 ， 不 能 看 见 。 约 瑟 领 他 们 到 他 跟 前 ， 他 就 和 他 们 亲 嘴 ， 抱 着 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1463', '1', '48', '11', '以 色 列 对 约 瑟 说 ： “ 我 想 不 到 得 见 你 的 面 ， 不 料 ， 神 又 使 我 得 见 你 的 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1464', '1', '48', '12', '约 瑟 把 两 个 儿 子 从 以 色 列 两 膝 中 领 出 来 ， 自 己 就 脸 伏 于 地 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1465', '1', '48', '13', '随 后 ， 约 瑟 又 拉 着 他 们 两 个 ， 以 法 莲 在 他 的 右 手 里 ， 对 着 以 色 列 的 左 手 ， 玛 拿 西 在 他 的 左 手 里 ， 对 着 以 色 列 的 右 手 ， 领 他 们 到 以 色 列 的 跟 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1466', '1', '48', '14', '以 色 列 伸 出 右 手 来 ， 按 在 以 法 莲 的 头 上 〈 以 法 莲 乃 是 次 子 〉 ， 又 剪 搭 过 左 手 来 ， 按 在 玛 拿 西 的 头 上 〈 玛 拿 西 原 是 长 子 〉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1467', '1', '48', '15', '他 就 给 约 瑟 祝 福 说 ： “ 愿 我 祖 亚 伯 拉 罕 和 我 父 以 撒 所 事 奉 的 神 ， 就 是 一 生 牧 养 我 直 到 今 日 的 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1468', '1', '48', '16', '救 赎 我 脱 离 一 切 患 难 的 那 使 者 ， 赐 福 与 这 两 个 童 子 。 愿 他 们 归 在 我 的 名 下 和 我 祖 亚 伯 拉 罕 、 我 父 以 撒 的 名 下 。 又 愿 他 们 在 世 界 中 生 养 众 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1469', '1', '48', '17', '约 瑟 见 他 父 亲 把 右 手 按 在 以 法 莲 的 头 上 ， 就 不 喜 悦 ， 便 提 起 他 父 亲 的 手 ， 要 从 以 法 莲 头 上 挪 到 玛 拿 西 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1470', '1', '48', '18', '约 瑟 对 他 父 亲 说 ： “ 我 父 ， 不 是 这 样 。 这 本 是 长 子 ， 求 你 把 右 手 按 在 他 的 头 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1471', '1', '48', '19', '他 父 亲 不 从 ， 说 ： “ 我 知 道 ， 我 儿 ， 我 知 道 。 他 也 必 成 为 一 族 ， 也 必 昌 大 。 只 是 他 的 兄 弟 将 来 比 他 还 大 ； 他 兄 弟 的 后 裔 要 成 为 多 族 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1472', '1', '48', '20', '当 日 就 给 他 们 祝 福 说 ： “ 以 色 列 人 要 指 着 你 们 祝 福 说 ： ‘ 愿 神 使 你 如 以 法 莲 、 玛 拿 西 一 样 。 ’ ” 于 是 立 以 法 莲 在 玛 拿 西 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1473', '1', '48', '21', '以 色 列 又 对 约 瑟 说 ： “ 我 要 死 了 ， 但 神 必 与 你 们 同 在 ， 领 你 们 回 到 你 们 列 祖 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1474', '1', '48', '22', '并 且 我 从 前 用 弓 用 刀 从 亚 摩 利 人 手 下 夺 的 那 块 地 ， 我 都 赐 给 你 ， 使 你 比 众 弟 兄 多 得 一 分 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1475', '1', '49', '1', '＜ 雅 各 的 遗 嘱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1476', '1', '49', '2', '雅 各 的 儿 子 们 ， 你 们 要 聚 集 而 听 ， 要 听 你 们 父 亲 以 色 列 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1477', '1', '49', '3', '吕 便 哪 ， 你 是 我 的 长 子 ， 是 我 力 量 强 壮 的 时 候 生 的 ， 本 当 大 有 尊 荣 ， 权 力 超 众 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1478', '1', '49', '4', '但 你 放 纵 情 欲 ， 滚 沸 如 水 ， 必 不 得 居 首 位 ； 因 为 你 上 了 你 父 亲 的 床 ， 污 秽 了 我 的 榻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1479', '1', '49', '5', '西 缅 和 利 未 是 弟 兄 ； 他 们 的 刀 剑 是 残 忍 的 器 具 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1480', '1', '49', '6', '我 的 灵 啊 ， 不 要 与 他 们 同 谋 ； 我 的 心 哪 ， 不 要 与 他 们 联 络 ； 因 为 他 们 趁 怒 杀 害 人 命 ， 任 意 砍 断 牛 腿 大 筋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1481', '1', '49', '7', '他 们 的 怒 气 暴 烈 可 咒 ； 他 们 的 忿 恨 残 忍 可 诅 。 我 要 使 他 们 分 居 在 雅 各 家 里 ， 散 住 在 以 色 列 地 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1482', '1', '49', '8', '犹 大 啊 ， 你 弟 兄 们 必 赞 美 你 ； 你 手 必 掐 住 仇 敌 的 颈 项 ； 你 父 亲 的 儿 子 们 必 向 你 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1483', '1', '49', '9', '犹 大 是 个 小 狮 子 ； 我 儿 啊 ， 你 抓 了 食 便 上 去 。 你 屈 下 身 去 ， 卧 如 公 狮 ， 蹲 如 母 狮 ， 谁 敢 惹 你 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1484', '1', '49', '10', '圭 必 不 离 犹 大 ， 杖 必 不 离 他 两 脚 之 间 ， 直 等 细 罗 ｛ 就 是 赐 平 安 者 ｝ 来 到 ， 万 民 都 必 归 顺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1485', '1', '49', '11', '犹 大 把 小 驴 拴 在 葡 萄 树 上 ， 把 驴 驹 拴 在 美 好 的 葡 萄 树 上 。 他 在 葡 萄 酒 中 洗 了 衣 服 ， 在 葡 萄 汁 中 洗 了 袍 褂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1486', '1', '49', '12', '他 的 眼 睛 必 因 酒 红 润 ； 他 的 牙 齿 必 因 奶 白 亮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1487', '1', '49', '13', '西 布 伦 必 住 在 海 口 ， 必 成 为 停 船 的 海 口 ； 他 的 境 界 必 延 到 西 顿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1488', '1', '49', '14', '以 萨 迦 是 个 强 壮 的 驴 ， 卧 在 羊 圈 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1489', '1', '49', '15', '他 以 安 静 为 佳 ， 以 肥 地 为 美 ， 便 低 肩 背 重 ， 成 为 服 苦 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1490', '1', '49', '16', '但 必 判 断 他 的 民 ， 作 以 色 列 支 派 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1491', '1', '49', '17', '但 必 作 道 上 的 蛇 ， 路 中 的 虺 ， 咬 伤 马 蹄 ， 使 骑 马 的 坠 落 于 后 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1492', '1', '49', '18', '耶 和 华 啊 ， 我 向 来 等 候 你 的 救 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1493', '1', '49', '19', '迦 得 必 被 敌 军 追 逼 ， 他 却 要 追 逼 他 们 的 脚 跟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1494', '1', '49', '20', '亚 设 之 地 必 出 肥 美 的 粮 食 ， 且 出 君 王 的 美 味 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1495', '1', '49', '21', '拿 弗 他 利 是 被 释 放 的 母 鹿 ； 他 出 嘉 美 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1496', '1', '49', '22', '约 瑟 是 多 结 果 子 的 树 枝 ， 是 泉 旁 多 结 果 的 枝 子 ； 他 的 枝 条 探 出 墙 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1497', '1', '49', '23', '弓 箭 手 将 他 苦 害 ， 向 他 射 箭 ， 逼 迫 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1498', '1', '49', '24', '但 他 的 弓 仍 旧 坚 硬 ； 他 的 手 健 壮 敏 捷 。 这 是 因 以 色 列 的 牧 者 ， 以 色 列 的 磐 石 ─ ─ 就 是 雅 各 的 大 能 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1499', '1', '49', '25', '你 父 亲 的 神 必 帮 助 你 ； 那 全 能 者 必 将 天 上 所 有 的 福 ， 地 里 所 藏 的 福 ， 以 及 生 产 乳 养 的 福 ， 都 赐 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1500', '1', '49', '26', '你 父 亲 所 祝 的 福 胜 过 我 祖 先 所 祝 的 福 如 永 世 的 山 岭 ， 至 极 的 边 界 ； 这 些 福 必 降 在 约 瑟 的 头 上 ， 临 到 那 与 弟 兄 迥 别 之 人 的 顶 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1501', '1', '49', '27', '便 雅 悯 是 个 撕 掠 的 狼 ， 早 晨 要 吃 他 所 抓 的 ， 晚 上 要 分 他 所 夺 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1502', '1', '49', '28', '这 一 切 是 以 色 列 的 十 二 支 派 ； 这 也 是 他 们 的 父 亲 对 他 们 所 说 的 话 ， 为 他 们 所 祝 的 福 ， 都 是 按 着 各 人 的 福 分 为 他 们 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1503', '1', '49', '29', '＜ 雅 各 的 死 和 埋 葬 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1504', '1', '49', '30', '就 是 在 迦 南 地 幔 利 前 、 麦 比 拉 田 间 的 洞 ； 那 洞 和 田 是 亚 伯 拉 罕 向 赫 人 以 弗 仑 买 来 为 业 ， 作 坟 地 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1505', '1', '49', '31', '他 们 在 那 里 葬 了 亚 伯 拉 罕 和 他 妻 撒 拉 ， 又 在 那 里 葬 了 以 撒 和 他 的 妻 子 利 百 加 ； 我 也 在 那 里 葬 了 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1506', '1', '49', '32', '那 块 田 和 田 间 的 洞 原 是 向 赫 人 买 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1507', '1', '49', '33', '雅 各 嘱 咐 众 子 已 毕 ， 就 把 脚 收 在 床 上 ， 气 绝 而 死 ， 归 他 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1508', '1', '50', '1', '约 瑟 伏 在 他 父 亲 的 面 上 哀 哭 ， 与 他 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1509', '1', '50', '2', '约 瑟 吩 咐 伺 候 他 的 医 生 用 香 料 薰 他 父 亲 ， 医 生 就 用 香 料 薰 了 以 色 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1510', '1', '50', '3', '薰 尸 的 常 例 是 四 十 天 ； 那 四 十 天 满 了 ， 埃 及 人 为 他 哀 哭 了 七 十 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1511', '1', '50', '4', '为 他 哀 哭 的 日 子 过 了 ， 约 瑟 对 法 老 家 中 的 人 说 ： “ 我 若 在 你 们 眼 前 蒙 恩 ， 请 你 们 报 告 法 老 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1512', '1', '50', '5', '‘ 我 父 亲 要 死 的 时 候 叫 我 起 誓 说 ： 你 要 将 我 葬 在 迦 南 地 ， 在 我 为 自 己 所 掘 的 坟 墓 里 。 ’ 现 在 求 你 让 我 上 去 葬 我 父 亲 ， 以 后 我 必 回 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1513', '1', '50', '6', '法 老 说 ： “ 你 可 以 上 去 ， 照 着 你 父 亲 叫 你 起 的 誓 ， 将 他 葬 埋 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1514', '1', '50', '7', '于 是 约 瑟 上 去 葬 他 父 亲 。 与 他 一 同 上 去 的 ， 有 法 老 的 臣 仆 和 法 老 家 中 的 长 老 ， 并 埃 及 国 的 长 老 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1515', '1', '50', '8', '还 有 约 瑟 的 全 家 和 他 的 弟 兄 们 ， 并 他 父 亲 的 眷 属 ； 只 有 他 们 的 妇 人 孩 子 ， 和 羊 群 牛 群 ， 都 留 在 歌 珊 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1516', '1', '50', '9', '又 有 车 辆 马 兵 ， 和 他 一 同 上 去 ； 那 一 帮 人 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1517', '1', '50', '10', '他 们 到 了 约 旦 河 外 、 亚 达 的 禾 场 ， 就 在 那 里 大 大 地 号 啕 痛 哭 。 约 瑟 为 他 父 亲 哀 哭 了 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1518', '1', '50', '11', '迦 南 的 居 民 见 亚 达 禾 场 上 的 哀 哭 ， 就 说 ： “ 这 是 埃 及 人 一 场 极 大 的 哀 哭 。 ” 因 此 那 地 方 名 叫 亚 伯 ． 麦 西 ， 是 在 约 旦 河 东 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1519', '1', '50', '12', '雅 各 的 儿 子 们 就 遵 着 他 父 亲 所 吩 咐 的 办 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1520', '1', '50', '13', '把 他 搬 到 迦 南 地 ， 葬 在 幔 利 前 、 麦 比 拉 田 间 的 洞 里 ； 那 洞 和 田 是 亚 伯 拉 罕 向 赫 人 以 弗 仑 买 来 为 业 ， 作 坟 地 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1521', '1', '50', '14', '约 瑟 葬 了 他 父 亲 以 后 ， 就 和 众 弟 兄 ， 并 一 切 同 他 上 去 葬 他 父 亲 的 人 ， 都 回 埃 及 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1522', '1', '50', '15', '＜ 约 瑟 安 慰 哥 哥 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1523', '1', '50', '16', '他 们 就 打 发 人 去 见 约 瑟 ， 说 ： “ 你 父 亲 未 死 以 先 吩 咐 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1524', '1', '50', '17', '‘ 你 们 要 对 约 瑟 这 样 说 ： 从 前 你 哥 哥 们 恶 待 你 ， 求 你 饶 恕 他 们 的 过 犯 和 罪 恶 。 ’ 如 今 求 你 饶 恕 你 父 亲 神 之 仆 人 的 过 犯 。 ” 他 们 对 约 瑟 说 这 话 ， 约 瑟 就 哭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1525', '1', '50', '18', '他 的 哥 哥 们 又 来 俯 伏 在 他 面 前 ， 说 ： “ 我 们 是 你 的 仆 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1526', '1', '50', '19', '约 瑟 对 他 们 说 ： “ 不 要 害 怕 ， 我 岂 能 代 替 神 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1527', '1', '50', '20', '从 前 你 们 的 意 思 是 要 害 我 ， 但 神 的 意 思 原 是 好 的 ， 要 保 全 许 多 人 的 性 命 ， 成 就 今 日 的 光 景 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1528', '1', '50', '21', '现 在 你 们 不 要 害 怕 ， 我 必 养 活 你 们 和 你 们 的 妇 人 孩 子 。 ” 于 是 约 瑟 用 亲 爱 的 话 安 慰 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1529', '1', '50', '22', '＜ 约 瑟 的 死 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1530', '1', '50', '23', '约 瑟 得 见 以 法 莲 第 三 代 的 子 孙 。 玛 拿 西 的 孙 子 、 玛 吉 的 儿 子 也 养 在 约 瑟 的 膝 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1531', '1', '50', '24', '约 瑟 对 他 弟 兄 们 说 ： “ 我 要 死 了 ， 但 神 必 定 看 顾 你 们 ， 领 你 们 从 这 地 上 去 ， 到 他 起 誓 所 应 许 给 亚 伯 拉 罕 、 以 撒 、 雅 各 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1532', '1', '50', '25', '约 瑟 叫 以 色 列 的 子 孙 起 誓 说 ： “ 神 必 定 看 顾 你 们 ； 你 们 要 把 我 的 骸 骨 从 这 里 搬 上 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1533', '1', '50', '26', '约 瑟 死 了 ， 正 一 百 一 十 岁 。 人 用 香 料 将 他 薰 了 ， 把 他 收 殓 在 棺 材 里 ， 停 在 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1534', '2', '1', '1', '＜ 以 色 列 人 在 埃 及 受 虐 待 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1535', '2', '1', '2', '有 吕 便 、 西 缅 、 利 未 、 犹 大 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1536', '2', '1', '3', '以 萨 迦 、 西 布 伦 、 便 雅 悯 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1537', '2', '1', '4', '但 、 拿 弗 他 利 、 迦 得 、 亚 设 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1538', '2', '1', '5', '凡 从 雅 各 而 生 的 ， 共 有 七 十 人 。 约 瑟 已 经 在 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1539', '2', '1', '6', '约 瑟 和 他 的 弟 兄 ， 并 那 一 代 的 人 ， 都 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1540', '2', '1', '7', '以 色 列 人 生 养 众 多 ， 并 且 繁 茂 ， 极 其 强 盛 ， 满 了 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1541', '2', '1', '8', '有 不 认 识 约 瑟 的 新 王 起 来 ， 治 理 埃 及 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1542', '2', '1', '9', '对 他 的 百 姓 说 ： “ 看 哪 ， 这 以 色 列 民 比 我 们 还 多 ， 又 比 我 们 强 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1543', '2', '1', '10', '来 吧 ， 我 们 不 如 用 巧 计 待 他 们 ， 恐 怕 他 们 多 起 来 ， 日 后 若 遇 什 么 争 战 的 事 ， 就 连 合 我 们 的 仇 敌 攻 击 我 们 ， 离 开 这 地 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1544', '2', '1', '11', '于 是 埃 及 人 派 督 工 的 辖 制 他 们 ， 加 重 担 苦 害 他 们 。 他 们 为 法 老 建 造 两 座 积 货 城 ， 就 是 比 东 和 兰 塞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1545', '2', '1', '12', '只 是 越 发 苦 害 他 们 ， 他 们 越 发 多 起 来 ， 越 发 蔓 延 ； 埃 及 人 就 因 以 色 列 人 愁 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1546', '2', '1', '13', '埃 及 人 严 严 地 使 以 色 列 人 做 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1547', '2', '1', '14', '使 他 们 因 做 苦 工 觉 得 命 苦 ； 无 论 是 和 泥 ， 是 做 砖 ， 是 做 田 间 各 样 的 工 ， 在 一 切 的 工 上 都 严 严 地 待 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1548', '2', '1', '15', '有 希 伯 来 的 两 个 收 生 婆 ， 一 名 施 弗 拉 ， 一 名 普 阿 ； 埃 及 王 对 她 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1549', '2', '1', '16', '“ 你 们 为 希 伯 来 妇 人 收 生 ， 看 她 们 临 盆 的 时 候 ， 若 是 男 孩 ， 就 把 他 杀 了 ； 若 是 女 孩 ， 就 留 她 存 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1550', '2', '1', '17', '但 是 收 生 婆 敬 畏 神 ， 不 照 埃 及 王 的 吩 咐 行 ， 竟 存 留 男 孩 的 性 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1551', '2', '1', '18', '埃 及 王 召 了 收 生 婆 来 ， 说 ： “ 你 们 为 什 么 做 这 事 ， 存 留 男 孩 的 性 命 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1552', '2', '1', '19', '收 生 婆 对 法 老 说 ： “ 因 为 希 伯 来 妇 人 与 埃 及 妇 人 不 同 ； 希 伯 来 妇 人 本 是 健 壮 的 ｛ 原 文 是 活 泼 的 ｝ ， 收 生 婆 还 没 有 到 ， 她 们 已 经 生 产 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1553', '2', '1', '20', '神 厚 待 收 生 婆 。 以 色 列 人 多 起 来 ， 极 其 强 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1554', '2', '1', '21', '收 生 婆 因 为 敬 畏 神 ， 神 便 叫 她 们 成 立 家 室 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1555', '2', '1', '22', '法 老 吩 咐 他 的 众 民 说 ： “ 以 色 列 人 所 生 的 男 孩 ， 你 们 都 要 丢 在 河 里 ； 一 切 的 女 孩 ， 你 们 要 存 留 她 的 性 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1556', '2', '2', '1', '＜ 摩 西 的 出 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1557', '2', '2', '2', '那 女 人 怀 孕 ， 生 一 个 儿 子 ， 见 他 俊 美 ， 就 藏 了 他 三 个 月 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1558', '2', '2', '3', '后 来 不 能 再 藏 ， 就 取 了 一 个 蒲 草 箱 ， 抹 上 石 漆 和 石 油 ， 将 孩 子 放 在 里 头 ， 把 箱 子 搁 在 河 边 的 芦 荻 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1559', '2', '2', '4', '孩 子 的 姊 姊 远 远 站 着 ， 要 知 道 他 究 竟 怎 么 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1560', '2', '2', '5', '法 老 的 女 儿 来 到 河 边 洗 澡 ， 她 的 使 女 们 在 河 边 行 走 。 她 看 见 箱 子 在 芦 荻 中 ， 就 打 发 一 个 婢 女 拿 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1561', '2', '2', '6', '她 打 开 箱 子 ， 看 见 那 孩 子 。 孩 子 哭 了 ， 她 就 可 怜 他 ， 说 ： “ 这 是 希 伯 来 人 的 一 个 孩 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1562', '2', '2', '7', '孩 子 的 姊 姊 对 法 老 的 女 儿 说 ： “ 我 去 在 希 伯 来 妇 人 中 叫 一 个 奶 妈 来 ， 为 你 奶 这 孩 子 ， 可 以 不 可 以 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1563', '2', '2', '8', '法 老 的 女 儿 说 ： “ 可 以 。 ” 童 女 就 去 叫 了 孩 子 的 母 亲 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1564', '2', '2', '9', '法 老 的 女 儿 对 她 说 ： “ 你 把 这 孩 子 抱 去 ， 为 我 奶 他 ， 我 必 给 你 工 价 。 ” 妇 人 就 抱 了 孩 子 去 奶 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1565', '2', '2', '10', '孩 子 渐 长 ， 妇 人 把 他 带 到 法 老 的 女 儿 那 里 ， 就 作 了 她 的 儿 子 。 她 给 孩 子 起 名 叫 摩 西 ， 意 思 说 ： “ 因 我 把 他 从 水 里 拉 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1566', '2', '2', '11', '＜ 摩 西 逃 往 米 甸 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1567', '2', '2', '12', '他 左 右 观 看 ， 见 没 有 人 ， 就 把 埃 及 人 打 死 了 ， 藏 在 沙 土 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1568', '2', '2', '13', '第 二 天 他 出 去 ， 见 有 两 个 希 伯 来 人 争 斗 ， 就 对 那 欺 负 人 的 说 ： “ 你 为 什 么 打 你 同 族 的 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1569', '2', '2', '14', '那 人 说 ： “ 谁 立 你 作 我 们 的 首 领 和 审 判 官 呢 ？ 难 道 你 要 杀 我 ， 像 杀 那 埃 及 人 吗 ？ ” 摩 西 便 惧 怕 ， 说 ： “ 这 事 必 是 被 人 知 道 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1570', '2', '2', '15', '法 老 听 见 这 事 ， 就 想 杀 摩 西 ， 但 摩 西 躲 避 法 老 ， 逃 往 米 甸 地 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1571', '2', '2', '16', '一 日 ， 他 在 井 旁 坐 下 。 米 甸 的 祭 司 有 七 个 女 儿 ； 她 们 来 打 水 ， 打 满 了 槽 ， 要 饮 父 亲 的 群 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1572', '2', '2', '17', '有 牧 羊 的 人 来 ， 把 她 们 赶 走 了 ， 摩 西 却 起 来 帮 助 她 们 ， 又 饮 了 她 们 的 群 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1573', '2', '2', '18', '她 们 来 到 父 亲 流 珥 那 里 ； 他 说 ： “ 今 日 你 们 为 何 来 得 这 么 快 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1574', '2', '2', '19', '她 们 说 ： “ 有 一 个 埃 及 人 救 我 们 脱 离 牧 羊 人 的 手 ， 并 且 为 我 们 打 水 饮 了 群 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1575', '2', '2', '20', '他 对 女 儿 们 说 ： “ 那 个 人 在 哪 里 ？ 你 们 为 什 么 撇 下 他 呢 ？ 你 们 去 请 他 来 吃 饭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1576', '2', '2', '21', '摩 西 甘 心 和 那 人 同 住 ； 那 人 把 他 的 女 儿 西 坡 拉 给 摩 西 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1577', '2', '2', '22', '西 坡 拉 生 了 一 个 儿 子 ， 摩 西 给 他 起 名 叫 革 舜 ， 意 思 说 ： “ 因 我 在 外 邦 作 了 寄 居 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1578', '2', '2', '23', '过 了 多 年 ， 埃 及 王 死 了 。 以 色 列 人 因 做 苦 工 ， 就 叹 息 哀 求 ， 他 们 的 哀 声 达 于 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1579', '2', '2', '24', '神 听 见 他 们 的 哀 声 ， 就 记 念 他 与 亚 伯 拉 罕 、 以 撒 、 雅 各 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1580', '2', '2', '25', '神 看 顾 以 色 列 人 ， 也 知 道 他 们 的 苦 情 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1581', '2', '3', '1', '＜ 神 呼 召 摩 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1582', '2', '3', '2', '耶 和 华 的 使 者 从 荆 棘 里 火 焰 中 向 摩 西 显 现 。 摩 西 观 看 ， 不 料 ， 荆 棘 被 火 烧 着 ， 却 没 有 烧 毁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1583', '2', '3', '3', '摩 西 说 ： “ 我 要 过 去 看 这 大 异 象 ， 这 荆 棘 为 何 没 有 烧 坏 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1584', '2', '3', '4', '耶 和 华 神 见 他 过 去 要 看 ， 就 从 荆 棘 里 呼 叫 说 ： “ 摩 西 ！ 摩 西 ！ ” 他 说 ： “ 我 在 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1585', '2', '3', '5', '神 说 ： “ 不 要 近 前 来 。 当 把 你 脚 上 的 鞋 脱 下 来 ， 因 为 你 所 站 之 地 是 圣 地 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1586', '2', '3', '6', '又 说 ： “ 我 是 你 父 亲 的 神 ， 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 。 ” 摩 西 蒙 上 脸 ， 因 为 怕 看 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1587', '2', '3', '7', '耶 和 华 说 ： “ 我 的 百 姓 在 埃 及 所 受 的 困 苦 ， 我 实 在 看 见 了 ； 他 们 因 受 督 工 的 辖 制 所 发 的 哀 声 ， 我 也 听 见 了 。 我 原 知 道 他 们 的 痛 苦 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1588', '2', '3', '8', '我 下 来 是 要 救 他 们 脱 离 埃 及 人 的 手 ， 领 他 们 出 了 那 地 ， 到 美 好 、 宽 阔 、 流 奶 与 蜜 之 地 ， 就 是 到 迦 南 人 、 赫 人 、 亚 摩 利 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1589', '2', '3', '9', '现 在 以 色 列 人 的 哀 声 达 到 我 耳 中 ， 我 也 看 见 埃 及 人 怎 样 欺 压 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1590', '2', '3', '10', '故 此 ， 我 要 打 发 你 去 见 法 老 ， 使 你 可 以 将 我 的 百 姓 以 色 列 人 从 埃 及 领 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1591', '2', '3', '11', '摩 西 对 神 说 ： “ 我 是 什 么 人 ， 竟 能 去 见 法 老 ， 将 以 色 列 人 从 埃 及 领 出 来 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1592', '2', '3', '12', '神 说 ： “ 我 必 与 你 同 在 。 你 将 百 姓 从 埃 及 领 出 来 之 后 ， 你 们 必 在 这 山 上 事 奉 我 ； 这 就 是 我 打 发 你 去 的 证 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1593', '2', '3', '13', '摩 西 对 神 说 ： “ 我 到 以 色 列 人 那 里 ， 对 他 们 说 ： ‘ 你 们 祖 宗 的 神 打 发 我 到 你 们 这 里 来 。 ’ 他 们 若 问 我 说 ： ‘ 他 叫 什 么 名 字 ？ ’ 我 要 对 他 们 说 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1594', '2', '3', '14', '神 对 摩 西 说 ： “ 我 是 自 有 永 有 的 ” ； 又 说 ： “ 你 要 对 以 色 列 人 这 样 说 ： ‘ 那 自 有 的 打 发 我 到 你 们 这 里 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1595', '2', '3', '15', '神 又 对 摩 西 说 ： “ 你 要 对 以 色 列 人 这 样 说 ： ‘ 耶 和 华 ─ ─ 你 们 祖 宗 的 神 ， 就 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 ， 打 发 我 到 你 们 这 里 来 。 ’ 耶 和 华 是 我 的 名 ， 直 到 永 远 ； 这 也 是 我 的 纪 念 ， 直 到 万 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1596', '2', '3', '16', '你 去 招 聚 以 色 列 的 长 老 ， 对 他 们 说 ： ‘ 耶 和 华 ─ ─ 你 们 祖 宗 的 神 ， 就 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 ， 向 我 显 现 ， 说 ： 我 实 在 眷 顾 了 你 们 ， 我 也 看 见 埃 及 人 怎 样 待 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1597', '2', '3', '17', '我 也 说 ： 要 将 你 们 从 埃 及 的 困 苦 中 领 出 来 ， 往 迦 南 人 、 赫 人 、 亚 摩 利 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 的 地 去 ， 就 是 到 流 奶 与 蜜 之 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1598', '2', '3', '18', '他 们 必 听 你 的 话 。 你 和 以 色 列 的 长 老 要 去 见 埃 及 王 ， 对 他 说 ： ‘ 耶 和 华 ─ ─ 希 伯 来 人 的 神 遇 见 了 我 们 ， 现 在 求 你 容 我 们 往 旷 野 去 ， 走 三 天 的 路 程 ， 为 要 祭 祀 耶 和 华 ─ ─ 我 们 的 神 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1599', '2', '3', '19', '我 知 道 虽 用 大 能 的 手 ， 埃 及 王 也 不 容 你 们 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1600', '2', '3', '20', '我 必 伸 手 在 埃 及 中 间 施 行 我 一 切 的 奇 事 ， 攻 击 那 地 ， 然 后 他 才 容 你 们 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1601', '2', '3', '21', '我 必 叫 你 们 在 埃 及 人 眼 前 蒙 恩 ， 你 们 去 的 时 候 就 不 至 于 空 手 而 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1602', '2', '3', '22', '但 各 妇 女 必 向 她 的 邻 舍 ， 并 居 住 在 她 家 里 的 女 人 ， 要 金 器 银 器 和 衣 裳 ， 好 给 你 们 的 儿 女 穿 戴 。 这 样 你 们 就 把 埃 及 人 的 财 物 夺 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1603', '2', '4', '1', '＜ 神 赐 摩 西 行 神 迹 的 权 能 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1604', '2', '4', '2', '耶 和 华 对 摩 西 说 ： “ 你 手 里 是 什 么 ？ ” 他 说 ： “ 是 杖 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1605', '2', '4', '3', '耶 和 华 说 ： “ 丢 在 地 上 。 ” 他 一 丢 下 去 ， 就 变 作 蛇 ； 摩 西 便 跑 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1606', '2', '4', '4', '耶 和 华 对 摩 西 说 ： “ 伸 出 手 来 ， 拿 住 它 的 尾 巴 ， 它 必 在 你 手 中 仍 变 为 杖 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1607', '2', '4', '5', '如 此 好 叫 他 们 信 耶 和 华 ─ ─ 他 们 祖 宗 的 神 ， 就 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 ， 是 向 你 显 现 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1608', '2', '4', '6', '耶 和 华 又 对 他 说 ： “ 把 手 放 在 怀 里 。 ” 他 就 把 手 放 在 怀 里 ， 及 至 抽 出 来 ， 不 料 ， 手 长 了 大 痲 疯 ， 有 雪 那 样 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1609', '2', '4', '7', '耶 和 华 说 ： “ 再 把 手 放 在 怀 里 。 ” 他 就 再 把 手 放 在 怀 里 ， 及 至 从 怀 里 抽 出 来 ， 不 料 ， 手 已 经 复 原 ， 与 周 身 的 肉 一 样 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1610', '2', '4', '8', '又 说 ： “ 倘 或 他 们 不 听 你 的 话 ， 也 不 信 头 一 个 神 迹 ， 他 们 必 信 第 二 个 神 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1611', '2', '4', '9', '这 两 个 神 迹 若 都 不 信 ， 也 不 听 你 的 话 ， 你 就 从 河 里 取 些 水 ， 倒 在 旱 地 上 ， 你 从 河 里 取 的 水 必 在 旱 地 上 变 作 血 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1612', '2', '4', '10', '摩 西 对 耶 和 华 说 ： “ 主 啊 ， 我 素 日 不 是 能 言 的 人 ， 就 是 从 你 对 仆 人 说 话 以 后 ， 也 是 这 样 。 我 本 是 拙 口 笨 舌 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1613', '2', '4', '11', '耶 和 华 对 他 说 ： “ 谁 造 人 的 口 呢 ？ 谁 使 人 口 哑 、 耳 聋 、 目 明 、 眼 瞎 呢 ？ 岂 不 是 我 ─ ─ 耶 和 华 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1614', '2', '4', '12', '现 在 去 吧 ， 我 必 赐 你 口 才 ， 指 教 你 所 当 说 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1615', '2', '4', '13', '摩 西 说 ： “ 主 啊 ， 你 愿 意 打 发 谁 ， 就 打 发 谁 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1616', '2', '4', '14', '耶 和 华 向 摩 西 发 怒 说 ： “ 不 是 有 你 的 哥 哥 利 未 人 亚 伦 吗 ？ 我 知 道 他 是 能 言 的 ； 现 在 他 出 来 迎 接 你 ， 他 一 见 你 ， 心 里 就 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1617', '2', '4', '15', '你 要 将 当 说 的 话 传 给 他 ； 我 也 要 赐 你 和 他 口 才 ， 又 要 指 教 你 们 所 当 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1618', '2', '4', '16', '他 要 替 你 对 百 姓 说 话 ； 你 要 以 他 当 作 口 ， 他 要 以 你 当 作 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1619', '2', '4', '17', '你 手 里 要 拿 这 杖 ， 好 行 神 迹 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1620', '2', '4', '18', '＜ 摩 西 返 回 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1621', '2', '4', '19', '耶 和 华 在 米 甸 对 摩 西 说 ： “ 你 要 回 埃 及 去 ， 因 为 寻 索 你 命 的 人 都 死 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1622', '2', '4', '20', '摩 西 就 带 着 妻 子 和 两 个 儿 子 ， 叫 他 们 骑 上 驴 ， 回 埃 及 地 去 。 摩 西 手 里 拿 着 神 的 杖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1623', '2', '4', '21', '耶 和 华 对 摩 西 说 ： “ 你 回 到 埃 及 的 时 候 ， 要 留 意 将 我 指 示 你 的 一 切 奇 事 行 在 法 老 面 前 。 但 我 要 使 ｛ 或 译 ： 任 凭 ； 下 同 ｝ 他 的 心 刚 硬 ， 他 必 不 容 百 姓 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1624', '2', '4', '22', '你 要 对 法 老 说 ： ‘ 耶 和 华 这 样 说 ： 以 色 列 是 我 的 儿 子 ， 我 的 长 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1625', '2', '4', '23', '我 对 你 说 过 ： 容 我 的 儿 子 去 ， 好 事 奉 我 。 你 还 是 不 肯 容 他 去 。 看 哪 ， 我 要 杀 你 的 长 子 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1626', '2', '4', '24', '摩 西 在 路 上 住 宿 的 地 方 ， 耶 和 华 遇 见 他 ， 想 要 杀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1627', '2', '4', '25', '西 坡 拉 就 拿 一 块 火 石 ， 割 下 他 儿 子 的 阳 皮 ， 丢 在 摩 西 脚 前 ， 说 ： “ 你 真 是 我 的 血 郎 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1628', '2', '4', '26', '这 样 ， 耶 和 华 才 放 了 他 。 西 坡 拉 说 ： “ 你 因 割 礼 就 是 血 郎 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1629', '2', '4', '27', '耶 和 华 对 亚 伦 说 ： “ 你 往 旷 野 去 迎 接 摩 西 。 ” 他 就 去 ， 在 神 的 山 遇 见 摩 西 ， 和 他 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1630', '2', '4', '28', '摩 西 将 耶 和 华 打 发 他 所 说 的 言 语 和 嘱 咐 他 所 行 的 神 迹 都 告 诉 了 亚 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1631', '2', '4', '29', '摩 西 、 亚 伦 就 去 招 聚 以 色 列 的 众 长 老 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1632', '2', '4', '30', '亚 伦 将 耶 和 华 对 摩 西 所 说 的 一 切 话 述 说 了 一 遍 ， 又 在 百 姓 眼 前 行 了 那 些 神 迹 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1633', '2', '4', '31', '百 姓 就 信 了 。 以 色 列 人 听 见 耶 和 华 眷 顾 他 们 ， 鉴 察 他 们 的 困 苦 ， 就 低 头 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1634', '2', '5', '1', '＜ 摩 西 和 亚 伦 见 埃 及 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1635', '2', '5', '2', '法 老 说 ： “ 耶 和 华 是 谁 ， 使 我 听 他 的 话 ， 容 以 色 列 人 去 呢 ？ 我 不 认 识 耶 和 华 ， 也 不 容 以 色 列 人 去 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1636', '2', '5', '3', '他 们 说 ： “ 希 伯 来 人 的 神 遇 见 了 我 们 。 求 你 容 我 们 往 旷 野 去 ， 走 三 天 的 路 程 ， 祭 祀 耶 和 华 ─ ─ 我 们 的 神 ， 免 得 他 用 瘟 疫 、 刀 兵 攻 击 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1637', '2', '5', '4', '埃 及 王 对 他 们 说 ： “ 摩 西 、 亚 伦 ！ 你 们 为 什 么 叫 百 姓 旷 工 呢 ？ 你 们 去 担 你 们 的 担 子 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1638', '2', '5', '5', '又 说 ： “ 看 哪 ， 这 地 的 以 色 列 人 如 今 众 多 ， 你 们 竟 叫 他 们 歇 下 担 子 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1639', '2', '5', '6', '当 天 ， 法 老 吩 咐 督 工 的 和 官 长 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1640', '2', '5', '7', '“ 你 们 不 可 照 常 把 草 给 百 姓 做 砖 ， 叫 他 们 自 己 去 捡 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1641', '2', '5', '8', '他 们 素 常 做 砖 的 数 目 ， 你 们 仍 旧 向 他 们 要 ， 一 点 不 可 减 少 ； 因 为 他 们 是 懒 惰 的 ， 所 以 呼 求 说 ： ‘ 容 我 们 去 祭 祀 我 们 的 神 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1642', '2', '5', '9', '你 们 要 把 更 重 的 工 夫 加 在 这 些 人 身 上 ， 叫 他 们 劳 碌 ， 不 听 虚 谎 的 言 语 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1643', '2', '5', '10', '督 工 的 和 官 长 出 来 对 百 姓 说 ： “ 法 老 这 样 说 ： ‘ 我 不 给 你 们 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1644', '2', '5', '11', '你 们 自 己 在 哪 里 能 找 草 ， 就 往 那 里 去 找 吧 ！ 但 你 们 的 工 一 点 不 可 减 少 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1645', '2', '5', '12', '于 是 百 姓 散 在 埃 及 遍 地 ， 捡 碎 秸 当 作 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1646', '2', '5', '13', '督 工 的 催 着 说 ： “ 你 们 一 天 当 完 一 天 的 工 ， 与 先 前 有 草 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1647', '2', '5', '14', '法 老 督 工 的 ， 责 打 他 所 派 以 色 列 人 的 官 长 ， 说 ： “ 你 们 昨 天 今 天 为 什 么 没 有 照 向 来 的 数 目 做 砖 、 完 你 们 的 工 作 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1648', '2', '5', '15', '以 色 列 人 的 官 长 就 来 哀 求 法 老 说 ： “ 为 什 么 这 样 待 你 的 仆 人 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1649', '2', '5', '16', '督 工 的 不 把 草 给 仆 人 ， 并 且 对 我 们 说 ： ‘ 做 砖 吧 ！ ’ 看 哪 ， 你 仆 人 挨 了 打 ， 其 实 是 你 百 姓 的 错 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1650', '2', '5', '17', '但 法 老 说 ： “ 你 们 是 懒 惰 的 ！ 你 们 是 懒 惰 的 ！ 所 以 说 ： ‘ 容 我 们 去 祭 祀 耶 和 华 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1651', '2', '5', '18', '现 在 你 们 去 做 工 吧 ！ 草 是 不 给 你 们 的 ， 砖 却 要 如 数 交 纳 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1652', '2', '5', '19', '以 色 列 人 的 官 长 听 说 “ 你 们 每 天 做 砖 的 工 作 一 点 不 可 减 少 ” ， 就 知 道 是 遭 遇 祸 患 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1653', '2', '5', '20', '他 们 离 了 法 老 出 来 ， 正 遇 见 摩 西 、 亚 伦 站 在 对 面 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1654', '2', '5', '21', '就 向 他 们 说 ： “ 愿 耶 和 华 鉴 察 你 们 ， 施 行 判 断 ； 因 你 们 使 我 们 在 法 老 和 他 臣 仆 面 前 有 了 臭 名 ， 把 刀 递 在 他 们 手 中 杀 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1655', '2', '5', '22', '＜ 摩 西 向 耶 和 华 诉 苦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1656', '2', '5', '23', '自 从 我 去 见 法 老 ， 奉 你 的 名 说 话 ， 他 就 苦 待 这 百 姓 ， 你 一 点 也 没 有 拯 救 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1657', '2', '6', '1', '耶 和 华 对 摩 西 说 ： “ 现 在 你 必 看 见 我 向 法 老 所 行 的 事 ， 使 他 因 我 大 能 的 手 容 以 色 列 人 去 ， 且 把 他 们 赶 出 他 的 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1658', '2', '6', '2', '＜ 神 呼 召 摩 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1659', '2', '6', '3', '我 从 前 向 亚 伯 拉 罕 、 以 撒 、 雅 各 显 现 为 全 能 的 神 ； 至 于 我 名 耶 和 华 ， 他 们 未 曾 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1660', '2', '6', '4', '我 与 他 们 坚 定 所 立 的 约 ， 要 把 他 们 寄 居 的 迦 南 地 赐 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1661', '2', '6', '5', '我 也 听 见 以 色 列 人 被 埃 及 人 苦 待 的 哀 声 ， 我 也 记 念 我 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1662', '2', '6', '6', '所 以 你 要 对 以 色 列 人 说 ： ‘ 我 是 耶 和 华 ； 我 要 用 伸 出 来 的 膀 臂 重 重 地 刑 罚 埃 及 人 ， 救 赎 你 们 脱 离 他 们 的 重 担 ， 不 做 他 们 的 苦 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1663', '2', '6', '7', '我 要 以 你 们 为 我 的 百 姓 ， 我 也 要 作 你 们 的 神 。 你 们 要 知 道 我 是 耶 和 华 ─ ─ 你 们 的 神 ， 是 救 你 们 脱 离 埃 及 人 之 重 担 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1664', '2', '6', '8', '我 起 誓 应 许 给 亚 伯 拉 罕 、 以 撒 、 雅 各 的 那 地 ， 我 要 把 你 们 领 进 去 ， 将 那 地 赐 给 你 们 为 业 。 我 是 耶 和 华 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1665', '2', '6', '9', '摩 西 将 这 话 告 诉 以 色 列 人 ， 只 是 他 们 因 苦 工 愁 烦 ， 不 肯 听 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1666', '2', '6', '10', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1667', '2', '6', '11', '“ 你 进 去 对 埃 及 王 法 老 说 ， 要 容 以 色 列 人 出 他 的 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1668', '2', '6', '12', '摩 西 在 耶 和 华 面 前 说 ： “ 以 色 列 人 尚 且 不 听 我 的 话 ， 法 老 怎 肯 听 我 这 拙 口 笨 舌 的 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1669', '2', '6', '13', '耶 和 华 吩 咐 摩 西 、 亚 伦 往 以 色 列 人 和 埃 及 王 法 老 那 里 去 ， 把 以 色 列 人 从 埃 及 地 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1670', '2', '6', '14', '＜ 摩 西 和 亚 伦 的 族 谱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1671', '2', '6', '15', '西 缅 的 儿 子 是 耶 母 利 、 雅 悯 、 阿 辖 、 雅 斤 、 琐 辖 ， 和 迦 南 女 子 的 儿 子 扫 罗 ； 这 是 西 缅 的 各 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1672', '2', '6', '16', '利 未 众 子 的 名 字 按 着 他 们 的 后 代 记 在 下 面 ： 就 是 革 顺 、 哥 辖 、 米 拉 利 。 利 未 一 生 的 岁 数 是 一 百 三 十 七 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1673', '2', '6', '17', '革 顺 的 儿 子 按 着 家 室 是 立 尼 、 示 每 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1674', '2', '6', '18', '哥 辖 的 儿 子 是 暗 兰 、 以 斯 哈 、 希 伯 伦 、 乌 薛 。 哥 辖 一 生 的 岁 数 是 一 百 三 十 三 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1675', '2', '6', '19', '米 拉 利 的 儿 子 是 抹 利 和 母 示 ； 这 是 利 未 的 家 ， 都 按 着 他 们 的 后 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1676', '2', '6', '20', '暗 兰 娶 了 他 父 亲 的 妹 妹 约 基 别 为 妻 ， 她 给 他 生 了 亚 伦 和 摩 西 。 暗 兰 一 生 的 岁 数 是 一 百 三 十 七 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1677', '2', '6', '21', '以 斯 哈 的 儿 子 是 可 拉 、 尼 斐 、 细 基 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1678', '2', '6', '22', '乌 薛 的 儿 子 是 米 沙 利 、 以 利 撒 反 、 西 提 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1679', '2', '6', '23', '亚 伦 娶 了 亚 米 拿 达 的 女 儿 ， 拿 顺 的 妹 妹 ， 以 利 沙 巴 为 妻 ， 她 给 他 生 了 拿 答 、 亚 比 户 、 以 利 亚 撒 、 以 他 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1680', '2', '6', '24', '可 拉 的 儿 子 是 亚 惜 、 以 利 加 拿 、 亚 比 亚 撒 ； 这 是 可 拉 的 各 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1681', '2', '6', '25', '亚 伦 的 儿 子 以 利 亚 撒 娶 了 普 铁 的 一 个 女 儿 为 妻 ， 她 给 他 生 了 非 尼 哈 。 这 是 利 未 人 的 家 长 ， 都 按 着 他 们 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1682', '2', '6', '26', '耶 和 华 说 ： “ 将 以 色 列 人 按 着 他 们 的 军 队 从 埃 及 地 领 出 来 。 ” 这 是 对 那 亚 伦 、 摩 西 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1683', '2', '6', '27', '对 埃 及 王 法 老 说 要 将 以 色 列 人 从 埃 及 领 出 来 的 ， 就 是 这 摩 西 、 亚 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1684', '2', '6', '28', '＜ 耶 和 华 吩 咐 摩 西 和 亚 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1685', '2', '6', '29', '他 向 摩 西 说 ： “ 我 是 耶 和 华 ； 我 对 你 说 的 一 切 话 ， 你 都 要 告 诉 埃 及 王 法 老 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1686', '2', '6', '30', '摩 西 在 耶 和 华 面 前 说 ： “ 看 哪 ， 我 是 拙 口 笨 舌 的 人 ， 法 老 怎 肯 听 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1687', '2', '7', '1', '耶 和 华 对 摩 西 说 ： “ 我 使 你 在 法 老 面 前 代 替 神 ， 你 的 哥 哥 亚 伦 是 替 你 说 话 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1688', '2', '7', '2', '凡 我 所 吩 咐 你 的 ， 你 都 要 说 。 你 的 哥 哥 亚 伦 要 对 法 老 说 ， 容 以 色 列 人 出 他 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1689', '2', '7', '3', '我 要 使 法 老 的 心 刚 硬 ， 也 要 在 埃 及 地 多 行 神 迹 奇 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1690', '2', '7', '4', '但 法 老 必 不 听 你 们 ； 我 要 伸 手 重 重 地 刑 罚 埃 及 ， 将 我 的 军 队 以 色 列 民 从 埃 及 地 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1691', '2', '7', '5', '我 伸 手 攻 击 埃 及 ， 将 以 色 列 人 从 他 们 中 间 领 出 来 的 时 候 ， 埃 及 人 就 要 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1692', '2', '7', '6', '摩 西 、 亚 伦 这 样 行 ； 耶 和 华 怎 样 吩 咐 他 们 ， 他 们 就 照 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1693', '2', '7', '7', '摩 西 、 亚 伦 与 法 老 说 话 的 时 候 ， 摩 西 八 十 岁 ， 亚 伦 八 十 三 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1694', '2', '7', '8', '＜ 亚 伦 的 杖 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1695', '2', '7', '9', '“ 法 老 若 对 你 们 说 ： ‘ 你 们 行 件 奇 事 吧 ！ ’ 你 就 吩 咐 亚 伦 说 ： ‘ 把 杖 丢 在 法 老 面 前 ， 使 杖 变 作 蛇 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1696', '2', '7', '10', '摩 西 、 亚 伦 进 去 见 法 老 ， 就 照 耶 和 华 所 吩 咐 的 行 。 亚 伦 把 杖 丢 在 法 老 和 臣 仆 面 前 ， 杖 就 变 作 蛇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1697', '2', '7', '11', '于 是 法 老 召 了 博 士 和 术 士 来 ； 他 们 是 埃 及 行 法 术 的 ， 也 用 邪 术 照 样 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1698', '2', '7', '12', '他 们 各 人 丢 下 自 己 的 杖 ， 杖 就 变 作 蛇 ； 但 亚 伦 的 杖 吞 了 他 们 的 杖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1699', '2', '7', '13', '法 老 心 里 刚 硬 ， 不 肯 听 从 摩 西 、 亚 伦 ， 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1700', '2', '7', '14', '＜ 埃 及 遭 灾 ─ ─ 血 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1701', '2', '7', '15', '明 日 早 晨 ， 他 出 来 往 水 边 去 ， 你 要 往 河 边 迎 接 他 ， 手 里 要 拿 着 那 变 过 蛇 的 杖 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1702', '2', '7', '16', '对 他 说 ： ‘ 耶 和 华 ─ ─ 希 伯 来 人 的 神 打 发 我 来 见 你 ， 说 ： 容 我 的 百 姓 去 ， 好 在 旷 野 事 奉 我 。 到 如 今 你 还 是 不 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1703', '2', '7', '17', '耶 和 华 这 样 说 ： 我 要 用 我 手 里 的 杖 击 打 河 中 的 水 ， 水 就 变 作 血 ； 因 此 ， 你 必 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1704', '2', '7', '18', '河 里 的 鱼 必 死 ， 河 也 要 腥 臭 ， 埃 及 人 就 要 厌 恶 吃 这 河 里 的 水 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1705', '2', '7', '19', '耶 和 华 晓 谕 摩 西 说 ： “ 你 对 亚 伦 说 ： ‘ 把 你 的 杖 伸 在 埃 及 所 有 的 水 以 上 ， 就 是 在 他 们 的 江 、 河 、 池 、 塘 以 上 ， 叫 水 都 变 作 血 。 在 埃 及 遍 地 ， 无 论 在 木 器 中 ， 石 器 中 ， 都 必 有 血 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1706', '2', '7', '20', '摩 西 、 亚 伦 就 照 耶 和 华 所 吩 咐 的 行 。 亚 伦 在 法 老 和 臣 仆 眼 前 举 杖 击 打 河 里 的 水 ， 河 里 的 水 都 变 作 血 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1707', '2', '7', '21', '河 里 的 鱼 死 了 ， 河 也 腥 臭 了 ， 埃 及 人 就 不 能 吃 这 河 里 的 水 ； 埃 及 遍 地 都 有 了 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1708', '2', '7', '22', '埃 及 行 法 术 的 ， 也 用 邪 术 照 样 而 行 。 法 老 心 里 刚 硬 ， 不 肯 听 摩 西 、 亚 伦 ， 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1709', '2', '7', '23', '法 老 转 身 进 宫 ， 也 不 把 这 事 放 在 心 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1710', '2', '7', '24', '埃 及 人 都 在 河 的 两 边 挖 地 ， 要 得 水 喝 ， 因 为 他 们 不 能 喝 这 河 里 的 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1711', '2', '7', '25', '耶 和 华 击 打 河 以 后 满 了 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1712', '2', '8', '1', '＜ ─ ─ 蛙 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1713', '2', '8', '2', '你 若 不 肯 容 他 们 去 ， 我 必 使 青 蛙 糟 蹋 你 的 四 境 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1714', '2', '8', '3', '河 里 要 滋 生 青 蛙 ； 这 青 蛙 要 上 来 进 你 的 宫 殿 和 你 的 卧 房 ， 上 你 的 床 榻 ， 进 你 臣 仆 的 房 屋 ， 上 你 百 姓 的 身 上 ， 进 你 的 炉 灶 和 你 的 抟 面 盆 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1715', '2', '8', '4', '又 要 上 你 和 你 百 姓 并 你 众 臣 仆 的 身 上 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1716', '2', '8', '5', '耶 和 华 晓 谕 摩 西 说 ： “ 你 对 亚 伦 说 ： ‘ 把 你 的 杖 伸 在 江 、 河 、 池 以 上 ， 使 青 蛙 到 埃 及 地 上 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1717', '2', '8', '6', '亚 伦 便 伸 杖 在 埃 及 的 诸 水 以 上 ， 青 蛙 就 上 来 ， 遮 满 了 埃 及 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1718', '2', '8', '7', '行 法 术 的 也 用 他 们 的 邪 术 照 样 而 行 ， 叫 青 蛙 上 了 埃 及 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1719', '2', '8', '8', '法 老 召 了 摩 西 、 亚 伦 来 ， 说 ： “ 请 你 们 求 耶 和 华 使 这 青 蛙 离 开 我 和 我 的 民 ， 我 就 容 百 姓 去 祭 祀 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1720', '2', '8', '9', '摩 西 对 法 老 说 ： “ 任 凭 你 吧 ， 我 要 何 时 为 你 和 你 的 臣 仆 并 你 的 百 姓 祈 求 ， 除 灭 青 蛙 离 开 你 和 你 的 宫 殿 只 留 在 河 里 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1721', '2', '8', '10', '他 说 ： “ 明 天 。 ” 摩 西 说 ： “ 可 以 照 你 的 话 吧 ， 好 叫 你 知 道 没 有 像 耶 和 华 ─ ─ 我 们 神 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1722', '2', '8', '11', '青 蛙 要 离 开 你 和 你 的 宫 殿 ， 并 你 的 臣 仆 与 你 的 百 姓 ， 只 留 在 河 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1723', '2', '8', '12', '于 是 摩 西 、 亚 伦 离 开 法 老 出 去 。 摩 西 为 扰 害 法 老 的 青 蛙 呼 求 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1724', '2', '8', '13', '耶 和 华 就 照 摩 西 的 话 行 。 凡 在 房 里 、 院 中 、 田 间 的 青 蛙 都 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1725', '2', '8', '14', '众 人 把 青 蛙 聚 拢 成 堆 ， 遍 地 就 都 腥 臭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1726', '2', '8', '15', '但 法 老 见 灾 祸 松 缓 ， 就 硬 着 心 ， 不 肯 听 他 们 ， 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1727', '2', '8', '16', '＜ ─ ─ 虱 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1728', '2', '8', '17', '他 们 就 这 样 行 。 亚 伦 伸 杖 击 打 地 上 的 尘 土 ， 就 在 人 身 上 和 牲 畜 身 上 有 了 虱 子 ； 埃 及 遍 地 的 尘 土 都 变 成 虱 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1729', '2', '8', '18', '行 法 术 的 也 用 邪 术 要 生 出 虱 子 来 ， 却 是 不 能 。 于 是 在 人 身 上 和 牲 畜 身 上 都 有 了 虱 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1730', '2', '8', '19', '行 法 术 的 就 对 法 老 说 ： “ 这 是 神 的 手 段 。 ” 法 老 心 里 刚 硬 ， 不 肯 听 摩 西 、 亚 伦 ， 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1731', '2', '8', '20', '＜ ─ ─ 蝇 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1732', '2', '8', '21', '你 若 不 容 我 的 百 姓 去 ， 我 要 叫 成 群 的 苍 蝇 到 你 和 你 臣 仆 并 你 百 姓 的 身 上 ， 进 你 的 房 屋 ， 并 且 埃 及 人 的 房 屋 和 他 们 所 住 的 地 都 要 满 了 成 群 的 苍 蝇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1733', '2', '8', '22', '当 那 日 ， 我 必 分 别 我 百 姓 所 住 的 歌 珊 地 ， 使 那 里 没 有 成 群 的 苍 蝇 ， 好 叫 你 知 道 我 是 天 下 的 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1734', '2', '8', '23', '我 要 将 我 的 百 姓 和 你 的 百 姓 分 别 出 来 。 明 天 必 有 这 神 迹 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1735', '2', '8', '24', '耶 和 华 就 这 样 行 。 苍 蝇 成 了 大 群 ， 进 入 法 老 的 宫 殿 ， 和 他 臣 仆 的 房 屋 ； 埃 及 遍 地 就 因 这 成 群 的 苍 蝇 败 坏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1736', '2', '8', '25', '法 老 召 了 摩 西 、 亚 伦 来 ， 说 ： “ 你 们 去 ， 在 这 地 祭 祀 你 们 的 神 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1737', '2', '8', '26', '摩 西 说 ： “ 这 样 行 本 不 相 宜 ， 因 为 我 们 要 把 埃 及 人 所 厌 恶 的 祭 祀 耶 和 华 ─ ─ 我 们 的 神 ； 若 把 埃 及 人 所 厌 恶 的 在 他 们 眼 前 献 为 祭 ， 他 们 岂 不 拿 石 头 打 死 我 们 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1738', '2', '8', '27', '我 们 要 往 旷 野 去 ， 走 三 天 的 路 程 ， 照 着 耶 和 华 ─ ─ 我 们 神 所 要 吩 咐 我 们 的 祭 祀 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1739', '2', '8', '28', '法 老 说 ： “ 我 容 你 们 去 ， 在 旷 野 祭 祀 耶 和 华 ─ ─ 你 们 的 神 ； 只 是 不 要 走 得 很 远 。 求 你 们 为 我 祈 祷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1740', '2', '8', '29', '摩 西 说 ： “ 我 要 出 去 求 耶 和 华 ， 使 成 群 的 苍 蝇 明 天 离 开 法 老 和 法 老 的 臣 仆 并 法 老 的 百 姓 ； 法 老 却 不 可 再 行 诡 诈 ， 不 容 百 姓 去 祭 祀 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1741', '2', '8', '30', '于 是 摩 西 离 开 法 老 去 求 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1742', '2', '8', '31', '耶 和 华 就 照 摩 西 的 话 行 ， 叫 成 群 的 苍 蝇 离 开 法 老 和 他 的 臣 仆 并 他 的 百 姓 ， 一 个 也 没 有 留 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1743', '2', '8', '32', '这 一 次 法 老 又 硬 着 心 ， 不 容 百 姓 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1744', '2', '9', '1', '＜ ─ ─ 畜 疫 之 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1745', '2', '9', '2', '你 若 不 肯 容 他 们 去 ， 仍 旧 强 留 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1746', '2', '9', '3', '耶 和 华 的 手 加 在 你 田 间 的 牲 畜 上 ， 就 是 在 马 、 驴 、 骆 驼 、 牛 群 、 羊 群 上 ， 必 有 重 重 的 瘟 疫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1747', '2', '9', '4', '耶 和 华 要 分 别 以 色 列 的 牲 畜 和 埃 及 的 牲 畜 ， 凡 属 以 色 列 人 的 ， 一 样 都 不 死 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1748', '2', '9', '5', '耶 和 华 就 定 了 时 候 ， 说 ： “ 明 天 耶 和 华 必 在 此 地 行 这 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1749', '2', '9', '6', '第 二 天 ， 耶 和 华 就 行 这 事 。 埃 及 的 牲 畜 几 乎 都 死 了 ， 只 是 以 色 列 人 的 牲 畜 ， 一 个 都 没 有 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1750', '2', '9', '7', '法 老 打 发 人 去 看 ， 谁 知 以 色 列 人 的 牲 畜 连 一 个 都 没 有 死 。 法 老 的 心 却 是 固 执 ， 不 容 百 姓 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1751', '2', '9', '8', '＜ ─ ─ 疮 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1752', '2', '9', '9', '这 灰 要 在 埃 及 全 地 变 作 尘 土 ， 在 人 身 上 和 牲 畜 身 上 成 了 起 泡 的 疮 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1753', '2', '9', '10', '摩 西 、 亚 伦 取 了 炉 灰 ， 站 在 法 老 面 前 。 摩 西 向 天 扬 起 来 ， 就 在 人 身 上 和 牲 畜 身 上 成 了 起 泡 的 疮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1754', '2', '9', '11', '行 法 术 的 在 摩 西 面 前 站 立 不 住 ， 因 为 在 他 们 身 上 和 一 切 埃 及 人 身 上 都 有 这 疮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1755', '2', '9', '12', '耶 和 华 使 法 老 的 心 刚 硬 ， 不 听 他 们 ， 正 如 耶 和 华 对 摩 西 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1756', '2', '9', '13', '＜ ─ ─ 雹 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1757', '2', '9', '14', '因 为 这 一 次 我 要 叫 一 切 的 灾 殃 临 到 你 和 你 臣 仆 并 你 百 姓 的 身 上 ， 叫 你 知 道 在 普 天 下 没 有 像 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1758', '2', '9', '15', '我 若 伸 手 用 瘟 疫 攻 击 你 和 你 的 百 姓 ， 你 早 就 从 地 上 除 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1759', '2', '9', '16', '其 实 ， 我 叫 你 存 立 ， 是 特 要 向 你 显 我 的 大 能 ， 并 要 使 我 的 名 传 遍 天 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1760', '2', '9', '17', '你 还 向 我 的 百 姓 自 高 ， 不 容 他 们 去 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1761', '2', '9', '18', '到 明 天 约 在 这 时 候 ， 我 必 叫 重 大 的 冰 雹 降 下 ， 自 从 埃 及 开 国 以 来 ， 没 有 这 样 的 冰 雹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1762', '2', '9', '19', '现 在 你 要 打 发 人 把 你 的 牲 畜 和 你 田 间 一 切 所 有 的 催 进 来 ； 凡 在 田 间 不 收 回 家 的 ， 无 论 是 人 是 牲 畜 ， 冰 雹 必 降 在 他 们 身 上 ， 他 们 就 必 死 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1763', '2', '9', '20', '法 老 的 臣 仆 中 ， 惧 怕 耶 和 华 这 话 的 ， 便 叫 他 的 奴 仆 和 牲 畜 跑 进 家 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1764', '2', '9', '21', '但 那 不 把 耶 和 华 这 话 放 在 心 上 的 ， 就 将 他 的 奴 仆 和 牲 畜 留 在 田 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1765', '2', '9', '22', '耶 和 华 对 摩 西 说 ： “ 你 向 天 伸 杖 ， 使 埃 及 遍 地 的 人 身 上 和 牲 畜 身 上 ， 并 田 间 各 样 菜 蔬 上 ， 都 有 冰 雹 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1766', '2', '9', '23', '摩 西 向 天 伸 杖 ， 耶 和 华 就 打 雷 下 雹 ， 有 火 闪 到 地 上 ； 耶 和 华 下 雹 在 埃 及 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1767', '2', '9', '24', '那 时 ， 雹 与 火 搀 杂 ， 甚 是 厉 害 ， 自 从 埃 及 成 国 以 来 ， 遍 地 没 有 这 样 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1768', '2', '9', '25', '在 埃 及 遍 地 ， 雹 击 打 了 田 间 所 有 的 人 和 牲 畜 ， 并 一 切 的 菜 蔬 ， 又 打 坏 田 间 一 切 的 树 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1769', '2', '9', '26', '惟 独 以 色 列 人 所 住 的 歌 珊 地 没 有 冰 雹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1770', '2', '9', '27', '法 老 打 发 人 召 摩 西 、 亚 伦 来 ， 对 他 们 说 ： “ 这 一 次 我 犯 了 罪 了 。 耶 和 华 是 公 义 的 ； 我 和 我 的 百 姓 是 邪 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1771', '2', '9', '28', '这 雷 轰 和 冰 雹 已 经 够 了 。 请 你 们 求 耶 和 华 ， 我 就 容 你 们 去 ， 不 再 留 住 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1772', '2', '9', '29', '摩 西 对 他 说 ： “ 我 一 出 城 ， 就 要 向 耶 和 华 举 手 祷 告 ； 雷 必 止 住 ， 也 不 再 有 冰 雹 ， 叫 你 知 道 全 地 都 是 属 耶 和 华 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1773', '2', '9', '30', '至 于 你 和 你 的 臣 仆 ， 我 知 道 你 们 还 是 不 惧 怕 耶 和 华 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1774', '2', '9', '31', '（ 那 时 ， 麻 和 大 麦 被 雹 击 打 ； 因 为 大 麦 已 经 吐 穗 ， 麻 也 开 了 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1775', '2', '9', '32', '只 是 小 麦 和 粗 麦 没 有 被 击 打 ， 因 为 还 没 有 长 成 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1776', '2', '9', '33', '摩 西 离 了 法 老 出 城 ， 向 耶 和 华 举 手 祷 告 ； 雷 和 雹 就 止 住 ， 雨 也 不 再 浇 在 地 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1777', '2', '9', '34', '法 老 见 雨 和 雹 与 雷 止 住 ， 就 越 发 犯 罪 ； 他 和 他 的 臣 仆 都 硬 着 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1778', '2', '9', '35', '法 老 的 心 刚 硬 ， 不 容 以 色 列 人 去 ， 正 如 耶 和 华 藉 着 摩 西 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1779', '2', '10', '1', '＜ ─ ─ 蝗 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1780', '2', '10', '2', '并 要 叫 你 将 我 向 埃 及 人 所 做 的 事 ， 和 在 他 们 中 间 所 行 的 神 迹 ， 传 于 你 儿 子 和 你 孙 子 的 耳 中 ， 好 叫 你 们 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1781', '2', '10', '3', '摩 西 、 亚 伦 就 进 去 见 法 老 ， 对 他 说 ： “ 耶 和 华 ─ ─ 希 伯 来 人 的 神 这 样 说 ： ‘ 你 在 我 面 前 不 肯 自 卑 要 到 几 时 呢 ？ 容 我 的 百 姓 去 ， 好 事 奉 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1782', '2', '10', '4', '你 若 不 肯 容 我 的 百 姓 去 ， 明 天 我 要 使 蝗 虫 进 入 你 的 境 内 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1783', '2', '10', '5', '遮 满 地 面 ， 甚 至 看 不 见 地 ， 并 且 吃 那 冰 雹 所 剩 的 和 田 间 所 长 的 一 切 树 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1784', '2', '10', '6', '你 的 宫 殿 和 你 众 臣 仆 的 房 屋 ， 并 一 切 埃 及 人 的 房 屋 ， 都 要 被 蝗 虫 占 满 了 ； 自 从 你 祖 宗 和 你 祖 宗 的 祖 宗 在 世 以 来 ， 直 到 今 日 ， 没 有 见 过 这 样 的 灾 。 ’ ” 摩 西 就 转 身 离 开 法 老 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1785', '2', '10', '7', '法 老 的 臣 仆 对 法 老 说 ： “ 这 人 为 我 们 的 网 罗 要 到 几 时 呢 ？ 容 这 些 人 去 事 奉 耶 和 华 ─ ─ 他 们 的 神 吧 ！ 埃 及 已 经 败 坏 了 ， 你 还 不 知 道 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1786', '2', '10', '8', '于 是 摩 西 、 亚 伦 被 召 回 来 见 法 老 ； 法 老 对 他 们 说 ： “ 你 们 去 事 奉 耶 和 华 ─ ─ 你 们 的 神 ； 但 那 要 去 的 是 谁 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1787', '2', '10', '9', '摩 西 说 ： “ 我 们 要 和 我 们 老 的 少 的 、 儿 子 女 儿 同 去 ， 且 把 羊 群 牛 群 一 同 带 去 ， 因 为 我 们 务 要 向 耶 和 华 守 节 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1788', '2', '10', '10', '法 老 对 他 们 说 ： “ 我 容 你 们 和 你 们 妇 人 孩 子 去 的 时 候 ， 耶 和 华 与 你 们 同 在 吧 ！ 你 们 要 谨 慎 ； 因 为 有 祸 在 你 们 眼 前 ｛ 或 译 ： 你 们 存 着 恶 意 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1789', '2', '10', '11', '不 可 都 去 ！ 你 们 这 壮 年 人 去 事 奉 耶 和 华 吧 ， 因 为 这 是 你 们 所 求 的 。 ” 于 是 把 他 们 从 法 老 面 前 撵 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1790', '2', '10', '12', '耶 和 华 对 摩 西 说 ： “ 你 向 埃 及 地 伸 杖 ， 使 蝗 虫 到 埃 及 地 上 来 ， 吃 地 上 一 切 的 菜 蔬 ， 就 是 冰 雹 所 剩 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1791', '2', '10', '13', '摩 西 就 向 埃 及 地 伸 杖 ， 那 一 昼 一 夜 ， 耶 和 华 使 东 风 刮 在 埃 及 地 上 ； 到 了 早 晨 ， 东 风 把 蝗 虫 刮 了 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1792', '2', '10', '14', '蝗 虫 上 来 ， 落 在 埃 及 的 四 境 ， 甚 是 厉 害 ； 以 前 没 有 这 样 的 ， 以 后 也 必 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1793', '2', '10', '15', '因 为 这 蝗 虫 遮 满 地 面 ， 甚 至 地 都 黑 暗 了 ， 又 吃 地 上 一 切 的 菜 蔬 和 冰 雹 所 剩 树 上 的 果 子 。 埃 及 遍 地 ， 无 论 是 树 木 ， 是 田 间 的 菜 蔬 ， 连 一 点 青 的 也 没 有 留 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1794', '2', '10', '16', '于 是 法 老 急 忙 召 了 摩 西 、 亚 伦 来 ， 说 ： “ 我 得 罪 耶 和 华 ─ ─ 你 们 的 神 ， 又 得 罪 了 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1795', '2', '10', '17', '现 在 求 你 ， 只 这 一 次 ， 饶 恕 我 的 罪 ， 求 耶 和 华 ─ ─ 你 们 的 神 使 我 脱 离 这 一 次 的 死 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1796', '2', '10', '18', '摩 西 就 离 开 法 老 去 求 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1797', '2', '10', '19', '耶 和 华 转 了 极 大 的 西 风 ， 把 蝗 虫 刮 起 ， 吹 入 红 海 ； 在 埃 及 的 四 境 连 一 个 也 没 有 留 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1798', '2', '10', '20', '但 耶 和 华 使 法 老 的 心 刚 硬 ， 不 容 以 色 列 人 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1799', '2', '10', '21', '＜ ─ ─ 黑 暗 之 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1800', '2', '10', '22', '摩 西 向 天 伸 杖 ， 埃 及 遍 地 就 乌 黑 了 三 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1801', '2', '10', '23', '三 天 之 久 ， 人 不 能 相 见 ， 谁 也 不 敢 起 来 离 开 本 处 ； 惟 有 以 色 列 人 家 中 都 有 亮 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1802', '2', '10', '24', '法 老 就 召 摩 西 来 ， 说 ： “ 你 们 去 事 奉 耶 和 华 ； 只 是 你 们 的 羊 群 牛 群 要 留 下 ； 你 们 的 妇 人 孩 子 可 以 和 你 们 同 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1803', '2', '10', '25', '摩 西 说 ： “ 你 总 要 把 祭 物 和 燔 祭 牲 交 给 我 们 ， 使 我 们 可 以 祭 祀 耶 和 华 ─ ─ 我 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1804', '2', '10', '26', '我 们 的 牲 畜 也 要 带 去 ， 连 一 蹄 也 不 留 下 ； 因 为 我 们 要 从 其 中 取 出 来 ， 事 奉 耶 和 华 ─ ─ 我 们 的 神 。 我 们 未 到 那 里 ， 还 不 知 道 用 什 么 事 奉 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1805', '2', '10', '27', '但 耶 和 华 使 法 老 的 心 刚 硬 ， 不 肯 容 他 们 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1806', '2', '10', '28', '法 老 对 摩 西 说 ： “ 你 离 开 我 去 吧 ， 你 要 小 心 ， 不 要 再 见 我 的 面 ！ 因 为 你 见 我 面 的 那 日 你 就 必 死 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1807', '2', '10', '29', '摩 西 说 ： “ 你 说 得 好 ！ 我 必 不 再 见 你 的 面 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1808', '2', '11', '1', '＜ 所 有 头 胎 的 都 死 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1809', '2', '11', '2', '你 要 传 于 百 姓 的 耳 中 ， 叫 他 们 男 女 各 人 向 邻 舍 要 金 器 银 器 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1810', '2', '11', '3', '耶 和 华 叫 百 姓 在 埃 及 人 眼 前 蒙 恩 ， 并 且 摩 西 在 埃 及 地 、 法 老 臣 仆 ， 和 百 姓 的 眼 中 看 为 极 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1811', '2', '11', '4', '摩 西 说 ： “ 耶 和 华 这 样 说 ： ‘ 约 到 半 夜 ， 我 必 出 去 巡 行 埃 及 遍 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1812', '2', '11', '5', '凡 在 埃 及 地 ， 从 坐 宝 座 的 法 老 直 到 磨 子 后 的 婢 女 所 有 的 长 子 ， 以 及 一 切 头 生 的 牲 畜 ， 都 必 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1813', '2', '11', '6', '埃 及 遍 地 必 有 大 哀 号 ； 从 前 没 有 这 样 的 ， 后 来 也 必 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1814', '2', '11', '7', '至 于 以 色 列 中 ， 无 论 是 人 是 牲 畜 ， 连 狗 也 不 敢 向 他 们 摇 舌 ， 好 叫 你 们 知 道 耶 和 华 是 将 埃 及 人 和 以 色 列 人 分 别 出 来 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1815', '2', '11', '8', '你 这 一 切 臣 仆 都 要 俯 伏 来 见 我 ， 说 ： ‘ 求 你 和 跟 从 你 的 百 姓 都 出 去 ’ ， 然 后 我 要 出 去 。 ” 于 是 ， 摩 西 气 忿 忿 地 离 开 法 老 ， 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1816', '2', '11', '9', '耶 和 华 对 摩 西 说 ： “ 法 老 必 不 听 你 们 ， 使 我 的 奇 事 在 埃 及 地 多 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1817', '2', '11', '10', '摩 西 、 亚 伦 在 法 老 面 前 行 了 这 一 切 奇 事 ； 耶 和 华 使 法 老 的 心 刚 硬 ， 不 容 以 色 列 人 出 离 他 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1818', '2', '12', '1', '＜ 逾 越 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1819', '2', '12', '2', '“ 你 们 要 以 本 月 为 正 月 ， 为 一 年 之 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1820', '2', '12', '3', '你 们 吩 咐 以 色 列 全 会 众 说 ： 本 月 初 十 日 ， 各 人 要 按 着 父 家 取 羊 羔 ， 一 家 一 只 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1821', '2', '12', '4', '若 是 一 家 的 人 太 少 ， 吃 不 了 一 只 羊 羔 ， 本 人 就 要 和 他 隔 壁 的 邻 舍 共 取 一 只 。 你 们 预 备 羊 羔 ， 要 按 着 人 数 和 饭 量 计 算 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1822', '2', '12', '5', '要 无 残 疾 、 一 岁 的 公 羊 羔 ， 你 们 或 从 绵 羊 里 取 ， 或 从 山 羊 里 取 ， 都 可 以 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1823', '2', '12', '6', '要 留 到 本 月 十 四 日 ， 在 黄 昏 的 时 候 ， 以 色 列 全 会 众 把 羊 羔 宰 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1824', '2', '12', '7', '各 家 要 取 点 血 ， 涂 在 吃 羊 羔 的 房 屋 左 右 的 门 框 上 和 门 楣 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1825', '2', '12', '8', '当 夜 要 吃 羊 羔 的 肉 ； 用 火 烤 了 ， 与 无 酵 饼 和 苦 菜 同 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1826', '2', '12', '9', '不 可 吃 生 的 ， 断 不 可 吃 水 煮 的 ， 要 带 着 头 、 腿 、 五 脏 ， 用 火 烤 了 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1827', '2', '12', '10', '不 可 剩 下 一 点 留 到 早 晨 ； 若 留 到 早 晨 ， 要 用 火 烧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1828', '2', '12', '11', '你 们 吃 羊 羔 当 腰 间 束 带 ， 脚 上 穿 鞋 ， 手 中 拿 杖 ， 赶 紧 地 吃 ； 这 是 耶 和 华 的 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1829', '2', '12', '12', '因 为 那 夜 我 要 巡 行 埃 及 地 ， 把 埃 及 地 一 切 头 生 的 ， 无 论 是 人 是 牲 畜 ， 都 击 杀 了 ， 又 要 败 坏 埃 及 一 切 的 神 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1830', '2', '12', '13', '这 血 要 在 你 们 所 住 的 房 屋 上 作 记 号 ； 我 一 见 这 血 ， 就 越 过 你 们 去 。 我 击 杀 埃 及 地 头 生 的 时 候 ， 灾 殃 必 不 临 到 你 们 身 上 灭 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1831', '2', '12', '14', '＜ 除 酵 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1832', '2', '12', '15', '你 们 要 吃 无 酵 饼 七 日 。 头 一 日 要 把 酵 从 你 们 各 家 中 除 去 ； 因 为 从 头 一 日 起 ， 到 第 七 日 为 止 ， 凡 吃 有 酵 之 饼 的 ， 必 从 以 色 列 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1833', '2', '12', '16', '头 一 日 你 们 当 有 圣 会 ， 第 七 日 也 当 有 圣 会 。 这 两 日 之 内 ， 除 了 预 备 各 人 所 要 吃 的 以 外 ， 无 论 何 工 都 不 可 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1834', '2', '12', '17', '你 们 要 守 无 酵 节 ， 因 为 我 正 当 这 日 把 你 们 的 军 队 从 埃 及 地 领 出 来 。 所 以 ， 你 们 要 守 这 日 ， 作 为 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1835', '2', '12', '18', '从 正 月 十 四 日 晚 上 ， 直 到 二 十 一 日 晚 上 ， 你 们 要 吃 无 酵 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1836', '2', '12', '19', '在 你 们 各 家 中 ， 七 日 之 内 不 可 有 酵 ； 因 为 凡 吃 有 酵 之 物 的 ， 无 论 是 寄 居 的 ， 是 本 地 的 ， 必 从 以 色 列 的 会 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1837', '2', '12', '20', '有 酵 的 物 ， 你 们 都 不 可 吃 ； 在 你 们 一 切 住 处 要 吃 无 酵 饼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1838', '2', '12', '21', '＜ 第 一 个 逾 越 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1839', '2', '12', '22', '拿 一 把 牛 膝 草 ， 蘸 盆 里 的 血 ， 打 在 门 楣 上 和 左 右 的 门 框 上 。 你 们 谁 也 不 可 出 自 己 的 房 门 ， 直 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1840', '2', '12', '23', '因 为 耶 和 华 要 巡 行 击 杀 埃 及 人 ， 他 看 见 血 在 门 楣 上 和 左 右 的 门 框 上 ， 就 必 越 过 那 门 ， 不 容 灭 命 的 进 你 们 的 房 屋 ， 击 杀 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1841', '2', '12', '24', '这 例 ， 你 们 要 守 着 ， 作 为 你 们 和 你 们 子 孙 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1842', '2', '12', '25', '日 后 ， 你 们 到 了 耶 和 华 按 着 所 应 许 赐 给 你 们 的 那 地 ， 就 要 守 这 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1843', '2', '12', '26', '你 们 的 儿 女 问 你 们 说 ： ‘ 行 这 礼 是 什 么 意 思 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1844', '2', '12', '27', '你 们 就 说 ： ‘ 这 是 献 给 耶 和 华 逾 越 节 的 祭 。 当 以 色 列 人 在 埃 及 的 时 候 ， 他 击 杀 埃 及 人 ， 越 过 以 色 列 人 的 房 屋 ， 救 了 我 们 各 家 。 ’ ” 于 是 百 姓 低 头 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1845', '2', '12', '28', '耶 和 华 怎 样 吩 咐 摩 西 、 亚 伦 ， 以 色 列 人 就 怎 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1846', '2', '12', '29', '＜ 头 胎 的 被 杀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1847', '2', '12', '30', '法 老 和 一 切 臣 仆 ， 并 埃 及 众 人 ， 夜 间 都 起 来 了 。 在 埃 及 有 大 哀 号 ， 无 一 家 不 死 一 个 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1848', '2', '12', '31', '夜 间 ， 法 老 召 了 摩 西 、 亚 伦 来 ， 说 ： “ 起 来 ！ 连 你 们 带 以 色 列 人 ， 从 我 民 中 出 去 ， 依 你 们 所 说 的 ， 去 事 奉 耶 和 华 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1849', '2', '12', '32', '也 依 你 们 所 说 的 ， 连 羊 群 牛 群 带 着 走 吧 ！ 并 要 为 我 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1850', '2', '12', '33', '埃 及 人 催 促 百 姓 ， 打 发 他 们 快 快 出 离 那 地 ， 因 为 埃 及 人 说 ： “ 我 们 都 要 死 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1851', '2', '12', '34', '百 姓 就 拿 着 没 有 酵 的 生 面 ， 把 抟 面 盆 包 在 衣 服 中 ， 扛 在 肩 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1852', '2', '12', '35', '以 色 列 人 照 着 摩 西 的 话 行 ， 向 埃 及 人 要 金 器 、 银 器 ， 和 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1853', '2', '12', '36', '耶 和 华 叫 百 姓 在 埃 及 人 眼 前 蒙 恩 ， 以 致 埃 及 人 给 他 们 所 要 的 。 他 们 就 把 埃 及 人 的 财 物 夺 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1854', '2', '12', '37', '＜ 以 色 列 人 出 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1855', '2', '12', '38', '又 有 许 多 闲 杂 人 ， 并 有 羊 群 牛 群 ， 和 他 们 一 同 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1856', '2', '12', '39', '他 们 用 埃 及 带 出 来 的 生 面 烤 成 无 酵 饼 。 这 生 面 原 没 有 发 起 ； 因 为 他 们 被 催 逼 离 开 埃 及 ， 不 能 耽 延 ， 也 没 有 为 自 己 预 备 什 么 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1857', '2', '12', '40', '以 色 列 人 住 在 埃 及 共 有 四 百 三 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1858', '2', '12', '41', '正 满 了 四 百 三 十 年 的 那 一 天 ， 耶 和 华 的 军 队 都 从 埃 及 地 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1859', '2', '12', '42', '这 夜 是 耶 和 华 的 夜 ； 因 耶 和 华 领 他 们 出 了 埃 及 地 ， 所 以 当 向 耶 和 华 谨 守 ， 是 以 色 列 众 人 世 世 代 代 该 谨 守 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1860', '2', '12', '43', '＜ 逾 越 节 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1861', '2', '12', '44', '但 各 人 用 银 子 买 的 奴 仆 ， 既 受 了 割 礼 就 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1862', '2', '12', '45', '寄 居 的 和 雇 工 人 都 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1863', '2', '12', '46', '应 当 在 一 个 房 子 里 吃 ； 不 可 把 一 点 肉 从 房 子 里 带 到 外 头 去 。 羊 羔 的 骨 头 一 根 也 不 可 折 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1864', '2', '12', '47', '以 色 列 全 会 众 都 要 守 这 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1865', '2', '12', '48', '若 有 外 人 寄 居 在 你 们 中 间 ， 愿 向 耶 和 华 守 逾 越 节 ， 他 所 有 的 男 子 务 要 受 割 礼 ， 然 后 才 容 他 前 来 遵 守 ， 他 也 就 像 本 地 人 一 样 ； 但 未 受 割 礼 的 ， 都 不 可 吃 这 羊 羔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1866', '2', '12', '49', '本 地 人 和 寄 居 在 你 们 中 间 的 外 人 同 归 一 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1867', '2', '12', '50', '耶 和 华 怎 样 吩 咐 摩 西 、 亚 伦 ， 以 色 列 众 人 就 怎 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1868', '2', '12', '51', '正 当 那 日 ， 耶 和 华 将 以 色 列 人 按 着 他 们 的 军 队 ， 从 埃 及 地 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1869', '2', '13', '1', '＜ 奉 献 头 胎 的 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1870', '2', '13', '2', '“ 以 色 列 中 凡 头 生 的 ， 无 论 是 人 是 牲 畜 ， 都 是 我 的 ， 要 分 别 为 圣 归 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1871', '2', '13', '3', '＜ 除 酵 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1872', '2', '13', '4', '亚 笔 月 间 的 这 日 是 你 们 出 来 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1873', '2', '13', '5', '将 来 耶 和 华 领 你 进 迦 南 人 、 赫 人 、 亚 摩 利 人 、 希 未 人 、 耶 布 斯 人 之 地 ， 就 是 他 向 你 的 祖 宗 起 誓 应 许 给 你 那 流 奶 与 蜜 之 地 ， 那 时 你 要 在 这 月 间 守 这 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1874', '2', '13', '6', '你 要 吃 无 酵 饼 七 日 ， 到 第 七 日 要 向 耶 和 华 守 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1875', '2', '13', '7', '这 七 日 之 久 ， 要 吃 无 酵 饼 ； 在 你 四 境 之 内 不 可 见 有 酵 的 饼 ， 也 不 可 见 发 酵 的 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1876', '2', '13', '8', '当 那 日 ， 你 要 告 诉 你 的 儿 子 说 ： ‘ 这 是 因 耶 和 华 在 我 出 埃 及 的 时 候 为 我 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1877', '2', '13', '9', '这 要 在 你 手 上 作 记 号 ， 在 你 额 上 作 纪 念 ， 使 耶 和 华 的 律 法 常 在 你 口 中 ， 因 为 耶 和 华 曾 用 大 能 的 手 将 你 从 埃 及 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1878', '2', '13', '10', '所 以 你 每 年 要 按 着 日 期 守 这 例 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1879', '2', '13', '11', '＜ 长 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1880', '2', '13', '12', '那 时 你 要 将 一 切 头 生 的 ， 并 牲 畜 中 头 生 的 ， 归 给 耶 和 华 ； 公 的 都 要 属 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1881', '2', '13', '13', '凡 头 生 的 驴 ， 你 要 用 羊 羔 代 赎 ； 若 不 代 赎 ， 就 要 打 折 它 的 颈 项 。 凡 你 儿 子 中 头 生 的 都 要 赎 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1882', '2', '13', '14', '日 后 ， 你 的 儿 子 问 你 说 ： ‘ 这 是 什 么 意 思 ？ ’ 你 就 说 ： ‘ 耶 和 华 用 大 能 的 手 将 我 们 从 埃 及 为 奴 之 家 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1883', '2', '13', '15', '那 时 法 老 几 乎 不 容 我 们 去 ， 耶 和 华 就 把 埃 及 地 所 有 头 生 的 ， 无 论 是 人 是 牲 畜 ， 都 杀 了 。 因 此 ， 我 把 一 切 头 生 的 公 牲 畜 献 给 耶 和 华 为 祭 ， 但 将 头 生 的 儿 子 都 赎 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1884', '2', '13', '16', '这 要 在 你 手 上 作 记 号 ， 在 你 额 上 作 经 文 ， 因 为 耶 和 华 用 大 能 的 手 将 我 们 从 埃 及 领 出 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1885', '2', '13', '17', '＜ 云 柱 和 火 柱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1886', '2', '13', '18', '所 以 神 领 百 姓 绕 道 而 行 ， 走 红 海 旷 野 的 路 。 以 色 列 人 出 埃 及 地 ， 都 带 着 兵 器 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1887', '2', '13', '19', '摩 西 把 约 瑟 的 骸 骨 一 同 带 去 ； 因 为 约 瑟 曾 叫 以 色 列 人 严 严 地 起 誓 ， 对 他 们 说 ： “ 神 必 眷 顾 你 们 ， 你 们 要 把 我 的 骸 骨 从 这 里 一 同 带 上 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1888', '2', '13', '20', '他 们 从 疏 割 起 行 ， 在 旷 野 边 的 以 倘 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1889', '2', '13', '21', '日 间 ， 耶 和 华 在 云 柱 中 领 他 们 的 路 ； 夜 间 ， 在 火 柱 中 光 照 他 们 ， 使 他 们 日 夜 都 可 以 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1890', '2', '13', '22', '日 间 云 柱 ， 夜 间 火 柱 ， 总 不 离 开 百 姓 的 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1891', '2', '14', '1', '＜ 过 红 海 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1892', '2', '14', '2', '“ 你 吩 咐 以 色 列 人 转 回 ， 安 营 在 比 ． 哈 希 录 前 ， 密 夺 和 海 的 中 间 ， 对 着 巴 力 ． 洗 分 ， 靠 近 海 边 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1893', '2', '14', '3', '法 老 必 说 ： ‘ 以 色 列 人 在 地 中 绕 迷 了 ， 旷 野 把 他 们 困 住 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1894', '2', '14', '4', '我 要 使 法 老 的 心 刚 硬 ， 他 要 追 赶 他 们 ， 我 便 在 法 老 和 他 全 军 身 上 得 荣 耀 ； 埃 及 人 就 知 道 我 是 耶 和 华 。 ” 于 是 以 色 列 人 这 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1895', '2', '14', '5', '有 人 告 诉 埃 及 王 说 ： “ 百 姓 逃 跑 。 ” 法 老 和 他 的 臣 仆 就 向 百 姓 变 心 ， 说 ： “ 我 们 容 以 色 列 人 去 ， 不 再 服 事 我 们 ， 这 做 的 是 什 么 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1896', '2', '14', '6', '法 老 就 预 备 他 的 车 辆 ， 带 领 军 兵 同 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1897', '2', '14', '7', '并 带 着 六 百 辆 特 选 的 车 和 埃 及 所 有 的 车 ， 每 辆 都 有 车 兵 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1898', '2', '14', '8', '耶 和 华 使 埃 及 王 法 老 的 心 刚 硬 ， 他 就 追 赶 以 色 列 人 ， 因 为 以 色 列 人 是 昂 然 无 惧 地 出 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1899', '2', '14', '9', '埃 及 人 追 赶 他 们 ， 法 老 一 切 的 马 匹 、 车 辆 、 马 兵 ， 与 军 兵 就 在 海 边 上 ， 靠 近 比 ． 哈 希 录 ， 对 着 巴 力 ． 洗 分 ， 在 他 们 安 营 的 地 方 追 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1900', '2', '14', '10', '法 老 临 近 的 时 候 ， 以 色 列 人 举 目 看 见 埃 及 人 赶 来 ， 就 甚 惧 怕 ， 向 耶 和 华 哀 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1901', '2', '14', '11', '他 们 对 摩 西 说 ： “ 难 道 在 埃 及 没 有 坟 地 ， 你 把 我 们 带 来 死 在 旷 野 吗 ？ 你 为 什 么 这 样 待 我 们 ， 将 我 们 从 埃 及 领 出 来 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1902', '2', '14', '12', '我 们 在 埃 及 岂 没 有 对 你 说 过 ， 不 要 搅 扰 我 们 ， 容 我 们 服 事 埃 及 人 吗 ？ 因 为 服 事 埃 及 人 比 死 在 旷 野 还 好 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1903', '2', '14', '13', '摩 西 对 百 姓 说 ： “ 不 要 惧 怕 ， 只 管 站 住 ！ 看 耶 和 华 今 天 向 你 们 所 要 施 行 的 救 恩 。 因 为 ， 你 们 今 天 所 看 见 的 埃 及 人 必 永 远 不 再 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1904', '2', '14', '14', '耶 和 华 必 为 你 们 争 战 ； 你 们 只 管 静 默 ， 不 要 作 声 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1905', '2', '14', '15', '耶 和 华 对 摩 西 说 ： “ 你 为 什 么 向 我 哀 求 呢 ？ 你 吩 咐 以 色 列 人 往 前 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1906', '2', '14', '16', '你 举 手 向 海 伸 杖 ， 把 水 分 开 。 以 色 列 人 要 下 海 中 走 干 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1907', '2', '14', '17', '我 要 使 埃 及 人 的 心 刚 硬 ， 他 们 就 跟 着 下 去 。 我 要 在 法 老 和 他 的 全 军 、 车 辆 、 马 兵 上 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1908', '2', '14', '18', '我 在 法 老 和 他 的 车 辆 、 马 兵 上 得 荣 耀 的 时 候 ， 埃 及 人 就 知 道 我 是 耶 和 华 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1909', '2', '14', '19', '在 以 色 列 营 前 行 走 神 的 使 者 ， 转 到 他 们 后 边 去 ； 云 柱 也 从 他 们 前 边 转 到 他 们 后 边 立 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1910', '2', '14', '20', '在 埃 及 营 和 以 色 列 营 中 间 有 云 柱 ， 一 边 黑 暗 ， 一 边 发 光 ， 终 夜 两 下 不 得 相 近 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1911', '2', '14', '21', '摩 西 向 海 伸 杖 ， 耶 和 华 便 用 大 东 风 ， 使 海 水 一 夜 退 去 ， 水 便 分 开 ， 海 就 成 了 干 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1912', '2', '14', '22', '以 色 列 人 下 海 中 走 干 地 ， 水 在 他 们 的 左 右 作 了 墙 垣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1913', '2', '14', '23', '埃 及 人 追 赶 他 们 ， 法 老 一 切 的 马 匹 、 车 辆 ， 和 马 兵 都 跟 着 下 到 海 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1914', '2', '14', '24', '到 了 晨 更 的 时 候 ， 耶 和 华 从 云 火 柱 中 向 埃 及 的 军 兵 观 看 ， 使 埃 及 的 军 兵 混 乱 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1915', '2', '14', '25', '又 使 他 们 的 车 轮 脱 落 ， 难 以 行 走 ， 以 致 埃 及 人 说 ： “ 我 们 从 以 色 列 人 面 前 逃 跑 吧 ！ 因 耶 和 华 为 他 们 攻 击 我 们 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1916', '2', '14', '26', '耶 和 华 对 摩 西 说 ： “ 你 向 海 伸 杖 ， 叫 水 仍 合 在 埃 及 人 并 他 们 的 车 辆 、 马 兵 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1917', '2', '14', '27', '摩 西 就 向 海 伸 杖 ， 到 了 天 一 亮 ， 海 水 仍 旧 复 原 。 埃 及 人 避 水 逃 跑 的 时 候 ， 耶 和 华 把 他 们 推 翻 在 海 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1918', '2', '14', '28', '水 就 回 流 ， 淹 没 了 车 辆 和 马 兵 。 那 些 跟 着 以 色 列 人 下 海 法 老 的 全 军 ， 连 一 个 也 没 有 剩 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1919', '2', '14', '29', '以 色 列 人 却 在 海 中 走 干 地 ； 水 在 他 们 的 左 右 作 了 墙 垣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1920', '2', '14', '30', '当 日 ， 耶 和 华 这 样 拯 救 以 色 列 人 脱 离 埃 及 人 的 手 ， 以 色 列 人 看 见 埃 及 人 的 死 尸 都 在 海 边 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1921', '2', '14', '31', '以 色 列 人 看 见 耶 和 华 向 埃 及 人 所 行 的 大 事 ， 就 敬 畏 耶 和 华 ， 又 信 服 他 和 他 的 仆 人 摩 西 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1922', '2', '15', '1', '＜ 摩 西 的 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1923', '2', '15', '2', '耶 和 华 是 我 的 力 量 ， 我 的 诗 歌 ， 也 成 了 我 的 拯 救 。 这 是 我 的 神 ， 我 要 赞 美 他 ， 是 我 父 亲 的 神 ， 我 要 尊 崇 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1924', '2', '15', '3', '耶 和 华 是 战 士 ； 他 的 名 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1925', '2', '15', '4', '法 老 的 车 辆 、 军 兵 ， 耶 和 华 已 抛 在 海 中 ； 他 特 选 的 军 长 都 沉 于 红 海 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1926', '2', '15', '5', '深 水 淹 没 他 们 ； 他 们 如 同 石 头 坠 到 深 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1927', '2', '15', '6', '耶 和 华 啊 ， 你 的 右 手 施 展 能 力 ， 显 出 荣 耀 ； 耶 和 华 啊 ， 你 的 右 手 摔 碎 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1928', '2', '15', '7', '你 大 发 威 严 ， 推 翻 那 些 起 来 攻 击 你 的 ； 你 发 出 烈 怒 如 火 ， 烧 灭 他 们 像 烧 碎 秸 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1929', '2', '15', '8', '你 发 鼻 中 的 气 ， 水 便 聚 起 成 堆 ， 大 水 直 立 如 垒 ， 海 中 的 深 水 凝 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1930', '2', '15', '9', '仇 敌 说 ： 我 要 追 赶 ， 我 要 追 上 ； 我 要 分 掳 物 ， 我 要 在 他 们 身 上 称 我 的 心 愿 。 我 要 拔 出 刀 来 ， 亲 手 杀 灭 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1931', '2', '15', '10', '你 叫 风 一 吹 ， 海 就 把 他 们 淹 没 ； 他 们 如 铅 沉 在 大 水 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1932', '2', '15', '11', '耶 和 华 啊 ， 众 神 之 中 ， 谁 能 像 你 ？ 谁 能 像 你 ─ ─ 至 圣 至 荣 ， 可 颂 可 畏 ， 施 行 奇 事 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1933', '2', '15', '12', '你 伸 出 右 手 ， 地 便 吞 灭 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1934', '2', '15', '13', '你 凭 慈 爱 领 了 你 所 赎 的 百 姓 ； 你 凭 能 力 引 他 们 到 了 你 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1935', '2', '15', '14', '外 邦 人 听 见 就 发 颤 ； 疼 痛 抓 住 非 利 士 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1936', '2', '15', '15', '那 时 ， 以 东 的 族 长 惊 惶 ， 摩 押 的 英 雄 被 战 兢 抓 住 ， 迦 南 的 居 民 心 都 消 化 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1937', '2', '15', '16', '惊 骇 恐 惧 临 到 他 们 。 耶 和 华 啊 ， 因 你 膀 臂 的 大 能 ， 他 们 如 石 头 寂 然 不 动 ， 等 候 你 的 百 姓 过 去 ， 等 候 你 所 赎 的 百 姓 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1938', '2', '15', '17', '你 要 将 他 们 领 进 去 ， 栽 于 你 产 业 的 山 上 ─ ─ 耶 和 华 啊 ， 就 是 你 为 自 己 所 造 的 住 处 ； 主 啊 ， 就 是 你 手 所 建 立 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1939', '2', '15', '18', '耶 和 华 必 作 王 ， 直 到 永 永 远 远 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1940', '2', '15', '19', '＜ 米 利 暗 的 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1941', '2', '15', '20', '亚 伦 的 姊 姊 ， 女 先 知 米 利 暗 ， 手 里 拿 着 鼓 ； 众 妇 女 也 跟 她 出 去 拿 鼓 跳 舞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1942', '2', '15', '21', '米 利 暗 应 声 说 ： 你 们 要 歌 颂 耶 和 华 ， 因 他 大 大 战 胜 ， 将 马 和 骑 马 的 投 在 海 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1943', '2', '15', '22', '＜ 苦 水 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1944', '2', '15', '23', '到 了 玛 拉 ， 不 能 喝 那 里 的 水 ； 因 为 水 苦 ， 所 以 那 地 名 叫 玛 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1945', '2', '15', '24', '百 姓 就 向 摩 西 发 怨 言 ， 说 ： “ 我 们 喝 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1946', '2', '15', '25', '摩 西 呼 求 耶 和 华 ， 耶 和 华 指 示 他 一 棵 树 。 他 把 树 丢 在 水 里 ， 水 就 变 甜 了 。 耶 和 华 在 那 里 为 他 们 定 了 律 例 、 典 章 ， 在 那 里 试 验 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1947', '2', '15', '26', '又 说 ： “ 你 若 留 意 听 耶 和 华 ─ ─ 你 神 的 话 ， 又 行 我 眼 中 看 为 正 的 事 ， 留 心 听 我 的 诫 命 ， 守 我 一 切 的 律 例 ， 我 就 不 将 所 加 与 埃 及 人 的 疾 病 加 在 你 身 上 ， 因 为 我 ─ ─ 耶 和 华 是 医 治 你 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1948', '2', '15', '27', '他 们 到 了 以 琳 ， 在 那 里 有 十 二 股 水 泉 ， 七 十 棵 棕 树 ； 他 们 就 在 那 里 的 水 边 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1949', '2', '16', '1', '＜ 吗 哪 和 鹌 鹑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1950', '2', '16', '2', '以 色 列 全 会 众 在 旷 野 向 摩 西 、 亚 伦 发 怨 言 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1951', '2', '16', '3', '说 ： “ 巴 不 得 我 们 早 死 在 埃 及 地 、 耶 和 华 的 手 下 ； 那 时 我 们 坐 在 肉 锅 旁 边 ， 吃 得 饱 足 。 你 们 将 我 们 领 出 来 ， 到 这 旷 野 ， 是 要 叫 这 全 会 众 都 饿 死 啊 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1952', '2', '16', '4', '耶 和 华 对 摩 西 说 ： “ 我 要 将 粮 食 从 天 降 给 你 们 。 百 姓 可 以 出 去 ， 每 天 收 每 天 的 分 ， 我 好 试 验 他 们 遵 不 遵 我 的 法 度 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1953', '2', '16', '5', '到 第 六 天 ， 他 们 要 把 所 收 进 来 的 预 备 好 了 ， 比 每 天 所 收 的 多 一 倍 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1954', '2', '16', '6', '摩 西 、 亚 伦 对 以 色 列 众 人 说 ： “ 到 了 晚 上 ， 你 们 要 知 道 是 耶 和 华 将 你 们 从 埃 及 地 领 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1955', '2', '16', '7', '早 晨 ， 你 们 要 看 见 耶 和 华 的 荣 耀 ， 因 为 耶 和 华 听 见 你 们 向 他 所 发 的 怨 言 了 。 我 们 算 什 么 ， 你 们 竟 向 我 们 发 怨 言 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1956', '2', '16', '8', '摩 西 又 说 ： “ 耶 和 华 晚 上 必 给 你 们 肉 吃 ， 早 晨 必 给 你 们 食 物 得 饱 ； 因 为 你 们 向 耶 和 华 发 的 怨 言 ， 他 都 听 见 了 。 我 们 算 什 么 ， 你 们 的 怨 言 不 是 向 我 们 发 的 ， 乃 是 向 耶 和 华 发 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1957', '2', '16', '9', '摩 西 对 亚 伦 说 ： “ 你 告 诉 以 色 列 全 会 众 说 ： ‘ 你 们 就 近 耶 和 华 面 前 ， 因 为 他 已 经 听 见 你 们 的 怨 言 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1958', '2', '16', '10', '亚 伦 正 对 以 色 列 全 会 众 说 话 的 时 候 ， 他 们 向 旷 野 观 看 ， 不 料 ， 耶 和 华 的 荣 光 在 云 中 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1959', '2', '16', '11', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1960', '2', '16', '12', '“ 我 已 经 听 见 以 色 列 人 的 怨 言 。 你 告 诉 他 们 说 ： ‘ 到 黄 昏 的 时 候 ， 你 们 要 吃 肉 ， 早 晨 必 有 食 物 得 饱 ， 你 们 就 知 道 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1961', '2', '16', '13', '到 了 晚 上 ， 有 鹌 鹑 飞 来 ， 遮 满 了 营 ； 早 晨 在 营 四 围 的 地 上 有 露 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1962', '2', '16', '14', '露 水 上 升 之 后 ， 不 料 ， 野 地 面 上 有 如 白 霜 的 小 圆 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1963', '2', '16', '15', '以 色 列 人 看 见 ， 不 知 道 是 什 么 ， 就 彼 此 对 问 说 ： “ 这 是 什 么 呢 ？ ” 摩 西 对 他 们 说 ： “ 这 就 是 耶 和 华 给 你 们 吃 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1964', '2', '16', '16', '耶 和 华 所 吩 咐 的 是 这 样 ： 你 们 要 按 着 各 人 的 饭 量 ， 为 帐 棚 里 的 人 ， 按 着 人 数 收 起 来 ， 各 拿 一 俄 梅 珥 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1965', '2', '16', '17', '以 色 列 人 就 这 样 行 ； 有 多 收 的 ， 有 少 收 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1966', '2', '16', '18', '及 至 用 俄 梅 珥 量 一 量 ， 多 收 的 也 没 有 余 ， 少 收 的 也 没 有 缺 ； 各 人 按 着 自 己 的 饭 量 收 取 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1967', '2', '16', '19', '摩 西 对 他 们 说 ： “ 所 收 的 ， 不 许 什 么 人 留 到 早 晨 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1968', '2', '16', '20', '然 而 他 们 不 听 摩 西 的 话 ， 内 中 有 留 到 早 晨 的 ， 就 生 虫 变 臭 了 ； 摩 西 便 向 他 们 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1969', '2', '16', '21', '他 们 每 日 早 晨 ， 按 着 各 人 的 饭 量 收 取 ， 日 头 一 发 热 ， 就 消 化 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1970', '2', '16', '22', '到 第 六 天 ， 他 们 收 了 双 倍 的 食 物 ， 每 人 两 俄 梅 珥 。 会 众 的 官 长 来 告 诉 摩 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1971', '2', '16', '23', '摩 西 对 他 们 说 ： “ 耶 和 华 这 样 说 ： ‘ 明 天 是 圣 安 息 日 ， 是 向 耶 和 华 守 的 圣 安 息 日 。 你 们 要 烤 的 就 烤 了 ， 要 煮 的 就 煮 了 ， 所 剩 下 的 都 留 到 早 晨 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1972', '2', '16', '24', '他 们 就 照 摩 西 的 吩 咐 留 到 早 晨 ， 也 不 臭 ， 里 头 也 没 有 虫 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1973', '2', '16', '25', '摩 西 说 ： “ 你 们 今 天 吃 这 个 吧 ！ 因 为 今 天 是 向 耶 和 华 守 的 安 息 日 ； 你 们 在 田 野 必 找 不 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1974', '2', '16', '26', '六 天 可 以 收 取 ， 第 七 天 乃 是 安 息 日 ， 那 一 天 必 没 有 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1975', '2', '16', '27', '第 七 天 ， 百 姓 中 有 人 出 去 收 ， 什 么 也 找 不 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1976', '2', '16', '28', '耶 和 华 对 摩 西 说 ： “ 你 们 不 肯 守 我 的 诫 命 和 律 法 ， 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1977', '2', '16', '29', '你 们 看 ！ 耶 和 华 既 将 安 息 日 赐 给 你 们 ， 所 以 第 六 天 他 赐 给 你 们 两 天 的 食 物 ， 第 七 天 各 人 要 住 在 自 己 的 地 方 ， 不 许 什 么 人 出 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1978', '2', '16', '30', '于 是 百 姓 第 七 天 安 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1979', '2', '16', '31', '这 食 物 ， 以 色 列 家 叫 吗 哪 ； 样 子 像 芫 荽 子 ， 颜 色 是 白 的 ， 滋 味 如 同 搀 蜜 的 薄 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1980', '2', '16', '32', '摩 西 说 ： “ 耶 和 华 所 吩 咐 的 是 这 样 ： ‘ 要 将 一 满 俄 梅 珥 吗 哪 留 到 世 世 代 代 ， 使 后 人 可 以 看 见 我 当 日 将 你 们 领 出 埃 及 地 ， 在 旷 野 所 给 你 们 吃 的 食 物 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1981', '2', '16', '33', '摩 西 对 亚 伦 说 ： “ 你 拿 一 个 罐 子 ， 盛 一 满 俄 梅 珥 吗 哪 ， 存 在 耶 和 华 面 前 ， 要 留 到 世 世 代 代 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1982', '2', '16', '34', '耶 和 华 怎 么 吩 咐 摩 西 ， 亚 伦 就 怎 么 行 ， 把 吗 哪 放 在 法 柜 前 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1983', '2', '16', '35', '以 色 列 人 吃 吗 哪 共 四 十 年 ， 直 到 进 了 有 人 居 住 之 地 ， 就 是 迦 南 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1984', '2', '16', '36', '｛ 俄 梅 珥 就 是 伊 法 十 分 之 一 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1985', '2', '17', '1', '＜ 磐 石 出 水 （ 民   2 0 : 1 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1986', '2', '17', '2', '所 以 与 摩 西 争 闹 ， 说 ： “ 给 我 们 水 喝 吧 ！ ” 摩 西 对 他 们 说 ： “ 你 们 为 什 么 与 我 争 闹 ？ 为 什 么 试 探 耶 和 华 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1987', '2', '17', '3', '百 姓 在 那 里 甚 渴 ， 要 喝 水 ， 就 向 摩 西 发 怨 言 ， 说 ： “ 你 为 什 么 将 我 们 从 埃 及 领 出 来 ， 使 我 们 和 我 们 的 儿 女 并 牲 畜 都 渴 死 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1988', '2', '17', '4', '摩 西 就 呼 求 耶 和 华 说 ： “ 我 向 这 百 姓 怎 样 行 呢 ？ 他 们 几 乎 要 拿 石 头 打 死 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1989', '2', '17', '5', '耶 和 华 对 摩 西 说 ： “ 你 手 里 拿 着 你 先 前 击 打 河 水 的 杖 ， 带 领 以 色 列 的 几 个 长 老 ， 从 百 姓 面 前 走 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1990', '2', '17', '6', '我 必 在 何 烈 的 磐 石 那 里 ， 站 在 你 面 前 。 你 要 击 打 磐 石 ， 从 磐 石 里 必 有 水 流 出 来 ， 使 百 姓 可 以 喝 。 ” 摩 西 就 在 以 色 列 的 长 老 眼 前 这 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1991', '2', '17', '7', '他 给 那 地 方 起 名 叫 玛 撒 ｛ 就 是 试 探 的 意 思 ｝ ， 又 叫 米 利 巴 ｛ 就 是 争 闹 的 意 思 ｝ ； 因 以 色 列 人 争 闹 ， 又 因 他 们 试 探 耶 和 华 ， 说 ： “ 耶 和 华 是 在 我 们 中 间 不 是 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1992', '2', '17', '8', '＜ 跟 亚 玛 力 人 争 战 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1993', '2', '17', '9', '摩 西 对 约 书 亚 说 ： “ 你 为 我 们 选 出 人 来 ， 出 去 和 亚 玛 力 人 争 战 。 明 天 我 手 里 要 拿 着 神 的 杖 ， 站 在 山 顶 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1994', '2', '17', '10', '于 是 约 书 亚 照 着 摩 西 对 他 所 说 的 话 行 ， 和 亚 玛 力 人 争 战 。 摩 西 、 亚 伦 ， 与 户 珥 都 上 了 山 顶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1995', '2', '17', '11', '摩 西 何 时 举 手 ， 以 色 列 人 就 得 胜 ， 何 时 垂 手 ， 亚 玛 力 人 就 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1996', '2', '17', '12', '但 摩 西 的 手 发 沉 ， 他 们 就 搬 石 头 来 ， 放 在 他 以 下 ， 他 就 坐 在 上 面 。 亚 伦 与 户 珥 扶 着 他 的 手 ， 一 个 在 这 边 ， 一 个 在 那 边 ， 他 的 手 就 稳 住 ， 直 到 日 落 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1997', '2', '17', '13', '约 书 亚 用 刀 杀 了 亚 玛 力 王 和 他 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1998', '2', '17', '14', '耶 和 华 对 摩 西 说 ： “ 我 要 将 亚 玛 力 的 名 号 从 天 下 全 然 涂 抹 了 ； 你 要 将 这 话 写 在 书 上 作 纪 念 ， 又 念 给 约 书 亚 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('1999', '2', '17', '15', '摩 西 筑 了 一 座 坛 ， 起 名 叫 “ 耶 和 华 尼 西 ” ｛ 就 是 耶 和 华 是 我 旌 旗 的 意 思 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2000', '2', '17', '16', '又 说 ： “ 耶 和 华 已 经 起 了 誓 ， 必 世 世 代 代 和 亚 玛 力 人 争 战 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2001', '2', '18', '1', '＜ 叶 忒 罗 访 问 摩 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2002', '2', '18', '2', '便 带 着 摩 西 的 妻 子 西 坡 拉 ， 就 是 摩 西 从 前 打 发 回 去 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2003', '2', '18', '3', '又 带 着 西 坡 拉 的 两 个 儿 子 ， 一 个 名 叫 革 舜 ， 因 为 摩 西 说 ： “ 我 在 外 邦 作 了 寄 居 的 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2004', '2', '18', '4', '一 个 名 叫 以 利 以 谢 ， 因 为 他 说 ： “ 我 父 亲 的 神 帮 助 了 我 ， 救 我 脱 离 法 老 的 刀 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2005', '2', '18', '5', '摩 西 的 岳 父 叶 忒 罗 带 着 摩 西 的 妻 子 和 两 个 儿 子 来 到 神 的 山 ， 就 是 摩 西 在 旷 野 安 营 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2006', '2', '18', '6', '他 对 摩 西 说 ： “ 我 是 你 岳 父 叶 忒 罗 ， 带 着 你 的 妻 子 和 两 个 儿 子 来 到 你 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2007', '2', '18', '7', '摩 西 迎 接 他 的 岳 父 ， 向 他 下 拜 ， 与 他 亲 嘴 ， 彼 此 问 安 ， 都 进 了 帐 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2008', '2', '18', '8', '摩 西 将 耶 和 华 为 以 色 列 的 缘 故 向 法 老 和 埃 及 人 所 行 的 一 切 事 ， 以 及 路 上 所 遭 遇 的 一 切 艰 难 ， 并 耶 和 华 怎 样 搭 救 他 们 ， 都 述 说 与 他 岳 父 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2009', '2', '18', '9', '叶 忒 罗 因 耶 和 华 待 以 色 列 的 一 切 好 处 ， 就 是 拯 救 他 们 脱 离 埃 及 人 的 手 ， 便 甚 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2010', '2', '18', '10', '叶 忒 罗 说 ： “ 耶 和 华 是 应 当 称 颂 的 ； 他 救 了 你 们 脱 离 埃 及 人 和 法 老 的 手 ， 将 这 百 姓 从 埃 及 人 的 手 下 救 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2011', '2', '18', '11', '我 现 今 在 埃 及 人 向 这 百 姓 发 狂 傲 的 事 上 得 知 ， 耶 和 华 比 万 神 都 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2012', '2', '18', '12', '摩 西 的 岳 父 叶 忒 罗 把 燔 祭 和 平 安 祭 献 给 神 。 亚 伦 和 以 色 列 的 众 长 老 都 来 了 ， 与 摩 西 的 岳 父 在 神 面 前 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2013', '2', '18', '13', '＜ 选 立 百 姓 的 官 长 （ 申   1 : 9 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2014', '2', '18', '14', '摩 西 的 岳 父 看 见 他 向 百 姓 所 做 的 一 切 事 ， 就 说 ： “ 你 向 百 姓 做 的 是 什 么 事 呢 ？ 你 为 什 么 独 自 坐 着 ， 众 百 姓 从 早 到 晚 都 站 在 你 的 左 右 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2015', '2', '18', '15', '摩 西 对 岳 父 说 ： “ 这 是 因 百 姓 到 我 这 里 来 求 问 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2016', '2', '18', '16', '他 们 有 事 的 时 候 就 到 我 这 里 来 ， 我 便 在 两 造 之 间 施 行 审 判 ； 我 又 叫 他 们 知 道 神 的 律 例 和 法 度 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2017', '2', '18', '17', '摩 西 的 岳 父 说 ： “ 你 这 做 的 不 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2018', '2', '18', '18', '你 和 这 些 百 姓 必 都 疲 惫 ； 因 为 这 事 太 重 ， 你 独 自 一 人 办 理 不 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2019', '2', '18', '19', '现 在 你 要 听 我 的 话 。 我 为 你 出 个 主 意 ， 愿 神 与 你 同 在 。 你 要 替 百 姓 到 神 面 前 ， 将 案 件 奏 告 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2020', '2', '18', '20', '又 要 将 律 例 和 法 度 教 训 他 们 ， 指 示 他 们 当 行 的 道 ， 当 做 的 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2021', '2', '18', '21', '并 要 从 百 姓 中 拣 选 有 才 能 的 人 ， 就 是 敬 畏 神 、 诚 实 无 妄 、 恨 不 义 之 财 的 人 ， 派 他 们 作 千 夫 长 、 百 夫 长 、 五 十 夫 长 、 十 夫 长 ， 管 理 百 姓 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2022', '2', '18', '22', '叫 他 们 随 时 审 判 百 姓 ， 大 事 都 要 呈 到 你 这 里 ， 小 事 他 们 自 己 可 以 审 判 。 这 样 ， 你 就 轻 省 些 ， 他 们 也 可 以 同 当 此 任 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2023', '2', '18', '23', '你 若 这 样 行 ， 神 也 这 样 吩 咐 你 ， 你 就 能 受 得 住 ， 这 百 姓 也 都 平 平 安 安 归 回 他 们 的 住 处 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2024', '2', '18', '24', '于 是 ， 摩 西 听 从 他 岳 父 的 话 ， 按 着 他 所 说 的 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2025', '2', '18', '25', '摩 西 从 以 色 列 人 中 拣 选 了 有 才 能 的 人 ， 立 他 们 为 百 姓 的 首 领 ， 作 千 夫 长 、 百 夫 长 、 五 十 夫 长 、 十 夫 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2026', '2', '18', '26', '他 们 随 时 审 判 百 姓 ， 有 难 断 的 案 件 就 呈 到 摩 西 那 里 ， 但 各 样 小 事 他 们 自 己 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2027', '2', '18', '27', '此 后 ， 摩 西 让 他 的 岳 父 去 ， 他 就 往 本 地 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2028', '2', '19', '1', '＜ 以 色 列 人 在 西 奈 山 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2029', '2', '19', '2', '他 们 离 了 利 非 订 ， 来 到 西 奈 的 旷 野 ， 就 在 那 里 的 山 下 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2030', '2', '19', '3', '摩 西 到 神 那 里 ， 耶 和 华 从 山 上 呼 唤 他 说 ： “ 你 要 这 样 告 诉 雅 各 家 ， 晓 谕 以 色 列 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2031', '2', '19', '4', '‘ 我 向 埃 及 人 所 行 的 事 ， 你 们 都 看 见 了 ， 且 看 见 我 如 鹰 将 你 们 背 在 翅 膀 上 ， 带 来 归 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2032', '2', '19', '5', '如 今 你 们 若 实 在 听 从 我 的 话 ， 遵 守 我 的 约 ， 就 要 在 万 民 中 作 属 我 的 子 民 ， 因 为 全 地 都 是 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2033', '2', '19', '6', '你 们 要 归 我 作 祭 司 的 国 度 ， 为 圣 洁 的 国 民 。 ’ 这 些 话 你 要 告 诉 以 色 列 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2034', '2', '19', '7', '摩 西 去 召 了 民 间 的 长 老 来 ， 将 耶 和 华 所 吩 咐 他 的 话 都 在 他 们 面 前 陈 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2035', '2', '19', '8', '百 姓 都 同 声 回 答 说 ： “ 凡 耶 和 华 所 说 的 ， 我 们 都 要 遵 行 。 ” 摩 西 就 将 百 姓 的 话 回 覆 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2036', '2', '19', '9', '耶 和 华 对 摩 西 说 ： “ 我 要 在 密 云 中 临 到 你 那 里 ， 叫 百 姓 在 我 与 你 说 话 的 时 候 可 以 听 见 ， 也 可 以 永 远 信 你 了 。 ” 于 是 ， 摩 西 将 百 姓 的 话 奏 告 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2037', '2', '19', '10', '耶 和 华 又 对 摩 西 说 ： “ 你 往 百 姓 那 里 去 ， 叫 他 们 今 天 明 天 自 洁 ， 又 叫 他 们 洗 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2038', '2', '19', '11', '到 第 三 天 要 预 备 好 了 ， 因 为 第 三 天 耶 和 华 要 在 众 百 姓 眼 前 降 临 在 西 奈 山 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2039', '2', '19', '12', '你 要 在 山 的 四 围 给 百 姓 定 界 限 ， 说 ： ‘ 你 们 当 谨 慎 ， 不 可 上 山 去 ， 也 不 可 摸 山 的 边 界 ； 凡 摸 这 山 的 ， 必 要 治 死 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2040', '2', '19', '13', '不 可 用 手 摸 他 ， 必 用 石 头 打 死 ， 或 用 箭 射 透 ； 无 论 是 人 是 牲 畜 ， 都 不 得 活 。 到 角 声 拖 长 的 时 候 ， 他 们 才 可 到 山 根 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2041', '2', '19', '14', '摩 西 下 山 往 百 姓 那 里 去 ， 叫 他 们 自 洁 ， 他 们 就 洗 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2042', '2', '19', '15', '他 对 百 姓 说 ： “ 到 第 三 天 要 预 备 好 了 。 不 可 亲 近 女 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2043', '2', '19', '16', '到 了 第 三 天 早 晨 ， 在 山 上 有 雷 轰 、 闪 电 ， 和 密 云 ， 并 且 角 声 甚 大 ， 营 中 的 百 姓 尽 都 发 颤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2044', '2', '19', '17', '摩 西 率 领 百 姓 出 营 迎 接 神 ， 都 站 在 山 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2045', '2', '19', '18', '西 奈 全 山 冒 烟 ， 因 为 耶 和 华 在 火 中 降 于 山 上 。 山 的 烟 气 上 腾 ， 如 烧 窑 一 般 ， 遍 山 大 大 地 震 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2046', '2', '19', '19', '角 声 渐 渐 地 高 而 又 高 ， 摩 西 就 说 话 ， 神 有 声 音 答 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2047', '2', '19', '20', '耶 和 华 降 临 在 西 奈 山 顶 上 ， 耶 和 华 召 摩 西 上 山 顶 ， 摩 西 就 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2048', '2', '19', '21', '耶 和 华 对 摩 西 说 ： “ 你 下 去 嘱 咐 百 姓 ， 不 可 闯 过 来 到 我 面 前 观 看 ， 恐 怕 他 们 有 多 人 死 亡 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2049', '2', '19', '22', '又 叫 亲 近 我 的 祭 司 自 洁 ， 恐 怕 我 忽 然 出 来 击 杀 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2050', '2', '19', '23', '摩 西 对 耶 和 华 说 ： “ 百 姓 不 能 上 西 奈 山 ， 因 为 你 已 经 嘱 咐 我 们 说 ： ‘ 要 在 山 的 四 围 定 界 限 ， 叫 山 成 圣 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2051', '2', '19', '24', '耶 和 华 对 他 说 ： “ 下 去 吧 ， 你 要 和 亚 伦 一 同 上 来 ； 只 是 祭 司 和 百 姓 不 可 闯 过 来 上 到 我 面 前 ， 恐 怕 我 忽 然 出 来 击 杀 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2052', '2', '19', '25', '于 是 摩 西 下 到 百 姓 那 里 告 诉 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2053', '2', '20', '1', '＜ 十 诫 （ 申   5 : 1 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2054', '2', '20', '2', '“ 我 是 耶 和 华 ─ ─ 你 的 神 ， 曾 将 你 从 埃 及 地 为 奴 之 家 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2055', '2', '20', '3', '“ 除 了 我 以 外 ， 你 不 可 有 别 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2056', '2', '20', '4', '“ 不 可 为 自 己 雕 刻 偶 像 ， 也 不 可 做 什 么 形 像 仿 佛 上 天 、 下 地 ， 和 地 底 下 、 水 中 的 百 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2057', '2', '20', '5', '不 可 跪 拜 那 些 像 ， 也 不 可 事 奉 它 ， 因 为 我 耶 和 华 ─ ─ 你 的 神 是 忌 邪 的 神 。 恨 我 的 ， 我 必 追 讨 他 的 罪 ， 自 父 及 子 ， 直 到 三 四 代 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2058', '2', '20', '6', '爱 我 、 守 我 诫 命 的 ， 我 必 向 他 们 发 慈 爱 ， 直 到 千 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2059', '2', '20', '7', '“ 不 可 妄 称 耶 和 华 ─ ─ 你 神 的 名 ； 因 为 妄 称 耶 和 华 名 的 ， 耶 和 华 必 不 以 他 为 无 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2060', '2', '20', '8', '“ 当 记 念 安 息 日 ， 守 为 圣 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2061', '2', '20', '9', '六 日 要 劳 碌 做 你 一 切 的 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2062', '2', '20', '10', '但 第 七 日 是 向 耶 和 华 ─ ─ 你 神 当 守 的 安 息 日 。 这 一 日 你 和 你 的 儿 女 、 仆 婢 、 牲 畜 ， 并 你 城 里 寄 居 的 客 旅 ， 无 论 何 工 都 不 可 做 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2063', '2', '20', '11', '因 为 六 日 之 内 ， 耶 和 华 造 天 、 地 、 海 ， 和 其 中 的 万 物 ， 第 七 日 便 安 息 ， 所 以 耶 和 华 赐 福 与 安 息 日 ， 定 为 圣 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2064', '2', '20', '12', '“ 当 孝 敬 父 母 ， 使 你 的 日 子 在 耶 和 华 ─ ─ 你 神 所 赐 你 的 地 上 得 以 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2065', '2', '20', '13', '“ 不 可 杀 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2066', '2', '20', '14', '“ 不 可 奸 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2067', '2', '20', '15', '“ 不 可 偷 盗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2068', '2', '20', '16', '“ 不 可 作 假 见 证 陷 害 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2069', '2', '20', '17', '“ 不 可 贪 恋 人 的 房 屋 ； 也 不 可 贪 恋 人 的 妻 子 、 仆 婢 、 牛 驴 ， 并 他 一 切 所 有 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2070', '2', '20', '18', '＜ 众 民 战 惧 （ 申   5 : 2 2 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2071', '2', '20', '19', '对 摩 西 说 ： “ 求 你 和 我 们 说 话 ， 我 们 必 听 ； 不 要 神 和 我 们 说 话 ， 恐 怕 我 们 死 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2072', '2', '20', '20', '摩 西 对 百 姓 说 ： “ 不 要 惧 怕 ； 因 为 神 降 临 是 要 试 验 你 们 ， 叫 你 们 时 常 敬 畏 他 ， 不 致 犯 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2073', '2', '20', '21', '于 是 百 姓 远 远 地 站 立 ； 摩 西 就 挨 近 神 所 在 的 幽 暗 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2074', '2', '20', '22', '＜ 祭 坛 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2075', '2', '20', '23', '你 们 不 可 做 什 么 神 像 与 我 相 配 ， 不 可 为 自 己 做 金 银 的 神 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2076', '2', '20', '24', '你 要 为 我 筑 土 坛 ， 在 上 面 以 牛 羊 献 为 燔 祭 和 平 安 祭 。 凡 记 下 我 名 的 地 方 ， 我 必 到 那 里 赐 福 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2077', '2', '20', '25', '你 若 为 我 筑 一 座 石 坛 ， 不 可 用 凿 成 的 石 头 ， 因 你 在 上 头 一 动 家 具 ， 就 把 坛 污 秽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2078', '2', '20', '26', '你 上 我 的 坛 ， 不 可 用 台 阶 ， 免 得 露 出 你 的 下 体 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2079', '2', '21', '1', '＜ 对 待 奴 仆 的 条 例 （ 申   1 5 : 1 2 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2080', '2', '21', '2', '你 若 买 希 伯 来 人 作 奴 仆 ， 他 必 服 事 你 六 年 ； 第 七 年 他 可 以 自 由 ， 白 白 地 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2081', '2', '21', '3', '他 若 孤 身 来 就 可 以 孤 身 去 ； 他 若 有 妻 ， 他 的 妻 就 可 以 同 他 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2082', '2', '21', '4', '他 主 人 若 给 他 妻 子 ， 妻 子 给 他 生 了 儿 子 或 女 儿 ， 妻 子 和 儿 女 要 归 主 人 ， 他 要 独 自 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2083', '2', '21', '5', '倘 或 奴 仆 明 说 ： ‘ 我 爱 我 的 主 人 和 我 的 妻 子 儿 女 ， 不 愿 意 自 由 出 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2084', '2', '21', '6', '他 的 主 人 就 要 带 他 到 审 判 官 ｛ 或 译 ： 神 ； 下 同 ｝ 那 里 ， 又 要 带 他 到 门 前 ， 靠 近 门 框 ， 用 锥 子 穿 他 的 耳 朵 ， 他 就 永 远 服 事 主 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2085', '2', '21', '7', '“ 人 若 卖 女 儿 作 婢 女 ， 婢 女 不 可 像 男 仆 那 样 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2086', '2', '21', '8', '主 人 选 定 她 归 自 己 ， 若 不 喜 欢 她 ， 就 要 许 她 赎 身 ； 主 人 既 然 用 诡 诈 待 她 ， 就 没 有 权 柄 卖 给 外 邦 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2087', '2', '21', '9', '主 人 若 选 定 她 给 自 己 的 儿 子 ， 就 当 待 她 如 同 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2088', '2', '21', '10', '若 另 娶 一 个 ， 那 女 子 的 吃 食 、 衣 服 ， 并 好 合 的 事 ， 仍 不 可 减 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2089', '2', '21', '11', '若 不 向 她 行 这 三 样 ， 她 就 可 以 不 用 钱 赎 ， 白 白 地 出 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2090', '2', '21', '12', '＜ 惩 罚 暴 行 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2091', '2', '21', '13', '人 若 不 是 埋 伏 着 杀 人 ， 乃 是 神 交 在 他 手 中 ， 我 就 设 下 一 个 地 方 ， 他 可 以 往 那 里 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2092', '2', '21', '14', '人 若 任 意 用 诡 计 杀 了 他 的 邻 舍 ， 就 是 逃 到 我 的 坛 那 里 ， 也 当 捉 去 把 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2093', '2', '21', '15', '“ 打 父 母 的 ， 必 要 把 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2094', '2', '21', '16', '“ 拐 带 人 口 ， 或 是 把 人 卖 了 ， 或 是 留 在 他 手 下 ， 必 要 把 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2095', '2', '21', '17', '“ 咒 骂 父 母 的 ， 必 要 把 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2096', '2', '21', '18', '“ 人 若 彼 此 相 争 ， 这 个 用 石 头 或 是 拳 头 打 那 个 ， 尚 且 不 至 于 死 ， 不 过 躺 卧 在 床 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2097', '2', '21', '19', '若 再 能 起 来 扶 杖 而 出 ， 那 打 他 的 可 算 无 罪 ； 但 要 将 他 耽 误 的 工 夫 用 钱 赔 补 ， 并 要 将 他 全 然 医 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2098', '2', '21', '20', '“ 人 若 用 棍 子 打 奴 仆 或 婢 女 ， 立 时 死 在 他 的 手 下 ， 他 必 要 受 刑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2099', '2', '21', '21', '若 过 一 两 天 才 死 ， 就 可 以 不 受 刑 ， 因 为 是 用 钱 买 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2100', '2', '21', '22', '“ 人 若 彼 此 争 斗 ， 伤 害 有 孕 的 妇 人 ， 甚 至 坠 胎 ， 随 后 却 无 别 害 ， 那 伤 害 她 的 ， 总 要 按 妇 人 的 丈 夫 所 要 的 ， 照 审 判 官 所 断 的 ， 受 罚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2101', '2', '21', '23', '若 有 别 害 ， 就 要 以 命 偿 命 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2102', '2', '21', '24', '以 眼 还 眼 ， 以 牙 还 牙 ， 以 手 还 手 ， 以 脚 还 脚 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2103', '2', '21', '25', '以 烙 还 烙 ， 以 伤 还 伤 ， 以 打 还 打 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2104', '2', '21', '26', '“ 人 若 打 坏 了 他 奴 仆 或 是 婢 女 的 一 只 眼 ， 就 要 因 他 的 眼 放 他 去 得 以 自 由 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2105', '2', '21', '27', '若 打 掉 了 他 奴 仆 或 是 婢 女 的 一 个 牙 ， 就 要 因 他 的 牙 放 他 去 得 以 自 由 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2106', '2', '21', '28', '＜ 物 主 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2107', '2', '21', '29', '倘 若 那 牛 素 来 是 触 人 的 ， 有 人 报 告 了 牛 主 ， 他 竟 不 把 牛 拴 着 ， 以 致 把 男 人 或 是 女 人 触 死 ， 就 要 用 石 头 打 死 那 牛 ， 牛 主 也 必 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2108', '2', '21', '30', '若 罚 他 赎 命 的 价 银 ， 他 必 照 所 罚 的 赎 他 的 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2109', '2', '21', '31', '牛 无 论 触 了 人 的 儿 子 或 是 女 儿 ， 必 照 这 例 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2110', '2', '21', '32', '牛 若 触 了 奴 仆 或 是 婢 女 ， 必 将 银 子 三 十 舍 客 勒 给 他 们 的 主 人 ， 也 要 用 石 头 把 牛 打 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2111', '2', '21', '33', '“ 人 若 敞 着 井 口 ， 或 挖 井 不 遮 盖 ， 有 牛 或 驴 掉 在 里 头 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2112', '2', '21', '34', '井 主 要 拿 钱 赔 还 本 主 人 ， 死 牲 畜 要 归 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2113', '2', '21', '35', '“ 这 人 的 牛 若 伤 了 那 人 的 牛 ， 以 至 于 死 ， 他 们 要 卖 了 活 牛 ， 平 分 价 值 ， 也 要 平 分 死 牛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2114', '2', '21', '36', '人 若 知 道 这 牛 素 来 是 触 人 的 ， 主 人 竟 不 把 牛 拴 着 ， 他 必 要 以 牛 还 牛 ， 死 牛 要 归 自 己 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2115', '2', '22', '1', '＜ 赔 偿 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2116', '2', '22', '2', '人 若 遇 见 贼 挖 窟 窿 ， 把 贼 打 了 ， 以 至 于 死 ， 就 不 能 为 他 有 流 血 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2117', '2', '22', '3', '若 太 阳 已 经 出 来 ， 就 为 他 有 流 血 的 罪 。 贼 若 被 拿 ， 总 要 赔 还 。 若 他 一 无 所 有 ， 就 要 被 卖 ， 顶 他 所 偷 的 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2118', '2', '22', '4', '若 他 所 偷 的 ， 或 牛 ， 或 驴 ， 或 羊 ， 仍 在 他 手 下 存 活 ， 他 就 要 加 倍 赔 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2119', '2', '22', '5', '“ 人 若 在 田 间 或 在 葡 萄 园 里 放 牲 畜 ， 任 凭 牲 畜 上 别 人 的 田 里 去 吃 ， 就 必 拿 自 己 田 间 上 好 的 和 葡 萄 园 上 好 的 赔 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2120', '2', '22', '6', '“ 若 点 火 焚 烧 荆 棘 ， 以 致 将 别 人 堆 积 的 禾 捆 ， 站 着 的 禾 稼 ， 或 是 田 园 ， 都 烧 尽 了 ， 那 点 火 的 必 要 赔 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2121', '2', '22', '7', '“ 人 若 将 银 钱 或 家 具 交 付 邻 舍 看 守 ， 这 物 从 那 人 的 家 被 偷 去 ， 若 把 贼 找 到 了 ， 贼 要 加 倍 赔 还 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2122', '2', '22', '8', '若 找 不 到 贼 ， 那 家 主 必 就 近 审 判 官 ， 要 看 看 他 拿 了 原 主 的 物 件 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2123', '2', '22', '9', '“ 两 个 人 的 案 件 ， 无 论 是 为 什 么 过 犯 ， 或 是 为 牛 ， 为 驴 ， 为 羊 ， 为 衣 裳 ， 或 是 为 什 么 失 掉 之 物 ， 有 一 人 说 ： ‘ 这 是 我 的 ’ ， 两 造 就 要 将 案 件 禀 告 审 判 官 ， 审 判 官 定 谁 有 罪 ， 谁 就 要 加 倍 赔 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2124', '2', '22', '10', '“ 人 若 将 驴 ， 或 牛 ， 或 羊 ， 或 别 的 牲 畜 ， 交 付 邻 舍 看 守 ， 牲 畜 或 死 ， 或 受 伤 ， 或 被 赶 去 ， 无 人 看 见 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2125', '2', '22', '11', '那 看 守 的 人 要 凭 着 耶 和 华 起 誓 ， 手 里 未 曾 拿 邻 舍 的 物 ， 本 主 就 要 罢 休 ， 看 守 的 人 不 必 赔 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2126', '2', '22', '12', '牲 畜 若 从 看 守 的 那 里 被 偷 去 ， 他 就 要 赔 还 本 主 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2127', '2', '22', '13', '若 被 野 兽 撕 碎 ， 看 守 的 要 带 来 当 作 证 据 ， 所 撕 的 不 必 赔 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2128', '2', '22', '14', '“ 人 若 向 邻 舍 借 什 么 ， 所 借 的 或 受 伤 ， 或 死 ， 本 主 没 有 同 在 一 处 ， 借 的 人 总 要 赔 还 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2129', '2', '22', '15', '若 本 主 同 在 一 处 ， 他 就 不 必 赔 还 ； 若 是 雇 的 ， 也 不 必 赔 还 ， 本 是 为 雇 价 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2130', '2', '22', '16', '＜ 道 德 上 和 宗 教 上 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2131', '2', '22', '17', '若 女 子 的 父 亲 决 不 肯 将 女 子 给 他 ， 他 就 要 按 处 女 的 聘 礼 ， 交 出 钱 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2132', '2', '22', '18', '“ 行 邪 术 的 女 人 ， 不 可 容 她 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2133', '2', '22', '19', '“ 凡 与 兽 淫 合 的 ， 总 要 把 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2134', '2', '22', '20', '“ 祭 祀 别 神 ， 不 单 单 祭 祀 耶 和 华 的 ， 那 人 必 要 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2135', '2', '22', '21', '“ 不 可 亏 负 寄 居 的 ， 也 不 可 欺 压 他 ， 因 为 你 们 在 埃 及 地 也 作 过 寄 居 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2136', '2', '22', '22', '不 可 苦 待 寡 妇 和 孤 儿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2137', '2', '22', '23', '若 是 苦 待 他 们 一 点 ， 他 们 向 我 一 哀 求 ， 我 总 要 听 他 们 的 哀 声 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2138', '2', '22', '24', '并 要 发 烈 怒 ， 用 刀 杀 你 们 ， 使 你 们 的 妻 子 为 寡 妇 ， 儿 女 为 孤 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2139', '2', '22', '25', '“ 我 民 中 有 贫 穷 人 与 你 同 住 ， 你 若 借 钱 给 他 ， 不 可 如 放 债 的 向 他 取 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2140', '2', '22', '26', '你 即 或 拿 邻 舍 的 衣 服 作 当 头 ， 必 在 日 落 以 先 归 还 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2141', '2', '22', '27', '因 他 只 有 这 一 件 当 盖 头 ， 是 他 盖 身 的 衣 服 ， 若 是 没 有 ， 他 拿 什 么 睡 觉 呢 ？ 他 哀 求 我 ， 我 就 应 允 ， 因 为 我 是 有 恩 惠 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2142', '2', '22', '28', '“ 不 可 毁 谤 神 ； 也 不 可 毁 谤 你 百 姓 的 官 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2143', '2', '22', '29', '“ 你 要 从 你 庄 稼 中 的 谷 和 酒 醡 中 滴 出 来 的 酒 拿 来 献 上 ， 不 可 迟 延 。 “ 你 要 将 头 生 的 儿 子 归 给 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2144', '2', '22', '30', '你 牛 羊 头 生 的 ， 也 要 这 样 ； 七 天 当 跟 着 母 ， 第 八 天 要 归 给 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2145', '2', '22', '31', '“ 你 们 要 在 我 面 前 为 圣 洁 的 人 。 因 此 ， 田 间 被 野 兽 撕 裂 牲 畜 的 肉 ， 你 们 不 可 吃 ， 要 丢 给 狗 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2146', '2', '23', '1', '＜ 正 义 和 公 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2147', '2', '23', '2', '不 可 随 众 行 恶 ； 不 可 在 争 讼 的 事 上 随 众 偏 行 ， 作 见 证 屈 枉 正 直 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2148', '2', '23', '3', '也 不 可 在 争 讼 的 事 上 偏 护 穷 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2149', '2', '23', '4', '“ 若 遇 见 你 仇 敌 的 牛 或 驴 失 迷 了 路 ， 总 要 牵 回 来 交 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2150', '2', '23', '5', '若 看 见 恨 你 人 的 驴 压 卧 在 重 驮 之 下 ， 不 可 走 开 ， 务 要 和 驴 主 一 同 抬 开 重 驮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2151', '2', '23', '6', '“ 不 可 在 穷 人 争 讼 的 事 上 屈 枉 正 直 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2152', '2', '23', '7', '当 远 离 虚 假 的 事 。 不 可 杀 无 辜 和 有 义 的 人 ， 因 我 必 不 以 恶 人 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2153', '2', '23', '8', '不 可 受 贿 赂 ； 因 为 贿 赂 能 叫 明 眼 人 变 瞎 了 ， 又 能 颠 倒 义 人 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2154', '2', '23', '9', '“ 不 可 欺 压 寄 居 的 ； 因 为 你 们 在 埃 及 地 作 过 寄 居 的 ， 知 道 寄 居 的 心 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2155', '2', '23', '10', '＜ 安 息 年 和 安 息 日 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2156', '2', '23', '11', '只 是 第 七 年 要 叫 地 歇 息 ， 不 耕 不 种 ， 使 你 民 中 的 穷 人 有 吃 的 ； 他 们 所 剩 下 的 ， 野 兽 可 以 吃 。 你 的 葡 萄 园 和 橄 榄 园 也 要 照 样 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2157', '2', '23', '12', '“ 六 日 你 要 做 工 ， 第 七 日 要 安 息 ， 使 牛 、 驴 可 以 歇 息 ， 并 使 你 婢 女 的 儿 子 和 寄 居 的 都 可 以 舒 畅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2158', '2', '23', '13', '“ 凡 我 对 你 们 说 的 话 ， 你 们 要 谨 守 。 别 神 的 名 ， 你 不 可 提 ， 也 不 可 从 你 口 中 传 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2159', '2', '23', '14', '＜ 三 大 节 期 （ 出   3 4 : 1 8 - 2 6 ； 申   1 6 : 1 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2160', '2', '23', '15', '你 要 守 除 酵 节 ， 照 我 所 吩 咐 你 的 ， 在 亚 笔 月 内 所 定 的 日 期 ， 吃 无 酵 饼 七 天 。 谁 也 不 可 空 手 朝 见 我 ， 因 为 你 是 这 月 出 了 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2161', '2', '23', '16', '又 要 守 收 割 节 ， 所 收 的 是 你 田 间 所 种 、 劳 碌 得 来 初 熟 之 物 。 并 在 年 底 收 藏 ， 要 守 收 藏 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2162', '2', '23', '17', '一 切 的 男 丁 要 一 年 三 次 朝 见 主 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2163', '2', '23', '18', '“ 不 可 将 我 祭 牲 的 血 和 有 酵 的 饼 一 同 献 上 ； 也 不 可 将 我 节 上 祭 牲 的 脂 油 留 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2164', '2', '23', '19', '“ 地 里 首 先 初 熟 之 物 要 送 到 耶 和 华 ─ ─ 你 神 的 殿 。 “ 不 可 用 山 羊 羔 母 的 奶 煮 山 羊 羔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2165', '2', '23', '20', '＜ 应 许 和 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2166', '2', '23', '21', '他 是 奉 我 名 来 的 ； 你 们 要 在 他 面 前 谨 慎 ， 听 从 他 的 话 ， 不 可 惹 ｛ 或 译 ： 违 背 ｝ 他 ， 因 为 他 必 不 赦 免 你 们 的 过 犯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2167', '2', '23', '22', '“ 你 若 实 在 听 从 他 的 话 ， 照 着 我 一 切 所 说 的 去 行 ， 我 就 向 你 的 仇 敌 作 仇 敌 ， 向 你 的 敌 人 作 敌 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2168', '2', '23', '23', '“ 我 的 使 者 要 在 你 前 面 行 ， 领 你 到 亚 摩 利 人 、 赫 人 、 比 利 洗 人 、 迦 南 人 、 希 未 人 、 耶 布 斯 人 那 里 去 ， 我 必 将 他 们 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2169', '2', '23', '24', '你 不 可 跪 拜 他 们 的 神 ， 不 可 事 奉 他 ， 也 不 可 效 法 他 们 的 行 为 ， 却 要 把 神 像 尽 行 拆 毁 ， 打 碎 他 们 的 柱 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2170', '2', '23', '25', '你 们 要 事 奉 耶 和 华 ─ ─ 你 们 的 神 ， 他 必 赐 福 与 你 的 粮 与 你 的 水 ， 也 必 从 你 们 中 间 除 去 疾 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2171', '2', '23', '26', '你 境 内 必 没 有 坠 胎 的 ， 不 生 产 的 。 我 要 使 你 满 了 你 年 日 的 数 目 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2172', '2', '23', '27', '凡 你 所 到 的 地 方 ， 我 要 使 那 里 的 众 民 在 你 面 前 惊 骇 ， 扰 乱 ， 又 要 使 你 一 切 仇 敌 转 背 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2173', '2', '23', '28', '我 要 打 发 黄 蜂 飞 在 你 前 面 ， 把 希 未 人 、 迦 南 人 、 赫 人 撵 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2174', '2', '23', '29', '我 不 在 一 年 之 内 将 他 们 从 你 面 前 撵 出 去 ， 恐 怕 地 成 为 荒 凉 ， 野 地 的 兽 多 起 来 害 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2175', '2', '23', '30', '我 要 渐 渐 地 将 他 们 从 你 面 前 撵 出 去 ， 等 到 你 的 人 数 加 多 ， 承 受 那 地 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2176', '2', '23', '31', '我 要 定 你 的 境 界 ， 从 红 海 直 到 非 利 士 海 ， 又 从 旷 野 直 到 大 河 。 我 要 将 那 地 的 居 民 交 在 你 手 中 ， 你 要 将 他 们 从 你 面 前 撵 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2177', '2', '23', '32', '不 可 和 他 们 并 他 们 的 神 立 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2178', '2', '23', '33', '他 们 不 可 住 在 你 的 地 上 ， 恐 怕 他 们 使 你 得 罪 我 。 你 若 事 奉 他 们 的 神 ， 这 必 成 为 你 的 网 罗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2179', '2', '24', '1', '＜ 立 约 的 凭 据 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2180', '2', '24', '2', '惟 独 你 可 以 亲 近 耶 和 华 ； 他 们 却 不 可 亲 近 ； 百 姓 也 不 可 和 你 一 同 上 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2181', '2', '24', '3', '摩 西 下 山 ， 将 耶 和 华 的 命 令 典 章 都 述 说 与 百 姓 听 。 众 百 姓 齐 声 说 ： “ 耶 和 华 所 吩 咐 的 ， 我 们 都 必 遵 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2182', '2', '24', '4', '摩 西 将 耶 和 华 的 命 令 都 写 上 。 清 早 起 来 ， 在 山 下 筑 一 座 坛 ， 按 以 色 列 十 二 支 派 立 十 二 根 柱 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2183', '2', '24', '5', '又 打 发 以 色 列 人 中 的 少 年 人 去 献 燔 祭 ， 又 向 耶 和 华 献 牛 为 平 安 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2184', '2', '24', '6', '摩 西 将 血 一 半 盛 在 盆 中 ， 一 半 洒 在 坛 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2185', '2', '24', '7', '又 将 约 书 念 给 百 姓 听 。 他 们 说 ： “ 耶 和 华 所 吩 咐 的 ， 我 们 都 必 遵 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2186', '2', '24', '8', '摩 西 将 血 洒 在 百 姓 身 上 ， 说 ： “ 你 看 ！ 这 是 立 约 的 血 ， 是 耶 和 华 按 这 一 切 话 与 你 们 立 约 的 凭 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2187', '2', '24', '9', '摩 西 、 亚 伦 、 拿 答 、 亚 比 户 ， 并 以 色 列 长 老 中 的 七 十 人 ， 都 上 了 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2188', '2', '24', '10', '他 们 看 见 以 色 列 的 神 ， 他 脚 下 仿 佛 有 平 铺 的 蓝 宝 石 ， 如 同 天 色 明 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2189', '2', '24', '11', '他 的 手 不 加 害 在 以 色 列 的 尊 者 身 上 。 他 们 观 看 神 ； 他 们 又 吃 又 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2190', '2', '24', '12', '＜ 摩 西 在 西 奈 山 上 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2191', '2', '24', '13', '摩 西 和 他 的 帮 手 约 书 亚 起 来 ， 上 了 神 的 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2192', '2', '24', '14', '摩 西 对 长 老 说 ： “ 你 们 在 这 里 等 着 ， 等 到 我 们 再 回 来 ， 有 亚 伦 、 户 珥 与 你 们 同 在 。 凡 有 争 讼 的 ， 都 可 以 就 近 他 们 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2193', '2', '24', '15', '摩 西 上 山 ， 有 云 彩 把 山 遮 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2194', '2', '24', '16', '耶 和 华 的 荣 耀 停 于 西 奈 山 ； 云 彩 遮 盖 山 六 天 ， 第 七 天 他 从 云 中 召 摩 西 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2195', '2', '24', '17', '耶 和 华 的 荣 耀 在 山 顶 上 ， 在 以 色 列 人 眼 前 ， 形 状 如 烈 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2196', '2', '24', '18', '摩 西 进 入 云 中 上 山 ， 在 山 上 四 十 昼 夜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2197', '2', '25', '1', '＜ 奉 献 圣 所 （ 出   3 5 : 4 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2198', '2', '25', '2', '“ 你 告 诉 以 色 列 人 当 为 我 送 礼 物 来 ； 凡 甘 心 乐 意 的 ， 你 们 就 可 以 收 下 归 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2199', '2', '25', '3', '所 要 收 的 礼 物 ： 就 是 金 、 银 、 铜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2200', '2', '25', '4', '蓝 色 、 紫 色 、 朱 红 色 线 ， 细 麻 ， 山 羊 毛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2201', '2', '25', '5', '染 红 的 公 羊 皮 ， 海 狗 皮 ， 皂 荚 木 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2202', '2', '25', '6', '点 灯 的 油 并 做 膏 油 和 香 的 香 料 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2203', '2', '25', '7', '红 玛 瑙 与 别 样 的 宝 石 ， 可 以 镶 嵌 在 以 弗 得 和 胸 牌 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2204', '2', '25', '8', '又 当 为 我 造 圣 所 ， 使 我 可 以 住 在 他 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2205', '2', '25', '9', '制 造 帐 幕 和 其 中 的 一 切 器 具 都 要 照 我 所 指 示 你 的 样 式 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2206', '2', '25', '10', '＜ 约 柜 （ 出   3 7 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2207', '2', '25', '11', '要 里 外 包 上 精 金 ， 四 围 镶 上 金 牙 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2208', '2', '25', '12', '也 要 铸 四 个 金 环 ， 安 在 柜 的 四 脚 上 ； 这 边 两 环 ， 那 边 两 环 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2209', '2', '25', '13', '要 用 皂 荚 木 做 两 根 杠 ， 用 金 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2210', '2', '25', '14', '要 把 杠 穿 在 柜 旁 的 环 内 ， 以 便 抬 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2211', '2', '25', '15', '这 杠 要 常 在 柜 的 环 内 ， 不 可 抽 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2212', '2', '25', '16', '必 将 我 所 要 赐 给 你 的 法 版 放 在 柜 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2213', '2', '25', '17', '要 用 精 金 做 施 恩 座 ｛ 施 恩 ： 或 译 蔽 罪 ； 下 同 ｝ ， 长 二 肘 半 ， 宽 一 肘 半 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2214', '2', '25', '18', '要 用 金 子 锤 出 两 个 基 路 伯 来 ， 安 在 施 恩 座 的 两 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2215', '2', '25', '19', '这 头 做 一 个 基 路 伯 ， 那 头 做 一 个 基 路 伯 ， 二 基 路 伯 要 接 连 一 块 ， 在 施 恩 座 的 两 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2216', '2', '25', '20', '二 基 路 伯 要 高 张 翅 膀 ， 遮 掩 施 恩 座 。 基 路 伯 要 脸 对 脸 ， 朝 着 施 恩 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2217', '2', '25', '21', '要 将 施 恩 座 安 在 柜 的 上 边 ， 又 将 我 所 要 赐 给 你 的 法 版 放 在 柜 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2218', '2', '25', '22', '我 要 在 那 里 与 你 相 会 ， 又 要 从 法 柜 施 恩 座 上 二 基 路 伯 中 间 ， 和 你 说 我 所 要 吩 咐 你 传 给 以 色 列 人 的 一 切 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2219', '2', '25', '23', '＜ 陈 设 饼 的 桌 子 （ 出   3 7 : 1 0 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2220', '2', '25', '24', '要 包 上 精 金 ， 四 围 镶 上 金 牙 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2221', '2', '25', '25', '桌 子 的 四 围 各 做 一 掌 宽 的 横 梁 ， 横 梁 上 镶 着 金 牙 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2222', '2', '25', '26', '要 做 四 个 金 环 ， 安 在 桌 子 的 四 角 上 ， 就 是 桌 子 四 脚 上 的 四 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2223', '2', '25', '27', '安 环 子 的 地 方 要 挨 近 横 梁 ， 可 以 穿 杠 抬 桌 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2224', '2', '25', '28', '要 用 皂 荚 木 做 两 根 杠 ， 用 金 包 裹 ， 以 便 抬 桌 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2225', '2', '25', '29', '要 做 桌 子 上 的 盘 子 、 调 羹 ， 并 奠 酒 的 爵 和 瓶 ； 这 都 要 用 精 金 制 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2226', '2', '25', '30', '又 要 在 桌 子 上 ， 在 我 面 前 ， 常 摆 陈 设 饼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2227', '2', '25', '31', '＜ 灯 台 （ 出   3 7 : 1 7 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2228', '2', '25', '32', '灯 台 两 旁 要 杈 出 六 个 枝 子 ： 这 旁 三 个 ， 那 旁 三 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2229', '2', '25', '33', '这 旁 每 枝 上 有 三 个 杯 ， 形 状 像 杏 花 ， 有 球 ， 有 花 ； 那 旁 每 枝 上 也 有 三 个 杯 ， 形 状 像 杏 花 ， 有 球 ， 有 花 。 从 灯 台 杈 出 来 的 六 个 枝 子 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2230', '2', '25', '34', '灯 台 上 有 四 个 杯 ， 形 状 像 杏 花 ， 有 球 ， 有 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2231', '2', '25', '35', '灯 台 每 两 个 枝 子 以 下 有 球 与 枝 子 接 连 一 块 。 灯 台 出 的 六 个 枝 子 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2232', '2', '25', '36', '球 和 枝 子 要 接 连 一 块 ， 都 是 一 块 精 金 锤 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2233', '2', '25', '37', '要 做 灯 台 的 七 个 灯 盏 。 祭 司 要 点 这 灯 ， 使 灯 光 对 照 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2234', '2', '25', '38', '灯 台 的 蜡 剪 和 蜡 花 盘 也 是 要 精 金 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2235', '2', '25', '39', '做 灯 台 和 这 一 切 的 器 具 要 用 精 金 一 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2236', '2', '25', '40', '要 谨 慎 做 这 些 物 件 ， 都 要 照 着 在 山 上 指 示 你 的 样 式 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2237', '2', '26', '1', '＜ 会 幕 （ 出   3 6 : 8 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2238', '2', '26', '2', '每 幅 幔 子 要 长 二 十 八 肘 ， 宽 四 肘 ， 幔 子 都 要 一 样 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2239', '2', '26', '3', '这 五 幅 幔 子 要 幅 幅 相 连 ； 那 五 幅 幔 子 也 要 幅 幅 相 连 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2240', '2', '26', '4', '在 这 相 连 的 幔 子 末 幅 边 上 要 做 蓝 色 的 钮 扣 ； 在 那 相 连 的 幔 子 末 幅 边 上 也 要 照 样 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2241', '2', '26', '5', '要 在 这 相 连 的 幔 子 上 做 五 十 个 钮 扣 ； 在 那 相 连 的 幔 子 上 也 做 五 十 个 钮 扣 ， 都 要 两 两 相 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2242', '2', '26', '6', '又 要 做 五 十 个 金 钩 ， 用 钩 使 幔 子 相 连 ， 这 才 成 了 一 个 帐 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2243', '2', '26', '7', '“ 你 要 用 山 羊 毛 织 十 一 幅 幔 子 ， 作 为 帐 幕 以 上 的 罩 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2244', '2', '26', '8', '每 幅 幔 子 要 长 三 十 肘 ， 宽 四 肘 ； 十 一 幅 幔 子 都 要 一 样 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2245', '2', '26', '9', '要 把 五 幅 幔 子 连 成 一 幅 ， 又 把 六 幅 幔 子 连 成 一 幅 ， 这 第 六 幅 幔 子 要 在 罩 棚 的 前 面 摺 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2246', '2', '26', '10', '在 这 相 连 的 幔 子 末 幅 边 上 要 做 五 十 个 钮 扣 ； 在 那 相 连 的 幔 子 末 幅 边 上 也 做 五 十 个 钮 扣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2247', '2', '26', '11', '又 要 做 五 十 个 铜 钩 ， 钩 在 钮 扣 中 ， 使 罩 棚 连 成 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2248', '2', '26', '12', '罩 棚 的 幔 子 所 余 那 垂 下 来 的 半 幅 幔 子 ， 要 垂 在 帐 幕 的 后 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2249', '2', '26', '13', '罩 棚 的 幔 子 所 余 长 的 ， 这 边 一 肘 ， 那 边 一 肘 ， 要 垂 在 帐 幕 的 两 旁 ， 遮 盖 帐 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2250', '2', '26', '14', '又 要 用 染 红 的 公 羊 皮 做 罩 棚 的 盖 ； 再 用 海 狗 皮 做 一 层 罩 棚 上 的 顶 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2251', '2', '26', '15', '“ 你 要 用 皂 荚 木 做 帐 幕 的 竖 板 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2252', '2', '26', '16', '每 块 要 长 十 肘 ， 宽 一 肘 半 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2253', '2', '26', '17', '每 块 必 有 两 榫 相 对 。 帐 幕 一 切 的 板 都 要 这 样 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2254', '2', '26', '18', '帐 幕 的 南 面 要 做 板 二 十 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2255', '2', '26', '19', '在 这 二 十 块 板 底 下 要 做 四 十 个 带 卯 的 银 座 ， 两 卯 接 这 块 板 上 的 两 榫 ， 两 卯 接 那 块 板 上 的 两 榫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2256', '2', '26', '20', '帐 幕 第 二 面 ， 就 是 北 面 ， 也 要 做 板 二 十 块');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2257', '2', '26', '21', '和 带 卯 的 银 座 四 十 个 ； 这 板 底 下 有 两 卯 ， 那 板 底 下 也 有 两 卯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2258', '2', '26', '22', '帐 幕 的 后 面 ， 就 是 西 面 ， 要 做 板 六 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2259', '2', '26', '23', '帐 幕 后 面 的 拐 角 要 做 板 两 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2260', '2', '26', '24', '板 的 下 半 截 要 双 的 ， 上 半 截 要 整 的 ， 直 顶 到 第 一 个 环 子 ； 两 块 都 要 这 样 做 两 个 拐 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2261', '2', '26', '25', '必 有 八 块 板 和 十 六 个 带 卯 的 银 座 ； 这 板 底 下 有 两 卯 ， 那 板 底 下 也 有 两 卯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2262', '2', '26', '26', '“ 你 要 用 皂 荚 木 做 闩 ： 为 帐 幕 这 面 的 板 做 五 闩 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2263', '2', '26', '27', '为 帐 幕 那 面 的 板 做 五 闩 ， 又 为 帐 幕 后 面 的 板 做 五 闩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2264', '2', '26', '28', '板 腰 间 的 中 闩 要 从 这 一 头 通 到 那 一 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2265', '2', '26', '29', '板 要 用 金 子 包 裹 ， 又 要 做 板 上 的 金 环 套 闩 ； 闩 也 要 用 金 子 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2266', '2', '26', '30', '要 照 着 在 山 上 指 示 你 的 样 式 立 起 帐 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2267', '2', '26', '31', '“ 你 要 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 捻 的 细 麻 织 幔 子 ， 以 巧 匠 的 手 工 绣 上 基 路 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2268', '2', '26', '32', '要 把 幔 子 挂 在 四 根 包 金 的 皂 荚 木 柱 子 上 ， 柱 子 上 当 有 金 钩 ， 柱 子 安 在 四 个 带 卯 的 银 座 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2269', '2', '26', '33', '要 使 幔 子 垂 在 钩 子 下 ， 把 法 柜 抬 进 幔 子 内 ； 这 幔 子 要 将 圣 所 和 至 圣 所 隔 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2270', '2', '26', '34', '又 要 把 施 恩 座 安 在 至 圣 所 内 的 法 柜 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2271', '2', '26', '35', '把 桌 子 安 在 幔 子 外 帐 幕 的 北 面 ； 把 灯 台 安 在 帐 幕 的 南 面 ， 彼 此 相 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2272', '2', '26', '36', '“ 你 要 拿 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 捻 的 细 麻 ， 用 绣 花 的 手 工 织 帐 幕 的 门 帘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2273', '2', '26', '37', '要 用 皂 荚 木 为 帘 子 做 五 根 柱 子 ， 用 金 子 包 裹 。 柱 子 上 当 有 金 钩 ； 又 要 为 柱 子 用 铜 铸 造 五 个 带 卯 的 座 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2274', '2', '27', '1', '＜ 祭 坛 （ 出   3 8 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2275', '2', '27', '2', '要 在 坛 的 四 拐 角 上 做 四 个 角 ， 与 坛 接 连 一 块 ， 用 铜 把 坛 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2276', '2', '27', '3', '要 做 盆 ， 收 去 坛 上 的 灰 ， 又 做 铲 子 、 盘 子 、 肉 锸 子 、 火 鼎 ； 坛 上 一 切 的 器 具 都 用 铜 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2277', '2', '27', '4', '要 为 坛 做 一 个 铜 网 ， 在 网 的 四 角 上 做 四 个 铜 环 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2278', '2', '27', '5', '把 网 安 在 坛 四 面 的 围 腰 板 以 下 ， 使 网 从 下 达 到 坛 的 半 腰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2279', '2', '27', '6', '又 要 用 皂 荚 木 为 坛 做 杠 ， 用 铜 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2280', '2', '27', '7', '这 杠 要 穿 在 坛 两 旁 的 环 子 内 ， 用 以 抬 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2281', '2', '27', '8', '要 用 板 做 坛 ， 坛 是 空 的 ， 都 照 着 在 山 上 指 示 你 的 样 式 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2282', '2', '27', '9', '＜ 会 幕 的 周 围 （ 出   3 8 : 9 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2283', '2', '27', '10', '帷 子 的 柱 子 要 二 十 根 ， 带 卯 的 铜 座 二 十 个 。 柱 子 上 的 钩 子 和 杆 子 都 要 用 银 子 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2284', '2', '27', '11', '北 面 也 当 有 帷 子 ， 长 一 百 肘 ， 帷 子 的 柱 子 二 十 根 ， 带 卯 的 铜 座 二 十 个 。 柱 子 上 的 钩 子 和 杆 子 都 要 用 银 子 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2285', '2', '27', '12', '院 子 的 西 面 当 有 帷 子 ， 宽 五 十 肘 ， 帷 子 的 柱 子 十 根 ， 带 卯 的 座 十 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2286', '2', '27', '13', '院 子 的 东 面 要 宽 五 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2287', '2', '27', '14', '门 这 边 的 帷 子 要 十 五 肘 ， 帷 子 的 柱 子 三 根 ， 带 卯 的 座 三 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2288', '2', '27', '15', '门 那 边 的 帷 子 也 要 十 五 肘 ， 帷 子 的 柱 子 三 根 ， 带 卯 的 座 三 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2289', '2', '27', '16', '院 子 的 门 当 有 帘 子 ， 长 二 十 肘 ， 要 拿 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 捻 的 细 麻 ， 用 绣 花 的 手 工 织 成 ， 柱 子 四 根 ， 带 卯 的 座 四 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2290', '2', '27', '17', '院 子 四 围 一 切 的 柱 子 都 要 用 银 杆 连 络 ， 柱 子 上 的 钩 子 要 用 银 做 ， 带 卯 的 座 要 用 铜 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2291', '2', '27', '18', '院 子 要 长 一 百 肘 ， 宽 五 十 肘 ， 高 五 肘 ， 帷 子 要 用 捻 的 细 麻 做 ， 带 卯 的 座 要 用 铜 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2292', '2', '27', '19', '帐 幕 各 样 用 处 的 器 具 ， 并 帐 幕 一 切 的 橛 子 ， 和 院 子 里 一 切 的 橛 子 ， 都 要 用 铜 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2293', '2', '27', '20', '＜ 燃 灯 的 条 例 （ 利   2 4 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2294', '2', '27', '21', '在 会 幕 中 法 柜 前 的 幔 外 ， 亚 伦 和 他 的 儿 子 ， 从 晚 上 到 早 晨 ， 要 在 耶 和 华 面 前 经 理 这 灯 。 这 要 作 以 色 列 人 世 世 代 代 永 远 的 定 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2295', '2', '28', '1', '＜ 祭 司 的 圣 服 （ 出   3 9 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2296', '2', '28', '2', '你 要 给 你 哥 哥 亚 伦 做 圣 衣 为 荣 耀 ， 为 华 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2297', '2', '28', '3', '又 要 吩 咐 一 切 心 中 有 智 慧 的 ， 就 是 我 用 智 慧 的 灵 所 充 满 的 ， 给 亚 伦 做 衣 服 ， 使 他 分 别 为 圣 ， 可 以 给 我 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2298', '2', '28', '4', '所 要 做 的 就 是 胸 牌 、 以 弗 得 、 外 袍 、 杂 色 的 内 袍 、 冠 冕 、 腰 带 ， 使 你 哥 哥 亚 伦 和 他 儿 子 穿 这 圣 服 ， 可 以 给 我 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2299', '2', '28', '5', '要 用 金 线 和 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 细 麻 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2300', '2', '28', '6', '“ 他 们 要 拿 金 线 和 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 捻 的 细 麻 ， 用 巧 匠 的 手 工 做 以 弗 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2301', '2', '28', '7', '以 弗 得 当 有 两 条 肩 带 ， 接 上 两 头 ， 使 它 相 连 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2302', '2', '28', '8', '其 上 巧 工 织 的 带 子 ， 要 和 以 弗 得 一 样 的 做 法 ， 用 以 束 上 ， 与 以 弗 得 接 连 一 块 ， 要 用 金 线 和 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 捻 的 细 麻 做 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2303', '2', '28', '9', '要 取 两 块 红 玛 瑙 ， 在 上 面 刻 以 色 列 儿 子 的 名 字 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2304', '2', '28', '10', '六 个 名 字 在 这 块 宝 石 上 ， 六 个 名 字 在 那 块 宝 石 上 ， 都 照 他 们 生 来 的 次 序 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2305', '2', '28', '11', '要 用 刻 宝 石 的 手 工 ， 仿 佛 刻 图 书 ， 按 着 以 色 列 儿 子 的 名 字 ， 刻 这 两 块 宝 石 ， 要 镶 在 金 槽 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2306', '2', '28', '12', '要 将 这 两 块 宝 石 安 在 以 弗 得 的 两 条 肩 带 上 ， 为 以 色 列 人 做 纪 念 石 。 亚 伦 要 在 两 肩 上 担 他 们 的 名 字 ， 在 耶 和 华 面 前 作 为 纪 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2307', '2', '28', '13', '要 用 金 子 做 二 槽 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2308', '2', '28', '14', '又 拿 精 金 ， 用 拧 工 仿 佛 拧 绳 子 ， 做 两 条 链 子 ， 把 这 拧 成 的 链 子 搭 在 二 槽 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2309', '2', '28', '15', '＜ 胸 牌 （ 出   3 9 : 8 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2310', '2', '28', '16', '这 胸 牌 要 四 方 的 ， 叠 为 两 层 ， 长 一 虎 口 ， 宽 一 虎 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2311', '2', '28', '17', '要 在 上 面 镶 宝 石 四 行 ： 第 一 行 是 红 宝 石 、 红 璧 玺 、 红 玉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2312', '2', '28', '18', '第 二 行 是 绿 宝 石 、 蓝 宝 石 、 金 钢 石 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2313', '2', '28', '19', '第 三 行 是 紫 玛 瑙 、 白 玛 瑙 、 紫 晶 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2314', '2', '28', '20', '第 四 行 是 水 苍 玉 、 红 玛 瑙 、 碧 玉 。 这 都 要 镶 在 金 槽 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2315', '2', '28', '21', '这 些 宝 石 都 要 按 着 以 色 列 十 二 个 儿 子 的 名 字 ， 仿 佛 刻 图 书 ， 刻 十 二 个 支 派 的 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2316', '2', '28', '22', '要 在 胸 牌 上 用 精 金 拧 成 如 绳 的 链 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2317', '2', '28', '23', '在 胸 牌 上 也 要 做 两 个 金 环 ， 安 在 胸 牌 的 两 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2318', '2', '28', '24', '要 把 那 两 条 拧 成 的 金 链 子 ， 穿 过 胸 牌 两 头 的 环 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2319', '2', '28', '25', '又 要 把 链 子 的 那 两 头 接 在 两 槽 上 ， 安 在 以 弗 得 前 面 肩 带 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2320', '2', '28', '26', '要 做 两 个 金 环 ， 安 在 胸 牌 的 两 头 ， 在 以 弗 得 里 面 的 边 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2321', '2', '28', '27', '又 要 做 两 个 金 环 ， 安 在 以 弗 得 前 面 两 条 肩 带 的 下 边 ， 挨 近 相 接 之 处 ， 在 以 弗 得 巧 工 织 的 带 子 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2322', '2', '28', '28', '要 用 蓝 细 带 子 把 胸 牌 的 环 子 与 以 弗 得 的 环 子 系 住 ， 使 胸 牌 贴 在 以 弗 得 巧 工 织 的 带 子 上 ， 不 可 与 以 弗 得 离 缝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2323', '2', '28', '29', '亚 伦 进 圣 所 的 时 候 ， 要 将 决 断 胸 牌 ， 就 是 刻 着 以 色 列 儿 子 名 字 的 ， 带 在 胸 前 ， 在 耶 和 华 面 前 常 作 纪 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2324', '2', '28', '30', '又 要 将 乌 陵 和 土 明 放 在 决 断 的 胸 牌 里 ； 亚 伦 进 到 耶 和 华 面 前 的 时 候 ， 要 带 在 胸 前 ， 在 耶 和 华 面 前 常 将 以 色 列 人 的 决 断 牌 带 在 胸 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2325', '2', '28', '31', '＜ 祭 司 的 其 他 圣 服 （ 出   3 9 : 2 2 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2326', '2', '28', '32', '袍 上 要 为 头 留 一 领 口 ， 口 的 周 围 织 出 领 边 来 ， 仿 佛 铠 甲 的 领 口 ， 免 得 破 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2327', '2', '28', '33', '袍 子 周 围 底 边 上 要 用 蓝 色 、 紫 色 、 朱 红 色 线 做 石 榴 。 在 袍 子 周 围 的 石 榴 中 间 要 有 金 铃 铛 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2328', '2', '28', '34', '一 个 金 铃 铛 一 个 石 榴 ， 一 个 金 铃 铛 一 个 石 榴 ， 在 袍 子 周 围 的 底 边 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2329', '2', '28', '35', '亚 伦 供 职 的 时 候 要 穿 这 袍 子 。 他 进 圣 所 到 耶 和 华 面 前 ， 以 及 出 来 的 时 候 ， 袍 上 的 响 声 必 被 听 见 ， 使 他 不 至 于 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2330', '2', '28', '36', '“ 你 要 用 精 金 做 一 面 牌 ， 在 上 面 按 刻 图 书 之 法 刻 着 ‘ 归 耶 和 华 为 圣 ’ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2331', '2', '28', '37', '要 用 一 条 蓝 细 带 子 将 牌 系 在 冠 冕 的 前 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2332', '2', '28', '38', '这 牌 必 在 亚 伦 的 额 上 ， 亚 伦 要 担 当 干 犯 圣 物 条 例 的 罪 孽 ； 这 圣 物 是 以 色 列 人 在 一 切 的 圣 礼 物 上 所 分 别 为 圣 的 。 这 牌 要 常 在 他 的 额 上 ， 使 他 们 可 以 在 耶 和 华 面 前 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2333', '2', '28', '39', '要 用 杂 色 细 麻 线 织 内 袍 ， 用 细 麻 布 做 冠 冕 ， 又 用 绣 花 的 手 工 做 腰 带 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2334', '2', '28', '40', '“ 你 要 为 亚 伦 的 儿 子 做 内 袍 、 腰 带 、 裹 头 巾 ， 为 荣 耀 ， 为 华 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2335', '2', '28', '41', '要 把 这 些 给 你 的 哥 哥 亚 伦 和 他 的 儿 子 穿 戴 ， 又 要 膏 他 们 ， 将 他 们 分 别 为 圣 ， 好 给 我 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2336', '2', '28', '42', '要 给 他 们 做 细 麻 布 裤 子 ， 遮 掩 下 体 ； 裤 子 当 从 腰 达 到 大 腿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2337', '2', '28', '43', '亚 伦 和 他 儿 子 进 入 会 幕 ， 或 就 近 坛 ， 在 圣 所 供 职 的 时 候 必 穿 上 ， 免 得 担 罪 而 死 。 这 要 为 亚 伦 和 他 的 后 裔 作 永 远 的 定 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2338', '2', '29', '1', '＜ 立 亚 伦 和 他 子 孙 作 祭 司 的 条 例 （ 利   8 : 1 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2339', '2', '29', '2', '无 酵 饼 和 调 油 的 无 酵 饼 ， 与 抹 油 的 无 酵 薄 饼 ； 这 都 要 用 细 麦 面 做 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2340', '2', '29', '3', '这 饼 要 装 在 一 个 筐 子 里 ， 连 筐 子 带 来 ， 又 把 公 牛 和 两 只 公 绵 羊 牵 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2341', '2', '29', '4', '要 使 亚 伦 和 他 儿 子 到 会 幕 门 口 来 ， 用 水 洗 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2342', '2', '29', '5', '要 给 亚 伦 穿 上 内 袍 和 以 弗 得 的 外 袍 ， 并 以 弗 得 ， 又 带 上 胸 牌 ， 束 上 以 弗 得 巧 工 织 的 带 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2343', '2', '29', '6', '把 冠 冕 戴 在 他 头 上 ， 将 圣 冠 加 在 冠 冕 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2344', '2', '29', '7', '就 把 膏 油 倒 在 他 头 上 膏 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2345', '2', '29', '8', '要 叫 他 的 儿 子 来 ， 给 他 们 穿 上 内 袍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2346', '2', '29', '9', '给 亚 伦 和 他 儿 子 束 上 腰 带 ， 包 上 裹 头 巾 ， 他 们 就 凭 永 远 的 定 例 得 了 祭 司 的 职 任 。 又 要 将 亚 伦 和 他 儿 子 分 别 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2347', '2', '29', '10', '“ 你 要 把 公 牛 牵 到 会 幕 前 ， 亚 伦 和 他 儿 子 要 按 手 在 公 牛 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2348', '2', '29', '11', '你 要 在 耶 和 华 面 前 ， 在 会 幕 门 口 ， 宰 这 公 牛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2349', '2', '29', '12', '要 取 些 公 牛 的 血 ， 用 指 头 抹 在 坛 的 四 角 上 ， 把 血 都 倒 在 坛 脚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2350', '2', '29', '13', '要 把 一 切 盖 脏 的 脂 油 与 肝 上 的 网 子 ， 并 两 个 腰 子 和 腰 子 上 的 脂 油 ， 都 烧 在 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2351', '2', '29', '14', '只 是 公 牛 的 皮 、 肉 、 粪 都 要 用 火 烧 在 营 外 。 这 牛 是 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2352', '2', '29', '15', '“ 你 要 牵 一 只 公 绵 羊 来 ， 亚 伦 和 他 儿 子 要 按 手 在 这 羊 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2353', '2', '29', '16', '要 宰 这 羊 ， 把 血 洒 在 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2354', '2', '29', '17', '要 把 羊 切 成 块 子 ， 洗 净 五 脏 和 腿 ， 连 块 子 带 头 ， 都 放 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2355', '2', '29', '18', '要 把 全 羊 烧 在 坛 上 ， 是 给 耶 和 华 献 的 燔 祭 ， 是 献 给 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2356', '2', '29', '19', '“ 你 要 将 那 一 只 公 绵 羊 牵 来 ， 亚 伦 和 他 儿 子 要 按 手 在 羊 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2357', '2', '29', '20', '你 要 宰 这 羊 ， 取 点 血 抹 在 亚 伦 的 右 耳 垂 上 和 他 儿 子 的 右 耳 垂 上 ， 又 抹 在 他 们 右 手 的 大 拇 指 上 和 右 脚 的 大 拇 指 上 ； 并 要 把 血 洒 在 坛 的 四 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2358', '2', '29', '21', '你 要 取 点 膏 油 和 坛 上 的 血 ， 弹 在 亚 伦 和 他 的 衣 服 上 ， 并 他 儿 子 和 他 儿 子 的 衣 服 上 ， 他 们 和 他 们 的 衣 服 就 一 同 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2359', '2', '29', '22', '“ 你 要 取 这 羊 的 脂 油 和 肥 尾 巴 ， 并 盖 脏 的 脂 油 与 肝 上 的 网 子 ， 两 个 腰 子 和 腰 子 上 的 脂 油 并 右 腿 （ 这 是 承 接 圣 职 所 献 的 羊 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2360', '2', '29', '23', '再 从 耶 和 华 面 前 装 无 酵 饼 的 筐 子 中 取 一 个 饼 ， 一 个 调 油 的 饼 和 一 个 薄 饼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2361', '2', '29', '24', '都 放 在 亚 伦 的 手 上 和 他 儿 子 的 手 上 ， 作 为 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2362', '2', '29', '25', '要 从 他 们 手 中 接 过 来 ， 烧 在 耶 和 华 面 前 坛 上 的 燔 祭 上 ， 是 献 给 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2363', '2', '29', '26', '“ 你 要 取 亚 伦 承 接 圣 职 所 献 公 羊 的 胸 ， 作 为 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ， 这 就 可 以 作 你 的 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2364', '2', '29', '27', '那 摇 祭 的 胸 和 举 祭 的 腿 ， 就 是 承 接 圣 职 所 摇 的 、 所 举 的 ， 是 归 亚 伦 和 他 儿 子 的 。 这 些 你 都 要 成 为 圣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2365', '2', '29', '28', '作 亚 伦 和 他 子 孙 从 以 色 列 人 中 永 远 所 得 的 分 ， 因 为 是 举 祭 。 这 要 从 以 色 列 人 的 平 安 祭 中 ， 作 为 献 给 耶 和 华 的 举 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2366', '2', '29', '29', '“ 亚 伦 的 圣 衣 要 留 给 他 的 子 孙 ， 可 以 穿 着 受 膏 ， 又 穿 着 承 接 圣 职 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2367', '2', '29', '30', '他 的 子 孙 接 续 他 当 祭 司 的 ， 每 逢 进 会 幕 在 圣 所 供 职 的 时 候 ， 要 穿 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2368', '2', '29', '31', '“ 你 要 将 承 接 圣 职 所 献 公 羊 的 肉 煮 在 圣 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2369', '2', '29', '32', '亚 伦 和 他 儿 子 要 在 会 幕 门 口 吃 这 羊 的 肉 和 筐 内 的 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2370', '2', '29', '33', '他 们 吃 那 些 赎 罪 之 物 ， 好 承 接 圣 职 ， 使 他 们 成 圣 ； 只 是 外 人 不 可 吃 ， 因 为 这 是 圣 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2371', '2', '29', '34', '那 承 接 圣 职 所 献 的 肉 或 饼 ， 若 有 一 点 留 到 早 晨 ， 就 要 用 火 烧 了 ， 不 可 吃 这 物 ， 因 为 是 圣 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2372', '2', '29', '35', '“ 你 要 这 样 照 我 一 切 所 吩 咐 的 ， 向 亚 伦 和 他 儿 子 行 承 接 圣 职 的 礼 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2373', '2', '29', '36', '每 天 要 献 公 牛 一 只 为 赎 罪 祭 。 你 洁 净 坛 的 时 候 ， 坛 就 洁 净 了 ； 且 要 用 膏 抹 坛 ， 使 坛 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2374', '2', '29', '37', '要 洁 净 坛 七 天 ， 使 坛 成 圣 ， 坛 就 成 为 至 圣 。 凡 挨 着 坛 的 都 成 为 圣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2375', '2', '29', '38', '＜ 每 天 当 献 的 祭 （ 民   2 8 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2376', '2', '29', '39', '早 晨 要 献 这 一 只 ， 黄 昏 的 时 候 要 献 那 一 只 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2377', '2', '29', '40', '和 这 一 只 羊 羔 同 献 的 ， 要 用 细 面 伊 法 十 分 之 一 与 捣 成 的 油 一 欣 四 分 之 一 调 和 ， 又 用 酒 一 欣 四 分 之 一 作 为 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2378', '2', '29', '41', '那 一 只 羊 羔 要 在 黄 昏 的 时 候 献 上 ， 照 着 早 晨 的 素 祭 和 奠 祭 的 礼 办 理 ， 作 为 献 给 耶 和 华 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2379', '2', '29', '42', '这 要 在 耶 和 华 面 前 、 会 幕 门 口 ， 作 你 们 世 世 代 代 常 献 的 燔 祭 。 我 要 在 那 里 与 你 们 相 会 ， 和 你 们 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2380', '2', '29', '43', '我 要 在 那 里 与 以 色 列 人 相 会 ， 会 幕 就 要 因 我 的 荣 耀 成 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2381', '2', '29', '44', '我 要 使 会 幕 和 坛 成 圣 ， 也 要 使 亚 伦 和 他 的 儿 子 成 圣 ， 给 我 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2382', '2', '29', '45', '我 要 住 在 以 色 列 人 中 间 ， 作 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2383', '2', '29', '46', '他 们 必 知 道 我 是 耶 和 华 ─ ─ 他 们 的 神 ， 是 将 他 们 从 埃 及 地 领 出 来 的 ， 为 要 住 在 他 们 中 间 。 我 是 耶 和 华 ─ ─ 他 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2384', '2', '30', '1', '＜ 香 坛 （ 出   3 7 : 2 5 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2385', '2', '30', '2', '这 坛 要 四 方 的 ， 长 一 肘 ， 宽 一 肘 ， 高 二 肘 ； 坛 的 四 角 要 与 坛 接 连 一 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2386', '2', '30', '3', '要 用 精 金 把 坛 的 上 面 与 坛 的 四 围 ， 并 坛 的 四 角 ， 包 裹 ； 又 要 在 坛 的 四 围 镶 上 金 牙 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2387', '2', '30', '4', '要 做 两 个 金 环 安 在 牙 子 边 以 下 ， 在 坛 的 两 旁 ， 两 根 横 撑 上 ， 作 为 穿 杠 的 用 处 ， 以 便 抬 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2388', '2', '30', '5', '要 用 皂 荚 木 做 杠 ， 用 金 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2389', '2', '30', '6', '要 把 坛 放 在 法 柜 前 的 幔 子 外 ， 对 着 法 柜 上 的 施 恩 座 ， 就 是 我 要 与 你 相 会 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2390', '2', '30', '7', '亚 伦 在 坛 上 要 烧 馨 香 料 做 的 香 ； 每 早 晨 他 收 拾 灯 的 时 候 ， 要 烧 这 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2391', '2', '30', '8', '黄 昏 点 灯 的 时 候 ， 他 要 在 耶 和 华 面 前 烧 这 香 ， 作 为 世 世 代 代 常 烧 的 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2392', '2', '30', '9', '在 这 坛 上 不 可 奉 上 异 样 的 香 ， 不 可 献 燔 祭 、 素 祭 ， 也 不 可 浇 上 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2393', '2', '30', '10', '亚 伦 一 年 一 次 要 在 坛 的 角 上 行 赎 罪 之 礼 。 他 一 年 一 次 要 用 赎 罪 祭 牲 的 血 在 坛 上 行 赎 罪 之 礼 ， 作 为 世 世 代 代 的 定 例 。 这 坛 在 耶 和 华 面 前 为 至 圣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2394', '2', '30', '11', '＜ 会 幕 的 捐 献 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2395', '2', '30', '12', '“ 你 要 按 以 色 列 人 被 数 的 ， 计 算 总 数 ， 你 数 的 时 候 ， 他 们 各 人 要 为 自 己 的 生 命 把 赎 价 奉 给 耶 和 华 ， 免 得 数 的 时 候 在 他 们 中 间 有 灾 殃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2396', '2', '30', '13', '凡 过 去 归 那 些 被 数 之 人 的 ， 每 人 要 按 圣 所 的 平 ， 拿 银 子 半 舍 客 勒 ； 这 半 舍 客 勒 是 奉 给 耶 和 华 的 礼 物 （ 一 舍 客 勒 是 二 十 季 拉 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2397', '2', '30', '14', '凡 过 去 归 那 些 被 数 的 人 ， 从 二 十 岁 以 外 的 ， 要 将 这 礼 物 奉 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2398', '2', '30', '15', '他 们 为 赎 生 命 将 礼 物 奉 给 耶 和 华 ， 富 足 的 不 可 多 出 ， 贫 穷 的 也 不 可 少 出 ， 各 人 要 出 半 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2399', '2', '30', '16', '你 要 从 以 色 列 人 收 这 赎 罪 银 ， 作 为 会 幕 的 使 用 ， 可 以 在 耶 和 华 面 前 为 以 色 列 人 作 纪 念 ， 赎 生 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2400', '2', '30', '17', '＜ 铜 盆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2401', '2', '30', '18', '“ 你 要 用 铜 做 洗 濯 盆 和 盆 座 ， 以 便 洗 濯 。 要 将 盆 放 在 会 幕 和 坛 的 中 间 ， 在 盆 里 盛 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2402', '2', '30', '19', '亚 伦 和 他 的 儿 子 要 在 这 盆 里 洗 手 洗 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2403', '2', '30', '20', '他 们 进 会 幕 ， 或 是 就 近 坛 前 供 职 给 耶 和 华 献 火 祭 的 时 候 ， 必 用 水 洗 濯 ， 免 得 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2404', '2', '30', '21', '他 们 洗 手 洗 脚 就 免 得 死 亡 。 这 要 作 亚 伦 和 他 后 裔 世 世 代 代 永 远 的 定 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2405', '2', '30', '22', '＜ 圣 膏 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2406', '2', '30', '23', '“ 你 要 取 上 品 的 香 料 ， 就 是 流 质 的 没 药 五 百 舍 客 勒 ， 香 肉 桂 一 半 ， 就 是 二 百 五 十 舍 客 勒 ， 菖 蒲 二 百 五 十 舍 客 勒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2407', '2', '30', '24', '桂 皮 五 百 舍 客 勒 ， 都 按 着 圣 所 的 平 ， 又 取 橄 榄 油 一 欣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2408', '2', '30', '25', '按 做 香 之 法 调 和 做 成 圣 膏 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2409', '2', '30', '26', '要 用 这 膏 油 抹 会 幕 和 法 柜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2410', '2', '30', '27', '桌 子 与 桌 子 的 一 切 器 具 ， 灯 台 和 灯 台 的 器 具 ， 并 香 坛 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2411', '2', '30', '28', '燔 祭 坛 ， 和 坛 的 一 切 器 具 ， 洗 濯 盆 和 盆 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2412', '2', '30', '29', '要 使 这 些 物 成 为 圣 ， 好 成 为 至 圣 ； 凡 挨 着 的 都 成 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2413', '2', '30', '30', '要 膏 亚 伦 和 他 的 儿 子 ， 使 他 们 成 为 圣 ， 可 以 给 我 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2414', '2', '30', '31', '你 要 对 以 色 列 人 说 ： ‘ 这 油 ， 我 要 世 世 代 代 以 为 圣 膏 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2415', '2', '30', '32', '不 可 倒 在 别 人 的 身 上 ， 也 不 可 按 这 调 和 之 法 做 与 此 相 似 的 。 这 膏 油 是 圣 的 ， 你 们 也 要 以 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2416', '2', '30', '33', '凡 调 和 与 此 相 似 的 ， 或 将 这 膏 膏 在 别 人 身 上 的 ， 这 人 要 从 民 中 剪 除 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2417', '2', '30', '34', '＜ 香 的 做 法 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2418', '2', '30', '35', '你 要 用 这 些 加 上 盐 ， 按 做 香 之 法 做 成 清 净 圣 洁 的 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2419', '2', '30', '36', '这 香 要 取 点 捣 得 极 细 ， 放 在 会 幕 内 、 法 柜 前 ， 我 要 在 那 里 与 你 相 会 。 你 们 要 以 这 香 为 至 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2420', '2', '30', '37', '你 们 不 可 按 这 调 和 之 法 为 自 己 做 香 ； 要 以 这 香 为 圣 ， 归 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2421', '2', '30', '38', '凡 做 香 和 这 香 一 样 ， 为 要 闻 香 味 的 ， 这 人 要 从 民 中 剪 除 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2422', '2', '31', '1', '＜ 会 幕 的 技 工 （ 出   3 5 : 3 0 - 3 6 : 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2423', '2', '31', '2', '“ 看 哪 ， 犹 大 支 派 中 ， 户 珥 的 孙 子 、 乌 利 的 儿 子 比 撒 列 ， 我 已 经 题 他 的 名 召 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2424', '2', '31', '3', '我 也 以 我 的 灵 充 满 了 他 ， 使 他 有 智 慧 ， 有 聪 明 ， 有 知 识 ， 能 做 各 样 的 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2425', '2', '31', '4', '能 想 出 巧 工 ， 用 金 、 银 、 铜 制 造 各 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2426', '2', '31', '5', '又 能 刻 宝 石 ， 可 以 镶 嵌 ， 能 雕 刻 木 头 ， 能 做 各 样 的 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2427', '2', '31', '6', '我 分 派 但 支 派 中 、 亚 希 撒 抹 的 儿 子 亚 何 利 亚 伯 与 他 同 工 。 凡 心 里 有 智 慧 的 ， 我 更 使 他 们 有 智 慧 ， 能 做 我 一 切 所 吩 咐 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2428', '2', '31', '7', '就 是 会 幕 和 法 柜 ， 并 其 上 的 施 恩 座 ， 与 会 幕 中 一 切 的 器 具 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2429', '2', '31', '8', '桌 子 和 桌 子 的 器 具 ， 精 金 的 灯 台 和 灯 台 的 一 切 器 具 并 香 坛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2430', '2', '31', '9', '燔 祭 坛 和 坛 的 一 切 器 具 ， 并 洗 濯 盆 与 盆 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2431', '2', '31', '10', '精 工 做 的 礼 服 ， 和 祭 司 亚 伦 并 他 儿 子 用 以 供 祭 司 职 分 的 圣 衣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2432', '2', '31', '11', '膏 油 和 为 圣 所 用 馨 香 的 香 料 。 他 们 都 要 照 我 一 切 所 吩 咐 的 去 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2433', '2', '31', '12', '＜ 安 息 日 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2434', '2', '31', '13', '“ 你 要 吩 咐 以 色 列 人 说 ： ‘ 你 们 务 要 守 我 的 安 息 日 ； 因 为 这 是 你 我 之 间 世 世 代 代 的 证 据 ， 使 你 们 知 道 我 ─ ─ 耶 和 华 是 叫 你 们 成 为 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2435', '2', '31', '14', '所 以 你 们 要 守 安 息 日 ， 以 为 圣 日 。 凡 干 犯 这 日 的 ， 必 要 把 他 治 死 ； 凡 在 这 日 做 工 的 ， 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2436', '2', '31', '15', '六 日 要 做 工 ， 但 第 七 日 是 安 息 圣 日 ， 是 向 耶 和 华 守 为 圣 的 。 凡 在 安 息 日 做 工 的 ， 必 要 把 他 治 死 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2437', '2', '31', '16', '故 此 ， 以 色 列 人 要 世 世 代 代 守 安 息 日 为 永 远 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2438', '2', '31', '17', '这 是 我 和 以 色 列 人 永 远 的 证 据 ； 因 为 六 日 之 内 耶 和 华 造 天 地 ， 第 七 日 便 安 息 舒 畅 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2439', '2', '31', '18', '耶 和 华 在 西 奈 山 和 摩 西 说 完 了 话 ， 就 把 两 块 法 版 交 给 他 ， 是 神 用 指 头 写 的 石 版 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2440', '2', '32', '1', '＜ 金 牛 犊 （ 申   9 : 6 - 2 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2441', '2', '32', '2', '亚 伦 对 他 们 说 ： “ 你 们 去 摘 下 你 们 妻 子 、 儿 女 耳 上 的 金 环 ， 拿 来 给 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2442', '2', '32', '3', '百 姓 就 都 摘 下 他 们 耳 上 的 金 环 ， 拿 来 给 亚 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2443', '2', '32', '4', '亚 伦 从 他 们 手 里 接 过 来 ， 铸 了 一 只 牛 犊 ， 用 雕 刻 的 器 具 做 成 。 他 们 就 说 ： “ 以 色 列 啊 ， 这 是 领 你 出 埃 及 地 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2444', '2', '32', '5', '亚 伦 看 见 ， 就 在 牛 犊 面 前 筑 坛 ， 且 宣 告 说 ： “ 明 日 要 向 耶 和 华 守 节 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2445', '2', '32', '6', '次 日 清 早 ， 百 姓 起 来 献 燔 祭 和 平 安 祭 ， 就 坐 下 吃 喝 ， 起 来 玩 耍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2446', '2', '32', '7', '耶 和 华 吩 咐 摩 西 说 ： “ 下 去 吧 ， 因 为 你 的 百 姓 ， 就 是 你 从 埃 及 地 领 出 来 的 ， 已 经 败 坏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2447', '2', '32', '8', '他 们 快 快 偏 离 了 我 所 吩 咐 的 道 ， 为 自 己 铸 了 一 只 牛 犊 ， 向 它 下 拜 献 祭 ， 说 ： “ 以 色 列 啊 ， 这 就 是 领 你 出 埃 及 地 的 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2448', '2', '32', '9', '耶 和 华 对 摩 西 说 ： “ 我 看 这 百 姓 真 是 硬 着 颈 项 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2449', '2', '32', '10', '你 且 由 着 我 ， 我 要 向 他 们 发 烈 怒 ， 将 他 们 灭 绝 ， 使 你 的 后 裔 成 为 大 国 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2450', '2', '32', '11', '摩 西 便 恳 求 耶 和 华 ─ ─ 他 的 神 说 ： “ 耶 和 华 啊 ， 你 为 什 么 向 你 的 百 姓 发 烈 怒 呢 ？ 这 百 姓 是 你 用 大 力 和 大 能 的 手 从 埃 及 地 领 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2451', '2', '32', '12', '为 什 么 使 埃 及 人 议 论 说 ‘ 他 领 他 们 出 去 ， 是 要 降 祸 与 他 们 ， 把 他 们 杀 在 山 中 ， 将 他 们 从 地 上 除 灭 ’ ？ 求 你 转 意 ， 不 发 你 的 烈 怒 ， 后 悔 ， 不 降 祸 与 你 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2452', '2', '32', '13', '求 你 记 念 你 的 仆 人 亚 伯 拉 罕 、 以 撒 、 以 色 列 。 你 曾 指 着 自 己 起 誓 说 ： ‘ 我 必 使 你 们 的 后 裔 像 天 上 的 星 那 样 多 ， 并 且 我 所 应 许 的 这 全 地 ， 必 给 你 们 的 后 裔 ， 他 们 要 永 远 承 受 为 业 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2453', '2', '32', '14', '于 是 耶 和 华 后 悔 ， 不 把 所 说 的 祸 降 与 他 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2454', '2', '32', '15', '摩 西 转 身 下 山 ， 手 里 拿 着 两 块 法 版 。 这 版 是 两 面 写 的 ， 这 面 那 面 都 有 字 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2455', '2', '32', '16', '是 神 的 工 作 ， 字 是 神 写 的 ， 刻 在 版 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2456', '2', '32', '17', '约 书 亚 一 听 见 百 姓 呼 喊 的 声 音 ， 就 对 摩 西 说 ： “ 在 营 里 有 争 战 的 声 音 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2457', '2', '32', '18', '摩 西 说 ： “ 这 不 是 人 打 胜 仗 的 声 音 ， 也 不 是 人 打 败 仗 的 声 音 ， 我 所 听 见 的 乃 是 人 歌 唱 的 声 音 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2458', '2', '32', '19', '摩 西 挨 近 营 前 就 看 见 牛 犊 ， 又 看 见 人 跳 舞 ， 便 发 烈 怒 ， 把 两 块 版 扔 在 山 下 摔 碎 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2459', '2', '32', '20', '又 将 他 们 所 铸 的 牛 犊 用 火 焚 烧 ， 磨 得 粉 碎 ， 撒 在 水 面 上 ， 叫 以 色 列 人 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2460', '2', '32', '21', '摩 西 对 亚 伦 说 ： “ 这 百 姓 向 你 做 了 什 么 ？ 你 竟 使 他 们 陷 在 大 罪 里 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2461', '2', '32', '22', '亚 伦 说 ： “ 求 我 主 不 要 发 烈 怒 。 这 百 姓 专 于 作 恶 ， 是 你 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2462', '2', '32', '23', '他 们 对 我 说 ： ‘ 你 为 我 们 做 神 像 ， 可 以 在 我 们 前 面 引 路 ； 因 为 领 我 们 出 埃 及 地 的 那 个 摩 西 ， 我 们 不 知 道 他 遭 了 什 么 事 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2463', '2', '32', '24', '我 对 他 们 说 ： ‘ 凡 有 金 环 的 可 以 摘 下 来 ’ ， 他 们 就 给 了 我 。 我 把 金 环 扔 在 火 中 ， 这 牛 犊 便 出 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2464', '2', '32', '25', '摩 西 见 百 姓 放 肆 （ 亚 伦 纵 容 他 们 ， 使 他 们 在 仇 敌 中 间 被 讥 刺 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2465', '2', '32', '26', '就 站 在 营 门 中 ， 说 ： “ 凡 属 耶 和 华 的 ， 都 要 到 我 这 里 来 ！ ” 于 是 利 未 的 子 孙 都 到 他 那 里 聚 集 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2466', '2', '32', '27', '他 对 他 们 说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 这 样 说 ： ‘ 你 们 各 人 把 刀 跨 在 腰 间 ， 在 营 中 往 来 ， 从 这 门 到 那 门 ， 各 人 杀 他 的 弟 兄 与 同 伴 并 邻 舍 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2467', '2', '32', '28', '利 未 的 子 孙 照 摩 西 的 话 行 了 。 那 一 天 百 姓 中 被 杀 的 约 有 三 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2468', '2', '32', '29', '摩 西 说 ： “ 今 天 你 们 要 自 洁 ， 归 耶 和 华 为 圣 ， 各 人 攻 击 他 的 儿 子 和 弟 兄 ， 使 耶 和 华 赐 福 与 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2469', '2', '32', '30', '到 了 第 二 天 ， 摩 西 对 百 姓 说 ： “ 你 们 犯 了 大 罪 。 我 如 今 要 上 耶 和 华 那 里 去 ， 或 者 可 以 为 你 们 赎 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2470', '2', '32', '31', '摩 西 回 到 耶 和 华 那 里 ， 说 ： “ 唉 ！ 这 百 姓 犯 了 大 罪 ， 为 自 己 做 了 金 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2471', '2', '32', '32', '倘 或 你 肯 赦 免 他 们 的 罪 … … 不 然 ， 求 你 从 你 所 写 的 册 上 涂 抹 我 的 名 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2472', '2', '32', '33', '耶 和 华 对 摩 西 说 ： “ 谁 得 罪 我 ， 我 就 从 我 的 册 上 涂 抹 谁 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2473', '2', '32', '34', '现 在 你 去 领 这 百 姓 ， 往 我 所 告 诉 你 的 地 方 去 ， 我 的 使 者 必 在 你 前 面 引 路 ； 只 是 到 我 追 讨 的 日 子 ， 我 必 追 讨 他 们 的 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2474', '2', '32', '35', '耶 和 华 杀 百 姓 的 缘 故 是 因 他 们 同 亚 伦 做 了 牛 犊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2475', '2', '33', '1', '＜ 耶 和 华 吩 咐 以 色 列 人 离 开 西 奈 山 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2476', '2', '33', '2', '我 要 差 遣 使 者 在 你 前 面 ， 撵 出 迦 南 人 、 亚 摩 利 人 、 赫 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2477', '2', '33', '3', '领 你 到 那 流 奶 与 蜜 之 地 。 我 自 己 不 同 你 们 上 去 ； 因 为 你 们 是 硬 着 颈 项 的 百 姓 ， 恐 怕 我 在 路 上 把 你 们 灭 绝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2478', '2', '33', '4', '百 姓 听 见 这 凶 信 就 悲 哀 ， 也 没 有 人 佩 戴 妆 饰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2479', '2', '33', '5', '耶 和 华 对 摩 西 说 ： “ 你 告 诉 以 色 列 人 说 ： ‘ 耶 和 华 说 ： 你 们 是 硬 着 颈 项 的 百 姓 ， 我 若 一 霎 时 临 到 你 们 中 间 ， 必 灭 绝 你 们 。 现 在 你 们 要 把 身 上 的 妆 饰 摘 下 来 ， 使 我 可 以 知 道 怎 样 待 你 们 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2480', '2', '33', '6', '以 色 列 人 从 住 何 烈 山 以 后 ， 就 把 身 上 的 妆 饰 摘 得 干 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2481', '2', '33', '7', '＜ 耶 和 华 的 会 幕 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2482', '2', '33', '8', '当 摩 西 出 营 到 会 幕 去 的 时 候 ， 百 姓 就 都 起 来 ， 各 人 站 在 自 己 帐 棚 的 门 口 ， 望 着 摩 西 ， 直 等 到 他 进 了 会 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2483', '2', '33', '9', '摩 西 进 会 幕 的 时 候 ， 云 柱 降 下 来 ， 立 在 会 幕 的 门 前 ， 耶 和 华 便 与 摩 西 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2484', '2', '33', '10', '众 百 姓 看 见 云 柱 立 在 会 幕 门 前 ， 就 都 起 来 ， 各 人 在 自 己 帐 棚 的 门 口 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2485', '2', '33', '11', '耶 和 华 与 摩 西 面 对 面 说 话 ， 好 像 人 与 朋 友 说 话 一 般 。 摩 西 转 到 营 里 去 ， 惟 有 他 的 帮 手 ─ ─ 一 个 少 年 人 嫩 的 儿 子 约 书 亚 不 离 开 会 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2486', '2', '33', '12', '＜ 耶 和 华 应 许 跟 百 姓 同 在 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2487', '2', '33', '13', '我 如 今 若 在 你 眼 前 蒙 恩 ， 求 你 将 你 的 道 指 示 我 ， 使 我 可 以 认 识 你 ， 好 在 你 眼 前 蒙 恩 。 求 你 想 到 这 民 是 你 的 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2488', '2', '33', '14', '耶 和 华 说 ： “ 我 必 亲 自 和 你 同 去 ， 使 你 得 安 息 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2489', '2', '33', '15', '摩 西 说 ： “ 你 若 不 亲 自 和 我 同 去 ， 就 不 要 把 我 们 从 这 里 领 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2490', '2', '33', '16', '人 在 何 事 上 得 以 知 道 我 和 你 的 百 姓 在 你 眼 前 蒙 恩 呢 ？ 岂 不 是 因 你 与 我 们 同 去 、 使 我 和 你 的 百 姓 与 地 上 的 万 民 有 分 别 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2491', '2', '33', '17', '耶 和 华 对 摩 西 说 ： “ 你 这 所 求 的 我 也 要 行 ； 因 为 你 在 我 眼 前 蒙 了 恩 ， 并 且 我 按 你 的 名 认 识 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2492', '2', '33', '18', '摩 西 说 ： “ 求 你 显 出 你 的 荣 耀 给 我 看 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2493', '2', '33', '19', '耶 和 华 说 ： “ 我 要 显 我 一 切 的 恩 慈 ， 在 你 面 前 经 过 ， 宣 告 我 的 名 。 我 要 恩 待 谁 就 恩 待 谁 ； 要 怜 悯 谁 就 怜 悯 谁 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2494', '2', '33', '20', '又 说 ： “ 你 不 能 看 见 我 的 面 ， 因 为 人 见 我 的 面 不 能 存 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2495', '2', '33', '21', '耶 和 华 说 ： “ 看 哪 ， 在 我 这 里 有 地 方 ， 你 要 站 在 磐 石 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2496', '2', '33', '22', '我 的 荣 耀 经 过 的 时 候 ， 我 必 将 你 放 在 磐 石 穴 中 ， 用 我 的 手 遮 掩 你 ， 等 我 过 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2497', '2', '33', '23', '然 后 我 要 将 我 的 手 收 回 ， 你 就 得 见 我 的 背 ， 却 不 得 见 我 的 面 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2498', '2', '34', '1', '＜ 复 造 法 版 （ 申   1 0 : 1 - 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2499', '2', '34', '2', '明 日 早 晨 ， 你 要 预 备 好 了 ， 上 西 奈 山 ， 在 山 顶 上 站 在 我 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2500', '2', '34', '3', '谁 也 不 可 和 你 一 同 上 去 ， 遍 山 都 不 可 有 人 ， 在 山 根 也 不 可 叫 羊 群 牛 群 吃 草 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2501', '2', '34', '4', '摩 西 就 凿 出 两 块 石 版 ， 和 先 前 的 一 样 。 清 晨 起 来 ， 照 耶 和 华 所 吩 咐 的 上 西 奈 山 去 ， 手 里 拿 着 两 块 石 版 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2502', '2', '34', '5', '耶 和 华 在 云 中 降 临 ， 和 摩 西 一 同 站 在 那 里 ， 宣 告 耶 和 华 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2503', '2', '34', '6', '耶 和 华 在 他 面 前 宣 告 说 ： “ 耶 和 华 ， 耶 和 华 ， 是 有 怜 悯 有 恩 典 的 神 ， 不 轻 易 发 怒 ， 并 有 丰 盛 的 慈 爱 和 诚 实 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2504', '2', '34', '7', '为 千 万 人 存 留 慈 爱 ， 赦 免 罪 孽 、 过 犯 ， 和 罪 恶 ， 万 不 以 有 罪 的 为 无 罪 ， 必 追 讨 他 的 罪 ， 自 父 及 子 ， 直 到 三 、 四 代 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2505', '2', '34', '8', '摩 西 急 忙 伏 地 下 拜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2506', '2', '34', '9', '说 ： “ 主 啊 ， 我 若 在 你 眼 前 蒙 恩 ， 求 你 在 我 们 中 间 同 行 ， 因 为 这 是 硬 着 颈 项 的 百 姓 。 又 求 你 赦 免 我 们 的 罪 孽 和 罪 恶 ， 以 我 们 为 你 的 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2507', '2', '34', '10', '＜ 重 新 立 约 （ 出   2 3 : 1 4 - 1 9 ； 申   7 : 1 - 5 ； 1 6 : 1 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2508', '2', '34', '11', '“ 我 今 天 所 吩 咐 你 的 ， 你 要 谨 守 。 我 要 从 你 面 前 撵 出 亚 摩 利 人 、 迦 南 人 、 赫 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2509', '2', '34', '12', '你 要 谨 慎 ， 不 可 与 你 所 去 那 地 的 居 民 立 约 ， 恐 怕 成 为 你 们 中 间 的 网 罗 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2510', '2', '34', '13', '却 要 拆 毁 他 们 的 祭 坛 ， 打 碎 他 们 的 柱 像 ， 砍 下 他 们 的 木 偶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2511', '2', '34', '14', '不 可 敬 拜 别 神 ； 因 为 耶 和 华 是 忌 邪 的 神 ， 名 为 忌 邪 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2512', '2', '34', '15', '只 怕 你 与 那 地 的 居 民 立 约 ， 百 姓 随 从 他 们 的 神 ， 就 行 邪 淫 ， 祭 祀 他 们 的 神 ， 有 人 叫 你 ， 你 便 吃 他 的 祭 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2513', '2', '34', '16', '又 为 你 的 儿 子 娶 他 们 的 女 儿 为 妻 ， 她 们 的 女 儿 随 从 她 们 的 神 ， 就 行 邪 淫 ， 使 你 的 儿 子 也 随 从 她 们 的 神 行 邪 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2514', '2', '34', '17', '“ 不 可 为 自 己 铸 造 神 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2515', '2', '34', '18', '“ 你 要 守 除 酵 节 ， 照 我 所 吩 咐 你 的 ， 在 亚 笔 月 内 所 定 的 日 期 吃 无 酵 饼 七 天 ， 因 为 你 是 这 亚 笔 月 内 出 了 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2516', '2', '34', '19', '凡 头 生 的 都 是 我 的 ； 一 切 牲 畜 头 生 的 ， 无 论 是 牛 是 羊 ， 公 的 都 是 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2517', '2', '34', '20', '头 生 的 驴 要 用 羊 羔 代 赎 ， 若 不 代 赎 就 要 打 折 它 的 颈 项 。 凡 头 生 的 儿 子 都 要 赎 出 来 。 谁 也 不 可 空 手 朝 见 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2518', '2', '34', '21', '“ 你 六 日 要 做 工 ， 第 七 日 要 安 息 ， 虽 在 耕 种 收 割 的 时 候 也 要 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2519', '2', '34', '22', '在 收 割 初 熟 麦 子 的 时 候 要 守 七 七 节 ； 又 在 年 底 要 守 收 藏 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2520', '2', '34', '23', '你 们 一 切 男 丁 要 一 年 三 次 朝 见 主 耶 和 华 ─ ─ 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2521', '2', '34', '24', '我 要 从 你 面 前 赶 出 外 邦 人 ， 扩 张 你 的 境 界 。 你 一 年 三 次 上 去 朝 见 耶 和 华 ─ ─ 你 神 的 时 候 ， 必 没 有 人 贪 慕 你 的 地 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2522', '2', '34', '25', '“ 你 不 可 将 我 祭 物 的 血 和 有 酵 的 饼 一 同 献 上 。 逾 越 节 的 祭 物 也 不 可 留 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2523', '2', '34', '26', '地 里 首 先 初 熟 之 物 要 送 到 耶 和 华 ─ ─ 你 神 的 殿 。 不 可 用 山 羊 羔 母 的 奶 煮 山 羊 羔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2524', '2', '34', '27', '耶 和 华 吩 咐 摩 西 说 ： “ 你 要 将 这 些 话 写 上 ， 因 为 我 是 按 这 话 与 你 和 以 色 列 人 立 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2525', '2', '34', '28', '摩 西 在 耶 和 华 那 里 四 十 昼 夜 ， 也 不 吃 饭 也 不 喝 水 。 耶 和 华 将 这 约 的 话 ， 就 是 十 条 诫 ， 写 在 两 块 版 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2526', '2', '34', '29', '＜ 摩 西 下 西 奈 山 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2527', '2', '34', '30', '亚 伦 和 以 色 列 众 人 看 见 摩 西 的 面 皮 发 光 就 怕 挨 近 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2528', '2', '34', '31', '摩 西 叫 他 们 来 ； 于 是 亚 伦 和 会 众 的 官 长 都 到 他 那 里 去 ， 摩 西 就 与 他 们 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2529', '2', '34', '32', '随 后 以 色 列 众 人 都 近 前 来 ， 他 就 把 耶 和 华 在 西 奈 山 与 他 所 说 的 一 切 话 都 吩 咐 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2530', '2', '34', '33', '摩 西 与 他 们 说 完 了 话 就 用 帕 子 蒙 上 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2531', '2', '34', '34', '但 摩 西 进 到 耶 和 华 面 前 与 他 说 话 就 揭 去 帕 子 ， 及 至 出 来 的 时 候 便 将 耶 和 华 所 吩 咐 的 告 诉 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2532', '2', '34', '35', '以 色 列 人 看 见 摩 西 的 面 皮 发 光 。 摩 西 又 用 帕 子 蒙 上 脸 ， 等 到 他 进 去 与 耶 和 华 说 话 就 揭 去 帕 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2533', '2', '35', '1', '＜ 安 息 日 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2534', '2', '35', '2', '六 日 要 做 工 ， 第 七 日 乃 为 圣 日 ， 当 向 耶 和 华 守 为 安 息 圣 日 。 凡 这 日 之 内 做 工 的 ， 必 把 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2535', '2', '35', '3', '当 安 息 日 ， 不 可 在 你 们 一 切 的 住 处 生 火 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2536', '2', '35', '4', '＜ 为 会 幕 奉 献 （ 出   2 5 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2537', '2', '35', '5', '你 们 中 间 要 拿 礼 物 献 给 耶 和 华 ， 凡 乐 意 献 的 可 以 拿 耶 和 华 的 礼 物 来 ， 就 是 金 、 银 、 铜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2538', '2', '35', '6', '蓝 色 、 紫 色 、 朱 红 色 线 ， 细 麻 ， 山 羊 毛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2539', '2', '35', '7', '染 红 的 公 羊 皮 ， 海 狗 皮 ， 皂 荚 木 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2540', '2', '35', '8', '点 灯 的 油 ， 并 做 膏 油 和 香 的 香 料 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2541', '2', '35', '9', '红 玛 瑙 与 别 样 的 宝 石 ， 可 以 镶 嵌 在 以 弗 得 和 胸 牌 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2542', '2', '35', '10', '＜ 会 幕 的 器 物 （ 出   3 9 : 3 2 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2543', '2', '35', '11', '就 是 帐 幕 和 帐 幕 的 罩 棚 ， 并 帐 幕 的 盖 、 钩 子 、 板 、 闩 、 柱 子 、 带 卯 的 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2544', '2', '35', '12', '柜 和 柜 的 杠 ， 施 恩 座 和 遮 掩 柜 的 幔 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2545', '2', '35', '13', '桌 子 和 桌 子 的 杠 与 桌 子 的 一 切 器 具 ， 并 陈 设 饼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2546', '2', '35', '14', '灯 台 和 灯 台 的 器 具 ， 灯 盏 并 点 灯 的 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2547', '2', '35', '15', '香 坛 和 坛 的 杠 ， 膏 油 和 馨 香 的 香 料 ， 并 帐 幕 门 口 的 帘 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2548', '2', '35', '16', '燔 祭 坛 和 坛 的 铜 网 ， 坛 的 杠 并 坛 的 一 切 器 具 ， 洗 濯 盆 和 盆 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2549', '2', '35', '17', '院 子 的 帷 子 和 帷 子 的 柱 子 ， 带 卯 的 座 和 院 子 的 门 帘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2550', '2', '35', '18', '帐 幕 的 橛 子 并 院 子 的 橛 子 ， 和 这 两 处 的 绳 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2551', '2', '35', '19', '精 工 做 的 礼 服 和 祭 司 亚 伦 并 他 儿 子 在 圣 所 用 以 供 祭 司 职 分 的 圣 衣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2552', '2', '35', '20', '＜ 百 姓 奉 献 礼 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2553', '2', '35', '21', '凡 心 里 受 感 和 甘 心 乐 意 的 都 拿 耶 和 华 的 礼 物 来 ， 用 以 做 会 幕 和 其 中 一 切 的 使 用 ， 又 用 以 做 圣 衣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2554', '2', '35', '22', '凡 心 里 乐 意 献 礼 物 的 ， 连 男 带 女 ， 各 将 金 器 ， 就 是 胸 前 针 、 耳 环 ｛ 或 译 ： 鼻 环 ｝ 、 打 印 的 戒 指 ， 和 手 钏 带 来 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2555', '2', '35', '23', '凡 有 蓝 色 、 紫 色 、 朱 红 色 线 ， 细 麻 ， 山 羊 毛 ， 染 红 的 公 羊 皮 ， 海 狗 皮 的 ， 都 拿 了 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2556', '2', '35', '24', '凡 献 银 子 和 铜 给 耶 和 华 为 礼 物 的 都 拿 了 来 ； 凡 有 皂 荚 木 可 做 什 么 使 用 的 也 拿 了 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2557', '2', '35', '25', '凡 心 中 有 智 慧 的 妇 女 亲 手 纺 线 ， 把 所 纺 的 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 细 麻 都 拿 了 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2558', '2', '35', '26', '凡 有 智 慧 、 心 里 受 感 的 妇 女 就 纺 山 羊 毛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2559', '2', '35', '27', '众 官 长 把 红 玛 瑙 和 别 样 的 宝 石 ， 可 以 镶 嵌 在 以 弗 得 与 胸 牌 上 的 ， 都 拿 了 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2560', '2', '35', '28', '又 拿 香 料 做 香 ， 拿 油 点 灯 ， 做 膏 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2561', '2', '35', '29', '以 色 列 人 ， 无 论 男 女 ， 凡 甘 心 乐 意 献 礼 物 给 耶 和 华 的 ， 都 将 礼 物 拿 来 ， 做 耶 和 华 藉 摩 西 所 吩 咐 的 一 切 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2562', '2', '35', '30', '＜ 造 会 幕 的 技 工 （ 出   3 1 : 1 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2563', '2', '35', '31', '又 以 神 的 灵 充 满 了 他 ， 使 他 有 智 慧 、 聪 明 、 知 识 ， 能 做 各 样 的 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2564', '2', '35', '32', '能 想 出 巧 工 ， 用 金 、 银 、 铜 制 造 各 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2565', '2', '35', '33', '又 能 刻 宝 石 ， 可 以 镶 嵌 ， 能 雕 刻 木 头 ， 能 做 各 样 的 巧 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2566', '2', '35', '34', '耶 和 华 又 使 他 ， 和 但 支 派 中 亚 希 撒 抹 的 儿 子 亚 何 利 亚 伯 ， 心 里 灵 明 ， 能 教 导 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2567', '2', '35', '35', '耶 和 华 使 他 们 的 心 满 有 智 慧 ， 能 做 各 样 的 工 ， 无 论 是 雕 刻 的 工 ， 巧 匠 的 工 ， 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 细 麻 、 绣 花 的 工 ， 并 机 匠 的 工 ， 他 们 都 能 做 ， 也 能 想 出 奇 巧 的 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2568', '2', '36', '1', '“ 比 撒 列 和 亚 何 利 亚 伯 ， 并 一 切 心 里 有 智 慧 的 ， 就 是 蒙 耶 和 华 赐 智 慧 聪 明 、 叫 他 知 道 做 圣 所 各 样 使 用 之 工 的 ， 都 要 照 耶 和 华 所 吩 咐 的 做 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2569', '2', '36', '2', '＜ 百 姓 奉 献 礼 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2570', '2', '36', '3', '这 些 人 就 从 摩 西 收 了 以 色 列 人 为 做 圣 所 并 圣 所 使 用 之 工 所 拿 来 的 礼 物 。 百 姓 每 早 晨 还 把 甘 心 献 的 礼 物 拿 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2571', '2', '36', '4', '凡 做 圣 所 一 切 工 的 智 慧 人 各 都 离 开 他 所 做 的 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2572', '2', '36', '5', '来 对 摩 西 说 ： “ 百 姓 为 耶 和 华 吩 咐 使 用 之 工 所 拿 来 的 ， 富 富 有 余 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2573', '2', '36', '6', '摩 西 传 命 ， 他 们 就 在 全 营 中 宣 告 说 ： “ 无 论 男 女 ， 不 必 再 为 圣 所 拿 什 么 礼 物 来 。 ” 这 样 才 拦 住 百 姓 不 再 拿 礼 物 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2574', '2', '36', '7', '因 为 他 们 所 有 的 材 料 够 做 一 切 当 做 的 物 ， 而 且 有 余 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2575', '2', '36', '8', '＜ 造 耶 和 华 的 会 幕 （ 出   2 6 : 1 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2576', '2', '36', '9', '每 幅 幔 子 长 二 十 八 肘 ， 宽 四 肘 ， 都 是 一 样 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2577', '2', '36', '10', '他 使 这 五 幅 幔 子 幅 幅 相 连 ， 又 使 那 五 幅 幔 子 幅 幅 相 连 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2578', '2', '36', '11', '在 这 相 连 的 幔 子 末 幅 边 上 做 蓝 色 的 钮 扣 ， 在 那 相 连 的 幔 子 末 幅 边 上 也 照 样 做 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2579', '2', '36', '12', '在 这 相 连 的 幔 子 上 做 五 十 个 钮 扣 ， 在 那 相 连 的 幔 子 上 也 做 五 十 个 钮 扣 ， 都 是 两 两 相 对 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2580', '2', '36', '13', '又 做 五 十 个 金 钩 ， 使 幔 子 相 连 。 这 才 成 了 一 个 帐 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2581', '2', '36', '14', '他 用 山 羊 毛 织 十 一 幅 幔 子 ， 作 为 帐 幕 以 上 的 罩 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2582', '2', '36', '15', '每 幅 幔 子 长 三 十 肘 ， 宽 四 肘 ； 十 一 幅 幔 子 都 是 一 样 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2583', '2', '36', '16', '他 把 五 幅 幔 子 连 成 一 幅 ， 又 把 六 幅 幔 子 连 成 一 幅 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2584', '2', '36', '17', '在 这 相 连 的 幔 子 末 幅 边 上 做 五 十 个 钮 扣 ， 在 那 相 连 的 幔 子 末 幅 边 上 也 做 五 十 个 钮 扣 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2585', '2', '36', '18', '又 做 五 十 个 铜 钩 ， 使 罩 棚 连 成 一 个 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2586', '2', '36', '19', '并 用 染 红 的 公 羊 皮 做 罩 棚 的 盖 ， 再 用 海 狗 皮 做 一 层 罩 棚 上 的 顶 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2587', '2', '36', '20', '他 用 皂 荚 木 做 帐 幕 的 竖 板 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2588', '2', '36', '21', '每 块 长 十 肘 ， 宽 一 肘 半 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2589', '2', '36', '22', '每 块 有 两 榫 相 对 。 帐 幕 一 切 的 板 都 是 这 样 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2590', '2', '36', '23', '帐 幕 的 南 面 做 板 二 十 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2591', '2', '36', '24', '在 这 二 十 块 板 底 下 又 做 四 十 个 带 卯 的 银 座 ： 两 卯 接 这 块 板 上 的 两 榫 ， 两 卯 接 那 块 板 上 的 两 榫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2592', '2', '36', '25', '帐 幕 的 第 二 面 ， 就 是 北 面 ， 也 做 板 二 十 块');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2593', '2', '36', '26', '和 带 卯 的 银 座 四 十 个 ： 这 板 底 下 有 两 卯 ， 那 板 底 下 也 有 两 卯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2594', '2', '36', '27', '帐 幕 的 后 面 ， 就 是 西 面 ， 做 板 六 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2595', '2', '36', '28', '帐 幕 后 面 的 拐 角 做 板 两 块 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2596', '2', '36', '29', '板 的 下 半 截 是 双 的 ， 上 半 截 是 整 的 ， 直 到 第 一 个 环 子 ； 在 帐 幕 的 两 个 拐 角 上 都 是 这 样 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2597', '2', '36', '30', '有 八 块 板 和 十 六 个 带 卯 的 银 座 ， 每 块 板 底 下 有 两 卯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2598', '2', '36', '31', '他 用 皂 荚 木 做 闩 ： 为 帐 幕 这 面 的 板 做 五 闩 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2599', '2', '36', '32', '为 帐 幕 那 面 的 板 做 五 闩 ， 又 为 帐 幕 后 面 的 板 做 五 闩 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2600', '2', '36', '33', '使 板 腰 间 的 中 闩 从 这 一 头 通 到 那 一 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2601', '2', '36', '34', '用 金 子 将 板 包 裹 ， 又 做 板 上 的 金 环 套 闩 ； 闩 也 用 金 子 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2602', '2', '36', '35', '他 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 捻 的 细 麻 织 幔 子 ， 以 巧 匠 的 手 工 绣 上 基 路 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2603', '2', '36', '36', '为 幔 子 做 四 根 皂 荚 木 柱 子 ， 用 金 包 裹 ， 柱 子 上 有 金 钩 ， 又 为 柱 子 铸 了 四 个 带 卯 的 银 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2604', '2', '36', '37', '拿 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 捻 的 细 麻 ， 用 绣 花 的 手 工 织 帐 幕 的 门 帘 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2605', '2', '36', '38', '又 为 帘 子 做 五 根 柱 子 和 柱 子 上 的 钩 子 ， 用 金 子 把 柱 顶 和 柱 子 上 的 杆 子 包 裹 。 柱 子 有 五 个 带 卯 的 座 ， 是 铜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2606', '2', '37', '1', '＜ 造 约 柜 （ 出   2 5 : 1 0 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2607', '2', '37', '2', '里 外 包 上 精 金 ， 四 围 镶 上 金 牙 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2608', '2', '37', '3', '又 铸 四 个 金 环 ， 安 在 柜 的 四 脚 上 ： 这 边 两 环 ， 那 边 两 环 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2609', '2', '37', '4', '用 皂 荚 木 做 两 根 杠 ， 用 金 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2610', '2', '37', '5', '把 杠 穿 在 柜 旁 的 环 内 ， 以 便 抬 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2611', '2', '37', '6', '用 精 金 做 施 恩 座 ， 长 二 肘 半 ， 宽 一 肘 半 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2612', '2', '37', '7', '用 金 子 锤 出 两 个 基 路 伯 来 ， 安 在 施 恩 座 的 两 头 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2613', '2', '37', '8', '这 头 做 一 个 基 路 伯 ， 那 头 做 一 个 基 路 伯 ， 二 基 路 伯 接 连 一 块 ， 在 施 恩 座 的 两 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2614', '2', '37', '9', '二 基 路 伯 高 张 翅 膀 ， 遮 掩 施 恩 座 ； 基 路 伯 是 脸 对 脸 ， 朝 着 施 恩 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2615', '2', '37', '10', '＜ 造 陈 设 饼 的 桌 子 （ 出   2 5 : 2 3 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2616', '2', '37', '11', '又 包 上 精 金 ， 四 围 镶 上 金 牙 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2617', '2', '37', '12', '桌 子 的 四 围 各 做 一 掌 宽 的 横 梁 ， 横 梁 上 镶 着 金 牙 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2618', '2', '37', '13', '又 铸 了 四 个 金 环 ， 安 在 桌 子 四 脚 的 四 角 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2619', '2', '37', '14', '安 环 子 的 地 方 是 挨 近 横 梁 ， 可 以 穿 杠 抬 桌 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2620', '2', '37', '15', '他 用 皂 荚 木 做 两 根 杠 ， 用 金 包 裹 ， 以 便 抬 桌 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2621', '2', '37', '16', '又 用 精 金 做 桌 子 上 的 器 皿 ， 就 是 盘 子 、 调 羹 ， 并 奠 酒 的 瓶 和 爵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2622', '2', '37', '17', '＜ 造 灯 台 （ 出   2 5 : 3 1 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2623', '2', '37', '18', '灯 台 两 旁 杈 出 六 个 枝 子 ： 这 旁 三 个 ， 那 旁 三 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2624', '2', '37', '19', '这 旁 每 枝 上 有 三 个 杯 ， 形 状 像 杏 花 ， 有 球 有 花 ； 那 旁 每 枝 上 也 有 三 个 杯 ， 形 状 像 杏 花 ， 有 球 有 花 。 从 灯 台 杈 出 来 的 六 个 枝 子 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2625', '2', '37', '20', '灯 台 上 有 四 个 杯 ， 形 状 像 杏 花 ， 有 球 有 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2626', '2', '37', '21', '灯 台 每 两 个 枝 子 以 下 有 球 ， 与 枝 子 接 连 一 块 ； 灯 台 杈 出 的 六 个 枝 子 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2627', '2', '37', '22', '球 和 枝 子 是 接 连 一 块 ， 都 是 一 块 精 金 锤 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2628', '2', '37', '23', '用 精 金 做 灯 台 的 七 个 灯 盏 ， 并 灯 台 的 蜡 剪 和 蜡 花 盘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2629', '2', '37', '24', '他 用 精 金 一 他 连 得 做 灯 台 和 灯 台 的 一 切 器 具 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2630', '2', '37', '25', '＜ 造 香 坛 （ 出   3 0 : 1 - 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2631', '2', '37', '26', '又 用 精 金 把 坛 的 上 面 与 坛 的 四 面 并 坛 的 四 角 包 裹 ， 又 在 坛 的 四 围 镶 上 金 牙 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2632', '2', '37', '27', '做 两 个 金 环 ， 安 在 牙 子 边 以 下 ， 在 坛 的 两 旁 、 两 根 横 撑 上 ， 作 为 穿 杠 的 用 处 ， 以 便 抬 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2633', '2', '37', '28', '用 皂 荚 木 做 杠 ， 用 金 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2634', '2', '37', '29', '＜ 造 圣 油 和 圣 膏 （ 出   3 0 : 2 2 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2635', '2', '38', '1', '＜ 造 燔 祭 坛 （ 出   2 7 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2636', '2', '38', '2', '在 坛 的 四 拐 角 上 做 四 个 角 ， 与 坛 接 连 一 块 ， 用 铜 把 坛 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2637', '2', '38', '3', '他 做 坛 上 的 盆 、 铲 子 、 盘 子 、 肉 锸 子 、 火 鼎 ； 这 一 切 器 具 都 是 用 铜 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2638', '2', '38', '4', '又 为 坛 做 一 个 铜 网 ， 安 在 坛 四 面 的 围 腰 板 以 下 ， 从 下 达 到 坛 的 半 腰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2639', '2', '38', '5', '为 铜 网 的 四 角 铸 四 个 环 子 ， 作 为 穿 杠 的 用 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2640', '2', '38', '6', '用 皂 荚 木 做 杠 ， 用 铜 包 裹 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2641', '2', '38', '7', '把 杠 穿 在 坛 两 旁 的 环 子 内 ， 用 以 抬 坛 ， 并 用 板 做 坛 ； 坛 是 空 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2642', '2', '38', '8', '＜ 造 铜 盆 （ 出   3 0 : 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2643', '2', '38', '9', '＜ 耶 和 华 会 幕 的 周 围 （ 出   2 7 : 9 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2644', '2', '38', '10', '帷 子 的 柱 子 二 十 根 ， 带 卯 的 铜 座 二 十 个 ； 柱 子 上 的 钩 子 和 杆 子 都 是 用 银 子 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2645', '2', '38', '11', '北 面 也 有 帷 子 ， 宽 一 百 肘 。 帷 子 的 柱 子 二 十 根 ， 带 卯 的 铜 座 二 十 个 ； 柱 子 上 的 钩 子 和 杆 子 都 是 用 银 子 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2646', '2', '38', '12', '院 子 的 西 面 有 帷 子 ， 宽 五 十 肘 。 帷 子 的 柱 子 十 根 ， 带 卯 的 座 十 个 ； 柱 子 的 钩 子 和 杆 子 都 是 用 银 子 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2647', '2', '38', '13', '院 子 的 东 面 ， 宽 五 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2648', '2', '38', '14', '门 这 边 的 帷 子 十 五 肘 ， 那 边 也 是 一 样 。 帷 子 的 柱 子 三 根 ， 带 卯 的 座 三 个 。 在 门 的 左 右 各 有 帷 子 十 五 肘 ， 帷 子 的 柱 子 三 根 ， 带 卯 的 座 三 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2649', '2', '38', '15', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2650', '2', '38', '16', '院 子 四 面 的 帷 子 都 是 用 捻 的 细 麻 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2651', '2', '38', '17', '柱 子 带 卯 的 座 是 铜 的 ， 柱 子 上 的 钩 子 和 杆 子 是 银 的 ， 柱 顶 是 用 银 子 包 的 。 院 子 一 切 的 柱 子 都 是 用 银 杆 连 络 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2652', '2', '38', '18', '院 子 的 门 帘 是 以 绣 花 的 手 工 ， 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 捻 的 细 麻 织 的 ， 宽 二 十 肘 ， 高 五 肘 ， 与 院 子 的 帷 子 相 配 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2653', '2', '38', '19', '帷 子 的 柱 子 四 根 ， 带 卯 的 铜 座 四 个 ； 柱 子 上 的 钩 子 和 杆 子 是 银 的 ； 柱 顶 是 用 银 子 包 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2654', '2', '38', '20', '帐 幕 一 切 的 橛 子 和 院 子 四 围 的 橛 子 都 是 铜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2655', '2', '38', '21', '＜ 耶 和 华 会 幕 所 用 的 金 属 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2656', '2', '38', '22', '凡 耶 和 华 所 吩 咐 摩 西 的 都 是 犹 大 支 派 户 珥 的 孙 子 、 乌 利 的 儿 子 比 撒 列 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2657', '2', '38', '23', '与 他 同 工 的 有 但 支 派 中 亚 希 撒 抹 的 儿 子 亚 何 利 亚 伯 ； 他 是 雕 刻 匠 ， 又 是 巧 匠 ， 又 能 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 和 细 麻 绣 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2658', '2', '38', '24', '为 圣 所 一 切 工 作 使 用 所 献 的 金 子 ， 按 圣 所 的 平 ， 有 二 十 九 他 连 得 并 七 百 三 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2659', '2', '38', '25', '会 中 被 数 的 人 所 出 的 银 子 ， 按 圣 所 的 平 ， 有 一 百 他 连 得 并 一 千 七 百 七 十 五 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2660', '2', '38', '26', '凡 过 去 归 那 些 被 数 之 人 的 ， 从 二 十 岁 以 外 ， 有 六 十 万 零 三 千 五 百 五 十 人 。 按 圣 所 的 平 ， 每 人 出 银 半 舍 客 勒 ， 就 是 一 比 加 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2661', '2', '38', '27', '用 那 一 百 他 连 得 银 子 铸 造 圣 所 带 卯 的 座 和 幔 子 柱 子 带 卯 的 座 ； 一 百 他 连 得 共 一 百 带 卯 的 座 ， 每 带 卯 的 座 用 一 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2662', '2', '38', '28', '用 那 一 千 七 百 七 十 五 舍 客 勒 银 子 做 柱 子 上 的 钩 子 ， 包 裹 柱 顶 并 柱 子 上 的 杆 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2663', '2', '38', '29', '所 献 的 铜 有 七 十 他 连 得 并 二 千 四 百 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2664', '2', '38', '30', '用 这 铜 做 会 幕 门 带 卯 的 座 和 铜 坛 ， 并 坛 上 的 铜 网 和 坛 的 一 切 器 具 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2665', '2', '38', '31', '并 院 子 四 围 带 卯 的 座 和 院 门 带 卯 的 座 ， 与 帐 幕 一 切 的 橛 子 和 院 子 四 围 所 有 的 橛 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2666', '2', '39', '1', '＜ 为 祭 司 制 圣 服 （ 出   2 8 : 1 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2667', '2', '39', '2', '他 用 金 线 和 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 捻 的 细 麻 做 以 弗 得 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2668', '2', '39', '3', '把 金 子 锤 成 薄 片 ， 剪 出 线 来 ， 与 蓝 色 、 紫 色 、 朱 红 色 线 ， 用 巧 匠 的 手 工 一 同 绣 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2669', '2', '39', '4', '又 为 以 弗 得 做 两 条 相 连 的 肩 带 ， 接 连 在 以 弗 得 的 两 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2670', '2', '39', '5', '其 上 巧 工 织 的 带 子 和 以 弗 得 一 样 的 做 法 ， 用 以 束 上 ， 与 以 弗 得 接 连 一 块 ， 是 用 金 线 和 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 捻 的 细 麻 做 的 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2671', '2', '39', '6', '又 琢 出 两 块 红 玛 瑙 ， 镶 在 金 槽 上 ， 仿 佛 刻 图 书 ， 按 着 以 色 列 儿 子 的 名 字 雕 刻 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2672', '2', '39', '7', '将 这 两 块 宝 石 安 在 以 弗 得 的 两 条 肩 带 上 ， 为 以 色 列 人 做 纪 念 石 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2673', '2', '39', '8', '＜ 制 胸 牌 （ 出   2 8 : 1 5 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2674', '2', '39', '9', '胸 牌 是 四 方 的 ， 叠 为 两 层 ； 这 两 层 长 一 虎 口 ， 宽 一 虎 口 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2675', '2', '39', '10', '上 面 镶 着 宝 石 四 行 ： 第 一 行 是 红 宝 石 、 红 璧 玺 、 红 玉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2676', '2', '39', '11', '第 二 行 是 绿 宝 石 、 蓝 宝 石 、 金 钢 石 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2677', '2', '39', '12', '第 三 行 是 紫 玛 瑙 、 白 玛 瑙 、 紫 晶 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2678', '2', '39', '13', '第 四 行 是 水 苍 玉 、 红 玛 瑙 、 碧 玉 。 这 都 镶 在 金 槽 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2679', '2', '39', '14', '这 些 宝 石 都 是 按 着 以 色 列 十 二 个 儿 子 的 名 字 ， 仿 佛 刻 图 书 ， 刻 十 二 个 支 派 的 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2680', '2', '39', '15', '在 胸 牌 上 ， 用 精 金 拧 成 如 绳 子 的 链 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2681', '2', '39', '16', '又 做 两 个 金 槽 和 两 个 金 环 ， 安 在 胸 牌 的 两 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2682', '2', '39', '17', '把 那 两 条 拧 成 的 金 链 子 穿 过 胸 牌 两 头 的 环 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2683', '2', '39', '18', '又 把 链 子 的 那 两 头 接 在 两 槽 上 ， 安 在 以 弗 得 前 面 肩 带 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2684', '2', '39', '19', '做 两 个 金 环 ， 安 在 胸 牌 的 两 头 ， 在 以 弗 得 里 面 的 边 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2685', '2', '39', '20', '又 做 两 个 金 环 ， 安 在 以 弗 得 前 面 两 条 肩 带 的 下 边 ， 挨 近 相 接 之 处 ， 在 以 弗 得 巧 工 织 的 带 子 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2686', '2', '39', '21', '用 一 条 蓝 细 带 子 把 胸 牌 的 环 子 和 以 弗 得 的 环 子 系 住 ， 使 胸 牌 贴 在 以 弗 得 巧 工 织 的 带 子 上 ， 不 可 与 以 弗 得 离 缝 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2687', '2', '39', '22', '＜ 祭 司 其 他 的 圣 服 （ 出   2 8 : 3 1 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2688', '2', '39', '23', '袍 上 留 一 领 口 ， 口 的 周 围 织 出 领 边 来 ， 仿 佛 铠 甲 的 领 口 ， 免 得 破 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2689', '2', '39', '24', '在 袍 子 底 边 上 ， 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 捻 的 细 麻 做 石 榴 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2690', '2', '39', '25', '又 用 精 金 做 铃 铛 ， 把 铃 铛 钉 在 袍 子 周 围 底 边 上 的 石 榴 中 间 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2691', '2', '39', '26', '一 个 铃 铛 一 个 石 榴 ， 一 个 铃 铛 一 个 石 榴 ， 在 袍 子 周 围 底 边 上 用 以 供 职 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2692', '2', '39', '27', '他 用 织 成 的 细 麻 布 为 亚 伦 和 他 的 儿 子 做 内 袍 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2693', '2', '39', '28', '并 用 细 麻 布 做 冠 冕 和 华 美 的 裹 头 巾 ， 用 捻 的 细 麻 布 做 裤 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2694', '2', '39', '29', '又 用 蓝 色 、 紫 色 、 朱 红 色 线 ， 并 捻 的 细 麻 ， 以 绣 花 的 手 工 做 腰 带 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2695', '2', '39', '30', '他 用 精 金 做 圣 冠 上 的 牌 ， 在 上 面 按 刻 图 书 之 法 ， 刻 着 “ 归 耶 和 华 为 圣 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2696', '2', '39', '31', '又 用 一 条 蓝 细 带 子 将 牌 系 在 冠 冕 上 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2697', '2', '39', '32', '＜ 会 幕 完 工 （ 出   3 5 : 1 0 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2698', '2', '39', '33', '他 们 送 到 摩 西 那 里 。 帐 幕 和 帐 幕 的 一 切 器 具 ， 就 是 钩 子 、 板 、 闩 、 柱 子 、 带 卯 的 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2699', '2', '39', '34', '染 红 公 羊 皮 的 盖 、 海 狗 皮 的 顶 盖 ， 和 遮 掩 柜 的 幔 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2700', '2', '39', '35', '法 柜 和 柜 的 杠 并 施 恩 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2701', '2', '39', '36', '桌 子 和 桌 子 的 一 切 器 具 并 陈 设 饼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2702', '2', '39', '37', '精 金 的 灯 台 和 摆 列 的 灯 盏 ， 与 灯 台 的 一 切 器 具 ， 并 点 灯 的 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2703', '2', '39', '38', '金 坛 、 膏 油 、 馨 香 的 香 料 、 会 幕 的 门 帘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2704', '2', '39', '39', '铜 坛 和 坛 上 的 铜 网 ， 坛 的 杠 并 坛 的 一 切 器 具 ， 洗 濯 盆 和 盆 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2705', '2', '39', '40', '院 子 的 帷 子 和 柱 子 ， 并 带 卯 的 座 ， 院 子 的 门 帘 、 绳 子 、 橛 子 ， 并 帐 幕 和 会 幕 中 一 切 使 用 的 器 具 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2706', '2', '39', '41', '精 工 做 的 礼 服 ， 和 祭 司 亚 伦 并 他 儿 子 在 圣 所 用 以 供 祭 司 职 分 的 圣 衣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2707', '2', '39', '42', '这 一 切 工 作 都 是 以 色 列 人 照 耶 和 华 所 吩 咐 摩 西 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2708', '2', '39', '43', '耶 和 华 怎 样 吩 咐 的 ， 他 们 就 怎 样 做 了 。 摩 西 看 见 一 切 的 工 都 做 成 了 ， 就 给 他 们 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2709', '2', '40', '1', '＜ 耶 和 华 会 幕 的 建 立 和 奉 献 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2710', '2', '40', '2', '“ 正 月 初 一 日 ， 你 要 立 起 帐 幕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2711', '2', '40', '3', '把 法 柜 安 放 在 里 面 ， 用 幔 子 将 柜 遮 掩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2712', '2', '40', '4', '把 桌 子 搬 进 去 ， 摆 设 上 面 的 物 。 把 灯 台 搬 进 去 ， 点 其 上 的 灯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2713', '2', '40', '5', '把 烧 香 的 金 坛 安 在 法 柜 前 ， 挂 上 帐 幕 的 门 帘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2714', '2', '40', '6', '把 燔 祭 坛 安 在 帐 幕 门 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2715', '2', '40', '7', '把 洗 濯 盆 安 在 会 幕 和 坛 的 中 间 ， 在 盆 里 盛 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2716', '2', '40', '8', '又 在 四 围 立 院 帷 ， 把 院 子 的 门 帘 挂 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2717', '2', '40', '9', '用 膏 油 把 帐 幕 和 其 中 所 有 的 都 抹 上 ， 使 帐 幕 和 一 切 器 具 成 圣 ， 就 都 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2718', '2', '40', '10', '又 要 抹 燔 祭 坛 和 一 切 器 具 ， 使 坛 成 圣 ， 就 都 成 为 至 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2719', '2', '40', '11', '要 抹 洗 濯 盆 和 盆 座 ， 使 盆 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2720', '2', '40', '12', '要 使 亚 伦 和 他 儿 子 到 会 幕 门 口 来 ， 用 水 洗 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2721', '2', '40', '13', '要 给 亚 伦 穿 上 圣 衣 ， 又 膏 他 ， 使 他 成 圣 ， 可 以 给 我 供 祭 司 的 职 分 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2722', '2', '40', '14', '又 要 使 他 儿 子 来 ， 给 他 们 穿 上 内 袍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2723', '2', '40', '15', '怎 样 膏 他 们 的 父 亲 ， 也 要 照 样 膏 他 们 ， 使 他 们 给 我 供 祭 司 的 职 分 。 他 们 世 世 代 代 凡 受 膏 的 ， 就 永 远 当 祭 司 的 职 任 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2724', '2', '40', '16', '摩 西 这 样 行 ， 都 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2725', '2', '40', '17', '第 二 年 正 月 初 一 日 ， 帐 幕 就 立 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2726', '2', '40', '18', '摩 西 立 起 帐 幕 ， 安 上 带 卯 的 座 ， 立 上 板 ， 穿 上 闩 ， 立 起 柱 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2727', '2', '40', '19', '在 帐 幕 以 上 搭 罩 棚 ， 把 罩 棚 的 顶 盖 盖 在 其 上 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2728', '2', '40', '20', '又 把 法 版 放 在 柜 里 ， 把 杠 穿 在 柜 的 两 旁 ， 把 施 恩 座 安 在 柜 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2729', '2', '40', '21', '把 柜 抬 进 帐 幕 ， 挂 上 遮 掩 柜 的 幔 子 ， 把 法 柜 遮 掩 了 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2730', '2', '40', '22', '又 把 桌 子 安 在 会 幕 内 ， 在 帐 幕 北 边 ， 在 幔 子 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2731', '2', '40', '23', '在 桌 子 上 将 饼 陈 设 在 耶 和 华 面 前 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2732', '2', '40', '24', '又 把 灯 台 安 在 会 幕 内 ， 在 帐 幕 南 边 ， 与 桌 子 相 对 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2733', '2', '40', '25', '在 耶 和 华 面 前 点 灯 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2734', '2', '40', '26', '把 金 坛 安 在 会 幕 内 的 幔 子 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2735', '2', '40', '27', '在 坛 上 烧 了 馨 香 料 做 的 香 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2736', '2', '40', '28', '又 挂 上 帐 幕 的 门 帘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2737', '2', '40', '29', '在 会 幕 的 帐 幕 门 前 ， 安 设 燔 祭 坛 ， 把 燔 祭 和 素 祭 献 在 其 上 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2738', '2', '40', '30', '把 洗 濯 盆 安 在 会 幕 和 坛 的 中 间 ， 盆 中 盛 水 ， 以 便 洗 濯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2739', '2', '40', '31', '摩 西 和 亚 伦 并 亚 伦 的 儿 子 在 这 盆 里 洗 手 洗 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2740', '2', '40', '32', '他 们 进 会 幕 或 就 近 坛 的 时 候 ， 便 都 洗 濯 ， 是 照 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2741', '2', '40', '33', '在 帐 幕 和 坛 的 四 围 立 了 院 帷 ， 把 院 子 的 门 帘 挂 上 。 这 样 ， 摩 西 就 完 了 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2742', '2', '40', '34', '＜ 云 彩 覆 盖 会 幕 （ 民   9 : 1 5 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2743', '2', '40', '35', '摩 西 不 能 进 会 幕 ； 因 为 云 彩 停 在 其 上 ， 并 且 耶 和 华 的 荣 光 充 满 了 帐 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2744', '2', '40', '36', '每 逢 云 彩 从 帐 幕 收 上 去 ， 以 色 列 人 就 起 程 前 往 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2745', '2', '40', '37', '云 彩 若 不 收 上 去 ， 他 们 就 不 起 程 ， 直 等 到 云 彩 收 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2746', '2', '40', '38', '日 间 ， 耶 和 华 的 云 彩 是 在 帐 幕 以 上 ； 夜 间 ， 云 中 有 火 ， 在 以 色 列 全 家 的 眼 前 。 在 他 们 所 行 的 路 上 都 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2747', '3', '1', '1', '＜ 燔 祭 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2748', '3', '1', '2', '“ 你 晓 谕 以 色 列 人 说 ： 你 们 中 间 若 有 人 献 供 物 给 耶 和 华 ， 要 从 牛 群 羊 群 中 献 牲 畜 为 供 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2749', '3', '1', '3', '“ 他 的 供 物 若 以 牛 为 燔 祭 ， 就 要 在 会 幕 门 口 献 一 只 没 有 残 疾 的 公 牛 ， 可 以 在 耶 和 华 面 前 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2750', '3', '1', '4', '他 要 按 手 在 燔 祭 牲 的 头 上 ， 燔 祭 便 蒙 悦 纳 ， 为 他 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2751', '3', '1', '5', '他 要 在 耶 和 华 面 前 宰 公 牛 ； 亚 伦 子 孙 作 祭 司 的 ， 要 奉 上 血 ， 把 血 洒 在 会 幕 门 口 、 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2752', '3', '1', '6', '那 人 要 剥 去 燔 祭 牲 的 皮 ， 把 燔 祭 牲 切 成 块 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2753', '3', '1', '7', '祭 司 亚 伦 的 子 孙 要 把 火 放 在 坛 上 ， 把 柴 摆 在 火 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2754', '3', '1', '8', '亚 伦 子 孙 作 祭 司 的 ， 要 把 肉 块 和 头 并 脂 油 摆 在 坛 上 火 的 柴 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2755', '3', '1', '9', '但 燔 祭 的 脏 腑 与 腿 要 用 水 洗 。 祭 司 就 要 把 一 切 全 烧 在 坛 上 ， 当 作 燔 祭 ， 献 与 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2756', '3', '1', '10', '“ 人 的 供 物 若 以 绵 羊 或 山 羊 为 燔 祭 ， 就 要 献 上 没 有 残 疾 的 公 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2757', '3', '1', '11', '要 把 羊 宰 于 坛 的 北 边 ， 在 耶 和 华 面 前 ； 亚 伦 子 孙 作 祭 司 的 ， 要 把 羊 血 洒 在 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2758', '3', '1', '12', '要 把 燔 祭 牲 切 成 块 子 ， 连 头 和 脂 油 ， 祭 司 就 要 摆 在 坛 上 火 的 柴 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2759', '3', '1', '13', '但 脏 腑 与 腿 要 用 水 洗 ， 祭 司 就 要 全 然 奉 献 ， 烧 在 坛 上 。 这 是 燔 祭 ， 是 献 与 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2760', '3', '1', '14', '“ 人 奉 给 耶 和 华 的 供 物 ， 若 以 鸟 为 燔 祭 ， 就 要 献 斑 鸠 或 是 雏 鸽 为 供 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2761', '3', '1', '15', '祭 司 要 把 鸟 拿 到 坛 前 ， 揪 下 头 来 ， 把 鸟 烧 在 坛 上 ； 鸟 的 血 要 流 在 坛 的 旁 边 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2762', '3', '1', '16', '又 要 把 鸟 的 嗉 子 和 脏 物 ｛ 脏 物 ： 或 译 翎 毛 ｝ 除 掉 ， 丢 在 坛 的 东 边 倒 灰 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2763', '3', '1', '17', '要 拿 着 鸟 的 两 个 翅 膀 ， 把 鸟 撕 开 ， 只 是 不 可 撕 断 ； 祭 司 要 在 坛 上 、 在 火 的 柴 上 焚 烧 。 这 是 燔 祭 ， 是 献 与 耶 和 华 为 馨 香 的 火 祭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2764', '3', '2', '1', '＜ 素 祭 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2765', '3', '2', '2', '带 到 亚 伦 子 孙 作 祭 司 的 那 里 ； 祭 司 就 要 从 细 面 中 取 出 一 把 来 ， 并 取 些 油 和 所 有 的 乳 香 ， 然 后 要 把 所 取 的 这 些 作 为 纪 念 ， 烧 在 坛 上 ， 是 献 与 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2766', '3', '2', '3', '素 祭 所 剩 的 要 归 给 亚 伦 和 他 的 子 孙 ； 这 是 献 与 耶 和 华 的 火 祭 中 为 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2767', '3', '2', '4', '“ 若 用 炉 中 烤 的 物 为 素 祭 ， 就 要 用 调 油 的 无 酵 细 面 饼 ， 或 是 抹 油 的 无 酵 薄 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2768', '3', '2', '5', '若 用 铁 鏊 上 做 的 物 为 素 祭 ， 就 要 用 调 油 的 无 酵 细 面 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2769', '3', '2', '6', '分 成 块 子 ， 浇 上 油 ； 这 是 素 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2770', '3', '2', '7', '若 用 煎 盘 做 的 物 为 素 祭 ， 就 要 用 油 与 细 面 做 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2771', '3', '2', '8', '要 把 这 些 东 西 做 的 素 祭 带 到 耶 和 华 面 前 ， 并 奉 给 祭 司 ， 带 到 坛 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2772', '3', '2', '9', '祭 司 要 从 素 祭 中 取 出 作 为 纪 念 的 ， 烧 在 坛 上 ， 是 献 与 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2773', '3', '2', '10', '素 祭 所 剩 的 要 归 给 亚 伦 和 他 的 子 孙 。 这 是 献 与 耶 和 华 的 火 祭 中 为 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2774', '3', '2', '11', '“ 凡 献 给 耶 和 华 的 素 祭 都 不 可 有 酵 ； 因 为 你 们 不 可 烧 一 点 酵 、 一 点 蜜 当 作 火 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2775', '3', '2', '12', '这 些 物 要 献 给 耶 和 华 作 为 初 熟 的 供 物 ， 只 是 不 可 在 坛 上 献 为 馨 香 的 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2776', '3', '2', '13', '凡 献 为 素 祭 的 供 物 都 要 用 盐 调 和 ， 在 素 祭 上 不 可 缺 了 你 神 立 约 的 盐 。 一 切 的 供 物 都 要 配 盐 而 献 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2777', '3', '2', '14', '若 向 耶 和 华 献 初 熟 之 物 为 素 祭 ， 要 献 上 烘 了 的 禾 穗 子 ， 就 是 轧 了 的 新 穗 子 ， 当 作 初 熟 之 物 的 素 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2778', '3', '2', '15', '并 要 抹 上 油 ， 加 上 乳 香 ； 这 是 素 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2779', '3', '2', '16', '祭 司 要 把 其 中 作 为 纪 念 的 ， 就 是 一 些 轧 了 的 禾 穗 子 和 一 些 油 ， 并 所 有 的 乳 香 ， 都 焚 烧 ， 是 向 耶 和 华 献 的 火 祭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2780', '3', '3', '1', '＜ 平 安 祭 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2781', '3', '3', '2', '他 要 按 手 在 供 物 的 头 上 ， 宰 于 会 幕 门 口 。 亚 伦 子 孙 作 祭 司 的 ， 要 把 血 洒 在 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2782', '3', '3', '3', '从 平 安 祭 中 ， 将 火 祭 献 给 耶 和 华 ， 也 要 把 盖 脏 的 脂 油 和 脏 上 所 有 的 脂 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2783', '3', '3', '4', '并 两 个 腰 子 和 腰 子 上 的 脂 油 ， 就 是 靠 腰 两 旁 的 脂 油 ， 与 肝 上 的 网 子 和 腰 子 ， 一 概 取 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2784', '3', '3', '5', '亚 伦 的 子 孙 要 把 这 些 烧 在 坛 的 燔 祭 上 ， 就 是 在 火 的 柴 上 ， 是 献 与 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2785', '3', '3', '6', '“ 人 向 耶 和 华 献 供 物 为 平 安 祭 ， 若 是 从 羊 群 中 献 ， 无 论 是 公 的 是 母 的 ， 必 用 没 有 残 疾 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2786', '3', '3', '7', '若 献 一 只 羊 羔 为 供 物 ， 必 在 耶 和 华 面 前 献 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2787', '3', '3', '8', '并 要 按 手 在 供 物 的 头 上 ， 宰 于 会 幕 前 。 亚 伦 的 子 孙 要 把 血 洒 在 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2788', '3', '3', '9', '从 平 安 祭 中 ， 将 火 祭 献 给 耶 和 华 ， 其 中 的 脂 油 和 整 肥 尾 巴 都 要 在 靠 近 脊 骨 处 取 下 ， 并 要 把 盖 脏 的 脂 油 和 脏 上 所 有 的 脂 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2789', '3', '3', '10', '两 个 腰 子 和 腰 子 上 的 脂 油 ， 就 是 靠 腰 两 旁 的 脂 油 ， 并 肝 上 的 网 子 和 腰 子 ， 一 概 取 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2790', '3', '3', '11', '祭 司 要 在 坛 上 焚 烧 ， 是 献 给 耶 和 华 为 食 物 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2791', '3', '3', '12', '“ 人 的 供 物 若 是 山 羊 ， 必 在 耶 和 华 面 前 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2792', '3', '3', '13', '要 按 手 在 山 羊 头 上 ， 宰 于 会 幕 前 。 亚 伦 的 子 孙 要 把 血 洒 在 坛 的 周 围 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2793', '3', '3', '14', '又 把 盖 脏 的 脂 油 和 脏 上 所 有 的 脂 油 ， 两 个 腰 子 和 腰 子 上 的 脂 油 ， 就 是 靠 腰 两 旁 的 脂 油 ， 并 肝 上 的 网 子 和 腰 子 ， 一 概 取 下 ， 献 给 耶 和 华 为 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2794', '3', '3', '15', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2795', '3', '3', '16', '祭 司 要 在 坛 上 焚 烧 ， 作 为 馨 香 火 祭 的 食 物 。 脂 油 都 是 耶 和 华 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2796', '3', '3', '17', '在 你 们 一 切 的 住 处 ， 脂 油 和 血 都 不 可 吃 ； 这 要 成 为 你 们 世 世 代 代 永 远 的 定 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2797', '3', '4', '1', '＜ 为 误 犯 的 罪 献 祭 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2798', '3', '4', '2', '“ 你 晓 谕 以 色 列 人 说 ： 若 有 人 在 耶 和 华 所 吩 咐 不 可 行 的 什 么 事 上 误 犯 了 一 件 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2799', '3', '4', '3', '或 是 受 膏 的 祭 司 犯 罪 ， 使 百 姓 陷 在 罪 里 ， 就 当 为 他 所 犯 的 罪 把 没 有 残 疾 的 公 牛 犊 献 给 耶 和 华 为 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2800', '3', '4', '4', '他 要 牵 公 牛 到 会 幕 门 口 ， 在 耶 和 华 面 前 按 手 在 牛 的 头 上 ， 把 牛 宰 于 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2801', '3', '4', '5', '受 膏 的 祭 司 要 取 些 公 牛 的 血 带 到 会 幕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2802', '3', '4', '6', '把 指 头 蘸 于 血 中 ， 在 耶 和 华 面 前 对 着 圣 所 的 幔 子 弹 血 七 次 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2803', '3', '4', '7', '又 要 把 些 血 抹 在 会 幕 内 、 耶 和 华 面 前 香 坛 的 四 角 上 ， 再 把 公 牛 所 有 的 血 倒 在 会 幕 门 口 、 燔 祭 坛 的 脚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2804', '3', '4', '8', '要 把 赎 罪 祭 公 牛 所 有 的 脂 油 ， 乃 是 盖 脏 的 脂 油 和 脏 上 所 有 的 脂 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2805', '3', '4', '9', '并 两 个 腰 子 和 腰 子 上 的 脂 油 ， 就 是 靠 腰 两 旁 的 脂 油 ， 与 肝 上 的 网 子 和 腰 子 ， 一 概 取 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2806', '3', '4', '10', '与 平 安 祭 公 牛 上 所 取 的 一 样 ； 祭 司 要 把 这 些 烧 在 燔 祭 的 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2807', '3', '4', '11', '公 牛 的 皮 和 所 有 的 肉 ， 并 头 、 腿 、 脏 、 腑 、 粪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2808', '3', '4', '12', '就 是 全 公 牛 ， 要 搬 到 营 外 洁 净 之 地 、 倒 灰 之 所 ， 用 火 烧 在 柴 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2809', '3', '4', '13', '“ 以 色 列 全 会 众 若 行 了 耶 和 华 所 吩 咐 不 可 行 的 什 么 事 ， 误 犯 了 罪 ， 是 隐 而 未 现 、 会 众 看 不 出 来 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2810', '3', '4', '14', '会 众 一 知 道 所 犯 的 罪 就 要 献 一 只 公 牛 犊 为 赎 罪 祭 ， 牵 到 会 幕 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2811', '3', '4', '15', '会 中 的 长 老 就 要 在 耶 和 华 面 前 按 手 在 牛 的 头 上 ， 将 牛 在 耶 和 华 面 前 宰 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2812', '3', '4', '16', '受 膏 的 祭 司 要 取 些 公 牛 的 血 带 到 会 幕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2813', '3', '4', '17', '把 指 头 蘸 于 血 中 ， 在 耶 和 华 面 前 对 着 幔 子 弹 血 七 次 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2814', '3', '4', '18', '又 要 把 些 血 抹 在 会 幕 内 、 耶 和 华 面 前 坛 的 四 角 上 ， 再 把 所 有 的 血 倒 在 会 幕 门 口 、 燔 祭 坛 的 脚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2815', '3', '4', '19', '把 牛 所 有 的 脂 油 都 取 下 ， 烧 在 坛 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2816', '3', '4', '20', '收 拾 这 牛 ， 与 那 赎 罪 祭 的 牛 一 样 。 祭 司 要 为 他 们 赎 罪 ， 他 们 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2817', '3', '4', '21', '他 要 把 牛 搬 到 营 外 烧 了 ， 像 烧 头 一 个 牛 一 样 ； 这 是 会 众 的 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2818', '3', '4', '22', '“ 官 长 若 行 了 耶 和 华 ─ ─ 他 神 所 吩 咐 不 可 行 的 什 么 事 ， 误 犯 了 罪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2819', '3', '4', '23', '所 犯 的 罪 自 己 知 道 了 ， 就 要 牵 一 只 没 有 残 疾 的 公 山 羊 为 供 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2820', '3', '4', '24', '按 手 在 羊 的 头 上 ， 宰 于 耶 和 华 面 前 、 宰 燔 祭 牲 的 地 方 ； 这 是 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2821', '3', '4', '25', '祭 司 要 用 指 头 蘸 些 赎 罪 祭 牲 的 血 ， 抹 在 燔 祭 坛 的 四 角 上 ， 把 血 倒 在 燔 祭 坛 的 脚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2822', '3', '4', '26', '所 有 的 脂 油 ， 祭 司 都 要 烧 在 坛 上 ， 正 如 平 安 祭 的 脂 油 一 样 。 至 于 他 的 罪 ， 祭 司 要 为 他 赎 了 ， 他 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2823', '3', '4', '27', '“ 民 中 若 有 人 行 了 耶 和 华 所 吩 咐 不 可 行 的 什 么 事 ， 误 犯 了 罪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2824', '3', '4', '28', '所 犯 的 罪 自 己 知 道 了 ， 就 要 为 所 犯 的 罪 牵 一 只 没 有 残 疾 的 母 山 羊 为 供 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2825', '3', '4', '29', '按 手 在 赎 罪 祭 牲 的 头 上 ， 在 那 宰 燔 祭 牲 的 地 方 宰 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2826', '3', '4', '30', '祭 司 要 用 指 头 蘸 些 羊 的 血 ， 抹 在 燔 祭 坛 的 四 角 上 ， 所 有 的 血 都 要 倒 在 坛 的 脚 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2827', '3', '4', '31', '又 要 把 羊 所 有 的 脂 油 都 取 下 ， 正 如 取 平 安 祭 牲 的 脂 油 一 样 。 祭 司 要 在 坛 上 焚 烧 ， 在 耶 和 华 面 前 作 为 馨 香 的 祭 ， 为 他 赎 罪 ， 他 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2828', '3', '4', '32', '“ 人 若 牵 一 只 绵 羊 羔 为 赎 罪 祭 的 供 物 ， 必 要 牵 一 只 没 有 残 疾 的 母 羊 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2829', '3', '4', '33', '按 手 在 赎 罪 祭 牲 的 头 上 ， 在 那 宰 燔 祭 牲 的 地 方 宰 了 作 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2830', '3', '4', '34', '祭 司 要 用 指 头 蘸 些 赎 罪 祭 牲 的 血 ， 抹 在 燔 祭 坛 的 四 角 上 ， 所 有 的 血 都 要 倒 在 坛 的 脚 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2831', '3', '4', '35', '又 要 把 所 有 的 脂 油 都 取 下 ， 正 如 取 平 安 祭 羊 羔 的 脂 油 一 样 。 祭 司 要 按 献 给 耶 和 华 火 祭 的 条 例 ， 烧 在 坛 上 。 至 于 所 犯 的 罪 ， 祭 司 要 为 他 赎 了 ， 他 必 蒙 赦 免 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2832', '3', '5', '1', '＜ 赎 愆 祭 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2833', '3', '5', '2', '或 是 有 人 摸 了 不 洁 的 物 ， 无 论 是 不 洁 的 死 兽 ， 是 不 洁 的 死 畜 ， 是 不 洁 的 死 虫 ， 他 却 不 知 道 ， 因 此 成 了 不 洁 ， 就 有 了 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2834', '3', '5', '3', '或 是 他 摸 了 别 人 的 污 秽 ， 无 论 是 染 了 什 么 污 秽 ， 他 却 不 知 道 ， 一 知 道 了 就 有 了 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2835', '3', '5', '4', '或 是 有 人 嘴 里 冒 失 发 誓 ， 要 行 恶 ， 要 行 善 ， 无 论 人 在 什 么 事 上 冒 失 发 誓 ， 他 却 不 知 道 ， 一 知 道 了 就 要 在 这 其 中 的 一 件 上 有 了 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2836', '3', '5', '5', '他 有 了 罪 的 时 候 ， 就 要 承 认 所 犯 的 罪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2837', '3', '5', '6', '并 要 因 所 犯 的 罪 ， 把 他 的 赎 愆 祭 牲 ─ ─ 就 是 羊 群 中 的 母 羊 ， 或 是 一 只 羊 羔 ， 或 是 一 只 山 羊 ─ ─ 牵 到 耶 和 华 面 前 为 赎 罪 祭 。 至 于 他 的 罪 ， 祭 司 要 为 他 赎 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2838', '3', '5', '7', '“ 他 的 力 量 若 不 够 献 一 只 羊 羔 ， 就 要 因 所 犯 的 罪 ， 把 两 只 斑 鸠 或 是 两 只 雏 鸽 带 到 耶 和 华 面 前 为 赎 愆 祭 ： 一 只 作 赎 罪 祭 ， 一 只 作 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2839', '3', '5', '8', '把 这 些 带 到 祭 司 那 里 ， 祭 司 就 要 先 把 那 赎 罪 祭 献 上 ， 从 鸟 的 颈 项 上 揪 下 头 来 ， 只 是 不 可 把 鸟 撕 断 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2840', '3', '5', '9', '也 把 些 赎 罪 祭 牲 的 血 弹 在 坛 的 旁 边 ， 剩 下 的 血 要 流 在 坛 的 脚 那 里 ； 这 是 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2841', '3', '5', '10', '他 要 照 例 献 第 二 只 为 燔 祭 。 至 于 他 所 犯 的 罪 ， 祭 司 要 为 他 赎 了 ， 他 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2842', '3', '5', '11', '“ 他 的 力 量 若 不 够 献 两 只 斑 鸠 或 是 两 只 雏 鸽 ， 就 要 因 所 犯 的 罪 带 供 物 来 ， 就 是 细 面 伊 法 十 分 之 一 为 赎 罪 祭 ； 不 可 加 上 油 ， 也 不 可 加 上 乳 香 ， 因 为 是 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2843', '3', '5', '12', '他 要 把 供 物 带 到 祭 司 那 里 ， 祭 司 要 取 出 自 己 的 一 把 来 作 为 纪 念 ， 按 献 给 耶 和 华 火 祭 的 条 例 烧 在 坛 上 ； 这 是 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2844', '3', '5', '13', '至 于 他 在 这 几 件 事 中 所 犯 的 罪 ， 祭 司 要 为 他 赎 了 ， 他 必 蒙 赦 免 。 剩 下 的 面 都 归 与 祭 司 ， 和 素 祭 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2845', '3', '5', '14', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2846', '3', '5', '15', '“ 人 若 在 耶 和 华 的 圣 物 上 误 犯 了 罪 ， 有 了 过 犯 ， 就 要 照 你 所 估 的 ， 按 圣 所 的 舍 客 勒 拿 银 子 ， 将 赎 愆 祭 牲 ─ ─ 就 是 羊 群 中 一 只 没 有 残 疾 的 公 绵 羊 ─ ─ 牵 到 耶 和 华 面 前 为 赎 愆 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2847', '3', '5', '16', '并 且 他 因 在 圣 物 上 的 差 错 要 偿 还 ， 另 外 加 五 分 之 一 ， 都 给 祭 司 。 祭 司 要 用 赎 愆 祭 的 公 绵 羊 为 他 赎 罪 ， 他 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2848', '3', '5', '17', '“ 若 有 人 犯 罪 ， 行 了 耶 和 华 所 吩 咐 不 可 行 的 什 么 事 ， 他 虽 然 不 知 道 ， 还 是 有 了 罪 ， 就 要 担 当 他 的 罪 孽 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2849', '3', '5', '18', '也 要 照 你 所 估 定 的 价 ， 从 羊 群 中 牵 一 只 没 有 残 疾 的 公 绵 羊 来 ， 给 祭 司 作 赎 愆 祭 。 至 于 他 误 行 的 那 错 事 ， 祭 司 要 为 他 赎 罪 ， 他 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2850', '3', '5', '19', '这 是 赎 愆 祭 ， 因 他 在 耶 和 华 面 前 实 在 有 了 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2851', '3', '6', '1', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2852', '3', '6', '2', '“ 若 有 人 犯 罪 ， 干 犯 耶 和 华 ， 在 邻 舍 交 付 他 的 物 上 ， 或 是 在 交 易 上 行 了 诡 诈 ， 或 是 抢 夺 人 的 财 物 ， 或 是 欺 压 邻 舍 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2853', '3', '6', '3', '或 是 在 捡 了 遗 失 的 物 上 行 了 诡 诈 ， 说 谎 起 誓 ， 在 这 一 切 的 事 上 犯 了 什 么 罪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2854', '3', '6', '4', '他 既 犯 了 罪 ， 有 了 过 犯 ， 就 要 归 还 他 所 抢 夺 的 ， 或 是 因 欺 压 所 得 的 ， 或 是 人 交 付 他 的 ， 或 是 人 遗 失 他 所 捡 的 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2855', '3', '6', '5', '或 是 他 因 什 么 物 起 了 假 誓 ， 就 要 如 数 归 还 ， 另 外 加 上 五 分 之 一 ， 在 查 出 他 有 罪 的 日 子 要 交 还 本 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2856', '3', '6', '6', '也 要 照 你 所 估 定 的 价 ， 把 赎 愆 祭 牲 ─ ─ 就 是 羊 群 中 一 只 没 有 残 疾 的 公 绵 羊 ─ ─ 牵 到 耶 和 华 面 前 ， 给 祭 司 为 赎 愆 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2857', '3', '6', '7', '祭 司 要 在 耶 和 华 面 前 为 他 赎 罪 ； 他 无 论 行 了 什 么 事 ， 使 他 有 了 罪 ， 都 必 蒙 赦 免 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2858', '3', '6', '8', '＜ 祭 司 献 燔 祭 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2859', '3', '6', '9', '“ 你 要 吩 咐 亚 伦 和 他 的 子 孙 说 ， 燔 祭 的 条 例 乃 是 这 样 ： 燔 祭 要 放 在 坛 的 柴 上 ， 从 晚 上 到 天 亮 ， 坛 上 的 火 要 常 常 烧 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2860', '3', '6', '10', '祭 司 要 穿 上 细 麻 布 衣 服 ， 又 要 把 细 麻 布 裤 子 穿 在 身 上 ， 把 坛 上 所 烧 的 燔 祭 灰 收 起 来 ， 倒 在 坛 的 旁 边 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2861', '3', '6', '11', '随 后 要 脱 去 这 衣 服 ， 穿 上 别 的 衣 服 ， 把 灰 拿 到 营 外 洁 净 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2862', '3', '6', '12', '坛 上 的 火 要 在 其 上 常 常 烧 着 ， 不 可 熄 灭 。 祭 司 要 每 日 早 晨 在 上 面 烧 柴 ， 并 要 把 燔 祭 摆 在 坛 上 ， 在 其 上 烧 平 安 祭 牲 的 脂 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2863', '3', '6', '13', '在 坛 上 必 有 常 常 烧 着 的 火 ， 不 可 熄 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2864', '3', '6', '14', '＜ 祭 司 献 素 祭 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2865', '3', '6', '15', '祭 司 要 从 其 中 ─ ─ 就 是 从 素 祭 的 细 面 中 ─ ─ 取 出 自 己 的 一 把 ， 又 要 取 些 油 和 素 祭 上 所 有 的 乳 香 ， 烧 在 坛 上 ， 奉 给 耶 和 华 为 馨 香 素 祭 的 纪 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2866', '3', '6', '16', '所 剩 下 的 ， 亚 伦 和 他 子 孙 要 吃 ， 必 在 圣 处 不 带 酵 而 吃 ， 要 在 会 幕 的 院 子 里 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2867', '3', '6', '17', '烤 的 时 候 不 可 搀 酵 。 这 是 从 所 献 给 我 的 火 祭 中 赐 给 他 们 的 分 ， 是 至 圣 的 ， 和 赎 罪 祭 并 赎 愆 祭 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2868', '3', '6', '18', '凡 献 给 耶 和 华 的 火 祭 ， 亚 伦 子 孙 中 的 男 丁 都 要 吃 这 一 分 ， 直 到 万 代 ， 作 他 们 永 得 的 分 。 摸 这 些 祭 物 的 ， 都 要 成 为 圣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2869', '3', '6', '19', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2870', '3', '6', '20', '“ 当 亚 伦 受 膏 的 日 子 ， 他 和 他 子 孙 所 要 献 给 耶 和 华 的 供 物 ， 就 是 细 面 伊 法 十 分 之 一 ， 为 常 献 的 素 祭 ： 早 晨 一 半 ， 晚 上 一 半 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2871', '3', '6', '21', '要 在 铁 鏊 上 用 油 调 和 做 成 ， 调 匀 了 ， 你 就 拿 进 来 ； 烤 好 了 分 成 块 子 ， 献 给 耶 和 华 为 馨 香 的 素 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2872', '3', '6', '22', '亚 伦 的 子 孙 中 ， 接 续 他 为 受 膏 的 祭 司 ， 要 把 这 素 祭 献 上 ， 要 全 烧 给 耶 和 华 。 这 是 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2873', '3', '6', '23', '祭 司 的 素 祭 都 要 烧 了 ， 却 不 可 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2874', '3', '6', '24', '＜ 祭 司 献 赎 罪 祭 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2875', '3', '6', '25', '“ 你 对 亚 伦 和 他 的 子 孙 说 ， 赎 罪 祭 的 条 例 乃 是 这 样 ： 要 在 耶 和 华 面 前 、 宰 燔 祭 牲 的 地 方 宰 赎 罪 祭 牲 ； 这 是 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2876', '3', '6', '26', '为 赎 罪 献 这 祭 的 祭 司 要 吃 ， 要 在 圣 处 ， 就 是 在 会 幕 的 院 子 里 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2877', '3', '6', '27', '凡 摸 这 祭 肉 的 要 成 为 圣 ； 这 祭 牲 的 血 若 弹 在 什 么 衣 服 上 ， 所 弹 的 那 一 件 要 在 圣 处 洗 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2878', '3', '6', '28', '惟 有 煮 祭 物 的 瓦 器 要 打 碎 ； 若 是 煮 在 铜 器 里 ， 这 铜 器 要 擦 磨 ， 在 水 中 涮 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2879', '3', '6', '29', '凡 祭 司 中 的 男 丁 都 可 以 吃 ； 这 是 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2880', '3', '6', '30', '凡 赎 罪 祭 ， 若 将 血 带 进 会 幕 在 圣 所 赎 罪 ， 那 肉 都 不 可 吃 ， 必 用 火 焚 烧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2881', '3', '7', '1', '＜ 祭 司 献 赎 愆 祭 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2882', '3', '7', '2', '人 在 那 里 宰 燔 祭 牲 ， 也 要 在 那 里 宰 赎 愆 祭 牲 ； 其 血 ， 祭 司 要 洒 在 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2883', '3', '7', '3', '又 要 将 肥 尾 巴 和 盖 脏 的 脂 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2884', '3', '7', '4', '两 个 腰 子 和 腰 子 上 的 脂 油 ， 就 是 靠 腰 两 旁 的 脂 油 ， 并 肝 上 的 网 子 和 腰 子 ， 一 概 取 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2885', '3', '7', '5', '祭 司 要 在 坛 上 焚 烧 ， 为 献 给 耶 和 华 的 火 祭 ， 是 赎 愆 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2886', '3', '7', '6', '祭 司 中 的 男 丁 都 可 以 吃 这 祭 物 ； 要 在 圣 处 吃 ， 是 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2887', '3', '7', '7', '赎 罪 祭 怎 样 ， 赎 愆 祭 也 是 怎 样 ， 两 个 祭 是 一 个 条 例 。 献 赎 愆 祭 赎 罪 的 祭 司 要 得 这 祭 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2888', '3', '7', '8', '献 燔 祭 的 祭 司 ， 无 论 为 谁 奉 献 ， 要 亲 自 得 他 所 献 那 燔 祭 牲 的 皮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2889', '3', '7', '9', '凡 在 炉 中 烤 的 素 祭 和 煎 盘 中 做 的 ， 并 铁 鏊 上 做 的 ， 都 要 归 那 献 祭 的 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2890', '3', '7', '10', '凡 素 祭 ， 无 论 是 油 调 和 的 是 干 的 ， 都 要 归 亚 伦 的 子 孙 ， 大 家 均 分 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2891', '3', '7', '11', '＜ 祭 司 献 平 安 祭 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2892', '3', '7', '12', '他 若 为 感 谢 献 上 ， 就 要 用 调 油 的 无 酵 饼 和 抹 油 的 无 酵 薄 饼 ， 并 用 油 调 匀 细 面 做 的 饼 ， 与 感 谢 祭 一 同 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2893', '3', '7', '13', '要 用 有 酵 的 饼 和 为 感 谢 献 的 平 安 祭 ， 与 供 物 一 同 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2894', '3', '7', '14', '从 各 样 的 供 物 中 ， 他 要 把 一 个 饼 献 给 耶 和 华 为 举 祭 ， 是 要 归 给 洒 平 安 祭 牲 血 的 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2895', '3', '7', '15', '为 感 谢 献 平 安 祭 牲 的 肉 ， 要 在 献 的 日 子 吃 ， 一 点 不 可 留 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2896', '3', '7', '16', '若 所 献 的 是 为 还 愿 ， 或 是 甘 心 献 的 ， 必 在 献 祭 的 日 子 吃 ， 所 剩 下 的 第 二 天 也 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2897', '3', '7', '17', '但 所 剩 下 的 祭 肉 ， 到 第 三 天 要 用 火 焚 烧 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2898', '3', '7', '18', '第 三 天 若 吃 了 平 安 祭 的 肉 ， 这 祭 必 不 蒙 悦 纳 ， 人 所 献 的 也 不 算 为 祭 ， 反 为 可 憎 嫌 的 ， 吃 这 祭 肉 的 ， 就 必 担 当 他 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2899', '3', '7', '19', '“ 挨 了 污 秽 物 的 肉 就 不 可 吃 ， 要 用 火 焚 烧 。 至 于 平 安 祭 的 肉 ， 凡 洁 净 的 人 都 要 吃 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2900', '3', '7', '20', '只 是 献 与 耶 和 华 平 安 祭 的 肉 ， 人 若 不 洁 净 而 吃 了 ， 这 人 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2901', '3', '7', '21', '有 人 摸 了 什 么 不 洁 净 的 物 ， 或 是 人 的 不 洁 净 ， 或 是 不 洁 净 的 牲 畜 ， 或 是 不 洁 可 憎 之 物 ， 吃 了 献 与 耶 和 华 平 安 祭 的 肉 ， 这 人 必 从 民 中 剪 除 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2902', '3', '7', '22', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2903', '3', '7', '23', '“ 你 晓 谕 以 色 列 人 说 ： 牛 的 脂 油 、 绵 羊 的 脂 油 、 山 羊 的 脂 油 ， 你 们 都 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2904', '3', '7', '24', '自 死 的 和 被 野 兽 撕 裂 的 ， 那 脂 油 可 以 做 别 的 使 用 ， 只 是 你 们 万 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2905', '3', '7', '25', '无 论 何 人 吃 了 献 给 耶 和 华 当 火 祭 牲 畜 的 脂 油 ， 那 人 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2906', '3', '7', '26', '在 你 们 一 切 的 住 处 ， 无 论 是 雀 鸟 的 血 是 野 兽 的 血 ， 你 们 都 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2907', '3', '7', '27', '无 论 是 谁 吃 血 ， 那 人 必 从 民 中 剪 除 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2908', '3', '7', '28', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2909', '3', '7', '29', '“ 你 晓 谕 以 色 列 人 说 ： 献 平 安 祭 给 耶 和 华 的 ， 要 从 平 安 祭 中 取 些 来 奉 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2910', '3', '7', '30', '他 亲 手 献 给 耶 和 华 的 火 祭 ， 就 是 脂 油 和 胸 ， 要 带 来 ， 好 把 胸 在 耶 和 华 面 前 作 摇 祭 ， 摇 一 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2911', '3', '7', '31', '祭 司 要 把 脂 油 在 坛 上 焚 烧 ， 但 胸 要 归 亚 伦 和 他 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2912', '3', '7', '32', '你 们 要 从 平 安 祭 中 把 右 腿 作 举 祭 ， 奉 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2913', '3', '7', '33', '亚 伦 子 孙 中 ， 献 平 安 祭 牲 血 和 脂 油 的 ， 要 得 这 右 腿 为 分 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2914', '3', '7', '34', '因 为 我 从 以 色 列 人 的 平 安 祭 中 ， 取 了 这 摇 的 胸 和 举 的 腿 给 祭 司 亚 伦 和 他 子 孙 ， 作 他 们 从 以 色 列 人 中 所 永 得 的 分 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2915', '3', '7', '35', '这 是 从 耶 和 华 火 祭 中 ， 作 亚 伦 受 膏 的 分 和 他 子 孙 受 膏 的 分 ， 正 在 摩 西 ｛ 原 文 是 他 ｝ 叫 他 们 前 来 给 耶 和 华 供 祭 司 职 分 的 日 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2916', '3', '7', '36', '就 是 在 摩 西 ｛ 原 文 是 他 ｝ 膏 他 们 的 日 子 ， 耶 和 华 吩 咐 以 色 列 人 给 他 们 的 。 这 是 他 们 世 世 代 代 永 得 的 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2917', '3', '7', '37', '这 就 是 燔 祭 、 素 祭 、 赎 罪 祭 、 赎 愆 祭 ， 和 平 安 祭 的 条 例 ， 并 承 接 圣 职 的 礼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2918', '3', '7', '38', '都 是 耶 和 华 在 西 奈 山 所 吩 咐 摩 西 的 ， 就 是 他 在 西 奈 旷 野 吩 咐 以 色 列 人 献 供 物 给 耶 和 华 之 日 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2919', '3', '8', '1', '＜ 立 亚 伦 和 他 的 儿 子 们 作 祭 司 （ 出   2 9 : 1 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2920', '3', '8', '2', '“ 你 将 亚 伦 和 他 儿 子 一 同 带 来 ， 并 将 圣 衣 、 膏 油 ， 与 赎 罪 祭 的 一 只 公 牛 、 两 只 公 绵 羊 、 一 筐 无 酵 饼 都 带 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2921', '3', '8', '3', '又 招 聚 会 众 到 会 幕 门 口 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2922', '3', '8', '4', '摩 西 就 照 耶 和 华 所 吩 咐 的 行 了 ； 于 是 会 众 聚 集 在 会 幕 门 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2923', '3', '8', '5', '摩 西 告 诉 会 众 说 ： “ 这 就 是 耶 和 华 所 吩 咐 当 行 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2924', '3', '8', '6', '摩 西 带 了 亚 伦 和 他 儿 子 来 ， 用 水 洗 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2925', '3', '8', '7', '给 亚 伦 穿 上 内 袍 ， 束 上 腰 带 ， 穿 上 外 袍 ， 又 加 上 以 弗 得 ， 用 其 上 巧 工 织 的 带 子 把 以 弗 得 系 在 他 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2926', '3', '8', '8', '又 给 他 戴 上 胸 牌 ， 把 乌 陵 和 土 明 放 在 胸 牌 内 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2927', '3', '8', '9', '把 冠 冕 戴 在 他 头 上 ， 在 冠 冕 的 前 面 钉 上 金 牌 ， 就 是 圣 冠 ， 都 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2928', '3', '8', '10', '摩 西 用 膏 油 抹 帐 幕 和 其 中 所 有 的 ， 使 它 成 圣 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2929', '3', '8', '11', '又 用 膏 油 在 坛 上 弹 了 七 次 ， 又 抹 了 坛 和 坛 的 一 切 器 皿 ， 并 洗 濯 盆 和 盆 座 ， 使 它 成 圣 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2930', '3', '8', '12', '又 把 膏 油 倒 在 亚 伦 的 头 上 膏 他 ， 使 他 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2931', '3', '8', '13', '摩 西 带 了 亚 伦 的 儿 子 来 ， 给 他 们 穿 上 内 袍 ， 束 上 腰 带 ， 包 上 裹 头 巾 ， 都 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2932', '3', '8', '14', '他 牵 了 赎 罪 祭 的 公 牛 来 ， 亚 伦 和 他 儿 子 按 手 在 赎 罪 祭 公 牛 的 头 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2933', '3', '8', '15', '就 宰 了 公 牛 。 摩 西 用 指 头 蘸 血 ， 抹 在 坛 上 四 角 的 周 围 ， 使 坛 洁 净 ， 把 血 倒 在 坛 的 脚 那 里 ， 使 坛 成 圣 ， 坛 就 洁 净 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2934', '3', '8', '16', '又 取 脏 上 所 有 的 脂 油 和 肝 上 的 网 子 ， 并 两 个 腰 子 与 腰 子 上 的 脂 油 ， 都 烧 在 坛 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2935', '3', '8', '17', '惟 有 公 牛 ， 连 皮 带 肉 并 粪 ， 用 火 烧 在 营 外 ， 都 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2936', '3', '8', '18', '他 奉 上 燔 祭 的 公 绵 羊 ； 亚 伦 和 他 儿 子 按 手 在 羊 的 头 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2937', '3', '8', '19', '就 宰 了 公 羊 。 摩 西 把 血 洒 在 坛 的 周 围 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2938', '3', '8', '20', '把 羊 切 成 块 子 ， 把 头 和 肉 块 并 脂 油 都 烧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2939', '3', '8', '21', '用 水 洗 了 脏 腑 和 腿 ， 就 把 全 羊 烧 在 坛 上 为 馨 香 的 燔 祭 ， 是 献 给 耶 和 华 的 火 祭 ， 都 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2940', '3', '8', '22', '他 又 奉 上 第 二 只 公 绵 羊 ， 就 是 承 接 圣 职 之 礼 的 羊 ； 亚 伦 和 他 儿 子 按 手 在 羊 的 头 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2941', '3', '8', '23', '就 宰 了 羊 。 摩 西 把 些 血 抹 在 亚 伦 的 右 耳 垂 上 和 右 手 的 大 拇 指 上 ， 并 右 脚 的 大 拇 指 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2942', '3', '8', '24', '又 带 了 亚 伦 的 儿 子 来 ， 把 些 血 抹 在 他 们 的 右 耳 垂 上 和 右 手 的 大 拇 指 上 ， 并 右 脚 的 大 拇 指 上 ， 又 把 血 洒 在 坛 的 周 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2943', '3', '8', '25', '取 脂 油 和 肥 尾 巴 ， 并 脏 上 一 切 的 脂 油 与 肝 上 的 网 子 ， 两 个 腰 子 和 腰 子 上 的 脂 油 ， 并 右 腿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2944', '3', '8', '26', '再 从 耶 和 华 面 前 、 盛 无 酵 饼 的 筐 子 里 取 出 一 个 无 酵 饼 ， 一 个 油 饼 ， 一 个 薄 饼 ， 都 放 在 脂 油 和 右 腿 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2945', '3', '8', '27', '把 这 一 切 放 在 亚 伦 的 手 上 和 他 儿 子 的 手 上 作 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2946', '3', '8', '28', '摩 西 从 他 们 的 手 上 拿 下 来 ， 烧 在 坛 上 的 燔 祭 上 ， 都 是 为 承 接 圣 职 献 给 耶 和 华 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2947', '3', '8', '29', '摩 西 拿 羊 的 胸 作 为 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ， 是 承 接 圣 职 之 礼 ， 归 摩 西 的 分 ， 都 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2948', '3', '8', '30', '摩 西 取 点 膏 油 和 坛 上 的 血 ， 弹 在 亚 伦 和 他 的 衣 服 上 ， 并 他 儿 子 和 他 儿 子 的 衣 服 上 ， 使 他 和 他 们 的 衣 服 一 同 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2949', '3', '8', '31', '摩 西 对 亚 伦 和 他 儿 子 说 ： “ 把 肉 煮 在 会 幕 门 口 ， 在 那 里 吃 ， 又 吃 承 接 圣 职 筐 子 里 的 饼 ， 按 我 所 吩 咐 的 说 ｛ 或 译 ： 按 所 吩 咐 我 的 说 ｝ ： ‘ 这 是 亚 伦 和 他 儿 子 要 吃 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2950', '3', '8', '32', '剩 下 的 肉 和 饼 ， 你 们 要 用 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2951', '3', '8', '33', '你 们 七 天 不 可 出 会 幕 的 门 ， 等 到 你 们 承 接 圣 职 的 日 子 满 了 ， 因 为 主 叫 你 们 七 天 承 接 圣 职 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2952', '3', '8', '34', '像 今 天 所 行 的 都 是 耶 和 华 吩 咐 行 的 ， 为 你 们 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2953', '3', '8', '35', '七 天 你 们 要 昼 夜 住 在 会 幕 门 口 ， 遵 守 耶 和 华 的 吩 咐 ， 免 得 你 们 死 亡 ， 因 为 所 吩 咐 我 的 就 是 这 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2954', '3', '8', '36', '于 是 亚 伦 和 他 儿 子 行 了 耶 和 华 藉 着 摩 西 所 吩 咐 的 一 切 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2955', '3', '9', '1', '＜ 亚 伦 献 祭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2956', '3', '9', '2', '对 亚 伦 说 ： “ 你 当 取 牛 群 中 的 一 只 公 牛 犊 作 赎 罪 祭 ， 一 只 公 绵 羊 作 燔 祭 ， 都 要 没 有 残 疾 的 ， 献 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2957', '3', '9', '3', '你 也 要 对 以 色 列 人 说 ： ‘ 你 们 当 取 一 只 公 山 羊 作 赎 罪 祭 ， 又 取 一 只 牛 犊 和 一 只 绵 羊 羔 ， 都 要 一 岁 、 没 有 残 疾 的 ， 作 燔 祭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2958', '3', '9', '4', '又 取 一 只 公 牛 ， 一 只 公 绵 羊 作 平 安 祭 ， 献 在 耶 和 华 面 前 ， 并 取 调 油 的 素 祭 ， 因 为 今 天 耶 和 华 要 向 你 们 显 现 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2959', '3', '9', '5', '于 是 他 们 把 摩 西 所 吩 咐 的 ， 带 到 会 幕 前 ； 全 会 众 都 近 前 来 ， 站 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2960', '3', '9', '6', '摩 西 说 ： “ 这 是 耶 和 华 吩 咐 你 们 所 当 行 的 ； 耶 和 华 的 荣 光 就 要 向 你 们 显 现 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2961', '3', '9', '7', '摩 西 对 亚 伦 说 ： “ 你 就 近 坛 前 ， 献 你 的 赎 罪 祭 和 燔 祭 ， 为 自 己 与 百 姓 赎 罪 ， 又 献 上 百 姓 的 供 物 ， 为 他 们 赎 罪 ， 都 照 耶 和 华 所 吩 咐 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2962', '3', '9', '8', '于 是 ， 亚 伦 就 近 坛 前 ， 宰 了 为 自 己 作 赎 罪 祭 的 牛 犊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2963', '3', '9', '9', '亚 伦 的 儿 子 把 血 奉 给 他 ， 他 就 把 指 头 蘸 在 血 中 ， 抹 在 坛 的 四 角 上 ， 又 把 血 倒 在 坛 脚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2964', '3', '9', '10', '惟 有 赎 罪 祭 的 脂 油 和 腰 子 ， 并 肝 上 取 的 网 子 ， 都 烧 在 坛 上 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2965', '3', '9', '11', '又 用 火 将 肉 和 皮 烧 在 营 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2966', '3', '9', '12', '亚 伦 宰 了 燔 祭 牲 ， 他 儿 子 把 血 递 给 他 ， 他 就 洒 在 坛 的 周 围 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2967', '3', '9', '13', '又 把 燔 祭 一 块 一 块 地 、 连 头 递 给 他 ， 他 都 烧 在 坛 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2968', '3', '9', '14', '又 洗 了 脏 腑 和 腿 ， 烧 在 坛 上 的 燔 祭 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2969', '3', '9', '15', '他 奉 上 百 姓 的 供 物 ， 把 那 给 百 姓 作 赎 罪 祭 的 公 山 羊 宰 了 ， 为 罪 献 上 ， 和 先 献 的 一 样 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2970', '3', '9', '16', '也 奉 上 燔 祭 ， 照 例 而 献 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2971', '3', '9', '17', '他 又 奉 上 素 祭 ， 从 其 中 取 一 满 把 ， 烧 在 坛 上 ； 这 是 在 早 晨 的 燔 祭 以 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2972', '3', '9', '18', '亚 伦 宰 了 那 给 百 姓 作 平 安 祭 的 公 牛 和 公 绵 羊 。 他 儿 子 把 血 递 给 他 ， 他 就 洒 在 坛 的 周 围 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2973', '3', '9', '19', '又 把 公 牛 和 公 绵 羊 的 脂 油 、 肥 尾 巴 ， 并 盖 脏 的 脂 油 与 腰 子 ， 和 肝 上 的 网 子 ， 都 递 给 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2974', '3', '9', '20', '把 脂 油 放 在 胸 上 ， 他 就 把 脂 油 烧 在 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2975', '3', '9', '21', '胸 和 右 腿 ， 亚 伦 当 作 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ， 都 是 照 摩 西 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2976', '3', '9', '22', '亚 伦 向 百 姓 举 手 ， 为 他 们 祝 福 。 他 献 了 赎 罪 祭 、 燔 祭 、 平 安 祭 就 下 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2977', '3', '9', '23', '摩 西 、 亚 伦 进 入 会 幕 ， 又 出 来 为 百 姓 祝 福 ， 耶 和 华 的 荣 光 就 向 众 民 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2978', '3', '9', '24', '有 火 从 耶 和 华 面 前 出 来 ， 在 坛 上 烧 尽 燔 祭 和 脂 油 ； 众 民 一 见 ， 就 都 欢 呼 ， 俯 伏 在 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2979', '3', '10', '1', '＜ 拿 答 和 亚 比 户 犯 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2980', '3', '10', '2', '就 有 火 从 耶 和 华 面 前 出 来 ， 把 他 们 烧 灭 ， 他 们 就 死 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2981', '3', '10', '3', '于 是 摩 西 对 亚 伦 说 ： “ 这 就 是 耶 和 华 所 说 ： ‘ 我 在 亲 近 我 的 人 中 要 显 为 圣 ； 在 众 民 面 前 ， 我 要 得 荣 耀 。 ’ ” 亚 伦 就 默 默 不 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2982', '3', '10', '4', '摩 西 召 了 亚 伦 叔 父 乌 薛 的 儿 子 米 沙 利 、 以 利 撒 反 来 ， 对 他 们 说 ： “ 上 前 来 ， 把 你 们 的 亲 属 从 圣 所 前 抬 到 营 外 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2983', '3', '10', '5', '于 是 二 人 上 前 来 ， 把 他 们 穿 着 袍 子 抬 到 营 外 ， 是 照 摩 西 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2984', '3', '10', '6', '摩 西 对 亚 伦 和 他 儿 子 以 利 亚 撒 、 以 他 玛 说 ： “ 不 可 蓬 头 散 发 ， 也 不 可 撕 裂 衣 裳 ， 免 得 你 们 死 亡 ， 又 免 得 耶 和 华 向 会 众 发 怒 ； 只 要 你 们 的 弟 兄 以 色 列 全 家 为 耶 和 华 所 发 的 火 哀 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2985', '3', '10', '7', '你 们 也 不 可 出 会 幕 的 门 ， 恐 怕 你 们 死 亡 ， 因 为 耶 和 华 的 膏 油 在 你 们 的 身 上 。 ” 他 们 就 照 摩 西 的 话 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2986', '3', '10', '8', '＜ 有 关 祭 司 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2987', '3', '10', '9', '“ 你 和 你 儿 子 进 会 幕 的 时 候 ， 清 酒 、 浓 酒 都 不 可 喝 ， 免 得 你 们 死 亡 ； 这 要 作 你 们 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2988', '3', '10', '10', '使 你 们 可 以 将 圣 的 、 俗 的 ， 洁 净 的 、 不 洁 净 的 ， 分 别 出 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2989', '3', '10', '11', '又 使 你 们 可 以 将 耶 和 华 藉 摩 西 晓 谕 以 色 列 人 的 一 切 律 例 教 训 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2990', '3', '10', '12', '摩 西 对 亚 伦 和 他 剩 下 的 儿 子 以 利 亚 撒 、 以 他 玛 说 ： “ 你 们 献 给 耶 和 华 火 祭 中 所 剩 的 素 祭 ， 要 在 坛 旁 不 带 酵 而 吃 ， 因 为 是 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2991', '3', '10', '13', '你 们 要 在 圣 处 吃 ； 因 为 在 献 给 耶 和 华 的 火 祭 中 ， 这 是 你 的 分 和 你 儿 子 的 分 ； 所 吩 咐 我 的 本 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2992', '3', '10', '14', '所 摇 的 胸 ， 所 举 的 腿 ， 你 们 要 在 洁 净 地 方 吃 。 你 和 你 的 儿 女 都 要 同 吃 ； 因 为 这 些 是 从 以 色 列 人 平 安 祭 中 给 你 ， 当 你 的 分 和 你 儿 子 的 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2993', '3', '10', '15', '所 举 的 腿 ， 所 摇 的 胸 ， 他 们 要 与 火 祭 的 脂 油 一 同 带 来 当 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ； 这 要 归 你 和 你 儿 子 ， 当 作 永 得 的 分 ， 都 是 照 耶 和 华 所 吩 咐 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2994', '3', '10', '16', '当 下 摩 西 急 切 地 寻 找 作 赎 罪 祭 的 公 山 羊 ， 谁 知 已 经 焚 烧 了 ， 便 向 亚 伦 剩 下 的 儿 子 以 利 亚 撒 、 以 他 玛 发 怒 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2995', '3', '10', '17', '“ 这 赎 罪 祭 既 是 至 圣 的 ， 主 又 给 了 你 们 ， 为 要 你 们 担 当 会 众 的 罪 孽 ， 在 耶 和 华 面 前 为 他 们 赎 罪 ， 你 们 为 何 没 有 在 圣 所 吃 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2996', '3', '10', '18', '看 哪 ， 这 祭 牲 的 血 并 没 有 拿 到 圣 所 里 去 ， 你 们 本 当 照 我 所 吩 咐 的 ， 在 圣 所 里 吃 这 祭 肉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2997', '3', '10', '19', '亚 伦 对 摩 西 说 ： “ 今 天 他 们 在 耶 和 华 面 前 献 上 赎 罪 祭 和 燔 祭 ， 我 又 遇 见 这 样 的 灾 ， 若 今 天 吃 了 赎 罪 祭 ， 耶 和 华 岂 能 看 为 美 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2998', '3', '10', '20', '摩 西 听 见 这 话 ， 便 以 为 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('2999', '3', '11', '1', '＜ 有 关 食 物 的 条 例 （ 申   1 4 : 3 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3000', '3', '11', '2', '“ 你 们 晓 谕 以 色 列 人 说 ， 在 地 上 一 切 走 兽 中 可 吃 的 乃 是 这 些 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3001', '3', '11', '3', '凡 蹄 分 两 瓣 、 倒 嚼 的 走 兽 ， 你 们 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3002', '3', '11', '4', '但 那 倒 嚼 或 分 蹄 之 中 不 可 吃 的 乃 是 ： 骆 驼 ─ ─ 因 为 倒 嚼 不 分 蹄 ， 就 与 你 们 不 洁 净 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3003', '3', '11', '5', '沙 番 ─ ─ 因 为 倒 嚼 不 分 蹄 ， 就 与 你 们 不 洁 净 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3004', '3', '11', '6', '兔 子 ─ ─ 因 为 倒 嚼 不 分 蹄 ， 就 与 你 们 不 洁 净 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3005', '3', '11', '7', '猪 ─ ─ 因 为 蹄 分 两 瓣 ， 却 不 倒 嚼 ， 就 与 你 们 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3006', '3', '11', '8', '这 些 兽 的 肉 ， 你 们 不 可 吃 ； 死 的 ， 你 们 不 可 摸 ， 都 与 你 们 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3007', '3', '11', '9', '“ 水 中 可 吃 的 乃 是 这 些 ： 凡 在 水 里 、 海 里 、 河 里 、 有 翅 有 鳞 的 ， 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3008', '3', '11', '10', '凡 在 海 里 、 河 里 ， 并 一 切 水 里 游 动 的 活 物 ， 无 翅 无 鳞 的 ， 你 们 都 当 以 为 可 憎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3009', '3', '11', '11', '这 些 无 翅 无 鳞 、 以 为 可 憎 的 ， 你 们 不 可 吃 它 的 肉 ； 死 的 也 当 以 为 可 憎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3010', '3', '11', '12', '凡 水 里 无 翅 无 鳞 的 ， 你 们 都 当 以 为 可 憎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3011', '3', '11', '13', '“ 雀 鸟 中 你 们 当 以 为 可 憎 、 不 可 吃 的 乃 是 ： 雕 、 狗 头 雕 、 红 头 雕 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3012', '3', '11', '14', '鹞 鹰 、 小 鹰 与 其 类 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3013', '3', '11', '15', '乌 鸦 与 其 类 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3014', '3', '11', '16', '鸵 鸟 、 夜 鹰 、 鱼 鹰 、 鹰 与 其 类 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3015', '3', '11', '17', '鸮 鸟 、 鸬 鹚 、 猫 头 鹰 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3016', '3', '11', '18', '角 鸱 、 鹈 鹕 、 秃 雕 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3017', '3', '11', '19', '鹳 、 鹭 鸶 与 其 类 ； 戴 鵀 与 蝙 蝠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3018', '3', '11', '20', '“ 凡 有 翅 膀 用 四 足 爬 行 的 物 ， 你 们 都 当 以 为 可 憎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3019', '3', '11', '21', '只 是 有 翅 膀 用 四 足 爬 行 的 物 中 ， 有 足 有 腿 ， 在 地 上 蹦 跳 的 ， 你 们 还 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3020', '3', '11', '22', '其 中 有 蝗 虫 、 蚂 蚱 、 蟋 蟀 与 其 类 ； 蚱 蜢 与 其 类 ； 这 些 你 们 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3021', '3', '11', '23', '但 是 有 翅 膀 有 四 足 的 爬 物 ， 你 们 都 当 以 为 可 憎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3022', '3', '11', '24', '“ 这 些 都 能 使 你 们 不 洁 净 。 凡 摸 了 死 的 ， 必 不 洁 净 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3023', '3', '11', '25', '凡 拿 了 死 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3024', '3', '11', '26', '凡 走 兽 分 蹄 不 成 两 瓣 、 也 不 倒 嚼 的 ， 是 与 你 们 不 洁 净 ； 凡 摸 了 的 就 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3025', '3', '11', '27', '凡 四 足 的 走 兽 ， 用 掌 行 走 的 ， 是 与 你 们 不 洁 净 ； 摸 其 尸 的 ， 必 不 洁 净 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3026', '3', '11', '28', '拿 其 尸 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 。 这 些 是 与 你 们 不 洁 净 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3027', '3', '11', '29', '“ 地 上 爬 物 与 你 们 不 洁 净 的 乃 是 这 些 ： 鼬 鼠 、 鼫 鼠 、 蜥 蜴 与 其 类 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3028', '3', '11', '30', '壁 虎 、 龙 子 、 守 宫 、 蛇 医 、 蝘 蜓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3029', '3', '11', '31', '这 些 爬 物 都 是 与 你 们 不 洁 净 的 。 在 它 死 了 以 后 ， 凡 摸 了 的 ， 必 不 洁 净 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3030', '3', '11', '32', '其 中 死 了 的 ， 掉 在 什 么 东 西 上 ， 这 东 西 就 不 洁 净 ， 无 论 是 木 器 、 衣 服 、 皮 子 、 口 袋 ， 不 拘 是 做 什 么 工 用 的 器 皿 ， 须 要 放 在 水 中 ， 必 不 洁 净 到 晚 上 ， 到 晚 上 才 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3031', '3', '11', '33', '若 有 死 了 掉 在 瓦 器 里 的 ， 其 中 不 拘 有 什 么 ， 就 不 洁 净 ， 你 们 要 把 这 瓦 器 打 破 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3032', '3', '11', '34', '其 中 一 切 可 吃 的 食 物 ， 沾 水 的 就 不 洁 净 ， 并 且 那 样 器 皿 中 一 切 可 喝 的 ， 也 必 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3033', '3', '11', '35', '其 中 已 死 的 ， 若 有 一 点 掉 在 什 么 物 件 上 ， 那 物 件 就 不 洁 净 ， 不 拘 是 炉 子 ， 是 锅 台 ， 就 要 打 碎 ， 都 不 洁 净 ， 也 必 与 你 们 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3034', '3', '11', '36', '但 是 泉 源 或 是 聚 水 的 池 子 仍 是 洁 净 ； 惟 挨 了 那 死 的 ， 就 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3035', '3', '11', '37', '若 是 死 的 ， 有 一 点 掉 在 要 种 的 子 粒 上 ， 子 粒 仍 是 洁 净 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3036', '3', '11', '38', '若 水 已 经 浇 在 子 粒 上 ， 那 死 的 有 一 点 掉 在 上 头 ， 这 子 粒 就 与 你 们 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3037', '3', '11', '39', '“ 你 们 可 吃 的 走 兽 若 是 死 了 ， 有 人 摸 它 ， 必 不 洁 净 到 晚 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3038', '3', '11', '40', '有 人 吃 那 死 了 的 走 兽 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ； 拿 了 死 走 兽 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3039', '3', '11', '41', '“ 凡 地 上 的 爬 物 是 可 憎 的 ， 都 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3040', '3', '11', '42', '凡 用 肚 子 行 走 的 和 用 四 足 行 走 的 ， 或 是 有 许 多 足 的 ， 就 是 一 切 爬 在 地 上 的 ， 你 们 都 不 可 吃 ， 因 为 是 可 憎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3041', '3', '11', '43', '你 们 不 可 因 什 么 爬 物 使 自 己 成 为 可 憎 的 ， 也 不 可 因 这 些 使 自 己 不 洁 净 ， 以 致 染 了 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3042', '3', '11', '44', '我 是 耶 和 华 ─ ─ 你 们 的 神 ； 所 以 你 们 要 成 为 圣 洁 ， 因 为 我 是 圣 洁 的 。 你 们 也 不 可 在 地 上 的 爬 物 污 秽 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3043', '3', '11', '45', '我 是 把 你 们 从 埃 及 地 领 出 来 的 耶 和 华 ， 要 作 你 们 的 神 ； 所 以 你 们 要 圣 洁 ， 因 为 我 是 圣 洁 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3044', '3', '11', '46', '这 是 走 兽 、 飞 鸟 ， 和 水 中 游 动 的 活 物 ， 并 地 上 爬 物 的 条 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3045', '3', '11', '47', '要 把 洁 净 的 和 不 洁 净 的 ， 可 吃 的 与 不 可 吃 的 活 物 ， 都 分 别 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3046', '3', '12', '1', '＜ 产 妇 洁 净 礼 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3047', '3', '12', '2', '“ 你 晓 谕 以 色 列 人 说 ： 若 有 妇 人 怀 孕 生 男 孩 ， 她 就 不 洁 净 七 天 ， 像 在 月 经 污 秽 的 日 子 不 洁 净 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3048', '3', '12', '3', '第 八 天 ， 要 给 婴 孩 行 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3049', '3', '12', '4', '妇 人 在 产 血 不 洁 之 中 ， 要 家 居 三 十 三 天 。 她 洁 净 的 日 子 未 满 ， 不 可 摸 圣 物 ， 也 不 可 进 入 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3050', '3', '12', '5', '她 若 生 女 孩 ， 就 不 洁 净 两 个 七 天 ， 像 污 秽 的 时 候 一 样 ， 要 在 产 血 不 洁 之 中 ， 家 居 六 十 六 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3051', '3', '12', '6', '“ 满 了 洁 净 的 日 子 ， 无 论 是 为 男 孩 是 为 女 孩 ， 她 要 把 一 岁 的 羊 羔 为 燔 祭 ， 一 只 雏 鸽 或 是 一 只 斑 鸠 为 赎 罪 祭 ， 带 到 会 幕 门 口 交 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3052', '3', '12', '7', '祭 司 要 献 在 耶 和 华 面 前 ， 为 她 赎 罪 ， 她 的 血 源 就 洁 净 了 。 这 条 例 是 为 生 育 的 妇 人 ， 无 论 是 生 男 生 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3053', '3', '12', '8', '她 的 力 量 若 不 够 献 一 只 羊 羔 ， 她 就 要 取 两 只 斑 鸠 或 是 两 只 雏 鸽 ， 一 只 为 燔 祭 ， 一 只 为 赎 罪 祭 。 祭 司 要 为 她 赎 罪 ， 她 就 洁 净 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3054', '3', '13', '1', '＜ 有 关 皮 肤 病 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3055', '3', '13', '2', '“ 人 的 肉 皮 上 若 长 了 疖 子 ， 或 长 了 癣 ， 或 长 了 火 斑 ， 在 他 肉 皮 上 成 了 大 痲 疯 的 灾 病 ， 就 要 将 他 带 到 祭 司 亚 伦 或 亚 伦 作 祭 司 的 一 个 子 孙 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3056', '3', '13', '3', '祭 司 要 察 看 肉 皮 上 的 灾 病 ， 若 灾 病 处 的 毛 已 经 变 白 ， 灾 病 的 现 象 深 于 肉 上 的 皮 ， 这 便 是 大 痲 疯 的 灾 病 。 祭 司 要 察 看 他 ， 定 他 为 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3057', '3', '13', '4', '若 火 斑 在 他 肉 皮 上 是 白 的 ， 现 象 不 深 于 皮 ， 其 上 的 毛 也 没 有 变 白 ， 祭 司 就 要 将 有 灾 病 的 人 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3058', '3', '13', '5', '第 七 天 ， 祭 司 要 察 看 他 ， 若 看 灾 病 止 住 了 ， 没 有 在 皮 上 发 散 ， 祭 司 还 要 将 他 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3059', '3', '13', '6', '第 七 天 ， 祭 司 要 再 察 看 他 ， 若 灾 病 发 暗 ， 而 且 没 有 在 皮 上 发 散 ， 祭 司 要 定 他 为 洁 净 ， 原 来 是 癣 ； 那 人 就 要 洗 衣 服 ， 得 为 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3060', '3', '13', '7', '但 他 为 得 洁 净 ， 将 身 体 给 祭 司 察 看 以 后 ， 癣 若 在 皮 上 发 散 开 了 ， 他 要 再 将 身 体 给 祭 司 察 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3061', '3', '13', '8', '祭 司 要 察 看 ， 癣 若 在 皮 上 发 散 ， 就 要 定 他 为 不 洁 净 ， 是 大 痲 疯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3062', '3', '13', '9', '“ 人 有 了 大 痲 疯 的 灾 病 ， 就 要 将 他 带 到 祭 司 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3063', '3', '13', '10', '祭 司 要 察 看 ， 皮 上 若 长 了 白 疖 ， 使 毛 变 白 ， 在 长 白 疖 之 处 有 了 红 瘀 肉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3064', '3', '13', '11', '这 是 肉 皮 上 的 旧 大 痲 疯 ， 祭 司 要 定 他 为 不 洁 净 ， 不 用 将 他 关 锁 ， 因 为 他 是 不 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3065', '3', '13', '12', '大 痲 疯 若 在 皮 上 四 外 发 散 ， 长 满 了 患 灾 病 人 的 皮 ， 据 祭 司 察 看 ， 从 头 到 脚 无 处 不 有 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3066', '3', '13', '13', '祭 司 就 要 察 看 ， 全 身 的 肉 若 长 满 了 大 痲 疯 ， 就 要 定 那 患 灾 病 的 为 洁 净 ； 全 身 都 变 为 白 ， 他 乃 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3067', '3', '13', '14', '但 红 肉 几 时 显 在 他 的 身 上 就 几 时 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3068', '3', '13', '15', '祭 司 一 看 那 红 肉 就 定 他 为 不 洁 净 。 红 肉 本 是 不 洁 净 ， 是 大 痲 疯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3069', '3', '13', '16', '红 肉 若 复 原 ， 又 变 白 了 ， 他 就 要 来 见 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3070', '3', '13', '17', '祭 司 要 察 看 ， 灾 病 处 若 变 白 了 ， 祭 司 就 要 定 那 患 灾 病 的 为 洁 净 ， 他 乃 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3071', '3', '13', '18', '“ 人 若 在 皮 肉 上 长 疮 ， 却 治 好 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3072', '3', '13', '19', '在 长 疮 之 处 又 起 了 白 疖 ， 或 是 白 中 带 红 的 火 斑 ， 就 要 给 祭 司 察 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3073', '3', '13', '20', '祭 司 要 察 看 ， 若 现 象 洼 于 皮 ， 其 上 的 毛 也 变 白 了 ， 就 要 定 他 为 不 洁 净 ， 是 大 痲 疯 的 灾 病 发 在 疮 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3074', '3', '13', '21', '祭 司 若 察 看 ， 其 上 没 有 白 毛 ， 也 没 有 洼 于 皮 ， 乃 是 发 暗 ， 就 要 将 他 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3075', '3', '13', '22', '若 在 皮 上 发 散 开 了 ， 祭 司 就 要 定 他 为 不 洁 净 ， 是 灾 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3076', '3', '13', '23', '火 斑 若 在 原 处 止 住 ， 没 有 发 散 ， 便 是 疮 的 痕 迹 ， 祭 司 就 要 定 他 为 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3077', '3', '13', '24', '“ 人 的 皮 肉 上 若 起 了 火 毒 ， 火 毒 的 瘀 肉 成 了 火 斑 ， 或 是 白 中 带 红 的 ， 或 是 全 白 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3078', '3', '13', '25', '祭 司 就 要 察 看 ， 火 斑 中 的 毛 若 变 白 了 ， 现 象 又 深 于 皮 ， 是 大 痲 疯 在 火 毒 中 发 出 ， 就 要 定 他 为 不 洁 净 ， 是 大 痲 疯 的 灾 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3079', '3', '13', '26', '但 是 祭 司 察 看 ， 在 火 斑 中 若 没 有 白 毛 ， 也 没 有 洼 于 皮 ， 乃 是 发 暗 ， 就 要 将 他 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3080', '3', '13', '27', '到 第 七 天 ， 祭 司 要 察 看 他 ， 火 斑 若 在 皮 上 发 散 开 了 ， 就 要 定 他 为 不 洁 净 ， 是 大 痲 疯 的 灾 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3081', '3', '13', '28', '火 斑 若 在 原 处 止 住 ， 没 有 在 皮 上 发 散 ， 乃 是 发 暗 ， 是 起 的 火 毒 ， 祭 司 要 定 他 为 洁 净 ， 不 过 是 火 毒 的 痕 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3082', '3', '13', '29', '“ 无 论 男 女 ， 若 在 头 上 有 灾 病 ， 或 是 男 人 胡 须 上 有 灾 病 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3083', '3', '13', '30', '祭 司 就 要 察 看 ； 这 灾 病 现 象 若 深 于 皮 ， 其 间 有 细 黄 毛 ， 就 要 定 他 为 不 洁 净 ， 这 是 头 疥 ， 是 头 上 或 是 胡 须 上 的 大 痲 疯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3084', '3', '13', '31', '祭 司 若 察 看 头 疥 的 灾 病 ， 现 象 不 深 于 皮 ， 其 间 也 没 有 黑 毛 ， 就 要 将 长 头 疥 灾 病 的 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3085', '3', '13', '32', '第 七 天 ， 祭 司 要 察 看 灾 病 ， 若 头 疥 没 有 发 散 ， 其 间 也 没 有 黄 毛 ， 头 疥 的 现 象 不 深 于 皮 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3086', '3', '13', '33', '那 人 就 要 剃 去 须 发 ， 但 他 不 可 剃 头 疥 之 处 。 祭 司 要 将 那 长 头 疥 的 ， 再 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3087', '3', '13', '34', '第 七 天 ， 祭 司 要 察 看 头 疥 ， 头 疥 若 没 有 在 皮 上 发 散 ， 现 象 也 不 深 于 皮 ， 就 要 定 他 为 洁 净 ， 他 要 洗 衣 服 ， 便 成 为 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3088', '3', '13', '35', '但 他 得 洁 净 以 后 ， 头 疥 若 在 皮 上 发 散 开 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3089', '3', '13', '36', '祭 司 就 要 察 看 他 。 头 疥 若 在 皮 上 发 散 ， 就 不 必 找 那 黄 毛 ， 他 是 不 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3090', '3', '13', '37', '祭 司 若 看 头 疥 已 经 止 住 ， 其 间 也 长 了 黑 毛 ， 头 疥 已 然 痊 愈 ， 那 人 是 洁 净 了 ， 就 要 定 他 为 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3091', '3', '13', '38', '“ 无 论 男 女 ， 皮 肉 上 若 起 了 火 斑 ， 就 是 白 火 斑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3092', '3', '13', '39', '祭 司 就 要 察 看 ， 他 们 肉 皮 上 的 火 斑 若 白 中 带 黑 ， 这 是 皮 上 发 出 的 白 癣 ， 那 人 是 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3093', '3', '13', '40', '“ 人 头 上 的 发 若 掉 了 ， 他 不 过 是 头 秃 ， 还 是 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3094', '3', '13', '41', '他 顶 前 若 掉 了 头 发 ， 他 不 过 是 顶 门 秃 ， 还 是 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3095', '3', '13', '42', '头 秃 处 或 是 顶 门 秃 处 若 有 白 中 带 红 的 灾 病 ， 这 就 是 大 痲 疯 发 在 他 头 秃 处 或 是 顶 门 秃 处 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3096', '3', '13', '43', '祭 司 就 要 察 看 ， 他 起 的 那 灾 病 若 在 头 秃 处 或 是 顶 门 秃 处 有 白 中 带 红 的 ， 像 肉 皮 上 大 痲 疯 的 现 象 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3097', '3', '13', '44', '那 人 就 是 长 大 痲 疯 ， 不 洁 净 的 ， 祭 司 总 要 定 他 为 不 洁 净 ， 他 的 灾 病 是 在 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3098', '3', '13', '45', '“ 身 上 有 长 大 痲 疯 灾 病 的 ， 他 的 衣 服 要 撕 裂 ， 也 要 蓬 头 散 发 ， 蒙 着 上 唇 ， 喊 叫 说 ： ‘ 不 洁 净 了 ！ 不 洁 净 了 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3099', '3', '13', '46', '灾 病 在 他 身 上 的 日 子 ， 他 便 是 不 洁 净 ； 他 既 是 不 洁 净 ， 就 要 独 居 营 外 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3100', '3', '13', '47', '＜ 衣 物 发 霉 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3101', '3', '13', '48', '无 论 是 在 经 上 、 在 纬 上 ， 是 麻 布 的 、 是 羊 毛 的 ， 是 在 皮 子 上 ， 或 在 皮 子 做 的 什 么 物 件 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3102', '3', '13', '49', '或 在 衣 服 上 、 皮 子 上 ， 经 上 、 纬 上 ， 或 在 皮 子 做 的 什 么 物 件 上 ， 这 灾 病 若 是 发 绿 ， 或 是 发 红 ， 是 大 痲 疯 的 灾 病 ， 要 给 祭 司 察 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3103', '3', '13', '50', '祭 司 就 要 察 看 那 灾 病 ， 把 染 了 灾 病 的 物 件 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3104', '3', '13', '51', '第 七 天 ， 他 要 察 看 那 灾 病 ， 灾 病 或 在 衣 服 上 ， 经 上 、 纬 上 ， 皮 子 上 ， 若 发 散 ， 这 皮 子 无 论 当 作 何 用 ， 这 灾 病 是 蚕 食 的 大 痲 疯 ， 都 是 不 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3105', '3', '13', '52', '那 染 了 灾 病 的 衣 服 ， 或 是 经 上 、 纬 上 ， 羊 毛 上 ， 麻 衣 上 ， 或 是 皮 子 做 的 什 么 物 件 上 ， 他 都 要 焚 烧 ； 因 为 这 是 蚕 食 的 大 痲 疯 ， 必 在 火 中 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3106', '3', '13', '53', '“ 祭 司 要 察 看 ， 若 灾 病 在 衣 服 上 ， 经 上 、 纬 上 ， 或 是 皮 子 做 的 什 么 物 件 上 ， 没 有 发 散 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3107', '3', '13', '54', '祭 司 就 要 吩 咐 他 们 ， 把 染 了 灾 病 的 物 件 洗 了 ， 再 关 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3108', '3', '13', '55', '洗 过 以 后 ， 祭 司 要 察 看 ， 那 物 件 若 没 有 变 色 ， 灾 病 也 没 有 消 散 ， 那 物 件 就 不 洁 净 ， 是 透 重 的 灾 病 ， 无 论 正 面 反 面 ， 都 要 在 火 中 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3109', '3', '13', '56', '洗 过 以 后 ， 祭 司 要 察 看 ， 若 见 那 灾 病 发 暗 ， 他 就 要 把 那 灾 病 从 衣 服 上 、 皮 子 上 、 经 上 、 纬 上 ， 都 撕 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3110', '3', '13', '57', '若 仍 现 在 衣 服 上 ， 或 是 经 上 、 纬 上 、 皮 子 做 的 什 么 物 件 上 ， 这 就 是 灾 病 又 发 了 、 必 用 火 焚 烧 那 染 灾 病 的 物 件 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3111', '3', '13', '58', '所 洗 的 衣 服 ， 或 是 经 ， 或 是 纬 ， 或 是 皮 子 做 的 什 么 物 件 ， 若 灾 病 离 开 了 ， 要 再 洗 ， 就 洁 净 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3112', '3', '13', '59', '这 就 是 大 痲 疯 灾 病 的 条 例 ， 无 论 是 在 羊 毛 衣 服 上 ， 麻 布 衣 服 上 ， 经 上 、 纬 上 ， 和 皮 子 做 的 什 么 物 件 上 ， 可 以 定 为 洁 净 或 是 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3113', '3', '14', '1', '＜ 皮 肤 病 后 洁 净 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3114', '3', '14', '2', '“ 长 大 痲 疯 得 洁 净 的 日 子 ， 其 例 乃 是 这 样 ： 要 带 他 去 见 祭 司 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3115', '3', '14', '3', '祭 司 要 出 到 营 外 察 看 ， 若 见 他 的 大 痲 疯 痊 愈 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3116', '3', '14', '4', '就 要 吩 咐 人 为 那 求 洁 净 的 拿 两 只 洁 净 的 活 鸟 和 香 柏 木 、 朱 红 色 线 ， 并 牛 膝 草 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3117', '3', '14', '5', '祭 司 要 吩 咐 用 瓦 器 盛 活 水 ， 把 一 只 鸟 宰 在 上 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3118', '3', '14', '6', '至 于 那 只 活 鸟 ， 祭 司 要 把 它 和 香 柏 木 、 朱 红 色 线 并 牛 膝 草 一 同 蘸 于 宰 在 活 水 上 的 鸟 血 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3119', '3', '14', '7', '用 以 在 那 长 大 痲 疯 求 洁 净 的 人 身 上 洒 七 次 ， 就 定 他 为 洁 净 ， 又 把 活 鸟 放 在 田 野 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3120', '3', '14', '8', '求 洁 净 的 人 当 洗 衣 服 ， 剃 去 毛 发 ， 用 水 洗 澡 ， 就 洁 净 了 ； 然 后 可 以 进 营 ， 只 是 要 在 自 己 的 帐 棚 外 居 住 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3121', '3', '14', '9', '第 七 天 ， 再 把 头 上 所 有 的 头 发 与 胡 须 、 眉 毛 ， 并 全 身 的 毛 ， 都 剃 了 ； 又 要 洗 衣 服 ， 用 水 洗 身 ， 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3122', '3', '14', '10', '“ 第 八 天 ， 他 要 取 两 只 没 有 残 疾 的 公 羊 羔 和 一 只 没 有 残 疾 、 一 岁 的 母 羊 羔 ， 又 要 把 调 油 的 细 面 伊 法 十 分 之 三 为 素 祭 ， 并 油 一 罗 革 ， 一 同 取 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3123', '3', '14', '11', '行 洁 净 之 礼 的 祭 司 要 将 那 求 洁 净 的 人 和 这 些 东 西 安 置 在 会 幕 门 口 、 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3124', '3', '14', '12', '祭 司 要 取 一 只 公 羊 羔 献 为 赎 愆 祭 ， 和 那 一 罗 革 油 一 同 作 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3125', '3', '14', '13', '把 公 羊 羔 宰 于 圣 地 ， 就 是 宰 赎 罪 祭 牲 和 燔 祭 牲 之 地 。 赎 愆 祭 要 归 祭 司 ， 与 赎 罪 祭 一 样 ， 是 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3126', '3', '14', '14', '祭 司 要 取 些 赎 愆 祭 牲 的 血 ， 抹 在 求 洁 净 人 的 右 耳 垂 上 和 右 手 的 大 拇 指 上 ， 并 右 脚 的 大 拇 指 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3127', '3', '14', '15', '祭 司 要 从 那 一 罗 革 油 中 取 些 倒 在 自 己 的 左 手 掌 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3128', '3', '14', '16', '把 右 手 的 一 个 指 头 蘸 在 左 手 的 油 里 ， 在 耶 和 华 面 前 用 指 头 弹 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3129', '3', '14', '17', '将 手 里 所 剩 的 油 抹 在 那 求 洁 净 人 的 右 耳 垂 上 和 右 手 的 大 拇 指 上 ， 并 右 脚 的 大 拇 指 上 ， 就 是 抹 在 赎 愆 祭 牲 的 血 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3130', '3', '14', '18', '祭 司 手 里 所 剩 的 油 要 抹 在 那 求 洁 净 人 的 头 上 ， 在 耶 和 华 面 前 为 他 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3131', '3', '14', '19', '祭 司 要 献 赎 罪 祭 ， 为 那 本 不 洁 净 、 求 洁 净 的 人 赎 罪 ； 然 后 要 宰 燔 祭 牲 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3132', '3', '14', '20', '把 燔 祭 和 素 祭 献 在 坛 上 ， 为 他 赎 罪 ， 他 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3133', '3', '14', '21', '“ 他 若 贫 穷 不 能 预 备 够 数 ， 就 要 取 一 只 公 羊 羔 作 赎 愆 祭 ， 可 以 摇 一 摇 ， 为 他 赎 罪 ； 也 要 把 调 油 的 细 面 伊 法 十 分 之 一 为 素 祭 ， 和 油 一 罗 革 一 同 取 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3134', '3', '14', '22', '又 照 他 的 力 量 取 两 只 斑 鸠 或 是 两 只 雏 鸽 ， 一 只 作 赎 罪 祭 ， 一 只 作 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3135', '3', '14', '23', '第 八 天 ， 要 为 洁 净 ， 把 这 些 带 到 会 幕 门 口 、 耶 和 华 面 前 ， 交 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3136', '3', '14', '24', '祭 司 要 把 赎 愆 祭 的 羊 羔 和 那 一 罗 革 油 一 同 作 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3137', '3', '14', '25', '要 宰 了 赎 愆 祭 的 羊 羔 ， 取 些 赎 愆 祭 牲 的 血 ， 抹 在 那 求 洁 净 人 的 右 耳 垂 上 和 右 手 的 大 拇 指 上 ， 并 右 脚 的 大 拇 指 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3138', '3', '14', '26', '祭 司 要 把 些 油 倒 在 自 己 的 左 手 掌 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3139', '3', '14', '27', '把 左 手 里 的 油 ， 在 耶 和 华 面 前 ， 用 右 手 的 一 个 指 头 弹 七 次 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3140', '3', '14', '28', '又 把 手 里 的 油 抹 些 在 那 求 洁 净 人 的 右 耳 垂 上 和 右 手 的 大 拇 指 上 ， 并 右 脚 的 大 拇 指 上 ， 就 是 抹 赎 愆 祭 之 血 的 原 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3141', '3', '14', '29', '祭 司 手 里 所 剩 的 油 要 抹 在 那 求 洁 净 人 的 头 上 ， 在 耶 和 华 面 前 为 他 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3142', '3', '14', '30', '那 人 又 要 照 他 的 力 量 献 上 一 只 斑 鸠 或 是 一 只 雏 鸽 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3143', '3', '14', '31', '就 是 他 所 能 办 的 ， 一 只 为 赎 罪 祭 ， 一 只 为 燔 祭 ， 与 素 祭 一 同 献 上 ； 祭 司 要 在 耶 和 华 面 前 为 他 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3144', '3', '14', '32', '这 是 那 有 大 痲 疯 灾 病 的 人 、 不 能 将 关 乎 得 洁 净 之 物 预 备 够 数 的 条 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3145', '3', '14', '33', '＜ 处 理 房 屋 发 霉 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3146', '3', '14', '34', '“ 你 们 到 了 我 赐 给 你 们 为 业 的 迦 南 地 ， 我 若 使 你 们 所 得 为 业 之 地 的 房 屋 中 有 大 痲 疯 的 灾 病 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3147', '3', '14', '35', '房 主 就 要 去 告 诉 祭 司 说 ： ‘ 据 我 看 ， 房 屋 中 似 乎 有 灾 病 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3148', '3', '14', '36', '祭 司 还 没 有 进 去 察 看 灾 病 以 前 ， 就 要 吩 咐 人 把 房 子 腾 空 ， 免 得 房 子 里 所 有 的 都 成 了 不 洁 净 ； 然 后 祭 司 要 进 去 察 看 房 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3149', '3', '14', '37', '他 要 察 看 那 灾 病 ， 灾 病 若 在 房 子 的 墙 上 有 发 绿 或 发 红 的 凹 斑 纹 ， 现 象 洼 于 墙 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3150', '3', '14', '38', '祭 司 就 要 出 到 房 门 外 ， 把 房 子 封 锁 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3151', '3', '14', '39', '第 七 天 ， 祭 司 要 再 去 察 看 ， 灾 病 若 在 房 子 的 墙 上 发 散 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3152', '3', '14', '40', '就 要 吩 咐 人 把 那 有 灾 病 的 石 头 挖 出 来 ， 扔 在 城 外 不 洁 净 之 处 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3153', '3', '14', '41', '也 要 叫 人 刮 房 内 的 四 围 ， 所 刮 掉 的 灰 泥 要 倒 在 城 外 不 洁 净 之 处 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3154', '3', '14', '42', '又 要 用 别 的 石 头 代 替 那 挖 出 来 的 石 头 ， 要 另 用 灰 泥 墁 房 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3155', '3', '14', '43', '“ 他 挖 出 石 头 ， 刮 了 房 子 ， 墁 了 以 后 ， 灾 病 若 在 房 子 里 又 发 现 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3156', '3', '14', '44', '祭 司 就 要 进 去 察 看 ， 灾 病 若 在 房 子 里 发 散 ， 这 就 是 房 内 蚕 食 的 大 痲 疯 ， 是 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3157', '3', '14', '45', '他 就 要 拆 毁 房 子 ， 把 石 头 、 木 头 、 灰 泥 都 搬 到 城 外 不 洁 净 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3158', '3', '14', '46', '在 房 子 封 锁 的 时 候 ， 进 去 的 人 必 不 洁 净 到 晚 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3159', '3', '14', '47', '在 房 子 里 躺 着 的 必 洗 衣 服 ； 在 房 子 里 吃 饭 的 也 必 洗 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3160', '3', '14', '48', '“ 房 子 墁 了 以 后 ， 祭 司 若 进 去 察 看 ， 见 灾 病 在 房 内 没 有 发 散 ， 就 要 定 房 子 为 洁 净 ， 因 为 灾 病 已 经 消 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3161', '3', '14', '49', '要 为 洁 净 房 子 取 两 只 鸟 和 香 柏 木 、 朱 红 色 线 并 牛 膝 草 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3162', '3', '14', '50', '用 瓦 器 盛 活 水 ， 把 一 只 鸟 宰 在 上 面 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3163', '3', '14', '51', '把 香 柏 木 、 牛 膝 草 、 朱 红 色 线 ， 并 那 活 鸟 ， 都 蘸 在 被 宰 的 鸟 血 中 与 活 水 中 ， 用 以 洒 房 子 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3164', '3', '14', '52', '要 用 鸟 血 、 活 水 、 活 鸟 、 香 柏 木 、 牛 膝 草 ， 并 朱 红 色 线 ， 洁 净 那 房 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3165', '3', '14', '53', '但 要 把 活 鸟 放 在 城 外 田 野 里 。 这 样 洁 净 房 子 ｛ 原 文 是 为 房 子 赎 罪 ｝ ， 房 子 就 洁 净 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3166', '3', '14', '54', '这 是 为 各 类 大 痲 疯 的 灾 病 和 头 疥 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3167', '3', '14', '55', '并 衣 服 与 房 子 的 大 痲 疯 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3168', '3', '14', '56', '以 及 疖 子 、 癣 、 火 斑 所 立 的 条 例 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3169', '3', '14', '57', '指 明 何 时 为 洁 净 ， 何 时 为 不 洁 净 。 这 是 大 痲 疯 的 条 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3170', '3', '15', '1', '＜ 漏 症 患 者 洁 净 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3171', '3', '15', '2', '“ 你 们 晓 谕 以 色 列 人 说 ： 人 若 身 患 漏 症 ， 他 因 这 漏 症 就 不 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3172', '3', '15', '3', '他 患 漏 症 ， 无 论 是 下 流 的 ， 是 止 住 的 ， 都 是 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3173', '3', '15', '4', '他 所 躺 的 床 都 为 不 洁 净 ， 所 坐 的 物 也 为 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3174', '3', '15', '5', '凡 摸 那 床 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3175', '3', '15', '6', '那 坐 患 漏 症 人 所 坐 之 物 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3176', '3', '15', '7', '那 摸 患 漏 症 人 身 体 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3177', '3', '15', '8', '若 患 漏 症 人 吐 在 洁 净 的 人 身 上 ， 那 人 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3178', '3', '15', '9', '患 漏 症 人 所 骑 的 鞍 子 也 为 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3179', '3', '15', '10', '凡 摸 了 他 身 下 之 物 的 ， 必 不 洁 净 到 晚 上 ； 拿 了 那 物 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3180', '3', '15', '11', '患 漏 症 的 人 没 有 用 水 涮 手 ， 无 论 摸 了 谁 ， 谁 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3181', '3', '15', '12', '患 漏 症 人 所 摸 的 瓦 器 就 必 打 破 ； 所 摸 的 一 切 木 器 也 必 用 水 涮 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3182', '3', '15', '13', '“ 患 漏 症 的 人 痊 愈 了 ， 就 要 为 洁 净 自 己 计 算 七 天 ， 也 必 洗 衣 服 ， 用 活 水 洗 身 ， 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3183', '3', '15', '14', '第 八 天 ， 要 取 两 只 斑 鸠 或 是 两 只 雏 鸽 ， 来 到 会 幕 门 口 、 耶 和 华 面 前 ， 把 鸟 交 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3184', '3', '15', '15', '祭 司 要 献 上 一 只 为 赎 罪 祭 ， 一 只 为 燔 祭 ； 因 那 人 患 的 漏 症 ， 祭 司 要 在 耶 和 华 面 前 为 他 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3185', '3', '15', '16', '“ 人 若 梦 遗 ， 他 必 不 洁 净 到 晚 上 ， 并 要 用 水 洗 全 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3186', '3', '15', '17', '无 论 是 衣 服 是 皮 子 ， 被 精 所 染 ， 必 不 洁 净 到 晚 上 ， 并 要 用 水 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3187', '3', '15', '18', '若 男 女 交 合 ， 两 个 人 必 不 洁 净 到 晚 上 ， 并 要 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3188', '3', '15', '19', '“ 女 人 行 经 ， 必 污 秽 七 天 ； 凡 摸 她 的 ， 必 不 洁 净 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3189', '3', '15', '20', '女 人 在 污 秽 之 中 ， 凡 她 所 躺 的 物 件 都 为 不 洁 净 ， 所 坐 的 物 件 也 都 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3190', '3', '15', '21', '凡 摸 她 床 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3191', '3', '15', '22', '凡 摸 她 所 坐 什 么 物 件 的 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3192', '3', '15', '23', '在 女 人 的 床 上 ， 或 在 她 坐 的 物 上 ， 若 有 别 的 物 件 ， 人 一 摸 了 ， 必 不 洁 净 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3193', '3', '15', '24', '男 人 若 与 那 女 人 同 房 ， 染 了 她 的 污 秽 ， 就 要 七 天 不 洁 净 ； 所 躺 的 床 也 为 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3194', '3', '15', '25', '“ 女 人 若 在 经 期 以 外 患 多 日 的 血 漏 ， 或 是 经 期 过 长 ， 有 了 漏 症 ， 她 就 因 这 漏 症 不 洁 净 ， 与 她 在 经 期 不 洁 净 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3195', '3', '15', '26', '她 在 患 漏 症 的 日 子 所 躺 的 床 、 所 坐 的 物 都 要 看 为 不 洁 净 ， 与 她 月 经 的 时 候 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3196', '3', '15', '27', '凡 摸 这 些 物 件 的 ， 就 为 不 洁 净 ， 必 不 洁 净 到 晚 上 ， 并 要 洗 衣 服 ， 用 水 洗 澡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3197', '3', '15', '28', '女 人 的 漏 症 若 好 了 ， 就 要 计 算 七 天 ， 然 后 才 为 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3198', '3', '15', '29', '第 八 天 ， 要 取 两 只 斑 鸠 或 是 两 只 雏 鸽 ， 带 到 会 幕 门 口 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3199', '3', '15', '30', '祭 司 要 献 一 只 为 赎 罪 祭 ， 一 只 为 燔 祭 ； 因 那 人 血 漏 不 洁 ， 祭 司 要 在 耶 和 华 面 前 为 她 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3200', '3', '15', '31', '“ 你 们 要 这 样 使 以 色 列 人 与 他 们 的 污 秽 隔 绝 ， 免 得 他 们 玷 污 我 的 帐 幕 ， 就 因 自 己 的 污 秽 死 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3201', '3', '15', '32', '这 是 患 漏 症 和 梦 遗 而 不 洁 净 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3202', '3', '15', '33', '并 有 月 经 病 的 和 患 漏 症 的 ， 无 论 男 女 ， 并 人 与 不 洁 净 女 人 同 房 的 条 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3203', '3', '16', '1', '＜ 赎 罪 日 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3204', '3', '16', '2', '“ 要 告 诉 你 哥 哥 亚 伦 ， 不 可 随 时 进 圣 所 的 幔 子 内 、 到 柜 上 的 施 恩 座 前 ， 免 得 他 死 亡 ， 因 为 我 要 从 云 中 显 现 在 施 恩 座 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3205', '3', '16', '3', '亚 伦 进 圣 所 ， 要 带 一 只 公 牛 犊 为 赎 罪 祭 ， 一 只 公 绵 羊 为 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3206', '3', '16', '4', '要 穿 上 细 麻 布 圣 内 袍 ， 把 细 麻 布 裤 子 穿 在 身 上 ， 腰 束 细 麻 布 带 子 ， 头 戴 细 麻 布 冠 冕 ； 这 都 是 圣 服 。 他 要 用 水 洗 身 ， 然 后 穿 戴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3207', '3', '16', '5', '要 从 以 色 列 会 众 取 两 只 公 山 羊 为 赎 罪 祭 ， 一 只 公 绵 羊 为 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3208', '3', '16', '6', '“ 亚 伦 要 把 赎 罪 祭 的 公 牛 奉 上 ， 为 自 己 和 本 家 赎 罪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3209', '3', '16', '7', '也 要 把 两 只 公 山 羊 安 置 在 会 幕 门 口 、 耶 和 华 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3210', '3', '16', '8', '为 那 两 只 羊 拈 阄 ， 一 阄 归 与 耶 和 华 ， 一 阄 归 与 阿 撒 泻 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3211', '3', '16', '9', '亚 伦 要 把 那 拈 阄 归 与 耶 和 华 的 羊 献 为 赎 罪 祭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3212', '3', '16', '10', '但 那 拈 阄 归 与 阿 撒 泻 勒 的 羊 要 活 着 安 置 在 耶 和 华 面 前 ， 用 以 赎 罪 ， 打 发 人 送 到 旷 野 去 ， 归 与 阿 撒 泻 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3213', '3', '16', '11', '“ 亚 伦 要 把 赎 罪 祭 的 公 牛 牵 来 宰 了 ， 为 自 己 和 本 家 赎 罪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3214', '3', '16', '12', '拿 香 炉 ， 从 耶 和 华 面 前 的 坛 上 盛 满 火 炭 ， 又 拿 一 捧 捣 细 的 香 料 ， 都 带 入 幔 子 内 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3215', '3', '16', '13', '在 耶 和 华 面 前 ， 把 香 放 在 火 上 ， 使 香 的 烟 云 遮 掩 法 柜 上 的 施 恩 座 ， 免 得 他 死 亡 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3216', '3', '16', '14', '也 要 取 些 公 牛 的 血 ， 用 指 头 弹 在 施 恩 座 的 东 面 ， 又 在 施 恩 座 的 前 面 弹 血 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3217', '3', '16', '15', '“ 随 后 他 要 宰 那 为 百 姓 作 赎 罪 祭 的 公 山 羊 ， 把 羊 的 血 带 入 幔 子 内 ， 弹 在 施 恩 座 的 上 面 和 前 面 ， 好 像 弹 公 牛 的 血 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3218', '3', '16', '16', '他 因 以 色 列 人 诸 般 的 污 秽 、 过 犯 ， 就 是 他 们 一 切 的 罪 愆 ， 当 这 样 在 圣 所 行 赎 罪 之 礼 ， 并 因 会 幕 在 他 们 污 秽 之 中 ， 也 要 照 样 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3219', '3', '16', '17', '他 进 圣 所 赎 罪 的 时 候 ， 会 幕 里 不 可 有 人 ， 直 等 到 他 为 自 己 和 本 家 并 以 色 列 全 会 众 赎 了 罪 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3220', '3', '16', '18', '他 出 来 ， 要 到 耶 和 华 面 前 的 坛 那 里 ， 在 坛 上 行 赎 罪 之 礼 ， 又 要 取 些 公 牛 的 血 和 公 山 羊 的 血 ， 抹 在 坛 上 四 角 的 周 围 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3221', '3', '16', '19', '也 要 用 指 头 把 血 弹 在 坛 上 七 次 ， 洁 净 了 坛 ， 从 坛 上 除 掉 以 色 列 人 诸 般 的 污 秽 ， 使 坛 成 圣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3222', '3', '16', '20', '＜ 代 罪 羊 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3223', '3', '16', '21', '两 手 按 在 羊 头 上 ， 承 认 以 色 列 人 诸 般 的 罪 孽 过 犯 ， 就 是 他 们 一 切 的 罪 愆 ， 把 这 罪 都 归 在 羊 的 头 上 ， 藉 着 所 派 之 人 的 手 ， 送 到 旷 野 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3224', '3', '16', '22', '要 把 这 羊 放 在 旷 野 ， 这 羊 要 担 当 他 们 一 切 的 罪 孽 ， 带 到 无 人 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3225', '3', '16', '23', '“ 亚 伦 要 进 会 幕 ， 把 他 进 圣 所 时 所 穿 的 细 麻 布 衣 服 脱 下 ， 放 在 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3226', '3', '16', '24', '又 要 在 圣 处 用 水 洗 身 ， 穿 上 衣 服 ， 出 来 ， 把 自 己 的 燔 祭 和 百 姓 的 燔 祭 献 上 ， 为 自 己 和 百 姓 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3227', '3', '16', '25', '赎 罪 祭 牲 的 脂 油 要 在 坛 上 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3228', '3', '16', '26', '那 放 羊 归 与 阿 撒 泻 勒 的 人 要 洗 衣 服 ， 用 水 洗 身 ， 然 后 进 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3229', '3', '16', '27', '作 赎 罪 祭 的 公 牛 和 公 山 羊 的 血 既 带 入 圣 所 赎 罪 ， 这 牛 羊 就 要 搬 到 营 外 ， 将 皮 、 肉 、 粪 用 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3230', '3', '16', '28', '焚 烧 的 人 要 洗 衣 服 ， 用 水 洗 身 ， 然 后 进 营 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3231', '3', '16', '29', '＜ 守 赎 罪 日 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3232', '3', '16', '30', '因 在 这 日 要 为 你 们 赎 罪 ， 使 你 们 洁 净 。 你 们 要 在 耶 和 华 面 前 得 以 洁 净 ， 脱 尽 一 切 的 罪 愆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3233', '3', '16', '31', '这 日 你 们 要 守 为 圣 安 息 日 ， 要 刻 苦 己 心 ； 这 为 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3234', '3', '16', '32', '那 受 膏 、 接 续 他 父 亲 承 接 圣 职 的 祭 司 要 穿 上 细 麻 布 的 圣 衣 ， 行 赎 罪 之 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3235', '3', '16', '33', '他 要 在 至 圣 所 和 会 幕 与 坛 行 赎 罪 之 礼 ， 并 要 为 众 祭 司 和 会 众 的 百 姓 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3236', '3', '16', '34', '这 要 作 你 们 永 远 的 定 例 ─ ─ 就 是 因 以 色 列 人 一 切 的 罪 ， 要 一 年 一 次 为 他 们 赎 罪 。 ” 于 是 ， 亚 伦 照 耶 和 华 所 吩 咐 摩 西 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3237', '3', '17', '1', '＜ 血 的 神 圣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3238', '3', '17', '2', '“ 你 晓 谕 亚 伦 和 他 儿 子 并 以 色 列 众 人 说 ， 耶 和 华 所 吩 咐 的 乃 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3239', '3', '17', '3', '凡 以 色 列 家 中 的 人 宰 公 牛 ， 或 是 绵 羊 羔 ， 或 是 山 羊 ， 不 拘 宰 于 营 内 营 外 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3240', '3', '17', '4', '若 未 曾 牵 到 会 幕 门 口 、 耶 和 华 的 帐 幕 前 献 给 耶 和 华 为 供 物 ， 流 血 的 罪 必 归 到 那 人 身 上 。 他 流 了 血 ， 要 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3241', '3', '17', '5', '这 是 为 要 使 以 色 列 人 把 他 们 在 田 野 里 所 献 的 祭 带 到 会 幕 门 口 、 耶 和 华 面 前 ， 交 给 祭 司 ， 献 与 耶 和 华 为 平 安 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3242', '3', '17', '6', '祭 司 要 把 血 洒 在 会 幕 门 口 、 耶 和 华 的 坛 上 ， 把 脂 油 焚 烧 ， 献 给 耶 和 华 为 馨 香 的 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3243', '3', '17', '7', '他 们 不 可 再 献 祭 给 他 们 行 邪 淫 所 随 从 的 鬼 魔 ｛ 原 文 是 公 山 羊 ｝ ； 这 要 作 他 们 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3244', '3', '17', '8', '“ 你 要 晓 谕 他 们 说 ： 凡 以 色 列 家 中 的 人 ， 或 是 寄 居 在 他 们 中 间 的 外 人 ， 献 燔 祭 或 是 平 安 祭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3245', '3', '17', '9', '若 不 带 到 会 幕 门 口 献 给 耶 和 华 ， 那 人 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3246', '3', '17', '10', '“ 凡 以 色 列 家 中 的 人 ， 或 是 寄 居 在 他 们 中 间 的 外 人 ， 若 吃 什 么 血 ， 我 必 向 那 吃 血 的 人 变 脸 ， 把 他 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3247', '3', '17', '11', '因 为 活 物 的 生 命 是 在 血 中 。 我 把 这 血 赐 给 你 们 ， 可 以 在 坛 上 为 你 们 的 生 命 赎 罪 ； 因 血 里 有 生 命 ， 所 以 能 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3248', '3', '17', '12', '因 此 ， 我 对 以 色 列 人 说 ： 你 们 都 不 可 吃 血 ； 寄 居 在 你 们 中 间 的 外 人 也 不 可 吃 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3249', '3', '17', '13', '凡 以 色 列 人 ， 或 是 寄 居 在 他 们 中 间 的 外 人 ， 若 打 猎 得 了 可 吃 的 禽 兽 ， 必 放 出 它 的 血 来 ， 用 土 掩 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3250', '3', '17', '14', '“ 论 到 一 切 活 物 的 生 命 ， 就 在 血 中 。 所 以 我 对 以 色 列 人 说 ： 无 论 什 么 活 物 的 血 ， 你 们 都 不 可 吃 ， 因 为 一 切 活 物 的 血 就 是 他 的 生 命 。 凡 吃 了 血 的 ， 必 被 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3251', '3', '17', '15', '凡 吃 自 死 的 ， 或 是 被 野 兽 撕 裂 的 ， 无 论 是 本 地 人 ， 是 寄 居 的 ， 必 不 洁 净 到 晚 上 ， 都 要 洗 衣 服 ， 用 水 洗 身 ， 到 了 晚 上 才 为 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3252', '3', '17', '16', '但 他 若 不 洗 衣 服 ， 也 不 洗 身 ， 就 必 担 当 他 的 罪 孽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3253', '3', '18', '1', '＜ 有 关 淫 乱 的 禁 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3254', '3', '18', '2', '“ 你 晓 谕 以 色 列 人 说 ： 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3255', '3', '18', '3', '你 们 从 前 住 的 埃 及 地 ， 那 里 人 的 行 为 ， 你 们 不 可 效 法 ， 我 要 领 你 们 到 的 迦 南 地 ， 那 里 人 的 行 为 也 不 可 效 法 ， 也 不 可 照 他 们 的 恶 俗 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3256', '3', '18', '4', '你 们 要 遵 我 的 典 章 ， 守 我 的 律 例 ， 按 此 而 行 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3257', '3', '18', '5', '所 以 ， 你 们 要 守 我 的 律 例 典 章 ； 人 若 遵 行 ， 就 必 因 此 活 着 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3258', '3', '18', '6', '“ 你 们 都 不 可 露 骨 肉 之 亲 的 下 体 ， 亲 近 他 们 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3259', '3', '18', '7', '不 可 露 你 母 亲 的 下 体 ， 羞 辱 了 你 父 亲 。 她 是 你 的 母 亲 ， 不 可 露 她 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3260', '3', '18', '8', '不 可 露 你 继 母 的 下 体 ； 这 本 是 你 父 亲 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3261', '3', '18', '9', '你 的 姊 妹 ， 不 拘 是 异 母 同 父 的 ， 是 异 父 同 母 的 ， 无 论 是 生 在 家 生 在 外 的 ， 都 不 可 露 她 们 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3262', '3', '18', '10', '不 可 露 你 孙 女 或 是 外 孙 女 的 下 体 ， 露 了 她 们 的 下 体 就 是 露 了 自 己 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3263', '3', '18', '11', '你 继 母 从 你 父 亲 生 的 女 儿 本 是 你 的 妹 妹 ， 不 可 露 她 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3264', '3', '18', '12', '不 可 露 你 姑 母 的 下 体 ； 她 是 你 父 亲 的 骨 肉 之 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3265', '3', '18', '13', '不 可 露 你 姨 母 的 下 体 ； 她 是 你 母 亲 的 骨 肉 之 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3266', '3', '18', '14', '不 可 亲 近 你 伯 叔 之 妻 ， 羞 辱 了 你 伯 叔 ； 她 是 你 的 伯 叔 母 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3267', '3', '18', '15', '不 可 露 你 儿 妇 的 下 体 ； 她 是 你 儿 子 的 妻 ， 不 可 露 她 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3268', '3', '18', '16', '不 可 露 你 弟 兄 妻 子 的 下 体 ； 这 本 是 你 弟 兄 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3269', '3', '18', '17', '不 可 露 了 妇 人 的 下 体 ， 又 露 她 女 儿 的 下 体 ， 也 不 可 娶 她 孙 女 或 是 外 孙 女 ， 露 她 们 的 下 体 ； 她 们 是 骨 肉 之 亲 ， 这 本 是 大 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3270', '3', '18', '18', '你 妻 还 在 的 时 候 ， 不 可 另 娶 她 的 姊 妹 作 对 头 ， 露 她 的 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3271', '3', '18', '19', '“ 女 人 行 经 不 洁 净 的 时 候 ， 不 可 露 她 的 下 体 ， 与 她 亲 近 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3272', '3', '18', '20', '不 可 与 邻 舍 的 妻 行 淫 ， 玷 污 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3273', '3', '18', '21', '不 可 使 你 的 儿 女 经 火 归 与 摩 洛 ， 也 不 可 亵 渎 你 神 的 名 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3274', '3', '18', '22', '不 可 与 男 人 苟 合 ， 像 与 女 人 一 样 ； 这 本 是 可 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3275', '3', '18', '23', '不 可 与 兽 淫 合 ， 玷 污 自 己 。 女 人 也 不 可 站 在 兽 前 ， 与 它 淫 合 ； 这 本 是 逆 性 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3276', '3', '18', '24', '“ 在 这 一 切 的 事 上 ， 你 们 都 不 可 玷 污 自 己 ； 因 为 我 在 你 们 面 前 所 逐 出 的 列 邦 ， 在 这 一 切 的 事 上 玷 污 了 自 己 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3277', '3', '18', '25', '连 地 也 玷 污 了 ， 所 以 我 追 讨 那 地 的 罪 孽 ， 那 地 也 吐 出 它 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3278', '3', '18', '26', '故 此 ， 你 们 要 守 我 的 律 例 典 章 。 这 一 切 可 憎 恶 的 事 ， 无 论 是 本 地 人 ， 是 寄 居 在 你 们 中 间 的 外 人 ， 都 不 可 行 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3279', '3', '18', '27', '（ 在 你 们 以 先 居 住 那 地 的 人 行 了 这 一 切 可 憎 恶 的 事 ， 地 就 玷 污 了 ， ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3280', '3', '18', '28', '免 得 你 们 玷 污 那 地 的 时 候 ， 地 就 把 你 们 吐 出 ， 像 吐 出 在 你 们 以 先 的 国 民 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3281', '3', '18', '29', '无 论 什 么 人 ， 行 了 其 中 可 憎 的 一 件 事 ， 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3282', '3', '18', '30', '所 以 ， 你 们 要 守 我 所 吩 咐 的 ， 免 得 你 们 随 从 那 些 可 憎 的 恶 俗 ， 就 是 在 你 们 以 先 的 人 所 常 行 的 ， 以 致 玷 污 了 自 己 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3283', '3', '19', '1', '＜ 圣 洁 和 公 正 的 法 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3284', '3', '19', '2', '“ 你 晓 谕 以 色 列 全 会 众 说 ： 你 们 要 圣 洁 ， 因 为 我 耶 和 华 ─ ─ 你 们 的 神 是 圣 洁 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3285', '3', '19', '3', '你 们 各 人 都 当 孝 敬 父 母 ， 也 要 守 我 的 安 息 日 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3286', '3', '19', '4', '你 们 不 可 偏 向 虚 无 的 神 ， 也 不 可 为 自 己 铸 造 神 像 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3287', '3', '19', '5', '“ 你 们 献 平 安 祭 给 耶 和 华 的 时 候 ， 要 献 得 可 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3288', '3', '19', '6', '这 祭 物 要 在 献 的 那 一 天 和 第 二 天 吃 ， 若 有 剩 到 第 三 天 的 ， 就 必 用 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3289', '3', '19', '7', '第 三 天 若 再 吃 ， 这 就 为 可 憎 恶 的 ， 必 不 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3290', '3', '19', '8', '凡 吃 的 人 必 担 当 他 的 罪 孽 ； 因 为 他 亵 渎 了 耶 和 华 的 圣 物 ， 那 人 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3291', '3', '19', '9', '“ 在 你 们 的 地 收 割 庄 稼 ， 不 可 割 尽 田 角 ， 也 不 可 拾 取 所 遗 落 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3292', '3', '19', '10', '不 可 摘 尽 葡 萄 园 的 果 子 ， 也 不 可 拾 取 葡 萄 园 所 掉 的 果 子 ； 要 留 给 穷 人 和 寄 居 的 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3293', '3', '19', '11', '“ 你 们 不 可 偷 盗 ， 不 可 欺 骗 ， 也 不 可 彼 此 说 谎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3294', '3', '19', '12', '不 可 指 着 我 的 名 起 假 誓 ， 亵 渎 你 神 的 名 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3295', '3', '19', '13', '“ 不 可 欺 压 你 的 邻 舍 ， 也 不 可 抢 夺 他 的 物 。 雇 工 人 的 工 价 ， 不 可 在 你 那 里 过 夜 ， 留 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3296', '3', '19', '14', '不 可 咒 骂 聋 子 ， 也 不 可 将 绊 脚 石 放 在 瞎 子 面 前 ， 只 要 敬 畏 你 的 神 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3297', '3', '19', '15', '“ 你 们 施 行 审 判 ， 不 可 行 不 义 ； 不 可 偏 护 穷 人 ， 也 不 可 重 看 有 势 力 的 人 ， 只 要 按 着 公 义 审 判 你 的 邻 舍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3298', '3', '19', '16', '不 可 在 民 中 往 来 搬 弄 是 非 ， 也 不 可 与 邻 舍 为 敌 ， 置 之 于 死 ｛ 原 文 是 流 他 的 血 ｝ 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3299', '3', '19', '17', '“ 不 可 心 里 恨 你 的 弟 兄 ； 总 要 指 摘 你 的 邻 舍 ， 免 得 因 他 担 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3300', '3', '19', '18', '不 可 报 仇 ， 也 不 可 埋 怨 你 本 国 的 子 民 ， 却 要 爱 人 如 己 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3301', '3', '19', '19', '“ 你 们 要 守 我 的 律 例 。 不 可 叫 你 的 牲 畜 与 异 类 配 合 ； 不 可 用 两 样 搀 杂 的 种 种 你 的 地 ， 也 不 可 用 两 样 搀 杂 的 料 做 衣 服 穿 在 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3302', '3', '19', '20', '“ 婢 女 许 配 了 丈 夫 ， 还 没 有 被 赎 、 得 释 放 ， 人 若 与 她 行 淫 ， 二 人 要 受 刑 罚 ， 却 不 把 他 们 治 死 ， 因 为 婢 女 还 没 有 得 自 由 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3303', '3', '19', '21', '那 人 要 把 赎 愆 祭 ， 就 是 一 只 公 绵 羊 牵 到 会 幕 门 口 、 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3304', '3', '19', '22', '祭 司 要 用 赎 愆 祭 的 羊 在 耶 和 华 面 前 赎 他 所 犯 的 罪 ， 他 的 罪 就 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3305', '3', '19', '23', '“ 你 们 到 了 迦 南 地 ， 栽 种 各 样 结 果 子 的 树 木 ， 就 要 以 所 结 的 果 子 如 未 受 割 礼 的 一 样 。 三 年 之 久 ， 你 们 要 以 这 些 果 子 ， 如 未 受 割 礼 的 ， 是 不 可 吃 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3306', '3', '19', '24', '但 第 四 年 所 结 的 果 子 全 要 成 为 圣 ， 用 以 赞 美 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3307', '3', '19', '25', '第 五 年 ， 你 们 要 吃 那 树 上 的 果 子 ， 好 叫 树 给 你 们 结 果 子 更 多 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3308', '3', '19', '26', '“ 你 们 不 可 吃 带 血 的 物 ； 不 可 用 法 术 ， 也 不 可 观 兆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3309', '3', '19', '27', '头 的 周 围 ｛ 或 译 ： 两 鬓 ｝ 不 可 剃 ， 胡 须 的 周 围 也 不 可 损 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3310', '3', '19', '28', '不 可 为 死 人 用 刀 划 身 ， 也 不 可 在 身 上 刺 花 纹 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3311', '3', '19', '29', '“ 不 可 辱 没 你 的 女 儿 ， 使 她 为 娼 妓 ， 恐 怕 地 上 的 人 专 向 淫 乱 ， 地 就 满 了 大 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3312', '3', '19', '30', '你 们 要 守 我 的 安 息 日 ， 敬 我 的 圣 所 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3313', '3', '19', '31', '“ 不 可 偏 向 那 些 交 鬼 的 和 行 巫 术 的 ； 不 可 求 问 他 们 ， 以 致 被 他 们 玷 污 了 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3314', '3', '19', '32', '“ 在 白 发 的 人 面 前 ， 你 要 站 起 来 ； 也 要 尊 敬 老 人 ， 又 要 敬 畏 你 的 神 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3315', '3', '19', '33', '“ 若 有 外 人 在 你 们 国 中 和 你 同 居 ， 就 不 可 欺 负 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3316', '3', '19', '34', '和 你 们 同 居 的 外 人 ， 你 们 要 看 他 如 本 地 人 一 样 ， 并 要 爱 他 如 己 ， 因 为 你 们 在 埃 及 地 也 作 过 寄 居 的 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3317', '3', '19', '35', '“ 你 们 施 行 审 判 ， 不 可 行 不 义 ； 在 尺 、 秤 、 升 、 斗 上 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3318', '3', '19', '36', '要 用 公 道 天 平 、 公 道 法 码 、 公 道 升 斗 、 公 道 秤 。 我 是 耶 和 华 ─ ─ 你 们 的 神 ， 曾 把 你 们 从 埃 及 地 领 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3319', '3', '19', '37', '你 们 要 谨 守 遵 行 我 一 切 的 律 例 典 章 。 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3320', '3', '20', '1', '＜ 处 罚 悖 逆 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3321', '3', '20', '2', '“ 你 还 要 晓 谕 以 色 列 人 说 ： 凡 以 色 列 人 ， 或 是 在 以 色 列 中 寄 居 的 外 人 ， 把 自 己 的 儿 女 献 给 摩 洛 的 ， 总 要 治 死 他 ； 本 地 人 要 用 石 头 把 他 打 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3322', '3', '20', '3', '我 也 要 向 那 人 变 脸 ， 把 他 从 民 中 剪 除 ； 因 为 他 把 儿 女 献 给 摩 洛 ， 玷 污 我 的 圣 所 ， 亵 渎 我 的 圣 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3323', '3', '20', '4', '那 人 把 儿 女 献 给 摩 洛 ， 本 地 人 若 佯 为 不 见 ， 不 把 他 治 死 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3324', '3', '20', '5', '我 就 要 向 这 人 和 他 的 家 变 脸 ， 把 他 和 一 切 随 他 与 摩 洛 行 邪 淫 的 人 都 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3325', '3', '20', '6', '“ 人 偏 向 交 鬼 的 和 行 巫 术 的 ， 随 他 们 行 邪 淫 ， 我 要 向 那 人 变 脸 ， 把 他 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3326', '3', '20', '7', '所 以 你 们 要 自 洁 成 圣 ， 因 为 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3327', '3', '20', '8', '你 们 要 谨 守 遵 行 我 的 律 例 ； 我 是 叫 你 们 成 圣 的 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3328', '3', '20', '9', '凡 咒 骂 父 母 的 ， 总 要 治 死 他 ； 他 咒 骂 了 父 母 ， 他 的 罪 ｛ 原 文 是 血 ； 本 章 同 ｝ 要 归 到 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3329', '3', '20', '10', '“ 与 邻 舍 之 妻 行 淫 的 ， 奸 夫 淫 妇 都 必 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3330', '3', '20', '11', '与 继 母 行 淫 的 ， 就 是 羞 辱 了 他 父 亲 ， 总 要 把 他 们 二 人 治 死 ， 罪 要 归 到 他 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3331', '3', '20', '12', '与 儿 妇 同 房 的 ， 总 要 把 他 们 二 人 治 死 ； 他 们 行 了 逆 伦 的 事 ， 罪 要 归 到 他 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3332', '3', '20', '13', '人 若 与 男 人 苟 合 ， 像 与 女 人 一 样 ， 他 们 二 人 行 了 可 憎 的 事 ， 总 要 把 他 们 治 死 ， 罪 要 归 到 他 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3333', '3', '20', '14', '人 若 娶 妻 ， 并 娶 其 母 ， 便 是 大 恶 ， 要 把 这 三 人 用 火 焚 烧 ， 使 你 们 中 间 免 去 大 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3334', '3', '20', '15', '人 若 与 兽 淫 合 ， 总 要 治 死 他 ， 也 要 杀 那 兽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3335', '3', '20', '16', '女 人 若 与 兽 亲 近 ， 与 它 淫 合 ， 你 要 杀 那 女 人 和 那 兽 ， 总 要 把 他 们 治 死 ， 罪 要 归 到 他 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3336', '3', '20', '17', '“ 人 若 娶 他 的 姊 妹 ， 无 论 是 异 母 同 父 的 ， 是 异 父 同 母 的 ， 彼 此 见 了 下 体 ， 这 是 可 耻 的 事 ； 他 们 必 在 本 民 的 眼 前 被 剪 除 。 他 露 了 姊 妹 的 下 体 ， 必 担 当 自 己 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3337', '3', '20', '18', '妇 人 有 月 经 ， 若 与 她 同 房 ， 露 了 她 的 下 体 ， 就 是 露 了 妇 人 的 血 源 ， 妇 人 也 露 了 自 己 的 血 源 ， 二 人 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3338', '3', '20', '19', '不 可 露 姨 母 或 是 姑 母 的 下 体 ， 这 是 露 了 骨 肉 之 亲 的 下 体 ； 二 人 必 担 当 自 己 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3339', '3', '20', '20', '人 若 与 伯 叔 之 妻 同 房 ， 就 羞 辱 了 他 的 伯 叔 ； 二 人 要 担 当 自 己 的 罪 ， 必 无 子 女 而 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3340', '3', '20', '21', '人 若 娶 弟 兄 之 妻 ， 这 本 是 污 秽 的 事 ， 羞 辱 了 他 的 弟 兄 ； 二 人 必 无 子 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3341', '3', '20', '22', '“ 所 以 ， 你 们 要 谨 守 遵 行 我 一 切 的 律 例 典 章 ， 免 得 我 领 你 们 去 住 的 那 地 把 你 们 吐 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3342', '3', '20', '23', '我 在 你 们 面 前 所 逐 出 的 国 民 ， 你 们 不 可 随 从 他 们 的 风 俗 ； 因 为 他 们 行 了 这 一 切 的 事 ， 所 以 我 厌 恶 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3343', '3', '20', '24', '但 我 对 你 们 说 过 ， 你 们 要 承 受 他 们 的 地 ， 就 是 我 要 赐 给 你 们 为 业 、 流 奶 与 蜜 之 地 。 我 是 耶 和 华 ─ ─ 你 们 的 神 ， 使 你 们 与 万 民 有 分 别 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3344', '3', '20', '25', '所 以 ， 你 们 要 把 洁 净 和 不 洁 净 的 禽 兽 分 别 出 来 ； 不 可 因 我 给 你 们 分 为 不 洁 净 的 禽 兽 ， 或 是 滋 生 在 地 上 的 活 物 ， 使 自 己 成 为 可 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3345', '3', '20', '26', '你 们 要 归 我 为 圣 ， 因 为 我 ─ ─ 耶 和 华 是 圣 的 ， 并 叫 你 们 与 万 民 有 分 别 ， 使 你 们 作 我 的 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3346', '3', '20', '27', '“ 无 论 男 女 ， 是 交 鬼 的 或 行 巫 术 的 ， 总 要 治 死 他 们 。 人 必 用 石 头 把 他 们 打 死 ， 罪 要 归 到 他 们 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3347', '3', '21', '1', '＜ 祭 司 圣 洁 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3348', '3', '21', '2', '除 非 为 他 骨 肉 之 亲 的 父 母 、 儿 女 、 弟 兄 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3349', '3', '21', '3', '和 未 曾 出 嫁 、 作 处 女 的 姊 妹 ， 才 可 以 沾 染 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3350', '3', '21', '4', '祭 司 既 在 民 中 为 首 ， 就 不 可 从 俗 沾 染 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3351', '3', '21', '5', '不 可 使 头 光 秃 ； 不 可 剃 除 胡 须 的 周 围 ， 也 不 可 用 刀 划 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3352', '3', '21', '6', '要 归 神 为 圣 ， 不 可 亵 渎 神 的 名 ； 因 为 耶 和 华 的 火 祭 ， 就 是 神 的 食 物 ， 是 他 们 献 的 ， 所 以 他 们 要 成 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3353', '3', '21', '7', '不 可 娶 妓 女 或 被 污 的 女 人 为 妻 ， 也 不 可 娶 被 休 的 妇 人 为 妻 ， 因 为 祭 司 是 归 神 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3354', '3', '21', '8', '所 以 你 要 使 他 成 圣 ， 因 为 他 奉 献 你 神 的 食 物 ； 你 要 以 他 为 圣 ， 因 为 我 ─ ─ 使 你 们 成 圣 的 耶 和 华 ─ ─ 是 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3355', '3', '21', '9', '祭 司 的 女 儿 若 行 淫 辱 没 自 己 ， 就 辱 没 了 父 亲 ， 必 用 火 将 她 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3356', '3', '21', '10', '“ 在 弟 兄 中 作 大 祭 司 、 头 上 倒 了 膏 油 、 又 承 接 圣 职 ， 穿 了 圣 衣 的 ， 不 可 蓬 头 散 发 ， 也 不 可 撕 裂 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3357', '3', '21', '11', '不 可 挨 近 死 尸 ， 也 不 可 为 父 母 沾 染 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3358', '3', '21', '12', '不 可 出 圣 所 ， 也 不 可 亵 渎 神 的 圣 所 ， 因 为 神 膏 油 的 冠 冕 在 他 头 上 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3359', '3', '21', '13', '他 要 娶 处 女 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3360', '3', '21', '14', '寡 妇 或 是 被 休 的 妇 人 ， 或 是 被 污 为 妓 的 女 人 ， 都 不 可 娶 ； 只 可 娶 本 民 中 的 处 女 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3361', '3', '21', '15', '不 可 在 民 中 辱 没 他 的 儿 女 ， 因 为 我 是 叫 他 成 圣 的 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3362', '3', '21', '16', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3363', '3', '21', '17', '“ 你 告 诉 亚 伦 说 ： 你 世 世 代 代 的 后 裔 ， 凡 有 残 疾 的 ， 都 不 可 近 前 来 献 他 神 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3364', '3', '21', '18', '因 为 凡 有 残 疾 的 ， 无 论 是 瞎 眼 的 、 瘸 腿 的 、 塌 鼻 子 的 、 肢 体 有 余 的 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3365', '3', '21', '19', '折 脚 折 手 的 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3366', '3', '21', '20', '驼 背 的 、 矮 矬 的 、 眼 睛 有 毛 病 的 、 长 癣 的 、 长 疥 的 ， 或 是 损 坏 肾 子 的 ， 都 不 可 近 前 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3367', '3', '21', '21', '祭 司 亚 伦 的 后 裔 ， 凡 有 残 疾 的 ， 都 不 可 近 前 来 ， 将 火 祭 献 给 耶 和 华 。 他 有 残 疾 ， 不 可 近 前 来 献 神 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3368', '3', '21', '22', '神 的 食 物 ， 无 论 是 圣 的 ， 至 圣 的 ， 他 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3369', '3', '21', '23', '但 不 可 进 到 幔 子 前 ， 也 不 可 就 近 坛 前 ； 因 为 他 有 残 疾 ， 免 得 亵 渎 我 的 圣 所 。 我 是 叫 他 成 圣 的 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3370', '3', '21', '24', '于 是 ， 摩 西 晓 谕 亚 伦 和 亚 伦 的 子 孙 ， 并 以 色 列 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3371', '3', '22', '1', '＜ 圣 物 的 圣 洁 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3372', '3', '22', '2', '“ 你 吩 咐 亚 伦 和 他 子 孙 说 ： 要 远 离 以 色 列 人 所 分 别 为 圣 、 归 给 我 的 圣 物 ， 免 得 亵 渎 我 的 圣 名 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3373', '3', '22', '3', '你 要 对 他 们 说 ： 你 们 世 世 代 代 的 后 裔 ， 凡 身 上 有 污 秽 、 亲 近 以 色 列 人 所 分 别 为 圣 、 归 耶 和 华 圣 物 的 ， 那 人 必 在 我 面 前 剪 除 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3374', '3', '22', '4', '亚 伦 的 后 裔 ， 凡 长 大 痲 疯 的 ， 或 是 有 漏 症 的 ， 不 可 吃 圣 物 ， 直 等 他 洁 净 了 。 无 论 谁 摸 那 因 死 尸 不 洁 净 的 物 ｛ 或 译 ： 人 ｝ ， 或 是 遗 精 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3375', '3', '22', '5', '或 是 摸 什 么 使 他 不 洁 净 的 爬 物 ， 或 是 摸 那 使 他 不 洁 净 的 人 （ 不 拘 那 人 有 什 么 不 洁 净 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3376', '3', '22', '6', '摸 了 这 些 人 、 物 的 ， 必 不 洁 净 到 晚 上 ； 若 不 用 水 洗 身 ， 就 不 可 吃 圣 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3377', '3', '22', '7', '日 落 的 时 候 ， 他 就 洁 净 了 ， 然 后 可 以 吃 圣 物 ， 因 为 这 是 他 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3378', '3', '22', '8', '自 死 的 或 是 被 野 兽 撕 裂 的 ， 他 不 可 吃 ， 因 此 污 秽 自 己 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3379', '3', '22', '9', '所 以 他 们 要 守 我 所 吩 咐 的 ， 免 得 轻 忽 了 ， 因 此 担 罪 而 死 。 我 是 叫 他 们 成 圣 的 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3380', '3', '22', '10', '“ 凡 外 人 不 可 吃 圣 物 ； 寄 居 在 祭 司 家 的 ， 或 是 雇 工 人 ， 都 不 可 吃 圣 物 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3381', '3', '22', '11', '倘 若 祭 司 买 人 ， 是 他 的 钱 买 的 ， 那 人 就 可 以 吃 圣 物 ； 生 在 他 家 的 人 也 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3382', '3', '22', '12', '祭 司 的 女 儿 若 嫁 外 人 ， 就 不 可 吃 举 祭 的 圣 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3383', '3', '22', '13', '但 祭 司 的 女 儿 若 是 寡 妇 ， 或 是 被 休 的 ， 没 有 孩 子 ， 又 归 回 父 家 ， 与 她 青 年 一 样 ， 就 可 以 吃 她 父 亲 的 食 物 ； 只 是 外 人 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3384', '3', '22', '14', '若 有 人 误 吃 了 圣 物 ， 要 照 圣 物 的 原 数 加 上 五 分 之 一 交 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3385', '3', '22', '15', '祭 司 不 可 亵 渎 以 色 列 人 所 献 给 耶 和 华 的 圣 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3386', '3', '22', '16', '免 得 他 们 在 吃 圣 物 上 自 取 罪 孽 ， 因 为 我 是 叫 他 们 成 圣 的 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3387', '3', '22', '17', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3388', '3', '22', '18', '“ 你 晓 谕 亚 伦 和 他 子 孙 ， 并 以 色 列 众 人 说 ： 以 色 列 家 中 的 人 ， 或 在 以 色 列 中 寄 居 的 ， 凡 献 供 物 ， 无 论 是 所 许 的 愿 ， 是 甘 心 献 的 ， 就 是 献 给 耶 和 华 作 燔 祭 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3389', '3', '22', '19', '要 将 没 有 残 疾 的 公 牛 ， 或 是 绵 羊 ， 或 是 山 羊 献 上 ， 如 此 方 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3390', '3', '22', '20', '凡 有 残 疾 的 ， 你 们 不 可 献 上 ， 因 为 这 不 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3391', '3', '22', '21', '凡 从 牛 群 或 是 羊 群 中 ， 将 平 安 祭 献 给 耶 和 华 ， 为 要 还 特 许 的 愿 ， 或 是 作 甘 心 献 的 ， 所 献 的 必 纯 全 无 残 疾 的 才 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3392', '3', '22', '22', '瞎 眼 的 、 折 伤 的 、 残 废 的 、 有 瘤 子 的 、 长 癣 的 、 长 疥 的 都 不 可 献 给 耶 和 华 ， 也 不 可 在 坛 上 作 为 火 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3393', '3', '22', '23', '无 论 是 公 牛 是 绵 羊 羔 ， 若 肢 体 有 余 的 ， 或 是 缺 少 的 ， 只 可 作 甘 心 祭 献 上 ； 用 以 还 愿 ， 却 不 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3394', '3', '22', '24', '肾 子 损 伤 的 ， 或 是 压 碎 的 ， 或 是 破 裂 的 ， 或 是 骟 了 的 ， 不 可 献 给 耶 和 华 ， 在 你 们 的 地 上 也 不 可 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3395', '3', '22', '25', '这 类 的 物 ， 你 们 从 外 人 的 手 ， 一 样 也 不 可 接 受 作 你 们 神 的 食 物 献 上 ； 因 为 这 些 都 有 损 坏 ， 有 残 疾 ， 不 蒙 悦 纳 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3396', '3', '22', '26', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3397', '3', '22', '27', '“ 才 生 的 公 牛 ， 或 是 绵 羊 或 是 山 羊 ， 七 天 当 跟 着 母 ； 从 第 八 天 以 后 ， 可 以 当 供 物 蒙 悦 纳 ， 作 为 耶 和 华 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3398', '3', '22', '28', '无 论 是 母 牛 是 母 羊 ， 不 可 同 日 宰 母 和 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3399', '3', '22', '29', '你 们 献 感 谢 祭 给 耶 和 华 ， 要 献 得 可 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3400', '3', '22', '30', '要 当 天 吃 ， 一 点 不 可 留 到 早 晨 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3401', '3', '22', '31', '“ 你 们 要 谨 守 遵 行 我 的 诫 命 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3402', '3', '22', '32', '你 们 不 可 亵 渎 我 的 圣 名 ； 我 在 以 色 列 人 中 ， 却 要 被 尊 为 圣 。 我 是 叫 你 们 成 圣 的 耶 和 华 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3403', '3', '22', '33', '把 你 们 从 埃 及 地 领 出 来 ， 作 你 们 的 神 。 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3404', '3', '23', '1', '＜ 节 期 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3405', '3', '23', '2', '“ 你 晓 谕 以 色 列 人 说 ： 耶 和 华 的 节 期 ， 你 们 要 宣 告 为 圣 会 的 节 期 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3406', '3', '23', '3', '六 日 要 做 工 ， 第 七 日 是 圣 安 息 日 ， 当 有 圣 会 ； 你 们 什 么 工 都 不 可 做 。 这 是 在 你 们 一 切 的 住 处 向 耶 和 华 守 的 安 息 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3407', '3', '23', '4', '耶 和 华 的 节 期 ， 就 是 你 们 到 了 日 期 要 宣 告 为 圣 会 的 ， 乃 是 这 些 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3408', '3', '23', '5', '＜ 逾 越 节 和 除 酵 节 （ 民   2 8 : 1 6 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3409', '3', '23', '6', '这 月 十 五 日 是 向 耶 和 华 守 的 无 酵 节 ； 你 们 要 吃 无 酵 饼 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3410', '3', '23', '7', '第 一 日 当 有 圣 会 ， 什 么 劳 碌 的 工 都 不 可 做 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3411', '3', '23', '8', '要 将 火 祭 献 给 耶 和 华 七 日 。 第 七 日 是 圣 会 ， 什 么 劳 碌 的 工 都 不 可 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3412', '3', '23', '9', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3413', '3', '23', '10', '“ 你 晓 谕 以 色 列 人 说 ： 你 们 到 了 我 赐 给 你 们 的 地 ， 收 割 庄 稼 的 时 候 ， 要 将 初 熟 的 庄 稼 一 捆 带 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3414', '3', '23', '11', '他 要 把 这 一 捆 在 耶 和 华 面 前 摇 一 摇 ， 使 你 们 得 蒙 悦 纳 。 祭 司 要 在 安 息 日 的 次 日 把 这 捆 摇 一 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3415', '3', '23', '12', '摇 这 捆 的 日 子 ， 你 们 要 把 一 岁 、 没 有 残 疾 的 公 绵 羊 羔 献 给 耶 和 华 为 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3416', '3', '23', '13', '同 献 的 素 祭 ， 就 是 调 油 的 细 面 伊 法 十 分 之 二 ， 作 为 馨 香 的 火 祭 ， 献 给 耶 和 华 。 同 献 的 奠 祭 ， 要 酒 一 欣 四 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3417', '3', '23', '14', '无 论 是 饼 ， 是 烘 的 子 粒 ， 是 新 穗 子 ， 你 们 都 不 可 吃 ， 直 等 到 把 你 们 献 给 神 的 供 物 带 来 的 那 一 天 才 可 以 吃 。 这 在 你 们 一 切 的 住 处 作 为 世 世 代 代 永 远 的 定 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3418', '3', '23', '15', '＜ 五 旬 收 获 节 （ 民   2 8 : 2 6 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3419', '3', '23', '16', '到 第 七 个 安 息 日 的 次 日 ， 共 计 五 十 天 ， 又 要 将 新 素 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3420', '3', '23', '17', '要 从 你 们 的 住 处 取 出 细 面 伊 法 十 分 之 二 ， 加 酵 ， 烤 成 两 个 摇 祭 的 饼 ， 当 作 初 熟 之 物 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3421', '3', '23', '18', '又 要 将 一 岁 、 没 有 残 疾 的 羊 羔 七 只 、 公 牛 犊 一 只 、 公 绵 羊 两 只 ， 和 饼 一 同 奉 上 。 这 些 与 同 献 的 素 祭 和 奠 祭 要 作 为 燔 祭 献 给 耶 和 华 ， 就 是 作 馨 香 的 火 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3422', '3', '23', '19', '你 们 要 献 一 只 公 山 羊 为 赎 罪 祭 ， 两 只 一 岁 的 公 绵 羊 羔 为 平 安 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3423', '3', '23', '20', '祭 司 要 把 这 些 和 初 熟 麦 子 做 的 饼 一 同 作 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ； 这 是 献 与 耶 和 华 为 圣 物 归 给 祭 司 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3424', '3', '23', '21', '当 这 日 ， 你 们 要 宣 告 圣 会 ； 什 么 劳 碌 的 工 都 不 可 做 。 这 在 你 们 一 切 的 住 处 作 为 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3425', '3', '23', '22', '“ 在 你 们 的 地 收 割 庄 稼 ， 不 可 割 尽 田 角 ， 也 不 可 拾 取 所 遗 落 的 ； 要 留 给 穷 人 和 寄 居 的 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3426', '3', '23', '23', '＜ 新 年 （ 民   2 9 : 1 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3427', '3', '23', '24', '“ 你 晓 谕 以 色 列 人 说 ： 七 月 初 一 ， 你 们 要 守 为 圣 安 息 日 ， 要 吹 角 作 纪 念 ， 当 有 圣 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3428', '3', '23', '25', '什 么 劳 碌 的 工 都 不 可 做 ； 要 将 火 祭 献 给 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3429', '3', '23', '26', '＜ 赎 罪 日 （ 民   2 9 : 7 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3430', '3', '23', '27', '“ 七 月 初 十 是 赎 罪 日 ； 你 们 要 守 为 圣 会 ， 并 要 刻 苦 己 心 ， 也 要 将 火 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3431', '3', '23', '28', '当 这 日 ， 什 么 工 都 不 可 做 ； 因 为 是 赎 罪 日 ， 要 在 耶 和 华 ─ ─ 你 们 的 神 面 前 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3432', '3', '23', '29', '当 这 日 ， 凡 不 刻 苦 己 心 的 ， 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3433', '3', '23', '30', '凡 这 日 做 什 么 工 的 ， 我 必 将 他 从 民 中 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3434', '3', '23', '31', '你 们 什 么 工 都 不 可 做 。 这 在 你 们 一 切 的 住 处 作 为 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3435', '3', '23', '32', '你 们 要 守 这 日 为 圣 安 息 日 ， 并 要 刻 苦 己 心 。 从 这 月 初 九 日 晚 上 到 次 日 晚 上 ， 要 守 为 安 息 日 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3436', '3', '23', '33', '＜ 住 棚 节 （ 民   2 9 : 1 2 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3437', '3', '23', '34', '“ 你 晓 谕 以 色 列 人 说 ： 这 七 月 十 五 日 是 住 棚 节 ， 要 在 耶 和 华 面 前 守 这 节 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3438', '3', '23', '35', '第 一 日 当 有 圣 会 ， 什 么 劳 碌 的 工 都 不 可 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3439', '3', '23', '36', '七 日 内 要 将 火 祭 献 给 耶 和 华 。 第 八 日 当 守 圣 会 ， 要 将 火 祭 献 给 耶 和 华 。 这 是 严 肃 会 ， 什 么 劳 碌 的 工 都 不 可 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3440', '3', '23', '37', '“ 这 是 耶 和 华 的 节 期 ， 就 是 你 们 要 宣 告 为 圣 会 的 节 期 ； 要 将 火 祭 、 燔 祭 、 素 祭 、 祭 物 ， 并 奠 祭 ， 各 归 各 日 ， 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3441', '3', '23', '38', '这 是 在 耶 和 华 的 安 息 日 以 外 ， 又 在 你 们 的 供 物 和 所 许 的 愿 ， 并 甘 心 献 给 耶 和 华 的 以 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3442', '3', '23', '39', '“ 你 们 收 藏 了 地 的 出 产 ， 就 从 七 月 十 五 日 起 ， 要 守 耶 和 华 的 节 七 日 。 第 一 日 为 圣 安 息 ； 第 八 日 也 为 圣 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3443', '3', '23', '40', '第 一 日 要 拿 美 好 树 上 的 果 子 和 棕 树 上 的 枝 子 ， 与 茂 密 树 的 枝 条 并 河 旁 的 柳 枝 ， 在 耶 和 华 ─ ─ 你 们 的 神 面 前 欢 乐 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3444', '3', '23', '41', '每 年 七 月 间 ， 要 向 耶 和 华 守 这 节 七 日 。 这 为 你 们 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3445', '3', '23', '42', '你 们 要 住 在 棚 里 七 日 ； 凡 以 色 列 家 的 人 都 要 住 在 棚 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3446', '3', '23', '43', '好 叫 你 们 世 世 代 代 知 道 ， 我 领 以 色 列 人 出 埃 及 地 的 时 候 曾 使 他 们 住 在 棚 里 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3447', '3', '23', '44', '于 是 ， 摩 西 将 耶 和 华 的 节 期 传 给 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3448', '3', '24', '1', '＜ 燃 灯 的 条 例 （ 出   2 7 : 2 0 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3449', '3', '24', '2', '“ 要 吩 咐 以 色 列 人 ， 把 那 为 点 灯 捣 成 的 清 橄 榄 油 拿 来 给 你 ， 使 灯 常 常 点 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3450', '3', '24', '3', '在 会 幕 中 法 柜 的 幔 子 外 ， 亚 伦 从 晚 上 到 早 晨 必 在 耶 和 华 面 前 经 理 这 灯 。 这 要 作 你 们 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3451', '3', '24', '4', '他 要 在 耶 和 华 面 前 常 收 拾 精 金 灯 台 上 的 灯 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3452', '3', '24', '5', '＜ 陈 设 饼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3453', '3', '24', '6', '要 把 饼 摆 列 两 行 ｛ 或 译 ： 摞 ； 下 同 ｝ ， 每 行 六 个 ， 在 耶 和 华 面 前 精 金 的 桌 子 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3454', '3', '24', '7', '又 要 把 净 乳 香 放 在 每 行 饼 上 ， 作 为 纪 念 ， 就 是 作 为 火 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3455', '3', '24', '8', '每 安 息 日 要 常 摆 在 耶 和 华 面 前 ； 这 为 以 色 列 人 作 永 远 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3456', '3', '24', '9', '这 饼 是 要 给 亚 伦 和 他 子 孙 的 ； 他 们 要 在 圣 处 吃 ， 为 永 远 的 定 例 ， 因 为 在 献 给 耶 和 华 的 火 祭 中 是 至 圣 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3457', '3', '24', '10', '＜ 公 正 的 判 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3458', '3', '24', '11', '这 以 色 列 妇 人 的 儿 子 亵 渎 了 圣 名 ， 并 且 咒 诅 ， 就 有 人 把 他 送 到 摩 西 那 里 。 （ 他 母 亲 名 叫 示 罗 密 ， 是 但 支 派 底 伯 利 的 女 儿 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3459', '3', '24', '12', '他 们 把 那 人 收 在 监 里 ， 要 得 耶 和 华 所 指 示 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3460', '3', '24', '13', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3461', '3', '24', '14', '“ 把 那 咒 诅 圣 名 的 人 带 到 营 外 。 叫 听 见 的 人 都 放 手 在 他 头 上 ； 全 会 众 就 要 用 石 头 打 死 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3462', '3', '24', '15', '你 要 晓 谕 以 色 列 人 说 ： 凡 咒 诅 神 的 ， 必 担 当 他 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3463', '3', '24', '16', '那 亵 渎 耶 和 华 名 的 ， 必 被 治 死 ； 全 会 众 总 要 用 石 头 打 死 他 。 不 管 是 寄 居 的 是 本 地 人 ， 他 亵 渎 耶 和 华 名 的 时 候 ， 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3464', '3', '24', '17', '打 死 人 的 ， 必 被 治 死 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3465', '3', '24', '18', '打 死 牲 畜 的 ， 必 赔 上 牲 畜 ， 以 命 偿 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3466', '3', '24', '19', '人 若 使 他 邻 舍 的 身 体 有 残 疾 ， 他 怎 样 行 ， 也 要 照 样 向 他 行 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3467', '3', '24', '20', '以 伤 还 伤 ， 以 眼 还 眼 ， 以 牙 还 牙 。 他 怎 样 叫 人 的 身 体 有 残 疾 ， 也 要 照 样 向 他 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3468', '3', '24', '21', '打 死 牲 畜 的 ， 必 赔 上 牲 畜 ； 打 死 人 的 ， 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3469', '3', '24', '22', '不 管 是 寄 居 的 是 本 地 人 ， 同 归 一 例 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3470', '3', '24', '23', '于 是 ， 摩 西 晓 谕 以 色 列 人 ， 他 们 就 把 那 咒 诅 圣 名 的 人 带 到 营 外 ， 用 石 头 打 死 。 以 色 列 人 就 照 耶 和 华 所 吩 咐 摩 西 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3471', '3', '25', '1', '＜ 安 息 年 （ 申   1 5 : 1 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3472', '3', '25', '2', '“ 你 晓 谕 以 色 列 人 说 ： 你 们 到 了 我 所 赐 你 们 那 地 的 时 候 ， 地 就 要 向 耶 和 华 守 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3473', '3', '25', '3', '六 年 要 耕 种 田 地 ， 也 要 修 理 葡 萄 园 ， 收 藏 地 的 出 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3474', '3', '25', '4', '第 七 年 ， 地 要 守 圣 安 息 ， 就 是 向 耶 和 华 守 的 安 息 ， 不 可 耕 种 田 地 ， 也 不 可 修 理 葡 萄 园 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3475', '3', '25', '5', '遗 落 自 长 的 庄 稼 不 可 收 割 ； 没 有 修 理 的 葡 萄 树 也 不 可 摘 取 葡 萄 。 这 年 ， 地 要 守 圣 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3476', '3', '25', '6', '地 在 安 息 年 所 出 的 ， 要 给 你 和 你 的 仆 人 、 婢 女 、 雇 工 人 ， 并 寄 居 的 外 人 当 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3477', '3', '25', '7', '这 年 的 土 产 也 要 给 你 的 牲 畜 和 你 地 上 的 走 兽 当 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3478', '3', '25', '8', '＜ 禧 年 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3479', '3', '25', '9', '当 年 七 月 初 十 日 ， 你 要 大 发 角 声 ； 这 日 就 是 赎 罪 日 ， 要 在 遍 地 发 出 角 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3480', '3', '25', '10', '第 五 十 年 ， 你 们 要 当 作 圣 年 ， 在 遍 地 给 一 切 的 居 民 宣 告 自 由 。 这 年 必 为 你 们 的 禧 年 ， 各 人 要 归 自 己 的 产 业 ， 各 归 本 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3481', '3', '25', '11', '第 五 十 年 要 作 为 你 们 的 禧 年 。 这 年 不 可 耕 种 ； 地 中 自 长 的 ， 不 可 收 割 ； 没 有 修 理 的 葡 萄 树 也 不 可 摘 取 葡 萄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3482', '3', '25', '12', '因 为 这 是 禧 年 ， 你 们 要 当 作 圣 年 ， 吃 地 中 自 出 的 土 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3483', '3', '25', '13', '“ 这 禧 年 ， 你 们 各 人 要 归 自 己 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3484', '3', '25', '14', '你 若 卖 什 么 给 邻 舍 ， 或 是 从 邻 舍 的 手 中 买 什 么 ， 彼 此 不 可 亏 负 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3485', '3', '25', '15', '你 要 按 禧 年 以 后 的 年 数 向 邻 舍 买 ； 他 也 要 按 年 数 的 收 成 卖 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3486', '3', '25', '16', '年 岁 若 多 ， 要 照 数 加 添 价 值 ； 年 岁 若 少 ， 要 照 数 减 去 价 值 ， 因 为 他 照 收 成 的 数 目 卖 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3487', '3', '25', '17', '你 们 彼 此 不 可 亏 负 ， 只 要 敬 畏 你 们 的 神 ， 因 为 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3488', '3', '25', '18', '＜ 安 息 年 的 问 题 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3489', '3', '25', '19', '地 必 出 土 产 ， 你 们 就 要 吃 饱 ， 在 那 地 上 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3490', '3', '25', '20', '你 们 若 说 ： ‘ 这 第 七 年 我 们 不 耕 种 ， 也 不 收 藏 土 产 ， 吃 什 么 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3491', '3', '25', '21', '我 必 在 第 六 年 将 我 所 命 的 福 赐 给 你 们 ， 地 便 生 三 年 的 土 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3492', '3', '25', '22', '第 八 年 ， 你 们 要 耕 种 ， 也 要 吃 陈 粮 ， 等 到 第 九 年 出 产 收 来 的 时 候 ， 你 们 还 吃 陈 粮 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3493', '3', '25', '23', '＜ 赎 房 地 产 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3494', '3', '25', '24', '在 你 们 所 得 为 业 的 全 地 ， 也 要 准 人 将 地 赎 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3495', '3', '25', '25', '你 的 弟 兄 ｛ 弟 兄 是 指 本 国 人 说 ； 下 同 ｝ 若 渐 渐 穷 乏 ， 卖 了 几 分 地 业 ， 他 至 近 的 亲 属 就 要 来 把 弟 兄 所 卖 的 赎 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3496', '3', '25', '26', '若 没 有 能 给 他 赎 回 的 ， 他 自 己 渐 渐 富 足 ， 能 够 赎 回 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3497', '3', '25', '27', '就 要 算 出 卖 地 的 年 数 ， 把 余 剩 年 数 的 价 值 还 那 买 主 ， 自 己 便 归 回 自 己 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3498', '3', '25', '28', '倘 若 不 能 为 自 己 得 回 所 卖 的 ， 仍 要 存 在 买 主 的 手 里 直 到 禧 年 ； 到 了 禧 年 ， 地 业 要 出 买 主 的 手 ， 自 己 便 归 回 自 己 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3499', '3', '25', '29', '“ 人 若 卖 城 内 的 住 宅 ， 卖 了 以 后 ， 一 年 之 内 可 以 赎 回 ； 在 一 整 年 ， 必 有 赎 回 的 权 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3500', '3', '25', '30', '若 在 一 整 年 之 内 不 赎 回 ， 这 城 内 的 房 屋 就 定 准 永 归 买 主 ， 世 世 代 代 为 业 ； 在 禧 年 也 不 得 出 买 主 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3501', '3', '25', '31', '但 房 屋 在 无 城 墙 的 村 庄 里 ， 要 看 如 乡 下 的 田 地 一 样 ， 可 以 赎 回 ； 到 了 禧 年 ， 都 要 出 买 主 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3502', '3', '25', '32', '然 而 利 未 人 所 得 为 业 的 城 邑 ， 其 中 的 房 屋 ， 利 未 人 可 以 随 时 赎 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3503', '3', '25', '33', '若 是 一 个 利 未 人 不 将 所 卖 的 房 屋 赎 回 ， 是 在 所 得 为 业 的 城 内 ， 到 了 禧 年 就 要 出 买 主 的 手 ， 因 为 利 未 人 城 邑 的 房 屋 是 他 们 在 以 色 列 人 中 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3504', '3', '25', '34', '只 是 他 们 各 城 郊 野 之 地 不 可 卖 ， 因 为 是 他 们 永 远 的 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3505', '3', '25', '35', '＜ 借 贷 给 穷 人 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3506', '3', '25', '36', '不 可 向 他 取 利 ， 也 不 可 向 他 多 要 ； 只 要 敬 畏 你 的 神 ， 使 你 的 弟 兄 与 你 同 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3507', '3', '25', '37', '你 借 钱 给 他 ， 不 可 向 他 取 利 ； 借 粮 给 他 ， 也 不 可 向 他 多 要 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3508', '3', '25', '38', '我 是 耶 和 华 ─ ─ 你 们 的 神 ， 曾 领 你 们 从 埃 及 地 出 来 ， 为 要 把 迦 南 地 赐 给 你 们 ， 要 作 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3509', '3', '25', '39', '＜ 赎 回 奴 仆 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3510', '3', '25', '40', '他 要 在 你 那 里 像 雇 工 人 和 寄 居 的 一 样 ， 要 服 事 你 直 到 禧 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3511', '3', '25', '41', '到 了 禧 年 ， 他 和 他 儿 女 要 离 开 你 ， 一 同 出 去 归 回 本 家 ， 到 他 祖 宗 的 地 业 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3512', '3', '25', '42', '因 为 他 们 是 我 的 仆 人 ， 是 我 从 埃 及 地 领 出 来 的 ， 不 可 卖 为 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3513', '3', '25', '43', '不 可 严 严 地 辖 管 他 ， 只 要 敬 畏 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3514', '3', '25', '44', '至 于 你 的 奴 仆 、 婢 女 ， 可 以 从 你 四 围 的 国 中 买 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3515', '3', '25', '45', '并 且 那 寄 居 在 你 们 中 间 的 外 人 和 他 们 的 家 属 ， 在 你 们 地 上 所 生 的 ， 你 们 也 可 以 从 其 中 买 人 ； 他 们 要 作 你 们 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3516', '3', '25', '46', '你 们 要 将 他 们 遗 留 给 你 们 的 子 孙 为 产 业 ， 要 永 远 从 他 们 中 间 拣 出 奴 仆 ； 只 是 你 们 的 弟 兄 以 色 列 人 ， 你 们 不 可 严 严 地 辖 管 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3517', '3', '25', '47', '“ 住 在 你 那 里 的 外 人 ， 或 是 寄 居 的 ， 若 渐 渐 富 足 ， 你 的 弟 兄 却 渐 渐 穷 乏 ， 将 自 己 卖 给 那 外 人 ， 或 是 寄 居 的 ， 或 是 外 人 的 宗 族 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3518', '3', '25', '48', '卖 了 以 后 ， 可 以 将 他 赎 回 。 无 论 是 他 的 弟 兄 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3519', '3', '25', '49', '或 伯 叔 、 伯 叔 的 儿 子 ， 本 家 的 近 支 ， 都 可 以 赎 他 。 他 自 己 若 渐 渐 富 足 ， 也 可 以 自 赎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3520', '3', '25', '50', '他 要 和 买 主 计 算 ， 从 卖 自 己 的 那 年 起 ， 算 到 禧 年 ； 所 卖 的 价 值 照 着 年 数 多 少 ， 好 像 工 人 每 年 的 工 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3521', '3', '25', '51', '若 缺 少 的 年 数 多 ， 就 要 按 着 年 数 从 买 价 中 偿 还 他 的 赎 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3522', '3', '25', '52', '若 到 禧 年 只 缺 少 几 年 ， 就 要 按 着 年 数 和 买 主 计 算 ， 偿 还 他 的 赎 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3523', '3', '25', '53', '他 和 买 主 同 住 ， 要 像 每 年 雇 的 工 人 ， 买 主 不 可 严 严 地 辖 管 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3524', '3', '25', '54', '他 若 不 这 样 被 赎 ， 到 了 禧 年 ， 要 和 他 的 儿 女 一 同 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3525', '3', '25', '55', '因 为 以 色 列 人 都 是 我 的 仆 人 ， 是 我 从 埃 及 地 领 出 来 的 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3526', '3', '26', '1', '＜ 遵 行 诫 命 者 的 福 祉 （ 申   7 : 1 2 - 2 4 ； 2 8 : 1 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3527', '3', '26', '2', '你 们 要 守 我 的 安 息 日 ， 敬 我 的 圣 所 。 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3528', '3', '26', '3', '“ 你 们 若 遵 行 我 的 律 例 ， 谨 守 我 的 诫 命 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3529', '3', '26', '4', '我 就 给 你 们 降 下 时 雨 ， 叫 地 生 出 土 产 ， 田 野 的 树 木 结 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3530', '3', '26', '5', '你 们 打 粮 食 要 打 到 摘 葡 萄 的 时 候 ， 摘 葡 萄 要 摘 到 撒 种 的 时 候 ； 并 且 要 吃 得 饱 足 ， 在 你 们 的 地 上 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3531', '3', '26', '6', '我 要 赐 平 安 在 你 们 的 地 上 ； 你 们 躺 卧 ， 无 人 惊 吓 。 我 要 叫 恶 兽 从 你 们 的 地 上 息 灭 ； 刀 剑 也 必 不 经 过 你 们 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3532', '3', '26', '7', '你 们 要 追 赶 仇 敌 ， 他 们 必 倒 在 你 们 刀 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3533', '3', '26', '8', '你 们 五 个 人 要 追 赶 一 百 人 ， 一 百 人 要 追 赶 一 万 人 ； 仇 敌 必 倒 在 你 们 刀 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3534', '3', '26', '9', '我 要 眷 顾 你 们 ， 使 你 们 生 养 众 多 ， 也 要 与 你 们 坚 定 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3535', '3', '26', '10', '你 们 要 吃 陈 粮 ， 又 因 新 粮 挪 开 陈 粮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3536', '3', '26', '11', '我 要 在 你 们 中 间 立 我 的 帐 幕 ； 我 的 心 也 不 厌 恶 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3537', '3', '26', '12', '我 要 在 你 们 中 间 行 走 ； 我 要 作 你 们 的 神 ， 你 们 要 作 我 的 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3538', '3', '26', '13', '我 是 耶 和 华 ─ ─ 你 们 的 神 ， 曾 将 你 们 从 埃 及 地 领 出 来 ， 使 你 们 不 作 埃 及 人 的 奴 仆 ； 我 也 折 断 你 们 所 负 的 轭 ， 叫 你 们 挺 身 而 走 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3539', '3', '26', '14', '＜ 违 反 诫 命 者 的 刑 罚 （ 申   2 8 : 1 5 - 6 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3540', '3', '26', '15', '厌 弃 我 的 律 例 ， 厌 恶 我 的 典 章 ， 不 遵 行 我 一 切 的 诫 命 ， 背 弃 我 的 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3541', '3', '26', '16', '我 待 你 们 就 要 这 样 ： 我 必 命 定 惊 惶 ， 叫 眼 目 干 瘪 、 精 神 消 耗 的 痨 病 热 病 辖 制 你 们 。 你 们 也 要 白 白 地 撒 种 ， 因 为 仇 敌 要 吃 你 们 所 种 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3542', '3', '26', '17', '我 要 向 你 们 变 脸 ， 你 们 就 要 败 在 仇 敌 面 前 。 恨 恶 你 们 的 ， 必 辖 管 你 们 ； 无 人 追 赶 ， 你 们 却 要 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3543', '3', '26', '18', '你 们 因 这 些 事 若 还 不 听 从 我 ， 我 就 要 为 你 们 的 罪 加 七 倍 惩 罚 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3544', '3', '26', '19', '我 必 断 绝 你 们 因 势 力 而 有 的 骄 傲 ， 又 要 使 覆 你 们 的 天 如 铁 ， 载 你 们 的 地 如 铜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3545', '3', '26', '20', '你 们 要 白 白 地 劳 力 ； 因 为 你 们 的 地 不 出 土 产 ， 其 上 的 树 木 也 不 结 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3546', '3', '26', '21', '“ 你 们 行 事 若 与 我 反 对 ， 不 肯 听 从 我 ， 我 就 要 按 你 们 的 罪 加 七 倍 降 灾 与 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3547', '3', '26', '22', '我 也 要 打 发 野 地 的 走 兽 到 你 们 中 间 ， 抢 吃 你 们 的 儿 女 ， 吞 灭 你 们 的 牲 畜 ， 使 你 们 的 人 数 减 少 ， 道 路 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3548', '3', '26', '23', '“ 你 们 因 这 些 事 若 仍 不 改 正 归 我 ， 行 事 与 我 反 对 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3549', '3', '26', '24', '我 就 要 行 事 与 你 们 反 对 ， 因 你 们 的 罪 击 打 你 们 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3550', '3', '26', '25', '我 又 要 使 刀 剑 临 到 你 们 ， 报 复 你 们 背 约 的 仇 ； 聚 集 你 们 在 各 城 内 ， 降 瘟 疫 在 你 们 中 间 ， 也 必 将 你 们 交 在 仇 敌 的 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3551', '3', '26', '26', '我 要 折 断 你 们 的 杖 ， 就 是 断 绝 你 们 的 粮 。 那 时 ， 必 有 十 个 女 人 在 一 个 炉 子 给 你 们 烤 饼 ， 按 分 量 秤 给 你 们 ； 你 们 要 吃 ， 也 吃 不 饱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3552', '3', '26', '27', '“ 你 们 因 这 一 切 的 事 若 不 听 从 我 ， 却 行 事 与 我 反 对 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3553', '3', '26', '28', '我 就 要 发 烈 怒 ， 行 事 与 你 们 反 对 ， 又 因 你 们 的 罪 惩 罚 你 们 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3554', '3', '26', '29', '并 且 你 们 要 吃 儿 子 的 肉 ， 也 要 吃 女 儿 的 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3555', '3', '26', '30', '我 又 要 毁 坏 你 们 的 邱 坛 ， 砍 下 你 们 的 日 像 ， 把 你 们 的 尸 首 扔 在 你 们 偶 像 的 身 上 ； 我 的 心 也 必 厌 恶 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3556', '3', '26', '31', '我 要 使 你 们 的 城 邑 变 为 荒 凉 ， 使 你 们 的 众 圣 所 成 为 荒 场 ； 我 也 不 闻 你 们 馨 香 的 香 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3557', '3', '26', '32', '我 要 使 地 成 为 荒 场 ， 住 在 其 上 的 仇 敌 就 因 此 诧 异 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3558', '3', '26', '33', '我 要 把 你 们 散 在 列 邦 中 ； 我 也 要 拔 刀 追 赶 你 们 。 你 们 的 地 要 成 为 荒 场 ； 你 们 的 城 邑 要 变 为 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3559', '3', '26', '34', '“ 你 们 在 仇 敌 之 地 居 住 的 时 候 ， 你 们 的 地 荒 凉 ， 要 享 受 众 安 息 ； 正 在 那 时 候 ， 地 要 歇 息 ， 享 受 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3560', '3', '26', '35', '地 多 时 为 荒 场 ， 就 要 多 时 歇 息 ； 地 这 样 歇 息 ， 是 你 们 住 在 其 上 的 安 息 年 所 不 能 得 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3561', '3', '26', '36', '至 于 你 们 剩 下 的 人 ， 我 要 使 他 们 在 仇 敌 之 地 心 惊 胆 怯 。 叶 子 被 风 吹 的 响 声 ， 要 追 赶 他 们 ； 他 们 要 逃 避 ， 像 人 逃 避 刀 剑 ， 无 人 追 赶 ， 却 要 跌 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3562', '3', '26', '37', '无 人 追 赶 ， 他 们 要 彼 此 撞 跌 ， 像 在 刀 剑 之 前 。 你 们 在 仇 敌 面 前 也 必 站 立 不 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3563', '3', '26', '38', '你 们 要 在 列 邦 中 灭 亡 ； 仇 敌 之 地 要 吞 吃 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3564', '3', '26', '39', '你 们 剩 下 的 人 必 因 自 己 的 罪 孽 和 祖 宗 的 罪 孽 在 仇 敌 之 地 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3565', '3', '26', '40', '“ 他 们 要 承 认 自 己 的 罪 和 他 们 祖 宗 的 罪 ， 就 是 干 犯 我 的 那 罪 ， 并 且 承 认 自 己 行 事 与 我 反 对 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3566', '3', '26', '41', '我 所 以 行 事 与 他 们 反 对 ， 把 他 们 带 到 仇 敌 之 地 。 那 时 ， 他 们 未 受 割 礼 的 心 若 谦 卑 了 ， 他 们 也 服 了 罪 孽 的 刑 罚 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3567', '3', '26', '42', '我 就 要 记 念 我 与 雅 各 所 立 的 约 ， 与 以 撒 所 立 的 约 ， 与 亚 伯 拉 罕 所 立 的 约 ， 并 要 记 念 这 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3568', '3', '26', '43', '他 们 离 开 这 地 ， 地 在 荒 废 无 人 的 时 候 就 要 享 受 安 息 。 并 且 他 们 要 服 罪 孽 的 刑 罚 ； 因 为 他 们 厌 弃 了 我 的 典 章 ， 心 中 厌 恶 了 我 的 律 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3569', '3', '26', '44', '虽 是 这 样 ， 他 们 在 仇 敌 之 地 ， 我 却 不 厌 弃 他 们 ， 也 不 厌 恶 他 们 ， 将 他 们 尽 行 灭 绝 ， 也 不 背 弃 我 与 他 们 所 立 的 约 ， 因 为 我 是 耶 和 华 ─ ─ 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3570', '3', '26', '45', '我 却 要 为 他 们 的 缘 故 记 念 我 与 他 们 先 祖 所 立 的 约 。 他 们 的 先 祖 是 我 在 列 邦 人 眼 前 、 从 埃 及 地 领 出 来 的 ， 为 要 作 他 们 的 神 。 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3571', '3', '26', '46', '这 些 律 例 、 典 章 ， 和 法 度 是 耶 和 华 与 以 色 列 人 在 西 奈 山 藉 着 摩 西 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3572', '3', '27', '1', '＜ 许 愿 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3573', '3', '27', '2', '“ 你 晓 谕 以 色 列 人 说 ： 人 还 特 许 的 愿 ， 被 许 的 人 要 按 你 所 估 的 价 值 归 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3574', '3', '27', '3', '你 估 定 的 ， 从 二 十 岁 到 六 十 岁 的 男 人 ， 要 按 圣 所 的 平 ， 估 定 价 银 五 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3575', '3', '27', '4', '若 是 女 人 ， 你 要 估 定 三 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3576', '3', '27', '5', '若 是 从 五 岁 到 二 十 岁 ， 男 子 你 要 估 定 二 十 舍 客 勒 ， 女 子 估 定 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3577', '3', '27', '6', '若 是 从 一 月 到 五 岁 ， 男 子 你 要 估 定 五 舍 客 勒 ， 女 子 估 定 三 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3578', '3', '27', '7', '若 是 从 六 十 岁 以 上 ， 男 人 你 要 估 定 十 五 舍 客 勒 ， 女 人 估 定 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3579', '3', '27', '8', '他 若 贫 穷 ， 不 能 照 你 所 估 定 的 价 ， 就 要 把 他 带 到 祭 司 面 前 ， 祭 司 要 按 许 愿 人 的 力 量 估 定 他 的 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3580', '3', '27', '9', '“ 所 许 的 若 是 牲 畜 ， 就 是 人 献 给 耶 和 华 为 供 物 的 ， 凡 这 一 类 献 给 耶 和 华 的 ， 都 要 成 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3581', '3', '27', '10', '人 不 可 改 换 ， 也 不 可 更 换 ， 或 是 好 的 换 坏 的 ， 或 是 坏 的 换 好 的 。 若 以 牲 畜 更 换 牲 畜 ， 所 许 的 与 所 换 的 都 要 成 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3582', '3', '27', '11', '若 牲 畜 不 洁 净 ， 是 不 可 献 给 耶 和 华 为 供 物 的 ， 就 要 把 牲 畜 安 置 在 祭 司 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3583', '3', '27', '12', '祭 司 就 要 估 定 价 值 ； 牲 畜 是 好 是 坏 ， 祭 司 怎 样 估 定 ， 就 要 以 怎 样 为 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3584', '3', '27', '13', '他 若 一 定 要 赎 回 ， 就 要 在 你 所 估 定 的 价 值 以 外 加 上 五 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3585', '3', '27', '14', '“ 人 将 房 屋 分 别 为 圣 ， 归 给 耶 和 华 ， 祭 司 就 要 估 定 价 值 。 房 屋 是 好 是 坏 ， 祭 司 怎 样 估 定 ， 就 要 以 怎 样 为 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3586', '3', '27', '15', '将 房 屋 分 别 为 圣 的 人 ， 若 要 赎 回 房 屋 ， 就 必 在 你 所 估 定 的 价 值 以 外 加 上 五 分 之 一 ， 房 屋 仍 旧 归 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3587', '3', '27', '16', '“ 人 若 将 承 受 为 业 的 几 分 地 分 别 为 圣 ， 归 给 耶 和 华 ， 你 要 按 这 地 撒 种 多 少 估 定 价 值 ， 若 撒 大 麦 一 贺 梅 珥 ， 要 估 价 五 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3588', '3', '27', '17', '他 若 从 禧 年 将 地 分 别 为 圣 ， 就 要 以 你 所 估 定 的 价 为 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3589', '3', '27', '18', '倘 若 他 在 禧 年 以 后 将 地 分 别 为 圣 ， 祭 司 就 要 按 着 未 到 禧 年 所 剩 的 年 数 推 算 价 值 ， 也 要 从 你 所 估 的 减 去 价 值 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3590', '3', '27', '19', '将 地 分 别 为 圣 的 人 若 定 要 把 地 赎 回 ， 他 便 要 在 你 所 估 的 价 值 以 外 加 上 五 分 之 一 ， 地 就 准 定 归 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3591', '3', '27', '20', '他 若 不 赎 回 那 地 ， 或 是 将 地 卖 给 别 人 ， 就 再 不 能 赎 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3592', '3', '27', '21', '但 到 了 禧 年 ， 那 地 从 买 主 手 下 出 来 的 时 候 ， 就 要 归 耶 和 华 为 圣 ， 和 永 献 的 地 一 样 ， 要 归 祭 司 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3593', '3', '27', '22', '他 若 将 所 买 的 一 块 地 ， 不 是 承 受 为 业 的 ， 分 别 为 圣 归 给 耶 和 华 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3594', '3', '27', '23', '祭 司 就 要 将 你 所 估 的 价 值 给 他 推 算 到 禧 年 。 当 日 ， 他 要 以 你 所 估 的 价 银 为 圣 ， 归 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3595', '3', '27', '24', '到 了 禧 年 ， 那 地 要 归 卖 主 ， 就 是 那 承 受 为 业 的 原 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3596', '3', '27', '25', '凡 你 所 估 定 的 价 银 都 要 按 着 圣 所 的 平 ： 二 十 季 拉 为 一 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3597', '3', '27', '26', '“ 惟 独 牲 畜 中 头 生 的 ， 无 论 是 牛 是 羊 ， 既 归 耶 和 华 ， 谁 也 不 可 再 分 别 为 圣 ， 因 为 这 是 耶 和 华 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3598', '3', '27', '27', '若 是 不 洁 净 的 牲 畜 生 的 ， 就 要 按 你 所 估 定 的 价 值 加 上 五 分 之 一 赎 回 ； 若 不 赎 回 ， 就 要 按 你 所 估 定 的 价 值 卖 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3599', '3', '27', '28', '“ 但 一 切 永 献 的 ， 就 是 人 从 他 所 有 永 献 给 耶 和 华 的 ， 无 论 是 人 ， 是 牲 畜 ， 是 他 承 受 为 业 的 地 ， 都 不 可 卖 ， 也 不 可 赎 。 凡 永 献 的 是 归 给 耶 和 华 为 至 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3600', '3', '27', '29', '凡 从 人 中 当 灭 的 都 不 可 赎 ， 必 被 治 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3601', '3', '27', '30', '“ 地 上 所 有 的 ， 无 论 是 地 上 的 种 子 是 树 上 的 果 子 ， 十 分 之 一 是 耶 和 华 的 ， 是 归 给 耶 和 华 为 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3602', '3', '27', '31', '人 若 要 赎 这 十 分 之 一 的 什 么 物 ， 就 要 加 上 五 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3603', '3', '27', '32', '凡 牛 群 羊 群 中 ， 一 切 从 杖 下 经 过 的 ， 每 第 十 只 要 归 给 耶 和 华 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3604', '3', '27', '33', '不 可 问 是 好 是 坏 ， 也 不 可 更 换 ； 若 定 要 更 换 ， 所 更 换 的 与 本 来 的 牲 畜 都 要 成 为 圣 ， 不 可 赎 回 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3605', '3', '27', '34', '这 就 是 耶 和 华 在 西 奈 山 为 以 色 列 人 所 吩 咐 摩 西 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3606', '4', '1', '1', '＜ 以 色 列 的 第 一 次 人 口 普 查 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3607', '4', '1', '2', '“ 你 要 按 以 色 列 全 会 众 的 家 室 、 宗 族 、 人 名 的 数 目 计 算 所 有 的 男 丁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3608', '4', '1', '3', '凡 以 色 列 中 ， 从 二 十 岁 以 外 ， 能 出 去 打 仗 的 ， 你 和 亚 伦 要 照 他 们 的 军 队 数 点 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3609', '4', '1', '4', '每 支 派 中 必 有 一 人 作 本 支 派 的 族 长 ， 帮 助 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3610', '4', '1', '5', '他 们 的 名 字 ： 属 吕 便 的 ， 有 示 丢 珥 的 儿 子 以 利 蓿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3611', '4', '1', '6', '属 西 缅 的 ， 有 苏 利 沙 代 的 儿 子 示 路 蔑 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3612', '4', '1', '7', '属 犹 大 的 ， 有 亚 米 拿 达 的 儿 子 拿 顺 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3613', '4', '1', '8', '属 以 萨 迦 的 ， 有 苏 押 的 儿 子 拿 坦 业 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3614', '4', '1', '9', '属 西 布 伦 的 ， 有 希 伦 的 儿 子 以 利 押 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3615', '4', '1', '10', '约 瑟 子 孙 、 属 以 法 莲 的 ， 有 亚 米 忽 的 儿 子 以 利 沙 玛 ； 属 玛 拿 西 的 ， 有 比 大 蓿 的 儿 子 迦 玛 列 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3616', '4', '1', '11', '属 便 雅 悯 的 ， 有 基 多 尼 的 儿 子 亚 比 但 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3617', '4', '1', '12', '属 但 的 ， 有 亚 米 沙 代 的 儿 子 亚 希 以 谢 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3618', '4', '1', '13', '属 亚 设 的 ， 有 俄 兰 的 儿 子 帕 结 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3619', '4', '1', '14', '属 迦 得 的 ， 有 丢 珥 的 儿 子 以 利 雅 萨 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3620', '4', '1', '15', '属 拿 弗 他 利 的 ， 有 以 南 的 儿 子 亚 希 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3621', '4', '1', '16', '这 都 是 从 会 中 选 召 的 ， 各 作 本 支 派 的 首 领 ， 都 是 以 色 列 军 中 的 统 领 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3622', '4', '1', '17', '于 是 ， 摩 西 、 亚 伦 带 着 这 些 按 名 指 定 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3623', '4', '1', '18', '当 二 月 初 一 日 招 聚 全 会 众 。 会 众 就 照 他 们 的 家 室 、 宗 族 、 人 名 的 数 目 ， 从 二 十 岁 以 外 的 ， 都 述 说 自 己 的 家 谱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3624', '4', '1', '19', '耶 和 华 怎 样 吩 咐 摩 西 ， 他 就 怎 样 在 西 奈 的 旷 野 数 点 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3625', '4', '1', '20', '以 色 列 的 长 子 ， 吕 便 子 孙 的 后 代 ， 照 着 家 室 、 宗 族 、 人 名 的 数 目 ， 从 二 十 岁 以 外 ， 凡 能 出 去 打 仗 、 被 数 的 男 丁 ， 共 有 四 万 六 千 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3626', '4', '1', '21', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3627', '4', '1', '22', '西 缅 子 孙 的 后 代 ， 照 着 家 室 、 宗 族 、 人 名 的 数 目 ， 从 二 十 岁 以 外 ， 凡 能 出 去 打 仗 、 被 数 的 男 丁 ， 共 有 五 万 九 千 三 百 名 。');
