INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3646', '4', '1', '41', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3647', '4', '1', '42', '拿 弗 他 利 子 孙 的 后 代 ， 照 着 家 室 、 宗 族 、 人 名 的 数 目 ， 从 二 十 岁 以 外 ， 凡 能 出 去 打 仗 、 被 数 的 ， 共 有 五 万 三 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3648', '4', '1', '43', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3649', '4', '1', '44', '这 些 就 是 被 数 点 的 ， 是 摩 西 、 亚 伦 ， 和 以 色 列 中 十 二 个 首 领 所 数 点 的 ； 这 十 二 个 人 各 作 各 宗 族 的 代 表 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3650', '4', '1', '45', '这 样 ， 凡 以 色 列 人 中 被 数 的 ， 照 着 宗 族 ， 从 二 十 岁 以 外 ， 能 出 去 打 仗 、 被 数 的 ， 共 有 六 十 万 零 三 千 五 百 五 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3651', '4', '1', '46', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3652', '4', '1', '47', '利 未 人 却 没 有 按 着 支 派 数 在 其 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3653', '4', '1', '48', '因 为 耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3654', '4', '1', '49', '“ 惟 独 利 未 支 派 你 不 可 数 点 ， 也 不 可 在 以 色 列 人 中 计 算 他 们 的 总 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3655', '4', '1', '50', '只 要 派 利 未 人 管 法 柜 的 帐 幕 和 其 中 的 器 具 ， 并 属 乎 帐 幕 的 ； 他 们 要 抬 ｛ 或 译 ： 搬 运 ｝ 帐 幕 和 其 中 的 器 具 ， 并 要 办 理 帐 幕 的 事 ， 在 帐 幕 的 四 围 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3656', '4', '1', '51', '帐 幕 将 往 前 行 的 时 候 ， 利 未 人 要 拆 卸 ； 将 支 搭 的 时 候 ， 利 未 人 要 竖 起 。 近 前 来 的 外 人 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3657', '4', '1', '52', '以 色 列 人 支 搭 帐 棚 ， 要 照 他 们 的 军 队 ， 各 归 本 营 ， 各 归 本 纛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3658', '4', '1', '53', '但 利 未 人 要 在 法 柜 帐 幕 的 四 围 安 营 ， 免 得 忿 怒 临 到 以 色 列 会 众 ； 利 未 人 并 要 谨 守 法 柜 的 帐 幕 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3659', '4', '1', '54', '以 色 列 人 就 这 样 行 。 凡 耶 和 华 所 吩 咐 摩 西 的 ， 他 们 就 照 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3660', '4', '2', '1', '＜ 各 支 派 在 营 地 的 位 置 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3661', '4', '2', '2', '“ 以 色 列 人 要 各 归 自 己 的 纛 下 ， 在 本 族 的 旗 号 那 里 ， 对 着 会 幕 的 四 围 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3662', '4', '2', '3', '在 东 边 ， 向 日 出 之 地 ， 照 着 军 队 安 营 的 是 犹 大 营 的 纛 。 有 亚 米 拿 达 的 儿 子 拿 顺 作 犹 大 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3663', '4', '2', '4', '他 军 队 被 数 的 ， 共 有 七 万 四 千 六 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3664', '4', '2', '5', '挨 着 他 安 营 的 是 以 萨 迦 支 派 。 有 苏 押 的 儿 子 拿 坦 业 作 以 萨 迦 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3665', '4', '2', '6', '他 军 队 被 数 的 ， 共 有 五 万 四 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3666', '4', '2', '7', '又 有 西 布 伦 支 派 。 希 伦 的 儿 子 以 利 押 作 西 布 伦 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3667', '4', '2', '8', '他 军 队 被 数 的 ， 共 有 五 万 七 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3668', '4', '2', '9', '凡 属 犹 大 营 、 按 着 军 队 被 数 的 ， 共 有 十 八 万 六 千 四 百 名 ， 要 作 第 一 队 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3669', '4', '2', '10', '“ 在 南 边 ， 按 着 军 队 是 吕 便 营 的 纛 。 有 示 丢 珥 的 儿 子 以 利 蓿 作 吕 便 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3670', '4', '2', '11', '他 军 队 被 数 的 ， 共 有 四 万 六 千 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3671', '4', '2', '12', '挨 着 他 安 营 的 是 西 缅 支 派 。 苏 利 沙 代 的 儿 子 示 路 蔑 作 西 缅 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3672', '4', '2', '13', '他 军 队 被 数 的 ， 共 有 五 万 九 千 三 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3673', '4', '2', '14', '又 有 迦 得 支 派 。 丢 珥 的 儿 子 以 利 雅 萨 作 迦 得 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3674', '4', '2', '15', '他 军 队 被 数 的 ， 共 有 四 万 五 千 六 百 五 十 名 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3675', '4', '2', '16', '凡 属 吕 便 营 、 按 着 军 队 被 数 的 ， 共 有 十 五 万 一 千 四 百 五 十 名 ， 要 作 第 二 队 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3676', '4', '2', '17', '“ 随 后 ， 会 幕 要 往 前 行 ， 有 利 未 营 在 诸 营 中 间 。 他 们 怎 样 安 营 就 怎 样 往 前 行 ， 各 按 本 位 ， 各 归 本 纛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3677', '4', '2', '18', '“ 在 西 边 ， 按 着 军 队 是 以 法 莲 营 的 纛 。 亚 米 忽 的 儿 子 以 利 沙 玛 作 以 法 莲 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3678', '4', '2', '19', '他 军 队 被 数 的 ， 共 有 四 万 零 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3679', '4', '2', '20', '挨 着 他 的 是 玛 拿 西 支 派 。 比 大 蓿 的 儿 子 迦 玛 列 作 玛 拿 西 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3680', '4', '2', '21', '他 军 队 被 数 的 ， 共 有 三 万 二 千 二 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3681', '4', '2', '22', '又 有 便 雅 悯 支 派 。 基 多 尼 的 儿 子 亚 比 但 作 便 雅 悯 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3682', '4', '2', '23', '他 军 队 被 数 的 ， 共 有 三 万 五 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3683', '4', '2', '24', '凡 属 以 法 莲 营 、 按 着 军 队 被 数 的 ， 共 有 十 万 零 八 千 一 百 名 ， 要 作 第 三 队 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3684', '4', '2', '25', '“ 在 北 边 ， 按 着 军 队 是 但 营 的 纛 。 亚 米 沙 代 的 儿 子 亚 希 以 谢 作 但 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3685', '4', '2', '26', '他 军 队 被 数 的 ， 共 有 六 万 二 千 七 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3686', '4', '2', '27', '挨 着 他 安 营 的 是 亚 设 支 派 。 俄 兰 的 儿 子 帕 结 作 亚 设 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3687', '4', '2', '28', '他 军 队 被 数 的 ， 共 有 四 万 一 千 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3688', '4', '2', '29', '又 有 拿 弗 他 利 支 派 。 以 南 的 儿 子 亚 希 拉 作 拿 弗 他 利 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3689', '4', '2', '30', '他 军 队 被 数 的 ， 共 有 五 万 三 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3690', '4', '2', '31', '凡 但 营 被 数 的 ， 共 有 十 五 万 七 千 六 百 名 ， 要 归 本 纛 作 末 队 往 前 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3691', '4', '2', '32', '这 些 以 色 列 人 ， 照 他 们 的 宗 族 ， 按 他 们 的 军 队 ， 在 诸 营 中 被 数 的 ， 共 有 六 十 万 零 三 千 五 百 五 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3692', '4', '2', '33', '惟 独 利 未 人 没 有 数 在 以 色 列 人 中 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3693', '4', '2', '34', '以 色 列 人 就 这 样 行 ， 各 人 照 他 们 的 家 室 、 宗 族 归 于 本 纛 ， 安 营 起 行 ， 都 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3694', '4', '3', '1', '＜ 亚 伦 的 儿 子 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3695', '4', '3', '2', '亚 伦 的 儿 子 ， 长 子 名 叫 拿 答 ， 还 有 亚 比 户 、 以 利 亚 撒 、 以 他 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3696', '4', '3', '3', '这 是 亚 伦 儿 子 的 名 字 ， 都 是 受 膏 的 祭 司 ， 是 摩 西 叫 他 们 承 接 圣 职 供 祭 司 职 分 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3697', '4', '3', '4', '拿 答 、 亚 比 户 在 西 奈 的 旷 野 向 耶 和 华 献 凡 火 的 时 候 就 死 在 耶 和 华 面 前 了 。 他 们 也 没 有 儿 子 。 以 利 亚 撒 、 以 他 玛 在 他 们 的 父 亲 亚 伦 面 前 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3698', '4', '3', '5', '＜ 利 未 人 被 派 作 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3699', '4', '3', '6', '“ 你 使 利 未 支 派 近 前 来 ， 站 在 祭 司 亚 伦 面 前 好 服 事 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3700', '4', '3', '7', '替 他 和 会 众 在 会 幕 前 守 所 吩 咐 的 ， 办 理 帐 幕 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3701', '4', '3', '8', '又 要 看 守 会 幕 的 器 具 ， 并 守 所 吩 咐 以 色 列 人 的 ， 办 理 帐 幕 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3702', '4', '3', '9', '你 要 将 利 未 人 给 亚 伦 和 他 的 儿 子 ， 因 为 他 们 是 从 以 色 列 人 中 选 出 来 给 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3703', '4', '3', '10', '你 要 嘱 咐 亚 伦 和 他 的 儿 子 谨 守 自 己 祭 司 的 职 任 。 近 前 来 的 外 人 必 被 治 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3704', '4', '3', '11', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3705', '4', '3', '12', '“ 我 从 以 色 列 人 中 拣 选 了 利 未 人 ， 代 替 以 色 列 人 一 切 头 生 的 ； 利 未 人 要 归 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3706', '4', '3', '13', '因 为 凡 头 生 的 是 我 的 ； 我 在 埃 及 地 击 杀 一 切 头 生 的 那 日 就 把 以 色 列 中 一 切 头 生 的 ， 连 人 带 牲 畜 都 分 别 为 圣 归 我 ； 他 们 定 要 属 我 。 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3707', '4', '3', '14', '＜ 利 未 人 男 丁 的 统 计 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3708', '4', '3', '15', '“ 你 要 照 利 未 人 的 宗 族 、 家 室 数 点 他 们 。 凡 一 个 月 以 外 的 男 子 都 要 数 点 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3709', '4', '3', '16', '于 是 摩 西 照 耶 和 华 所 吩 咐 的 数 点 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3710', '4', '3', '17', '利 未 众 子 的 名 字 是 革 顺 、 哥 辖 、 米 拉 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3711', '4', '3', '18', '革 顺 的 儿 子 ， 按 着 家 室 ， 是 立 尼 、 示 每 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3712', '4', '3', '19', '哥 辖 的 儿 子 ， 按 着 家 室 ， 是 暗 兰 、 以 斯 哈 、 希 伯 伦 、 乌 薛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3713', '4', '3', '20', '米 拉 利 的 儿 子 ， 按 着 家 室 ， 是 抹 利 、 母 示 。 这 些 按 着 宗 族 是 利 未 人 的 家 室 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3714', '4', '3', '21', '属 革 顺 的 ， 有 立 尼 族 、 示 每 族 。 这 是 革 顺 的 二 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3715', '4', '3', '22', '其 中 被 数 、 从 一 个 月 以 外 所 有 的 男 子 共 有 七 千 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3716', '4', '3', '23', '这 革 顺 的 二 族 要 在 帐 幕 后 西 边 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3717', '4', '3', '24', '拉 伊 勒 的 儿 子 以 利 雅 萨 作 革 顺 人 宗 族 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3718', '4', '3', '25', '革 顺 的 子 孙 在 会 幕 中 所 要 看 守 的 ， 就 是 帐 幕 和 罩 棚 ， 并 罩 棚 的 盖 与 会 幕 的 门 帘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3719', '4', '3', '26', '院 子 的 帷 子 和 门 帘 （ 院 子 是 围 帐 幕 和 坛 的 ） ， 并 一 切 使 用 的 绳 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3720', '4', '3', '27', '属 哥 辖 的 ， 有 暗 兰 族 、 以 斯 哈 族 、 希 伯 伦 族 、 乌 薛 族 。 这 是 哥 辖 的 诸 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3721', '4', '3', '28', '按 所 有 男 子 的 数 目 ， 从 一 个 月 以 外 看 守 圣 所 的 ， 共 有 八 千 六 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3722', '4', '3', '29', '哥 辖 儿 子 的 诸 族 要 在 帐 幕 的 南 边 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3723', '4', '3', '30', '乌 薛 的 儿 子 以 利 撒 反 作 哥 辖 宗 族 家 室 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3724', '4', '3', '31', '他 们 所 要 看 守 的 是 约 柜 、 桌 子 、 灯 台 、 两 座 坛 与 圣 所 内 使 用 的 器 皿 ， 并 帘 子 和 一 切 使 用 之 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3725', '4', '3', '32', '祭 司 亚 伦 的 儿 子 以 利 亚 撒 作 利 未 人 众 首 领 的 领 袖 ， 要 监 察 那 些 看 守 圣 所 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3726', '4', '3', '33', '属 米 拉 利 的 ， 有 抹 利 族 、 母 示 族 。 这 是 米 拉 利 的 二 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3727', '4', '3', '34', '他 们 被 数 的 ， 按 所 有 男 子 的 数 目 ， 从 一 个 月 以 外 的 ， 共 有 六 千 二 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3728', '4', '3', '35', '亚 比 亥 的 儿 子 苏 列 作 米 拉 利 二 宗 族 的 首 领 。 他 们 要 在 帐 幕 的 北 边 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3729', '4', '3', '36', '米 拉 利 子 孙 的 职 分 是 看 守 帐 幕 的 板 、 闩 、 柱 子 、 带 卯 的 座 ， 和 帐 幕 一 切 所 使 用 的 器 具 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3730', '4', '3', '37', '院 子 四 围 的 柱 子 、 带 卯 的 座 、 橛 子 ， 和 绳 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3731', '4', '3', '38', '在 帐 幕 前 东 边 ， 向 日 出 之 地 安 营 的 是 摩 西 、 亚 伦 ， 和 亚 伦 的 儿 子 。 他 们 看 守 圣 所 ， 替 以 色 列 人 守 耶 和 华 所 吩 咐 的 。 近 前 来 的 外 人 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3732', '4', '3', '39', '凡 被 数 的 利 未 人 ， 就 是 摩 西 、 亚 伦 照 耶 和 华 吩 咐 所 数 的 ， 按 着 家 室 ， 从 一 个 月 以 外 的 男 子 ， 共 有 二 万 二 千 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3733', '4', '3', '40', '＜ 利 未 人 代 替 长 子 的 地 位 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3734', '4', '3', '41', '我 是 耶 和 华 。 你 要 拣 选 利 未 人 归 我 ， 代 替 以 色 列 人 所 有 头 生 的 ， 也 取 利 未 人 的 牲 畜 代 替 以 色 列 所 有 头 生 的 牲 畜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3735', '4', '3', '42', '摩 西 就 照 耶 和 华 所 吩 咐 的 把 以 色 列 人 头 生 的 都 数 点 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3736', '4', '3', '43', '按 人 名 的 数 目 ， 从 一 个 月 以 外 、 凡 头 生 的 男 子 ， 共 有 二 万 二 千 二 百 七 十 三 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3737', '4', '3', '44', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3738', '4', '3', '45', '“ 你 拣 选 利 未 人 代 替 以 色 列 人 所 有 头 生 的 ， 也 取 利 未 人 的 牲 畜 代 替 以 色 列 人 的 牲 畜 。 利 未 人 要 归 我 ； 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3739', '4', '3', '46', '以 色 列 人 中 头 生 的 男 子 比 利 未 人 多 二 百 七 十 三 个 ， 必 当 将 他 们 赎 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3740', '4', '3', '47', '你 要 按 人 丁 ， 照 圣 所 的 平 ， 每 人 取 赎 银 五 舍 客 勒 （ 一 舍 客 勒 是 二 十 季 拉 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3741', '4', '3', '48', '把 那 多 余 之 人 的 赎 银 交 给 亚 伦 和 他 的 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3742', '4', '3', '49', '于 是 摩 西 从 那 被 利 未 人 所 赎 以 外 的 人 取 了 赎 银 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3743', '4', '3', '50', '从 以 色 列 人 头 生 的 所 取 之 银 ， 按 圣 所 的 平 ， 有 一 千 三 百 六 十 五 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3744', '4', '3', '51', '摩 西 照 耶 和 华 的 话 把 这 赎 银 给 亚 伦 和 他 的 儿 子 ， 正 如 耶 和 华 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3745', '4', '4', '1', '＜ 哥 辖 子 孙 的 职 责 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3746', '4', '4', '2', '“ 你 从 利 未 人 中 ， 将 哥 辖 子 孙 的 总 数 ， 照 他 们 的 家 室 、 宗 族 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3747', '4', '4', '3', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 办 事 的 ， 全 都 计 算 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3748', '4', '4', '4', '哥 辖 子 孙 在 会 幕 搬 运 至 圣 之 物 ， 所 办 的 事 乃 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3749', '4', '4', '5', '起 营 的 时 候 ， 亚 伦 和 他 儿 子 要 进 去 摘 下 遮 掩 柜 的 幔 子 ， 用 以 蒙 盖 法 柜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3750', '4', '4', '6', '又 用 海 狗 皮 盖 在 上 头 ， 再 蒙 上 纯 蓝 色 的 毯 子 ， 把 杠 穿 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3751', '4', '4', '7', '又 用 蓝 色 毯 子 铺 在 陈 设 饼 的 桌 子 上 ， 将 盘 子 、 调 羹 、 奠 酒 的 爵 ， 和 杯 摆 在 上 头 。 桌 子 上 也 必 有 常 设 的 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3752', '4', '4', '8', '在 其 上 又 要 蒙 朱 红 色 的 毯 子 ， 再 蒙 上 海 狗 皮 ， 把 杠 穿 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3753', '4', '4', '9', '要 拿 蓝 色 毯 子 ， 把 灯 台 和 灯 台 上 所 用 的 灯 盏 、 剪 子 、 蜡 花 盘 ， 并 一 切 盛 油 的 器 皿 ， 全 都 遮 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3754', '4', '4', '10', '又 要 把 灯 台 和 灯 台 的 一 切 器 具 包 在 海 狗 皮 里 ， 放 在 抬 架 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3755', '4', '4', '11', '在 金 坛 上 要 铺 蓝 色 毯 子 ， 蒙 上 海 狗 皮 ， 把 杠 穿 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3756', '4', '4', '12', '又 要 把 圣 所 用 的 一 切 器 具 包 在 蓝 色 毯 子 里 ， 用 海 狗 皮 蒙 上 ， 放 在 抬 架 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3757', '4', '4', '13', '要 收 去 坛 上 的 灰 ， 把 紫 色 毯 子 铺 在 坛 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3758', '4', '4', '14', '又 要 把 所 用 的 一 切 器 具 ， 就 是 火 鼎 、 肉 锸 子 、 铲 子 、 盘 子 ， 一 切 属 坛 的 器 具 都 摆 在 坛 上 ， 又 蒙 上 海 狗 皮 ， 把 杠 穿 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3759', '4', '4', '15', '将 要 起 营 的 时 候 ， 亚 伦 和 他 儿 子 把 圣 所 和 圣 所 的 一 切 器 具 遮 盖 完 了 ， 哥 辖 的 子 孙 就 要 来 抬 ， 只 是 不 可 摸 圣 物 ， 免 得 他 们 死 亡 。 会 幕 里 这 些 物 件 是 哥 辖 子 孙 所 当 抬 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3760', '4', '4', '16', '“ 祭 司 亚 伦 的 儿 子 以 利 亚 撒 所 要 看 守 的 是 点 灯 的 油 与 香 料 ， 并 当 献 的 素 祭 和 膏 油 ， 也 要 看 守 全 帐 幕 与 其 中 所 有 的 ， 并 圣 所 和 圣 所 的 器 具 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3761', '4', '4', '17', '耶 和 华 晓 谕 摩 西 、 亚 伦 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3762', '4', '4', '18', '“ 你 们 不 可 将 哥 辖 人 的 支 派 从 利 未 人 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3763', '4', '4', '19', '他 们 挨 近 至 圣 物 的 时 候 ， 亚 伦 和 他 儿 子 要 进 去 派 他 们 各 人 所 当 办 的 ， 所 当 抬 的 。 这 样 待 他 们 ， 好 使 他 们 活 着 ， 不 致 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3764', '4', '4', '20', '只 是 他 们 连 片 时 不 可 进 去 观 看 圣 所 ， 免 得 他 们 死 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3765', '4', '4', '21', '＜ 革 顺 子 孙 的 职 责 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3766', '4', '4', '22', '“ 你 要 将 革 顺 子 孙 的 总 数 ， 照 着 宗 族 、 家 室 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3767', '4', '4', '23', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 办 事 的 ， 全 都 数 点 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3768', '4', '4', '24', '＜ 利 未 支 派 男 丁 的 统 计 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3769', '4', '4', '25', '他 们 要 抬 帐 幕 的 幔 子 和 会 幕 ， 并 会 幕 的 盖 与 其 上 的 海 狗 皮 ， 和 会 幕 的 门 帘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3770', '4', '4', '26', '院 子 的 帷 子 和 门 帘 （ 院 子 是 围 帐 幕 和 坛 的 ） 、 绳 子 ， 并 所 用 的 器 具 ， 不 论 是 做 什 么 用 的 ， 他 们 都 要 经 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3771', '4', '4', '27', '革 顺 的 子 孙 在 一 切 抬 物 办 事 之 上 都 要 凭 亚 伦 和 他 儿 子 的 吩 咐 ； 他 们 所 当 抬 的 ， 要 派 他 们 看 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3772', '4', '4', '28', '这 是 革 顺 子 孙 的 各 族 在 会 幕 里 所 办 的 事 ； 他 们 所 看 守 的 ， 必 在 祭 司 亚 伦 儿 子 以 他 玛 的 手 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3773', '4', '4', '29', '＜ 米 拉 利 子 孙 的 职 责 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3774', '4', '4', '30', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 办 事 的 ， 你 都 要 数 点 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3775', '4', '4', '31', '他 们 办 理 会 幕 的 事 ， 就 是 抬 帐 幕 的 板 、 闩 、 柱 子 ， 和 带 卯 的 座 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3776', '4', '4', '32', '院 子 四 围 的 柱 子 和 其 上 带 卯 的 座 、 橛 子 、 绳 子 ， 并 一 切 使 用 的 器 具 。 他 们 所 抬 的 器 具 ， 你 们 要 按 名 指 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3777', '4', '4', '33', '这 是 米 拉 利 子 孙 各 族 在 会 幕 里 所 办 的 事 ， 都 在 祭 司 亚 伦 儿 子 以 他 玛 的 手 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3778', '4', '4', '34', '＜ 利 未 支 派 男 丁 的 统 计 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3779', '4', '4', '35', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 办 事 的 ， 都 数 点 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3780', '4', '4', '36', '被 数 的 共 有 二 千 七 百 五 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3781', '4', '4', '37', '这 是 哥 辖 各 族 中 被 数 的 ， 是 在 会 幕 里 办 事 的 ， 就 是 摩 西 、 亚 伦 照 耶 和 华 藉 摩 西 所 吩 咐 数 点 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3782', '4', '4', '38', '革 顺 子 孙 被 数 的 ， 照 着 家 室 、 宗 族 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3783', '4', '4', '39', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 办 事 的 ， 共 有 二 千 六 百 三 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3784', '4', '4', '40', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3785', '4', '4', '41', '这 是 革 顺 子 孙 各 族 中 被 数 的 ， 是 在 会 幕 里 办 事 的 ， 就 是 摩 西 、 亚 伦 照 耶 和 华 藉 摩 西 所 吩 咐 数 点 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3786', '4', '4', '42', '米 拉 利 子 孙 中 各 族 被 数 的 ， 照 着 家 室 、 宗 族 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3787', '4', '4', '43', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 办 事 的 ， 共 有 三 千 二 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3788', '4', '4', '44', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3789', '4', '4', '45', '这 是 米 拉 利 子 孙 各 族 中 被 数 的 ， 就 是 摩 西 、 亚 伦 照 耶 和 华 藉 摩 西 所 吩 咐 数 点 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3790', '4', '4', '46', '凡 被 数 的 利 未 人 ， 就 是 摩 西 、 亚 伦 并 以 色 列 众 首 领 ， 照 着 家 室 、 宗 族 所 数 点 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3791', '4', '4', '47', '从 三 十 岁 直 到 五 十 岁 ， 凡 前 来 任 职 、 在 会 幕 里 做 抬 物 之 工 的 ， 共 有 八 千 五 百 八 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3792', '4', '4', '48', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3793', '4', '4', '49', '摩 西 按 他 们 所 办 的 事 、 所 抬 的 物 ， 凭 耶 和 华 的 吩 咐 数 点 他 们 ； 他 们 这 样 被 摩 西 数 点 ， 正 如 耶 和 华 所 吩 咐 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3794', '4', '5', '1', '＜ 不 洁 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3795', '4', '5', '2', '“ 你 吩 咐 以 色 列 人 ， 使 一 切 长 大 痲 疯 的 ， 患 漏 症 的 ， 并 因 死 尸 不 洁 净 的 ， 都 出 营 外 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3796', '4', '5', '3', '无 论 男 女 都 要 使 他 们 出 到 营 外 ， 免 得 污 秽 他 们 的 营 ； 这 营 是 我 所 住 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3797', '4', '5', '4', '以 色 列 人 就 这 样 行 ， 使 他 们 出 到 营 外 。 耶 和 华 怎 样 吩 咐 摩 西 ， 以 色 列 人 就 怎 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3798', '4', '5', '5', '＜ 赔 偿 亏 负 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3799', '4', '5', '6', '“ 你 晓 谕 以 色 列 人 说 ： 无 论 男 女 ， 若 犯 了 人 所 常 犯 的 罪 ， 以 致 干 犯 耶 和 华 ， 那 人 就 有 了 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3800', '4', '5', '7', '他 要 承 认 所 犯 的 罪 ， 将 所 亏 负 人 的 ， 如 数 赔 还 ， 另 外 加 上 五 分 之 一 ， 也 归 与 所 亏 负 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3801', '4', '5', '8', '那 人 若 没 有 亲 属 可 受 所 赔 还 的 ， 那 所 赔 还 的 就 要 归 与 服 事 耶 和 华 的 祭 司 ； 至 于 那 为 他 赎 罪 的 公 羊 是 在 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3802', '4', '5', '9', '以 色 列 人 一 切 的 圣 物 中 ， 所 奉 给 祭 司 的 举 祭 都 要 归 与 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3803', '4', '5', '10', '各 人 所 分 别 为 圣 的 物 ， 无 论 是 什 么 ， 都 要 归 给 祭 司 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3804', '4', '5', '11', '＜ 疑 妻 不 贞 的 案 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3805', '4', '5', '12', '“ 你 晓 谕 以 色 列 人 说 ： 人 的 妻 若 有 邪 行 ， 得 罪 她 丈 夫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3806', '4', '5', '13', '有 人 与 她 行 淫 ， 事 情 严 密 ， 瞒 过 她 丈 夫 ， 而 且 她 被 玷 污 ， 没 有 作 见 证 的 人 ， 当 她 行 淫 的 时 候 也 没 有 被 捉 住 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3807', '4', '5', '14', '她 丈 夫 生 了 疑 恨 的 心 ， 疑 恨 她 ， 她 是 被 玷 污 ， 或 是 她 丈 夫 生 了 疑 恨 的 心 ， 疑 恨 她 ， 她 并 没 有 被 玷 污 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3808', '4', '5', '15', '这 人 就 要 将 妻 送 到 祭 司 那 里 ， 又 为 她 带 着 大 麦 面 伊 法 十 分 之 一 作 供 物 ， 不 可 浇 上 油 ， 也 不 可 加 上 乳 香 ； 因 为 这 是 疑 恨 的 素 祭 ， 是 思 念 的 素 祭 ， 使 人 思 念 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3809', '4', '5', '16', '“ 祭 司 要 使 那 妇 人 近 前 来 ， 站 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3810', '4', '5', '17', '祭 司 要 把 圣 水 盛 在 瓦 器 里 ， 又 从 帐 幕 的 地 上 取 点 尘 土 ， 放 在 水 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3811', '4', '5', '18', '祭 司 要 叫 那 妇 人 蓬 头 散 发 ， 站 在 耶 和 华 面 前 ， 把 思 念 的 素 祭 ， 就 是 疑 恨 的 素 祭 ， 放 在 她 手 中 。 祭 司 手 里 拿 着 致 咒 诅 的 苦 水 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3812', '4', '5', '19', '要 叫 妇 人 起 誓 ， 对 她 说 ： ‘ 若 没 有 人 与 你 行 淫 ， 也 未 曾 背 着 丈 夫 做 污 秽 的 事 ， 你 就 免 受 这 致 咒 诅 苦 水 的 灾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3813', '4', '5', '20', '你 若 背 着 丈 夫 行 了 污 秽 的 事 ， 在 你 丈 夫 以 外 有 人 与 你 行 淫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3814', '4', '5', '21', '（ 祭 司 叫 妇 人 发 咒 起 誓 ） ， 愿 耶 和 华 叫 你 大 腿 消 瘦 ， 肚 腹 发 胀 ， 使 你 在 你 民 中 被 人 咒 诅 ， 成 了 誓 语 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3815', '4', '5', '22', '并 且 这 致 咒 诅 的 水 入 你 的 肠 中 ， 要 叫 你 的 肚 腹 发 胀 ， 大 腿 消 瘦 。 ’ 妇 人 要 回 答 说 ： ‘ 阿 们 ， 阿 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3816', '4', '5', '23', '“ 祭 司 要 写 这 咒 诅 的 话 ， 将 所 写 的 字 抹 在 苦 水 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3817', '4', '5', '24', '又 叫 妇 人 喝 这 致 咒 诅 的 苦 水 ； 这 水 要 进 入 她 里 面 变 苦 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3818', '4', '5', '25', '祭 司 要 从 妇 人 的 手 中 取 那 疑 恨 的 素 祭 ， 在 耶 和 华 面 前 摇 一 摇 ， 拿 到 坛 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3819', '4', '5', '26', '又 要 从 素 祭 中 取 出 一 把 ， 作 为 这 事 的 纪 念 ， 烧 在 坛 上 ， 然 后 叫 妇 人 喝 这 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3820', '4', '5', '27', '叫 她 喝 了 以 后 ， 她 若 被 玷 污 ， 得 罪 了 丈 夫 ， 这 致 咒 诅 的 水 必 进 入 她 里 面 变 苦 了 ， 她 的 肚 腹 就 要 发 胀 ， 大 腿 就 要 消 瘦 ， 那 妇 人 便 要 在 他 民 中 被 人 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3821', '4', '5', '28', '若 妇 人 没 有 被 玷 污 ， 却 是 清 洁 的 ， 就 要 免 受 这 灾 ， 且 要 怀 孕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3822', '4', '5', '29', '“ 妻 子 背 着 丈 夫 行 了 污 秽 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3823', '4', '5', '30', '或 是 人 生 了 疑 恨 的 心 ， 疑 恨 他 的 妻 ， 就 有 这 疑 恨 的 条 例 。 那 时 他 要 叫 妇 人 站 在 耶 和 华 面 前 ， 祭 司 要 在 她 身 上 照 这 条 例 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3824', '4', '5', '31', '男 人 就 为 无 罪 ， 妇 人 必 担 当 自 己 的 罪 孽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3825', '4', '6', '1', '＜ 拿 细 耳 人 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3826', '4', '6', '2', '“ 你 晓 谕 以 色 列 人 说 ： 无 论 男 女 许 了 特 别 的 愿 ， 就 是 拿 细 耳 人 的 愿 ｛ 拿 细 耳 就 是 归 主 的 意 思 ； 下 同 ｝ ， 要 离 俗 归 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3827', '4', '6', '3', '他 就 要 远 离 清 酒 浓 酒 ， 也 不 可 喝 什 么 清 酒 浓 酒 做 的 醋 ； 不 可 喝 什 么 葡 萄 汁 ， 也 不 可 吃 鲜 葡 萄 和 干 葡 萄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3828', '4', '6', '4', '在 一 切 离 俗 的 日 子 ， 凡 葡 萄 树 上 结 的 ， 自 核 至 皮 所 做 的 物 ， 都 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3829', '4', '6', '5', '“ 在 他 一 切 许 愿 离 俗 的 日 子 ， 不 可 用 剃 头 刀 剃 头 ， 要 由 发 绺 长 长 了 。 他 要 圣 洁 ， 直 到 离 俗 归 耶 和 华 的 日 子 满 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3830', '4', '6', '6', '在 他 离 俗 归 耶 和 华 的 一 切 日 子 ， 不 可 挨 近 死 尸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3831', '4', '6', '7', '他 的 父 母 或 是 弟 兄 姊 妹 死 了 的 时 候 ， 他 不 可 因 他 们 使 自 己 不 洁 净 ， 因 为 那 离 俗 归 神 的 凭 据 是 在 他 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3832', '4', '6', '8', '在 他 一 切 离 俗 的 日 子 是 归 耶 和 华 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3833', '4', '6', '9', '“ 若 在 他 旁 边 忽 然 有 人 死 了 ， 以 致 沾 染 了 他 离 俗 的 头 ， 他 要 在 第 七 日 ， 得 洁 净 的 时 候 ， 剃 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3834', '4', '6', '10', '第 八 日 ， 他 要 把 两 只 斑 鸠 或 两 只 雏 鸽 带 到 会 幕 门 口 ， 交 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3835', '4', '6', '11', '祭 司 要 献 一 只 作 赎 罪 祭 ， 一 只 作 燔 祭 ， 为 他 赎 那 因 死 尸 而 有 的 罪 ， 并 要 当 日 使 他 的 头 成 为 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3836', '4', '6', '12', '他 要 另 选 离 俗 归 耶 和 华 的 日 子 ， 又 要 牵 一 只 一 岁 的 公 羊 羔 来 作 赎 愆 祭 ； 但 先 前 的 日 子 要 归 徒 然 ， 因 为 他 在 离 俗 之 间 被 玷 污 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3837', '4', '6', '13', '“ 拿 细 耳 人 满 了 离 俗 的 日 子 乃 有 这 条 例 ： 人 要 领 他 到 会 幕 门 口 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3838', '4', '6', '14', '他 要 将 供 物 奉 给 耶 和 华 ， 就 是 一 只 没 有 残 疾 、 一 岁 的 公 羊 羔 作 燔 祭 ， 一 只 没 有 残 疾 、 一 岁 的 母 羊 羔 作 赎 罪 祭 ， 和 一 只 没 有 残 疾 的 公 绵 羊 作 平 安 祭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3839', '4', '6', '15', '并 一 筐 子 无 酵 调 油 的 细 面 饼 ， 与 抹 油 的 无 酵 薄 饼 ， 并 同 献 的 素 祭 和 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3840', '4', '6', '16', '祭 司 要 在 耶 和 华 面 前 献 那 人 的 赎 罪 祭 和 燔 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3841', '4', '6', '17', '也 要 把 那 只 公 羊 和 那 筐 无 酵 饼 献 给 耶 和 华 作 平 安 祭 ， 又 要 将 同 献 的 素 祭 和 奠 祭 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3842', '4', '6', '18', '拿 细 耳 人 要 在 会 幕 门 口 剃 离 俗 的 头 ， 把 离 俗 头 上 的 发 放 在 平 安 祭 下 的 火 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3843', '4', '6', '19', '他 剃 了 以 后 ， 祭 司 就 要 取 那 已 煮 的 公 羊 一 条 前 腿 ， 又 从 筐 子 里 取 一 个 无 酵 饼 和 一 个 无 酵 薄 饼 ， 都 放 在 他 手 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3844', '4', '6', '20', '祭 司 要 拿 这 些 作 为 摇 祭 ， 在 耶 和 华 面 前 摇 一 摇 ； 这 与 所 摇 的 胸 、 所 举 的 腿 同 为 圣 物 ， 归 给 祭 司 。 然 后 拿 细 耳 人 可 以 喝 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3845', '4', '6', '21', '“ 许 愿 的 拿 细 耳 人 为 离 俗 所 献 的 供 物 ， 和 他 以 外 所 能 得 的 献 给 耶 和 华 ， 就 有 这 条 例 。 他 怎 样 许 愿 就 当 照 离 俗 的 条 例 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3846', '4', '6', '22', '＜ 祭 司 的 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3847', '4', '6', '23', '“ 你 告 诉 亚 伦 和 他 儿 子 说 ： 你 们 要 这 样 为 以 色 列 人 祝 福 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3848', '4', '6', '24', '‘ 愿 耶 和 华 赐 福 给 你 ， 保 护 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3849', '4', '6', '25', '愿 耶 和 华 使 他 的 脸 光 照 你 ， 赐 恩 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3850', '4', '6', '26', '愿 耶 和 华 向 你 仰 脸 ， 赐 你 平 安 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3851', '4', '6', '27', '他 们 要 如 此 奉 我 的 名 为 以 色 列 人 祝 福 ； 我 也 要 赐 福 给 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3852', '4', '7', '1', '＜ 各 族 长 奉 献 祭 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3853', '4', '7', '2', '当 天 ， 以 色 列 的 众 首 领 ， 就 是 各 族 的 族 长 ， 都 来 奉 献 。 他 们 是 各 支 派 的 首 领 ， 管 理 那 些 被 数 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3854', '4', '7', '3', '他 们 把 自 己 的 供 物 送 到 耶 和 华 面 前 ， 就 是 六 辆 篷 子 车 和 十 二 只 公 牛 。 每 两 个 首 领 奉 献 一 辆 车 ， 每 首 领 奉 献 一 只 牛 。 他 们 把 这 些 都 奉 到 帐 幕 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3855', '4', '7', '4', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3856', '4', '7', '5', '“ 你 要 收 下 这 些 ， 好 作 会 幕 的 使 用 ， 都 要 照 利 未 人 所 办 的 事 交 给 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3857', '4', '7', '6', '于 是 摩 西 收 了 车 和 牛 ， 交 给 利 未 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3858', '4', '7', '7', '把 两 辆 车 ， 四 只 牛 ， 照 革 顺 子 孙 所 办 的 事 交 给 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3859', '4', '7', '8', '又 把 四 辆 车 ， 八 只 牛 ， 照 米 拉 利 子 孙 所 办 的 事 交 给 他 们 ； 他 们 都 在 祭 司 亚 伦 的 儿 子 以 他 玛 手 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3860', '4', '7', '9', '但 车 与 牛 都 没 有 交 给 哥 辖 子 孙 ； 因 为 他 们 办 的 是 圣 所 的 事 ， 在 肩 头 上 抬 圣 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3861', '4', '7', '10', '用 膏 抹 坛 的 日 子 ， 首 领 都 来 行 奉 献 坛 的 礼 ， 众 首 领 就 在 坛 前 献 供 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3862', '4', '7', '11', '耶 和 华 对 摩 西 说 ： “ 众 首 领 为 行 奉 献 坛 的 礼 ， 要 每 天 一 个 首 领 来 献 供 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3863', '4', '7', '12', '头 一 日 献 供 物 的 是 犹 大 支 派 的 亚 米 拿 达 的 儿 子 拿 顺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3864', '4', '7', '13', '他 的 供 物 是 ： 一 个 银 盘 子 ， 重 一 百 三 十 舍 客 勒 ， 一 个 银 碗 ， 重 七 十 舍 客 勒 ， 都 是 按 圣 所 的 平 ， 也 都 盛 满 了 调 油 的 细 面 作 素 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3865', '4', '7', '14', '一 个 金 盂 ， 重 十 舍 客 勒 ， 盛 满 了 香 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3866', '4', '7', '15', '一 只 公 牛 犊 ， 一 只 公 绵 羊 ， 一 只 一 岁 的 公 羊 羔 作 燔 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3867', '4', '7', '16', '一 只 公 山 羊 作 赎 罪 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3868', '4', '7', '17', '两 只 公 牛 ， 五 只 公 绵 羊 ， 五 只 公 山 羊 ， 五 只 一 岁 的 公 羊 羔 作 平 安 祭 。 这 是 亚 米 拿 达 儿 子 拿 顺 的 供 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3869', '4', '7', '18', '第 二 日 来 献 的 是 以 萨 迦 子 孙 的 首 领 、 苏 押 的 儿 子 拿 坦 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3870', '4', '7', '19', '他 献 为 供 物 的 是 ： 一 个 银 盘 子 ， 重 一 百 三 十 舍 客 勒 ， 一 个 银 碗 ， 重 七 十 舍 客 勒 ， 都 是 按 圣 所 的 平 ， 也 都 盛 满 了 调 油 的 细 面 作 素 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3871', '4', '7', '20', '一 个 金 盂 ， 重 十 舍 客 勒 ， 盛 满 了 香 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3872', '4', '7', '21', '一 只 公 牛 犊 ， 一 只 公 绵 羊 ， 一 只 一 岁 的 公 羊 羔 作 燔 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3873', '4', '7', '22', '一 只 公 山 羊 作 赎 罪 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3874', '4', '7', '23', '两 只 公 牛 ， 五 只 公 绵 羊 ， 五 只 公 山 羊 ， 五 只 一 岁 的 公 羊 羔 作 平 安 祭 。 这 是 苏 押 儿 子 拿 坦 业 的 供 物 。');
