INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3935', '4', '7', '84', '用 膏 抹 坛 的 日 子 ， 以 色 列 的 众 首 领 为 行 献 坛 之 礼 所 献 的 是 ： 银 盘 子 十 二 个 ， 银 碗 十 二 个 ， 金 盂 十 二 个 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3936', '4', '7', '85', '每 盘 子 重 一 百 三 十 舍 客 勒 ， 每 碗 重 七 十 舍 客 勒 。 一 切 器 皿 的 银 子 ， 按 圣 所 的 平 ， 共 有 二 千 四 百 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3937', '4', '7', '86', '十 二 个 金 盂 盛 满 了 香 ， 按 圣 所 的 平 ， 每 盂 重 十 舍 客 勒 ， 所 有 的 金 子 共 一 百 二 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3938', '4', '7', '87', '作 燔 祭 的 ， 共 有 公 牛 十 二 只 ， 公 羊 十 二 只 ， 一 岁 的 公 羊 羔 十 二 只 ， 并 同 献 的 素 祭 作 赎 罪 祭 的 公 山 羊 十 二 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3939', '4', '7', '88', '作 平 安 祭 的 ， 共 有 公 牛 二 十 四 只 ， 公 绵 羊 六 十 只 ， 公 山 羊 六 十 只 ， 一 岁 的 公 羊 羔 六 十 只 。 这 就 是 用 膏 抹 坛 之 后 ， 为 行 奉 献 坛 之 礼 所 献 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3940', '4', '7', '89', '摩 西 进 会 幕 要 与 耶 和 华 说 话 的 时 候 ， 听 见 法 柜 的 施 恩 座 以 上 、 二 基 路 伯 中 间 有 与 他 说 话 的 声 音 ， 就 是 耶 和 华 与 他 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3941', '4', '8', '1', '＜ 安 置 七 盏 灯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3942', '4', '8', '2', '“ 你 告 诉 亚 伦 说 ： 点 灯 的 时 候 ， 七 盏 灯 都 要 向 灯 台 前 面 发 光 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3943', '4', '8', '3', '亚 伦 便 这 样 行 。 他 点 灯 台 上 的 灯 ， 使 灯 向 前 发 光 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3944', '4', '8', '4', '这 灯 台 的 做 法 是 用 金 子 锤 出 来 的 ， 连 座 带 花 都 是 锤 出 来 的 。 摩 西 制 造 灯 台 ， 是 照 耶 和 华 所 指 示 的 样 式 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3945', '4', '8', '5', '＜ 为 利 未 人 行 洁 净 与 奉 献 礼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3946', '4', '8', '6', '“ 你 从 以 色 列 人 中 选 出 利 未 人 来 ， 洁 净 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3947', '4', '8', '7', '洁 净 他 们 当 这 样 行 ： 用 除 罪 水 弹 在 他 们 身 上 ， 又 叫 他 们 用 剃 头 刀 刮 全 身 ， 洗 衣 服 ， 洁 净 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3948', '4', '8', '8', '然 后 叫 他 们 取 一 只 公 牛 犊 ， 并 同 献 的 素 祭 ， 就 是 调 油 的 细 面 ； 你 要 另 取 一 只 公 牛 犊 作 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3949', '4', '8', '9', '将 利 未 人 奉 到 会 幕 前 ， 招 聚 以 色 列 全 会 众 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3950', '4', '8', '10', '将 利 未 人 奉 到 耶 和 华 面 前 ， 以 色 列 人 要 按 手 在 他 们 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3951', '4', '8', '11', '亚 伦 也 将 他 们 奉 到 耶 和 华 面 前 ， 为 以 色 列 人 当 作 摇 祭 ， 使 他 们 好 办 耶 和 华 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3952', '4', '8', '12', '利 未 人 要 按 手 在 那 两 只 牛 的 头 上 ； 你 要 将 一 只 作 赎 罪 祭 ， 一 只 作 燔 祭 ， 献 给 耶 和 华 ， 为 利 未 人 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3953', '4', '8', '13', '你 也 要 使 利 未 人 站 在 亚 伦 和 他 儿 子 面 前 ， 将 他 们 当 作 摇 祭 奉 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3954', '4', '8', '14', '“ 这 样 ， 你 从 以 色 列 人 中 将 利 未 人 分 别 出 来 ， 利 未 人 便 要 归 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3955', '4', '8', '15', '此 后 利 未 人 要 进 去 办 会 幕 的 事 ， 你 要 洁 净 他 们 ， 将 他 们 当 作 摇 祭 奉 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3956', '4', '8', '16', '因 为 他 们 是 从 以 色 列 人 中 全 然 给 我 的 ， 我 拣 选 他 们 归 我 ， 是 代 替 以 色 列 人 中 一 切 头 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3957', '4', '8', '17', '以 色 列 人 中 一 切 头 生 的 ， 连 人 带 牲 畜 ， 都 是 我 的 。 我 在 埃 及 地 击 杀 一 切 头 生 的 那 天 ， 将 他 们 分 别 为 圣 归 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3958', '4', '8', '18', '我 拣 选 利 未 人 代 替 以 色 列 人 中 一 切 头 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3959', '4', '8', '19', '我 从 以 色 列 人 中 将 利 未 人 当 作 赏 赐 给 亚 伦 和 他 的 儿 子 ， 在 会 幕 中 办 以 色 列 人 的 事 ， 又 为 以 色 列 人 赎 罪 ， 免 得 他 们 挨 近 圣 所 ， 有 灾 殃 临 到 他 们 中 间 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3960', '4', '8', '20', '摩 西 、 亚 伦 ， 并 以 色 列 全 会 众 便 向 利 未 人 如 此 行 。 凡 耶 和 华 指 着 利 未 人 所 吩 咐 摩 西 的 ， 以 色 列 人 就 向 他 们 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3961', '4', '8', '21', '于 是 利 未 人 洁 净 自 己 ， 除 了 罪 ， 洗 了 衣 服 ； 亚 伦 将 他 们 当 作 摇 祭 奉 到 耶 和 华 面 前 ， 又 为 他 们 赎 罪 ， 洁 净 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3962', '4', '8', '22', '然 后 利 未 人 进 去 ， 在 亚 伦 和 他 儿 子 面 前 ， 在 会 幕 中 办 事 。 耶 和 华 指 着 利 未 人 怎 样 吩 咐 摩 西 ， 以 色 列 人 就 怎 样 向 他 们 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3963', '4', '8', '23', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3964', '4', '8', '24', '“ 利 未 人 是 这 样 ： 从 二 十 五 岁 以 外 ， 他 们 要 前 来 任 职 ， 办 会 幕 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3965', '4', '8', '25', '到 了 五 十 岁 要 停 工 退 任 ， 不 再 办 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3966', '4', '8', '26', '只 要 在 会 幕 里 ， 和 他 们 的 弟 兄 一 同 伺 候 ， 谨 守 所 吩 咐 的 ， 不 再 办 事 了 。 至 于 所 吩 咐 利 未 人 的 ， 你 要 这 样 向 他 们 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3967', '4', '9', '1', '＜ 第 二 个 逾 越 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3968', '4', '9', '2', '“ 以 色 列 人 应 当 在 所 定 的 日 期 守 逾 越 节 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3969', '4', '9', '3', '就 是 本 月 十 四 日 黄 昏 的 时 候 ， 你 们 要 在 所 定 的 日 期 守 这 节 ， 要 按 这 节 的 律 例 典 章 而 守 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3970', '4', '9', '4', '于 是 摩 西 吩 咐 以 色 列 人 守 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3971', '4', '9', '5', '他 们 就 在 西 奈 的 旷 野 ， 正 月 十 四 日 黄 昏 的 时 候 ， 守 逾 越 节 。 凡 耶 和 华 所 吩 咐 摩 西 的 ， 以 色 列 人 都 照 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3972', '4', '9', '6', '有 几 个 人 因 死 尸 而 不 洁 净 ， 不 能 在 那 日 守 逾 越 节 。 当 日 他 们 到 摩 西 、 亚 伦 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3973', '4', '9', '7', '说 ： “ 我 们 虽 因 死 尸 而 不 洁 净 ， 为 何 被 阻 止 、 不 得 同 以 色 列 人 在 所 定 的 日 期 献 耶 和 华 的 供 物 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3974', '4', '9', '8', '摩 西 对 他 们 说 ： “ 你 们 暂 且 等 候 ， 我 可 以 去 听 耶 和 华 指 着 你 们 是 怎 样 吩 咐 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3975', '4', '9', '9', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3976', '4', '9', '10', '“ 你 晓 谕 以 色 列 人 说 ： 你 们 和 你 们 后 代 中 ， 若 有 人 因 死 尸 而 不 洁 净 ， 或 在 远 方 行 路 ， 还 要 向 耶 和 华 守 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3977', '4', '9', '11', '他 们 要 在 二 月 十 四 日 黄 昏 的 时 候 ， 守 逾 越 节 。 要 用 无 酵 饼 与 苦 菜 ， 和 逾 越 节 的 羊 羔 同 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3978', '4', '9', '12', '一 点 不 可 留 到 早 晨 ； 羊 羔 的 骨 头 一 根 也 不 可 折 断 。 他 们 要 照 逾 越 节 的 一 切 律 例 而 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3979', '4', '9', '13', '那 洁 净 而 不 行 路 的 人 若 推 辞 不 守 逾 越 节 ， 那 人 要 从 民 中 剪 除 ； 因 为 他 在 所 定 的 日 期 不 献 耶 和 华 的 供 物 ， 应 该 担 当 他 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3980', '4', '9', '14', '若 有 外 人 寄 居 在 你 们 中 间 ， 愿 意 向 耶 和 华 守 逾 越 节 ， 他 要 照 逾 越 节 的 律 例 典 章 行 ， 不 管 是 寄 居 的 是 本 地 人 ， 同 归 一 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3981', '4', '9', '15', '＜ 云 彩 遮 盖 帐 幕 （ 出   4 0 : 3 4 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3982', '4', '9', '16', '常 是 这 样 ， 云 彩 遮 盖 帐 幕 ， 夜 间 形 状 如 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3983', '4', '9', '17', '云 彩 几 时 从 帐 幕 收 上 去 ， 以 色 列 人 就 几 时 起 行 ； 云 彩 在 哪 里 停 住 ， 以 色 列 人 就 在 那 里 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3984', '4', '9', '18', '以 色 列 人 遵 耶 和 华 的 吩 咐 起 行 ， 也 遵 耶 和 华 的 吩 咐 安 营 。 云 彩 在 帐 幕 上 停 住 几 时 ， 他 们 就 住 营 几 时 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3985', '4', '9', '19', '云 彩 在 帐 幕 上 停 留 许 多 日 子 ， 以 色 列 人 就 守 耶 和 华 所 吩 咐 的 不 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3986', '4', '9', '20', '有 时 云 彩 在 帐 幕 上 几 天 ， 他 们 就 照 耶 和 华 的 吩 咐 住 营 ， 也 照 耶 和 华 的 吩 咐 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3987', '4', '9', '21', '有 时 从 晚 上 到 早 晨 ， 有 这 云 彩 在 帐 幕 上 ； 早 晨 云 彩 收 上 去 ， 他 们 就 起 行 。 有 时 昼 夜 云 彩 停 在 帐 幕 上 ， 收 上 去 的 时 候 ， 他 们 就 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3988', '4', '9', '22', '云 彩 停 留 在 帐 幕 上 ， 无 论 是 两 天 ， 是 一 月 ， 是 一 年 ， 以 色 列 人 就 住 营 不 起 行 ； 但 云 彩 收 上 去 ， 他 们 就 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3989', '4', '9', '23', '他 们 遵 耶 和 华 的 吩 咐 安 营 ， 也 遵 耶 和 华 的 吩 咐 起 行 。 他 们 守 耶 和 华 所 吩 咐 的 ， 都 是 凭 耶 和 华 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3990', '4', '10', '1', '＜ 制 银 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3991', '4', '10', '2', '你 要 用 银 子 做 两 枝 号 ， 都 要 锤 出 来 的 ， 用 以 招 聚 会 众 ， 并 叫 众 营 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3992', '4', '10', '3', '吹 这 号 的 时 候 ， 全 会 众 要 到 你 那 里 ， 聚 集 在 会 幕 门 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3993', '4', '10', '4', '若 单 吹 一 枝 ， 众 首 领 ， 就 是 以 色 列 军 中 的 统 领 ， 要 聚 集 到 你 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3994', '4', '10', '5', '吹 出 大 声 的 时 候 ， 东 边 安 的 营 都 要 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3995', '4', '10', '6', '二 次 吹 出 大 声 的 时 候 ， 南 边 安 的 营 都 要 起 行 。 他 们 将 起 行 ， 必 吹 出 大 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3996', '4', '10', '7', '但 招 聚 会 众 的 时 候 ， 你 们 要 吹 号 ， 却 不 要 吹 出 大 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3997', '4', '10', '8', '亚 伦 子 孙 作 祭 司 的 要 吹 这 号 ； 这 要 作 你 们 世 世 代 代 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3998', '4', '10', '9', '你 们 在 自 己 的 地 ， 与 欺 压 你 们 的 敌 人 打 仗 ， 就 要 用 号 吹 出 大 声 ， 便 在 耶 和 华 ─ ─ 你 们 的 神 面 前 得 蒙 纪 念 ， 也 蒙 拯 救 脱 离 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('3999', '4', '10', '10', '在 你 们 快 乐 的 日 子 和 节 期 ， 并 月 朔 ， 献 燔 祭 和 平 安 祭 ， 也 要 吹 号 ， 这 都 要 在 你 们 的 神 面 前 作 为 纪 念 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4000', '4', '10', '11', '＜ 离 开 西 奈 山   ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4001', '4', '10', '12', '以 色 列 人 就 按 站 往 前 行 ， 离 开 西 奈 的 旷 野 ， 云 彩 停 住 在 巴 兰 的 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4002', '4', '10', '13', '这 是 他 们 照 耶 和 华 藉 摩 西 所 吩 咐 的 ， 初 次 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4003', '4', '10', '14', '按 着 军 队 首 先 往 前 行 的 是 犹 大 营 的 纛 。 统 领 军 队 的 是 亚 米 拿 达 的 儿 子 拿 顺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4004', '4', '10', '15', '统 领 以 萨 迦 支 派 军 队 的 是 苏 押 的 儿 子 拿 坦 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4005', '4', '10', '16', '统 领 西 布 伦 支 派 军 队 的 是 希 伦 的 儿 子 以 利 押 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4006', '4', '10', '17', '帐 幕 拆 卸 ， 革 顺 的 子 孙 和 米 拉 利 的 子 孙 就 抬 着 帐 幕 先 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4007', '4', '10', '18', '按 着 军 队 往 前 行 的 是 吕 便 营 的 纛 。 统 领 军 队 的 是 示 丢 珥 的 儿 子 以 利 蓿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4008', '4', '10', '19', '统 领 西 缅 支 派 军 队 的 是 苏 利 沙 代 的 儿 子 示 路 蔑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4009', '4', '10', '20', '统 领 迦 得 支 派 军 队 的 是 丢 珥 的 儿 子 以 利 雅 萨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4010', '4', '10', '21', '哥 辖 人 抬 着 圣 物 先 往 前 行 。 他 们 未 到 以 前 ， 抬 帐 幕 的 已 经 把 帐 幕 支 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4011', '4', '10', '22', '按 着 军 队 往 前 行 的 是 以 法 莲 营 的 纛 ， 统 领 军 队 的 是 亚 米 忽 的 儿 子 以 利 沙 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4012', '4', '10', '23', '统 领 玛 拿 西 支 派 军 队 的 是 比 大 蓿 的 儿 子 迦 玛 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4013', '4', '10', '24', '统 领 便 雅 悯 支 派 军 队 的 是 基 多 尼 的 儿 子 亚 比 但 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4014', '4', '10', '25', '在 诸 营 末 后 的 是 但 营 的 纛 ， 按 着 军 队 往 前 行 。 统 领 军 队 的 是 亚 米 沙 代 的 儿 子 亚 希 以 谢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4015', '4', '10', '26', '统 领 亚 设 支 派 军 队 的 是 俄 兰 的 儿 子 帕 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4016', '4', '10', '27', '统 领 拿 弗 他 利 支 派 军 队 的 是 以 南 的 儿 子 亚 希 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4017', '4', '10', '28', '以 色 列 人 按 着 军 队 往 前 行 ， 就 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4018', '4', '10', '29', '摩 西 对 他 岳 父 ｛ 或 译 ： 内 兄 ｝ ─ ─ 米 甸 人 流 珥 的 儿 子 何 巴 ─ ─ 说 ： “ 我 们 要 行 路 ， 往 耶 和 华 所 应 许 之 地 去 ； 他 曾 说 ： ‘ 我 要 将 这 地 赐 给 你 们 。 ’ 现 在 求 你 和 我 们 同 去 ， 我 们 必 厚 待 你 ， 因 为 耶 和 华 指 着 以 色 列 人 已 经 应 许 给 好 处 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4019', '4', '10', '30', '何 巴 回 答 说 ： “ 我 不 去 ； 我 要 回 本 地 本 族 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4020', '4', '10', '31', '摩 西 说 ： “ 求 你 不 要 离 开 我 们 ； 因 为 你 知 道 我 们 要 在 旷 野 安 营 ， 你 可 以 当 作 我 们 的 眼 目 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4021', '4', '10', '32', '你 若 和 我 们 同 去 ， 将 来 耶 和 华 有 什 么 好 处 待 我 们 ， 我 们 也 必 以 什 么 好 处 待 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4022', '4', '10', '33', '＜ 众 民 和 约 柜 往 前 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4023', '4', '10', '34', '他 们 拔 营 往 前 行 ， 日 间 有 耶 和 华 的 云 彩 在 他 们 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4024', '4', '10', '35', '约 柜 往 前 行 的 时 候 ， 摩 西 就 说 ： “ 耶 和 华 啊 ， 求 你 兴 起 ！ 愿 你 的 仇 敌 四 散 ！ 愿 恨 你 的 人 从 你 面 前 逃 跑 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4025', '4', '10', '36', '约 柜 停 住 的 时 候 ， 他 就 说 ： “ 耶 和 华 啊 ， 求 你 回 到 以 色 列 的 千 万 人 中 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4026', '4', '11', '1', '＜ 在 他 备 拉 发 怨 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4027', '4', '11', '2', '百 姓 向 摩 西 哀 求 ， 摩 西 祈 求 耶 和 华 ， 火 就 熄 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4028', '4', '11', '3', '那 地 方 便 叫 做 他 备 拉 ， 因 为 耶 和 华 的 火 烧 在 他 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4029', '4', '11', '4', '＜ 摩 西 选 立 七 十 个 长 老 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4030', '4', '11', '5', '我 们 记 得 ， 在 埃 及 的 时 候 不 花 钱 就 吃 鱼 ， 也 记 得 有 黄 瓜 、 西 瓜 、 韭 菜 、 葱 、 蒜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4031', '4', '11', '6', '现 在 我 们 的 心 血 枯 竭 了 ， 除 这 吗 哪 以 外 ， 在 我 们 眼 前 并 没 有 别 的 东 西 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4032', '4', '11', '7', '（ 这 吗 哪 仿 佛 芫 荽 子 ， 又 好 像 珍 珠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4033', '4', '11', '8', '百 姓 周 围 行 走 ， 把 吗 哪 收 起 来 ， 或 用 磨 推 ， 或 用 臼 捣 ， 煮 在 锅 中 ， 又 做 成 饼 ， 滋 味 好 像 新 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4034', '4', '11', '9', '夜 间 露 水 降 在 营 中 ， 吗 哪 也 随 着 降 下 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4035', '4', '11', '10', '摩 西 听 见 百 姓 各 在 各 家 的 帐 棚 门 口 哭 号 。 耶 和 华 的 怒 气 便 大 发 作 ， 摩 西 就 不 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4036', '4', '11', '11', '摩 西 对 耶 和 华 说 ： “ 你 为 何 苦 待 仆 人 ？ 我 为 何 不 在 你 眼 前 蒙 恩 ， 竟 把 这 管 理 百 姓 的 重 任 加 在 我 身 上 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4037', '4', '11', '12', '这 百 姓 岂 是 我 怀 的 胎 ， 岂 是 我 生 下 来 的 呢 ？ 你 竟 对 我 说 ： ‘ 把 他 们 抱 在 怀 里 ， 如 养 育 之 父 抱 吃 奶 的 孩 子 ， 直 抱 到 你 起 誓 应 许 给 他 们 祖 宗 的 地 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4038', '4', '11', '13', '我 从 哪 里 得 肉 给 这 百 姓 吃 呢 ？ 他 们 都 向 我 哭 号 说 ： ‘ 你 给 我 们 肉 吃 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4039', '4', '11', '14', '管 理 这 百 姓 的 责 任 太 重 了 ， 我 独 自 担 当 不 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4040', '4', '11', '15', '你 这 样 待 我 ， 我 若 在 你 眼 前 蒙 恩 ， 求 你 立 时 将 我 杀 了 ， 不 叫 我 见 自 己 的 苦 情 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4041', '4', '11', '16', '耶 和 华 对 摩 西 说 ： “ 你 从 以 色 列 的 长 老 中 招 聚 七 十 个 人 ， 就 是 你 所 知 道 作 百 姓 的 长 老 和 官 长 的 ， 到 我 这 里 来 ， 领 他 们 到 会 幕 前 ， 使 他 们 和 你 一 同 站 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4042', '4', '11', '17', '我 要 在 那 里 降 临 ， 与 你 说 话 ， 也 要 把 降 于 你 身 上 的 灵 分 赐 他 们 ， 他 们 就 和 你 同 当 这 管 百 姓 的 重 任 ， 免 得 你 独 自 担 当 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4043', '4', '11', '18', '又 要 对 百 姓 说 ： ‘ 你 们 应 当 自 洁 ， 预 备 明 天 吃 肉 ， 因 为 你 们 哭 号 说 ： 谁 给 我 们 肉 吃 ！ 我 们 在 埃 及 很 好 。 这 声 音 达 到 了 耶 和 华 的 耳 中 ， 所 以 他 必 给 你 们 肉 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4044', '4', '11', '19', '你 们 不 止 吃 一 天 、 两 天 、 五 天 、 十 天 、 二 十 天 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4045', '4', '11', '20', '要 吃 一 个 整 月 ， 甚 至 肉 从 你 们 鼻 孔 里 喷 出 来 ， 使 你 们 厌 恶 了 ， 因 为 你 们 厌 弃 住 在 你 们 中 间 的 耶 和 华 ， 在 他 面 前 哭 号 说 ： 我 们 为 何 出 了 埃 及 呢 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4046', '4', '11', '21', '摩 西 对 耶 和 华 说 ： “ 这 与 我 同 住 的 百 姓 、 步 行 的 男 人 有 六 十 万 ， 你 还 说 ： ‘ 我 要 把 肉 给 他 们 ， 使 他 们 可 以 吃 一 个 整 月 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4047', '4', '11', '22', '难 道 给 他 们 宰 了 羊 群 牛 群 ， 或 是 把 海 中 所 有 的 鱼 都 聚 了 来 ， 就 够 他 们 吃 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4048', '4', '11', '23', '耶 和 华 对 摩 西 说 ： “ 耶 和 华 的 膀 臂 岂 是 缩 短 了 吗 ？ 现 在 要 看 我 的 话 向 你 应 验 不 应 验 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4049', '4', '11', '24', '摩 西 出 去 ， 将 耶 和 华 的 话 告 诉 百 姓 ， 又 招 聚 百 姓 的 长 老 中 七 十 个 人 来 ， 使 他 们 站 在 会 幕 的 四 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4050', '4', '11', '25', '耶 和 华 在 云 中 降 临 ， 对 摩 西 说 话 ， 把 降 与 他 身 上 的 灵 分 赐 那 七 十 个 长 老 。 灵 停 在 他 们 身 上 的 时 候 ， 他 们 就 受 感 说 话 ， 以 后 却 没 有 再 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4051', '4', '11', '26', '但 有 两 个 人 仍 在 营 里 ， 一 个 名 叫 伊 利 达 ， 一 个 名 叫 米 达 。 他 们 本 是 在 那 些 被 录 的 人 中 ， 却 没 有 到 会 幕 那 里 去 。 灵 停 在 他 们 身 上 ， 他 们 就 在 营 里 说 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4052', '4', '11', '27', '有 个 少 年 人 跑 来 告 诉 摩 西 说 ： “ 伊 利 达 、 米 达 在 营 里 说 预 言 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4053', '4', '11', '28', '摩 西 的 帮 手 ， 嫩 的 儿 子 约 书 亚 ， 就 是 摩 西 所 拣 选 的 一 个 人 ， 说 ： “ 请 我 主 摩 西 禁 止 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4054', '4', '11', '29', '摩 西 对 他 说 ： “ 你 为 我 的 缘 故 嫉 妒 人 吗 ？ 惟 愿 耶 和 华 的 百 姓 都 受 感 说 话 ！ 愿 耶 和 华 把 他 的 灵 降 在 他 们 身 上 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4055', '4', '11', '30', '于 是 ， 摩 西 和 以 色 列 的 长 老 都 回 到 营 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4056', '4', '11', '31', '＜ 神 赐 鹌 鹑 为 食 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4057', '4', '11', '32', '百 姓 起 来 ， 终 日 终 夜 ， 并 次 日 一 整 天 ， 捕 取 鹌 鹑 ； 至 少 的 也 取 了 十 贺 梅 珥 ， 为 自 己 摆 列 在 营 的 四 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4058', '4', '11', '33', '肉 在 他 们 牙 齿 之 间 尚 未 嚼 烂 ， 耶 和 华 的 怒 气 就 向 他 们 发 作 ， 用 最 重 的 灾 殃 击 杀 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4059', '4', '11', '34', '那 地 方 便 叫 做 基 博 罗 ． 哈 他 瓦 ｛ 就 是 贪 欲 之 人 的 坟 墓 ｝ ， 因 为 他 们 在 那 里 葬 埋 那 起 贪 欲 之 心 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4060', '4', '11', '35', '百 姓 从 基 博 罗 ． 哈 他 瓦 走 到 哈 洗 录 ， 就 住 在 哈 洗 录 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4061', '4', '12', '1', '＜ 米 利 暗 受 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4062', '4', '12', '2', '“ 难 道 耶 和 华 单 与 摩 西 说 话 ， 不 也 与 我 们 说 话 吗 ？ ” 这 话 耶 和 华 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4063', '4', '12', '3', '（ 摩 西 为 人 极 其 谦 和 ， 胜 过 世 上 的 众 人 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4064', '4', '12', '4', '耶 和 华 忽 然 对 摩 西 、 亚 伦 、 米 利 暗 说 ： “ 你 们 三 个 人 都 出 来 ， 到 会 幕 这 里 。 ” 他 们 三 个 人 就 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4065', '4', '12', '5', '耶 和 华 在 云 柱 中 降 临 ， 站 在 会 幕 门 口 ， 召 亚 伦 和 米 利 暗 ， 二 人 就 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4066', '4', '12', '6', '耶 和 华 说 ： “ 你 们 且 听 我 的 话 ： 你 们 中 间 若 有 先 知 ， 我 ─ ─ 耶 和 华 必 在 异 象 中 向 他 显 现 ， 在 梦 中 与 他 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4067', '4', '12', '7', '我 的 仆 人 摩 西 不 是 这 样 ； 他 是 在 我 全 家 尽 忠 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4068', '4', '12', '8', '我 要 与 他 面 对 面 说 话 ， 乃 是 明 说 ， 不 用 谜 语 ， 并 且 他 必 见 我 的 形 像 。 你 们 毁 谤 我 的 仆 人 摩 西 ， 为 何 不 惧 怕 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4069', '4', '12', '9', '耶 和 华 就 向 他 们 二 人 发 怒 而 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4070', '4', '12', '10', '云 彩 从 会 幕 上 挪 开 了 ， 不 料 ， 米 利 暗 长 了 大 痲 疯 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4071', '4', '12', '11', '有 雪 那 样 白 。 亚 伦 一 看 米 利 暗 长 了 大 痲 疯 ， 就 对 摩 西 说 ： “ 我 主 啊 ， 求 你 不 要 因 我 们 愚 昧 犯 罪 ， 便 将 这 罪 加 在 我 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4072', '4', '12', '12', '求 你 不 要 使 她 像 那 出 母 腹 、 肉 已 半 烂 的 死 胎 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4073', '4', '12', '13', '于 是 摩 西 哀 求 耶 和 华 说 ： “ 神 啊 ， 求 你 医 治 她 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4074', '4', '12', '14', '耶 和 华 对 摩 西 说 ： “ 她 父 亲 若 吐 唾 沫 在 她 脸 上 ， 她 岂 不 蒙 羞 七 天 吗 ？ 现 在 要 把 她 在 营 外 关 锁 七 天 ， 然 后 才 可 以 领 她 进 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4075', '4', '12', '15', '于 是 米 利 暗 关 锁 在 营 外 七 天 。 百 姓 没 有 行 路 ， 直 等 到 把 米 利 暗 领 进 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4076', '4', '12', '16', '以 后 百 姓 从 哈 洗 录 起 行 ， 在 巴 兰 的 旷 野 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4077', '4', '13', '1', '＜ 十 二 个 探 子 （ 申   1 : 1 9 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4078', '4', '13', '2', '“ 你 打 发 人 去 窥 探 我 所 赐 给 以 色 列 人 的 迦 南 地 ， 他 们 每 支 派 中 要 打 发 一 个 人 ， 都 要 作 首 领 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4079', '4', '13', '3', '摩 西 就 照 耶 和 华 的 吩 咐 从 巴 兰 的 旷 野 打 发 他 们 去 ； 他 们 都 是 以 色 列 人 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4080', '4', '13', '4', '他 们 的 名 字 ： 属 吕 便 支 派 的 有 撒 刻 的 儿 子 沙 母 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4081', '4', '13', '5', '属 西 缅 支 派 的 有 何 利 的 儿 子 沙 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4082', '4', '13', '6', '属 犹 大 支 派 的 有 耶 孚 尼 的 儿 子 迦 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4083', '4', '13', '7', '属 以 萨 迦 支 派 的 有 约 色 的 儿 子 以 迦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4084', '4', '13', '8', '属 以 法 莲 支 派 的 有 嫩 的 儿 子 何 希 阿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4085', '4', '13', '9', '属 便 雅 悯 支 派 的 有 拉 孚 的 儿 子 帕 提 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4086', '4', '13', '10', '属 西 布 伦 支 派 的 有 梭 底 的 儿 子 迦 叠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4087', '4', '13', '11', '约 瑟 的 子 孙 ， 属 玛 拿 西 支 派 的 有 稣 西 的 儿 子 迦 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4088', '4', '13', '12', '属 但 支 派 的 有 基 玛 利 的 儿 子 亚 米 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4089', '4', '13', '13', '属 亚 设 支 派 的 有 米 迦 勒 的 儿 子 西 帖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4090', '4', '13', '14', '属 拿 弗 他 利 支 派 的 有 缚 西 的 儿 子 拿 比 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4091', '4', '13', '15', '属 迦 得 支 派 的 有 玛 基 的 儿 子 臼 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4092', '4', '13', '16', '这 就 是 摩 西 所 打 发 、 窥 探 那 地 之 人 的 名 字 。 摩 西 就 称 嫩 的 儿 子 何 希 阿 为 约 书 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4093', '4', '13', '17', '摩 西 打 发 他 们 去 窥 探 迦 南 地 ， 说 ： “ 你 们 从 南 地 上 山 地 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4094', '4', '13', '18', '看 那 地 如 何 ， 其 中 所 住 的 民 是 强 是 弱 ， 是 多 是 少 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4095', '4', '13', '19', '所 住 之 处 是 好 是 歹 ， 所 住 之 处 是 营 盘 是 坚 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4096', '4', '13', '20', '又 看 那 地 土 是 肥 美 是 瘠 薄 ， 其 中 有 树 木 没 有 。 你 们 要 放 开 胆 量 ， 把 那 地 的 果 子 带 些 来 。 ” （ 那 时 正 是 葡 萄 初 熟 的 时 候 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4097', '4', '13', '21', '他 们 上 去 窥 探 那 地 ， 从 寻 的 旷 野 到 利 合 ， 直 到 哈 马 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4098', '4', '13', '22', '他 们 从 南 地 上 去 ， 到 了 希 伯 仑 ； 在 那 里 有 亚 衲 族 人 亚 希 幔 、 示 筛 、 挞 买 。 （ 原 来 希 伯 仑 城 被 建 造 比 埃 及 的 锁 安 城 早 七 年 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4099', '4', '13', '23', '他 们 到 了 以 实 各 谷 ， 从 那 里 砍 了 葡 萄 树 的 一 枝 ， 上 头 有 一 挂 葡 萄 ， 两 个 人 用 杠 抬 着 ， 又 带 了 些 石 榴 和 无 花 果 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4100', '4', '13', '24', '（ 因 为 以 色 列 人 从 那 里 砍 来 的 那 挂 葡 萄 ， 所 以 那 地 方 叫 做 以 实 各 谷 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4101', '4', '13', '25', '过 了 四 十 天 ， 他 们 窥 探 那 地 才 回 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4102', '4', '13', '26', '到 了 巴 兰 旷 野 的 加 低 斯 ， 见 摩 西 、 亚 伦 ， 并 以 色 列 的 全 会 众 ， 回 报 摩 西 、 亚 伦 ， 并 全 会 众 ， 又 把 那 地 的 果 子 给 他 们 看 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4103', '4', '13', '27', '又 告 诉 摩 西 说 ： “ 我 们 到 了 你 所 打 发 我 们 去 的 那 地 ， 果 然 是 流 奶 与 蜜 之 地 ； 这 就 是 那 地 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4104', '4', '13', '28', '然 而 住 那 地 的 民 强 壮 ， 城 邑 也 坚 固 宽 大 ， 并 且 我 们 在 那 里 看 见 了 亚 衲 族 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4105', '4', '13', '29', '亚 玛 力 人 住 在 南 地 ； 赫 人 、 耶 布 斯 人 、 亚 摩 利 人 住 在 山 地 ； 迦 南 人 住 在 海 边 并 约 旦 河 旁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4106', '4', '13', '30', '迦 勒 在 摩 西 面 前 安 抚 百 姓 ， 说 ： “ 我 们 立 刻 上 去 得 那 地 吧 ！ 我 们 足 能 得 胜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4107', '4', '13', '31', '但 那 些 和 他 同 去 的 人 说 ： “ 我 们 不 能 上 去 攻 击 那 民 ， 因 为 他 们 比 我 们 强 壮 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4108', '4', '13', '32', '探 子 中 有 人 论 到 所 窥 探 之 地 ， 向 以 色 列 人 报 恶 信 ， 说 ： “ 我 们 所 窥 探 、 经 过 之 地 是 吞 吃 居 民 之 地 ， 我 们 在 那 里 所 看 见 的 人 民 都 身 量 高 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4109', '4', '13', '33', '我 们 在 那 里 看 见 亚 衲 族 人 ， 就 是 伟 人 ； 他 们 是 伟 人 的 后 裔 。 据 我 们 看 ， 自 己 就 如 蚱 蜢 一 样 ； 据 他 们 看 ， 我 们 也 是 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4110', '4', '14', '1', '＜ 民 众 埋 怨 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4111', '4', '14', '2', '以 色 列 众 人 向 摩 西 、 亚 伦 发 怨 言 ； 全 会 众 对 他 们 说 ： “ 巴 不 得 我 们 早 死 在 埃 及 地 ， 或 是 死 在 这 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4112', '4', '14', '3', '耶 和 华 为 什 么 把 我 们 领 到 那 地 ， 使 我 们 倒 在 刀 下 呢 ？ 我 们 的 妻 子 和 孩 子 必 被 掳 掠 。 我 们 回 埃 及 去 岂 不 好 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4113', '4', '14', '4', '众 人 彼 此 说 ： “ 我 们 不 如 立 一 个 首 领 回 埃 及 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4114', '4', '14', '5', '摩 西 、 亚 伦 就 俯 伏 在 以 色 列 全 会 众 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4115', '4', '14', '6', '窥 探 地 的 人 中 ， 嫩 的 儿 子 约 书 亚 和 耶 孚 尼 的 儿 子 迦 勒 撕 裂 衣 服 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4116', '4', '14', '7', '对 以 色 列 全 会 众 说 ： “ 我 们 所 窥 探 、 经 过 之 地 是 极 美 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4117', '4', '14', '8', '耶 和 华 若 喜 悦 我 们 ， 就 必 将 我 们 领 进 那 地 ， 把 地 赐 给 我 们 ； 那 地 原 是 流 奶 与 蜜 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4118', '4', '14', '9', '但 你 们 不 可 背 叛 耶 和 华 ， 也 不 要 怕 那 地 的 居 民 ； 因 为 他 们 是 我 们 的 食 物 ， 并 且 荫 庇 他 们 的 已 经 离 开 他 们 。 有 耶 和 华 与 我 们 同 在 ， 不 要 怕 他 们 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4119', '4', '14', '10', '但 全 会 众 说 ： “ 拿 石 头 打 死 他 们 二 人 。 ” 忽 然 ， 耶 和 华 的 荣 光 在 会 幕 中 向 以 色 列 众 人 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4120', '4', '14', '11', '＜ 摩 西 为 民 众 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4121', '4', '14', '12', '我 要 用 瘟 疫 击 杀 他 们 ， 使 他 们 不 得 承 受 那 地 ， 叫 你 的 后 裔 成 为 大 国 ， 比 他 们 强 胜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4122', '4', '14', '13', '摩 西 对 耶 和 华 说 ： “ 埃 及 人 必 听 见 这 事 ； 因 为 你 曾 施 展 大 能 ， 将 这 百 姓 从 他 们 中 间 领 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4123', '4', '14', '14', '埃 及 人 要 将 这 事 传 给 迦 南 地 的 居 民 ； 那 民 已 经 听 见 你 ─ ─ 耶 和 华 是 在 这 百 姓 中 间 ； 因 为 你 面 对 面 被 人 看 见 ， 有 你 的 云 彩 停 在 他 们 以 上 。 你 日 间 在 云 柱 中 ， 夜 间 在 火 柱 中 ， 在 他 们 前 面 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4124', '4', '14', '15', '如 今 你 若 把 这 百 姓 杀 了 ， 如 杀 一 人 ， 那 些 听 见 你 名 声 的 列 邦 必 议 论 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4125', '4', '14', '16', '‘ 耶 和 华 因 为 不 能 把 这 百 姓 领 进 他 向 他 们 起 誓 应 许 之 地 ， 所 以 在 旷 野 把 他 们 杀 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4126', '4', '14', '17', '现 在 求 主 大 显 能 力 ， 照 你 所 说 过 的 话 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4127', '4', '14', '18', '‘ 耶 和 华 不 轻 易 发 怒 ， 并 有 丰 盛 的 慈 爱 ， 赦 免 罪 孽 和 过 犯 ； 万 不 以 有 罪 的 为 无 罪 ， 必 追 讨 他 的 罪 ， 自 父 及 子 ， 直 到 三 、 四 代 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4128', '4', '14', '19', '求 你 照 你 的 大 慈 爱 赦 免 这 百 姓 的 罪 孽 ， 好 像 你 从 埃 及 到 如 今 常 赦 免 他 们 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4129', '4', '14', '20', '耶 和 华 说 ： “ 我 照 着 你 的 话 赦 免 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4130', '4', '14', '21', '然 我 指 着 我 的 永 生 起 誓 ， 遍 地 要 被 我 的 荣 耀 充 满 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4131', '4', '14', '22', '这 些 人 虽 看 见 我 的 荣 耀 和 我 在 埃 及 与 旷 野 所 行 的 神 迹 ， 仍 然 试 探 我 这 十 次 ， 不 听 从 我 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4132', '4', '14', '23', '他 们 断 不 得 看 见 我 向 他 们 的 祖 宗 所 起 誓 应 许 之 地 。 凡 藐 视 我 的 ， 一 个 也 不 得 看 见 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4133', '4', '14', '24', '惟 独 我 的 仆 人 迦 勒 ， 因 他 另 有 一 个 心 志 ， 专 一 跟 从 我 ， 我 就 把 他 领 进 他 所 去 过 的 那 地 ； 他 的 后 裔 也 必 得 那 地 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4134', '4', '14', '25', '亚 玛 力 人 和 迦 南 人 住 在 谷 中 ， 明 天 你 们 要 转 回 ， 从 红 海 的 路 往 旷 野 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4135', '4', '14', '26', '＜ 耶 和 华 惩 罚 埋 怨 的 民 众 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4136', '4', '14', '27', '“ 这 恶 会 众 向 我 发 怨 言 ， 我 忍 耐 他 们 要 到 几 时 呢 ？ 以 色 列 人 向 我 所 发 的 怨 言 ， 我 都 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4137', '4', '14', '28', '你 们 告 诉 他 们 ， 耶 和 华 说 ： ‘ 我 指 着 我 的 永 生 起 誓 ， 我 必 要 照 你 们 达 到 我 耳 中 的 话 待 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4138', '4', '14', '29', '你 们 的 尸 首 必 倒 在 这 旷 野 ， 并 且 你 们 中 间 凡 被 数 点 、 从 二 十 岁 以 外 、 向 我 发 怨 言 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4139', '4', '14', '30', '必 不 得 进 我 起 誓 应 许 叫 你 们 住 的 那 地 ； 惟 有 耶 孚 尼 的 儿 子 迦 勒 和 嫩 的 儿 子 约 书 亚 才 能 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4140', '4', '14', '31', '但 你 们 的 妇 人 孩 子 ， 就 是 你 们 所 说 、 要 被 掳 掠 的 ， 我 必 把 他 们 领 进 去 ， 他 们 就 得 知 你 们 所 厌 弃 的 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4141', '4', '14', '32', '至 于 你 们 ， 你 们 的 尸 首 必 倒 在 这 旷 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4142', '4', '14', '33', '你 们 的 儿 女 必 在 旷 野 飘 流 四 十 年 ， 担 当 你 们 淫 行 的 罪 ， 直 到 你 们 的 尸 首 在 旷 野 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4143', '4', '14', '34', '按 你 们 窥 探 那 地 的 四 十 日 ， 一 年 顶 一 日 ， 你 们 要 担 当 罪 孽 四 十 年 ， 就 知 道 我 与 你 们 疏 远 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4144', '4', '14', '35', '我 ─ ─ 耶 和 华 说 过 ， 我 总 要 这 样 待 这 一 切 聚 集 敌 我 的 恶 会 众 ； 他 们 必 在 这 旷 野 消 灭 ， 在 这 里 死 亡 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4145', '4', '14', '36', '摩 西 所 打 发 、 窥 探 那 地 的 人 回 来 ， 报 那 地 的 恶 信 ， 叫 全 会 众 向 摩 西 发 怨 言 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4146', '4', '14', '37', '这 些 报 恶 信 的 人 都 遭 瘟 疫 ， 死 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4147', '4', '14', '38', '其 中 惟 有 嫩 的 儿 子 约 书 亚 和 耶 孚 尼 的 儿 子 迦 勒 仍 然 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4148', '4', '14', '39', '＜ 首 次 进 攻 迦 南 （ 申   1 : 4 1 - 4 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4149', '4', '14', '40', '清 早 起 来 ， 上 山 顶 去 ， 说 ： “ 我 们 在 这 里 ， 我 们 有 罪 了 ； 情 愿 上 耶 和 华 所 应 许 的 地 方 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4150', '4', '14', '41', '摩 西 说 ： “ 你 们 为 何 违 背 耶 和 华 的 命 令 呢 ？ 这 事 不 能 顺 利 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4151', '4', '14', '42', '不 要 上 去 ； 因 为 耶 和 华 不 在 你 们 中 间 ， 恐 怕 你 们 被 仇 敌 杀 败 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4152', '4', '14', '43', '亚 玛 力 人 和 迦 南 人 都 在 你 们 面 前 ， 你 们 必 倒 在 刀 下 ； 因 你 们 退 回 不 跟 从 耶 和 华 ， 所 以 他 必 不 与 你 们 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4153', '4', '14', '44', '他 们 却 擅 敢 上 山 顶 去 ， 然 而 耶 和 华 的 约 柜 和 摩 西 没 有 出 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4154', '4', '14', '45', '于 是 亚 玛 力 人 和 住 在 那 山 上 的 迦 南 人 都 下 来 击 打 他 们 ， 把 他 们 杀 退 了 ， 直 到 何 珥 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4155', '4', '15', '1', '＜ 献 祭 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4156', '4', '15', '2', '“ 你 晓 谕 以 色 列 人 说 ： 你 们 到 了 我 所 赐 给 你 们 居 住 的 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4157', '4', '15', '3', '若 愿 意 从 牛 群 羊 群 中 取 牛 羊 作 火 祭 ， 献 给 耶 和 华 ， 无 论 是 燔 祭 是 平 安 祭 ， 为 要 还 特 许 的 愿 ， 或 是 作 甘 心 祭 ， 或 是 逢 你 们 节 期 献 的 ， 都 要 奉 给 耶 和 华 为 馨 香 之 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4158', '4', '15', '4', '那 献 供 物 的 就 要 将 细 面 伊 法 十 分 之 一 ， 并 油 一 欣 四 分 之 一 ， 调 和 作 素 祭 ， 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4159', '4', '15', '5', '无 论 是 燔 祭 是 平 安 祭 ， 你 要 为 每 只 绵 羊 羔 ， 一 同 预 备 奠 祭 的 酒 一 欣 四 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4160', '4', '15', '6', '为 公 绵 羊 预 备 细 面 伊 法 十 分 之 二 ， 并 油 一 欣 三 分 之 一 ， 调 和 作 素 祭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4161', '4', '15', '7', '又 用 酒 一 欣 三 分 之 一 作 奠 祭 ， 献 给 耶 和 华 为 馨 香 之 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4162', '4', '15', '8', '你 预 备 公 牛 作 燔 祭 ， 或 是 作 平 安 祭 ， 为 要 还 特 许 的 愿 ， 或 是 作 平 安 祭 ， 献 给 耶 和 华 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4163', '4', '15', '9', '就 要 把 细 面 伊 法 十 分 之 三 ， 并 油 半 欣 ， 调 和 作 素 祭 ， 和 公 牛 一 同 献 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4164', '4', '15', '10', '又 用 酒 半 欣 作 奠 祭 ， 献 给 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4165', '4', '15', '11', '“ 献 公 牛 、 公 绵 羊 、 绵 羊 羔 、 山 羊 羔 ， 每 只 都 要 这 样 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4166', '4', '15', '12', '照 你 们 所 预 备 的 数 目 ， 按 着 只 数 都 要 这 样 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4167', '4', '15', '13', '凡 本 地 人 将 馨 香 的 火 祭 献 给 耶 和 华 ， 都 要 这 样 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4168', '4', '15', '14', '若 有 外 人 和 你 们 同 居 ， 或 有 人 世 世 代 代 住 在 你 们 中 间 ， 愿 意 将 馨 香 的 火 祭 献 给 耶 和 华 ， 你 们 怎 样 办 理 ， 他 也 要 照 样 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4169', '4', '15', '15', '至 于 会 众 ， 你 们 和 同 居 的 外 人 都 归 一 例 ， 作 为 你 们 世 世 代 代 永 远 的 定 例 ， 在 耶 和 华 面 前 ， 你 们 怎 样 ， 寄 居 的 也 要 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4170', '4', '15', '16', '你 们 并 与 你 们 同 居 的 外 人 当 有 一 样 的 条 例 ， 一 样 的 典 章 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4171', '4', '15', '17', '耶 和 华 对 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4172', '4', '15', '18', '“ 你 晓 谕 以 色 列 人 说 ： 你 们 到 了 我 所 领 你 们 进 去 的 那 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4173', '4', '15', '19', '吃 那 地 的 粮 食 ， 就 要 把 举 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4174', '4', '15', '20', '你 们 要 用 初 熟 的 麦 子 磨 面 ， 做 饼 当 举 祭 奉 献 ； 你 们 举 上 ， 好 像 举 禾 场 的 举 祭 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4175', '4', '15', '21', '你 们 世 世 代 代 要 用 初 熟 的 麦 子 磨 面 ， 当 举 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4176', '4', '15', '22', '“ 你 们 有 错 误 的 时 候 ， 不 守 耶 和 华 所 晓 谕 摩 西 的 这 一 切 命 令 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4177', '4', '15', '23', '就 是 耶 和 华 藉 摩 西 一 切 所 吩 咐 你 们 的 ， 自 那 日 以 至 你 们 的 世 世 代 代 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4178', '4', '15', '24', '若 有 误 行 ， 是 会 众 所 不 知 道 的 ， 后 来 全 会 众 就 要 将 一 只 公 牛 犊 作 燔 祭 ， 并 照 典 章 把 素 祭 和 奠 祭 一 同 献 给 耶 和 华 为 馨 香 之 祭 ， 又 献 一 只 公 山 羊 作 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4179', '4', '15', '25', '祭 司 要 为 以 色 列 全 会 众 赎 罪 ， 他 们 就 必 蒙 赦 免 ， 因 为 这 是 错 误 。 他 们 又 因 自 己 的 错 误 ， 把 供 物 ， 就 是 向 耶 和 华 献 的 火 祭 和 赎 罪 祭 ， 一 并 奉 到 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4180', '4', '15', '26', '以 色 列 全 会 众 和 寄 居 在 他 们 中 间 的 外 人 就 必 蒙 赦 免 ， 因 为 这 罪 是 百 姓 误 犯 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4181', '4', '15', '27', '“ 若 有 一 个 人 误 犯 了 罪 ， 他 就 要 献 一 岁 的 母 山 羊 作 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4182', '4', '15', '28', '那 误 行 的 人 犯 罪 的 时 候 ， 祭 司 要 在 耶 和 华 面 前 为 他 赎 罪 ， 他 就 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4183', '4', '15', '29', '以 色 列 中 的 本 地 人 和 寄 居 在 他 们 中 间 的 外 人 ， 若 误 行 了 什 么 事 ， 必 归 一 样 的 条 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4184', '4', '15', '30', '但 那 擅 敢 行 事 的 ， 无 论 是 本 地 人 是 寄 居 的 ， 他 亵 渎 了 耶 和 华 ， 必 从 民 中 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4185', '4', '15', '31', '因 他 藐 视 耶 和 华 的 言 语 ， 违 背 耶 和 华 的 命 令 ， 那 人 总 要 剪 除 ； 他 的 罪 孽 要 归 到 他 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4186', '4', '15', '32', '＜ 违 反 安 息 日 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4187', '4', '15', '33', '遇 见 他 捡 柴 的 人 ， 就 把 他 带 到 摩 西 、 亚 伦 并 全 会 众 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4188', '4', '15', '34', '将 他 收 在 监 内 ； 因 为 当 怎 样 办 他 ， 还 没 有 指 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4189', '4', '15', '35', '耶 和 华 吩 咐 摩 西 说 ： “ 总 要 把 那 人 治 死 ； 全 会 众 要 在 营 外 用 石 头 把 他 打 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4190', '4', '15', '36', '于 是 全 会 众 将 他 带 到 营 外 ， 用 石 头 打 死 他 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4191', '4', '15', '37', '＜ 有 关 衣 服 繸 子 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4192', '4', '15', '38', '“ 你 吩 咐 以 色 列 人 ， 叫 他 们 世 世 代 代 在 衣 服 边 上 做 繸 子 ， 又 在 底 边 的 繸 子 上 钉 一 根 蓝 细 带 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4193', '4', '15', '39', '你 们 佩 带 这 繸 子 ， 好 叫 你 们 看 见 就 记 念 遵 行 耶 和 华 一 切 的 命 令 ， 不 随 从 自 己 的 心 意 、 眼 目 行 邪 淫 ， 像 你 们 素 常 一 样 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4194', '4', '15', '40', '使 你 们 记 念 遵 行 我 一 切 的 命 令 ， 成 为 圣 洁 ， 归 与 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4195', '4', '15', '41', '“ 我 是 耶 和 华 ─ ─ 你 们 的 神 ， 曾 把 你 们 从 埃 及 地 领 出 来 ， 要 作 你 们 的 神 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4196', '4', '16', '1', '＜ 可 拉 、 大 坍 、 亚 比 兰 的 叛 变 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4197', '4', '16', '2', '并 以 色 列 会 中 的 二 百 五 十 个 首 领 ， 就 是 有 名 望 选 入 会 中 的 人 ， 在 摩 西 面 前 一 同 起 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4198', '4', '16', '3', '聚 集 攻 击 摩 西 、 亚 伦 ， 说 ： “ 你 们 擅 自 专 权 ！ 全 会 众 个 个 既 是 圣 洁 ， 耶 和 华 也 在 他 们 中 间 ， 你 们 为 什 么 自 高 ， 超 过 耶 和 华 的 会 众 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4199', '4', '16', '4', '摩 西 听 见 这 话 就 俯 伏 在 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4200', '4', '16', '5', '对 可 拉 和 他 一 党 的 人 说 ： “ 到 了 早 晨 ， 耶 和 华 必 指 示 谁 是 属 他 的 ， 谁 是 圣 洁 的 ， 就 叫 谁 亲 近 他 ； 他 所 拣 选 的 是 谁 ， 必 叫 谁 亲 近 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4201', '4', '16', '6', '可 拉 啊 ， 你 们 要 这 样 行 ， 你 和 你 的 一 党 要 拿 香 炉 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4202', '4', '16', '7', '明 日 ， 在 耶 和 华 面 前 ， 把 火 盛 在 炉 中 ， 把 香 放 在 其 上 。 耶 和 华 拣 选 谁 ， 谁 就 为 圣 洁 。 你 们 这 利 未 的 子 孙 擅 自 专 权 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4203', '4', '16', '8', '摩 西 又 对 可 拉 说 ： “ 利 未 的 子 孙 哪 ， 你 们 听 我 说 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4204', '4', '16', '9', '以 色 列 的 神 从 以 色 列 会 中 将 你 们 分 别 出 来 ， 使 你 们 亲 近 他 ， 办 耶 和 华 帐 幕 的 事 ， 并 站 在 会 众 面 前 替 他 们 当 差 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4205', '4', '16', '10', '耶 和 华 又 使 你 和 你 一 切 弟 兄 ─ ─ 利 未 的 子 孙 ─ ─ 一 同 亲 近 他 ， 这 岂 为 小 事 ？ 你 们 还 要 求 祭 司 的 职 任 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4206', '4', '16', '11', '你 和 你 一 党 的 人 聚 集 是 要 攻 击 耶 和 华 。 亚 伦 算 什 么 ， 你 们 竟 向 他 发 怨 言 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4207', '4', '16', '12', '摩 西 打 发 人 去 召 以 利 押 的 儿 子 大 坍 、 亚 比 兰 。 他 们 说 ： “ 我 们 不 上 去 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4208', '4', '16', '13', '你 将 我 们 从 流 奶 与 蜜 之 地 领 上 来 ， 要 在 旷 野 杀 我 们 ， 这 岂 为 小 事 ？ 你 还 要 自 立 为 王 辖 管 我 们 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4209', '4', '16', '14', '并 且 你 没 有 将 我 们 领 到 流 奶 与 蜜 之 地 ， 也 没 有 把 田 地 和 葡 萄 园 给 我 们 为 业 。 难 道 你 要 剜 这 些 人 的 眼 睛 吗 ？ 我 们 不 上 去 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4210', '4', '16', '15', '摩 西 就 甚 发 怒 ， 对 耶 和 华 说 ： “ 求 你 不 要 享 受 他 们 的 供 物 。 我 并 没 有 夺 过 他 们 一 匹 驴 ， 也 没 有 害 过 他 们 一 个 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4211', '4', '16', '16', '摩 西 对 可 拉 说 ： “ 明 天 ， 你 和 你 一 党 的 人 ， 并 亚 伦 ， 都 要 站 在 耶 和 华 面 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4212', '4', '16', '17', '各 人 要 拿 一 个 香 炉 ， 共 二 百 五 十 个 ， 把 香 放 在 上 面 ， 到 耶 和 华 面 前 。 你 和 亚 伦 也 各 拿 自 己 的 香 炉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4213', '4', '16', '18', '于 是 他 们 各 人 拿 一 个 香 炉 ， 盛 上 火 ， 加 上 香 ， 同 摩 西 、 亚 伦 站 在 会 幕 门 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4214', '4', '16', '19', '可 拉 招 聚 全 会 众 到 会 幕 门 前 ， 要 攻 击 摩 西 、 亚 伦 ； 耶 和 华 的 荣 光 就 向 全 会 众 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4215', '4', '16', '20', '耶 和 华 晓 谕 摩 西 、 亚 伦 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4216', '4', '16', '21', '“ 你 们 离 开 这 会 众 ， 我 好 在 转 眼 之 间 把 他 们 灭 绝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4217', '4', '16', '22', '摩 西 、 亚 伦 就 俯 伏 在 地 ， 说 ： “ 神 ， 万 人 之 灵 的 神 啊 ， 一 人 犯 罪 ， 你 就 要 向 全 会 众 发 怒 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4218', '4', '16', '23', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4219', '4', '16', '24', '“ 你 吩 咐 会 众 说 ： ‘ 你 们 离 开 可 拉 、 大 坍 、 亚 比 兰 帐 棚 的 四 围 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4220', '4', '16', '25', '摩 西 起 来 ， 往 大 坍 、 亚 比 兰 那 里 去 ； 以 色 列 的 长 老 也 随 着 他 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4221', '4', '16', '26', '他 吩 咐 会 众 说 ： “ 你 们 离 开 这 恶 人 的 帐 棚 吧 ， 他 们 的 物 件 ， 什 么 都 不 可 摸 ， 恐 怕 你 们 陷 在 他 们 的 罪 中 ， 与 他 们 一 同 消 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4222', '4', '16', '27', '于 是 众 人 离 开 可 拉 、 大 坍 、 亚 比 兰 帐 棚 的 四 围 。 大 坍 、 亚 比 兰 带 着 妻 子 、 儿 女 、 小 孩 子 ， 都 出 来 ， 站 在 自 己 的 帐 棚 门 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4223', '4', '16', '28', '摩 西 说 ： “ 我 行 的 这 一 切 事 本 不 是 凭 我 自 己 心 意 行 的 ， 乃 是 耶 和 华 打 发 我 行 的 ， 必 有 证 据 使 你 们 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4224', '4', '16', '29', '这 些 人 死 若 与 世 人 无 异 ， 或 是 他 们 所 遭 的 与 世 人 相 同 ， 就 不 是 耶 和 华 打 发 我 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4225', '4', '16', '30', '倘 若 耶 和 华 创 作 一 件 新 事 ， 使 地 开 口 ， 把 他 们 和 一 切 属 他 们 的 都 吞 下 去 ， 叫 他 们 活 活 地 坠 落 阴 间 ， 你 们 就 明 白 这 些 人 是 藐 视 耶 和 华 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4226', '4', '16', '31', '摩 西 刚 说 完 了 这 一 切 话 ， 他 们 脚 下 的 地 就 开 了 口 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4227', '4', '16', '32', '把 他 们 和 他 们 的 家 眷 ， 并 一 切 属 可 拉 的 人 丁 、 财 物 ， 都 吞 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4228', '4', '16', '33', '这 样 ， 他 们 和 一 切 属 他 们 的 ， 都 活 活 地 坠 落 阴 间 ； 地 口 在 他 们 上 头 照 旧 合 闭 ， 他 们 就 从 会 中 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4229', '4', '16', '34', '在 他 们 四 围 的 以 色 列 众 人 听 他 们 呼 号 ， 就 都 逃 跑 ， 说 ： “ 恐 怕 地 也 把 我 们 吞 下 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4230', '4', '16', '35', '又 有 火 从 耶 和 华 那 里 出 来 ， 烧 灭 了 那 献 香 的 二 百 五 十 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4231', '4', '16', '36', '＜ 香 炉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4232', '4', '16', '37', '“ 你 吩 咐 祭 司 亚 伦 的 儿 子 以 利 亚 撒 从 火 中 捡 起 那 些 香 炉 来 ， 把 火 撒 在 别 处 ， 因 为 那 些 香 炉 是 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4233', '4', '16', '38', '把 那 些 犯 罪 、 自 害 己 命 之 人 的 香 炉 ， 叫 人 锤 成 片 子 ， 用 以 包 坛 。 那 些 香 炉 本 是 他 们 在 耶 和 华 面 前 献 过 的 ， 所 以 是 圣 的 ， 并 且 可 以 给 以 色 列 人 作 记 号 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4234', '4', '16', '39', '于 是 祭 司 以 利 亚 撒 将 被 烧 之 人 所 献 的 铜 香 炉 拿 来 ， 人 就 锤 出 来 ， 用 以 包 坛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4235', '4', '16', '40', '给 以 色 列 人 作 纪 念 ， 使 亚 伦 后 裔 之 外 的 人 不 得 近 前 来 在 耶 和 华 面 前 烧 香 ， 免 得 他 遭 可 拉 和 他 一 党 所 遭 的 。 这 乃 是 照 耶 和 华 藉 着 摩 西 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4236', '4', '16', '41', '＜ 亚 伦 救 了 人 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4237', '4', '16', '42', '会 众 聚 集 攻 击 摩 西 、 亚 伦 的 时 候 ， 向 会 幕 观 看 ， 不 料 ， 有 云 彩 遮 盖 了 ， 耶 和 华 的 荣 光 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4238', '4', '16', '43', '摩 西 、 亚 伦 就 来 到 会 幕 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4239', '4', '16', '44', '耶 和 华 吩 咐 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4240', '4', '16', '45', '“ 你 们 离 开 这 会 众 ， 我 好 在 转 眼 之 间 把 他 们 灭 绝 。 ” 他 们 二 人 就 俯 伏 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4241', '4', '16', '46', '摩 西 对 亚 伦 说 ： “ 拿 你 的 香 炉 ， 把 坛 上 的 火 盛 在 其 中 ， 又 加 上 香 ， 快 快 带 到 会 众 那 里 ， 为 他 们 赎 罪 ； 因 为 有 忿 怒 从 耶 和 华 那 里 出 来 ， 瘟 疫 已 经 发 作 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4242', '4', '16', '47', '亚 伦 照 着 摩 西 所 说 的 拿 来 ， 跑 到 会 中 ， 不 料 ， 瘟 疫 在 百 姓 中 已 经 发 作 了 。 他 就 加 上 香 ， 为 百 姓 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4243', '4', '16', '48', '他 站 在 活 人 死 人 中 间 ， 瘟 疫 就 止 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4244', '4', '16', '49', '除 了 因 可 拉 事 情 死 的 以 外 ， 遭 瘟 疫 死 的 ， 共 有 一 万 四 千 七 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4245', '4', '16', '50', '亚 伦 回 到 会 幕 门 口 ， 到 摩 西 那 里 ， 瘟 疫 已 经 止 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4246', '4', '17', '1', '＜ 亚 伦 的 杖 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4247', '4', '17', '2', '“ 你 晓 谕 以 色 列 人 ， 从 他 们 手 下 取 杖 ， 每 支 派 一 根 ； 从 他 们 所 有 的 首 领 ， 按 着 支 派 ， 共 取 十 二 根 。 你 要 将 各 人 的 名 字 写 在 各 人 的 杖 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4248', '4', '17', '3', '并 要 将 亚 伦 的 名 字 写 在 利 未 的 杖 上 ， 因 为 各 族 长 必 有 一 根 杖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4249', '4', '17', '4', '你 要 把 这 些 杖 存 在 会 幕 内 法 柜 前 ， 就 是 我 与 你 们 相 会 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4250', '4', '17', '5', '后 来 我 所 拣 选 的 那 人 ， 他 的 杖 必 发 芽 。 这 样 ， 我 必 使 以 色 列 人 向 你 们 所 发 的 怨 言 止 息 ， 不 再 达 到 我 耳 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4251', '4', '17', '6', '于 是 摩 西 晓 谕 以 色 列 人 ， 他 们 的 首 领 就 把 杖 交 给 他 ， 按 着 支 派 ， 每 首 领 一 根 ， 共 有 十 二 根 ； 亚 伦 的 杖 也 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4252', '4', '17', '7', '摩 西 就 把 杖 存 在 法 柜 的 帐 幕 内 ， 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4253', '4', '17', '8', '第 二 天 ， 摩 西 进 法 柜 的 帐 幕 去 。 谁 知 利 未 族 亚 伦 的 杖 已 经 发 了 芽 ， 生 了 花 苞 ， 开 了 花 ， 结 了 熟 杏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4254', '4', '17', '9', '摩 西 就 把 所 有 的 杖 从 耶 和 华 面 前 拿 出 来 ， 给 以 色 列 众 人 看 ； 他 们 看 见 了 ， 各 首 领 就 把 自 己 的 杖 拿 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4255', '4', '17', '10', '耶 和 华 吩 咐 摩 西 说 ： “ 把 亚 伦 的 杖 还 放 在 法 柜 前 ， 给 这 些 背 叛 之 子 留 作 记 号 。 这 样 ， 你 就 使 他 们 向 我 发 的 怨 言 止 息 ， 免 得 他 们 死 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4256', '4', '17', '11', '摩 西 就 这 样 行 。 耶 和 华 怎 样 吩 咐 他 ， 他 就 怎 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4257', '4', '17', '12', '以 色 列 人 对 摩 西 说 ： “ 我 们 死 啦 ！ 我 们 灭 亡 啦 ！ 都 灭 亡 啦 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4258', '4', '17', '13', '凡 挨 近 耶 和 华 帐 幕 的 是 必 死 的 。 我 们 都 要 死 亡 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4259', '4', '18', '1', '＜ 祭 司 和 利 未 人 的 职 责 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4260', '4', '18', '2', '你 要 带 你 弟 兄 利 未 人 ， 就 是 你 祖 宗 支 派 的 人 前 来 ， 使 他 们 与 你 联 合 ， 服 事 你 ， 只 是 你 和 你 的 儿 子 ， 要 一 同 在 法 柜 的 帐 幕 前 供 职 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4261', '4', '18', '3', '他 们 要 守 所 吩 咐 你 的 ， 并 守 全 帐 幕 ， 只 是 不 可 挨 近 圣 所 的 器 具 和 坛 ， 免 得 他 们 和 你 们 都 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4262', '4', '18', '4', '他 们 要 与 你 联 合 ， 也 要 看 守 会 幕 ， 办 理 帐 幕 一 切 的 事 ， 只 是 外 人 不 可 挨 近 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4263', '4', '18', '5', '你 们 要 看 守 圣 所 和 坛 ， 免 得 忿 怒 再 临 到 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4264', '4', '18', '6', '我 已 将 你 们 的 弟 兄 利 未 人 从 以 色 列 人 中 拣 选 出 来 归 耶 和 华 ， 是 给 你 们 为 赏 赐 的 ， 为 要 办 理 会 幕 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4265', '4', '18', '7', '你 和 你 的 儿 子 要 为 一 切 属 坛 和 幔 子 内 的 事 一 同 守 祭 司 的 职 任 。 你 们 要 这 样 供 职 ； 我 将 祭 司 的 职 任 给 你 们 当 作 赏 赐 事 奉 我 。 凡 挨 近 的 外 人 必 被 治 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4266', '4', '18', '8', '＜ 祭 司 当 得 之 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4267', '4', '18', '9', '以 色 列 人 归 给 我 至 圣 的 供 物 ， 就 是 一 切 的 素 祭 、 赎 罪 祭 、 赎 愆 祭 ， 其 中 所 有 存 留 不 经 火 的 ， 都 为 至 圣 之 物 ， 要 归 给 你 和 你 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4268', '4', '18', '10', '你 要 拿 这 些 当 至 圣 物 吃 ； 凡 男 丁 都 可 以 吃 。 你 当 以 此 物 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4269', '4', '18', '11', '以 色 列 人 所 献 的 举 祭 并 摇 祭 都 是 你 的 ； 我 已 赐 给 你 和 你 的 儿 女 ， 当 作 永 得 的 分 ； 凡 在 你 家 中 的 洁 净 人 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4270', '4', '18', '12', '凡 油 中 、 新 酒 中 、 五 谷 中 至 好 的 ， 就 是 以 色 列 人 所 献 给 耶 和 华 初 熟 之 物 ， 我 都 赐 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4271', '4', '18', '13', '凡 从 他 们 地 上 所 带 来 给 耶 和 华 初 熟 之 物 也 都 要 归 与 你 。 你 家 中 的 洁 净 人 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4272', '4', '18', '14', '以 色 列 中 一 切 永 献 的 都 必 归 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4273', '4', '18', '15', '他 们 所 有 奉 给 耶 和 华 的 ， 连 人 带 牲 畜 ， 凡 头 生 的 ， 都 要 归 给 你 ； 只 是 人 头 生 的 ， 总 要 赎 出 来 ； 不 洁 净 牲 畜 头 生 的 ， 也 要 赎 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4274', '4', '18', '16', '其 中 在 一 月 之 外 所 当 赎 的 ， 要 照 你 所 估 定 的 价 ， 按 圣 所 的 平 ， 用 银 子 五 舍 客 勒 赎 出 来 （ 一 舍 客 勒 是 二 十 季 拉 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4275', '4', '18', '17', '只 是 头 生 的 牛 ， 或 是 头 生 的 绵 羊 和 山 羊 ， 必 不 可 赎 ， 都 是 圣 的 ， 要 把 它 的 血 洒 在 坛 上 ， 把 它 的 脂 油 焚 烧 ， 当 作 馨 香 的 火 祭 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4276', '4', '18', '18', '它 的 肉 必 归 你 ， 像 被 摇 的 胸 、 被 举 的 右 腿 归 你 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4277', '4', '18', '19', '凡 以 色 列 人 所 献 给 耶 和 华 圣 物 中 的 举 祭 ， 我 都 赐 给 你 和 你 的 儿 女 ， 当 作 永 得 的 分 。 这 是 给 你 和 你 的 后 裔 、 在 耶 和 华 面 前 作 为 永 远 的 盐 约 ｛ 盐 就 是 不 废 坏 的 意 思 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4278', '4', '18', '20', '耶 和 华 对 亚 伦 说 ： “ 你 在 以 色 列 人 的 境 内 不 可 有 产 业 ， 在 他 们 中 间 也 不 可 有 分 。 我 就 是 你 的 分 ， 是 你 的 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4279', '4', '18', '21', '＜ 利 未 人 的 分 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4280', '4', '18', '22', '从 今 以 后 ， 以 色 列 人 不 可 挨 近 会 幕 ， 免 得 他 们 担 罪 而 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4281', '4', '18', '23', '惟 独 利 未 人 要 办 会 幕 的 事 ， 担 当 罪 孽 ； 这 要 作 你 们 世 世 代 代 永 远 的 定 例 。 他 们 在 以 色 列 人 中 不 可 有 产 业 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4282', '4', '18', '24', '因 为 以 色 列 人 中 出 产 的 十 分 之 一 ， 就 是 献 给 耶 和 华 为 举 祭 的 ， 我 已 赐 给 利 未 人 为 业 。 所 以 我 对 他 们 说 ： ‘ 在 以 色 列 人 中 不 可 有 产 业 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4283', '4', '18', '25', '＜ 利 未 人 的 十 一 奉 献 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4284', '4', '18', '26', '“ 你 晓 谕 利 未 人 说 ： 你 们 从 以 色 列 人 中 所 取 的 十 分 之 一 ， 就 是 我 给 你 们 为 业 的 ， 要 再 从 那 十 分 之 一 中 取 十 分 之 一 作 为 举 祭 献 给 耶 和 华 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4285', '4', '18', '27', '这 举 祭 要 算 为 你 们 场 上 的 谷 ， 又 如 满 酒 醡 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4286', '4', '18', '28', '这 样 ， 你 们 从 以 色 列 人 中 所 得 的 十 分 之 一 也 要 作 举 祭 献 给 耶 和 华 ， 从 这 十 分 之 一 中 ， 将 所 献 给 耶 和 华 的 举 祭 归 给 祭 司 亚 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4287', '4', '18', '29', '奉 给 你 们 的 一 切 礼 物 ， 要 从 其 中 将 至 好 的 ， 就 是 分 别 为 圣 的 ， 献 给 耶 和 华 为 举 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4288', '4', '18', '30', '所 以 你 要 对 利 未 人 说 ： 你 们 从 其 中 将 至 好 的 举 起 ， 这 就 算 为 你 们 场 上 的 粮 ， 又 如 酒 醡 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4289', '4', '18', '31', '你 们 和 你 们 家 属 随 处 可 以 吃 ； 这 原 是 你 们 的 赏 赐 ， 是 酬 你 们 在 会 幕 里 办 事 的 劳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4290', '4', '18', '32', '你 们 从 其 中 将 至 好 的 举 起 ， 就 不 致 因 这 物 担 罪 。 你 们 不 可 亵 渎 以 色 列 人 的 圣 物 ， 免 得 死 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4291', '4', '19', '1', '＜ 红 母 牛 的 灰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4292', '4', '19', '2', '“ 耶 和 华 命 定 律 法 中 的 一 条 律 例 乃 是 这 样 说 ： 你 要 吩 咐 以 色 列 人 ， 把 一 只 没 有 残 疾 、 未 曾 负 轭 、 纯 红 的 母 牛 牵 到 你 这 里 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4293', '4', '19', '3', '交 给 祭 司 以 利 亚 撒 ； 他 必 牵 到 营 外 ， 人 就 把 牛 宰 在 他 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4294', '4', '19', '4', '祭 司 以 利 亚 撒 要 用 指 头 蘸 这 牛 的 血 ， 向 会 幕 前 面 弹 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4295', '4', '19', '5', '人 要 在 他 眼 前 把 这 母 牛 焚 烧 ； 牛 的 皮 、 肉 、 血 、 粪 都 要 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4296', '4', '19', '6', '祭 司 要 把 香 柏 木 、 牛 膝 草 、 朱 红 色 线 都 丢 在 烧 牛 的 火 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4297', '4', '19', '7', '祭 司 必 不 洁 净 到 晚 上 ， 要 洗 衣 服 ， 用 水 洗 身 ， 然 后 可 以 进 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4298', '4', '19', '8', '烧 牛 的 人 必 不 洁 净 到 晚 上 ， 也 要 洗 衣 服 ， 用 水 洗 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4299', '4', '19', '9', '必 有 一 个 洁 净 的 人 收 起 母 牛 的 灰 ， 存 在 营 外 洁 净 的 地 方 ， 为 以 色 列 会 众 调 做 除 污 秽 的 水 。 这 本 是 除 罪 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4300', '4', '19', '10', '收 起 母 牛 灰 的 人 必 不 洁 净 到 晚 上 ， 要 洗 衣 服 。 这 要 给 以 色 列 人 和 寄 居 在 他 们 中 间 的 外 人 作 为 永 远 的 定 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4301', '4', '19', '11', '＜ 接 触 尸 体 不 洁 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4302', '4', '19', '12', '那 人 到 第 三 天 要 用 这 除 污 秽 的 水 洁 净 自 己 ， 第 七 天 就 洁 净 了 。 他 若 在 第 三 天 不 洁 净 自 己 ， 第 七 天 就 不 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4303', '4', '19', '13', '凡 摸 了 人 死 尸 、 不 洁 净 自 己 的 ， 就 玷 污 了 耶 和 华 的 帐 幕 ， 这 人 必 从 以 色 列 中 剪 除 ； 因 为 那 除 污 秽 的 水 没 有 洒 在 他 身 上 ， 他 就 为 不 洁 净 ， 污 秽 还 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4304', '4', '19', '14', '“ 人 死 在 帐 棚 里 的 条 例 乃 是 这 样 ： 凡 进 那 帐 棚 的 ， 和 一 切 在 帐 棚 里 的 ， 都 必 七 天 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4305', '4', '19', '15', '凡 敞 口 的 器 皿 ， 就 是 没 有 扎 上 盖 的 ， 也 是 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4306', '4', '19', '16', '无 论 何 人 在 田 野 里 摸 了 被 刀 杀 的 ， 或 是 尸 首 ， 或 是 人 的 骨 头 ， 或 是 坟 墓 ， 就 要 七 天 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4307', '4', '19', '17', '要 为 这 不 洁 净 的 人 拿 些 烧 成 的 除 罪 灰 放 在 器 皿 里 ， 倒 上 活 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4308', '4', '19', '18', '必 当 有 一 个 洁 净 的 人 拿 牛 膝 草 蘸 在 这 水 中 ， 把 水 洒 在 帐 棚 上 ， 和 一 切 器 皿 并 帐 棚 内 的 众 人 身 上 ， 又 洒 在 摸 了 骨 头 ， 或 摸 了 被 杀 的 ， 或 摸 了 自 死 的 ， 或 摸 了 坟 墓 的 那 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4309', '4', '19', '19', '第 三 天 和 第 七 天 ， 洁 净 的 人 要 洒 水 在 不 洁 净 的 人 身 上 ， 第 七 天 就 使 他 成 为 洁 净 。 那 人 要 洗 衣 服 ， 用 水 洗 澡 ， 到 晚 上 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4310', '4', '19', '20', '“ 但 那 污 秽 而 不 洁 净 自 己 的 ， 要 将 他 从 会 中 剪 除 ， 因 为 他 玷 污 了 耶 和 华 的 圣 所 。 除 污 秽 的 水 没 有 洒 在 他 身 上 ， 他 是 不 洁 净 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4311', '4', '19', '21', '这 要 给 你 们 作 为 永 远 的 定 例 。 并 且 那 洒 除 污 秽 水 的 人 要 洗 衣 服 。 凡 摸 除 污 秽 水 的 ， 必 不 洁 净 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4312', '4', '19', '22', '不 洁 净 人 所 摸 的 一 切 物 就 不 洁 净 ； 摸 了 这 物 的 人 必 不 洁 净 到 晚 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4313', '4', '20', '1', '＜ 在 加 低 斯 发 生 的 事 件 （ 出   1 7 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4314', '4', '20', '2', '会 众 没 有 水 喝 ， 就 聚 集 攻 击 摩 西 、 亚 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4315', '4', '20', '3', '百 姓 向 摩 西 争 闹 说 ： “ 我 们 的 弟 兄 曾 死 在 耶 和 华 面 前 ， 我 们 恨 不 得 与 他 们 同 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4316', '4', '20', '4', '你 们 为 何 把 耶 和 华 的 会 众 领 到 这 旷 野 、 使 我 们 和 牲 畜 都 死 在 这 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4317', '4', '20', '5', '你 们 为 何 逼 着 我 们 出 埃 及 、 领 我 们 到 这 坏 地 方 呢 ？ 这 地 方 不 好 撒 种 ， 也 没 有 无 花 果 树 、 葡 萄 树 、 石 榴 树 ， 又 没 有 水 喝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4318', '4', '20', '6', '摩 西 、 亚 伦 离 开 会 众 ， 到 会 幕 门 口 ， 俯 伏 在 地 ； 耶 和 华 的 荣 光 向 他 们 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4319', '4', '20', '7', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4320', '4', '20', '8', '“ 你 拿 着 杖 去 ， 和 你 的 哥 哥 亚 伦 招 聚 会 众 ， 在 他 们 眼 前 吩 咐 磐 石 发 出 水 来 ， 水 就 从 磐 石 流 出 ， 给 会 众 和 他 们 的 牲 畜 喝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4321', '4', '20', '9', '于 是 摩 西 照 耶 和 华 所 吩 咐 的 ， 从 耶 和 华 面 前 取 了 杖 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4322', '4', '20', '10', '摩 西 、 亚 伦 就 招 聚 会 众 到 磐 石 前 。 摩 西 说 ： “ 你 们 这 些 背 叛 的 人 听 我 说 ： 我 为 你 们 使 水 从 这 磐 石 中 流 出 来 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4323', '4', '20', '11', '摩 西 举 手 ， 用 杖 击 打 磐 石 两 下 ， 就 有 许 多 水 流 出 来 ， 会 众 和 他 们 的 牲 畜 都 喝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4324', '4', '20', '12', '耶 和 华 对 摩 西 、 亚 伦 说 ： “ 因 为 你 们 不 信 我 ， 不 在 以 色 列 人 眼 前 尊 我 为 圣 ， 所 以 你 们 必 不 得 领 这 会 众 进 我 所 赐 给 他 们 的 地 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4325', '4', '20', '13', '这 水 名 叫 米 利 巴 水 ｛ 米 利 巴 就 是 争 闹 的 意 思 ｝ ， 是 因 以 色 列 人 向 耶 和 华 争 闹 ， 耶 和 华 就 在 他 们 面 前 显 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4326', '4', '20', '14', '＜ 以 东 王 不 容 以 色 列 人 通 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4327', '4', '20', '15', '就 是 我 们 的 列 祖 下 到 埃 及 ， 我 们 在 埃 及 久 住 ； 埃 及 人 恶 待 我 们 的 列 祖 和 我 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4328', '4', '20', '16', '我 们 哀 求 耶 和 华 的 时 候 ， 他 听 了 我 们 的 声 音 ， 差 遣 使 者 把 我 们 从 埃 及 领 出 来 。 这 事 你 都 知 道 。 如 今 ， 我 们 在 你 边 界 上 的 城 加 低 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4329', '4', '20', '17', '求 你 容 我 们 从 你 的 地 经 过 。 我 们 不 走 田 间 和 葡 萄 园 ， 也 不 喝 井 里 的 水 ， 只 走 大 道 ｛ 原 文 是 王 道 ｝ ， 不 偏 左 右 ， 直 到 过 了 你 的 境 界 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4330', '4', '20', '18', '以 东 王 说 ： “ 你 不 可 从 我 的 地 经 过 ， 免 得 我 带 刀 出 去 攻 击 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4331', '4', '20', '19', '以 色 列 人 说 ： “ 我 们 要 走 大 道 上 去 ； 我 们 和 牲 畜 若 喝 你 的 水 ， 必 给 你 价 值 。 不 求 别 的 ， 只 求 你 容 我 们 步 行 过 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4332', '4', '20', '20', '以 东 王 说 ： “ 你 们 不 可 经 过 ！ ” 就 率 领 许 多 人 出 来 ， 要 用 强 硬 的 手 攻 击 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4333', '4', '20', '21', '这 样 ， 以 东 王 不 肯 容 以 色 列 人 从 他 的 境 界 过 去 。 于 是 他 们 转 去 ， 离 开 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4334', '4', '20', '22', '＜ 亚 伦 逝 世 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4335', '4', '20', '23', '耶 和 华 在 附 近 以 东 边 界 的 何 珥 山 上 晓 谕 摩 西 、 亚 伦 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4336', '4', '20', '24', '“ 亚 伦 要 归 到 他 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 。 他 必 不 得 入 我 所 赐 给 以 色 列 人 的 地 ； 因 为 在 米 利 巴 水 ， 你 们 违 背 了 我 的 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4337', '4', '20', '25', '你 带 亚 伦 和 他 的 儿 子 以 利 亚 撒 上 何 珥 山 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4338', '4', '20', '26', '把 亚 伦 的 圣 衣 脱 下 来 ， 给 他 的 儿 子 以 利 亚 撒 穿 上 ； 亚 伦 必 死 在 那 里 ， 归 他 列 祖 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4339', '4', '20', '27', '摩 西 就 照 耶 和 华 所 吩 咐 的 行 。 三 人 当 着 会 众 的 眼 前 上 了 何 珥 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4340', '4', '20', '28', '摩 西 把 亚 伦 的 圣 衣 脱 下 来 ， 给 他 的 儿 子 以 利 亚 撒 穿 上 ， 亚 伦 就 死 在 山 顶 那 里 。 于 是 摩 西 和 以 利 亚 撒 下 了 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4341', '4', '20', '29', '全 会 众 ， 就 是 以 色 列 全 家 ， 见 亚 伦 已 经 死 了 ， 便 都 为 亚 伦 哀 哭 了 三 十 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4342', '4', '21', '1', '＜ 战 胜 迦 南 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4343', '4', '21', '2', '以 色 列 人 向 耶 和 华 发 愿 说 ： “ 你 若 将 这 民 交 付 我 手 ， 我 就 把 他 们 的 城 邑 尽 行 毁 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4344', '4', '21', '3', '耶 和 华 应 允 了 以 色 列 人 ， 把 迦 南 人 交 付 他 们 ， 他 们 就 把 迦 南 人 和 迦 南 人 的 城 邑 尽 行 毁 灭 。 那 地 方 的 名 便 叫 何 珥 玛 ｛ 就 是 毁 灭 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4345', '4', '21', '4', '＜ 铜 制 的 蛇 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4346', '4', '21', '5', '就 怨 讟 神 和 摩 西 说 ： “ 你 们 为 什 么 把 我 们 从 埃 及 领 出 来 、 使 我 们 死 在 旷 野 呢 ？ 这 里 没 有 粮 ， 没 有 水 ， 我 们 的 心 厌 恶 这 淡 薄 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4347', '4', '21', '6', '于 是 耶 和 华 使 火 蛇 进 入 百 姓 中 间 ， 蛇 就 咬 他 们 。 以 色 列 人 中 死 了 许 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4348', '4', '21', '7', '百 姓 到 摩 西 那 里 ， 说 ： “ 我 们 怨 讟 耶 和 华 和 你 ， 有 罪 了 。 求 你 祷 告 耶 和 华 ， 叫 这 些 蛇 离 开 我 们 。 ” 于 是 摩 西 为 百 姓 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4349', '4', '21', '8', '耶 和 华 对 摩 西 说 ： “ 你 制 造 一 条 火 蛇 ， 挂 在 杆 子 上 ； 凡 被 咬 的 ， 一 望 这 蛇 ， 就 必 得 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4350', '4', '21', '9', '摩 西 便 制 造 一 条 铜 蛇 ， 挂 在 杆 子 上 ； 凡 被 蛇 咬 的 ， 一 望 这 铜 蛇 就 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4351', '4', '21', '10', '＜ 从 何 珥 山 到 摩 押 谷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4352', '4', '21', '11', '又 从 阿 伯 起 行 ， 安 营 在 以 耶 ． 亚 巴 琳 ， 与 摩 押 相 对 的 旷 野 ， 向 日 出 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4353', '4', '21', '12', '从 那 里 起 行 ， 安 营 在 撒 烈 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4354', '4', '21', '13', '从 那 里 起 行 ， 安 营 在 亚 嫩 河 那 边 。 这 亚 嫩 河 是 在 旷 野 ， 从 亚 摩 利 的 境 界 流 出 来 的 ； 原 来 亚 嫩 河 是 摩 押 的 边 界 ， 在 摩 押 和 亚 摩 利 人 搭 界 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4355', '4', '21', '14', '所 以 耶 和 华 的 战 记 上 说 ： “ 苏 法 的 哇 哈 伯 与 亚 嫩 河 的 谷 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4356', '4', '21', '15', '并 向 亚 珥 城 众 谷 的 下 坡 ， 是 靠 近 摩 押 的 境 界 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4357', '4', '21', '16', '以 色 列 人 从 那 里 起 行 ， 到 了 比 珥 ｛ 就 是 井 的 意 思 ｝ 。 从 前 耶 和 华 吩 咐 摩 西 说 ： “ 招 聚 百 姓 ， 我 好 给 他 们 水 喝 ” ， 说 的 就 是 这 井 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4358', '4', '21', '17', '当 时 ， 以 色 列 人 唱 歌 说 ： 井 啊 ， 涌 上 水 来 ！ 你 们 要 向 这 井 歌 唱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4359', '4', '21', '18', '这 井 是 首 领 和 民 中 的 尊 贵 人 用 圭 用 杖 所 挖 所 掘 的 。 以 色 列 人 从 旷 野 往 玛 他 拿 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4360', '4', '21', '19', '从 玛 他 拿 到 拿 哈 列 ， 从 拿 哈 列 到 巴 末 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4361', '4', '21', '20', '从 巴 末 到 摩 押 地 的 谷 ， 又 到 那 下 望 旷 野 之 毗 斯 迦 的 山 顶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4362', '4', '21', '21', '＜ 战 胜 亚 摩 利 王 和 巴 珊 王 （ 申   2 : 2 6 - 3 : 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4363', '4', '21', '22', '“ 求 你 容 我 们 从 你 的 地 经 过 ； 我 们 不 偏 入 田 间 和 葡 萄 园 ， 也 不 喝 井 里 的 水 ， 只 走 大 道 ｛ 原 文 是 王 道 ｝ ， 直 到 过 了 你 的 境 界 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4364', '4', '21', '23', '西 宏 不 容 以 色 列 人 从 他 的 境 界 经 过 ， 就 招 聚 他 的 众 民 出 到 旷 野 ， 要 攻 击 以 色 列 人 ， 到 了 雅 杂 与 以 色 列 人 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4365', '4', '21', '24', '以 色 列 人 用 刀 杀 了 他 ， 得 了 他 的 地 ， 从 亚 嫩 河 到 雅 博 河 ， 直 到 亚 扪 人 的 境 界 ， 因 为 亚 扪 人 的 境 界 多 有 坚 垒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4366', '4', '21', '25', '以 色 列 人 夺 取 这 一 切 的 城 邑 ， 也 住 亚 摩 利 人 的 城 邑 ， 就 是 希 实 本 与 希 实 本 的 一 切 乡 村 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4367', '4', '21', '26', '这 希 实 本 是 亚 摩 利 王 西 宏 的 京 城 ； 西 宏 曾 与 摩 押 的 先 王 争 战 ， 从 他 手 中 夺 取 了 全 地 ， 直 到 亚 嫩 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4368', '4', '21', '27', '所 以 那 些 作 诗 歌 的 说 ： 你 们 来 到 希 实 本 ； 愿 西 宏 的 城 被 修 造 ， 被 建 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4369', '4', '21', '28', '因 为 有 火 从 希 实 本 发 出 ， 有 火 焰 出 于 西 宏 的 城 ， 烧 尽 摩 押 的 亚 珥 和 亚 嫩 河 邱 坛 的 祭 司 ｛ 祭 司 原 文 是 主 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4370', '4', '21', '29', '摩 押 啊 ， 你 有 祸 了 ！ 基 抹 的 民 哪 ， 你 们 灭 亡 了 ！ 基 抹 的 男 子 逃 奔 ， 女 子 被 掳 ， 交 付 亚 摩 利 的 王 西 宏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4371', '4', '21', '30', '我 们 射 了 他 们 ； 希 实 本 直 到 底 本 尽 皆 毁 灭 。 我 们 使 地 变 成 荒 场 ， 直 到 挪 法 ； 这 挪 法 直 延 到 米 底 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4372', '4', '21', '31', '这 样 ， 以 色 列 人 就 住 在 亚 摩 利 人 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4373', '4', '21', '32', '摩 西 打 发 人 去 窥 探 雅 谢 ， 以 色 列 人 就 占 了 雅 谢 的 镇 市 ， 赶 出 那 里 的 亚 摩 利 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4374', '4', '21', '33', '以 色 列 人 转 回 ， 向 巴 珊 去 。 巴 珊 王 噩 和 他 的 众 民 都 出 来 ， 在 以 得 来 与 他 们 交 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4375', '4', '21', '34', '耶 和 华 对 摩 西 说 ： “ 不 要 怕 他 ！ 因 我 已 将 他 和 他 的 众 民 ， 并 他 的 地 ， 都 交 在 你 手 中 ； 你 要 待 他 像 从 前 待 住 希 实 本 的 亚 摩 利 王 西 宏 一 般 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4376', '4', '21', '35', '于 是 他 们 杀 了 他 和 他 的 众 子 ， 并 他 的 众 民 ， 没 有 留 下 一 个 ， 就 得 了 他 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4377', '4', '22', '1', '＜ 摩 押 王 召 巴 兰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4378', '4', '22', '2', '以 色 列 人 向 亚 摩 利 人 所 行 的 一 切 事 ， 西 拨 的 儿 子 巴 勒 都 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4379', '4', '22', '3', '摩 押 人 因 以 色 列 民 甚 多 ， 就 大 大 惧 怕 ， 心 内 忧 急 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4380', '4', '22', '4', '对 米 甸 的 长 老 说 ： “ 现 在 这 众 人 要 把 我 们 四 围 所 有 的 一 概 餂 尽 ， 就 如 牛 餂 尽 田 间 的 草 一 般 。 ” 那 时 西 拨 的 儿 子 巴 勒 作 摩 押 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4381', '4', '22', '5', '他 差 遣 使 者 往 大 河 边 的 毗 夺 去 ， 到 比 珥 的 儿 子 巴 兰 本 乡 那 里 ， 召 巴 兰 来 ， 说 ： “ 有 一 宗 民 从 埃 及 出 来 ， 遮 满 地 面 ， 与 我 对 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4382', '4', '22', '6', '这 民 比 我 强 盛 ， 现 在 求 你 来 为 我 咒 诅 他 们 ， 或 者 我 能 得 胜 ， 攻 打 他 们 ， 赶 出 此 地 。 因 为 我 知 道 ， 你 为 谁 祝 福 ， 谁 就 得 福 ； 你 咒 诅 谁 ， 谁 就 受 咒 诅 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4383', '4', '22', '7', '摩 押 的 长 老 和 米 甸 的 长 老 手 里 拿 着 卦 金 ， 到 了 巴 兰 那 里 ， 将 巴 勒 的 话 都 告 诉 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4384', '4', '22', '8', '巴 兰 说 ： “ 你 们 今 夜 在 这 里 住 宿 ， 我 必 照 耶 和 华 所 晓 谕 我 的 回 报 你 们 。 ” 摩 押 的 使 臣 就 在 巴 兰 那 里 住 下 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4385', '4', '22', '9', '神 临 到 巴 兰 那 里 ， 说 ： “ 在 你 这 里 的 人 都 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4386', '4', '22', '10', '巴 兰 回 答 说 ： “ 是 摩 押 王 西 拨 的 儿 子 巴 勒 打 发 人 到 我 这 里 来 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4387', '4', '22', '11', '‘ 从 埃 及 出 来 的 民 遮 满 地 面 ， 你 来 为 我 咒 诅 他 们 ， 或 者 我 能 与 他 们 争 战 ， 把 他 们 赶 出 去 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4388', '4', '22', '12', '神 对 巴 兰 说 ： “ 你 不 可 同 他 们 去 ， 也 不 可 咒 诅 那 民 ， 因 为 那 民 是 蒙 福 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4389', '4', '22', '13', '巴 兰 早 晨 起 来 ， 对 巴 勒 的 使 臣 说 ： “ 你 们 回 本 地 去 吧 ， 因 为 耶 和 华 不 容 我 和 你 们 同 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4390', '4', '22', '14', '摩 押 的 使 臣 就 起 来 ， 回 巴 勒 那 里 去 ， 说 ： “ 巴 兰 不 肯 和 我 们 同 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4391', '4', '22', '15', '巴 勒 又 差 遣 使 臣 ， 比 先 前 的 又 多 又 尊 贵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4392', '4', '22', '16', '他 们 到 了 巴 兰 那 里 ， 对 他 说 ： “ 西 拨 的 儿 子 巴 勒 这 样 说 ： ‘ 求 你 不 容 什 么 事 拦 阻 你 不 到 我 这 里 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4393', '4', '22', '17', '因 为 我 必 使 你 得 极 大 的 尊 荣 。 你 向 我 要 什 么 ， 我 就 给 你 什 么 ； 只 求 你 来 为 我 咒 诅 这 民 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4394', '4', '22', '18', '巴 兰 回 答 巴 勒 的 臣 仆 说 ： “ 巴 勒 就 是 将 他 满 屋 的 金 银 给 我 ， 我 行 大 事 小 事 也 不 得 越 过 耶 和 华 ─ ─ 我 神 的 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4395', '4', '22', '19', '现 在 我 请 你 们 今 夜 在 这 里 住 宿 ， 等 我 得 知 耶 和 华 还 要 对 我 说 什 么 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4396', '4', '22', '20', '当 夜 ， 神 临 到 巴 兰 那 里 ， 说 ： “ 这 些 人 若 来 召 你 ， 你 就 起 来 同 他 们 去 ， 你 只 要 遵 行 我 对 你 所 说 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4397', '4', '22', '21', '＜ 巴 兰 和 他 的 驴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4398', '4', '22', '22', '神 因 他 去 就 发 了 怒 ； 耶 和 华 的 使 者 站 在 路 上 敌 挡 他 。 他 骑 着 驴 ， 有 两 个 仆 人 跟 随 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4399', '4', '22', '23', '驴 看 见 耶 和 华 的 使 者 站 在 路 上 ， 手 里 有 拔 出 来 的 刀 ， 就 从 路 上 跨 进 田 间 ， 巴 兰 便 打 驴 ， 要 叫 它 回 转 上 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4400', '4', '22', '24', '耶 和 华 的 使 者 就 站 在 葡 萄 园 的 窄 路 上 ； 这 边 有 墙 ， 那 边 也 有 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4401', '4', '22', '25', '驴 看 见 耶 和 华 的 使 者 ， 就 贴 靠 墙 ， 将 巴 兰 的 脚 挤 伤 了 ； 巴 兰 又 打 驴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4402', '4', '22', '26', '耶 和 华 的 使 者 又 往 前 去 ， 站 在 狭 窄 之 处 ， 左 右 都 没 有 转 折 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4403', '4', '22', '27', '驴 看 见 耶 和 华 的 使 者 ， 就 卧 在 巴 兰 底 下 ， 巴 兰 发 怒 ， 用 杖 打 驴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4404', '4', '22', '28', '耶 和 华 叫 驴 开 口 ， 对 巴 兰 说 ： “ 我 向 你 行 了 什 么 ， 你 竟 打 我 这 三 次 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4405', '4', '22', '29', '巴 兰 对 驴 说 ： “ 因 为 你 戏 弄 我 ， 我 恨 不 能 手 中 有 刀 ， 把 你 杀 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4406', '4', '22', '30', '驴 对 巴 兰 说 ： “ 我 不 是 你 从 小 时 直 到 今 日 所 骑 的 驴 吗 ？ 我 素 常 向 你 这 样 行 过 吗 ？ ” 巴 兰 说 ： “ 没 有 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4407', '4', '22', '31', '当 时 ， 耶 和 华 使 巴 兰 的 眼 目 明 亮 ， 他 就 看 见 耶 和 华 的 使 者 站 在 路 上 ， 手 里 有 拔 出 来 的 刀 ， 巴 兰 便 低 头 俯 伏 在 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4408', '4', '22', '32', '耶 和 华 的 使 者 对 他 说 ： “ 你 为 何 这 三 次 打 你 的 驴 呢 ？ 我 出 来 敌 挡 你 ， 因 你 所 行 的 ， 在 我 面 前 偏 僻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4409', '4', '22', '33', '驴 看 见 我 就 三 次 从 我 面 前 偏 过 去 ； 驴 若 没 有 偏 过 去 ， 我 早 把 你 杀 了 ， 留 它 存 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4410', '4', '22', '34', '巴 兰 对 耶 和 华 的 使 者 说 ： “ 我 有 罪 了 。 我 不 知 道 你 站 在 路 上 阻 挡 我 ； 你 若 不 喜 欢 我 去 ， 我 就 转 回 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4411', '4', '22', '35', '耶 和 华 的 使 者 对 巴 兰 说 ： “ 你 同 这 些 人 去 吧 ！ 你 只 要 说 我 对 你 说 的 话 。 ” 于 是 巴 兰 同 着 巴 勒 的 使 臣 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4412', '4', '22', '36', '＜ 巴 勒 欢 迎 巴 兰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4413', '4', '22', '37', '巴 勒 对 巴 兰 说 ： “ 我 不 是 急 急 地 打 发 人 到 你 那 里 去 召 你 吗 ？ 你 为 何 不 到 我 这 里 来 呢 ？ 我 岂 不 能 使 你 得 尊 荣 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4414', '4', '22', '38', '巴 兰 说 ： “ 我 已 经 到 你 这 里 来 了 ！ 现 在 我 岂 能 擅 自 说 什 么 呢 ？ 神 将 什 么 话 传 给 我 ， 我 就 说 什 么 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4415', '4', '22', '39', '巴 兰 和 巴 勒 同 行 ， 来 到 基 列 ． 胡 琐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4416', '4', '22', '40', '巴 勒 宰 了 ｛ 原 文 是 献 ｝ 牛 羊 ， 送 给 巴 兰 和 陪 伴 的 使 臣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4417', '4', '22', '41', '＜ 巴 兰 首 次 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4418', '4', '23', '1', '巴 兰 对 巴 勒 说 ： “ 你 在 这 里 给 我 筑 七 座 坛 ， 为 我 预 备 七 只 公 牛 ， 七 只 公 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4419', '4', '23', '2', '巴 勒 照 巴 兰 的 话 行 了 。 巴 勒 和 巴 兰 在 每 座 坛 上 献 一 只 公 牛 ， 一 只 公 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4420', '4', '23', '3', '巴 兰 对 巴 勒 说 ： “ 你 站 在 你 的 燔 祭 旁 边 ， 我 且 往 前 去 ， 或 者 耶 和 华 来 迎 见 我 。 他 指 示 我 什 么 ， 我 必 告 诉 你 。 ” 于 是 巴 兰 上 一 净 光 的 高 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4421', '4', '23', '4', '神 迎 见 巴 兰 ； 巴 兰 说 ： “ 我 预 备 了 七 座 坛 ， 在 每 座 坛 上 献 了 一 只 公 牛 ， 一 只 公 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4422', '4', '23', '5', '耶 和 华 将 话 传 给 巴 兰 ， 又 说 ： “ 你 回 到 巴 勒 那 里 ， 要 如 此 如 此 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4423', '4', '23', '6', '他 就 回 到 巴 勒 那 里 ， 见 他 同 摩 押 的 使 臣 都 站 在 燔 祭 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4424', '4', '23', '7', '巴 兰 便 题 起 诗 歌 说 ： 巴 勒 引 我 出 亚 兰 ， 摩 押 王 引 我 出 东 山 ， 说 ： 来 啊 ， 为 我 咒 诅 雅 各 ； 来 啊 ， 怒 骂 以 色 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4425', '4', '23', '8', '神 没 有 咒 诅 的 ， 我 焉 能 咒 诅 ？ 耶 和 华 没 有 怒 骂 的 ， 我 焉 能 怒 骂 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4426', '4', '23', '9', '我 从 高 峰 看 他 ， 从 小 山 望 他 ； 这 是 独 居 的 民 ， 不 列 在 万 民 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4427', '4', '23', '10', '谁 能 数 点 雅 各 的 尘 土 ？ 谁 能 计 算 以 色 列 的 四 分 之 一 ？ 我 愿 如 义 人 之 死 而 死 ； 我 愿 如 义 人 之 终 而 终 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4428', '4', '23', '11', '巴 勒 对 巴 兰 说 ： “ 你 向 我 做 的 是 什 么 事 呢 ？ 我 领 你 来 咒 诅 我 的 仇 敌 ， 不 料 ， 你 竟 为 他 们 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4429', '4', '23', '12', '他 回 答 说 ： “ 耶 和 华 传 给 我 的 话 ， 我 能 不 谨 慎 传 说 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4430', '4', '23', '13', '＜ 巴 兰 第 二 次 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4431', '4', '23', '14', '于 是 领 巴 兰 到 了 琐 腓 田 ， 上 了 毗 斯 迦 山 顶 ， 筑 了 七 座 坛 ； 每 座 坛 上 献 一 只 公 牛 ， 一 只 公 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4432', '4', '23', '15', '巴 兰 对 巴 勒 说 ： “ 你 站 在 这 燔 祭 旁 边 ， 等 我 往 那 边 去 迎 见 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4433', '4', '23', '16', '耶 和 华 临 到 巴 兰 那 里 ， 将 话 传 给 他 ； 又 说 ： “ 你 回 到 巴 勒 那 里 ， 要 如 此 如 此 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4434', '4', '23', '17', '他 就 回 到 巴 勒 那 里 ， 见 他 站 在 燔 祭 旁 边 ； 摩 押 的 使 臣 也 和 他 在 一 处 。 巴 勒 问 他 说 ： “ 耶 和 华 说 了 什 么 话 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4435', '4', '23', '18', '巴 兰 就 题 诗 歌 说 ： 巴 勒 ， 你 起 来 听 ； 西 拨 的 儿 子 ， 你 听 我 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4436', '4', '23', '19', '神 非 人 ， 必 不 致 说 谎 ， 也 非 人 子 ， 必 不 致 后 悔 。 他 说 话 岂 不 照 着 行 呢 ？ 他 发 言 岂 不 要 成 就 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4437', '4', '23', '20', '我 奉 命 祝 福 ； 神 也 曾 赐 福 ， 此 事 我 不 能 翻 转 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4438', '4', '23', '21', '他 未 见 雅 各 中 有 罪 孽 ， 也 未 见 以 色 列 中 有 奸 恶 。 耶 和 华 ─ ─ 他 的 神 和 他 同 在 ； 有 欢 呼 王 的 声 音 在 他 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4439', '4', '23', '22', '神 领 他 们 出 埃 及 ； 他 们 似 乎 有 野 牛 之 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4440', '4', '23', '23', '断 没 有 法 术 可 以 害 雅 各 ， 也 没 有 占 卜 可 以 害 以 色 列 。 现 在 必 有 人 论 及 雅 各 ， 就 是 论 及 以 色 列 说 ： 神 为 他 行 了 何 等 的 大 事 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4441', '4', '23', '24', '这 民 起 来 ， 仿 佛 母 狮 ， 挺 身 ， 好 像 公 狮 ， 未 曾 吃 野 食 ， 未 曾 喝 被 伤 者 之 血 ， 决 不 躺 卧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4442', '4', '23', '25', '巴 勒 对 巴 兰 说 ： “ 你 一 点 不 要 咒 诅 他 们 ， 也 不 要 为 他 们 祝 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4443', '4', '23', '26', '巴 兰 回 答 巴 勒 说 ： “ 我 岂 不 是 告 诉 你 说 ‘ 凡 耶 和 华 所 说 的 ， 我 必 须 遵 行 ’ 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4444', '4', '23', '27', '＜ 巴 兰 第 三 次 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4445', '4', '23', '28', '巴 勒 就 领 巴 兰 到 那 下 望 旷 野 的 毗 珥 山 顶 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4446', '4', '23', '29', '巴 兰 对 巴 勒 说 ： “ 你 在 这 里 为 我 筑 七 座 坛 ， 又 在 这 里 为 我 预 备 七 只 公 牛 ， 七 只 公 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4447', '4', '23', '30', '巴 勒 就 照 巴 兰 的 话 行 ， 在 每 座 坛 上 献 一 只 公 牛 ， 一 只 公 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4448', '4', '24', '1', '巴 兰 见 耶 和 华 喜 欢 赐 福 与 以 色 列 ， 就 不 像 前 两 次 去 求 法 术 ， 却 面 向 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4449', '4', '24', '2', '巴 兰 举 目 ， 看 见 以 色 列 人 照 着 支 派 居 住 。 神 的 灵 就 临 到 他 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4450', '4', '24', '3', '他 便 题 起 诗 歌 说 ： 比 珥 的 儿 子 巴 兰 说 ， 眼 目 闭 住 ｛ 或 译 ： 睁 开 ｝ 的 人 说 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4451', '4', '24', '4', '得 听 神 的 言 语 ， 得 见 全 能 者 的 异 象 ， 眼 目 睁 开 而 仆 倒 的 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4452', '4', '24', '5', '雅 各 啊 ， 你 的 帐 棚 何 等 华 美 ！ 以 色 列 啊 ， 你 的 帐 幕 何 其 华 丽 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4453', '4', '24', '6', '如 接 连 的 山 谷 ， 如 河 旁 的 园 子 ， 如 耶 和 华 所 栽 的 沉 香 树 ， 如 水 边 的 香 柏 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4454', '4', '24', '7', '水 要 从 他 的 桶 里 流 出 ； 种 子 要 撒 在 多 水 之 处 。 他 的 王 必 超 过 亚 甲 ； 他 的 国 必 要 振 兴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4455', '4', '24', '8', '神 领 他 出 埃 及 ； 他 似 乎 有 野 牛 之 力 。 他 要 吞 吃 敌 国 ， 折 断 他 们 的 骨 头 ， 用 箭 射 透 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4456', '4', '24', '9', '他 蹲 如 公 狮 ， 卧 如 母 狮 ， 谁 敢 惹 他 ？ 凡 给 你 祝 福 的 ， 愿 他 蒙 福 ； 凡 咒 诅 你 的 ， 愿 他 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4457', '4', '24', '10', '巴 勒 向 巴 兰 生 气 ， 就 拍 起 手 来 ， 对 巴 兰 说 ： “ 我 召 你 来 为 我 咒 诅 仇 敌 ， 不 料 ， 你 这 三 次 竟 为 他 们 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4458', '4', '24', '11', '如 今 你 快 回 本 地 去 吧 ！ 我 想 使 你 得 大 尊 荣 ， 耶 和 华 却 阻 止 你 不 得 尊 荣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4459', '4', '24', '12', '巴 兰 对 巴 勒 说 ： “ 我 岂 不 是 对 你 所 差 遣 到 我 那 里 的 使 者 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4460', '4', '24', '13', '‘ 巴 勒 就 是 将 他 满 屋 的 金 银 给 我 ， 我 也 不 得 越 过 耶 和 华 的 命 ， 凭 自 己 的 心 意 行 好 行 歹 。 耶 和 华 说 什 么 ， 我 就 要 说 什 么 ’ ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4461', '4', '24', '14', '＜ 巴 兰 末 次 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4462', '4', '24', '15', '他 就 题 起 诗 歌 说 ： 比 珥 的 儿 子 巴 兰 说 ： 眼 目 闭 住 ｛ 或 译 ： 睁 开 ｝ 的 人 说 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4463', '4', '24', '16', '得 听 神 的 言 语 ， 明 白 至 高 者 的 意 旨 ， 看 见 全 能 者 的 异 象 ， 眼 目 睁 开 而 仆 倒 的 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4464', '4', '24', '17', '我 看 他 却 不 在 现 时 ； 我 望 他 却 不 在 近 日 。 有 星 要 出 于 雅 各 ， 有 杖 要 兴 于 以 色 列 ， 必 打 破 摩 押 的 四 角 ， 毁 坏 扰 乱 之 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4465', '4', '24', '18', '他 必 得 以 东 为 基 业 ， 又 得 仇 敌 之 地 西 珥 为 产 业 ； 以 色 列 必 行 事 勇 敢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4466', '4', '24', '19', '有 一 位 出 于 雅 各 的 ， 必 掌 大 权 ； 他 要 除 灭 城 中 的 余 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4467', '4', '24', '20', '巴 兰 观 看 亚 玛 力 ， 就 题 起 诗 歌 说 ： 亚 玛 力 原 为 诸 国 之 首 ， 但 他 终 必 沉 沦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4468', '4', '24', '21', '巴 兰 观 看 基 尼 人 ， 就 题 起 诗 歌 说 ： 你 的 住 处 本 是 坚 固 ； 你 的 窝 巢 做 在 岩 穴 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4469', '4', '24', '22', '然 而 基 尼 必 至 衰 微 ， 直 到 亚 述 把 你 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4470', '4', '24', '23', '巴 兰 又 题 起 诗 歌 说 ： 哀 哉 ！ 神 行 这 事 ， 谁 能 得 活 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4471', '4', '24', '24', '必 有 人 乘 船 从 基 提 界 而 来 ， 苦 害 亚 述 ， 苦 害 希 伯 ； 他 也 必 至 沉 沦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4472', '4', '24', '25', '于 是 巴 兰 起 来 ， 回 他 本 地 去 ； 巴 勒 也 回 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4473', '4', '25', '1', '＜ 以 色 列 人 在 毗 珥 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4474', '4', '25', '2', '因 为 这 女 子 叫 百 姓 来 ， 一 同 给 她 们 的 神 献 祭 ， 百 姓 就 吃 她 们 的 祭 物 ， 跪 拜 她 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4475', '4', '25', '3', '以 色 列 人 与 巴 力 ． 毗 珥 连 合 ， 耶 和 华 的 怒 气 就 向 以 色 列 人 发 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4476', '4', '25', '4', '耶 和 华 吩 咐 摩 西 说 ： “ 将 百 姓 中 所 有 的 族 长 在 我 面 前 对 着 日 头 悬 挂 ， 使 我 向 以 色 列 人 所 发 的 怒 气 可 以 消 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4477', '4', '25', '5', '于 是 摩 西 吩 咐 以 色 列 的 审 判 官 说 ： “ 凡 属 你 们 的 人 ， 有 与 巴 力 ． 毗 珥 连 合 的 ， 你 们 各 人 要 把 他 们 杀 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4478', '4', '25', '6', '摩 西 和 以 色 列 全 会 众 正 在 会 幕 门 前 哭 泣 的 时 候 ， 谁 知 ， 有 以 色 列 中 的 一 个 人 ， 当 他 们 眼 前 ， 带 着 一 个 米 甸 女 人 到 他 弟 兄 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4479', '4', '25', '7', '祭 司 亚 伦 的 孙 子 ， 以 利 亚 撒 的 儿 子 非 尼 哈 看 见 了 ， 就 从 会 中 起 来 ， 手 里 拿 着 枪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4480', '4', '25', '8', '跟 随 那 以 色 列 人 进 亭 子 里 去 ， 便 将 以 色 列 人 和 那 女 人 由 腹 中 刺 透 。 这 样 ， 在 以 色 列 人 中 瘟 疫 就 止 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4481', '4', '25', '9', '那 时 遭 瘟 疫 死 的 ， 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4482', '4', '25', '10', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4483', '4', '25', '11', '“ 祭 司 亚 伦 的 孙 子 ， 以 利 亚 撒 的 儿 子 非 尼 哈 ， 使 我 向 以 色 列 人 所 发 的 怒 消 了 ； 因 他 在 他 们 中 间 ， 以 我 的 忌 邪 为 心 ， 使 我 不 在 忌 邪 中 把 他 们 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4484', '4', '25', '12', '因 此 ， 你 要 说 ： ‘ 我 将 我 平 安 的 约 赐 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4485', '4', '25', '13', '这 约 要 给 他 和 他 的 后 裔 ， 作 为 永 远 当 祭 司 职 任 的 约 ； 因 他 为 神 有 忌 邪 的 心 ， 为 以 色 列 人 赎 罪 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4486', '4', '25', '14', '那 与 米 甸 女 人 一 同 被 杀 的 以 色 列 人 ， 名 叫 心 利 ， 是 撒 路 的 儿 子 ， 是 西 缅 一 个 宗 族 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4487', '4', '25', '15', '那 被 杀 的 米 甸 女 人 ， 名 叫 哥 斯 比 ， 是 苏 珥 的 女 儿 ； 这 苏 珥 是 米 甸 一 个 宗 族 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4488', '4', '25', '16', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4489', '4', '25', '17', '“ 你 要 扰 害 米 甸 人 ， 击 杀 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4490', '4', '25', '18', '因 为 他 们 用 诡 计 扰 害 你 们 ， 在 毗 珥 的 事 上 和 他 们 的 姊 妹 、 米 甸 首 领 的 女 儿 哥 斯 比 的 事 上 ， 用 这 诡 计 诱 惑 了 你 们 ； 这 哥 斯 比 ， 当 瘟 疫 流 行 的 日 子 ， 因 毗 珥 的 事 被 杀 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4491', '4', '26', '1', '＜ 第 二 次 的 人 口 普 查 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4492', '4', '26', '2', '“ 你 们 要 将 以 色 列 全 会 众 ， 按 他 们 的 宗 族 ， 凡 以 色 列 中 从 二 十 岁 以 外 、 能 出 去 打 仗 的 ， 计 算 总 数 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4493', '4', '26', '3', '摩 西 和 祭 司 以 利 亚 撒 在 摩 押 平 原 与 耶 利 哥 相 对 的 约 旦 河 边 向 以 色 列 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4494', '4', '26', '4', '“ 将 你 们 中 间 从 二 十 岁 以 外 的 计 算 总 数 ” ； 是 照 耶 和 华 吩 咐 出 埃 及 地 的 摩 西 和 以 色 列 人 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4495', '4', '26', '5', '以 色 列 的 长 子 是 吕 便 。 吕 便 的 众 子 ： 属 哈 诺 的 ， 有 哈 诺 族 ； 属 法 路 的 ， 有 法 路 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4496', '4', '26', '6', '属 希 斯 伦 的 ， 有 希 斯 伦 族 ； 属 迦 米 的 ， 有 迦 米 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4497', '4', '26', '7', '这 就 是 吕 便 的 各 族 ； 其 中 被 数 的 ， 共 有 四 万 三 千 七 百 三 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4498', '4', '26', '8', '法 路 的 儿 子 是 以 利 押 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4499', '4', '26', '9', '以 利 押 的 众 子 是 尼 母 利 、 大 坍 、 亚 比 兰 。 这 大 坍 、 亚 比 兰 ， 就 是 从 会 中 选 召 的 ， 与 可 拉 一 党 同 向 耶 和 华 争 闹 的 时 候 也 向 摩 西 、 亚 伦 争 闹 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4500', '4', '26', '10', '地 便 开 口 吞 了 他 们 ， 和 可 拉 、 可 拉 的 党 类 一 同 死 亡 。 那 时 火 烧 灭 了 二 百 五 十 个 人 ； 他 们 就 作 了 警 戒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4501', '4', '26', '11', '然 而 可 拉 的 众 子 没 有 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4502', '4', '26', '12', '按 着 家 族 ， 西 缅 的 众 子 ： 属 尼 母 利 的 ， 有 尼 母 利 族 ； 属 雅 悯 的 ， 有 雅 悯 族 ； 属 雅 斤 的 ， 有 雅 斤 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4503', '4', '26', '13', '属 谢 拉 的 ， 有 谢 拉 族 ； 属 扫 罗 的 ， 有 扫 罗 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4504', '4', '26', '14', '这 就 是 西 缅 的 各 族 ， 共 有 二 万 二 千 二 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4505', '4', '26', '15', '按 着 家 族 ， 迦 得 的 众 子 ： 属 洗 分 的 ， 有 洗 分 族 ； 属 哈 基 的 ， 有 哈 基 族 ； 属 书 尼 的 ， 有 书 尼 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4506', '4', '26', '16', '属 阿 斯 尼 的 ， 有 阿 斯 尼 族 ； 属 以 利 的 ， 有 以 利 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4507', '4', '26', '17', '属 亚 律 的 ， 有 亚 律 族 ； 属 亚 列 利 的 ， 有 亚 列 利 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4508', '4', '26', '18', '这 就 是 迦 得 子 孙 的 各 族 ， 照 他 们 中 间 被 数 的 ， 共 有 四 万 零 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4509', '4', '26', '19', '犹 大 的 儿 子 是 珥 和 俄 南 。 这 珥 和 俄 南 死 在 迦 南 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4510', '4', '26', '20', '按 着 家 族 ， 犹 大 其 余 的 众 子 ： 属 示 拉 的 ， 有 示 拉 族 ； 属 法 勒 斯 的 ， 有 法 勒 斯 族 ； 属 谢 拉 的 ， 有 谢 拉 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4511', '4', '26', '21', '法 勒 斯 的 儿 子 ： 属 希 斯 伦 的 ， 有 希 斯 伦 族 ； 属 哈 母 勒 的 ， 有 哈 母 勒 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4512', '4', '26', '22', '这 就 是 犹 大 的 各 族 ， 照 他 们 中 间 被 数 的 ， 共 有 七 万 六 千 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4513', '4', '26', '23', '按 着 家 族 ， 以 萨 迦 的 众 子 ： 属 陀 拉 的 ， 有 陀 拉 族 ； 属 普 瓦 的 ， 有 普 瓦 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4514', '4', '26', '24', '属 雅 述 的 ， 有 雅 述 族 ； 属 伸 仑 的 ， 有 伸 仑 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4515', '4', '26', '25', '这 就 是 以 萨 迦 的 各 族 ， 照 他 们 中 间 被 数 的 ， 共 有 六 万 四 千 三 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4516', '4', '26', '26', '按 着 家 族 ， 西 布 伦 的 众 子 ： 属 西 烈 的 ， 有 西 烈 族 ； 属 以 伦 的 ， 有 以 伦 族 ； 属 雅 利 的 ， 有 雅 利 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4517', '4', '26', '27', '这 就 是 西 布 伦 的 各 族 ， 照 他 们 中 间 被 数 的 ， 共 有 六 万 零 五 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4518', '4', '26', '28', '按 着 家 族 ， 约 瑟 的 儿 子 有 玛 拿 西 、 以 法 莲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4519', '4', '26', '29', '玛 拿 西 的 众 子 ： 属 玛 吉 的 ， 有 玛 吉 族 ； 玛 吉 生 基 列 ； 属 基 列 的 ， 有 基 列 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4520', '4', '26', '30', '基 列 的 众 子 ： 属 伊 以 谢 的 ， 有 伊 以 谢 族 ； 属 希 勒 的 ， 有 希 勒 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4521', '4', '26', '31', '属 亚 斯 烈 的 ， 有 亚 斯 烈 族 ； 属 示 剑 的 ， 有 示 剑 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4522', '4', '26', '32', '属 示 米 大 的 ， 有 示 米 大 族 ； 属 希 弗 的 ， 有 希 弗 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4523', '4', '26', '33', '希 弗 的 儿 子 ： 西 罗 非 哈 没 儿 子 ， 只 有 女 儿 。 西 罗 非 哈 女 儿 的 名 字 就 是 玛 拉 、 挪 阿 、 曷 拉 、 密 迦 、 得 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4524', '4', '26', '34', '这 就 是 玛 拿 西 的 各 族 ； 他 们 中 间 被 数 的 ， 共 有 五 万 二 千 七 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4525', '4', '26', '35', '按 着 家 族 ， 以 法 莲 的 众 子 ： 属 书 提 拉 的 ， 有 书 提 拉 族 ； 属 比 结 的 ， 有 比 结 族 ； 属 他 罕 的 ， 有 他 罕 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4526', '4', '26', '36', '书 提 拉 的 众 子 ： 属 以 兰 的 ， 有 以 兰 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4527', '4', '26', '37', '这 就 是 以 法 莲 子 孙 的 各 族 ， 照 他 们 中 间 被 数 的 ， 共 有 三 万 二 千 五 百 名 。 按 着 家 族 ， 这 都 是 约 瑟 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4528', '4', '26', '38', '按 着 家 族 ， 便 雅 悯 的 众 子 ： 属 比 拉 的 ， 有 比 拉 族 ； 属 亚 实 别 的 ， 有 亚 实 别 族 ； 属 亚 希 兰 的 ， 有 亚 希 兰 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4529', '4', '26', '39', '属 书 反 的 ， 有 书 反 族 ； 属 户 反 的 ， 有 户 反 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4530', '4', '26', '40', '比 拉 的 众 子 是 亚 勒 、 乃 幔 。 属 亚 勒 的 ， 有 亚 勒 族 ； 属 乃 幔 的 ， 有 乃 幔 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4531', '4', '26', '41', '按 着 家 族 ， 这 就 是 便 雅 悯 的 子 孙 ， 其 中 被 数 的 ， 共 有 四 万 五 千 六 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4532', '4', '26', '42', '按 着 家 族 ， 但 的 众 子 ： 属 书 含 的 ， 有 书 含 族 。 按 着 家 族 ， 这 就 是 但 的 各 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4533', '4', '26', '43', '照 其 中 被 数 的 ， 书 含 所 有 的 各 族 ， 共 有 六 万 四 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4534', '4', '26', '44', '按 着 家 族 ， 亚 设 的 众 子 ： 属 音 拿 的 ， 有 音 拿 族 ； 属 亦 施 韦 的 ， 有 亦 施 韦 族 ； 属 比 利 亚 的 ， 有 比 利 亚 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4535', '4', '26', '45', '比 利 亚 的 众 子 ： 属 希 别 的 ， 有 希 别 族 ； 属 玛 结 的 ， 有 玛 结 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4536', '4', '26', '46', '亚 设 的 女 儿 名 叫 西 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4537', '4', '26', '47', '这 就 是 亚 设 子 孙 的 各 族 ， 照 他 们 中 间 被 数 的 ， 共 有 五 万 三 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4538', '4', '26', '48', '按 着 家 族 ， 拿 弗 他 利 的 众 子 ： 属 雅 薛 的 ， 有 雅 薛 族 ； 属 沽 尼 的 ， 有 沽 尼 族 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4539', '4', '26', '49', '属 耶 色 的 ， 有 耶 色 族 ； 属 示 冷 的 ， 有 示 冷 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4540', '4', '26', '50', '按 着 家 族 ， 这 就 是 拿 弗 他 利 的 各 族 ； 他 们 中 间 被 数 的 ， 共 有 四 万 五 千 四 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4541', '4', '26', '51', '以 色 列 人 中 被 数 的 ， 共 有 六 十 万 零 一 千 七 百 三 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4542', '4', '26', '52', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4543', '4', '26', '53', '“ 你 要 按 着 人 名 的 数 目 将 地 分 给 这 些 人 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4544', '4', '26', '54', '人 多 的 ， 你 要 把 产 业 多 分 给 他 们 ； 人 少 的 ， 你 要 把 产 业 少 分 给 他 们 ； 要 照 被 数 的 人 数 ， 把 产 业 分 给 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4545', '4', '26', '55', '虽 是 这 样 ， 还 要 拈 阄 分 地 。 他 们 要 按 着 祖 宗 各 支 派 的 名 字 承 受 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4546', '4', '26', '56', '要 按 着 所 拈 的 阄 ， 看 人 数 多 ， 人 数 少 ， 把 产 业 分 给 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4547', '4', '26', '57', '利 未 人 ， 按 着 他 们 的 各 族 被 数 的 ： 属 革 顺 的 ， 有 革 顺 族 ； 属 哥 辖 的 ， 有 哥 辖 族 ； 属 米 拉 利 的 ， 有 米 拉 利 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4548', '4', '26', '58', '利 未 的 各 族 有 立 尼 族 、 希 伯 伦 族 、 玛 利 族 、 母 示 族 、 可 拉 族 。 哥 辖 生 暗 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4549', '4', '26', '59', '暗 兰 的 妻 名 叫 约 基 别 ， 是 利 未 女 子 ， 生 在 埃 及 。 她 给 暗 兰 生 了 亚 伦 、 摩 西 ， 并 他 们 的 姊 姊 米 利 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4550', '4', '26', '60', '亚 伦 生 拿 答 、 亚 比 户 、 以 利 亚 撒 、 以 他 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4551', '4', '26', '61', '拿 答 、 亚 比 户 在 耶 和 华 面 前 献 凡 火 的 时 候 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4552', '4', '26', '62', '利 未 人 中 ， 凡 一 个 月 以 外 、 被 数 的 男 丁 ， 共 有 二 万 三 千 。 他 们 本 来 没 有 数 在 以 色 列 人 中 ； 因 为 在 以 色 列 人 中 ， 没 有 分 给 他 们 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4553', '4', '26', '63', '这 些 就 是 被 摩 西 和 祭 司 以 利 亚 撒 所 数 的 ； 他 们 在 摩 押 平 原 与 耶 利 哥 相 对 的 约 旦 河 边 数 点 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4554', '4', '26', '64', '但 被 数 的 人 中 ， 没 有 一 个 是 摩 西 和 祭 司 亚 伦 从 前 在 西 奈 的 旷 野 所 数 的 以 色 列 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4555', '4', '26', '65', '因 为 耶 和 华 论 到 他 们 说 ： “ 他 们 必 要 死 在 旷 野 。 ” 所 以 ， 除 了 耶 孚 尼 的 儿 子 迦 勒 和 嫩 的 儿 子 约 书 亚 以 外 ， 连 一 个 人 也 没 有 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4556', '4', '27', '1', '＜ 西 罗 非 哈 的 女 儿 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4557', '4', '27', '2', '站 在 会 幕 门 口 ， 在 摩 西 和 祭 司 以 利 亚 撒 ， 并 众 首 领 与 全 会 众 面 前 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4558', '4', '27', '3', '“ 我 们 的 父 亲 死 在 旷 野 。 他 不 与 可 拉 同 党 聚 集 攻 击 耶 和 华 ， 是 在 自 己 罪 中 死 的 ； 他 也 没 有 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4559', '4', '27', '4', '为 什 么 因 我 们 的 父 亲 没 有 儿 子 就 把 他 的 名 从 他 族 中 除 掉 呢 ？ 求 你 们 在 我 们 父 亲 的 弟 兄 中 分 给 我 们 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4560', '4', '27', '5', '于 是 ， 摩 西 将 她 们 的 案 件 呈 到 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4561', '4', '27', '6', '耶 和 华 晓 谕 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4562', '4', '27', '7', '“ 西 罗 非 哈 的 女 儿 说 得 有 理 。 你 定 要 在 她 们 父 亲 的 弟 兄 中 ， 把 地 分 给 她 们 为 业 ； 要 将 她 们 父 亲 的 产 业 归 给 她 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4563', '4', '27', '8', '你 也 要 晓 谕 以 色 列 人 说 ： ‘ 人 若 死 了 没 有 儿 子 ， 就 要 把 他 的 产 业 归 给 他 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4564', '4', '27', '9', '他 若 没 有 女 儿 ， 就 要 把 他 的 产 业 给 他 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4565', '4', '27', '10', '他 若 没 有 弟 兄 ， 就 要 把 他 的 产 业 给 他 父 亲 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4566', '4', '27', '11', '他 父 亲 若 没 有 弟 兄 ， 就 要 把 他 的 产 业 给 他 族 中 最 近 的 亲 属 ， 他 便 要 得 为 业 。 ’ 这 要 作 以 色 列 人 的 律 例 典 章 ， 是 照 耶 和 华 吩 咐 摩 西 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4567', '4', '27', '12', '＜ 约 书 亚 被 选 为 摩 西 的 继 承 人 （ 申   3 1 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4568', '4', '27', '13', '看 了 以 后 ， 你 也 必 归 到 你 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 ， 像 你 哥 哥 亚 伦 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4569', '4', '27', '14', '因 为 你 们 在 寻 的 旷 野 ， 当 会 众 争 闹 的 时 候 ， 违 背 了 我 的 命 ， 没 有 在 涌 水 之 地 、 会 众 眼 前 尊 我 为 圣 。 ” （ 这 水 就 是 寻 的 旷 野 加 低 斯 米 利 巴 水 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4570', '4', '27', '15', '摩 西 对 耶 和 华 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4571', '4', '27', '16', '“ 愿 耶 和 华 万 人 之 灵 的 神 ， 立 一 个 人 治 理 会 众 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4572', '4', '27', '17', '可 以 在 他 们 面 前 出 入 ， 也 可 以 引 导 他 们 ， 免 得 耶 和 华 的 会 众 如 同 没 有 牧 人 的 羊 群 一 般 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4573', '4', '27', '18', '耶 和 华 对 摩 西 说 ： “ 嫩 的 儿 子 约 书 亚 是 心 中 有 圣 灵 的 ； 你 将 他 领 来 ， 按 手 在 他 头 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4574', '4', '27', '19', '使 他 站 在 祭 司 以 利 亚 撒 和 全 会 众 面 前 ， 嘱 咐 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4575', '4', '27', '20', '又 将 你 的 尊 荣 给 他 几 分 ， 使 以 色 列 全 会 众 都 听 从 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4576', '4', '27', '21', '他 要 站 在 祭 司 以 利 亚 撒 面 前 ； 以 利 亚 撒 要 凭 乌 陵 的 判 断 ， 在 耶 和 华 面 前 为 他 求 问 。 他 和 以 色 列 全 会 众 都 要 遵 以 利 亚 撒 的 命 出 入 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4577', '4', '27', '22', '于 是 摩 西 照 耶 和 华 所 吩 咐 的 将 约 书 亚 领 来 ， 使 他 站 在 祭 司 以 利 亚 撒 和 全 会 众 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4578', '4', '27', '23', '按 手 在 他 头 上 ， 嘱 咐 他 ， 是 照 耶 和 华 藉 摩 西 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4579', '4', '28', '1', '＜ 每 天 例 常 的 祭 （ 出   2 9 : 3 8 - 4 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4580', '4', '28', '2', '“ 你 要 吩 咐 以 色 列 人 说 ： ‘ 献 给 我 的 供 物 ， 就 是 献 给 我 作 馨 香 火 祭 的 食 物 ， 你 们 要 按 日 期 献 给 我 ’ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4581', '4', '28', '3', '又 要 对 他 们 说 ： 你 们 要 献 给 耶 和 华 的 火 祭 ， 就 是 没 有 残 疾 、 一 岁 的 公 羊 羔 ， 每 日 两 只 ， 作 为 常 献 的 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4582', '4', '28', '4', '早 晨 要 献 一 只 ， 黄 昏 的 时 候 要 献 一 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4583', '4', '28', '5', '又 用 细 面 伊 法 十 分 之 一 ， 并 捣 成 的 油 一 欣 四 分 之 一 ， 调 和 作 为 素 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4584', '4', '28', '6', '这 是 西 奈 山 所 命 定 为 常 献 的 燔 祭 ， 是 献 给 耶 和 华 为 馨 香 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4585', '4', '28', '7', '为 这 一 只 羊 羔 ， 要 同 献 奠 祭 的 酒 一 欣 四 分 之 一 。 在 圣 所 中 ， 你 要 将 醇 酒 奉 给 耶 和 华 为 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4586', '4', '28', '8', '晚 上 ， 你 要 献 那 一 只 羊 羔 ， 必 照 早 晨 的 素 祭 和 同 献 的 奠 祭 献 上 ， 作 为 馨 香 的 火 祭 ， 献 给 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4587', '4', '28', '9', '＜ 安 息 日 献 的 祭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4588', '4', '28', '10', '这 是 每 安 息 日 献 的 燔 祭 ； 那 常 献 的 燔 祭 和 同 献 的 奠 祭 在 外 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4589', '4', '28', '11', '＜ 月 初 献 的 祭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4590', '4', '28', '12', '每 只 公 牛 要 用 调 油 的 细 面 伊 法 十 分 之 三 作 为 素 祭 ； 那 只 公 羊 也 用 调 油 的 细 面 伊 法 十 分 之 二 作 为 素 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4591', '4', '28', '13', '每 只 羊 羔 要 用 调 油 的 细 面 伊 法 十 分 之 一 作 为 素 祭 和 馨 香 的 燔 祭 ， 是 献 给 耶 和 华 的 火 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4592', '4', '28', '14', '一 只 公 牛 要 奠 酒 半 欣 ， 一 只 公 羊 要 奠 酒 一 欣 三 分 之 一 ， 一 只 羊 羔 也 奠 酒 一 欣 四 分 之 一 。 这 是 每 月 的 燔 祭 ， 一 年 之 中 要 月 月 如 此 。');
