INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4640', '4', '29', '31', '又 要 献 一 只 公 山 羊 为 赎 罪 祭 。 这 是 在 常 献 的 燔 祭 和 同 献 的 素 祭 并 同 献 的 奠 祭 以 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4641', '4', '29', '32', '“ 第 七 日 要 献 公 牛 七 只 ， 公 羊 两 只 ， 没 有 残 疾 、 一 岁 的 公 羊 羔 十 四 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4642', '4', '29', '33', '并 为 公 牛 、 公 羊 ， 和 羊 羔 ， 按 数 照 例 ， 献 同 献 的 素 祭 和 同 献 的 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4643', '4', '29', '34', '又 要 献 一 只 公 山 羊 为 赎 罪 祭 。 这 是 在 常 献 的 燔 祭 和 同 献 的 素 祭 并 同 献 的 奠 祭 以 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4644', '4', '29', '35', '“ 第 八 日 你 们 当 有 严 肃 会 ； 什 么 劳 碌 的 工 都 不 可 做 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4645', '4', '29', '36', '只 要 将 公 牛 一 只 ， 公 羊 一 只 ， 没 有 残 疾 、 一 岁 的 公 羊 羔 七 只 作 火 祭 ， 献 给 耶 和 华 为 馨 香 的 燔 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4646', '4', '29', '37', '并 为 公 牛 、 公 羊 ， 和 羊 羔 ， 按 数 照 例 ， 献 同 献 的 素 祭 和 同 献 的 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4647', '4', '29', '38', '又 要 献 一 只 公 山 羊 为 赎 罪 祭 。 这 是 在 常 献 的 燔 祭 和 同 献 的 素 祭 并 同 献 的 奠 祭 以 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4648', '4', '29', '39', '“ 这 些 祭 要 在 你 们 的 节 期 献 给 耶 和 华 ， 都 在 所 许 的 愿 并 甘 心 所 献 的 以 外 ， 作 为 你 们 的 燔 祭 、 素 祭 、 奠 祭 ， 和 平 安 祭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4649', '4', '29', '40', '于 是 ， 摩 西 照 耶 和 华 所 吩 咐 他 的 一 切 话 告 诉 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4650', '4', '30', '1', '＜ 许 愿 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4651', '4', '30', '2', '人 若 向 耶 和 华 许 愿 或 起 誓 ， 要 约 束 自 己 ， 就 不 可 食 言 ， 必 要 按 口 中 所 出 的 一 切 话 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4652', '4', '30', '3', '女 子 年 幼 、 还 在 父 家 的 时 候 ， 若 向 耶 和 华 许 愿 ， 要 约 束 自 己 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4653', '4', '30', '4', '她 父 亲 也 听 见 她 所 许 的 愿 并 约 束 自 己 的 话 ， 却 向 她 默 默 不 言 ， 她 所 许 的 愿 并 约 束 自 己 的 话 就 都 要 为 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4654', '4', '30', '5', '但 她 父 亲 听 见 的 日 子 若 不 应 承 她 所 许 的 愿 和 约 束 自 己 的 话 ， 就 都 不 得 为 定 ； 耶 和 华 也 必 赦 免 她 ， 因 为 她 父 亲 不 应 承 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4655', '4', '30', '6', '她 若 出 了 嫁 ， 有 愿 在 身 ， 或 是 口 中 出 了 约 束 自 己 的 冒 失 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4656', '4', '30', '7', '她 丈 夫 听 见 的 日 子 ， 却 向 她 默 默 不 言 ， 她 所 许 的 愿 并 约 束 自 己 的 话 就 都 要 为 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4657', '4', '30', '8', '但 她 丈 夫 听 见 的 日 子 ， 若 不 应 承 ， 就 算 废 了 她 所 许 的 愿 和 她 出 口 约 束 自 己 的 冒 失 话 ； 耶 和 华 也 必 赦 免 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4658', '4', '30', '9', '寡 妇 或 是 被 休 的 妇 人 所 许 的 愿 ， 就 是 她 约 束 自 己 的 话 ， 都 要 为 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4659', '4', '30', '10', '她 若 在 丈 夫 家 里 许 了 愿 或 起 了 誓 ， 约 束 自 己 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4660', '4', '30', '11', '丈 夫 听 见 ， 却 向 她 默 默 不 言 ， 也 没 有 不 应 承 ， 她 所 许 的 愿 并 约 束 自 己 的 话 就 都 要 为 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4661', '4', '30', '12', '丈 夫 听 见 的 日 子 ， 若 把 这 两 样 全 废 了 ， 妇 人 口 中 所 许 的 愿 或 是 约 束 自 己 的 话 就 都 不 得 为 定 ， 因 她 丈 夫 已 经 把 这 两 样 废 了 ； 耶 和 华 也 必 赦 免 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4662', '4', '30', '13', '凡 她 所 许 的 愿 和 刻 苦 约 束 自 己 所 起 的 誓 ， 她 丈 夫 可 以 坚 定 ， 也 可 以 废 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4663', '4', '30', '14', '倘 若 她 丈 夫 天 天 向 她 默 默 不 言 ， 就 算 是 坚 定 她 所 许 的 愿 和 约 束 自 己 的 话 ； 因 丈 夫 听 见 的 日 子 向 她 默 默 不 言 ， 就 使 这 两 样 坚 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4664', '4', '30', '15', '但 她 丈 夫 听 见 以 后 ， 若 使 这 两 样 全 废 了 ， 就 要 担 当 妇 人 的 罪 孽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4665', '4', '30', '16', '这 是 丈 夫 待 妻 子 ， 父 亲 待 女 儿 ， 女 儿 年 幼 、 还 在 父 家 ， 耶 和 华 所 吩 咐 摩 西 的 律 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4666', '4', '31', '1', '＜ 跟 米 甸 人 打 仗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4667', '4', '31', '2', '“ 你 要 在 米 甸 人 身 上 报 以 色 列 人 的 仇 ， 后 来 要 归 到 你 列 祖 ｛ 原 文 是 本 民 ｝ 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4668', '4', '31', '3', '摩 西 吩 咐 百 姓 说 ： “ 要 从 你 们 中 间 叫 人 带 兵 器 出 去 攻 击 米 甸 ， 好 在 米 甸 人 身 上 为 耶 和 华 报 仇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4669', '4', '31', '4', '从 以 色 列 众 支 派 中 ， 每 支 派 要 打 发 一 千 人 去 打 仗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4670', '4', '31', '5', '于 是 从 以 色 列 千 万 人 中 ， 每 支 派 交 出 一 千 人 ， 共 一 万 二 千 人 ， 带 着 兵 器 预 备 打 仗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4671', '4', '31', '6', '摩 西 就 打 发 每 支 派 的 一 千 人 去 打 仗 ， 并 打 发 祭 司 以 利 亚 撒 的 儿 子 非 尼 哈 同 去 ； 非 尼 哈 手 里 拿 着 圣 所 的 器 皿 和 吹 大 声 的 号 筒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4672', '4', '31', '7', '他 们 就 照 耶 和 华 所 吩 咐 摩 西 的 ， 与 米 甸 人 打 仗 ， 杀 了 所 有 的 男 丁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4673', '4', '31', '8', '在 所 杀 的 人 中 ， 杀 了 米 甸 的 五 王 ， 就 是 以 未 、 利 金 、 苏 珥 、 户 珥 、 利 巴 ， 又 用 刀 杀 了 比 珥 的 儿 子 巴 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4674', '4', '31', '9', '以 色 列 人 掳 了 米 甸 人 的 妇 女 孩 子 ， 并 将 他 们 的 牲 畜 、 羊 群 ， 和 所 有 的 财 物 都 夺 了 来 ， 当 作 掳 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4675', '4', '31', '10', '又 用 火 焚 烧 他 们 所 住 的 城 邑 和 所 有 的 营 寨 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4676', '4', '31', '11', '把 一 切 所 夺 的 、 所 掳 的 ， 连 人 带 牲 畜 都 带 了 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4677', '4', '31', '12', '将 所 掳 的 人 ， 所 夺 的 牲 畜 、 财 物 ， 都 带 到 摩 押 平 原 ， 在 约 旦 河 边 与 耶 利 哥 相 对 的 营 盘 ， 交 给 摩 西 和 祭 司 以 利 亚 撒 ， 并 以 色 列 的 会 众 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4678', '4', '31', '13', '＜ 军 队 回 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4679', '4', '31', '14', '摩 西 向 打 仗 回 来 的 军 长 ， 就 是 千 夫 长 、 百 夫 长 ， 发 怒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4680', '4', '31', '15', '对 他 们 说 ： “ 你 们 要 存 留 这 一 切 妇 女 的 活 命 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4681', '4', '31', '16', '这 些 妇 女 因 巴 兰 的 计 谋 ， 叫 以 色 列 人 在 毗 珥 的 事 上 得 罪 耶 和 华 ， 以 致 耶 和 华 的 会 众 遭 遇 瘟 疫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4682', '4', '31', '17', '所 以 ， 你 们 要 把 一 切 的 男 孩 和 所 有 已 嫁 的 女 子 都 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4683', '4', '31', '18', '但 女 孩 子 中 ， 凡 没 有 出 嫁 的 ， 你 们 都 可 以 存 留 她 的 活 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4684', '4', '31', '19', '你 们 要 在 营 外 驻 扎 七 日 ； 凡 杀 了 人 的 ， 和 一 切 摸 了 被 杀 的 ， 并 你 们 所 掳 来 的 人 口 ， 第 三 日 ， 第 七 日 ， 都 要 洁 净 自 己 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4685', '4', '31', '20', '也 要 因 一 切 的 衣 服 、 皮 物 、 山 羊 毛 织 的 物 ， 和 各 样 的 木 器 ， 洁 净 自 己 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4686', '4', '31', '21', '祭 司 以 利 亚 撒 对 打 仗 回 来 的 兵 丁 说 ： “ 耶 和 华 所 吩 咐 摩 西 律 法 中 的 条 例 乃 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4687', '4', '31', '22', '金 、 银 、 铜 、 铁 、 锡 、 铅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4688', '4', '31', '23', '凡 能 见 火 的 ， 你 们 要 叫 它 经 火 就 为 洁 净 ， 然 而 还 要 用 除 污 秽 的 水 洁 净 它 ； 凡 不 能 见 火 的 ， 你 们 要 叫 它 过 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4689', '4', '31', '24', '第 七 日 ， 你 们 要 洗 衣 服 ， 就 为 洁 净 ， 然 后 可 以 进 营 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4690', '4', '31', '25', '＜ 分 战 利 品 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4691', '4', '31', '26', '“ 你 和 祭 司 以 利 亚 撒 ， 并 会 众 的 各 族 长 ， 要 计 算 所 掳 来 的 人 口 和 牲 畜 的 总 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4692', '4', '31', '27', '把 所 掳 来 的 分 作 两 半 ： 一 半 归 与 出 去 打 仗 的 精 兵 ， 一 半 归 与 全 会 众 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4693', '4', '31', '28', '又 要 从 出 去 打 仗 所 得 的 人 口 、 牛 、 驴 、 羊 群 中 ， 每 五 百 取 一 ， 作 为 贡 物 奉 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4694', '4', '31', '29', '从 他 们 一 半 之 中 ， 要 取 出 来 交 给 祭 司 以 利 亚 撒 ， 作 为 耶 和 华 的 举 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4695', '4', '31', '30', '从 以 色 列 人 的 一 半 之 中 ， 就 是 从 人 口 、 牛 、 驴 、 羊 群 、 各 样 牲 畜 中 ， 每 五 十 取 一 ， 交 给 看 守 耶 和 华 帐 幕 的 利 未 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4696', '4', '31', '31', '于 是 摩 西 和 祭 司 以 利 亚 撒 照 耶 和 华 所 吩 咐 摩 西 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4697', '4', '31', '32', '除 了 兵 丁 所 夺 的 财 物 以 外 ， 所 掳 来 的 ： 羊 六 十 七 万 五 千 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4698', '4', '31', '33', '牛 七 万 二 千 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4699', '4', '31', '34', '驴 六 万 一 千 匹 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4700', '4', '31', '35', '女 人 共 三 万 二 千 口 ， 都 是 没 有 出 嫁 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4701', '4', '31', '36', '出 去 打 仗 之 人 的 分 ， 就 是 他 们 所 得 的 那 一 半 ， 共 计 羊 三 十 三 万 七 千 五 百 只 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4702', '4', '31', '37', '从 其 中 归 耶 和 华 为 贡 物 的 ， 有 六 百 七 十 五 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4703', '4', '31', '38', '牛 三 万 六 千 只 ， 从 其 中 归 耶 和 华 为 贡 物 的 ， 有 七 十 二 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4704', '4', '31', '39', '驴 三 万 零 五 百 匹 ， 从 其 中 归 耶 和 华 为 贡 物 的 ， 有 六 十 一 匹 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4705', '4', '31', '40', '人 一 万 六 千 口 ， 从 其 中 归 耶 和 华 的 ， 有 三 十 二 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4706', '4', '31', '41', '摩 西 把 贡 物 ， 就 是 归 与 耶 和 华 的 举 祭 ， 交 给 祭 司 以 利 亚 撒 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4707', '4', '31', '42', '以 色 列 人 所 得 的 那 一 半 ， 就 是 摩 西 从 打 仗 的 人 取 来 分 给 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4708', '4', '31', '43', '（ 会 众 的 那 一 半 有 ： 羊 三 十 三 万 七 千 五 百 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4709', '4', '31', '44', '牛 三 万 六 千 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4710', '4', '31', '45', '驴 三 万 零 五 百 匹 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4711', '4', '31', '46', '人 一 万 六 千 口 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4712', '4', '31', '47', '无 论 是 人 口 是 牲 畜 ， 摩 西 每 五 十 取 一 ， 交 给 看 守 耶 和 华 帐 幕 的 利 未 人 ， 是 照 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4713', '4', '31', '48', '带 领 千 军 的 各 军 长 ， 就 是 千 夫 长 、 百 夫 长 ， 都 近 前 来 见 摩 西 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4714', '4', '31', '49', '对 他 说 ： “ 仆 人 权 下 的 兵 已 经 计 算 总 数 ， 并 不 短 少 一 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4715', '4', '31', '50', '如 今 我 们 将 各 人 所 得 的 金 器 ， 就 是 脚 链 子 、 镯 子 、 打 印 的 戒 指 、 耳 环 、 手 钏 ， 都 送 来 为 耶 和 华 的 供 物 ， 好 在 耶 和 华 面 前 为 我 们 的 生 命 赎 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4716', '4', '31', '51', '摩 西 和 祭 司 以 利 亚 撒 就 收 了 他 们 的 金 子 ， 都 是 打 成 的 器 皿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4717', '4', '31', '52', '千 夫 长 、 百 夫 长 所 献 给 耶 和 华 为 举 祭 的 金 子 共 有 一 万 六 千 七 百 五 十 舍 客 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4718', '4', '31', '53', '各 兵 丁 都 为 自 己 夺 了 财 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4719', '4', '31', '54', '摩 西 和 祭 司 以 利 亚 撒 收 了 千 夫 长 、 百 夫 长 的 金 子 ， 就 带 进 会 幕 ， 在 耶 和 华 面 前 作 为 以 色 列 人 的 纪 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4720', '4', '32', '1', '＜ 约 旦 河 东 的 两 支 派 （ 申   3 : 1 2 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4721', '4', '32', '2', '就 来 见 摩 西 和 祭 司 以 利 亚 撒 ， 并 会 众 的 首 领 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4722', '4', '32', '3', '“ 亚 大 录 、 底 本 、 雅 谢 、 宁 拉 、 希 实 本 、 以 利 亚 利 、 示 班 、 尼 波 、 比 稳 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4723', '4', '32', '4', '就 是 耶 和 华 在 以 色 列 会 众 前 面 所 攻 取 之 地 ， 是 可 牧 放 牲 畜 之 地 ， 你 仆 人 也 有 牲 畜 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4724', '4', '32', '5', '又 说 ： “ 我 们 若 在 你 眼 前 蒙 恩 ， 求 你 把 这 地 给 我 们 为 业 ， 不 要 领 我 们 过 约 旦 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4725', '4', '32', '6', '摩 西 对 迦 得 子 孙 和 吕 便 子 孙 说 ： “ 难 道 你 们 的 弟 兄 去 打 仗 ， 你 们 竟 坐 在 这 里 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4726', '4', '32', '7', '你 们 为 何 使 以 色 列 人 灰 心 丧 胆 、 不 过 去 进 入 耶 和 华 所 赐 给 他 们 的 那 地 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4727', '4', '32', '8', '我 先 前 从 加 低 斯 ． 巴 尼 亚 打 发 你 们 先 祖 去 窥 探 那 地 ， 他 们 也 是 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4728', '4', '32', '9', '他 们 上 以 实 各 谷 ， 去 窥 探 那 地 回 来 的 时 候 ， 使 以 色 列 人 灰 心 丧 胆 ， 不 进 入 耶 和 华 所 赐 给 他 们 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4729', '4', '32', '10', '当 日 ， 耶 和 华 的 怒 气 发 作 ， 就 起 誓 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4730', '4', '32', '11', '‘ 凡 从 埃 及 上 来 、 二 十 岁 以 外 的 人 断 不 得 看 见 我 对 亚 伯 拉 罕 、 以 撒 、 雅 各 起 誓 应 许 之 地 ， 因 为 他 们 没 有 专 心 跟 从 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4731', '4', '32', '12', '惟 有 基 尼 洗 族 耶 孚 尼 的 儿 子 迦 勒 和 嫩 的 儿 子 约 书 亚 可 以 看 见 ， 因 为 他 们 专 心 跟 从 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4732', '4', '32', '13', '耶 和 华 的 怒 气 向 以 色 列 人 发 作 ， 使 他 们 在 旷 野 飘 流 四 十 年 ， 等 到 在 耶 和 华 眼 前 行 恶 的 那 一 代 人 都 消 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4733', '4', '32', '14', '谁 知 ， 你 们 起 来 接 续 先 祖 ， 增 添 罪 人 的 数 目 ， 使 耶 和 华 向 以 色 列 大 发 烈 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4734', '4', '32', '15', '你 们 若 退 后 不 跟 从 他 ， 他 还 要 把 以 色 列 人 撇 在 旷 野 ， 便 是 你 们 使 这 众 民 灭 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4735', '4', '32', '16', '两 支 派 的 人 挨 近 摩 西 ， 说 ： “ 我 们 要 在 这 里 为 牲 畜 垒 圈 ， 为 妇 人 孩 子 造 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4736', '4', '32', '17', '我 们 自 己 要 带 兵 器 行 在 以 色 列 人 的 前 头 ， 好 把 他 们 领 到 他 们 的 地 方 ； 但 我 们 的 妇 人 孩 子 ， 因 这 地 居 民 的 缘 故 ， 要 住 在 坚 固 的 城 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4737', '4', '32', '18', '我 们 不 回 家 ， 直 等 到 以 色 列 人 各 承 受 自 己 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4738', '4', '32', '19', '我 们 不 和 他 们 在 约 旦 河 那 边 一 带 之 地 同 受 产 业 ， 因 为 我 们 的 产 业 是 坐 落 在 约 旦 河 东 边 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4739', '4', '32', '20', '摩 西 对 他 们 说 ： “ 你 们 若 这 样 行 ， 在 耶 和 华 面 前 带 着 兵 器 出 去 打 仗 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4740', '4', '32', '21', '所 有 带 兵 器 的 人 都 要 在 耶 和 华 面 前 过 约 旦 河 ， 等 他 赶 出 他 的 仇 敌 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4741', '4', '32', '22', '那 地 被 耶 和 华 制 伏 了 ， 然 后 你 们 可 以 回 来 ， 向 耶 和 华 和 以 色 列 才 为 无 罪 ， 这 地 也 必 在 耶 和 华 面 前 归 你 们 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4742', '4', '32', '23', '倘 若 你 们 不 这 样 行 ， 就 得 罪 耶 和 华 ， 要 知 道 你 们 的 罪 必 追 上 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4743', '4', '32', '24', '如 今 你 们 口 中 所 出 的 ， 只 管 去 行 ， 为 你 们 的 妇 人 孩 子 造 城 ， 为 你 们 的 羊 群 垒 圈 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4744', '4', '32', '25', '迦 得 子 孙 和 吕 便 子 孙 对 摩 西 说 ： “ 仆 人 要 照 我 主 所 吩 咐 的 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4745', '4', '32', '26', '我 们 的 妻 子 、 孩 子 、 羊 群 ， 和 所 有 的 牲 畜 都 要 留 在 基 列 的 各 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4746', '4', '32', '27', '但 你 的 仆 人 ， 凡 带 兵 器 的 ， 都 要 照 我 主 所 说 的 话 ， 在 耶 和 华 面 前 过 去 打 仗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4747', '4', '32', '28', '于 是 ， 摩 西 为 他 们 嘱 咐 祭 司 以 利 亚 撒 和 嫩 的 儿 子 约 书 亚 ， 并 以 色 列 众 支 派 的 族 长 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4748', '4', '32', '29', '“ 迦 得 子 孙 和 吕 便 子 孙 ， 凡 带 兵 器 在 耶 和 华 面 前 去 打 仗 的 ， 若 与 你 们 一 同 过 约 旦 河 ， 那 地 被 你 们 制 伏 了 ， 你 们 就 要 把 基 列 地 给 他 们 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4749', '4', '32', '30', '倘 若 他 们 不 带 兵 器 和 你 们 一 同 过 去 ， 就 要 在 迦 南 地 你 们 中 间 得 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4750', '4', '32', '31', '迦 得 子 孙 和 吕 便 子 孙 回 答 说 ： “ 耶 和 华 怎 样 吩 咐 仆 人 ， 仆 人 就 怎 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4751', '4', '32', '32', '我 们 要 带 兵 器 ， 在 耶 和 华 面 前 过 去 ， 进 入 迦 南 地 ， 只 是 约 旦 河 这 边 、 我 们 所 得 为 业 之 地 仍 归 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4752', '4', '32', '33', '摩 西 将 亚 摩 利 王 西 宏 的 国 和 巴 珊 王 噩 的 国 ， 连 那 地 和 周 围 的 城 邑 ， 都 给 了 迦 得 子 孙 和 吕 便 子 孙 ， 并 约 瑟 的 儿 子 玛 拿 西 半 个 支 派 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4753', '4', '32', '34', '迦 得 子 孙 建 造 底 本 、 亚 他 录 、 亚 罗 珥 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4754', '4', '32', '35', '亚 他 录 ． 朔 反 、 雅 谢 、 约 比 哈 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4755', '4', '32', '36', '伯 ． 宁 拉 、 伯 ． 哈 兰 ， 都 是 坚 固 城 。 他 们 又 垒 羊 圈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4756', '4', '32', '37', '吕 便 子 孙 建 造 希 实 本 、 以 利 亚 利 、 基 列 亭 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4757', '4', '32', '38', '尼 波 、 巴 力 ． 免 、 西 比 玛 （ 尼 波 、 巴 力 ． 免 ， 名 字 是 改 了 的 ） ， 又 给 他 们 所 建 造 的 城 另 起 别 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4758', '4', '32', '39', '玛 拿 西 的 儿 子 玛 吉 ， 他 的 子 孙 往 基 列 去 ， 占 了 那 地 ， 赶 出 那 里 的 亚 摩 利 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4759', '4', '32', '40', '摩 西 将 基 列 赐 给 玛 拿 西 的 儿 子 玛 吉 ， 他 子 孙 就 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4760', '4', '32', '41', '玛 拿 西 的 子 孙 睚 珥 去 占 了 基 列 的 村 庄 ， 就 称 这 些 村 庄 为 哈 倭 特 ． 睚 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4761', '4', '32', '42', '挪 巴 去 占 了 基 纳 和 基 纳 的 乡 村 ， 就 按 自 己 的 名 称 基 纳 为 挪 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4762', '4', '33', '1', '＜ 从 埃 及 到 摩 押 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4763', '4', '33', '2', '摩 西 遵 着 耶 和 华 的 吩 咐 记 载 他 们 所 行 的 路 程 ， 其 路 程 乃 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4764', '4', '33', '3', '正 月 十 五 日 ， 就 是 逾 越 节 的 次 日 ， 以 色 列 人 从 兰 塞 起 行 ， 在 一 切 埃 及 人 眼 前 昂 然 无 惧 地 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4765', '4', '33', '4', '那 时 ， 埃 及 人 正 葬 埋 他 们 的 长 子 ， 就 是 耶 和 华 在 他 们 中 间 所 击 杀 的 ； 耶 和 华 也 败 坏 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4766', '4', '33', '5', '以 色 列 人 从 兰 塞 起 行 ， 安 营 在 疏 割 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4767', '4', '33', '6', '从 疏 割 起 行 ， 安 营 在 旷 野 边 的 以 倘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4768', '4', '33', '7', '从 以 倘 起 行 ， 转 到 比 ． 哈 希 录 ， 是 在 巴 力 ． 洗 分 对 面 ， 就 在 密 夺 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4769', '4', '33', '8', '从 比 ． 哈 希 录 对 面 起 行 ， 经 过 海 中 到 了 书 珥 旷 野 ， 又 在 伊 坦 的 旷 野 走 了 三 天 的 路 程 ， 就 安 营 在 玛 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4770', '4', '33', '9', '从 玛 拉 起 行 ， 来 到 以 琳 （ 以 琳 有 十 二 股 水 泉 ， 七 十 棵 棕 树 ） ， 就 在 那 里 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4771', '4', '33', '10', '从 以 琳 起 行 ， 安 营 在 红 海 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4772', '4', '33', '11', '从 红 海 边 起 行 ， 安 营 在 汛 的 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4773', '4', '33', '12', '从 汛 的 旷 野 起 行 ， 安 营 在 脱 加 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4774', '4', '33', '13', '从 脱 加 起 行 ， 安 营 在 亚 录 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4775', '4', '33', '14', '从 亚 录 起 行 ， 安 营 在 利 非 订 ； 在 那 里 ， 百 姓 没 有 水 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4776', '4', '33', '15', '从 利 非 订 起 行 ， 安 营 在 西 奈 的 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4777', '4', '33', '16', '从 西 奈 的 旷 野 起 行 ， 安 营 在 基 博 罗 ． 哈 他 瓦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4778', '4', '33', '17', '从 基 博 罗 ． 哈 他 瓦 起 行 ， 安 营 在 哈 洗 录 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4779', '4', '33', '18', '从 哈 洗 录 起 行 ， 安 营 在 利 提 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4780', '4', '33', '19', '从 利 提 玛 起 行 ， 安 营 在 临 门 帕 烈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4781', '4', '33', '20', '从 临 门 帕 烈 起 行 ， 安 营 在 立 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4782', '4', '33', '21', '从 立 拿 起 行 ， 安 营 在 勒 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4783', '4', '33', '22', '从 勒 撒 起 行 ， 安 营 在 基 希 拉 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4784', '4', '33', '23', '从 基 希 拉 他 起 行 ， 安 营 在 沙 斐 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4785', '4', '33', '24', '从 沙 斐 山 起 行 ， 安 营 在 哈 拉 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4786', '4', '33', '25', '从 哈 拉 大 起 行 ， 安 营 在 玛 吉 希 录 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4787', '4', '33', '26', '从 玛 吉 希 录 起 行 ， 安 营 在 他 哈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4788', '4', '33', '27', '从 他 哈 起 行 ， 安 营 在 他 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4789', '4', '33', '28', '从 他 拉 起 行 ， 安 营 在 密 加 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4790', '4', '33', '29', '从 密 加 起 行 ， 安 营 在 哈 摩 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4791', '4', '33', '30', '从 哈 摩 拿 起 行 ， 安 营 在 摩 西 录 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4792', '4', '33', '31', '从 摩 西 录 起 行 ， 安 营 在 比 尼 ． 亚 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4793', '4', '33', '32', '从 比 尼 ． 亚 干 起 行 ， 安 营 在 曷 ． 哈 及 甲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4794', '4', '33', '33', '从 曷 ． 哈 及 甲 起 行 ， 安 营 在 约 巴 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4795', '4', '33', '34', '从 约 巴 他 起 行 ， 安 营 在 阿 博 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4796', '4', '33', '35', '从 阿 博 拿 起 行 ， 安 营 在 以 旬 ． 迦 别 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4797', '4', '33', '36', '从 以 旬 ． 迦 别 起 行 ， 安 营 在 寻 的 旷 野 ， 就 是 加 低 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4798', '4', '33', '37', '从 加 低 斯 起 行 ， 安 营 在 何 珥 山 ， 以 东 地 的 边 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4799', '4', '33', '38', '以 色 列 人 出 了 埃 及 地 后 四 十 年 ， 五 月 初 一 日 ， 祭 司 亚 伦 遵 着 耶 和 华 的 吩 咐 上 何 珥 山 ， 就 死 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4800', '4', '33', '39', '亚 伦 死 在 何 珥 山 的 时 候 年 一 百 二 十 三 岁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4801', '4', '33', '40', '住 在 迦 南 南 地 的 迦 南 人 亚 拉 得 王 听 说 以 色 列 人 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4802', '4', '33', '41', '以 色 列 人 从 何 珥 山 起 行 ， 安 营 在 撒 摩 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4803', '4', '33', '42', '从 撒 摩 拿 起 行 ， 安 营 在 普 嫩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4804', '4', '33', '43', '从 普 嫩 起 行 ， 安 营 在 阿 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4805', '4', '33', '44', '从 阿 伯 起 行 ， 安 营 在 以 耶 ． 亚 巴 琳 ， 摩 押 的 边 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4806', '4', '33', '45', '从 以 耶 ． 亚 巴 琳 起 行 ， 安 营 在 底 本 ． 迦 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4807', '4', '33', '46', '从 底 本 ． 迦 得 起 行 ， 安 营 在 亚 门 ． 低 比 拉 太 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4808', '4', '33', '47', '从 亚 门 ． 低 比 拉 太 音 起 行 ， 安 营 在 尼 波 对 面 的 亚 巴 琳 山 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4809', '4', '33', '48', '从 亚 巴 琳 山 起 行 ， 安 营 在 摩 押 平 原 ─ ─ 约 旦 河 边 、 耶 利 哥 对 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4810', '4', '33', '49', '他 们 在 摩 押 平 原 沿 约 旦 河 边 安 营 ， 从 伯 ． 耶 施 末 直 到 亚 伯 ． 什 亭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4811', '4', '33', '50', '＜ 过 约 旦 河 前 的 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4812', '4', '33', '51', '你 吩 咐 以 色 列 人 说 ： 你 们 过 约 旦 河 进 迦 南 地 的 时 候 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4813', '4', '33', '52', '就 要 从 你 们 面 前 赶 出 那 里 所 有 的 居 民 ， 毁 灭 他 们 一 切 錾 成 的 石 像 和 他 们 一 切 铸 成 的 偶 像 ， 又 拆 毁 他 们 一 切 的 邱 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4814', '4', '33', '53', '你 们 要 夺 那 地 ， 住 在 其 中 ， 因 我 把 那 地 赐 给 你 们 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4815', '4', '33', '54', '你 们 要 按 家 室 拈 阄 ， 承 受 那 地 ； 人 多 的 ， 要 把 产 业 多 分 给 他 们 ； 人 少 的 ， 要 把 产 业 少 分 给 他 们 。 拈 出 何 地 给 何 人 ， 就 要 归 何 人 。 你 们 要 按 宗 族 的 支 派 承 受 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4816', '4', '33', '55', '倘 若 你 们 不 赶 出 那 地 的 居 民 ， 所 容 留 的 居 民 就 必 作 你 们 眼 中 的 刺 ， 肋 下 的 荆 棘 ， 也 必 在 你 们 所 住 的 地 上 扰 害 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4817', '4', '33', '56', '而 且 我 素 常 有 意 怎 样 待 他 们 ， 也 必 照 样 待 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4818', '4', '34', '1', '＜ 迦 南 地 的 境 界 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4819', '4', '34', '2', '“ 你 吩 咐 以 色 列 人 说 ： 你 们 到 了 迦 南 地 ， 就 是 归 你 们 为 业 的 迦 南 四 境 之 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4820', '4', '34', '3', '南 角 要 从 寻 的 旷 野 ， 贴 着 以 东 的 边 界 ； 南 界 要 从 盐 海 东 头 起 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4821', '4', '34', '4', '绕 到 亚 克 拉 滨 坡 的 南 边 ， 接 连 到 寻 ， 直 通 到 加 低 斯 ． 巴 尼 亚 的 南 边 ， 又 通 到 哈 萨 ． 亚 达 ， 接 连 到 押 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4822', '4', '34', '5', '从 押 们 转 到 埃 及 小 河 ， 直 通 到 海 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4823', '4', '34', '6', '“ 西 边 要 以 大 海 为 界 ； 这 就 是 你 们 的 西 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4824', '4', '34', '7', '“ 北 界 要 从 大 海 起 ， 划 到 何 珥 山 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4825', '4', '34', '8', '从 何 珥 山 划 到 哈 马 口 ， 通 到 西 达 达 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4826', '4', '34', '9', '又 通 到 西 斐 仑 ， 直 到 哈 萨 ． 以 难 。 这 要 作 你 们 的 北 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4827', '4', '34', '10', '“ 你 们 要 从 哈 萨 ． 以 难 划 到 示 番 为 东 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4828', '4', '34', '11', '这 界 要 从 示 番 下 到 亚 延 东 边 的 利 比 拉 ， 又 要 达 到 基 尼 烈 湖 的 东 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4829', '4', '34', '12', '这 界 要 下 到 约 旦 河 ， 通 到 盐 海 为 止 。 这 四 围 的 边 界 以 内 ， 要 作 你 们 的 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4830', '4', '34', '13', '摩 西 吩 咐 以 色 列 人 说 ： “ 这 地 就 是 耶 和 华 吩 咐 拈 阄 给 九 个 半 支 派 承 受 为 业 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4831', '4', '34', '14', '因 为 吕 便 支 派 和 迦 得 支 派 按 着 宗 族 受 了 产 业 ， 玛 拿 西 半 个 支 派 也 受 了 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4832', '4', '34', '15', '这 两 个 半 支 派 已 经 在 耶 利 哥 对 面 、 约 旦 河 东 、 向 日 出 之 地 受 了 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4833', '4', '34', '16', '＜ 各 支 派 首 领 负 责 分 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4834', '4', '34', '17', '“ 要 给 你 们 分 地 为 业 之 人 的 名 字 是 祭 司 以 利 亚 撒 和 嫩 的 儿 子 约 书 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4835', '4', '34', '18', '又 要 从 每 支 派 中 选 一 个 首 领 帮 助 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4836', '4', '34', '19', '这 些 人 的 名 字 ： 犹 大 支 派 有 耶 孚 尼 的 儿 子 迦 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4837', '4', '34', '20', '西 缅 支 派 有 亚 米 忽 的 儿 子 示 母 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4838', '4', '34', '21', '便 雅 悯 支 派 有 基 斯 伦 的 儿 子 以 利 达 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4839', '4', '34', '22', '但 支 派 有 一 个 首 领 ， 约 利 的 儿 子 布 基 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4840', '4', '34', '23', '约 瑟 的 子 孙 玛 拿 西 支 派 有 一 个 首 领 ， 以 弗 的 儿 子 汉 聂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4841', '4', '34', '24', '以 法 莲 支 派 有 一 个 首 领 ， 拾 弗 但 的 儿 子 基 母 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4842', '4', '34', '25', '西 布 伦 支 派 有 一 个 首 领 ， 帕 纳 的 儿 子 以 利 撒 番 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4843', '4', '34', '26', '以 萨 迦 支 派 有 一 个 首 领 ， 阿 散 的 儿 子 帕 铁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4844', '4', '34', '27', '亚 设 支 派 有 一 个 首 领 ， 示 罗 米 的 儿 子 亚 希 忽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4845', '4', '34', '28', '拿 弗 他 利 支 派 有 一 个 首 领 ， 亚 米 忽 的 儿 子 比 大 黑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4846', '4', '34', '29', '这 些 人 就 是 耶 和 华 所 吩 咐 、 在 迦 南 地 把 产 业 分 给 以 色 列 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4847', '4', '35', '1', '＜ 分 给 利 未 人 的 城 邑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4848', '4', '35', '2', '“ 你 吩 咐 以 色 列 人 ， 要 从 所 得 为 业 的 地 中 把 些 城 给 利 未 人 居 住 ， 也 要 把 这 城 四 围 的 郊 野 给 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4849', '4', '35', '3', '这 城 邑 要 归 他 们 居 住 ， 城 邑 的 郊 野 可 以 牧 养 他 们 的 牛 羊 和 各 样 的 牲 畜 ， 又 可 以 安 置 他 们 的 财 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4850', '4', '35', '4', '你 们 给 利 未 人 的 郊 野 ， 要 从 城 根 起 ， 四 围 往 外 量 一 千 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4851', '4', '35', '5', '另 外 东 量 二 千 肘 ， 南 量 二 千 肘 ， 西 量 二 千 肘 ， 北 量 二 千 肘 ， 为 边 界 ， 城 在 当 中 ； 这 要 归 他 们 作 城 邑 的 郊 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4852', '4', '35', '6', '你 们 给 利 未 人 的 城 邑 ， 其 中 当 有 六 座 逃 城 ， 使 误 杀 人 的 可 以 逃 到 那 里 。 此 外 还 要 给 他 们 四 十 二 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4853', '4', '35', '7', '你 们 要 给 利 未 人 的 城 ， 共 有 四 十 八 座 ， 连 城 带 郊 野 都 要 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4854', '4', '35', '8', '以 色 列 人 所 得 的 地 业 从 中 要 把 些 城 邑 给 利 未 人 ； 人 多 的 就 多 给 ， 人 少 的 就 少 给 ； 各 支 派 要 按 所 承 受 为 业 之 地 把 城 邑 给 利 未 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4855', '4', '35', '9', '＜ 庇 护 城 （ 申   1 9 : 1 - 1 3 ； 书   2 0 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4856', '4', '35', '10', '“ 你 吩 咐 以 色 列 人 说 ： 你 们 过 约 旦 河 ， 进 了 迦 南 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4857', '4', '35', '11', '就 要 分 出 几 座 城 ， 为 你 们 作 逃 城 ， 使 误 杀 人 的 可 以 逃 到 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4858', '4', '35', '12', '这 些 城 可 以 作 逃 避 报 仇 人 的 城 ， 使 误 杀 人 的 不 至 于 死 ， 等 他 站 在 会 众 面 前 听 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4859', '4', '35', '13', '你 们 所 分 出 来 的 城 ， 要 作 六 座 逃 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4860', '4', '35', '14', '在 约 旦 河 东 要 分 出 三 座 城 ， 在 迦 南 地 也 要 分 出 三 座 城 ， 都 作 逃 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4861', '4', '35', '15', '这 六 座 城 要 给 以 色 列 人 和 他 们 中 间 的 外 人 ， 并 寄 居 的 ， 作 为 逃 城 ， 使 误 杀 人 的 都 可 以 逃 到 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4862', '4', '35', '16', '“ 倘 若 人 用 铁 器 打 人 ， 以 致 打 死 ， 他 就 是 故 杀 人 的 ； 故 杀 人 的 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4863', '4', '35', '17', '若 用 可 以 打 死 人 的 石 头 打 死 了 人 ， 他 就 是 故 杀 人 的 ； 故 杀 人 的 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4864', '4', '35', '18', '若 用 可 以 打 死 人 的 木 器 打 死 了 人 ， 他 就 是 故 杀 人 的 ； 故 杀 人 的 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4865', '4', '35', '19', '报 血 仇 的 必 亲 自 杀 那 故 杀 人 的 ， 一 遇 见 就 杀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4866', '4', '35', '20', '人 若 因 怨 恨 把 人 推 倒 ， 或 是 埋 伏 往 人 身 上 扔 物 ， 以 致 于 死 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4867', '4', '35', '21', '或 是 因 仇 恨 用 手 打 人 ， 以 致 于 死 ， 那 打 人 的 必 被 治 死 。 他 是 故 杀 人 的 ； 报 血 仇 的 一 遇 见 就 杀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4868', '4', '35', '22', '“ 倘 若 人 没 有 仇 恨 ， 忽 然 将 人 推 倒 ， 或 是 没 有 埋 伏 把 物 扔 在 人 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4869', '4', '35', '23', '或 是 没 有 看 见 的 时 候 用 可 以 打 死 人 的 石 头 扔 在 人 身 上 ， 以 致 于 死 ， 本 来 与 他 无 仇 ， 也 无 意 害 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4870', '4', '35', '24', '会 众 就 要 照 典 章 ， 在 打 死 人 的 和 报 血 仇 的 中 间 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4871', '4', '35', '25', '会 众 要 救 这 误 杀 人 的 脱 离 报 血 仇 人 的 手 ， 也 要 使 他 归 入 逃 城 。 他 要 住 在 其 中 ， 直 等 到 受 圣 膏 的 大 祭 司 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4872', '4', '35', '26', '但 误 杀 人 的 ， 无 论 什 么 时 候 ， 若 出 了 逃 城 的 境 外 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4873', '4', '35', '27', '报 血 仇 的 在 逃 城 境 外 遇 见 他 ， 将 他 杀 了 ， 报 血 仇 的 就 没 有 流 血 之 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4874', '4', '35', '28', '因 为 误 杀 人 的 该 住 在 逃 城 里 ， 等 到 大 祭 司 死 了 。 大 祭 司 死 了 以 后 ， 误 杀 人 的 才 可 以 回 到 他 所 得 为 业 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4875', '4', '35', '29', '这 在 你 们 一 切 的 住 处 ， 要 作 你 们 世 世 代 代 的 律 例 典 章 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4876', '4', '35', '30', '“ 无 论 谁 故 杀 人 ， 要 凭 几 个 见 证 人 的 口 把 那 故 杀 人 的 杀 了 ， 只 是 不 可 凭 一 个 见 证 的 口 叫 人 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4877', '4', '35', '31', '故 杀 人 、 犯 死 罪 的 ， 你 们 不 可 收 赎 价 代 替 他 的 命 ； 他 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4878', '4', '35', '32', '那 逃 到 逃 城 的 人 ， 你 们 不 可 为 他 收 赎 价 ， 使 他 在 大 祭 司 未 死 以 先 再 来 住 在 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4879', '4', '35', '33', '这 样 ， 你 们 就 不 污 秽 所 住 之 地 ， 因 为 血 是 污 秽 地 的 ； 若 有 在 地 上 流 人 血 的 ， 非 流 那 杀 人 者 的 血 ， 那 地 就 不 得 洁 净 ｛ 原 文 是 赎 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4880', '4', '35', '34', '你 们 不 可 玷 污 所 住 之 地 ， 就 是 我 住 在 其 中 之 地 ， 因 为 我 ─ ─ 耶 和 华 住 在 以 色 列 人 中 间 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4881', '4', '36', '1', '＜ 承 业 女 子 结 婚 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4882', '4', '36', '2', '“ 耶 和 华 曾 吩 咐 我 主 拈 阄 分 给 以 色 列 人 为 业 ， 我 主 也 受 了 耶 和 华 的 吩 咐 将 我 们 兄 弟 西 罗 非 哈 的 产 业 分 给 他 的 众 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4883', '4', '36', '3', '她 们 若 嫁 以 色 列 别 支 派 的 人 ， 就 必 将 我 们 祖 宗 所 遗 留 的 产 业 加 在 她 们 丈 夫 支 派 的 产 业 中 。 这 样 ， 我 们 拈 阄 所 得 的 产 业 就 要 减 少 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4884', '4', '36', '4', '到 了 以 色 列 人 的 禧 年 ， 这 女 儿 的 产 业 就 必 加 在 她 们 丈 夫 支 派 的 产 业 上 。 这 样 ， 我 们 祖 宗 支 派 的 产 业 就 减 少 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4885', '4', '36', '5', '摩 西 照 耶 和 华 的 话 吩 咐 以 色 列 人 说 ： “ 约 瑟 支 派 的 人 说 得 有 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4886', '4', '36', '6', '论 到 西 罗 非 哈 的 众 女 儿 ， 耶 和 华 这 样 吩 咐 说 ： 她 们 可 以 随 意 嫁 人 ， 只 是 要 嫁 同 宗 支 派 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4887', '4', '36', '7', '这 样 ， 以 色 列 人 的 产 业 就 不 从 这 支 派 归 到 那 支 派 ， 因 为 以 色 列 人 要 各 守 各 祖 宗 支 派 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4888', '4', '36', '8', '凡 在 以 色 列 支 派 中 得 了 产 业 的 女 子 必 作 同 宗 支 派 人 的 妻 ， 好 叫 以 色 列 人 各 自 承 受 他 祖 宗 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4889', '4', '36', '9', '这 样 ， 他 们 的 产 业 就 不 从 这 支 派 归 到 那 支 派 ， 因 为 以 色 列 支 派 的 人 要 各 守 各 的 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4890', '4', '36', '10', '耶 和 华 怎 样 吩 咐 摩 西 ， 西 罗 非 哈 的 众 女 儿 就 怎 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4891', '4', '36', '11', '西 罗 非 哈 的 女 儿 玛 拉 、 得 撒 、 曷 拉 、 密 迦 、 挪 阿 都 嫁 了 他 们 伯 叔 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4892', '4', '36', '12', '她 们 嫁 入 约 瑟 儿 子 、 玛 拿 西 子 孙 的 族 中 ； 她 们 的 产 业 仍 留 在 同 宗 支 派 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4893', '4', '36', '13', '这 是 耶 和 华 在 摩 押 平 原 ─ ─ 约 旦 河 边 、 耶 利 哥 对 面 ─ ─ 藉 着 摩 西 所 吩 咐 以 色 列 人 的 命 令 典 章 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4894', '5', '1', '1', '＜ 回 忆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4895', '5', '1', '2', '（ 从 何 烈 山 经 过 西 珥 山 到 加 低 斯 ． 巴 尼 亚 有 十 一 天 的 路 程 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4896', '5', '1', '3', '出 埃 及 第 四 十 年 十 一 月 初 一 日 ， 摩 西 照 耶 和 华 藉 着 他 所 吩 咐 以 色 列 人 的 话 都 晓 谕 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4897', '5', '1', '4', '那 时 ， 他 已 经 击 杀 了 住 希 实 本 的 亚 摩 利 王 西 宏 和 住 以 得 来 、 亚 斯 他 录 的 巴 珊 王 噩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4898', '5', '1', '5', '摩 西 在 约 旦 河 东 的 摩 押 地 讲 律 法 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4899', '5', '1', '6', '“ 耶 和 华 ─ ─ 我 们 的 神 在 何 烈 山 晓 谕 我 们 说 ： 你 们 在 这 山 上 住 的 日 子 够 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4900', '5', '1', '7', '要 起 行 转 到 亚 摩 利 人 的 山 地 和 靠 近 这 山 地 的 各 处 ， 就 是 亚 拉 巴 、 山 地 、 高 原 、 南 地 ， 沿 海 一 带 迦 南 人 的 地 ， 并 黎 巴 嫩 山 又 到 幼 发 拉 底 大 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4901', '5', '1', '8', '如 今 我 将 这 地 摆 在 你 们 面 前 ； 你 们 要 进 去 得 这 地 ， 就 是 耶 和 华 向 你 们 列 祖 亚 伯 拉 罕 、 以 撒 、 雅 各 起 誓 应 许 赐 给 他 们 和 他 们 后 裔 为 业 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4902', '5', '1', '9', '＜ 摩 西 指 派 审 判 官 （ 出   1 8 ： 1 3 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4903', '5', '1', '10', '耶 和 华 ─ ─ 你 们 的 神 使 你 们 多 起 来 。 看 哪 ， 你 们 今 日 像 天 上 的 星 那 样 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4904', '5', '1', '11', '惟 愿 耶 和 华 ─ ─ 你 们 列 祖 的 神 使 你 们 比 如 今 更 多 千 倍 ， 照 他 所 应 许 你 们 的 话 赐 福 与 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4905', '5', '1', '12', '但 你 们 的 麻 烦 ， 和 管 理 你 们 的 重 任 ， 并 你 们 的 争 讼 ， 我 独 自 一 人 怎 能 担 当 得 起 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4906', '5', '1', '13', '你 们 要 按 着 各 支 派 选 举 有 智 慧 、 有 见 识 、 为 众 人 所 认 识 的 ， 我 立 他 们 为 你 们 的 首 领 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4907', '5', '1', '14', '你 们 回 答 我 说 ： ‘ 照 你 所 说 的 行 了 为 妙 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4908', '5', '1', '15', '我 便 将 你 们 各 支 派 的 首 领 ， 有 智 慧 、 为 众 人 所 认 识 的 ， 照 你 们 的 支 派 ， 立 他 们 为 官 长 、 千 夫 长 、 百 夫 长 、 五 十 夫 长 、 十 夫 长 ， 管 理 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4909', '5', '1', '16', '“ 当 时 ， 我 嘱 咐 你 们 的 审 判 官 说 ： ‘ 你 们 听 讼 ， 无 论 是 弟 兄 彼 此 争 讼 ， 是 与 同 居 的 外 人 争 讼 ， 都 要 按 公 义 判 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4910', '5', '1', '17', '审 判 的 时 候 ， 不 可 看 人 的 外 貌 ； 听 讼 不 可 分 贵 贱 ， 不 可 惧 怕 人 ， 因 为 审 判 是 属 乎 神 的 。 若 有 难 断 的 案 件 ， 可 以 呈 到 我 这 里 ， 我 就 判 断 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4911', '5', '1', '18', '那 时 ， 我 将 你 们 所 当 行 的 事 都 吩 咐 你 们 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4912', '5', '1', '19', '＜ 从 加 低 斯 ． 巴 尼 亚 派 探 子 侦 察 （ 民   1 3 ： 1 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4913', '5', '1', '20', '我 对 你 们 说 ： ‘ 你 们 已 经 到 了 耶 和 华 ─ ─ 我 们 神 所 赐 给 我 们 的 亚 摩 利 人 之 山 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4914', '5', '1', '21', '看 哪 ， 耶 和 华 ─ ─ 你 的 神 已 将 那 地 摆 在 你 面 前 ， 你 要 照 耶 和 华 ─ ─ 你 列 祖 的 神 所 说 的 上 去 得 那 地 为 业 ； 不 要 惧 怕 ， 也 不 要 惊 惶 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4915', '5', '1', '22', '你 们 都 就 近 我 来 说 ： ‘ 我 们 要 先 打 发 人 去 ， 为 我 们 窥 探 那 地 ， 将 我 们 上 去 该 走 何 道 ， 必 进 何 城 ， 都 回 报 我 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4916', '5', '1', '23', '这 话 我 以 为 美 ， 就 从 你 们 中 间 选 了 十 二 个 人 ， 每 支 派 一 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4917', '5', '1', '24', '于 是 他 们 起 身 上 山 地 去 ， 到 以 实 各 谷 ， 窥 探 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4918', '5', '1', '25', '他 们 手 里 拿 着 那 地 的 果 子 下 来 ， 到 我 们 那 里 ， 回 报 说 ： ‘ 耶 和 华 ─ ─ 我 们 的 神 所 赐 给 我 们 的 是 美 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4919', '5', '1', '26', '“ 你 们 却 不 肯 上 去 ， 竟 违 背 了 耶 和 华 ─ ─ 你 们 神 的 命 令 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4920', '5', '1', '27', '在 帐 棚 内 发 怨 言 说 ： ‘ 耶 和 华 因 为 恨 我 们 ， 所 以 将 我 们 从 埃 及 地 领 出 来 ， 要 交 在 亚 摩 利 人 手 中 ， 除 灭 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4921', '5', '1', '28', '我 们 上 哪 里 去 呢 ？ 我 们 的 弟 兄 使 我 们 的 心 消 化 ， 说 那 地 的 民 比 我 们 又 大 又 高 ， 城 邑 又 广 大 又 坚 固 ， 高 得 顶 天 ， 并 且 我 们 在 那 里 看 见 亚 衲 族 的 人 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4922', '5', '1', '29', '我 就 对 你 们 说 ： ‘ 不 要 惊 恐 ， 也 不 要 怕 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4923', '5', '1', '30', '在 你 们 前 面 行 的 耶 和 华 ─ ─ 你 们 的 神 必 为 你 们 争 战 ， 正 如 他 在 埃 及 和 旷 野 ， 在 你 们 眼 前 所 行 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4924', '5', '1', '31', '你 们 在 旷 野 所 行 的 路 上 ， 也 曾 见 耶 和 华 ─ ─ 你 们 的 神 抚 养 你 们 ， 如 同 人 抚 养 儿 子 一 般 ， 直 等 你 们 来 到 这 地 方 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4925', '5', '1', '32', '你 们 在 这 事 上 却 不 信 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4926', '5', '1', '33', '他 在 路 上 ， 在 你 们 前 面 行 ， 为 你 们 找 安 营 的 地 方 ； 夜 间 在 火 柱 里 ， 日 间 在 云 柱 里 ， 指 示 你 们 所 当 行 的 路 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4927', '5', '1', '34', '＜ 耶 和 华 刑 罚 以 色 列 人 （ 民   1 4 ： 2 0 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4928', '5', '1', '35', '‘ 这 恶 世 代 的 人 ， 连 一 个 也 不 得 见 我 起 誓 应 许 赐 给 你 们 列 祖 的 美 地 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4929', '5', '1', '36', '惟 有 耶 孚 尼 的 儿 子 迦 勒 必 得 看 见 ， 并 且 我 要 将 他 所 踏 过 的 地 赐 给 他 和 他 的 子 孙 ， 因 为 他 专 心 跟 从 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4930', '5', '1', '37', '耶 和 华 为 你 的 缘 故 也 向 我 发 怒 ， 说 ： ‘ 你 必 不 得 进 入 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4931', '5', '1', '38', '伺 候 你 、 嫩 的 儿 子 约 书 亚 ， 他 必 得 进 入 那 地 ； 你 要 勉 励 他 ， 因 为 他 要 使 以 色 列 人 承 受 那 地 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4932', '5', '1', '39', '并 且 你 们 的 妇 人 孩 子 ， 就 是 你 们 所 说 、 必 被 掳 掠 的 ， 和 今 日 不 知 善 恶 的 儿 女 ， 必 进 入 那 地 。 我 要 将 那 地 赐 给 他 们 ， 他 们 必 得 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4933', '5', '1', '40', '至 于 你 们 ， 要 转 回 ， 从 红 海 的 路 往 旷 野 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4934', '5', '1', '41', '“ 那 时 ， 你 们 回 答 我 说 ： ‘ 我 们 得 罪 了 耶 和 华 ， 情 愿 照 耶 和 华 ─ ─ 我 们 神 一 切 所 吩 咐 的 上 去 争 战 。 ’ 于 是 你 们 各 人 带 着 兵 器 ， 争 先 上 山 地 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4935', '5', '1', '42', '耶 和 华 吩 咐 我 说 ： ‘ 你 对 他 们 说 ： 不 要 上 去 ， 也 不 要 争 战 ； 因 我 不 在 你 们 中 间 ， 恐 怕 你 们 被 仇 敌 杀 败 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4936', '5', '1', '43', '我 就 告 诉 了 你 们 ， 你 们 却 不 听 从 ， 竟 违 背 耶 和 华 的 命 令 ， 擅 自 上 山 地 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4937', '5', '1', '44', '住 那 山 地 的 亚 摩 利 人 就 出 来 攻 击 你 们 ， 追 赶 你 们 ， 如 蜂 拥 一 般 ， 在 西 珥 杀 退 你 们 ， 直 到 何 珥 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4938', '5', '1', '45', '你 们 便 回 来 ， 在 耶 和 华 面 前 哭 号 ； 耶 和 华 却 不 听 你 们 的 声 音 ， 也 不 向 你 们 侧 耳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4939', '5', '1', '46', '于 是 你 们 在 加 低 斯 住 了 许 多 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4940', '5', '2', '1', '＜ 多 年 在 旷 野 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4941', '5', '2', '2', '耶 和 华 对 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4942', '5', '2', '3', '‘ 你 们 绕 行 这 山 的 日 子 够 了 ， 要 转 向 北 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4943', '5', '2', '4', '你 吩 咐 百 姓 说 ： 你 们 弟 兄 以 扫 的 子 孙 住 在 西 珥 ， 你 们 要 经 过 他 们 的 境 界 。 他 们 必 惧 怕 你 们 ， 所 以 你 们 要 分 外 谨 慎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4944', '5', '2', '5', '不 可 与 他 们 争 战 ； 他 们 的 地 ， 连 脚 掌 可 踏 之 处 ， 我 都 不 给 你 们 ， 因 我 已 将 西 珥 山 赐 给 以 扫 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4945', '5', '2', '6', '你 们 要 用 钱 向 他 们 买 粮 吃 ， 也 要 用 钱 向 他 们 买 水 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4946', '5', '2', '7', '因 为 耶 和 华 ─ ─ 你 的 神 在 你 手 里 所 办 的 一 切 事 上 已 赐 福 与 你 。 你 走 这 大 旷 野 ， 他 都 知 道 了 。 这 四 十 年 ， 耶 和 华 ─ ─ 你 的 神 常 与 你 同 在 ， 故 此 你 一 无 所 缺 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4947', '5', '2', '8', '“ 于 是 ， 我 们 离 了 我 们 弟 兄 以 扫 子 孙 所 住 的 西 珥 ， 从 亚 拉 巴 的 路 ， 经 过 以 拉 他 、 以 旬 ． 迦 别 ， 转 向 摩 押 旷 野 的 路 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4948', '5', '2', '9', '耶 和 华 吩 咐 我 说 ： ‘ 不 可 扰 害 摩 押 人 ， 也 不 可 与 他 们 争 战 。 他 们 的 地 ， 我 不 赐 给 你 为 业 ， 因 我 已 将 亚 珥 赐 给 罗 得 的 子 孙 为 业 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4949', '5', '2', '10', '（ 先 前 ， 有 以 米 人 住 在 那 里 ， 民 数 众 多 ， 身 体 高 大 ， 像 亚 衲 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4950', '5', '2', '11', '这 以 米 人 像 亚 衲 人 ； 也 算 为 利 乏 音 人 ； 摩 押 人 称 他 们 为 以 米 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4951', '5', '2', '12', '先 前 ， 何 利 人 也 住 在 西 珥 ， 但 以 扫 的 子 孙 将 他 们 除 灭 ， 得 了 他 们 的 地 ， 接 着 居 住 ， 就 如 以 色 列 在 耶 和 华 赐 给 他 为 业 之 地 所 行 的 一 样 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4952', '5', '2', '13', '现 在 ， 起 来 过 撒 烈 溪 ！ 于 是 我 们 过 了 撒 烈 溪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4953', '5', '2', '14', '自 从 离 开 加 低 斯 ． 巴 尼 亚 ， 到 过 了 撒 烈 溪 的 时 候 ， 共 有 三 十 八 年 ， 等 那 世 代 的 兵 丁 都 从 营 中 灭 尽 ， 正 如 耶 和 华 向 他 们 所 起 的 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4954', '5', '2', '15', '耶 和 华 的 手 也 攻 击 他 们 ， 将 他 们 从 营 中 除 灭 ， 直 到 灭 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4955', '5', '2', '16', '“ 兵 丁 从 民 中 都 灭 尽 死 亡 以 后 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4956', '5', '2', '17', '耶 和 华 吩 咐 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4957', '5', '2', '18', '‘ 你 今 天 要 从 摩 押 的 境 界 亚 珥 经 过 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4958', '5', '2', '19', '走 近 亚 扪 人 之 地 ， 不 可 扰 害 他 们 ， 也 不 可 与 他 们 争 战 。 亚 扪 人 的 地 ， 我 不 赐 给 你 们 为 业 ， 因 我 已 将 那 地 赐 给 罗 得 的 子 孙 为 业 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4959', '5', '2', '20', '（ 那 地 也 算 为 利 乏 音 人 之 地 ， 先 前 利 乏 音 人 住 在 那 里 ， 亚 扪 人 称 他 们 为 散 送 冥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4960', '5', '2', '21', '那 民 众 多 ， 身 体 高 大 ， 像 亚 衲 人 一 样 ， 但 耶 和 华 从 亚 扪 人 面 前 除 灭 他 们 ， 亚 扪 人 就 得 了 他 们 的 地 ， 接 着 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4961', '5', '2', '22', '正 如 耶 和 华 从 前 为 住 西 珥 的 以 扫 子 孙 将 何 利 人 从 他 们 面 前 除 灭 、 他 们 得 了 何 利 人 的 地 、 接 着 居 住 一 样 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4962', '5', '2', '23', '从 迦 斐 托 出 来 的 迦 斐 托 人 将 先 前 住 在 乡 村 直 到 迦 萨 的 亚 卫 人 除 灭 ， 接 着 居 住 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4963', '5', '2', '24', '你 们 起 来 前 往 ， 过 亚 嫩 谷 ； 我 已 将 亚 摩 利 人 希 实 本 王 西 宏 和 他 的 地 交 在 你 手 中 ， 你 要 与 他 争 战 ， 得 他 的 地 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4964', '5', '2', '25', '从 今 日 起 ， 我 要 使 天 下 万 民 听 见 你 的 名 声 都 惊 恐 惧 怕 ， 且 因 你 发 颤 伤 恸 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4965', '5', '2', '26', '＜ 击 败 希 实 本 王 西 宏 （ 民   2 1 ： 2 1 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4966', '5', '2', '27', '‘ 求 你 容 我 从 你 的 地 经 过 ， 只 走 大 道 ， 不 偏 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4967', '5', '2', '28', '你 可 以 卖 粮 给 我 吃 ， 也 可 以 卖 水 给 我 喝 ， 只 要 容 我 步 行 过 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4968', '5', '2', '29', '就 如 住 西 珥 的 以 扫 子 孙 和 住 亚 珥 的 摩 押 人 待 我 一 样 ， 等 我 过 了 约 旦 河 ， 好 进 入 耶 和 华 ─ ─ 我 们 神 所 赐 给 我 们 的 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4969', '5', '2', '30', '但 希 实 本 王 西 宏 不 容 我 们 从 他 那 里 经 过 ； 因 为 耶 和 华 ─ ─ 你 的 神 使 他 心 中 刚 硬 ， 性 情 顽 梗 ， 为 要 将 他 交 在 你 手 中 ， 像 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4970', '5', '2', '31', '耶 和 华 对 我 说 ： ‘ 从 此 起 首 ， 我 要 将 西 宏 和 他 的 地 交 给 你 ； 你 要 得 他 的 地 为 业 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4971', '5', '2', '32', '那 时 ， 西 宏 和 他 的 众 民 出 来 攻 击 我 们 ， 在 雅 杂 与 我 们 交 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4972', '5', '2', '33', '耶 和 华 ─ ─ 我 们 的 神 将 他 交 给 我 们 ， 我 们 就 把 他 和 他 的 儿 子 ， 并 他 的 众 民 ， 都 击 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4973', '5', '2', '34', '我 们 夺 了 他 的 一 切 城 邑 ， 将 有 人 烟 的 各 城 ， 连 女 人 带 孩 子 ， 尽 都 毁 灭 ， 没 有 留 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4974', '5', '2', '35', '惟 有 牲 畜 和 所 夺 的 各 城 ， 并 其 中 的 财 物 ， 都 取 为 自 己 的 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4975', '5', '2', '36', '从 亚 嫩 谷 边 的 亚 罗 珥 和 谷 中 的 城 ， 直 到 基 列 ， 耶 和 华 ─ ─ 我 们 的 神 都 交 给 我 们 了 ， 没 有 一 座 城 高 得 使 我 们 不 能 攻 取 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4976', '5', '2', '37', '惟 有 亚 扪 人 之 地 ， 凡 靠 近 雅 博 河 的 地 ， 并 山 地 的 城 邑 ， 与 耶 和 华 ─ ─ 我 们 神 所 禁 止 我 们 去 的 地 方 ， 都 没 有 挨 近 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4977', '5', '3', '1', '＜ 击 败 巴 珊 王 噩 （ 民   2 1 ： 3 1 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4978', '5', '3', '2', '耶 和 华 对 我 说 ： ‘ 不 要 怕 他 ！ 因 我 已 将 他 和 他 的 众 民 ， 并 他 的 地 ， 都 交 在 你 手 中 ； 你 要 待 他 像 从 前 待 住 希 实 本 的 亚 摩 利 王 西 宏 一 样 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4979', '5', '3', '3', '于 是 耶 和 华 ─ ─ 我 们 的 神 也 将 巴 珊 王 噩 和 他 的 众 民 都 交 在 我 们 手 中 ； 我 们 杀 了 他 们 ， 没 有 留 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4980', '5', '3', '4', '那 时 ， 我 们 夺 了 他 所 有 的 城 ， 共 有 六 十 座 ， 没 有 一 座 城 不 被 我 们 所 夺 。 这 为 亚 珥 歌 伯 的 全 境 ， 就 是 巴 珊 地 噩 王 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4981', '5', '3', '5', '这 些 城 都 有 坚 固 的 高 墙 ， 有 门 有 闩 。 此 外 还 有 许 多 无 城 墙 的 乡 村 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4982', '5', '3', '6', '我 们 将 这 些 都 毁 灭 了 ， 像 从 前 待 希 实 本 王 西 宏 一 样 ， 把 有 人 烟 的 各 城 ， 连 女 人 带 孩 子 ， 尽 都 毁 灭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4983', '5', '3', '7', '惟 有 一 切 牲 畜 和 城 中 的 财 物 都 取 为 自 己 的 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4984', '5', '3', '8', '那 时 ， 我 们 从 约 旦 河 东 两 个 亚 摩 利 王 的 手 将 亚 嫩 谷 直 到 黑 门 山 之 地 夺 过 来');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4985', '5', '3', '9', '（ 这 黑 门 山 ， 西 顿 人 称 为 西 连 ， 亚 摩 利 人 称 为 示 尼 珥 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4986', '5', '3', '10', '就 是 夺 了 平 原 的 各 城 、 基 列 全 地 、 巴 珊 全 地 ， 直 到 撒 迦 和 以 得 来 ， 都 是 巴 珊 王 噩 国 内 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4987', '5', '3', '11', '（ 利 乏 音 人 所 剩 下 的 只 有 巴 珊 王 噩 。 他 的 床 是 铁 的 ， 长 九 肘 ， 宽 四 肘 ， 都 是 以 人 肘 为 度 。 现 今 岂 不 是 在 亚 扪 人 的 拉 巴 吗 ？ ） ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4988', '5', '3', '12', '＜ 定 居 约 旦 河 东 的 二 支 派 半 （ 民   3 2 ： 1 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4989', '5', '3', '13', '其 余 的 基 列 地 和 巴 珊 全 地 ， 就 是 噩 王 的 国 ， 我 给 了 玛 拿 西 半 支 派 。 亚 珥 歌 伯 全 地 乃 是 巴 珊 全 地 ； 这 叫 做 利 乏 音 人 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4990', '5', '3', '14', '玛 拿 西 的 子 孙 睚 珥 占 了 亚 珥 歌 伯 全 境 ， 直 到 基 述 人 和 玛 迦 人 的 交 界 ， 就 按 自 己 的 名 称 这 巴 珊 地 为 哈 倭 特 ． 睚 珥 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4991', '5', '3', '15', '我 又 将 基 列 给 了 玛 吉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4992', '5', '3', '16', '从 基 列 到 亚 嫩 谷 ， 以 谷 中 为 界 ， 直 到 亚 扪 人 交 界 的 雅 博 河 ， 我 给 了 吕 便 人 和 迦 得 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4993', '5', '3', '17', '又 将 亚 拉 巴 和 靠 近 约 旦 河 之 地 ， 从 基 尼 烈 直 到 亚 拉 巴 海 ， 就 是 盐 海 ， 并 毗 斯 迦 山 根 东 边 之 地 ， 都 给 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4994', '5', '3', '18', '“ 那 时 ， 我 吩 咐 你 们 说 ： ‘ 耶 和 华 ─ ─ 你 们 的 神 已 将 这 地 赐 给 你 们 为 业 ； 你 们 所 有 的 勇 士 都 要 带 着 兵 器 ， 在 你 们 的 弟 兄 以 色 列 人 前 面 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4995', '5', '3', '19', '但 你 们 的 妻 子 、 孩 子 、 牲 畜 （ 我 知 道 你 们 有 许 多 的 牲 畜 ） 可 以 住 在 我 所 赐 给 你 们 的 各 城 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4996', '5', '3', '20', '等 到 你 们 弟 兄 在 约 旦 河 那 边 ， 也 得 耶 和 华 ─ ─ 你 们 神 所 赐 给 他 们 的 地 ， 又 使 他 们 得 享 平 安 ， 与 你 们 一 样 ， 你 们 才 可 以 回 到 我 所 赐 给 你 们 为 业 之 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4997', '5', '3', '21', '那 时 我 吩 咐 约 书 亚 说 ： ‘ 你 亲 眼 看 见 了 耶 和 华 ─ ─ 你 神 向 这 二 王 所 行 的 ； 耶 和 华 也 必 向 你 所 要 去 的 各 国 照 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4998', '5', '3', '22', '你 不 要 怕 他 们 ， 因 那 为 你 争 战 的 是 耶 和 华 ─ ─ 你 的 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('4999', '5', '3', '23', '＜ 摩 西 不 得 进 入 迦 南 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5000', '5', '3', '24', '‘ 主 耶 和 华 啊 ， 你 已 将 你 的 大 力 大 能 显 给 仆 人 看 。 在 天 上 ， 在 地 下 ， 有 什 么 神 能 像 你 行 事 、 像 你 有 大 能 的 作 为 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5001', '5', '3', '25', '求 你 容 我 过 去 ， 看 约 旦 河 那 边 的 美 地 ， 就 是 那 佳 美 的 山 地 和 黎 巴 嫩 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5002', '5', '3', '26', '但 耶 和 华 因 你 们 的 缘 故 向 我 发 怒 ， 不 应 允 我 ， 对 我 说 ： ‘ 罢 了 ！ 你 不 要 向 我 再 提 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5003', '5', '3', '27', '你 且 上 毗 斯 迦 山 顶 去 ， 向 东 、 西 、 南 、 北 举 目 观 望 ， 因 为 你 必 不 能 过 这 约 旦 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5004', '5', '3', '28', '你 却 要 嘱 咐 约 书 亚 ， 勉 励 他 ， 使 他 胆 壮 ； 因 为 他 必 在 这 百 姓 前 面 过 去 ， 使 他 们 承 受 你 所 要 观 看 之 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5005', '5', '3', '29', '于 是 我 们 住 在 伯 ． 毗 珥 对 面 的 谷 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5006', '5', '4', '1', '＜ 摩 西 劝 人 民 遵 行 耶 和 华 的 律 例 典 章 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5007', '5', '4', '2', '所 吩 咐 你 们 的 话 ， 你 们 不 可 加 添 ， 也 不 可 删 减 ， 好 叫 你 们 遵 守 我 所 吩 咐 的 ， 就 是 耶 和 华 ─ ─ 你 们 神 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5008', '5', '4', '3', '耶 和 华 因 巴 力 ． 毗 珥 的 事 所 行 的 ， 你 们 亲 眼 看 见 了 。 凡 随 从 巴 力 ． 毗 珥 的 人 ， 耶 和 华 ─ ─ 你 们 的 神 都 从 你 们 中 间 除 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5009', '5', '4', '4', '惟 有 你 们 专 靠 耶 和 华 ─ ─ 你 们 神 的 人 ， 今 日 全 都 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5010', '5', '4', '5', '我 照 着 耶 和 华 ─ ─ 我 神 所 吩 咐 的 将 律 例 典 章 教 训 你 们 ， 使 你 们 在 所 要 进 去 得 为 业 的 地 上 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5011', '5', '4', '6', '所 以 你 们 要 谨 守 遵 行 ； 这 就 是 你 们 在 万 民 眼 前 的 智 慧 、 聪 明 。 他 们 听 见 这 一 切 律 例 ， 必 说 ： ‘ 这 大 国 的 人 真 是 有 智 慧 ， 有 聪 明 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5012', '5', '4', '7', '哪 一 大 国 的 人 有 神 与 他 们 相 近 ， 像 耶 和 华 ─ ─ 我 们 的 神 、 在 我 们 求 告 他 的 时 候 与 我 们 相 近 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5013', '5', '4', '8', '又 哪 一 大 国 有 这 样 公 义 的 律 例 典 章 、 像 我 今 日 在 你 们 面 前 所 陈 明 的 这 一 切 律 法 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5014', '5', '4', '9', '“ 你 只 要 谨 慎 ， 殷 勤 保 守 你 的 心 灵 ， 免 得 忘 记 你 亲 眼 所 看 见 的 事 ， 又 免 得 你 一 生 、 这 事 离 开 你 的 心 ； 总 要 传 给 你 的 子 子 孙 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5015', '5', '4', '10', '你 在 何 烈 山 站 在 耶 和 华 ─ ─ 你 神 面 前 的 那 日 ， 耶 和 华 对 我 说 ： ‘ 你 为 我 招 聚 百 姓 ， 我 要 叫 他 们 听 见 我 的 话 ， 使 他 们 存 活 在 世 的 日 子 ， 可 以 学 习 敬 畏 我 ， 又 可 以 教 训 儿 女 这 样 行 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5016', '5', '4', '11', '那 时 你 们 近 前 来 ， 站 在 山 下 ； 山 上 有 火 焰 冲 天 ， 并 有 昏 黑 、 密 云 、 幽 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5017', '5', '4', '12', '耶 和 华 从 火 焰 中 对 你 们 说 话 ， 你 们 只 听 见 声 音 ， 却 没 有 看 见 形 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5018', '5', '4', '13', '他 将 所 吩 咐 你 们 当 守 的 约 指 示 你 们 ， 就 是 十 条 诫 ， 并 将 这 诫 写 在 两 块 石 版 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5019', '5', '4', '14', '那 时 耶 和 华 又 吩 咐 我 将 律 例 典 章 教 训 你 们 ， 使 你 们 在 所 要 过 去 得 为 业 的 地 上 遵 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5020', '5', '4', '15', '＜ 警 告 人 民 不 可 拜 偶 像 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5021', '5', '4', '16', '惟 恐 你 们 败 坏 自 己 ， 雕 刻 偶 像 ， 仿 佛 什 么 男 像 女 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5022', '5', '4', '17', '或 地 上 走 兽 的 像 ， 或 空 中 飞 鸟 的 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5023', '5', '4', '18', '或 地 上 爬 物 的 像 ， 或 地 底 下 水 中 鱼 的 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5024', '5', '4', '19', '又 恐 怕 你 向 天 举 目 观 看 ， 见 耶 和 华 ─ ─ 你 的 神 为 天 下 万 民 所 摆 列 的 日 月 星 ， 就 是 天 上 的 万 象 ， 自 己 便 被 勾 引 敬 拜 事 奉 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5025', '5', '4', '20', '耶 和 华 将 你 们 从 埃 及 领 出 来 ， 脱 离 铁 炉 ， 要 特 作 自 己 产 业 的 子 民 ， 像 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5026', '5', '4', '21', '耶 和 华 又 因 你 们 的 缘 故 向 我 发 怒 ， 起 誓 必 不 容 我 过 约 旦 河 ， 也 不 容 我 进 入 耶 和 华 ─ ─ 你 神 所 赐 你 为 业 的 那 美 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5027', '5', '4', '22', '我 只 得 死 在 这 地 ， 不 能 过 约 旦 河 ； 但 你 们 必 过 去 得 那 美 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5028', '5', '4', '23', '你 们 要 谨 慎 ， 免 得 忘 记 耶 和 华 ─ ─ 你 们 神 与 你 们 所 立 的 约 ， 为 自 己 雕 刻 偶 像 ， 就 是 耶 和 华 ─ ─ 你 神 所 禁 止 你 做 的 偶 像 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5029', '5', '4', '24', '因 为 耶 和 华 ─ ─ 你 的 神 乃 是 烈 火 ， 是 忌 邪 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5030', '5', '4', '25', '“ 你 们 在 那 地 住 久 了 ， 生 子 生 孙 ， 就 雕 刻 偶 像 ， 仿 佛 什 么 形 像 ， 败 坏 自 己 ， 行 耶 和 华 ─ ─ 你 神 眼 中 看 为 恶 的 事 ， 惹 他 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5031', '5', '4', '26', '我 今 日 呼 天 唤 地 向 你 们 作 见 证 ， 你 们 必 在 过 约 旦 河 得 为 业 的 地 上 速 速 灭 尽 ！ 你 们 不 能 在 那 地 上 长 久 ， 必 尽 行 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5032', '5', '4', '27', '耶 和 华 必 使 你 们 分 散 在 万 民 中 ； 在 他 所 领 你 们 到 的 万 国 里 ， 你 们 剩 下 的 人 数 稀 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5033', '5', '4', '28', '在 那 里 ， 你 们 必 事 奉 人 手 所 造 的 神 ， 就 是 用 木 石 造 成 、 不 能 看 、 不 能 听 、 不 能 吃 、 不 能 闻 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5034', '5', '4', '29', '但 你 们 在 那 里 必 寻 求 耶 和 华 ─ ─ 你 的 神 。 你 尽 心 尽 性 寻 求 他 的 时 候 ， 就 必 寻 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5035', '5', '4', '30', '日 后 你 遭 遇 一 切 患 难 的 时 候 ， 你 必 归 回 耶 和 华 ─ ─ 你 的 神 ， 听 从 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5036', '5', '4', '31', '耶 和 华 ─ ─ 你 神 原 是 有 怜 悯 的 神 ； 他 总 不 撇 下 你 ， 不 灭 绝 你 ， 也 不 忘 记 他 起 誓 与 你 列 祖 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5037', '5', '4', '32', '“ 你 且 考 察 在 你 以 前 的 世 代 ， 自 神 造 人 在 世 以 来 ， 从 天 这 边 到 天 那 边 ， 曾 有 何 民 听 见 神 在 火 中 说 话 的 声 音 ， 像 你 听 见 还 能 存 活 呢 ？ 这 样 的 大 事 何 曾 有 、 何 曾 听 见 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5038', '5', '4', '33', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5039', '5', '4', '34', '神 何 曾 从 别 的 国 中 将 一 国 的 人 民 领 出 来 ， 用 试 验 、 神 迹 、 奇 事 、 争 战 、 大 能 的 手 ， 和 伸 出 来 的 膀 臂 ， 并 大 可 畏 的 事 ， 像 耶 和 华 ─ ─ 你 们 的 神 在 埃 及 ， 在 你 们 眼 前 为 你 们 所 行 的 一 切 事 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5040', '5', '4', '35', '这 是 显 给 你 看 ， 要 使 你 知 道 ， 惟 有 耶 和 华 ─ ─ 他 是 神 ， 除 他 以 外 ， 再 无 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5041', '5', '4', '36', '他 从 天 上 使 你 听 见 他 的 声 音 ， 为 要 教 训 你 ， 又 在 地 上 使 你 看 见 他 的 烈 火 ， 并 且 听 见 他 从 火 中 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5042', '5', '4', '37', '因 他 爱 你 的 列 祖 ， 所 以 拣 选 他 们 的 后 裔 ， 用 大 能 亲 自 领 你 出 了 埃 及 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5043', '5', '4', '38', '要 将 比 你 强 大 的 国 民 从 你 面 前 赶 出 ， 领 你 进 去 ， 将 他 们 的 地 赐 你 为 业 ， 像 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5044', '5', '4', '39', '所 以 ， 今 日 你 要 知 道 ， 也 要 记 在 心 上 ， 天 上 地 下 惟 有 耶 和 华 他 是 神 ， 除 他 以 外 ， 再 无 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5045', '5', '4', '40', '我 今 日 将 他 的 律 例 诫 命 晓 谕 你 ， 你 要 遵 守 ， 使 你 和 你 的 子 孙 可 以 得 福 ， 并 使 你 的 日 子 在 耶 和 华 ─ ─ 你 神 所 赐 的 地 上 得 以 长 久 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5046', '5', '4', '41', '＜ 设 立 河 东 的 庇 护 城 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5047', '5', '4', '42', '使 那 素 无 仇 恨 、 无 心 杀 了 人 的 ， 可 以 逃 到 这 三 城 之 中 的 一 座 城 ， 就 得 存 活 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5048', '5', '4', '43', '为 吕 便 人 分 定 旷 野 平 原 的 比 悉 ； 为 迦 得 人 分 定 基 列 的 拉 末 ； 为 玛 拿 西 人 分 定 巴 珊 的 哥 兰 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5049', '5', '4', '44', '＜ 颁 布 律 法 的 序 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5050', '5', '4', '45', '就 是 摩 西 在 以 色 列 人 出 埃 及 后 所 传 给 他 们 的 法 度 、 律 例 、 典 章 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5051', '5', '4', '46', '在 约 旦 河 东 伯 ． 毗 珥 对 面 的 谷 中 ， 在 住 希 实 本 、 亚 摩 利 王 西 宏 之 地 ； 这 西 宏 是 摩 西 和 以 色 列 人 出 埃 及 后 所 击 杀 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5052', '5', '4', '47', '他 们 得 了 他 的 地 ， 又 得 了 巴 珊 王 噩 的 地 ， 就 是 两 个 亚 摩 利 王 ， 在 约 旦 河 东 向 日 出 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5053', '5', '4', '48', '从 亚 嫩 谷 边 的 亚 罗 珥 ， 直 到 西 云 山 ， 就 是 黑 门 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5054', '5', '4', '49', '还 有 约 旦 河 东 的 全 亚 拉 巴 ， 直 到 亚 拉 巴 海 ， 靠 近 毗 斯 迦 山 根 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5055', '5', '5', '1', '＜ 十 诫 （ 出   2 0 ： 1 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5056', '5', '5', '2', '耶 和 华 ─ ─ 我 们 的 神 在 何 烈 山 与 我 们 立 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5057', '5', '5', '3', '这 约 不 是 与 我 们 列 祖 立 的 ， 乃 是 与 我 们 今 日 在 这 里 存 活 之 人 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5058', '5', '5', '4', '耶 和 华 在 山 上 ， 从 火 中 ， 面 对 面 与 你 们 说 话 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5059', '5', '5', '5', '那 时 我 站 在 耶 和 华 和 你 们 中 间 ， 要 将 耶 和 华 的 话 传 给 你 们 ； 因 为 你 们 惧 怕 那 火 ， 没 有 上 山 ─ ─ 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5060', '5', '5', '6', '“ ‘ 我 是 耶 和 华 ─ ─ 你 的 神 ， 曾 将 你 从 埃 及 地 为 奴 之 家 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5061', '5', '5', '7', '“ ‘ 除 了 我 以 外 ， 你 不 可 有 别 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5062', '5', '5', '8', '“ ‘ 不 可 为 自 己 雕 刻 偶 像 ， 也 不 可 做 什 么 形 像 ， 仿 佛 上 天 、 下 地 和 地 底 下 、 水 中 的 百 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5063', '5', '5', '9', '不 可 跪 拜 那 些 像 ， 也 不 可 事 奉 它 ， 因 为 我 耶 和 华 ─ ─ 你 的 神 是 忌 邪 的 神 。 恨 我 的 ， 我 必 追 讨 他 的 罪 ， 自 父 及 子 ， 直 到 三 、 四 代 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5064', '5', '5', '10', '爱 我 、 守 我 诫 命 的 ， 我 必 向 他 们 发 慈 爱 ， 直 到 千 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5065', '5', '5', '11', '“ ‘ 不 可 妄 称 耶 和 华 ─ ─ 你 神 的 名 ； 因 为 妄 称 耶 和 华 名 的 ， 耶 和 华 必 不 以 他 为 无 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5066', '5', '5', '12', '“ ‘ 当 照 耶 和 华 ─ ─ 你 神 所 吩 咐 的 守 安 息 日 为 圣 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5067', '5', '5', '13', '六 日 要 劳 碌 做 你 一 切 的 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5068', '5', '5', '14', '但 第 七 日 是 向 耶 和 华 ─ ─ 你 神 当 守 的 安 息 日 。 这 一 日 ， 你 和 你 的 儿 女 、 仆 婢 、 牛 、 驴 、 牲 畜 ， 并 在 你 城 里 寄 居 的 客 旅 ， 无 论 何 工 都 不 可 做 ， 使 你 的 仆 婢 可 以 和 你 一 样 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5069', '5', '5', '15', '你 也 要 记 念 你 在 埃 及 地 作 过 奴 仆 ； 耶 和 华 ─ ─ 你 神 用 大 能 的 手 和 伸 出 来 的 膀 臂 将 你 从 那 里 领 出 来 。 因 此 ， 耶 和 华 ─ ─ 你 的 神 吩 咐 你 守 安 息 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5070', '5', '5', '16', '“ ‘ 当 照 耶 和 华 ─ ─ 你 神 所 吩 咐 的 孝 敬 父 母 ， 使 你 得 福 ， 并 使 你 的 日 子 在 耶 和 华 ─ ─ 你 神 所 赐 你 的 地 上 得 以 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5071', '5', '5', '17', '“ ‘ 不 可 杀 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5072', '5', '5', '18', '“ ‘ 不 可 奸 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5073', '5', '5', '19', '“ ‘ 不 可 偷 盗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5074', '5', '5', '20', '“ ‘ 不 可 作 假 见 证 陷 害 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5075', '5', '5', '21', '“ ‘ 不 可 贪 恋 人 的 妻 子 ； 也 不 可 贪 图 人 的 房 屋 、 田 地 、 仆 婢 、 牛 、 驴 ， 并 他 一 切 所 有 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5076', '5', '5', '22', '“ 这 些 话 是 耶 和 华 在 山 上 ， 从 火 中 、 云 中 、 幽 暗 中 ， 大 声 晓 谕 你 们 全 会 众 的 ； 此 外 并 没 有 添 别 的 话 。 他 就 把 这 话 写 在 两 块 石 版 上 ， 交 给 我 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5077', '5', '5', '23', '＜ 人 民 看 见 火 焰 烧 山 而 惧 怕 （ 出   2 0 ： 1 8 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5078', '5', '5', '24', '说 ： ‘ 看 哪 ， 耶 和 华 ─ ─ 我 们 神 将 他 的 荣 光 和 他 的 大 能 显 给 我 们 看 ， 我 们 又 听 见 他 的 声 音 从 火 中 出 来 。 今 日 我 们 得 见 神 与 人 说 话 ， 人 还 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5079', '5', '5', '25', '现 在 这 大 火 将 要 烧 灭 我 们 ， 我 们 何 必 冒 死 呢 ？ 若 再 听 见 耶 和 华 ─ ─ 我 们 神 的 声 音 就 必 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5080', '5', '5', '26', '凡 属 血 气 的 ， 曾 有 何 人 听 见 永 生 神 的 声 音 从 火 中 出 来 ， 像 我 们 听 见 还 能 存 活 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5081', '5', '5', '27', '求 你 近 前 去 ， 听 耶 和 华 ─ ─ 我 们 神 所 要 说 的 一 切 话 ， 将 他 对 你 说 的 话 都 传 给 我 们 ， 我 们 就 听 从 遵 行 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5082', '5', '5', '28', '“ 你 们 对 我 说 的 话 ， 耶 和 华 都 听 见 了 。 耶 和 华 对 我 说 ： ‘ 这 百 姓 的 话 ， 我 听 见 了 ； 他 们 所 说 的 都 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5083', '5', '5', '29', '惟 愿 他 们 存 这 样 的 心 敬 畏 我 ， 常 遵 守 我 的 一 切 诫 命 ， 使 他 们 和 他 们 的 子 孙 永 远 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5084', '5', '5', '30', '你 去 对 他 们 说 ： 你 们 回 帐 棚 去 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5085', '5', '5', '31', '至 于 你 ， 可 以 站 在 我 这 里 ， 我 要 将 一 切 诫 命 、 律 例 、 典 章 传 给 你 ； 你 要 教 训 他 们 ， 使 他 们 在 我 赐 他 们 为 业 的 地 上 遵 行 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5086', '5', '5', '32', '所 以 ， 你 们 要 照 耶 和 华 ─ ─ 你 们 神 所 吩 咐 的 谨 守 遵 行 ， 不 可 偏 离 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5087', '5', '5', '33', '耶 和 华 ─ ─ 你 们 神 所 吩 咐 你 们 行 的 ， 你 们 都 要 去 行 ， 使 你 们 可 以 存 活 得 福 ， 并 使 你 们 的 日 子 在 所 要 承 受 的 地 上 得 以 长 久 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5088', '5', '6', '1', '＜ 最 大 的 诫 命 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5089', '5', '6', '2', '好 叫 你 和 你 子 子 孙 孙 一 生 敬 畏 耶 和 华 ─ ─ 你 的 神 ， 谨 守 他 的 一 切 律 例 诫 命 ， 就 是 我 所 吩 咐 你 的 ， 使 你 的 日 子 得 以 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5090', '5', '6', '3', '以 色 列 啊 ， 你 要 听 ， 要 谨 守 遵 行 ， 使 你 可 以 在 那 流 奶 与 蜜 之 地 得 以 享 福 ， 人 数 极 其 增 多 ， 正 如 耶 和 华 ─ ─ 你 列 祖 的 神 所 应 许 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5091', '5', '6', '4', '“ 以 色 列 啊 ， 你 要 听 ！ 耶 和 华 ─ ─ 我 们 神 是 独 一 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5092', '5', '6', '5', '你 要 尽 心 、 尽 性 、 尽 力 爱 耶 和 华 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5093', '5', '6', '6', '我 今 日 所 吩 咐 你 的 话 都 要 记 在 心 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5094', '5', '6', '7', '也 要 殷 勤 教 训 你 的 儿 女 。 无 论 你 坐 在 家 里 ， 行 在 路 上 ， 躺 下 ， 起 来 ， 都 要 谈 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5095', '5', '6', '8', '也 要 系 在 手 上 为 记 号 ， 戴 在 额 上 为 经 文 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5096', '5', '6', '9', '又 要 写 在 你 房 屋 的 门 框 上 ， 并 你 的 城 门 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5097', '5', '6', '10', '＜ 警 告 人 民 不 可 背 逆 神 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5098', '5', '6', '11', '有 房 屋 ， 装 满 各 样 美 物 ， 非 你 所 装 满 的 ； 有 凿 成 的 水 井 ， 非 你 所 凿 成 的 ； 还 有 葡 萄 园 、 橄 榄 园 ， 非 你 所 栽 种 的 ； 你 吃 了 而 且 饱 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5099', '5', '6', '12', '那 时 你 要 谨 慎 ， 免 得 你 忘 记 将 你 从 埃 及 地 、 为 奴 之 家 领 出 来 的 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5100', '5', '6', '13', '你 要 敬 畏 耶 和 华 ─ ─ 你 的 神 ， 事 奉 他 ， 指 着 他 的 名 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5101', '5', '6', '14', '不 可 随 从 别 神 ， 就 是 你 们 四 围 国 民 的 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5102', '5', '6', '15', '因 为 在 你 们 中 间 的 耶 和 华 ─ ─ 你 神 是 忌 邪 的 神 ， 惟 恐 耶 和 华 ─ ─ 你 神 的 怒 气 向 你 发 作 ， 就 把 你 从 地 上 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5103', '5', '6', '16', '“ 你 们 不 可 试 探 耶 和 华 ─ ─ 你 们 的 神 ， 像 你 们 在 玛 撒 那 样 试 探 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5104', '5', '6', '17', '要 留 意 遵 守 耶 和 华 ─ ─ 你 们 神 所 吩 咐 的 诫 命 、 法 度 、 律 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5105', '5', '6', '18', '耶 和 华 眼 中 看 为 正 、 看 为 善 的 ， 你 都 要 遵 行 ， 使 你 可 以 享 福 ， 并 可 以 进 去 得 耶 和 华 向 你 列 祖 起 誓 应 许 的 那 美 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5106', '5', '6', '19', '照 耶 和 华 所 说 的 ， 从 你 面 前 撵 出 你 的 一 切 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5107', '5', '6', '20', '“ 日 后 ， 你 的 儿 子 问 你 说 ： ‘ 耶 和 华 ─ ─ 我 们 神 吩 咐 你 们 的 这 些 法 度 、 律 例 、 典 章 是 什 么 意 思 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5108', '5', '6', '21', '你 就 告 诉 你 的 儿 子 说 ： ‘ 我 们 在 埃 及 作 过 法 老 的 奴 仆 ； 耶 和 华 用 大 能 的 手 将 我 们 从 埃 及 领 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5109', '5', '6', '22', '在 我 们 眼 前 ， 将 重 大 可 怕 的 神 迹 奇 事 施 行 在 埃 及 地 和 法 老 并 他 全 家 的 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5110', '5', '6', '23', '将 我 们 从 那 里 领 出 来 ， 要 领 我 们 进 入 他 向 我 们 列 祖 起 誓 应 许 之 地 ， 把 这 地 赐 给 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5111', '5', '6', '24', '耶 和 华 又 吩 咐 我 们 遵 行 这 一 切 律 例 ， 要 敬 畏 耶 和 华 ─ ─ 我 们 的 神 ， 使 我 们 常 得 好 处 ， 蒙 他 保 全 我 们 的 生 命 ， 像 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5112', '5', '6', '25', '我 们 若 照 耶 和 华 ─ ─ 我 们 神 所 吩 咐 的 一 切 诫 命 谨 守 遵 行 ， 这 就 是 我 们 的 义 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5113', '5', '7', '1', '＜ 耶 和 华 的 子 民 （ 出   3 4 ： 1 1 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5114', '5', '7', '2', '耶 和 华 ─ ─ 你 神 将 他 们 交 给 你 击 杀 ， 那 时 你 要 把 他 们 灭 绝 净 尽 ， 不 可 与 他 们 立 约 ， 也 不 可 怜 恤 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5115', '5', '7', '3', '不 可 与 他 们 结 亲 。 不 可 将 你 的 女 儿 嫁 他 们 的 儿 子 ， 也 不 可 叫 你 的 儿 子 娶 他 们 的 女 儿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5116', '5', '7', '4', '因 为 他 必 使 你 儿 子 转 离 不 跟 从 主 ， 去 事 奉 别 神 ， 以 致 耶 和 华 的 怒 气 向 你 们 发 作 ， 就 速 速 地 将 你 们 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5117', '5', '7', '5', '你 们 却 要 这 样 待 他 们 ： 拆 毁 他 们 的 祭 坛 ， 打 碎 他 们 的 柱 像 ， 砍 下 他 们 的 木 偶 ， 用 火 焚 烧 他 们 雕 刻 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5118', '5', '7', '6', '因 为 你 归 耶 和 华 ─ ─ 你 神 为 圣 洁 的 民 ； 耶 和 华 ─ ─ 你 神 从 地 上 的 万 民 中 拣 选 你 ， 特 作 自 己 的 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5119', '5', '7', '7', '“ 耶 和 华 专 爱 你 们 ， 拣 选 你 们 ， 并 非 因 你 们 的 人 数 多 于 别 民 ， 原 来 你 们 的 人 数 在 万 民 中 是 最 少 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5120', '5', '7', '8', '只 因 耶 和 华 爱 你 们 ， 又 因 要 守 他 向 你 们 列 祖 所 起 的 誓 ， 就 用 大 能 的 手 领 你 们 出 来 ， 从 为 奴 之 家 救 赎 你 们 脱 离 埃 及 王 法 老 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5121', '5', '7', '9', '所 以 ， 你 要 知 道 耶 和 华 ─ ─ 你 的 神 ， 他 是 神 ， 是 信 实 的 神 ； 向 爱 他 、 守 他 诫 命 的 人 守 约 ， 施 慈 爱 ， 直 到 千 代 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5122', '5', '7', '10', '向 恨 他 的 人 当 面 报 应 他 们 ， 将 他 们 灭 绝 。 凡 恨 他 的 人 必 报 应 他 们 ， 决 不 迟 延 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5123', '5', '7', '11', '所 以 ， 你 要 谨 守 遵 行 我 今 日 所 吩 咐 你 的 诫 命 、 律 例 、 典 章 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5124', '5', '7', '12', '＜ 遵 行 诫 命 必 蒙 福 （ 申   2 8 ： 1 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5125', '5', '7', '13', '他 必 爱 你 ， 赐 福 与 你 ， 使 你 人 数 增 多 ， 也 必 在 他 向 你 列 祖 起 誓 应 许 给 你 的 地 上 赐 福 与 你 身 所 生 的 ， 地 所 产 的 ， 并 你 的 五 谷 、 新 酒 ， 和 油 ， 以 及 牛 犊 、 羊 羔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5126', '5', '7', '14', '你 必 蒙 福 胜 过 万 民 ； 你 们 的 男 女 没 有 不 能 生 养 的 ， 牲 畜 也 没 有 不 能 生 育 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5127', '5', '7', '15', '耶 和 华 必 使 一 切 的 病 症 离 开 你 ； 你 所 知 道 埃 及 各 样 的 恶 疾 ， 他 不 加 在 你 身 上 ， 只 加 在 一 切 恨 你 的 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5128', '5', '7', '16', '耶 和 华 ─ ─ 你 神 所 要 交 给 你 的 一 切 人 民 ， 你 要 将 他 们 除 灭 ； 你 眼 不 可 顾 惜 他 们 。 你 也 不 可 事 奉 他 们 的 神 ， 因 这 必 成 为 你 的 网 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5129', '5', '7', '17', '“ 你 若 心 里 说 ， 这 些 国 的 民 比 我 更 多 ， 我 怎 能 赶 出 他 们 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5130', '5', '7', '18', '你 不 要 惧 怕 他 们 ， 要 牢 牢 记 念 耶 和 华 ─ ─ 你 神 向 法 老 和 埃 及 全 地 所 行 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5131', '5', '7', '19', '就 是 你 亲 眼 所 看 见 的 大 试 验 、 神 迹 、 奇 事 ， 和 大 能 的 手 ， 并 伸 出 来 的 膀 臂 ， 都 是 耶 和 华 ─ ─ 你 神 领 你 出 来 所 用 的 。 耶 和 华 ─ ─ 你 神 必 照 样 待 你 所 惧 怕 的 一 切 人 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5132', '5', '7', '20', '并 且 耶 和 华 ─ ─ 你 神 必 打 发 黄 蜂 飞 到 他 们 中 间 ， 直 到 那 剩 下 而 藏 躲 的 人 从 你 面 前 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5133', '5', '7', '21', '你 不 要 因 他 们 惊 恐 ， 因 为 耶 和 华 ─ ─ 你 神 在 你 们 中 间 是 大 而 可 畏 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5134', '5', '7', '22', '耶 和 华 ─ ─ 你 神 必 将 这 些 国 的 民 从 你 面 前 渐 渐 赶 出 ； 你 不 可 把 他 们 速 速 灭 尽 ， 恐 怕 野 地 的 兽 多 起 来 害 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5135', '5', '7', '23', '耶 和 华 ─ ─ 你 神 必 将 他 们 交 给 你 ， 大 大 地 扰 乱 他 们 ， 直 到 他 们 灭 绝 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5136', '5', '7', '24', '又 要 将 他 们 的 君 王 交 在 你 手 中 ， 你 就 使 他 们 的 名 从 天 下 消 灭 。 必 无 一 人 能 在 你 面 前 站 立 得 住 ， 直 到 你 将 他 们 灭 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5137', '5', '7', '25', '他 们 雕 刻 的 神 像 ， 你 们 要 用 火 焚 烧 ； 其 上 的 金 银 ， 你 不 可 贪 图 ， 也 不 可 收 取 ， 免 得 你 因 此 陷 入 网 罗 ； 这 原 是 耶 和 华 ─ ─ 你 神 所 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5138', '5', '7', '26', '可 憎 的 物 ， 你 不 可 带 进 家 去 ； 不 然 ， 你 就 成 了 当 毁 灭 的 ， 与 那 物 一 样 。 你 要 十 分 厌 恶 ， 十 分 憎 嫌 ， 因 为 这 是 当 毁 灭 的 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5139', '5', '8', '1', '＜ 将 得 美 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5140', '5', '8', '2', '你 也 要 记 念 耶 和 华 ─ ─ 你 的 神 在 旷 野 引 导 你 这 四 十 年 ， 是 要 苦 炼 你 ， 试 验 你 ， 要 知 道 你 心 内 如 何 ， 肯 守 他 的 诫 命 不 肯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5141', '5', '8', '3', '他 苦 炼 你 ， 任 你 饥 饿 ， 将 你 和 你 列 祖 所 不 认 识 的 吗 哪 赐 给 你 吃 ， 使 你 知 道 ， 人 活 着 不 是 单 靠 食 物 ， 乃 是 靠 耶 和 华 口 里 所 出 的 一 切 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5142', '5', '8', '4', '这 四 十 年 ， 你 的 衣 服 没 有 穿 破 ， 你 的 脚 也 没 有 肿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5143', '5', '8', '5', '你 当 心 里 思 想 ， 耶 和 华 ─ ─ 你 神 管 教 你 ， 好 像 人 管 教 儿 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5144', '5', '8', '6', '你 要 谨 守 耶 和 华 ─ ─ 你 神 的 诫 命 ， 遵 行 他 的 道 ， 敬 畏 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5145', '5', '8', '7', '因 为 耶 和 华 ─ ─ 你 神 领 你 进 入 美 地 ， 那 地 有 河 ， 有 泉 ， 有 源 ， 从 山 谷 中 流 出 水 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5146', '5', '8', '8', '那 地 有 小 麦 、 大 麦 、 葡 萄 树 、 无 花 果 树 、 石 榴 树 、 橄 榄 树 ， 和 蜜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5147', '5', '8', '9', '你 在 那 地 不 缺 食 物 ， 一 无 所 缺 。 那 地 的 石 头 是 铁 ， 山 内 可 以 挖 铜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5148', '5', '8', '10', '你 吃 得 饱 足 ， 就 要 称 颂 耶 和 华 ─ ─ 你 的 神 ， 因 他 将 那 美 地 赐 给 你 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5149', '5', '8', '11', '＜ 警 告 人 民 不 可 忘 记 主 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5150', '5', '8', '12', '恐 怕 你 吃 得 饱 足 ， 建 造 美 好 的 房 屋 居 住 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5151', '5', '8', '13', '你 的 牛 羊 加 多 ， 你 的 金 银 增 添 ， 并 你 所 有 的 全 都 加 增 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5152', '5', '8', '14', '你 就 心 高 气 傲 ， 忘 记 耶 和 华 ─ ─ 你 的 神 ， 就 是 将 你 从 埃 及 地 为 奴 之 家 领 出 来 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5153', '5', '8', '15', '引 你 经 过 那 大 而 可 怕 的 旷 野 ， 那 里 有 火 蛇 、 蝎 子 、 干 旱 无 水 之 地 。 他 曾 为 你 使 水 从 坚 硬 的 磐 石 中 流 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5154', '5', '8', '16', '又 在 旷 野 将 你 列 祖 所 不 认 识 的 吗 哪 赐 给 你 吃 ， 是 要 苦 炼 你 ， 试 验 你 ， 叫 你 终 久 享 福 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5155', '5', '8', '17', '恐 怕 你 心 里 说 ： ‘ 这 货 财 是 我 力 量 、 我 能 力 得 来 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5156', '5', '8', '18', '你 要 记 念 耶 和 华 ─ ─ 你 的 神 ， 因 为 得 货 财 的 力 量 是 他 给 你 的 ， 为 要 坚 定 他 向 你 列 祖 起 誓 所 立 的 约 ， 像 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5157', '5', '8', '19', '你 若 忘 记 耶 和 华 ─ ─ 你 的 神 ， 随 从 别 神 ， 事 奉 敬 拜 ， 你 们 必 定 灭 亡 ； 这 是 我 今 日 警 戒 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5158', '5', '8', '20', '耶 和 华 在 你 们 面 前 怎 样 使 列 国 的 民 灭 亡 ， 你 们 也 必 照 样 灭 亡 ， 因 为 你 们 不 听 从 耶 和 华 ─ ─ 你 们 神 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5159', '5', '9', '1', '＜ 人 民 背 逆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5160', '5', '9', '2', '那 民 是 亚 衲 族 的 人 ， 又 大 又 高 ， 是 你 所 知 道 的 ； 也 曾 听 见 有 人 指 着 他 们 说 ： ‘ 谁 能 在 亚 衲 族 人 面 前 站 立 得 住 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5161', '5', '9', '3', '你 今 日 当 知 道 ， 耶 和 华 ─ ─ 你 的 神 在 你 前 面 过 去 ， 如 同 烈 火 ， 要 灭 绝 他 们 ， 将 他 们 制 伏 在 你 面 前 。 这 样 ， 你 就 要 照 耶 和 华 所 说 的 赶 出 他 们 ， 使 他 们 速 速 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5162', '5', '9', '4', '“ 耶 和 华 ─ ─ 你 的 神 将 这 些 国 民 从 你 面 前 撵 出 以 后 ， 你 心 里 不 可 说 ： ‘ 耶 和 华 将 我 领 进 来 得 这 地 是 因 我 的 义 。 ’ 其 实 ， 耶 和 华 将 他 们 从 你 面 前 赶 出 去 是 因 他 们 的 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5163', '5', '9', '5', '你 进 去 得 他 们 的 地 ， 并 不 是 因 你 的 义 ， 也 不 是 因 你 心 里 正 直 ， 乃 是 因 这 些 国 民 的 恶 ， 耶 和 华 ─ ─ 你 的 神 将 他 们 从 你 面 前 赶 出 去 ， 又 因 耶 和 华 要 坚 定 他 向 你 列 祖 亚 伯 拉 罕 、 以 撒 、 雅 各 起 誓 所 应 许 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5164', '5', '9', '6', '“ 你 当 知 道 ， 耶 和 华 ─ ─ 你 神 将 这 美 地 赐 你 为 业 ， 并 不 是 因 你 的 义 ； 你 本 是 硬 着 颈 项 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5165', '5', '9', '7', '你 当 记 念 不 忘 ， 你 在 旷 野 怎 样 惹 耶 和 华 ─ ─ 你 神 发 怒 。 自 从 你 出 了 埃 及 地 的 那 日 ， 直 到 你 们 来 到 这 地 方 ， 你 们 时 常 悖 逆 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5166', '5', '9', '8', '你 们 在 何 烈 山 又 惹 耶 和 华 发 怒 ； 他 恼 怒 你 们 ， 要 灭 绝 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5167', '5', '9', '9', '我 上 了 山 ， 要 领 受 两 块 石 版 ， 就 是 耶 和 华 与 你 们 立 约 的 版 。 那 时 我 在 山 上 住 了 四 十 昼 夜 ， 没 有 吃 饭 ， 也 没 有 喝 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5168', '5', '9', '10', '耶 和 华 把 那 两 块 石 版 交 给 我 ， 是 神 用 指 头 写 的 。 版 上 所 写 的 是 照 耶 和 华 在 大 会 的 日 子 、 在 山 上 、 从 火 中 对 你 们 所 说 的 一 切 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5169', '5', '9', '11', '过 了 四 十 昼 夜 ， 耶 和 华 把 那 两 块 石 版 ， 就 是 约 版 ， 交 给 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5170', '5', '9', '12', '对 我 说 ： ‘ 你 起 来 ， 赶 快 下 去 ！ 因 为 你 从 埃 及 领 出 来 的 百 姓 已 经 败 坏 了 自 己 ； 他 们 快 快 地 偏 离 了 我 所 吩 咐 的 道 ， 为 自 己 铸 成 了 偶 像 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5171', '5', '9', '13', '“ 耶 和 华 又 对 我 说 ： ‘ 我 看 这 百 姓 是 硬 着 颈 项 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5172', '5', '9', '14', '你 且 由 着 我 ， 我 要 灭 绝 他 们 ， 将 他 们 的 名 从 天 下 涂 抹 ， 使 你 的 后 裔 比 他 们 成 为 更 大 更 强 的 国 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5173', '5', '9', '15', '于 是 我 转 身 下 山 ， 山 被 火 烧 着 ， 两 块 约 版 在 我 两 手 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5174', '5', '9', '16', '我 一 看 见 你 们 得 罪 了 耶 和 华 ─ ─ 你 们 的 神 ， 铸 成 了 牛 犊 ， 快 快 地 偏 离 了 耶 和 华 所 吩 咐 你 们 的 道 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5175', '5', '9', '17', '我 就 把 那 两 块 版 从 我 手 中 扔 下 去 ， 在 你 们 眼 前 摔 碎 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5176', '5', '9', '18', '因 你 们 所 犯 的 一 切 罪 ， 行 了 耶 和 华 眼 中 看 为 恶 的 事 ， 惹 他 发 怒 ， 我 就 像 从 前 俯 伏 在 耶 和 华 面 前 四 十 昼 夜 ， 没 有 吃 饭 ， 也 没 有 喝 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5177', '5', '9', '19', '我 因 耶 和 华 向 你 们 大 发 烈 怒 ， 要 灭 绝 你 们 ， 就 甚 害 怕 ； 但 那 次 耶 和 华 又 应 允 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5178', '5', '9', '20', '耶 和 华 也 向 亚 伦 甚 是 发 怒 ， 要 灭 绝 他 ； 那 时 我 又 为 亚 伦 祈 祷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5179', '5', '9', '21', '我 把 那 叫 你 们 犯 罪 所 铸 的 牛 犊 用 火 焚 烧 ， 又 捣 碎 磨 得 很 细 ， 以 致 细 如 灰 尘 ， 我 就 把 这 灰 尘 撒 在 从 山 上 流 下 来 的 溪 水 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5180', '5', '9', '22', '“ 你 们 在 他 备 拉 、 玛 撒 、 基 博 罗 ． 哈 他 瓦 又 惹 耶 和 华 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5181', '5', '9', '23', '耶 和 华 打 发 你 们 离 开 加 低 斯 ． 巴 尼 亚 ， 说 ： ‘ 你 们 上 去 得 我 所 赐 给 你 们 的 地 。 ’ 那 时 你 们 违 背 了 耶 和 华 ─ ─ 你 们 神 的 命 令 ， 不 信 服 他 ， 不 听 从 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5182', '5', '9', '24', '自 从 我 认 识 你 们 以 来 ， 你 们 常 常 悖 逆 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5183', '5', '9', '25', '“ 我 因 耶 和 华 说 要 灭 绝 你 们 ， 就 在 耶 和 华 面 前 照 旧 俯 伏 四 十 昼 夜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5184', '5', '9', '26', '我 祈 祷 耶 和 华 说 ： ‘ 主 耶 和 华 啊 ， 求 你 不 要 灭 绝 你 的 百 姓 。 他 们 是 你 的 产 业 ， 是 你 用 大 力 救 赎 的 ， 用 大 能 从 埃 及 领 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5185', '5', '9', '27', '求 你 记 念 你 的 仆 人 亚 伯 拉 罕 、 以 撒 、 雅 各 ， 不 要 想 念 这 百 姓 的 顽 梗 、 邪 恶 、 罪 过 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5186', '5', '9', '28', '免 得 你 领 我 们 出 来 的 那 地 之 人 说 ， 耶 和 华 因 为 不 能 将 这 百 姓 领 进 他 所 应 许 之 地 ， 又 因 恨 他 们 ， 所 以 领 他 们 出 去 ， 要 在 旷 野 杀 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5187', '5', '9', '29', '其 实 他 们 是 你 的 百 姓 ， 你 的 产 业 ， 是 你 用 大 能 和 伸 出 来 的 膀 臂 领 出 来 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5188', '5', '10', '1', '＜ 摩 西 重 新 接 受 十 诫 （ 出   3 4 ： 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5189', '5', '10', '2', '你 先 前 摔 碎 的 那 版 ， 其 上 的 字 我 要 写 在 这 版 上 ； 你 要 将 这 版 放 在 柜 中 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5190', '5', '10', '3', '于 是 我 用 皂 荚 木 做 了 一 柜 ， 又 凿 出 两 块 石 版 ， 和 先 前 的 一 样 ， 手 里 拿 这 两 块 版 上 山 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5191', '5', '10', '4', '耶 和 华 将 那 大 会 之 日 、 在 山 上 从 火 中 所 传 与 你 们 的 十 条 诫 ， 照 先 前 所 写 的 ， 写 在 这 版 上 ， 将 版 交 给 我 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5192', '5', '10', '5', '我 转 身 下 山 ， 将 这 版 放 在 我 所 做 的 柜 中 ， 现 今 还 在 那 里 ， 正 如 耶 和 华 所 吩 咐 我 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5193', '5', '10', '6', '（ 以 色 列 人 从 比 罗 比 尼 ． 亚 干 ｛ 或 译 ： 亚 干 井 ｝ 起 行 ， 到 了 摩 西 拉 。 亚 伦 死 在 那 里 ， 就 葬 在 那 里 。 他 儿 子 以 利 亚 撒 接 续 他 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5194', '5', '10', '7', '他 们 从 那 里 起 行 ， 到 了 谷 歌 大 ， 又 从 谷 歌 大 到 了 有 溪 水 之 地 的 约 巴 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5195', '5', '10', '8', '那 时 ， 耶 和 华 将 利 未 支 派 分 别 出 来 ， 抬 耶 和 华 的 约 柜 ， 又 侍 立 在 耶 和 华 面 前 事 奉 他 ， 奉 他 的 名 祝 福 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5196', '5', '10', '9', '所 以 利 未 人 在 他 弟 兄 中 无 分 无 业 ， 耶 和 华 是 他 的 产 业 ， 正 如 耶 和 华 ─ ─ 你 神 所 应 许 他 的 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5197', '5', '10', '10', '“ 我 又 像 从 前 在 山 上 住 了 四 十 昼 夜 。 那 次 耶 和 华 也 应 允 我 ， 不 忍 将 你 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5198', '5', '10', '11', '耶 和 华 吩 咐 我 说 ： ‘ 你 起 来 引 导 这 百 姓 ， 使 他 们 进 去 得 我 向 他 们 列 祖 起 誓 应 许 所 赐 之 地 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5199', '5', '10', '12', '＜ 神 的 要 求 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5200', '5', '10', '13', '遵 守 他 的 诫 命 律 例 ， 就 是 我 今 日 所 吩 咐 你 的 ， 为 要 叫 你 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5201', '5', '10', '14', '看 哪 ， 天 和 天 上 的 天 ， 地 和 地 上 所 有 的 ， 都 属 耶 和 华 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5202', '5', '10', '15', '耶 和 华 但 喜 悦 你 的 列 祖 ， 爱 他 们 ， 从 万 民 中 拣 选 他 们 的 后 裔 ， 就 是 你 们 ， 像 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5203', '5', '10', '16', '所 以 你 们 要 将 心 里 的 污 秽 除 掉 ， 不 可 再 硬 着 颈 项 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5204', '5', '10', '17', '因 为 耶 和 华 ─ ─ 你 们 的 神 ─ ─ 他 是 万 神 之 神 ， 万 主 之 主 ， 至 大 的 神 ， 大 有 能 力 ， 大 而 可 畏 ， 不 以 貌 取 人 ， 也 不 受 贿 赂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5205', '5', '10', '18', '他 为 孤 儿 寡 妇 伸 冤 ， 又 怜 爱 寄 居 的 ， 赐 给 他 衣 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5206', '5', '10', '19', '所 以 你 们 要 怜 爱 寄 居 的 ， 因 为 你 们 在 埃 及 地 也 作 过 寄 居 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5207', '5', '10', '20', '你 要 敬 畏 耶 和 华 ─ ─ 你 的 神 ， 事 奉 他 ， 专 靠 他 ， 也 要 指 着 他 的 名 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5208', '5', '10', '21', '他 是 你 所 赞 美 的 ， 是 你 的 神 ， 为 你 做 了 那 大 而 可 畏 的 事 ， 是 你 亲 眼 所 看 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5209', '5', '10', '22', '你 的 列 祖 七 十 人 下 埃 及 ； 现 在 耶 和 华 ─ ─ 你 的 神 使 你 如 同 天 上 的 星 那 样 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5210', '5', '11', '1', '＜ 主 的 伟 大 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5211', '5', '11', '2', '你 们 今 日 当 知 道 ， 我 本 不 是 和 你 们 的 儿 女 说 话 ； 因 为 他 们 不 知 道 ， 也 没 有 看 见 耶 和 华 ─ ─ 你 们 神 的 管 教 、 威 严 、 大 能 的 手 ， 和 伸 出 来 的 膀 臂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5212', '5', '11', '3', '并 他 在 埃 及 中 向 埃 及 王 法 老 和 其 全 地 所 行 的 神 迹 奇 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5213', '5', '11', '4', '也 没 有 看 见 他 怎 样 待 埃 及 的 军 兵 、 车 马 ， 他 们 追 赶 你 们 的 时 候 ， 耶 和 华 怎 样 使 红 海 的 水 淹 没 他 们 ， 将 他 们 灭 绝 ， 直 到 今 日 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5214', '5', '11', '5', '并 他 在 旷 野 怎 样 待 你 们 ， 以 致 你 们 来 到 这 地 方 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5215', '5', '11', '6', '也 没 有 看 见 他 怎 样 待 吕 便 子 孙 以 利 押 的 儿 子 大 坍 、 亚 比 兰 ， 地 怎 样 在 以 色 列 人 中 间 开 口 ， 吞 了 他 们 和 他 们 的 家 眷 ， 并 帐 棚 与 跟 他 们 的 一 切 活 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5216', '5', '11', '7', '惟 有 你 们 亲 眼 看 见 耶 和 华 所 做 的 一 切 大 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5217', '5', '11', '8', '＜ 应 许 之 地 的 福 泽 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5218', '5', '11', '9', '并 使 你 们 的 日 子 在 耶 和 华 向 你 们 列 祖 起 誓 、 应 许 给 他 们 和 他 们 后 裔 的 地 上 得 以 长 久 ； 那 是 流 奶 与 蜜 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5219', '5', '11', '10', '你 要 进 去 得 为 业 的 那 地 ， 本 不 像 你 出 来 的 埃 及 地 。 你 在 那 里 撒 种 ， 用 脚 浇 灌 ， 像 浇 灌 菜 园 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5220', '5', '11', '11', '你 们 要 过 去 得 为 业 的 那 地 乃 是 有 山 有 谷 、 雨 水 滋 润 之 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5221', '5', '11', '12', '是 耶 和 华 ─ ─ 你 神 所 眷 顾 的 ； 从 岁 首 到 年 终 ， 耶 和 华 ─ ─ 你 神 的 眼 目 时 常 看 顾 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5222', '5', '11', '13', '“ 你 们 若 留 意 听 从 我 今 日 所 吩 咐 的 诫 命 ， 爱 耶 和 华 ─ ─ 你 们 的 神 ， 尽 心 尽 性 事 奉 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5223', '5', '11', '14', '他 ｛ 原 文 是 我 ｝ 必 按 时 降 秋 雨 春 雨 在 你 们 的 地 上 ， 使 你 们 可 以 收 藏 五 谷 、 新 酒 ， 和 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5224', '5', '11', '15', '也 必 使 你 吃 得 饱 足 ， 并 使 田 野 为 你 的 牲 畜 长 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5225', '5', '11', '16', '你 们 要 谨 慎 ， 免 得 心 中 受 迷 惑 ， 就 偏 离 正 路 ， 去 事 奉 敬 拜 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5226', '5', '11', '17', '耶 和 华 的 怒 气 向 你 们 发 作 ， 就 使 天 闭 塞 不 下 雨 ， 地 也 不 出 产 ， 使 你 们 在 耶 和 华 所 赐 给 你 们 的 美 地 上 速 速 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5227', '5', '11', '18', '“ 你 们 要 将 我 这 话 存 在 心 内 ， 留 在 意 中 ， 系 在 手 上 为 记 号 ， 戴 在 额 上 为 经 文 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5228', '5', '11', '19', '也 要 教 训 你 们 的 儿 女 ， 无 论 坐 在 家 里 ， 行 在 路 上 ， 躺 下 ， 起 来 ， 都 要 谈 论 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5229', '5', '11', '20', '又 要 写 在 房 屋 的 门 框 上 ， 并 城 门 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5230', '5', '11', '21', '使 你 们 和 你 们 子 孙 的 日 子 在 耶 和 华 向 你 们 列 祖 起 誓 、 应 许 给 他 们 的 地 上 得 以 增 多 ， 如 天 覆 地 的 日 子 那 样 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5231', '5', '11', '22', '你 们 若 留 意 谨 守 遵 行 我 所 吩 咐 这 一 切 的 诫 命 ， 爱 耶 和 华 ─ ─ 你 们 的 神 ， 行 他 的 道 ， 专 靠 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5232', '5', '11', '23', '他 必 从 你 们 面 前 赶 出 这 一 切 国 民 ， 就 是 比 你 们 更 大 更 强 的 国 民 ， 你 们 也 要 得 他 们 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5233', '5', '11', '24', '凡 你 们 脚 掌 所 踏 之 地 都 必 归 你 们 ； 从 旷 野 和 黎 巴 嫩 ， 并 幼 发 拉 底 大 河 ， 直 到 西 海 ， 都 要 作 你 们 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5234', '5', '11', '25', '必 无 一 人 能 在 你 们 面 前 站 立 得 住 ； 耶 和 华 ─ ─ 你 们 的 神 必 照 他 所 说 的 ， 使 惧 怕 惊 恐 临 到 你 们 所 踏 之 地 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5235', '5', '11', '26', '“ 看 哪 ， 我 今 日 将 祝 福 与 咒 诅 的 话 都 陈 明 在 你 们 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5236', '5', '11', '27', '你 们 若 听 从 耶 和 华 ─ ─ 你 们 神 的 诫 命 ， 就 是 我 今 日 所 吩 咐 你 们 的 ， 就 必 蒙 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5237', '5', '11', '28', '你 们 若 不 听 从 耶 和 华 ─ ─ 你 们 神 的 诫 命 ， 偏 离 我 今 日 所 吩 咐 你 们 的 道 ， 去 事 奉 你 们 素 来 所 不 认 识 的 别 神 ， 就 必 受 祸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5238', '5', '11', '29', '及 至 耶 和 华 ─ ─ 你 的 神 领 你 进 入 要 去 得 为 业 的 那 地 ， 你 就 要 将 祝 福 的 话 陈 明 在 基 利 心 山 上 ， 将 咒 诅 的 话 陈 明 在 以 巴 路 山 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5239', '5', '11', '30', '这 二 山 岂 不 是 在 约 旦 河 那 边 ， 日 落 之 处 ， 在 住 亚 拉 巴 的 迦 南 人 之 地 与 吉 甲 相 对 ， 靠 近 摩 利 橡 树 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5240', '5', '11', '31', '你 们 要 过 约 旦 河 ， 进 去 得 耶 和 华 ─ ─ 你 们 神 所 赐 你 们 为 业 之 地 ， 在 那 地 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5241', '5', '11', '32', '你 们 要 谨 守 遵 行 我 今 日 在 你 们 面 前 所 陈 明 的 一 切 律 例 典 章 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5242', '5', '12', '1', '＜ 惟 一 的 敬 拜 场 所 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5243', '5', '12', '2', '你 们 要 将 所 赶 出 的 国 民 事 奉 神 的 各 地 方 ， 无 论 是 在 高 山 ， 在 小 山 ， 在 各 青 翠 树 下 ， 都 毁 坏 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5244', '5', '12', '3', '也 要 拆 毁 他 们 的 祭 坛 ， 打 碎 他 们 的 柱 像 ， 用 火 焚 烧 他 们 的 木 偶 ， 砍 下 他 们 雕 刻 的 神 像 ， 并 将 其 名 从 那 地 方 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5245', '5', '12', '4', '你 们 不 可 照 他 们 那 样 事 奉 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5246', '5', '12', '5', '但 耶 和 华 ─ ─ 你 们 的 神 从 你 们 各 支 派 中 选 择 何 处 为 立 他 名 的 居 所 ， 你 们 就 当 往 那 里 去 求 问 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5247', '5', '12', '6', '将 你 们 的 燔 祭 、 平 安 祭 、 十 分 取 一 之 物 ， 和 手 中 的 举 祭 ， 并 还 愿 祭 、 甘 心 祭 ， 以 及 牛 群 羊 群 中 头 生 的 ， 都 奉 到 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5248', '5', '12', '7', '在 那 里 ， 耶 和 华 ─ ─ 你 们 神 的 面 前 ， 你 们 和 你 们 的 家 属 都 可 以 吃 ， 并 且 因 你 手 所 办 的 一 切 事 蒙 耶 和 华 ─ ─ 你 的 神 赐 福 ， 就 都 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5249', '5', '12', '8', '我 们 今 日 在 这 里 所 行 的 是 各 人 行 自 己 眼 中 看 为 正 的 事 ， 你 们 将 来 不 可 这 样 行 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5250', '5', '12', '9', '因 为 你 们 还 没 有 到 耶 和 华 ─ ─ 你 神 所 赐 你 的 安 息 地 ， 所 给 你 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5251', '5', '12', '10', '但 你 们 过 了 约 旦 河 ， 得 以 住 在 耶 和 华 ─ ─ 你 们 神 使 你 们 承 受 为 业 之 地 ， 又 使 你 们 太 平 ， 不 被 四 围 的 一 切 仇 敌 扰 乱 ， 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5252', '5', '12', '11', '那 时 要 将 我 所 吩 咐 你 们 的 燔 祭 、 平 安 祭 、 十 分 取 一 之 物 ， 和 手 中 的 举 祭 ， 并 向 耶 和 华 许 愿 献 的 一 切 美 祭 ， 都 奉 到 耶 和 华 ─ ─ 你 们 神 所 选 择 要 立 为 他 名 的 居 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5253', '5', '12', '12', '你 们 和 儿 女 、 仆 婢 ， 并 住 在 你 们 城 里 无 分 无 业 的 利 未 人 ， 都 要 在 耶 和 华 ─ ─ 你 们 的 神 面 前 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5254', '5', '12', '13', '你 要 谨 慎 ， 不 可 在 你 所 看 中 的 各 处 献 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5255', '5', '12', '14', '惟 独 耶 和 华 从 你 那 一 支 派 中 所 选 择 的 地 方 ， 你 就 要 在 那 里 献 燔 祭 ， 行 我 一 切 所 吩 咐 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5256', '5', '12', '15', '“ 然 而 ， 在 你 各 城 里 都 可 以 照 耶 和 华 ─ ─ 你 神 所 赐 你 的 福 分 ， 随 心 所 欲 宰 牲 吃 肉 ； 无 论 洁 净 人 不 洁 净 人 都 可 以 吃 ， 就 如 吃 羚 羊 与 鹿 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5257', '5', '12', '16', '只 是 不 可 吃 血 ， 要 倒 在 地 上 ， 如 同 倒 水 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5258', '5', '12', '17', '你 的 五 谷 、 新 酒 ， 和 油 的 十 分 之 一 ， 或 是 牛 群 羊 群 中 头 生 的 ， 或 是 你 许 愿 献 的 ， 甘 心 献 的 ， 或 是 手 中 的 举 祭 ， 都 不 可 在 你 城 里 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5259', '5', '12', '18', '但 要 在 耶 和 华 ─ ─ 你 的 神 面 前 吃 ， 在 耶 和 华 ─ ─ 你 神 所 要 选 择 的 地 方 ， 你 和 儿 女 、 仆 婢 ， 并 住 在 你 城 里 的 利 未 人 ， 都 可 以 吃 ； 也 要 因 你 手 所 办 的 ， 在 耶 和 华 ─ ─ 你 神 面 前 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5260', '5', '12', '19', '你 要 谨 慎 ， 在 你 所 住 的 地 方 永 不 可 丢 弃 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5261', '5', '12', '20', '“ 耶 和 华 ─ ─ 你 的 神 照 他 所 应 许 扩 张 你 境 界 的 时 候 ， 你 心 里 想 要 吃 肉 ， 说 ： ‘ 我 要 吃 肉 ’ ， 就 可 以 随 心 所 欲 地 吃 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5262', '5', '12', '21', '耶 和 华 ─ ─ 你 神 所 选 择 要 立 他 名 的 地 方 若 离 你 太 远 ， 就 可 以 照 我 所 吩 咐 的 ， 将 耶 和 华 赐 给 你 的 牛 羊 取 些 宰 了 ， 可 以 随 心 所 欲 在 你 城 里 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5263', '5', '12', '22', '你 吃 那 肉 ， 要 像 吃 羚 羊 与 鹿 一 般 ； 无 论 洁 净 人 不 洁 净 人 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5264', '5', '12', '23', '只 是 你 要 心 意 坚 定 ， 不 可 吃 血 ， 因 为 血 是 生 命 ； 不 可 将 血 ｛ 原 文 是 生 命 ｝ 与 肉 同 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5265', '5', '12', '24', '不 可 吃 血 ， 要 倒 在 地 上 ， 如 同 倒 水 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5266', '5', '12', '25', '不 可 吃 血 。 这 样 ， 你 行 耶 和 华 眼 中 看 为 正 的 事 ， 你 和 你 的 子 孙 就 可 以 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5267', '5', '12', '26', '只 是 你 分 别 为 圣 的 物 和 你 的 还 愿 祭 要 奉 到 耶 和 华 所 选 择 的 地 方 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5268', '5', '12', '27', '你 的 燔 祭 ， 连 肉 带 血 ， 都 要 献 在 耶 和 华 ─ ─ 你 神 的 坛 上 。 平 安 祭 的 血 要 倒 在 耶 和 华 ─ ─ 你 神 的 坛 上 ； 平 安 祭 的 肉 ， 你 自 己 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5269', '5', '12', '28', '你 要 谨 守 听 从 我 所 吩 咐 的 一 切 话 ， 行 耶 和 华 ─ ─ 你 神 眼 中 看 为 善 ， 看 为 正 的 事 。 这 样 ， 你 和 你 的 子 孙 就 可 以 永 远 享 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5270', '5', '12', '29', '＜ 警 告 不 可 拜 偶 像 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5271', '5', '12', '30', '那 时 就 要 谨 慎 ， 不 可 在 他 们 除 灭 之 后 随 从 他 们 的 恶 俗 ， 陷 入 网 罗 ， 也 不 可 访 问 他 们 的 神 说 ： ‘ 这 些 国 民 怎 样 事 奉 他 们 的 神 ， 我 也 要 照 样 行 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5272', '5', '12', '31', '你 不 可 向 耶 和 华 ─ ─ 你 的 神 这 样 行 ， 因 为 他 们 向 他 们 的 神 行 了 耶 和 华 所 憎 嫌 所 恨 恶 的 一 切 事 ， 甚 至 将 自 己 的 儿 女 用 火 焚 烧 ， 献 与 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5273', '5', '12', '32', '凡 我 所 吩 咐 的 ， 你 们 都 要 谨 守 遵 行 ， 不 可 加 添 ， 也 不 可 删 减 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5274', '5', '13', '1', '“ 你 们 中 间 若 有 先 知 或 是 做 梦 的 起 来 ， 向 你 显 个 神 迹 奇 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5275', '5', '13', '2', '对 你 说 ： ‘ 我 们 去 随 从 你 素 来 所 不 认 识 的 别 神 ， 事 奉 它 吧 。 ’ 他 所 显 的 神 迹 奇 事 虽 有 应 验 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5276', '5', '13', '3', '你 也 不 可 听 那 先 知 或 是 那 做 梦 之 人 的 话 ； 因 为 这 是 耶 和 华 ─ ─ 你 们 的 神 试 验 你 们 ， 要 知 道 你 们 是 尽 心 尽 性 爱 耶 和 华 ─ ─ 你 们 的 神 不 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5277', '5', '13', '4', '你 们 要 顺 从 耶 和 华 ─ ─ 你 们 的 神 ， 敬 畏 他 ， 谨 守 他 的 诫 命 ， 听 从 他 的 话 ， 事 奉 他 ， 专 靠 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5278', '5', '13', '5', '那 先 知 或 是 那 做 梦 的 既 用 言 语 叛 逆 那 领 你 们 出 埃 及 地 、 救 赎 你 脱 离 为 奴 之 家 的 耶 和 华 ─ ─ 你 们 的 神 ， 要 勾 引 你 离 开 耶 和 华 ─ ─ 你 神 所 吩 咐 你 行 的 道 ， 你 便 要 将 他 治 死 。 这 样 ， 就 把 那 恶 从 你 们 中 间 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5279', '5', '13', '6', '“ 你 的 同 胞 弟 兄 ， 或 是 你 的 儿 女 ， 或 是 你 怀 中 的 妻 ， 或 是 如 同 你 性 命 的 朋 友 ， 若 暗 中 引 诱 你 ， 说 ： ‘ 我 们 不 如 去 事 奉 你 和 你 列 祖 素 来 所 不 认 识 的 别 神 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5280', '5', '13', '7', '是 你 四 围 列 国 的 神 。 ’ 无 论 是 离 你 近 ， 离 你 远 ， 从 地 这 边 到 地 那 边 的 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5281', '5', '13', '8', '你 不 可 依 从 他 ， 也 不 可 听 从 他 ， 眼 不 可 顾 惜 他 。 你 不 可 怜 恤 他 ， 也 不 可 遮 庇 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5282', '5', '13', '9', '总 要 杀 他 ； 你 先 下 手 ， 然 后 众 民 也 下 手 ， 将 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5283', '5', '13', '10', '要 用 石 头 打 死 他 ， 因 为 他 想 要 勾 引 你 离 开 那 领 你 出 埃 及 地 为 奴 之 家 的 耶 和 华 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5284', '5', '13', '11', '以 色 列 众 人 都 要 听 见 害 怕 ， 就 不 敢 在 你 们 中 间 再 行 这 样 的 恶 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5285', '5', '13', '12', '“ 在 耶 和 华 ─ ─ 你 神 所 赐 你 居 住 的 各 城 中 ， 你 若 听 人 说 ， 有 些 匪 类 从 你 们 中 间 的 一 座 城 出 来 勾 引 本 城 的 居 民 ， 说 ： ‘ 我 们 不 如 去 事 奉 你 们 素 来 所 不 认 识 的 别 神 ’ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5286', '5', '13', '13', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5287', '5', '13', '14', '你 就 要 探 听 ， 查 究 ， 细 细 地 访 问 ， 果 然 是 真 ， 准 有 这 可 憎 恶 的 事 行 在 你 们 中 间 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5288', '5', '13', '15', '你 必 要 用 刀 杀 那 城 里 的 居 民 ， 把 城 里 所 有 的 ， 连 牲 畜 ， 都 用 刀 杀 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5289', '5', '13', '16', '你 从 那 城 里 所 夺 的 财 物 都 要 堆 积 在 街 市 上 ， 用 火 将 城 和 其 内 所 夺 的 财 物 都 在 耶 和 华 ─ ─ 你 神 面 前 烧 尽 ； 那 城 就 永 为 荒 堆 ， 不 可 再 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5290', '5', '13', '17', '那 当 毁 灭 的 物 连 一 点 都 不 可 粘 你 的 手 。 你 要 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 遵 守 我 今 日 所 吩 咐 你 的 一 切 诫 命 ， 行 耶 和 华 ─ ─ 你 神 眼 中 看 为 正 的 事 ， 耶 和 华 就 必 转 意 ， 不 发 烈 怒 ， 恩 待 你 ， 怜 恤 你 ， 照 他 向 你 列 祖 所 起 的 誓 使 你 人 数 增 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5291', '5', '13', '18', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5292', '5', '14', '1', '＜ 举 哀 时 的 禁 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5293', '5', '14', '2', '因 为 你 归 耶 和 华 ─ ─ 你 神 为 圣 洁 的 民 ， 耶 和 华 从 地 上 的 万 民 中 拣 选 你 特 作 自 己 的 子 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5294', '5', '14', '3', '＜ 洁 净 和 不 洁 净 的 动 物 （ 利   1 1 ： 1 - 4 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5295', '5', '14', '4', '可 吃 的 牲 畜 就 是 牛 、 绵 羊 、 山 羊 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5296', '5', '14', '5', '鹿 、 羚 羊 、 麃 子 、 野 山 羊 、 麋 鹿 、 黄 羊 、 青 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5297', '5', '14', '6', '凡 分 蹄 成 为 两 瓣 又 倒 嚼 的 走 兽 ， 你 们 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5298', '5', '14', '7', '但 那 些 倒 嚼 或 是 分 蹄 之 中 不 可 吃 的 乃 是 骆 驼 、 兔 子 、 沙 番 ─ ─ 因 为 是 倒 嚼 不 分 蹄 ， 就 与 你 们 不 洁 净 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5299', '5', '14', '8', '猪 ─ ─ 因 为 是 分 蹄 却 不 倒 嚼 ， 就 与 你 们 不 洁 净 。 这 些 兽 的 肉 ， 你 们 不 可 吃 ， 死 的 也 不 可 摸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5300', '5', '14', '9', '“ 水 中 可 吃 的 乃 是 这 些 ： 凡 有 翅 有 鳞 的 都 可 以 吃 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5301', '5', '14', '10', '凡 无 翅 无 鳞 的 都 不 可 吃 ， 是 与 你 们 不 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5302', '5', '14', '11', '“ 凡 洁 净 的 鸟 ， 你 们 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5303', '5', '14', '12', '不 可 吃 的 乃 是 雕 、 狗 头 雕 、 红 头 雕 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5304', '5', '14', '13', '鹯 、 小 鹰 、 鹞 鹰 与 其 类 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5305', '5', '14', '14', '乌 鸦 与 其 类 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5306', '5', '14', '15', '鸵 鸟 、 夜 鹰 、 鱼 鹰 、 鹰 与 其 类 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5307', '5', '14', '16', '鸮 鸟 、 猫 头 鹰 、 角 鸱 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5308', '5', '14', '17', '鹈 鹕 、 秃 雕 、 鸬 鹚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5309', '5', '14', '18', '鹳 、 鹭 鸶 与 其 类 ， 戴 鵀 与 蝙 蝠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5310', '5', '14', '19', '凡 有 翅 膀 爬 行 的 物 是 与 你 们 不 洁 净 ， 都 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5311', '5', '14', '20', '凡 洁 净 的 鸟 ， 你 们 都 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5312', '5', '14', '21', '“ 凡 自 死 的 ， 你 们 都 不 可 吃 ， 可 以 给 你 城 里 寄 居 的 吃 ， 或 卖 与 外 人 吃 ， 因 为 你 是 归 耶 和 华 ─ ─ 你 神 为 圣 洁 的 民 。 “ 不 可 用 山 羊 羔 母 的 奶 煮 山 羊 羔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5313', '5', '14', '22', '＜ 十 分 献 一 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5314', '5', '14', '23', '又 要 把 你 的 五 谷 、 新 酒 、 和 油 的 十 分 之 一 ， 并 牛 群 羊 群 中 头 生 的 ， 吃 在 耶 和 华 ─ ─ 你 神 面 前 ， 就 是 他 所 选 择 要 立 为 他 名 的 居 所 。 这 样 ， 你 可 以 学 习 时 常 敬 畏 耶 和 华 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5315', '5', '14', '24', '当 耶 和 华 ─ ─ 你 神 赐 福 与 你 的 时 候 ， 耶 和 华 ─ ─ 你 神 所 选 择 要 立 为 他 名 的 地 方 若 离 你 太 远 ， 那 路 也 太 长 ， 使 你 不 能 把 这 物 带 到 那 里 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5316', '5', '14', '25', '你 就 可 以 换 成 银 子 ， 将 银 子 包 起 来 ， 拿 在 手 中 ， 往 耶 和 华 ─ ─ 你 神 所 要 选 择 的 地 方 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5317', '5', '14', '26', '你 用 这 银 子 ， 随 心 所 欲 ， 或 买 牛 羊 ， 或 买 清 酒 浓 酒 ， 凡 你 心 所 想 的 都 可 以 买 ； 你 和 你 的 家 属 在 耶 和 华 ─ ─ 你 神 的 面 前 吃 喝 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5318', '5', '14', '27', '“ 住 在 你 城 里 的 利 未 人 ， 你 不 可 丢 弃 他 ， 因 为 他 在 你 们 中 间 无 分 无 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5319', '5', '14', '28', '每 逢 三 年 的 末 一 年 ， 你 要 将 本 年 的 土 产 十 分 之 一 都 取 出 来 ， 积 存 在 你 的 城 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5320', '5', '14', '29', '在 你 城 里 无 分 无 业 的 利 未 人 ， 和 你 城 里 寄 居 的 ， 并 孤 儿 寡 妇 ， 都 可 以 来 ， 吃 得 饱 足 。 这 样 ， 耶 和 华 ─ ─ 你 的 神 必 在 你 手 里 所 办 的 一 切 事 上 赐 福 与 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5321', '5', '15', '1', '＜ 安 息 年 （ 利   2 5 ： 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5322', '5', '15', '2', '豁 免 的 定 例 乃 是 这 样 ： 凡 债 主 要 把 所 借 给 邻 舍 的 豁 免 了 ； 不 可 向 邻 舍 和 弟 兄 追 讨 ， 因 为 耶 和 华 的 豁 免 年 已 经 宣 告 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5323', '5', '15', '3', '若 借 给 外 邦 人 ， 你 可 以 向 他 追 讨 ； 但 借 给 你 弟 兄 ， 无 论 是 什 么 ， 你 要 松 手 豁 免 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5324', '5', '15', '4', '你 若 留 意 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 谨 守 遵 行 我 今 日 所 吩 咐 你 这 一 切 的 命 令 ， 就 必 在 你 们 中 间 没 有 穷 人 了 （ 在 耶 和 华 ─ ─ 你 神 所 赐 你 为 业 的 地 上 ， 耶 和 华 必 大 大 赐 福 与 你 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5325', '5', '15', '5', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5326', '5', '15', '6', '因 为 耶 和 华 ─ ─ 你 的 神 必 照 他 所 应 许 你 的 赐 福 与 你 。 你 必 借 给 许 多 国 民 ， 却 不 致 向 他 们 借 贷 ； 你 必 管 辖 许 多 国 民 ， 他 们 却 不 能 管 辖 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5327', '5', '15', '7', '“ 在 耶 和 华 ─ ─ 你 神 所 赐 你 的 地 上 ， 无 论 哪 一 座 城 里 ， 你 弟 兄 中 若 有 一 个 穷 人 ， 你 不 可 忍 着 心 、 揝 着 手 不 帮 补 你 穷 乏 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5328', '5', '15', '8', '总 要 向 他 松 开 手 ， 照 他 所 缺 乏 的 借 给 他 ， 补 他 的 不 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5329', '5', '15', '9', '你 要 谨 慎 ， 不 可 心 里 起 恶 念 ， 说 ： ‘ 第 七 年 的 豁 免 年 快 到 了 ’ ， 你 便 恶 眼 看 你 穷 乏 的 弟 兄 ， 什 么 都 不 给 他 ， 以 致 他 因 你 求 告 耶 和 华 ， 罪 便 归 于 你 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5330', '5', '15', '10', '你 总 要 给 他 ， 给 他 的 时 候 心 里 不 可 愁 烦 ； 因 耶 和 华 ─ ─ 你 的 神 必 在 你 这 一 切 所 行 的 ， 并 你 手 里 所 办 的 事 上 ， 赐 福 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5331', '5', '15', '11', '原 来 那 地 上 的 穷 人 永 不 断 绝 ； 所 以 我 吩 咐 你 说 ： ‘ 总 要 向 你 地 上 困 苦 穷 乏 的 弟 兄 松 开 手 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5332', '5', '15', '12', '＜ 对 待 奴 婢 的 条 例 （ 出   2 1 : 1 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5333', '5', '15', '13', '你 任 他 自 由 的 时 候 ， 不 可 使 他 空 手 而 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5334', '5', '15', '14', '要 从 你 羊 群 、 禾 场 、 酒 醡 之 中 多 多 地 给 他 ； 耶 和 华 ─ ─ 你 的 神 怎 样 赐 福 与 你 ， 你 也 要 照 样 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5335', '5', '15', '15', '要 记 念 你 在 埃 及 地 作 过 奴 仆 ， 耶 和 华 ─ ─ 你 的 神 将 你 救 赎 ； 因 此 ， 我 今 日 吩 咐 你 这 件 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5336', '5', '15', '16', '他 若 对 你 说 ： ‘ 我 不 愿 意 离 开 你 ’ ， 是 因 他 爱 你 和 你 的 家 ， 且 因 在 你 那 里 很 好 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5337', '5', '15', '17', '你 就 要 拿 锥 子 将 他 的 耳 朵 在 门 上 刺 透 ， 他 便 永 为 你 的 奴 仆 了 。 你 待 婢 女 也 要 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5338', '5', '15', '18', '你 任 他 自 由 的 时 候 ， 不 可 以 为 难 事 ， 因 他 服 事 你 六 年 ， 较 比 雇 工 的 工 价 多 加 一 倍 了 。 耶 和 华 ─ ─ 你 的 神 就 必 在 你 所 做 的 一 切 事 上 赐 福 与 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5339', '5', '15', '19', '＜ 头 生 牛 羊 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5340', '5', '15', '20', '这 头 生 的 ， 你 和 你 的 家 属 ， 每 年 要 在 耶 和 华 所 选 择 的 地 方 ， 在 耶 和 华 ─ ─ 你 神 面 前 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5341', '5', '15', '21', '这 头 生 的 若 有 什 么 残 疾 ， 就 如 瘸 腿 的 、 瞎 眼 的 ， 无 论 有 什 么 恶 残 疾 ， 都 不 可 献 给 耶 和 华 ─ ─ 你 的 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5342', '5', '15', '22', '可 以 在 你 城 里 吃 ； 洁 净 人 与 不 洁 净 人 都 可 以 吃 ， 就 如 吃 羚 羊 与 鹿 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5343', '5', '15', '23', '只 是 不 可 吃 它 的 血 ； 要 倒 在 地 上 ， 如 同 倒 水 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5344', '5', '16', '1', '＜ 逾 越 节 （ 出   1 2 ： 1 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5345', '5', '16', '2', '你 当 在 耶 和 华 所 选 择 要 立 为 他 名 的 居 所 ， 从 牛 群 羊 群 中 ， 将 逾 越 节 的 祭 牲 献 给 耶 和 华 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5346', '5', '16', '3', '你 吃 这 祭 牲 ， 不 可 吃 有 酵 的 饼 ； 七 日 之 内 要 吃 无 酵 饼 ， 就 是 困 苦 饼 ─ ─ 你 本 是 急 忙 出 了 埃 及 地 ─ ─ 要 叫 你 一 生 一 世 记 念 你 从 埃 及 地 出 来 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5347', '5', '16', '4', '在 你 四 境 之 内 ， 七 日 不 可 见 面 酵 ， 头 一 日 晚 上 所 献 的 肉 ， 一 点 不 可 留 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5348', '5', '16', '5', '在 耶 和 华 ─ ─ 你 神 所 赐 的 各 城 中 ， 你 不 可 献 逾 越 节 的 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5349', '5', '16', '6', '只 当 在 耶 和 华 ─ ─ 你 神 所 选 择 要 立 为 他 名 的 居 所 ， 晚 上 日 落 的 时 候 ， 乃 是 你 出 埃 及 的 时 候 ， 献 逾 越 节 的 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5350', '5', '16', '7', '当 在 耶 和 华 ─ ─ 你 神 所 选 择 的 地 方 把 肉 烤 了 吃 ｛ 烤 ： 或 译 煮 ｝ ， 次 日 早 晨 就 回 到 你 的 帐 棚 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5351', '5', '16', '8', '你 要 吃 无 酵 饼 六 日 ， 第 七 日 要 向 耶 和 华 ─ ─ 你 的 神 守 严 肃 会 ， 不 可 做 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5352', '5', '16', '9', '＜ 七 七 收 获 节 （ 出   3 4 ： 2 2 ； 利   2 3 ： 1 5 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5353', '5', '16', '10', '你 要 照 耶 和 华 ─ ─ 你 神 所 赐 你 的 福 ， 手 里 拿 着 甘 心 祭 ， 献 在 耶 和 华 ─ ─ 你 的 神 面 前 ， 守 七 七 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5354', '5', '16', '11', '你 和 你 儿 女 、 仆 婢 ， 并 住 在 你 城 里 的 利 未 人 ， 以 及 在 你 们 中 间 寄 居 的 与 孤 儿 寡 妇 ， 都 要 在 耶 和 华 ─ ─ 你 神 所 选 择 立 为 他 名 的 居 所 ， 在 耶 和 华 ─ ─ 你 的 神 面 前 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5355', '5', '16', '12', '你 也 要 记 念 你 在 埃 及 作 过 奴 仆 。 你 要 谨 守 遵 行 这 些 律 例 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5356', '5', '16', '13', '＜ 住 棚 节 （ 利   2 3 ： 3 3 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5357', '5', '16', '14', '守 节 的 时 候 ， 你 和 你 儿 女 、 仆 婢 ， 并 住 在 你 城 里 的 利 未 人 ， 以 及 寄 居 的 与 孤 儿 寡 妇 ， 都 要 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5358', '5', '16', '15', '在 耶 和 华 所 选 择 的 地 方 ， 你 当 向 耶 和 华 ─ ─ 你 的 神 守 节 七 日 ； 因 为 耶 和 华 ─ ─ 你 神 在 你 一 切 的 土 产 上 和 你 手 里 所 办 的 事 上 要 赐 福 与 你 ， 你 就 非 常 地 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5359', '5', '16', '16', '你 一 切 的 男 丁 要 在 除 酵 节 、 七 七 节 、 住 棚 节 ， 一 年 三 次 ， 在 耶 和 华 ─ ─ 你 神 所 选 择 的 地 方 朝 见 他 ， 却 不 可 空 手 朝 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5360', '5', '16', '17', '各 人 要 按 自 己 的 力 量 ， 照 耶 和 华 ─ ─ 你 神 所 赐 的 福 分 ， 奉 献 礼 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5361', '5', '16', '18', '＜ 秉 公 审 断 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5362', '5', '16', '19', '不 可 屈 枉 正 直 ； 不 可 看 人 的 外 貌 。 也 不 可 受 贿 赂 ； 因 为 贿 赂 能 叫 智 慧 人 的 眼 变 瞎 了 ， 又 能 颠 倒 义 人 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5363', '5', '16', '20', '你 要 追 求 至 公 至 义 ， 好 叫 你 存 活 ， 承 受 耶 和 华 ─ ─ 你 神 所 赐 你 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5364', '5', '16', '21', '“ 你 为 耶 和 华 ─ ─ 你 的 神 筑 坛 ， 不 可 在 坛 旁 栽 什 么 树 木 作 为 木 偶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5365', '5', '16', '22', '也 不 可 为 自 己 设 立 柱 像 ； 这 是 耶 和 华 ─ ─ 你 神 所 恨 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5366', '5', '17', '1', '“ 凡 有 残 疾 ， 或 有 什 么 恶 病 的 牛 羊 ， 你 都 不 可 献 给 耶 和 华 ─ ─ 你 的 神 ， 因 为 这 是 耶 和 华 ─ ─ 你 神 所 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5367', '5', '17', '2', '“ 在 你 们 中 间 ， 在 耶 和 华 ─ ─ 你 神 所 赐 你 的 诸 城 中 ， 无 论 哪 座 城 里 ， 若 有 人 ， 或 男 或 女 ， 行 耶 和 华 ─ ─ 你 神 眼 中 看 为 恶 的 事 ， 违 背 了 他 的 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5368', '5', '17', '3', '去 事 奉 敬 拜 别 神 ， 或 拜 日 头 ， 或 拜 月 亮 ， 或 拜 天 象 ， 是 主 不 曾 吩 咐 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5369', '5', '17', '4', '有 人 告 诉 你 ， 你 也 听 见 了 ， 就 要 细 细 地 探 听 ， 果 然 是 真 ， 准 有 这 可 憎 恶 的 事 行 在 以 色 列 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5370', '5', '17', '5', '你 就 要 将 行 这 恶 事 的 男 人 或 女 人 拉 到 城 门 外 ， 用 石 头 将 他 打 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5371', '5', '17', '6', '要 凭 两 三 个 人 的 口 作 见 证 将 那 当 死 的 人 治 死 ； 不 可 凭 一 个 人 的 口 作 见 证 将 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5372', '5', '17', '7', '见 证 人 要 先 下 手 ， 然 后 众 民 也 下 手 将 他 治 死 。 这 样 ， 就 把 那 恶 从 你 们 中 间 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5373', '5', '17', '8', '“ 你 城 中 若 起 了 争 讼 的 事 ， 或 因 流 血 ， 或 因 争 竞 ， 或 因 殴 打 ， 是 你 难 断 的 案 件 ， 你 就 当 起 来 ， 往 耶 和 华 ─ ─ 你 神 所 选 择 的 地 方');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5374', '5', '17', '9', '去 见 祭 司 利 未 人 ， 并 当 时 的 审 判 官 ， 求 问 他 们 ， 他 们 必 将 判 语 指 示 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5375', '5', '17', '10', '他 们 在 耶 和 华 所 选 择 的 地 方 指 示 你 的 判 语 ， 你 必 照 着 他 们 所 指 教 你 的 一 切 话 谨 守 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5376', '5', '17', '11', '要 按 他 们 所 指 教 你 的 律 法 ， 照 他 们 所 断 定 的 去 行 ； 他 们 所 指 示 你 的 判 语 ， 你 不 可 偏 离 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5377', '5', '17', '12', '若 有 人 擅 敢 不 听 从 那 侍 立 在 耶 和 华 ─ ─ 你 神 面 前 的 祭 司 ， 或 不 听 从 审 判 官 ， 那 人 就 必 治 死 ； 这 样 ， 便 将 那 恶 从 以 色 列 中 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5378', '5', '17', '13', '众 百 姓 都 要 听 见 害 怕 ， 不 再 擅 敢 行 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5379', '5', '17', '14', '＜ 有 关 立 王 的 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5380', '5', '17', '15', '你 总 要 立 耶 和 华 ─ ─ 你 神 所 拣 选 的 人 为 王 。 必 从 你 弟 兄 中 立 一 人 ； 不 可 立 你 弟 兄 以 外 的 人 为 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5381', '5', '17', '16', '只 是 王 不 可 为 自 己 加 添 马 匹 ， 也 不 可 使 百 姓 回 埃 及 去 ， 为 要 加 添 他 的 马 匹 ， 因 耶 和 华 曾 吩 咐 你 们 说 ： ‘ 不 可 再 回 那 条 路 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5382', '5', '17', '17', '他 也 不 可 为 自 己 多 立 妃 嫔 ， 恐 怕 他 的 心 偏 邪 ； 也 不 可 为 自 己 多 积 金 银 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5383', '5', '17', '18', '他 登 了 国 位 ， 就 要 将 祭 司 利 未 人 面 前 的 这 律 法 书 ， 为 自 己 抄 录 一 本 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5384', '5', '17', '19', '存 在 他 那 里 ， 要 平 生 诵 读 ， 好 学 习 敬 畏 耶 和 华 ─ ─ 他 的 神 ， 谨 守 遵 行 这 律 法 书 上 的 一 切 言 语 和 这 些 律 例 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5385', '5', '17', '20', '免 得 他 向 弟 兄 心 高 气 傲 ， 偏 左 偏 右 ， 离 了 这 诫 命 。 这 样 ， 他 和 他 的 子 孙 便 可 在 以 色 列 中 ， 在 国 位 上 年 长 日 久 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5386', '5', '18', '1', '＜ 祭 司 当 得 的 分 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5387', '5', '18', '2', '他 们 在 弟 兄 中 必 没 有 产 业 ； 耶 和 华 是 他 们 的 产 业 ， 正 如 耶 和 华 所 应 许 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5388', '5', '18', '3', '祭 司 从 百 姓 所 当 得 的 分 乃 是 这 样 ： 凡 献 牛 或 羊 为 祭 的 ， 要 把 前 腿 和 两 腮 并 脾 胃 给 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5389', '5', '18', '4', '初 收 的 五 谷 、 新 酒 和 油 ， 并 初 剪 的 羊 毛 ， 也 要 给 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5390', '5', '18', '5', '因 为 耶 和 华 ─ ─ 你 的 神 从 你 各 支 派 中 将 他 拣 选 出 来 ， 使 他 和 他 子 孙 永 远 奉 耶 和 华 的 名 侍 立 ， 事 奉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5391', '5', '18', '6', '“ 利 未 人 无 论 寄 居 在 以 色 列 中 的 哪 一 座 城 ， 若 从 那 里 出 来 ， 一 心 愿 意 到 耶 和 华 所 选 择 的 地 方 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5392', '5', '18', '7', '就 要 奉 耶 和 华 ─ ─ 他 神 的 名 事 奉 ， 像 他 众 弟 兄 利 未 人 侍 立 在 耶 和 华 面 前 事 奉 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5393', '5', '18', '8', '除 了 他 卖 祖 父 产 业 所 得 的 以 外 ， 还 要 得 一 分 祭 物 与 他 们 同 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5394', '5', '18', '9', '＜ 不 可 随 从 异 邦 的 恶 俗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5395', '5', '18', '10', '你 们 中 间 不 可 有 人 使 儿 女 经 火 ， 也 不 可 有 占 卜 的 、 观 兆 的 、 用 法 术 的 、 行 邪 术 的 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5396', '5', '18', '11', '用 迷 术 的 、 交 鬼 的 、 行 巫 术 的 、 过 阴 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5397', '5', '18', '12', '凡 行 这 些 事 的 都 为 耶 和 华 所 憎 恶 ； 因 那 些 国 民 行 这 可 憎 恶 的 事 ， 所 以 耶 和 华 ─ ─ 你 的 神 将 他 们 从 你 面 前 赶 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5398', '5', '18', '13', '你 要 在 耶 和 华 ─ ─ 你 的 神 面 前 作 完 全 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5399', '5', '18', '14', '＜ 应 许 兴 起 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5400', '5', '18', '15', '耶 和 华 ─ ─ 你 的 神 要 从 你 们 弟 兄 中 间 给 你 兴 起 一 位 先 知 ， 像 我 ， 你 们 要 听 从 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5401', '5', '18', '16', '正 如 你 在 何 烈 山 大 会 的 日 子 求 耶 和 华 ─ ─ 你 神 一 切 的 话 ， 说 ： ‘ 求 你 不 再 叫 我 听 见 耶 和 华 ─ ─ 我 神 的 声 音 ， 也 不 再 叫 我 看 见 这 大 火 ， 免 得 我 死 亡 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5402', '5', '18', '17', '耶 和 华 就 对 我 说 ： ‘ 他 们 所 说 的 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5403', '5', '18', '18', '我 必 在 他 们 弟 兄 中 间 给 他 们 兴 起 一 位 先 知 ， 像 你 。 我 要 将 当 说 的 话 传 给 他 ； 他 要 将 我 一 切 所 吩 咐 的 都 传 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5404', '5', '18', '19', '谁 不 听 他 奉 我 名 所 说 的 话 ， 我 必 讨 谁 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5405', '5', '18', '20', '若 有 先 知 擅 敢 托 我 的 名 说 我 所 未 曾 吩 咐 他 说 的 话 ， 或 是 奉 别 神 的 名 说 话 ， 那 先 知 就 必 治 死 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5406', '5', '18', '21', '你 心 里 若 说 ： ‘ 耶 和 华 所 未 曾 吩 咐 的 话 ， 我 们 怎 能 知 道 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5407', '5', '18', '22', '先 知 托 耶 和 华 的 名 说 话 ， 所 说 的 若 不 成 就 ， 也 无 效 验 ， 这 就 是 耶 和 华 所 未 曾 吩 咐 的 ， 是 那 先 知 擅 自 说 的 ， 你 不 要 怕 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5408', '5', '19', '1', '＜ 设 立 庇 护 城 （ 民   3 5 : 9 - 2 8 ； 书   2 0 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5409', '5', '19', '2', '就 要 在 耶 和 华 ─ ─ 你 神 所 赐 你 为 业 的 地 上 分 定 三 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5410', '5', '19', '3', '要 将 耶 和 华 ─ ─ 你 神 使 你 承 受 为 业 的 地 分 为 三 段 ； 又 要 预 备 道 路 ， 使 误 杀 人 的 ， 都 可 以 逃 到 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5411', '5', '19', '4', '“ 误 杀 人 的 逃 到 那 里 可 以 存 活 ， 定 例 乃 是 这 样 ： 凡 素 无 仇 恨 ， 无 心 杀 了 人 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5412', '5', '19', '5', '就 如 人 与 邻 舍 同 入 树 林 砍 伐 树 木 ， 手 拿 斧 子 一 砍 ， 本 想 砍 下 树 木 ， 不 料 ， 斧 头 脱 了 把 ， 飞 落 在 邻 舍 身 上 ， 以 致 于 死 ， 这 人 逃 到 那 些 城 的 一 座 城 ， 就 可 以 存 活 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5413', '5', '19', '6', '免 得 报 血 仇 的 ， 心 中 火 热 追 赶 他 ， 因 路 远 就 追 上 ， 将 他 杀 死 ； 其 实 他 不 该 死 ， 因 为 他 与 被 杀 的 素 无 仇 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5414', '5', '19', '7', '所 以 我 吩 咐 你 说 ， 要 分 定 三 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5415', '5', '19', '8', '耶 和 华 ─ ─ 你 神 若 照 他 向 你 列 祖 所 起 的 誓 扩 张 你 的 境 界 ， 将 所 应 许 赐 你 列 祖 的 地 全 然 给 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5416', '5', '19', '9', '你 若 谨 守 遵 行 我 今 日 所 吩 咐 的 这 一 切 诫 命 ， 爱 耶 和 华 ─ ─ 你 的 神 ， 常 常 遵 行 他 的 道 ， 就 要 在 这 三 座 城 之 外 ， 再 添 三 座 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5417', '5', '19', '10', '免 得 无 辜 之 人 的 血 流 在 耶 和 华 ─ ─ 你 神 所 赐 你 为 业 的 地 上 ， 流 血 的 罪 就 归 于 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5418', '5', '19', '11', '“ 若 有 人 恨 他 的 邻 舍 ， 埋 伏 着 起 来 击 杀 他 ， 以 致 于 死 ， 便 逃 到 这 些 城 的 一 座 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5419', '5', '19', '12', '本 城 的 长 老 就 要 打 发 人 去 ， 从 那 里 带 出 他 来 ， 交 在 报 血 仇 的 手 中 ， 将 他 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5420', '5', '19', '13', '你 眼 不 可 顾 惜 他 ， 却 要 从 以 色 列 中 除 掉 流 无 辜 血 的 罪 ， 使 你 可 以 得 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5421', '5', '19', '14', '＜ 旧 地 界 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5422', '5', '19', '15', '＜ 有 关 证 人 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5423', '5', '19', '16', '若 有 凶 恶 的 见 证 人 起 来 ， 见 证 某 人 作 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5424', '5', '19', '17', '这 两 个 争 讼 的 人 就 要 站 在 耶 和 华 面 前 ， 和 当 时 的 祭 司 ， 并 审 判 官 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5425', '5', '19', '18', '审 判 官 要 细 细 地 查 究 ， 若 见 证 人 果 然 是 作 假 见 证 的 ， 以 假 见 证 陷 害 弟 兄 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5426', '5', '19', '19', '你 们 就 要 待 他 如 同 他 想 要 待 的 弟 兄 。 这 样 ， 就 把 那 恶 从 你 们 中 间 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5427', '5', '19', '20', '别 人 听 见 都 要 害 怕 ， 就 不 敢 在 你 们 中 间 再 行 这 样 的 恶 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5428', '5', '19', '21', '你 眼 不 可 顾 惜 ， 要 以 命 偿 命 ， 以 眼 还 眼 ， 以 牙 还 牙 ， 以 手 还 手 ， 以 脚 还 脚 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5429', '5', '20', '1', '＜ 有 关 战 争 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5430', '5', '20', '2', '你 们 将 要 上 阵 的 时 候 ， 祭 司 要 到 百 姓 面 前 宣 告');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5431', '5', '20', '3', '说 ： ‘ 以 色 列 人 哪 ， 你 们 当 听 ， 你 们 今 日 将 要 与 仇 敌 争 战 ， 不 要 胆 怯 ， 不 要 惧 怕 战 兢 ， 也 不 要 因 他 们 惊 恐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5432', '5', '20', '4', '因 为 耶 和 华 ─ ─ 你 们 的 神 与 你 们 同 去 ， 要 为 你 们 与 仇 敌 争 战 ， 拯 救 你 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5433', '5', '20', '5', '官 长 也 要 对 百 姓 宣 告 说 ： ‘ 谁 建 造 房 屋 ， 尚 未 奉 献 ， 他 可 以 回 家 去 ， 恐 怕 他 阵 亡 ， 别 人 去 奉 献 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5434', '5', '20', '6', '谁 种 葡 萄 园 ， 尚 未 用 所 结 的 果 子 ， 他 可 以 回 家 去 ， 恐 怕 他 阵 亡 ， 别 人 去 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5435', '5', '20', '7', '谁 聘 定 了 妻 ， 尚 未 迎 娶 ， 他 可 以 回 家 去 ， 恐 怕 他 阵 亡 ， 别 人 去 娶 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5436', '5', '20', '8', '官 长 又 要 对 百 姓 宣 告 说 ： ‘ 谁 惧 怕 胆 怯 ， 他 可 以 回 家 去 ， 恐 怕 他 弟 兄 的 心 消 化 ， 和 他 一 样 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5437', '5', '20', '9', '官 长 对 百 姓 宣 告 完 了 ， 就 当 派 军 长 率 领 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5438', '5', '20', '10', '“ 你 临 近 一 座 城 、 要 攻 打 的 时 候 ， 先 要 对 城 里 的 民 宣 告 和 睦 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5439', '5', '20', '11', '他 们 若 以 和 睦 的 话 回 答 你 ， 给 你 开 了 城 ， 城 里 所 有 的 人 都 要 给 你 效 劳 ， 服 事 你 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5440', '5', '20', '12', '若 不 肯 与 你 和 好 ， 反 要 与 你 打 仗 ， 你 就 要 围 困 那 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5441', '5', '20', '13', '耶 和 华 ─ ─ 你 的 神 把 城 交 付 你 手 ， 你 就 要 用 刀 杀 尽 这 城 的 男 丁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5442', '5', '20', '14', '惟 有 妇 女 、 孩 子 、 牲 畜 ， 和 城 内 一 切 的 财 物 ， 你 可 以 取 为 自 己 的 掠 物 。 耶 和 华 ─ ─ 你 神 把 你 仇 敌 的 财 物 赐 给 你 ， 你 可 以 吃 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5443', '5', '20', '15', '离 你 甚 远 的 各 城 ， 不 是 这 些 国 民 的 城 ， 你 都 要 这 样 待 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5444', '5', '20', '16', '但 这 些 国 民 的 城 ， 耶 和 华 ─ ─ 你 神 既 赐 你 为 业 ， 其 中 凡 有 气 息 的 ， 一 个 不 可 存 留 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5445', '5', '20', '17', '只 要 照 耶 和 华 ─ ─ 你 神 所 吩 咐 的 将 这 赫 人 、 亚 摩 利 人 、 迦 南 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 都 灭 绝 净 尽 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5446', '5', '20', '18', '免 得 他 们 教 导 你 们 学 习 一 切 可 憎 恶 的 事 ， 就 是 他 们 向 自 己 神 所 行 的 ， 以 致 你 们 得 罪 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5447', '5', '20', '19', '“ 你 若 许 久 围 困 、 攻 打 所 要 取 的 一 座 城 ， 就 不 可 举 斧 子 砍 坏 树 木 ； 因 为 你 可 以 吃 那 树 上 的 果 子 ， 不 可 砍 伐 。 田 间 的 树 木 岂 是 人 ， 叫 你 糟 蹋 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5448', '5', '20', '20', '惟 独 你 所 知 道 不 是 结 果 子 的 树 木 可 以 毁 坏 、 砍 伐 ， 用 以 修 筑 营 垒 ， 攻 击 那 与 你 打 仗 的 城 ， 直 到 攻 塌 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5449', '5', '21', '1', '＜ 有 关 未 结 案 的 谋 杀 案 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5450', '5', '21', '2', '长 老 和 审 判 官 就 要 出 去 ， 从 被 杀 的 人 那 里 量 起 ， 直 量 到 四 围 的 城 邑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5451', '5', '21', '3', '看 哪 城 离 被 杀 的 人 最 近 ， 那 城 的 长 老 就 要 从 牛 群 中 取 一 只 未 曾 耕 地 、 未 曾 负 轭 的 母 牛 犊 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5452', '5', '21', '4', '把 母 牛 犊 牵 到 流 水 、 未 曾 耕 种 的 山 谷 去 ， 在 谷 中 打 折 母 牛 犊 的 颈 项 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5453', '5', '21', '5', '祭 司 利 未 的 子 孙 要 近 前 来 ； 因 为 耶 和 华 ─ ─ 你 的 神 拣 选 了 他 们 事 奉 他 ， 奉 耶 和 华 的 名 祝 福 ， 所 有 争 讼 殴 打 的 事 都 要 凭 他 们 判 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5454', '5', '21', '6', '那 城 的 众 长 老 ， 就 是 离 被 杀 的 人 最 近 的 ， 要 在 那 山 谷 中 ， 在 所 打 折 颈 项 的 母 牛 犊 以 上 洗 手 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5455', '5', '21', '7', '祷 告 ｛ 原 文 是 回 答 ｝ 说 ： ‘ 我 们 的 手 未 曾 流 这 人 的 血 ； 我 们 的 眼 也 未 曾 看 见 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5456', '5', '21', '8', '耶 和 华 啊 ， 求 你 赦 免 你 所 救 赎 的 以 色 列 民 ， 不 要 使 流 无 辜 血 的 罪 归 在 你 的 百 姓 以 色 列 中 间 。 ’ 这 样 ， 流 血 的 罪 必 得 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5457', '5', '21', '9', '你 行 耶 和 华 眼 中 看 为 正 的 事 ， 就 可 以 从 你 们 中 间 除 掉 流 无 辜 血 的 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5458', '5', '21', '10', '＜ 有 关 女 战 俘 的 案 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5459', '5', '21', '11', '若 在 被 掳 的 人 中 见 有 美 貌 的 女 子 ， 恋 慕 她 ， 要 娶 她 为 妻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5460', '5', '21', '12', '就 可 以 领 她 到 你 家 里 去 ； 她 便 要 剃 头 发 ， 修 指 甲 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5461', '5', '21', '13', '脱 去 被 掳 时 所 穿 的 衣 服 ， 住 在 你 家 里 哀 哭 父 母 一 个 整 月 ， 然 后 可 以 与 她 同 房 。 你 作 她 的 丈 夫 ， 她 作 你 的 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5462', '5', '21', '14', '后 来 你 若 不 喜 悦 她 ， 就 要 由 她 随 意 出 去 ， 决 不 可 为 钱 卖 她 ， 也 不 可 当 婢 女 待 她 ， 因 为 你 玷 污 了 她 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5463', '5', '21', '15', '＜ 有 关 长 子 的 承 继 权 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5464', '5', '21', '16', '到 了 把 产 业 分 给 儿 子 承 受 的 时 候 ， 不 可 将 所 爱 之 妻 生 的 儿 子 立 为 长 子 ， 在 所 恶 之 妻 生 的 儿 子 以 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5465', '5', '21', '17', '却 要 认 所 恶 之 妻 生 的 儿 子 为 长 子 ， 将 产 业 多 加 一 分 给 他 ； 因 这 儿 子 是 他 力 量 强 壮 的 时 候 生 的 ， 长 子 的 名 分 本 当 归 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5466', '5', '21', '18', '＜ 有 关 逆 子 的 处 置 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5467', '5', '21', '19', '父 母 就 要 抓 住 他 ， 将 他 带 到 本 地 的 城 门 、 本 城 的 长 老 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5468', '5', '21', '20', '对 长 老 说 ： ‘ 我 们 这 儿 子 顽 梗 悖 逆 ， 不 听 从 我 们 的 话 ， 是 贪 食 好 酒 的 人 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5469', '5', '21', '21', '本 城 的 众 人 就 要 用 石 头 将 他 打 死 。 这 样 ， 就 把 那 恶 从 你 们 中 间 除 掉 ， 以 色 列 众 人 都 要 听 见 害 怕 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5470', '5', '21', '22', '＜ 其 他 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5471', '5', '21', '23', '他 的 尸 首 不 可 留 在 木 头 上 过 夜 ， 必 要 当 日 将 他 葬 埋 ， 免 得 玷 污 了 耶 和 华 ─ ─ 你 神 所 赐 你 为 业 之 地 。 因 为 被 挂 的 人 是 在 神 面 前 受 咒 诅 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5472', '5', '22', '1', '“ 你 若 看 见 弟 兄 的 牛 或 羊 失 迷 了 路 ， 不 可 佯 为 不 见 ， 总 要 把 它 牵 回 来 交 给 你 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5473', '5', '22', '2', '你 弟 兄 若 离 你 远 ， 或 是 你 不 认 识 他 ， 就 要 牵 到 你 家 去 ， 留 在 你 那 里 ， 等 你 弟 兄 来 寻 找 就 还 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5474', '5', '22', '3', '你 的 弟 兄 无 论 失 落 什 么 ， 或 是 驴 ， 或 是 衣 服 ， 你 若 遇 见 ， 都 要 这 样 行 ， 不 可 佯 为 不 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5475', '5', '22', '4', '你 若 看 见 弟 兄 的 牛 或 驴 跌 倒 在 路 上 ， 不 可 佯 为 不 见 ， 总 要 帮 助 他 拉 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5476', '5', '22', '5', '“ 妇 女 不 可 穿 戴 男 子 所 穿 戴 的 ， 男 子 也 不 可 穿 妇 女 的 衣 服 ， 因 为 这 样 行 都 是 耶 和 华 ─ ─ 你 神 所 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5477', '5', '22', '6', '“ 你 若 路 上 遇 见 鸟 窝 ， 或 在 树 上 或 在 地 上 ， 里 头 有 雏 或 有 蛋 ， 母 鸟 伏 在 雏 上 或 在 蛋 上 ， 你 不 可 连 母 带 雏 一 并 取 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5478', '5', '22', '7', '总 要 放 母 ， 只 可 取 雏 ； 这 样 你 就 可 以 享 福 ， 日 子 得 以 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5479', '5', '22', '8', '“ 你 若 建 造 房 屋 ， 要 在 房 上 的 四 围 安 栏 杆 ， 免 得 有 人 从 房 上 掉 下 来 ， 流 血 的 罪 就 归 于 你 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5480', '5', '22', '9', '“ 不 可 把 两 样 种 子 种 在 你 的 葡 萄 园 里 ， 免 得 你 撒 种 所 结 的 和 葡 萄 园 的 果 子 都 要 充 公 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5481', '5', '22', '10', '不 可 并 用 牛 、 驴 耕 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5482', '5', '22', '11', '不 可 穿 羊 毛 、 细 麻 两 样 搀 杂 料 做 的 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5483', '5', '22', '12', '“ 你 要 在 所 披 的 外 衣 上 四 围 做 繸 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5484', '5', '22', '13', '＜ 有 关 贞 洁 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5485', '5', '22', '14', '信 口 说 她 ， 将 丑 名 加 在 她 身 上 ， 说 ： ‘ 我 娶 了 这 女 子 ， 与 她 同 房 ， 见 她 没 有 贞 洁 的 凭 据 ’ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5486', '5', '22', '15', '女 子 的 父 母 就 要 把 女 子 贞 洁 的 凭 据 拿 出 来 ， 带 到 本 城 门 长 老 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5487', '5', '22', '16', '女 子 的 父 亲 要 对 长 老 说 ： ‘ 我 将 我 的 女 儿 给 这 人 为 妻 ， 他 恨 恶 她 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5488', '5', '22', '17', '信 口 说 她 ， 说 ： 我 见 你 的 女 儿 没 有 贞 洁 的 凭 据 ； 其 实 这 就 是 我 女 儿 贞 洁 的 凭 据 。 ’ 父 母 就 把 那 布 铺 在 本 城 的 长 老 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5489', '5', '22', '18', '本 城 的 长 老 要 拿 住 那 人 ， 惩 治 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5490', '5', '22', '19', '并 要 罚 他 一 百 舍 客 勒 银 子 ， 给 女 子 的 父 亲 ， 因 为 他 将 丑 名 加 在 以 色 列 的 一 个 处 女 身 上 。 女 子 仍 作 他 的 妻 ， 终 身 不 可 休 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5491', '5', '22', '20', '但 这 事 若 是 真 的 ， 女 子 没 有 贞 洁 的 凭 据 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5492', '5', '22', '21', '就 要 将 女 子 带 到 她 父 家 的 门 口 ， 本 城 的 人 要 用 石 头 将 她 打 死 ； 因 为 她 在 父 家 行 了 淫 乱 ， 在 以 色 列 中 做 了 丑 事 。 这 样 ， 就 把 那 恶 从 你 们 中 间 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5493', '5', '22', '22', '“ 若 遇 见 人 与 有 丈 夫 的 妇 人 行 淫 ， 就 要 将 奸 夫 淫 妇 一 并 治 死 。 这 样 ， 就 把 那 恶 从 以 色 列 中 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5494', '5', '22', '23', '“ 若 有 处 女 已 经 许 配 丈 夫 ， 有 人 在 城 里 遇 见 她 ， 与 她 行 淫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5495', '5', '22', '24', '你 们 就 要 把 这 二 人 带 到 本 城 门 ， 用 石 头 打 死 ─ ─ 女 子 是 因 为 虽 在 城 里 却 没 有 喊 叫 ； 男 子 是 因 为 玷 污 别 人 的 妻 。 这 样 ， 就 把 那 恶 从 你 们 中 间 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5496', '5', '22', '25', '“ 若 有 男 子 在 田 野 遇 见 已 经 许 配 人 的 女 子 ， 强 与 她 行 淫 ， 只 要 将 那 男 子 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5497', '5', '22', '26', '但 不 可 办 女 子 ； 她 本 没 有 该 死 的 罪 ， 这 事 就 类 乎 人 起 来 攻 击 邻 舍 ， 将 他 杀 了 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5498', '5', '22', '27', '因 为 男 子 是 在 田 野 遇 见 那 已 经 许 配 人 的 女 子 ， 女 子 喊 叫 ， 并 无 人 救 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5499', '5', '22', '28', '“ 若 有 男 子 遇 见 没 有 许 配 人 的 处 女 ， 抓 住 她 ， 与 她 行 淫 ， 被 人 看 见 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5500', '5', '22', '29', '这 男 子 就 要 拿 五 十 舍 客 勒 银 子 给 女 子 的 父 亲 ； 因 他 玷 污 了 这 女 子 ， 就 要 娶 她 为 妻 ， 终 身 不 可 休 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5501', '5', '22', '30', '“ 人 不 可 娶 继 母 为 妻 ； 不 可 掀 开 他 父 亲 的 衣 襟 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5502', '5', '23', '1', '＜ 不 许 进 入 圣 会 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5503', '5', '23', '2', '“ 私 生 子 不 可 入 耶 和 华 的 会 ； 他 的 子 孙 ， 直 到 十 代 ， 也 不 可 入 耶 和 华 的 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5504', '5', '23', '3', '“ 亚 扪 人 或 是 摩 押 人 不 可 入 耶 和 华 的 会 ； 他 们 的 子 孙 ， 虽 过 十 代 ， 也 永 不 可 入 耶 和 华 的 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5505', '5', '23', '4', '因 为 你 们 出 埃 及 的 时 候 ， 他 们 没 有 拿 食 物 和 水 在 路 上 迎 接 你 们 ， 又 因 他 们 雇 了 美 索 不 达 米 亚 的 毗 夺 人 比 珥 的 儿 子 巴 兰 来 咒 诅 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5506', '5', '23', '5', '然 而 耶 和 华 ─ ─ 你 的 神 不 肯 听 从 巴 兰 ， 却 使 那 咒 诅 的 言 语 变 为 祝 福 的 话 ， 因 为 耶 和 华 ─ ─ 你 的 神 爱 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5507', '5', '23', '6', '你 一 生 一 世 永 不 可 求 他 们 的 平 安 和 他 们 的 利 益 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5508', '5', '23', '7', '“ 不 可 憎 恶 以 东 人 ， 因 为 他 是 你 的 弟 兄 。 不 可 憎 恶 埃 及 人 ， 因 为 你 在 他 的 地 上 作 过 寄 居 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5509', '5', '23', '8', '他 们 第 三 代 子 孙 可 以 入 耶 和 华 的 会 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5510', '5', '23', '9', '＜ 保 持 军 营 的 卫 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5511', '5', '23', '10', '“ 你 们 中 间 ， 若 有 人 夜 间 偶 然 梦 遗 ， 不 洁 净 ， 就 要 出 到 营 外 ， 不 可 入 营 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5512', '5', '23', '11', '到 傍 晚 的 时 候 ， 他 要 用 水 洗 澡 ， 及 至 日 落 了 才 可 以 入 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5513', '5', '23', '12', '“ 你 在 营 外 也 该 定 出 一 个 地 方 作 为 便 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5514', '5', '23', '13', '在 你 器 械 之 中 当 预 备 一 把 锹 ， 你 出 营 外 便 溺 以 后 ， 用 以 铲 土 ， 转 身 掩 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5515', '5', '23', '14', '因 为 耶 和 华 ─ ─ 你 的 神 常 在 你 营 中 行 走 ， 要 救 护 你 ， 将 仇 敌 交 给 你 ， 所 以 你 的 营 理 当 圣 洁 ， 免 得 他 见 你 那 里 有 污 秽 ， 就 离 开 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5516', '5', '23', '15', '＜ 一 般 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5517', '5', '23', '16', '他 必 在 你 那 里 与 你 同 住 ， 在 你 的 城 邑 中 ， 要 由 他 选 择 一 个 所 喜 悦 的 地 方 居 住 ； 你 不 可 欺 负 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5518', '5', '23', '17', '“ 以 色 列 的 女 子 中 不 可 有 妓 女 ； 以 色 列 的 男 子 中 不 可 有 娈 童 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5519', '5', '23', '18', '娼 妓 所 得 的 钱 ， 或 娈 童 ｛ 原 文 是 狗 ｝ 所 得 的 价 ， 你 不 可 带 入 耶 和 华 ─ ─ 你 神 的 殿 还 愿 ， 因 为 这 两 样 都 是 耶 和 华 ─ ─ 你 神 所 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5520', '5', '23', '19', '“ 你 借 给 你 弟 兄 的 ， 或 是 钱 财 或 是 粮 食 ， 无 论 什 么 可 生 利 的 物 ， 都 不 可 取 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5521', '5', '23', '20', '借 给 外 邦 人 可 以 取 利 ， 只 是 借 给 你 弟 兄 不 可 取 利 。 这 样 ， 耶 和 华 ─ ─ 你 神 必 在 你 所 去 得 为 业 的 地 上 和 你 手 里 所 办 的 一 切 事 上 赐 福 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5522', '5', '23', '21', '“ 你 向 耶 和 华 ─ ─ 你 的 神 许 愿 ， 偿 还 不 可 迟 延 ； 因 为 耶 和 华 ─ ─ 你 的 神 必 定 向 你 追 讨 ， 你 不 偿 还 就 有 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5523', '5', '23', '22', '你 若 不 许 愿 ， 倒 无 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5524', '5', '23', '23', '你 嘴 里 所 出 的 ， 就 是 你 口 中 应 许 甘 心 所 献 的 ， 要 照 你 向 耶 和 华 ─ ─ 你 神 所 许 的 愿 谨 守 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5525', '5', '23', '24', '“ 你 进 了 邻 舍 的 葡 萄 园 ， 可 以 随 意 吃 饱 了 葡 萄 ， 只 是 不 可 装 在 器 皿 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5526', '5', '23', '25', '你 进 了 邻 舍 站 着 的 禾 稼 ， 可 以 用 手 摘 穗 子 ， 只 是 不 可 用 镰 刀 割 取 禾 稼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5527', '5', '24', '1', '＜ 离 婚 和 再 婚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5528', '5', '24', '2', '妇 人 离 开 夫 家 以 后 ， 可 以 去 嫁 别 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5529', '5', '24', '3', '后 夫 若 恨 恶 她 ， 写 休 书 交 在 她 手 中 ， 打 发 她 离 开 夫 家 ， 或 是 娶 她 为 妻 的 后 夫 死 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5530', '5', '24', '4', '打 发 她 去 的 前 夫 不 可 在 妇 人 玷 污 之 后 再 娶 她 为 妻 ， 因 为 这 是 耶 和 华 所 憎 恶 的 ； 不 可 使 耶 和 华 ─ ─ 你 神 所 赐 为 业 之 地 被 玷 污 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5531', '5', '24', '5', '＜ 一 般 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5532', '5', '24', '6', '“ 不 可 拿 人 的 全 盘 磨 石 或 是 上 磨 石 作 当 头 ， 因 为 这 是 拿 人 的 命 作 当 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5533', '5', '24', '7', '“ 若 遇 见 人 拐 带 以 色 列 中 的 一 个 弟 兄 ， 当 奴 才 待 他 ， 或 是 卖 了 他 ， 那 拐 带 人 的 就 必 治 死 。 这 样 ， 便 将 那 恶 从 你 们 中 间 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5534', '5', '24', '8', '“ 在 大 痲 疯 的 灾 病 上 ， 你 们 要 谨 慎 ， 照 祭 司 利 未 人 一 切 所 指 教 你 们 的 留 意 遵 行 。 我 怎 样 吩 咐 他 们 ， 你 们 要 怎 样 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5535', '5', '24', '9', '当 记 念 出 埃 及 后 ， 在 路 上 ， 耶 和 华 ─ ─ 你 神 向 米 利 暗 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5536', '5', '24', '10', '“ 你 借 给 邻 舍 ， 不 拘 是 什 么 ， 不 可 进 他 家 拿 他 的 当 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5537', '5', '24', '11', '要 站 在 外 面 ， 等 那 向 你 借 贷 的 人 把 当 头 拿 出 来 交 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5538', '5', '24', '12', '他 若 是 穷 人 ， 你 不 可 留 他 的 当 头 过 夜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5539', '5', '24', '13', '日 落 的 时 候 ， 总 要 把 当 头 还 他 ， 使 他 用 那 件 衣 服 盖 着 睡 觉 ， 他 就 为 你 祝 福 ； 这 在 耶 和 华 ─ ─ 你 神 面 前 就 是 你 的 义 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5540', '5', '24', '14', '“ 困 苦 穷 乏 的 雇 工 ， 无 论 是 你 的 弟 兄 或 是 在 你 城 里 寄 居 的 ， 你 不 可 欺 负 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5541', '5', '24', '15', '要 当 日 给 他 工 价 ， 不 可 等 到 日 落 ─ ─ 因 为 他 穷 苦 ， 把 心 放 在 工 价 上 ─ ─ 恐 怕 他 因 你 求 告 耶 和 华 ， 罪 便 归 你 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5542', '5', '24', '16', '“ 不 可 因 子 杀 父 ， 也 不 可 因 父 杀 子 ； 凡 被 杀 的 都 为 本 身 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5543', '5', '24', '17', '“ 你 不 可 向 寄 居 的 和 孤 儿 屈 枉 正 直 ， 也 不 可 拿 寡 妇 的 衣 裳 作 当 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5544', '5', '24', '18', '要 记 念 你 在 埃 及 作 过 奴 仆 。 耶 和 华 ─ ─ 你 的 神 从 那 里 将 你 救 赎 ， 所 以 我 吩 咐 你 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5545', '5', '24', '19', '“ 你 在 田 间 收 割 庄 稼 ， 若 忘 下 一 捆 ， 不 可 回 去 再 取 ， 要 留 给 寄 居 的 与 孤 儿 寡 妇 。 这 样 ， 耶 和 华 ─ ─ 你 神 必 在 你 手 里 所 办 的 一 切 事 上 赐 福 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5546', '5', '24', '20', '你 打 橄 榄 树 ， 枝 上 剩 下 的 ， 不 可 再 打 ； 要 留 给 寄 居 的 与 孤 儿 寡 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5547', '5', '24', '21', '你 摘 葡 萄 园 的 葡 萄 ， 所 剩 下 的 ， 不 可 再 摘 ； 要 留 给 寄 居 的 与 孤 儿 寡 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5548', '5', '24', '22', '你 也 要 记 念 你 在 埃 及 地 作 过 奴 仆 ， 所 以 我 吩 咐 你 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5549', '5', '25', '1', '“ 人 若 有 争 讼 ， 来 听 审 判 ， 审 判 官 就 要 定 义 人 有 理 ， 定 恶 人 有 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5550', '5', '25', '2', '恶 人 若 该 受 责 打 ， 审 判 官 就 要 叫 他 当 面 伏 在 地 上 ， 按 着 他 的 罪 照 数 责 打 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5551', '5', '25', '3', '只 可 打 他 四 十 下 ， 不 可 过 数 ； 若 过 数 ， 便 是 轻 贱 你 的 弟 兄 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5552', '5', '25', '4', '“ 牛 在 场 上 踹 谷 的 时 候 ， 不 可 笼 住 它 的 嘴 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5553', '5', '25', '5', '＜ 对 丧 亡 的 弟 兄 传 宗 接 代 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5554', '5', '25', '6', '妇 人 生 的 长 子 必 归 死 兄 的 名 下 ， 免 得 他 的 名 在 以 色 列 中 涂 抹 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5555', '5', '25', '7', '那 人 若 不 愿 意 娶 他 哥 哥 的 妻 ， 他 哥 哥 的 妻 就 要 到 城 门 长 老 那 里 ， 说 ： ‘ 我 丈 夫 的 兄 弟 不 肯 在 以 色 列 中 兴 起 他 哥 哥 的 名 字 ， 不 给 我 尽 弟 兄 的 本 分 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5556', '5', '25', '8', '本 城 的 长 老 就 要 召 那 人 来 问 他 ， 他 若 执 意 说 ： ‘ 我 不 愿 意 娶 她 ’ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5557', '5', '25', '9', '他 哥 哥 的 妻 就 要 当 着 长 老 到 那 人 的 跟 前 ， 脱 了 他 的 鞋 ， 吐 唾 沫 在 他 脸 上 ， 说 ： ‘ 凡 不 为 哥 哥 建 立 家 室 的 都 要 这 样 待 他 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5558', '5', '25', '10', '在 以 色 列 中 ， 他 的 名 必 称 为 脱 鞋 之 家 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5559', '5', '25', '11', '＜ 其 他 的 条 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5560', '5', '25', '12', '就 要 砍 断 妇 人 的 手 ， 眼 不 可 顾 惜 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5561', '5', '25', '13', '“ 你 囊 中 不 可 有 一 大 一 小 两 样 的 法 码 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5562', '5', '25', '14', '你 家 里 不 可 有 一 大 一 小 两 样 的 升 斗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5563', '5', '25', '15', '当 用 对 准 公 平 的 法 码 ， 公 平 的 升 斗 。 这 样 ， 在 耶 和 华 ─ ─ 你 神 所 赐 你 的 地 上 ， 你 的 日 子 就 可 以 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5564', '5', '25', '16', '因 为 行 非 义 之 事 的 人 都 是 耶 和 华 ─ ─ 你 神 所 憎 恶 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5565', '5', '25', '17', '＜ 吩 咐 人 民 消 灭 亚 玛 力 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5566', '5', '25', '18', '他 们 在 路 上 遇 见 你 ， 趁 你 疲 乏 困 倦 击 杀 你 尽 后 边 软 弱 的 人 ， 并 不 敬 畏 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5567', '5', '25', '19', '所 以 耶 和 华 ─ ─ 你 神 使 你 不 被 四 围 一 切 的 仇 敌 扰 乱 ， 在 耶 和 华 ─ ─ 你 神 赐 你 为 业 的 地 上 得 享 平 安 。 那 时 ， 你 要 将 亚 玛 力 的 名 号 从 天 下 涂 抹 了 ， 不 可 忘 记 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5568', '5', '26', '1', '＜ 奉 献 初 熟 的 土 产 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5569', '5', '26', '2', '就 要 从 耶 和 华 ─ ─ 你 神 赐 你 的 地 上 将 所 收 的 各 种 初 熟 的 土 产 取 些 来 ， 盛 在 筐 子 里 ， 往 耶 和 华 ─ ─ 你 神 所 选 择 要 立 为 他 名 的 居 所 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5570', '5', '26', '3', '见 当 时 作 祭 司 的 ， 对 他 说 ： ‘ 我 今 日 向 耶 和 华 ─ ─ 你 神 明 认 ， 我 已 来 到 耶 和 华 向 我 们 列 祖 起 誓 应 许 赐 给 我 们 的 地 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5571', '5', '26', '4', '祭 司 就 从 你 手 里 取 过 筐 子 来 ， 放 在 耶 和 华 ─ ─ 你 神 的 坛 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5572', '5', '26', '5', '你 要 在 耶 和 华 ─ ─ 你 神 面 前 说 ： ‘ 我 祖 原 是 一 个 将 亡 的 亚 兰 人 ， 下 到 埃 及 寄 居 。 他 人 口 稀 少 ， 在 那 里 却 成 了 又 大 又 强 、 人 数 很 多 的 国 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5573', '5', '26', '6', '埃 及 人 恶 待 我 们 ， 苦 害 我 们 ， 将 苦 工 加 在 我 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5574', '5', '26', '7', '于 是 我 们 哀 求 耶 和 华 ─ ─ 我 们 列 祖 的 神 ， 耶 和 华 听 见 我 们 的 声 音 ， 看 见 我 们 所 受 的 困 苦 、 劳 碌 、 欺 压 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5575', '5', '26', '8', '他 就 用 大 能 的 手 和 伸 出 来 的 膀 臂 ， 并 大 可 畏 的 事 与 神 迹 奇 事 ， 领 我 们 出 了 埃 及 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5576', '5', '26', '9', '将 我 们 领 进 这 地 方 ， 把 这 流 奶 与 蜜 之 地 赐 给 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5577', '5', '26', '10', '耶 和 华 啊 ， 现 在 我 把 你 所 赐 给 我 地 上 初 熟 的 土 产 奉 了 来 。 ’ 随 后 你 要 把 筐 子 放 在 耶 和 华 ─ ─ 你 神 面 前 ， 向 耶 和 华 ─ ─ 你 的 神 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5578', '5', '26', '11', '你 和 利 未 人 ， 并 在 你 们 中 间 寄 居 的 ， 要 因 耶 和 华 ─ ─ 你 神 所 赐 你 和 你 家 的 一 切 福 分 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5579', '5', '26', '12', '“ 每 逢 三 年 ， 就 是 十 分 取 一 之 年 ， 你 取 完 了 一 切 土 产 的 十 分 之 一 ， 要 分 给 利 未 人 和 寄 居 的 ， 与 孤 儿 寡 妇 ， 使 他 们 在 你 城 中 可 以 吃 得 饱 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5580', '5', '26', '13', '你 又 要 在 耶 和 华 ─ ─ 你 神 面 前 说 ： ‘ 我 已 将 圣 物 从 我 家 里 拿 出 来 ， 给 了 利 未 人 和 寄 居 的 ， 与 孤 儿 寡 妇 ， 是 照 你 所 吩 咐 我 的 一 切 命 令 。 你 的 命 令 我 都 没 有 违 背 ， 也 没 有 忘 记 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5581', '5', '26', '14', '我 守 丧 的 时 候 ， 没 有 吃 这 圣 物 ； 不 洁 净 的 时 候 ， 也 没 有 拿 出 来 ， 又 没 有 为 死 人 送 去 。 我 听 从 了 耶 和 华 ─ ─ 我 神 的 话 ， 都 照 你 所 吩 咐 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5582', '5', '26', '15', '求 你 从 天 上 、 你 的 圣 所 垂 看 ， 赐 福 给 你 的 百 姓 以 色 列 与 你 所 赐 给 我 们 的 地 ， 就 是 你 向 我 们 列 祖 起 誓 赐 我 们 流 奶 与 蜜 之 地 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5583', '5', '26', '16', '＜ 属 主 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5584', '5', '26', '17', '你 今 日 认 耶 和 华 为 你 的 神 ， 应 许 遵 行 他 的 道 ， 谨 守 他 的 律 例 、 诫 命 、 典 章 ， 听 从 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5585', '5', '26', '18', '耶 和 华 今 日 照 他 所 应 许 你 的 ， 也 认 你 为 他 的 子 民 ， 使 你 谨 守 他 的 一 切 诫 命 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5586', '5', '26', '19', '又 使 你 得 称 赞 、 美 名 、 尊 荣 ， 超 乎 他 所 造 的 万 民 之 上 ， 并 照 他 所 应 许 的 使 你 归 耶 和 华 ─ ─ 你 神 为 圣 洁 的 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5587', '5', '27', '1', '＜ 神 的 律 法 写 在 石 头 上 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5588', '5', '27', '2', '你 们 过 约 旦 河 ， 到 了 耶 和 华 ─ ─ 你 神 所 赐 给 你 的 地 ， 当 天 要 立 起 几 块 大 石 头 ， 墁 上 石 灰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5589', '5', '27', '3', '把 这 律 法 的 一 切 话 写 在 石 头 上 。 你 过 了 河 ， 可 以 进 入 耶 和 华 ─ ─ 你 神 所 赐 你 流 奶 与 蜜 之 地 ， 正 如 耶 和 华 ─ ─ 你 列 祖 之 神 所 应 许 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5590', '5', '27', '4', '你 们 过 了 约 旦 河 ， 就 要 在 以 巴 路 山 上 照 我 今 日 所 吩 咐 的 ， 将 这 些 石 头 立 起 来 ， 墁 上 石 灰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5591', '5', '27', '5', '在 那 里 要 为 耶 和 华 ─ ─ 你 的 神 筑 一 座 石 坛 ； 在 石 头 上 不 可 动 铁 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5592', '5', '27', '6', '要 用 没 有 凿 过 的 石 头 筑 耶 和 华 ─ ─ 你 神 的 坛 ， 在 坛 上 要 将 燔 祭 献 给 耶 和 华 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5593', '5', '27', '7', '又 要 献 平 安 祭 ， 且 在 那 里 吃 ， 在 耶 和 华 ─ ─ 你 的 神 面 前 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5594', '5', '27', '8', '你 要 将 这 律 法 的 一 切 话 明 明 地 写 在 石 头 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5595', '5', '27', '9', '摩 西 和 祭 司 利 未 人 晓 谕 以 色 列 众 人 说 ： “ 以 色 列 啊 ， 要 默 默 静 听 。 你 今 日 成 为 耶 和 华 ─ ─ 你 神 的 百 姓 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5596', '5', '27', '10', '所 以 要 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 遵 行 他 的 诫 命 律 例 ， 就 是 我 今 日 所 吩 咐 你 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5597', '5', '27', '11', '＜ 违 命 必 受 咒 诅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5598', '5', '27', '12', '“ 你 们 过 了 约 旦 河 ， 西 缅 、 利 未 、 犹 大 、 以 萨 迦 、 约 瑟 、 便 雅 悯 六 个 支 派 的 人 都 要 站 在 基 利 心 山 上 为 百 姓 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5599', '5', '27', '13', '吕 便 、 迦 得 、 亚 设 、 西 布 伦 、 但 、 拿 弗 他 利 六 个 支 派 的 人 都 要 站 在 以 巴 路 山 上 宣 布 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5600', '5', '27', '14', '利 未 人 要 向 以 色 列 众 人 高 声 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5601', '5', '27', '15', '“ ‘ 有 人 制 造 耶 和 华 所 憎 恶 的 偶 像 ， 或 雕 刻 ， 或 铸 造 ， 就 是 工 匠 手 所 做 的 ， 在 暗 中 设 立 ， 那 人 必 受 咒 诅 ！ ’ 百 姓 都 要 答 应 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5602', '5', '27', '16', '“ ‘ 轻 慢 父 母 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5603', '5', '27', '17', '“ ‘ 挪 移 邻 舍 地 界 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5604', '5', '27', '18', '“ ‘ 使 瞎 子 走 差 路 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5605', '5', '27', '19', '“ ‘ 向 寄 居 的 和 孤 儿 寡 妇 屈 枉 正 直 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5606', '5', '27', '20', '“ ‘ 与 继 母 行 淫 的 ， 必 受 咒 诅 ！ 因 为 掀 开 他 父 亲 的 衣 襟 。 ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5607', '5', '27', '21', '“ ‘ 与 兽 淫 合 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5608', '5', '27', '22', '“ ‘ 与 异 母 同 父 ， 或 异 父 同 母 的 姊 妹 行 淫 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5609', '5', '27', '23', '“ ‘ 与 岳 母 行 淫 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5610', '5', '27', '24', '“ ‘ 暗 中 杀 人 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5611', '5', '27', '25', '“ ‘ 受 贿 赂 害 死 无 辜 之 人 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5612', '5', '27', '26', '“ ‘ 不 坚 守 遵 行 这 律 法 言 语 的 ， 必 受 咒 诅 ！ ’ 百 姓 都 要 说 ： ‘ 阿 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5613', '5', '28', '1', '＜ 遵 行 诫 命 蒙 福 （ 利   2 6 ： 3 - 1 3 ； 申   7 ： 1 2 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5614', '5', '28', '2', '你 若 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 这 以 下 的 福 必 追 随 你 ， 临 到 你 身 上 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5615', '5', '28', '3', '你 在 城 里 必 蒙 福 ， 在 田 间 也 必 蒙 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5616', '5', '28', '4', '你 身 所 生 的 ， 地 所 产 的 ， 牲 畜 所 下 的 ， 以 及 牛 犊 、 羊 羔 ， 都 必 蒙 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5617', '5', '28', '5', '你 的 筐 子 和 你 的 抟 面 盆 都 必 蒙 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5618', '5', '28', '6', '你 出 也 蒙 福 ， 入 也 蒙 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5619', '5', '28', '7', '“ 仇 敌 起 来 攻 击 你 ， 耶 和 华 必 使 他 们 在 你 面 前 被 你 杀 败 ； 他 们 从 一 条 路 来 攻 击 你 ， 必 从 七 条 路 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5620', '5', '28', '8', '在 你 仓 房 里 ， 并 你 手 所 办 的 一 切 事 上 ， 耶 和 华 所 命 的 福 必 临 到 你 。 耶 和 华 ─ ─ 你 神 也 要 在 所 给 你 的 地 上 赐 福 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5621', '5', '28', '9', '你 若 谨 守 耶 和 华 ─ ─ 你 神 的 诫 命 ， 遵 行 他 的 道 ， 他 必 照 着 向 你 所 起 的 誓 立 你 作 为 自 己 的 圣 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5622', '5', '28', '10', '天 下 万 民 见 你 归 在 耶 和 华 的 名 下 ， 就 要 惧 怕 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5623', '5', '28', '11', '你 在 耶 和 华 向 你 列 祖 起 誓 应 许 赐 你 的 地 上 ， 他 必 使 你 身 所 生 的 ， 牲 畜 所 下 的 ， 地 所 产 的 ， 都 绰 绰 有 余 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5624', '5', '28', '12', '耶 和 华 必 为 你 开 天 上 的 府 库 ， 按 时 降 雨 在 你 的 地 上 。 在 你 手 里 所 办 的 一 切 事 上 赐 福 与 你 。 你 必 借 给 许 多 国 民 ， 却 不 致 向 他 们 借 贷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5625', '5', '28', '13', '你 若 听 从 耶 和 华 ─ ─ 你 神 的 诫 命 ， 就 是 我 今 日 所 吩 咐 你 的 ， 谨 守 遵 行 ， 不 偏 左 右 ， 也 不 随 从 事 奉 别 神 ， 耶 和 华 就 必 使 你 作 首 不 作 尾 ， 但 居 上 不 居 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5626', '5', '28', '14', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5627', '5', '28', '15', '＜ 背 逆 的 后 果 （ 利   2 6 ： 1 4 - 4 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5628', '5', '28', '16', '你 在 城 里 必 受 咒 诅 ， 在 田 间 也 必 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5629', '5', '28', '17', '你 的 筐 子 和 你 的 抟 面 盆 都 必 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5630', '5', '28', '18', '你 身 所 生 的 ， 地 所 产 的 ， 以 及 牛 犊 、 羊 羔 ， 都 必 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5631', '5', '28', '19', '你 出 也 受 咒 诅 ， 入 也 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5632', '5', '28', '20', '耶 和 华 因 你 行 恶 离 弃 他 ， 必 在 你 手 里 所 办 的 一 切 事 上 ， 使 咒 诅 、 扰 乱 、 责 罚 临 到 你 ， 直 到 你 被 毁 灭 ， 速 速 地 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5633', '5', '28', '21', '耶 和 华 必 使 瘟 疫 贴 在 你 身 上 ， 直 到 他 将 你 从 所 进 去 得 为 业 的 地 上 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5634', '5', '28', '22', '耶 和 华 要 用 痨 病 、 热 病 、 火 症 、 疟 疾 、 刀 剑 、 旱 风 ｛ 或 译 ： 干 旱 ｝ 、 霉 烂 攻 击 你 。 这 都 要 追 赶 你 ， 直 到 你 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5635', '5', '28', '23', '你 头 上 的 天 要 变 为 铜 ， 脚 下 的 地 要 变 为 铁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5636', '5', '28', '24', '耶 和 华 要 使 那 降 在 你 地 上 的 雨 变 为 尘 沙 ， 从 天 临 在 你 身 上 ， 直 到 你 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5637', '5', '28', '25', '“ 耶 和 华 必 使 你 败 在 仇 敌 面 前 ， 你 从 一 条 路 去 攻 击 他 们 ， 必 从 七 条 路 逃 跑 。 你 必 在 天 下 万 国 中 抛 来 抛 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5638', '5', '28', '26', '你 的 尸 首 必 给 空 中 的 飞 鸟 和 地 上 的 走 兽 作 食 物 ， 并 无 人 哄 赶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5639', '5', '28', '27', '耶 和 华 必 用 埃 及 人 的 疮 并 痔 疮 、 牛 皮 癣 与 疥 攻 击 你 ， 使 你 不 能 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5640', '5', '28', '28', '耶 和 华 必 用 癫 狂 、 眼 瞎 、 心 惊 攻 击 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5641', '5', '28', '29', '你 必 在 午 间 摸 索 ， 好 像 瞎 子 在 暗 中 摸 索 一 样 。 你 所 行 的 必 不 亨 通 ， 时 常 遭 遇 欺 压 、 抢 夺 ， 无 人 搭 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5642', '5', '28', '30', '你 聘 定 了 妻 ， 别 人 必 与 她 同 房 ； 你 建 造 房 屋 ， 不 得 住 在 其 内 ； 你 栽 种 葡 萄 园 ， 也 不 得 用 其 中 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5643', '5', '28', '31', '你 的 牛 在 你 眼 前 宰 了 ， 你 必 不 得 吃 它 的 肉 ； 你 的 驴 在 你 眼 前 被 抢 夺 ， 不 得 归 还 ； 你 的 羊 归 了 仇 敌 ， 无 人 搭 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5644', '5', '28', '32', '你 的 儿 女 必 归 与 别 国 的 民 ； 你 的 眼 目 终 日 切 望 ， 甚 至 失 明 ， 你 手 中 无 力 拯 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5645', '5', '28', '33', '你 的 土 产 和 你 劳 碌 得 来 的 ， 必 被 你 所 不 认 识 的 国 民 吃 尽 。 你 时 常 被 欺 负 ， 受 压 制 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5646', '5', '28', '34', '甚 至 你 因 眼 中 所 看 见 的 ， 必 致 疯 狂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5647', '5', '28', '35', '耶 和 华 必 攻 击 你 ， 使 你 膝 上 腿 上 ， 从 脚 掌 到 头 顶 ， 长 毒 疮 无 法 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5648', '5', '28', '36', '“ 耶 和 华 必 将 你 和 你 所 立 的 王 领 到 你 和 你 列 祖 素 不 认 识 的 国 去 ； 在 那 里 你 必 事 奉 木 头 石 头 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5649', '5', '28', '37', '你 在 耶 和 华 领 你 到 的 各 国 中 ， 要 令 人 惊 骇 、 笑 谈 、 讥 诮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5650', '5', '28', '38', '你 带 到 田 间 的 种 子 虽 多 ， 收 进 来 的 却 少 ， 因 为 被 蝗 虫 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5651', '5', '28', '39', '你 栽 种 、 修 理 葡 萄 园 ， 却 不 得 收 葡 萄 ， 也 不 得 喝 葡 萄 酒 ， 因 为 被 虫 子 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5652', '5', '28', '40', '你 全 境 有 橄 榄 树 ， 却 不 得 其 油 抹 身 ， 因 为 树 上 的 橄 榄 不 熟 自 落 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5653', '5', '28', '41', '你 生 儿 养 女 ， 却 不 算 是 你 的 ， 因 为 必 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5654', '5', '28', '42', '你 所 有 的 树 木 和 你 地 里 的 出 产 必 被 蝗 虫 所 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5655', '5', '28', '43', '在 你 中 间 寄 居 的 ， 必 渐 渐 上 升 ， 比 你 高 而 又 高 ； 你 必 渐 渐 下 降 ， 低 而 又 低 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5656', '5', '28', '44', '他 必 借 给 你 ， 你 却 不 能 借 给 他 ； 他 必 作 首 ， 你 必 作 尾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5657', '5', '28', '45', '这 一 切 咒 诅 必 追 随 你 ， 赶 上 你 ， 直 到 你 灭 亡 ； 因 为 你 不 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 不 遵 守 他 所 吩 咐 的 诫 命 律 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5658', '5', '28', '46', '这 些 咒 诅 必 在 你 和 你 后 裔 的 身 上 成 为 异 迹 奇 事 ， 直 到 永 远 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5659', '5', '28', '47', '“ 因 为 你 富 有 的 时 候 ， 不 欢 心 乐 意 地 事 奉 耶 和 华 ─ ─ 你 的 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5660', '5', '28', '48', '所 以 你 必 在 饥 饿 、 干 渴 、 赤 露 、 缺 乏 之 中 事 奉 耶 和 华 所 打 发 来 攻 击 你 的 仇 敌 。 他 必 把 铁 轭 加 在 你 的 颈 项 上 ， 直 到 将 你 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5661', '5', '28', '49', '“ 耶 和 华 要 从 远 方 、 地 极 带 一 国 的 民 ， 如 鹰 飞 来 攻 击 你 。 这 民 的 言 语 ， 你 不 懂 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5662', '5', '28', '50', '这 民 的 面 貌 凶 恶 ， 不 顾 恤 年 老 的 ， 也 不 恩 待 年 少 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5663', '5', '28', '51', '他 们 必 吃 你 牲 畜 所 下 的 和 你 地 土 所 产 的 ， 直 到 你 灭 亡 。 你 的 五 谷 、 新 酒 ， 和 油 ， 以 及 牛 犊 、 羊 羔 ， 都 不 给 你 留 下 ， 直 到 将 你 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5664', '5', '28', '52', '他 们 必 将 你 困 在 你 各 城 里 ， 直 到 你 所 倚 靠 、 高 大 坚 固 的 城 墙 都 被 攻 塌 。 他 们 必 将 你 困 在 耶 和 华 ─ ─ 你 神 所 赐 你 遍 地 的 各 城 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5665', '5', '28', '53', '你 在 仇 敌 围 困 窘 迫 之 中 ， 必 吃 你 本 身 所 生 的 ， 就 是 耶 和 华 ─ ─ 你 神 所 赐 给 你 的 儿 女 之 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5666', '5', '28', '54', '你 们 中 间 ， 柔 弱 娇 嫩 的 人 必 恶 眼 看 他 弟 兄 和 他 怀 中 的 妻 ， 并 他 余 剩 的 儿 女 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5667', '5', '28', '55', '甚 至 在 你 受 仇 敌 围 困 窘 迫 的 城 中 ， 他 要 吃 儿 女 的 肉 ， 不 肯 分 一 点 给 他 的 亲 人 ， 因 为 他 一 无 所 剩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5668', '5', '28', '56', '你 们 中 间 ， 柔 弱 娇 嫩 的 妇 人 ， 是 因 娇 嫩 柔 弱 不 肯 把 脚 踏 地 的 ， 必 恶 眼 看 她 怀 中 的 丈 夫 和 她 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5669', '5', '28', '57', '她 两 腿 中 间 出 来 的 婴 孩 与 她 所 要 生 的 儿 女 ， 她 因 缺 乏 一 切 就 要 在 你 受 仇 敌 围 困 窘 迫 的 城 中 将 他 们 暗 暗 地 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5670', '5', '28', '58', '“ 这 书 上 所 写 律 法 的 一 切 话 是 叫 你 敬 畏 耶 和 华 ─ ─ 你 神 可 荣 可 畏 的 名 。 你 若 不 谨 守 遵 行 ， 耶 和 华 就 必 将 奇 灾 ， 就 是 至 大 至 长 的 灾 ， 至 重 至 久 的 病 ， 加 在 你 和 你 后 裔 的 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5671', '5', '28', '59', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5672', '5', '28', '60', '也 必 使 你 所 惧 怕 、 埃 及 人 的 病 都 临 到 你 ， 贴 在 你 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5673', '5', '28', '61', '又 必 将 没 有 写 在 这 律 法 书 上 的 各 样 疾 病 、 灾 殃 降 在 你 身 上 ， 直 到 你 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5674', '5', '28', '62', '你 们 先 前 虽 然 像 天 上 的 星 那 样 多 ， 却 因 不 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 所 剩 的 人 数 就 稀 少 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5675', '5', '28', '63', '先 前 耶 和 华 怎 样 喜 悦 善 待 你 们 ， 使 你 们 众 多 ， 也 要 照 样 喜 悦 毁 灭 你 们 ， 使 你 们 灭 亡 ； 并 且 你 们 从 所 要 进 去 得 的 地 上 必 被 拔 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5676', '5', '28', '64', '耶 和 华 必 使 你 们 分 散 在 万 民 中 ， 从 地 这 边 到 地 那 边 ， 你 必 在 那 里 事 奉 你 和 你 列 祖 素 不 认 识 、 木 头 石 头 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5677', '5', '28', '65', '在 那 些 国 中 ， 你 必 不 得 安 逸 ， 也 不 得 落 脚 之 地 ； 耶 和 华 却 使 你 在 那 里 心 中 跳 动 ， 眼 目 失 明 ， 精 神 消 耗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5678', '5', '28', '66', '你 的 性 命 必 悬 悬 无 定 ； 你 昼 夜 恐 惧 ， 自 料 性 命 难 保 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5679', '5', '28', '67', '你 因 心 里 所 恐 惧 的 ， 眼 中 所 看 见 的 ， 早 晨 必 说 ， 巴 不 得 到 晚 上 才 好 ； 晚 上 必 说 ， 巴 不 得 到 早 晨 才 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5680', '5', '28', '68', '耶 和 华 必 使 你 坐 船 回 埃 及 去 ， 走 我 曾 告 诉 你 不 得 再 见 的 路 ； 在 那 里 你 必 卖 己 身 与 仇 敌 作 奴 婢 ， 却 无 人 买 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5681', '5', '29', '1', '＜ 在 摩 押 跟 以 色 列 人 立 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5682', '5', '29', '2', '摩 西 召 了 以 色 列 众 人 来 ， 对 他 们 说 ： “ 耶 和 华 在 埃 及 地 ， 在 你 们 眼 前 向 法 老 和 他 众 臣 仆 ， 并 他 全 地 所 行 的 一 切 事 ， 你 们 都 看 见 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5683', '5', '29', '3', '就 是 你 亲 眼 看 见 的 大 试 验 和 神 迹 ， 并 那 些 大 奇 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5684', '5', '29', '4', '但 耶 和 华 到 今 日 没 有 使 你 们 心 能 明 白 ， 眼 能 看 见 ， 耳 能 听 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5685', '5', '29', '5', '我 领 你 们 在 旷 野 四 十 年 ， 你 们 身 上 的 衣 服 并 没 有 穿 破 ， 脚 上 的 鞋 也 没 有 穿 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5686', '5', '29', '6', '你 们 没 有 吃 饼 ， 也 没 有 喝 清 酒 浓 酒 。 这 要 使 你 们 知 道 ， 耶 和 华 是 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5687', '5', '29', '7', '你 们 来 到 这 地 方 ， 希 实 本 王 西 宏 、 巴 珊 王 噩 都 出 来 与 我 们 交 战 ， 我 们 就 击 杀 了 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5688', '5', '29', '8', '取 了 他 们 的 地 给 吕 便 支 派 、 迦 得 支 派 ， 和 玛 拿 西 半 支 派 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5689', '5', '29', '9', '所 以 你 们 要 谨 守 遵 行 这 约 的 话 ， 好 叫 你 们 在 一 切 所 行 的 事 上 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5690', '5', '29', '10', '“ 今 日 ， 你 们 的 首 领 、 族 长 ｛ 原 文 是 支 派 ｝ 、 长 老 、 官 长 、 以 色 列 的 男 丁 ， 你 们 的 妻 子 儿 女 ， 和 营 中 寄 居 的 ， 以 及 为 你 们 劈 柴 挑 水 的 人 ， 都 站 在 耶 和 华 ─ ─ 你 们 的 神 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5691', '5', '29', '11', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5692', '5', '29', '12', '为 要 你 顺 从 耶 和 华 ─ ─ 你 神 今 日 与 你 所 立 的 约 ， 向 你 所 起 的 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5693', '5', '29', '13', '这 样 ， 他 要 照 他 向 你 所 应 许 的 话 ， 又 向 你 列 祖 亚 伯 拉 罕 、 以 撒 、 雅 各 所 起 的 誓 ， 今 日 立 你 作 他 的 子 民 ， 他 作 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5694', '5', '29', '14', '我 不 但 与 你 们 立 这 约 ， 起 这 誓 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5695', '5', '29', '15', '凡 与 我 们 一 同 站 在 耶 和 华 ─ ─ 我 们 神 面 前 的 ， 并 今 日 不 在 我 们 这 里 的 人 ， 我 也 与 他 们 立 这 约 ， 起 这 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5696', '5', '29', '16', '“ 我 们 曾 住 过 埃 及 地 ， 也 从 列 国 经 过 ； 这 是 你 们 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5697', '5', '29', '17', '你 们 也 看 见 他 们 中 间 可 憎 之 物 ， 并 他 们 木 、 石 、 金 、 银 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5698', '5', '29', '18', '惟 恐 你 们 中 间 ， 或 男 或 女 ， 或 族 长 或 支 派 长 ， 今 日 心 里 偏 离 耶 和 华 ─ ─ 我 们 的 神 ， 去 事 奉 那 些 国 的 神 ； 又 怕 你 们 中 间 有 恶 根 生 出 苦 菜 和 茵 蔯 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5699', '5', '29', '19', '听 见 这 咒 诅 的 话 ， 心 里 仍 是 自 夸 说 ： ‘ 我 虽 然 行 事 心 里 顽 梗 ， 连 累 众 人 ， 却 还 是 平 安 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5700', '5', '29', '20', '耶 和 华 必 不 饶 恕 他 ； 耶 和 华 的 怒 气 与 愤 恨 要 向 他 发 作 ， 如 烟 冒 出 ， 将 这 书 上 所 写 的 一 切 咒 诅 都 加 在 他 身 上 。 耶 和 华 又 要 从 天 下 涂 抹 他 的 名 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5701', '5', '29', '21', '也 必 照 着 写 在 律 法 书 上 、 约 中 的 一 切 咒 诅 将 他 从 以 色 列 众 支 派 中 分 别 出 来 ， 使 他 受 祸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5702', '5', '29', '22', '你 们 的 后 代 ， 就 是 以 后 兴 起 来 的 子 孙 ， 和 远 方 来 的 外 人 ， 看 见 这 地 的 灾 殃 ， 并 耶 和 华 所 降 与 这 地 的 疾 病 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5703', '5', '29', '23', '又 看 见 遍 地 有 硫 磺 ， 有 盐 卤 ， 有 火 迹 ， 没 有 耕 种 ， 没 有 出 产 ， 连 草 都 不 生 长 ─ ─ 好 像 耶 和 华 在 忿 怒 中 所 倾 覆 的 所 多 玛 、 蛾 摩 拉 、 押 玛 、 洗 扁 一 样 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5704', '5', '29', '24', '所 看 见 的 人 ， 连 万 国 人 ， 都 必 问 说 ： ‘ 耶 和 华 为 何 向 此 地 这 样 行 呢 ？ 这 样 大 发 烈 怒 是 什 么 意 思 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5705', '5', '29', '25', '人 必 回 答 说 ： ‘ 是 因 这 地 的 人 离 弃 了 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 领 他 们 出 埃 及 地 的 时 候 与 他 们 所 立 的 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5706', '5', '29', '26', '去 事 奉 敬 拜 素 不 认 识 的 别 神 ， 是 耶 和 华 所 未 曾 给 他 们 安 排 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5707', '5', '29', '27', '所 以 耶 和 华 的 怒 气 向 这 地 发 作 ， 将 这 书 上 所 写 的 一 切 咒 诅 都 降 在 这 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5708', '5', '29', '28', '耶 和 华 在 怒 气 、 忿 怒 、 大 恼 恨 中 将 他 们 从 本 地 拔 出 来 ， 扔 在 别 的 地 上 ， 像 今 日 一 样 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5709', '5', '29', '29', '“ 隐 秘 的 事 是 属 耶 和 华 ─ ─ 我 们 神 的 ； 惟 有 明 显 的 事 是 永 远 属 我 们 和 我 们 子 孙 的 ， 好 叫 我 们 遵 行 这 律 法 上 的 一 切 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5710', '5', '30', '1', '＜ 复 兴 和 蒙 福 的 条 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5711', '5', '30', '2', '你 和 你 的 子 孙 若 尽 心 尽 性 归 向 耶 和 华 ─ ─ 你 的 神 ， 照 着 我 今 日 一 切 所 吩 咐 的 听 从 他 的 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5712', '5', '30', '3', '那 时 ， 耶 和 华 ─ ─ 你 的 神 必 怜 恤 你 ， 救 回 你 这 被 掳 的 子 民 ； 耶 和 华 ─ ─ 你 的 神 要 回 转 过 来 ， 从 分 散 你 到 的 万 民 中 将 你 招 聚 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5713', '5', '30', '4', '你 被 赶 散 的 人 ， 就 是 在 天 涯 的 ， 耶 和 华 ─ ─ 你 的 神 也 必 从 那 里 将 你 招 聚 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5714', '5', '30', '5', '耶 和 华 ─ ─ 你 的 神 必 领 你 进 入 你 列 祖 所 得 的 地 ， 使 你 可 以 得 着 ； 又 必 善 待 你 ， 使 你 的 人 数 比 你 列 祖 众 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5715', '5', '30', '6', '耶 和 华 ─ ─ 你 神 必 将 你 心 里 和 你 后 裔 心 里 的 污 秽 除 掉 ， 好 叫 你 尽 心 尽 性 爱 耶 和 华 ─ ─ 你 的 神 ， 使 你 可 以 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5716', '5', '30', '7', '耶 和 华 ─ ─ 你 的 神 必 将 这 一 切 咒 诅 加 在 你 仇 敌 和 恨 恶 你 、 逼 迫 你 的 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5717', '5', '30', '8', '你 必 归 回 ， 听 从 耶 和 华 的 话 ， 遵 行 他 的 一 切 诫 命 ， 就 是 我 今 日 所 吩 咐 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5718', '5', '30', '9', '你 若 听 从 耶 和 华 ─ ─ 你 神 的 话 ， 谨 守 这 律 法 书 上 所 写 的 诫 命 律 例 ， 又 尽 心 尽 性 归 向 耶 和 华 ─ ─ 你 的 神 ， 他 必 使 你 手 里 所 办 的 一 切 事 ， 并 你 身 所 生 的 ， 牲 畜 所 下 的 ， 地 土 所 产 的 ， 都 绰 绰 有 余 ； 因 为 耶 和 华 必 再 喜 悦 你 ， 降 福 与 你 ， 像 从 前 喜 悦 你 列 祖 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5719', '5', '30', '10', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5720', '5', '30', '11', '“ 我 今 日 所 吩 咐 你 的 诫 命 不 是 你 难 行 的 ， 也 不 是 离 你 远 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5721', '5', '30', '12', '不 是 在 天 上 ， 使 你 说 ： ‘ 谁 替 我 们 上 天 取 下 来 ， 使 我 们 听 见 可 以 遵 行 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5722', '5', '30', '13', '也 不 是 在 海 外 ， 使 你 说 ： ‘ 谁 替 我 们 过 海 取 了 来 ， 使 我 们 听 见 可 以 遵 行 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5723', '5', '30', '14', '这 话 却 离 你 甚 近 ， 就 在 你 口 中 ， 在 你 心 里 ， 使 你 可 以 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5724', '5', '30', '15', '“ 看 哪 ， 我 今 日 将 生 与 福 ， 死 与 祸 ， 陈 明 在 你 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5725', '5', '30', '16', '吩 咐 你 爱 耶 和 华 ─ ─ 你 的 神 ， 遵 行 他 的 道 ， 谨 守 他 的 诫 命 、 律 例 、 典 章 ， 使 你 可 以 存 活 ， 人 数 增 多 ， 耶 和 华 ─ ─ 你 神 就 必 在 你 所 要 进 去 得 为 业 的 地 上 赐 福 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5726', '5', '30', '17', '倘 若 你 心 里 偏 离 ， 不 肯 听 从 ， 却 被 勾 引 去 敬 拜 事 奉 别 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5727', '5', '30', '18', '我 今 日 明 明 告 诉 你 们 ， 你 们 必 要 灭 亡 ； 在 你 过 约 旦 河 、 进 去 得 为 业 的 地 上 ， 你 的 日 子 必 不 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5728', '5', '30', '19', '我 今 日 呼 天 唤 地 向 你 作 见 证 ； 我 将 生 死 祸 福 陈 明 在 你 面 前 ， 所 以 你 要 拣 选 生 命 ， 使 你 和 你 的 后 裔 都 得 存 活 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5729', '5', '30', '20', '且 爱 耶 和 华 ─ ─ 你 的 神 ， 听 从 他 的 话 ， 专 靠 他 ； 因 为 他 是 你 的 生 命 ， 你 的 日 子 长 久 也 在 乎 他 。 这 样 ， 你 就 可 以 在 耶 和 华 向 你 列 祖 亚 伯 拉 罕 、 以 撒 、 雅 各 起 誓 应 许 所 赐 的 地 上 居 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5730', '5', '31', '1', '＜ 约 书 亚 承 继 摩 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5731', '5', '31', '2', '说 ： “ 我 现 在 一 百 二 十 岁 了 ， 不 能 照 常 出 入 ； 耶 和 华 也 曾 对 我 说 ： ‘ 你 必 不 得 过 这 约 旦 河 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5732', '5', '31', '3', '耶 和 华 ─ ─ 你 们 的 神 必 引 导 你 们 过 去 ， 将 这 些 国 民 在 你 们 面 前 灭 绝 ， 你 们 就 得 他 们 的 地 。 约 书 亚 必 引 导 你 们 过 去 ， 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5733', '5', '31', '4', '耶 和 华 必 待 他 们 ， 如 同 从 前 待 他 所 灭 绝 的 亚 摩 利 二 王 西 宏 与 噩 以 及 他 们 的 国 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5734', '5', '31', '5', '耶 和 华 必 将 他 们 交 给 你 们 ； 你 们 要 照 我 所 吩 咐 的 一 切 命 令 待 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5735', '5', '31', '6', '你 们 当 刚 强 壮 胆 ， 不 要 害 怕 ， 也 不 要 畏 惧 他 们 ， 因 为 耶 和 华 ─ ─ 你 的 神 和 你 同 去 。 他 必 不 撇 下 你 ， 也 不 丢 弃 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5736', '5', '31', '7', '摩 西 召 了 约 书 亚 来 ， 在 以 色 列 众 人 眼 前 对 他 说 ： “ 你 当 刚 强 壮 胆 ！ 因 为 ， 你 要 和 这 百 姓 一 同 进 入 耶 和 华 向 他 们 列 祖 起 誓 应 许 所 赐 之 地 ； 你 也 要 使 他 们 承 受 那 地 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5737', '5', '31', '8', '耶 和 华 必 在 你 前 面 行 ； 他 必 与 你 同 在 ， 必 不 撇 下 你 ， 也 不 丢 弃 你 。 不 要 惧 怕 ， 也 不 要 惊 惶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5738', '5', '31', '9', '＜ 每 七 年 诵 读 律 法 一 次 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5739', '5', '31', '10', '摩 西 吩 咐 他 们 说 ： “ 每 逢 七 年 的 末 一 年 ， 就 在 豁 免 年 的 定 期 住 棚 节 的 时 候 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5740', '5', '31', '11', '以 色 列 众 人 来 到 耶 和 华 ─ ─ 你 神 所 选 择 的 地 方 朝 见 他 。 那 时 ， 你 要 在 以 色 列 众 人 面 前 将 这 律 法 念 给 他 们 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5741', '5', '31', '12', '要 招 聚 他 们 男 、 女 、 孩 子 ， 并 城 里 寄 居 的 ， 使 他 们 听 ， 使 他 们 学 习 ， 好 敬 畏 耶 和 华 ─ ─ 你 们 的 神 ， 谨 守 、 遵 行 这 律 法 的 一 切 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5742', '5', '31', '13', '也 使 他 们 未 曾 晓 得 这 律 法 的 儿 女 得 以 听 见 ， 学 习 敬 畏 耶 和 华 ─ ─ 你 们 的 神 ， 在 你 们 过 约 旦 河 要 得 为 业 之 地 ， 存 活 的 日 子 ， 常 常 这 样 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5743', '5', '31', '14', '＜ 对 摩 西 的 最 后 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5744', '5', '31', '15', '耶 和 华 在 会 幕 里 云 柱 中 显 现 ， 云 柱 停 在 会 幕 门 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5745', '5', '31', '16', '耶 和 华 又 对 摩 西 说 ： “ 你 必 和 你 列 祖 同 睡 。 这 百 姓 要 起 来 ， 在 他 们 所 要 去 的 地 上 ， 在 那 地 的 人 中 ， 随 从 外 邦 神 行 邪 淫 ， 离 弃 我 ， 违 背 我 与 他 们 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5746', '5', '31', '17', '那 时 ， 我 的 怒 气 必 向 他 们 发 作 ； 我 也 必 离 弃 他 们 ， 掩 面 不 顾 他 们 ， 以 致 他 们 被 吞 灭 ， 并 有 许 多 的 祸 患 灾 难 临 到 他 们 。 那 日 他 们 必 说 ： ‘ 这 些 祸 患 临 到 我 们 ， 岂 不 是 因 我 们 的 神 不 在 我 们 中 间 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5747', '5', '31', '18', '那 时 ， 因 他 们 偏 向 别 神 所 行 的 一 切 恶 ， 我 必 定 掩 面 不 顾 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5748', '5', '31', '19', '现 在 你 要 写 一 篇 歌 ， 教 导 以 色 列 人 ， 传 给 他 们 ， 使 这 歌 见 证 他 们 的 不 是 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5749', '5', '31', '20', '因 为 我 将 他 们 领 进 我 向 他 们 列 祖 起 誓 应 许 那 流 奶 与 蜜 之 地 ， 他 们 在 那 里 吃 得 饱 足 ， 身 体 肥 胖 ， 就 必 偏 向 别 神 ， 事 奉 他 们 ， 藐 视 我 ， 背 弃 我 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5750', '5', '31', '21', '那 时 ， 有 许 多 祸 患 灾 难 临 到 他 们 ， 这 歌 必 在 他 们 面 前 作 见 证 ， 他 们 后 裔 的 口 中 必 念 诵 不 忘 。 我 未 领 他 们 到 我 所 起 誓 应 许 之 地 以 先 ， 他 们 所 怀 的 意 念 我 都 知 道 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5751', '5', '31', '22', '当 日 摩 西 就 写 了 一 篇 歌 ， 教 导 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5752', '5', '31', '23', '耶 和 华 嘱 咐 嫩 的 儿 子 约 书 亚 说 ： “ 你 当 刚 强 壮 胆 ， 因 为 你 必 领 以 色 列 人 进 我 所 起 誓 应 许 他 们 的 地 ； 我 必 与 你 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5753', '5', '31', '24', '摩 西 将 这 律 法 的 话 写 在 书 上 ， 及 至 写 完 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5754', '5', '31', '25', '就 吩 咐 抬 耶 和 华 约 柜 的 利 未 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5755', '5', '31', '26', '“ 将 这 律 法 书 放 在 耶 和 华 ─ ─ 你 们 神 的 约 柜 旁 ， 可 以 在 那 里 见 证 以 色 列 人 的 不 是 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5756', '5', '31', '27', '因 为 我 知 道 你 们 是 悖 逆 的 ， 是 硬 着 颈 项 的 。 我 今 日 还 活 着 与 你 们 同 在 ， 你 们 尚 且 悖 逆 耶 和 华 ， 何 况 我 死 后 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5757', '5', '31', '28', '你 们 要 将 你 们 支 派 的 众 长 老 和 官 长 都 招 聚 了 来 ， 我 好 将 这 些 话 说 与 他 们 听 ， 并 呼 天 唤 地 见 证 他 们 的 不 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5758', '5', '31', '29', '我 知 道 我 死 后 ， 你 们 必 全 然 败 坏 ， 偏 离 我 所 吩 咐 你 们 的 道 ， 行 耶 和 华 眼 中 看 为 恶 的 事 ， 以 手 所 做 的 惹 他 发 怒 ； 日 后 必 有 祸 患 临 到 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5759', '5', '31', '30', '＜ 摩 西 的 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5760', '5', '32', '1', '诸 天 哪 ， 侧 耳 ， 我 要 说 话 ； 愿 地 也 听 我 口 中 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5761', '5', '32', '2', '我 的 教 训 要 淋 漓 如 雨 ； 我 的 言 语 要 滴 落 如 露 ， 如 细 雨 降 在 嫩 草 上 ， 如 甘 霖 降 在 菜 蔬 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5762', '5', '32', '3', '我 要 宣 告 耶 和 华 的 名 ； 你 们 要 将 大 德 归 与 我 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5763', '5', '32', '4', '他 是 磐 石 ， 他 的 作 为 完 全 ； 他 所 行 的 无 不 公 平 ， 是 诚 实 无 伪 的 神 ， 又 公 义 ， 又 正 直 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5764', '5', '32', '5', '这 乖 僻 弯 曲 的 世 代 向 他 行 事 邪 僻 ； 有 这 弊 病 就 不 是 他 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5765', '5', '32', '6', '愚 昧 无 知 的 民 哪 ， 你 们 这 样 报 答 耶 和 华 吗 ？ 他 岂 不 是 你 的 父 、 将 你 买 来 的 吗 ？ 他 是 制 造 你 、 建 立 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5766', '5', '32', '7', '你 当 追 想 上 古 之 日 ， 思 念 历 代 之 年 ； 问 你 的 父 亲 ， 他 必 指 示 你 ； 问 你 的 长 者 ， 他 必 告 诉 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5767', '5', '32', '8', '至 高 者 将 地 业 赐 给 列 邦 ， 将 世 人 分 开 ， 就 照 以 色 列 人 的 数 目 立 定 万 民 的 疆 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5768', '5', '32', '9', '耶 和 华 的 分 本 是 他 的 百 姓 ； 他 的 产 业 本 是 雅 各 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5769', '5', '32', '10', '耶 和 华 遇 见 他 在 旷 野 ─ ─ 荒 凉 野 兽 吼 叫 之 地 ， 就 环 绕 他 ， 看 顾 他 ， 保 护 他 ， 如 同 保 护 眼 中 的 瞳 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5770', '5', '32', '11', '又 如 鹰 搅 动 巢 窝 ， 在 雏 鹰 以 上 两 翅 扇 展 ， 接 取 雏 鹰 ， 背 在 两 翼 之 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5771', '5', '32', '12', '这 样 ， 耶 和 华 独 自 引 导 他 ， 并 无 外 邦 神 与 他 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5772', '5', '32', '13', '耶 和 华 使 他 乘 驾 地 的 高 处 ， 得 吃 田 间 的 土 产 ； 又 使 他 从 磐 石 中 咂 蜜 ， 从 坚 石 中 吸 油 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5773', '5', '32', '14', '也 吃 牛 的 奶 油 ， 羊 的 奶 ， 羊 羔 的 脂 油 ， 巴 珊 所 出 的 公 绵 羊 和 山 羊 ， 与 上 好 的 麦 子 ， 也 喝 葡 萄 汁 酿 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5774', '5', '32', '15', '但 耶 书 仑 渐 渐 肥 胖 ， 粗 壮 ， 光 润 ， 踢 跳 ， 奔 跑 ， 便 离 弃 造 他 的 神 ， 轻 看 救 他 的 磐 石 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5775', '5', '32', '16', '敬 拜 别 神 ， 触 动 神 的 愤 恨 ， 行 可 憎 恶 的 事 ， 惹 了 他 的 怒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5776', '5', '32', '17', '所 祭 祀 的 鬼 魔 并 非 真 神 ， 乃 是 素 不 认 识 的 神 ， 是 近 来 新 兴 的 ， 是 你 列 祖 所 不 畏 惧 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5777', '5', '32', '18', '你 轻 忽 生 你 的 磐 石 ， 忘 记 产 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5778', '5', '32', '19', '耶 和 华 看 见 他 的 儿 女 惹 动 他 ， 就 厌 恶 他 们 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5779', '5', '32', '20', '我 要 向 他 们 掩 面 ， 看 他 们 的 结 局 如 何 。 他 们 本 是 极 乖 僻 的 族 类 ， 心 中 无 诚 实 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5780', '5', '32', '21', '他 们 以 那 “ 不 算 为 神 ” 的 触 动 我 的 愤 恨 ， 以 虚 无 的 神 惹 了 我 的 怒 气 。 我 也 要 以 那 “ 不 成 子 民 ” 的 触 动 他 们 的 愤 恨 ， 以 愚 昧 的 国 民 惹 了 他 们 的 怒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5781', '5', '32', '22', '因 为 在 我 怒 中 有 火 烧 起 ， 直 烧 到 极 深 的 阴 间 ， 把 地 和 地 的 出 产 尽 都 焚 烧 ， 山 的 根 基 也 烧 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5782', '5', '32', '23', '我 要 将 祸 患 堆 在 他 们 身 上 ， 把 我 的 箭 向 他 们 射 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5783', '5', '32', '24', '他 们 必 因 饥 饿 消 瘦 ， 被 炎 热 苦 毒 吞 灭 。 我 要 打 发 野 兽 用 牙 齿 咬 他 们 ， 并 土 中 腹 行 的 ， 用 毒 气 害 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5784', '5', '32', '25', '外 头 有 刀 剑 ， 内 室 有 惊 恐 ， 使 人 丧 亡 ， 使 少 男 、 童 女 、 吃 奶 的 、 白 发 的 ， 尽 都 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5785', '5', '32', '26', '我 说 ， 我 必 将 他 们 分 散 远 方 ， 使 他 们 的 名 号 从 人 间 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5786', '5', '32', '27', '惟 恐 仇 敌 惹 动 我 ， 只 怕 敌 人 错 看 ， 说 ： 是 我 们 手 的 能 力 ， 并 非 耶 和 华 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5787', '5', '32', '28', '因 为 以 色 列 民 毫 无 计 谋 ， 心 中 没 有 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5788', '5', '32', '29', '惟 愿 他 们 有 智 慧 ， 能 明 白 这 事 ， 肯 思 念 他 们 的 结 局 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5789', '5', '32', '30', '若 不 是 他 们 的 磐 石 卖 了 他 们 ， 若 不 是 耶 和 华 交 出 他 们 ， 一 人 焉 能 追 赶 他 们 千 人 ？ 二 人 焉 能 使 万 人 逃 跑 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5790', '5', '32', '31', '据 我 们 的 仇 敌 自 己 断 定 ， 他 们 的 磐 石 不 如 我 们 的 磐 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5791', '5', '32', '32', '他 们 的 葡 萄 树 是 所 多 玛 的 葡 萄 树 ， 蛾 摩 拉 田 园 所 生 的 ； 他 们 的 葡 萄 是 毒 葡 萄 ， 全 挂 都 是 苦 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5792', '5', '32', '33', '他 们 的 酒 是 大 蛇 的 毒 气 ， 是 虺 蛇 残 害 的 恶 毒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5793', '5', '32', '34', '这 不 都 是 积 蓄 在 我 这 里 ， 封 锁 在 我 府 库 中 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5794', '5', '32', '35', '他 们 失 脚 的 时 候 ， 伸 冤 报 应 在 我 ； 因 他 们 遭 灾 的 日 子 近 了 ； 那 要 临 在 他 们 身 上 的 必 速 速 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5795', '5', '32', '36', '耶 和 华 见 他 百 姓 毫 无 能 力 ， 无 论 困 住 的 、 自 由 的 都 没 有 剩 下 ， 就 必 为 他 们 伸 冤 ， 为 他 的 仆 人 后 悔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5796', '5', '32', '37', '他 必 说 ： 他 们 的 神 ， 他 们 所 投 靠 的 磐 石 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5797', '5', '32', '38', '就 是 向 来 吃 他 们 祭 牲 的 脂 油 ， 喝 他 们 奠 祭 之 酒 的 ， 在 哪 里 呢 ？ 他 可 以 兴 起 帮 助 你 们 ， 护 卫 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5798', '5', '32', '39', '你 们 如 今 要 知 道 ： 我 ， 惟 有 我 是 神 ； 在 我 以 外 并 无 别 神 。 我 使 人 死 ， 我 使 人 活 ； 我 损 伤 ， 我 也 医 治 ， 并 无 人 能 从 我 手 中 救 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5799', '5', '32', '40', '我 向 天 举 手 说 ： 我 凭 我 的 永 生 起 誓 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5800', '5', '32', '41', '我 若 磨 我 闪 亮 的 刀 ， 手 掌 审 判 之 权 ， 就 必 报 复 我 的 敌 人 ， 报 应 恨 我 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5801', '5', '32', '42', '我 要 使 我 的 箭 饮 血 饮 醉 ， 就 是 被 杀 被 掳 之 人 的 血 。 我 的 刀 要 吃 肉 ， 乃 是 仇 敌 中 首 领 之 头 的 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5802', '5', '32', '43', '你 们 外 邦 人 当 与 主 的 百 姓 一 同 欢 呼 ； 因 他 要 伸 他 仆 人 流 血 的 冤 ， 报 应 他 的 敌 人 ， 洁 净 他 的 地 ， 救 赎 他 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5803', '5', '32', '44', '摩 西 和 嫩 的 儿 子 约 书 亚 去 将 这 歌 的 一 切 话 说 给 百 姓 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5804', '5', '32', '45', '＜ 摩 西 的 最 后 训 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5805', '5', '32', '46', '又 说 ： “ 我 今 日 所 警 教 你 们 的 ， 你 们 都 要 放 在 心 上 ； 要 吩 咐 你 们 的 子 孙 谨 守 遵 行 这 律 法 上 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5806', '5', '32', '47', '因 为 这 不 是 虚 空 、 与 你 们 无 关 的 事 ， 乃 是 你 们 的 生 命 ； 在 你 们 过 约 旦 河 要 得 为 业 的 地 上 必 因 这 事 日 子 得 以 长 久 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5807', '5', '32', '48', '当 日 ， 耶 和 华 吩 咐 摩 西 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5808', '5', '32', '49', '“ 你 上 这 亚 巴 琳 山 中 的 尼 波 山 去 ， 在 摩 押 地 与 耶 利 哥 相 对 ， 观 看 我 所 要 赐 给 以 色 列 人 为 业 的 迦 南 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5809', '5', '32', '50', '你 必 死 在 你 所 登 的 山 上 ， 归 你 列 祖 ｛ 原 文 是 本 民 ｝ 去 ， 像 你 哥 哥 亚 伦 死 在 何 珥 山 上 ， 归 他 的 列 祖 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5810', '5', '32', '51', '因 为 你 们 在 寻 的 旷 野 ， 加 低 斯 的 米 利 巴 水 ， 在 以 色 列 人 中 没 有 尊 我 为 圣 ， 得 罪 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5811', '5', '32', '52', '我 所 赐 给 以 色 列 人 的 地 ， 你 可 以 远 远 地 观 看 ， 却 不 得 进 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5812', '5', '33', '1', '＜ 摩 西 祝 福 以 色 列 众 支 派 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5813', '5', '33', '2', '他 说 ： 耶 和 华 从 西 奈 而 来 ， 从 西 珥 向 他 们 显 现 ， 从 巴 兰 山 发 出 光 辉 ， 从 万 万 圣 者 中 来 临 ， 从 他 右 手 为 百 姓 传 出 烈 火 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5814', '5', '33', '3', '他 疼 爱 百 姓 ； 众 圣 徒 都 在 他 手 中 。 他 们 坐 在 他 的 脚 下 ， 领 受 他 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5815', '5', '33', '4', '摩 西 将 律 法 传 给 我 们 ， 作 为 雅 各 会 众 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5816', '5', '33', '5', '百 姓 的 众 首 领 ， 以 色 列 的 各 支 派 ， 一 同 聚 会 的 时 候 ， 耶 和 华 ｛ 原 文 是 他 ｝ 在 耶 书 仑 中 为 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5817', '5', '33', '6', '愿 吕 便 存 活 ， 不 致 死 亡 ； 愿 他 人 数 不 致 稀 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5818', '5', '33', '7', '为 犹 大 祝 福 说 ： 求 耶 和 华 俯 听 犹 大 的 声 音 ， 引 导 他 归 于 本 族 ； 他 曾 用 手 为 自 己 争 战 ， 你 必 帮 助 他 攻 击 敌 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5819', '5', '33', '8', '论 利 未 说 ： 耶 和 华 啊 ， 你 的 土 明 和 乌 陵 都 在 你 的 虔 诚 人 那 里 。 你 在 玛 撒 曾 试 验 他 ， 在 米 利 巴 水 与 他 争 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5820', '5', '33', '9', '他 论 自 己 的 父 母 说 ： 我 未 曾 看 见 ； 他 也 不 承 认 弟 兄 ， 也 不 认 识 自 己 的 儿 女 。 这 是 因 利 未 人 遵 行 你 的 话 ， 谨 守 你 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5821', '5', '33', '10', '他 们 要 将 你 的 典 章 教 训 雅 各 ， 将 你 的 律 法 教 训 以 色 列 。 他 们 要 把 香 焚 在 你 面 前 ， 把 全 牲 的 燔 祭 献 在 你 的 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5822', '5', '33', '11', '求 耶 和 华 降 福 在 他 的 财 物 上 ， 悦 纳 他 手 里 所 办 的 事 。 那 些 起 来 攻 击 他 和 恨 恶 他 的 人 ， 愿 你 刺 透 他 们 的 腰 ， 使 他 们 不 得 再 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5823', '5', '33', '12', '论 便 雅 悯 说 ： 耶 和 华 所 亲 爱 的 必 同 耶 和 华 安 然 居 住 ； 耶 和 华 终 日 遮 蔽 他 ， 也 住 在 他 两 肩 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5824', '5', '33', '13', '论 约 瑟 说 ： 愿 他 的 地 蒙 耶 和 华 赐 福 ， 得 天 上 的 宝 物 、 甘 露 ， 以 及 地 里 所 藏 的 泉 水 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5825', '5', '33', '14', '得 太 阳 所 晒 熟 的 美 果 ， 月 亮 所 养 成 的 宝 物 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5826', '5', '33', '15', '得 上 古 之 山 的 至 宝 ， 永 世 之 岭 的 宝 物 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5827', '5', '33', '16', '得 地 和 其 中 所 充 满 的 宝 物 ， 并 住 荆 棘 中 上 主 的 喜 悦 。 愿 这 些 福 都 归 于 约 瑟 的 头 上 ， 归 于 那 与 弟 兄 迥 别 之 人 的 顶 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5828', '5', '33', '17', '他 为 牛 群 中 头 生 的 ， 有 威 严 ； 他 的 角 是 野 牛 的 角 ， 用 以 抵 触 万 邦 ， 直 到 地 极 。 这 角 是 以 法 莲 的 万 万 ， 玛 拿 西 的 千 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5829', '5', '33', '18', '论 西 布 伦 说 ： 西 布 伦 哪 ， 你 出 外 可 以 欢 喜 。 以 萨 迦 啊 ， 在 你 帐 棚 里 可 以 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5830', '5', '33', '19', '他 们 要 将 列 邦 召 到 山 上 ， 在 那 里 献 公 义 的 祭 ； 因 为 他 们 要 吸 取 海 里 的 丰 富 ， 并 沙 中 所 藏 的 珍 宝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5831', '5', '33', '20', '论 迦 得 说 ： 使 迦 得 扩 张 的 应 当 称 颂 ！ 迦 得 住 如 母 狮 ； 他 撕 裂 膀 臂 ， 连 头 顶 也 撕 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5832', '5', '33', '21', '他 为 自 己 选 择 头 一 段 地 ， 因 在 那 里 有 设 立 律 法 者 的 分 存 留 。 他 与 百 姓 的 首 领 同 来 ； 他 施 行 耶 和 华 的 公 义 和 耶 和 华 与 以 色 列 所 立 的 典 章 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5833', '5', '33', '22', '论 但 说 ： 但 为 小 狮 子 ， 从 巴 珊 跳 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5834', '5', '33', '23', '论 拿 弗 他 利 说 ： 拿 弗 他 利 啊 ， 你 足 沾 恩 惠 ， 满 得 耶 和 华 的 福 ， 可 以 得 西 方 和 南 方 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5835', '5', '33', '24', '论 亚 设 说 ： 愿 亚 设 享 受 多 子 的 福 乐 ， 得 他 弟 兄 的 喜 悦 ， 可 以 把 脚 蘸 在 油 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5836', '5', '33', '25', '你 的 门 闩 ｛ 或 译 ： 鞋 ｝ 是 铜 的 ， 铁 的 。 你 的 日 子 如 何 ， 你 的 力 量 也 必 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5837', '5', '33', '26', '耶 书 仑 哪 ， 没 有 能 比 神 的 。 他 为 帮 助 你 ， 乘 在 天 空 ， 显 其 威 荣 ， 驾 行 穹 苍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5838', '5', '33', '27', '永 生 的 神 是 你 的 居 所 ； 他 永 久 的 膀 臂 在 你 以 下 。 他 在 你 前 面 撵 出 仇 敌 ， 说 ： 毁 灭 吧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5839', '5', '33', '28', '以 色 列 安 然 居 住 ； 雅 各 的 本 源 独 居 五 谷 新 酒 之 地 。 他 的 天 也 滴 甘 露 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5840', '5', '33', '29', '以 色 列 啊 ， 你 是 有 福 的 ！ 谁 像 你 这 蒙 耶 和 华 所 拯 救 的 百 姓 呢 ？ 他 是 你 的 盾 牌 ， 帮 助 你 ， 是 你 威 荣 的 刀 剑 。 你 的 仇 敌 必 投 降 你 ； 你 必 踏 在 他 们 的 高 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5841', '5', '34', '1', '＜ 摩 西 去 世 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5842', '5', '34', '2', '拿 弗 他 利 全 地 ， 以 法 莲 、 玛 拿 西 的 地 ， 犹 大 全 地 直 到 西 海 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5843', '5', '34', '3', '南 地 和 棕 树 城 耶 利 哥 的 平 原 ， 直 到 琐 珥 ， 都 指 给 他 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5844', '5', '34', '4', '耶 和 华 对 他 说 ： “ 这 就 是 我 向 亚 伯 拉 罕 、 以 撒 、 雅 各 起 誓 应 许 之 地 ， 说 ： ‘ 我 必 将 这 地 赐 给 你 的 后 裔 。 ’ 现 在 我 使 你 眼 睛 看 见 了 ， 你 却 不 得 过 到 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5845', '5', '34', '5', '于 是 ， 耶 和 华 的 仆 人 摩 西 死 在 摩 押 地 ， 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5846', '5', '34', '6', '耶 和 华 将 他 埋 葬 在 摩 押 地 、 伯 ． 毗 珥 对 面 的 谷 中 ， 只 是 到 今 日 没 有 人 知 道 他 的 坟 墓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5847', '5', '34', '7', '摩 西 死 的 时 候 年 一 百 二 十 岁 ； 眼 目 没 有 昏 花 ， 精 神 没 有 衰 败 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5848', '5', '34', '8', '以 色 列 人 在 摩 押 平 原 为 摩 西 哀 哭 了 三 十 日 ， 为 摩 西 居 丧 哀 哭 的 日 子 就 满 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5849', '5', '34', '9', '嫩 的 儿 子 约 书 亚 ； 因 为 摩 西 曾 按 手 在 他 头 上 ， 就 被 智 慧 的 灵 充 满 ， 以 色 列 人 便 听 从 他 ， 照 着 耶 和 华 吩 咐 摩 西 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5850', '5', '34', '10', '以 后 以 色 列 中 再 没 有 兴 起 先 知 像 摩 西 的 。 他 是 耶 和 华 面 对 面 所 认 识 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5851', '5', '34', '11', '耶 和 华 打 发 他 在 埃 及 地 向 法 老 和 他 的 一 切 臣 仆 ， 并 他 的 全 地 ， 行 各 样 神 迹 奇 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5852', '5', '34', '12', '又 在 以 色 列 众 人 眼 前 显 大 能 的 手 ， 行 一 切 大 而 可 畏 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5853', '6', '1', '1', '＜ 神 命 令 约 书 亚 征 服 迦 南 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5854', '6', '1', '2', '“ 我 的 仆 人 摩 西 死 了 。 现 在 你 要 起 来 ， 和 众 百 姓 过 这 约 旦 河 ， 往 我 所 要 赐 给 以 色 列 人 的 地 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5855', '6', '1', '3', '凡 你 们 脚 掌 所 踏 之 地 ， 我 都 照 着 我 所 应 许 摩 西 的 话 赐 给 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5856', '6', '1', '4', '从 旷 野 和 这 黎 巴 嫩 ， 直 到 幼 发 拉 底 大 河 ， 赫 人 的 全 地 ， 又 到 大 海 日 落 之 处 ， 都 要 作 你 们 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5857', '6', '1', '5', '你 平 生 的 日 子 ， 必 无 一 人 能 在 你 面 前 站 立 得 住 。 我 怎 样 与 摩 西 同 在 ， 也 必 照 样 与 你 同 在 ； 我 必 不 撇 下 你 ， 也 不 丢 弃 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5858', '6', '1', '6', '你 当 刚 强 壮 胆 ！ 因 为 你 必 使 这 百 姓 承 受 那 地 为 业 ， 就 是 我 向 他 们 列 祖 起 誓 应 许 赐 给 他 们 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5859', '6', '1', '7', '只 要 刚 强 ， 大 大 壮 胆 ， 谨 守 遵 行 我 仆 人 摩 西 所 吩 咐 你 的 一 切 律 法 ， 不 可 偏 离 左 右 ， 使 你 无 论 往 哪 里 去 ， 都 可 以 顺 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5860', '6', '1', '8', '这 律 法 书 不 可 离 开 你 的 口 ， 总 要 昼 夜 思 想 ， 好 使 你 谨 守 遵 行 这 书 上 所 写 的 一 切 话 。 如 此 ， 你 的 道 路 就 可 以 亨 通 ， 凡 事 顺 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5861', '6', '1', '9', '我 岂 没 有 吩 咐 你 吗 ？ 你 当 刚 强 壮 胆 ！ 不 要 惧 怕 ， 也 不 要 惊 惶 ； 因 为 你 无 论 往 哪 里 去 ， 耶 和 华 ─ ─ 你 的 神 必 与 你 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5862', '6', '1', '10', '＜ 约 书 亚 吩 咐 百 姓 准 备 渡 河 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5863', '6', '1', '11', '“ 你 们 要 走 遍 营 中 ， 吩 咐 百 姓 说 ： ‘ 当 预 备 食 物 ； 因 为 三 日 之 内 你 们 要 过 这 约 旦 河 ， 进 去 得 耶 和 华 ─ ─ 你 们 神 赐 你 们 为 业 之 地 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5864', '6', '1', '12', '约 书 亚 对 吕 便 人 、 迦 得 人 ， 和 玛 拿 西 半 支 派 的 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5865', '6', '1', '13', '“ 你 们 要 追 念 耶 和 华 的 仆 人 摩 西 所 吩 咐 你 们 的 话 说 ： ‘ 耶 和 华 ─ ─ 你 们 的 神 使 你 们 得 享 平 安 ， 也 必 将 这 地 赐 给 你 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5866', '6', '1', '14', '你 们 的 妻 子 、 孩 子 ， 和 牲 畜 都 可 以 留 在 约 旦 河 东 、 摩 西 所 给 你 们 的 地 ； 但 你 们 中 间 一 切 大 能 的 勇 士 都 要 带 着 兵 器 在 你 们 的 弟 兄 前 面 过 去 ， 帮 助 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5867', '6', '1', '15', '等 到 耶 和 华 使 你 们 的 弟 兄 像 你 们 一 样 得 享 平 安 ， 并 且 得 着 耶 和 华 ─ ─ 你 们 神 所 赐 他 们 为 业 之 地 ， 那 时 才 可 以 回 你 们 所 得 之 地 ， 承 受 为 业 ， 就 是 耶 和 华 的 仆 人 摩 西 在 约 旦 河 东 、 向 日 出 之 地 所 给 你 们 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5868', '6', '1', '16', '他 们 回 答 约 书 亚 说 ： “ 你 所 吩 咐 我 们 行 的 ， 我 们 都 必 行 ； 你 所 差 遣 我 们 去 的 ， 我 们 都 必 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5869', '6', '1', '17', '我 们 从 前 在 一 切 事 上 怎 样 听 从 摩 西 ， 现 在 也 必 照 样 听 从 你 ； 惟 愿 耶 和 华 ─ ─ 你 的 神 与 你 同 在 ， 像 与 摩 西 同 在 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5870', '6', '1', '18', '无 论 什 么 人 违 背 你 的 命 令 ， 不 听 从 你 所 吩 咐 他 的 一 切 话 ， 就 必 治 死 他 。 你 只 要 刚 强 壮 胆 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5871', '6', '2', '1', '＜ 约 书 亚 派 探 子 进 耶 利 哥 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5872', '6', '2', '2', '有 人 告 诉 耶 利 哥 王 说 ： “ 今 夜 有 以 色 列 人 来 到 这 里 窥 探 此 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5873', '6', '2', '3', '耶 利 哥 王 打 发 人 去 见 喇 合 说 ： “ 那 来 到 你 这 里 、 进 了 你 家 的 人 要 交 出 来 ， 因 为 他 们 来 窥 探 全 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5874', '6', '2', '4', '女 人 将 二 人 隐 藏 ， 就 回 答 说 ： “ 那 人 果 然 到 我 这 里 来 ； 他 们 是 哪 里 来 的 我 却 不 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5875', '6', '2', '5', '天 黑 、 要 关 城 门 的 时 候 ， 他 们 出 去 了 ， 往 哪 里 去 我 却 不 知 道 。 你 们 快 快 地 去 追 赶 ， 就 必 追 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5876', '6', '2', '6', '（ 先 是 女 人 领 二 人 上 了 房 顶 ， 将 他 们 藏 在 那 里 所 摆 的 麻 秸 中 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5877', '6', '2', '7', '那 些 人 就 往 约 旦 河 的 渡 口 追 赶 他 们 去 了 。 追 赶 他 们 的 人 一 出 去 ， 城 门 就 关 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5878', '6', '2', '8', '二 人 还 没 有 躺 卧 ， 女 人 就 上 房 顶 ， 到 他 们 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5879', '6', '2', '9', '对 他 们 说 ： “ 我 知 道 耶 和 华 已 经 把 这 地 赐 给 你 们 ， 并 且 因 你 们 的 缘 故 我 们 都 惊 慌 了 。 这 地 的 一 切 居 民 在 你 们 面 前 心 都 消 化 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5880', '6', '2', '10', '因 为 我 们 听 见 你 们 出 埃 及 的 时 候 ， 耶 和 华 怎 样 在 你 们 前 面 使 红 海 的 水 干 了 ， 并 且 你 们 怎 样 待 约 旦 河 东 的 两 个 亚 摩 利 王 西 宏 和 噩 ， 将 他 们 尽 行 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5881', '6', '2', '11', '我 们 一 听 见 这 些 事 ， 心 就 消 化 了 。 因 你 们 的 缘 故 ， 并 无 一 人 有 胆 气 。 耶 和 华 ─ ─ 你 们 的 神 本 是 上 天 下 地 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5882', '6', '2', '12', '现 在 我 既 是 恩 待 你 们 ， 求 你 们 指 着 耶 和 华 向 我 起 誓 ， 也 要 恩 待 我 父 家 ， 并 给 我 一 个 实 在 的 证 据 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5883', '6', '2', '13', '要 救 活 我 的 父 母 、 弟 兄 、 姊 妹 ， 和 一 切 属 他 们 的 ， 拯 救 我 们 性 命 不 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5884', '6', '2', '14', '二 人 对 她 说 ： “ 你 若 不 泄 漏 我 们 这 件 事 ， 我 们 情 愿 替 你 们 死 。 耶 和 华 将 这 地 赐 给 我 们 的 时 候 ， 我 们 必 以 慈 爱 诚 实 待 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5885', '6', '2', '15', '于 是 女 人 用 绳 子 将 二 人 从 窗 户 里 缒 下 去 ； 因 她 的 房 子 是 在 城 墙 边 上 ， 她 也 住 在 城 墙 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5886', '6', '2', '16', '她 对 他 们 说 ： “ 你 们 且 往 山 上 去 ， 恐 怕 追 赶 的 人 碰 见 你 们 ； 要 在 那 里 隐 藏 三 天 ， 等 追 赶 的 人 回 来 ， 然 后 才 可 以 走 你 们 的 路 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5887', '6', '2', '17', '二 人 对 她 说 ： “ 你 要 这 样 行 。 不 然 ， 你 叫 我 们 所 起 的 誓 就 与 我 们 无 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5888', '6', '2', '18', '我 们 来 到 这 地 的 时 候 ， 你 要 把 这 条 朱 红 线 绳 系 在 缒 我 们 下 去 的 窗 户 上 ， 并 要 使 你 的 父 母 、 弟 兄 ， 和 你 父 的 全 家 都 聚 集 在 你 家 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5889', '6', '2', '19', '凡 出 了 你 家 门 往 街 上 去 的 ， 他 的 罪 ｛ 原 文 是 血 ｝ 必 归 到 自 己 的 头 上 ， 与 我 们 无 干 了 。 凡 在 你 家 里 的 ， 若 有 人 下 手 害 他 ， 流 他 血 的 罪 就 归 到 我 们 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5890', '6', '2', '20', '你 若 泄 漏 我 们 这 件 事 ， 你 叫 我 们 所 起 的 誓 就 与 我 们 无 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5891', '6', '2', '21', '女 人 说 ： “ 照 你 们 的 话 行 吧 ！ ” 于 是 打 发 他 们 去 了 ， 又 把 朱 红 线 绳 系 在 窗 户 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5892', '6', '2', '22', '二 人 到 山 上 ， 在 那 里 住 了 三 天 ， 等 着 追 赶 的 人 回 去 了 。 追 赶 的 人 一 路 找 他 们 ， 却 找 不 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5893', '6', '2', '23', '二 人 就 下 山 回 来 ， 过 了 河 ， 到 嫩 的 儿 子 约 书 亚 那 里 ， 向 他 述 说 所 遭 遇 的 一 切 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5894', '6', '2', '24', '又 对 约 书 亚 说 ： “ 耶 和 华 果 然 将 那 全 地 交 在 我 们 手 中 ； 那 地 的 一 切 居 民 在 我 们 面 前 心 都 消 化 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5895', '6', '3', '1', '＜ 以 色 列 人 过 约 旦 河 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5896', '6', '3', '2', '过 了 三 天 ， 官 长 走 遍 营 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5897', '6', '3', '3', '吩 咐 百 姓 说 ： “ 你 们 看 见 耶 和 华 ─ ─ 你 们 神 的 约 柜 ， 又 见 祭 司 利 未 人 抬 着 ， 就 要 离 开 所 住 的 地 方 ， 跟 着 约 柜 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5898', '6', '3', '4', '只 是 你 们 和 约 柜 相 离 要 量 二 千 肘 ， 不 可 与 约 柜 相 近 ， 使 你 们 知 道 所 当 走 的 路 ， 因 为 这 条 路 你 们 向 来 没 有 走 过 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5899', '6', '3', '5', '约 书 亚 吩 咐 百 姓 说 ： “ 你 们 要 自 洁 ， 因 为 明 天 耶 和 华 必 在 你 们 中 间 行 奇 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5900', '6', '3', '6', '约 书 亚 又 吩 咐 祭 司 说 ： “ 你 们 抬 起 约 柜 ， 在 百 姓 前 头 过 去 。 ” 于 是 他 们 抬 起 约 柜 ， 在 百 姓 前 头 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5901', '6', '3', '7', '耶 和 华 对 约 书 亚 说 ： “ 从 今 日 起 ， 我 必 使 你 在 以 色 列 众 人 眼 前 尊 大 ， 使 他 们 知 道 我 怎 样 与 摩 西 同 在 ， 也 必 照 样 与 你 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5902', '6', '3', '8', '你 要 吩 咐 抬 约 柜 的 祭 司 说 ： ‘ 你 们 到 了 约 旦 河 的 水 边 上 ， 就 要 在 约 旦 河 水 里 站 住 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5903', '6', '3', '9', '约 书 亚 对 以 色 列 人 说 ： “ 你 们 近 前 来 ， 听 耶 和 华 ─ ─ 你 们 神 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5904', '6', '3', '10', '约 书 亚 说 ： “ 看 哪 ， 普 天 下 主 的 约 柜 必 在 你 们 前 头 过 去 ， 到 约 旦 河 里 ， 因 此 你 们 就 知 道 在 你 们 中 间 有 永 生 神 ； 并 且 他 必 在 你 们 面 前 赶 出 迦 南 人 、 赫 人 、 希 未 人 、 比 利 洗 人 、 革 迦 撒 人 、 亚 摩 利 人 、 耶 布 斯 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5905', '6', '3', '11', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5906', '6', '3', '12', '你 们 现 在 要 从 以 色 列 支 派 中 拣 选 十 二 个 人 ， 每 支 派 一 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5907', '6', '3', '13', '等 到 抬 普 天 下 主 耶 和 华 约 柜 的 祭 司 把 脚 站 在 约 旦 河 水 里 ， 约 旦 河 的 水 ， 就 是 从 上 往 下 流 的 水 ， 必 然 断 绝 ， 立 起 成 垒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5908', '6', '3', '14', '百 姓 离 开 帐 棚 要 过 约 旦 河 的 时 候 ， 抬 约 柜 的 祭 司 乃 在 百 姓 的 前 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5909', '6', '3', '15', '他 们 到 了 约 旦 河 ， 脚 一 入 水 （ 原 来 约 旦 河 水 在 收 割 的 日 子 涨 过 两 岸 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5910', '6', '3', '16', '那 从 上 往 下 流 的 水 便 在 极 远 之 地 、 撒 拉 但 旁 的 亚 当 城 那 里 停 住 ， 立 起 成 垒 ； 那 往 亚 拉 巴 的 海 ， 就 是 盐 海 ， 下 流 的 水 全 然 断 绝 。 于 是 百 姓 在 耶 利 哥 的 对 面 过 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5911', '6', '3', '17', '抬 耶 和 华 约 柜 的 祭 司 在 约 旦 河 中 的 干 地 上 站 定 ， 以 色 列 众 人 都 从 干 地 上 过 去 ， 直 到 国 民 尽 都 过 了 约 旦 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5912', '6', '4', '1', '＜ 立 石 为 记 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5913', '6', '4', '2', '“ 你 从 民 中 要 拣 选 十 二 个 人 ， 每 支 派 一 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5914', '6', '4', '3', '吩 咐 他 们 说 ： ‘ 你 们 从 这 里 ， 从 约 旦 河 中 、 祭 司 脚 站 定 的 地 方 ， 取 十 二 块 石 头 带 过 去 ， 放 在 你 们 今 夜 要 住 宿 的 地 方 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5915', '6', '4', '4', '于 是 ， 约 书 亚 将 他 从 以 色 列 人 中 所 预 备 的 那 十 二 个 人 ， 每 支 派 一 人 ， 都 召 了 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5916', '6', '4', '5', '对 他 们 说 ： “ 你 们 下 约 旦 河 中 ， 过 到 耶 和 华 ─ ─ 你 们 神 的 约 柜 前 头 ， 按 着 以 色 列 人 十 二 支 派 的 数 目 ， 每 人 取 一 块 石 头 扛 在 肩 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5917', '6', '4', '6', '这 些 石 头 在 你 们 中 间 可 以 作 为 证 据 。 日 后 ， 你 们 的 子 孙 问 你 们 说 ： ‘ 这 些 石 头 是 什 么 意 思 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5918', '6', '4', '7', '你 们 就 对 他 们 说 ： ‘ 这 是 因 为 约 旦 河 的 水 在 耶 和 华 的 约 柜 前 断 绝 ； 约 柜 过 约 旦 河 的 时 候 ， 约 旦 河 的 水 就 断 绝 了 。 这 些 石 头 要 作 以 色 列 人 永 远 的 纪 念 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5919', '6', '4', '8', '以 色 列 人 就 照 约 书 亚 所 吩 咐 的 ， 按 着 以 色 列 人 支 派 的 数 目 ， 从 约 旦 河 中 取 了 十 二 块 石 头 ， 都 遵 耶 和 华 所 吩 咐 约 书 亚 的 行 了 。 他 们 把 石 头 带 过 去 ， 到 他 们 所 住 宿 的 地 方 ， 就 放 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5920', '6', '4', '9', '约 书 亚 另 把 十 二 块 石 头 立 在 约 旦 河 中 ， 在 抬 约 柜 的 祭 司 脚 站 立 的 地 方 ； 直 到 今 日 ， 那 石 头 还 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5921', '6', '4', '10', '抬 约 柜 的 祭 司 站 在 约 旦 河 中 ， 等 到 耶 和 华 晓 谕 约 书 亚 吩 咐 百 姓 的 事 办 完 了 ， 是 照 摩 西 所 吩 咐 约 书 亚 的 一 切 话 。 于 是 百 姓 急 速 过 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5922', '6', '4', '11', '众 百 姓 尽 都 过 了 河 ， 耶 和 华 的 约 柜 和 祭 司 就 在 百 姓 面 前 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5923', '6', '4', '12', '吕 便 人 、 迦 得 人 、 玛 拿 西 半 支 派 的 人 都 照 摩 西 所 吩 咐 他 们 的 ， 带 着 兵 器 在 以 色 列 人 前 头 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5924', '6', '4', '13', '约 有 四 万 人 都 准 备 打 仗 ， 在 耶 和 华 面 前 过 去 ， 到 耶 利 哥 的 平 原 ， 等 候 上 阵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5925', '6', '4', '14', '当 那 日 ， 耶 和 华 使 约 书 亚 在 以 色 列 众 人 眼 前 尊 大 。 在 他 平 生 的 日 子 ， 百 姓 敬 畏 他 ， 像 从 前 敬 畏 摩 西 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5926', '6', '4', '15', '耶 和 华 晓 谕 约 书 亚 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5927', '6', '4', '16', '“ 你 吩 咐 抬 法 柜 的 祭 司 从 约 旦 河 里 上 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5928', '6', '4', '17', '约 书 亚 就 吩 咐 祭 司 说 ： “ 你 们 从 约 旦 河 里 上 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5929', '6', '4', '18', '抬 耶 和 华 约 柜 的 祭 司 从 约 旦 河 里 上 来 ， 脚 掌 刚 落 旱 地 ， 约 旦 河 的 水 就 流 到 原 处 ， 仍 旧 涨 过 两 岸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5930', '6', '4', '19', '正 月 初 十 日 ， 百 姓 从 约 旦 河 里 上 来 ， 就 在 吉 甲 ， 在 耶 利 哥 的 东 边 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5931', '6', '4', '20', '他 们 从 约 旦 河 中 取 来 的 那 十 二 块 石 头 ， 约 书 亚 就 立 在 吉 甲 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5932', '6', '4', '21', '对 以 色 列 人 说 ： “ 日 后 你 们 的 子 孙 问 他 们 的 父 亲 说 ： ‘ 这 些 石 头 是 什 么 意 思 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5933', '6', '4', '22', '你 们 就 告 诉 他 们 说 ： ‘ 以 色 列 人 曾 走 干 地 过 这 约 旦 河 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5934', '6', '4', '23', '因 为 耶 和 华 ─ ─ 你 们 的 神 在 你 们 前 面 使 约 旦 河 的 水 干 了 ， 等 着 你 们 过 来 ， 就 如 耶 和 华 ─ ─ 你 们 的 神 从 前 在 我 们 前 面 使 红 海 干 了 ， 等 着 我 们 过 来 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5935', '6', '4', '24', '要 使 地 上 万 民 都 知 道 ， 耶 和 华 的 手 大 有 能 力 ， 也 要 使 你 们 永 远 敬 畏 耶 和 华 ─ ─ 你 们 的 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5936', '6', '5', '1', '约 旦 河 西 亚 摩 利 人 的 诸 王 和 靠 海 迦 南 人 的 诸 王 ， 听 见 耶 和 华 在 以 色 列 人 前 面 使 约 旦 河 的 水 干 了 ， 等 到 我 们 过 去 ， 他 们 的 心 因 以 色 列 人 的 缘 故 就 消 化 了 ， 不 再 有 胆 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5937', '6', '5', '2', '＜ 在 吉 甲 行 割 礼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5938', '6', '5', '3', '约 书 亚 就 制 造 了 火 石 刀 ， 在 “ 除 皮 山 ” 那 里 给 以 色 列 人 行 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5939', '6', '5', '4', '约 书 亚 行 割 礼 的 缘 故 ， 是 因 为 从 埃 及 出 来 的 众 民 ， 就 是 一 切 能 打 仗 的 男 丁 ， 出 了 埃 及 以 后 ， 都 死 在 旷 野 的 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5940', '6', '5', '5', '因 为 出 来 的 众 民 都 受 过 割 礼 ； 惟 独 出 埃 及 以 后 、 在 旷 野 的 路 上 所 生 的 众 民 都 没 有 受 过 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5941', '6', '5', '6', '以 色 列 人 在 旷 野 走 了 四 十 年 ， 等 到 国 民 ， 就 是 出 埃 及 的 兵 丁 ， 都 消 灭 了 ， 因 为 他 们 没 有 听 从 耶 和 华 的 话 。 耶 和 华 曾 向 他 们 起 誓 ， 必 不 容 他 们 看 见 耶 和 华 向 他 们 列 祖 起 誓 、 应 许 赐 给 我 们 的 地 ， 就 是 流 奶 与 蜜 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5942', '6', '5', '7', '他 们 的 子 孙 ， 就 是 耶 和 华 所 兴 起 来 接 续 他 们 的 ， 都 没 有 受 过 割 礼 ； 因 为 在 路 上 没 有 给 他 们 行 割 礼 ， 约 书 亚 这 才 给 他 们 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5943', '6', '5', '8', '国 民 都 受 完 了 割 礼 ， 就 住 在 营 中 自 己 的 地 方 ， 等 到 痊 愈 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5944', '6', '5', '9', '耶 和 华 对 约 书 亚 说 ： “ 我 今 日 将 埃 及 的 羞 辱 从 你 们 身 上 滚 去 了 。 ” 因 此 ， 那 地 方 名 叫 吉 甲 ｛ 就 是 滚 的 意 思 ｝ ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5945', '6', '5', '10', '以 色 列 人 在 吉 甲 安 营 。 正 月 十 四 日 晚 上 ， 在 耶 利 哥 的 平 原 守 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5946', '6', '5', '11', '逾 越 节 的 次 日 ， 他 们 就 吃 了 那 地 的 出 产 ； 正 当 那 日 吃 无 酵 饼 和 烘 的 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5947', '6', '5', '12', '他 们 吃 了 那 地 的 出 产 ， 第 二 日 吗 哪 就 止 住 了 ， 以 色 列 人 也 不 再 有 吗 哪 了 。 那 一 年 ， 他 们 却 吃 迦 南 地 的 出 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5948', '6', '5', '13', '＜ 约 书 亚 和 耶 和 华 军 队 的 元 帅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5949', '6', '5', '14', '他 回 答 说 ： “ 不 是 的 ， 我 来 是 要 作 耶 和 华 军 队 的 元 帅 。 ” 约 书 亚 就 俯 伏 在 地 下 拜 ， 说 ： “ 我 主 有 什 么 话 吩 咐 仆 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5950', '6', '5', '15', '耶 和 华 军 队 的 元 帅 对 约 书 亚 说 ： “ 把 你 脚 上 的 鞋 脱 下 来 ， 因 为 你 所 站 的 地 方 是 圣 的 。 ” 约 书 亚 就 照 着 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5951', '6', '6', '1', '＜ 耶 利 哥 城 陷 落 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5952', '6', '6', '2', '耶 和 华 晓 谕 约 书 亚 说 ： “ 看 哪 ， 我 已 经 把 耶 利 哥 和 耶 利 哥 的 王 ， 并 大 能 的 勇 士 ， 都 交 在 你 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5953', '6', '6', '3', '你 们 的 一 切 兵 丁 要 围 绕 这 城 ， 一 日 围 绕 一 次 ， 六 日 都 要 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5954', '6', '6', '4', '七 个 祭 司 要 拿 七 个 羊 角 走 在 约 柜 前 。 到 第 七 日 ， 你 们 要 绕 城 七 次 ， 祭 司 也 要 吹 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5955', '6', '6', '5', '他 们 吹 的 角 声 拖 长 ， 你 们 听 见 角 声 ， 众 百 姓 要 大 声 呼 喊 ， 城 墙 就 必 塌 陷 ， 各 人 都 要 往 前 直 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5956', '6', '6', '6', '嫩 的 儿 子 约 书 亚 召 了 祭 司 来 ， 吩 咐 他 们 说 ： “ 你 们 抬 起 约 柜 来 ， 要 有 七 个 祭 司 拿 七 个 羊 角 走 在 耶 和 华 的 约 柜 前 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5957', '6', '6', '7', '又 对 百 姓 说 ： “ 你 们 前 去 绕 城 ， 带 兵 器 的 要 走 在 耶 和 华 的 约 柜 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5958', '6', '6', '8', '约 书 亚 对 百 姓 说 完 了 话 ， 七 个 祭 司 拿 七 个 羊 角 走 在 耶 和 华 面 前 吹 角 ； 耶 和 华 的 约 柜 在 他 们 后 面 跟 随 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5959', '6', '6', '9', '带 兵 器 的 走 在 吹 角 的 祭 司 前 面 ， 后 队 随 着 约 柜 行 。 祭 司 一 面 走 一 面 吹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5960', '6', '6', '10', '约 书 亚 吩 咐 百 姓 说 ： “ 你 们 不 可 呼 喊 ， 不 可 出 声 ， 连 一 句 话 也 不 可 出 你 们 的 口 ， 等 到 我 吩 咐 你 们 呼 喊 的 日 子 ， 那 时 才 可 以 呼 喊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5961', '6', '6', '11', '这 样 ， 他 使 耶 和 华 的 约 柜 绕 城 ， 把 城 绕 了 一 次 ； 众 人 回 到 营 里 ， 就 在 营 里 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5962', '6', '6', '12', '约 书 亚 清 早 起 来 ， 祭 司 又 抬 起 耶 和 华 的 约 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5963', '6', '6', '13', '七 个 祭 司 拿 七 个 羊 角 在 耶 和 华 的 约 柜 前 ， 时 常 行 走 吹 角 ； 带 兵 器 的 在 他 们 前 面 走 ， 后 队 随 着 耶 和 华 的 约 柜 行 。 祭 司 一 面 走 一 面 吹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5964', '6', '6', '14', '第 二 日 ， 众 人 把 城 绕 了 一 次 ， 就 回 营 里 去 。 六 日 都 是 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5965', '6', '6', '15', '第 七 日 清 早 ， 黎 明 的 时 候 ， 他 们 起 来 ， 照 样 绕 城 七 次 ； 惟 独 这 日 把 城 绕 了 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5966', '6', '6', '16', '到 了 第 七 次 ， 祭 司 吹 角 的 时 候 ， 约 书 亚 吩 咐 百 姓 说 ： “ 呼 喊 吧 ， 因 为 耶 和 华 已 经 把 城 交 给 你 们 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5967', '6', '6', '17', '这 城 和 其 中 所 有 的 都 要 在 耶 和 华 面 前 毁 灭 ； 只 有 妓 女 喇 合 与 她 家 中 所 有 的 可 以 存 活 ， 因 为 她 隐 藏 了 我 们 所 打 发 的 使 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5968', '6', '6', '18', '至 于 你 们 ， 务 要 谨 慎 ， 不 可 取 那 当 灭 的 物 ， 恐 怕 你 们 取 了 那 当 灭 的 物 就 连 累 以 色 列 的 全 营 ， 使 全 营 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5969', '6', '6', '19', '惟 有 金 子 、 银 子 ， 和 铜 铁 的 器 皿 都 要 归 耶 和 华 为 圣 ， 必 入 耶 和 华 的 库 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5970', '6', '6', '20', '于 是 百 姓 呼 喊 ， 祭 司 也 吹 角 。 百 姓 听 见 角 声 ， 便 大 声 呼 喊 ， 城 墙 就 塌 陷 ， 百 姓 便 上 去 进 城 ， 各 人 往 前 直 上 ， 将 城 夺 取 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5971', '6', '6', '21', '又 将 城 中 所 有 的 ， 不 拘 男 女 老 少 ， 牛 羊 和 驴 ， 都 用 刀 杀 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5972', '6', '6', '22', '约 书 亚 吩 咐 窥 探 地 的 两 个 人 说 ： “ 你 们 进 那 妓 女 的 家 ， 照 着 你 们 向 她 所 起 的 誓 ， 将 那 女 人 和 她 所 有 的 都 从 那 里 带 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5973', '6', '6', '23', '当 探 子 的 两 个 少 年 人 就 进 去 ， 将 喇 合 与 她 的 父 母 、 弟 兄 ， 和 她 所 有 的 ， 并 她 一 切 的 亲 眷 ， 都 带 出 来 ， 安 置 在 以 色 列 的 营 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5974', '6', '6', '24', '众 人 就 用 火 将 城 和 其 中 所 有 的 焚 烧 了 ； 惟 有 金 子 、 银 子 ， 和 铜 铁 的 器 皿 都 放 在 耶 和 华 殿 的 库 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5975', '6', '6', '25', '约 书 亚 却 把 妓 女 喇 合 与 她 父 家 ， 并 她 所 有 的 ， 都 救 活 了 ； 因 为 她 隐 藏 了 约 书 亚 所 打 发 窥 探 耶 利 哥 的 使 者 ， 她 就 住 在 以 色 列 中 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5976', '6', '6', '26', '当 时 ， 约 书 亚 叫 众 人 起 誓 说 ： “ 有 兴 起 重 修 这 耶 利 哥 城 的 人 ， 当 在 耶 和 华 面 前 受 咒 诅 。 他 立 根 基 的 时 候 ， 必 丧 长 子 ， 安 门 的 时 候 ， 必 丧 幼 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5977', '6', '6', '27', '耶 和 华 与 约 书 亚 同 在 ， 约 书 亚 的 声 名 传 扬 遍 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5978', '6', '7', '1', '＜ 亚 干 犯 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5979', '6', '7', '2', '当 下 ， 约 书 亚 从 耶 利 哥 打 发 人 往 伯 特 利 东 边 、 靠 近 伯 ． 亚 文 的 艾 城 去 ， 吩 咐 他 们 说 ： “ 你 们 上 去 窥 探 那 地 。 ” 他 们 就 上 去 窥 探 艾 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5980', '6', '7', '3', '他 们 回 到 约 书 亚 那 里 ， 对 他 说 ： “ 众 民 不 必 都 上 去 ， 只 要 二 三 千 人 上 去 就 能 攻 取 艾 城 ； 不 必 劳 累 众 民 都 去 ， 因 为 那 里 的 人 少 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5981', '6', '7', '4', '于 是 民 中 约 有 三 千 人 上 那 里 去 ， 竟 在 艾 城 人 面 前 逃 跑 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5982', '6', '7', '5', '艾 城 的 人 击 杀 了 他 们 三 十 六 人 ， 从 城 门 前 追 赶 他 们 ， 直 到 示 巴 琳 ， 在 下 坡 杀 败 他 们 ； 众 民 的 心 就 消 化 如 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5983', '6', '7', '6', '约 书 亚 便 撕 裂 衣 服 ； 他 和 以 色 列 的 长 老 把 灰 撒 在 头 上 ， 在 耶 和 华 的 约 柜 前 俯 伏 在 地 ， 直 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5984', '6', '7', '7', '约 书 亚 说 ： “ 哀 哉 ！ 主 耶 和 华 啊 ， 你 为 什 么 竟 领 这 百 姓 过 约 旦 河 ， 将 我 们 交 在 亚 摩 利 人 的 手 中 ， 使 我 们 灭 亡 呢 ？ 我 们 不 如 住 在 约 旦 河 那 边 倒 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5985', '6', '7', '8', '主 啊 ， 以 色 列 人 既 在 仇 敌 面 前 转 背 逃 跑 ， 我 还 有 什 么 可 说 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5986', '6', '7', '9', '迦 南 人 和 这 地 一 切 的 居 民 听 见 了 就 必 围 困 我 们 ， 将 我 们 的 名 从 地 上 除 灭 。 那 时 你 为 你 的 大 名 要 怎 样 行 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5987', '6', '7', '10', '耶 和 华 吩 咐 约 书 亚 说 ： “ 起 来 ！ 你 为 何 这 样 俯 伏 在 地 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5988', '6', '7', '11', '以 色 列 人 犯 了 罪 ， 违 背 了 我 所 吩 咐 他 们 的 约 ， 取 了 当 灭 的 物 ； 又 偷 窃 ， 又 行 诡 诈 ， 又 把 那 当 灭 的 放 在 他 们 的 家 具 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5989', '6', '7', '12', '因 此 ， 以 色 列 人 在 仇 敌 面 前 站 立 不 住 。 他 们 在 仇 敌 面 前 转 背 逃 跑 ， 是 因 成 了 被 咒 诅 的 ； 你 们 若 不 把 当 灭 的 物 从 你 们 中 间 除 掉 ， 我 就 不 再 与 你 们 同 在 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5990', '6', '7', '13', '你 起 来 ， 叫 百 姓 自 洁 ， 对 他 们 说 ： ‘ 你 们 要 自 洁 ， 预 备 明 天 ， 因 为 耶 和 华 ─ ─ 以 色 列 的 神 这 样 说 ： 以 色 列 啊 ， 你 们 中 间 有 当 灭 的 物 ， 你 们 若 不 除 掉 ， 在 仇 敌 面 前 必 站 立 不 住 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5991', '6', '7', '14', '到 了 早 晨 ， 你 们 要 按 着 支 派 近 前 来 ； 耶 和 华 所 取 的 支 派 ， 要 按 着 宗 族 近 前 来 ； 耶 和 华 所 取 的 宗 族 ， 要 按 着 家 室 近 前 来 ； 耶 和 华 所 取 的 家 室 ， 要 按 着 人 丁 ， 一 个 一 个 地 近 前 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5992', '6', '7', '15', '被 取 的 人 有 当 灭 的 物 在 他 那 里 ， 他 和 他 所 有 的 必 被 火 焚 烧 ； 因 他 违 背 了 耶 和 华 的 约 ， 又 因 他 在 以 色 列 中 行 了 愚 妄 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5993', '6', '7', '16', '于 是 ， 约 书 亚 清 早 起 来 ， 使 以 色 列 人 按 着 支 派 近 前 来 ， 取 出 来 的 是 犹 大 支 派 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5994', '6', '7', '17', '使 犹 大 支 派 ｛ 原 文 是 宗 族 ｝ 近 前 来 ， 就 取 了 谢 拉 的 宗 族 ； 使 谢 拉 的 宗 族 ， 按 着 家 室 人 丁 ， 一 个 一 个 地 近 前 来 ， 取 出 来 的 是 撒 底 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5995', '6', '7', '18', '使 撒 底 的 家 室 ， 按 着 人 丁 ， 一 个 一 个 地 近 前 来 ， 就 取 出 犹 大 支 派 的 人 谢 拉 的 曾 孙 ， 撒 底 的 孙 子 ， 迦 米 的 儿 子 亚 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5996', '6', '7', '19', '约 书 亚 对 亚 干 说 ： “ 我 儿 ， 我 劝 你 将 荣 耀 归 给 耶 和 华 ─ ─ 以 色 列 的 神 ， 在 他 面 前 认 罪 ， 将 你 所 做 的 事 告 诉 我 ， 不 要 向 我 隐 瞒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5997', '6', '7', '20', '亚 干 回 答 约 书 亚 说 ： “ 我 实 在 得 罪 了 耶 和 华 ─ ─ 以 色 列 的 神 。 我 所 做 的 事 如 此 如 此 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5998', '6', '7', '21', '我 在 所 夺 的 财 物 中 看 见 一 件 美 好 的 示 拿 衣 服 ， 二 百 舍 客 勒 银 子 ， 一 条 金 子 重 五 十 舍 客 勒 ， 我 就 贪 爱 这 些 物 件 ， 便 拿 去 了 。 现 今 藏 在 我 帐 棚 内 的 地 里 ， 银 子 在 衣 服 底 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('5999', '6', '7', '22', '约 书 亚 就 打 发 人 跑 到 亚 干 的 帐 棚 里 。 那 件 衣 服 果 然 藏 在 他 帐 棚 内 ， 银 子 在 底 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6000', '6', '7', '23', '他 们 就 从 帐 棚 里 取 出 来 ， 拿 到 约 书 亚 和 以 色 列 众 人 那 里 ， 放 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6001', '6', '7', '24', '约 书 亚 和 以 色 列 众 人 把 谢 拉 的 曾 孙 亚 干 和 那 银 子 、 那 件 衣 服 、 那 条 金 子 ， 并 亚 干 的 儿 女 、 牛 、 驴 、 羊 、 帐 棚 ， 以 及 他 所 有 的 ， 都 带 到 亚 割 谷 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6002', '6', '7', '25', '约 书 亚 说 ： “ 你 为 什 么 连 累 我 们 呢 ？ 今 日 耶 和 华 必 叫 你 受 连 累 。 ” 于 是 以 色 列 众 人 用 石 头 打 死 他 ， 将 石 头 扔 在 其 上 ， 又 用 火 焚 烧 他 所 有 的 ｛ 原 文 是 他 们 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6003', '6', '7', '26', '众 人 在 亚 干 身 上 堆 成 一 大 堆 石 头 ， 直 存 到 今 日 。 于 是 耶 和 华 转 意 ， 不 发 他 的 烈 怒 。 因 此 那 地 方 名 叫 亚 割 谷 ｛ 就 是 连 累 的 意 思 ｝ ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6004', '6', '8', '1', '＜ 攻 取 艾 城 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6005', '6', '8', '2', '你 怎 样 待 耶 利 哥 和 耶 利 哥 的 王 ， 也 当 照 样 待 艾 城 和 艾 城 的 王 。 只 是 城 内 所 夺 的 财 物 和 牲 畜 ， 你 们 可 以 取 为 自 己 的 掠 物 。 你 要 在 城 后 设 下 伏 兵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6006', '6', '8', '3', '于 是 ， 约 书 亚 和 一 切 兵 丁 都 起 来 ， 要 上 艾 城 去 。 约 书 亚 选 了 三 万 大 能 的 勇 士 ， 夜 间 打 发 他 们 前 往 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6007', '6', '8', '4', '吩 咐 他 们 说 ： “ 你 们 要 在 城 后 埋 伏 ， 不 可 离 城 太 远 ， 都 要 各 自 准 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6008', '6', '8', '5', '我 与 我 所 带 领 的 众 民 要 向 城 前 往 。 城 里 的 人 像 初 次 出 来 攻 击 我 们 的 时 候 ， 我 们 就 在 他 们 面 前 逃 跑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6009', '6', '8', '6', '他 们 必 出 来 追 赶 我 们 ， 直 到 我 们 引 诱 他 们 离 开 城 ； 因 为 他 们 必 说 ： ‘ 这 些 人 像 初 次 在 我 们 面 前 逃 跑 。 ’ 所 以 我 们 要 在 他 们 面 前 逃 跑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6010', '6', '8', '7', '你 们 就 从 埋 伏 的 地 方 起 来 ， 夺 取 那 城 ， 因 为 耶 和 华 ─ ─ 你 们 的 神 必 把 城 交 在 你 们 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6011', '6', '8', '8', '你 们 夺 了 城 以 后 ， 就 放 火 烧 城 ， 要 照 耶 和 华 的 话 行 。 这 是 我 吩 咐 你 们 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6012', '6', '8', '9', '约 书 亚 打 发 他 们 前 往 ， 他 们 就 上 埋 伏 的 地 方 去 ， 住 在 伯 特 利 和 艾 城 的 中 间 ， 就 是 在 艾 城 的 西 边 。 这 夜 约 书 亚 却 在 民 中 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6013', '6', '8', '10', '约 书 亚 清 早 起 来 ， 点 齐 百 姓 ， 他 和 以 色 列 的 长 老 在 百 姓 前 面 上 艾 城 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6014', '6', '8', '11', '众 民 ， 就 是 他 所 带 领 的 兵 丁 ， 都 上 去 ， 向 前 直 往 ， 来 到 城 前 ， 在 艾 城 北 边 安 营 。 在 约 书 亚 和 艾 城 中 间 有 一 山 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6015', '6', '8', '12', '他 挑 了 约 有 五 千 人 ， 使 他 们 埋 伏 在 伯 特 利 和 艾 城 的 中 间 ， 就 是 在 艾 城 的 西 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6016', '6', '8', '13', '于 是 安 置 了 百 姓 ， 就 是 城 北 的 全 军 和 城 西 的 伏 兵 。 这 夜 约 书 亚 进 入 山 谷 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6017', '6', '8', '14', '艾 城 的 王 看 见 这 景 况 ， 就 和 全 城 的 人 ， 清 早 急 忙 起 来 ， 按 所 定 的 时 候 ， 出 到 亚 拉 巴 前 ， 要 与 以 色 列 人 交 战 ； 王 却 不 知 道 在 城 后 有 伏 兵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6018', '6', '8', '15', '约 书 亚 和 以 色 列 众 人 在 他 们 面 前 装 败 ， 往 那 通 旷 野 的 路 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6019', '6', '8', '16', '城 内 的 众 民 都 被 招 聚 ， 追 赶 他 们 ； 艾 城 人 追 赶 的 时 候 ， 就 被 引 诱 离 开 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6020', '6', '8', '17', '艾 城 和 伯 特 利 城 没 有 一 人 不 出 来 追 赶 以 色 列 人 的 ， 撇 了 敞 开 的 城 门 ， 去 追 赶 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6021', '6', '8', '18', '耶 和 华 吩 咐 约 书 亚 说 ： “ 你 向 艾 城 伸 出 手 里 的 短 枪 ， 因 为 我 要 将 城 交 在 你 手 里 。 ” 约 书 亚 就 向 城 伸 出 手 里 的 短 枪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6022', '6', '8', '19', '他 一 伸 手 ， 伏 兵 就 从 埋 伏 的 地 方 急 忙 起 来 ， 夺 了 城 ， 跑 进 城 去 ， 放 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6023', '6', '8', '20', '艾 城 的 人 回 头 一 看 ， 不 料 ， 城 中 烟 气 冲 天 ， 他 们 就 无 力 向 左 向 右 逃 跑 。 那 往 旷 野 逃 跑 的 百 姓 便 转 身 攻 击 追 赶 他 们 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6024', '6', '8', '21', '约 书 亚 和 以 色 列 众 人 见 伏 兵 已 经 夺 了 城 ， 城 中 烟 气 飞 腾 ， 就 转 身 回 去 ， 击 杀 艾 城 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6025', '6', '8', '22', '伏 兵 也 出 城 迎 击 艾 城 人 ， 艾 城 人 就 困 在 以 色 列 人 中 间 ， 前 后 都 是 以 色 列 人 。 于 是 以 色 列 人 击 杀 他 们 ， 没 有 留 下 一 个 ， 也 没 有 一 个 逃 脱 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6026', '6', '8', '23', '生 擒 了 艾 城 的 王 ， 将 他 解 到 约 书 亚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6027', '6', '8', '24', '以 色 列 人 在 田 间 和 旷 野 杀 尽 所 追 赶 一 切 艾 城 的 居 民 。 艾 城 人 倒 在 刀 下 ， 直 到 灭 尽 ； 以 色 列 众 人 就 回 到 艾 城 ， 用 刀 杀 了 城 中 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6028', '6', '8', '25', '当 日 杀 毙 的 人 ， 连 男 带 女 共 有 一 万 二 千 ， 就 是 艾 城 所 有 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6029', '6', '8', '26', '约 书 亚 没 有 收 回 手 里 所 伸 出 来 的 短 枪 ， 直 到 把 艾 城 的 一 切 居 民 尽 行 杀 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6030', '6', '8', '27', '惟 独 城 中 的 牲 畜 和 财 物 ， 以 色 列 人 都 取 为 自 己 的 掠 物 ， 是 照 耶 和 华 所 吩 咐 约 书 亚 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6031', '6', '8', '28', '约 书 亚 将 艾 城 焚 烧 ， 使 城 永 为 高 堆 、 荒 场 ， 直 到 今 日 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6032', '6', '8', '29', '又 将 艾 城 王 挂 在 树 上 ， 直 到 晚 上 。 日 落 的 时 候 ， 约 书 亚 吩 咐 人 把 尸 首 从 树 上 取 下 来 ， 丢 在 城 门 口 ， 在 尸 首 上 堆 成 一 大 堆 石 头 ， 直 存 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6033', '6', '8', '30', '＜ 在 以 巴 路 山 上 宣 读 律 法 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6034', '6', '8', '31', '是 用 没 有 动 过 铁 器 的 整 石 头 筑 的 ， 照 着 耶 和 华 仆 人 摩 西 所 吩 咐 以 色 列 人 的 话 ， 正 如 摩 西 律 法 书 上 所 写 的 。 众 人 在 这 坛 上 给 耶 和 华 奉 献 燔 祭 和 平 安 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6035', '6', '8', '32', '约 书 亚 在 那 里 ， 当 着 以 色 列 人 面 前 ， 将 摩 西 所 写 的 律 法 抄 写 在 石 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6036', '6', '8', '33', '以 色 列 众 人 ， 无 论 是 本 地 人 、 是 寄 居 的 ， 和 长 老 、 官 长 ， 并 审 判 官 ， 都 站 在 约 柜 两 旁 ， 在 抬 耶 和 华 约 柜 的 祭 司 利 未 人 面 前 ， 一 半 对 着 基 利 心 山 ， 一 半 对 着 以 巴 路 山 ， 为 以 色 列 民 祝 福 ， 正 如 耶 和 华 仆 人 摩 西 先 前 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6037', '6', '8', '34', '随 后 ， 约 书 亚 将 律 法 上 祝 福 、 咒 诅 的 话 ， 照 着 律 法 书 上 一 切 所 写 的 ， 都 宣 读 了 一 遍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6038', '6', '8', '35', '摩 西 所 吩 咐 的 一 切 话 ， 约 书 亚 在 以 色 列 全 会 众 和 妇 女 、 孩 子 ， 并 他 们 中 间 寄 居 的 外 人 面 前 ， 没 有 一 句 不 宣 读 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6039', '6', '9', '1', '＜ 基 遍 人 欺 瞒 约 书 亚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6040', '6', '9', '2', '就 都 聚 集 ， 同 心 合 意 地 要 与 约 书 亚 和 以 色 列 人 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6041', '6', '9', '3', '基 遍 的 居 民 听 见 约 书 亚 向 耶 利 哥 和 艾 城 所 行 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6042', '6', '9', '4', '就 设 诡 计 ， 假 充 使 者 ， 拿 旧 口 袋 和 破 裂 缝 补 的 旧 皮 酒 袋 驮 在 驴 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6043', '6', '9', '5', '将 补 过 的 旧 鞋 穿 在 脚 上 ， 把 旧 衣 服 穿 在 身 上 ； 他 们 所 带 的 饼 都 是 干 的 ， 长 了 霉 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6044', '6', '9', '6', '他 们 到 吉 甲 营 中 见 约 书 亚 ， 对 他 和 以 色 列 人 说 ： “ 我 们 是 从 远 方 来 的 ， 现 在 求 你 与 我 们 立 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6045', '6', '9', '7', '以 色 列 人 对 这 些 希 未 人 说 ： “ 只 怕 你 们 是 住 在 我 们 中 间 的 ； 若 是 这 样 ， 怎 能 和 你 们 立 约 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6046', '6', '9', '8', '他 们 对 约 书 亚 说 ： “ 我 们 是 你 的 仆 人 。 ” 约 书 亚 问 他 们 说 ： “ 你 们 是 什 么 人 ？ 是 从 哪 里 来 的 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6047', '6', '9', '9', '他 们 回 答 说 ： “ 仆 人 从 极 远 之 地 而 来 ， 是 因 听 见 耶 和 华 ─ ─ 你 神 的 名 声 和 他 在 埃 及 所 行 的 一 切 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6048', '6', '9', '10', '并 他 向 约 旦 河 东 的 两 个 亚 摩 利 王 ， 就 是 希 实 本 王 西 宏 和 在 亚 斯 他 录 的 巴 珊 王 噩 一 切 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6049', '6', '9', '11', '我 们 的 长 老 和 我 们 那 地 的 一 切 居 民 对 我 们 说 ： ‘ 你 们 手 里 要 带 着 路 上 用 的 食 物 去 迎 接 以 色 列 人 ， 对 他 们 说 ： 我 们 是 你 们 的 仆 人 ； 现 在 求 你 们 与 我 们 立 约 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6050', '6', '9', '12', '我 们 出 来 要 往 你 们 这 里 来 的 日 子 ， 从 家 里 带 出 来 的 这 饼 还 是 热 的 ； 看 哪 ， 现 在 都 干 了 ， 长 了 霉 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6051', '6', '9', '13', '这 皮 酒 袋 ， 我 们 盛 酒 的 时 候 还 是 新 的 ； 看 哪 ， 现 在 已 经 破 裂 。 我 们 这 衣 服 和 鞋 ， 因 为 道 路 甚 远 ， 也 都 穿 旧 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6052', '6', '9', '14', '以 色 列 人 受 了 他 们 些 食 物 ， 并 没 有 求 问 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6053', '6', '9', '15', '于 是 约 书 亚 与 他 们 讲 和 ， 与 他 们 立 约 ， 容 他 们 活 着 ； 会 众 的 首 领 也 向 他 们 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6054', '6', '9', '16', '以 色 列 人 与 他 们 立 约 之 后 ， 过 了 三 天 才 听 见 他 们 是 近 邻 ， 住 在 以 色 列 人 中 间 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6055', '6', '9', '17', '以 色 列 人 起 行 ， 第 三 天 到 了 他 们 的 城 邑 ， 就 是 基 遍 、 基 非 拉 、 比 录 、 基 列 ． 耶 琳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6056', '6', '9', '18', '因 为 会 众 的 首 领 已 经 指 着 耶 和 华 ─ ─ 以 色 列 的 神 向 他 们 起 誓 ， 所 以 以 色 列 人 不 击 杀 他 们 ； 全 会 众 就 向 首 领 发 怨 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6057', '6', '9', '19', '众 首 领 对 全 会 众 说 ： “ 我 们 已 经 指 着 耶 和 华 ─ ─ 以 色 列 的 神 向 他 们 起 誓 ， 现 在 我 们 不 能 害 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6058', '6', '9', '20', '我 们 要 如 此 待 他 们 ， 容 他 们 活 着 ， 免 得 有 忿 怒 因 我 们 所 起 的 誓 临 到 我 们 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6059', '6', '9', '21', '首 领 又 对 会 众 说 ： “ 要 容 他 们 活 着 。 ” 于 是 他 们 为 全 会 众 作 了 劈 柴 挑 水 的 人 ， 正 如 首 领 对 他 们 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6060', '6', '9', '22', '约 书 亚 召 了 他 们 来 ， 对 他 们 说 ： “ 为 什 么 欺 哄 我 们 说 ‘ 我 们 离 你 们 甚 远 ’ 呢 ？ 其 实 你 们 是 住 在 我 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6061', '6', '9', '23', '现 在 你 们 是 被 咒 诅 的 ！ 你 们 中 间 的 人 必 断 不 了 作 奴 仆 ， 为 我 神 的 殿 作 劈 柴 挑 水 的 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6062', '6', '9', '24', '他 们 回 答 约 书 亚 说 ： “ 因 为 有 人 实 在 告 诉 你 的 仆 人 ， 耶 和 华 ─ ─ 你 的 神 曾 吩 咐 他 的 仆 人 摩 西 ， 把 这 全 地 赐 给 你 们 ， 并 在 你 们 面 前 灭 绝 这 地 的 一 切 居 民 ， 所 以 我 们 为 你 们 的 缘 故 甚 怕 丧 命 ， 就 行 了 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6063', '6', '9', '25', '现 在 我 们 在 你 手 中 ， 你 以 怎 样 待 我 们 为 善 为 正 ， 就 怎 样 做 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6064', '6', '9', '26', '于 是 约 书 亚 这 样 待 他 们 ， 救 他 们 脱 离 以 色 列 人 的 手 ， 以 色 列 人 就 没 有 杀 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6065', '6', '9', '27', '当 日 约 书 亚 使 他 们 在 耶 和 华 所 要 选 择 的 地 方 ， 为 会 众 和 耶 和 华 的 坛 作 劈 柴 挑 水 的 人 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6066', '6', '10', '1', '＜ 击 败 亚 摩 利 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6067', '6', '10', '2', '就 甚 惧 怕 ； 因 为 基 遍 是 一 座 大 城 ， 如 都 城 一 般 ， 比 艾 城 更 大 ， 并 且 城 内 的 人 都 是 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6068', '6', '10', '3', '所 以 耶 路 撒 冷 王 亚 多 尼 ． 洗 德 打 发 人 去 见 希 伯 仑 王 何 咸 、 耶 末 王 毗 兰 、 拉 吉 王 雅 非 亚 ， 和 伊 矶 伦 王 底 璧 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6069', '6', '10', '4', '“ 求 你 们 上 来 帮 助 我 ， 我 们 好 攻 打 基 遍 ， 因 为 他 们 与 约 书 亚 和 以 色 列 人 立 了 和 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6070', '6', '10', '5', '于 是 五 个 亚 摩 利 王 ， 就 是 耶 路 撒 冷 王 、 希 伯 仑 王 、 耶 末 王 、 拉 吉 王 、 伊 矶 伦 王 ， 大 家 聚 集 ， 率 领 他 们 的 众 军 上 去 ， 对 着 基 遍 安 营 ， 攻 打 基 遍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6071', '6', '10', '6', '基 遍 人 就 打 发 人 往 吉 甲 的 营 中 去 见 约 书 亚 ， 说 ： “ 你 不 要 袖 手 不 顾 你 的 仆 人 ， 求 你 速 速 上 来 拯 救 我 们 ， 帮 助 我 们 ， 因 为 住 山 地 亚 摩 利 人 的 诸 王 都 聚 集 攻 击 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6072', '6', '10', '7', '于 是 约 书 亚 和 他 一 切 兵 丁 ， 并 大 能 的 勇 士 ， 都 从 吉 甲 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6073', '6', '10', '8', '耶 和 华 对 约 书 亚 说 ： “ 不 要 怕 他 们 ； 因 为 我 已 将 他 们 交 在 你 手 里 ， 他 们 无 一 人 能 在 你 面 前 站 立 得 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6074', '6', '10', '9', '约 书 亚 就 终 夜 从 吉 甲 上 去 ， 猛 然 临 到 他 们 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6075', '6', '10', '10', '耶 和 华 使 他 们 在 以 色 列 人 面 前 溃 乱 。 约 书 亚 在 基 遍 大 大 地 杀 败 他 们 ， 追 赶 他 们 ， 在 伯 ． 和 仑 的 上 坡 路 击 杀 他 们 ， 直 到 亚 西 加 和 玛 基 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6076', '6', '10', '11', '他 们 在 以 色 列 人 面 前 逃 跑 ， 正 在 伯 ． 和 仑 下 坡 的 时 候 ， 耶 和 华 从 天 上 降 大 冰 雹 ｛ 原 文 是 石 头 ｝ 在 他 们 身 上 ， 直 降 到 亚 西 加 ， 打 死 他 们 。 被 冰 雹 打 死 的 ， 比 以 色 列 人 用 刀 杀 死 的 还 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6077', '6', '10', '12', '当 耶 和 华 将 亚 摩 利 人 交 付 以 色 列 人 的 日 子 ， 约 书 亚 就 祷 告 耶 和 华 ， 在 以 色 列 人 眼 前 说 ： 日 头 啊 ， 你 要 停 在 基 遍 ； 月 亮 啊 ， 你 要 止 在 亚 雅 仑 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6078', '6', '10', '13', '于 是 日 头 停 留 ， 月 亮 止 住 ， 直 等 国 民 向 敌 人 报 仇 。 这 事 岂 不 是 写 在 雅 煞 珥 书 上 吗 ？ 日 头 在 天 当 中 停 住 ， 不 急 速 下 落 ， 约 有 一 日 之 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6079', '6', '10', '14', '在 这 日 以 前 ， 这 日 以 后 ， 耶 和 华 听 人 的 祷 告 ， 没 有 像 这 日 的 ， 是 因 耶 和 华 为 以 色 列 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6080', '6', '10', '15', '约 书 亚 和 以 色 列 众 人 回 到 吉 甲 的 营 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6081', '6', '10', '16', '＜ 生 擒 亚 摩 利 的 五 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6082', '6', '10', '17', '有 人 告 诉 约 书 亚 说 ： “ 那 五 王 已 经 找 到 了 ， 都 藏 在 玛 基 大 洞 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6083', '6', '10', '18', '约 书 亚 说 ： “ 你 们 把 几 块 大 石 头 滚 到 洞 口 ， 派 人 看 守 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6084', '6', '10', '19', '你 们 却 不 可 耽 延 ， 要 追 赶 你 们 的 仇 敌 ， 击 杀 他 们 尽 后 边 的 人 ， 不 容 他 们 进 自 己 的 城 邑 ， 因 为 耶 和 华 ─ ─ 你 们 的 神 已 经 把 他 们 交 在 你 们 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6085', '6', '10', '20', '约 书 亚 和 以 色 列 人 大 大 杀 败 他 们 ， 直 到 将 他 们 灭 尽 ； 其 中 剩 下 的 人 都 进 了 坚 固 的 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6086', '6', '10', '21', '众 百 姓 就 安 然 回 玛 基 大 营 中 ， 到 约 书 亚 那 里 。 没 有 一 人 敢 向 以 色 列 人 饶 舌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6087', '6', '10', '22', '约 书 亚 说 ： “ 打 开 洞 口 ， 将 那 五 王 从 洞 里 带 出 来 ， 领 到 我 面 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6088', '6', '10', '23', '众 人 就 这 样 行 ， 将 那 五 王 ， 就 是 耶 路 撒 冷 王 、 希 伯 仑 王 、 耶 末 王 、 拉 吉 王 、 伊 矶 伦 王 ， 从 洞 里 带 出 来 ， 领 到 约 书 亚 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6089', '6', '10', '24', '带 出 那 五 王 到 约 书 亚 面 前 的 时 候 ， 约 书 亚 就 召 了 以 色 列 众 人 来 ， 对 那 些 和 他 同 去 的 军 长 说 ： “ 你 们 近 前 来 ， 把 脚 踏 在 这 些 王 的 颈 项 上 。 ” 他 们 就 近 前 来 ， 把 脚 踏 在 这 些 王 的 颈 项 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6090', '6', '10', '25', '约 书 亚 对 他 们 说 ： “ 你 们 不 要 惧 怕 ， 也 不 要 惊 惶 。 应 当 刚 强 壮 胆 ， 因 为 耶 和 华 必 这 样 待 你 们 所 要 攻 打 的 一 切 仇 敌 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6091', '6', '10', '26', '随 后 约 书 亚 将 这 五 王 杀 死 ， 挂 在 五 棵 树 上 。 他 们 就 在 树 上 直 挂 到 晚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6092', '6', '10', '27', '日 头 要 落 的 时 候 ， 约 书 亚 一 吩 咐 ， 人 就 把 尸 首 从 树 上 取 下 来 ， 丢 在 他 们 藏 过 的 洞 里 ， 把 几 块 大 石 头 放 在 洞 口 ， 直 存 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6093', '6', '10', '28', '＜ 约 书 亚 攻 取 更 多 的 城 邑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6094', '6', '10', '29', '约 书 亚 和 以 色 列 众 人 从 玛 基 大 往 立 拿 去 ， 攻 打 立 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6095', '6', '10', '30', '耶 和 华 将 立 拿 和 立 拿 的 王 也 交 在 以 色 列 人 手 里 。 约 书 亚 攻 打 这 城 ， 用 刀 击 杀 了 城 中 的 一 切 人 口 ， 没 有 留 下 一 个 。 他 待 立 拿 王 ， 像 从 前 待 耶 利 哥 王 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6096', '6', '10', '31', '约 书 亚 和 以 色 列 众 人 从 立 拿 往 拉 吉 去 ， 对 着 拉 吉 安 营 ， 攻 打 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6097', '6', '10', '32', '耶 和 华 将 拉 吉 交 在 以 色 列 人 的 手 里 。 第 二 天 约 书 亚 就 夺 了 拉 吉 ， 用 刀 击 杀 了 城 中 的 一 切 人 口 ， 是 照 他 向 立 拿 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6098', '6', '10', '33', '那 时 基 色 王 荷 兰 上 来 帮 助 拉 吉 ， 约 书 亚 就 把 他 和 他 的 民 都 击 杀 了 ， 没 有 留 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6099', '6', '10', '34', '约 书 亚 和 以 色 列 众 人 从 拉 吉 往 伊 矶 伦 去 ， 对 着 伊 矶 伦 安 营 ， 攻 打 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6100', '6', '10', '35', '当 日 就 夺 了 城 ， 用 刀 击 杀 了 城 中 的 人 。 那 日 ， 约 书 亚 将 城 中 的 一 切 人 口 尽 行 杀 灭 ， 是 照 他 向 拉 吉 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6101', '6', '10', '36', '约 书 亚 和 以 色 列 众 人 从 伊 矶 伦 上 希 伯 仑 去 ， 攻 打 这 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6102', '6', '10', '37', '就 夺 了 希 伯 仑 和 属 希 伯 仑 的 诸 城 邑 ， 用 刀 将 城 中 的 人 与 王 ， 并 那 些 城 邑 中 的 人 口 ， 都 击 杀 了 ， 没 有 留 下 一 个 ， 是 照 他 向 伊 矶 伦 所 行 的 ， 把 城 中 的 一 切 人 口 尽 行 杀 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6103', '6', '10', '38', '约 书 亚 和 以 色 列 众 人 回 到 底 璧 ， 攻 打 这 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6104', '6', '10', '39', '就 夺 了 底 璧 和 属 底 璧 的 城 邑 ， 又 擒 获 底 璧 的 王 ， 用 刀 将 这 些 城 中 的 人 口 尽 行 杀 灭 ， 没 有 留 下 一 个 。 他 待 底 璧 和 底 璧 王 ， 像 从 前 待 希 伯 仑 和 立 拿 与 立 拿 王 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6105', '6', '10', '40', '这 样 ， 约 书 亚 击 杀 全 地 的 人 ， 就 是 山 地 、 南 地 、 高 原 、 山 坡 的 人 ， 和 那 些 地 的 诸 王 ， 没 有 留 下 一 个 。 将 凡 有 气 息 的 尽 行 杀 灭 ， 正 如 耶 和 华 ─ ─ 以 色 列 的 神 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6106', '6', '10', '41', '约 书 亚 从 加 低 斯 ． 巴 尼 亚 攻 击 到 迦 萨 ， 又 攻 击 歌 珊 全 地 ， 直 到 基 遍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6107', '6', '10', '42', '约 书 亚 一 时 杀 败 了 这 些 王 ， 并 夺 了 他 们 的 地 ， 因 为 耶 和 华 ─ ─ 以 色 列 的 神 为 以 色 列 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6108', '6', '10', '43', '于 是 约 书 亚 和 以 色 列 众 人 回 到 吉 甲 的 营 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6109', '6', '11', '1', '＜ 约 书 亚 击 败 耶 宾 和 他 的 盟 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6110', '6', '11', '2', '与 北 方 山 地 、 基 尼 烈 南 边 的 亚 拉 巴 高 原 ， 并 西 边 多 珥 山 冈 的 诸 王 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6111', '6', '11', '3', '又 去 见 东 方 和 西 方 的 迦 南 人 ， 与 山 地 的 亚 摩 利 人 、 赫 人 、 比 利 洗 人 、 耶 布 斯 人 ， 并 黑 门 山 根 米 斯 巴 地 的 希 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6112', '6', '11', '4', '这 些 王 和 他 们 的 众 军 都 出 来 ， 人 数 多 如 海 边 的 沙 ， 并 有 许 多 马 匹 车 辆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6113', '6', '11', '5', '这 诸 王 会 合 ， 来 到 米 伦 水 边 ， 一 同 安 营 ， 要 与 以 色 列 人 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6114', '6', '11', '6', '耶 和 华 对 约 书 亚 说 ： “ 你 不 要 因 他 们 惧 怕 。 明 日 这 时 ， 我 必 将 他 们 交 付 以 色 列 人 全 然 杀 了 。 你 要 砍 断 他 们 马 的 蹄 筋 ， 用 火 焚 烧 他 们 的 车 辆 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6115', '6', '11', '7', '于 是 约 书 亚 率 领 一 切 兵 丁 ， 在 米 伦 水 边 突 然 向 前 攻 打 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6116', '6', '11', '8', '耶 和 华 将 他 们 交 在 以 色 列 人 手 里 ， 以 色 列 人 就 击 杀 他 们 ， 追 赶 他 们 到 西 顿 大 城 ， 到 米 斯 利 弗 ． 玛 音 ， 直 到 东 边 米 斯 巴 的 平 原 ， 将 他 们 击 杀 ， 没 有 留 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6117', '6', '11', '9', '约 书 亚 就 照 耶 和 华 所 吩 咐 他 的 去 行 ， 砍 断 他 们 马 的 蹄 筋 ， 用 火 焚 烧 他 们 的 车 辆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6118', '6', '11', '10', '当 时 ， 约 书 亚 转 回 夺 了 夏 琐 ， 用 刀 击 杀 夏 琐 王 。 （ 素 来 夏 琐 在 这 诸 国 中 是 为 首 的 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6119', '6', '11', '11', '以 色 列 人 用 刀 击 杀 城 中 的 人 口 ， 将 他 们 尽 行 杀 灭 ； 凡 有 气 息 的 没 有 留 下 一 个 。 约 书 亚 又 用 火 焚 烧 夏 琐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6120', '6', '11', '12', '约 书 亚 夺 了 这 些 王 的 一 切 城 邑 ， 擒 获 其 中 的 诸 王 ， 用 刀 击 杀 他 们 ， 将 他 们 尽 行 杀 灭 ， 正 如 耶 和 华 仆 人 摩 西 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6121', '6', '11', '13', '至 于 造 在 山 冈 上 的 城 ， 除 了 夏 琐 以 外 ， 以 色 列 人 都 没 有 焚 烧 。 约 书 亚 只 将 夏 琐 焚 烧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6122', '6', '11', '14', '那 些 城 邑 所 有 的 财 物 和 牲 畜 ， 以 色 列 人 都 取 为 自 己 的 掠 物 ； 惟 有 一 切 人 口 都 用 刀 击 杀 ， 直 到 杀 尽 ； 凡 有 气 息 的 没 有 留 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6123', '6', '11', '15', '耶 和 华 怎 样 吩 咐 他 仆 人 摩 西 ， 摩 西 就 照 样 吩 咐 约 书 亚 ， 约 书 亚 也 照 样 行 。 凡 耶 和 华 所 吩 咐 摩 西 的 ， 约 书 亚 没 有 一 件 懈 怠 不 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6124', '6', '11', '16', '＜ 约 书 亚 占 领 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6125', '6', '11', '17', '从 上 西 珥 的 哈 拉 山 ， 直 到 黑 门 山 下 黎 巴 嫩 平 原 的 巴 力 ． 迦 得 ， 并 且 擒 获 那 些 地 的 诸 王 ， 将 他 们 杀 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6126', '6', '11', '18', '约 书 亚 和 这 诸 王 争 战 了 许 多 年 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6127', '6', '11', '19', '除 了 基 遍 的 希 未 人 之 外 ， 没 有 一 城 与 以 色 列 人 讲 和 的 ， 都 是 以 色 列 人 争 战 夺 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6128', '6', '11', '20', '因 为 耶 和 华 的 意 思 是 要 使 他 们 心 里 刚 硬 ， 来 与 以 色 列 人 争 战 ， 好 叫 他 们 尽 被 杀 灭 ， 不 蒙 怜 悯 ， 正 如 耶 和 华 所 吩 咐 摩 西 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6129', '6', '11', '21', '当 时 约 书 亚 来 到 ， 将 住 山 地 、 希 伯 仑 、 底 璧 、 亚 拿 伯 、 犹 大 山 地 、 以 色 列 山 地 所 有 的 亚 衲 族 人 剪 除 了 。 约 书 亚 将 他 们 和 他 们 的 城 邑 尽 都 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6130', '6', '11', '22', '在 以 色 列 人 的 地 没 有 留 下 一 个 亚 衲 族 人 ， 只 在 迦 萨 、 迦 特 ， 和 亚 实 突 有 留 下 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6131', '6', '11', '23', '这 样 ， 约 书 亚 照 着 耶 和 华 所 吩 咐 摩 西 的 一 切 话 夺 了 那 全 地 ， 就 按 着 以 色 列 支 派 的 宗 族 将 地 分 给 他 们 为 业 。 于 是 国 中 太 平 ， 没 有 争 战 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6132', '6', '12', '1', '＜ 摩 西 击 败 的 诸 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6133', '6', '12', '2', '这 二 王 ， 有 住 希 实 本 、 亚 摩 利 人 的 王 西 宏 。 他 所 管 之 地 是 从 亚 嫩 谷 边 的 亚 罗 珥 和 谷 中 的 城 ， 并 基 列 一 半 ， 直 到 亚 扪 人 的 境 界 ， 雅 博 河');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6134', '6', '12', '3', '与 约 旦 河 东 边 的 亚 拉 巴 ， 直 到 基 尼 烈 海 ， 又 到 亚 拉 巴 的 海 ， 就 是 盐 海 ， 通 伯 ． 耶 西 末 的 路 ， 以 及 南 方 ， 直 到 毗 斯 迦 的 山 根 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6135', '6', '12', '4', '又 有 巴 珊 王 噩 。 他 是 利 乏 音 人 所 剩 下 的 ， 住 在 亚 斯 他 录 和 以 得 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6136', '6', '12', '5', '他 所 管 之 地 是 黑 门 山 、 撒 迦 、 巴 珊 全 地 ， 直 到 基 述 人 和 玛 迦 人 的 境 界 ， 并 基 列 一 半 ， 直 到 希 实 本 王 西 宏 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6137', '6', '12', '6', '这 二 王 是 耶 和 华 仆 人 摩 西 和 以 色 列 人 所 击 杀 的 ； 耶 和 华 仆 人 摩 西 将 他 们 的 地 赐 给 吕 便 人 、 迦 得 人 ， 和 玛 拿 西 半 支 派 的 人 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6138', '6', '12', '7', '＜ 约 书 亚 击 败 的 诸 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6139', '6', '12', '8', '就 是 赫 人 、 亚 摩 利 人 、 迦 南 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 的 山 地 、 高 原 亚 拉 巴 、 山 坡 、 旷 野 ， 和 南 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6140', '6', '12', '9', '他 们 的 王 ： 一 个 是 耶 利 哥 王 ， 一 个 是 靠 近 伯 特 利 的 艾 城 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6141', '6', '12', '10', '一 个 是 耶 路 撒 冷 王 ， 一 个 是 希 伯 仑 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6142', '6', '12', '11', '一 个 是 耶 末 王 ， 一 个 是 拉 吉 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6143', '6', '12', '12', '一 个 是 伊 矶 伦 王 ， 一 个 是 基 色 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6144', '6', '12', '13', '一 个 是 底 璧 王 ， 一 个 是 基 德 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6145', '6', '12', '14', '一 个 是 何 珥 玛 王 ， 一 个 是 亚 拉 得 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6146', '6', '12', '15', '一 个 是 立 拿 王 ， 一 个 是 亚 杜 兰 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6147', '6', '12', '16', '一 个 是 玛 基 大 王 ， 一 个 是 伯 特 利 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6148', '6', '12', '17', '一 个 是 他 普 亚 王 ， 一 个 是 希 弗 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6149', '6', '12', '18', '一 个 是 亚 弗 王 ， 一 个 是 拉 沙 仑 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6150', '6', '12', '19', '一 个 是 玛 顿 王 ， 一 个 是 夏 琐 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6151', '6', '12', '20', '一 个 是 伸 仑 ． 米 仑 王 ， 一 个 是 押 煞 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6152', '6', '12', '21', '一 个 是 他 纳 王 ， 一 个 是 米 吉 多 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6153', '6', '12', '22', '一 个 是 基 低 斯 王 ， 一 个 是 靠 近 迦 密 的 约 念 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6154', '6', '12', '23', '一 个 是 多 珥 山 冈 的 多 珥 王 ， 一 个 是 吉 甲 的 戈 印 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6155', '6', '12', '24', '一 个 是 得 撒 王 ； 共 计 三 十 一 个 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6156', '6', '13', '1', '＜ 尚 未 占 领 之 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6157', '6', '13', '2', '就 是 非 利 士 人 的 全 境 和 基 述 人 的 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6158', '6', '13', '3', '从 埃 及 前 的 西 曷 河 往 北 ， 直 到 以 革 伦 的 境 界 ， 就 算 属 迦 南 人 之 地 。 有 非 利 士 人 五 个 首 领 所 管 的 迦 萨 人 、 亚 实 突 人 、 亚 实 基 伦 人 、 迦 特 人 、 以 革 伦 人 之 地 ， 并 有 南 方 亚 卫 人 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6159', '6', '13', '4', '又 有 迦 南 人 的 全 地 ， 并 属 西 顿 人 的 米 亚 拉 到 亚 弗 ， 直 到 亚 摩 利 人 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6160', '6', '13', '5', '还 有 迦 巴 勒 人 之 地 ， 并 向 日 出 的 全 黎 巴 嫩 ， 就 是 从 黑 门 山 根 的 巴 力 ． 迦 得 ， 直 到 哈 马 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6161', '6', '13', '6', '山 地 的 一 切 居 民 ， 从 黎 巴 嫩 直 到 米 斯 利 弗 ． 玛 音 ， 就 是 所 有 的 西 顿 人 ， 我 必 在 以 色 列 人 面 前 赶 出 他 们 去 。 你 只 管 照 我 所 吩 咐 的 ， 将 这 地 拈 阄 分 给 以 色 列 人 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6162', '6', '13', '7', '现 在 你 要 把 这 地 分 给 九 个 支 派 和 玛 拿 西 半 个 支 派 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6163', '6', '13', '8', '＜ 分 配 约 旦 河 东 之 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6164', '6', '13', '9', '是 从 亚 嫩 谷 边 的 亚 罗 珥 和 谷 中 的 城 ， 并 米 底 巴 的 全 平 原 ， 直 到 底 本 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6165', '6', '13', '10', '和 在 希 实 本 作 王 亚 摩 利 王 西 宏 的 诸 城 ， 直 到 亚 扪 人 的 境 界 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6166', '6', '13', '11', '又 有 基 列 地 、 基 述 人 、 玛 迦 人 的 地 界 ， 并 黑 门 全 山 、 巴 珊 全 地 ， 直 到 撒 迦 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6167', '6', '13', '12', '又 有 巴 珊 王 噩 的 全 国 ─ ─ 他 在 亚 斯 他 录 和 以 得 来 作 王 （ 利 乏 音 人 所 存 留 的 只 剩 下 他 ） 。 这 些 地 的 人 都 是 摩 西 所 击 杀 、 所 赶 逐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6168', '6', '13', '13', '以 色 列 人 却 没 有 赶 逐 基 述 人 、 玛 迦 人 ； 这 些 人 仍 住 在 以 色 列 中 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6169', '6', '13', '14', '只 是 利 未 支 派 ， 摩 西 ｛ 原 文 是 他 ｝ 没 有 把 产 业 分 给 他 们 。 他 们 的 产 业 乃 是 献 与 耶 和 华 ─ ─ 以 色 列 神 的 火 祭 ， 正 如 耶 和 华 所 应 许 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6170', '6', '13', '15', '＜ 分 给 吕 便 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6171', '6', '13', '16', '他 们 的 境 界 是 亚 嫩 谷 边 的 亚 罗 珥 和 谷 中 的 城 ， 靠 近 米 底 巴 的 全 平 原 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6172', '6', '13', '17', '希 实 本 并 属 希 实 本 平 原 的 各 城 ， 底 本 、 巴 末 ． 巴 力 、 伯 ． 巴 力 ． 勉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6173', '6', '13', '18', '雅 杂 、 基 底 莫 、 米 法 押 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6174', '6', '13', '19', '基 列 亭 、 西 比 玛 、 谷 中 山 的 细 列 哈 ． 沙 辖 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6175', '6', '13', '20', '伯 ． 毗 珥 、 毗 斯 迦 山 坡 、 伯 ． 耶 西 末 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6176', '6', '13', '21', '平 原 的 各 城 ， 并 亚 摩 利 王 西 宏 的 全 国 。 这 西 宏 曾 在 希 实 本 作 王 ， 摩 西 把 他 和 米 甸 的 族 长 以 未 、 利 金 、 苏 珥 、 户 珥 、 利 巴 击 杀 了 ； 这 都 是 住 那 地 属 西 宏 为 首 领 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6177', '6', '13', '22', '那 时 以 色 列 人 在 所 杀 的 人 中 ， 也 用 刀 杀 了 比 珥 的 儿 子 术 士 巴 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6178', '6', '13', '23', '吕 便 人 的 境 界 就 是 约 旦 河 与 靠 近 约 旦 河 的 地 。 以 上 是 吕 便 人 按 着 宗 族 所 得 为 业 的 诸 城 ， 并 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6179', '6', '13', '24', '＜ 分 给 迦 得 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6180', '6', '13', '25', '他 们 的 境 界 是 雅 谢 和 基 列 的 各 城 ， 并 亚 扪 人 的 一 半 地 ， 直 到 拉 巴 前 的 亚 罗 珥 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6181', '6', '13', '26', '从 希 实 本 到 拉 抹 ． 米 斯 巴 和 比 多 宁 ， 又 从 玛 哈 念 到 底 璧 的 境 界 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6182', '6', '13', '27', '并 谷 中 的 伯 ． 亚 兰 、 伯 ． 宁 拉 、 疏 割 、 撒 分 ， 就 是 希 实 本 王 西 宏 国 中 的 余 地 ， 以 及 约 旦 河 与 靠 近 约 旦 河 的 地 ， 直 到 基 尼 烈 海 的 极 边 ， 都 在 约 旦 河 东 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6183', '6', '13', '28', '以 上 是 迦 得 人 按 着 宗 族 所 得 为 业 的 诸 城 ， 并 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6184', '6', '13', '29', '＜ 分 给 玛 拿 西 半 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6185', '6', '13', '30', '他 们 的 境 界 是 从 玛 哈 念 起 ， 包 括 巴 珊 全 地 ， 就 是 巴 珊 王 噩 的 全 国 ， 并 在 巴 珊 、 睚 珥 的 一 切 城 邑 ， 共 六 十 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6186', '6', '13', '31', '基 列 的 一 半 ， 并 亚 斯 他 录 、 以 得 来 ， 就 是 属 巴 珊 王 噩 国 的 二 城 ， 是 按 着 宗 族 给 玛 拿 西 的 儿 子 玛 吉 的 一 半 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6187', '6', '13', '32', '以 上 是 摩 西 在 约 旦 河 东 对 着 耶 利 哥 的 摩 押 平 原 所 分 给 他 们 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6188', '6', '13', '33', '只 是 利 未 支 派 ， 摩 西 没 有 把 产 业 分 给 他 们 。 耶 和 华 ─ ─ 以 色 列 的 神 是 他 们 的 产 业 ， 正 如 耶 和 华 所 应 许 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6189', '6', '14', '1', '＜ 分 配 约 旦 河 西 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6190', '6', '14', '2', '是 照 耶 和 华 藉 摩 西 所 吩 咐 的 ， 把 产 业 拈 阄 分 给 九 个 半 支 派 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6191', '6', '14', '3', '原 来 ， 摩 西 在 约 旦 河 东 已 经 把 产 业 分 给 那 两 个 半 支 派 ， 只 是 在 他 们 中 间 没 有 把 产 业 分 给 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6192', '6', '14', '4', '因 为 约 瑟 的 子 孙 是 两 个 支 派 ， 就 是 玛 拿 西 和 以 法 莲 ， 所 以 没 有 把 地 分 给 利 未 人 ， 但 给 他 们 城 邑 居 住 ， 并 城 邑 的 郊 野 ， 可 以 牧 养 他 们 的 牲 畜 ， 安 置 他 们 的 财 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6193', '6', '14', '5', '耶 和 华 怎 样 吩 咐 摩 西 ， 以 色 列 人 就 照 样 行 ， 把 地 分 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6194', '6', '14', '6', '＜ 迦 勒 得 希 伯 仑 为 业 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6195', '6', '14', '7', '耶 和 华 的 仆 人 摩 西 从 加 低 斯 ． 巴 尼 亚 打 发 我 窥 探 这 地 ， 那 时 我 正 四 十 岁 ； 我 按 着 心 意 回 报 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6196', '6', '14', '8', '然 而 ， 同 我 上 去 的 众 弟 兄 使 百 姓 的 心 消 化 ； 但 我 专 心 跟 从 耶 和 华 ─ ─ 我 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6197', '6', '14', '9', '当 日 摩 西 起 誓 说 ： ‘ 你 脚 所 踏 之 地 定 要 归 你 和 你 的 子 孙 永 远 为 业 ， 因 为 你 专 心 跟 从 耶 和 华 ─ ─ 我 的 神 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6198', '6', '14', '10', '自 从 耶 和 华 对 摩 西 说 这 话 的 时 候 ， 耶 和 华 照 他 所 应 许 的 使 我 存 活 这 四 十 五 年 ； 其 间 以 色 列 人 在 旷 野 行 走 。 看 哪 ， 现 今 我 八 十 五 岁 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6199', '6', '14', '11', '我 还 是 强 壮 ， 像 摩 西 打 发 我 去 的 那 天 一 样 ； 无 论 是 争 战 ， 是 出 入 ， 我 的 力 量 那 时 如 何 ， 现 在 还 是 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6200', '6', '14', '12', '求 你 将 耶 和 华 那 日 应 许 我 的 这 山 地 给 我 ； 那 里 有 亚 衲 族 人 ， 并 宽 大 坚 固 的 城 ， 你 也 曾 听 见 了 。 或 者 耶 和 华 照 他 所 应 许 的 与 我 同 在 ， 我 就 把 他 们 赶 出 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6201', '6', '14', '13', '于 是 约 书 亚 为 耶 孚 尼 的 儿 子 迦 勒 祝 福 ， 将 希 伯 仑 给 他 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6202', '6', '14', '14', '所 以 希 伯 仑 作 了 基 尼 洗 族 耶 孚 尼 的 儿 子 迦 勒 的 产 业 ， 直 到 今 日 ， 因 为 他 专 心 跟 从 耶 和 华 ─ ─ 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6203', '6', '14', '15', '希 伯 仑 从 前 名 叫 基 列 ． 亚 巴 ； 亚 巴 是 亚 衲 族 中 最 尊 大 的 人 。 于 是 国 中 太 平 ， 没 有 争 战 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6204', '6', '15', '1', '＜ 分 给 犹 大 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6205', '6', '15', '2', '他 们 的 南 界 是 从 盐 海 的 尽 边 ， 就 是 从 朝 南 的 海 汊 起 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6206', '6', '15', '3', '通 到 亚 克 拉 滨 坡 的 南 边 ， 接 连 到 寻 ， 上 到 加 低 斯 ． 巴 尼 亚 的 南 边 ， 又 过 希 斯 仑 ， 上 到 亚 达 珥 ， 绕 到 甲 加 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6207', '6', '15', '4', '接 连 到 押 们 ， 通 到 埃 及 小 河 ， 直 通 到 海 为 止 。 这 就 是 他 们 的 南 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6208', '6', '15', '5', '东 界 是 从 盐 海 南 边 到 约 旦 河 口 。 北 界 是 从 约 旦 河 口 的 海 汊 起 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6209', '6', '15', '6', '上 到 伯 ． 曷 拉 ， 过 伯 ． 亚 拉 巴 的 北 边 ， 上 到 吕 便 之 子 波 罕 的 磐 石 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6210', '6', '15', '7', '从 亚 割 谷 往 北 ， 上 到 底 璧 ， 直 向 河 南 亚 都 冥 坡 对 面 的 吉 甲 ； 又 接 连 到 隐 ． 示 麦 泉 ， 直 通 到 隐 ． 罗 结 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6211', '6', '15', '8', '上 到 欣 嫩 子 谷 ， 贴 近 耶 布 斯 的 南 界 （ 耶 布 斯 就 是 耶 路 撒 冷 ） ； 又 上 到 欣 嫩 谷 西 边 的 山 顶 ， 就 是 在 利 乏 音 谷 极 北 的 边 界 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6212', '6', '15', '9', '又 从 山 顶 延 到 尼 弗 多 亚 的 水 源 ， 通 到 以 弗 仑 山 的 城 邑 ， 又 延 到 巴 拉 （ 巴 拉 就 是 基 列 ． 耶 琳 ） ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6213', '6', '15', '10', '又 从 巴 拉 往 西 绕 到 西 珥 山 ， 接 连 到 耶 琳 山 的 北 边 （ 耶 琳 就 是 基 撒 仑 ） ； 又 下 到 伯 ． 示 麦 过 亭 纳 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6214', '6', '15', '11', '通 到 以 革 伦 北 边 ， 延 到 施 基 仑 ， 接 连 到 巴 拉 山 ； 又 通 到 雅 比 聂 ， 直 通 到 海 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6215', '6', '15', '12', '西 界 就 是 大 海 和 靠 近 大 海 之 地 。 这 是 犹 大 人 按 着 宗 族 所 得 之 地 四 围 的 交 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6216', '6', '15', '13', '＜ 迦 勒 攻 取 希 伯 仑 和 底 璧 （ 士   1 ： 1 1 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6217', '6', '15', '14', '迦 勒 就 从 那 里 赶 出 亚 衲 族 的 三 个 族 长 ， 就 是 示 筛 、 亚 希 幔 、 挞 买 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6218', '6', '15', '15', '又 从 那 里 上 去 ， 攻 击 底 璧 的 居 民 。 （ 这 底 璧 从 前 名 叫 基 列 ． 西 弗 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6219', '6', '15', '16', '迦 勒 说 ： “ 谁 能 攻 打 基 列 ． 西 弗 将 城 夺 取 ， 我 就 把 我 女 儿 押 撒 给 他 为 妻 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6220', '6', '15', '17', '迦 勒 兄 弟 基 纳 斯 的 儿 子 俄 陀 聂 夺 取 了 那 城 ， 迦 勒 就 把 女 儿 押 撒 给 他 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6221', '6', '15', '18', '押 撒 过 门 的 时 候 ， 劝 丈 夫 向 她 父 亲 求 一 块 田 ， 押 撒 一 下 驴 ， 迦 勒 问 她 说 ： “ 你 要 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6222', '6', '15', '19', '她 说 ： “ 求 你 赐 福 给 我 ， 你 既 将 我 安 置 在 南 地 ， 求 你 也 给 我 水 泉 。 ” 她 父 亲 就 把 上 泉 下 泉 赐 给 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6223', '6', '15', '20', '＜ 犹 大 所 得 的 城 邑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6224', '6', '15', '21', '犹 大 支 派 尽 南 边 的 城 邑 ， 与 以 东 交 界 相 近 的 ， 就 是 甲 薛 、 以 得 、 雅 姑 珥 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6225', '6', '15', '22', '基 拿 、 底 摩 拿 、 亚 大 达 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6226', '6', '15', '23', '基 低 斯 、 夏 琐 、 以 提 楠 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6227', '6', '15', '24', '西 弗 、 提 炼 、 比 亚 绿 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6228', '6', '15', '25', '夏 琐 ． 哈 大 他 、 加 略 ． 希 斯 仑 （ 加 略 ． 希 斯 仑 就 是 夏 琐 ） 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6229', '6', '15', '26', '亚 曼 、 示 玛 、 摩 拉 大 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6230', '6', '15', '27', '哈 萨 ． 迦 大 、 黑 实 门 、 伯 ． 帕 列 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6231', '6', '15', '28', '哈 萨 ． 书 亚 、 别 是 巴 、 比 斯 约 他 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6232', '6', '15', '29', '巴 拉 、 以 因 、 以 森 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6233', '6', '15', '30', '伊 勒 多 腊 、 基 失 、 何 珥 玛 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6234', '6', '15', '31', '洗 革 拉 、 麦 玛 拿 、 三 撒 拿 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6235', '6', '15', '32', '利 巴 勿 、 实 忻 、 亚 因 、 临 门 ， 共 二 十 九 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6236', '6', '15', '33', '在 高 原 有 以 实 陶 、 琐 拉 、 亚 实 拿 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6237', '6', '15', '34', '撒 挪 亚 、 隐 ． 干 宁 、 他 普 亚 、 以 楠 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6238', '6', '15', '35', '耶 末 、 亚 杜 兰 、 梭 哥 、 亚 西 加 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6239', '6', '15', '36', '沙 拉 音 、 亚 底 他 音 、 基 底 拉 、 基 底 罗 他 音 ， 共 十 四 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6240', '6', '15', '37', '又 有 洗 楠 、 哈 大 沙 、 麦 大 ． 迦 得 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6241', '6', '15', '38', '底 连 、 米 斯 巴 、 约 帖 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6242', '6', '15', '39', '拉 吉 、 波 斯 加 、 伊 矶 伦 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6243', '6', '15', '40', '迦 本 、 拉 幔 、 基 提 利 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6244', '6', '15', '41', '基 低 罗 、 伯 ． 大 衮 、 拿 玛 、 玛 基 大 ， 共 十 六 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6245', '6', '15', '42', '又 有 立 拿 、 以 帖 、 亚 珊 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6246', '6', '15', '43', '益 弗 他 、 亚 实 拿 、 尼 悉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6247', '6', '15', '44', '基 伊 拉 、 亚 革 悉 、 玛 利 沙 ， 共 九 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6248', '6', '15', '45', '又 有 以 革 伦 和 属 以 革 伦 的 镇 市 村 庄 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6249', '6', '15', '46', '从 以 革 伦 直 到 海 ， 一 切 靠 近 亚 实 突 之 地 ， 并 属 其 地 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6250', '6', '15', '47', '亚 实 突 和 属 亚 实 突 的 镇 市 村 庄 ； 迦 萨 和 属 迦 萨 的 镇 市 村 庄 ； 直 到 埃 及 小 河 ， 并 大 海 和 靠 近 大 海 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6251', '6', '15', '48', '在 山 地 有 沙 密 、 雅 提 珥 、 梭 哥 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6252', '6', '15', '49', '大 拿 、 基 列 ． 萨 拿 （ 基 列 ． 萨 拿 就 是 底 璧 ） 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6253', '6', '15', '50', '亚 拿 伯 、 以 实 提 莫 、 亚 念 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6254', '6', '15', '51', '歌 珊 、 何 伦 、 基 罗 ， 共 十 一 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6255', '6', '15', '52', '又 有 亚 拉 、 度 玛 、 以 珊 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6256', '6', '15', '53', '雅 农 、 伯 ． 他 普 亚 、 亚 非 加 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6257', '6', '15', '54', '宏 他 、 基 列 ． 亚 巴 （ 基 列 ． 亚 巴 就 是 希 伯 仑 ） 、 洗 珥 ， 共 九 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6258', '6', '15', '55', '又 有 玛 云 、 迦 密 、 西 弗 、 淤 他 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6259', '6', '15', '56', '耶 斯 列 、 约 甸 、 撒 挪 亚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6260', '6', '15', '57', '该 隐 、 基 比 亚 、 亭 纳 ， 共 十 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6261', '6', '15', '58', '又 有 哈 忽 、 伯 ． 夙 、 基 突 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6262', '6', '15', '59', '玛 腊 、 伯 ． 亚 诺 、 伊 勒 提 君 ， 共 六 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6263', '6', '15', '60', '又 有 基 列 ． 巴 力 （ 基 列 ． 巴 力 就 是 基 列 ． 耶 琳 ） 、 拉 巴 ， 共 两 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6264', '6', '15', '61', '在 旷 野 有 伯 ． 亚 拉 巴 、 密 丁 、 西 迦 迦 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6265', '6', '15', '62', '匿 珊 、 盐 城 、 隐 ． 基 底 ， 共 六 座 城 ， 还 有 属 城 的 村 庄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6266', '6', '15', '63', '至 于 住 耶 路 撒 冷 的 耶 布 斯 人 ， 犹 大 人 不 能 把 他 们 赶 出 去 ， 耶 布 斯 人 却 在 耶 路 撒 冷 与 犹 大 人 同 住 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6267', '6', '16', '1', '＜ 分 给 以 法 莲 支 派 和 玛 拿 西 半 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6268', '6', '16', '2', '又 从 伯 特 利 到 路 斯 ， 接 连 到 亚 基 人 的 境 界 ， 至 亚 他 绿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6269', '6', '16', '3', '又 往 西 下 到 押 利 提 人 的 境 界 ， 到 下 伯 ． 和 仑 的 境 界 ， 直 到 基 色 ， 通 到 海 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6270', '6', '16', '4', '约 瑟 的 儿 子 玛 拿 西 、 以 法 莲 就 得 了 他 们 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6271', '6', '16', '5', '＜ 以 法 莲 支 派 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6272', '6', '16', '6', '往 西 通 到 北 边 的 密 米 他 ， 又 向 东 绕 到 他 纳 ． 示 罗 ， 又 接 连 到 雅 挪 哈 的 东 边 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6273', '6', '16', '7', '从 雅 挪 哈 下 到 亚 他 绿 ， 又 到 拿 拉 ， 达 到 耶 利 哥 ， 通 到 约 旦 河 为 止 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6274', '6', '16', '8', '从 他 普 亚 往 西 ， 到 加 拿 河 ， 直 通 到 海 为 止 。 这 就 是 以 法 莲 支 派 按 着 宗 族 所 得 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6275', '6', '16', '9', '另 外 在 玛 拿 西 人 地 业 中 得 了 些 城 邑 和 属 城 的 村 庄 。 这 都 是 分 给 以 法 莲 子 孙 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6276', '6', '16', '10', '他 们 没 有 赶 出 住 基 色 的 迦 南 人 ； 迦 南 人 却 住 在 以 法 莲 人 中 间 ， 成 为 做 苦 工 的 仆 人 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6277', '6', '17', '1', '＜ 西 玛 拿 西 半 支 派 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6278', '6', '17', '2', '玛 拿 西 其 余 的 子 孙 ， 按 着 宗 族 拈 阄 分 地 ， 就 是 亚 比 以 谢 子 孙 ， 希 勒 子 孙 ， 亚 斯 列 子 孙 ， 示 剑 子 孙 ， 希 弗 子 孙 ， 示 米 大 子 孙 ； 这 些 按 着 宗 族 ， 都 是 约 瑟 儿 子 玛 拿 西 子 孙 的 男 丁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6279', '6', '17', '3', '玛 拿 西 的 玄 孙 ， 玛 吉 的 曾 孙 ， 基 列 的 孙 子 ， 希 弗 的 儿 子 西 罗 非 哈 没 有 儿 子 ， 只 有 女 儿 。 他 的 女 儿 名 叫 玛 拉 、 挪 阿 、 曷 拉 、 密 迦 、 得 撒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6280', '6', '17', '4', '她 们 来 到 祭 司 以 利 亚 撒 和 嫩 的 儿 子 约 书 亚 并 众 首 领 面 前 ， 说 ： “ 耶 和 华 曾 吩 咐 摩 西 在 我 们 弟 兄 中 分 给 我 们 产 业 。 ” 于 是 约 书 亚 照 耶 和 华 所 吩 咐 的 ， 在 她 们 伯 叔 中 ， 把 产 业 分 给 她 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6281', '6', '17', '5', '除 了 约 旦 河 东 的 基 列 和 巴 珊 地 之 外 ， 还 有 十 分 地 归 玛 拿 西 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6282', '6', '17', '6', '因 为 玛 拿 西 的 孙 女 们 在 玛 拿 西 的 孙 子 中 得 了 产 业 。 基 列 地 是 属 玛 拿 西 其 余 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6283', '6', '17', '7', '玛 拿 西 的 境 界 ： 从 亚 设 起 ， 到 示 剑 前 的 密 米 他 ， 往 北 到 隐 ． 他 普 亚 居 民 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6284', '6', '17', '8', '他 普 亚 地 归 玛 拿 西 ， 只 是 玛 拿 西 境 界 上 的 他 普 亚 城 归 以 法 莲 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6285', '6', '17', '9', '其 界 下 到 加 拿 河 的 南 边 。 在 玛 拿 西 城 邑 中 的 这 些 城 邑 都 归 以 法 莲 。 玛 拿 西 的 地 界 是 在 河 北 直 通 到 海 为 止 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6286', '6', '17', '10', '南 归 以 法 莲 ， 北 归 玛 拿 西 ， 以 海 为 界 ； 北 边 到 亚 设 ， 东 边 到 以 萨 迦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6287', '6', '17', '11', '玛 拿 西 在 以 萨 迦 和 亚 设 境 内 ， 有 伯 ． 善 和 属 伯 ． 善 的 镇 市 ， 以 伯 莲 和 属 以 伯 莲 的 镇 市 ， 多 珥 的 居 民 和 属 多 珥 的 镇 市 ； 又 有 三 处 山 冈 ， 就 是 隐 ． 多 珥 和 属 隐 ． 多 珥 的 镇 市 ； 他 纳 的 居 民 和 属 他 纳 的 镇 市 ， 米 吉 多 的 居 民 和 属 米 吉 多 的 镇 市 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6288', '6', '17', '12', '只 是 玛 拿 西 子 孙 不 能 赶 出 这 些 城 的 居 民 ， 迦 南 人 偏 要 住 在 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6289', '6', '17', '13', '及 至 以 色 列 人 强 盛 了 ， 就 使 迦 南 人 做 苦 工 ， 没 有 把 他 们 全 然 赶 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6290', '6', '17', '14', '＜ 约 瑟 子 孙 要 求 多 得 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6291', '6', '17', '15', '约 书 亚 说 ： “ 你 们 如 果 族 大 人 多 ， 嫌 以 法 莲 山 地 窄 小 ， 就 可 以 上 比 利 洗 人 、 利 乏 音 人 之 地 ， 在 树 林 中 砍 伐 树 木 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6292', '6', '17', '16', '约 瑟 的 子 孙 说 ： “ 那 山 地 容 不 下 我 们 ， 并 且 住 平 原 的 迦 南 人 ， 就 是 住 伯 ． 善 和 属 伯 ． 善 的 镇 市 ， 并 住 耶 斯 列 平 原 的 人 ， 都 有 铁 车 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6293', '6', '17', '17', '约 书 亚 对 约 瑟 家 ， 就 是 以 法 莲 和 玛 拿 西 人 ， 说 ： “ 你 是 族 大 人 多 ， 并 且 强 盛 ， 不 可 仅 有 一 阄 之 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6294', '6', '17', '18', '山 地 也 要 归 你 ， 虽 是 树 林 ， 你 也 可 以 砍 伐 ； 靠 近 之 地 必 归 你 。 迦 南 人 虽 有 铁 车 ， 虽 是 强 盛 ， 你 也 能 把 他 们 赶 出 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6295', '6', '18', '1', '＜ 余 地 的 分 配 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6296', '6', '18', '2', '以 色 列 人 中 其 余 的 七 个 支 派 还 没 有 分 给 他 们 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6297', '6', '18', '3', '约 书 亚 对 以 色 列 人 说 ： “ 耶 和 华 ─ ─ 你 们 列 祖 的 神 所 赐 给 你 们 的 地 ， 你 们 耽 延 不 去 得 ， 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6298', '6', '18', '4', '你 们 每 支 派 当 选 举 三 个 人 ， 我 要 打 发 他 们 去 ， 他 们 就 要 起 身 走 遍 那 地 ， 按 着 各 支 派 应 得 的 地 业 写 明 ｛ 或 译 ： 画 图 ｝ ， 就 回 到 我 这 里 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6299', '6', '18', '5', '他 们 要 将 地 分 做 七 分 ； 犹 大 仍 在 南 方 ， 住 在 他 的 境 内 。 约 瑟 家 仍 在 北 方 ， 住 在 他 的 境 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6300', '6', '18', '6', '你 们 要 将 地 分 做 七 分 ， 写 明 了 拿 到 我 这 里 来 。 我 要 在 耶 和 华 ─ ─ 我 们 神 面 前 ， 为 你 们 拈 阄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6301', '6', '18', '7', '利 未 人 在 你 们 中 间 没 有 分 ， 因 为 供 耶 和 华 祭 司 的 职 任 就 是 他 们 的 产 业 。 迦 得 支 派 、 吕 便 支 派 ， 和 玛 拿 西 半 支 派 已 经 在 约 旦 河 东 得 了 地 业 ， 就 是 耶 和 华 仆 人 摩 西 所 给 他 们 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6302', '6', '18', '8', '划 地 势 的 人 起 身 去 的 时 候 ， 约 书 亚 嘱 咐 他 们 说 ： “ 你 们 去 走 遍 那 地 ， 划 明 地 势 ， 就 回 到 我 这 里 来 。 我 要 在 示 罗 这 里 ， 耶 和 华 面 前 ， 为 你 们 拈 阄 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6303', '6', '18', '9', '他 们 就 去 了 ， 走 遍 那 地 ， 按 着 城 邑 分 做 七 分 ， 写 在 册 子 上 ， 回 到 示 罗 营 中 见 约 书 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6304', '6', '18', '10', '约 书 亚 就 在 示 罗 ， 耶 和 华 面 前 ， 为 他 们 拈 阄 。 约 书 亚 在 那 里 ， 按 着 以 色 列 人 的 支 派 ， 将 地 分 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6305', '6', '18', '11', '＜ 分 给 便 雅 悯 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6306', '6', '18', '12', '他 们 的 北 界 是 从 约 旦 河 起 ， 往 上 贴 近 耶 利 哥 的 北 边 ； 又 往 西 通 过 山 地 ， 直 到 伯 ． 亚 文 的 旷 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6307', '6', '18', '13', '从 那 里 往 南 接 连 到 路 斯 ， 贴 近 路 斯 （ 路 斯 就 是 伯 特 利 ） ， 又 下 到 亚 他 绿 ． 亚 达 ， 靠 近 下 伯 ． 和 仑 南 边 的 山 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6308', '6', '18', '14', '从 那 里 往 西 ， 又 转 向 南 ， 从 伯 ． 和 仑 南 对 面 的 山 ， 直 达 到 犹 大 人 的 城 基 列 ． 巴 力 （ 基 列 ． 巴 力 就 是 基 列 ． 耶 琳 ） ； 这 是 西 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6309', '6', '18', '15', '南 界 是 从 基 列 ． 耶 琳 的 尽 边 起 ， 往 西 达 到 尼 弗 多 亚 的 水 源 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6310', '6', '18', '16', '又 下 到 欣 嫩 子 谷 对 面 山 的 尽 边 ， 就 是 利 乏 音 谷 北 边 的 山 ； 又 下 到 欣 嫩 谷 ， 贴 近 耶 布 斯 的 南 边 ； 又 下 到 隐 ． 罗 结 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6311', '6', '18', '17', '又 往 北 通 到 隐 ． 示 麦 ， 达 到 亚 都 冥 坡 对 面 的 基 利 绿 ； 又 下 到 吕 便 之 子 波 罕 的 磐 石 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6312', '6', '18', '18', '又 接 连 到 亚 拉 巴 对 面 ， 往 北 下 到 亚 拉 巴 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6313', '6', '18', '19', '又 接 连 到 伯 ． 曷 拉 的 北 边 ， 直 通 到 盐 海 的 北 汊 ， 就 是 约 旦 河 的 南 头 ； 这 是 南 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6314', '6', '18', '20', '东 界 是 约 旦 河 。 这 是 便 雅 悯 人 按 着 宗 族 ， 照 他 们 四 围 的 交 界 所 得 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6315', '6', '18', '21', '便 雅 悯 支 派 按 着 宗 族 所 得 的 城 邑 就 是 ： 耶 利 哥 、 伯 ． 曷 拉 、 伊 麦 ． 基 悉 、');
