INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6334', '6', '19', '12', '又 从 撒 立 往 东 转 向 日 出 之 地 ， 到 吉 斯 绿 ． 他 泊 的 境 界 ， 又 通 到 大 比 拉 ， 上 到 雅 非 亚 ；');
