INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6337', '6', '19', '15', '还 有 加 他 、 拿 哈 拉 、 伸 仑 、 以 大 拉 、 伯 利 恒 ， 共 十 二 座 城 ， 还 有 属 城 的 村 庄 。');
