INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6345', '6', '19', '23', '这 些 城 并 属 城 的 村 庄 就 是 以 萨 迦 支 派 按 着 宗 族 所 得 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6346', '6', '19', '24', '＜ 分 给 亚 设 支 派 的 土 地 ＞ 
