INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6348', '6', '19', '26', '亚 拉 米 勒 、 亚 末 、 米 沙 勒 ； 往 西 达 到 迦 密 ， 又 到 希 曷 ． 立 纳 ，');
