INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6351', '6', '19', '29', '转 到 拉 玛 和 坚 固 城 泰 尔 ； 又 转 到 何 萨 ， 靠 近 亚 革 悉 一 带 地 方 ， 直 通 到 海 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('6352', '6', '19', '30', '又 有 乌 玛 、 亚 弗 、 利 合 ， 共 二 十 二 座 城 ， 还 有 属 城 的 村 庄 。');
