INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9953', '12', '15', '27', '＜ 以 色 列 国 的 王 比 加 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9954', '12', '15', '28', '他 行 耶 和 华 眼 中 看 为 恶 的 事 ， 不 离 开 尼 八 的 儿 子 耶 罗 波 安 使 以 色 列 人 陷 在 罪 里 的 那 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9955', '12', '15', '29', '以 色 列 王 比 加 年 间 ， 亚 述 王 提 革 拉 ． 毗 列 色 来 夺 了 以 云 、 亚 伯 ． 伯 ． 玛 迦 、 亚 挪 、 基 低 斯 、 夏 琐 、 基 列 、 加 利 利 ， 和 拿 弗 他 利 全 地 ， 将 这 些 地 方 的 居 民 都 掳 到 亚 述 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9956', '12', '15', '30', '乌 西 雅 的 儿 子 约 坦 二 十 年 ， 以 拉 的 儿 子 何 细 亚 背 叛 利 玛 利 的 儿 子 比 加 ， 击 杀 他 ， 篡 了 他 的 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9957', '12', '15', '31', '比 加 其 余 的 事 ， 凡 他 所 行 的 都 写 在 以 色 列 诸 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9958', '12', '15', '32', '＜ 犹 大 国 的 王 约 坦 （ 代 下   2 7 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9959', '12', '15', '33', '他 登 基 的 时 候 年 二 十 五 岁 ， 在 耶 路 撒 冷 作 王 十 六 年 。 他 母 亲 名 叫 耶 路 沙 ， 是 撒 督 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9960', '12', '15', '34', '约 坦 行 耶 和 华 眼 中 看 为 正 的 事 ， 效 法 他 父 亲 乌 西 雅 一 切 所 行 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9961', '12', '15', '35', '只 是 邱 坛 还 没 有 废 去 ， 百 姓 仍 在 那 里 献 祭 烧 香 。 约 坦 建 立 耶 和 华 殿 的 上 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9962', '12', '15', '36', '约 坦 其 余 的 事 ， 凡 他 所 行 的 都 写 在 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9963', '12', '15', '37', '在 那 些 日 子 ， 耶 和 华 才 使 亚 兰 王 利 汛 和 利 玛 利 的 儿 子 比 加 去 攻 击 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9964', '12', '15', '38', '约 坦 与 他 列 祖 同 睡 ， 葬 在 他 祖 大 卫 城 他 列 祖 的 坟 地 里 。 他 儿 子 亚 哈 斯 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9965', '12', '16', '1', '＜ 犹 大 国 的 王 亚 哈 斯 （ 代 下   2 8 : 1 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9966', '12', '16', '2', '他 登 基 的 时 候 年 二 十 岁 ， 在 耶 路 撒 冷 作 王 十 六 年 ； 不 像 他 祖 大 卫 行 耶 和 华 ─ ─ 他 神 眼 中 看 为 正 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9967', '12', '16', '3', '却 效 法 以 色 列 诸 王 所 行 的 ， 又 照 着 耶 和 华 从 以 色 列 人 面 前 赶 出 的 外 邦 人 所 行 可 憎 的 事 ， 使 他 的 儿 子 经 火 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9968', '12', '16', '4', '并 在 邱 坛 上 、 山 冈 上 、 各 青 翠 树 下 献 祭 烧 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9969', '12', '16', '5', '亚 兰 王 利 汛 和 以 色 列 王 利 玛 利 的 儿 子 比 加 上 来 攻 打 耶 路 撒 冷 ， 围 困 亚 哈 斯 ， 却 不 能 胜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9970', '12', '16', '6', '当 时 亚 兰 王 利 汛 收 回 以 拉 他 归 与 亚 兰 ， 将 犹 大 人 从 以 拉 他 赶 出 去 。 亚 兰 人 ｛ 有 译 以 东 人 的 ｝ 就 来 到 以 拉 他 ， 住 在 那 里 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9971', '12', '16', '7', '亚 哈 斯 差 遣 使 者 去 见 亚 述 王 提 革 拉 ． 毗 列 色 ， 说 ： “ 我 是 你 的 仆 人 、 你 的 儿 子 。 现 在 亚 兰 王 和 以 色 列 王 攻 击 我 ， 求 你 来 救 我 脱 离 他 们 的 手 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9972', '12', '16', '8', '亚 哈 斯 将 耶 和 华 殿 里 和 王 宫 府 库 里 所 有 的 金 银 都 送 给 亚 述 王 为 礼 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9973', '12', '16', '9', '亚 述 王 应 允 了 他 ， 就 上 去 攻 打 大 马 士 革 ， 将 城 攻 取 ， 杀 了 利 汛 ， 把 居 民 掳 到 吉 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9974', '12', '16', '10', '亚 哈 斯 王 上 大 马 士 革 去 迎 接 亚 述 王 提 革 拉 ． 毗 列 色 ， 在 大 马 士 革 看 见 一 座 坛 ， 就 照 坛 的 规 模 样 式 作 法 画 了 图 样 ， 送 到 祭 司 乌 利 亚 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9975', '12', '16', '11', '祭 司 乌 利 亚 照 着 亚 哈 斯 王 从 大 马 士 革 送 来 的 图 样 ， 在 亚 哈 斯 王 没 有 从 大 马 士 革 回 来 之 先 ， 建 筑 一 座 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9976', '12', '16', '12', '王 从 大 马 士 革 回 来 看 见 坛 ， 就 近 前 来 ， 在 坛 上 献 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9977', '12', '16', '13', '烧 燔 祭 、 素 祭 、 浇 奠 祭 ， 将 平 安 祭 牲 的 血 洒 在 坛 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9978', '12', '16', '14', '又 将 耶 和 华 面 前 的 铜 坛 从 耶 和 华 殿 和 新 坛 的 中 间 搬 到 新 坛 的 北 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9979', '12', '16', '15', '亚 哈 斯 王 吩 咐 祭 司 乌 利 亚 说 ： “ 早 晨 的 燔 祭 、 晚 上 的 素 祭 ， 王 的 燔 祭 、 素 祭 ， 国 内 众 民 的 燔 祭 、 素 祭 、 奠 祭 都 要 烧 在 大 坛 上 。 燔 祭 牲 和 平 安 祭 牲 的 血 也 要 洒 在 这 坛 上 ， 只 是 铜 坛 我 要 用 以 求 问 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9980', '12', '16', '16', '祭 司 乌 利 亚 就 照 着 亚 哈 斯 王 所 吩 咐 的 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9981', '12', '16', '17', '亚 哈 斯 王 打 掉 盆 座 四 面 镶 着 的 心 子 ， 把 盆 从 座 上 挪 下 来 ， 又 将 铜 海 从 驮 海 的 铜 牛 上 搬 下 来 ， 放 在 铺 石 地 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9982', '12', '16', '18', '又 因 亚 述 王 的 缘 故 ， 将 耶 和 华 殿 为 安 息 日 所 盖 的 廊 子 和 王 从 外 入 殿 的 廊 子 挪 移 ， 围 绕 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9983', '12', '16', '19', '亚 哈 斯 其 余 所 行 的 事 都 写 在 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9984', '12', '16', '20', '亚 哈 斯 与 他 列 祖 同 睡 ， 葬 在 大 卫 城 他 列 祖 的 坟 地 里 。 他 儿 子 希 西 家 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9985', '12', '17', '1', '＜ 以 色 列 国 的 王 何 细 亚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9986', '12', '17', '2', '他 行 耶 和 华 眼 中 看 为 恶 的 事 ， 只 是 不 像 在 他 以 前 的 以 色 列 诸 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9987', '12', '17', '3', '亚 述 王 撒 缦 以 色 上 来 攻 击 何 细 亚 ， 何 细 亚 就 服 事 他 ， 给 他 进 贡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9988', '12', '17', '4', '何 细 亚 背 叛 ， 差 人 去 见 埃 及 王 梭 ， 不 照 往 年 所 行 的 与 亚 述 王 进 贡 。 亚 述 王 知 道 了 ， 就 把 他 锁 禁 ， 囚 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9989', '12', '17', '5', '亚 述 王 上 来 攻 击 以 色 列 遍 地 ， 上 到 撒 马 利 亚 ， 围 困 三 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9990', '12', '17', '6', '何 细 亚 第 九 年 亚 述 王 攻 取 了 撒 马 利 亚 ， 将 以 色 列 人 掳 到 亚 述 ， 把 他 们 安 置 在 哈 腊 与 歌 散 的 哈 博 河 边 ， 并 米 底 亚 人 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9991', '12', '17', '7', '这 是 因 以 色 列 人 得 罪 那 领 他 们 出 埃 及 地 、 脱 离 埃 及 王 法 老 手 的 耶 和 华 ─ ─ 他 们 的 神 ， 去 敬 畏 别 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9992', '12', '17', '8', '随 从 耶 和 华 在 他 们 面 前 所 赶 出 外 邦 人 的 风 俗 和 以 色 列 诸 王 所 立 的 条 规 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9993', '12', '17', '9', '以 色 列 人 暗 中 行 不 正 的 事 ， 违 背 耶 和 华 ─ ─ 他 们 的 神 ， 在 他 们 所 有 的 城 邑 ， 从 了 望 楼 直 到 坚 固 城 ， 建 筑 邱 坛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9994', '12', '17', '10', '在 各 高 冈 上 、 各 青 翠 树 下 立 柱 像 和 木 偶 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9995', '12', '17', '11', '在 邱 坛 上 烧 香 ， 效 法 耶 和 华 在 他 们 面 前 赶 出 的 外 邦 人 所 行 的 ， 又 行 恶 事 惹 动 耶 和 华 的 怒 气 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9996', '12', '17', '12', '且 事 奉 偶 像 ， 就 是 耶 和 华 警 戒 他 们 不 可 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9997', '12', '17', '13', '但 耶 和 华 藉 众 先 知 、 先 见 劝 戒 以 色 列 人 和 犹 大 人 说 ： “ 当 离 开 你 们 的 恶 行 ， 谨 守 我 的 诫 命 律 例 ， 遵 行 我 吩 咐 你 们 列 祖 ， 并 藉 我 仆 人 众 先 知 所 传 给 你 们 的 律 法 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9998', '12', '17', '14', '他 们 却 不 听 从 ， 竟 硬 着 颈 项 ， 效 法 他 们 列 祖 ， 不 信 服 耶 和 华 ─ ─ 他 们 的 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('9999', '12', '17', '15', '厌 弃 他 的 律 例 和 他 与 他 们 列 祖 所 立 的 约 ， 并 劝 戒 他 们 的 话 ， 随 从 虚 无 的 神 ， 自 己 成 为 虚 妄 ， 效 法 周 围 的 外 邦 人 ， 就 是 耶 和 华 嘱 咐 他 们 不 可 效 法 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10000', '12', '17', '16', '离 弃 耶 和 华 ─ ─ 他 们 神 的 一 切 诫 命 ， 为 自 己 铸 了 两 个 牛 犊 的 像 ， 立 了 亚 舍 拉 ， 敬 拜 天 上 的 万 象 ， 事 奉 巴 力 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10001', '12', '17', '17', '又 使 他 们 的 儿 女 经 火 ， 用 占 卜 ， 行 法 术 卖 了 自 己 ， 行 耶 和 华 眼 中 看 为 恶 的 事 ， 惹 动 他 的 怒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10002', '12', '17', '18', '所 以 耶 和 华 向 以 色 列 人 大 大 发 怒 ， 从 自 己 面 前 赶 出 他 们 ， 只 剩 下 犹 大 一 个 支 派 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10003', '12', '17', '19', '犹 大 人 也 不 遵 守 耶 和 华 ─ ─ 他 们 神 的 诫 命 ， 随 从 以 色 列 人 所 立 的 条 规 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10004', '12', '17', '20', '耶 和 华 就 厌 弃 以 色 列 全 族 ， 使 他 们 受 苦 ， 把 他 们 交 在 抢 夺 他 们 的 人 手 中 ， 以 致 赶 出 他 们 离 开 自 己 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10005', '12', '17', '21', '将 以 色 列 国 从 大 卫 家 夺 回 ； 他 们 就 立 尼 八 的 儿 子 耶 罗 波 安 作 王 。 耶 罗 波 安 引 诱 以 色 列 人 不 随 从 耶 和 华 ， 陷 在 大 罪 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10006', '12', '17', '22', '以 色 列 人 犯 耶 罗 波 安 所 犯 的 一 切 罪 ， 总 不 离 开 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10007', '12', '17', '23', '以 致 耶 和 华 从 自 己 面 前 赶 出 他 们 ， 正 如 藉 他 仆 人 众 先 知 所 说 的 。 这 样 ， 以 色 列 人 从 本 地 被 掳 到 亚 述 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10008', '12', '17', '24', '＜ 亚 述 人 定 居 于 以 色 列 人 中 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10009', '12', '17', '25', '他 们 才 住 那 里 的 时 候 ， 不 敬 畏 耶 和 华 ， 所 以 耶 和 华 叫 狮 子 进 入 他 们 中 间 ， 咬 死 了 些 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10010', '12', '17', '26', '有 人 告 诉 亚 述 王 说 ： “ 你 所 迁 移 安 置 在 撒 马 利 亚 各 城 的 那 些 民 ， 不 知 道 那 地 之 神 的 规 矩 ， 所 以 那 神 叫 狮 子 进 入 他 们 中 间 ， 咬 死 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10011', '12', '17', '27', '亚 述 王 就 吩 咐 说 ： “ 叫 所 掳 来 的 祭 司 回 去 一 个 ， 使 他 住 在 那 里 ， 将 那 地 之 神 的 规 矩 指 教 那 些 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10012', '12', '17', '28', '于 是 有 一 个 从 撒 马 利 亚 掳 去 的 祭 司 回 来 ， 住 在 伯 特 利 ， 指 教 他 们 怎 样 敬 畏 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10013', '12', '17', '29', '然 而 ， 各 族 之 人 在 所 住 的 城 里 各 为 自 己 制 造 神 像 ， 安 置 在 撒 马 利 亚 人 所 造 有 邱 坛 的 殿 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10014', '12', '17', '30', '巴 比 伦 人 造 疏 割 ． 比 讷 像 ； 古 他 人 造 匿 甲 像 ； 哈 马 人 造 亚 示 玛 像 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10015', '12', '17', '31', '亚 瓦 人 造 匿 哈 和 他 珥 他 像 ； 西 法 瓦 音 人 用 火 焚 烧 儿 女 ， 献 给 西 法 瓦 音 的 神 亚 得 米 勒 和 亚 拿 米 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10016', '12', '17', '32', '他 们 惧 怕 耶 和 华 ， 也 从 他 们 中 间 立 邱 坛 的 祭 司 ， 为 他 们 在 有 邱 坛 的 殿 中 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10017', '12', '17', '33', '他 们 又 惧 怕 耶 和 华 ， 又 事 奉 自 己 的 神 ， 从 何 邦 迁 移 ， 就 随 何 邦 的 风 俗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10018', '12', '17', '34', '他 们 直 到 如 今 仍 照 先 前 的 风 俗 去 行 ， 不 专 心 敬 畏 耶 和 华 ， 不 全 守 自 己 的 规 矩 、 典 章 ， 也 不 遵 守 耶 和 华 吩 咐 雅 各 后 裔 的 律 法 、 诫 命 。 （ 雅 各 ， 就 是 从 前 耶 和 华 起 名 叫 以 色 列 的 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10019', '12', '17', '35', '耶 和 华 曾 与 他 们 立 约 ， 嘱 咐 他 们 说 ： “ 不 可 敬 畏 别 神 ， 不 可 跪 拜 事 奉 他 ， 也 不 可 向 他 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10020', '12', '17', '36', '但 那 用 大 能 和 伸 出 来 的 膀 臂 领 你 们 出 埃 及 地 的 耶 和 华 ， 你 们 当 敬 畏 ， 跪 拜 ， 向 他 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10021', '12', '17', '37', '他 给 你 们 写 的 律 例 、 典 章 、 律 法 、 诫 命 ， 你 们 应 当 永 远 谨 守 遵 行 ， 不 可 敬 畏 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10022', '12', '17', '38', '我 ─ ─ 耶 和 华 与 你 们 所 立 的 约 你 们 不 可 忘 记 ， 也 不 可 敬 畏 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10023', '12', '17', '39', '但 要 敬 畏 耶 和 华 ─ ─ 你 们 的 神 ， 他 必 救 你 们 脱 离 一 切 仇 敌 的 手 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10024', '12', '17', '40', '他 们 却 不 听 从 ， 仍 照 先 前 的 风 俗 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10025', '12', '17', '41', '如 此 这 些 民 又 惧 怕 耶 和 华 ， 又 事 奉 他 们 的 偶 像 。 他 们 子 子 孙 孙 也 都 照 样 行 ， 效 法 他 们 的 祖 宗 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10026', '12', '18', '1', '＜ 犹 大 国 的 王 希 西 家 （ 代 下   2 9 : 1 - 2 ； 3 0 : 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10027', '12', '18', '2', '他 登 基 的 时 候 年 二 十 五 岁 ， 在 耶 路 撒 冷 作 王 二 十 九 年 。 他 母 亲 名 叫 亚 比 ， 是 撒 迦 利 雅 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10028', '12', '18', '3', '希 西 家 行 耶 和 华 眼 中 看 为 正 的 事 ， 效 法 他 祖 大 卫 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10029', '12', '18', '4', '他 废 去 邱 坛 ， 毁 坏 柱 像 ， 砍 下 木 偶 ， 打 碎 摩 西 所 造 的 铜 蛇 ， 因 为 到 那 时 以 色 列 人 仍 向 铜 蛇 烧 香 。 希 西 家 叫 铜 蛇 为 铜 块 ｛ 或 译 ： 人 称 铜 蛇 为 铜 像 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10030', '12', '18', '5', '希 西 家 倚 靠 耶 和 华 ─ ─ 以 色 列 的 神 ， 在 他 前 后 的 犹 大 列 王 中 没 有 一 个 及 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10031', '12', '18', '6', '因 为 他 专 靠 耶 和 华 ， 总 不 离 开 ， 谨 守 耶 和 华 所 吩 咐 摩 西 的 诫 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10032', '12', '18', '7', '耶 和 华 与 他 同 在 ， 他 无 论 往 何 处 去 尽 都 亨 通 。 他 背 叛 、 不 肯 事 奉 亚 述 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10033', '12', '18', '8', '希 西 家 攻 击 非 利 士 人 ， 直 到 迦 萨 ， 并 迦 萨 的 四 境 ， 从 了 望 楼 到 坚 固 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10034', '12', '18', '9', '希 西 家 王 第 四 年 ， 就 是 以 色 列 王 以 拉 的 儿 子 何 细 亚 第 七 年 ， 亚 述 王 撒 缦 以 色 上 来 围 困 撒 马 利 亚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10035', '12', '18', '10', '过 了 三 年 就 攻 取 了 城 。 希 西 家 第 六 年 ， 以 色 列 王 何 细 亚 第 九 年 ， 撒 马 利 亚 被 攻 取 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10036', '12', '18', '11', '亚 述 王 将 以 色 列 人 掳 到 亚 述 ， 把 他 们 安 置 在 哈 腊 与 歌 散 的 哈 博 河 边 ， 并 米 底 亚 人 的 城 邑 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10037', '12', '18', '12', '都 因 他 们 不 听 从 耶 和 华 ─ ─ 他 们 神 的 话 ， 违 背 他 的 约 ， 就 是 耶 和 华 仆 人 摩 西 吩 咐 他 们 所 当 守 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10038', '12', '18', '13', '＜ 亚 述 人 威 胁 耶 路 撒 冷 （ 代 下   3 2 : 1 - 1 9 ； 赛   3 6 : 1 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10039', '12', '18', '14', '犹 大 王 希 西 家 差 人 往 拉 吉 去 见 亚 述 王 ， 说 ： “ 我 有 罪 了 ， 求 你 离 开 我 ； 凡 你 罚 我 的 ， 我 必 承 当 。 ” 于 是 亚 述 王 罚 犹 大 王 希 西 家 银 子 三 百 他 连 得 ， 金 子 三 十 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10040', '12', '18', '15', '希 西 家 就 把 耶 和 华 殿 里 和 王 宫 府 库 里 所 有 的 银 子 都 给 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10041', '12', '18', '16', '那 时 ， 犹 大 王 希 西 家 将 耶 和 华 殿 门 上 的 金 子 和 他 自 己 包 在 柱 上 的 金 子 都 刮 下 来 ， 给 了 亚 述 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10042', '12', '18', '17', '亚 述 王 从 拉 吉 差 遣 他 珥 探 、 拉 伯 撒 利 ， 和 拉 伯 沙 基 率 领 大 军 往 耶 路 撒 冷 ， 到 希 西 家 王 那 里 去 。 他 们 上 到 耶 路 撒 冷 ， 就 站 在 上 池 的 水 沟 旁 ， 在 漂 布 地 的 大 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10043', '12', '18', '18', '他 们 呼 叫 王 的 时 候 ， 就 有 希 勒 家 的 儿 子 家 宰 以 利 亚 敬 ， 并 书 记 舍 伯 那 和 亚 萨 的 儿 子 史 官 约 亚 ， 出 来 见 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10044', '12', '18', '19', '拉 伯 沙 基 说 ： “ 你 们 去 告 诉 希 西 家 说 ， 亚 述 大 王 如 此 说 ： ‘ 你 所 倚 靠 的 有 什 么 可 仗 赖 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10045', '12', '18', '20', '你 说 有 打 仗 的 计 谋 和 能 力 ， 我 看 不 过 是 虚 话 。 你 到 底 倚 靠 谁 才 背 叛 我 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10046', '12', '18', '21', '看 哪 ， 你 所 倚 靠 的 埃 及 是 那 压 伤 的 苇 杖 ； 人 若 靠 这 杖 ， 就 必 刺 透 他 的 手 。 埃 及 王 法 老 向 一 切 倚 靠 他 的 人 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10047', '12', '18', '22', '你 们 若 对 我 说 ： 我 们 倚 靠 耶 和 华 ─ ─ 我 们 的 神 ， 希 西 家 岂 不 是 将 神 的 邱 坛 和 祭 坛 废 去 ， 且 对 犹 大 和 耶 路 撒 冷 的 人 说 ： 你 们 当 在 耶 路 撒 冷 这 坛 前 敬 拜 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10048', '12', '18', '23', '现 在 你 把 当 头 给 我 主 亚 述 王 ， 我 给 你 二 千 匹 马 ， 看 你 这 一 面 骑 马 的 人 够 不 够 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10049', '12', '18', '24', '若 不 然 ， 怎 能 打 败 我 主 臣 仆 中 最 小 的 军 长 呢 ？ 你 竟 倚 靠 埃 及 的 战 车 马 兵 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10050', '12', '18', '25', '现 在 我 上 来 攻 击 毁 灭 这 地 ， 岂 没 有 耶 和 华 的 意 思 吗 ？ 耶 和 华 吩 咐 我 说 ： 你 上 去 攻 击 毁 灭 这 地 吧 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10051', '12', '18', '26', '希 勒 家 的 儿 子 以 利 亚 敬 和 舍 伯 那 ， 并 约 亚 ， 对 拉 伯 沙 基 说 ： “ 求 你 用 亚 兰 言 语 和 仆 人 说 话 ， 因 为 我 们 懂 得 ； 不 要 用 犹 大 言 语 和 我 们 说 话 ， 达 到 城 上 百 姓 的 耳 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10052', '12', '18', '27', '拉 伯 沙 基 说 ： “ 我 主 差 遣 我 来 ， 岂 是 单 对 你 和 你 的 主 说 这 些 话 吗 ？ 不 也 是 对 这 些 坐 在 城 上 、 要 与 你 们 一 同 吃 自 己 粪 、 喝 自 己 尿 的 人 说 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10053', '12', '18', '28', '于 是 拉 伯 沙 基 站 着 ， 用 犹 大 言 语 大 声 喊 着 说 ： “ 你 们 当 听 亚 述 大 王 的 话 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10054', '12', '18', '29', '王 如 此 说 ： ‘ 你 们 不 要 被 希 西 家 欺 哄 了 ； 因 他 不 能 救 你 们 脱 离 我 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10055', '12', '18', '30', '也 不 要 听 希 西 家 使 你 们 倚 靠 耶 和 华 ， 说 耶 和 华 必 要 拯 救 我 们 ， 这 城 必 不 交 在 亚 述 王 的 手 中 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10056', '12', '18', '31', '不 要 听 希 西 家 的 话 ！ 因 亚 述 王 如 此 说 ： ‘ 你 们 要 与 我 和 好 ， 出 来 投 降 我 ， 各 人 就 可 以 吃 自 己 葡 萄 树 和 无 花 果 树 的 果 子 ， 喝 自 己 井 里 的 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10057', '12', '18', '32', '等 我 来 领 你 们 到 一 个 地 方 与 你 们 本 地 一 样 ， 就 是 有 五 谷 和 新 酒 之 地 ， 有 粮 食 和 葡 萄 园 之 地 ， 有 橄 榄 树 和 蜂 蜜 之 地 ， 好 使 你 们 存 活 ， 不 至 于 死 。 希 西 家 劝 导 你 们 ， 说 耶 和 华 必 拯 救 我 们 ； 你 们 不 要 听 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10058', '12', '18', '33', '列 国 的 神 有 哪 一 个 救 他 本 国 脱 离 亚 述 王 的 手 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10059', '12', '18', '34', '哈 马 、 亚 珥 拔 的 神 在 哪 里 呢 ？ 西 法 瓦 音 、 希 拿 、 以 瓦 的 神 在 哪 里 呢 ？ 他 们 曾 救 撒 马 利 亚 脱 离 我 的 手 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10060', '12', '18', '35', '这 些 国 的 神 有 谁 曾 救 自 己 的 国 脱 离 我 的 手 呢 ？ 难 道 耶 和 华 能 救 耶 路 撒 冷 脱 离 我 的 手 吗 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10061', '12', '18', '36', '百 姓 静 默 不 言 ， 并 不 回 答 一 句 ， 因 为 王 曾 吩 咐 说 ： “ 不 要 回 答 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10062', '12', '18', '37', '当 下 ， 希 勒 家 的 儿 子 家 宰 以 利 亚 敬 和 书 记 舍 伯 那 ， 并 亚 萨 的 儿 子 史 官 约 亚 ， 都 撕 裂 衣 服 ， 来 到 希 西 家 那 里 ， 将 拉 伯 沙 基 的 话 告 诉 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10063', '12', '19', '1', '＜ 希 西 家 王 派 人 请 示 以 赛 亚 （ 赛   3 7 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10064', '12', '19', '2', '使 家 宰 以 利 亚 敬 和 书 记 舍 伯 那 ， 并 祭 司 中 的 长 老 ， 都 披 上 麻 布 ， 去 见 亚 摩 斯 的 儿 子 先 知 以 赛 亚 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10065', '12', '19', '3', '对 他 说 ： “ 希 西 家 如 此 说 ： ‘ 今 日 是 急 难 、 责 罚 、 凌 辱 的 日 子 ， 就 如 妇 人 将 要 生 产 婴 孩 ， 却 没 有 力 量 生 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10066', '12', '19', '4', '或 者 耶 和 华 ─ ─ 你 的 神 听 见 拉 伯 沙 基 的 一 切 话 ， 就 是 他 主 人 亚 述 王 打 发 他 来 辱 骂 永 生 神 的 话 ， 耶 和 华 ─ ─ 你 的 神 听 见 这 话 ， 就 发 斥 责 。 故 此 ， 求 你 为 余 剩 的 民 扬 声 祷 告 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10067', '12', '19', '5', '希 西 家 王 的 臣 仆 就 去 见 以 赛 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10068', '12', '19', '6', '以 赛 亚 对 他 们 说 ： “ 要 这 样 对 你 们 的 主 人 说 ， 耶 和 华 如 此 说 ： ‘ 你 听 见 亚 述 王 的 仆 人 亵 渎 我 的 话 ， 不 要 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10069', '12', '19', '7', '我 必 惊 动 ｛ 原 文 是 使 灵 进 入 ｝ 他 的 心 ， 他 要 听 见 风 声 就 归 回 本 地 。 我 必 使 他 在 那 里 倒 在 刀 下 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10070', '12', '19', '8', '＜ 亚 述 人 再 度 威 胁 （ 赛   3 7 : 8 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10071', '12', '19', '9', '亚 述 王 听 见 人 论 古 实 王 特 哈 加 说 ： “ 他 出 来 要 与 你 争 战 。 ” 于 是 亚 述 王 又 打 发 使 者 去 见 希 西 家 ， 吩 咐 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10072', '12', '19', '10', '“ 你 们 对 犹 大 王 希 西 家 如 此 说 ： ‘ 不 要 听 你 所 倚 靠 的 神 欺 哄 你 ， 说 耶 路 撒 冷 必 不 交 在 亚 述 王 的 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10073', '12', '19', '11', '你 总 听 说 亚 述 诸 王 向 列 国 所 行 的 ， 乃 是 尽 行 灭 绝 ， 难 道 你 还 能 得 救 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10074', '12', '19', '12', '我 列 祖 所 毁 灭 的 ， 就 是 歌 散 、 哈 兰 、 利 色 ， 和 属 提 ． 拉 撒 的 伊 甸 人 ， 这 些 国 的 神 何 曾 拯 救 这 些 国 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10075', '12', '19', '13', '哈 马 的 王 、 亚 珥 拔 的 王 、 西 法 瓦 音 城 的 王 、 希 拿 ， 和 以 瓦 的 王 都 在 哪 里 呢 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10076', '12', '19', '14', '希 西 家 从 使 者 手 里 接 过 书 信 来 ， 看 完 了 ， 就 上 耶 和 华 的 殿 ， 将 书 信 在 耶 和 华 面 前 展 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10077', '12', '19', '15', '希 西 家 向 耶 和 华 祷 告 说 ： “ 坐 在 二 基 路 伯 上 耶 和 华 ─ ─ 以 色 列 的 神 啊 ， 你 是 天 下 万 国 的 神 ， 你 曾 创 造 天 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10078', '12', '19', '16', '耶 和 华 啊 ， 求 你 侧 耳 而 听 ！ 耶 和 华 啊 ， 求 你 睁 眼 而 看 ！ 要 听 西 拿 基 立 打 发 使 者 来 辱 骂 永 生 神 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10079', '12', '19', '17', '耶 和 华 啊 ， 亚 述 诸 王 果 然 使 列 国 和 列 国 之 地 变 为 荒 凉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10080', '12', '19', '18', '将 列 国 的 神 像 都 扔 在 火 里 ； 因 为 它 本 不 是 神 ， 乃 是 人 手 所 造 的 ， 是 木 头 石 头 的 ， 所 以 灭 绝 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10081', '12', '19', '19', '耶 和 华 ─ ─ 我 们 的 神 啊 ， 现 在 求 你 救 我 们 脱 离 亚 述 王 的 手 ， 使 天 下 万 国 都 知 道 惟 独 你 ─ ─ 耶 和 华 是 神 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10082', '12', '19', '20', '＜ 以 赛 亚 传 给 王 的 信 息 （ 赛   3 7 : 2 0 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10083', '12', '19', '21', '耶 和 华 论 他 这 样 说 ： 锡 安 的 处 女 藐 视 你 ， 嗤 笑 你 ； 耶 路 撒 冷 的 女 子 向 你 摇 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10084', '12', '19', '22', '你 辱 骂 谁 ？ 亵 渎 谁 ？ 扬 起 声 来 ， 高 举 眼 目 攻 击 谁 呢 ？ 乃 是 攻 击 以 色 列 的 圣 者 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10085', '12', '19', '23', '你 藉 你 的 使 者 辱 骂 主 ， 并 说 ： 我 率 领 许 多 战 车 上 山 顶 ， 到 黎 巴 嫩 极 深 之 处 ； 我 要 砍 伐 其 中 高 大 的 香 柏 树 和 佳 美 的 松 树 ； 我 必 上 极 高 之 处 ， 进 入 肥 田 的 树 林 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10086', '12', '19', '24', '我 已 经 在 外 邦 挖 井 喝 水 ； 我 必 用 脚 掌 踏 干 埃 及 的 一 切 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10087', '12', '19', '25', '耶 和 华 说 ， 我 早 先 所 做 的 ， 古 时 所 立 的 ， 就 是 现 在 藉 你 使 坚 固 城 荒 废 ， 变 为 乱 堆 ， 这 事 你 岂 没 有 听 见 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10088', '12', '19', '26', '所 以 其 中 的 居 民 力 量 甚 小 ， 惊 惶 羞 愧 。 他 们 像 野 草 ， 像 青 菜 ， 如 房 顶 上 的 草 ， 又 如 未 长 成 而 枯 干 的 禾 稼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10089', '12', '19', '27', '你 坐 下 ， 你 出 去 ， 你 进 来 ， 你 向 我 发 烈 怒 ， 我 都 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10090', '12', '19', '28', '因 你 向 我 发 烈 怒 ， 又 因 你 狂 傲 的 话 达 到 我 耳 中 ， 我 就 要 用 钩 子 钩 上 你 的 鼻 子 ， 把 嚼 环 放 在 你 口 里 ， 使 你 从 你 来 的 路 转 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10091', '12', '19', '29', '“ 以 色 列 人 哪 ， 我 赐 你 们 一 个 证 据 ： 你 们 今 年 要 吃 自 生 的 ， 明 年 也 要 吃 自 长 的 ； 至 于 后 年 ， 你 们 要 耕 种 收 割 ， 栽 植 葡 萄 园 ， 吃 其 中 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10092', '12', '19', '30', '犹 大 家 所 逃 脱 余 剩 的 ， 仍 要 往 下 扎 根 ， 向 上 结 果 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10093', '12', '19', '31', '必 有 余 剩 的 民 从 耶 路 撒 冷 而 出 ； 必 有 逃 脱 的 人 从 锡 安 山 而 来 。 耶 和 华 的 热 心 必 成 就 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10094', '12', '19', '32', '“ 所 以 ， 耶 和 华 论 亚 述 王 如 此 说 ： ‘ 他 必 不 得 来 到 这 城 ， 也 不 在 这 里 射 箭 ， 不 得 拿 盾 牌 到 城 前 ， 也 不 筑 垒 攻 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10095', '12', '19', '33', '他 从 哪 条 路 来 ， 必 从 那 条 路 回 去 ， 必 不 得 来 到 这 城 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10096', '12', '19', '34', '因 我 为 自 己 的 缘 故 ， 又 为 我 仆 人 大 卫 的 缘 故 ， 必 保 护 拯 救 这 城 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10097', '12', '19', '35', '当 夜 ， 耶 和 华 的 使 者 出 去 ， 在 亚 述 营 中 杀 了 十 八 万 五 千 人 。 清 早 有 人 起 来 ， 一 看 ， 都 是 死 尸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10098', '12', '19', '36', '亚 述 王 西 拿 基 立 就 拔 营 回 去 ， 住 在 尼 尼 微 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10099', '12', '19', '37', '一 日 在 他 的 神 尼 斯 洛 庙 里 叩 拜 ， 他 儿 子 亚 得 米 勒 和 沙 利 色 用 刀 杀 了 他 ， 就 逃 到 亚 拉 腊 地 。 他 儿 子 以 撒 哈 顿 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10100', '12', '20', '1', '＜ 希 西 家 病 重 康 复 （ 赛   3 8 : 1 - 8 ； 3 8 : 2 1 - 2 2 ； 代 下   3 2 : 2 4 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10101', '12', '20', '2', '希 西 家 就 转 脸 朝 墙 ， 祷 告 耶 和 华 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10102', '12', '20', '3', '“ 耶 和 华 啊 ， 求 你 记 念 我 在 你 面 前 怎 样 存 完 全 的 心 ， 按 诚 实 行 事 ， 又 做 你 眼 中 所 看 为 善 的 。 ” 希 西 家 就 痛 哭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10103', '12', '20', '4', '以 赛 亚 出 来 ， 还 没 有 到 中 院 ｛ 院 ： 或 译 城 ｝ ， 耶 和 华 的 话 就 临 到 他 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10104', '12', '20', '5', '“ 你 回 去 告 诉 我 民 的 君 希 西 家 说 ： 耶 和 华 ─ ─ 你 祖 大 卫 的 神 如 此 说 ： ‘ 我 听 见 了 你 的 祷 告 ， 看 见 了 你 的 眼 泪 ， 我 必 医 治 你 ； 到 第 三 日 ， 你 必 上 到 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10105', '12', '20', '6', '我 必 加 增 你 十 五 年 的 寿 数 ， 并 且 我 要 救 你 和 这 城 脱 离 亚 述 王 的 手 。 我 为 自 己 和 我 仆 人 大 卫 的 缘 故 ， 必 保 护 这 城 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10106', '12', '20', '7', '以 赛 亚 说 ： “ 当 取 一 块 无 花 果 饼 来 。 ” 人 就 取 了 来 ， 贴 在 疮 上 ， 王 便 痊 愈 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10107', '12', '20', '8', '希 西 家 问 以 赛 亚 说 ： “ 耶 和 华 必 医 治 我 ， 到 第 三 日 ， 我 能 上 耶 和 华 的 殿 ， 有 什 么 兆 头 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10108', '12', '20', '9', '以 赛 亚 说 ： “ 耶 和 华 必 成 就 他 所 说 的 。 这 是 他 给 你 的 兆 头 ： 你 要 日 影 向 前 进 十 度 呢 ？ 是 要 往 后 退 十 度 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10109', '12', '20', '10', '希 西 家 回 答 说 ： “ 日 影 向 前 进 十 度 容 易 ， 我 要 日 影 往 后 退 十 度 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10110', '12', '20', '11', '先 知 以 赛 亚 求 告 耶 和 华 ， 耶 和 华 就 使 亚 哈 斯 的 日 晷 向 前 进 的 日 影 ， 往 后 退 了 十 度 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10111', '12', '20', '12', '＜ 从 巴 比 伦 来 的 使 者 （ 赛   3 9 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10112', '12', '20', '13', '希 西 家 听 从 使 者 的 话 ， 就 把 他 宝 库 的 金 子 、 银 子 、 香 料 、 贵 重 的 膏 油 ， 和 他 武 库 的 一 切 军 器 ， 并 他 所 有 的 财 宝 ， 都 给 他 们 看 。 他 家 中 和 他 全 国 之 内 ， 希 西 家 没 有 一 样 不 给 他 们 看 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10113', '12', '20', '14', '于 是 先 知 以 赛 亚 来 见 希 西 家 王 ， 问 他 说 ： “ 这 些 人 说 什 么 ？ 他 们 从 哪 里 来 见 你 ？ ” 希 西 家 说 ： “ 他 们 从 远 方 的 巴 比 伦 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10114', '12', '20', '15', '以 赛 亚 说 ： “ 他 们 在 你 家 里 看 见 了 什 么 ？ ” 希 西 家 说 ： “ 凡 我 家 中 所 有 的 ， 他 们 都 看 见 了 ； 我 财 宝 中 没 有 一 样 不 给 他 们 看 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10115', '12', '20', '16', '以 赛 亚 对 希 西 家 说 ： “ 你 要 听 耶 和 华 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10116', '12', '20', '17', '日 子 必 到 ， 凡 你 家 里 所 有 的 ， 并 你 列 祖 积 蓄 到 如 今 的 ， 都 要 被 掳 到 巴 比 伦 去 ， 不 留 下 一 样 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10117', '12', '20', '18', '并 且 从 你 本 身 所 生 的 众 子 ， 其 中 必 有 被 掳 去 在 巴 比 伦 王 宫 里 当 太 监 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10118', '12', '20', '19', '希 西 家 对 以 赛 亚 说 ： “ 你 所 说 耶 和 华 的 话 甚 好 ！ 若 在 我 的 年 日 中 有 太 平 和 稳 固 的 景 况 ， 岂 不 是 好 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10119', '12', '20', '20', '＜ 希 西 家 逝 世 （ 代 下   3 2 : 3 2 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10120', '12', '20', '21', '希 西 家 与 他 列 祖 同 睡 。 他 儿 子 玛 拿 西 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10121', '12', '21', '1', '＜ 犹 大 国 的 王 玛 拿 西 （ 代 下   3 3 : 1 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10122', '12', '21', '2', '玛 拿 西 行 耶 和 华 眼 中 看 为 恶 的 事 ， 效 法 耶 和 华 在 以 色 列 人 面 前 赶 出 的 外 邦 人 所 行 可 憎 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10123', '12', '21', '3', '重 新 建 筑 他 父 希 西 家 所 毁 坏 的 邱 坛 ， 又 为 巴 力 筑 坛 ， 做 亚 舍 拉 像 ， 效 法 以 色 列 王 亚 哈 所 行 的 ， 且 敬 拜 事 奉 天 上 的 万 象 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10124', '12', '21', '4', '在 耶 和 华 殿 宇 中 筑 坛 。 耶 和 华 曾 指 着 这 殿 说 ： “ 我 必 立 我 的 名 在 耶 路 撒 冷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10125', '12', '21', '5', '他 在 耶 和 华 殿 的 两 院 中 为 天 上 的 万 象 筑 坛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10126', '12', '21', '6', '并 使 他 的 儿 子 经 火 ， 又 观 兆 ， 用 法 术 ， 立 交 鬼 的 和 行 巫 术 的 ， 多 行 耶 和 华 眼 中 看 为 恶 的 事 ， 惹 动 他 的 怒 气 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10127', '12', '21', '7', '又 在 殿 内 立 雕 刻 的 亚 舍 拉 像 。 耶 和 华 曾 对 大 卫 和 他 儿 子 所 罗 门 说 ： “ 我 在 以 色 列 众 支 派 中 所 选 择 的 耶 路 撒 冷 和 这 殿 ， 必 立 我 的 名 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10128', '12', '21', '8', '以 色 列 人 若 谨 守 遵 行 我 一 切 所 吩 咐 他 们 的 和 我 仆 人 摩 西 所 吩 咐 他 们 的 一 切 律 法 ， 我 就 不 再 使 他 们 挪 移 离 开 我 所 赐 给 他 们 列 祖 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10129', '12', '21', '9', '他 们 却 不 听 从 。 玛 拿 西 引 诱 他 们 行 恶 ， 比 耶 和 华 在 以 色 列 人 面 前 所 灭 的 列 国 更 甚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10130', '12', '21', '10', '耶 和 华 藉 他 仆 人 众 先 知 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10131', '12', '21', '11', '“ 因 犹 大 王 玛 拿 西 行 这 些 可 憎 的 恶 事 比 先 前 亚 摩 利 人 所 行 的 更 甚 ， 使 犹 大 人 拜 他 的 偶 像 ， 陷 在 罪 里 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10132', '12', '21', '12', '所 以 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 必 降 祸 与 耶 路 撒 冷 和 犹 大 ， 叫 一 切 听 见 的 人 无 不 耳 鸣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10133', '12', '21', '13', '我 必 用 量 撒 马 利 亚 的 准 绳 和 亚 哈 家 的 线 铊 拉 在 耶 路 撒 冷 上 ， 必 擦 净 耶 路 撒 冷 ， 如 人 擦 盘 ， 将 盘 倒 扣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10134', '12', '21', '14', '我 必 弃 掉 所 余 剩 的 子 民 ｛ 原 文 是 产 业 ｝ ， 把 他 们 交 在 仇 敌 手 中 ， 使 他 们 成 为 一 切 仇 敌 掳 掠 之 物 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10135', '12', '21', '15', '是 因 他 们 自 从 列 祖 出 埃 及 直 到 如 今 ， 常 行 我 眼 中 看 为 恶 的 事 ， 惹 动 我 的 怒 气 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10136', '12', '21', '16', '玛 拿 西 行 耶 和 华 眼 中 看 为 恶 的 事 ， 使 犹 大 人 陷 在 罪 里 ， 又 流 许 多 无 辜 人 的 血 ， 充 满 了 耶 路 撒 冷 ， 从 这 边 直 到 那 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10137', '12', '21', '17', '玛 拿 西 其 余 的 事 ， 凡 他 所 行 的 和 他 所 犯 的 罪 都 写 在 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10138', '12', '21', '18', '玛 拿 西 与 他 列 祖 同 睡 ， 葬 在 自 己 宫 院 乌 撒 的 园 内 ； 他 儿 子 亚 们 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10139', '12', '21', '19', '＜ 犹 大 国 的 王 亚 们 （ 代 下   3 3 : 2 1 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10140', '12', '21', '20', '亚 们 行 耶 和 华 眼 中 看 为 恶 的 事 ， 与 他 父 亲 玛 拿 西 所 行 的 一 样 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10141', '12', '21', '21', '行 他 父 亲 一 切 所 行 的 ， 敬 奉 他 父 亲 所 敬 奉 的 偶 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10142', '12', '21', '22', '离 弃 耶 和 华 ─ ─ 他 列 祖 的 神 ， 不 遵 行 耶 和 华 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10143', '12', '21', '23', '亚 们 王 的 臣 仆 背 叛 他 ， 在 宫 里 杀 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10144', '12', '21', '24', '但 国 民 杀 了 那 些 背 叛 亚 们 王 的 人 ， 立 他 儿 子 约 西 亚 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10145', '12', '21', '25', '亚 们 其 余 所 行 的 事 都 写 在 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10146', '12', '21', '26', '亚 们 葬 在 乌 撒 的 园 内 自 己 的 坟 墓 里 。 他 儿 子 约 西 亚 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10147', '12', '22', '1', '＜ 犹 大 国 的 王 约 西 亚 （ 代 下   3 4 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10148', '12', '22', '2', '约 西 亚 行 耶 和 华 眼 中 看 为 正 的 事 ， 行 他 祖 大 卫 一 切 所 行 的 ， 不 偏 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10149', '12', '22', '3', '＜ 发 现 律 法 书 （ 代 下   3 4 : 8 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10150', '12', '22', '4', '“ 你 去 见 大 祭 司 希 勒 家 ， 使 他 将 奉 到 耶 和 华 殿 的 银 子 ， 就 是 守 门 的 从 民 中 收 聚 的 银 子 ， 数 算 数 算 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10151', '12', '22', '5', '交 给 耶 和 华 殿 里 办 事 的 人 ， 使 他 们 转 交 耶 和 华 殿 里 做 工 的 人 ， 好 修 理 殿 的 破 坏 之 处 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10152', '12', '22', '6', '就 是 转 交 木 匠 和 工 人 ， 并 瓦 匠 ， 又 买 木 料 和 凿 成 的 石 头 修 理 殿 宇 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10153', '12', '22', '7', '将 银 子 交 在 办 事 的 人 手 里 ， 不 与 他 们 算 帐 ， 因 为 他 们 办 事 诚 实 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10154', '12', '22', '8', '大 祭 司 希 勒 家 对 书 记 沙 番 说 ： “ 我 在 耶 和 华 殿 里 得 了 律 法 书 。 ” 希 勒 家 将 书 递 给 沙 番 ， 沙 番 就 看 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10155', '12', '22', '9', '书 记 沙 番 到 王 那 里 ， 回 覆 王 说 ： “ 你 的 仆 人 已 将 殿 里 的 银 子 倒 出 数 算 ， 交 给 耶 和 华 殿 里 办 事 的 人 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10156', '12', '22', '10', '书 记 沙 番 又 对 王 说 ： “ 祭 司 希 勒 家 递 给 我 一 卷 书 。 ” 沙 番 就 在 王 面 前 读 那 书 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10157', '12', '22', '11', '王 听 见 律 法 书 上 的 话 ， 便 撕 裂 衣 服 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10158', '12', '22', '12', '吩 咐 祭 司 希 勒 家 与 沙 番 的 儿 子 亚 希 甘 、 米 该 亚 的 儿 子 亚 革 波 、 书 记 沙 番 和 王 的 臣 仆 亚 撒 雅 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10159', '12', '22', '13', '“ 你 们 去 为 我 、 为 民 、 为 犹 大 众 人 ， 以 这 书 上 的 话 求 问 耶 和 华 ； 因 为 我 们 列 祖 没 有 听 从 这 书 上 的 言 语 ， 没 有 遵 著 书 上 所 吩 咐 我 们 的 去 行 ， 耶 和 华 就 向 我 们 大 发 烈 怒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10160', '12', '22', '14', '于 是 ， 祭 司 希 勒 家 和 亚 希 甘 、 亚 革 波 、 沙 番 、 亚 撒 雅 都 去 见 女 先 知 户 勒 大 。 户 勒 大 是 掌 管 礼 服 沙 龙 的 妻 ； 沙 龙 是 哈 珥 哈 斯 的 孙 子 、 特 瓦 的 儿 子 。 户 勒 大 住 在 耶 路 撒 冷 第 二 区 。 他 们 请 问 于 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10161', '12', '22', '15', '她 对 他 们 说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： ‘ 你 们 可 以 回 覆 那 差 遣 你 们 来 见 我 的 人 说 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10162', '12', '22', '16', '耶 和 华 如 此 说 ： 我 必 照 着 犹 大 王 所 读 那 书 上 的 一 切 话 ， 降 祸 与 这 地 和 其 上 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10163', '12', '22', '17', '因 为 他 们 离 弃 我 ， 向 别 神 烧 香 ， 用 他 们 手 所 做 的 惹 我 发 怒 ， 所 以 我 的 忿 怒 必 向 这 地 发 作 ， 总 不 止 息 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10164', '12', '22', '18', '然 而 ， 差 遣 你 们 来 求 问 耶 和 华 的 犹 大 王 ， 你 们 要 这 样 回 覆 他 说 ： ‘ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 至 于 你 所 听 见 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10165', '12', '22', '19', '就 是 听 见 我 指 着 这 地 和 其 上 的 居 民 所 说 、 要 使 这 地 变 为 荒 场 、 民 受 咒 诅 的 话 ， 你 便 心 里 敬 服 ， 在 我 面 前 自 卑 ， 撕 裂 衣 服 ， 向 我 哭 泣 ， 因 此 我 应 允 了 你 。 这 是 我 ─ ─ 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10166', '12', '22', '20', '我 必 使 你 平 平 安 安 地 归 到 坟 墓 到 你 列 祖 那 里 ； 我 要 降 与 这 地 的 一 切 灾 祸 ， 你 也 不 致 亲 眼 看 见 。 ’ ” 他 们 就 回 覆 王 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10167', '12', '23', '1', '＜ 约 西 亚 废 除 异 教 崇 拜 （ 代 下   3 4 : 3 - 7 ； 3 4 : 2 9 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10168', '12', '23', '2', '王 和 犹 大 众 人 与 耶 路 撒 冷 的 居 民 ， 并 祭 司 、 先 知 ， 和 所 有 的 百 姓 ， 无 论 大 小 ， 都 一 同 上 到 耶 和 华 的 殿 ； 王 就 把 耶 和 华 殿 里 所 得 的 约 书 念 给 他 们 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10169', '12', '23', '3', '王 站 在 柱 旁 ， 在 耶 和 华 面 前 立 约 ， 要 尽 心 尽 性 地 顺 从 耶 和 华 ， 遵 守 他 的 诫 命 、 法 度 、 律 例 ， 成 就 这 书 上 所 记 的 约 言 。 众 民 都 服 从 这 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10170', '12', '23', '4', '王 吩 咐 大 祭 司 希 勒 家 和 副 祭 司 ， 并 把 门 的 ， 将 那 为 巴 力 和 亚 舍 拉 ， 并 天 上 万 象 所 造 的 器 皿 ， 都 从 耶 和 华 殿 里 搬 出 来 ， 在 耶 路 撒 冷 外 汲 沦 溪 旁 的 田 间 烧 了 ， 把 灰 拿 到 伯 特 利 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10171', '12', '23', '5', '从 前 犹 大 列 王 所 立 拜 偶 像 的 祭 司 ， 在 犹 大 城 邑 的 邱 坛 和 耶 路 撒 冷 的 周 围 烧 香 ， 现 在 王 都 废 去 ， 又 废 去 向 巴 力 和 日 、 月 、 行 星 ｛ 或 译 ： 十 二 宫 ｝ ， 并 天 上 万 象 烧 香 的 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10172', '12', '23', '6', '又 从 耶 和 华 殿 里 将 亚 舍 拉 搬 到 耶 路 撒 冷 外 汲 沦 溪 边 焚 烧 ， 打 碎 成 灰 ， 将 灰 撒 在 平 民 的 坟 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10173', '12', '23', '7', '又 拆 毁 耶 和 华 殿 里 娈 童 的 屋 子 ， 就 是 妇 女 为 亚 舍 拉 织 帐 子 的 屋 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10174', '12', '23', '8', '并 且 从 犹 大 的 城 邑 带 众 祭 司 来 ， 污 秽 祭 司 烧 香 的 邱 坛 ， 从 迦 巴 直 到 别 是 巴 ， 又 拆 毁 城 门 旁 的 邱 坛 ， 这 邱 坛 在 邑 宰 约 书 亚 门 前 ， 进 城 门 的 左 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10175', '12', '23', '9', '但 是 邱 坛 的 祭 司 不 登 耶 路 撒 冷 耶 和 华 的 坛 ， 只 在 他 们 弟 兄 中 间 吃 无 酵 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10176', '12', '23', '10', '又 污 秽 欣 嫩 子 谷 的 陀 斐 特 ， 不 许 人 在 那 里 使 儿 女 经 火 献 给 摩 洛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10177', '12', '23', '11', '又 将 犹 大 列 王 在 耶 和 华 殿 门 旁 、 太 监 拿 单 ． 米 勒 靠 近 游 廊 的 屋 子 、 向 日 头 所 献 的 马 废 去 ， 且 用 火 焚 烧 日 车 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10178', '12', '23', '12', '犹 大 列 王 在 亚 哈 斯 楼 顶 上 所 筑 的 坛 和 玛 拿 西 在 耶 和 华 殿 两 院 中 所 筑 的 坛 ， 王 都 拆 毁 打 碎 了 ， 就 把 灰 倒 在 汲 沦 溪 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10179', '12', '23', '13', '从 前 以 色 列 王 所 罗 门 在 耶 路 撒 冷 前 、 邪 僻 山 右 边 为 西 顿 人 可 憎 的 神 亚 斯 她 录 、 摩 押 人 可 憎 的 神 基 抹 、 亚 扪 人 可 憎 的 神 米 勒 公 所 筑 的 邱 坛 ， 王 都 污 秽 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10180', '12', '23', '14', '又 打 碎 柱 像 ， 砍 下 木 偶 ， 将 人 的 骨 头 充 满 了 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10181', '12', '23', '15', '他 将 伯 特 利 的 坛 ， 就 是 叫 以 色 列 人 陷 在 罪 里 、 尼 八 的 儿 子 耶 罗 波 安 所 筑 的 那 坛 ， 都 拆 毁 焚 烧 ， 打 碎 成 灰 ， 并 焚 烧 了 亚 舍 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10182', '12', '23', '16', '约 西 亚 回 头 ， 看 见 山 上 的 坟 墓 ， 就 打 发 人 将 坟 墓 里 的 骸 骨 取 出 来 ， 烧 在 坛 上 ， 污 秽 了 坛 ， 正 如 从 前 神 人 宣 传 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10183', '12', '23', '17', '约 西 亚 问 说 ： “ 我 所 看 见 的 是 什 么 碑 ？ ” 那 城 里 的 人 回 答 说 ： “ 先 前 有 神 人 从 犹 大 来 ， 预 先 说 王 现 在 向 伯 特 利 坛 所 行 的 事 ， 这 就 是 他 的 墓 碑 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10184', '12', '23', '18', '约 西 亚 说 ： “ 由 他 吧 ！ 不 要 挪 移 他 的 骸 骨 。 ” 他 们 就 不 动 他 的 骸 骨 ， 也 不 动 从 撒 马 利 亚 来 那 先 知 的 骸 骨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10185', '12', '23', '19', '从 前 以 色 列 诸 王 在 撒 马 利 亚 的 城 邑 建 筑 邱 坛 的 殿 ， 惹 动 耶 和 华 的 怒 气 ， 现 在 约 西 亚 都 废 去 了 ， 就 如 他 在 伯 特 利 所 行 的 一 般 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10186', '12', '23', '20', '又 将 邱 坛 的 祭 司 都 杀 在 坛 上 ， 并 在 坛 上 烧 人 的 骨 头 ， 就 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10187', '12', '23', '21', '＜ 约 西 亚 守 逾 越 节 （ 代 下   3 5 : 1 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10188', '12', '23', '22', '自 从 士 师 治 理 以 色 列 人 和 以 色 列 王 、 犹 大 王 的 时 候 ， 直 到 如 今 ， 实 在 没 有 守 过 这 样 的 逾 越 节 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10189', '12', '23', '23', '只 有 约 西 亚 王 十 八 年 在 耶 路 撒 冷 向 耶 和 华 守 这 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10190', '12', '23', '24', '＜ 约 西 亚 的 其 他 改 革 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10191', '12', '23', '25', '在 约 西 亚 以 前 没 有 王 像 他 尽 心 、 尽 性 、 尽 力 地 归 向 耶 和 华 ， 遵 行 摩 西 的 一 切 律 法 ； 在 他 以 后 也 没 有 兴 起 一 个 王 像 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10192', '12', '23', '26', '然 而 ， 耶 和 华 向 犹 大 所 发 猛 烈 的 怒 气 仍 不 止 息 ， 是 因 玛 拿 西 诸 事 惹 动 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10193', '12', '23', '27', '耶 和 华 说 ： “ 我 必 将 犹 大 人 从 我 面 前 赶 出 ， 如 同 赶 出 以 色 列 人 一 般 ； 我 必 弃 掉 我 从 前 所 选 择 的 这 城 ─ ─ 耶 路 撒 冷 和 我 所 说 立 我 名 的 殿 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10194', '12', '23', '28', '＜ 约 西 亚 逝 世 （ 代 下   3 5 : 2 0 - 3 6 : 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10195', '12', '23', '29', '约 西 亚 年 间 ， 埃 及 王 法 老 尼 哥 上 到 幼 发 拉 底 河 攻 击 亚 述 王 ； 约 西 亚 王 去 抵 挡 他 。 埃 及 王 遇 见 约 西 亚 在 米 吉 多 ， 就 杀 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10196', '12', '23', '30', '他 的 臣 仆 用 车 将 他 的 尸 首 从 米 吉 多 送 到 耶 路 撒 冷 ， 葬 在 他 自 己 的 坟 墓 里 。 国 民 膏 约 西 亚 的 儿 子 约 哈 斯 接 续 他 父 亲 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10197', '12', '23', '31', '＜ 犹 大 国 的 王 约 哈 斯 （ 代 下   3 6 : 2 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10198', '12', '23', '32', '约 哈 斯 行 耶 和 华 眼 中 看 为 恶 的 事 ， 效 法 他 列 祖 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10199', '12', '23', '33', '法 老 尼 哥 将 约 哈 斯 锁 禁 在 哈 马 地 的 利 比 拉 ， 不 许 他 在 耶 路 撒 冷 作 王 ， 又 罚 犹 大 国 银 子 一 百 他 连 得 ， 金 子 一 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10200', '12', '23', '34', '法 老 尼 哥 立 约 西 亚 的 儿 子 以 利 亚 敬 接 续 他 父 亲 约 西 亚 作 王 ， 给 他 改 名 叫 约 雅 敬 ， 却 将 约 哈 斯 带 到 埃 及 ， 他 就 死 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10201', '12', '23', '35', '＜ 犹 大 国 的 王 约 雅 敬 （ 代 下   3 6 : 5 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10202', '12', '23', '36', '约 雅 敬 登 基 的 时 候 年 二 十 五 岁 ， 在 耶 路 撒 冷 作 王 十 一 年 。 他 母 亲 名 叫 西 布 大 ， 是 鲁 玛 人 毗 大 雅 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10203', '12', '23', '37', '约 雅 敬 行 耶 和 华 眼 中 看 为 恶 的 事 ， 效 法 他 列 祖 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10204', '12', '24', '1', '约 雅 敬 年 间 ， 巴 比 伦 王 尼 布 甲 尼 撒 上 到 犹 大 ； 约 雅 敬 服 事 他 三 年 ， 然 后 背 叛 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10205', '12', '24', '2', '耶 和 华 使 迦 勒 底 军 、 亚 兰 军 、 摩 押 军 ， 和 亚 扪 人 的 军 来 攻 击 约 雅 敬 ， 毁 灭 犹 大 ， 正 如 耶 和 华 藉 他 仆 人 众 先 知 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10206', '12', '24', '3', '这 祸 临 到 犹 大 人 ， 诚 然 是 耶 和 华 所 命 的 ， 要 将 他 们 从 自 己 面 前 赶 出 ， 是 因 玛 拿 西 所 犯 的 一 切 罪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10207', '12', '24', '4', '又 因 他 流 无 辜 人 的 血 ， 充 满 了 耶 路 撒 冷 ； 耶 和 华 决 不 肯 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10208', '12', '24', '5', '约 雅 敬 其 余 的 事 ， 凡 他 所 行 的 都 写 在 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10209', '12', '24', '6', '约 雅 敬 与 他 列 祖 同 睡 。 他 儿 子 约 雅 斤 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10210', '12', '24', '7', '埃 及 王 不 再 从 他 国 中 出 来 ； 因 为 巴 比 伦 王 将 埃 及 王 所 管 之 地 ， 从 埃 及 小 河 直 到 幼 发 拉 底 河 都 夺 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10211', '12', '24', '8', '＜ 犹 大 国 的 王 约 雅 斤 （ 代 下   3 6 : 9 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10212', '12', '24', '9', '约 雅 斤 行 耶 和 华 眼 中 看 为 恶 的 事 ， 效 法 他 父 亲 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10213', '12', '24', '10', '那 时 ， 巴 比 伦 王 尼 布 甲 尼 撒 的 军 兵 上 到 耶 路 撒 冷 ， 围 困 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10214', '12', '24', '11', '当 他 军 兵 围 困 城 的 时 候 ， 巴 比 伦 王 尼 布 甲 尼 撒 就 亲 自 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10215', '12', '24', '12', '犹 大 王 约 雅 斤 和 他 母 亲 、 臣 仆 、 首 领 、 太 监 一 同 出 城 ， 投 降 巴 比 伦 王 ； 巴 比 伦 王 便 拿 住 他 。 那 时 是 巴 比 伦 王 第 八 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10216', '12', '24', '13', '巴 比 伦 王 将 耶 和 华 殿 和 王 宫 里 的 宝 物 都 拿 去 了 ， 将 以 色 列 王 所 罗 门 所 造 耶 和 华 殿 里 的 金 器 都 毁 坏 了 ， 正 如 耶 和 华 所 说 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10217', '12', '24', '14', '又 将 耶 路 撒 冷 的 众 民 和 众 首 领 ， 并 所 有 大 能 的 勇 士 ， 共 一 万 人 ， 连 一 切 木 匠 、 铁 匠 都 掳 了 去 ； 除 了 国 中 极 贫 穷 的 人 以 外 ， 没 有 剩 下 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10218', '12', '24', '15', '并 将 约 雅 斤 和 王 母 、 后 妃 、 太 监 ， 与 国 中 的 大 官 ， 都 从 耶 路 撒 冷 掳 到 巴 比 伦 去 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10219', '12', '24', '16', '又 将 一 切 勇 士 七 千 人 和 木 匠 、 铁 匠 一 千 人 ， 都 是 能 上 阵 的 勇 士 ， 全 掳 到 巴 比 伦 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10220', '12', '24', '17', '巴 比 伦 王 立 约 雅 斤 的 叔 叔 玛 探 雅 代 替 他 作 王 ， 给 玛 探 雅 改 名 叫 西 底 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10221', '12', '24', '18', '＜ 犹 大 国 的 王 西 底 家 （ 代 下   3 6 : 1 1 - 1 2 ； 耶   5 2 : 1 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10222', '12', '24', '19', '西 底 家 行 耶 和 华 眼 中 看 为 恶 的 事 ， 是 照 约 雅 敬 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10223', '12', '24', '20', '因 此 耶 和 华 的 怒 气 在 耶 路 撒 冷 和 犹 大 发 作 ， 以 致 将 人 民 从 自 己 面 前 赶 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10224', '12', '25', '1', '＜ 耶 路 撒 冷 陷 落 （ 代 下   3 6 : 1 3 - 2 1 ； 耶   5 2 : 3 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10225', '12', '25', '2', '于 是 城 被 围 困 ， 直 到 西 底 家 王 十 一 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10226', '12', '25', '3', '四 月 初 九 日 ， 城 里 有 大 饥 荒 ， 甚 至 百 姓 都 没 有 粮 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10227', '12', '25', '4', '城 被 攻 破 ， 一 切 兵 丁 就 在 夜 间 从 靠 近 王 园 两 城 中 间 的 门 逃 跑 。 迦 勒 底 人 正 在 四 围 攻 城 ， 王 就 向 亚 拉 巴 逃 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10228', '12', '25', '5', '迦 勒 底 的 军 队 追 赶 王 ， 在 耶 利 哥 的 平 原 追 上 他 ； 他 的 全 军 都 离 开 他 四 散 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10229', '12', '25', '6', '迦 勒 底 人 就 拿 住 王 ， 带 他 到 在 利 比 拉 的 巴 比 伦 王 那 里 审 判 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10230', '12', '25', '7', '在 西 底 家 眼 前 杀 了 他 的 众 子 ， 并 且 剜 了 西 底 家 的 眼 睛 ， 用 铜 链 锁 着 他 ， 带 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10231', '12', '25', '8', '＜ 圣 殿 被 毁 （ 耶   5 2 : 1 2 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10232', '12', '25', '9', '用 火 焚 烧 耶 和 华 的 殿 和 王 宫 ， 又 焚 烧 耶 路 撒 冷 的 房 屋 ， 就 是 各 大 户 家 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10233', '12', '25', '10', '跟 从 护 卫 长 迦 勒 底 的 全 军 就 拆 毁 耶 路 撒 冷 四 围 的 城 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10234', '12', '25', '11', '那 时 护 卫 长 尼 布 撒 拉 旦 将 城 里 所 剩 下 的 百 姓 ， 并 已 经 投 降 巴 比 伦 王 的 人 ， 以 及 大 众 所 剩 下 的 人 ， 都 掳 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10235', '12', '25', '12', '但 护 卫 长 留 下 些 民 中 最 穷 的 ， 使 他 们 修 理 葡 萄 园 ， 耕 种 田 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10236', '12', '25', '13', '耶 和 华 殿 的 铜 柱 ， 并 耶 和 华 殿 的 盆 座 和 铜 海 ， 迦 勒 底 人 都 打 碎 了 ， 将 那 铜 运 到 巴 比 伦 去 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10237', '12', '25', '14', '又 带 去 锅 、 铲 子 、 蜡 剪 、 调 羹 ， 并 所 用 的 一 切 铜 器 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10238', '12', '25', '15', '火 鼎 、 碗 ， 无 论 金 的 银 的 ， 护 卫 长 也 都 带 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10239', '12', '25', '16', '所 罗 门 为 耶 和 华 殿 所 造 的 两 根 铜 柱 、 一 个 铜 海 ， 和 几 个 盆 座 ， 这 一 切 的 铜 ， 多 得 无 法 可 称 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10240', '12', '25', '17', '这 一 根 柱 子 高 十 八 肘 ， 柱 上 有 铜 顶 ， 高 三 肘 ； 铜 顶 的 周 围 有 网 子 和 石 榴 ， 都 是 铜 的 。 那 一 根 柱 子 ， 照 此 一 样 ， 也 有 网 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10241', '12', '25', '18', '＜ 犹 大 人 被 掳 （ 耶   5 2 ： 2 4 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10242', '12', '25', '19', '又 从 城 中 拿 住 一 个 管 理 兵 丁 的 官 ｛ 或 译 ： 太 监 ｝ ， 并 在 城 里 所 遇 常 见 王 面 的 五 个 人 和 检 点 国 民 军 长 的 书 记 ， 以 及 城 里 遇 见 的 国 民 六 十 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10243', '12', '25', '20', '护 卫 长 尼 布 撒 拉 旦 将 这 些 人 带 到 在 利 比 拉 的 巴 比 伦 王 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10244', '12', '25', '21', '巴 比 伦 王 就 把 他 们 击 杀 在 哈 马 地 的 利 比 拉 。 这 样 ， 犹 大 人 被 掳 去 离 开 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10245', '12', '25', '22', '＜ 立 基 大 利 作 犹 大 省 长 （ 耶   4 0 : 7 - 9 ； 4 1 : 1 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10246', '12', '25', '23', '众 军 长 和 属 他 们 的 人 听 见 巴 比 伦 王 立 了 基 大 利 作 省 长 ， 于 是 军 长 尼 探 雅 的 儿 子 以 实 玛 利 、 加 利 亚 的 儿 子 约 哈 难 、 尼 陀 法 人 单 户 蔑 的 儿 子 西 莱 雅 、 玛 迦 人 的 儿 子 雅 撒 尼 亚 ， 和 属 他 们 的 人 都 到 米 斯 巴 见 基 大 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10247', '12', '25', '24', '基 大 利 向 他 们 和 属 他 们 的 人 起 誓 说 ： “ 你 们 不 必 惧 怕 迦 勒 底 臣 仆 ， 只 管 住 在 这 地 服 事 巴 比 伦 王 ， 就 可 以 得 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10248', '12', '25', '25', '七 月 间 ， 宗 室 以 利 沙 玛 的 孙 子 、 尼 探 雅 的 儿 子 以 实 玛 利 带 着 十 个 人 来 ， 杀 了 基 大 利 和 同 他 在 米 斯 巴 的 犹 大 人 与 迦 勒 底 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10249', '12', '25', '26', '于 是 众 民 ， 无 论 大 小 ， 连 众 军 长 ； 因 为 惧 怕 迦 勒 底 人 ， 都 起 身 往 埃 及 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10250', '12', '25', '27', '＜ 约 雅 斤 被 释 （ 耶   5 2 : 3 1 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10251', '12', '25', '28', '又 对 他 说 恩 言 ， 使 他 的 位 高 过 与 他 一 同 在 巴 比 伦 众 王 的 位 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10252', '12', '25', '29', '给 他 脱 了 囚 服 。 他 终 身 常 在 巴 比 伦 王 面 前 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10253', '12', '25', '30', '王 赐 他 所 需 用 的 食 物 ， 日 日 赐 他 一 分 ， 终 身 都 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10254', '13', '1', '1', '＜ 从 亚 当 到 亚 伯 拉 罕 （ 创   5 : 1 - 3 2 ； 1 0 : 1 - 3 2 ； 1 1 : 1 0 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10255', '13', '1', '2', '以 挪 士 生 该 南 ； 该 南 生 玛 勒 列 ； 玛 勒 列 生 雅 列 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10256', '13', '1', '3', '雅 列 生 以 诺 ； 以 诺 生 玛 土 撒 拉 ； 玛 土 撒 拉 生 拉 麦 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10257', '13', '1', '4', '拉 麦 生 挪 亚 ； 挪 亚 生 闪 、 含 、 雅 弗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10258', '13', '1', '5', '雅 弗 的 儿 子 是 歌 篾 、 玛 各 、 玛 代 、 雅 完 、 土 巴 、 米 设 、 提 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10259', '13', '1', '6', '歌 篾 的 儿 子 是 亚 实 基 拿 、 低 法 ｛ 在 创 世 记 十 章 三 节 是 利 法 ｝ 、 陀 迦 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10260', '13', '1', '7', '雅 完 的 儿 子 是 以 利 沙 、 他 施 、 基 提 、 多 单 ｛ 有 作 罗 单 的 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10261', '13', '1', '8', '含 的 儿 子 是 古 实 、 麦 西 、 弗 、 迦 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10262', '13', '1', '9', '古 实 的 儿 子 是 西 巴 、 哈 腓 拉 、 撒 弗 他 、 拉 玛 、 撒 弗 提 迦 。 拉 玛 的 儿 子 是 示 巴 、 底 但 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10263', '13', '1', '10', '古 实 生 宁 录 ； 他 为 世 上 英 雄 之 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10264', '13', '1', '11', '麦 西 生 路 低 人 、 亚 拿 米 人 、 利 哈 比 人 、 拿 弗 土 希 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10265', '13', '1', '12', '帕 斯 鲁 细 人 、 迦 斯 路 希 人 、 迦 斐 托 人 ； 从 迦 斐 托 出 来 的 有 非 利 士 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10266', '13', '1', '13', '迦 南 生 长 子 西 顿 ， 又 生 赫');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10267', '13', '1', '14', '和 耶 布 斯 人 、 亚 摩 利 人 、 革 迦 撒 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10268', '13', '1', '15', '希 未 人 、 亚 基 人 、 西 尼 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10269', '13', '1', '16', '亚 瓦 底 人 、 洗 玛 利 人 ， 并 哈 马 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10270', '13', '1', '17', '闪 的 儿 子 是 以 拦 、 亚 述 、 亚 法 撒 、 路 德 、 亚 兰 、 乌 斯 、 户 勒 、 基 帖 、 米 设 ｛ 在 创 世 记 十 章 二 十 三 节 是 玛 施 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10271', '13', '1', '18', '亚 法 撒 生 沙 拉 ； 沙 拉 生 希 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10272', '13', '1', '19', '希 伯 生 了 两 个 儿 子 ： 一 个 名 叫 法 勒 ｛ 就 是 分 的 意 思 ｝ ， 因 为 那 时 人 就 分 地 居 住 ； 法 勒 的 兄 弟 名 叫 约 坍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10273', '13', '1', '20', '约 坍 生 亚 摩 答 、 沙 列 、 哈 萨 玛 非 、 耶 拉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10274', '13', '1', '21', '哈 多 兰 、 乌 萨 、 德 拉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10275', '13', '1', '22', '以 巴 录 、 亚 比 玛 利 、 示 巴 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10276', '13', '1', '23', '阿 斐 、 哈 腓 拉 、 约 巴 。 这 都 是 约 坍 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10277', '13', '1', '24', '闪 生 亚 法 撒 ； 亚 法 撒 生 沙 拉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10278', '13', '1', '25', '沙 拉 生 希 伯 ； 希 伯 生 法 勒 ； 法 勒 生 拉 吴 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10279', '13', '1', '26', '拉 吴 生 西 鹿 ； 西 鹿 生 拿 鹤 ； 拿 鹤 生 他 拉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10280', '13', '1', '27', '他 拉 生 亚 伯 兰 ， 亚 伯 兰 就 是 亚 伯 拉 罕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10281', '13', '1', '28', '＜ 以 实 玛 利 的 后 裔 （ 创   2 5 : 1 2 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10282', '13', '1', '29', '以 实 玛 利 的 儿 子 记 在 下 面 ： 以 实 玛 利 的 长 子 是 尼 拜 约 ， 其 次 是 基 达 、 押 德 别 、 米 比 衫 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10283', '13', '1', '30', '米 施 玛 、 度 玛 、 玛 撒 、 哈 达 、 提 玛 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10284', '13', '1', '31', '伊 突 、 拿 非 施 、 基 底 玛 。 这 都 是 以 实 玛 利 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10285', '13', '1', '32', '亚 伯 拉 罕 的 妾 基 土 拉 所 生 的 儿 子 ， 就 是 心 兰 、 约 珊 、 米 但 、 米 甸 、 伊 施 巴 、 书 亚 。 约 珊 的 儿 子 是 示 巴 、 底 但 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10286', '13', '1', '33', '米 甸 的 儿 子 是 以 法 、 以 弗 、 哈 诺 、 亚 比 大 、 以 勒 大 。 这 都 是 基 土 拉 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10287', '13', '1', '34', '＜ 以 扫 的 后 裔 （ 创   3 6 : 1 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10288', '13', '1', '35', '以 扫 的 儿 子 是 以 利 法 、 流 珥 、 耶 乌 施 、 雅 兰 、 可 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10289', '13', '1', '36', '以 利 法 的 儿 子 是 提 幔 、 阿 抹 、 洗 玻 、 迦 坦 、 基 纳 斯 、 亭 纳 、 亚 玛 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10290', '13', '1', '37', '流 珥 的 儿 子 是 拿 哈 、 谢 拉 、 沙 玛 、 米 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10291', '13', '1', '38', '＜ 以 东 地 的 原 住 民 （ 创   3 6 : 2 0 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10292', '13', '1', '39', '罗 坍 的 儿 子 是 何 利 、 荷 幔 ； 罗 坍 的 妹 子 是 亭 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10293', '13', '1', '40', '朔 巴 的 儿 子 是 亚 勒 文 、 玛 拿 辖 、 以 巴 录 、 示 非 、 阿 南 。 祭 便 的 儿 子 是 亚 雅 、 亚 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10294', '13', '1', '41', '亚 拿 的 儿 子 是 底 顺 。 底 顺 的 儿 子 是 哈 默 兰 、 伊 是 班 、 益 兰 、 基 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10295', '13', '1', '42', '以 察 的 儿 子 是 辟 罕 、 撒 番 、 亚 干 。 底 珊 的 儿 子 是 乌 斯 、 亚 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10296', '13', '1', '43', '＜ 以 东 诸 王 （ 创   3 6 : 3 1 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10297', '13', '1', '44', '比 拉 死 了 ， 波 斯 拉 人 谢 拉 的 儿 子 约 巴 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10298', '13', '1', '45', '约 巴 死 了 ， 提 幔 地 的 人 户 珊 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10299', '13', '1', '46', '户 珊 死 了 ， 比 达 的 儿 子 哈 达 接 续 他 作 王 。 这 哈 达 就 是 在 摩 押 地 杀 败 米 甸 人 的 ， 他 的 京 城 名 叫 亚 未 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10300', '13', '1', '47', '哈 达 死 了 ， 玛 士 利 加 人 桑 拉 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10301', '13', '1', '48', '桑 拉 死 了 ， 大 河 边 的 利 河 伯 人 扫 罗 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10302', '13', '1', '49', '扫 罗 死 了 ， 亚 革 波 的 儿 子 巴 勒 ． 哈 南 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10303', '13', '1', '50', '巴 勒 ． 哈 南 死 了 ， 哈 达 接 续 他 作 王 。 他 的 京 城 名 叫 巴 伊 ， 他 的 妻 子 名 叫 米 希 她 别 ， 是 米 ． 萨 合 的 孙 女 ， 玛 特 列 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10304', '13', '1', '51', '哈 达 死 了 ， 以 东 人 的 族 长 有 亭 纳 族 长 、 亚 勒 瓦 族 长 、 耶 帖 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10305', '13', '1', '52', '亚 何 利 巴 玛 族 长 、 以 拉 族 长 、 比 嫩 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10306', '13', '1', '53', '基 纳 斯 族 长 、 提 幔 族 长 、 米 比 萨 族 长 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10307', '13', '1', '54', '玛 基 叠 族 长 、 以 兰 族 长 。 这 都 是 以 东 人 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10308', '13', '2', '1', '＜ 犹 大 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10309', '13', '2', '2', '但 、 约 瑟 、 便 雅 悯 、 拿 弗 他 利 、 迦 得 、 亚 设 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10310', '13', '2', '3', '犹 大 的 儿 子 是 珥 、 俄 南 、 示 拉 ， 这 三 人 是 迦 南 人 书 亚 女 儿 所 生 的 。 犹 大 的 长 子 珥 在 耶 和 华 眼 中 看 为 恶 ， 耶 和 华 就 使 他 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10311', '13', '2', '4', '犹 大 的 儿 妇 她 玛 给 犹 大 生 法 勒 斯 和 谢 拉 。 犹 大 共 有 五 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10312', '13', '2', '5', '法 勒 斯 的 儿 子 是 希 斯 仑 、 哈 母 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10313', '13', '2', '6', '谢 拉 的 儿 子 是 心 利 、 以 探 、 希 幔 、 甲 各 、 大 拉 ｛ 就 是 达 大 ｝ ， 共 五 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10314', '13', '2', '7', '迦 米 的 儿 子 是 亚 干 ， 这 亚 干 在 当 灭 的 物 上 犯 了 罪 ， 连 累 了 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10315', '13', '2', '8', '以 探 的 儿 子 是 亚 撒 利 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10316', '13', '2', '9', '＜ 大 卫 王 的 家 谱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10317', '13', '2', '10', '兰 生 亚 米 拿 达 ； 亚 米 拿 达 生 拿 顺 。 拿 顺 作 犹 大 人 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10318', '13', '2', '11', '拿 顺 生 撒 门 ； 撒 门 生 波 阿 斯 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10319', '13', '2', '12', '波 阿 斯 生 俄 备 得 ； 俄 备 得 生 耶 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10320', '13', '2', '13', '耶 西 生 长 子 以 利 押 ， 次 子 亚 比 拿 达 ， 三 子 示 米 亚 ｛ 示 米 亚 就 是 沙 玛 ， 见 撒 母 耳 上 十 六 章 九 节 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10321', '13', '2', '14', '四 子 拿 坦 业 ， 五 子 拉 代 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10322', '13', '2', '15', '六 子 阿 鲜 ， 七 子 大 卫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10323', '13', '2', '16', '他 们 的 姊 妹 是 洗 鲁 雅 和 亚 比 该 。 洗 鲁 雅 的 儿 子 是 亚 比 筛 、 约 押 、 亚 撒 黑 ， 共 三 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10324', '13', '2', '17', '亚 比 该 生 亚 玛 撒 ； 亚 玛 撒 的 父 亲 是 以 实 玛 利 人 益 帖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10325', '13', '2', '18', '＜ 希 斯 仑 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10326', '13', '2', '19', '阿 苏 巴 死 了 ， 迦 勒 又 娶 以 法 她 ， 生 了 户 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10327', '13', '2', '20', '户 珥 生 乌 利 ； 乌 利 生 比 撒 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10328', '13', '2', '21', '希 斯 仑 正 六 十 岁 娶 了 基 列 父 亲 玛 吉 的 女 儿 ， 与 她 同 房 ； 玛 吉 的 女 儿 生 了 西 割 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10329', '13', '2', '22', '西 割 生 睚 珥 。 睚 珥 在 基 列 地 有 二 十 三 个 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10330', '13', '2', '23', '后 来 基 述 人 和 亚 兰 人 夺 了 睚 珥 的 城 邑 ， 并 基 纳 和 其 乡 村 ， 共 六 十 个 。 这 都 是 基 列 父 亲 玛 吉 之 子 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10331', '13', '2', '24', '希 斯 仑 在 迦 勒 ． 以 法 他 死 后 ， 他 的 妻 亚 比 雅 给 他 生 了 亚 施 户 ； 亚 施 户 是 提 哥 亚 的 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10332', '13', '2', '25', '＜ 耶 拉 篾 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10333', '13', '2', '26', '耶 拉 篾 又 娶 一 妻 名 叫 亚 她 拉 ， 是 阿 南 的 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10334', '13', '2', '27', '耶 拉 篾 长 子 兰 的 儿 子 是 玛 斯 、 雅 悯 、 以 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10335', '13', '2', '28', '阿 南 的 儿 子 是 沙 买 、 雅 大 。 沙 买 的 儿 子 是 拿 答 、 亚 比 述 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10336', '13', '2', '29', '亚 比 述 的 妻 名 叫 亚 比 孩 ， 亚 比 孩 给 他 生 了 亚 办 和 摩 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10337', '13', '2', '30', '拿 答 的 儿 子 是 西 列 、 亚 遍 ； 西 列 死 了 没 有 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10338', '13', '2', '31', '亚 遍 的 儿 子 是 以 示 ； 以 示 的 儿 子 是 示 珊 ； 示 珊 的 儿 子 是 亚 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10339', '13', '2', '32', '沙 买 兄 弟 雅 大 的 儿 子 是 益 帖 、 约 拿 单 ； 益 帖 死 了 没 有 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10340', '13', '2', '33', '约 拿 单 的 儿 子 是 比 勒 、 撒 萨 。 这 都 是 耶 拉 篾 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10341', '13', '2', '34', '示 珊 没 有 儿 子 ， 只 有 女 儿 。 示 珊 有 一 个 仆 人 名 叫 耶 哈 ， 是 埃 及 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10342', '13', '2', '35', '示 珊 将 女 儿 给 了 仆 人 耶 哈 为 妻 ， 给 他 生 了 亚 太 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10343', '13', '2', '36', '亚 太 生 拿 单 ； 拿 单 生 撒 拔 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10344', '13', '2', '37', '撒 拔 生 以 弗 拉 ； 以 弗 拉 生 俄 备 得 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10345', '13', '2', '38', '俄 备 得 生 耶 户 ； 耶 户 生 亚 撒 利 雅 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10346', '13', '2', '39', '亚 撒 利 雅 生 希 利 斯 ； 希 利 斯 生 以 利 亚 萨 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10347', '13', '2', '40', '以 利 亚 萨 生 西 斯 买 ； 西 斯 买 生 沙 龙 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10348', '13', '2', '41', '沙 龙 生 耶 加 米 雅 ； 耶 加 米 雅 生 以 利 沙 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10349', '13', '2', '42', '＜ 迦 勒 的 其 余 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10350', '13', '2', '43', '希 伯 仑 的 儿 子 是 可 拉 、 他 普 亚 、 利 肯 、 示 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10351', '13', '2', '44', '示 玛 生 拉 含 ， 是 约 干 之 祖 。 利 肯 生 沙 买 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10352', '13', '2', '45', '沙 买 的 儿 子 是 玛 云 ； 玛 云 是 伯 ． 夙 之 祖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10353', '13', '2', '46', '迦 勒 的 妾 以 法 生 哈 兰 、 摩 撒 、 迦 谢 ； 哈 兰 生 迦 卸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10354', '13', '2', '47', '〈 雅 代 的 儿 子 是 利 健 、 约 坦 、 基 珊 、 毗 力 、 以 法 、 沙 亚 弗 。 〉');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10355', '13', '2', '48', '迦 勒 的 妾 玛 迦 生 示 别 、 特 哈 拿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10356', '13', '2', '49', '又 生 麦 玛 拿 之 祖 沙 亚 弗 、 抹 比 拿 和 基 比 亚 之 祖 示 法 。 迦 勒 的 女 儿 是 押 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10357', '13', '2', '50', '迦 勒 的 子 孙 就 是 以 法 她 的 长 子 、 户 珥 的 儿 子 ， 记 在 下 面 ： 基 列 ． 耶 琳 之 祖 朔 巴 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10358', '13', '2', '51', '伯 利 恒 之 祖 萨 玛 ， 伯 迦 得 之 祖 哈 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10359', '13', '2', '52', '基 列 ． 耶 琳 之 祖 朔 巴 的 子 孙 是 哈 罗 以 和 一 半 米 努 ． 哈 人 ｛ 米 努 ． 哈 人 就 是 玛 拿 哈 人 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10360', '13', '2', '53', '基 列 ． 耶 琳 的 诸 族 是 以 帖 人 、 布 特 人 、 舒 玛 人 、 密 来 人 ， 又 从 这 些 族 中 生 出 琐 拉 人 和 以 实 陶 人 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10361', '13', '2', '54', '萨 玛 的 子 孙 是 伯 利 恒 人 、 尼 陀 法 人 、 亚 他 绿 ． 伯 ． 约 押 人 、 一 半 玛 拿 哈 人 、 琐 利 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10362', '13', '2', '55', '和 住 雅 比 斯 众 文 士 家 的 特 拉 人 、 示 米 押 人 、 苏 甲 人 。 这 都 是 基 尼 人 利 甲 家 之 祖 哈 末 所 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10363', '13', '3', '1', '＜ 大 卫 的 儿 女 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10364', '13', '3', '2', '三 子 押 沙 龙 是 基 述 王 达 买 的 女 儿 玛 迦 生 的 。 四 子 亚 多 尼 雅 是 哈 及 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10365', '13', '3', '3', '五 子 示 法 提 雅 是 亚 比 她 生 的 。 六 子 以 特 念 是 大 卫 的 妻 以 格 拉 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10366', '13', '3', '4', '这 六 人 都 是 大 卫 在 希 伯 仑 生 的 。 大 卫 在 希 伯 仑 作 王 七 年 零 六 个 月 ， 在 耶 路 撒 冷 作 王 三 十 三 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10367', '13', '3', '5', '大 卫 在 耶 路 撒 冷 所 生 的 儿 子 是 示 米 亚 、 朔 罢 、 拿 单 、 所 罗 门 。 这 四 人 是 亚 米 利 的 女 儿 拔 ． 书 亚 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10368', '13', '3', '6', '还 有 益 辖 、 以 利 沙 玛 、 以 利 法 列 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10369', '13', '3', '7', '挪 迦 、 尼 斐 、 雅 非 亚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10370', '13', '3', '8', '以 利 沙 玛 、 以 利 雅 大 、 以 利 法 列 ， 共 九 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10371', '13', '3', '9', '这 都 是 大 卫 的 儿 子 ， 还 有 他 们 的 妹 子 她 玛 ， 妃 嫔 的 儿 子 不 在 其 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10372', '13', '3', '10', '＜ 所 罗 门 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10373', '13', '3', '11', '约 沙 法 的 儿 子 是 约 兰 ； 约 兰 的 儿 子 是 亚 哈 谢 ； 亚 哈 谢 的 儿 子 是 约 阿 施 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10374', '13', '3', '12', '约 阿 施 的 儿 子 是 亚 玛 谢 ； 亚 玛 谢 的 儿 子 是 亚 撒 利 雅 ； 亚 撒 利 雅 的 儿 子 是 约 坦 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10375', '13', '3', '13', '约 坦 的 儿 子 是 亚 哈 斯 ； 亚 哈 斯 的 儿 子 是 希 西 家 ； 希 西 家 的 儿 子 是 玛 拿 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10376', '13', '3', '14', '玛 拿 西 的 儿 子 是 亚 们 ； 亚 们 的 儿 子 是 约 西 亚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10377', '13', '3', '15', '约 西 亚 的 长 子 是 约 哈 难 ， 次 子 是 约 雅 敬 ， 三 子 是 西 底 家 ， 四 子 是 沙 龙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10378', '13', '3', '16', '约 雅 敬 的 儿 子 是 耶 哥 尼 雅 和 西 底 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10379', '13', '3', '17', '＜ 耶 哥 尼 亚 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10380', '13', '3', '18', '玛 基 兰 、 毗 大 雅 、 示 拿 萨 、 耶 加 米 、 何 沙 玛 、 尼 大 比 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10381', '13', '3', '19', '毗 大 雅 的 儿 子 是 所 罗 巴 伯 、 示 每 。 所 罗 巴 伯 的 儿 子 是 米 书 兰 、 哈 拿 尼 雅 ， 他 们 的 妹 子 名 叫 示 罗 密 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10382', '13', '3', '20', '米 书 兰 的 儿 子 是 哈 舒 巴 、 阿 黑 、 比 利 家 、 哈 撒 底 、 于 沙 ． 希 悉 ， 共 五 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10383', '13', '3', '21', '哈 拿 尼 雅 的 儿 子 是 毗 拉 提 、 耶 筛 亚 。 还 有 利 法 雅 的 众 子 ， 亚 珥 难 的 众 子 ， 俄 巴 底 亚 的 众 子 ， 示 迦 尼 的 众 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10384', '13', '3', '22', '示 迦 尼 的 儿 子 是 示 玛 雅 ； 示 玛 雅 的 儿 子 是 哈 突 、 以 甲 、 巴 利 亚 、 尼 利 雅 、 沙 法 ， 共 六 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10385', '13', '3', '23', '尼 利 雅 的 儿 子 是 以 利 约 乃 、 希 西 家 、 亚 斯 利 干 ， 共 三 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10386', '13', '3', '24', '以 利 约 乃 的 儿 子 是 何 大 雅 、 以 利 亚 实 、 毗 莱 雅 、 阿 谷 、 约 哈 难 、 第 莱 雅 、 阿 拿 尼 ， 共 七 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10387', '13', '4', '1', '＜ 复 记 犹 大 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10388', '13', '4', '2', '朔 巴 的 儿 子 利 亚 雅 生 雅 哈 ； 雅 哈 生 亚 户 买 和 拉 哈 。 这 是 琐 拉 人 的 诸 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10389', '13', '4', '3', '以 坦 之 祖 的 儿 子 是 耶 斯 列 、 伊 施 玛 、 伊 得 巴 ； 他 们 的 妹 子 名 叫 哈 悉 勒 玻 尼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10390', '13', '4', '4', '基 多 之 祖 是 毗 努 伊 勒 。 户 沙 之 祖 是 以 谢 珥 。 这 都 是 伯 利 恒 之 祖 以 法 她 的 长 子 户 珥 所 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10391', '13', '4', '5', '提 哥 亚 之 祖 亚 施 户 有 两 个 妻 子 ： 一 名 希 拉 ， 一 名 拿 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10392', '13', '4', '6', '拿 拉 给 亚 施 户 生 亚 户 撒 、 希 弗 、 提 米 尼 、 哈 辖 斯 他 利 。 这 都 是 拿 拉 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10393', '13', '4', '7', '希 拉 的 儿 子 是 洗 列 、 琐 辖 、 伊 提 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10394', '13', '4', '8', '哥 斯 生 亚 诺 、 琐 比 巴 ， 并 哈 仑 儿 子 亚 哈 黑 的 诸 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10395', '13', '4', '9', '雅 比 斯 比 他 众 弟 兄 更 尊 贵 ， 他 母 亲 给 他 起 名 叫 雅 比 斯 ， 意 思 说 ： 我 生 他 甚 是 痛 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10396', '13', '4', '10', '雅 比 斯 求 告 以 色 列 的 神 说 ： “ 甚 愿 你 赐 福 与 我 ， 扩 张 我 的 境 界 ， 常 与 我 同 在 ， 保 佑 我 不 遭 患 难 ， 不 受 艰 苦 。 ” 神 就 应 允 他 所 求 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10397', '13', '4', '11', '＜ 其 他 的 家 族 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10398', '13', '4', '12', '伊 施 屯 生 伯 拉 巴 、 巴 西 亚 ， 并 珥 拿 辖 之 祖 提 欣 拿 ， 这 都 是 利 迦 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10399', '13', '4', '13', '基 纳 斯 的 儿 子 是 俄 陀 聂 、 西 莱 雅 。 俄 陀 聂 的 儿 子 是 哈 塔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10400', '13', '4', '14', '悯 挪 太 生 俄 弗 拉 ； 西 莱 雅 生 革 ． 夏 纳 欣 人 之 祖 约 押 。 他 们 都 是 匠 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10401', '13', '4', '15', '耶 孚 尼 的 儿 子 是 迦 勒 ； 迦 勒 的 儿 子 是 以 路 、 以 拉 、 拿 安 。 以 拉 的 儿 子 是 基 纳 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10402', '13', '4', '16', '耶 哈 利 勒 的 儿 子 是 西 弗 、 西 法 、 提 利 、 亚 撒 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10403', '13', '4', '17', '以 斯 拉 的 儿 子 是 益 帖 、 米 列 、 以 弗 、 雅 伦 。 米 列 娶 法 老 女 儿 比 提 雅 为 妻 ， 生 米 利 暗 、 沙 买 ， 和 以 实 提 摩 之 祖 益 巴 。 米 列 又 娶 犹 大 女 子 为 妻 ， 生 基 多 之 祖 雅 列 ， 梭 哥 之 祖 希 伯 ， 和 撒 挪 亚 之 祖 耶 古 铁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10404', '13', '4', '18', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10405', '13', '4', '19', '荷 第 雅 的 妻 是 拿 含 的 妹 子 ， 她 所 生 的 儿 子 是 迦 米 人 基 伊 拉 和 玛 迦 人 以 实 提 摩 之 祖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10406', '13', '4', '20', '示 门 的 儿 子 是 暗 嫩 、 林 拿 、 便 ． 哈 南 、 提 伦 。 以 示 的 儿 子 是 梭 黑 与 便 ． 梭 黑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10407', '13', '4', '21', '＜ 示 拉 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10408', '13', '4', '22', '还 有 约 敬 、 哥 西 巴 人 、 约 阿 施 、 萨 拉 ， 就 是 在 摩 押 地 掌 权 的 ， 又 有 雅 叔 比 利 恒 。 这 都 是 古 时 所 记 载 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10409', '13', '4', '23', '这 些 人 都 是 窑 匠 ， 是 尼 他 应 和 基 低 拉 的 居 民 ； 与 王 同 处 ， 为 王 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10410', '13', '4', '24', '＜ 西 缅 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10411', '13', '4', '25', '扫 罗 的 儿 子 是 沙 龙 ； 沙 龙 的 儿 子 是 米 比 衫 ； 米 比 衫 的 儿 子 是 米 施 玛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10412', '13', '4', '26', '米 施 玛 的 儿 子 是 哈 母 利 ； 哈 母 利 的 儿 子 是 撒 刻 ； 撒 刻 的 儿 子 是 示 每 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10413', '13', '4', '27', '示 每 有 十 六 个 儿 子 ， 六 个 女 儿 ， 他 弟 兄 的 儿 女 不 多 ， 他 们 各 家 不 如 犹 大 族 的 人 丁 增 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10414', '13', '4', '28', '西 缅 人 住 在 别 是 巴 、 摩 拉 大 、 哈 萨 ． 书 亚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10415', '13', '4', '29', '辟 拉 、 以 森 、 陀 腊 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10416', '13', '4', '30', '彼 土 利 、 何 珥 玛 、 洗 革 拉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10417', '13', '4', '31', '伯 ． 玛 嘉 博 、 哈 萨 ． 苏 撒 、 伯 ． 比 利 、 沙 拉 音 ， 这 些 城 邑 直 到 大 卫 作 王 的 时 候 都 是 属 西 缅 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10418', '13', '4', '32', '他 们 的 五 个 城 邑 是 以 坦 、 亚 因 、 临 门 、 陀 健 、 亚 珊 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10419', '13', '4', '33', '还 有 属 城 的 乡 村 ， 直 到 巴 力 。 这 是 他 们 的 住 处 ， 他 们 都 有 家 谱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10420', '13', '4', '34', '还 有 米 所 巴 、 雅 米 勒 、 亚 玛 谢 的 儿 子 约 沙 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10421', '13', '4', '35', '约 珥 、 约 示 比 的 儿 子 耶 户 ； 约 示 比 是 西 莱 雅 的 儿 子 ； 西 莱 雅 是 亚 薛 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10422', '13', '4', '36', '还 有 以 利 约 乃 、 雅 哥 巴 、 约 朔 海 、 亚 帅 雅 、 亚 底 业 、 耶 西 篾 、 比 拿 雅 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10423', '13', '4', '37', '示 非 的 儿 子 细 撒 。 示 非 是 亚 龙 的 儿 子 ； 亚 龙 是 耶 大 雅 的 儿 子 ； 耶 大 雅 是 申 利 的 儿 子 ； 申 利 是 示 玛 雅 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10424', '13', '4', '38', '以 上 所 记 的 人 名 都 是 作 族 长 的 ， 他 们 宗 族 的 人 数 增 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10425', '13', '4', '39', '他 们 往 平 原 东 边 基 多 口 去 ， 寻 找 牧 放 羊 群 的 草 场 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10426', '13', '4', '40', '寻 得 肥 美 的 草 场 地 ， 又 宽 阔 又 平 静 。 从 前 住 那 里 的 是 含 族 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10427', '13', '4', '41', '以 上 录 名 的 人 ， 在 犹 大 王 希 西 家 年 间 ， 来 攻 击 含 族 人 的 帐 棚 和 那 里 所 有 的 米 乌 尼 人 ， 将 他 们 灭 尽 ， 就 住 在 他 们 的 地 方 ， 直 到 今 日 ， 因 为 那 里 有 草 场 可 以 牧 放 羊 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10428', '13', '4', '42', '这 西 缅 人 中 ， 有 五 百 人 上 西 珥 山 ， 率 领 他 们 的 是 以 示 的 儿 子 毗 拉 提 、 尼 利 雅 、 利 法 雅 ， 和 乌 薛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10429', '13', '4', '43', '杀 了 逃 脱 剩 下 的 亚 玛 力 人 ， 就 住 在 那 里 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10430', '13', '5', '1', '＜ 吕 便 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10431', '13', '5', '2', '犹 大 胜 过 一 切 弟 兄 ， 君 王 也 是 从 他 而 出 ； 长 子 的 名 分 却 归 约 瑟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10432', '13', '5', '3', '以 色 列 长 子 吕 便 的 儿 子 是 哈 诺 、 法 路 、 希 斯 伦 、 迦 米 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10433', '13', '5', '4', '约 珥 的 儿 子 是 示 玛 雅 ； 示 玛 雅 的 儿 子 是 歌 革 ； 歌 革 的 儿 子 是 示 每 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10434', '13', '5', '5', '示 每 的 儿 子 是 米 迦 ； 米 迦 的 儿 子 是 利 ． 亚 雅 ； 利 ． 亚 雅 的 儿 子 是 巴 力 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10435', '13', '5', '6', '巴 力 的 儿 子 是 备 ． 拉 。 这 备 ． 拉 作 吕 便 支 派 的 首 领 ， 被 亚 述 王 提 革 拉 ． 毗 列 色 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10436', '13', '5', '7', '他 的 弟 兄 照 着 宗 族 ， 按 着 家 谱 作 族 长 的 是 耶 利 、 撒 迦 利 雅 、 比 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10437', '13', '5', '8', '比 拉 是 亚 撒 的 儿 子 ； 亚 撒 是 示 玛 的 儿 子 ； 示 玛 是 约 珥 的 儿 子 ； 约 珥 所 住 的 地 方 是 从 亚 罗 珥 直 到 尼 波 和 巴 力 ． 免 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10438', '13', '5', '9', '又 向 东 延 到 幼 发 拉 底 河 这 边 的 旷 野 ， 因 为 他 们 在 基 列 地 牲 畜 增 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10439', '13', '5', '10', '扫 罗 年 间 ， 他 们 与 夏 甲 人 争 战 ， 夏 甲 人 倒 在 他 们 手 下 ， 他 们 就 在 基 列 东 边 的 全 地 ， 住 在 夏 甲 人 的 帐 棚 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10440', '13', '5', '11', '＜ 迦 得 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10441', '13', '5', '12', '他 们 中 间 有 作 族 长 的 约 珥 ， 有 作 副 族 长 的 沙 番 ， 还 有 雅 乃 和 住 在 巴 珊 的 沙 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10442', '13', '5', '13', '他 们 族 弟 兄 是 米 迦 勒 、 米 书 兰 、 示 巴 、 约 赖 、 雅 干 、 细 亚 、 希 伯 ， 共 七 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10443', '13', '5', '14', '这 都 是 亚 比 孩 的 儿 子 。 亚 比 孩 是 户 利 的 儿 子 ； 户 利 是 耶 罗 亚 的 儿 子 ； 耶 罗 亚 是 基 列 的 儿 子 ； 基 列 是 米 迦 勒 的 儿 子 ； 米 迦 勒 是 耶 示 筛 的 儿 子 ； 耶 示 筛 是 耶 哈 多 的 儿 子 ； 耶 哈 多 是 布 斯 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10444', '13', '5', '15', '还 有 古 尼 的 孙 子 、 押 比 叠 的 儿 子 亚 希 。 这 都 是 作 族 长 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10445', '13', '5', '16', '他 们 住 在 基 列 与 巴 珊 和 巴 珊 的 乡 村 ， 并 沙 仑 的 郊 野 ， 直 到 四 围 的 交 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10446', '13', '5', '17', '这 些 人 在 犹 大 王 约 坦 并 在 以 色 列 王 耶 罗 波 安 年 间 ， 都 载 入 家 谱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10447', '13', '5', '18', '＜ 吕 便 迦 得 玛 拿 西 族 的 军 队 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10448', '13', '5', '19', '他 们 与 夏 甲 人 、 伊 突 人 、 拿 非 施 人 、 挪 答 人 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10449', '13', '5', '20', '他 们 得 了 神 的 帮 助 ， 夏 甲 人 和 跟 随 夏 甲 的 人 都 交 在 他 们 手 中 ； 因 为 他 们 在 阵 上 呼 求 神 ， 倚 赖 神 ， 神 就 应 允 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10450', '13', '5', '21', '他 们 掳 掠 了 夏 甲 人 的 牲 畜 ， 有 骆 驼 五 万 ， 羊 二 十 五 万 ， 驴 二 千 ； 又 有 人 十 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10451', '13', '5', '22', '敌 人 被 杀 仆 倒 的 甚 多 ， 因 为 这 争 战 是 出 乎 神 。 他 们 就 住 在 敌 人 的 地 上 ， 直 到 被 掳 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10452', '13', '5', '23', '＜ 玛 拿 西 半 支 派 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10453', '13', '5', '24', '他 们 的 族 长 是 以 弗 、 以 示 、 以 列 、 亚 斯 列 、 耶 利 米 、 何 达 威 雅 、 雅 叠 ， 都 是 大 能 的 勇 士 ， 是 有 名 的 人 ， 也 是 作 族 长 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10454', '13', '5', '25', '＜ 二 支 派 半 人 叛 逆 神 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10455', '13', '5', '26', '故 此 ， 以 色 列 的 神 激 动 亚 述 王 普 勒 和 亚 述 王 提 革 拉 ． 毗 列 色 的 心 ， 他 们 就 把 吕 便 人 、 迦 得 人 、 玛 拿 西 半 支 派 的 人 掳 到 哈 腊 、 哈 博 、 哈 拉 与 歌 散 河 边 ， 直 到 今 日 还 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10456', '13', '6', '1', '＜ 利 未 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10457', '13', '6', '2', '哥 辖 的 儿 子 是 暗 兰 、 以 斯 哈 、 希 伯 伦 、 乌 薛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10458', '13', '6', '3', '暗 兰 的 儿 子 是 亚 伦 、 摩 西 ， 还 有 女 儿 米 利 暗 。 亚 伦 的 儿 子 是 拿 答 、 亚 比 户 、 以 利 亚 撒 、 以 他 玛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10459', '13', '6', '4', '以 利 亚 撒 生 非 尼 哈 ； 非 尼 哈 生 亚 比 书 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10460', '13', '6', '5', '亚 比 书 生 布 基 ； 布 基 生 乌 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10461', '13', '6', '6', '乌 西 生 西 拉 希 雅 ； 西 拉 希 雅 生 米 拉 约 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10462', '13', '6', '7', '米 拉 约 生 亚 玛 利 雅 ； 亚 玛 利 雅 生 亚 希 突 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10463', '13', '6', '8', '亚 希 突 生 撒 督 ； 撒 督 生 亚 希 玛 斯 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10464', '13', '6', '9', '亚 希 玛 斯 生 亚 撒 利 雅 ； 亚 撒 利 雅 生 约 哈 难 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10465', '13', '6', '10', '约 哈 难 生 亚 撒 利 雅 （ 这 亚 撒 利 雅 在 所 罗 门 于 耶 路 撒 冷 所 建 造 的 殿 中 ， 供 祭 司 的 职 分 ） ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10466', '13', '6', '11', '亚 撒 利 雅 生 亚 玛 利 雅 ； 亚 玛 利 雅 生 亚 希 突 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10467', '13', '6', '12', '亚 希 突 生 撒 督 ； 撒 督 生 沙 龙 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10468', '13', '6', '13', '沙 龙 生 希 勒 家 ； 希 勒 家 生 亚 撒 利 雅 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10469', '13', '6', '14', '亚 撒 利 雅 生 西 莱 雅 ； 西 莱 雅 生 约 萨 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10470', '13', '6', '15', '当 耶 和 华 藉 尼 布 甲 尼 撒 的 手 掳 掠 犹 大 和 耶 路 撒 冷 人 的 时 候 ， 这 约 萨 答 也 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10471', '13', '6', '16', '＜ 利 未 的 其 余 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10472', '13', '6', '17', '革 顺 的 儿 子 名 叫 立 尼 、 示 每 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10473', '13', '6', '18', '哥 辖 的 儿 子 是 暗 兰 、 以 斯 哈 、 希 伯 伦 、 乌 薛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10474', '13', '6', '19', '米 拉 利 的 儿 子 是 抹 利 、 母 示 。 这 是 按 着 利 未 人 宗 族 分 的 各 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10475', '13', '6', '20', '革 顺 的 儿 子 是 立 尼 ； 立 尼 的 儿 子 是 雅 哈 ； 雅 哈 的 儿 子 是 薪 玛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10476', '13', '6', '21', '薪 玛 的 儿 子 是 约 亚 ； 约 亚 的 儿 子 是 易 多 ； 易 多 的 儿 子 是 谢 拉 ； 谢 拉 的 儿 子 是 耶 特 赖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10477', '13', '6', '22', '哥 辖 的 儿 子 是 亚 米 拿 达 ； 亚 米 拿 达 的 儿 子 是 可 拉 ； 可 拉 的 儿 子 是 亚 惜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10478', '13', '6', '23', '亚 惜 的 儿 子 是 以 利 加 拿 ； 以 利 加 拿 的 儿 子 是 以 比 雅 撒 ； 以 比 雅 撒 的 儿 子 是 亚 惜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10479', '13', '6', '24', '亚 惜 的 儿 子 是 他 哈 ； 他 哈 的 儿 子 是 乌 列 ； 乌 列 的 儿 子 是 乌 西 雅 ； 乌 西 雅 的 儿 子 是 少 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10480', '13', '6', '25', '以 利 加 拿 的 儿 子 是 亚 玛 赛 和 亚 希 摩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10481', '13', '6', '26', '亚 希 摩 的 儿 子 是 以 利 加 拿 ； 以 利 加 拿 的 儿 子 是 琐 菲 ； 琐 菲 的 儿 子 是 拿 哈 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10482', '13', '6', '27', '拿 哈 的 儿 子 是 以 利 押 ； 以 利 押 的 儿 子 是 耶 罗 罕 ； 耶 罗 罕 的 儿 子 是 以 利 加 拿 ； 以 利 加 拿 的 儿 子 是 撒 母 耳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10483', '13', '6', '28', '撒 母 耳 的 长 子 是 约 珥 ， 次 子 是 亚 比 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10484', '13', '6', '29', '米 拉 利 的 儿 子 是 抹 利 ； 抹 利 的 儿 子 是 立 尼 ； 立 尼 的 儿 子 是 示 每 ； 示 每 的 儿 子 是 乌 撒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10485', '13', '6', '30', '乌 撒 的 儿 子 是 示 米 亚 ； 示 米 亚 的 儿 子 是 哈 基 雅 ； 哈 基 雅 的 儿 子 是 亚 帅 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10486', '13', '6', '31', '＜ 圣 殿 中 的 歌 者 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10487', '13', '6', '32', '他 们 就 在 会 幕 前 当 歌 唱 的 差 ， 及 至 所 罗 门 在 耶 路 撒 冷 建 造 了 耶 和 华 的 殿 ， 他 们 便 按 着 班 次 供 职 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10488', '13', '6', '33', '供 职 的 人 和 他 们 的 子 孙 记 在 下 面 ： 哥 辖 的 子 孙 中 有 歌 唱 的 希 幔 。 希 幔 是 约 珥 的 儿 子 ； 约 珥 是 撒 母 耳 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10489', '13', '6', '34', '撒 母 耳 是 以 利 加 拿 的 儿 子 ； 以 利 加 拿 是 耶 罗 罕 的 儿 子 ； 耶 罗 罕 是 以 列 的 儿 子 ； 以 列 是 陀 亚 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10490', '13', '6', '35', '陀 亚 是 苏 弗 的 儿 子 ； 苏 弗 是 以 利 加 拿 的 儿 子 ； 以 利 加 拿 是 玛 哈 的 儿 子 ； 玛 哈 是 亚 玛 赛 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10491', '13', '6', '36', '亚 玛 赛 是 以 利 加 拿 的 儿 子 ； 以 利 加 拿 是 约 珥 的 儿 子 ； 约 珥 是 亚 撒 利 雅 的 儿 子 ； 亚 撒 利 雅 是 西 番 雅 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10492', '13', '6', '37', '西 番 雅 是 他 哈 的 儿 子 ； 他 哈 是 亚 惜 的 儿 子 ； 亚 惜 是 以 比 雅 撒 的 儿 子 ； 以 比 雅 撒 是 可 拉 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10493', '13', '6', '38', '可 拉 是 以 斯 哈 的 儿 子 ； 以 斯 哈 是 哥 辖 的 儿 子 ； 哥 辖 是 利 未 的 儿 子 ； 利 未 是 以 色 列 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10494', '13', '6', '39', '希 幔 的 族 兄 亚 萨 是 比 利 家 的 儿 子 ， 亚 萨 在 希 幔 右 边 供 职 。 比 利 家 是 示 米 亚 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10495', '13', '6', '40', '示 米 亚 是 米 迦 勒 的 儿 子 ； 米 迦 勒 是 巴 西 雅 的 儿 子 ； 巴 西 雅 是 玛 基 雅 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10496', '13', '6', '41', '玛 基 雅 是 伊 特 尼 的 儿 子 ； 伊 特 尼 是 谢 拉 的 儿 子 ； 谢 拉 是 亚 大 雅 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10497', '13', '6', '42', '亚 大 雅 是 以 探 的 儿 子 ； 以 探 是 薪 玛 的 儿 子 ； 薪 玛 是 示 每 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10498', '13', '6', '43', '示 每 是 雅 哈 的 儿 子 ； 雅 哈 是 革 顺 的 儿 子 。 革 顺 是 利 未 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10499', '13', '6', '44', '他 们 的 族 弟 兄 米 拉 利 的 子 孙 ， 在 他 们 左 边 供 职 的 有 以 探 。 以 探 是 基 示 的 儿 子 ； 基 示 是 亚 伯 底 的 儿 子 ； 亚 伯 底 是 玛 鹿 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10500', '13', '6', '45', '玛 鹿 是 哈 沙 比 雅 的 儿 子 ； 哈 沙 比 雅 是 亚 玛 谢 的 儿 子 ； 亚 玛 谢 是 希 勒 家 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10501', '13', '6', '46', '希 勒 家 是 暗 西 的 儿 子 ； 暗 西 是 巴 尼 的 儿 子 ； 巴 尼 是 沙 麦 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10502', '13', '6', '47', '沙 麦 是 末 力 的 儿 子 ； 末 力 是 母 示 的 儿 子 ； 母 示 是 米 拉 利 的 儿 子 ； 米 拉 利 是 利 未 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10503', '13', '6', '48', '他 们 的 族 弟 兄 利 未 人 也 被 派 办 神 殿 中 的 一 切 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10504', '13', '6', '49', '＜ 亚 伦 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10505', '13', '6', '50', '亚 伦 的 儿 子 是 以 利 亚 撒 ； 以 利 亚 撒 的 儿 子 是 非 尼 哈 ； 非 尼 哈 的 儿 子 是 亚 比 书 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10506', '13', '6', '51', '亚 比 书 的 儿 子 是 布 基 ； 布 基 的 儿 子 是 乌 西 ； 乌 西 的 儿 子 是 西 拉 希 雅 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10507', '13', '6', '52', '西 拉 希 雅 的 儿 子 是 米 拉 约 ； 米 拉 约 的 儿 子 是 亚 玛 利 雅 ； 亚 玛 利 雅 的 儿 子 是 亚 希 突 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10508', '13', '6', '53', '亚 希 突 的 儿 子 是 撒 督 ； 撒 督 的 儿 子 是 亚 希 玛 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10509', '13', '6', '54', '＜ 利 未 支 派 的 居 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10510', '13', '6', '55', '在 犹 大 地 中 得 了 希 伯 仑 和 四 围 的 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10511', '13', '6', '56', '只 是 属 城 的 田 地 和 村 庄 都 为 耶 孚 尼 的 儿 子 迦 勒 所 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10512', '13', '6', '57', '亚 伦 的 子 孙 得 了 逃 城 希 伯 仑 ， 又 得 了 立 拿 与 其 郊 野 ， 雅 提 珥 、 以 实 提 莫 与 其 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10513', '13', '6', '58', '希 仑 与 其 郊 野 ， 底 璧 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10514', '13', '6', '59', '亚 珊 与 其 郊 野 ， 伯 ． 示 麦 与 其 郊 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10515', '13', '6', '60', '在 便 雅 悯 支 派 的 地 中 ， 得 了 迦 巴 与 其 郊 野 ， 阿 勒 篾 与 其 郊 野 ， 亚 拿 突 与 其 郊 野 。 他 们 诸 家 所 得 的 城 共 十 三 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10516', '13', '6', '61', '哥 辖 族 其 余 的 人 又 拈 阄 ， 在 玛 拿 西 半 支 派 的 地 中 得 了 十 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10517', '13', '6', '62', '革 顺 族 按 着 宗 族 ， 在 以 萨 迦 支 派 的 地 中 ， 亚 设 支 派 的 地 中 ， 拿 弗 他 利 支 派 的 地 中 ， 巴 珊 内 玛 拿 西 支 派 的 地 中 ， 得 了 十 三 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10518', '13', '6', '63', '米 拉 利 族 按 着 宗 族 拈 阄 ， 在 吕 便 支 派 的 地 中 ， 迦 得 支 派 的 地 中 ， 西 布 伦 支 派 的 地 中 ， 得 了 十 二 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10519', '13', '6', '64', '以 色 列 人 将 这 些 城 与 其 郊 野 给 了 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10520', '13', '6', '65', '这 以 上 录 名 的 城 ， 在 犹 大 、 西 缅 、 便 雅 悯 三 支 派 的 地 中 ， 以 色 列 人 拈 阄 给 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10521', '13', '6', '66', '哥 辖 族 中 有 几 家 在 以 法 莲 支 派 的 地 中 也 得 了 城 邑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10522', '13', '6', '67', '在 以 法 莲 山 地 得 了 逃 城 示 剑 与 其 郊 野 ， 又 得 了 基 色 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10523', '13', '6', '68', '约 缅 与 其 郊 野 ， 伯 ． 和 仑 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10524', '13', '6', '69', '亚 雅 仑 与 其 郊 野 ， 迦 特 ． 临 门 与 其 郊 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10525', '13', '6', '70', '哥 辖 族 其 余 的 人 在 玛 拿 西 半 支 派 的 地 中 得 了 亚 乃 与 其 郊 野 ， 比 连 与 其 郊 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10526', '13', '6', '71', '革 顺 族 在 玛 拿 西 半 支 派 的 地 中 得 了 巴 珊 的 哥 兰 与 其 郊 野 ， 亚 斯 他 录 与 其 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10527', '13', '6', '72', '又 在 以 萨 迦 支 派 的 地 中 得 了 基 低 斯 与 其 郊 野 ， 大 比 拉 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10528', '13', '6', '73', '拉 末 与 其 郊 野 ， 亚 年 与 其 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10529', '13', '6', '74', '在 亚 设 支 派 的 地 中 得 了 玛 沙 与 其 郊 野 ， 押 顿 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10530', '13', '6', '75', '户 割 与 其 郊 野 ， 利 合 与 其 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10531', '13', '6', '76', '在 拿 弗 他 利 支 派 的 地 中 得 了 加 利 利 的 基 低 斯 与 其 郊 野 ， 哈 们 与 其 郊 野 ， 基 列 亭 与 其 郊 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10532', '13', '6', '77', '还 有 米 拉 利 族 的 人 在 西 布 伦 支 派 的 地 中 得 了 临 摩 挪 与 其 郊 野 ， 他 泊 与 其 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10533', '13', '6', '78', '又 在 耶 利 哥 的 约 旦 河 东 ， 在 吕 便 支 派 的 地 中 得 了 旷 野 的 比 悉 与 其 郊 野 ， 雅 哈 撒 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10534', '13', '6', '79', '基 底 莫 与 其 郊 野 ， 米 法 押 与 其 郊 野 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10535', '13', '6', '80', '又 在 迦 得 支 派 的 地 中 得 了 基 列 的 拉 末 与 其 郊 野 ， 玛 哈 念 与 其 郊 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10536', '13', '6', '81', '希 实 本 与 其 郊 野 ， 雅 谢 与 其 郊 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10537', '13', '7', '1', '＜ 以 萨 迦 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10538', '13', '7', '2', '陀 拉 的 儿 子 是 乌 西 、 利 法 雅 、 耶 勒 、 雅 买 、 易 伯 散 、 示 母 利 ， 都 是 陀 拉 的 族 长 ， 是 大 能 的 勇 士 。 到 大 卫 年 间 ， 他 们 的 人 数 共 有 二 万 二 千 六 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10539', '13', '7', '3', '乌 西 的 儿 子 是 伊 斯 拉 希 ； 伊 斯 拉 希 的 儿 子 是 米 迦 勒 、 俄 巴 底 亚 、 约 珥 、 伊 示 雅 ， 共 五 人 ， 都 是 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10540', '13', '7', '4', '他 们 所 率 领 的 ， 按 着 宗 族 出 战 的 军 队 ， 共 有 三 万 六 千 人 ， 因 为 他 们 的 妻 和 子 众 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10541', '13', '7', '5', '他 们 的 族 弟 兄 在 以 萨 迦 各 族 中 都 是 大 能 的 勇 士 ， 按 着 家 谱 计 算 共 有 八 万 七 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10542', '13', '7', '6', '＜ 便 雅 悯 和 但 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10543', '13', '7', '7', '比 拉 的 儿 子 是 以 斯 本 、 乌 西 、 乌 薛 、 耶 利 摩 、 以 利 ， 共 五 人 ， 都 是 族 长 ， 是 大 能 的 勇 士 。 按 着 家 谱 计 算 ， 他 们 的 子 孙 共 有 二 万 二 千 零 三 十 四 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10544', '13', '7', '8', '比 结 的 儿 子 是 细 米 拉 、 约 阿 施 、 以 利 以 谢 、 以 利 约 乃 、 暗 利 、 耶 利 摩 、 亚 比 雅 、 亚 拿 突 、 亚 拉 篾 。 这 都 是 比 结 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10545', '13', '7', '9', '他 们 都 是 族 长 ， 是 大 能 的 勇 士 。 按 着 家 谱 计 算 ， 他 们 的 子 孙 共 有 二 万 零 二 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10546', '13', '7', '10', '耶 叠 的 儿 子 是 比 勒 罕 ； 比 勒 罕 的 儿 子 是 耶 乌 施 、 便 雅 悯 、 以 忽 、 基 拿 拿 、 细 坦 、 他 施 、 亚 希 沙 哈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10547', '13', '7', '11', '这 都 是 耶 叠 的 儿 子 ， 都 是 族 长 ， 是 大 能 的 勇 士 ； 他 们 的 子 孙 能 上 阵 打 仗 的 ， 共 有 一 万 七 千 二 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10548', '13', '7', '12', '还 有 以 珥 的 儿 子 书 品 、 户 品 ， 并 亚 黑 的 儿 子 户 伸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10549', '13', '7', '13', '＜ 拿 弗 他 利 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10550', '13', '7', '14', '＜ 玛 拿 西 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10551', '13', '7', '15', '玛 吉 娶 的 妻 是 户 品 、 书 品 的 妹 子 ， 名 叫 玛 迦 。 玛 拿 西 的 次 子 名 叫 西 罗 非 哈 ； 西 罗 非 哈 但 有 几 个 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10552', '13', '7', '16', '玛 吉 的 妻 玛 迦 生 了 一 个 儿 子 ， 起 名 叫 毗 利 施 。 毗 利 施 的 兄 弟 名 叫 示 利 施 ； 示 利 施 的 儿 子 是 乌 兰 和 利 金 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10553', '13', '7', '17', '乌 兰 的 儿 子 是 比 但 。 这 都 是 基 列 的 子 孙 。 基 列 是 玛 吉 的 儿 子 ， 玛 吉 是 玛 拿 西 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10554', '13', '7', '18', '基 列 的 妹 子 哈 摩 利 吉 生 了 伊 施 荷 、 亚 比 以 谢 、 玛 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10555', '13', '7', '19', '〈 示 米 大 的 儿 子 是 亚 现 、 示 剑 、 利 克 希 、 阿 尼 安 。 〉');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10556', '13', '7', '20', '＜ 以 法 莲 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10557', '13', '7', '21', '他 哈 的 儿 子 是 撒 拔 ； 撒 拔 的 儿 子 是 书 提 拉 。 以 法 莲 又 生 以 谢 、 以 列 ； 这 二 人 因 为 下 去 夺 取 迦 特 人 的 牲 畜 ， 被 本 地 的 迦 特 人 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10558', '13', '7', '22', '他 们 的 父 亲 以 法 莲 为 他 们 悲 哀 了 多 日 ， 他 的 弟 兄 都 来 安 慰 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10559', '13', '7', '23', '以 法 莲 与 妻 同 房 ， 他 妻 就 怀 孕 生 了 一 子 ， 以 法 莲 因 为 家 里 遭 祸 ， 就 给 这 儿 子 起 名 叫 比 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10560', '13', '7', '24', '他 的 女 儿 名 叫 舍 伊 拉 ， 就 是 建 筑 上 伯 ． 和 仑 、 下 伯 ． 和 仑 与 乌 羡 ． 舍 伊 拉 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10561', '13', '7', '25', '比 利 亚 的 儿 子 是 利 法 和 利 悉 。 利 悉 的 儿 子 是 他 拉 ； 他 拉 的 儿 子 是 他 罕 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10562', '13', '7', '26', '他 罕 的 儿 子 是 拉 但 ； 拉 但 的 儿 子 是 亚 米 忽 ； 亚 米 忽 的 儿 子 是 以 利 沙 玛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10563', '13', '7', '27', '以 利 沙 玛 的 儿 子 是 嫩 ； 嫩 的 儿 子 是 约 书 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10564', '13', '7', '28', '以 法 莲 人 的 地 业 和 住 处 是 伯 特 利 与 其 村 庄 ； 东 边 拿 兰 ， 西 边 基 色 与 其 村 庄 ； 示 剑 与 其 村 庄 ， 直 到 迦 萨 与 其 村 庄 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10565', '13', '7', '29', '还 有 靠 近 玛 拿 西 人 的 境 界 ， 伯 ． 善 与 其 村 庄 ； 他 纳 与 其 村 庄 ； 米 吉 多 与 其 村 庄 ； 多 珥 与 其 村 庄 。 以 色 列 儿 子 约 瑟 的 子 孙 住 在 这 些 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10566', '13', '7', '30', '＜ 亚 设 的 后 裔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10567', '13', '7', '31', '比 利 亚 的 儿 子 是 希 别 、 玛 结 ； 玛 结 是 比 撒 威 的 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10568', '13', '7', '32', '希 别 生 雅 弗 勒 、 朔 默 、 何 坦 ， 和 他 们 的 妹 子 书 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10569', '13', '7', '33', '雅 弗 勒 的 儿 子 是 巴 萨 、 宾 哈 、 亚 施 法 。 这 都 是 雅 弗 勒 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10570', '13', '7', '34', '朔 默 的 儿 子 是 亚 希 、 罗 迦 、 耶 户 巴 、 亚 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10571', '13', '7', '35', '朔 默 兄 弟 希 连 的 儿 子 是 琐 法 、 音 那 、 示 利 斯 、 亚 抹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10572', '13', '7', '36', '琐 法 的 儿 子 是 书 亚 、 哈 尼 弗 、 书 阿 勒 、 比 利 、 音 拉 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10573', '13', '7', '37', '比 悉 、 河 得 、 珊 玛 、 施 沙 、 益 兰 、 比 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10574', '13', '7', '38', '益 帖 的 儿 子 是 耶 孚 尼 、 毗 斯 巴 、 亚 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10575', '13', '7', '39', '乌 拉 的 儿 子 是 亚 拉 、 汉 尼 业 、 利 写 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10576', '13', '7', '40', '这 都 是 亚 设 的 子 孙 ， 都 是 族 长 ， 是 精 壮 大 能 的 勇 士 ， 也 是 首 领 中 的 头 目 ， 按 着 家 谱 计 算 ， 他 们 的 子 孙 能 出 战 的 共 有 二 万 六 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10577', '13', '8', '1', '＜ 便 雅 悯 的 后 裔 ＞ 
