INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10601', '13', '8', '25', '伊 弗 底 雅 、 毗 努 伊 勒 都 是 沙 煞 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10602', '13', '8', '26', '珊 示 莱 、 示 哈 利 、 亚 他 利 雅 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10603', '13', '8', '27', '雅 利 西 、 以 利 亚 、 细 基 利 都 是 耶 罗 罕 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10604', '13', '8', '28', '这 些 人 都 是 著 名 的 族 长 ， 住 在 耶 路 撒 冷 。');
