INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10608', '13', '8', '32', '米 基 罗 生 示 米 暗 。 这 些 人 和 他 们 的 弟 兄 在 耶 路 撒 冷 对 面 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10609', '13', '8', '33', '＜ 扫 罗 王 的 家 族 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10610', '13', '8', '34', '约 拿 单 的 儿 子 是 米 力 ． 巴 力 ｛ 在 撒 母 耳 下 四 章 四 节 是 米 非 波 设 ｝ ； 米 力 ． 巴 力 生 米 迦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10611', '13', '8', '35', '米 迦 的 儿 子 是 毗 敦 、 米 勒 、 他 利 亚 、 亚 哈 斯 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10612', '13', '8', '36', '亚 哈 斯 生 耶 何 阿 达 ； 耶 何 阿 达 生 亚 拉 篾 、 亚 斯 玛 威 、 心 利 ； 心 利 生 摩 撒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10613', '13', '8', '37', '摩 撒 生 比 尼 亚 ； 比 尼 亚 的 儿 子 是 拉 法 ； 拉 法 的 儿 子 是 以 利 亚 萨 ； 以 利 亚 萨 的 儿 子 是 亚 悉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10614', '13', '8', '38', '亚 悉 有 六 个 儿 子 ， 他 们 的 名 字 是 亚 斯 利 干 、 波 基 路 、 以 实 玛 利 、 示 亚 利 雅 、 俄 巴 底 雅 、 哈 难 。 这 都 是 亚 悉 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10615', '13', '8', '39', '亚 悉 兄 弟 以 设 的 长 子 是 乌 兰 ， 次 子 耶 乌 施 ， 三 子 是 以 利 法 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10616', '13', '8', '40', '乌 兰 的 儿 子 都 是 大 能 的 勇 士 ， 是 弓 箭 手 ， 他 们 有 许 多 的 子 孙 ， 共 一 百 五 十 名 ， 都 是 便 雅 悯 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10617', '13', '9', '1', '＜ 被 掳 归 回 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10618', '13', '9', '2', '先 从 巴 比 伦 回 来 ， 住 在 自 己 地 业 城 邑 中 的 有 以 色 列 人 、 祭 司 、 利 未 人 、 尼 提 宁 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10619', '13', '9', '3', '住 在 耶 路 撒 冷 的 有 犹 大 人 、 便 雅 悯 人 、 以 法 莲 人 、 玛 拿 西 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10620', '13', '9', '4', '犹 大 儿 子 法 勒 斯 的 子 孙 中 有 乌 太 。 乌 太 是 亚 米 忽 的 儿 子 ； 亚 米 忽 是 暗 利 的 儿 子 ； 暗 利 是 音 利 的 儿 子 ； 音 利 是 巴 尼 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10621', '13', '9', '5', '示 罗 的 子 孙 中 有 长 子 亚 帅 雅 和 他 的 众 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10622', '13', '9', '6', '谢 拉 的 子 孙 中 有 耶 乌 利 和 他 的 弟 兄 ， 共 六 百 九 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10623', '13', '9', '7', '便 雅 悯 人 中 有 哈 西 努 的 曾 孙 、 何 达 威 雅 的 孙 子 、 米 书 兰 的 儿 子 撒 路 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10624', '13', '9', '8', '又 有 耶 罗 罕 的 儿 子 伊 比 尼 雅 ， 米 基 立 的 孙 子 、 乌 西 的 儿 子 以 拉 ， 伊 比 尼 雅 的 曾 孙 、 流 珥 的 孙 子 、 示 法 提 雅 的 儿 子 米 书 兰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10625', '13', '9', '9', '和 他 们 的 族 弟 兄 ， 按 着 家 谱 计 算 共 有 九 百 五 十 六 名 。 这 些 人 都 是 他 们 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10626', '13', '9', '10', '＜ 住 在 耶 路 撒 冷 的 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10627', '13', '9', '11', '还 有 管 理 神 殿 希 勒 家 的 儿 子 亚 萨 利 雅 。 希 勒 家 是 米 书 兰 的 儿 子 ； 米 书 兰 是 撒 督 的 儿 子 ； 撒 督 是 米 拉 约 的 儿 子 ； 米 拉 约 是 亚 希 突 的 儿 子 。');
