INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10643', '13', '9', '27', '他 们 住 在 神 殿 的 四 围 ， 是 因 委 托 他 们 守 殿 ， 要 每 日 早 晨 开 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10644', '13', '9', '28', '＜ 其 余 的 利 未 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10645', '13', '9', '29', '又 有 人 管 理 器 具 和 圣 所 的 器 皿 ， 并 细 面 、 酒 、 油 、 乳 香 、 香 料 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10646', '13', '9', '30', '祭 司 中 有 人 用 香 料 做 膏 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10647', '13', '9', '31', '利 未 人 玛 他 提 雅 是 可 拉 族 沙 龙 的 长 子 ， 他 紧 要 的 职 任 是 管 理 盘 中 烤 的 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10648', '13', '9', '32', '他 们 族 弟 兄 哥 辖 子 孙 中 ， 有 管 理 陈 设 饼 的 ， 每 安 息 日 预 备 摆 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10649', '13', '9', '33', '歌 唱 的 有 利 未 人 的 族 长 ， 住 在 属 殿 的 房 屋 ， 昼 夜 供 职 ， 不 做 别 样 的 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10650', '13', '9', '34', '以 上 都 是 利 未 人 著 名 的 族 长 ， 住 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10651', '13', '9', '35', '＜ 扫 罗 王 的 祖 先 和 后 代 （ 代 上   8 : 2 9 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10652', '13', '9', '36', '他 长 子 是 亚 伯 顿 。 他 又 生 苏 珥 、 基 士 、 巴 力 、 尼 珥 、 拿 答 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10653', '13', '9', '37', '基 多 、 亚 希 约 、 撒 迦 利 雅 、 米 基 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10654', '13', '9', '38', '米 基 罗 生 示 米 暗 。 这 些 人 和 他 们 的 弟 兄 在 耶 路 撒 冷 对 面 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10655', '13', '9', '39', '尼 珥 生 基 士 ； 基 士 生 扫 罗 ； 扫 罗 生 约 拿 单 、 麦 基 舒 亚 、 亚 比 拿 达 、 伊 施 ． 巴 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10656', '13', '9', '40', '约 拿 单 的 儿 子 是 米 力 ． 巴 力 ｛ 就 是 米 非 波 设 ｝ ； 米 力 ． 巴 力 生 米 迦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10657', '13', '9', '41', '米 迦 的 儿 子 是 毗 敦 、 米 勒 、 他 利 亚 、 亚 哈 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10658', '13', '9', '42', '亚 哈 斯 生 雅 拉 ； 雅 拉 生 亚 拉 篾 、 亚 斯 玛 威 、 心 利 ； 心 利 生 摩 撒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10659', '13', '9', '43', '摩 撒 生 比 尼 亚 ； 比 尼 亚 生 利 法 雅 ； 利 法 雅 的 儿 子 是 以 利 亚 萨 ； 以 利 亚 萨 的 儿 子 是 亚 悉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10660', '13', '9', '44', '亚 悉 有 六 个 儿 子 ， 他 们 的 名 字 是 亚 斯 利 干 、 波 基 路 、 以 实 玛 利 、 示 亚 利 雅 、 俄 巴 底 雅 、 哈 难 。 这 都 是 亚 悉 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10661', '13', '10', '1', '＜ 扫 罗 逝 世 （ 撒 上   3 1 : 1 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10662', '13', '10', '2', '非 利 士 人 紧 追 扫 罗 和 他 儿 子 们 ， 就 杀 了 扫 罗 的 儿 子 约 拿 单 、 亚 比 拿 达 、 麦 基 舒 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10663', '13', '10', '3', '势 派 甚 大 ， 扫 罗 被 弓 箭 手 追 上 ， 射 伤 甚 重 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10664', '13', '10', '4', '就 吩 咐 拿 他 兵 器 的 人 说 ： “ 你 拔 出 刀 来 ， 将 我 刺 死 ， 免 得 那 些 未 受 割 礼 的 人 来 凌 辱 我 。 ” 但 拿 兵 器 的 人 甚 惧 怕 ， 不 肯 刺 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10665', '13', '10', '5', '扫 罗 就 自 己 伏 在 刀 上 死 了 。 拿 兵 器 的 人 见 扫 罗 已 死 ， 也 伏 在 刀 上 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10666', '13', '10', '6', '这 样 ， 扫 罗 和 他 三 个 儿 子 ， 并 他 的 全 家 都 一 同 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10667', '13', '10', '7', '住 平 原 的 以 色 列 众 人 见 以 色 列 军 兵 逃 跑 ， 扫 罗 和 他 儿 子 都 死 了 ， 也 就 弃 城 逃 跑 ， 非 利 士 人 便 来 住 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10668', '13', '10', '8', '次 日 ， 非 利 士 人 来 剥 那 被 杀 之 人 的 衣 服 ， 看 见 扫 罗 和 他 儿 子 仆 倒 在 基 利 波 山 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10669', '13', '10', '9', '就 剥 了 他 的 军 装 ， 割 下 他 的 首 级 ， 打 发 人 到 ｛ 到 ： 或 译 送 到 ｝ 非 利 士 地 的 四 境 报 信 与 他 们 的 偶 像 和 众 民 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10670', '13', '10', '10', '又 将 扫 罗 的 军 装 放 在 他 们 神 的 庙 里 ， 将 他 的 首 级 钉 在 大 衮 庙 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10671', '13', '10', '11', '基 列 ． 雅 比 人 听 见 非 利 士 人 向 扫 罗 所 行 的 一 切 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10672', '13', '10', '12', '他 们 中 间 所 有 的 勇 士 就 起 身 前 去 ， 将 扫 罗 和 他 儿 子 的 尸 身 送 到 雅 比 ， 将 他 们 的 尸 骨 葬 在 雅 比 的 橡 树 下 ， 就 禁 食 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10673', '13', '10', '13', '这 样 ， 扫 罗 死 了 。 因 为 他 干 犯 耶 和 华 ， 没 有 遵 守 耶 和 华 的 命 ； 又 因 他 求 问 交 鬼 的 妇 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10674', '13', '10', '14', '没 有 求 问 耶 和 华 ， 所 以 耶 和 华 使 他 被 杀 ， 把 国 归 于 耶 西 的 儿 子 大 卫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10675', '13', '11', '1', '＜ 大 卫 作 以 色 列 和 犹 大 的 王 （ 撒 下   5 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10676', '13', '11', '2', '从 前 扫 罗 作 王 的 时 候 ， 率 领 以 色 列 人 出 入 的 是 你 ； 耶 和 华 ─ ─ 你 的 神 也 曾 应 许 你 说 ： ‘ 你 必 牧 养 我 的 民 以 色 列 ， 作 以 色 列 的 君 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10677', '13', '11', '3', '于 是 以 色 列 的 长 老 都 来 到 希 伯 仑 见 大 卫 王 。 大 卫 在 希 伯 仑 耶 和 华 面 前 与 他 们 立 约 ， 他 们 就 膏 大 卫 作 以 色 列 的 王 ， 是 照 耶 和 华 藉 撒 母 耳 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10678', '13', '11', '4', '大 卫 和 以 色 列 众 人 到 了 耶 路 撒 冷 ， 就 是 耶 布 斯 ； 那 时 耶 布 斯 人 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10679', '13', '11', '5', '耶 布 斯 人 对 大 卫 说 ： “ 你 决 不 能 进 这 地 方 。 ” 然 而 大 卫 攻 取 锡 安 的 保 障 ， 就 是 大 卫 的 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10680', '13', '11', '6', '大 卫 说 ： “ 谁 先 攻 打 耶 布 斯 人 ， 必 作 首 领 元 帅 。 ” 洗 鲁 雅 的 儿 子 约 押 先 上 去 ， 就 作 了 元 帅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10681', '13', '11', '7', '大 卫 住 在 保 障 里 ， 所 以 那 保 障 叫 作 大 卫 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10682', '13', '11', '8', '大 卫 又 从 米 罗 起 ， 四 围 建 筑 城 墙 ， 其 余 的 是 约 押 修 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10683', '13', '11', '9', '大 卫 日 见 强 盛 ， 因 为 万 军 之 耶 和 华 与 他 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10684', '13', '11', '10', '＜ 大 卫 的 有 名 将 领 （ 撒 下   2 3 : 8 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10685', '13', '11', '11', '大 卫 勇 士 的 数 目 记 在 下 面 ： 哈 革 摩 尼 的 儿 子 雅 朔 班 ， 他 是 军 长 的 统 领 ， 一 时 举 枪 杀 了 三 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10686', '13', '11', '12', '其 次 是 亚 合 人 朵 多 的 儿 子 以 利 亚 撒 ， 他 是 三 个 勇 士 里 的 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10687', '13', '11', '13', '他 从 前 与 大 卫 在 巴 斯 ． 达 闵 ， 非 利 士 人 聚 集 要 打 仗 。 那 里 有 一 块 长 满 大 麦 的 田 ， 众 民 就 在 非 利 士 人 面 前 逃 跑 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10688', '13', '11', '14', '这 勇 士 便 站 在 那 田 间 击 杀 非 利 士 人 ， 救 护 了 那 田 。 耶 和 华 使 以 色 列 人 大 获 全 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10689', '13', '11', '15', '三 十 个 勇 士 中 的 三 个 人 下 到 磐 石 那 里 ， 进 了 亚 杜 兰 洞 见 大 卫 ； 非 利 士 的 军 队 在 利 乏 音 谷 安 营 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10690', '13', '11', '16', '那 时 大 卫 在 山 寨 ， 非 利 士 人 的 防 营 在 伯 利 恒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10691', '13', '11', '17', '大 卫 渴 想 ， 说 ： “ 甚 愿 有 人 将 伯 利 恒 城 门 旁 井 里 的 水 打 来 给 我 喝 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10692', '13', '11', '18', '这 三 个 勇 士 就 闯 过 非 利 士 人 的 营 盘 ， 从 伯 利 恒 城 门 旁 的 井 里 打 水 ， 拿 来 奉 给 大 卫 。 他 却 不 肯 喝 ， 将 水 奠 在 耶 和 华 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10693', '13', '11', '19', '说 ： “ 我 的 神 啊 ， 这 三 个 人 冒 死 去 打 水 ， 这 水 好 像 他 们 的 血 一 般 ， 我 断 不 敢 喝 ！ ” 如 此 ， 大 卫 不 肯 喝 。 这 是 三 个 勇 士 所 做 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10694', '13', '11', '20', '约 押 的 兄 弟 亚 比 筛 是 这 三 个 勇 士 的 首 领 ； 他 举 枪 杀 了 三 百 人 ， 就 在 三 个 勇 士 里 得 了 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10695', '13', '11', '21', '他 在 这 三 个 勇 士 里 是 最 尊 贵 的 ， 所 以 作 他 们 的 首 领 ； 只 是 不 及 前 三 个 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10696', '13', '11', '22', '有 甲 薛 勇 士 耶 何 耶 大 的 儿 子 比 拿 雅 行 过 大 能 的 事 ： 他 杀 了 摩 押 人 亚 利 伊 勒 的 两 个 儿 子 ， 又 在 下 雪 的 时 候 下 坑 里 去 杀 了 一 个 狮 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10697', '13', '11', '23', '又 杀 了 一 个 埃 及 人 。 埃 及 人 身 高 五 肘 ， 手 里 拿 着 枪 ， 枪 杆 粗 如 织 布 的 机 轴 ； 比 拿 雅 只 拿 着 棍 子 下 去 ， 从 埃 及 人 手 里 夺 过 枪 来 ， 用 那 枪 将 他 刺 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10698', '13', '11', '24', '这 是 耶 何 耶 大 的 儿 子 比 拿 雅 所 行 的 事 ， 就 在 三 个 勇 士 里 得 了 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10699', '13', '11', '25', '他 比 那 三 十 个 勇 士 都 尊 贵 ， 只 是 不 及 前 三 个 勇 士 。 大 卫 立 他 作 护 卫 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10700', '13', '11', '26', '军 中 的 勇 士 有 约 押 的 兄 弟 亚 撒 黑 ， 伯 利 恒 人 朵 多 的 儿 子 伊 勒 哈 难 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10701', '13', '11', '27', '哈 律 人 沙 玛 ， 比 伦 人 希 利 斯 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10702', '13', '11', '28', '提 哥 亚 人 益 吉 的 儿 子 以 拉 ， 亚 拿 突 人 亚 比 以 谢 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10703', '13', '11', '29', '户 沙 人 西 比 该 ， 亚 合 人 以 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10704', '13', '11', '30', '尼 陀 法 人 玛 哈 莱 ， 尼 陀 法 人 巴 拿 的 儿 子 希 立 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10705', '13', '11', '31', '便 雅 悯 族 基 比 亚 人 利 拜 的 儿 子 以 太 ， 比 拉 顿 人 比 拿 雅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10706', '13', '11', '32', '迦 实 溪 人 户 莱 ， 亚 拉 巴 人 亚 比 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10707', '13', '11', '33', '巴 路 米 人 押 斯 玛 弗 ， 沙 本 人 以 利 雅 哈 巴 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10708', '13', '11', '34', '基 孙 人 哈 深 的 众 子 ， 哈 拉 人 沙 基 的 儿 子 约 拿 单 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10709', '13', '11', '35', '哈 拉 人 沙 甲 的 儿 子 亚 希 暗 ， 吾 珥 的 儿 子 以 利 法 勒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10710', '13', '11', '36', '米 基 拉 人 希 弗 ， 比 伦 人 亚 希 雅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10711', '13', '11', '37', '迦 密 人 希 斯 罗 ， 伊 斯 拜 的 儿 子 拿 莱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10712', '13', '11', '38', '拿 单 的 兄 弟 约 珥 ， 哈 基 利 的 儿 子 弥 伯 哈 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10713', '13', '11', '39', '亚 扪 人 洗 勒 ， 比 录 人 拿 哈 莱 〈 拿 哈 莱 是 给 洗 鲁 雅 的 儿 子 约 押 拿 兵 器 的 〉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10714', '13', '11', '40', '以 帖 人 以 拉 ， 以 帖 人 迦 立 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10715', '13', '11', '41', '赫 人 乌 利 亚 ， 亚 莱 的 儿 子 撒 拔 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10716', '13', '11', '42', '吕 便 人 示 撒 的 儿 子 亚 第 拿 〈 他 是 吕 便 支 派 中 的 一 个 族 长 ， 率 领 三 十 人 〉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10717', '13', '11', '43', '玛 迦 的 儿 子 哈 难 ， 弥 特 尼 人 约 沙 法 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10718', '13', '11', '44', '亚 施 他 拉 人 乌 西 亚 ， 亚 罗 珥 人 何 坦 的 儿 子 沙 玛 、 耶 利 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10719', '13', '11', '45', '提 洗 人 申 利 的 儿 子 耶 叠 和 他 的 兄 弟 约 哈 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10720', '13', '11', '46', '玛 哈 未 人 以 利 业 ， 伊 利 拿 安 的 儿 子 耶 利 拜 、 约 沙 未 雅 ， 摩 押 人 伊 特 玛 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10721', '13', '11', '47', '以 利 业 、 俄 备 得 ， 并 米 琐 八 人 雅 西 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10722', '13', '12', '1', '＜ 早 期 跟 随 大 卫 的 便 雅 悯 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10723', '13', '12', '2', '他 们 善 于 拉 弓 ， 能 用 左 右 两 手 甩 石 射 箭 ， 都 是 便 雅 悯 人 扫 罗 的 族 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10724', '13', '12', '3', '为 首 的 是 亚 希 以 谢 ， 其 次 是 约 阿 施 ， 都 是 基 比 亚 人 示 玛 的 儿 子 。 还 有 亚 斯 玛 威 的 儿 子 耶 薛 和 毗 力 ， 又 有 比 拉 迦 ， 并 亚 拿 突 人 耶 户 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10725', '13', '12', '4', '基 遍 人 以 实 买 雅 〈 他 在 三 十 人 中 是 勇 士 ， 管 理 他 们 〉 ， 且 有 耶 利 米 、 雅 哈 悉 、 约 哈 难 ， 和 基 得 拉 人 约 撒 拔 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10726', '13', '12', '5', '伊 利 乌 赛 、 耶 利 摩 、 比 亚 利 雅 、 示 玛 利 雅 ， 哈 律 弗 人 示 法 提 雅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10727', '13', '12', '6', '可 拉 人 以 利 加 拿 、 耶 西 亚 、 亚 萨 列 、 约 以 谢 、 雅 朔 班 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10728', '13', '12', '7', '基 多 人 耶 罗 罕 的 儿 子 犹 拉 和 西 巴 第 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10729', '13', '12', '8', '＜ 跟 随 大 卫 的 迦 得 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10730', '13', '12', '9', '第 一 以 薛 ， 第 二 俄 巴 底 雅 ， 第 三 以 利 押 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10731', '13', '12', '10', '第 四 弥 施 玛 拿 ， 第 五 耶 利 米 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10732', '13', '12', '11', '第 六 亚 太 ， 第 七 以 利 业 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10733', '13', '12', '12', '第 八 约 哈 难 ， 第 九 以 利 萨 巴 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10734', '13', '12', '13', '第 十 耶 利 米 ， 第 十 一 末 巴 奈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10735', '13', '12', '14', '这 都 是 迦 得 人 中 的 军 长 ， 至 小 的 能 抵 一 百 人 ， 至 大 的 能 抵 一 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10736', '13', '12', '15', '正 月 ， 约 旦 河 水 涨 过 两 岸 的 时 候 ， 他 们 过 河 ， 使 一 切 住 平 原 的 人 东 奔 西 逃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10737', '13', '12', '16', '＜ 跟 随 大 卫 的 便 雅 悯 人 和 犹 大 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10738', '13', '12', '17', '大 卫 出 去 迎 接 他 们 ， 对 他 们 说 ： “ 你 们 若 是 和 和 平 平 地 来 帮 助 我 ， 我 心 就 与 你 们 相 契 ； 你 们 若 是 将 我 这 无 罪 的 人 卖 在 敌 人 手 里 ， 愿 我 们 列 祖 的 神 察 看 责 罚 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10739', '13', '12', '18', '那 时 神 的 灵 感 动 那 三 十 个 勇 士 的 首 领 亚 玛 撒 ， 他 就 说 ： 大 卫 啊 ， 我 们 是 归 于 你 的 ！ 耶 西 的 儿 子 啊 ， 我 们 是 帮 助 你 的 ！ 愿 你 平 平 安 安 ， 愿 帮 助 你 的 也 都 平 安 ！ 因 为 你 的 神 帮 助 你 。 大 卫 就 收 留 他 们 ， 立 他 们 作 军 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10740', '13', '12', '19', '＜ 跟 随 大 卫 的 玛 拿 西 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10741', '13', '12', '20', '大 卫 往 洗 革 拉 去 的 时 候 ， 有 玛 拿 西 人 的 千 夫 长 押 拿 、 约 撒 拔 、 耶 叠 、 米 迦 勒 、 约 撒 拔 、 以 利 户 、 洗 勒 太 都 来 投 奔 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10742', '13', '12', '21', '这 些 人 帮 助 大 卫 攻 击 群 贼 ； 他 们 都 是 大 能 的 勇 士 ， 且 作 军 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10743', '13', '12', '22', '那 时 天 天 有 人 来 帮 助 大 卫 ， 以 致 成 了 大 军 ， 如 神 的 军 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10744', '13', '12', '23', '＜ 大 卫 的 军 力 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10745', '13', '12', '24', '犹 大 支 派 ， 拿 盾 牌 和 枪 预 备 打 仗 的 有 六 千 八 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10746', '13', '12', '25', '西 缅 支 派 ， 能 上 阵 大 能 的 勇 士 有 七 千 一 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10747', '13', '12', '26', '利 未 支 派 有 四 千 六 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10748', '13', '12', '27', '耶 何 耶 大 是 亚 伦 家 的 首 领 ， 跟 从 他 的 有 三 千 七 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10749', '13', '12', '28', '还 有 少 年 大 能 的 勇 士 撒 督 ， 同 着 他 的 有 族 长 二 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10750', '13', '12', '29', '便 雅 悯 支 派 ， 扫 罗 的 族 弟 兄 也 有 三 千 人 ， 他 们 向 来 大 半 归 顺 扫 罗 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10751', '13', '12', '30', '以 法 莲 支 派 大 能 的 勇 士 ， 在 本 族 著 名 的 有 二 万 零 八 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10752', '13', '12', '31', '玛 拿 西 半 支 派 ， 册 上 有 名 的 共 一 万 八 千 人 ， 都 来 立 大 卫 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10753', '13', '12', '32', '以 萨 迦 支 派 ， 有 二 百 族 长 都 通 达 时 务 ， 知 道 以 色 列 人 所 当 行 的 ； 他 们 族 弟 兄 都 听 从 他 们 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10754', '13', '12', '33', '西 布 伦 支 派 ， 能 上 阵 用 各 样 兵 器 打 仗 、 行 伍 整 齐 、 不 生 二 心 的 有 五 万 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10755', '13', '12', '34', '拿 弗 他 利 支 派 ， 有 一 千 军 长 ； 跟 从 他 们 、 拿 盾 牌 和 枪 的 有 三 万 七 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10756', '13', '12', '35', '但 支 派 ， 能 摆 阵 的 有 二 万 八 千 六 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10757', '13', '12', '36', '亚 设 支 派 ， 能 上 阵 打 仗 的 有 四 万 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10758', '13', '12', '37', '约 旦 河 东 的 吕 便 支 派 、 迦 得 支 派 、 玛 拿 西 半 支 派 ， 拿 着 各 样 兵 器 打 仗 的 有 十 二 万 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10759', '13', '12', '38', '以 上 都 是 能 守 行 伍 的 战 士 ， 他 们 都 诚 心 来 到 希 伯 仑 ， 要 立 大 卫 作 以 色 列 的 王 。 以 色 列 其 余 的 人 也 都 一 心 要 立 大 卫 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10760', '13', '12', '39', '他 们 在 那 里 三 日 ， 与 大 卫 一 同 吃 喝 ， 因 为 他 们 的 族 弟 兄 给 他 们 预 备 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10761', '13', '12', '40', '靠 近 他 们 的 人 以 及 以 萨 迦 、 西 布 伦 、 拿 弗 他 利 人 将 许 多 面 饼 、 无 花 果 饼 、 干 葡 萄 、 酒 、 油 ， 用 驴 、 骆 驼 、 骡 子 、 牛 驮 来 ， 又 带 了 许 多 的 牛 和 羊 来 ， 因 为 以 色 列 人 甚 是 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10762', '13', '13', '1', '＜ 约 柜 迁 出 基 列 ． 耶 琳 （ 撒 下   6 : 1 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10763', '13', '13', '2', '大 卫 对 以 色 列 全 会 众 说 ： “ 你 们 若 以 为 美 ， 见 这 事 是 出 于 耶 和 华 ─ ─ 我 们 的 神 ， 我 们 就 差 遣 人 走 遍 以 色 列 地 ， 见 我 们 未 来 的 弟 兄 ， 又 见 住 在 有 郊 野 之 城 的 祭 司 利 未 人 ， 使 他 们 都 到 这 里 来 聚 集 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10764', '13', '13', '3', '我 们 要 把 神 的 约 柜 运 到 我 们 这 里 来 ； 因 为 在 扫 罗 年 间 ， 我 们 没 有 在 约 柜 前 求 问 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10765', '13', '13', '4', '全 会 众 都 说 可 以 如 此 行 ； 这 事 在 众 民 眼 中 都 看 为 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10766', '13', '13', '5', '于 是 ， 大 卫 将 以 色 列 人 从 埃 及 的 西 曷 河 直 到 哈 马 口 都 招 聚 了 来 ， 要 从 基 列 耶 琳 将 神 的 约 柜 运 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10767', '13', '13', '6', '大 卫 率 领 以 色 列 众 人 上 到 巴 拉 ， 就 是 属 犹 大 的 基 列 ． 耶 琳 ， 要 从 那 里 将 约 柜 运 来 。 这 约 柜 就 是 坐 在 二 基 路 伯 上 耶 和 华 神 留 名 的 约 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10768', '13', '13', '7', '他 们 将 神 的 约 柜 从 亚 比 拿 达 的 家 里 抬 出 来 ， 放 在 新 车 上 。 乌 撒 和 亚 希 约 赶 车 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10769', '13', '13', '8', '大 卫 和 以 色 列 众 人 在 神 前 用 琴 、 瑟 、 锣 、 鼓 、 号 作 乐 ， 极 力 跳 舞 歌 唱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10770', '13', '13', '9', '到 了 基 顿 ｛ 在 撒 母 耳 下 六 章 六 节 是 拿 艮 ｝ 的 禾 场 ； 因 为 牛 失 前 蹄 ｛ 或 译 ： 惊 跳 ｝ ， 乌 撒 就 伸 手 扶 住 约 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10771', '13', '13', '10', '耶 和 华 向 他 发 怒 ， 因 他 伸 手 扶 住 约 柜 击 杀 他 ， 他 就 死 在 神 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10772', '13', '13', '11', '大 卫 因 耶 和 华 击 杀 ｛ 原 文 是 闯 杀 ｝ 乌 撒 ， 心 里 愁 烦 ， 就 称 那 地 方 为 毗 列 斯 ． 乌 撒 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10773', '13', '13', '12', '那 日 ， 大 卫 惧 怕 神 ， 说 ： “ 神 的 约 柜 怎 可 运 到 我 这 里 来 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10774', '13', '13', '13', '于 是 大 卫 不 将 约 柜 运 进 大 卫 的 城 ， 却 运 到 迦 特 人 俄 别 ． 以 东 的 家 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10775', '13', '13', '14', '神 的 约 柜 在 俄 别 ． 以 东 家 中 三 个 月 ， 耶 和 华 赐 福 给 俄 别 ． 以 东 的 家 和 他 一 切 所 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10776', '13', '14', '1', '＜ 大 卫 在 耶 路 撒 冷 的 活 动 （ 撒 下   5 : 1 1 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10777', '13', '14', '2', '大 卫 就 知 道 耶 和 华 坚 立 他 作 以 色 列 王 ， 又 为 自 己 的 民 以 色 列 ， 使 他 的 国 兴 旺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10778', '13', '14', '3', '大 卫 在 耶 路 撒 冷 又 立 后 妃 ， 又 生 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10779', '13', '14', '4', '在 耶 路 撒 冷 所 生 的 众 子 是 沙 母 亚 、 朔 罢 、 拿 单 、 所 罗 门 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10780', '13', '14', '5', '益 辖 、 以 利 书 亚 、 以 法 列 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10781', '13', '14', '6', '挪 迦 、 尼 斐 、 雅 非 亚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10782', '13', '14', '7', '以 利 沙 玛 、 比 利 雅 大 、 以 利 法 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10783', '13', '14', '8', '＜ 战 胜 非 利 士 人 （ 撒 下   5 : 1 7 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10784', '13', '14', '9', '非 利 士 人 来 了 ， 布 散 在 利 乏 音 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10785', '13', '14', '10', '大 卫 求 问 神 ， 说 ： “ 我 可 以 上 去 攻 打 非 利 士 人 吗 ？ 你 将 他 们 交 在 我 手 里 吗 ？ ” 耶 和 华 说 ： “ 你 可 以 上 去 ， 我 必 将 他 们 交 在 你 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10786', '13', '14', '11', '非 利 士 人 来 到 巴 力 ． 毗 拉 心 ， 大 卫 在 那 里 杀 败 他 们 。 大 卫 说 ： “ 神 藉 我 的 手 冲 破 敌 人 ， 如 同 水 冲 去 一 般 ” ； 因 此 称 那 地 方 为 巴 力 ． 毗 拉 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10787', '13', '14', '12', '非 利 士 人 将 神 像 撇 在 那 里 ， 大 卫 吩 咐 人 用 火 焚 烧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10788', '13', '14', '13', '非 利 士 人 又 布 散 在 利 乏 音 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10789', '13', '14', '14', '大 卫 又 求 问 神 。 神 说 ： “ 不 要 一 直 地 上 去 ， 要 转 到 他 们 后 头 ， 从 桑 林 对 面 攻 打 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10790', '13', '14', '15', '你 听 见 桑 树 梢 上 有 脚 步 的 声 音 ， 就 要 出 战 ， 因 为 神 已 经 在 你 前 头 去 攻 打 非 利 士 人 的 军 队 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10791', '13', '14', '16', '大 卫 就 遵 着 神 所 吩 咐 的 ， 攻 打 非 利 士 人 的 军 队 ， 从 基 遍 直 到 基 色 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10792', '13', '14', '17', '于 是 大 卫 的 名 传 扬 到 列 国 ， 耶 和 华 使 列 国 都 惧 怕 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10793', '13', '15', '1', '＜ 准 备 搬 运 约 柜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10794', '13', '15', '2', '那 时 大 卫 说 ： “ 除 了 利 未 人 之 外 ， 无 人 可 抬 神 的 约 柜 ； 因 为 耶 和 华 拣 选 他 们 抬 神 的 约 柜 ， 且 永 远 事 奉 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10795', '13', '15', '3', '大 卫 招 聚 以 色 列 众 人 到 耶 路 撒 冷 ， 要 将 耶 和 华 的 约 柜 抬 到 他 所 预 备 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10796', '13', '15', '4', '大 卫 又 聚 集 亚 伦 的 子 孙 和 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10797', '13', '15', '5', '哥 辖 子 孙 中 有 族 长 乌 列 和 他 的 弟 兄 一 百 二 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10798', '13', '15', '6', '米 拉 利 子 孙 中 有 族 长 亚 帅 雅 和 他 的 弟 兄 二 百 二 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10799', '13', '15', '7', '革 顺 子 孙 中 有 族 长 约 珥 和 他 的 弟 兄 一 百 三 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10800', '13', '15', '8', '以 利 撒 反 子 孙 中 有 族 长 示 玛 雅 和 他 的 弟 兄 二 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10801', '13', '15', '9', '希 伯 仑 子 孙 中 有 族 长 以 列 和 他 的 弟 兄 八 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10802', '13', '15', '10', '乌 薛 子 孙 中 有 族 长 亚 米 拿 达 和 他 的 弟 兄 一 百 一 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10803', '13', '15', '11', '大 卫 将 祭 司 撒 督 和 亚 比 亚 他 ， 并 利 未 人 乌 列 、 亚 帅 雅 、 约 珥 、 示 玛 雅 、 以 列 、 亚 米 拿 达 召 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10804', '13', '15', '12', '对 他 们 说 ： “ 你 们 是 利 未 人 的 族 长 ， 你 们 和 你 们 的 弟 兄 应 当 自 洁 ， 好 将 耶 和 华 ─ ─ 以 色 列 神 的 约 柜 抬 到 我 所 预 备 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10805', '13', '15', '13', '因 你 们 先 前 没 有 抬 这 约 柜 ， 按 定 例 求 问 耶 和 华 ─ ─ 我 们 的 神 ， 所 以 他 刑 罚 ｛ 原 文 是 闯 杀 ｝ 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10806', '13', '15', '14', '于 是 祭 司 利 未 人 自 洁 ， 好 将 耶 和 华 ─ ─ 以 色 列 神 的 约 柜 抬 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10807', '13', '15', '15', '利 未 子 孙 就 用 杠 ， 肩 抬 神 的 约 柜 ， 是 照 耶 和 华 藉 摩 西 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10808', '13', '15', '16', '大 卫 吩 咐 利 未 人 的 族 长 ， 派 他 们 歌 唱 的 弟 兄 用 琴 瑟 和 钹 作 乐 ， 欢 欢 喜 喜 地 大 声 歌 颂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10809', '13', '15', '17', '于 是 利 未 人 派 约 珥 的 儿 子 希 幔 和 他 弟 兄 中 比 利 家 的 儿 子 亚 萨 ， 并 他 们 族 弟 兄 米 拉 利 子 孙 里 古 沙 雅 的 儿 子 以 探 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10810', '13', '15', '18', '其 次 还 有 他 们 的 弟 兄 撒 迦 利 雅 、 便 雅 薛 、 示 米 拉 末 、 耶 歇 、 乌 尼 、 以 利 押 、 比 拿 雅 、 玛 西 雅 、 玛 他 提 雅 、 以 利 斐 利 户 、 弥 克 尼 雅 ， 并 守 门 的 俄 别 ． 以 东 和 耶 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10811', '13', '15', '19', '这 样 ， 派 歌 唱 的 希 幔 、 亚 萨 、 以 探 敲 铜 钹 ， 大 发 响 声 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10812', '13', '15', '20', '派 撒 迦 利 雅 、 雅 薛 、 示 米 拉 末 、 耶 歇 、 乌 尼 、 以 利 押 、 玛 西 雅 、 比 拿 雅 鼓 瑟 ， 调 用 女 音 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10813', '13', '15', '21', '又 派 玛 他 提 雅 、 以 利 斐 利 户 、 弥 克 尼 雅 、 俄 别 ． 以 东 、 耶 利 、 亚 撒 西 雅 领 首 弹 琴 ， 调 用 第 八 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10814', '13', '15', '22', '利 未 人 的 族 长 基 拿 尼 雅 是 歌 唱 人 的 首 领 ， 又 教 训 人 歌 唱 ， 因 为 他 精 通 此 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10815', '13', '15', '23', '比 利 家 、 以 利 加 拿 是 约 柜 前 守 门 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10816', '13', '15', '24', '祭 司 示 巴 尼 、 约 沙 法 、 拿 坦 业 、 亚 玛 赛 、 撒 迦 利 雅 、 比 拿 亚 、 以 利 以 谢 在 神 的 约 柜 前 吹 号 。 俄 别 ． 以 东 和 耶 希 亚 也 是 约 柜 前 守 门 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10817', '13', '15', '25', '＜ 约 柜 迁 入 耶 路 撒 冷 （ 撒 下   6 : 1 2 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10818', '13', '15', '26', '神 赐 恩 与 抬 耶 和 华 约 柜 的 利 未 人 ， 他 们 就 献 上 七 只 公 牛 ， 七 只 公 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10819', '13', '15', '27', '大 卫 和 抬 约 柜 的 利 未 人 ， 并 歌 唱 人 的 首 领 基 拿 尼 雅 ， 以 及 歌 唱 的 人 ， 都 穿 着 细 麻 布 的 外 袍 ； 大 卫 另 外 穿 着 细 麻 布 的 以 弗 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10820', '13', '15', '28', '这 样 ， 以 色 列 众 人 欢 呼 吹 角 、 吹 号 、 敲 钹 、 鼓 瑟 、 弹 琴 ， 大 发 响 声 ， 将 耶 和 华 的 约 柜 抬 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10821', '13', '15', '29', '耶 和 华 的 约 柜 进 了 大 卫 城 的 时 候 ， 扫 罗 的 女 儿 米 甲 从 窗 户 里 观 看 ， 见 大 卫 王 踊 跃 跳 舞 ， 心 里 就 轻 视 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10822', '13', '16', '1', '众 人 将 神 的 约 柜 请 进 去 ， 安 放 在 大 卫 所 搭 的 帐 幕 里 ， 就 在 神 面 前 献 燔 祭 和 平 安 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10823', '13', '16', '2', '大 卫 献 完 了 燔 祭 和 平 安 祭 ， 就 奉 耶 和 华 的 名 给 民 祝 福 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10824', '13', '16', '3', '并 且 分 给 以 色 列 人 ， 无 论 男 女 ， 每 人 一 个 饼 ， 一 块 肉 ， 一 个 葡 萄 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10825', '13', '16', '4', '大 卫 派 几 个 利 未 人 在 耶 和 华 的 约 柜 前 事 奉 ， 颂 扬 ， 称 谢 ， 赞 美 耶 和 华 ─ ─ 以 色 列 的 神 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10826', '13', '16', '5', '为 首 的 是 亚 萨 ， 其 次 是 撒 迦 利 雅 、 雅 薛 、 示 米 拉 末 、 耶 歇 、 玛 他 提 雅 、 以 利 押 、 比 拿 雅 、 俄 别 ． 以 东 、 耶 利 ， 鼓 瑟 弹 琴 ； 惟 有 亚 萨 敲 钹 ， 大 发 响 声 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10827', '13', '16', '6', '祭 司 比 拿 雅 和 雅 哈 悉 常 在 神 的 约 柜 前 吹 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10828', '13', '16', '7', '那 日 ， 大 卫 初 次 藉 亚 萨 和 他 的 弟 兄 以 诗 歌 称 颂 耶 和 华 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10829', '13', '16', '8', '＜ 颂 赞 之 歌 （ 诗   1 0 5 : 1 - 1 5 ； 9 6 : 1 - 1 3 ； 1 0 6 : 1 , 4 7 - 4 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10830', '13', '16', '9', '要 向 他 唱 诗 、 歌 颂 ， 谈 论 他 一 切 奇 妙 的 作 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10831', '13', '16', '10', '要 以 他 的 圣 名 夸 耀 ； 寻 求 耶 和 华 的 人 ， 心 中 应 当 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10832', '13', '16', '11', '要 寻 求 耶 和 华 与 他 的 能 力 ， 时 常 寻 求 他 的 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10833', '13', '16', '12', '他 仆 人 以 色 列 的 后 裔 ， 他 所 拣 选 雅 各 的 子 孙 哪 ， 你 们 要 记 念 他 奇 妙 的 作 为 和 他 的 奇 事 ， 并 他 口 中 的 判 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10834', '13', '16', '13', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10835', '13', '16', '14', '他 是 耶 和 华 ─ ─ 我 们 的 神 ， 全 地 都 有 他 的 判 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10836', '13', '16', '15', '你 们 要 记 念 他 的 约 ， 直 到 永 远 ； 他 所 吩 咐 的 话 ， 直 到 千 代 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10837', '13', '16', '16', '就 是 与 亚 伯 拉 罕 所 立 的 约 ， 向 以 撒 所 起 的 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10838', '13', '16', '17', '他 又 将 这 约 向 雅 各 定 为 律 例 ， 向 以 色 列 定 为 永 远 的 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10839', '13', '16', '18', '说 ： 我 必 将 迦 南 地 赐 给 你 ， 作 你 产 业 的 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10840', '13', '16', '19', '当 时 你 们 人 丁 有 限 ， 数 目 稀 少 ， 并 且 在 那 地 为 寄 居 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10841', '13', '16', '20', '他 们 从 这 邦 游 到 那 邦 ， 从 这 国 行 到 那 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10842', '13', '16', '21', '耶 和 华 不 容 什 么 人 欺 负 他 们 ， 为 他 们 的 缘 故 责 备 君 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10843', '13', '16', '22', '说 ： 不 可 难 为 我 受 膏 的 人 ， 也 不 可 恶 待 我 的 先 知 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10844', '13', '16', '23', '全 地 都 要 向 耶 和 华 歌 唱 ！ 天 天 传 扬 他 的 救 恩 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10845', '13', '16', '24', '在 列 邦 中 述 说 他 的 荣 耀 ， 在 万 民 中 述 说 他 的 奇 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10846', '13', '16', '25', '因 耶 和 华 为 大 ， 当 受 极 大 的 赞 美 ； 他 在 万 神 之 上 ， 当 受 敬 畏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10847', '13', '16', '26', '外 邦 的 神 都 属 虚 无 ， 惟 独 耶 和 华 创 造 诸 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10848', '13', '16', '27', '有 尊 荣 和 威 严 在 他 面 前 ， 有 能 力 和 喜 乐 在 他 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10849', '13', '16', '28', '民 中 的 万 族 啊 ， 你 们 要 将 荣 耀 能 力 归 给 耶 和 华 ， 都 归 给 耶 和 华 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10850', '13', '16', '29', '要 将 耶 和 华 的 名 所 当 得 的 荣 耀 归 给 他 ， 拿 供 物 来 奉 到 他 面 前 ； 当 以 圣 洁 的 ｛ 的 ： 或 译 为 ｝ 妆 饰 敬 拜 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10851', '13', '16', '30', '全 地 要 在 他 面 前 战 抖 ， 世 界 也 坚 定 不 得 动 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10852', '13', '16', '31', '愿 天 欢 喜 ， 愿 地 快 乐 ； 愿 人 在 列 邦 中 说 ： 耶 和 华 作 王 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10853', '13', '16', '32', '愿 海 和 其 中 所 充 满 的 澎 湃 ； 愿 田 和 其 中 所 有 的 都 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10854', '13', '16', '33', '那 时 ， 林 中 的 树 木 都 要 在 耶 和 华 面 前 欢 呼 ， 因 为 他 来 要 审 判 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10855', '13', '16', '34', '应 当 称 谢 耶 和 华 ； 因 他 本 为 善 ， 他 的 慈 爱 永 远 长 存 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10856', '13', '16', '35', '要 说 ： 拯 救 我 们 的 神 啊 ， 求 你 救 我 们 ， 聚 集 我 们 ， 使 我 们 脱 离 外 邦 ， 我 们 好 称 赞 你 的 圣 名 ， 以 赞 美 你 为 夸 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10857', '13', '16', '36', '耶 和 华 ─ ─ 以 色 列 的 神 ， 从 亘 古 直 到 永 远 ， 是 应 当 称 颂 的 ！ 众 民 都 说 ： “ 阿 们 ！ ” 并 且 赞 美 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10858', '13', '16', '37', '＜ 在 耶 路 撒 冷 和 基 遍 的 敬 拜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10859', '13', '16', '38', '又 派 俄 别 ． 以 东 和 他 的 弟 兄 六 十 八 人 ， 与 耶 杜 顿 的 儿 子 俄 别 ． 以 东 ， 并 何 萨 作 守 门 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10860', '13', '16', '39', '且 派 祭 司 撒 督 和 他 弟 兄 众 祭 司 在 基 遍 的 邱 坛 、 耶 和 华 的 帐 幕 前 燔 祭 坛 上 ， 每 日 早 晚 ， 照 着 耶 和 华 律 法 书 上 所 吩 咐 以 色 列 人 的 ， 常 给 耶 和 华 献 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10861', '13', '16', '40', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10862', '13', '16', '41', '与 他 们 一 同 被 派 的 有 希 幔 、 耶 杜 顿 ， 和 其 余 被 选 名 字 录 在 册 上 的 ， 称 谢 耶 和 华 ， 因 他 的 慈 爱 永 远 长 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10863', '13', '16', '42', '希 幔 、 耶 杜 顿 同 着 他 们 吹 号 、 敲 钹 ， 大 发 响 声 ， 并 用 别 的 乐 器 随 着 歌 颂 神 。 耶 杜 顿 的 子 孙 作 守 门 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10864', '13', '16', '43', '于 是 众 民 各 归 各 家 ； 大 卫 也 回 去 为 家 眷 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10865', '13', '17', '1', '＜ 拿 单 传 给 大 卫 的 信 息 （ 撒 下   7 : 1 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10866', '13', '17', '2', '拿 单 对 大 卫 说 ： “ 你 可 以 照 你 的 心 意 而 行 ， 因 为 神 与 你 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10867', '13', '17', '3', '当 夜 ， 神 的 话 临 到 拿 单 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10868', '13', '17', '4', '“ 你 去 告 诉 我 仆 人 大 卫 ， 说 耶 和 华 如 此 说 ： ‘ 你 不 可 建 造 殿 宇 给 我 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10869', '13', '17', '5', '自 从 我 领 以 色 列 人 出 埃 及 ， 直 到 今 日 ， 我 未 曾 住 过 殿 宇 ， 乃 从 这 会 幕 到 那 会 幕 ， 从 这 帐 幕 到 那 帐 幕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10870', '13', '17', '6', '凡 我 同 以 色 列 人 所 走 的 地 方 ， 我 何 曾 向 以 色 列 的 一 个 士 师 ， 就 是 我 吩 咐 牧 养 我 民 的 说 ： 你 为 何 不 给 我 建 造 香 柏 木 的 殿 宇 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10871', '13', '17', '7', '现 在 你 要 告 诉 我 仆 人 大 卫 ， 说 万 军 之 耶 和 华 如 此 说 ： ‘ 我 从 羊 圈 中 将 你 召 来 ， 叫 你 不 再 跟 从 羊 群 ， 立 你 作 我 民 以 色 列 的 君 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10872', '13', '17', '8', '你 无 论 往 哪 里 去 ， 我 常 与 你 同 在 ， 剪 除 你 的 一 切 仇 敌 ； 我 必 使 你 得 大 名 ， 好 像 世 上 大 大 有 名 的 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10873', '13', '17', '9', '我 必 为 我 民 以 色 列 选 定 一 个 地 方 ， 栽 培 他 们 ， 使 他 们 住 自 己 的 地 方 ， 不 再 迁 移 ； 凶 恶 之 子 也 不 像 从 前 扰 害 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10874', '13', '17', '10', '并 不 像 我 命 士 师 治 理 我 民 以 色 列 的 时 候 一 样 。 我 必 治 服 你 的 一 切 仇 敌 ， 并 且 我 ─ ─ 耶 和 华 应 许 你 ， 必 为 你 建 立 家 室 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10875', '13', '17', '11', '你 寿 数 满 足 归 你 列 祖 的 时 候 ， 我 必 使 你 的 后 裔 接 续 你 的 位 ， 我 也 必 坚 定 他 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10876', '13', '17', '12', '他 必 为 我 建 造 殿 宇 ； 我 必 坚 定 他 的 国 位 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10877', '13', '17', '13', '我 要 作 他 的 父 ， 他 要 作 我 的 子 ； 并 不 使 我 的 慈 爱 离 开 他 ， 像 离 开 在 你 以 前 的 扫 罗 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10878', '13', '17', '14', '我 却 要 将 他 永 远 坚 立 在 我 家 里 和 我 国 里 ； 他 的 国 位 也 必 坚 定 ， 直 到 永 远 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10879', '13', '17', '15', '拿 单 就 按 这 一 切 话 ， 照 这 默 示 告 诉 大 卫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10880', '13', '17', '16', '＜ 感 恩 的 祷 告 （ 撒 下   7 : 1 8 - 2 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10881', '13', '17', '17', '神 啊 ， 这 在 你 眼 中 还 看 为 小 ， 又 应 许 你 仆 人 的 家 至 于 久 远 。 耶 和 华 神 啊 ， 你 看 顾 我 好 像 看 顾 高 贵 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10882', '13', '17', '18', '你 加 于 仆 人 的 尊 荣 ， 我 还 有 何 言 可 说 呢 ？ 因 为 你 知 道 你 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10883', '13', '17', '19', '耶 和 华 啊 ， 你 行 了 这 大 事 ， 并 且 显 明 出 来 ， 是 因 你 仆 人 的 缘 故 ， 也 是 照 你 的 心 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10884', '13', '17', '20', '耶 和 华 啊 ， 照 我 们 耳 中 听 见 ， 没 有 可 比 你 的 ， 除 你 以 外 再 无 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10885', '13', '17', '21', '世 上 有 何 民 能 比 你 的 民 以 色 列 呢 ？ 你 神 从 埃 及 救 赎 他 们 作 自 己 的 子 民 ， 又 在 你 赎 出 来 的 民 面 前 行 大 而 可 畏 的 事 ， 驱 逐 列 邦 人 ， 显 出 你 的 大 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10886', '13', '17', '22', '你 使 以 色 列 人 作 你 的 子 民 ， 直 到 永 远 ； 你 ─ ─ 耶 和 华 也 作 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10887', '13', '17', '23', '耶 和 华 啊 ， 你 所 应 许 仆 人 和 仆 人 家 的 话 ， 求 你 坚 定 ， 直 到 永 远 ， 照 你 所 说 的 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10888', '13', '17', '24', '愿 你 的 名 永 远 坚 立 ， 被 尊 为 大 ， 说 ： ‘ 万 军 之 耶 和 华 是 以 色 列 的 神 ， 是 治 理 以 色 列 的 神 。 ’ 这 样 ， 你 仆 人 大 卫 的 家 必 在 你 面 前 坚 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10889', '13', '17', '25', '我 的 神 啊 ， 因 你 启 示 仆 人 说 ， 我 必 为 你 建 立 家 室 ， 所 以 仆 人 大 胆 在 你 面 前 祈 祷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10890', '13', '17', '26', '耶 和 华 啊 ， 惟 有 你 是 神 ， 你 也 应 许 将 这 福 气 赐 给 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10891', '13', '17', '27', '现 在 你 喜 悦 赐 福 与 仆 人 的 家 ， 可 以 永 存 在 你 面 前 。 耶 和 华 啊 ， 你 已 经 赐 福 ， 还 要 赐 福 到 永 远 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10892', '13', '18', '1', '＜ 在 军 事 上 的 胜 利 （ 撒 下   8 : 1 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10893', '13', '18', '2', '又 攻 打 摩 押 ， 摩 押 人 就 归 服 大 卫 ， 给 他 进 贡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10894', '13', '18', '3', '琐 巴 王 哈 大 利 谢 ｛ 在 撒 母 耳 下 八 章 三 节 是 哈 大 底 谢 ｝ 往 幼 发 拉 底 河 去 ， 要 坚 定 自 己 的 国 权 ， 大 卫 就 攻 打 他 ， 直 到 哈 马 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10895', '13', '18', '4', '夺 了 他 的 战 车 一 千 ， 马 兵 七 千 ， 步 兵 二 万 ， 将 拉 战 车 的 马 砍 断 蹄 筋 ， 但 留 下 一 百 辆 车 的 马 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10896', '13', '18', '5', '大 马 士 革 的 亚 兰 人 来 帮 助 琐 巴 王 哈 大 利 谢 ， 大 卫 就 杀 了 亚 兰 人 二 万 二 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10897', '13', '18', '6', '于 是 大 卫 在 大 马 士 革 的 亚 兰 地 设 立 防 营 ， 亚 兰 人 就 归 服 他 ， 给 他 进 贡 。 大 卫 无 论 往 哪 里 去 ， 耶 和 华 都 使 他 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10898', '13', '18', '7', '他 夺 了 哈 大 利 谢 臣 仆 所 拿 的 金 盾 牌 带 到 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10899', '13', '18', '8', '大 卫 又 从 属 哈 大 利 谢 的 提 巴 ｛ 或 译 ： 比 他 ｝ 和 均 二 城 中 夺 取 了 许 多 的 铜 。 后 来 所 罗 门 用 此 制 造 铜 海 、 铜 柱 ， 和 一 切 的 铜 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10900', '13', '18', '9', '哈 马 王 陀 乌 听 见 大 卫 杀 败 琐 巴 王 哈 大 利 谢 的 全 军 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10901', '13', '18', '10', '就 打 发 他 儿 子 哈 多 兰 去 见 大 卫 王 ， 问 他 的 安 ， 为 他 祝 福 ， 因 为 他 杀 败 了 哈 大 利 谢 〈 原 来 陀 乌 与 哈 大 利 谢 常 常 争 战 〉 。 哈 多 兰 带 了 金 银 铜 的 各 样 器 皿 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10902', '13', '18', '11', '大 卫 王 将 这 些 器 皿 ， 并 从 各 国 夺 来 的 金 银 ， 就 是 从 以 东 、 摩 押 、 亚 扪 、 非 利 士 、 亚 玛 力 人 所 夺 来 的 ， 都 分 别 为 圣 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10903', '13', '18', '12', '洗 鲁 雅 的 儿 子 亚 比 筛 在 盐 谷 击 杀 了 以 东 一 万 八 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10904', '13', '18', '13', '大 卫 在 以 东 地 设 立 防 营 ， 以 东 人 就 都 归 服 他 。 大 卫 无 论 往 哪 里 去 ， 耶 和 华 都 使 他 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10905', '13', '18', '14', '大 卫 作 以 色 列 众 人 的 王 ， 又 向 众 民 秉 公 行 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10906', '13', '18', '15', '洗 鲁 雅 的 儿 子 约 押 作 元 帅 ； 亚 希 律 的 儿 子 约 沙 法 作 史 官 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10907', '13', '18', '16', '亚 希 突 的 儿 子 撒 督 和 亚 比 亚 他 的 儿 子 亚 希 米 勒 作 祭 司 长 ； 沙 威 沙 作 书 记 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10908', '13', '18', '17', '耶 何 耶 大 的 儿 子 比 拿 雅 统 辖 基 利 提 人 和 比 利 提 人 。 大 卫 的 众 子 都 在 王 的 左 右 作 领 袖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10909', '13', '19', '1', '＜ 大 卫 击 败 亚 扪 人 和 亚 兰 人 （ 撒 下   1 0 : 1 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10910', '13', '19', '2', '大 卫 说 ： “ 我 要 照 哈 嫩 的 父 亲 拿 辖 厚 待 我 的 恩 典 厚 待 哈 嫩 。 ” 于 是 大 卫 差 遣 使 者 为 他 丧 父 安 慰 他 。 大 卫 的 臣 仆 到 了 亚 扪 人 的 境 内 见 哈 嫩 ， 要 安 慰 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10911', '13', '19', '3', '但 亚 扪 人 的 首 领 对 哈 嫩 说 ： “ 大 卫 差 人 来 安 慰 你 ， 你 想 他 是 尊 敬 你 父 亲 吗 ？ 他 的 臣 仆 来 见 你 不 是 为 详 察 窥 探 、 倾 覆 这 地 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10912', '13', '19', '4', '哈 嫩 便 将 大 卫 臣 仆 的 胡 须 剃 去 一 半 ， 又 割 断 他 们 下 半 截 的 衣 服 ， 使 他 们 露 出 下 体 ， 打 发 他 们 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10913', '13', '19', '5', '有 人 将 臣 仆 所 遇 的 事 告 诉 大 卫 ， 他 就 差 人 去 迎 接 他 们 ， 因 为 他 们 甚 觉 羞 耻 ； 告 诉 他 们 说 ： “ 可 以 住 在 耶 利 哥 ， 等 到 胡 须 长 起 再 回 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10914', '13', '19', '6', '亚 扪 人 知 道 大 卫 憎 恶 他 们 ， 哈 嫩 和 亚 扪 人 就 打 发 人 拿 一 千 他 连 得 银 子 ， 从 美 索 不 达 米 亚 、 亚 兰 、 玛 迦 、 琐 巴 雇 战 车 和 马 兵 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10915', '13', '19', '7', '于 是 雇 了 三 万 二 千 辆 战 车 和 玛 迦 王 并 他 的 军 兵 ； 他 们 来 安 营 在 米 底 巴 前 。 亚 扪 人 也 从 他 们 的 城 里 出 来 ， 聚 集 交 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10916', '13', '19', '8', '大 卫 听 见 了 ， 就 差 派 约 押 统 带 勇 猛 的 全 军 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10917', '13', '19', '9', '亚 扪 人 出 来 在 城 门 前 摆 阵 ， 所 来 的 诸 王 另 在 郊 野 摆 阵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10918', '13', '19', '10', '约 押 看 见 敌 人 在 他 前 后 摆 阵 ， 就 从 以 色 列 军 中 挑 选 精 兵 ， 使 他 们 对 着 亚 兰 人 摆 阵 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10919', '13', '19', '11', '其 余 的 兵 交 与 他 兄 弟 亚 比 筛 ， 对 着 亚 扪 人 摆 阵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10920', '13', '19', '12', '约 押 对 亚 比 筛 说 ： “ 亚 兰 人 若 强 过 我 ， 你 就 来 帮 助 我 ； 亚 扪 人 若 强 过 你 ， 我 就 去 帮 助 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10921', '13', '19', '13', '我 们 都 当 刚 强 ， 为 本 国 的 民 和 神 的 城 邑 作 大 丈 夫 ， 愿 耶 和 华 凭 他 的 意 旨 而 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10922', '13', '19', '14', '于 是 约 押 和 跟 随 他 的 人 前 进 攻 打 亚 兰 人 ； 亚 兰 人 在 约 押 面 前 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10923', '13', '19', '15', '亚 扪 人 见 亚 兰 人 逃 跑 ， 他 们 也 在 约 押 的 兄 弟 亚 比 筛 面 前 逃 跑 进 城 。 约 押 就 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10924', '13', '19', '16', '亚 兰 人 见 自 己 被 以 色 列 人 打 败 ， 就 打 发 使 者 将 大 河 那 边 的 亚 兰 人 调 来 ， 哈 大 利 谢 的 将 军 朔 法 率 领 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10925', '13', '19', '17', '有 人 告 诉 大 卫 ， 他 就 聚 集 以 色 列 众 人 过 约 旦 河 ， 来 到 亚 兰 人 那 里 ， 迎 着 他 们 摆 阵 。 大 卫 既 摆 阵 攻 击 亚 兰 人 ， 亚 兰 人 就 与 他 打 仗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10926', '13', '19', '18', '亚 兰 人 在 以 色 列 人 面 前 逃 跑 。 大 卫 杀 了 亚 兰 七 千 辆 战 车 的 人 ， 四 万 步 兵 ， 又 杀 了 亚 兰 的 将 军 朔 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10927', '13', '19', '19', '属 哈 大 利 谢 的 诸 王 见 自 己 被 以 色 列 人 打 败 ， 就 与 大 卫 和 好 ， 归 服 他 。 于 是 亚 兰 人 不 敢 再 帮 助 亚 扪 人 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10928', '13', '20', '1', '＜ 大 卫 攻 取 拉 巴 城 （ 撒 下   1 2 : 2 6 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10929', '13', '20', '2', '大 卫 夺 了 亚 扪 人 之 王 所 戴 的 金 冠 冕 ｛ 王 ： 或 译 玛 勒 堪 。 玛 勒 堪 即 米 勒 公 ， 是 亚 扪 族 之 神 名 ｝ ， 其 上 的 金 子 重 一 他 连 得 ， 又 嵌 着 宝 石 ； 人 将 这 冠 冕 戴 在 大 卫 头 上 。 大 卫 从 城 里 夺 了 许 多 财 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10930', '13', '20', '3', '将 城 里 的 人 拉 出 来 ， 放 在 锯 下 ， 或 铁 耙 下 ， 或 铁 斧 下 ｛ 或 译 ： 强 他 们 用 锯 ， 或 用 打 粮 食 的 铁 器 ， 或 用 铁 斧 做 工 ｝ ， 大 卫 待 亚 扪 各 城 的 居 民 都 是 如 此 。 其 后 大 卫 和 众 军 都 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10931', '13', '20', '4', '＜ 与 非 利 士 巨 人 争 战 （ 撒 下   2 1 : 1 5 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10932', '13', '20', '5', '又 与 非 利 士 人 打 仗 。 睚 珥 的 儿 子 伊 勒 哈 难 杀 了 迦 特 人 歌 利 亚 的 兄 弟 拉 哈 米 ； 这 人 的 枪 杆 粗 如 织 布 的 机 轴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10933', '13', '20', '6', '又 在 迦 特 打 仗 。 那 里 有 一 个 身 量 高 大 的 人 ， 手 脚 都 是 六 指 ， 共 有 二 十 四 个 指 头 ， 他 也 是 伟 人 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10934', '13', '20', '7', '这 人 向 以 色 列 人 骂 阵 ， 大 卫 的 哥 哥 示 米 亚 的 儿 子 约 拿 单 就 杀 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10935', '13', '20', '8', '这 三 个 人 是 迦 特 伟 人 的 儿 子 ， 都 死 在 大 卫 和 他 仆 人 的 手 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10936', '13', '21', '1', '＜ 大 卫 数 点 以 色 列 民 （ 撒 下   2 4 : 1 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10937', '13', '21', '2', '大 卫 就 吩 咐 约 押 和 民 中 的 首 领 说 ： “ 你 们 去 数 点 以 色 列 人 ， 从 别 是 巴 直 到 但 ， 回 来 告 诉 我 ， 我 好 知 道 他 们 的 数 目 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10938', '13', '21', '3', '约 押 说 ： “ 愿 耶 和 华 使 他 的 百 姓 比 现 在 加 增 百 倍 。 我 主 我 王 啊 ， 他 们 不 都 是 你 的 仆 人 吗 ？ 我 主 为 何 吩 咐 行 这 事 ， 为 何 使 以 色 列 人 陷 在 罪 里 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10939', '13', '21', '4', '但 王 的 命 令 胜 过 约 押 。 约 押 就 出 去 ， 走 遍 以 色 列 地 ， 回 到 耶 路 撒 冷 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10940', '13', '21', '5', '将 百 姓 的 总 数 奏 告 大 卫 ： 以 色 列 人 拿 刀 的 有 一 百 一 十 万 ； 犹 大 人 拿 刀 的 有 四 十 七 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10941', '13', '21', '6', '惟 有 利 未 人 和 便 雅 悯 人 没 有 数 在 其 中 ， 因 为 约 押 厌 恶 王 的 这 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10942', '13', '21', '7', '神 不 喜 悦 这 数 点 百 姓 的 事 ， 便 降 灾 给 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10943', '13', '21', '8', '大 卫 祷 告 神 说 ： “ 我 行 这 事 大 有 罪 了 ！ 现 在 求 你 除 掉 仆 人 的 罪 孽 ， 因 我 所 行 的 甚 是 愚 昧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10944', '13', '21', '9', '耶 和 华 吩 咐 大 卫 的 先 见 迦 得 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10945', '13', '21', '10', '“ 你 去 告 诉 大 卫 说 ， 耶 和 华 如 此 说 ： 我 有 三 样 灾 ， 随 你 选 择 一 样 ， 我 好 降 与 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10946', '13', '21', '11', '于 是 ， 迦 得 来 见 大 卫 ， 对 他 说 ： “ 耶 和 华 如 此 说 ： ‘ 你 可 以 随 意 选 择 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10947', '13', '21', '12', '或 三 年 的 饥 荒 ； 或 败 在 你 敌 人 面 前 ， 被 敌 人 的 刀 追 杀 三 个 月 ； 或 在 你 国 中 有 耶 和 华 的 刀 ， 就 是 三 日 的 瘟 疫 ， 耶 和 华 的 使 者 在 以 色 列 的 四 境 施 行 毁 灭 。 ’ 现 在 你 要 想 一 想 ， 我 好 回 覆 那 差 我 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10948', '13', '21', '13', '大 卫 对 迦 得 说 ： “ 我 甚 为 难 。 我 愿 落 在 耶 和 华 的 手 里 ， 因 为 他 有 丰 盛 的 怜 悯 ； 我 不 愿 落 在 人 的 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10949', '13', '21', '14', '于 是 ， 耶 和 华 降 瘟 疫 与 以 色 列 人 ， 以 色 列 人 就 死 了 七 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10950', '13', '21', '15', '神 差 遣 使 者 去 灭 耶 路 撒 冷 ， 刚 要 灭 的 时 候 ， 耶 和 华 看 见 后 悔 ， 就 不 降 这 灾 了 ， 吩 咐 灭 城 的 天 使 说 ： “ 够 了 ， 住 手 吧 ！ ” 那 时 ， 耶 和 华 的 使 者 站 在 耶 布 斯 人 阿 珥 楠 的 禾 场 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10951', '13', '21', '16', '大 卫 举 目 ， 看 见 耶 和 华 的 使 者 站 在 天 地 间 ， 手 里 有 拔 出 来 的 刀 ， 伸 在 耶 路 撒 冷 以 上 。 大 卫 和 长 老 都 身 穿 麻 衣 ， 面 伏 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10952', '13', '21', '17', '大 卫 祷 告 神 说 ： “ 吩 咐 数 点 百 姓 的 不 是 我 吗 ？ 我 犯 了 罪 ， 行 了 恶 ， 但 这 群 羊 做 了 什 么 呢 ？ 愿 耶 和 华 ─ ─ 我 神 的 手 攻 击 我 和 我 的 父 家 ， 不 要 攻 击 你 的 民 ， 降 瘟 疫 与 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10953', '13', '21', '18', '耶 和 华 的 使 者 吩 咐 迦 得 去 告 诉 大 卫 ， 叫 他 上 去 ， 在 耶 布 斯 人 阿 珥 楠 的 禾 场 上 为 耶 和 华 筑 一 座 坛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10954', '13', '21', '19', '大 卫 就 照 着 迦 得 奉 耶 和 华 名 所 说 的 话 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10955', '13', '21', '20', '那 时 阿 珥 楠 正 打 麦 子 ， 回 头 看 见 天 使 ， 就 和 他 四 个 儿 子 都 藏 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10956', '13', '21', '21', '大 卫 到 了 阿 珥 楠 那 里 ， 阿 珥 楠 看 见 大 卫 ， 就 从 禾 场 上 出 去 ， 脸 伏 于 地 ， 向 他 下 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10957', '13', '21', '22', '大 卫 对 阿 珥 楠 说 ： “ 你 将 这 禾 场 与 相 连 之 地 卖 给 我 ， 我 必 给 你 足 价 ， 我 好 在 其 上 为 耶 和 华 筑 一 座 坛 ， 使 民 间 的 瘟 疫 止 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10958', '13', '21', '23', '阿 珥 楠 对 大 卫 说 ： “ 你 可 以 用 这 禾 场 ， 愿 我 主 我 王 照 你 所 喜 悦 的 去 行 。 我 也 将 牛 给 你 作 燔 祭 ， 把 打 粮 的 器 具 当 柴 烧 ， 拿 麦 子 作 素 祭 。 这 些 我 都 送 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10959', '13', '21', '24', '大 卫 王 对 阿 珥 楠 说 ： “ 不 然 ！ 我 必 要 用 足 价 向 你 买 。 我 不 用 你 的 物 献 给 耶 和 华 ， 也 不 用 白 得 之 物 献 为 燔 祭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10960', '13', '21', '25', '于 是 大 卫 为 那 块 地 平 了 六 百 舍 客 勒 金 子 给 阿 珥 楠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10961', '13', '21', '26', '大 卫 在 那 里 为 耶 和 华 筑 了 一 座 坛 ， 献 燔 祭 和 平 安 祭 ， 求 告 耶 和 华 。 耶 和 华 就 应 允 他 ， 使 火 从 天 降 在 燔 祭 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10962', '13', '21', '27', '耶 和 华 吩 咐 使 者 ， 他 就 收 刀 入 鞘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10963', '13', '21', '28', '那 时 ， 大 卫 见 耶 和 华 在 耶 布 斯 人 阿 珥 楠 的 禾 场 上 应 允 了 他 ， 就 在 那 里 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10964', '13', '21', '29', '摩 西 在 旷 野 所 造 之 耶 和 华 的 帐 幕 和 燔 祭 坛 都 在 基 遍 的 高 处 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10965', '13', '21', '30', '只 是 大 卫 不 敢 前 去 求 问 神 ， 因 为 惧 怕 耶 和 华 使 者 的 刀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10966', '13', '22', '1', '大 卫 说 ： “ 这 就 是 耶 和 华 神 的 殿 ， 为 以 色 列 人 献 燔 祭 的 坛 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10967', '13', '22', '2', '＜ 筹 备 建 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10968', '13', '22', '3', '大 卫 预 备 许 多 铁 做 门 上 的 钉 子 和 钩 子 ， 又 预 备 许 多 铜 ， 多 得 无 法 可 称 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10969', '13', '22', '4', '又 预 备 无 数 的 香 柏 木 ， 因 为 西 顿 人 和 泰 尔 人 给 大 卫 运 了 许 多 香 柏 木 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10970', '13', '22', '5', '大 卫 说 ： “ 我 儿 子 所 罗 门 还 年 幼 娇 嫩 ， 要 为 耶 和 华 建 造 的 殿 宇 必 须 高 大 辉 煌 ， 使 名 誉 荣 耀 传 遍 万 国 ； 所 以 我 要 为 殿 预 备 材 料 。 ” 于 是 ， 大 卫 在 未 死 之 先 预 备 的 材 料 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10971', '13', '22', '6', '大 卫 召 了 他 儿 子 所 罗 门 来 ， 嘱 咐 他 给 耶 和 华 ─ ─ 以 色 列 的 神 建 造 殿 宇 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10972', '13', '22', '7', '对 所 罗 门 说 ： “ 我 儿 啊 ， 我 心 里 本 想 为 耶 和 华 ─ ─ 我 神 的 名 建 造 殿 宇 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10973', '13', '22', '8', '只 是 耶 和 华 的 话 临 到 我 说 ： ‘ 你 流 了 多 人 的 血 ， 打 了 多 次 大 仗 ， 你 不 可 为 我 的 名 建 造 殿 宇 ， 因 为 你 在 我 眼 前 使 多 人 的 血 流 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10974', '13', '22', '9', '你 要 生 一 个 儿 子 ， 他 必 作 太 平 的 人 ； 我 必 使 他 安 静 ， 不 被 四 围 的 仇 敌 扰 乱 。 他 的 名 要 叫 所 罗 门 ｛ 就 是 太 平 的 意 思 ｝ 。 他 在 位 的 日 子 ， 我 必 使 以 色 列 人 平 安 康 泰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10975', '13', '22', '10', '他 必 为 我 的 名 建 造 殿 宇 。 他 要 作 我 的 子 ； 我 要 作 他 的 父 。 他 作 以 色 列 王 ； 我 必 坚 定 他 的 国 位 ， 直 到 永 远 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10976', '13', '22', '11', '我 儿 啊 ， 现 今 愿 耶 和 华 与 你 同 在 ， 使 你 亨 通 ， 照 他 指 着 你 说 的 话 ， 建 造 耶 和 华 ─ ─ 你 神 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10977', '13', '22', '12', '但 愿 耶 和 华 赐 你 聪 明 智 慧 ， 好 治 理 以 色 列 国 ， 遵 行 耶 和 华 ─ ─ 你 神 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10978', '13', '22', '13', '你 若 谨 守 遵 行 耶 和 华 藉 摩 西 吩 咐 以 色 列 的 律 例 典 章 ， 就 得 亨 通 。 你 当 刚 强 壮 胆 ， 不 要 惧 怕 ， 也 不 要 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10979', '13', '22', '14', '我 在 困 难 之 中 为 耶 和 华 的 殿 预 备 了 金 子 十 万 他 连 得 ， 银 子 一 百 万 他 连 得 ， 铜 和 铁 多 得 无 法 可 称 ； 我 也 预 备 了 木 头 、 石 头 ， 你 还 可 以 增 添 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10980', '13', '22', '15', '你 有 许 多 匠 人 ， 就 是 石 匠 、 木 匠 ， 和 一 切 能 做 各 样 工 的 巧 匠 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10981', '13', '22', '16', '并 有 无 数 的 金 银 铜 铁 。 你 当 起 来 办 事 ， 愿 耶 和 华 与 你 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10982', '13', '22', '17', '大 卫 又 吩 咐 以 色 列 的 众 首 领 帮 助 他 儿 子 所 罗 门 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10983', '13', '22', '18', '“ 耶 和 华 ─ ─ 你 们 的 神 不 是 与 你 们 同 在 吗 ？ 不 是 叫 你 们 四 围 都 平 安 吗 ？ 因 他 已 将 这 地 的 居 民 交 在 我 手 中 ， 这 地 就 在 耶 和 华 与 他 百 姓 面 前 制 伏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10984', '13', '22', '19', '现 在 你 们 应 当 立 定 心 意 ， 寻 求 耶 和 华 ─ ─ 你 们 的 神 ； 也 当 起 来 建 造 耶 和 华 神 的 圣 所 ， 好 将 耶 和 华 的 约 柜 和 供 奉 神 的 圣 器 皿 都 搬 进 为 耶 和 华 名 建 造 的 殿 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10985', '13', '23', '1', '大 卫 年 纪 老 迈 ， 日 子 满 足 ， 就 立 他 儿 子 所 罗 门 作 以 色 列 的 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10986', '13', '23', '2', '＜ 利 未 人 的 职 务 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10987', '13', '23', '3', '利 未 人 从 三 十 岁 以 外 的 都 被 数 点 ， 他 们 男 丁 的 数 目 共 有 三 万 八 千 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10988', '13', '23', '4', '其 中 有 二 万 四 千 人 管 理 耶 和 华 殿 的 事 ， 有 六 千 人 作 官 长 和 士 师 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10989', '13', '23', '5', '有 四 千 人 作 守 门 的 ， 又 有 四 千 人 用 大 卫 所 做 的 乐 器 颂 赞 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10990', '13', '23', '6', '大 卫 将 利 未 人 革 顺 、 哥 辖 、 米 拉 利 的 子 孙 分 了 班 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10991', '13', '23', '7', '革 顺 的 子 孙 有 拉 但 和 示 每 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10992', '13', '23', '8', '拉 但 的 长 子 是 耶 歇 ， 还 有 细 坦 和 约 珥 ， 共 三 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10993', '13', '23', '9', '示 每 的 儿 子 是 示 罗 密 、 哈 薛 、 哈 兰 三 人 。 这 是 拉 但 族 的 族 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10994', '13', '23', '10', '示 每 的 儿 子 是 雅 哈 、 细 拿 、 耶 乌 施 、 比 利 亚 共 四 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10995', '13', '23', '11', '雅 哈 是 长 子 ， 细 撒 是 次 子 。 但 耶 乌 施 和 比 利 亚 的 子 孙 不 多 ， 所 以 算 为 一 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10996', '13', '23', '12', '哥 辖 的 儿 子 是 暗 兰 、 以 斯 哈 、 希 伯 伦 、 乌 薛 共 四 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10997', '13', '23', '13', '暗 兰 的 儿 子 是 亚 伦 、 摩 西 。 亚 伦 和 他 的 子 孙 分 出 来 ， 好 分 别 至 圣 的 物 ， 在 耶 和 华 面 前 烧 香 、 事 奉 他 ， 奉 他 的 名 祝 福 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10998', '13', '23', '14', '至 于 神 人 摩 西 ， 他 的 子 孙 名 字 记 在 利 未 支 派 的 册 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('10999', '13', '23', '15', '摩 西 的 儿 子 是 革 舜 和 以 利 以 谢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11000', '13', '23', '16', '革 舜 的 长 子 是 细 布 业 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11001', '13', '23', '17', '以 利 以 谢 的 儿 子 是 利 哈 比 雅 。 以 利 以 谢 没 有 别 的 儿 子 ， 但 利 哈 比 雅 的 子 孙 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11002', '13', '23', '18', '以 斯 哈 的 长 子 是 示 罗 密 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11003', '13', '23', '19', '希 伯 伦 的 长 子 是 耶 利 雅 ， 次 子 是 亚 玛 利 亚 ， 三 子 是 雅 哈 悉 ， 四 子 是 耶 加 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11004', '13', '23', '20', '乌 薛 的 长 子 是 米 迦 ， 次 子 是 耶 西 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11005', '13', '23', '21', '米 拉 利 的 儿 子 是 抹 利 、 母 示 。 抹 利 的 儿 子 是 以 利 亚 撒 、 基 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11006', '13', '23', '22', '以 利 亚 撒 死 了 ， 没 有 儿 子 ， 只 有 女 儿 ， 他 们 本 族 基 士 的 儿 子 娶 了 她 们 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11007', '13', '23', '23', '母 示 的 儿 子 是 末 力 、 以 得 、 耶 利 摩 共 三 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11008', '13', '23', '24', '以 上 利 未 子 孙 作 族 长 的 ， 照 着 男 丁 的 数 目 ， 从 二 十 岁 以 外 ， 都 办 耶 和 华 殿 的 事 务 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11009', '13', '23', '25', '大 卫 说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 已 经 使 他 的 百 姓 平 安 ， 他 永 远 住 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11010', '13', '23', '26', '利 未 人 不 必 再 抬 帐 幕 和 其 中 所 用 的 一 切 器 皿 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11011', '13', '23', '27', '照 着 大 卫 临 终 所 吩 咐 的 ， 利 未 人 从 二 十 岁 以 外 的 都 被 数 点 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11012', '13', '23', '28', '他 们 的 职 任 是 服 事 亚 伦 的 子 孙 ， 在 耶 和 华 的 殿 和 院 子 ， 并 屋 中 办 事 ， 洁 净 一 切 圣 物 ， 就 是 办 神 殿 的 事 务 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11013', '13', '23', '29', '并 管 理 陈 设 饼 ， 素 祭 的 细 面 ， 或 无 酵 薄 饼 ， 或 用 盘 烤 ， 或 用 油 调 和 的 物 ， 又 管 理 各 样 的 升 斗 尺 度 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11014', '13', '23', '30', '每 日 早 晚 ， 站 立 称 谢 赞 美 耶 和 华 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11015', '13', '23', '31', '又 在 安 息 日 、 月 朔 ， 并 节 期 ， 按 数 照 例 ， 将 燔 祭 常 常 献 给 耶 和 华 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11016', '13', '23', '32', '又 看 守 会 幕 和 圣 所 ， 并 守 耶 和 华 吩 咐 他 们 弟 兄 亚 伦 子 孙 的 ， 办 耶 和 华 殿 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11017', '13', '24', '1', '＜ 祭 司 的 职 务 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11018', '13', '24', '2', '拿 答 、 亚 比 户 死 在 他 们 父 亲 之 先 ， 没 有 留 下 儿 子 ； 故 此 ， 以 利 亚 撒 、 以 他 玛 供 祭 司 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11019', '13', '24', '3', '以 利 亚 撒 的 子 孙 撒 督 和 以 他 玛 的 子 孙 亚 希 米 勒 ， 同 着 大 卫 将 他 们 的 族 弟 兄 分 成 班 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11020', '13', '24', '4', '以 利 亚 撒 子 孙 中 为 首 的 比 以 他 玛 子 孙 中 为 首 的 更 多 ， 分 班 如 下 ： 以 利 亚 撒 的 子 孙 中 有 十 六 个 族 长 ， 以 他 玛 的 子 孙 中 有 八 个 族 长 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11021', '13', '24', '5', '都 掣 签 分 立 ， 彼 此 一 样 。 在 圣 所 和 神 面 前 作 首 领 的 有 以 利 亚 撒 的 子 孙 ， 也 有 以 他 玛 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11022', '13', '24', '6', '作 书 记 的 利 未 人 拿 坦 业 的 儿 子 示 玛 雅 在 王 和 首 领 ， 与 祭 司 撒 督 、 亚 比 亚 他 的 儿 子 亚 希 米 勒 ， 并 祭 司 利 未 人 的 族 长 面 前 记 录 他 们 的 名 字 。 在 以 利 亚 撒 的 子 孙 中 取 一 族 ， 在 以 他 玛 的 子 孙 中 取 一 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11023', '13', '24', '7', '掣 签 的 时 候 ， 第 一 掣 出 来 的 是 耶 何 雅 立 ， 第 二 是 耶 大 雅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11024', '13', '24', '8', '第 三 是 哈 琳 ， 第 四 是 梭 琳 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11025', '13', '24', '9', '第 五 是 玛 基 雅 ， 第 六 是 米 雅 民 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11026', '13', '24', '10', '第 七 是 哈 歌 斯 ， 第 八 是 亚 比 雅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11027', '13', '24', '11', '第 九 是 耶 书 亚 ， 第 十 是 示 迦 尼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11028', '13', '24', '12', '第 十 一 是 以 利 亚 实 ， 第 十 二 是 雅 金 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11029', '13', '24', '13', '第 十 三 是 胡 巴 ， 第 十 四 是 耶 是 比 押 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11030', '13', '24', '14', '第 十 五 是 璧 迦 ， 第 十 六 是 音 麦 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11031', '13', '24', '15', '第 十 七 是 希 悉 ， 第 十 八 是 哈 辟 悉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11032', '13', '24', '16', '第 十 九 是 毗 他 希 雅 ， 第 二 十 是 以 西 结 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11033', '13', '24', '17', '第 二 十 一 是 雅 斤 ， 第 二 十 二 是 迦 末 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11034', '13', '24', '18', '第 二 十 三 是 第 来 雅 ， 第 二 十 四 是 玛 西 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11035', '13', '24', '19', '这 就 是 他 们 的 班 次 ， 要 照 耶 和 华 ─ ─ 以 色 列 的 神 藉 他 们 祖 宗 亚 伦 所 吩 咐 的 条 例 进 入 耶 和 华 的 殿 办 理 事 务 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11036', '13', '24', '20', '＜ 利 未 人 名 单 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11037', '13', '24', '21', '利 哈 比 雅 的 子 孙 里 有 长 子 伊 示 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11038', '13', '24', '22', '以 斯 哈 的 子 孙 里 有 示 罗 摩 ； 示 罗 摩 的 子 孙 里 有 雅 哈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11039', '13', '24', '23', '希 伯 伦 的 子 孙 里 有 长 子 耶 利 雅 ， 次 子 亚 玛 利 亚 ， 三 子 雅 哈 悉 ， 四 子 耶 加 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11040', '13', '24', '24', '乌 薛 的 子 孙 里 有 米 迦 ； 米 迦 的 子 孙 里 有 沙 密 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11041', '13', '24', '25', '米 迦 的 兄 弟 是 伊 示 雅 ； 伊 示 雅 的 子 孙 里 有 撒 迦 利 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11042', '13', '24', '26', '米 拉 利 的 儿 子 是 抹 利 、 母 示 、 雅 西 雅 ； 雅 西 雅 的 儿 子 有 比 挪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11043', '13', '24', '27', '米 拉 利 的 子 孙 里 有 雅 西 雅 的 儿 子 比 挪 、 朔 含 、 撒 刻 、 伊 比 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11044', '13', '24', '28', '抹 利 的 儿 子 是 以 利 亚 撒 ； 以 利 亚 撒 没 有 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11045', '13', '24', '29', '基 士 的 子 孙 里 有 耶 拉 篾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11046', '13', '24', '30', '母 示 的 儿 子 是 末 力 、 以 得 、 耶 利 摩 。 按 着 宗 族 这 都 是 利 未 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11047', '13', '24', '31', '他 们 在 大 卫 王 和 撒 督 ， 并 亚 希 米 勒 与 祭 司 利 未 人 的 族 长 面 前 掣 签 ， 正 如 他 们 弟 兄 亚 伦 的 子 孙 一 般 。 各 族 的 长 者 与 兄 弟 没 有 分 别 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11048', '13', '25', '1', '＜ 圣 殿 中 的 圣 乐 人 员 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11049', '13', '25', '2', '亚 萨 的 儿 子 撒 刻 、 约 瑟 、 尼 探 雅 、 亚 萨 利 拉 都 归 亚 萨 指 教 ， 遵 王 的 旨 意 唱 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11050', '13', '25', '3', '耶 杜 顿 的 儿 子 基 大 利 、 西 利 、 耶 筛 亚 、 哈 沙 比 雅 、 玛 他 提 雅 、 示 每 共 六 人 ， 都 归 他 们 父 亲 耶 杜 顿 指 教 ， 弹 琴 ， 唱 歌 ， 称 谢 ， 颂 赞 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11051', '13', '25', '4', '希 幔 的 儿 子 布 基 雅 、 玛 探 雅 、 乌 薛 、 细 布 业 、 耶 利 摩 、 哈 拿 尼 雅 、 哈 拿 尼 、 以 利 亚 他 、 基 大 利 提 、 罗 幔 提 ． 以 谢 、 约 施 比 加 沙 、 玛 罗 提 、 何 提 、 玛 哈 秀 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11052', '13', '25', '5', '这 都 是 希 幔 的 儿 子 ， 吹 角 颂 赞 。 希 幔 奉 神 之 命 作 王 的 先 见 。 神 赐 给 希 幔 十 四 个 儿 子 ， 三 个 女 儿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11053', '13', '25', '6', '都 归 他 们 父 亲 指 教 ， 在 耶 和 华 的 殿 唱 歌 、 敲 钹 、 弹 琴 、 鼓 瑟 ， 办 神 殿 的 事 务 。 亚 萨 、 耶 杜 顿 、 希 幔 都 是 王 所 命 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11054', '13', '25', '7', '他 们 和 他 们 的 弟 兄 学 习 颂 赞 耶 和 华 ； 善 于 歌 唱 的 共 有 二 百 八 十 八 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11055', '13', '25', '8', '这 些 人 无 论 大 小 ， 为 师 的 、 为 徒 的 ， 都 一 同 掣 签 分 了 班 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11056', '13', '25', '9', '掣 签 的 时 候 ， 第 一 掣 出 来 的 是 亚 萨 的 儿 子 约 瑟 。 第 二 是 基 大 利 ； 他 和 他 弟 兄 并 儿 子 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11057', '13', '25', '10', '第 三 是 撒 刻 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11058', '13', '25', '11', '第 四 是 伊 洗 利 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11059', '13', '25', '12', '第 五 是 尼 探 雅 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11060', '13', '25', '13', '第 六 是 布 基 雅 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11061', '13', '25', '14', '第 七 是 耶 萨 利 拉 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11062', '13', '25', '15', '第 八 是 耶 筛 亚 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11063', '13', '25', '16', '第 九 是 玛 探 雅 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11064', '13', '25', '17', '第 十 是 示 每 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11065', '13', '25', '18', '第 十 一 是 亚 萨 烈 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11066', '13', '25', '19', '第 十 二 是 哈 沙 比 雅 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11067', '13', '25', '20', '第 十 三 是 书 巴 业 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11068', '13', '25', '21', '第 十 四 是 玛 他 提 雅 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11069', '13', '25', '22', '第 十 五 是 耶 利 摩 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11070', '13', '25', '23', '第 十 六 是 哈 拿 尼 雅 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11071', '13', '25', '24', '第 十 七 是 约 施 比 加 沙 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11072', '13', '25', '25', '第 十 八 是 哈 拿 尼 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11073', '13', '25', '26', '第 十 九 是 玛 罗 提 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11074', '13', '25', '27', '第 二 十 是 以 利 亚 他 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11075', '13', '25', '28', '第 二 十 一 是 何 提 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11076', '13', '25', '29', '第 二 十 二 是 基 大 利 提 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11077', '13', '25', '30', '第 二 十 三 是 玛 哈 秀 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11078', '13', '25', '31', '第 二 十 四 是 罗 幔 提 ． 以 谢 ； 他 和 他 儿 子 并 弟 兄 共 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11079', '13', '26', '1', '＜ 圣 殿 的 卫 队 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11080', '13', '26', '2', '米 施 利 米 雅 的 长 子 是 撒 迦 利 亚 ， 次 子 是 耶 叠 ， 三 子 是 西 巴 第 雅 ， 四 子 是 耶 提 聂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11081', '13', '26', '3', '五 子 是 以 拦 ， 六 子 是 约 哈 难 ， 七 子 是 以 利 约 乃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11082', '13', '26', '4', '俄 别 ． 以 东 的 长 子 是 示 玛 雅 ， 次 子 是 约 萨 拔 ， 三 子 是 约 亚 ， 四 子 是 沙 甲 ， 五 子 是 拿 坦 业 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11083', '13', '26', '5', '六 子 是 亚 米 利 ， 七 子 是 以 萨 迦 ， 八 子 是 毗 乌 利 太 ， 因 为 神 赐 福 与 俄 别 ． 以 东 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11084', '13', '26', '6', '他 的 儿 子 示 玛 雅 有 几 个 儿 子 ， 都 是 大 能 的 壮 士 ， 掌 管 父 亲 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11085', '13', '26', '7', '示 玛 雅 的 儿 子 是 俄 得 尼 、 利 法 益 、 俄 备 得 、 以 利 萨 巴 。 以 利 萨 巴 的 弟 兄 是 壮 士 ， 还 有 以 利 户 和 西 玛 迦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11086', '13', '26', '8', '这 都 是 俄 别 ． 以 东 的 子 孙 ， 他 们 和 他 们 的 儿 子 并 弟 兄 ， 都 是 善 于 办 事 的 壮 士 。 俄 别 ． 以 东 的 子 孙 共 六 十 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11087', '13', '26', '9', '米 施 利 米 雅 的 儿 子 和 弟 兄 都 是 壮 士 ， 共 十 八 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11088', '13', '26', '10', '米 拉 利 子 孙 何 萨 有 几 个 儿 子 ： 长 子 是 申 利 ， 他 原 不 是 长 子 ， 是 他 父 亲 立 他 作 长 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11089', '13', '26', '11', '次 子 是 希 勒 家 ， 三 子 是 底 巴 利 雅 ， 四 子 是 撒 迦 利 亚 。 何 萨 的 儿 子 并 弟 兄 共 十 三 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11090', '13', '26', '12', '这 些 人 都 是 守 门 的 班 长 ， 与 他 们 的 弟 兄 一 同 在 耶 和 华 殿 里 按 班 供 职 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11091', '13', '26', '13', '他 们 无 论 大 小 ， 都 按 着 宗 族 掣 签 分 守 各 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11092', '13', '26', '14', '掣 签 守 东 门 的 是 示 利 米 雅 ； 他 的 儿 子 撒 迦 利 亚 是 精 明 的 谋 士 ， 掣 签 守 北 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11093', '13', '26', '15', '俄 别 ． 以 东 守 南 门 ， 他 的 儿 子 守 库 房 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11094', '13', '26', '16', '书 聘 与 何 萨 守 西 门 ， 在 靠 近 沙 利 基 门 、 通 着 往 上 去 的 街 道 上 ， 班 与 班 相 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11095', '13', '26', '17', '每 日 东 门 有 六 个 利 未 人 ， 北 门 有 四 个 ， 南 门 有 四 个 ， 库 房 有 两 个 ， 又 有 两 个 轮 班 替 换 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11096', '13', '26', '18', '在 西 面 街 道 上 有 四 个 ， 在 游 廊 上 有 两 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11097', '13', '26', '19', '以 上 是 可 拉 子 孙 和 米 拉 利 子 孙 守 门 的 班 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11098', '13', '26', '20', '＜ 其 他 职 守 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11099', '13', '26', '21', '革 顺 族 、 拉 但 子 孙 里 ， 作 族 长 的 是 革 顺 族 拉 但 的 子 孙 耶 希 伊 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11100', '13', '26', '22', '耶 希 伊 利 的 儿 子 西 坦 和 他 兄 弟 约 珥 掌 管 耶 和 华 殿 里 的 府 库 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11101', '13', '26', '23', '暗 兰 族 、 以 斯 哈 族 、 希 伯 伦 族 、 乌 泄 族 也 有 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11102', '13', '26', '24', '摩 西 的 孙 子 、 革 舜 的 儿 子 细 布 业 掌 管 府 库 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11103', '13', '26', '25', '还 有 他 的 弟 兄 以 利 以 谢 。 以 利 以 谢 的 儿 子 是 利 哈 比 雅 ； 利 哈 比 雅 的 儿 子 是 耶 筛 亚 ； 耶 筛 亚 的 儿 子 是 约 兰 ； 约 兰 的 儿 子 是 细 基 利 ； 细 基 利 的 儿 子 是 示 罗 密 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11104', '13', '26', '26', '这 示 罗 密 和 他 的 弟 兄 掌 管 府 库 的 圣 物 ， 就 是 大 卫 王 和 众 族 长 、 千 夫 长 、 百 夫 长 ， 并 军 长 所 分 别 为 圣 的 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11105', '13', '26', '27', '他 们 将 争 战 时 所 夺 的 财 物 分 别 为 圣 ， 以 备 修 造 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11106', '13', '26', '28', '先 见 撒 母 耳 、 基 士 的 儿 子 扫 罗 、 尼 珥 的 儿 子 押 尼 珥 、 洗 鲁 雅 的 儿 子 约 押 所 分 别 为 圣 的 物 都 归 示 罗 密 和 他 的 弟 兄 掌 管 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11107', '13', '26', '29', '＜ 其 余 利 未 人 的 职 守 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11108', '13', '26', '30', '希 伯 伦 族 有 哈 沙 比 雅 和 他 弟 兄 一 千 七 百 人 ， 都 是 壮 士 ， 在 约 旦 河 西 、 以 色 列 地 办 理 耶 和 华 与 王 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11109', '13', '26', '31', '希 伯 伦 族 中 有 耶 利 雅 作 族 长 。 大 卫 作 王 第 四 十 年 ， 在 基 列 的 雅 谢 ， 从 这 族 中 寻 得 大 能 的 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11110', '13', '26', '32', '耶 利 雅 的 弟 兄 有 二 千 七 百 人 ， 都 是 壮 士 ， 且 作 族 长 ； 大 卫 王 派 他 们 在 吕 便 支 派 、 迦 得 支 派 、 玛 拿 西 半 支 派 中 办 理 神 和 王 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11111', '13', '27', '1', '＜ 军 长 和 民 政 的 组 织 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11112', '13', '27', '2', '正 月 第 一 班 的 班 长 是 撒 巴 第 业 的 儿 子 雅 朔 班 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11113', '13', '27', '3', '他 是 法 勒 斯 的 子 孙 ， 统 管 正 月 班 的 一 切 军 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11114', '13', '27', '4', '二 月 的 班 长 是 亚 哈 希 人 朵 代 ， 还 有 副 官 密 基 罗 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11115', '13', '27', '5', '三 月 第 三 班 的 班 长 ｛ 原 文 是 军 长 ； 下 同 ｝ 是 祭 司 耶 何 耶 大 的 儿 子 比 拿 雅 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11116', '13', '27', '6', '这 比 拿 雅 是 那 三 十 人 中 的 勇 士 ， 管 理 那 三 十 人 ； 他 班 内 又 有 他 儿 子 暗 米 萨 拔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11117', '13', '27', '7', '四 月 第 四 班 的 班 长 是 约 押 的 兄 弟 亚 撒 黑 。 接 续 他 的 是 他 儿 子 西 巴 第 雅 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11118', '13', '27', '8', '五 月 第 五 班 的 班 长 是 伊 斯 拉 人 珊 合 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11119', '13', '27', '9', '六 月 第 六 班 的 班 长 是 提 哥 亚 人 益 吉 的 儿 子 以 拉 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11120', '13', '27', '10', '七 月 第 七 班 的 班 长 是 以 法 莲 族 比 伦 人 希 利 斯 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11121', '13', '27', '11', '八 月 第 八 班 的 班 长 是 谢 拉 族 户 沙 人 西 比 该 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11122', '13', '27', '12', '九 月 第 九 班 的 班 长 是 便 雅 悯 族 亚 拿 突 人 亚 比 以 谢 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11123', '13', '27', '13', '十 月 第 十 班 的 班 长 是 谢 拉 族 尼 陀 法 人 玛 哈 莱 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11124', '13', '27', '14', '十 一 月 第 十 一 班 的 班 长 是 以 法 莲 族 比 拉 顿 人 比 拿 雅 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11125', '13', '27', '15', '十 二 月 第 十 二 班 的 班 长 是 俄 陀 聂 族 尼 陀 法 人 黑 玳 ； 他 班 内 有 二 万 四 千 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11126', '13', '27', '16', '＜ 以 色 列 各 支 派 的 行 政 长 官 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11127', '13', '27', '17', '管 利 未 人 的 是 基 母 利 的 儿 子 哈 沙 比 雅 ； 管 亚 伦 子 孙 的 是 撒 督 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11128', '13', '27', '18', '管 犹 大 人 的 是 大 卫 的 一 个 哥 哥 以 利 户 ， 管 以 萨 迦 人 的 是 米 迦 勒 的 儿 子 暗 利 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11129', '13', '27', '19', '管 西 布 伦 人 的 是 俄 巴 第 雅 的 儿 子 伊 施 玛 雅 ； 管 拿 弗 他 利 人 的 是 亚 斯 列 的 儿 子 耶 利 摩 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11130', '13', '27', '20', '管 以 法 莲 人 的 是 阿 撒 细 雅 的 儿 子 何 细 亚 ； 管 玛 拿 西 半 支 派 的 是 毗 大 雅 的 儿 子 约 珥 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11131', '13', '27', '21', '管 基 列 地 玛 拿 西 那 半 支 派 的 是 撒 迦 利 亚 的 儿 子 易 多 ； 管 便 雅 悯 人 的 是 押 尼 珥 的 儿 子 雅 西 业 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11132', '13', '27', '22', '管 但 人 的 是 耶 罗 罕 的 儿 子 亚 萨 列 。 以 上 是 以 色 列 众 支 派 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11133', '13', '27', '23', '以 色 列 人 二 十 岁 以 内 的 ， 大 卫 没 有 记 其 数 目 ； 因 耶 和 华 曾 应 许 说 ， 必 加 增 以 色 列 人 如 天 上 的 星 那 样 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11134', '13', '27', '24', '洗 鲁 雅 的 儿 子 约 押 动 手 数 点 ， 当 时 耶 和 华 的 烈 怒 临 到 以 色 列 人 ； 因 此 ， 没 有 点 完 ， 数 目 也 没 有 写 在 大 卫 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11135', '13', '27', '25', '＜ 管 理 王 产 的 官 员 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11136', '13', '27', '26', '掌 管 耕 田 种 地 的 是 基 绿 的 儿 子 以 斯 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11137', '13', '27', '27', '掌 管 葡 萄 园 的 是 拉 玛 人 示 每 。 掌 管 葡 萄 园 酒 窖 的 是 实 弗 米 人 撒 巴 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11138', '13', '27', '28', '掌 管 高 原 橄 榄 树 和 桑 树 的 是 基 第 利 人 巴 勒 ． 哈 南 。 掌 管 油 库 的 是 约 阿 施 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11139', '13', '27', '29', '掌 管 沙 仑 牧 放 牛 群 的 是 沙 仑 人 施 提 赉 。 掌 管 山 谷 牧 养 牛 群 的 是 亚 第 赉 的 儿 子 沙 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11140', '13', '27', '30', '掌 管 驼 群 的 是 以 实 玛 利 人 阿 比 勒 。 掌 管 驴 群 的 是 米 仑 人 耶 希 底 亚 。 掌 管 羊 群 的 是 夏 甲 人 雅 悉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11141', '13', '27', '31', '这 都 是 给 大 卫 王 掌 管 产 业 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11142', '13', '27', '32', '＜ 大 卫 的 谋 士 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11143', '13', '27', '33', '亚 希 多 弗 也 作 王 的 谋 士 。 亚 基 人 户 筛 作 王 的 陪 伴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11144', '13', '27', '34', '亚 希 多 弗 之 后 ， 有 比 拿 雅 的 儿 子 耶 何 耶 大 和 亚 比 亚 他 接 续 他 作 谋 士 。 约 押 作 王 的 元 帅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11145', '13', '28', '1', '＜ 大 卫 对 建 殿 的 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11146', '13', '28', '2', '大 卫 王 就 站 起 来 ， 说 ： “ 我 的 弟 兄 ， 我 的 百 姓 啊 ， 你 们 当 听 我 言 ， 我 心 里 本 想 建 造 殿 宇 ， 安 放 耶 和 华 的 约 柜 ， 作 为 我 神 的 脚 凳 ； 我 已 经 预 备 建 造 的 材 料 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11147', '13', '28', '3', '只 是 神 对 我 说 ： ‘ 你 不 可 为 我 的 名 建 造 殿 宇 ； 因 你 是 战 士 ， 流 了 人 的 血 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11148', '13', '28', '4', '然 而 ， 耶 和 华 ─ ─ 以 色 列 的 神 在 我 父 的 全 家 拣 选 我 作 以 色 列 的 王 ， 直 到 永 远 。 因 他 拣 选 犹 大 为 首 领 ； 在 犹 大 支 派 中 拣 选 我 父 家 ， 在 我 父 的 众 子 里 喜 悦 我 ， 立 我 作 以 色 列 众 人 的 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11149', '13', '28', '5', '耶 和 华 赐 我 许 多 儿 子 ， 在 我 儿 子 中 拣 选 所 罗 门 坐 耶 和 华 的 国 位 ， 治 理 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11150', '13', '28', '6', '耶 和 华 对 我 说 ： ‘ 你 儿 子 所 罗 门 必 建 造 我 的 殿 和 院 宇 ； 因 为 我 拣 选 他 作 我 的 子 ， 我 也 必 作 他 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11151', '13', '28', '7', '他 若 恒 久 遵 行 我 的 诫 命 典 章 如 今 日 一 样 ， 我 就 必 坚 定 他 的 国 位 ， 直 到 永 远 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11152', '13', '28', '8', '现 今 在 耶 和 华 的 会 中 ， 以 色 列 众 人 眼 前 所 说 的 ， 我 们 的 神 也 听 见 了 。 你 们 应 当 寻 求 耶 和 华 ─ ─ 你 们 神 的 一 切 诫 命 ， 谨 守 遵 行 ， 如 此 你 们 可 以 承 受 这 美 地 ， 遗 留 给 你 们 的 子 孙 ， 永 远 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11153', '13', '28', '9', '“ 我 儿 所 罗 门 哪 ， 你 当 认 识 耶 和 华 ─ ─ 你 父 的 神 ， 诚 心 乐 意 地 事 奉 他 ； 因 为 他 鉴 察 众 人 的 心 ， 知 道 一 切 心 思 意 念 。 你 若 寻 求 他 ， 他 必 使 你 寻 见 ； 你 若 离 弃 他 ， 他 必 永 远 丢 弃 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11154', '13', '28', '10', '你 当 谨 慎 ， 因 耶 和 华 拣 选 你 建 造 殿 宇 作 为 圣 所 。 你 当 刚 强 去 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11155', '13', '28', '11', '大 卫 将 殿 的 游 廊 、 旁 屋 、 府 库 、 楼 房 、 内 殿 ， 和 施 恩 所 的 样 式 指 示 他 儿 子 所 罗 门 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11156', '13', '28', '12', '又 将 被 灵 感 动 所 得 的 样 式 ， 就 是 耶 和 华 神 殿 的 院 子 、 周 围 的 房 屋 、 殿 的 府 库 ， 和 圣 物 府 库 的 一 切 样 式 都 指 示 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11157', '13', '28', '13', '又 指 示 他 祭 司 和 利 未 人 的 班 次 与 耶 和 华 殿 里 各 样 的 工 作 ， 并 耶 和 华 殿 里 一 切 器 皿 的 样 式 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11158', '13', '28', '14', '以 及 各 样 应 用 金 器 的 分 两 和 各 样 应 用 银 器 的 分 两 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11159', '13', '28', '15', '金 灯 台 和 金 灯 的 分 两 ， 银 灯 台 和 银 灯 的 分 两 ， 轻 重 各 都 合 宜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11160', '13', '28', '16', '陈 设 饼 金 桌 子 的 分 两 ， 银 桌 子 的 分 两 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11161', '13', '28', '17', '精 金 的 肉 叉 子 、 盘 子 ， 和 爵 的 分 两 ， 各 金 碗 与 各 银 碗 的 分 两 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11162', '13', '28', '18', '精 金 香 坛 的 分 两 ， 并 用 金 子 做 基 路 伯 ｛ 原 文 是 用 金 子 做 车 式 的 基 路 伯 ｝ ； 基 路 伯 张 开 翅 膀 ， 遮 掩 耶 和 华 的 约 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11163', '13', '28', '19', '大 卫 说 ： “ 这 一 切 工 作 的 样 式 都 是 耶 和 华 用 手 划 出 来 使 我 明 白 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11164', '13', '28', '20', '大 卫 又 对 他 儿 子 所 罗 门 说 ： “ 你 当 刚 强 壮 胆 去 行 ！ 不 要 惧 怕 ， 也 不 要 惊 惶 。 因 为 耶 和 华 神 就 是 我 的 神 ， 与 你 同 在 ； 他 必 不 撇 下 你 ， 也 不 丢 弃 你 ， 直 到 耶 和 华 殿 的 工 作 都 完 毕 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11165', '13', '28', '21', '有 祭 司 和 利 未 人 的 各 班 ， 为 要 办 理 神 殿 各 样 的 事 ， 又 有 灵 巧 的 人 在 各 样 的 工 作 上 乐 意 帮 助 你 ； 并 有 众 首 领 和 众 民 一 心 听 从 你 的 命 令 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11166', '13', '29', '1', '＜ 为 建 殿 而 献 的 礼 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11167', '13', '29', '2', '我 为 我 神 的 殿 已 经 尽 力 ， 预 备 金 子 做 金 器 ， 银 子 做 银 器 ， 铜 做 铜 器 ， 铁 做 铁 器 ， 木 做 木 器 ， 还 有 红 玛 瑙 可 镶 嵌 的 宝 石 ， 彩 石 和 一 切 的 宝 石 ， 并 许 多 汉 白 玉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11168', '13', '29', '3', '且 因 我 心 中 爱 慕 我 神 的 殿 ， 就 在 预 备 建 造 圣 殿 的 材 料 之 外 ， 又 将 我 自 己 积 蓄 的 金 银 献 上 ， 建 造 我 神 的 殿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11169', '13', '29', '4', '就 是 俄 斐 金 三 千 他 连 得 、 精 炼 的 银 子 七 千 他 连 得 ， 以 贴 殿 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11170', '13', '29', '5', '金 子 做 金 器 ， 银 子 做 银 器 ， 并 藉 匠 人 的 手 制 造 一 切 。 今 日 有 谁 乐 意 将 自 己 献 给 耶 和 华 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11171', '13', '29', '6', '于 是 ， 众 族 长 和 以 色 列 各 支 派 的 首 领 、 千 夫 长 、 百 夫 长 ， 并 监 管 王 工 的 官 长 ， 都 乐 意 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11172', '13', '29', '7', '他 们 为 神 殿 的 使 用 献 上 金 子 五 千 他 连 得 零 一 万 达 利 克 ， 银 子 一 万 他 连 得 ， 铜 一 万 八 千 他 连 得 ， 铁 十 万 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11173', '13', '29', '8', '凡 有 宝 石 的 都 交 给 革 顺 人 耶 歇 ， 送 入 耶 和 华 殿 的 府 库 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11174', '13', '29', '9', '因 这 些 人 诚 心 乐 意 献 给 耶 和 华 ， 百 姓 就 欢 喜 ， 大 卫 王 也 大 大 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11175', '13', '29', '10', '＜ 大 卫 称 颂 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11176', '13', '29', '11', '耶 和 华 啊 ， 尊 大 、 能 力 、 荣 耀 、 强 胜 、 威 严 都 是 你 的 ； 凡 天 上 地 下 的 都 是 你 的 ； 国 度 也 是 你 的 ， 并 且 你 为 至 高 ， 为 万 有 之 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11177', '13', '29', '12', '丰 富 尊 荣 都 从 你 而 来 ， 你 也 治 理 万 物 。 在 你 手 里 有 大 能 大 力 ， 使 人 尊 大 强 盛 都 出 于 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11178', '13', '29', '13', '我 们 的 神 啊 ， 现 在 我 们 称 谢 你 ， 赞 美 你 荣 耀 之 名 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11179', '13', '29', '14', '“ 我 算 什 么 ， 我 的 民 算 什 么 ， 竟 能 如 此 乐 意 奉 献 ？ 因 为 万 物 都 从 你 而 来 ， 我 们 把 从 你 而 得 的 献 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11180', '13', '29', '15', '我 们 在 你 面 前 是 客 旅 ， 是 寄 居 的 ， 与 我 们 列 祖 一 样 。 我 们 在 世 的 日 子 如 影 儿 ， 不 能 长 存 ｛ 或 译 ： 没 有 长 存 的 指 望 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11181', '13', '29', '16', '耶 和 华 ─ ─ 我 们 的 神 啊 ， 我 们 预 备 这 许 多 材 料 ， 要 为 你 的 圣 名 建 造 殿 宇 ， 都 是 从 你 而 来 ， 都 是 属 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11182', '13', '29', '17', '我 的 神 啊 ， 我 知 道 你 察 验 人 心 ， 喜 悦 正 直 ； 我 以 正 直 的 心 乐 意 献 上 这 一 切 物 。 现 在 我 喜 欢 见 你 的 民 在 这 里 都 乐 意 奉 献 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11183', '13', '29', '18', '耶 和 华 ─ ─ 我 们 列 祖 亚 伯 拉 罕 、 以 撒 、 以 色 列 的 神 啊 ， 求 你 使 你 的 民 常 存 这 样 的 心 思 意 念 ， 坚 定 他 们 的 心 归 向 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11184', '13', '29', '19', '又 求 你 赐 我 儿 子 所 罗 门 诚 实 的 心 ， 遵 守 你 的 命 令 、 法 度 、 律 例 ， 成 就 这 一 切 的 事 ， 用 我 所 预 备 的 建 造 殿 宇 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11185', '13', '29', '20', '大 卫 对 全 会 众 说 ： “ 你 们 应 当 称 颂 耶 和 华 ─ ─ 你 们 的 神 。 ” 于 是 会 众 称 颂 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 低 头 拜 耶 和 华 与 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11186', '13', '29', '21', '次 日 ， 他 们 向 耶 和 华 献 平 安 祭 和 燔 祭 ， 就 是 献 公 牛 一 千 只 ， 公 绵 羊 一 千 只 ， 羊 羔 一 千 只 ， 并 同 献 的 奠 祭 ； 又 为 以 色 列 众 人 献 许 多 的 祭 。 那 日 ， 他 们 在 耶 和 华 面 前 吃 喝 ， 大 大 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11187', '13', '29', '22', '他 们 奉 耶 和 华 的 命 再 膏 大 卫 的 儿 子 所 罗 门 作 王 ， 又 膏 撒 督 作 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11188', '13', '29', '23', '于 是 所 罗 门 坐 在 耶 和 华 所 赐 的 位 上 ， 接 续 他 父 亲 大 卫 作 王 ， 万 事 亨 通 ； 以 色 列 众 人 也 都 听 从 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11189', '13', '29', '24', '众 首 领 和 勇 士 ， 并 大 卫 王 的 众 子 ， 都 顺 服 所 罗 门 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11190', '13', '29', '25', '耶 和 华 使 所 罗 门 在 以 色 列 众 人 眼 前 甚 为 尊 大 ， 极 其 威 严 ， 胜 过 在 他 以 前 的 以 色 列 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11191', '13', '29', '26', '＜ 大 卫 政 绩 简 述 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11192', '13', '29', '27', '作 王 共 四 十 年 ： 在 希 伯 仑 作 王 七 年 ， 在 耶 路 撒 冷 作 王 三 十 三 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11193', '13', '29', '28', '他 年 纪 老 迈 ， 日 子 满 足 ， 享 受 丰 富 、 尊 荣 ， 就 死 了 。 他 儿 子 所 罗 门 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11194', '13', '29', '29', '大 卫 王 始 终 的 事 都 写 在 先 见 撒 母 耳 的 书 上 和 先 知 拿 单 并 先 见 迦 得 的 书 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11195', '13', '29', '30', '他 的 国 事 和 他 的 勇 力 ， 以 及 他 和 以 色 列 并 列 国 所 经 过 的 事 都 写 在 这 书 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11196', '14', '1', '1', '＜ 所 罗 门 王 祈 求 智 慧 （ 王 上   3 : 1 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11197', '14', '1', '2', '所 罗 门 吩 咐 以 色 列 众 人 ， 就 是 千 夫 长 、 百 夫 长 、 审 判 官 、 首 领 与 族 长 都 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11198', '14', '1', '3', '所 罗 门 和 会 众 都 往 基 遍 的 邱 坛 去 ， 因 那 里 有 神 的 会 幕 ， 就 是 耶 和 华 仆 人 摩 西 在 旷 野 所 制 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11199', '14', '1', '4', '只 是 神 的 约 柜 ， 大 卫 已 经 从 基 列 ． 耶 琳 搬 到 他 所 预 备 的 地 方 ， 因 他 曾 在 耶 路 撒 冷 为 约 柜 支 搭 了 帐 幕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11200', '14', '1', '5', '并 且 户 珥 的 孙 子 、 乌 利 的 儿 子 比 撒 列 所 造 的 铜 坛 也 在 基 遍 耶 和 华 的 会 幕 前 。 所 罗 门 和 会 众 都 就 近 坛 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11201', '14', '1', '6', '所 罗 门 上 到 耶 和 华 面 前 会 幕 的 铜 坛 那 里 ， 献 一 千 牺 牲 为 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11202', '14', '1', '7', '当 夜 ， 神 向 所 罗 门 显 现 ， 对 他 说 ： “ 你 愿 我 赐 你 什 么 ， 你 可 以 求 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11203', '14', '1', '8', '所 罗 门 对 神 说 ： “ 你 曾 向 我 父 大 卫 大 施 慈 爱 ， 使 我 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11204', '14', '1', '9', '耶 和 华 神 啊 ， 现 在 求 你 成 就 向 我 父 大 卫 所 应 许 的 话 ； 因 你 立 我 作 这 民 的 王 ， 他 们 如 同 地 上 尘 沙 那 样 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11205', '14', '1', '10', '求 你 赐 我 智 慧 聪 明 ， 我 好 在 这 民 前 出 入 ； 不 然 ， 谁 能 判 断 这 众 多 的 民 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11206', '14', '1', '11', '神 对 所 罗 门 说 ： “ 我 已 立 你 作 我 民 的 王 。 你 既 有 这 心 意 ， 并 不 求 资 财 、 丰 富 、 尊 荣 ， 也 不 求 灭 绝 那 恨 你 之 人 的 性 命 ， 又 不 求 大 寿 数 ， 只 求 智 慧 聪 明 好 判 断 我 的 民 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11207', '14', '1', '12', '我 必 赐 你 智 慧 聪 明 ， 也 必 赐 你 资 财 、 丰 富 、 尊 荣 。 在 你 以 前 的 列 王 都 没 有 这 样 ， 在 你 以 后 也 必 没 有 这 样 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11208', '14', '1', '13', '于 是 ， 所 罗 门 从 基 遍 邱 坛 会 幕 前 回 到 耶 路 撒 冷 ， 治 理 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11209', '14', '1', '14', '＜ 所 罗 门 王 的 权 力 和 财 力 （ 王 上   1 0 : 2 6 - 2 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11210', '14', '1', '15', '王 在 耶 路 撒 冷 使 金 银 多 如 石 头 ， 香 柏 木 多 如 高 原 的 桑 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11211', '14', '1', '16', '所 罗 门 的 马 是 从 埃 及 带 来 的 ， 是 王 的 商 人 一 群 一 群 按 着 定 价 买 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11212', '14', '1', '17', '他 们 从 埃 及 买 来 的 车 ， 每 辆 价 银 六 百 舍 客 勒 ， 马 每 匹 一 百 五 十 舍 客 勒 。 赫 人 诸 王 和 亚 兰 诸 王 所 买 的 车 马 ， 也 是 按 这 价 值 经 他 们 手 买 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11213', '14', '2', '1', '＜ 筹 备 建 造 圣 殿 （ 王 上   5 : 1 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11214', '14', '2', '2', '所 罗 门 就 挑 选 七 万 扛 抬 的 ， 八 万 在 山 上 凿 石 头 的 ， 三 千 六 百 督 工 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11215', '14', '2', '3', '所 罗 门 差 人 去 见 泰 尔 王 希 兰 ， 说 ： “ 你 曾 运 香 柏 木 与 我 父 大 卫 建 宫 居 住 ， 求 你 也 这 样 待 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11216', '14', '2', '4', '我 要 为 耶 和 华 ─ ─ 我 神 的 名 建 造 殿 宇 ， 分 别 为 圣 献 给 他 ， 在 他 面 前 焚 烧 美 香 ， 常 摆 陈 设 饼 ， 每 早 晚 、 安 息 日 、 月 朔 ， 并 耶 和 华 ─ ─ 我 们 神 所 定 的 节 期 献 燔 祭 。 这 是 以 色 列 人 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11217', '14', '2', '5', '我 所 要 建 造 的 殿 宇 甚 大 ； 因 为 我 们 的 神 至 大 ， 超 乎 诸 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11218', '14', '2', '6', '天 和 天 上 的 天 ， 尚 且 不 足 他 居 住 的 ， 谁 能 为 他 建 造 殿 宇 呢 ？ 我 是 谁 ？ 能 为 他 建 造 殿 宇 吗 ？ 不 过 在 他 面 前 烧 香 而 已 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11219', '14', '2', '7', '现 在 求 你 差 一 个 巧 匠 来 ， 就 是 善 用 金 、 银 、 铜 、 铁 ， 和 紫 色 、 朱 红 色 、 蓝 色 线 ， 并 精 于 雕 刻 之 工 的 巧 匠 ， 与 我 父 大 卫 在 犹 大 和 耶 路 撒 冷 所 预 备 的 巧 匠 一 同 做 工 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11220', '14', '2', '8', '又 求 你 从 黎 巴 嫩 运 些 香 柏 木 、 松 木 、 檀 香 木 到 我 这 里 来 ， 因 我 知 道 你 的 仆 人 善 于 砍 伐 黎 巴 嫩 的 树 木 。 我 的 仆 人 也 必 与 你 的 仆 人 同 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11221', '14', '2', '9', '这 样 ， 可 以 给 我 预 备 许 多 的 木 料 ， 因 我 要 建 造 的 殿 宇 高 大 出 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11222', '14', '2', '10', '你 的 仆 人 砍 伐 树 木 ， 我 必 给 他 们 打 好 了 的 小 麦 二 万 歌 珥 ， 大 麦 二 万 歌 珥 ， 酒 二 万 罢 特 ， 油 二 万 罢 特 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11223', '14', '2', '11', '泰 尔 王 希 兰 写 信 回 答 所 罗 门 说 ： “ 耶 和 华 因 为 爱 他 的 子 民 ， 所 以 立 你 作 他 们 的 王 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11224', '14', '2', '12', '又 说 ： “ 创 造 天 地 的 耶 和 华 ─ ─ 以 色 列 的 神 是 应 当 称 颂 的 ！ 他 赐 给 大 卫 王 一 个 有 智 慧 的 儿 子 ， 使 他 有 谋 略 聪 明 ， 可 以 为 耶 和 华 建 造 殿 宇 ， 又 为 自 己 的 国 建 造 宫 室 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11225', '14', '2', '13', '“ 现 在 我 打 发 一 个 精 巧 有 聪 明 的 人 去 ， 他 是 我 父 亲 希 兰 所 用 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11226', '14', '2', '14', '是 但 支 派 一 个 妇 人 的 儿 子 。 他 父 亲 是 泰 尔 人 ， 他 善 用 金 、 银 、 铜 、 铁 、 石 、 木 ， 和 紫 色 、 蓝 色 、 朱 红 色 线 与 细 麻 制 造 各 物 ， 并 精 于 雕 刻 ， 又 能 想 出 各 样 的 巧 工 。 请 你 派 定 这 人 ， 与 你 的 巧 匠 和 你 父 ─ ─ 我 主 大 卫 的 巧 匠 一 同 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11227', '14', '2', '15', '我 主 所 说 的 小 麦 、 大 麦 、 酒 、 油 ， 愿 我 主 运 来 给 众 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11228', '14', '2', '16', '我 们 必 照 你 所 需 用 的 ， 从 黎 巴 嫩 砍 伐 树 木 ， 扎 成 筏 子 ， 浮 海 运 到 约 帕 ； 你 可 以 从 那 里 运 到 耶 路 撒 冷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11229', '14', '2', '17', '＜ 圣 殿 工 程 动 工 （ 王 上   6 : 1 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11230', '14', '2', '18', '使 七 万 人 扛 抬 材 料 ， 八 万 人 在 山 上 凿 石 头 ， 三 千 六 百 人 督 理 工 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11231', '14', '3', '1', '所 罗 门 就 在 耶 路 撒 冷 、 耶 和 华 向 他 父 大 卫 显 现 的 摩 利 亚 山 上 ， 就 是 耶 布 斯 人 阿 珥 楠 的 禾 场 上 、 大 卫 所 指 定 的 地 方 预 备 好 了 ， 开 工 建 造 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11232', '14', '3', '2', '所 罗 门 作 王 第 四 年 二 月 初 二 日 开 工 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11233', '14', '3', '3', '所 罗 门 建 筑 神 殿 的 根 基 ， 乃 是 这 样 ： 长 六 十 肘 ， 宽 二 十 肘 ， 都 按 着 古 时 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11234', '14', '3', '4', '殿 前 的 廊 子 长 二 十 肘 ， 与 殿 的 宽 窄 一 样 ， 高 一 百 二 十 肘 ； 里 面 贴 上 精 金 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11235', '14', '3', '5', '大 殿 的 墙 都 用 松 木 板 遮 蔽 ， 又 贴 了 精 金 ， 上 面 雕 刻 棕 树 和 链 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11236', '14', '3', '6', '又 用 宝 石 装 饰 殿 墙 ， 使 殿 华 美 ； 所 用 的 金 子 都 是 巴 瓦 音 的 金 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11237', '14', '3', '7', '又 用 金 子 贴 殿 和 殿 的 栋 梁 、 门 槛 、 墙 壁 、 门 扇 ； 墙 上 雕 刻 基 路 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11238', '14', '3', '8', '又 建 造 至 圣 所 ， 长 二 十 肘 ， 与 殿 的 宽 窄 一 样 ， 宽 也 是 二 十 肘 ； 贴 上 精 金 ， 共 用 金 子 六 百 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11239', '14', '3', '9', '金 钉 重 五 十 舍 客 勒 。 楼 房 都 贴 上 金 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11240', '14', '3', '10', '在 至 圣 所 按 造 像 的 法 子 造 两 个 基 路 伯 ， 用 金 子 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11241', '14', '3', '11', '两 个 基 路 伯 的 翅 膀 共 长 二 十 肘 。 这 基 路 伯 的 一 个 翅 膀 长 五 肘 ， 挨 着 殿 这 边 的 墙 ； 那 一 个 翅 膀 也 长 五 肘 ， 与 那 基 路 伯 翅 膀 相 接 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11242', '14', '3', '12', '那 基 路 伯 的 一 个 翅 膀 长 五 肘 ， 挨 着 殿 那 边 的 墙 ； 那 一 个 翅 膀 也 长 五 肘 ， 与 这 基 路 伯 的 翅 膀 相 接 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11243', '14', '3', '13', '两 个 基 路 伯 张 开 翅 膀 ， 共 长 二 十 肘 ， 面 向 外 殿 而 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11244', '14', '3', '14', '又 用 蓝 色 、 紫 色 、 朱 红 色 线 和 细 麻 织 幔 子 ， 在 其 上 绣 出 基 路 伯 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11245', '14', '3', '15', '＜ 两 根 铜 柱 （ 王 上   7 : 1 5 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11246', '14', '3', '16', '又 照 圣 所 内 链 子 的 样 式 做 链 子 ， 安 在 柱 顶 上 ； 又 做 一 百 石 榴 ， 安 在 链 子 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11247', '14', '3', '17', '将 两 根 柱 子 立 在 殿 前 ， 一 根 在 右 边 ， 一 根 在 左 边 ； 右 边 的 起 名 叫 雅 斤 ， 左 边 的 起 名 叫 波 阿 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11248', '14', '4', '1', '＜ 圣 殿 的 设 备 （ 王 上   7 : 2 3 - 5 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11249', '14', '4', '2', '又 铸 一 个 铜 海 ， 样 式 是 圆 的 ， 高 五 肘 ， 径 十 肘 ， 围 三 十 肘 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11250', '14', '4', '3', '海 周 围 有 野 瓜 ｛ 野 瓜 ： 原 文 是 牛 ｝ 的 样 式 ， 每 肘 十 瓜 ， 共 有 两 行 ， 是 铸 海 的 时 候 铸 上 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11251', '14', '4', '4', '有 十 二 只 铜 牛 驮 海 ： 三 只 向 北 ， 三 只 向 西 ， 三 只 向 南 ， 三 只 向 东 ； 海 在 牛 上 ， 牛 尾 向 内 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11252', '14', '4', '5', '海 厚 一 掌 ， 边 如 杯 边 ， 又 如 百 合 花 ， 可 容 三 千 罢 特 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11253', '14', '4', '6', '又 制 造 十 个 盆 ： 五 个 放 在 右 边 ， 五 个 放 在 左 边 ， 献 燔 祭 所 用 之 物 都 洗 在 其 内 ； 但 海 是 为 祭 司 沐 浴 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11254', '14', '4', '7', '他 又 照 所 定 的 样 式 造 十 个 金 灯 台 ， 放 在 殿 里 ： 五 个 在 右 边 ， 五 个 在 左 边 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11255', '14', '4', '8', '又 造 十 张 桌 子 放 在 殿 里 ： 五 张 在 右 边 ， 五 张 在 左 边 ； 又 造 一 百 个 金 碗 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11256', '14', '4', '9', '又 建 立 祭 司 院 和 大 院 ， 并 院 门 ， 用 铜 包 裹 门 扇 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11257', '14', '4', '10', '将 海 安 在 殿 门 的 右 边 ， 就 是 南 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11258', '14', '4', '11', '户 兰 又 造 了 盆 、 铲 、 碗 。 这 样 ， 他 为 所 罗 门 王 做 完 了 神 殿 的 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11259', '14', '4', '12', '所 造 的 就 是 ： 两 根 柱 子 和 柱 上 两 个 如 球 的 顶 ， 并 两 个 盖 柱 顶 的 网 子');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11260', '14', '4', '13', '和 四 百 石 榴 ， 安 在 两 个 网 子 上 （ 每 网 两 行 盖 着 两 个 柱 上 如 球 的 顶 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11261', '14', '4', '14', '盆 座 和 其 上 的 盆 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11262', '14', '4', '15', '海 和 海 下 的 十 二 只 牛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11263', '14', '4', '16', '盆 、 铲 子 、 肉 锸 子 ， 与 耶 和 华 殿 里 的 一 切 器 皿 ， 都 是 巧 匠 户 兰 用 光 亮 的 铜 为 所 罗 门 王 造 成 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11264', '14', '4', '17', '是 在 约 旦 平 原 疏 割 和 撒 利 但 中 间 藉 胶 泥 铸 成 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11265', '14', '4', '18', '所 罗 门 制 造 的 这 一 切 甚 多 ， 铜 的 轻 重 无 法 可 查 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11266', '14', '4', '19', '所 罗 门 又 造 神 殿 里 的 金 坛 和 陈 设 饼 的 桌 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11267', '14', '4', '20', '并 精 金 的 灯 台 和 灯 盏 ， 可 以 照 例 点 在 内 殿 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11268', '14', '4', '21', '灯 台 上 的 花 和 灯 盏 ， 并 蜡 剪 都 是 金 的 ， 且 是 纯 金 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11269', '14', '4', '22', '又 用 精 金 制 造 镊 子 、 盘 子 、 调 羹 、 火 鼎 。 至 于 殿 门 和 至 圣 所 的 门 扇 ， 并 殿 的 门 扇 ， 都 是 金 子 妆 饰 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11270', '14', '5', '1', '所 罗 门 做 完 了 耶 和 华 殿 的 一 切 工 ， 就 把 他 父 大 卫 分 别 为 圣 的 金 银 和 器 皿 都 带 来 ， 放 在 神 殿 的 府 库 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11271', '14', '5', '2', '＜ 运 约 柜 入 殿 （ 王 上   8 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11272', '14', '5', '3', '于 是 以 色 列 众 人 在 七 月 节 前 都 聚 集 到 王 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11273', '14', '5', '4', '以 色 列 众 长 老 来 到 ， 利 未 人 便 抬 起 约 柜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11274', '14', '5', '5', '祭 司 利 未 人 将 约 柜 运 上 来 ， 又 将 会 幕 和 会 幕 的 一 切 圣 器 具 都 带 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11275', '14', '5', '6', '所 罗 门 王 和 聚 集 到 他 那 里 的 以 色 列 全 会 众 都 在 约 柜 前 献 牛 羊 为 祭 ， 多 得 不 可 胜 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11276', '14', '5', '7', '祭 司 将 耶 和 华 的 约 柜 抬 进 内 殿 ， 就 是 至 圣 所 ， 放 在 两 个 基 路 伯 的 翅 膀 底 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11277', '14', '5', '8', '基 路 伯 张 着 翅 膀 在 约 柜 之 上 ， 遮 掩 约 柜 和 抬 柜 的 杠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11278', '14', '5', '9', '这 杠 甚 长 ， 杠 头 在 内 殿 前 可 以 看 见 ， 在 殿 外 却 不 能 看 见 ， 直 到 如 今 还 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11279', '14', '5', '10', '约 柜 里 惟 有 两 块 石 版 ， 就 是 以 色 列 人 出 埃 及 后 ， 耶 和 华 与 他 们 立 约 的 时 候 ， 摩 西 在 何 烈 山 所 放 的 。 除 此 以 外 ， 并 无 别 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11280', '14', '5', '11', '＜ 神 的 光 荣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11281', '14', '5', '12', '他 们 出 圣 所 的 时 候 ， 歌 唱 的 利 未 人 亚 萨 、 希 幔 、 耶 杜 顿 ， 和 他 们 的 众 子 众 弟 兄 都 穿 细 麻 布 衣 服 ， 站 在 坛 的 东 边 ， 敲 钹 、 鼓 瑟 、 弹 琴 ， 同 着 他 们 有 一 百 二 十 个 祭 司 吹 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11282', '14', '5', '13', '吹 号 的 、 歌 唱 的 都 一 齐 发 声 ， 声 合 为 一 ， 赞 美 感 谢 耶 和 华 。 吹 号 、 敲 钹 ， 用 各 种 乐 器 ， 扬 声 赞 美 耶 和 华 说 ： 耶 和 华 本 为 善 ， 他 的 慈 爱 永 远 长 存 ！ 那 时 ， 耶 和 华 的 殿 有 云 充 满 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11283', '14', '5', '14', '甚 至 祭 司 不 能 站 立 供 职 ， 因 为 耶 和 华 的 荣 光 充 满 了 神 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11284', '14', '6', '1', '＜ 所 罗 门 向 人 民 宣 告 （ 王 上   8 : 1 2 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11285', '14', '6', '2', '但 我 已 经 建 造 殿 宇 作 你 的 居 所 ， 为 你 永 远 的 住 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11286', '14', '6', '3', '王 转 脸 为 以 色 列 会 众 祝 福 ， 以 色 列 会 众 就 都 站 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11287', '14', '6', '4', '所 罗 门 说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 是 应 当 称 颂 的 ！ 因 他 亲 口 向 我 父 大 卫 所 应 许 的 ， 也 亲 手 成 就 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11288', '14', '6', '5', '他 说 ： ‘ 自 从 我 领 我 民 出 埃 及 地 以 来 ， 我 未 曾 在 以 色 列 众 支 派 中 选 择 一 城 建 造 殿 宇 为 我 名 的 居 所 ， 也 未 曾 拣 选 一 人 作 我 民 以 色 列 的 君 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11289', '14', '6', '6', '但 选 择 耶 路 撒 冷 为 我 名 的 居 所 ， 又 拣 选 大 卫 治 理 我 民 以 色 列 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11290', '14', '6', '7', '所 罗 门 说 ： “ 我 父 大 卫 曾 立 意 要 为 耶 和 华 ─ ─ 以 色 列 神 的 名 建 殿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11291', '14', '6', '8', '耶 和 华 却 对 我 父 大 卫 说 ： ‘ 你 立 意 要 为 我 的 名 建 殿 ， 这 意 思 甚 好 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11292', '14', '6', '9', '只 是 你 不 可 建 殿 ， 惟 你 所 生 的 儿 子 必 为 我 名 建 殿 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11293', '14', '6', '10', '“ 现 在 耶 和 华 成 就 了 他 所 应 许 的 话 ， 使 我 接 续 我 父 大 卫 坐 以 色 列 的 国 位 ， 是 照 耶 和 华 所 说 的 ， 又 为 耶 和 华 ─ ─ 以 色 列 神 的 名 建 造 了 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11294', '14', '6', '11', '我 将 约 柜 安 置 在 其 中 ， 柜 内 有 耶 和 华 的 约 ， 就 是 他 与 以 色 列 人 所 立 的 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11295', '14', '6', '12', '＜ 所 罗 门 的 祷 告 （ 王 上   8 : 2 2 - 5 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11296', '14', '6', '13', '（ 所 罗 门 曾 造 一 个 铜 台 ， 长 五 肘 ， 宽 五 肘 ， 高 三 肘 ， 放 在 院 中 ） 就 站 在 台 上 ， 当 着 以 色 列 的 会 众 跪 下 ， 向 天 举 手 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11297', '14', '6', '14', '说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 啊 ， 天 上 地 下 没 有 神 可 比 你 的 ！ 你 向 那 尽 心 行 在 你 面 前 的 仆 人 守 约 施 慈 爱 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11298', '14', '6', '15', '向 你 仆 人 ─ ─ 我 父 大 卫 所 应 许 的 话 现 在 应 验 了 。 你 亲 口 应 许 ， 亲 手 成 就 ， 正 如 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11299', '14', '6', '16', '耶 和 华 ─ ─ 以 色 列 的 神 啊 ， 你 所 应 许 你 仆 人 ─ ─ 我 父 大 卫 的 话 说 ： ‘ 你 的 子 孙 若 谨 慎 自 己 的 行 为 ， 遵 守 我 的 律 法 ， 像 你 在 我 面 前 所 行 的 一 样 ， 就 不 断 人 坐 以 色 列 的 国 位 。 ’ 现 在 求 你 应 验 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11300', '14', '6', '17', '耶 和 华 ─ ─ 以 色 列 的 神 啊 ， 求 你 成 就 向 你 仆 人 大 卫 所 应 许 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11301', '14', '6', '18', '“ 神 果 真 与 世 人 同 住 在 地 上 吗 ？ 看 哪 ， 天 和 天 上 的 天 尚 且 不 足 你 居 住 的 ， 何 况 我 所 建 的 这 殿 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11302', '14', '6', '19', '惟 求 耶 和 华 ─ ─ 我 的 神 垂 顾 仆 人 的 祷 告 祈 求 ， 俯 听 仆 人 在 你 面 前 的 祈 祷 呼 吁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11303', '14', '6', '20', '愿 你 昼 夜 看 顾 这 殿 ， 就 是 你 应 许 立 为 你 名 的 居 所 ； 求 你 垂 听 仆 人 向 此 处 祷 告 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11304', '14', '6', '21', '你 仆 人 和 你 民 以 色 列 向 此 处 祈 祷 的 时 候 ， 求 你 从 天 上 你 的 居 所 垂 听 ， 垂 听 而 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11305', '14', '6', '22', '“ 人 若 得 罪 邻 舍 ， 有 人 叫 他 起 誓 ， 他 来 到 这 殿 ， 在 你 的 坛 前 起 誓 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11306', '14', '6', '23', '求 你 从 天 上 垂 听 ， 判 断 你 的 仆 人 ， 定 恶 人 有 罪 ， 照 他 所 行 的 报 应 在 他 头 上 ； 定 义 人 有 理 ， 照 他 的 义 赏 赐 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11307', '14', '6', '24', '“ 你 的 民 以 色 列 若 得 罪 你 ， 败 在 仇 敌 面 前 ， 又 回 心 转 意 承 认 你 的 名 ， 在 这 殿 里 向 你 祈 求 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11308', '14', '6', '25', '求 你 从 天 上 垂 听 ， 赦 免 你 民 以 色 列 的 罪 ， 使 他 们 归 回 你 赐 给 他 们 和 他 们 列 祖 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11309', '14', '6', '26', '“ 你 的 民 因 得 罪 你 ， 你 惩 罚 他 们 ， 使 天 闭 塞 不 下 雨 ， 他 们 若 向 此 处 祷 告 ， 承 认 你 的 名 ， 离 开 他 们 的 罪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11310', '14', '6', '27', '求 你 在 天 上 垂 听 ， 赦 免 你 仆 人 和 你 民 以 色 列 的 罪 ， 将 当 行 的 善 道 指 教 他 们 ， 且 降 雨 在 你 的 地 ， 就 是 你 赐 给 你 民 为 业 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11311', '14', '6', '28', '“ 国 中 若 有 饥 荒 、 瘟 疫 、 旱 风 、 霉 烂 、 蝗 虫 、 蚂 蚱 ， 或 有 仇 敌 犯 境 ， 围 困 城 邑 ， 无 论 遭 遇 什 么 灾 祸 疾 病 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11312', '14', '6', '29', '你 的 民 以 色 列 ， 或 是 众 人 ， 或 是 一 人 ， 自 觉 灾 祸 甚 苦 ， 向 这 殿 举 手 ， 无 论 祈 求 什 么 ， 祷 告 什 么 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11313', '14', '6', '30', '求 你 从 天 上 你 的 居 所 垂 听 赦 免 。 你 是 知 道 人 心 的 ， 要 照 各 人 所 行 的 待 他 们 （ 惟 有 你 知 道 世 人 的 心 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11314', '14', '6', '31', '使 他 们 在 你 赐 给 我 们 列 祖 之 地 上 一 生 一 世 敬 畏 你 ， 遵 行 你 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11315', '14', '6', '32', '“ 论 到 不 属 你 民 以 色 列 的 外 邦 人 ， 为 你 的 大 名 和 大 能 的 手 ， 并 伸 出 来 的 膀 臂 ， 从 远 方 而 来 ， 向 这 殿 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11316', '14', '6', '33', '求 你 从 天 上 你 的 居 所 垂 听 ， 照 着 外 邦 人 所 祈 求 的 而 行 ， 使 天 下 万 民 都 认 识 你 的 名 ， 敬 畏 你 ， 像 你 的 民 以 色 列 一 样 ， 又 使 他 们 知 道 我 建 造 的 这 殿 是 称 为 你 名 下 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11317', '14', '6', '34', '“ 你 的 民 若 奉 你 的 差 遣 ， 无 论 往 何 处 去 与 仇 敌 争 战 ， 向 你 所 选 择 的 城 与 我 为 你 名 所 建 造 的 殿 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11318', '14', '6', '35', '求 你 从 天 上 垂 听 他 们 的 祷 告 祈 求 ， 使 他 们 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11319', '14', '6', '36', '“ 你 的 民 若 得 罪 你 （ 世 上 没 有 不 犯 罪 的 人 ） ， 你 向 他 们 发 怒 ， 将 他 们 交 给 仇 敌 掳 到 或 远 或 近 之 地 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11320', '14', '6', '37', '他 们 若 在 掳 到 之 地 想 起 罪 来 ， 回 心 转 意 ， 恳 求 你 说 ： ‘ 我 们 有 罪 了 ， 我 们 悖 逆 了 ， 我 们 作 恶 了 ’ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11321', '14', '6', '38', '他 们 若 在 掳 到 之 地 尽 心 尽 性 归 服 你 ， 又 向 自 己 的 地 ， 就 是 你 赐 给 他 们 列 祖 之 地 和 你 所 选 择 的 城 ， 并 我 为 你 名 所 建 造 的 殿 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11322', '14', '6', '39', '求 你 从 天 上 你 的 居 所 垂 听 你 民 的 祷 告 祈 求 ， 为 他 们 伸 冤 ， 赦 免 他 们 的 过 犯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11323', '14', '6', '40', '“ 我 的 神 啊 ， 现 在 求 你 睁 眼 看 ， 侧 耳 听 在 此 处 所 献 的 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11324', '14', '6', '41', '耶 和 华 神 啊 ， 求 你 起 来 ， 和 你 有 能 力 的 约 柜 同 入 安 息 之 所 。 耶 和 华 神 啊 ， 愿 你 的 祭 司 披 上 救 恩 ； 愿 你 的 圣 民 蒙 福 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11325', '14', '6', '42', '耶 和 华 神 啊 ， 求 你 不 要 厌 弃 你 的 受 膏 者 ， 要 记 念 向 你 仆 人 大 卫 所 施 的 慈 爱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11326', '14', '7', '1', '＜ 圣 殿 奉 献 （ 王 上   8 : 6 2 - 6 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11327', '14', '7', '2', '因 耶 和 华 的 荣 光 充 满 了 耶 和 华 殿 ， 所 以 祭 司 不 能 进 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11328', '14', '7', '3', '那 火 降 下 、 耶 和 华 的 荣 光 在 殿 上 的 时 候 ， 以 色 列 众 人 看 见 ， 就 在 铺 石 地 俯 伏 叩 拜 ， 称 谢 耶 和 华 说 ： 耶 和 华 本 为 善 ， 他 的 慈 爱 永 远 长 存 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11329', '14', '7', '4', '王 和 众 民 在 耶 和 华 面 前 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11330', '14', '7', '5', '所 罗 门 王 用 牛 二 万 二 千 ， 羊 十 二 万 献 祭 。 这 样 ， 王 和 众 民 为 神 的 殿 行 奉 献 之 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11331', '14', '7', '6', '祭 司 侍 立 ， 各 供 其 职 ； 利 未 人 也 拿 着 耶 和 华 的 乐 器 ， 就 是 大 卫 王 造 出 来 、 藉 利 未 人 颂 赞 耶 和 华 的 。 （ 他 的 慈 爱 永 远 长 存 ！ ） 祭 司 在 众 人 面 前 吹 号 ， 以 色 列 人 都 站 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11332', '14', '7', '7', '所 罗 门 因 他 所 造 的 铜 坛 容 不 下 燔 祭 、 素 祭 ， 和 脂 油 ， 便 将 耶 和 华 殿 前 院 子 当 中 分 别 为 圣 ， 在 那 里 献 燔 祭 和 平 安 祭 牲 的 脂 油 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11333', '14', '7', '8', '那 时 所 罗 门 和 以 色 列 众 人 ， 就 是 从 哈 马 口 直 到 埃 及 小 河 ， 所 有 的 以 色 列 人 都 聚 集 成 为 大 会 ， 守 节 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11334', '14', '7', '9', '第 八 日 设 立 严 肃 会 ， 行 奉 献 坛 的 礼 七 日 ， 守 节 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11335', '14', '7', '10', '七 月 二 十 三 日 ， 王 遣 散 众 民 ； 他 们 因 见 耶 和 华 向 大 卫 和 所 罗 门 与 他 民 以 色 列 所 施 的 恩 惠 ， 就 都 心 中 喜 乐 ， 各 归 各 家 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11336', '14', '7', '11', '＜ 神 再 次 向 所 罗 门 显 现 （   王 上   9 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11337', '14', '7', '12', '夜 间 耶 和 华 向 所 罗 门 显 现 ， 对 他 说 ： “ 我 已 听 了 你 的 祷 告 ， 也 选 择 这 地 方 作 为 祭 祀 我 的 殿 宇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11338', '14', '7', '13', '我 若 使 天 闭 塞 不 下 雨 ， 或 使 蝗 虫 吃 这 地 的 出 产 ， 或 使 瘟 疫 流 行 在 我 民 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11339', '14', '7', '14', '这 称 为 我 名 下 的 子 民 ， 若 是 自 卑 、 祷 告 ， 寻 求 我 的 面 ， 转 离 他 们 的 恶 行 ， 我 必 从 天 上 垂 听 ， 赦 免 他 们 的 罪 ， 医 治 他 们 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11340', '14', '7', '15', '我 必 睁 眼 看 、 侧 耳 听 在 此 处 所 献 的 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11341', '14', '7', '16', '现 在 我 已 选 择 这 殿 ， 分 别 为 圣 ， 使 我 的 名 永 在 其 中 ， 我 的 眼 、 我 的 心 也 必 常 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11342', '14', '7', '17', '你 若 在 我 面 前 效 法 你 父 大 卫 所 行 的 ， 遵 行 我 一 切 所 吩 咐 你 的 ， 谨 守 我 的 律 例 典 章 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11343', '14', '7', '18', '我 就 必 坚 固 你 的 国 位 ， 正 如 我 与 你 父 大 卫 所 立 的 约 ， 说 ： ‘ 你 的 子 孙 必 不 断 人 作 以 色 列 的 王 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11344', '14', '7', '19', '“ 倘 若 你 们 转 去 丢 弃 我 指 示 你 们 的 律 例 诫 命 ， 去 事 奉 敬 拜 别 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11345', '14', '7', '20', '我 就 必 将 以 色 列 人 从 我 赐 给 他 们 的 地 上 拔 出 根 来 ， 并 且 我 为 己 名 所 分 别 为 圣 的 殿 也 必 舍 弃 不 顾 ， 使 他 在 万 民 中 作 笑 谈 ， 被 讥 诮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11346', '14', '7', '21', '这 殿 虽 然 甚 高 ， 将 来 经 过 的 人 必 惊 讶 说 ： ‘ 耶 和 华 为 何 向 这 地 和 这 殿 如 此 行 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11347', '14', '7', '22', '人 必 回 答 说 ： ‘ 是 因 此 地 的 人 离 弃 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 就 是 领 他 们 出 埃 及 地 的 神 ， 去 亲 近 别 神 ， 敬 拜 事 奉 他 ， 所 以 耶 和 华 使 这 一 切 灾 祸 临 到 他 们 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11348', '14', '8', '1', '＜ 所 罗 门 的 成 就 （ 王 上   9 : 1 0 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11349', '14', '8', '2', '以 后 所 罗 门 重 新 修 筑 希 兰 送 给 他 的 那 些 城 邑 ， 使 以 色 列 人 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11350', '14', '8', '3', '所 罗 门 往 哈 马 琐 巴 去 ， 攻 取 了 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11351', '14', '8', '4', '所 罗 门 建 造 旷 野 里 的 达 莫 ， 又 建 造 哈 马 所 有 的 积 货 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11352', '14', '8', '5', '又 建 造 上 伯 ． 和 仑 、 下 伯 ． 和 仑 作 为 保 障 ， 都 有 墙 ， 有 门 ， 有 闩 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11353', '14', '8', '6', '又 建 造 巴 拉 和 所 有 的 积 货 城 ， 并 屯 车 辆 马 兵 的 城 ， 与 耶 路 撒 冷 、 黎 巴 嫩 ， 以 及 自 己 治 理 的 全 国 中 所 愿 意 建 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11354', '14', '8', '7', '至 于 国 中 所 剩 下 不 属 以 色 列 人 的 赫 人 、 亚 摩 利 人 、 比 利 洗 人 、 希 未 人 、 耶 布 斯 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11355', '14', '8', '8', '就 是 以 色 列 人 未 曾 灭 绝 的 ， 所 罗 门 挑 取 他 们 的 后 裔 作 服 苦 的 奴 仆 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11356', '14', '8', '9', '惟 有 以 色 列 人 ， 所 罗 门 不 使 他 们 当 奴 仆 做 工 ， 乃 是 作 他 的 战 士 、 军 长 的 统 领 、 车 兵 长 、 马 兵 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11357', '14', '8', '10', '所 罗 门 王 有 二 百 五 十 督 工 的 ， 监 管 工 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11358', '14', '8', '11', '所 罗 门 将 法 老 的 女 儿 带 出 大 卫 城 ， 上 到 为 她 建 造 的 宫 里 ； 因 所 罗 门 说 ： “ 耶 和 华 约 柜 所 到 之 处 都 为 圣 地 ， 所 以 我 的 妻 不 可 住 在 以 色 列 王 大 卫 的 宫 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11359', '14', '8', '12', '所 罗 门 在 耶 和 华 的 坛 上 ， 就 是 在 廊 子 前 他 所 筑 的 坛 上 ， 与 耶 和 华 献 燔 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11360', '14', '8', '13', '又 遵 着 摩 西 的 吩 咐 在 安 息 日 、 月 朔 ， 并 一 年 三 节 ， 就 是 除 酵 节 、 七 七 节 、 住 棚 节 ， 献 每 日 所 当 献 的 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11361', '14', '8', '14', '所 罗 门 照 着 他 父 大 卫 所 定 的 例 ， 派 定 祭 司 的 班 次 ， 使 他 们 各 供 己 事 ， 又 使 利 未 人 各 尽 其 职 ， 赞 美 耶 和 华 ， 在 祭 司 面 前 做 每 日 所 当 做 的 ； 又 派 守 门 的 按 着 班 次 看 守 各 门 ， 因 为 神 人 大 卫 是 这 样 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11362', '14', '8', '15', '王 所 吩 咐 众 祭 司 和 利 未 人 的 ， 无 论 是 管 府 库 或 办 别 的 事 ， 他 们 都 不 违 背 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11363', '14', '8', '16', '所 罗 门 建 造 耶 和 华 的 殿 ， 从 立 根 基 直 到 成 功 的 日 子 ， 工 料 俱 备 。 这 样 ， 耶 和 华 的 殿 全 然 完 毕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11364', '14', '8', '17', '那 时 ， 所 罗 门 往 以 东 地 靠 海 的 以 旬 ． 迦 别 和 以 禄 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11365', '14', '8', '18', '希 兰 差 遣 他 的 臣 仆 ， 将 船 只 和 熟 悉 泛 海 的 仆 人 送 到 所 罗 门 那 里 。 他 们 同 着 所 罗 门 的 仆 人 到 了 俄 斐 ， 得 了 四 百 五 十 他 连 得 金 子 ， 运 到 所 罗 门 王 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11366', '14', '9', '1', '＜ 示 巴 女 王 访 问 所 罗 门 （ 王 上   1 0 : 1 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11367', '14', '9', '2', '所 罗 门 将 她 所 问 的 都 答 上 了 ， 没 有 一 句 不 明 白 、 不 能 答 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11368', '14', '9', '3', '示 巴 女 王 见 所 罗 门 的 智 慧 和 他 所 建 造 的 宫 室 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11369', '14', '9', '4', '席 上 的 珍 馐 美 味 、 群 臣 分 列 而 坐 、 仆 人 两 旁 侍 立 ， 以 及 他 们 的 衣 服 装 饰 、 酒 政 ， 和 酒 政 的 衣 服 装 饰 ， 又 见 他 上 耶 和 华 殿 的 台 阶 ， 就 诧 异 得 神 不 守 舍 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11370', '14', '9', '5', '对 王 说 ： “ 我 在 本 国 里 所 听 见 论 到 你 的 事 和 你 的 智 慧 实 在 是 真 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11371', '14', '9', '6', '我 先 不 信 那 些 话 ， 及 至 我 来 亲 眼 见 了 ， 才 知 道 你 的 大 智 慧 ； 人 所 告 诉 我 的 ， 还 不 到 一 半 ； 你 的 实 迹 越 过 我 所 听 见 的 名 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11372', '14', '9', '7', '你 的 群 臣 、 你 的 仆 人 常 侍 立 在 你 面 前 听 你 智 慧 的 话 是 有 福 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11373', '14', '9', '8', '耶 和 华 ─ ─ 你 的 神 是 应 当 称 颂 的 ！ 他 喜 悦 你 ， 使 你 坐 他 的 国 位 ， 为 耶 和 华 ─ ─ 你 的 神 作 王 ； 因 为 你 的 神 爱 以 色 列 人 ， 要 永 远 坚 立 他 们 ， 所 以 立 你 作 他 们 的 王 ， 使 你 秉 公 行 义 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11374', '14', '9', '9', '于 是 示 巴 女 王 将 一 百 二 十 他 连 得 金 子 和 宝 石 ， 与 极 多 的 香 料 送 给 所 罗 门 王 ； 她 送 给 王 的 香 料 ， 以 后 再 没 有 这 样 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11375', '14', '9', '10', '希 兰 的 仆 人 和 所 罗 门 的 仆 人 从 俄 斐 运 了 金 子 来 ， 也 运 了 檀 香 木 ｛ 或 译 ： 乌 木 ； 下 同 ｝ 和 宝 石 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11376', '14', '9', '11', '王 用 檀 香 木 为 耶 和 华 殿 和 王 宫 做 台 ， 又 为 歌 唱 的 人 做 琴 瑟 ； 犹 大 地 从 来 没 有 见 过 这 样 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11377', '14', '9', '12', '所 罗 门 王 按 示 巴 女 王 所 带 来 的 ， 还 她 礼 物 ， 另 外 照 她 一 切 所 要 所 求 的 ， 都 送 给 她 。 于 是 女 王 和 她 臣 仆 转 回 本 国 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11378', '14', '9', '13', '＜ 所 罗 门 王 的 财 富 （ 王 上   1 0 : 1 4 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11379', '14', '9', '14', '另 外 还 有 商 人 所 进 的 金 子 ， 并 且 阿 拉 伯 诸 王 与 属 国 的 省 长 都 带 金 银 给 所 罗 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11380', '14', '9', '15', '所 罗 门 王 用 锤 出 来 的 金 子 打 成 挡 牌 二 百 面 ， 每 面 用 金 子 六 百 舍 客 勒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11381', '14', '9', '16', '又 用 锤 出 来 的 金 子 打 成 盾 牌 三 百 面 ， 每 面 用 金 子 三 百 舍 客 勒 ， 都 放 在 黎 巴 嫩 林 宫 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11382', '14', '9', '17', '王 用 象 牙 制 造 一 个 大 宝 座 ， 用 精 金 包 裹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11383', '14', '9', '18', '宝 座 有 六 层 台 阶 ， 又 有 金 脚 凳 ， 与 宝 座 相 连 。 宝 座 两 旁 有 扶 手 ， 靠 近 扶 手 有 两 个 狮 子 站 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11384', '14', '9', '19', '六 层 台 阶 上 有 十 二 个 狮 子 站 立 ， 每 层 有 两 个 ： 左 边 一 个 ， 右 边 一 个 ； 在 列 国 中 没 有 这 样 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11385', '14', '9', '20', '所 罗 门 王 一 切 的 饮 器 都 是 金 的 ， 黎 巴 嫩 林 宫 里 的 一 切 器 皿 都 是 精 金 的 。 所 罗 门 年 间 ， 银 子 算 不 了 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11386', '14', '9', '21', '因 为 王 的 船 只 与 希 兰 的 仆 人 一 同 往 他 施 去 ； 他 施 船 只 三 年 一 次 装 载 金 、 银 、 象 牙 、 猿 猴 、 孔 雀 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11387', '14', '9', '22', '所 罗 门 王 的 财 宝 与 智 慧 胜 过 天 下 的 列 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11388', '14', '9', '23', '普 天 下 的 王 都 求 见 所 罗 门 ， 要 听 神 赐 给 他 智 慧 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11389', '14', '9', '24', '他 们 各 带 贡 物 ， 就 是 金 器 、 银 器 、 衣 服 、 军 械 、 香 料 、 骡 马 ， 每 年 有 一 定 之 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11390', '14', '9', '25', '所 罗 门 有 套 车 的 马 四 千 棚 ， 有 马 兵 一 万 二 千 ， 安 置 在 屯 车 的 城 邑 和 耶 路 撒 冷 ， 就 是 王 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11391', '14', '9', '26', '所 罗 门 统 管 诸 王 ， 从 大 河 到 非 利 士 地 ， 直 到 埃 及 的 边 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11392', '14', '9', '27', '王 在 耶 路 撒 冷 使 银 子 多 如 石 头 ， 香 柏 木 多 如 高 原 的 桑 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11393', '14', '9', '28', '有 人 从 埃 及 和 各 国 为 所 罗 门 赶 马 群 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11394', '14', '9', '29', '＜ 所 罗 门 政 绩 简 述 （ 王 上   1 1 : 4 1 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11395', '14', '9', '30', '所 罗 门 在 耶 路 撒 冷 作 以 色 列 众 人 的 王 共 四 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11396', '14', '9', '31', '所 罗 门 与 他 列 祖 同 睡 ， 葬 在 他 父 大 卫 城 里 。 他 儿 子 罗 波 安 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11397', '14', '10', '1', '＜ 北 部 支 族 的 反 叛 （ 王 上   1 2 : 1 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11398', '14', '10', '2', '尼 八 的 儿 子 耶 罗 波 安 先 前 躲 避 所 罗 门 王 ， 逃 往 埃 及 ， 住 在 那 里 ； 他 听 见 这 事 ， 就 从 埃 及 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11399', '14', '10', '3', '以 色 列 人 打 发 人 去 请 他 ， 他 就 和 以 色 列 众 人 来 见 罗 波 安 ， 对 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11400', '14', '10', '4', '“ 你 父 亲 使 我 们 负 重 轭 做 苦 工 ， 现 在 求 你 使 我 们 做 的 苦 工 负 的 重 轭 轻 松 些 ， 我 们 就 事 奉 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11401', '14', '10', '5', '罗 波 安 对 他 们 说 ： “ 第 三 日 再 来 见 我 吧 ！ ” 民 就 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11402', '14', '10', '6', '罗 波 安 之 父 所 罗 门 在 世 的 日 子 ， 有 侍 立 在 他 面 前 的 老 年 人 ， 罗 波 安 王 和 他 们 商 议 ， 说 ： “ 你 们 给 我 出 个 什 么 主 意 ， 我 好 回 覆 这 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11403', '14', '10', '7', '老 年 人 对 他 说 ： “ 王 若 恩 待 这 民 ， 使 他 们 喜 悦 ， 用 好 话 回 覆 他 们 ， 他 们 就 永 远 作 王 的 仆 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11404', '14', '10', '8', '王 却 不 用 老 年 人 给 他 出 的 主 意 ， 就 和 那 些 与 他 一 同 长 大 、 在 他 面 前 侍 立 的 少 年 人 商 议 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11405', '14', '10', '9', '说 ： “ 这 民 对 我 说 ： ‘ 你 父 亲 使 我 们 负 重 轭 ， 求 你 使 我 们 轻 松 些 ’ ； 你 们 给 我 出 个 什 么 主 意 ， 我 好 回 覆 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11406', '14', '10', '10', '那 同 他 长 大 的 少 年 人 说 ： “ 这 民 对 王 说 ： ‘ 你 父 亲 使 我 们 负 重 轭 ， 求 你 使 我 们 轻 松 些 ’ ； 王 要 对 他 们 如 此 说 ： “ 我 的 小 拇 指 比 我 父 亲 的 腰 还 粗 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11407', '14', '10', '11', '我 父 亲 使 你 们 负 重 轭 ， 我 必 使 你 们 负 更 重 的 轭 ； 我 父 亲 用 鞭 子 责 打 你 们 ， 我 要 用 蝎 子 鞭 责 打 你 们 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11408', '14', '10', '12', '耶 罗 波 安 和 众 百 姓 遵 着 罗 波 安 王 所 说 “ 你 们 第 三 日 再 来 见 我 ” 的 那 话 ， 第 三 日 他 们 果 然 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11409', '14', '10', '13', '罗 波 安 王 用 严 厉 的 话 回 覆 他 们 ， 不 用 老 年 人 所 出 的 主 意 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11410', '14', '10', '14', '照 着 少 年 人 所 出 的 主 意 对 他 们 说 ： “ 我 父 亲 使 你 们 负 重 轭 ， 我 必 使 你 们 负 更 重 的 轭 ； 我 父 亲 用 鞭 子 责 打 你 们 ， 我 要 用 蝎 子 鞭 责 打 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11411', '14', '10', '15', '王 不 肯 依 从 百 姓 ； 这 事 乃 出 于 神 ， 为 要 应 验 耶 和 华 藉 示 罗 人 亚 希 雅 对 尼 八 儿 子 耶 罗 波 安 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11412', '14', '10', '16', '以 色 列 众 民 见 王 不 依 从 他 们 ， 就 对 王 说 ： 我 们 与 大 卫 有 什 么 分 儿 呢 ？ 与 耶 西 的 儿 子 并 没 有 关 涉 ！ 以 色 列 人 哪 ， 各 回 各 家 去 吧 ！ 大 卫 家 啊 ， 自 己 顾 自 己 吧 ！ 于 是 ， 以 色 列 众 人 都 回 自 己 家 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11413', '14', '10', '17', '惟 独 住 在 犹 大 城 邑 的 以 色 列 人 ， 罗 波 安 仍 作 他 们 的 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11414', '14', '10', '18', '罗 波 安 王 差 遣 掌 管 服 苦 之 人 的 哈 多 兰 往 以 色 列 人 那 里 去 ， 以 色 列 人 就 用 石 头 打 死 他 。 罗 波 安 王 急 忙 上 车 ， 逃 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11415', '14', '10', '19', '这 样 ， 以 色 列 人 背 叛 大 卫 家 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11416', '14', '11', '1', '＜ 示 玛 雅 的 预 言 （ 王 上   1 2 : 2 1 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11417', '14', '11', '2', '但 耶 和 华 的 话 临 到 神 人 示 玛 雅 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11418', '14', '11', '3', '“ 你 去 告 诉 所 罗 门 的 儿 子 犹 大 王 罗 波 安 和 住 犹 大 、 便 雅 悯 的 以 色 列 众 人 说 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11419', '14', '11', '4', '耶 和 华 如 此 说 ： ‘ 你 们 不 可 上 去 与 你 们 的 弟 兄 争 战 ， 各 归 各 家 去 吧 ！ 因 为 这 事 出 于 我 。 ’ ” 众 人 就 听 从 耶 和 华 的 话 归 回 ， 不 去 与 耶 罗 波 安 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11420', '14', '11', '5', '＜ 罗 波 安 修 筑 诸 城 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11421', '14', '11', '6', '为 保 障 修 筑 伯 利 恒 、 以 坦 、 提 哥 亚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11422', '14', '11', '7', '伯 ． 夙 、 梭 哥 、 亚 杜 兰 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11423', '14', '11', '8', '迦 特 、 玛 利 沙 、 西 弗 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11424', '14', '11', '9', '亚 多 莱 音 、 拉 吉 、 亚 西 加 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11425', '14', '11', '10', '琐 拉 、 亚 雅 仑 、 希 伯 仑 。 这 都 是 犹 大 和 便 雅 悯 的 坚 固 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11426', '14', '11', '11', '罗 波 安 又 坚 固 各 处 的 保 障 ， 在 其 中 安 置 军 长 ， 又 预 备 下 粮 食 、 油 、 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11427', '14', '11', '12', '他 在 各 城 里 预 备 盾 牌 和 枪 ， 且 使 城 极 其 坚 固 。 犹 大 和 便 雅 悯 都 归 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11428', '14', '11', '13', '＜ 祭 司 和 利 未 人 都 归 犹 大 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11429', '14', '11', '14', '利 未 人 撇 下 他 们 的 郊 野 和 产 业 ， 来 到 犹 大 与 耶 路 撒 冷 ， 是 因 耶 罗 波 安 和 他 的 儿 子 拒 绝 他 们 ， 不 许 他 们 供 祭 司 职 分 事 奉 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11430', '14', '11', '15', '耶 罗 波 安 为 邱 坛 、 为 鬼 魔 ｛ 原 文 是 公 山 羊 ｝ 、 为 自 己 所 铸 造 的 牛 犊 设 立 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11431', '14', '11', '16', '以 色 列 各 支 派 中 ， 凡 立 定 心 意 寻 求 耶 和 华 ─ ─ 以 色 列 神 的 ， 都 随 从 利 未 人 ， 来 到 耶 路 撒 冷 祭 祀 耶 和 华 ─ ─ 他 们 列 祖 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11432', '14', '11', '17', '这 样 ， 就 坚 固 犹 大 国 ， 使 所 罗 门 的 儿 子 罗 波 安 强 盛 三 年 ， 因 为 他 们 三 年 遵 行 大 卫 和 所 罗 门 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11433', '14', '11', '18', '＜ 罗 波 安 的 家 室 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11434', '14', '11', '19', '从 她 生 了 几 个 儿 子 ， 就 是 耶 乌 施 、 示 玛 利 雅 、 撒 罕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11435', '14', '11', '20', '后 来 又 娶 押 沙 龙 的 女 儿 玛 迦 ｛ 十 三 章 二 节 是 乌 列 的 女 儿 米 该 亚 ｝ ， 从 她 生 了 亚 比 雅 、 亚 太 、 细 撒 、 示 罗 密 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11436', '14', '11', '21', '罗 波 安 娶 十 八 个 妻 ， 立 六 十 个 妾 ， 生 二 十 八 个 儿 子 ， 六 十 个 女 儿 ； 他 却 爱 押 沙 龙 的 女 儿 玛 迦 ， 比 爱 别 的 妻 妾 更 甚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11437', '14', '11', '22', '罗 波 安 立 玛 迦 的 儿 子 亚 比 雅 作 太 子 ， 在 他 弟 兄 中 为 首 ， 因 为 想 要 立 他 接 续 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11438', '14', '11', '23', '罗 波 安 办 事 精 明 ， 使 他 众 子 分 散 在 犹 大 和 便 雅 悯 全 地 各 坚 固 城 里 ， 又 赐 他 们 许 多 粮 食 ， 为 他 们 多 寻 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11439', '14', '12', '1', '＜ 埃 及 侵 犯 犹 大 （ 王 上   1 4 : 2 5 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11440', '14', '12', '2', '罗 波 安 王 第 五 年 ， 埃 及 王 示 撒 上 来 攻 打 耶 路 撒 冷 ， 因 为 王 和 民 得 罪 了 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11441', '14', '12', '3', '示 撒 带 战 车 一 千 二 百 辆 ， 马 兵 六 万 ， 并 且 跟 从 他 出 埃 及 的 路 比 人 、 苏 基 人 ， 和 古 实 人 ， 多 得 不 可 胜 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11442', '14', '12', '4', '他 攻 取 了 犹 大 的 坚 固 城 ， 就 来 到 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11443', '14', '12', '5', '那 时 ， 犹 大 的 首 领 因 为 示 撒 就 聚 集 在 耶 路 撒 冷 。 有 先 知 示 玛 雅 去 见 罗 波 安 和 众 首 领 ， 对 他 们 说 ： “ 耶 和 华 如 此 说 ： ‘ 你 们 离 弃 了 我 ， 所 以 我 使 你 们 落 在 示 撒 手 里 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11444', '14', '12', '6', '于 是 王 和 以 色 列 的 众 首 领 都 自 卑 说 ： “ 耶 和 华 是 公 义 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11445', '14', '12', '7', '耶 和 华 见 他 们 自 卑 ， 耶 和 华 的 话 就 临 到 示 玛 雅 说 ： “ 他 们 既 自 卑 ， 我 必 不 灭 绝 他 们 ； 必 使 他 们 略 得 拯 救 ， 我 不 藉 着 示 撒 的 手 将 我 的 怒 气 倒 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11446', '14', '12', '8', '然 而 他 们 必 作 示 撒 的 仆 人 ， 好 叫 他 们 知 道 ， 服 事 我 与 服 事 外 邦 人 有 何 分 别 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11447', '14', '12', '9', '于 是 ， 埃 及 王 示 撒 上 来 攻 取 耶 路 撒 冷 ， 夺 了 耶 和 华 殿 和 王 宫 里 的 宝 物 ， 尽 都 带 走 ， 又 夺 去 所 罗 门 制 造 的 金 盾 牌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11448', '14', '12', '10', '罗 波 安 王 制 造 铜 盾 牌 代 替 那 金 盾 牌 ， 交 给 守 王 宫 门 的 护 卫 长 看 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11449', '14', '12', '11', '王 每 逢 进 耶 和 华 的 殿 ， 护 卫 兵 就 拿 这 盾 牌 ， 随 后 仍 将 盾 牌 送 回 ， 放 在 护 卫 房 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11450', '14', '12', '12', '王 自 卑 的 时 候 ， 耶 和 华 的 怒 气 就 转 消 了 ， 不 将 他 灭 尽 ， 并 且 在 犹 大 中 间 也 有 善 益 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11451', '14', '12', '13', '＜ 罗 波 安 政 绩 简 述 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11452', '14', '12', '14', '罗 波 安 行 恶 ， 因 他 不 立 定 心 意 寻 求 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11453', '14', '12', '15', '罗 波 安 所 行 的 事 ， 自 始 至 终 不 都 写 在 先 知 示 玛 雅 和 先 见 易 多 的 史 记 上 吗 ？ 罗 波 安 与 耶 罗 波 安 时 常 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11454', '14', '12', '16', '罗 波 安 与 他 列 祖 同 睡 ， 葬 在 大 卫 城 里 。 他 儿 子 亚 比 雅 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11455', '14', '13', '1', '＜ 亚 比 雅 与 耶 罗 波 安 争 战 （ 王 上   1 5 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11456', '14', '13', '2', '在 耶 路 撒 冷 作 王 三 年 。 他 母 亲 名 叫 米 该 亚 ｛ 又 作 玛 迦 ｝ ， 是 基 比 亚 人 乌 列 的 女 儿 。 亚 比 雅 常 与 耶 罗 波 安 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11457', '14', '13', '3', '有 一 次 亚 比 雅 率 领 挑 选 的 兵 四 十 万 摆 阵 ， 都 是 勇 敢 的 战 士 ； 耶 罗 波 安 也 挑 选 大 能 的 勇 士 八 十 万 ， 对 亚 比 雅 摆 阵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11458', '14', '13', '4', '亚 比 雅 站 在 以 法 莲 山 地 中 的 洗 玛 脸 山 上 ， 说 ： “ 耶 罗 波 安 和 以 色 列 众 人 哪 ， 要 听 我 说 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11459', '14', '13', '5', '耶 和 华 ─ ─ 以 色 列 的 神 曾 立 盐 约 ｛ 盐 就 是 不 废 坏 的 意 思 ｝ ， 将 以 色 列 国 永 远 赐 给 大 卫 和 他 的 子 孙 ， 你 们 不 知 道 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11460', '14', '13', '6', '无 奈 大 卫 儿 子 所 罗 门 的 臣 仆 、 尼 八 儿 子 耶 罗 波 安 起 来 背 叛 他 的 主 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11461', '14', '13', '7', '有 些 无 赖 的 匪 徒 聚 集 跟 从 他 ， 逞 强 攻 击 所 罗 门 的 儿 子 罗 波 安 ； 那 时 罗 波 安 还 幼 弱 ， 不 能 抵 挡 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11462', '14', '13', '8', '“ 现 在 你 们 有 意 抗 拒 大 卫 子 孙 手 下 所 治 耶 和 华 的 国 ， 你 们 的 人 也 甚 多 ， 你 们 那 里 又 有 耶 罗 波 安 为 你 们 所 造 当 作 神 的 金 牛 犊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11463', '14', '13', '9', '你 们 不 是 驱 逐 耶 和 华 的 祭 司 亚 伦 的 后 裔 和 利 未 人 吗 ？ 不 是 照 着 外 邦 人 的 恶 俗 为 自 己 立 祭 司 吗 ？ 无 论 何 人 牵 一 只 公 牛 犊 、 七 只 公 绵 羊 将 自 己 分 别 出 来 ， 就 可 作 虚 无 之 神 的 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11464', '14', '13', '10', '至 于 我 们 ， 耶 和 华 是 我 们 的 神 ， 我 们 并 没 有 离 弃 他 。 我 们 有 事 奉 耶 和 华 的 祭 司 ， 都 是 亚 伦 的 后 裔 ， 并 有 利 未 人 各 尽 其 职 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11465', '14', '13', '11', '每 日 早 晚 向 耶 和 华 献 燔 祭 ， 烧 美 香 ， 又 在 精 金 的 桌 子 上 摆 陈 设 饼 ； 又 有 金 灯 台 和 灯 盏 ， 每 晚 点 起 ， 因 为 我 们 遵 守 耶 和 华 ─ ─ 我 们 神 的 命 ； 惟 有 你 们 离 弃 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11466', '14', '13', '12', '率 领 我 们 的 是 神 ， 我 们 这 里 也 有 神 的 祭 司 拿 号 向 你 们 吹 出 大 声 。 以 色 列 人 哪 ， 不 要 与 耶 和 华 ─ ─ 你 们 列 祖 的 神 争 战 ， 因 你 们 必 不 能 亨 通 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11467', '14', '13', '13', '耶 罗 波 安 却 在 犹 大 人 的 后 头 设 伏 兵 。 这 样 ， 以 色 列 人 在 犹 大 人 的 前 头 ， 伏 兵 在 犹 大 人 的 后 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11468', '14', '13', '14', '犹 大 人 回 头 观 看 ， 见 前 后 都 有 敌 兵 ， 就 呼 求 耶 和 华 ， 祭 司 也 吹 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11469', '14', '13', '15', '于 是 犹 大 人 呐 喊 ； 犹 大 人 呐 喊 的 时 候 ， 神 就 使 耶 罗 波 安 和 以 色 列 众 人 败 在 亚 比 雅 与 犹 大 人 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11470', '14', '13', '16', '以 色 列 人 在 犹 大 人 面 前 逃 跑 ， 神 将 他 们 交 在 犹 大 人 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11471', '14', '13', '17', '亚 比 雅 和 他 的 军 兵 大 大 杀 戮 以 色 列 人 ， 以 色 列 人 仆 倒 死 亡 的 精 兵 有 五 十 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11472', '14', '13', '18', '那 时 ， 以 色 列 人 被 制 伏 了 ， 犹 大 人 得 胜 ， 是 因 倚 靠 耶 和 华 ─ ─ 他 们 列 祖 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11473', '14', '13', '19', '亚 比 雅 追 赶 耶 罗 波 安 ， 攻 取 了 他 的 几 座 城 ， 就 是 伯 特 利 和 属 伯 特 利 的 镇 市 ， 耶 沙 拿 和 属 耶 沙 拿 的 镇 市 ， 以 法 拉 音 或 译 ： 以 弗 伦 ） 和 属 以 法 拉 音 的 镇 市 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11474', '14', '13', '20', '亚 比 雅 在 世 的 时 候 ， 耶 罗 波 安 不 能 再 强 盛 ； 耶 和 华 攻 击 他 ， 他 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11475', '14', '13', '21', '亚 比 雅 却 渐 渐 强 盛 ， 娶 妻 妾 十 四 个 ， 生 了 二 十 二 个 儿 子 ， 十 六 个 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11476', '14', '13', '22', '亚 比 雅 其 余 的 事 和 他 的 言 行 都 写 在 先 知 易 多 的 传 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11477', '14', '14', '1', '＜ 亚 撒 王 击 败 古 实 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11478', '14', '14', '2', '亚 撒 行 耶 和 华 ─ ─ 他 神 眼 中 看 为 善 为 正 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11479', '14', '14', '3', '除 掉 外 邦 神 的 坛 和 邱 坛 ， 打 碎 柱 像 ， 砍 下 木 偶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11480', '14', '14', '4', '吩 咐 犹 大 人 寻 求 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 遵 行 他 的 律 法 、 诫 命 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11481', '14', '14', '5', '又 在 犹 大 各 城 邑 除 掉 邱 坛 和 日 像 ， 那 时 国 享 太 平 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11482', '14', '14', '6', '又 在 犹 大 建 造 了 几 座 坚 固 城 。 国 中 太 平 数 年 ， 没 有 战 争 ， 因 为 耶 和 华 赐 他 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11483', '14', '14', '7', '他 对 犹 大 人 说 ： “ 我 们 要 建 造 这 些 城 邑 ， 四 围 筑 墙 ， 盖 楼 ， 安 门 ， 做 闩 ； 地 还 属 我 们 ， 是 因 寻 求 耶 和 华 ─ ─ 我 们 的 神 ； 我 们 既 寻 求 他 ， 他 就 赐 我 们 四 境 平 安 。 ” 于 是 建 造 城 邑 ， 诸 事 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11484', '14', '14', '8', '亚 撒 的 军 兵 ， 出 自 犹 大 拿 盾 牌 拿 枪 的 三 十 万 人 ； 出 自 便 雅 悯 拿 盾 牌 拉 弓 的 二 十 八 万 人 。 这 都 是 大 能 的 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11485', '14', '14', '9', '有 古 实 王 谢 拉 率 领 军 兵 一 百 万 ， 战 车 三 百 辆 ， 出 来 攻 击 犹 大 人 ， 到 了 玛 利 沙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11486', '14', '14', '10', '于 是 亚 撒 出 去 与 他 迎 敌 ， 就 在 玛 利 沙 的 洗 法 谷 彼 此 摆 阵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11487', '14', '14', '11', '亚 撒 呼 求 耶 和 华 ─ ─ 他 的 神 说 ： “ 耶 和 华 啊 ， 惟 有 你 能 帮 助 软 弱 的 ， 胜 过 强 盛 的 。 耶 和 华 ─ ─ 我 们 的 神 啊 ， 求 你 帮 助 我 们 ； 因 为 我 们 仰 赖 你 ， 奉 你 的 名 来 攻 击 这 大 军 。 耶 和 华 啊 ， 你 是 我 们 的 神 ， 不 要 容 人 胜 过 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11488', '14', '14', '12', '于 是 耶 和 华 使 古 实 人 败 在 亚 撒 和 犹 大 人 面 前 ， 古 实 人 就 逃 跑 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11489', '14', '14', '13', '亚 撒 和 跟 随 他 的 军 兵 追 赶 他 们 ， 直 到 基 拉 耳 。 古 实 人 被 杀 的 甚 多 ， 不 能 再 强 盛 ， 因 为 败 在 耶 和 华 与 他 军 兵 面 前 。 犹 大 人 就 夺 了 许 多 财 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11490', '14', '14', '14', '又 打 破 基 拉 耳 四 围 的 城 邑 ； 耶 和 华 使 其 中 的 人 都 甚 恐 惧 。 犹 大 人 又 将 所 有 的 城 掳 掠 一 空 ， 因 其 中 的 财 物 甚 多 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11491', '14', '14', '15', '又 毁 坏 了 群 畜 的 圈 ， 夺 取 许 多 的 羊 和 骆 驼 ， 就 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11492', '14', '15', '1', '＜ 亚 撒 的 改 革 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11493', '14', '15', '2', '他 出 来 迎 接 亚 撒 ， 对 他 说 ： “ 亚 撒 和 犹 大 、 便 雅 悯 众 人 哪 ， 要 听 我 说 ： 你 们 若 顺 从 耶 和 华 ， 耶 和 华 必 与 你 们 同 在 ； 你 们 若 寻 求 他 ， 就 必 寻 见 ； 你 们 若 离 弃 他 ， 他 必 离 弃 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11494', '14', '15', '3', '以 色 列 人 不 信 真 神 ， 没 有 训 诲 的 祭 司 ， 也 没 有 律 法 ， 已 经 好 久 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11495', '14', '15', '4', '但 他 们 在 急 难 的 时 候 归 向 耶 和 华 ─ ─ 以 色 列 的 神 ， 寻 求 他 ， 他 就 被 他 们 寻 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11496', '14', '15', '5', '那 时 ， 出 入 的 人 不 得 平 安 ， 列 国 的 居 民 都 遭 大 乱 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11497', '14', '15', '6', '这 国 攻 击 那 国 ， 这 城 攻 击 那 城 ， 互 相 破 坏 ， 因 为 神 用 各 样 灾 难 扰 乱 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11498', '14', '15', '7', '现 在 你 们 要 刚 强 ， 不 要 手 软 ， 因 你 们 所 行 的 必 得 赏 赐 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11499', '14', '15', '8', '亚 撒 听 见 这 话 和 俄 德 儿 子 先 知 亚 撒 利 雅 的 预 言 ， 就 壮 起 胆 来 ， 在 犹 大 、 便 雅 悯 全 地 ， 并 以 法 莲 山 地 所 夺 的 各 城 ， 将 可 憎 之 物 尽 都 除 掉 ， 又 在 耶 和 华 殿 的 廊 前 重 新 修 筑 耶 和 华 的 坛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11500', '14', '15', '9', '又 招 聚 犹 大 、 便 雅 悯 的 众 人 ， 并 他 们 中 间 寄 居 的 以 法 莲 人 、 玛 拿 西 人 、 西 缅 人 。 有 许 多 以 色 列 人 归 降 亚 撒 ， 因 见 耶 和 华 ─ ─ 他 的 神 与 他 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11501', '14', '15', '10', '亚 撒 十 五 年 三 月 ， 他 们 都 聚 集 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11502', '14', '15', '11', '当 日 他 们 从 所 取 的 掳 物 中 ， 将 牛 七 百 只 、 羊 七 千 只 献 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11503', '14', '15', '12', '他 们 就 立 约 ， 要 尽 心 尽 性 地 寻 求 耶 和 华 ─ ─ 他 们 列 祖 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11504', '14', '15', '13', '凡 不 寻 求 耶 和 华 ─ ─ 以 色 列 神 的 ， 无 论 大 小 、 男 女 ， 必 被 治 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11505', '14', '15', '14', '他 们 就 大 声 欢 呼 ， 吹 号 吹 角 ， 向 耶 和 华 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11506', '14', '15', '15', '犹 大 众 人 为 所 起 的 誓 欢 喜 ； 因 他 们 是 尽 心 起 誓 ， 尽 意 寻 求 耶 和 华 ， 耶 和 华 就 被 他 们 寻 见 ， 且 赐 他 们 四 境 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11507', '14', '15', '16', '亚 撒 王 贬 了 他 祖 母 玛 迦 太 后 的 位 ， 因 她 造 了 可 憎 的 偶 像 亚 舍 拉 。 亚 撒 砍 下 她 的 偶 像 ， 捣 得 粉 碎 ， 烧 在 汲 沦 溪 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11508', '14', '15', '17', '只 是 邱 坛 还 没 有 从 以 色 列 中 废 去 ， 然 而 亚 撒 的 心 一 生 诚 实 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11509', '14', '15', '18', '亚 撒 将 他 父 所 分 别 为 圣 、 与 自 己 所 分 别 为 圣 的 金 银 和 器 皿 都 奉 到 神 的 殿 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11510', '14', '15', '19', '从 这 时 直 到 亚 撒 三 十 五 年 ， 都 没 有 争 战 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11511', '14', '16', '1', '＜ 犹 大 与 以 色 列 争 战 （ 王 上   1 5 : 1 7 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11512', '14', '16', '2', '于 是 亚 撒 从 耶 和 华 殿 和 王 宫 的 府 库 里 拿 出 金 银 来 ， 送 与 住 大 马 士 革 的 亚 兰 王 便 ． 哈 达 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11513', '14', '16', '3', '“ 你 父 曾 与 我 父 立 约 ， 我 与 你 也 要 立 约 。 现 在 我 将 金 银 送 给 你 ， 求 你 废 掉 你 与 以 色 列 王 巴 沙 所 立 的 约 ， 使 他 离 开 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11514', '14', '16', '4', '便 ． 哈 达 听 从 亚 撒 王 的 话 ， 派 军 长 去 攻 击 以 色 列 的 城 邑 。 他 们 就 攻 破 以 云 、 但 、 亚 伯 。 玛 音 ， 和 拿 弗 他 利 一 切 的 积 货 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11515', '14', '16', '5', '巴 沙 听 见 就 停 工 ， 不 修 筑 拉 玛 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11516', '14', '16', '6', '于 是 亚 撒 王 率 领 犹 大 众 人 ， 将 巴 沙 修 筑 拉 玛 所 用 的 石 头 、 木 头 都 运 去 ， 用 以 修 筑 迦 巴 和 米 斯 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11517', '14', '16', '7', '＜ 先 知 哈 拿 尼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11518', '14', '16', '8', '古 实 人 、 路 比 人 的 军 队 不 是 甚 大 吗 ？ 战 车 马 兵 不 是 极 多 吗 ？ 只 因 你 仰 赖 耶 和 华 ， 他 便 将 他 们 交 在 你 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11519', '14', '16', '9', '耶 和 华 的 眼 目 遍 察 全 地 ， 要 显 大 能 帮 助 向 他 心 存 诚 实 的 人 。 你 这 事 行 得 愚 昧 ； 此 后 ， 你 必 有 争 战 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11520', '14', '16', '10', '亚 撒 因 此 恼 恨 先 见 ， 将 他 囚 在 监 里 。 那 时 亚 撒 也 虐 待 一 些 人 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11521', '14', '16', '11', '＜ 亚 撒 逝 世 （ 代 上   1 5 : 2 3 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11522', '14', '16', '12', '亚 撒 作 王 三 十 九 年 ， 他 脚 上 有 病 ， 而 且 甚 重 。 病 的 时 候 没 有 求 耶 和 华 ， 只 求 医 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11523', '14', '16', '13', '他 作 王 四 十 一 年 而 死 ， 与 他 列 祖 同 睡 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11524', '14', '16', '14', '葬 在 大 卫 城 自 己 所 凿 的 坟 墓 里 ， 放 在 床 上 ， 其 床 堆 满 各 样 馨 香 的 香 料 ， 就 是 按 做 香 的 作 法 调 和 的 香 料 ， 又 为 他 烧 了 许 多 的 物 件 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11525', '14', '17', '1', '＜ 犹 大 国 的 王 约 沙 法 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11526', '14', '17', '2', '安 置 军 兵 在 犹 大 一 切 坚 固 城 里 ， 又 安 置 防 兵 在 犹 大 地 和 他 父 亚 撒 所 得 以 法 莲 的 城 邑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11527', '14', '17', '3', '耶 和 华 与 约 沙 法 同 在 ； 因 为 他 行 他 祖 大 卫 初 行 的 道 ， 不 寻 求 巴 力 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11528', '14', '17', '4', '只 寻 求 他 父 亲 的 神 ， 遵 行 他 的 诫 命 ， 不 效 法 以 色 列 人 的 行 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11529', '14', '17', '5', '所 以 耶 和 华 坚 定 他 的 国 ， 犹 大 众 人 给 他 进 贡 ； 约 沙 法 大 有 尊 荣 资 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11530', '14', '17', '6', '他 高 兴 遵 行 耶 和 华 的 道 ， 并 且 从 犹 大 除 掉 一 切 邱 坛 和 木 偶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11531', '14', '17', '7', '他 作 王 第 三 年 ， 就 差 遣 臣 子 便 。 亥 伊 勒 、 俄 巴 底 、 撒 迦 利 雅 、 拿 坦 业 、 米 该 亚 往 犹 大 各 城 去 教 训 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11532', '14', '17', '8', '同 着 他 们 有 利 未 人 示 玛 雅 、 尼 探 雅 、 西 巴 第 雅 、 亚 撒 黑 、 示 米 拉 末 、 约 拿 单 、 亚 多 尼 雅 、 多 比 雅 、 驼 。 巴 多 尼 雅 ， 又 有 祭 司 以 利 沙 玛 、 约 兰 同 着 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11533', '14', '17', '9', '他 们 带 着 耶 和 华 的 律 法 书 ， 走 遍 犹 大 各 城 教 训 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11534', '14', '17', '10', '＜ 约 沙 法 的 功 绩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11535', '14', '17', '11', '有 些 非 利 士 人 与 约 沙 法 送 礼 物 ， 纳 贡 银 。 阿 拉 伯 人 也 送 他 公 绵 羊 七 千 七 百 只 ， 公 山 羊 七 千 七 百 只 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11536', '14', '17', '12', '约 沙 法 日 渐 强 大 ， 在 犹 大 建 造 营 寨 和 积 货 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11537', '14', '17', '13', '他 在 犹 大 城 邑 中 有 许 多 工 程 ， 又 在 耶 路 撒 冷 有 战 士 ， 就 是 大 能 的 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11538', '14', '17', '14', '他 们 的 数 目 ， 按 着 宗 族 ， 记 在 下 面 ： 犹 大 族 的 千 夫 长 押 拿 为 首 率 领 大 能 的 勇 士 ─ ─ 三 十 万 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11539', '14', '17', '15', '其 次 是 ， 千 夫 长 约 哈 难 率 领 大 能 的 勇 士 ─ ─ 二 十 八 万 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11540', '14', '17', '16', '其 次 是 ， 细 基 利 的 儿 子 亚 玛 斯 雅 （ 他 为 耶 和 华 牺 牲 自 己 ） 率 领 大 能 的 勇 士 ─ ─ 二 十 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11541', '14', '17', '17', '便 雅 悯 族 ， 是 大 能 的 勇 士 以 利 雅 大 率 领 拿 弓 箭 和 盾 牌 的 ─ ─ 二 十 万 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11542', '14', '17', '18', '其 次 是 ， 约 萨 拔 率 领 预 备 打 仗 的 ─ ─ 十 八 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11543', '14', '17', '19', '这 都 是 伺 候 王 的 ， 还 有 王 在 犹 大 全 地 坚 固 城 所 安 置 的 不 在 其 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11544', '14', '18', '1', '＜ 先 知 米 该 雅 警 告 亚 哈 王 （ 王 上   2 2 : 1 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11545', '14', '18', '2', '过 了 几 年 ， 他 下 到 撒 马 利 亚 去 见 亚 哈 ； 亚 哈 为 他 和 跟 从 他 的 人 宰 了 许 多 牛 羊 ， 劝 他 与 自 己 同 去 攻 取 基 列 的 拉 末 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11546', '14', '18', '3', '以 色 列 王 亚 哈 问 犹 大 王 约 沙 法 说 ： “ 你 肯 同 我 去 攻 取 基 列 的 拉 末 吗 ？ ” 他 回 答 说 ： “ 你 我 不 分 彼 此 ， 我 的 民 与 你 的 民 一 样 ， 必 与 你 同 去 争 战 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11547', '14', '18', '4', '约 沙 法 对 以 色 列 王 说 ： “ 请 你 先 求 问 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11548', '14', '18', '5', '于 是 以 色 列 王 招 聚 先 知 四 百 人 ， 问 他 们 说 ： “ 我 们 上 去 攻 取 基 列 的 拉 末 可 以 不 可 以 ？ ” 他 们 说 ： “ 可 以 上 去 ， 因 为 神 必 将 那 城 交 在 王 的 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11549', '14', '18', '6', '约 沙 法 说 ： “ 这 里 不 是 还 有 耶 和 华 的 先 知 ， 我 们 可 以 求 问 他 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11550', '14', '18', '7', '以 色 列 王 对 约 沙 法 说 ： “ 还 有 一 个 人 ， 是 音 拉 的 儿 子 米 该 雅 。 我 们 可 以 托 他 求 问 耶 和 华 ， 只 是 我 恨 他 ； 因 为 他 指 着 我 所 说 的 预 言 ， 不 说 吉 语 ， 常 说 凶 言 。 ” 约 沙 法 说 ： “ 王 不 必 这 样 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11551', '14', '18', '8', '以 色 列 王 就 召 了 一 个 太 监 来 ， 说 ： “ 你 快 去 将 音 拉 的 儿 子 米 该 雅 召 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11552', '14', '18', '9', '以 色 列 王 和 犹 大 王 约 沙 法 在 撒 马 利 亚 城 门 前 的 空 场 上 ， 各 穿 朝 服 坐 在 位 上 ， 所 有 的 先 知 都 在 他 们 面 前 说 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11553', '14', '18', '10', '基 拿 拿 的 儿 子 西 底 家 造 了 两 个 铁 角 ， 说 ： “ 耶 和 华 如 此 说 ： ‘ 你 要 用 这 角 抵 触 亚 兰 人 ， 直 到 将 他 们 灭 尽 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11554', '14', '18', '11', '所 有 的 先 知 也 都 这 样 预 言 说 ： “ 可 以 上 基 列 的 拉 末 去 ， 必 然 得 胜 ， 因 为 耶 和 华 必 将 那 城 交 在 王 的 手 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11555', '14', '18', '12', '那 去 召 米 该 雅 的 使 者 对 米 该 雅 说 ： “ 众 先 知 一 口 同 音 地 都 向 王 说 吉 言 ， 你 不 如 与 他 们 说 一 样 的 话 ， 也 说 吉 言 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11556', '14', '18', '13', '米 该 雅 说 ： “ 我 指 着 永 生 的 耶 和 华 起 誓 ， 我 的 神 说 什 么 ， 我 就 说 什 么 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11557', '14', '18', '14', '米 该 雅 到 王 面 前 ， 王 问 他 说 ： “ 米 该 雅 啊 ， 我 们 上 去 攻 取 基 列 的 拉 末 可 以 不 可 以 ？ ” 他 说 ： “ 可 以 上 去 ， 必 然 得 胜 ， 敌 人 必 交 在 你 们 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11558', '14', '18', '15', '王 对 他 说 ： “ 我 当 嘱 咐 你 几 次 ， 你 才 奉 耶 和 华 的 名 向 我 说 实 话 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11559', '14', '18', '16', '米 该 雅 说 ： “ 我 看 见 以 色 列 众 民 散 在 山 上 ， 如 同 没 有 牧 人 的 羊 群 一 般 。 耶 和 华 说 ： ‘ 这 民 没 有 主 人 ， 他 们 可 以 平 平 安 安 地 各 归 各 家 去 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11560', '14', '18', '17', '以 色 列 王 对 约 沙 法 说 ： “ 我 岂 没 有 告 诉 你 ， 这 人 指 着 我 所 说 的 预 言 ， 不 说 吉 语 ， 单 说 凶 言 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11561', '14', '18', '18', '米 该 雅 说 ： “ 你 们 要 听 耶 和 华 的 话 。 我 看 见 耶 和 华 坐 在 宝 座 上 ， 天 上 的 万 军 侍 立 在 他 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11562', '14', '18', '19', '耶 和 华 说 ： ‘ 谁 去 引 诱 以 色 列 王 亚 哈 上 基 列 的 拉 末 去 阵 亡 呢 ？ ’ 这 个 就 这 样 说 ， 那 个 就 那 样 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11563', '14', '18', '20', '随 后 ， 有 一 个 神 灵 出 来 ， 站 在 耶 和 华 面 前 说 ： ‘ 我 去 引 诱 他 。 ’ 耶 和 华 问 他 说 ： ‘ 你 用 何 法 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11564', '14', '18', '21', '他 说 ： ‘ 我 去 ， 要 在 他 众 先 知 口 中 作 谎 言 的 灵 。 ’ 耶 和 华 说 ： ‘ 这 样 ， 你 必 能 引 诱 他 ， 你 去 如 此 行 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11565', '14', '18', '22', '现 在 耶 和 华 使 谎 言 的 灵 入 了 你 这 些 先 知 的 口 ， 并 且 耶 和 华 已 经 命 定 降 祸 与 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11566', '14', '18', '23', '基 拿 拿 的 儿 子 西 底 家 前 来 打 米 该 雅 的 脸 ， 说 ： “ 耶 和 华 的 灵 从 哪 里 离 开 我 与 你 说 话 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11567', '14', '18', '24', '米 该 雅 说 ： “ 你 进 严 密 的 屋 子 藏 躲 的 那 日 ， 就 必 看 见 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11568', '14', '18', '25', '以 色 列 王 说 ： “ 将 米 该 雅 带 回 ， 交 给 邑 宰 亚 们 和 王 的 儿 子 约 阿 施 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11569', '14', '18', '26', '‘ 王 如 此 说 ： 把 这 个 人 下 在 监 里 ， 使 他 受 苦 ， 吃 不 饱 喝 不 足 ， 等 候 我 平 平 安 安 地 回 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11570', '14', '18', '27', '米 该 雅 说 ： “ 你 若 能 平 安 回 来 ， 那 就 是 耶 和 华 没 有 藉 我 说 这 话 了 ” ； 又 说 ： “ 众 民 哪 ， 你 们 都 要 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11571', '14', '18', '28', '＜ 亚 哈 阵 亡 （ 王 上   2 2 : 2 9 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11572', '14', '18', '29', '以 色 列 王 对 约 沙 法 说 ： “ 我 要 改 装 上 阵 ， 你 可 以 仍 穿 王 服 。 ” 于 是 以 色 列 王 改 装 ， 他 们 就 上 阵 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11573', '14', '18', '30', '先 是 亚 兰 王 吩 咐 车 兵 长 说 ： “ 他 们 的 兵 将 ， 无 论 大 小 ， 你 们 都 不 可 与 他 们 争 战 ， 只 要 与 以 色 列 王 争 战 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11574', '14', '18', '31', '车 兵 长 看 见 约 沙 法 便 说 ， 这 必 是 以 色 列 王 ， 就 转 过 去 与 他 争 战 。 约 沙 法 一 呼 喊 ， 耶 和 华 就 帮 助 他 ， 神 又 感 动 他 们 离 开 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11575', '14', '18', '32', '车 兵 长 见 不 是 以 色 列 王 ， 就 转 去 不 追 他 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11576', '14', '18', '33', '有 一 人 随 便 开 弓 ， 恰 巧 射 入 以 色 列 王 的 甲 缝 里 。 王 对 赶 车 的 说 ： “ 我 受 了 重 伤 ， 你 转 过 车 来 ， 拉 我 出 阵 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11577', '14', '18', '34', '那 日 阵 势 越 战 越 猛 ， 以 色 列 王 勉 强 站 在 车 上 抵 挡 亚 兰 人 ， 直 到 晚 上 。 约 在 日 落 的 时 候 ， 王 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11578', '14', '19', '1', '＜ 先 知 斥 责 约 沙 法 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11579', '14', '19', '2', '先 见 哈 拿 尼 的 儿 子 耶 户 出 来 迎 接 约 沙 法 王 ， 对 他 说 ： “ 你 岂 当 帮 助 恶 人 ， 爱 那 恨 恶 耶 和 华 的 人 呢 ？ 因 此 耶 和 华 的 忿 怒 临 到 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11580', '14', '19', '3', '然 而 你 还 有 善 行 ， 因 你 从 国 中 除 掉 木 偶 ， 立 定 心 意 寻 求 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11581', '14', '19', '4', '＜ 约 沙 法 的 改 革 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11582', '14', '19', '5', '又 在 犹 大 国 中 遍 地 的 坚 固 城 里 设 立 审 判 官 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11583', '14', '19', '6', '对 他 们 说 ： “ 你 们 办 事 应 当 谨 慎 ； 因 为 你 们 判 断 不 是 为 人 ， 乃 是 为 耶 和 华 。 判 断 的 时 候 ， 他 必 与 你 们 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11584', '14', '19', '7', '现 在 你 们 应 当 敬 畏 耶 和 华 ， 谨 慎 办 事 ； 因 为 耶 和 华 ─ ─ 我 们 的 神 没 有 不 义 ， 不 偏 待 人 ， 也 不 受 贿 赂 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11585', '14', '19', '8', '约 沙 法 从 利 未 人 和 祭 司 ， 并 以 色 列 族 长 中 派 定 人 ， 在 耶 路 撒 冷 为 耶 和 华 判 断 ， 听 民 间 的 争 讼 ， 就 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11586', '14', '19', '9', '约 沙 法 嘱 咐 他 们 说 ： “ 你 们 当 敬 畏 耶 和 华 ， 忠 心 诚 实 办 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11587', '14', '19', '10', '住 在 各 城 里 你 们 的 弟 兄 ， 若 有 争 讼 的 事 来 到 你 们 这 里 ， 或 为 流 血 ， 或 犯 律 法 、 诫 命 、 律 例 、 典 章 ， 你 们 要 警 戒 他 们 ， 免 得 他 们 得 罪 耶 和 华 ， 以 致 他 的 忿 怒 临 到 你 们 和 你 们 的 弟 兄 ； 这 样 行 ， 你 们 就 没 有 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11588', '14', '19', '11', '凡 属 耶 和 华 的 事 ， 有 大 祭 司 亚 玛 利 雅 管 理 你 们 ； 凡 属 王 的 事 ， 有 犹 大 支 派 的 族 长 以 实 玛 利 的 儿 子 西 巴 第 雅 管 理 你 们 ； 在 你 们 面 前 有 利 未 人 作 官 长 。 你 们 应 当 壮 胆 办 事 ， 愿 耶 和 华 与 善 人 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11589', '14', '20', '1', '＜ 与 以 东 交 战 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11590', '14', '20', '2', '有 人 来 报 告 约 沙 法 说 ： “ 从 海 外 亚 兰 ｛ 又 作 以 东 ｝ 那 边 有 大 军 来 攻 击 你 ， 如 今 他 们 在 哈 洗 逊 ． 他 玛 ， 就 是 隐 ． 基 底 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11591', '14', '20', '3', '约 沙 法 便 惧 怕 ， 定 意 寻 求 耶 和 华 ， 在 犹 大 全 地 宣 告 禁 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11592', '14', '20', '4', '于 是 犹 大 人 聚 会 ， 求 耶 和 华 帮 助 。 犹 大 各 城 都 有 人 出 来 寻 求 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11593', '14', '20', '5', '约 沙 法 就 在 犹 大 和 耶 路 撒 冷 的 会 中 ， 站 在 耶 和 华 殿 的 新 院 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11594', '14', '20', '6', '说 ： “ 耶 和 华 ─ ─ 我 们 列 祖 的 神 啊 ， 你 不 是 天 上 的 神 吗 ？ 你 不 是 万 邦 万 国 的 主 宰 吗 ？ 在 你 手 中 有 大 能 大 力 ， 无 人 能 抵 挡 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11595', '14', '20', '7', '我 们 的 神 啊 ， 你 不 是 曾 在 你 民 以 色 列 人 面 前 驱 逐 这 地 的 居 民 ， 将 这 地 赐 给 你 朋 友 亚 伯 拉 罕 的 后 裔 永 远 为 业 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11596', '14', '20', '8', '他 们 住 在 这 地 ， 又 为 你 的 名 建 造 圣 所 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11597', '14', '20', '9', '‘ 倘 有 祸 患 临 到 我 们 ， 或 刀 兵 灾 殃 ， 或 瘟 疫 饥 荒 ， 我 们 在 急 难 的 时 候 ， 站 在 这 殿 前 向 你 呼 求 ， 你 必 垂 听 而 拯 救 ， 因 为 你 的 名 在 这 殿 里 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11598', '14', '20', '10', '从 前 以 色 列 人 出 埃 及 地 的 时 候 ， 你 不 容 以 色 列 人 侵 犯 亚 扪 人 、 摩 押 人 ， 和 西 珥 山 人 ， 以 色 列 人 就 离 开 他 们 ， 不 灭 绝 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11599', '14', '20', '11', '看 哪 ， 他 们 怎 样 报 复 我 们 ， 要 来 驱 逐 我 们 出 离 你 的 地 ， 就 是 你 赐 给 我 们 为 业 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11600', '14', '20', '12', '我 们 的 神 啊 ， 你 不 惩 罚 他 们 吗 ？ 因 为 我 们 无 力 抵 挡 这 来 攻 击 我 们 的 大 军 ， 我 们 也 不 知 道 怎 样 行 ， 我 们 的 眼 目 单 仰 望 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11601', '14', '20', '13', '犹 大 众 人 和 他 们 的 婴 孩 、 妻 子 、 儿 女 都 站 在 耶 和 华 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11602', '14', '20', '14', '那 时 ， 耶 和 华 的 灵 在 会 中 临 到 利 未 人 亚 萨 的 后 裔 ─ ─ 玛 探 雅 的 玄 孙 ， 耶 利 的 曾 孙 ， 比 拿 雅 的 孙 子 ， 撒 迦 利 雅 的 儿 子 雅 哈 悉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11603', '14', '20', '15', '他 说 ： “ 犹 大 众 人 、 耶 路 撒 冷 的 居 民 ， 和 约 沙 法 王 ， 你 们 请 听 。 耶 和 华 对 你 们 如 此 说 ： ‘ 不 要 因 这 大 军 恐 惧 惊 惶 ； 因 为 胜 败 不 在 乎 你 们 ， 乃 在 乎 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11604', '14', '20', '16', '明 日 你 们 要 下 去 迎 敌 ， 他 们 是 从 洗 斯 坡 上 来 ， 你 们 必 在 耶 鲁 伊 勒 旷 野 前 的 谷 口 遇 见 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11605', '14', '20', '17', '犹 大 和 耶 路 撒 冷 人 哪 ， 这 次 你 们 不 要 争 战 ， 要 摆 阵 站 着 ， 看 耶 和 华 为 你 们 施 行 拯 救 。 不 要 恐 惧 ， 也 不 要 惊 惶 。 明 日 当 出 去 迎 敌 ， 因 为 耶 和 华 与 你 们 同 在 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11606', '14', '20', '18', '约 沙 法 就 面 伏 于 地 ， 犹 大 众 人 和 耶 路 撒 冷 的 居 民 也 俯 伏 在 耶 和 华 面 前 ， 叩 拜 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11607', '14', '20', '19', '哥 辖 族 和 可 拉 族 的 利 未 人 都 起 来 ， 用 极 大 的 声 音 赞 美 耶 和 华 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11608', '14', '20', '20', '次 日 清 早 ， 众 人 起 来 往 提 哥 亚 的 旷 野 去 。 出 去 的 时 候 ， 约 沙 法 站 着 说 ： “ 犹 大 人 和 耶 路 撒 冷 的 居 民 哪 ， 要 听 我 说 ： 信 耶 和 华 ─ ─ 你 们 的 神 就 必 立 稳 ； 信 他 的 先 知 就 必 亨 通 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11609', '14', '20', '21', '约 沙 法 既 与 民 商 议 了 ， 就 设 立 歌 唱 的 人 ， 颂 赞 耶 和 华 ， 使 他 们 穿 上 圣 洁 的 礼 服 ， 走 在 军 前 赞 美 耶 和 华 说 ： “ 当 称 谢 耶 和 华 ， 因 他 的 慈 爱 永 远 长 存 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11610', '14', '20', '22', '众 人 方 唱 歌 赞 美 的 时 候 ， 耶 和 华 就 派 伏 兵 击 杀 那 来 攻 击 犹 大 人 的 亚 扪 人 、 摩 押 人 ， 和 西 珥 山 人 ， 他 们 就 被 打 败 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11611', '14', '20', '23', '因 为 亚 扪 人 和 摩 押 人 起 来 ， 击 杀 住 西 珥 山 的 人 ， 将 他 们 灭 尽 ； 灭 尽 住 西 珥 山 的 人 之 后 ， 他 们 又 彼 此 自 相 击 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11612', '14', '20', '24', '犹 大 人 来 到 旷 野 的 望 楼 ， 向 那 大 军 观 看 ， 见 尸 横 遍 地 ， 没 有 一 个 逃 脱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11613', '14', '20', '25', '约 沙 法 和 他 的 百 姓 就 来 收 取 敌 人 的 财 物 ， 在 尸 首 中 见 了 许 多 财 物 、 珍 宝 ， 他 们 剥 脱 下 来 的 多 得 不 可 携 带 ； 因 为 甚 多 ， 直 收 取 了 三 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11614', '14', '20', '26', '第 四 日 众 人 聚 集 在 比 拉 迦 谷 ｛ 就 是 称 颂 的 意 思 ｝ ， 在 那 里 称 颂 耶 和 华 。 因 此 那 地 方 名 叫 比 拉 迦 谷 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11615', '14', '20', '27', '犹 大 人 和 耶 路 撒 冷 人 都 欢 欢 喜 喜 地 回 耶 路 撒 冷 ， 约 沙 法 率 领 他 们 ； 因 为 耶 和 华 使 他 们 战 胜 仇 敌 ， 就 欢 喜 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11616', '14', '20', '28', '他 们 弹 琴 、 鼓 瑟 、 吹 号 来 到 耶 路 撒 冷 ， 进 了 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11617', '14', '20', '29', '列 邦 诸 国 听 见 耶 和 华 战 败 以 色 列 的 仇 敌 ， 就 甚 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11618', '14', '20', '30', '这 样 ， 约 沙 法 的 国 得 享 太 平 ， 因 为 神 赐 他 四 境 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11619', '14', '20', '31', '＜ 约 沙 法 逝 世 （ 王 上   2 2 : 4 1 - 5 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11620', '14', '20', '32', '约 沙 法 效 法 他 父 亚 撒 所 行 的 ， 不 偏 左 右 ， 行 耶 和 华 眼 中 看 为 正 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11621', '14', '20', '33', '只 是 邱 坛 还 没 有 废 去 ， 百 姓 也 没 有 立 定 心 意 归 向 他 们 列 祖 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11622', '14', '20', '34', '约 沙 法 其 余 的 事 ， 自 始 至 终 都 写 在 哈 拿 尼 的 儿 子 耶 户 的 书 上 ， 也 载 入 以 色 列 诸 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11623', '14', '20', '35', '此 后 ， 犹 大 王 约 沙 法 与 以 色 列 王 亚 哈 谢 交 好 ； 亚 哈 谢 行 恶 太 甚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11624', '14', '20', '36', '二 王 合 伙 造 船 要 往 他 施 去 ， 遂 在 以 旬 ． 迦 别 造 船 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11625', '14', '20', '37', '那 时 玛 利 沙 人 、 多 大 瓦 的 儿 子 以 利 以 谢 向 约 沙 法 预 言 说 ： “ 因 你 与 亚 哈 谢 交 好 ， 耶 和 华 必 破 坏 你 所 造 的 。 ” 后 来 那 船 果 然 破 坏 ， 不 能 往 他 施 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11626', '14', '21', '1', '约 沙 法 与 他 列 祖 同 睡 ， 葬 在 大 卫 城 他 列 祖 的 坟 地 里 。 他 儿 子 约 兰 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11627', '14', '21', '2', '＜ 犹 大 国 的 王 约 兰 （ 王 下   8 : 1 7 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11628', '14', '21', '3', '他 们 的 父 亲 将 许 多 金 银 、 财 宝 ， 和 犹 大 地 的 坚 固 城 赐 给 他 们 ； 但 将 国 赐 给 约 兰 ， 因 为 他 是 长 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11629', '14', '21', '4', '约 兰 兴 起 坐 他 父 的 位 ， 奋 勇 自 强 ， 就 用 刀 杀 了 他 的 众 兄 弟 和 以 色 列 的 几 个 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11630', '14', '21', '5', '约 兰 登 基 的 时 候 年 三 十 二 岁 ， 在 耶 路 撒 冷 作 王 八 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11631', '14', '21', '6', '他 行 以 色 列 诸 王 的 道 ， 与 亚 哈 家 一 样 ； 因 他 娶 了 亚 哈 的 女 儿 为 妻 ， 行 耶 和 华 眼 中 看 为 恶 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11632', '14', '21', '7', '耶 和 华 却 因 自 己 与 大 卫 所 立 的 约 ， 不 肯 灭 大 卫 的 家 ， 照 他 所 应 许 的 ， 永 远 赐 灯 光 与 大 卫 和 他 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11633', '14', '21', '8', '约 兰 年 间 ， 以 东 人 背 叛 犹 大 ， 脱 离 他 的 权 下 ， 自 己 立 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11634', '14', '21', '9', '约 兰 就 率 领 军 长 和 所 有 的 战 车 ， 夜 间 起 来 ， 攻 击 围 困 他 的 以 东 人 和 车 兵 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11635', '14', '21', '10', '这 样 ， 以 东 人 背 叛 犹 大 ， 脱 离 他 的 权 下 ， 直 到 今 日 。 那 时 ， 立 拿 人 也 背 叛 了 ， 因 为 约 兰 离 弃 耶 和 华 ─ ─ 他 列 祖 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11636', '14', '21', '11', '他 又 在 犹 大 诸 山 建 筑 邱 坛 ， 使 耶 路 撒 冷 的 居 民 行 邪 淫 ， 诱 惑 犹 大 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11637', '14', '21', '12', '先 知 以 利 亚 达 信 与 约 兰 说 ： “ 耶 和 华 ─ ─ 你 祖 大 卫 的 神 如 此 说 ： ‘ 因 为 你 不 行 你 父 约 沙 法 和 犹 大 王 亚 撒 的 道 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11638', '14', '21', '13', '乃 行 以 色 列 诸 王 的 道 ， 使 犹 大 人 和 耶 路 撒 冷 的 居 民 行 邪 淫 ， 像 亚 哈 家 一 样 ， 又 杀 了 你 父 家 比 你 好 的 诸 兄 弟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11639', '14', '21', '14', '故 此 ， 耶 和 华 降 大 灾 与 你 的 百 姓 和 你 的 妻 子 、 儿 女 ， 并 你 一 切 所 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11640', '14', '21', '15', '你 的 肠 子 必 患 病 ， 日 加 沉 重 ， 以 致 你 的 肠 子 坠 落 下 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11641', '14', '21', '16', '以 后 ， 耶 和 华 激 动 非 利 士 人 和 靠 近 古 实 的 阿 拉 伯 人 来 攻 击 约 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11642', '14', '21', '17', '他 们 上 来 攻 击 犹 大 ， 侵 入 境 内 ， 掳 掠 了 王 宫 里 所 有 的 财 货 和 他 的 妻 子 、 儿 女 ， 除 了 他 小 儿 子 约 哈 斯 ｛ 又 名 亚 哈 谢 ｝ 之 外 ， 没 有 留 下 一 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11643', '14', '21', '18', '这 些 事 以 后 ， 耶 和 华 使 约 兰 的 肠 子 患 不 能 医 治 的 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11644', '14', '21', '19', '他 患 此 病 缠 绵 日 久 ， 过 了 二 年 ， 肠 子 坠 落 下 来 ， 病 重 而 死 。 他 的 民 没 有 为 他 烧 什 么 物 件 ， 像 从 前 为 他 列 祖 所 烧 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11645', '14', '21', '20', '约 兰 登 基 的 时 候 年 三 十 二 岁 ， 在 耶 路 撒 冷 作 王 八 年 。 他 去 世 无 人 思 慕 ， 众 人 葬 他 在 大 卫 城 ， 只 是 不 在 列 王 的 坟 墓 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11646', '14', '22', '1', '＜ 犹 大 国 的 王 亚 哈 谢 （ 王 下   8 : 2 5 - 2 9 ； 9 : 2 1 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11647', '14', '22', '2', '亚 哈 谢 登 基 的 时 候 年 四 十 二 岁 ｛ 列 王 下 八 章 二 十 六 节 是 二 十 二 岁 ｝ ， 在 耶 路 撒 冷 作 王 一 年 。 他 母 亲 名 叫 亚 她 利 雅 ， 是 暗 利 的 孙 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11648', '14', '22', '3', '亚 哈 谢 也 行 亚 哈 家 的 道 ； 因 为 他 母 亲 给 他 主 谋 ， 使 他 行 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11649', '14', '22', '4', '他 行 耶 和 华 眼 中 看 为 恶 的 事 ， 像 亚 哈 家 一 样 ； 因 他 父 亲 死 后 有 亚 哈 家 的 人 给 他 主 谋 ， 以 致 败 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11650', '14', '22', '5', '他 听 从 亚 哈 家 的 计 谋 ， 同 以 色 列 王 亚 哈 的 儿 子 约 兰 往 基 列 的 拉 末 去 ， 与 亚 兰 王 哈 薛 争 战 ； 亚 兰 人 打 伤 了 约 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11651', '14', '22', '6', '约 兰 回 到 耶 斯 列 ， 医 治 在 拉 末 与 亚 兰 王 哈 薛 打 仗 所 受 的 伤 ， 犹 大 王 约 兰 的 儿 子 亚 撒 利 雅 ｛ 就 是 亚 哈 谢 ｝ 因 为 亚 哈 的 儿 子 约 兰 病 了 ， 就 下 到 耶 斯 列 看 望 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11652', '14', '22', '7', '亚 哈 谢 去 见 约 兰 就 被 害 了 ， 这 是 出 乎 神 ； 因 为 他 到 了 ， 就 同 约 兰 出 去 攻 击 宁 示 的 孙 子 耶 户 。 这 耶 户 是 耶 和 华 所 膏 、 使 他 剪 除 亚 哈 家 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11653', '14', '22', '8', '耶 户 讨 亚 哈 家 罪 的 时 候 ， 遇 见 犹 大 的 众 首 领 和 亚 哈 谢 的 众 侄 子 服 事 亚 哈 谢 ， 就 把 他 们 都 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11654', '14', '22', '9', '亚 哈 谢 藏 在 撒 马 利 亚 ， 耶 户 寻 找 他 ， 众 人 将 他 拿 住 ， 送 到 耶 户 那 里 ， 就 杀 了 他 ， 将 他 葬 埋 ； 因 他 们 说 ， 他 是 那 尽 心 寻 求 耶 和 华 之 约 沙 法 的 儿 子 。 这 样 ， 亚 哈 谢 的 家 无 力 保 守 国 权 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11655', '14', '22', '10', '＜ 犹 大 国 的 女 王 亚 她 利 雅 （ 王 下   1 1 : 1 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11656', '14', '22', '11', '但 王 的 女 儿 约 示 巴 将 亚 哈 谢 的 儿 子 约 阿 施 从 那 被 杀 的 王 子 中 偷 出 来 ， 把 他 和 他 的 乳 母 都 藏 在 卧 房 里 。 约 示 巴 是 约 兰 王 的 女 儿 ， 亚 哈 谢 的 妹 子 ， 祭 司 耶 何 耶 大 的 妻 。 她 收 藏 约 阿 施 ， 躲 避 亚 她 利 雅 ， 免 得 被 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11657', '14', '22', '12', '约 阿 施 和 她 们 一 同 藏 在 神 殿 里 六 年 ； 亚 她 利 雅 篡 了 国 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11658', '14', '23', '1', '＜ 推 翻 亚 她 利 雅 （ 王 下   1 1 : 4 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11659', '14', '23', '2', '他 们 走 遍 犹 大 ， 从 犹 大 各 城 里 招 聚 利 未 人 和 以 色 列 的 众 族 长 到 耶 路 撒 冷 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11660', '14', '23', '3', '会 众 在 神 殿 里 与 王 立 约 。 耶 何 耶 大 对 他 们 说 ： “ 看 哪 ， 王 的 儿 子 必 当 作 王 ， 正 如 耶 和 华 指 着 大 卫 子 孙 所 应 许 的 话 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11661', '14', '23', '4', '又 说 ： “ 你 们 当 这 样 行 ： 祭 司 和 利 未 人 凡 安 息 日 进 班 的 ， 三 分 之 一 要 把 守 各 门 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11662', '14', '23', '5', '三 分 之 一 要 在 王 宫 ， 三 分 之 一 要 在 基 址 门 ； 众 百 姓 要 在 耶 和 华 殿 的 院 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11663', '14', '23', '6', '除 了 祭 司 和 供 职 的 利 未 人 之 外 ， 不 准 别 人 进 耶 和 华 的 殿 ； 惟 独 他 们 可 以 进 去 ， 因 为 他 们 圣 洁 。 众 百 姓 要 遵 守 耶 和 华 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11664', '14', '23', '7', '利 未 人 要 手 中 各 拿 兵 器 ， 四 围 护 卫 王 ； 凡 擅 入 殿 宇 的 ， 必 当 治 死 。 王 出 入 的 时 候 ， 你 们 当 跟 随 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11665', '14', '23', '8', '利 未 人 和 犹 大 众 人 都 照 着 祭 司 耶 何 耶 大 一 切 所 吩 咐 的 去 行 ， 各 带 所 管 安 息 日 进 班 出 班 的 人 来 ， 因 为 祭 司 耶 何 耶 大 不 许 他 们 下 班 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11666', '14', '23', '9', '祭 司 耶 何 耶 大 便 将 神 殿 里 所 藏 大 卫 王 的 枪 、 盾 牌 、 挡 牌 交 给 百 夫 长 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11667', '14', '23', '10', '又 分 派 众 民 手 中 各 拿 兵 器 ， 在 坛 和 殿 那 里 ， 从 殿 右 直 到 殿 左 ， 站 在 王 子 的 四 围 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11668', '14', '23', '11', '于 是 领 王 子 出 来 ， 给 他 戴 上 冠 冕 ， 将 律 法 书 交 给 他 ， 立 他 作 王 。 耶 何 耶 大 和 众 子 膏 他 ， 众 人 说 ： “ 愿 王 万 岁 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11669', '14', '23', '12', '亚 她 利 雅 听 见 民 奔 走 赞 美 王 的 声 音 ， 就 到 民 那 里 ， 进 耶 和 华 的 殿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11670', '14', '23', '13', '看 见 王 站 在 殿 门 的 柱 旁 ， 百 夫 长 和 吹 号 的 人 侍 立 在 王 左 右 ， 国 民 都 欢 乐 吹 号 ， 又 有 歌 唱 的 ， 用 各 样 的 乐 器 领 人 歌 唱 赞 美 ； 亚 她 利 雅 就 撕 裂 衣 服 ， 喊 叫 说 ： “ 反 了 ！ 反 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11671', '14', '23', '14', '祭 司 耶 何 耶 大 带 管 辖 军 兵 的 百 夫 长 出 来 ， 吩 咐 他 们 说 ： “ 将 她 赶 到 班 外 ， 凡 跟 随 她 的 必 用 刀 杀 死 ！ ” 因 为 祭 司 说 ： “ 不 可 在 耶 和 华 殿 里 杀 她 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11672', '14', '23', '15', '众 兵 就 闪 开 ， 让 她 去 ； 她 走 到 王 宫 的 马 门 ， 便 在 那 里 把 她 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11673', '14', '23', '16', '＜ 耶 何 耶 大 的 改 革 （ 王 下   1 1 : 1 7 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11674', '14', '23', '17', '于 是 众 民 都 到 巴 力 庙 ， 拆 毁 了 庙 ， 打 碎 坛 和 像 ， 又 在 坛 前 将 巴 力 的 祭 司 玛 坦 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11675', '14', '23', '18', '耶 何 耶 大 派 官 看 守 耶 和 华 的 殿 ， 是 在 祭 司 利 未 人 手 下 。 这 祭 司 利 未 人 是 大 卫 分 派 在 耶 和 华 殿 中 、 照 摩 西 律 法 上 所 写 的 ， 给 耶 和 华 献 燔 祭 ， 又 按 大 卫 所 定 的 例 ， 欢 乐 歌 唱 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11676', '14', '23', '19', '且 设 立 守 门 的 把 守 耶 和 华 殿 的 各 门 ， 无 论 为 何 事 ， 不 洁 净 的 人 都 不 准 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11677', '14', '23', '20', '又 率 领 百 夫 长 和 贵 胄 ， 与 民 间 的 官 长 ， 并 国 中 的 众 民 ， 请 王 从 耶 和 华 殿 下 来 ， 由 上 门 进 入 王 宫 ， 立 王 坐 在 国 位 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11678', '14', '23', '21', '国 民 都 欢 乐 ， 合 城 都 安 静 。 众 人 已 将 亚 她 利 雅 用 刀 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11679', '14', '24', '1', '＜ 犹 大 国 的 王 约 阿 施 （ 王 下   1 2 : 1 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11680', '14', '24', '2', '祭 司 耶 何 耶 大 在 世 的 时 候 ， 约 阿 施 行 耶 和 华 眼 中 看 为 正 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11681', '14', '24', '3', '耶 何 耶 大 为 他 娶 了 两 个 妻 ， 并 且 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11682', '14', '24', '4', '此 后 ， 约 阿 施 有 意 重 修 耶 和 华 的 殿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11683', '14', '24', '5', '便 召 聚 众 祭 司 和 利 未 人 ， 吩 咐 他 们 说 ： “ 你 们 要 往 犹 大 各 城 去 ， 使 以 色 列 众 人 捐 纳 银 子 ， 每 年 可 以 修 理 你 们 神 的 殿 ； 你 们 要 急 速 办 理 这 事 。 ” 只 是 利 未 人 不 急 速 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11684', '14', '24', '6', '王 召 了 大 祭 司 耶 何 耶 大 来 ， 对 他 说 ： “ 从 前 耶 和 华 的 仆 人 摩 西 ， 为 法 柜 的 帐 幕 与 以 色 列 会 众 所 定 的 捐 项 ， 你 为 何 不 叫 利 未 人 照 这 例 从 犹 大 和 耶 路 撒 冷 带 来 作 殿 的 费 用 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11685', '14', '24', '7', '（ 因 为 那 恶 妇 亚 她 利 雅 的 众 子 曾 拆 毁 神 的 殿 ， 又 用 耶 和 华 殿 中 分 别 为 圣 的 物 供 奉 巴 力 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11686', '14', '24', '8', '于 是 王 下 令 ， 众 人 做 了 一 柜 ， 放 在 耶 和 华 殿 的 门 外 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11687', '14', '24', '9', '又 通 告 犹 大 和 耶 路 撒 冷 的 百 姓 ， 要 将 神 仆 人 摩 西 在 旷 野 所 吩 咐 以 色 列 人 的 捐 项 给 耶 和 华 送 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11688', '14', '24', '10', '众 首 领 和 百 姓 都 欢 欢 喜 喜 地 将 银 子 送 来 ， 投 入 柜 中 ， 直 到 捐 完 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11689', '14', '24', '11', '利 未 人 见 银 子 多 了 ， 就 把 柜 抬 到 王 所 派 的 司 事 面 前 ； 王 的 书 记 和 大 祭 司 的 属 员 来 将 柜 倒 空 ， 仍 放 在 原 处 。 日 日 都 是 这 样 ， 积 蓄 的 银 子 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11690', '14', '24', '12', '王 与 耶 何 耶 大 将 银 子 交 给 耶 和 华 殿 里 办 事 的 人 ， 他 们 就 雇 了 石 匠 、 木 匠 重 修 耶 和 华 的 殿 ， 又 雇 了 铁 匠 、 铜 匠 修 理 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11691', '14', '24', '13', '工 人 操 作 ， 渐 渐 修 成 ， 将 神 殿 修 造 得 与 从 前 一 样 ， 而 且 甚 是 坚 固 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11692', '14', '24', '14', '工 程 完 了 ， 他 们 就 把 其 余 的 银 子 拿 到 王 与 耶 何 耶 大 面 前 ， 用 以 制 造 耶 和 华 殿 供 奉 所 用 的 器 皿 和 调 羹 ， 并 金 银 的 器 皿 。 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11693', '14', '24', '15', '耶 何 耶 大 年 纪 老 迈 ， 日 子 满 足 而 死 。 死 的 时 候 年 一 百 三 十 岁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11694', '14', '24', '16', '葬 在 大 卫 城 列 王 的 坟 墓 里 ； 因 为 他 在 以 色 列 人 中 行 善 ， 又 事 奉 神 ， 修 理 神 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11695', '14', '24', '17', '耶 何 耶 大 死 后 ， 犹 大 的 众 首 领 来 朝 拜 王 ； 王 就 听 从 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11696', '14', '24', '18', '他 们 离 弃 耶 和 华 ─ ─ 他 们 列 祖 神 的 殿 ， 去 事 奉 亚 舍 拉 和 偶 像 ； 因 他 们 这 罪 ， 就 有 忿 怒 临 到 犹 大 和 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11697', '14', '24', '19', '但 神 仍 遣 先 知 到 他 们 那 里 ， 引 导 他 们 归 向 耶 和 华 。 这 先 知 警 戒 他 们 ， 他 们 却 不 肯 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11698', '14', '24', '20', '那 时 ， 神 的 灵 感 动 祭 司 耶 何 耶 大 的 儿 子 撒 迦 利 亚 ， 他 就 站 在 上 面 对 民 说 ： “ 神 如 此 说 ： 你 们 为 何 干 犯 耶 和 华 的 诫 命 ， 以 致 不 得 亨 通 呢 ？ 因 为 你 们 离 弃 耶 和 华 ， 所 以 他 也 离 弃 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11699', '14', '24', '21', '众 民 同 心 谋 害 撒 迦 利 亚 ， 就 照 王 的 吩 咐 ， 在 耶 和 华 殿 的 院 内 用 石 头 打 死 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11700', '14', '24', '22', '这 样 ， 约 阿 施 王 不 想 念 撒 迦 利 亚 的 父 亲 耶 何 耶 大 向 自 己 所 施 的 恩 ， 杀 了 他 的 儿 子 。 撒 迦 利 亚 临 死 的 时 候 说 ： “ 愿 耶 和 华 鉴 察 伸 冤 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11701', '14', '24', '23', '＜ 约 阿 施 被 杀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11702', '14', '24', '24', '亚 兰 的 军 兵 虽 来 了 一 小 队 ， 耶 和 华 却 将 大 队 的 军 兵 交 在 他 们 手 里 ， 是 因 犹 大 人 离 弃 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 所 以 藉 亚 兰 人 惩 罚 约 阿 施 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11703', '14', '24', '25', '亚 兰 人 离 开 约 阿 施 的 时 候 ， 他 患 重 病 ； 臣 仆 背 叛 他 ， 要 报 祭 司 耶 何 耶 大 儿 子 流 血 之 仇 ， 杀 他 在 床 上 ， 葬 他 在 大 卫 城 ， 只 是 不 葬 在 列 王 的 坟 墓 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11704', '14', '24', '26', '背 叛 他 的 是 亚 扪 妇 人 示 米 押 的 儿 子 撒 拔 和 摩 押 妇 人 示 米 利 的 儿 子 约 萨 拔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11705', '14', '24', '27', '至 于 他 的 众 子 和 他 所 受 的 警 戒 ， 并 他 重 修 神 殿 的 事 ， 都 写 在 列 王 的 传 上 。 他 儿 子 亚 玛 谢 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11706', '14', '25', '1', '＜ 犹 大 国 的 王 亚 玛 谢 （ 王 下   1 4 : 2 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11707', '14', '25', '2', '亚 玛 谢 行 耶 和 华 眼 中 看 为 正 的 事 ， 只 是 心 不 专 诚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11708', '14', '25', '3', '国 一 坚 定 ， 就 把 杀 他 父 王 的 臣 仆 杀 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11709', '14', '25', '4', '却 没 有 治 死 他 们 的 儿 子 ， 是 照 摩 西 律 法 书 上 耶 和 华 所 吩 咐 的 说 ： “ 不 可 因 子 杀 父 ， 也 不 可 因 父 杀 子 ， 各 人 要 为 本 身 的 罪 而 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11710', '14', '25', '5', '＜ 与 以 东 交 战 （ 王 下   1 4 : 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11711', '14', '25', '6', '又 用 银 子 一 百 他 连 得 ， 从 以 色 列 招 募 了 十 万 大 能 的 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11712', '14', '25', '7', '有 一 个 神 人 来 见 亚 玛 谢 ， 对 他 说 ： “ 王 啊 ， 不 要 使 以 色 列 的 军 兵 与 你 同 去 ， 因 为 耶 和 华 不 与 以 色 列 人 以 法 莲 的 后 裔 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11713', '14', '25', '8', '你 若 一 定 要 去 ， 就 奋 勇 争 战 吧 ！ 但 神 必 使 你 败 在 敌 人 面 前 ； 因 为 神 能 助 人 得 胜 ， 也 能 使 人 倾 败 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11714', '14', '25', '9', '亚 玛 谢 问 神 人 说 ： “ 我 给 了 以 色 列 军 的 那 一 百 他 连 得 银 子 怎 么 样 呢 ？ ” 神 人 回 答 说 ： “ 耶 和 华 能 把 更 多 的 赐 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11715', '14', '25', '10', '于 是 亚 玛 谢 将 那 从 以 法 莲 来 的 军 兵 分 别 出 来 ， 叫 他 们 回 家 去 。 故 此 ， 他 们 甚 恼 怒 犹 大 人 ， 气 忿 忿 地 回 家 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11716', '14', '25', '11', '亚 玛 谢 壮 起 胆 来 ， 率 领 他 的 民 到 盐 谷 ， 杀 了 西 珥 人 一 万 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11717', '14', '25', '12', '犹 大 人 又 生 擒 了 一 万 带 到 山 崖 上 ， 从 那 里 把 他 们 扔 下 去 ， 以 致 他 们 都 摔 碎 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11718', '14', '25', '13', '但 亚 玛 谢 所 打 发 回 去 、 不 许 一 同 出 征 的 那 些 军 兵 攻 打 犹 大 各 城 ， 从 撒 马 利 亚 直 到 伯 ． 和 仑 ， 杀 了 三 千 人 ， 抢 了 许 多 财 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11719', '14', '25', '14', '亚 玛 谢 杀 了 以 东 人 回 来 ， 就 把 西 珥 的 神 像 带 回 ， 立 为 自 己 的 神 ， 在 它 面 前 叩 拜 烧 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11720', '14', '25', '15', '因 此 ， 耶 和 华 的 怒 气 向 亚 玛 谢 发 作 ， 就 差 一 个 先 知 去 见 他 ， 说 ： “ 这 些 神 不 能 救 它 的 民 脱 离 你 的 手 ， 你 为 何 寻 求 它 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11721', '14', '25', '16', '先 知 与 王 说 话 的 时 候 ， 王 对 他 说 ： “ 谁 立 你 作 王 的 谋 士 呢 ？ 你 住 口 吧 ！ 为 何 找 打 呢 ？ ” 先 知 就 止 住 了 ， 又 说 ： “ 你 行 这 事 ， 不 听 从 我 的 劝 戒 ， 我 知 道 神 定 意 要 灭 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11722', '14', '25', '17', '＜ 与 以 色 列 争 战 （ 王 下   1 4 : 8 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11723', '14', '25', '18', '以 色 列 王 约 阿 施 差 遣 使 者 去 见 犹 大 王 亚 玛 谢 ， 说 ： “ 黎 巴 嫩 的 蒺 藜 差 遣 使 者 去 见 黎 巴 嫩 的 香 柏 树 ， 说 ： ‘ 将 你 的 女 儿 给 我 儿 子 为 妻 。 ’ 后 来 黎 巴 嫩 有 一 个 野 兽 经 过 ， 把 蒺 藜 践 踏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11724', '14', '25', '19', '你 说 ： ‘ 看 哪 ， 我 打 败 了 以 东 人 ’ ， 你 就 心 高 气 傲 ， 以 致 矜 夸 。 你 在 家 里 安 居 就 罢 了 ， 为 何 要 惹 祸 使 自 己 和 犹 大 国 一 同 败 亡 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11725', '14', '25', '20', '亚 玛 谢 却 不 肯 听 从 。 这 是 出 乎 神 ， 好 将 他 们 交 在 敌 人 手 里 ， 因 为 他 们 寻 求 以 东 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11726', '14', '25', '21', '于 是 以 色 列 王 约 阿 施 上 来 ， 在 犹 大 的 伯 ． 示 麦 与 犹 大 王 亚 玛 谢 相 见 于 战 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11727', '14', '25', '22', '犹 大 人 败 在 以 色 列 人 面 前 ， 各 自 逃 回 家 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11728', '14', '25', '23', '以 色 列 王 约 阿 施 在 伯 ． 示 麦 擒 住 约 哈 斯 ｛ 就 是 亚 哈 谢 ｝ 的 孙 子 、 约 阿 施 的 儿 子 、 犹 大 王 亚 玛 谢 ， 将 他 带 到 耶 路 撒 冷 ， 又 拆 毁 耶 路 撒 冷 的 城 墙 ， 从 以 法 莲 门 直 到 角 门 ， 共 四 百 肘 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11729', '14', '25', '24', '又 将 俄 别 ． 以 东 所 看 守 神 殿 里 的 一 切 金 银 和 器 皿 ， 与 王 宫 里 的 财 宝 都 拿 了 去 ， 并 带 人 去 为 质 ， 就 回 撒 马 利 亚 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11730', '14', '25', '25', '以 色 列 王 约 哈 斯 的 儿 子 约 阿 施 死 后 ， 犹 大 王 约 阿 施 的 儿 子 亚 玛 谢 又 活 了 十 五 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11731', '14', '25', '26', '亚 玛 谢 其 余 的 事 ， 自 始 至 终 不 都 写 在 犹 大 和 以 色 列 诸 王 记 上 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11732', '14', '25', '27', '自 从 亚 玛 谢 离 弃 耶 和 华 之 后 ， 在 耶 路 撒 冷 有 人 背 叛 他 ， 他 就 逃 到 拉 吉 ； 叛 党 却 打 发 人 到 拉 吉 ， 将 他 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11733', '14', '25', '28', '人 就 用 马 将 他 的 尸 首 驮 回 ， 葬 在 犹 大 京 城 他 列 祖 的 坟 地 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11734', '14', '26', '1', '＜ 犹 大 国 的 王 乌 西 雅 （ 王 下   1 4 : 2 1 - 2 2 ； 1 5 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11735', '14', '26', '2', '（ 亚 玛 谢 与 他 列 祖 同 睡 之 后 ， 乌 西 雅 收 回 以 禄 仍 归 犹 大 ， 又 重 新 修 理 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11736', '14', '26', '3', '乌 西 雅 登 基 的 时 候 年 十 六 岁 ， 在 耶 路 撒 冷 作 王 五 十 二 年 。 他 母 亲 名 叫 耶 可 利 雅 ， 是 耶 路 撒 冷 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11737', '14', '26', '4', '乌 西 雅 行 耶 和 华 眼 中 看 为 正 的 事 ， 效 法 他 父 亚 玛 谢 一 切 所 行 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11738', '14', '26', '5', '通 晓 神 默 示 ， 撒 迦 利 亚 在 世 的 时 候 ， 乌 西 雅 定 意 寻 求 神 ； 他 寻 求 耶 和 华 ， 神 就 使 他 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11739', '14', '26', '6', '他 出 去 攻 击 非 利 士 人 ， 拆 毁 了 迦 特 城 、 雅 比 尼 城 ， 和 亚 实 突 城 ； 在 非 利 士 人 中 ， 在 亚 实 突 境 内 ， 又 建 筑 了 些 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11740', '14', '26', '7', '神 帮 助 他 攻 击 非 利 士 人 和 住 在 姑 珥 ， 巴 力 的 阿 拉 伯 人 ， 并 米 乌 尼 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11741', '14', '26', '8', '亚 扪 人 给 乌 西 雅 进 贡 。 他 的 名 声 传 到 埃 及 ， 因 他 甚 是 强 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11742', '14', '26', '9', '乌 西 雅 在 耶 路 撒 冷 的 角 门 和 谷 门 ， 并 城 墙 转 弯 之 处 ， 建 筑 城 楼 ， 且 甚 坚 固 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11743', '14', '26', '10', '又 在 旷 野 与 高 原 和 平 原 ， 建 筑 望 楼 ， 挖 了 许 多 井 ， 因 他 的 牲 畜 甚 多 ； 又 在 山 地 和 佳 美 之 地 ， 有 农 夫 和 修 理 葡 萄 园 的 人 ， 因 为 他 喜 悦 农 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11744', '14', '26', '11', '乌 西 雅 又 有 军 兵 ， 照 书 记 耶 利 和 官 长 玛 西 雅 所 数 点 的 ， 在 王 的 一 个 将 军 哈 拿 尼 雅 手 下 ， 分 队 出 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11745', '14', '26', '12', '族 长 、 大 能 勇 士 的 总 数 共 有 二 千 六 百 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11746', '14', '26', '13', '他 们 手 下 的 军 兵 共 有 三 十 万 七 千 五 百 人 ， 都 有 大 能 ， 善 于 争 战 ， 帮 助 王 攻 击 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11747', '14', '26', '14', '乌 西 雅 为 全 军 预 备 盾 牌 、 枪 、 盔 、 甲 、 弓 ， 和 甩 石 的 机 弦 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11748', '14', '26', '15', '又 在 耶 路 撒 冷 使 巧 匠 做 机 器 ， 安 在 城 楼 和 角 楼 上 ， 用 以 射 箭 发 石 。 乌 西 雅 的 名 声 传 到 远 方 ； 因 为 他 得 了 非 常 的 帮 助 ， 甚 是 强 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11749', '14', '26', '16', '＜ 乌 西 雅 因 骄 傲 受 惩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11750', '14', '26', '17', '祭 司 亚 撒 利 雅 率 领 耶 和 华 勇 敢 的 祭 司 八 十 人 ， 跟 随 他 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11751', '14', '26', '18', '他 们 就 阻 挡 乌 西 雅 王 ， 对 他 说 ： “ 乌 西 雅 啊 ， 给 耶 和 华 烧 香 不 是 你 的 事 ， 乃 是 亚 伦 子 孙 承 接 圣 职 祭 司 的 事 。 你 出 圣 殿 吧 ！ 因 为 你 犯 了 罪 。 你 行 这 事 ， 耶 和 华 神 必 不 使 你 得 荣 耀 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11752', '14', '26', '19', '乌 西 雅 就 发 怒 ， 手 拿 香 炉 要 烧 香 。 他 向 祭 司 发 怒 的 时 候 ， 在 耶 和 华 殿 中 香 坛 旁 众 祭 司 面 前 ， 额 上 忽 然 发 出 大 痲 疯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11753', '14', '26', '20', '大 祭 司 亚 撒 利 雅 和 众 祭 司 观 看 ， 见 他 额 上 发 出 大 痲 疯 ， 就 催 他 出 殿 ； 他 自 己 也 急 速 出 去 ， 因 为 耶 和 华 降 灾 与 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11754', '14', '26', '21', '乌 西 雅 王 长 大 痲 疯 直 到 死 日 ， 因 此 住 在 别 的 宫 里 ， 与 耶 和 华 的 殿 隔 绝 。 他 儿 子 约 坦 管 理 家 事 ， 治 理 国 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11755', '14', '26', '22', '乌 西 雅 其 余 的 事 ， 自 始 至 终 都 是 亚 摩 斯 的 儿 子 先 知 以 赛 亚 所 记 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11756', '14', '26', '23', '乌 西 雅 与 他 列 祖 同 睡 ， 葬 在 王 陵 的 田 间 他 列 祖 的 坟 地 里 ； 因 为 人 说 ， 他 是 长 大 痲 疯 的 。 他 儿 子 约 坦 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11757', '14', '27', '1', '＜ 犹 大 国 的 王 约 坦 （ 王 下   1 5 : 3 2 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11758', '14', '27', '2', '约 坦 行 耶 和 华 眼 中 看 为 正 的 事 ， 效 法 他 父 乌 西 雅 一 切 所 行 的 ， 只 是 不 入 耶 和 华 的 殿 。 百 姓 还 行 邪 僻 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11759', '14', '27', '3', '约 坦 建 立 耶 和 华 殿 的 上 门 ， 在 俄 斐 勒 城 上 多 有 建 造 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11760', '14', '27', '4', '又 在 犹 大 山 地 建 造 城 邑 ， 在 树 林 中 建 筑 营 寨 和 高 楼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11761', '14', '27', '5', '约 坦 与 亚 扪 人 的 王 打 仗 胜 了 他 们 ， 当 年 他 们 进 贡 银 一 百 他 连 得 ， 小 麦 一 万 歌 珥 ， 大 麦 一 万 歌 珥 ； 第 二 年 、 第 三 年 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11762', '14', '27', '6', '约 坦 在 耶 和 华 ─ ─ 他 神 面 前 行 正 道 ， 以 致 日 渐 强 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11763', '14', '27', '7', '约 坦 其 余 的 事 和 一 切 争 战 ， 并 他 的 行 为 ， 都 写 在 以 色 列 和 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11764', '14', '27', '8', '他 登 基 的 时 候 年 二 十 五 岁 ， 在 耶 路 撒 冷 作 王 十 六 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11765', '14', '27', '9', '约 坦 与 他 列 祖 同 睡 ， 葬 在 大 卫 城 里 。 他 儿 子 亚 哈 斯 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11766', '14', '28', '1', '＜ 犹 大 国 的 王 亚 哈 斯 （ 王 下   1 6 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11767', '14', '28', '2', '却 行 以 色 列 诸 王 的 道 ， 又 铸 造 巴 力 的 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11768', '14', '28', '3', '并 且 在 欣 嫩 子 谷 烧 香 ， 用 火 焚 烧 他 的 儿 女 ， 行 耶 和 华 在 以 色 列 人 面 前 所 驱 逐 的 外 邦 人 那 可 憎 的 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11769', '14', '28', '4', '并 在 邱 坛 上 、 山 冈 上 、 各 青 翠 树 下 献 祭 烧 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11770', '14', '28', '5', '＜ 跟 亚 兰 和 以 色 列 交 战 （ 王 下   1 6 : 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11771', '14', '28', '6', '利 玛 利 的 儿 子 比 加 一 日 杀 了 犹 大 人 十 二 万 ， 都 是 勇 士 ， 因 为 他 们 离 弃 了 耶 和 华 ─ ─ 他 们 列 祖 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11772', '14', '28', '7', '有 一 个 以 法 莲 中 的 勇 士 ， 名 叫 细 基 利 ， 杀 了 王 的 儿 子 玛 西 雅 和 管 理 王 宫 的 押 斯 利 甘 ， 并 宰 相 以 利 加 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11773', '14', '28', '8', '以 色 列 人 掳 了 他 们 的 弟 兄 ， 连 妇 人 带 儿 女 共 有 二 十 万 ， 又 掠 了 许 多 的 财 物 ， 带 到 撒 马 利 亚 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11774', '14', '28', '9', '＜ 先 知 俄 德 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11775', '14', '28', '10', '如 今 你 们 又 有 意 强 逼 犹 大 人 和 耶 路 撒 冷 人 作 你 们 的 奴 婢 ， 你 们 岂 不 也 有 得 罪 耶 和 华 ─ ─ 你 们 神 的 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11776', '14', '28', '11', '现 在 你 们 当 听 我 说 ， 要 将 掳 来 的 弟 兄 释 放 回 去 ， 因 为 耶 和 华 向 你 们 已 经 大 发 烈 怒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11777', '14', '28', '12', '于 是 ， 以 法 莲 人 的 几 个 族 长 ─ ─ 就 是 约 哈 难 的 儿 子 亚 撒 利 雅 、 米 实 利 末 的 儿 子 比 利 家 、 沙 龙 的 儿 子 耶 希 西 家 、 哈 得 莱 的 儿 子 亚 玛 撒 ─ ─ 起 来 拦 挡 出 兵 回 来 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11778', '14', '28', '13', '对 他 们 说 ： “ 你 们 不 可 带 进 这 被 掳 的 人 来 ！ 你 们 想 要 使 我 们 得 罪 耶 和 华 ， 加 增 我 们 的 罪 恶 过 犯 ？ 因 为 我 们 的 罪 过 甚 大 ， 已 经 有 烈 怒 临 到 以 色 列 人 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11779', '14', '28', '14', '于 是 带 兵 器 的 人 将 掳 来 的 人 口 和 掠 来 的 财 物 都 留 在 众 首 领 和 会 众 的 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11780', '14', '28', '15', '以 上 提 名 的 那 些 人 就 站 起 ， 使 被 掳 的 人 前 来 ； 其 中 有 赤 身 的 ， 就 从 所 掠 的 财 物 中 拿 出 衣 服 和 鞋 来 ， 给 他 们 穿 ， 又 给 他 们 吃 喝 ， 用 膏 抹 他 们 ； 其 中 有 软 弱 的 ， 就 使 他 们 骑 驴 ， 送 到 棕 树 城 耶 利 哥 他 们 弟 兄 那 里 ； 随 后 就 回 撒 马 利 亚 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11781', '14', '28', '16', '＜ 亚 哈 斯 向 亚 述 王 求 援 （ 王 下   1 6 : 7 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11782', '14', '28', '17', '因 为 以 东 人 又 来 攻 击 犹 大 ， 掳 掠 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11783', '14', '28', '18', '非 利 士 人 也 来 侵 占 高 原 和 犹 大 南 方 的 城 邑 ， 取 了 伯 ． 示 麦 、 亚 雅 仑 、 基 低 罗 ， 梭 哥 和 属 梭 哥 的 乡 村 ， 亭 纳 和 属 亭 纳 的 乡 村 ， 瑾 锁 和 属 瑾 锁 的 乡 村 ， 就 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11784', '14', '28', '19', '因 为 以 色 列 王 亚 哈 斯 在 犹 大 放 肆 ， 大 大 干 犯 耶 和 华 ， 所 以 耶 和 华 使 犹 大 卑 微 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11785', '14', '28', '20', '亚 述 王 提 革 拉 ． 毗 列 色 上 来 ， 却 没 有 帮 助 他 ， 反 倒 欺 凌 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11786', '14', '28', '21', '亚 哈 斯 从 耶 和 华 殿 里 和 王 宫 中 ， 并 首 领 家 内 所 取 的 财 宝 给 了 亚 述 王 ， 这 也 无 济 于 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11787', '14', '28', '22', '＜ 亚 哈 斯 的 罪 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11788', '14', '28', '23', '他 祭 祀 攻 击 他 的 大 马 士 革 之 神 ， 说 ： “ 因 为 亚 兰 王 的 神 帮 助 他 们 ， 我 也 献 祭 与 他 ， 他 好 帮 助 我 。 ” 但 那 些 神 使 他 和 以 色 列 众 人 败 亡 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11789', '14', '28', '24', '亚 哈 斯 将 神 殿 里 的 器 皿 都 聚 了 来 ， 毁 坏 了 ， 且 封 锁 耶 和 华 殿 的 门 ； 在 耶 路 撒 冷 各 处 的 拐 角 建 筑 祭 坛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11790', '14', '28', '25', '又 在 犹 大 各 城 建 立 邱 坛 ， 与 别 神 烧 香 ， 惹 动 耶 和 华 ─ ─ 他 列 祖 神 的 怒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11791', '14', '28', '26', '亚 哈 斯 其 余 的 事 和 他 的 行 为 ， 自 始 至 终 都 写 在 犹 大 和 以 色 列 诸 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11792', '14', '28', '27', '亚 哈 斯 与 他 列 祖 同 睡 ， 葬 在 耶 路 撒 冷 城 里 ， 没 有 送 入 以 色 列 诸 王 的 坟 墓 中 。 他 儿 子 希 西 家 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11793', '14', '29', '1', '＜ 犹 大 国 的 王 希 西 家 （ 王 下   1 8 : 1 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11794', '14', '29', '2', '希 西 家 行 耶 和 华 眼 中 看 为 正 的 事 ， 效 法 他 祖 大 卫 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11795', '14', '29', '3', '＜ 洁 净 圣 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11796', '14', '29', '4', '他 召 众 祭 司 和 利 未 人 来 ， 聚 集 在 东 边 的 宽 阔 处 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11797', '14', '29', '5', '对 他 们 说 ： “ 利 未 人 哪 ， 当 听 我 说 ： 现 在 你 们 要 洁 净 自 己 ， 又 洁 净 耶 和 华 ─ ─ 你 们 列 祖 神 的 殿 ， 从 圣 所 中 除 去 污 秽 之 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11798', '14', '29', '6', '我 们 列 祖 犯 了 罪 ， 行 耶 和 华 ─ ─ 我 们 神 眼 中 看 为 恶 的 事 ， 离 弃 他 ， 转 脸 背 向 他 的 居 所 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11799', '14', '29', '7', '封 锁 廊 门 ， 吹 灭 灯 火 ， 不 在 圣 所 中 向 以 色 列 神 烧 香 ， 或 献 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11800', '14', '29', '8', '因 此 ， 耶 和 华 的 忿 怒 临 到 犹 大 和 耶 路 撒 冷 ， 将 其 中 的 人 抛 来 抛 去 ， 令 人 惊 骇 、 嗤 笑 ， 正 如 你 们 亲 眼 所 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11801', '14', '29', '9', '所 以 我 们 的 祖 宗 倒 在 刀 下 ， 我 们 的 妻 子 儿 女 也 被 掳 掠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11802', '14', '29', '10', '现 在 我 心 中 有 意 与 耶 和 华 ─ ─ 以 色 列 的 神 立 约 ， 好 使 他 的 烈 怒 转 离 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11803', '14', '29', '11', '我 的 众 子 啊 ， 现 在 不 要 懈 怠 ； 因 为 耶 和 华 拣 选 你 们 站 在 他 面 前 事 奉 他 ， 与 他 烧 香 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11804', '14', '29', '12', '于 是 ， 利 未 人 哥 辖 的 子 孙 、 亚 玛 赛 的 儿 子 玛 哈 ， 亚 撒 利 雅 的 儿 子 约 珥 ； 米 拉 利 的 子 孙 、 亚 伯 底 的 儿 子 基 士 ， 耶 哈 利 勒 的 儿 子 亚 撒 利 雅 ； 革 顺 的 子 孙 、 薪 玛 的 儿 子 约 亚 ， 约 亚 的 儿 子 伊 甸 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11805', '14', '29', '13', '以 利 撒 反 的 子 孙 申 利 和 耶 利 ； 亚 萨 的 子 孙 撒 迦 利 雅 和 玛 探 雅 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11806', '14', '29', '14', '希 幔 的 子 孙 耶 歇 和 示 每 ； 耶 杜 顿 的 子 孙 示 玛 雅 和 乌 薛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11807', '14', '29', '15', '起 来 聚 集 他 们 的 弟 兄 ， 洁 净 自 己 ， 照 着 王 的 吩 咐 、 耶 和 华 的 命 令 ， 进 去 洁 净 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11808', '14', '29', '16', '祭 司 进 入 耶 和 华 的 殿 要 洁 净 殿 ， 将 殿 中 所 有 污 秽 之 物 搬 到 耶 和 华 殿 的 院 内 ， 利 未 人 接 去 ， 搬 到 外 头 汲 沦 溪 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11809', '14', '29', '17', '从 正 月 初 一 日 洁 净 起 ， 初 八 日 到 了 耶 和 华 的 殿 廊 ， 用 八 日 的 工 夫 洁 净 耶 和 华 的 殿 ， 到 正 月 十 六 日 才 洁 净 完 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11810', '14', '29', '18', '＜ 重 新 奉 献 圣 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11811', '14', '29', '19', '并 且 亚 哈 斯 王 在 位 犯 罪 的 时 候 所 废 弃 的 器 皿 ， 我 们 预 备 齐 全 ， 且 洁 净 了 ， 现 今 都 在 耶 和 华 的 坛 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11812', '14', '29', '20', '希 西 家 王 清 早 起 来 ， 聚 集 城 里 的 首 领 都 上 耶 和 华 的 殿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11813', '14', '29', '21', '牵 了 七 只 公 牛 ， 七 只 公 羊 ， 七 只 羊 羔 ， 七 只 公 山 羊 ， 要 为 国 、 为 殿 、 为 犹 大 人 作 赎 罪 祭 。 王 吩 咐 亚 伦 的 子 孙 众 祭 司 ， 献 在 耶 和 华 的 坛 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11814', '14', '29', '22', '就 宰 了 公 牛 ， 祭 司 接 血 洒 在 坛 上 ， 宰 了 公 羊 ， 把 血 洒 在 坛 上 ， 又 宰 了 羊 羔 ， 也 把 血 洒 在 坛 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11815', '14', '29', '23', '把 那 作 赎 罪 祭 的 公 山 羊 牵 到 王 和 会 众 面 前 ， 他 们 就 按 手 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11816', '14', '29', '24', '祭 司 宰 了 羊 ， 将 血 献 在 坛 上 作 赎 罪 祭 ， 为 以 色 列 众 人 赎 罪 ， 因 为 王 吩 咐 将 燔 祭 和 赎 罪 祭 为 以 色 列 众 人 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11817', '14', '29', '25', '王 又 派 利 未 人 在 耶 和 华 殿 中 敲 钹 ， 鼓 瑟 ， 弹 琴 ， 乃 照 大 卫 和 他 先 见 迦 得 ， 并 先 知 拿 单 所 吩 咐 的 ， 就 是 耶 和 华 藉 先 知 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11818', '14', '29', '26', '利 未 人 拿 大 卫 的 乐 器 ， 祭 司 拿 号 ， 一 同 站 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11819', '14', '29', '27', '希 西 家 吩 咐 在 坛 上 献 燔 祭 ， 燔 祭 一 献 ， 就 唱 赞 美 耶 和 华 的 歌 ， 用 号 ， 并 用 以 色 列 王 大 卫 的 乐 器 相 和 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11820', '14', '29', '28', '会 众 都 敬 拜 ， 歌 唱 的 歌 唱 ， 吹 号 的 吹 号 ， 如 此 直 到 燔 祭 献 完 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11821', '14', '29', '29', '献 完 了 祭 ， 王 和 一 切 跟 随 的 人 都 俯 伏 敬 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11822', '14', '29', '30', '希 西 家 王 与 众 首 领 又 吩 咐 利 未 人 用 大 卫 和 先 见 亚 萨 的 诗 词 颂 赞 耶 和 华 ； 他 们 就 欢 欢 喜 喜 地 颂 赞 耶 和 华 ， 低 头 敬 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11823', '14', '29', '31', '希 西 家 说 ： “ 你 们 既 然 归 耶 和 华 为 圣 ， 就 要 前 来 把 祭 物 和 感 谢 祭 奉 到 耶 和 华 殿 里 。 ” 会 众 就 把 祭 物 和 感 谢 祭 奉 来 ， 凡 甘 心 乐 意 的 也 将 燔 祭 奉 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11824', '14', '29', '32', '会 众 所 奉 的 燔 祭 如 下 ： 公 牛 七 十 只 ， 公 羊 一 百 只 ， 羊 羔 二 百 只 ， 这 都 是 作 燔 祭 献 给 耶 和 华 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11825', '14', '29', '33', '又 有 分 别 为 圣 之 物 ， 公 牛 六 百 只 ， 绵 羊 三 千 只 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11826', '14', '29', '34', '但 祭 司 太 少 ， 不 能 剥 尽 燔 祭 牲 的 皮 ， 所 以 他 们 的 弟 兄 利 未 人 帮 助 他 们 ， 直 等 燔 祭 的 事 完 了 ， 又 等 别 的 祭 司 自 洁 了 ； 因 为 利 未 人 诚 心 自 洁 ， 胜 过 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11827', '14', '29', '35', '燔 祭 和 平 安 祭 牲 的 脂 油 ， 并 燔 祭 同 献 的 奠 祭 甚 多 。 这 样 ， 耶 和 华 殿 中 的 事 务 俱 都 齐 备 了 ｛ 或 译 ： 就 整 顿 了 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11828', '14', '29', '36', '这 事 办 的 甚 速 ， 希 西 家 和 众 民 都 喜 乐 ， 是 因 神 为 众 民 所 预 备 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11829', '14', '30', '1', '＜ 预 备 守 逾 越 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11830', '14', '30', '2', '因 为 王 和 众 首 领 ， 并 耶 路 撒 冷 全 会 众 已 经 商 议 ， 要 在 二 月 内 守 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11831', '14', '30', '3', '正 月 ｛ 原 文 是 那 时 ｝ 间 他 们 不 能 守 ； 因 为 自 洁 的 祭 司 尚 不 敷 用 ， 百 姓 也 没 有 聚 集 在 耶 路 撒 冷 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11832', '14', '30', '4', '王 与 全 会 众 都 以 这 事 为 善 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11833', '14', '30', '5', '于 是 定 了 命 令 ， 传 遍 以 色 列 ， 从 别 是 巴 直 到 但 ， 使 他 们 都 来 ， 在 耶 路 撒 冷 向 耶 和 华 ─ ─ 以 色 列 的 神 守 逾 越 节 ； 因 为 照 所 写 的 例 ， 守 这 节 的 不 多 了 ｛ 或 译 ： 因 为 民 许 久 没 有 照 所 写 的 例 守 节 了 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11834', '14', '30', '6', '驿 卒 就 把 王 和 众 首 领 的 信 ， 遵 着 王 命 传 遍 以 色 列 和 犹 大 。 信 内 说 ： “ 以 色 列 人 哪 ， 你 们 当 转 向 耶 和 华 ─ ─ 亚 伯 拉 罕 、 以 撒 、 以 色 列 的 神 ， 好 叫 他 转 向 你 们 这 脱 离 亚 述 王 手 的 余 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11835', '14', '30', '7', '你 们 不 要 效 法 你 们 列 祖 和 你 们 的 弟 兄 ； 他 们 干 犯 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 以 致 耶 和 华 丢 弃 他 们 ， 使 他 们 败 亡 ｛ 或 译 ： 令 人 惊 骇 ｝ ， 正 如 你 们 所 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11836', '14', '30', '8', '现 在 不 要 像 你 们 列 祖 硬 着 颈 项 ， 只 要 归 顺 耶 和 华 ， 进 入 他 的 圣 所 ， 就 是 永 远 成 圣 的 居 所 ； 又 要 事 奉 耶 和 华 ─ ─ 你 们 的 神 ， 好 使 他 的 烈 怒 转 离 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11837', '14', '30', '9', '你 们 若 转 向 耶 和 华 ， 你 们 的 弟 兄 和 儿 女 必 在 掳 掠 他 们 的 人 面 前 蒙 怜 恤 ， 得 以 归 回 这 地 ， 因 为 耶 和 华 ─ ─ 你 们 的 神 有 恩 典 、 施 怜 悯 。 你 们 若 转 向 他 ， 他 必 不 转 脸 不 顾 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11838', '14', '30', '10', '驿 卒 就 由 这 城 跑 到 那 城 ， 传 遍 了 以 法 莲 、 玛 拿 西 ， 直 到 西 布 伦 。 那 里 的 人 却 戏 笑 他 们 ， 讥 诮 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11839', '14', '30', '11', '然 而 亚 设 、 玛 拿 西 、 西 布 伦 中 也 有 人 自 卑 ， 来 到 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11840', '14', '30', '12', '神 也 感 动 犹 大 人 ， 使 他 们 一 心 遵 行 王 与 众 首 领 凭 耶 和 华 之 言 所 发 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11841', '14', '30', '13', '＜ 守 逾 越 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11842', '14', '30', '14', '他 们 起 来 ， 把 耶 路 撒 冷 的 祭 坛 和 烧 香 的 坛 尽 都 除 去 ， 抛 在 汲 沦 溪 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11843', '14', '30', '15', '二 月 十 四 日 ， 宰 了 逾 越 节 的 羊 羔 。 祭 司 与 利 未 人 觉 得 惭 愧 ， 就 洁 净 自 己 ， 把 燔 祭 奉 到 耶 和 华 殿 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11844', '14', '30', '16', '遵 着 神 人 摩 西 的 律 法 ， 照 例 站 在 自 己 的 地 方 ； 祭 司 从 利 未 人 手 里 接 过 血 来 ， 洒 在 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11845', '14', '30', '17', '会 中 有 许 多 人 尚 未 自 洁 ， 所 以 利 未 人 为 一 切 不 洁 之 人 宰 逾 越 节 的 羊 羔 ， 使 他 们 在 耶 和 华 面 前 成 为 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11846', '14', '30', '18', '以 法 莲 、 玛 拿 西 、 以 萨 迦 、 西 布 伦 有 许 多 人 尚 未 自 洁 ， 他 们 却 也 吃 逾 越 节 的 羊 羔 ， 不 合 所 记 录 的 定 例 。 希 西 家 为 他 们 祷 告 说 ： “ 凡 专 心 寻 求 神 ， 就 是 耶 和 华 ─ ─ 他 列 祖 之 神 的 ， 虽 不 照 着 圣 所 洁 净 之 礼 自 洁 ， 求 至 善 的 耶 和 华 也 饶 恕 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11847', '14', '30', '19', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11848', '14', '30', '20', '耶 和 华 垂 听 希 西 家 的 祷 告 ， 就 饶 恕 ｛ 原 文 是 医 治 ｝ 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11849', '14', '30', '21', '在 耶 路 撒 冷 的 以 色 列 人 大 大 喜 乐 ， 守 除 酵 节 七 日 。 利 未 人 和 祭 司 用 响 亮 的 乐 器 ， 日 日 颂 赞 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11850', '14', '30', '22', '希 西 家 慰 劳 一 切 善 于 事 奉 耶 和 华 的 利 未 人 。 于 是 众 人 吃 节 筵 七 日 ， 又 献 平 安 祭 ， 且 向 耶 和 华 ─ ─ 他 们 列 祖 的 神 认 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11851', '14', '30', '23', '＜ 再 度 守 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11852', '14', '30', '24', '犹 大 王 希 西 家 赐 给 会 众 公 牛 一 千 只 ， 羊 七 千 只 为 祭 物 ； 众 首 领 也 赐 给 会 众 公 牛 一 千 只 ， 羊 一 万 只 ， 并 有 许 多 的 祭 司 洁 净 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11853', '14', '30', '25', '犹 大 全 会 众 、 祭 司 、 利 未 人 ， 并 那 从 以 色 列 地 来 的 会 众 和 寄 居 的 人 ， 以 及 犹 大 寄 居 的 人 ， 尽 都 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11854', '14', '30', '26', '这 样 ， 在 耶 路 撒 冷 大 有 喜 乐 ， 自 从 以 色 列 王 大 卫 儿 子 所 罗 门 的 时 候 ， 在 耶 路 撒 冷 没 有 这 样 的 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11855', '14', '30', '27', '那 时 ， 祭 司 、 利 未 人 起 来 ， 为 民 祝 福 。 他 们 的 声 音 蒙 神 垂 听 ， 他 们 的 祷 告 达 到 天 上 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11856', '14', '31', '1', '＜ 希 西 家 改 革 宗 教 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11857', '14', '31', '2', '希 西 家 派 定 祭 司 利 未 人 的 班 次 ， 各 按 各 职 献 燔 祭 和 平 安 祭 ， 又 在 耶 和 华 殿 ｛ 原 文 是 营 ｝ 门 内 事 奉 ， 称 谢 颂 赞 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11858', '14', '31', '3', '王 又 从 自 己 的 产 业 中 定 出 分 来 为 燔 祭 ， 就 是 早 晚 的 燔 祭 和 安 息 日 、 月 朔 ， 并 节 期 的 燔 祭 ， 都 是 按 耶 和 华 律 法 上 所 载 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11859', '14', '31', '4', '又 吩 咐 住 耶 路 撒 冷 的 百 姓 将 祭 司 、 利 未 人 所 应 得 的 分 给 他 们 ， 使 他 们 专 心 遵 守 耶 和 华 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11860', '14', '31', '5', '谕 旨 一 出 ， 以 色 列 人 就 把 初 熟 的 五 谷 、 新 酒 、 油 、 蜜 ， 和 田 地 的 出 产 多 多 送 来 ， 又 把 各 物 的 十 分 之 一 送 来 的 极 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11861', '14', '31', '6', '住 犹 大 各 城 的 以 色 列 人 和 犹 大 人 也 将 牛 羊 的 十 分 之 一 ， 并 分 别 为 圣 归 耶 和 华 ─ ─ 他 们 神 之 物 ， 就 是 十 分 取 一 之 物 ， 尽 都 送 来 ， 积 成 堆 垒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11862', '14', '31', '7', '从 三 月 积 起 ， 到 七 月 才 完 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11863', '14', '31', '8', '希 西 家 和 众 首 领 来 ， 看 见 堆 垒 ， 就 称 颂 耶 和 华 ， 又 为 耶 和 华 的 民 以 色 列 人 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11864', '14', '31', '9', '希 西 家 向 祭 司 、 利 未 人 查 问 这 堆 垒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11865', '14', '31', '10', '撒 督 家 的 大 祭 司 亚 撒 利 雅 回 答 说 ： “ 自 从 民 将 供 物 送 到 耶 和 华 殿 以 来 ， 我 们 不 但 吃 饱 ， 且 剩 下 的 甚 多 ； 因 为 耶 和 华 赐 福 给 他 的 民 ， 所 剩 下 的 才 这 样 丰 盛 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11866', '14', '31', '11', '希 西 家 吩 咐 在 耶 和 华 殿 里 预 备 仓 房 ， 他 们 就 预 备 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11867', '14', '31', '12', '他 们 诚 心 将 供 物 和 十 分 取 一 之 物 ， 并 分 别 为 圣 之 物 ， 都 搬 入 仓 内 。 利 未 人 歌 楠 雅 掌 管 这 事 ， 他 兄 弟 示 每 为 副 管 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11868', '14', '31', '13', '耶 歇 、 亚 撒 细 雅 、 拿 哈 、 亚 撒 黑 、 耶 利 末 、 约 撒 拔 、 以 列 、 伊 斯 玛 基 雅 、 玛 哈 、 比 拿 雅 都 是 督 理 ， 在 歌 楠 雅 和 他 兄 弟 示 每 的 手 下 ， 是 希 西 家 王 和 管 理 神 殿 的 亚 撒 利 雅 所 派 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11869', '14', '31', '14', '守 东 门 的 利 未 人 音 拿 的 儿 子 可 利 ， 掌 管 乐 意 献 与 神 的 礼 物 ， 发 放 献 与 耶 和 华 的 供 物 和 至 圣 的 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11870', '14', '31', '15', '在 他 手 下 有 伊 甸 、 岷 雅 岷 、 耶 书 亚 、 示 玛 雅 、 亚 玛 利 雅 、 示 迦 尼 雅 ， 在 祭 司 的 各 城 里 供 紧 要 的 职 任 ， 无 论 弟 兄 大 小 ， 都 按 着 班 次 分 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11871', '14', '31', '16', '按 家 谱 ， 三 岁 以 外 的 男 丁 ， 凡 每 日 进 耶 和 华 殿 、 按 班 次 供 职 的 ， 也 分 给 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11872', '14', '31', '17', '又 按 宗 族 家 谱 分 给 祭 司 ， 按 班 次 职 任 分 给 二 十 岁 以 外 的 利 未 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11873', '14', '31', '18', '又 按 家 谱 计 算 ， 分 给 他 们 会 中 的 妻 子 、 儿 女 ； 因 他 们 身 供 要 职 ， 自 洁 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11874', '14', '31', '19', '按 名 派 定 的 人 要 把 应 得 的 分 给 亚 伦 子 孙 ， 住 在 各 城 郊 野 、 祭 司 所 有 的 男 丁 和 一 切 载 入 家 谱 的 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11875', '14', '31', '20', '希 西 家 在 犹 大 遍 地 这 样 办 理 ， 行 耶 和 华 ─ ─ 他 神 眼 中 看 为 善 为 正 为 忠 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11876', '14', '31', '21', '凡 他 所 行 的 ， 无 论 是 办 神 殿 的 事 ， 是 遵 律 法 守 诫 命 ， 是 寻 求 他 的 神 ， 都 是 尽 心 去 行 ， 无 不 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11877', '14', '32', '1', '＜ 亚 述 人 恐 吓 耶 路 撒 冷 （ 王 下   1 8 : 1 3 - 3 7 ； 1 9 : 1 4 - 1 9 , 3 5 - 3 7 ； 赛   3 6 : 1 - 2 2 ； 3 7 : 8 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11878', '14', '32', '2', '希 西 家 见 西 拿 基 立 来 ， 定 意 要 攻 打 耶 路 撒 冷 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11879', '14', '32', '3', '就 与 首 领 和 勇 士 商 议 ， 塞 住 城 外 的 泉 源 ； 他 们 就 都 帮 助 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11880', '14', '32', '4', '于 是 有 许 多 人 聚 集 ， 塞 了 一 切 泉 源 ， 并 通 流 国 中 的 小 河 ， 说 ： “ 亚 述 王 来 ， 为 何 让 他 得 着 许 多 水 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11881', '14', '32', '5', '希 西 家 力 图 自 强 ， 就 修 筑 所 有 拆 毁 的 城 墙 ， 高 与 城 楼 相 齐 ； 在 城 外 又 筑 一 城 ， 坚 固 大 卫 城 的 米 罗 ， 制 造 了 许 多 军 器 、 盾 牌 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11882', '14', '32', '6', '设 立 军 长 管 理 百 姓 ， 将 他 们 招 聚 在 城 门 的 宽 阔 处 ， 用 话 勉 励 他 们 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11883', '14', '32', '7', '“ 你 们 当 刚 强 壮 胆 ， 不 要 因 亚 述 王 和 跟 随 他 的 大 军 恐 惧 、 惊 慌 ； 因 为 与 我 们 同 在 的 ， 比 与 他 们 同 在 的 更 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11884', '14', '32', '8', '与 他 们 同 在 的 是 肉 臂 ， 与 我 们 同 在 的 是 耶 和 华 ─ ─ 我 们 的 神 ， 他 必 帮 助 我 们 ， 为 我 们 争 战 。 ” 百 姓 就 靠 犹 大 王 希 西 家 的 话 ， 安 然 无 惧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11885', '14', '32', '9', '此 后 ， 亚 述 王 西 拿 基 立 和 他 的 全 军 攻 打 拉 吉 ， 就 差 遣 臣 仆 到 耶 路 撒 冷 见 犹 大 王 希 西 家 和 一 切 在 耶 路 撒 冷 的 犹 大 人 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11886', '14', '32', '10', '“ 亚 述 王 西 拿 基 立 如 此 说 ： ‘ 你 们 倚 靠 什 么 ， 还 在 耶 路 撒 冷 受 困 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11887', '14', '32', '11', '希 西 家 对 你 们 说 “ 耶 和 华 ─ ─ 我 们 的 神 必 救 我 们 脱 离 亚 述 王 的 手 ” ， 这 不 是 诱 惑 你 们 ， 使 你 们 受 饥 渴 而 死 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11888', '14', '32', '12', '这 希 西 家 岂 不 是 废 去 耶 和 华 的 邱 坛 和 祭 坛 ， 吩 咐 犹 大 与 耶 路 撒 冷 的 人 说 “ 你 们 当 在 一 个 坛 前 敬 拜 ， 在 其 上 烧 香 ” 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11889', '14', '32', '13', '我 与 我 列 祖 向 列 邦 所 行 的 ， 你 们 岂 不 知 道 吗 ？ 列 邦 的 神 何 尝 能 救 自 己 的 国 脱 离 我 手 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11890', '14', '32', '14', '我 列 祖 所 灭 的 国 ， 那 些 神 中 谁 能 救 自 己 的 民 脱 离 我 手 呢 ？ 难 道 你 们 的 神 能 救 你 们 脱 离 我 手 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11891', '14', '32', '15', '所 以 你 们 不 要 叫 希 西 家 这 样 欺 哄 诱 惑 你 们 ， 也 不 要 信 他 ； 因 为 没 有 一 国 一 邦 的 神 能 救 自 己 的 民 脱 离 我 手 和 我 列 祖 的 手 ， 何 况 你 们 的 神 更 不 能 救 你 们 脱 离 我 的 手 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11892', '14', '32', '16', '西 拿 基 立 的 臣 仆 还 有 别 的 话 毁 谤 耶 和 华 神 和 他 仆 人 希 西 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11893', '14', '32', '17', '西 拿 基 立 也 写 信 毁 谤 耶 和 华 ─ ─ 以 色 列 的 神 说 ： “ 列 邦 的 神 既 不 能 救 他 的 民 脱 离 我 手 ， 希 西 家 的 神 也 不 能 救 他 的 民 脱 离 我 手 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11894', '14', '32', '18', '亚 述 王 的 臣 仆 用 犹 大 言 语 向 耶 路 撒 冷 城 上 的 民 大 声 呼 叫 ， 要 惊 吓 他 们 ， 扰 乱 他 们 ， 以 便 取 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11895', '14', '32', '19', '他 们 论 耶 路 撒 冷 的 神 ， 如 同 论 世 上 人 手 所 造 的 神 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11896', '14', '32', '20', '希 西 家 王 和 亚 摩 斯 的 儿 子 先 知 以 赛 亚 因 此 祷 告 ， 向 天 呼 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11897', '14', '32', '21', '耶 和 华 就 差 遣 一 个 使 者 进 入 亚 述 王 营 中 ， 把 所 有 大 能 的 勇 士 和 官 长 、 将 帅 尽 都 灭 了 。 亚 述 王 满 面 含 羞 地 回 到 本 国 ， 进 了 他 神 的 庙 中 ， 有 他 亲 生 的 儿 子 在 那 里 用 刀 杀 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11898', '14', '32', '22', '这 样 ， 耶 和 华 救 希 西 家 和 耶 路 撒 冷 的 居 民 脱 离 亚 述 王 西 拿 基 立 的 手 ， 也 脱 离 一 切 仇 敌 的 手 ， 又 赐 他 们 四 境 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11899', '14', '32', '23', '有 许 多 人 到 耶 路 撒 冷 ， 将 供 物 献 与 耶 和 华 ， 又 将 宝 物 送 给 犹 大 王 希 西 家 。 此 后 ， 希 西 家 在 列 邦 人 的 眼 中 看 为 尊 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11900', '14', '32', '24', '＜ 希 西 家 的 疾 病 和 骄 傲 （ 王 下   2 0 : 1 - 3 , 1 2 - 1 9 ； 赛   3 8 : 1 - 3 ； 3 9 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11901', '14', '32', '25', '希 西 家 却 没 有 照 他 所 蒙 的 恩 报 答 耶 和 华 ； 因 他 心 里 骄 傲 ， 所 以 忿 怒 要 临 到 他 和 犹 大 并 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11902', '14', '32', '26', '但 希 西 家 和 耶 路 撒 冷 的 居 民 觉 得 心 里 骄 傲 ， 就 一 同 自 卑 ， 以 致 耶 和 华 的 忿 怒 在 希 西 家 的 日 子 没 有 临 到 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11903', '14', '32', '27', '＜ 希 西 家 的 财 富 和 尊 荣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11904', '14', '32', '28', '又 建 造 仓 房 ， 收 藏 五 谷 、 新 酒 ， 和 油 ， 又 为 各 类 牲 畜 盖 棚 立 圈 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11905', '14', '32', '29', '并 且 建 立 城 邑 ， 还 有 许 多 的 羊 群 牛 群 ， 因 为 神 赐 他 极 多 的 财 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11906', '14', '32', '30', '这 希 西 家 也 塞 住 基 训 的 上 源 ， 引 水 直 下 ， 流 在 大 卫 城 的 西 边 。 希 西 家 所 行 的 事 尽 都 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11907', '14', '32', '31', '惟 有 一 件 事 ， 就 是 巴 比 伦 王 差 遣 使 者 来 见 希 西 家 ， 访 问 国 中 所 现 的 奇 事 ； 这 件 事 神 离 开 他 ， 要 试 验 他 ， 好 知 道 他 心 内 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11908', '14', '32', '32', '＜ 希 西 家 逝 世 （ 王 下   2 0 : 2 0 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11909', '14', '32', '33', '希 西 家 与 他 列 祖 同 睡 ， 葬 在 大 卫 子 孙 的 高 陵 上 。 他 死 的 时 候 ， 犹 大 人 和 耶 路 撒 冷 的 居 民 都 尊 敬 他 。 他 儿 子 玛 拿 西 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11910', '14', '33', '1', '＜ 犹 大 国 的 王 玛 拿 西 （ 王 下   2 1 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11911', '14', '33', '2', '他 行 耶 和 华 眼 中 看 为 恶 的 事 ， 效 法 耶 和 华 在 以 色 列 人 面 前 赶 出 的 外 邦 人 那 可 憎 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11912', '14', '33', '3', '重 新 建 筑 他 父 希 西 家 所 拆 毁 的 邱 坛 ， 又 为 巴 力 筑 坛 ， 作 木 偶 ， 且 敬 拜 事 奉 天 上 的 万 象 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11913', '14', '33', '4', '在 耶 和 华 的 殿 宇 中 筑 坛 ─ ─ 耶 和 华 曾 指 着 这 殿 说 ： “ 我 的 名 必 永 远 在 耶 路 撒 冷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11914', '14', '33', '5', '他 在 耶 和 华 殿 的 两 院 中 为 天 上 的 万 象 筑 坛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11915', '14', '33', '6', '并 在 欣 嫩 子 谷 使 他 的 儿 女 经 火 ， 又 观 兆 ， 用 法 术 ， 行 邪 术 ， 立 交 鬼 的 和 行 巫 术 的 ， 多 行 耶 和 华 眼 中 看 为 恶 的 事 ， 惹 动 他 的 怒 气 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11916', '14', '33', '7', '又 在 神 殿 内 立 雕 刻 的 偶 像 。 神 曾 对 大 卫 和 他 儿 子 所 罗 门 说 ： “ 我 在 以 色 列 各 支 派 中 所 选 择 的 耶 路 撒 冷 和 这 殿 ， 必 立 我 的 名 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11917', '14', '33', '8', '以 色 列 人 若 谨 守 遵 行 我 藉 摩 西 所 吩 咐 他 们 的 一 切 法 度 、 律 例 、 典 章 ， 我 就 不 再 使 他 们 挪 移 离 开 我 所 赐 给 他 们 列 祖 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11918', '14', '33', '9', '玛 拿 西 引 诱 犹 大 和 耶 路 撒 冷 的 居 民 ， 以 致 他 们 行 恶 比 耶 和 华 在 以 色 列 人 面 前 所 灭 的 列 国 更 甚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11919', '14', '33', '10', '＜ 玛 拿 西 悔 改 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11920', '14', '33', '11', '所 以 耶 和 华 使 亚 述 王 的 将 帅 来 攻 击 他 们 ， 用 铙 钩 钩 住 玛 拿 西 ， 用 铜 链 锁 住 他 ， 带 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11921', '14', '33', '12', '他 在 急 难 的 时 候 ， 就 恳 求 耶 和 华 ─ ─ 他 的 神 ， 且 在 他 列 祖 的 神 面 前 极 其 自 卑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11922', '14', '33', '13', '他 祈 祷 耶 和 华 ， 耶 和 华 就 允 准 他 的 祈 求 ， 垂 听 他 的 祷 告 ， 使 他 归 回 耶 路 撒 冷 ， 仍 坐 国 位 。 玛 拿 西 这 才 知 道 惟 独 耶 和 华 是 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11923', '14', '33', '14', '此 后 ， 玛 拿 西 在 大 卫 城 外 ， 从 谷 内 基 训 西 边 直 到 鱼 门 口 ， 建 筑 城 墙 ， 环 绕 俄 斐 勒 ， 这 墙 筑 得 甚 高 ； 又 在 犹 大 各 坚 固 城 内 设 立 勇 敢 的 军 长 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11924', '14', '33', '15', '并 除 掉 外 邦 人 的 神 像 与 耶 和 华 殿 中 的 偶 像 ， 又 将 他 在 耶 和 华 殿 的 山 上 和 耶 路 撒 冷 所 筑 的 各 坛 都 拆 毁 抛 在 城 外 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11925', '14', '33', '16', '重 修 耶 和 华 的 祭 坛 ， 在 坛 上 献 平 安 祭 、 感 谢 祭 ， 吩 咐 犹 大 人 事 奉 耶 和 华 ─ ─ 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11926', '14', '33', '17', '百 姓 却 仍 在 邱 坛 上 献 祭 ， 只 献 给 耶 和 华 ─ ─ 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11927', '14', '33', '18', '＜ 玛 拿 西 逝 世 （ 王 下   2 1 : 1 7 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11928', '14', '33', '19', '他 的 祷 告 ， 与 神 怎 样 应 允 他 ， 他 未 自 卑 以 前 的 罪 愆 过 犯 ， 并 在 何 处 建 筑 邱 坛 ， 设 立 亚 舍 拉 和 雕 刻 的 偶 像 ， 都 写 在 何 赛 的 书 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11929', '14', '33', '20', '玛 拿 西 与 他 列 祖 同 睡 ， 葬 在 自 己 的 宫 院 里 。 他 儿 子 亚 们 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11930', '14', '33', '21', '＜ 犹 大 国 的 王 亚 们 （ 王 下   2 1 : 1 9 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11931', '14', '33', '22', '他 行 耶 和 华 眼 中 看 为 恶 的 事 ， 效 法 他 父 玛 拿 西 所 行 的 ， 祭 祀 事 奉 他 父 玛 拿 西 所 雕 刻 的 偶 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11932', '14', '33', '23', '不 在 耶 和 华 面 前 像 他 父 玛 拿 西 自 卑 。 这 亚 们 所 犯 的 罪 越 犯 越 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11933', '14', '33', '24', '他 的 臣 仆 背 叛 ， 在 宫 里 杀 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11934', '14', '33', '25', '但 国 民 杀 了 那 些 背 叛 亚 们 王 的 人 ， 立 他 儿 子 约 西 亚 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11935', '14', '34', '1', '＜ 犹 大 国 的 王 约 西 亚 （ 王 下   2 2 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11936', '14', '34', '2', '他 行 耶 和 华 眼 中 看 为 正 的 事 ， 效 法 他 祖 大 卫 所 行 的 ， 不 偏 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11937', '14', '34', '3', '＜ 约 西 亚 攻 击 异 教 崇 拜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11938', '14', '34', '4', '众 人 在 他 面 前 拆 毁 巴 力 的 坛 ， 砍 断 坛 上 高 高 的 日 像 ， 又 把 木 偶 和 雕 刻 的 像 ， 并 铸 造 的 像 打 碎 成 灰 ， 撒 在 祭 偶 像 人 的 坟 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11939', '14', '34', '5', '将 他 们 祭 司 的 骸 骨 烧 在 坛 上 ， 洁 净 了 犹 大 和 耶 路 撒 冷 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11940', '14', '34', '6', '又 在 玛 拿 西 、 以 法 莲 、 西 缅 、 拿 弗 他 利 各 城 ， 和 四 围 破 坏 之 处 ， 都 这 样 行 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11941', '14', '34', '7', '又 拆 毁 祭 坛 ， 把 木 偶 和 雕 刻 的 像 打 碎 成 灰 ， 砍 断 以 色 列 遍 地 所 有 的 日 像 ， 就 回 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11942', '14', '34', '8', '＜ 发 现 律 法 书 （ 王 下   2 2 : 3 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11943', '14', '34', '9', '他 们 就 去 见 大 祭 司 希 勒 家 ， 将 奉 到 神 殿 的 银 子 交 给 他 ； 这 银 子 是 看 守 殿 门 的 利 未 人 从 玛 拿 西 、 以 法 莲 ， 和 一 切 以 色 列 剩 下 的 人 ， 以 及 犹 大 、 便 雅 悯 众 人 ， 并 耶 路 撒 冷 的 居 民 收 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11944', '14', '34', '10', '又 将 这 银 子 交 给 耶 和 华 殿 里 督 工 的 ， 转 交 修 理 耶 和 华 殿 的 工 匠 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11945', '14', '34', '11', '就 是 交 给 木 匠 、 石 匠 ， 买 凿 成 的 石 头 和 架 木 与 栋 梁 ， 修 犹 大 王 所 毁 坏 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11946', '14', '34', '12', '这 些 人 办 事 诚 实 ， 督 工 的 是 利 未 人 米 拉 利 的 子 孙 雅 哈 、 俄 巴 底 ； 督 催 的 是 哥 辖 的 子 孙 撒 迦 利 亚 、 米 书 兰 ； 还 有 善 于 作 乐 的 利 未 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11947', '14', '34', '13', '他 们 又 监 管 扛 抬 的 人 ， 督 催 一 切 做 工 的 。 利 未 人 中 也 有 作 书 记 、 作 司 事 、 作 守 门 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11948', '14', '34', '14', '他 们 将 奉 到 耶 和 华 殿 的 银 子 运 出 来 的 时 候 ， 祭 司 希 勒 家 偶 然 得 了 摩 西 所 传 耶 和 华 的 律 法 书 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11949', '14', '34', '15', '希 勒 家 对 书 记 沙 番 说 ： “ 我 在 耶 和 华 殿 里 得 了 律 法 书 。 ” 遂 将 书 递 给 沙 番 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11950', '14', '34', '16', '沙 番 把 书 拿 到 王 那 里 ， 回 覆 王 说 ： “ 凡 交 给 仆 人 们 办 的 都 办 理 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11951', '14', '34', '17', '耶 和 华 殿 里 的 银 子 倒 出 来 ， 交 给 督 工 的 和 匠 人 的 手 里 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11952', '14', '34', '18', '书 记 沙 番 又 对 王 说 ： “ 祭 司 希 勒 家 递 给 我 一 卷 书 。 ” 沙 番 就 在 王 面 前 读 那 书 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11953', '14', '34', '19', '王 听 见 律 法 上 的 话 ， 就 撕 裂 衣 服 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11954', '14', '34', '20', '吩 咐 希 勒 家 与 沙 番 的 儿 子 亚 希 甘 、 米 迦 的 儿 子 亚 比 顿 、 书 记 沙 番 ， 和 王 的 臣 仆 亚 撒 雅 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11955', '14', '34', '21', '“ 你 们 去 为 我 、 为 以 色 列 和 犹 大 剩 下 的 人 ， 以 这 书 上 的 话 求 问 耶 和 华 ； 因 我 们 列 祖 没 有 遵 守 耶 和 华 的 言 语 ， 没 有 照 这 书 上 所 记 的 去 行 ， 耶 和 华 的 烈 怒 就 倒 在 我 们 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11956', '14', '34', '22', '于 是 ， 希 勒 家 和 王 所 派 的 众 人 都 去 见 女 先 知 户 勒 大 。 户 勒 大 是 掌 管 礼 服 沙 龙 的 妻 ， 沙 龙 是 哈 斯 拉 的 孙 子 、 特 瓦 的 儿 子 。 户 勒 大 住 在 耶 路 撒 冷 第 二 区 ； 他 们 请 问 于 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11957', '14', '34', '23', '她 对 他 们 说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： ‘ 你 们 可 以 回 覆 那 差 遣 你 们 来 见 我 的 人 说 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11958', '14', '34', '24', '耶 和 华 如 此 说 ： 我 必 照 着 在 犹 大 王 面 前 所 读 那 书 上 的 一 切 咒 诅 ， 降 祸 与 这 地 和 其 上 的 居 民 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11959', '14', '34', '25', '因 为 他 们 离 弃 我 ， 向 别 神 烧 香 ， 用 他 们 手 所 做 的 惹 我 发 怒 ， 所 以 我 的 忿 怒 如 火 倒 在 这 地 上 ， 总 不 熄 灭 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11960', '14', '34', '26', '然 而 差 遣 你 们 来 求 问 耶 和 华 的 犹 大 王 ， 你 们 要 这 样 回 覆 他 说 ： ‘ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 至 于 你 所 听 见 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11961', '14', '34', '27', '就 是 听 见 我 指 着 这 地 和 其 上 居 民 所 说 的 话 ， 你 便 心 里 敬 服 ， 在 我 面 前 自 卑 ， 撕 裂 衣 服 ， 向 我 哭 泣 ， 因 此 我 应 允 了 你 。 这 是 我 ─ ─ 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11962', '14', '34', '28', '我 必 使 你 平 平 安 安 地 归 到 坟 墓 ， 到 你 列 祖 那 里 ， 我 要 降 与 这 地 和 其 上 居 民 的 一 切 灾 祸 ， 你 也 不 致 亲 眼 看 见 。 ’ ” 他 们 就 回 覆 王 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11963', '14', '34', '29', '＜ 约 西 亚 立 约 顺 从 主 （ 王 下   2 3 : 1 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11964', '14', '34', '30', '王 和 犹 大 众 人 ， 与 耶 路 撒 冷 的 居 民 ， 并 祭 司 利 未 人 ， 以 及 所 有 的 百 姓 ， 无 论 大 小 ， 都 一 同 上 到 耶 和 华 的 殿 ； 王 就 把 殿 里 所 得 的 约 书 念 给 他 们 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11965', '14', '34', '31', '王 站 在 他 的 地 位 上 ， 在 耶 和 华 面 前 立 约 ， 要 尽 心 尽 性 地 顺 从 耶 和 华 ， 遵 守 他 的 诫 命 、 法 度 、 律 例 ， 成 就 这 书 上 所 记 的 约 言 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11966', '14', '34', '32', '又 使 住 耶 路 撒 冷 和 便 雅 悯 的 人 都 服 从 这 约 。 于 是 耶 路 撒 冷 的 居 民 都 遵 行 他 们 列 祖 之 神 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11967', '14', '34', '33', '约 西 亚 从 以 色 列 各 处 将 一 切 可 憎 之 物 尽 都 除 掉 ， 使 以 色 列 境 内 的 人 都 事 奉 耶 和 华 ─ ─ 他 们 的 神 。 约 西 亚 在 世 的 日 子 ， 就 跟 从 耶 和 华 ─ ─ 他 们 列 祖 的 神 ， 总 不 离 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11968', '14', '35', '1', '＜ 约 西 亚 守 逾 越 节 （ 王 下   2 3 : 2 1 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11969', '14', '35', '2', '王 分 派 祭 司 各 尽 其 职 ， 又 勉 励 他 们 办 耶 和 华 殿 中 的 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11970', '14', '35', '3', '又 对 那 归 耶 和 华 为 圣 、 教 训 以 色 列 人 的 利 未 人 说 ： “ 你 们 将 圣 约 柜 安 放 在 以 色 列 王 大 卫 儿 子 所 罗 门 建 造 的 殿 里 ， 不 必 再 用 肩 扛 抬 。 现 在 要 事 奉 耶 和 华 ─ ─ 你 们 的 神 ， 服 事 他 的 民 以 色 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11971', '14', '35', '4', '你 们 应 当 按 着 宗 族 ， 照 着 班 次 ， 遵 以 色 列 王 大 卫 和 他 儿 子 所 罗 门 所 写 的 ， 自 己 预 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11972', '14', '35', '5', '要 按 着 你 们 的 弟 兄 ， 这 民 宗 族 的 班 次 ， 站 在 圣 所 ， 每 班 中 要 利 未 宗 族 的 几 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11973', '14', '35', '6', '要 宰 逾 越 节 的 羊 羔 ， 洁 净 自 己 ， 为 你 们 的 弟 兄 预 备 了 ， 好 遵 守 耶 和 华 藉 摩 西 所 吩 咐 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11974', '14', '35', '7', '约 西 亚 从 群 畜 中 赐 给 在 那 里 所 有 的 人 民 ， 绵 羊 羔 和 山 羊 羔 三 万 只 ， 牛 三 千 只 ， 作 逾 越 节 的 祭 物 ； 这 都 是 出 自 王 的 产 业 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11975', '14', '35', '8', '约 西 亚 的 众 首 领 也 乐 意 将 牺 牲 给 百 姓 和 祭 司 利 未 人 ； 又 有 管 理 神 殿 的 希 勒 家 、 撒 迦 利 亚 、 耶 歇 将 羊 羔 二 千 六 百 只 ， 牛 三 百 只 ， 给 祭 司 作 逾 越 节 的 祭 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11976', '14', '35', '9', '利 未 人 的 族 长 歌 楠 雅 和 他 两 个 兄 弟 示 玛 雅 、 拿 坦 业 ， 与 哈 沙 比 雅 、 耶 利 、 约 撒 拔 将 羊 羔 五 千 只 ， 牛 五 百 只 ， 给 利 未 人 作 逾 越 节 的 祭 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11977', '14', '35', '10', '这 样 ， 供 献 的 事 齐 备 了 。 祭 司 站 在 自 己 的 地 方 ， 利 未 人 按 着 班 次 站 立 ， 都 是 照 王 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11978', '14', '35', '11', '利 未 人 宰 了 逾 越 节 的 羊 羔 ， 祭 司 从 他 们 手 里 接 过 血 来 洒 在 坛 上 ； 利 未 人 剥 皮 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11979', '14', '35', '12', '将 燔 祭 搬 来 ， 按 着 宗 族 的 班 次 分 给 众 民 ， 好 照 摩 西 书 上 所 写 的 ， 献 给 耶 和 华 ； 献 牛 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11980', '14', '35', '13', '他 们 按 着 常 例 ， 用 火 烤 逾 越 节 的 羊 羔 。 别 的 圣 物 用 锅 ， 用 釜 ， 用 罐 煮 了 ， 速 速 地 送 给 众 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11981', '14', '35', '14', '然 后 为 自 己 和 祭 司 预 备 祭 物 ； 因 为 祭 司 亚 伦 的 子 孙 献 燔 祭 和 脂 油 ， 直 到 晚 上 。 所 以 利 未 人 为 自 己 和 祭 司 亚 伦 的 子 孙 ， 预 备 祭 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11982', '14', '35', '15', '歌 唱 的 亚 萨 之 子 孙 ， 照 着 大 卫 、 亚 萨 、 希 幔 ， 和 王 的 先 见 耶 杜 顿 所 吩 咐 的 ， 站 在 自 己 的 地 位 上 。 守 门 的 看 守 各 门 ， 不 用 离 开 他 们 的 职 事 ， 因 为 他 们 的 弟 兄 利 未 人 给 他 们 预 备 祭 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11983', '14', '35', '16', '当 日 ， 供 奉 耶 和 华 的 事 齐 备 了 ， 就 照 约 西 亚 王 的 吩 咐 守 逾 越 节 ， 献 燔 祭 在 耶 和 华 的 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11984', '14', '35', '17', '当 时 在 耶 路 撒 冷 的 以 色 列 人 守 逾 越 节 ， 又 守 除 酵 节 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11985', '14', '35', '18', '自 从 先 知 撒 母 耳 以 来 ， 在 以 色 列 中 没 有 守 过 这 样 的 逾 越 节 ， 以 色 列 诸 王 也 没 有 守 过 ， 像 约 西 亚 、 祭 司 、 利 未 人 、 在 那 里 的 犹 大 人 ， 和 以 色 列 人 ， 以 及 耶 路 撒 冷 居 民 所 守 的 逾 越 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11986', '14', '35', '19', '这 逾 越 节 是 约 西 亚 作 王 十 八 年 守 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11987', '14', '35', '20', '＜ 约 西 亚 逝 世 （ 王 下   2 3 : 2 8 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11988', '14', '35', '21', '他 差 遣 使 者 来 见 约 西 亚 ， 说 ： “ 犹 大 王 啊 ， 我 与 你 何 干 ？ 我 今 日 来 不 是 要 攻 击 你 ， 乃 是 要 攻 击 与 我 争 战 之 家 ， 并 且 神 吩 咐 我 速 行 ， 你 不 要 干 预 神 的 事 ， 免 得 他 毁 灭 你 ， 因 为 神 是 与 我 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11989', '14', '35', '22', '约 西 亚 却 不 肯 转 去 离 开 他 ， 改 装 要 与 他 打 仗 ， 不 听 从 神 藉 尼 哥 之 口 所 说 的 话 ， 便 来 到 米 吉 多 平 原 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11990', '14', '35', '23', '弓 箭 手 射 中 约 西 亚 王 。 王 对 他 的 臣 仆 说 ： “ 我 受 了 重 伤 ， 你 拉 我 出 阵 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11991', '14', '35', '24', '他 的 臣 仆 扶 他 下 了 战 车 ， 上 了 次 车 ， 送 他 到 耶 路 撒 冷 ， 他 就 死 了 ， 葬 在 他 列 祖 的 坟 墓 里 。 犹 大 人 和 耶 路 撒 冷 人 都 为 他 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11992', '14', '35', '25', '耶 利 米 为 约 西 亚 作 哀 歌 。 所 有 歌 唱 的 男 女 也 唱 哀 歌 ， 追 悼 约 西 亚 ， 直 到 今 日 ； 而 且 在 以 色 列 中 成 了 定 例 。 这 歌 载 在 哀 歌 书 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11993', '14', '35', '26', '约 西 亚 其 余 的 事 和 他 遵 着 耶 和 华 律 法 上 所 记 而 行 的 善 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11994', '14', '35', '27', '并 他 自 始 至 终 所 行 的 ， 都 写 在 以 色 列 和 犹 大 列 王 记 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11995', '14', '36', '1', '＜ 犹 大 国 的 王 约 哈 斯 （ 王 下   2 3 : 3 0 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11996', '14', '36', '2', '约 哈 斯 登 基 的 时 候 年 二 十 三 岁 ， 在 耶 路 撒 冷 作 王 三 个 月 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11997', '14', '36', '3', '埃 及 王 在 耶 路 撒 冷 废 了 他 ， 又 罚 犹 大 国 银 子 一 百 他 连 得 ， 金 子 一 他 连 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11998', '14', '36', '4', '埃 及 王 尼 哥 立 约 哈 斯 的 哥 哥 以 利 雅 敬 作 犹 大 和 耶 路 撒 冷 的 王 ， 改 名 叫 约 雅 敬 ， 又 将 约 哈 斯 带 到 埃 及 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('11999', '14', '36', '5', '＜ 犹 大 国 的 王 约 雅 敬 （ 王 下   2 3 : 3 6 - 2 4 : 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12000', '14', '36', '6', '巴 比 伦 王 尼 布 甲 尼 撒 上 来 攻 击 他 ， 用 铜 链 锁 着 他 ， 要 将 他 带 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12001', '14', '36', '7', '尼 布 甲 尼 撒 又 将 耶 和 华 殿 里 的 器 皿 带 到 巴 比 伦 ， 放 在 他 神 的 庙 里 ｛ 或 译 ： 自 己 的 宫 里 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12002', '14', '36', '8', '约 雅 敬 其 余 的 事 和 他 所 行 可 憎 的 事 ， 并 他 一 切 的 行 为 ， 都 写 在 以 色 列 和 犹 大 列 王 记 上 。 他 儿 子 约 雅 斤 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12003', '14', '36', '9', '＜ 犹 大 国 的 王 约 雅 斤 （ 王 下   2 4 : 8 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12004', '14', '36', '10', '过 了 一 年 ， 尼 布 甲 尼 撒 差 遣 人 将 约 雅 斤 和 耶 和 华 殿 里 各 样 宝 贵 的 器 皿 带 到 巴 比 伦 ， 就 立 约 雅 斤 的 叔 叔 ｛ 原 文 是 兄 ｝ 西 底 家 作 犹 大 和 耶 路 撒 冷 的 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12005', '14', '36', '11', '＜ 犹 大 国 的 王 西 底 家 （ 王 下   2 4 : 1 8 - 2 0 ； 耶   5 2 : 1 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12006', '14', '36', '12', '行 耶 和 华 ─ ─ 他 神 眼 中 看 为 恶 的 事 。 先 知 耶 利 米 以 耶 和 华 的 话 劝 他 ， 他 仍 不 在 耶 利 米 面 前 自 卑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12007', '14', '36', '13', '＜ 耶 路 撒 冷 陷 落 （ 王 下   2 5 : 1 - 2 1 ； 耶   5 2 : 3 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12008', '14', '36', '14', '众 祭 司 长 和 百 姓 也 大 大 犯 罪 ， 效 法 外 邦 人 一 切 可 憎 的 事 ， 污 秽 耶 和 华 在 耶 路 撒 冷 分 别 为 圣 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12009', '14', '36', '15', '耶 和 华 ─ ─ 他 们 列 祖 的 神 因 为 爱 惜 自 己 的 民 和 他 的 居 所 ， 从 早 起 来 差 遣 使 者 去 警 戒 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12010', '14', '36', '16', '他 们 却 嘻 笑 神 的 使 者 ， 藐 视 他 的 言 语 ， 讥 诮 他 的 先 知 ， 以 致 耶 和 华 的 忿 怒 向 他 的 百 姓 发 作 ， 无 法 可 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12011', '14', '36', '17', '所 以 ， 耶 和 华 使 迦 勒 底 人 的 王 来 攻 击 他 们 ， 在 他 们 圣 殿 里 用 刀 杀 了 他 们 的 壮 丁 ， 不 怜 恤 他 们 的 少 男 处 女 、 老 人 白 叟 。 耶 和 华 将 他 们 都 交 在 迦 勒 底 王 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12012', '14', '36', '18', '迦 勒 底 王 将 神 殿 里 的 大 小 器 皿 与 耶 和 华 殿 里 的 财 宝 ， 并 王 和 众 首 领 的 财 宝 ， 都 带 到 巴 比 伦 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12013', '14', '36', '19', '迦 勒 底 人 焚 烧 神 的 殿 ， 拆 毁 耶 路 撒 冷 的 城 墙 ， 用 火 烧 了 城 里 的 宫 殿 ， 毁 坏 了 城 里 宝 贵 的 器 皿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12014', '14', '36', '20', '凡 脱 离 刀 剑 的 ， 迦 勒 底 王 都 掳 到 巴 比 伦 去 ， 作 他 和 他 子 孙 的 仆 婢 ， 直 到 波 斯 国 兴 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12015', '14', '36', '21', '这 就 应 验 耶 和 华 藉 耶 利 米 口 所 说 的 话 ： 地 享 受 安 息 ； 因 为 地 土 荒 凉 便 守 安 息 ， 直 满 了 七 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12016', '14', '36', '22', '＜ 塞 鲁 士 王 下 令 犹 大 人 返 国 （ 拉   1 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12017', '14', '36', '23', '“ 波 斯 王 塞 鲁 士 如 此 说 ： 耶 和 华 ─ ─ 天 上 的 神 已 将 天 下 万 国 赐 给 我 ， 又 嘱 咐 我 在 犹 大 的 耶 路 撒 冷 为 他 建 造 殿 宇 。 你 们 中 间 凡 作 他 子 民 的 ， 可 以 上 去 ， 愿 耶 和 华 ─ ─ 他 的 神 与 他 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12018', '15', '1', '1', '＜ 塞 鲁 士 王 下 令 犹 大 人 返 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12019', '15', '1', '2', '“ 波 斯 王 塞 鲁 士 如 此 说 ： ‘ 耶 和 华 天 上 的 神 已 将 天 下 万 国 赐 给 我 ， 又 嘱 咐 我 在 犹 大 的 耶 路 撒 冷 为 他 建 造 殿 宇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12020', '15', '1', '3', '在 你 们 中 间 凡 作 他 子 民 的 ， 可 以 上 犹 大 的 耶 路 撒 冷 ， 在 耶 路 撒 冷 重 建 耶 和 华 ─ ─ 以 色 列 神 的 殿 （ 只 有 他 是 神 ） 。 愿 神 与 这 人 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12021', '15', '1', '4', '凡 剩 下 的 人 ， 无 论 寄 居 何 处 ， 那 地 的 人 要 用 金 银 、 财 物 、 牲 畜 帮 助 他 ， 另 外 也 要 为 耶 路 撒 冷 神 的 殿 甘 心 献 上 礼 物 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12022', '15', '1', '5', '于 是 ， 犹 大 和 便 雅 悯 的 族 长 、 祭 司 、 利 未 人 ， 就 是 一 切 被 神 激 动 他 心 的 人 ， 都 起 来 要 上 耶 路 撒 冷 去 建 造 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12023', '15', '1', '6', '他 们 四 围 的 人 就 拿 银 器 、 金 子 、 财 物 、 牲 畜 、 珍 宝 帮 助 他 们 ｛ 原 文 是 坚 固 他 们 的 手 ｝ ， 另 外 还 有 甘 心 献 的 礼 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12024', '15', '1', '7', '塞 鲁 士 王 也 将 耶 和 华 殿 的 器 皿 拿 出 来 ， 这 器 皿 是 尼 布 甲 尼 撒 从 耶 路 撒 冷 掠 来 、 放 在 自 己 神 之 庙 中 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12025', '15', '1', '8', '波 斯 王 塞 鲁 士 派 库 官 米 提 利 达 将 这 器 皿 拿 出 来 ， 按 数 交 给 犹 大 的 首 领 设 巴 萨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12026', '15', '1', '9', '器 皿 的 数 目 记 在 下 面 ： 金 盘 三 十 个 ， 银 盘 一 千 个 ， 刀 二 十 九 把 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12027', '15', '1', '10', '金 碗 三 十 个 ， 银 碗 之 次 的 四 百 一 十 个 ， 别 样 的 器 皿 一 千 件 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12028', '15', '1', '11', '金 银 器 皿 共 有 五 千 四 百 件 。 被 掳 的 人 从 巴 比 伦 上 耶 路 撒 冷 的 时 候 ， 设 巴 萨 将 这 一 切 都 带 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12029', '15', '2', '1', '＜ 归 回 的 被 掳 者 名 单 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12030', '15', '2', '2', '他 们 是 同 着 所 罗 巴 伯 、 耶 书 亚 、 尼 希 米 、 西 莱 雅 、 利 来 雅 、 末 底 改 、 必 珊 、 米 斯 拔 、 比 革 瓦 伊 、 利 宏 、 巴 拿 回 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12031', '15', '2', '3', '以 色 列 人 民 的 数 目 记 在 下 面 ： 巴 录 的 子 孙 二 千 一 百 七 十 二 名 ；');
