INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12087', '15', '2', '59', '从 特 ． 米 拉 、 特 ． 哈 萨 、 基 绿 、 押 但 、 音 麦 上 来 的 ， 不 能 指 明 他 们 的 宗 族 谱 系 是 以 色 列 人 不 是 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12088', '15', '2', '60', '他 们 是 第 来 雅 的 子 孙 、 多 比 雅 的 子 孙 、 尼 哥 大 的 子 孙 ， 共 六 百 五 十 二 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12089', '15', '2', '61', '祭 司 中 ， 哈 巴 雅 的 子 孙 、 哈 哥 斯 的 子 孙 、 巴 西 莱 的 子 孙 ； 因 为 他 们 的 先 祖 娶 了 基 列 人 巴 西 莱 的 女 儿 为 妻 ， 所 以 起 名 叫 巴 西 莱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12090', '15', '2', '62', '这 三 家 的 人 在 族 谱 之 中 寻 查 自 己 的 谱 系 ， 却 寻 不 着 ， 因 此 算 为 不 洁 ， 不 准 供 祭 司 的 职 任 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12091', '15', '2', '63', '省 长 对 他 们 说 ： “ 不 可 吃 至 圣 的 物 ， 直 到 有 用 乌 陵 和 土 明 决 疑 的 祭 司 兴 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12092', '15', '2', '64', '会 众 共 有 四 万 二 千 三 百 六 十 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12093', '15', '2', '65', '此 外 ， 还 有 他 们 的 仆 婢 七 千 三 百 三 十 七 名 ， 又 有 歌 唱 的 男 女 二 百 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12094', '15', '2', '66', '他 们 有 马 七 百 三 十 六 匹 ， 骡 子 二 百 四 十 五 匹 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12095', '15', '2', '67', '骆 驼 四 百 三 十 五 只 ， 驴 六 千 七 百 二 十 匹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12096', '15', '2', '68', '有 些 族 长 到 了 耶 路 撒 冷 耶 和 华 殿 的 地 方 ， 便 为 神 的 殿 甘 心 献 上 礼 物 ， 要 重 新 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12097', '15', '2', '69', '他 们 量 力 捐 入 工 程 库 的 金 子 六 万 一 千 达 利 克 ， 银 子 五 千 弥 拿 ， 并 祭 司 的 礼 服 一 百 件 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12098', '15', '2', '70', '于 是 祭 司 、 利 未 人 、 民 中 的 一 些 人 、 歌 唱 的 、 守 门 的 、 尼 提 宁 ， 并 以 色 列 众 人 ， 各 住 在 自 己 的 城 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12099', '15', '3', '1', '＜ 恢 复 敬 拜 神 的 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12100', '15', '3', '2', '约 萨 达 的 儿 子 耶 书 亚 和 他 的 弟 兄 众 祭 司 ， 并 撒 拉 铁 的 儿 子 所 罗 巴 伯 与 他 的 弟 兄 ， 都 起 来 建 筑 以 色 列 神 的 坛 ， 要 照 神 人 摩 西 律 法 书 上 所 写 的 ， 在 坛 上 献 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12101', '15', '3', '3', '他 们 在 原 有 的 根 基 上 筑 坛 ， 因 惧 怕 邻 国 的 民 ， 又 在 其 上 向 耶 和 华 早 晚 献 燔 祭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12102', '15', '3', '4', '又 照 律 法 书 上 所 写 的 守 住 棚 节 ， 按 数 照 例 献 每 日 所 当 献 的 燔 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12103', '15', '3', '5', '其 后 献 常 献 的 燔 祭 ， 并 在 月 朔 与 耶 和 华 的 一 切 圣 节 献 祭 ， 又 向 耶 和 华 献 各 人 的 甘 心 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12104', '15', '3', '6', '从 七 月 初 一 日 起 ， 他 们 就 向 耶 和 华 献 燔 祭 。 但 耶 和 华 殿 的 根 基 尚 未 立 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12105', '15', '3', '7', '他 们 又 将 银 子 给 石 匠 、 木 匠 ， 把 粮 食 、 酒 、 油 给 西 顿 人 、 泰 尔 人 ， 使 他 们 将 香 柏 树 从 黎 巴 嫩 运 到 海 里 ， 浮 海 运 到 约 帕 ， 是 照 波 斯 王 塞 鲁 士 所 允 准 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12106', '15', '3', '8', '＜ 开 始 重 建 圣 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12107', '15', '3', '9', '于 是 犹 大 ｛ 在 二 章 四 十 节 作 何 达 威 雅 ｝ 的 后 裔 ， 就 是 耶 书 亚 和 他 的 子 孙 与 弟 兄 ， 甲 篾 和 他 的 子 孙 ， 利 未 人 希 拿 达 的 子 孙 与 弟 兄 ， 都 一 同 起 来 ， 督 理 那 在 神 殿 做 工 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12108', '15', '3', '10', '匠 人 立 耶 和 华 殿 根 基 的 时 候 ， 祭 司 皆 穿 礼 服 吹 号 ， 亚 萨 的 子 孙 利 未 人 敲 钹 ， 照 以 色 列 王 大 卫 所 定 的 例 ， 都 站 着 赞 美 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12109', '15', '3', '11', '他 们 彼 此 唱 和 ， 赞 美 称 谢 耶 和 华 说 ： 他 本 为 善 ， 他 向 以 色 列 人 永 发 慈 爱 。 他 们 赞 美 耶 和 华 的 时 候 ， 众 民 大 声 呼 喊 ， 因 耶 和 华 殿 的 根 基 已 经 立 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12110', '15', '3', '12', '然 而 有 许 多 祭 司 、 利 未 人 、 族 长 ， 就 是 见 过 旧 殿 的 老 年 人 ， 现 在 亲 眼 看 见 立 这 殿 的 根 基 ， 便 大 声 哭 号 ， 也 有 许 多 人 大 声 欢 呼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12111', '15', '3', '13', '甚 至 百 姓 不 能 分 辨 欢 呼 的 声 音 和 哭 号 的 声 音 ； 因 为 众 人 大 声 呼 喊 ， 声 音 听 到 远 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12112', '15', '4', '1', '＜ 建 殿 之 工 受 阻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12113', '15', '4', '2', '就 去 见 所 罗 巴 伯 和 以 色 列 的 族 长 ， 对 他 们 说 ： “ 请 容 我 们 与 你 们 一 同 建 造 ； 因 为 我 们 寻 求 你 们 的 神 ， 与 你 们 一 样 。 自 从 亚 述 王 以 撒 哈 顿 带 我 们 上 这 地 以 来 ， 我 们 常 祭 祀 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12114', '15', '4', '3', '但 所 罗 巴 伯 、 耶 书 亚 ， 和 其 余 以 色 列 的 族 长 对 他 们 说 ： “ 我 们 建 造 神 的 殿 与 你 们 无 干 ， 我 们 自 己 为 耶 和 华 ─ ─ 以 色 列 的 神 协 力 建 造 ， 是 照 波 斯 王 塞 鲁 士 所 吩 咐 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12115', '15', '4', '4', '那 地 的 民 ， 就 在 犹 大 人 建 造 的 时 候 ， 使 他 们 的 手 发 软 ， 扰 乱 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12116', '15', '4', '5', '从 波 斯 王 塞 鲁 士 年 间 ， 直 到 波 斯 王 大 流 士 登 基 的 时 候 ， 贿 买 谋 士 ， 要 败 坏 他 们 的 谋 算 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12117', '15', '4', '6', '＜ 阻 挡 重 建 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12118', '15', '4', '7', '亚 达 薛 西 年 间 ， 比 施 兰 、 米 特 利 达 、 他 别 ， 和 他 们 的 同 党 上 本 奏 告 波 斯 王 亚 达 薛 西 。 本 章 是 用 亚 兰 文 字 ， 亚 兰 方 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12119', '15', '4', '8', '省 长 利 宏 、 书 记 伸 帅 要 控 告 耶 路 撒 冷 人 ， 也 上 本 奏 告 亚 达 薛 西 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12120', '15', '4', '9', '省 长 利 宏 、 书 记 伸 帅 ， 和 同 党 的 底 拿 人 、 亚 法 萨 提 迦 人 、 他 毗 拉 人 、 亚 法 撒 人 、 亚 基 卫 人 、 巴 比 伦 人 、 书 珊 迦 人 、 底 亥 人 、 以 拦 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12121', '15', '4', '10', '和 尊 大 的 亚 斯 那 巴 所 迁 移 、 安 置 在 撒 马 利 亚 城 ， 并 大 河 西 一 带 地 方 的 人 等 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12122', '15', '4', '11', '上 奏 亚 达 薛 西 王 说 ： “ 河 西 的 臣 民 云 云 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12123', '15', '4', '12', '王 该 知 道 ， 从 王 那 里 上 到 我 们 这 里 的 犹 大 人 ， 已 经 到 耶 路 撒 冷 重 建 这 反 叛 恶 劣 的 城 ， 筑 立 根 基 ， 建 造 城 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12124', '15', '4', '13', '如 今 王 该 知 道 ， 他 们 若 建 造 这 城 ， 城 墙 完 毕 就 不 再 与 王 进 贡 ， 交 课 ， 纳 税 ， 终 久 王 必 受 亏 损 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12125', '15', '4', '14', '我 们 既 食 御 盐 ， 不 忍 见 王 吃 亏 ， 因 此 奏 告 于 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12126', '15', '4', '15', '请 王 考 察 先 王 的 实 录 ， 必 在 其 上 查 知 这 城 是 反 叛 的 城 ， 与 列 王 和 各 省 有 害 ； 自 古 以 来 ， 其 中 常 有 悖 逆 的 事 ， 因 此 这 城 曾 被 拆 毁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12127', '15', '4', '16', '我 们 谨 奏 王 知 ， 这 城 若 再 建 造 ， 城 墙 完 毕 ， 河 西 之 地 王 就 无 分 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12128', '15', '4', '17', '那 时 王 谕 覆 省 长 利 宏 、 书 记 伸 帅 ， 和 他 们 的 同 党 ， 就 是 住 撒 马 利 亚 并 河 西 一 带 地 方 的 人 ， 说 ： “ 愿 你 们 平 安 云 云 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12129', '15', '4', '18', '你 们 所 上 的 本 ， 已 经 明 读 在 我 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12130', '15', '4', '19', '我 已 命 人 考 查 ， 得 知 此 城 古 来 果 然 背 叛 列 王 ， 其 中 常 有 反 叛 悖 逆 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12131', '15', '4', '20', '从 前 耶 路 撒 冷 也 有 大 君 王 统 管 河 西 全 地 ， 人 就 给 他 们 进 贡 ， 交 课 ， 纳 税 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12132', '15', '4', '21', '现 在 你 们 要 出 告 示 命 这 些 人 停 工 ， 使 这 城 不 得 建 造 ， 等 我 降 旨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12133', '15', '4', '22', '你 们 当 谨 慎 ， 不 可 迟 延 ， 为 何 容 害 加 重 ， 使 王 受 亏 损 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12134', '15', '4', '23', '亚 达 薛 西 王 的 上 谕 读 在 利 宏 和 书 记 伸 帅 ， 并 他 们 的 同 党 面 前 ， 他 们 就 急 忙 往 耶 路 撒 冷 去 见 犹 大 人 ， 用 势 力 强 迫 他 们 停 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12135', '15', '4', '24', '＜ 恢 复 重 建 圣 殿 工 作 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12136', '15', '5', '1', '那 时 ， 先 知 哈 该 和 易 多 的 孙 子 撒 迦 利 亚 奉 以 色 列 神 的 名 向 犹 大 和 耶 路 撒 冷 的 犹 大 人 说 劝 勉 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12137', '15', '5', '2', '于 是 撒 拉 铁 的 儿 子 所 罗 巴 伯 和 约 萨 达 的 儿 子 耶 书 亚 都 起 来 动 手 建 造 耶 路 撒 冷 神 的 殿 ， 有 神 的 先 知 在 那 里 帮 助 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12138', '15', '5', '3', '当 时 河 西 的 总 督 达 乃 和 示 他 ． 波 斯 乃 ， 并 他 们 的 同 党 来 问 说 ： “ 谁 降 旨 让 你 们 建 造 这 殿 ， 修 成 这 墙 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12139', '15', '5', '4', '我 们 便 告 诉 他 们 建 造 这 殿 的 人 叫 什 么 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12140', '15', '5', '5', '神 的 眼 目 看 顾 犹 大 的 长 老 ， 以 致 总 督 等 没 有 叫 他 们 停 工 ， 直 到 这 事 奏 告 大 流 士 ， 得 着 他 的 回 谕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12141', '15', '5', '6', '河 西 的 总 督 达 乃 和 示 他 ． 波 斯 乃 ， 并 他 们 的 同 党 ， 就 是 住 河 西 的 亚 法 萨 迦 人 ， 上 本 奏 告 大 流 士 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12142', '15', '5', '7', '本 上 写 着 说 ： “ 愿 大 流 士 王 诸 事 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12143', '15', '5', '8', '王 该 知 道 ， 我 们 往 犹 大 省 去 ， 到 了 至 大 神 的 殿 ， 这 殿 是 用 大 石 建 造 的 。 梁 木 插 入 墙 内 ， 工 作 甚 速 ， 他 们 手 下 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12144', '15', '5', '9', '我 们 就 问 那 些 长 老 说 ： ‘ 谁 降 旨 让 你 们 建 造 这 殿 ， 修 成 这 墙 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12145', '15', '5', '10', '又 问 他 们 的 名 字 ， 要 记 录 他 们 首 领 的 名 字 ， 奏 告 于 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12146', '15', '5', '11', '他 们 回 答 说 ： ‘ 我 们 是 天 地 之 神 的 仆 人 ， 重 建 前 多 年 所 建 造 的 殿 ， 就 是 以 色 列 的 一 位 大 君 王 建 造 修 成 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12147', '15', '5', '12', '只 因 我 们 列 祖 惹 天 上 的 神 发 怒 ， 神 把 他 们 交 在 迦 勒 底 人 巴 比 伦 王 尼 布 甲 尼 撒 的 手 中 ， 他 就 拆 毁 这 殿 ， 又 将 百 姓 掳 到 巴 比 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12148', '15', '5', '13', '然 而 巴 比 伦 王 塞 鲁 士 元 年 ， 他 降 旨 允 准 建 造 神 的 这 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12149', '15', '5', '14', '神 殿 中 的 金 、 银 器 皿 ， 就 是 尼 布 甲 尼 撒 从 耶 路 撒 冷 的 殿 中 掠 去 带 到 巴 比 伦 庙 里 的 ， 塞 鲁 士 王 从 巴 比 伦 庙 里 取 出 来 ， 交 给 派 为 省 长 的 ， 名 叫 设 巴 萨 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12150', '15', '5', '15', '对 他 说 可 以 将 这 些 器 皿 带 去 ， 放 在 耶 路 撒 冷 的 殿 中 ， 在 原 处 建 造 神 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12151', '15', '5', '16', '于 是 这 设 巴 萨 来 建 立 耶 路 撒 冷 神 殿 的 根 基 。 这 殿 从 那 时 直 到 如 今 尚 未 造 成 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12152', '15', '5', '17', '现 在 王 若 以 为 美 ， 请 察 巴 比 伦 王 的 府 库 ， 看 塞 鲁 士 王 降 旨 允 准 在 耶 路 撒 冷 建 造 神 的 殿 没 有 ， 王 的 心 意 如 何 ？ 请 降 旨 晓 谕 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12153', '15', '6', '1', '＜ 发 现 塞 鲁 士 王 原 有 的 诏 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12154', '15', '6', '2', '在 米 底 亚 省 亚 马 他 城 的 宫 内 寻 得 一 卷 ， 其 中 记 着 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12155', '15', '6', '3', '“ 塞 鲁 士 王 元 年 ， 他 降 旨 论 到 耶 路 撒 冷 神 的 殿 ， 要 建 造 这 殿 为 献 祭 之 处 ， 坚 立 殿 的 根 基 。 殿 高 六 十 肘 ， 宽 六 十 肘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12156', '15', '6', '4', '用 三 层 大 石 头 ， 一 层 新 木 头 ， 经 费 要 出 于 王 库 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12157', '15', '6', '5', '并 且 神 殿 的 金 银 器 皿 ， 就 是 尼 布 甲 尼 撒 从 耶 路 撒 冷 的 殿 中 掠 到 巴 比 伦 的 ， 要 归 还 带 到 耶 路 撒 冷 的 殿 中 ， 各 按 原 处 放 在 神 的 殿 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12158', '15', '6', '6', '＜ 大 流 士 王 下 令 继 续 建 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12159', '15', '6', '7', '不 要 拦 阻 神 殿 的 工 作 ， 任 凭 犹 大 人 的 省 长 和 犹 大 人 的 长 老 在 原 处 建 造 神 的 这 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12160', '15', '6', '8', '我 又 降 旨 ， 吩 咐 你 们 向 犹 大 人 的 长 老 为 建 造 神 的 殿 当 怎 样 行 ， 就 是 从 河 西 的 款 项 中 ， 急 速 拨 取 贡 银 作 他 们 的 经 费 ， 免 得 耽 误 工 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12161', '15', '6', '9', '他 们 与 天 上 的 神 献 燔 祭 所 需 用 的 公 牛 犊 、 公 绵 羊 、 绵 羊 羔 ， 并 所 用 的 麦 子 、 盐 、 酒 、 油 ， 都 要 照 耶 路 撒 冷 祭 司 的 话 ， 每 日 供 给 他 们 ， 不 得 有 误 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12162', '15', '6', '10', '好 叫 他 们 献 馨 香 的 祭 给 天 上 的 神 ， 又 为 王 和 王 众 子 的 寿 命 祈 祷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12163', '15', '6', '11', '我 再 降 旨 ， 无 论 谁 更 改 这 命 令 ， 必 从 他 房 屋 中 拆 出 一 根 梁 来 ， 把 他 举 起 ， 悬 在 其 上 ， 又 使 他 的 房 屋 成 为 粪 堆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12164', '15', '6', '12', '若 有 王 和 民 伸 手 更 改 这 命 令 ， 拆 毁 这 殿 ， 愿 那 使 耶 路 撒 冷 的 殿 作 为 他 名 居 所 的 神 将 他 们 灭 绝 。 我 ─ ─ 大 流 士 降 这 旨 意 ， 当 速 速 遵 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12165', '15', '6', '13', '＜ 圣 殿 奉 献 典 礼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12166', '15', '6', '14', '犹 大 长 老 因 先 知 哈 该 和 易 多 的 孙 子 撒 迦 利 亚 所 说 劝 勉 的 话 就 建 造 这 殿 ， 凡 事 亨 通 。 他 们 遵 着 以 色 列 神 的 命 令 和 波 斯 王 塞 鲁 士 、 大 流 士 、 亚 达 薛 西 的 旨 意 ， 建 造 完 毕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12167', '15', '6', '15', '大 流 士 王 第 六 年 ， 亚 达 月 初 三 日 ， 这 殿 修 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12168', '15', '6', '16', '以 色 列 的 祭 司 和 利 未 人 ， 并 其 余 被 掳 归 回 的 人 都 欢 欢 喜 喜 地 行 奉 献 神 殿 的 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12169', '15', '6', '17', '行 奉 献 神 殿 的 礼 就 献 公 牛 一 百 只 ， 公 绵 羊 二 百 只 ， 绵 羊 羔 四 百 只 ， 又 照 以 色 列 支 派 的 数 目 献 公 山 羊 十 二 只 ， 为 以 色 列 众 人 作 赎 罪 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12170', '15', '6', '18', '且 派 祭 司 和 利 未 人 按 着 班 次 在 耶 路 撒 冷 事 奉 神 ， 是 照 摩 西 律 法 书 上 所 写 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12171', '15', '6', '19', '＜ 守 逾 越 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12172', '15', '6', '20', '原 来 ， 祭 司 和 利 未 人 一 同 自 洁 ， 无 一 人 不 洁 净 。 利 未 人 为 被 掳 归 回 的 众 人 和 他 们 的 弟 兄 众 祭 司 ， 并 为 自 己 宰 逾 越 节 的 羊 羔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12173', '15', '6', '21', '从 掳 到 之 地 归 回 的 以 色 列 人 和 一 切 除 掉 所 染 外 邦 人 污 秽 、 归 附 他 们 、 要 寻 求 耶 和 华 ─ ─ 以 色 列 神 的 人 都 吃 这 羊 羔 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12174', '15', '6', '22', '欢 欢 喜 喜 地 守 除 酵 节 七 日 ； 因 为 耶 和 华 使 他 们 欢 喜 ， 又 使 亚 述 王 的 心 转 向 他 们 ， 坚 固 他 们 的 手 ， 作 以 色 列 神 殿 的 工 程 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12175', '15', '7', '1', '＜ 以 斯 拉 到 达 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12176', '15', '7', '2', '希 勒 家 是 沙 龙 的 儿 子 ， 沙 龙 是 撒 督 的 儿 子 ， 撒 督 是 亚 希 突 的 儿 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12177', '15', '7', '3', '亚 希 突 是 亚 玛 利 雅 的 儿 子 ， 亚 玛 利 雅 是 亚 撒 利 雅 的 儿 子 ， 亚 撒 利 雅 是 米 拉 约 的 儿 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12178', '15', '7', '4', '米 拉 约 是 西 拉 希 雅 的 儿 子 ， 西 拉 希 雅 是 乌 西 的 儿 子 ， 乌 西 是 布 基 的 儿 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12179', '15', '7', '5', '布 基 是 亚 比 书 的 儿 子 ， 亚 比 书 是 非 尼 哈 的 儿 子 ， 非 尼 哈 是 以 利 亚 撒 的 儿 子 ， 以 利 亚 撒 是 大 祭 司 亚 伦 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12180', '15', '7', '6', '这 以 斯 拉 从 巴 比 伦 上 来 ， 他 是 敏 捷 的 文 士 ， 通 达 耶 和 华 ─ ─ 以 色 列 神 所 赐 摩 西 的 律 法 书 。 王 允 准 他 一 切 所 求 的 ， 是 因 耶 和 华 ─ ─ 他 神 的 手 帮 助 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12181', '15', '7', '7', '亚 达 薛 西 王 第 七 年 ， 以 色 列 人 、 祭 司 、 利 未 人 、 歌 唱 的 、 守 门 的 、 尼 提 宁 ， 有 上 耶 路 撒 冷 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12182', '15', '7', '8', '王 第 七 年 五 月 ， 以 斯 拉 到 了 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12183', '15', '7', '9', '正 月 初 一 日 ， 他 从 巴 比 伦 起 程 ； 因 他 神 施 恩 的 手 帮 助 他 ， 五 月 初 一 日 就 到 了 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12184', '15', '7', '10', '以 斯 拉 定 志 考 究 遵 行 耶 和 华 的 律 法 ， 又 将 律 例 典 章 教 训 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12185', '15', '7', '11', '＜ 亚 达 薛 西 王 给 以 斯 拉 的 文 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12186', '15', '7', '12', '“ 诸 王 之 王 亚 达 薛 西 ， 达 于 祭 司 以 斯 拉 通 达 天 上 神 律 法 大 德 的 文 士 ， 云 云 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12187', '15', '7', '13', '住 在 我 国 中 的 以 色 列 人 、 祭 司 、 利 未 人 ， 凡 甘 心 上 耶 路 撒 冷 去 的 ， 我 降 旨 准 他 们 与 你 同 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12188', '15', '7', '14', '王 与 七 个 谋 士 既 然 差 你 去 ， 照 你 手 中 神 的 律 法 书 察 问 犹 大 和 耶 路 撒 冷 的 景 况 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12189', '15', '7', '15', '又 带 金 银 ， 就 是 王 和 谋 士 甘 心 献 给 住 耶 路 撒 冷 、 以 色 列 神 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12190', '15', '7', '16', '并 带 你 在 巴 比 伦 全 省 所 得 的 金 银 ， 和 百 姓 、 祭 司 乐 意 献 给 耶 路 撒 冷 ─ ─ 他 们 神 殿 的 礼 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12191', '15', '7', '17', '所 以 你 当 用 这 金 银 ， 急 速 买 公 牛 、 公 绵 羊 、 绵 羊 羔 ， 和 同 献 的 素 祭 奠 祭 之 物 ， 献 在 耶 路 撒 冷 ─ ─ 你 们 神 殿 的 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12192', '15', '7', '18', '剩 下 的 金 银 ， 你 和 你 的 弟 兄 看 着 怎 样 好 ， 就 怎 样 用 ， 总 要 遵 着 你 们 神 的 旨 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12193', '15', '7', '19', '所 交 给 你 神 殿 中 使 用 的 器 皿 ， 你 要 交 在 耶 路 撒 冷 神 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12194', '15', '7', '20', '你 神 殿 里 若 再 有 需 用 的 经 费 ， 你 可 以 从 王 的 府 库 里 支 取 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12195', '15', '7', '21', '“ 我 ─ ─ 亚 达 薛 西 王 又 降 旨 与 河 西 的 一 切 库 官 ， 说 ： ‘ 通 达 天 上 神 律 法 的 文 士 祭 司 以 斯 拉 ， 无 论 向 你 们 要 什 么 ， 你 们 要 速 速 地 备 办 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12196', '15', '7', '22', '就 是 银 子 直 到 一 百 他 连 得 ， 麦 子 一 百 柯 珥 ， 酒 一 百 罢 特 ， 油 一 百 罢 特 ， 盐 不 计 其 数 ， 也 要 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12197', '15', '7', '23', '凡 天 上 之 神 所 吩 咐 的 ， 当 为 天 上 神 的 殿 详 细 办 理 。 为 何 使 忿 怒 临 到 王 和 王 众 子 的 国 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12198', '15', '7', '24', '我 又 晓 谕 你 们 ， 至 于 祭 司 、 利 未 人 、 歌 唱 的 、 守 门 的 ， 和 尼 提 宁 ， 并 在 神 殿 当 差 的 人 ， 不 可 叫 他 们 进 贡 ， 交 课 ， 纳 税 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12199', '15', '7', '25', '“ 以 斯 拉 啊 ， 要 照 着 你 神 赐 你 的 智 慧 ， 将 所 有 明 白 你 神 律 法 的 人 立 为 士 师 、 审 判 官 ， 治 理 河 西 的 百 姓 ， 使 他 们 教 训 一 切 不 明 白 神 律 法 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12200', '15', '7', '26', '凡 不 遵 行 你 神 律 法 和 王 命 令 的 人 就 当 速 速 定 他 的 罪 ， 或 治 死 ， 或 充 军 ， 或 抄 家 ， 或 囚 禁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12201', '15', '7', '27', '＜ 以 斯 拉 称 颂 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12202', '15', '7', '28', '又 在 王 和 谋 士 ， 并 大 能 的 军 长 面 前 施 恩 于 我 。 因 耶 和 华 ─ ─ 我 神 的 手 帮 助 我 ， 我 就 得 以 坚 强 ， 从 以 色 列 中 招 聚 首 领 ， 与 我 一 同 上 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12203', '15', '8', '1', '＜ 从 被 掳 之 地 回 来 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12204', '15', '8', '2', '属 非 尼 哈 的 子 孙 有 革 顺 ； 属 以 他 玛 的 子 孙 有 但 以 理 ； 属 大 卫 的 子 孙 有 哈 突 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12205', '15', '8', '3', '属 巴 录 的 后 裔 ， 就 是 示 迦 尼 的 子 孙 有 撒 迦 利 亚 ， 同 着 他 ， 按 家 谱 计 算 ， 男 丁 一 百 五 十 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12206', '15', '8', '4', '属 巴 哈 ． 摩 押 的 子 孙 有 西 拉 希 雅 的 儿 子 以 利 约 乃 ， 同 着 他 有 男 丁 二 百 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12207', '15', '8', '5', '属 示 迦 尼 的 子 孙 有 雅 哈 悉 的 儿 子 ， 同 着 他 有 男 丁 三 百 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12208', '15', '8', '6', '属 亚 丁 的 子 孙 有 约 拿 单 的 儿 子 以 别 ， 同 着 他 有 男 丁 五 十 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12209', '15', '8', '7', '属 以 拦 的 子 孙 有 亚 他 利 雅 的 儿 子 耶 筛 亚 ， 同 着 他 有 男 丁 七 十 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12210', '15', '8', '8', '属 示 法 提 雅 的 子 孙 有 米 迦 勒 的 儿 子 西 巴 第 雅 ， 同 着 他 有 男 丁 八 十 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12211', '15', '8', '9', '属 约 押 的 子 孙 有 耶 歇 的 儿 子 俄 巴 底 亚 ， 同 着 他 有 男 丁 二 百 一 十 八 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12212', '15', '8', '10', '属 示 罗 密 的 子 孙 有 约 细 斐 的 儿 子 ， 同 着 他 有 男 丁 一 百 六 十 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12213', '15', '8', '11', '属 比 拜 的 子 孙 有 比 拜 的 儿 子 撒 迦 利 亚 ， 同 着 他 有 男 丁 二 十 八 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12214', '15', '8', '12', '属 押 甲 的 子 孙 有 哈 加 坦 的 儿 子 约 哈 难 ， 同 着 他 有 男 丁 一 百 一 十 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12215', '15', '8', '13', '属 亚 多 尼 干 的 子 孙 ， 就 是 末 尾 的 ， 他 们 的 名 字 是 以 利 法 列 、 耶 利 、 示 玛 雅 ， 同 着 他 们 有 男 丁 六 十 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12216', '15', '8', '14', '属 比 革 瓦 伊 的 子 孙 有 乌 太 和 撒 布 ， 同 着 他 们 有 男 丁 七 十 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12217', '15', '8', '15', '＜ 以 斯 拉 为 圣 殿 招 集 利 未 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12218', '15', '8', '16', '就 召 首 领 以 利 以 谢 、 亚 列 、 示 玛 雅 、 以 利 拿 单 、 雅 立 、 以 利 拿 单 、 拿 单 、 撒 迦 利 亚 、 米 书 兰 ， 又 召 教 习 约 雅 立 和 以 利 拿 单 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12219', '15', '8', '17', '我 打 发 他 们 往 迦 西 斐 雅 地 方 去 见 那 里 的 首 领 易 多 ， 又 告 诉 他 们 当 向 易 多 和 他 的 弟 兄 尼 提 宁 说 什 么 话 ， 叫 他 们 为 我 们 神 的 殿 带 使 用 的 人 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12220', '15', '8', '18', '蒙 我 们 神 施 恩 的 手 帮 助 我 们 ， 他 们 在 以 色 列 的 曾 孙 、 利 未 的 孙 子 、 抹 利 的 后 裔 中 带 一 个 通 达 人 来 ； 还 有 示 利 比 和 他 的 众 子 与 弟 兄 共 一 十 八 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12221', '15', '8', '19', '又 有 哈 沙 比 雅 ， 同 着 他 有 米 拉 利 的 子 孙 耶 筛 亚 ， 并 他 的 众 子 和 弟 兄 共 二 十 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12222', '15', '8', '20', '从 前 大 卫 和 众 首 领 派 尼 提 宁 服 事 利 未 人 ， 现 在 从 这 尼 提 宁 中 也 带 了 二 百 二 十 人 来 ， 都 是 按 名 指 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12223', '15', '8', '21', '＜ 以 斯 拉 领 导 人 民 禁 食 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12224', '15', '8', '22', '我 求 王 拨 步 兵 马 兵 帮 助 我 们 抵 挡 路 上 的 仇 敌 ， 本 以 为 羞 耻 ； 因 我 曾 对 王 说 ： “ 我 们 神 施 恩 的 手 必 帮 助 一 切 寻 求 他 的 ； 但 他 的 能 力 和 忿 怒 必 攻 击 一 切 离 弃 他 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12225', '15', '8', '23', '所 以 我 们 禁 食 祈 求 我 们 的 神 ， 他 就 应 允 了 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12226', '15', '8', '24', '＜ 献 给 圣 殿 的 礼 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12227', '15', '8', '25', '将 王 和 谋 士 、 军 长 ， 并 在 那 里 的 以 色 列 众 人 为 我 们 神 殿 所 献 的 金 银 和 器 皿 ， 都 秤 了 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12228', '15', '8', '26', '我 秤 了 交 在 他 们 手 中 的 银 子 有 六 百 五 十 他 连 得 ； 银 器 重 一 百 他 连 得 ； 金 子 一 百 他 连 得 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12229', '15', '8', '27', '金 碗 二 十 个 ， 重 一 千 达 利 克 ； 上 等 光 铜 的 器 皿 两 个 ， 宝 贵 如 金 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12230', '15', '8', '28', '我 对 他 们 说 ： “ 你 们 归 耶 和 华 为 圣 ， 器 皿 也 为 圣 ； 金 银 是 甘 心 献 给 耶 和 华 ─ ─ 你 们 列 祖 之 神 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12231', '15', '8', '29', '你 们 当 警 醒 看 守 ， 直 到 你 们 在 耶 路 撒 冷 耶 和 华 殿 的 库 内 ， 在 祭 司 长 和 利 未 族 长 ， 并 以 色 列 的 各 族 长 面 前 过 了 秤 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12232', '15', '8', '30', '于 是 ， 祭 司 、 利 未 人 按 着 分 量 接 受 金 银 和 器 皿 ， 要 带 到 耶 路 撒 冷 我 们 神 的 殿 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12233', '15', '8', '31', '＜ 返 回 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12234', '15', '8', '32', '我 们 到 了 耶 路 撒 冷 ， 在 那 里 住 了 三 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12235', '15', '8', '33', '第 四 日 ， 在 我 们 神 的 殿 里 把 金 银 和 器 皿 都 秤 了 ， 交 在 祭 司 乌 利 亚 的 儿 子 米 利 末 的 手 中 。 同 着 他 有 非 尼 哈 的 儿 子 以 利 亚 撒 ， 还 有 利 未 人 耶 书 亚 的 儿 子 约 撒 拔 和 宾 内 的 儿 子 挪 亚 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12236', '15', '8', '34', '当 时 都 点 了 数 目 ， 按 着 分 量 写 在 册 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12237', '15', '8', '35', '从 掳 到 之 地 归 回 的 人 向 以 色 列 的 神 献 燔 祭 ， 就 是 为 以 色 列 众 人 献 公 牛 十 二 只 ， 公 绵 羊 九 十 六 只 ， 绵 羊 羔 七 十 七 只 ， 又 献 公 山 羊 十 二 只 作 赎 罪 祭 ， 这 都 是 向 耶 和 华 焚 献 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12238', '15', '8', '36', '他 们 将 王 的 谕 旨 交 给 王 所 派 的 总 督 与 河 西 的 省 长 ， 他 们 就 帮 助 百 姓 ， 又 供 给 神 殿 里 所 需 用 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12239', '15', '9', '1', '＜ 以 斯 拉 知 道 有 人 与 异 族 通 婚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12240', '15', '9', '2', '因 他 们 为 自 己 和 儿 子 娶 了 这 些 外 邦 女 子 为 妻 ， 以 致 圣 洁 的 种 类 和 这 些 国 的 民 混 杂 ； 而 且 首 领 和 官 长 在 这 事 上 为 罪 魁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12241', '15', '9', '3', '我 一 听 见 这 事 ， 就 撕 裂 衣 服 和 外 袍 ， 拔 了 头 发 和 胡 须 ， 惊 惧 忧 闷 而 坐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12242', '15', '9', '4', '凡 为 以 色 列 神 言 语 战 兢 的 ， 都 因 这 被 掳 归 回 之 人 所 犯 的 罪 聚 集 到 我 这 里 来 。 我 就 惊 惧 忧 闷 而 坐 ， 直 到 献 晚 祭 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12243', '15', '9', '5', '献 晚 祭 的 时 候 我 起 来 ， 心 中 愁 苦 ， 穿 着 撕 裂 的 衣 袍 ， 双 膝 跪 下 向 耶 和 华 ─ ─ 我 的 神 举 手 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12244', '15', '9', '6', '说 ： “ 我 的 神 啊 ， 我 抱 愧 蒙 羞 ， 不 敢 向 我 神 仰 面 ； 因 为 我 们 的 罪 孽 灭 顶 ， 我 们 的 罪 恶 滔 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12245', '15', '9', '7', '从 我 们 列 祖 直 到 今 日 ， 我 们 的 罪 恶 甚 重 ； 因 我 们 的 罪 孽 ， 我 们 和 君 王 、 祭 司 都 交 在 外 邦 列 王 的 手 中 ， 杀 害 、 掳 掠 、 抢 夺 、 脸 上 蒙 羞 正 如 今 日 的 光 景 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12246', '15', '9', '8', '现 在 耶 和 华 ─ ─ 我 们 的 神 暂 且 施 恩 与 我 们 ， 给 我 们 留 些 逃 脱 的 人 ， 使 我 们 安 稳 如 钉 子 钉 在 他 的 圣 所 ， 我 们 的 神 好 光 照 我 们 的 眼 目 ， 使 我 们 在 受 辖 制 之 中 稍 微 复 兴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12247', '15', '9', '9', '我 们 是 奴 仆 ， 然 而 在 受 辖 制 之 中 ， 我 们 的 神 仍 没 有 丢 弃 我 们 ， 在 波 斯 王 眼 前 向 我 们 施 恩 ， 叫 我 们 复 兴 ， 能 重 建 我 们 神 的 殿 ， 修 其 毁 坏 之 处 ， 使 我 们 在 犹 大 和 耶 路 撒 冷 有 墙 垣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12248', '15', '9', '10', '“ 我 们 的 神 啊 ， 既 是 如 此 ， 我 们 还 有 什 么 话 可 说 呢 ？ 因 为 我 们 已 经 离 弃 你 的 命 令 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12249', '15', '9', '11', '就 是 你 藉 你 仆 人 众 先 知 所 吩 咐 的 说 ： ‘ 你 们 要 去 得 为 业 之 地 是 污 秽 之 地 ； 因 列 国 之 民 的 污 秽 和 可 憎 的 事 ， 叫 全 地 从 这 边 直 到 那 边 满 了 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12250', '15', '9', '12', '所 以 不 可 将 你 们 的 女 儿 嫁 他 们 的 儿 子 ， 也 不 可 为 你 们 的 儿 子 娶 他 们 的 女 儿 ， 永 不 可 求 他 们 的 平 安 和 他 们 的 利 益 ， 这 样 你 们 就 可 以 强 盛 ， 吃 这 地 的 美 物 ， 并 遗 留 这 地 给 你 们 的 子 孙 永 远 为 业 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12251', '15', '9', '13', '神 啊 ， 我 们 因 自 己 的 恶 行 和 大 罪 ， 遭 遇 了 这 一 切 的 事 ， 并 且 你 刑 罚 我 们 轻 于 我 们 罪 所 当 得 的 ， 又 给 我 们 留 下 这 些 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12252', '15', '9', '14', '我 们 岂 可 再 违 背 你 的 命 令 ， 与 这 行 可 憎 之 事 的 民 结 亲 呢 ？ 若 这 样 行 ， 你 岂 不 向 我 们 发 怒 ， 将 我 们 灭 绝 ， 以 致 没 有 一 个 剩 下 逃 脱 的 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12253', '15', '9', '15', '耶 和 华 ─ ─ 以 色 列 的 神 啊 ， 因 你 是 公 义 的 ， 我 们 这 剩 下 的 人 才 得 逃 脱 ， 正 如 今 日 的 光 景 。 看 哪 ， 我 们 在 你 面 前 有 罪 恶 ， 因 此 无 人 在 你 面 前 站 立 得 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12254', '15', '10', '1', '＜ 终 止 杂 婚 的 方 案 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12255', '15', '10', '2', '属 以 拦 的 子 孙 、 耶 歇 的 儿 子 示 迦 尼 对 以 斯 拉 说 ： “ 我 们 在 此 地 娶 了 外 邦 女 子 为 妻 ， 干 犯 了 我 们 的 神 ， 然 而 以 色 列 人 还 有 指 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12256', '15', '10', '3', '现 在 当 与 我 们 的 神 立 约 ， 休 这 一 切 的 妻 ， 离 绝 她 们 所 生 的 ， 照 着 我 主 和 那 因 神 命 令 战 兢 之 人 所 议 定 的 ， 按 律 法 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12257', '15', '10', '4', '你 起 来 ， 这 是 你 当 办 的 事 ， 我 们 必 帮 助 你 ， 你 当 奋 勉 而 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12258', '15', '10', '5', '以 斯 拉 便 起 来 ， 使 祭 司 长 和 利 未 人 ， 并 以 色 列 众 人 起 誓 说 ， 必 照 这 话 去 行 ； 他 们 就 起 了 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12259', '15', '10', '6', '以 斯 拉 从 神 殿 前 起 来 ， 进 入 以 利 亚 实 的 儿 子 约 哈 难 的 屋 里 ， 到 了 那 里 不 吃 饭 ， 也 不 喝 水 ； 因 为 被 掳 归 回 之 人 所 犯 的 罪 ， 心 里 悲 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12260', '15', '10', '7', '他 们 通 告 犹 大 和 耶 路 撒 冷 被 掳 归 回 的 人 ， 叫 他 们 在 耶 路 撒 冷 聚 集 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12261', '15', '10', '8', '凡 不 遵 首 领 和 长 老 所 议 定 、 三 日 之 内 不 来 的 ， 就 必 抄 他 的 家 ， 使 他 离 开 被 掳 归 回 之 人 的 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12262', '15', '10', '9', '于 是 ， 犹 大 和 便 雅 悯 众 人 ， 三 日 之 内 都 聚 集 在 耶 路 撒 冷 。 那 日 正 是 九 月 二 十 日 ， 众 人 都 坐 在 神 殿 前 的 宽 阔 处 ； 因 这 事 ， 又 因 下 大 雨 ， 就 都 战 兢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12263', '15', '10', '10', '祭 司 以 斯 拉 站 起 来 ， 对 他 们 说 ： “ 你 们 有 罪 了 ； 因 你 们 娶 了 外 邦 的 女 子 为 妻 ， 增 添 以 色 列 人 的 罪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12264', '15', '10', '11', '现 在 当 向 耶 和 华 ─ ─ 你 们 列 祖 的 神 认 罪 ， 遵 行 他 的 旨 意 ， 离 绝 这 些 国 的 民 和 外 邦 的 女 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12265', '15', '10', '12', '会 众 都 大 声 回 答 说 ： “ 我 们 必 照 着 你 的 话 行 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12266', '15', '10', '13', '只 是 百 姓 众 多 ， 又 逢 大 雨 的 时 令 ， 我 们 不 能 站 在 外 头 ， 这 也 不 是 一 两 天 办 完 的 事 ， 因 我 们 在 这 事 上 犯 了 大 罪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12267', '15', '10', '14', '不 如 为 全 会 众 派 首 领 办 理 。 凡 我 们 城 邑 中 娶 外 邦 女 子 为 妻 的 ， 当 按 所 定 的 日 期 ， 同 着 本 城 的 长 老 和 士 师 而 来 ， 直 到 办 完 这 事 ， 神 的 烈 怒 就 转 离 我 们 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12268', '15', '10', '15', '惟 有 亚 撒 黑 的 儿 子 约 拿 单 ， 特 瓦 的 儿 子 雅 哈 谢 阻 挡 ｛ 或 译 ： 总 办 ｝ 这 事 ， 并 有 米 书 兰 和 利 未 人 沙 比 太 帮 助 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12269', '15', '10', '16', '被 掳 归 回 的 人 如 此 而 行 。 祭 司 以 斯 拉 和 些 族 长 按 着 宗 族 都 指 名 见 派 ； 在 十 月 初 一 日 ， 一 同 在 座 查 办 这 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12270', '15', '10', '17', '到 正 月 初 一 日 ， 才 查 清 娶 外 邦 女 子 的 人 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12271', '15', '10', '18', '＜ 娶 外 邦 女 子 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12272', '15', '10', '19', '他 们 便 应 许 必 休 他 们 的 妻 。 他 们 因 有 罪 ， 就 献 群 中 的 一 只 公 绵 羊 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12273', '15', '10', '20', '音 麦 的 子 孙 中 ， 有 哈 拿 尼 、 西 巴 第 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12274', '15', '10', '21', '哈 琳 的 子 孙 中 ， 有 玛 西 雅 、 以 利 雅 、 示 玛 雅 、 耶 歇 、 乌 西 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12275', '15', '10', '22', '巴 施 户 珥 的 子 孙 中 ， 有 以 利 约 乃 、 玛 西 雅 、 以 实 玛 利 、 拿 坦 业 、 约 撒 拔 、 以 利 亚 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12276', '15', '10', '23', '利 未 人 中 ， 有 约 撒 拔 、 示 每 、 基 拉 雅 （ 基 拉 雅 就 是 基 利 他 ） ， 还 有 毗 他 希 雅 、 犹 大 、 以 利 以 谢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12277', '15', '10', '24', '歌 唱 的 人 中 有 以 利 亚 实 。 守 门 的 人 中 ， 有 沙 龙 、 提 联 、 乌 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12278', '15', '10', '25', '以 色 列 人 巴 录 的 子 孙 中 ， 有 拉 米 、 耶 西 雅 、 玛 基 雅 、 米 雅 民 、 以 利 亚 撒 、 玛 基 雅 、 比 拿 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12279', '15', '10', '26', '以 拦 的 子 孙 中 ， 有 玛 他 尼 、 撒 迦 利 亚 、 耶 歇 、 押 底 、 耶 利 末 、 以 利 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12280', '15', '10', '27', '萨 土 的 子 孙 中 ， 有 以 利 约 乃 、 以 利 亚 实 、 玛 他 尼 、 耶 利 末 、 撒 拔 、 亚 西 撒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12281', '15', '10', '28', '比 拜 的 子 孙 中 ， 有 约 哈 难 、 哈 拿 尼 雅 、 萨 拜 、 亚 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12282', '15', '10', '29', '巴 尼 的 子 孙 中 ， 有 米 书 兰 、 玛 鹿 、 亚 大 雅 、 雅 述 、 示 押 、 耶 利 末 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12283', '15', '10', '30', '巴 哈 ． 摩 押 的 子 孙 中 ， 有 阿 底 拿 、 基 拉 、 比 拿 雅 、 玛 西 雅 、 玛 他 尼 、 比 撒 列 、 宾 内 、 玛 拿 西 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12284', '15', '10', '31', '哈 琳 的 子 孙 中 ， 有 以 利 以 谢 、 伊 示 雅 、 玛 基 雅 、 示 玛 雅 、 西 缅 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12285', '15', '10', '32', '便 雅 悯 、 玛 鹿 、 示 玛 利 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12286', '15', '10', '33', '哈 顺 的 子 孙 中 ， 有 玛 特 乃 、 玛 达 他 、 撒 拔 、 以 利 法 列 、 耶 利 买 、 玛 拿 西 、 示 每 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12287', '15', '10', '34', '巴 尼 的 子 孙 中 ， 有 玛 玳 、 暗 兰 、 乌 益 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12288', '15', '10', '35', '比 拿 雅 、 比 底 雅 、 基 禄 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12289', '15', '10', '36', '瓦 尼 雅 、 米 利 末 、 以 利 亚 实 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12290', '15', '10', '37', '玛 他 尼 、 玛 特 乃 、 雅 扫 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12291', '15', '10', '38', '巴 尼 、 宾 内 、 示 每 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12292', '15', '10', '39', '示 利 米 雅 、 拿 单 、 亚 大 雅 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12293', '15', '10', '40', '玛 拿 底 拜 、 沙 赛 、 沙 赖 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12294', '15', '10', '41', '亚 萨 利 、 示 利 米 雅 、 示 玛 利 雅 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12295', '15', '10', '42', '沙 龙 、 亚 玛 利 雅 、 约 瑟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12296', '15', '10', '43', '尼 波 的 子 孙 中 ， 有 耶 利 、 玛 他 提 雅 、 撒 拔 、 西 比 拿 、 雅 玳 、 约 珥 、 比 拿 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12297', '15', '10', '44', '这 些 人 都 娶 了 外 邦 女 子 为 妻 ， 其 中 也 有 生 了 儿 女 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12298', '16', '1', '1', '＜ 尼 希 米 关 心 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12299', '16', '1', '2', '那 时 ， 有 我 一 个 弟 兄 哈 拿 尼 ， 同 着 几 个 人 从 犹 大 来 。 我 问 他 们 那 些 被 掳 归 回 、 剩 下 逃 脱 的 犹 大 人 和 耶 路 撒 冷 的 光 景 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12300', '16', '1', '3', '他 们 对 我 说 ： “ 那 些 被 掳 归 回 剩 下 的 人 在 犹 大 省 遭 大 难 ， 受 凌 辱 ； 并 且 耶 路 撒 冷 的 城 墙 拆 毁 ， 城 门 被 火 焚 烧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12301', '16', '1', '4', '我 听 见 这 话 ， 就 坐 下 哭 泣 ， 悲 哀 几 日 ， 在 天 上 的 神 面 前 禁 食 祈 祷 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12302', '16', '1', '5', '“ 耶 和 华 ─ ─ 天 上 的 神 ， 大 而 可 畏 的 神 啊 ， 你 向 爱 你 、 守 你 诫 命 的 人 守 约 施 慈 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12303', '16', '1', '6', '愿 你 睁 眼 看 ， 侧 耳 听 ， 你 仆 人 昼 夜 在 你 面 前 为 你 众 仆 人 以 色 列 民 的 祈 祷 ， 承 认 我 们 以 色 列 人 向 你 所 犯 的 罪 ； 我 与 我 父 家 都 有 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12304', '16', '1', '7', '我 们 向 你 所 行 的 甚 是 邪 恶 ， 没 有 遵 守 你 藉 着 仆 人 摩 西 所 吩 咐 的 诫 命 、 律 例 、 典 章 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12305', '16', '1', '8', '求 你 记 念 所 吩 咐 你 仆 人 摩 西 的 话 ， 说 ： ‘ 你 们 若 犯 罪 ， 我 就 把 你 们 分 散 在 万 民 中 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12306', '16', '1', '9', '但 你 们 若 归 向 我 ， 谨 守 遵 行 我 的 诫 命 ， 你 们 被 赶 散 的 人 虽 在 天 涯 ， 我 也 必 从 那 里 将 他 们 招 聚 回 来 ， 带 到 我 所 选 择 立 为 我 名 的 居 所 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12307', '16', '1', '10', '这 都 是 你 的 仆 人 、 你 的 百 姓 ， 就 是 你 用 大 力 和 大 能 的 手 所 救 赎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12308', '16', '1', '11', '主 啊 ， 求 你 侧 耳 听 你 仆 人 的 祈 祷 ， 和 喜 爱 敬 畏 你 名 众 仆 人 的 祈 祷 ， 使 你 仆 人 现 今 亨 通 ， 在 王 面 前 蒙 恩 。 ” 我 是 作 王 酒 政 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12309', '16', '2', '1', '＜ 尼 希 米 返 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12310', '16', '2', '2', '王 对 我 说 ： “ 你 既 没 有 病 ， 为 什 么 面 带 愁 容 呢 ？ 这 不 是 别 的 ， 必 是 你 心 中 愁 烦 。 ” 于 是 我 甚 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12311', '16', '2', '3', '我 对 王 说 ： “ 愿 王 万 岁 ！ 我 列 祖 坟 墓 所 在 的 那 城 荒 凉 ， 城 门 被 火 焚 烧 ， 我 岂 能 面 无 愁 容 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12312', '16', '2', '4', '王 问 我 说 ： “ 你 要 求 什 么 ？ ” 于 是 我 默 祷 天 上 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12313', '16', '2', '5', '我 对 王 说 ： “ 仆 人 若 在 王 眼 前 蒙 恩 ， 王 若 喜 欢 ， 求 王 差 遣 我 往 犹 大 ， 到 我 列 祖 坟 墓 所 在 的 那 城 去 ， 我 好 重 新 建 造 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12314', '16', '2', '6', '那 时 王 后 坐 在 王 的 旁 边 。 王 问 我 说 ： “ 你 去 要 多 少 日 子 ？ 几 时 回 来 ？ ” 我 就 定 了 日 期 。 于 是 王 喜 欢 差 遣 我 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12315', '16', '2', '7', '我 又 对 王 说 ： “ 王 若 喜 欢 ， 求 王 赐 我 诏 书 ， 通 知 大 河 西 的 省 长 准 我 经 过 ， 直 到 犹 大 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12316', '16', '2', '8', '又 赐 诏 书 ， 通 知 管 理 王 园 林 的 亚 萨 ， 使 他 给 我 木 料 ， 做 属 殿 营 楼 之 门 的 横 梁 和 城 墙 ， 与 我 自 己 房 屋 使 用 的 。 ” 王 就 允 准 我 ， 因 我 神 施 恩 的 手 帮 助 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12317', '16', '2', '9', '王 派 了 军 长 和 马 兵 护 送 我 。 我 到 了 河 西 的 省 长 那 里 ， 将 王 的 诏 书 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12318', '16', '2', '10', '和 伦 人 参 巴 拉 ， 并 为 奴 的 亚 扪 人 多 比 雅 ， 听 见 有 人 来 为 以 色 列 人 求 好 处 ， 就 甚 恼 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12319', '16', '2', '11', '我 到 了 耶 路 撒 冷 ， 在 那 里 住 了 三 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12320', '16', '2', '12', '我 夜 间 起 来 ， 有 几 个 人 也 一 同 起 来 ； 但 神 使 我 心 里 要 为 耶 路 撒 冷 做 什 么 事 ， 我 并 没 有 告 诉 人 。 除 了 我 骑 的 牲 口 以 外 ， 也 没 有 别 的 牲 口 在 我 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12321', '16', '2', '13', '当 夜 我 出 了 谷 门 ， 往 野 狗 井 去 ｛ 野 狗 ： 或 译 龙 ｝ ， 到 了 粪 厂 门 ， 察 看 耶 路 撒 冷 的 城 墙 ， 见 城 墙 拆 毁 ， 城 门 被 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12322', '16', '2', '14', '我 又 往 前 ， 到 了 泉 门 和 王 池 ， 但 所 骑 的 牲 口 没 有 地 方 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12323', '16', '2', '15', '于 是 夜 间 沿 溪 而 上 ， 察 看 城 墙 ， 又 转 身 进 入 谷 门 ， 就 回 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12324', '16', '2', '16', '我 往 哪 里 去 ， 我 做 什 么 事 ， 官 长 都 不 知 道 。 我 还 没 有 告 诉 犹 大 平 民 、 祭 司 、 贵 胄 、 官 长 ， 和 其 余 做 工 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12325', '16', '2', '17', '以 后 ， 我 对 他 们 说 ： “ 我 们 所 遭 的 难 ， 耶 路 撒 冷 怎 样 荒 凉 ， 城 门 被 火 焚 烧 ， 你 们 都 看 见 了 。 来 吧 ， 我 们 重 建 耶 路 撒 冷 的 城 墙 ， 免 得 再 受 凌 辱 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12326', '16', '2', '18', '我 告 诉 他 们 我 神 施 恩 的 手 怎 样 帮 助 我 ， 并 王 对 我 所 说 的 话 。 他 们 就 说 ： “ 我 们 起 来 建 造 吧 ！ ” 于 是 他 们 奋 勇 做 这 善 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12327', '16', '2', '19', '但 和 伦 人 参 巴 拉 ， 并 为 奴 的 亚 扪 人 多 比 雅 和 阿 拉 伯 人 基 善 听 见 就 嗤 笑 我 们 ， 藐 视 我 们 ， 说 ： “ 你 们 做 什 么 呢 ？ 要 背 叛 王 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12328', '16', '2', '20', '我 回 答 他 们 说 ： “ 天 上 的 神 必 使 我 们 亨 通 。 我 们 作 他 仆 人 的 ， 要 起 来 建 造 ； 你 们 却 在 耶 路 撒 冷 无 分 、 无 权 、 无 纪 念 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12329', '16', '3', '1', '＜ 重 建 耶 路 撒 冷 城 墙 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12330', '16', '3', '2', '其 次 是 耶 利 哥 人 建 造 。 其 次 是 音 利 的 儿 子 撒 刻 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12331', '16', '3', '3', '哈 西 拿 的 子 孙 建 立 鱼 门 ， 架 横 梁 、 安 门 扇 ， 和 闩 锁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12332', '16', '3', '4', '其 次 是 哈 哥 斯 的 孙 子 、 乌 利 亚 的 儿 子 米 利 末 修 造 。 其 次 是 米 示 萨 别 的 孙 子 、 比 利 迦 的 儿 子 米 书 兰 修 造 。 其 次 是 巴 拿 的 儿 子 撒 督 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12333', '16', '3', '5', '其 次 是 提 哥 亚 人 修 造 ； 但 是 他 们 的 贵 胄 不 用 肩 ｛ 原 文 是 颈 项 ｝ 担 他 们 主 的 工 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12334', '16', '3', '6', '巴 西 亚 的 儿 子 耶 何 耶 大 与 比 所 玳 的 儿 子 米 书 兰 修 造 古 门 ， 架 横 梁 ， 安 门 扇 和 闩 锁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12335', '16', '3', '7', '其 次 是 基 遍 人 米 拉 提 ， 米 伦 人 雅 顿 与 基 遍 人 ， 并 属 河 西 总 督 所 管 的 米 斯 巴 人 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12336', '16', '3', '8', '其 次 是 银 匠 哈 海 雅 的 儿 子 乌 薛 修 造 。 其 次 是 做 香 的 哈 拿 尼 雅 修 造 。 这 些 人 修 坚 耶 路 撒 冷 ， 直 到 宽 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12337', '16', '3', '9', '其 次 是 管 理 耶 路 撒 冷 一 半 、 户 珥 的 儿 子 利 法 雅 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12338', '16', '3', '10', '其 次 是 哈 路 抹 的 儿 子 耶 大 雅 对 着 自 己 的 房 屋 修 造 。 其 次 是 哈 沙 尼 的 儿 子 哈 突 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12339', '16', '3', '11', '哈 琳 的 儿 子 玛 基 雅 和 巴 哈 ． 摩 押 的 儿 子 哈 述 修 造 一 段 ， 并 修 造 炉 楼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12340', '16', '3', '12', '其 次 是 管 理 耶 路 撒 冷 那 一 半 、 哈 罗 黑 的 儿 子 沙 龙 和 他 的 女 儿 们 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12341', '16', '3', '13', '哈 嫩 和 撒 挪 亚 的 居 民 修 造 谷 门 ， 立 门 ， 安 门 扇 和 闩 锁 ， 又 建 筑 城 墙 一 千 肘 ， 直 到 粪 厂 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12342', '16', '3', '14', '管 理 伯 ． 哈 基 琳 、 利 甲 的 儿 子 玛 基 雅 修 造 粪 厂 门 ， 立 门 ， 安 门 扇 和 闩 锁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12343', '16', '3', '15', '管 理 米 斯 巴 、 各 荷 西 的 儿 子 沙 仑 修 造 泉 门 ， 立 门 ， 盖 门 顶 ， 安 门 扇 和 闩 锁 ， 又 修 造 靠 近 王 园 西 罗 亚 池 的 墙 垣 ， 直 到 那 从 大 卫 城 下 来 的 台 阶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12344', '16', '3', '16', '其 次 是 管 理 伯 ． 夙 一 半 、 押 卜 的 儿 子 尼 希 米 修 造 ， 直 到 大 卫 坟 地 的 对 面 ， 又 到 挖 成 的 池 子 ， 并 勇 士 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12345', '16', '3', '17', '＜ 造 城 墙 的 利 未 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12346', '16', '3', '18', '其 次 是 利 未 人 弟 兄 中 管 理 基 伊 拉 那 一 半 、 希 拿 达 的 儿 子 巴 瓦 伊 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12347', '16', '3', '19', '其 次 是 管 理 米 斯 巴 、 耶 书 亚 的 儿 子 以 谢 修 造 一 段 ， 对 着 武 库 的 上 坡 、 城 墙 转 弯 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12348', '16', '3', '20', '其 次 是 萨 拜 的 儿 子 巴 录 竭 力 修 造 一 段 ， 从 城 墙 转 弯 ， 直 到 大 祭 司 以 利 亚 实 的 府 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12349', '16', '3', '21', '其 次 是 哈 哥 斯 的 孙 子 、 乌 利 亚 的 儿 子 米 利 末 修 造 一 段 ， 从 以 利 亚 实 的 府 门 ， 直 到 以 利 亚 实 府 的 尽 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12350', '16', '3', '22', '＜ 造 城 墙 的 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12351', '16', '3', '23', '其 次 是 便 雅 悯 与 哈 述 对 着 自 己 的 房 屋 修 造 。 其 次 是 亚 难 尼 的 孙 子 、 玛 西 雅 的 儿 子 亚 撒 利 雅 在 靠 近 自 己 的 房 屋 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12352', '16', '3', '24', '其 次 是 希 拿 达 的 儿 子 宾 内 修 造 一 段 ， 从 亚 撒 利 雅 的 房 屋 直 到 城 墙 转 弯 ， 又 到 城 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12353', '16', '3', '25', '乌 赛 的 儿 子 巴 拉 修 造 对 着 城 墙 的 转 弯 和 王 上 宫 凸 出 来 的 城 楼 ， 靠 近 护 卫 院 的 那 一 段 。 其 次 是 巴 录 的 儿 子 毗 大 雅 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12354', '16', '3', '26', '（ 尼 提 宁 住 在 俄 斐 勒 ， 直 到 朝 东 水 门 的 对 面 和 凸 出 来 的 城 楼 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12355', '16', '3', '27', '＜ 其 他 建 造 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12356', '16', '3', '28', '从 马 门 往 上 ， 众 祭 司 各 对 自 己 的 房 屋 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12357', '16', '3', '29', '其 次 是 音 麦 的 儿 子 撒 督 对 着 自 己 的 房 屋 修 造 。 其 次 是 守 东 门 、 示 迦 尼 的 儿 子 示 玛 雅 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12358', '16', '3', '30', '其 次 是 示 利 米 雅 的 儿 子 哈 拿 尼 雅 和 萨 拉 的 第 六 子 哈 嫩 又 修 一 段 。 其 次 是 比 利 迦 的 儿 子 米 书 兰 对 着 自 己 的 房 屋 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12359', '16', '3', '31', '其 次 是 银 匠 玛 基 雅 修 造 到 尼 提 宁 和 商 人 的 房 屋 ， 对 着 哈 米 弗 甲 门 ， 直 到 城 的 角 楼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12360', '16', '3', '32', '银 匠 与 商 人 在 城 的 角 楼 和 羊 门 中 间 修 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12361', '16', '4', '1', '＜ 尼 希 米 胜 过 阻 挡 他 工 作 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12362', '16', '4', '2', '对 他 弟 兄 和 撒 马 利 亚 的 军 兵 说 ： “ 这 些 软 弱 的 犹 大 人 做 什 么 呢 ？ 要 保 护 自 己 吗 ？ 要 献 祭 吗 ？ 要 一 日 成 功 吗 ？ 要 从 土 堆 里 拿 出 火 烧 的 石 头 再 立 墙 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12363', '16', '4', '3', '亚 扪 人 多 比 雅 站 在 旁 边 ， 说 ： “ 他 们 所 修 造 的 石 墙 ， 就 是 狐 狸 上 去 也 必 跐 倒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12364', '16', '4', '4', '我 们 的 神 啊 ， 求 你 垂 听 ， 因 为 我 们 被 藐 视 。 求 你 使 他 们 的 毁 谤 归 于 他 们 的 头 上 ， 使 他 们 在 掳 到 之 地 作 为 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12365', '16', '4', '5', '不 要 遮 掩 他 们 的 罪 孽 ， 不 要 使 他 们 的 罪 恶 从 你 面 前 涂 抹 ， 因 为 他 们 在 修 造 的 人 眼 前 惹 动 你 的 怒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12366', '16', '4', '6', '这 样 ， 我 们 修 造 城 墙 ， 城 墙 就 都 连 络 ， 高 至 一 半 ， 因 为 百 姓 专 心 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12367', '16', '4', '7', '参 巴 拉 、 多 比 雅 、 阿 拉 伯 人 、 亚 扪 人 、 亚 实 突 人 听 见 修 造 耶 路 撒 冷 城 墙 ， 着 手 进 行 堵 塞 破 裂 的 地 方 ， 就 甚 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12368', '16', '4', '8', '大 家 同 谋 要 来 攻 击 耶 路 撒 冷 ， 使 城 内 扰 乱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12369', '16', '4', '9', '然 而 ， 我 们 祷 告 我 们 的 神 ， 又 因 他 们 的 缘 故 ， 就 派 人 看 守 ， 昼 夜 防 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12370', '16', '4', '10', '犹 太 人 说 ： “ 灰 土 尚 多 ， 扛 抬 的 人 力 气 已 经 衰 败 ， 所 以 我 们 不 能 建 造 城 墙 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12371', '16', '4', '11', '我 们 的 敌 人 且 说 ： “ 趁 他 们 不 知 不 见 ， 我 们 进 入 他 们 中 间 ， 杀 他 们 ， 使 工 作 止 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12372', '16', '4', '12', '那 靠 近 敌 人 居 住 的 犹 大 人 十 次 从 各 处 来 见 我 们 ， 说 ： “ 你 们 必 要 回 到 我 们 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12373', '16', '4', '13', '所 以 我 使 百 姓 各 按 宗 族 拿 刀 、 拿 枪 、 拿 弓 站 在 城 墙 后 边 低 洼 的 空 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12374', '16', '4', '14', '我 察 看 了 ， 就 起 来 对 贵 胄 、 官 长 ， 和 其 余 的 人 说 ： “ 不 要 怕 他 们 ！ 当 记 念 主 是 大 而 可 畏 的 。 你 们 要 为 弟 兄 、 儿 女 、 妻 子 、 家 产 争 战 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12375', '16', '4', '15', '仇 敌 听 见 我 们 知 道 他 们 的 心 意 ， 见 神 也 破 坏 他 们 的 计 谋 ， 就 不 来 了 。 我 们 都 回 到 城 墙 那 里 ， 各 做 各 的 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12376', '16', '4', '16', '从 那 日 起 ， 我 的 仆 人 一 半 做 工 ， 一 半 拿 枪 、 拿 盾 牌 、 拿 弓 、 穿 ｛ 或 译 ： 拿 ｝ 铠 甲 ， 官 长 都 站 在 犹 大 众 人 的 后 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12377', '16', '4', '17', '修 造 城 墙 的 ， 扛 抬 材 料 的 ， 都 一 手 做 工 一 手 拿 兵 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12378', '16', '4', '18', '修 造 的 人 都 腰 间 佩 刀 修 造 ， 吹 角 的 人 在 我 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12379', '16', '4', '19', '我 对 贵 胄 、 官 长 ， 和 其 余 的 人 说 ： “ 这 工 程 浩 大 ， 我 们 在 城 墙 上 相 离 甚 远 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12380', '16', '4', '20', '你 们 听 见 角 声 在 哪 里 ， 就 聚 集 到 我 们 那 里 去 。 我 们 的 神 必 为 我 们 争 战 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12381', '16', '4', '21', '于 是 ， 我 们 做 工 ， 一 半 拿 兵 器 ， 从 天 亮 直 到 星 宿 出 现 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12382', '16', '4', '22', '那 时 ， 我 又 对 百 姓 说 ： “ 各 人 和 他 的 仆 人 当 在 耶 路 撒 冷 住 宿 ， 好 在 夜 间 保 守 我 们 ， 白 昼 做 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12383', '16', '4', '23', '这 样 ， 我 和 弟 兄 仆 人 ， 并 跟 从 我 的 护 兵 都 不 脱 衣 服 ， 出 去 打 水 也 带 兵 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12384', '16', '5', '1', '＜ 尼 希 米 处 理 官 长 们 的 剥 削 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12385', '16', '5', '2', '有 的 说 ： “ 我 们 和 儿 女 人 口 众 多 ， 要 去 得 粮 食 度 命 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12386', '16', '5', '3', '有 的 说 ： “ 我 们 典 了 田 地 、 葡 萄 园 、 房 屋 ， 要 得 粮 食 充 饥 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12387', '16', '5', '4', '有 的 说 ： “ 我 们 已 经 指 着 田 地 、 葡 萄 园 ， 借 了 钱 给 王 纳 税 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12388', '16', '5', '5', '我 们 的 身 体 与 我 们 弟 兄 的 身 体 一 样 ； 我 们 的 儿 女 与 他 们 的 儿 女 一 般 。 现 在 我 们 将 要 使 儿 女 作 人 的 仆 婢 ， 我 们 的 女 儿 已 有 为 婢 的 ； 我 们 并 无 力 拯 救 ， 因 为 我 们 的 田 地 、 葡 萄 园 已 经 归 了 别 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12389', '16', '5', '6', '我 听 见 他 们 呼 号 说 这 些 话 ， 便 甚 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12390', '16', '5', '7', '我 心 里 筹 划 ， 就 斥 责 贵 胄 和 官 长 说 ： “ 你 们 各 人 向 弟 兄 取 利 ！ ” 于 是 我 招 聚 大 会 攻 击 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12391', '16', '5', '8', '我 对 他 们 说 ： “ 我 们 尽 力 赎 回 我 们 弟 兄 ， 就 是 卖 与 外 邦 的 犹 大 人 ； 你 们 还 要 卖 弟 兄 ， 使 我 们 赎 回 来 吗 ？ ” 他 们 就 静 默 不 语 ， 无 话 可 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12392', '16', '5', '9', '我 又 说 ： “ 你 们 所 行 的 不 善 ！ 你 们 行 事 不 当 敬 畏 我 们 的 神 吗 ？ 不 然 ， 难 免 我 们 的 仇 敌 外 邦 人 毁 谤 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12393', '16', '5', '10', '我 和 我 的 弟 兄 与 仆 人 也 将 银 钱 粮 食 借 给 百 姓 ； 我 们 大 家 都 当 免 去 利 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12394', '16', '5', '11', '如 今 我 劝 你 们 将 他 们 的 田 地 、 葡 萄 园 、 橄 榄 园 、 房 屋 ， 并 向 他 们 所 取 的 银 钱 、 粮 食 、 新 酒 ， 和 油 ， 百 分 之 一 的 利 息 都 归 还 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12395', '16', '5', '12', '众 人 说 ： “ 我 们 必 归 还 ， 不 再 向 他 们 索 要 ， 必 照 你 的 话 行 。 ” 我 就 召 了 祭 司 来 ， 叫 众 人 起 誓 ， 必 照 着 所 应 许 的 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12396', '16', '5', '13', '我 也 抖 着 胸 前 的 衣 襟 ， 说 ： “ 凡 不 成 就 这 应 许 的 ， 愿 神 照 样 抖 他 离 开 家 产 和 他 劳 碌 得 来 的 ， 直 到 抖 空 了 。 ” 会 众 都 说 ： “ 阿 们 ！ ” 又 赞 美 耶 和 华 。 百 姓 就 照 着 所 应 许 的 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12397', '16', '5', '14', '＜ 尼 希 米 大 公 无 私 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12398', '16', '5', '15', '在 我 以 前 的 省 长 加 重 百 姓 的 担 子 ， 每 日 索 要 粮 食 和 酒 ， 并 银 子 四 十 舍 客 勒 ， 就 是 他 们 的 仆 人 也 辖 制 百 姓 ； 但 我 因 敬 畏 神 不 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12399', '16', '5', '16', '并 且 我 恒 心 修 造 城 墙 ， 并 没 有 置 买 田 地 ； 我 的 仆 人 也 都 聚 集 在 那 里 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12400', '16', '5', '17', '除 了 从 四 围 外 邦 中 来 的 犹 大 人 以 外 ， 有 犹 大 平 民 和 官 长 一 百 五 十 人 在 我 席 上 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12401', '16', '5', '18', '每 日 预 备 一 只 公 牛 ， 六 只 肥 羊 ， 又 预 备 些 飞 禽 ； 每 十 日 一 次 ， 多 预 备 各 样 的 酒 。 虽 然 如 此 ， 我 并 不 要 省 长 的 俸 禄 ， 因 为 百 姓 服 役 甚 重 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12402', '16', '5', '19', '我 的 神 啊 ， 求 你 记 念 我 为 这 百 姓 所 行 的 一 切 事 ， 施 恩 与 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12403', '16', '6', '1', '＜ 敌 对 尼 希 米 的 阴 谋 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12404', '16', '6', '2', '参 巴 拉 和 基 善 就 打 发 人 来 见 我 ， 说 ： “ 请 你 来 ， 我 们 在 阿 挪 平 原 的 一 个 村 庄 相 会 。 ” 他 们 却 想 害 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12405', '16', '6', '3', '于 是 我 差 遣 人 去 见 他 们 ， 说 ： “ 我 现 在 办 理 大 工 ， 不 能 下 去 。 焉 能 停 工 下 去 见 你 们 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12406', '16', '6', '4', '他 们 这 样 四 次 打 发 人 来 见 我 ， 我 都 如 此 回 答 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12407', '16', '6', '5', '参 巴 拉 第 五 次 打 发 仆 人 来 见 我 ， 手 里 拿 着 未 封 的 信 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12408', '16', '6', '6', '信 上 写 着 说 ： “ 外 邦 人 中 有 风 声 ， 迦 施 慕 ｛ 就 是 基 善 ， 见 二 章 十 九 节 ｝ 也 说 ， 你 和 犹 大 人 谋 反 ， 修 造 城 墙 ， 你 要 作 他 们 的 王 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12409', '16', '6', '7', '你 又 派 先 知 在 耶 路 撒 冷 指 着 你 宣 讲 ， 说 在 犹 大 有 王 。 现 在 这 话 必 传 与 王 知 ； 所 以 请 你 来 ， 与 我 们 彼 此 商 议 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12410', '16', '6', '8', '我 就 差 遣 人 去 见 他 ， 说 ： “ 你 所 说 的 这 事 ， 一 概 没 有 ， 是 你 心 里 捏 造 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12411', '16', '6', '9', '他 们 都 要 使 我 们 惧 怕 ， 意 思 说 ， 他 们 的 手 必 软 弱 ， 以 致 工 作 不 能 成 就 。 神 啊 ， 求 你 坚 固 我 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12412', '16', '6', '10', '我 到 了 米 希 大 别 的 孙 子 、 第 来 雅 的 儿 子 示 玛 雅 家 里 ； 那 时 ， 他 闭 门 不 出 。 他 说 ： “ 我 们 不 如 在 神 的 殿 里 会 面 ， 将 殿 门 关 锁 ； 因 为 他 们 要 来 杀 你 ， 就 是 夜 里 来 杀 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12413', '16', '6', '11', '我 说 ： “ 像 我 这 样 的 人 岂 要 逃 跑 呢 ？ 像 我 这 样 的 人 岂 能 进 入 殿 里 保 全 生 命 呢 ？ 我 不 进 去 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12414', '16', '6', '12', '我 看 明 神 没 有 差 遣 他 ， 是 他 自 己 说 这 话 攻 击 我 ， 是 多 比 雅 和 参 巴 拉 贿 买 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12415', '16', '6', '13', '贿 买 他 的 缘 故 ， 是 要 叫 我 惧 怕 ， 依 从 他 犯 罪 ， 他 们 好 传 扬 恶 言 毁 谤 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12416', '16', '6', '14', '我 的 神 啊 ， 多 比 雅 、 参 巴 拉 、 女 先 知 挪 亚 底 ， 和 其 余 的 先 知 要 叫 我 惧 怕 ， 求 你 记 念 他 们 所 行 的 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12417', '16', '6', '15', '＜ 工 程 结 束 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12418', '16', '6', '16', '我 们 一 切 仇 敌 、 四 围 的 外 邦 人 听 见 了 便 惧 怕 ， 愁 眉 不 展 ； 因 为 见 这 工 作 完 成 是 出 乎 我 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12419', '16', '6', '17', '在 那 些 日 子 ， 犹 大 的 贵 胄 屡 次 寄 信 与 多 比 雅 ， 多 比 雅 也 来 信 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12420', '16', '6', '18', '在 犹 大 有 许 多 人 与 多 比 雅 结 盟 ； 因 他 是 亚 拉 的 儿 子 ， 示 迦 尼 的 女 婿 ， 并 且 他 的 儿 子 约 哈 难 娶 了 比 利 迦 儿 子 米 书 兰 的 女 儿 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12421', '16', '6', '19', '他 们 常 在 我 面 前 说 多 比 雅 的 善 行 ， 也 将 我 的 话 传 与 他 。 多 比 雅 又 常 寄 信 来 ， 要 叫 我 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12422', '16', '7', '1', '城 墙 修 完 ， 我 安 了 门 扇 ， 守 门 的 、 歌 唱 的 ， 和 利 未 人 都 已 派 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12423', '16', '7', '2', '我 就 派 我 的 弟 兄 哈 拿 尼 和 营 楼 的 宰 官 哈 拿 尼 雅 管 理 耶 路 撒 冷 ； 因 为 哈 拿 尼 雅 是 忠 信 的 ， 又 敬 畏 神 过 于 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12424', '16', '7', '3', '我 吩 咐 他 们 说 ： “ 等 到 太 阳 上 升 才 可 开 耶 路 撒 冷 的 城 门 ； 人 尚 看 守 的 时 候 就 要 关 门 上 闩 ； 也 当 派 耶 路 撒 冷 的 居 民 各 按 班 次 看 守 自 己 房 屋 对 面 之 处 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12425', '16', '7', '4', '＜ 流 亡 归 返 人 的 名 单 （ 拉   2 ： 1 - 7 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12426', '16', '7', '5', '我 的 神 感 动 我 心 ， 招 聚 贵 胄 、 官 长 ， 和 百 姓 ， 要 照 家 谱 计 算 。 我 找 着 第 一 次 上 来 之 人 的 家 谱 ， 其 上 写 着 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12427', '16', '7', '6', '巴 比 伦 王 尼 布 甲 尼 撒 从 前 掳 去 犹 大 省 的 人 ， 现 在 他 们 的 子 孙 从 被 掳 到 之 地 回 耶 路 撒 冷 和 犹 大 ， 各 归 本 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12428', '16', '7', '7', '他 们 是 同 着 所 罗 巴 伯 、 耶 书 亚 、 尼 希 米 、 亚 撒 利 雅 、 拉 米 、 拿 哈 玛 尼 、 末 底 改 、 必 珊 、 米 斯 毗 列 、 比 革 瓦 伊 、 尼 宏 、 巴 拿 回 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('12429', '16', '7', '8', '以 色 列 人 民 的 数 目 记 在 下 面 ： 巴 录 的 子 孙 二 千 一 百 七 十 二 名 ；');
