INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17602', '22', '5', '3', '＜ （ 新 娘 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17603', '22', '5', '4', '我 的 良 人 从 门 孔 里 伸 进 手 来 ， 我 便 因 他 动 了 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17604', '22', '5', '5', '我 起 来 ， 要 给 我 良 人 开 门 。 我 的 两 手 滴 下 没 药 ； 我 的 指 头 有 没 药 汁 滴 在 门 闩 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17605', '22', '5', '6', '我 给 我 的 良 人 开 了 门 ； 我 的 良 人 却 已 转 身 走 了 。 他 说 话 的 时 候 ， 我 神 不 守 舍 ； 我 寻 找 他 ， 竟 寻 不 见 ； 我 呼 叫 他 ， 他 却 不 回 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17606', '22', '5', '7', '城 中 巡 逻 看 守 的 人 遇 见 我 ， 打 了 我 ， 伤 了 我 ； 看 守 城 墙 的 人 夺 去 我 的 披 肩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17607', '22', '5', '8', '耶 路 撒 冷 的 众 女 子 啊 ， 我 嘱 咐 你 们 ： 若 遇 见 我 的 良 人 ， 要 告 诉 他 ， 我 因 思 爱 成 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17608', '22', '5', '9', '＜ （ 耶 路 撒 冷 的 众 女 子 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17609', '22', '5', '10', '＜ （ 新 娘 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17610', '22', '5', '11', '他 的 头 像 至 精 的 金 子 ； 他 的 头 发 厚 密 累 垂 ， 黑 如 乌 鸦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17611', '22', '5', '12', '他 的 眼 如 溪 水 旁 的 鸽 子 眼 ， 用 奶 洗 净 ， 安 得 合 式 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17612', '22', '5', '13', '他 的 两 腮 如 香 花 畦 ， 如 香 草 台 ； 他 的 嘴 唇 像 百 合 花 ， 且 滴 下 没 药 汁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17613', '22', '5', '14', '他 的 两 手 好 像 金 管 ， 镶 嵌 水 苍 玉 ； 他 的 身 体 如 同 雕 刻 的 象 牙 ， 周 围 镶 嵌 蓝 宝 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17614', '22', '5', '15', '他 的 腿 好 像 白 玉 石 柱 ， 安 在 精 金 座 上 ； 他 的 形 状 如 黎 巴 嫩 ， 且 佳 美 如 香 柏 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17615', '22', '5', '16', '他 的 口 极 其 甘 甜 ； 他 全 然 可 爱 。 耶 路 撒 冷 的 众 女 子 啊 ， 这 是 我 的 良 人 ； 这 是 我 的 朋 友 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17616', '22', '6', '1', '＜ （ 耶 路 撒 冷 的 众 女 子 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17617', '22', '6', '2', '＜ （ 新 娘 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17618', '22', '6', '3', '我 属 我 的 良 人 ， 我 的 良 人 也 属 我 ； 他 在 百 合 花 中 牧 放 群 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17619', '22', '6', '4', '＜ 第 五 首 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17620', '22', '6', '5', '求 你 掉 转 眼 目 不 看 我 ， 因 你 的 眼 目 使 我 惊 乱 。 你 的 头 发 如 同 山 羊 群 卧 在 基 列 山 旁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17621', '22', '6', '6', '你 的 牙 齿 如 一 群 母 羊 洗 净 上 来 ， 个 个 都 有 双 生 ， 没 有 一 只 丧 掉 子 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17622', '22', '6', '7', '你 的 两 太 阳 在 帕 子 内 ， 如 同 一 块 石 榴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17623', '22', '6', '8', '有 六 十 王 后 八 十 妃 嫔 ， 并 有 无 数 的 童 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17624', '22', '6', '9', '我 的 鸽 子 ， 我 的 完 全 人 ， 只 有 这 一 个 是 她 母 亲 独 生 的 ， 是 生 养 她 者 所 宝 爱 的 。 众 女 子 见 了 就 称 她 有 福 ； 王 后 妃 嫔 见 了 也 赞 美 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17625', '22', '6', '10', '那 向 外 观 看 、 如 晨 光 发 现 、 美 丽 如 月 亮 、 皎 洁 如 日 头 、 威 武 如 展 开 旌 旗 军 队 的 是 谁 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17626', '22', '6', '11', '我 下 入 核 桃 园 ， 要 看 谷 中 青 绿 的 植 物 ， 要 看 葡 萄 发 芽 没 有 ， 石 榴 开 花 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17627', '22', '6', '12', '不 知 不 觉 ， 我 的 心 将 我 安 置 在 我 尊 长 的 车 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17628', '22', '6', '13', '＜ （ 耶 路 撒 冷 的 众 女 子 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17629', '22', '7', '1', '＜ （ 新 郎 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17630', '22', '7', '2', '你 的 肚 脐 如 圆 杯 ， 不 缺 调 和 的 酒 ； 你 的 腰 如 一 堆 麦 子 ， 周 围 有 百 合 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17631', '22', '7', '3', '你 的 两 乳 好 像 一 对 小 鹿 ， 就 是 母 鹿 双 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17632', '22', '7', '4', '你 的 颈 项 如 象 牙 台 ； 你 的 眼 目 像 希 实 本 、 巴 特 ． 拉 并 门 旁 的 水 池 ； 你 的 鼻 子 仿 佛 朝 大 马 士 革 的 黎 巴 嫩 塔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17633', '22', '7', '5', '你 的 头 在 你 身 上 好 像 迦 密 山 ； 你 头 上 的 发 是 紫 黑 色 ； 王 的 心 因 这 下 垂 的 发 绺 系 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17634', '22', '7', '6', '我 所 爱 的 ， 你 何 其 美 好 ！ 何 其 可 悦 ， 使 人 欢 畅 喜 乐 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17635', '22', '7', '7', '你 的 身 量 好 像 棕 树 ； 你 的 两 乳 如 同 其 上 的 果 子 ， 累 累 下 垂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17636', '22', '7', '8', '我 说 ： 我 要 上 这 棕 树 ， 抓 住 枝 子 。 愿 你 的 两 乳 好 像 葡 萄 累 累 下 垂 ， 你 鼻 子 的 气 味 香 如 苹 果 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17637', '22', '7', '9', '你 的 口 如 上 好 的 酒 。 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17638', '22', '7', '10', '我 属 我 的 良 人 ， 他 也 恋 慕 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17639', '22', '7', '11', '我 的 良 人 ， 来 吧 ！ 你 我 可 以 往 田 间 去 ； 你 我 可 以 在 村 庄 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17640', '22', '7', '12', '我 们 早 晨 起 来 往 葡 萄 园 去 ， 看 看 葡 萄 发 芽 开 花 没 有 ， 石 榴 放 蕊 没 有 ； 我 在 那 里 要 将 我 的 爱 情 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17641', '22', '7', '13', '风 茄 放 香 ， 在 我 们 的 门 内 有 各 样 新 陈 佳 美 的 果 子 ； 我 的 良 人 ， 这 都 是 我 为 你 存 留 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17642', '22', '8', '1', '巴 不 得 你 像 我 的 兄 弟 ， 像 吃 我 母 亲 奶 的 兄 弟 ； 我 在 外 头 遇 见 你 就 与 你 亲 嘴 ， 谁 也 不 轻 看 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17643', '22', '8', '2', '我 必 引 导 你 ， 领 你 进 我 母 亲 的 家 ； 我 可 以 领 受 教 训 ， 也 就 使 你 喝 石 榴 汁 酿 的 香 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17644', '22', '8', '3', '他 的 左 手 必 在 我 头 下 ； 他 的 右 手 必 将 我 抱 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17645', '22', '8', '4', '耶 路 撒 冷 的 众 女 子 啊 ， 我 嘱 咐 你 们 ： 不 要 惊 动 、 不 要 叫 醒 我 所 亲 爱 的 ， 等 他 自 己 情 愿 ｛ 不 要 叫 醒 … … 情 愿 ： 或 译 不 要 激 动 爱 情 ， 等 它 自 发 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17646', '22', '8', '5', '＜ 第 六 首 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17647', '22', '8', '6', '求 你 将 我 放 在 你 心 上 如 印 记 ， 带 在 你 臂 上 如 戳 记 。 因 为 爱 情 如 死 之 坚 强 ， 嫉 恨 如 阴 间 之 残 忍 ； 所 发 的 电 光 是 火 焰 的 电 光 ， 是 耶 和 华 的 烈 焰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17648', '22', '8', '7', '爱 情 ， 众 水 不 能 息 灭 ， 大 水 也 不 能 淹 没 。 若 有 人 拿 家 中 所 有 的 财 宝 要 换 爱 情 ， 就 全 被 藐 视 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17649', '22', '8', '8', '＜ （ 新 娘 的 兄 弟 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17650', '22', '8', '9', '她 若 是 墙 ， 我 们 要 在 其 上 建 造 银 塔 ； 她 若 是 门 ， 我 们 要 用 香 柏 木 板 围 护 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17651', '22', '8', '10', '＜ （ 新 娘 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17652', '22', '8', '11', '＜ （ 新 郎 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17653', '22', '8', '12', '我 自 己 的 葡 萄 园 在 我 面 前 。 所 罗 门 哪 ， 一 千 舍 客 勒 归 你 ， 二 百 舍 客 勒 归 看 守 果 子 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17654', '22', '8', '13', '你 这 住 在 园 中 的 ， 同 伴 都 要 听 你 的 声 音 ， 求 你 使 我 也 得 听 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17655', '22', '8', '14', '＜ （   新 娘 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17656', '23', '1', '1', '当 乌 西 雅 、 约 坦 、 亚 哈 斯 、 希 西 家 作 犹 大 王 的 时 候 ， 亚 摩 斯 的 儿 子 以 赛 亚 得 默 示 ， 论 到 犹 大 和 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17657', '23', '1', '2', '＜ 神 责 备 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17658', '23', '1', '3', '牛 认 识 主 人 ， 驴 认 识 主 人 的 槽 ， 以 色 列 却 不 认 识 ； 我 的 民 却 不 留 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17659', '23', '1', '4', '嗐 ！ 犯 罪 的 国 民 ， 担 着 罪 孽 的 百 姓 ； 行 恶 的 种 类 ， 败 坏 的 儿 女 ！ 他 们 离 弃 耶 和 华 ， 藐 视 以 色 列 的 圣 者 ， 与 他 生 疏 ， 往 后 退 步 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17660', '23', '1', '5', '你 们 为 什 么 屡 次 悖 逆 ， 还 要 受 责 打 吗 ？ 你 们 已 经 满 头 疼 痛 ， 全 心 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17661', '23', '1', '6', '从 脚 掌 到 头 顶 ， 没 有 一 处 完 全 的 ， 尽 是 伤 口 、 青 肿 ， 与 新 打 的 伤 痕 ， 都 没 有 收 口 ， 没 有 缠 裹 ， 也 没 有 用 膏 滋 润 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17662', '23', '1', '7', '你 们 的 地 土 已 经 荒 凉 ； 你 们 的 城 邑 被 火 焚 毁 。 你 们 的 田 地 在 你 们 眼 前 为 外 邦 人 所 侵 吞 ， 既 被 外 邦 人 倾 覆 就 成 为 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17663', '23', '1', '8', '仅 存 锡 安 城 ｛ 原 文 是 女 子 ｝ ， 好 像 葡 萄 园 的 草 棚 ， 瓜 田 的 茅 屋 ， 被 围 困 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17664', '23', '1', '9', '若 不 是 万 军 之 耶 和 华 给 我 们 稍 留 余 种 ， 我 们 早 已 像 所 多 玛 、 蛾 摩 拉 的 样 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17665', '23', '1', '10', '你 们 这 所 多 玛 的 官 长 啊 ， 要 听 耶 和 华 的 话 ！ 你 们 这 蛾 摩 拉 的 百 姓 啊 ， 要 侧 耳 听 我 们 神 的 训 诲 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17666', '23', '1', '11', '耶 和 华 说 ： 你 们 所 献 的 许 多 祭 物 与 我 何 益 呢 ？ 公 绵 羊 的 燔 祭 和 肥 畜 的 脂 油 ， 我 已 经 够 了 ； 公 牛 的 血 ， 羊 羔 的 血 ， 公 山 羊 的 血 ， 我 都 不 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17667', '23', '1', '12', '你 们 来 朝 见 我 ， 谁 向 你 们 讨 这 些 ， 使 你 们 践 踏 我 的 院 宇 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17668', '23', '1', '13', '你 们 不 要 再 献 虚 浮 的 供 物 。 香 品 是 我 所 憎 恶 的 ； 月 朔 和 安 息 日 ， 并 宣 召 的 大 会 ， 也 是 我 所 憎 恶 的 ； 作 罪 孽 ， 又 守 严 肃 会 ， 我 也 不 能 容 忍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17669', '23', '1', '14', '你 们 的 月 朔 和 节 期 ， 我 心 里 恨 恶 ， 我 都 以 为 麻 烦 ； 我 担 当 ， 便 不 耐 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17670', '23', '1', '15', '你 们 举 手 祷 告 ， 我 必 遮 眼 不 看 ； 就 是 你 们 多 多 地 祈 祷 ， 我 也 不 听 。 你 们 的 手 都 满 了 杀 人 的 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17671', '23', '1', '16', '你 们 要 洗 濯 、 自 洁 ， 从 我 眼 前 除 掉 你 们 的 恶 行 ， 要 止 住 作 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17672', '23', '1', '17', '学 习 行 善 ， 寻 求 公 平 ， 解 救 受 欺 压 的 ； 给 孤 儿 伸 冤 ， 为 寡 妇 辨 屈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17673', '23', '1', '18', '耶 和 华 说 ： 你 们 来 ， 我 们 彼 此 辩 论 。 你 们 的 罪 虽 像 朱 红 ， 必 变 成 雪 白 ； 虽 红 如 丹 颜 ， 必 白 如 羊 毛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17674', '23', '1', '19', '你 们 若 甘 心 听 从 ， 必 吃 地 上 的 美 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17675', '23', '1', '20', '若 不 听 从 ， 反 倒 悖 逆 ， 必 被 刀 剑 吞 灭 。 这 是 耶 和 华 亲 口 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17676', '23', '1', '21', '＜ 罪 大 恶 极 的 城 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17677', '23', '1', '22', '你 的 银 子 变 为 渣 滓 ； 你 的 酒 用 水 搀 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17678', '23', '1', '23', '你 的 官 长 居 心 悖 逆 ， 与 盗 贼 作 伴 ， 各 都 喜 爱 贿 赂 ， 追 求 赃 私 。 他 们 不 为 孤 儿 伸 冤 ； 寡 妇 的 案 件 也 不 得 呈 到 他 们 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17679', '23', '1', '24', '因 此 ， 主 ─ ─ 万 军 之 耶 和 华 、 以 色 列 的 大 能 者 说 ： 哎 ！ 我 要 向 我 的 对 头 雪 恨 ， 向 我 的 敌 人 报 仇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17680', '23', '1', '25', '我 必 反 手 加 在 你 身 上 ， 炼 尽 你 的 渣 滓 ， 除 净 你 的 杂 质 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17681', '23', '1', '26', '我 也 必 复 还 你 的 审 判 官 ， 像 起 初 一 样 ， 复 还 你 的 谋 士 ， 像 起 先 一 般 。 然 后 ， 你 必 称 为 公 义 之 城 ， 忠 信 之 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17682', '23', '1', '27', '锡 安 必 因 公 平 得 蒙 救 赎 ； 其 中 归 正 的 人 必 因 公 义 得 蒙 救 赎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17683', '23', '1', '28', '但 悖 逆 的 和 犯 罪 的 必 一 同 败 亡 ； 离 弃 耶 和 华 的 必 致 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17684', '23', '1', '29', '那 等 人 必 因 你 们 所 喜 爱 的 橡 树 抱 愧 ； 你 们 必 因 所 选 择 的 园 子 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17685', '23', '1', '30', '因 为 ， 你 们 必 如 叶 子 枯 干 的 橡 树 ， 好 像 无 水 浇 灌 的 园 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17686', '23', '1', '31', '有 权 势 的 必 如 麻 瓤 ； 他 的 工 作 好 像 火 星 ， 都 要 一 同 焚 毁 ， 无 人 扑 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17687', '23', '2', '1', '＜ 永 恒 的 和 平 （ 弥   4 : 1 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17688', '23', '2', '2', '末 后 的 日 子 ， 耶 和 华 殿 的 山 必 坚 立 ， 超 乎 诸 山 ， 高 举 过 于 万 岭 ； 万 民 都 要 流 归 这 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17689', '23', '2', '3', '必 有 许 多 国 的 民 前 往 ， 说 ： 来 吧 ， 我 们 登 耶 和 华 的 山 ， 奔 雅 各 神 的 殿 。 主 必 将 他 的 道 教 训 我 们 ； 我 们 也 要 行 他 的 路 。 因 为 训 诲 必 出 于 锡 安 ； 耶 和 华 的 言 语 必 出 于 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17690', '23', '2', '4', '他 必 在 列 国 中 施 行 审 判 ， 为 许 多 国 民 断 定 是 非 。 他 们 要 将 刀 打 成 犁 头 ， 把 枪 打 成 镰 刀 。 这 国 不 举 刀 攻 击 那 国 ； 他 们 也 不 再 学 习 战 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17691', '23', '2', '5', '雅 各 家 啊 ， 来 吧 ！ 我 们 在 耶 和 华 的 光 明 中 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17692', '23', '2', '6', '＜ 骄 者 必 败 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17693', '23', '2', '7', '他 们 的 国 满 了 金 银 ， 财 宝 也 无 穷 ； 他 们 的 地 满 了 马 匹 ， 车 辆 也 无 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17694', '23', '2', '8', '他 们 的 地 满 了 偶 像 ； 他 们 跪 拜 自 己 手 所 造 的 ， 就 是 自 己 指 头 所 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17695', '23', '2', '9', '卑 贱 人 屈 膝 ； 尊 贵 人 下 跪 ； 所 以 不 可 饶 恕 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17696', '23', '2', '10', '你 当 进 入 岩 穴 ， 藏 在 土 中 ， 躲 避 耶 和 华 的 惊 吓 和 他 威 严 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17697', '23', '2', '11', '到 那 日 ， 眼 目 高 傲 的 必 降 为 卑 ； 性 情 狂 傲 的 都 必 屈 膝 ； 惟 独 耶 和 华 被 尊 崇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17698', '23', '2', '12', '必 有 万 军 耶 和 华 降 罚 的 一 个 日 子 ， 要 临 到 骄 傲 狂 妄 的 ； 一 切 自 高 的 都 必 降 为 卑 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17699', '23', '2', '13', '又 临 到 黎 巴 嫩 高 大 的 香 柏 树 和 巴 珊 的 橡 树 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17700', '23', '2', '14', '又 临 到 一 切 高 山 的 峻 岭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17701', '23', '2', '15', '又 临 到 高 台 和 坚 固 城 墙 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17702', '23', '2', '16', '又 临 到 他 施 的 船 只 并 一 切 可 爱 的 美 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17703', '23', '2', '17', '骄 傲 的 必 屈 膝 ； 狂 妄 的 必 降 卑 。 在 那 日 ， 惟 独 耶 和 华 被 尊 崇 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17704', '23', '2', '18', '偶 像 必 全 然 废 弃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17705', '23', '2', '19', '耶 和 华 兴 起 ， 使 地 大 震 动 的 时 候 ， 人 就 进 入 石 洞 ， 进 入 土 穴 ， 躲 避 耶 和 华 的 惊 吓 和 他 威 严 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17706', '23', '2', '20', '到 那 日 ， 人 必 将 为 拜 而 造 的 金 偶 像 、 银 偶 像 抛 给 田 鼠 和 蝙 蝠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17707', '23', '2', '21', '到 耶 和 华 兴 起 ， 使 地 大 震 动 的 时 候 ， 人 好 进 入 磐 石 洞 中 和 岩 石 穴 里 ， 躲 避 耶 和 华 的 惊 吓 和 他 威 严 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17708', '23', '2', '22', '你 们 休 要 倚 靠 世 人 。 他 鼻 孔 里 不 过 有 气 息 ； 他 在 一 切 事 上 可 算 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17709', '23', '3', '1', '＜ 耶 路 撒 冷 的 混 乱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17710', '23', '3', '2', '除 掉 勇 士 和 战 士 ， 审 判 官 和 先 知 ， 占 卜 的 和 长 老 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17711', '23', '3', '3', '五 十 夫 长 和 尊 贵 人 ， 谋 士 和 有 巧 艺 的 ， 以 及 妙 行 法 术 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17712', '23', '3', '4', '主 说 ： 我 必 使 孩 童 作 他 们 的 首 领 ， 使 婴 孩 辖 管 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17713', '23', '3', '5', '百 姓 要 彼 此 欺 压 ； 各 人 受 邻 舍 的 欺 压 。 少 年 人 必 侮 慢 老 年 人 ； 卑 贱 人 必 侮 慢 尊 贵 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17714', '23', '3', '6', '人 在 父 家 拉 住 弟 兄 ， 说 ： 你 有 衣 服 ， 可 以 作 我 们 的 官 长 。 这 败 落 的 事 归 在 你 手 下 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17715', '23', '3', '7', '那 时 ， 他 必 扬 声 说 ： 我 不 作 医 治 你 们 的 人 ； 因 我 家 中 没 有 粮 食 ， 也 没 有 衣 服 ， 你 们 不 可 立 我 作 百 姓 的 官 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17716', '23', '3', '8', '耶 路 撒 冷 败 落 ， 犹 大 倾 倒 ； 因 为 他 们 的 舌 头 和 行 为 与 耶 和 华 反 对 ， 惹 了 他 荣 光 的 眼 目 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17717', '23', '3', '9', '他 们 的 面 色 证 明 自 己 的 不 正 ； 他 们 述 说 自 己 的 罪 恶 ， 并 不 隐 瞒 ， 好 像 所 多 玛 一 样 。 他 们 有 祸 了 ！ 因 为 作 恶 自 害 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17718', '23', '3', '10', '你 们 要 论 义 人 说 ： 他 必 享 福 乐 ， 因 为 要 吃 自 己 行 为 所 结 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17719', '23', '3', '11', '恶 人 有 祸 了 ！ 他 必 遭 灾 难 ！ 因 为 要 照 自 己 手 所 行 的 受 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17720', '23', '3', '12', '至 于 我 的 百 姓 ， 孩 童 欺 压 他 们 ， 妇 女 辖 管 他 们 。 我 的 百 姓 啊 ， 引 导 你 的 使 你 走 错 ， 并 毁 坏 你 所 行 的 道 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17721', '23', '3', '13', '＜ 耶 和 华 审 判 他 的 人 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17722', '23', '3', '14', '耶 和 华 必 审 问 他 民 中 的 长 老 和 首 领 ， 说 ： 吃 尽 葡 萄 园 果 子 的 就 是 你 们 ； 向 贫 穷 人 所 夺 的 都 在 你 们 家 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17723', '23', '3', '15', '主 ─ ─ 万 军 之 耶 和 华 说 ： 你 们 为 何 压 制 我 的 百 姓 ， 搓 磨 贫 穷 人 的 脸 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17724', '23', '3', '16', '＜ 对 耶 路 撒 冷 女 子 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17725', '23', '3', '17', '所 以 ， 主 必 使 锡 安 的 女 子 头 长 秃 疮 ； 耶 和 华 又 使 她 们 赤 露 下 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17726', '23', '3', '18', '到 那 日 ， 主 必 除 掉 她 们 华 美 的 脚 钏 、 发 网 、 月 牙 圈 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17727', '23', '3', '19', '耳 环 、 手 镯 、 蒙 脸 的 帕 子 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17728', '23', '3', '20', '华 冠 、 足 炼 、 华 带 、 香 盒 、 符 囊 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17729', '23', '3', '21', '戒 指 、 鼻 环 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17730', '23', '3', '22', '吉 服 、 外 套 、 云 肩 、 荷 包 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17731', '23', '3', '23', '手 镜 、 细 麻 衣 、 裹 头 巾 、 蒙 身 的 帕 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17732', '23', '3', '24', '必 有 臭 烂 代 替 馨 香 ， 绳 子 代 替 腰 带 ， 光 秃 代 替 美 发 ， 麻 衣 系 腰 代 替 华 服 ， 烙 伤 代 替 美 容 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17733', '23', '3', '25', '你 的 男 丁 必 倒 在 刀 下 ； 你 的 勇 士 必 死 在 阵 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17734', '23', '3', '26', '锡 安 ｛ 原 文 是 她 ｝ 的 城 门 必 悲 伤 、 哀 号 ； 她 必 荒 凉 坐 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17735', '23', '4', '1', '在 那 日 ， 七 个 女 人 必 拉 住 一 个 男 人 ， 说 ： “ 我 们 吃 自 己 的 食 物 ， 穿 自 己 的 衣 服 ， 但 求 你 许 我 们 归 你 名 下 ； 求 你 除 掉 我 们 的 羞 耻 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17736', '23', '4', '2', '＜ 耶 路 撒 冷 的 重 建 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17737', '23', '4', '3', '主 以 公 义 的 灵 和 焚 烧 的 灵 ， 将 锡 安 女 子 的 污 秽 洗 去 ， 又 将 耶 路 撒 冷 中 杀 人 的 血 除 净 。 那 时 ， 剩 在 锡 安 、 留 在 耶 路 撒 冷 的 ， 就 是 一 切 住 耶 路 撒 冷 、 在 生 命 册 上 记 名 的 ， 必 称 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17738', '23', '4', '4', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17739', '23', '4', '5', '耶 和 华 也 必 在 锡 安 全 山 ， 并 各 会 众 以 上 ， 使 白 日 有 烟 云 ， 黑 夜 有 火 焰 的 光 。 因 为 在 全 荣 耀 之 上 必 有 遮 蔽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17740', '23', '4', '6', '必 有 亭 子 ， 白 日 可 以 得 荫 避 暑 ， 也 可 以 作 为 藏 身 之 处 ， 躲 避 狂 风 暴 雨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17741', '23', '5', '1', '＜ 葡 萄 园 之 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17742', '23', '5', '2', '他 刨 挖 园 子 ， 捡 去 石 头 ， 栽 种 上 等 的 葡 萄 树 ， 在 园 中 盖 了 一 座 楼 ， 又 凿 出 压 酒 池 ； 指 望 结 好 葡 萄 ， 反 倒 结 了 野 葡 萄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17743', '23', '5', '3', '耶 路 撒 冷 的 居 民 和 犹 大 人 哪 ， 请 你 们 现 今 在 我 与 我 的 葡 萄 园 中 ， 断 定 是 非 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17744', '23', '5', '4', '我 为 我 葡 萄 园 所 做 之 外 ， 还 有 什 么 可 做 的 呢 ？ 我 指 望 结 好 葡 萄 ， 怎 么 倒 结 了 野 葡 萄 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17745', '23', '5', '5', '现 在 我 告 诉 你 们 ， 我 要 向 我 葡 萄 园 怎 样 行 ： 我 必 撤 去 篱 笆 ， 使 它 被 吞 灭 ， 拆 毁 墙 垣 ， 使 它 被 践 踏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17746', '23', '5', '6', '我 必 使 它 荒 废 ， 不 再 修 理 ， 不 再 锄 刨 ， 荆 棘 蒺 藜 倒 要 生 长 。 我 也 必 命 云 不 降 雨 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17747', '23', '5', '7', '万 军 之 耶 和 华 的 葡 萄 园 就 是 以 色 列 家 ； 他 所 喜 爱 的 树 就 是 犹 大 人 。 他 指 望 的 是 公 平 ， 谁 知 倒 有 暴 虐 ｛ 或 译 ： 倒 流 人 血 ｝ ； 指 望 的 是 公 义 ， 谁 知 倒 有 冤 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17748', '23', '5', '8', '＜ 人 的 恶 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17749', '23', '5', '9', '我 耳 闻 万 军 之 耶 和 华 说 ： 必 有 许 多 又 大 又 美 的 房 屋 成 为 荒 凉 ， 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17750', '23', '5', '10', '三 十 亩 葡 萄 园 只 出 一 罢 特 酒 ； 一 贺 梅 珥 谷 种 只 结 一 伊 法 粮 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17751', '23', '5', '11', '祸 哉 ！ 那 些 清 早 起 来 追 求 浓 酒 ， 留 连 到 夜 深 ， 甚 至 因 酒 发 烧 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17752', '23', '5', '12', '他 们 在 筵 席 上 弹 琴 ， 鼓 瑟 ， 击 鼓 ， 吹 笛 ， 饮 酒 ， 却 不 顾 念 耶 和 华 的 作 为 ， 也 不 留 心 他 手 所 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17753', '23', '5', '13', '所 以 ， 我 的 百 姓 因 无 知 就 被 掳 去 ； 他 们 的 尊 贵 人 甚 是 饥 饿 ， 群 众 极 其 干 渴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17754', '23', '5', '14', '故 此 ， 阴 间 扩 张 其 欲 ， 开 了 无 限 量 的 口 ； 他 们 的 荣 耀 、 群 众 、 繁 华 ， 并 快 乐 的 人 都 落 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17755', '23', '5', '15', '卑 贱 人 被 压 服 ； 尊 贵 人 降 为 卑 ； 眼 目 高 傲 的 人 也 降 为 卑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17756', '23', '5', '16', '惟 有 万 军 之 耶 和 华 因 公 平 而 崇 高 ； 圣 者 神 因 公 义 显 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17757', '23', '5', '17', '那 时 ， 羊 羔 必 来 吃 草 ， 如 同 在 自 己 的 草 场 ； 丰 肥 人 的 荒 场 被 游 行 的 人 吃 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17758', '23', '5', '18', '祸 哉 ！ 那 些 以 虚 假 之 细 绳 牵 罪 孽 的 人 ！ 他 们 又 像 以 套 绳 拉 罪 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17759', '23', '5', '19', '说 ： 任 他 急 速 行 ， 赶 快 成 就 他 的 作 为 ， 使 我 们 看 看 ； 任 以 色 列 圣 者 所 谋 划 的 临 近 成 就 ， 使 我 们 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17760', '23', '5', '20', '祸 哉 ！ 那 些 称 恶 为 善 ， 称 善 为 恶 ， 以 暗 为 光 ， 以 光 为 暗 ， 以 苦 为 甜 ， 以 甜 为 苦 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17761', '23', '5', '21', '祸 哉 ！ 那 些 自 以 为 有 智 慧 ， 自 看 为 通 达 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17762', '23', '5', '22', '祸 哉 ！ 那 些 勇 于 饮 酒 ， 以 能 力 调 浓 酒 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17763', '23', '5', '23', '他 们 因 受 贿 赂 ， 就 称 恶 人 为 义 ， 将 义 人 的 义 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17764', '23', '5', '24', '火 苗 怎 样 吞 灭 碎 秸 ， 干 草 怎 样 落 在 火 焰 之 中 ， 照 样 ， 他 们 的 根 必 像 朽 物 ， 他 们 的 花 必 像 灰 尘 飞 腾 ； 因 为 他 们 厌 弃 万 军 之 耶 和 华 的 训 诲 ， 藐 视 以 色 列 圣 者 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17765', '23', '5', '25', '所 以 ， 耶 和 华 的 怒 气 向 他 的 百 姓 发 作 。 他 的 手 伸 出 攻 击 他 们 ， 山 岭 就 震 动 ； 他 们 的 尸 首 在 街 市 上 好 像 粪 土 。 虽 然 如 此 ， 他 的 怒 气 还 未 转 消 ； 他 的 手 仍 伸 不 缩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17766', '23', '5', '26', '他 必 竖 立 大 旗 ， 招 远 方 的 国 民 ， 发 嘶 声 叫 他 们 从 地 极 而 来 ； 看 哪 ， 他 们 必 急 速 奔 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17767', '23', '5', '27', '其 中 没 有 疲 倦 的 ， 绊 跌 的 ； 没 有 打 盹 的 ， 睡 觉 的 ； 腰 带 并 不 放 松 ， 鞋 带 也 不 折 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17768', '23', '5', '28', '他 们 的 箭 快 利 ， 弓 也 上 了 弦 。 马 蹄 算 如 坚 石 ， 车 轮 好 像 旋 风 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17769', '23', '5', '29', '他 们 要 吼 叫 ， 像 母 狮 子 ， 咆 哮 ， 像 少 壮 狮 子 ； 他 们 要 咆 哮 抓 食 ， 坦 然 叼 去 ， 无 人 救 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17770', '23', '5', '30', '那 日 ， 他 们 要 向 以 色 列 人 吼 叫 ， 像 海 浪 匉 訇 ； 人 若 望 地 ， 只 见 黑 暗 艰 难 ， 光 明 在 云 中 变 为 昏 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17771', '23', '6', '1', '＜ 神 呼 召 以 赛 亚 作 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17772', '23', '6', '2', '其 上 有 撒 拉 弗 侍 立 ， 各 有 六 个 翅 膀 ： 用 两 个 翅 膀 遮 脸 ， 两 个 翅 膀 遮 脚 ， 两 个 翅 膀 飞 翔 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17773', '23', '6', '3', '彼 此 呼 喊 说 ： 圣 哉 ！ 圣 哉 ！ 圣 哉 ！ 万 军 之 耶 和 华 ； 他 的 荣 光 充 满 全 地 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17774', '23', '6', '4', '因 呼 喊 者 的 声 音 ， 门 槛 的 根 基 震 动 ， 殿 充 满 了 烟 云 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17775', '23', '6', '5', '那 时 我 说 ： “ 祸 哉 ！ 我 灭 亡 了 ！ 因 为 我 是 嘴 唇 不 洁 的 人 ， 又 住 在 嘴 唇 不 洁 的 民 中 ， 又 因 我 眼 见 大 君 王 ─ ─ 万 军 之 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17776', '23', '6', '6', '有 一 撒 拉 弗 飞 到 我 跟 前 ， 手 里 拿 着 红 炭 ， 是 用 火 剪 从 坛 上 取 下 来 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17777', '23', '6', '7', '将 炭 沾 我 的 口 ， 说 ： “ 看 哪 ， 这 炭 沾 了 你 的 嘴 ， 你 的 罪 孽 便 除 掉 ， 你 的 罪 恶 就 赦 免 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17778', '23', '6', '8', '我 又 听 见 主 的 声 音 说 ： “ 我 可 以 差 遣 谁 呢 ？ 谁 肯 为 我 们 去 呢 ？ ” 我 说 ： “ 我 在 这 里 ， 请 差 遣 我 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17779', '23', '6', '9', '他 说 ： “ 你 去 告 诉 这 百 姓 说 ： 你 们 听 是 要 听 见 ， 却 不 明 白 ； 看 是 要 看 见 ， 却 不 晓 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17780', '23', '6', '10', '要 使 这 百 姓 心 蒙 脂 油 ， 耳 朵 发 沉 ， 眼 睛 昏 迷 ； 恐 怕 眼 睛 看 见 ， 耳 朵 听 见 ， 心 里 明 白 ， 回 转 过 来 ， 便 得 医 治 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17781', '23', '6', '11', '我 就 说 ： “ 主 啊 ， 这 到 几 时 为 止 呢 ？ ” 他 说 ： 直 到 城 邑 荒 凉 ， 无 人 居 住 ， 房 屋 空 闲 无 人 ， 地 土 极 其 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17782', '23', '6', '12', '并 且 耶 和 华 将 人 迁 到 远 方 ， 在 这 境 内 撇 下 的 地 土 很 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17783', '23', '6', '13', '境 内 剩 下 的 人 若 还 有 十 分 之 一 ， 也 必 被 吞 灭 ， 像 栗 树 、 橡 树 虽 被 砍 伐 ， 树 不 子 却 仍 存 留 。 这 圣 洁 的 种 类 在 国 中 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17784', '23', '7', '1', '＜ 传 给 亚 哈 斯 王 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17785', '23', '7', '2', '有 人 告 诉 大 卫 家 说 ： “ 亚 兰 与 以 法 莲 已 经 同 盟 。 ” 王 的 心 和 百 姓 的 心 就 都 跳 动 ， 好 像 林 中 的 树 被 风 吹 动 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17786', '23', '7', '3', '耶 和 华 对 以 赛 亚 说 ： “ 你 和 你 的 儿 子 施 亚 雅 述 出 去 ， 到 上 池 的 水 沟 头 ， 在 漂 布 地 的 大 路 上 ， 去 迎 接 亚 哈 斯 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17787', '23', '7', '4', '对 他 说 ： ‘ 你 要 谨 慎 安 静 ， 不 要 因 亚 兰 王 利 汛 和 利 玛 利 的 儿 子 这 两 个 冒 烟 的 火 把 头 所 发 的 烈 怒 害 怕 ， 也 不 要 心 里 胆 怯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17788', '23', '7', '5', '因 为 亚 兰 和 以 法 莲 ， 并 利 玛 利 的 儿 子 ， 设 恶 谋 害 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17789', '23', '7', '6', '说 ： 我 们 可 以 上 去 攻 击 犹 大 ， 扰 乱 它 ， 攻 破 它 ， 在 其 中 立 他 比 勒 的 儿 子 为 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17790', '23', '7', '7', '所 以 主 耶 和 华 如 此 说 ： 这 所 谋 的 必 立 不 住 ， 也 不 得 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17791', '23', '7', '8', '原 来 亚 兰 的 首 城 是 大 马 士 革 ； 大 马 士 革 的 首 领 是 利 汛 。 （ 六 十 五 年 之 内 ， 以 法 莲 必 然 破 坏 ， 不 再 成 为 国 民 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17792', '23', '7', '9', '以 法 莲 的 首 城 是 撒 马 利 亚 ； 撒 马 利 亚 的 首 领 是 利 玛 利 的 儿 子 。 你 们 若 是 不 信 ， 定 然 不 得 立 稳 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17793', '23', '7', '10', '＜ 以 马 内 利 的 记 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17794', '23', '7', '11', '“ 你 向 耶 和 华 ─ ─ 你 的 神 求 一 个 兆 头 ： 或 求 显 在 深 处 ， 或 求 显 在 高 处 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17795', '23', '7', '12', '亚 哈 斯 说 ： “ 我 不 求 ； 我 不 试 探 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17796', '23', '7', '13', '以 赛 亚 说 ： “ 大 卫 家 啊 ， 你 们 当 听 ！ 你 们 使 人 厌 烦 岂 算 小 事 ， 还 要 使 我 的 神 厌 烦 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17797', '23', '7', '14', '因 此 ， 主 自 己 要 给 你 们 一 个 兆 头 ， 必 有 童 女 怀 孕 生 子 ， 给 他 起 名 叫 以 马 内 利 ｛ 就 是 神 与 我 们 同 在 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17798', '23', '7', '15', '到 他 晓 得 弃 恶 择 善 的 时 候 ， 他 必 吃 奶 油 与 蜂 蜜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17799', '23', '7', '16', '因 为 在 这 孩 子 还 不 晓 得 弃 恶 择 善 之 先 ， 你 所 憎 恶 的 那 二 王 之 地 必 致 见 弃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17800', '23', '7', '17', '耶 和 华 必 使 亚 述 王 攻 击 你 的 日 子 临 到 你 和 你 的 百 姓 ， 并 你 的 父 家 ， 自 从 以 法 莲 离 开 犹 大 以 来 ， 未 曾 有 这 样 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17801', '23', '7', '18', '“ 那 时 ， 耶 和 华 要 发 嘶 声 ， 使 埃 及 江 河 源 头 的 苍 蝇 和 亚 述 地 的 蜂 子 飞 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17802', '23', '7', '19', '都 必 飞 来 ， 落 在 荒 凉 的 谷 内 、 磐 石 的 穴 里 ， 和 一 切 荆 棘 篱 笆 中 ， 并 一 切 的 草 场 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17803', '23', '7', '20', '“ 那 时 ， 主 必 用 大 河 外 赁 的 剃 头 刀 ， 就 是 亚 述 王 ， 剃 去 头 发 和 脚 上 的 毛 ， 并 要 剃 净 胡 须 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17804', '23', '7', '21', '“ 那 时 ， 一 个 人 要 养 活 一 只 母 牛 犊 ， 两 只 母 绵 羊 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17805', '23', '7', '22', '因 为 出 的 奶 多 ， 他 就 得 吃 奶 油 ， 在 境 内 所 剩 的 人 都 要 吃 奶 油 与 蜂 蜜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17806', '23', '7', '23', '“ 从 前 ， 凡 种 一 千 棵 葡 萄 树 、 值 银 一 千 舍 客 勒 的 地 方 ， 到 那 时 必 长 荆 棘 和 蒺 藜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17807', '23', '7', '24', '人 上 那 里 去 ， 必 带 弓 箭 ， 因 为 遍 地 满 了 荆 棘 和 蒺 藜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17808', '23', '7', '25', '所 有 用 锄 刨 挖 的 山 地 ， 你 因 怕 荆 棘 和 蒺 藜 ， 不 敢 上 那 里 去 ； 只 可 成 了 放 牛 之 处 ， 为 羊 践 踏 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17809', '23', '8', '1', '＜ 用 以 赛 亚 的 儿 子 作 为 记 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17810', '23', '8', '2', '我 要 用 诚 实 的 见 证 人 ， 祭 司 乌 利 亚 和 耶 比 利 家 的 儿 子 撒 迦 利 亚 记 录 这 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17811', '23', '8', '3', '我 ─ ─ 以 赛 亚 与 妻 子 ｛ 原 文 是 女 先 知 ｝ 同 室 ； 她 怀 孕 生 子 ， 耶 和 华 就 对 我 说 ： “ 给 他 起 名 叫 玛 黑 珥 ． 沙 拉 勒 ． 哈 施 ． 罢 斯 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17812', '23', '8', '4', '因 为 在 这 小 孩 子 不 晓 得 叫 父 叫 母 之 先 ， 大 马 士 革 的 财 宝 和 撒 马 利 亚 的 掳 物 必 在 亚 述 王 面 前 搬 了 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17813', '23', '8', '5', '＜ 亚 述 王 快 来 了 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17814', '23', '8', '6', '“ 这 百 姓 既 厌 弃 西 罗 亚 缓 流 的 水 ， 喜 悦 利 汛 和 利 玛 利 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17815', '23', '8', '7', '因 此 ， 主 必 使 大 河 翻 腾 的 水 猛 然 冲 来 ， 就 是 亚 述 王 和 他 所 有 的 威 势 ， 必 漫 过 一 切 的 水 道 ， 涨 过 两 岸 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17816', '23', '8', '8', '必 冲 入 犹 大 ， 涨 溢 泛 滥 ， 直 到 颈 项 。 以 马 内 利 啊 ， 他 展 开 翅 膀 ， 遍 满 你 的 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17817', '23', '8', '9', '列 国 的 人 民 哪 ， 任 凭 你 们 喧 嚷 ， 终 必 破 坏 ； 远 方 的 众 人 哪 ， 当 侧 耳 而 听 ！ 任 凭 你 们 束 起 腰 来 ， 终 必 破 坏 ； 你 们 束 起 腰 来 ， 终 必 破 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17818', '23', '8', '10', '任 凭 你 们 同 谋 ， 终 归 无 有 ； 任 凭 你 们 言 定 ， 终 不 成 立 ； 因 为 神 与 我 们 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17819', '23', '8', '11', '＜ 耶 和 华 警 告 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17820', '23', '8', '12', '“ 这 百 姓 说 同 谋 背 叛 ， 你 们 不 要 说 同 谋 背 叛 。 他 们 所 怕 的 ， 你 们 不 要 怕 ， 也 不 要 畏 惧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17821', '23', '8', '13', '但 要 尊 万 军 之 耶 和 华 为 圣 ， 以 他 为 你 们 所 当 怕 的 ， 所 当 畏 惧 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17822', '23', '8', '14', '他 必 作 为 圣 所 ， 却 向 以 色 列 两 家 作 绊 脚 的 石 头 ， 跌 人 的 磐 石 ； 向 耶 路 撒 冷 的 居 民 作 为 圈 套 和 网 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17823', '23', '8', '15', '许 多 人 必 在 其 上 绊 脚 跌 倒 ， 而 且 跌 碎 ， 并 陷 入 网 罗 ， 被 缠 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17824', '23', '8', '16', '＜ 不 要 去 请 教 死 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17825', '23', '8', '17', '我 要 等 候 那 掩 面 不 顾 雅 各 家 的 耶 和 华 ； 我 也 要 仰 望 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17826', '23', '8', '18', '看 哪 ， 我 与 耶 和 华 所 给 我 的 儿 女 ， 就 是 从 住 在 锡 安 山 万 军 之 耶 和 华 来 的 ， 在 以 色 列 中 作 为 预 兆 和 奇 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17827', '23', '8', '19', '有 人 对 你 们 说 ： “ 当 求 问 那 些 交 鬼 的 和 行 巫 术 的 ， 就 是 声 音 绵 蛮 ， 言 语 微 细 的 。 ” 你 们 便 回 答 说 ： “ 百 姓 不 当 求 问 自 己 的 神 吗 ？ 岂 可 为 活 人 求 问 死 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17828', '23', '8', '20', '人 当 以 训 诲 和 法 度 为 标 准 ； 他 们 所 说 的 ， 若 不 与 此 相 符 ， 必 不 得 见 晨 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17829', '23', '8', '21', '＜ 遭 难 的 时 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17830', '23', '8', '22', '仰 观 上 天 ， 俯 察 下 地 ， 不 料 ， 尽 是 艰 难 、 黑 暗 ， 和 幽 暗 的 痛 苦 。 他 们 必 被 赶 入 乌 黑 的 黑 暗 中 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17831', '23', '9', '1', '但 那 受 过 痛 苦 的 必 不 再 见 幽 暗 。 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17832', '23', '9', '2', '在 黑 暗 中 行 走 的 百 姓 看 见 了 大 光 ； 住 在 死 荫 之 地 的 人 有 光 照 耀 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17833', '23', '9', '3', '你 使 这 国 民 繁 多 ， 加 增 他 们 的 喜 乐 ； 他 们 在 你 面 前 欢 喜 ， 好 像 收 割 的 欢 喜 ， 像 人 分 掳 物 那 样 的 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17834', '23', '9', '4', '因 为 他 们 所 负 的 重 轭 和 肩 头 上 的 杖 ， 并 欺 压 他 们 人 的 棍 ， 你 都 已 经 折 断 ， 好 像 在 米 甸 的 日 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17835', '23', '9', '5', '战 士 在 乱 杀 之 间 所 穿 戴 的 盔 甲 ， 并 那 滚 在 血 中 的 衣 服 ， 都 必 作 为 可 烧 的 ， 当 作 火 柴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17836', '23', '9', '6', '因 有 一 婴 孩 为 我 们 而 生 ； 有 一 子 赐 给 我 们 。 政 权 必 担 在 他 的 肩 头 上 ； 他 名 称 为 “ 奇 妙 策 士 、 全 能 的 神 、 永 在 的 父 、 和 平 的 君 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17837', '23', '9', '7', '他 的 政 权 与 平 安 必 加 增 无 穷 。 他 必 在 大 卫 的 宝 座 上 治 理 他 的 国 ， 以 公 平 公 义 使 国 坚 定 稳 固 ， 从 今 直 到 永 远 。 万 军 之 耶 和 华 的 热 心 必 成 就 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17838', '23', '9', '8', '＜ 耶 和 华 要 惩 罚 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17839', '23', '9', '9', '这 众 百 姓 ， 就 是 以 法 莲 和 撒 马 利 亚 的 居 民 ， 都 要 知 道 ； 他 们 凭 骄 傲 自 大 的 心 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17840', '23', '9', '10', '砖 墙 塌 了 ， 我 们 却 要 凿 石 头 建 筑 ； 桑 树 砍 了 ， 我 们 却 要 换 香 柏 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17841', '23', '9', '11', '因 此 ， 耶 和 华 要 高 举 利 汛 的 敌 人 来 攻 击 以 色 列 ， 并 要 激 动 以 色 列 的 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17842', '23', '9', '12', '东 有 亚 兰 人 ， 西 有 非 利 士 人 ； 他 们 张 口 要 吞 吃 以 色 列 。 虽 然 如 此 ， 耶 和 华 的 怒 气 还 未 转 消 ； 他 的 手 仍 伸 不 缩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17843', '23', '9', '13', '这 百 姓 还 没 有 归 向 击 打 他 们 的 主 ， 也 没 有 寻 求 万 军 之 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17844', '23', '9', '14', '因 此 ， 耶 和 华 一 日 之 间 必 从 以 色 列 中 剪 除 头 与 尾 ， 棕 枝 与 芦 苇 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17845', '23', '9', '15', '长 老 和 尊 贵 人 就 是 头 ， 以 谎 言 教 人 的 先 知 就 是 尾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17846', '23', '9', '16', '因 为 ， 引 导 这 百 姓 的 使 他 们 走 错 了 路 ； 被 引 导 的 都 必 败 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17847', '23', '9', '17', '所 以 ， 主 必 不 喜 悦 他 们 的 少 年 人 ， 也 不 怜 恤 他 们 的 孤 儿 寡 妇 ； 因 为 ， 各 人 是 亵 渎 的 ， 是 行 恶 的 ， 并 且 各 人 的 口 都 说 愚 妄 的 话 。 虽 然 如 此 ， 耶 和 华 的 怒 气 还 未 转 消 ； 他 的 手 仍 伸 不 缩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17848', '23', '9', '18', '邪 恶 像 火 焚 烧 ， 烧 灭 荆 棘 和 蒺 藜 ， 在 稠 密 的 树 林 中 着 起 来 ， 就 成 为 烟 柱 ， 旋 转 上 腾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17849', '23', '9', '19', '因 万 军 之 耶 和 华 的 烈 怒 ， 地 都 烧 遍 ； 百 姓 成 为 火 柴 ； 无 人 怜 爱 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17850', '23', '9', '20', '有 人 右 边 抢 夺 ， 仍 受 饥 饿 ， 左 边 吞 吃 ， 仍 不 饱 足 ； 各 人 吃 自 己 膀 臂 上 的 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17851', '23', '9', '21', '玛 拿 西 吞 吃 ｛ 或 译 ： 攻 击 ； 下 同 ｝ 以 法 莲 ； 以 法 莲 吞 吃 玛 拿 西 ， 又 一 同 攻 击 犹 大 。 虽 然 如 此 ， 耶 和 华 的 怒 气 还 未 转 消 ； 他 的 手 仍 伸 不 缩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17852', '23', '10', '1', '祸 哉 ！ 那 些 设 立 不 义 之 律 例 的 和 记 录 奸 诈 之 判 语 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17853', '23', '10', '2', '为 要 屈 枉 穷 乏 人 ， 夺 去 我 民 中 困 苦 人 的 理 ， 以 寡 妇 当 作 掳 物 ， 以 孤 儿 当 作 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17854', '23', '10', '3', '到 降 罚 的 日 子 ， 有 灾 祸 从 远 方 临 到 ， 那 时 ， 你 们 怎 样 行 呢 ？ 你 们 向 谁 逃 奔 求 救 呢 ？ 你 们 的 荣 耀 ｛ 或 译 ： 财 宝 ｝ 存 留 何 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17855', '23', '10', '4', '他 们 只 得 屈 身 在 被 掳 的 人 以 下 ， 仆 倒 在 被 杀 的 人 以 下 。 虽 然 如 此 ， 耶 和 华 的 怒 气 还 未 转 消 ； 他 的 手 仍 伸 不 缩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17856', '23', '10', '5', '＜ 神 用 亚 述 王 为 工 具 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17857', '23', '10', '6', '我 要 打 发 他 攻 击 亵 渎 的 国 民 ， 吩 咐 他 攻 击 我 所 恼 怒 的 百 姓 ， 抢 财 为 掳 物 ， 夺 货 为 掠 物 ， 将 他 们 践 踏 ， 像 街 上 的 泥 土 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17858', '23', '10', '7', '然 而 ， 他 不 是 这 样 的 意 思 ； 他 心 也 不 这 样 打 算 。 他 心 里 倒 想 毁 灭 ， 剪 除 不 少 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17859', '23', '10', '8', '他 说 ： 我 的 臣 仆 岂 不 都 是 王 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17860', '23', '10', '9', '迦 勒 挪 岂 不 像 迦 基 米 施 吗 ？ 哈 马 岂 不 像 亚 珥 拔 吗 ？ 撒 马 利 亚 岂 不 像 大 马 士 革 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17861', '23', '10', '10', '我 手 已 经 构 到 有 偶 像 的 国 ； 这 些 国 雕 刻 的 偶 像 过 于 耶 路 撒 冷 和 撒 马 利 亚 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17862', '23', '10', '11', '我 怎 样 待 撒 马 利 亚 和 其 中 的 偶 像 ， 岂 不 照 样 待 耶 路 撒 冷 和 其 中 的 偶 像 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17863', '23', '10', '12', '主 在 锡 安 山 和 耶 路 撒 冷 成 就 他 一 切 工 作 的 时 候 ， 主 说 ： “ 我 必 罚 亚 述 王 自 大 的 心 和 他 高 傲 眼 目 的 荣 耀 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17864', '23', '10', '13', '因 为 他 说 ： 我 所 成 就 的 事 是 靠 我 手 的 能 力 和 我 的 智 慧 ， 我 本 有 聪 明 。 我 挪 移 列 国 的 地 界 ， 抢 夺 他 们 所 积 蓄 的 财 宝 ； 并 且 我 像 勇 士 ， 使 坐 宝 座 的 降 为 卑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17865', '23', '10', '14', '我 的 手 构 到 列 国 的 财 宝 ， 好 像 人 构 到 鸟 窝 ； 我 也 得 了 全 地 ， 好 像 人 拾 起 所 弃 的 雀 蛋 。 没 有 动 翅 膀 的 ； 没 有 张 嘴 的 ， 也 没 有 鸣 叫 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17866', '23', '10', '15', '斧 岂 可 向 用 斧 砍 木 的 自 夸 呢 ？ 锯 岂 可 向 用 锯 的 自 大 呢 ？ 好 比 棍 抡 起 那 举 棍 的 ， 好 比 杖 举 起 那 非 木 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17867', '23', '10', '16', '因 此 ， 主 ─ ─ 万 军 之 耶 和 华 必 使 亚 述 王 的 肥 壮 人 变 为 瘦 弱 ， 在 他 的 荣 华 之 下 必 有 火 着 起 ， 如 同 焚 烧 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17868', '23', '10', '17', '以 色 列 的 光 必 如 火 ； 他 的 圣 者 必 如 火 焰 。 在 一 日 之 间 ， 将 亚 述 王 的 荆 棘 和 蒺 藜 焚 烧 净 尽 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17869', '23', '10', '18', '又 将 他 树 林 和 肥 田 的 荣 耀 全 然 烧 尽 ， 好 像 拿 军 旗 的 昏 过 去 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17870', '23', '10', '19', '他 林 中 剩 下 的 树 必 稀 少 ， 就 是 孩 子 也 能 写 其 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17871', '23', '10', '20', '＜ 残 存 之 民 归 回 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17872', '23', '10', '21', '所 剩 下 的 ， 就 是 雅 各 家 所 剩 下 的 ， 必 归 回 全 能 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17873', '23', '10', '22', '以 色 列 啊 ， 你 的 百 姓 虽 多 如 海 沙 ， 惟 有 剩 下 的 归 回 。 原 来 灭 绝 的 事 已 定 ， 必 有 公 义 施 行 ， 如 水 涨 溢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17874', '23', '10', '23', '因 为 主 ─ ─ 万 军 之 耶 和 华 在 全 地 之 中 必 成 就 所 定 规 的 结 局 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17875', '23', '10', '24', '＜ 耶 和 华 要 惩 罚 亚 述 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17876', '23', '10', '25', '因 为 还 有 一 点 点 时 候 ， 向 你 们 发 的 忿 恨 就 要 完 毕 ， 我 的 怒 气 要 向 他 发 作 ， 使 他 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17877', '23', '10', '26', '万 军 之 耶 和 华 要 兴 起 鞭 来 攻 击 他 ， 好 像 在 俄 立 磐 石 那 里 杀 戮 米 甸 人 一 样 。 耶 和 华 的 杖 要 向 海 伸 出 ， 把 杖 举 起 ， 像 在 埃 及 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17878', '23', '10', '27', '到 那 日 ， 亚 述 王 的 重 担 必 离 开 你 的 肩 头 ； 他 的 轭 必 离 开 你 的 颈 项 ； 那 轭 也 必 因 肥 壮 的 缘 故 撑 断 ｛ 或 译 ： 因 膏 油 的 缘 故 毁 坏 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17879', '23', '10', '28', '＜ 侵 略 者 进 攻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17880', '23', '10', '29', '他 们 过 了 隘 口 ， 在 迦 巴 住 宿 。 拉 玛 人 战 兢 ； 扫 罗 的 基 比 亚 人 逃 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17881', '23', '10', '30', '迦 琳 的 居 民 ｛ 原 文 是 女 子 ｝ 哪 ， 要 高 声 呼 喊 ！ 莱 煞 人 哪 ， 须 听 ！ 哀 哉 ！ 困 苦 的 亚 拿 突 啊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17882', '23', '10', '31', '玛 得 米 那 人 躲 避 ； 基 柄 的 居 民 逃 遁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17883', '23', '10', '32', '当 那 日 ， 亚 述 王 要 在 挪 伯 歇 兵 ， 向 锡 安 女 子 的 山 ─ ─ 就 是 耶 路 撒 冷 的 山 ─ ─ 抡 手 攻 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17884', '23', '10', '33', '看 哪 ， 主 ─ ─ 万 军 之 耶 和 华 以 惊 吓 削 去 树 枝 ； 长 高 的 必 被 砍 下 ， 高 大 的 必 被 伐 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17885', '23', '10', '34', '稠 密 的 树 林 ， 他 要 用 铁 器 砍 下 ； 黎 巴 嫩 的 树 木 必 被 大 能 者 伐 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17886', '23', '11', '1', '＜ 和 平 的 国 度 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17887', '23', '11', '2', '耶 和 华 的 灵 必 住 在 他 身 上 ， 就 是 使 他 有 智 慧 和 聪 明 的 灵 ， 谋 略 和 能 力 的 灵 ， 知 识 和 敬 畏 耶 和 华 的 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17888', '23', '11', '3', '他 必 以 敬 畏 耶 和 华 为 乐 ； 行 审 判 不 凭 眼 见 ， 断 是 非 也 不 凭 耳 闻 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17889', '23', '11', '4', '却 要 以 公 义 审 判 贫 穷 人 ， 以 正 直 判 断 世 上 的 谦 卑 人 ， 以 口 中 的 杖 击 打 世 界 ， 以 嘴 里 的 气 杀 戮 恶 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17890', '23', '11', '5', '公 义 必 当 他 的 腰 带 ； 信 实 必 当 他 胁 下 的 带 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17891', '23', '11', '6', '豺 狼 必 与 绵 羊 羔 同 居 ， 豹 子 与 山 羊 羔 同 卧 ； 少 壮 狮 子 与 牛 犊 并 肥 畜 同 群 ； 小 孩 子 要 牵 引 它 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17892', '23', '11', '7', '牛 必 与 熊 同 食 ； 牛 犊 必 与 小 熊 同 卧 ； 狮 子 必 吃 草 ， 与 牛 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17893', '23', '11', '8', '吃 奶 的 孩 子 必 玩 耍 在 虺 蛇 的 洞 口 ； 断 奶 的 婴 儿 必 按 手 在 毒 蛇 的 穴 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17894', '23', '11', '9', '在 我 圣 山 的 遍 处 ， 这 一 切 都 不 伤 人 ， 不 害 物 ； 因 为 认 识 耶 和 华 的 知 识 要 充 满 遍 地 ， 好 像 水 充 满 洋 海 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17895', '23', '11', '10', '＜ 流 亡 的 人 回 乡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17896', '23', '11', '11', '当 那 日 ， 主 必 二 次 伸 手 救 回 自 己 百 姓 中 所 余 剩 的 ， 就 是 在 亚 述 、 埃 及 、 巴 忒 罗 、 古 实 、 以 拦 、 示 拿 、 哈 马 ， 并 众 海 岛 所 剩 下 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17897', '23', '11', '12', '他 必 向 列 国 竖 立 大 旗 ， 招 回 以 色 列 被 赶 散 的 人 ， 又 从 地 的 四 方 聚 集 分 散 的 犹 大 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17898', '23', '11', '13', '以 法 莲 的 嫉 妒 就 必 消 散 ； 扰 害 犹 大 的 必 被 剪 除 。 以 法 莲 必 不 嫉 妒 犹 大 ， 犹 大 也 不 扰 害 以 法 莲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17899', '23', '11', '14', '他 们 要 向 西 飞 ， 扑 在 非 利 士 人 的 肩 头 上 ｛ 肩 头 上 ： 或 译 西 界 ｝ ， 一 同 掳 掠 东 方 人 ， 伸 手 按 住 以 东 和 摩 押 ； 亚 扪 人 也 必 顺 服 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17900', '23', '11', '15', '耶 和 华 必 使 埃 及 海 汊 枯 干 ， 抡 手 用 暴 热 的 风 使 大 河 分 为 七 条 ， 令 人 过 去 不 致 湿 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17901', '23', '11', '16', '为 主 余 剩 的 百 姓 ， 就 是 从 亚 述 剩 下 回 来 的 ， 必 有 一 条 大 道 ， 如 当 日 以 色 列 从 埃 及 地 上 来 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17902', '23', '12', '1', '＜ 感 恩 的 诗 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17903', '23', '12', '2', '看 哪 ！ 神 是 我 的 拯 救 ； 我 要 倚 靠 他 ， 并 不 惧 怕 。 因 为 主 耶 和 华 是 我 的 力 量 ， 是 我 的 诗 歌 ， 他 也 成 了 我 的 拯 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17904', '23', '12', '3', '所 以 ， 你 们 必 从 救 恩 的 泉 源 欢 然 取 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17905', '23', '12', '4', '在 那 日 ， 你 们 要 说 ： 当 称 谢 耶 和 华 ， 求 告 他 的 名 ； 将 他 所 行 的 传 扬 在 万 民 中 ， 提 说 他 的 名 已 被 尊 崇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17906', '23', '12', '5', '你 们 要 向 耶 和 华 唱 歌 ， 因 他 所 行 的 甚 是 美 好 ； 但 愿 这 事 普 传 天 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17907', '23', '12', '6', '锡 安 的 居 民 哪 ， 当 扬 声 欢 呼 ， 因 为 在 你 们 中 间 的 以 色 列 圣 者 乃 为 至 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17908', '23', '13', '1', '＜ 神 要 惩 罚 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17909', '23', '13', '2', '应 当 在 净 光 的 山 竖 立 大 旗 ， 向 群 众 扬 声 招 手 ， 使 他 们 进 入 贵 胄 的 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17910', '23', '13', '3', '我 吩 咐 我 所 挑 出 来 的 人 ； 我 招 呼 我 的 勇 士 ─ ─ 就 是 那 矜 夸 高 傲 之 辈 ， 为 要 成 就 我 怒 中 所 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17911', '23', '13', '4', '山 间 有 多 人 的 声 音 ， 好 像 是 大 国 人 民 。 有 许 多 国 的 民 聚 集 哄 嚷 的 声 音 ； 这 是 万 军 之 耶 和 华 点 齐 军 队 ， 预 备 打 仗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17912', '23', '13', '5', '他 们 从 远 方 来 ， 从 天 边 来 ， 就 是 耶 和 华 并 他 恼 恨 的 兵 器 要 毁 灭 这 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17913', '23', '13', '6', '你 们 要 哀 号 ， 因 为 耶 和 华 的 日 子 临 近 了 ！ 这 日 来 到 ， 好 像 毁 灭 从 全 能 者 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17914', '23', '13', '7', '所 以 ， 人 手 都 必 软 弱 ； 人 心 都 必 消 化 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17915', '23', '13', '8', '他 们 必 惊 惶 悲 痛 ； 愁 苦 必 将 他 们 抓 住 。 他 们 疼 痛 ， 好 像 产 难 的 妇 人 一 样 ， 彼 此 惊 奇 相 看 ， 脸 如 火 焰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17916', '23', '13', '9', '耶 和 华 的 日 子 临 到 ， 必 有 残 忍 、 忿 恨 、 烈 怒 ， 使 这 地 荒 凉 ， 从 其 中 除 灭 罪 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17917', '23', '13', '10', '天 上 的 众 星 群 宿 都 不 发 光 ； 日 头 一 出 就 变 黑 暗 ； 月 亮 也 不 放 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17918', '23', '13', '11', '我 必 因 邪 恶 刑 罚 世 界 ， 因 罪 孽 刑 罚 恶 人 ， 使 骄 傲 人 的 狂 妄 止 息 ， 制 伏 强 暴 人 的 狂 傲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17919', '23', '13', '12', '我 必 使 人 比 精 金 还 少 ， 使 人 比 俄 斐 纯 金 更 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17920', '23', '13', '13', '我 ─ ─ 万 军 之 耶 和 华 在 忿 恨 中 发 烈 怒 的 日 子 ， 必 使 天 震 动 ， 使 地 摇 撼 ， 离 其 本 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17921', '23', '13', '14', '人 必 像 被 追 赶 的 鹿 ， 像 无 人 收 聚 的 羊 ， 各 归 回 本 族 ， 各 逃 到 本 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17922', '23', '13', '15', '凡 被 仇 敌 追 上 的 必 被 刺 死 ； 凡 被 捉 住 的 必 被 刀 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17923', '23', '13', '16', '他 们 的 婴 孩 必 在 他 们 眼 前 摔 碎 ； 他 们 的 房 屋 必 被 抢 夺 ； 他 们 的 妻 子 必 被 玷 污 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17924', '23', '13', '17', '我 必 激 动 米 底 亚 人 来 攻 击 他 们 。 米 底 亚 人 不 注 重 银 子 ， 也 不 喜 爱 金 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17925', '23', '13', '18', '他 们 必 用 弓 击 碎 少 年 人 ， 不 怜 悯 妇 人 所 生 的 ， 眼 也 不 顾 惜 孩 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17926', '23', '13', '19', '巴 比 伦 素 来 为 列 国 的 荣 耀 ， 为 迦 勒 底 人 所 矜 夸 的 华 美 ， 必 像 神 所 倾 覆 的 所 多 玛 、 蛾 摩 拉 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17927', '23', '13', '20', '其 内 必 永 无 人 烟 ， 世 世 代 代 无 人 居 住 。 阿 拉 伯 人 也 不 在 那 里 支 搭 帐 棚 ； 牧 羊 的 人 也 不 使 羊 群 卧 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17928', '23', '13', '21', '只 有 旷 野 的 走 兽 卧 在 那 里 ； 咆 哮 的 兽 满 了 房 屋 。 鸵 鸟 住 在 那 里 ； 野 山 羊 在 那 里 跳 舞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17929', '23', '13', '22', '豺 狼 必 在 它 宫 中 呼 号 ； 野 狗 必 在 它 华 美 殿 内 吼 叫 。 巴 比 伦 受 罚 的 时 候 临 近 ； 它 的 日 子 必 不 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17930', '23', '14', '1', '＜ 从 流 亡 中 归 回 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17931', '23', '14', '2', '外 邦 人 必 将 他 们 带 回 本 土 ； 以 色 列 家 必 在 耶 和 华 的 地 上 得 外 邦 人 为 仆 婢 ， 也 要 掳 掠 先 前 掳 掠 他 们 的 ， 辖 制 先 前 欺 压 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17932', '23', '14', '3', '＜ 巴 比 伦 王 在 阴 间 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17933', '23', '14', '4', '你 必 题 这 诗 歌 论 巴 比 伦 王 说 ： 欺 压 人 的 何 竟 息 灭 ？ 强 暴 的 何 竟 止 息 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17934', '23', '14', '5', '耶 和 华 折 断 了 恶 人 的 杖 ， 辖 制 人 的 圭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17935', '23', '14', '6', '就 是 在 忿 怒 中 连 连 攻 击 众 民 的 ， 在 怒 气 中 辖 制 列 国 ， 行 逼 迫 无 人 阻 止 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17936', '23', '14', '7', '现 在 全 地 得 安 息 ， 享 平 静 ； 人 皆 发 声 欢 呼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17937', '23', '14', '8', '松 树 和 黎 巴 嫩 的 香 柏 树 都 因 你 欢 乐 ， 说 ： 自 从 你 仆 倒 ， 再 无 人 上 来 砍 伐 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17938', '23', '14', '9', '你 下 到 阴 间 ， 阴 间 就 因 你 震 动 来 迎 接 你 ， 又 因 你 惊 动 在 世 曾 为 首 领 的 阴 魂 ， 并 使 那 曾 为 列 国 君 王 的 ， 都 离 位 站 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17939', '23', '14', '10', '他 们 都 要 发 言 对 你 说 ： 你 也 变 为 软 弱 像 我 们 一 样 吗 ？ 你 也 成 了 我 们 的 样 子 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17940', '23', '14', '11', '你 的 威 势 和 你 琴 瑟 的 声 音 都 下 到 阴 间 。 你 下 铺 的 是 虫 ， 上 盖 的 是 蛆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17941', '23', '14', '12', '明 亮 之 星 ， 早 晨 之 子 啊 ， 你 何 竟 从 天 坠 落 ？ 你 这 攻 败 列 国 的 何 竟 被 砍 倒 在 地 上 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17942', '23', '14', '13', '你 心 里 曾 说 ： 我 要 升 到 天 上 ； 我 要 高 举 我 的 宝 座 在 神 众 星 以 上 ； 我 要 坐 在 聚 会 的 山 上 ， 在 北 方 的 极 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17943', '23', '14', '14', '我 要 升 到 高 云 之 上 ； 我 要 与 至 上 者 同 等 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17944', '23', '14', '15', '然 而 ， 你 必 坠 落 阴 间 ， 到 坑 中 极 深 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17945', '23', '14', '16', '凡 看 见 你 的 都 要 定 睛 看 你 ， 留 意 看 你 ， 说 ： 使 大 地 战 抖 ， 使 列 国 震 动 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17946', '23', '14', '17', '使 世 界 如 同 荒 野 ， 使 城 邑 倾 覆 ， 不 释 放 被 掳 的 人 归 家 ， 是 这 个 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17947', '23', '14', '18', '列 国 的 君 王 俱 各 在 自 己 阴 宅 的 荣 耀 中 安 睡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17948', '23', '14', '19', '惟 独 你 被 抛 弃 ， 不 得 入 你 的 坟 墓 ， 好 像 可 憎 的 枝 子 ， 以 被 杀 的 人 为 衣 ， 就 是 被 刀 刺 透 ， 坠 落 坑 中 石 头 那 里 的 ； 你 又 像 被 践 踏 的 尸 首 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17949', '23', '14', '20', '你 不 得 与 君 王 同 葬 ； 因 为 你 败 坏 你 的 国 ， 杀 戮 你 的 民 。 恶 人 后 裔 的 名 ， 必 永 不 提 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17950', '23', '14', '21', '先 人 既 有 罪 孽 ， 就 要 预 备 杀 戮 他 的 子 孙 ， 免 得 他 们 兴 起 来 ， 得 了 遍 地 ， 在 世 上 修 满 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17951', '23', '14', '22', '＜ 神 要 毁 灭 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17952', '23', '14', '23', '我 必 使 巴 比 伦 为 箭 猪 所 得 ， 又 变 为 水 池 ； 我 要 用 灭 亡 的 扫 帚 扫 净 它 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17953', '23', '14', '24', '＜ 神 要 毁 灭 亚 述 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17954', '23', '14', '25', '就 是 在 我 地 上 打 折 亚 述 人 ， 在 我 山 上 将 他 践 踏 。 他 加 的 轭 必 离 开 以 色 列 人 ； 他 加 的 重 担 必 离 开 他 们 的 肩 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17955', '23', '14', '26', '这 是 向 全 地 所 定 的 旨 意 ； 这 是 向 万 国 所 伸 出 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17956', '23', '14', '27', '万 军 之 耶 和 华 既 然 定 意 ， 谁 能 废 弃 呢 ？ 他 的 手 已 经 伸 出 ， 谁 能 转 回 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17957', '23', '14', '28', '＜ 神 要 毁 灭 非 利 士 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17958', '23', '14', '29', '非 利 士 全 地 啊 ， 不 要 因 击 打 你 的 杖 折 断 就 喜 乐 。 因 为 从 蛇 的 根 必 生 出 毒 蛇 ； 它 所 生 的 是 火 焰 的 飞 龙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17959', '23', '14', '30', '贫 寒 人 的 长 子 必 有 所 食 ； 穷 乏 人 必 安 然 躺 卧 。 我 必 以 饥 荒 治 死 你 的 根 ； 你 所 余 剩 的 人 必 被 杀 戮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17960', '23', '14', '31', '门 哪 ， 应 当 哀 号 ！ 城 啊 ， 应 当 呼 喊 ！ 非 利 士 全 地 啊 ， 你 都 消 化 了 ！ 因 为 有 烟 从 北 方 出 来 ， 他 行 伍 中 并 无 乱 队 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17961', '23', '14', '32', '可 怎 样 回 答 外 邦 ｛ 或 指 非 利 士 ｝ 的 使 者 呢 ？ 必 说 ： 耶 和 华 建 立 了 锡 安 ； 他 百 姓 中 的 困 苦 人 必 投 奔 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17962', '23', '15', '1', '＜ 神 要 毁 灭 摩 押 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17963', '23', '15', '2', '他 们 上 巴 益 ， 又 往 底 本 ， 到 高 处 去 哭 泣 。 摩 押 人 因 尼 波 和 米 底 巴 哀 号 ， 各 人 头 上 光 秃 ， 胡 须 剃 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17964', '23', '15', '3', '他 们 在 街 市 上 都 腰 束 麻 布 ， 在 房 顶 上 和 宽 阔 处 俱 各 哀 号 ， 眼 泪 汪 汪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17965', '23', '15', '4', '希 实 本 和 以 利 亚 利 悲 哀 的 声 音 达 到 雅 杂 ， 所 以 摩 押 带 兵 器 的 高 声 喊 嚷 ， 人 心 战 兢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17966', '23', '15', '5', '我 心 为 摩 押 悲 哀 ； 他 的 贵 胄 ｛ 或 译 ： 逃 民 ｝ 逃 到 琐 珥 ， 到 伊 基 拉 ． 施 利 施 亚 。 他 们 上 鲁 希 坡 ， 随 走 随 哭 ； 在 何 罗 念 的 路 上 ， 因 毁 灭 举 起 哀 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17967', '23', '15', '6', '因 为 宁 林 的 水 成 为 干 涸 ， 青 草 枯 干 ， 嫩 草 灭 没 ， 青 绿 之 物 ， 一 无 所 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17968', '23', '15', '7', '因 此 ， 摩 押 人 所 得 的 财 物 和 所 积 蓄 的 都 要 运 过 柳 树 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17969', '23', '15', '8', '哀 声 遍 闻 摩 押 的 四 境 ； 哀 号 的 声 音 达 到 以 基 莲 ； 哀 号 的 声 音 达 到 比 珥 ． 以 琳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17970', '23', '15', '9', '底 们 的 水 充 满 了 血 ； 我 还 要 加 增 底 们 的 灾 难 ， 叫 狮 子 来 追 上 摩 押 逃 脱 的 民 和 那 地 上 所 余 剩 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17971', '23', '16', '1', '＜ 摩 押 的 难 民 逃 到 犹 大 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17972', '23', '16', '2', '摩 押 的 居 民 ｛ 原 文 是 女 子 ｝ 在 亚 嫩 渡 口 ， 必 像 游 飞 的 鸟 ， 如 拆 窝 的 雏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17973', '23', '16', '3', '求 你 献 谋 略 ， 行 公 平 ， 使 你 的 影 子 在 午 间 如 黑 夜 ， 隐 藏 被 赶 散 的 人 ， 不 可 显 露 逃 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17974', '23', '16', '4', '求 你 容 我 这 被 赶 散 的 人 和 你 同 居 。 至 于 摩 押 ， 求 你 作 他 的 隐 密 处 ， 脱 离 灭 命 者 的 面 。 勒 索 人 的 归 于 无 有 ， 毁 灭 的 事 止 息 了 ， 欺 压 人 的 从 国 中 除 灭 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17975', '23', '16', '5', '必 有 宝 座 因 慈 爱 坚 立 ； 必 有 一 位 诚 诚 实 实 坐 在 其 上 ， 在 大 卫 帐 幕 中 施 行 审 判 ， 寻 求 公 平 ， 速 行 公 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17976', '23', '16', '6', '我 们 听 说 摩 押 人 骄 傲 ， 是 极 其 骄 傲 ； 听 说 他 狂 妄 、 骄 傲 、 忿 怒 ； 他 夸 大 的 话 是 虚 空 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17977', '23', '16', '7', '因 此 ， 摩 押 人 必 为 摩 押 哀 号 ； 人 人 都 要 哀 号 。 你 们 摩 押 人 要 为 吉 珥 ． 哈 列 设 的 葡 萄 饼 哀 叹 ， 极 其 忧 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17978', '23', '16', '8', '因 为 希 实 本 的 田 地 和 西 比 玛 的 葡 萄 树 都 衰 残 了 。 列 国 的 君 主 折 断 其 上 美 好 的 枝 子 ； 这 枝 子 长 到 雅 谢 延 到 旷 野 ， 嫩 枝 向 外 探 出 ， 直 探 过 盐 海 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17979', '23', '16', '9', '因 此 ， 我 要 为 西 比 玛 的 葡 萄 树 哀 哭 ， 与 雅 谢 人 哀 哭 一 样 。 希 实 本 、 以 利 亚 利 啊 ， 我 要 以 眼 泪 浇 灌 你 ； 因 为 有 交 战 呐 喊 的 声 音 临 到 你 夏 天 的 果 子 ， 并 你 收 割 的 庄 稼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17980', '23', '16', '10', '从 肥 美 的 田 中 夺 去 了 欢 喜 快 乐 ； 在 葡 萄 园 里 必 无 歌 唱 ， 也 无 欢 呼 的 声 音 。 踹 酒 的 在 酒 醡 中 不 得 踹 出 酒 来 ； 我 使 他 欢 呼 的 声 音 止 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17981', '23', '16', '11', '因 此 ， 我 心 腹 为 摩 押 哀 鸣 如 琴 ； 我 心 肠 为 吉 珥 ． 哈 列 设 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17982', '23', '16', '12', '摩 押 人 朝 见 的 时 候 ， 在 高 处 疲 乏 ， 又 到 他 圣 所 祈 祷 ， 也 不 蒙 应 允 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17983', '23', '16', '13', '这 是 耶 和 华 从 前 论 摩 押 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17984', '23', '16', '14', '但 现 在 耶 和 华 说 ： “ 三 年 之 内 ， 照 雇 工 的 年 数 ， 摩 押 的 荣 耀 与 他 的 群 众 必 被 藐 视 ， 余 剩 的 人 甚 少 无 几 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17985', '23', '17', '1', '＜ 神 要 刑 罚 亚 兰 和 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17986', '23', '17', '2', '亚 罗 珥 的 城 邑 已 被 撇 弃 ， 必 成 为 牧 羊 之 处 ； 羊 在 那 里 躺 卧 ， 无 人 惊 吓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17987', '23', '17', '3', '以 法 莲 不 再 有 保 障 ； 大 马 士 革 不 再 有 国 权 ； 亚 兰 所 剩 下 的 必 像 以 色 列 人 的 荣 耀 消 灭 一 样 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17988', '23', '17', '4', '到 那 日 ， 雅 各 的 荣 耀 必 至 枵 薄 ； 他 肥 胖 的 身 体 必 渐 瘦 弱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17989', '23', '17', '5', '就 必 像 收 割 的 人 收 敛 禾 稼 ， 用 手 割 取 穗 子 ， 又 像 人 在 利 乏 音 谷 拾 取 遗 落 的 穗 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17990', '23', '17', '6', '其 间 所 剩 下 的 不 多 ， 好 像 人 打 橄 榄 树 ─ ─ 在 尽 上 的 枝 梢 上 只 剩 两 三 个 果 子 ； 在 多 果 树 的 旁 枝 上 只 剩 四 五 个 果 子 。 这 是 耶 和 华 ─ ─ 以 色 列 的 神 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17991', '23', '17', '7', '当 那 日 ， 人 必 仰 望 造 他 们 的 主 ， 眼 目 重 看 以 色 列 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17992', '23', '17', '8', '他 们 必 不 仰 望 祭 坛 ， 就 是 自 己 手 所 筑 的 ， 也 不 重 看 自 己 指 头 所 做 的 ， 无 论 是 木 偶 是 日 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17993', '23', '17', '9', '在 那 日 ， 他 们 的 坚 固 城 必 像 树 林 中 和 山 顶 上 所 撇 弃 的 地 方 ， 就 是 从 前 在 以 色 列 人 面 前 被 人 撇 弃 的 。 这 样 ， 地 就 荒 凉 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17994', '23', '17', '10', '因 你 忘 记 救 你 的 神 ， 不 记 念 你 能 力 的 磐 石 ； 所 以 ， 你 栽 上 佳 美 的 树 秧 子 ， 插 上 异 样 的 栽 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17995', '23', '17', '11', '栽 种 的 日 子 ， 你 周 围 圈 上 篱 笆 ， 又 到 早 晨 使 你 所 种 的 开 花 ； 但 在 愁 苦 极 其 伤 痛 的 日 子 ， 所 收 割 的 都 飞 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17996', '23', '17', '12', '＜ 敌 国 都 被 击 败 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17997', '23', '17', '13', '列 邦 奔 腾 ， 好 像 多 水 滔 滔 ； 但 神 斥 责 他 们 ， 他 们 就 远 远 逃 避 ， 又 被 追 赶 ， 如 同 山 上 的 风 前 糠 ， 又 如 暴 风 前 的 旋 风 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17998', '23', '17', '14', '到 晚 上 有 惊 吓 ， 未 到 早 晨 他 们 就 没 有 了 。 这 是 掳 掠 我 们 之 人 所 得 的 分 ， 是 抢 夺 我 们 之 人 的 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('17999', '23', '18', '1', '＜ 神 要 责 罚 古 实 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18000', '23', '18', '2', '差 遣 使 者 在 水 面 上 ， 坐 蒲 草 船 过 海 。 先 知 说 ： 你 们 快 行 的 使 者 ， 要 到 高 大 光 滑 的 民 那 里 去 。 自 从 开 国 以 来 ， 那 民 极 其 可 畏 ， 是 分 地 界 践 踏 人 的 ； 他 们 的 地 有 江 河 分 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18001', '23', '18', '3', '世 上 一 切 的 居 民 和 地 上 所 住 的 人 哪 ， 山 上 竖 立 大 旗 的 时 候 你 们 要 看 ； 吹 角 的 时 候 你 们 要 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18002', '23', '18', '4', '耶 和 华 对 我 这 样 说 ： 我 要 安 静 ， 在 我 的 居 所 观 看 ， 如 同 日 光 中 的 清 热 ， 又 如 露 水 的 云 雾 在 收 割 的 热 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18003', '23', '18', '5', '收 割 之 先 ， 花 开 已 谢 ， 花 也 成 了 将 熟 的 葡 萄 ； 他 必 用 镰 刀 削 去 嫩 枝 ， 又 砍 掉 蔓 延 的 枝 条 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18004', '23', '18', '6', '都 要 撇 给 山 间 的 鸷 鸟 和 地 上 的 野 兽 。 夏 天 ， 鸷 鸟 要 宿 在 其 上 ； 冬 天 ， 野 兽 都 卧 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18005', '23', '18', '7', '到 那 时 ， 这 高 大 光 滑 的 民 ， 就 是 从 开 国 以 来 极 其 可 畏 、 分 地 界 践 踏 人 的 ， 他 们 的 地 有 江 河 分 开 ； 他 们 必 将 礼 物 奉 给 万 军 之 耶 和 华 ， 就 是 奉 到 锡 安 山 ─ ─ 耶 和 华 安 置 他 名 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18006', '23', '19', '1', '＜ 神 要 惩 罚 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18007', '23', '19', '2', '我 必 激 动 埃 及 人 攻 击 埃 及 人 ─ ─ 弟 兄 攻 击 弟 兄 ， 邻 舍 攻 击 邻 舍 ； 这 城 攻 击 那 城 ， 这 国 攻 击 那 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18008', '23', '19', '3', '埃 及 人 的 心 神 必 在 里 面 耗 尽 ； 我 必 败 坏 他 们 的 谋 略 。 他 们 必 求 问 偶 像 和 念 咒 的 、 交 鬼 的 、 行 巫 术 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18009', '23', '19', '4', '我 必 将 埃 及 人 交 在 残 忍 主 的 手 中 ； 强 暴 王 必 辖 制 他 们 。 这 是 主 ─ ─ 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18010', '23', '19', '5', '海 中 的 水 必 绝 尽 ， 河 也 消 没 干 涸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18011', '23', '19', '6', '江 河 要 变 臭 ； 埃 及 的 河 水 都 必 减 少 枯 干 。 苇 子 和 芦 荻 都 必 衰 残 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18012', '23', '19', '7', '靠 尼 罗 河 旁 的 草 田 ， 并 沿 尼 罗 河 所 种 的 田 ， 都 必 枯 干 。 庄 稼 被 风 吹 去 ， 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18013', '23', '19', '8', '打 鱼 的 必 哀 哭 。 在 尼 罗 河 一 切 钓 鱼 的 必 悲 伤 ； 在 水 上 撒 网 的 必 都 衰 弱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18014', '23', '19', '9', '用 梳 好 的 麻 造 物 的 和 织 白 布 的 都 必 羞 愧 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18015', '23', '19', '10', '国 柱 必 被 打 碎 ， 所 有 佣 工 的 ， 心 必 愁 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18016', '23', '19', '11', '琐 安 的 首 领 极 其 愚 昧 ； 法 老 大 有 智 慧 的 谋 士 ， 所 筹 划 的 成 为 愚 谋 。 你 们 怎 敢 对 法 老 说 ： 我 是 智 慧 人 的 子 孙 ， 我 是 古 王 的 后 裔 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18017', '23', '19', '12', '你 的 智 慧 人 在 哪 里 呢 ？ 万 军 之 耶 和 华 向 埃 及 所 定 的 旨 意 ， 他 们 可 以 知 道 ， 可 以 告 诉 你 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18018', '23', '19', '13', '琐 安 的 首 领 都 变 为 愚 昧 ； 挪 弗 的 首 领 都 受 了 迷 惑 。 当 埃 及 支 派 房 角 石 的 ， 使 埃 及 人 走 错 了 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18019', '23', '19', '14', '耶 和 华 使 乖 谬 的 灵 搀 入 埃 及 中 间 ； 首 领 使 埃 及 一 切 所 做 的 都 有 差 错 ， 好 像 醉 酒 之 人 呕 吐 的 时 候 东 倒 西 歪 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18020', '23', '19', '15', '埃 及 中 ， 无 论 是 头 与 尾 ， 棕 枝 与 芦 苇 ， 所 做 之 工 都 不 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18021', '23', '19', '16', '到 那 日 ， 埃 及 人 必 像 妇 人 一 样 ， 他 们 必 因 万 军 之 耶 和 华 在 埃 及 以 上 所 抡 的 手 ， 战 兢 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18022', '23', '19', '17', '犹 大 地 必 使 埃 及 惊 恐 ， 向 谁 提 起 犹 大 地 ， 谁 就 惧 怕 。 这 是 因 万 军 之 耶 和 华 向 埃 及 所 定 的 旨 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18023', '23', '19', '18', '当 那 日 ， 埃 及 地 必 有 五 城 的 人 说 迦 南 的 方 言 ， 又 指 着 万 军 之 耶 和 华 起 誓 。 有 一 城 必 称 为 “ 灭 亡 城 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18024', '23', '19', '19', '当 那 日 ， 在 埃 及 地 中 必 有 为 耶 和 华 筑 的 一 座 坛 ； 在 埃 及 的 边 界 上 必 有 为 耶 和 华 立 的 一 根 柱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18025', '23', '19', '20', '这 都 要 在 埃 及 地 为 万 军 之 耶 和 华 作 记 号 和 证 据 。 埃 及 人 因 为 受 人 的 欺 压 哀 求 耶 和 华 ， 他 就 差 遣 一 位 救 主 作 护 卫 者 ， 拯 救 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18026', '23', '19', '21', '耶 和 华 必 被 埃 及 人 所 认 识 。 在 那 日 ， 埃 及 人 必 认 识 耶 和 华 ， 也 要 献 祭 物 和 供 物 敬 拜 他 ， 并 向 耶 和 华 许 愿 还 愿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18027', '23', '19', '22', '耶 和 华 必 击 打 埃 及 ， 又 击 打 又 医 治 ， 埃 及 人 就 归 向 耶 和 华 。 他 必 应 允 他 们 的 祷 告 ， 医 治 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18028', '23', '19', '23', '当 那 日 ， 必 有 从 埃 及 通 亚 述 去 的 大 道 。 亚 述 人 要 进 入 埃 及 ， 埃 及 人 也 进 入 亚 述 ； 埃 及 人 要 与 亚 述 人 一 同 敬 拜 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18029', '23', '19', '24', '当 那 日 ， 以 色 列 必 与 埃 及 、 亚 述 三 国 一 律 ， 使 地 上 的 人 得 福 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18030', '23', '19', '25', '因 为 万 军 之 耶 和 华 赐 福 给 他 们 ， 说 ： “ 埃 及 ─ ─ 我 的 百 姓 ， 亚 述 ─ ─ 我 手 的 工 作 ， 以 色 列 ─ ─ 我 的 产 业 ， 都 有 福 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18031', '23', '20', '1', '＜ 赤 身 的 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18032', '23', '20', '2', '那 时 ， 耶 和 华 晓 谕 亚 摩 斯 的 儿 子 以 赛 亚 说 ： “ 你 去 解 掉 你 腰 间 的 麻 布 ， 脱 下 你 脚 上 的 鞋 。 ” 以 赛 亚 就 这 样 做 ， 露 身 赤 脚 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18033', '23', '20', '3', '耶 和 华 说 ： “ 我 仆 人 以 赛 亚 怎 样 露 身 赤 脚 行 走 三 年 ， 作 为 关 乎 埃 及 和 古 实 的 预 兆 奇 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18034', '23', '20', '4', '照 样 ， 亚 述 王 也 必 掳 去 埃 及 人 ， 掠 去 古 实 人 ， 无 论 老 少 ， 都 露 身 赤 脚 ， 现 出 下 体 ， 使 埃 及 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18035', '23', '20', '5', '以 色 列 人 必 因 所 仰 望 的 古 实 ， 所 夸 耀 的 埃 及 ， 惊 惶 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18036', '23', '20', '6', '“ 那 时 ， 这 沿 海 一 带 的 居 民 必 说 ： ‘ 看 哪 ， 我 们 素 所 仰 望 的 ， 就 是 我 们 为 脱 离 亚 述 王 逃 往 求 救 的 ， 不 过 是 如 此 ！ 我 们 怎 能 逃 脱 呢 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18037', '23', '21', '1', '＜ 巴 比 伦 的 覆 灭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18038', '23', '21', '2', '令 人 凄 惨 的 异 象 已 默 示 于 我 。 诡 诈 的 行 诡 诈 ， 毁 灭 的 行 毁 灭 。 以 拦 哪 ， 你 要 上 去 ！ 米 底 亚 啊 ， 你 要 围 困 ！ 主 说 ： 我 使 一 切 叹 息 止 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18039', '23', '21', '3', '所 以 ， 我 满 腰 疼 痛 ； 痛 苦 将 我 抓 住 ， 好 像 产 难 的 妇 人 一 样 。 我 疼 痛 甚 至 不 能 听 ； 我 惊 惶 甚 至 不 能 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18040', '23', '21', '4', '我 心 慌 张 ， 惊 恐 威 吓 我 。 我 所 羡 慕 的 黄 昏 ， 变 为 我 的 战 兢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18041', '23', '21', '5', '他 们 摆 设 筵 席 ， 派 人 守 望 ， 又 吃 又 喝 。 首 领 啊 ， 你 们 起 来 ， 用 油 抹 盾 牌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18042', '23', '21', '6', '主 对 我 如 此 说 ： 你 去 设 立 守 望 的 ， 使 他 将 所 看 见 的 述 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18043', '23', '21', '7', '他 看 见 军 队 ， 就 是 骑 马 的 一 对 一 对 地 来 ， 又 看 见 驴 队 ， 骆 驼 队 ， 就 要 侧 耳 细 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18044', '23', '21', '8', '他 像 狮 子 吼 叫 ， 说 ： 主 啊 ， 我 白 日 常 站 在 望 楼 上 ， 整 夜 立 在 我 守 望 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18045', '23', '21', '9', '看 哪 ， 有 一 队 军 兵 骑 着 马 ， 一 对 一 对 地 来 。 他 就 说 ： 巴 比 伦 倾 倒 了 ！ 倾 倒 了 ！ 他 一 切 雕 刻 的 神 像 都 打 碎 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18046', '23', '21', '10', '我 被 打 的 禾 稼 ， 我 场 上 的 谷 啊 ， 我 从 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 那 里 所 听 见 的 ， 都 告 诉 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18047', '23', '21', '11', '＜ 论 以 东 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18048', '23', '21', '12', '守 望 的 说 ： 早 晨 将 到 ， 黑 夜 也 来 。 你 们 若 要 问 就 可 以 问 ， 可 以 回 头 再 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18049', '23', '21', '13', '＜ 论 阿 拉 伯 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18050', '23', '21', '14', '提 玛 地 的 居 民 拿 水 来 ， 送 给 口 渴 的 ， 拿 饼 来 迎 接 逃 避 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18051', '23', '21', '15', '因 为 他 们 逃 避 刀 剑 和 出 了 鞘 的 刀 ， 并 上 了 弦 的 弓 与 刀 兵 的 重 灾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18052', '23', '21', '16', '主 对 我 这 样 说 ： “ 一 年 之 内 ， 照 雇 工 的 年 数 ， 基 达 的 一 切 荣 耀 必 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18053', '23', '21', '17', '弓 箭 手 所 余 剩 的 ， 就 是 基 达 人 的 勇 士 ， 必 然 稀 少 ， 因 为 这 是 耶 和 华 ─ ─ 以 色 列 的 神 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18054', '23', '22', '1', '＜ 论 耶 路 撒 冷 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18055', '23', '22', '2', '你 这 满 处 呐 喊 、 大 有 喧 哗 的 城 ， 欢 乐 的 邑 啊 ， 你 中 间 被 杀 的 并 不 是 被 刀 杀 ， 也 不 是 因 打 仗 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18056', '23', '22', '3', '你 所 有 的 官 长 一 同 逃 跑 ， 都 为 弓 箭 手 所 捆 绑 。 你 中 间 一 切 被 找 到 的 都 一 同 被 捆 绑 ； 他 们 本 是 逃 往 远 方 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18057', '23', '22', '4', '所 以 我 说 ： 你 们 转 眼 不 看 我 ， 我 要 痛 哭 。 不 要 因 我 众 民 ｛ 原 文 是 民 女 ｝ 的 毁 灭 ， 就 竭 力 安 慰 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18058', '23', '22', '5', '因 为 主 ─ ─ 万 军 之 耶 和 华 使 “ 异 象 谷 ” 有 溃 乱 、 践 踏 、 烦 扰 的 日 子 。 城 被 攻 破 ， 哀 声 达 到 山 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18059', '23', '22', '6', '以 拦 带 着 箭 袋 ， 还 有 坐 战 车 的 和 马 兵 ； 吉 珥 揭 开 盾 牌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18060', '23', '22', '7', '你 嘉 美 的 谷 遍 满 战 车 ， 也 有 马 兵 在 城 门 前 排 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18061', '23', '22', '8', '他 去 掉 犹 大 的 遮 盖 。 那 日 ， 你 就 仰 望 林 库 内 的 军 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18062', '23', '22', '9', '你 们 看 见 大 卫 城 的 破 口 很 多 ， 便 聚 积 下 池 的 水 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18063', '23', '22', '10', '又 数 点 耶 路 撒 冷 的 房 屋 ， 将 房 屋 拆 毁 ， 修 补 城 墙 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18064', '23', '22', '11', '又 在 两 道 城 墙 中 间 挖 一 个 聚 水 池 可 盛 旧 池 的 水 ， 却 不 仰 望 做 这 事 的 主 ， 也 不 顾 念 从 古 定 这 事 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18065', '23', '22', '12', '当 那 日 ， 主 ─ ─ 万 军 之 耶 和 华 叫 人 哭 泣 哀 号 ， 头 上 光 秃 ， 身 披 麻 布 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18066', '23', '22', '13', '谁 知 ， 人 倒 欢 喜 快 乐 ， 宰 牛 杀 羊 ， 吃 肉 喝 酒 ， 说 ： 我 们 吃 喝 吧 ！ 因 为 明 天 要 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18067', '23', '22', '14', '万 军 之 耶 和 华 亲 自 默 示 我 说 ： 这 罪 孽 直 到 你 们 死 ， 断 不 得 赦 免 ！ 这 是 主 ─ ─ 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18068', '23', '22', '15', '＜ 对 舍 伯 那 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18069', '23', '22', '16', '‘ 你 在 这 里 做 什 么 呢 ？ 有 什 么 人 竟 在 这 里 凿 坟 墓 ， 就 是 在 高 处 为 自 己 凿 坟 墓 ， 在 磐 石 中 为 自 己 凿 出 安 身 之 所 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18070', '23', '22', '17', '看 哪 ， 耶 和 华 必 像 大 有 力 的 人 ， 将 你 紧 紧 缠 裹 ， 竭 力 抛 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18071', '23', '22', '18', '他 必 将 你 滚 成 一 团 ， 抛 在 宽 阔 之 地 ， 好 像 抛 球 一 样 。 你 这 主 人 家 的 羞 辱 ， 必 在 那 里 坐 你 荣 耀 的 车 ， 也 必 在 那 里 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18072', '23', '22', '19', '我 必 赶 逐 你 离 开 官 职 ； 你 必 从 你 的 原 位 撤 下 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18073', '23', '22', '20', '“ 到 那 日 ， 我 必 召 我 仆 人 希 勒 家 的 儿 子 以 利 亚 敬 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18074', '23', '22', '21', '将 你 的 外 袍 给 他 穿 上 ， 将 你 的 腰 带 给 他 系 紧 ， 将 你 的 政 权 交 在 他 手 中 。 他 必 作 耶 路 撒 冷 居 民 和 犹 大 家 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18075', '23', '22', '22', '我 必 将 大 卫 家 的 钥 匙 放 在 他 肩 头 上 。 他 开 ， 无 人 能 关 ； 他 关 ， 无 人 能 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18076', '23', '22', '23', '我 必 将 他 安 稳 ， 像 钉 子 钉 在 坚 固 处 ； 他 必 作 为 他 父 家 荣 耀 的 宝 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18077', '23', '22', '24', '他 父 家 所 有 的 荣 耀 ， 连 儿 女 带 子 孙 ， 都 挂 在 他 身 上 ， 好 像 一 切 小 器 皿 ， 从 杯 子 到 酒 瓶 挂 上 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18078', '23', '22', '25', '万 军 之 耶 和 华 说 ： 当 那 日 ， 钉 在 坚 固 处 的 钉 子 必 压 斜 ， 被 砍 断 落 地 ； 挂 在 其 上 的 重 担 必 被 剪 断 。 因 为 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18079', '23', '23', '1', '＜ 神 要 责 罚 泰 尔 的 海 港 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18080', '23', '23', '2', '沿 海 的 居 民 ， 就 是 素 来 靠 航 海 西 顿 的 商 家 得 丰 盛 的 ， 你 们 当 静 默 无 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18081', '23', '23', '3', '在 大 水 之 上 ， 西 曷 的 粮 食 、 尼 罗 河 的 庄 稼 是 泰 尔 的 进 项 ； 她 作 列 国 的 大 码 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18082', '23', '23', '4', '西 顿 哪 ， 你 当 惭 愧 ； 因 为 大 海 说 ， 就 是 海 中 的 保 障 说 ： 我 没 有 劬 劳 ， 也 没 有 生 产 ， 没 有 养 育 男 子 ， 也 没 有 抚 养 童 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18083', '23', '23', '5', '这 风 声 传 到 埃 及 ； 埃 及 人 为 泰 尔 的 风 声 极 其 疼 痛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18084', '23', '23', '6', '泰 尔 人 哪 ， 你 们 当 过 到 他 施 去 ； 沿 海 的 居 民 哪 ， 你 们 都 当 哀 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18085', '23', '23', '7', '这 是 你 们 欢 乐 的 城 ， 从 上 古 而 有 的 吗 ？ 其 中 的 居 民 往 远 方 寄 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18086', '23', '23', '8', '泰 尔 本 是 赐 冠 冕 的 。 她 的 商 家 是 王 子 ； 她 的 买 卖 人 是 世 上 的 尊 贵 人 。 遭 遇 如 此 是 谁 定 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18087', '23', '23', '9', '是 万 军 之 耶 和 华 所 定 的 ！ 为 要 污 辱 一 切 高 傲 的 荣 耀 ， 使 地 上 一 切 的 尊 贵 人 被 藐 视 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18088', '23', '23', '10', '他 施 的 民 ｛ 原 文 是 女 ｝ 哪 ， 可 以 流 行 你 的 地 ， 好 像 尼 罗 河 ； 不 再 有 腰 带 拘 紧 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18089', '23', '23', '11', '耶 和 华 已 经 向 海 伸 手 ， 震 动 列 国 。 至 于 迦 南 ， 他 已 经 吩 咐 拆 毁 其 中 的 保 障 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18090', '23', '23', '12', '他 又 说 ： 受 欺 压 西 顿 的 居 民 ｛ 原 文 是 处 女 ｝ 哪 ， 你 必 不 得 再 欢 乐 。 起 来 ！ 过 到 基 提 去 ； 就 是 在 那 里 也 不 得 安 歇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18091', '23', '23', '13', '（ 看 哪 ， 迦 勒 底 人 之 地 向 来 没 有 这 民 ， 这 国 是 亚 述 人 为 住 旷 野 的 人 所 立 的 。 现 在 他 们 建 筑 戍 楼 ， 拆 毁 泰 尔 的 宫 殿 ， 使 她 成 为 荒 凉 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18092', '23', '23', '14', '他 施 的 船 只 都 要 哀 号 ， 因 为 你 们 的 保 障 变 为 荒 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18093', '23', '23', '15', '到 那 时 ， 泰 尔 必 被 忘 记 七 十 年 ， 照 着 一 王 的 年 日 。 七 十 年 后 ， 泰 尔 的 景 况 必 像 妓 女 所 唱 的 歌 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18094', '23', '23', '16', '你 这 被 忘 记 的 妓 女 啊 ， 拿 琴 周 流 城 内 ， 巧 弹 多 唱 ， 使 人 再 想 念 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18095', '23', '23', '17', '七 十 年 后 ， 耶 和 华 必 眷 顾 泰 尔 ， 她 就 仍 得 利 息 ｛ 原 文 是 雇 价 ； 下 同 ｝ ， 与 地 上 的 万 国 交 易 ｛ 原 文 是 行 淫 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18096', '23', '23', '18', '她 的 货 财 和 利 息 要 归 耶 和 华 为 圣 ， 必 不 积 攒 存 留 ； 因 为 她 的 货 财 必 为 住 在 耶 和 华 面 前 的 人 所 得 ， 使 他 们 吃 饱 ， 穿 耐 久 的 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18097', '23', '24', '1', '＜ 耶 和 华 要 责 罚 世 界 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18098', '23', '24', '2', '那 时 百 姓 怎 样 ， 祭 司 也 怎 样 ； 仆 人 怎 样 ， 主 人 也 怎 样 ； 婢 女 怎 样 ， 主 母 也 怎 样 ； 买 物 的 怎 样 ， 卖 物 的 也 怎 样 ； 放 债 的 怎 样 ， 借 债 的 也 怎 样 ； 取 利 的 怎 样 ， 出 利 的 也 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18099', '23', '24', '3', '地 必 全 然 空 虚 ， 尽 都 荒 凉 ； 因 为 这 话 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18100', '23', '24', '4', '地 上 悲 哀 衰 残 ， 世 界 败 落 衰 残 ； 地 上 居 高 位 的 人 也 败 落 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18101', '23', '24', '5', '地 被 其 上 的 居 民 污 秽 ； 因 为 他 们 犯 了 律 法 ， 废 了 律 例 ， 背 了 永 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18102', '23', '24', '6', '所 以 ， 地 被 咒 诅 吞 灭 ； 住 在 其 上 的 显 为 有 罪 。 地 上 的 居 民 被 火 焚 烧 ， 剩 下 的 人 稀 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18103', '23', '24', '7', '新 酒 悲 哀 ， 葡 萄 树 衰 残 ； 心 中 欢 乐 的 俱 都 叹 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18104', '23', '24', '8', '击 鼓 之 乐 止 息 ； 宴 乐 人 的 声 音 完 毕 ， 弹 琴 之 乐 也 止 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18105', '23', '24', '9', '人 必 不 得 饮 酒 唱 歌 ； 喝 浓 酒 的 ， 必 以 为 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18106', '23', '24', '10', '荒 凉 的 城 拆 毁 了 ； 各 家 关 门 闭 户 ， 使 人 都 不 得 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18107', '23', '24', '11', '在 街 上 因 酒 有 悲 叹 的 声 音 ； 一 切 喜 乐 变 为 昏 暗 ； 地 上 的 欢 乐 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18108', '23', '24', '12', '城 中 只 有 荒 凉 ； 城 门 拆 毁 净 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18109', '23', '24', '13', '在 地 上 的 万 民 中 ， 必 像 打 过 的 橄 榄 树 ， 又 像 已 摘 的 葡 萄 所 剩 无 几 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18110', '23', '24', '14', '这 些 人 要 高 声 欢 呼 ； 他 们 为 耶 和 华 的 威 严 ， 从 海 那 里 扬 起 声 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18111', '23', '24', '15', '因 此 ， 你 们 要 在 东 方 荣 耀 耶 和 华 ， 在 众 海 岛 荣 耀 耶 和 华 ─ ─ 以 色 列 神 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18112', '23', '24', '16', '我 们 听 见 从 地 极 有 人 歌 唱 ， 说 ： 荣 耀 归 于 义 人 。 我 却 说 ： 我 消 灭 了 ！ 我 消 灭 了 ， 我 有 祸 了 ！ 诡 诈 的 行 诡 诈 ； 诡 诈 的 大 行 诡 诈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18113', '23', '24', '17', '地 上 的 居 民 哪 ， 恐 惧 、 陷 坑 、 网 罗 都 临 近 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18114', '23', '24', '18', '躲 避 恐 惧 声 音 的 必 坠 入 陷 坑 ； 从 陷 坑 上 来 的 必 被 网 罗 缠 住 ； 因 为 天 上 的 窗 户 都 开 了 ， 地 的 根 基 也 震 动 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18115', '23', '24', '19', '地 全 然 破 坏 ， 尽 都 崩 裂 ， 大 大 地 震 动 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18116', '23', '24', '20', '地 要 东 倒 西 歪 ， 好 像 醉 酒 的 人 ； 又 摇 来 摇 去 ， 好 像 吊 床 。 罪 过 在 其 上 沉 重 ， 必 然 塌 陷 ， 不 能 复 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18117', '23', '24', '21', '到 那 日 ， 耶 和 华 在 高 处 必 惩 罚 高 处 的 众 军 ， 在 地 上 必 惩 罚 地 上 的 列 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18118', '23', '24', '22', '他 们 必 被 聚 集 ， 像 囚 犯 被 聚 在 牢 狱 中 ， 并 要 囚 在 监 牢 里 ， 多 日 之 后 便 被 讨 罪 ｛ 或 译 ： 眷 顾 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18119', '23', '24', '23', '那 时 ， 月 亮 要 蒙 羞 ， 日 头 要 惭 愧 ； 因 为 万 军 之 耶 和 华 必 在 锡 安 山 ， 在 耶 路 撒 冷 作 王 ； 在 敬 畏 他 的 长 老 面 前 ， 必 有 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18120', '23', '25', '1', '＜ 一 首 赞 美 诗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18121', '23', '25', '2', '你 使 城 变 为 乱 堆 ， 使 坚 固 城 变 为 荒 场 ， 使 外 邦 人 宫 殿 的 城 不 再 为 城 ， 永 远 不 再 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18122', '23', '25', '3', '所 以 ， 刚 强 的 民 必 荣 耀 你 ； 强 暴 之 国 的 城 必 敬 畏 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18123', '23', '25', '4', '因 为 当 强 暴 人 催 逼 人 的 时 候 ， 如 同 暴 风 直 吹 墙 壁 ， 你 就 作 贫 穷 人 的 保 障 ， 作 困 乏 人 急 难 中 的 保 障 ， 作 躲 暴 风 之 处 ， 作 避 炎 热 的 阴 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18124', '23', '25', '5', '你 要 压 制 外 邦 人 的 喧 哗 ， 好 像 干 燥 地 的 热 气 下 落 ； 禁 止 强 暴 人 的 凯 歌 ， 好 像 热 气 被 云 影 消 化 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18125', '23', '25', '6', '＜ 神 预 备 筵 席 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18126', '23', '25', '7', '他 又 必 在 这 山 上 除 灭 遮 盖 万 民 之 物 和 遮 蔽 万 国 蒙 脸 的 帕 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18127', '23', '25', '8', '他 已 经 吞 灭 死 亡 直 到 永 远 。 主 耶 和 华 必 擦 去 各 人 脸 上 的 眼 泪 ， 又 除 掉 普 天 下 他 百 姓 的 羞 辱 ， 因 为 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18128', '23', '25', '9', '到 那 日 ， 人 必 说 ： “ 看 哪 ， 这 是 我 们 的 神 ； 我 们 素 来 等 候 他 ， 他 必 拯 救 我 们 。 这 是 耶 和 华 ， 我 们 素 来 等 候 他 ， 我 们 必 因 他 的 救 恩 欢 喜 快 乐 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18129', '23', '25', '10', '＜ 神 要 刑 罚 摩 押 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18130', '23', '25', '11', '他 必 在 其 中 伸 开 手 ， 好 像 洑 水 的 伸 开 手 洑 水 一 样 ； 但 耶 和 华 必 使 他 的 骄 傲 和 他 手 所 行 的 诡 计 一 并 败 落 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18131', '23', '25', '12', '耶 和 华 使 你 城 上 的 坚 固 高 台 倾 倒 ， 拆 平 ， 直 到 尘 埃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18132', '23', '26', '1', '＜ 神 使 他 的 百 姓 得 胜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18133', '23', '26', '2', '敞 开 城 门 ， 使 守 信 的 义 民 得 以 进 入 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18134', '23', '26', '3', '坚 心 倚 赖 你 的 ， 你 必 保 守 他 十 分 平 安 ， 因 为 他 倚 靠 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18135', '23', '26', '4', '你 们 当 倚 靠 耶 和 华 直 到 永 远 ， 因 为 耶 和 华 是 永 久 的 磐 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18136', '23', '26', '5', '他 使 住 高 处 的 与 高 城 一 并 败 落 ， 将 城 拆 毁 ， 拆 平 ， 直 到 尘 埃 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18137', '23', '26', '6', '要 被 脚 践 踏 ， 就 是 被 困 苦 人 的 脚 和 穷 乏 人 的 脚 践 踏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18138', '23', '26', '7', '义 人 的 道 是 正 直 的 ； 你 为 正 直 的 主 ， 必 修 平 义 人 的 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18139', '23', '26', '8', '耶 和 华 啊 ， 我 们 在 你 行 审 判 的 路 上 等 候 你 ； 我 们 心 里 所 羡 慕 的 是 你 的 名 ， 就 是 你 那 可 记 念 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18140', '23', '26', '9', '夜 间 ， 我 心 中 羡 慕 你 ； 我 里 面 的 灵 切 切 寻 求 你 。 因 为 你 在 世 上 行 审 判 的 时 候 ， 地 上 的 居 民 就 学 习 公 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18141', '23', '26', '10', '以 恩 惠 待 恶 人 ， 他 仍 不 学 习 公 义 ； 在 正 直 的 地 上 ， 他 必 行 事 不 义 ， 也 不 注 意 耶 和 华 的 威 严 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18142', '23', '26', '11', '耶 和 华 啊 ， 你 的 手 高 举 ， 他 们 仍 然 不 看 ； 却 要 看 你 为 百 姓 发 的 热 心 ， 因 而 抱 愧 ， 并 且 有 火 烧 灭 你 的 敌 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18143', '23', '26', '12', '耶 和 华 啊 ， 你 必 派 定 我 们 得 平 安 ， 因 为 我 们 所 做 的 事 都 是 你 给 我 们 成 就 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18144', '23', '26', '13', '耶 和 华 ─ ─ 我 们 的 神 啊 ， 在 你 以 外 曾 有 别 的 主 管 辖 我 们 ， 但 我 们 专 要 倚 靠 你 ， 提 你 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18145', '23', '26', '14', '他 们 死 了 ， 必 不 能 再 活 ； 他 们 去 世 ， 必 不 能 再 起 ； 因 为 你 刑 罚 他 们 ， 毁 灭 他 们 ， 他 们 的 名 号 就 全 然 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18146', '23', '26', '15', '耶 和 华 啊 ， 你 增 添 国 民 ， 你 增 添 国 民 ； 你 得 了 荣 耀 ， 又 扩 张 地 的 四 境 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18147', '23', '26', '16', '耶 和 华 啊 ， 他 们 在 急 难 中 寻 求 你 ； 你 的 惩 罚 临 到 他 们 身 上 ， 他 们 就 倾 心 吐 胆 祷 告 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18148', '23', '26', '17', '妇 人 怀 孕 ， 临 产 疼 痛 ， 在 痛 苦 之 中 喊 叫 ； 耶 和 华 啊 ， 我 们 在 你 面 前 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18149', '23', '26', '18', '我 们 也 曾 怀 孕 疼 痛 ， 所 产 的 竟 像 风 一 样 。 我 们 在 地 上 未 曾 行 什 么 拯 救 的 事 ； 世 上 的 居 民 也 未 曾 败 落 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18150', '23', '26', '19', '死 人 ｛ 原 文 是 你 的 死 人 ｝ 要 复 活 ， 尸 首 ｛ 原 文 是 我 的 尸 首 ｝ 要 兴 起 。 睡 在 尘 埃 的 啊 ， 要 醒 起 歌 唱 ！ 因 你 的 甘 露 好 像 菜 蔬 上 的 甘 露 ， 地 也 要 交 出 死 人 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18151', '23', '26', '20', '＜ 审 判 和 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18152', '23', '26', '21', '因 为 耶 和 华 从 他 的 居 所 出 来 ， 要 刑 罚 地 上 居 民 的 罪 孽 。 地 也 必 露 出 其 中 的 血 ， 不 再 掩 盖 被 杀 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18153', '23', '27', '1', '到 那 日 ， 耶 和 华 必 用 他 刚 硬 有 力 的 大 刀 刑 罚 鳄 鱼 ─ ─ 就 是 那 快 行 的 蛇 ， 刑 罚 鳄 鱼 ─ ─ 就 是 那 曲 行 的 蛇 ， 并 杀 海 中 的 大 鱼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18154', '23', '27', '2', '当 那 日 ， 有 出 酒 的 葡 萄 园 ， 你 们 要 指 这 园 唱 歌 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18155', '23', '27', '3', '我 ─ ─ 耶 和 华 是 看 守 葡 萄 园 的 ； 我 必 时 刻 浇 灌 ， 昼 夜 看 守 ， 免 得 有 人 损 害 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18156', '23', '27', '4', '我 心 中 不 存 忿 怒 。 惟 愿 荆 棘 蒺 藜 与 我 交 战 ， 我 就 勇 往 直 前 ， 把 它 一 同 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18157', '23', '27', '5', '不 然 ， 让 它 持 住 我 的 能 力 ， 使 它 与 我 和 好 ， 愿 它 与 我 和 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18158', '23', '27', '6', '将 来 雅 各 要 扎 根 ， 以 色 列 要 发 芽 开 花 ； 他 们 的 果 实 必 充 满 世 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18159', '23', '27', '7', '主 击 打 他 们 ， 岂 像 击 打 那 些 击 打 他 们 的 人 吗 ？ 他 们 被 杀 戮 ， 岂 像 被 他 们 所 杀 戮 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18160', '23', '27', '8', '你 打 发 他 们 去 ， 是 相 机 宜 与 他 们 相 争 ； 刮 东 风 的 日 子 ， 就 用 暴 风 将 他 们 逐 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18161', '23', '27', '9', '所 以 ， 雅 各 的 罪 孽 得 赦 免 ， 他 的 罪 过 得 除 掉 的 果 效 ， 全 在 乎 此 ： 就 是 他 叫 祭 坛 的 石 头 变 为 打 碎 的 灰 石 ， 以 致 木 偶 和 日 像 不 再 立 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18162', '23', '27', '10', '因 为 坚 固 城 变 为 凄 凉 ， 成 了 撇 下 离 弃 的 居 所 ， 像 旷 野 一 样 ； 牛 犊 必 在 那 里 吃 草 ， 在 那 里 躺 卧 ， 并 吃 尽 其 中 的 树 枝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18163', '23', '27', '11', '枝 条 枯 干 ， 必 被 折 断 ； 妇 女 要 来 点 火 烧 着 。 因 为 这 百 姓 蒙 昧 无 知 ， 所 以 ， 创 造 他 们 的 必 不 怜 恤 他 们 ； 造 成 他 们 的 也 不 施 恩 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18164', '23', '27', '12', '以 色 列 人 哪 ， 到 那 日 ， 耶 和 华 必 从 大 河 ， 直 到 埃 及 小 河 ， 将 你 们 一 一 地 收 集 ， 如 同 人 打 树 拾 果 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18165', '23', '27', '13', '当 那 日 ， 必 大 发 角 声 ， 在 亚 述 地 将 要 灭 亡 的 ， 并 在 埃 及 地 被 赶 散 的 ， 都 要 来 ， 他 们 就 在 耶 路 撒 冷 圣 山 上 敬 拜 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18166', '23', '28', '1', '＜ 对 北 国 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18167', '23', '28', '2', '看 哪 ， 主 有 一 大 能 大 力 者 ， 像 一 阵 冰 雹 ， 像 毁 灭 的 暴 风 ， 像 涨 溢 的 大 水 ， 他 必 用 手 将 冠 冕 摔 落 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18168', '23', '28', '3', '以 法 莲 高 傲 的 酒 徒 ， 他 的 冠 冕 必 被 踏 在 脚 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18169', '23', '28', '4', '那 荣 美 将 残 之 花 ， 就 是 在 肥 美 谷 山 上 的 ， 必 像 夏 令 以 前 初 熟 的 无 花 果 ； 看 见 这 果 的 就 注 意 ， 一 到 手 中 就 吞 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18170', '23', '28', '5', '到 那 日 ， 万 军 之 耶 和 华 必 作 他 余 剩 之 民 的 荣 冠 华 冕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18171', '23', '28', '6', '也 作 了 在 位 上 行 审 判 者 公 平 之 灵 ， 并 城 门 口 打 退 仇 敌 者 的 力 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18172', '23', '28', '7', '＜ 以 赛 亚 和 犹 大 酒 醉 的 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18173', '23', '28', '8', '因 为 各 席 上 满 了 呕 吐 的 污 秽 ， 无 一 处 干 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18174', '23', '28', '9', '讥 诮 先 知 的 说 ： 他 要 将 知 识 指 教 谁 呢 ？ 要 使 谁 明 白 传 言 呢 ？ 是 那 刚 断 奶 离 怀 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18175', '23', '28', '10', '他 竟 命 上 加 命 ， 令 上 加 令 ， 律 上 加 律 ， 例 上 加 例 ， 这 里 一 点 ， 那 里 一 点 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18176', '23', '28', '11', '先 知 说 ： 不 然 ， 主 要 藉 异 邦 人 的 嘴 唇 和 外 邦 人 的 舌 头 对 这 百 姓 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18177', '23', '28', '12', '他 曾 对 他 们 说 ： 你 们 要 使 疲 乏 人 得 安 息 ， 这 样 才 得 安 息 ， 才 得 舒 畅 ， 他 们 却 不 肯 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18178', '23', '28', '13', '所 以 ， 耶 和 华 向 他 们 说 的 话 是 命 上 加 命 ， 令 上 加 令 ， 律 上 加 律 ， 例 上 加 例 ， 这 里 一 点 ， 那 里 一 点 ， 以 致 他 们 前 行 仰 面 跌 倒 ， 而 且 跌 碎 ， 并 陷 入 网 罗 被 缠 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18179', '23', '28', '14', '＜ 锡 安 的 房 角 石 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18180', '23', '28', '15', '你 们 曾 说 ： 我 们 与 死 亡 立 约 ， 与 阴 间 结 盟 ； 敌 军 ｛ 原 文 是 鞭 子 ｝ 如 水 涨 漫 经 过 的 时 候 ， 必 不 临 到 我 们 ； 因 我 们 以 谎 言 为 避 所 ， 在 虚 假 以 下 藏 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18181', '23', '28', '16', '所 以 ， 主 耶 和 华 如 此 说 ： 看 哪 ， 我 在 锡 安 放 一 块 石 头 作 为 根 基 ， 是 试 验 过 的 石 头 ， 是 稳 固 根 基 ， 宝 贵 的 房 角 石 ； 信 靠 的 人 必 不 着 急 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18182', '23', '28', '17', '我 必 以 公 平 为 准 绳 ， 以 公 义 为 线 铊 。 冰 雹 必 冲 去 谎 言 的 避 所 ； 大 水 必 漫 过 藏 身 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18183', '23', '28', '18', '你 们 与 死 亡 所 立 的 约 必 然 废 掉 ， 与 阴 间 所 结 的 盟 必 立 不 住 。 敌 军 ｛ 原 文 是 鞭 子 ｝ 如 水 涨 漫 经 过 的 时 候 ， 你 们 必 被 他 践 踏 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18184', '23', '28', '19', '每 逢 经 过 必 将 你 们 掳 去 。 因 为 每 早 晨 他 必 经 过 ， 白 昼 黑 夜 都 必 如 此 。 明 白 传 言 的 必 受 惊 恐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18185', '23', '28', '20', '原 来 ， 床 榻 短 ， 使 人 不 能 舒 身 ； 被 窝 窄 ， 使 人 不 能 遮 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18186', '23', '28', '21', '耶 和 华 必 兴 起 ， 像 在 毗 拉 心 山 ； 他 必 发 怒 ， 像 在 基 遍 谷 ， 好 做 成 他 的 工 ， 就 是 非 常 的 工 ； 成 就 他 的 事 ， 就 是 奇 异 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18187', '23', '28', '22', '现 在 你 们 不 可 亵 慢 ， 恐 怕 捆 你 们 的 绑 索 更 结 实 了 ； 因 为 我 从 主 ─ ─ 万 军 之 耶 和 华 那 里 听 见 ， 已 经 决 定 在 全 地 上 施 行 灭 绝 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18188', '23', '28', '23', '＜ 神 的 智 慧 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18189', '23', '28', '24', '那 耕 地 为 要 撒 种 的 ， 岂 是 常 常 耕 地 呢 ？ 岂 是 常 常 开 垦 耙 地 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18190', '23', '28', '25', '他 拉 平 了 地 面 ， 岂 不 就 撒 种 小 茴 香 ， 播 种 大 茴 香 ， 按 行 列 种 小 麦 ， 在 定 处 种 大 麦 ， 在 田 边 种 粗 麦 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18191', '23', '28', '26', '因 为 他 的 神 教 导 他 务 农 相 宜 ， 并 且 指 教 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18192', '23', '28', '27', '原 来 打 小 茴 香 ， 不 用 尖 利 的 器 具 ， 轧 大 茴 香 ， 也 不 用 碌 碡 ｛ 原 文 是 车 轮 ； 下 同 ｝ ； 但 用 杖 打 小 茴 香 ， 用 棍 打 大 茴 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18193', '23', '28', '28', '做 饼 的 粮 食 是 用 磨 磨 碎 ， 因 它 不 必 常 打 ； 虽 用 碌 碡 和 马 打 散 ， 却 不 磨 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18194', '23', '28', '29', '这 也 是 出 于 万 军 之 耶 和 华 ─ ─ 他 的 谋 略 奇 妙 ； 他 的 智 慧 广 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18195', '23', '29', '1', '＜ 耶 路 撒 冷 的 命 运 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18196', '23', '29', '2', '我 终 必 使 亚 利 伊 勒 困 难 ； 她 必 悲 伤 哀 号 ， 我 却 仍 以 她 为 亚 利 伊 勒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18197', '23', '29', '3', '我 必 四 围 安 营 攻 击 你 ， 屯 兵 围 困 你 ， 筑 垒 攻 击 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18198', '23', '29', '4', '你 必 败 落 ， 从 地 中 说 话 ； 你 的 言 语 必 微 细 出 于 尘 埃 。 你 的 声 音 必 像 那 交 鬼 者 的 声 音 出 于 地 ； 你 的 言 语 低 低 微 微 出 于 尘 埃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18199', '23', '29', '5', '你 仇 敌 的 群 众 ， 却 要 像 细 尘 ； 强 暴 人 的 群 众 ， 也 要 像 飞 糠 。 这 事 必 顷 刻 之 间 忽 然 临 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18200', '23', '29', '6', '万 军 之 耶 和 华 必 用 雷 轰 、 地 震 、 大 声 、 旋 风 、 暴 风 ， 并 吞 灭 的 火 焰 ， 向 她 讨 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18201', '23', '29', '7', '那 时 ， 攻 击 亚 利 伊 勒 列 国 的 群 众 ， 就 是 一 切 攻 击 亚 利 伊 勒 和 她 的 保 障 ， 并 使 她 困 难 的 ， 必 如 梦 景 ， 如 夜 间 的 异 象 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18202', '23', '29', '8', '又 必 像 饥 饿 的 人 梦 中 吃 饭 ， 醒 了 仍 觉 腹 空 ； 或 像 口 渴 的 人 梦 中 喝 水 ， 醒 了 仍 觉 发 昏 ， 心 里 想 喝 。 攻 击 锡 安 山 列 国 的 群 众 也 必 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18203', '23', '29', '9', '＜ 没 有 人 听 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18204', '23', '29', '10', '因 为 耶 和 华 将 沉 睡 的 灵 浇 灌 你 们 ， 封 闭 你 们 的 眼 ， 蒙 盖 你 们 的 头 。 你 们 的 眼 就 是 先 知 ； 你 们 的 头 就 是 先 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18205', '23', '29', '11', '所 有 的 默 示 ， 你 们 看 如 封 住 的 书 卷 ， 人 将 这 书 卷 交 给 识 字 的 ， 说 ： “ 请 念 吧 ！ 他 说 ： “ 我 不 能 念 ， 因 为 是 封 住 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18206', '23', '29', '12', '又 将 这 书 卷 交 给 不 识 字 的 人 ， 说 ： “ 请 念 吧 ！ ” 他 说 ： “ 我 不 识 字 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18207', '23', '29', '13', '主 说 ： 因 为 这 百 姓 亲 近 我 ， 用 嘴 唇 尊 敬 我 ， 心 却 远 离 我 ； 他 们 敬 畏 我 ， 不 过 是 领 受 人 的 吩 咐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18208', '23', '29', '14', '所 以 ， 我 在 这 百 姓 中 要 行 奇 妙 的 事 ， 就 是 奇 妙 又 奇 妙 的 事 。 他 们 智 慧 人 的 智 慧 必 然 消 灭 ， 聪 明 人 的 聪 明 必 然 隐 藏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18209', '23', '29', '15', '＜ 将 来 的 希 望 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18210', '23', '29', '16', '你 们 把 事 颠 倒 了 ， 岂 可 看 窑 匠 如 泥 吗 ？ 被 制 作 的 物 岂 可 论 制 作 物 的 说 ： 他 没 有 制 作 我 ？ 或 是 被 创 造 的 物 论 造 物 的 说 ： 他 没 有 聪 明 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18211', '23', '29', '17', '黎 巴 嫩 变 为 肥 田 ， 肥 田 看 如 树 林 ， 不 是 只 有 一 点 点 时 候 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18212', '23', '29', '18', '那 时 ， 聋 子 必 听 见 这 书 上 的 话 ； 瞎 子 的 眼 必 从 迷 蒙 黑 暗 中 得 以 看 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18213', '23', '29', '19', '谦 卑 人 必 因 耶 和 华 增 添 欢 喜 ； 人 间 贫 穷 的 必 因 以 色 列 的 圣 者 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18214', '23', '29', '20', '因 为 ， 强 暴 人 已 归 无 有 ， 亵 慢 人 已 经 灭 绝 ， 一 切 找 机 会 作 孽 的 都 被 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18215', '23', '29', '21', '他 们 在 争 讼 的 事 上 定 无 罪 的 为 有 罪 ， 为 城 门 口 责 备 人 的 设 下 网 罗 ， 用 虚 无 的 事 屈 枉 义 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18216', '23', '29', '22', '所 以 ， 救 赎 亚 伯 拉 罕 的 耶 和 华 论 雅 各 家 如 此 说 ： 雅 各 必 不 再 羞 愧 ， 面 容 也 不 致 变 色 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18217', '23', '29', '23', '但 他 看 见 他 的 众 子 ， 就 是 我 手 的 工 作 在 他 那 里 ， 他 们 必 尊 我 的 名 为 圣 ， 必 尊 雅 各 的 圣 者 为 圣 ， 必 敬 畏 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18218', '23', '29', '24', '心 中 迷 糊 的 必 得 明 白 ； 发 怨 言 的 必 受 训 诲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18219', '23', '30', '1', '＜ 跟 埃 及 订 立 无 用 的 条 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18220', '23', '30', '2', '起 身 下 埃 及 去 ， 并 没 有 求 问 我 ； 要 靠 法 老 的 力 量 加 添 自 己 的 力 量 ， 并 投 在 埃 及 的 荫 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18221', '23', '30', '3', '所 以 ， 法 老 的 力 量 必 作 你 们 的 羞 辱 ； 投 在 埃 及 的 荫 下 ， 要 为 你 们 的 惭 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18222', '23', '30', '4', '他 们 的 首 领 已 在 琐 安 ； 他 们 的 使 臣 到 了 哈 内 斯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18223', '23', '30', '5', '他 们 必 因 那 不 利 于 他 们 的 民 蒙 羞 。 那 民 并 非 帮 助 ， 也 非 利 益 ， 只 作 羞 耻 凌 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18224', '23', '30', '6', '论 南 方 牲 畜 的 默 示 ： 他 们 把 财 物 驮 在 驴 驹 的 脊 背 上 ， 将 宝 物 驮 在 骆 驼 的 肉 鞍 上 ， 经 过 艰 难 困 苦 之 地 ， 就 是 公 狮 、 母 狮 、 蝮 蛇 、 火 焰 的 飞 龙 之 地 ， 往 那 不 利 于 他 们 的 民 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18225', '23', '30', '7', '埃 及 的 帮 助 是 徒 然 无 益 的 ； 所 以 我 称 她 为 “ 坐 而 不 动 的 拉 哈 伯 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18226', '23', '30', '8', '＜ 不 顺 服 的 人 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18227', '23', '30', '9', '因 为 他 们 是 悖 逆 的 百 姓 、 说 谎 的 儿 女 ， 不 肯 听 从 耶 和 华 训 诲 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18228', '23', '30', '10', '他 们 对 先 见 说 ： 不 要 望 见 不 吉 利 的 事 ， 对 先 知 说 ： 不 要 向 我 们 讲 正 直 的 话 ； 要 向 我 们 说 柔 和 的 话 ， 言 虚 幻 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18229', '23', '30', '11', '你 们 要 离 弃 正 道 ， 偏 离 直 路 ， 不 要 在 我 们 面 前 再 提 说 以 色 列 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18230', '23', '30', '12', '所 以 ， 以 色 列 的 圣 者 如 此 说 ： 因 为 你 们 藐 视 这 训 诲 的 话 ， 倚 赖 欺 压 和 乖 僻 ， 以 此 为 可 靠 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18231', '23', '30', '13', '故 此 ， 这 罪 孽 在 你 们 身 上 ， 好 像 将 要 破 裂 凸 出 来 的 高 墙 ， 顷 刻 之 间 忽 然 坍 塌 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18232', '23', '30', '14', '要 被 打 碎 ， 好 像 把 窑 匠 的 瓦 器 打 碎 ， 毫 不 顾 惜 ， 甚 至 碎 块 中 找 不 到 一 片 可 用 以 从 炉 内 取 火 ， 从 池 中 舀 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18233', '23', '30', '15', '主 耶 和 华 ─ ─ 以 色 列 的 圣 者 曾 如 此 说 ： 你 们 得 救 在 乎 归 回 安 息 ； 你 们 得 力 在 乎 平 静 安 稳 ； 你 们 竟 自 不 肯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18234', '23', '30', '16', '你 们 却 说 ： 不 然 ， 我 们 要 骑 马 奔 走 。 所 以 你 们 必 然 奔 走 ； 又 说 ： 我 们 要 骑 飞 快 的 牲 口 。 所 以 追 赶 你 们 的 ， 也 必 飞 快 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18235', '23', '30', '17', '一 人 叱 喝 ， 必 令 千 人 逃 跑 ； 五 人 叱 喝 ， 你 们 都 必 逃 跑 ； 以 致 剩 下 的 ， 好 像 山 顶 的 旗 杆 ， 冈 上 的 大 旗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18236', '23', '30', '18', '耶 和 华 必 然 等 候 ， 要 施 恩 给 你 们 ； 必 然 兴 起 ， 好 怜 悯 你 们 。 因 为 耶 和 华 是 公 平 的 神 ； 凡 等 候 他 的 都 是 有 福 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18237', '23', '30', '19', '＜ 神 要 赐 福 给 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18238', '23', '30', '20', '主 虽 然 以 艰 难 给 你 当 饼 ， 以 困 苦 给 你 当 水 ， 你 的 教 师 却 不 再 隐 藏 ； 你 眼 必 看 见 你 的 教 师 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18239', '23', '30', '21', '你 或 向 左 或 向 右 ， 你 必 听 见 后 边 有 声 音 说 ： “ 这 是 正 路 ， 要 行 在 其 间 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18240', '23', '30', '22', '你 雕 刻 偶 像 所 包 的 银 子 和 铸 造 偶 像 所 镀 的 金 子 ， 你 要 玷 污 ， 要 抛 弃 ， 好 像 污 秽 之 物 ， 对 偶 像 说 ： “ 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18241', '23', '30', '23', '你 将 种 子 撒 在 地 里 ， 主 必 降 雨 在 其 上 ， 并 使 地 所 出 的 粮 肥 美 丰 盛 。 到 那 时 ， 你 的 牲 畜 必 在 宽 阔 的 草 场 吃 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18242', '23', '30', '24', '耕 地 的 牛 和 驴 驹 必 吃 加 盐 的 料 ； 这 料 是 用 木 杴 和 杈 子 扬 净 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18243', '23', '30', '25', '在 大 行 杀 戮 的 日 子 ， 高 台 倒 塌 的 时 候 ， 各 高 山 冈 陵 必 有 川 流 河 涌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18244', '23', '30', '26', '当 耶 和 华 缠 裹 他 百 姓 的 损 处 ， 医 治 他 民 鞭 伤 的 日 子 ， 月 光 必 像 日 光 ， 日 光 必 加 七 倍 ， 像 七 日 的 光 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18245', '23', '30', '27', '＜ 神 要 惩 罚 亚 述 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18246', '23', '30', '28', '他 的 气 如 涨 溢 的 河 水 ， 直 涨 到 颈 项 ， 要 用 毁 灭 的 筛 箩 筛 净 列 国 ， 并 且 在 众 民 的 口 中 必 有 使 人 错 行 的 嚼 环 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18247', '23', '30', '29', '你 们 必 唱 歌 ， 像 守 圣 节 的 夜 间 一 样 ， 并 且 心 中 喜 乐 ， 像 人 吹 笛 ， 上 耶 和 华 的 山 ， 到 以 色 列 的 磐 石 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18248', '23', '30', '30', '耶 和 华 必 使 人 听 他 威 严 的 声 音 ， 又 显 他 降 罚 的 膀 臂 和 他 怒 中 的 忿 恨 ， 并 吞 灭 的 火 焰 与 霹 雷 、 暴 风 、 冰 雹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18249', '23', '30', '31', '亚 述 人 必 因 耶 和 华 的 声 音 惊 惶 ； 耶 和 华 必 用 杖 击 打 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18250', '23', '30', '32', '耶 和 华 必 将 命 定 的 杖 加 在 他 身 上 ； 每 打 一 下 ， 人 必 击 鼓 弹 琴 。 打 仗 的 时 候 ， 耶 和 华 必 抡 起 手 来 ， 与 他 交 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18251', '23', '30', '33', '原 来 陀 斐 特 又 深 又 宽 ， 早 已 为 王 预 备 好 了 ； 其 中 堆 的 是 火 与 许 多 木 柴 。 耶 和 华 的 气 如 一 股 硫 磺 火 使 他 着 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18252', '23', '31', '1', '＜ 神 要 保 护 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18253', '23', '31', '2', '其 实 ， 耶 和 华 有 智 慧 ； 他 必 降 灾 祸 ， 并 不 反 悔 自 己 的 话 ， 却 要 兴 起 攻 击 那 作 恶 之 家 ， 又 攻 击 那 作 孽 帮 助 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18254', '23', '31', '3', '埃 及 人 不 过 是 人 ， 并 不 是 神 ； 他 们 的 马 不 过 是 血 肉 ， 并 不 是 灵 。 耶 和 华 一 伸 手 ， 那 帮 助 人 的 必 绊 跌 ， 那 受 帮 助 的 也 必 跌 倒 ， 都 一 同 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18255', '23', '31', '4', '耶 和 华 对 我 如 此 说 ： 狮 子 和 少 壮 狮 子 护 食 咆 哮 ， 就 是 喊 许 多 牧 人 来 攻 击 它 ， 它 总 不 因 他 们 的 声 音 惊 惶 ， 也 不 因 他 们 的 喧 哗 缩 伏 。 如 此 ， 万 军 之 耶 和 华 也 必 降 临 在 锡 安 山 冈 上 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18256', '23', '31', '5', '雀 鸟 怎 样 扇 翅 覆 雏 ， 万 军 之 耶 和 华 也 要 照 样 保 护 耶 路 撒 冷 。 他 必 保 护 拯 救 ， 要 越 门 保 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18257', '23', '31', '6', '以 色 列 人 哪 ， 你 们 深 深 地 悖 逆 耶 和 华 ， 现 今 要 归 向 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18258', '23', '31', '7', '到 那 日 ， 各 人 必 将 他 金 偶 像 银 偶 像 ， 就 是 亲 手 所 造 、 陷 自 己 在 罪 中 的 ， 都 抛 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18259', '23', '31', '8', '亚 述 人 必 倒 在 刀 下 ， 并 非 人 的 刀 ； 有 刀 要 将 他 吞 灭 ， 并 非 人 的 刀 。 他 必 逃 避 这 刀 ； 他 的 少 年 人 必 成 为 服 苦 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18260', '23', '31', '9', '他 的 磐 石 必 因 惊 吓 挪 去 ； 他 的 首 领 必 因 大 旗 惊 惶 。 这 是 那 有 火 在 锡 安 、 有 炉 在 耶 路 撒 冷 的 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18261', '23', '32', '1', '＜ 公 正 的 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18262', '23', '32', '2', '必 有 一 人 像 避 风 所 和 避 暴 雨 的 隐 密 处 ， 又 像 河 流 在 干 旱 之 地 ， 像 大 磐 石 的 影 子 在 疲 乏 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18263', '23', '32', '3', '那 能 看 的 人 ， 眼 不 再 昏 迷 ； 能 听 的 人 ， 耳 必 得 听 闻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18264', '23', '32', '4', '冒 失 人 的 心 必 明 白 知 识 ； 结 吧 人 的 舌 必 说 话 通 快 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18265', '23', '32', '5', '愚 顽 人 不 再 称 为 高 明 ； 吝 啬 人 不 再 称 为 大 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18266', '23', '32', '6', '因 为 愚 顽 人 必 说 愚 顽 话 ， 心 里 想 作 罪 孽 ， 惯 行 亵 渎 的 事 ， 说 错 谬 的 话 攻 击 耶 和 华 ， 使 饥 饿 的 人 无 食 可 吃 ， 使 口 渴 的 人 无 水 可 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18267', '23', '32', '7', '吝 啬 人 所 用 的 法 子 是 恶 的 ； 他 图 谋 恶 计 ， 用 谎 言 毁 灭 谦 卑 人 ； 穷 乏 人 讲 公 理 的 时 候 ， 他 也 是 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18268', '23', '32', '8', '高 明 人 却 谋 高 明 事 ， 在 高 明 事 上 也 必 永 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18269', '23', '32', '9', '＜ 审 判 和 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18270', '23', '32', '10', '无 虑 的 女 子 啊 ， 再 过 一 年 多 ， 必 受 骚 扰 ； 因 为 无 葡 萄 可 摘 ， 无 果 子 ｛ 或 译 ： 禾 稼 ｝ 可 收 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18271', '23', '32', '11', '安 逸 的 妇 女 啊 ， 要 战 兢 ； 无 虑 的 女 子 啊 ， 要 受 骚 扰 。 脱 去 衣 服 ， 赤 着 身 体 ， 腰 束 麻 布 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18272', '23', '32', '12', '她 们 必 为 美 好 的 田 地 和 多 结 果 的 葡 萄 树 ， 捶 胸 哀 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18273', '23', '32', '13', '荆 棘 蒺 藜 必 长 在 我 百 姓 的 地 上 ， 又 长 在 欢 乐 的 城 中 和 一 切 快 乐 的 房 屋 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18274', '23', '32', '14', '因 为 宫 殿 必 被 撇 下 ， 多 民 的 城 必 被 离 弃 ； 山 冈 望 楼 永 为 洞 穴 ， 作 野 驴 所 喜 乐 的 ， 为 羊 群 的 草 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18275', '23', '32', '15', '等 到 圣 灵 从 上 浇 灌 我 们 ， 旷 野 就 变 为 肥 田 ， 肥 田 看 如 树 林 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18276', '23', '32', '16', '那 时 ， 公 平 要 居 在 旷 野 ； 公 义 要 居 在 肥 田 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18277', '23', '32', '17', '公 义 的 果 效 必 是 平 安 ； 公 义 的 效 验 必 是 平 稳 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18278', '23', '32', '18', '我 的 百 姓 必 住 在 平 安 的 居 所 ， 安 稳 的 住 处 ， 平 静 的 安 歇 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18279', '23', '32', '19', '（ 但 要 降 冰 雹 打 倒 树 林 ； 城 必 全 然 拆 平 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18280', '23', '32', '20', '你 们 在 各 水 边 撒 种 、 牧 放 牛 驴 的 有 福 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18281', '23', '33', '1', '＜ 求 救 的 祈 祷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18282', '23', '33', '2', '耶 和 华 啊 ， 求 你 施 恩 于 我 们 ； 我 们 等 候 你 。 求 你 每 早 晨 作 我 们 的 膀 臂 ， 遭 难 的 时 候 为 我 们 的 拯 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18283', '23', '33', '3', '喧 嚷 的 响 声 一 发 ， 众 民 奔 逃 ； 你 一 兴 起 ， 列 国 四 散 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18284', '23', '33', '4', '你 们 所 掳 的 必 被 敛 尽 ， 好 像 蚂 蚱 吃 ｛ 原 文 是 敛 ｝ 尽 禾 稼 。 人 要 蹦 在 其 上 ， 好 像 蝗 虫 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18285', '23', '33', '5', '耶 和 华 被 尊 崇 ， 因 他 居 在 高 处 ； 他 以 公 平 公 义 充 满 锡 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18286', '23', '33', '6', '你 一 生 一 世 必 得 安 稳 ─ ─ 有 丰 盛 的 救 恩 ， 并 智 慧 和 知 识 ； 你 以 敬 畏 耶 和 华 为 至 宝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18287', '23', '33', '7', '看 哪 ， 他 们 的 豪 杰 在 外 头 哀 号 ； 求 和 的 使 臣 痛 痛 哭 泣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18288', '23', '33', '8', '大 路 荒 凉 ， 行 人 止 息 ； 敌 人 背 约 ， 藐 视 城 邑 ， 不 顾 人 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18289', '23', '33', '9', '地 上 悲 哀 衰 残 ； 黎 巴 嫩 羞 愧 枯 干 ； 沙 仑 像 旷 野 ； 巴 珊 和 迦 密 的 树 林 凋 残 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18290', '23', '33', '10', '＜ 耶 和 华 对 敌 人 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18291', '23', '33', '11', '你 们 要 怀 的 是 糠 秕 ， 要 生 的 是 碎 秸 ； 你 们 的 气 就 是 吞 灭 自 己 的 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18292', '23', '33', '12', '列 邦 必 像 已 烧 的 石 灰 ， 像 已 割 的 荆 棘 在 火 中 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18293', '23', '33', '13', '你 们 远 方 的 人 当 听 我 所 行 的 ； 你 们 近 处 的 人 当 承 认 我 的 大 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18294', '23', '33', '14', '锡 安 中 的 罪 人 都 惧 怕 ； 不 敬 虔 的 人 被 战 兢 抓 住 。 我 们 中 间 谁 能 与 吞 灭 的 火 同 住 ？ 我 们 中 间 谁 能 与 永 火 同 住 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18295', '23', '33', '15', '行 事 公 义 、 说 话 正 直 、 憎 恶 欺 压 的 财 利 、 摆 手 不 受 贿 赂 、 塞 耳 不 听 流 血 的 话 ， 闭 眼 不 看 邪 恶 事 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18296', '23', '33', '16', '他 必 居 高 处 ； 他 的 保 障 是 磐 石 的 坚 垒 ； 他 的 粮 必 不 缺 乏 ｛ 原 文 是 赐 给 ｝ ； 他 的 水 必 不 断 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18297', '23', '33', '17', '＜ 光 荣 的 将 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18298', '23', '33', '18', '你 的 心 必 思 想 那 惊 吓 的 事 ， 自 问 说 ： 记 数 目 的 在 哪 里 呢 ？ 平 贡 银 的 在 哪 里 呢 ？ 数 戍 楼 的 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18299', '23', '33', '19', '你 必 不 见 那 强 暴 的 民 ， 就 是 说 话 深 奥 ， 你 不 能 明 白 ， 言 语 呢 喃 ， 你 不 能 懂 得 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18300', '23', '33', '20', '你 要 看 锡 安 ─ ─ 我 们 守 圣 节 的 城 ！ 你 的 眼 必 见 耶 路 撒 冷 为 安 静 的 居 所 ， 为 不 挪 移 的 帐 幕 ， 橛 子 永 不 拔 出 ， 绳 索 一 根 也 不 折 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18301', '23', '33', '21', '在 那 里 ， 耶 和 华 必 显 威 严 与 我 们 同 在 ， 当 作 江 河 宽 阔 之 地 ； 其 中 必 没 有 荡 桨 摇 橹 的 船 来 往 ， 也 没 有 威 武 的 船 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18302', '23', '33', '22', '因 为 ， 耶 和 华 是 审 判 我 们 的 ； 耶 和 华 是 给 我 们 设 律 法 的 ； 耶 和 华 是 我 们 的 王 ； 他 必 拯 救 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18303', '23', '33', '23', '你 的 绳 索 松 开 ： 不 能 栽 稳 桅 杆 ， 也 不 能 扬 起 篷 来 。 那 时 许 多 掳 来 的 物 被 分 了 ； 瘸 腿 的 把 掠 物 夺 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18304', '23', '33', '24', '城 内 居 民 必 不 说 ： 我 病 了 ； 其 中 居 住 的 百 姓 ， 罪 孽 都 赦 免 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18305', '23', '34', '1', '＜ 神 要 惩 罚 仇 敌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18306', '23', '34', '2', '因 为 耶 和 华 向 万 国 发 忿 恨 ， 向 他 们 的 全 军 发 烈 怒 ， 将 他 们 灭 尽 ， 交 出 他 们 受 杀 戮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18307', '23', '34', '3', '被 杀 的 必 然 抛 弃 ， 尸 首 臭 气 上 腾 ； 诸 山 被 他 们 的 血 融 化 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18308', '23', '34', '4', '天 上 的 万 象 都 要 消 没 ； 天 被 卷 起 ， 好 像 书 卷 。 其 上 的 万 象 要 残 败 ， 像 葡 萄 树 的 叶 子 残 败 ， 又 像 无 花 果 树 的 叶 子 残 败 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18309', '23', '34', '5', '因 为 我 的 刀 在 天 上 已 经 喝 足 ； 这 刀 必 临 到 以 东 和 我 所 咒 诅 的 民 ， 要 施 行 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18310', '23', '34', '6', '耶 和 华 的 刀 满 了 血 ， 用 脂 油 和 羊 羔 、 公 山 羊 的 血 ， 并 公 绵 羊 腰 子 的 脂 油 滋 润 的 ； 因 为 耶 和 华 在 波 斯 拉 有 献 祭 的 事 ， 在 以 东 地 大 行 杀 戮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18311', '23', '34', '7', '野 牛 、 牛 犊 ， 和 公 牛 要 一 同 下 来 。 他 们 的 地 喝 醉 了 血 ； 他 们 的 尘 土 因 脂 油 肥 润 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18312', '23', '34', '8', '因 耶 和 华 有 报 仇 之 日 ， 为 锡 安 的 争 辩 有 报 应 之 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18313', '23', '34', '9', '以 东 的 河 水 要 变 为 石 油 ， 尘 埃 要 变 为 硫 磺 ； 地 土 成 为 烧 着 的 石 油 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18314', '23', '34', '10', '昼 夜 总 不 熄 灭 ， 烟 气 永 远 上 腾 ， 必 世 世 代 代 成 为 荒 废 ， 永 永 远 远 无 人 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18315', '23', '34', '11', '鹈 鹕 、 箭 猪 却 要 得 为 业 ； 猫 头 鹰 、 乌 鸦 要 住 在 其 间 。 耶 和 华 必 将 空 虚 的 准 绳 ， 混 沌 的 线 铊 ， 拉 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18316', '23', '34', '12', '以 东 人 要 召 贵 胄 来 治 国 ； 那 里 却 无 一 个 ， 首 领 也 都 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18317', '23', '34', '13', '以 东 的 宫 殿 要 长 荆 棘 ； 保 障 要 长 蒺 藜 和 刺 草 ； 要 作 野 狗 的 住 处 ， 鸵 鸟 的 居 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18318', '23', '34', '14', '旷 野 的 走 兽 要 和 豺 狼 相 遇 ； 野 山 羊 要 与 伴 偶 对 叫 。 夜 间 的 怪 物 必 在 那 里 栖 身 ， 自 找 安 歇 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18319', '23', '34', '15', '箭 蛇 要 在 那 里 做 窝 ， 下 蛋 ， 菢 蛋 ， 生 子 ， 聚 子 在 其 影 下 ； 鹞 鹰 各 与 伴 偶 聚 集 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18320', '23', '34', '16', '你 们 要 查 考 宣 读 耶 和 华 的 书 。 这 都 无 一 缺 少 ， 无 一 没 有 伴 偶 ； 因 为 我 的 口 已 经 吩 咐 ， 他 的 灵 将 它 们 聚 集 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18321', '23', '34', '17', '他 也 为 它 们 拈 阄 ， 又 亲 手 用 准 绳 给 它 们 分 地 ； 它 们 必 永 得 为 业 ， 世 世 代 代 住 在 其 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18322', '23', '35', '1', '＜ 神 圣 之 路 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18323', '23', '35', '2', '必 开 花 繁 盛 ， 乐 上 加 乐 ， 而 且 欢 呼 。 黎 巴 嫩 的 荣 耀 ， 并 迦 密 与 沙 仑 的 华 美 ， 必 赐 给 它 。 人 必 看 见 耶 和 华 的 荣 耀 ， 我 们 神 的 华 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18324', '23', '35', '3', '你 们 要 使 软 弱 的 手 坚 壮 ， 无 力 的 膝 稳 固 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18325', '23', '35', '4', '对 胆 怯 的 人 说 ： 你 们 要 刚 强 ， 不 要 惧 怕 。 看 哪 ， 你 们 的 神 必 来 报 仇 ， 必 来 施 行 极 大 的 报 应 ； 他 必 来 拯 救 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18326', '23', '35', '5', '那 时 ， 瞎 子 的 眼 必 睁 开 ； 聋 子 的 耳 必 开 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18327', '23', '35', '6', '那 时 ， 瘸 子 必 跳 跃 像 鹿 ； 哑 巴 的 舌 头 必 能 歌 唱 。 在 旷 野 必 有 水 发 出 ； 在 沙 漠 必 有 河 涌 流 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18328', '23', '35', '7', '发 光 的 沙 ｛ 或 译 ： 蜃 楼 ｝ 要 变 为 水 池 ； 干 渴 之 地 要 变 为 泉 源 。 在 野 狗 躺 卧 之 处 ， 必 有 青 草 、 芦 苇 ， 和 蒲 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18329', '23', '35', '8', '在 那 里 必 有 一 条 大 道 ， 称 为 圣 路 。 污 秽 人 不 得 经 过 ， 必 专 为 赎 民 行 走 ； 行 路 的 人 虽 愚 昧 ， 也 不 致 失 迷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18330', '23', '35', '9', '在 那 里 必 没 有 狮 子 ， 猛 兽 也 不 登 这 路 ； 在 那 里 都 遇 不 见 ， 只 有 赎 民 在 那 里 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18331', '23', '35', '10', '并 且 耶 和 华 救 赎 的 民 必 归 回 ， 歌 唱 来 到 锡 安 ； 永 乐 必 归 到 他 们 的 头 上 ； 他 们 必 得 着 欢 喜 快 乐 ， 忧 愁 叹 息 尽 都 逃 避 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18332', '23', '36', '1', '＜ 亚 述 人 威 胁 耶 路 撒 冷 （ 王 下   1 8 : 1 3 - 3 7 ； 代 下   3 2 : 1 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18333', '23', '36', '2', '亚 述 王 从 拉 吉 差 遣 拉 伯 沙 基 率 领 大 军 往 耶 路 撒 冷 ， 到 希 西 家 王 那 里 去 。 他 就 站 在 上 池 的 水 沟 旁 ， 在 漂 布 地 的 大 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18334', '23', '36', '3', '于 是 希 勒 家 的 儿 子 家 宰 以 利 亚 敬 ， 并 书 记 舍 伯 那 和 亚 萨 的 儿 子 史 官 约 亚 ， 出 来 见 拉 伯 沙 基 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18335', '23', '36', '4', '拉 伯 沙 基 对 他 们 说 ： “ 你 们 去 告 诉 希 西 家 说 ， 亚 述 大 王 如 此 说 ： ‘ 你 所 倚 靠 的 有 什 么 可 仗 赖 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18336', '23', '36', '5', '你 说 ， 有 打 仗 的 计 谋 和 能 力 ， 我 看 不 过 是 虚 话 。 你 到 底 倚 靠 谁 才 背 叛 我 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18337', '23', '36', '6', '看 哪 ， 你 所 倚 靠 的 埃 及 是 那 压 伤 的 苇 杖 ， 人 若 靠 这 杖 ， 就 必 刺 透 他 的 手 。 埃 及 王 法 老 向 一 切 倚 靠 他 的 人 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18338', '23', '36', '7', '你 若 对 我 说 ： 我 们 倚 靠 耶 和 华 ─ ─ 我 们 的 神 。 希 西 家 岂 不 是 将 神 的 邱 坛 和 祭 坛 废 去 ， 且 对 犹 大 和 耶 路 撒 冷 的 人 说 ： 你 们 当 在 这 坛 前 敬 拜 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18339', '23', '36', '8', '现 在 你 把 当 头 给 我 主 亚 述 王 ， 我 给 你 二 千 匹 马 ， 看 你 这 一 面 骑 马 的 人 够 不 够 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18340', '23', '36', '9', '若 不 然 ， 怎 能 打 败 我 主 臣 仆 中 最 小 的 军 长 呢 ？ 你 竟 倚 靠 埃 及 的 战 车 马 兵 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18341', '23', '36', '10', '现 在 我 上 来 攻 击 毁 灭 这 地 ， 岂 没 有 耶 和 华 的 意 思 吗 ？ 耶 和 华 吩 咐 我 说 ， 你 上 去 攻 击 毁 灭 这 地 吧 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18342', '23', '36', '11', '以 利 亚 敬 、 舍 伯 那 、 约 亚 对 拉 伯 沙 基 说 ： “ 求 你 用 亚 兰 言 语 和 仆 人 说 话 ， 因 为 我 们 懂 得 ； 不 要 用 犹 大 言 语 和 我 们 说 话 ， 达 到 城 上 百 姓 的 耳 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18343', '23', '36', '12', '拉 伯 沙 基 说 ： “ 我 主 差 遣 我 来 ， 岂 是 单 对 你 和 你 的 主 说 这 些 话 吗 ？ 不 也 是 对 这 些 坐 在 城 上 、 要 与 你 们 一 同 吃 自 己 粪 喝 自 己 尿 的 人 说 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18344', '23', '36', '13', '于 是 ， 拉 伯 沙 基 站 着 ， 用 犹 大 言 语 大 声 喊 着 说 ： “ 你 们 当 听 亚 述 大 王 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18345', '23', '36', '14', '王 如 此 说 ： ‘ 你 们 不 要 被 希 西 家 欺 哄 了 ， 因 他 不 能 拯 救 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18346', '23', '36', '15', '也 不 要 听 希 西 家 使 你 们 倚 靠 耶 和 华 说 ： 耶 和 华 必 要 拯 救 我 们 ， 这 城 必 不 交 在 亚 述 王 的 手 中 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18347', '23', '36', '16', '不 要 听 希 西 家 的 话 ， 因 亚 述 王 如 此 说 ： ‘ 你 们 要 与 我 和 好 。 出 来 投 降 我 ， 各 人 就 可 以 吃 自 己 葡 萄 树 和 无 花 果 树 的 果 子 ， 喝 自 己 井 里 的 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18348', '23', '36', '17', '等 我 来 领 你 们 到 一 个 地 方 ， 与 你 们 本 地 一 样 ， 就 是 有 五 榖 和 新 酒 之 地 ， 有 粮 食 和 葡 萄 园 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18349', '23', '36', '18', '你 们 要 谨 防 ， 恐 怕 希 西 家 劝 导 你 们 说 ： 耶 和 华 必 拯 救 我 们 。 列 国 的 神 有 哪 一 个 救 他 本 国 脱 离 亚 述 王 的 手 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18350', '23', '36', '19', '哈 马 和 亚 珥 拔 的 神 在 哪 里 呢 ？ 西 法 瓦 音 的 神 在 哪 里 呢 ？ 他 们 曾 救 撒 马 利 亚 脱 离 我 的 手 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18351', '23', '36', '20', '这 些 国 的 神 有 谁 曾 救 自 己 的 国 脱 离 我 的 手 呢 ？ 难 道 耶 和 华 能 救 耶 路 撒 冷 脱 离 我 的 手 吗 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18352', '23', '36', '21', '百 姓 静 默 不 言 ， 并 不 回 答 一 句 ， 因 为 王 曾 吩 咐 说 ： “ 不 要 回 答 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18353', '23', '36', '22', '当 下 希 勒 家 的 儿 子 家 宰 以 利 亚 敬 和 书 记 舍 伯 那 ， 并 亚 萨 的 儿 子 史 官 约 亚 ， 都 撕 裂 衣 服 ， 来 到 希 西 家 那 里 ， 将 拉 伯 沙 基 的 话 告 诉 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18354', '23', '37', '1', '＜ 国 王 下 令 征 求 以 赛 亚 的 意 见 （ 王 下   1 9 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18355', '23', '37', '2', '使 家 宰 以 利 亚 敬 和 书 记 舍 伯 那 ， 并 祭 司 中 的 长 老 ， 都 披 上 麻 布 ， 去 见 亚 摩 斯 的 儿 子 先 知 以 赛 亚 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18356', '23', '37', '3', '对 他 说 ： “ 希 西 家 如 此 说 ： ‘ 今 日 是 急 难 、 责 罚 、 凌 辱 的 日 子 ， 就 如 妇 人 将 要 生 产 婴 孩 ， 却 没 有 力 量 生 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18357', '23', '37', '4', '或 者 耶 和 华 ─ ─ 你 的 神 听 见 拉 伯 沙 基 的 话 ， 就 是 他 主 人 亚 述 王 打 发 他 来 辱 骂 永 生 神 的 话 ； 耶 和 华 ─ ─ 你 的 神 听 见 这 话 就 发 斥 责 。 故 此 ， 求 你 为 余 剩 的 民 扬 声 祷 告 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18358', '23', '37', '5', '希 西 家 王 的 臣 仆 就 去 见 以 赛 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18359', '23', '37', '6', '以 赛 亚 对 他 们 说 ： “ 要 这 样 对 你 们 的 主 人 说 ， 耶 和 华 如 此 说 ： ‘ 你 听 见 亚 述 王 的 仆 人 亵 渎 我 的 话 ， 不 要 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18360', '23', '37', '7', '我 必 惊 动 ｛ 原 文 是 使 灵 进 入 ｝ 他 的 心 ； 他 要 听 见 风 声 就 归 回 本 地 ， 我 必 使 他 在 那 里 倒 在 刀 下 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18361', '23', '37', '8', '＜ 亚 述 人 再 来 威 胁 （ 王 下   1 9 : 8 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18362', '23', '37', '9', '亚 述 王 听 见 人 论 古 实 王 特 哈 加 说 ： “ 他 出 来 要 与 你 争 战 。 ” 亚 述 王 一 听 见 ， 就 打 发 使 者 去 见 希 西 家 ， 吩 咐 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18363', '23', '37', '10', '“ 你 们 对 犹 大 王 希 西 家 如 此 说 ： ‘ 不 要 听 你 所 倚 靠 的 神 欺 哄 你 说 ： 耶 路 撒 冷 必 不 交 在 亚 述 王 的 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18364', '23', '37', '11', '你 总 听 说 亚 述 诸 王 向 列 国 所 行 的 乃 是 尽 行 灭 绝 ， 难 道 你 还 能 得 救 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18365', '23', '37', '12', '我 列 祖 所 毁 灭 的 ， 就 是 歌 散 、 哈 兰 、 利 色 ， 和 属 提 ． 拉 撒 的 伊 甸 人 ； 这 些 国 的 神 何 曾 拯 救 这 些 国 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18366', '23', '37', '13', '哈 马 的 王 ， 亚 珥 拔 的 王 ， 西 法 瓦 音 城 的 王 ， 希 拿 和 以 瓦 的 王 ， 都 在 哪 里 呢 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18367', '23', '37', '14', '希 西 家 从 使 者 手 里 接 过 书 信 来 ， 看 完 了 ， 就 上 耶 和 华 的 殿 ， 将 书 信 在 耶 和 华 面 前 展 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18368', '23', '37', '15', '希 西 家 向 耶 和 华 祷 告 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18369', '23', '37', '16', '“ 坐 在 二 基 路 伯 上 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 啊 ， 你 ─ ─ 惟 有 你 是 天 下 万 国 的 神 ， 你 曾 创 造 天 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18370', '23', '37', '17', '耶 和 华 啊 ， 求 你 侧 耳 而 听 ； 耶 和 华 啊 ， 求 你 睁 眼 而 看 ， 要 听 西 拿 基 立 的 一 切 话 ， 他 是 打 发 使 者 来 辱 骂 永 生 神 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18371', '23', '37', '18', '耶 和 华 啊 ， 亚 述 诸 王 果 然 使 列 国 和 列 国 之 地 变 为 荒 凉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18372', '23', '37', '19', '将 列 国 的 神 像 都 扔 在 火 里 ； 因 为 他 本 不 是 神 ， 乃 是 人 手 所 造 的 ， 是 木 头 、 石 头 的 ， 所 以 灭 绝 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18373', '23', '37', '20', '耶 和 华 ─ ─ 我 们 的 神 啊 ， 现 在 求 你 救 我 们 脱 离 亚 述 王 的 手 ， 使 天 下 万 国 都 知 道 惟 有 你 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18374', '23', '37', '21', '＜ 以 赛 亚 给 王 的 信 息 （ 王 下   1 9 : 2 0 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18375', '23', '37', '22', '所 以 耶 和 华 论 他 这 样 说 ： 锡 安 的 处 女 藐 视 你 ， 嗤 笑 你 ； 耶 路 撒 冷 的 女 子 向 你 摇 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18376', '23', '37', '23', '你 辱 骂 谁 ， 亵 渎 谁 ？ 扬 起 声 来 ， 高 举 眼 目 攻 击 谁 呢 ？ 乃 是 攻 击 以 色 列 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18377', '23', '37', '24', '你 藉 你 的 臣 仆 辱 骂 主 说 ： 我 率 领 许 多 战 车 上 山 顶 ， 到 黎 巴 嫩 极 深 之 处 ； 我 要 砍 伐 其 中 高 大 的 香 柏 树 和 佳 美 的 松 树 。 我 必 上 极 高 之 处 ， 进 入 肥 田 的 树 林 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18378', '23', '37', '25', '我 已 经 挖 井 喝 水 ； 我 必 用 脚 掌 踏 干 埃 及 的 一 切 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18379', '23', '37', '26', '耶 和 华 说 ： 你 岂 没 有 听 见 我 早 先 所 做 的 、 古 时 所 立 的 吗 ？ 现 在 藉 你 使 坚 固 城 荒 废 ， 变 为 乱 堆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18380', '23', '37', '27', '所 以 其 中 的 居 民 力 量 甚 小 ， 惊 惶 羞 愧 。 他 们 像 野 草 ， 像 青 菜 ， 如 房 顶 上 的 草 ， 又 如 田 间 未 长 成 的 禾 稼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18381', '23', '37', '28', '你 坐 下 ， 你 出 去 ， 你 进 来 ， 你 向 我 发 烈 怒 ， 我 都 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18382', '23', '37', '29', '因 你 向 我 发 烈 怒 ， 又 因 你 狂 傲 的 话 达 到 我 耳 中 ， 我 就 要 用 钩 子 钩 上 你 的 鼻 子 ， 把 嚼 环 放 在 你 口 里 ， 使 你 从 原 路 转 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18383', '23', '37', '30', '“ 以 色 列 人 哪 ， 我 赐 你 们 一 个 证 据 ： 你 们 今 年 要 吃 自 生 的 ， 明 年 也 要 吃 自 长 的 ， 至 于 后 年 ， 你 们 要 耕 种 收 割 ， 栽 植 葡 萄 园 ， 吃 其 中 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18384', '23', '37', '31', '犹 大 家 所 逃 脱 余 剩 的 ， 仍 要 往 下 扎 根 ， 向 上 结 果 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18385', '23', '37', '32', '必 有 余 剩 的 民 从 耶 路 撒 冷 而 出 ； 必 有 逃 脱 的 人 从 锡 安 山 而 来 。 万 军 之 耶 和 华 的 热 心 必 成 就 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18386', '23', '37', '33', '“ 所 以 耶 和 华 论 亚 述 王 如 此 说 ： 他 必 不 得 来 到 这 城 ， 也 不 在 这 里 射 箭 ， 不 得 拿 盾 牌 到 城 前 ， 也 不 筑 垒 攻 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18387', '23', '37', '34', '他 从 哪 条 路 来 ， 必 从 那 条 路 回 去 ， 必 不 得 来 到 这 城 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18388', '23', '37', '35', '因 我 为 自 己 的 缘 故 ， 又 为 我 仆 人 大 卫 的 缘 故 ， 必 保 护 拯 救 这 城 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18389', '23', '37', '36', '耶 和 华 的 使 者 出 去 ， 在 亚 述 营 中 杀 了 十 八 万 五 千 人 。 清 早 有 人 起 来 一 看 ， 都 是 死 尸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18390', '23', '37', '37', '亚 述 王 西 拿 基 立 就 拔 营 回 去 ， 住 在 尼 尼 微 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18391', '23', '37', '38', '一 日 在 他 的 神 ─ ─ 尼 斯 洛 庙 里 叩 拜 ， 他 儿 子 亚 得 米 勒 和 沙 利 色 用 刀 杀 了 他 ， 就 逃 到 亚 拉 腊 地 。 他 儿 子 以 撒 哈 顿 接 续 他 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18392', '23', '38', '1', '＜ 希 西 家 王 的 疾 病 和 痊 愈 （ 王 下   2 0 : 1 - 1 1 ； 代 下   3 2 : 2 4 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18393', '23', '38', '2', '希 西 家 就 转 脸 朝 墙 ， 祷 告 耶 和 华 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18394', '23', '38', '3', '“ 耶 和 华 啊 ， 求 你 记 念 我 在 你 面 前 怎 样 存 完 全 的 心 ， 按 诚 实 行 事 ， 又 做 你 眼 中 所 看 为 善 的 。 ” 希 西 家 就 痛 哭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18395', '23', '38', '4', '耶 和 华 的 话 临 到 以 赛 亚 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18396', '23', '38', '5', '“ 你 去 告 诉 希 西 家 说 ， 耶 和 华 ─ ─ 你 祖 大 卫 的 神 如 此 说 ： 我 听 见 了 你 的 祷 告 ， 看 见 了 你 的 眼 泪 。 我 必 加 增 你 十 五 年 的 寿 数 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18397', '23', '38', '6', '并 且 我 要 救 你 和 这 城 脱 离 亚 述 王 的 手 ， 也 要 保 护 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18398', '23', '38', '7', '“ 我 ─ ─ 耶 和 华 必 成 就 我 所 说 的 。 我 先 给 你 一 个 兆 头 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18399', '23', '38', '8', '就 是 叫 亚 哈 斯 的 日 晷 ， 向 前 进 的 日 影 往 后 退 十 度 。 ” 于 是 ， 前 进 的 日 影 果 然 在 日 晷 上 往 后 退 了 十 度 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18400', '23', '38', '9', '犹 大 王 希 西 家 患 病 已 经 痊 愈 ， 就 作 诗 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18401', '23', '38', '10', '我 说 ： 正 在 我 中 年 ｛ 或 译 ： 晌 午 ｝ 之 日 必 进 入 阴 间 的 门 ； 我 余 剩 的 年 岁 不 得 享 受 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18402', '23', '38', '11', '我 说 ： 我 必 不 得 见 耶 和 华 ， 就 是 在 活 人 之 地 不 见 耶 和 华 ； 我 与 世 上 的 居 民 不 再 见 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18403', '23', '38', '12', '我 的 住 处 被 迁 去 离 开 我 ， 好 像 牧 人 的 帐 棚 一 样 ； 我 将 性 命 卷 起 ， 像 织 布 的 卷 布 一 样 。 耶 和 华 必 将 我 从 机 头 剪 断 ， 从 早 到 晚 ， 他 要 使 我 完 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18404', '23', '38', '13', '我 使 自 己 安 静 直 到 天 亮 ； 他 像 狮 子 折 断 我 一 切 的 骨 头 ， 从 早 到 晚 ， 他 要 使 我 完 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18405', '23', '38', '14', '我 像 燕 子 呢 喃 ， 像 白 鹤 鸣 叫 ， 又 像 鸽 子 哀 鸣 ； 我 因 仰 观 ， 眼 睛 困 倦 。 耶 和 华 啊 ， 我 受 欺 压 ， 求 你 为 我 作 保 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18406', '23', '38', '15', '我 可 说 什 么 呢 ？ 他 应 许 我 的 ， 也 给 我 成 就 了 。 我 因 心 里 的 苦 楚 ， 在 一 生 的 年 日 必 悄 悄 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18407', '23', '38', '16', '主 啊 ， 人 得 存 活 乃 在 乎 此 。 我 灵 存 活 也 全 在 此 。 所 以 求 你 使 我 痊 愈 ， 仍 然 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18408', '23', '38', '17', '看 哪 ， 我 受 大 苦 ， 本 为 使 我 得 平 安 ； 你 因 爱 我 的 灵 魂 ｛ 或 译 ： 生 命 ｝ 便 救 我 脱 离 败 坏 的 坑 ， 因 为 你 将 我 一 切 的 罪 扔 在 你 的 背 后 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18409', '23', '38', '18', '原 来 ， 阴 间 不 能 称 谢 你 ， 死 亡 不 能 颂 扬 你 ； 下 坑 的 人 不 能 盼 望 你 的 诚 实 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18410', '23', '38', '19', '只 有 活 人 ， 活 人 必 称 谢 你 ， 像 我 今 日 称 谢 你 一 样 。 为 父 的 ， 必 使 儿 女 知 道 你 的 诚 实 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18411', '23', '38', '20', '耶 和 华 肯 救 我 ， 所 以 ， 我 们 要 一 生 一 世 在 耶 和 华 殿 中 用 丝 弦 的 乐 器 唱 我 的 诗 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18412', '23', '38', '21', '以 赛 亚 说 ： “ 当 取 一 块 无 花 果 饼 来 ， 贴 在 疮 上 ， 王 必 痊 愈 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18413', '23', '38', '22', '希 西 家 问 说 ： “ 我 能 上 耶 和 华 的 殿 ， 有 什 么 兆 头 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18414', '23', '39', '1', '＜ 巴 比 伦 王 的 使 节 （ 王 下   2 0 : 1 2 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18415', '23', '39', '2', '希 西 家 喜 欢 见 使 者 ， 就 把 自 己 宝 库 的 金 子 、 银 子 、 香 料 、 贵 重 的 膏 油 ， 和 他 武 库 的 一 切 军 器 ， 并 所 有 的 财 宝 都 给 他 们 看 ； 他 家 中 和 全 国 之 内 ， 希 西 家 没 有 一 样 不 给 他 们 看 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18416', '23', '39', '3', '于 是 先 知 以 赛 亚 来 见 希 西 家 王 ， 问 他 说 ： “ 这 些 人 说 什 么 ？ 他 们 从 哪 里 来 见 你 ？ ” 希 西 家 说 ： “ 他 们 从 远 方 的 巴 比 伦 来 见 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18417', '23', '39', '4', '以 赛 亚 说 ： “ 他 们 在 你 家 里 看 见 了 什 么 ？ ” 希 西 家 说 ： “ 凡 我 家 中 所 有 的 ， 他 们 都 看 见 了 ； 我 财 宝 中 没 有 一 样 不 给 他 们 看 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18418', '23', '39', '5', '以 赛 亚 对 希 西 家 说 ： “ 你 要 听 万 军 之 耶 和 华 的 话 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18419', '23', '39', '6', '日 子 必 到 ， 凡 你 家 里 所 有 的 ， 并 你 列 祖 积 蓄 到 如 今 的 ， 都 要 被 掳 到 巴 比 伦 去 ， 不 留 下 一 样 ； 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18420', '23', '39', '7', '并 且 从 你 本 身 所 生 的 众 子 ， 其 中 必 有 被 掳 去 、 在 巴 比 伦 王 宫 里 当 太 监 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18421', '23', '39', '8', '希 西 家 对 以 赛 亚 说 ： “ 你 所 说 耶 和 华 的 话 甚 好 ， 因 为 在 我 的 年 日 中 必 有 太 平 和 稳 固 的 景 况 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18422', '23', '40', '1', '＜ 希 望 的 话 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18423', '23', '40', '2', '要 对 耶 路 撒 冷 说 安 慰 的 话 ， 又 向 她 宣 告 说 ， 她 争 战 的 日 子 已 满 了 ； 她 的 罪 孽 赦 免 了 ； 她 为 自 己 的 一 切 罪 ， 从 耶 和 华 手 中 加 倍 受 罚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18424', '23', '40', '3', '有 人 声 喊 着 说 ： 在 旷 野 预 备 耶 和 华 的 路 ｛ 或 译 ： 在 旷 野 ， 有 人 声 喊 着 说 ： 当 预 备 耶 和 华 的 路 ｝ ， 在 沙 漠 地 修 平 我 们 神 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18425', '23', '40', '4', '一 切 山 洼 都 要 填 满 ， 大 小 山 冈 都 要 削 平 ； 高 高 低 低 的 要 改 为 平 坦 ， 崎 崎 岖 岖 的 必 成 为 平 原 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18426', '23', '40', '5', '耶 和 华 的 荣 耀 必 然 显 现 ； 凡 有 血 气 的 必 一 同 看 见 ； 因 为 这 是 耶 和 华 亲 口 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18427', '23', '40', '6', '有 人 声 说 ： 你 喊 叫 吧 ！ 有 一 个 说 ： 我 喊 叫 什 么 呢 ？ 说 ： 凡 有 血 气 的 尽 都 如 草 ； 他 的 美 容 都 像 野 地 的 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18428', '23', '40', '7', '草 必 枯 干 ， 花 必 凋 残 ， 因 为 耶 和 华 的 气 吹 在 其 上 ； 百 姓 诚 然 是 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18429', '23', '40', '8', '草 必 枯 干 ， 花 必 凋 残 ， 惟 有 我 们 神 的 话 必 永 远 立 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18430', '23', '40', '9', '报 好 信 息 给 锡 安 的 啊 ， 你 要 登 高 山 ； 报 好 信 息 给 耶 路 撒 冷 的 啊 ， 你 要 极 力 扬 声 。 扬 声 不 要 惧 怕 ， 对 犹 大 的 城 邑 说 ： 看 哪 ， 你 们 的 神 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18431', '23', '40', '10', '主 耶 和 华 必 像 大 能 者 临 到 ； 他 的 膀 臂 必 为 他 掌 权 。 他 的 赏 赐 在 他 那 里 ； 他 的 报 应 在 他 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18432', '23', '40', '11', '他 必 像 牧 人 牧 养 自 己 的 羊 群 ， 用 膀 臂 聚 集 羊 羔 抱 在 怀 中 ， 慢 慢 引 导 那 乳 养 小 羊 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18433', '23', '40', '12', '＜ 以 色 列 的 神 无 可 比 拟 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18434', '23', '40', '13', '谁 曾 测 度 耶 和 华 的 心 ｛ 或 译 ： 谁 曾 指 示 耶 和 华 的 灵 ｝ ， 或 作 他 的 谋 士 指 教 他 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18435', '23', '40', '14', '他 与 谁 商 议 ， 谁 教 导 他 ， 谁 将 公 平 的 路 指 示 他 ， 又 将 知 识 教 训 他 ， 将 通 达 的 道 指 教 他 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18436', '23', '40', '15', '看 哪 ， 万 民 都 像 水 桶 的 一 滴 ， 又 算 如 天 平 上 的 微 尘 ； 他 举 起 众 海 岛 ， 好 像 极 微 之 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18437', '23', '40', '16', '黎 巴 嫩 的 树 林 不 够 当 柴 烧 ； 其 中 的 走 兽 也 不 够 作 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18438', '23', '40', '17', '万 民 在 他 面 前 好 像 虚 无 ， 被 他 看 为 不 及 虚 无 ， 乃 为 虚 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18439', '23', '40', '18', '你 们 究 竟 将 谁 比 神 ， 用 什 么 形 像 与 神 比 较 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18440', '23', '40', '19', '偶 像 是 匠 人 铸 造 ， 银 匠 用 金 包 裹 ， 为 它 铸 造 银 链 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18441', '23', '40', '20', '穷 乏 献 不 起 这 样 供 物 的 ， 就 拣 选 不 能 朽 坏 的 树 木 ， 为 自 己 寻 找 巧 匠 ， 立 起 不 能 摇 动 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18442', '23', '40', '21', '你 们 岂 不 曾 知 道 吗 ？ 你 们 岂 不 曾 听 见 吗 ？ 从 起 初 岂 没 有 人 告 诉 你 们 吗 ？ 自 从 立 地 的 根 基 ， 你 们 岂 没 有 明 白 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18443', '23', '40', '22', '神 坐 在 地 球 大 圈 之 上 ； 地 上 的 居 民 好 像 蝗 虫 。 他 铺 张 穹 苍 如 幔 子 ， 展 开 诸 天 如 可 住 的 帐 棚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18444', '23', '40', '23', '他 使 君 王 归 于 虚 无 ， 使 地 上 的 审 判 官 成 为 虚 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18445', '23', '40', '24', '他 们 是 刚 才 ｛ 或 译 ： 不 曾 ； 下 同 ｝ 栽 上 ， 刚 才 种 上 ， 根 也 刚 才 扎 在 地 里 ， 他 一 吹 在 其 上 ， 便 都 枯 干 ； 旋 风 将 他 们 吹 去 ， 像 碎 秸 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18446', '23', '40', '25', '那 圣 者 说 ： 你 们 将 谁 比 我 ， 叫 他 与 我 相 等 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18447', '23', '40', '26', '你 们 向 上 举 目 ， 看 谁 创 造 这 万 象 ， 按 数 目 领 出 ， 他 一 一 称 其 名 ； 因 他 的 权 能 ， 又 因 他 的 大 能 大 力 ， 连 一 个 都 不 缺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18448', '23', '40', '27', '雅 各 啊 ， 你 为 何 说 ， 我 的 道 路 向 耶 和 华 隐 藏 ？ 以 色 列 啊 ， 你 为 何 言 ， 我 的 冤 屈 神 并 不 查 问 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18449', '23', '40', '28', '你 岂 不 曾 知 道 吗 ？ 你 岂 不 曾 听 见 吗 ？ 永 在 的 神 耶 和 华 ， 创 造 地 极 的 主 ， 并 不 疲 乏 ， 也 不 困 倦 ； 他 的 智 慧 无 法 测 度 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18450', '23', '40', '29', '疲 乏 的 ， 他 赐 能 力 ； 软 弱 的 ， 他 加 力 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18451', '23', '40', '30', '就 是 少 年 人 也 要 疲 乏 困 倦 ； 强 壮 的 也 必 全 然 跌 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18452', '23', '40', '31', '但 那 等 候 耶 和 华 的 必 重 新 得 力 。 他 们 必 如 鹰 展 翅 上 腾 ； 他 们 奔 跑 却 不 困 倦 ， 行 走 却 不 疲 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18453', '23', '41', '1', '＜ 神 对 以 色 列 的 保 证 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18454', '23', '41', '2', '谁 从 东 方 兴 起 一 人 ， 凭 公 义 召 他 来 到 脚 前 呢 ？ 耶 和 华 将 列 国 交 给 他 ， 使 他 管 辖 君 王 ， 把 他 们 如 灰 尘 交 与 他 的 刀 ， 如 风 吹 的 碎 秸 交 与 他 的 弓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18455', '23', '41', '3', '他 追 赶 他 们 ， 走 他 所 未 走 的 道 ， 坦 然 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18456', '23', '41', '4', '谁 行 做 成 就 这 事 ， 从 起 初 宣 召 历 代 呢 ？ 就 是 我 ─ ─ 耶 和 华 ！ 我 是 首 先 的 ， 也 与 末 后 的 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18457', '23', '41', '5', '海 岛 看 见 就 都 害 怕 ； 地 极 也 都 战 兢 ， 就 近 前 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18458', '23', '41', '6', '他 们 各 人 帮 助 邻 舍 ， 各 人 对 弟 兄 说 ： 壮 胆 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18459', '23', '41', '7', '木 匠 勉 励 银 匠 ， 用 锤 打 光 的 勉 励 打 砧 的 ， 论 焊 工 说 ， 焊 得 好 ； 又 用 钉 子 钉 稳 ， 免 得 偶 像 动 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18460', '23', '41', '8', '惟 你 以 色 列 ─ ─ 我 的 仆 人 ， 雅 各 ─ ─ 我 所 拣 选 的 ， 我 朋 友 亚 伯 拉 罕 的 后 裔 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18461', '23', '41', '9', '你 是 我 从 地 极 所 领 ｛ 原 文 是 抓 ｝ 来 的 ， 从 地 角 所 召 来 的 ， 且 对 你 说 ： 你 是 我 的 仆 人 ； 我 拣 选 你 ， 并 不 弃 绝 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18462', '23', '41', '10', '你 不 要 害 怕 ， 因 为 我 与 你 同 在 ； 不 要 惊 惶 ， 因 为 我 是 你 的 神 。 我 必 坚 固 你 ， 我 必 帮 助 你 ； 我 必 用 我 公 义 的 右 手 扶 持 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18463', '23', '41', '11', '凡 向 你 发 怒 的 必 都 抱 愧 蒙 羞 ； 与 你 相 争 的 必 如 无 有 ， 并 要 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18464', '23', '41', '12', '与 你 争 竞 的 ， 你 要 找 他 们 也 找 不 着 ； 与 你 争 战 的 必 如 无 有 ， 成 为 虚 无 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18465', '23', '41', '13', '因 为 我 耶 和 华 ─ ─ 你 的 神 必 搀 扶 你 的 右 手 ， 对 你 说 ： 不 要 害 怕 ！ 我 必 帮 助 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18466', '23', '41', '14', '你 这 虫 雅 各 和 你 们 以 色 列 人 ， 不 要 害 怕 ！ 耶 和 华 说 ： 我 必 帮 助 你 。 你 的 救 赎 主 就 是 以 色 列 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18467', '23', '41', '15', '看 哪 ， 我 已 使 你 成 为 有 快 齿 打 粮 的 新 器 具 ； 你 要 把 山 岭 打 得 粉 碎 ， 使 冈 陵 如 同 糠 秕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18468', '23', '41', '16', '你 要 把 它 簸 扬 ， 风 要 吹 去 ； 旋 风 要 把 它 刮 散 。 你 倒 要 以 耶 和 华 为 喜 乐 ， 以 以 色 列 的 圣 者 为 夸 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18469', '23', '41', '17', '困 苦 穷 乏 人 寻 求 水 却 没 有 ； 他 们 因 口 渴 ， 舌 头 干 燥 。 我 ─ ─ 耶 和 华 必 应 允 他 们 ； 我 ─ ─ 以 色 列 的 神 必 不 离 弃 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18470', '23', '41', '18', '我 要 在 净 光 的 高 处 开 江 河 ， 在 谷 中 开 泉 源 ； 我 要 使 沙 漠 变 为 水 池 ， 使 干 地 变 为 涌 泉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18471', '23', '41', '19', '我 要 在 旷 野 种 上 香 柏 树 、 皂 荚 树 、 番 石 榴 树 ， 和 野 橄 榄 树 。 我 在 沙 漠 要 把 松 树 、 杉 树 ， 并 黄 杨 树 一 同 栽 植 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18472', '23', '41', '20', '好 叫 人 看 见 、 知 道 、 思 想 、 明 白 ； 这 是 耶 和 华 的 手 所 做 的 ， 是 以 色 列 的 圣 者 所 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18473', '23', '41', '21', '＜ 耶 和 华 向 假 神 挑 战 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18474', '23', '41', '22', '可 以 声 明 ， 指 示 我 们 将 来 必 遇 的 事 ， 说 明 先 前 的 是 什 么 事 ， 好 叫 我 们 思 索 ， 得 知 事 的 结 局 ， 或 者 把 将 来 的 事 指 示 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18475', '23', '41', '23', '要 说 明 后 来 的 事 ， 好 叫 我 们 知 道 你 们 是 神 。 你 们 或 降 福 ， 或 降 祸 ， 使 我 们 惊 奇 ， 一 同 观 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18476', '23', '41', '24', '看 哪 ， 你 们 属 乎 虚 无 ； 你 们 的 作 为 也 属 乎 虚 空 。 那 选 择 你 们 的 是 可 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18477', '23', '41', '25', '我 从 北 方 兴 起 一 人 ； 他 是 求 告 我 名 的 ， 从 日 出 之 地 而 来 。 他 必 临 到 掌 权 的 ， 好 像 临 到 灰 泥 ， 仿 佛 窑 匠 踹 泥 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18478', '23', '41', '26', '谁 从 起 初 指 明 这 事 ， 使 我 们 知 道 呢 ？ 谁 从 先 前 说 明 ， 使 我 们 说 他 不 错 呢 ？ 谁 也 没 有 指 明 ； 谁 也 没 有 说 明 ； 谁 也 没 有 听 见 你 们 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18479', '23', '41', '27', '我 首 先 对 锡 安 说 ： 看 哪 ， 我 要 将 一 位 报 好 信 息 的 赐 给 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18480', '23', '41', '28', '我 看 的 时 候 并 没 有 人 ； 我 问 的 时 候 ， 他 们 中 间 也 没 有 谋 士 可 以 回 答 一 句 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18481', '23', '41', '29', '看 哪 ， 他 们 和 他 们 的 工 作 都 是 虚 空 ， 且 是 虚 无 。 他 们 所 铸 的 偶 像 都 是 风 ， 都 是 虚 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18482', '23', '42', '1', '＜ 耶 和 华 的 仆 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18483', '23', '42', '2', '他 不 喧 嚷 ， 不 扬 声 ， 也 不 使 街 上 听 见 他 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18484', '23', '42', '3', '压 伤 的 芦 苇 ， 他 不 折 断 ； 将 残 的 灯 火 ， 他 不 吹 灭 。 他 凭 真 实 将 公 理 传 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18485', '23', '42', '4', '他 不 灰 心 ， 也 不 丧 胆 ， 直 到 他 在 地 上 设 立 公 理 ； 海 岛 都 等 候 他 的 训 诲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18486', '23', '42', '5', '创 造 诸 天 ， 铺 张 穹 苍 ， 将 地 和 地 所 出 的 一 并 铺 开 ， 赐 气 息 给 地 上 的 众 人 ， 又 赐 灵 性 给 行 在 其 上 之 人 的 神 耶 和 华 ， 他 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18487', '23', '42', '6', '我 ─ ─ 耶 和 华 凭 公 义 召 你 ， 必 搀 扶 你 的 手 ， 保 守 你 ， 使 你 作 众 民 的 中 保 ｛ 中 保 ： 原 文 是 约 ｝ ， 作 外 邦 人 的 光 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18488', '23', '42', '7', '开 瞎 子 的 眼 ， 领 被 囚 的 出 牢 狱 ， 领 坐 黑 暗 的 出 监 牢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18489', '23', '42', '8', '我 是 耶 和 华 ， 这 是 我 的 名 ； 我 必 不 将 我 的 荣 耀 归 给 假 神 ， 也 不 将 我 的 称 赞 归 给 雕 刻 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18490', '23', '42', '9', '看 哪 ， 先 前 的 事 已 经 成 就 ， 现 在 我 将 新 事 说 明 ， 这 事 未 发 以 先 ， 我 就 说 给 你 们 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18491', '23', '42', '10', '＜ 颂 赞 之 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18492', '23', '42', '11', '旷 野 和 其 中 的 城 邑 ， 并 基 达 人 居 住 的 村 庄 都 当 扬 声 ； 西 拉 的 居 民 当 欢 呼 ， 在 山 顶 上 呐 喊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18493', '23', '42', '12', '他 们 当 将 荣 耀 归 给 耶 和 华 ， 在 海 岛 中 传 扬 他 的 颂 赞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18494', '23', '42', '13', '耶 和 华 必 像 勇 士 出 去 ， 必 像 战 士 激 动 热 心 ， 要 喊 叫 ， 大 声 呐 喊 ， 要 用 大 力 攻 击 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18495', '23', '42', '14', '＜ 神 应 许 帮 助 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18496', '23', '42', '15', '我 要 使 大 山 小 冈 变 为 荒 场 ， 使 其 上 的 花 草 都 枯 干 ； 我 要 使 江 河 变 为 洲 岛 ， 使 水 池 都 干 涸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18497', '23', '42', '16', '我 要 引 瞎 子 行 不 认 识 的 道 ， 领 他 们 走 不 知 道 的 路 ； 在 他 们 面 前 使 黑 暗 变 为 光 明 ， 使 弯 曲 变 为 平 直 。 这 些 事 我 都 要 行 ， 并 不 离 弃 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18498', '23', '42', '17', '倚 靠 雕 刻 的 偶 像 ， 对 铸 造 的 偶 像 说 ： 你 是 我 们 的 神 ； 这 等 人 要 退 后 ， 全 然 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18499', '23', '42', '18', '＜ 以 色 列 人 不 受 教 益 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18500', '23', '42', '19', '谁 比 我 的 仆 人 眼 瞎 呢 ？ 谁 比 我 差 遣 的 使 者 耳 聋 呢 ？ 谁 瞎 眼 像 那 与 我 和 好 的 ？ 谁 瞎 眼 像 耶 和 华 的 仆 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18501', '23', '42', '20', '你 看 见 许 多 事 却 不 领 会 ， 耳 朵 开 通 却 不 听 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18502', '23', '42', '21', '耶 和 华 因 自 己 公 义 的 缘 故 ， 喜 欢 使 律 法 ｛ 或 译 ： 训 诲 ｝ 为 大 ， 为 尊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18503', '23', '42', '22', '但 这 百 姓 是 被 抢 被 夺 的 ， 都 牢 笼 在 坑 中 ， 隐 藏 在 狱 里 ； 他 们 作 掠 物 ， 无 人 拯 救 ， 作 掳 物 ， 无 人 说 交 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18504', '23', '42', '23', '你 们 中 间 谁 肯 侧 耳 听 此 ， 谁 肯 留 心 而 听 ， 以 防 将 来 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18505', '23', '42', '24', '谁 将 雅 各 交 出 当 作 掳 物 ， 将 以 色 列 交 给 抢 夺 的 呢 ？ 岂 不 是 耶 和 华 吗 ？ 就 是 我 们 所 得 罪 的 那 位 。 他 们 不 肯 遵 行 他 的 道 ， 也 不 听 从 他 的 训 诲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18506', '23', '42', '25', '所 以 ， 他 将 猛 烈 的 怒 气 和 争 战 的 勇 力 倾 倒 在 以 色 列 的 身 上 。 在 他 四 围 如 火 着 起 ， 他 还 不 知 道 ， 烧 着 他 ， 他 也 不 介 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18507', '23', '43', '1', '＜ 神 应 许 拯 救 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18508', '23', '43', '2', '你 从 水 中 经 过 ， 我 必 与 你 同 在 ； 你 逿 过 江 河 ， 水 必 不 漫 过 你 ； 你 从 火 中 行 过 ， 必 不 被 烧 ， 火 焰 也 不 着 在 你 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18509', '23', '43', '3', '因 为 我 是 耶 和 华 ─ ─ 你 的 神 ， 是 以 色 列 的 圣 者 ─ ─ 你 的 救 主 ； 我 已 经 使 埃 及 作 你 的 赎 价 ， 使 古 实 和 西 巴 代 替 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18510', '23', '43', '4', '因 我 看 你 为 宝 为 尊 ； 又 因 我 爱 你 ， 所 以 我 使 人 代 替 你 ， 使 列 邦 人 替 换 你 的 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18511', '23', '43', '5', '不 要 害 怕 ， 因 我 与 你 同 在 ； 我 必 领 你 的 后 裔 从 东 方 来 ， 又 从 西 方 招 聚 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18512', '23', '43', '6', '我 要 对 北 方 说 ， 交 出 来 ！ 对 南 方 说 ， 不 要 拘 留 ！ 将 我 的 众 子 从 远 方 带 来 ， 将 我 的 众 女 从 地 极 领 回 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18513', '23', '43', '7', '就 是 凡 称 为 我 名 下 的 人 ， 是 我 为 自 己 的 荣 耀 创 造 的 ， 是 我 所 做 成 ， 所 造 作 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18514', '23', '43', '8', '＜ 以 色 列 是 耶 和 华 的 见 证 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18515', '23', '43', '9', '任 凭 万 国 聚 集 ； 任 凭 众 民 会 合 。 其 中 谁 能 将 此 声 明 ， 并 将 先 前 的 事 说 给 我 们 听 呢 ？ 他 们 可 以 带 出 见 证 来 ， 自 显 为 是 ； 或 者 他 们 听 见 便 说 ： 这 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18516', '23', '43', '10', '耶 和 华 说 ： 你 们 是 我 的 见 证 ， 我 所 拣 选 的 仆 人 。 既 是 这 样 ， 便 可 以 知 道 ， 且 信 服 我 ， 又 明 白 我 就 是 耶 和 华 。 在 我 以 前 没 有 真 神 ｛ 真 ： 原 文 是 造 作 的 ｝ ； 在 我 以 后 也 必 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18517', '23', '43', '11', '惟 有 我 是 耶 和 华 ； 除 我 以 外 没 有 救 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18518', '23', '43', '12', '我 曾 指 示 ， 我 曾 拯 救 ， 我 曾 说 明 ， 并 且 在 你 们 中 间 没 有 别 神 。 所 以 耶 和 华 说 ： 你 们 是 我 的 见 证 。 我 也 是 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18519', '23', '43', '13', '自 从 有 日 子 以 来 ， 我 就 是 神 ； 谁 也 不 能 救 人 脱 离 我 手 。 我 要 行 事 谁 能 阻 止 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18520', '23', '43', '14', '＜ 逃 离 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18521', '23', '43', '15', '我 是 耶 和 华 ─ ─ 你 们 的 圣 者 ， 是 创 造 以 色 列 的 ， 是 你 们 的 君 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18522', '23', '43', '16', '耶 和 华 在 沧 海 中 开 道 ， 在 大 水 中 开 路 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18523', '23', '43', '17', '使 车 辆 、 马 匹 、 军 兵 、 勇 士 都 出 来 ， 一 同 躺 下 ， 不 再 起 来 ； 他 们 灭 没 ， 好 像 熄 灭 的 灯 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18524', '23', '43', '18', '耶 和 华 如 此 说 ： 你 们 不 要 记 念 从 前 的 事 ， 也 不 要 思 想 古 时 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18525', '23', '43', '19', '看 哪 ， 我 要 做 一 件 新 事 ； 如 今 要 发 现 ， 你 们 岂 不 知 道 吗 ？ 我 必 在 旷 野 开 道 路 ， 在 沙 漠 开 江 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18526', '23', '43', '20', '野 地 的 走 兽 必 尊 重 我 ； 野 狗 和 鸵 鸟 也 必 如 此 。 因 我 使 旷 野 有 水 ， 使 沙 漠 有 河 ， 好 赐 给 我 的 百 姓 、 我 的 选 民 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18527', '23', '43', '21', '这 百 姓 是 我 为 自 己 所 造 的 ， 好 述 说 我 的 美 德 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18528', '23', '43', '22', '＜ 以 色 列 人 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18529', '23', '43', '23', '你 没 有 将 你 的 羊 带 来 给 我 作 燔 祭 ， 也 没 有 用 祭 物 尊 敬 我 ； 我 没 有 因 供 物 使 你 服 劳 ， 也 没 有 因 乳 香 使 你 厌 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18530', '23', '43', '24', '你 没 有 用 银 子 为 我 买 菖 蒲 ， 也 没 有 用 祭 物 的 脂 油 使 我 饱 足 ； 倒 使 我 因 你 的 罪 恶 服 劳 ， 使 我 因 你 的 罪 孽 厌 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18531', '23', '43', '25', '惟 有 我 为 自 己 的 缘 故 涂 抹 你 的 过 犯 ； 我 也 不 记 念 你 的 罪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18532', '23', '43', '26', '你 要 提 醒 我 ， 你 我 可 以 一 同 辩 论 ； 你 可 以 将 你 的 理 陈 明 ， 自 显 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18533', '23', '43', '27', '你 的 始 祖 犯 罪 ； 你 的 师 傅 违 背 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18534', '23', '43', '28', '所 以 ， 我 要 辱 没 圣 所 的 首 领 ， 使 雅 各 成 为 咒 诅 ， 使 以 色 列 成 为 辱 骂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18535', '23', '44', '1', '＜ 耶 和 华 是 独 一 的 神 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18536', '23', '44', '2', '造 作 你 ， 又 从 你 出 胎 造 就 你 ， 并 要 帮 助 你 的 耶 和 华 如 此 说 ： 我 的 仆 人 雅 各 ， 我 所 拣 选 的 耶 书 仑 哪 ， 不 要 害 怕 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18537', '23', '44', '3', '因 为 我 要 将 水 浇 灌 口 渴 的 人 ， 将 河 浇 灌 干 旱 之 地 。 我 要 将 我 的 灵 浇 灌 你 的 后 裔 ， 将 我 的 福 浇 灌 你 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18538', '23', '44', '4', '他 们 要 发 生 在 草 中 ， 像 溪 水 旁 的 柳 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18539', '23', '44', '5', '这 个 要 说 ： 我 是 属 耶 和 华 的 ； 那 个 要 以 雅 各 的 名 自 称 ； 又 一 个 要 亲 手 写 ： 归 耶 和 华 的 ｛ 或 译 ： 在 手 上 写 归 耶 和 华 ｝ ， 并 自 称 为 以 色 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18540', '23', '44', '6', '耶 和 华 ─ ─ 以 色 列 的 君 ， 以 色 列 的 救 赎 主 ─ ─ 万 军 之 耶 和 华 如 此 说 ： 我 是 首 先 的 ， 我 是 末 后 的 ； 除 我 以 外 再 没 有 真 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18541', '23', '44', '7', '自 从 我 设 立 古 时 的 民 ， 谁 能 像 我 宣 告 ， 并 且 指 明 ， 又 为 自 己 陈 说 呢 ？ 让 他 将 未 来 来 的 事 和 必 成 的 事 说 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18542', '23', '44', '8', '你 们 不 要 恐 惧 ， 也 不 要 害 怕 。 我 岂 不 是 从 上 古 就 说 明 指 示 你 们 吗 ？ 并 且 你 们 是 我 的 见 证 ！ 除 我 以 外 ， 岂 有 真 神 吗 ？ 诚 然 没 有 磐 石 ， 我 不 知 道 一 个 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18543', '23', '44', '9', '＜ 虚 无 的 偶 像 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18544', '23', '44', '10', '谁 制 造 神 像 ， 铸 造 无 益 的 偶 像 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18545', '23', '44', '11', '看 哪 ， 他 的 同 伴 都 必 羞 愧 。 工 匠 也 不 过 是 人 ， 任 他 们 聚 会 ， 任 他 们 站 立 ， 都 必 惧 怕 ， 一 同 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18546', '23', '44', '12', '铁 匠 把 铁 在 火 炭 中 烧 热 ， 用 锤 打 铁 器 ， 用 他 有 力 的 膀 臂 锤 成 ； 他 饥 饿 而 无 力 ， 不 喝 水 而 发 倦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18547', '23', '44', '13', '木 匠 拉 线 ， 用 笔 划 出 样 子 ， 用 刨 子 刨 成 形 状 ， 用 圆 尺 划 了 模 样 ， 仿 照 人 的 体 态 ， 做 成 人 形 ， 好 住 在 房 屋 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18548', '23', '44', '14', '他 砍 伐 香 柏 树 ， 又 取 柞 ｛ 或 译 ： 青 桐 ｝ 树 和 橡 树 ， 在 树 林 中 选 定 了 一 棵 。 他 栽 种 松 树 ， 得 雨 长 养 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18549', '23', '44', '15', '这 树 ， 人 可 用 以 烧 火 ； 他 自 己 取 些 烤 火 ， 又 烧 着 烤 饼 ， 而 且 做 神 像 跪 拜 ， 做 雕 刻 的 偶 像 向 它 叩 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18550', '23', '44', '16', '他 把 一 分 烧 在 火 中 ， 把 一 分 烤 肉 吃 饱 。 自 己 烤 火 说 ： “ 啊 哈 ， 我 暖 和 了 ， 我 见 火 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18551', '23', '44', '17', '他 用 剩 下 的 做 了 一 神 ， 就 是 雕 刻 的 偶 像 。 他 向 这 偶 像 俯 伏 叩 拜 ， 祷 告 它 说 ： “ 求 你 拯 救 我 ， 因 你 是 我 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18552', '23', '44', '18', '他 们 不 知 道 ， 也 不 思 想 ； 因 为 耶 和 华 闭 住 他 们 的 眼 ， 不 能 看 见 ， 塞 住 他 们 的 心 ， 不 能 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18553', '23', '44', '19', '谁 心 里 也 不 醒 悟 ， 也 没 有 知 识 ， 没 有 聪 明 ， 能 说 ： “ 我 曾 拿 一 分 在 火 中 烧 了 ， 在 炭 火 上 烤 过 饼 ； 我 也 烤 过 肉 吃 。 这 剩 下 的 ， 我 岂 要 做 可 憎 的 物 吗 ？ 我 岂 可 向 木 不 子 叩 拜 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18554', '23', '44', '20', '他 以 灰 为 食 ， 心 中 昏 迷 ， 使 他 偏 邪 ， 他 不 能 自 救 ， 也 不 能 说 ： “ 我 右 手 中 岂 不 是 有 虚 谎 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18555', '23', '44', '21', '＜ 耶 和 华 是 创 造 主 也 是 救 赎 主 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18556', '23', '44', '22', '我 涂 抹 了 你 的 过 犯 ， 像 厚 云 消 散 ； 我 涂 抹 了 你 的 罪 恶 ， 如 薄 云 灭 没 。 你 当 归 向 我 ， 因 我 救 赎 了 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18557', '23', '44', '23', '诸 天 哪 ， 应 当 歌 唱 ， 因 为 耶 和 华 做 成 这 事 。 地 的 深 处 啊 ， 应 当 欢 呼 ； 众 山 应 当 发 声 歌 唱 ； 树 林 和 其 中 所 有 的 树 都 当 如 此 ！ 因 为 耶 和 华 救 赎 了 雅 各 ， 并 要 因 以 色 列 荣 耀 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18558', '23', '44', '24', '从 你 出 胎 ， 造 就 你 的 救 赎 主 ─ ─ 耶 和 华 如 此 说 ： 我 ─ ─ 耶 和 华 是 创 造 万 物 的 ， 是 独 自 铺 张 诸 天 、 铺 开 大 地 的 。 谁 与 我 同 在 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18559', '23', '44', '25', '使 说 假 话 的 兆 头 失 效 ， 使 占 卜 的 癫 狂 ， 使 智 慧 人 退 后 ， 使 他 的 知 识 变 为 愚 拙 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18560', '23', '44', '26', '使 我 仆 人 的 话 语 立 定 ， 我 使 者 的 谋 算 成 就 。 论 到 耶 路 撒 冷 说 ： 必 有 人 居 住 ； 论 到 犹 大 的 城 邑 说 ： 必 被 建 造 ， 其 中 的 荒 场 我 也 必 兴 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18561', '23', '44', '27', '对 深 渊 说 ： 你 干 了 吧 ！ 我 也 要 使 你 的 江 河 干 涸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18562', '23', '44', '28', '论 塞 鲁 士 说 ： 他 是 我 的 牧 人 ， 必 成 就 我 所 喜 悦 的 ， 必 下 令 建 造 耶 路 撒 冷 ， 发 命 立 稳 圣 殿 的 根 基 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18563', '23', '45', '1', '＜ 耶 和 华 立 塞 鲁 士 为 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18564', '23', '45', '2', '我 必 在 你 前 面 行 ， 修 平 崎 岖 之 地 。 我 必 打 破 铜 门 ， 砍 断 铁 闩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18565', '23', '45', '3', '我 要 将 暗 中 的 宝 物 和 隐 密 的 财 宝 赐 给 你 ， 使 你 知 道 提 名 召 你 的 ， 就 是 我 ─ ─ 耶 和 华 、 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18566', '23', '45', '4', '因 我 仆 人 雅 各 ， 我 所 拣 选 以 色 列 的 缘 故 ， 我 就 提 名 召 你 ； 你 虽 不 认 识 我 ， 我 也 加 给 你 名 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18567', '23', '45', '5', '我 是 耶 和 华 ， 在 我 以 外 并 没 有 别 神 ； 除 了 我 以 外 再 没 有 神 。 你 虽 不 认 识 我 ， 我 必 给 你 束 腰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18568', '23', '45', '6', '从 日 出 之 地 到 日 落 之 处 使 人 都 知 道 除 了 我 以 外 ， 没 有 别 神 。 我 是 耶 和 华 ； 在 我 以 外 并 没 有 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18569', '23', '45', '7', '我 造 光 ， 又 造 暗 ； 我 施 平 安 ， 又 降 灾 祸 ； 造 作 这 一 切 的 是 我 ─ ─ 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18570', '23', '45', '8', '诸 天 哪 ， 自 上 而 滴 ， 穹 苍 降 下 公 义 ； 地 面 开 裂 ， 产 出 救 恩 ， 使 公 义 一 同 发 生 ； 这 都 是 我 ─ ─ 耶 和 华 所 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18571', '23', '45', '9', '＜ 创 造 和 历 史 的 主 宰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18572', '23', '45', '10', '祸 哉 ， 那 对 父 亲 说 ： 你 生 的 是 什 么 呢 ？ 或 对 母 亲 ｛ 原 文 是 妇 人 ｝ 说 ： 你 产 的 是 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18573', '23', '45', '11', '耶 和 华 ─ ─ 以 色 列 的 圣 者 ， 就 是 造 就 以 色 列 的 如 此 说 ： 将 来 的 事 ， 你 们 可 以 问 我 ； 至 于 我 的 众 子 ， 并 我 手 的 工 作 ， 你 们 可 以 求 我 命 定 ｛ 原 文 是 吩 咐 我 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18574', '23', '45', '12', '我 造 地 ， 又 造 人 在 地 上 。 我 亲 手 铺 张 诸 天 ； 天 上 万 象 也 是 我 所 命 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18575', '23', '45', '13', '我 凭 公 义 兴 起 塞 鲁 士 ｛ 原 文 是 他 ｝ ， 又 要 修 直 他 一 切 道 路 。 他 必 建 造 我 的 城 ， 释 放 我 被 掳 的 民 ； 不 是 为 工 价 ， 也 不 是 为 赏 赐 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18576', '23', '45', '14', '耶 和 华 如 此 说 ： 埃 及 劳 碌 得 来 的 和 古 实 的 货 物 必 归 你 ； 身 量 高 大 的 西 巴 人 必 投 降 你 ， 也 要 属 你 。 他 们 必 带 着 锁 炼 过 来 随 从 你 ， 又 向 你 下 拜 ， 祈 求 你 说 ： 神 真 在 你 们 中 间 ， 此 外 再 没 有 别 神 ； 再 没 有 别 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18577', '23', '45', '15', '救 主 ─ ─ 以 色 列 的 神 啊 ， 你 实 在 是 自 隐 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18578', '23', '45', '16', '凡 制 造 偶 像 的 都 必 抱 愧 蒙 羞 ， 都 要 一 同 归 于 惭 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18579', '23', '45', '17', '惟 有 以 色 列 必 蒙 耶 和 华 的 拯 救 ， 得 永 远 的 救 恩 。 你 们 必 不 蒙 羞 ， 也 不 抱 愧 ， 直 到 永 世 无 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18580', '23', '45', '18', '创 造 诸 天 的 耶 和 华 ， 制 造 成 全 大 地 的 神 ， 他 创 造 坚 定 大 地 ， 并 非 使 地 荒 凉 ， 是 要 给 人 居 住 。 他 如 此 说 ： 我 是 耶 和 华 ， 再 没 有 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18581', '23', '45', '19', '我 没 有 在 隐 密 黑 暗 之 地 说 话 ； 我 没 有 对 雅 各 的 后 裔 说 ： 你 们 寻 求 我 是 徒 然 的 。 我 ─ ─ 耶 和 华 所 讲 的 是 公 义 ， 所 说 的 是 正 直 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18582', '23', '45', '20', '＜ 天 地 之 主 和 巴 比 伦 的 偶 像 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18583', '23', '45', '21', '你 们 要 述 说 陈 明 你 们 的 理 ， 让 他 们 彼 此 商 议 。 谁 从 古 时 指 明 ？ 谁 从 上 古 述 说 ？ 不 是 我 ─ ─ 耶 和 华 吗 ？ 除 了 我 以 外 ， 再 没 有 神 ； 我 是 公 义 的 神 ， 又 是 救 主 ； 除 了 我 以 外 ， 再 没 有 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18584', '23', '45', '22', '地 极 的 人 都 当 仰 望 我 ， 就 必 得 救 ； 因 为 我 是 神 ， 再 没 有 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18585', '23', '45', '23', '我 指 着 自 己 起 誓 ， 我 口 所 出 的 话 是 凭 公 义 ， 并 不 反 回 ： 万 膝 必 向 我 跪 拜 ； 万 口 必 凭 我 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18586', '23', '45', '24', '人 论 我 说 ， 公 义 、 能 力 ， 惟 独 在 乎 耶 和 华 ； 人 都 必 归 向 他 。 凡 向 他 发 怒 的 必 至 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18587', '23', '45', '25', '以 色 列 的 后 裔 都 必 因 耶 和 华 得 称 为 义 ， 并 要 夸 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18588', '23', '46', '1', '彼 勒 屈 身 ， 尼 波 弯 腰 ； 巴 比 伦 的 偶 像 驮 在 兽 和 牲 畜 上 。 他 们 所 抬 的 如 今 成 了 重 驮 ， 使 牲 畜 疲 乏 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18589', '23', '46', '2', '都 一 同 弯 腰 屈 身 ， 不 能 保 全 重 驮 ， 自 己 倒 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18590', '23', '46', '3', '雅 各 家 ， 以 色 列 家 一 切 余 剩 的 要 听 我 言 ： 你 们 自 从 生 下 ， 就 蒙 我 保 抱 ， 自 从 出 胎 ， 便 蒙 我 怀 搋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18591', '23', '46', '4', '直 到 你 们 年 老 ， 我 仍 这 样 ； 直 到 你 们 发 白 ， 我 仍 怀 搋 。 我 已 造 作 ， 也 必 保 抱 ； 我 必 怀 抱 ， 也 必 拯 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18592', '23', '46', '5', '你 们 将 谁 与 我 相 比 ， 与 我 同 等 ， 可 以 与 我 比 较 ， 使 我 们 相 同 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18593', '23', '46', '6', '那 从 囊 中 抓 金 子 ， 用 天 平 平 银 子 的 人 ， 雇 银 匠 制 造 神 像 ， 他 们 又 俯 伏 ， 又 叩 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18594', '23', '46', '7', '他 们 将 神 像 抬 起 ， 扛 在 肩 上 ， 安 置 在 定 处 ， 它 就 站 立 ， 不 离 本 位 ； 人 呼 求 它 ， 它 不 能 答 应 ， 也 不 能 救 人 脱 离 患 难 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18595', '23', '46', '8', '你 们 当 想 念 这 事 ， 自 己 作 大 丈 夫 。 悖 逆 的 人 哪 ， 要 心 里 思 想 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18596', '23', '46', '9', '你 们 要 追 念 上 古 的 事 。 因 为 我 是 神 ， 并 无 别 神 ； 我 是 神 ， 再 没 有 能 比 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18597', '23', '46', '10', '我 从 起 初 指 明 末 后 的 事 ， 从 古 时 言 明 未 成 的 事 ， 说 ： 我 的 筹 算 必 立 定 ； 凡 我 所 喜 悦 的 ， 我 必 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18598', '23', '46', '11', '我 召 鸷 鸟 从 东 方 来 ， 召 那 成 就 我 筹 算 的 人 从 远 方 来 。 我 已 说 出 ， 也 必 成 就 ； 我 已 谋 定 ， 也 必 做 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18599', '23', '46', '12', '你 们 这 些 心 中 顽 梗 、 远 离 公 义 的 ， 当 听 我 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18600', '23', '46', '13', '我 使 我 的 公 义 临 近 ， 必 不 远 离 。 我 的 救 恩 必 不 迟 延 ； 我 要 为 以 色 列 ─ ─ 我 的 荣 耀 ， 在 锡 安 施 行 救 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18601', '23', '47', '1', '＜ 审 判 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18602', '23', '47', '2', '要 用 磨 磨 面 ， 揭 去 帕 子 ， 脱 去 长 衣 ， 露 腿 逿 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18603', '23', '47', '3', '你 的 下 体 必 被 露 出 ； 你 的 丑 陋 必 被 看 见 。 我 要 报 仇 ， 谁 也 不 宽 容 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18604', '23', '47', '4', '我 们 救 赎 主 的 名 是 万 军 之 耶 和 华 ─ ─ 以 色 列 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18605', '23', '47', '5', '迦 勒 底 的 闺 女 啊 ， 你 要 默 然 静 坐 ， 进 入 暗 中 ， 因 为 你 不 再 称 为 列 国 的 主 母 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18606', '23', '47', '6', '我 向 我 的 百 姓 发 怒 ， 使 我 的 产 业 被 亵 渎 ， 将 他 们 交 在 你 手 中 ， 你 毫 不 怜 悯 他 们 ， 把 极 重 的 轭 加 在 老 年 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18607', '23', '47', '7', '你 自 己 说 ： 我 必 永 为 主 母 ， 所 以 你 不 将 这 事 放 在 心 上 ， 也 不 思 想 这 事 的 结 局 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18608', '23', '47', '8', '你 这 专 好 宴 乐 、 安 然 居 住 的 ， 现 在 当 听 这 话 。 你 心 中 说 ： 惟 有 我 ， 除 我 以 外 再 没 有 别 的 。 我 必 不 致 寡 居 ， 也 不 遭 丧 子 之 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18609', '23', '47', '9', '哪 知 ， 丧 子 、 寡 居 这 两 件 事 在 一 日 转 眼 之 间 必 临 到 你 ； 正 在 你 多 行 邪 术 、 广 施 符 咒 的 时 候 ， 这 两 件 事 必 全 然 临 到 你 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18610', '23', '47', '10', '你 素 来 倚 仗 自 己 的 恶 行 ， 说 ： 无 人 看 见 我 。 你 的 智 慧 聪 明 使 你 偏 邪 ， 并 且 你 心 里 说 ： 惟 有 我 ， 除 我 以 外 再 没 有 别 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18611', '23', '47', '11', '因 此 ， 祸 患 要 临 到 你 身 ， 你 不 知 何 时 发 现 ｛ 或 译 ： 如 何 驱 逐 ｝ ； 灾 害 落 在 你 身 上 ， 你 也 不 能 除 掉 ； 所 不 知 道 的 毁 灭 也 必 忽 然 临 到 你 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18612', '23', '47', '12', '站 起 来 吧 ！ 用 你 从 幼 年 劳 神 施 行 的 符 咒 和 你 许 多 的 邪 术 ； 或 者 可 得 益 处 ， 或 者 可 得 强 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18613', '23', '47', '13', '你 筹 划 太 多 ， 以 致 疲 倦 。 让 那 些 观 天 象 的 ， 看 星 宿 的 ， 在 月 朔 说 预 言 的 ， 都 站 起 来 ， 救 你 脱 离 所 要 临 到 你 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18614', '23', '47', '14', '他 们 要 像 碎 秸 被 火 焚 烧 ， 不 能 救 自 己 脱 离 火 焰 之 力 ； 这 火 并 非 可 烤 的 炭 火 ， 也 不 是 可 以 坐 在 其 前 的 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18615', '23', '47', '15', '你 所 劳 神 的 事 都 要 这 样 与 你 无 益 ； 从 幼 年 与 你 贸 易 的 也 都 各 奔 各 乡 ， 无 人 救 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18616', '23', '48', '1', '＜ 神 掌 管 未 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18617', '23', '48', '2', '他 们 自 称 为 圣 城 的 人 ， 所 倚 靠 的 是 名 为 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18618', '23', '48', '3', '主 说 ： 早 先 的 事 ， 我 从 古 时 说 明 ， 已 经 出 了 我 的 口 ， 也 是 我 所 指 示 的 ； 我 忽 然 行 做 ， 事 便 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18619', '23', '48', '4', '因 为 我 素 来 知 道 你 是 顽 梗 的 ─ ─ 你 的 颈 项 是 铁 的 ； 你 的 额 是 铜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18620', '23', '48', '5', '所 以 ， 我 从 古 时 将 这 事 给 你 说 明 ， 在 未 成 以 先 指 示 你 ， 免 得 你 说 ： 这 些 事 是 我 的 偶 像 所 行 的 ， 是 我 雕 刻 的 偶 像 和 我 铸 造 的 偶 像 所 命 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18621', '23', '48', '6', '你 已 经 听 见 ， 现 在 要 看 见 这 一 切 ； 你 不 说 明 吗 ？ 从 今 以 后 ， 我 将 新 事 ， 就 是 你 所 不 知 道 的 隐 密 事 指 示 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18622', '23', '48', '7', '这 事 是 现 今 造 的 ， 并 非 从 古 就 有 ； 在 今 日 以 先 ， 你 也 未 曾 听 见 ， 免 得 你 说 ： 这 事 我 早 已 知 道 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18623', '23', '48', '8', '你 未 曾 听 见 ， 未 曾 知 道 ； 你 的 耳 朵 从 来 未 曾 开 通 。 我 原 知 道 你 行 事 极 其 诡 诈 ， 你 自 从 出 胎 以 来 ， 便 称 为 悖 逆 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18624', '23', '48', '9', '我 为 我 的 名 暂 且 忍 怒 ， 为 我 的 颂 赞 向 你 容 忍 ， 不 将 你 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18625', '23', '48', '10', '我 熬 炼 你 ， 却 不 像 熬 炼 银 子 ； 你 在 苦 难 的 炉 中 ， 我 拣 选 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18626', '23', '48', '11', '我 为 自 己 的 缘 故 必 行 这 事 ， 我 焉 能 使 我 的 名 被 亵 渎 ？ 我 必 不 将 我 的 荣 耀 归 给 假 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18627', '23', '48', '12', '＜ 耶 和 华 拣 选 塞 鲁 士 为 领 导 者 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18628', '23', '48', '13', '我 手 立 了 地 的 根 基 ； 我 右 手 铺 张 诸 天 ； 我 一 招 呼 便 都 立 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18629', '23', '48', '14', '你 们 都 当 聚 集 而 听 ， 他 们 ｛ 或 译 ： 偶 像 ｝ 内 中 谁 说 过 这 些 事 ？ 耶 和 华 所 爱 的 人 必 向 巴 比 伦 行 他 所 喜 悦 的 事 ； 他 的 膀 臂 也 要 加 在 迦 勒 底 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18630', '23', '48', '15', '惟 有 我 曾 说 过 ， 我 又 选 召 他 ， 领 他 来 ， 他 的 道 路 就 必 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18631', '23', '48', '16', '你 们 要 就 近 我 来 听 这 话 ： 我 从 起 头 并 未 曾 在 隐 密 处 说 话 ； 自 从 有 这 事 ， 我 就 在 那 里 。 现 在 ， 主 耶 和 华 差 遣 我 和 他 的 灵 来 ｛ 或 译 ： 耶 和 华 和 他 的 灵 差 遣 我 来 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18632', '23', '48', '17', '＜ 耶 和 华 对 他 子 民 的 计 划 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18633', '23', '48', '18', '甚 愿 你 素 来 听 从 我 的 命 令 ！ 你 的 平 安 就 如 河 水 ； 你 的 公 义 就 如 海 浪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18634', '23', '48', '19', '你 的 后 裔 也 必 多 如 海 沙 ； 你 腹 中 所 生 的 也 必 多 如 沙 粒 。 他 的 名 在 我 面 前 必 不 剪 除 ， 也 不 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18635', '23', '48', '20', '你 们 要 从 巴 比 伦 出 来 ， 从 迦 勒 底 人 中 逃 脱 ， 以 欢 呼 的 声 音 传 扬 说 ： 耶 和 华 救 赎 了 他 的 仆 人 雅 各 ！ 你 们 要 将 这 事 宣 扬 到 地 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18636', '23', '48', '21', '耶 和 华 引 导 他 们 经 过 沙 漠 。 他 们 并 不 干 渴 ； 他 为 他 们 使 水 从 磐 石 而 流 ， 分 裂 磐 石 ， 水 就 涌 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18637', '23', '48', '22', '耶 和 华 说 ： 恶 人 必 不 得 平 安 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18638', '23', '49', '1', '＜ 以 色 列 外 邦 之 光 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18639', '23', '49', '2', '他 使 我 的 口 如 快 刀 ， 将 我 藏 在 他 手 荫 之 下 ； 又 使 我 成 为 磨 亮 的 箭 ， 将 我 藏 在 他 箭 袋 之 中 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18640', '23', '49', '3', '对 我 说 ： 你 是 我 的 仆 人 以 色 列 ； 我 必 因 你 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18641', '23', '49', '4', '我 却 说 ： 我 劳 碌 是 徒 然 ； 我 尽 力 是 虚 无 虚 空 。 然 而 ， 我 当 得 的 理 必 在 耶 和 华 那 里 ； 我 的 赏 赐 必 在 我 神 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18642', '23', '49', '5', '耶 和 华 从 我 出 胎 ， 造 就 我 作 他 的 仆 人 ， 要 使 雅 各 归 向 他 ， 使 以 色 列 到 他 那 里 聚 集 。 原 来 耶 和 华 看 我 为 尊 贵 ； 我 的 神 也 成 为 我 的 力 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18643', '23', '49', '6', '现 在 他 说 ： 你 作 我 的 仆 人 ， 使 雅 各 众 支 派 复 兴 ， 使 以 色 列 中 得 保 全 的 归 回 尚 为 小 事 ， 我 还 要 使 你 作 外 邦 人 的 光 ， 叫 你 施 行 我 的 救 恩 ， 直 到 地 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18644', '23', '49', '7', '救 赎 主 ─ ─ 以 色 列 的 圣 者 耶 和 华 对 那 被 人 所 藐 视 、 本 国 所 憎 恶 、 官 长 所 虐 待 的 如 此 说 ： 君 王 要 看 见 就 站 起 ， 首 领 也 要 下 拜 ； 都 因 信 实 的 耶 和 华 ， 就 是 拣 选 你 ─ ─ 以 色 列 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18645', '23', '49', '8', '＜ 耶 路 撒 冷 的 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18646', '23', '49', '9', '对 那 被 捆 绑 的 人 说 ： 出 来 吧 ！ 对 那 在 黑 暗 的 人 说 ： 显 露 吧 ！ 他 们 在 路 上 必 得 饮 食 ， 在 一 切 净 光 的 高 处 必 有 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18647', '23', '49', '10', '不 饥 不 渴 ， 炎 热 和 烈 日 必 不 伤 害 他 们 ； 因 为 怜 恤 他 们 的 必 引 导 他 们 ， 领 他 们 到 水 泉 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18648', '23', '49', '11', '我 必 使 我 的 众 山 成 为 大 道 ； 我 的 大 路 也 被 修 高 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18649', '23', '49', '12', '看 哪 ， 这 些 从 远 方 来 ； 这 些 从 北 方 、 从 西 方 来 ； 这 些 从 秦 ｛ 原 文 是 希 尼 ｝ 国 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18650', '23', '49', '13', '诸 天 哪 ， 应 当 欢 呼 ！ 大 地 啊 ， 应 当 快 乐 ！ 众 山 哪 ， 应 当 发 声 歌 唱 ！ 因 为 耶 和 华 已 经 安 慰 他 的 百 姓 ， 也 要 怜 恤 他 困 苦 之 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18651', '23', '49', '14', '锡 安 说 ： 耶 和 华 离 弃 了 我 ； 主 忘 记 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18652', '23', '49', '15', '妇 人 焉 能 忘 记 她 吃 奶 的 婴 孩 ， 不 怜 恤 她 所 生 的 儿 子 ？ 即 或 有 忘 记 的 ， 我 却 不 忘 记 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18653', '23', '49', '16', '看 哪 ， 我 将 你 铭 刻 在 我 掌 上 ； 你 的 墙 垣 常 在 我 眼 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18654', '23', '49', '17', '你 的 儿 女 必 急 速 归 回 ； 毁 坏 你 的 ， 使 你 荒 废 的 ， 必 都 离 你 出 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18655', '23', '49', '18', '你 举 目 向 四 方 观 看 ； 他 们 都 聚 集 来 到 你 这 里 。 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ： 你 必 要 以 他 们 为 妆 饰 佩 戴 ， 以 他 们 为 华 带 束 腰 ， 像 新 妇 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18656', '23', '49', '19', '至 于 你 荒 废 凄 凉 之 处 ， 并 你 被 毁 坏 之 地 ， 现 今 众 民 居 住 必 显 为 太 窄 ； 吞 灭 你 的 必 离 你 遥 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18657', '23', '49', '20', '你 必 听 见 丧 子 之 后 所 生 的 儿 女 说 ： 这 地 方 我 居 住 太 窄 ， 求 你 给 我 地 方 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18658', '23', '49', '21', '那 时 你 心 里 必 说 ： 我 既 丧 子 独 居 ， 是 被 掳 的 ， 漂 流 在 外 。 谁 给 我 生 这 些 ？ 谁 将 这 些 养 大 呢 ？ 撇 下 我 一 人 独 居 的 时 候 ， 这 些 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18659', '23', '49', '22', '主 耶 和 华 如 此 说 ： 我 必 向 列 国 举 手 ， 向 万 民 竖 立 大 旗 ； 他 们 必 将 你 的 众 子 怀 中 抱 来 ， 将 你 的 众 女 肩 上 扛 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18660', '23', '49', '23', '列 王 必 作 你 的 养 父 ； 王 后 必 作 你 的 乳 母 。 他 们 必 将 脸 伏 地 ， 向 你 下 拜 ， 并 舔 你 脚 上 的 尘 土 。 你 便 知 道 我 是 耶 和 华 ； 等 候 我 的 必 不 致 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18661', '23', '49', '24', '勇 士 抢 去 的 岂 能 夺 回 ？ 该 掳 掠 的 岂 能 解 救 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18662', '23', '49', '25', '但 耶 和 华 如 此 说 ： 就 是 勇 士 所 掳 掠 的 ， 也 可 以 夺 回 ； 强 暴 人 所 抢 的 ， 也 可 以 解 救 。 与 你 相 争 的 ， 我 必 与 他 相 争 ； 我 要 拯 救 你 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18663', '23', '49', '26', '并 且 我 必 使 那 欺 压 你 的 吃 自 己 的 肉 ， 也 要 以 自 己 的 血 喝 醉 ， 好 像 喝 甜 酒 一 样 。 凡 有 血 气 的 必 都 知 道 我 ─ ─ 耶 和 华 是 你 的 救 主 ， 是 你 的 救 赎 主 ， 是 雅 各 的 大 能 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18664', '23', '50', '1', '耶 和 华 如 此 说 ： 我 休 你 们 的 母 亲 ， 休 书 在 哪 里 呢 ？ 我 将 你 们 卖 给 我 哪 一 个 债 主 呢 ？ 你 们 被 卖 ， 是 因 你 们 的 罪 孽 ； 你 们 的 母 亲 被 休 ， 是 因 你 们 的 过 犯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18665', '23', '50', '2', '我 来 的 时 候 ， 为 何 无 人 等 候 呢 ？ 我 呼 唤 的 时 候 ， 为 何 无 人 答 应 呢 ？ 我 的 膀 臂 岂 是 缩 短 、 不 能 救 赎 吗 ？ 我 岂 无 拯 救 之 力 吗 ？ 看 哪 ， 我 一 斥 责 ， 海 就 干 了 ； 我 使 江 河 变 为 旷 野 ； 其 中 的 鱼 因 无 水 腥 臭 ， 干 渴 而 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18666', '23', '50', '3', '我 使 诸 天 以 黑 暗 为 衣 服 ， 以 麻 布 为 遮 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18667', '23', '50', '4', '＜ 耶 和 华 仆 人 的 顺 服 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18668', '23', '50', '5', '主 耶 和 华 开 通 我 的 耳 朵 ； 我 并 没 有 违 背 ， 也 没 有 退 后 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18669', '23', '50', '6', '人 打 我 的 背 ， 我 任 他 打 ； 人 拔 我 腮 颊 的 胡 须 ， 我 由 他 拔 ； 人 辱 我 ， 吐 我 ， 我 并 不 掩 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18670', '23', '50', '7', '主 耶 和 华 必 帮 助 我 ， 所 以 我 不 抱 愧 。 我 硬 着 脸 面 好 像 坚 石 ； 我 也 知 道 我 必 不 致 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18671', '23', '50', '8', '称 我 为 义 的 与 我 相 近 ； 谁 与 我 争 论 ， 可 以 与 我 一 同 站 立 ； 谁 与 我 作 对 ， 可 以 就 近 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18672', '23', '50', '9', '主 耶 和 华 要 帮 助 我 ； 谁 能 定 我 有 罪 呢 ？ 他 们 都 像 衣 服 渐 渐 旧 了 ， 为 蛀 虫 所 咬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18673', '23', '50', '10', '你 们 中 间 谁 是 敬 畏 耶 和 华 、 听 从 他 仆 人 之 话 的 ？ 这 人 行 在 暗 中 ， 没 有 亮 光 。 当 倚 靠 耶 和 华 的 名 ， 仗 赖 自 己 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18674', '23', '50', '11', '凡 你 们 点 火 ， 用 火 把 围 绕 自 己 的 可 以 行 在 你 们 的 火 焰 里 ， 并 你 们 所 点 的 火 把 中 。 这 是 我 手 所 定 的 ： 你 们 必 躺 在 悲 惨 之 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18675', '23', '51', '1', '＜ 安 慰 耶 路 撒 冷 的 话 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18676', '23', '51', '2', '要 追 想 你 们 的 祖 宗 亚 伯 拉 罕 和 生 养 你 们 的 撒 拉 ； 因 为 亚 伯 拉 罕 独 自 一 人 的 时 候 ， 我 选 召 他 ， 赐 福 与 他 ， 使 他 人 数 增 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18677', '23', '51', '3', '耶 和 华 已 经 安 慰 锡 安 和 锡 安 一 切 的 荒 场 ， 使 旷 野 像 伊 甸 ， 使 沙 漠 像 耶 和 华 的 园 囿 ； 在 其 中 必 有 欢 喜 、 快 乐 、 感 谢 ， 和 歌 唱 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18678', '23', '51', '4', '我 的 百 姓 啊 ， 要 向 我 留 心 ； 我 的 国 民 哪 ， 要 向 我 侧 耳 ； 因 为 训 诲 必 从 我 而 出 ； 我 必 坚 定 我 的 公 理 为 万 民 之 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18679', '23', '51', '5', '我 的 公 义 临 近 ； 我 的 救 恩 发 出 。 我 的 膀 臂 要 审 判 万 民 ； 海 岛 都 要 等 候 我 ， 倚 赖 我 的 膀 臂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18680', '23', '51', '6', '你 们 要 向 天 举 目 ， 观 看 下 地 ； 因 为 天 必 像 烟 云 消 散 ， 地 必 如 衣 服 渐 渐 旧 了 ； 其 上 的 居 民 也 要 如 此 死 亡 ｛ 如 此 死 亡 ： 或 译 像 蠓 虫 死 亡 ｝ 。 惟 有 我 的 救 恩 永 远 长 存 ； 我 的 公 义 也 不 废 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18681', '23', '51', '7', '知 道 公 义 、 将 我 训 诲 存 在 心 中 的 民 ， 要 听 我 言 ！ 不 要 怕 人 的 辱 骂 ， 也 不 要 因 人 的 毁 谤 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18682', '23', '51', '8', '因 为 蛀 虫 必 咬 他 们 ， 好 像 咬 衣 服 ； 虫 子 必 咬 他 们 ， 如 同 咬 羊 绒 。 惟 有 我 的 公 义 永 远 长 存 ， 我 的 救 恩 直 到 万 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18683', '23', '51', '9', '耶 和 华 的 膀 臂 啊 ， 兴 起 ！ 兴 起 ！ 以 能 力 为 衣 穿 上 ， 像 古 时 的 年 日 、 上 古 的 世 代 兴 起 一 样 。 从 前 砍 碎 拉 哈 伯 、 刺 透 大 鱼 的 ， 不 是 你 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18684', '23', '51', '10', '使 海 与 深 渊 的 水 干 涸 、 使 海 的 深 处 变 为 赎 民 经 过 之 路 的 ， 不 是 你 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18685', '23', '51', '11', '耶 和 华 救 赎 的 民 必 归 回 ， 歌 唱 来 到 锡 安 ； 永 乐 必 归 到 他 们 的 头 上 。 他 们 必 得 着 欢 喜 快 乐 ； 忧 愁 叹 息 尽 都 逃 避 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18686', '23', '51', '12', '惟 有 我 ， 是 安 慰 你 们 的 。 你 是 谁 ， 竟 怕 那 必 死 的 人 ？ 怕 那 要 变 如 草 的 世 人 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18687', '23', '51', '13', '却 忘 记 铺 张 诸 天 、 立 定 地 基 、 创 造 你 的 耶 和 华 ？ 又 因 欺 压 者 图 谋 毁 灭 要 发 的 暴 怒 ， 整 天 害 怕 ， 其 实 那 欺 压 者 的 暴 怒 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18688', '23', '51', '14', '被 掳 去 的 快 得 释 放 ， 必 不 死 而 下 坑 ； 他 的 食 物 也 不 致 缺 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18689', '23', '51', '15', '我 是 耶 和 华 ─ ─ 你 的 神 ─ ─ 搅 动 大 海 ， 使 海 中 的 波 浪 匉 訇 ─ ─ 万 军 之 耶 和 华 是 我 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18690', '23', '51', '16', '我 将 我 的 话 传 给 你 ， 用 我 的 手 影 遮 蔽 你 ， 为 要 栽 定 诸 天 ， 立 定 地 基 ， 又 对 锡 安 说 ： 你 是 我 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18691', '23', '51', '17', '＜ 耶 路 撒 冷 苦 难 的 终 结 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18692', '23', '51', '18', '她 所 生 育 的 诸 子 中 ， 没 有 一 个 引 导 她 的 ； 她 所 养 大 的 诸 子 中 ， 没 有 一 个 搀 扶 她 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18693', '23', '51', '19', '荒 凉 、 毁 灭 、 饥 荒 、 刀 兵 ， 这 几 样 临 到 你 ， 谁 为 你 举 哀 ？ 我 如 何 能 安 慰 你 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18694', '23', '51', '20', '你 的 众 子 发 昏 ， 在 各 市 口 上 躺 卧 ， 好 像 黄 羊 在 网 罗 之 中 ， 都 满 了 耶 和 华 的 忿 怒 ─ ─ 你 神 的 斥 责 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18695', '23', '51', '21', '因 此 ， 你 这 困 苦 却 非 因 酒 而 醉 的 ， 要 听 我 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18696', '23', '51', '22', '你 的 主 耶 和 华 ─ ─ 就 是 为 他 百 姓 辨 屈 的 神 如 此 说 ： 看 哪 ， 我 已 将 那 使 人 东 倒 西 歪 的 杯 ， 就 是 我 忿 怒 的 爵 ， 从 你 手 中 接 过 来 ； 你 必 不 致 再 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18697', '23', '51', '23', '我 必 将 这 杯 递 在 苦 待 你 的 人 手 中 ； 他 们 曾 对 你 说 ： 你 屈 身 ， 由 我 们 践 踏 过 去 吧 ！ 你 便 以 背 为 地 ， 好 像 街 市 ， 任 人 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18698', '23', '52', '1', '＜ 神 要 拯 救 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18699', '23', '52', '2', '耶 路 撒 冷 啊 ， 要 抖 下 尘 土 ！ 起 来 坐 在 位 上 ！ 锡 安 被 掳 的 居 民 ｛ 原 文 是 女 子 ｝ 哪 ， 要 解 开 你 颈 项 的 锁 炼 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18700', '23', '52', '3', '耶 和 华 如 此 说 ： “ 你 们 是 无 价 被 卖 的 ， 也 必 无 银 被 赎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18701', '23', '52', '4', '主 耶 和 华 如 此 说 ： 起 先 我 的 百 姓 下 到 埃 及 ， 在 那 里 寄 居 ， 又 有 亚 述 人 无 故 欺 压 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18702', '23', '52', '5', '耶 和 华 说 ： 我 的 百 姓 既 是 无 价 被 掳 去 ， 如 今 我 在 这 里 做 什 么 呢 ？ 耶 和 华 说 ： 辖 制 他 们 的 人 呼 叫 ， 我 的 名 整 天 受 亵 渎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18703', '23', '52', '6', '所 以 ， 我 的 百 姓 必 知 道 我 的 名 ； 到 那 日 他 们 必 知 道 说 这 话 的 就 是 我 。 看 哪 ， 是 我 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18704', '23', '52', '7', '那 报 佳 音 ， 传 平 安 ， 报 好 信 ， 传 救 恩 的 ， 对 锡 安 说 ： 你 的 神 作 王 了 ！ 这 人 的 脚 登 山 何 等 佳 美 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18705', '23', '52', '8', '听 啊 ， 你 守 望 之 人 的 声 音 ， 他 们 扬 起 声 来 ， 一 同 歌 唱 ； 因 为 耶 和 华 归 回 锡 安 的 时 候 ， 他 们 必 亲 眼 看 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18706', '23', '52', '9', '耶 路 撒 冷 的 荒 场 啊 ， 要 发 起 欢 声 ， 一 同 歌 唱 ； 因 为 耶 和 华 安 慰 了 他 的 百 姓 ， 救 赎 了 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18707', '23', '52', '10', '耶 和 华 在 万 国 眼 前 露 出 圣 臂 ； 地 极 的 人 都 看 见 我 们 神 的 救 恩 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18708', '23', '52', '11', '你 们 离 开 吧 ！ 离 开 吧 ！ 从 巴 比 伦 出 来 。 不 要 沾 不 洁 净 的 物 ； 要 从 其 中 出 来 。 你 们 扛 抬 耶 和 华 器 皿 的 人 哪 ， 务 要 自 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18709', '23', '52', '12', '你 们 出 来 必 不 致 急 忙 ， 也 不 致 奔 逃 。 因 为 ， 耶 和 华 必 在 你 们 前 头 行 ； 以 色 列 的 神 必 作 你 们 的 后 盾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18710', '23', '52', '13', '＜ 受 苦 的 仆 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18711', '23', '52', '14', '许 多 人 因 他 ｛ 原 文 是 你 ｝ 惊 奇 ； 他 的 面 貌 比 别 人 憔 悴 ； 他 的 形 容 比 世 人 枯 槁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18712', '23', '52', '15', '这 样 ， 他 必 洗 净 ｛ 或 译 ： 鼓 动 ｝ 许 多 国 民 ； 君 王 要 向 他 闭 口 。 因 所 未 曾 传 与 他 们 的 ， 他 们 必 看 见 ； 未 曾 听 见 的 ， 他 们 要 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18713', '23', '53', '1', '我 们 所 传 的 ｛ 或 译 ： 所 传 与 我 们 的 ｝ 有 谁 信 呢 ？ 耶 和 华 的 膀 臂 向 谁 显 露 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18714', '23', '53', '2', '他 在 耶 和 华 面 前 生 长 如 嫩 芽 ， 像 根 出 于 干 地 。 他 无 佳 形 美 容 ； 我 们 看 见 他 的 时 候 ， 也 无 美 貌 使 我 们 羡 慕 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18715', '23', '53', '3', '他 被 藐 视 ， 被 人 厌 弃 ； 多 受 痛 苦 ， 常 经 忧 患 。 他 被 藐 视 ， 好 像 被 人 掩 面 不 看 的 一 样 ； 我 们 也 不 尊 重 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18716', '23', '53', '4', '他 诚 然 担 当 我 们 的 忧 患 ， 背 负 我 们 的 痛 苦 ； 我 们 却 以 为 他 受 责 罚 ， 被 神 击 打 苦 待 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18717', '23', '53', '5', '哪 知 他 为 我 们 的 过 犯 受 害 ， 为 我 们 的 罪 孽 压 伤 。 因 他 受 的 刑 罚 ， 我 们 得 平 安 ； 因 他 受 的 鞭 伤 ， 我 们 得 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18718', '23', '53', '6', '我 们 都 如 羊 走 迷 ； 各 人 偏 行 己 路 ； 耶 和 华 使 我 们 众 人 的 罪 孽 都 归 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18719', '23', '53', '7', '他 被 欺 压 ， 在 受 苦 的 时 候 却 不 开 口 ｛ 或 译 ： 他 受 欺 压 ， 却 自 卑 不 开 口 ｝ ； 他 像 羊 羔 被 牵 到 宰 杀 之 地 ， 又 像 羊 在 剪 毛 的 人 手 下 无 声 ， 他 也 是 这 样 不 开 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18720', '23', '53', '8', '因 受 欺 压 和 审 判 ， 他 被 夺 去 ， 至 于 他 同 世 的 人 ， 谁 想 他 受 鞭 打 、 从 活 人 之 地 被 剪 除 ， 是 因 我 百 姓 的 罪 过 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18721', '23', '53', '9', '他 虽 然 未 行 强 暴 ， 口 中 也 没 有 诡 诈 ， 人 还 使 他 与 恶 人 同 埋 ； 谁 知 死 的 时 候 与 财 主 同 葬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18722', '23', '53', '10', '耶 和 华 却 定 意 ｛ 或 译 ： 喜 悦 ｝ 将 他 压 伤 ， 使 他 受 痛 苦 。 耶 和 华 以 他 为 赎 罪 祭 ｛ 或 译 ： 他 献 本 身 为 赎 罪 祭 ｝ 。 他 必 看 见 后 裔 ， 并 且 延 长 年 日 。 耶 和 华 所 喜 悦 的 事 必 在 他 手 中 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18723', '23', '53', '11', '他 必 看 见 自 己 劳 苦 的 功 效 ， 便 心 满 意 足 。 有 许 多 人 因 认 识 我 的 义 仆 得 称 为 义 ； 并 且 他 要 担 当 他 们 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18724', '23', '53', '12', '所 以 ， 我 要 使 他 与 位 大 的 同 分 ， 与 强 盛 的 均 分 掳 物 。 因 为 他 将 命 倾 倒 ， 以 致 于 死 ； 他 也 被 列 在 罪 犯 之 中 。 他 却 担 当 多 人 的 罪 ， 又 为 罪 犯 代 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18725', '23', '54', '1', '＜ 耶 和 华 对 以 色 列 的 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18726', '23', '54', '2', '要 扩 张 你 帐 幕 之 地 ， 张 大 你 居 所 的 幔 子 ， 不 要 限 止 ； 要 放 长 你 的 绳 子 ， 坚 固 你 的 橛 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18727', '23', '54', '3', '因 为 你 要 向 左 向 右 开 展 ； 你 的 后 裔 必 得 多 国 为 业 ， 又 使 荒 凉 的 城 邑 有 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18728', '23', '54', '4', '不 要 惧 怕 ， 因 你 必 不 致 蒙 羞 ； 也 不 要 抱 愧 ， 因 你 必 不 致 受 辱 。 你 必 忘 记 幼 年 的 羞 愧 ， 不 再 记 念 你 寡 居 的 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18729', '23', '54', '5', '因 为 造 你 的 是 你 的 丈 夫 ； 万 军 之 耶 和 华 是 他 的 名 。 救 赎 你 的 是 以 色 列 的 圣 者 ； 他 必 称 为 全 地 之 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18730', '23', '54', '6', '耶 和 华 召 你 ， 如 召 被 离 弃 心 中 忧 伤 的 妻 ， 就 是 幼 年 所 娶 被 弃 的 妻 。 这 是 你 神 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18731', '23', '54', '7', '我 离 弃 你 不 过 片 时 ， 却 要 施 大 恩 将 你 收 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18732', '23', '54', '8', '我 的 怒 气 涨 溢 ， 顷 刻 之 间 向 你 掩 面 ， 却 要 以 永 远 的 慈 爱 怜 恤 你 。 这 是 耶 和 华 ─ ─ 你 的 救 赎 主 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18733', '23', '54', '9', '这 事 在 我 好 像 挪 亚 的 洪 水 。 我 怎 样 起 誓 不 再 使 挪 亚 的 洪 水 漫 过 遍 地 ， 我 也 照 样 起 誓 不 再 向 你 发 怒 ， 也 不 斥 责 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18734', '23', '54', '10', '大 山 可 以 挪 开 ， 小 山 可 以 迁 移 ； 但 我 的 慈 爱 必 不 离 开 你 ； 我 平 安 的 约 也 不 迁 移 。 这 是 怜 恤 你 的 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18735', '23', '54', '11', '＜ 耶 路 撒 冷 的 将 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18736', '23', '54', '12', '又 以 红 宝 石 造 你 的 女 墙 ， 以 红 玉 造 你 的 城 门 ， 以 宝 石 造 你 四 围 的 边 界 ｛ 或 译 ： 外 郭 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18737', '23', '54', '13', '你 的 儿 女 都 要 受 耶 和 华 的 教 训 ； 你 的 儿 女 必 大 享 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18738', '23', '54', '14', '你 必 因 公 义 得 坚 立 ， 必 远 离 欺 压 ， 不 致 害 怕 ； 你 必 远 离 惊 吓 ， 惊 吓 必 不 临 近 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18739', '23', '54', '15', '即 或 有 人 聚 集 ， 却 不 由 于 我 ； 凡 聚 集 攻 击 你 的 ， 必 因 你 仆 倒 ｛ 或 译 ： 投 降 你 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18740', '23', '54', '16', '吹 嘘 炭 火 、 打 造 合 用 器 械 的 铁 匠 是 我 所 造 ； 残 害 人 、 行 毁 灭 的 也 是 我 所 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18741', '23', '54', '17', '凡 为 攻 击 你 造 成 的 器 械 必 不 利 用 ； 凡 在 审 判 时 兴 起 用 舌 攻 击 你 的 ， 你 必 定 他 为 有 罪 。 这 是 耶 和 华 仆 人 的 产 业 ， 是 他 们 从 我 所 得 的 义 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18742', '23', '55', '1', '＜ 神 要 施 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18743', '23', '55', '2', '你 们 为 何 花 钱 ｛ 原 文 是 平 银 ｝ 买 那 不 足 为 食 物 的 ？ 用 劳 碌 得 来 的 买 那 不 使 人 饱 足 的 呢 ？ 你 们 要 留 意 听 我 的 话 就 能 吃 那 美 物 ， 得 享 肥 甘 ， 心 中 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18744', '23', '55', '3', '你 们 当 就 近 我 来 ； 侧 耳 而 听 ， 就 必 得 活 。 我 必 与 你 们 立 永 约 ， 就 是 应 许 大 卫 那 可 靠 的 恩 典 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18745', '23', '55', '4', '我 已 立 他 作 万 民 的 见 证 ， 为 万 民 的 君 王 和 司 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18746', '23', '55', '5', '你 素 不 认 识 的 国 民 ， 你 也 必 召 来 ； 素 不 认 识 你 的 国 民 也 必 向 你 奔 跑 ， 都 因 耶 和 华 ─ ─ 你 的 神 以 色 列 的 圣 者 ， 因 为 他 已 经 荣 耀 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18747', '23', '55', '6', '当 趁 耶 和 华 可 寻 找 的 时 候 寻 找 他 ， 相 近 的 时 候 求 告 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18748', '23', '55', '7', '恶 人 当 离 弃 自 己 的 道 路 ； 不 义 的 人 当 除 掉 自 己 的 意 念 。 归 向 耶 和 华 ， 耶 和 华 就 必 怜 恤 他 ； 当 归 向 我 们 的 神 ， 因 为 神 必 广 行 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18749', '23', '55', '8', '耶 和 华 说 ： 我 的 意 念 非 同 你 们 的 意 念 ； 我 的 道 路 非 同 你 们 的 道 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18750', '23', '55', '9', '天 怎 样 高 过 地 ， 照 样 ， 我 的 道 路 高 过 你 们 的 道 路 ； 我 的 意 念 高 过 你 们 的 意 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18751', '23', '55', '10', '雨 雪 从 天 而 降 ， 并 不 返 回 ， 却 滋 润 地 土 ， 使 地 上 发 芽 结 实 ， 使 撒 种 的 有 种 ， 使 要 吃 的 有 粮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18752', '23', '55', '11', '我 口 所 出 的 话 也 必 如 此 ， 决 不 徒 然 返 回 ， 却 要 成 就 我 所 喜 悦 的 ， 在 我 发 他 去 成 就 ｛ 发 他 去 成 就 ： 或 译 所 命 定 ｝ 的 事 上 必 然 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18753', '23', '55', '12', '你 们 必 欢 欢 喜 喜 而 出 来 ， 平 平 安 安 蒙 引 导 。 大 山 小 山 必 在 你 们 面 前 发 声 歌 唱 ； 田 野 的 树 木 也 都 拍 掌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18754', '23', '55', '13', '松 树 长 出 ， 代 替 荆 棘 ； 番 石 榴 长 出 ， 代 替 蒺 藜 。 这 要 为 耶 和 华 留 名 ， 作 为 永 远 的 证 据 ， 不 能 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18755', '23', '56', '1', '＜ 神 的 子 民 将 包 括 各 国 的 人 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18756', '23', '56', '2', '谨 守 安 息 日 而 不 干 犯 ， 禁 止 己 手 而 不 作 恶 ； 如 此 行 、 如 此 持 守 的 人 便 为 有 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18757', '23', '56', '3', '与 耶 和 华 联 合 的 外 邦 人 不 要 说 ： 耶 和 华 必 定 将 我 从 他 民 中 分 别 出 来 。 太 监 也 不 要 说 ： 我 是 枯 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18758', '23', '56', '4', '因 为 耶 和 华 如 此 说 ： 那 些 谨 守 我 的 安 息 日 ， 拣 选 我 所 喜 悦 的 事 ， 持 守 我 约 的 太 监 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18759', '23', '56', '5', '我 必 使 他 们 在 我 殿 中 ， 在 我 墙 内 ， 有 记 念 ， 有 名 号 ， 比 有 儿 女 的 更 美 。 我 必 赐 他 们 永 远 的 名 ， 不 能 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18760', '23', '56', '6', '还 有 那 些 与 耶 和 华 联 合 的 外 邦 人 ， 要 事 奉 他 ， 要 爱 耶 和 华 的 名 ， 要 作 他 的 仆 人 ─ ─ 就 是 凡 守 安 息 日 不 干 犯 ， 又 持 守 他 ｛ 原 文 是 我 ｝ 约 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18761', '23', '56', '7', '我 必 领 他 们 到 我 的 圣 山 ， 使 他 们 在 祷 告 我 的 殿 中 喜 乐 。 他 们 的 燔 祭 和 平 安 祭 ， 在 我 坛 上 必 蒙 悦 纳 ， 因 我 的 殿 必 称 为 万 民 祷 告 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18762', '23', '56', '8', '主 耶 和 华 ， 就 是 招 聚 以 色 列 被 赶 散 的 ， 说 ： 在 这 被 招 聚 的 人 以 外 ， 我 还 要 招 聚 别 人 归 并 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18763', '23', '56', '9', '＜ 以 色 列 的 领 袖 被 定 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18764', '23', '56', '10', '他 看 守 的 人 是 瞎 眼 的 ， 都 没 有 知 识 ， 都 是 哑 巴 狗 ， 不 能 叫 唤 ； 但 知 做 梦 ， 躺 卧 ， 贪 睡 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18765', '23', '56', '11', '这 些 狗 贪 食 ， 不 知 饱 足 。 这 些 牧 人 不 能 明 白 ─ ─ 各 人 偏 行 己 路 ， 各 从 各 方 求 自 己 的 利 益 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18766', '23', '56', '12', '他 们 说 ： 来 吧 ！ 我 去 拿 酒 ， 我 们 饱 饮 浓 酒 ； 明 日 必 和 今 日 一 样 ， 就 是 宴 乐 无 量 极 大 之 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18767', '23', '57', '1', '＜ 以 色 列 拜 偶 像 被 定 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18768', '23', '57', '2', '他 们 得 享 ｛ 原 文 是 进 入 ｝ 平 安 。 素 行 正 直 的 ， 各 人 在 坟 里 ｛ 原 文 是 床 上 ｝ 安 歇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18769', '23', '57', '3', '你 们 这 些 巫 婆 的 儿 子 ， 奸 夫 和 妓 女 的 种 子 ， 都 要 前 来 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18770', '23', '57', '4', '你 们 向 谁 戏 笑 ？ 向 谁 张 口 吐 舌 呢 ？ 你 们 岂 不 是 悖 逆 的 儿 女 ， 虚 谎 的 种 类 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18771', '23', '57', '5', '你 们 在 橡 树 中 间 ， 在 各 青 翠 树 下 欲 火 攻 心 ； 在 山 谷 间 ， 在 石 穴 下 杀 了 儿 女 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18772', '23', '57', '6', '在 谷 中 光 滑 石 头 里 有 你 的 分 。 这 些 就 是 你 所 得 的 分 ； 你 也 向 他 浇 了 奠 祭 ， 献 了 供 物 ， 因 这 事 我 岂 能 容 忍 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18773', '23', '57', '7', '你 在 高 而 又 高 的 山 上 安 设 床 榻 ， 也 上 那 里 去 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18774', '23', '57', '8', '你 在 门 后 ， 在 门 框 后 ， 立 起 你 的 纪 念 ； 向 外 人 赤 露 ， 又 上 去 扩 张 床 榻 ， 与 他 们 立 约 ； 你 在 那 里 看 见 他 们 的 床 就 甚 喜 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18775', '23', '57', '9', '你 把 油 带 到 王 那 里 ， 又 多 加 香 料 ， 打 发 使 者 往 远 方 去 ， 自 卑 自 贱 直 到 阴 间 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18776', '23', '57', '10', '你 因 路 远 疲 倦 ， 却 不 说 这 是 枉 然 ； 你 以 为 有 复 兴 之 力 ， 所 以 不 觉 疲 惫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18777', '23', '57', '11', '你 怕 谁 ？ 因 谁 恐 惧 ？ 竟 说 谎 ， 不 记 念 我 ， 又 不 将 这 事 放 在 心 上 。 我 不 是 许 久 闭 口 不 言 ， 你 仍 不 怕 我 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18778', '23', '57', '12', '我 要 指 明 你 的 公 义 ； 至 于 你 所 行 的 都 必 与 你 无 益 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18779', '23', '57', '13', '你 哀 求 的 时 候 ， 让 你 所 聚 集 的 拯 救 你 吧 ！ 风 要 把 他 们 刮 散 ， 一 口 气 要 把 他 们 都 吹 去 。 但 那 投 靠 我 的 必 得 地 土 ， 必 承 受 我 的 圣 山 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18780', '23', '57', '14', '＜ 神 应 许 帮 助 和 医 治 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18781', '23', '57', '15', '因 为 那 至 高 至 上 、 永 远 长 存 ｛ 原 文 是 住 在 永 远 ｝ 名 为 圣 者 的 如 此 说 ： 我 住 在 至 高 至 圣 的 所 在 ， 也 与 心 灵 痛 悔 谦 卑 的 人 同 居 ； 要 使 谦 卑 人 的 灵 苏 醒 ， 也 使 痛 悔 人 的 心 苏 醒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18782', '23', '57', '16', '我 必 不 永 远 相 争 ， 也 不 长 久 发 怒 ， 恐 怕 我 所 造 的 人 与 灵 性 都 必 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18783', '23', '57', '17', '因 他 贪 婪 的 罪 孽 ， 我 就 发 怒 击 打 他 ； 我 向 他 掩 面 发 怒 ， 他 却 仍 然 随 心 背 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18784', '23', '57', '18', '我 看 见 他 所 行 的 道 ， 也 要 医 治 他 ； 又 要 引 导 他 ， 使 他 和 那 一 同 伤 心 的 人 再 得 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18785', '23', '57', '19', '我 造 就 嘴 唇 的 果 子 ； 愿 平 安 康 泰 归 与 远 处 的 人 ， 也 归 与 近 处 的 人 ； 并 且 我 要 医 治 他 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18786', '23', '57', '20', '惟 独 恶 人 ， 好 像 翻 腾 的 海 ， 不 得 平 静 ； 其 中 的 水 常 涌 出 污 秽 和 淤 泥 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18787', '23', '57', '21', '我 的 神 说 ： 恶 人 必 不 得 平 安 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18788', '23', '58', '1', '＜ 真 正 的 禁 食 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18789', '23', '58', '2', '他 们 天 天 寻 求 我 ， 乐 意 明 白 我 的 道 ， 好 像 行 义 的 国 民 ， 不 离 弃 他 们 神 的 典 章 ， 向 我 求 问 公 义 的 判 语 ， 喜 悦 亲 近 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18790', '23', '58', '3', '他 们 说 ： 我 们 禁 食 ， 你 为 何 不 看 见 呢 ？ 我 们 刻 苦 己 心 ， 你 为 何 不 理 会 呢 ？ 看 哪 ， 你 们 禁 食 的 日 子 仍 求 利 益 ， 勒 逼 人 为 你 们 做 苦 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18791', '23', '58', '4', '你 们 禁 食 ， 却 互 相 争 竞 ， 以 凶 恶 的 拳 头 打 人 。 你 们 今 日 禁 食 ， 不 得 使 你 们 的 声 音 听 闻 于 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18792', '23', '58', '5', '这 样 禁 食 岂 是 我 所 拣 选 、 使 人 刻 苦 己 心 的 日 子 吗 ？ 岂 是 叫 人 垂 头 像 苇 子 ， 用 麻 布 和 炉 灰 铺 在 他 以 下 吗 ？ 你 这 可 称 为 禁 食 、 为 耶 和 华 所 悦 纳 的 日 子 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18793', '23', '58', '6', '我 所 拣 选 的 禁 食 不 是 要 松 开 凶 恶 的 绳 ， 解 下 轭 上 的 索 ， 使 被 欺 压 的 得 自 由 ， 折 断 一 切 的 轭 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18794', '23', '58', '7', '不 是 要 把 你 的 饼 分 给 饥 饿 的 人 ， 将 飘 流 的 穷 人 接 到 你 家 中 ， 见 赤 身 的 给 他 衣 服 遮 体 ， 顾 恤 自 己 的 骨 肉 而 不 掩 藏 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18795', '23', '58', '8', '这 样 ， 你 的 光 就 必 发 现 如 早 晨 的 光 ； 你 所 得 的 医 治 要 速 速 发 明 。 你 的 公 义 必 在 你 前 面 行 ； 耶 和 华 的 荣 光 必 作 你 的 后 盾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18796', '23', '58', '9', '那 时 你 求 告 ， 耶 和 华 必 应 允 ； 你 呼 求 ， 他 必 说 ： 我 在 这 里 。 你 若 从 你 中 间 除 掉 重 轭 和 指 摘 人 的 指 头 ， 并 发 恶 言 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18797', '23', '58', '10', '你 心 若 向 饥 饿 的 人 发 怜 悯 ， 使 困 苦 的 人 得 满 足 ， 你 的 光 就 必 在 黑 暗 中 发 现 ； 你 的 幽 暗 必 变 如 正 午 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18798', '23', '58', '11', '耶 和 华 也 必 时 常 引 导 你 ， 在 干 旱 之 地 使 你 心 满 意 足 ， 骨 头 强 壮 。 你 必 像 浇 灌 的 园 子 ， 又 像 水 流 不 绝 的 泉 源 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18799', '23', '58', '12', '那 些 出 于 你 的 人 必 修 造 久 已 荒 废 之 处 ； 你 要 建 立 拆 毁 累 代 的 根 基 。 你 必 称 为 补 破 口 的 ， 和 重 修 路 径 与 人 居 住 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18800', '23', '58', '13', '＜ 守 安 息 日 的 报 赏 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18801', '23', '58', '14', '你 就 以 耶 和 华 为 乐 。 耶 和 华 要 使 你 乘 驾 地 的 高 处 ， 又 以 你 祖 雅 各 的 产 业 养 育 你 。 这 是 耶 和 华 亲 口 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18802', '23', '59', '1', '＜ 先 知 指 责 人 民 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18803', '23', '59', '2', '但 你 们 的 罪 孽 使 你 们 与 神 隔 绝 ； 你 们 的 罪 恶 使 他 掩 面 不 听 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18804', '23', '59', '3', '因 你 们 的 手 被 血 沾 染 ， 你 们 的 指 头 被 罪 孽 沾 污 ， 你 们 的 嘴 唇 说 谎 言 ， 你 们 的 舌 头 出 恶 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18805', '23', '59', '4', '无 一 人 按 公 义 告 状 ， 无 一 人 凭 诚 实 辩 白 ； 都 倚 靠 虚 妄 ， 说 谎 言 。 所 怀 的 是 毒 害 ； 所 生 的 是 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18806', '23', '59', '5', '他 们 菢 毒 蛇 蛋 ， 结 蜘 蛛 网 ； 人 吃 这 蛋 必 死 。 这 蛋 被 踏 ， 必 出 蝮 蛇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18807', '23', '59', '6', '所 结 的 网 不 能 成 为 衣 服 ； 所 做 的 也 不 能 遮 盖 自 己 。 他 们 的 行 为 都 是 罪 孽 ； 手 所 做 的 都 是 强 暴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18808', '23', '59', '7', '他 们 的 脚 奔 跑 行 恶 ； 他 们 急 速 流 无 辜 人 的 血 ； 意 念 都 是 罪 孽 ， 所 经 过 的 路 都 荒 凉 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18809', '23', '59', '8', '平 安 的 路 ， 他 们 不 知 道 ； 所 行 的 事 没 有 公 平 。 他 们 为 自 己 修 弯 曲 的 路 ； 凡 行 此 路 的 都 不 知 道 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18810', '23', '59', '9', '＜ 人 民 悔 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18811', '23', '59', '10', '我 们 摸 索 墙 壁 ， 好 像 瞎 子 ； 我 们 摸 索 ， 如 同 无 目 之 人 。 我 们 晌 午 绊 脚 ， 如 在 黄 昏 一 样 ； 我 们 在 肥 壮 人 中 ， 像 死 人 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18812', '23', '59', '11', '我 们 咆 哮 如 熊 ， 哀 鸣 如 鸽 ； 指 望 公 平 ， 却 是 没 有 ； 指 望 救 恩 ， 却 远 离 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18813', '23', '59', '12', '我 们 的 过 犯 在 你 面 前 增 多 ， 罪 恶 作 见 证 告 我 们 ； 过 犯 与 我 们 同 在 。 至 于 我 们 的 罪 孽 ， 我 们 都 知 道 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18814', '23', '59', '13', '就 是 悖 逆 、 不 认 识 耶 和 华 ， 转 去 不 跟 从 我 们 的 神 ， 说 欺 压 和 叛 逆 的 话 ， 心 怀 谎 言 ， 随 即 说 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18815', '23', '59', '14', '并 且 公 平 转 而 退 后 ， 公 义 站 在 远 处 ； 诚 实 在 街 上 仆 倒 ， 正 直 也 不 得 进 入 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18816', '23', '59', '15', '诚 实 少 见 ； 离 恶 的 人 反 成 掠 物 。 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18817', '23', '59', '16', '他 见 无 人 拯 救 ， 无 人 代 求 ， 甚 为 诧 异 ， 就 用 自 己 的 膀 臂 施 行 拯 救 ， 以 公 义 扶 持 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18818', '23', '59', '17', '他 以 公 义 为 铠 甲 ｛ 或 译 ： 护 心 镜 ｝ ， 以 拯 救 为 头 盔 ， 以 报 仇 为 衣 服 ， 以 热 心 为 外 袍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18819', '23', '59', '18', '他 必 按 人 的 行 为 施 报 ， 恼 怒 他 的 敌 人 ， 报 复 他 的 仇 敌 ， 向 众 海 岛 施 行 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18820', '23', '59', '19', '如 此 ， 人 从 日 落 之 处 必 敬 畏 耶 和 华 的 名 ， 从 日 出 之 地 也 必 敬 畏 他 的 荣 耀 ； 因 为 仇 敌 好 像 急 流 的 河 水 冲 来 ， 是 耶 和 华 之 气 所 驱 逐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18821', '23', '59', '20', '必 有 一 位 救 赎 主 来 到 锡 安 ─ ─ 雅 各 族 中 转 离 过 犯 的 人 那 里 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18822', '23', '59', '21', '耶 和 华 说 ： “ 至 于 我 与 他 们 所 立 的 约 乃 是 这 样 ： 我 加 给 你 的 灵 ， 传 给 你 的 话 ， 必 不 离 你 的 口 ， 也 不 离 你 后 裔 与 你 后 裔 之 后 裔 的 口 ， 从 今 直 到 永 远 ； 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18823', '23', '60', '1', '＜ 耶 路 撒 冷 未 来 的 荣 耀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18824', '23', '60', '2', '看 哪 ， 黑 暗 遮 盖 大 地 ， 幽 暗 遮 盖 万 民 ， 耶 和 华 却 要 显 现 照 耀 你 ； 他 的 荣 耀 要 现 在 你 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18825', '23', '60', '3', '万 国 要 来 就 你 的 光 ； 君 王 要 来 就 你 发 现 的 光 辉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18826', '23', '60', '4', '你 举 目 向 四 方 观 看 ； 众 人 都 聚 集 来 到 你 这 里 。 你 的 众 子 从 远 方 而 来 ； 你 的 众 女 也 被 怀 抱 而 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18827', '23', '60', '5', '那 时 ， 你 看 见 就 有 光 荣 ； 你 心 又 跳 动 又 宽 畅 ； 因 为 大 海 丰 盛 的 货 物 必 转 来 归 你 ； 列 国 的 财 宝 也 必 来 归 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18828', '23', '60', '6', '成 群 的 骆 驼 ， 并 米 甸 和 以 法 的 独 峰 驼 必 遮 满 你 ； 示 巴 的 众 人 都 必 来 到 ； 要 奉 上 黄 金 乳 香 ， 又 要 传 说 耶 和 华 的 赞 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18829', '23', '60', '7', '基 达 的 羊 群 都 必 聚 集 到 你 这 里 ， 尼 拜 约 的 公 羊 要 供 你 使 用 ， 在 我 坛 上 必 蒙 悦 纳 ； 我 必 荣 耀 我 荣 耀 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18830', '23', '60', '8', '那 些 飞 来 如 云 、 又 如 鸽 子 向 窗 户 飞 回 的 是 谁 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18831', '23', '60', '9', '众 海 岛 必 等 候 我 ， 首 先 是 他 施 的 船 只 ， 将 你 的 众 子 连 他 们 的 金 银 从 远 方 一 同 带 来 ， 都 为 耶 和 华 ─ ─ 你 神 的 名 ， 又 为 以 色 列 的 圣 者 ， 因 为 他 已 经 荣 耀 了 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18832', '23', '60', '10', '外 邦 人 必 建 筑 你 的 城 墙 ； 他 们 的 王 必 服 事 你 。 我 曾 发 怒 击 打 你 ， 现 今 却 施 恩 怜 恤 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18833', '23', '60', '11', '你 的 城 门 必 时 常 开 放 ， 昼 夜 不 关 ； 使 人 把 列 国 的 财 物 带 来 归 你 ， 并 将 他 们 的 君 王 牵 引 而 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18834', '23', '60', '12', '哪 一 邦 哪 一 国 不 事 奉 你 ， 就 必 灭 亡 ， 也 必 全 然 荒 废 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18835', '23', '60', '13', '黎 巴 嫩 的 荣 耀 ， 就 是 松 树 、 杉 树 、 黄 杨 树 ， 都 必 一 同 归 你 ， 为 要 修 饰 我 圣 所 之 地 ； 我 也 要 使 我 脚 踏 之 处 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18836', '23', '60', '14', '素 来 苦 待 你 的 ， 他 的 子 孙 都 必 屈 身 来 就 你 ； 藐 视 你 的 ， 都 要 在 你 脚 下 跪 拜 。 他 们 要 称 你 为 “ 耶 和 华 的 城 ” ， 为 “ 以 色 列 圣 者 的 锡 安 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18837', '23', '60', '15', '你 虽 然 被 撇 弃 被 厌 恶 ， 甚 至 无 人 经 过 ， 我 却 使 你 变 为 永 远 的 荣 华 ， 成 为 累 代 的 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18838', '23', '60', '16', '你 也 必 吃 万 国 的 奶 ， 又 吃 君 王 的 奶 。 你 便 知 道 我 ─ ─ 耶 和 华 是 你 的 救 主 ， 是 你 的 救 赎 主 ， 雅 各 的 大 能 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18839', '23', '60', '17', '我 要 拿 金 子 代 替 铜 ， 拿 银 子 代 替 铁 ， 拿 铜 代 替 木 头 ， 拿 铁 代 替 石 头 ； 并 要 以 和 平 为 你 的 官 长 ， 以 公 义 为 你 的 监 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18840', '23', '60', '18', '你 地 上 不 再 听 见 强 暴 的 事 ， 境 内 不 再 听 见 荒 凉 毁 灭 的 事 。 你 必 称 你 的 墙 为 “ 拯 救 ” ， 称 你 的 门 为 “ 赞 美 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18841', '23', '60', '19', '日 头 不 再 作 你 白 昼 的 光 ； 月 亮 也 不 再 发 光 照 耀 你 。 耶 和 华 却 要 作 你 永 远 的 光 ； 你 神 要 为 你 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18842', '23', '60', '20', '你 的 日 头 不 再 下 落 ； 你 的 月 亮 也 不 退 缩 ； 因 为 耶 和 华 必 作 你 永 远 的 光 。 你 悲 哀 的 日 子 也 完 毕 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18843', '23', '60', '21', '你 的 居 民 都 成 为 义 人 ， 永 远 得 地 为 业 ； 是 我 种 的 栽 子 ， 我 手 的 工 作 ， 使 我 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18844', '23', '60', '22', '至 小 的 族 要 加 增 千 倍 ； 微 弱 的 国 必 成 为 强 盛 。 我 ─ ─ 耶 和 华 要 按 定 期 速 成 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18845', '23', '61', '1', '＜ 拯 救 的 好 消 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18846', '23', '61', '2', '报 告 耶 和 华 的 恩 年 ， 和 我 们 神 报 仇 的 日 子 ； 安 慰 一 切 悲 哀 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18847', '23', '61', '3', '赐 华 冠 与 锡 安 悲 哀 的 人 ， 代 替 灰 尘 ； 喜 乐 油 代 替 悲 哀 ； 赞 美 衣 代 替 忧 伤 之 灵 ； 使 他 们 称 为 “ 公 义 树 ” ， 是 耶 和 华 所 栽 的 ， 叫 他 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18848', '23', '61', '4', '他 们 必 修 造 已 久 的 荒 场 ， 建 立 先 前 凄 凉 之 处 ， 重 修 历 代 荒 凉 之 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18849', '23', '61', '5', '那 时 ， 外 人 必 起 来 牧 放 你 们 的 羊 群 ； 外 邦 人 必 作 你 们 耕 种 田 地 的 ， 修 理 葡 萄 园 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18850', '23', '61', '6', '你 们 倒 要 称 为 耶 和 华 的 祭 司 ； 人 必 称 你 们 为 我 们 神 的 仆 役 。 你 们 必 吃 用 列 国 的 财 物 ， 因 得 他 们 的 荣 耀 自 夸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18851', '23', '61', '7', '你 们 必 得 加 倍 的 好 处 ， 代 替 所 受 的 羞 辱 ； 分 中 所 得 的 喜 乐 ， 必 代 替 所 受 的 凌 辱 。 在 境 内 必 得 加 倍 的 产 业 ； 永 远 之 乐 必 归 与 你 们 ｛ 原 文 是 他 们 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18852', '23', '61', '8', '因 为 我 ─ ─ 耶 和 华 喜 爱 公 平 ， 恨 恶 抢 夺 和 罪 孽 ； 我 要 凭 诚 实 施 行 报 应 ， 并 要 与 我 的 百 姓 立 永 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18853', '23', '61', '9', '他 们 的 后 裔 必 在 列 国 中 被 人 认 识 ； 他 们 的 子 孙 在 众 民 中 也 是 如 此 。 凡 看 见 他 们 的 必 认 他 们 是 耶 和 华 赐 福 的 后 裔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18854', '23', '61', '10', '我 因 耶 和 华 大 大 欢 喜 ； 我 的 心 靠 神 快 乐 。 因 他 以 拯 救 为 衣 给 我 穿 上 ， 以 公 义 为 袍 给 我 披 上 ， 好 像 新 郎 戴 上 华 冠 ， 又 像 新 妇 佩 戴 妆 饰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18855', '23', '61', '11', '田 地 怎 样 使 百 谷 发 芽 ， 园 子 怎 样 使 所 种 的 发 生 ， 主 耶 和 华 必 照 样 使 公 义 和 赞 美 在 万 民 中 发 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18856', '23', '62', '1', '我 因 锡 安 必 不 静 默 ， 为 耶 路 撒 冷 必 不 息 声 ， 直 到 他 的 公 义 如 光 辉 发 出 ， 他 的 救 恩 如 明 灯 发 亮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18857', '23', '62', '2', '列 国 必 见 你 的 公 义 ； 列 王 必 见 你 的 荣 耀 。 你 必 得 新 名 的 称 呼 ， 是 耶 和 华 亲 口 所 起 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18858', '23', '62', '3', '你 在 耶 和 华 的 手 中 要 作 为 华 冠 ， 在 你 神 的 掌 上 必 作 为 冕 旒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18859', '23', '62', '4', '你 必 不 再 称 为 “ 撇 弃 的 ” ； 你 的 地 也 不 再 称 为 “ 荒 凉 的 ” 。 你 却 要 称 为 “ 我 所 喜 悦 的 ” ； 你 的 地 也 必 称 为 “ 有 夫 之 妇 ” 。 因 为 耶 和 华 喜 悦 你 ， 你 的 地 也 必 归 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18860', '23', '62', '5', '少 年 人 怎 样 娶 处 女 ， 你 的 众 民 ｛ 民 ： 原 文 是 子 ｝ 也 要 照 样 娶 你 ； 新 郎 怎 样 喜 悦 新 妇 ， 你 的 神 也 要 照 样 喜 悦 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18861', '23', '62', '6', '耶 路 撒 冷 啊 ， 我 在 你 城 上 设 立 守 望 的 ， 他 们 昼 夜 必 不 静 默 。 呼 吁 耶 和 华 的 ， 你 们 不 要 歇 息 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18862', '23', '62', '7', '也 不 要 使 他 歇 息 ， 直 等 他 建 立 耶 路 撒 冷 ， 使 耶 路 撒 冷 在 地 上 成 为 可 赞 美 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18863', '23', '62', '8', '耶 和 华 指 着 自 己 的 右 手 和 大 能 的 膀 臂 起 誓 说 ： 我 必 不 再 将 你 的 五 谷 给 你 仇 敌 作 食 物 ； 外 邦 人 也 不 再 喝 你 劳 碌 得 来 的 新 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18864', '23', '62', '9', '惟 有 那 收 割 的 要 吃 ， 并 赞 美 耶 和 华 ； 那 聚 敛 的 要 在 我 圣 所 的 院 内 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18865', '23', '62', '10', '你 们 当 从 门 经 过 经 过 ， 预 备 百 姓 的 路 ； 修 筑 修 筑 大 道 ， 捡 去 石 头 ， 为 万 民 竖 立 大 旗 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18866', '23', '62', '11', '看 哪 ， 耶 和 华 曾 宣 告 到 地 极 ， 对 锡 安 的 居 民 ｛ 原 文 是 女 子 ｝ 说 ： 你 的 拯 救 者 来 到 。 他 的 赏 赐 在 他 那 里 ； 他 的 报 应 在 他 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18867', '23', '62', '12', '人 必 称 他 们 为 “ 圣 民 ” ， 为 “ 耶 和 华 的 赎 民 ” ； 你 也 必 称 为 “ 被 眷 顾 、 不 撇 弃 的 城 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18868', '23', '63', '1', '＜ 耶 和 华 恩 待 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18869', '23', '63', '2', '你 的 装 扮 为 何 有 红 色 ？ 你 的 衣 服 为 何 像 踹 酒 醡 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18870', '23', '63', '3', '我 独 自 踹 酒 醡 ； 众 民 中 无 一 人 与 我 同 在 。 我 发 怒 将 他 们 踹 下 ， 发 烈 怒 将 他 们 践 踏 。 他 们 的 血 溅 在 我 衣 服 上 ， 并 且 污 染 了 我 一 切 的 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18871', '23', '63', '4', '因 为 ， 报 仇 之 日 在 我 心 中 ； 救 赎 我 民 之 年 已 经 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18872', '23', '63', '5', '我 仰 望 ， 见 无 人 帮 助 ； 我 诧 异 ， 没 有 人 扶 持 。 所 以 ， 我 自 己 的 膀 臂 为 我 施 行 拯 救 ； 我 的 烈 怒 将 我 扶 持 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18873', '23', '63', '6', '我 发 怒 ， 踹 下 众 民 ； 发 烈 怒 ， 使 他 们 沉 醉 ， 又 将 他 们 的 血 倒 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18874', '23', '63', '7', '＜ 耶 和 华 对 以 色 列 的 良 善 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18875', '23', '63', '8', '他 说 ： 他 们 诚 然 是 我 的 百 姓 ， 不 行 虚 假 的 子 民 ； 这 样 ， 他 就 作 了 他 们 的 救 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18876', '23', '63', '9', '他 们 在 一 切 苦 难 中 ， 他 也 同 受 苦 难 ； 并 且 他 面 前 的 使 者 拯 救 他 们 ； 他 以 慈 爱 和 怜 悯 救 赎 他 们 ； 在 古 时 的 日 子 常 保 抱 他 们 ， 怀 搋 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18877', '23', '63', '10', '他 们 竟 悖 逆 ， 使 主 的 圣 灵 担 忧 。 他 就 转 作 他 们 的 仇 敌 ， 亲 自 攻 击 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18878', '23', '63', '11', '那 时 ， 他 们 ｛ 原 文 是 他 ｝ 想 起 古 时 的 日 子 ─ ─ 摩 西 和 他 百 姓 ， 说 ： 将 百 姓 和 牧 养 他 全 群 的 人 从 海 里 领 上 来 的 在 哪 里 呢 ？ 将 他 的 圣 灵 降 在 他 们 中 间 的 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18879', '23', '63', '12', '使 他 荣 耀 的 膀 臂 在 摩 西 的 右 手 边 行 动 ， 在 他 们 前 面 将 水 分 开 ， 要 建 立 自 己 永 远 的 名 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18880', '23', '63', '13', '带 领 他 们 经 过 深 处 ， 如 马 行 走 旷 野 ， 使 他 们 不 致 绊 跌 的 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18881', '23', '63', '14', '耶 和 华 的 灵 使 他 们 得 安 息 ， 仿 佛 牲 畜 下 到 山 谷 ； 照 样 ， 你 也 引 导 你 的 百 姓 ， 要 建 立 自 己 荣 耀 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18882', '23', '63', '15', '＜ 求 主 怜 悯 帮 助 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18883', '23', '63', '16', '亚 伯 拉 罕 虽 然 不 认 识 我 们 ， 以 色 列 也 不 承 认 我 们 ， 你 却 是 我 们 的 父 。 耶 和 华 啊 ， 你 是 我 们 的 父 ； 从 万 古 以 来 ， 你 名 称 为 “ 我 们 的 救 赎 主 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18884', '23', '63', '17', '耶 和 华 啊 ， 你 为 何 使 我 们 走 差 离 开 你 的 道 ， 使 我 们 心 里 刚 硬 、 不 敬 畏 你 呢 ？ 求 你 为 你 仆 人 ， 为 你 产 业 支 派 的 缘 故 ， 转 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18885', '23', '63', '18', '你 的 圣 民 不 过 暂 时 得 这 产 业 ； 我 们 的 敌 人 已 经 践 踏 你 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18886', '23', '63', '19', '我 们 好 像 你 未 曾 治 理 的 人 ， 又 像 未 曾 得 称 你 名 下 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18887', '23', '64', '1', '愿 你 裂 天 而 降 ； 愿 山 在 你 面 前 震 动 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18888', '23', '64', '2', '好 像 火 烧 干 柴 ， 又 像 火 将 水 烧 开 ， 使 你 敌 人 知 道 你 的 名 ， 使 列 国 在 你 面 前 发 颤 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18889', '23', '64', '3', '你 曾 行 我 们 不 能 逆 料 可 畏 的 事 。 那 时 你 降 临 ， 山 岭 在 你 面 前 震 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18890', '23', '64', '4', '从 古 以 来 ， 人 未 曾 听 见 、 未 曾 耳 闻 、 未 曾 眼 见 在 你 以 外 有 什 么 神 为 等 候 他 的 人 行 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18891', '23', '64', '5', '你 迎 接 那 欢 喜 行 义 、 记 念 你 道 的 人 ； 你 曾 发 怒 ， 我 们 仍 犯 罪 ； 这 景 况 已 久 ， 我 们 还 能 得 救 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18892', '23', '64', '6', '我 们 都 像 不 洁 净 的 人 ； 所 有 的 义 都 像 污 秽 的 衣 服 。 我 们 都 像 叶 子 渐 渐 枯 干 ； 我 们 的 罪 孽 好 像 风 把 我 们 吹 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18893', '23', '64', '7', '并 且 无 人 求 告 你 的 名 ； 无 人 奋 力 抓 住 你 。 原 来 你 掩 面 不 顾 我 们 ， 使 我 们 因 罪 孽 消 化 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18894', '23', '64', '8', '耶 和 华 啊 ， 现 在 你 仍 是 我 们 的 父 ！ 我 们 是 泥 ， 你 是 窑 匠 ； 我 们 都 是 你 手 的 工 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18895', '23', '64', '9', '耶 和 华 啊 ， 求 你 不 要 大 发 震 怒 ， 也 不 要 永 远 记 念 罪 孽 。 求 你 垂 顾 我 们 ， 我 们 都 是 你 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18896', '23', '64', '10', '你 的 圣 邑 变 为 旷 野 。 锡 安 变 为 旷 野 ； 耶 路 撒 冷 成 为 荒 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18897', '23', '64', '11', '我 们 圣 洁 华 美 的 殿 ─ ─ 就 是 我 们 列 祖 赞 美 你 的 所 在 被 火 焚 烧 ； 我 们 所 羡 慕 的 美 地 尽 都 荒 废 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18898', '23', '64', '12', '耶 和 华 啊 ， 有 这 些 事 ， 你 还 忍 得 住 吗 ？ 你 仍 静 默 使 我 们 深 受 苦 难 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18899', '23', '65', '1', '＜ 神 对 背 逆 者 的 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18900', '23', '65', '2', '我 整 天 伸 手 招 呼 那 悖 逆 的 百 姓 ； 他 们 随 自 己 的 意 念 行 不 善 之 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18901', '23', '65', '3', '这 百 姓 时 常 当 面 惹 我 发 怒 ； 在 园 中 献 祭 ， 在 坛 ｛ 原 文 是 砖 ｝ 上 烧 香 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18902', '23', '65', '4', '在 坟 墓 间 坐 着 ， 在 隐 密 处 住 宿 ， 吃 猪 肉 ； 他 们 器 皿 中 有 可 憎 之 物 做 的 汤 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18903', '23', '65', '5', '且 对 人 说 ： 你 站 开 吧 ！ 不 要 挨 近 我 ， 因 为 我 比 你 圣 洁 。 主 说 ： 这 些 人 是 我 鼻 中 的 烟 ， 是 整 天 烧 着 的 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18904', '23', '65', '6', '看 哪 ， 这 都 写 在 我 面 前 。 我 必 不 静 默 ， 必 施 行 报 应 ， 必 将 你 们 的 罪 孽 和 你 们 列 祖 的 罪 孽 ， 就 是 在 山 上 烧 香 ， 在 冈 上 亵 渎 我 的 罪 孽 ， 一 同 报 应 在 他 们 后 人 怀 中 ， 我 先 要 把 他 们 所 行 的 量 给 他 们 ； 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18905', '23', '65', '7', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18906', '23', '65', '8', '耶 和 华 如 此 说 ： 葡 萄 中 寻 得 新 酒 ， 人 就 说 ： 不 要 毁 坏 ， 因 为 福 在 其 中 。 我 因 我 仆 人 的 缘 故 也 必 照 样 而 行 ， 不 将 他 们 全 然 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18907', '23', '65', '9', '我 必 从 雅 各 中 领 出 后 裔 ， 从 犹 大 中 领 出 承 受 我 众 山 的 。 我 的 选 民 必 承 受 ； 我 的 仆 人 要 在 那 里 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18908', '23', '65', '10', '沙 仑 平 原 必 成 为 羊 群 的 圈 ； 亚 割 谷 必 成 为 牛 群 躺 卧 之 处 ， 都 为 寻 求 我 的 民 所 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18909', '23', '65', '11', '但 你 们 这 些 离 弃 耶 和 华 、 忘 记 我 的 圣 山 、 给 时 运 摆 筵 席 ｛ 原 文 是 桌 子 ｝ 、 给 天 命 盛 满 调 和 酒 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18910', '23', '65', '12', '我 要 命 定 你 们 归 在 刀 下 ， 都 必 屈 身 被 杀 ； 因 为 我 呼 唤 ， 你 们 没 有 答 应 ； 我 说 话 ， 你 们 没 有 听 从 ； 反 倒 行 我 眼 中 看 为 恶 的 ， 拣 选 我 所 不 喜 悦 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18911', '23', '65', '13', '所 以 ， 主 耶 和 华 如 此 说 ： 我 的 仆 人 必 得 吃 ， 你 们 却 饥 饿 ； 我 的 仆 人 必 得 喝 ， 你 们 却 干 渴 ； 我 的 仆 人 必 欢 喜 ， 你 们 却 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18912', '23', '65', '14', '我 的 仆 人 因 心 中 高 兴 欢 呼 ， 你 们 却 因 心 中 忧 愁 哀 哭 ， 又 因 心 里 忧 伤 哀 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18913', '23', '65', '15', '你 们 必 留 下 自 己 的 名 ， 为 我 选 民 指 着 赌 咒 。 主 耶 和 华 必 杀 你 们 ， 另 起 别 名 称 呼 他 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18914', '23', '65', '16', '这 样 ， 在 地 上 为 自 己 求 福 的 ， 必 凭 真 实 的 神 求 福 ； 在 地 上 起 誓 的 ， 必 指 真 实 的 神 起 誓 。 因 为 ， 从 前 的 患 难 已 经 忘 记 ， 也 从 我 眼 前 隐 藏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18915', '23', '65', '17', '＜ 新 天 新 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18916', '23', '65', '18', '你 们 当 因 我 所 造 的 永 远 欢 喜 快 乐 ； 因 我 造 耶 路 撒 冷 为 人 所 喜 ， 造 其 中 的 居 民 为 人 所 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18917', '23', '65', '19', '我 必 因 耶 路 撒 冷 欢 喜 ， 因 我 的 百 姓 快 乐 ； 其 中 必 不 再 听 见 哭 泣 的 声 音 和 哀 号 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18918', '23', '65', '20', '其 中 必 没 有 数 日 夭 亡 的 婴 孩 ， 也 没 有 寿 数 不 满 的 老 者 ； 因 为 百 岁 死 的 仍 算 孩 童 ， 有 百 岁 死 的 罪 人 算 被 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18919', '23', '65', '21', '他 们 要 建 造 房 屋 ， 自 己 居 住 ； 栽 种 葡 萄 园 ， 吃 其 中 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18920', '23', '65', '22', '他 们 建 造 的 ， 别 人 不 得 住 ； 他 们 栽 种 的 ， 别 人 不 得 吃 ； 因 为 我 民 的 日 子 必 像 树 木 的 日 子 ； 我 选 民 亲 手 劳 碌 得 来 的 必 长 久 享 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18921', '23', '65', '23', '他 们 必 不 徒 然 劳 碌 ， 所 生 产 的 ， 也 不 遭 灾 害 ， 因 为 都 是 蒙 耶 和 华 赐 福 的 后 裔 ； 他 们 的 子 孙 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18922', '23', '65', '24', '他 们 尚 未 求 告 ， 我 就 应 允 ； 正 说 话 的 时 候 ， 我 就 垂 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18923', '23', '65', '25', '豺 狼 必 与 羊 羔 同 食 ； 狮 子 必 吃 草 与 牛 一 样 ； 尘 土 必 作 蛇 的 食 物 。 在 我 圣 山 的 遍 处 ， 这 一 切 都 不 伤 人 ， 不 害 物 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18924', '23', '66', '1', '＜ 神 审 判 万 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18925', '23', '66', '2', '耶 和 华 说 ： 这 一 切 都 是 我 手 所 造 的 ， 所 以 就 都 有 了 。 但 我 所 看 顾 的 ， 就 是 虚 心 ｛ 原 文 是 贫 穷 ｝ 痛 悔 、 因 我 话 而 战 兢 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18926', '23', '66', '3', '假 冒 为 善 的 宰 牛 ， 好 像 杀 人 ， 献 羊 羔 ， 好 像 打 折 狗 项 ， 献 供 物 ， 好 像 献 猪 血 ， 烧 乳 香 ， 好 像 称 颂 偶 像 。 这 等 人 拣 选 自 己 的 道 路 ， 心 里 喜 悦 行 可 憎 恶 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18927', '23', '66', '4', '我 也 必 拣 选 迷 惑 他 们 的 事 ， 使 他 们 所 惧 怕 的 临 到 他 们 ； 因 为 我 呼 唤 ， 无 人 答 应 ； 我 说 话 ， 他 们 不 听 从 ； 反 倒 行 我 眼 中 看 为 恶 的 ， 拣 选 我 所 不 喜 悦 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18928', '23', '66', '5', '你 们 因 耶 和 华 言 语 战 兢 的 人 当 听 他 的 话 ： 你 们 的 弟 兄 ─ ─ 就 是 恨 恶 你 们 ， 因 我 名 赶 出 你 们 的 ， 曾 说 ： 愿 耶 和 华 得 荣 耀 ， 使 我 们 得 见 你 们 的 喜 乐 ； 但 蒙 羞 的 究 竟 是 他 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18929', '23', '66', '6', '有 喧 哗 的 声 音 出 自 城 中 ！ 有 声 音 出 于 殿 中 ！ 是 耶 和 华 向 仇 敌 施 行 报 应 的 声 音 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18930', '23', '66', '7', '锡 安 未 曾 劬 劳 就 生 产 ， 未 觉 疼 痛 就 生 出 男 孩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18931', '23', '66', '8', '国 岂 能 一 日 而 生 ？ 民 岂 能 一 时 而 产 ？ 因 为 锡 安 一 劬 劳 便 生 下 儿 女 ， 这 样 的 事 谁 曾 听 见 ？ 谁 曾 看 见 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18932', '23', '66', '9', '耶 和 华 说 ： 我 既 使 她 临 产 ， 岂 不 使 她 生 产 呢 ？ 你 的 神 说 ： 我 既 使 她 生 产 ， 岂 能 使 她 闭 胎 不 生 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18933', '23', '66', '10', '你 们 爱 慕 耶 路 撒 冷 的 都 要 与 她 一 同 欢 喜 快 乐 ； 你 们 为 她 悲 哀 的 都 要 与 她 一 同 乐 上 加 乐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18934', '23', '66', '11', '使 你 们 在 她 安 慰 的 怀 中 吃 奶 得 饱 ， 使 他 们 得 她 丰 盛 的 荣 耀 ， 犹 如 挤 奶 ， 满 心 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18935', '23', '66', '12', '耶 和 华 如 此 说 ： 我 要 使 平 安 延 及 她 ， 好 像 江 河 ， 使 列 国 的 荣 耀 延 及 她 ， 如 同 涨 溢 的 河 。 你 们 要 从 中 享 受 ｛ 原 文 是 咂 ｝ ； 你 们 必 蒙 抱 在 肋 旁 ， 摇 弄 在 膝 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18936', '23', '66', '13', '母 亲 怎 样 安 慰 儿 子 ， 我 就 照 样 安 慰 你 们 ； 你 们 也 必 因 ｛ 或 译 ： 在 ｝ 耶 路 撒 冷 得 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18937', '23', '66', '14', '你 们 看 见 ， 就 心 中 快 乐 ； 你 们 的 骨 头 必 得 滋 润 像 嫩 草 一 样 ； 而 且 耶 和 华 的 手 向 他 仆 人 所 行 的 必 被 人 知 道 ； 他 也 要 向 仇 敌 发 恼 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18938', '23', '66', '15', '看 哪 ， 耶 和 华 必 在 火 中 降 临 ； 他 的 车 辇 像 旋 风 ， 以 烈 怒 施 行 报 应 ， 以 火 焰 施 行 责 罚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18939', '23', '66', '16', '因 为 耶 和 华 在 一 切 有 血 气 的 人 身 上 ， 必 以 火 与 刀 施 行 审 判 ； 被 耶 和 华 所 杀 的 必 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18940', '23', '66', '17', '“ 那 些 分 别 为 圣 、 洁 净 自 己 的 ， 进 入 园 内 跟 在 其 中 一 个 人 的 后 头 ， 吃 猪 肉 和 仓 鼠 并 可 憎 之 物 ， 他 们 必 一 同 灭 绝 ； 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18941', '23', '66', '18', '“ 我 知 道 他 们 的 行 为 和 他 们 的 意 念 。 时 候 将 到 ， 我 必 将 万 民 万 族 ｛ 族 ： 原 文 是 舌 ｝ 聚 来 ， 看 见 我 的 荣 耀 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18942', '23', '66', '19', '我 要 显 神 迹 ｛ 或 译 ： 记 号 ｝ 在 他 们 中 间 。 逃 脱 的 ， 我 要 差 到 列 国 去 ， 就 是 到 他 施 、 普 勒 、 拉 弓 的 路 德 和 土 巴 、 雅 完 ， 并 素 来 没 有 听 见 我 名 声 、 没 有 看 见 我 荣 耀 辽 远 的 海 岛 ； 他 们 必 将 我 的 荣 耀 传 扬 在 列 国 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18943', '23', '66', '20', '他 们 必 将 你 们 的 弟 兄 从 列 国 中 送 回 ， 使 他 们 或 骑 马 ， 或 坐 车 ， 坐 轿 ， 骑 骡 子 ， 骑 独 峰 驼 ， 到 我 的 圣 山 耶 路 撒 冷 ， 作 为 供 物 献 给 耶 和 华 ， 好 像 以 色 列 人 用 洁 净 的 器 皿 盛 供 物 奉 到 耶 和 华 的 殿 中 ； 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18944', '23', '66', '21', '耶 和 华 说 ： 我 也 必 从 他 们 中 间 取 人 为 祭 司 ， 为 利 未 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18945', '23', '66', '22', '耶 和 华 说 ： 我 所 要 造 的 新 天 新 地 ， 怎 样 在 我 面 前 长 存 ； 你 们 的 后 裔 和 你 们 的 名 字 也 必 照 样 长 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18946', '23', '66', '23', '每 逢 月 朔 、 安 息 日 ， 凡 有 血 气 的 必 来 在 我 面 前 下 拜 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18947', '23', '66', '24', '他 们 必 出 去 观 看 那 些 违 背 我 人 的 尸 首 ； 因 为 他 们 的 虫 是 不 死 的 ； 他 们 的 火 是 不 灭 的 ； 凡 有 血 气 的 都 必 憎 恶 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18948', '24', '1', '1', '便 雅 悯 地 亚 拿 突 城 的 祭 司 中 ， 希 勒 家 的 儿 子 耶 利 米 的 话 记 在 下 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18949', '24', '1', '2', '犹 大 王 亚 们 的 儿 子 约 西 亚 在 位 十 三 年 ， 耶 和 华 的 话 临 到 耶 利 米 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18950', '24', '1', '3', '从 犹 大 王 约 西 亚 的 儿 子 约 雅 敬 在 位 的 时 候 ， 直 到 犹 大 王 约 西 亚 的 儿 子 西 底 家 在 位 的 末 年 ， 就 是 十 一 年 五 月 间 耶 路 撒 冷 人 被 掳 的 时 候 ， 耶 和 华 的 话 也 常 临 到 耶 利 米 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18951', '24', '1', '4', '＜ 耶 利 米 蒙 选 召 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18952', '24', '1', '5', '我 未 将 你 造 在 腹 中 ， 我 已 晓 得 你 ； 你 未 出 母 胎 ， 我 已 分 别 你 为 圣 ； 我 已 派 你 作 列 国 的 先 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18953', '24', '1', '6', '我 就 说 ： 主 耶 和 华 啊 ， 我 不 知 怎 样 说 ， 因 为 我 是 年 幼 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18954', '24', '1', '7', '耶 和 华 对 我 说 ： 你 不 要 说 我 是 年 幼 的 ， 因 为 我 差 遣 你 到 谁 那 里 去 ， 你 都 要 去 ； 我 吩 咐 你 说 什 么 话 ， 你 都 要 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18955', '24', '1', '8', '你 不 要 惧 怕 他 们 ， 因 为 我 与 你 同 在 ， 要 拯 救 你 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18956', '24', '1', '9', '于 是 耶 和 华 伸 手 按 我 的 口 ， 对 我 说 ： 我 已 将 当 说 的 话 传 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18957', '24', '1', '10', '看 哪 ， 我 今 日 立 你 在 列 邦 列 国 之 上 ， 为 要 施 行 拔 出 、 拆 毁 、 毁 坏 、 倾 覆 ， 又 要 建 立 、 栽 植 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18958', '24', '1', '11', '＜ 两 个 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18959', '24', '1', '12', '耶 和 华 对 我 说 ： “ 你 看 得 不 错 ； 因 为 我 留 意 保 守 我 的 话 ， 使 得 成 就 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18960', '24', '1', '13', '耶 和 华 的 话 第 二 次 临 到 我 说 ： “ 你 看 见 什 么 ？ ” 我 说 ： “ 我 看 见 一 个 烧 开 的 锅 ， 从 北 而 倾 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18961', '24', '1', '14', '耶 和 华 对 我 说 ： “ 必 有 灾 祸 从 北 方 发 出 ， 临 到 这 地 的 一 切 居 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18962', '24', '1', '15', '耶 和 华 说 ： “ 看 哪 ， 我 要 召 北 方 列 国 的 众 族 ； 他 们 要 来 ， 各 安 座 位 在 耶 路 撒 冷 的 城 门 口 ， 周 围 攻 击 城 墙 ， 又 要 攻 击 犹 大 的 一 切 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18963', '24', '1', '16', '至 于 这 民 的 一 切 恶 ， 就 是 离 弃 我 、 向 别 神 烧 香 、 跪 拜 自 己 手 所 造 的 ， 我 要 发 出 我 的 判 语 ， 攻 击 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18964', '24', '1', '17', '所 以 你 当 束 腰 ， 起 来 将 我 所 吩 咐 你 的 一 切 话 告 诉 他 们 ； 不 要 因 他 们 惊 惶 ， 免 得 我 使 你 在 他 们 面 前 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18965', '24', '1', '18', '看 哪 ， 我 今 日 使 你 成 为 坚 城 、 铁 柱 、 铜 墙 ， 与 全 地 和 犹 大 的 君 王 、 首 领 、 祭 司 ， 并 地 上 的 众 民 反 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18966', '24', '1', '19', '他 们 要 攻 击 你 ， 却 不 能 胜 你 ； 因 为 我 与 你 同 在 ， 要 拯 救 你 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18967', '24', '2', '1', '＜ 神 眷 顾 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18968', '24', '2', '2', '“ 你 去 向 耶 路 撒 冷 人 的 耳 中 喊 叫 说 ， 耶 和 华 如 此 说 ： 你 幼 年 的 恩 爱 ， 婚 姻 的 爱 情 ， 你 怎 样 在 旷 野 ， 在 未 曾 耕 种 之 地 跟 随 我 ， 我 都 记 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18969', '24', '2', '3', '那 时 以 色 列 归 耶 和 华 为 圣 ， 作 为 土 产 初 熟 的 果 子 ； 凡 吞 吃 它 的 必 算 为 有 罪 ， 灾 祸 必 临 到 他 们 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18970', '24', '2', '4', '＜ 以 色 列 祖 先 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18971', '24', '2', '5', '耶 和 华 如 此 说 ： 你 们 的 列 祖 见 我 有 什 么 不 义 ， 竟 远 离 我 ， 随 从 虚 无 的 神 ， 自 己 成 为 虚 妄 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18972', '24', '2', '6', '他 们 也 不 说 ： 那 领 我 们 从 埃 及 地 上 来 ， 引 导 我 们 经 过 旷 野 ， 沙 漠 有 深 坑 之 地 ， 和 干 旱 死 荫 、 无 人 经 过 、 无 人 居 住 之 地 的 耶 和 华 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18973', '24', '2', '7', '我 领 你 们 进 入 肥 美 之 地 ， 使 你 们 得 吃 其 中 的 果 子 和 美 物 ； 但 你 们 进 入 的 时 候 就 玷 污 我 的 地 ， 使 我 的 产 业 成 为 可 憎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18974', '24', '2', '8', '祭 司 都 不 说 ， 耶 和 华 在 哪 里 呢 ？ 传 讲 律 法 的 都 不 认 识 我 。 官 长 违 背 我 ； 先 知 藉 巴 力 说 预 言 ， 随 从 无 益 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18975', '24', '2', '9', '＜ 神 谴 责 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18976', '24', '2', '10', '你 们 且 过 到 基 提 海 岛 去 察 看 ， 打 发 人 往 基 达 去 留 心 查 考 ， 看 曾 有 这 样 的 事 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18977', '24', '2', '11', '岂 有 一 国 换 了 他 的 神 吗 ？ 其 实 这 不 是 神 ！ 但 我 的 百 姓 将 他 们 的 荣 耀 换 了 那 无 益 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18978', '24', '2', '12', '诸 天 哪 ， 要 因 此 惊 奇 ， 极 其 恐 慌 ， 甚 为 凄 凉 ！ 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18979', '24', '2', '13', '因 为 我 的 百 姓 做 了 两 件 恶 事 ， 就 是 离 弃 我 这 活 水 的 泉 源 ， 为 自 己 凿 出 池 子 ， 是 破 裂 不 能 存 水 的 池 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18980', '24', '2', '14', '＜ 以 色 列 不 忠 的 结 局 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18981', '24', '2', '15', '少 壮 狮 子 向 他 咆 哮 ， 大 声 吼 叫 ， 使 他 的 地 荒 凉 ； 城 邑 也 都 焚 烧 ， 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18982', '24', '2', '16', '挪 弗 人 和 答 比 匿 人 也 打 破 你 的 头 顶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18983', '24', '2', '17', '这 事 临 到 你 身 上 ， 不 是 你 自 招 的 吗 ？ 不 是 因 耶 和 华 ─ ─ 你 神 引 你 行 路 的 时 候 ， 你 离 弃 他 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18984', '24', '2', '18', '现 今 你 为 何 在 埃 及 路 上 要 喝 西 曷 的 水 呢 ？ 你 为 何 在 亚 述 路 上 要 喝 大 河 的 水 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18985', '24', '2', '19', '你 自 己 的 恶 必 惩 治 你 ； 你 背 道 的 事 必 责 备 你 。 由 此 可 知 可 见 ， 你 离 弃 耶 和 华 ─ ─ 你 的 神 ， 不 存 敬 畏 我 的 心 ， 乃 为 恶 事 ， 为 苦 事 。 这 是 主 ─ ─ 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18986', '24', '2', '20', '＜ 以 色 列 拒 绝 敬 拜 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18987', '24', '2', '21', '然 而 ， 我 栽 你 是 上 等 的 葡 萄 树 ， 全 然 是 真 种 子 ； 你 怎 么 向 我 变 为 外 邦 葡 萄 树 的 坏 枝 子 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18988', '24', '2', '22', '你 虽 用 碱 、 多 用 肥 皂 洗 濯 ， 你 罪 孽 的 痕 迹 仍 然 在 我 面 前 显 出 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18989', '24', '2', '23', '你 怎 能 说 ： 我 没 有 玷 污 、 没 有 随 从 众 巴 力 ？ 你 看 你 谷 中 的 路 ， 就 知 道 你 所 行 的 如 何 。 你 是 快 行 的 独 峰 驼 ， 狂 奔 乱 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18990', '24', '2', '24', '你 是 野 驴 ， 惯 在 旷 野 ， 欲 心 发 动 就 吸 风 ； 起 性 的 时 候 谁 能 使 它 转 去 呢 ？ 凡 寻 找 它 的 必 不 致 疲 乏 ； 在 它 的 月 分 必 能 寻 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18991', '24', '2', '25', '我 说 ： 你 不 要 使 脚 上 无 鞋 ， 喉 咙 干 渴 。 你 倒 说 ： 这 是 枉 然 。 我 喜 爱 别 神 ， 我 必 随 从 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18992', '24', '2', '26', '＜ 以 色 列 该 受 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18993', '24', '2', '27', '他 们 向 木 头 说 ： 你 是 我 的 父 ； 向 石 头 说 ： 你 是 生 我 的 。 他 们 以 背 向 我 ， 不 以 面 向 我 ； 及 至 遭 遇 患 难 的 时 候 却 说 ： 起 来 拯 救 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18994', '24', '2', '28', '你 为 自 己 做 的 神 在 哪 里 呢 ？ 你 遭 遇 患 难 的 时 候 ， 叫 他 们 起 来 拯 救 你 吧 ！ 犹 大 啊 ， 你 神 的 数 目 与 你 城 的 数 目 相 等 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18995', '24', '2', '29', '耶 和 华 说 ： 你 们 为 何 与 我 争 辩 呢 ？ 你 们 都 违 背 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18996', '24', '2', '30', '我 责 打 你 们 的 儿 女 是 徒 然 的 ， 他 们 不 受 惩 治 。 你 们 自 己 的 刀 吞 灭 你 们 的 先 知 ， 好 像 残 害 的 狮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18997', '24', '2', '31', '这 世 代 的 人 哪 ， 你 们 要 看 明 耶 和 华 的 话 。 我 岂 向 以 色 列 作 旷 野 呢 ？ 或 作 幽 暗 之 地 呢 ？ 我 的 百 姓 为 何 说 ： 我 们 脱 离 约 束 ， 再 不 归 向 你 了 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18998', '24', '2', '32', '处 女 岂 能 忘 记 她 的 妆 饰 呢 ？ 新 妇 岂 能 忘 记 她 的 美 衣 呢 ？ 我 的 百 姓 却 忘 记 了 我 无 数 的 日 子 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('18999', '24', '2', '33', '你 怎 么 修 饰 你 的 道 路 要 求 爱 情 呢 ？ 就 是 恶 劣 的 妇 人 你 也 叫 她 们 行 你 的 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19000', '24', '2', '34', '并 且 你 的 衣 襟 上 有 无 辜 穷 人 的 血 ； 你 杀 他 们 并 不 是 遇 见 他 们 挖 窟 窿 ， 乃 是 因 这 一 切 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19001', '24', '2', '35', '你 还 说 ： 我 无 辜 ； 耶 和 华 的 怒 气 必 定 向 我 消 了 。 看 哪 ， 我 必 审 问 你 ； 因 你 自 说 ： 我 没 有 犯 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19002', '24', '2', '36', '你 为 何 东 跑 西 奔 要 更 换 你 的 路 呢 ？ 你 必 因 埃 及 蒙 羞 ， 像 从 前 因 亚 述 蒙 羞 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19003', '24', '2', '37', '你 也 必 两 手 抱 头 从 埃 及 出 来 ； 因 为 耶 和 华 已 经 弃 绝 你 所 倚 靠 的 ， 你 必 不 因 他 们 得 顺 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19004', '24', '3', '1', '＜ 不 忠 心 的 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19005', '24', '3', '2', '你 向 净 光 的 高 处 举 目 观 看 ， 你 在 何 处 没 有 淫 行 呢 ？ 你 坐 在 道 旁 等 候 ， 好 像 阿 拉 伯 人 在 旷 野 埋 伏 一 样 ， 并 且 你 的 淫 行 邪 恶 玷 污 了 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19006', '24', '3', '3', '因 此 甘 霖 停 止 ， 春 ｛ 原 文 是 晚 ｝ 雨 不 降 。 你 还 是 有 娼 妓 之 脸 ， 不 顾 羞 耻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19007', '24', '3', '4', '从 今 以 后 ， 你 岂 不 向 我 呼 叫 说 ： 我 父 啊 ， 你 是 我 幼 年 的 恩 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19008', '24', '3', '5', '耶 和 华 岂 永 远 怀 怒 ， 存 留 到 底 吗 ？ 看 哪 ， 你 又 发 恶 言 又 行 坏 事 ， 随 自 己 的 私 意 而 行 ｛ 或 译 ： 你 虽 这 样 说 ， 还 是 行 恶 放 纵 欲 心 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19009', '24', '3', '6', '＜ 以 色 列 和 犹 大 应 当 悔 改 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19010', '24', '3', '7', '她 行 这 些 事 以 后 ， 我 说 她 必 归 向 我 ， 她 却 不 归 向 我 。 她 奸 诈 的 妹 妹 犹 大 也 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19011', '24', '3', '8', '背 道 的 以 色 列 行 淫 ， 我 为 这 缘 故 给 她 休 书 休 她 ； 我 看 见 她 奸 诈 的 妹 妹 犹 大 ， 还 不 惧 怕 ， 也 去 行 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19012', '24', '3', '9', '因 以 色 列 轻 忽 了 她 的 淫 乱 ， 和 石 头 木 头 行 淫 ， 地 就 被 玷 污 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19013', '24', '3', '10', '虽 有 这 一 切 的 事 ， 她 奸 诈 的 妹 妹 犹 大 还 不 一 心 归 向 我 ， 不 过 是 假 意 归 我 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19014', '24', '3', '11', '耶 和 华 对 我 说 ： “ 背 道 的 以 色 列 比 奸 诈 的 犹 大 还 显 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19015', '24', '3', '12', '你 去 向 北 方 宣 告 说 ： 耶 和 华 说 ： 背 道 的 以 色 列 啊 ， 回 来 吧 ！ 我 必 不 怒 目 看 你 们 ； 因 为 我 是 慈 爱 的 ， 我 必 不 永 远 存 怒 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19016', '24', '3', '13', '只 要 承 认 你 的 罪 孽 ， 就 是 你 违 背 耶 和 华 ─ ─ 你 的 神 ， 在 各 青 翠 树 下 向 别 神 东 奔 西 跑 ， 没 有 听 从 我 的 话 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19017', '24', '3', '14', '耶 和 华 说 ： 背 道 的 儿 女 啊 ， 回 来 吧 ！ 因 为 我 作 你 们 的 丈 夫 ， 并 且 我 必 将 你 们 从 一 城 取 一 人 ， 从 一 族 取 两 人 ， 带 到 锡 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19018', '24', '3', '15', '我 也 必 将 合 我 心 的 牧 者 赐 给 你 们 。 他 们 必 以 知 识 和 智 慧 牧 养 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19019', '24', '3', '16', '耶 和 华 说 ： “ 你 们 在 国 中 生 养 众 多 ； 当 那 些 日 子 ， 人 必 不 再 提 说 耶 和 华 的 约 柜 ， 不 追 想 ， 不 记 念 ， 不 觉 缺 少 ， 也 不 再 制 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19020', '24', '3', '17', '那 时 ， 人 必 称 耶 路 撒 冷 为 耶 和 华 的 宝 座 ； 万 国 必 到 耶 路 撒 冷 ， 在 耶 和 华 立 名 的 地 方 聚 集 。 他 们 必 不 再 随 从 自 己 顽 梗 的 恶 心 行 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19021', '24', '3', '18', '当 那 些 日 子 ， 犹 大 家 要 和 以 色 列 家 同 行 ， 从 北 方 之 地 一 同 来 到 我 赐 给 你 们 列 祖 为 业 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19022', '24', '3', '19', '＜ 神 的 子 民 拜 偶 像 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19023', '24', '3', '20', '以 色 列 家 ， 你 们 向 我 行 诡 诈 ， 真 像 妻 子 行 诡 诈 离 开 她 丈 夫 一 样 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19024', '24', '3', '21', '在 净 光 的 高 处 听 见 人 声 ， 就 是 以 色 列 人 哭 泣 恳 求 之 声 ， 乃 因 他 们 走 弯 曲 之 道 ， 忘 记 耶 和 华 ─ ─ 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19025', '24', '3', '22', '你 们 这 背 道 的 儿 女 啊 ， 回 来 吧 ！ 我 要 医 治 你 们 背 道 的 病 。 看 哪 ， 我 们 来 到 你 这 里 ， 因 你 是 耶 和 华 ─ ─ 我 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19026', '24', '3', '23', '仰 望 从 小 山 或 从 大 山 的 喧 嚷 中 得 帮 助 ， 真 是 枉 然 的 。 以 色 列 得 救 ， 诚 然 在 乎 耶 和 华 ─ ─ 我 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19027', '24', '3', '24', '从 我 们 幼 年 以 来 ， 那 可 耻 的 偶 像 将 我 们 列 祖 所 劳 碌 得 来 的 羊 群 、 牛 群 ， 和 他 们 的 儿 女 都 吞 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19028', '24', '3', '25', '我 们 在 羞 耻 中 躺 卧 吧 ！ 愿 惭 愧 将 我 们 遮 盖 ； 因 为 从 立 国 ｛ 原 文 是 幼 年 ｝ 以 来 ， 我 们 和 我 们 的 列 祖 常 常 得 罪 耶 和 华 ─ ─ 我 们 的 神 ， 没 有 听 从 耶 和 华 ─ ─ 我 们 神 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19029', '24', '4', '1', '＜ 呼 召 以 色 列 悔 改 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19030', '24', '4', '2', '你 必 凭 诚 实 、 公 平 、 公 义 ， 指 着 永 生 的 耶 和 华 起 誓 ； 列 国 必 因 耶 和 华 称 自 己 为 有 福 ， 也 必 因 他 夸 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19031', '24', '4', '3', '耶 和 华 对 犹 大 和 耶 路 撒 冷 人 如 此 说 ： 要 开 垦 你 们 的 荒 地 ， 不 要 撒 种 在 荆 棘 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19032', '24', '4', '4', '犹 大 人 和 耶 路 撒 冷 的 居 民 哪 ， 你 们 当 自 行 割 礼 ， 归 耶 和 华 ， 将 心 里 的 污 秽 除 掉 ； 恐 怕 我 的 忿 怒 因 你 们 的 恶 行 发 作 ， 如 火 着 起 ， 甚 至 无 人 能 以 熄 灭 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19033', '24', '4', '5', '＜ 外 患 威 胁 犹 大 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19034', '24', '4', '6', '应 当 向 锡 安 竖 立 大 旗 。 要 逃 避 ， 不 要 迟 延 ， 因 我 必 使 灾 祸 与 大 毁 灭 从 北 方 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19035', '24', '4', '7', '有 狮 子 从 密 林 中 上 来 ， 是 毁 坏 列 国 的 。 它 已 经 动 身 出 离 本 处 ， 要 使 你 的 地 荒 凉 ， 使 你 的 城 邑 变 为 荒 场 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19036', '24', '4', '8', '因 此 ， 你 们 当 腰 束 麻 布 ， 大 声 哀 号 ， 因 为 耶 和 华 的 烈 怒 没 有 向 我 们 转 消 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19037', '24', '4', '9', '耶 和 华 说 ： “ 到 那 时 ， 君 王 和 首 领 的 心 都 要 消 灭 ； 祭 司 都 要 惊 奇 ， 先 知 都 要 诧 异 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19038', '24', '4', '10', '我 说 ： “ 哀 哉 ！ 主 耶 和 华 啊 ， 你 真 是 大 大 地 欺 哄 这 百 姓 和 耶 路 撒 冷 ， 说 ： ‘ 你 们 必 得 平 安 ’ 。 其 实 刀 剑 害 及 性 命 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19039', '24', '4', '11', '那 时 ， 必 有 话 对 这 百 姓 和 耶 路 撒 冷 说 ： “ 有 一 阵 热 风 从 旷 野 净 光 的 高 处 向 我 的 众 民 ｛ 原 文 是 民 女 ｝ 刮 来 ， 不 是 为 簸 扬 ， 也 不 是 为 扬 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19040', '24', '4', '12', '必 有 一 阵 更 大 的 风 从 这 些 地 方 为 我 刮 来 ； 现 在 我 又 必 发 出 判 语 ， 攻 击 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19041', '24', '4', '13', '＜ 犹 大 被 敌 人 围 困 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19042', '24', '4', '14', '耶 路 撒 冷 啊 ， 你 当 洗 去 心 中 的 恶 ， 使 你 可 以 得 救 。 恶 念 存 在 你 心 里 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19043', '24', '4', '15', '有 声 音 从 但 传 扬 ， 从 以 法 莲 山 报 祸 患 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19044', '24', '4', '16', '你 们 当 传 给 列 国 ， 报 告 攻 击 耶 路 撒 冷 的 事 说 ： 有 探 望 的 人 从 远 方 来 到 ， 向 犹 大 的 城 邑 大 声 呐 喊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19045', '24', '4', '17', '他 们 周 围 攻 击 耶 路 撒 冷 ， 好 像 看 守 田 园 的 ， 因 为 她 背 叛 了 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19046', '24', '4', '18', '你 的 行 动 ， 你 的 作 为 ， 招 惹 这 事 ； 这 是 你 罪 恶 的 结 果 ， 实 在 是 苦 ， 是 害 及 你 心 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19047', '24', '4', '19', '＜ 耶 利 米 为 同 胞 担 忧 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19048', '24', '4', '20', '毁 坏 的 信 息 连 络 不 绝 ， 因 为 全 地 荒 废 。 我 的 帐 棚 忽 然 毁 坏 ； 我 的 幔 子 顷 刻 破 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19049', '24', '4', '21', '我 看 见 大 旗 ， 听 见 角 声 ， 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19050', '24', '4', '22', '耶 和 华 说 ： 我 的 百 姓 愚 顽 ， 不 认 识 我 ； 他 们 是 愚 昧 无 知 的 儿 女 ， 有 智 慧 行 恶 ， 没 有 知 识 行 善 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19051', '24', '4', '23', '＜ 耶 利 米 的 异 象 ─ ─ 将 要 来 临 的 毁 灭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19052', '24', '4', '24', '我 观 看 大 山 ， 不 料 ， 尽 都 震 动 ， 小 山 也 都 摇 来 摇 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19053', '24', '4', '25', '我 观 看 ， 不 料 ， 无 人 ； 空 中 的 飞 鸟 也 都 躲 避 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19054', '24', '4', '26', '我 观 看 ， 不 料 ， 肥 田 变 为 荒 地 ； 一 切 城 邑 在 耶 和 华 面 前 ， 因 他 的 烈 怒 都 被 拆 毁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19055', '24', '4', '27', '耶 和 华 如 此 说 ： 全 地 必 然 荒 凉 ， 我 却 不 毁 灭 净 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19056', '24', '4', '28', '因 此 ， 地 要 悲 哀 ， 在 上 的 天 也 必 黑 暗 ； 因 为 我 言 已 出 ， 我 意 已 定 ， 必 不 后 悔 ， 也 不 转 意 不 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19057', '24', '4', '29', '各 城 的 人 因 马 兵 和 弓 箭 手 的 响 声 就 都 逃 跑 ， 进 入 密 林 ， 爬 上 磐 石 ； 各 城 被 撇 下 ， 无 人 住 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19058', '24', '4', '30', '你 凄 凉 的 时 候 要 怎 样 行 呢 ？ 你 虽 穿 上 朱 红 衣 服 ， 佩 戴 黄 金 装 饰 ， 用 颜 料 修 饰 眼 目 ， 这 样 标 致 是 枉 然 的 ！ 恋 爱 你 的 藐 视 你 ， 并 且 寻 索 你 的 性 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19059', '24', '4', '31', '我 听 见 有 声 音 ， 仿 佛 妇 人 产 难 的 声 音 ， 好 像 生 头 胎 疼 痛 的 声 音 ， 是 锡 安 女 子 ｛ 就 是 指 民 的 意 思 ｝ 的 声 音 ； 她 喘 着 气 、 挓 挲 手 ， 说 ： 我 有 祸 了 ！ 在 杀 人 的 跟 前 ， 我 的 心 发 昏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19060', '24', '5', '1', '＜ 耶 路 撒 冷 的 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19061', '24', '5', '2', '其 中 的 人 虽 然 指 着 永 生 的 耶 和 华 起 誓 ， 所 起 的 誓 实 在 是 假 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19062', '24', '5', '3', '耶 和 华 啊 ， 你 的 眼 目 不 是 看 顾 诚 实 吗 ？ 你 击 打 他 们 ， 他 们 却 不 伤 恸 ； 你 毁 灭 他 们 ， 他 们 仍 不 受 惩 治 。 他 们 使 脸 刚 硬 过 于 磐 石 ， 不 肯 回 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19063', '24', '5', '4', '我 说 ： 这 些 人 实 在 是 贫 穷 的 ， 是 愚 昧 的 ， 因 为 不 晓 得 耶 和 华 的 作 为 和 他 们 神 的 法 则 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19064', '24', '5', '5', '我 要 去 见 尊 大 的 人 ， 对 他 们 说 话 ， 因 为 他 们 晓 得 耶 和 华 的 作 为 和 他 们 神 的 法 则 。 哪 知 ， 这 些 人 齐 心 将 轭 折 断 ， 挣 开 绳 索 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19065', '24', '5', '6', '因 此 ， 林 中 的 狮 子 必 害 死 他 们 ； 晚 上 ｛ 或 译 ： 野 地 ｝ 的 豺 狼 必 灭 绝 他 们 ； 豹 子 要 在 城 外 窥 伺 他 们 。 凡 出 城 的 必 被 撕 碎 ； 因 为 他 们 的 罪 过 极 多 ， 背 道 的 事 也 加 增 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19066', '24', '5', '7', '我 怎 能 赦 免 你 呢 ？ 你 的 儿 女 离 弃 我 ， 又 指 着 那 不 是 神 的 起 誓 。 我 使 他 们 饱 足 ， 他 们 就 行 奸 淫 ， 成 群 地 聚 集 在 娼 妓 家 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19067', '24', '5', '8', '他 们 像 喂 饱 的 马 到 处 乱 跑 ， 各 向 他 邻 舍 的 妻 发 嘶 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19068', '24', '5', '9', '耶 和 华 说 ： 我 岂 不 因 这 些 事 讨 罪 呢 ？ 岂 不 报 复 这 样 的 国 民 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19069', '24', '5', '10', '你 们 要 上 她 葡 萄 园 的 墙 施 行 毁 坏 ， 但 不 可 毁 坏 净 尽 ， 只 可 除 掉 她 的 枝 子 ， 因 为 不 属 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19070', '24', '5', '11', '原 来 以 色 列 家 和 犹 大 家 大 行 诡 诈 攻 击 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19071', '24', '5', '12', '＜ 耶 和 华 丢 弃 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19072', '24', '5', '13', '先 知 的 话 必 成 为 风 ； 道 也 不 在 他 们 里 面 。 这 灾 必 临 到 他 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19073', '24', '5', '14', '所 以 耶 和 华 ─ ─ 万 军 之 神 如 此 说 ： 因 为 百 姓 说 这 话 ， 我 必 使 我 的 话 在 你 口 中 为 火 ， 使 他 们 为 柴 ； 这 火 便 将 他 们 烧 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19074', '24', '5', '15', '耶 和 华 说 ： 以 色 列 家 啊 ， 我 必 使 一 国 的 民 从 远 方 来 攻 击 你 ， 是 强 盛 的 国 ， 是 从 古 而 有 的 国 。 他 们 的 言 语 你 不 晓 得 ， 他 们 的 话 你 不 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19075', '24', '5', '16', '他 们 的 箭 袋 是 敞 开 的 坟 墓 ； 他 们 都 是 勇 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19076', '24', '5', '17', '他 们 必 吃 尽 你 的 庄 稼 和 你 的 粮 食 ， 是 你 儿 女 该 吃 的 ； 必 吃 尽 你 的 牛 羊 ， 吃 尽 你 的 葡 萄 和 无 花 果 ； 又 必 用 刀 毁 坏 你 所 倚 靠 的 坚 固 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19077', '24', '5', '18', '耶 和 华 说 ： “ 就 是 到 那 时 ， 我 也 不 将 你 们 毁 灭 净 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19078', '24', '5', '19', '百 姓 若 说 ： ‘ 耶 和 华 ─ ─ 我 们 的 神 为 什 么 向 我 们 行 这 一 切 事 呢 ？ ’ 你 就 对 他 们 说 ： ‘ 你 们 怎 样 离 弃 耶 和 华 ｛ 原 文 是 我 ｝ ， 在 你 们 的 地 上 事 奉 外 邦 神 ， 也 必 照 样 在 不 属 你 们 的 地 上 事 奉 外 邦 人 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19079', '24', '5', '20', '＜ 神 警 告 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19080', '24', '5', '21', '愚 昧 无 知 的 百 姓 啊 ， 你 们 有 眼 不 看 ， 有 耳 不 听 ， 现 在 当 听 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19081', '24', '5', '22', '耶 和 华 说 ： 你 们 怎 么 不 惧 怕 我 呢 ？ 我 以 永 远 的 定 例 ， 用 沙 为 海 的 界 限 ， 水 不 得 越 过 。 因 此 ， 你 们 在 我 面 前 还 不 战 兢 吗 ？ 波 浪 虽 然 翻 腾 ， 却 不 能 逾 越 ； 虽 然 匉 訇 ， 却 不 能 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19082', '24', '5', '23', '但 这 百 姓 有 背 叛 忤 逆 的 心 ； 他 们 叛 我 而 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19083', '24', '5', '24', '心 内 也 不 说 ： 我 们 应 当 敬 畏 耶 和 华 ─ ─ 我 们 的 神 ； 他 按 时 赐 雨 ， 就 是 秋 雨 春 雨 ， 又 为 我 们 定 收 割 的 节 令 ， 永 存 不 废 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19084', '24', '5', '25', '你 们 的 罪 孽 使 这 些 事 转 离 你 们 ； 你 们 的 罪 恶 使 你 们 不 能 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19085', '24', '5', '26', '因 为 在 我 民 中 有 恶 人 。 他 们 埋 伏 窥 探 ， 好 像 捕 鸟 的 人 ； 他 们 设 立 圈 套 陷 害 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19086', '24', '5', '27', '笼 内 怎 样 满 了 雀 鸟 ， 他 们 的 房 中 也 照 样 充 满 诡 诈 ； 所 以 他 们 得 成 为 大 ， 而 且 富 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19087', '24', '5', '28', '他 们 肥 胖 光 润 ， 作 恶 过 甚 ， 不 为 人 伸 冤 ！ 就 是 不 为 孤 儿 伸 冤 ， 不 使 他 亨 通 ， 也 不 为 穷 人 辨 屈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19088', '24', '5', '29', '耶 和 华 说 ： 我 岂 不 因 这 些 事 讨 罪 呢 ？ 岂 不 报 复 这 样 的 国 民 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19089', '24', '5', '30', '国 中 有 可 惊 骇 、 可 憎 恶 的 事 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19090', '24', '5', '31', '就 是 先 知 说 假 预 言 ， 祭 司 藉 他 们 把 持 权 柄 ； 我 的 百 姓 也 喜 爱 这 些 事 ， 到 了 结 局 你 们 怎 样 行 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19091', '24', '6', '1', '＜ 耶 路 撒 冷 受 敌 人 围 攻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19092', '24', '6', '2', '那 秀 美 娇 嫩 的 锡 安 女 子 ｛ 就 是 指 民 的 意 思 ｝ ， 我 必 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19093', '24', '6', '3', '牧 人 必 引 他 们 的 羊 群 到 她 那 里 ， 在 她 周 围 支 搭 帐 棚 ， 各 在 自 己 所 占 之 地 使 羊 吃 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19094', '24', '6', '4', '你 们 要 准 备 攻 击 她 。 起 来 吧 ， 我 们 可 以 趁 午 时 上 去 。 哀 哉 ！ 日 已 渐 斜 ， 晚 影 拖 长 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19095', '24', '6', '5', '起 来 吧 ， 我 们 夜 间 上 去 ， 毁 坏 她 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19096', '24', '6', '6', '因 为 万 军 之 耶 和 华 如 此 说 ： 你 们 要 砍 伐 树 木 ， 筑 垒 攻 打 耶 路 撒 冷 。 这 就 是 那 该 罚 的 城 ， 其 中 尽 是 欺 压 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19097', '24', '6', '7', '井 怎 样 涌 出 水 来 ， 这 城 也 照 样 涌 出 恶 来 ； 在 其 间 常 听 见 有 强 暴 毁 灭 的 事 ， 病 患 损 伤 也 常 在 我 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19098', '24', '6', '8', '耶 路 撒 冷 啊 ， 你 当 受 教 ， 免 得 我 心 与 你 生 疏 ， 免 得 我 使 你 荒 凉 ， 成 为 无 人 居 住 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19099', '24', '6', '9', '＜ 叛 逆 的 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19100', '24', '6', '10', '现 在 我 可 以 向 谁 说 话 作 见 证 ， 使 他 们 听 呢 ？ 他 们 的 耳 朵 未 受 割 礼 ， 不 能 听 见 。 看 哪 ， 耶 和 华 的 话 他 们 以 为 羞 辱 ， 不 以 为 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19101', '24', '6', '11', '因 此 我 被 耶 和 华 的 忿 怒 充 满 ， 难 以 含 忍 。 我 要 倾 在 街 中 的 孩 童 和 聚 会 的 少 年 人 身 上 ， 连 夫 带 妻 ， 并 年 老 的 与 日 子 满 足 的 都 必 被 擒 拿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19102', '24', '6', '12', '他 们 的 房 屋 、 田 地 ， 和 妻 子 都 必 转 归 别 人 ； 我 要 伸 手 攻 击 这 地 的 居 民 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19103', '24', '6', '13', '因 为 他 们 从 最 小 的 到 至 大 的 都 一 味 地 贪 婪 ， 从 先 知 到 祭 司 都 行 事 虚 谎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19104', '24', '6', '14', '他 们 轻 轻 忽 忽 地 医 治 我 百 姓 的 损 伤 ， 说 ： 平 安 了 ！ 平 安 了 ！ 其 实 没 有 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19105', '24', '6', '15', '他 们 行 可 憎 的 事 知 道 惭 愧 吗 ？ 不 然 ， 他 们 毫 不 惭 愧 ， 也 不 知 羞 耻 。 因 此 ， 他 们 必 在 仆 倒 的 人 中 仆 倒 ； 我 向 他 们 讨 罪 的 时 候 ， 他 们 必 致 跌 倒 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19106', '24', '6', '16', '＜ 以 色 列 拒 绝 神 的 道 路 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19107', '24', '6', '17', '我 设 立 守 望 的 人 照 管 你 们 ， 说 ： 要 听 角 声 。 他 们 却 说 ： 我 们 不 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19108', '24', '6', '18', '列 国 啊 ， 因 此 你 们 当 听 ！ 会 众 啊 ， 要 知 道 他 们 必 遭 遇 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19109', '24', '6', '19', '地 啊 ， 当 听 ！ 我 必 使 灾 祸 临 到 这 百 姓 ， 就 是 他 们 意 念 所 结 的 果 子 ； 因 为 他 们 不 听 从 我 的 言 语 ， 至 于 我 的 训 诲 ｛ 或 译 ： 律 法 ｝ ， 他 们 也 厌 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19110', '24', '6', '20', '从 示 巴 出 的 乳 香 ， 从 远 方 出 的 菖 蒲 ｛ 或 译 ： 甘 蔗 ｝ 奉 来 给 我 有 何 益 呢 ？ 你 们 的 燔 祭 不 蒙 悦 纳 ； 你 们 的 平 安 祭 ， 我 也 不 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19111', '24', '6', '21', '所 以 耶 和 华 如 此 说 ： 我 要 将 绊 脚 石 放 在 这 百 姓 前 面 。 父 亲 和 儿 子 要 一 同 跌 在 其 上 ； 邻 舍 与 朋 友 也 都 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19112', '24', '6', '22', '＜ 北 方 来 的 侵 略 者 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19113', '24', '6', '23', '他 们 拿 弓 和 枪 ， 性 情 残 忍 ， 不 施 怜 悯 ； 他 们 的 声 音 像 海 浪 匉 訇 。 锡 安 城 ｛ 原 文 是 女 子 ｝ 啊 ， 他 们 骑 马 都 摆 队 伍 ， 如 上 战 场 的 人 要 攻 击 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19114', '24', '6', '24', '我 们 听 见 他 们 的 风 声 ， 手 就 发 软 ； 痛 苦 将 我 们 抓 住 ， 疼 痛 仿 佛 产 难 的 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19115', '24', '6', '25', '你 们 不 要 往 田 野 去 ， 也 不 要 行 在 路 上 ， 因 四 围 有 仇 敌 的 刀 剑 和 惊 吓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19116', '24', '6', '26', '我 民 ｛ 原 文 是 民 女 ｝ 哪 ， 应 当 腰 束 麻 布 ， 滚 在 灰 中 。 你 要 悲 伤 ， 如 丧 独 生 子 痛 痛 哭 号 ， 因 为 灭 命 的 要 忽 然 临 到 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19117', '24', '6', '27', '我 使 你 在 我 民 中 为 高 台 ｛ 或 译 ： 试 验 人 的 ｝ ， 为 保 障 ， 使 你 知 道 试 验 他 们 的 行 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19118', '24', '6', '28', '他 们 都 是 极 悖 逆 的 ， 往 来 谗 谤 人 。 他 们 是 铜 是 铁 ， 都 行 坏 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19119', '24', '6', '29', '风 箱 吹 火 ， 铅 被 烧 毁 ； 他 们 炼 而 又 炼 ， 终 是 徒 然 ； 因 为 恶 劣 的 还 未 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19120', '24', '6', '30', '人 必 称 他 们 为 被 弃 的 银 渣 ， 因 为 耶 和 华 已 经 弃 掉 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19121', '24', '7', '1', '＜ 耶 利 米 在 圣 殿 讲 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19122', '24', '7', '2', '“ 你 当 站 在 耶 和 华 殿 的 门 口 ， 在 那 里 宣 传 这 话 说 ： 你 们 进 这 些 门 敬 拜 耶 和 华 的 一 切 犹 大 人 ， 当 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19123', '24', '7', '3', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 们 改 正 行 动 作 为 ， 我 就 使 你 们 在 这 地 方 仍 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19124', '24', '7', '4', '你 们 不 要 倚 靠 虚 谎 的 话 ， 说 ： ‘ 这 些 是 耶 和 华 的 殿 ， 是 耶 和 华 的 殿 ， 是 耶 和 华 的 殿 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19125', '24', '7', '5', '“ 你 们 若 实 在 改 正 行 动 作 为 ， 在 人 和 邻 舍 中 间 诚 然 施 行 公 平 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19126', '24', '7', '6', '不 欺 压 寄 居 的 和 孤 儿 寡 妇 ， 在 这 地 方 不 流 无 辜 人 的 血 ， 也 不 随 从 别 神 陷 害 自 己 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19127', '24', '7', '7', '我 就 使 你 们 在 这 地 方 仍 然 居 住 ， 就 是 我 古 时 所 赐 给 你 们 列 祖 的 地 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19128', '24', '7', '8', '“ 看 哪 ， 你 们 倚 靠 虚 谎 无 益 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19129', '24', '7', '9', '你 们 偷 盗 ， 杀 害 ， 奸 淫 ， 起 假 誓 ， 向 巴 力 烧 香 ， 并 随 从 素 不 认 识 的 别 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19130', '24', '7', '10', '且 来 到 这 称 为 我 名 下 的 殿 ， 在 我 面 前 敬 拜 ； 又 说 ： ‘ 我 们 可 以 自 由 了 。 ’ 你 们 这 样 的 举 动 是 要 行 那 些 可 憎 的 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19131', '24', '7', '11', '这 称 为 我 名 下 的 殿 在 你 们 眼 中 岂 可 看 为 贼 窝 吗 ？ 我 都 看 见 了 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19132', '24', '7', '12', '你 们 且 往 示 罗 去 ， 就 是 我 先 前 立 为 我 名 的 居 所 ， 察 看 我 因 这 百 姓 以 色 列 的 罪 恶 向 那 地 所 行 的 如 何 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19133', '24', '7', '13', '耶 和 华 说 ： “ 现 在 因 你 们 行 了 这 一 切 的 事 ， 我 也 从 早 起 来 警 戒 你 们 ， 你 们 却 不 听 从 ； 呼 唤 你 们 ， 你 们 却 不 答 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19134', '24', '7', '14', '所 以 我 要 向 这 称 为 我 名 下 、 你 们 所 倚 靠 的 殿 ， 与 我 所 赐 给 你 们 和 你 们 列 祖 的 地 施 行 ， 照 我 从 前 向 示 罗 所 行 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19135', '24', '7', '15', '我 必 将 你 们 从 我 眼 前 赶 出 ， 正 如 赶 出 你 们 的 众 弟 兄 ， 就 是 以 法 莲 的 一 切 后 裔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19136', '24', '7', '16', '＜ 人 民 违 背 命 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19137', '24', '7', '17', '他 们 在 犹 大 城 邑 中 和 耶 路 撒 冷 街 上 所 行 的 ， 你 没 有 看 见 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19138', '24', '7', '18', '孩 子 捡 柴 ， 父 亲 烧 火 ， 妇 女 抟 面 做 饼 ， 献 给 天 后 ， 又 向 别 神 浇 奠 祭 ， 惹 我 发 怒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19139', '24', '7', '19', '耶 和 华 说 ： “ 他 们 岂 是 惹 我 发 怒 呢 ？ 不 是 自 己 惹 祸 ， 以 致 脸 上 惭 愧 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19140', '24', '7', '20', '所 以 主 耶 和 华 如 此 说 ： “ 看 哪 ， 我 必 将 我 的 怒 气 和 忿 怒 倾 在 这 地 方 的 人 和 牲 畜 身 上 ， 并 田 野 的 树 木 和 地 里 的 出 产 上 ， 必 如 火 着 起 ， 不 能 熄 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19141', '24', '7', '21', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： “ 你 们 将 燔 祭 加 在 平 安 祭 上 ， 吃 肉 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19142', '24', '7', '22', '因 为 我 将 你 们 列 祖 从 埃 及 地 领 出 来 的 那 日 ， 燔 祭 平 安 祭 的 事 我 并 没 有 提 说 ， 也 没 有 吩 咐 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19143', '24', '7', '23', '我 只 吩 咐 他 们 这 一 件 说 ： ‘ 你 们 当 听 从 我 的 话 ， 我 就 作 你 们 的 神 ， 你 们 也 作 我 的 子 民 。 你 们 行 我 所 吩 咐 的 一 切 道 ， 就 可 以 得 福 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19144', '24', '7', '24', '他 们 却 不 听 从 ， 不 侧 耳 而 听 ， 竟 随 从 自 己 的 计 谋 和 顽 梗 的 恶 心 ， 向 后 不 向 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19145', '24', '7', '25', '自 从 你 们 列 祖 出 埃 及 地 的 那 日 ， 直 到 今 日 ， 我 差 遣 我 的 仆 人 众 先 知 到 你 们 那 里 去 ， 每 日 从 早 起 来 差 遣 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19146', '24', '7', '26', '你 们 却 不 听 从 ， 不 侧 耳 而 听 ， 竟 硬 着 颈 项 行 恶 ， 比 你 们 列 祖 更 甚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19147', '24', '7', '27', '“ 你 要 将 这 一 切 的 话 告 诉 他 们 ， 他 们 却 不 听 从 ； 呼 唤 他 们 ， 他 们 却 不 答 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19148', '24', '7', '28', '你 要 对 他 们 说 ： 这 就 是 不 听 从 耶 和 华 ─ ─ 他 们 神 的 话 、 不 受 教 训 的 国 民 ； 从 他 们 的 口 中 ， 诚 实 灭 绝 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19149', '24', '7', '29', '＜ 在 欣 嫩 子 谷 的 罪 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19150', '24', '7', '30', '耶 和 华 说 ： “ 犹 大 人 行 我 眼 中 看 为 恶 的 事 ， 将 可 憎 之 物 设 立 在 称 为 我 名 下 的 殿 中 ， 污 秽 这 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19151', '24', '7', '31', '他 们 在 欣 嫩 子 谷 建 筑 陀 斐 特 的 邱 坛 ， 好 在 火 中 焚 烧 自 己 的 儿 女 。 这 并 不 是 我 所 吩 咐 的 ， 也 不 是 我 心 所 起 的 意 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19152', '24', '7', '32', '耶 和 华 说 ： “ 因 此 ， 日 子 将 到 ， 这 地 方 不 再 称 为 陀 斐 特 和 欣 嫩 子 谷 ， 反 倒 称 为 杀 戮 谷 。 因 为 要 在 陀 斐 特 葬 埋 尸 首 ， 甚 至 无 处 可 葬 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19153', '24', '7', '33', '并 且 这 百 姓 的 尸 首 必 给 空 中 的 飞 鸟 和 地 上 的 野 兽 作 食 物 ， 并 无 人 哄 赶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19154', '24', '7', '34', '那 时 ， 我 必 使 犹 大 城 邑 中 和 耶 路 撒 冷 街 上 ， 欢 喜 和 快 乐 的 声 音 ， 新 郎 和 新 妇 的 声 音 ， 都 止 息 了 ， 因 为 地 必 成 为 荒 场 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19155', '24', '8', '1', '耶 和 华 说 ： “ 到 那 时 ， 人 必 将 犹 大 王 的 骸 骨 和 他 首 领 的 骸 骨 、 祭 司 的 骸 骨 、 先 知 的 骸 骨 ， 并 耶 路 撒 冷 居 民 的 骸 骨 ， 都 从 坟 墓 中 取 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19156', '24', '8', '2', '抛 散 在 日 头 、 月 亮 ， 和 天 上 众 星 之 下 ， 就 是 他 们 从 前 所 喜 爱 、 所 事 奉 、 所 随 从 、 所 求 问 、 所 敬 拜 的 。 这 些 骸 骨 不 再 收 殓 ， 不 再 葬 埋 ， 必 在 地 面 上 成 为 粪 土 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19157', '24', '8', '3', '并 且 这 恶 族 所 剩 下 的 民 在 我 所 赶 他 们 到 的 各 处 ， 宁 可 拣 死 不 拣 生 。 这 是 万 军 之 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19158', '24', '8', '4', '＜ 罪 与 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19159', '24', '8', '5', '这 耶 路 撒 冷 的 民 ， 为 何 恒 久 背 道 呢 ？ 他 们 守 定 诡 诈 ， 不 肯 回 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19160', '24', '8', '6', '我 留 心 听 ， 听 见 他 们 说 不 正 直 的 话 。 无 人 悔 改 恶 行 ， 说 ： 我 做 的 是 什 么 呢 ？ 他 们 各 人 转 奔 己 路 ， 如 马 直 闯 战 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19161', '24', '8', '7', '空 中 的 鹳 鸟 知 道 来 去 的 定 期 ； 斑 鸠 燕 子 与 白 鹤 也 守 候 当 来 的 时 令 ； 我 的 百 姓 却 不 知 道 耶 和 华 的 法 则 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19162', '24', '8', '8', '你 们 怎 么 说 ： 我 们 有 智 慧 ， 耶 和 华 的 律 法 在 我 们 这 里 ？ 看 哪 ， 文 士 的 假 笔 舞 弄 虚 假 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19163', '24', '8', '9', '智 慧 人 惭 愧 ， 惊 惶 ， 被 擒 拿 ； 他 们 弃 掉 耶 和 华 的 话 ， 心 里 还 有 什 么 智 慧 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19164', '24', '8', '10', '所 以 我 必 将 他 们 的 妻 子 给 别 人 ， 将 他 们 的 田 地 给 别 人 为 业 ； 因 为 他 们 从 最 小 的 到 至 大 的 都 一 味 地 贪 婪 ， 从 先 知 到 祭 司 都 行 事 虚 谎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19165', '24', '8', '11', '他 们 轻 轻 忽 忽 地 医 治 我 百 姓 的 损 伤 ， 说 ： 平 安 了 ！ 平 安 了 ！ 其 实 没 有 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19166', '24', '8', '12', '他 们 行 可 憎 的 事 知 道 惭 愧 吗 ？ 不 然 ， 他 们 毫 不 惭 愧 ， 也 不 知 羞 耻 。 因 此 他 们 必 在 仆 倒 的 人 中 仆 倒 ； 我 向 他 们 讨 罪 的 时 候 ， 他 们 必 致 跌 倒 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19167', '24', '8', '13', '耶 和 华 说 ： 我 必 使 他 们 全 然 灭 绝 ； 葡 萄 树 上 必 没 有 葡 萄 ， 无 花 果 树 上 必 没 有 果 子 ， 叶 子 也 必 枯 干 。 我 所 赐 给 他 们 的 ， 必 离 开 他 们 过 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19168', '24', '8', '14', '我 们 为 何 静 坐 不 动 呢 ？ 我 们 当 聚 集 ， 进 入 坚 固 城 ， 在 那 里 静 默 不 言 ； 因 为 耶 和 华 ─ ─ 我 们 的 神 使 我 们 静 默 不 言 ， 又 将 苦 胆 水 给 我 们 喝 ， 都 因 我 们 得 罪 了 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19169', '24', '8', '15', '我 们 指 望 平 安 ， 却 得 不 着 好 处 ； 指 望 痊 愈 的 时 候 ， 不 料 ， 受 了 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19170', '24', '8', '16', '听 见 从 但 那 里 敌 人 的 马 喷 鼻 气 ， 他 的 壮 马 发 嘶 声 ， 全 地 就 都 震 动 ； 因 为 他 们 来 吞 灭 这 地 和 其 上 所 有 的 ， 吞 灭 这 城 与 其 中 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19171', '24', '8', '17', '看 哪 ， 我 必 使 毒 蛇 到 你 们 中 间 ， 是 不 服 法 术 的 ， 必 咬 你 们 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19172', '24', '8', '18', '＜ 耶 利 米 为 同 胞 悲 伤 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19173', '24', '8', '19', '听 啊 ， 是 我 百 姓 的 哀 声 从 极 远 之 地 而 来 ， 说 ： 耶 和 华 不 在 锡 安 吗 ？ 锡 安 的 王 不 在 其 中 吗 ？ 耶 和 华 说 ： 他 们 为 什 么 以 雕 刻 的 偶 像 和 外 邦 虚 无 的 神 惹 我 发 怒 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19174', '24', '8', '20', '麦 秋 已 过 ， 夏 令 已 完 ， 我 们 还 未 得 救 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19175', '24', '8', '21', '先 知 说 ： 因 我 百 姓 的 损 伤 ， 我 也 受 了 损 伤 。 我 哀 痛 ， 惊 惶 将 我 抓 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19176', '24', '8', '22', '在 基 列 岂 没 有 乳 香 呢 ？ 在 那 里 岂 没 有 医 生 呢 ？ 我 百 姓 为 何 不 得 痊 愈 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19177', '24', '9', '1', '但 愿 我 的 头 为 水 ， 我 的 眼 为 泪 的 泉 源 ， 我 好 为 我 百 姓 ｛ 原 文 是 民 女 ； 七 节 同 ｝ 中 被 杀 的 人 昼 夜 哭 泣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19178', '24', '9', '2', '惟 愿 我 在 旷 野 有 行 路 人 住 宿 之 处 ， 使 我 可 以 离 开 我 的 民 出 去 ； 因 他 们 都 是 行 奸 淫 的 ， 是 行 诡 诈 的 一 党 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19179', '24', '9', '3', '他 们 弯 起 舌 头 像 弓 一 样 ， 为 要 说 谎 话 。 他 们 在 国 中 增 长 势 力 ， 不 是 为 行 诚 实 ， 乃 是 恶 上 加 恶 ， 并 不 认 识 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19180', '24', '9', '4', '你 们 各 人 当 谨 防 邻 舍 ， 不 可 信 靠 弟 兄 ； 因 为 弟 兄 尽 行 欺 骗 ， 邻 舍 都 往 来 谗 谤 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19181', '24', '9', '5', '他 们 各 人 欺 哄 邻 舍 ， 不 说 真 话 ； 他 们 教 舌 头 学 习 说 谎 ， 劳 劳 碌 碌 地 作 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19182', '24', '9', '6', '你 的 住 处 在 诡 诈 的 人 中 ； 他 们 因 行 诡 诈 ， 不 肯 认 识 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19183', '24', '9', '7', '所 以 万 军 之 耶 和 华 如 此 说 ： 看 哪 ， 我 要 将 他 们 镕 化 熬 炼 ； 不 然 ， 我 因 我 百 姓 的 罪 该 怎 样 行 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19184', '24', '9', '8', '他 们 的 舌 头 是 毒 箭 ， 说 话 诡 诈 ； 人 与 邻 舍 口 说 和 平 话 ， 心 却 谋 害 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19185', '24', '9', '9', '耶 和 华 说 ： 我 岂 不 因 这 些 事 讨 他 们 的 罪 呢 ？ 岂 不 报 复 这 样 的 国 民 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19186', '24', '9', '10', '我 要 为 山 岭 哭 泣 悲 哀 ， 为 旷 野 的 草 场 扬 声 哀 号 ； 因 为 都 已 干 焦 ， 甚 至 无 人 经 过 。 人 也 听 不 见 牲 畜 鸣 叫 ， 空 中 的 飞 鸟 和 地 上 的 野 兽 都 已 逃 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19187', '24', '9', '11', '我 必 使 耶 路 撒 冷 变 为 乱 堆 ， 为 野 狗 的 住 处 ， 也 必 使 犹 大 的 城 邑 变 为 荒 场 ， 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19188', '24', '9', '12', '谁 是 智 慧 人 ， 可 以 明 白 这 事 ？ 耶 和 华 的 口 向 谁 说 过 ， 使 他 可 以 传 说 ？ 遍 地 为 何 灭 亡 ， 干 焦 好 像 旷 野 ， 甚 至 无 人 经 过 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19189', '24', '9', '13', '耶 和 华 说 ： “ 因 为 这 百 姓 离 弃 我 ， 在 他 们 面 前 所 设 立 的 律 法 没 有 遵 行 ， 也 没 有 听 从 我 的 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19190', '24', '9', '14', '只 随 从 自 己 顽 梗 的 心 行 事 ， 照 他 们 列 祖 所 教 训 的 随 从 众 巴 力 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19191', '24', '9', '15', '所 以 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： “ 看 哪 ， 我 必 将 茵 蔯 给 这 百 姓 吃 ， 又 将 苦 胆 水 给 他 们 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19192', '24', '9', '16', '我 要 把 他 们 散 在 列 邦 中 ， 就 是 他 们 和 他 们 列 祖 素 不 认 识 的 列 邦 。 我 也 要 使 刀 剑 追 杀 他 们 ， 直 到 将 他 们 灭 尽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19193', '24', '9', '17', '＜ 耶 路 撒 冷 哀 求 援 助 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19194', '24', '9', '18', '叫 她 们 速 速 为 我 们 举 哀 ， 使 我 们 眼 泪 汪 汪 ， 使 我 们 的 眼 皮 涌 出 水 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19195', '24', '9', '19', '因 为 听 见 哀 声 出 于 锡 安 ， 说 ： 我 们 怎 样 败 落 了 ！ 我 们 大 大 地 惭 愧 ！ 我 们 撇 下 地 土 ； 人 也 拆 毁 了 我 们 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19196', '24', '9', '20', '妇 女 们 哪 ， 你 们 当 听 耶 和 华 的 话 ， 领 受 他 口 中 的 言 语 ； 又 当 教 导 你 们 的 儿 女 举 哀 ， 各 人 教 导 邻 舍 唱 哀 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19197', '24', '9', '21', '因 为 死 亡 上 来 ， 进 了 我 们 的 窗 户 ， 入 了 我 们 的 宫 殿 ； 要 从 外 边 剪 除 孩 童 ， 从 街 上 剪 除 少 年 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19198', '24', '9', '22', '你 当 说 ， 耶 和 华 如 此 说 ： 人 的 尸 首 必 倒 在 田 野 像 粪 土 ， 又 像 收 割 的 人 遗 落 的 一 把 禾 稼 ， 无 人 收 取 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19199', '24', '9', '23', '耶 和 华 如 此 说 ： “ 智 慧 人 不 要 因 他 的 智 慧 夸 口 ， 勇 士 不 要 因 他 的 勇 力 夸 口 ， 财 主 不 要 因 他 的 财 物 夸 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19200', '24', '9', '24', '夸 口 的 却 因 他 有 聪 明 ， 认 识 我 是 耶 和 华 ， 又 知 道 我 喜 悦 在 世 上 施 行 慈 爱 、 公 平 ， 和 公 义 ， 以 此 夸 口 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19201', '24', '9', '25', '耶 和 华 说 ： “ 看 哪 ， 日 子 将 到 ， 我 要 刑 罚 一 切 受 过 割 礼 、 心 却 未 受 割 礼 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19202', '24', '9', '26', '就 是 埃 及 、 犹 大 、 以 东 、 亚 扪 人 、 摩 押 人 ， 和 一 切 住 在 旷 野 剃 周 围 头 发 的 ； 因 为 列 国 人 都 没 有 受 割 礼 ， 以 色 列 人 心 中 也 没 有 受 割 礼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19203', '24', '10', '1', '＜ 拜 偶 像 和 真 崇 拜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19204', '24', '10', '2', '耶 和 华 如 此 说 ： 你 们 不 要 效 法 列 国 的 行 为 ， 也 不 要 为 天 象 惊 惶 ， 因 列 国 为 此 事 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19205', '24', '10', '3', '众 民 的 风 俗 是 虚 空 的 ； 他 们 在 树 林 中 用 斧 子 砍 伐 一 棵 树 ， 匠 人 用 手 工 造 成 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19206', '24', '10', '4', '他 们 用 金 银 妆 饰 它 ， 用 钉 子 和 锤 子 钉 稳 ， 使 它 不 动 摇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19207', '24', '10', '5', '它 好 像 棕 树 ， 是 镟 成 的 ， 不 能 说 话 ， 不 能 行 走 ， 必 须 有 人 抬 着 。 你 们 不 要 怕 它 ； 它 不 能 降 祸 ， 也 无 力 降 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19208', '24', '10', '6', '耶 和 华 啊 ， 没 有 能 比 你 的 ！ 你 本 为 大 ， 有 大 能 大 力 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19209', '24', '10', '7', '万 国 的 王 啊 ， 谁 不 敬 畏 你 ？ 敬 畏 你 本 是 合 宜 的 ； 因 为 在 列 国 的 智 慧 人 中 ， 虽 有 政 权 的 尊 荣 ， 也 不 能 比 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19210', '24', '10', '8', '他 们 尽 都 是 畜 类 ， 是 愚 昧 的 。 偶 像 的 训 诲 算 什 么 呢 ？ 偶 像 不 过 是 木 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19211', '24', '10', '9', '有 银 子 打 成 片 ， 是 从 他 施 带 来 的 ， 并 有 从 乌 法 来 的 金 子 ， 都 是 匠 人 和 银 匠 的 手 工 ， 又 有 蓝 色 紫 色 料 的 衣 服 ， 都 是 巧 匠 的 工 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19212', '24', '10', '10', '惟 耶 和 华 是 真 神 ， 是 活 神 ， 是 永 远 的 王 。 他 一 发 怒 ， 大 地 震 动 ； 他 一 恼 恨 ， 列 国 都 担 当 不 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19213', '24', '10', '11', '（ 你 们 要 对 他 们 如 此 说 ： 不 是 那 创 造 天 地 的 神 ， 必 从 地 上 从 天 下 被 除 灭 ！ ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19214', '24', '10', '12', '＜ 颂 赞 神 的 诗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19215', '24', '10', '13', '他 一 发 声 ， 空 中 便 有 多 水 激 动 ； 他 使 云 雾 从 地 极 上 腾 ； 他 造 电 随 雨 而 闪 ， 从 他 府 库 中 带 出 风 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19216', '24', '10', '14', '各 人 都 成 了 畜 类 ， 毫 无 知 识 ； 各 银 匠 都 因 他 雕 刻 的 偶 像 羞 愧 。 他 所 铸 的 偶 像 本 是 虚 假 的 ， 其 中 并 无 气 息 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19217', '24', '10', '15', '都 是 虚 无 的 ， 是 迷 惑 人 的 工 作 ； 到 追 讨 的 时 候 必 被 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19218', '24', '10', '16', '雅 各 的 分 不 像 这 些 ， 因 他 是 造 作 万 有 的 主 。 以 色 列 也 是 他 产 业 的 支 派 ， 万 军 之 耶 和 华 是 他 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19219', '24', '10', '17', '＜ 预 告 流 亡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19220', '24', '10', '18', '因 为 耶 和 华 如 此 说 ： 这 时 候 ， 我 必 将 此 地 的 居 民 ， 好 像 用 机 弦 甩 出 去 ， 又 必 加 害 在 他 们 身 上 ， 使 他 们 觉 悟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19221', '24', '10', '19', '民 说 ： 祸 哉 ！ 我 受 损 伤 ； 我 的 伤 痕 极 其 重 大 。 我 却 说 ： 这 真 是 我 的 痛 苦 ， 必 须 忍 受 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19222', '24', '10', '20', '我 的 帐 棚 毁 坏 ； 我 的 绳 索 折 断 。 我 的 儿 女 离 我 出 去 ， 没 有 了 。 无 人 再 支 搭 我 的 帐 棚 ， 挂 起 我 的 幔 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19223', '24', '10', '21', '因 为 牧 人 都 成 为 畜 类 ， 没 有 求 问 耶 和 华 ， 所 以 不 得 顺 利 ； 他 们 的 羊 群 也 都 分 散 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19224', '24', '10', '22', '有 风 声 ！ 看 哪 ， 敌 人 来 了 ！ 有 大 扰 乱 从 北 方 出 来 ， 要 使 犹 大 城 邑 变 为 荒 凉 ， 成 为 野 狗 的 住 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19225', '24', '10', '23', '耶 和 华 啊 ， 我 晓 得 人 的 道 路 不 由 自 己 ， 行 路 的 人 也 不 能 定 自 己 的 脚 步 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19226', '24', '10', '24', '耶 和 华 啊 ， 求 你 从 宽 惩 治 我 ， 不 要 在 你 的 怒 中 惩 治 我 ， 恐 怕 使 我 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19227', '24', '10', '25', '愿 你 将 忿 怒 倾 在 不 认 识 你 的 列 国 中 ， 和 不 求 告 你 名 的 各 族 上 ； 因 为 他 们 吞 了 雅 各 ， 不 但 吞 了 ， 而 且 灭 绝 ， 把 他 的 住 处 变 为 荒 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19228', '24', '11', '1', '＜ 耶 利 米 和 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19229', '24', '11', '2', '“ 当 听 这 约 的 话 ， 告 诉 犹 大 人 和 耶 路 撒 冷 的 居 民 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19230', '24', '11', '3', '对 他 们 说 ， 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 不 听 从 这 约 之 话 的 人 必 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19231', '24', '11', '4', '这 约 是 我 将 你 们 列 祖 从 埃 及 地 领 出 来 、 脱 离 铁 炉 的 那 日 所 吩 咐 他 们 的 ， 说 ： ‘ 你 们 要 听 从 我 的 话 ， 照 我 一 切 所 吩 咐 的 去 行 。 ’ 这 样 ， 你 们 就 作 我 的 子 民 ， 我 也 作 你 们 的 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19232', '24', '11', '5', '我 好 坚 定 向 你 们 列 祖 所 起 的 誓 ， 给 他 们 流 奶 与 蜜 之 地 ， 正 如 今 日 一 样 。 ” 我 就 回 答 说 ： “ 耶 和 华 啊 ， 阿 们 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19233', '24', '11', '6', '耶 和 华 对 我 说 ： “ 你 要 在 犹 大 城 邑 中 和 耶 路 撒 冷 街 市 上 ， 宣 告 这 一 切 话 说 ： 你 们 当 听 从 遵 行 这 约 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19234', '24', '11', '7', '因 为 我 将 你 们 列 祖 从 埃 及 地 领 出 来 的 那 日 ， 直 到 今 日 ， 都 是 从 早 起 来 ， 切 切 诰 诫 他 们 说 ： ‘ 你 们 当 听 从 我 的 话 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19235', '24', '11', '8', '他 们 却 不 听 从 ， 不 侧 耳 而 听 ， 竟 随 从 自 己 顽 梗 的 恶 心 去 行 。 所 以 我 使 这 约 中 一 切 咒 诅 的 话 临 到 他 们 身 上 ； 这 约 是 我 吩 咐 他 们 行 的 ， 他 们 却 不 去 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19236', '24', '11', '9', '耶 和 华 对 我 说 ： “ 在 犹 大 人 和 耶 路 撒 冷 居 民 中 有 同 谋 背 叛 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19237', '24', '11', '10', '他 们 转 去 效 法 他 们 的 先 祖 ， 不 肯 听 我 的 话 ， 犯 罪 作 孽 ， 又 随 从 别 神 ， 事 奉 它 。 以 色 列 家 和 犹 大 家 背 了 我 与 他 们 列 祖 所 立 的 约 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19238', '24', '11', '11', '所 以 耶 和 华 如 此 说 ： “ 我 必 使 灾 祸 临 到 他 们 ， 是 他 们 不 能 逃 脱 的 。 他 们 必 向 我 哀 求 ， 我 却 不 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19239', '24', '11', '12', '那 时 ， 犹 大 城 邑 的 人 和 耶 路 撒 冷 的 居 民 要 去 哀 求 他 们 烧 香 所 供 奉 的 神 ； 只 是 遭 难 的 时 候 ， 这 些 神 毫 不 拯 救 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19240', '24', '11', '13', '犹 大 啊 ， 你 神 的 数 目 与 你 城 的 数 目 相 等 ； 你 为 那 可 耻 的 巴 力 所 筑 烧 香 的 坛 也 与 耶 路 撒 冷 街 道 的 数 目 相 等 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19241', '24', '11', '14', '“ 所 以 你 不 要 为 这 百 姓 祈 祷 ， 不 要 为 他 们 呼 求 祷 告 ； 因 为 他 们 遭 难 向 我 哀 求 的 时 候 ， 我 必 不 应 允 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19242', '24', '11', '15', '我 所 亲 爱 的 ， 既 行 许 多 淫 乱 ， 圣 肉 也 离 了 你 ， 你 在 我 殿 中 做 什 么 呢 ？ 你 作 恶 就 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19243', '24', '11', '16', '从 前 耶 和 华 给 你 起 名 叫 青 橄 榄 树 ， 又 华 美 又 结 好 果 子 ； 如 今 他 用 哄 嚷 之 声 ， 点 火 在 其 上 ， 枝 子 也 被 折 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19244', '24', '11', '17', '原 来 栽 培 你 的 万 军 之 耶 和 华 已 经 说 ， 要 降 祸 攻 击 你 ， 是 因 以 色 列 家 和 犹 大 家 行 恶 ， 向 巴 力 烧 香 ， 惹 我 发 怒 ， 是 自 作 自 受 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19245', '24', '11', '18', '＜ 杀 害 耶 利 米 的 阴 谋 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19246', '24', '11', '19', '我 却 像 柔 顺 的 羊 羔 被 牵 到 宰 杀 之 地 ； 我 并 不 知 道 他 们 设 计 谋 害 我 ， 说 ： 我 们 把 树 连 果 子 都 灭 了 吧 ！ 将 他 从 活 人 之 地 剪 除 ， 使 他 的 名 不 再 被 纪 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19247', '24', '11', '20', '按 公 义 判 断 、 察 验 人 肺 腑 心 肠 的 万 军 之 耶 和 华 啊 ， 我 却 要 见 你 在 他 们 身 上 报 仇 ， 因 我 将 我 的 案 件 向 你 禀 明 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19248', '24', '11', '21', '所 以 ， 耶 和 华 论 到 寻 索 你 命 的 亚 拿 突 人 如 此 说 ： “ 他 们 说 ： 你 不 要 奉 耶 和 华 的 名 说 预 言 ， 免 得 你 死 在 我 们 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19249', '24', '11', '22', '所 以 万 军 之 耶 和 华 如 此 说 ： 看 哪 ， 我 必 刑 罚 他 们 ； 他 们 的 少 年 人 必 被 刀 剑 杀 死 ， 他 们 的 儿 女 必 因 饥 荒 灭 亡 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19250', '24', '11', '23', '并 且 没 有 余 剩 的 人 留 给 他 们 ； 因 为 在 追 讨 之 年 ， 我 必 使 灾 祸 临 到 亚 拿 突 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19251', '24', '12', '1', '＜ 耶 利 米 询 问 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19252', '24', '12', '2', '你 栽 培 了 他 们 ， 他 们 也 扎 了 根 ， 长 大 ， 而 且 结 果 。 他 们 的 口 是 与 你 相 近 ， 心 却 与 你 远 离 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19253', '24', '12', '3', '耶 和 华 啊 ， 你 晓 得 我 ， 看 见 我 ， 察 验 我 向 你 是 怎 样 的 心 。 求 你 将 他 们 拉 出 来 ， 好 像 将 宰 的 羊 ， 叫 他 们 等 候 杀 戮 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19254', '24', '12', '4', '这 地 悲 哀 ， 通 国 的 青 草 枯 干 ， 要 到 几 时 呢 ？ 因 其 上 居 民 的 恶 行 ， 牲 畜 和 飞 鸟 都 灭 绝 了 。 他 们 曾 说 ： 他 看 不 见 我 们 的 结 局 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19255', '24', '12', '5', '耶 和 华 说 ： 你 若 与 步 行 的 人 同 跑 ， 尚 且 觉 累 ， 怎 能 与 马 赛 跑 呢 ？ 你 在 平 安 之 地 ， 虽 然 安 稳 ， 在 约 旦 河 边 的 丛 林 要 怎 样 行 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19256', '24', '12', '6', '因 为 连 你 弟 兄 和 你 父 家 都 用 奸 诈 待 你 。 他 们 也 在 你 后 边 大 声 喊 叫 ， 虽 向 你 说 好 话 ， 你 也 不 要 信 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19257', '24', '12', '7', '＜ 耶 和 华 为 他 的 子 民 忧 伤 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19258', '24', '12', '8', '我 的 产 业 向 我 如 林 中 的 狮 子 ， 她 发 声 攻 击 我 ， 因 此 我 恨 恶 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19259', '24', '12', '9', '我 的 产 业 向 我 岂 如 斑 点 的 鸷 鸟 呢 ？ 鸷 鸟 岂 在 她 四 围 攻 击 她 呢 ？ 你 们 要 去 聚 集 田 野 的 百 兽 ， 带 来 吞 吃 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19260', '24', '12', '10', '许 多 牧 人 毁 坏 我 的 葡 萄 园 ， 践 踏 我 的 分 ， 使 我 美 好 的 分 变 为 荒 凉 的 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19261', '24', '12', '11', '他 们 使 地 荒 凉 ； 地 既 荒 凉 ， 便 向 我 悲 哀 。 全 地 荒 凉 ， 因 无 人 介 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19262', '24', '12', '12', '灭 命 的 都 来 到 旷 野 中 一 切 净 光 的 高 处 ； 耶 和 华 的 刀 从 地 这 边 直 到 地 那 边 尽 行 杀 灭 。 凡 有 血 气 的 都 不 得 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19263', '24', '12', '13', '他 们 种 的 是 麦 子 ， 收 的 是 荆 棘 ； 劳 劳 苦 苦 却 毫 无 益 处 。 因 耶 和 华 的 烈 怒 ， 你 们 必 为 自 己 的 土 产 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19264', '24', '12', '14', '＜ 耶 和 华 对 以 色 列 邻 国 的 许 诺 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19265', '24', '12', '15', '我 拔 出 他 们 以 后 ， 我 必 转 过 来 怜 悯 他 们 ， 把 他 们 再 带 回 来 ， 各 归 本 业 ， 各 归 故 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19266', '24', '12', '16', '他 们 若 殷 勤 学 习 我 百 姓 的 道 ， 指 着 我 的 名 起 誓 说 ： ‘ 我 指 着 永 生 的 耶 和 华 起 誓 ’ ， 正 如 他 们 从 前 教 我 百 姓 指 着 巴 力 起 誓 ， 他 们 就 必 建 立 在 我 百 姓 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19267', '24', '12', '17', '他 们 若 是 不 听 ， 我 必 拔 出 那 国 ， 拔 出 而 且 毁 灭 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19268', '24', '13', '1', '＜ 腰 带 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19269', '24', '13', '2', '我 就 照 着 耶 和 华 的 话 ， 买 了 一 根 带 子 束 腰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19270', '24', '13', '3', '耶 和 华 的 话 第 二 次 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19271', '24', '13', '4', '“ 要 拿 着 你 所 买 的 腰 带 ， 就 是 你 腰 上 的 带 子 ， 起 来 往 幼 发 拉 底 河 去 ， 将 腰 带 藏 在 那 里 的 磐 石 穴 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19272', '24', '13', '5', '我 就 去 ， 照 着 耶 和 华 所 吩 咐 我 的 ， 将 腰 带 藏 在 幼 发 拉 底 河 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19273', '24', '13', '6', '过 了 多 日 ， 耶 和 华 对 我 说 ： “ 你 起 来 往 幼 发 拉 底 河 去 ， 将 我 吩 咐 你 藏 在 那 里 的 腰 带 取 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19274', '24', '13', '7', '我 就 往 幼 发 拉 底 河 去 ， 将 腰 带 从 我 所 藏 的 地 方 刨 出 来 ， 见 腰 带 已 经 变 坏 ， 毫 无 用 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19275', '24', '13', '8', '耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19276', '24', '13', '9', '“ 耶 和 华 如 此 说 ： 我 必 照 样 败 坏 犹 大 的 骄 傲 和 耶 路 撒 冷 的 大 骄 傲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19277', '24', '13', '10', '这 恶 民 不 肯 听 我 的 话 ， 按 自 己 顽 梗 的 心 而 行 ， 随 从 别 神 ， 事 奉 敬 拜 ， 他 们 也 必 像 这 腰 带 变 为 无 用 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19278', '24', '13', '11', '耶 和 华 说 ： “ 腰 带 怎 样 紧 贴 人 腰 ， 照 样 ， 我 也 使 以 色 列 全 家 和 犹 大 全 家 紧 贴 我 ， 好 叫 他 们 属 我 为 子 民 ， 使 我 得 名 声 ， 得 颂 赞 ， 得 荣 耀 ； 他 们 却 不 肯 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19279', '24', '13', '12', '＜ 酒 坛 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19280', '24', '13', '13', '你 就 要 对 他 们 说 ： ‘ 耶 和 华 如 此 说 ： 我 必 使 这 地 的 一 切 居 民 ， 就 是 坐 大 卫 宝 座 的 君 王 和 祭 司 ， 与 先 知 ， 并 耶 路 撒 冷 的 一 切 居 民 ， 都 酩 酊 大 醉 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19281', '24', '13', '14', '耶 和 华 说 ： “ 我 要 使 他 们 彼 此 相 碰 ， 就 是 父 与 子 彼 此 相 碰 ； 我 必 不 可 怜 ， 不 顾 惜 ， 不 怜 悯 ， 以 致 灭 绝 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19282', '24', '13', '15', '＜ 耶 利 米 警 告 狂 傲 的 行 为 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19283', '24', '13', '16', '耶 和 华 ─ ─ 你 们 的 神 未 使 黑 暗 来 到 ， 你 们 的 脚 未 在 昏 暗 山 上 绊 跌 之 先 ， 当 将 荣 耀 归 给 他 ； 免 得 你 们 盼 望 光 明 ， 他 使 光 明 变 为 死 荫 ， 成 为 幽 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19284', '24', '13', '17', '你 们 若 不 听 这 话 ， 我 必 因 你 们 的 骄 傲 在 暗 地 哭 泣 ； 我 眼 必 痛 哭 流 泪 ， 因 为 耶 和 华 的 群 众 被 掳 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19285', '24', '13', '18', '你 要 对 君 王 和 太 后 说 ： 你 们 当 自 卑 ， 坐 在 下 边 ； 因 你 们 的 头 巾 ， 就 是 你 们 的 华 冠 ， 已 经 脱 落 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19286', '24', '13', '19', '南 方 的 城 尽 都 关 闭 ， 无 人 开 放 ； 犹 大 全 被 掳 掠 ， 且 掳 掠 净 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19287', '24', '13', '20', '你 们 要 举 目 观 看 从 北 方 来 的 人 。 先 前 赐 给 你 的 群 众 ， 就 是 你 佳 美 的 群 众 ， 如 今 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19288', '24', '13', '21', '耶 和 华 立 你 自 己 所 交 的 朋 友 为 首 ， 辖 制 你 ， 那 时 你 还 有 什 么 话 说 呢 ？ 痛 苦 岂 不 将 你 抓 住 像 产 难 的 妇 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19289', '24', '13', '22', '你 若 心 里 说 ： 这 一 切 事 为 何 临 到 我 呢 ？ 你 的 衣 襟 揭 起 ， 你 的 脚 跟 受 伤 ， 是 因 你 的 罪 孽 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19290', '24', '13', '23', '古 实 人 岂 能 改 变 皮 肤 呢 ？ 豹 岂 能 改 变 斑 点 呢 ？ 若 能 ， 你 们 这 习 惯 行 恶 的 便 能 行 善 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19291', '24', '13', '24', '所 以 我 必 用 旷 野 的 风 吹 散 他 们 ， 像 吹 过 的 碎 秸 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19292', '24', '13', '25', '耶 和 华 说 ： 这 是 你 所 当 得 的 ， 是 我 量 给 你 的 分 ； 因 为 你 忘 记 我 ， 倚 靠 虚 假 ｛ 或 译 ： 偶 像 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19293', '24', '13', '26', '所 以 我 要 揭 起 你 的 衣 襟 ， 蒙 在 你 脸 上 ， 显 出 你 的 丑 陋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19294', '24', '13', '27', '你 那 些 可 憎 恶 之 事 ─ ─ 就 是 在 田 野 的 山 上 行 奸 淫 ， 发 嘶 声 ， 做 淫 乱 的 事 ─ ─ 我 都 看 见 了 。 耶 路 撒 冷 啊 ， 你 有 祸 了 ！ 你 不 肯 洁 净 ， 还 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19295', '24', '14', '1', '＜ 可 怕 的 旱 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19296', '24', '14', '2', '犹 大 悲 哀 ， 城 门 衰 败 。 众 人 披 上 黑 衣 坐 在 地 上 ； 耶 路 撒 冷 的 哀 声 上 达 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19297', '24', '14', '3', '他 们 的 贵 胄 打 发 家 僮 打 水 ； 他 们 来 到 水 池 ， 见 没 有 水 ， 就 拿 着 空 器 皿 ， 蒙 羞 惭 愧 ， 抱 头 而 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19298', '24', '14', '4', '耕 地 的 也 蒙 羞 抱 头 ； 因 为 无 雨 降 在 地 上 ， 地 都 干 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19299', '24', '14', '5', '田 野 的 母 鹿 生 下 小 鹿 ， 就 撇 弃 ， 因 为 无 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19300', '24', '14', '6', '野 驴 站 在 净 光 的 高 处 ， 喘 气 好 像 野 狗 ； 因 为 无 草 ， 眼 目 失 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19301', '24', '14', '7', '耶 和 华 啊 ， 我 们 的 罪 孽 虽 然 作 见 证 告 我 们 ， 还 求 你 为 你 名 的 缘 故 行 事 。 我 们 本 是 多 次 背 道 ， 得 罪 了 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19302', '24', '14', '8', '以 色 列 所 盼 望 、 在 患 难 时 作 他 救 主 的 啊 ， 你 为 何 在 这 地 像 寄 居 的 ， 又 像 行 路 的 只 住 一 宵 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19303', '24', '14', '9', '你 为 何 像 受 惊 的 人 ， 像 不 能 救 人 的 勇 士 呢 ？ 耶 和 华 啊 ， 你 仍 在 我 们 中 间 ； 我 们 也 称 为 你 名 下 的 人 ， 求 你 不 要 离 开 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19304', '24', '14', '10', '耶 和 华 对 这 百 姓 如 此 说 ： 这 百 姓 喜 爱 妄 行 ｛ 原 文 是 飘 流 ｝ ， 不 禁 止 脚 步 ， 所 以 耶 和 华 不 悦 纳 他 们 。 现 今 要 记 念 他 们 的 罪 孽 ， 追 讨 他 们 的 罪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19305', '24', '14', '11', '耶 和 华 又 对 我 说 ： “ 不 要 为 这 百 姓 祈 祷 求 好 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19306', '24', '14', '12', '他 们 禁 食 的 时 候 ， 我 不 听 他 们 的 呼 求 ； 他 们 献 燔 祭 和 素 祭 ， 我 也 不 悦 纳 ； 我 却 要 用 刀 剑 、 饥 荒 、 瘟 疫 灭 绝 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19307', '24', '14', '13', '我 就 说 ： “ 唉 ！ 主 耶 和 华 啊 ， 那 些 先 知 常 对 他 们 说 ： ‘ 你 们 必 不 看 见 刀 剑 ， 也 不 遭 遇 饥 荒 ； 耶 和 华 要 在 这 地 方 赐 你 们 长 久 的 平 安 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19308', '24', '14', '14', '耶 和 华 对 我 说 ： “ 那 些 先 知 托 我 的 名 说 假 预 言 ， 我 并 没 有 打 发 他 们 ， 没 有 吩 咐 他 们 ， 也 没 有 对 他 们 说 话 ； 他 们 向 你 们 预 言 的 ， 乃 是 虚 假 的 异 象 和 占 卜 ， 并 虚 无 的 事 ， 以 及 本 心 的 诡 诈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19309', '24', '14', '15', '所 以 耶 和 华 如 此 说 ： 论 到 托 我 名 说 预 言 的 那 些 先 知 ， 我 并 没 有 打 发 他 们 ； 他 们 还 说 这 地 不 能 有 刀 剑 饥 荒 ， 其 实 那 些 先 知 必 被 刀 剑 饥 荒 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19310', '24', '14', '16', '听 他 们 说 预 言 的 百 姓 必 因 饥 荒 刀 剑 抛 在 耶 路 撒 冷 的 街 道 上 ， 无 人 葬 埋 。 他 们 连 妻 子 带 儿 女 ， 都 是 如 此 。 我 必 将 他 们 的 恶 倒 在 他 们 身 上 ｛ 或 译 ： 我 必 使 他 们 罪 恶 的 报 应 临 到 他 们 身 上 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19311', '24', '14', '17', '你 要 将 这 话 对 他 们 说 ： 愿 我 眼 泪 汪 汪 ， 昼 夜 不 息 ， 因 为 我 百 姓 ｛ 原 文 是 民 的 处 女 ｝ 受 了 裂 口 破 坏 的 大 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19312', '24', '14', '18', '我 若 出 往 田 间 ， 就 见 有 被 刀 杀 的 ； 我 若 进 入 城 内 ， 就 见 有 因 饥 荒 患 病 的 ； 连 先 知 带 祭 司 在 国 中 往 来 ， 也 是 毫 无 知 识 ｛ 或 译 ： 不 知 怎 样 才 好 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19313', '24', '14', '19', '＜ 人 民 恳 求 耶 和 华 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19314', '24', '14', '20', '耶 和 华 啊 ， 我 们 承 认 自 己 的 罪 恶 ， 和 我 们 列 祖 的 罪 孽 ， 因 我 们 得 罪 了 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19315', '24', '14', '21', '求 你 为 你 名 的 缘 故 ， 不 厌 恶 我 们 ， 不 辱 没 你 荣 耀 的 宝 座 。 求 你 追 念 ， 不 要 背 了 与 我 们 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19316', '24', '14', '22', '外 邦 人 虚 无 的 神 中 有 能 降 雨 的 吗 ？ 天 能 自 降 甘 霖 吗 ？ 耶 和 华 ─ ─ 我 们 的 神 啊 ， 能 如 此 的 不 是 你 吗 ？ 所 以 ， 我 们 仍 要 等 候 你 ， 因 为 这 一 切 都 是 你 所 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19317', '24', '15', '1', '＜ 犹 大 人 民 的 恶 运 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19318', '24', '15', '2', '他 们 问 你 说 ： ‘ 我 们 往 哪 里 去 呢 ？ ’ 你 便 告 诉 他 们 ， 耶 和 华 如 此 说 ： 定 为 死 亡 的 ， 必 致 死 亡 ； 定 为 刀 杀 的 ， 必 交 刀 杀 ； 定 为 饥 荒 的 ， 必 遭 饥 荒 ； 定 为 掳 掠 的 ， 必 被 掳 掠 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19319', '24', '15', '3', '耶 和 华 说 ： “ 我 命 定 四 样 害 他 们 ， 就 是 刀 剑 杀 戮 、 狗 类 撕 裂 、 空 中 的 飞 鸟 ， 和 地 上 的 野 兽 吞 吃 毁 灭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19320', '24', '15', '4', '又 必 使 他 们 在 天 下 万 国 中 抛 来 抛 去 ， 都 因 犹 大 王 希 西 家 的 儿 子 玛 拿 西 在 耶 路 撒 冷 所 行 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19321', '24', '15', '5', '耶 路 撒 冷 啊 ， 谁 可 怜 你 呢 ？ 谁 为 你 悲 伤 呢 ？ 谁 转 身 问 你 的 安 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19322', '24', '15', '6', '耶 和 华 说 ： 你 弃 绝 了 我 ， 转 身 退 后 ； 因 此 我 伸 手 攻 击 你 ， 毁 坏 你 。 我 后 悔 甚 不 耐 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19323', '24', '15', '7', '我 在 境 内 各 城 门 口 ｛ 或 译 ： 我 在 这 地 边 界 的 关 口 ｝ ， 用 簸 箕 簸 了 我 的 百 姓 ， 使 他 们 丧 掉 儿 女 。 我 毁 灭 他 们 ， 他 们 仍 不 转 离 所 行 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19324', '24', '15', '8', '他 们 的 寡 妇 在 我 面 前 比 海 沙 更 多 ； 我 使 灭 命 的 午 间 来 ， 攻 击 少 年 人 的 母 亲 ， 使 痛 苦 惊 吓 忽 然 临 到 她 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19325', '24', '15', '9', '生 过 七 子 的 妇 人 力 衰 气 绝 ； 尚 在 白 昼 ， 日 头 忽 落 ； 她 抱 愧 蒙 羞 。 其 余 的 人 ， 我 必 在 他 们 敌 人 跟 前 ， 交 与 刀 剑 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19326', '24', '15', '10', '＜ 耶 利 米 向 耶 和 华 诉 苦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19327', '24', '15', '11', '耶 和 华 说 ： “ 我 必 要 坚 固 你 ， 使 你 得 好 处 。 灾 祸 苦 难 临 到 的 时 候 ， 我 必 要 使 仇 敌 央 求 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19328', '24', '15', '12', '（ 人 岂 能 将 铜 与 铁 ， 就 是 北 方 的 铁 折 断 呢 ？ ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19329', '24', '15', '13', '“ 我 必 因 你 在 四 境 之 内 所 犯 的 一 切 罪 ， 把 你 的 货 物 财 宝 当 掠 物 ， 白 白 地 交 给 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19330', '24', '15', '14', '我 也 必 使 仇 敌 带 这 掠 物 到 你 所 不 认 识 的 地 去 ， 因 我 怒 中 起 的 火 要 将 你 们 焚 烧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19331', '24', '15', '15', '耶 和 华 啊 ， 你 是 知 道 的 ； 求 你 记 念 我 ， 眷 顾 我 ， 向 逼 迫 我 的 人 为 我 报 仇 ； 不 要 向 他 们 忍 怒 取 我 的 命 ， 要 知 道 我 为 你 的 缘 故 受 了 凌 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19332', '24', '15', '16', '耶 和 华 ─ ─ 万 军 之 神 啊 ， 我 得 着 你 的 言 语 就 当 食 物 吃 了 ； 你 的 言 语 是 我 心 中 的 欢 喜 快 乐 ， 因 我 是 称 为 你 名 下 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19333', '24', '15', '17', '我 没 有 坐 在 宴 乐 人 的 会 中 ， 也 没 有 欢 乐 ； 我 因 你 的 感 动 ｛ 原 文 是 手 ｝ 独 自 静 坐 ， 因 你 使 我 满 心 愤 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19334', '24', '15', '18', '我 的 痛 苦 为 何 长 久 不 止 呢 ？ 我 的 伤 痕 为 何 无 法 医 治 、 不 能 痊 愈 呢 ？ 难 道 你 待 我 有 诡 诈 ， 像 流 干 的 河 道 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19335', '24', '15', '19', '耶 和 华 如 此 说 ： 你 若 归 回 ， 我 就 将 你 再 带 来 ， 使 你 站 在 我 面 前 ； 你 若 将 宝 贵 的 和 下 贱 的 分 别 出 来 ， 你 就 可 以 当 作 我 的 口 。 他 们 必 归 向 你 ， 你 却 不 可 归 向 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19336', '24', '15', '20', '我 必 使 你 向 这 百 姓 成 为 坚 固 的 铜 墙 ； 他 们 必 攻 击 你 ， 却 不 能 胜 你 ； 因 我 与 你 同 在 ， 要 拯 救 你 ， 搭 救 你 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19337', '24', '15', '21', '我 必 搭 救 你 脱 离 恶 人 的 手 ， 救 赎 你 脱 离 强 暴 人 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19338', '24', '16', '1', '＜ 耶 和 华 要 耶 利 米 过 孤 独 的 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19339', '24', '16', '2', '“ 你 在 这 地 方 不 可 娶 妻 ， 生 儿 养 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19340', '24', '16', '3', '因 为 论 到 在 这 地 方 所 生 的 儿 女 ， 又 论 到 在 这 国 中 生 养 他 们 的 父 母 ， 耶 和 华 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19341', '24', '16', '4', '他 们 必 死 得 甚 苦 ， 无 人 哀 哭 ， 必 不 得 葬 埋 ， 必 在 地 上 像 粪 土 ， 必 被 刀 剑 和 饥 荒 灭 绝 ； 他 们 的 尸 首 必 给 空 中 的 飞 鸟 和 地 上 的 野 兽 作 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19342', '24', '16', '5', '耶 和 华 如 此 说 ： “ 不 要 进 入 丧 家 ， 不 要 去 哀 哭 ， 也 不 要 为 他 们 悲 伤 ， 因 我 已 将 我 的 平 安 、 慈 爱 、 怜 悯 从 这 百 姓 夺 去 了 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19343', '24', '16', '6', '连 大 带 小 ， 都 必 在 这 地 死 亡 ， 不 得 葬 埋 。 人 必 不 为 他 们 哀 哭 ， 不 用 刀 划 身 ， 也 不 使 头 光 秃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19344', '24', '16', '7', '他 们 有 丧 事 ， 人 必 不 为 他 们 擘 饼 ， 因 死 人 安 慰 他 们 ； 他 们 丧 父 丧 母 ， 人 也 不 给 他 们 一 杯 酒 安 慰 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19345', '24', '16', '8', '你 不 可 进 入 宴 乐 的 家 ， 与 他 们 同 坐 吃 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19346', '24', '16', '9', '因 为 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 们 还 活 着 的 日 子 在 你 们 眼 前 ， 我 必 使 欢 喜 和 快 乐 的 声 音 ， 新 郎 和 新 妇 的 声 音 ， 从 这 地 方 止 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19347', '24', '16', '10', '“ 你 将 这 一 切 的 话 指 示 这 百 姓 。 他 们 问 你 说 ： ‘ 耶 和 华 为 什 么 说 ， 要 降 这 大 灾 祸 攻 击 我 们 呢 ？ 我 们 有 什 么 罪 孽 呢 ？ 我 们 向 耶 和 华 ─ ─ 我 们 的 神 犯 了 什 么 罪 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19348', '24', '16', '11', '你 就 对 他 们 说 ： ‘ 耶 和 华 说 ： 因 为 你 们 列 祖 离 弃 我 ， 随 从 别 神 ， 事 奉 敬 拜 ， 不 遵 守 我 的 律 法 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19349', '24', '16', '12', '而 且 你 们 行 恶 比 你 们 列 祖 更 甚 ； 因 为 各 人 随 从 自 己 顽 梗 的 恶 心 行 事 ， 甚 至 不 听 从 我 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19350', '24', '16', '13', '所 以 我 必 将 你 们 从 这 地 赶 出 ， 直 赶 到 你 们 和 你 们 列 祖 素 不 认 识 的 地 。 你 们 在 那 里 必 昼 夜 事 奉 别 神 ， 因 为 我 必 不 向 你 们 施 恩 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19351', '24', '16', '14', '＜ 从 流 亡 中 回 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19352', '24', '16', '15', '却 要 指 着 那 领 以 色 列 人 从 北 方 之 地 ， 并 赶 他 们 到 的 各 国 上 来 之 永 生 的 耶 和 华 起 誓 ， 并 且 我 要 领 他 们 再 入 我 从 前 赐 给 他 们 列 祖 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19353', '24', '16', '16', '＜ 将 要 临 到 的 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19354', '24', '16', '17', '因 我 的 眼 目 察 看 他 们 的 一 切 行 为 ； 他 们 不 能 在 我 面 前 遮 掩 ， 他 们 的 罪 孽 也 不 能 在 我 眼 前 隐 藏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19355', '24', '16', '18', '我 先 要 加 倍 报 应 他 们 的 罪 孽 和 罪 恶 ； 因 为 他 们 用 可 憎 之 尸 玷 污 我 的 地 土 ， 又 用 可 厌 之 物 充 满 我 的 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19356', '24', '16', '19', '＜ 耶 利 米 的 信 心 祈 祷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19357', '24', '16', '20', '人 岂 可 为 自 己 制 造 神 呢 ？ 其 实 这 不 是 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19358', '24', '16', '21', '耶 和 华 说 ： “ 我 要 使 他 们 知 道 ， 就 是 这 一 次 使 他 们 知 道 我 的 手 和 我 的 能 力 。 他 们 就 知 道 我 的 名 是 耶 和 华 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19359', '24', '17', '1', '＜ 犹 大 的 罪 和 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19360', '24', '17', '2', '他 们 的 儿 女 记 念 他 们 高 冈 上 、 青 翠 树 旁 的 坛 和 木 偶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19361', '24', '17', '3', '我 田 野 的 山 哪 ， 我 必 因 你 在 四 境 之 内 所 犯 的 罪 ， 把 你 的 货 物 、 财 宝 ， 并 邱 坛 当 掠 物 交 给 仇 敌 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19362', '24', '17', '4', '并 且 你 因 自 己 的 罪 必 失 去 我 所 赐 给 你 的 产 业 。 我 也 必 使 你 在 你 所 不 认 识 的 地 上 服 事 你 的 仇 敌 ； 因 为 你 使 我 怒 中 起 火 ， 直 烧 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19363', '24', '17', '5', '＜ 训 诲 集 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19364', '24', '17', '6', '因 他 必 像 沙 漠 的 杜 松 ， 不 见 福 乐 来 到 ， 却 要 住 旷 野 干 旱 之 处 ， 无 人 居 住 的 碱 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19365', '24', '17', '7', '倚 靠 耶 和 华 、 以 耶 和 华 为 可 靠 的 ， 那 人 有 福 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19366', '24', '17', '8', '他 必 像 树 栽 于 水 旁 ， 在 河 边 扎 根 ， 炎 热 来 到 ， 并 不 惧 怕 ， 叶 子 仍 必 青 翠 ， 在 干 旱 之 年 毫 无 挂 虑 ， 而 且 结 果 不 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19367', '24', '17', '9', '人 心 比 万 物 都 诡 诈 ， 坏 到 极 处 ， 谁 能 识 透 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19368', '24', '17', '10', '我 ─ ─ 耶 和 华 是 鉴 察 人 心 、 试 验 人 肺 腑 的 ， 要 照 各 人 所 行 的 和 他 做 事 的 结 果 报 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19369', '24', '17', '11', '那 不 按 正 道 得 财 的 ， 好 像 鹧 鸪 菢 不 是 自 己 下 的 蛋 ； 到 了 中 年 ， 那 财 都 必 离 开 他 ， 他 终 久 成 为 愚 顽 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19370', '24', '17', '12', '我 们 的 圣 所 是 荣 耀 的 宝 座 ， 从 太 初 安 置 在 高 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19371', '24', '17', '13', '耶 和 华 ─ ─ 以 色 列 的 盼 望 啊 ， 凡 离 弃 你 的 必 致 蒙 羞 。 耶 和 华 说 ： 离 开 我 的 ， 他 们 的 名 字 必 写 在 土 里 ， 因 为 他 们 离 弃 我 这 活 水 的 泉 源 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19372', '24', '17', '14', '＜ 耶 利 米 求 主 帮 助 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19373', '24', '17', '15', '他 们 对 我 说 ： 耶 和 华 的 话 在 哪 里 呢 ？ 叫 这 话 应 验 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19374', '24', '17', '16', '至 于 我 ， 那 跟 从 你 作 牧 人 的 职 分 ， 我 并 没 有 急 忙 离 弃 ， 也 没 有 想 那 灾 殃 的 日 子 ； 这 是 你 知 道 的 。 我 口 中 所 出 的 言 语 都 在 你 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19375', '24', '17', '17', '不 要 使 我 因 你 惊 恐 ； 当 灾 祸 的 日 子 ， 你 是 我 的 避 难 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19376', '24', '17', '18', '愿 那 些 逼 迫 我 的 蒙 羞 ， 却 不 要 使 我 蒙 羞 ； 使 他 们 惊 惶 ， 却 不 要 使 我 惊 惶 ； 使 灾 祸 的 日 子 临 到 他 们 ， 以 加 倍 的 毁 坏 毁 坏 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19377', '24', '17', '19', '＜ 关 于 遵 守 安 息 日 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19378', '24', '17', '20', '对 他 们 说 ： ‘ 你 们 这 犹 大 君 王 和 犹 大 众 人 ， 并 耶 路 撒 冷 的 一 切 居 民 ， 凡 从 这 些 门 进 入 的 都 当 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19379', '24', '17', '21', '耶 和 华 如 此 说 ： 你 们 要 谨 慎 ， 不 要 在 安 息 日 担 什 么 担 子 进 入 耶 路 撒 冷 的 各 门 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19380', '24', '17', '22', '也 不 要 在 安 息 日 从 家 中 担 出 担 子 去 。 无 论 何 工 都 不 可 做 ， 只 要 以 安 息 日 为 圣 日 ， 正 如 我 所 吩 咐 你 们 列 祖 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19381', '24', '17', '23', '他 们 却 不 听 从 ， 不 侧 耳 而 听 ， 竟 硬 着 颈 项 不 听 ， 不 受 教 训 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19382', '24', '17', '24', '耶 和 华 说 ： “ 你 们 若 留 意 听 从 我 ， 在 安 息 日 不 担 什 么 担 子 进 入 这 城 的 各 门 ， 只 以 安 息 日 为 圣 日 ， 在 那 日 无 论 何 工 都 不 做 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19383', '24', '17', '25', '那 时 就 有 坐 大 卫 宝 座 的 君 王 和 首 领 ， 他 们 与 犹 大 人 ， 并 耶 路 撒 冷 的 居 民 ， 或 坐 车 ， 或 骑 马 ， 进 入 这 城 的 各 门 ， 而 且 这 城 必 存 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19384', '24', '17', '26', '也 必 有 人 从 犹 大 城 邑 和 耶 路 撒 冷 四 围 的 各 处 ， 从 便 雅 悯 地 、 高 原 、 山 地 ， 并 南 地 而 来 ， 都 带 燔 祭 、 平 安 祭 、 素 祭 ， 和 乳 香 ， 并 感 谢 祭 ， 到 耶 和 华 的 殿 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19385', '24', '17', '27', '你 们 若 不 听 从 我 ， 不 以 安 息 日 为 圣 日 ， 仍 在 安 息 日 担 担 子 ， 进 入 耶 路 撒 冷 的 各 门 ， 我 必 在 各 门 中 点 火 ； 这 火 也 必 烧 毁 耶 路 撒 冷 的 宫 殿 ， 不 能 熄 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19386', '24', '18', '1', '＜ 耶 利 米 在 陶 匠 的 家 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19387', '24', '18', '2', '“ 你 起 来 ， 下 到 窑 匠 的 家 里 去 ， 我 在 那 里 要 使 你 听 我 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19388', '24', '18', '3', '我 就 下 到 窑 匠 的 家 里 去 ， 正 遇 他 转 轮 做 器 皿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19389', '24', '18', '4', '窑 匠 用 泥 做 的 器 皿 ， 在 他 手 中 做 坏 了 ， 他 又 用 这 泥 另 做 别 的 器 皿 ； 窑 匠 看 怎 样 好 ， 就 怎 样 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19390', '24', '18', '5', '耶 和 华 的 话 就 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19391', '24', '18', '6', '“ 耶 和 华 说 ： 以 色 列 家 啊 ， 我 待 你 们 ， 岂 不 能 照 这 窑 匠 弄 泥 吗 ？ 以 色 列 家 啊 ， 泥 在 窑 匠 的 手 中 怎 样 ， 你 们 在 我 的 手 中 也 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19392', '24', '18', '7', '我 何 时 论 到 一 邦 或 一 国 说 ， 要 拔 出 、 拆 毁 、 毁 坏 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19393', '24', '18', '8', '我 所 说 的 那 一 邦 ， 若 是 转 意 离 开 他 们 的 恶 ， 我 就 必 后 悔 ， 不 将 我 想 要 施 行 的 灾 祸 降 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19394', '24', '18', '9', '我 何 时 论 到 一 邦 或 一 国 说 ， 要 建 立 、 栽 植 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19395', '24', '18', '10', '他 们 若 行 我 眼 中 看 为 恶 的 事 ， 不 听 从 我 的 话 ， 我 就 必 后 悔 ， 不 将 我 所 说 的 福 气 赐 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19396', '24', '18', '11', '现 在 你 要 对 犹 大 人 和 耶 路 撒 冷 的 居 民 说 ： ‘ 耶 和 华 如 此 说 ： 我 造 出 灾 祸 攻 击 你 们 ， 定 意 刑 罚 你 们 。 你 们 各 人 当 回 头 离 开 所 行 的 恶 道 ， 改 正 你 们 的 行 动 作 为 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19397', '24', '18', '12', '“ 他 们 却 说 ： ‘ 这 是 枉 然 。 我 们 要 照 自 己 的 计 谋 去 行 。 ’ 各 人 随 自 己 顽 梗 的 恶 心 做 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19398', '24', '18', '13', '＜ 人 民 弃 绝 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19399', '24', '18', '14', '黎 巴 嫩 的 雪 从 田 野 的 磐 石 上 岂 能 断 绝 呢 ？ 从 远 处 流 下 的 凉 水 岂 能 干 涸 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19400', '24', '18', '15', '我 的 百 姓 竟 忘 记 我 ， 向 假 神 烧 香 ， 使 他 们 在 所 行 的 路 上 ， 在 古 道 上 绊 跌 ， 使 他 们 行 没 有 修 筑 的 斜 路 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19401', '24', '18', '16', '以 致 他 们 的 地 令 人 惊 骇 ， 常 常 嗤 笑 ； 凡 经 过 这 地 的 必 惊 骇 摇 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19402', '24', '18', '17', '我 必 在 仇 敌 面 前 分 散 他 们 ， 好 像 用 东 风 吹 散 一 样 。 遭 难 的 日 子 ， 我 必 以 背 向 他 们 ， 不 以 面 向 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19403', '24', '18', '18', '＜ 谋 害 耶 利 米 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19404', '24', '18', '19', '耶 和 华 啊 ， 求 你 理 会 我 ， 且 听 那 些 与 我 争 竞 之 人 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19405', '24', '18', '20', '岂 可 以 恶 报 善 呢 ？ 他 们 竟 挖 坑 要 害 我 的 性 命 ！ 求 你 记 念 我 怎 样 站 在 你 面 前 为 他 们 代 求 ， 要 使 你 的 忿 怒 向 他 们 转 消 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19406', '24', '18', '21', '故 此 ， 愿 你 将 他 们 的 儿 女 交 与 饥 荒 和 刀 剑 ； 愿 他 们 的 妻 无 子 ， 且 作 寡 妇 ； 又 愿 他 们 的 男 人 被 死 亡 所 灭 ， 他 们 的 少 年 人 在 阵 上 被 刀 击 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19407', '24', '18', '22', '你 使 敌 军 忽 然 临 到 他 们 的 时 候 ， 愿 人 听 见 哀 声 从 他 们 的 屋 内 发 出 ； 因 他 们 挖 坑 要 捉 拿 我 ， 暗 设 网 罗 要 绊 我 的 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19408', '24', '18', '23', '耶 和 华 啊 ， 他 们 要 杀 我 的 那 一 切 计 谋 ， 你 都 知 道 。 不 要 赦 免 他 们 的 罪 孽 ， 也 不 要 从 你 面 前 涂 抹 他 们 的 罪 恶 ， 要 叫 他 们 在 你 面 前 跌 倒 ； 愿 你 发 怒 的 时 候 罚 办 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19409', '24', '19', '1', '＜ 破 碎 的 瓶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19410', '24', '19', '2', '出 去 到 欣 嫩 子 谷 、 哈 珥 西 ｛ 就 是 瓦 片 的 意 思 ｝ 的 门 口 那 里 ， 宣 告 我 所 吩 咐 你 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19411', '24', '19', '3', '说 ： ‘ 犹 大 君 王 和 耶 路 撒 冷 的 居 民 哪 ， 当 听 耶 和 华 的 话 。 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 必 使 灾 祸 临 到 这 地 方 ， 凡 听 见 的 人 都 必 耳 鸣 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19412', '24', '19', '4', '因 为 他 们 和 他 们 列 祖 ， 并 犹 大 君 王 离 弃 我 ， 将 这 地 方 看 为 平 常 ， 在 这 里 向 素 不 认 识 的 别 神 烧 香 ， 又 使 这 地 方 满 了 无 辜 人 的 血 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19413', '24', '19', '5', '又 建 筑 巴 力 的 邱 坛 ， 好 在 火 中 焚 烧 自 己 的 儿 子 ， 作 为 燔 祭 献 给 巴 力 。 这 不 是 我 所 吩 咐 的 ， 不 是 我 所 提 说 的 ， 也 不 是 我 心 所 起 的 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19414', '24', '19', '6', '耶 和 华 说 ： 因 此 ， 日 子 将 到 ， 这 地 方 不 再 称 为 陀 斐 特 和 欣 嫩 子 谷 ， 反 倒 称 为 杀 戮 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19415', '24', '19', '7', '我 必 在 这 地 方 使 犹 大 和 耶 路 撒 冷 的 计 谋 落 空 ， 也 必 使 他 们 在 仇 敌 面 前 倒 于 刀 下 ， 并 寻 索 其 命 的 人 手 下 。 他 们 的 尸 首 ， 我 必 给 空 中 的 飞 鸟 和 地 上 的 野 兽 作 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19416', '24', '19', '8', '我 必 使 这 城 令 人 惊 骇 嗤 笑 ； 凡 经 过 的 人 ， 必 因 这 城 所 遭 的 灾 惊 骇 嗤 笑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19417', '24', '19', '9', '我 必 使 他 们 在 围 困 窘 迫 之 中 ， 就 是 仇 敌 和 寻 索 其 命 的 人 窘 迫 他 们 的 时 候 ， 各 人 吃 自 己 儿 女 的 肉 和 朋 友 的 肉 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19418', '24', '19', '10', '“ 你 要 在 同 去 的 人 眼 前 打 碎 那 瓶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19419', '24', '19', '11', '对 他 们 说 ： ‘ 万 军 之 耶 和 华 如 此 说 ： 我 要 照 样 打 碎 这 民 和 这 城 ， 正 如 人 打 碎 窑 匠 的 瓦 器 ， 以 致 不 能 再 囫 囵 。 并 且 人 要 在 陀 斐 特 葬 埋 尸 首 ， 甚 至 无 处 可 葬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19420', '24', '19', '12', '耶 和 华 说 ： 我 必 向 这 地 方 和 其 中 的 居 民 如 此 行 ， 使 这 城 与 陀 斐 特 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19421', '24', '19', '13', '耶 路 撒 冷 的 房 屋 和 犹 大 君 王 的 宫 殿 是 已 经 被 玷 污 的 ， 就 是 他 们 在 其 上 向 天 上 的 万 象 烧 香 、 向 别 神 浇 奠 祭 的 宫 殿 房 屋 ， 都 必 与 陀 斐 特 一 样 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19422', '24', '19', '14', '耶 利 米 从 陀 斐 特 ─ ─ 就 是 耶 和 华 差 他 去 说 预 言 的 地 方 ─ ─ 回 来 ， 站 在 耶 和 华 殿 的 院 中 ， 对 众 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19423', '24', '19', '15', '“ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 必 使 我 所 说 的 一 切 灾 祸 临 到 这 城 和 属 城 的 一 切 城 邑 ， 因 为 他 们 硬 着 颈 项 不 听 我 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19424', '24', '20', '1', '＜ 耶 利 米 跟 祭 司 巴 施 户 珥 冲 突 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19425', '24', '20', '2', '他 就 打 先 知 耶 利 米 ， 用 耶 和 华 殿 里 便 雅 悯 高 门 内 的 枷 ， 将 他 枷 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19426', '24', '20', '3', '次 日 ， 巴 施 户 珥 将 耶 利 米 开 枷 释 放 。 于 是 耶 利 米 对 他 说 ： “ 耶 和 华 不 是 叫 你 的 名 为 巴 施 户 珥 ， 乃 是 叫 你 玛 歌 珥 ． 米 撒 毕 ｛ 就 是 四 面 惊 吓 的 意 思 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19427', '24', '20', '4', '因 耶 和 华 如 此 说 ： ‘ 我 必 使 你 自 觉 惊 吓 ， 你 也 必 使 众 朋 友 惊 吓 ； 他 们 必 倒 在 仇 敌 的 刀 下 ， 你 也 必 亲 眼 看 见 ； 我 必 将 犹 大 人 全 交 在 巴 比 伦 王 的 手 中 ， 他 要 将 他 们 掳 到 巴 比 伦 去 ， 也 要 用 刀 将 他 们 杀 戮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19428', '24', '20', '5', '并 且 我 要 将 这 城 中 的 一 切 货 财 和 劳 碌 得 来 的 ， 并 一 切 珍 宝 ， 以 及 犹 大 君 王 所 有 的 宝 物 ， 都 交 在 他 们 仇 敌 的 手 中 ； 仇 敌 要 当 作 掠 物 带 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19429', '24', '20', '6', '你 这 巴 施 户 珥 和 一 切 住 在 你 家 中 的 人 都 必 被 掳 去 ； 你 和 你 的 众 朋 友 ， 就 是 你 向 他 们 说 假 预 言 的 ， 都 必 到 巴 比 伦 去 ， 要 死 在 那 里 ， 葬 在 那 里 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19430', '24', '20', '7', '＜ 耶 利 米 向 主 投 诉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19431', '24', '20', '8', '我 每 逢 讲 论 的 时 候 ， 就 发 出 哀 声 ， 我 喊 叫 说 ： 有 强 暴 和 毁 灭 ！ 因 为 耶 和 华 的 话 终 日 成 了 我 的 凌 辱 、 讥 刺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19432', '24', '20', '9', '我 若 说 ： 我 不 再 提 耶 和 华 ， 也 不 再 奉 他 的 名 讲 论 ， 我 便 心 里 觉 得 似 乎 有 烧 着 的 火 闭 塞 在 我 骨 中 ， 我 就 含 忍 不 住 ， 不 能 自 禁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19433', '24', '20', '10', '我 听 见 了 许 多 人 的 谗 谤 ， 四 围 都 是 惊 吓 ； 就 是 我 知 己 的 朋 友 也 都 窥 探 我 ， 愿 我 跌 倒 ， 说 ： 告 他 吧 ， 我 们 也 要 告 他 ！ 或 者 他 被 引 诱 ， 我 们 就 能 胜 他 ， 在 他 身 上 报 仇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19434', '24', '20', '11', '然 而 ， 耶 和 华 与 我 同 在 ， 好 像 甚 可 怕 的 勇 士 。 因 此 ， 逼 迫 我 的 必 都 绊 跌 ， 不 能 得 胜 ； 他 们 必 大 大 蒙 羞 ， 就 是 受 永 不 忘 记 的 羞 辱 ， 因 为 他 们 行 事 没 有 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19435', '24', '20', '12', '试 验 义 人 、 察 看 人 肺 腑 心 肠 的 万 军 之 耶 和 华 啊 ， 求 你 容 我 见 你 在 他 们 身 上 报 仇 ， 因 我 将 我 的 案 件 向 你 禀 明 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19436', '24', '20', '13', '你 们 要 向 耶 和 华 唱 歌 ； 赞 美 耶 和 华 ！ 因 他 救 了 穷 人 的 性 命 脱 离 恶 人 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19437', '24', '20', '14', '愿 我 生 的 那 日 受 咒 诅 ； 愿 我 母 亲 产 我 的 那 日 不 蒙 福 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19438', '24', '20', '15', '给 我 父 亲 报 信 说 “ 你 得 了 儿 子 ” ， 使 我 父 亲 甚 欢 喜 的 ， 愿 那 人 受 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19439', '24', '20', '16', '愿 那 人 像 耶 和 华 所 倾 覆 而 不 后 悔 的 城 邑 ； 愿 他 早 晨 听 见 哀 声 ， 晌 午 听 见 呐 喊 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19440', '24', '20', '17', '因 他 在 我 未 出 胎 的 时 候 不 杀 我 ， 使 我 母 亲 成 了 我 的 坟 墓 ， 胎 就 时 常 重 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19441', '24', '20', '18', '我 为 何 出 胎 见 劳 碌 愁 苦 ， 使 我 的 年 日 因 羞 愧 消 灭 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19442', '24', '21', '1', '＜ 预 言 耶 路 撒 冷 灭 亡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19443', '24', '21', '2', '“ 请 你 为 我 们 求 问 耶 和 华 ； 因 为 巴 比 伦 王 尼 布 甲 尼 撒 来 攻 击 我 们 ， 或 者 耶 和 华 照 他 一 切 奇 妙 的 作 为 待 我 们 ， 使 巴 比 伦 王 离 开 我 们 上 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19444', '24', '21', '3', '耶 利 米 对 他 们 说 ： “ 你 们 当 对 西 底 家 这 样 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19445', '24', '21', '4', '‘ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 要 使 你 们 手 中 的 兵 器 ， 就 是 你 们 在 城 外 与 巴 比 伦 王 和 围 困 你 们 的 迦 勒 底 人 打 仗 的 兵 器 翻 转 过 来 ， 又 要 使 这 些 都 聚 集 在 这 城 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19446', '24', '21', '5', '并 且 我 要 在 怒 气 、 忿 怒 ， 和 大 恼 恨 中 ， 用 伸 出 来 的 手 ， 并 大 能 的 膀 臂 ， 亲 自 攻 击 你 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19447', '24', '21', '6', '又 要 击 打 这 城 的 居 民 ， 连 人 带 牲 畜 都 必 遭 遇 大 瘟 疫 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19448', '24', '21', '7', '以 后 我 要 将 犹 大 王 西 底 家 和 他 的 臣 仆 百 姓 ， 就 是 在 城 内 ， 从 瘟 疫 、 刀 剑 、 饥 荒 中 剩 下 的 人 ， 都 交 在 巴 比 伦 王 尼 布 甲 尼 撒 的 手 中 和 他 们 仇 敌 ， 并 寻 索 其 命 的 人 手 中 。 巴 比 伦 王 必 用 刀 击 杀 他 们 ， 不 顾 惜 ， 不 可 怜 ， 不 怜 悯 。 这 是 耶 和 华 说 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19449', '24', '21', '8', '“ 你 要 对 这 百 姓 说 ： ‘ 耶 和 华 如 此 说 ： 看 哪 ， 我 将 生 命 的 路 和 死 亡 的 路 摆 在 你 们 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19450', '24', '21', '9', '住 在 这 城 里 的 必 遭 刀 剑 、 饥 荒 、 瘟 疫 而 死 ； 但 出 去 归 降 围 困 你 们 迦 勒 底 人 的 必 得 存 活 ， 要 以 自 己 的 命 为 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19451', '24', '21', '10', '耶 和 华 说 ： 我 向 这 城 变 脸 ， 降 祸 不 降 福 ； 这 城 必 交 在 巴 比 伦 王 的 手 中 ， 他 必 用 火 焚 烧 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19452', '24', '21', '11', '＜ 审 判 犹 大 王 室 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19453', '24', '21', '12', '大 卫 家 啊 ， 耶 和 华 如 此 说 ： 你 们 每 早 晨 要 施 行 公 平 ， 拯 救 被 抢 夺 的 脱 离 欺 压 人 的 手 ， 恐 怕 我 的 忿 怒 因 你 们 的 恶 行 发 作 ， 如 火 着 起 ， 甚 至 无 人 能 以 熄 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19454', '24', '21', '13', '耶 和 华 说 ： 住 山 谷 和 平 原 磐 石 上 的 居 民 ， 你 们 说 ： 谁 能 下 来 攻 击 我 们 ？ 谁 能 进 入 我 们 的 住 处 呢 ？ 看 哪 ， 我 与 你 们 为 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19455', '24', '21', '14', '耶 和 华 又 说 ： 我 必 按 你 们 做 事 的 结 果 刑 罚 你 们 ； 我 也 必 使 火 在 耶 路 撒 冷 的 林 中 着 起 ， 将 她 四 围 所 有 的 尽 行 烧 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19456', '24', '22', '1', '＜ 耶 利 米 给 犹 大 王 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19457', '24', '22', '2', '说 ： ‘ 坐 大 卫 宝 座 的 犹 大 王 啊 ， 你 和 你 的 臣 仆 ， 并 进 入 城 门 的 百 姓 ， 都 当 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19458', '24', '22', '3', '耶 和 华 如 此 说 ： 你 们 要 施 行 公 平 和 公 义 ， 拯 救 被 抢 夺 的 脱 离 欺 压 人 的 手 ， 不 可 亏 负 寄 居 的 和 孤 儿 寡 妇 ， 不 可 以 强 暴 待 他 们 ， 在 这 地 方 也 不 可 流 无 辜 人 的 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19459', '24', '22', '4', '你 们 若 认 真 行 这 事 ， 就 必 有 坐 大 卫 宝 座 的 君 王 和 他 的 臣 仆 百 姓 ， 或 坐 车 或 骑 马 ， 从 这 城 的 各 门 进 入 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19460', '24', '22', '5', '你 们 若 不 听 这 些 话 ， 耶 和 华 说 ： 我 指 着 自 己 起 誓 ， 这 城 必 变 为 荒 场 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19461', '24', '22', '6', '耶 和 华 论 到 犹 大 王 的 家 如 此 说 ： 我 看 你 如 基 列 ， 如 黎 巴 嫩 顶 ； 然 而 ， 我 必 使 你 变 为 旷 野 ， 为 无 人 居 住 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19462', '24', '22', '7', '我 要 预 备 行 毁 灭 的 人 ， 各 拿 器 械 攻 击 你 ； 他 们 要 砍 下 你 佳 美 的 香 柏 树 ， 扔 在 火 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19463', '24', '22', '8', '“ 许 多 国 的 民 要 经 过 这 城 ， 各 人 对 邻 舍 说 ： ‘ 耶 和 华 为 何 向 这 大 城 如 此 行 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19464', '24', '22', '9', '他 们 必 回 答 说 ： ‘ 是 因 离 弃 了 耶 和 华 ─ ─ 他 们 神 的 约 ， 事 奉 敬 拜 别 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19465', '24', '22', '10', '＜ 关 于 约 哈 斯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19466', '24', '22', '11', '因 为 耶 和 华 论 到 从 这 地 方 出 去 的 犹 大 王 约 西 亚 的 儿 子 沙 龙 ｛ 在 列 王 下 二 十 三 章 三 十 节 名 约 哈 斯 ｝ ， 就 是 接 续 他 父 亲 约 西 亚 作 王 的 ， 这 样 说 ： “ 他 必 不 得 再 回 到 这 里 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19467', '24', '22', '12', '却 要 死 在 被 掳 去 的 地 方 ， 必 不 得 再 见 这 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19468', '24', '22', '13', '＜ 关 于 约 雅 敬 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19469', '24', '22', '14', '他 说 ： 我 要 为 自 己 盖 广 大 的 房 、 宽 敞 的 楼 ， 为 自 己 开 窗 户 。 这 楼 房 的 护 墙 板 是 香 柏 木 的 ， 楼 房 是 丹 色 油 漆 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19470', '24', '22', '15', '难 道 你 作 王 是 在 乎 造 香 柏 木 楼 房 争 胜 吗 ？ 你 的 父 亲 岂 不 是 也 吃 也 喝 、 也 施 行 公 平 和 公 义 吗 ？ 那 时 他 得 了 福 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19471', '24', '22', '16', '他 为 困 苦 和 穷 乏 人 伸 冤 ， 那 时 就 得 了 福 乐 。 认 识 我 不 在 乎 此 吗 ？ 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19472', '24', '22', '17', '惟 有 你 的 眼 和 你 的 心 专 顾 贪 婪 ， 流 无 辜 人 的 血 ， 行 欺 压 和 强 暴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19473', '24', '22', '18', '所 以 ， 耶 和 华 论 到 犹 大 王 约 西 亚 的 儿 子 约 雅 敬 如 此 说 ： 人 必 不 为 他 举 哀 说 ： 哀 哉 ！ 我 的 哥 哥 ； 或 说 ： 哀 哉 ！ 我 的 姊 姊 ； 也 不 为 他 举 哀 说 ： 哀 哉 ！ 我 的 主 ； 或 说 ： 哀 哉 ！ 我 主 的 荣 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19474', '24', '22', '19', '他 被 埋 葬 ， 好 像 埋 驴 一 样 ， 要 拉 出 去 扔 在 耶 路 撒 冷 的 城 门 之 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19475', '24', '22', '20', '＜ 关 于 耶 路 撒 冷 人 民 的 命 运 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19476', '24', '22', '21', '你 兴 盛 的 时 候 ， 我 对 你 说 话 ； 你 却 说 ： 我 不 听 。 你 自 幼 年 以 来 总 是 这 样 ， 不 听 从 我 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19477', '24', '22', '22', '你 的 牧 人 要 被 风 吞 吃 ， 你 所 亲 爱 的 必 被 掳 去 ； 那 时 你 必 因 你 一 切 的 恶 抱 愧 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19478', '24', '22', '23', '你 这 住 黎 巴 嫩 、 在 香 柏 树 上 搭 窝 的 ， 有 痛 苦 临 到 你 ， 好 像 疼 痛 临 到 产 难 的 妇 人 ， 那 时 你 何 等 可 怜 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19479', '24', '22', '24', '＜ 神 审 判 哥 尼 雅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19480', '24', '22', '25', '并 且 我 必 将 你 交 给 寻 索 你 命 的 人 和 你 所 惧 怕 的 人 手 中 ， 就 是 巴 比 伦 王 尼 布 甲 尼 撒 和 迦 勒 底 人 的 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19481', '24', '22', '26', '我 也 必 将 你 和 生 你 的 母 亲 赶 到 别 国 ， 并 不 是 你 们 生 的 地 方 ； 你 们 必 死 在 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19482', '24', '22', '27', '但 心 中 甚 想 归 回 之 地 ， 必 不 得 归 回 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19483', '24', '22', '28', '哥 尼 雅 这 人 是 被 轻 看 、 破 坏 的 器 皿 吗 ？ 是 无 人 喜 爱 的 器 皿 吗 ？ 他 和 他 的 后 裔 为 何 被 赶 到 不 认 识 之 地 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19484', '24', '22', '29', '地 啊 ， 地 啊 ， 地 啊 ， 当 听 耶 和 华 的 话 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19485', '24', '22', '30', '耶 和 华 如 此 说 ： 要 写 明 这 人 算 为 无 子 ， 是 平 生 不 得 亨 通 的 ； 因 为 他 后 裔 中 再 无 一 人 得 亨 通 ， 能 坐 在 大 卫 的 宝 座 上 治 理 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19486', '24', '23', '1', '＜ 对 将 来 的 希 望 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19487', '24', '23', '2', '耶 和 华 ─ ─ 以 色 列 的 神 斥 责 那 些 牧 养 他 百 姓 的 牧 人 ， 如 此 说 ： “ 你 们 赶 散 我 的 羊 群 ， 并 没 有 看 顾 他 们 ； 我 必 讨 你 们 这 行 恶 的 罪 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19488', '24', '23', '3', '我 要 将 我 羊 群 中 所 余 剩 的 ， 从 我 赶 他 们 到 的 各 国 内 招 聚 出 来 ， 领 他 们 归 回 本 圈 ； 他 们 也 必 生 养 众 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19489', '24', '23', '4', '我 必 设 立 照 管 他 们 的 牧 人 ， 牧 养 他 们 。 他 们 不 再 惧 怕 ， 不 再 惊 惶 ， 也 不 缺 少 一 个 ； 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19490', '24', '23', '5', '耶 和 华 说 ： “ 日 子 将 到 ， 我 要 给 大 卫 兴 起 一 个 公 义 的 苗 裔 ； 他 必 掌 王 权 ， 行 事 有 智 慧 ， 在 地 上 施 行 公 平 和 公 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19491', '24', '23', '6', '在 他 的 日 子 ， 犹 大 必 得 救 ， 以 色 列 也 安 然 居 住 。 他 的 名 必 称 为 ‘ 耶 和 华 ─ ─ 我 们 的 义 ’ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19492', '24', '23', '7', '耶 和 华 说 ： “ 日 子 将 到 ， 人 必 不 再 指 着 那 领 以 色 列 人 从 埃 及 地 上 来 永 生 的 耶 和 华 起 誓 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19493', '24', '23', '8', '却 要 指 着 那 领 以 色 列 家 的 后 裔 从 北 方 和 赶 他 们 到 的 各 国 中 上 来 、 永 生 的 耶 和 华 起 誓 。 他 们 必 住 在 本 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19494', '24', '23', '9', '＜ 对 先 知 们 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19495', '24', '23', '10', '地 满 了 行 淫 的 人 ！ 因 妄 自 赌 咒 ， 地 就 悲 哀 ； 旷 野 的 草 场 都 枯 干 了 。 他 们 所 行 的 道 乃 是 恶 的 ； 他 们 的 勇 力 使 得 不 正 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19496', '24', '23', '11', '连 先 知 带 祭 司 都 是 亵 渎 的 ， 就 是 在 我 殿 中 我 也 看 见 他 们 的 恶 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19497', '24', '23', '12', '因 此 ， 他 们 的 道 路 必 像 黑 暗 中 的 滑 地 ， 他 们 必 被 追 赶 ， 在 这 路 中 仆 倒 ； 因 为 当 追 讨 之 年 ， 我 必 使 灾 祸 临 到 他 们 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19498', '24', '23', '13', '我 在 撒 马 利 亚 的 先 知 中 曾 见 愚 妄 ； 他 们 藉 巴 力 说 预 言 ， 使 我 的 百 姓 以 色 列 走 错 了 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19499', '24', '23', '14', '我 在 耶 路 撒 冷 的 先 知 中 曾 见 可 憎 恶 的 事 ； 他 们 行 奸 淫 ， 做 事 虚 妄 ， 又 坚 固 恶 人 的 手 ， 甚 至 无 人 回 头 离 开 他 的 恶 。 他 们 在 我 面 前 都 像 所 多 玛 ； 耶 路 撒 冷 的 居 民 都 像 蛾 摩 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19500', '24', '23', '15', '所 以 万 军 之 耶 和 华 论 到 先 知 如 此 说 ： 我 必 将 茵 蔯 给 他 们 吃 ， 又 将 苦 胆 水 给 他 们 喝 ； 因 为 亵 渎 的 事 出 于 耶 路 撒 冷 的 先 知 ， 流 行 遍 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19501', '24', '23', '16', '万 军 之 耶 和 华 如 此 说 ： “ 这 些 先 知 向 你 们 说 预 言 ， 你 们 不 要 听 他 们 的 话 。 他 们 以 虚 空 教 训 你 们 ， 所 说 的 异 象 是 出 于 自 己 的 心 ， 不 是 出 于 耶 和 华 的 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19502', '24', '23', '17', '他 们 常 对 藐 视 我 的 人 说 ： ‘ 耶 和 华 说 ： 你 们 必 享 平 安 ’ ； 又 对 一 切 按 自 己 顽 梗 之 心 而 行 的 人 说 ： ‘ 必 没 有 灾 祸 临 到 你 们 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19503', '24', '23', '18', '有 谁 站 在 耶 和 华 的 会 中 得 以 听 见 并 会 悟 他 的 话 呢 ？ 有 谁 留 心 听 他 的 话 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19504', '24', '23', '19', '看 哪 ！ 耶 和 华 的 忿 怒 好 像 暴 风 ， 已 经 发 出 ； 是 暴 烈 的 旋 风 ， 必 转 到 恶 人 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19505', '24', '23', '20', '耶 和 华 的 怒 气 必 不 转 消 ， 直 到 他 心 中 所 拟 定 的 成 就 了 。 末 后 的 日 子 你 们 要 全 然 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19506', '24', '23', '21', '我 没 有 打 发 那 些 先 知 ， 他 们 竟 自 奔 跑 ； 我 没 有 对 他 们 说 话 ， 他 们 竟 自 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19507', '24', '23', '22', '他 们 若 是 站 在 我 的 会 中 ， 就 必 使 我 的 百 姓 听 我 的 话 ， 又 使 他 们 回 头 离 开 恶 道 和 他 们 所 行 的 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19508', '24', '23', '23', '耶 和 华 说 ： “ 我 岂 为 近 处 的 神 呢 ？ 不 也 为 远 处 的 神 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19509', '24', '23', '24', '耶 和 华 说 ： “ 人 岂 能 在 隐 密 处 藏 身 ， 使 我 看 不 见 他 呢 ？ ” 耶 和 华 说 ： “ 我 岂 不 充 满 天 地 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19510', '24', '23', '25', '我 已 听 见 那 些 先 知 所 说 的 ， 就 是 托 我 名 说 的 假 预 言 ， 他 们 说 ： ‘ 我 做 了 梦 ！ 我 做 了 梦 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19511', '24', '23', '26', '说 假 预 言 的 先 知 ， 就 是 预 言 本 心 诡 诈 的 先 知 ， 他 们 这 样 存 心 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19512', '24', '23', '27', '他 们 各 人 将 所 做 的 梦 对 邻 舍 述 说 ， 想 要 使 我 的 百 姓 忘 记 我 的 名 ， 正 如 他 们 列 祖 因 巴 力 忘 记 我 的 名 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19513', '24', '23', '28', '得 梦 的 先 知 可 以 述 说 那 梦 ； 得 我 话 的 人 可 以 诚 实 讲 说 我 的 话 。 糠 秕 怎 能 与 麦 子 比 较 呢 ？ 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19514', '24', '23', '29', '耶 和 华 说 ： “ 我 的 话 岂 不 像 火 ， 又 像 能 打 碎 磐 石 的 大 锤 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19515', '24', '23', '30', '耶 和 华 说 ： “ 那 些 先 知 各 从 邻 舍 偷 窃 我 的 言 语 ， 因 此 我 必 与 他 们 反 对 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19516', '24', '23', '31', '耶 和 华 说 ： “ 那 些 先 知 用 舌 头 ， 说 是 耶 和 华 说 的 ； 我 必 与 他 们 反 对 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19517', '24', '23', '32', '耶 和 华 说 ： “ 那 些 以 幻 梦 为 预 言 ， 又 述 说 这 梦 ， 以 谎 言 和 矜 夸 使 我 百 姓 走 错 了 路 的 ， 我 必 与 他 们 反 对 。 我 没 有 打 发 他 们 ， 也 没 有 吩 咐 他 们 。 他 们 与 这 百 姓 毫 无 益 处 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19518', '24', '23', '33', '＜ 耶 和 华 的 重 担 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19519', '24', '23', '34', '无 论 是 先 知 ， 是 祭 司 ， 是 百 姓 ， 说 ‘ 耶 和 华 的 默 示 ’ ， 我 必 刑 罚 那 人 和 他 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19520', '24', '23', '35', '你 们 各 人 要 对 邻 舍 ， 各 人 要 对 弟 兄 如 此 说 ： ‘ 耶 和 华 回 答 什 么 ？ ’ ‘ 耶 和 华 说 了 什 么 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19521', '24', '23', '36', '‘ 耶 和 华 的 默 示 ’ 你 们 不 可 再 提 ， 各 人 所 说 的 话 必 作 自 己 的 重 担 ｛ 重 担 和 默 示 原 文 同 ｝ ， 因 为 你 们 谬 用 永 生 神 、 万 军 之 耶 和 华 ─ ─ 我 们 神 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19522', '24', '23', '37', '你 们 要 对 先 知 如 此 说 ： ‘ 耶 和 华 回 答 你 什 么 ？ ’ ‘ 耶 和 华 说 了 什 么 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19523', '24', '23', '38', '你 们 若 说 ‘ 耶 和 华 的 默 示 ’ ， 耶 和 华 就 如 此 说 ： ‘ 因 你 们 说 “ 耶 和 华 的 默 示 ” 这 句 话 ， 我 也 打 发 人 到 你 们 那 里 去 ， 告 诉 你 们 不 可 说 “ 耶 和 华 的 默 示 ” 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19524', '24', '23', '39', '所 以 我 必 全 然 忘 记 你 们 ， 将 你 们 和 我 所 赐 给 你 们 并 你 们 列 祖 的 城 撇 弃 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19525', '24', '23', '40', '又 必 使 永 远 的 凌 辱 和 长 久 的 羞 耻 临 到 你 们 ， 是 不 能 忘 记 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19526', '24', '24', '1', '＜ 两 筐 无 花 果 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19527', '24', '24', '2', '一 筐 是 极 好 的 无 花 果 ， 好 像 是 初 熟 的 ； 一 筐 是 极 坏 的 无 花 果 ， 坏 得 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19528', '24', '24', '3', '于 是 耶 和 华 问 我 说 ： “ 耶 利 米 你 看 见 什 么 ？ ” 我 说 ： “ 我 看 见 无 花 果 ， 好 的 极 好 ， 坏 的 极 坏 ， 坏 得 不 可 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19529', '24', '24', '4', '耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19530', '24', '24', '5', '“ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 被 掳 去 的 犹 大 人 ， 就 是 我 打 发 离 开 这 地 到 迦 勒 底 人 之 地 去 的 ， 我 必 看 顾 他 们 如 这 好 无 花 果 ， 使 他 们 得 好 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19531', '24', '24', '6', '我 要 眷 顾 他 们 ， 使 他 们 得 好 处 ， 领 他 们 归 回 这 地 。 我 也 要 建 立 他 们 ， 必 不 拆 毁 ； 栽 植 他 们 ， 并 不 拔 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19532', '24', '24', '7', '我 要 赐 他 们 认 识 我 的 心 ， 知 道 我 是 耶 和 华 。 他 们 要 作 我 的 子 民 ， 我 要 作 他 们 的 神 ， 因 为 他 们 要 一 心 归 向 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19533', '24', '24', '8', '耶 和 华 如 此 说 ： “ 我 必 将 犹 大 王 西 底 家 和 他 的 首 领 ， 以 及 剩 在 这 地 耶 路 撒 冷 的 余 民 ， 并 住 在 埃 及 地 的 犹 大 人 都 交 出 来 ， 好 像 那 极 坏 、 坏 得 不 可 吃 的 无 花 果 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19534', '24', '24', '9', '我 必 使 他 们 交 出 来 ， 在 天 下 万 国 中 抛 来 抛 去 ， 遭 遇 灾 祸 ； 在 我 赶 逐 他 们 到 的 各 处 成 为 凌 辱 、 笑 谈 、 讥 刺 、 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19535', '24', '24', '10', '我 必 使 刀 剑 、 饥 荒 、 瘟 疫 临 到 他 们 ， 直 到 他 们 从 我 所 赐 给 他 们 和 他 们 列 祖 之 地 灭 绝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19536', '24', '25', '1', '＜ 从 北 方 来 的 敌 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19537', '24', '25', '2', '先 知 耶 利 米 就 将 这 话 对 犹 大 众 人 和 耶 路 撒 冷 的 一 切 居 民 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19538', '24', '25', '3', '“ 从 犹 大 王 亚 们 的 儿 子 约 西 亚 十 三 年 直 到 今 日 ， 这 二 十 三 年 之 内 ， 常 有 耶 和 华 的 话 临 到 我 ； 我 也 对 你 们 传 说 ， 就 是 从 早 起 来 传 说 ， 只 是 你 们 没 有 听 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19539', '24', '25', '4', '耶 和 华 也 从 早 起 来 ， 差 遣 他 的 仆 人 众 先 知 到 你 们 这 里 来 （ 只 是 你 们 没 有 听 从 ， 也 没 有 侧 耳 而 听 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19540', '24', '25', '5', '说 ： ‘ 你 们 各 人 当 回 头 ， 离 开 恶 道 和 所 作 的 恶 ， 便 可 居 住 耶 和 华 古 时 所 赐 给 你 们 和 你 们 列 祖 之 地 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19541', '24', '25', '6', '不 可 随 从 别 神 事 奉 敬 拜 ， 以 你 们 手 所 做 的 惹 我 发 怒 ； 这 样 ， 我 就 不 加 害 与 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19542', '24', '25', '7', '然 而 你 们 没 有 听 从 我 ， 竟 以 手 所 做 的 惹 我 发 怒 ， 陷 害 自 己 。 这 是 耶 和 华 说 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19543', '24', '25', '8', '所 以 万 军 之 耶 和 华 如 此 说 ： “ 因 为 你 们 没 有 听 从 我 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19544', '24', '25', '9', '我 必 召 北 方 的 众 族 和 我 仆 人 巴 比 伦 王 尼 布 甲 尼 撒 来 攻 击 这 地 和 这 地 的 居 民 ， 并 四 围 一 切 的 国 民 。 我 要 将 他 们 尽 行 灭 绝 ， 以 致 他 们 令 人 惊 骇 、 嗤 笑 ， 并 且 永 久 荒 凉 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19545', '24', '25', '10', '我 又 要 使 欢 喜 和 快 乐 的 声 音 ， 新 郎 和 新 妇 的 声 音 ， 推 磨 的 声 音 和 灯 的 亮 光 ， 从 他 们 中 间 止 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19546', '24', '25', '11', '这 全 地 必 然 荒 凉 ， 令 人 惊 骇 。 这 些 国 民 要 服 事 巴 比 伦 王 七 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19547', '24', '25', '12', '七 十 年 满 了 以 后 ， 我 必 刑 罚 巴 比 伦 王 和 那 国 民 ， 并 迦 勒 底 人 之 地 ， 因 他 们 的 罪 孽 使 那 地 永 远 荒 凉 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19548', '24', '25', '13', '我 也 必 使 我 向 那 地 所 说 的 话 ， 就 是 记 在 这 书 上 的 话 ， 是 耶 利 米 向 这 些 国 民 说 的 预 言 ， 都 临 到 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19549', '24', '25', '14', '因 为 有 多 国 和 大 君 王 必 使 迦 勒 底 人 作 奴 仆 ； 我 也 必 照 他 们 的 行 为 ， 按 他 们 手 所 做 的 报 应 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19550', '24', '25', '15', '＜ 神 审 判 列 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19551', '24', '25', '16', '他 们 喝 了 就 要 东 倒 西 歪 ， 并 要 发 狂 ， 因 我 使 刀 剑 临 到 他 们 中 间 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19552', '24', '25', '17', '我 就 从 耶 和 华 的 手 中 接 了 这 杯 ， 给 耶 和 华 所 差 遣 我 去 的 各 国 的 民 喝 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19553', '24', '25', '18', '就 是 耶 路 撒 冷 和 犹 大 的 城 邑 ， 并 耶 路 撒 冷 的 君 王 与 首 领 ， 使 这 城 邑 荒 凉 ， 令 人 惊 骇 、 嗤 笑 、 咒 诅 ， 正 如 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19554', '24', '25', '19', '又 有 埃 及 王 法 老 和 他 的 臣 仆 、 首 领 ， 以 及 他 的 众 民 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19555', '24', '25', '20', '并 杂 族 的 人 民 和 乌 斯 地 的 诸 王 ， 与 非 利 士 地 的 诸 王 （ 亚 实 基 伦 、 迦 萨 、 以 革 伦 ， 以 及 亚 实 突 剩 下 的 人 ） ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19556', '24', '25', '21', '以 东 、 摩 押 、 亚 扪 人 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19557', '24', '25', '22', '泰 尔 的 诸 王 、 西 顿 的 诸 王 、 海 岛 的 诸 王 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19558', '24', '25', '23', '底 但 、 提 玛 、 布 斯 ， 和 一 切 剃 周 围 头 发 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19559', '24', '25', '24', '阿 拉 伯 的 诸 王 、 住 旷 野 杂 族 人 民 的 诸 王 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19560', '24', '25', '25', '心 利 的 诸 王 、 以 拦 的 诸 王 、 米 底 亚 的 诸 王 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19561', '24', '25', '26', '北 方 远 近 的 诸 王 ， 以 及 天 下 地 上 的 万 国 喝 了 ， 以 后 示 沙 克 ｛ 就 是 巴 比 伦 ｝ 王 也 要 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19562', '24', '25', '27', '“ 你 要 对 他 们 说 ： ‘ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 们 要 喝 ， 且 要 喝 醉 ， 要 呕 吐 ， 且 要 跌 倒 ， 不 得 再 起 来 ， 都 因 我 使 刀 剑 临 到 你 们 中 间 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19563', '24', '25', '28', '“ 他 们 若 不 肯 从 你 手 接 这 杯 喝 ， 你 就 要 对 他 们 说 ： ‘ 万 军 之 耶 和 华 如 此 说 ： 你 们 一 定 要 喝 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19564', '24', '25', '29', '我 既 从 称 为 我 名 下 的 城 起 首 施 行 灾 祸 ， 你 们 能 尽 免 刑 罚 吗 ？ 你 们 必 不 能 免 ， 因 为 我 要 命 刀 剑 临 到 地 上 一 切 的 居 民 。 这 是 万 军 之 耶 和 华 说 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19565', '24', '25', '30', '“ 所 以 你 要 向 他 们 预 言 这 一 切 的 话 ， 攻 击 他 们 ， 说 ： 耶 和 华 必 从 高 天 吼 叫 ， 从 圣 所 发 声 ， 向 自 己 的 羊 群 大 声 吼 叫 ； 他 要 向 地 上 一 切 的 居 民 呐 喊 ， 像 踹 葡 萄 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19566', '24', '25', '31', '必 有 响 声 达 到 地 极 ， 因 为 耶 和 华 与 列 国 相 争 ； 凡 有 血 气 的 ， 他 必 审 问 ； 至 于 恶 人 ， 他 必 交 给 刀 剑 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19567', '24', '25', '32', '万 军 之 耶 和 华 如 此 说 ： 看 哪 ， 必 有 灾 祸 从 这 国 发 到 那 国 ， 并 有 大 暴 风 从 地 极 刮 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19568', '24', '25', '33', '“ 到 那 日 ， 从 地 这 边 直 到 地 那 边 都 有 耶 和 华 所 杀 戮 的 。 必 无 人 哀 哭 ， 不 得 收 殓 ， 不 得 葬 埋 ， 必 在 地 上 成 为 粪 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19569', '24', '25', '34', '牧 人 哪 ， 你 们 当 哀 号 ， 呼 喊 ； 群 众 的 头 目 啊 ， 你 们 要 滚 在 灰 中 ； 因 为 你 们 被 杀 戮 分 散 的 日 子 足 足 来 到 。 你 们 要 跌 碎 ， 好 像 美 器 打 碎 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19570', '24', '25', '35', '牧 人 无 路 逃 跑 ； 群 众 的 头 目 也 无 法 逃 脱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19571', '24', '25', '36', '听 啊 ， 有 牧 人 呼 喊 ， 有 群 众 头 目 哀 号 的 声 音 ， 因 为 耶 和 华 使 他 们 的 草 场 变 为 荒 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19572', '24', '25', '37', '耶 和 华 发 出 猛 烈 的 怒 气 ， 平 安 的 羊 圈 就 都 寂 静 无 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19573', '24', '25', '38', '他 离 了 隐 密 处 像 狮 子 一 样 ， 他 们 的 地 ， 因 刀 剑 凶 猛 的 欺 压 ， 又 因 他 猛 烈 的 怒 气 都 成 为 可 惊 骇 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19574', '24', '26', '1', '＜ 耶 利 米 受 审 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19575', '24', '26', '2', '“ 耶 和 华 如 此 说 ： 你 站 在 耶 和 华 殿 的 院 内 ， 对 犹 大 众 城 邑 的 人 ， 就 是 到 耶 和 华 殿 来 礼 拜 的 ， 说 我 所 吩 咐 你 的 一 切 话 ， 一 字 不 可 删 减 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19576', '24', '26', '3', '或 者 他 们 肯 听 从 ， 各 人 回 头 离 开 恶 道 ， 使 我 后 悔 不 将 我 因 他 们 所 行 的 恶 ， 想 要 施 行 的 灾 祸 降 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19577', '24', '26', '4', '你 要 对 他 们 说 ， 耶 和 华 如 此 说 ： ‘ 你 们 若 不 听 从 我 ， 不 遵 行 我 设 立 在 你 们 面 前 的 律 法 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19578', '24', '26', '5', '不 听 我 从 早 起 来 差 遣 到 你 们 那 里 去 我 仆 人 众 先 知 的 话 （ 你 们 还 是 没 有 听 从 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19579', '24', '26', '6', '我 就 必 使 这 殿 如 示 罗 ， 使 这 城 为 地 上 万 国 所 咒 诅 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19580', '24', '26', '7', '耶 利 米 在 耶 和 华 殿 中 说 的 这 些 话 ， 祭 司 、 先 知 与 众 民 都 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19581', '24', '26', '8', '耶 利 米 说 完 了 耶 和 华 所 吩 咐 他 对 众 人 说 的 一 切 话 ， 祭 司 、 先 知 与 众 民 都 来 抓 住 他 ， 说 ： “ 你 必 要 死 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19582', '24', '26', '9', '你 为 何 托 耶 和 华 的 名 预 言 ， 说 这 殿 必 如 示 罗 ， 这 城 必 变 为 荒 场 无 人 居 住 呢 ？ ” 于 是 众 民 都 在 耶 和 华 的 殿 中 聚 集 到 耶 利 米 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19583', '24', '26', '10', '犹 大 的 首 领 听 见 这 事 ， 就 从 王 宫 上 到 耶 和 华 的 殿 ， 坐 在 耶 和 华 殿 的 新 门 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19584', '24', '26', '11', '祭 司 、 先 知 对 首 领 和 众 民 说 ： “ 这 人 是 该 死 的 ； 因 为 他 说 预 言 攻 击 这 城 ， 正 如 你 们 亲 耳 所 听 见 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19585', '24', '26', '12', '耶 利 米 就 对 众 首 领 和 众 民 说 ： “ 耶 和 华 差 遣 我 预 言 ， 攻 击 这 殿 和 这 城 ， 说 你 们 所 听 见 的 这 一 切 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19586', '24', '26', '13', '现 在 要 改 正 你 们 的 行 动 作 为 ， 听 从 耶 和 华 ─ ─ 你 们 神 的 话 ， 他 就 必 后 悔 ， 不 将 所 说 的 灾 祸 降 与 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19587', '24', '26', '14', '至 于 我 ， 我 在 你 们 手 中 ， 你 们 眼 看 何 为 善 ， 何 为 正 ， 就 那 样 待 我 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19588', '24', '26', '15', '但 你 们 要 确 实 地 知 道 ， 若 把 我 治 死 ， 就 使 无 辜 人 的 血 归 到 你 们 和 这 城 ， 并 其 中 的 居 民 了 ； 因 为 耶 和 华 实 在 差 遣 我 到 你 们 这 里 来 ， 将 这 一 切 话 传 与 你 们 耳 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19589', '24', '26', '16', '首 领 和 众 民 就 对 祭 司 、 先 知 说 ： “ 这 人 是 不 该 死 的 ， 因 为 他 是 奉 耶 和 华 ─ ─ 我 们 神 的 名 向 我 们 说 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19590', '24', '26', '17', '国 中 的 长 老 就 有 几 个 人 起 来 ， 对 聚 会 的 众 民 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19591', '24', '26', '18', '“ 当 犹 大 王 希 西 家 的 日 子 ， 有 摩 利 沙 人 弥 迦 对 犹 大 众 人 预 言 说 ： 万 军 之 耶 和 华 如 此 说 ： 锡 安 必 被 耕 种 像 一 块 田 ； 耶 路 撒 冷 必 变 为 乱 堆 ； 这 殿 的 山 必 像 丛 林 的 高 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19592', '24', '26', '19', '犹 大 王 希 西 家 和 犹 大 众 人 岂 是 把 他 治 死 呢 ？ 希 西 家 岂 不 是 敬 畏 耶 和 华 、 恳 求 他 的 恩 吗 ？ 耶 和 华 就 后 悔 ， 不 把 自 己 所 说 的 灾 祸 降 与 他 们 。 若 治 死 这 人 ， 我 们 就 作 了 大 恶 ， 自 害 己 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19593', '24', '26', '20', '（ 又 有 一 个 人 奉 耶 和 华 的 名 说 预 言 ， 是 基 列 ． 耶 琳 人 示 玛 雅 的 儿 子 乌 利 亚 ， 他 照 耶 利 米 的 一 切 话 说 预 言 ， 攻 击 这 城 和 这 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19594', '24', '26', '21', '约 雅 敬 王 和 他 众 勇 士 、 众 首 领 听 见 了 乌 利 亚 的 话 ， 王 就 想 要 把 他 治 死 。 乌 利 亚 听 见 就 惧 怕 ， 逃 往 埃 及 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19595', '24', '26', '22', '约 雅 敬 王 便 打 发 亚 革 波 的 儿 子 以 利 拿 单 ， 带 领 几 个 人 往 埃 及 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19596', '24', '26', '23', '他 们 就 从 埃 及 将 乌 利 亚 带 出 来 ， 送 到 约 雅 敬 王 那 里 ； 王 用 刀 杀 了 他 ， 把 他 的 尸 首 抛 在 平 民 的 坟 地 中 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19597', '24', '26', '24', '然 而 ， 沙 番 的 儿 子 亚 希 甘 保 护 耶 利 米 ， 不 交 在 百 姓 的 手 中 治 死 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19598', '24', '27', '1', '＜ 耶 利 米 负 轭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19599', '24', '27', '2', '“ 耶 和 华 对 我 如 此 说 ： 你 做 绳 索 与 轭 ， 加 在 自 己 的 颈 项 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19600', '24', '27', '3', '藉 那 些 来 到 耶 路 撒 冷 见 犹 大 王 西 底 家 的 使 臣 之 手 ， 把 绳 索 与 轭 送 到 以 东 王 、 摩 押 王 、 亚 扪 王 、 泰 尔 王 、 西 顿 王 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19601', '24', '27', '4', '且 嘱 咐 使 臣 ， 传 与 他 们 的 主 人 说 ， 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19602', '24', '27', '5', '我 用 大 能 和 伸 出 来 的 膀 臂 ， 创 造 大 地 和 地 上 的 人 民 、 牲 畜 。 我 看 给 谁 相 宜 ， 就 把 地 给 谁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19603', '24', '27', '6', '现 在 我 将 这 些 地 都 交 给 我 仆 人 巴 比 伦 王 尼 布 甲 尼 撒 的 手 ， 我 也 将 田 野 的 走 兽 给 他 使 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19604', '24', '27', '7', '列 国 都 必 服 事 他 和 他 的 儿 孙 ， 直 到 他 本 国 遭 报 的 日 期 来 到 。 那 时 ， 多 国 和 大 君 王 要 使 他 作 他 们 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19605', '24', '27', '8', '“ 无 论 哪 一 邦 哪 一 国 ， 不 肯 服 事 这 巴 比 伦 王 尼 布 甲 尼 撒 ， 也 不 把 颈 项 放 在 巴 比 伦 王 的 轭 下 ， 我 必 用 刀 剑 、 饥 荒 、 瘟 疫 刑 罚 那 邦 ， 直 到 我 藉 巴 比 伦 王 的 手 将 他 们 毁 灭 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19606', '24', '27', '9', '至 于 你 们 ， 不 可 听 从 你 们 的 先 知 和 占 卜 的 、 圆 梦 的 、 观 兆 的 ， 以 及 行 邪 术 的 ； 他 们 告 诉 你 们 说 ： ‘ 你 们 不 致 服 事 巴 比 伦 王 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19607', '24', '27', '10', '他 们 向 你 们 说 假 预 言 ， 要 叫 你 们 迁 移 ， 远 离 本 地 ， 以 致 我 将 你 们 赶 出 去 ， 使 你 们 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19608', '24', '27', '11', '但 哪 一 邦 肯 把 颈 项 放 在 巴 比 伦 王 的 轭 下 服 事 他 ， 我 必 使 那 邦 仍 在 本 地 存 留 ， 得 以 耕 种 居 住 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19609', '24', '27', '12', '我 就 照 这 一 切 的 话 对 犹 大 王 西 底 家 说 ： “ 要 把 你 们 的 颈 项 放 在 巴 比 伦 王 的 轭 下 ， 服 事 他 和 他 的 百 姓 ， 便 得 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19610', '24', '27', '13', '你 和 你 的 百 姓 为 何 要 因 刀 剑 、 饥 荒 、 瘟 疫 死 亡 ， 正 如 耶 和 华 论 到 不 服 事 巴 比 伦 王 的 那 国 说 的 话 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19611', '24', '27', '14', '不 可 听 那 些 先 知 对 你 们 所 说 的 话 ； 他 们 说 ： ‘ 你 们 不 致 服 事 巴 比 伦 王 ’ ， 其 实 他 们 向 你 们 说 假 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19612', '24', '27', '15', '耶 和 华 说 ： ‘ 我 并 没 有 打 发 他 们 ， 他 们 却 托 我 的 名 说 假 预 言 ， 好 使 我 将 你 们 和 向 你 们 说 预 言 的 那 些 先 知 赶 出 去 ， 一 同 灭 亡 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19613', '24', '27', '16', '我 又 对 祭 司 和 这 众 民 说 ： “ 耶 和 华 如 此 说 ： 你 们 不 可 听 那 先 知 对 你 们 所 说 的 预 言 。 他 们 说 ： ‘ 耶 和 华 殿 中 的 器 皿 快 要 从 巴 比 伦 带 回 来 ’ ； 其 实 他 们 向 你 们 说 假 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19614', '24', '27', '17', '不 可 听 从 他 们 ， 只 管 服 事 巴 比 伦 王 便 得 存 活 。 这 城 何 致 变 为 荒 场 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19615', '24', '27', '18', '他 们 若 果 是 先 知 ， 有 耶 和 华 的 话 临 到 他 们 ， 让 他 们 祈 求 万 军 之 耶 和 华 ， 使 那 在 耶 和 华 殿 中 和 犹 大 王 宫 内 ， 并 耶 路 撒 冷 剩 下 的 器 皿 ， 不 被 带 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19616', '24', '27', '19', '（ 因 为 万 军 之 耶 和 华 论 到 柱 子 、 铜 海 、 盆 座 ， 并 剩 在 这 城 里 的 器 皿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19617', '24', '27', '20', '就 是 巴 比 伦 王 尼 布 甲 尼 撒 掳 掠 犹 大 王 约 雅 敬 的 儿 子 耶 哥 尼 雅 ， 和 犹 大 、 耶 路 撒 冷 一 切 贵 胄 的 时 候 所 没 有 掠 去 的 器 皿 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19618', '24', '27', '21', '论 到 那 在 耶 和 华 殿 中 和 犹 大 王 宫 内 ， 并 耶 路 撒 冷 剩 下 的 器 皿 ， 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19619', '24', '27', '22', '必 被 带 到 巴 比 伦 存 在 那 里 ， 直 到 我 眷 顾 以 色 列 人 的 日 子 。 那 时 ， 我 必 将 这 器 皿 带 回 来 ， 交 还 此 地 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19620', '24', '28', '1', '＜ 耶 利 米 和 先 知 哈 拿 尼 雅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19621', '24', '28', '2', '“ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 已 经 折 断 巴 比 伦 王 的 轭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19622', '24', '28', '3', '二 年 之 内 ， 我 要 将 巴 比 伦 王 尼 布 甲 尼 撒 从 这 地 掠 到 巴 比 伦 的 器 皿 ， 就 是 耶 和 华 殿 中 的 一 切 器 皿 都 带 回 此 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19623', '24', '28', '4', '我 又 要 将 犹 大 王 约 雅 敬 的 儿 子 耶 哥 尼 雅 和 被 掳 到 巴 比 伦 去 的 一 切 犹 大 人 带 回 此 地 ， 因 为 我 要 折 断 巴 比 伦 王 的 轭 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19624', '24', '28', '5', '先 知 耶 利 米 当 着 祭 司 和 站 在 耶 和 华 殿 里 的 众 民 对 先 知 哈 拿 尼 雅 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19625', '24', '28', '6', '“ 阿 们 ！ 愿 耶 和 华 如 此 行 ， 愿 耶 和 华 成 就 你 所 预 言 的 话 ， 将 耶 和 华 殿 中 的 器 皿 和 一 切 被 掳 去 的 人 从 巴 比 伦 带 回 此 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19626', '24', '28', '7', '然 而 我 向 你 和 众 民 耳 中 所 要 说 的 话 ， 你 应 当 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19627', '24', '28', '8', '从 古 以 来 ， 在 你 我 以 前 的 先 知 ， 向 多 国 和 大 邦 说 预 言 ， 论 到 争 战 、 灾 祸 、 瘟 疫 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19628', '24', '28', '9', '先 知 预 言 的 平 安 ， 到 话 语 成 就 的 时 候 ， 人 便 知 道 他 真 是 耶 和 华 所 差 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19629', '24', '28', '10', '于 是 ， 先 知 哈 拿 尼 雅 将 先 知 耶 利 米 颈 项 上 的 轭 取 下 来 ， 折 断 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19630', '24', '28', '11', '哈 拿 尼 雅 又 当 着 众 民 说 ： “ 耶 和 华 如 此 说 ： 二 年 之 内 我 必 照 样 从 列 国 人 的 颈 项 上 折 断 巴 比 伦 王 尼 布 甲 尼 撒 的 轭 。 ” 于 是 先 知 耶 利 米 就 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19631', '24', '28', '12', '先 知 哈 拿 尼 雅 把 先 知 耶 利 米 颈 项 上 的 轭 折 断 以 后 ， 耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19632', '24', '28', '13', '“ 你 去 告 诉 哈 拿 尼 雅 说 ， 耶 和 华 如 此 说 ： 你 折 断 木 轭 ， 却 换 了 铁 轭 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19633', '24', '28', '14', '因 为 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 已 将 铁 轭 加 在 这 些 国 的 颈 项 上 ， 使 他 们 服 事 巴 比 伦 王 尼 布 甲 尼 撒 ， 他 们 总 要 服 事 他 ； 我 也 把 田 野 的 走 兽 给 了 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19634', '24', '28', '15', '于 是 先 知 耶 利 米 对 先 知 哈 拿 尼 雅 说 ： “ 哈 拿 尼 雅 啊 ， 你 应 当 听 ！ 耶 和 华 并 没 有 差 遣 你 ， 你 竟 使 这 百 姓 倚 靠 谎 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19635', '24', '28', '16', '所 以 耶 和 华 如 此 说 ： 看 哪 ， 我 要 叫 你 去 世 ， 你 今 年 必 死 ， 因 为 你 向 耶 和 华 说 了 叛 逆 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19636', '24', '28', '17', '这 样 ， 先 知 哈 拿 尼 雅 当 年 七 月 间 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19637', '24', '29', '1', '＜ 耶 利 米 写 信 给 巴 比 伦 的 犹 大 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19638', '24', '29', '2', '（ 这 在 耶 哥 尼 雅 王 和 太 后 、 太 监 ， 并 犹 大 、 耶 路 撒 冷 的 首 领 ， 以 及 工 匠 、 铁 匠 都 离 了 耶 路 撒 冷 以 后 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19639', '24', '29', '3', '他 藉 沙 番 的 儿 子 以 利 亚 萨 和 希 勒 家 的 儿 子 基 玛 利 的 手 寄 去 。 他 们 二 人 是 犹 大 王 西 底 家 打 发 往 巴 比 伦 去 见 尼 布 甲 尼 撒 王 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19640', '24', '29', '4', '信 上 说 ： “ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 对 一 切 被 掳 去 的 （ 就 是 我 使 他 们 从 耶 路 撒 冷 被 掳 到 巴 比 伦 的 人 ） 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19641', '24', '29', '5', '你 们 要 盖 造 房 屋 ， 住 在 其 中 ； 栽 种 田 园 ， 吃 其 中 所 产 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19642', '24', '29', '6', '娶 妻 生 儿 女 ， 为 你 们 的 儿 子 娶 妻 ， 使 你 们 的 女 儿 嫁 人 ， 生 儿 养 女 。 在 那 里 生 养 众 多 ， 不 致 减 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19643', '24', '29', '7', '我 所 使 你 们 被 掳 到 的 那 城 ， 你 们 要 为 那 城 求 平 安 ， 为 那 城 祷 告 耶 和 华 ； 因 为 那 城 得 平 安 ， 你 们 也 随 着 得 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19644', '24', '29', '8', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 不 要 被 你 们 中 间 的 先 知 和 占 卜 的 诱 惑 ， 也 不 要 听 信 自 己 所 做 的 梦 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19645', '24', '29', '9', '因 为 他 们 托 我 的 名 对 你 们 说 假 预 言 ， 我 并 没 有 差 遣 他 们 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19646', '24', '29', '10', '“ 耶 和 华 如 此 说 ： 为 巴 比 伦 所 定 的 七 十 年 满 了 以 后 ， 我 要 眷 顾 你 们 ， 向 你 们 成 就 我 的 恩 言 ， 使 你 们 仍 回 此 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19647', '24', '29', '11', '耶 和 华 说 ： 我 知 道 我 向 你 们 所 怀 的 意 念 是 赐 平 安 的 意 念 ， 不 是 降 灾 祸 的 意 念 ， 要 叫 你 们 末 后 有 指 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19648', '24', '29', '12', '你 们 要 呼 求 我 ， 祷 告 我 ， 我 就 应 允 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19649', '24', '29', '13', '你 们 寻 求 我 ， 若 专 心 寻 求 我 ， 就 必 寻 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19650', '24', '29', '14', '耶 和 华 说 ： 我 必 被 你 们 寻 见 ， 我 也 必 使 你 们 被 掳 的 人 归 回 ， 将 你 们 从 各 国 中 和 我 所 赶 你 们 到 的 各 处 招 聚 了 来 ， 又 将 你 们 带 回 我 使 你 们 被 掳 掠 离 开 的 地 方 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19651', '24', '29', '15', '“ 你 们 说 ： ‘ 耶 和 华 在 巴 比 伦 为 我 们 兴 起 先 知 ’ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19652', '24', '29', '16', '所 以 耶 和 华 论 到 坐 大 卫 宝 座 的 王 和 住 在 这 城 里 的 一 切 百 姓 ， 就 是 未 曾 与 你 们 一 同 被 掳 的 弟 兄 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19653', '24', '29', '17', '万 军 之 耶 和 华 如 此 说 ： ‘ 看 哪 ， 我 必 使 刀 剑 、 饥 荒 、 瘟 疫 临 到 他 们 ， 使 他 们 像 极 坏 的 无 花 果 ， 坏 得 不 可 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19654', '24', '29', '18', '我 必 用 刀 剑 、 饥 荒 、 瘟 疫 追 赶 他 们 ， 使 他 们 在 天 下 万 国 抛 来 抛 去 ， 在 我 所 赶 他 们 到 的 各 国 中 ， 令 人 咒 诅 、 惊 骇 、 嗤 笑 、 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19655', '24', '29', '19', '耶 和 华 说 ： 这 是 因 为 他 们 没 有 听 从 我 的 话 ， 就 是 我 从 早 起 来 差 遣 我 仆 人 众 先 知 去 说 的 ， 无 奈 他 们 不 听 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19656', '24', '29', '20', '所 以 你 们 一 切 被 掳 去 的 ， 就 是 我 从 耶 路 撒 冷 打 发 到 巴 比 伦 去 的 ， 当 听 耶 和 华 的 话 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19657', '24', '29', '21', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 论 到 哥 赖 雅 的 儿 子 亚 哈 ， 并 玛 西 雅 的 儿 子 西 底 家 ， 如 此 说 ： “ 他 们 是 托 我 名 向 你 们 说 假 预 言 的 ， 我 必 将 他 们 交 在 巴 比 伦 王 尼 布 甲 尼 撒 的 手 中 ； 他 要 在 你 们 眼 前 杀 害 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19658', '24', '29', '22', '住 巴 比 伦 一 切 被 掳 的 犹 大 人 必 藉 这 二 人 赌 咒 说 ： ‘ 愿 耶 和 华 使 你 像 巴 比 伦 王 在 火 中 烧 的 西 底 家 和 亚 哈 一 样 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19659', '24', '29', '23', '这 二 人 是 在 以 色 列 中 行 了 丑 事 ， 与 邻 舍 的 妻 行 淫 ， 又 假 托 我 名 说 我 未 曾 吩 咐 他 们 的 话 。 知 道 的 是 我 ， 作 见 证 的 也 是 我 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19660', '24', '29', '24', '＜ 示 玛 雅 的 信 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19661', '24', '29', '25', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 曾 用 自 己 的 名 寄 信 给 耶 路 撒 冷 的 众 民 和 祭 司 玛 西 雅 的 儿 子 西 番 雅 ， 并 众 祭 司 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19662', '24', '29', '26', '‘ 耶 和 华 已 经 立 你 西 番 雅 为 祭 司 ， 代 替 祭 司 耶 何 耶 大 ， 使 耶 和 华 殿 中 有 官 长 ， 好 将 一 切 狂 妄 自 称 为 先 知 的 人 用 枷 枷 住 ， 用 锁 锁 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19663', '24', '29', '27', '现 在 亚 拿 突 人 耶 利 米 向 你 们 自 称 为 先 知 ， 你 们 为 何 没 有 责 备 他 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19664', '24', '29', '28', '因 为 他 寄 信 给 我 们 在 巴 比 伦 的 人 说 ： 被 掳 的 事 必 长 久 。 你 们 要 盖 造 房 屋 ， 住 在 其 中 ； 栽 种 田 园 ， 吃 其 中 所 产 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19665', '24', '29', '29', '祭 司 西 番 雅 就 把 这 信 念 给 先 知 耶 利 米 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19666', '24', '29', '30', '于 是 耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19667', '24', '29', '31', '“ 你 当 寄 信 给 一 切 被 掳 的 人 说 ： ‘ 耶 和 华 论 到 尼 希 兰 人 示 玛 雅 说 ： 因 为 示 玛 雅 向 你 们 说 预 言 ， 我 并 没 有 差 遣 他 ， 他 使 你 们 倚 靠 谎 言 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19668', '24', '29', '32', '所 以 耶 和 华 如 此 说 ： 我 必 刑 罚 尼 希 兰 人 示 玛 雅 和 他 的 后 裔 ， 他 必 无 一 人 存 留 住 在 这 民 中 ， 也 不 得 见 我 所 要 赐 与 我 百 姓 的 福 乐 ， 因 为 他 向 耶 和 华 说 了 叛 逆 的 话 。 这 是 耶 和 华 说 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19669', '24', '30', '1', '＜ 耶 和 华 给 他 子 民 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19670', '24', '30', '2', '“ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 将 我 对 你 说 过 的 一 切 话 都 写 在 书 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19671', '24', '30', '3', '耶 和 华 说 ： 日 子 将 到 ， 我 要 使 我 的 百 姓 以 色 列 和 犹 大 被 掳 的 人 归 回 ； 我 也 要 使 他 们 回 到 我 所 赐 给 他 们 列 祖 之 地 ， 他 们 就 得 这 地 为 业 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19672', '24', '30', '4', '以 下 是 耶 和 华 论 到 以 色 列 和 犹 大 所 说 的 话 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19673', '24', '30', '5', '耶 和 华 如 此 说 ： 我 们 听 见 声 音 ， 是 战 抖 惧 怕 而 不 平 安 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19674', '24', '30', '6', '你 们 且 访 问 看 看 ， 男 人 有 产 难 吗 ？ 我 怎 么 看 见 人 人 用 手 掐 腰 ， 像 产 难 的 妇 人 ， 脸 面 都 变 青 了 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19675', '24', '30', '7', '哀 哉 ！ 那 日 为 大 ， 无 日 可 比 ； 这 是 雅 各 遭 难 的 时 候 ， 但 他 必 被 救 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19676', '24', '30', '8', '万 军 之 耶 和 华 说 ： “ 到 那 日 ， 我 必 从 你 颈 项 上 折 断 仇 敌 的 轭 ， 扭 开 他 的 绳 索 ； 外 邦 人 不 得 再 使 你 作 他 们 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19677', '24', '30', '9', '你 们 却 要 事 奉 耶 和 华 ─ ─ 你 们 的 神 和 我 为 你 们 所 要 兴 起 的 王 大 卫 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19678', '24', '30', '10', '故 此 ， 耶 和 华 说 ： 我 的 仆 人 雅 各 啊 ， 不 要 惧 怕 ； 以 色 列 啊 ， 不 要 惊 惶 ； 因 我 要 从 远 方 拯 救 你 ， 从 被 掳 到 之 地 拯 救 你 的 后 裔 ； 雅 各 必 回 来 得 享 平 靖 安 逸 ， 无 人 使 他 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19679', '24', '30', '11', '因 我 与 你 同 在 ， 要 拯 救 你 ， 也 要 将 所 赶 散 你 到 的 那 些 国 灭 绝 净 尽 ， 却 不 将 你 灭 绝 净 尽 ， 倒 要 从 宽 惩 治 你 ， 万 不 能 不 罚 你 ｛ 不 罚 你 ： 或 译 以 你 为 无 罪 ｝ 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19680', '24', '30', '12', '耶 和 华 如 此 说 ： 你 的 损 伤 无 法 医 治 ； 你 的 伤 痕 极 其 重 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19681', '24', '30', '13', '无 人 为 你 分 诉 ， 使 你 的 伤 痕 得 以 缠 裹 ； 你 没 有 医 治 的 良 药 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19682', '24', '30', '14', '你 所 亲 爱 的 都 忘 记 你 ， 不 来 探 问 ｛ 或 译 ： 理 会 ｝ 你 。 我 因 你 的 罪 孽 甚 大 ， 罪 恶 众 多 ， 曾 用 仇 敌 加 的 伤 害 伤 害 你 ， 用 残 忍 者 的 惩 治 惩 治 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19683', '24', '30', '15', '你 为 何 因 损 伤 哀 号 呢 ？ 你 的 痛 苦 无 法 医 治 。 我 因 你 的 罪 孽 甚 大 ， 罪 恶 众 多 ， 曾 将 这 些 加 在 你 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19684', '24', '30', '16', '故 此 ， 凡 吞 吃 你 的 必 被 吞 吃 ； 你 的 敌 人 个 个 都 被 掳 去 ； 掳 掠 你 的 必 成 为 掳 物 ； 抢 夺 你 的 必 成 为 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19685', '24', '30', '17', '耶 和 华 说 ： 我 必 使 你 痊 愈 ， 医 好 你 的 伤 痕 ， 都 因 人 称 你 为 被 赶 散 的 ， 说 ： 这 是 锡 安 ， 无 人 来 探 问 ｛ 或 译 ： 理 会 ｝ 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19686', '24', '30', '18', '耶 和 华 如 此 说 ： 我 必 使 雅 各 被 掳 去 的 帐 棚 归 回 ， 也 必 顾 惜 他 的 住 处 。 城 必 建 造 在 原 旧 的 山 冈 ； 宫 殿 也 照 旧 有 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19687', '24', '30', '19', '必 有 感 谢 和 欢 乐 的 声 音 从 其 中 发 出 ， 我 要 使 他 们 增 多 ， 不 致 减 少 ； 使 他 们 尊 荣 ， 不 致 卑 微 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19688', '24', '30', '20', '他 们 的 儿 女 要 如 往 日 ； 他 们 的 会 众 坚 立 在 我 面 前 ； 凡 欺 压 他 们 的 ， 我 必 刑 罚 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19689', '24', '30', '21', '他 们 的 君 王 必 是 属 乎 他 们 的 ； 掌 权 的 必 从 他 们 中 间 而 出 。 我 要 使 他 就 近 我 ， 他 也 要 亲 近 我 ； 不 然 ， 谁 有 胆 量 亲 近 我 呢 ？ 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19690', '24', '30', '22', '你 们 要 作 我 的 子 民 ， 我 要 作 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19691', '24', '30', '23', '看 哪 ， 耶 和 华 的 忿 怒 好 像 暴 风 已 经 发 出 ； 是 扫 灭 的 暴 风 ， 必 转 到 恶 人 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19692', '24', '30', '24', '耶 和 华 的 烈 怒 必 不 转 消 ， 直 到 他 心 中 所 拟 定 的 成 就 了 ； 末 后 的 日 子 你 们 要 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19693', '24', '31', '1', '＜ 以 色 列 人 还 乡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19694', '24', '31', '2', '耶 和 华 如 此 说 ： 脱 离 刀 剑 的 就 是 以 色 列 人 。 我 使 他 享 安 息 的 时 候 ， 他 曾 在 旷 野 蒙 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19695', '24', '31', '3', '古 时 ｛ 或 译 ： 从 远 方 ｝ 耶 和 华 向 以 色 列 ｛ 原 文 是 我 ｝ 显 现 ， 说 ： 我 以 永 远 的 爱 爱 你 ， 因 此 我 以 慈 爱 吸 引 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19696', '24', '31', '4', '以 色 列 的 民 ｛ 原 文 是 处 女 ｝ 哪 ， 我 要 再 建 立 你 ， 你 就 被 建 立 ； 你 必 再 以 击 鼓 为 美 ， 与 欢 乐 的 人 一 同 跳 舞 而 出 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19697', '24', '31', '5', '又 必 在 撒 马 利 亚 的 山 上 栽 种 葡 萄 园 ， 栽 种 的 人 要 享 用 所 结 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19698', '24', '31', '6', '日 子 必 到 ， 以 法 莲 山 上 守 望 的 人 必 呼 叫 说 ： 起 来 吧 ！ 我 们 可 以 上 锡 安 ， 到 耶 和 华 ─ ─ 我 们 的 神 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19699', '24', '31', '7', '耶 和 华 如 此 说 ： 你 们 当 为 雅 各 欢 乐 歌 唱 ， 因 万 国 中 为 首 的 欢 呼 。 当 传 扬 颂 赞 说 ： 耶 和 华 啊 ， 求 你 拯 救 你 的 百 姓 以 色 列 所 剩 下 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19700', '24', '31', '8', '我 必 将 他 们 从 北 方 领 来 ， 从 地 极 招 聚 ； 同 着 他 们 来 的 有 瞎 子 、 瘸 子 、 孕 妇 、 产 妇 ； 他 们 必 成 为 大 帮 回 到 这 里 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19701', '24', '31', '9', '他 们 要 哭 泣 而 来 。 我 要 照 他 们 恳 求 的 引 导 他 们 ， 使 他 们 在 河 水 旁 走 正 直 的 路 ， 在 其 上 不 致 绊 跌 ； 因 为 我 是 以 色 列 的 父 ， 以 法 莲 是 我 的 长 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19702', '24', '31', '10', '列 国 啊 ， 要 听 耶 和 华 的 话 ， 传 扬 在 远 处 的 海 岛 说 ： 赶 散 以 色 列 的 必 招 聚 他 ， 又 看 守 他 ， 好 像 牧 人 看 守 羊 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19703', '24', '31', '11', '因 耶 和 华 救 赎 了 雅 各 ， 救 赎 他 脱 离 比 他 更 强 之 人 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19704', '24', '31', '12', '他 们 要 来 到 锡 安 的 高 处 歌 唱 ， 又 流 归 耶 和 华 施 恩 之 地 ， 就 是 有 五 谷 、 新 酒 ， 和 油 ， 并 羊 羔 、 牛 犊 之 地 。 他 们 的 心 必 像 浇 灌 的 园 子 ； 他 们 也 不 再 有 一 点 愁 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19705', '24', '31', '13', '那 时 ， 处 女 必 欢 乐 跳 舞 ； 年 少 的 、 年 老 的 ， 也 必 一 同 欢 乐 ； 因 为 我 要 使 他 们 的 悲 哀 变 为 欢 喜 ， 并 要 安 慰 他 们 ， 使 他 们 的 愁 烦 转 为 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19706', '24', '31', '14', '我 必 以 肥 油 使 祭 司 的 心 满 足 ； 我 的 百 姓 也 要 因 我 的 恩 惠 知 足 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19707', '24', '31', '15', '＜ 耶 和 华 怜 悯 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19708', '24', '31', '16', '耶 和 华 如 此 说 ： 你 禁 止 声 音 不 要 哀 哭 ， 禁 止 眼 目 不 要 流 泪 ， 因 你 所 做 之 工 必 有 赏 赐 ； 他 们 必 从 敌 国 归 回 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19709', '24', '31', '17', '耶 和 华 说 ： 你 末 后 必 有 指 望 ； 你 的 儿 女 必 回 到 自 己 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19710', '24', '31', '18', '我 听 见 以 法 莲 为 自 己 悲 叹 说 ： 你 责 罚 我 ， 我 便 受 责 罚 ， 像 不 惯 负 轭 的 牛 犊 一 样 。 求 你 使 我 回 转 ， 我 便 回 转 ， 因 为 你 是 耶 和 华 ─ ─ 我 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19711', '24', '31', '19', '我 回 转 以 后 就 真 正 懊 悔 ； 受 教 以 后 就 拍 腿 叹 息 ； 我 因 担 当 幼 年 的 凌 辱 就 抱 愧 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19712', '24', '31', '20', '耶 和 华 说 ： 以 法 莲 是 我 的 爱 子 吗 ？ 是 可 喜 悦 的 孩 子 吗 ？ 我 每 逢 责 备 他 ， 仍 深 顾 念 他 ； 所 以 我 的 心 肠 恋 慕 他 ； 我 必 要 怜 悯 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19713', '24', '31', '21', '以 色 列 民 ｛ 原 文 是 处 女 ｝ 哪 ， 你 当 为 自 己 设 立 指 路 碑 ， 竖 起 引 路 柱 。 你 要 留 心 向 大 路 ， 就 是 你 所 去 的 原 路 ； 你 当 回 转 ， 回 转 到 你 这 些 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19714', '24', '31', '22', '背 道 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 你 反 来 覆 去 要 到 几 时 呢 ？ 耶 和 华 在 地 上 造 了 一 件 新 事 ， 就 是 女 子 护 卫 男 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19715', '24', '31', '23', '＜ 神 子 民 的 光 明 前 途 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19716', '24', '31', '24', '犹 大 和 属 犹 大 城 邑 的 人 ， 农 夫 和 放 羊 的 人 ， 要 一 同 住 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19717', '24', '31', '25', '疲 乏 的 人 ， 我 使 他 饱 饫 ； 愁 烦 的 人 ， 我 使 他 知 足 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19718', '24', '31', '26', '先 知 说 ： “ 我 醒 了 ， 觉 着 睡 得 香 甜 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19719', '24', '31', '27', '耶 和 华 说 ： “ 日 子 将 到 ， 我 要 把 人 的 种 和 牲 畜 的 种 播 种 在 以 色 列 家 和 犹 大 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19720', '24', '31', '28', '我 先 前 怎 样 留 意 将 他 们 拔 出 、 拆 毁 、 毁 坏 、 倾 覆 、 苦 害 ， 也 必 照 样 留 意 将 他 们 建 立 、 栽 植 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19721', '24', '31', '29', '当 那 些 日 子 ， 人 不 再 说 ： 父 亲 吃 了 酸 葡 萄 ， 儿 子 的 牙 酸 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19722', '24', '31', '30', '但 各 人 必 因 自 己 的 罪 死 亡 ； 凡 吃 酸 葡 萄 的 ， 自 己 的 牙 必 酸 倒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19723', '24', '31', '31', '耶 和 华 说 ： “ 日 子 将 到 ， 我 要 与 以 色 列 家 和 犹 大 家 另 立 新 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19724', '24', '31', '32', '不 像 我 拉 着 他 们 祖 宗 的 手 ， 领 他 们 出 埃 及 地 的 时 候 ， 与 他 们 所 立 的 约 。 我 虽 作 他 们 的 丈 夫 ， 他 们 却 背 了 我 的 约 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19725', '24', '31', '33', '耶 和 华 说 ： “ 那 些 日 子 以 后 ， 我 与 以 色 列 家 所 立 的 约 乃 是 这 样 ： 我 要 将 我 的 律 法 放 在 他 们 里 面 ， 写 在 他 们 心 上 。 我 要 作 他 们 的 神 ， 他 们 要 作 我 的 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19726', '24', '31', '34', '他 们 各 人 不 再 教 导 自 己 的 邻 舍 和 自 己 的 弟 兄 说 ： ‘ 你 该 认 识 耶 和 华 ’ ， 因 为 他 们 从 最 小 的 到 至 大 的 都 必 认 识 我 。 我 要 赦 免 他 们 的 罪 孽 ， 不 再 记 念 他 们 的 罪 恶 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19727', '24', '31', '35', '那 使 太 阳 白 日 发 光 ， 使 星 月 有 定 例 ， 黑 夜 发 亮 ， 又 搅 动 大 海 ， 使 海 中 波 浪 匉 訇 的 ， 万 军 之 耶 和 华 是 他 的 名 。 他 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19728', '24', '31', '36', '这 些 定 例 若 能 在 我 面 前 废 掉 ， 以 色 列 的 后 裔 也 就 在 我 面 前 断 绝 ， 永 远 不 再 成 国 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19729', '24', '31', '37', '耶 和 华 如 此 说 ： 若 能 量 度 上 天 ， 寻 察 下 地 的 根 基 ， 我 就 因 以 色 列 后 裔 一 切 所 行 的 弃 绝 他 们 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19730', '24', '31', '38', '耶 和 华 说 ： “ 日 子 将 到 ， 这 城 必 为 耶 和 华 建 造 ， 从 哈 楠 业 楼 直 到 角 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19731', '24', '31', '39', '准 绳 要 往 外 量 出 ， 直 到 迦 立 山 ， 又 转 到 歌 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19732', '24', '31', '40', '抛 尸 的 全 谷 和 倒 灰 之 处 ， 并 一 切 田 地 ， 直 到 汲 沦 溪 ， 又 直 到 东 方 马 门 的 拐 角 ， 都 要 归 耶 和 华 为 圣 ， 不 再 拔 出 ， 不 再 倾 覆 ， 直 到 永 远 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19733', '24', '32', '1', '＜ 耶 利 米 购 置 田 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19734', '24', '32', '2', '那 时 巴 比 伦 王 的 军 队 围 困 耶 路 撒 冷 ， 先 知 耶 利 米 囚 在 护 卫 兵 的 院 内 ， 在 犹 大 王 的 宫 中 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19735', '24', '32', '3', '因 为 犹 大 王 西 底 家 已 将 他 囚 禁 ， 说 ： “ 你 为 什 么 预 言 说 ， 耶 和 华 如 此 说 ： ‘ 我 必 将 这 城 交 在 巴 比 伦 王 的 手 中 ， 他 必 攻 取 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19736', '24', '32', '4', '犹 大 王 西 底 家 必 不 能 逃 脱 迦 勒 底 人 的 手 ， 定 要 交 在 巴 比 伦 王 的 手 中 ， 要 口 对 口 彼 此 说 话 ， 眼 对 眼 彼 此 相 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19737', '24', '32', '5', '巴 比 伦 王 必 将 西 底 家 带 到 巴 比 伦 ； 西 底 家 必 住 在 那 里 ， 直 到 我 眷 顾 他 的 时 候 。 你 们 虽 与 迦 勒 底 人 争 战 ， 却 不 顺 利 。 这 是 耶 和 华 说 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19738', '24', '32', '6', '耶 利 米 说 ： “ 耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19739', '24', '32', '7', '‘ 你 叔 叔 沙 龙 的 儿 子 哈 拿 篾 必 来 见 你 ， 说 ： 我 在 亚 拿 突 的 那 块 地 ， 求 你 买 来 ； 因 你 买 这 地 是 合 乎 赎 回 之 理 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19740', '24', '32', '8', '我 叔 叔 的 儿 子 哈 拿 篾 果 然 照 耶 和 华 的 话 来 到 护 卫 兵 的 院 内 ， 对 我 说 ： “ 我 在 便 雅 悯 境 内 、 亚 拿 突 的 那 块 地 ， 求 你 买 来 ； 因 你 买 来 是 合 乎 承 受 之 理 ， 是 你 当 赎 的 。 你 为 自 己 买 来 吧 ！ ” 我 ─ ─ 耶 利 米 就 知 道 这 是 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19741', '24', '32', '9', '我 便 向 我 叔 叔 的 儿 子 哈 拿 篾 买 了 亚 拿 突 的 那 块 地 ， 平 了 十 七 舍 客 勒 银 子 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19742', '24', '32', '10', '我 在 契 上 画 押 ， 将 契 封 缄 ， 又 请 见 证 人 来 ， 并 用 天 平 将 银 子 平 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19743', '24', '32', '11', '我 便 将 照 例 按 规 所 立 的 买 契 ， 就 是 封 缄 的 那 一 张 和 敞 着 的 那 一 张 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19744', '24', '32', '12', '当 着 我 叔 叔 的 儿 子 哈 拿 篾 和 画 押 作 见 证 的 人 ， 并 坐 在 护 卫 兵 院 内 的 一 切 犹 大 人 眼 前 ， 交 给 玛 西 雅 的 孙 子 尼 利 亚 的 儿 子 巴 录 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19745', '24', '32', '13', '当 着 他 们 众 人 眼 前 ， 我 嘱 咐 巴 录 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19746', '24', '32', '14', '“ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 要 将 这 封 缄 的 和 敞 着 的 两 张 契 放 在 瓦 器 里 ， 可 以 存 留 多 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19747', '24', '32', '15', '因 为 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 将 来 在 这 地 必 有 人 再 买 房 屋 、 田 地 ， 和 葡 萄 园 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19748', '24', '32', '16', '＜ 耶 利 米 的 祈 祷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19749', '24', '32', '17', '“ 主 耶 和 华 啊 ， 你 曾 用 大 能 和 伸 出 来 的 膀 臂 创 造 天 地 ， 在 你 没 有 难 成 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19750', '24', '32', '18', '你 施 慈 爱 与 千 万 人 ， 又 将 父 亲 的 罪 孽 报 应 在 他 后 世 子 孙 的 怀 中 ， 是 至 大 全 能 的 神 ， 万 军 之 耶 和 华 是 你 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19751', '24', '32', '19', '谋 事 有 大 略 ， 行 事 有 大 能 ， 注 目 观 看 世 人 一 切 的 举 动 ， 为 要 照 各 人 所 行 的 和 他 做 事 的 结 果 报 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19752', '24', '32', '20', '在 埃 及 地 显 神 迹 奇 事 ， 直 到 今 日 在 以 色 列 和 别 人 中 间 也 是 如 此 ， 使 自 己 得 了 名 声 ， 正 如 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19753', '24', '32', '21', '用 神 迹 奇 事 和 大 能 的 手 ， 并 伸 出 来 的 膀 臂 与 大 可 畏 的 事 ， 领 你 的 百 姓 以 色 列 出 了 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19754', '24', '32', '22', '将 这 地 赐 给 他 们 ， 就 是 你 向 他 们 列 祖 起 誓 应 许 赐 给 他 们 流 奶 与 蜜 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19755', '24', '32', '23', '他 们 进 入 这 地 得 了 为 业 ， 却 不 听 从 你 的 话 ， 也 不 遵 行 你 的 律 法 ； 你 一 切 所 吩 咐 他 们 行 的 ， 他 们 一 无 所 行 ， 因 此 你 使 这 一 切 的 灾 祸 临 到 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19756', '24', '32', '24', '看 哪 ， 敌 人 已 经 来 到 ， 筑 垒 要 攻 取 这 城 ； 城 也 因 刀 剑 、 饥 荒 、 瘟 疫 交 在 攻 城 的 迦 勒 底 人 手 中 。 你 所 说 的 话 都 成 就 了 ， 你 也 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19757', '24', '32', '25', '主 耶 和 华 啊 ， 你 对 我 说 ： 要 用 银 子 为 自 己 买 那 块 地 ， 又 请 见 证 人 。 其 实 这 城 已 交 在 迦 勒 底 人 的 手 中 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19758', '24', '32', '26', '耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19759', '24', '32', '27', '“ 我 是 耶 和 华 ， 是 凡 有 血 气 者 的 神 ， 岂 有 我 难 成 的 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19760', '24', '32', '28', '耶 和 华 如 此 说 ： 我 必 将 这 城 交 付 迦 勒 底 人 的 手 和 巴 比 伦 王 尼 布 甲 尼 撒 的 手 ， 他 必 攻 取 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19761', '24', '32', '29', '攻 城 的 迦 勒 底 人 必 来 放 火 焚 烧 这 城 和 其 中 的 房 屋 。 在 这 房 屋 上 ， 人 曾 向 巴 力 烧 香 ， 向 别 神 浇 奠 ， 惹 我 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19762', '24', '32', '30', '以 色 列 人 和 犹 大 人 自 从 幼 年 以 来 ， 专 行 我 眼 中 看 为 恶 的 事 ； 以 色 列 人 尽 以 手 所 做 的 惹 我 发 怒 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19763', '24', '32', '31', '这 城 自 从 建 造 的 那 日 直 到 今 日 ， 常 惹 我 的 怒 气 和 忿 怒 ， 使 我 将 这 城 从 我 面 前 除 掉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19764', '24', '32', '32', '是 因 以 色 列 人 和 犹 大 人 一 切 的 邪 恶 ， 就 是 他 们 和 他 们 的 君 王 、 首 领 、 祭 司 、 先 知 ， 并 犹 大 的 众 人 ， 以 及 耶 路 撒 冷 的 居 民 所 行 的 ， 惹 我 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19765', '24', '32', '33', '他 们 以 背 向 我 ， 不 以 面 向 我 ； 我 虽 从 早 起 来 教 训 他 们 ， 他 们 却 不 听 从 ， 不 受 教 训 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19766', '24', '32', '34', '竟 把 可 憎 之 物 设 立 在 称 为 我 名 下 的 殿 中 ， 污 秽 了 这 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19767', '24', '32', '35', '他 们 在 欣 嫩 子 谷 建 筑 巴 力 的 邱 坛 ， 好 使 自 己 的 儿 女 经 火 归 摩 洛 ； 他 们 行 这 可 憎 的 事 ， 使 犹 大 陷 在 罪 里 ， 这 并 不 是 我 所 吩 咐 的 ， 也 不 是 我 心 所 起 的 意 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19768', '24', '32', '36', '＜ 复 国 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19769', '24', '32', '37', '“ 我 在 怒 气 、 忿 怒 ， 和 大 恼 恨 中 ， 将 以 色 列 人 赶 到 各 国 。 日 后 我 必 从 那 里 将 他 们 招 聚 出 来 ， 领 他 们 回 到 此 地 ， 使 他 们 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19770', '24', '32', '38', '他 们 要 作 我 的 子 民 ， 我 要 作 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19771', '24', '32', '39', '我 要 使 他 们 彼 此 同 心 同 道 ， 好 叫 他 们 永 远 敬 畏 我 ， 使 他 们 和 他 们 后 世 的 子 孙 得 福 乐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19772', '24', '32', '40', '又 要 与 他 们 立 永 远 的 约 ， 必 随 着 他 们 施 恩 ， 并 不 离 开 他 们 ， 且 使 他 们 有 敬 畏 我 的 心 ， 不 离 开 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19773', '24', '32', '41', '我 必 欢 喜 施 恩 与 他 们 ， 要 尽 心 尽 意 、 诚 诚 实 实 将 他 们 栽 于 此 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19774', '24', '32', '42', '“ 因 为 耶 和 华 如 此 说 ： 我 怎 样 使 这 一 切 大 祸 临 到 这 百 姓 ， 我 也 要 照 样 使 我 所 应 许 他 们 的 一 切 福 乐 都 临 到 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19775', '24', '32', '43', '你 们 说 ， 这 地 是 荒 凉 、 无 人 民 、 无 牲 畜 ， 是 交 付 迦 勒 底 人 手 之 地 。 日 后 在 这 境 内 ， 必 有 人 置 买 田 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19776', '24', '32', '44', '在 便 雅 悯 地 、 耶 路 撒 冷 四 围 的 各 处 、 犹 大 的 城 邑 、 山 地 的 城 邑 、 高 原 的 城 邑 ， 并 南 地 的 城 邑 ， 人 必 用 银 子 买 田 地 ， 在 契 上 画 押 ， 将 契 封 缄 ， 请 出 见 证 人 ， 因 为 我 必 使 被 掳 的 人 归 回 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19777', '24', '33', '1', '＜ 重 申 复 国 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19778', '24', '33', '2', '“ 成 就 的 是 耶 和 华 ， 造 作 、 为 要 建 立 的 也 是 耶 和 华 ； 耶 和 华 是 他 的 名 。 他 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19779', '24', '33', '3', '你 求 告 我 ， 我 就 应 允 你 ， 并 将 你 所 不 知 道 、 又 大 又 难 的 事 指 示 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19780', '24', '33', '4', '论 到 这 城 中 的 房 屋 和 犹 大 王 的 宫 室 ， 就 是 拆 毁 为 挡 敌 人 高 垒 和 刀 剑 的 ， 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19781', '24', '33', '5', '人 要 与 迦 勒 底 人 争 战 ， 正 是 拿 死 尸 充 满 这 房 屋 ， 就 是 我 在 怒 气 和 忿 怒 中 所 杀 的 人 ， 因 他 们 的 一 切 恶 ， 我 就 掩 面 不 顾 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19782', '24', '33', '6', '看 哪 ， 我 要 使 这 城 得 以 痊 愈 安 舒 ， 使 城 中 的 人 得 医 治 ， 又 将 丰 盛 的 平 安 和 诚 实 显 明 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19783', '24', '33', '7', '我 也 要 使 犹 大 被 掳 的 和 以 色 列 被 掳 的 归 回 ， 并 建 立 他 们 和 起 初 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19784', '24', '33', '8', '我 要 除 净 他 们 的 一 切 罪 ， 就 是 向 我 所 犯 的 罪 ； 又 要 赦 免 他 们 的 一 切 罪 ， 就 是 干 犯 我 、 违 背 我 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19785', '24', '33', '9', '这 城 要 在 地 上 万 国 人 面 前 使 我 得 颂 赞 ， 得 荣 耀 ， 名 为 可 喜 可 乐 之 城 。 万 国 人 因 听 见 我 向 这 城 所 赐 的 福 乐 、 所 施 的 恩 惠 平 安 ， 就 惧 怕 战 兢 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19786', '24', '33', '10', '耶 和 华 如 此 说 ： “ 你 们 论 这 地 方 ， 说 是 荒 废 无 人 民 无 牲 畜 之 地 ， 但 在 这 荒 凉 无 人 民 无 牲 畜 的 犹 大 城 邑 和 耶 路 撒 冷 的 街 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19787', '24', '33', '11', '必 再 听 见 有 欢 喜 和 快 乐 的 声 音 、 新 郎 和 新 妇 的 声 音 ， 并 听 见 有 人 说 ： 要 称 谢 万 军 之 耶 和 华 ， 因 耶 和 华 本 为 善 ； 他 的 慈 爱 永 远 长 存 ！ 又 有 奉 感 谢 祭 到 耶 和 华 殿 中 之 人 的 声 音 ； 因 为 我 必 使 这 地 被 掳 的 人 归 回 ， 和 起 初 一 样 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19788', '24', '33', '12', '万 军 之 耶 和 华 如 此 说 ： “ 在 这 荒 废 无 人 民 无 牲 畜 之 地 ， 并 其 中 所 有 的 城 邑 ， 必 再 有 牧 人 的 住 处 ； 他 们 要 使 羊 群 躺 卧 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19789', '24', '33', '13', '在 山 地 的 城 邑 、 高 原 的 城 邑 、 南 地 的 城 邑 、 便 雅 悯 地 、 耶 路 撒 冷 四 围 的 各 处 ， 和 犹 大 的 城 邑 必 再 有 羊 群 从 数 点 的 人 手 下 经 过 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19790', '24', '33', '14', '耶 和 华 说 ： “ 日 子 将 到 ， 我 应 许 以 色 列 家 和 犹 大 家 的 恩 言 必 然 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19791', '24', '33', '15', '当 那 日 子 ， 那 时 候 ， 我 必 使 大 卫 公 义 的 苗 裔 长 起 来 ； 他 必 在 地 上 施 行 公 平 和 公 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19792', '24', '33', '16', '在 那 日 子 犹 大 必 得 救 ， 耶 路 撒 冷 必 安 然 居 住 ， 他 的 名 必 称 为 ‘ 耶 和 华 ─ ─ 我 们 的 义 ’ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19793', '24', '33', '17', '“ 因 为 耶 和 华 如 此 说 ： 大 卫 必 永 不 断 人 坐 在 以 色 列 家 的 宝 座 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19794', '24', '33', '18', '祭 司 、 利 未 人 在 我 面 前 也 不 断 人 献 燔 祭 、 烧 素 祭 ， 时 常 办 理 献 祭 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19795', '24', '33', '19', '耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19796', '24', '33', '20', '“ 耶 和 华 如 此 说 ： 你 们 若 能 废 弃 我 所 立 白 日 黑 夜 的 约 ， 使 白 日 黑 夜 不 按 时 轮 转 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19797', '24', '33', '21', '就 能 废 弃 我 与 我 仆 人 大 卫 所 立 的 约 ， 使 他 没 有 儿 子 在 他 的 宝 座 上 为 王 ， 并 能 废 弃 我 与 事 奉 我 的 祭 司 、 利 未 人 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19798', '24', '33', '22', '天 上 的 万 象 不 能 数 算 ， 海 边 的 尘 沙 也 不 能 斗 量 ； 我 必 照 样 使 我 仆 人 大 卫 的 后 裔 和 事 奉 我 的 利 未 人 多 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19799', '24', '33', '23', '耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19800', '24', '33', '24', '“ 你 没 有 揣 摩 这 百 姓 的 话 吗 ？ 他 们 说 ： ‘ 耶 和 华 所 拣 选 的 二 族 ， 他 已 经 弃 绝 了 。 ’ 他 们 这 样 藐 视 我 的 百 姓 ， 以 为 不 再 成 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19801', '24', '33', '25', '耶 和 华 如 此 说 ： 若 是 我 立 白 日 黑 夜 的 约 不 能 存 住 ， 若 是 我 未 曾 安 排 天 地 的 定 例 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19802', '24', '33', '26', '我 就 弃 绝 雅 各 的 后 裔 和 我 仆 人 大 卫 的 后 裔 ， 不 使 大 卫 的 后 裔 治 理 亚 伯 拉 罕 、 以 撒 、 雅 各 的 后 裔 ； 因 为 我 必 使 他 们 被 掳 的 人 归 回 ， 也 必 怜 悯 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19803', '24', '34', '1', '＜ 给 西 底 家 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19804', '24', '34', '2', '“ 耶 和 华 ─ ─ 以 色 列 的 神 说 ， 你 去 告 诉 犹 大 王 西 底 家 ， 耶 和 华 如 此 说 ： 我 要 将 这 城 交 付 巴 比 伦 王 的 手 ， 他 必 用 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19805', '24', '34', '3', '你 必 不 能 逃 脱 他 的 手 ， 定 被 拿 住 ， 交 在 他 的 手 中 。 你 的 眼 要 见 巴 比 伦 王 的 眼 ， 他 要 口 对 口 和 你 说 话 ， 你 也 必 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19806', '24', '34', '4', '犹 大 王 西 底 家 啊 ， 你 还 要 听 耶 和 华 的 话 。 耶 和 华 论 到 你 如 此 说 ： 你 必 不 被 刀 剑 杀 死 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19807', '24', '34', '5', '你 必 平 安 而 死 ， 人 必 为 你 焚 烧 物 件 ， 好 像 为 你 列 祖 ， 就 是 在 你 以 前 的 先 王 焚 烧 一 般 。 人 必 为 你 举 哀 说 ： ‘ 哀 哉 ！ 我 主 啊 。 ’ 耶 和 华 说 ： 这 话 是 我 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19808', '24', '34', '6', '于 是 ， 先 知 耶 利 米 在 耶 路 撒 冷 将 这 一 切 话 告 诉 犹 大 王 西 底 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19809', '24', '34', '7', '那 时 ， 巴 比 伦 王 的 军 队 正 攻 打 耶 路 撒 冷 ， 又 攻 打 犹 大 所 剩 下 的 城 邑 ， 就 是 拉 吉 和 亚 西 加 。 原 来 犹 大 的 坚 固 城 只 剩 下 这 两 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19810', '24', '34', '8', '＜ 释 放 奴 隶 的 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19811', '24', '34', '9', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19812', '24', '34', '10', '所 有 立 约 的 首 领 和 众 民 就 任 他 的 仆 人 婢 女 自 由 出 去 ， 谁 也 不 再 叫 他 们 作 奴 仆 。 大 家 都 顺 从 ， 将 他 们 释 放 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19813', '24', '34', '11', '后 来 却 又 反 悔 ， 叫 所 任 去 自 由 的 仆 人 婢 女 回 来 ， 勉 强 他 们 仍 为 仆 婢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19814', '24', '34', '12', '因 此 耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19815', '24', '34', '13', '“ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 将 你 们 的 列 祖 从 埃 及 地 为 奴 之 家 领 出 来 的 时 候 ， 与 他 们 立 约 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19816', '24', '34', '14', '‘ 你 的 一 个 希 伯 来 弟 兄 若 卖 给 你 ， 服 事 你 六 年 ， 到 第 七 年 你 们 各 人 就 要 任 他 自 由 出 去 。 ’ 只 是 你 们 列 祖 不 听 从 我 ， 也 不 侧 耳 而 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19817', '24', '34', '15', '如 今 你 们 回 转 ， 行 我 眼 中 看 为 正 的 事 ， 各 人 向 邻 舍 宣 告 自 由 ， 并 且 在 称 为 我 名 下 的 殿 中 、 在 我 面 前 立 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19818', '24', '34', '16', '你 们 却 又 反 悔 ， 亵 渎 我 的 名 ， 各 人 叫 所 任 去 随 意 自 由 的 仆 人 婢 女 回 来 ， 勉 强 他 们 仍 为 仆 婢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19819', '24', '34', '17', '所 以 耶 和 华 如 此 说 ： 你 们 没 有 听 从 我 ， 各 人 向 弟 兄 邻 舍 宣 告 自 由 。 看 哪 ！ 我 向 你 们 宣 告 一 样 自 由 ， 就 是 使 你 们 自 由 于 刀 剑 、 饥 荒 、 瘟 疫 之 下 ， 并 且 使 你 们 在 天 下 万 国 中 抛 来 抛 去 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19820', '24', '34', '18', '犹 大 的 首 领 、 耶 路 撒 冷 的 首 领 、 太 监 、 祭 司 ， 和 国 中 的 众 民 曾 将 牛 犊 劈 开 ， 分 成 两 半 ， 从 其 中 经 过 ， 在 我 面 前 立 约 。 后 来 又 违 背 我 的 约 ， 不 遵 行 这 约 上 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19821', '24', '34', '19', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19822', '24', '34', '20', '我 必 将 他 们 交 在 仇 敌 和 寻 索 其 命 的 人 手 中 ； 他 们 的 尸 首 必 给 空 中 的 飞 鸟 和 地 上 的 野 兽 作 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19823', '24', '34', '21', '并 且 我 必 将 犹 大 王 西 底 家 和 他 的 首 领 交 在 他 们 仇 敌 和 寻 索 其 命 的 人 ， 与 那 暂 离 你 们 而 去 巴 比 伦 王 军 队 的 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19824', '24', '34', '22', '耶 和 华 说 ： 我 必 吩 咐 他 们 回 到 这 城 ， 攻 打 这 城 ， 将 城 攻 取 ， 用 火 焚 烧 。 我 也 要 使 犹 大 的 城 邑 变 为 荒 场 ， 无 人 居 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19825', '24', '35', '1', '＜ 耶 利 米 和 利 甲 族 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19826', '24', '35', '2', '“ 你 去 见 利 甲 族 的 人 ， 和 他 们 说 话 ， 领 他 们 进 入 耶 和 华 殿 的 一 间 屋 子 ， 给 他 们 酒 喝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19827', '24', '35', '3', '我 就 将 哈 巴 洗 尼 雅 的 孙 子 雅 利 米 雅 的 儿 子 雅 撒 尼 亚 和 他 弟 兄 ， 并 他 众 子 ， 以 及 利 甲 全 族 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19828', '24', '35', '4', '领 到 耶 和 华 的 殿 ， 进 入 神 人 伊 基 大 利 的 儿 子 哈 难 众 子 的 屋 子 。 那 屋 子 在 首 领 的 屋 子 旁 边 ， 在 沙 龙 之 子 把 门 的 玛 西 雅 屋 子 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19829', '24', '35', '5', '于 是 我 在 利 甲 族 人 面 前 设 摆 盛 满 酒 的 碗 和 杯 ， 对 他 们 说 ： “ 请 你 们 喝 酒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19830', '24', '35', '6', '他 们 却 说 ： “ 我 们 不 喝 酒 ； 因 为 我 们 先 祖 利 甲 的 儿 子 约 拿 达 曾 吩 咐 我 们 说 ： ‘ 你 们 与 你 们 的 子 孙 永 不 可 喝 酒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19831', '24', '35', '7', '也 不 可 盖 房 、 撒 种 、 栽 种 葡 萄 园 ， 但 一 生 的 年 日 要 住 帐 棚 ， 使 你 们 的 日 子 在 寄 居 之 地 得 以 延 长 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19832', '24', '35', '8', '凡 我 们 先 祖 利 甲 的 儿 子 约 拿 达 所 吩 咐 我 们 的 话 ， 我 们 都 听 从 了 。 我 们 和 我 们 的 妻 子 儿 女 一 生 的 年 日 都 不 喝 酒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19833', '24', '35', '9', '也 不 盖 房 居 住 ， 也 没 有 葡 萄 园 、 田 地 ， 和 种 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19834', '24', '35', '10', '但 住 帐 棚 ， 听 从 我 们 先 祖 约 拿 达 的 话 ， 照 他 所 吩 咐 我 们 的 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19835', '24', '35', '11', '巴 比 伦 王 尼 布 甲 尼 撒 上 此 地 来 ， 我 们 因 怕 迦 勒 底 的 军 队 和 亚 兰 的 军 队 ， 就 说 ： ‘ 来 吧 ， 我 们 到 耶 路 撒 冷 去 。 ’ 这 样 ， 我 们 才 住 在 耶 路 撒 冷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19836', '24', '35', '12', '耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19837', '24', '35', '13', '“ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 去 对 犹 大 人 和 耶 路 撒 冷 的 居 民 说 ， 耶 和 华 说 ： 你 们 不 受 教 训 ， 不 听 从 我 的 话 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19838', '24', '35', '14', '利 甲 的 儿 子 约 拿 达 所 吩 咐 他 子 孙 不 可 喝 酒 的 话 ， 他 们 已 经 遵 守 ， 直 到 今 日 也 不 喝 酒 ， 因 为 他 们 听 从 先 祖 的 吩 咐 。 我 从 早 起 来 警 戒 你 们 ， 你 们 却 不 听 从 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19839', '24', '35', '15', '我 从 早 起 来 ， 差 遣 我 的 仆 人 众 先 知 去 ， 说 ： ‘ 你 们 各 人 当 回 头 ， 离 开 恶 道 ， 改 正 行 为 ， 不 随 从 事 奉 别 神 ， 就 必 住 在 我 所 赐 给 你 们 和 你 们 列 祖 的 地 上 。 ’ 只 是 你 们 没 有 听 从 我 ， 也 没 有 侧 耳 而 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19840', '24', '35', '16', '利 甲 的 儿 子 约 拿 达 的 子 孙 能 遵 守 先 人 所 吩 咐 他 们 的 命 ， 这 百 姓 却 没 有 听 从 我 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19841', '24', '35', '17', '因 此 ， 耶 和 华 ─ ─ 万 军 之 神 、 以 色 列 的 神 如 此 说 ： 我 要 使 我 所 说 的 一 切 灾 祸 临 到 犹 大 人 和 耶 路 撒 冷 的 一 切 居 民 。 因 为 我 对 他 们 说 话 ， 他 们 没 有 听 从 ； 我 呼 唤 他 们 ， 他 们 没 有 答 应 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19842', '24', '35', '18', '耶 利 米 对 利 甲 族 的 人 说 ： “ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 因 你 们 听 从 你 们 先 祖 约 拿 达 的 吩 咐 ， 谨 守 他 的 一 切 诫 命 ， 照 他 所 吩 咐 你 们 的 去 行 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19843', '24', '35', '19', '所 以 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 利 甲 的 儿 子 约 拿 达 必 永 不 缺 人 侍 立 在 我 面 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19844', '24', '36', '1', '＜ 巴 录 在 圣 殿 里 宣 读 书 卷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19845', '24', '36', '2', '“ 你 取 一 书 卷 ， 将 我 对 你 说 攻 击 以 色 列 和 犹 大 ， 并 各 国 的 一 切 话 ， 从 我 对 你 说 话 的 那 日 ， 就 是 从 约 西 亚 的 日 子 起 直 到 今 日 ， 都 写 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19846', '24', '36', '3', '或 者 犹 大 家 听 见 我 想 要 降 与 他 们 的 一 切 灾 祸 ， 各 人 就 回 头 ， 离 开 恶 道 ， 我 好 赦 免 他 们 的 罪 孽 和 罪 恶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19847', '24', '36', '4', '所 以 ， 耶 利 米 召 了 尼 利 亚 的 儿 子 巴 录 来 ； 巴 录 就 从 耶 利 米 口 中 ， 将 耶 和 华 对 耶 利 米 所 说 的 一 切 话 写 在 书 卷 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19848', '24', '36', '5', '耶 利 米 吩 咐 巴 录 说 ： “ 我 被 拘 管 ， 不 能 进 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19849', '24', '36', '6', '所 以 你 要 去 趁 禁 食 的 日 子 ， 在 耶 和 华 殿 中 将 耶 和 华 的 话 ， 就 是 你 从 我 口 中 所 写 在 书 卷 上 的 话 ， 念 给 百 姓 和 一 切 从 犹 大 城 邑 出 来 的 人 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19850', '24', '36', '7', '或 者 他 们 在 耶 和 华 面 前 恳 求 各 人 回 头 ， 离 开 恶 道 ， 因 为 耶 和 华 向 这 百 姓 所 说 要 发 的 怒 气 和 忿 怒 是 大 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19851', '24', '36', '8', '尼 利 亚 的 儿 子 巴 录 就 照 先 知 耶 利 米 一 切 所 吩 咐 的 去 行 ， 在 耶 和 华 的 殿 中 从 书 上 念 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19852', '24', '36', '9', '犹 大 王 约 西 亚 的 儿 子 约 雅 敬 第 五 年 九 月 ， 耶 路 撒 冷 的 众 民 和 那 从 犹 大 城 邑 来 到 耶 路 撒 冷 的 众 民 ， 在 耶 和 华 面 前 宣 告 禁 食 的 日 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19853', '24', '36', '10', '巴 录 就 在 耶 和 华 殿 的 上 院 ， 耶 和 华 殿 的 新 门 口 ， 沙 番 的 儿 子 文 士 基 玛 利 雅 的 屋 内 ， 念 书 上 耶 利 米 的 话 给 众 民 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19854', '24', '36', '11', '＜ 向 官 员 宣 读 书 卷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19855', '24', '36', '12', '他 就 下 到 王 宫 ， 进 入 文 士 的 屋 子 。 众 首 领 ， 就 是 文 士 以 利 沙 玛 、 示 玛 雅 的 儿 子 第 莱 雅 、 亚 革 波 的 儿 子 以 利 拿 单 、 沙 番 的 儿 子 基 玛 利 雅 、 哈 拿 尼 雅 的 儿 子 西 底 家 ， 和 其 余 的 首 领 都 坐 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19856', '24', '36', '13', '于 是 米 该 亚 对 他 们 述 说 他 所 听 见 的 一 切 话 ， 就 是 巴 录 向 百 姓 念 那 书 的 时 候 所 听 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19857', '24', '36', '14', '众 首 领 就 打 发 古 示 的 曾 孙 、 示 利 米 雅 的 孙 子 、 尼 探 雅 的 儿 子 犹 底 到 巴 录 那 里 ， 对 他 说 ： “ 你 将 所 念 给 百 姓 听 的 书 卷 拿 在 手 中 到 我 们 这 里 来 。 ” 尼 利 亚 的 儿 子 巴 录 就 手 拿 书 卷 来 到 他 们 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19858', '24', '36', '15', '他 们 对 他 说 ： “ 请 你 坐 下 ， 念 给 我 们 听 。 ” 巴 录 就 念 给 他 们 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19859', '24', '36', '16', '他 们 听 见 这 一 切 话 就 害 怕 ， 面 面 相 观 ， 对 巴 录 说 ： “ 我 们 必 须 将 这 一 切 话 告 诉 王 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19860', '24', '36', '17', '他 们 问 巴 录 说 ： “ 请 你 告 诉 我 们 ， 你 怎 样 从 他 口 中 写 这 一 切 话 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19861', '24', '36', '18', '巴 录 回 答 说 ： “ 他 用 口 向 我 说 这 一 切 话 ， 我 就 用 笔 墨 写 在 书 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19862', '24', '36', '19', '众 首 领 对 巴 录 说 ： “ 你 和 耶 利 米 要 去 藏 起 来 ， 不 可 叫 人 知 道 你 们 在 哪 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19863', '24', '36', '20', '＜ 约 雅 敬 焚 烧 书 卷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19864', '24', '36', '21', '王 就 打 发 犹 底 去 拿 这 书 卷 来 ， 他 便 从 文 士 以 利 沙 玛 的 屋 内 取 来 ， 念 给 王 和 王 左 右 侍 立 的 众 首 领 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19865', '24', '36', '22', '那 时 正 是 九 月 ， 王 坐 在 过 冬 的 房 屋 里 ， 王 的 前 面 火 盆 中 有 烧 着 的 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19866', '24', '36', '23', '犹 底 念 了 三 四 篇 ｛ 或 译 ： 行 ｝ ， 王 就 用 文 士 的 刀 将 书 卷 割 破 ， 扔 在 火 盆 中 ， 直 到 全 卷 在 火 中 烧 尽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19867', '24', '36', '24', '王 和 听 见 这 一 切 话 的 臣 仆 都 不 惧 怕 ， 也 不 撕 裂 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19868', '24', '36', '25', '以 利 拿 单 和 第 莱 雅 ， 并 基 玛 利 雅 恳 求 王 不 要 烧 这 书 卷 ， 他 却 不 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19869', '24', '36', '26', '王 就 吩 咐 哈 米 勒 的 儿 子 ｛ 或 译 ： 王 的 儿 子 ｝ 耶 拉 篾 和 亚 斯 列 的 儿 子 西 莱 雅 ， 并 亚 伯 叠 的 儿 子 示 利 米 雅 ， 去 捉 拿 文 士 巴 录 和 先 知 耶 利 米 。 耶 和 华 却 将 他 们 隐 藏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19870', '24', '36', '27', '＜ 耶 利 米 另 写 一 书 卷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19871', '24', '36', '28', '“ 你 再 取 一 卷 ， 将 犹 大 王 约 雅 敬 所 烧 第 一 卷 上 的 一 切 话 写 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19872', '24', '36', '29', '论 到 犹 大 王 约 雅 敬 你 要 说 ， 耶 和 华 如 此 说 ： 你 烧 了 书 卷 ， 说 ： ‘ 你 为 什 么 在 其 上 写 着 ， 说 巴 比 伦 王 必 要 来 毁 灭 这 地 ， 使 这 地 上 绝 了 人 民 牲 畜 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19873', '24', '36', '30', '所 以 耶 和 华 论 到 犹 大 王 约 雅 敬 说 ： 他 后 裔 中 必 没 有 人 坐 在 大 卫 的 宝 座 上 ； 他 的 尸 首 必 被 抛 弃 ， 白 日 受 炎 热 ， 黑 夜 受 寒 霜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19874', '24', '36', '31', '我 必 因 他 和 他 后 裔 ， 并 他 臣 仆 的 罪 孽 刑 罚 他 们 。 我 要 使 我 所 说 的 一 切 灾 祸 临 到 他 们 和 耶 路 撒 冷 的 居 民 ， 并 犹 大 人 ； 只 是 他 们 不 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19875', '24', '36', '32', '于 是 ， 耶 利 米 又 取 一 书 卷 交 给 尼 利 亚 的 儿 子 文 士 巴 录 ， 他 就 从 耶 利 米 的 口 中 写 了 犹 大 王 约 雅 敬 所 烧 前 卷 上 的 一 切 话 ， 另 外 又 添 了 许 多 相 仿 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19876', '24', '37', '1', '＜ 西 底 家 求 耶 利 米 代 祷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19877', '24', '37', '2', '但 西 底 家 和 他 的 臣 仆 ， 并 国 中 的 百 姓 ， 都 不 听 从 耶 和 华 藉 先 知 耶 利 米 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19878', '24', '37', '3', '西 底 家 王 打 发 示 利 米 雅 的 儿 子 犹 甲 和 祭 司 玛 西 雅 的 儿 子 西 番 雅 去 见 先 知 耶 利 米 ， 说 ： “ 求 你 为 我 们 祷 告 耶 和 华 ─ ─ 我 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19879', '24', '37', '4', '那 时 耶 利 米 在 民 中 出 入 ， 因 为 他 们 还 没 有 把 他 囚 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19880', '24', '37', '5', '法 老 的 军 队 已 经 从 埃 及 出 来 ， 那 围 困 耶 路 撒 冷 的 迦 勒 底 人 听 见 他 们 的 风 声 ， 就 拔 营 离 开 耶 路 撒 冷 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19881', '24', '37', '6', '耶 和 华 的 话 临 到 先 知 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19882', '24', '37', '7', '“ 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 犹 大 王 打 发 你 们 来 求 问 我 ， 你 们 要 如 此 对 他 说 ： ‘ 那 出 来 帮 助 你 们 法 老 的 军 队 必 回 埃 及 本 国 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19883', '24', '37', '8', '迦 勒 底 人 必 再 来 攻 打 这 城 ， 并 要 攻 取 ， 用 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19884', '24', '37', '9', '耶 和 华 如 此 说 ： 你 们 不 要 自 欺 说 “ 迦 勒 底 人 必 定 离 开 我 们 ” ， 因 为 他 们 必 不 离 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19885', '24', '37', '10', '你 们 即 便 杀 败 了 与 你 们 争 战 的 迦 勒 底 全 军 ， 但 剩 下 受 伤 的 人 也 必 各 人 从 帐 棚 里 起 来 ， 用 火 焚 烧 这 城 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19886', '24', '37', '11', '＜ 耶 利 米 被 捕 入 狱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19887', '24', '37', '12', '耶 利 米 就 杂 在 民 中 出 离 耶 路 撒 冷 ， 要 往 便 雅 悯 地 去 ， 在 那 里 得 自 己 的 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19888', '24', '37', '13', '他 到 了 便 雅 悯 门 那 里 ， 有 守 门 官 名 叫 伊 利 雅 ， 是 哈 拿 尼 亚 的 孙 子 、 示 利 米 雅 的 儿 子 ， 他 就 拿 住 先 知 耶 利 米 ， 说 ： “ 你 是 投 降 迦 勒 底 人 哪 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19889', '24', '37', '14', '耶 利 米 说 ： “ 你 这 是 谎 话 ， 我 并 不 是 投 降 迦 勒 底 人 。 ” 伊 利 雅 不 听 他 的 话 ， 就 拿 住 他 ， 解 到 首 领 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19890', '24', '37', '15', '首 领 恼 怒 耶 利 米 ， 就 打 了 他 ， 将 他 囚 在 文 士 约 拿 单 的 房 屋 中 ， 因 为 他 们 以 这 房 屋 当 作 监 牢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19891', '24', '37', '16', '耶 利 米 来 到 狱 中 ， 进 入 牢 房 ， 在 那 里 囚 了 多 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19892', '24', '37', '17', '西 底 家 王 打 发 人 提 出 他 来 ， 在 自 己 的 宫 内 私 下 问 他 说 ： “ 从 耶 和 华 有 什 么 话 临 到 没 有 ？ ” 耶 利 米 说 ： “ 有 ！ ” 又 说 ： “ 你 必 交 在 巴 比 伦 王 手 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19893', '24', '37', '18', '耶 利 米 又 对 西 底 家 王 说 ： “ 我 在 什 么 事 上 得 罪 你 ， 或 你 的 臣 仆 ， 或 这 百 姓 ， 你 竟 将 我 囚 在 监 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19894', '24', '37', '19', '对 你 们 预 言 巴 比 伦 王 必 不 来 攻 击 你 们 和 这 地 的 先 知 ， 现 今 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19895', '24', '37', '20', '主 ─ ─ 我 的 王 啊 ， 求 你 现 在 垂 听 ， 准 我 在 你 面 前 的 恳 求 ： 不 要 使 我 回 到 文 士 约 拿 单 的 房 屋 中 ， 免 得 我 死 在 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19896', '24', '37', '21', '于 是 ， 西 底 家 王 下 令 ， 他 们 就 把 耶 利 米 交 在 护 卫 兵 的 院 中 ， 每 天 从 饼 铺 街 取 一 个 饼 给 他 ， 直 到 城 中 的 饼 用 尽 了 。 这 样 ， 耶 利 米 仍 在 护 卫 兵 的 院 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19897', '24', '38', '1', '＜ 耶 利 米 在 枯 井 里 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19898', '24', '38', '2', '“ 耶 和 华 如 此 说 ： 住 在 这 城 里 的 必 遭 刀 剑 、 饥 荒 、 瘟 疫 而 死 ； 但 出 去 归 降 迦 勒 底 人 的 必 得 存 活 ， 就 是 以 自 己 命 为 掠 物 的 ， 必 得 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19899', '24', '38', '3', '耶 和 华 如 此 说 ： 这 城 必 要 交 在 巴 比 伦 王 军 队 的 手 中 ， 他 必 攻 取 这 城 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19900', '24', '38', '4', '于 是 首 领 对 王 说 ： “ 求 你 将 这 人 治 死 ； 因 他 向 城 里 剩 下 的 兵 丁 和 众 民 说 这 样 的 话 ， 使 他 们 的 手 发 软 。 这 人 不 是 求 这 百 姓 得 平 安 ， 乃 是 叫 他 们 受 灾 祸 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19901', '24', '38', '5', '西 底 家 王 说 ： “ 他 在 你 们 手 中 ， 无 论 何 事 ， 王 也 不 能 与 你 们 反 对 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19902', '24', '38', '6', '他 们 就 拿 住 耶 利 米 ， 下 在 哈 米 勒 的 儿 子 ｛ 或 译 ： 王 的 儿 子 ｝ 玛 基 雅 的 牢 狱 里 ； 那 牢 狱 在 护 卫 兵 的 院 中 。 他 们 用 绳 子 将 耶 利 米 系 下 去 。 牢 狱 里 没 有 水 ， 只 有 淤 泥 ， 耶 利 米 就 陷 在 淤 泥 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19903', '24', '38', '7', '在 王 宫 的 太 监 古 实 人 以 伯 ． 米 勒 ， 听 见 他 们 将 耶 利 米 下 了 牢 狱 （ 那 时 王 坐 在 便 雅 悯 门 口 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19904', '24', '38', '8', '以 伯 ． 米 勒 就 从 王 宫 里 出 来 ， 对 王 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19905', '24', '38', '9', '“ 主 ─ ─ 我 的 王 啊 ， 这 些 人 向 先 知 耶 利 米 一 味 地 行 恶 ， 将 他 下 在 牢 狱 中 ； 他 在 那 里 必 因 饥 饿 而 死 ， 因 为 城 中 再 没 有 粮 食 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19906', '24', '38', '10', '王 就 吩 咐 古 实 人 以 伯 ． 米 勒 说 ： “ 你 从 这 里 带 领 三 十 人 ， 趁 着 先 知 耶 利 米 未 死 以 前 ， 将 他 从 牢 狱 中 提 上 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19907', '24', '38', '11', '于 是 以 伯 ． 米 勒 带 领 这 些 人 同 去 ， 进 入 王 宫 ， 到 库 房 以 下 ， 从 那 里 取 了 些 碎 布 和 破 烂 的 衣 服 ， 用 绳 子 缒 下 牢 狱 去 到 耶 利 米 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19908', '24', '38', '12', '古 实 人 以 伯 ． 米 勒 对 耶 利 米 说 ： “ 你 用 这 些 碎 布 和 破 烂 的 衣 服 放 在 绳 子 上 ， 垫 你 的 胳 肢 窝 。 ” 耶 利 米 就 照 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19909', '24', '38', '13', '这 样 ， 他 们 用 绳 子 将 耶 利 米 从 牢 狱 里 拉 上 来 。 耶 利 米 仍 在 护 卫 兵 的 院 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19910', '24', '38', '14', '＜ 西 底 家 问 计 于 耶 利 米 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19911', '24', '38', '15', '耶 利 米 对 西 底 家 说 ： “ 我 若 告 诉 你 ， 你 岂 不 定 要 杀 我 吗 ？ 我 若 劝 戒 你 ， 你 必 不 听 从 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19912', '24', '38', '16', '西 底 家 王 就 私 下 向 耶 利 米 说 ： “ 我 指 着 那 造 我 们 生 命 之 永 生 的 耶 和 华 起 誓 ： 我 必 不 杀 你 ， 也 不 将 你 交 在 寻 索 你 命 的 人 手 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19913', '24', '38', '17', '耶 利 米 对 西 底 家 说 ： “ 耶 和 华 ─ ─ 万 军 之 神 、 以 色 列 的 神 如 此 说 ： 你 若 出 去 归 降 巴 比 伦 王 的 首 领 ， 你 的 命 就 必 存 活 ， 这 城 也 不 致 被 火 焚 烧 ， 你 和 你 的 全 家 都 必 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19914', '24', '38', '18', '你 若 不 出 去 归 降 巴 比 伦 王 的 首 领 ， 这 城 必 交 在 迦 勒 底 人 手 中 。 他 们 必 用 火 焚 烧 ， 你 也 不 得 脱 离 他 们 的 手 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19915', '24', '38', '19', '西 底 家 王 对 耶 利 米 说 ： “ 我 怕 那 些 投 降 迦 勒 底 人 的 犹 大 人 ， 恐 怕 迦 勒 底 人 将 我 交 在 他 们 手 中 ， 他 们 戏 弄 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19916', '24', '38', '20', '耶 利 米 说 ： “ 迦 勒 底 人 必 不 将 你 交 出 。 求 你 听 从 我 对 你 所 说 耶 和 华 的 话 ， 这 样 你 必 得 好 处 ， 你 的 命 也 必 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19917', '24', '38', '21', '你 若 不 肯 出 去 ， 耶 和 华 指 示 我 的 话 乃 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19918', '24', '38', '22', '犹 大 王 宫 里 所 剩 的 妇 女 必 都 带 到 巴 比 伦 王 的 首 领 那 里 。 这 些 妇 女 必 说 ： 你 知 己 的 朋 友 催 逼 你 ， 胜 过 你 ； 见 你 的 脚 陷 入 淤 泥 中 ， 就 转 身 退 后 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19919', '24', '38', '23', '“ 人 必 将 你 的 后 妃 和 你 的 儿 女 带 到 迦 勒 底 人 那 里 ； 你 也 不 得 脱 离 他 们 的 手 ， 必 被 巴 比 伦 王 的 手 捉 住 ； 你 也 必 使 这 城 被 火 焚 烧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19920', '24', '38', '24', '西 底 家 对 耶 利 米 说 ： “ 不 要 使 人 知 道 这 些 话 ， 你 就 不 至 于 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19921', '24', '38', '25', '首 领 若 听 见 了 我 与 你 说 话 ， 就 来 见 你 ， 问 你 说 ： ‘ 你 对 王 说 什 么 话 不 要 向 我 们 隐 瞒 ， 我 们 就 不 杀 你 。 王 向 你 说 什 么 话 也 要 告 诉 我 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19922', '24', '38', '26', '你 就 对 他 们 说 ： ‘ 我 在 王 面 前 恳 求 不 要 叫 我 回 到 约 拿 单 的 房 屋 死 在 那 里 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19923', '24', '38', '27', '随 后 众 首 领 来 见 耶 利 米 ， 问 他 ， 他 就 照 王 所 吩 咐 的 一 切 话 回 答 他 们 。 他 们 不 再 与 他 说 话 ， 因 为 事 情 没 有 泄 漏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19924', '24', '38', '28', '于 是 耶 利 米 仍 在 护 卫 兵 的 院 中 ， 直 到 耶 路 撒 冷 被 攻 取 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19925', '24', '39', '1', '＜ 耶 路 撒 冷 陷 落 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19926', '24', '39', '2', '西 底 家 十 一 年 四 月 初 九 日 ， 城 被 攻 破 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19927', '24', '39', '3', '耶 路 撒 冷 被 攻 取 的 时 候 ， 巴 比 伦 王 的 首 领 尼 甲 ． 沙 利 薛 、 三 甲 ． 尼 波 、 撒 西 金 ─ ─ 拉 撒 力 、 尼 甲 ． 沙 利 薛 ─ ─ 拉 墨 ， 并 巴 比 伦 王 其 余 的 一 切 首 领 都 来 坐 在 中 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19928', '24', '39', '4', '犹 大 王 西 底 家 和 一 切 兵 丁 看 见 他 们 ， 就 在 夜 间 从 靠 近 王 园 两 城 中 间 的 门 出 城 逃 跑 ， 往 亚 拉 巴 逃 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19929', '24', '39', '5', '迦 勒 底 的 军 队 追 赶 他 们 ， 在 耶 利 哥 的 平 原 追 上 西 底 家 ， 将 他 拿 住 ， 带 到 哈 马 地 的 利 比 拉 、 巴 比 伦 王 尼 布 甲 尼 撒 那 里 ； 尼 布 甲 尼 撒 就 审 判 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19930', '24', '39', '6', '巴 比 伦 王 在 利 比 拉 、 西 底 家 眼 前 杀 了 他 的 众 子 ， 又 杀 了 犹 大 的 一 切 贵 胄 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19931', '24', '39', '7', '并 且 剜 西 底 家 的 眼 睛 ， 用 铜 链 锁 着 他 ， 要 带 到 巴 比 伦 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19932', '24', '39', '8', '迦 勒 底 人 用 火 焚 烧 王 宫 和 百 姓 的 房 屋 ， 又 拆 毁 耶 路 撒 冷 的 城 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19933', '24', '39', '9', '那 时 ， 护 卫 长 尼 布 撒 拉 旦 将 城 里 所 剩 下 的 百 姓 和 投 降 他 的 逃 民 ， 以 及 其 余 的 民 都 掳 到 巴 比 伦 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19934', '24', '39', '10', '护 卫 长 尼 布 撒 拉 旦 却 将 民 中 毫 无 所 有 的 穷 人 留 在 犹 大 地 ， 当 时 给 他 们 葡 萄 园 和 田 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19935', '24', '39', '11', '＜ 耶 利 米 被 释 放 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19936', '24', '39', '12', '“ 你 领 他 去 ， 好 好 地 看 待 他 ， 切 不 可 害 他 ； 他 对 你 怎 么 说 ， 你 就 向 他 怎 么 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19937', '24', '39', '13', '护 卫 长 尼 布 撒 拉 旦 和 尼 布 沙 斯 班 ─ ─ 拉 撒 力 、 尼 甲 ． 沙 利 薛 ─ ─ 拉 墨 ， 并 巴 比 伦 王 的 一 切 官 长 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19938', '24', '39', '14', '打 发 人 去 ， 将 耶 利 米 从 护 卫 兵 院 中 提 出 来 ， 交 与 沙 番 的 孙 子 亚 希 甘 的 儿 子 基 大 利 ， 带 回 家 去 。 于 是 耶 利 米 住 在 民 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19939', '24', '39', '15', '＜ 以 伯 ． 米 勒 的 希 望 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19940', '24', '39', '16', '“ 你 去 告 诉 古 实 人 以 伯 ． 米 勒 说 ， 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 说 降 祸 不 降 福 的 话 必 临 到 这 城 ， 到 那 时 必 在 你 面 前 成 就 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19941', '24', '39', '17', '耶 和 华 说 ： 到 那 日 我 必 拯 救 你 ， 你 必 不 致 交 在 你 所 怕 的 人 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19942', '24', '39', '18', '我 定 要 搭 救 你 ， 你 不 致 倒 在 刀 下 ， 却 要 以 自 己 的 命 为 掠 物 ， 因 你 倚 靠 我 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19943', '24', '40', '1', '＜ 耶 利 米 跟 基 大 利 同 住 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19944', '24', '40', '2', '护 卫 长 将 耶 利 米 叫 来 ， 对 他 说 ： “ 耶 和 华 ─ ─ 你 的 神 曾 说 要 降 这 祸 与 此 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19945', '24', '40', '3', '耶 和 华 使 这 祸 临 到 ， 照 他 所 说 的 行 了 ； 因 为 你 们 得 罪 耶 和 华 ， 没 有 听 从 他 的 话 ， 所 以 这 事 临 到 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19946', '24', '40', '4', '现 在 我 解 开 你 手 上 的 链 子 ， 你 若 看 与 我 同 往 巴 比 伦 去 好 ， 就 可 以 去 ， 我 必 厚 待 你 ； 你 若 看 与 我 同 往 巴 比 伦 去 不 好 ， 就 不 必 去 。 看 哪 ， 全 地 在 你 面 前 ， 你 以 为 哪 里 美 好 ， 哪 里 合 宜 ， 只 管 上 那 里 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19947', '24', '40', '5', '耶 利 米 还 没 有 回 去 ， 护 卫 长 说 ： “ 你 可 以 回 到 沙 番 的 孙 子 亚 希 甘 的 儿 子 基 大 利 那 里 去 ； 现 在 巴 比 伦 王 立 他 作 犹 大 城 邑 的 省 长 。 你 可 以 在 他 那 里 住 在 民 中 ， 不 然 ， 你 看 哪 里 合 宜 就 可 以 上 那 里 去 。 ” 于 是 护 卫 长 送 他 粮 食 和 礼 物 ， 释 放 他 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19948', '24', '40', '6', '耶 利 米 就 到 米 斯 巴 见 亚 希 甘 的 儿 子 基 大 利 ， 在 他 那 里 住 在 境 内 剩 下 的 民 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19949', '24', '40', '7', '＜ 基 大 利 被 委 派 为 总 督 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19950', '24', '40', '8', '于 是 军 长 尼 探 雅 的 儿 子 以 实 玛 利 ， 加 利 亚 的 两 个 儿 子 约 哈 难 和 约 拿 单 ， 单 户 篾 的 儿 子 西 莱 雅 ， 并 尼 陀 法 人 以 斐 的 众 子 ， 玛 迦 人 的 儿 子 耶 撒 尼 亚 和 属 他 们 的 人 ， 都 到 米 斯 巴 见 基 大 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19951', '24', '40', '9', '沙 番 的 孙 子 亚 希 甘 的 儿 子 基 大 利 向 他 们 和 属 他 们 的 人 起 誓 说 ： “ 不 要 怕 服 事 迦 勒 底 人 ， 只 管 住 在 这 地 ， 服 事 巴 比 伦 王 ， 就 可 以 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19952', '24', '40', '10', '至 于 我 ， 我 要 住 在 米 斯 巴 ， 伺 候 那 到 我 们 这 里 来 的 迦 勒 底 人 ； 只 是 你 们 当 积 蓄 酒 、 油 ， 和 夏 天 的 果 子 ， 收 在 器 皿 里 ， 住 在 你 们 所 占 的 城 邑 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19953', '24', '40', '11', '在 摩 押 地 和 亚 扪 人 中 ， 在 以 东 地 和 各 国 的 一 切 犹 大 人 ， 听 见 巴 比 伦 王 留 下 些 犹 大 人 ， 并 立 沙 番 的 孙 子 亚 希 甘 的 儿 子 基 大 利 管 理 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19954', '24', '40', '12', '这 一 切 犹 大 人 就 从 所 赶 到 的 各 处 回 来 ， 到 犹 大 地 米 斯 巴 的 基 大 利 那 里 ， 又 积 蓄 了 许 多 的 酒 ， 并 夏 天 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19955', '24', '40', '13', '＜ 基 大 利 被 暗 杀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19956', '24', '40', '14', '对 他 说 ： “ 亚 扪 人 的 王 巴 利 斯 打 发 尼 探 雅 的 儿 子 以 实 玛 利 来 要 你 的 命 ， 你 知 道 吗 ？ ” 亚 希 甘 的 儿 子 基 大 利 却 不 信 他 们 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19957', '24', '40', '15', '加 利 亚 的 儿 子 约 哈 难 在 米 斯 巴 私 下 对 基 大 利 说 ： “ 求 你 容 我 去 杀 尼 探 雅 的 儿 子 以 实 玛 利 ， 必 无 人 知 道 。 何 必 让 他 要 你 的 命 ， 使 聚 集 到 你 这 里 来 的 犹 大 人 都 分 散 ， 以 致 犹 大 剩 下 的 人 都 灭 亡 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19958', '24', '40', '16', '亚 希 甘 的 儿 子 基 大 利 对 加 利 亚 的 儿 子 约 哈 难 说 ： “ 你 不 可 行 这 事 ， 你 所 论 以 实 玛 利 的 话 是 假 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19959', '24', '41', '1', '七 月 间 ， 王 的 大 臣 宗 室 以 利 沙 玛 的 孙 子 、 尼 探 雅 的 儿 子 以 实 玛 利 带 着 十 个 人 ， 来 到 米 斯 巴 见 亚 希 甘 的 儿 子 基 大 利 。 他 们 在 米 斯 巴 一 同 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19960', '24', '41', '2', '尼 探 雅 的 儿 子 以 实 玛 利 和 同 他 来 的 那 十 个 人 起 来 ， 用 刀 杀 了 沙 番 的 孙 子 亚 希 甘 的 儿 子 基 大 利 ， 就 是 巴 比 伦 王 所 立 为 全 地 省 长 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19961', '24', '41', '3', '以 实 玛 利 又 杀 了 在 米 斯 巴 、 基 大 利 那 里 的 一 切 犹 大 人 和 所 遇 见 的 迦 勒 底 兵 丁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19962', '24', '41', '4', '他 杀 了 基 大 利 ， 无 人 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19963', '24', '41', '5', '第 二 天 ， 有 八 十 人 从 示 剑 和 示 罗 ， 并 撒 马 利 亚 来 ， 胡 须 剃 去 ， 衣 服 撕 裂 ， 身 体 划 破 ， 手 拿 素 祭 和 乳 香 ， 要 奉 到 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19964', '24', '41', '6', '尼 探 雅 的 儿 子 以 实 玛 利 出 米 斯 巴 迎 接 他 们 ， 随 走 随 哭 。 遇 见 了 他 们 ， 就 对 他 们 说 ： “ 你 们 可 以 来 见 亚 希 甘 的 儿 子 基 大 利 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19965', '24', '41', '7', '他 们 到 了 城 中 ， 尼 探 雅 的 儿 子 以 实 玛 利 和 同 着 他 的 人 就 将 他 们 杀 了 ， 抛 在 坑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19966', '24', '41', '8', '只 是 他 们 中 间 有 十 个 人 对 以 实 玛 利 说 ： “ 不 要 杀 我 们 ， 因 为 我 们 有 许 多 大 麦 、 小 麦 、 油 、 蜜 藏 在 田 间 。 ” 于 是 他 住 了 手 ， 没 有 将 他 们 杀 在 弟 兄 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19967', '24', '41', '9', '以 实 玛 利 将 所 杀 之 人 的 尸 首 都 抛 在 坑 里 基 大 利 的 旁 边 ； 这 坑 是 从 前 亚 撒 王 因 怕 以 色 列 王 巴 沙 所 挖 的 。 尼 探 雅 的 儿 子 以 实 玛 利 将 那 些 被 杀 的 人 填 满 了 坑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19968', '24', '41', '10', '以 实 玛 利 将 米 斯 巴 剩 下 的 人 ， 就 是 众 公 主 和 仍 住 在 米 斯 巴 所 有 的 百 姓 ， 原 是 护 卫 长 尼 布 撒 拉 旦 交 给 亚 希 甘 的 儿 子 基 大 利 的 ， 都 掳 去 了 。 尼 探 雅 的 儿 子 以 实 玛 利 掳 了 他 们 ， 要 往 亚 扪 人 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19969', '24', '41', '11', '加 利 亚 的 儿 子 约 哈 难 和 同 着 他 的 众 军 长 听 见 尼 探 雅 的 儿 子 以 实 玛 利 所 行 的 一 切 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19970', '24', '41', '12', '就 带 领 众 人 前 往 ， 要 和 尼 探 雅 的 儿 子 以 实 玛 利 争 战 ， 在 基 遍 的 大 水 旁 ｛ 或 译 ： 大 水 池 旁 ｝ 遇 见 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19971', '24', '41', '13', '以 实 玛 利 那 里 的 众 人 看 见 加 利 亚 的 儿 子 约 哈 难 和 同 着 他 的 众 军 长 ， 就 都 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19972', '24', '41', '14', '这 样 ， 以 实 玛 利 从 米 斯 巴 所 掳 去 的 众 人 都 转 身 归 加 利 亚 的 儿 子 约 哈 难 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19973', '24', '41', '15', '尼 探 雅 的 儿 子 以 实 玛 利 和 八 个 人 脱 离 约 哈 难 的 手 ， 逃 往 亚 扪 人 那 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19974', '24', '41', '16', '尼 探 雅 的 儿 子 以 实 玛 利 杀 了 亚 希 甘 的 儿 子 基 大 利 ， 从 米 斯 巴 将 剩 下 的 一 切 百 姓 、 兵 丁 、 妇 女 、 孩 童 、 太 监 掳 到 基 遍 之 后 ， 加 利 亚 的 儿 子 约 哈 难 和 同 着 他 的 众 军 长 将 他 们 都 夺 回 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19975', '24', '41', '17', '带 到 靠 近 伯 利 恒 的 金 罕 寓 ｛ 或 译 ： 基 罗 特 金 罕 ｝ 住 下 ， 要 进 入 埃 及 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19976', '24', '41', '18', '因 为 尼 探 雅 的 儿 子 以 实 玛 利 杀 了 巴 比 伦 王 所 立 为 省 长 的 亚 希 甘 的 儿 子 基 大 利 ， 约 哈 难 惧 怕 迦 勒 底 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19977', '24', '42', '1', '＜ 人 民 求 耶 利 米 代 祷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19978', '24', '42', '2', '对 先 知 耶 利 米 说 ： “ 求 你 准 我 们 在 你 面 前 祈 求 ， 为 我 们 这 剩 下 的 人 祷 告 耶 和 华 ─ ─ 你 的 神 。 我 们 本 来 众 多 ， 现 在 剩 下 的 极 少 ， 这 是 你 亲 眼 所 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19979', '24', '42', '3', '愿 耶 和 华 ─ ─ 你 的 神 指 示 我 们 所 当 走 的 路 ， 所 当 做 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19980', '24', '42', '4', '先 知 耶 利 米 对 他 们 说 ： “ 我 已 经 听 见 你 们 了 ， 我 必 照 着 你 们 的 话 祷 告 耶 和 华 ─ ─ 你 们 的 神 。 耶 和 华 无 论 回 答 什 么 ， 我 必 都 告 诉 你 们 ， 毫 不 隐 瞒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19981', '24', '42', '5', '于 是 他 们 对 耶 利 米 说 ： “ 我 们 若 不 照 耶 和 华 ─ ─ 你 的 神 差 遣 你 来 说 的 一 切 话 行 ， 愿 耶 和 华 在 我 们 中 间 作 真 实 诚 信 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19982', '24', '42', '6', '我 们 现 在 请 你 到 耶 和 华 ─ ─ 我 们 的 神 面 前 ， 他 说 的 无 论 是 好 是 歹 ， 我 们 都 必 听 从 ； 我 们 听 从 耶 和 华 ─ ─ 我 们 神 的 话 ， 就 可 以 得 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19983', '24', '42', '7', '＜ 耶 和 华 回 答 耶 利 米 的 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19984', '24', '42', '8', '他 就 将 加 利 亚 的 儿 子 约 哈 难 和 同 着 他 的 众 军 长 ， 并 众 百 姓 ， 从 最 小 的 到 至 大 的 都 叫 了 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19985', '24', '42', '9', '对 他 们 说 ： “ 耶 和 华 ─ ─ 以 色 列 的 神 ， 就 是 你 们 请 我 在 他 面 前 为 你 们 祈 求 的 主 ， 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19986', '24', '42', '10', '‘ 你 们 若 仍 住 在 这 地 ， 我 就 建 立 你 们 ， 必 不 拆 毁 ， 栽 植 你 们 ， 并 不 拔 出 ， 因 我 为 降 与 你 们 的 灾 祸 后 悔 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19987', '24', '42', '11', '不 要 怕 你 们 所 怕 的 巴 比 伦 王 ’ ” 。 耶 和 华 说 ： “ 不 要 怕 他 ！ 因 为 我 与 你 们 同 在 ， 要 拯 救 你 们 脱 离 他 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19988', '24', '42', '12', '我 也 要 使 他 发 怜 悯 ， 好 怜 悯 你 们 ， 叫 你 们 归 回 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19989', '24', '42', '13', '倘 若 你 们 说 ： ‘ 我 们 不 住 在 这 地 ’ ， 以 致 不 听 从 耶 和 华 ─ ─ 你 们 神 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19990', '24', '42', '14', '说 ： ‘ 我 们 不 住 这 地 ， 却 要 进 入 埃 及 地 ， 在 那 里 看 不 见 争 战 ， 听 不 见 角 声 ， 也 不 致 无 食 饥 饿 。 我 们 必 住 在 那 里 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19991', '24', '42', '15', '你 们 所 剩 下 的 犹 大 人 哪 ， 现 在 要 听 耶 和 华 的 话 。 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： ‘ 你 们 若 定 意 要 进 入 埃 及 ， 在 那 里 寄 居 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19992', '24', '42', '16', '你 们 所 惧 怕 的 刀 剑 在 埃 及 地 必 追 上 你 们 ！ 你 们 所 惧 怕 的 饥 荒 在 埃 及 要 紧 紧 地 跟 随 你 们 ！ 你 们 必 死 在 那 里 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19993', '24', '42', '17', '凡 定 意 要 进 入 埃 及 在 那 里 寄 居 的 必 遭 刀 剑 、 饥 荒 、 瘟 疫 而 死 ， 无 一 人 存 留 ， 逃 脱 我 所 降 与 他 们 的 灾 祸 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19994', '24', '42', '18', '“ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： ‘ 我 怎 样 将 我 的 怒 气 和 忿 怒 倾 在 耶 路 撒 冷 的 居 民 身 上 ， 你 们 进 入 埃 及 的 时 候 ， 我 也 必 照 样 将 我 的 忿 怒 倾 在 你 们 身 上 ， 以 致 你 们 令 人 辱 骂 、 惊 骇 、 咒 诅 、 羞 辱 ， 你 们 不 得 再 见 这 地 方 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19995', '24', '42', '19', '所 剩 下 的 犹 大 人 哪 ， 耶 和 华 论 到 你 们 说 ： ‘ 不 要 进 入 埃 及 去 。 ’ 你 们 要 确 实 地 知 道 我 今 日 警 教 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19996', '24', '42', '20', '你 们 行 诡 诈 自 害 ； 因 为 你 们 请 我 到 耶 和 华 ─ ─ 你 们 的 神 那 里 ， 说 ： ‘ 求 你 为 我 们 祷 告 耶 和 华 ─ ─ 我 们 神 ， 照 耶 和 华 ─ ─ 我 们 的 神 一 切 所 说 的 告 诉 我 们 ， 我 们 就 必 遵 行 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19997', '24', '42', '21', '我 今 日 将 这 话 告 诉 你 们 ， 耶 和 华 ─ ─ 你 们 的 神 为 你 们 的 事 差 遣 我 到 你 们 那 里 说 的 ， 你 们 却 一 样 没 有 听 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19998', '24', '42', '22', '现 在 你 们 要 确 实 地 知 道 ， 你 们 在 所 要 去 寄 居 之 地 必 遭 刀 剑 、 饥 荒 、 瘟 疫 而 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('19999', '24', '43', '1', '＜ 耶 利 米 被 带 到 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20000', '24', '43', '2', '何 沙 雅 的 儿 子 亚 撒 利 雅 和 加 利 亚 的 儿 子 约 哈 难 ， 并 一 切 狂 傲 的 人 ， 就 对 耶 利 米 说 ： “ 你 说 谎 言 ！ 耶 和 华 ─ ─ 我 们 的 神 并 没 有 差 遣 你 来 说 ： ‘ 你 们 不 可 进 入 埃 及 ， 在 那 里 寄 居 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20001', '24', '43', '3', '这 是 尼 利 亚 的 儿 子 巴 录 挑 唆 你 害 我 们 ， 要 将 我 们 交 在 迦 勒 底 人 的 手 中 ， 使 我 们 有 被 杀 的 ， 有 被 掳 到 巴 比 伦 去 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20002', '24', '43', '4', '于 是 加 利 亚 的 儿 子 约 哈 难 和 一 切 军 长 ， 并 众 百 姓 ， 不 听 从 耶 和 华 的 话 住 在 犹 大 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20003', '24', '43', '5', '加 利 亚 的 儿 子 约 哈 难 和 一 切 军 长 却 将 所 剩 下 的 犹 大 人 ， 就 是 从 被 赶 到 各 国 回 来 在 犹 大 地 寄 居 的 男 人 、 妇 女 、 孩 童 ， 和 众 公 主 ， 并 护 卫 长 尼 布 撒 拉 旦 所 留 在 沙 番 的 孙 子 亚 希 甘 的 儿 子 基 大 利 那 里 的 众 人 ， 与 先 知 耶 利 米 ， 以 及 尼 利 亚 的 儿 子 巴 录 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20004', '24', '43', '6', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20005', '24', '43', '7', '都 带 入 埃 及 地 ， 到 了 答 比 匿 。 这 是 因 他 们 不 听 从 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20006', '24', '43', '8', '在 答 比 匿 ， 耶 和 华 的 话 临 到 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20007', '24', '43', '9', '“ 你 在 犹 大 人 眼 前 要 用 手 拿 几 块 大 石 头 ， 藏 在 砌 砖 的 灰 泥 中 ， 就 是 在 答 比 匿 法 老 的 宫 门 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20008', '24', '43', '10', '对 他 们 说 ： ‘ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 必 召 我 的 仆 人 巴 比 伦 王 尼 布 甲 尼 撒 来 。 在 所 藏 的 石 头 上 我 要 安 置 他 的 宝 座 ； 他 必 将 光 华 的 宝 帐 支 搭 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20009', '24', '43', '11', '他 要 来 攻 击 埃 及 地 ， 定 为 死 亡 的 ， 必 致 死 亡 ； 定 为 掳 掠 的 ， 必 被 掳 掠 ； 定 为 刀 杀 的 ， 必 交 刀 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20010', '24', '43', '12', '我 要 在 埃 及 神 的 庙 中 使 火 着 起 ， 巴 比 伦 王 要 将 庙 宇 焚 烧 ， 神 像 掳 去 ； 他 要 得 ｛ 原 文 是 披 上 ｝ 埃 及 地 ， 好 像 牧 人 披 上 外 衣 ， 从 那 里 安 然 而 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20011', '24', '43', '13', '他 必 打 碎 埃 及 地 伯 ． 示 麦 的 柱 像 ， 用 火 焚 烧 埃 及 神 的 庙 宇 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20012', '24', '44', '1', '＜ 耶 和 华 给 流 亡 埃 及 的 以 色 列 人 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20013', '24', '44', '2', '“ 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 所 降 与 耶 路 撒 冷 和 犹 大 各 城 的 一 切 灾 祸 你 们 都 看 见 了 。 那 些 城 邑 今 日 荒 凉 ， 无 人 居 住 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20014', '24', '44', '3', '这 是 因 居 民 所 行 的 恶 ， 去 烧 香 事 奉 别 神 ， 就 是 他 们 和 你 们 ， 并 你 们 列 祖 所 不 认 识 的 神 ， 惹 我 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20015', '24', '44', '4', '我 从 早 起 来 差 遣 我 的 仆 人 众 先 知 去 说 ， 你 们 切 不 要 行 我 所 厌 恶 这 可 憎 之 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20016', '24', '44', '5', '他 们 却 不 听 从 ， 不 侧 耳 而 听 ， 不 转 离 恶 事 ， 仍 向 别 神 烧 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20017', '24', '44', '6', '因 此 ， 我 的 怒 气 和 忿 怒 都 倒 出 来 ， 在 犹 大 城 邑 中 和 耶 路 撒 冷 的 街 市 上 ， 如 火 着 起 ， 以 致 都 荒 废 凄 凉 ， 正 如 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20018', '24', '44', '7', '现 在 耶 和 华 ─ ─ 万 军 之 神 、 以 色 列 的 神 如 此 说 ： 你 们 为 何 作 这 大 恶 自 害 己 命 ， 使 你 们 的 男 人 、 妇 女 、 婴 孩 ， 和 吃 奶 的 都 从 犹 大 中 剪 除 、 不 留 一 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20019', '24', '44', '8', '就 是 因 你 们 手 所 做 的 ， 在 所 去 寄 居 的 埃 及 地 向 别 神 烧 香 惹 我 发 怒 ， 使 你 们 被 剪 除 ， 在 天 下 万 国 中 令 人 咒 诅 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20020', '24', '44', '9', '你 们 列 祖 的 恶 行 ， 犹 大 列 王 和 他 们 后 妃 的 恶 行 ， 你 们 自 己 和 你 们 妻 子 的 恶 行 ， 就 是 在 犹 大 地 、 耶 路 撒 冷 街 上 所 行 的 ， 你 们 都 忘 了 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20021', '24', '44', '10', '到 如 今 还 没 有 懊 悔 ， 没 有 惧 怕 ， 没 有 遵 行 我 在 你 们 和 你 们 列 祖 面 前 所 设 立 的 法 度 律 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20022', '24', '44', '11', '“ 所 以 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 我 必 向 你 们 变 脸 降 灾 ， 以 致 剪 除 犹 大 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20023', '24', '44', '12', '那 定 意 进 入 埃 及 地 、 在 那 里 寄 居 的 ， 就 是 所 剩 下 的 犹 大 人 ， 我 必 使 他 们 尽 都 灭 绝 ， 必 在 埃 及 地 仆 倒 ， 必 因 刀 剑 饥 荒 灭 绝 ； 从 最 小 的 到 至 大 的 都 必 遭 刀 剑 饥 荒 而 死 ， 以 致 令 人 辱 骂 、 惊 骇 、 咒 诅 、 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20024', '24', '44', '13', '我 怎 样 用 刀 剑 、 饥 荒 、 瘟 疫 刑 罚 耶 路 撒 冷 ， 也 必 照 样 刑 罚 那 些 住 在 埃 及 地 的 犹 大 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20025', '24', '44', '14', '甚 至 那 进 入 埃 及 地 寄 居 的 ， 就 是 所 剩 下 的 犹 大 人 ， 都 不 得 逃 脱 ， 也 不 得 存 留 归 回 犹 大 地 。 他 们 心 中 甚 想 归 回 居 住 之 地 ； 除 了 逃 脱 的 以 外 ， 一 个 都 不 能 归 回 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20026', '24', '44', '15', '那 些 住 在 埃 及 地 巴 忒 罗 知 道 自 己 妻 子 向 别 神 烧 香 的 ， 与 旁 边 站 立 的 众 妇 女 ， 聚 集 成 群 ， 回 答 耶 利 米 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20027', '24', '44', '16', '“ 论 到 你 奉 耶 和 华 的 名 向 我 们 所 说 的 话 ， 我 们 必 不 听 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20028', '24', '44', '17', '我 们 定 要 成 就 我 们 口 中 所 出 的 一 切 话 ， 向 天 后 烧 香 、 浇 奠 祭 ， 按 着 我 们 与 我 们 列 祖 、 君 王 、 首 领 在 犹 大 的 城 邑 中 和 耶 路 撒 冷 的 街 市 上 素 常 所 行 的 一 样 ； 因 为 那 时 我 们 吃 饱 饭 、 享 福 乐 ， 并 不 见 灾 祸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20029', '24', '44', '18', '自 从 我 们 停 止 向 天 后 烧 香 、 浇 奠 祭 ， 我 们 倒 缺 乏 一 切 ， 又 因 刀 剑 饥 荒 灭 绝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20030', '24', '44', '19', '妇 女 说 ： “ 我 们 向 天 后 烧 香 、 浇 奠 祭 ， 做 天 后 像 的 饼 供 奉 她 ， 向 她 浇 奠 祭 ， 是 外 乎 我 们 的 丈 夫 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20031', '24', '44', '20', '耶 利 米 对 一 切 那 样 回 答 他 的 男 人 妇 女 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20032', '24', '44', '21', '“ 你 们 与 你 们 列 祖 、 君 王 、 首 领 ， 并 国 内 的 百 姓 ， 在 犹 大 城 邑 中 和 耶 路 撒 冷 街 市 上 所 烧 的 香 ， 耶 和 华 岂 不 记 念 ， 心 中 岂 不 思 想 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20033', '24', '44', '22', '耶 和 华 因 你 们 所 作 的 恶 、 所 行 可 憎 的 事 ， 不 能 再 容 忍 ， 所 以 你 们 的 地 荒 凉 ， 令 人 惊 骇 咒 诅 ， 无 人 居 住 ， 正 如 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20034', '24', '44', '23', '你 们 烧 香 ， 得 罪 耶 和 华 ， 没 有 听 从 他 的 话 ， 没 有 遵 行 他 的 律 法 、 条 例 、 法 度 ， 所 以 你 们 遭 遇 这 灾 祸 ， 正 如 今 日 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20035', '24', '44', '24', '耶 利 米 又 对 众 民 和 众 妇 女 说 ： “ 你 们 在 埃 及 地 的 一 切 犹 大 人 当 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20036', '24', '44', '25', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 你 们 和 你 们 的 妻 都 口 中 说 、 手 里 做 ， 说 ： ‘ 我 们 定 要 偿 还 所 许 的 愿 ， 向 天 后 烧 香 、 浇 奠 祭 。 ’ 现 在 你 们 只 管 坚 定 所 许 的 愿 而 偿 还 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20037', '24', '44', '26', '所 以 你 们 住 在 埃 及 地 的 一 切 犹 大 人 当 听 耶 和 华 的 话 。 耶 和 华 说 ： 我 指 着 我 的 大 名 起 誓 ， 在 埃 及 全 地 ， 我 的 名 不 再 被 犹 大 一 个 人 的 口 称 呼 说 ： ‘ 我 指 着 主 ─ ─ 永 生 的 耶 和 华 起 誓 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20038', '24', '44', '27', '我 向 他 们 留 意 降 祸 不 降 福 ； 在 埃 及 地 的 一 切 犹 大 人 必 因 刀 剑 、 饥 荒 所 灭 ， 直 到 灭 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20039', '24', '44', '28', '脱 离 刀 剑 、 从 埃 及 地 归 回 犹 大 地 的 人 数 很 少 ； 那 进 入 埃 及 地 要 在 那 里 寄 居 的 ， 就 是 所 剩 下 的 犹 大 人 ， 必 知 道 是 谁 的 话 立 得 住 ， 是 我 的 话 呢 ？ 是 他 们 的 话 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20040', '24', '44', '29', '耶 和 华 说 ： 我 在 这 地 方 刑 罚 你 们 ， 必 有 预 兆 ， 使 你 们 知 道 我 降 祸 与 你 们 的 话 必 要 立 得 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20041', '24', '44', '30', '耶 和 华 如 此 说 ： 我 必 将 埃 及 王 法 老 合 弗 拉 交 在 他 仇 敌 和 寻 索 其 命 的 人 手 中 ， 像 我 将 犹 大 王 西 底 家 交 在 他 仇 敌 和 寻 索 其 命 的 巴 比 伦 王 尼 布 甲 尼 撒 手 中 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20042', '24', '45', '1', '＜ 耶 和 华 给 巴 录 的 许 诺 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20043', '24', '45', '2', '“ 巴 录 啊 ， 耶 和 华 ─ ─ 以 色 列 的 神 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20044', '24', '45', '3', '巴 录 ｛ 原 文 是 你 ｝ 曾 说 ： ‘ 哀 哉 ！ 耶 和 华 将 忧 愁 加 在 我 的 痛 苦 上 ， 我 因 唉 哼 而 困 乏 ， 不 得 安 歇 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20045', '24', '45', '4', '你 要 这 样 告 诉 他 ， 耶 和 华 如 此 说 ： 我 所 建 立 的 ， 我 必 拆 毁 ； 我 所 栽 植 的 ， 我 必 拔 出 ； 在 全 地 我 都 如 此 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20046', '24', '45', '5', '你 为 自 己 图 谋 大 事 吗 ？ 不 要 图 谋 ！ 我 必 使 灾 祸 临 到 凡 有 血 气 的 。 但 你 无 论 往 哪 里 去 ， 我 必 使 你 以 自 己 的 命 为 掠 物 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20047', '24', '46', '1', '＜ 埃 及 在 迦 基 米 施 受 挫 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20048', '24', '46', '2', '论 到 关 乎 埃 及 王 法 老 尼 哥 的 军 队 ： 这 军 队 安 营 在 幼 发 拉 底 河 边 的 迦 基 米 施 ， 是 巴 比 伦 王 尼 布 甲 尼 撒 在 犹 大 王 约 西 亚 的 儿 子 约 雅 敬 第 四 年 所 打 败 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20049', '24', '46', '3', '你 们 要 预 备 大 小 盾 牌 ， 往 前 上 阵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20050', '24', '46', '4', '你 们 套 上 车 ， 骑 上 马 ！ 顶 盔 站 立 ， 磨 枪 贯 甲 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20051', '24', '46', '5', '我 为 何 看 见 他 们 惊 惶 转 身 退 后 呢 ？ 他 们 的 勇 士 打 败 了 ， 急 忙 逃 跑 ， 并 不 回 头 ； 惊 吓 四 围 都 有 ！ 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20052', '24', '46', '6', '不 要 容 快 跑 的 逃 避 ； 不 要 容 勇 士 逃 脱 ｛ 或 译 ： 快 跑 的 不 能 逃 避 ； 勇 士 不 能 逃 脱 ｝ ； 他 们 在 北 方 幼 发 拉 底 河 边 绊 跌 仆 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20053', '24', '46', '7', '像 尼 罗 河 涨 发 ， 像 江 河 之 水 翻 腾 的 是 谁 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20054', '24', '46', '8', '埃 及 像 尼 罗 河 涨 发 ， 像 江 河 的 水 翻 腾 。 他 说 ： 我 要 涨 发 遮 盖 遍 地 ； 我 要 毁 灭 城 邑 和 其 中 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20055', '24', '46', '9', '马 匹 上 去 吧 ！ 车 辆 急 行 吧 ！ 勇 士 ， 就 是 手 拿 盾 牌 的 古 实 人 和 弗 人 ｛ 又 作 利 比 亚 人 ｝ ， 并 拉 弓 的 路 德 族 ， 都 出 去 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20056', '24', '46', '10', '那 日 是 主 ─ ─ 万 军 之 耶 和 华 报 仇 的 日 子 ， 要 向 敌 人 报 仇 。 刀 剑 必 吞 吃 得 饱 ， 饮 血 饮 足 ； 因 为 主 ─ ─ 万 军 之 耶 和 华 在 北 方 幼 发 拉 底 河 边 有 献 祭 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20057', '24', '46', '11', '埃 及 的 民 ｛ 原 文 是 处 女 ｝ 哪 ， 可 以 上 基 列 取 乳 香 去 ； 你 虽 多 服 良 药 ， 总 是 徒 然 ， 不 得 治 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20058', '24', '46', '12', '列 国 听 见 你 的 羞 辱 ， 遍 地 满 了 你 的 哀 声 ； 勇 士 与 勇 士 彼 此 相 碰 ， 一 齐 跌 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20059', '24', '46', '13', '＜ 尼 布 甲 尼 撒 来 犯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20060', '24', '46', '14', '你 们 要 传 扬 在 埃 及 ， 宣 告 在 密 夺 ， 报 告 在 挪 弗 、 答 比 匿 说 ： 要 站 起 出 队 ， 自 作 准 备 ， 因 为 刀 剑 在 你 四 围 施 行 吞 灭 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20061', '24', '46', '15', '你 的 壮 士 为 何 被 冲 去 呢 ？ 他 们 站 立 不 住 ； 因 为 耶 和 华 驱 逐 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20062', '24', '46', '16', '使 多 人 绊 跌 ； 他 们 也 彼 此 撞 倒 ， 说 ： 起 来 吧 ！ 我 们 再 往 本 民 本 地 去 ， 好 躲 避 欺 压 的 刀 剑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20063', '24', '46', '17', '他 们 在 那 里 喊 叫 说 ： 埃 及 王 法 老 不 过 是 个 声 音 ｛ 或 译 ： 已 经 败 亡 ｝ ； 他 已 错 过 所 定 的 时 候 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20064', '24', '46', '18', '君 王 ─ ─ 名 为 万 军 之 耶 和 华 的 说 ： 我 指 着 我 的 永 生 起 誓 ： 尼 布 甲 尼 撒 ｛ 原 文 是 他 ｝ 来 的 势 派 必 像 他 泊 在 众 山 之 中 ， 像 迦 密 在 海 边 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20065', '24', '46', '19', '住 在 埃 及 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 要 预 备 掳 去 时 所 用 的 物 件 ； 因 为 挪 弗 必 成 为 荒 场 ， 且 被 烧 毁 ， 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20066', '24', '46', '20', '埃 及 是 肥 美 的 母 牛 犊 ； 但 出 于 北 方 的 毁 灭 ｛ 或 译 牛 亡 ｝ 来 到 了 ！ 来 到 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20067', '24', '46', '21', '其 中 的 雇 勇 好 像 圈 里 的 肥 牛 犊 ， 他 们 转 身 退 后 ， 一 齐 逃 跑 ， 站 立 不 住 ； 因 为 他 们 遭 难 的 日 子 、 追 讨 的 时 候 已 经 临 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20068', '24', '46', '22', '其 中 的 声 音 好 像 蛇 行 一 样 。 敌 人 要 成 队 而 来 ， 如 砍 伐 树 木 的 手 拿 斧 子 攻 击 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20069', '24', '46', '23', '耶 和 华 说 ： 埃 及 的 树 林 虽 然 不 能 寻 察 ｛ 或 译 ： 穿 不 过 ｝ ， 敌 人 却 要 砍 伐 ， 因 他 们 多 于 蝗 虫 ， 不 可 胜 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20070', '24', '46', '24', '埃 及 的 民 ｛ 原 文 是 女 子 ｝ 必 然 蒙 羞 ， 必 交 在 北 方 人 的 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20071', '24', '46', '25', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 说 ： “ 我 必 刑 罚 挪 的 亚 扪 ｛ 埃 及 尊 大 之 神 ｝ 和 法 老 ， 并 埃 及 与 埃 及 的 神 ， 以 及 君 王 ， 也 必 刑 罚 法 老 和 倚 靠 他 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20072', '24', '46', '26', '我 要 将 他 们 交 付 寻 索 其 命 之 人 的 手 和 巴 比 伦 王 尼 布 甲 尼 撒 与 他 臣 仆 的 手 ； 以 后 埃 及 必 再 有 人 居 住 ， 与 从 前 一 样 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20073', '24', '46', '27', '＜ 耶 和 华 要 救 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20074', '24', '46', '28', '我 的 仆 人 雅 各 啊 ， 不 要 惧 怕 ！ 因 我 与 你 同 在 。 我 要 将 我 所 赶 你 到 的 那 些 国 灭 绝 净 尽 ， 却 不 将 你 灭 绝 净 尽 ， 倒 要 从 宽 惩 治 你 ， 万 不 能 不 罚 你 ｛ 不 罚 你 ： 或 译 以 你 为 无 罪 ｝ 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20075', '24', '47', '1', '＜ 有 关 非 利 士 的 话 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20076', '24', '47', '2', '耶 和 华 如 此 说 ： 有 水 从 北 方 发 起 ， 成 为 涨 溢 的 河 ， 要 涨 过 遍 地 和 其 中 所 有 的 ， 并 城 和 其 中 所 住 的 。 人 必 呼 喊 ； 境 内 的 居 民 都 必 哀 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20077', '24', '47', '3', '听 见 敌 人 壮 马 蹄 跳 的 响 声 和 战 车 隆 隆 、 车 轮 轰 轰 ； 为 父 的 手 就 发 软 ， 不 回 头 看 顾 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20078', '24', '47', '4', '因 为 日 子 将 到 ， 要 毁 灭 一 切 非 利 士 人 ， 剪 除 帮 助 泰 尔 、 西 顿 所 剩 下 的 人 。 原 来 耶 和 华 必 毁 灭 非 利 士 人 ， 就 是 迦 斐 托 海 岛 余 剩 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20079', '24', '47', '5', '迦 萨 成 了 光 秃 ； 平 原 中 所 剩 的 亚 实 基 伦 归 于 无 有 。 你 用 刀 划 身 ， 要 到 几 时 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20080', '24', '47', '6', '耶 和 华 的 刀 剑 哪 ， 你 到 几 时 才 止 息 呢 ？ 你 要 入 鞘 ， 安 靖 不 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20081', '24', '47', '7', '耶 和 华 既 吩 咐 你 攻 击 亚 实 基 伦 和 海 边 之 地 ， 他 已 经 派 定 你 ， 焉 能 止 息 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20082', '24', '48', '1', '＜ 摩 押 的 毁 灭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20083', '24', '48', '2', '摩 押 不 再 被 称 赞 。 有 人 在 希 实 本 设 计 谋 害 她 ， 说 ： 来 吧 ！ 我 们 将 她 剪 除 ， 不 再 成 国 。 玛 得 缅 哪 ， 你 也 必 默 默 无 声 ； 刀 剑 必 追 赶 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20084', '24', '48', '3', '从 何 罗 念 有 喊 荒 凉 大 毁 灭 的 哀 声 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20085', '24', '48', '4', '摩 押 毁 灭 了 ！ 她 的 孩 童 ｛ 或 译 ： 家 僮 ｝ 发 哀 声 ， 使 人 听 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20086', '24', '48', '5', '人 上 鲁 希 坡 随 走 随 哭 ， 因 为 在 何 罗 念 的 下 坡 听 见 毁 灭 的 哀 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20087', '24', '48', '6', '你 们 要 奔 逃 ， 自 救 性 命 ， 独 自 居 住 ， 好 像 旷 野 的 杜 松 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20088', '24', '48', '7', '你 因 倚 靠 自 己 所 做 的 和 自 己 的 财 宝 必 被 攻 取 。 基 抹 和 属 他 的 祭 司 、 首 领 也 要 一 同 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20089', '24', '48', '8', '行 毁 灭 的 必 来 到 各 城 ， 并 无 一 城 得 免 。 山 谷 必 致 败 落 ， 平 原 必 被 毁 坏 ； 正 如 耶 和 华 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20090', '24', '48', '9', '要 将 翅 膀 给 摩 押 ， 使 她 可 以 飞 去 。 她 的 城 邑 必 致 荒 凉 ， 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20091', '24', '48', '10', '（ 懒 惰 为 耶 和 华 行 事 的 ， 必 受 咒 诅 ； 禁 止 刀 剑 不 经 血 的 ， 必 受 咒 诅 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20092', '24', '48', '11', '＜ 摩 押 的 城 镇 被 毁 灭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20093', '24', '48', '12', '耶 和 华 说 ： “ 日 子 将 到 ， 我 必 打 发 倒 酒 的 往 她 那 里 去 ， 将 她 倒 出 来 ， 倒 空 她 的 器 皿 ， 打 碎 她 的 坛 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20094', '24', '48', '13', '摩 押 必 因 基 抹 羞 愧 ， 像 以 色 列 家 从 前 倚 靠 伯 特 利 的 神 羞 愧 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20095', '24', '48', '14', '你 们 怎 么 说 ： 我 们 是 勇 士 ， 是 有 勇 力 打 仗 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20096', '24', '48', '15', '摩 押 变 为 荒 场 ， 敌 人 上 去 进 了 她 的 城 邑 。 她 所 特 选 的 少 年 人 下 去 遭 了 杀 戮 ； 这 是 君 王 ─ ─ 名 为 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20097', '24', '48', '16', '摩 押 的 灾 殃 临 近 ； 她 的 苦 难 速 速 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20098', '24', '48', '17', '凡 在 她 四 围 的 和 认 识 她 名 的 ， 你 们 都 要 为 她 悲 伤 ， 说 ： 那 结 实 的 杖 和 那 美 好 的 棍 ， 何 竟 折 断 了 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20099', '24', '48', '18', '住 在 底 本 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 要 从 你 荣 耀 的 位 上 下 来 ， 坐 受 干 渴 ； 因 毁 灭 摩 押 的 上 来 攻 击 你 ， 毁 坏 了 你 的 保 障 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20100', '24', '48', '19', '住 亚 罗 珥 的 啊 ， 要 站 在 道 旁 观 望 ， 问 逃 避 的 男 人 和 逃 脱 的 女 人 说 ： 是 什 么 事 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20101', '24', '48', '20', '摩 押 因 毁 坏 蒙 羞 ； 你 们 要 哀 号 呼 喊 ， 要 在 亚 嫩 旁 报 告 说 ： 摩 押 变 为 荒 场 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20102', '24', '48', '21', '“ 刑 罚 临 到 平 原 之 地 的 何 伦 、 雅 杂 、 米 法 押 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20103', '24', '48', '22', '底 本 、 尼 波 、 伯 ． 低 比 拉 太 音 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20104', '24', '48', '23', '基 列 亭 、 伯 ． 迦 末 、 伯 ． 米 恩 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20105', '24', '48', '24', '加 略 、 波 斯 拉 ， 和 摩 押 地 远 近 所 有 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20106', '24', '48', '25', '摩 押 的 角 砍 断 了 ， 摩 押 的 膀 臂 折 断 了 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20107', '24', '48', '26', '＜ 摩 押 要 受 凌 辱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20108', '24', '48', '27', '摩 押 啊 ， 你 不 曾 嗤 笑 以 色 列 吗 ？ 她 岂 是 在 贼 中 查 出 来 的 呢 ？ 你 每 逢 提 到 她 便 摇 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20109', '24', '48', '28', '摩 押 的 居 民 哪 ， 要 离 开 城 邑 ， 住 在 山 崖 里 ， 像 鸽 子 在 深 渊 口 上 搭 窝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20110', '24', '48', '29', '我 们 听 说 摩 押 人 骄 傲 ， 是 极 其 骄 傲 ； 听 说 他 自 高 自 傲 ， 并 且 狂 妄 ， 居 心 自 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20111', '24', '48', '30', '耶 和 华 说 ： 我 知 道 他 的 忿 怒 是 虚 空 的 ； 他 夸 大 的 话 一 无 所 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20112', '24', '48', '31', '因 此 ， 我 要 为 摩 押 哀 号 ， 为 摩 押 全 地 呼 喊 ； 人 必 为 吉 珥 ． 哈 列 设 人 叹 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20113', '24', '48', '32', '西 比 玛 的 葡 萄 树 啊 ， 我 为 你 哀 哭 ， 甚 于 雅 谢 人 哀 哭 。 你 的 枝 子 蔓 延 过 海 ， 直 长 到 雅 谢 海 。 那 行 毁 灭 的 已 经 临 到 你 夏 天 的 果 子 和 你 所 摘 的 葡 萄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20114', '24', '48', '33', '肥 田 和 摩 押 地 的 欢 喜 快 乐 都 被 夺 去 ； 我 使 酒 醡 的 酒 绝 流 ， 无 人 踹 酒 欢 呼 ； 那 欢 呼 却 变 为 仇 敌 的 呐 喊 ｛ 原 文 是 那 欢 呼 却 不 是 欢 呼 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20115', '24', '48', '34', '“ 希 实 本 人 发 的 哀 声 达 到 以 利 亚 利 ， 直 达 到 雅 杂 ； 从 琐 珥 达 到 何 罗 念 ， 直 到 伊 基 拉 ． 施 利 施 亚 ， 因 为 宁 林 的 水 必 然 干 涸 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20116', '24', '48', '35', '耶 和 华 说 ： “ 我 必 在 摩 押 地 使 那 在 邱 坛 献 祭 的 ， 和 那 向 他 的 神 烧 香 的 都 断 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20117', '24', '48', '36', '我 心 腹 为 摩 押 哀 鸣 如 箫 ， 我 心 肠 为 吉 珥 ． 哈 列 设 人 也 是 如 此 ， 因 摩 押 人 所 得 的 财 物 都 灭 没 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20118', '24', '48', '37', '“ 各 人 头 上 光 秃 ， 胡 须 剪 短 ， 手 有 划 伤 ， 腰 束 麻 布 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20119', '24', '48', '38', '在 摩 押 的 各 房 顶 上 和 街 市 上 处 处 有 人 哀 哭 ； 因 我 打 碎 摩 押 ， 好 像 打 碎 无 人 喜 悦 的 器 皿 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20120', '24', '48', '39', '摩 押 何 等 毁 坏 ！ 何 等 哀 号 ！ 何 等 羞 愧 转 背 ！ 这 样 ， 摩 押 必 令 四 围 的 人 嗤 笑 惊 骇 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20121', '24', '48', '40', '＜ 摩 押 无 路 可 逃 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20122', '24', '48', '41', '加 略 被 攻 取 ， 保 障 也 被 占 据 。 到 那 日 ， 摩 押 的 勇 士 心 中 疼 痛 如 临 产 的 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20123', '24', '48', '42', '摩 押 必 被 毁 灭 ， 不 再 成 国 ， 因 她 向 耶 和 华 夸 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20124', '24', '48', '43', '耶 和 华 说 ： 摩 押 的 居 民 哪 ， 恐 惧 、 陷 坑 、 网 罗 都 临 近 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20125', '24', '48', '44', '躲 避 恐 惧 的 必 坠 入 陷 坑 ； 从 陷 坑 上 来 的 必 被 网 罗 缠 住 ； 因 我 必 使 追 讨 之 年 临 到 摩 押 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20126', '24', '48', '45', '躲 避 的 人 无 力 站 在 希 实 本 的 影 下 ； 因 为 有 火 从 希 实 本 发 出 ， 有 火 焰 出 于 西 宏 的 城 ， 烧 尽 摩 押 的 角 和 哄 嚷 人 的 头 顶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20127', '24', '48', '46', '摩 押 啊 ， 你 有 祸 了 ！ 属 基 抹 的 民 灭 亡 了 ！ 因 你 的 众 子 都 被 掳 去 ， 你 的 众 女 也 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20128', '24', '48', '47', '耶 和 华 说 ： 到 末 后 ， 我 还 要 使 被 掳 的 摩 押 人 归 回 。 摩 押 受 审 判 的 话 到 此 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20129', '24', '49', '1', '＜ 耶 和 华 审 判 亚 扪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20130', '24', '49', '2', '耶 和 华 说 ： 日 子 将 到 ， 我 必 使 人 听 见 打 仗 的 喊 声 ， 是 攻 击 亚 扪 人 拉 巴 的 喊 声 。 拉 巴 要 成 为 乱 堆 ； 属 她 的 乡 村 ｛ 原 文 是 女 子 ｝ 要 被 火 焚 烧 。 先 前 得 以 色 列 地 为 业 的 ， 此 时 以 色 列 倒 要 得 他 们 的 地 为 业 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20131', '24', '49', '3', '希 实 本 哪 ， 你 要 哀 号 ， 因 为 爱 地 变 为 荒 场 。 拉 巴 的 居 民 ｛ 原 文 是 女 子 ｝ 哪 ， 要 呼 喊 ， 以 麻 布 束 腰 ； 要 哭 号 ， 在 篱 笆 中 跑 来 跑 去 ； 因 玛 勒 堪 和 属 他 的 祭 司 、 首 领 要 一 同 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20132', '24', '49', '4', '背 道 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 你 们 为 何 因 有 山 谷 ， 就 是 水 流 的 山 谷 夸 张 呢 ？ 为 何 倚 靠 财 宝 说 ： 谁 能 来 到 我 们 这 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20133', '24', '49', '5', '主 ─ ─ 万 军 之 耶 和 华 说 ： 我 要 使 恐 吓 从 四 围 的 人 中 临 到 你 们 ； 你 们 必 被 赶 出 ， 各 人 一 直 前 往 ， 没 有 人 收 聚 逃 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20134', '24', '49', '6', '后 来 我 还 要 使 被 掳 的 亚 扪 人 归 回 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20135', '24', '49', '7', '＜ 耶 和 华 审 判 以 东 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20136', '24', '49', '8', '底 但 的 居 民 哪 ， 要 转 身 逃 跑 ， 住 在 深 密 处 ； 因 为 我 向 以 扫 追 讨 的 时 候 ， 必 使 灾 殃 临 到 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20137', '24', '49', '9', '摘 葡 萄 的 若 来 到 他 那 里 ， 岂 不 剩 下 些 葡 萄 呢 ？ 盗 贼 若 夜 间 而 来 ， 岂 不 毁 坏 直 到 够 了 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20138', '24', '49', '10', '我 却 使 以 扫 赤 露 ， 显 出 他 的 隐 密 处 ； 他 不 能 自 藏 。 他 的 后 裔 、 弟 兄 、 邻 舍 尽 都 灭 绝 ； 他 也 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20139', '24', '49', '11', '你 撇 下 孤 儿 ， 我 必 保 全 他 们 的 命 ； 你 的 寡 妇 可 以 倚 靠 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20140', '24', '49', '12', '耶 和 华 如 此 说 ： “ 原 不 该 喝 那 杯 的 一 定 要 喝 。 你 能 尽 免 刑 罚 吗 ？ 你 必 不 能 免 ， 一 定 要 喝 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20141', '24', '49', '13', '耶 和 华 说 ： “ 我 指 着 自 己 起 誓 ， 波 斯 拉 必 令 人 惊 骇 、 羞 辱 、 咒 诅 ， 并 且 荒 凉 。 她 的 一 切 城 邑 必 变 为 永 远 的 荒 场 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20142', '24', '49', '14', '我 从 耶 和 华 那 里 听 见 信 息 ， 并 有 使 者 被 差 往 列 国 去 ， 说 ： 你 们 聚 集 来 攻 击 以 东 ， 要 起 来 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20143', '24', '49', '15', '我 使 你 在 列 国 中 为 最 小 ， 在 世 人 中 被 藐 视 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20144', '24', '49', '16', '住 在 山 穴 中 据 守 山 顶 的 啊 ， 论 到 你 的 威 吓 ， 你 因 心 中 的 狂 傲 自 欺 ； 你 虽 如 大 鹰 高 高 搭 窝 ， 我 却 从 那 里 拉 下 你 来 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20145', '24', '49', '17', '“ 以 东 必 令 人 惊 骇 ； 凡 经 过 的 人 就 受 惊 骇 ， 又 因 她 一 切 的 灾 祸 嗤 笑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20146', '24', '49', '18', '耶 和 华 说 ： 必 无 人 住 在 那 里 ， 也 无 人 在 其 中 寄 居 ， 要 像 所 多 玛 、 蛾 摩 拉 ， 和 邻 近 的 城 邑 倾 覆 的 时 候 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20147', '24', '49', '19', '仇 敌 必 像 狮 子 从 约 旦 河 边 的 丛 林 上 来 ， 攻 击 坚 固 的 居 所 。 转 眼 之 间 ， 我 要 使 以 东 人 逃 跑 ， 离 开 这 地 。 谁 蒙 拣 选 ， 我 就 派 谁 治 理 这 地 。 谁 能 比 我 呢 ？ 谁 能 给 我 定 规 日 期 呢 ？ 有 何 牧 人 能 在 我 面 前 站 立 得 住 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20148', '24', '49', '20', '你 们 要 听 耶 和 华 攻 击 以 东 所 说 的 谋 略 和 他 攻 击 提 幔 居 民 所 定 的 旨 意 。 仇 敌 定 要 将 他 们 群 众 微 弱 的 拉 去 ， 定 要 使 他 们 的 居 所 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20149', '24', '49', '21', '因 他 们 仆 倒 的 声 音 ， 地 就 震 动 。 人 在 红 海 那 里 必 听 见 呼 喊 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20150', '24', '49', '22', '仇 敌 必 如 大 鹰 飞 起 ， 展 开 翅 膀 攻 击 波 斯 拉 。 到 那 日 ， 以 东 的 勇 士 心 中 疼 痛 如 临 产 的 妇 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20151', '24', '49', '23', '＜ 耶 和 华 审 判 大 马 士 革 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20152', '24', '49', '24', '大 马 士 革 发 软 ， 转 身 逃 跑 。 战 兢 将 她 捉 住 ； 痛 苦 忧 愁 将 她 抓 住 ， 如 产 难 的 妇 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20153', '24', '49', '25', '我 所 喜 乐 可 称 赞 的 城 ， 为 何 被 撇 弃 了 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20154', '24', '49', '26', '她 的 少 年 人 必 仆 倒 在 街 上 ； 当 那 日 ， 一 切 兵 丁 必 默 默 无 声 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20155', '24', '49', '27', '我 必 在 大 马 士 革 城 中 使 火 着 起 ， 烧 灭 便 ． 哈 达 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20156', '24', '49', '28', '＜ 审 判 基 达 和 夏 琐 城 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20157', '24', '49', '29', '他 们 的 帐 棚 和 羊 群 都 要 夺 去 ， 将 幔 子 和 一 切 器 皿 ， 并 骆 驼 为 自 己 掠 去 。 人 向 他 们 喊 着 说 ： 四 围 都 有 惊 吓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20158', '24', '49', '30', '耶 和 华 说 ： 夏 琐 的 居 民 哪 ， 要 逃 奔 远 方 ， 住 在 深 密 处 ； 因 为 巴 比 伦 王 尼 布 甲 尼 撒 设 计 谋 害 你 们 ， 起 意 攻 击 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20159', '24', '49', '31', '耶 和 华 说 ： 迦 勒 底 人 哪 ， 起 来 ！ 上 安 逸 无 虑 的 居 民 那 里 去 ； 他 们 是 无 门 无 闩 、 独 自 居 住 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20160', '24', '49', '32', '他 们 的 骆 驼 必 成 为 掠 物 ； 他 们 众 多 的 牲 畜 必 成 为 掳 物 。 我 必 将 剃 周 围 头 发 的 人 分 散 四 方 ｛ 原 文 是 风 ｝ ， 使 灾 殃 从 四 围 临 到 他 们 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20161', '24', '49', '33', '夏 琐 必 成 为 野 狗 的 住 处 ， 永 远 凄 凉 ； 必 无 人 住 在 那 里 ， 也 无 人 在 其 中 寄 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20162', '24', '49', '34', '＜ 耶 和 华 审 判 以 拦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20163', '24', '49', '35', '“ 万 军 之 耶 和 华 如 此 说 ： 我 必 折 断 以 拦 人 的 弓 ， 就 是 他 们 为 首 的 权 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20164', '24', '49', '36', '我 要 使 四 风 从 天 的 四 方 刮 来 ， 临 到 以 拦 人 ， 将 他 们 分 散 四 方 ｛ 原 文 是 风 ｝ 。 这 被 赶 散 的 人 没 有 一 国 不 到 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20165', '24', '49', '37', '耶 和 华 说 ： “ 我 必 使 以 拦 人 在 仇 敌 和 寻 索 其 命 的 人 面 前 惊 惶 ； 我 也 必 使 灾 祸 ， 就 是 我 的 烈 怒 临 到 他 们 ， 又 必 使 刀 剑 追 杀 他 们 ， 直 到 将 他 们 灭 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20166', '24', '49', '38', '我 要 在 以 拦 设 立 我 的 宝 座 ， 从 那 里 除 灭 君 王 和 首 领 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20167', '24', '49', '39', '“ 到 末 后 ， 我 还 要 使 被 掳 的 以 拦 人 归 回 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20168', '24', '50', '1', '＜ 巴 比 伦 被 占 领 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20169', '24', '50', '2', '你 们 要 在 万 国 中 传 扬 报 告 ， 竖 立 大 旗 ； 要 报 告 ， 不 可 隐 瞒 ， 说 ： 巴 比 伦 被 攻 取 ， 彼 勒 蒙 羞 ， 米 罗 达 惊 惶 。 巴 比 伦 的 神 像 都 蒙 羞 ； 她 的 偶 像 都 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20170', '24', '50', '3', '“ 因 有 一 国 从 北 方 上 来 攻 击 她 ， 使 她 的 地 荒 凉 ， 无 人 居 住 ， 连 人 带 牲 畜 都 逃 走 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20171', '24', '50', '4', '＜ 以 色 列 人 还 乡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20172', '24', '50', '5', '他 们 必 访 问 锡 安 ， 又 面 向 这 里 ， 说 ： ‘ 来 吧 ， 你 们 要 与 耶 和 华 联 合 为 永 远 不 忘 的 约 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20173', '24', '50', '6', '“ 我 的 百 姓 作 了 迷 失 的 羊 ， 牧 人 使 他 们 走 差 路 ， 使 他 们 转 到 山 上 。 他 们 从 大 山 走 到 小 山 ， 竟 忘 了 安 歇 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20174', '24', '50', '7', '凡 遇 见 他 们 的 ， 就 把 他 们 吞 灭 。 敌 人 说 ： ‘ 我 们 没 有 罪 ； 因 他 们 得 罪 那 作 公 义 居 所 的 耶 和 华 ， 就 是 他 们 列 祖 所 仰 望 的 耶 和 华 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20175', '24', '50', '8', '“ 我 民 哪 ， 你 们 要 从 巴 比 伦 中 逃 走 ， 从 迦 勒 底 人 之 地 出 去 ， 要 像 羊 群 前 面 走 的 公 山 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20176', '24', '50', '9', '因 我 必 激 动 联 合 的 大 国 从 北 方 上 来 攻 击 巴 比 伦 ， 他 们 要 摆 阵 攻 击 她 ； 她 必 从 那 里 被 攻 取 。 他 们 的 箭 好 像 善 射 之 勇 士 的 箭 ， 一 枝 也 不 徒 然 返 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20177', '24', '50', '10', '迦 勒 底 必 成 为 掠 物 ； 凡 掳 掠 她 的 都 必 心 满 意 足 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20178', '24', '50', '11', '＜ 巴 比 伦 陷 落 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20179', '24', '50', '12', '你 们 的 母 巴 比 伦 就 极 其 抱 愧 ， 生 你 们 的 必 然 蒙 羞 。 她 要 列 在 诸 国 之 末 ， 成 为 旷 野 、 旱 地 、 沙 漠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20180', '24', '50', '13', '因 耶 和 华 的 忿 怒 ， 必 无 人 居 住 ， 要 全 然 荒 凉 。 凡 经 过 巴 比 伦 的 要 受 惊 骇 ， 又 因 她 所 遭 的 灾 殃 嗤 笑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20181', '24', '50', '14', '所 有 拉 弓 的 ， 你 们 要 在 巴 比 伦 的 四 围 摆 阵 ， 射 箭 攻 击 她 。 不 要 爱 惜 箭 枝 ， 因 她 得 罪 了 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20182', '24', '50', '15', '你 们 要 在 她 四 围 呐 喊 ； 她 已 经 投 降 。 外 郭 坍 塌 了 ， 城 墙 拆 毁 了 ， 因 为 这 是 耶 和 华 报 仇 的 事 。 你 们 要 向 巴 比 伦 报 仇 ； 她 怎 样 待 人 ， 也 要 怎 样 待 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20183', '24', '50', '16', '你 们 要 将 巴 比 伦 撒 种 的 和 收 割 时 拿 镰 刀 的 都 剪 除 了 。 他 们 各 人 因 怕 欺 压 的 刀 剑 ， 必 归 回 本 族 ， 逃 到 本 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20184', '24', '50', '17', '＜ 以 色 列 人 还 乡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20185', '24', '50', '18', '所 以 万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： “ 我 必 罚 巴 比 伦 王 和 他 的 地 ， 像 我 从 前 罚 亚 述 王 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20186', '24', '50', '19', '我 必 再 领 以 色 列 回 他 的 草 场 ， 他 必 在 迦 密 和 巴 珊 吃 草 ， 又 在 以 法 莲 山 上 和 基 列 境 内 得 以 饱 足 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20187', '24', '50', '20', '耶 和 华 说 ： “ 当 那 日 子 、 那 时 候 ， 虽 寻 以 色 列 的 罪 孽 ， 一 无 所 有 ； 虽 寻 犹 大 的 罪 恶 ， 也 无 所 见 ； 因 为 我 所 留 下 的 人 ， 我 必 赦 免 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20188', '24', '50', '21', '＜ 神 审 判 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20189', '24', '50', '22', '境 内 有 打 仗 和 大 毁 灭 的 响 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20190', '24', '50', '23', '全 地 的 大 锤 何 竟 砍 断 破 坏 ？ 巴 比 伦 在 列 国 中 何 竟 荒 凉 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20191', '24', '50', '24', '巴 比 伦 哪 ， 我 为 你 设 下 网 罗 ， 你 不 知 不 觉 被 缠 住 。 你 被 寻 着 ， 也 被 捉 住 ； 因 为 你 与 耶 和 华 争 竞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20192', '24', '50', '25', '耶 和 华 已 经 开 了 武 库 ， 拿 出 他 恼 恨 的 兵 器 ； 因 为 主 ─ ─ 万 军 之 耶 和 华 在 迦 勒 底 人 之 地 有 当 做 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20193', '24', '50', '26', '你 们 要 从 极 远 的 边 界 来 攻 击 她 ， 开 她 的 仓 廪 ， 将 她 堆 如 高 堆 ， 毁 灭 净 尽 ， 丝 毫 不 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20194', '24', '50', '27', '要 杀 她 的 一 切 牛 犊 ， 使 他 们 下 去 遭 遇 杀 戮 。 他 们 有 祸 了 ， 因 为 追 讨 他 们 的 日 子 已 经 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20195', '24', '50', '28', '（ 有 从 巴 比 伦 之 地 逃 避 出 来 的 人 ， 在 锡 安 扬 声 报 告 耶 和 华 ─ ─ 我 们 的 神 报 仇 ， 就 是 为 他 的 殿 报 仇 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20196', '24', '50', '29', '“ 招 集 一 切 弓 箭 手 来 攻 击 巴 比 伦 。 要 在 巴 比 伦 四 围 安 营 ， 不 要 容 一 人 逃 脱 ， 照 着 她 所 做 的 报 应 她 ； 他 怎 样 待 人 ， 也 要 怎 样 待 她 ， 因 为 她 向 耶 和 华 ─ ─ 以 色 列 的 圣 者 发 了 狂 傲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20197', '24', '50', '30', '所 以 她 的 少 年 人 必 仆 倒 在 街 上 。 当 那 日 ， 一 切 兵 丁 必 默 默 无 声 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20198', '24', '50', '31', '主 ─ ─ 万 军 之 耶 和 华 说 ： 你 这 狂 傲 的 啊 ， 我 与 你 反 对 ， 因 为 我 追 讨 你 的 日 子 已 经 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20199', '24', '50', '32', '狂 傲 的 必 绊 跌 仆 倒 ， 无 人 扶 起 。 我 也 必 使 火 在 他 的 城 邑 中 着 起 来 ， 将 他 四 围 所 有 的 尽 行 烧 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20200', '24', '50', '33', '万 军 之 耶 和 华 如 此 说 ： “ 以 色 列 人 和 犹 大 人 一 同 受 欺 压 ； 凡 掳 掠 他 们 的 都 紧 紧 抓 住 他 们 ， 不 肯 释 放 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20201', '24', '50', '34', '他 们 的 救 赎 主 大 有 能 力 ， 万 军 之 耶 和 华 是 他 的 名 。 他 必 伸 清 他 们 的 冤 ， 好 使 全 地 得 平 安 ， 并 搅 扰 巴 比 伦 的 居 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20202', '24', '50', '35', '耶 和 华 说 ： 有 刀 剑 临 到 迦 勒 底 人 和 巴 比 伦 的 居 民 ， 并 她 的 首 领 与 智 慧 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20203', '24', '50', '36', '有 刀 剑 临 到 矜 夸 的 人 ， 他 们 就 成 为 愚 昧 ； 有 刀 剑 临 到 她 的 勇 士 ， 他 们 就 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20204', '24', '50', '37', '有 刀 剑 临 到 她 的 马 匹 、 车 辆 ， 和 其 中 杂 族 的 人 民 ； 他 们 必 像 妇 女 一 样 。 有 刀 剑 临 到 她 的 宝 物 ， 就 被 抢 夺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20205', '24', '50', '38', '有 干 旱 临 到 她 的 众 水 ， 就 必 干 涸 ； 因 为 这 是 有 雕 刻 偶 像 之 地 ， 人 因 偶 像 而 颠 狂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20206', '24', '50', '39', '所 以 旷 野 的 走 兽 和 豺 狼 必 住 在 那 里 ， 鸵 鸟 也 住 在 其 中 ， 永 无 人 烟 ， 世 世 代 代 无 人 居 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20207', '24', '50', '40', '耶 和 华 说 ： “ 必 无 人 住 在 那 里 ， 也 无 人 在 其 中 寄 居 ， 要 像 我 倾 覆 所 多 玛 、 蛾 摩 拉 ， 和 邻 近 的 城 邑 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20208', '24', '50', '41', '看 哪 ， 有 一 种 民 从 北 方 而 来 ， 并 有 一 大 国 和 许 多 君 王 被 激 动 ， 从 地 极 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20209', '24', '50', '42', '他 们 拿 弓 和 枪 ， 性 情 残 忍 ， 不 施 怜 悯 ； 他 们 的 声 音 像 海 浪 匉 訇 。 巴 比 伦 城 ｛ 原 文 是 女 子 ｝ 啊 ， 他 们 骑 马 ， 都 摆 队 伍 如 上 战 场 的 人 ， 要 攻 击 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20210', '24', '50', '43', '巴 比 伦 王 听 见 他 们 的 风 声 ， 手 就 发 软 ， 痛 苦 将 他 抓 住 ， 疼 痛 仿 佛 产 难 的 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20211', '24', '50', '44', '“ 仇 敌 必 像 狮 子 从 约 旦 河 边 的 丛 林 上 来 ， 攻 击 坚 固 的 居 所 。 转 眼 之 间 ， 我 要 使 他 们 逃 跑 ， 离 开 这 地 。 谁 蒙 拣 选 ， 我 就 派 谁 治 理 这 地 。 谁 能 比 我 呢 ？ 谁 能 给 我 定 规 日 期 呢 ？ 有 何 牧 人 能 在 我 面 前 站 立 得 住 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20212', '24', '50', '45', '你 们 要 听 耶 和 华 攻 击 巴 比 伦 所 说 的 谋 略 和 他 攻 击 迦 勒 底 人 之 地 所 定 的 旨 意 。 仇 敌 定 要 将 他 们 群 众 微 弱 的 拉 去 ， 定 要 使 他 们 的 居 所 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20213', '24', '50', '46', '因 巴 比 伦 被 取 的 声 音 ， 地 就 震 动 ， 人 在 列 邦 都 听 见 呼 喊 的 声 音 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20214', '24', '51', '1', '＜ 再 审 判 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20215', '24', '51', '2', '我 要 打 发 外 邦 人 来 到 巴 比 伦 ， 簸 扬 她 ， 使 她 的 地 空 虚 。 在 她 遭 祸 的 日 子 ， 他 们 要 周 围 攻 击 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20216', '24', '51', '3', '拉 弓 的 ， 要 向 拉 弓 的 和 贯 甲 挺 身 的 射 箭 。 不 要 怜 惜 她 的 少 年 人 ； 要 灭 尽 她 的 全 军 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20217', '24', '51', '4', '他 们 必 在 迦 勒 底 人 之 地 被 杀 仆 倒 ， 在 巴 比 伦 的 街 上 被 刺 透 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20218', '24', '51', '5', '以 色 列 和 犹 大 虽 然 境 内 充 满 违 背 以 色 列 圣 者 的 罪 ， 却 没 有 被 他 的 神 ─ ─ 万 军 之 耶 和 华 丢 弃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20219', '24', '51', '6', '你 们 要 从 巴 比 伦 中 逃 奔 ， 各 救 自 己 的 性 命 ！ 不 要 陷 在 她 的 罪 孽 中 一 同 灭 亡 ； 因 为 这 是 耶 和 华 报 仇 的 时 候 ， 他 必 向 巴 比 伦 施 行 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20220', '24', '51', '7', '巴 比 伦 素 来 是 耶 和 华 手 中 的 金 杯 ， 使 天 下 沉 醉 ； 万 国 喝 了 她 的 酒 就 颠 狂 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20221', '24', '51', '8', '巴 比 伦 忽 然 倾 覆 毁 坏 ； 要 为 她 哀 号 ； 为 止 她 的 疼 痛 ， 拿 乳 香 或 者 可 以 治 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20222', '24', '51', '9', '我 们 想 医 治 巴 比 伦 ， 她 却 没 有 治 好 。 离 开 她 吧 ！ 我 们 各 人 归 回 本 国 ； 因 为 她 受 的 审 判 通 于 上 天 ， 达 到 穹 苍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20223', '24', '51', '10', '耶 和 华 已 经 彰 显 我 们 的 公 义 。 来 吧 ！ 我 们 可 以 在 锡 安 报 告 耶 和 华 ─ ─ 我 们 神 的 作 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20224', '24', '51', '11', '你 们 要 磨 尖 了 箭 头 ， 抓 住 盾 牌 。 耶 和 华 定 意 攻 击 巴 比 伦 ， 将 她 毁 灭 ， 所 以 激 动 了 米 底 亚 君 王 的 心 ； 因 这 是 耶 和 华 报 仇 ， 就 是 为 自 己 的 殿 报 仇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20225', '24', '51', '12', '你 们 要 竖 立 大 旗 ， 攻 击 巴 比 伦 的 城 墙 ； 要 坚 固 了 望 台 ， 派 定 守 望 的 设 下 埋 伏 ； 因 为 耶 和 华 指 着 巴 比 伦 居 民 所 说 的 话 、 所 定 的 意 ， 他 已 经 作 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20226', '24', '51', '13', '住 在 众 水 之 上 多 有 财 宝 的 啊 ， 你 的 结 局 到 了 ！ 你 贪 婪 之 量 满 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20227', '24', '51', '14', '万 军 之 耶 和 华 指 着 自 己 起 誓 说 ： 我 必 使 敌 人 充 满 你 ， 像 蚂 蚱 一 样 ； 他 们 必 呐 喊 攻 击 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20228', '24', '51', '15', '＜ 颂 赞 神 的 诗 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20229', '24', '51', '16', '他 一 发 声 ， 空 中 便 有 多 水 激 动 ； 他 使 云 雾 从 地 极 上 腾 。 他 造 电 随 雨 而 闪 ， 从 他 府 库 中 带 出 风 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20230', '24', '51', '17', '各 人 都 成 了 畜 类 ， 毫 无 知 识 。 各 银 匠 都 因 他 的 偶 像 羞 愧 ； 他 所 铸 的 偶 像 本 是 虚 假 的 ， 其 中 并 无 气 息 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20231', '24', '51', '18', '都 是 虚 无 的 ， 是 迷 惑 人 的 工 作 ， 到 追 讨 的 时 候 ， 必 被 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20232', '24', '51', '19', '雅 各 的 分 不 像 这 些 ， 因 他 是 造 作 万 有 的 主 ； 以 色 列 也 是 他 产 业 的 支 派 。 万 军 之 耶 和 华 是 他 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20233', '24', '51', '20', '＜ 耶 和 华 的 铁 锤 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20234', '24', '51', '21', '用 你 打 碎 马 和 骑 马 的 ； 用 你 打 碎 战 车 和 坐 在 其 上 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20235', '24', '51', '22', '用 你 打 碎 男 人 和 女 人 ； 用 你 打 碎 老 年 人 和 少 年 人 ； 用 你 打 碎 壮 丁 和 处 女 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20236', '24', '51', '23', '用 你 打 碎 牧 人 和 他 的 群 畜 ； 用 你 打 碎 农 夫 和 他 一 对 牛 ； 用 你 打 碎 省 长 和 副 省 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20237', '24', '51', '24', '＜ 惩 罚 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20238', '24', '51', '25', '耶 和 华 说 ： 你 这 行 毁 灭 的 山 哪 ， 就 是 毁 灭 天 下 的 山 ， 我 与 你 反 对 。 我 必 向 你 伸 手 ， 将 你 从 山 岩 滚 下 去 ， 使 你 成 为 烧 毁 的 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20239', '24', '51', '26', '人 必 不 从 你 那 里 取 石 头 为 房 角 石 ， 也 不 取 石 头 为 根 基 石 ； 你 必 永 远 荒 凉 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20240', '24', '51', '27', '要 在 境 内 竖 立 大 旗 ， 在 各 国 中 吹 角 ， 使 列 国 预 备 攻 击 巴 比 伦 ， 将 亚 拉 腊 、 米 尼 、 亚 实 基 拿 各 国 招 来 攻 击 她 ； 又 派 军 长 来 攻 击 她 ， 使 马 匹 上 来 如 蚂 蚱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20241', '24', '51', '28', '使 列 国 和 米 底 亚 君 王 ， 与 省 长 和 副 省 长 ， 并 他 们 所 管 全 地 之 人 ， 都 预 备 攻 击 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20242', '24', '51', '29', '地 必 震 动 而 瘠 苦 ； 因 耶 和 华 向 巴 比 伦 所 定 的 旨 意 成 立 了 ， 使 巴 比 伦 之 地 荒 凉 ， 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20243', '24', '51', '30', '巴 比 伦 的 勇 士 止 息 争 战 ， 藏 在 坚 垒 之 中 。 他 们 的 勇 力 衰 尽 ， 好 像 妇 女 一 样 。 巴 比 伦 的 住 处 有 火 着 起 ， 门 闩 都 折 断 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20244', '24', '51', '31', '跑 报 的 要 彼 此 相 遇 ， 送 信 的 要 互 相 迎 接 ， 报 告 巴 比 伦 王 说 ： 城 的 四 方 被 攻 取 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20245', '24', '51', '32', '渡 口 被 占 据 了 ， 苇 塘 被 火 烧 了 ， 兵 丁 也 惊 慌 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20246', '24', '51', '33', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 如 此 说 ： 巴 比 伦 城 ｛ 原 文 是 女 子 ｝ 好 像 踹 谷 的 禾 场 ； 再 过 片 时 ， 收 割 她 的 时 候 就 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20247', '24', '51', '34', '以 色 列 人 说 ： 巴 比 伦 王 尼 布 甲 尼 撒 吞 灭 我 ， 压 碎 我 ， 使 我 成 为 空 虚 的 器 皿 。 他 像 大 鱼 将 我 吞 下 ， 用 我 的 美 物 充 满 他 的 肚 腹 ， 又 将 我 赶 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20248', '24', '51', '35', '锡 安 的 居 民 要 说 ： 巴 比 伦 以 强 暴 待 我 ， 损 害 我 的 身 体 ， 愿 这 罪 归 给 她 。 耶 路 撒 冷 人 要 说 ： 愿 流 我 们 血 的 罪 归 到 迦 勒 底 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20249', '24', '51', '36', '＜ 耶 和 华 要 帮 助 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20250', '24', '51', '37', '巴 比 伦 必 成 为 乱 堆 ， 为 野 狗 的 住 处 ， 令 人 惊 骇 、 嗤 笑 ， 并 且 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20251', '24', '51', '38', '他 们 要 像 少 壮 狮 子 咆 哮 ， 像 小 狮 子 吼 叫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20252', '24', '51', '39', '他 们 火 热 的 时 候 ， 我 必 为 他 们 设 摆 酒 席 ， 使 他 们 沉 醉 ， 好 叫 他 们 快 乐 ， 睡 了 长 觉 ， 永 不 醒 起 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20253', '24', '51', '40', '我 必 使 他 们 像 羊 羔 、 像 公 绵 羊 和 公 山 羊 下 到 宰 杀 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20254', '24', '51', '41', '＜ 巴 比 伦 的 命 运 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20255', '24', '51', '42', '海 水 涨 起 ， 漫 过 巴 比 伦 ； 她 被 许 多 海 浪 遮 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20256', '24', '51', '43', '她 的 城 邑 变 为 荒 场 、 旱 地 、 沙 漠 ， 无 人 居 住 ， 无 人 经 过 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20257', '24', '51', '44', '我 必 刑 罚 巴 比 伦 的 彼 勒 ， 使 他 吐 出 所 吞 的 。 万 民 必 不 再 流 归 他 那 里 ； 巴 比 伦 的 城 墙 也 必 坍 塌 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20258', '24', '51', '45', '我 的 民 哪 ， 你 们 要 从 其 中 出 去 ！ 各 人 拯 救 自 己 ， 躲 避 耶 和 华 的 烈 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20259', '24', '51', '46', '你 们 不 要 心 惊 胆 怯 ， 也 不 要 因 境 内 所 听 见 的 风 声 惧 怕 ； 因 为 这 年 有 风 声 传 来 ； 那 年 也 有 风 声 传 来 ， 境 内 有 强 暴 的 事 ， 官 长 攻 击 官 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20260', '24', '51', '47', '日 子 将 到 ， 我 必 刑 罚 巴 比 伦 雕 刻 的 偶 像 。 她 全 地 必 然 抱 愧 ； 她 被 杀 的 人 必 在 其 中 仆 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20261', '24', '51', '48', '那 时 ， 天 地 和 其 中 所 有 的 ， 必 因 巴 比 伦 欢 呼 ， 因 为 行 毁 灭 的 要 从 北 方 来 到 她 那 里 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20262', '24', '51', '49', '巴 比 伦 怎 样 使 以 色 列 被 杀 的 人 仆 倒 ， 照 样 她 全 地 被 杀 的 人 也 必 在 巴 比 伦 仆 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20263', '24', '51', '50', '＜ 给 在 巴 比 伦 的 以 色 列 人 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20264', '24', '51', '51', '我 们 听 见 辱 骂 就 蒙 羞 ， 满 面 惭 愧 ， 因 为 外 邦 人 进 入 耶 和 华 殿 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20265', '24', '51', '52', '耶 和 华 说 ： 日 子 将 到 ， 我 必 刑 罚 巴 比 伦 雕 刻 的 偶 像 ， 通 国 受 伤 的 人 必 唉 哼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20266', '24', '51', '53', '巴 比 伦 虽 升 到 天 上 ， 虽 使 她 坚 固 的 高 处 更 坚 固 ， 还 有 行 毁 灭 的 从 我 这 里 到 她 那 里 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20267', '24', '51', '54', '＜ 巴 比 伦 灭 亡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20268', '24', '51', '55', '因 耶 和 华 使 巴 比 伦 变 为 荒 场 ， 使 其 中 的 大 声 灭 绝 。 仇 敌 仿 佛 众 水 ， 波 浪 匉 訇 ， 响 声 已 经 发 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20269', '24', '51', '56', '这 是 行 毁 灭 的 临 到 巴 比 伦 。 巴 比 伦 的 勇 士 被 捉 住 ， 他 们 的 弓 折 断 了 ； 因 为 耶 和 华 是 施 行 报 应 的 神 ， 必 定 施 行 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20270', '24', '51', '57', '君 王 ─ ─ 名 为 万 军 之 耶 和 华 的 说 ： 我 必 使 巴 比 伦 的 首 领 、 智 慧 人 、 省 长 、 副 省 长 ， 和 勇 士 都 沉 醉 ， 使 他 们 睡 了 长 觉 ， 永 不 醒 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20271', '24', '51', '58', '万 军 之 耶 和 华 如 此 说 ： 巴 比 伦 宽 阔 的 城 墙 必 全 然 倾 倒 ； 她 高 大 的 城 门 必 被 火 焚 烧 。 众 民 所 劳 碌 的 必 致 虚 空 ； 列 国 所 劳 碌 的 被 火 焚 烧 ， 他 们 都 必 困 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20272', '24', '51', '59', '＜ 耶 利 米 的 信 息 传 到 巴 比 伦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20273', '24', '51', '60', '耶 利 米 将 一 切 要 临 到 巴 比 伦 的 灾 祸 ， 就 是 论 到 巴 比 伦 的 一 切 话 ， 写 在 书 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20274', '24', '51', '61', '耶 利 米 对 西 莱 雅 说 ： “ 你 到 了 巴 比 伦 务 要 念 这 书 上 的 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20275', '24', '51', '62', '又 说 ： ‘ 耶 和 华 啊 ， 你 曾 论 到 这 地 方 说 ： 要 剪 除 ， 甚 至 连 人 带 牲 畜 没 有 在 这 里 居 住 的 ， 必 永 远 荒 凉 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20276', '24', '51', '63', '你 念 完 了 这 书 ， 就 把 一 块 石 头 拴 在 书 上 ， 扔 在 幼 发 拉 底 河 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20277', '24', '51', '64', '说 ： ‘ 巴 比 伦 因 耶 和 华 所 要 降 与 她 的 灾 祸 ， 必 如 此 沉 下 去 ， 不 再 兴 起 ， 人 民 也 必 困 乏 。 ’ 耶 利 米 的 话 到 此 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20278', '24', '52', '1', '＜ 耶 路 撒 冷 的 陷 落 （ 王 下   2 4 : 1 8 - 2 5 : 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20279', '24', '52', '2', '西 底 家 行 耶 和 华 眼 中 看 为 恶 的 事 ， 是 照 约 雅 敬 一 切 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20280', '24', '52', '3', '因 此 耶 和 华 的 怒 气 在 耶 路 撒 冷 和 犹 大 发 作 ， 以 致 将 人 民 从 自 己 的 面 前 赶 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20281', '24', '52', '4', '西 底 家 背 叛 巴 比 伦 王 。 他 作 王 第 九 年 十 月 初 十 日 ， 巴 比 伦 王 尼 布 甲 尼 撒 率 领 全 军 来 攻 击 耶 路 撒 冷 ， 对 城 安 营 ， 四 围 筑 垒 攻 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20282', '24', '52', '5', '于 是 城 被 围 困 直 到 西 底 家 王 十 一 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20283', '24', '52', '6', '四 月 初 九 日 ， 城 里 有 大 饥 荒 ， 甚 至 百 姓 都 没 有 粮 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20284', '24', '52', '7', '城 被 攻 破 ， 一 切 兵 丁 就 在 夜 间 从 靠 近 王 园 两 城 中 间 的 门 ， 出 城 逃 跑 ； 迦 勒 底 人 正 在 四 围 攻 城 。 他 们 就 往 亚 拉 巴 逃 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20285', '24', '52', '8', '迦 勒 底 的 军 队 追 赶 西 底 家 王 ， 在 耶 利 哥 的 平 原 追 上 他 。 他 的 全 军 都 离 开 他 四 散 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20286', '24', '52', '9', '迦 勒 底 人 就 拿 住 王 ， 带 他 到 在 哈 马 地 利 比 拉 的 巴 比 伦 王 那 里 ； 巴 比 伦 王 便 审 判 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20287', '24', '52', '10', '巴 比 伦 王 在 西 底 家 眼 前 杀 了 他 的 众 子 ， 又 在 利 比 拉 杀 了 犹 大 的 一 切 首 领 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20288', '24', '52', '11', '并 且 剜 了 西 底 家 的 眼 睛 ， 用 铜 链 锁 着 他 ， 带 到 巴 比 伦 去 ， 将 他 囚 在 监 里 ， 直 到 他 死 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20289', '24', '52', '12', '＜ 圣 殿 毁 灭 （ 王 下   2 5 : 8 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20290', '24', '52', '13', '用 火 焚 烧 耶 和 华 的 殿 和 王 宫 ， 又 焚 烧 耶 路 撒 冷 的 房 屋 ， 就 是 各 大 户 家 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20291', '24', '52', '14', '跟 从 护 卫 长 迦 勒 底 的 全 军 就 拆 毁 耶 路 撒 冷 四 围 的 城 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20292', '24', '52', '15', '那 时 护 卫 长 尼 布 撒 拉 旦 将 民 中 最 穷 的 和 城 里 所 剩 下 的 百 姓 ， 并 已 经 投 降 巴 比 伦 王 的 人 ， 以 及 大 众 所 剩 下 的 人 ， 都 掳 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20293', '24', '52', '16', '但 护 卫 长 尼 布 撒 拉 旦 留 下 些 民 中 最 穷 的 ， 使 他 们 修 理 葡 萄 园 ， 耕 种 田 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20294', '24', '52', '17', '耶 和 华 殿 的 铜 柱 并 殿 内 的 盆 座 和 铜 海 ， 迦 勒 底 人 都 打 碎 了 ， 将 那 铜 运 到 巴 比 伦 去 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20295', '24', '52', '18', '又 带 去 锅 、 铲 子 、 蜡 剪 、 盘 子 、 调 羹 ， 并 所 用 的 一 切 铜 器 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20296', '24', '52', '19', '杯 、 火 鼎 、 碗 、 盆 、 灯 台 、 调 羹 、 爵 ， 无 论 金 的 银 的 ， 护 卫 长 也 都 带 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20297', '24', '52', '20', '所 罗 门 为 耶 和 华 殿 所 造 的 两 根 铜 柱 、 一 个 铜 海 ， 并 座 下 的 十 二 只 铜 牛 ， 这 一 切 的 铜 多 得 无 法 可 称 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20298', '24', '52', '21', '这 一 根 柱 子 高 十 八 肘 ， 厚 四 指 ， 是 空 的 ， 围 十 二 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20299', '24', '52', '22', '柱 上 有 铜 顶 ， 高 五 肘 ； 铜 顶 的 周 围 有 网 子 和 石 榴 ， 都 是 铜 的 。 那 一 根 柱 子 照 此 一 样 ， 也 有 石 榴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20300', '24', '52', '23', '柱 子 四 面 有 九 十 六 个 石 榴 ， 在 网 子 周 围 ， 共 有 一 百 石 榴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20301', '24', '52', '24', '＜ 以 色 列 人 被 掳 到 巴 比 伦 （ 王 下   2 5 : 1 8 - 2 1 ； 2 5 : 2 7 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20302', '24', '52', '25', '又 从 城 中 拿 住 一 个 管 理 兵 丁 的 官 ｛ 或 译 ： 太 监 ｝ ， 并 在 城 里 所 遇 常 见 王 面 的 七 个 人 和 检 点 国 民 军 长 的 书 记 ， 以 及 城 里 所 遇 见 的 国 民 六 十 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20303', '24', '52', '26', '护 卫 长 尼 布 撒 拉 旦 将 这 些 人 带 到 利 比 拉 的 巴 比 伦 王 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20304', '24', '52', '27', '巴 比 伦 王 就 把 他 们 击 杀 在 哈 马 地 的 利 比 拉 。 这 样 ， 犹 大 人 被 掳 去 离 开 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20305', '24', '52', '28', '尼 布 甲 尼 撒 所 掳 的 民 数 记 在 下 面 ： 在 他 第 七 年 掳 去 犹 大 人 三 千 零 二 十 三 名 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20306', '24', '52', '29', '尼 布 甲 尼 撒 十 八 年 从 耶 路 撒 冷 掳 去 八 百 三 十 二 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20307', '24', '52', '30', '尼 布 甲 尼 撒 二 十 三 年 ， 护 卫 长 尼 布 撒 拉 旦 掳 去 犹 大 人 七 百 四 十 五 名 ； 共 有 四 千 六 百 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20308', '24', '52', '31', '犹 大 王 约 雅 斤 被 掳 后 三 十 七 年 ， 巴 比 伦 王 以 未 ． 米 罗 达 元 年 十 二 月 二 十 五 日 ， 使 犹 大 王 约 雅 斤 抬 头 ， 提 他 出 监 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20309', '24', '52', '32', '又 对 他 说 恩 言 ， 使 他 的 位 高 过 与 他 一 同 在 巴 比 伦 众 王 的 位 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20310', '24', '52', '33', '给 他 脱 了 囚 服 。 他 终 身 在 巴 比 伦 王 面 前 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20311', '24', '52', '34', '巴 比 伦 王 赐 他 所 需 用 的 食 物 ， 日 日 赐 他 一 分 ， 终 身 是 这 样 ， 直 到 他 死 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20312', '25', '1', '1', '＜ 耶 路 撒 冷 的 忧 患 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20313', '25', '1', '2', '她 夜 间 痛 哭 ， 泪 流 满 腮 ； 在 一 切 所 亲 爱 的 中 间 没 有 一 个 安 慰 她 的 。 她 的 朋 友 都 以 诡 诈 待 她 ， 成 为 她 的 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20314', '25', '1', '3', '犹 大 因 遭 遇 苦 难 ， 又 因 多 服 劳 苦 就 迁 到 外 邦 。 她 住 在 列 国 中 ， 寻 不 着 安 息 ； 追 逼 她 的 都 在 狭 窄 之 地 将 她 追 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20315', '25', '1', '4', '锡 安 的 路 径 因 无 人 来 守 圣 节 就 悲 伤 ； 她 的 城 门 凄 凉 ； 她 的 祭 司 叹 息 ； 她 的 处 女 受 艰 难 ， 自 己 也 愁 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20316', '25', '1', '5', '她 的 敌 人 为 首 ； 她 的 仇 敌 亨 通 ； 因 耶 和 华 为 她 许 多 的 罪 过 使 她 受 苦 ； 她 的 孩 童 被 敌 人 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20317', '25', '1', '6', '锡 安 城 ｛ 原 文 是 女 子 ； 下 同 ｝ 的 威 荣 全 都 失 去 。 她 的 首 领 像 找 不 着 草 场 的 鹿 ； 在 追 赶 的 人 前 无 力 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20318', '25', '1', '7', '耶 路 撒 冷 在 困 苦 窘 迫 之 时 ， 就 追 想 古 时 一 切 的 乐 境 。 她 百 姓 落 在 敌 人 手 中 ， 无 人 救 济 ； 敌 人 看 见 ， 就 因 她 的 荒 凉 嗤 笑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20319', '25', '1', '8', '耶 路 撒 冷 大 大 犯 罪 ， 所 以 成 为 不 洁 之 物 ； 素 来 尊 敬 她 的 ， 见 她 赤 露 就 都 藐 视 她 ； 她 自 己 也 叹 息 退 后 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20320', '25', '1', '9', '她 的 污 秽 是 在 衣 襟 上 ； 她 不 思 想 自 己 的 结 局 ， 所 以 非 常 地 败 落 ， 无 人 安 慰 她 。 她 说 ： 耶 和 华 啊 ， 求 你 看 我 的 苦 难 ， 因 为 仇 敌 夸 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20321', '25', '1', '10', '敌 人 伸 手 ， 夺 取 她 的 美 物 ； 她 眼 见 外 邦 人 进 入 她 的 圣 所 ─ ─ 论 这 外 邦 人 ， 你 曾 吩 咐 不 可 入 你 的 会 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20322', '25', '1', '11', '她 的 民 都 叹 息 ， 寻 求 食 物 ； 他 们 用 美 物 换 粮 食 ， 要 救 性 命 。 他 们 说 ： 耶 和 华 啊 ， 求 你 观 看 ， 因 为 我 甚 是 卑 贱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20323', '25', '1', '12', '你 们 一 切 过 路 的 人 哪 ， 这 事 你 们 不 介 意 吗 ？ 你 们 要 观 看 ： 有 像 这 临 到 我 的 痛 苦 没 有 ─ ─ 就 是 耶 和 华 在 他 发 烈 怒 的 日 子 使 我 所 受 的 苦 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20324', '25', '1', '13', '他 从 高 天 使 火 进 入 我 的 骨 头 ， 克 制 了 我 ； 他 铺 下 网 罗 ， 绊 我 的 脚 ， 使 我 转 回 ； 他 使 我 终 日 凄 凉 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20325', '25', '1', '14', '我 罪 过 的 轭 是 他 手 所 绑 的 ， 犹 如 轭 绳 缚 在 我 颈 项 上 ； 他 使 我 的 力 量 衰 败 。 主 将 我 交 在 我 所 不 能 敌 挡 的 人 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20326', '25', '1', '15', '主 轻 弃 我 中 间 的 一 切 勇 士 ， 招 聚 多 人 ｛ 原 文 是 大 会 ｝ 攻 击 我 ， 要 压 碎 我 的 少 年 人 。 主 将 犹 大 居 民 踹 下 ， 像 在 酒 醡 中 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20327', '25', '1', '16', '我 因 这 些 事 哭 泣 ； 我 眼 泪 汪 汪 ； 因 为 那 当 安 慰 我 、 救 我 性 命 的 ， 离 我 甚 远 。 我 的 儿 女 孤 苦 ， 因 为 仇 敌 得 了 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20328', '25', '1', '17', '锡 安 举 手 ， 无 人 安 慰 。 耶 和 华 论 雅 各 已 经 出 令 ， 使 四 围 的 人 作 他 仇 敌 ； 耶 路 撒 冷 在 他 们 中 间 像 不 洁 之 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20329', '25', '1', '18', '耶 和 华 是 公 义 的 ！ 他 这 样 待 我 ， 是 因 我 违 背 他 的 命 令 。 众 民 哪 ， 请 听 我 的 话 ， 看 我 的 痛 苦 ； 我 的 处 女 和 少 年 人 都 被 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20330', '25', '1', '19', '我 招 呼 我 所 亲 爱 的 ， 他 们 却 愚 弄 我 。 我 的 祭 司 和 长 老 正 寻 求 食 物 、 救 性 命 的 时 候 ， 就 在 城 中 绝 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20331', '25', '1', '20', '耶 和 华 啊 ， 求 你 观 看 ， 因 为 我 在 急 难 中 。 我 心 肠 扰 乱 ； 我 心 在 我 里 面 翻 转 ， 因 我 大 大 悖 逆 。 在 外 ， 刀 剑 使 人 丧 子 ； 在 家 ， 犹 如 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20332', '25', '1', '21', '听 见 我 叹 息 的 有 人 ； 安 慰 我 的 却 无 人 ！ 我 的 仇 敌 都 听 见 我 所 遭 的 患 难 ； 因 你 做 这 事 ， 他 们 都 喜 乐 。 你 必 使 你 报 告 的 日 子 来 到 ， 他 们 就 像 我 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20333', '25', '1', '22', '愿 他 们 的 恶 行 都 呈 在 你 面 前 ； 你 怎 样 因 我 的 一 切 罪 过 待 我 ， 求 你 照 样 待 他 们 ； 因 我 叹 息 甚 多 ， 心 中 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20334', '25', '2', '1', '＜ 耶 和 华 刑 罚 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20335', '25', '2', '2', '主 吞 灭 雅 各 一 切 的 住 处 ， 并 不 顾 惜 。 他 发 怒 倾 覆 犹 大 民 的 保 障 ， 使 这 保 障 坍 倒 在 地 ； 他 辱 没 这 国 和 其 中 的 首 领 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20336', '25', '2', '3', '他 发 烈 怒 ， 把 以 色 列 的 角 全 然 砍 断 ， 在 仇 敌 面 前 收 回 右 手 。 他 像 火 焰 四 围 吞 灭 ， 将 雅 各 烧 毁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20337', '25', '2', '4', '他 张 弓 好 像 仇 敌 ； 他 站 着 举 起 右 手 ， 如 同 敌 人 将 悦 人 眼 目 的 ， 尽 行 杀 戮 。 在 锡 安 百 姓 的 帐 棚 上 倒 出 他 的 忿 怒 ， 像 火 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20338', '25', '2', '5', '主 如 仇 敌 吞 灭 以 色 列 和 锡 安 的 一 切 宫 殿 ， 拆 毁 百 姓 的 保 障 ； 在 犹 大 民 中 加 增 悲 伤 哭 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20339', '25', '2', '6', '他 强 取 自 己 的 帐 幕 ， 好 像 是 园 中 的 窝 棚 ， 毁 坏 他 的 聚 会 之 处 。 耶 和 华 使 圣 节 和 安 息 日 在 锡 安 都 被 忘 记 ， 又 在 怒 气 的 愤 恨 中 藐 视 君 王 和 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20340', '25', '2', '7', '耶 和 华 丢 弃 自 己 的 祭 坛 ， 憎 恶 自 己 的 圣 所 ， 将 宫 殿 的 墙 垣 交 付 仇 敌 。 他 们 在 耶 和 华 的 殿 中 喧 嚷 ， 像 在 圣 会 之 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20341', '25', '2', '8', '耶 和 华 定 意 拆 毁 锡 安 的 城 墙 ； 他 拉 了 准 绳 ， 不 将 手 收 回 ， 定 要 毁 灭 。 他 使 外 郭 和 城 墙 都 悲 哀 ， 一 同 衰 败 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20342', '25', '2', '9', '锡 安 的 门 都 陷 入 地 内 ； 主 将 她 的 门 闩 毁 坏 ， 折 断 。 她 的 君 王 和 首 领 落 在 没 有 律 法 的 列 国 中 ； 她 的 先 知 不 得 见 耶 和 华 的 异 象 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20343', '25', '2', '10', '锡 安 城 的 长 老 坐 在 地 上 默 默 无 声 ； 他 们 扬 起 尘 土 落 在 头 上 ， 腰 束 麻 布 ； 耶 路 撒 冷 的 处 女 垂 头 至 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20344', '25', '2', '11', '我 眼 中 流 泪 ， 以 致 失 明 ； 我 的 心 肠 扰 乱 ， 肝 胆 涂 地 ， 都 因 我 众 民 遭 毁 灭 ， 又 因 孩 童 和 吃 奶 的 在 城 内 街 上 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20345', '25', '2', '12', '那 时 ， 他 们 在 城 内 街 上 发 昏 ， 好 像 受 伤 的 ， 在 母 亲 的 怀 里 ， 将 要 丧 命 ； 对 母 亲 说 ： 谷 、 酒 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20346', '25', '2', '13', '耶 路 撒 冷 的 民 哪 ， 我 可 用 什 么 向 你 证 明 呢 ？ 我 可 用 什 么 与 你 相 比 呢 ？ 锡 安 的 民 哪 ， 我 可 拿 什 么 和 你 比 较 ， 好 安 慰 你 呢 ？ 因 为 你 的 裂 口 大 如 海 ， 谁 能 医 治 你 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20347', '25', '2', '14', '你 的 先 知 为 你 见 虚 假 和 愚 昧 的 异 象 ， 并 没 有 显 露 你 的 罪 孽 ， 使 你 被 掳 的 归 回 ； 却 为 你 见 虚 假 的 默 示 和 使 你 被 赶 出 本 境 的 缘 故 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20348', '25', '2', '15', '凡 过 路 的 都 向 你 拍 掌 。 他 们 向 耶 路 撒 冷 城 嗤 笑 ， 摇 头 ， 说 ： 难 道 人 所 称 为 全 美 的 ， 称 为 全 地 所 喜 悦 的 ， 就 是 这 城 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20349', '25', '2', '16', '你 的 仇 敌 都 向 你 大 大 张 口 ； 他 们 嗤 笑 ， 又 切 齿 说 ： 我 们 吞 灭 她 。 这 真 是 我 们 所 盼 望 的 日 子 临 到 了 ！ 我 们 亲 眼 看 见 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20350', '25', '2', '17', '耶 和 华 成 就 了 他 所 定 的 ， 应 验 了 他 古 时 所 命 定 的 。 他 倾 覆 了 ， 并 不 顾 惜 ， 使 你 的 仇 敌 向 你 夸 耀 ； 使 你 敌 人 的 角 也 被 高 举 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20351', '25', '2', '18', '锡 安 民 的 心 哀 求 主 。 锡 安 的 城 墙 啊 ， 愿 你 流 泪 如 河 ， 昼 夜 不 息 ； 愿 你 眼 中 的 瞳 人 泪 流 不 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20352', '25', '2', '19', '夜 间 ， 每 逢 交 更 的 时 候 要 起 来 呼 喊 ， 在 主 面 前 倾 心 如 水 。 你 的 孩 童 在 各 市 口 上 受 饿 发 昏 ； 你 要 为 他 们 的 性 命 向 主 举 手 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20353', '25', '2', '20', '耶 和 华 啊 ， 求 你 观 看 ！ 见 你 向 谁 这 样 行 ？ 妇 人 岂 可 吃 自 己 所 生 育 手 里 所 摇 弄 的 婴 孩 吗 ？ 祭 司 和 先 知 岂 可 在 主 的 圣 所 中 被 杀 戮 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20354', '25', '2', '21', '少 年 人 和 老 年 人 都 在 街 上 躺 卧 ； 我 的 处 女 和 壮 丁 都 倒 在 刀 下 ； 你 发 怒 的 日 子 杀 死 他 们 。 你 杀 了 ， 并 不 顾 惜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20355', '25', '2', '22', '你 招 聚 四 围 惊 吓 我 的 ， 像 在 大 会 的 日 子 招 聚 人 一 样 。 耶 和 华 发 怒 的 日 子 ， 无 人 逃 脱 ， 无 人 存 留 。 我 所 摇 弄 所 养 育 的 婴 孩 ， 仇 敌 都 杀 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20356', '25', '3', '1', '＜ 刑 罚 、 悔 改 、 希 望 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20357', '25', '3', '2', '他 引 导 我 ， 使 我 行 在 黑 暗 中 ， 不 行 在 光 明 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20358', '25', '3', '3', '他 真 是 终 日 再 三 反 手 攻 击 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20359', '25', '3', '4', '他 使 我 的 皮 肉 枯 干 ； 他 折 断 ｛ 或 译 ： 压 伤 ｝ 我 的 骨 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20360', '25', '3', '5', '他 筑 垒 攻 击 我 ， 用 苦 楚 ｛ 原 文 是 苦 胆 ｝ 和 艰 难 围 困 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20361', '25', '3', '6', '他 使 我 住 在 幽 暗 之 处 ， 像 死 了 许 久 的 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20362', '25', '3', '7', '他 用 篱 笆 围 住 我 ， 使 我 不 能 出 去 ； 他 使 我 的 铜 炼 沉 重 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20363', '25', '3', '8', '我 哀 号 求 救 ； 他 使 我 的 祷 告 不 得 上 达 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20364', '25', '3', '9', '他 用 凿 过 的 石 头 挡 住 我 的 道 ； 他 使 我 的 路 弯 曲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20365', '25', '3', '10', '他 向 我 如 熊 埋 伏 ， 如 狮 子 在 隐 密 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20366', '25', '3', '11', '他 使 我 转 离 正 路 ， 将 我 撕 碎 ， 使 我 凄 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20367', '25', '3', '12', '他 张 弓 将 我 当 作 箭 靶 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20368', '25', '3', '13', '他 把 箭 袋 中 的 箭 射 入 我 的 肺 腑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20369', '25', '3', '14', '我 成 了 众 民 的 笑 话 ； 他 们 终 日 以 我 为 歌 曲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20370', '25', '3', '15', '他 用 苦 楚 充 满 我 ， 使 我 饱 用 茵 蔯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20371', '25', '3', '16', '他 又 用 沙 石 碜 断 我 的 牙 ， 用 灰 尘 将 我 蒙 蔽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20372', '25', '3', '17', '你 使 我 远 离 平 安 ， 我 忘 记 好 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20373', '25', '3', '18', '我 就 说 ： 我 的 力 量 衰 败 ； 我 在 耶 和 华 那 里 毫 无 指 望 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20374', '25', '3', '19', '耶 和 华 啊 ， 求 你 记 念 我 如 茵 蔯 和 苦 胆 的 困 苦 窘 迫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20375', '25', '3', '20', '我 心 想 念 这 些 ， 就 在 里 面 忧 闷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20376', '25', '3', '21', '我 想 起 这 事 ， 心 里 就 有 指 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20377', '25', '3', '22', '我 们 不 致 消 灭 ， 是 出 于 耶 和 华 诸 般 的 慈 爱 ； 是 因 他 的 怜 悯 不 致 断 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20378', '25', '3', '23', '每 早 晨 ， 这 都 是 新 的 ； 你 的 诚 实 极 其 广 大 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20379', '25', '3', '24', '我 心 里 说 ： 耶 和 华 是 我 的 分 ， 因 此 ， 我 要 仰 望 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20380', '25', '3', '25', '凡 等 候 耶 和 华 ， 心 里 寻 求 他 的 ， 耶 和 华 必 施 恩 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20381', '25', '3', '26', '人 仰 望 耶 和 华 ， 静 默 等 候 他 的 救 恩 ， 这 原 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20382', '25', '3', '27', '人 在 幼 年 负 轭 ， 这 原 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20383', '25', '3', '28', '他 当 独 坐 无 言 ， 因 为 这 是 耶 和 华 加 在 他 身 上 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20384', '25', '3', '29', '他 当 口 贴 尘 埃 ， 或 者 有 指 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20385', '25', '3', '30', '他 当 由 人 打 他 的 腮 颊 ， 要 满 受 凌 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20386', '25', '3', '31', '因 为 主 必 不 永 远 丢 弃 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20387', '25', '3', '32', '主 虽 使 人 忧 愁 ， 还 要 照 他 诸 般 的 慈 爱 发 怜 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20388', '25', '3', '33', '因 他 并 不 甘 心 使 人 受 苦 ， 使 人 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20389', '25', '3', '34', '人 将 世 上 被 囚 的 踹 ｛ 原 文 是 压 ｝ 在 脚 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20390', '25', '3', '35', '或 在 至 高 者 面 前 屈 枉 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20391', '25', '3', '36', '或 在 人 的 讼 事 上 颠 倒 是 非 ， 这 都 是 主 看 不 上 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20392', '25', '3', '37', '除 非 主 命 定 ， 谁 能 说 成 就 成 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20393', '25', '3', '38', '祸 福 不 都 出 于 至 高 者 的 口 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20394', '25', '3', '39', '活 人 因 自 己 的 罪 受 罚 ， 为 何 发 怨 言 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20395', '25', '3', '40', '我 们 当 深 深 考 察 自 己 的 行 为 ， 再 归 向 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20396', '25', '3', '41', '我 们 当 诚 心 向 天 上 的 神 举 手 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20397', '25', '3', '42', '我 们 犯 罪 背 逆 ， 你 并 不 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20398', '25', '3', '43', '你 自 被 怒 气 遮 蔽 ， 追 赶 我 们 ； 你 施 行 杀 戮 ， 并 不 顾 惜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20399', '25', '3', '44', '你 以 黑 云 遮 蔽 自 己 ， 以 致 祷 告 不 得 透 入 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20400', '25', '3', '45', '你 使 我 们 在 万 民 中 成 为 污 秽 和 渣 滓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20401', '25', '3', '46', '我 们 的 仇 敌 都 向 我 们 大 大 张 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20402', '25', '3', '47', '恐 惧 和 陷 坑 ， 残 害 和 毁 灭 ， 都 临 近 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20403', '25', '3', '48', '因 我 众 民 遭 的 毁 灭 ， 我 就 眼 泪 下 流 如 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20404', '25', '3', '49', '我 的 眼 多 多 流 泪 ， 总 不 止 息 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20405', '25', '3', '50', '直 等 耶 和 华 垂 顾 ， 从 天 观 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20406', '25', '3', '51', '因 我 本 城 的 众 民 ， 我 的 眼 ， 使 我 的 心 伤 痛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20407', '25', '3', '52', '无 故 与 我 为 仇 的 追 逼 我 ， 像 追 雀 鸟 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20408', '25', '3', '53', '他 们 使 我 的 命 在 牢 狱 中 断 绝 ， 并 将 一 块 石 头 抛 在 我 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20409', '25', '3', '54', '众 水 流 过 我 头 ， 我 说 ： 我 命 断 绝 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20410', '25', '3', '55', '耶 和 华 啊 ， 我 从 深 牢 中 求 告 你 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20411', '25', '3', '56', '你 曾 听 见 我 的 声 音 ； 我 求 你 解 救 ， 你 不 要 掩 耳 不 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20412', '25', '3', '57', '我 求 告 你 的 日 子 ， 你 临 近 我 ， 说 ： 不 要 惧 怕 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20413', '25', '3', '58', '主 啊 ， 你 伸 明 了 我 的 冤 ； 你 救 赎 了 我 的 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20414', '25', '3', '59', '耶 和 华 啊 ， 你 见 了 我 受 的 委 屈 ； 求 你 为 我 伸 冤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20415', '25', '3', '60', '他 们 仇 恨 我 ， 谋 害 我 ， 你 都 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20416', '25', '3', '61', '耶 和 华 啊 ， 你 听 见 他 们 辱 骂 我 的 话 ， 知 道 他 们 向 我 所 设 的 计 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20417', '25', '3', '62', '并 那 些 起 来 攻 击 我 的 人 口 中 所 说 的 话 ， 以 及 终 日 向 我 所 设 的 计 谋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20418', '25', '3', '63', '求 你 观 看 ， 他 们 坐 下 ， 起 来 ， 都 以 我 为 歌 曲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20419', '25', '3', '64', '耶 和 华 啊 ， 你 要 按 着 他 们 手 所 做 的 向 他 们 施 行 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20420', '25', '3', '65', '你 要 使 他 们 心 里 刚 硬 ， 使 你 的 咒 诅 临 到 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20421', '25', '3', '66', '你 要 发 怒 追 赶 他 们 ， 从 耶 和 华 的 天 下 除 灭 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20422', '25', '4', '1', '＜ 耶 路 撒 冷 陷 落 之 后 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20423', '25', '4', '2', '锡 安 宝 贵 的 众 子 好 比 精 金 ， 现 在 何 竟 算 为 窑 匠 手 所 做 的 瓦 瓶 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20424', '25', '4', '3', '野 狗 尚 且 把 奶 乳 哺 其 子 ， 我 民 的 妇 人 倒 成 为 残 忍 ， 好 像 旷 野 的 鸵 鸟 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20425', '25', '4', '4', '吃 奶 孩 子 的 舌 头 因 干 渴 贴 住 上 膛 ； 孩 童 求 饼 ， 无 人 擘 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20426', '25', '4', '5', '素 来 吃 美 好 食 物 的 ， 现 今 在 街 上 变 为 孤 寒 ； 素 来 卧 朱 红 褥 子 的 ， 现 今 躺 卧 粪 堆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20427', '25', '4', '6', '都 因 我 众 民 的 罪 孽 比 所 多 玛 的 罪 还 大 ； 所 多 玛 虽 然 无 人 加 手 于 她 ， 还 是 转 眼 之 间 被 倾 覆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20428', '25', '4', '7', '锡 安 的 贵 胄 素 来 比 雪 纯 净 ， 比 奶 更 白 ； 他 们 的 身 体 比 红 宝 玉 ｛ 或 译 ： 珊 瑚 ｝ 更 红 ， 像 光 润 的 蓝 宝 石 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20429', '25', '4', '8', '现 在 他 们 的 面 貌 比 煤 炭 更 黑 ， 以 致 在 街 上 无 人 认 识 ； 他 们 的 皮 肤 紧 贴 骨 头 ， 枯 干 如 同 槁 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20430', '25', '4', '9', '饿 死 的 不 如 被 刀 杀 的 ， 因 为 这 是 缺 了 田 间 的 土 产 ， 就 身 体 衰 弱 ， 渐 渐 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20431', '25', '4', '10', '慈 心 的 妇 人 ， 当 我 众 民 被 毁 灭 的 时 候 ， 亲 手 煮 自 己 的 儿 女 作 为 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20432', '25', '4', '11', '耶 和 华 发 怒 成 就 他 所 定 的 ， 倒 出 他 的 烈 怒 ； 在 锡 安 使 火 着 起 ， 烧 毁 锡 安 的 根 基 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20433', '25', '4', '12', '地 上 的 君 王 和 世 上 的 居 民 都 不 信 敌 人 和 仇 敌 能 进 耶 路 撒 冷 的 城 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20434', '25', '4', '13', '这 都 因 她 先 知 的 罪 恶 和 祭 司 的 罪 孽 ； 他 们 在 城 中 流 了 义 人 的 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20435', '25', '4', '14', '他 们 在 街 上 如 瞎 子 乱 走 ， 又 被 血 玷 污 ， 以 致 人 不 能 摸 他 们 的 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20436', '25', '4', '15', '人 向 他 们 喊 着 说 ： 不 洁 净 的 ， 躲 开 ， 躲 开 ！ 不 要 挨 近 我 ！ 他 们 逃 走 飘 流 的 时 候 ， 列 国 中 有 人 说 ： 他 们 不 可 仍 在 这 里 寄 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20437', '25', '4', '16', '耶 和 华 发 怒 ， 将 他 们 分 散 ， 不 再 眷 顾 他 们 ； 人 不 重 看 祭 司 ， 也 不 厚 待 长 老 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20438', '25', '4', '17', '我 们 仰 望 人 来 帮 助 ， 以 致 眼 目 失 明 ， 还 是 枉 然 ； 我 们 所 盼 望 的 ， 竟 盼 望 一 个 不 能 救 人 的 国 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20439', '25', '4', '18', '仇 敌 追 赶 我 们 的 脚 步 像 打 猎 的 ， 以 致 我 们 不 敢 在 自 己 的 街 上 行 走 。 我 们 的 结 局 临 近 ； 我 们 的 日 子 满 足 ； 我 们 的 结 局 来 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20440', '25', '4', '19', '追 赶 我 们 的 比 空 中 的 鹰 更 快 ； 他 们 在 山 上 追 逼 我 们 ， 在 旷 野 埋 伏 ， 等 候 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20441', '25', '4', '20', '耶 和 华 的 受 膏 者 好 比 我 们 鼻 中 的 气 ， 在 他 们 的 坑 中 被 捉 住 ； 我 们 曾 论 到 他 说 ： 我 们 必 在 他 荫 下 ， 在 列 国 中 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20442', '25', '4', '21', '住 乌 斯 地 的 以 东 民 哪 ， 只 管 欢 喜 快 乐 ； 苦 杯 也 必 传 到 你 那 里 ； 你 必 喝 醉 ， 以 致 露 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20443', '25', '4', '22', '锡 安 的 民 哪 ， 你 罪 孽 的 刑 罚 受 足 了 ， 耶 和 华 必 不 使 你 再 被 掳 去 。 以 东 的 民 哪 ， 他 必 追 讨 你 的 罪 孽 ， 显 露 你 的 罪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20444', '25', '5', '1', '＜ 求 主 垂 怜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20445', '25', '5', '2', '我 们 的 产 业 归 与 外 邦 人 ； 我 们 的 房 屋 归 与 外 路 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20446', '25', '5', '3', '我 们 是 无 父 的 孤 儿 ； 我 们 的 母 亲 好 像 寡 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20447', '25', '5', '4', '我 们 出 钱 才 得 水 喝 ； 我 们 的 柴 是 人 卖 给 我 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20448', '25', '5', '5', '追 赶 我 们 的 ， 到 了 我 们 的 颈 项 上 ； 我 们 疲 乏 不 得 歇 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20449', '25', '5', '6', '我 们 投 降 埃 及 人 和 亚 述 人 ， 为 要 得 粮 吃 饱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20450', '25', '5', '7', '我 们 列 祖 犯 罪 ， 而 今 不 在 了 ； 我 们 担 当 他 们 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20451', '25', '5', '8', '奴 仆 辖 制 我 们 ， 无 人 救 我 们 脱 离 他 们 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20452', '25', '5', '9', '因 为 旷 野 的 刀 剑 ， 我 们 冒 着 险 才 得 粮 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20453', '25', '5', '10', '因 饥 饿 燥 热 ， 我 们 的 皮 肤 就 黑 如 炉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20454', '25', '5', '11', '敌 人 在 锡 安 玷 污 妇 人 ， 在 犹 大 的 城 邑 玷 污 处 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20455', '25', '5', '12', '他 们 吊 起 首 领 的 手 ， 也 不 尊 敬 老 人 的 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20456', '25', '5', '13', '少 年 人 扛 磨 石 ， 孩 童 背 木 柴 ， 都 绊 跌 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20457', '25', '5', '14', '老 年 人 在 城 门 口 断 绝 ； 少 年 人 不 再 作 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20458', '25', '5', '15', '我 们 心 中 的 快 乐 止 息 ， 跳 舞 变 为 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20459', '25', '5', '16', '冠 冕 从 我 们 的 头 上 落 下 ； 我 们 犯 罪 了 ， 我 们 有 祸 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20460', '25', '5', '17', '这 些 事 我 们 心 里 发 昏 ， 我 们 的 眼 睛 昏 花 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20461', '25', '5', '18', '锡 安 山 荒 凉 ， 野 狗 ｛ 或 译 ： 狐 狸 ｝ 行 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20462', '25', '5', '19', '耶 和 华 啊 ， 你 存 到 永 远 ； 你 的 宝 座 存 到 万 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20463', '25', '5', '20', '你 为 何 永 远 忘 记 我 们 ？ 为 何 许 久 离 弃 我 们 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20464', '25', '5', '21', '耶 和 华 啊 ， 求 你 使 我 们 向 你 回 转 ， 我 们 便 得 回 转 。 求 你 复 新 我 们 的 日 子 ， 像 古 时 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20465', '25', '5', '22', '你 竟 全 然 弃 绝 我 们 ， 向 我 们 大 发 烈 怒 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20466', '26', '1', '1', '＜ 以 西 结 所 见 的 第 一 个 异 象 （ 结   1 : 1 - 7 : 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20467', '26', '1', '2', '正 是 约 雅 斤 王 被 掳 去 第 五 年 四 月 初 五 日 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20468', '26', '1', '3', '在 迦 勒 底 人 之 地 、 迦 巴 鲁 河 边 ， 耶 和 华 的 话 特 特 临 到 布 西 的 儿 子 祭 司 以 西 结 ； 耶 和 华 的 灵 ｛ 原 文 是 手 ｝ 降 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20469', '26', '1', '4', '我 观 看 ， 见 狂 风 从 北 方 刮 来 ， 随 着 有 一 朵 包 括 闪 烁 火 的 大 云 ， 周 围 有 光 辉 ； 从 其 中 的 火 内 发 出 好 像 光 耀 的 精 金 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20470', '26', '1', '5', '又 从 其 中 显 出 四 个 活 物 的 形 像 来 。 他 们 的 形 状 是 这 样 ： 有 人 的 形 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20471', '26', '1', '6', '各 有 四 个 脸 面 ， 四 个 翅 膀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20472', '26', '1', '7', '他 们 的 腿 是 直 的 ， 脚 掌 好 像 牛 犊 之 蹄 ， 都 灿 烂 如 光 明 的 铜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20473', '26', '1', '8', '在 四 面 的 翅 膀 以 下 有 人 的 手 。 这 四 个 活 物 的 脸 和 翅 膀 乃 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20474', '26', '1', '9', '翅 膀 彼 此 相 接 ， 行 走 并 不 转 身 ， 俱 各 直 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20475', '26', '1', '10', '至 于 脸 的 形 像 ： 前 面 各 有 人 的 脸 ， 右 面 各 有 狮 子 的 脸 ， 左 面 各 有 牛 的 脸 ， 后 面 各 有 鹰 的 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20476', '26', '1', '11', '各 展 开 上 边 的 两 个 翅 膀 相 接 ， 各 以 下 边 的 两 个 翅 膀 遮 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20477', '26', '1', '12', '他 们 俱 各 直 往 前 行 。 灵 往 哪 里 去 ， 他 们 就 往 那 里 去 ， 行 走 并 不 转 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20478', '26', '1', '13', '至 于 四 活 物 的 形 像 ， 就 如 烧 着 火 炭 的 形 状 ， 又 如 火 把 的 形 状 。 火 在 四 活 物 中 间 上 去 下 来 ， 这 火 有 光 辉 ， 从 火 中 发 出 闪 电 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20479', '26', '1', '14', '这 活 物 往 来 奔 走 ， 好 像 电 光 一 闪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20480', '26', '1', '15', '我 正 观 看 活 物 的 时 候 ， 见 活 物 的 脸 旁 各 有 一 轮 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20481', '26', '1', '16', '轮 的 形 状 和 颜 色 ｛ 原 文 是 作 法 ｝ 好 像 水 苍 玉 。 四 轮 都 是 一 个 样 式 ， 形 状 和 作 法 好 像 轮 中 套 轮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20482', '26', '1', '17', '轮 行 走 的 时 候 ， 向 四 方 都 能 直 行 ， 并 不 掉 转 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20483', '26', '1', '18', '至 于 轮 辋 ， 高 而 可 畏 ； 四 个 轮 辋 周 围 满 有 眼 睛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20484', '26', '1', '19', '活 物 行 走 ， 轮 也 在 旁 边 行 走 ； 活 物 从 地 上 升 ， 轮 也 都 上 升 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20485', '26', '1', '20', '灵 往 哪 里 去 ， 活 物 就 往 那 里 去 ； 活 物 上 升 ， 轮 也 在 活 物 旁 边 上 升 ， 因 为 活 物 的 灵 在 轮 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20486', '26', '1', '21', '那 些 行 走 ， 这 些 也 行 走 ； 那 些 站 住 ， 这 些 也 站 住 ； 那 些 从 地 上 升 ， 轮 也 在 旁 边 上 升 ， 因 为 活 物 的 灵 在 轮 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20487', '26', '1', '22', '活 物 的 头 以 上 有 穹 苍 的 形 像 ， 看 着 像 可 畏 的 水 晶 ， 铺 张 在 活 物 的 头 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20488', '26', '1', '23', '穹 苍 以 下 ， 活 物 的 翅 膀 直 张 ， 彼 此 相 对 ； 每 活 物 有 两 个 翅 膀 遮 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20489', '26', '1', '24', '活 物 行 走 的 时 候 ， 我 听 见 翅 膀 的 响 声 ， 像 大 水 的 声 音 ， 像 全 能 者 的 声 音 ， 也 像 军 队 哄 嚷 的 声 音 。 活 物 站 住 的 时 候 ， 便 将 翅 膀 垂 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20490', '26', '1', '25', '在 他 们 头 以 上 的 穹 苍 之 上 有 声 音 。 他 们 站 住 的 时 候 ， 便 将 翅 膀 垂 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20491', '26', '1', '26', '在 他 们 头 以 上 的 穹 苍 之 上 有 宝 座 的 形 像 ， 仿 佛 蓝 宝 石 ； 在 宝 座 形 像 以 上 有 仿 佛 人 的 形 状 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20492', '26', '1', '27', '我 见 从 他 腰 以 上 有 仿 佛 光 耀 的 精 金 ， 周 围 都 有 火 的 形 状 ， 又 见 从 他 腰 以 下 有 仿 佛 火 的 形 状 ， 周 围 也 有 光 辉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20493', '26', '1', '28', '下 雨 的 日 子 ， 云 中 虹 的 形 状 怎 样 ， 周 围 光 辉 的 形 状 也 是 怎 样 。 这 就 是 耶 和 华 荣 耀 的 形 像 。 我 一 看 见 就 俯 伏 在 地 ， 又 听 见 一 位 说 话 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20494', '26', '2', '1', '＜ 神 选 召 以 西 结 作 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20495', '26', '2', '2', '他 对 我 说 话 的 时 候 ， 灵 就 进 入 我 里 面 ， 使 我 站 起 来 ， 我 便 听 见 那 位 对 我 说 话 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20496', '26', '2', '3', '他 对 我 说 ： “ 人 子 啊 ， 我 差 你 往 悖 逆 的 国 民 以 色 列 人 那 里 去 。 他 们 是 悖 逆 我 的 ， 他 们 和 他 们 的 列 祖 违 背 我 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20497', '26', '2', '4', '这 众 子 面 无 羞 耻 ， 心 里 刚 硬 。 我 差 你 往 他 们 那 里 去 ， 你 要 对 他 们 说 ： 主 耶 和 华 如 此 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20498', '26', '2', '5', '他 们 或 听 ， 或 不 听 ， （ 他 们 是 悖 逆 之 家 ） ， 必 知 道 在 他 们 中 间 有 了 先 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20499', '26', '2', '6', '人 子 啊 ， 虽 有 荆 棘 和 蒺 藜 在 你 那 里 ， 你 又 住 在 蝎 子 中 间 ， 总 不 要 怕 他 们 ， 也 不 要 怕 他 们 的 话 ； 他 们 虽 是 悖 逆 之 家 ， 还 不 要 怕 他 们 的 话 ， 也 不 要 因 他 们 的 脸 色 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20500', '26', '2', '7', '他 们 或 听 ， 或 不 听 ， 你 只 管 将 我 的 话 告 诉 他 们 ； 他 们 是 极 其 悖 逆 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20501', '26', '2', '8', '“ 人 子 啊 ， 要 听 我 对 你 所 说 的 话 ， 不 要 悖 逆 像 那 悖 逆 之 家 ， 你 要 开 口 吃 我 所 赐 给 你 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20502', '26', '2', '9', '我 观 看 ， 见 有 一 只 手 向 我 伸 出 来 ， 手 中 有 一 书 卷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20503', '26', '2', '10', '他 将 书 卷 在 我 面 前 展 开 ， 内 外 都 写 着 字 ， 其 上 所 写 的 有 哀 号 、 叹 息 、 悲 痛 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20504', '26', '3', '1', '他 对 我 说 ： “ 人 子 啊 ， 要 吃 你 所 得 的 ， 要 吃 这 书 卷 ， 好 去 对 以 色 列 家 讲 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20505', '26', '3', '2', '于 是 我 开 口 ， 他 就 使 我 吃 这 书 卷 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20506', '26', '3', '3', '又 对 我 说 ： “ 人 子 啊 ， 要 吃 我 所 赐 给 你 的 这 书 卷 ， 充 满 你 的 肚 腹 。 ” 我 就 吃 了 ， 口 中 觉 得 其 甜 如 蜜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20507', '26', '3', '4', '他 对 我 说 ： “ 人 子 啊 ， 你 往 以 色 列 家 那 里 去 ， 将 我 的 话 对 他 们 讲 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20508', '26', '3', '5', '你 奉 差 遣 不 是 往 那 说 话 深 奥 、 言 语 难 懂 的 民 那 里 去 ， 乃 是 往 以 色 列 家 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20509', '26', '3', '6', '不 是 往 那 说 话 深 奥 、 言 语 难 懂 的 多 国 去 ， 他 们 的 话 语 是 你 不 懂 得 的 。 我 若 差 你 往 他 们 那 里 去 ， 他 们 必 听 从 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20510', '26', '3', '7', '以 色 列 家 却 不 肯 听 从 你 ， 因 为 他 们 不 肯 听 从 我 ； 原 来 以 色 列 全 家 是 额 坚 心 硬 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20511', '26', '3', '8', '看 哪 ， 我 使 你 的 脸 硬 过 他 们 的 脸 ， 使 你 的 额 硬 过 他 们 的 额 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20512', '26', '3', '9', '我 使 你 的 额 像 金 钢 钻 ， 比 火 石 更 硬 。 他 们 虽 是 悖 逆 之 家 ， 你 不 要 怕 他 们 ， 也 不 要 因 他 们 的 脸 色 惊 惶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20513', '26', '3', '10', '他 又 对 我 说 ： “ 人 子 啊 ， 我 对 你 所 说 的 一 切 话 ， 要 心 里 领 会 ， 耳 中 听 闻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20514', '26', '3', '11', '你 往 你 本 国 被 掳 的 子 民 那 里 去 ， 他 们 或 听 ， 或 不 听 ， 你 要 对 他 们 讲 说 ， 告 诉 他 们 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20515', '26', '3', '12', '那 时 ， 灵 将 我 举 起 ， 我 就 听 见 在 我 身 后 有 震 动 轰 轰 的 声 音 ， 说 ： “ 从 耶 和 华 的 所 在 显 出 来 的 荣 耀 是 该 称 颂 的 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20516', '26', '3', '13', '我 又 听 见 那 活 物 翅 膀 相 碰 ， 与 活 物 旁 边 轮 子 旋 转 震 动 轰 轰 的 响 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20517', '26', '3', '14', '于 是 灵 将 我 举 起 ， 带 我 而 去 。 我 心 中 甚 苦 ， 灵 性 忿 激 ， 并 且 耶 和 华 的 灵 ｛ 原 文 是 手 ｝ 在 我 身 上 大 有 能 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20518', '26', '3', '15', '我 就 来 到 提 勒 ． 亚 毕 ， 住 在 迦 巴 鲁 河 边 被 掳 的 人 那 里 ， 到 他 们 所 住 的 地 方 ， 在 他 们 中 间 忧 忧 闷 闷 地 坐 了 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20519', '26', '3', '16', '＜ 耶 和 华 派 以 西 结 作 守 望 者 （ 结   3 3 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20520', '26', '3', '17', '“ 人 子 啊 ， 我 立 你 作 以 色 列 家 守 望 的 人 ， 所 以 你 要 听 我 口 中 的 话 ， 替 我 警 戒 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20521', '26', '3', '18', '我 何 时 指 着 恶 人 说 ： 他 必 要 死 ； 你 若 不 警 戒 他 ， 也 不 劝 戒 他 ， 使 他 离 开 恶 行 ， 拯 救 他 的 性 命 ， 这 恶 人 必 死 在 罪 孽 之 中 ； 我 却 要 向 你 讨 他 丧 命 的 罪 ｛ 原 文 是 血 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20522', '26', '3', '19', '倘 若 你 警 戒 恶 人 ， 他 仍 不 转 离 罪 恶 ， 也 不 离 开 恶 行 ， 他 必 死 在 罪 孽 之 中 ， 你 却 救 自 己 脱 离 了 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20523', '26', '3', '20', '再 者 ， 义 人 何 时 离 义 而 犯 罪 ， 我 将 绊 脚 石 放 在 他 面 前 ， 他 就 必 死 ； 因 你 没 有 警 戒 他 ， 他 必 死 在 罪 中 ， 他 素 来 所 行 的 义 不 被 记 念 ； 我 却 要 向 你 讨 他 丧 命 的 罪 ｛ 原 文 是 血 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20524', '26', '3', '21', '倘 若 你 警 戒 义 人 ， 使 他 不 犯 罪 ， 他 就 不 犯 罪 ； 他 因 受 警 戒 就 必 存 活 ， 你 也 救 自 己 脱 离 了 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20525', '26', '3', '22', '＜ 以 西 结 暂 成 哑 巴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20526', '26', '3', '23', '于 是 我 起 来 往 平 原 去 ， 不 料 ， 耶 和 华 的 荣 耀 正 如 我 在 迦 巴 鲁 河 边 所 见 的 一 样 ， 停 在 那 里 ， 我 就 俯 伏 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20527', '26', '3', '24', '灵 就 进 入 我 里 面 ， 使 我 站 起 来 。 耶 和 华 对 我 说 ： “ 你 进 房 屋 去 ， 将 门 关 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20528', '26', '3', '25', '人 子 啊 ， 人 必 用 绳 索 捆 绑 你 ， 你 就 不 能 出 去 在 他 们 中 间 来 往 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20529', '26', '3', '26', '我 必 使 你 的 舌 头 贴 住 上 膛 ， 以 致 你 哑 口 ， 不 能 作 责 备 他 们 的 人 ； 他 们 原 是 悖 逆 之 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20530', '26', '3', '27', '但 我 对 你 说 话 的 时 候 ， 必 使 你 开 口 ， 你 就 要 对 他 们 说 ： ‘ 主 耶 和 华 如 此 说 。 ’ 听 的 可 以 听 ， 不 听 的 任 他 不 听 ， 因 为 他 们 是 悖 逆 之 家 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20531', '26', '4', '1', '＜ 表 演 耶 路 撒 冷 被 困 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20532', '26', '4', '2', '又 围 困 这 城 ， 造 台 筑 垒 ， 安 营 攻 击 ， 在 四 围 安 设 撞 锤 攻 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20533', '26', '4', '3', '又 要 拿 个 铁 鏊 ， 放 在 你 和 城 的 中 间 ， 作 为 铁 墙 。 你 要 对 面 攻 击 这 城 ， 使 城 被 困 ； 这 样 ， 好 作 以 色 列 家 的 预 兆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20534', '26', '4', '4', '“ 你 要 向 左 侧 卧 ， 承 当 以 色 列 家 的 罪 孽 ； 要 按 你 向 左 侧 卧 的 日 数 ， 担 当 他 们 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20535', '26', '4', '5', '因 为 我 已 将 他 们 作 孽 的 年 数 定 为 你 向 左 侧 卧 的 日 数 ， 就 是 三 百 九 十 日 ， 你 要 这 样 担 当 以 色 列 家 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20536', '26', '4', '6', '再 者 ， 你 满 了 这 些 日 子 ， 还 要 向 右 侧 卧 ， 担 当 犹 大 家 的 罪 孽 。 我 给 你 定 规 侧 卧 四 十 日 ， 一 日 顶 一 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20537', '26', '4', '7', '你 要 露 出 膀 臂 ， 面 向 被 困 的 耶 路 撒 冷 ， 说 预 言 攻 击 这 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20538', '26', '4', '8', '我 用 绳 索 捆 绑 你 ， 使 你 不 能 辗 转 ， 直 等 你 满 了 困 城 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20539', '26', '4', '9', '“ 你 要 取 小 麦 、 大 麦 、 豆 子 、 红 豆 、 小 米 、 粗 麦 ， 装 在 一 个 器 皿 中 ， 用 以 为 自 己 做 饼 ； 要 按 你 侧 卧 的 三 百 九 十 日 吃 这 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20540', '26', '4', '10', '你 所 吃 的 要 按 分 两 吃 ， 每 日 二 十 舍 客 勒 ， 按 时 而 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20541', '26', '4', '11', '你 喝 水 也 要 按 制 子 ， 每 日 喝 一 欣 六 分 之 一 ， 按 时 而 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20542', '26', '4', '12', '你 吃 这 饼 像 吃 大 麦 饼 一 样 ， 要 用 人 粪 在 众 人 眼 前 烧 烤 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20543', '26', '4', '13', '耶 和 华 说 ： “ 以 色 列 人 在 我 所 赶 他 们 到 的 各 国 中 ， 也 必 这 样 吃 不 洁 净 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20544', '26', '4', '14', '我 说 ： “ 哎 ！ 主 耶 和 华 啊 ， 我 素 来 未 曾 被 玷 污 ， 从 幼 年 到 如 今 没 有 吃 过 自 死 的 ， 或 被 野 兽 撕 裂 的 ， 那 可 憎 的 肉 也 未 曾 入 我 的 口 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20545', '26', '4', '15', '于 是 他 对 我 说 ： “ 看 哪 ， 我 给 你 牛 粪 代 替 人 粪 ， 你 要 将 你 的 饼 烤 在 其 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20546', '26', '4', '16', '他 又 对 我 说 ： “ 人 子 啊 ， 我 必 在 耶 路 撒 冷 折 断 他 们 的 杖 ， 就 是 断 绝 他 们 的 粮 。 他 们 吃 饼 要 按 分 两 ， 忧 虑 而 吃 ； 喝 水 也 要 按 制 子 ， 惊 惶 而 喝 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20547', '26', '4', '17', '使 他 们 缺 粮 缺 水 ， 彼 此 惊 惶 ， 因 自 己 的 罪 孽 消 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20548', '26', '5', '1', '＜ 以 西 结 剃 发 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20549', '26', '5', '2', '围 困 城 的 日 子 满 了 ， 你 要 将 三 分 之 一 在 城 中 用 火 焚 烧 ， 将 三 分 之 一 在 城 的 四 围 用 刀 砍 碎 ， 将 三 分 之 一 任 风 吹 散 ； 我 也 要 拔 刀 追 赶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20550', '26', '5', '3', '你 要 从 其 中 取 几 根 包 在 衣 襟 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20551', '26', '5', '4', '再 从 这 几 根 中 取 些 扔 在 火 中 焚 烧 ， 从 里 面 必 有 火 出 来 烧 入 以 色 列 全 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20552', '26', '5', '5', '主 耶 和 华 如 此 说 ： 这 就 是 耶 路 撒 冷 。 我 曾 将 她 安 置 在 列 邦 之 中 ； 列 国 都 在 她 的 四 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20553', '26', '5', '6', '她 行 恶 ， 违 背 我 的 典 章 ， 过 于 列 国 ； 干 犯 我 的 律 例 ， 过 于 四 围 的 列 邦 ， 因 为 她 弃 掉 我 的 典 章 。 至 于 我 的 律 例 ， 她 并 没 有 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20554', '26', '5', '7', '所 以 主 耶 和 华 如 此 说 ： 因 为 你 们 纷 争 过 于 四 围 的 列 国 ， 也 不 遵 行 我 的 律 例 ， 不 谨 守 我 的 典 章 ， 并 以 遵 从 四 围 列 国 的 恶 规 尚 不 满 意 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20555', '26', '5', '8', '所 以 主 耶 和 华 如 此 说 ： 看 哪 ， 我 与 你 反 对 ， 必 在 列 国 的 眼 前 ， 在 你 中 间 ， 施 行 审 判 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20556', '26', '5', '9', '并 且 因 你 一 切 可 憎 的 事 ， 我 要 在 你 中 间 行 我 所 未 曾 行 的 ， 以 后 我 也 不 再 照 着 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20557', '26', '5', '10', '在 你 中 间 父 亲 要 吃 儿 子 ， 儿 子 要 吃 父 亲 。 我 必 向 你 施 行 审 判 ， 我 必 将 你 所 剩 下 的 分 散 四 方 ｛ 方 ： 原 文 是 风 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20558', '26', '5', '11', '主 耶 和 华 说 ： “ 我 指 着 我 的 永 生 起 誓 ， 因 你 用 一 切 可 憎 的 物 、 可 厌 的 事 玷 污 了 我 的 圣 所 ， 故 此 ， 我 定 要 使 你 人 数 减 少 ， 我 眼 必 不 顾 惜 你 ， 也 不 可 怜 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20559', '26', '5', '12', '你 的 民 三 分 之 一 必 遭 瘟 疫 而 死 ， 在 你 中 间 必 因 饥 荒 消 灭 ； 三 分 之 一 必 在 你 四 围 倒 在 刀 下 ； 我 必 将 三 分 之 一 分 散 四 方 ｛ 方 ： 原 文 是 风 ｝ ， 并 要 拔 刀 追 赶 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20560', '26', '5', '13', '“ 我 要 这 样 成 就 怒 中 所 定 的 ； 我 向 他 们 发 的 忿 怒 止 息 了 ， 自 己 就 得 着 安 慰 。 我 在 他 们 身 上 成 就 怒 中 所 定 的 那 时 ， 他 们 就 知 道 我 ─ ─ 耶 和 华 所 说 的 是 出 于 热 心 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20561', '26', '5', '14', '并 且 我 必 使 你 在 四 围 的 列 国 中 ， 在 经 过 的 众 人 眼 前 ， 成 了 荒 凉 和 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20562', '26', '5', '15', '这 样 ， 我 必 以 怒 气 和 忿 怒 ， 并 烈 怒 的 责 备 ， 向 你 施 行 审 判 。 那 时 ， 你 就 在 四 围 的 列 国 中 成 为 羞 辱 、 讥 刺 、 警 戒 、 惊 骇 。 这 是 我 ─ ─ 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20563', '26', '5', '16', '那 时 ， 我 要 将 灭 人 、 使 人 饥 荒 的 恶 箭 ， 就 是 射 去 灭 人 的 ， 射 在 你 们 身 上 ， 并 要 加 增 你 们 的 饥 荒 ， 断 绝 你 们 所 倚 靠 的 粮 食 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20564', '26', '5', '17', '又 要 使 饥 荒 和 恶 兽 到 你 那 里 ， 叫 你 丧 子 ， 瘟 疫 和 流 血 的 事 也 必 盛 行 在 你 那 里 ； 我 也 要 使 刀 剑 临 到 你 。 这 是 我 ─ ─ 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20565', '26', '6', '1', '＜ 谴 责 拜 偶 像 的 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20566', '26', '6', '2', '“ 人 子 啊 ， 你 要 面 向 以 色 列 的 众 山 说 预 言 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20567', '26', '6', '3', '说 ： 以 色 列 的 众 山 哪 ， 要 听 主 耶 和 华 的 话 。 主 耶 和 华 对 大 山 、 小 冈 、 水 沟 、 山 谷 如 此 说 ： 我 必 使 刀 剑 临 到 你 们 ， 也 必 毁 灭 你 们 的 邱 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20568', '26', '6', '4', '你 们 的 祭 坛 必 然 荒 凉 ， 你 们 的 日 像 必 被 打 碎 。 我 要 使 你 们 被 杀 的 人 倒 在 你 们 的 偶 像 面 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20569', '26', '6', '5', '我 也 要 将 以 色 列 人 的 尸 首 放 在 他 们 的 偶 像 面 前 ， 将 你 们 的 骸 骨 抛 散 在 你 们 祭 坛 的 四 围 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20570', '26', '6', '6', '在 你 们 一 切 的 住 处 ， 城 邑 要 变 为 荒 场 ， 邱 坛 必 然 凄 凉 ， 使 你 们 的 祭 坛 荒 废 ， 将 你 们 的 偶 像 打 碎 。 你 们 的 日 像 被 砍 倒 ， 你 们 的 工 作 被 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20571', '26', '6', '7', '被 杀 的 人 必 倒 在 你 们 中 间 ， 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20572', '26', '6', '8', '“ 你 们 分 散 在 各 国 的 时 候 ， 我 必 在 列 邦 中 使 你 们 有 剩 下 脱 离 刀 剑 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20573', '26', '6', '9', '那 脱 离 刀 剑 的 人 必 在 所 掳 到 的 各 国 中 记 念 我 ， 为 他 们 心 中 何 等 伤 破 ， 是 因 他 们 起 淫 心 ， 远 离 我 ， 眼 对 偶 像 行 邪 淫 。 他 们 因 行 一 切 可 憎 的 恶 事 ， 必 厌 恶 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20574', '26', '6', '10', '他 们 必 知 道 我 是 耶 和 华 ； 我 说 要 使 这 灾 祸 临 到 他 们 身 上 ， 并 非 空 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20575', '26', '6', '11', '“ 主 耶 和 华 如 此 说 ： 你 当 拍 手 顿 足 ， 说 ： 哀 哉 ！ 以 色 列 家 行 这 一 切 可 憎 的 恶 事 ， 他 们 必 倒 在 刀 剑 、 饥 荒 、 瘟 疫 之 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20576', '26', '6', '12', '在 远 处 的 ， 必 遭 瘟 疫 而 死 ； 在 近 处 的 ， 必 倒 在 刀 剑 之 下 ； 那 存 留 被 围 困 的 ， 必 因 饥 荒 而 死 ； 我 必 这 样 在 他 们 身 上 成 就 我 怒 中 所 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20577', '26', '6', '13', '他 们 被 杀 的 人 倒 在 他 们 祭 坛 四 围 的 偶 像 中 ， 就 是 各 高 冈 、 各 山 顶 、 各 青 翠 树 下 、 各 茂 密 的 橡 树 下 ， 乃 是 他 们 献 馨 香 的 祭 牲 给 一 切 偶 像 的 地 方 。 那 时 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20578', '26', '6', '14', '我 必 伸 手 攻 击 他 们 ， 使 他 们 的 地 从 旷 野 到 第 伯 拉 他 一 切 住 处 极 其 荒 凉 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20579', '26', '7', '1', '＜ 以 色 列 的 终 局 近 了 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20580', '26', '7', '2', '“ 人 子 啊 ， 主 耶 和 华 对 以 色 列 地 如 此 说 ： 结 局 到 了 ， 结 局 到 了 地 的 四 境 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20581', '26', '7', '3', '现 在 你 的 结 局 已 经 临 到 ， 我 必 使 我 的 怒 气 归 与 你 ， 也 必 按 你 的 行 为 审 判 你 ， 照 你 一 切 可 憎 的 事 刑 罚 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20582', '26', '7', '4', '我 眼 必 不 顾 惜 你 ， 也 不 可 怜 你 ， 却 要 按 你 所 行 的 报 应 你 ， 照 你 中 间 可 憎 的 事 刑 罚 你 。 你 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20583', '26', '7', '5', '“ 主 耶 和 华 如 此 说 ： 有 一 灾 ， 独 有 一 灾 ； 看 哪 ， 临 近 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20584', '26', '7', '6', '结 局 来 了 ， 结 局 来 了 ， 向 你 兴 起 。 看 哪 ， 来 到 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20585', '26', '7', '7', '境 内 的 居 民 哪 ， 所 定 的 灾 临 到 你 ， 时 候 到 了 ， 日 子 近 了 ， 乃 是 哄 嚷 并 非 在 山 上 欢 呼 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20586', '26', '7', '8', '我 快 要 将 我 的 忿 怒 倾 在 你 身 上 ， 向 你 成 就 我 怒 中 所 定 的 ， 按 你 的 行 为 审 判 你 ， 照 你 一 切 可 憎 的 事 刑 罚 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20587', '26', '7', '9', '我 眼 必 不 顾 惜 你 ， 也 不 可 怜 你 ， 必 按 你 所 行 的 报 应 你 ， 照 你 中 间 可 憎 的 事 刑 罚 你 。 你 就 知 道 击 打 你 的 是 我 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20588', '26', '7', '10', '“ 看 哪 ， 看 哪 ， 日 子 快 到 了 ； 所 定 的 灾 已 经 发 出 ！ 杖 已 经 开 花 ， 骄 傲 已 经 发 芽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20589', '26', '7', '11', '强 暴 兴 起 ， 成 了 罚 恶 的 杖 。 以 色 列 人 ， 或 是 他 们 的 群 众 ， 或 是 他 们 的 财 宝 ， 无 一 存 留 ； 他 们 中 间 也 没 有 得 尊 荣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20590', '26', '7', '12', '时 候 到 了 ， 日 子 近 了 ， 买 主 不 可 欢 喜 ， 卖 主 不 可 愁 烦 ， 因 为 烈 怒 已 经 临 到 他 们 众 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20591', '26', '7', '13', '卖 主 虽 然 存 活 ， 却 不 能 归 回 再 得 所 卖 的 ， 因 为 这 异 象 关 乎 他 们 众 人 。 谁 都 不 得 归 回 ， 也 没 有 人 在 他 的 罪 孽 中 坚 立 自 己 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20592', '26', '7', '14', '＜ 惩 罚 以 色 列 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20593', '26', '7', '15', '在 外 有 刀 剑 ； 在 内 有 瘟 疫 、 饥 荒 。 在 田 野 的 ， 必 遭 刀 剑 而 死 ； 在 城 中 的 ， 必 有 饥 荒 、 瘟 疫 吞 灭 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20594', '26', '7', '16', '其 中 所 逃 脱 的 就 必 逃 脱 ， 各 人 因 自 己 的 罪 孽 在 山 上 发 出 悲 声 ， 好 像 谷 中 的 鸽 子 哀 鸣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20595', '26', '7', '17', '手 都 发 软 ， 膝 弱 如 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20596', '26', '7', '18', '要 用 麻 布 束 腰 ， 被 战 兢 所 盖 ； 各 人 脸 上 羞 愧 ， 头 上 光 秃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20597', '26', '7', '19', '他 们 要 将 银 子 抛 在 街 上 ， 金 子 看 如 污 秽 之 物 。 当 耶 和 华 发 怒 的 日 子 ， 他 们 的 金 银 不 能 救 他 们 ， 不 能 使 心 里 知 足 ， 也 不 能 使 肚 腹 饱 满 ， 因 为 这 金 银 作 了 他 们 罪 孽 的 绊 脚 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20598', '26', '7', '20', '论 到 耶 和 华 妆 饰 华 美 的 殿 ， 他 建 立 得 威 严 ， 他 们 却 在 其 中 制 造 可 憎 可 厌 的 偶 像 ， 所 以 这 殿 我 使 他 们 看 如 污 秽 之 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20599', '26', '7', '21', '我 必 将 这 殿 交 付 外 邦 人 为 掠 物 ， 交 付 地 上 的 恶 人 为 掳 物 ； 他 们 也 必 亵 渎 这 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20600', '26', '7', '22', '我 必 转 脸 不 顾 以 色 列 人 ， 他 们 亵 渎 我 隐 密 之 所 ， 强 盗 也 必 进 去 亵 渎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20601', '26', '7', '23', '“ 要 制 造 锁 炼 ； 因 为 这 地 遍 满 流 血 的 罪 ， 城 邑 充 满 强 暴 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20602', '26', '7', '24', '所 以 ， 我 必 使 列 国 中 最 恶 的 人 来 占 据 他 们 的 房 屋 ； 我 必 使 强 暴 人 的 骄 傲 止 息 ， 他 们 的 圣 所 都 要 被 亵 渎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20603', '26', '7', '25', '毁 灭 临 近 了 ； 他 们 要 求 平 安 ， 却 无 平 安 可 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20604', '26', '7', '26', '灾 害 加 上 灾 害 ， 风 声 接 连 风 声 ； 他 们 必 向 先 知 求 异 象 ， 但 祭 司 讲 的 律 法 、 长 老 设 的 谋 略 都 必 断 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20605', '26', '7', '27', '君 要 悲 哀 ， 王 要 披 凄 凉 为 衣 ， 国 民 的 手 都 发 颤 。 我 必 照 他 们 的 行 为 待 他 们 ， 按 他 们 应 得 的 审 判 他 们 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20606', '26', '8', '1', '＜ 以 西 结 所 见 的 第 二 个 异 象 （ 结   8 : 1 - 1 0 : 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20607', '26', '8', '2', '我 观 看 ， 见 有 形 像 仿 佛 火 的 形 状 ， 从 他 腰 以 下 的 形 状 有 火 ， 从 他 腰 以 上 有 光 辉 的 形 状 ， 仿 佛 光 耀 的 精 金 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20608', '26', '8', '3', '他 伸 出 仿 佛 一 只 手 的 样 式 ， 抓 住 我 的 一 绺 头 发 ， 灵 就 将 我 举 到 天 地 中 间 ， 在 神 的 异 象 中 ， 带 我 到 耶 路 撒 冷 朝 北 的 内 院 门 口 ， 在 那 里 有 触 动 主 怒 偶 像 的 坐 位 ， 就 是 惹 动 忌 邪 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20609', '26', '8', '4', '谁 知 ， 在 那 里 有 以 色 列 神 的 荣 耀 ， 形 状 与 我 在 平 原 所 见 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20610', '26', '8', '5', '神 对 我 说 ： “ 人 子 啊 ， 你 举 目 向 北 观 看 。 ” 我 就 举 目 向 北 观 看 ， 见 祭 坛 门 的 北 边 ， 在 门 口 有 这 惹 忌 邪 的 偶 像 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20611', '26', '8', '6', '又 对 我 说 ： “ 人 子 啊 ， 以 色 列 家 所 行 的 ， 就 是 在 此 行 这 大 可 憎 的 事 ， 使 我 远 离 我 的 圣 所 ， 你 看 见 了 吗 ？ 你 还 要 看 见 另 有 大 可 憎 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20612', '26', '8', '7', '他 领 我 到 院 门 口 。 我 观 看 ， 见 墙 上 有 个 窟 窿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20613', '26', '8', '8', '他 对 我 说 ： “ 人 子 啊 ， 你 要 挖 墙 。 ” 我 一 挖 墙 ， 见 有 一 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20614', '26', '8', '9', '他 说 ： “ 你 进 去 ， 看 他 们 在 这 里 所 行 可 憎 的 恶 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20615', '26', '8', '10', '我 进 去 一 看 ， 谁 知 ， 在 四 面 墙 上 画 着 各 样 爬 物 和 可 憎 的 走 兽 ， 并 以 色 列 家 一 切 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20616', '26', '8', '11', '在 这 些 像 前 有 以 色 列 家 的 七 十 个 长 老 站 立 ， 沙 番 的 儿 子 雅 撒 尼 亚 也 站 在 其 中 。 各 人 手 拿 香 炉 ， 烟 云 的 香 气 上 腾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20617', '26', '8', '12', '他 对 我 说 ： “ 人 子 啊 ， 以 色 列 家 的 长 老 暗 中 在 各 人 画 像 屋 里 所 行 的 ， 你 看 见 了 吗 ？ 他 们 常 说 ： ‘ 耶 和 华 看 不 见 我 们 ； 耶 和 华 已 经 离 弃 这 地 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20618', '26', '8', '13', '他 又 说 ： “ 你 还 要 看 见 他 们 另 外 行 大 可 憎 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20619', '26', '8', '14', '他 领 我 到 耶 和 华 殿 外 院 朝 北 的 门 口 。 谁 知 ， 在 那 里 有 妇 女 坐 着 ， 为 搭 模 斯 哭 泣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20620', '26', '8', '15', '他 对 我 说 ： “ 人 子 啊 ， 你 看 见 了 吗 ？ 你 还 要 看 见 比 这 更 可 憎 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20621', '26', '8', '16', '他 又 领 我 到 耶 和 华 殿 的 内 院 。 谁 知 ， 在 耶 和 华 的 殿 门 口 、 廊 子 和 祭 坛 中 间 ， 约 有 二 十 五 个 人 背 向 耶 和 华 的 殿 ， 面 向 东 方 拜 日 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20622', '26', '8', '17', '他 对 我 说 ： “ 人 子 啊 ， 你 看 见 了 吗 ？ 犹 大 家 在 此 行 这 可 憎 的 事 还 算 为 小 吗 ？ 他 们 在 这 地 遍 行 强 暴 ， 再 三 惹 我 发 怒 ， 他 们 手 拿 枝 条 举 向 鼻 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20623', '26', '8', '18', '因 此 ， 我 也 要 以 忿 怒 行 事 ， 我 眼 必 不 顾 惜 ， 也 不 可 怜 他 们 ； 他 们 虽 向 我 耳 中 大 声 呼 求 ， 我 还 是 不 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20624', '26', '9', '1', '＜ 耶 路 撒 冷 受 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20625', '26', '9', '2', '忽 然 有 六 个 人 从 朝 北 的 上 门 而 来 ， 各 人 手 拿 杀 人 的 兵 器 ； 内 中 有 一 人 身 穿 细 麻 衣 ， 腰 间 带 着 墨 盒 子 。 他 们 进 来 ， 站 在 铜 祭 坛 旁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20626', '26', '9', '3', '以 色 列 神 的 荣 耀 本 在 基 路 伯 上 ， 现 今 从 那 里 升 到 殿 的 门 槛 。 神 将 那 身 穿 细 麻 衣 、 腰 间 带 着 墨 盒 子 的 人 召 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20627', '26', '9', '4', '耶 和 华 对 他 说 ： “ 你 去 走 遍 耶 路 撒 冷 全 城 ， 那 些 因 城 中 所 行 可 憎 之 事 叹 息 哀 哭 的 人 ， 画 记 号 在 额 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20628', '26', '9', '5', '我 耳 中 听 见 他 对 其 余 的 人 说 ： “ 要 跟 随 他 走 遍 全 城 ， 以 行 击 杀 。 你 们 的 眼 不 要 顾 惜 ， 也 不 要 可 怜 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20629', '26', '9', '6', '要 将 年 老 的 、 年 少 的 ， 并 处 女 、 婴 孩 ， 和 妇 女 ， 从 圣 所 起 全 都 杀 尽 ， 只 是 凡 有 记 号 的 人 不 要 挨 近 他 。 ” 于 是 他 们 从 殿 前 的 长 老 杀 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20630', '26', '9', '7', '他 对 他 们 说 ： “ 要 污 秽 这 殿 ， 使 院 中 充 满 被 杀 的 人 。 你 们 出 去 吧 ！ ” 他 们 就 出 去 ， 在 城 中 击 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20631', '26', '9', '8', '他 们 击 杀 的 时 候 ， 我 被 留 下 ， 我 就 俯 伏 在 地 ， 说 ： “ 哎 ！ 主 耶 和 华 啊 ， 你 将 忿 怒 倾 在 耶 路 撒 冷 ， 岂 要 将 以 色 列 所 剩 下 的 人 都 灭 绝 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20632', '26', '9', '9', '他 对 我 说 ： “ 以 色 列 家 和 犹 大 家 的 罪 孽 极 其 重 大 。 遍 地 有 流 血 的 事 ， 满 城 有 冤 屈 ， 因 为 他 们 说 ： ‘ 耶 和 华 已 经 离 弃 这 地 ， 他 看 不 见 我 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20633', '26', '9', '10', '故 此 ， 我 眼 必 不 顾 惜 ， 也 不 可 怜 他 们 ， 要 照 他 们 所 行 的 报 应 在 他 们 头 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20634', '26', '9', '11', '那 穿 细 麻 衣 、 腰 间 带 着 墨 盒 子 的 人 将 这 事 回 覆 说 ： “ 我 已 经 照 你 所 吩 咐 的 行 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20635', '26', '10', '1', '＜ 耶 和 华 的 荣 耀 离 开 圣 城 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20636', '26', '10', '2', '主 对 那 穿 细 麻 衣 的 人 说 ： “ 你 进 去 ， 在 旋 转 的 轮 内 基 路 伯 以 下 ， 从 基 路 伯 中 间 将 火 炭 取 满 两 手 ， 撒 在 城 上 。 ” 我 就 见 他 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20637', '26', '10', '3', '那 人 进 去 的 时 候 ， 基 路 伯 站 在 殿 的 右 边 ， 云 彩 充 满 了 内 院 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20638', '26', '10', '4', '耶 和 华 的 荣 耀 从 基 路 伯 那 里 上 升 ， 停 在 门 槛 以 上 ； 殿 内 满 了 云 彩 ， 院 宇 也 被 耶 和 华 荣 耀 的 光 辉 充 满 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20639', '26', '10', '5', '基 路 伯 翅 膀 的 响 声 听 到 外 院 ， 好 像 全 能 神 说 话 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20640', '26', '10', '6', '他 吩 咐 那 穿 细 麻 衣 的 人 说 ： “ 要 从 旋 转 的 轮 内 基 路 伯 中 间 取 火 。 ” 那 人 就 进 去 站 在 一 个 轮 子 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20641', '26', '10', '7', '有 一 个 基 路 伯 从 基 路 伯 中 伸 手 到 基 路 伯 中 间 的 火 那 里 ， 取 些 放 在 那 穿 细 麻 衣 的 人 两 手 中 ， 那 人 就 拿 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20642', '26', '10', '8', '在 基 路 伯 翅 膀 之 下 ， 显 出 有 人 手 的 样 式 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20643', '26', '10', '9', '我 又 观 看 ， 见 基 路 伯 旁 边 有 四 个 轮 子 。 这 基 路 伯 旁 有 一 个 轮 子 ， 那 基 路 伯 旁 有 一 个 轮 子 ， 每 基 路 伯 都 是 如 此 ； 轮 子 的 颜 色 ｛ 原 文 是 形 状 ｝ 仿 佛 水 苍 玉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20644', '26', '10', '10', '至 于 四 轮 的 形 状 ， 都 是 一 个 样 式 ， 仿 佛 轮 中 套 轮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20645', '26', '10', '11', '轮 行 走 的 时 候 ， 向 四 方 都 能 直 行 ， 并 不 掉 转 。 头 向 何 方 ， 他 们 也 随 向 何 方 ， 行 走 的 时 候 并 不 掉 转 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20646', '26', '10', '12', '他 们 全 身 ， 连 背 带 手 和 翅 膀 ， 并 轮 周 围 都 满 了 眼 睛 。 这 四 个 基 路 伯 的 轮 子 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20647', '26', '10', '13', '至 于 这 些 轮 子 ， 我 耳 中 听 见 说 是 旋 转 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20648', '26', '10', '14', '基 路 伯 各 有 四 脸 ： 第 一 是 基 路 伯 的 脸 ， 第 二 是 人 的 脸 ， 第 三 是 狮 子 的 脸 ， 第 四 是 鹰 的 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20649', '26', '10', '15', '基 路 伯 升 上 去 了 ； 这 是 我 在 迦 巴 鲁 河 边 所 见 的 活 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20650', '26', '10', '16', '基 路 伯 行 走 ， 轮 也 在 旁 边 行 走 。 基 路 伯 展 开 翅 膀 ， 离 地 上 升 ， 轮 也 不 转 离 他 们 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20651', '26', '10', '17', '那 些 站 住 ， 这 些 也 站 住 ； 那 些 上 升 ， 这 些 也 一 同 上 升 ， 因 为 活 物 的 灵 在 轮 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20652', '26', '10', '18', '耶 和 华 的 荣 耀 从 殿 的 门 槛 那 里 出 去 ， 停 在 基 路 伯 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20653', '26', '10', '19', '基 路 伯 出 去 的 时 候 ， 就 展 开 翅 膀 ， 在 我 眼 前 离 地 上 升 。 轮 也 在 他 们 的 旁 边 ， 都 停 在 耶 和 华 殿 的 东 门 口 。 在 他 们 以 上 有 以 色 列 神 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20654', '26', '10', '20', '这 是 我 在 迦 巴 鲁 河 边 所 见 、 以 色 列 神 荣 耀 以 下 的 活 物 ， 我 就 知 道 他 们 是 基 路 伯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20655', '26', '10', '21', '各 有 四 个 脸 面 ， 四 个 翅 膀 ， 翅 膀 以 下 有 人 手 的 样 式 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20656', '26', '10', '22', '至 于 他 们 脸 的 模 样 ， 并 身 体 的 形 像 ， 是 我 从 前 在 迦 巴 鲁 河 边 所 看 见 的 。 他 们 俱 各 直 往 前 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20657', '26', '11', '1', '＜ 耶 路 撒 冷 被 判 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20658', '26', '11', '2', '耶 和 华 对 我 说 ： “ 人 子 啊 ， 这 就 是 图 谋 罪 孽 的 人 ， 在 这 城 中 给 人 设 恶 谋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20659', '26', '11', '3', '他 们 说 ： ‘ 盖 房 屋 的 时 候 尚 未 临 近 ； 这 城 是 锅 ， 我 们 是 肉 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20660', '26', '11', '4', '人 子 啊 ， 因 此 你 当 说 预 言 ， 说 预 言 攻 击 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20661', '26', '11', '5', '耶 和 华 的 灵 降 在 我 身 上 ， 对 我 说 ： “ 你 当 说 ， 耶 和 华 如 此 说 ： 以 色 列 家 啊 ， 你 们 口 中 所 说 的 ， 心 里 所 想 的 ， 我 都 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20662', '26', '11', '6', '你 们 在 这 城 中 杀 人 增 多 ， 使 被 杀 的 人 充 满 街 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20663', '26', '11', '7', '所 以 主 耶 和 华 如 此 说 ： 你 们 杀 在 城 中 的 人 就 是 肉 ， 这 城 就 是 锅 ； 你 们 却 要 从 其 中 被 带 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20664', '26', '11', '8', '你 们 怕 刀 剑 ， 我 必 使 刀 剑 临 到 你 们 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20665', '26', '11', '9', '我 必 从 这 城 中 带 出 你 们 去 ， 交 在 外 邦 人 的 手 中 ， 且 要 在 你 们 中 间 施 行 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20666', '26', '11', '10', '你 们 必 倒 在 刀 下 ； 我 必 在 以 色 列 的 境 界 审 判 你 们 ， 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20667', '26', '11', '11', '这 城 必 不 作 你 们 的 锅 ， 你 们 也 不 作 其 中 的 肉 。 我 必 在 以 色 列 的 境 界 审 判 你 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20668', '26', '11', '12', '你 们 就 知 道 我 是 耶 和 华 ； 因 为 你 们 没 有 遵 行 我 的 律 例 ， 也 没 有 顺 从 我 的 典 章 ， 却 随 从 你 们 四 围 列 国 的 恶 规 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20669', '26', '11', '13', '我 正 说 预 言 的 时 候 ， 比 拿 雅 的 儿 子 毗 拉 提 死 了 。 于 是 我 俯 伏 在 地 ， 大 声 呼 叫 说 ： “ 哎 ！ 主 耶 和 华 啊 ， 你 要 将 以 色 列 剩 下 的 人 灭 绝 净 尽 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20670', '26', '11', '14', '＜ 神 对 流 亡 者 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20671', '26', '11', '15', '“ 人 子 啊 ， 耶 路 撒 冷 的 居 民 对 你 的 弟 兄 、 你 的 本 族 、 你 的 亲 属 、 以 色 列 全 家 ， 就 是 对 大 众 说 ： ‘ 你 们 远 离 耶 和 华 吧 ！ 这 地 是 赐 给 我 们 为 业 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20672', '26', '11', '16', '所 以 你 当 说 ： ‘ 耶 和 华 如 此 说 ： 我 虽 将 以 色 列 全 家 远 远 迁 移 到 列 国 中 ， 将 他 们 分 散 在 列 邦 内 ， 我 还 要 在 他 们 所 到 的 列 邦 ， 暂 作 他 们 的 圣 所 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20673', '26', '11', '17', '你 当 说 ： ‘ 主 耶 和 华 如 此 说 ： 我 必 从 万 民 中 招 聚 你 们 ， 从 分 散 的 列 国 内 聚 集 你 们 ， 又 要 将 以 色 列 地 赐 给 你 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20674', '26', '11', '18', '他 们 必 到 那 里 ， 也 必 从 其 中 除 掉 一 切 可 憎 可 厌 的 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20675', '26', '11', '19', '我 要 使 他 们 有 合 一 的 心 ， 也 要 将 新 灵 放 在 他 们 里 面 ， 又 从 他 们 肉 体 中 除 掉 石 心 ， 赐 给 他 们 肉 心 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20676', '26', '11', '20', '使 他 们 顺 从 我 的 律 例 ， 谨 守 遵 行 我 的 典 章 。 他 们 要 作 我 的 子 民 ， 我 要 作 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20677', '26', '11', '21', '至 于 那 些 心 中 随 从 可 憎 可 厌 之 物 的 ， 我 必 照 他 们 所 行 的 报 应 在 他 们 头 上 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20678', '26', '11', '22', '＜ 神 的 荣 耀 离 开 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20679', '26', '11', '23', '耶 和 华 的 荣 耀 从 城 中 上 升 ， 停 在 城 东 的 那 座 山 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20680', '26', '11', '24', '灵 将 我 举 起 ， 在 异 象 中 藉 着 神 的 灵 将 我 带 进 迦 勒 底 地 ， 到 被 掳 的 人 那 里 ； 我 所 见 的 异 象 就 离 我 上 升 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20681', '26', '11', '25', '我 便 将 耶 和 华 所 指 示 我 的 一 切 事 都 说 给 被 掳 的 人 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20682', '26', '12', '1', '＜ 先 知 扮 演 难 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20683', '26', '12', '2', '“ 人 子 啊 ， 你 住 在 悖 逆 的 家 中 。 他 们 有 眼 睛 看 不 见 ， 有 耳 朵 听 不 见 ， 因 为 他 们 是 悖 逆 之 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20684', '26', '12', '3', '所 以 人 子 啊 ， 你 要 预 备 掳 去 使 用 的 物 件 ， 在 白 日 当 他 们 眼 前 从 你 所 住 的 地 方 移 到 别 处 去 ； 他 们 虽 是 悖 逆 之 家 ， 或 者 可 以 揣 摩 思 想 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20685', '26', '12', '4', '你 要 在 白 日 当 他 们 眼 前 带 出 你 的 物 件 去 ， 好 像 预 备 掳 去 使 用 的 物 件 。 到 了 晚 上 ， 你 要 在 他 们 眼 前 亲 自 出 去 ， 像 被 掳 的 人 出 去 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20686', '26', '12', '5', '你 要 在 他 们 眼 前 挖 通 了 墙 ， 从 其 中 将 物 件 带 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20687', '26', '12', '6', '到 天 黑 时 ， 你 要 当 他 们 眼 前 搭 在 肩 头 上 带 出 去 ， 并 要 蒙 住 脸 看 不 见 地 ， 因 为 我 立 你 作 以 色 列 家 的 预 兆 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20688', '26', '12', '7', '我 就 照 着 所 吩 咐 的 去 行 ， 白 日 带 出 我 的 物 件 ， 好 像 预 备 掳 去 使 用 的 物 件 。 到 了 晚 上 ， 我 用 手 挖 通 了 墙 。 天 黑 的 时 候 ， 就 当 他 们 眼 前 搭 在 肩 头 上 带 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20689', '26', '12', '8', '次 日 早 晨 ， 耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20690', '26', '12', '9', '“ 人 子 啊 ， 以 色 列 家 ， 就 是 那 悖 逆 之 家 ， 岂 不 是 问 你 说 ： ‘ 你 做 什 么 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20691', '26', '12', '10', '你 要 对 他 们 说 ： ‘ 主 耶 和 华 如 此 说 ： 这 是 关 乎 耶 路 撒 冷 的 君 王 和 他 周 围 以 色 列 全 家 的 预 表 ｛ 原 文 是 担 子 ｝ 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20692', '26', '12', '11', '你 要 说 ： ‘ 我 作 你 们 的 预 兆 ： 我 怎 样 行 ， 他 们 所 遭 遇 的 也 必 怎 样 ， 他 们 必 被 掳 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20693', '26', '12', '12', '他 们 中 间 的 君 王 也 必 在 天 黑 的 时 候 将 物 件 搭 在 肩 头 上 带 出 去 。 他 们 要 挖 通 了 墙 ， 从 其 中 带 出 去 。 他 必 蒙 住 脸 ， 眼 看 不 见 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20694', '26', '12', '13', '我 必 将 我 的 网 撒 在 他 身 上 ， 他 必 在 我 的 网 罗 中 缠 住 。 我 必 带 他 到 迦 勒 底 人 之 地 的 巴 比 伦 ； 他 虽 死 在 那 里 ， 却 看 不 见 那 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20695', '26', '12', '14', '周 围 一 切 帮 助 他 的 和 他 所 有 的 军 队 ， 我 必 分 散 四 方 ｛ 方 ： 原 文 是 风 ｝ ， 也 要 拔 刀 追 赶 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20696', '26', '12', '15', '我 将 他 们 四 散 在 列 国 、 分 散 在 列 邦 的 时 候 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20697', '26', '12', '16', '我 却 要 留 下 他 们 几 个 人 得 免 刀 剑 、 饥 荒 、 瘟 疫 ， 使 他 们 在 所 到 的 各 国 中 述 说 他 们 一 切 可 憎 的 事 ， 人 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20698', '26', '12', '17', '＜ 先 知 扮 演 惊 惶 战 栗 的 情 况 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20699', '26', '12', '18', '“ 人 子 啊 ， 你 吃 饭 必 胆 战 ， 喝 水 必 惶 惶 忧 虑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20700', '26', '12', '19', '你 要 对 这 地 的 百 姓 说 ： 主 耶 和 华 论 耶 路 撒 冷 和 以 色 列 地 的 居 民 如 此 说 ， 他 们 吃 饭 必 忧 虑 ， 喝 水 必 惊 惶 。 因 其 中 居 住 的 众 人 所 行 强 暴 的 事 ， 这 地 必 然 荒 废 ， 一 无 所 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20701', '26', '12', '20', '有 居 民 的 城 邑 必 变 为 荒 场 ， 地 也 必 变 为 荒 废 ； 你 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20702', '26', '12', '21', '＜ 平 凡 的 俗 语 和 非 凡 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20703', '26', '12', '22', '“ 人 子 啊 ， 在 你 们 以 色 列 地 怎 么 有 这 俗 语 ， 说 ‘ 日 子 迟 延 ， 一 切 异 象 都 落 了 空 ’ 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20704', '26', '12', '23', '你 要 告 诉 他 们 说 ： ‘ 主 耶 和 华 如 此 说 ： 我 必 使 这 俗 语 止 息 ， 以 色 列 中 不 再 用 这 俗 语 。 ’ 你 却 要 对 他 们 说 ： ‘ 日 子 临 近 ， 一 切 的 异 象 必 都 应 验 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20705', '26', '12', '24', '从 此 ， 在 以 色 列 家 中 必 不 再 有 虚 假 的 异 象 和 奉 承 的 占 卜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20706', '26', '12', '25', '我 ─ ─ 耶 和 华 说 话 ， 所 说 的 必 定 成 就 ， 不 再 耽 延 。 你 们 这 悖 逆 之 家 ， 我 所 说 的 话 必 趁 你 们 在 世 的 日 子 成 就 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20707', '26', '12', '26', '耶 和 华 的 话 又 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20708', '26', '12', '27', '“ 人 子 啊 ， 以 色 列 家 的 人 说 ： ‘ 他 所 见 的 异 象 是 关 乎 后 来 许 多 的 日 子 ， 所 说 的 预 言 是 指 着 极 远 的 时 候 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20709', '26', '12', '28', '所 以 你 要 对 他 们 说 ： ‘ 主 耶 和 华 如 此 说 ： 我 的 话 没 有 一 句 再 耽 延 的 ， 我 所 说 的 必 定 成 就 。 这 是 主 耶 和 华 说 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20710', '26', '13', '1', '＜ 斥 责 假 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20711', '26', '13', '2', '“ 人 子 啊 ， 你 要 说 预 言 攻 击 以 色 列 中 说 预 言 的 先 知 ， 对 那 些 本 己 心 发 预 言 的 说 ： ‘ 你 们 当 听 耶 和 华 的 话 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20712', '26', '13', '3', '主 耶 和 华 如 此 说 ： “ 愚 顽 的 先 知 有 祸 了 ， 他 们 随 从 自 己 的 心 意 ， 却 一 无 所 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20713', '26', '13', '4', '以 色 列 啊 ， 你 的 先 知 好 像 荒 场 中 的 狐 狸 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20714', '26', '13', '5', '没 有 上 去 堵 挡 破 口 ， 也 没 有 为 以 色 列 家 重 修 墙 垣 ， 使 他 们 当 耶 和 华 的 日 子 在 阵 上 站 立 得 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20715', '26', '13', '6', '这 些 人 所 见 的 是 虚 假 ， 是 谎 诈 的 占 卜 。 他 们 说 是 耶 和 华 说 的 ， 其 实 耶 和 华 并 没 有 差 遣 他 们 ， 他 们 倒 使 人 指 望 那 话 必 然 立 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20716', '26', '13', '7', '你 们 岂 不 是 见 了 虚 假 的 异 象 吗 ？ 岂 不 是 说 了 谎 诈 的 占 卜 吗 ？ 你 们 说 ， 这 是 耶 和 华 说 的 ， 其 实 我 没 有 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20717', '26', '13', '8', '所 以 主 耶 和 华 如 此 说 ： “ 因 你 们 说 的 是 虚 假 ， 见 的 是 谎 诈 ， 我 就 与 你 们 反 对 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20718', '26', '13', '9', '我 的 手 必 攻 击 那 见 虚 假 异 象 、 用 谎 诈 占 卜 的 先 知 ， 他 们 必 不 列 在 我 百 姓 的 会 中 ， 不 录 在 以 色 列 家 的 册 上 ， 也 不 进 入 以 色 列 地 ； 你 们 就 知 道 我 是 主 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20719', '26', '13', '10', '因 为 他 们 诱 惑 我 的 百 姓 ， 说 ： ‘ 平 安 ！ ’ 其 实 没 有 平 安 ， 就 像 有 人 立 起 墙 壁 ， 他 们 倒 用 未 泡 透 的 灰 抹 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20720', '26', '13', '11', '所 以 你 要 对 那 些 抹 上 未 泡 透 灰 的 人 说 ： ‘ 墙 要 倒 塌 ， 必 有 暴 雨 漫 过 。 大 冰 雹 啊 ， 你 们 要 降 下 ， 狂 风 也 要 吹 裂 这 墙 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20721', '26', '13', '12', '这 墙 倒 塌 之 后 ， 人 岂 不 问 你 们 说 ： ‘ 你 们 抹 上 未 泡 透 的 灰 在 哪 里 呢 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20722', '26', '13', '13', '所 以 主 耶 和 华 如 此 说 ： “ 我 要 发 怒 ， 使 狂 风 吹 裂 这 墙 ， 在 怒 中 使 暴 雨 漫 过 ， 又 发 怒 降 下 大 冰 雹 ， 毁 灭 这 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20723', '26', '13', '14', '我 要 这 样 拆 毁 你 们 那 未 泡 透 灰 所 抹 的 墙 ， 拆 平 到 地 ， 以 致 根 基 露 出 ， 墙 必 倒 塌 ， 你 们 也 必 在 其 中 灭 亡 ； 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20724', '26', '13', '15', '我 要 这 样 向 墙 和 用 未 泡 透 灰 抹 墙 的 人 成 就 我 怒 中 所 定 的 ， 并 要 对 你 们 说 ： ‘ 墙 和 抹 墙 的 人 都 没 有 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20725', '26', '13', '16', '这 抹 墙 的 就 是 以 色 列 的 先 知 ， 他 们 指 着 耶 路 撒 冷 说 预 言 ， 为 这 城 见 了 平 安 的 异 象 ， 其 实 没 有 平 安 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20726', '26', '13', '17', '＜ 斥 责 假 的 女 先 知 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20727', '26', '13', '18', '说 主 耶 和 华 如 此 说 ： ‘ 这 些 妇 女 有 祸 了 ！ 她 们 为 众 人 的 膀 臂 缝 靠 枕 ， 给 高 矮 之 人 做 下 垂 的 头 巾 ， 为 要 猎 取 人 的 性 命 。 难 道 你 们 要 猎 取 我 百 姓 的 性 命 ， 为 利 己 将 人 救 活 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20728', '26', '13', '19', '你 们 为 两 把 大 麦 ， 为 几 块 饼 ， 在 我 民 中 亵 渎 我 ， 对 肯 听 谎 言 的 民 说 谎 ， 杀 死 不 该 死 的 人 ， 救 活 不 该 活 的 人 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20729', '26', '13', '20', '所 以 主 耶 和 华 如 此 说 ： “ 看 哪 ， 我 与 你 们 的 靠 枕 反 对 ， 就 是 你 们 用 以 猎 取 人 、 使 人 的 性 命 如 鸟 飞 的 。 我 要 将 靠 枕 从 你 们 的 膀 臂 上 扯 去 ， 释 放 你 们 猎 取 如 鸟 飞 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20730', '26', '13', '21', '我 也 必 撕 裂 你 们 下 垂 的 头 巾 ， 救 我 百 姓 脱 离 你 们 的 手 ， 不 再 被 猎 取 ， 落 在 你 们 手 中 。 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20731', '26', '13', '22', '我 不 使 义 人 伤 心 ， 你 们 却 以 谎 话 使 他 伤 心 ， 又 坚 固 恶 人 的 手 ， 使 他 不 回 头 离 开 恶 道 得 以 救 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20732', '26', '13', '23', '你 们 就 不 再 见 虚 假 的 异 象 ， 也 不 再 行 占 卜 的 事 ； 我 必 救 我 的 百 姓 脱 离 你 们 的 手 ； 你 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20733', '26', '14', '1', '＜ 神 斥 责 拜 偶 像 的 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20734', '26', '14', '2', '耶 和 华 的 话 就 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20735', '26', '14', '3', '“ 人 子 啊 ， 这 些 人 已 将 他 们 的 假 神 接 到 心 里 ， 把 陷 于 罪 的 绊 脚 石 放 在 面 前 ， 我 岂 能 丝 毫 被 他 们 求 问 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20736', '26', '14', '4', '所 以 你 要 告 诉 他 们 ： ‘ 主 耶 和 华 如 此 说 ： 以 色 列 家 的 人 中 ， 凡 将 他 的 假 神 接 到 心 里 ， 把 陷 于 罪 的 绊 脚 石 放 在 面 前 ， 又 就 了 先 知 来 的 ， 我 ─ ─ 耶 和 华 在 他 所 求 的 事 上 ， 必 按 他 众 多 的 假 神 回 答 他 ｛ 或 译 ： 必 按 他 拜 许 多 假 神 的 罪 报 应 他 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20737', '26', '14', '5', '好 在 以 色 列 家 的 心 事 上 捉 住 他 们 ， 因 为 他 们 都 藉 着 假 神 与 我 生 疏 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20738', '26', '14', '6', '“ 所 以 你 要 告 诉 以 色 列 家 说 ： ‘ 主 耶 和 华 如 此 说 ： 回 头 吧 ！ 离 开 你 们 的 偶 像 ， 转 脸 莫 从 你 们 一 切 可 憎 的 事 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20739', '26', '14', '7', '因 为 以 色 列 家 的 人 ， 或 在 以 色 列 中 寄 居 的 外 人 ， 凡 与 我 隔 绝 ， 将 他 的 假 神 接 到 心 里 ， 把 陷 于 罪 的 绊 脚 石 放 在 面 前 ， 又 就 了 先 知 来 要 为 自 己 的 事 求 问 我 的 ， 我 ─ ─ 耶 和 华 必 亲 自 回 答 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20740', '26', '14', '8', '我 必 向 那 人 变 脸 ， 使 他 作 了 警 戒 ， 笑 谈 ， 令 人 惊 骇 ， 并 且 我 要 将 他 从 我 民 中 剪 除 ； 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20741', '26', '14', '9', '先 知 若 被 迷 惑 说 一 句 预 言 ， 是 我 ─ ─ 耶 和 华 任 那 先 知 受 迷 惑 ， 我 也 必 向 他 伸 手 ， 将 他 从 我 民 以 色 列 中 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20742', '26', '14', '10', '他 们 必 担 当 自 己 的 罪 孽 。 先 知 的 罪 孽 和 求 问 之 人 的 罪 孽 都 是 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20743', '26', '14', '11', '好 使 以 色 列 家 不 再 走 迷 离 开 我 ， 不 再 因 各 样 的 罪 过 玷 污 自 己 ， 只 要 作 我 的 子 民 ， 我 作 他 们 的 神 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20744', '26', '14', '12', '＜ 挪 亚 、 但 以 理 、 约 伯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20745', '26', '14', '13', '“ 人 子 啊 ， 若 有 一 国 犯 罪 干 犯 我 ， 我 也 向 他 伸 手 折 断 他 们 的 杖 ， 就 是 断 绝 他 们 的 粮 ， 使 饥 荒 临 到 那 地 ， 将 人 与 牲 畜 从 其 中 剪 除 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20746', '26', '14', '14', '其 中 虽 有 挪 亚 、 但 以 理 、 约 伯 这 三 人 ， 他 们 只 能 因 他 们 的 义 救 自 己 的 性 命 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20747', '26', '14', '15', '我 若 使 恶 兽 经 过 糟 践 那 地 ， 使 地 荒 凉 ， 以 致 因 这 些 兽 ， 人 都 不 得 经 过 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20748', '26', '14', '16', '虽 有 这 三 人 在 其 中 ， 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 他 们 连 儿 带 女 都 不 能 得 救 ， 只 能 自 己 得 救 ， 那 地 仍 然 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20749', '26', '14', '17', '或 者 我 使 刀 剑 临 到 那 地 ， 说 ： 刀 剑 哪 ， 要 经 过 那 地 ， 以 致 我 将 人 与 牲 畜 从 其 中 剪 除 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20750', '26', '14', '18', '虽 有 这 三 人 在 其 中 ， 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 他 们 连 儿 带 女 都 不 能 得 救 ， 只 能 自 己 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20751', '26', '14', '19', '或 者 我 叫 瘟 疫 流 行 那 地 ， 使 我 灭 命 ｛ 原 文 是 带 血 ｝ 的 忿 怒 倾 在 其 上 ， 好 将 人 与 牲 畜 从 其 中 剪 除 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20752', '26', '14', '20', '虽 有 挪 亚 、 但 以 理 、 约 伯 在 其 中 ， 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 他 们 连 儿 带 女 都 不 能 救 ， 只 能 因 他 们 的 义 救 自 己 的 性 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20753', '26', '14', '21', '主 耶 和 华 如 此 说 ： “ 我 将 这 四 样 大 灾 ─ ─ 就 是 刀 剑 、 饥 荒 、 恶 兽 、 瘟 疫 降 在 耶 路 撒 冷 ， 将 人 与 牲 畜 从 其 中 剪 除 ， 岂 不 更 重 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20754', '26', '14', '22', '然 而 其 中 必 有 剩 下 的 人 ， 他 们 连 儿 带 女 必 带 到 你 们 这 里 来 ， 你 们 看 见 他 们 所 行 所 为 的 ， 要 因 我 降 给 耶 路 撒 冷 的 一 切 灾 祸 ， 便 得 了 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20755', '26', '14', '23', '你 们 看 见 他 们 所 行 所 为 的 ， 得 了 安 慰 ， 就 知 道 我 在 耶 路 撒 冷 中 所 行 的 并 非 无 故 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20756', '26', '15', '1', '＜ 葡 萄 树 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20757', '26', '15', '2', '“ 人 子 啊 ， 葡 萄 树 比 别 样 树 有 什 么 强 处 ？ 葡 萄 枝 比 众 树 枝 有 什 么 好 处 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20758', '26', '15', '3', '其 上 可 以 取 木 料 做 什 么 工 用 ， 可 以 取 来 做 钉 子 挂 什 么 器 皿 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20759', '26', '15', '4', '看 哪 ， 已 经 抛 在 火 中 当 作 柴 烧 ， 火 既 烧 了 两 头 ， 中 间 也 被 烧 了 ， 还 有 益 于 工 用 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20760', '26', '15', '5', '完 全 的 时 候 尚 且 不 合 乎 什 么 工 用 ， 何 况 被 火 烧 坏 ， 还 能 合 乎 什 么 工 用 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20761', '26', '15', '6', '所 以 ， 主 耶 和 华 如 此 说 ： “ 众 树 以 内 的 葡 萄 树 ， 我 怎 样 使 它 在 火 中 当 柴 ， 也 必 照 样 待 耶 路 撒 冷 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20762', '26', '15', '7', '我 必 向 他 们 变 脸 ； 他 们 虽 从 火 中 出 来 ， 火 却 要 烧 灭 他 们 。 我 向 他 们 变 脸 的 时 候 ， 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20763', '26', '15', '8', '我 必 使 地 土 荒 凉 ， 因 为 他 们 行 事 干 犯 我 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20764', '26', '16', '1', '＜ 不 忠 实 的 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20765', '26', '16', '2', '“ 人 子 啊 ， 你 要 使 耶 路 撒 冷 知 道 她 那 些 可 憎 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20766', '26', '16', '3', '说 主 耶 和 华 对 耶 路 撒 冷 如 此 说 ： 你 根 本 ， 你 出 世 ， 是 在 迦 南 地 ； 你 父 亲 是 亚 摩 利 人 ， 你 母 亲 是 赫 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20767', '26', '16', '4', '论 到 你 出 世 的 景 况 ， 在 你 初 生 的 日 子 没 有 为 你 断 脐 带 ， 也 没 有 用 水 洗 你 ， 使 你 洁 净 ， 丝 毫 没 有 撒 盐 在 你 身 上 ， 也 没 有 用 布 裹 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20768', '26', '16', '5', '谁 的 眼 也 不 可 怜 你 ， 为 你 做 一 件 这 样 的 事 怜 恤 你 ； 但 你 初 生 的 日 子 扔 在 田 野 ， 是 因 你 被 厌 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20769', '26', '16', '6', '“ 我 从 你 旁 边 经 过 ， 见 你 滚 在 血 中 ， 就 对 你 说 ： 你 虽 在 血 中 ， 仍 可 存 活 ； 你 虽 在 血 中 ， 仍 可 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20770', '26', '16', '7', '我 使 你 生 长 好 像 田 间 所 长 的 ， 你 就 渐 渐 长 大 ， 以 致 极 其 俊 美 ， 两 乳 成 形 ， 头 发 长 成 ， 你 却 仍 然 赤 身 露 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20771', '26', '16', '8', '“ 我 从 你 旁 边 经 过 ， 看 见 你 的 时 候 正 动 爱 情 ， 便 用 衣 襟 搭 在 你 身 上 ， 遮 盖 你 的 赤 体 ； 又 向 你 起 誓 ， 与 你 结 盟 ， 你 就 归 于 我 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20772', '26', '16', '9', '那 时 我 用 水 洗 你 ， 洗 净 你 身 上 的 血 ， 又 用 油 抹 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20773', '26', '16', '10', '我 也 使 你 身 穿 绣 花 衣 服 ， 脚 穿 海 狗 皮 鞋 ， 并 用 细 麻 布 给 你 束 腰 ， 用 丝 绸 为 衣 披 在 你 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20774', '26', '16', '11', '又 用 妆 饰 打 扮 你 ， 将 镯 子 戴 在 你 手 上 ， 将 金 链 戴 在 你 项 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20775', '26', '16', '12', '我 也 将 环 子 戴 在 你 鼻 子 上 ， 将 耳 环 戴 在 你 耳 朵 上 ， 将 华 冠 戴 在 你 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20776', '26', '16', '13', '这 样 ， 你 就 有 金 银 的 妆 饰 ， 穿 的 是 细 麻 衣 和 丝 绸 ， 并 绣 花 衣 ； 吃 的 是 细 面 、 蜂 蜜 ， 并 油 。 你 也 极 其 美 貌 ， 发 达 到 王 后 的 尊 荣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20777', '26', '16', '14', '你 美 貌 的 名 声 传 在 列 邦 中 ， 你 十 分 美 貌 ， 是 因 我 加 在 你 身 上 的 威 荣 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20778', '26', '16', '15', '“ 只 是 你 仗 着 自 己 的 美 貌 ， 又 因 你 的 名 声 就 行 邪 淫 。 你 纵 情 淫 乱 ， 使 过 路 的 任 意 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20779', '26', '16', '16', '你 用 衣 服 为 自 己 在 高 处 结 彩 ， 在 其 上 行 邪 淫 。 这 样 的 事 将 来 必 没 有 ， 也 必 不 再 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20780', '26', '16', '17', '你 又 将 我 所 给 你 那 华 美 的 金 银 、 宝 器 为 自 己 制 造 人 像 ， 与 他 行 邪 淫 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20781', '26', '16', '18', '又 用 你 的 绣 花 衣 服 给 他 披 上 ， 并 将 我 的 膏 油 和 香 料 摆 在 他 跟 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20782', '26', '16', '19', '又 将 我 赐 给 你 的 食 物 ， 就 是 我 赐 给 你 吃 的 细 面 、 油 ， 和 蜂 蜜 ， 都 摆 在 他 跟 前 为 馨 香 的 供 物 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20783', '26', '16', '20', '并 且 你 将 给 我 所 生 的 儿 女 焚 献 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20784', '26', '16', '21', '你 行 淫 乱 岂 是 小 事 ， 竟 将 我 的 儿 女 杀 了 ， 使 他 们 经 火 归 与 他 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20785', '26', '16', '22', '你 行 这 一 切 可 憎 和 淫 乱 的 事 ， 并 未 追 念 你 幼 年 赤 身 露 体 滚 在 血 中 的 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20786', '26', '16', '23', '＜ 耶 路 撒 冷 像 淫 妇 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20787', '26', '16', '24', '又 为 自 己 建 造 圆 顶 花 楼 ， 在 各 街 上 做 了 高 台 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20788', '26', '16', '25', '你 在 一 切 市 口 上 建 造 高 台 ， 使 你 的 美 貌 变 为 可 憎 的 ， 又 与 一 切 过 路 的 多 行 淫 乱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20789', '26', '16', '26', '你 也 和 你 邻 邦 放 纵 情 欲 的 埃 及 人 行 淫 ， 加 增 你 的 淫 乱 ， 惹 我 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20790', '26', '16', '27', '因 此 我 伸 手 攻 击 你 ， 减 少 你 应 用 的 粮 食 ， 又 将 你 交 给 恨 你 的 非 利 士 众 女 ｛ 众 女 是 城 邑 的 意 思 ； 本 章 下 同 ｝ ， 使 她 们 任 意 待 你 。 她 们 见 你 的 淫 行 ， 为 你 羞 耻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20791', '26', '16', '28', '你 因 贪 色 无 厌 ， 又 与 亚 述 人 行 淫 ， 与 他 们 行 淫 之 后 ， 仍 不 满 意 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20792', '26', '16', '29', '并 且 多 行 淫 乱 ， 直 到 那 贸 易 之 地 ， 就 是 迦 勒 底 ， 你 仍 不 满 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20793', '26', '16', '30', '主 耶 和 华 说 ： 你 行 这 一 切 事 ， 都 是 不 知 羞 耻 妓 女 所 行 的 ， 可 见 你 的 心 是 何 等 懦 弱 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20794', '26', '16', '31', '因 你 在 一 切 市 口 上 建 造 圆 顶 花 楼 ， 在 各 街 上 做 了 高 台 ， 你 却 藐 视 赏 赐 ， 不 像 妓 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20795', '26', '16', '32', '哎 ！ 你 这 行 淫 的 妻 啊 ， 宁 肯 接 外 人 ， 不 接 丈 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20796', '26', '16', '33', '凡 妓 女 是 得 人 赠 送 ， 你 反 倒 赠 送 你 所 爱 的 人 ， 贿 赂 他 们 从 四 围 来 与 你 行 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20797', '26', '16', '34', '你 行 淫 与 别 的 妇 女 相 反 ， 因 为 不 是 人 从 你 行 淫 ； 你 既 赠 送 人 ， 人 并 不 赠 送 你 ； 所 以 你 与 别 的 妇 女 相 反 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20798', '26', '16', '35', '＜ 神 审 判 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20799', '26', '16', '36', '主 耶 和 华 如 此 说 ： 因 你 的 污 秽 倾 泄 了 ， 你 与 你 所 爱 的 行 淫 露 出 下 体 ， 又 因 你 拜 一 切 可 憎 的 偶 像 ， 流 儿 女 的 血 献 给 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20800', '26', '16', '37', '我 就 要 将 你 一 切 相 欢 相 爱 的 和 你 一 切 所 恨 的 都 聚 集 来 ， 从 四 围 攻 击 你 ； 又 将 你 的 下 体 露 出 ， 使 他 们 看 尽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20801', '26', '16', '38', '我 也 要 审 判 你 ， 好 像 官 长 审 判 淫 妇 和 流 人 血 的 妇 女 一 样 。 我 因 忿 怒 忌 恨 ， 使 流 血 的 罪 归 到 你 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20802', '26', '16', '39', '我 又 要 将 你 交 在 他 们 手 中 ； 他 们 必 拆 毁 你 的 圆 顶 花 楼 ， 毁 坏 你 的 高 台 ， 剥 去 你 的 衣 服 ， 夺 取 你 的 华 美 宝 器 ， 留 下 你 赤 身 露 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20803', '26', '16', '40', '他 们 也 必 带 多 人 来 攻 击 你 ， 用 石 头 打 死 你 ， 用 刀 剑 刺 透 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20804', '26', '16', '41', '用 火 焚 烧 你 的 房 屋 ， 在 许 多 妇 人 眼 前 向 你 施 行 审 判 。 我 必 使 你 不 再 行 淫 ， 也 不 再 赠 送 与 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20805', '26', '16', '42', '这 样 ， 我 就 止 息 向 你 发 的 忿 怒 ， 我 的 忌 恨 也 要 离 开 你 ， 我 要 安 静 不 再 恼 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20806', '26', '16', '43', '因 你 不 追 念 你 幼 年 的 日 子 ， 在 这 一 切 的 事 上 向 我 发 烈 怒 ， 所 以 我 必 照 你 所 行 的 报 应 在 你 头 上 ， 你 就 不 再 贪 淫 ， 行 那 一 切 可 憎 的 事 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20807', '26', '16', '44', '＜ 有 其 母 必 有 其 女 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20808', '26', '16', '45', '你 正 是 你 母 亲 的 女 儿 ， 厌 弃 丈 夫 和 儿 女 ； 你 正 是 你 姊 妹 的 姊 妹 ， 厌 弃 丈 夫 和 儿 女 。 你 母 亲 是 赫 人 ， 你 父 亲 是 亚 摩 利 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20809', '26', '16', '46', '你 的 姊 姊 是 撒 马 利 亚 ， 她 和 她 的 众 女 住 在 你 左 边 ； 你 的 妹 妹 是 所 多 玛 ， 她 和 她 的 众 女 住 在 你 右 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20810', '26', '16', '47', '你 没 有 效 法 她 们 的 行 为 ， 也 没 有 照 她 们 可 憎 的 事 去 做 ， 你 以 那 为 小 事 ， 你 一 切 所 行 的 倒 比 她 们 更 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20811', '26', '16', '48', '主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 你 妹 妹 所 多 玛 与 她 的 众 女 尚 未 行 你 和 你 众 女 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20812', '26', '16', '49', '看 哪 ， 你 妹 妹 所 多 玛 的 罪 孽 是 这 样 ： 她 和 她 的 众 女 都 心 骄 气 傲 ， 粮 食 饱 足 ， 大 享 安 逸 ， 并 没 有 扶 助 困 苦 和 穷 乏 人 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20813', '26', '16', '50', '她 们 狂 傲 ， 在 我 面 前 行 可 憎 的 事 ， 我 看 见 便 将 她 们 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20814', '26', '16', '51', '撒 马 利 亚 没 有 犯 你 一 半 的 罪 ， 你 行 可 憎 的 事 比 她 更 多 ， 使 你 的 姊 妹 因 你 所 行 一 切 可 憎 的 事 ， 倒 显 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20815', '26', '16', '52', '你 既 断 定 你 姊 妹 为 义 ｛ 为 义 ： 或 译 当 受 羞 辱 ｝ ， 就 要 担 当 自 己 的 羞 辱 ； 因 你 所 犯 的 罪 比 她 们 更 为 可 憎 ， 她 们 就 比 你 更 显 为 义 ； 你 既 使 你 的 姊 妹 显 为 义 ， 你 就 要 抱 愧 担 当 自 己 的 羞 辱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20816', '26', '16', '53', '＜ 所 多 玛 、 撒 马 利 亚 要 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20817', '26', '16', '54', '好 使 你 担 当 自 己 的 羞 辱 ， 并 因 你 一 切 所 行 的 使 她 们 得 安 慰 ， 你 就 抱 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20818', '26', '16', '55', '你 的 妹 妹 所 多 玛 和 她 的 众 女 必 归 回 原 位 ； 撒 马 利 亚 和 她 的 众 女 ， 你 和 你 的 众 女 ， 也 必 归 回 原 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20819', '26', '16', '56', '在 你 骄 傲 的 日 子 ， 你 的 恶 行 没 有 显 露 以 先 ， 你 的 口 就 不 提 你 的 妹 妹 所 多 玛 。 那 受 了 凌 辱 的 亚 兰 众 女 和 亚 兰 四 围 非 利 士 的 众 女 都 恨 恶 你 ， 藐 视 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20820', '26', '16', '57', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20821', '26', '16', '58', '耶 和 华 说 ： 你 贪 淫 和 可 憎 的 事 ， 你 已 经 担 当 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20822', '26', '16', '59', '＜ 永 远 的 约 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20823', '26', '16', '60', '然 而 我 要 追 念 在 你 幼 年 时 与 你 所 立 的 约 ， 也 要 与 你 立 定 永 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20824', '26', '16', '61', '你 接 待 你 姊 姊 和 你 妹 妹 的 时 候 ， 你 要 追 念 你 所 行 的 ， 自 觉 惭 愧 ； 并 且 我 要 将 她 们 赐 你 为 女 儿 ， 却 不 是 按 着 前 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20825', '26', '16', '62', '我 要 坚 定 与 你 所 立 的 约 （ 你 就 知 道 我 是 耶 和 华 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20826', '26', '16', '63', '好 使 你 在 我 赦 免 你 一 切 所 行 的 时 候 ， 心 里 追 念 ， 自 觉 抱 愧 ， 又 因 你 的 羞 辱 就 不 再 开 口 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20827', '26', '17', '1', '＜ 老 鹰 和 葡 萄 树 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20828', '26', '17', '2', '“ 人 子 啊 ， 你 要 向 以 色 列 家 出 谜 语 ， 设 比 喻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20829', '26', '17', '3', '说 主 耶 和 华 如 此 说 ： 有 一 大 鹰 ， 翅 膀 大 ， 翎 毛 长 ， 羽 毛 丰 满 ， 彩 色 俱 备 ， 来 到 黎 巴 嫩 ， 将 香 柏 树 梢 拧 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20830', '26', '17', '4', '就 是 折 去 香 柏 树 尽 尖 的 嫩 枝 ， 叼 到 贸 易 之 地 ， 放 在 买 卖 城 中 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20831', '26', '17', '5', '又 将 以 色 列 地 的 枝 子 栽 于 肥 田 里 ， 插 在 大 水 旁 ， 如 插 柳 树 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20832', '26', '17', '6', '就 渐 渐 生 长 ， 成 为 蔓 延 矮 小 的 葡 萄 树 。 其 枝 转 向 那 鹰 ， 其 根 在 鹰 以 下 ， 于 是 成 了 葡 萄 树 ， 生 出 枝 子 ， 发 出 小 枝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20833', '26', '17', '7', '“ 又 有 一 大 鹰 ， 翅 膀 大 ， 羽 毛 多 。 这 葡 萄 树 从 栽 种 的 畦 中 向 这 鹰 弯 过 根 来 ， 发 出 枝 子 ， 好 得 它 的 浇 灌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20834', '26', '17', '8', '这 树 栽 于 肥 田 多 水 的 旁 边 ， 好 生 枝 子 ， 结 果 子 ， 成 为 佳 美 的 葡 萄 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20835', '26', '17', '9', '你 要 说 ， 主 耶 和 华 如 此 说 ： 这 葡 萄 树 岂 能 发 旺 呢 ？ 鹰 岂 不 拔 出 它 的 根 来 ， 芟 除 它 的 果 子 ， 使 它 枯 干 ， 使 它 发 的 嫩 叶 都 枯 干 了 吗 ？ 也 不 用 大 力 和 多 民 ， 就 拔 出 它 的 根 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20836', '26', '17', '10', '葡 萄 树 虽 然 栽 种 ， 岂 能 发 旺 呢 ？ 一 经 东 风 ， 岂 不 全 然 枯 干 吗 ？ 必 在 生 长 的 畦 中 枯 干 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20837', '26', '17', '11', '＜ 解 释 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20838', '26', '17', '12', '“ 你 对 那 悖 逆 之 家 说 ： 你 们 不 知 道 这 些 事 是 什 么 意 思 吗 ？ 你 要 告 诉 他 们 说 ， 巴 比 伦 王 曾 到 耶 路 撒 冷 ， 将 其 中 的 君 王 和 首 领 带 到 巴 比 伦 自 己 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20839', '26', '17', '13', '从 以 色 列 的 宗 室 中 取 一 人 与 他 立 约 ， 使 他 发 誓 ， 并 将 国 中 有 势 力 的 人 掳 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20840', '26', '17', '14', '使 国 低 微 不 能 自 强 ， 惟 因 守 盟 约 得 以 存 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20841', '26', '17', '15', '他 却 背 叛 巴 比 伦 王 ， 打 发 使 者 往 埃 及 去 ， 要 他 们 给 他 马 匹 和 多 民 。 他 岂 能 亨 通 呢 ？ 行 这 样 事 的 人 岂 能 逃 脱 呢 ？ 他 背 约 岂 能 逃 脱 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20842', '26', '17', '16', '他 轻 看 向 王 所 起 的 誓 ， 背 弃 王 与 他 所 立 的 约 。 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 他 定 要 死 在 立 他 作 王 、 巴 比 伦 王 的 京 都 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20843', '26', '17', '17', '敌 人 筑 垒 造 台 ， 与 他 打 仗 的 时 候 ， 为 要 剪 除 多 人 ， 法 老 虽 领 大 军 队 和 大 群 众 ， 还 是 不 能 帮 助 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20844', '26', '17', '18', '他 轻 看 誓 言 ， 背 弃 盟 约 ， 已 经 投 降 ， 却 又 做 这 一 切 的 事 ， 他 必 不 能 逃 脱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20845', '26', '17', '19', '所 以 主 耶 和 华 如 此 说 ： “ 我 指 着 我 的 永 生 起 誓 ， 他 既 轻 看 指 我 所 起 的 誓 ， 背 弃 指 我 所 立 的 约 ， 我 必 要 使 这 罪 归 在 他 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20846', '26', '17', '20', '我 必 将 我 的 网 撒 在 他 身 上 ， 他 必 在 我 的 网 罗 中 缠 住 。 我 必 带 他 到 巴 比 伦 ， 并 要 在 那 里 因 他 干 犯 我 的 罪 刑 罚 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20847', '26', '17', '21', '他 的 一 切 军 队 ， 凡 逃 跑 的 ， 都 必 倒 在 刀 下 ； 所 剩 下 的 ， 也 必 分 散 四 方 ｛ 方 ： 原 文 是 风 ｝ 。 你 们 就 知 道 说 这 话 的 是 我 ─ ─ 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20848', '26', '17', '22', '＜ 神 对 将 来 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20849', '26', '17', '23', '在 以 色 列 高 处 的 山 栽 上 。 它 就 生 枝 子 ， 结 果 子 ， 成 为 佳 美 的 香 柏 树 ， 各 类 飞 鸟 都 必 宿 在 其 下 ， 就 是 宿 在 枝 子 的 荫 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20850', '26', '17', '24', '田 野 的 树 木 都 必 知 道 我 ─ ─ 耶 和 华 使 高 树 矮 小 ， 矮 树 高 大 ； 青 树 枯 干 ， 枯 树 发 旺 。 我 ─ ─ 耶 和 华 如 此 说 ， 也 如 此 行 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20851', '26', '18', '1', '耶 和 华 的 话 又 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20852', '26', '18', '2', '“ 你 们 在 以 色 列 地 怎 么 用 这 俗 语 说 ‘ 父 亲 吃 了 酸 葡 萄 ， 儿 子 的 牙 酸 倒 了 ’ 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20853', '26', '18', '3', '主 耶 和 华 说 ： “ 我 指 着 我 的 永 生 起 誓 ， 你 们 在 以 色 列 中 ， 必 不 再 有 用 这 俗 语 的 因 由 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20854', '26', '18', '4', '看 哪 ， 世 人 都 是 属 我 的 ； 为 父 的 怎 样 属 我 ， 为 子 的 也 照 样 属 我 ； 犯 罪 的 ， 他 必 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20855', '26', '18', '5', '“ 人 若 是 公 义 ， 且 行 正 直 与 合 理 的 事 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20856', '26', '18', '6', '未 曾 在 山 上 吃 过 祭 偶 像 之 物 ， 未 曾 仰 望 以 色 列 家 的 偶 像 ， 未 曾 玷 污 邻 舍 的 妻 ， 未 曾 在 妇 人 的 经 期 内 亲 近 她 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20857', '26', '18', '7', '未 曾 亏 负 人 ， 乃 将 欠 债 之 人 的 当 头 还 给 他 ； 未 曾 抢 夺 人 的 物 件 ， 却 将 食 物 给 饥 饿 的 人 吃 ， 将 衣 服 给 赤 身 的 人 穿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20858', '26', '18', '8', '未 曾 向 借 钱 的 弟 兄 取 利 ， 也 未 曾 向 借 粮 的 弟 兄 多 要 ， 缩 手 不 作 罪 孽 ， 在 两 人 之 间 ， 按 至 理 判 断 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20859', '26', '18', '9', '遵 行 我 的 律 例 ， 谨 守 我 的 典 章 ， 按 诚 实 行 事 ─ ─ 这 人 是 公 义 的 ， 必 定 存 活 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20860', '26', '18', '10', '“ 他 若 生 一 个 儿 子 ， 作 强 盗 ， 是 流 人 血 的 ， 不 行 以 上 所 说 之 善 ， 反 行 其 中 之 恶 ， 乃 在 山 上 吃 过 祭 偶 像 之 物 ， 并 玷 污 邻 舍 的 妻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20861', '26', '18', '11', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20862', '26', '18', '12', '亏 负 困 苦 和 穷 乏 的 人 ， 抢 夺 人 的 物 ， 未 曾 将 当 头 还 给 人 ， 仰 望 偶 像 ， 并 行 可 憎 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20863', '26', '18', '13', '向 借 钱 的 弟 兄 取 利 ， 向 借 粮 的 弟 兄 多 要 ─ ─ 这 人 岂 能 存 活 呢 ？ 他 必 不 能 存 活 。 他 行 这 一 切 可 憎 的 事 ， 必 要 死 亡 ， 他 的 罪 ｛ 原 文 是 血 ｝ 必 归 到 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20864', '26', '18', '14', '“ 他 若 生 一 个 儿 子 ， 见 父 亲 所 犯 的 一 切 罪 便 惧 怕 ｛ 有 古 卷 ： 思 量 ｝ ， 不 照 样 去 做 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20865', '26', '18', '15', '未 曾 在 山 上 吃 过 祭 偶 像 之 物 ， 未 曾 仰 望 以 色 列 家 的 偶 像 ， 未 曾 玷 污 邻 舍 的 妻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20866', '26', '18', '16', '未 曾 亏 负 人 ， 未 曾 取 人 的 当 头 ， 未 曾 抢 夺 人 的 物 件 ， 却 将 食 物 给 饥 饿 的 人 吃 ， 将 衣 服 给 赤 身 的 人 穿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20867', '26', '18', '17', '缩 手 不 害 贫 穷 人 ， 未 曾 向 借 钱 的 弟 兄 取 利 ， 也 未 曾 向 借 粮 的 弟 兄 多 要 ； 他 顺 从 我 的 典 章 ， 遵 行 我 的 律 例 ， 就 不 因 父 亲 的 罪 孽 死 亡 ， 定 要 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20868', '26', '18', '18', '至 于 他 父 亲 ； 因 为 欺 人 太 甚 ， 抢 夺 弟 兄 ， 在 本 国 的 民 中 行 不 善 ， 他 必 因 自 己 的 罪 孽 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20869', '26', '18', '19', '“ 你 们 还 说 ： ‘ 儿 子 为 何 不 担 当 父 亲 的 罪 孽 呢 ？ ’ 儿 子 行 正 直 与 合 理 的 事 ， 谨 守 遵 行 我 的 一 切 律 例 ， 他 必 定 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20870', '26', '18', '20', '惟 有 犯 罪 的 ， 他 必 死 亡 。 儿 子 必 不 担 当 父 亲 的 罪 孽 ， 父 亲 也 不 担 当 儿 子 的 罪 孽 。 义 人 的 善 果 必 归 自 己 ， 恶 人 的 恶 报 也 必 归 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20871', '26', '18', '21', '“ 恶 人 若 回 头 离 开 所 做 的 一 切 罪 恶 ， 谨 守 我 一 切 的 律 例 ， 行 正 直 与 合 理 的 事 ， 他 必 定 存 活 ， 不 致 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20872', '26', '18', '22', '他 所 犯 的 一 切 罪 过 都 不 被 记 念 ， 因 所 行 的 义 ， 他 必 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20873', '26', '18', '23', '主 耶 和 华 说 ： 恶 人 死 亡 ， 岂 是 我 喜 悦 的 吗 ？ 不 是 喜 悦 他 回 头 离 开 所 行 的 道 存 活 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20874', '26', '18', '24', '义 人 若 转 离 义 行 而 作 罪 孽 ， 照 着 恶 人 所 行 一 切 可 憎 的 事 而 行 ， 他 岂 能 存 活 吗 ？ 他 所 行 的 一 切 义 都 不 被 记 念 ； 他 必 因 所 犯 的 罪 、 所 行 的 恶 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20875', '26', '18', '25', '“ 你 们 还 说 ： ‘ 主 的 道 不 公 平 ！ ’ 以 色 列 家 啊 ， 你 们 当 听 ， 我 的 道 岂 不 公 平 吗 ？ 你 们 的 道 岂 不 是 不 公 平 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20876', '26', '18', '26', '义 人 若 转 离 义 行 而 作 罪 孽 死 亡 ， 他 是 因 所 作 的 罪 孽 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20877', '26', '18', '27', '再 者 ， 恶 人 若 回 头 离 开 所 行 的 恶 ， 行 正 直 与 合 理 的 事 ， 他 必 将 性 命 救 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20878', '26', '18', '28', '因 为 他 思 量 ， 回 头 离 开 所 犯 的 一 切 罪 过 ， 必 定 存 活 ， 不 致 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20879', '26', '18', '29', '以 色 列 家 还 说 ： ‘ 主 的 道 不 公 平 ！ ’ 以 色 列 家 啊 ， 我 的 道 岂 不 公 平 吗 ？ 你 们 的 道 岂 不 是 不 公 平 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20880', '26', '18', '30', '所 以 主 耶 和 华 说 ： “ 以 色 列 家 啊 ， 我 必 按 你 们 各 人 所 行 的 审 判 你 们 。 你 们 当 回 头 离 开 所 犯 的 一 切 罪 过 。 这 样 ， 罪 孽 必 不 使 你 们 败 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20881', '26', '18', '31', '你 们 要 将 所 犯 的 一 切 罪 过 尽 行 抛 弃 ， 自 做 一 个 新 心 和 新 灵 。 以 色 列 家 啊 ， 你 们 何 必 死 亡 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20882', '26', '18', '32', '主 耶 和 华 说 ： 我 不 喜 悦 那 死 人 之 死 ， 所 以 你 们 当 回 头 而 存 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20883', '26', '19', '1', '＜ 挽 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20884', '26', '19', '2', '说 ： 你 的 母 亲 是 什 么 呢 ？ 是 个 母 狮 子 ， 蹲 伏 在 狮 子 中 间 ， 在 少 壮 狮 子 中 养 育 小 狮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20885', '26', '19', '3', '在 它 小 狮 子 中 养 大 一 个 ， 成 了 少 壮 狮 子 ， 学 会 抓 食 而 吃 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20886', '26', '19', '4', '列 国 听 见 了 就 把 它 捉 在 他 们 的 坑 中 ， 用 钩 子 拉 到 埃 及 地 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20887', '26', '19', '5', '母 狮 见 自 己 等 候 失 了 指 望 ， 就 从 它 小 狮 子 中 又 将 一 个 养 为 少 壮 狮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20888', '26', '19', '6', '它 在 众 狮 子 中 走 来 走 去 ， 成 了 少 壮 狮 子 ， 学 会 抓 食 而 吃 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20889', '26', '19', '7', '它 知 道 列 国 的 宫 殿 ， 又 使 他 们 的 城 邑 变 为 荒 场 ； 因 它 咆 哮 的 声 音 ， 遍 地 和 其 中 所 有 的 就 都 荒 废 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20890', '26', '19', '8', '于 是 四 围 邦 国 各 省 的 人 来 攻 击 它 ， 将 网 撒 在 它 身 上 ， 捉 在 他 们 的 坑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20891', '26', '19', '9', '他 们 用 钩 子 钩 住 它 ， 将 它 放 在 笼 中 ， 带 到 巴 比 伦 王 那 里 ， 将 它 放 入 坚 固 之 所 ， 使 它 的 声 音 在 以 色 列 山 上 不 再 听 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20892', '26', '19', '10', '你 的 母 亲 先 前 如 葡 萄 树 ， 极 其 茂 盛 ｛ 原 文 是 在 你 血 中 ｝ ， 栽 于 水 旁 。 因 为 水 多 ， 就 多 结 果 子 ， 满 生 枝 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20893', '26', '19', '11', '生 出 坚 固 的 枝 干 ， 可 作 掌 权 者 的 杖 。 这 枝 干 高 举 在 茂 密 的 枝 中 ， 而 且 它 生 长 高 大 ， 枝 子 繁 多 ， 远 远 可 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20894', '26', '19', '12', '但 这 葡 萄 树 因 忿 怒 被 拔 出 摔 在 地 上 ； 东 风 吹 干 其 上 的 果 子 ， 坚 固 的 枝 干 折 断 枯 干 ， 被 火 烧 毁 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20895', '26', '19', '13', '如 今 栽 于 旷 野 干 旱 无 水 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20896', '26', '19', '14', '火 也 从 它 枝 干 中 发 出 ， 烧 灭 果 子 ， 以 致 没 有 坚 固 的 枝 干 可 做 掌 权 者 的 杖 。 这 是 哀 歌 ， 也 必 用 以 作 哀 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20897', '26', '20', '1', '＜ 神 的 旨 意 ， 人 的 抗 命 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20898', '26', '20', '2', '耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20899', '26', '20', '3', '“ 人 子 啊 ， 你 要 告 诉 以 色 列 的 长 老 说 ， 主 耶 和 华 如 此 说 ： 你 们 来 是 求 问 我 吗 ？ 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 我 必 不 被 你 们 求 问 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20900', '26', '20', '4', '人 子 啊 ， 你 要 审 问 审 问 他 们 吗 ？ 你 当 使 他 们 知 道 他 们 列 祖 那 些 可 憎 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20901', '26', '20', '5', '对 他 们 说 ， 主 耶 和 华 如 此 说 ： 当 日 我 拣 选 以 色 列 ， 向 雅 各 家 的 后 裔 起 誓 ， 在 埃 及 地 将 自 己 向 他 们 显 现 ， 说 ： 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20902', '26', '20', '6', '那 日 我 向 他 们 起 誓 ， 必 领 他 们 出 埃 及 地 ， 到 我 为 他 们 察 看 的 流 奶 与 蜜 之 地 ； 那 地 在 万 国 中 是 有 荣 耀 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20903', '26', '20', '7', '我 对 他 们 说 ， 你 们 各 人 要 抛 弃 眼 所 喜 爱 那 可 憎 之 物 ， 不 可 因 埃 及 的 偶 像 玷 污 自 己 。 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20904', '26', '20', '8', '他 们 却 悖 逆 我 ， 不 肯 听 从 我 ， 不 抛 弃 他 们 眼 所 喜 爱 那 可 憎 之 物 ， 不 离 弃 埃 及 的 偶 像 。 “ 我 就 说 ， 我 要 将 我 的 忿 怒 倾 在 他 们 身 上 ， 在 埃 及 地 向 他 们 成 就 我 怒 中 所 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20905', '26', '20', '9', '我 却 为 我 名 的 缘 故 没 有 这 样 行 ， 免 得 我 名 在 他 们 所 住 的 列 国 人 眼 前 被 亵 渎 ； 我 领 他 们 出 埃 及 地 ， 在 这 列 国 人 的 眼 前 将 自 己 向 他 们 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20906', '26', '20', '10', '这 样 ， 我 就 使 他 们 出 埃 及 地 ， 领 他 们 到 旷 野 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20907', '26', '20', '11', '将 我 的 律 例 赐 给 他 们 ， 将 我 的 典 章 指 示 他 们 ； 人 若 遵 行 就 必 因 此 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20908', '26', '20', '12', '又 将 我 的 安 息 日 赐 给 他 们 ， 好 在 我 与 他 们 中 间 为 证 据 ， 使 他 们 知 道 我 ─ ─ 耶 和 华 是 叫 他 们 成 为 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20909', '26', '20', '13', '以 色 列 家 却 在 旷 野 悖 逆 我 ， 不 顺 从 我 的 律 例 ， 厌 弃 我 的 典 章 （ 人 若 遵 行 就 必 因 此 活 着 ） ， 大 大 干 犯 我 的 安 息 日 。 “ 我 就 说 ， 要 在 旷 野 将 我 的 忿 怒 倾 在 他 们 身 上 ， 灭 绝 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20910', '26', '20', '14', '我 却 为 我 名 的 缘 故 ， 没 有 这 样 行 ， 免 得 我 的 名 在 我 领 他 们 出 埃 及 的 列 国 人 眼 前 被 亵 渎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20911', '26', '20', '15', '并 且 我 在 旷 野 向 他 们 起 誓 ， 必 不 领 他 们 进 入 我 所 赐 给 他 们 流 奶 与 蜜 之 地 （ 那 地 在 万 国 中 是 有 荣 耀 的 ） ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20912', '26', '20', '16', '因 为 他 们 厌 弃 我 的 典 章 ， 不 顺 从 我 的 律 例 ， 干 犯 我 的 安 息 日 ， 他 们 的 心 随 从 自 己 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20913', '26', '20', '17', '虽 然 如 此 ， 我 眼 仍 顾 惜 他 们 ， 不 毁 灭 他 们 ， 不 在 旷 野 将 他 们 灭 绝 净 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20914', '26', '20', '18', '“ 我 在 旷 野 对 他 们 的 儿 女 说 ： 不 要 遵 行 你 们 父 亲 的 律 例 ， 不 要 谨 守 他 们 的 恶 规 ， 也 不 要 因 他 们 的 偶 像 玷 污 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20915', '26', '20', '19', '我 是 耶 和 华 ─ ─ 你 们 的 神 ， 你 们 要 顺 从 我 的 律 例 ， 谨 守 遵 行 我 的 典 章 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20916', '26', '20', '20', '且 以 我 的 安 息 日 为 圣 。 这 日 在 我 与 你 们 中 间 为 证 据 ， 使 你 们 知 道 我 是 耶 和 华 ─ ─ 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20917', '26', '20', '21', '只 是 他 们 的 儿 女 悖 逆 我 ， 不 顺 从 我 的 律 例 ， 也 不 谨 守 遵 行 我 的 典 章 （ 人 若 遵 行 就 必 因 此 活 着 ） ， 干 犯 我 的 安 息 日 。 “ 我 就 说 ， 要 将 我 的 忿 怒 倾 在 他 们 身 上 ， 在 旷 野 向 他 们 成 就 我 怒 中 所 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20918', '26', '20', '22', '虽 然 如 此 ， 我 却 为 我 名 的 缘 故 缩 手 没 有 这 样 行 ， 免 得 我 的 名 在 我 领 他 们 出 埃 及 的 列 国 人 眼 前 被 亵 渎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20919', '26', '20', '23', '并 且 我 在 旷 野 向 他 们 起 誓 ， 必 将 他 们 分 散 在 列 国 ， 四 散 在 列 邦 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20920', '26', '20', '24', '因 为 他 们 不 遵 行 我 的 典 章 ， 竟 厌 弃 我 的 律 例 ， 干 犯 我 的 安 息 日 ， 眼 目 仰 望 他 们 父 亲 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20921', '26', '20', '25', '我 也 任 他 们 遵 行 不 美 的 律 例 ， 谨 守 不 能 使 人 活 着 的 恶 规 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20922', '26', '20', '26', '因 他 们 将 一 切 头 生 的 经 火 ， 我 就 任 凭 他 们 在 这 供 献 的 事 上 玷 污 自 己 ， 好 叫 他 们 凄 凉 ， 使 他 们 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20923', '26', '20', '27', '“ 人 子 啊 ， 你 要 告 诉 以 色 列 家 说 ， 主 耶 和 华 如 此 说 ： 你 们 的 列 祖 在 得 罪 我 的 事 上 亵 渎 我 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20924', '26', '20', '28', '因 为 我 领 他 们 到 了 我 起 誓 应 许 赐 给 他 们 的 地 ， 他 们 看 见 各 高 山 、 各 茂 密 树 ， 就 在 那 里 献 祭 ， 奉 上 惹 我 发 怒 的 供 物 ， 也 在 那 里 焚 烧 馨 香 的 祭 牲 ， 并 浇 上 奠 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20925', '26', '20', '29', '我 就 对 他 们 说 ： 你 们 所 上 的 那 高 处 叫 什 么 呢 ？ （ 那 高 处 的 名 字 叫 巴 麻 直 到 今 日 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20926', '26', '20', '30', '所 以 你 要 对 以 色 列 家 说 ， 主 耶 和 华 如 此 说 ： 你 们 仍 照 你 们 列 祖 所 行 的 玷 污 自 己 吗 ？ 仍 照 他 们 可 憎 的 事 行 邪 淫 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20927', '26', '20', '31', '你 们 奉 上 供 物 使 你 们 儿 子 经 火 的 时 候 ， 仍 将 一 切 偶 像 玷 污 自 己 ， 直 到 今 日 吗 ？ 以 色 列 家 啊 ， 我 岂 被 你 们 求 问 吗 ？ 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 我 必 不 被 你 们 求 问 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20928', '26', '20', '32', '“ 你 们 说 ： 我 们 要 像 外 邦 人 和 列 国 的 宗 族 一 样 ， 去 事 奉 木 头 与 石 头 。 你 们 所 起 的 这 心 意 万 不 能 成 就 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20929', '26', '20', '33', '＜ 神 的 惩 罚 和 赦 免 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20930', '26', '20', '34', '我 必 用 大 能 的 手 和 伸 出 来 的 膀 臂 ， 并 倾 出 来 的 忿 怒 ， 将 你 们 从 万 民 中 领 出 来 ， 从 分 散 的 列 国 内 聚 集 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20931', '26', '20', '35', '我 必 带 你 们 到 外 邦 人 的 旷 野 ， 在 那 里 当 面 刑 罚 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20932', '26', '20', '36', '我 怎 样 在 埃 及 地 的 旷 野 刑 罚 你 们 的 列 祖 ， 也 必 照 样 刑 罚 你 们 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20933', '26', '20', '37', '我 必 使 你 们 从 杖 下 经 过 ， 使 你 们 被 约 拘 束 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20934', '26', '20', '38', '我 必 从 你 们 中 间 除 净 叛 逆 和 得 罪 我 的 人 ， 将 他 们 从 所 寄 居 的 地 方 领 出 来 ， 他 们 却 不 得 入 以 色 列 地 。 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20935', '26', '20', '39', '“ 以 色 列 家 啊 ， 至 于 你 们 ， 主 耶 和 华 如 此 说 ： 从 此 以 后 若 不 听 从 我 ， 就 任 凭 你 们 去 事 奉 偶 像 ， 只 是 不 可 再 因 你 们 的 供 物 和 偶 像 亵 渎 我 的 圣 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20936', '26', '20', '40', '“ 主 耶 和 华 说 ： 在 我 的 圣 山 ， 就 是 以 色 列 高 处 的 山 ， 所 有 以 色 列 的 全 家 都 要 事 奉 我 。 我 要 在 那 里 悦 纳 你 们 ， 向 你 们 要 供 物 和 初 熟 的 土 产 ， 并 一 切 的 圣 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20937', '26', '20', '41', '我 从 万 民 中 领 你 们 出 来 ， 从 分 散 的 列 国 内 聚 集 你 们 ， 那 时 我 必 悦 纳 你 们 好 像 馨 香 之 祭 ， 要 在 外 邦 人 眼 前 在 你 们 身 上 显 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20938', '26', '20', '42', '我 领 你 们 进 入 以 色 列 地 ， 就 是 我 起 誓 应 许 赐 给 你 们 列 祖 之 地 ， 那 时 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20939', '26', '20', '43', '你 们 在 那 里 要 追 念 玷 污 自 己 的 行 动 作 为 ， 又 要 因 所 做 的 一 切 恶 事 厌 恶 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20940', '26', '20', '44', '主 耶 和 华 说 ： 以 色 列 家 啊 ， 我 为 我 名 的 缘 故 ， 不 照 着 你 们 的 恶 行 和 你 们 的 坏 事 待 你 们 ； 你 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20941', '26', '20', '45', '＜ 南 方 大 火 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20942', '26', '20', '46', '“ 人 子 啊 ， 你 要 面 向 南 方 ， 向 南 滴 下 预 言 攻 击 南 方 田 野 的 树 林 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20943', '26', '20', '47', '对 南 方 的 树 林 说 ， 要 听 耶 和 华 的 话 。 主 耶 和 华 如 此 说 ： 我 必 使 火 在 你 中 间 着 起 ， 烧 灭 你 中 间 的 一 切 青 树 和 枯 树 ， 猛 烈 的 火 焰 必 不 熄 灭 。 从 南 到 北 ， 人 的 脸 面 都 被 烧 焦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20944', '26', '20', '48', '凡 有 血 气 的 都 必 知 道 是 我 ─ ─ 耶 和 华 使 火 着 起 ， 这 火 必 不 熄 灭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20945', '26', '20', '49', '于 是 我 说 ： “ 哎 ！ 主 耶 和 华 啊 ， 人 都 指 着 我 说 ： 他 岂 不 是 说 比 喻 的 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20946', '26', '21', '1', '＜ 耶 和 华 的 刀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20947', '26', '21', '2', '“ 人 子 啊 ， 你 要 面 向 耶 路 撒 冷 和 圣 所 滴 下 预 言 ， 攻 击 以 色 列 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20948', '26', '21', '3', '对 以 色 列 地 说 ， 耶 和 华 如 此 说 ： 我 与 你 为 敌 ， 并 要 拔 刀 出 鞘 ， 从 你 中 间 将 义 人 和 恶 人 一 并 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20949', '26', '21', '4', '我 既 要 从 你 中 间 剪 除 义 人 和 恶 人 ， 所 以 我 的 刀 要 出 鞘 ， 自 南 至 北 攻 击 一 切 有 血 气 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20950', '26', '21', '5', '一 切 有 血 气 的 就 知 道 我 ─ ─ 耶 和 华 已 经 拔 刀 出 鞘 ， 必 不 再 入 鞘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20951', '26', '21', '6', '人 子 啊 ， 你 要 叹 息 ， 在 他 们 眼 前 弯 着 腰 ， 苦 苦 地 叹 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20952', '26', '21', '7', '他 们 问 你 说 ： ‘ 为 何 叹 息 呢 ？ ’ 你 就 说 ： ‘ 因 为 有 风 声 、 灾 祸 要 来 。 人 心 都 必 消 化 ， 手 都 发 软 ， 精 神 衰 败 ， 膝 弱 如 水 。 看 哪 ， 这 灾 祸 临 近 ， 必 然 成 就 。 这 是 主 耶 和 华 说 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20953', '26', '21', '8', '耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20954', '26', '21', '9', '“ 人 子 啊 ， 你 要 预 言 。 耶 和 华 吩 咐 我 如 此 说 ： 有 刀 、 有 刀 ， 是 磨 快 擦 亮 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20955', '26', '21', '10', '磨 快 为 要 行 杀 戮 ， 擦 亮 为 要 像 闪 电 。 我 们 岂 可 快 乐 吗 ？ 罚 我 子 的 杖 藐 视 各 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20956', '26', '21', '11', '这 刀 已 经 交 给 人 擦 亮 ， 为 要 应 手 使 用 。 这 刀 已 经 磨 快 擦 亮 ， 好 交 在 行 杀 戮 的 人 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20957', '26', '21', '12', '人 子 啊 ， 你 要 呼 喊 哀 号 ， 因 为 这 刀 临 到 我 的 百 姓 和 以 色 列 一 切 的 首 领 。 他 们 和 我 的 百 姓 都 交 在 刀 下 ， 所 以 你 要 拍 腿 叹 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20958', '26', '21', '13', '有 试 验 的 事 ； 若 那 藐 视 的 杖 归 于 无 有 ， 怎 么 样 呢 ？ 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20959', '26', '21', '14', '“ 人 子 啊 ， 你 要 拍 掌 预 言 。 我 ─ ─ 耶 和 华 要 使 这 刀 ， 就 是 致 死 伤 的 刀 ， 一 连 三 次 加 倍 刺 人 ， 进 入 他 们 的 内 屋 ， 使 大 人 受 死 伤 的 就 是 这 刀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20960', '26', '21', '15', '我 设 立 这 恐 吓 人 的 刀 ， 攻 击 他 们 的 一 切 城 门 ， 使 他 们 的 心 消 化 ， 加 增 他 们 跌 倒 的 事 。 哎 ！ 这 刀 造 得 像 闪 电 ， 磨 得 尖 利 ， 要 行 杀 戮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20961', '26', '21', '16', '刀 啊 ， 你 归 在 右 边 ， 摆 在 左 边 ； 你 面 向 哪 方 ， 就 向 那 方 杀 戮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20962', '26', '21', '17', '我 也 要 拍 掌 ， 并 要 使 我 的 忿 怒 止 息 。 这 是 我 ─ ─ 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20963', '26', '21', '18', '＜ 巴 比 伦 王 的 刀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20964', '26', '21', '19', '“ 人 子 啊 ， 你 要 定 出 两 条 路 ， 好 使 巴 比 伦 王 的 刀 来 。 这 两 条 路 必 从 一 地 分 出 来 ， 又 要 在 通 城 的 路 口 上 画 出 一 只 手 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20965', '26', '21', '20', '你 要 定 出 一 条 路 ， 使 刀 来 到 亚 扪 人 的 拉 巴 ； 又 要 定 出 一 条 路 ， 使 刀 来 到 犹 大 的 坚 固 城 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20966', '26', '21', '21', '因 为 巴 比 伦 王 站 在 岔 路 那 里 ， 在 两 条 路 口 上 要 占 卜 。 他 摇 签 ｛ 原 文 是 箭 ｝ 求 问 神 像 ， 察 看 牺 牲 的 肝 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20967', '26', '21', '22', '在 右 手 中 拿 着 为 耶 路 撒 冷 占 卜 的 签 ， 使 他 安 设 撞 城 锤 ， 张 口 叫 杀 ， 扬 声 呐 喊 ， 筑 垒 造 台 ， 以 撞 城 锤 ， 攻 打 城 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20968', '26', '21', '23', '据 那 些 曾 起 誓 的 犹 大 人 看 来 ， 这 是 虚 假 的 占 卜 ； 但 巴 比 伦 王 要 使 他 们 想 起 罪 孽 ， 以 致 将 他 们 捉 住 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20969', '26', '21', '24', '主 耶 和 华 如 此 说 ： “ 因 你 们 的 过 犯 显 露 ， 使 你 们 的 罪 孽 被 记 念 ， 以 致 你 们 的 罪 恶 在 行 为 上 都 彰 显 出 来 ； 又 因 你 们 被 记 念 ， 就 被 捉 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20970', '26', '21', '25', '你 这 受 死 伤 行 恶 的 以 色 列 王 啊 ， 罪 孽 的 尽 头 到 了 ， 受 报 的 日 子 已 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20971', '26', '21', '26', '主 耶 和 华 如 此 说 ： 当 除 掉 冠 ， 摘 下 冕 ， 景 况 必 不 再 像 先 前 ； 要 使 卑 者 升 为 高 ， 使 高 者 降 为 卑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20972', '26', '21', '27', '我 要 将 这 国 倾 覆 ， 倾 覆 ， 而 又 倾 覆 ； 这 国 也 必 不 再 有 ， 直 等 到 那 应 得 的 人 来 到 ， 我 就 赐 给 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20973', '26', '21', '28', '＜ 刀 和 亚 扪 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20974', '26', '21', '29', '人 为 你 见 虚 假 的 异 象 ， 行 谎 诈 的 占 卜 ， 使 你 倒 在 受 死 伤 之 恶 人 的 颈 项 上 。 他 们 罪 孽 到 了 尽 头 ， 受 报 的 日 子 已 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20975', '26', '21', '30', '你 将 刀 收 入 鞘 吧 ！ 在 你 受 造 之 处 、 生 长 之 地 ， 我 必 刑 罚 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20976', '26', '21', '31', '我 必 将 我 的 恼 恨 倒 在 你 身 上 ， 将 我 烈 怒 的 火 喷 在 你 身 上 ， 又 将 你 交 在 善 于 杀 灭 的 畜 类 人 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20977', '26', '21', '32', '你 必 当 柴 被 火 焚 烧 ； 你 的 血 必 流 在 国 中 。 你 必 不 再 被 记 念 ， 因 为 这 是 我 ─ ─ 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20978', '26', '22', '1', '＜ 耶 路 撒 冷 的 过 犯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20979', '26', '22', '2', '“ 人 子 啊 ， 你 要 审 问 审 问 这 流 人 血 的 城 吗 ？ 当 使 她 知 道 她 一 切 可 憎 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20980', '26', '22', '3', '你 要 说 ， 主 耶 和 华 如 此 说 ： 哎 ！ 这 城 有 流 人 血 的 事 在 其 中 ， 叫 她 受 报 的 日 期 来 到 ， 又 做 偶 像 玷 污 自 己 ， 陷 害 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20981', '26', '22', '4', '你 因 流 了 人 的 血 ， 就 为 有 罪 ； 你 做 了 偶 像 ， 就 玷 污 自 己 ， 使 你 受 报 之 日 临 近 ， 报 应 之 年 来 到 。 所 以 我 叫 你 受 列 国 的 凌 辱 和 列 邦 的 讥 诮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20982', '26', '22', '5', '你 这 名 臭 、 多 乱 的 城 啊 ， 那 些 离 你 近 、 离 你 远 的 都 必 讥 诮 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20983', '26', '22', '6', '“ 看 哪 ， 以 色 列 的 首 领 各 逞 其 能 ， 在 你 中 间 流 人 之 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20984', '26', '22', '7', '在 你 中 间 有 轻 慢 父 母 的 ， 有 欺 压 寄 居 的 ， 有 亏 负 孤 儿 寡 妇 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20985', '26', '22', '8', '你 藐 视 了 我 的 圣 物 ， 干 犯 了 我 的 安 息 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20986', '26', '22', '9', '在 你 中 间 有 谗 谤 人 、 流 人 血 的 ； 有 在 山 上 吃 过 祭 偶 像 之 物 的 ， 有 行 淫 乱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20987', '26', '22', '10', '在 你 中 间 有 露 继 母 下 体 羞 辱 父 亲 的 ， 有 玷 辱 月 经 不 洁 净 之 妇 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20988', '26', '22', '11', '这 人 与 邻 舍 的 妻 行 可 憎 的 事 ； 那 人 贪 淫 玷 污 儿 妇 ； 还 有 玷 辱 同 父 之 姊 妹 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20989', '26', '22', '12', '在 你 中 间 有 为 流 人 血 受 贿 赂 的 ； 有 向 借 钱 的 弟 兄 取 利 ， 向 借 粮 的 弟 兄 多 要 的 。 且 因 贪 得 无 餍 ， 欺 压 邻 舍 夺 取 财 物 ， 竟 忘 了 我 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20990', '26', '22', '13', '“ 看 哪 ， 我 因 你 所 得 不 义 之 财 和 你 中 间 所 流 的 血 ， 就 拍 掌 叹 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20991', '26', '22', '14', '到 了 我 惩 罚 你 的 日 子 ， 你 的 心 还 能 忍 受 吗 ？ 你 的 手 还 能 有 力 吗 ？ 我 ─ ─ 耶 和 华 说 了 这 话 ， 就 必 照 着 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20992', '26', '22', '15', '我 必 将 你 分 散 在 列 国 ， 四 散 在 列 邦 。 我 也 必 从 你 中 间 除 掉 你 的 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20993', '26', '22', '16', '你 必 在 列 国 人 的 眼 前 因 自 己 所 行 的 被 亵 渎 ， 你 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20994', '26', '22', '17', '＜ 神 的 大 炼 炉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20995', '26', '22', '18', '“ 人 子 啊 ， 以 色 列 家 在 我 看 为 渣 滓 。 他 们 都 是 炉 中 的 铜 、 锡 、 铁 、 铅 ， 都 是 银 渣 滓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20996', '26', '22', '19', '所 以 主 耶 和 华 如 此 说 ： 因 你 们 都 成 为 渣 滓 ， 我 必 聚 集 你 们 在 耶 路 撒 冷 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20997', '26', '22', '20', '人 怎 样 将 银 、 铜 、 铁 、 铅 、 锡 聚 在 炉 中 ， 吹 火 镕 化 ； 照 样 ， 我 也 要 发 怒 气 和 忿 怒 ， 将 你 们 聚 集 放 在 城 中 ， 镕 化 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20998', '26', '22', '21', '我 必 聚 集 你 们 ， 把 我 烈 怒 的 火 吹 在 你 们 身 上 ， 你 们 就 在 其 中 镕 化 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('20999', '26', '22', '22', '银 子 怎 样 镕 化 在 炉 中 ， 你 们 也 必 照 样 镕 化 在 城 中 ， 你 们 就 知 道 我 ─ ─ 耶 和 华 是 将 忿 怒 倒 在 你 们 身 上 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21000', '26', '22', '23', '＜ 以 色 列 领 袖 们 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21001', '26', '22', '24', '“ 人 子 啊 ， 你 要 对 这 地 说 ： 你 是 未 得 洁 净 之 地 ， 在 恼 恨 的 日 子 也 没 有 雨 下 在 你 以 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21002', '26', '22', '25', '其 中 的 先 知 同 谋 背 叛 ， 如 咆 哮 的 狮 子 抓 撕 掠 物 。 他 们 吞 灭 人 民 ， 抢 夺 财 宝 ， 使 这 地 多 有 寡 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21003', '26', '22', '26', '其 中 的 祭 司 强 解 我 的 律 法 ， 亵 渎 我 的 圣 物 ， 不 分 别 圣 的 和 俗 的 ， 也 不 使 人 分 辨 洁 净 的 和 不 洁 净 的 ， 又 遮 眼 不 顾 我 的 安 息 日 ； 我 也 在 他 们 中 间 被 亵 慢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21004', '26', '22', '27', '其 中 的 首 领 仿 佛 豺 狼 抓 撕 掠 物 ， 杀 人 流 血 ， 伤 害 人 命 ， 要 得 不 义 之 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21005', '26', '22', '28', '其 中 的 先 知 为 百 姓 用 未 泡 透 的 灰 抹 墙 ， 就 是 为 他 们 见 虚 假 的 异 象 ， 用 谎 诈 的 占 卜 ， 说 ： ‘ 主 耶 和 华 如 此 说 ’ ， 其 实 耶 和 华 没 有 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21006', '26', '22', '29', '国 内 众 民 一 味 地 欺 压 ， 惯 行 抢 夺 ， 亏 负 困 苦 穷 乏 的 ， 背 理 欺 压 寄 居 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21007', '26', '22', '30', '我 在 他 们 中 间 寻 找 一 人 重 修 墙 垣 ， 在 我 面 前 为 这 国 站 在 破 口 防 堵 ， 使 我 不 灭 绝 这 国 ， 却 找 不 着 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21008', '26', '22', '31', '所 以 我 将 恼 恨 倒 在 他 们 身 上 ， 用 烈 怒 的 火 灭 了 他 们 ， 照 他 们 所 行 的 报 应 在 他 们 头 上 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21009', '26', '23', '1', '＜ 两 个 犯 罪 的 姊 妹 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21010', '26', '23', '2', '“ 人 子 啊 ， 有 两 个 女 子 ， 是 一 母 所 生 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21011', '26', '23', '3', '她 们 在 埃 及 行 邪 淫 ， 在 幼 年 时 行 邪 淫 。 她 们 在 那 里 作 处 女 的 时 候 ， 有 人 拥 抱 她 们 的 怀 ， 抚 摸 她 们 的 乳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21012', '26', '23', '4', '她 们 的 名 字 ， 姊 姊 名 叫 阿 荷 拉 ， 妹 妹 名 叫 阿 荷 利 巴 。 她 们 都 归 于 我 ， 生 了 儿 女 。 论 到 她 们 的 名 字 ， 阿 荷 拉 就 是 撒 马 利 亚 ， 阿 荷 利 巴 就 是 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21013', '26', '23', '5', '“ 阿 荷 拉 归 我 之 后 行 邪 淫 ， 贪 恋 所 爱 的 人 ， 就 是 她 的 邻 邦 亚 述 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21014', '26', '23', '6', '这 些 人 都 穿 蓝 衣 ， 作 省 长 、 副 省 长 ， 都 骑 着 马 ， 是 可 爱 的 少 年 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21015', '26', '23', '7', '阿 荷 拉 就 与 亚 述 人 中 最 美 的 男 子 放 纵 淫 行 ， 她 因 所 恋 爱 之 人 的 一 切 偶 像 ， 玷 污 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21016', '26', '23', '8', '自 从 在 埃 及 的 时 候 ， 她 就 没 有 离 开 淫 乱 ， 因 为 她 年 幼 作 处 女 的 时 候 ， 埃 及 人 与 她 行 淫 ， 抚 摸 她 的 乳 ， 纵 欲 与 她 行 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21017', '26', '23', '9', '因 此 ， 我 将 她 交 在 她 所 爱 的 人 手 中 ， 就 是 她 所 恋 爱 的 亚 述 人 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21018', '26', '23', '10', '他 们 就 露 了 她 的 下 体 ， 掳 掠 她 的 儿 女 ， 用 刀 杀 了 她 ， 使 她 在 妇 女 中 留 下 臭 名 ， 因 他 们 向 她 施 行 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21019', '26', '23', '11', '“ 她 妹 妹 阿 荷 利 巴 虽 然 看 见 了 ， 却 还 贪 恋 ， 比 她 姊 姊 更 丑 ； 行 淫 乱 比 她 姊 姊 更 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21020', '26', '23', '12', '她 贪 恋 邻 邦 的 亚 述 人 ， 就 是 穿 极 华 美 的 衣 服 ， 骑 着 马 的 省 长 、 副 省 长 ， 都 是 可 爱 的 少 年 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21021', '26', '23', '13', '我 看 见 她 被 玷 污 了 ， 她 姊 妹 二 人 同 行 一 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21022', '26', '23', '14', '阿 荷 利 巴 又 加 增 淫 行 ， 因 她 看 见 人 像 画 在 墙 上 ， 就 是 用 丹 色 所 画 迦 勒 底 人 的 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21023', '26', '23', '15', '腰 间 系 着 带 子 ， 头 上 有 下 垂 的 裹 头 巾 ， 都 是 军 长 的 形 状 ， 仿 照 巴 比 伦 人 的 形 像 ； 他 们 的 故 土 就 是 迦 勒 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21024', '26', '23', '16', '阿 荷 利 巴 一 看 见 就 贪 恋 他 们 ， 打 发 使 者 往 迦 勒 底 去 见 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21025', '26', '23', '17', '巴 比 伦 人 就 来 登 她 爱 情 的 床 ， 与 她 行 淫 玷 污 她 。 她 被 玷 污 ， 随 后 心 里 与 他 们 生 疏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21026', '26', '23', '18', '这 样 ， 她 显 露 淫 行 ， 又 显 露 下 体 ； 我 心 就 与 她 生 疏 ， 像 先 前 与 她 姊 姊 生 疏 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21027', '26', '23', '19', '她 还 加 增 她 的 淫 行 ， 追 念 她 幼 年 在 埃 及 地 行 邪 淫 的 日 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21028', '26', '23', '20', '贪 恋 情 人 身 壮 精 足 ， 如 驴 如 马 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21029', '26', '23', '21', '这 样 ， 你 就 想 起 你 幼 年 的 淫 行 。 那 时 ， 埃 及 人 拥 抱 你 的 怀 ， 抚 摸 你 的 乳 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21030', '26', '23', '22', '＜ 神 审 判 妹 妹 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21031', '26', '23', '23', '所 来 的 就 是 巴 比 伦 人 、 迦 勒 底 的 众 人 、 比 割 人 、 书 亚 人 、 哥 亚 人 ， 同 着 他 们 的 还 有 亚 述 众 人 ， 乃 是 作 省 长 、 副 省 长 、 作 军 长 有 名 声 的 ， 都 骑 着 马 ， 是 可 爱 的 少 年 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21032', '26', '23', '24', '他 们 必 带 兵 器 、 战 车 、 辎 重 车 ， 率 领 大 众 来 攻 击 你 。 他 们 要 拿 大 小 盾 牌 ， 顶 盔 摆 阵 ， 在 你 四 围 攻 击 你 。 我 要 将 审 判 的 事 交 给 他 们 ， 他 们 必 按 着 自 己 的 条 例 审 判 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21033', '26', '23', '25', '我 必 以 忌 恨 攻 击 你 ； 他 们 必 以 忿 怒 办 你 。 他 们 必 割 去 你 的 鼻 子 和 耳 朵 ； 你 遗 留 ｛ 或 译 ： 余 剩 ； 下 同 ｝ 的 人 必 倒 在 刀 下 。 他 们 必 掳 去 你 的 儿 女 ； 你 所 遗 留 的 必 被 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21034', '26', '23', '26', '他 们 必 剥 去 你 的 衣 服 ， 夺 取 你 华 美 的 宝 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21035', '26', '23', '27', '这 样 ， 我 必 使 你 的 淫 行 和 你 从 埃 及 地 染 来 的 淫 乱 止 息 了 ， 使 你 不 再 仰 望 亚 述 ， 也 不 再 追 念 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21036', '26', '23', '28', '主 耶 和 华 如 此 说 ： 我 必 将 你 交 在 你 所 恨 恶 的 人 手 中 ， 就 是 你 心 与 他 生 疏 的 人 手 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21037', '26', '23', '29', '他 们 必 以 恨 恶 办 你 ， 夺 取 你 一 切 劳 碌 得 来 的 ， 留 下 你 赤 身 露 体 。 你 淫 乱 的 下 体 ， 连 你 的 淫 行 ， 带 你 的 淫 乱 ， 都 被 显 露 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21038', '26', '23', '30', '人 必 向 你 行 这 些 事 ； 因 为 你 随 从 外 邦 人 行 邪 淫 ， 被 他 们 的 偶 像 玷 污 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21039', '26', '23', '31', '你 走 了 你 姊 姊 所 走 的 路 ， 所 以 我 必 将 她 的 杯 交 在 你 手 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21040', '26', '23', '32', '主 耶 和 华 如 此 说 ： 你 必 喝 你 姊 姊 所 喝 的 杯 ； 那 杯 又 深 又 广 ， 盛 得 甚 多 ， 使 你 被 人 嗤 笑 讥 刺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21041', '26', '23', '33', '你 必 酩 酊 大 醉 ， 满 有 愁 苦 ， 喝 干 你 姊 姊 撒 马 利 亚 的 杯 ， 就 是 令 人 惊 骇 凄 凉 的 杯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21042', '26', '23', '34', '你 必 喝 这 杯 ， 以 致 喝 尽 。 杯 破 又 龈 杯 片 ， 撕 裂 自 己 的 乳 ； 因 为 这 事 我 曾 说 过 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21043', '26', '23', '35', '主 耶 和 华 如 此 说 ： “ 因 你 忘 记 我 ， 将 我 丢 在 背 后 ， 所 以 你 要 担 当 你 淫 行 和 淫 乱 的 报 应 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21044', '26', '23', '36', '＜ 神 审 判 两 姊 妹 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21045', '26', '23', '37', '她 们 行 淫 ， 手 中 有 杀 人 的 血 ， 又 与 偶 像 行 淫 ， 并 使 她 们 为 我 所 生 的 儿 女 经 火 烧 给 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21046', '26', '23', '38', '此 外 ， 她 们 还 有 向 我 所 行 的 ， 就 是 同 日 玷 污 我 的 圣 所 ， 干 犯 我 的 安 息 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21047', '26', '23', '39', '她 们 杀 了 儿 女 献 与 偶 像 ， 当 天 又 入 我 的 圣 所 ， 将 圣 所 亵 渎 了 。 她 们 在 我 殿 中 所 行 的 乃 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21048', '26', '23', '40', '“ 况 且 你 们 二 妇 打 发 使 者 去 请 远 方 人 。 使 者 到 他 们 那 里 ， 他 们 就 来 了 。 你 们 为 他 们 沐 浴 己 身 ， 粉 饰 眼 目 ， 佩 戴 妆 饰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21049', '26', '23', '41', '坐 在 华 美 的 床 上 ， 前 面 摆 设 桌 案 ， 将 我 的 香 料 膏 油 摆 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21050', '26', '23', '42', '在 那 里 有 群 众 安 逸 欢 乐 的 声 音 ， 并 有 粗 俗 的 人 和 酒 徒 从 旷 野 同 来 ， 把 镯 子 戴 在 二 妇 的 手 上 ， 把 华 冠 戴 在 她 们 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21051', '26', '23', '43', '“ 我 论 这 行 淫 衰 老 的 妇 人 说 ： 现 在 人 还 要 与 她 行 淫 ， 她 也 要 与 人 行 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21052', '26', '23', '44', '人 与 阿 荷 拉 ， 并 阿 荷 利 巴 二 淫 妇 茍 合 ， 好 像 与 妓 女 苟 合 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21053', '26', '23', '45', '必 有 义 人 ， 照 审 判 淫 妇 和 流 人 血 的 妇 人 之 例 ， 审 判 她 们 ； 因 为 她 们 是 淫 妇 ， 手 中 有 杀 人 的 血 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21054', '26', '23', '46', '主 耶 和 华 如 此 说 ： “ 我 必 使 多 人 来 攻 击 她 们 ， 使 她 们 抛 来 抛 去 ， 被 人 抢 夺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21055', '26', '23', '47', '这 些 人 必 用 石 头 打 死 她 们 ， 用 刀 剑 杀 害 她 们 ， 又 杀 戮 她 们 的 儿 女 ， 用 火 焚 烧 她 们 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21056', '26', '23', '48', '这 样 ， 我 必 使 淫 行 从 境 内 止 息 ， 好 叫 一 切 妇 人 都 受 警 戒 ， 不 效 法 你 们 的 淫 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21057', '26', '23', '49', '人 必 照 着 你 们 的 淫 行 报 应 你 们 ； 你 们 要 担 当 拜 偶 像 的 罪 ， 就 知 道 我 是 主 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21058', '26', '24', '1', '＜ 生 锈 的 锅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21059', '26', '24', '2', '“ 人 子 啊 ， 今 日 正 是 巴 比 伦 王 就 近 耶 路 撒 冷 的 日 子 ， 你 要 将 这 日 记 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21060', '26', '24', '3', '要 向 这 悖 逆 之 家 设 比 喻 说 ， 主 耶 和 华 如 此 说 ： 将 锅 放 在 火 上 ， 放 好 了 ， 就 倒 水 在 其 中 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21061', '26', '24', '4', '将 肉 块 ， 就 是 一 切 肥 美 的 肉 块 、 腿 ， 和 肩 都 聚 在 其 中 ， 拿 美 好 的 骨 头 把 锅 装 满 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21062', '26', '24', '5', '取 羊 群 中 最 好 的 ， 将 柴 堆 在 锅 下 ， 使 锅 开 滚 ， 好 把 骨 头 煮 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21063', '26', '24', '6', '“ 主 耶 和 华 如 此 说 ： 祸 哉 ！ 这 流 人 血 的 城 ， 就 是 长 锈 的 锅 。 其 中 的 锈 未 曾 除 掉 ， 须 要 将 肉 块 从 其 中 一 一 取 出 来 ， 不 必 为 它 拈 阄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21064', '26', '24', '7', '城 中 所 流 的 血 倒 在 净 光 的 磐 石 上 ， 不 倒 在 地 上 ， 用 土 掩 盖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21065', '26', '24', '8', '这 城 中 所 流 的 血 倒 在 净 光 的 磐 石 上 ， 不 得 掩 盖 ， 乃 是 出 于 我 ， 为 要 发 忿 怒 施 行 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21066', '26', '24', '9', '所 以 主 耶 和 华 如 此 说 ： 祸 哉 ！ 这 流 人 血 的 城 ， 我 也 必 大 堆 火 柴 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21067', '26', '24', '10', '添 上 木 柴 ， 使 火 着 旺 ， 将 肉 煮 烂 ， 把 汤 熬 浓 ， 使 骨 头 烤 焦 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21068', '26', '24', '11', '把 锅 倒 空 坐 在 炭 火 上 ， 使 锅 烧 热 ， 使 铜 烧 红 ， 镕 化 其 中 的 污 秽 ， 除 净 其 上 的 锈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21069', '26', '24', '12', '这 锅 劳 碌 疲 乏 ， 所 长 的 大 锈 仍 未 除 掉 ； 这 锈 就 是 用 火 也 不 能 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21070', '26', '24', '13', '在 你 污 秽 中 有 淫 行 ， 我 洁 净 你 ， 你 却 不 洁 净 。 你 的 污 秽 再 不 能 洁 净 ， 直 等 我 向 你 发 的 忿 怒 止 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21071', '26', '24', '14', '我 ─ ─ 耶 和 华 说 过 的 必 定 成 就 ， 必 照 话 而 行 ， 必 不 返 回 ， 必 不 顾 惜 ， 也 不 后 悔 。 人 必 照 你 的 举 动 行 为 审 判 你 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21072', '26', '24', '15', '＜ 先 知 妻 子 的 死 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21073', '26', '24', '16', '“ 人 子 啊 ， 我 要 将 你 眼 目 所 喜 爱 的 忽 然 取 去 ， 你 却 不 可 悲 哀 哭 泣 ， 也 不 可 流 泪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21074', '26', '24', '17', '只 可 叹 息 ， 不 可 出 声 ， 不 可 办 理 丧 事 ； 头 上 仍 勒 裹 头 巾 ， 脚 上 仍 穿 鞋 ， 不 可 蒙 着 嘴 唇 ， 也 不 可 吃 吊 丧 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21075', '26', '24', '18', '于 是 我 将 这 事 早 晨 告 诉 百 姓 ， 晚 上 我 的 妻 就 死 了 。 次 日 早 晨 我 便 遵 命 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21076', '26', '24', '19', '百 姓 问 我 说 ： “ 你 这 样 行 与 我 们 有 什 么 关 系 ， 你 不 告 诉 我 们 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21077', '26', '24', '20', '我 回 答 他 们 ： “ 耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21078', '26', '24', '21', '‘ 你 告 诉 以 色 列 家 ， 主 耶 和 华 如 此 说 ： 我 必 使 我 的 圣 所 ， 就 是 你 们 势 力 所 夸 耀 、 眼 里 所 喜 爱 、 心 中 所 爱 惜 的 被 亵 渎 ， 并 且 你 们 所 遗 留 的 儿 女 必 倒 在 刀 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21079', '26', '24', '22', '那 时 ， 你 们 必 行 我 仆 人 所 行 的 ， 不 蒙 着 嘴 唇 ， 也 不 吃 吊 丧 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21080', '26', '24', '23', '你 们 仍 要 头 上 勒 裹 头 巾 ， 脚 上 穿 鞋 ； 不 可 悲 哀 哭 泣 。 你 们 必 因 自 己 的 罪 孽 相 对 叹 息 ， 渐 渐 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21081', '26', '24', '24', '以 西 结 必 这 样 为 你 们 作 预 兆 ； 凡 他 所 行 的 ， 你 们 也 必 照 样 行 。 那 事 来 到 ， 你 们 就 知 道 我 是 主 耶 和 华 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21082', '26', '24', '25', '“ 人 子 啊 ， 我 除 掉 他 们 所 倚 靠 、 所 欢 喜 的 荣 耀 ， 并 眼 中 所 喜 爱 、 心 里 所 重 看 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21083', '26', '24', '26', '那 日 逃 脱 的 人 岂 不 来 到 你 这 里 ， 使 你 耳 闻 这 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21084', '26', '24', '27', '你 必 向 逃 脱 的 人 开 口 说 话 ， 不 再 哑 口 。 你 必 这 样 为 他 们 作 预 兆 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21085', '26', '25', '1', '＜ 预 言 亚 扪 受 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21086', '26', '25', '2', '“ 人 子 啊 ， 你 要 面 向 亚 扪 人 说 预 言 ， 攻 击 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21087', '26', '25', '3', '说 ： 你 们 当 听 主 耶 和 华 的 话 。 主 耶 和 华 如 此 说 ： 我 的 圣 所 被 亵 渎 ， 以 色 列 地 变 荒 凉 ， 犹 大 家 被 掳 掠 ； 那 时 ， 你 便 因 这 些 事 说 ： ‘ 阿 哈 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21088', '26', '25', '4', '所 以 我 必 将 你 的 地 交 给 东 方 人 为 业 ； 他 们 必 在 你 的 地 上 安 营 居 住 ， 吃 你 的 果 子 ， 喝 你 的 奶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21089', '26', '25', '5', '我 必 使 拉 巴 为 骆 驼 场 ， 使 亚 扪 人 的 地 为 羊 群 躺 卧 之 处 ， 你 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21090', '26', '25', '6', '主 耶 和 华 如 此 说 ： “ 因 你 拍 手 顿 足 ， 以 满 心 的 恨 恶 向 以 色 列 地 欢 喜 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21091', '26', '25', '7', '所 以 我 伸 手 攻 击 你 ， 将 你 交 给 列 国 作 为 掳 物 。 我 必 从 万 民 中 剪 除 你 ， 使 你 从 万 国 中 败 亡 。 我 必 除 灭 你 ， 你 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21092', '26', '25', '8', '＜ 斥 责 摩 押 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21093', '26', '25', '9', '所 以 我 要 破 开 摩 押 边 界 上 的 城 邑 ， 就 是 摩 押 人 看 为 本 国 之 荣 耀 的 伯 ． 耶 西 末 、 巴 力 ． 免 、 基 列 亭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21094', '26', '25', '10', '好 使 东 方 人 来 攻 击 亚 扪 人 。 我 必 将 亚 扪 人 之 地 交 给 他 们 为 业 ， 使 亚 扪 人 在 列 国 中 不 再 被 记 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21095', '26', '25', '11', '我 必 向 摩 押 施 行 审 判 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21096', '26', '25', '12', '＜ 斥 责 以 东 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21097', '26', '25', '13', '所 以 主 耶 和 华 如 此 说 ： 我 必 伸 手 攻 击 以 东 ， 剪 除 人 与 牲 畜 ， 使 以 东 从 提 幔 起 ， 人 必 倒 在 刀 下 ， 地 要 变 为 荒 凉 ， 直 到 底 但 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21098', '26', '25', '14', '我 必 藉 我 民 以 色 列 的 手 报 复 以 东 ； 以 色 列 民 必 照 我 的 怒 气 ， 按 我 的 忿 怒 在 以 东 施 报 ， 以 东 人 就 知 道 是 我 施 报 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21099', '26', '25', '15', '＜ 斥 责 非 利 士 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21100', '26', '25', '16', '所 以 主 耶 和 华 如 此 说 ： 我 必 伸 手 攻 击 非 利 士 人 ， 剪 除 基 利 提 人 ， 灭 绝 沿 海 剩 下 的 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21101', '26', '25', '17', '我 向 他 们 大 施 报 应 ， 发 怒 斥 责 他 们 。 我 报 复 他 们 的 时 候 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21102', '26', '26', '1', '＜ 斥 责 泰 尔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21103', '26', '26', '2', '“ 人 子 啊 ， 因 泰 尔 向 耶 路 撒 冷 说 ： ‘ 阿 哈 ， 那 作 众 民 之 门 的 已 经 破 坏 ， 向 我 开 放 ； 她 既 变 为 荒 场 ， 我 必 丰 盛 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21104', '26', '26', '3', '所 以 ， 主 耶 和 华 如 此 说 ： 泰 尔 啊 ， 我 必 与 你 为 敌 ， 使 许 多 国 民 上 来 攻 击 你 ， 如 同 海 使 波 浪 涌 上 来 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21105', '26', '26', '4', '他 们 必 破 坏 泰 尔 的 墙 垣 ， 拆 毁 她 的 城 楼 。 我 也 要 刮 净 尘 土 ， 使 她 成 为 净 光 的 磐 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21106', '26', '26', '5', '她 必 在 海 中 作 晒 网 的 地 方 ， 也 必 成 为 列 国 的 掳 物 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21107', '26', '26', '6', '属 泰 尔 城 邑 的 居 民 ｛ 原 文 是 田 间 的 众 女 ； 八 节 同 ｝ 必 被 刀 剑 杀 灭 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21108', '26', '26', '7', '主 耶 和 华 如 此 说 ： “ 我 必 使 诸 王 之 王 的 巴 比 伦 王 尼 布 甲 尼 撒 率 领 马 匹 车 辆 、 马 兵 、 军 队 ， 和 许 多 人 民 从 北 方 来 攻 击 你 泰 尔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21109', '26', '26', '8', '他 必 用 刀 剑 杀 灭 属 你 城 邑 的 居 民 ， 也 必 造 台 筑 垒 举 盾 牌 攻 击 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21110', '26', '26', '9', '他 必 安 设 撞 城 锤 攻 破 你 的 墙 垣 ， 用 铁 器 拆 毁 你 的 城 楼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21111', '26', '26', '10', '因 他 的 马 匹 众 多 ， 尘 土 扬 起 遮 蔽 你 。 他 进 入 你 的 城 门 ， 好 像 人 进 入 已 有 破 口 之 城 。 那 时 ， 你 的 墙 垣 必 因 骑 马 的 和 战 车 、 辎 重 车 的 响 声 震 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21112', '26', '26', '11', '他 的 马 蹄 必 践 踏 你 一 切 的 街 道 ； 他 必 用 刀 杀 戮 你 的 居 民 。 你 坚 固 的 柱 子 ｛ 或 译 ： 柱 像 ｝ 必 倒 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21113', '26', '26', '12', '人 必 以 你 的 财 宝 为 掳 物 ， 以 你 的 货 财 为 掠 物 ， 破 坏 你 的 墙 垣 ， 拆 毁 你 华 美 的 房 屋 ， 将 你 的 石 头 、 木 头 、 尘 土 都 抛 在 水 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21114', '26', '26', '13', '我 必 使 你 唱 歌 的 声 音 止 息 ； 人 也 不 再 听 见 你 弹 琴 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21115', '26', '26', '14', '我 必 使 你 成 为 净 光 的 磐 石 ， 作 晒 网 的 地 方 。 你 不 得 再 被 建 造 ， 因 为 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21116', '26', '26', '15', '主 耶 和 华 对 泰 尔 如 此 说 ： “ 在 你 中 间 行 杀 戮 ， 受 伤 之 人 唉 哼 的 时 候 ， 因 你 倾 倒 的 响 声 ， 海 岛 岂 不 都 震 动 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21117', '26', '26', '16', '那 时 靠 海 的 君 王 必 都 下 位 ， 除 去 朝 服 ， 脱 下 花 衣 ， 披 上 战 兢 ， 坐 在 地 上 ， 时 刻 发 抖 ， 为 你 惊 骇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21118', '26', '26', '17', '他 们 必 为 你 作 起 哀 歌 说 ： 你 这 有 名 之 城 ， 素 为 航 海 之 人 居 住 ， 在 海 上 为 最 坚 固 的 ； 平 日 你 和 居 民 使 一 切 住 在 那 里 的 人 无 不 惊 恐 ； 现 在 何 竟 毁 灭 了 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21119', '26', '26', '18', '如 今 在 你 这 倾 覆 的 日 子 ， 海 岛 都 必 战 兢 ； 海 中 的 群 岛 见 你 归 于 无 有 就 都 惊 惶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21120', '26', '26', '19', '主 耶 和 华 如 此 说 ： “ 泰 尔 啊 ， 我 使 你 变 为 荒 凉 ， 如 无 人 居 住 的 城 邑 ； 又 使 深 水 漫 过 你 ， 大 水 淹 没 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21121', '26', '26', '20', '那 时 ， 我 要 叫 你 下 入 阴 府 ， 与 古 时 的 人 一 同 在 地 的 深 处 、 久 已 荒 凉 之 地 居 住 ， 使 你 不 再 有 居 民 。 我 也 要 在 活 人 之 地 显 荣 耀 ｛ 我 也 … … 荣 耀 ： 或 译 在 活 人 之 地 不 再 有 荣 耀 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21122', '26', '26', '21', '我 必 叫 你 令 人 惊 恐 ， 不 再 存 留 于 世 ； 人 虽 寻 找 你 ， 却 永 寻 不 见 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21123', '26', '27', '1', '＜ 哀 悼 泰 尔 的 挽 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21124', '26', '27', '2', '“ 人 子 啊 ， 要 为 泰 尔 作 起 哀 歌 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21125', '26', '27', '3', '说 ： 你 居 住 海 口 ， 是 众 民 的 商 埠 ； 你 的 交 易 通 到 许 多 的 海 岛 。 主 耶 和 华 如 此 说 ： 泰 尔 啊 ， 你 曾 说 ： 我 是 全 然 美 丽 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21126', '26', '27', '4', '你 的 境 界 在 海 中 ， 造 你 的 使 你 全 然 美 丽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21127', '26', '27', '5', '他 们 用 示 尼 珥 的 松 树 做 你 的 一 切 板 ， 用 黎 巴 嫩 的 香 柏 树 做 桅 杆 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21128', '26', '27', '6', '用 巴 珊 的 橡 树 做 你 的 桨 ， 用 象 牙 镶 嵌 基 提 海 岛 的 黄 杨 木 为 坐 板 ｛ 或 译 ： 舱 板 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21129', '26', '27', '7', '你 的 篷 帆 是 用 埃 及 绣 花 细 麻 布 做 的 ， 可 以 做 你 的 大 旗 ； 你 的 凉 棚 是 用 以 利 沙 岛 的 蓝 色 、 紫 色 布 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21130', '26', '27', '8', '西 顿 和 亚 发 的 居 民 作 你 荡 桨 的 。 泰 尔 啊 ， 你 中 间 的 智 慧 人 作 掌 舵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21131', '26', '27', '9', '迦 巴 勒 的 老 者 和 聪 明 人 都 在 你 中 间 作 补 缝 的 ； 一 切 泛 海 的 船 只 和 水 手 都 在 你 中 间 经 营 交 易 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21132', '26', '27', '10', '“ 波 斯 人 、 路 德 人 、 弗 人 在 你 军 营 中 作 战 士 ； 他 们 在 你 中 间 悬 挂 盾 牌 和 头 盔 ， 彰 显 你 的 尊 荣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21133', '26', '27', '11', '亚 发 人 和 你 的 军 队 都 在 你 四 围 的 墙 上 ， 你 的 望 楼 也 有 勇 士 ； 他 们 悬 挂 盾 牌 ， 成 全 你 的 美 丽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21134', '26', '27', '12', '“ 他 施 人 因 你 多 有 各 类 的 财 物 ， 就 作 你 的 客 商 ， 拿 银 、 铁 、 锡 、 铅 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21135', '26', '27', '13', '雅 完 人 、 土 巴 人 、 米 设 人 都 与 你 交 易 ； 他 们 用 人 口 和 铜 器 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21136', '26', '27', '14', '陀 迦 玛 族 用 马 和 战 马 并 骡 子 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21137', '26', '27', '15', '底 但 人 与 你 交 易 ， 许 多 海 岛 作 你 的 码 头 ； 他 们 拿 象 牙 、 乌 木 与 你 兑 换 ｛ 或 译 ： 进 贡 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21138', '26', '27', '16', '亚 兰 人 因 你 的 工 作 很 多 ， 就 作 你 的 客 商 ； 他 们 用 绿 宝 石 、 紫 色 布 绣 货 、 细 麻 布 、 珊 瑚 、 红 宝 石 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21139', '26', '27', '17', '犹 大 和 以 色 列 地 的 人 都 与 你 交 易 ； 他 们 用 米 匿 的 麦 子 、 饼 、 蜜 、 油 、 乳 香 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21140', '26', '27', '18', '大 马 士 革 人 因 你 的 工 作 很 多 ， 又 因 你 多 有 各 类 的 财 物 ， 就 拿 黑 本 酒 和 白 羊 毛 与 你 交 易 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21141', '26', '27', '19', '威 但 人 和 雅 完 人 拿 纺 成 的 线 、 亮 铁 、 桂 皮 、 菖 蒲 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21142', '26', '27', '20', '底 但 人 用 高 贵 的 毯 子 、 鞍 、 屉 与 你 交 易 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21143', '26', '27', '21', '阿 拉 伯 人 和 基 达 的 一 切 首 领 都 作 你 的 客 商 ， 用 羊 羔 、 公 绵 羊 、 公 山 羊 与 你 交 易 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21144', '26', '27', '22', '示 巴 和 拉 玛 的 商 人 与 你 交 易 ， 他 们 用 各 类 上 好 的 香 料 、 各 类 的 宝 石 ， 和 黄 金 兑 换 你 的 货 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21145', '26', '27', '23', '哈 兰 人 、 干 尼 人 、 伊 甸 人 、 示 巴 的 商 人 ， 和 亚 述 人 、 基 抹 人 与 你 交 易 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21146', '26', '27', '24', '这 些 商 人 以 美 好 的 货 物 包 在 绣 花 蓝 色 包 袱 内 ， 又 有 华 丽 的 衣 服 装 在 香 柏 木 的 箱 子 里 ， 用 绳 捆 着 与 你 交 易 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21147', '26', '27', '25', '他 施 的 船 只 接 连 成 帮 为 你 运 货 ， 你 便 在 海 中 丰 富 极 其 荣 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21148', '26', '27', '26', '荡 桨 的 已 经 把 你 荡 到 大 水 之 处 ， 东 风 在 海 中 将 你 打 破 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21149', '26', '27', '27', '你 的 资 财 、 物 件 、 货 物 、 水 手 、 掌 舵 的 、 补 缝 的 、 经 营 交 易 的 ， 并 你 中 间 的 战 士 和 人 民 ， 在 你 破 坏 的 日 子 必 都 沉 在 海 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21150', '26', '27', '28', '你 掌 舵 的 呼 号 之 声 一 发 ， 郊 野 都 必 震 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21151', '26', '27', '29', '凡 荡 桨 的 和 水 手 ， 并 一 切 泛 海 掌 舵 的 ， 都 必 下 船 登 岸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21152', '26', '27', '30', '他 们 必 为 你 放 声 痛 哭 ， 把 尘 土 撒 在 头 上 ， 在 灰 中 打 滚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21153', '26', '27', '31', '又 为 你 使 头 上 光 秃 ， 用 麻 布 束 腰 ， 号 啕 痛 哭 ， 苦 苦 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21154', '26', '27', '32', '他 们 哀 号 的 时 候 ， 为 你 作 起 哀 歌 哀 哭 ， 说 ： 有 何 城 如 泰 尔 ？ 有 何 城 如 她 在 海 中 成 为 寂 寞 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21155', '26', '27', '33', '你 由 海 上 运 出 货 物 ， 就 使 许 多 国 民 充 足 ； 你 以 许 多 资 财 、 货 物 使 地 上 的 君 王 丰 富 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21156', '26', '27', '34', '你 在 深 水 中 被 海 浪 打 破 的 时 候 ， 你 的 货 物 和 你 中 间 的 一 切 人 民 ， 就 都 沉 下 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21157', '26', '27', '35', '海 岛 的 居 民 为 你 惊 奇 ； 他 们 的 君 王 都 甚 恐 慌 ， 面 带 愁 容 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21158', '26', '27', '36', '各 国 民 中 的 客 商 都 向 你 发 嘶 声 ； 你 令 人 惊 恐 ， 不 再 存 留 于 世 ， 直 到 永 远 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21159', '26', '28', '1', '＜ 斥 责 泰 尔 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21160', '26', '28', '2', '“ 人 子 啊 ， 你 对 泰 尔 君 王 说 ， 主 耶 和 华 如 此 说 ： 因 你 心 里 高 傲 ， 说 ： 我 是 神 ； 我 在 海 中 坐 神 之 位 。 你 虽 然 居 心 自 比 神 ， 也 不 过 是 人 ， 并 不 是 神 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21161', '26', '28', '3', '看 哪 ， 你 比 但 以 理 更 有 智 慧 ， 什 么 秘 事 都 不 能 向 你 隐 藏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21162', '26', '28', '4', '你 靠 自 己 的 智 慧 聪 明 得 了 金 银 财 宝 ， 收 入 库 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21163', '26', '28', '5', '你 靠 自 己 的 大 智 慧 和 贸 易 增 添 资 财 ， 又 因 资 财 心 里 高 傲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21164', '26', '28', '6', '所 以 主 耶 和 华 如 此 说 ： 因 你 居 心 自 比 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21165', '26', '28', '7', '我 必 使 外 邦 人 ， 就 是 列 国 中 的 强 暴 人 临 到 你 这 里 ； 他 们 必 拔 刀 砍 坏 你 用 智 慧 得 来 的 美 物 ， 亵 渎 你 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21166', '26', '28', '8', '他 们 必 使 你 下 坑 ； 你 必 死 在 海 中 ， 与 被 杀 的 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21167', '26', '28', '9', '在 杀 你 的 人 面 前 你 还 能 说 “ 我 是 神 ” 吗 ？ 其 实 你 在 杀 害 你 的 人 手 中 ， 不 过 是 人 ， 并 不 是 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21168', '26', '28', '10', '你 必 死 在 外 邦 人 手 中 ， 与 未 受 割 礼 ｛ 或 译 ： 不 洁 ； 下 同 ｝ 的 人 一 样 ， 因 为 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21169', '26', '28', '11', '＜ 泰 尔 王 的 终 局 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21170', '26', '28', '12', '“ 人 子 啊 ， 你 为 泰 尔 王 作 起 哀 歌 ， 说 主 耶 和 华 如 此 说 ： 你 无 所 不 备 ， 智 慧 充 足 ， 全 然 美 丽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21171', '26', '28', '13', '你 曾 在 伊 甸 神 的 园 中 ， 佩 戴 各 样 宝 石 ， 就 是 红 宝 石 、 红 璧 玺 、 金 钢 石 、 水 苍 玉 、 红 玛 瑙 、 碧 玉 、 蓝 宝 石 、 绿 宝 石 、 红 玉 ， 和 黄 金 ； 又 有 精 美 的 鼓 笛 在 你 那 里 ， 都 是 在 你 受 造 之 日 预 备 齐 全 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21172', '26', '28', '14', '你 是 那 受 膏 遮 掩 约 柜 的 基 路 伯 ； 我 将 你 安 置 在 神 的 圣 山 上 ； 你 在 发 光 如 火 的 宝 石 中 间 往 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21173', '26', '28', '15', '你 从 受 造 之 日 所 行 的 都 完 全 ， 后 来 在 你 中 间 又 察 出 不 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21174', '26', '28', '16', '因 你 贸 易 很 多 ， 就 被 强 暴 的 事 充 满 ， 以 致 犯 罪 ， 所 以 我 因 你 亵 渎 圣 地 ， 就 从 神 的 山 驱 逐 你 。 遮 掩 约 柜 的 基 路 伯 啊 ， 我 已 将 你 从 发 光 如 火 的 宝 石 中 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21175', '26', '28', '17', '你 因 美 丽 心 中 高 傲 ， 又 因 荣 光 败 坏 智 慧 ， 我 已 将 你 摔 倒 在 地 ， 使 你 倒 在 君 王 面 前 ， 好 叫 他 们 目 睹 眼 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21176', '26', '28', '18', '你 因 罪 孽 众 多 ， 贸 易 不 公 ， 就 亵 渎 你 那 里 的 圣 所 。 故 此 ， 我 使 火 从 你 中 间 发 出 ， 烧 灭 你 ， 使 你 在 所 有 观 看 的 人 眼 前 变 为 地 上 的 炉 灰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21177', '26', '28', '19', '各 国 民 中 ， 凡 认 识 你 的 ， 都 必 为 你 惊 奇 。 你 令 人 惊 恐 ， 不 再 存 留 于 世 ， 直 到 永 远 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21178', '26', '28', '20', '＜ 斥 责 西 顿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21179', '26', '28', '21', '“ 人 子 啊 ， 你 要 向 西 顿 预 言 攻 击 她 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21180', '26', '28', '22', '说 主 耶 和 华 如 此 说 ： 西 顿 哪 ， 我 与 你 为 敌 ， 我 必 在 你 中 间 得 荣 耀 。 我 在 你 中 间 施 行 审 判 、 显 为 圣 的 时 候 ， 人 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21181', '26', '28', '23', '我 必 使 瘟 疫 进 入 西 顿 ， 使 血 流 在 她 街 上 。 被 杀 的 必 在 其 中 仆 倒 ， 四 围 有 刀 剑 临 到 她 ， 人 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21182', '26', '28', '24', '＜ 以 色 列 要 蒙 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21183', '26', '28', '25', '主 耶 和 华 如 此 说 ： “ 我 将 分 散 在 万 民 中 的 以 色 列 家 招 聚 回 来 ， 向 他 们 在 列 邦 人 眼 前 显 为 圣 的 时 候 ， 他 们 就 在 我 赐 给 我 仆 人 雅 各 之 地 ， 仍 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21184', '26', '28', '26', '他 们 要 在 这 地 上 安 然 居 住 。 我 向 四 围 恨 恶 他 们 的 众 人 施 行 审 判 以 后 ， 他 们 要 盖 造 房 屋 ， 栽 种 葡 萄 园 ， 安 然 居 住 ， 就 知 道 我 是 耶 和 华 ─ ─ 他 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21185', '26', '29', '1', '＜ 斥 责 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21186', '26', '29', '2', '“ 人 子 啊 ， 你 要 向 埃 及 王 法 老 预 言 攻 击 他 和 埃 及 全 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21187', '26', '29', '3', '说 主 耶 和 华 如 此 说 ： 埃 及 王 法 老 啊 ， 我 与 你 这 卧 在 自 己 河 中 的 大 鱼 为 敌 。 你 曾 说 ： 这 河 是 我 的 ， 是 我 为 自 己 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21188', '26', '29', '4', '我 ─ ─ 耶 和 华 必 用 钩 子 钩 住 你 的 腮 颊 ， 又 使 江 河 中 的 鱼 贴 住 你 的 鳞 甲 ； 我 必 将 你 和 所 有 贴 住 你 鳞 甲 的 鱼 ， 从 江 河 中 拉 上 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21189', '26', '29', '5', '把 你 并 江 河 中 的 鱼 都 抛 在 旷 野 ； 你 必 倒 在 田 间 ， 不 被 收 殓 ， 不 被 掩 埋 。 我 已 将 你 给 地 上 野 兽 、 空 中 飞 鸟 作 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21190', '26', '29', '6', '“ 埃 及 一 切 的 居 民 ， 因 向 以 色 列 家 成 了 芦 苇 的 杖 ， 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21191', '26', '29', '7', '他 们 用 手 持 住 你 ， 你 就 断 折 ， 伤 了 他 们 的 肩 ； 他 们 倚 靠 你 ， 你 就 断 折 ， 闪 了 他 们 的 腰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21192', '26', '29', '8', '所 以 主 耶 和 华 如 此 说 ： 我 必 使 刀 剑 临 到 你 ， 从 你 中 间 将 人 与 牲 畜 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21193', '26', '29', '9', '埃 及 地 必 荒 废 凄 凉 ， 他 们 就 知 道 我 是 耶 和 华 。 “ 因 为 法 老 说 ： ‘ 这 河 是 我 的 ， 是 我 所 造 的 ’ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21194', '26', '29', '10', '所 以 我 必 与 你 并 你 的 江 河 为 敌 ， 使 埃 及 地 ， 从 色 弗 尼 塔 直 到 古 实 境 界 ， 全 然 荒 废 凄 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21195', '26', '29', '11', '人 的 脚 、 兽 的 蹄 都 不 经 过 ， 四 十 年 之 久 并 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21196', '26', '29', '12', '我 必 使 埃 及 地 在 荒 凉 的 国 中 成 为 荒 凉 ， 使 埃 及 城 在 荒 废 的 城 中 变 为 荒 废 ， 共 有 四 十 年 。 我 必 将 埃 及 人 分 散 在 列 国 ， 四 散 在 列 邦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21197', '26', '29', '13', '主 耶 和 华 如 此 说 ： “ 满 了 四 十 年 ， 我 必 招 聚 分 散 在 各 国 民 中 的 埃 及 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21198', '26', '29', '14', '我 必 叫 埃 及 被 掳 的 人 回 来 ， 使 他 们 归 回 本 地 巴 忒 罗 。 在 那 里 必 成 为 低 微 的 国 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21199', '26', '29', '15', '必 为 列 国 中 最 低 微 的 ， 也 不 再 自 高 于 列 国 之 上 。 我 必 减 少 他 们 ， 以 致 不 再 辖 制 列 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21200', '26', '29', '16', '埃 及 必 不 再 作 以 色 列 家 所 倚 靠 的 ； 以 色 列 家 仰 望 埃 及 人 的 时 候 ， 便 思 念 罪 孽 。 他 们 就 知 道 我 是 主 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21201', '26', '29', '17', '＜ 尼 布 甲 尼 撒 要 征 服 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21202', '26', '29', '18', '“ 人 子 啊 ， 巴 比 伦 王 尼 布 甲 尼 撒 使 他 的 军 兵 大 大 效 劳 ， 攻 打 泰 尔 ， 以 致 头 都 光 秃 ， 肩 都 磨 破 ； 然 而 他 和 他 的 军 兵 攻 打 泰 尔 ， 并 没 有 从 那 里 得 什 么 酬 劳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21203', '26', '29', '19', '所 以 主 耶 和 华 如 此 说 ： 我 必 将 埃 及 地 赐 给 巴 比 伦 王 尼 布 甲 尼 撒 ； 他 必 掳 掠 埃 及 群 众 ， 抢 其 中 的 财 为 掳 物 ， 夺 其 中 的 货 为 掠 物 ， 这 就 可 以 作 他 军 兵 的 酬 劳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21204', '26', '29', '20', '我 将 埃 及 地 赐 给 他 ， 酬 他 所 效 的 劳 ， 因 王 与 军 兵 是 为 我 勤 劳 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21205', '26', '29', '21', '“ 当 那 日 ， 我 必 使 以 色 列 家 的 角 发 生 ， 又 必 使 你 ─ ─ 以 西 结 在 他 们 中 间 得 以 开 口 ； 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21206', '26', '30', '1', '＜ 耶 和 华 要 惩 罚 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21207', '26', '30', '2', '“ 人 子 啊 ， 你 要 发 预 言 说 ， 主 耶 和 华 如 此 说 ： 哀 哉 这 日 ！ 你 们 应 当 哭 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21208', '26', '30', '3', '因 为 耶 和 华 的 日 子 临 近 ， 就 是 密 云 之 日 ， 列 国 受 罚 之 期 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21209', '26', '30', '4', '必 有 刀 剑 临 到 埃 及 ； 在 埃 及 被 杀 之 人 仆 倒 的 时 候 ， 古 实 人 就 有 痛 苦 ， 人 民 必 被 掳 掠 ， 基 址 必 被 拆 毁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21210', '26', '30', '5', '古 实 人 、 弗 人 ｛ 或 译 ： 利 比 亚 ｝ 、 路 德 人 、 杂 族 的 人 民 ， 并 古 巴 人 ， 以 及 同 盟 之 地 的 人 都 要 与 埃 及 人 一 同 倒 在 刀 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21211', '26', '30', '6', '耶 和 华 如 此 说 ： 扶 助 埃 及 的 也 必 倾 倒 。 埃 及 因 势 力 而 有 的 骄 傲 必 降 低 微 ； 其 中 的 人 民 ， 从 色 弗 尼 塔 起 ｛ 见 二 十 九 章 十 节 ｝ 必 倒 在 刀 下 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21212', '26', '30', '7', '埃 及 地 在 荒 凉 的 国 中 必 成 为 荒 凉 ； 埃 及 城 在 荒 废 的 城 中 也 变 为 荒 废 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21213', '26', '30', '8', '我 在 埃 及 中 使 火 着 起 ； 帮 助 埃 及 的 ， 都 被 灭 绝 。 那 时 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21214', '26', '30', '9', '“ 到 那 日 ， 必 有 使 者 坐 船 ， 从 我 面 前 出 去 ， 使 安 逸 无 虑 的 古 实 人 惊 惧 ； 必 有 痛 苦 临 到 他 们 ， 好 像 埃 及 遭 灾 的 日 子 一 样 。 看 哪 ， 这 事 临 近 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21215', '26', '30', '10', '主 耶 和 华 如 此 说 ： 我 必 藉 巴 比 伦 王 尼 布 甲 尼 撒 的 手 ， 除 灭 埃 及 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21216', '26', '30', '11', '他 和 随 从 他 的 人 ， 就 是 列 国 中 强 暴 的 ， 必 进 来 毁 灭 这 地 。 他 们 必 拔 刀 攻 击 埃 及 ， 使 遍 地 有 被 杀 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21217', '26', '30', '12', '我 必 使 江 河 干 涸 ， 将 地 卖 在 恶 人 的 手 中 ； 我 必 藉 外 邦 人 的 手 ， 使 这 地 和 其 中 所 有 的 变 为 凄 凉 。 这 是 我 ─ ─ 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21218', '26', '30', '13', '主 耶 和 华 如 此 说 ： 我 必 毁 灭 偶 像 ， 从 挪 弗 除 灭 神 像 ； 必 不 再 有 君 王 出 自 埃 及 地 。 我 要 使 埃 及 地 的 人 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21219', '26', '30', '14', '我 必 使 巴 忒 罗 荒 凉 ， 在 琐 安 中 使 火 着 起 ， 向 挪 施 行 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21220', '26', '30', '15', '我 必 将 我 的 忿 怒 倒 在 埃 及 的 保 障 上 ， 就 是 训 上 ， 并 要 剪 除 挪 的 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21221', '26', '30', '16', '我 必 在 埃 及 中 使 火 着 起 ； 训 必 大 大 痛 苦 ； 挪 必 被 攻 破 ； 挪 弗 白 日 ｛ 或 译 ： 终 日 ｝ 见 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21222', '26', '30', '17', '亚 文 和 比 伯 实 的 少 年 人 必 倒 在 刀 下 ； 这 些 城 的 人 必 被 掳 掠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21223', '26', '30', '18', '我 在 答 比 匿 折 断 埃 及 的 诸 轭 ， 使 她 因 势 力 而 有 的 骄 傲 在 其 中 止 息 。 那 时 ， 日 光 必 退 去 ； 至 于 这 城 ， 必 有 密 云 遮 蔽 ， 其 中 的 女 子 必 被 掳 掠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21224', '26', '30', '19', '我 必 这 样 向 埃 及 施 行 审 判 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21225', '26', '30', '20', '＜ 埃 及 王 破 碎 的 力 量 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21226', '26', '30', '21', '“ 人 子 啊 ， 我 已 打 折 埃 及 王 法 老 的 膀 臂 ； 没 有 敷 药 ， 也 没 有 用 布 缠 好 ， 使 他 有 力 持 刀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21227', '26', '30', '22', '所 以 主 耶 和 华 如 此 说 ： 看 哪 ， 我 与 埃 及 王 法 老 为 敌 ， 必 将 他 有 力 的 膀 臂 和 已 打 折 的 膀 臂 全 行 打 断 ， 使 刀 从 他 手 中 坠 落 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21228', '26', '30', '23', '我 必 将 埃 及 人 分 散 在 列 国 ， 四 散 在 列 邦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21229', '26', '30', '24', '我 必 使 巴 比 伦 王 的 膀 臂 有 力 ， 将 我 的 刀 交 在 他 手 中 ； 却 要 打 断 法 老 的 膀 臂 ， 他 就 在 巴 比 伦 王 面 前 唉 哼 ， 如 同 受 死 伤 的 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21230', '26', '30', '25', '我 必 扶 持 巴 比 伦 王 的 膀 臂 ， 法 老 的 膀 臂 却 要 下 垂 ； 我 将 我 的 刀 交 在 巴 比 伦 王 手 中 ， 他 必 举 刀 攻 击 埃 及 地 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21231', '26', '30', '26', '我 必 将 埃 及 人 分 散 在 列 国 ， 四 散 在 列 邦 ； 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21232', '26', '31', '1', '＜ 以 香 柏 树 比 拟 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21233', '26', '31', '2', '“ 人 子 啊 ， 你 要 向 埃 及 王 法 老 和 他 的 众 人 说 ： 在 威 势 上 谁 能 与 你 相 比 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21234', '26', '31', '3', '亚 述 王 曾 如 黎 巴 嫩 中 的 香 柏 树 ， 枝 条 荣 美 ， 影 密 如 林 ， 极 其 高 大 ， 树 尖 插 入 云 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21235', '26', '31', '4', '众 水 使 它 生 长 ； 深 水 使 它 长 大 。 所 栽 之 地 有 江 河 围 流 ， 汊 出 的 水 道 延 到 田 野 诸 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21236', '26', '31', '5', '所 以 他 高 大 超 过 田 野 诸 树 ； 发 旺 的 时 候 ， 枝 子 繁 多 ， 因 得 大 水 之 力 枝 条 长 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21237', '26', '31', '6', '空 中 的 飞 鸟 都 在 枝 子 上 搭 窝 ； 田 野 的 走 兽 都 在 枝 条 下 生 子 ； 所 有 大 国 的 人 民 都 在 它 荫 下 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21238', '26', '31', '7', '树 大 条 长 ， 成 为 荣 美 ， 因 为 根 在 众 水 之 旁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21239', '26', '31', '8', '神 园 中 的 香 柏 树 不 能 遮 蔽 它 ； 松 树 不 及 它 的 枝 子 ； 枫 树 不 及 它 的 枝 条 ； 神 园 中 的 树 都 没 有 它 荣 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21240', '26', '31', '9', '我 使 它 的 枝 条 蕃 多 ， 成 为 荣 美 ， 以 致 神 伊 甸 园 中 的 树 都 嫉 妒 它 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21241', '26', '31', '10', '所 以 主 耶 和 华 如 此 说 ： “ 因 它 高 大 ， 树 尖 插 入 云 中 ， 心 骄 气 傲 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21242', '26', '31', '11', '我 就 必 将 它 交 给 列 国 中 大 有 威 势 的 人 ； 他 必 定 办 它 。 我 因 它 的 罪 恶 ， 已 经 驱 逐 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21243', '26', '31', '12', '外 邦 人 ， 就 是 列 邦 中 强 暴 的 ， 将 它 砍 断 弃 掉 。 它 的 枝 条 落 在 山 间 和 一 切 谷 中 ， 它 的 枝 子 折 断 ， 落 在 地 的 一 切 河 旁 。 地 上 的 众 民 已 经 走 去 ， 离 开 它 的 荫 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21244', '26', '31', '13', '空 中 的 飞 鸟 都 要 宿 在 这 败 落 的 树 上 ， 田 野 的 走 兽 都 要 卧 在 它 的 枝 条 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21245', '26', '31', '14', '好 使 水 旁 的 诸 树 不 因 高 大 而 自 尊 ， 也 不 将 树 尖 插 入 云 中 ， 并 且 那 些 得 水 滋 润 、 有 势 力 的 ， 也 不 得 高 大 自 立 。 因 为 它 们 在 世 人 中 ， 和 下 坑 的 人 都 被 交 与 死 亡 ， 到 阴 府 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21246', '26', '31', '15', '主 耶 和 华 如 此 说 ： “ 它 下 阴 间 的 那 日 ， 我 便 使 人 悲 哀 。 我 为 它 遮 盖 深 渊 ， 使 江 河 凝 结 ， 大 水 停 流 ； 我 也 使 黎 巴 嫩 为 它 凄 惨 ， 田 野 的 诸 树 都 因 它 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21247', '26', '31', '16', '我 将 它 扔 到 阴 间 ， 与 下 坑 的 人 一 同 下 去 。 那 时 ， 列 国 听 见 它 坠 落 的 响 声 就 都 震 动 ， 并 且 伊 甸 的 一 切 树 ─ ─ 就 是 黎 巴 嫩 得 水 滋 润 、 最 佳 最 美 的 树 ─ ─ 都 在 阴 府 受 了 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21248', '26', '31', '17', '它 们 也 与 它 同 下 阴 间 ， 到 被 杀 的 人 那 里 。 它 们 曾 作 它 的 膀 臂 ， 在 列 国 中 它 的 荫 下 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21249', '26', '31', '18', '在 这 样 荣 耀 威 势 上 ， 在 伊 甸 园 诸 树 中 ， 谁 能 与 你 相 比 呢 ？ 然 而 你 要 与 伊 甸 的 诸 树 一 同 下 到 阴 府 ， 在 未 受 割 礼 的 人 中 ， 与 被 杀 的 人 一 同 躺 卧 。 “ 法 老 和 他 的 群 众 乃 是 如 此 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21250', '26', '32', '1', '＜ 以 鳄 鱼 比 拟 埃 及 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21251', '26', '32', '2', '“ 人 子 啊 ， 你 要 为 埃 及 王 法 老 作 哀 歌 ， 说 ： 从 前 你 在 列 国 中 ， 如 同 少 壮 狮 子 ； 现 在 你 却 像 海 中 的 大 鱼 。 你 冲 出 江 河 ， 用 爪 搅 动 诸 水 ， 使 江 河 浑 浊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21252', '26', '32', '3', '主 耶 和 华 如 此 说 ： 我 必 用 多 国 的 人 民 ， 将 我 的 网 撒 在 你 身 上 ， 把 你 拉 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21253', '26', '32', '4', '我 必 将 你 丢 在 地 上 ， 抛 在 田 野 ， 使 空 中 的 飞 鸟 都 落 在 你 身 上 ， 使 遍 地 的 野 兽 吃 你 得 饱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21254', '26', '32', '5', '我 必 将 你 的 肉 丢 在 山 间 ， 用 你 高 大 的 尸 首 填 满 山 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21255', '26', '32', '6', '我 又 必 用 你 的 血 浇 灌 你 所 游 泳 之 地 ， 漫 过 山 顶 ； 河 道 都 必 充 满 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21256', '26', '32', '7', '我 将 你 扑 灭 的 时 候 ， 要 把 天 遮 蔽 ， 使 众 星 昏 暗 ， 以 密 云 遮 掩 太 阳 ， 月 亮 也 不 放 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21257', '26', '32', '8', '我 必 使 天 上 的 亮 光 都 在 你 以 上 变 为 昏 暗 ， 使 你 的 地 上 黑 暗 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21258', '26', '32', '9', '“ 我 使 你 败 亡 的 风 声 传 到 你 所 不 认 识 的 各 国 。 那 时 ， 我 必 使 多 民 的 心 因 你 愁 烦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21259', '26', '32', '10', '我 在 许 多 国 民 和 君 王 面 前 向 你 抡 我 的 刀 ， 国 民 就 必 因 你 惊 奇 ， 君 王 也 必 因 你 极 其 恐 慌 。 在 你 仆 倒 的 日 子 ， 他 们 各 人 为 自 己 的 性 命 时 刻 战 兢 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21260', '26', '32', '11', '主 耶 和 华 如 此 说 ： “ 巴 比 伦 王 的 刀 必 临 到 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21261', '26', '32', '12', '我 必 藉 勇 士 的 刀 使 你 的 众 民 仆 倒 ； 这 勇 士 都 是 列 国 中 强 暴 的 。 他 们 必 使 埃 及 的 骄 傲 归 于 无 有 ； 埃 及 的 众 民 必 被 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21262', '26', '32', '13', '我 必 从 埃 及 多 水 旁 除 灭 所 有 的 走 兽 ； 人 脚 兽 蹄 必 不 再 搅 浑 这 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21263', '26', '32', '14', '那 时 ， 我 必 使 埃 及 河 澄 清 ， 江 河 像 油 缓 流 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21264', '26', '32', '15', '我 使 埃 及 地 变 为 荒 废 凄 凉 ； 这 地 缺 少 从 前 所 充 满 的 ， 又 击 杀 其 中 一 切 的 居 民 。 那 时 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21265', '26', '32', '16', '“ 人 必 用 这 哀 歌 去 哀 哭 ， 列 国 的 女 子 为 埃 及 和 她 的 群 众 也 必 以 此 悲 哀 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21266', '26', '32', '17', '＜ 为 埃 及 哀 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21267', '26', '32', '18', '“ 人 子 啊 ， 你 要 为 埃 及 群 众 哀 号 ， 又 要 将 埃 及 和 有 名 之 国 的 女 子 ， 并 下 坑 的 人 ， 一 同 扔 到 阴 府 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21268', '26', '32', '19', '你 埃 及 的 美 丽 胜 过 谁 呢 ？ 你 下 去 与 未 受 割 礼 的 人 一 同 躺 卧 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21269', '26', '32', '20', '他 们 必 在 被 杀 的 人 中 仆 到 。 她 被 交 给 刀 剑 ， 要 把 她 和 她 的 群 众 拉 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21270', '26', '32', '21', '强 盛 的 勇 士 要 在 阴 间 对 埃 及 王 和 帮 助 他 的 说 话 ； 他 们 是 未 受 割 礼 被 杀 的 人 ， 已 经 下 去 ， 躺 卧 不 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21271', '26', '32', '22', '“ 亚 述 和 她 的 众 民 都 在 那 里 ， 她 民 的 坟 墓 在 她 四 围 ； 他 们 都 是 被 杀 倒 在 刀 下 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21272', '26', '32', '23', '他 们 的 坟 墓 在 坑 中 极 深 之 处 。 她 的 众 民 在 她 坟 墓 的 四 围 ， 都 是 被 杀 倒 在 刀 下 的 ； 他 们 曾 在 活 人 之 地 使 人 惊 恐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21273', '26', '32', '24', '“ 以 拦 也 在 那 里 ， 她 的 群 众 在 她 坟 墓 的 四 围 ， 都 是 被 杀 倒 在 刀 下 、 未 受 割 礼 而 下 阴 府 的 ； 他 们 曾 在 活 人 之 地 使 人 惊 恐 ， 并 且 与 下 坑 的 人 一 同 担 当 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21274', '26', '32', '25', '人 给 她 和 她 的 群 众 在 被 杀 的 人 中 设 立 床 榻 。 她 民 的 坟 墓 在 她 四 围 ， 他 们 都 是 未 受 割 礼 被 刀 杀 的 ； 他 们 曾 在 活 人 之 地 使 人 惊 恐 ， 并 且 与 下 坑 的 人 一 同 担 当 羞 辱 。 以 拦 已 经 放 在 被 杀 的 人 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21275', '26', '32', '26', '“ 米 设 、 土 巴 ， 和 她 们 的 群 众 都 在 那 里 。 她 民 的 坟 墓 在 她 四 围 ， 他 们 都 是 未 受 割 礼 被 刀 杀 的 ； 他 们 曾 在 活 人 之 地 使 人 惊 恐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21276', '26', '32', '27', '他 们 不 得 与 那 未 受 割 礼 仆 倒 的 勇 士 一 同 躺 卧 ； 这 些 勇 士 带 着 兵 器 下 阴 间 ， 头 枕 刀 剑 ， 骨 头 上 有 本 身 的 罪 孽 ； 他 们 曾 在 活 人 之 地 使 勇 士 惊 恐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21277', '26', '32', '28', '“ 法 老 啊 ， 你 必 在 未 受 割 礼 的 人 中 败 坏 ， 与 那 些 被 杀 的 人 一 同 躺 卧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21278', '26', '32', '29', '“ 以 东 也 在 那 里 。 她 君 王 和 一 切 首 领 虽 然 仗 着 势 力 ， 还 是 放 在 被 杀 的 人 中 ； 他 们 必 与 未 受 割 礼 的 和 下 坑 的 人 一 同 躺 卧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21279', '26', '32', '30', '“ 在 那 里 有 北 方 的 众 王 子 和 一 切 西 顿 人 ， 都 与 被 杀 的 人 下 去 。 他 们 虽 然 仗 着 势 力 使 人 惊 恐 ， 还 是 蒙 羞 。 他 们 未 受 割 礼 ， 和 被 刀 杀 的 一 同 躺 卧 ， 与 下 坑 的 人 一 同 担 当 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21280', '26', '32', '31', '“ 法 老 看 见 他 们 ， 便 为 他 被 杀 的 军 队 受 安 慰 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21281', '26', '32', '32', '我 任 凭 法 老 在 活 人 之 地 使 人 惊 恐 ， 法 老 和 他 的 群 众 必 放 在 未 受 割 礼 和 被 杀 的 人 中 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21282', '26', '33', '1', '＜ 神 指 派 以 西 结 作 守 望 者 （ 结   3 : 1 6 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21283', '26', '33', '2', '“ 人 子 啊 ， 你 要 告 诉 本 国 的 子 民 说 ： 我 使 刀 剑 临 到 哪 一 国 ， 那 一 国 的 民 从 他 们 中 间 选 立 一 人 为 守 望 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21284', '26', '33', '3', '他 见 刀 剑 临 到 那 地 ， 若 吹 角 警 戒 众 民 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21285', '26', '33', '4', '凡 听 见 角 声 不 受 警 戒 的 ， 刀 剑 若 来 除 灭 了 他 ， 他 的 罪 ｛ 原 文 是 血 ｝ 就 必 归 到 自 己 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21286', '26', '33', '5', '他 听 见 角 声 ， 不 受 警 戒 ， 他 的 罪 必 归 到 自 己 的 身 上 ； 他 若 受 警 戒 ， 便 是 救 了 自 己 的 性 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21287', '26', '33', '6', '倘 若 守 望 的 人 见 刀 剑 临 到 ， 不 吹 角 ， 以 致 民 不 受 警 戒 ， 刀 剑 来 杀 了 他 们 中 间 的 一 个 人 ， 他 虽 然 死 在 罪 孽 之 中 ， 我 却 要 向 守 望 的 人 讨 他 丧 命 的 罪 ｛ 原 文 是 血 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21288', '26', '33', '7', '“ 人 子 啊 ， 我 照 样 立 你 作 以 色 列 家 守 望 的 人 。 所 以 你 要 听 我 口 中 的 话 ， 替 我 警 戒 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21289', '26', '33', '8', '我 对 恶 人 说 ： ‘ 恶 人 哪 ， 你 必 要 死 ！ ’ 你 ─ ─ 以 西 结 若 不 开 口 警 戒 恶 人 ， 使 他 离 开 所 行 的 道 ， 这 恶 人 必 死 在 罪 孽 之 中 ， 我 却 要 向 你 讨 他 丧 命 的 罪 ｛ 原 文 是 血 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21290', '26', '33', '9', '倘 若 你 警 戒 恶 人 转 离 所 行 的 道 ， 他 仍 不 转 离 ， 他 必 死 在 罪 孽 之 中 ， 你 却 救 自 己 脱 离 了 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21291', '26', '33', '10', '＜ 个 人 的 责 任 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21292', '26', '33', '11', '你 对 他 们 说 ， 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 我 断 不 喜 悦 恶 人 死 亡 ， 惟 喜 悦 恶 人 转 离 所 行 的 道 而 活 。 以 色 列 家 啊 ， 你 们 转 回 ， 转 回 吧 ！ 离 开 恶 道 ， 何 必 死 亡 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21293', '26', '33', '12', '人 子 啊 ， 你 要 对 本 国 的 人 民 说 ： 义 人 的 义 ， 在 犯 罪 之 日 不 能 救 他 ； 至 于 恶 人 的 恶 ， 在 他 转 离 恶 行 之 日 也 不 能 使 他 倾 倒 ； 义 人 在 犯 罪 之 日 也 不 能 因 他 的 义 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21294', '26', '33', '13', '我 对 义 人 说 ： ‘ 你 必 定 存 活 ！ ’ 他 若 倚 靠 他 的 义 而 作 罪 孽 ， 他 所 行 的 义 都 不 被 记 念 。 他 必 因 所 作 的 罪 孽 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21295', '26', '33', '14', '再 者 ， 我 对 恶 人 说 ： ‘ 你 必 定 死 亡 ！ ’ 他 若 转 离 他 的 罪 ， 行 正 直 与 合 理 的 事 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21296', '26', '33', '15', '还 人 的 当 头 和 所 抢 夺 的 ， 遵 行 生 命 的 律 例 ， 不 作 罪 孽 ， 他 必 定 存 活 ， 不 致 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21297', '26', '33', '16', '他 所 犯 的 一 切 罪 必 不 被 记 念 。 他 行 了 正 直 与 合 理 的 事 ， 必 定 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21298', '26', '33', '17', '“ 你 本 国 的 子 民 还 说 ： ‘ 主 的 道 不 公 平 。 ’ 其 实 他 们 的 道 不 公 平 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21299', '26', '33', '18', '义 人 转 离 他 的 义 而 作 罪 孽 ， 就 必 因 此 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21300', '26', '33', '19', '恶 人 转 离 他 的 恶 ， 行 正 直 与 合 理 的 事 ， 就 必 因 此 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21301', '26', '33', '20', '你 们 还 说 ： ‘ 主 的 道 不 公 平 。 ’ 以 色 列 家 啊 ， 我 必 按 你 们 各 人 所 行 的 审 判 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21302', '26', '33', '21', '＜ 耶 路 撒 冷 陷 落 的 消 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21303', '26', '33', '22', '逃 来 的 人 未 到 前 一 日 的 晚 上 ， 耶 和 华 的 灵 ｛ 原 文 是 手 ｝ 降 在 我 身 上 ， 开 我 的 口 。 到 第 二 日 早 晨 ， 那 人 来 到 我 这 里 ， 我 口 就 开 了 ， 不 再 缄 默 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21304', '26', '33', '23', '＜ 人 民 的 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21305', '26', '33', '24', '“ 人 子 啊 ， 住 在 以 色 列 荒 废 之 地 的 人 说 ： ‘ 亚 伯 拉 罕 独 自 一 人 能 得 这 地 为 业 ， 我 们 人 数 众 多 ， 这 地 更 是 给 我 们 为 业 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21306', '26', '33', '25', '所 以 你 要 对 他 们 说 ， 主 耶 和 华 如 此 说 ： 你 们 吃 带 血 的 物 ， 仰 望 偶 像 ， 并 且 杀 人 流 血 ， 你 们 还 能 得 这 地 为 业 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21307', '26', '33', '26', '你 们 倚 仗 自 己 的 刀 剑 行 可 憎 的 事 ， 人 人 玷 污 邻 舍 的 妻 ， 你 们 还 能 得 这 地 为 业 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21308', '26', '33', '27', '你 要 对 他 们 这 样 说 ， 主 耶 和 华 如 此 说 ： 我 指 着 我 的 永 生 起 誓 ， 在 荒 场 中 的 ， 必 倒 在 刀 下 ； 在 田 野 间 的 ， 必 交 给 野 兽 吞 吃 ； 在 保 障 和 洞 里 的 ， 必 遭 瘟 疫 而 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21309', '26', '33', '28', '我 必 使 这 地 荒 凉 ， 令 人 惊 骇 ； 她 因 势 力 而 有 的 骄 傲 也 必 止 息 。 以 色 列 的 山 都 必 荒 凉 ， 无 人 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21310', '26', '33', '29', '我 因 他 们 所 行 一 切 可 憎 的 事 使 地 荒 凉 ， 令 人 惊 骇 。 那 时 ， 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21311', '26', '33', '30', '＜ 先 知 传 讲 信 息 的 结 果 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21312', '26', '33', '31', '他 们 来 到 你 这 里 如 同 民 来 聚 会 ， 坐 在 你 面 前 仿 佛 是 我 的 民 。 他 们 听 你 的 话 却 不 去 行 ； 因 为 他 们 的 口 多 显 爱 情 ， 心 却 追 随 财 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21313', '26', '33', '32', '他 们 看 你 如 善 于 奏 乐 、 声 音 幽 雅 之 人 所 唱 的 雅 歌 ， 他 们 听 你 的 话 却 不 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21314', '26', '33', '33', '看 哪 ， 所 说 的 快 要 应 验 ； 应 验 了 ， 他 们 就 知 道 在 他 们 中 间 有 了 先 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21315', '26', '34', '1', '＜ 以 色 列 的 牧 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21316', '26', '34', '2', '“ 人 子 啊 ， 你 要 向 以 色 列 的 牧 人 发 预 言 ， 攻 击 他 们 ， 说 ， 主 耶 和 华 如 此 说 ： 祸 哉 ！ 以 色 列 的 牧 人 只 知 牧 养 自 己 。 牧 人 岂 不 当 牧 养 群 羊 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21317', '26', '34', '3', '你 们 吃 脂 油 、 穿 羊 毛 、 宰 肥 壮 的 ， 却 不 牧 养 群 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21318', '26', '34', '4', '瘦 弱 的 ， 你 们 没 有 养 壮 ； 有 病 的 ， 你 们 没 有 医 治 ； 受 伤 的 ， 你 们 没 有 缠 裹 ； 被 逐 的 ， 你 们 没 有 领 回 ； 失 丧 的 ， 你 们 没 有 寻 找 ； 但 用 强 暴 严 严 地 辖 制 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21319', '26', '34', '5', '因 无 牧 人 ， 羊 就 分 散 ； 既 分 散 ， 便 作 了 一 切 野 兽 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21320', '26', '34', '6', '我 的 羊 在 诸 山 间 、 在 各 高 冈 上 流 离 ， 在 全 地 上 分 散 ， 无 人 去 寻 ， 无 人 去 找 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21321', '26', '34', '7', '“ 所 以 ， 你 们 这 些 牧 人 要 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21322', '26', '34', '8', '主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 我 的 羊 因 无 牧 人 就 成 为 掠 物 ， 也 作 了 一 切 野 兽 的 食 物 。 我 的 牧 人 不 寻 找 我 的 羊 ； 这 些 牧 人 只 知 牧 养 自 己 ， 并 不 牧 养 我 的 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21323', '26', '34', '9', '所 以 你 们 这 些 牧 人 要 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21324', '26', '34', '10', '主 耶 和 华 如 此 说 ： 我 必 与 牧 人 为 敌 ， 必 向 他 们 的 手 追 讨 我 的 羊 ， 使 他 们 不 再 牧 放 群 羊 ； 牧 人 也 不 再 牧 养 自 己 。 我 必 救 我 的 羊 脱 离 他 们 的 口 ， 不 再 作 他 们 的 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21325', '26', '34', '11', '＜ 好 牧 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21326', '26', '34', '12', '牧 人 在 羊 群 四 散 的 日 子 怎 样 寻 找 他 的 羊 ， 我 必 照 样 寻 找 我 的 羊 。 这 些 羊 在 密 云 黑 暗 的 日 子 散 到 各 处 ， 我 必 从 那 里 救 回 它 们 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21327', '26', '34', '13', '我 必 从 万 民 中 领 出 它 们 ， 从 各 国 内 聚 集 它 们 ， 引 导 它 们 归 回 故 土 ， 也 必 在 以 色 列 山 上 ─ ─ 一 切 溪 水 旁 边 、 境 内 一 切 可 居 之 处 ─ ─ 牧 养 它 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21328', '26', '34', '14', '我 必 在 美 好 的 草 场 牧 养 它 们 。 它 们 的 圈 必 在 以 色 列 高 处 的 山 上 ， 它 们 必 在 佳 美 之 圈 中 躺 卧 ， 也 在 以 色 列 山 肥 美 的 草 场 吃 草 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21329', '26', '34', '15', '主 耶 和 华 说 ： 我 必 亲 自 作 我 羊 的 牧 人 ， 使 它 们 得 以 躺 卧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21330', '26', '34', '16', '失 丧 的 ， 我 必 寻 找 ； 被 逐 的 ， 我 必 领 回 ； 受 伤 的 ， 我 必 缠 裹 ； 有 病 的 ， 我 必 医 治 ； 只 是 肥 的 壮 的 ， 我 必 除 灭 ， 也 要 秉 公 牧 养 它 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21331', '26', '34', '17', '“ 我 的 羊 群 哪 ， 论 到 你 们 ， 主 耶 和 华 如 此 说 ： 我 必 在 羊 与 羊 中 间 、 公 绵 羊 与 公 山 羊 中 间 施 行 判 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21332', '26', '34', '18', '你 们 这 些 肥 壮 的 羊 ， 在 美 好 的 草 场 吃 草 还 以 为 小 事 吗 ？ 剩 下 的 草 ， 你 们 竟 用 蹄 践 踏 了 ； 你 们 喝 清 水 ， 剩 下 的 水 ， 你 们 竟 用 蹄 搅 浑 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21333', '26', '34', '19', '至 于 我 的 羊 ， 只 得 吃 你 们 所 践 踏 的 ， 喝 你 们 所 搅 浑 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21334', '26', '34', '20', '“ 所 以 ， 主 耶 和 华 如 此 说 ： 我 必 在 肥 羊 和 瘦 羊 中 间 施 行 判 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21335', '26', '34', '21', '因 为 你 们 用 胁 用 肩 拥 挤 一 切 瘦 弱 的 ， 又 用 角 抵 触 ， 以 致 使 它 们 四 散 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21336', '26', '34', '22', '所 以 ， 我 必 拯 救 我 的 群 羊 不 再 作 掠 物 ； 我 也 必 在 羊 和 羊 中 间 施 行 判 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21337', '26', '34', '23', '我 必 立 一 牧 人 照 管 他 们 ， 牧 养 他 们 ， 就 是 我 的 仆 人 大 卫 。 他 必 牧 养 他 们 ， 作 他 们 的 牧 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21338', '26', '34', '24', '我 ─ ─ 耶 和 华 必 作 他 们 的 神 ， 我 的 仆 人 大 卫 必 在 他 们 中 间 作 王 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21339', '26', '34', '25', '“ 我 必 与 他 们 立 平 安 的 约 ， 使 恶 兽 从 境 内 断 绝 ， 他 们 就 必 安 居 在 旷 野 ， 躺 卧 在 林 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21340', '26', '34', '26', '我 必 使 他 们 与 我 山 的 四 围 成 为 福 源 ， 我 也 必 叫 时 雨 落 下 ， 必 有 福 如 甘 霖 而 降 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21341', '26', '34', '27', '田 野 的 树 必 结 果 ， 地 也 必 有 出 产 ； 他 们 必 在 故 土 安 然 居 住 。 我 折 断 他 们 所 负 的 轭 ， 救 他 们 脱 离 那 以 他 们 为 奴 之 人 的 手 ； 那 时 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21342', '26', '34', '28', '他 们 必 不 再 作 外 邦 人 的 掠 物 ， 地 上 的 野 兽 也 不 再 吞 吃 他 们 ； 却 要 安 然 居 住 ， 无 人 惊 吓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21343', '26', '34', '29', '我 必 给 他 们 兴 起 有 名 的 植 物 ； 他 们 在 境 内 不 再 为 饥 荒 所 灭 ， 也 不 再 受 外 邦 人 的 羞 辱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21344', '26', '34', '30', '必 知 道 我 、 耶 和 华 ─ ─ 他 们 的 神 是 与 他 们 同 在 的 ， 并 知 道 他 们 ─ ─ 以 色 列 家 是 我 的 民 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21345', '26', '34', '31', '你 们 作 我 的 羊 ， 我 草 场 上 的 羊 ， 乃 是 以 色 列 人 ， 我 也 是 你 们 的 神 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21346', '26', '35', '1', '＜ 神 惩 罚 以 东 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21347', '26', '35', '2', '“ 人 子 啊 ， 你 要 面 向 西 珥 山 发 预 言 ， 攻 击 它 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21348', '26', '35', '3', '对 它 说 ， 主 耶 和 华 如 此 说 ： 西 珥 山 哪 ， 我 与 你 为 敌 ， 必 向 你 伸 手 攻 击 你 ， 使 你 荒 凉 ， 令 人 惊 骇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21349', '26', '35', '4', '我 必 使 你 的 城 邑 变 为 荒 场 ， 成 为 凄 凉 。 你 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21350', '26', '35', '5', '因 为 你 永 怀 仇 恨 ， 在 以 色 列 人 遭 灾 、 罪 孽 到 了 尽 头 的 时 候 ， 将 他 们 交 与 刀 剑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21351', '26', '35', '6', '所 以 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 我 必 使 你 遭 遇 流 血 的 报 应 ， 罪 ｛ 原 文 是 血 ； 本 节 同 ｝ 必 追 赶 你 ； 你 既 不 恨 恶 杀 人 流 血 ， 所 以 这 罪 必 追 赶 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21352', '26', '35', '7', '我 必 使 西 珥 山 荒 凉 ， 令 人 惊 骇 ， 来 往 经 过 的 人 我 必 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21353', '26', '35', '8', '我 必 使 西 珥 山 满 有 被 杀 的 人 。 被 刀 杀 的 ， 必 倒 在 你 小 山 和 山 谷 ， 并 一 切 的 溪 水 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21354', '26', '35', '9', '我 必 使 你 永 远 荒 凉 ， 使 你 的 城 邑 无 人 居 住 ， 你 的 民 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21355', '26', '35', '10', '“ 因 为 你 曾 说 ： ‘ 这 二 国 这 二 邦 必 归 于 我 ， 我 必 得 为 业 ’ （ 其 实 耶 和 华 仍 在 那 里 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21356', '26', '35', '11', '所 以 主 耶 和 华 说 ： 我 指 着 我 的 永 生 起 誓 ， 我 必 照 你 的 怒 气 和 你 从 仇 恨 中 向 他 们 所 发 的 嫉 妒 待 你 。 我 审 判 你 的 时 候 ， 必 将 自 己 显 明 在 他 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21357', '26', '35', '12', '你 也 必 知 道 我 ─ ─ 耶 和 华 听 见 了 你 的 一 切 毁 谤 ， 就 是 你 攻 击 以 色 列 山 的 话 ， 说 ： ‘ 这 些 山 荒 凉 ， 是 归 我 们 吞 灭 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21358', '26', '35', '13', '你 们 也 用 口 向 我 夸 大 ， 增 添 与 我 反 对 的 话 ， 我 都 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21359', '26', '35', '14', '主 耶 和 华 如 此 说 ： 全 地 欢 乐 的 时 候 ， 我 必 使 你 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21360', '26', '35', '15', '你 怎 样 因 以 色 列 家 的 地 业 荒 凉 而 喜 乐 ， 我 必 照 你 所 行 的 待 你 。 西 珥 山 哪 ， 你 和 以 东 全 地 必 都 荒 凉 。 你 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21361', '26', '36', '1', '＜ 神 赐 福 给 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21362', '26', '36', '2', '主 耶 和 华 如 此 说 ： 因 仇 敌 说 ： ‘ 阿 哈 ！ 这 永 久 的 山 冈 都 归 我 们 为 业 了 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21363', '26', '36', '3', '所 以 要 发 预 言 说 ， 主 耶 和 华 如 此 说 ： 因 为 敌 人 使 你 荒 凉 ， 四 围 吞 吃 ， 好 叫 你 归 与 其 余 的 外 邦 人 为 业 ， 并 且 多 嘴 多 舌 的 人 提 起 你 来 ， 百 姓 也 说 你 有 臭 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21364', '26', '36', '4', '故 此 ， 以 色 列 山 要 听 主 耶 和 华 的 话 。 大 山 小 冈 、 水 沟 山 谷 、 荒 废 之 地 、 被 弃 之 城 ， 为 四 围 其 余 的 外 邦 人 所 占 据 、 所 讥 刺 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21365', '26', '36', '5', '主 耶 和 华 对 你 们 如 此 说 ： 我 真 发 愤 恨 如 火 ， 责 备 那 其 余 的 外 邦 人 和 以 东 的 众 人 。 他 们 快 乐 满 怀 ， 心 存 恨 恶 ， 将 我 的 地 归 自 己 为 业 ， 又 看 为 被 弃 的 掠 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21366', '26', '36', '6', '所 以 ， 你 要 指 着 以 色 列 地 说 预 言 ， 对 大 山 小 冈 、 水 沟 山 谷 说 ， 主 耶 和 华 如 此 说 ： 我 发 愤 恨 和 忿 怒 说 ， 因 你 们 曾 受 外 邦 人 的 羞 辱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21367', '26', '36', '7', '所 以 我 起 誓 说 ： 你 们 四 围 的 外 邦 人 总 要 担 当 自 己 的 羞 辱 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21368', '26', '36', '8', '“ 以 色 列 山 哪 ， 你 必 发 枝 条 ， 为 我 的 民 以 色 列 结 果 子 ， 因 为 他 们 快 要 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21369', '26', '36', '9', '看 哪 ， 我 是 帮 助 你 的 ， 也 必 向 你 转 意 ， 使 你 得 以 耕 种 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21370', '26', '36', '10', '我 必 使 以 色 列 全 家 的 人 数 在 你 上 面 增 多 ， 城 邑 有 人 居 住 ， 荒 场 再 被 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21371', '26', '36', '11', '我 必 使 人 和 牲 畜 在 你 上 面 加 增 ； 他 们 必 生 养 众 多 。 我 要 使 你 照 旧 有 人 居 住 ， 并 要 赐 福 与 你 比 先 前 更 多 ， 你 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21372', '26', '36', '12', '我 必 使 人 ， 就 是 我 的 民 以 色 列 ， 行 在 你 上 面 。 他 们 必 得 你 为 业 ； 你 也 不 再 使 他 们 丧 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21373', '26', '36', '13', '主 耶 和 华 如 此 说 ： 因 为 人 对 你 说 ： ‘ 你 是 吞 吃 人 的 ， 又 使 国 民 丧 子 ’ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21374', '26', '36', '14', '所 以 主 耶 和 华 说 ： 你 必 不 再 吞 吃 人 ， 也 不 再 使 国 民 丧 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21375', '26', '36', '15', '我 使 你 不 再 听 见 各 国 的 羞 辱 ， 不 再 受 万 民 的 辱 骂 ， 也 不 再 使 国 民 绊 跌 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21376', '26', '36', '16', '＜ 以 色 列 的 新 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21377', '26', '36', '17', '“ 人 子 啊 ， 以 色 列 家 住 在 本 地 的 时 候 ， 在 行 动 作 为 上 玷 污 那 地 。 他 们 的 行 为 在 我 面 前 ， 好 像 正 在 经 期 的 妇 人 那 样 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21378', '26', '36', '18', '所 以 我 因 他 们 在 那 地 上 流 人 的 血 ， 又 因 他 们 以 偶 像 玷 污 那 地 ， 就 把 我 的 忿 怒 倾 在 他 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21379', '26', '36', '19', '我 将 他 们 分 散 在 列 国 ， 四 散 在 列 邦 ， 按 他 们 的 行 动 作 为 惩 罚 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21380', '26', '36', '20', '他 们 到 了 所 去 的 列 国 ， 就 使 我 的 圣 名 被 亵 渎 ； 因 为 人 谈 论 他 们 说 ， 这 是 耶 和 华 的 民 ， 是 从 耶 和 华 的 地 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21381', '26', '36', '21', '我 却 顾 惜 我 的 圣 名 ， 就 是 以 色 列 家 在 所 到 的 列 国 中 所 亵 渎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21382', '26', '36', '22', '“ 所 以 ， 你 要 对 以 色 列 家 说 ， 主 耶 和 华 如 此 说 ： 以 色 列 家 啊 ， 我 行 这 事 不 是 为 你 们 ， 乃 是 为 我 的 圣 名 ， 就 是 在 你 们 到 的 列 国 中 所 亵 渎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21383', '26', '36', '23', '我 要 使 我 的 大 名 显 为 圣 ； 这 名 在 列 国 中 已 被 亵 渎 ， 就 是 你 们 在 他 们 中 间 所 亵 渎 的 。 我 在 他 们 眼 前 ， 在 你 们 身 上 显 为 圣 的 时 候 ， 他 们 就 知 道 我 是 耶 和 华 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21384', '26', '36', '24', '我 必 从 各 国 收 取 你 们 ， 从 列 邦 聚 集 你 们 ， 引 导 你 们 归 回 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21385', '26', '36', '25', '我 必 用 清 水 洒 在 你 们 身 上 ， 你 们 就 洁 净 了 。 我 要 洁 净 你 们 ， 使 你 们 脱 离 一 切 的 污 秽 ， 弃 掉 一 切 的 偶 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21386', '26', '36', '26', '我 也 要 赐 给 你 们 一 个 新 心 ， 将 新 灵 放 在 你 们 里 面 ， 又 从 你 们 的 肉 体 中 除 掉 石 心 ， 赐 给 你 们 肉 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21387', '26', '36', '27', '我 必 将 我 的 灵 放 在 你 们 里 面 ， 使 你 们 顺 从 我 的 律 例 ， 谨 守 遵 行 我 的 典 章 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21388', '26', '36', '28', '你 们 必 住 在 我 所 赐 给 你 们 列 祖 之 地 。 你 们 要 作 我 的 子 民 ， 我 要 作 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21389', '26', '36', '29', '我 必 救 你 们 脱 离 一 切 的 污 秽 ， 也 必 命 五 谷 丰 登 ， 不 使 你 们 遭 遇 饥 荒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21390', '26', '36', '30', '我 必 使 树 木 多 结 果 子 ， 田 地 多 出 土 产 ， 好 叫 你 们 不 再 因 饥 荒 受 外 邦 人 的 讥 诮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21391', '26', '36', '31', '那 时 ， 你 们 必 追 想 你 们 的 恶 行 和 你 们 不 善 的 作 为 ， 就 因 你 们 的 罪 孽 和 可 憎 的 事 厌 恶 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21392', '26', '36', '32', '主 耶 和 华 说 ： 你 们 要 知 道 ， 我 这 样 行 不 是 为 你 们 。 以 色 列 家 啊 ， 当 为 自 己 的 行 为 抱 愧 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21393', '26', '36', '33', '“ 主 耶 和 华 如 此 说 ： 我 洁 净 你 们 ， 使 你 们 脱 离 一 切 罪 孽 的 日 子 ， 必 使 城 邑 有 人 居 住 ， 荒 场 再 被 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21394', '26', '36', '34', '过 路 的 人 虽 看 为 荒 废 之 地 ， 现 今 这 荒 废 之 地 仍 得 耕 种 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21395', '26', '36', '35', '他 们 必 说 ： ‘ 这 先 前 为 荒 废 之 地 ， 现 在 成 如 伊 甸 园 ； 这 荒 废 凄 凉 、 毁 坏 的 城 邑 现 在 坚 固 有 人 居 住 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21396', '26', '36', '36', '那 时 ， 在 你 们 四 围 其 余 的 外 邦 人 必 知 道 我 ─ ─ 耶 和 华 修 造 那 毁 坏 之 处 ， 培 植 那 荒 废 之 地 。 我 ─ ─ 耶 和 华 说 过 ， 也 必 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21397', '26', '36', '37', '“ 主 耶 和 华 如 此 说 ： 我 要 加 增 以 色 列 家 的 人 数 ， 多 如 羊 群 。 他 们 必 为 这 事 向 我 求 问 ， 我 要 给 他 们 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21398', '26', '36', '38', '耶 路 撒 冷 在 守 节 作 祭 物 所 献 的 羊 群 怎 样 多 ， 照 样 ， 荒 凉 的 城 邑 必 被 人 群 充 满 。 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21399', '26', '37', '1', '＜ 枯 骨 的 复 苏 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21400', '26', '37', '2', '他 使 我 从 骸 骨 的 四 围 经 过 ， 谁 知 在 平 原 的 骸 骨 甚 多 ， 而 且 极 其 枯 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21401', '26', '37', '3', '他 对 我 说 ： “ 人 子 啊 ， 这 些 骸 骨 能 复 活 吗 ？ ” 我 说 ： “ 主 耶 和 华 啊 ， 你 是 知 道 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21402', '26', '37', '4', '他 又 对 我 说 ： “ 你 向 这 些 骸 骨 发 预 言 说 ： 枯 干 的 骸 骨 啊 ， 要 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21403', '26', '37', '5', '主 耶 和 华 对 这 些 骸 骨 如 此 说 ： ‘ 我 必 使 气 息 进 入 你 们 里 面 ， 你 们 就 要 活 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21404', '26', '37', '6', '我 必 给 你 们 加 上 筋 ， 使 你 们 长 肉 ， 又 将 皮 遮 蔽 你 们 ， 使 气 息 进 入 你 们 里 面 ， 你 们 就 要 活 了 ； 你 们 便 知 道 我 是 耶 和 华 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21405', '26', '37', '7', '于 是 ， 我 遵 命 说 预 言 。 正 说 预 言 的 时 候 ， 不 料 ， 有 响 声 ， 有 地 震 ； 骨 与 骨 互 相 联 络 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21406', '26', '37', '8', '我 观 看 ， 见 骸 骨 上 有 筋 ， 也 长 了 肉 ， 又 有 皮 遮 蔽 其 上 ， 只 是 还 没 有 气 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21407', '26', '37', '9', '主 对 我 说 ： “ 人 子 啊 ， 你 要 发 预 言 ， 向 风 发 预 言 ， 说 主 耶 和 华 如 此 说 ： 气 息 啊 ， 要 从 四 方 ｛ 原 文 是 风 ｝ 而 来 ， 吹 在 这 些 被 杀 的 人 身 上 ， 使 他 们 活 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21408', '26', '37', '10', '于 是 我 遵 命 说 预 言 ， 气 息 就 进 入 骸 骨 ， 骸 骨 便 活 了 ， 并 且 站 起 来 ， 成 为 极 大 的 军 队 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21409', '26', '37', '11', '主 对 我 说 ： “ 人 子 啊 ， 这 些 骸 骨 就 是 以 色 列 全 家 。 他 们 说 ： ‘ 我 们 的 骨 头 枯 干 了 ， 我 们 的 指 望 失 去 了 ， 我 们 灭 绝 净 尽 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21410', '26', '37', '12', '所 以 你 要 发 预 言 对 他 们 说 ， 主 耶 和 华 如 此 说 ： ‘ 我 的 民 哪 ， 我 必 开 你 们 的 坟 墓 ， 使 你 们 从 坟 墓 中 出 来 ， 领 你 们 进 入 以 色 列 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21411', '26', '37', '13', '我 的 民 哪 ， 我 开 你 们 的 坟 墓 ， 使 你 们 从 坟 墓 中 出 来 ， 你 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21412', '26', '37', '14', '我 必 将 我 的 灵 放 在 你 们 里 面 ， 你 们 就 要 活 了 。 我 将 你 们 安 置 在 本 地 ， 你 们 就 知 道 我 ─ ─ 耶 和 华 如 此 说 ， 也 如 此 成 就 了 。 这 是 耶 和 华 说 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21413', '26', '37', '15', '＜ 犹 大 和 以 色 列 组 成 联 合 王 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21414', '26', '37', '16', '“ 人 子 啊 ， 你 要 取 一 根 木 杖 ， 在 其 上 写 ‘ 为 犹 大 和 他 的 同 伴 以 色 列 人 ’ ； 又 取 一 根 木 杖 ， 在 其 上 写 ‘ 为 约 瑟 ， 就 是 为 以 法 莲 ， 又 为 他 的 同 伴 以 色 列 全 家 ’ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21415', '26', '37', '17', '你 要 使 这 两 根 木 杖 接 连 为 一 ， 在 你 手 中 成 为 一 根 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21416', '26', '37', '18', '你 本 国 的 子 民 问 你 说 ： ‘ 这 是 什 么 意 思 ？ 你 不 指 示 我 们 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21417', '26', '37', '19', '你 就 对 他 们 说 ： ‘ 主 耶 和 华 如 此 说 ： 我 要 将 约 瑟 和 他 同 伴 以 色 列 支 派 的 杖 ， 就 是 那 在 以 法 莲 手 中 的 ， 与 犹 大 的 杖 一 同 接 连 为 一 ， 在 我 手 中 成 为 一 根 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21418', '26', '37', '20', '你 所 写 的 那 两 根 杖 要 在 他 们 眼 前 拿 在 手 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21419', '26', '37', '21', '要 对 他 们 说 ， 主 耶 和 华 如 此 说 ： 我 要 将 以 色 列 人 从 他 们 所 到 的 各 国 收 取 ， 又 从 四 围 聚 集 他 们 ， 引 导 他 们 归 回 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21420', '26', '37', '22', '我 要 使 他 们 在 那 地 ， 在 以 色 列 山 上 成 为 一 国 ， 有 一 王 作 他 们 众 民 的 王 。 他 们 不 再 为 二 国 ， 决 不 再 分 为 二 国 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21421', '26', '37', '23', '也 不 再 因 偶 像 和 可 憎 的 物 ， 并 一 切 的 罪 过 玷 污 自 己 。 我 却 要 救 他 们 出 离 一 切 的 住 处 ， 就 是 他 们 犯 罪 的 地 方 ； 我 要 洁 净 他 们 ， 如 此 ， 他 们 要 作 我 的 子 民 ， 我 要 作 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21422', '26', '37', '24', '“ 我 的 仆 人 大 卫 必 作 他 们 的 王 ； 众 民 必 归 一 个 牧 人 。 他 们 必 顺 从 我 的 典 章 ， 谨 守 遵 行 我 的 律 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21423', '26', '37', '25', '他 们 必 住 在 我 赐 给 我 仆 人 雅 各 的 地 上 ， 就 是 你 们 列 祖 所 住 之 地 。 他 们 和 他 们 的 子 孙 ， 并 子 孙 的 子 孙 ， 都 永 远 住 在 那 里 。 我 的 仆 人 大 卫 必 作 他 们 的 王 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21424', '26', '37', '26', '并 且 我 要 与 他 们 立 平 安 的 约 ， 作 为 永 约 。 我 也 要 将 他 们 安 置 在 本 地 ， 使 他 们 的 人 数 增 多 ， 又 在 他 们 中 间 设 立 我 的 圣 所 ， 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21425', '26', '37', '27', '我 的 居 所 必 在 他 们 中 间 ； 我 要 作 他 们 的 神 ， 他 们 要 作 我 的 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21426', '26', '37', '28', '我 的 圣 所 在 以 色 列 人 中 间 直 到 永 远 ， 外 邦 人 就 必 知 道 我 是 叫 以 色 列 成 为 圣 的 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21427', '26', '38', '1', '＜ 歌 革 ─ ─ 耶 和 华 的 工 具 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21428', '26', '38', '2', '“ 人 子 啊 ， 你 要 面 向 玛 各 地 的 歌 革 ， 就 是 罗 施 、 米 设 、 土 巴 的 王 发 预 言 攻 击 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21429', '26', '38', '3', '说 主 耶 和 华 如 此 说 ： 罗 施 、 米 设 、 土 巴 的 王 歌 革 啊 ， 我 与 你 为 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21430', '26', '38', '4', '我 必 用 钩 子 钩 住 你 的 腮 颊 ， 调 转 你 ， 将 你 和 你 的 军 兵 、 马 匹 、 马 兵 带 出 来 ， 都 披 挂 整 齐 ， 成 了 大 队 ， 有 大 小 盾 牌 ， 各 拿 刀 剑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21431', '26', '38', '5', '波 斯 人 、 古 实 人 ， 和 弗 人 ｛ 又 作 利 比 亚 人 ｝ ， 各 拿 盾 牌 ， 头 上 戴 盔 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21432', '26', '38', '6', '歌 篾 人 和 他 的 军 队 ， 北 方 极 处 的 陀 迦 玛 族 和 他 的 军 队 ， 这 许 多 国 的 民 都 同 着 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21433', '26', '38', '7', '“ 那 聚 集 到 你 这 里 的 各 队 都 当 准 备 ； 你 自 己 也 要 准 备 ， 作 他 们 的 大 帅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21434', '26', '38', '8', '过 了 多 日 ， 你 必 被 差 派 。 到 末 后 之 年 ， 你 必 来 到 脱 离 刀 剑 从 列 国 收 回 之 地 ， 到 以 色 列 常 久 荒 凉 的 山 上 ； 但 那 从 列 国 中 招 聚 出 来 的 必 在 其 上 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21435', '26', '38', '9', '你 和 你 的 军 队 ， 并 同 着 你 许 多 国 的 民 ， 必 如 暴 风 上 来 ， 如 密 云 遮 盖 地 面 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21436', '26', '38', '10', '主 耶 和 华 如 此 说 ： “ 到 那 时 ， 你 心 必 起 意 念 ， 图 谋 恶 计 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21437', '26', '38', '11', '说 ： ‘ 我 要 上 那 无 城 墙 的 乡 村 ， 我 要 到 那 安 静 的 民 那 里 ， 他 们 都 没 有 城 墙 ， 无 门 、 无 闩 ， 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21438', '26', '38', '12', '我 去 要 抢 财 为 掳 物 ， 夺 货 为 掠 物 ， 反 手 攻 击 那 从 前 荒 凉 、 现 在 有 人 居 住 之 地 ， 又 攻 击 那 住 世 界 中 间 、 从 列 国 招 聚 、 得 了 牲 畜 财 货 的 民 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21439', '26', '38', '13', '示 巴 人 、 底 但 人 、 他 施 的 客 商 ， 和 其 间 的 少 壮 狮 子 都 必 问 你 说 ： ‘ 你 来 要 抢 财 为 掳 物 吗 ？ 你 聚 集 军 队 要 夺 货 为 掠 物 吗 ？ 要 夺 取 金 银 ， 掳 去 牲 畜 、 财 货 吗 ？ 要 抢 夺 许 多 财 宝 为 掳 物 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21440', '26', '38', '14', '“ 人 子 啊 ， 你 要 因 此 发 预 言 ， 对 歌 革 说 ， 主 耶 和 华 如 此 说 ： 到 我 民 以 色 列 安 然 居 住 之 日 ， 你 岂 不 知 道 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21441', '26', '38', '15', '你 必 从 本 地 ， 从 北 方 的 极 处 率 领 许 多 国 的 民 来 ， 都 骑 着 马 ， 乃 一 大 队 极 多 的 军 兵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21442', '26', '38', '16', '歌 革 啊 ， 你 必 上 来 攻 击 我 的 民 以 色 列 ， 如 密 云 遮 盖 地 面 。 末 后 的 日 子 ， 我 必 带 你 来 攻 击 我 的 地 ， 到 我 在 外 邦 人 眼 前 ， 在 你 身 上 显 为 圣 的 时 候 ， 好 叫 他 们 认 识 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21443', '26', '38', '17', '主 耶 和 华 如 此 说 ： 我 在 古 时 藉 我 的 仆 人 以 色 列 的 先 知 所 说 的 ， 就 是 你 吗 ？ 当 日 他 们 多 年 预 言 我 必 带 你 来 攻 击 以 色 列 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21444', '26', '38', '18', '＜ 神 惩 罚 歌 革 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21445', '26', '38', '19', '我 发 愤 恨 和 烈 怒 如 火 说 ： 那 日 在 以 色 列 地 必 有 大 震 动 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21446', '26', '38', '20', '甚 至 海 中 的 鱼 、 天 空 的 鸟 、 田 野 的 兽 ， 并 地 上 的 一 切 昆 虫 ， 和 其 上 的 众 人 ， 因 见 我 的 面 就 都 震 动 ； 山 岭 必 崩 裂 ， 陡 岩 必 塌 陷 ， 墙 垣 都 必 坍 倒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21447', '26', '38', '21', '主 耶 和 华 说 ： “ 我 必 命 我 的 诸 山 发 刀 剑 来 攻 击 歌 革 ； 人 都 要 用 刀 剑 杀 害 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21448', '26', '38', '22', '我 必 用 瘟 疫 和 流 血 的 事 刑 罚 他 。 我 也 必 将 暴 雨 、 大 雹 与 火 ， 并 硫 磺 降 与 他 和 他 的 军 队 ， 并 他 所 率 领 的 众 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21449', '26', '38', '23', '我 必 显 为 大 ， 显 为 圣 ， 在 多 国 人 的 眼 前 显 现 ； 他 们 就 知 道 我 是 耶 和 华 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21450', '26', '39', '1', '＜ 歌 革 被 击 败 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21451', '26', '39', '2', '我 必 调 转 你 ， 领 你 前 往 ， 使 你 从 北 方 的 极 处 上 来 ， 带 你 到 以 色 列 的 山 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21452', '26', '39', '3', '我 必 从 你 左 手 打 落 你 的 弓 ， 从 你 右 手 打 掉 你 的 箭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21453', '26', '39', '4', '你 和 你 的 军 队 ， 并 同 着 你 的 列 国 人 ， 都 必 倒 在 以 色 列 的 山 上 。 我 必 将 你 给 各 类 的 鸷 鸟 和 田 野 的 走 兽 作 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21454', '26', '39', '5', '你 必 倒 在 田 野 ， 因 为 我 曾 说 过 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21455', '26', '39', '6', '我 要 降 火 在 玛 各 和 海 岛 安 然 居 住 的 人 身 上 ， 他 们 就 知 道 我 是 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21456', '26', '39', '7', '“ 我 要 在 我 民 以 色 列 中 显 出 我 的 圣 名 ， 也 不 容 我 的 圣 名 再 被 亵 渎 ， 列 国 人 就 知 道 我 是 耶 和 华 ─ ─ 以 色 列 中 的 圣 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21457', '26', '39', '8', '主 耶 和 华 说 ： 这 日 事 情 临 近 ， 也 必 成 就 ， 乃 是 我 所 说 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21458', '26', '39', '9', '“ 住 以 色 列 城 邑 的 人 必 出 去 捡 器 械 ， 就 是 大 小 盾 牌 、 弓 箭 、 梃 杖 、 枪 矛 ， 都 当 柴 烧 火 ， 直 烧 七 年 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21459', '26', '39', '10', '甚 至 他 们 不 必 从 田 野 捡 柴 ， 也 不 必 从 树 林 伐 木 ； 因 为 他 们 要 用 器 械 烧 火 ， 并 且 抢 夺 那 抢 夺 他 们 的 人 ， 掳 掠 那 掳 掠 他 们 的 人 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21460', '26', '39', '11', '＜ 歌 革 的 埋 葬 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21461', '26', '39', '12', '以 色 列 家 的 人 必 用 七 个 月 葬 埋 他 们 ， 为 要 洁 净 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21462', '26', '39', '13', '全 地 的 居 民 都 必 葬 埋 他 们 。 当 我 得 荣 耀 的 日 子 ， 这 事 必 叫 他 们 得 名 声 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21463', '26', '39', '14', '他 们 必 分 派 人 时 常 巡 查 遍 地 ， 与 过 路 的 人 一 同 葬 埋 那 剩 在 地 面 上 的 尸 首 ， 好 洁 净 全 地 。 过 了 七 个 月 ， 他 们 还 要 巡 查 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21464', '26', '39', '15', '巡 查 遍 地 的 人 要 经 过 全 地 ， 见 有 人 的 骸 骨 ， 就 在 旁 边 立 一 标 记 ， 等 葬 埋 的 人 来 将 骸 骨 葬 在 哈 们 ． 歌 革 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21465', '26', '39', '16', '他 们 必 这 样 洁 净 那 地 ， 并 有 一 城 名 叫 哈 摩 那 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21466', '26', '39', '17', '“ 人 子 啊 ， 主 耶 和 华 如 此 说 ： 你 要 对 各 类 的 飞 鸟 和 田 野 的 走 兽 说 ： 你 们 聚 集 来 吧 ， 要 从 四 方 聚 到 我 为 你 们 献 祭 之 地 ， 就 是 在 以 色 列 山 上 献 大 祭 之 地 ， 好 叫 你 们 吃 肉 、 喝 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21467', '26', '39', '18', '你 们 必 吃 勇 士 的 肉 ， 喝 地 上 首 领 的 血 ， 就 如 吃 公 绵 羊 、 羊 羔 、 公 山 羊 、 公 牛 ， 都 是 巴 珊 的 肥 畜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21468', '26', '39', '19', '你 们 吃 我 为 你 们 所 献 的 祭 ， 必 吃 饱 了 脂 油 ， 喝 醉 了 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21469', '26', '39', '20', '你 们 必 在 我 席 上 饱 吃 马 匹 和 坐 车 的 人 ， 并 勇 士 和 一 切 的 战 士 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21470', '26', '39', '21', '＜ 以 色 列 的 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21471', '26', '39', '22', '这 样 ， 从 那 日 以 后 ， 以 色 列 家 必 知 道 我 是 耶 和 华 ─ ─ 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21472', '26', '39', '23', '列 国 人 也 必 知 道 以 色 列 家 被 掳 掠 是 因 他 们 的 罪 孽 。 他 们 得 罪 我 ， 我 就 掩 面 不 顾 ， 将 他 们 交 在 敌 人 手 中 ， 他 们 便 都 倒 在 刀 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21473', '26', '39', '24', '我 是 照 他 们 的 污 秽 和 罪 过 待 他 们 ， 并 且 我 掩 面 不 顾 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21474', '26', '39', '25', '主 耶 和 华 如 此 说 ： “ 我 要 使 雅 各 被 掳 的 人 归 回 ， 要 怜 悯 以 色 列 全 家 ， 又 为 我 的 圣 名 发 热 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21475', '26', '39', '26', '他 们 在 本 地 安 然 居 住 ， 无 人 惊 吓 ， 是 我 将 他 们 从 万 民 中 领 回 ， 从 仇 敌 之 地 召 来 。 我 在 许 多 国 的 民 眼 前 ， 在 他 们 身 上 显 为 圣 的 时 候 ， 他 们 要 担 当 自 己 的 羞 辱 和 干 犯 我 的 一 切 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21476', '26', '39', '27', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21477', '26', '39', '28', '因 我 使 他 们 被 掳 到 外 邦 人 中 ， 后 又 聚 集 他 们 归 回 本 地 ， 他 们 就 知 道 我 是 耶 和 华 ─ ─ 他 们 的 神 ； 我 必 不 再 留 他 们 一 人 在 外 邦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21478', '26', '39', '29', '我 也 不 再 掩 面 不 顾 他 们 ， 因 我 已 将 我 的 灵 浇 灌 以 色 列 家 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21479', '26', '40', '1', '＜ 新 圣 殿 的 异 象 （ 结   4 0 : 1 - 4 8 : 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21480', '26', '40', '2', '在 神 的 异 象 中 带 我 到 以 色 列 地 ， 安 置 在 至 高 的 山 上 ； 在 山 上 的 南 边 有 仿 佛 一 座 城 建 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21481', '26', '40', '3', '他 带 我 到 那 里 ， 见 有 一 人 ， 颜 色 ｛ 原 文 是 形 状 ｝ 如 铜 ， 手 拿 麻 绳 和 量 度 的 竿 ， 站 在 门 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21482', '26', '40', '4', '那 人 对 我 说 ： “ 人 子 啊 ， 凡 我 所 指 示 你 的 ， 你 都 要 用 眼 看 ， 用 耳 听 ， 并 要 放 在 心 上 。 我 带 你 到 这 里 来 ， 特 为 要 指 示 你 ； 凡 你 所 见 的 ， 你 都 要 告 诉 以 色 列 家 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21483', '26', '40', '5', '＜ 东 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21484', '26', '40', '6', '他 到 了 朝 东 的 门 ， 就 上 门 的 台 阶 ， 量 门 的 这 槛 ， 宽 一 竿 ； 又 量 门 的 那 槛 ， 宽 一 竿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21485', '26', '40', '7', '又 有 卫 房 ， 每 房 长 一 竿 ， 宽 一 竿 ， 相 隔 五 肘 。 门 槛 ， 就 是 挨 着 向 殿 的 廊 门 槛 ， 宽 一 竿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21486', '26', '40', '8', '他 又 量 向 殿 门 的 廊 子 ， 宽 一 竿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21487', '26', '40', '9', '又 量 门 廊 ， 宽 八 肘 ， 墙 柱 厚 二 肘 ； 那 门 的 廊 子 向 着 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21488', '26', '40', '10', '东 门 洞 有 卫 房 ： 这 旁 三 间 ， 那 旁 三 间 ， 都 是 一 样 的 尺 寸 ； 这 边 的 柱 子 和 那 边 的 柱 子 ， 也 是 一 样 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21489', '26', '40', '11', '他 量 门 口 ， 宽 十 肘 ， 长 十 三 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21490', '26', '40', '12', '卫 房 前 展 出 的 境 界 ： 这 边 一 肘 ， 那 边 一 肘 ； 卫 房 这 边 六 肘 ， 那 边 六 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21491', '26', '40', '13', '又 量 门 洞 ， 从 这 卫 房 顶 的 后 檐 到 那 卫 房 顶 的 后 檐 ， 宽 二 十 五 肘 ； 卫 房 门 与 门 相 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21492', '26', '40', '14', '又 量 ｛ 原 文 是 造 ｝ 廊 子 六 十 肘 ｛ 七 十 士 译 本 是 二 十 肘 ｝ ， 墙 柱 外 是 院 子 ， 有 廊 为 界 ， 在 门 洞 两 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21493', '26', '40', '15', '从 大 门 口 到 内 廊 前 ， 共 五 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21494', '26', '40', '16', '卫 房 和 门 洞 两 旁 柱 间 并 廊 子 ， 都 有 严 紧 的 窗 棂 ； 里 边 都 有 窗 棂 ， 柱 上 有 雕 刻 的 棕 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21495', '26', '40', '17', '＜ 外 院 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21496', '26', '40', '18', '铺 石 地 ， 就 是 矮 铺 石 地 在 各 门 洞 两 旁 ， 以 门 洞 的 长 短 为 度 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21497', '26', '40', '19', '他 从 下 门 量 到 内 院 外 ， 共 宽 一 百 肘 ， 东 面 北 面 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21498', '26', '40', '20', '＜ 北 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21499', '26', '40', '21', '门 洞 的 卫 房 ， 这 旁 三 间 ， 那 旁 三 间 。 门 洞 的 柱 子 和 廊 子 ， 与 第 一 门 的 尺 寸 一 样 。 门 洞 长 五 十 肘 ， 宽 二 十 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21500', '26', '40', '22', '其 窗 棂 和 廊 子 ， 并 雕 刻 的 棕 树 ， 与 朝 东 的 门 尺 寸 一 样 。 登 七 层 台 阶 上 到 这 门 ， 前 面 有 廊 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21501', '26', '40', '23', '内 院 有 门 与 这 门 相 对 ， 北 面 东 面 都 是 如 此 。 他 从 这 门 量 到 那 门 ， 共 一 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21502', '26', '40', '24', '＜ 南 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21503', '26', '40', '25', '门 洞 两 旁 与 廊 子 的 周 围 都 有 窗 棂 ， 和 先 量 的 窗 棂 一 样 。 门 洞 长 五 十 肘 ， 宽 二 十 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21504', '26', '40', '26', '登 七 层 台 阶 上 到 这 门 ， 前 面 有 廊 子 ； 柱 上 有 雕 刻 的 棕 树 ， 这 边 一 棵 ， 那 边 一 棵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21505', '26', '40', '27', '内 院 朝 南 有 门 。 从 这 门 量 到 朝 南 的 那 门 ， 共 一 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21506', '26', '40', '28', '＜ 内 院 的 南 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21507', '26', '40', '29', '卫 房 和 柱 子 ， 并 廊 子 都 照 先 前 的 尺 寸 。 门 洞 两 旁 与 廊 子 的 周 围 都 有 窗 棂 。 门 洞 长 五 十 肘 ， 宽 二 十 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21508', '26', '40', '30', '周 围 有 廊 子 ， 长 二 十 五 肘 ， 宽 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21509', '26', '40', '31', '廊 子 朝 着 外 院 ， 柱 上 有 雕 刻 的 棕 树 。 登 八 层 台 阶 上 到 这 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21510', '26', '40', '32', '＜ 内 院 的 东 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21511', '26', '40', '33', '卫 房 和 柱 子 ， 并 廊 子 都 照 先 前 的 尺 寸 。 门 洞 两 旁 与 廊 子 的 周 围 都 有 窗 棂 。 门 洞 长 五 十 肘 ， 宽 二 十 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21512', '26', '40', '34', '廊 子 朝 着 外 院 。 门 洞 两 旁 的 柱 子 都 有 雕 刻 的 棕 树 。 登 八 层 台 阶 上 到 这 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21513', '26', '40', '35', '＜ 内 院 的 北 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21514', '26', '40', '36', '就 是 量 卫 房 和 柱 子 ， 并 廊 子 。 门 洞 周 围 都 有 窗 棂 ； 门 洞 长 五 十 肘 ， 宽 二 十 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21515', '26', '40', '37', '廊 柱 朝 着 外 院 。 门 洞 两 旁 的 柱 子 都 有 雕 刻 的 棕 树 。 登 八 层 台 阶 上 到 这 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21516', '26', '40', '38', '＜ 厢 房 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21517', '26', '40', '39', '在 门 廊 内 ， 这 边 有 两 张 桌 子 ， 那 边 有 两 张 桌 子 ， 在 其 上 可 以 宰 杀 燔 祭 牲 、 赎 罪 祭 牲 ， 和 赎 愆 祭 牲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21518', '26', '40', '40', '上 到 朝 北 的 门 口 ， 这 边 有 两 张 桌 子 ， 门 廊 那 边 也 有 两 张 桌 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21519', '26', '40', '41', '门 这 边 有 四 张 桌 子 ， 那 边 有 四 张 桌 子 ， 共 八 张 ； 在 其 上 祭 司 宰 杀 牺 牲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21520', '26', '40', '42', '为 燔 祭 牲 有 四 张 桌 子 ， 是 凿 过 的 石 头 做 成 的 ， 长 一 肘 半 ， 宽 一 肘 半 ， 高 一 肘 。 祭 司 将 宰 杀 燔 祭 牲 和 平 安 祭 牲 所 用 的 器 皿 放 在 其 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21521', '26', '40', '43', '有 钩 子 ， 宽 一 掌 ， 钉 在 廊 内 的 四 围 。 桌 子 上 有 牺 牲 的 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21522', '26', '40', '44', '在 北 门 旁 ， 内 院 里 有 屋 子 ， 为 歌 唱 的 人 而 设 。 这 屋 子 朝 南 ｛ 南 ： 原 文 是 东 ｝ ； 在 南 门 旁 ， 又 有 一 间 朝 北 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21523', '26', '40', '45', '他 对 我 说 ： “ 这 朝 南 的 屋 子 是 为 看 守 殿 宇 的 祭 司 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21524', '26', '40', '46', '那 朝 北 的 屋 子 是 为 看 守 祭 坛 的 祭 司 。 这 些 祭 司 是 利 未 人 中 撒 督 的 子 孙 ， 近 前 来 事 奉 耶 和 华 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21525', '26', '40', '47', '＜ 内 院 和 圣 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21526', '26', '40', '48', '于 是 他 带 我 到 殿 前 的 廊 子 ， 量 廊 子 的 墙 柱 。 这 面 厚 五 肘 ， 那 面 厚 五 肘 。 门 两 旁 ， 这 边 三 肘 ， 那 边 三 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21527', '26', '40', '49', '廊 子 长 二 十 肘 ， 宽 十 一 肘 。 上 廊 子 有 台 阶 。 靠 近 墙 柱 又 有 柱 子 ， 这 边 一 根 ， 那 边 一 根 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21528', '26', '41', '1', '他 带 我 到 殿 那 里 量 墙 柱 ： 这 面 厚 六 肘 ， 那 面 厚 六 肘 ， 宽 窄 与 会 幕 相 同 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21529', '26', '41', '2', '门 口 宽 十 肘 。 门 两 旁 ， 这 边 五 肘 ， 那 边 五 肘 。 他 量 殿 长 四 十 肘 ， 宽 二 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21530', '26', '41', '3', '他 到 内 殿 量 墙 柱 ， 各 厚 二 肘 。 门 口 宽 六 肘 ， 门 两 旁 各 宽 七 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21531', '26', '41', '4', '他 量 内 殿 ， 长 二 十 肘 ， 宽 二 十 肘 。 他 对 我 说 ： “ 这 是 至 圣 所 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21532', '26', '41', '5', '＜ 靠 圣 殿 墙 边 的 厢 房 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21533', '26', '41', '6', '旁 屋 有 三 层 ， 层 叠 而 上 ， 每 层 排 列 三 十 间 。 旁 屋 的 梁 木 搁 在 殿 墙 坎 上 ， 免 得 插 入 殿 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21534', '26', '41', '7', '这 围 殿 的 旁 屋 越 高 越 宽 ； 因 旁 屋 围 殿 悬 叠 而 上 ， 所 以 越 上 越 宽 ， 从 下 一 层 ， 由 中 一 层 ， 到 上 一 层 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21535', '26', '41', '8', '我 又 见 围 着 殿 有 高 月 台 。 旁 屋 的 根 基 ， 高 足 一 竿 ， 就 是 六 大 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21536', '26', '41', '9', '旁 屋 的 外 墙 厚 五 肘 。 旁 屋 之 外 还 有 余 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21537', '26', '41', '10', '在 旁 屋 与 对 面 的 房 屋 中 间 有 空 地 ， 宽 二 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21538', '26', '41', '11', '旁 屋 的 门 都 向 余 地 ： 一 门 向 北 ， 一 门 向 南 。 周 围 的 余 地 宽 五 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21539', '26', '41', '12', '＜ 西 边 的 屋 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21540', '26', '41', '13', '＜ 圣 殿 的 尺 寸 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21541', '26', '41', '14', '殿 的 前 面 和 两 旁 的 空 地 ， 宽 一 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21542', '26', '41', '15', '他 量 空 地 后 面 的 那 房 子 ， 并 两 旁 的 楼 廊 ， 共 长 一 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21543', '26', '41', '16', '＜ 圣 殿 的 内 部 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21544', '26', '41', '17', '直 到 门 以 上 ， 就 是 到 内 殿 和 外 殿 内 外 四 围 墙 壁 ， 都 按 尺 寸 用 木 板 遮 蔽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21545', '26', '41', '18', '墙 上 雕 刻 基 路 伯 和 棕 树 。 每 二 基 路 伯 中 间 有 一 棵 棕 树 ， 每 基 路 伯 有 二 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21546', '26', '41', '19', '这 边 有 人 脸 向 着 棕 树 ， 那 边 有 狮 子 脸 向 着 棕 树 ， 殿 内 周 围 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21547', '26', '41', '20', '从 地 至 门 以 上 ， 都 有 基 路 伯 和 棕 树 。 殿 墙 就 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21548', '26', '41', '21', '殿 的 门 柱 是 方 的 。 至 圣 所 的 前 面 ， 形 状 和 殿 的 形 状 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21549', '26', '41', '22', '坛 是 木 头 作 的 ， 高 三 肘 ， 长 二 肘 。 坛 角 和 坛 面 ， 并 四 旁 ， 都 是 木 头 做 的 。 他 对 我 说 ： “ 这 是 耶 和 华 面 前 的 桌 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21550', '26', '41', '23', '＜ 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21551', '26', '41', '24', '每 扇 分 两 扇 ， 这 两 扇 是 摺 叠 的 。 这 边 门 分 两 扇 ， 那 边 门 也 分 两 扇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21552', '26', '41', '25', '殿 的 门 扇 上 雕 刻 基 路 伯 和 棕 树 ， 与 刻 在 墙 上 的 一 般 。 在 外 头 廊 前 有 木 槛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21553', '26', '41', '26', '廊 这 边 那 边 都 有 严 紧 的 窗 棂 和 棕 树 ； 殿 的 旁 屋 和 槛 就 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21554', '26', '42', '1', '＜ 圣 殿 附 近 的 两 座 屋 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21555', '26', '42', '2', '这 圣 屋 长 一 百 肘 ， 宽 五 十 肘 ， 有 向 北 的 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21556', '26', '42', '3', '对 着 内 院 那 二 十 肘 宽 之 空 地 ， 又 对 着 外 院 的 铺 石 地 ， 在 第 三 层 楼 上 有 楼 廊 对 着 楼 廊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21557', '26', '42', '4', '在 圣 屋 前 有 一 条 夹 道 ， 宽 十 肘 ， 长 一 百 肘 。 房 门 都 向 北 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21558', '26', '42', '5', '圣 屋 因 为 楼 廊 占 去 些 地 方 ， 所 以 上 层 比 中 下 两 层 窄 些 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21559', '26', '42', '6', '圣 屋 有 三 层 ， 却 无 柱 子 ， 不 像 外 院 的 屋 子 有 柱 子 ； 所 以 上 层 比 中 下 两 层 更 窄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21560', '26', '42', '7', '圣 屋 外 ， 东 边 有 墙 ， 靠 着 外 院 ， 长 五 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21561', '26', '42', '8', '靠 着 外 院 的 圣 屋 长 五 十 肘 。 殿 北 面 的 圣 屋 长 一 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21562', '26', '42', '9', '在 圣 屋 以 下 ， 东 头 有 进 入 之 处 ， 就 是 从 外 院 进 入 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21563', '26', '42', '10', '向 南 ｛ 原 文 是 东 ｝ 在 内 院 墙 里 有 圣 屋 ， 一 排 与 铺 石 地 之 屋 相 对 ， 一 排 顺 着 空 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21564', '26', '42', '11', '这 圣 屋 前 的 夹 道 与 北 边 圣 屋 的 夹 道 长 宽 一 样 ； 出 入 之 处 与 北 屋 门 的 样 式 相 同 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21565', '26', '42', '12', '正 在 墙 前 、 夹 道 的 东 头 ， 有 门 可 以 进 入 ， 与 向 南 圣 屋 的 门 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21566', '26', '42', '13', '他 对 我 说 ： “ 顺 着 空 地 的 南 屋 北 屋 ， 都 是 圣 屋 ； 亲 近 耶 和 华 的 祭 司 当 在 那 里 吃 至 圣 的 物 ， 也 当 在 那 里 放 至 圣 的 物 ， 就 是 素 祭 、 赎 罪 祭 ， 和 赎 愆 祭 ， 因 此 处 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21567', '26', '42', '14', '祭 司 进 去 出 了 圣 所 的 时 候 ， 不 可 直 到 外 院 ， 但 要 在 圣 屋 放 下 他 们 供 职 的 衣 服 ， 因 为 是 圣 衣 ； 要 穿 上 别 的 衣 服 才 可 以 到 属 民 的 外 院 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21568', '26', '42', '15', '＜ 圣 殿 周 围 的 尺 寸 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21569', '26', '42', '16', '他 用 量 度 的 竿 量 四 围 ， 量 东 面 五 百 肘 ｛ 原 文 是 竿 ； 本 章 下 同 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21570', '26', '42', '17', '用 竿 量 北 面 五 百 肘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21571', '26', '42', '18', '用 竿 量 南 面 五 百 肘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21572', '26', '42', '19', '又 转 到 西 面 ， 用 竿 量 五 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21573', '26', '42', '20', '他 量 四 面 ， 四 围 有 墙 ， 长 五 百 肘 ， 宽 五 百 肘 ， 为 要 分 别 圣 地 与 俗 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21574', '26', '43', '1', '＜ 耶 和 华 回 到 圣 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21575', '26', '43', '2', '以 色 列 神 的 荣 光 从 东 而 来 。 他 的 声 音 如 同 多 水 的 声 音 ； 地 就 因 他 的 荣 耀 发 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21576', '26', '43', '3', '其 状 如 从 前 他 来 灭 城 的 时 候 我 所 见 的 异 象 ， 那 异 象 如 我 在 迦 巴 鲁 河 边 所 见 的 异 象 ， 我 就 俯 伏 在 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21577', '26', '43', '4', '耶 和 华 的 荣 光 从 朝 东 的 门 照 入 殿 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21578', '26', '43', '5', '灵 将 我 举 起 ， 带 入 内 院 ， 不 料 ， 耶 和 华 的 荣 光 充 满 了 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21579', '26', '43', '6', '我 听 见 有 一 位 从 殿 中 对 我 说 话 。 有 一 人 站 在 我 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21580', '26', '43', '7', '他 对 我 说 ： “ 人 子 啊 ， 这 是 我 宝 座 之 地 ， 是 我 脚 掌 所 踏 之 地 。 我 要 在 这 里 住 ， 在 以 色 列 人 中 直 到 永 远 。 以 色 列 家 和 他 们 的 君 王 必 不 再 玷 污 我 的 圣 名 ， 就 是 行 邪 淫 、 在 锡 安 的 高 处 葬 埋 他 们 君 王 的 尸 首 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21581', '26', '43', '8', '使 他 们 的 门 槛 挨 近 我 的 门 槛 ， 他 们 的 门 框 挨 近 我 的 门 框 ； 他 们 与 我 中 间 仅 隔 一 墙 ， 并 且 行 可 憎 的 事 ， 玷 污 了 我 的 圣 名 ， 所 以 我 发 怒 灭 绝 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21582', '26', '43', '9', '现 在 他 们 当 从 我 面 前 远 除 邪 淫 和 他 们 君 王 的 尸 首 ， 我 就 住 在 他 们 中 间 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21583', '26', '43', '10', '“ 人 子 啊 ， 你 要 将 这 殿 指 示 以 色 列 家 ， 使 他 们 因 自 己 的 罪 孽 惭 愧 ， 也 要 他 们 量 殿 的 尺 寸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21584', '26', '43', '11', '他 们 若 因 自 己 所 行 的 一 切 事 惭 愧 ， 你 就 将 殿 的 规 模 、 样 式 、 出 入 之 处 ， 和 一 切 形 状 、 典 章 、 礼 仪 、 法 则 指 示 他 们 ， 在 他 们 眼 前 写 上 ， 使 他 们 遵 照 殿 的 一 切 规 模 典 章 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21585', '26', '43', '12', '殿 的 法 则 乃 是 如 此 ： 殿 在 山 顶 上 ， 四 围 的 全 界 要 称 为 至 圣 。 这 就 是 殿 的 法 则 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21586', '26', '43', '13', '＜ 祭 坛 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21587', '26', '43', '14', '从 底 座 到 下 层 磴 台 ， 高 二 肘 ， 边 宽 一 肘 。 从 小 磴 台 到 大 磴 台 ， 高 四 肘 ， 边 宽 一 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21588', '26', '43', '15', '坛 上 的 供 台 ， 高 四 肘 。 供 台 的 四 拐 角 上 都 有 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21589', '26', '43', '16', '供 台 长 十 二 肘 ， 宽 十 二 肘 ， 四 面 见 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21590', '26', '43', '17', '磴 台 长 十 四 肘 ， 宽 十 四 肘 ， 四 面 见 方 。 四 围 起 边 高 半 肘 ， 底 座 四 围 的 边 宽 一 肘 。 台 阶 朝 东 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21591', '26', '43', '18', '＜ 奉 献 祭 坛 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21592', '26', '43', '19', '主 耶 和 华 说 ， 你 要 将 一 只 公 牛 犊 作 为 赎 罪 祭 ， 给 祭 司 利 未 人 撒 督 的 后 裔 ， 就 是 那 亲 近 我 、 事 奉 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21593', '26', '43', '20', '你 要 取 些 公 牛 的 血 ， 抹 在 坛 的 四 角 和 磴 台 的 四 拐 角 ， 并 四 围 所 起 的 边 上 。 你 这 样 洁 净 坛 ， 坛 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21594', '26', '43', '21', '你 又 要 将 那 作 赎 罪 祭 的 公 牛 犊 烧 在 殿 外 、 圣 地 之 外 预 定 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21595', '26', '43', '22', '次 日 ， 要 将 无 残 疾 的 公 山 羊 献 为 赎 罪 祭 ； 要 洁 净 坛 ， 像 用 公 牛 犊 洁 净 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21596', '26', '43', '23', '洁 净 了 坛 ， 就 要 将 一 只 无 残 疾 的 公 牛 犊 和 羊 群 中 一 只 无 残 疾 的 公 绵 羊');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21597', '26', '43', '24', '奉 到 耶 和 华 前 。 祭 司 要 撒 盐 在 其 上 ， 献 与 耶 和 华 为 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21598', '26', '43', '25', '七 日 内 ， 每 日 要 预 备 一 只 公 山 羊 为 赎 罪 祭 ， 也 要 预 备 一 只 公 牛 犊 和 羊 群 中 的 一 只 公 绵 羊 ， 都 要 没 有 残 疾 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21599', '26', '43', '26', '七 日 祭 司 洁 净 坛 ， 坛 就 洁 净 了 ； 要 这 样 把 坛 分 别 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21600', '26', '43', '27', '满 了 七 日 ， 自 八 日 以 后 ， 祭 司 要 在 坛 上 献 你 们 的 燔 祭 和 平 安 祭 ； 我 必 悦 纳 你 们 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21601', '26', '44', '1', '＜ 东 门 的 使 用 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21602', '26', '44', '2', '耶 和 华 对 我 说 ： “ 这 门 必 须 关 闭 ， 不 可 敞 开 ， 谁 也 不 可 由 其 中 进 入 ； 因 为 耶 和 华 ─ ─ 以 色 列 的 神 已 经 由 其 中 进 入 ， 所 以 必 须 关 闭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21603', '26', '44', '3', '至 于 王 ， 他 必 按 王 的 位 分 ， 坐 在 其 内 ， 在 耶 和 华 面 前 吃 饼 。 他 必 由 这 门 的 廊 而 入 ， 也 必 由 此 而 出 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21604', '26', '44', '4', '＜ 进 入 圣 殿 的 规 则 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21605', '26', '44', '5', '耶 和 华 对 我 说 ： “ 人 子 啊 ， 我 对 你 所 说 耶 和 华 殿 中 的 一 切 典 章 法 则 ， 你 要 放 在 心 上 ， 用 眼 看 ， 用 耳 听 ， 并 要 留 心 殿 宇 和 圣 地 一 切 出 入 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21606', '26', '44', '6', '你 要 对 那 悖 逆 的 以 色 列 家 说 ， 主 耶 和 华 如 此 说 ： 以 色 列 家 啊 ， 你 们 行 一 切 可 憎 的 事 ， 当 够 了 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21607', '26', '44', '7', '你 们 把 我 的 食 物 ， 就 是 脂 油 和 血 献 上 的 时 候 ， 将 身 心 未 受 割 礼 的 外 邦 人 领 进 我 的 圣 地 ， 玷 污 了 我 的 殿 ； 又 背 了 我 的 约 ， 在 你 们 一 切 可 憎 的 事 上 ， 加 上 这 一 层 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21608', '26', '44', '8', '你 们 也 没 有 看 守 我 的 圣 物 ， 却 派 别 人 在 圣 地 替 你 们 看 守 我 所 吩 咐 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21609', '26', '44', '9', '“ 主 耶 和 华 如 此 说 ： 以 色 列 中 的 外 邦 人 ， 就 是 身 心 未 受 割 礼 的 ， 都 不 可 入 我 的 圣 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21610', '26', '44', '10', '＜ 不 准 当 祭 司 的 利 未 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21611', '26', '44', '11', '然 而 他 们 必 在 我 的 圣 地 当 仆 役 ， 照 管 殿 门 ， 在 殿 中 供 职 ； 必 为 民 宰 杀 燔 祭 牲 和 平 安 祭 牲 ， 必 站 在 民 前 伺 候 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21612', '26', '44', '12', '因 为 这 些 利 未 人 曾 在 偶 像 前 伺 候 这 民 ， 成 了 以 色 列 家 罪 孽 的 绊 脚 石 ， 所 以 我 向 他 们 起 誓 ： 他 们 必 担 当 自 己 的 罪 孽 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21613', '26', '44', '13', '他 们 不 可 亲 近 我 ， 给 我 供 祭 司 的 职 分 ， 也 不 可 挨 近 我 的 一 件 圣 物 ， 就 是 至 圣 的 物 ； 他 们 却 要 担 当 自 己 的 羞 辱 和 所 行 可 憎 之 事 的 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21614', '26', '44', '14', '然 而 我 要 使 他 们 看 守 殿 宇 ， 办 理 其 中 的 一 切 事 ， 并 做 其 内 一 切 当 做 之 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21615', '26', '44', '15', '＜ 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21616', '26', '44', '16', '他 们 必 进 入 我 的 圣 所 ， 就 近 我 的 桌 前 事 奉 我 ， 守 我 所 吩 咐 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21617', '26', '44', '17', '他 们 进 内 院 门 必 穿 细 麻 衣 。 在 内 院 门 和 殿 内 供 职 的 时 候 不 可 穿 羊 毛 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21618', '26', '44', '18', '他 们 头 上 要 戴 细 麻 布 裹 头 巾 ， 腰 穿 细 麻 布 裤 子 ； 不 可 穿 使 身 体 出 汗 的 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21619', '26', '44', '19', '他 们 出 到 外 院 的 民 那 里 ， 当 脱 下 供 职 的 衣 服 ， 放 在 圣 屋 内 ， 穿 上 别 的 衣 服 ， 免 得 因 圣 衣 使 民 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21620', '26', '44', '20', '不 可 剃 头 ， 也 不 可 容 发 绺 长 长 ， 只 可 剪 发 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21621', '26', '44', '21', '祭 司 进 内 院 的 时 候 都 不 可 喝 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21622', '26', '44', '22', '不 可 娶 寡 妇 和 被 休 的 妇 人 为 妻 ， 只 可 娶 以 色 列 后 裔 中 的 处 女 ， 或 是 祭 司 遗 留 的 寡 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21623', '26', '44', '23', '他 们 要 使 我 的 民 知 道 圣 俗 的 分 别 ， 又 使 他 们 分 辨 洁 净 的 和 不 洁 净 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21624', '26', '44', '24', '有 争 讼 的 事 ， 他 们 应 当 站 立 判 断 ， 要 按 我 的 典 章 判 断 。 在 我 一 切 的 节 期 必 守 我 的 律 法 、 条 例 ， 也 必 以 我 的 安 息 日 为 圣 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21625', '26', '44', '25', '他 们 不 可 挨 近 死 尸 沾 染 自 己 ， 只 可 为 父 亲 、 母 亲 、 儿 子 、 女 儿 、 弟 兄 ， 和 未 嫁 人 的 姊 妹 沾 染 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21626', '26', '44', '26', '祭 司 洁 净 之 后 ， 必 再 计 算 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21627', '26', '44', '27', '当 他 进 内 院 ， 进 圣 所 ， 在 圣 所 中 事 奉 的 日 子 ， 要 为 自 己 献 赎 罪 祭 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21628', '26', '44', '28', '“ 祭 司 必 有 产 业 ， 我 是 他 们 的 产 业 。 不 可 在 以 色 列 中 给 他 们 基 业 ； 我 是 他 们 的 基 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21629', '26', '44', '29', '素 祭 、 赎 罪 祭 ， 和 赎 愆 祭 他 们 都 可 以 吃 ， 以 色 列 中 一 切 永 献 的 物 都 要 归 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21630', '26', '44', '30', '首 先 初 熟 之 物 和 一 切 所 献 的 供 物 都 要 归 给 祭 司 。 你 们 也 要 用 初 熟 的 麦 子 磨 面 给 祭 司 ； 这 样 ， 福 气 就 必 临 到 你 们 的 家 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21631', '26', '44', '31', '无 论 是 鸟 是 兽 ， 凡 自 死 的 ， 或 是 撕 裂 的 ， 祭 司 都 不 可 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21632', '26', '45', '1', '＜ 归 给 耶 和 华 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21633', '26', '45', '2', '其 中 有 作 为 圣 所 之 地 ， 长 五 百 肘 ， 宽 五 百 肘 ， 四 面 见 方 。 四 围 再 有 五 十 肘 为 郊 野 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21634', '26', '45', '3', '要 以 肘 为 度 量 地 ， 长 二 万 五 千 肘 ， 宽 一 万 肘 。 其 中 有 圣 所 ， 是 至 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21635', '26', '45', '4', '这 是 全 地 的 一 分 圣 地 ， 要 归 与 供 圣 所 职 事 的 祭 司 ， 就 是 亲 近 事 奉 耶 和 华 的 ， 作 为 他 们 房 屋 之 地 与 圣 所 之 圣 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21636', '26', '45', '5', '又 有 一 分 ， 长 二 万 五 千 肘 ， 宽 一 万 肘 ， 要 归 与 在 殿 中 供 职 的 利 未 人 ， 作 为 二 十 间 房 屋 之 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21637', '26', '45', '6', '也 要 分 定 属 城 的 地 业 ， 宽 五 千 肘 ， 长 二 万 五 千 肘 ， 挨 着 那 分 圣 供 地 ， 要 归 以 色 列 全 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21638', '26', '45', '7', '＜ 君 王 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21639', '26', '45', '8', '这 地 在 以 色 列 中 必 归 王 为 业 。 我 所 立 的 王 必 不 再 欺 压 我 的 民 ， 却 要 按 支 派 将 地 分 给 以 色 列 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21640', '26', '45', '9', '＜ 君 王 应 守 的 规 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21641', '26', '45', '10', '“ 你 们 要 用 公 道 天 平 、 公 道 伊 法 、 公 道 罢 特 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21642', '26', '45', '11', '伊 法 与 罢 特 大 小 要 一 样 。 罢 特 可 盛 贺 梅 珥 十 分 之 一 ， 伊 法 也 可 盛 贺 梅 珥 十 分 之 一 ， 都 以 贺 梅 珥 的 大 小 为 准 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21643', '26', '45', '12', '舍 客 勒 是 二 十 季 拉 ； 二 十 舍 客 勒 ， 二 十 五 舍 客 勒 ， 十 五 舍 客 勒 ， 为 你 们 的 弥 那 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21644', '26', '45', '13', '“ 你 们 当 献 的 供 物 乃 是 这 样 ： 一 贺 梅 珥 麦 子 要 献 伊 法 六 分 之 一 ； 一 贺 梅 珥 大 麦 要 献 伊 法 六 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21645', '26', '45', '14', '你 们 献 所 分 定 的 油 ， 按 油 的 罢 特 ， 一 柯 珥 油 要 献 罢 特 十 分 之 一 （ 原 来 十 罢 特 就 是 一 贺 梅 珥 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21646', '26', '45', '15', '从 以 色 列 滋 润 的 草 场 上 每 二 百 羊 中 ， 要 献 一 只 羊 羔 。 这 都 可 作 素 祭 、 燔 祭 、 平 安 祭 ， 为 民 赎 罪 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21647', '26', '45', '16', '此 地 的 民 都 要 奉 上 这 供 物 给 以 色 列 中 的 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21648', '26', '45', '17', '王 的 本 分 是 在 节 期 、 月 朔 、 安 息 日 ， 就 是 以 色 列 家 一 切 的 节 期 ， 奉 上 燔 祭 、 素 祭 、 奠 祭 。 他 要 预 备 赎 罪 祭 、 素 祭 、 燔 祭 ， 和 平 安 祭 ， 为 以 色 列 家 赎 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21649', '26', '45', '18', '＜ 节 期 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21650', '26', '45', '19', '祭 司 要 取 些 赎 罪 祭 牲 的 血 ， 抹 在 殿 的 门 柱 上 和 坛 磴 台 的 四 角 上 ， 并 内 院 的 门 框 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21651', '26', '45', '20', '本 月 初 七 日 ｛ 七 十 士 译 本 是 七 月 初 一 日 ｝ 也 要 为 误 犯 罪 的 和 愚 蒙 犯 罪 的 如 此 行 ， 为 殿 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21652', '26', '45', '21', '“ 正 月 十 四 日 ， 你 们 要 守 逾 越 节 ， 守 节 七 日 ， 要 吃 无 酵 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21653', '26', '45', '22', '当 日 ， 王 要 为 自 己 和 国 内 的 众 民 预 备 一 只 公 牛 作 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21654', '26', '45', '23', '这 节 的 七 日 ， 每 日 他 要 为 耶 和 华 预 备 无 残 疾 的 公 牛 七 只 、 公 绵 羊 七 只 为 燔 祭 。 每 日 又 要 预 备 公 山 羊 一 只 为 赎 罪 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21655', '26', '45', '24', '他 也 要 预 备 素 祭 ， 就 是 为 一 只 公 牛 同 献 一 伊 法 细 面 ， 为 一 只 公 绵 羊 同 献 一 伊 法 细 面 ， 每 一 伊 法 细 面 加 油 一 欣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21656', '26', '45', '25', '七 月 十 五 日 守 节 的 时 候 ， 七 日 他 都 要 如 此 行 ， 照 逾 越 节 的 赎 罪 祭 、 燔 祭 、 素 祭 ， 和 油 的 条 例 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21657', '26', '46', '1', '＜ 君 王 和 节 期 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21658', '26', '46', '2', '王 要 从 这 门 的 廊 进 入 ， 站 在 门 框 旁 边 。 祭 司 要 为 他 预 备 燔 祭 和 平 安 祭 ， 他 就 要 在 门 槛 那 里 敬 拜 ， 然 后 出 去 。 这 门 直 到 晚 上 不 可 关 闭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21659', '26', '46', '3', '在 安 息 日 和 月 朔 ， 国 内 的 居 民 要 在 这 门 口 ， 耶 和 华 面 前 敬 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21660', '26', '46', '4', '安 息 日 ， 王 所 献 与 耶 和 华 的 燔 祭 要 用 无 残 疾 的 羊 羔 六 只 ， 无 残 疾 的 公 绵 羊 一 只 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21661', '26', '46', '5', '同 献 的 素 祭 要 为 公 绵 羊 献 一 伊 法 细 面 ， 为 羊 羔 照 他 的 力 量 而 献 ， 一 伊 法 细 面 加 油 一 欣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21662', '26', '46', '6', '当 月 朔 ， 要 献 无 残 疾 的 公 牛 犊 一 只 ， 羊 羔 六 只 ， 公 绵 羊 一 只 ， 都 要 无 残 疾 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21663', '26', '46', '7', '他 也 要 预 备 素 祭 ， 为 公 牛 献 一 伊 法 细 面 ， 为 公 绵 羊 献 一 伊 法 细 面 ， 为 羊 羔 照 他 的 力 量 而 献 ， 一 伊 法 细 面 加 油 一 欣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21664', '26', '46', '8', '王 进 入 的 时 候 必 由 这 门 的 廊 而 入 ， 也 必 由 此 而 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21665', '26', '46', '9', '“ 在 各 节 期 ， 国 内 居 民 朝 见 耶 和 华 的 时 候 ， 从 北 门 进 入 敬 拜 的 ， 必 由 南 门 而 出 ； 从 南 门 进 入 的 ， 必 由 北 门 而 出 。 不 可 从 所 入 的 门 而 出 ， 必 要 直 往 前 行 ， 由 对 门 而 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21666', '26', '46', '10', '民 进 入 ， 王 也 要 在 民 中 进 入 ； 民 出 去 ， 王 也 要 一 同 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21667', '26', '46', '11', '“ 在 节 期 和 圣 会 的 日 子 同 献 的 素 祭 ， 要 为 一 只 公 牛 献 一 伊 法 细 面 ， 为 一 只 公 绵 羊 献 一 伊 法 细 面 ， 为 羊 羔 照 他 的 力 量 而 献 ， 一 伊 法 细 面 加 油 一 欣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21668', '26', '46', '12', '王 预 备 甘 心 献 的 燔 祭 或 平 安 祭 ， 就 是 向 耶 和 华 甘 心 献 的 ， 当 有 人 为 他 开 朝 东 的 门 。 他 就 预 备 燔 祭 和 平 安 祭 ， 与 安 息 日 预 备 的 一 样 ， 献 毕 就 出 去 。 他 出 去 之 后 ， 当 有 人 将 门 关 闭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21669', '26', '46', '13', '＜ 每 日 的 祭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21670', '26', '46', '14', '每 早 晨 也 要 预 备 同 献 的 素 祭 ， 细 面 一 伊 法 六 分 之 一 ， 并 油 一 欣 三 分 之 一 ， 调 和 细 面 。 这 素 祭 要 常 献 与 耶 和 华 为 永 远 的 定 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21671', '26', '46', '15', '每 早 晨 要 这 样 预 备 羊 羔 、 素 祭 ， 并 油 为 常 献 的 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21672', '26', '46', '16', '＜ 王 和 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21673', '26', '46', '17', '倘 若 王 将 一 分 产 业 赐 给 他 的 臣 仆 ， 就 成 了 他 臣 仆 的 产 业 ； 到 自 由 之 年 仍 要 归 与 王 。 至 于 王 的 产 业 ， 必 归 与 他 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21674', '26', '46', '18', '王 不 可 夺 取 民 的 产 业 ， 以 致 驱 逐 他 们 离 开 所 承 受 的 ； 他 要 从 自 己 的 地 业 中 ， 将 产 业 赐 给 他 儿 子 ， 免 得 我 的 民 分 散 ， 各 人 离 开 所 承 受 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21675', '26', '46', '19', '＜ 圣 殿 的 厨 房 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21676', '26', '46', '20', '他 对 我 说 ： “ 这 是 祭 司 煮 赎 愆 祭 、 赎 罪 祭 ， 烤 素 祭 之 地 ， 免 得 带 到 外 院 ， 使 民 成 圣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21677', '26', '46', '21', '他 又 带 我 到 外 院 ， 使 我 经 过 院 子 的 四 拐 角 ， 见 每 拐 角 各 有 一 个 院 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21678', '26', '46', '22', '院 子 四 拐 角 的 院 子 ， 周 围 有 墙 ， 每 院 长 四 十 肘 ， 宽 三 十 肘 。 四 拐 角 院 子 的 尺 寸 都 是 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21679', '26', '46', '23', '其 中 周 围 有 一 排 房 子 ， 房 子 内 有 煮 肉 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21680', '26', '46', '24', '他 对 我 说 ： “ 这 都 是 煮 肉 的 房 子 ， 殿 内 的 仆 役 要 在 这 里 煮 民 的 祭 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21681', '26', '47', '1', '＜ 从 圣 殿 流 出 的 水 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21682', '26', '47', '2', '他 带 我 出 北 门 ， 又 领 我 从 外 边 转 到 朝 东 的 外 门 ， 见 水 从 右 边 流 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21683', '26', '47', '3', '他 手 拿 准 绳 往 东 出 去 的 时 候 ， 量 了 一 千 肘 ， 使 我 逿 过 水 ， 水 到 踝 子 骨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21684', '26', '47', '4', '他 又 量 了 一 千 肘 ， 使 我 逿 过 水 ， 水 就 到 膝 ； 再 量 了 一 千 肘 ， 使 我 逿 过 水 ， 水 便 到 腰 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21685', '26', '47', '5', '又 量 了 一 千 肘 ， 水 便 成 了 河 ， 使 我 不 能 逿 过 。 因 为 水 势 涨 起 ， 成 为 可 洑 的 水 ， 不 可 逿 的 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21686', '26', '47', '6', '他 对 我 说 ： “ 人 子 啊 ， 你 看 见 了 什 么 ？ ” 他 就 带 我 回 到 河 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21687', '26', '47', '7', '我 回 到 河 边 的 时 候 ， 见 在 河 这 边 与 那 边 的 岸 上 有 极 多 的 树 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21688', '26', '47', '8', '他 对 我 说 ： “ 这 水 往 东 方 流 去 ， 必 下 到 亚 拉 巴 ， 直 到 海 。 所 发 出 来 的 水 必 流 入 盐 海 ， 使 水 变 甜 ｛ 原 文 是 得 医 治 ； 下 同 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21689', '26', '47', '9', '这 河 水 所 到 之 处 ， 凡 滋 生 的 动 物 都 必 生 活 ， 并 且 因 这 流 来 的 水 必 有 极 多 的 鱼 ， 海 水 也 变 甜 了 。 这 河 水 所 到 之 处 ， 百 物 都 必 生 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21690', '26', '47', '10', '必 有 渔 夫 站 在 河 边 ， 从 隐 ． 基 底 直 到 隐 ． 以 革 莲 ， 都 作 晒 ｛ 或 译 ： 张 ｝ 网 之 处 。 那 鱼 各 从 其 类 ， 好 像 大 海 的 鱼 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21691', '26', '47', '11', '只 是 泥 泞 之 地 与 洼 湿 之 处 不 得 治 好 ， 必 为 盐 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21692', '26', '47', '12', '在 河 这 边 与 那 边 的 岸 上 必 生 长 各 类 的 树 木 ； 其 果 可 作 食 物 ， 叶 子 不 枯 干 ， 果 子 不 断 绝 。 每 月 必 结 新 果 子 ， 因 为 这 水 是 从 圣 所 流 出 来 的 。 树 上 的 果 子 必 作 食 物 ， 叶 子 乃 为 治 病 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21693', '26', '47', '13', '＜ 地 界 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21694', '26', '47', '14', '你 们 承 受 这 地 为 业 ， 要 彼 此 均 分 ； 因 为 我 曾 起 誓 应 许 将 这 地 赐 与 你 们 的 列 祖 ； 这 地 必 归 你 们 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21695', '26', '47', '15', '“ 地 的 四 界 乃 是 如 此 ： 北 界 从 大 海 往 希 特 伦 ， 直 到 西 达 达 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21696', '26', '47', '16', '又 往 哈 马 、 比 罗 他 、 西 伯 莲 （ 西 伯 莲 在 大 马 士 革 与 哈 马 两 界 中 间 ） ， 到 浩 兰 边 界 的 哈 撒 ． 哈 提 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21697', '26', '47', '17', '这 样 ， 境 界 从 海 边 往 大 马 士 革 地 界 上 的 哈 萨 ． 以 难 ， 北 边 以 哈 马 地 为 界 。 这 是 北 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21698', '26', '47', '18', '“ 东 界 在 浩 兰 、 大 马 士 革 、 基 列 ， 和 以 色 列 地 的 中 间 ， 就 是 约 旦 河 。 你 们 要 从 北 界 量 到 东 海 。 这 是 东 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21699', '26', '47', '19', '“ 南 界 是 从 他 玛 到 米 利 巴 ． 加 低 斯 的 水 ， 延 到 埃 及 小 河 ， 直 到 大 海 。 这 是 南 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21700', '26', '47', '20', '“ 西 界 就 是 大 海 ， 从 南 界 直 到 哈 马 口 对 面 之 地 。 这 是 西 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21701', '26', '47', '21', '“ 你 们 要 按 着 以 色 列 的 支 派 彼 此 分 这 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21702', '26', '47', '22', '要 拈 阄 分 这 地 为 业 ， 归 与 自 己 和 你 们 中 间 寄 居 的 外 人 ， 就 是 在 你 们 中 间 生 养 儿 女 的 外 人 。 你 们 要 看 他 们 如 同 以 色 列 人 中 所 生 的 一 样 ； 他 们 在 以 色 列 支 派 中 要 与 你 们 同 得 地 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21703', '26', '47', '23', '外 人 寄 居 在 哪 支 派 中 ， 你 们 就 在 那 里 分 给 他 地 业 。 这 是 主 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21704', '26', '48', '1', '＜ 各 支 派 分 配 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21705', '26', '48', '2', '挨 着 但 的 地 界 ， 从 东 到 西 ， 是 亚 设 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21706', '26', '48', '3', '挨 着 亚 设 的 地 界 ， 从 东 到 西 ， 是 拿 弗 他 利 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21707', '26', '48', '4', '挨 着 拿 弗 他 利 的 地 界 ， 从 东 到 西 ， 是 玛 拿 西 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21708', '26', '48', '5', '挨 着 玛 拿 西 的 地 界 ， 从 东 到 西 ， 是 以 法 莲 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21709', '26', '48', '6', '挨 着 以 法 莲 的 地 界 ， 从 东 到 西 ， 是 吕 便 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21710', '26', '48', '7', '挨 着 吕 便 的 地 界 ， 从 东 到 西 ， 是 犹 大 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21711', '26', '48', '8', '＜ 中 部 特 区 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21712', '26', '48', '9', '你 们 献 与 耶 和 华 的 供 地 要 长 二 万 五 千 肘 ， 宽 一 万 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21713', '26', '48', '10', '这 圣 供 地 要 归 与 祭 司 ， 北 长 二 万 五 千 肘 ， 西 宽 一 万 肘 ， 东 宽 一 万 肘 ， 南 长 二 万 五 千 肘 。 耶 和 华 的 圣 地 当 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21714', '26', '48', '11', '这 地 要 归 与 撒 督 的 子 孙 中 成 为 圣 的 祭 司 ， 就 是 那 守 我 所 吩 咐 的 。 当 以 色 列 人 走 迷 的 时 候 ， 他 们 不 像 那 些 利 未 人 走 迷 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21715', '26', '48', '12', '这 要 归 与 他 们 为 供 地 ， 是 全 地 中 至 圣 的 。 供 地 挨 着 利 未 人 的 地 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21716', '26', '48', '13', '利 未 人 所 得 的 地 要 长 二 万 五 千 肘 ， 宽 一 万 肘 ， 与 祭 司 的 地 界 相 等 ， 都 长 二 万 五 千 肘 ， 宽 一 万 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21717', '26', '48', '14', '这 地 不 可 卖 ， 不 可 换 ， 初 熟 之 物 也 不 可 归 与 别 人 ， 因 为 是 归 耶 和 华 为 圣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21718', '26', '48', '15', '这 二 万 五 千 肘 前 面 所 剩 下 五 千 肘 宽 之 地 要 作 俗 用 ， 作 为 造 城 盖 房 郊 野 之 地 。 城 要 在 当 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21719', '26', '48', '16', '城 的 尺 寸 乃 是 如 此 ： 北 面 四 千 五 百 肘 ， 南 面 四 千 五 百 肘 ， 东 面 四 千 五 百 肘 ， 西 面 四 千 五 百 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21720', '26', '48', '17', '城 必 有 郊 野 ， 向 北 二 百 五 十 肘 ， 向 南 二 百 五 十 肘 ， 向 东 二 百 五 十 肘 ， 向 西 二 百 五 十 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21721', '26', '48', '18', '靠 着 圣 供 地 的 余 地 ， 东 长 一 万 肘 ， 西 长 一 万 肘 ， 要 与 圣 供 地 相 等 ； 其 中 的 土 产 要 作 城 内 工 人 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21722', '26', '48', '19', '所 有 以 色 列 支 派 中 ， 在 城 内 做 工 的 ， 都 要 耕 种 这 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21723', '26', '48', '20', '你 们 所 献 的 圣 供 地 连 归 城 之 地 ， 是 四 方 的 ： 长 二 万 五 千 肘 ， 宽 二 万 五 千 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21724', '26', '48', '21', '圣 供 地 连 归 城 之 地 ， 两 边 的 余 地 要 归 与 王 。 供 地 东 边 ， 南 北 二 万 五 千 肘 ， 东 至 东 界 ， 西 边 南 北 二 万 五 千 肘 ， 西 至 西 界 ， 与 各 分 之 地 相 同 ， 都 要 归 王 。 圣 供 地 和 殿 的 圣 地 要 在 其 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21725', '26', '48', '22', '并 且 利 未 人 之 地 ， 与 归 城 之 地 的 东 西 两 边 延 长 之 地 （ 这 两 地 在 王 地 中 间 ） ， 就 是 在 犹 大 和 便 雅 悯 两 界 中 间 ， 要 归 与 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21726', '26', '48', '23', '＜ 其 他 支 派 的 土 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21727', '26', '48', '24', '挨 着 便 雅 悯 的 地 界 ， 从 东 到 西 ， 是 西 缅 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21728', '26', '48', '25', '挨 着 西 缅 的 地 界 ， 从 东 到 西 ， 是 以 萨 迦 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21729', '26', '48', '26', '挨 着 以 萨 迦 的 地 界 ， 从 东 到 西 ， 是 西 布 伦 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21730', '26', '48', '27', '挨 着 西 布 伦 的 地 界 ， 从 东 到 西 ， 是 迦 得 的 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21731', '26', '48', '28', '迦 得 地 的 南 界 是 从 他 玛 到 米 利 巴 ． 加 低 斯 的 水 ， 延 到 埃 及 小 河 ， 直 到 大 海 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21732', '26', '48', '29', '这 就 是 你 们 要 拈 阄 分 给 以 色 列 支 派 为 业 之 地 ， 乃 是 他 们 各 支 派 所 得 之 分 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21733', '26', '48', '30', '＜ 耶 路 撒 冷 的 城 门 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21734', '26', '48', '31', '城 的 各 门 要 按 以 色 列 支 派 的 名 字 。 北 面 有 三 门 ， 一 为 吕 便 门 ， 一 为 犹 大 门 ， 一 为 利 未 门 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21735', '26', '48', '32', '东 面 四 千 五 百 肘 ， 有 三 门 ， 一 为 约 瑟 门 ， 一 为 便 雅 悯 门 ， 一 为 但 门 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21736', '26', '48', '33', '南 面 四 千 五 百 肘 ， 有 三 门 ， 一 为 西 缅 门 ， 一 为 以 萨 迦 门 ， 一 为 西 布 伦 门 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21737', '26', '48', '34', '西 面 四 千 五 百 肘 ， 有 三 门 ， 一 为 迦 得 门 ， 一 为 亚 设 门 ， 一 为 拿 弗 他 利 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21738', '26', '48', '35', '城 四 围 共 一 万 八 千 肘 。 从 此 以 后 ， 这 城 的 名 字 必 称 为 “ 耶 和 华 的 所 在 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21739', '27', '1', '1', '＜ 但 以 理 和 他 的 朋 友 们 （ 但   1 : 1 - 6 : 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21740', '27', '1', '2', '主 将 犹 大 王 约 雅 敬 ， 并 神 殿 中 器 皿 的 几 分 交 付 他 手 。 他 就 把 这 器 皿 带 到 示 拿 地 ， 收 入 他 神 的 庙 里 ， 放 在 他 神 的 库 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21741', '27', '1', '3', '王 吩 咐 太 监 长 亚 施 毗 拿 ， 从 以 色 列 人 的 宗 室 和 贵 胄 中 带 进 几 个 人 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21742', '27', '1', '4', '就 是 年 少 没 有 残 疾 、 相 貌 俊 美 、 通 达 各 样 学 问 、 知 识 聪 明 俱 备 、 足 能 侍 立 在 王 宫 里 的 ， 要 教 他 们 迦 勒 底 的 文 字 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21743', '27', '1', '5', '王 派 定 将 自 己 所 用 的 膳 和 所 饮 的 酒 ， 每 日 赐 他 们 一 分 ， 养 他 们 三 年 。 满 了 三 年 ， 好 叫 他 们 在 王 面 前 侍 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21744', '27', '1', '6', '他 们 中 间 有 犹 大 族 的 人 ： 但 以 理 、 哈 拿 尼 雅 、 米 沙 利 、 亚 撒 利 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21745', '27', '1', '7', '太 监 长 给 他 们 起 名 ： 称 但 以 理 为 伯 提 沙 撒 ， 称 哈 拿 尼 雅 为 沙 得 拉 ， 称 米 沙 利 为 米 煞 ， 称 亚 撒 利 雅 为 亚 伯 尼 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21746', '27', '1', '8', '但 以 理 却 立 志 不 以 王 的 膳 和 王 所 饮 的 酒 玷 污 自 己 ， 所 以 求 太 监 长 容 他 不 玷 污 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21747', '27', '1', '9', '神 使 但 以 理 在 太 监 长 眼 前 蒙 恩 惠 ， 受 怜 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21748', '27', '1', '10', '太 监 长 对 但 以 理 说 ： “ 我 惧 怕 我 主 我 王 ， 他 已 经 派 定 你 们 的 饮 食 ， 倘 若 他 见 你 们 的 面 貌 比 你 们 同 岁 的 少 年 人 肌 瘦 ， 怎 么 好 呢 ？ 这 样 ， 你 们 就 使 我 的 头 在 王 那 里 难 保 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21749', '27', '1', '11', '但 以 理 对 太 监 长 所 派 管 理 但 以 理 、 哈 拿 尼 雅 、 米 沙 利 、 亚 撒 利 雅 的 委 办 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21750', '27', '1', '12', '“ 求 你 试 试 仆 人 们 十 天 ， 给 我 们 素 菜 吃 ， 白 水 喝 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21751', '27', '1', '13', '然 后 看 看 我 们 的 面 貌 和 用 王 膳 那 少 年 人 的 面 貌 ， 就 照 你 所 看 的 待 仆 人 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21752', '27', '1', '14', '委 办 便 允 准 他 们 这 件 事 ， 试 看 他 们 十 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21753', '27', '1', '15', '过 了 十 天 ， 见 他 们 的 面 貌 比 用 王 膳 的 一 切 少 年 人 更 加 俊 美 肥 胖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21754', '27', '1', '16', '于 是 委 办 撤 去 派 他 们 用 的 膳 ， 饮 的 酒 ， 给 他 们 素 菜 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21755', '27', '1', '17', '这 四 个 少 年 人 ， 神 在 各 样 文 字 学 问 ｛ 学 问 ： 原 文 是 智 慧 ｝ 上 赐 给 他 们 聪 明 知 识 ； 但 以 理 又 明 白 各 样 的 异 象 和 梦 兆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21756', '27', '1', '18', '尼 布 甲 尼 撒 王 预 定 带 进 少 年 人 来 的 日 期 满 了 ， 太 监 长 就 把 他 们 带 到 王 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21757', '27', '1', '19', '王 与 他 们 谈 论 ， 见 少 年 人 中 无 一 人 能 比 但 以 理 、 哈 拿 尼 雅 、 米 沙 利 、 亚 撒 利 雅 ， 所 以 留 他 们 在 王 面 前 侍 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21758', '27', '1', '20', '王 考 问 他 们 一 切 事 ， 就 见 他 们 的 智 慧 聪 明 比 通 国 的 术 士 和 用 法 术 的 胜 过 十 倍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21759', '27', '1', '21', '到 塞 鲁 士 王 元 年 ， 但 以 理 还 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21760', '27', '2', '1', '尼 布 甲 尼 撒 在 位 第 二 年 ， 他 做 了 梦 ， 心 里 烦 乱 ， 不 能 睡 觉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21761', '27', '2', '2', '王 吩 咐 人 将 术 士 、 用 法 术 的 、 行 邪 术 的 ， 和 迦 勒 底 人 召 来 ， 要 他 们 将 王 的 梦 告 诉 王 ， 他 们 就 来 站 在 王 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21762', '27', '2', '3', '王 对 他 们 说 ： “ 我 做 了 一 梦 ， 心 里 烦 乱 ， 要 知 道 这 是 什 么 梦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21763', '27', '2', '4', '迦 勒 底 人 用 亚 兰 的 言 语 对 王 说 ： “ 愿 王 万 岁 ！ 请 将 那 梦 告 诉 仆 人 ， 仆 人 就 可 以 讲 解 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21764', '27', '2', '5', '王 回 答 迦 勒 底 人 说 ： “ 梦 我 已 经 忘 了 ｛ 或 译 ： 我 已 定 命 ； 八 节 同 ｝ ， 你 们 若 不 将 梦 和 梦 的 讲 解 告 诉 我 ， 就 必 被 凌 迟 ， 你 们 的 房 屋 必 成 为 粪 堆 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21765', '27', '2', '6', '你 们 若 将 梦 和 梦 的 讲 解 告 诉 我 ， 就 必 从 我 这 里 得 赠 品 和 赏 赐 ， 并 大 尊 荣 。 现 在 你 们 要 将 梦 和 梦 的 讲 解 告 诉 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21766', '27', '2', '7', '他 们 第 二 次 对 王 说 ： “ 请 王 将 梦 告 诉 仆 人 ， 仆 人 就 可 以 讲 解 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21767', '27', '2', '8', '王 回 答 说 ： “ 我 准 知 道 你 们 是 故 意 迟 延 ， 因 为 你 们 知 道 那 梦 我 已 经 忘 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21768', '27', '2', '9', '你 们 若 不 将 梦 告 诉 我 ， 只 有 一 法 待 你 们 ； 因 为 你 们 预 备 了 谎 言 乱 语 向 我 说 ， 要 等 候 时 势 改 变 。 现 在 你 们 要 将 梦 告 诉 我 ， 因 我 知 道 你 们 能 将 梦 的 讲 解 告 诉 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21769', '27', '2', '10', '迦 勒 底 人 在 王 面 前 回 答 说 ： “ 世 上 没 有 人 能 将 王 所 问 的 事 说 出 来 ； 因 为 没 有 君 王 、 大 臣 、 掌 权 的 向 术 士 ， 或 用 法 术 的 ， 或 迦 勒 底 人 问 过 这 样 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21770', '27', '2', '11', '王 所 问 的 事 甚 难 。 除 了 不 与 世 人 同 居 的 神 明 ， 没 有 人 在 王 面 前 能 说 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21771', '27', '2', '12', '因 此 ， 王 气 忿 忿 地 大 发 烈 怒 ， 吩 咐 灭 绝 巴 比 伦 所 有 的 哲 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21772', '27', '2', '13', '于 是 命 令 发 出 ， 哲 士 将 要 见 杀 ， 人 就 寻 找 但 以 理 和 他 的 同 伴 ， 要 杀 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21773', '27', '2', '14', '＜ 神 把 梦 的 意 思 指 示 但 以 理 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21774', '27', '2', '15', '向 王 的 护 卫 长 亚 略 说 ： “ 王 的 命 令 为 何 这 样 紧 急 呢 ？ ” 亚 略 就 将 情 节 告 诉 但 以 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21775', '27', '2', '16', '但 以 理 遂 进 去 求 王 宽 限 ， 就 可 以 将 梦 的 讲 解 告 诉 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21776', '27', '2', '17', '但 以 理 回 到 他 的 居 所 ， 将 这 事 告 诉 他 的 同 伴 哈 拿 尼 雅 、 米 沙 利 、 亚 撒 利 雅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21777', '27', '2', '18', '要 他 们 祈 求 天 上 的 神 施 怜 悯 ， 将 这 奥 秘 的 事 指 明 ， 免 得 但 以 理 和 他 的 同 伴 与 巴 比 伦 其 余 的 哲 士 一 同 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21778', '27', '2', '19', '这 奥 秘 的 事 就 在 夜 间 异 象 中 给 但 以 理 显 明 ， 但 以 理 便 称 颂 天 上 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21779', '27', '2', '20', '但 以 理 说 ： “ 神 的 名 是 应 当 称 颂 的 ！ 从 亘 古 直 到 永 远 ， 因 为 智 慧 能 力 都 属 乎 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21780', '27', '2', '21', '他 改 变 时 候 、 日 期 ， 废 王 ， 立 王 ， 将 智 慧 赐 与 智 慧 人 ， 将 知 识 赐 与 聪 明 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21781', '27', '2', '22', '他 显 明 深 奥 隐 秘 的 事 ， 知 道 暗 中 所 有 的 ， 光 明 也 与 他 同 居 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21782', '27', '2', '23', '我 列 祖 的 神 啊 ， 我 感 谢 你 ， 赞 美 你 ； 因 你 将 智 慧 才 能 赐 给 我 ， 允 准 我 们 所 求 的 ， 把 王 的 事 给 我 们 指 明 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21783', '27', '2', '24', '＜ 但 以 理 为 王 解 梦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21784', '27', '2', '25', '亚 略 就 急 忙 将 但 以 理 领 到 王 面 前 ， 对 王 说 ： “ 我 在 被 掳 的 犹 大 人 中 遇 见 一 人 ， 他 能 将 梦 的 讲 解 告 诉 王 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21785', '27', '2', '26', '王 问 称 为 伯 提 沙 撒 的 但 以 理 说 ： “ 你 能 将 我 所 做 的 梦 和 梦 的 讲 解 告 诉 我 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21786', '27', '2', '27', '但 以 理 在 王 面 前 回 答 说 ： “ 王 所 问 的 那 奥 秘 事 ， 哲 士 、 用 法 术 的 、 术 士 、 观 兆 的 都 不 能 告 诉 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21787', '27', '2', '28', '只 有 一 位 在 天 上 的 神 能 显 明 奥 秘 的 事 。 他 已 将 日 后 必 有 的 事 指 示 尼 布 甲 尼 撒 王 。 你 的 梦 和 你 在 床 上 脑 中 的 异 象 是 这 样 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21788', '27', '2', '29', '王 啊 ， 你 在 床 上 想 到 后 来 的 事 ， 那 显 明 奥 秘 事 的 主 把 将 来 必 有 的 事 指 示 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21789', '27', '2', '30', '至 于 那 奥 秘 的 事 显 明 给 我 ， 并 非 因 我 的 智 慧 胜 过 一 切 活 人 ， 乃 为 使 王 知 道 梦 的 讲 解 和 心 里 的 思 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21790', '27', '2', '31', '“ 王 啊 ， 你 梦 见 一 个 大 像 ， 这 像 甚 高 ， 极 其 光 耀 ， 站 在 你 面 前 ， 形 状 甚 是 可 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21791', '27', '2', '32', '这 像 的 头 是 精 金 的 ， 胸 膛 和 膀 臂 是 银 的 ， 肚 腹 和 腰 是 铜 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21792', '27', '2', '33', '腿 是 铁 的 ， 脚 是 半 铁 半 泥 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21793', '27', '2', '34', '你 观 看 ， 见 有 一 块 非 人 手 凿 出 来 的 石 头 打 在 这 像 半 铁 半 泥 的 脚 上 ， 把 脚 砸 碎 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21794', '27', '2', '35', '于 是 金 、 银 、 铜 、 铁 、 泥 都 一 同 砸 得 粉 碎 ， 成 如 夏 天 禾 场 上 的 糠 秕 ， 被 风 吹 散 ， 无 处 可 寻 。 打 碎 这 像 的 石 头 变 成 一 座 大 山 ， 充 满 天 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21795', '27', '2', '36', '“ 这 就 是 那 梦 ； 我 们 在 王 面 前 要 讲 解 那 梦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21796', '27', '2', '37', '王 啊 ， 你 是 诸 王 之 王 。 天 上 的 神 已 将 国 度 、 权 柄 、 能 力 、 尊 荣 都 赐 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21797', '27', '2', '38', '凡 世 人 所 住 之 地 的 走 兽 ， 并 天 空 的 飞 鸟 ， 他 都 交 付 你 手 ， 使 你 掌 管 这 一 切 。 你 就 是 那 金 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21798', '27', '2', '39', '在 你 以 后 必 另 兴 一 国 ， 不 及 于 你 ； 又 有 第 三 国 ， 就 是 铜 的 ， 必 掌 管 天 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21799', '27', '2', '40', '第 四 国 ， 必 坚 壮 如 铁 ， 铁 能 打 碎 克 制 百 物 ， 又 能 压 碎 一 切 ， 那 国 也 必 打 碎 压 制 列 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21800', '27', '2', '41', '你 既 见 像 的 脚 和 脚 指 头 ， 一 半 是 窑 匠 的 泥 ， 一 半 是 铁 ， 那 国 将 来 也 必 分 开 。 你 既 见 铁 与 泥 搀 杂 ， 那 国 也 必 有 铁 的 力 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21801', '27', '2', '42', '那 脚 指 头 ， 既 是 半 铁 半 泥 ， 那 国 也 必 半 强 半 弱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21802', '27', '2', '43', '你 既 见 铁 与 泥 搀 杂 ， 那 国 民 也 必 与 各 种 人 搀 杂 ， 却 不 能 彼 此 相 合 ， 正 如 铁 与 泥 不 能 相 合 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21803', '27', '2', '44', '当 那 列 王 在 位 的 时 候 ， 天 上 的 神 必 另 立 一 国 ， 永 不 败 坏 ， 也 不 归 别 国 的 人 ， 却 要 打 碎 灭 绝 那 一 切 国 ， 这 国 必 存 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21804', '27', '2', '45', '你 既 看 见 非 人 手 凿 出 来 的 一 块 石 头 从 山 而 出 ， 打 碎 金 、 银 、 铜 、 铁 、 泥 ， 那 就 是 至 大 的 神 把 后 来 必 有 的 事 给 王 指 明 。 这 梦 准 是 这 样 ， 这 讲 解 也 是 确 实 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21805', '27', '2', '46', '＜ 王 奖 赏 但 以 理 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21806', '27', '2', '47', '王 对 但 以 理 说 ： “ 你 既 能 显 明 这 奥 秘 的 事 ， 你 们 的 神 诚 然 是 万 神 之 神 、 万 王 之 主 ， 又 是 显 明 奥 秘 事 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21807', '27', '2', '48', '于 是 王 高 抬 但 以 理 ， 赏 赐 他 许 多 上 等 礼 物 ， 派 他 管 理 巴 比 伦 全 省 ， 又 立 他 为 总 理 ， 掌 管 巴 比 伦 的 一 切 哲 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21808', '27', '2', '49', '但 以 理 求 王 ， 王 就 派 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 管 理 巴 比 伦 省 的 事 务 ， 只 是 但 以 理 常 在 朝 中 侍 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21809', '27', '3', '1', '＜ 尼 布 甲 尼 撒 下 令 拜 金 像 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21810', '27', '3', '2', '尼 布 甲 尼 撒 王 差 人 将 总 督 、 钦 差 、 巡 抚 、 臬 司 、 藩 司 、 谋 士 、 法 官 ， 和 各 省 的 官 员 都 召 了 来 ， 为 尼 布 甲 尼 撒 王 所 立 的 像 行 开 光 之 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21811', '27', '3', '3', '于 是 总 督 、 钦 差 、 巡 抚 、 臬 司 、 藩 司 、 谋 士 、 法 官 ， 和 各 省 的 官 员 都 聚 集 了 来 ， 要 为 尼 布 甲 尼 撒 王 所 立 的 像 行 开 光 之 礼 ， 就 站 在 尼 布 甲 尼 撒 所 立 的 像 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21812', '27', '3', '4', '那 时 传 令 的 大 声 呼 叫 说 ： “ 各 方 、 各 国 、 各 族 ｛ 原 文 是 舌 ； 下 同 ｝ 的 人 哪 ， 有 令 传 与 你 们 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21813', '27', '3', '5', '你 们 一 听 见 角 、 笛 、 琵 琶 、 琴 、 瑟 、 笙 ， 和 各 样 乐 器 的 声 音 ， 就 当 俯 伏 敬 拜 尼 布 甲 尼 撒 王 所 立 的 金 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21814', '27', '3', '6', '凡 不 俯 伏 敬 拜 的 ， 必 立 时 扔 在 烈 火 的 窑 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21815', '27', '3', '7', '因 此 各 方 、 各 国 、 各 族 的 人 民 一 听 见 角 、 笛 、 琵 琶 、 琴 、 瑟 ， 和 各 样 乐 器 的 声 音 ， 就 都 俯 伏 敬 拜 尼 布 甲 尼 撒 王 所 立 的 金 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21816', '27', '3', '8', '＜ 但 以 理 的 三 个 朋 友 被 控 违 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21817', '27', '3', '9', '他 们 对 尼 布 甲 尼 撒 王 说 ： “ 愿 王 万 岁 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21818', '27', '3', '10', '王 啊 ， 你 曾 降 旨 说 ， 凡 听 见 角 、 笛 、 琵 琶 、 琴 、 瑟 、 笙 ， 和 各 样 乐 器 声 音 的 都 当 俯 伏 敬 拜 金 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21819', '27', '3', '11', '凡 不 俯 伏 敬 拜 的 ， 必 扔 在 烈 火 的 窑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21820', '27', '3', '12', '现 在 有 几 个 犹 大 人 ， 就 是 王 所 派 管 理 巴 比 伦 省 事 务 的 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 ； 王 啊 ， 这 些 人 不 理 你 ， 不 事 奉 你 的 神 ， 也 不 敬 拜 你 所 立 的 金 像 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21821', '27', '3', '13', '当 时 ， 尼 布 甲 尼 撒 冲 冲 大 怒 ， 吩 咐 人 把 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 带 过 来 ， 他 们 就 把 那 些 人 带 到 王 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21822', '27', '3', '14', '尼 布 甲 尼 撒 问 他 们 说 ： “ 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 ， 你 们 不 事 奉 我 的 神 ， 也 不 敬 拜 我 所 立 的 金 像 ， 是 故 意 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21823', '27', '3', '15', '你 们 再 听 见 角 、 笛 、 琵 琶 、 琴 、 瑟 、 笙 ， 和 各 样 乐 器 的 声 音 ， 若 俯 伏 敬 拜 我 所 造 的 像 ， 却 还 可 以 ； 若 不 敬 拜 ， 必 立 时 扔 在 烈 火 的 窑 中 ， 有 何 神 能 救 你 们 脱 离 我 手 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21824', '27', '3', '16', '沙 得 拉 、 米 煞 、 亚 伯 尼 歌 对 王 说 ： “ 尼 布 甲 尼 撒 啊 ， 这 件 事 我 们 不 必 回 答 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21825', '27', '3', '17', '即 便 如 此 ， 我 们 所 事 奉 的 神 能 将 我 们 从 烈 火 的 窑 中 救 出 来 。 王 啊 ， 他 也 必 救 我 们 脱 离 你 的 手 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21826', '27', '3', '18', '即 或 不 然 ， 王 啊 ， 你 当 知 道 我 们 决 不 事 奉 你 的 神 ， 也 不 敬 拜 你 所 立 的 金 像 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21827', '27', '3', '19', '＜ 但 以 理 的 三 个 朋 友 被 判 死 刑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21828', '27', '3', '20', '又 吩 咐 他 军 中 的 几 个 壮 士 ， 将 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 捆 起 来 ， 扔 在 烈 火 的 窑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21829', '27', '3', '21', '这 三 人 穿 着 裤 子 、 内 袍 、 外 衣 ， 和 别 的 衣 服 ， 被 捆 起 来 扔 在 烈 火 的 窑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21830', '27', '3', '22', '因 为 王 命 紧 急 ， 窑 又 甚 热 ， 那 抬 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 的 人 都 被 火 焰 烧 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21831', '27', '3', '23', '沙 得 拉 、 米 煞 、 亚 伯 尼 歌 这 三 个 人 都 被 捆 着 落 在 烈 火 的 窑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21832', '27', '3', '24', '那 时 ， 尼 布 甲 尼 撒 王 惊 奇 ， 急 忙 起 来 ， 对 谋 士 说 ： “ 我 们 捆 起 来 扔 在 火 里 的 不 是 三 个 人 吗 ？ ” 他 们 回 答 王 说 ： “ 王 啊 ， 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21833', '27', '3', '25', '王 说 ： “ 看 哪 ， 我 见 有 四 个 人 ， 并 没 有 捆 绑 ， 在 火 中 游 行 ， 也 没 有 受 伤 ； 那 第 四 个 的 相 貌 好 像 神 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21834', '27', '3', '26', '＜ 三 人 获 释 且 得 高 升 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21835', '27', '3', '27', '那 些 总 督 、 钦 差 、 巡 抚 ， 和 王 的 谋 士 一 同 聚 集 看 这 三 个 人 ， 见 火 无 力 伤 他 们 的 身 体 ， 头 发 也 没 有 烧 焦 ， 衣 裳 也 没 有 变 色 ， 并 没 有 火 燎 的 气 味 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21836', '27', '3', '28', '尼 布 甲 尼 撒 说 ： “ 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 的 神 是 应 当 称 颂 的 ！ 他 差 遣 使 者 救 护 倚 靠 他 的 仆 人 ， 他 们 不 遵 王 命 ， 舍 去 己 身 ， 在 他 们 神 以 外 不 肯 事 奉 敬 拜 别 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21837', '27', '3', '29', '现 在 我 降 旨 ， 无 论 何 方 、 何 国 、 何 族 的 人 ， 谤 讟 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 之 神 的 ， 必 被 凌 迟 ， 他 的 房 屋 必 成 粪 堆 ， 因 为 没 有 别 神 能 这 样 施 行 拯 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21838', '27', '3', '30', '那 时 王 在 巴 比 伦 省 ， 高 升 了 沙 得 拉 、 米 煞 、 亚 伯 尼 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21839', '27', '4', '1', '＜ 尼 布 甲 尼 撒 的 第 二 个 梦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21840', '27', '4', '2', '我 乐 意 将 至 高 的 神 向 我 所 行 的 神 迹 奇 事 宣 扬 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21841', '27', '4', '3', '他 的 神 迹 何 其 大 ！ 他 的 奇 事 何 其 盛 ！ 他 的 国 是 永 远 的 ； 他 的 权 柄 存 到 万 代 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21842', '27', '4', '4', '“ 我 ─ ─ 尼 布 甲 尼 撒 安 居 在 宫 中 ， 平 顺 在 殿 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21843', '27', '4', '5', '我 做 了 一 梦 ， 使 我 惧 怕 。 我 在 床 上 的 思 念 ， 并 脑 中 的 异 象 ， 使 我 惊 惶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21844', '27', '4', '6', '所 以 我 降 旨 召 巴 比 伦 的 一 切 哲 士 到 我 面 前 ， 叫 他 们 把 梦 的 讲 解 告 诉 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21845', '27', '4', '7', '于 是 那 些 术 士 、 用 法 术 的 、 迦 勒 底 人 、 观 兆 的 都 进 来 ， 我 将 那 梦 告 诉 了 他 们 ， 他 们 却 不 能 把 梦 的 讲 解 告 诉 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21846', '27', '4', '8', '末 后 那 照 我 神 的 名 ， 称 为 伯 提 沙 撒 的 但 以 理 来 到 我 面 前 ， 他 里 头 有 圣 神 的 灵 ， 我 将 梦 告 诉 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21847', '27', '4', '9', '‘ 术 士 的 领 袖 伯 提 沙 撒 啊 ， 因 我 知 道 你 里 头 有 圣 神 的 灵 ， 什 么 奥 秘 的 事 都 不 能 使 你 为 难 。 现 在 要 把 我 梦 中 所 见 的 异 象 和 梦 的 讲 解 告 诉 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21848', '27', '4', '10', '“ 我 在 床 上 脑 中 的 异 象 是 这 样 ： 我 看 见 地 当 中 有 一 棵 树 ， 极 其 高 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21849', '27', '4', '11', '那 树 渐 长 ， 而 且 坚 固 ， 高 得 顶 天 ， 从 地 极 都 能 看 见 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21850', '27', '4', '12', '叶 子 华 美 ， 果 子 甚 多 ， 可 作 众 生 的 食 物 ； 田 野 的 走 兽 卧 在 荫 下 ， 天 空 的 飞 鸟 宿 在 枝 上 ； 凡 有 血 气 的 都 从 这 树 得 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21851', '27', '4', '13', '“ 我 在 床 上 脑 中 的 异 象 ， 见 有 一 位 守 望 的 圣 者 从 天 而 降 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21852', '27', '4', '14', '大 声 呼 叫 说 ： ‘ 伐 倒 这 树 ！ 砍 下 枝 子 ！ 摇 掉 叶 子 ！ 抛 散 果 子 ！ 使 走 兽 离 开 树 下 ， 飞 鸟 躲 开 树 枝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21853', '27', '4', '15', '树 丕 却 要 留 在 地 内 ， 用 铁 圈 和 铜 圈 箍 住 ， 在 田 野 的 青 草 中 让 天 露 滴 湿 ， 使 他 与 地 上 的 兽 一 同 吃 草 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21854', '27', '4', '16', '使 他 的 心 改 变 ， 不 如 人 心 ， 给 他 一 个 兽 心 ， 使 他 经 过 七 期 ｛ 期 ： 或 译 年 ； 本 章 同 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21855', '27', '4', '17', '这 是 守 望 者 所 发 的 命 ， 圣 者 所 出 的 令 ， 好 叫 世 人 知 道 至 高 者 在 人 的 国 中 掌 权 ， 要 将 国 赐 与 谁 就 赐 与 谁 ， 或 立 极 卑 微 的 人 执 掌 国 权 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21856', '27', '4', '18', '“ 这 是 我 ─ ─ 尼 布 甲 尼 撒 王 所 做 的 梦 。 伯 提 沙 撒 啊 ， 你 要 说 明 这 梦 的 讲 解 ； 因 为 我 国 中 的 一 切 哲 士 都 不 能 将 梦 的 讲 解 告 诉 我 ， 惟 独 你 能 ， 因 你 里 头 有 圣 神 的 灵 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21857', '27', '4', '19', '＜ 但 以 理 解 梦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21858', '27', '4', '20', '你 所 见 的 树 渐 长 ， 而 且 坚 固 ， 高 得 顶 天 ， 从 地 极 都 能 看 见 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21859', '27', '4', '21', '叶 子 华 美 ， 果 子 甚 多 ， 可 作 众 生 的 食 物 ； 田 野 的 走 兽 住 在 其 下 ； 天 空 的 飞 鸟 宿 在 枝 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21860', '27', '4', '22', '“ 王 啊 ， 这 渐 长 又 坚 固 的 树 就 是 你 。 你 的 威 势 渐 长 及 天 ， 你 的 权 柄 管 到 地 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21861', '27', '4', '23', '王 既 看 见 一 位 守 望 的 圣 者 从 天 而 降 ， 说 ： ‘ 将 这 树 砍 伐 毁 坏 ， 树 丕 却 要 留 在 地 内 ， 用 铁 圈 和 铜 圈 箍 住 ； 在 田 野 的 青 草 中 ， 让 天 露 滴 湿 ， 使 他 与 地 上 的 兽 一 同 吃 草 ， 直 到 经 过 七 期 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21862', '27', '4', '24', '“ 王 啊 ， 讲 解 就 是 这 样 ： 临 到 我 主 我 王 的 事 是 出 于 至 高 者 的 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21863', '27', '4', '25', '你 必 被 赶 出 离 开 世 人 ， 与 野 地 的 兽 同 居 ， 吃 草 如 牛 ， 被 天 露 滴 湿 ， 且 要 经 过 七 期 。 等 你 知 道 至 高 者 在 人 的 国 中 掌 权 ， 要 将 国 赐 与 谁 就 赐 与 谁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21864', '27', '4', '26', '守 望 者 既 吩 咐 存 留 树 丕 ， 等 你 知 道 诸 天 掌 权 ， 以 后 你 的 国 必 定 归 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21865', '27', '4', '27', '王 啊 ， 求 你 悦 纳 我 的 谏 言 ， 以 施 行 公 义 断 绝 罪 过 ， 以 怜 悯 穷 人 除 掉 罪 孽 ， 或 者 你 的 平 安 可 以 延 长 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21866', '27', '4', '28', '这 事 都 临 到 尼 布 甲 尼 撒 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21867', '27', '4', '29', '过 了 十 二 个 月 ， 他 游 行 在 巴 比 伦 王 宫 里 ｛ 原 文 是 上 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21868', '27', '4', '30', '他 说 ： “ 这 大 巴 比 伦 不 是 我 用 大 能 大 力 建 为 京 都 ， 要 显 我 威 严 的 荣 耀 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21869', '27', '4', '31', '这 话 在 王 口 中 尚 未 说 完 ， 有 声 音 从 天 降 下 ， 说 ： “ 尼 布 甲 尼 撒 王 啊 ， 有 话 对 你 说 ， 你 的 国 位 离 开 你 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21870', '27', '4', '32', '你 必 被 赶 出 离 开 世 人 ， 与 野 地 的 兽 同 居 ， 吃 草 如 牛 ， 且 要 经 过 七 期 。 等 你 知 道 至 高 者 在 人 的 国 中 掌 权 ， 要 将 国 赐 与 谁 就 赐 与 谁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21871', '27', '4', '33', '当 时 这 话 就 应 验 在 尼 布 甲 尼 撒 的 身 上 ， 他 被 赶 出 离 开 世 人 ， 吃 草 如 牛 ， 身 被 天 露 滴 湿 ， 头 发 长 长 ， 好 像 鹰 毛 ； 指 甲 长 长 ， 如 同 鸟 爪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21872', '27', '4', '34', '＜ 尼 布 甲 尼 撒 颂 赞 神 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21873', '27', '4', '35', '世 上 所 有 的 居 民 都 算 为 虚 无 ； 在 天 上 的 万 军 和 世 上 的 居 民 中 ， 他 都 凭 自 己 的 意 旨 行 事 。 无 人 能 拦 住 他 手 ， 或 问 他 说 ， 你 做 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21874', '27', '4', '36', '那 时 ， 我 的 聪 明 复 归 于 我 ， 为 我 国 的 荣 耀 、 威 严 ， 和 光 耀 也 都 复 归 于 我 ； 并 且 我 的 谋 士 和 大 臣 也 来 朝 见 我 。 我 又 得 坚 立 在 国 位 上 ， 至 大 的 权 柄 加 增 于 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21875', '27', '4', '37', '现 在 我 ─ ─ 尼 布 甲 尼 撒 赞 美 、 尊 崇 、 恭 敬 天 上 的 王 ； 因 为 他 所 做 的 全 都 诚 实 ， 他 所 行 的 也 都 公 平 。 那 行 动 骄 傲 的 ， 他 能 降 为 卑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21876', '27', '5', '1', '＜ 伯 沙 撒 王 的 宴 会 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21877', '27', '5', '2', '伯 沙 撒 欢 饮 之 间 ， 吩 咐 人 将 他 父 ｛ 或 译 ： 祖 ； 下 同 ｝ 尼 布 甲 尼 撒 从 耶 路 撒 冷 殿 中 所 掠 的 金 银 器 皿 拿 来 ， 王 与 大 臣 、 皇 后 、 妃 嫔 好 用 这 器 皿 饮 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21878', '27', '5', '3', '于 是 他 们 把 耶 路 撒 冷 神 殿 库 房 中 所 掠 的 金 器 皿 拿 来 ， 王 和 大 臣 、 皇 后 、 妃 嫔 就 用 这 器 皿 饮 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21879', '27', '5', '4', '他 们 饮 酒 ， 赞 美 金 、 银 、 铜 、 铁 、 木 、 石 所 造 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21880', '27', '5', '5', '当 时 ， 忽 有 人 的 指 头 显 出 ， 在 王 宫 与 灯 台 相 对 的 粉 墙 上 写 字 。 王 看 见 写 字 的 指 头');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21881', '27', '5', '6', '就 变 了 脸 色 ， 心 意 惊 惶 ， 腰 骨 好 像 脱 节 ， 双 膝 彼 此 相 碰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21882', '27', '5', '7', '大 声 吩 咐 将 用 法 术 的 和 迦 勒 底 人 并 观 兆 的 领 进 来 ， 对 巴 比 伦 的 哲 士 说 ， 谁 能 读 这 文 字 ， 把 讲 解 告 诉 我 ， 他 必 身 穿 紫 袍 ， 项 带 金 链 ， 在 我 国 中 位 列 第 三 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21883', '27', '5', '8', '于 是 王 的 一 切 哲 士 都 进 来 ， 却 不 能 读 那 文 字 ， 也 不 能 把 讲 解 告 诉 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21884', '27', '5', '9', '伯 沙 撒 王 就 甚 惊 惶 ， 脸 色 改 变 ， 他 的 大 臣 也 都 惊 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21885', '27', '5', '10', '太 后 ｛ 或 译 ： 皇 后 ； 下 同 ｝ 因 王 和 他 大 臣 所 说 的 话 ， 就 进 入 宴 宫 ， 说 ： “ 愿 王 万 岁 ！ 你 心 意 不 要 惊 惶 ， 脸 面 不 要 变 色 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21886', '27', '5', '11', '在 你 国 中 有 一 人 ， 他 里 头 有 圣 神 的 灵 ， 你 父 在 世 的 日 子 ， 这 人 心 中 光 明 ， 又 有 聪 明 智 慧 ， 好 像 神 的 智 慧 。 你 父 尼 布 甲 尼 撒 王 ， 就 是 王 的 父 ， 立 他 为 术 士 、 用 法 术 的 ， 和 迦 勒 底 人 ， 并 观 兆 的 领 袖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21887', '27', '5', '12', '在 他 里 头 有 美 好 的 灵 性 ， 又 有 知 识 聪 明 ， 能 圆 梦 ， 释 谜 语 ， 解 疑 惑 。 这 人 名 叫 但 以 理 ， 尼 布 甲 尼 撒 王 又 称 他 为 伯 提 沙 撒 ， 现 在 可 以 召 他 来 ， 他 必 解 明 这 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21888', '27', '5', '13', '＜ 但 以 理 解 释 墙 上 的 字 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21889', '27', '5', '14', '我 听 说 你 里 头 有 神 的 灵 ， 心 中 光 明 ， 又 有 聪 明 和 美 好 的 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21890', '27', '5', '15', '现 在 哲 士 和 用 法 术 的 都 领 到 我 面 前 ， 为 叫 他 们 读 这 文 字 ， 把 讲 解 告 诉 我 ， 无 奈 他 们 都 不 能 把 讲 解 说 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21891', '27', '5', '16', '我 听 说 你 善 于 讲 解 ， 能 解 疑 惑 ； 现 在 你 若 能 读 这 文 字 ， 把 讲 解 告 诉 我 ， 就 必 身 穿 紫 袍 ， 项 戴 金 链 ， 在 我 国 中 位 列 第 三 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21892', '27', '5', '17', '但 以 理 在 王 面 前 回 答 说 ： “ 你 的 赠 品 可 以 归 你 自 己 ， 你 的 赏 赐 可 以 归 给 别 人 ； 我 却 要 为 王 读 这 文 字 ， 把 讲 解 告 诉 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21893', '27', '5', '18', '王 啊 ， 至 高 的 神 曾 将 国 位 、 大 权 、 荣 耀 、 威 严 赐 与 你 父 尼 布 甲 尼 撒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21894', '27', '5', '19', '因 神 所 赐 他 的 大 权 ， 各 方 、 各 国 、 各 族 的 人 都 在 他 面 前 战 兢 恐 惧 。 他 可 以 随 意 生 杀 ， 随 意 升 降 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21895', '27', '5', '20', '但 他 心 高 气 傲 ， 灵 也 刚 愎 ， 甚 至 行 事 狂 傲 ， 就 被 革 去 王 位 ， 夺 去 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21896', '27', '5', '21', '他 被 赶 出 离 开 世 人 ， 他 的 心 变 如 兽 心 ， 与 野 驴 同 居 ， 吃 草 如 牛 ， 身 被 天 露 滴 湿 ， 等 他 知 道 至 高 的 神 在 人 的 国 中 掌 权 ， 凭 自 己 的 意 旨 立 人 治 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21897', '27', '5', '22', '伯 沙 撒 啊 ， 你 是 他 的 儿 子 ｛ 或 译 ： 孙 子 ｝ ， 你 虽 知 道 这 一 切 ， 你 心 仍 不 自 卑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21898', '27', '5', '23', '竟 向 天 上 的 主 自 高 ， 使 人 将 他 殿 中 的 器 皿 拿 到 你 面 前 ， 你 和 大 臣 、 皇 后 、 妃 嫔 用 这 器 皿 饮 酒 。 你 又 赞 美 那 不 能 看 、 不 能 听 、 无 知 无 识 、 金 、 银 、 铜 、 铁 、 木 、 石 所 造 的 神 ， 却 没 有 将 荣 耀 归 与 那 手 中 有 你 气 息 ， 管 理 你 一 切 行 动 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21899', '27', '5', '24', '因 此 从 神 那 里 显 出 指 头 来 写 这 文 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21900', '27', '5', '25', '“ 所 写 的 文 字 是 ： ‘ 弥 尼 ， 弥 尼 ， 提 客 勒 ， 乌 法 珥 新 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21901', '27', '5', '26', '讲 解 是 这 样 ： 弥 尼 ， 就 是 神 已 经 数 算 你 国 的 年 日 到 此 完 毕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21902', '27', '5', '27', '提 客 勒 ， 就 是 你 被 称 在 天 平 里 ， 显 出 你 的 亏 欠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21903', '27', '5', '28', '毗 勒 斯 ｛ 与 乌 法 珥 新 同 义 ｝ ， 就 是 你 的 国 分 裂 ， 归 与 米 底 亚 人 和 波 斯 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21904', '27', '5', '29', '伯 沙 撒 下 令 ， 人 就 把 紫 袍 给 但 以 理 穿 上 ， 把 金 链 给 他 戴 在 颈 项 上 ， 又 传 令 使 他 在 国 中 位 列 第 三 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21905', '27', '5', '30', '当 夜 ， 迦 勒 底 王 伯 沙 撒 被 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21906', '27', '5', '31', '米 底 亚 人 大 流 士 年 六 十 二 岁 ， 取 了 迦 勒 底 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21907', '27', '6', '1', '＜ 但 以 理 在 狮 子 坑 中 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21908', '27', '6', '2', '又 在 他 们 以 上 立 总 长 三 人 （ 但 以 理 在 其 中 ） ， 使 总 督 在 他 们 三 人 面 前 回 覆 事 务 ， 免 得 王 受 亏 损 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21909', '27', '6', '3', '因 这 但 以 理 有 美 好 的 灵 性 ， 所 以 显 然 超 乎 其 余 的 总 长 和 总 督 ， 王 又 想 立 他 治 理 通 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21910', '27', '6', '4', '那 时 ， 总 长 和 总 督 寻 找 但 以 理 误 国 的 把 柄 ， 为 要 参 他 ； 只 是 找 不 着 他 的 错 误 过 失 ， 因 他 忠 心 办 事 ， 毫 无 错 误 过 失 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21911', '27', '6', '5', '那 些 人 便 说 ： “ 我 们 要 找 参 这 但 以 理 的 把 柄 ， 除 非 在 他 神 的 律 法 中 就 寻 不 着 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21912', '27', '6', '6', '于 是 ， 总 长 和 总 督 纷 纷 聚 集 来 见 王 ， 说 ： “ 愿 大 流 士 王 万 岁 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21913', '27', '6', '7', '国 中 的 总 长 、 钦 差 、 总 督 、 谋 士 ， 和 巡 抚 彼 此 商 议 ， 要 立 一 条 坚 定 的 禁 令 ｛ 或 译 ： 求 王 下 旨 要 立 一 条 … … ｝ ， 三 十 日 内 ， 不 拘 何 人 ， 若 在 王 以 外 ， 或 向 神 或 向 人 求 什 么 ， 就 必 扔 在 狮 子 坑 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21914', '27', '6', '8', '王 啊 ， 现 在 求 你 立 这 禁 令 ， 加 盖 玉 玺 ， 使 禁 令 决 不 更 改 ； 照 米 底 亚 和 波 斯 人 的 例 是 不 可 更 改 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21915', '27', '6', '9', '于 是 大 流 士 王 立 这 禁 令 ， 加 盖 玉 玺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21916', '27', '6', '10', '但 以 理 知 道 这 禁 令 盖 了 玉 玺 ， 就 到 自 己 家 里 （ 他 楼 上 的 窗 户 开 向 耶 路 撒 冷 ） ， 一 日 三 次 ， 双 膝 跪 在 他 神 面 前 ， 祷 告 感 谢 ， 与 素 常 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21917', '27', '6', '11', '那 些 人 就 纷 纷 聚 集 ， 见 但 以 理 在 他 神 面 前 祈 祷 恳 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21918', '27', '6', '12', '他 们 便 进 到 王 前 ， 提 王 的 禁 令 ， 说 ： “ 王 啊 ， 三 十 日 内 不 拘 何 人 ， 若 在 王 以 外 ， 或 向 神 或 向 人 求 什 么 ， 必 被 扔 在 狮 子 坑 中 。 王 不 是 在 这 禁 令 上 盖 了 玉 玺 吗 ？ ” 王 回 答 说 ： “ 实 有 这 事 ， 照 米 底 亚 和 波 斯 人 的 例 是 不 可 更 改 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21919', '27', '6', '13', '他 们 对 王 说 ： “ 王 啊 ， 那 被 掳 之 犹 大 人 中 的 但 以 理 不 理 你 ， 也 不 遵 你 盖 了 玉 玺 的 禁 令 ， 他 竟 一 日 三 次 祈 祷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21920', '27', '6', '14', '王 听 见 这 话 ， 就 甚 愁 烦 ， 一 心 要 救 但 以 理 ， 筹 划 解 救 他 ， 直 到 日 落 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21921', '27', '6', '15', '那 些 人 就 纷 纷 聚 集 来 见 王 ， 说 ： “ 王 啊 ， 当 知 道 米 底 亚 人 和 波 斯 人 有 例 ， 凡 王 所 立 的 禁 令 和 律 例 都 不 可 更 改 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21922', '27', '6', '16', '王 下 令 ， 人 就 把 但 以 理 带 来 ， 扔 在 狮 子 坑 中 。 王 对 但 以 理 说 ： “ 你 所 常 事 奉 的 神 ， 他 必 救 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21923', '27', '6', '17', '有 人 搬 石 头 放 在 坑 口 ， 王 用 自 己 的 玺 和 大 臣 的 印 ， 封 闭 那 坑 ， 使 惩 办 但 以 理 的 事 毫 无 更 改 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21924', '27', '6', '18', '王 回 宫 ， 终 夜 禁 食 ， 无 人 拿 乐 器 到 他 面 前 ， 并 且 睡 不 着 觉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21925', '27', '6', '19', '次 日 黎 明 ， 王 就 起 来 ， 急 忙 往 狮 子 坑 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21926', '27', '6', '20', '临 近 坑 边 ， 哀 声 呼 叫 但 以 理 ， 对 但 以 理 说 ： “ 永 生 神 的 仆 人 但 以 理 啊 ， 你 所 常 事 奉 的 神 能 救 你 脱 离 狮 子 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21927', '27', '6', '21', '但 以 理 对 王 说 ： “ 愿 王 万 岁 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21928', '27', '6', '22', '我 的 神 差 遣 使 者 ， 封 住 狮 子 的 口 ， 叫 狮 子 不 伤 我 ； 因 我 在 神 面 前 无 辜 ， 我 在 王 面 前 也 没 有 行 过 亏 损 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21929', '27', '6', '23', '王 就 甚 喜 乐 ， 吩 咐 人 将 但 以 理 从 坑 里 系 上 来 。 于 是 但 以 理 从 坑 里 被 系 上 来 ， 身 上 毫 无 伤 损 ， 因 为 信 靠 他 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21930', '27', '6', '24', '王 下 令 ， 人 就 把 那 些 控 告 但 以 理 的 人 ， 连 他 们 的 妻 子 儿 女 都 带 来 ， 扔 在 狮 子 坑 中 。 他 们 还 没 有 到 坑 底 ， 狮 子 就 抓 住 ｛ 原 文 是 胜 了 ｝ 他 们 ， 咬 碎 他 们 的 骨 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21931', '27', '6', '25', '那 时 ， 大 流 士 王 传 旨 ， 晓 谕 住 在 全 地 各 方 、 各 国 、 各 族 的 人 说 ： “ 愿 你 们 大 享 平 安 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21932', '27', '6', '26', '现 在 我 降 旨 晓 谕 我 所 统 辖 的 全 国 人 民 ， 要 在 但 以 理 的 神 面 前 ， 战 兢 恐 惧 。 因 为 他 是 永 远 长 存 的 活 神 ， 他 的 国 永 不 败 坏 ； 他 的 权 柄 永 存 无 极 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21933', '27', '6', '27', '他 护 庇 人 ， 搭 救 人 ， 在 天 上 地 下 施 行 神 迹 奇 事 ， 救 了 但 以 理 脱 离 狮 子 的 口 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21934', '27', '6', '28', '如 此 ， 这 但 以 理 ， 当 大 流 士 王 在 位 的 时 候 和 波 斯 王 塞 鲁 士 在 位 的 时 候 ， 大 享 亨 通 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21935', '27', '7', '1', '＜ 但 以 理 叙 述 异 象 （ 但   7 : 1 - 1 2 : 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21936', '27', '7', '2', '但 以 理 说 ： 我 夜 里 见 异 象 ， 看 见 天 的 四 风 陡 起 ， 刮 在 大 海 之 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21937', '27', '7', '3', '有 四 个 大 兽 从 海 中 上 来 ， 形 状 各 有 不 同 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21938', '27', '7', '4', '头 一 个 像 狮 子 ， 有 鹰 的 翅 膀 ； 我 正 观 看 的 时 候 ， 兽 的 翅 膀 被 拔 去 ， 兽 从 地 上 得 立 起 来 ， 用 两 脚 站 立 ， 像 人 一 样 ， 又 得 了 人 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21939', '27', '7', '5', '又 有 一 兽 如 熊 ， 就 是 第 二 兽 ， 旁 跨 而 坐 ， 口 齿 内 衔 着 三 根 肋 骨 。 有 吩 咐 这 兽 的 说 ： “ 起 来 吞 吃 多 肉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21940', '27', '7', '6', '此 后 我 观 看 ， 又 有 一 兽 如 豹 ， 背 上 有 鸟 的 四 个 翅 膀 ； 这 兽 有 四 个 头 ， 又 得 了 权 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21941', '27', '7', '7', '其 后 我 在 夜 间 的 异 象 中 观 看 ， 见 第 四 兽 甚 是 可 怕 ， 极 其 强 壮 ， 大 有 力 量 ， 有 大 铁 牙 ， 吞 吃 嚼 碎 ， 所 剩 下 的 用 脚 践 踏 。 这 兽 与 前 三 兽 大 不 相 同 ， 头 有 十 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21942', '27', '7', '8', '我 正 观 看 这 些 角 ， 见 其 中 又 长 起 一 个 小 角 ； 先 前 的 角 中 有 三 角 在 这 角 前 ， 连 根 被 它 拔 出 来 。 这 角 有 眼 ， 像 人 的 眼 ， 有 口 说 夸 大 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21943', '27', '7', '9', '＜ 永 存 者 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21944', '27', '7', '10', '从 他 面 前 有 火 ， 像 河 发 出 ； 事 奉 他 的 有 千 千 ， 在 他 面 前 侍 立 的 有 万 万 ； 他 坐 着 要 行 审 判 ， 案 卷 都 展 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21945', '27', '7', '11', '那 时 我 观 看 ， 见 那 兽 因 小 角 说 夸 大 话 的 声 音 被 杀 ， 身 体 损 坏 ， 扔 在 火 中 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21946', '27', '7', '12', '其 余 的 兽 ， 权 柄 都 被 夺 去 ， 生 命 却 仍 存 留 ， 直 到 所 定 的 时 候 和 日 期 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21947', '27', '7', '13', '我 在 夜 间 的 异 象 中 观 看 ， 见 有 一 位 像 人 子 的 ， 驾 着 天 云 而 来 ， 被 领 到 亘 古 常 在 者 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21948', '27', '7', '14', '得 了 权 柄 、 荣 耀 、 国 度 ， 使 各 方 、 各 国 、 各 族 的 人 都 事 奉 他 。 他 的 权 柄 是 永 远 的 ， 不 能 废 去 ； 他 的 国 必 不 败 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21949', '27', '7', '15', '＜ 解 释 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21950', '27', '7', '16', '我 就 近 一 位 侍 立 者 ， 问 他 这 一 切 的 真 情 。 他 就 告 诉 我 ， 将 那 事 的 讲 解 给 我 说 明 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21951', '27', '7', '17', '这 四 个 大 兽 就 是 四 王 将 要 在 世 上 兴 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21952', '27', '7', '18', '然 而 ， 至 高 者 的 圣 民 ， 必 要 得 国 享 受 ， 直 到 永 永 远 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21953', '27', '7', '19', '那 时 我 愿 知 道 第 四 兽 的 真 情 ， 它 为 何 与 那 三 兽 的 真 情 大 不 相 同 ， 甚 是 可 怕 ， 有 铁 牙 铜 爪 ， 吞 吃 嚼 碎 ， 所 剩 下 的 用 脚 践 踏 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21954', '27', '7', '20', '头 有 十 角 和 那 另 长 的 一 角 ， 在 这 角 前 有 三 角 被 它 打 落 。 这 角 有 眼 ， 有 说 夸 大 话 的 口 ， 形 状 强 横 ， 过 于 它 的 同 类 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21955', '27', '7', '21', '我 观 看 ， 见 这 角 与 圣 民 争 战 ， 胜 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21956', '27', '7', '22', '直 到 亘 古 常 在 者 来 给 至 高 者 的 圣 民 伸 冤 ， 圣 民 得 国 的 时 候 就 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21957', '27', '7', '23', '那 侍 立 者 这 样 说 ： 第 四 兽 就 是 世 上 必 有 的 第 四 国 ， 与 一 切 国 大 不 相 同 ， 必 吞 吃 全 地 ， 并 且 践 踏 嚼 碎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21958', '27', '7', '24', '至 于 那 十 角 ， 就 是 从 这 国 中 必 兴 起 的 十 王 ， 后 来 又 兴 起 一 王 ， 与 先 前 的 不 同 ； 他 必 制 伏 三 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21959', '27', '7', '25', '他 必 向 至 高 者 说 夸 大 的 话 ， 必 折 磨 至 高 者 的 圣 民 ， 必 想 改 变 节 期 和 律 法 。 圣 民 必 交 付 他 手 一 载 、 二 载 、 半 载 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21960', '27', '7', '26', '然 而 ， 审 判 者 必 坐 着 行 审 判 ； 他 的 权 柄 必 被 夺 去 ， 毁 坏 ， 灭 绝 ， 一 直 到 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21961', '27', '7', '27', '国 度 、 权 柄 ， 和 天 下 诸 国 的 大 权 必 赐 给 至 高 者 的 圣 民 。 他 的 国 是 永 远 的 ； 一 切 掌 权 的 都 必 事 奉 他 ， 顺 从 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21962', '27', '7', '28', '那 事 至 此 完 毕 。 至 于 我 ─ ─ 但 以 理 ， 心 中 甚 是 惊 惶 ， 脸 色 也 改 变 了 ， 却 将 那 事 存 记 在 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21963', '27', '8', '1', '＜ 公 绵 羊 、 公 山 羊 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21964', '27', '8', '2', '我 见 了 异 象 的 时 候 ， 我 以 为 在 以 拦 省 书 珊 城 ｛ 或 译 ： 宫 ｝ 中 ； 我 见 异 象 又 如 在 乌 莱 河 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21965', '27', '8', '3', '我 举 目 观 看 ， 见 有 双 角 的 公 绵 羊 站 在 河 边 ， 两 角 都 高 。 这 角 高 过 那 角 ， 更 高 的 是 后 长 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21966', '27', '8', '4', '我 见 那 公 绵 羊 往 西 、 往 北 、 往 南 抵 触 。 兽 在 它 面 前 都 站 立 不 住 ， 也 没 有 能 救 护 脱 离 它 手 的 ； 但 它 任 意 而 行 ， 自 高 自 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21967', '27', '8', '5', '我 正 思 想 的 时 候 ， 见 有 一 只 公 山 羊 从 西 而 来 ， 遍 行 全 地 ， 脚 不 沾 尘 。 这 山 羊 两 眼 当 中 有 一 非 常 的 角 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21968', '27', '8', '6', '它 往 我 所 看 见 、 站 在 河 边 有 双 角 的 公 绵 羊 那 里 去 ， 大 发 忿 怒 ， 向 它 直 闯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21969', '27', '8', '7', '我 见 公 山 羊 就 近 公 绵 羊 ， 向 它 发 烈 怒 ， 抵 触 它 ， 折 断 它 的 两 角 。 绵 羊 在 它 面 前 站 立 不 住 ； 它 将 绵 羊 触 倒 在 地 ， 用 脚 践 踏 ， 没 有 能 救 绵 羊 脱 离 它 手 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21970', '27', '8', '8', '这 山 羊 极 其 自 高 自 大 ， 正 强 盛 的 时 候 ， 那 大 角 折 断 了 ， 又 在 角 根 上 向 天 的 四 方 ｛ 原 文 是 风 ｝ 长 出 四 个 非 常 的 角 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21971', '27', '8', '9', '四 角 之 中 有 一 角 长 出 一 个 小 角 ， 向 南 、 向 东 、 向 荣 美 之 地 ， 渐 渐 成 为 强 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21972', '27', '8', '10', '它 渐 渐 强 大 ， 高 及 天 象 ， 将 些 天 象 和 星 宿 抛 落 在 地 ， 用 脚 践 踏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21973', '27', '8', '11', '并 且 它 自 高 自 大 ， 以 为 高 及 天 象 之 君 ； 除 掉 常 献 给 君 的 燔 祭 ， 毁 坏 君 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21974', '27', '8', '12', '因 罪 过 的 缘 故 ， 有 军 旅 和 常 献 的 燔 祭 交 付 它 。 它 将 真 理 抛 在 地 上 ， 任 意 而 行 ， 无 不 顺 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21975', '27', '8', '13', '我 听 见 有 一 位 圣 者 说 话 ， 又 有 一 位 圣 者 问 那 说 话 的 圣 者 说 ： “ 这 除 掉 常 献 的 燔 祭 和 施 行 毁 坏 的 罪 过 ， 将 圣 所 与 军 旅 ｛ 或 译 ： 以 色 列 的 军 ｝ 践 踏 的 异 象 ， 要 到 几 时 才 应 验 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21976', '27', '8', '14', '他 对 我 说 ： “ 到 二 千 三 百 日 ， 圣 所 就 必 洁 净 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21977', '27', '8', '15', '＜ 天 使 加 百 列 解 释 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21978', '27', '8', '16', '我 又 听 见 乌 莱 河 两 岸 中 有 人 声 呼 叫 说 ： “ 加 百 列 啊 ， 要 使 此 人 明 白 这 异 象 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21979', '27', '8', '17', '他 便 来 到 我 所 站 的 地 方 。 他 一 来 ， 我 就 惊 慌 俯 伏 在 地 ； 他 对 我 说 ： “ 人 子 啊 ， 你 要 明 白 ， 因 为 这 是 关 乎 末 后 的 异 象 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21980', '27', '8', '18', '他 与 我 说 话 的 时 候 ， 我 面 伏 在 地 沉 睡 ； 他 就 摸 我 ， 扶 我 站 起 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21981', '27', '8', '19', '说 ： “ 我 要 指 示 你 恼 怒 临 完 必 有 的 事 ， 因 为 这 是 关 乎 末 后 的 定 期 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21982', '27', '8', '20', '你 所 看 见 双 角 的 公 绵 羊 ， 就 是 米 底 亚 和 波 斯 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21983', '27', '8', '21', '那 公 山 羊 就 是 希 腊 王 ｛ 希 腊 ： 原 文 是 雅 完 ； 下 同 ｝ ； 两 眼 当 中 的 大 角 就 是 头 一 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21984', '27', '8', '22', '至 于 那 折 断 了 的 角 ， 在 其 根 上 又 长 出 四 角 ， 这 四 角 就 是 四 国 ， 必 从 这 国 里 兴 起 来 ， 只 是 权 势 都 不 及 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21985', '27', '8', '23', '这 四 国 末 时 ， 犯 法 的 人 罪 恶 满 盈 ， 必 有 一 王 兴 起 ， 面 貌 凶 恶 ， 能 用 双 关 的 诈 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21986', '27', '8', '24', '他 的 权 柄 必 大 ， 却 不 是 因 自 己 的 能 力 ； 他 必 行 非 常 的 毁 灭 ， 事 情 顺 利 ， 任 意 而 行 ； 又 必 毁 灭 有 能 力 的 和 圣 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21987', '27', '8', '25', '他 用 权 术 成 就 手 中 的 诡 计 ， 心 里 自 高 自 大 ， 在 人 坦 然 无 备 的 时 候 ， 毁 灭 多 人 ； 又 要 站 起 来 攻 击 万 君 之 君 ， 至 终 却 非 因 人 手 而 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21988', '27', '8', '26', '所 说 二 千 三 百 日 的 异 象 是 真 的 ， 但 你 要 将 这 异 象 封 住 ， 因 为 关 乎 后 来 许 多 的 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21989', '27', '8', '27', '于 是 我 ─ ─ 但 以 理 昏 迷 不 醒 ， 病 了 数 日 ， 然 后 起 来 办 理 王 的 事 务 。 我 因 这 异 象 惊 奇 ， 却 无 人 能 明 白 其 中 的 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21990', '27', '9', '1', '＜ 但 以 理 为 同 胞 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21991', '27', '9', '2', '就 是 他 在 位 第 一 年 ， 我 ─ ─ 但 以 理 从 书 上 得 知 耶 和 华 的 话 临 到 先 知 耶 利 米 ， 论 耶 路 撒 冷 荒 凉 的 年 数 ， 七 十 年 为 满 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21992', '27', '9', '3', '我 便 禁 食 ， 披 麻 蒙 灰 ， 定 意 向 主 神 祈 祷 恳 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21993', '27', '9', '4', '我 向 耶 和 华 ─ ─ 我 的 神 祈 祷 、 认 罪 ， 说 ： “ 主 啊 ， 大 而 可 畏 的 神 ， 向 爱 主 、 守 主 诫 命 的 人 守 约 施 慈 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21994', '27', '9', '5', '我 们 犯 罪 作 孽 ， 行 恶 叛 逆 ， 偏 离 你 的 诫 命 典 章 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21995', '27', '9', '6', '没 有 听 从 你 仆 人 众 先 知 奉 你 名 向 我 们 君 王 、 首 领 、 列 祖 ， 和 国 中 一 切 百 姓 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21996', '27', '9', '7', '主 啊 ， 你 是 公 义 的 ， 我 们 是 脸 上 蒙 羞 的 ； 因 我 们 犹 大 人 和 耶 路 撒 冷 的 居 民 ， 并 以 色 列 众 人 ， 或 在 近 处 ， 或 在 远 处 ， 被 你 赶 到 各 国 的 人 ， 都 得 罪 了 你 ， 正 如 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21997', '27', '9', '8', '主 啊 ， 我 们 和 我 们 的 君 王 、 首 领 、 列 祖 因 得 罪 了 你 ， 就 都 脸 上 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21998', '27', '9', '9', '主 ─ ─ 我 们 的 神 是 怜 悯 饶 恕 人 的 ， 我 们 却 违 背 了 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('21999', '27', '9', '10', '也 没 有 听 从 耶 和 华 ─ ─ 我 们 神 的 话 ， 没 有 遵 行 他 藉 仆 人 众 先 知 向 我 们 所 陈 明 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22000', '27', '9', '11', '以 色 列 众 人 都 犯 了 你 的 律 法 ， 偏 行 ， 不 听 从 你 的 话 ； 因 此 ， 在 你 仆 人 摩 西 律 法 上 所 写 的 咒 诅 和 誓 言 都 倾 在 我 们 身 上 ， 因 我 们 得 罪 了 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22001', '27', '9', '12', '他 使 大 灾 祸 临 到 我 们 ， 成 就 了 警 戒 我 们 和 审 判 我 们 官 长 的 话 ； 原 来 在 普 天 之 下 未 曾 行 过 像 在 耶 路 撒 冷 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22002', '27', '9', '13', '这 一 切 灾 祸 临 到 我 们 身 上 是 照 摩 西 律 法 上 所 写 的 ， 我 们 却 没 有 求 耶 和 华 ─ ─ 我 们 神 的 恩 典 ， 使 我 们 回 头 离 开 罪 孽 ， 明 白 你 的 真 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22003', '27', '9', '14', '所 以 耶 和 华 留 意 使 这 灾 祸 临 到 我 们 身 上 ， 因 为 耶 和 华 ─ ─ 我 们 的 神 在 他 所 行 的 事 上 都 是 公 义 ； 我 们 并 没 有 听 从 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22004', '27', '9', '15', '主 ─ ─ 我 们 的 神 啊 ， 你 曾 用 大 能 的 手 领 你 的 子 民 出 埃 及 地 ， 使 自 己 得 了 名 ， 正 如 今 日 一 样 。 我 们 犯 了 罪 ， 作 了 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22005', '27', '9', '16', '主 啊 ， 求 你 按 你 的 大 仁 大 义 ， 使 你 的 怒 气 和 忿 怒 转 离 你 的 城 耶 路 撒 冷 ， 就 是 你 的 圣 山 。 耶 路 撒 冷 和 你 的 子 民 ， 因 我 们 的 罪 恶 和 我 们 列 祖 的 罪 孽 被 四 围 的 人 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22006', '27', '9', '17', '我 们 的 神 啊 ， 现 在 求 你 垂 听 仆 人 的 祈 祷 恳 求 ， 为 自 己 使 脸 光 照 你 荒 凉 的 圣 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22007', '27', '9', '18', '我 的 神 啊 ， 求 你 侧 耳 而 听 ， 睁 眼 而 看 ， 眷 顾 我 们 荒 凉 之 地 和 称 为 你 名 下 的 城 。 我 们 在 你 面 前 恳 求 ， 原 不 是 因 自 己 的 义 ， 乃 因 你 的 大 怜 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22008', '27', '9', '19', '求 主 垂 听 ， 求 主 赦 免 ， 求 主 应 允 而 行 ， 为 你 自 己 不 要 迟 延 。 我 的 神 啊 ， 因 这 城 和 这 民 都 是 称 为 你 名 下 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22009', '27', '9', '20', '＜ 加 百 列 解 释 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22010', '27', '9', '21', '我 正 祷 告 的 时 候 ， 先 前 在 异 象 中 所 见 的 那 位 加 百 列 ， 奉 命 迅 速 飞 来 ， 约 在 献 晚 祭 的 时 候 ， 按 手 在 我 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22011', '27', '9', '22', '他 指 教 我 说 ： “ 但 以 理 啊 ， 现 在 我 出 来 要 使 你 有 智 慧 ， 有 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22012', '27', '9', '23', '你 初 恳 求 的 时 候 ， 就 发 出 命 令 ， 我 来 告 诉 你 ， 因 你 大 蒙 眷 爱 ； 所 以 你 要 思 想 明 白 这 以 下 的 事 和 异 象 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22013', '27', '9', '24', '“ 为 你 本 国 之 民 和 你 圣 城 ， 已 经 定 了 七 十 个 七 。 要 止 住 罪 过 ， 除 净 罪 恶 ， 赎 尽 罪 孽 ， 引 进 ｛ 或 译 ： 彰 显 ｝ 永 义 ， 封 住 异 象 和 预 言 ， 并 膏 至 圣 者 ｛ 者 ： 或 译 所 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22014', '27', '9', '25', '你 当 知 道 ， 当 明 白 ， 从 出 令 重 新 建 造 耶 路 撒 冷 ， 直 到 有 受 膏 君 的 时 候 ， 必 有 七 个 七 和 六 十 二 个 七 。 正 在 艰 难 的 时 候 ， 耶 路 撒 冷 城 连 街 带 濠 都 必 重 新 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22015', '27', '9', '26', '过 了 六 十 二 个 七 ， 那 ｛ 或 译 ： 有 ｝ 受 膏 者 必 被 剪 除 ， 一 无 所 有 ； 必 有 一 王 的 民 来 毁 灭 这 城 和 圣 所 ， 至 终 必 如 洪 水 冲 没 。 必 有 争 战 ， 一 直 到 底 ， 荒 凉 的 事 已 经 定 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22016', '27', '9', '27', '一 七 之 内 ， 他 必 与 许 多 人 坚 定 盟 约 ； 一 七 之 半 ， 他 必 使 祭 祀 与 供 献 止 息 。 那 行 毁 坏 可 憎 的 ｛ 或 译 ： 使 地 荒 凉 的 ｝ 如 飞 而 来 ， 并 且 有 忿 怒 倾 在 那 行 毁 坏 的 身 上 ｛ 或 译 ： 倾 在 那 荒 凉 之 地 ｝ ， 直 到 所 定 的 结 局 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22017', '27', '10', '1', '＜ 底 格 里 斯 大 河 边 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22018', '27', '10', '2', '当 那 时 ， 我 ─ ─ 但 以 理 悲 伤 了 三 个 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22019', '27', '10', '3', '美 味 我 没 有 吃 ， 酒 肉 没 有 入 我 的 口 ， 也 没 有 用 油 抹 我 的 身 ， 直 到 满 了 三 个 七 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22020', '27', '10', '4', '正 月 二 十 四 日 ， 我 在 底 格 里 斯 大 河 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22021', '27', '10', '5', '举 目 观 看 ， 见 有 一 人 身 穿 细 麻 衣 ， 腰 束 乌 法 精 金 带 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22022', '27', '10', '6', '他 身 体 如 水 苍 玉 ， 面 貌 如 闪 电 ， 眼 目 如 火 把 ， 手 和 脚 如 光 明 的 铜 ， 说 话 的 声 音 如 大 众 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22023', '27', '10', '7', '这 异 象 惟 有 我 ─ ─ 但 以 理 一 人 看 见 ， 同 着 我 的 人 没 有 看 见 。 他 们 却 大 大 战 兢 ， 逃 跑 隐 藏 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22024', '27', '10', '8', '只 剩 下 我 一 人 。 我 见 了 这 大 异 象 便 浑 身 无 力 ， 面 貌 失 色 ， 毫 无 气 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22025', '27', '10', '9', '我 却 听 见 他 说 话 的 声 音 ， 一 听 见 就 面 伏 在 地 沉 睡 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22026', '27', '10', '10', '忽 然 ， 有 一 手 按 在 我 身 上 ， 使 我 用 膝 和 手 掌 支 持 微 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22027', '27', '10', '11', '他 对 我 说 ： “ 大 蒙 眷 爱 的 但 以 理 啊 ， 要 明 白 我 与 你 所 说 的 话 ， 只 管 站 起 来 ， 因 为 我 现 在 奉 差 遣 来 到 你 这 里 。 ” 他 对 我 说 这 话 ， 我 便 战 战 兢 兢 地 立 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22028', '27', '10', '12', '他 就 说 ： “ 但 以 理 啊 ， 不 要 惧 怕 ！ 因 为 从 你 第 一 日 专 心 求 明 白 将 来 的 事 ， 又 在 你 神 面 前 刻 苦 己 心 ， 你 的 言 语 已 蒙 应 允 ； 我 是 因 你 的 言 语 而 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22029', '27', '10', '13', '但 波 斯 国 的 魔 君 拦 阻 我 二 十 一 日 。 忽 然 有 大 君 ｛ 就 是 天 使 长 ； 二 十 一 节 同 ｝ 中 的 一 位 米 迦 勒 来 帮 助 我 ， 我 就 停 留 在 波 斯 诸 王 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22030', '27', '10', '14', '现 在 我 来 ， 要 使 你 明 白 本 国 之 民 日 后 必 遭 遇 的 事 ， 因 为 这 异 象 关 乎 后 来 许 多 的 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22031', '27', '10', '15', '他 向 我 这 样 说 ， 我 就 脸 面 朝 地 ， 哑 口 无 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22032', '27', '10', '16', '不 料 ， 有 一 位 像 人 的 ， 摸 我 的 嘴 唇 ， 我 便 开 口 向 那 站 在 我 面 前 的 说 ： “ 我 主 啊 ， 因 见 这 异 象 ， 我 大 大 愁 苦 ， 毫 无 气 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22033', '27', '10', '17', '我 主 的 仆 人 怎 能 与 我 主 说 话 呢 ？ 我 一 见 异 象 就 浑 身 无 力 ， 毫 无 气 息 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22034', '27', '10', '18', '有 一 位 形 状 像 人 的 又 摸 我 ， 使 我 有 力 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22035', '27', '10', '19', '他 说 ： “ 大 蒙 眷 爱 的 人 哪 ， 不 要 惧 怕 ， 愿 你 平 安 ！ 你 总 要 坚 强 。 ” 他 一 向 我 说 话 ， 我 便 觉 得 有 力 量 ， 说 ： “ 我 主 请 说 ， 因 你 使 我 有 力 量 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22036', '27', '10', '20', '他 就 说 ： “ 你 知 道 我 为 何 来 见 你 吗 ？ 现 在 我 要 回 去 与 波 斯 的 魔 君 争 战 ， 我 去 后 ， 希 腊 ｛ 原 文 是 雅 完 ｝ 的 魔 君 必 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22037', '27', '10', '21', '但 我 要 将 那 录 在 真 确 书 上 的 事 告 诉 你 。 除 了 你 们 的 大 君 米 迦 勒 之 外 ， 没 有 帮 助 我 抵 挡 这 两 魔 君 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22038', '27', '11', '1', '又 说 ： “ 当 米 底 亚 王 大 流 士 元 年 ， 我 曾 起 来 扶 助 米 迦 勒 ， 使 他 坚 强 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22039', '27', '11', '2', '现 在 我 将 真 事 指 示 你 ： 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22040', '27', '11', '3', '必 有 一 个 勇 敢 的 王 兴 起 ， 执 掌 大 权 ， 随 意 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22041', '27', '11', '4', '他 兴 起 的 时 候 ， 他 的 国 必 破 裂 ， 向 天 的 四 方 ｛ 方 ： 原 文 是 风 ｝ 分 开 ， 却 不 归 他 的 后 裔 ， 治 国 的 权 势 也 都 不 及 他 ； 因 为 他 的 国 必 被 拔 出 ， 归 与 他 后 裔 之 外 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22042', '27', '11', '5', '“ 南 方 的 王 必 强 盛 ， 他 将 帅 中 必 有 一 个 比 他 更 强 盛 ， 执 掌 权 柄 ， 他 的 权 柄 甚 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22043', '27', '11', '6', '过 些 年 后 ， 他 们 必 互 相 连 合 ， 南 方 王 的 女 儿 必 就 了 北 方 王 来 立 约 ； 但 这 女 子 帮 助 之 力 存 立 不 住 ， 王 和 他 所 倚 靠 之 力 也 不 能 存 立 。 这 女 子 和 引 导 她 来 的 ， 并 生 她 的 ， 以 及 当 时 扶 助 她 的 ， 都 必 交 与 死 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22044', '27', '11', '7', '但 这 女 子 的 本 家 ｛ 原 文 是 根 ｝ 必 另 生 一 子 ｛ 子 ： 原 文 是 枝 ｝ 继 续 王 位 ， 他 必 率 领 军 队 进 入 北 方 王 的 保 障 ， 攻 击 他 们 ， 而 且 得 胜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22045', '27', '11', '8', '并 将 他 们 的 神 像 和 铸 成 的 偶 像 ， 与 金 银 的 宝 器 掠 到 埃 及 去 。 数 年 之 内 ， 他 不 去 攻 击 北 方 的 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22046', '27', '11', '9', '北 方 的 王 ｛ 原 文 是 他 ｝ 必 入 南 方 王 的 国 ， 却 要 仍 回 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22047', '27', '11', '10', '“ 北 方 王 ｛ 原 文 是 他 ｝ 的 二 子 必 动 干 戈 ， 招 聚 许 多 军 兵 。 这 军 兵 前 去 ， 如 洪 水 泛 滥 ， 又 必 再 去 争 战 ， 直 到 南 方 王 的 保 障 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22048', '27', '11', '11', '南 方 王 必 发 烈 怒 ， 出 来 与 北 方 王 争 战 ， 摆 列 大 军 ； 北 方 王 的 军 兵 必 交 付 他 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22049', '27', '11', '12', '他 的 众 军 高 傲 ， 他 的 心 也 必 自 高 ； 他 虽 使 数 万 人 仆 倒 ， 却 不 得 常 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22050', '27', '11', '13', '“ 北 方 王 必 回 来 摆 列 大 军 ， 比 先 前 的 更 多 。 满 了 所 定 的 年 数 ， 他 必 率 领 大 军 ， 带 极 多 的 军 装 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22051', '27', '11', '14', '那 时 ， 必 有 许 多 人 起 来 攻 击 南 方 王 ， 并 且 你 本 国 的 强 暴 人 必 兴 起 ， 要 应 验 那 异 象 ， 他 们 却 要 败 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22052', '27', '11', '15', '北 方 王 必 来 筑 垒 攻 取 坚 固 城 ； 南 方 的 军 兵 必 站 立 不 住 ， 就 是 选 择 的 精 兵 ｛ 原 文 是 民 ｝ 也 无 力 站 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22053', '27', '11', '16', '来 攻 击 他 的 ， 必 任 意 而 行 ， 无 人 在 北 方 王 ｛ 原 文 是 他 ｝ 面 前 站 立 得 住 。 他 必 站 在 那 荣 美 之 地 ， 用 手 施 行 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22054', '27', '11', '17', '“ 他 必 定 意 用 全 国 之 力 而 来 ， 立 公 正 的 约 ， 照 约 而 行 ， 将 自 己 的 女 儿 给 南 方 王 为 妻 ， 想 要 败 坏 他 ｛ 或 译 ： 埃 及 ｝ ， 这 计 却 不 得 成 就 ， 与 自 己 毫 无 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22055', '27', '11', '18', '其 后 他 必 转 回 夺 取 了 许 多 海 岛 。 但 有 一 大 帅 ， 除 掉 他 令 人 受 的 羞 辱 ， 并 且 使 这 羞 辱 归 他 本 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22056', '27', '11', '19', '他 就 必 转 向 本 地 的 保 障 ， 却 要 绊 跌 仆 倒 ， 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22057', '27', '11', '20', '“ 那 时 ， 必 有 一 人 兴 起 接 续 他 为 王 ， 使 横 征 暴 敛 的 人 通 行 国 中 的 荣 美 地 。 这 王 不 多 日 就 必 灭 亡 ， 却 不 因 忿 怒 ， 也 不 因 争 战 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22058', '27', '11', '21', '＜ 北 方 的 恶 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22059', '27', '11', '22', '必 有 无 数 的 军 兵 势 如 洪 水 ， 在 他 面 前 冲 没 败 坏 ； 同 盟 的 君 也 必 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22060', '27', '11', '23', '与 那 君 结 盟 之 后 ， 他 必 行 诡 诈 ， 因 为 他 必 上 来 以 微 小 的 军 ｛ 原 文 是 民 ｝ 成 为 强 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22061', '27', '11', '24', '趁 人 坦 然 无 备 的 时 候 ， 他 必 来 到 国 中 极 肥 美 之 地 ， 行 他 列 祖 和 他 列 祖 之 祖 所 未 曾 行 的 ， 将 掳 物 、 掠 物 ， 和 财 宝 散 给 众 人 ， 又 要 设 计 攻 打 保 障 ， 然 而 这 都 是 暂 时 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22062', '27', '11', '25', '“ 他 必 奋 勇 向 前 ， 率 领 大 军 攻 击 南 方 王 ； 南 方 王 也 必 以 极 大 极 强 的 军 兵 与 他 争 战 ， 却 站 立 不 住 ， 因 为 有 人 设 计 谋 害 南 方 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22063', '27', '11', '26', '吃 王 膳 的 ， 必 败 坏 他 ； 他 的 军 队 必 被 冲 没 ， 而 且 被 杀 的 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22064', '27', '11', '27', '至 于 这 二 王 ， 他 们 心 怀 恶 计 ， 同 席 说 谎 ， 计 谋 却 不 成 就 ； 因 为 到 了 定 期 ， 事 就 了 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22065', '27', '11', '28', '北 方 王 ｛ 原 文 是 他 ｝ 必 带 许 多 财 宝 回 往 本 国 ， 他 的 心 反 对 圣 约 ， 任 意 而 行 ， 回 到 本 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22066', '27', '11', '29', '“ 到 了 定 期 ， 他 必 返 回 ， 来 到 南 方 。 后 一 次 却 不 如 前 一 次 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22067', '27', '11', '30', '因 为 基 提 战 船 必 来 攻 击 他 ， 他 就 丧 胆 而 回 ， 又 要 恼 恨 圣 约 ， 任 意 而 行 ； 他 必 回 来 联 络 背 弃 圣 约 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22068', '27', '11', '31', '他 必 兴 兵 ， 这 兵 必 亵 渎 圣 地 ， 就 是 保 障 ， 除 掉 常 献 的 燔 祭 ， 设 立 那 行 毁 坏 可 憎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22069', '27', '11', '32', '作 恶 违 背 圣 约 的 人 ， 他 必 用 巧 言 勾 引 ； 惟 独 认 识 神 的 子 民 必 刚 强 行 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22070', '27', '11', '33', '民 间 的 智 慧 人 必 训 诲 多 人 ； 然 而 他 们 多 日 必 倒 在 刀 下 ， 或 被 火 烧 ， 或 被 掳 掠 抢 夺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22071', '27', '11', '34', '他 们 仆 倒 的 时 候 ， 稍 得 扶 助 ， 却 有 许 多 人 用 谄 媚 的 话 亲 近 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22072', '27', '11', '35', '智 慧 人 中 有 些 仆 倒 的 ， 为 要 熬 炼 其 余 的 人 ， 使 他 们 清 净 洁 白 ， 直 到 末 了 ； 因 为 到 了 定 期 ， 事 就 了 结 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22073', '27', '11', '36', '“ 王 必 任 意 而 行 ， 自 高 自 大 ， 超 过 所 有 的 神 ， 又 用 奇 异 的 话 攻 击 万 神 之 神 。 他 必 行 事 亨 通 ， 直 到 主 的 忿 怒 完 毕 ， 因 为 所 定 的 事 必 然 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22074', '27', '11', '37', '他 必 不 顾 他 列 祖 的 神 ， 也 不 顾 妇 女 所 羡 慕 的 神 ， 无 论 何 神 他 都 不 顾 ； 因 为 他 必 自 大 ， 高 过 一 切 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22075', '27', '11', '38', '他 倒 要 敬 拜 保 障 的 神 ， 用 金 、 银 、 宝 石 和 可 爱 之 物 敬 奉 他 列 祖 所 不 认 识 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22076', '27', '11', '39', '他 必 靠 外 邦 神 的 帮 助 ， 攻 破 最 坚 固 的 保 障 。 凡 承 认 他 的 ， 他 必 将 荣 耀 加 给 他 们 ， 使 他 们 管 辖 许 多 人 ， 又 为 贿 赂 分 地 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22077', '27', '11', '40', '“ 到 末 了 ， 南 方 王 要 与 他 交 战 。 北 方 王 必 用 战 车 、 马 兵 ， 和 许 多 战 船 ， 势 如 暴 风 来 攻 击 他 ， 也 必 进 入 列 国 ， 如 洪 水 泛 滥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22078', '27', '11', '41', '又 必 进 入 那 荣 美 之 地 ， 有 许 多 国 就 被 倾 覆 ， 但 以 东 人 、 摩 押 人 ， 和 一 大 半 亚 扪 人 必 脱 离 他 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22079', '27', '11', '42', '他 必 伸 手 攻 击 列 国 ； 埃 及 地 也 不 得 脱 离 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22080', '27', '11', '43', '他 必 把 持 埃 及 的 金 银 财 宝 和 各 样 的 宝 物 。 利 比 亚 人 和 古 实 人 都 必 跟 从 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22081', '27', '11', '44', '但 从 东 方 和 北 方 必 有 消 息 扰 乱 他 ， 他 就 大 发 烈 怒 出 去 ， 要 将 多 人 杀 灭 净 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22082', '27', '11', '45', '他 必 在 海 和 荣 美 的 圣 山 中 间 设 立 他 如 宫 殿 的 帐 幕 ； 然 而 到 了 他 的 结 局 ， 必 无 人 能 帮 助 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22083', '27', '12', '1', '＜ 末 日 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22084', '27', '12', '2', '睡 在 尘 埃 中 的 ， 必 有 多 人 复 醒 。 其 中 有 得 永 生 的 ， 有 受 羞 辱 永 远 被 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22085', '27', '12', '3', '智 慧 人 必 发 光 如 同 天 上 的 光 ； 那 使 多 人 归 义 的 ， 必 发 光 如 星 ， 直 到 永 永 远 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22086', '27', '12', '4', '但 以 理 啊 ， 你 要 隐 藏 这 话 ， 封 闭 这 书 ， 直 到 末 时 。 必 有 多 人 来 往 奔 跑 ｛ 或 译 ： 切 心 研 究 ｝ ， 知 识 就 必 增 长 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22087', '27', '12', '5', '我 ─ ─ 但 以 理 观 看 ， 见 另 有 两 个 人 站 立 ： 一 个 在 河 这 边 ， 一 个 在 河 那 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22088', '27', '12', '6', '有 一 个 问 那 站 在 河 水 以 上 、 穿 细 麻 衣 的 说 ： “ 这 奇 异 的 事 到 几 时 才 应 验 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22089', '27', '12', '7', '我 听 见 那 站 在 河 水 以 上 、 穿 细 麻 衣 的 ， 向 天 举 起 左 右 手 ， 指 着 活 到 永 远 的 主 起 誓 说 ： “ 要 到 一 载 、 二 载 、 半 载 ， 打 破 圣 民 权 力 的 时 候 ， 这 一 切 事 就 都 应 验 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22090', '27', '12', '8', '我 听 见 这 话 ， 却 不 明 白 ， 就 说 ： “ 我 主 啊 ， 这 些 事 的 结 局 是 怎 样 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22091', '27', '12', '9', '他 说 ： “ 但 以 理 啊 ， 你 只 管 去 ； 因 为 这 话 已 经 隐 藏 封 闭 ， 直 到 末 时 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22092', '27', '12', '10', '必 有 许 多 人 使 自 己 清 净 洁 白 ， 且 被 熬 炼 ； 但 恶 人 仍 必 行 恶 ， 一 切 恶 人 都 不 明 白 ， 惟 独 智 慧 人 能 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22093', '27', '12', '11', '从 除 掉 常 献 的 燔 祭 ， 并 设 立 那 行 毁 坏 可 憎 之 物 的 时 候 ， 必 有 一 千 二 百 九 十 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22094', '27', '12', '12', '等 到 一 千 三 百 三 十 五 日 的 ， 那 人 便 为 有 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22095', '27', '12', '13', '“ 你 且 去 等 候 结 局 ， 因 为 你 必 安 歇 。 到 了 末 期 ， 你 必 起 来 ， 享 受 你 的 福 分 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22096', '28', '1', '1', '当 乌 西 雅 、 约 坦 、 亚 哈 斯 、 希 西 家 作 犹 大 王 ， 约 阿 施 的 儿 子 耶 罗 波 安 作 以 色 列 王 的 时 候 ， 耶 和 华 的 话 临 到 备 利 的 儿 子 何 西 阿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22097', '28', '1', '2', '＜ 何 西 阿 的 妻 子 和 儿 女 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22098', '28', '1', '3', '于 是 ， 何 西 阿 去 娶 了 滴 拉 音 的 女 儿 歌 篾 。 这 妇 人 怀 孕 ， 给 他 生 了 一 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22099', '28', '1', '4', '耶 和 华 对 何 西 阿 说 ： “ 给 他 起 名 叫 耶 斯 列 ； 因 为 再 过 片 时 ， 我 必 讨 耶 户 家 在 耶 斯 列 杀 人 流 血 的 罪 ， 也 必 使 以 色 列 家 的 国 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22100', '28', '1', '5', '到 那 日 ， 我 必 在 耶 斯 列 平 原 折 断 以 色 列 的 弓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22101', '28', '1', '6', '歌 篾 又 怀 孕 生 了 一 个 女 儿 ， 耶 和 华 对 何 西 阿 说 ： “ 给 她 起 名 叫 罗 ． 路 哈 玛 ｛ 就 是 不 蒙 怜 悯 的 意 思 ｝ ； 因 为 我 必 不 再 怜 悯 以 色 列 家 ， 决 不 赦 免 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22102', '28', '1', '7', '我 却 要 怜 悯 犹 大 家 ， 使 他 们 靠 耶 和 华 ─ ─ 他 们 的 神 得 救 ， 不 使 他 们 靠 弓 、 刀 、 争 战 、 马 匹 ， 与 马 兵 得 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22103', '28', '1', '8', '歌 篾 给 罗 ． 路 哈 玛 断 奶 以 后 ， 又 怀 孕 生 了 一 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22104', '28', '1', '9', '耶 和 华 说 ： “ 给 他 起 名 叫 罗 ． 阿 米 ｛ 就 是 非 我 民 的 意 思 ｝ ； 因 为 你 们 不 作 我 的 子 民 ， 我 也 不 作 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22105', '28', '1', '10', '＜ 以 色 列 将 要 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22106', '28', '1', '11', '犹 大 人 和 以 色 列 人 必 一 同 聚 集 ， 为 自 己 立 一 个 首 领 ， 从 这 地 上 去 ｛ 或 译 ： 从 被 掳 之 地 上 来 ｝ ， 因 为 耶 斯 列 的 日 子 必 为 大 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22107', '28', '2', '1', '你 们 要 称 你 们 的 弟 兄 为 阿 米 ｛ 就 是 我 民 的 意 思 ｝ ， 称 你 们 的 姊 妹 为 路 哈 玛 ｛ 就 是 蒙 怜 悯 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22108', '28', '2', '2', '＜ 不 贞 的 歌 篾 ─ ─ 不 忠 的 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22109', '28', '2', '3', '免 得 我 剥 她 的 衣 服 ， 使 她 赤 体 ， 与 才 生 的 时 候 一 样 ， 使 她 如 旷 野 ， 如 干 旱 之 地 ， 因 渴 而 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22110', '28', '2', '4', '我 必 不 怜 悯 她 的 儿 女 ， 因 为 他 们 是 从 淫 乱 而 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22111', '28', '2', '5', '他 们 的 母 亲 行 了 淫 乱 ， 怀 他 们 的 母 做 了 可 羞 耻 的 事 ， 因 为 她 说 ： 我 要 随 从 所 爱 的 ； 我 的 饼 、 水 、 羊 毛 、 麻 、 油 、 酒 都 是 他 们 给 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22112', '28', '2', '6', '因 此 ， 我 必 用 荆 棘 堵 塞 她 的 道 ， 筑 墙 挡 住 她 ， 使 她 找 不 着 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22113', '28', '2', '7', '她 必 追 随 所 爱 的 ， 却 追 不 上 ； 她 必 寻 找 他 们 ， 却 寻 不 见 ， 便 说 ： 我 要 归 回 前 夫 ， 因 我 那 时 的 光 景 比 如 今 还 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22114', '28', '2', '8', '她 不 知 道 是 我 给 她 五 谷 、 新 酒 ， 和 油 ， 又 加 增 她 的 金 银 ； 她 却 以 此 供 奉 ｛ 或 译 ： 制 造 ｝ 巴 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22115', '28', '2', '9', '因 此 到 了 收 割 的 日 子 ， 出 酒 的 时 候 ， 我 必 将 我 的 五 谷 新 酒 收 回 ， 也 必 将 她 应 当 遮 体 的 羊 毛 和 麻 夺 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22116', '28', '2', '10', '如 今 我 必 在 她 所 爱 的 眼 前 显 露 她 的 丑 态 ； 必 无 人 能 救 她 脱 离 我 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22117', '28', '2', '11', '我 也 必 使 她 的 宴 乐 、 节 期 、 月 朔 、 安 息 日 ， 并 她 的 一 切 大 会 都 止 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22118', '28', '2', '12', '我 也 必 毁 坏 她 的 葡 萄 树 和 无 花 果 树 ， 就 是 她 说 “ 这 是 我 所 爱 的 给 我 为 赏 赐 ” 的 。 我 必 使 这 些 树 变 为 荒 林 ， 为 田 野 的 走 兽 所 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22119', '28', '2', '13', '我 必 追 讨 她 素 日 给 诸 巴 力 烧 香 的 罪 ； 那 时 她 佩 带 耳 环 和 别 样 妆 饰 ， 随 从 她 所 爱 的 ， 却 忘 记 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22120', '28', '2', '14', '＜ 神 对 他 子 民 的 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22121', '28', '2', '15', '她 从 那 里 出 来 ， 我 必 赐 她 葡 萄 园 ， 又 赐 她 亚 割 谷 作 为 指 望 的 门 。 她 必 在 那 里 应 声 ｛ 或 译 ： 歌 唱 ｝ ， 与 幼 年 的 日 子 一 样 ， 与 从 埃 及 地 上 来 的 时 候 相 同 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22122', '28', '2', '16', '耶 和 华 说 ： “ 那 日 你 必 称 呼 我 伊 施 ｛ 就 是 我 夫 的 意 思 ｝ ， 不 再 称 呼 我 巴 力 ｛ 就 是 我 主 的 意 思 ｝ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22123', '28', '2', '17', '因 为 我 必 从 我 民 的 口 中 除 掉 诸 巴 力 的 名 号 ， 这 名 号 不 再 提 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22124', '28', '2', '18', '当 那 日 ， 我 必 为 我 的 民 ， 与 田 野 的 走 兽 和 空 中 的 飞 鸟 ， 并 地 上 的 昆 虫 立 约 ； 又 必 在 国 中 折 断 弓 刀 ， 止 息 争 战 ， 使 他 们 安 然 躺 卧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22125', '28', '2', '19', '我 必 聘 你 永 远 归 我 为 妻 ， 以 仁 义 、 公 平 、 慈 爱 、 怜 悯 聘 你 归 我 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22126', '28', '2', '20', '也 以 诚 实 聘 你 归 我 ， 你 就 必 认 识 我 ─ ─ 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22127', '28', '2', '21', '耶 和 华 说 ： 那 日 我 必 应 允 ， 我 必 应 允 天 ， 天 必 应 允 地 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22128', '28', '2', '22', '地 必 应 允 五 谷 、 新 酒 ， 和 油 ， 这 些 必 应 允 耶 斯 列 民 ｛ 耶 斯 列 就 是 神 栽 种 的 意 思 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22129', '28', '2', '23', '我 必 将 她 种 在 这 地 。 素 不 蒙 怜 悯 的 ， 我 必 怜 悯 ； 本 非 我 民 的 ， 我 必 对 他 说 ： 你 是 我 的 民 ； 他 必 说 ： 你 是 我 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22130', '28', '3', '1', '＜ 何 西 阿 和 那 不 贞 的 妇 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22131', '28', '3', '2', '我 便 用 银 子 十 五 舍 客 勒 ， 大 麦 一 贺 梅 珥 半 ， 买 她 归 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22132', '28', '3', '3', '我 对 她 说 ： “ 你 当 多 日 为 我 独 居 ， 不 可 行 淫 ， 不 可 归 别 人 为 妻 ， 我 向 你 也 必 这 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22133', '28', '3', '4', '以 色 列 人 也 必 多 日 独 居 ， 无 君 王 ， 无 首 领 ， 无 祭 祀 ， 无 柱 像 ， 无 以 弗 得 ， 无 家 中 的 神 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22134', '28', '3', '5', '后 来 以 色 列 人 必 归 回 ｛ 或 译 ： 回 心 转 意 ｝ ， 寻 求 他 们 的 神 ─ ─ 耶 和 华 和 他 们 的 王 大 卫 。 在 末 后 的 日 子 ， 必 以 敬 畏 的 心 归 向 耶 和 华 ， 领 受 他 的 恩 惠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22135', '28', '4', '1', '＜ 耶 和 华 谴 责 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22136', '28', '4', '2', '但 起 假 誓 ， 不 践 前 言 ， 杀 害 ， 偷 盗 ， 奸 淫 ， 行 强 暴 ， 杀 人 流 血 ， 接 连 不 断 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22137', '28', '4', '3', '因 此 ， 这 地 悲 哀 ， 其 上 的 民 、 田 野 的 兽 、 空 中 的 鸟 必 都 衰 微 ， 海 中 的 鱼 也 必 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22138', '28', '4', '4', '＜ 谴 责 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22139', '28', '4', '5', '你 这 祭 司 必 日 间 跌 倒 ； 先 知 也 必 夜 间 与 你 一 同 跌 倒 ； 我 必 灭 绝 你 的 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22140', '28', '4', '6', '我 的 民 因 无 知 识 而 灭 亡 。 你 弃 掉 知 识 ， 我 也 必 弃 掉 你 ， 使 你 不 再 给 我 作 祭 司 。 你 既 忘 了 你 神 的 律 法 ， 我 也 必 忘 记 你 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22141', '28', '4', '7', '祭 司 越 发 增 多 ， 就 越 发 得 罪 我 ； 我 必 使 他 们 的 荣 耀 变 为 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22142', '28', '4', '8', '他 们 吃 我 民 的 赎 罪 祭 ， 满 心 愿 意 我 民 犯 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22143', '28', '4', '9', '将 来 民 如 何 ， 祭 司 也 必 如 何 ； 我 必 因 他 们 所 行 的 惩 罚 他 们 ， 照 他 们 所 做 的 报 应 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22144', '28', '4', '10', '他 们 吃 ， 却 不 得 饱 ； 行 淫 ， 而 不 得 立 后 ； 因 为 他 们 离 弃 耶 和 华 ， 不 遵 他 的 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22145', '28', '4', '11', '＜ 谴 责 拜 偶 像 的 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22146', '28', '4', '12', '我 的 民 求 问 木 偶 ， 以 为 木 杖 能 指 示 他 们 ； 因 为 他 们 的 淫 心 使 他 们 失 迷 ， 他 们 就 行 淫 离 弃 神 ， 不 守 约 束 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22147', '28', '4', '13', '在 各 山 顶 ， 各 高 冈 的 橡 树 、 杨 树 、 栗 树 之 下 ， 献 祭 烧 香 ， 因 为 树 影 美 好 。 所 以 ， 你 们 的 女 儿 淫 乱 ， 你 们 的 新 妇 ｛ 或 译 ： 儿 妇 ； 下 同 ｝ 行 淫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22148', '28', '4', '14', '你 们 的 女 儿 淫 乱 ， 你 们 的 新 妇 行 淫 ， 我 却 不 惩 罚 她 们 ； 因 为 你 们 自 己 离 群 与 娼 妓 同 居 ， 与 妓 女 一 同 献 祭 。 这 无 知 的 民 必 致 倾 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22149', '28', '4', '15', '以 色 列 啊 ， 你 虽 然 行 淫 ， 犹 大 却 不 可 犯 罪 。 不 要 往 吉 甲 去 ， 不 要 上 到 伯 ． 亚 文 ， 也 不 要 指 着 永 生 的 耶 和 华 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22150', '28', '4', '16', '以 色 列 倔 强 ， 犹 如 倔 强 的 母 牛 ； 现 在 耶 和 华 要 放 他 们 ， 如 同 放 羊 羔 在 宽 阔 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22151', '28', '4', '17', '以 法 莲 亲 近 偶 像 ， 任 凭 他 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22152', '28', '4', '18', '他 们 所 喝 的 已 经 发 酸 ， 他 们 时 常 行 淫 ， 他 们 的 官 长 最 爱 羞 耻 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22153', '28', '4', '19', '风 把 他 们 裹 在 翅 膀 里 ； 他 们 因 所 献 的 祭 必 致 蒙 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22154', '28', '5', '1', '众 祭 司 啊 ， 要 听 我 的 话 ！ 以 色 列 家 啊 ， 要 留 心 听 ！ 王 家 啊 ， 要 侧 耳 而 听 ！ 审 判 要 临 到 你 们 ， 因 你 们 在 米 斯 巴 如 网 罗 ， 在 他 泊 山 如 铺 张 的 网 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22155', '28', '5', '2', '这 些 悖 逆 的 人 肆 行 杀 戮 ， 罪 孽 极 深 ； 我 却 斥 责 他 们 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22156', '28', '5', '3', '以 法 莲 为 我 所 知 ； 以 色 列 不 能 向 我 隐 藏 。 以 法 莲 哪 ， 现 在 你 行 淫 了 ， 以 色 列 被 玷 污 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22157', '28', '5', '4', '＜ 何 西 阿 警 告 拜 偶 像 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22158', '28', '5', '5', '以 色 列 的 骄 傲 当 面 见 证 自 己 。 故 此 ， 以 色 列 和 以 法 莲 必 因 自 己 的 罪 孽 跌 倒 ； 犹 大 也 必 与 他 们 一 同 跌 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22159', '28', '5', '6', '他 们 必 牵 着 牛 羊 去 寻 求 耶 和 华 ， 却 寻 不 见 ； 他 已 经 转 去 离 开 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22160', '28', '5', '7', '他 们 向 耶 和 华 行 事 诡 诈 ， 生 了 私 子 。 到 了 月 朔 ， 他 们 与 他 们 的 地 业 必 被 吞 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22161', '28', '5', '8', '＜ 犹 大 和 以 色 列 的 战 争 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22162', '28', '5', '9', '在 责 罚 的 日 子 ， 以 法 莲 必 变 为 荒 场 ； 我 在 以 色 列 支 派 中 ， 指 示 将 来 必 成 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22163', '28', '5', '10', '犹 大 的 首 领 如 同 挪 移 地 界 的 人 ， 我 必 将 忿 怒 倒 在 他 们 身 上 ， 如 水 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22164', '28', '5', '11', '以 法 莲 因 乐 从 人 的 命 令 ， 就 受 欺 压 ， 被 审 判 压 碎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22165', '28', '5', '12', '我 使 以 法 莲 如 虫 蛀 之 物 ， 使 犹 大 家 如 朽 烂 之 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22166', '28', '5', '13', '以 法 莲 见 自 己 有 病 ， 犹 大 见 自 己 有 伤 ， 他 们 就 打 发 人 往 亚 述 去 见 耶 雷 布 王 ， 他 却 不 能 医 治 你 们 ， 不 能 治 好 你 们 的 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22167', '28', '5', '14', '我 必 向 以 法 莲 如 狮 子 ， 向 犹 大 家 如 少 壮 狮 子 。 我 必 撕 裂 而 去 ， 我 要 夺 去 ， 无 人 搭 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22168', '28', '5', '15', '我 要 回 到 原 处 ， 等 他 们 自 觉 有 罪 ｛ 或 译 ： 承 认 己 罪 ｝ ， 寻 求 我 面 ； 他 们 在 急 难 的 时 候 必 切 切 寻 求 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22169', '28', '6', '1', '＜ 以 色 列 无 悔 改 诚 意 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22170', '28', '6', '2', '过 两 天 他 必 使 我 们 苏 醒 ， 第 三 天 他 必 使 我 们 兴 起 ， 我 们 就 在 他 面 前 得 以 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22171', '28', '6', '3', '我 们 务 要 认 识 耶 和 华 ， 竭 力 追 求 认 识 他 。 他 出 现 确 如 晨 光 ； 他 必 临 到 我 们 像 甘 雨 ， 像 滋 润 田 地 的 春 雨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22172', '28', '6', '4', '主 说 ： 以 法 莲 哪 ， 我 可 向 你 怎 样 行 呢 ？ 犹 大 啊 ， 我 可 向 你 怎 样 做 呢 ？ 因 为 你 们 的 良 善 如 同 早 晨 的 云 雾 ， 又 如 速 散 的 甘 露 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22173', '28', '6', '5', '因 此 ， 我 藉 先 知 砍 伐 他 们 ， 以 我 口 中 的 话 杀 戮 他 们 ； 我 施 行 的 审 判 如 光 发 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22174', '28', '6', '6', '我 喜 爱 良 善 ｛ 或 译 ： 怜 恤 ｝ ， 不 喜 爱 祭 祀 ； 喜 爱 认 识 神 ， 胜 于 燔 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22175', '28', '6', '7', '他 们 却 如 亚 当 背 约 ， 在 境 内 向 我 行 事 诡 诈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22176', '28', '6', '8', '基 列 是 作 孽 之 人 的 城 ， 被 血 沾 染 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22177', '28', '6', '9', '强 盗 成 群 ， 怎 样 埋 伏 杀 人 ， 祭 司 结 党 ， 也 照 样 在 示 剑 的 路 上 杀 戮 ， 行 了 邪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22178', '28', '6', '10', '在 以 色 列 家 ， 我 见 了 可 憎 的 事 ； 在 以 法 莲 那 里 有 淫 行 ， 以 色 列 被 玷 污 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22179', '28', '6', '11', '犹 大 啊 ， 我 使 被 掳 之 民 归 回 的 时 候 ， 必 有 为 你 所 命 定 的 收 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22180', '28', '7', '1', '我 想 医 治 以 色 列 的 时 候 ， 以 法 莲 的 罪 孽 和 撒 马 利 亚 的 罪 恶 就 显 露 出 来 。 他 们 行 事 虚 谎 ， 内 有 贼 人 入 室 偷 窃 ， 外 有 强 盗 成 群 骚 扰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22181', '28', '7', '2', '他 们 心 里 并 不 思 想 我 记 念 他 们 的 一 切 恶 ； 他 们 所 行 的 现 在 缠 绕 他 们 ， 都 在 我 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22182', '28', '7', '3', '＜ 宫 廷 内 乱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22183', '28', '7', '4', '他 们 都 是 行 淫 的 ， 像 火 炉 被 烤 饼 的 烧 热 ， 从 抟 面 到 发 面 的 时 候 ， 暂 不 使 火 着 旺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22184', '28', '7', '5', '在 我 们 王 宴 乐 的 日 子 ， 首 领 因 酒 的 烈 性 成 病 ； 王 与 亵 慢 人 拉 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22185', '28', '7', '6', '首 领 埋 伏 的 时 候 ， 心 中 热 如 火 炉 ， 就 如 烤 饼 的 整 夜 睡 卧 ， 到 了 早 晨 火 气 炎 炎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22186', '28', '7', '7', '众 民 也 热 如 火 炉 ， 烧 灭 他 们 的 官 长 。 他 们 的 君 王 都 仆 倒 而 死 ； 他 们 中 间 无 一 人 求 告 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22187', '28', '7', '8', '＜ 以 色 列 和 列 邦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22188', '28', '7', '9', '外 邦 人 吞 吃 他 劳 力 得 来 的 ， 他 却 不 知 道 ； 头 发 斑 白 ， 他 也 不 觉 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22189', '28', '7', '10', '以 色 列 的 骄 傲 当 面 见 证 自 己 ， 虽 遭 遇 这 一 切 ， 他 们 仍 不 归 向 耶 和 华 ─ ─ 他 们 的 神 ， 也 不 寻 求 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22190', '28', '7', '11', '以 法 莲 好 像 鸽 子 愚 蠢 无 知 ； 他 们 求 告 埃 及 ， 投 奔 亚 述 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22191', '28', '7', '12', '他 们 去 的 时 候 ， 我 必 将 我 的 网 撒 在 他 们 身 上 ； 我 要 打 下 他 们 ， 如 同 空 中 的 鸟 。 我 必 按 他 们 会 众 所 听 见 的 惩 罚 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22192', '28', '7', '13', '他 们 因 离 弃 我 ， 必 定 有 祸 ； 因 违 背 我 ， 必 被 毁 灭 。 我 虽 要 救 赎 他 们 ， 他 们 却 向 我 说 谎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22193', '28', '7', '14', '他 们 并 不 诚 心 哀 求 我 ， 乃 在 床 上 呼 号 ； 他 们 为 求 五 谷 新 酒 聚 集 ， 仍 然 悖 逆 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22194', '28', '7', '15', '我 虽 教 导 他 们 ， 坚 固 他 们 的 膀 臂 ， 他 们 竟 图 谋 抗 拒 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22195', '28', '7', '16', '他 们 归 向 ， 却 不 归 向 至 上 者 ； 他 们 如 同 翻 背 的 弓 。 他 们 的 首 领 必 因 舌 头 的 狂 傲 倒 在 刀 下 ； 这 在 埃 及 地 必 作 人 的 讥 笑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22196', '28', '8', '1', '＜ 以 色 列 人 因 拜 偶 像 被 定 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22197', '28', '8', '2', '他 们 必 呼 叫 我 说 ： 我 的 神 啊 ， 我 们 以 色 列 认 识 你 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22198', '28', '8', '3', '以 色 列 丢 弃 良 善 ｛ 或 译 ： 福 分 ｝ ； 仇 敌 必 追 逼 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22199', '28', '8', '4', '他 们 立 君 王 ， 却 不 由 我 ； 他 们 立 首 领 ， 我 却 不 认 。 他 们 用 金 银 为 自 己 制 造 偶 像 ， 以 致 被 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22200', '28', '8', '5', '撒 马 利 亚 啊 ， 耶 和 华 已 经 丢 弃 你 的 牛 犊 ； 我 的 怒 气 向 拜 牛 犊 的 人 发 作 。 他 们 到 几 时 方 能 无 罪 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22201', '28', '8', '6', '这 牛 犊 出 于 以 色 列 ， 是 匠 人 所 造 的 ， 并 不 是 神 。 撒 马 利 亚 的 牛 犊 必 被 打 碎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22202', '28', '8', '7', '他 们 所 种 的 是 风 ， 所 收 的 是 暴 风 ； 所 种 的 不 成 禾 稼 ， 就 是 发 苗 也 不 结 实 ； 即 便 结 实 ， 外 邦 人 必 吞 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22203', '28', '8', '8', '以 色 列 被 吞 吃 ； 现 今 在 列 国 中 ， 好 像 人 不 喜 悦 的 器 皿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22204', '28', '8', '9', '他 们 投 奔 亚 述 ， 如 同 独 行 的 野 驴 ； 以 法 莲 贿 买 朋 党 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22205', '28', '8', '10', '他 们 虽 在 列 邦 中 贿 买 人 ， 现 在 我 却 要 聚 集 惩 罚 他 们 ； 他 们 因 君 王 和 首 领 所 加 的 重 担 日 渐 衰 微 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22206', '28', '8', '11', '以 法 莲 增 添 祭 坛 取 罪 ； 因 此 ， 祭 坛 使 他 犯 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22207', '28', '8', '12', '我 为 他 写 了 律 法 万 条 ， 他 却 以 为 与 他 毫 无 关 涉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22208', '28', '8', '13', '至 于 献 给 我 的 祭 物 ， 他 们 自 食 其 肉 ， 耶 和 华 却 不 悦 纳 他 们 。 现 在 必 记 念 他 们 的 罪 孽 ， 追 讨 他 们 的 罪 恶 ； 他 们 必 归 回 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22209', '28', '8', '14', '以 色 列 忘 记 造 他 的 主 ， 建 造 宫 殿 ； 犹 大 多 造 坚 固 城 ， 我 却 要 降 火 焚 烧 他 的 城 邑 ， 烧 灭 其 中 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22210', '28', '9', '1', '＜ 何 西 阿 宣 布 以 色 列 受 惩 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22211', '28', '9', '2', '谷 场 和 酒 醡 都 不 够 以 色 列 人 使 用 ； 新 酒 也 必 缺 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22212', '28', '9', '3', '他 们 必 不 得 住 耶 和 华 的 地 ； 以 法 莲 却 要 归 回 埃 及 ， 必 在 亚 述 吃 不 洁 净 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22213', '28', '9', '4', '他 们 必 不 得 向 耶 和 华 奠 酒 ， 即 便 奠 酒 也 不 蒙 悦 纳 。 他 们 的 祭 物 必 如 居 丧 者 的 食 物 ， 凡 吃 的 必 被 玷 污 ； 因 他 们 的 食 物 只 为 自 己 的 口 腹 ， 必 不 奉 入 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22214', '28', '9', '5', '在 大 会 的 日 子 ， 到 耶 和 华 的 节 期 ， 你 们 怎 样 行 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22215', '28', '9', '6', '看 哪 ， 他 们 逃 避 灾 难 ； 埃 及 人 必 收 殓 他 们 的 尸 首 ， 摩 弗 人 必 葬 埋 他 们 的 骸 骨 。 他 们 用 银 子 做 的 美 物 上 必 长 蒺 藜 ； 他 们 的 帐 棚 中 必 生 荆 棘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22216', '28', '9', '7', '以 色 列 人 必 知 道 降 罚 的 日 子 临 近 ， 报 应 的 时 候 来 到 。 民 说 ： 作 先 知 的 是 愚 昧 ； 受 灵 感 的 是 狂 妄 ， 皆 因 他 们 多 多 作 孽 ， 大 怀 怨 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22217', '28', '9', '8', '以 法 莲 曾 作 我 神 守 望 的 ； 至 于 先 知 ， 在 他 一 切 的 道 上 作 为 捕 鸟 人 的 网 罗 ， 在 他 神 的 家 中 怀 怨 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22218', '28', '9', '9', '以 法 莲 深 深 地 败 坏 ， 如 在 基 比 亚 的 日 子 一 样 。 耶 和 华 必 记 念 他 们 的 罪 孽 ， 追 讨 他 们 的 罪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22219', '28', '9', '10', '＜ 以 色 列 的 罪 和 它 的 后 果 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22220', '28', '9', '11', '至 于 以 法 莲 人 ， 他 们 的 荣 耀 必 如 鸟 飞 去 ， 必 不 生 产 ， 不 怀 胎 ， 不 成 孕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22221', '28', '9', '12', '纵 然 养 大 儿 女 ， 我 却 必 使 他 们 丧 子 ， 甚 至 不 留 一 个 。 我 离 弃 他 们 ， 他 们 就 有 祸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22222', '28', '9', '13', '我 看 以 法 莲 如 泰 尔 栽 于 美 地 。 以 法 莲 却 要 将 自 己 的 儿 女 带 出 来 ， 交 与 行 杀 戮 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22223', '28', '9', '14', '耶 和 华 啊 ， 求 你 加 给 他 们 ─ ─ 加 什 么 呢 ？ 要 使 他 们 胎 坠 乳 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22224', '28', '9', '15', '＜ 耶 和 华 审 判 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22225', '28', '9', '16', '以 法 莲 受 责 罚 ， 根 本 枯 干 ， 必 不 能 结 果 ， 即 或 生 产 ， 我 必 杀 他 们 所 生 的 爱 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22226', '28', '9', '17', '＜ 先 知 论 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22227', '28', '10', '1', '以 色 列 是 茂 盛 的 葡 萄 树 ， 结 果 繁 多 。 果 子 越 多 ， 就 越 增 添 祭 坛 ； 地 土 越 肥 美 ， 就 越 造 美 丽 的 柱 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22228', '28', '10', '2', '他 们 心 怀 二 意 ， 现 今 要 定 为 有 罪 。 耶 和 华 必 拆 毁 他 们 的 祭 坛 ， 毁 坏 他 们 的 柱 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22229', '28', '10', '3', '他 们 必 说 ： 我 们 没 有 王 ， 因 为 我 们 不 敬 畏 耶 和 华 。 王 能 为 我 们 做 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22230', '28', '10', '4', '他 们 为 立 约 说 谎 言 ， 起 假 誓 ； 因 此 ， 灾 罚 如 苦 菜 滋 生 在 田 间 的 犁 沟 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22231', '28', '10', '5', '撒 马 利 亚 的 居 民 必 因 伯 ． 亚 文 的 牛 犊 惊 恐 ； 崇 拜 牛 犊 的 民 和 喜 爱 牛 犊 的 祭 司 都 必 因 荣 耀 离 开 它 ， 为 它 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22232', '28', '10', '6', '人 必 将 牛 犊 带 到 亚 述 当 作 礼 物 ， 献 给 耶 雷 布 王 。 以 法 莲 必 蒙 羞 ； 以 色 列 必 因 自 己 的 计 谋 惭 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22233', '28', '10', '7', '至 于 撒 马 利 亚 ， 她 的 王 必 灭 没 ， 如 水 面 的 沫 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22234', '28', '10', '8', '伯 ． 亚 文 的 邱 坛 ─ ─ 就 是 以 色 列 取 罪 的 地 方 必 被 毁 灭 ； 荆 棘 和 蒺 藜 必 长 在 他 们 的 祭 坛 上 。 他 们 必 对 大 山 说 ： 遮 盖 我 们 ！ 对 小 山 说 ： 倒 在 我 们 身 上 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22235', '28', '10', '9', '＜ 神 审 判 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22236', '28', '10', '10', '我 必 随 意 惩 罚 他 们 。 他 们 为 两 样 的 罪 所 缠 ； 列 邦 的 民 必 聚 集 攻 击 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22237', '28', '10', '11', '以 法 莲 是 驯 良 的 母 牛 犊 ， 喜 爱 踹 谷 ， 我 却 将 轭 加 在 它 肥 美 的 颈 项 上 ， 我 要 使 以 法 莲 拉 套 ｛ 或 译 ： 被 骑 ｝ 。 犹 大 必 耕 田 ； 雅 各 必 耙 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22238', '28', '10', '12', '你 们 要 为 自 己 栽 种 公 义 ， 就 能 收 割 慈 爱 。 现 今 正 是 寻 求 耶 和 华 的 时 候 ； 你 们 要 开 垦 荒 地 ， 等 他 临 到 ， 使 公 义 如 雨 降 在 你 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22239', '28', '10', '13', '你 们 耕 种 的 是 奸 恶 ， 收 割 的 是 罪 孽 ， 吃 的 是 谎 话 的 果 子 。 因 你 倚 靠 自 己 的 行 为 ， 仰 赖 勇 士 众 多 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22240', '28', '10', '14', '所 以 在 这 民 中 必 有 哄 嚷 之 声 ， 你 一 切 的 保 障 必 被 拆 毁 ， 就 如 沙 勒 幔 在 争 战 的 日 子 拆 毁 伯 ． 亚 比 勒 ， 将 其 中 的 母 子 一 同 摔 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22241', '28', '10', '15', '因 他 们 的 大 恶 ， 伯 特 利 必 使 你 们 遭 遇 如 此 。 到 了 黎 明 ， 以 色 列 的 王 必 全 然 灭 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22242', '28', '11', '1', '＜ 怜 爱 叛 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22243', '28', '11', '2', '先 知 越 发 招 呼 他 们 ， 他 们 越 发 走 开 ， 向 诸 巴 力 献 祭 ， 给 雕 刻 的 偶 像 烧 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22244', '28', '11', '3', '我 原 教 导 以 法 莲 行 走 ， 用 膀 臂 抱 着 他 们 ， 他 们 却 不 知 道 是 我 医 治 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22245', '28', '11', '4', '我 用 慈 绳 ｛ 慈 ： 原 文 是 人 的 ｝ 爱 索 牵 引 他 们 ； 我 待 他 们 如 人 放 松 牛 的 两 腮 夹 板 ， 把 粮 食 放 在 他 们 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22246', '28', '11', '5', '他 们 必 不 归 回 埃 及 地 ， 亚 述 人 却 要 作 他 们 的 王 ， 因 他 们 不 肯 归 向 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22247', '28', '11', '6', '刀 剑 必 临 到 他 们 的 城 邑 ， 毁 坏 门 闩 ， 把 人 吞 灭 ， 都 因 他 们 随 从 自 己 的 计 谋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22248', '28', '11', '7', '我 的 民 偏 要 背 道 离 开 我 ； 众 先 知 虽 然 招 呼 他 们 归 向 至 上 的 主 ， 却 无 人 尊 崇 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22249', '28', '11', '8', '以 法 莲 哪 ， 我 怎 能 舍 弃 你 ？ 以 色 列 啊 ， 我 怎 能 弃 绝 你 ？ 我 怎 能 使 你 如 押 玛 ？ 怎 能 使 你 如 洗 扁 ？ 我 回 心 转 意 ， 我 的 怜 爱 大 大 发 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22250', '28', '11', '9', '我 必 不 发 猛 烈 的 怒 气 ， 也 不 再 毁 灭 以 法 莲 。 因 我 是 神 ， 并 非 世 人 ， 是 你 们 中 间 的 圣 者 ； 我 必 不 在 怒 中 临 到 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22251', '28', '11', '10', '耶 和 华 必 如 狮 子 吼 叫 ， 子 民 必 跟 随 他 。 他 一 吼 叫 ， 他 们 就 从 西 方 急 速 而 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22252', '28', '11', '11', '他 们 必 如 雀 鸟 从 埃 及 急 速 而 来 ， 又 如 鸽 子 从 亚 述 地 来 到 。 我 必 使 他 们 住 自 己 的 房 屋 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22253', '28', '11', '12', '＜ 以 色 列 和 犹 大 受 谴 责 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22254', '28', '12', '1', '以 法 莲 吃 风 ， 且 追 赶 东 风 ， 时 常 增 添 虚 谎 和 强 暴 ， 与 亚 述 立 约 ， 把 油 送 到 埃 及 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22255', '28', '12', '2', '耶 和 华 与 犹 大 争 辩 ， 必 照 雅 各 所 行 的 惩 罚 他 ， 按 他 所 做 的 报 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22256', '28', '12', '3', '他 在 腹 中 抓 住 哥 哥 的 脚 跟 ， 壮 年 的 时 候 与 神 较 力 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22257', '28', '12', '4', '与 天 使 较 力 ， 并 且 得 胜 ， 哭 泣 恳 求 ， 在 伯 特 利 遇 见 耶 和 华 。 耶 和 华 ─ ─ 万 军 之 神 在 那 里 晓 谕 我 们 以 色 列 人 ； 耶 和 华 是 他 可 记 念 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22258', '28', '12', '5', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22259', '28', '12', '6', '所 以 你 当 归 向 你 的 神 ， 谨 守 仁 爱 、 公 平 ， 常 常 等 候 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22260', '28', '12', '7', '＜ 其 他 的 判 词 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22261', '28', '12', '8', '以 法 莲 说 ： 我 果 然 成 了 富 足 ， 得 了 财 宝 ； 我 所 劳 碌 得 来 的 ， 人 必 不 见 有 什 么 不 义 ， 可 算 为 罪 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22262', '28', '12', '9', '自 从 你 出 埃 及 地 以 来 ， 我 就 是 耶 和 华 ─ ─ 你 的 神 ； 我 必 使 你 再 住 帐 棚 ， 如 在 大 会 的 日 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22263', '28', '12', '10', '我 已 晓 谕 众 先 知 ， 并 且 加 增 默 示 ， 藉 先 知 设 立 比 喻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22264', '28', '12', '11', '基 列 人 没 有 罪 孽 吗 ？ 他 们 全 然 是 虚 假 的 。 人 在 吉 甲 献 牛 犊 为 祭 ， 他 们 的 祭 坛 好 像 田 间 犁 沟 中 的 乱 堆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22265', '28', '12', '12', '从 前 雅 各 逃 到 亚 兰 地 ， 以 色 列 为 得 妻 服 事 人 ， 为 得 妻 与 人 放 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22266', '28', '12', '13', '耶 和 华 藉 先 知 领 以 色 列 从 埃 及 上 来 ； 以 色 列 也 藉 先 知 而 得 保 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22267', '28', '12', '14', '以 法 莲 大 大 惹 动 主 怒 ， 所 以 他 流 血 的 罪 必 归 在 他 身 上 。 主 必 将 那 因 以 法 莲 所 受 的 羞 辱 归 还 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22268', '28', '13', '1', '＜ 以 色 列 最 后 的 审 判 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22269', '28', '13', '2', '现 今 他 们 罪 上 加 罪 ， 用 银 子 为 自 己 铸 造 偶 像 ， 就 是 照 自 己 的 聪 明 制 造 ， 都 是 匠 人 的 工 作 。 有 人 论 说 ， 献 祭 的 人 可 以 向 牛 犊 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22270', '28', '13', '3', '因 此 ， 他 们 必 如 早 晨 的 云 雾 ， 又 如 速 散 的 甘 露 ， 像 场 上 的 糠 秕 被 狂 风 吹 去 ， 又 像 烟 气 腾 于 窗 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22271', '28', '13', '4', '自 从 你 出 埃 及 地 以 来 ， 我 就 是 耶 和 华 ─ ─ 你 的 神 。 在 我 以 外 ， 你 不 可 认 识 别 神 ； 除 我 以 外 并 没 有 救 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22272', '28', '13', '5', '我 曾 在 旷 野 干 旱 之 地 认 识 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22273', '28', '13', '6', '这 些 民 照 我 所 赐 的 食 物 得 了 饱 足 ； 既 得 饱 足 ， 心 就 高 傲 ， 忘 记 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22274', '28', '13', '7', '因 此 ， 我 向 他 们 如 狮 子 ， 又 如 豹 伏 在 道 旁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22275', '28', '13', '8', '我 遇 见 他 们 必 像 丢 崽 子 的 母 熊 ， 撕 裂 他 们 的 胸 膛 ｛ 或 译 ： 心 膜 ｝ 。 在 那 里 ， 我 必 像 母 狮 吞 吃 他 们 ； 野 兽 必 撕 裂 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22276', '28', '13', '9', '以 色 列 啊 ， 你 与 我 反 对 ， 就 是 反 对 帮 助 你 的 ， 自 取 败 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22277', '28', '13', '10', '你 曾 求 我 说 ： 给 我 立 王 和 首 领 。 现 在 你 的 王 在 哪 里 呢 ？ 治 理 你 的 在 哪 里 呢 ？ 让 他 在 你 所 有 的 城 中 拯 救 你 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22278', '28', '13', '11', '我 在 怒 气 中 将 王 赐 你 ， 又 在 烈 怒 中 将 王 废 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22279', '28', '13', '12', '以 法 莲 的 罪 孽 包 裹 ； 他 的 罪 恶 收 藏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22280', '28', '13', '13', '产 妇 的 疼 痛 必 临 到 他 身 上 ； 他 是 无 智 慧 之 子 ， 到 了 产 期 不 当 迟 延 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22281', '28', '13', '14', '我 必 救 赎 他 们 脱 离 阴 间 ， 救 赎 他 们 脱 离 死 亡 。 死 亡 啊 ， 你 的 灾 害 在 哪 里 呢 ？ 阴 间 哪 ， 你 的 毁 灭 在 哪 里 呢 ？ 在 我 眼 前 绝 无 后 悔 之 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22282', '28', '13', '15', '他 在 弟 兄 中 虽 然 茂 盛 ， 必 有 东 风 刮 来 ， 就 是 耶 和 华 的 风 从 旷 野 上 来 。 他 的 泉 源 必 干 ； 他 的 源 头 必 竭 ； 仇 敌 必 掳 掠 他 所 积 蓄 的 一 切 宝 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22283', '28', '13', '16', '撒 马 利 亚 必 担 当 自 己 的 罪 ， 因 为 悖 逆 她 的 神 。 她 必 倒 在 刀 下 ； 婴 孩 必 被 摔 死 ； 孕 妇 必 被 剖 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22284', '28', '14', '1', '＜ 何 西 阿 劝 告 以 色 列 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22285', '28', '14', '2', '当 归 向 耶 和 华 ， 用 言 语 祷 告 他 说 ： 求 你 除 净 罪 孽 ， 悦 纳 善 行 ； 这 样 ， 我 们 就 把 嘴 唇 的 祭 代 替 牛 犊 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22286', '28', '14', '3', '我 们 不 向 亚 述 求 救 ， 不 骑 埃 及 的 马 ， 也 不 再 对 我 们 手 所 造 的 说 ： 你 是 我 们 的 神 。 因 为 孤 儿 在 你 ─ ─ 耶 和 华 那 里 得 蒙 怜 悯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22287', '28', '14', '4', '＜ 耶 和 华 应 许 以 色 列 新 生 命 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22288', '28', '14', '5', '我 必 向 以 色 列 如 甘 露 ； 他 必 如 百 合 花 开 放 ， 如 黎 巴 嫩 的 树 木 扎 根 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22289', '28', '14', '6', '他 的 枝 条 必 延 长 ； 他 的 荣 华 如 橄 榄 树 ； 他 的 香 气 如 黎 巴 嫩 的 香 柏 树 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22290', '28', '14', '7', '曾 住 在 他 荫 下 的 必 归 回 ， 发 旺 如 五 谷 ， 开 花 如 葡 萄 树 。 他 的 香 气 如 黎 巴 嫩 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22291', '28', '14', '8', '以 法 莲 必 说 ： 我 与 偶 像 还 有 什 么 关 涉 呢 ？ 我 ─ ─ 耶 和 华 回 答 他 ， 也 必 顾 念 他 。 我 如 青 翠 的 松 树 ； 你 的 果 子 从 我 而 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22292', '28', '14', '9', '＜ 结 束 的 话 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22293', '29', '1', '1', '耶 和 华 的 话 临 到 毗 土 珥 的 儿 子 约 珥 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22294', '29', '1', '2', '＜ 人 民 因 收 成 受 损 坏 而 悲 伤 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22295', '29', '1', '3', '你 们 要 将 这 事 传 与 子 ， 子 传 与 孙 ， 孙 传 与 后 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22296', '29', '1', '4', '剪 虫 剩 下 的 ， 蝗 虫 来 吃 ； 蝗 虫 剩 下 的 ， 蝻 子 来 吃 ； 蝻 子 剩 下 的 ， 蚂 蚱 来 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22297', '29', '1', '5', '酒 醉 的 人 哪 ， 要 清 醒 哭 泣 ； 好 酒 的 人 哪 ， 都 要 为 甜 酒 哀 号 ， 因 为 从 你 们 的 口 中 断 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22298', '29', '1', '6', '有 一 队 蝗 虫 ｛ 原 文 是 民 ｝ 又 强 盛 又 无 数 ， 侵 犯 我 的 地 ； 它 的 牙 齿 如 狮 子 的 牙 齿 ， 大 牙 如 母 狮 的 大 牙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22299', '29', '1', '7', '它 毁 坏 我 的 葡 萄 树 ， 剥 了 我 无 花 果 树 的 皮 ， 剥 尽 而 丢 弃 ， 使 枝 条 露 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22300', '29', '1', '8', '我 的 民 哪 ， 你 当 哀 号 ， 像 处 女 腰 束 麻 布 ， 为 幼 年 的 丈 夫 哀 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22301', '29', '1', '9', '素 祭 和 奠 祭 从 耶 和 华 的 殿 中 断 绝 ； 事 奉 耶 和 华 的 祭 司 都 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22302', '29', '1', '10', '田 荒 凉 ， 地 悲 哀 ； 因 为 五 谷 毁 坏 ， 新 酒 干 竭 ， 油 也 缺 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22303', '29', '1', '11', '农 夫 啊 ， 你 们 要 惭 愧 ； 修 理 葡 萄 园 的 啊 ， 你 们 要 哀 号 ； 因 为 大 麦 小 麦 与 田 间 的 庄 稼 都 灭 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22304', '29', '1', '12', '葡 萄 树 枯 干 ； 无 花 果 树 衰 残 。 石 榴 树 、 棕 树 、 苹 果 树 ， 连 田 野 一 切 的 树 木 也 都 枯 干 ； 众 人 的 喜 乐 尽 都 消 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22305', '29', '1', '13', '祭 司 啊 ， 你 们 当 腰 束 麻 布 痛 哭 ； 伺 候 祭 坛 的 啊 ， 你 们 要 哀 号 ； 事 奉 我 神 的 啊 ， 你 们 要 来 披 上 麻 布 过 夜 ， 因 为 素 祭 和 奠 祭 从 你 们 神 的 殿 中 断 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22306', '29', '1', '14', '你 们 要 分 定 禁 食 的 日 子 ， 宣 告 严 肃 会 ， 招 聚 长 老 和 国 中 的 一 切 居 民 到 耶 和 华 ─ ─ 你 们 神 的 殿 ， 向 耶 和 华 哀 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22307', '29', '1', '15', '哀 哉 ！ 耶 和 华 的 日 子 临 近 了 。 这 日 来 到 ， 好 像 毁 灭 从 全 能 者 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22308', '29', '1', '16', '粮 食 不 是 在 我 们 眼 前 断 绝 了 吗 ？ 欢 喜 快 乐 不 是 从 我 们 神 的 殿 中 止 息 了 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22309', '29', '1', '17', '谷 种 在 土 块 下 朽 烂 ； 仓 也 荒 凉 ， 廪 也 破 坏 ； 因 为 五 谷 枯 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22310', '29', '1', '18', '牲 畜 哀 鸣 ； 牛 群 混 乱 ， 因 为 无 草 ； 羊 群 也 受 了 困 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22311', '29', '1', '19', '耶 和 华 啊 ， 我 向 你 求 告 ， 因 为 火 烧 灭 旷 野 的 草 场 ； 火 焰 烧 尽 田 野 的 树 木 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22312', '29', '1', '20', '田 野 的 走 兽 向 你 发 喘 ； 因 为 溪 水 干 涸 ， 火 也 烧 灭 旷 野 的 草 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22313', '29', '2', '1', '＜ 以 蝗 虫 为 耶 和 华 日 子 的 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22314', '29', '2', '2', '那 日 是 黑 暗 、 幽 冥 、 密 云 、 乌 黑 的 日 子 ， 好 像 晨 光 铺 满 山 岭 。 有 一 队 蝗 虫 ｛ 原 文 是 民 ｝ 又 大 又 强 ； 从 来 没 有 这 样 的 ， 以 后 直 到 万 代 也 必 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22315', '29', '2', '3', '它 们 前 面 如 火 烧 灭 ， 后 面 如 火 焰 烧 尽 。 未 到 以 前 ， 地 如 伊 甸 园 ； 过 去 以 后 ， 成 了 荒 凉 的 旷 野 ； 没 有 一 样 能 躲 避 它 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22316', '29', '2', '4', '它 们 的 形 状 如 马 ， 奔 跑 如 马 兵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22317', '29', '2', '5', '在 山 顶 蹦 跳 的 响 声 如 车 辆 的 响 声 ， 又 如 火 焰 烧 碎 秸 的 响 声 ， 好 像 强 盛 的 民 摆 阵 预 备 打 仗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22318', '29', '2', '6', '它 们 一 来 ， 众 民 伤 恸 ， 脸 都 变 色 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22319', '29', '2', '7', '它 们 如 勇 士 奔 跑 ， 像 战 士 爬 城 ； 各 都 步 行 ， 不 乱 队 伍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22320', '29', '2', '8', '彼 此 并 不 拥 挤 ， 向 前 各 行 其 路 ， 直 闯 兵 器 ， 不 偏 左 右 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22321', '29', '2', '9', '它 们 蹦 上 城 ， 蹿 上 墙 ， 爬 上 房 屋 ， 进 入 窗 户 如 同 盗 贼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22322', '29', '2', '10', '它 们 一 来 ， 地 震 天 动 ， 日 月 昏 暗 ， 星 宿 无 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22323', '29', '2', '11', '耶 和 华 在 他 军 旅 前 发 声 ， 他 的 队 伍 甚 大 ； 成 就 他 命 的 是 强 盛 者 。 因 为 耶 和 华 的 日 子 大 而 可 畏 ， 谁 能 当 得 起 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22324', '29', '2', '12', '＜ 呼 吁 人 民 悔 改 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22325', '29', '2', '13', '你 们 要 撕 裂 心 肠 ， 不 撕 裂 衣 服 。 归 向 耶 和 华 ─ ─ 你 们 的 神 ； 因 为 他 有 恩 典 ， 有 怜 悯 ， 不 轻 易 发 怒 ， 有 丰 盛 的 慈 爱 ， 并 且 后 悔 不 降 所 说 的 灾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22326', '29', '2', '14', '或 者 他 转 意 后 悔 ， 留 下 余 福 ， 就 是 留 下 献 给 耶 和 华 ─ ─ 你 们 神 的 素 祭 和 奠 祭 ， 也 未 可 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22327', '29', '2', '15', '你 们 要 在 锡 安 吹 角 ， 分 定 禁 食 的 日 子 ， 宣 告 严 肃 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22328', '29', '2', '16', '聚 集 众 民 ， 使 会 众 自 洁 ： 招 聚 老 者 ， 聚 集 孩 童 和 吃 奶 的 ； 使 新 郎 出 离 洞 房 ， 新 妇 出 离 内 室 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22329', '29', '2', '17', '事 奉 耶 和 华 的 祭 司 要 在 廊 子 和 祭 坛 中 间 哭 泣 ， 说 ： 耶 和 华 啊 ， 求 你 顾 惜 你 的 百 姓 ， 不 要 使 你 的 产 业 受 羞 辱 ， 列 邦 管 辖 他 们 。 为 何 容 列 国 的 人 说 ： “ 他 们 的 神 在 哪 里 ” 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22330', '29', '2', '18', '＜ 神 再 赐 福 泽 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22331', '29', '2', '19', '耶 和 华 应 允 他 的 百 姓 说 ： 我 必 赐 给 你 们 五 谷 、 新 酒 ， 和 油 ， 使 你 们 饱 足 ； 我 也 不 再 使 你 们 受 列 国 的 羞 辱 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22332', '29', '2', '20', '却 要 使 北 方 来 的 军 队 远 离 你 们 ， 将 他 们 赶 到 干 旱 荒 废 之 地 ： 前 队 赶 入 东 海 ， 后 队 赶 入 西 海 ； 因 为 他 们 所 行 的 大 恶 ｛ 原 文 是 事 ｝ ， 臭 气 上 升 ， 腥 味 腾 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22333', '29', '2', '21', '地 土 啊 ， 不 要 惧 怕 ； 要 欢 喜 快 乐 ， 因 为 耶 和 华 行 了 大 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22334', '29', '2', '22', '田 野 的 走 兽 啊 ， 不 要 惧 怕 ； 因 为 ， 旷 野 的 草 发 生 ， 树 木 结 果 ， 无 花 果 树 、 葡 萄 树 也 都 效 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22335', '29', '2', '23', '锡 安 的 民 哪 ， 你 们 要 快 乐 ， 为 耶 和 华 ─ ─ 你 们 的 神 欢 喜 ； 因 他 赐 给 你 们 合 宜 的 秋 雨 ， 为 你 们 降 下 甘 霖 ， 就 是 秋 雨 、 春 雨 ， 和 先 前 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22336', '29', '2', '24', '禾 场 必 满 了 麦 子 ； 酒 醡 与 油 醡 必 有 新 酒 和 油 盈 溢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22337', '29', '2', '25', '我 打 发 到 你 们 中 间 的 大 军 队 ， 就 是 蝗 虫 、 蝻 子 、 蚂 蚱 、 剪 虫 ， 那 些 年 所 吃 的 ， 我 要 补 还 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22338', '29', '2', '26', '你 们 必 多 吃 而 得 饱 足 ， 就 赞 美 为 你 们 行 奇 妙 事 之 耶 和 华 ─ ─ 你 们 神 的 名 。 我 的 百 姓 必 永 远 不 致 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22339', '29', '2', '27', '你 们 必 知 道 我 是 在 以 色 列 中 间 ， 又 知 道 我 是 耶 和 华 ─ ─ 你 们 的 神 ； 在 我 以 外 并 无 别 神 。 我 的 百 姓 必 永 远 不 致 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22340', '29', '2', '28', '＜ 耶 和 华 的 日 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22341', '29', '2', '29', '在 那 些 日 子 ， 我 要 将 我 的 灵 浇 灌 我 的 仆 人 和 使 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22342', '29', '2', '30', '“ 在 天 上 地 下 ， 我 要 显 出 奇 事 ， 有 血 ， 有 火 ， 有 烟 柱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22343', '29', '2', '31', '日 头 要 变 为 黑 暗 ， 月 亮 要 变 为 血 ， 这 都 在 耶 和 华 大 而 可 畏 的 日 子 未 到 以 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22344', '29', '2', '32', '到 那 时 候 ， 凡 求 告 耶 和 华 名 的 就 必 得 救 ； 因 为 照 耶 和 华 所 说 的 ， 在 锡 安 山 ， 耶 路 撒 冷 必 有 逃 脱 的 人 ， 在 剩 下 的 人 中 必 有 耶 和 华 所 召 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22345', '29', '3', '1', '＜ 神 要 审 判 万 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22346', '29', '3', '2', '我 要 聚 集 万 民 ， 带 他 们 下 到 约 沙 法 谷 ， 在 那 里 施 行 审 判 ； 因 为 他 们 将 我 的 百 姓 ， 就 是 我 的 产 业 以 色 列 ， 分 散 在 列 国 中 ， 又 分 取 我 的 地 土 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22347', '29', '3', '3', '且 为 我 的 百 姓 拈 阄 ， 将 童 子 换 妓 女 ， 卖 童 女 买 酒 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22348', '29', '3', '4', '“ 泰 尔 、 西 顿 ， 和 非 利 士 四 境 的 人 哪 ， 你 们 与 我 何 干 ？ 你 们 要 报 复 我 吗 ？ 若 报 复 我 ， 我 必 使 报 应 速 速 归 到 你 们 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22349', '29', '3', '5', '你 们 既 然 夺 取 我 的 金 银 ， 又 将 我 可 爱 的 宝 物 带 入 你 们 宫 殿 ｛ 或 译 ： 庙 中 ｝ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22350', '29', '3', '6', '并 将 犹 大 人 和 耶 路 撒 冷 人 卖 给 希 腊 人 ｛ 原 文 是 雅 完 人 ｝ ， 使 他 们 远 离 自 己 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22351', '29', '3', '7', '我 必 激 动 他 们 离 开 你 们 所 卖 到 之 地 ， 又 必 使 报 应 归 到 你 们 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22352', '29', '3', '8', '我 必 将 你 们 的 儿 女 卖 在 犹 大 人 的 手 中 ， 他 们 必 卖 给 远 方 示 巴 国 的 人 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22353', '29', '3', '9', '当 在 万 民 中 宣 告 说 ： 要 预 备 打 仗 ； 激 动 勇 士 ， 使 一 切 战 士 上 前 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22354', '29', '3', '10', '要 将 犁 头 打 成 刀 剑 ， 将 镰 刀 打 成 戈 矛 ； 软 弱 的 要 说 ： 我 有 勇 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22355', '29', '3', '11', '四 围 的 列 国 啊 ， 你 们 要 速 速 地 来 ， 一 同 聚 集 。 耶 和 华 啊 ， 求 你 使 你 的 大 能 者 降 临 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22356', '29', '3', '12', '万 民 都 当 兴 起 ， 上 到 约 沙 法 谷 ； 因 为 我 必 坐 在 那 里 ， 审 判 四 围 的 列 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22357', '29', '3', '13', '开 镰 吧 ！ 因 为 庄 稼 熟 了 ； 践 踏 吧 ！ 因 为 酒 醡 满 了 。 酒 池 盈 溢 ； 他 们 的 罪 恶 甚 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22358', '29', '3', '14', '许 多 许 多 的 人 在 断 定 谷 ， 因 为 耶 和 华 的 日 子 临 近 断 定 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22359', '29', '3', '15', '日 月 昏 暗 ， 星 宿 无 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22360', '29', '3', '16', '＜ 神 将 赐 福 给 他 的 子 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22361', '29', '3', '17', '你 们 就 知 道 我 是 耶 和 华 ─ ─ 你 们 的 神 ， 且 又 住 在 锡 安 ─ ─ 我 的 圣 山 。 那 时 ， 耶 路 撒 冷 必 成 为 圣 ； 外 邦 人 不 再 从 其 中 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22362', '29', '3', '18', '到 那 日 ， 大 山 要 滴 甜 酒 ； 小 山 要 流 奶 子 ； 犹 大 溪 河 都 有 水 流 。 必 有 泉 源 从 耶 和 华 的 殿 中 流 出 来 ， 滋 润 什 亭 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22363', '29', '3', '19', '埃 及 必 然 荒 凉 ， 以 东 变 为 凄 凉 的 旷 野 ， 都 因 向 犹 大 人 所 行 的 强 暴 ， 又 因 在 本 地 流 无 辜 人 的 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22364', '29', '3', '20', '但 犹 大 必 存 到 永 远 ； 耶 路 撒 冷 必 存 到 万 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22365', '29', '3', '21', '我 未 曾 报 复 ｛ 或 译 ： 洗 除 ； 下 同 ｝ 流 血 的 罪 ， 现 在 我 要 报 复 ， 因 为 耶 和 华 住 在 锡 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22366', '30', '1', '1', '当 犹 大 王 乌 西 雅 ， 以 色 列 王 约 阿 施 的 儿 子 耶 罗 波 安 在 位 的 时 候 ， 大 地 震 前 二 年 ， 提 哥 亚 牧 人 中 的 阿 摩 司 得 默 示 论 以 色 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22367', '30', '1', '2', '他 说 ： 耶 和 华 必 从 锡 安 吼 叫 ， 从 耶 路 撒 冷 发 声 ； 牧 人 的 草 场 要 悲 哀 ； 迦 密 的 山 顶 要 枯 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22368', '30', '1', '3', '＜ 神 审 判 以 色 列 的 邻 国 ─ ─ 亚 兰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22369', '30', '1', '4', '我 却 要 降 火 在 哈 薛 的 家 中 ， 烧 灭 便 ． 哈 达 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22370', '30', '1', '5', '我 必 折 断 大 马 士 革 的 门 闩 ， 剪 除 亚 文 平 原 的 居 民 和 伯 ． 伊 甸 掌 权 的 。 亚 兰 人 必 被 掳 到 吉 珥 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22371', '30', '1', '6', '＜ ─ ─ 非 利 士 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22372', '30', '1', '7', '我 却 要 降 火 在 迦 萨 的 城 内 ， 烧 灭 其 中 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22373', '30', '1', '8', '我 必 剪 除 亚 实 突 的 居 民 和 亚 实 基 伦 掌 权 的 ， 也 必 反 手 攻 击 以 革 伦 。 非 利 士 人 所 余 剩 的 必 都 灭 亡 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22374', '30', '1', '9', '＜ ─ ─ 泰 尔 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22375', '30', '1', '10', '我 却 要 降 火 在 泰 尔 的 城 内 ， 烧 灭 其 中 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22376', '30', '1', '11', '＜ ─ ─ 以 东 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22377', '30', '1', '12', '我 却 要 降 火 在 提 幔 ， 烧 灭 波 斯 拉 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22378', '30', '1', '13', '＜ ─ ─ 亚 扪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22379', '30', '1', '14', '我 却 要 在 争 战 呐 喊 的 日 子 ， 旋 风 狂 暴 的 时 候 ， 点 火 在 拉 巴 的 城 内 ， 烧 灭 其 中 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22380', '30', '1', '15', '他 们 的 王 和 首 领 必 一 同 被 掳 去 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22381', '30', '2', '1', '＜ ─ ─ 摩 押 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22382', '30', '2', '2', '我 却 要 降 火 在 摩 押 ， 烧 灭 加 略 的 宫 殿 。 摩 押 必 在 哄 嚷 呐 喊 吹 角 之 中 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22383', '30', '2', '3', '我 必 剪 除 摩 押 中 的 审 判 者 ， 将 其 中 的 一 切 首 领 和 他 一 同 杀 戮 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22384', '30', '2', '4', '＜ ─ ─ 犹 大 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22385', '30', '2', '5', '我 却 要 降 火 在 犹 大 ， 烧 灭 耶 路 撒 冷 的 宫 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22386', '30', '2', '6', '＜ 神 审 判 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22387', '30', '2', '7', '他 们 见 穷 人 头 上 所 蒙 的 灰 也 都 垂 涎 ， 阻 碍 谦 卑 人 的 道 路 。 父 子 同 一 个 女 子 行 淫 ， 亵 渎 我 的 圣 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22388', '30', '2', '8', '他 们 在 各 坛 旁 铺 人 所 当 的 衣 服 ， 卧 在 其 上 ， 又 在 他 们 神 的 庙 中 喝 受 罚 之 人 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22389', '30', '2', '9', '我 从 以 色 列 人 面 前 除 灭 亚 摩 利 人 。 他 虽 高 大 如 香 柏 树 ， 坚 固 如 橡 树 ， 我 却 上 灭 他 的 果 子 ， 下 绝 他 的 根 本 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22390', '30', '2', '10', '我 也 将 你 们 从 埃 及 地 领 上 来 ， 在 旷 野 引 导 你 们 四 十 年 ， 使 你 们 得 亚 摩 利 人 之 地 为 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22391', '30', '2', '11', '我 从 你 们 子 弟 中 兴 起 先 知 ， 又 从 你 们 少 年 人 中 兴 起 拿 细 耳 人 。 以 色 列 人 哪 ， 不 是 这 样 吗 ？ 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22392', '30', '2', '12', '你 们 却 给 拿 细 耳 人 酒 喝 ， 嘱 咐 先 知 说 ： 不 要 说 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22393', '30', '2', '13', '看 哪 ， 在 你 们 所 住 之 地 ， 我 必 压 你 们 ， 如 同 装 满 禾 捆 的 车 压 物 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22394', '30', '2', '14', '快 跑 的 不 能 逃 脱 ； 有 力 的 不 能 用 力 ； 刚 勇 的 也 不 能 自 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22395', '30', '2', '15', '拿 弓 的 不 能 站 立 ； 腿 快 的 不 能 逃 脱 ； 骑 马 的 也 不 能 自 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22396', '30', '2', '16', '到 那 日 ， 勇 士 中 最 有 胆 量 的 ， 必 赤 身 逃 跑 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22397', '30', '3', '1', '以 色 列 人 哪 ， 你 们 全 家 是 我 从 埃 及 地 领 上 来 的 ， 当 听 耶 和 华 攻 击 你 们 的 话 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22398', '30', '3', '2', '在 地 上 万 族 中 ， 我 只 认 识 你 们 ； 因 此 ， 我 必 追 讨 你 们 的 一 切 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22399', '30', '3', '3', '＜ 先 知 的 任 务 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22400', '30', '3', '4', '狮 子 若 非 抓 食 ， 岂 能 在 林 中 咆 哮 呢 ？ 少 壮 狮 子 若 无 所 得 ， 岂 能 从 洞 中 发 声 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22401', '30', '3', '5', '若 没 有 机 槛 ， 雀 鸟 岂 能 陷 在 网 罗 里 呢 ？ 网 罗 若 无 所 得 ， 岂 能 从 地 上 翻 起 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22402', '30', '3', '6', '城 中 若 吹 角 ， 百 姓 岂 不 惊 恐 呢 ？ 灾 祸 若 临 到 一 城 ， 岂 非 耶 和 华 所 降 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22403', '30', '3', '7', '主 耶 和 华 若 不 将 奥 秘 指 示 他 的 仆 人 ─ ─ 众 先 知 ， 就 一 无 所 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22404', '30', '3', '8', '狮 子 吼 叫 ， 谁 不 惧 怕 呢 ？ 主 耶 和 华 发 命 ， 谁 能 不 说 预 言 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22405', '30', '3', '9', '＜ 撒 马 利 亚 的 结 局 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22406', '30', '3', '10', '那 些 以 强 暴 抢 夺 财 物 、 积 蓄 在 自 己 家 中 的 人 不 知 道 行 正 直 的 事 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22407', '30', '3', '11', '所 以 主 耶 和 华 如 此 说 ： 敌 人 必 来 围 攻 这 地 ， 使 你 的 势 力 衰 微 ， 抢 掠 你 的 家 宅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22408', '30', '3', '12', '耶 和 华 如 此 说 ： “ 牧 人 怎 样 从 狮 子 口 中 抢 回 两 条 羊 腿 或 半 个 耳 朵 ， 住 撒 马 利 亚 的 以 色 列 人 躺 卧 在 床 角 上 或 铺 绣 花 毯 的 榻 上 ， 他 们 得 救 也 不 过 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22409', '30', '3', '13', '主 耶 和 华 ─ ─ 万 军 之 神 说 ： 当 听 这 话 ， 警 戒 雅 各 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22410', '30', '3', '14', '我 讨 以 色 列 罪 的 日 子 ， 也 要 讨 伯 特 利 祭 坛 的 罪 ； 坛 角 必 被 砍 下 ， 坠 落 于 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22411', '30', '3', '15', '我 要 拆 毁 过 冬 和 过 夏 的 房 屋 。 象 牙 的 房 屋 也 必 毁 灭 ； 高 大 的 房 屋 都 归 无 有 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22412', '30', '4', '1', '你 们 住 撒 马 利 亚 山 如 巴 珊 母 牛 的 啊 ， 当 听 我 的 话 ─ ─ 你 们 欺 负 贫 寒 的 ， 压 碎 穷 乏 的 ， 对 家 主 说 ： 拿 酒 来 ， 我 们 喝 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22413', '30', '4', '2', '主 耶 和 华 指 着 自 己 的 圣 洁 起 誓 说 ： 日 子 快 到 ， 人 必 用 钩 子 将 你 们 钩 去 ， 用 鱼 钩 将 你 们 余 剩 的 钩 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22414', '30', '4', '3', '你 们 各 人 必 从 破 口 直 往 前 行 ， 投 入 哈 门 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22415', '30', '4', '4', '＜ 以 色 列 的 失 败 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22416', '30', '4', '5', '任 你 们 献 有 酵 的 感 谢 祭 ， 把 甘 心 祭 宣 传 报 告 给 众 人 ， 因 为 是 你 们 所 喜 爱 的 。 这 是 主 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22417', '30', '4', '6', '我 使 你 们 在 一 切 城 中 牙 齿 干 净 ， 在 你 们 各 处 粮 食 缺 乏 ， 你 们 仍 不 归 向 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22418', '30', '4', '7', '在 收 割 的 前 三 月 ， 我 使 雨 停 止 ， 不 降 在 你 们 那 里 ； 我 降 雨 在 这 城 ， 不 降 雨 在 那 城 ； 这 块 地 有 雨 ， 那 块 地 无 雨 ； 无 雨 的 就 枯 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22419', '30', '4', '8', '这 样 ， 两 三 城 的 人 凑 到 一 城 去 找 水 ， 却 喝 不 足 ； 你 们 仍 不 归 向 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22420', '30', '4', '9', '我 以 旱 风 、 霉 烂 攻 击 你 们 ， 你 们 园 中 许 多 菜 蔬 、 葡 萄 树 、 无 花 果 树 、 橄 榄 树 都 被 剪 虫 所 吃 ； 你 们 仍 不 归 向 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22421', '30', '4', '10', '我 降 瘟 疫 在 你 们 中 间 ， 像 在 埃 及 一 样 ； 用 刀 杀 戮 你 们 的 少 年 人 ， 使 你 们 的 马 匹 被 掳 掠 ， 营 中 尸 首 的 臭 气 扑 鼻 ； 你 们 仍 不 归 向 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22422', '30', '4', '11', '我 倾 覆 你 们 中 间 的 城 邑 ， 如 同 我 从 前 倾 覆 所 多 玛 、 蛾 摩 拉 一 样 ， 使 你 们 好 像 从 火 中 抽 出 来 的 一 根 柴 ； 你 们 仍 不 归 向 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22423', '30', '4', '12', '以 色 列 啊 ， 我 必 向 你 如 此 行 ； 以 色 列 啊 ， 我 既 这 样 行 ， 你 当 预 备 迎 见 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22424', '30', '4', '13', '那 创 山 、 造 风 、 将 心 意 指 示 人 、 使 晨 光 变 为 幽 暗 、 脚 踏 在 地 之 高 处 的 ， 他 的 名 是 耶 和 华 ─ ─ 万 军 之 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22425', '30', '5', '1', '＜ 呼 吁 以 色 列 人 悔 改 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22426', '30', '5', '2', '以 色 列 民 ｛ 原 文 是 处 女 ｝ 跌 倒 ， 不 得 再 起 ； 躺 在 地 上 ， 无 人 搀 扶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22427', '30', '5', '3', '主 耶 和 华 如 此 说 ： 以 色 列 家 的 城 发 出 一 千 兵 的 ， 只 剩 一 百 ； 发 出 一 百 的 ， 只 剩 十 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22428', '30', '5', '4', '耶 和 华 向 以 色 列 家 如 此 说 ： 你 们 要 寻 求 我 ， 就 必 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22429', '30', '5', '5', '不 要 往 伯 特 利 寻 求 ， 不 要 进 入 吉 甲 ， 不 要 过 到 别 是 巴 ； 因 为 吉 甲 必 被 掳 掠 ， 伯 特 利 也 必 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22430', '30', '5', '6', '要 寻 求 耶 和 华 ， 就 必 存 活 ， 免 得 他 在 约 瑟 家 像 火 发 出 ， 在 伯 特 利 焚 烧 ， 无 人 扑 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22431', '30', '5', '7', '你 们 这 使 公 平 变 为 茵 蔯 、 将 公 义 丢 弃 于 地 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22432', '30', '5', '8', '要 寻 求 那 造 昴 星 和 参 星 ， 使 死 荫 变 为 晨 光 ， 使 白 日 变 为 黑 夜 ， 命 海 水 来 浇 在 地 上 的 ─ ─ 耶 和 华 是 他 的 名 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22433', '30', '5', '9', '他 使 力 强 的 忽 遭 灭 亡 ， 以 致 保 障 遭 遇 毁 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22434', '30', '5', '10', '你 们 怨 恨 那 在 城 门 口 责 备 人 的 ， 憎 恶 那 说 正 直 话 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22435', '30', '5', '11', '你 们 践 踏 贫 民 ， 向 他 们 勒 索 麦 子 ； 你 们 用 凿 过 的 石 头 建 造 房 屋 ， 却 不 得 住 在 其 内 ； 栽 种 美 好 的 葡 萄 园 ， 却 不 得 喝 所 出 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22436', '30', '5', '12', '我 知 道 你 们 的 罪 过 何 等 多 ， 你 们 的 罪 恶 何 等 大 。 你 们 苦 待 义 人 ， 收 受 贿 赂 ， 在 城 门 口 屈 枉 穷 乏 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22437', '30', '5', '13', '所 以 通 达 人 见 这 样 的 时 势 必 静 默 不 言 ， 因 为 时 势 真 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22438', '30', '5', '14', '你 们 要 求 善 ， 不 要 求 恶 ， 就 必 存 活 。 这 样 ， 耶 和 华 ─ ─ 万 军 之 神 必 照 你 们 所 说 的 与 你 们 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22439', '30', '5', '15', '要 恶 恶 好 善 ， 在 城 门 口 秉 公 行 义 ； 或 者 耶 和 华 ─ ─ 万 军 之 神 向 约 瑟 的 余 民 施 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22440', '30', '5', '16', '主 耶 和 华 ─ ─ 万 军 之 神 如 此 说 ： 在 一 切 宽 阔 处 必 有 哀 号 的 声 音 ； 在 各 街 市 上 必 有 人 说 ： 哀 哉 ！ 哀 哉 ！ 又 必 叫 农 夫 来 哭 号 ， 叫 善 唱 哀 歌 的 来 举 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22441', '30', '5', '17', '在 各 葡 萄 园 必 有 哀 号 的 声 音 ， 因 为 我 必 从 你 中 间 经 过 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22442', '30', '5', '18', '想 望 耶 和 华 日 子 来 到 的 有 祸 了 ！ 你 们 为 何 想 望 耶 和 华 的 日 子 呢 ？ 那 日 黑 暗 没 有 光 明 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22443', '30', '5', '19', '景 况 好 像 人 躲 避 狮 子 又 遇 见 熊 ， 或 是 进 房 屋 以 手 靠 墙 ， 就 被 蛇 咬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22444', '30', '5', '20', '耶 和 华 的 日 子 不 是 黑 暗 没 有 光 明 吗 ？ 不 是 幽 暗 毫 无 光 辉 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22445', '30', '5', '21', '我 厌 恶 你 们 的 节 期 ， 也 不 喜 悦 你 们 的 严 肃 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22446', '30', '5', '22', '你 们 虽 然 向 我 献 燔 祭 和 素 祭 ， 我 却 不 悦 纳 ， 也 不 顾 你 们 用 肥 畜 献 的 平 安 祭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22447', '30', '5', '23', '要 使 你 们 歌 唱 的 声 音 远 离 我 ， 因 为 我 不 听 你 们 弹 琴 的 响 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22448', '30', '5', '24', '惟 愿 公 平 如 大 水 滚 滚 ， 使 公 义 如 江 河 滔 滔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22449', '30', '5', '25', '“ 以 色 列 家 啊 ， 你 们 在 旷 野 四 十 年 ， 岂 是 将 祭 物 和 供 物 献 给 我 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22450', '30', '5', '26', '你 们 抬 着 为 自 己 所 造 之 摩 洛 的 帐 幕 和 偶 像 的 龛 ， 并 你 们 的 神 星 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22451', '30', '5', '27', '所 以 我 要 把 你 们 掳 到 大 马 士 革 以 外 。 ” 这 是 耶 和 华 ─ ─ 名 为 万 军 之 神 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22452', '30', '6', '1', '＜ 以 色 列 的 毁 灭 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22453', '30', '6', '2', '你 们 要 过 到 甲 尼 察 看 ， 从 那 里 往 大 城 哈 马 去 ， 又 下 到 非 利 士 人 的 迦 特 ， 看 那 些 国 比 你 们 的 国 还 强 吗 ？ 境 界 比 你 们 的 境 界 还 宽 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22454', '30', '6', '3', '你 们 以 为 降 祸 的 日 子 还 远 ， 坐 在 位 上 尽 行 强 暴 ｛ 或 译 ： 行 强 暴 使 审 判 临 近 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22455', '30', '6', '4', '你 们 躺 卧 在 象 牙 床 上 ， 舒 身 在 榻 上 ， 吃 群 中 的 羊 羔 ， 棚 里 的 牛 犊 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22456', '30', '6', '5', '弹 琴 鼓 瑟 唱 消 闲 的 歌 曲 ， 为 自 己 制 造 乐 器 ， 如 同 大 卫 所 造 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22457', '30', '6', '6', '以 大 碗 喝 酒 ， 用 上 等 的 油 抹 身 ， 却 不 为 约 瑟 的 苦 难 担 忧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22458', '30', '6', '7', '所 以 这 些 人 必 在 被 掳 的 人 中 首 先 被 掳 ； 舒 身 的 人 荒 宴 之 乐 必 消 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22459', '30', '6', '8', '主 耶 和 华 ─ ─ 万 军 之 神 指 着 自 己 起 誓 说 ： 我 憎 恶 雅 各 的 荣 华 ， 厌 弃 他 的 宫 殿 ； 因 此 ， 我 必 将 城 和 其 中 所 有 的 都 交 付 敌 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22460', '30', '6', '9', '那 时 ， 若 在 一 房 之 内 剩 下 十 个 人 ， 也 都 必 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22461', '30', '6', '10', '死 人 的 伯 叔 ， 就 是 烧 他 尸 首 的 ， 要 将 这 尸 首 搬 到 房 外 ， 问 房 屋 内 间 的 人 说 ： “ 你 那 里 还 有 人 没 有 ？ ” 他 必 说 ： “ 没 有 ” ； 又 说 ： “ 不 要 作 声 ， 因 为 我 们 不 可 提 耶 和 华 的 名 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22462', '30', '6', '11', '看 哪 ， 耶 和 华 出 令 ， 大 房 就 被 攻 破 ， 小 屋 就 被 打 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22463', '30', '6', '12', '马 岂 能 在 崖 石 上 奔 跑 ？ 人 岂 能 在 那 里 用 牛 耕 种 呢 ？ 你 们 却 使 公 平 变 为 苦 胆 ， 使 公 义 的 果 子 变 为 茵 蔯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22464', '30', '6', '13', '你 们 喜 爱 虚 浮 的 事 ， 自 夸 说 ： 我 们 不 是 凭 自 己 的 力 量 取 了 角 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22465', '30', '6', '14', '耶 和 华 、 万 军 之 神 说 ： 以 色 列 家 啊 ， 我 必 兴 起 一 国 攻 击 你 们 ； 他 们 必 欺 压 你 们 ， 从 哈 马 口 直 到 亚 拉 巴 的 河 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22466', '30', '7', '1', '＜ 蝗 虫 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22467', '30', '7', '2', '蝗 虫 吃 尽 那 地 的 青 物 ， 我 就 说 ： “ 主 耶 和 华 啊 ， 求 你 赦 免 ； 因 为 雅 各 微 弱 ， 他 怎 能 站 立 得 住 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22468', '30', '7', '3', '耶 和 华 就 后 悔 说 ： “ 这 灾 可 以 免 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22469', '30', '7', '4', '＜ 火 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22470', '30', '7', '5', '我 就 说 ： “ 主 耶 和 华 啊 ， 求 你 止 息 ； 因 为 雅 各 微 弱 ， 他 怎 能 站 立 得 住 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22471', '30', '7', '6', '耶 和 华 就 后 悔 说 ： “ 这 灾 也 可 免 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22472', '30', '7', '7', '＜ 准 绳 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22473', '30', '7', '8', '耶 和 华 对 我 说 ： “ 阿 摩 司 啊 ， 你 看 见 什 么 ？ ” 我 说 ： “ 看 见 准 绳 。 ” 主 说 ： “ 我 要 吊 起 准 绳 在 我 民 以 色 列 中 ； 我 必 不 再 宽 恕 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22474', '30', '7', '9', '以 撒 的 邱 坛 必 然 凄 凉 ； 以 色 列 的 圣 所 必 然 荒 废 。 我 必 兴 起 ， 用 刀 攻 击 耶 罗 波 安 的 家 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22475', '30', '7', '10', '＜ 阿 摩 司 和 亚 玛 谢 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22476', '30', '7', '11', '因 为 阿 摩 司 如 此 说 ： ‘ 耶 罗 波 安 必 被 刀 杀 ； 以 色 列 民 定 被 掳 去 离 开 本 地 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22477', '30', '7', '12', '亚 玛 谢 又 对 阿 摩 司 说 ： “ 你 这 先 见 哪 ， 要 逃 往 犹 大 地 去 ， 在 那 里 糊 口 ， 在 那 里 说 预 言 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22478', '30', '7', '13', '却 不 要 在 伯 特 利 再 说 预 言 ； 因 为 这 里 有 王 的 圣 所 ， 有 王 的 宫 殿 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22479', '30', '7', '14', '阿 摩 司 对 亚 玛 谢 说 ： “ 我 原 不 是 先 知 ， 也 不 是 先 知 的 门 徒 ｛ 原 文 是 儿 子 ｝ 。 我 是 牧 人 ， 又 是 修 理 桑 树 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22480', '30', '7', '15', '耶 和 华 选 召 我 ， 使 我 不 跟 从 羊 群 ， 对 我 说 ： ‘ 你 去 向 我 民 以 色 列 说 预 言 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22481', '30', '7', '16', '亚 玛 谢 啊 ， 现 在 你 要 听 耶 和 华 的 话 。 你 说 ： ‘ 不 要 向 以 色 列 说 预 言 ， 也 不 要 向 以 撒 家 滴 下 预 言 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22482', '30', '7', '17', '所 以 耶 和 华 如 此 说 ： ‘ 你 的 妻 子 必 在 城 中 作 妓 女 ； 你 的 儿 女 必 倒 在 刀 下 。 你 的 地 必 有 人 用 绳 子 量 了 分 取 ； 你 自 己 必 死 在 污 秽 之 地 。 以 色 列 民 定 被 掳 去 离 开 本 地 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22483', '30', '8', '1', '＜ 一 筐 水 果 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22484', '30', '8', '2', '他 说 ： “ 阿 摩 司 啊 ， 你 看 见 什 么 ？ ” 我 说 ： “ 看 见 一 筐 夏 天 的 果 子 。 ” 耶 和 华 说 ： “ 我 民 以 色 列 的 结 局 到 了 ， 我 必 不 再 宽 恕 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22485', '30', '8', '3', '主 耶 和 华 说 ： “ 那 日 ， 殿 中 的 诗 歌 变 为 哀 号 ； 必 有 许 多 尸 首 在 各 处 抛 弃 ， 无 人 作 声 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22486', '30', '8', '4', '＜ 以 色 列 的 结 局 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22487', '30', '8', '5', '你 们 说 ： 月 朔 几 时 过 去 ， 我 们 好 卖 粮 ； 安 息 日 几 时 过 去 ， 我 们 好 摆 开 麦 子 ； 卖 出 用 小 升 斗 ， 收 银 用 大 戥 子 ， 用 诡 诈 的 天 平 欺 哄 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22488', '30', '8', '6', '好 用 银 子 买 贫 寒 人 ， 用 一 双 鞋 换 穷 乏 人 ， 将 坏 了 的 麦 子 卖 给 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22489', '30', '8', '7', '耶 和 华 指 着 雅 各 的 荣 耀 起 誓 说 ： 他 们 的 一 切 行 为 ， 我 必 永 远 不 忘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22490', '30', '8', '8', '地 岂 不 因 这 事 震 动 ？ 其 上 的 居 民 不 也 悲 哀 吗 ？ 地 必 全 然 像 尼 罗 河 涨 起 ， 如 同 埃 及 河 涌 上 落 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22491', '30', '8', '9', '主 耶 和 华 说 ： 到 那 日 ， 我 必 使 日 头 在 午 间 落 下 ， 使 地 在 白 昼 黑 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22492', '30', '8', '10', '我 必 使 你 们 的 节 期 变 为 悲 哀 ， 歌 曲 变 为 哀 歌 。 众 人 腰 束 麻 布 ， 头 上 光 秃 ， 使 这 场 悲 哀 如 丧 独 生 子 ， 至 终 如 痛 苦 的 日 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22493', '30', '8', '11', '主 耶 和 华 说 ： 日 子 将 到 ， 我 必 命 饥 荒 降 在 地 上 。 人 饥 饿 非 因 无 饼 ， 干 渴 非 因 无 水 ， 乃 因 不 听 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22494', '30', '8', '12', '他 们 必 飘 流 ， 从 这 海 到 那 海 ， 从 北 边 到 东 边 ， 往 来 奔 跑 ， 寻 求 耶 和 华 的 话 ， 却 寻 不 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22495', '30', '8', '13', '当 那 日 ， 美 貌 的 处 女 和 少 年 的 男 子 必 因 干 渴 发 昏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22496', '30', '8', '14', '那 指 着 撒 马 利 亚 牛 犊 ｛ 原 文 是 罪 ｝ 起 誓 的 说 ： 但 哪 ， 我 们 指 着 你 那 里 的 活 神 起 誓 ； 又 说 ： 我 们 指 着 别 是 巴 的 神 道 ｛ 神 ： 原 文 是 活 ｝ 起 誓 。 这 些 人 都 必 仆 倒 ， 永 不 再 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22497', '30', '9', '1', '＜ 耶 和 华 的 审 判 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22498', '30', '9', '2', '他 们 虽 然 挖 透 阴 间 ， 我 的 手 必 取 出 他 们 来 ； 虽 然 爬 上 天 去 ， 我 必 拿 下 他 们 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22499', '30', '9', '3', '虽 然 藏 在 迦 密 山 顶 ， 我 必 搜 寻 ， 捉 出 他 们 来 ； 虽 然 从 我 眼 前 藏 在 海 底 ， 我 必 命 蛇 咬 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22500', '30', '9', '4', '虽 被 仇 敌 掳 去 ， 我 必 命 刀 剑 杀 戮 他 们 ； 我 必 向 他 们 定 住 眼 目 ， 降 祸 不 降 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22501', '30', '9', '5', '主 ─ ─ 万 军 之 耶 和 华 摸 地 ， 地 就 消 化 ， 凡 住 在 地 上 的 都 必 悲 哀 。 地 必 全 然 像 尼 罗 河 涨 起 ， 如 同 埃 及 河 落 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22502', '30', '9', '6', '那 在 天 上 建 造 楼 阁 、 在 地 上 安 定 穹 苍 、 命 海 水 浇 在 地 上 的 ─ ─ 耶 和 华 是 他 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22503', '30', '9', '7', '耶 和 华 说 ： 以 色 列 人 哪 ， 我 岂 不 看 你 们 如 古 实 人 吗 ？ 我 岂 不 是 领 以 色 列 人 出 埃 及 地 ， 领 非 利 士 人 出 迦 斐 托 ， 领 亚 兰 人 出 吉 珥 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22504', '30', '9', '8', '主 耶 和 华 的 眼 目 察 看 这 有 罪 的 国 ， 必 将 这 国 从 地 上 灭 绝 ， 却 不 将 雅 各 家 灭 绝 净 尽 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22505', '30', '9', '9', '我 必 出 令 ， 将 以 色 列 家 分 散 在 列 国 中 ， 好 像 用 筛 子 筛 谷 ， 连 一 粒 也 不 落 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22506', '30', '9', '10', '我 民 中 的 一 切 罪 人 说 ： 灾 祸 必 追 不 上 我 们 ， 也 迎 不 着 我 们 。 他 们 必 死 在 刀 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22507', '30', '9', '11', '＜ 以 色 列 的 未 来 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22508', '30', '9', '12', '使 以 色 列 人 得 以 东 所 余 剩 的 和 所 有 称 为 我 名 下 的 国 。 此 乃 行 这 事 的 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22509', '30', '9', '13', '耶 和 华 说 ： 日 子 将 到 ， 耕 种 的 必 接 续 收 割 的 ； 踹 葡 萄 的 必 接 续 撒 种 的 ； 大 山 要 滴 下 甜 酒 ； 小 山 都 必 流 奶 ｛ 原 文 是 消 化 ， 见 约 珥 三 章 十 八 节 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22510', '30', '9', '14', '我 必 使 我 民 以 色 列 被 掳 的 归 回 ； 他 们 必 重 修 荒 废 的 城 邑 居 住 ， 栽 种 葡 萄 园 ， 喝 其 中 所 出 的 酒 ， 修 造 果 木 园 ， 吃 其 中 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22511', '30', '9', '15', '我 要 将 他 们 栽 于 本 地 ， 他 们 不 再 从 我 所 赐 给 他 们 的 地 上 拔 出 来 。 这 是 耶 和 华 ─ ─ 你 的 神 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22512', '31', '1', '1', '俄 巴 底 亚 得 了 耶 和 华 的 默 示 。 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22513', '31', '1', '2', '我 使 你 ─ ─ 以 东 在 列 国 中 为 最 小 的 ， 被 人 大 大 藐 视 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22514', '31', '1', '3', '住 在 山 穴 中 、 居 所 在 高 处 的 啊 ， 你 因 狂 傲 自 欺 ， 心 里 说 ： 谁 能 将 我 拉 下 地 去 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22515', '31', '1', '4', '你 虽 如 大 鹰 高 飞 ， 在 星 宿 之 间 搭 窝 ， 我 必 从 那 里 拉 下 你 来 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22516', '31', '1', '5', '盗 贼 若 来 在 你 那 里 ， 或 强 盗 夜 间 而 来 ─ ─ 你 何 竟 被 剪 除 ─ ─ 岂 不 偷 窃 直 到 够 了 呢 ？ 摘 葡 萄 的 若 来 到 你 那 里 ， 岂 不 剩 下 些 葡 萄 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22517', '31', '1', '6', '以 扫 的 隐 密 处 何 竟 被 搜 寻 ？ 他 隐 藏 的 宝 物 何 竟 被 查 出 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22518', '31', '1', '7', '与 你 结 盟 的 都 送 你 上 路 ， 直 到 交 界 ； 与 你 和 好 的 欺 骗 你 ， 且 胜 过 你 ； 与 你 一 同 吃 饭 的 设 下 网 罗 陷 害 你 ； 在 你 心 里 毫 无 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22519', '31', '1', '8', '耶 和 华 说 ： 到 那 日 ， 我 岂 不 从 以 东 除 灭 智 慧 人 ？ 从 以 扫 山 除 灭 聪 明 人 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22520', '31', '1', '9', '提 幔 哪 ， 你 的 勇 士 必 惊 惶 ， 甚 至 以 扫 山 的 人 都 被 杀 戮 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22521', '31', '1', '10', '＜ 以 东 受 罚 的 原 因 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22522', '31', '1', '11', '当 外 人 掳 掠 雅 各 的 财 物 ， 外 邦 人 进 入 他 的 城 门 ， 为 耶 路 撒 冷 拈 阄 的 日 子 ， 你 竟 站 在 一 旁 ， 像 与 他 们 同 伙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22523', '31', '1', '12', '你 兄 弟 遭 难 的 日 子 ， 你 不 当 瞪 眼 看 着 ； 犹 大 人 被 灭 的 日 子 ， 你 不 当 因 此 欢 乐 ； 他 们 遭 难 的 日 子 ， 你 不 当 说 狂 傲 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22524', '31', '1', '13', '我 民 遭 灾 的 日 子 ， 你 不 当 进 他 们 的 城 门 ； 他 们 遭 灾 的 日 子 ， 你 不 当 瞪 眼 看 着 他 们 受 苦 ； 他 们 遭 灾 的 日 子 ， 你 不 当 伸 手 抢 他 们 的 财 物 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22525', '31', '1', '14', '你 不 当 站 在 岔 路 口 剪 除 他 们 中 间 逃 脱 的 ； 他 们 遭 难 的 日 子 ， 你 不 当 将 他 们 剩 下 的 人 交 付 仇 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22526', '31', '1', '15', '＜ 神 要 审 判 万 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22527', '31', '1', '16', '你 们 犹 大 人 在 我 圣 山 怎 样 喝 了 苦 杯 ， 万 国 也 必 照 样 常 常 地 喝 ； 且 喝 且 咽 ， 他 们 就 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22528', '31', '1', '17', '＜ 以 色 列 的 胜 利 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22529', '31', '1', '18', '雅 各 家 必 成 为 大 火 ； 约 瑟 家 必 为 火 焰 ； 以 扫 家 必 如 碎 秸 ； 火 必 将 他 烧 着 吞 灭 。 以 扫 家 必 无 余 剩 的 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22530', '31', '1', '19', '南 地 的 人 必 得 以 扫 山 ； 高 原 的 人 必 得 非 利 士 地 ， 也 得 以 法 莲 地 和 撒 马 利 亚 地 ； 便 雅 悯 人 必 得 基 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22531', '31', '1', '20', '在 迦 南 人 中 被 掳 的 以 色 列 众 人 必 得 地 直 到 撒 勒 法 ； 在 西 法 拉 中 被 掳 的 耶 路 撒 冷 人 必 得 南 地 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22532', '31', '1', '21', '必 有 拯 救 者 上 到 锡 安 山 ， 审 判 以 扫 山 ； 国 度 就 归 耶 和 华 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22533', '32', '1', '1', '＜ 约 拿 违 背 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22534', '32', '1', '2', '“ 你 起 来 往 尼 尼 微 大 城 去 ， 向 其 中 的 居 民 呼 喊 ， 因 为 他 们 的 恶 达 到 我 面 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22535', '32', '1', '3', '约 拿 却 起 来 ， 逃 往 他 施 去 躲 避 耶 和 华 ； 下 到 约 帕 ， 遇 见 一 只 船 ， 要 往 他 施 去 。 他 就 给 了 船 价 ， 上 了 船 ， 要 与 船 上 的 人 同 往 他 施 去 躲 避 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22536', '32', '1', '4', '然 而 耶 和 华 使 海 中 起 大 风 ， 海 就 狂 风 大 作 ， 甚 至 船 几 乎 破 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22537', '32', '1', '5', '水 手 便 惧 怕 ， 各 人 哀 求 自 己 的 神 。 他 们 将 船 上 的 货 物 抛 在 海 中 ， 为 要 使 船 轻 些 。 约 拿 已 下 到 底 舱 ， 躺 卧 沉 睡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22538', '32', '1', '6', '船 主 到 他 那 里 对 他 说 ： “ 你 这 沉 睡 的 人 哪 ， 为 何 这 样 呢 ？ 起 来 ， 求 告 你 的 神 ， 或 者 神 顾 念 我 们 ， 使 我 们 不 致 灭 亡 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22539', '32', '1', '7', '船 上 的 人 彼 此 说 ： “ 来 吧 ， 我 们 掣 签 ， 看 看 这 灾 临 到 我 们 是 因 谁 的 缘 故 。 ” 于 是 他 们 掣 签 ， 掣 出 约 拿 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22540', '32', '1', '8', '众 人 对 他 说 ： “ 请 你 告 诉 我 们 ， 这 灾 临 到 我 们 是 因 谁 的 缘 故 ？ 你 以 何 事 为 业 ？ 你 从 哪 里 来 ？ 你 是 哪 一 国 ？ 属 哪 一 族 的 人 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22541', '32', '1', '9', '他 说 ： “ 我 是 希 伯 来 人 。 我 敬 畏 耶 和 华 ─ ─ 那 创 造 沧 海 旱 地 之 天 上 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22542', '32', '1', '10', '他 们 就 大 大 惧 怕 ， 对 他 说 ： “ 你 做 的 是 什 么 事 呢 ？ ” 他 们 已 经 知 道 他 躲 避 耶 和 华 ， 因 为 他 告 诉 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22543', '32', '1', '11', '他 们 问 他 说 ： “ 我 们 当 向 你 怎 样 行 ， 使 海 浪 平 静 呢 ？ ” 这 话 是 因 海 浪 越 发 翻 腾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22544', '32', '1', '12', '他 对 他 们 说 ： “ 你 们 将 我 抬 起 来 ， 抛 在 海 中 ， 海 就 平 静 了 ； 我 知 道 你 们 遭 这 大 风 是 因 我 的 缘 故 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22545', '32', '1', '13', '然 而 那 些 人 竭 力 荡 桨 ， 要 把 船 拢 岸 ， 却 是 不 能 ， 因 为 海 浪 越 发 向 他 们 翻 腾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22546', '32', '1', '14', '他 们 便 求 告 耶 和 华 说 ： “ 耶 和 华 啊 ， 我 们 恳 求 你 ， 不 要 因 这 人 的 性 命 使 我 们 死 亡 ， 不 要 使 流 无 辜 血 的 罪 归 与 我 们 ； 因 为 你 ─ ─ 耶 和 华 是 随 自 己 的 意 旨 行 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22547', '32', '1', '15', '他 们 遂 将 约 拿 抬 起 ， 抛 在 海 中 ， 海 的 狂 浪 就 平 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22548', '32', '1', '16', '那 些 人 便 大 大 敬 畏 耶 和 华 ， 向 耶 和 华 献 祭 ， 并 且 许 愿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22549', '32', '1', '17', '耶 和 华 安 排 一 条 大 鱼 吞 了 约 拿 ， 他 在 鱼 腹 中 三 日 三 夜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22550', '32', '2', '1', '＜ 约 拿 的 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22551', '32', '2', '2', '说 ： 我 遭 遇 患 难 求 告 耶 和 华 ， 你 就 应 允 我 ； 从 阴 间 的 深 处 呼 求 ， 你 就 俯 听 我 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22552', '32', '2', '3', '你 将 我 投 下 深 渊 ， 就 是 海 的 深 处 ； 大 水 环 绕 我 ， 你 的 波 浪 洪 涛 都 漫 过 我 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22553', '32', '2', '4', '我 说 ： 我 从 你 眼 前 虽 被 驱 逐 ， 我 仍 要 仰 望 你 的 圣 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22554', '32', '2', '5', '诸 水 环 绕 我 ， 几 乎 淹 没 我 ； 深 渊 围 住 我 ； 海 草 缠 绕 我 的 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22555', '32', '2', '6', '我 下 到 山 根 ， 地 的 门 将 我 永 远 关 住 。 耶 和 华 ─ ─ 我 的 神 啊 ， 你 却 将 我 的 性 命 从 坑 中 救 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22556', '32', '2', '7', '我 心 在 我 里 面 发 昏 的 时 候 ， 我 就 想 念 耶 和 华 。 我 的 祷 告 进 入 你 的 圣 殿 ， 达 到 你 的 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22557', '32', '2', '8', '那 信 奉 虚 无 之 神 的 人 ， 离 弃 怜 爱 他 们 的 主 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22558', '32', '2', '9', '但 我 必 用 感 谢 的 声 音 献 祭 与 你 。 我 所 许 的 愿 ， 我 必 偿 还 。 救 恩 出 于 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22559', '32', '2', '10', '耶 和 华 吩 咐 鱼 ， 鱼 就 把 约 拿 吐 在 旱 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22560', '32', '3', '1', '＜ 约 拿 顺 服 耶 和 华 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22561', '32', '3', '2', '“ 你 起 来 ！ 往 尼 尼 微 大 城 去 ， 向 其 中 的 居 民 宣 告 我 所 吩 咐 你 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22562', '32', '3', '3', '约 拿 便 照 耶 和 华 的 话 起 来 ， 往 尼 尼 微 去 。 这 尼 尼 微 是 极 大 的 城 ， 有 三 日 的 路 程 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22563', '32', '3', '4', '约 拿 进 城 走 了 一 日 ， 宣 告 说 ： “ 再 等 四 十 日 ， 尼 尼 微 必 倾 覆 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22564', '32', '3', '5', '尼 尼 微 人 信 服 神 ， 便 宣 告 禁 食 ， 从 最 大 的 到 至 小 的 都 穿 麻 衣 ｛ 或 译 ： 披 上 麻 布 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22565', '32', '3', '6', '这 信 息 传 到 尼 尼 微 王 的 耳 中 ， 他 就 下 了 宝 座 ， 脱 下 朝 服 ， 披 上 麻 布 ， 坐 在 灰 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22566', '32', '3', '7', '他 又 使 人 遍 告 尼 尼 微 通 城 ， 说 ： “ 王 和 大 臣 有 令 ， 人 不 可 尝 什 么 ， 牲 畜 、 牛 羊 不 可 吃 草 ， 也 不 可 喝 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22567', '32', '3', '8', '人 与 牲 畜 都 当 披 上 麻 布 ； 人 要 切 切 求 告 神 。 各 人 回 头 离 开 所 行 的 恶 道 ， 丢 弃 手 中 的 强 暴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22568', '32', '3', '9', '或 者 神 转 意 后 悔 ， 不 发 烈 怒 ， 使 我 们 不 致 灭 亡 ， 也 未 可 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22569', '32', '3', '10', '于 是 神 察 看 他 们 的 行 为 ， 见 他 们 离 开 恶 道 ， 他 就 后 悔 ， 不 把 所 说 的 灾 祸 降 与 他 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22570', '32', '4', '1', '＜ 约 拿 的 忿 怒 和 神 的 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22571', '32', '4', '2', '就 祷 告 耶 和 华 说 ： “ 耶 和 华 啊 ， 我 在 本 国 的 时 候 岂 不 是 这 样 说 吗 ？ 我 知 道 你 是 有 恩 典 、 有 怜 悯 的 神 ， 不 轻 易 发 怒 ， 有 丰 盛 的 慈 爱 ， 并 且 后 悔 不 降 所 说 的 灾 ， 所 以 我 急 速 逃 往 他 施 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22572', '32', '4', '3', '耶 和 华 啊 ， 现 在 求 你 取 我 的 命 吧 ！ 因 为 我 死 了 比 活 着 还 好 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22573', '32', '4', '4', '耶 和 华 说 ： “ 你 这 样 发 怒 合 乎 理 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22574', '32', '4', '5', '于 是 约 拿 出 城 ， 坐 在 城 的 东 边 ， 在 那 里 为 自 己 搭 了 一 座 棚 ， 坐 在 棚 的 荫 下 ， 要 看 看 那 城 究 竟 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22575', '32', '4', '6', '耶 和 华 神 安 排 一 棵 蓖 麻 ， 使 其 发 生 高 过 约 拿 ， 影 儿 遮 盖 他 的 头 ， 救 他 脱 离 苦 楚 ； 约 拿 因 这 棵 蓖 麻 大 大 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22576', '32', '4', '7', '次 日 黎 明 ， 神 却 安 排 一 条 虫 子 咬 这 蓖 麻 ， 以 致 枯 槁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22577', '32', '4', '8', '日 头 出 来 的 时 候 ， 神 安 排 炎 热 的 东 风 ， 日 头 曝 晒 约 拿 的 头 ， 使 他 发 昏 ， 他 就 为 自 己 求 死 ， 说 ： “ 我 死 了 比 活 着 还 好 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22578', '32', '4', '9', '神 对 约 拿 说 ： “ 你 因 这 棵 蓖 麻 发 怒 合 乎 理 吗 ？ ” 他 说 ： “ 我 发 怒 以 至 于 死 ， 都 合 乎 理 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22579', '32', '4', '10', '耶 和 华 说 ： “ 这 蓖 麻 不 是 你 栽 种 的 ， 也 不 是 你 培 养 的 ； 一 夜 发 生 ， 一 夜 干 死 ， 你 尚 且 爱 惜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22580', '32', '4', '11', '何 况 这 尼 尼 微 大 城 ， 其 中 不 能 分 辨 左 手 右 手 的 有 十 二 万 多 人 ， 并 有 许 多 牲 畜 ， 我 岂 能 不 爱 惜 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22581', '33', '1', '1', '当 犹 大 王 约 坦 、 亚 哈 斯 、 希 西 家 在 位 的 时 候 ， 摩 利 沙 人 弥 迦 得 耶 和 华 的 默 示 ， 论 撒 马 利 亚 和 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22582', '33', '1', '2', '＜ 为 撒 马 利 亚 和 耶 路 撒 冷 唱 哀 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22583', '33', '1', '3', '看 哪 ， 耶 和 华 出 了 他 的 居 所 ， 降 临 步 行 地 的 高 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22584', '33', '1', '4', '众 山 在 他 以 下 必 消 化 ， 诸 谷 必 崩 裂 ， 如 蜡 化 在 火 中 ， 如 水 冲 下 山 坡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22585', '33', '1', '5', '这 都 因 雅 各 的 罪 过 ， 以 色 列 家 的 罪 恶 。 雅 各 的 罪 过 在 哪 里 呢 ？ 岂 不 是 在 撒 马 利 亚 吗 ？ 犹 大 的 邱 坛 在 哪 里 呢 ？ 岂 不 是 在 耶 路 撒 冷 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22586', '33', '1', '6', '所 以 我 必 使 撒 马 利 亚 变 为 田 野 的 乱 堆 ， 又 作 为 种 葡 萄 之 处 ； 也 必 将 她 的 石 头 倒 在 谷 中 ， 露 出 根 基 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22587', '33', '1', '7', '她 一 切 雕 刻 的 偶 像 必 被 打 碎 ； 她 所 得 的 财 物 必 被 火 烧 ； 所 有 的 偶 像 我 必 毁 灭 ； 因 为 是 从 妓 女 雇 价 所 聚 来 的 ， 后 必 归 为 妓 女 的 雇 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22588', '33', '1', '8', '先 知 说 ： 因 此 我 必 大 声 哀 号 ， 赤 脚 露 体 而 行 ； 又 要 呼 号 如 野 狗 ， 哀 鸣 如 鸵 鸟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22589', '33', '1', '9', '因 为 撒 马 利 亚 的 伤 痕 无 法 医 治 ， 延 及 犹 大 和 耶 路 撒 冷 我 民 的 城 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22590', '33', '1', '10', '＜ 敌 人 迫 近 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22591', '33', '1', '11', '沙 斐 的 居 民 哪 ， 你 们 要 赤 身 蒙 羞 过 去 。 撒 南 的 居 民 不 敢 出 来 。 伯 ． 以 薛 人 的 哀 哭 使 你 们 无 处 可 站 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22592', '33', '1', '12', '玛 律 的 居 民 心 甚 忧 急 ， 切 望 得 好 处 ， 因 为 灾 祸 从 耶 和 华 那 里 临 到 耶 路 撒 冷 的 城 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22593', '33', '1', '13', '拉 吉 的 居 民 哪 ， 要 用 快 马 套 车 ； 锡 安 民 ｛ 原 文 是 女 子 ｝ 的 罪 由 你 而 起 ； 以 色 列 人 的 罪 过 在 你 那 里 显 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22594', '33', '1', '14', '犹 大 啊 ， 你 要 将 礼 物 送 给 摩 利 设 ． 迦 特 。 亚 革 悉 的 众 族 必 用 诡 诈 待 以 色 列 诸 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22595', '33', '1', '15', '玛 利 沙 的 居 民 哪 ， 我 必 使 那 夺 取 你 的 来 到 你 这 里 ； 以 色 列 的 尊 贵 人 ｛ 原 文 是 荣 耀 ｝ 必 到 亚 杜 兰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22596', '33', '1', '16', '犹 大 啊 ， 要 为 你 所 喜 爱 的 儿 女 剪 除 你 的 头 发 ， 使 头 光 秃 ， 要 大 大 地 光 秃 ， 如 同 秃 鹰 ， 因 为 他 们 都 被 掳 去 离 开 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22597', '33', '2', '1', '＜ 剥 削 者 的 命 运 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22598', '33', '2', '2', '他 们 贪 图 田 地 就 占 据 ， 贪 图 房 屋 便 夺 取 ； 他 们 欺 压 人 ， 霸 占 房 屋 和 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22599', '33', '2', '3', '所 以 耶 和 华 如 此 说 ： 我 筹 划 灾 祸 降 与 这 族 ； 这 祸 在 你 们 的 颈 项 上 不 能 解 脱 ； 你 们 也 不 能 昂 首 而 行 ， 因 为 这 时 势 是 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22600', '33', '2', '4', '到 那 日 ， 必 有 人 向 你 们 提 起 悲 惨 的 哀 歌 ， 讥 刺 说 ： 我 们 全 然 败 落 了 ！ 耶 和 华 将 我 们 的 分 转 归 别 人 ， 何 竟 使 这 分 离 开 我 们 ？ 他 将 我 们 的 田 地 分 给 悖 逆 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22601', '33', '2', '5', '所 以 在 耶 和 华 的 会 中 ， 你 必 没 有 人 拈 阄 拉 准 绳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22602', '33', '2', '6', '他 们 ｛ 或 译 ： 假 先 知 ｝ 说 ： 你 们 不 可 说 预 言 ； 不 可 向 这 些 人 说 预 言 ， 不 住 地 羞 辱 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22603', '33', '2', '7', '雅 各 家 啊 ， 岂 可 说 耶 和 华 的 心 不 忍 耐 吗 ｛ 或 译 ： 心 肠 狭 窄 吗 ｝ ？ 这 些 事 是 他 所 行 的 吗 ？ 我 ─ ─ 耶 和 华 的 言 语 岂 不 是 与 行 动 正 直 的 人 有 益 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22604', '33', '2', '8', '然 而 ， 近 来 我 的 民 兴 起 如 仇 敌 ， 从 那 些 安 然 经 过 不 愿 打 仗 之 人 身 上 剥 去 外 衣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22605', '33', '2', '9', '你 们 将 我 民 中 的 妇 人 从 安 乐 家 中 赶 出 ， 又 将 我 的 荣 耀 从 她 们 的 小 孩 子 尽 行 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22606', '33', '2', '10', '你 们 起 来 去 吧 ！ 这 不 是 你 们 安 息 之 所 ； 因 为 污 秽 使 人 ｛ 或 译 ： 地 ｝ 毁 灭 ， 而 且 大 大 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22607', '33', '2', '11', '若 有 人 心 存 虚 假 ， 用 谎 言 说 ： 我 要 向 你 们 预 言 得 清 酒 和 浓 酒 。 那 人 就 必 作 这 民 的 先 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22608', '33', '2', '12', '雅 各 家 啊 ， 我 必 要 聚 集 你 们 ， 必 要 招 聚 以 色 列 剩 下 的 人 ， 安 置 在 一 处 ， 如 波 斯 拉 的 羊 ， 又 如 草 场 上 的 羊 群 ； 因 为 人 数 众 多 就 必 大 大 喧 哗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22609', '33', '2', '13', '开 路 的 ｛ 或 译 ： 破 城 的 ｝ 在 他 们 前 面 上 去 ； 他 们 直 闯 过 城 门 ， 从 城 门 出 去 。 他 们 的 王 在 前 面 行 ； 耶 和 华 引 导 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22610', '33', '3', '1', '＜ 弥 迦 斥 责 以 色 列 的 领 袖 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22611', '33', '3', '2', '你 们 恶 善 好 恶 ， 从 人 身 上 剥 皮 ， 从 人 骨 头 上 剔 肉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22612', '33', '3', '3', '吃 我 民 的 肉 ， 剥 他 们 的 皮 ， 打 折 他 们 的 骨 头 ， 分 成 块 子 像 要 下 锅 ， 又 像 釜 中 的 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22613', '33', '3', '4', '到 了 遭 灾 的 时 候 ， 这 些 人 必 哀 求 耶 和 华 ， 他 却 不 应 允 他 们 。 那 时 他 必 照 他 们 所 行 的 恶 事 向 他 们 掩 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22614', '33', '3', '5', '论 到 使 我 民 走 差 路 的 先 知 ─ ─ 他 们 牙 齿 有 所 嚼 的 ， 他 们 就 呼 喊 说 ： 平 安 了 ！ 凡 不 供 给 他 们 吃 的 ， 他 们 就 预 备 攻 击 他 ｛ 预 备 攻 击 他 ： 或 译 说 必 遭 遇 刀 兵 ｝ ─ ─ 耶 和 华 如 此 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22615', '33', '3', '6', '你 们 必 遭 遇 黑 夜 ， 以 致 不 见 异 象 ； 又 必 遭 遇 幽 暗 ， 以 致 不 能 占 卜 。 日 头 必 向 你 们 沉 落 ， 白 昼 变 为 黑 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22616', '33', '3', '7', '先 见 必 抱 愧 ， 占 卜 的 必 蒙 羞 ， 都 必 捂 着 嘴 唇 ， 因 为 神 不 应 允 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22617', '33', '3', '8', '至 于 我 ， 我 藉 耶 和 华 的 灵 ， 满 有 力 量 、 公 平 、 才 能 ， 可 以 向 雅 各 说 明 他 的 过 犯 ， 向 以 色 列 指 出 他 的 罪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22618', '33', '3', '9', '雅 各 家 的 首 领 、 以 色 列 家 的 官 长 啊 ， 当 听 我 的 话 ！ 你 们 厌 恶 公 平 ， 在 一 切 事 上 屈 枉 正 直 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22619', '33', '3', '10', '以 人 血 建 立 锡 安 ， 以 罪 孽 建 造 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22620', '33', '3', '11', '首 领 为 贿 赂 行 审 判 ； 祭 司 为 雇 价 施 训 诲 ； 先 知 为 银 钱 行 占 卜 。 他 们 却 倚 赖 耶 和 华 ， 说 ： 耶 和 华 不 是 在 我 们 中 间 吗 ？ 灾 祸 必 不 临 到 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22621', '33', '3', '12', '所 以 因 你 们 的 缘 故 ， 锡 安 必 被 耕 种 像 一 块 田 ， 耶 路 撒 冷 必 变 为 乱 堆 ； 这 殿 的 山 必 像 丛 林 的 高 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22622', '33', '4', '1', '＜ 耶 和 华 作 王 ， 天 下 太 平 （ 赛   2 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22623', '33', '4', '2', '必 有 许 多 国 的 民 前 往 ， 说 ： 来 吧 ， 我 们 登 耶 和 华 的 山 ， 奔 雅 各 神 的 殿 。 主 必 将 他 的 道 教 训 我 们 ； 我 们 也 要 行 他 的 路 。 因 为 训 诲 必 出 于 锡 安 ； 耶 和 华 的 言 语 必 出 于 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22624', '33', '4', '3', '他 必 在 多 国 的 民 中 施 行 审 判 ， 为 远 方 强 盛 的 国 断 定 是 非 。 他 们 要 将 刀 打 成 犁 头 ， 把 枪 打 成 镰 刀 。 这 国 不 举 刀 攻 击 那 国 ； 他 们 也 不 再 学 习 战 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22625', '33', '4', '4', '人 人 都 要 坐 在 自 己 葡 萄 树 下 和 无 花 果 树 下 ， 无 人 惊 吓 。 这 是 万 军 之 耶 和 华 亲 口 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22626', '33', '4', '5', '万 民 各 奉 己 神 的 名 而 行 ； 我 们 却 永 永 远 远 奉 耶 和 华 ─ ─ 我 们 神 的 名 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22627', '33', '4', '6', '＜ 以 色 列 人 归 回 本 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22628', '33', '4', '7', '我 必 使 瘸 腿 的 为 余 剩 之 民 ， 使 赶 到 远 方 的 为 强 盛 之 民 。 耶 和 华 要 在 锡 安 山 作 王 治 理 他 们 ， 从 今 直 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22629', '33', '4', '8', '你 这 羊 群 的 高 台 、 锡 安 城 ｛ 原 文 是 女 子 ｝ 的 山 哪 ， 从 前 的 权 柄 ─ ─ 就 是 耶 路 撒 冷 民 ｛ 原 文 是 女 子 ｝ 的 国 权 ─ ─ 必 归 与 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22630', '33', '4', '9', '现 在 你 为 何 大 声 哭 号 呢 ？ 疼 痛 抓 住 你 仿 佛 产 难 的 妇 人 ， 是 因 你 中 间 没 有 君 王 吗 ？ 你 的 谋 士 灭 亡 了 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22631', '33', '4', '10', '锡 安 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 你 要 疼 痛 劬 劳 ， 仿 佛 产 难 的 妇 人 ； 因 为 你 必 从 城 里 出 来 ， 住 在 田 野 ， 到 巴 比 伦 去 。 在 那 里 要 蒙 解 救 ； 在 那 里 耶 和 华 必 救 赎 你 脱 离 仇 敌 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22632', '33', '4', '11', '现 在 有 许 多 国 的 民 聚 集 攻 击 你 ， 说 ： 愿 锡 安 被 玷 污 ！ 愿 我 们 亲 眼 见 她 遭 报 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22633', '33', '4', '12', '他 们 却 不 知 道 耶 和 华 的 意 念 ， 也 不 明 白 他 的 筹 划 。 他 聚 集 他 们 ， 好 像 把 禾 捆 聚 到 禾 场 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22634', '33', '4', '13', '锡 安 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 起 来 踹 谷 吧 ！ 我 必 使 你 的 角 成 为 铁 ， 使 你 的 蹄 成 为 铜 。 你 必 打 碎 多 国 的 民 ， 将 他 们 的 财 献 与 耶 和 华 ， 将 他 们 的 货 献 与 普 天 下 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22635', '33', '5', '1', '成 群 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 现 在 你 要 聚 集 成 队 ； 因 为 仇 敌 围 攻 我 们 ， 要 用 杖 击 打 以 色 列 审 判 者 的 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22636', '33', '5', '2', '＜ 神 应 许 一 位 掌 权 者 出 于 伯 利 恒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22637', '33', '5', '3', '耶 和 华 必 将 以 色 列 人 交 付 敌 人 ， 直 等 那 生 产 的 妇 人 生 下 子 来 。 那 时 掌 权 者 ｛ 原 文 是 他 ｝ 其 余 的 弟 兄 必 归 到 以 色 列 人 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22638', '33', '5', '4', '他 必 起 来 ， 倚 靠 耶 和 华 的 大 能 ， 并 耶 和 华 ─ ─ 他 神 之 名 的 威 严 ， 牧 养 他 的 羊 群 。 他 们 要 安 然 居 住 ； 因 为 他 必 日 见 尊 大 ， 直 到 地 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22639', '33', '5', '5', '这 位 必 作 我 们 的 平 安 。 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22640', '33', '5', '6', '他 们 必 用 刀 剑 毁 坏 亚 述 地 和 宁 录 地 的 关 口 。 亚 述 人 进 入 我 们 的 地 境 践 踏 的 时 候 ， 他 必 拯 救 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22641', '33', '5', '7', '雅 各 余 剩 的 人 必 在 多 国 的 民 中 ， 如 从 耶 和 华 那 里 降 下 的 露 水 ， 又 如 甘 霖 降 在 草 上 ； 不 仗 赖 人 力 ， 也 不 等 候 世 人 之 功 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22642', '33', '5', '8', '雅 各 余 剩 的 人 必 在 多 国 多 民 中 ， 如 林 间 百 兽 中 的 狮 子 ， 又 如 少 壮 狮 子 在 羊 群 中 。 他 若 经 过 就 必 践 踏 撕 裂 ， 无 人 搭 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22643', '33', '5', '9', '愿 你 的 手 举 起 ， 高 过 敌 人 ！ 愿 你 的 仇 敌 都 被 剪 除 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22644', '33', '5', '10', '耶 和 华 说 ： 到 那 日 ， 我 必 从 你 中 间 剪 除 马 匹 ， 毁 坏 车 辆 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22645', '33', '5', '11', '也 必 从 你 国 中 除 灭 城 邑 ， 拆 毁 一 切 的 保 障 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22646', '33', '5', '12', '又 必 除 掉 你 手 中 的 邪 术 ； 你 那 里 也 不 再 有 占 卜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22647', '33', '5', '13', '我 必 从 你 中 间 除 灭 雕 刻 的 偶 像 和 柱 像 ， 你 就 不 再 跪 拜 自 己 手 所 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22648', '33', '5', '14', '我 必 从 你 中 间 拔 出 木 偶 ， 又 毁 灭 你 的 城 邑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22649', '33', '5', '15', '我 也 必 在 怒 气 和 忿 怒 中 向 那 不 听 从 的 列 国 施 报 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22650', '33', '6', '1', '＜ 耶 和 华 谴 责 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22651', '33', '6', '2', '山 岭 和 地 永 久 的 根 基 啊 ， 要 听 耶 和 华 争 辩 的 话 ！ 因 为 耶 和 华 要 与 他 的 百 姓 争 辩 ， 与 以 色 列 争 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22652', '33', '6', '3', '我 的 百 姓 啊 ， 我 向 你 做 了 什 么 呢 ？ 我 在 什 么 事 上 使 你 厌 烦 ？ 你 可 以 对 我 证 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22653', '33', '6', '4', '我 曾 将 你 从 埃 及 地 领 出 来 ， 从 作 奴 仆 之 家 救 赎 你 ； 我 也 差 遣 摩 西 、 亚 伦 ， 和 米 利 暗 在 你 前 面 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22654', '33', '6', '5', '我 的 百 姓 啊 ， 你 们 当 追 念 摩 押 王 巴 勒 所 设 的 谋 和 比 珥 的 儿 子 巴 兰 回 答 他 的 话 ， 并 你 们 从 什 亭 到 吉 甲 所 遇 见 的 事 ， 好 使 你 们 知 道 耶 和 华 公 义 的 作 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22655', '33', '6', '6', '＜ 神 的 要 求 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22656', '33', '6', '7', '耶 和 华 岂 喜 悦 千 千 的 公 羊 ， 或 是 万 万 的 油 河 吗 ？ 我 岂 可 为 自 己 的 罪 过 献 我 的 长 子 吗 ？ 为 心 中 的 罪 恶 献 我 身 所 生 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22657', '33', '6', '8', '世 人 哪 ， 耶 和 华 已 指 示 你 何 为 善 。 他 向 你 所 要 的 是 什 么 呢 ？ 只 要 你 行 公 义 ， 好 怜 悯 ， 存 谦 卑 的 心 ， 与 你 的 神 同 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22658', '33', '6', '9', '耶 和 华 向 这 城 呼 叫 ， 智 慧 人 必 敬 畏 他 的 名 。 你 们 当 听 是 谁 派 定 刑 杖 的 惩 罚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22659', '33', '6', '10', '恶 人 家 中 不 仍 有 非 义 之 财 和 可 恶 的 小 升 斗 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22660', '33', '6', '11', '我 若 用 不 公 道 的 天 平 和 囊 中 诡 诈 的 法 码 ， 岂 可 算 为 清 洁 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22661', '33', '6', '12', '城 里 的 富 户 满 行 强 暴 ； 其 中 的 居 民 也 说 谎 言 ， 口 中 的 舌 头 是 诡 诈 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22662', '33', '6', '13', '因 此 ， 我 击 打 你 ， 使 你 的 伤 痕 甚 重 ， 使 你 因 你 的 罪 恶 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22663', '33', '6', '14', '你 要 吃 ， 却 吃 不 饱 ； 你 的 虚 弱 必 显 在 你 中 间 。 你 必 挪 去 ， 却 不 得 救 护 ； 所 救 护 的 ， 我 必 交 给 刀 剑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22664', '33', '6', '15', '你 必 撒 种 ， 却 不 得 收 割 ； 踹 橄 榄 ， 却 不 得 油 抹 身 ； 踹 葡 萄 ， 却 不 得 酒 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22665', '33', '6', '16', '因 为 你 守 暗 利 的 恶 规 ， 行 亚 哈 家 一 切 所 行 的 ， 顺 从 他 们 的 计 谋 ； 因 此 ， 我 必 使 你 荒 凉 ， 使 你 的 居 民 令 人 嗤 笑 ， 你 们 也 必 担 当 我 民 的 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22666', '33', '7', '1', '＜ 以 色 列 人 的 腐 败 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22667', '33', '7', '2', '地 上 虔 诚 人 灭 尽 ； 世 间 没 有 正 直 人 ； 各 人 埋 伏 ， 要 杀 人 流 血 ， 都 用 网 罗 猎 取 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22668', '33', '7', '3', '他 们 双 手 作 恶 ； 君 王 徇 情 面 ， 审 判 官 要 贿 赂 ； 位 分 大 的 吐 出 恶 意 ， 都 彼 此 结 联 行 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22669', '33', '7', '4', '他 们 最 好 的 ， 不 过 是 蒺 藜 ； 最 正 直 的 ， 不 过 是 荆 棘 篱 笆 。 你 守 望 者 说 ， 降 罚 的 日 子 已 经 来 到 。 他 们 必 扰 乱 不 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22670', '33', '7', '5', '不 要 倚 赖 邻 舍 ； 不 要 信 靠 密 友 。 要 守 住 你 的 口 ； 不 要 向 你 怀 中 的 妻 提 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22671', '33', '7', '6', '因 为 ， 儿 子 藐 视 父 亲 ； 女 儿 抗 拒 母 亲 ； 媳 妇 抗 拒 婆 婆 ； 人 的 仇 敌 就 是 自 己 家 里 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22672', '33', '7', '7', '至 于 我 ， 我 要 仰 望 耶 和 华 ， 要 等 候 那 救 我 的 神 ； 我 的 神 必 应 允 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22673', '33', '7', '8', '＜ 神 赐 救 恩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22674', '33', '7', '9', '我 要 忍 受 耶 和 华 的 恼 怒 ； 因 我 得 罪 了 他 ， 直 等 他 为 我 辨 屈 ， 为 我 伸 冤 。 他 必 领 我 到 光 明 中 ； 我 必 得 见 他 的 公 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22675', '33', '7', '10', '那 时 我 的 仇 敌 ， 就 是 曾 对 我 说 “ 耶 和 华 ─ ─ 你 神 在 哪 里 ” 的 ， 他 一 看 见 这 事 就 被 羞 愧 遮 盖 。 我 必 亲 眼 见 他 遭 报 ； 他 必 被 践 踏 ， 如 同 街 上 的 泥 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22676', '33', '7', '11', '以 色 列 啊 ， 日 子 必 到 ， 你 的 墙 垣 必 重 修 ； 到 那 日 ， 你 的 境 界 必 开 展 ｛ 或 译 ： 命 令 必 传 到 远 方 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22677', '33', '7', '12', '当 那 日 ， 人 必 从 亚 述 ， 从 埃 及 的 城 邑 ， 从 埃 及 到 大 河 ， 从 这 海 到 那 海 ， 从 这 山 到 那 山 ， 都 归 到 你 这 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22678', '33', '7', '13', '然 而 ， 这 地 因 居 民 的 缘 故 ， 又 因 他 们 行 事 的 结 果 ， 必 然 荒 凉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22679', '33', '7', '14', '＜ 耶 和 华 怜 悯 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22680', '33', '7', '15', '耶 和 华 说 ： 我 要 把 奇 事 显 给 他 们 看 ， 好 像 出 埃 及 地 的 时 候 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22681', '33', '7', '16', '列 国 看 见 这 事 就 必 为 自 己 的 势 力 惭 愧 ； 他 们 必 用 手 捂 口 ， 掩 耳 不 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22682', '33', '7', '17', '他 们 必 舔 土 如 蛇 ， 又 如 土 中 腹 行 的 物 ， 战 战 兢 兢 地 出 他 们 的 营 寨 。 他 们 必 战 惧 投 降 耶 和 华 ， 也 必 因 我 们 的 神 而 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22683', '33', '7', '18', '神 啊 ， 有 何 神 像 你 ， 赦 免 罪 孽 ， 饶 恕 你 产 业 之 余 民 的 罪 过 ， 不 永 远 怀 怒 ， 喜 爱 施 恩 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22684', '33', '7', '19', '必 再 怜 悯 我 们 ， 将 我 们 的 罪 孽 踏 在 脚 下 ， 又 将 我 们 的 一 切 罪 投 于 深 海 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22685', '33', '7', '20', '你 必 按 古 时 起 誓 应 许 我 们 列 祖 的 话 ， 向 雅 各 发 诚 实 ， 向 亚 伯 拉 罕 施 慈 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22686', '34', '1', '1', '论 尼 尼 微 的 默 示 ， 就 是 伊 勒 歌 斯 人 那 鸿 所 得 的 默 示 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22687', '34', '1', '2', '＜ 耶 和 华 向 尼 尼 微 发 怒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22688', '34', '1', '3', '耶 和 华 不 轻 易 发 怒 ， 大 有 能 力 ， 万 不 以 有 罪 的 为 无 罪 。 他 乘 旋 风 和 暴 风 而 来 ， 云 彩 为 他 脚 下 的 尘 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22689', '34', '1', '4', '他 斥 责 海 ， 使 海 干 了 ， 使 一 切 江 河 干 涸 。 巴 珊 和 迦 密 的 树 林 衰 残 ； 黎 巴 嫩 的 花 草 也 衰 残 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22690', '34', '1', '5', '大 山 因 他 震 动 ； 小 山 也 都 消 化 。 大 地 在 他 面 前 突 起 ； 世 界 和 住 在 其 间 的 也 都 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22691', '34', '1', '6', '他 发 忿 恨 ， 谁 能 立 得 住 呢 ？ 他 发 烈 怒 ， 谁 能 当 得 起 呢 ？ 他 的 忿 怒 如 火 倾 倒 ； 磐 石 因 他 崩 裂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22692', '34', '1', '7', '耶 和 华 本 为 善 ， 在 患 难 的 日 子 为 人 的 保 障 ， 并 且 认 得 那 些 投 靠 他 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22693', '34', '1', '8', '但 他 必 以 涨 溢 的 洪 水 淹 没 尼 尼 微 ， 又 驱 逐 仇 敌 进 入 黑 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22694', '34', '1', '9', '尼 尼 微 人 哪 ， 设 何 谋 攻 击 耶 和 华 呢 ？ 他 必 将 你 们 灭 绝 净 尽 ； 灾 难 不 再 兴 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22695', '34', '1', '10', '你 们 像 丛 杂 的 荆 棘 ， 像 喝 醉 了 的 人 ， 又 如 枯 干 的 碎 秸 全 然 烧 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22696', '34', '1', '11', '有 一 人 从 你 那 里 出 来 ， 图 谋 邪 恶 ， 设 恶 计 攻 击 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22697', '34', '1', '12', '耶 和 华 如 此 说 ： 尼 尼 微 虽 然 势 力 充 足 ， 人 数 繁 多 ， 也 被 剪 除 ， 归 于 无 有 。 犹 大 啊 ， 我 虽 然 使 你 受 苦 ， 却 不 再 使 你 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22698', '34', '1', '13', '现 在 我 必 从 你 颈 项 上 折 断 他 的 轭 ， 扭 开 他 的 绳 索 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22699', '34', '1', '14', '耶 和 华 已 经 出 令 ， 指 着 尼 尼 微 说 ： 你 名 下 的 人 必 不 留 后 ； 我 必 从 你 神 的 庙 中 除 灭 雕 刻 的 偶 像 和 铸 造 的 偶 像 ； 我 必 因 你 鄙 陋 ， 使 你 归 于 坟 墓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22700', '34', '1', '15', '看 哪 ， 有 报 好 信 传 平 安 之 人 的 脚 登 山 ， 说 ： 犹 大 啊 ， 可 以 守 你 的 节 期 ， 还 你 所 许 的 愿 吧 ！ 因 为 那 恶 人 不 再 从 你 中 间 经 过 ， 他 已 灭 绝 净 尽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22701', '34', '2', '1', '＜ 尼 尼 微 的 倾 覆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22702', '34', '2', '2', '（ 耶 和 华 复 兴 雅 各 的 荣 华 ， 好 像 以 色 列 的 荣 华 一 样 ； 因 为 使 地 空 虚 的 ， 已 经 使 雅 各 和 以 色 列 空 虚 ， 将 他 们 的 葡 萄 枝 毁 坏 了 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22703', '34', '2', '3', '他 勇 士 的 盾 牌 是 红 的 ， 精 兵 都 穿 朱 红 衣 服 。 在 他 预 备 争 战 的 日 子 ， 战 车 上 的 钢 铁 闪 烁 如 火 ， 柏 木 把 的 枪 也 抡 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22704', '34', '2', '4', '车 辆 在 街 上 ｛ 或 译 ： 城 外 ｝ 急 行 ， 在 宽 阔 处 奔 来 奔 去 ， 形 状 如 火 把 ， 飞 跑 如 闪 电 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22705', '34', '2', '5', '尼 尼 微 王 招 聚 他 的 贵 胄 ； 他 们 步 行 绊 跌 ， 速 上 城 墙 ， 预 备 挡 牌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22706', '34', '2', '6', '河 闸 开 放 ， 宫 殿 冲 没 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22707', '34', '2', '7', '王 后 蒙 羞 ， 被 人 掳 去 ； 宫 女 捶 胸 ， 哀 鸣 如 鸽 。 此 乃 命 定 之 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22708', '34', '2', '8', '尼 尼 微 自 古 以 来 充 满 人 民 ， 如 同 聚 水 的 池 子 ； 现 在 居 民 却 都 逃 跑 。 虽 有 人 呼 喊 说 ： 站 住 ！ 站 住 ！ 却 无 人 回 顾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22709', '34', '2', '9', '你 们 抢 掠 金 银 吧 ！ 因 为 所 积 蓄 的 无 穷 ， 华 美 的 宝 器 无 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22710', '34', '2', '10', '尼 尼 微 现 在 空 虚 荒 凉 ， 人 心 消 化 ， 双 膝 相 碰 ， 腰 都 疼 痛 ， 脸 都 变 色 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22711', '34', '2', '11', '狮 子 的 洞 和 少 壮 狮 子 喂 养 之 处 在 哪 里 呢 ？ 公 狮 母 狮 小 狮 游 行 、 无 人 惊 吓 之 地 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22712', '34', '2', '12', '公 狮 为 小 狮 撕 碎 许 多 食 物 ， 为 母 狮 掐 死 活 物 ， 把 撕 碎 的 、 掐 死 的 充 满 它 的 洞 穴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22713', '34', '2', '13', '万 军 之 耶 和 华 说 ： “ 我 与 你 为 敌 ， 必 将 你 的 车 辆 焚 烧 成 烟 ， 刀 剑 也 必 吞 灭 你 的 少 壮 狮 子 。 我 必 从 地 上 除 灭 你 所 撕 碎 的 ， 你 使 者 的 声 音 必 不 再 听 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22714', '34', '3', '1', '祸 哉 ！ 这 流 人 血 的 城 ， 充 满 谎 诈 和 强 暴 ─ ─ 抢 夺 的 事 总 不 止 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22715', '34', '3', '2', '鞭 声 响 亮 ， 车 轮 轰 轰 ， 马 匹 踢 跳 ， 车 辆 奔 腾 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22716', '34', '3', '3', '马 兵 争 先 ， 刀 剑 发 光 ， 枪 矛 闪 烁 ， 被 杀 的 甚 多 ， 尸 首 成 了 大 堆 ， 尸 骸 无 数 ， 人 碰 着 而 跌 倒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22717', '34', '3', '4', '都 因 那 美 貌 的 妓 女 多 有 淫 行 ， 惯 行 邪 术 ， 藉 淫 行 诱 惑 列 国 ， 用 邪 术 诱 惑 ｛ 原 文 是 卖 ｝ 多 族 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22718', '34', '3', '5', '万 军 之 耶 和 华 说 ： 我 与 你 为 敌 ； 我 必 揭 起 你 的 衣 襟 ， 蒙 在 你 脸 上 ， 使 列 国 看 见 你 的 赤 体 ， 使 列 邦 观 看 你 的 丑 陋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22719', '34', '3', '6', '我 必 将 可 憎 污 秽 之 物 抛 在 你 身 上 ， 辱 没 你 ， 为 众 目 所 观 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22720', '34', '3', '7', '凡 看 见 你 的 ， 都 必 逃 跑 离 开 你 ， 说 ： 尼 尼 微 荒 凉 了 ！ 有 谁 为 你 悲 伤 呢 ？ 我 何 处 寻 得 安 慰 你 的 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22721', '34', '3', '8', '你 岂 比 挪 亚 们 强 呢 ？ 挪 亚 们 坐 落 在 众 河 之 间 ， 周 围 有 水 ； 海 ｛ 指 尼 罗 河 ｝ 作 她 的 濠 沟 ， 又 作 她 的 城 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22722', '34', '3', '9', '古 实 和 埃 及 是 她 无 穷 的 力 量 ； 弗 人 和 路 比 族 是 她 的 帮 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22723', '34', '3', '10', '但 她 被 迁 移 ， 被 掳 去 ； 她 的 婴 孩 在 各 市 口 上 也 被 摔 死 。 人 为 她 的 尊 贵 人 拈 阄 ； 她 所 有 的 大 人 都 被 链 子 锁 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22724', '34', '3', '11', '你 也 必 喝 醉 ， 必 被 埋 藏 ， 并 因 仇 敌 的 缘 故 寻 求 避 难 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22725', '34', '3', '12', '你 一 切 保 障 必 像 无 花 果 树 上 初 熟 的 无 花 果 ， 若 一 摇 撼 就 落 在 想 吃 之 人 的 口 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22726', '34', '3', '13', '你 地 上 的 人 民 如 同 妇 女 ； 你 国 中 的 关 口 向 仇 敌 敞 开 ； 你 的 门 闩 被 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22727', '34', '3', '14', '你 要 打 水 预 备 受 困 ； 要 坚 固 你 的 保 障 ， 踹 土 和 泥 ， 修 补 砖 窑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22728', '34', '3', '15', '在 那 里 ， 火 必 烧 灭 你 ； 刀 必 杀 戮 你 ， 吞 灭 你 如 同 蝻 子 。 任 你 加 增 人 数 多 如 蝻 子 ， 多 如 蝗 虫 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22729', '34', '3', '16', '你 增 添 商 贾 ， 多 过 天 上 的 星 ； 蝻 子 吃 尽 而 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22730', '34', '3', '17', '你 的 首 领 多 如 蝗 虫 ； 你 的 军 长 仿 佛 成 群 的 蚂 蚱 ， 天 凉 的 时 候 齐 落 在 篱 笆 上 ， 日 头 一 出 便 都 飞 去 ， 人 不 知 道 落 在 何 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22731', '34', '3', '18', '亚 述 王 啊 ， 你 的 牧 人 睡 觉 ； 你 的 贵 胄 安 歇 ； 你 的 人 民 散 在 山 间 ， 无 人 招 聚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22732', '34', '3', '19', '你 的 损 伤 无 法 医 治 ； 你 的 伤 痕 极 其 重 大 。 凡 听 你 信 息 的 必 都 因 此 向 你 拍 掌 。 你 所 行 的 恶 谁 没 有 时 常 遭 遇 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22733', '35', '1', '1', '先 知 哈 巴 谷 所 得 的 默 示 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22734', '35', '1', '2', '＜ 哈 巴 谷 为 不 公 平 而 诉 苦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22735', '35', '1', '3', '你 为 何 使 我 看 见 罪 孽 ？ 你 为 何 看 着 奸 恶 而 不 理 呢 ？ 毁 灭 和 强 暴 在 我 面 前 ， 又 起 了 争 端 和 相 斗 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22736', '35', '1', '4', '因 此 律 法 放 松 ， 公 理 也 不 显 明 ； 恶 人 围 困 义 人 ， 所 以 公 理 显 然 颠 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22737', '35', '1', '5', '＜ 耶 和 华 的 回 答 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22738', '35', '1', '6', '我 必 兴 起 迦 勒 底 人 ， 就 是 那 残 忍 暴 躁 之 民 ， 通 行 遍 地 ， 占 据 那 不 属 自 己 的 住 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22739', '35', '1', '7', '他 威 武 可 畏 ， 判 断 和 势 力 都 任 意 发 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22740', '35', '1', '8', '他 的 马 比 豹 更 快 ， 比 晚 上 的 豺 狼 更 猛 。 马 兵 踊 跃 争 先 ， 都 从 远 方 而 来 ； 他 们 飞 跑 如 鹰 抓 食 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22741', '35', '1', '9', '都 为 行 强 暴 而 来 ， 定 住 脸 面 向 前 ， 将 掳 掠 的 人 聚 集 ， 多 如 尘 沙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22742', '35', '1', '10', '他 们 讥 诮 君 王 ， 笑 话 首 领 ， 嗤 笑 一 切 保 障 ， 筑 垒 攻 取 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22743', '35', '1', '11', '他 以 自 己 的 势 力 为 神 ， 像 风 猛 然 扫 过 ， 显 为 有 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22744', '35', '1', '12', '＜ 哈 巴 谷 又 向 耶 和 华 诉 苦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22745', '35', '1', '13', '你 眼 目 清 洁 ， 不 看 邪 僻 ， 不 看 奸 恶 ； 行 诡 诈 的 ， 你 为 何 看 着 不 理 呢 ？ 恶 人 吞 灭 比 自 己 公 义 的 ， 你 为 何 静 默 不 语 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22746', '35', '1', '14', '你 为 何 使 人 如 海 中 的 鱼 ， 又 如 没 有 管 辖 的 爬 物 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22747', '35', '1', '15', '他 用 钩 钩 住 ， 用 网 捕 获 ， 用 拉 网 聚 集 他 们 ； 因 此 ， 他 欢 喜 快 乐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22748', '35', '1', '16', '就 向 网 献 祭 ， 向 网 烧 香 ， 因 他 由 此 得 肥 美 的 分 和 富 裕 的 食 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22749', '35', '1', '17', '他 岂 可 屡 次 倒 空 网 罗 ， 将 列 国 的 人 时 常 杀 戮 ， 毫 不 顾 惜 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22750', '35', '2', '1', '＜ 耶 和 华 回 答 哈 巴 谷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22751', '35', '2', '2', '他 对 我 说 ： 将 这 默 示 明 明 地 写 在 版 上 ， 使 读 的 人 容 易 读 ｛ 或 译 ： 随 跑 随 读 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22752', '35', '2', '3', '因 为 这 默 示 有 一 定 的 日 期 ， 快 要 应 验 ， 并 不 虚 谎 。 虽 然 迟 延 ， 还 要 等 候 ； 因 为 必 然 临 到 ， 不 再 迟 延 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22753', '35', '2', '4', '迦 勒 底 人 自 高 自 大 ， 心 不 正 直 ； 惟 义 人 因 信 得 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22754', '35', '2', '5', '＜ 不 义 的 结 局 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22755', '35', '2', '6', '这 些 国 的 民 岂 不 都 要 提 起 诗 歌 并 俗 语 讥 刺 他 说 ： 祸 哉 ！ 迦 勒 底 人 ， 你 增 添 不 属 自 己 的 财 物 ， 多 多 取 人 的 当 头 ， 要 到 几 时 为 止 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22756', '35', '2', '7', '咬 伤 你 的 岂 不 忽 然 起 来 ， 扰 害 你 的 岂 不 兴 起 ， 你 就 作 他 们 的 掳 物 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22757', '35', '2', '8', '因 你 抢 夺 许 多 的 国 ， 杀 人 流 血 ， 向 国 内 的 城 并 城 中 一 切 居 民 施 行 强 暴 ， 所 以 各 国 剩 下 的 民 都 必 抢 夺 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22758', '35', '2', '9', '为 本 家 积 蓄 不 义 之 财 、 在 高 处 搭 窝 、 指 望 免 灾 的 有 祸 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22759', '35', '2', '10', '你 图 谋 剪 除 多 国 的 民 ， 犯 了 罪 ， 使 你 的 家 蒙 羞 ， 自 害 己 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22760', '35', '2', '11', '墙 里 的 石 头 必 呼 叫 ； 房 内 的 栋 梁 必 应 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22761', '35', '2', '12', '以 人 血 建 城 、 以 罪 孽 立 邑 的 有 祸 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22762', '35', '2', '13', '众 民 所 劳 碌 得 来 的 被 火 焚 烧 ， 列 国 由 劳 乏 而 得 的 归 于 虚 空 ， 不 都 是 出 于 万 军 之 耶 和 华 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22763', '35', '2', '14', '认 识 耶 和 华 荣 耀 的 知 识 要 充 满 遍 地 ， 好 像 水 充 满 洋 海 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22764', '35', '2', '15', '给 人 酒 喝 、 又 加 上 毒 物 、 使 他 喝 醉 、 好 看 见 他 下 体 的 有 祸 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22765', '35', '2', '16', '你 满 受 羞 辱 ， 不 得 荣 耀 ； 你 也 喝 吧 ， 显 出 是 未 受 割 礼 的 ！ 耶 和 华 右 手 的 杯 必 传 到 你 那 里 ； 你 的 荣 耀 就 变 为 大 大 地 羞 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22766', '35', '2', '17', '你 向 黎 巴 嫩 行 强 暴 与 残 害 惊 吓 野 兽 的 事 必 遮 盖 你 ； 因 你 杀 人 流 血 ， 向 国 内 的 城 并 城 中 一 切 居 民 施 行 强 暴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22767', '35', '2', '18', '雕 刻 的 偶 像 ， 人 将 它 刻 出 来 ， 有 什 么 益 处 呢 ？ 铸 造 的 偶 像 就 是 虚 谎 的 师 傅 。 制 造 者 倚 靠 这 哑 巴 偶 像 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22768', '35', '2', '19', '对 木 偶 说 ： 醒 起 ！ 对 哑 巴 石 像 说 ： 起 来 ！ 那 人 有 祸 了 ！ 这 个 还 能 教 训 人 吗 ？ 看 哪 ， 是 包 裹 金 银 的 ， 其 中 毫 无 气 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22769', '35', '2', '20', '惟 耶 和 华 在 他 的 圣 殿 中 ； 全 地 的 人 都 当 在 他 面 前 肃 敬 静 默 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22770', '35', '3', '1', '＜ 哈 巴 谷 的 祈 祷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22771', '35', '3', '2', '耶 和 华 啊 ， 我 听 见 你 的 名 声 ｛ 或 译 ： 言 语 ｝ 就 惧 怕 。 耶 和 华 啊 ， 求 你 在 这 些 年 间 复 兴 你 的 作 为 ， 在 这 些 年 间 显 明 出 来 ； 在 发 怒 的 时 候 以 怜 悯 为 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22772', '35', '3', '3', '神 从 提 幔 而 来 ； 圣 者 从 巴 兰 山 临 到 。 （ 细 拉 ） 他 的 荣 光 遮 蔽 诸 天 ； 颂 赞 充 满 大 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22773', '35', '3', '4', '他 的 辉 煌 如 同 日 光 ； 从 他 手 里 射 出 光 线 ， 在 其 中 藏 着 他 的 能 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22774', '35', '3', '5', '在 他 前 面 有 瘟 疫 流 行 ； 在 他 脚 下 有 热 症 发 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22775', '35', '3', '6', '他 站 立 ， 量 了 大 地 ｛ 或 译 ： 使 地 震 动 ｝ ， 观 看 ， 赶 散 万 民 。 永 久 的 山 崩 裂 ； 长 存 的 岭 塌 陷 ； 他 的 作 为 与 古 时 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22776', '35', '3', '7', '我 见 古 珊 的 帐 棚 遭 难 ， 米 甸 的 幔 子 战 兢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22777', '35', '3', '8', '耶 和 华 啊 ， 你 乘 在 马 上 ， 坐 在 得 胜 的 车 上 ， 岂 是 不 喜 悦 江 河 、 向 江 河 发 怒 气 、 向 洋 海 发 愤 恨 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22778', '35', '3', '9', '你 的 弓 全 然 显 露 ， 向 众 支 派 所 起 的 誓 都 是 可 信 的 。 （ 细 拉 ） 你 以 江 河 分 开 大 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22779', '35', '3', '10', '山 岭 见 你 ， 无 不 战 惧 ； 大 水 泛 滥 过 去 ， 深 渊 发 声 ， 汹 涌 翻 腾 ｛ 原 文 是 向 上 举 手 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22780', '35', '3', '11', '因 你 的 箭 射 出 发 光 ， 你 的 枪 闪 出 光 耀 ， 日 月 都 在 本 宫 停 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22781', '35', '3', '12', '你 发 忿 恨 通 行 大 地 ， 发 怒 气 责 打 列 国 ， 如 同 打 粮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22782', '35', '3', '13', '你 出 来 要 拯 救 你 的 百 姓 ， 拯 救 你 的 受 膏 者 ， 打 破 恶 人 家 长 的 头 ， 露 出 他 的 脚 ｛ 原 文 是 根 基 ｝ ， 直 到 颈 项 。 （ 细 拉 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22783', '35', '3', '14', '你 用 敌 人 的 戈 矛 刺 透 他 战 士 的 头 ； 他 们 来 如 旋 风 ， 要 将 我 们 分 散 。 他 们 所 喜 爱 的 是 暗 中 吞 吃 贫 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22784', '35', '3', '15', '你 乘 马 践 踏 红 海 ， 就 是 践 踏 汹 涌 的 大 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22785', '35', '3', '16', '我 听 见 耶 和 华 的 声 音 ， 身 体 战 兢 ， 嘴 唇 发 颤 ， 骨 中 朽 烂 ； 我 在 所 立 之 处 战 兢 。 我 只 可 安 静 等 候 灾 难 之 日 临 到 ， 犯 境 之 民 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22786', '35', '3', '17', '虽 然 无 花 果 树 不 发 旺 ， 葡 萄 树 不 结 果 ， 橄 榄 树 也 不 效 力 ， 田 地 不 出 粮 食 ， 圈 中 绝 了 羊 ， 棚 内 也 没 有 牛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22787', '35', '3', '18', '然 而 ， 我 要 因 耶 和 华 欢 欣 ， 因 救 我 的 神 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22788', '35', '3', '19', '主 耶 和 华 是 我 的 力 量 ； 他 使 我 的 脚 快 如 母 鹿 的 蹄 ， 又 使 我 稳 行 在 高 处 。 这 歌 交 与 伶 长 ， 用 丝 弦 的 乐 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22789', '36', '1', '1', '当 犹 大 王 亚 们 的 儿 子 约 西 亚 在 位 的 时 候 ， 耶 和 华 的 话 临 到 希 西 家 的 玄 孙 ， 亚 玛 利 雅 的 曾 孙 ， 基 大 利 的 孙 子 ， 古 示 的 儿 子 西 番 雅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22790', '36', '1', '2', '＜ 耶 和 华 审 判 的 日 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22791', '36', '1', '3', '我 必 除 灭 人 和 牲 畜 ， 与 空 中 的 鸟 、 海 里 的 鱼 ， 以 及 绊 脚 石 和 恶 人 ； 我 必 将 人 从 地 上 剪 除 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22792', '36', '1', '4', '我 必 伸 手 攻 击 犹 大 和 耶 路 撒 冷 的 一 切 居 民 ， 也 必 从 这 地 方 剪 除 所 剩 下 的 巴 力 ， 并 基 玛 林 的 名 和 祭 司 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22793', '36', '1', '5', '与 那 些 在 房 顶 上 敬 拜 天 上 万 象 的 ， 并 那 些 敬 拜 耶 和 华 指 着 他 起 誓 ， 又 指 着 玛 勒 堪 起 誓 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22794', '36', '1', '6', '与 那 些 转 去 不 跟 从 耶 和 华 的 ， 和 不 寻 求 耶 和 华 也 不 访 问 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22795', '36', '1', '7', '你 要 在 主 耶 和 华 面 前 静 默 无 声 ， 因 为 耶 和 华 的 日 子 快 到 。 耶 和 华 已 经 预 备 祭 物 ， 将 他 的 客 分 别 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22796', '36', '1', '8', '到 了 我 ─ ─ 耶 和 华 献 祭 的 日 子 ， 必 惩 罚 首 领 和 王 子 ， 并 一 切 穿 外 邦 衣 服 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22797', '36', '1', '9', '到 那 日 ， 我 必 惩 罚 一 切 跳 过 门 槛 、 将 强 暴 和 诡 诈 得 来 之 物 充 满 主 人 房 屋 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22798', '36', '1', '10', '耶 和 华 说 ： 当 那 日 ， 从 鱼 门 必 发 出 悲 哀 的 声 音 ， 从 二 城 发 出 哀 号 的 声 音 ， 从 山 间 发 出 大 破 裂 的 响 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22799', '36', '1', '11', '玛 革 提 施 的 居 民 哪 ， 你 们 要 哀 号 ， 因 为 迦 南 的 商 民 都 灭 亡 了 ！ 凡 搬 运 银 子 的 都 被 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22800', '36', '1', '12', '那 时 ， 我 必 用 灯 巡 查 耶 路 撒 冷 ； 我 必 惩 罚 那 些 如 酒 在 渣 滓 上 澄 清 的 ； 他 们 心 里 说 ： 耶 和 华 必 不 降 福 ， 也 不 降 祸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22801', '36', '1', '13', '他 们 的 财 宝 必 成 为 掠 物 ； 他 们 的 房 屋 必 变 为 荒 场 。 他 们 必 建 造 房 屋 ， 却 不 得 住 在 其 内 ； 栽 种 葡 萄 园 ， 却 不 得 喝 所 出 的 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22802', '36', '1', '14', '耶 和 华 的 大 日 临 近 ， 临 近 而 且 甚 快 ， 乃 是 耶 和 华 日 子 的 风 声 ； 勇 士 必 痛 痛 地 哭 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22803', '36', '1', '15', '那 日 是 忿 怒 的 日 子 ， 是 急 难 困 苦 的 日 子 ， 是 荒 废 凄 凉 的 日 子 ， 是 黑 暗 幽 冥 、 密 云 乌 黑 的 日 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22804', '36', '1', '16', '是 吹 角 呐 喊 的 日 子 ， 要 攻 击 坚 固 城 和 高 大 的 城 楼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22805', '36', '1', '17', '我 必 使 灾 祸 临 到 人 身 上 ， 使 他 们 行 走 如 同 瞎 眼 的 ， 因 为 得 罪 了 我 。 他 们 的 血 必 倒 出 如 灰 尘 ； 他 们 的 肉 必 抛 弃 如 粪 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22806', '36', '1', '18', '当 耶 和 华 发 怒 的 日 子 ， 他 们 的 金 银 不 能 救 他 们 ； 他 的 忿 怒 如 火 必 烧 灭 全 地 ， 毁 灭 这 地 的 一 切 居 民 ， 而 且 大 大 毁 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22807', '36', '2', '1', '＜ 呼 吁 人 民 悔 改 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22808', '36', '2', '2', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22809', '36', '2', '3', '世 上 遵 守 耶 和 华 典 章 的 谦 卑 人 哪 ， 你 们 都 当 寻 求 耶 和 华 ！ 当 寻 求 公 义 谦 卑 ， 或 者 在 耶 和 华 发 怒 的 日 子 可 以 隐 藏 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22810', '36', '2', '4', '＜ 以 色 列 邻 国 的 结 局 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22811', '36', '2', '5', '住 沿 海 之 地 的 基 利 提 族 有 祸 了 ！ 迦 南 、 非 利 士 人 之 地 啊 ， 耶 和 华 的 话 与 你 反 对 ， 说 ： 我 必 毁 灭 你 ， 以 致 无 人 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22812', '36', '2', '6', '沿 海 之 地 要 变 为 草 场 ， 其 上 有 牧 人 的 住 处 和 羊 群 的 圈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22813', '36', '2', '7', '这 地 必 为 犹 大 家 剩 下 的 人 所 得 ； 他 们 必 在 那 里 牧 放 群 羊 ， 晚 上 必 躺 卧 在 亚 实 基 伦 的 房 屋 中 ； 因 为 耶 和 华 ─ ─ 他 们 的 神 必 眷 顾 他 们 ， 使 他 们 被 掳 的 人 归 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22814', '36', '2', '8', '我 听 见 摩 押 人 的 毁 谤 和 亚 扪 人 的 辱 骂 ， 就 是 毁 谤 我 的 百 姓 ， 自 夸 自 大 ， 侵 犯 他 们 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22815', '36', '2', '9', '万 军 之 耶 和 华 ─ ─ 以 色 列 的 神 说 ： 我 指 着 我 的 永 生 起 誓 ： 摩 押 必 像 所 多 玛 ， 亚 扪 人 必 像 蛾 摩 拉 ， 都 变 为 刺 草 、 盐 坑 、 永 远 荒 废 之 地 。 我 百 姓 所 剩 下 的 必 掳 掠 他 们 ； 我 国 中 所 余 剩 的 必 得 着 他 们 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22816', '36', '2', '10', '这 事 临 到 他 们 是 因 他 们 骄 傲 ， 自 夸 自 大 ， 毁 谤 万 军 之 耶 和 华 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22817', '36', '2', '11', '耶 和 华 必 向 他 们 显 可 畏 之 威 ， 因 他 必 叫 世 上 的 诸 神 瘦 弱 。 列 国 海 岛 的 居 民 各 在 自 己 的 地 方 敬 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22818', '36', '2', '12', '古 实 人 哪 ， 你 们 必 被 我 的 刀 所 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22819', '36', '2', '13', '耶 和 华 必 伸 手 攻 击 北 方 ， 毁 灭 亚 述 ， 使 尼 尼 微 荒 凉 ， 又 干 旱 如 旷 野 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22820', '36', '2', '14', '群 畜 ， 就 是 各 国 ｛ 国 ： 或 译 类 ｝ 的 走 兽 必 卧 在 其 中 ； 鹈 鹕 和 箭 猪 要 宿 在 柱 顶 上 。 在 窗 户 内 有 鸣 叫 的 声 音 ； 门 槛 都 必 毁 坏 ， 香 柏 木 已 经 露 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22821', '36', '2', '15', '这 是 素 来 欢 乐 安 然 居 住 的 城 ， 心 里 说 ： 惟 有 我 ， 除 我 以 外 再 没 有 别 的 ； 现 在 何 竟 荒 凉 成 为 野 兽 躺 卧 之 处 ！ 凡 经 过 的 人 都 必 摇 手 嗤 笑 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22822', '36', '3', '1', '＜ 耶 路 撒 冷 的 罪 恶 和 救 赎 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22823', '36', '3', '2', '她 不 听 从 命 令 ， 不 领 受 训 诲 ， 不 倚 靠 耶 和 华 ， 不 亲 近 她 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22824', '36', '3', '3', '她 中 间 的 首 领 是 咆 哮 的 狮 子 ； 她 的 审 判 官 是 晚 上 的 豺 狼 ， 一 点 食 物 也 不 留 到 早 晨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22825', '36', '3', '4', '她 的 先 知 是 虚 浮 诡 诈 的 人 ； 她 的 祭 司 亵 渎 圣 所 ， 强 解 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22826', '36', '3', '5', '耶 和 华 在 她 中 间 是 公 义 的 ， 断 不 做 非 义 的 事 ， 每 早 晨 显 明 他 的 公 义 ， 无 日 不 然 ； 只 是 不 义 的 人 不 知 羞 耻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22827', '36', '3', '6', '我 ─ ─ 耶 和 华 已 经 除 灭 列 国 的 民 ； 他 们 的 城 楼 毁 坏 。 我 使 他 们 的 街 道 荒 凉 ， 以 致 无 人 经 过 ； 他 们 的 城 邑 毁 灭 ， 以 致 无 人 ， 也 无 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22828', '36', '3', '7', '我 说 ： 你 只 要 敬 畏 我 ， 领 受 训 诲 ； 如 此 ， 你 的 住 处 不 致 照 我 所 拟 定 的 除 灭 。 只 是 你 们 从 早 起 来 就 在 一 切 事 上 败 坏 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22829', '36', '3', '8', '耶 和 华 说 ： 你 们 要 等 候 我 ， 直 到 我 兴 起 掳 掠 的 日 子 ； 因 为 我 已 定 意 招 聚 列 国 ， 聚 集 列 邦 ， 将 我 的 恼 怒 ─ ─ 就 是 我 的 烈 怒 都 倾 在 她 们 身 上 。 我 的 忿 怒 如 火 ， 必 烧 灭 全 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22830', '36', '3', '9', '那 时 ， 我 必 使 万 民 用 清 洁 的 言 语 好 求 告 我 ─ ─ 耶 和 华 的 名 ， 同 心 合 意 地 事 奉 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22831', '36', '3', '10', '祈 祷 我 的 ， 就 是 我 所 分 散 的 民 ｛ 原 文 是 女 子 ； 下 同 ｝ ， 必 从 古 实 河 外 来 ， 给 我 献 供 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22832', '36', '3', '11', '当 那 日 ， 你 必 不 因 你 一 切 得 罪 我 的 事 自 觉 羞 愧 ； 因 为 那 时 我 必 从 你 中 间 除 掉 矜 夸 高 傲 之 辈 ， 你 也 不 再 于 我 的 圣 山 狂 傲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22833', '36', '3', '12', '我 却 要 在 你 中 间 留 下 困 苦 贫 寒 的 民 ； 他 们 必 投 靠 我 ─ ─ 耶 和 华 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22834', '36', '3', '13', '以 色 列 所 剩 下 的 人 必 不 作 罪 孽 ， 不 说 谎 言 ， 口 中 也 没 有 诡 诈 的 舌 头 ； 而 且 吃 喝 躺 卧 ， 无 人 惊 吓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22835', '36', '3', '14', '＜ 欢 乐 之 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22836', '36', '3', '15', '耶 和 华 已 经 除 去 你 的 刑 罚 ， 赶 出 你 的 仇 敌 。 以 色 列 的 王 ─ ─ 耶 和 华 在 你 中 间 ； 你 必 不 再 惧 怕 灾 祸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22837', '36', '3', '16', '当 那 日 ， 必 有 话 向 耶 路 撒 冷 说 ： 不 要 惧 怕 ！ 锡 安 哪 ； 不 要 手 软 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22838', '36', '3', '17', '耶 和 华 ─ ─ 你 的 神 是 施 行 拯 救 、 大 有 能 力 的 主 。 他 在 你 中 间 必 因 你 欢 欣 喜 乐 ， 默 然 爱 你 ， 且 因 你 喜 乐 而 欢 呼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22839', '36', '3', '18', '那 些 属 你 、 为 无 大 会 愁 烦 、 因 你 担 当 羞 辱 的 ， 我 必 聚 集 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22840', '36', '3', '19', '那 时 ， 我 必 罚 办 一 切 苦 待 你 的 人 ， 又 拯 救 你 瘸 腿 的 ， 聚 集 你 被 赶 出 的 。 那 些 在 全 地 受 羞 辱 的 ， 我 必 使 他 们 得 称 赞 ， 有 名 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22841', '36', '3', '20', '那 时 ， 我 必 领 你 们 进 来 ， 聚 集 你 们 ； 我 使 你 们 被 掳 之 人 归 回 的 时 候 ， 就 必 使 你 们 在 地 上 的 万 民 中 有 名 声 ， 得 称 赞 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22842', '37', '1', '1', '＜ 耶 和 华 命 令 重 建 圣 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22843', '37', '1', '2', '万 军 之 耶 和 华 如 此 说 ： “ 这 百 姓 说 ， 建 造 耶 和 华 殿 的 时 候 尚 未 来 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22844', '37', '1', '3', '那 时 耶 和 华 的 话 临 到 先 知 哈 该 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22845', '37', '1', '4', '“ 这 殿 仍 然 荒 凉 ， 你 们 自 己 还 住 天 花 板 的 房 屋 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22846', '37', '1', '5', '现 在 万 军 之 耶 和 华 如 此 说 ： 你 们 要 省 察 自 己 的 行 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22847', '37', '1', '6', '你 们 撒 的 种 多 ， 收 的 却 少 ； 你 们 吃 ， 却 不 得 饱 ； 喝 ， 却 不 得 足 ； 穿 衣 服 ， 却 不 得 暖 ； 得 工 钱 的 ， 将 工 钱 装 在 破 漏 的 囊 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22848', '37', '1', '7', '万 军 之 耶 和 华 如 此 说 ： “ 你 们 要 省 察 自 己 的 行 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22849', '37', '1', '8', '你 们 要 上 山 取 木 料 ， 建 造 这 殿 ， 我 就 因 此 喜 乐 ， 且 得 荣 耀 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22850', '37', '1', '9', '你 们 盼 望 多 得 ， 所 得 的 却 少 ； 你 们 收 到 家 中 ， 我 就 吹 去 。 这 是 为 什 么 呢 ？ 因 为 我 的 殿 荒 凉 ， 你 们 各 人 却 顾 ｛ 原 文 是 奔 ｝ 自 己 的 房 屋 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22851', '37', '1', '10', '所 以 为 你 们 的 缘 故 ， 天 就 不 降 甘 露 ， 地 也 不 出 土 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22852', '37', '1', '11', '我 命 干 旱 临 到 地 土 、 山 冈 、 五 谷 、 新 酒 ， 和 油 ， 并 地 上 的 出 产 、 人 民 、 牲 畜 ， 以 及 人 手 一 切 劳 碌 得 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22853', '37', '1', '12', '＜ 人 民 顺 从 神 的 命 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22854', '37', '1', '13', '耶 和 华 的 使 者 哈 该 奉 耶 和 华 差 遣 对 百 姓 说 ： “ 耶 和 华 说 ： 我 与 你 们 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22855', '37', '1', '14', '耶 和 华 激 动 犹 大 省 长 撒 拉 铁 的 儿 子 所 罗 巴 伯 和 约 撒 答 的 儿 子 大 祭 司 约 书 亚 ， 并 剩 下 之 百 姓 的 心 ， 他 们 就 来 为 万 军 之 耶 和 华 ─ ─ 他 们 神 的 殿 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22856', '37', '1', '15', '这 是 在 大 流 士 王 第 二 年 六 月 二 十 四 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22857', '37', '2', '1', '＜ 新 殿 的 荣 耀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22858', '37', '2', '2', '“ 你 要 晓 谕 犹 大 省 长 撒 拉 铁 的 儿 子 所 罗 巴 伯 和 约 撒 答 的 儿 子 大 祭 司 约 书 亚 ， 并 剩 下 的 百 姓 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22859', '37', '2', '3', '你 们 中 间 存 留 的 ， 有 谁 见 过 这 殿 从 前 的 荣 耀 呢 ？ 现 在 你 们 看 着 如 何 ？ 岂 不 在 眼 中 看 如 无 有 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22860', '37', '2', '4', '耶 和 华 说 ： “ 所 罗 巴 伯 啊 ， 虽 然 如 此 ， 你 当 刚 强 ！ 约 撒 答 的 儿 子 大 祭 司 约 书 亚 啊 ， 你 也 当 刚 强 ！ 这 地 的 百 姓 ， 你 们 都 当 刚 强 做 工 ， 因 为 我 与 你 们 同 在 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22861', '37', '2', '5', '这 是 照 着 你 们 出 埃 及 我 与 你 们 立 约 的 话 。 那 时 ， 我 的 灵 住 在 你 们 中 间 ， 你 们 不 要 惧 怕 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22862', '37', '2', '6', '万 军 之 耶 和 华 如 此 说 ： “ 过 不 多 时 ， 我 必 再 一 次 震 动 天 地 、 沧 海 ， 与 旱 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22863', '37', '2', '7', '我 必 震 动 万 国 ； 万 国 的 珍 宝 必 都 运 来 ｛ 或 译 ： 万 国 所 羡 慕 的 必 来 到 ｝ ， 我 就 使 这 殿 满 了 荣 耀 。 这 是 万 军 之 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22864', '37', '2', '8', '万 军 之 耶 和 华 说 ： “ 银 子 是 我 的 ， 金 子 也 是 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22865', '37', '2', '9', '这 殿 后 来 的 荣 耀 必 大 过 先 前 的 荣 耀 ； 在 这 地 方 我 必 赐 平 安 。 这 是 万 军 之 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22866', '37', '2', '10', '＜ 先 知 向 祭 司 请 教 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22867', '37', '2', '11', '万 军 之 耶 和 华 如 此 说 ： “ 你 要 向 祭 司 问 律 法 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22868', '37', '2', '12', '说 ： 若 有 人 用 衣 襟 兜 圣 肉 ， 这 衣 襟 挨 着 饼 ， 或 汤 ， 或 酒 ， 或 油 ， 或 别 的 食 物 ， 便 算 为 圣 吗 ？ ” 祭 司 说 ： “ 不 算 为 圣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22869', '37', '2', '13', '哈 该 又 说 ： “ 若 有 人 因 摸 死 尸 染 了 污 秽 ， 然 后 挨 着 这 些 物 的 哪 一 样 ， 这 物 算 污 秽 吗 ？ ” 祭 司 说 ： “ 必 算 污 秽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22870', '37', '2', '14', '于 是 哈 该 说 ： “ 耶 和 华 说 ： 这 民 这 国 ， 在 我 面 前 也 是 如 此 ； 他 们 手 下 的 各 样 工 作 都 是 如 此 ； 他 们 在 坛 上 所 献 的 也 是 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22871', '37', '2', '15', '＜ 神 应 许 赐 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22872', '37', '2', '16', '在 那 一 切 日 子 ， 有 人 来 到 谷 堆 ， 想 得 二 十 斗 ， 只 得 了 十 斗 。 有 人 来 到 酒 池 ， 想 得 五 十 桶 ， 只 得 了 二 十 桶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22873', '37', '2', '17', '在 你 们 手 下 的 各 样 工 作 上 ， 我 以 旱 风 、 霉 烂 、 冰 雹 攻 击 你 们 ， 你 们 仍 不 归 向 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22874', '37', '2', '18', '你 们 要 追 想 此 日 以 前 ， 就 是 从 这 九 月 二 十 四 日 起 ， 追 想 到 立 耶 和 华 殿 根 基 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22875', '37', '2', '19', '仓 里 有 谷 种 吗 ？ 葡 萄 树 、 无 花 果 树 、 石 榴 树 、 橄 榄 树 都 没 有 结 果 子 。 从 今 日 起 ， 我 必 赐 福 与 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22876', '37', '2', '20', '＜ 神 给 所 罗 巴 伯 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22877', '37', '2', '21', '“ 你 要 告 诉 犹 大 省 长 所 罗 巴 伯 说 ： 我 必 震 动 天 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22878', '37', '2', '22', '我 必 倾 覆 列 国 的 宝 座 ， 除 灭 列 邦 的 势 力 ， 并 倾 覆 战 车 和 坐 在 其 上 的 。 马 必 跌 倒 ， 骑 马 的 败 落 ， 各 人 被 弟 兄 的 刀 所 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22879', '37', '2', '23', '万 军 之 耶 和 华 说 ： 我 仆 人 撒 拉 铁 的 儿 子 所 罗 巴 伯 啊 ， 到 那 日 ， 我 必 以 你 为 印 ， 因 我 拣 选 了 你 。 这 是 万 军 之 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22880', '38', '1', '1', '＜ 耶 和 华 呼 唤 子 民 归 向 他 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22881', '38', '1', '2', '“ 耶 和 华 曾 向 你 们 列 祖 大 大 发 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22882', '38', '1', '3', '所 以 你 要 对 以 色 列 人 说 ， 万 军 之 耶 和 华 如 此 说 ： 你 们 要 转 向 我 ， 我 就 转 向 你 们 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22883', '38', '1', '4', '不 要 效 法 你 们 列 祖 。 从 前 的 先 知 呼 叫 他 们 说 ， 万 军 之 耶 和 华 如 此 说 ： ‘ 你 们 要 回 头 离 开 你 们 的 恶 道 恶 行 。 ’ 他 们 却 不 听 ， 也 不 顺 从 我 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22884', '38', '1', '5', '你 们 的 列 祖 在 哪 里 呢 ？ 那 些 先 知 能 永 远 存 活 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22885', '38', '1', '6', '只 是 我 的 言 语 和 律 例 ， 就 是 所 吩 咐 我 仆 人 众 先 知 的 ， 岂 不 临 到 你 们 列 祖 吗 ？ 他 们 就 回 头 ， 说 ： ‘ 万 军 之 耶 和 华 定 意 按 我 们 的 行 动 作 为 向 我 们 怎 样 行 ， 他 已 照 样 行 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22886', '38', '1', '7', '＜ 马 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22887', '38', '1', '8', '“ 我 夜 间 观 看 ， 见 一 人 骑 着 红 马 ， 站 在 洼 地 番 石 榴 树 中 间 。 在 他 身 后 又 有 红 马 、 黄 马 ， 和 白 马 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22888', '38', '1', '9', '我 对 与 我 说 话 的 天 使 说 ： “ 主 啊 ， 这 是 什 么 意 思 ？ ” 他 说 ： “ 我 要 指 示 你 这 是 什 么 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22889', '38', '1', '10', '那 站 在 番 石 榴 树 中 间 的 人 说 ： “ 这 是 奉 耶 和 华 差 遣 在 遍 地 走 来 走 去 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22890', '38', '1', '11', '那 些 骑 马 的 对 站 在 番 石 榴 树 中 间 耶 和 华 的 使 者 说 ： “ 我 们 已 在 遍 地 走 来 走 去 ， 见 全 地 都 安 息 平 静 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22891', '38', '1', '12', '于 是 ， 耶 和 华 的 使 者 说 ： “ 万 军 之 耶 和 华 啊 ， 你 恼 恨 耶 路 撒 冷 和 犹 大 的 城 邑 已 经 七 十 年 ， 你 不 施 怜 悯 要 到 几 时 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22892', '38', '1', '13', '耶 和 华 就 用 美 善 的 安 慰 话 回 答 那 与 我 说 话 的 天 使 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22893', '38', '1', '14', '与 我 说 话 的 天 使 对 我 说 ： “ 你 要 宣 告 说 ， 万 军 之 耶 和 华 如 此 说 ： 我 为 耶 路 撒 冷 为 锡 安 ， 心 里 极 其 火 热 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22894', '38', '1', '15', '我 甚 恼 怒 那 安 逸 的 列 国 ， 因 我 从 前 稍 微 恼 怒 我 民 ， 他 们 就 加 害 过 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22895', '38', '1', '16', '所 以 耶 和 华 如 此 说 ： 现 今 我 回 到 耶 路 撒 冷 ， 仍 施 怜 悯 ， 我 的 殿 必 重 建 在 其 中 ， 准 绳 必 拉 在 耶 路 撒 冷 之 上 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22896', '38', '1', '17', '你 要 再 宣 告 说 ， 万 军 之 耶 和 华 如 此 说 ： 我 的 城 邑 必 再 丰 盛 发 达 。 耶 和 华 必 再 安 慰 锡 安 ， 拣 选 耶 路 撒 冷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22897', '38', '1', '18', '＜ 角 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22898', '38', '1', '19', '我 就 问 与 我 说 话 的 天 使 说 ： “ 这 是 什 么 意 思 ？ ” 他 回 答 说 ： “ 这 是 打 散 犹 大 、 以 色 列 ， 和 耶 路 撒 冷 的 角 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22899', '38', '1', '20', '耶 和 华 又 指 四 个 匠 人 给 我 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22900', '38', '1', '21', '我 说 ： “ 他 们 来 做 什 么 呢 ？ ” 他 说 ： “ 这 是 打 散 犹 大 的 角 ， 使 人 不 敢 抬 头 ； 但 这 些 匠 人 来 威 吓 列 国 ， 打 掉 他 们 的 角 ， 就 是 举 起 打 散 犹 大 地 的 角 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22901', '38', '2', '1', '＜ 准 绳 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22902', '38', '2', '2', '我 说 ： “ 你 往 哪 里 去 ？ ” 他 对 我 说 ： “ 要 去 量 耶 路 撒 冷 ， 看 有 多 宽 多 长 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22903', '38', '2', '3', '与 我 说 话 的 天 使 去 的 时 候 ， 又 有 一 位 天 使 迎 着 他 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22904', '38', '2', '4', '对 他 说 ： “ 你 跑 去 告 诉 那 少 年 人 说 ， 耶 路 撒 冷 必 有 人 居 住 ， 好 像 无 城 墙 的 乡 村 ， 因 为 人 民 和 牲 畜 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22905', '38', '2', '5', '耶 和 华 说 ： 我 要 作 耶 路 撒 冷 四 围 的 火 城 ， 并 要 作 其 中 的 荣 耀 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22906', '38', '2', '6', '＜ 呼 唤 被 掳 者 归 回 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22907', '38', '2', '7', '与 巴 比 伦 人 同 住 的 锡 安 民 哪 ， 应 当 逃 脱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22908', '38', '2', '8', '万 军 之 耶 和 华 说 ， 在 显 出 荣 耀 之 后 ， 差 遣 我 去 惩 罚 那 掳 掠 你 们 的 列 国 ， 摸 你 们 的 就 是 摸 他 眼 中 的 瞳 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22909', '38', '2', '9', '看 哪 ， 我 ｛ 或 译 ： 他 ｝ 要 向 他 们 抡 手 ， 他 们 就 必 作 服 事 他 们 之 人 的 掳 物 ， 你 们 便 知 道 万 军 之 耶 和 华 差 遣 我 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22910', '38', '2', '10', '锡 安 城 啊 ， 应 当 欢 乐 歌 唱 ， 因 为 我 来 要 住 在 你 中 间 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22911', '38', '2', '11', '那 时 ， 必 有 许 多 国 归 附 耶 和 华 ， 作 他 ｛ 原 文 是 我 ｝ 的 子 民 。 他 ｛ 原 文 是 我 ｝ 要 住 在 你 中 间 ， 你 就 知 道 万 军 之 耶 和 华 差 遣 我 到 你 那 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22912', '38', '2', '12', '耶 和 华 必 收 回 犹 大 作 他 圣 地 的 分 ， 也 必 再 拣 选 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22913', '38', '2', '13', '凡 有 血 气 的 都 当 在 耶 和 华 面 前 静 默 无 声 ； 因 为 他 兴 起 ， 从 圣 所 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22914', '38', '3', '1', '＜ 大 祭 司 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22915', '38', '3', '2', '耶 和 华 向 撒 但 说 ： “ 撒 但 哪 ， 耶 和 华 责 备 你 ！ 就 是 拣 选 耶 路 撒 冷 的 耶 和 华 责 备 你 ！ 这 不 是 从 火 中 抽 出 来 的 一 根 柴 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22916', '38', '3', '3', '约 书 亚 穿 着 污 秽 的 衣 服 站 在 使 者 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22917', '38', '3', '4', '使 者 吩 咐 站 在 面 前 的 说 ： “ 你 们 要 脱 去 他 污 秽 的 衣 服 ” ； 又 对 约 书 亚 说 ： “ 我 使 你 脱 离 罪 孽 ， 要 给 你 穿 上 华 美 的 衣 服 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22918', '38', '3', '5', '我 说 ： “ 要 将 洁 净 的 冠 冕 戴 在 他 头 上 。 ” 他 们 就 把 洁 净 的 冠 冕 戴 在 他 头 上 ， 给 他 穿 上 华 美 的 衣 服 ， 耶 和 华 的 使 者 在 旁 边 站 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22919', '38', '3', '6', '耶 和 华 的 使 者 告 诫 约 书 亚 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22920', '38', '3', '7', '“ 万 军 之 耶 和 华 如 此 说 ： 你 若 遵 行 我 的 道 ， 谨 守 我 的 命 令 ， 你 就 可 以 管 理 我 的 家 ， 看 守 我 的 院 宇 ； 我 也 要 使 你 在 这 些 站 立 的 人 中 间 来 往 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22921', '38', '3', '8', '大 祭 司 约 书 亚 啊 ， 你 和 坐 在 你 面 前 的 同 伴 都 当 听 。 （ 他 们 是 作 预 兆 的 。 ） 我 必 使 我 仆 人 大 卫 的 苗 裔 发 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22922', '38', '3', '9', '看 哪 ， 我 在 约 书 亚 面 前 所 立 的 石 头 ， 在 一 块 石 头 上 有 七 眼 。 万 军 之 耶 和 华 说 ： 我 要 亲 自 雕 刻 这 石 头 ， 并 要 在 一 日 之 间 除 掉 这 地 的 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22923', '38', '3', '10', '当 那 日 ， 你 们 各 人 要 请 邻 舍 坐 在 葡 萄 树 和 无 花 果 树 下 。 这 是 万 军 之 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22924', '38', '4', '1', '＜ 金 灯 台 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22925', '38', '4', '2', '他 问 我 说 ： “ 你 看 见 了 什 么 ？ ” 我 说 ： “ 我 看 见 了 一 个 纯 金 的 灯 台 ， 顶 上 有 盏 灯 ， 灯 台 上 有 七 盏 灯 ， 每 盏 有 七 个 管 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22926', '38', '4', '3', '旁 边 有 两 棵 橄 榄 树 ， 一 棵 在 灯 盏 的 右 边 ， 一 棵 在 灯 盏 的 左 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22927', '38', '4', '4', '我 问 与 我 说 话 的 天 使 说 ： “ 主 啊 ， 这 是 什 么 意 思 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22928', '38', '4', '5', '与 我 说 话 的 天 使 回 答 我 说 ： “ 你 不 知 道 这 是 什 么 意 思 吗 ？ ” 我 说 ： “ 主 啊 ， 我 不 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22929', '38', '4', '6', '＜ 神 给 所 罗 巴 伯 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22930', '38', '4', '7', '大 山 哪 ， 你 算 什 么 呢 ？ 在 所 罗 巴 伯 面 前 ， 你 必 成 为 平 地 。 他 必 搬 出 一 块 石 头 ， 安 在 殿 顶 上 。 人 且 大 声 欢 呼 说 ： ‘ 愿 恩 惠 恩 惠 归 与 这 殿 ｛ 殿 ： 或 译 石 ｝ ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22931', '38', '4', '8', '耶 和 华 的 话 又 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22932', '38', '4', '9', '“ 所 罗 巴 伯 的 手 立 了 这 殿 的 根 基 ， 他 的 手 也 必 完 成 这 工 ， 你 就 知 道 万 军 之 耶 和 华 差 遣 我 到 你 们 这 里 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22933', '38', '4', '10', '谁 藐 视 这 日 的 事 为 小 呢 ？ 这 七 眼 乃 是 耶 和 华 的 眼 睛 ， 遍 察 全 地 ， 见 所 罗 巴 伯 手 拿 线 铊 就 欢 喜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22934', '38', '4', '11', '我 又 问 天 使 说 ： “ 这 灯 台 左 右 的 两 棵 橄 榄 树 是 什 么 意 思 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22935', '38', '4', '12', '我 二 次 问 他 说 ： “ 这 两 根 橄 榄 枝 在 两 个 流 出 金 色 油 的 金 嘴 旁 边 是 什 么 意 思 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22936', '38', '4', '13', '他 对 我 说 ： “ 你 不 知 道 这 是 什 么 意 思 吗 ？ ” 我 说 ： “ 主 啊 ， 我 不 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22937', '38', '4', '14', '他 说 ： “ 这 是 两 个 受 膏 者 站 在 普 天 下 主 的 旁 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22938', '38', '5', '1', '＜ 飞 卷 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22939', '38', '5', '2', '他 问 我 说 ： “ 你 看 见 什 么 ？ ” 我 回 答 说 ： “ 我 看 见 一 飞 行 的 书 卷 ， 长 二 十 肘 ， 宽 十 肘 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22940', '38', '5', '3', '他 对 我 说 ： “ 这 是 发 出 行 在 遍 地 上 的 咒 诅 。 凡 偷 窃 的 必 按 卷 上 这 面 的 话 除 灭 ； 凡 起 假 誓 的 必 按 卷 上 那 面 的 话 除 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22941', '38', '5', '4', '万 军 之 耶 和 华 说 ： 我 必 使 这 书 卷 出 去 ， 进 入 偷 窃 人 的 家 和 指 我 名 起 假 誓 人 的 家 ， 必 常 在 他 家 里 ， 连 房 屋 带 木 石 都 毁 灭 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22942', '38', '5', '5', '＜ 量 器 中 妇 人 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22943', '38', '5', '6', '我 说 ： “ 这 是 什 么 呢 ？ ” 他 说 ： “ 这 出 来 的 是 量 器 。 ” 他 又 说 ： “ 这 是 恶 人 在 遍 地 的 形 状 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22944', '38', '5', '7', '（ 我 见 有 一 片 圆 铅 被 举 起 来 。 ） 这 坐 在 量 器 中 的 是 个 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22945', '38', '5', '8', '天 使 说 ： “ 这 是 罪 恶 。 ” 他 就 把 妇 人 扔 在 量 器 中 ， 将 那 片 圆 铅 扔 在 量 器 的 口 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22946', '38', '5', '9', '我 又 举 目 观 看 ， 见 有 两 个 妇 人 出 来 ， 在 她 们 翅 膀 中 有 风 ， 飞 得 甚 快 ， 翅 膀 如 同 鹳 鸟 的 翅 膀 。 她 们 将 量 器 抬 起 来 ， 悬 在 天 地 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22947', '38', '5', '10', '我 问 与 我 说 话 的 天 使 说 ： “ 她 们 要 将 量 器 抬 到 哪 里 去 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22948', '38', '5', '11', '他 对 我 说 ： “ 要 往 示 拿 地 去 ， 为 它 盖 造 房 屋 ； 等 房 屋 齐 备 ， 就 把 它 安 置 在 自 己 的 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22949', '38', '6', '1', '＜ 马 车 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22950', '38', '6', '2', '第 一 辆 车 套 着 红 马 ， 第 二 辆 车 套 着 黑 马 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22951', '38', '6', '3', '第 三 辆 车 套 着 白 马 ， 第 四 辆 车 套 着 有 斑 点 的 壮 马 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22952', '38', '6', '4', '我 就 问 与 我 说 话 的 天 使 说 ： “ 主 啊 ， 这 是 什 么 意 思 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22953', '38', '6', '5', '天 使 回 答 我 说 ： “ 这 是 天 的 四 风 ， 是 从 普 天 下 的 主 面 前 出 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22954', '38', '6', '6', '套 着 黑 马 的 车 往 北 方 去 ， 白 马 跟 随 在 后 ； 有 斑 点 的 马 往 南 方 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22955', '38', '6', '7', '壮 马 出 来 ， 要 在 遍 地 走 来 走 去 。 天 使 说 ： “ 你 们 只 管 在 遍 地 走 来 走 去 。 ” 它 们 就 照 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22956', '38', '6', '8', '他 又 呼 叫 我 说 ： “ 看 哪 ， 往 北 方 去 的 已 在 北 方 安 慰 我 的 心 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22957', '38', '6', '9', '＜ 为 约 书 亚 加 冕 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22958', '38', '6', '10', '“ 你 要 从 被 掳 之 人 中 取 黑 玳 、 多 比 雅 、 耶 大 雅 的 金 银 。 这 三 人 是 从 巴 比 伦 来 到 西 番 雅 的 儿 子 约 西 亚 的 家 里 。 当 日 你 要 进 他 的 家 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22959', '38', '6', '11', '取 这 金 银 做 冠 冕 ， 戴 在 约 撒 答 的 儿 子 大 祭 司 约 书 亚 的 头 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22960', '38', '6', '12', '对 他 说 ， 万 军 之 耶 和 华 如 此 说 ： 看 哪 ， 那 名 称 为 大 卫 苗 裔 的 ， 他 要 在 本 处 长 起 来 ， 并 要 建 造 耶 和 华 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22961', '38', '6', '13', '他 要 建 造 耶 和 华 的 殿 ， 并 担 负 尊 荣 ， 坐 在 位 上 掌 王 权 ； 又 必 在 位 上 作 祭 司 ， 使 两 职 之 间 筹 定 和 平 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22962', '38', '6', '14', '这 冠 冕 要 归 希 连 ｛ 就 是 黑 玳 ｝ 、 多 比 雅 、 耶 大 雅 ， 和 西 番 雅 的 儿 子 贤 ｛ 就 是 约 西 亚 ｝ ， 放 在 耶 和 华 的 殿 里 为 记 念 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22963', '38', '6', '15', '远 方 的 人 也 要 来 建 造 耶 和 华 的 殿 ， 你 们 就 知 道 万 军 之 耶 和 华 差 遣 我 到 你 们 这 里 来 。 你 们 若 留 意 听 从 耶 和 华 ─ ─ 你 们 神 的 话 ， 这 事 必 然 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22964', '38', '7', '1', '＜ 谴 责 不 诚 恳 的 禁 食 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22965', '38', '7', '2', '那 时 伯 特 利 人 已 经 打 发 沙 利 亚 和 利 坚 米 勒 ， 并 跟 从 他 们 的 人 ， 去 恳 求 耶 和 华 的 恩 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22966', '38', '7', '3', '并 问 万 军 之 耶 和 华 殿 中 的 祭 司 和 先 知 说 ： “ 我 历 年 以 来 ， 在 五 月 间 哭 泣 斋 戒 ， 现 在 还 当 这 样 行 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22967', '38', '7', '4', '万 军 之 耶 和 华 的 话 就 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22968', '38', '7', '5', '“ 你 要 宣 告 国 内 的 众 民 和 祭 司 ， 说 ： ‘ 你 们 这 七 十 年 ， 在 五 月 、 七 月 禁 食 悲 哀 ， 岂 是 丝 毫 向 我 禁 食 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22969', '38', '7', '6', '你 们 吃 喝 ， 不 是 为 自 己 吃 ， 为 自 己 喝 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22970', '38', '7', '7', '当 耶 路 撒 冷 和 四 围 的 城 邑 有 居 民 ， 正 兴 盛 ， 南 地 高 原 有 人 居 住 的 时 候 ， 耶 和 华 藉 从 前 的 先 知 所 宣 告 的 话 ， 你 们 不 当 听 吗 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22971', '38', '7', '8', '＜ 被 掳 的 原 因 是 背 逆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22972', '38', '7', '9', '“ 万 军 之 耶 和 华 曾 对 你 们 的 列 祖 如 此 说 ： ‘ 要 按 至 理 判 断 ， 各 人 以 慈 爱 怜 悯 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22973', '38', '7', '10', '不 可 欺 压 寡 妇 、 孤 儿 、 寄 居 的 ， 和 贫 穷 人 。 谁 都 不 可 心 里 谋 害 弟 兄 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22974', '38', '7', '11', '他 们 却 不 肯 听 从 ， 扭 转 肩 头 ， 塞 耳 不 听 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22975', '38', '7', '12', '使 心 硬 如 金 钢 石 ， 不 听 律 法 和 万 军 之 耶 和 华 用 灵 藉 从 前 的 先 知 所 说 的 话 。 故 此 ， 万 军 之 耶 和 华 大 发 烈 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22976', '38', '7', '13', '万 军 之 耶 和 华 说 ： “ 我 曾 呼 唤 他 们 ， 他 们 不 听 ； 将 来 他 们 呼 求 我 ， 我 也 不 听 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22977', '38', '7', '14', '我 必 以 旋 风 吹 散 他 们 到 素 不 认 识 的 万 国 中 。 这 样 ， 他 们 的 地 就 荒 凉 ， 甚 至 无 人 来 往 经 过 ， 因 为 他 们 使 美 好 之 地 荒 凉 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22978', '38', '8', '1', '＜ 耶 和 华 应 许 复 兴 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22979', '38', '8', '2', '“ 万 军 之 耶 和 华 如 此 说 ： 我 为 锡 安 心 里 极 其 火 热 ， 我 为 她 火 热 ， 向 她 的 仇 敌 发 烈 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22980', '38', '8', '3', '耶 和 华 如 此 说 ： 我 现 在 回 到 锡 安 ， 要 住 在 耶 路 撒 冷 中 。 耶 路 撒 冷 必 称 为 诚 实 的 城 ， 万 军 之 耶 和 华 的 山 必 称 为 圣 山 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22981', '38', '8', '4', '万 军 之 耶 和 华 如 此 说 ： 将 来 必 有 年 老 的 男 女 坐 在 耶 路 撒 冷 街 上 ， 因 为 年 纪 老 迈 就 手 拿 柺 杖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22982', '38', '8', '5', '城 中 街 上 必 满 有 男 孩 女 孩 玩 耍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22983', '38', '8', '6', '万 军 之 耶 和 华 如 此 说 ： 到 那 日 ， 这 事 在 余 剩 的 民 眼 中 看 为 希 奇 ， 在 我 眼 中 也 看 为 希 奇 吗 ？ 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22984', '38', '8', '7', '万 军 之 耶 和 华 如 此 说 ： 我 要 从 东 方 从 西 方 救 回 我 的 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22985', '38', '8', '8', '我 要 领 他 们 来 ， 使 他 们 住 在 耶 路 撒 冷 中 。 他 们 要 作 我 的 子 民 ， 我 要 作 他 们 的 神 ， 都 凭 诚 实 和 公 义 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22986', '38', '8', '9', '万 军 之 耶 和 华 如 此 说 ： “ 当 建 造 万 军 之 耶 和 华 的 殿 ， 立 根 基 之 日 的 先 知 所 说 的 话 ， 现 在 你 们 听 见 ， 应 当 手 里 强 壮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22987', '38', '8', '10', '那 日 以 先 ， 人 得 不 着 雇 价 ， 牲 畜 也 是 如 此 ； 且 因 敌 人 的 缘 故 ， 出 入 之 人 不 得 平 安 ， 乃 因 我 使 众 人 互 相 攻 击 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22988', '38', '8', '11', '但 如 今 ， 我 待 这 余 剩 的 民 必 不 像 从 前 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22989', '38', '8', '12', '因 为 他 们 必 平 安 撒 种 ， 葡 萄 树 必 结 果 子 ， 地 土 必 有 出 产 ， 天 也 必 降 甘 露 。 我 要 使 这 余 剩 的 民 享 受 这 一 切 的 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22990', '38', '8', '13', '犹 大 家 和 以 色 列 家 啊 ， 你 们 从 前 在 列 国 中 怎 样 成 为 可 咒 诅 的 ； 照 样 ， 我 要 拯 救 你 们 ， 使 人 称 你 们 为 有 福 的 ｛ 或 译 ： 使 你 们 叫 人 得 福 ｝ 。 你 们 不 要 惧 怕 ， 手 要 强 壮 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22991', '38', '8', '14', '万 军 之 耶 和 华 如 此 说 ： “ 你 们 列 祖 惹 我 发 怒 的 时 候 ， 我 怎 样 定 意 降 祸 ， 并 不 后 悔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22992', '38', '8', '15', '现 在 我 照 样 定 意 施 恩 与 耶 路 撒 冷 和 犹 大 家 ， 你 们 不 要 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22993', '38', '8', '16', '你 们 所 当 行 的 是 这 样 ： 各 人 与 邻 舍 说 话 诚 实 ， 在 城 门 口 按 至 理 判 断 ， 使 人 和 睦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22994', '38', '8', '17', '谁 都 不 可 心 里 谋 害 邻 舍 ， 也 不 可 喜 爱 起 假 誓 ， 因 为 这 些 事 都 为 我 所 恨 恶 。 这 是 耶 和 华 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22995', '38', '8', '18', '万 军 之 耶 和 华 的 话 临 到 我 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22996', '38', '8', '19', '“ 万 军 之 耶 和 华 如 此 说 ： 四 月 、 五 月 禁 食 的 日 子 ， 七 月 、 十 月 禁 食 的 日 子 ， 必 变 为 犹 大 家 欢 喜 快 乐 的 日 子 和 欢 乐 的 节 期 ； 所 以 你 们 要 喜 爱 诚 实 与 和 平 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22997', '38', '8', '20', '万 军 之 耶 和 华 如 此 说 ： “ 将 来 必 有 列 国 的 人 和 多 城 的 居 民 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22998', '38', '8', '21', '这 城 的 居 民 必 到 那 城 ， 说 ： ‘ 我 们 要 快 去 恳 求 耶 和 华 的 恩 ， 寻 求 万 军 之 耶 和 华 ； 我 也 要 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('22999', '38', '8', '22', '必 有 列 邦 的 人 和 强 国 的 民 来 到 耶 路 撒 冷 寻 求 万 军 之 耶 和 华 ， 恳 求 耶 和 华 的 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23000', '38', '8', '23', '万 军 之 耶 和 华 如 此 说 ： 在 那 些 日 子 ， 必 有 十 个 人 从 列 国 诸 族 ｛ 原 文 是 方 言 ｝ 中 出 来 ， 拉 住 一 个 犹 大 人 的 衣 襟 ， 说 ： ‘ 我 们 要 与 你 们 同 去 ， 因 为 我 们 听 见 神 与 你 们 同 在 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23001', '38', '9', '1', '＜ 审 判 邻 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23002', '38', '9', '2', '和 靠 近 的 哈 马 ， 并 泰 尔 、 西 顿 ； 因 为 这 二 城 的 人 大 有 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23003', '38', '9', '3', '泰 尔 为 自 己 修 筑 保 障 ， 积 蓄 银 子 如 尘 沙 ， 堆 起 精 金 如 街 上 的 泥 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23004', '38', '9', '4', '主 必 赶 出 她 ， 打 败 她 海 上 的 权 利 ； 她 必 被 火 烧 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23005', '38', '9', '5', '亚 实 基 伦 看 见 必 惧 怕 ； 迦 萨 看 见 甚 痛 苦 ； 以 革 伦 因 失 了 盼 望 蒙 羞 。 迦 萨 必 不 再 有 君 王 ； 亚 实 基 伦 也 不 再 有 居 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23006', '38', '9', '6', '私 生 子 ｛ 或 译 ： 外 族 人 ｝ 必 住 在 亚 实 突 ； 我 必 除 灭 非 利 士 人 的 骄 傲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23007', '38', '9', '7', '我 必 除 去 他 口 中 带 血 之 肉 和 牙 齿 内 可 憎 之 物 。 他 必 作 为 余 剩 的 人 归 与 我 们 的 神 ， 必 在 犹 大 像 族 长 ； 以 革 伦 人 必 如 耶 布 斯 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23008', '38', '9', '8', '我 必 在 我 家 的 四 围 安 营 ， 使 敌 军 不 得 任 意 往 来 ， 暴 虐 的 人 也 不 再 经 过 ， 因 为 我 亲 眼 看 顾 我 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23009', '38', '9', '9', '＜ 未 来 的 君 王 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23010', '38', '9', '10', '我 必 除 灭 以 法 莲 的 战 车 和 耶 路 撒 冷 的 战 马 ； 争 战 的 弓 也 必 除 灭 。 他 必 向 列 国 讲 和 平 ； 他 的 权 柄 必 从 这 海 管 到 那 海 ， 从 大 河 管 到 地 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23011', '38', '9', '11', '＜ 神 子 民 的 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23012', '38', '9', '12', '你 们 被 囚 而 有 指 望 的 人 都 要 转 回 保 障 。 我 今 日 说 明 ， 我 必 加 倍 赐 福 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23013', '38', '9', '13', '我 拿 犹 大 作 上 弦 的 弓 ； 我 拿 以 法 莲 为 张 弓 的 箭 。 锡 安 哪 ， 我 要 激 发 你 的 众 子 ， 攻 击 希 腊 ｛ 原 文 是 雅 完 ｝ 的 众 子 ， 使 你 如 勇 士 的 刀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23014', '38', '9', '14', '耶 和 华 必 显 现 在 他 们 以 上 ； 他 的 箭 必 射 出 像 闪 电 。 主 耶 和 华 必 吹 角 ， 乘 南 方 的 旋 风 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23015', '38', '9', '15', '万 军 之 耶 和 华 必 保 护 他 们 ； 他 们 必 吞 灭 仇 敌 ， 践 踏 弹 石 。 他 们 必 喝 血 呐 喊 ， 犹 如 饮 酒 ； 他 们 必 像 盛 满 血 的 碗 ， 又 像 坛 的 四 角 满 了 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23016', '38', '9', '16', '当 那 日 ， 耶 和 华 ─ ─ 他 们 的 神 必 看 他 的 民 如 群 羊 ， 拯 救 他 们 ； 因 为 他 们 必 像 冠 冕 上 的 宝 石 ， 高 举 在 他 的 地 以 上 ｛ 或 译 ： 在 他 的 地 上 发 光 辉 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23017', '38', '9', '17', '他 的 恩 慈 何 等 大 ！ 他 的 荣 美 何 其 盛 ！ 五 谷 健 壮 少 男 ； 新 酒 培 养 处 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23018', '38', '10', '1', '＜ 耶 和 华 应 许 解 救 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23019', '38', '10', '2', '因 为 ， 家 神 所 言 的 是 虚 空 ； 卜 士 所 见 的 是 虚 假 ； 做 梦 者 所 说 的 是 假 梦 。 他 们 白 白 地 安 慰 人 ， 所 以 众 人 如 羊 流 离 ， 因 无 牧 人 就 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23020', '38', '10', '3', '我 的 怒 气 向 牧 人 发 作 ； 我 必 惩 罚 公 山 羊 ； 因 我 ─ ─ 万 军 之 耶 和 华 眷 顾 自 己 的 羊 群 ， 就 是 犹 大 家 ， 必 使 他 们 如 骏 马 在 阵 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23021', '38', '10', '4', '房 角 石 、 钉 子 、 争 战 的 弓 ， 和 一 切 掌 权 的 都 从 他 而 出 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23022', '38', '10', '5', '他 们 必 如 勇 士 在 阵 上 将 仇 敌 践 踏 在 街 上 的 泥 土 中 。 他 们 必 争 战 ， 因 为 耶 和 华 与 他 们 同 在 ； 骑 马 的 也 必 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23023', '38', '10', '6', '我 要 坚 固 犹 大 家 ， 拯 救 约 瑟 家 ， 要 领 他 们 归 回 。 我 要 怜 恤 他 们 ； 他 们 必 像 未 曾 弃 绝 的 一 样 ， 都 因 我 是 耶 和 华 ─ ─ 他 们 的 神 ， 我 必 应 允 他 们 的 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23024', '38', '10', '7', '以 法 莲 人 必 如 勇 士 ； 他 们 心 中 畅 快 如 同 喝 酒 ； 他 们 的 儿 女 必 看 见 而 快 活 ； 他 们 的 心 必 因 耶 和 华 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23025', '38', '10', '8', '我 要 发 嘶 声 ， 聚 集 他 们 ， 因 我 已 经 救 赎 他 们 。 他 们 的 人 数 必 加 增 ， 如 从 前 加 增 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23026', '38', '10', '9', '我 虽 然 ｛ 或 译 ： 必 ｝ 播 散 他 们 在 列 国 中 ， 他 们 必 在 远 方 记 念 我 。 他 们 与 儿 女 都 必 存 活 ， 且 得 归 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23027', '38', '10', '10', '我 必 再 领 他 们 出 埃 及 地 ， 招 聚 他 们 出 亚 述 ， 领 他 们 到 基 列 和 黎 巴 嫩 ； 这 地 尚 且 不 够 他 们 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23028', '38', '10', '11', '耶 和 华 必 经 过 苦 海 ， 击 打 海 浪 ， 使 尼 罗 河 的 深 处 都 枯 干 。 亚 述 的 骄 傲 必 致 卑 微 ； 埃 及 的 权 柄 必 然 灭 没 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23029', '38', '10', '12', '我 必 使 他 们 倚 靠 我 ， 得 以 坚 固 ； 一 举 一 动 必 奉 我 的 名 。 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23030', '38', '11', '1', '＜ 暴 君 的 没 落 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23031', '38', '11', '2', '松 树 啊 ， 应 当 哀 号 ； 因 为 香 柏 树 倾 倒 ， 佳 美 的 树 毁 坏 。 巴 珊 的 橡 树 啊 ， 应 当 哀 号 ， 因 为 茂 盛 的 树 林 已 经 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23032', '38', '11', '3', '听 啊 ， 有 牧 人 哀 号 的 声 音 ， 因 他 们 荣 华 的 草 场 毁 坏 了 。 有 少 壮 狮 子 咆 哮 的 声 音 ， 因 约 旦 河 旁 的 丛 林 荒 废 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23033', '38', '11', '4', '＜ 两 个 牧 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23034', '38', '11', '5', '买 他 们 的 宰 了 他 们 ， 以 自 己 为 无 罪 ； 卖 他 们 的 说 ： ‘ 耶 和 华 是 应 当 称 颂 的 ， 因 我 成 为 富 足 。 ’ 牧 养 他 们 的 并 不 怜 恤 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23035', '38', '11', '6', '耶 和 华 说 ： ‘ 我 不 再 怜 恤 这 地 的 居 民 ， 必 将 这 民 交 给 各 人 的 邻 舍 和 他 们 王 的 手 中 。 他 们 必 毁 灭 这 地 ， 我 也 不 救 这 民 脱 离 他 们 的 手 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23036', '38', '11', '7', '于 是 ， 我 牧 养 这 将 宰 的 群 羊 ， 就 是 群 中 最 困 苦 的 羊 。 我 拿 着 两 根 杖 ， 一 根 我 称 为 “ 荣 美 ” ， 一 根 我 称 为 “ 联 索 ” 。 这 样 ， 我 牧 养 了 群 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23037', '38', '11', '8', '一 月 之 内 ， 我 除 灭 三 个 牧 人 ， 因 为 我 的 心 厌 烦 他 们 ； 他 们 的 心 也 憎 嫌 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23038', '38', '11', '9', '我 就 说 ： “ 我 不 牧 养 你 们 。 要 死 的 ， 由 他 死 ； 要 丧 亡 的 ， 由 他 丧 亡 ； 余 剩 的 ， 由 他 们 彼 此 相 食 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23039', '38', '11', '10', '我 折 断 那 称 为 “ 荣 美 ” 的 杖 ， 表 明 我 废 弃 与 万 民 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23040', '38', '11', '11', '当 日 就 废 弃 了 。 这 样 ， 那 些 仰 望 我 的 困 苦 羊 就 知 道 所 说 的 是 耶 和 华 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23041', '38', '11', '12', '我 对 他 们 说 ： “ 你 们 若 以 为 美 ， 就 给 我 工 价 。 不 然 ， 就 罢 了 ！ ” 于 是 他 们 给 了 三 十 块 钱 作 为 我 的 工 价 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23042', '38', '11', '13', '耶 和 华 吩 咐 我 说 ： “ 要 把 众 人 所 估 定 美 好 的 价 值 丢 给 窑 户 。 ” 我 便 将 这 三 十 块 钱 ， 在 耶 和 华 的 殿 中 丢 给 窑 户 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23043', '38', '11', '14', '我 又 折 断 称 为 “ 联 索 ” 的 那 根 杖 ， 表 明 我 废 弃 犹 大 与 以 色 列 弟 兄 的 情 谊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23044', '38', '11', '15', '耶 和 华 又 吩 咐 我 说 ： “ 你 再 取 愚 昧 牧 人 所 用 的 器 具 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23045', '38', '11', '16', '因 我 要 在 这 地 兴 起 一 个 牧 人 。 他 不 看 顾 丧 亡 的 ， 不 寻 找 分 散 的 ， 不 医 治 受 伤 的 ， 也 不 牧 养 强 壮 的 ； 却 要 吃 肥 羊 的 肉 ， 撕 裂 它 的 蹄 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23046', '38', '11', '17', '无 用 的 牧 人 丢 弃 羊 群 有 祸 了 ！ 刀 必 临 到 他 的 膀 臂 和 右 眼 上 。 他 的 膀 臂 必 全 然 枯 干 ； 他 的 右 眼 也 必 昏 暗 失 明 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23047', '38', '12', '1', '＜ 耶 路 撒 冷 将 蒙 拯 救 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23048', '38', '12', '2', '“ 我 必 使 耶 路 撒 冷 被 围 困 的 时 候 ， 向 四 围 列 国 的 民 成 为 令 人 昏 醉 的 杯 ； 这 默 示 也 论 到 犹 大 ｛ 或 译 ： 犹 大 也 是 如 此 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23049', '38', '12', '3', '那 日 ， 我 必 使 耶 路 撒 冷 向 聚 集 攻 击 他 的 万 民 当 作 一 块 重 石 头 ； 凡 举 起 的 必 受 重 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23050', '38', '12', '4', '耶 和 华 说 ： 到 那 日 ， 我 必 使 一 切 马 匹 惊 惶 ， 使 骑 马 的 颠 狂 。 我 必 看 顾 犹 大 家 ， 使 列 国 的 一 切 马 匹 瞎 眼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23051', '38', '12', '5', '犹 大 的 族 长 必 心 里 说 ： ‘ 耶 路 撒 冷 的 居 民 倚 靠 万 军 之 耶 和 华 ─ ─ 他 们 的 神 ， 就 作 我 们 的 能 力 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23052', '38', '12', '6', '“ 那 日 ， 我 必 使 犹 大 的 族 长 如 火 盆 在 木 柴 中 ， 又 如 火 把 在 禾 捆 里 ； 他 们 必 左 右 烧 灭 四 围 列 国 的 民 。 耶 路 撒 冷 人 必 仍 住 本 处 ， 就 是 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23053', '38', '12', '7', '“ 耶 和 华 必 先 拯 救 犹 大 的 帐 棚 ， 免 得 大 卫 家 的 荣 耀 和 耶 路 撒 冷 居 民 的 荣 耀 胜 过 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23054', '38', '12', '8', '那 日 ， 耶 和 华 必 保 护 耶 路 撒 冷 的 居 民 。 他 们 中 间 软 弱 的 必 如 大 卫 ； 大 卫 的 家 必 如 神 ， 如 行 在 他 们 前 面 之 耶 和 华 的 使 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23055', '38', '12', '9', '那 日 ， 我 必 定 意 灭 绝 来 攻 击 耶 路 撒 冷 各 国 的 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23056', '38', '12', '10', '“ 我 必 将 那 施 恩 叫 人 恳 求 的 灵 ， 浇 灌 大 卫 家 和 耶 路 撒 冷 的 居 民 。 他 们 必 仰 望 我 ｛ 或 译 ： 他 ； 本 节 同 ｝ ， 就 是 他 们 所 扎 的 ； 必 为 我 悲 哀 ， 如 丧 独 生 子 ， 又 为 我 愁 苦 ， 如 丧 长 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23057', '38', '12', '11', '那 日 ， 耶 路 撒 冷 必 有 大 大 的 悲 哀 ， 如 米 吉 多 平 原 之 哈 达 临 门 的 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23058', '38', '12', '12', '境 内 一 家 一 家 地 都 必 悲 哀 。 大 卫 家 ， 男 的 独 在 一 处 ， 女 的 独 在 一 处 。 拿 单 家 ， 男 的 独 在 一 处 ， 女 的 独 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23059', '38', '12', '13', '利 未 家 ， 男 的 独 在 一 处 ， 女 的 独 在 一 处 。 示 每 家 ， 男 的 独 在 一 处 ， 女 的 独 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23060', '38', '12', '14', '其 余 的 各 家 ， 男 的 独 在 一 处 ， 女 的 独 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23061', '38', '13', '1', '“ 那 日 ， 必 给 大 卫 家 和 耶 路 撒 冷 的 居 民 开 一 个 泉 源 ， 洗 除 罪 恶 与 污 秽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23062', '38', '13', '2', '万 军 之 耶 和 华 说 ： “ 那 日 ， 我 必 从 地 上 除 灭 偶 像 的 名 ， 不 再 被 人 记 念 ； 也 必 使 这 地 不 再 有 假 先 知 与 污 秽 的 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23063', '38', '13', '3', '若 再 有 人 说 预 言 ， 生 他 的 父 母 必 对 他 说 ： ‘ 你 不 得 存 活 ， 因 为 你 托 耶 和 华 的 名 说 假 预 言 。 ’ 生 他 的 父 母 在 他 说 预 言 的 时 候 ， 要 将 他 刺 透 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23064', '38', '13', '4', '那 日 ， 凡 作 先 知 说 预 言 的 必 因 他 所 论 的 异 象 羞 愧 ， 不 再 穿 毛 衣 哄 骗 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23065', '38', '13', '5', '他 必 说 ： ‘ 我 不 是 先 知 ， 我 是 耕 地 的 ； 我 从 幼 年 作 人 的 奴 仆 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23066', '38', '13', '6', '必 有 人 问 他 说 ： ‘ 你 两 臂 中 间 是 什 么 伤 呢 ？ ’ 他 必 回 答 说 ： ‘ 这 是 我 在 亲 友 家 中 所 受 的 伤 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23067', '38', '13', '7', '＜ 牧 人 被 杀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23068', '38', '13', '8', '耶 和 华 说 ： 这 全 地 的 人 ， 三 分 之 二 必 剪 除 而 死 ， 三 分 之 一 仍 必 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23069', '38', '13', '9', '我 要 使 这 三 分 之 一 经 火 ， 熬 炼 他 们 ， 如 熬 炼 银 子 ； 试 炼 他 们 ， 如 试 炼 金 子 。 他 们 必 求 告 我 的 名 ， 我 必 应 允 他 们 。 我 要 说 ： 这 是 我 的 子 民 。 他 们 也 要 说 ： 耶 和 华 是 我 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23070', '38', '14', '1', '＜ 耶 路 撒 冷 和 列 国 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23071', '38', '14', '2', '因 为 我 必 聚 集 万 国 与 耶 路 撒 冷 争 战 ， 城 必 被 攻 取 ， 房 屋 被 抢 夺 ， 妇 女 被 玷 污 ， 城 中 的 民 一 半 被 掳 去 ； 剩 下 的 民 仍 在 城 中 ， 不 致 剪 除 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23072', '38', '14', '3', '那 时 ， 耶 和 华 必 出 去 与 那 些 国 争 战 ， 好 像 从 前 争 战 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23073', '38', '14', '4', '那 日 ， 他 的 脚 必 站 在 耶 路 撒 冷 前 面 朝 东 的 橄 榄 山 上 。 这 山 必 从 中 间 分 裂 ， 自 东 至 西 成 为 极 大 的 谷 。 山 的 一 半 向 北 挪 移 ， 一 半 向 南 挪 移 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23074', '38', '14', '5', '你 们 要 从 我 山 的 谷 中 逃 跑 ， 因 为 山 谷 必 延 到 亚 萨 。 你 们 逃 跑 ， 必 如 犹 大 王 乌 西 雅 年 间 的 人 逃 避 大 地 震 一 样 。 耶 和 华 ─ ─ 我 的 神 必 降 临 ， 有 一 切 圣 者 同 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23075', '38', '14', '6', '那 日 ， 必 没 有 光 ， 三 光 必 退 缩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23076', '38', '14', '7', '那 日 ， 必 是 耶 和 华 所 知 道 的 ， 不 是 白 昼 ， 也 不 是 黑 夜 ， 到 了 晚 上 才 有 光 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23077', '38', '14', '8', '那 日 ， 必 有 活 水 从 耶 路 撒 冷 出 来 ， 一 半 往 东 海 流 ， 一 半 往 西 海 流 ； 冬 夏 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23078', '38', '14', '9', '耶 和 华 必 作 全 地 的 王 。 那 日 耶 和 华 必 为 独 一 无 二 的 ， 他 的 名 也 是 独 一 无 二 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23079', '38', '14', '10', '全 地 ， 从 迦 巴 直 到 耶 路 撒 冷 南 方 的 临 门 ， 要 变 为 亚 拉 巴 。 耶 路 撒 冷 必 仍 居 高 位 ， 就 是 从 便 雅 悯 门 到 第 一 门 之 处 ， 又 到 角 门 ， 并 从 哈 楠 业 楼 ， 直 到 王 的 酒 醡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23080', '38', '14', '11', '人 必 住 在 其 中 ， 不 再 有 咒 诅 。 耶 路 撒 冷 人 必 安 然 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23081', '38', '14', '12', '耶 和 华 用 灾 殃 攻 击 那 与 耶 路 撒 冷 争 战 的 列 国 人 ， 必 是 这 样 ： 他 们 两 脚 站 立 的 时 候 ， 肉 必 消 没 ， 眼 在 眶 中 干 瘪 ， 舌 在 口 中 溃 烂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23082', '38', '14', '13', '那 日 ， 耶 和 华 必 使 他 们 大 大 扰 乱 。 他 们 各 人 彼 此 揪 住 ， 举 手 攻 击 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23083', '38', '14', '14', '犹 大 也 必 在 耶 路 撒 冷 争 战 。 那 时 四 围 各 国 的 财 物 ， 就 是 许 多 金 银 衣 服 ， 必 被 收 聚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23084', '38', '14', '15', '那 临 到 马 匹 、 骡 子 、 骆 驼 、 驴 ， 和 营 中 一 切 牲 畜 的 灾 殃 是 与 那 灾 殃 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23085', '38', '14', '16', '所 有 来 攻 击 耶 路 撒 冷 列 国 中 剩 下 的 人 ， 必 年 年 上 来 敬 拜 大 君 王 ─ ─ 万 军 之 耶 和 华 ， 并 守 住 棚 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23086', '38', '14', '17', '地 上 万 族 中 ， 凡 不 上 耶 路 撒 冷 敬 拜 大 君 王 ─ ─ 万 军 之 耶 和 华 的 ， 必 无 雨 降 在 他 们 的 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23087', '38', '14', '18', '埃 及 族 若 不 上 来 ， 雨 也 不 降 在 他 们 的 地 上 ； 凡 不 上 来 守 住 棚 节 的 列 国 人 ， 耶 和 华 也 必 用 这 灾 攻 击 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23088', '38', '14', '19', '这 就 是 埃 及 的 刑 罚 和 那 不 上 来 守 住 棚 节 之 列 国 的 刑 罚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23089', '38', '14', '20', '当 那 日 ， 马 的 铃 铛 上 必 有 “ 归 耶 和 华 为 圣 ” 的 这 句 话 。 耶 和 华 殿 内 的 锅 必 如 祭 坛 前 的 碗 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23090', '38', '14', '21', '凡 耶 路 撒 冷 和 犹 大 的 锅 都 必 归 万 军 之 耶 和 华 为 圣 。 凡 献 祭 的 都 必 来 取 这 锅 ， 煮 肉 在 其 中 。 当 那 日 ， 在 万 军 之 耶 和 华 的 殿 中 必 不 再 有 迦 南 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23091', '39', '1', '1', '耶 和 华 藉 玛 拉 基 传 给 以 色 列 的 默 示 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23092', '39', '1', '2', '＜ 耶 和 华 爱 以 色 列 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23093', '39', '1', '3', '恶 以 扫 ， 使 他 的 山 岭 荒 凉 ， 把 他 的 地 业 交 给 旷 野 的 野 狗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23094', '39', '1', '4', '以 东 人 说 ： “ 我 们 现 在 虽 被 毁 坏 ， 却 要 重 建 荒 废 之 处 。 ” 万 军 之 耶 和 华 如 此 说 ： “ 任 他 们 建 造 ， 我 必 拆 毁 ； 人 必 称 他 们 的 地 为 ‘ 罪 恶 之 境 ’ ； 称 他 们 的 民 为 ‘ 耶 和 华 永 远 恼 怒 之 民 ’ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23095', '39', '1', '5', '你 们 必 亲 眼 看 见 ， 也 必 说 ： “ 愿 耶 和 华 在 以 色 列 境 界 之 外 被 尊 为 大 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23096', '39', '1', '6', '＜ 斥 责 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23097', '39', '1', '7', '你 们 将 污 秽 的 食 物 献 在 我 的 坛 上 ， 且 说 ： ‘ 我 们 在 何 事 上 污 秽 你 呢 ？ ’ 因 你 们 说 ， 耶 和 华 的 桌 子 是 可 藐 视 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23098', '39', '1', '8', '你 们 将 瞎 眼 的 献 为 祭 物 ， 这 不 为 恶 吗 ？ 将 瘸 腿 的 、 有 病 的 献 上 ， 这 不 为 恶 吗 ？ 你 献 给 你 的 省 长 ， 他 岂 喜 悦 你 ， 岂 能 看 你 的 情 面 吗 ？ 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23099', '39', '1', '9', '“ 现 在 我 劝 你 们 恳 求 神 ， 他 好 施 恩 与 我 们 。 这 妄 献 的 事 ， 既 由 你 们 经 手 ， 他 岂 能 看 你 们 的 情 面 吗 ？ 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23100', '39', '1', '10', '甚 愿 你 们 中 间 有 一 人 关 上 殿 门 ， 免 得 你 们 徒 然 在 我 坛 上 烧 火 。 万 军 之 耶 和 华 说 ： 我 不 喜 悦 你 们 ， 也 不 从 你 们 手 中 收 纳 供 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23101', '39', '1', '11', '万 军 之 耶 和 华 说 ： 从 日 出 之 地 到 日 落 之 处 ， 我 的 名 在 外 邦 中 必 尊 为 大 。 在 各 处 ， 人 必 奉 我 的 名 烧 香 ， 献 洁 净 的 供 物 ， 因 为 我 的 名 在 外 邦 中 必 尊 为 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23102', '39', '1', '12', '你 们 却 亵 渎 我 的 名 ， 说 ： ‘ 耶 和 华 的 桌 子 是 污 秽 的 ， 其 上 的 食 物 是 可 藐 视 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23103', '39', '1', '13', '你 们 又 说 ： ‘ 这 些 事 何 等 烦 琐 ！ ’ 并 嗤 之 以 鼻 。 这 是 万 军 之 耶 和 华 说 的 。 你 们 把 抢 夺 的 、 瘸 腿 的 、 有 病 的 拿 来 献 上 为 祭 。 我 岂 能 从 你 们 手 中 收 纳 呢 ？ 这 是 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23104', '39', '1', '14', '行 诡 诈 的 在 群 中 有 公 羊 ， 他 许 愿 却 用 有 残 疾 的 献 给 主 ， 这 人 是 可 咒 诅 的 。 因 为 我 是 大 君 王 ， 我 的 名 在 外 邦 中 是 可 畏 的 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23105', '39', '2', '1', '“ 众 祭 司 啊 ， 这 诫 命 是 传 给 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23106', '39', '2', '2', '万 军 之 耶 和 华 说 ： 你 们 若 不 听 从 ， 也 不 放 在 心 上 ， 将 荣 耀 归 与 我 的 名 ， 我 就 使 咒 诅 临 到 你 们 ， 使 你 们 的 福 分 变 为 咒 诅 ； 因 你 们 不 把 诫 命 放 在 心 上 ， 我 已 经 咒 诅 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23107', '39', '2', '3', '我 必 斥 责 你 们 的 种 子 ， 又 把 你 们 牺 牲 的 粪 抹 你 们 的 脸 上 ； 你 们 要 与 粪 一 同 除 掉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23108', '39', '2', '4', '你 们 就 知 道 我 传 这 诫 命 给 你 们 ， 使 我 与 利 未 ｛ 或 译 ： 利 未 人 ｝ 所 立 的 约 可 以 常 存 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23109', '39', '2', '5', '我 曾 与 他 立 生 命 和 平 安 的 约 。 我 将 这 两 样 赐 给 他 ， 使 他 存 敬 畏 的 心 ， 他 就 敬 畏 我 ， 惧 怕 我 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23110', '39', '2', '6', '真 实 的 律 法 在 他 口 中 ， 他 嘴 里 没 有 不 义 的 话 。 他 以 平 安 和 正 直 与 我 同 行 ， 使 多 人 回 头 离 开 罪 孽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23111', '39', '2', '7', '祭 司 的 嘴 里 当 存 知 识 ， 人 也 当 由 他 口 中 寻 求 律 法 ， 因 为 他 是 万 军 之 耶 和 华 的 使 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23112', '39', '2', '8', '你 们 却 偏 离 正 道 ， 使 许 多 人 在 律 法 上 跌 倒 。 你 们 废 弃 我 与 利 未 所 立 的 约 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23113', '39', '2', '9', '所 以 我 使 你 们 被 众 人 藐 视 ， 看 为 下 贱 ； 因 你 们 不 守 我 的 道 ， 竟 在 律 法 上 瞻 徇 情 面 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23114', '39', '2', '10', '＜ 人 民 对 神 不 忠 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23115', '39', '2', '11', '犹 大 人 行 事 诡 诈 ， 并 且 在 以 色 列 和 耶 路 撒 冷 中 行 一 件 可 憎 的 事 ； 因 为 犹 大 人 亵 渎 耶 和 华 所 喜 爱 的 圣 洁 ｛ 或 译 ： 圣 地 ｝ ， 娶 事 奉 外 邦 神 的 女 子 为 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23116', '39', '2', '12', '凡 行 这 事 的 ， 无 论 何 人 ｛ 何 人 ： 原 文 是 叫 醒 的 ， 答 应 的 ｝ ， 就 是 献 供 物 给 万 军 之 耶 和 华 ， 耶 和 华 也 必 从 雅 各 的 帐 棚 中 剪 除 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23117', '39', '2', '13', '你 们 又 行 了 一 件 这 样 的 事 ， 使 前 妻 叹 息 哭 泣 的 眼 泪 遮 盖 耶 和 华 的 坛 ， 以 致 耶 和 华 不 再 看 顾 那 供 物 ， 也 不 乐 意 从 你 们 手 中 收 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23118', '39', '2', '14', '你 们 还 说 ： “ 这 是 为 什 么 呢 ？ ” 因 耶 和 华 在 你 和 你 幼 年 所 娶 的 妻 中 间 作 见 证 。 她 虽 是 你 的 配 偶 ， 又 是 你 盟 约 的 妻 ， 你 却 以 诡 诈 待 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23119', '39', '2', '15', '虽 然 神 有 灵 的 余 力 能 造 多 人 ， 他 不 是 单 造 一 人 吗 ？ 为 何 只 造 一 人 呢 ？ 乃 是 他 愿 人 得 虔 诚 的 后 裔 。 所 以 当 谨 守 你 们 的 心 ， 谁 也 不 可 以 诡 诈 待 幼 年 所 娶 的 妻 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23120', '39', '2', '16', '耶 和 华 ─ ─ 以 色 列 的 神 说 ： “ 休 妻 的 事 和 以 强 暴 待 妻 的 人 都 是 我 所 恨 恶 的 ！ 所 以 当 谨 守 你 们 的 心 ， 不 可 行 诡 诈 。 ” 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23121', '39', '2', '17', '＜ 审 判 之 日 已 近 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23122', '39', '3', '1', '万 军 之 耶 和 华 说 ： “ 我 要 差 遣 我 的 使 者 在 我 前 面 预 备 道 路 。 你 们 所 寻 求 的 主 必 忽 然 进 入 他 的 殿 ； 立 约 的 使 者 ， 就 是 你 们 所 仰 慕 的 ， 快 要 来 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23123', '39', '3', '2', '他 来 的 日 子 ， 谁 能 当 得 起 呢 ？ 他 显 现 的 时 候 ， 谁 能 立 得 住 呢 ？ 因 为 他 如 炼 金 之 人 的 火 ， 如 漂 布 之 人 的 碱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23124', '39', '3', '3', '他 必 坐 下 如 炼 净 银 子 的 ， 必 洁 净 利 未 人 ， 熬 炼 他 们 像 金 银 一 样 ； 他 们 就 凭 公 义 献 供 物 给 耶 和 华 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23125', '39', '3', '4', '那 时 ， 犹 大 和 耶 路 撒 冷 所 献 的 供 物 必 蒙 耶 和 华 悦 纳 ， 仿 佛 古 时 之 日 、 上 古 之 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23126', '39', '3', '5', '万 军 之 耶 和 华 说 ： “ 我 必 临 近 你 们 ， 施 行 审 判 。 我 必 速 速 作 见 证 ， 警 戒 行 邪 术 的 、 犯 奸 淫 的 、 起 假 誓 的 、 亏 负 人 之 工 价 的 、 欺 压 寡 妇 孤 儿 的 、 屈 枉 寄 居 的 ， 和 不 敬 畏 我 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23127', '39', '3', '6', '＜ 十 分 之 一 捐 献 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23128', '39', '3', '7', '万 军 之 耶 和 华 说 ： 从 你 们 列 祖 的 日 子 以 来 ， 你 们 常 常 偏 离 我 的 典 章 而 不 遵 守 。 现 在 你 们 要 转 向 我 ， 我 就 转 向 你 们 。 你 们 却 问 说 ： ‘ 我 们 如 何 才 是 转 向 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23129', '39', '3', '8', '人 岂 可 夺 取 神 之 物 呢 ？ 你 们 竟 夺 取 我 的 供 物 。 你 们 却 说 ： ‘ 我 们 在 何 事 上 夺 取 你 的 供 物 呢 ？ ’ 就 是 你 们 在 当 纳 的 十 分 之 一 和 当 献 的 供 物 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23130', '39', '3', '9', '因 你 们 通 国 的 人 都 夺 取 我 的 供 物 ， 咒 诅 就 临 到 你 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23131', '39', '3', '10', '万 军 之 耶 和 华 说 ： 你 们 要 将 当 纳 的 十 分 之 一 全 然 送 入 仓 库 ， 使 我 家 有 粮 ， 以 此 试 试 我 ， 是 否 为 你 们 敞 开 天 上 的 窗 户 ， 倾 福 与 你 们 ， 甚 至 无 处 可 容 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23132', '39', '3', '11', '万 军 之 耶 和 华 说 ： 我 必 为 你 们 斥 责 蝗 虫 ｛ 原 文 是 吞 噬 者 ｝ ， 不 容 它 毁 坏 你 们 的 土 产 。 你 们 田 间 的 葡 萄 树 在 未 熟 之 先 也 不 掉 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23133', '39', '3', '12', '万 军 之 耶 和 华 说 ： 万 国 必 称 你 们 为 有 福 的 ， 因 你 们 的 地 必 成 为 喜 乐 之 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23134', '39', '3', '13', '＜ 神 应 许 施 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23135', '39', '3', '14', '你 们 说 ： ‘ 事 奉 神 是 徒 然 的 ， 遵 守 神 所 吩 咐 的 ， 在 万 军 之 耶 和 华 面 前 苦 苦 斋 戒 ， 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23136', '39', '3', '15', '如 今 我 们 称 狂 傲 的 人 为 有 福 ， 并 且 行 恶 的 人 得 建 立 ； 他 们 虽 然 试 探 神 ， 却 得 脱 离 灾 难 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23137', '39', '3', '16', '那 时 ， 敬 畏 耶 和 华 的 彼 此 谈 论 ， 耶 和 华 侧 耳 而 听 ， 且 有 纪 念 册 在 他 面 前 ， 记 录 那 敬 畏 耶 和 华 、 思 念 他 名 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23138', '39', '3', '17', '万 军 之 耶 和 华 说 ： “ 在 我 所 定 的 日 子 ， 他 们 必 属 我 ， 特 特 归 我 。 我 必 怜 恤 他 们 ， 如 同 人 怜 恤 服 事 自 己 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23139', '39', '3', '18', '那 时 你 们 必 归 回 ， 将 善 人 和 恶 人 ， 事 奉 神 的 和 不 事 奉 神 的 ， 分 别 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23140', '39', '4', '1', '＜ 耶 和 华 的 日 子 临 近 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23141', '39', '4', '2', '但 向 你 们 敬 畏 我 名 的 人 必 有 公 义 的 日 头 出 现 ， 其 光 线 ｛ 原 文 是 翅 膀 ｝ 有 医 治 之 能 。 你 们 必 出 来 跳 跃 如 圈 里 的 肥 犊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23142', '39', '4', '3', '你 们 必 践 踏 恶 人 ； 在 我 所 定 的 日 子 ， 他 们 必 如 灰 尘 在 你 们 脚 掌 之 下 。 这 是 万 军 之 耶 和 华 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23143', '39', '4', '4', '“ 你 们 当 记 念 我 仆 人 摩 西 的 律 法 ， 就 是 我 在 何 烈 山 为 以 色 列 众 人 所 吩 咐 他 的 律 例 典 章 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23144', '39', '4', '5', '“ 看 哪 ， 耶 和 华 大 而 可 畏 之 日 未 到 以 前 ， 我 必 差 遣 先 知 以 利 亚 到 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23145', '39', '4', '6', '他 必 使 父 亲 的 心 转 向 儿 女 ， 儿 女 的 心 转 向 父 亲 ， 免 得 我 来 咒 诅 遍 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23146', '40', '1', '1', '＜ 耶 稣 基 督 的 家 谱 （ 路   3 : 2 3 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23147', '40', '1', '2', '亚 伯 拉 罕 生 以 撒 ； 以 撒 生 雅 各 ； 雅 各 生 犹 大 和 他 的 弟 兄 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23148', '40', '1', '3', '犹 大 从 她 玛 氏 生 法 勒 斯 和 谢 拉 ； 法 勒 斯 生 希 斯 仑 ； 希 斯 仑 生 亚 兰 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23149', '40', '1', '4', '亚 兰 生 亚 米 拿 达 ； 亚 米 拿 达 生 拿 顺 ； 拿 顺 生 撒 门 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23150', '40', '1', '5', '撒 门 从 喇 合 氏 生 波 阿 斯 ； 波 阿 斯 从 路 得 氏 生 俄 备 得 ； 俄 备 得 生 耶 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23151', '40', '1', '6', '耶 西 生 大 卫 王 。 大 卫 从 乌 利 亚 的 妻 子 生 所 罗 门 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23152', '40', '1', '7', '所 罗 门 生 罗 波 安 ； 罗 波 安 生 亚 比 雅 ； 亚 比 雅 生 亚 撒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23153', '40', '1', '8', '亚 撒 生 约 沙 法 ； 约 沙 法 生 约 兰 ； 约 兰 生 乌 西 雅 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23154', '40', '1', '9', '乌 西 雅 生 约 坦 ； 约 坦 生 亚 哈 斯 ； 亚 哈 斯 生 希 西 家 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23155', '40', '1', '10', '希 西 家 生 玛 拿 西 ； 玛 拿 西 生 亚 们 ； 亚 们 生 约 西 亚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23156', '40', '1', '11', '百 姓 被 迁 到 巴 比 伦 的 时 候 ， 约 西 亚 生 耶 哥 尼 雅 和 他 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23157', '40', '1', '12', '迁 到 巴 比 伦 之 后 ， 耶 哥 尼 雅 生 撒 拉 铁 ； 撒 拉 铁 生 所 罗 巴 伯 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23158', '40', '1', '13', '所 罗 巴 伯 生 亚 比 玉 ； 亚 比 玉 生 以 利 亚 敬 ； 以 利 亚 敬 生 亚 所 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23159', '40', '1', '14', '亚 所 生 撒 督 ； 撒 督 生 亚 金 ； 亚 金 生 以 律 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23160', '40', '1', '15', '以 律 生 以 利 亚 撒 ； 以 利 亚 撒 生 马 但 ； 马 但 生 雅 各 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23161', '40', '1', '16', '雅 各 生 约 瑟 ， 就 是 马 利 亚 的 丈 夫 。 那 称 为 基 督 的 耶 稣 是 从 马 利 亚 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23162', '40', '1', '17', '这 样 ， 从 亚 伯 拉 罕 到 大 卫 共 有 十 四 代 ； 从 大 卫 到 迁 至 巴 比 伦 的 时 候 也 有 十 四 代 ； 从 迁 至 巴 比 伦 的 时 候 到 基 督 又 有 十 四 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23163', '40', '1', '18', '＜ 耶 稣 基 督 降 生 （ 路   2 : 1 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23164', '40', '1', '19', '她 丈 夫 约 瑟 是 个 义 人 ， 不 愿 意 明 明 地 羞 辱 她 ， 想 要 暗 暗 地 把 她 休 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23165', '40', '1', '20', '正 思 念 这 事 的 时 候 ， 有 主 的 使 者 向 他 梦 中 显 现 ， 说 ： “ 大 卫 的 子 孙 约 瑟 ， 不 要 怕 ！ 只 管 娶 过 你 的 妻 子 马 利 亚 来 ， 因 她 所 怀 的 孕 是 从 圣 灵 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23166', '40', '1', '21', '她 将 要 生 一 个 儿 子 ， 你 要 给 他 起 名 叫 耶 稣 ， 因 他 要 将 自 己 的 百 姓 从 罪 恶 里 救 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23167', '40', '1', '22', '这 一 切 的 事 成 就 是 要 应 验 主 藉 先 知 所 说 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23168', '40', '1', '23', '说 ： 必 有 童 女 怀 孕 生 子 ； 人 要 称 他 的 名 为 以 马 内 利 。 （ 以 马 内 利 翻 出 来 就 是 “ 神 与 我 们 同 在 ” 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23169', '40', '1', '24', '约 瑟 醒 了 ， 起 来 ， 就 遵 着 主 使 者 的 吩 咐 把 妻 子 娶 过 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23170', '40', '1', '25', '只 是 没 有 和 她 同 房 ， 等 她 生 了 儿 子 ｛ 有 古 卷 ： 等 她 生 了 头 胎 的 儿 子 ｝ ， 就 给 他 起 名 叫 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23171', '40', '2', '1', '＜ 博 士 朝 拜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23172', '40', '2', '2', '“ 那 生 下 来 作 犹 太 人 之 王 的 在 哪 里 ？ 我 们 在 东 方 看 见 他 的 星 ， 特 来 拜 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23173', '40', '2', '3', '希 律 王 听 见 了 ， 就 心 里 不 安 ； 耶 路 撒 冷 合 城 的 人 也 都 不 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23174', '40', '2', '4', '他 就 召 齐 了 祭 司 长 和 民 间 的 文 士 ， 问 他 们 说 ： “ 基 督 当 生 在 何 处 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23175', '40', '2', '5', '他 们 回 答 说 ： “ 在 犹 太 的 伯 利 恒 。 因 为 有 先 知 记 着 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23176', '40', '2', '6', '犹 大 地 的 伯 利 恒 啊 ， 你 在 犹 大 诸 城 中 并 不 是 最 小 的 ； 因 为 将 来 有 一 位 君 王 要 从 你 那 里 出 来 ， 牧 养 我 以 色 列 民 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23177', '40', '2', '7', '当 下 ， 希 律 暗 暗 地 召 了 博 士 来 ， 细 问 那 星 是 什 么 时 候 出 现 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23178', '40', '2', '8', '就 差 他 们 往 伯 利 恒 去 ， 说 ： “ 你 们 去 仔 细 寻 访 那 小 孩 子 ， 寻 到 了 就 来 报 信 ， 我 也 好 去 拜 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23179', '40', '2', '9', '他 们 听 见 王 的 话 就 去 了 。 在 东 方 所 看 见 的 那 星 忽 然 在 他 们 前 头 行 ， 直 行 到 小 孩 子 的 地 方 ， 就 在 上 头 停 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23180', '40', '2', '10', '他 们 看 见 那 星 ， 就 大 大 地 欢 喜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23181', '40', '2', '11', '进 了 房 子 ， 看 见 小 孩 子 和 他 母 亲 马 利 亚 ， 就 俯 伏 拜 那 小 孩 子 ， 揭 开 宝 盒 ， 拿 黄 金 、 乳 香 、 没 药 为 礼 物 献 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23182', '40', '2', '12', '博 士 因 为 在 梦 中 被 主 指 示 不 要 回 去 见 希 律 ， 就 从 别 的 路 回 本 地 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23183', '40', '2', '13', '＜ 逃 往 埃 及 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23184', '40', '2', '14', '约 瑟 就 起 来 ， 夜 间 带 着 小 孩 子 和 他 母 亲 往 埃 及 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23185', '40', '2', '15', '住 在 那 里 ， 直 到 希 律 死 了 。 这 是 要 应 验 主 藉 先 知 所 说 的 话 ， 说 ： “ 我 从 埃 及 召 出 我 的 儿 子 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23186', '40', '2', '16', '＜ 屠 杀 男 孩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23187', '40', '2', '17', '这 就 应 了 先 知 耶 利 米 的 话 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23188', '40', '2', '18', '在 拉 玛 听 见 号 啕 大 哭 的 声 音 ， 是 拉 结 哭 她 儿 女 ， 不 肯 受 安 慰 ， 因 为 他 们 都 不 在 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23189', '40', '2', '19', '＜ 从 埃 及 回 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23190', '40', '2', '20', '“ 起 来 ！ 带 着 小 孩 子 和 他 母 亲 往 以 色 列 地 去 ， 因 为 要 害 小 孩 子 性 命 的 人 已 经 死 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23191', '40', '2', '21', '约 瑟 就 起 来 ， 把 小 孩 子 和 他 母 亲 带 到 以 色 列 地 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23192', '40', '2', '22', '只 因 听 见 亚 基 老 接 着 他 父 亲 希 律 作 了 犹 太 王 ， 就 怕 往 那 里 去 ， 又 在 梦 中 被 主 指 示 ， 便 往 加 利 利 境 内 去 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23193', '40', '2', '23', '到 了 一 座 城 ， 名 叫 拿 撒 勒 ， 就 住 在 那 里 。 这 是 要 应 验 先 知 所 说 ， 他 将 称 为 拿 撒 勒 人 的 话 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23194', '40', '3', '1', '＜ 施 洗 约 翰 传 道 （ 可   1 : 1 - 8 ； 路   3 : 1 - 1 8 ； 约   1 : 1 9 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23195', '40', '3', '2', '“ 天 国 近 了 ， 你 们 应 当 悔 改 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23196', '40', '3', '3', '这 人 就 是 先 知 以 赛 亚 所 说 的 。 他 说 ： “ 在 旷 野 有 人 声 喊 着 说 ： 预 备 主 的 道 ， 修 直 他 的 路 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23197', '40', '3', '4', '这 约 翰 身 穿 骆 驼 毛 的 衣 服 ， 腰 束 皮 带 ， 吃 的 是 蝗 虫 、 野 蜜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23198', '40', '3', '5', '那 时 ， 耶 路 撒 冷 和 犹 太 全 地 ， 并 约 旦 河 一 带 地 方 的 人 ， 都 出 去 到 约 翰 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23199', '40', '3', '6', '承 认 他 们 的 罪 ， 在 约 旦 河 里 受 他 的 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23200', '40', '3', '7', '约 翰 看 见 许 多 法 利 赛 人 和 撒 都 该 人 也 来 受 洗 ， 就 对 他 们 说 ： “ 毒 蛇 的 种 类 ！ 谁 指 示 你 们 逃 避 将 来 的 忿 怒 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23201', '40', '3', '8', '你 们 要 结 出 果 子 来 ， 与 悔 改 的 心 相 称 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23202', '40', '3', '9', '不 要 自 己 心 里 说 ： ‘ 有 亚 伯 拉 罕 为 我 们 的 祖 宗 。 ’ 我 告 诉 你 们 ， 神 能 从 这 些 石 头 中 给 亚 伯 拉 罕 兴 起 子 孙 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23203', '40', '3', '10', '现 在 斧 子 已 经 放 在 树 根 上 ， 凡 不 结 好 果 子 的 树 就 砍 下 来 ， 丢 在 火 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23204', '40', '3', '11', '我 是 用 水 给 你 们 施 洗 ， 叫 你 们 悔 改 。 但 那 在 我 以 后 来 的 ， 能 力 比 我 更 大 ， 我 就 是 给 他 提 鞋 也 不 配 。 他 要 用 圣 灵 与 火 给 你 们 施 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23205', '40', '3', '12', '他 手 里 拿 着 簸 箕 ， 要 扬 净 他 的 场 ， 把 麦 子 收 在 仓 里 ， 把 糠 用 不 灭 的 火 烧 尽 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23206', '40', '3', '13', '＜ 耶 稣 受 洗 （ 可   1 : 9 - 1 1 ； 路   3 : 2 1 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23207', '40', '3', '14', '约 翰 想 要 拦 住 他 ， 说 ： “ 我 当 受 你 的 洗 ， 你 反 倒 上 我 这 里 来 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23208', '40', '3', '15', '耶 稣 回 答 说 ： “ 你 暂 且 许 我 ， 因 为 我 们 理 当 这 样 尽 诸 般 的 义 ｛ 或 译 ： 礼 ｝ 。 ” 于 是 约 翰 许 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23209', '40', '3', '16', '耶 稣 受 了 洗 ， 随 即 从 水 里 上 来 。 天 忽 然 为 他 开 了 ， 他 就 看 见 神 的 灵 仿 佛 鸽 子 降 下 ， 落 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23210', '40', '3', '17', '从 天 上 有 声 音 说 ： “ 这 是 我 的 爱 子 ， 我 所 喜 悦 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23211', '40', '4', '1', '＜ 耶 稣 受 试 探 （ 可   1 : 1 2 - 1 3 ； 路   4 : 1 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23212', '40', '4', '2', '他 禁 食 四 十 昼 夜 ， 后 来 就 饿 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23213', '40', '4', '3', '那 试 探 人 的 进 前 来 ， 对 他 说 ： “ 你 若 是 神 的 儿 子 ， 可 以 吩 咐 这 些 石 头 变 成 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23214', '40', '4', '4', '耶 稣 却 回 答 说 ： “ 经 上 记 着 说 ： 人 活 着 ， 不 是 单 靠 食 物 ， 乃 是 靠 神 口 里 所 出 的 一 切 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23215', '40', '4', '5', '魔 鬼 就 带 他 进 了 圣 城 ， 叫 他 站 在 殿 顶 ｛ 顶 ： 原 文 是 翅 ｝ 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23216', '40', '4', '6', '对 他 说 ： “ 你 若 是 神 的 儿 子 ， 可 以 跳 下 去 ， 因 为 经 上 记 着 说 ： 主 要 为 你 吩 咐 他 的 使 者 用 手 托 着 你 ， 免 得 你 的 脚 碰 在 石 头 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23217', '40', '4', '7', '耶 稣 对 他 说 ： “ 经 上 又 记 着 说 ： ‘ 不 可 试 探 主 ─ ─ 你 的 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23218', '40', '4', '8', '魔 鬼 又 带 他 上 了 一 座 最 高 的 山 ， 将 世 上 的 万 国 与 万 国 的 荣 华 都 指 给 他 看 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23219', '40', '4', '9', '对 他 说 ： “ 你 若 俯 伏 拜 我 ， 我 就 把 这 一 切 都 赐 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23220', '40', '4', '10', '耶 稣 说 ： “ 撒 但 ｛ 就 是 抵 挡 的 意 思 ， 乃 魔 鬼 的 别 名 ｝ ， 退 去 吧 ！ 因 为 经 上 记 着 说 ： 当 拜 主 ─ ─ 你 的 神 ， 单 要 事 奉 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23221', '40', '4', '11', '于 是 ， 魔 鬼 离 了 耶 稣 ， 有 天 使 来 伺 候 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23222', '40', '4', '12', '＜ 开 始 在 加 利 利 传 道 （ 可   1 : 1 4 - 1 5 ； 路   4 : 1 4 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23223', '40', '4', '13', '后 又 离 开 拿 撒 勒 ， 往 迦 百 农 去 ， 就 住 在 那 里 。 那 地 方 靠 海 ， 在 西 布 伦 和 拿 弗 他 利 的 边 界 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23224', '40', '4', '14', '这 是 要 应 验 先 知 以 赛 亚 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23225', '40', '4', '15', '说 ： 西 布 伦 地 ， 拿 弗 他 利 地 ， 就 是 沿 海 的 路 ， 约 旦 河 外 ， 外 邦 人 的 加 利 利 地 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23226', '40', '4', '16', '那 坐 在 黑 暗 里 的 百 姓 看 见 了 大 光 ； 坐 在 死 荫 之 地 的 人 有 光 发 现 照 着 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23227', '40', '4', '17', '从 那 时 候 ， 耶 稣 就 传 起 道 来 ， 说 ： “ 天 国 近 了 ， 你 们 应 当 悔 改 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23228', '40', '4', '18', '＜ 呼 召 四 个 渔 夫 （ 可   1 : 1 6 - 2 0 ； 路   5 : 1 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23229', '40', '4', '19', '耶 稣 对 他 们 说 ： “ 来 跟 从 我 ， 我 要 叫 你 们 得 人 如 得 鱼 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23230', '40', '4', '20', '他 们 就 立 刻 舍 了 网 ， 跟 从 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23231', '40', '4', '21', '从 那 里 往 前 走 ， 又 看 见 弟 兄 二 人 ， 西 庇 太 的 儿 子 雅 各 和 他 兄 弟 约 翰 ， 同 他 们 的 父 亲 西 庇 太 在 船 上 补 网 ， 耶 稣 就 招 呼 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23232', '40', '4', '22', '他 们 立 刻 舍 了 船 ， 别 了 父 亲 ， 跟 从 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23233', '40', '4', '23', '＜ 耶 稣 向 广 大 的 群 众 传 道 （ 路   6 : 1 7 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23234', '40', '4', '24', '他 的 名 声 就 传 遍 了 叙 利 亚 。 那 里 的 人 把 一 切 害 病 的 ， 就 是 害 各 样 疾 病 、 各 样 疼 痛 的 和 被 鬼 附 的 、 癫 痫 的 、 瘫 痪 的 ， 都 带 了 来 ， 耶 稣 就 治 好 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23235', '40', '4', '25', '当 下 ， 有 许 多 人 从 加 利 利 、 低 加 坡 里 、 耶 路 撒 冷 、 犹 太 、 约 旦 河 外 来 跟 着 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23236', '40', '5', '1', '＜ 山 上 宝 训 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23237', '40', '5', '2', '他 就 开 口 教 训 他 们 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23238', '40', '5', '3', '＜ 论 福 （ 路   6 : 2 0 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23239', '40', '5', '4', '哀 恸 的 人 有 福 了 ！ 因 为 他 们 必 得 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23240', '40', '5', '5', '温 柔 的 人 有 福 了 ！ 因 为 他 们 必 承 受 地 土 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23241', '40', '5', '6', '饥 渴 慕 义 的 人 有 福 了 ！ 因 为 他 们 必 得 饱 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23242', '40', '5', '7', '怜 恤 人 的 人 有 福 了 ！ 因 为 他 们 必 蒙 怜 恤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23243', '40', '5', '8', '清 心 的 人 有 福 了 ！ 因 为 他 们 必 得 见 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23244', '40', '5', '9', '使 人 和 睦 的 人 有 福 了 ！ 因 为 他 们 必 称 为 神 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23245', '40', '5', '10', '为 义 受 逼 迫 的 人 有 福 了 ！ 因 为 天 国 是 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23246', '40', '5', '11', '“ 人 若 因 我 辱 骂 你 们 ， 逼 迫 你 们 ， 捏 造 各 样 坏 话 毁 谤 你 们 ， 你 们 就 有 福 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23247', '40', '5', '12', '应 当 欢 喜 快 乐 ， 因 为 你 们 在 天 上 的 赏 赐 是 大 的 。 在 你 们 以 前 的 先 知 ， 人 也 是 这 样 逼 迫 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23248', '40', '5', '13', '＜ 盐 和 光 （ 可   9 : 5 0 ； 路   1 4 : 3 4 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23249', '40', '5', '14', '你 们 是 世 上 的 光 。 城 造 在 山 上 是 不 能 隐 藏 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23250', '40', '5', '15', '人 点 灯 ， 不 放 在 斗 底 下 ， 是 放 在 灯 台 上 ， 就 照 亮 一 家 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23251', '40', '5', '16', '你 们 的 光 也 当 这 样 照 在 人 前 ， 叫 他 们 看 见 你 们 的 好 行 为 ， 便 将 荣 耀 归 给 你 们 在 天 上 的 父 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23252', '40', '5', '17', '＜ 论 律 法 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23253', '40', '5', '18', '我 实 在 告 诉 你 们 ， 就 是 到 天 地 都 废 去 了 ， 律 法 的 一 点 一 画 也 不 能 废 去 ， 都 要 成 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23254', '40', '5', '19', '所 以 ， 无 论 何 人 废 掉 这 诫 命 中 最 小 的 一 条 ， 又 教 训 人 这 样 做 ， 他 在 天 国 要 称 为 最 小 的 。 但 无 论 何 人 遵 行 这 诫 命 ， 又 教 训 人 遵 行 ， 他 在 天 国 要 称 为 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23255', '40', '5', '20', '我 告 诉 你 们 ， 你 们 的 义 若 不 胜 于 文 士 和 法 利 赛 人 的 义 ， 断 不 能 进 天 国 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23256', '40', '5', '21', '＜ 论 发 怒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23257', '40', '5', '22', '只 是 我 告 诉 你 们 ， 凡 ｛ 有 古 卷 在 凡 字 下 加 ： 无 缘 无 故 地 ｝ 向 弟 兄 动 怒 的 ， 难 免 受 审 断 ； 凡 骂 弟 兄 是 拉 加 的 ， 难 免 公 会 的 审 断 ； 凡 骂 弟 兄 是 魔 利 的 ， 难 免 地 狱 的 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23258', '40', '5', '23', '所 以 ， 你 在 祭 坛 上 献 礼 物 的 时 候 ， 若 想 起 弟 兄 向 你 怀 怨 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23259', '40', '5', '24', '就 把 礼 物 留 在 坛 前 ， 先 去 同 弟 兄 和 好 ， 然 后 来 献 礼 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23260', '40', '5', '25', '你 同 告 你 的 对 头 还 在 路 上 ， 就 赶 紧 与 他 和 息 ， 恐 怕 他 把 你 送 给 审 判 官 ， 审 判 官 交 付 衙 役 ， 你 就 下 在 监 里 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23261', '40', '5', '26', '我 实 在 告 诉 你 ， 若 有 一 文 钱 没 有 还 清 ， 你 断 不 能 从 那 里 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23262', '40', '5', '27', '＜ 论 奸 淫 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23263', '40', '5', '28', '只 是 我 告 诉 你 们 ， 凡 看 见 妇 女 就 动 淫 念 的 ， 这 人 心 里 已 经 与 她 犯 奸 淫 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23264', '40', '5', '29', '若 是 你 的 右 眼 叫 你 跌 倒 ， 就 剜 出 来 丢 掉 ， 宁 可 失 去 百 体 中 的 一 体 ， 不 叫 全 身 丢 在 地 狱 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23265', '40', '5', '30', '若 是 右 手 叫 你 跌 倒 ， 就 砍 下 来 丢 掉 ， 宁 可 失 去 百 体 中 的 一 体 ， 不 叫 全 身 下 入 地 狱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23266', '40', '5', '31', '＜ 论 休 妻 （ 太   1 9 : 9 ； 可   1 0 : 1 1 - 1 2 ； 路   1 6 : 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23267', '40', '5', '32', '只 是 我 告 诉 你 们 ， 凡 休 妻 的 ， 若 不 是 为 淫 乱 的 缘 故 ， 就 是 叫 她 作 淫 妇 了 ； 人 若 娶 这 被 休 的 妇 人 ， 也 是 犯 奸 淫 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23268', '40', '5', '33', '＜ 论 起 誓 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23269', '40', '5', '34', '只 是 我 告 诉 你 们 ， 什 么 誓 都 不 可 起 。 不 可 指 着 天 起 誓 ， 因 为 天 是 神 的 座 位 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23270', '40', '5', '35', '不 可 指 着 地 起 誓 ， 因 为 地 是 他 的 脚 凳 ； 也 不 可 指 着 耶 路 撒 冷 起 誓 ， 因 为 耶 路 撒 冷 是 大 君 的 京 城 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23271', '40', '5', '36', '又 不 可 指 着 你 的 头 起 誓 ， 因 为 你 不 能 使 一 根 头 发 变 黑 变 白 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23272', '40', '5', '37', '你 们 的 话 ， 是 ， 就 说 是 ； 不 是 ， 就 说 不 是 ； 若 再 多 说 ， 就 是 出 于 那 恶 者 ｛ 或 译 ： 就 是 从 恶 里 出 来 的 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23273', '40', '5', '38', '＜ 论 报 复 （ 路   6 : 2 9 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23274', '40', '5', '39', '只 是 我 告 诉 你 们 ， 不 要 与 恶 人 作 对 。 有 人 打 你 的 右 脸 ， 连 左 脸 也 转 过 来 由 他 打 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23275', '40', '5', '40', '有 人 想 要 告 你 ， 要 拿 你 的 里 衣 ， 连 外 衣 也 由 他 拿 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23276', '40', '5', '41', '有 人 强 逼 你 走 一 里 路 ， 你 就 同 他 走 二 里 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23277', '40', '5', '42', '有 求 你 的 ， 就 给 他 ； 有 向 你 借 贷 的 ， 不 可 推 辞 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23278', '40', '5', '43', '＜ 论 爱 仇 敌 （ 路   6 : 2 7 - 2 8 ； 6 : 3 2 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23279', '40', '5', '44', '只 是 我 告 诉 你 们 ， 要 爱 你 们 的 仇 敌 ， 为 那 逼 迫 你 们 的 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23280', '40', '5', '45', '这 样 就 可 以 作 你 们 天 父 的 儿 子 ； 因 为 他 叫 日 头 照 好 人 ， 也 照 歹 人 ； 降 雨 给 义 人 ， 也 给 不 义 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23281', '40', '5', '46', '你 们 若 单 爱 那 爱 你 们 的 人 ， 有 什 么 赏 赐 呢 ？ 就 是 税 吏 不 也 是 这 样 行 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23282', '40', '5', '47', '你 们 若 单 请 你 弟 兄 的 安 ， 比 人 有 什 么 长 处 呢 ？ 就 是 外 邦 人 不 也 是 这 样 行 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23283', '40', '5', '48', '所 以 ， 你 们 要 完 全 ， 像 你 们 的 天 父 完 全 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23284', '40', '6', '1', '＜ 论 施 舍 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23285', '40', '6', '2', '所 以 ， 你 施 舍 的 时 候 ， 不 可 在 你 前 面 吹 号 ， 像 那 假 冒 为 善 的 人 在 会 堂 里 和 街 道 上 所 行 的 ， 故 意 要 得 人 的 荣 耀 。 我 实 在 告 诉 你 们 ， 他 们 已 经 得 了 他 们 的 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23286', '40', '6', '3', '你 施 舍 的 时 候 ， 不 要 叫 左 手 知 道 右 手 所 做 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23287', '40', '6', '4', '要 叫 你 施 舍 的 事 行 在 暗 中 。 你 父 在 暗 中 察 看 ， 必 然 报 答 你 ｛ 有 古 卷 ： 必 在 明 处 报 答 你 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23288', '40', '6', '5', '＜ 论 祷 告 （ 路   1 1 : 2 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23289', '40', '6', '6', '你 祷 告 的 时 候 ， 要 进 你 的 内 屋 ， 关 上 门 ， 祷 告 你 在 暗 中 的 父 ； 你 父 在 暗 中 察 看 ， 必 然 报 答 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23290', '40', '6', '7', '你 们 祷 告 ， 不 可 像 外 邦 人 ， 用 许 多 重 复 话 ， 他 们 以 为 话 多 了 必 蒙 垂 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23291', '40', '6', '8', '你 们 不 可 效 法 他 们 ； 因 为 你 们 没 有 祈 求 以 先 ， 你 们 所 需 用 的 ， 你 们 的 父 早 已 知 道 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23292', '40', '6', '9', '所 以 ， 你 们 祷 告 要 这 样 说 ： 我 们 在 天 上 的 父 ： 愿 人 都 尊 你 的 名 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23293', '40', '6', '10', '愿 你 的 国 降 临 ； 愿 你 的 旨 意 行 在 地 上 ， 如 同 行 在 天 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23294', '40', '6', '11', '我 们 日 用 的 饮 食 ， 今 日 赐 给 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23295', '40', '6', '12', '免 我 们 的 债 ， 如 同 我 们 免 了 人 的 债 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23296', '40', '6', '13', '不 叫 我 们 遇 见 试 探 ； 救 我 们 脱 离 凶 恶 ｛ 或 译 ： 脱 离 恶 者 ｝ 。 因 为 国 度 、 权 柄 、 荣 耀 ， 全 是 你 的 ， 直 到 永 远 。 阿 们 ｛ 有 古 卷 没 有 因 为 … … 阿 们 等 字 ｝ ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23297', '40', '6', '14', '“ 你 们 饶 恕 人 的 过 犯 ， 你 们 的 天 父 也 必 饶 恕 你 们 的 过 犯 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23298', '40', '6', '15', '你 们 不 饶 恕 人 的 过 犯 ， 你 们 的 天 父 也 必 不 饶 恕 你 们 的 过 犯 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23299', '40', '6', '16', '＜ 论 禁 食 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23300', '40', '6', '17', '你 禁 食 的 时 候 ， 要 梳 头 洗 脸 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23301', '40', '6', '18', '不 叫 人 看 出 你 禁 食 来 ， 只 叫 你 暗 中 的 父 看 见 ； 你 父 在 暗 中 察 看 ， 必 然 报 答 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23302', '40', '6', '19', '＜ 论 天 上 的 财 宝 （ 路   1 2 : 3 3 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23303', '40', '6', '20', '只 要 积 攒 财 宝 在 天 上 ； 天 上 没 有 虫 子 咬 ， 不 能 锈 坏 ， 也 没 有 贼 挖 窟 窿 来 偷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23304', '40', '6', '21', '因 为 你 的 财 宝 在 哪 里 ， 你 的 心 也 在 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23305', '40', '6', '22', '＜ 论 心 里 的 光 （ 路   1 1 : 3 4 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23306', '40', '6', '23', '你 的 眼 睛 若 昏 花 ， 全 身 就 黑 暗 。 你 里 头 的 光 若 黑 暗 了 ， 那 黑 暗 是 何 等 大 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23307', '40', '6', '24', '＜ 论   神 和 财 利 （ 路   1 6 : 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23308', '40', '6', '25', '＜ 不 要 忧 虑 （ 路   1 2 : 2 2 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23309', '40', '6', '26', '你 们 看 那 天 上 的 飞 鸟 ， 也 不 种 ， 也 不 收 ， 也 不 积 蓄 在 仓 里 ， 你 们 的 天 父 尚 且 养 活 它 。 你 们 不 比 飞 鸟 贵 重 得 多 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23310', '40', '6', '27', '你 们 哪 一 个 能 用 思 虑 使 寿 数 多 加 一 刻 呢 ｛ 或 译 ： 使 身 量 多 加 一 肘 呢 ｝ ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23311', '40', '6', '28', '何 必 为 衣 裳 忧 虑 呢 ？ 你 想 野 地 里 的 百 合 花 怎 么 长 起 来 ； 它 也 不 劳 苦 ， 也 不 纺 线 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23312', '40', '6', '29', '然 而 我 告 诉 你 们 ， 就 是 所 罗 门 极 荣 华 的 时 候 ， 他 所 穿 戴 的 ， 还 不 如 这 花 一 朵 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23313', '40', '6', '30', '你 们 这 小 信 的 人 哪 ！ 野 地 里 的 草 今 天 还 在 ， 明 天 就 丢 在 炉 里 ， 神 还 给 它 这 样 的 妆 饰 ， 何 况 你 们 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23314', '40', '6', '31', '所 以 ， 不 要 忧 虑 说 ， 吃 什 么 ？ 喝 什 么 ？ 穿 什 么 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23315', '40', '6', '32', '这 都 是 外 邦 人 所 求 的 ， 你 们 需 用 的 这 一 切 东 西 ， 你 们 的 天 父 是 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23316', '40', '6', '33', '你 们 要 先 求 他 的 国 和 他 的 义 ， 这 些 东 西 都 要 加 给 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23317', '40', '6', '34', '所 以 ， 不 要 为 明 天 忧 虑 ， 因 为 明 天 自 有 明 天 的 忧 虑 ； 一 天 的 难 处 一 天 当 就 够 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23318', '40', '7', '1', '＜ 不 要 论 断 人 （ 路   6 : 3 7 - 3 8 , 4 1 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23319', '40', '7', '2', '因 为 你 们 怎 样 论 断 人 ， 也 必 怎 样 被 论 断 ； 你 们 用 什 么 量 器 量 给 人 ， 也 必 用 什 么 量 器 量 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23320', '40', '7', '3', '为 什 么 看 见 你 弟 兄 眼 中 有 刺 ， 却 不 想 自 己 眼 中 有 梁 木 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23321', '40', '7', '4', '你 自 己 眼 中 有 梁 木 ， 怎 能 对 你 弟 兄 说 ： ‘ 容 我 去 掉 你 眼 中 的 刺 ’ 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23322', '40', '7', '5', '你 这 假 冒 为 善 的 人 ！ 先 去 掉 自 己 眼 中 的 梁 木 ， 然 后 才 能 看 得 清 楚 ， 去 掉 你 弟 兄 眼 中 的 刺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23323', '40', '7', '6', '不 要 把 圣 物 给 狗 ， 也 不 要 把 你 们 的 珍 珠 丢 在 猪 前 ， 恐 怕 它 践 踏 了 珍 珠 ， 转 过 来 咬 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23324', '40', '7', '7', '＜ 祈 求 、 寻 找 、 叩 门 （ 路   1 1 : 9 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23325', '40', '7', '8', '因 为 凡 祈 求 的 ， 就 得 着 ； 寻 找 的 ， 就 寻 见 ； 叩 门 的 ， 就 给 他 开 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23326', '40', '7', '9', '你 们 中 间 谁 有 儿 子 求 饼 ， 反 给 他 石 头 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23327', '40', '7', '10', '求 鱼 ， 反 给 他 蛇 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23328', '40', '7', '11', '你 们 虽 然 不 好 ， 尚 且 知 道 拿 好 东 西 给 儿 女 ， 何 况 你 们 在 天 上 的 父 ， 岂 不 更 把 好 东 西 给 求 他 的 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23329', '40', '7', '12', '所 以 ， 无 论 何 事 ， 你 们 愿 意 人 怎 样 待 你 们 ， 你 们 也 要 怎 样 待 人 ， 因 为 这 就 是 律 法 和 先 知 的 道 理 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23330', '40', '7', '13', '＜ 窄 门 （ 路   1 3 : 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23331', '40', '7', '14', '引 到 永 生 ， 那 门 是 窄 的 ， 路 是 小 的 ， 找 着 的 人 也 少 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23332', '40', '7', '15', '＜ 两 种 果 树 （ 路   6 : 4 3 - 4 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23333', '40', '7', '16', '凭 着 他 们 的 果 子 ， 就 可 以 认 出 他 们 来 。 荆 棘 上 岂 能 摘 葡 萄 呢 ？ 蒺 藜 里 岂 能 摘 无 花 果 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23334', '40', '7', '17', '这 样 ， 凡 好 树 都 结 好 果 子 ， 惟 独 坏 树 结 坏 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23335', '40', '7', '18', '好 树 不 能 结 坏 果 子 ； 坏 树 不 能 结 好 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23336', '40', '7', '19', '凡 不 结 好 果 子 的 树 就 砍 下 来 ， 丢 在 火 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23337', '40', '7', '20', '所 以 ， 凭 着 他 们 的 果 子 就 可 以 认 出 他 们 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23338', '40', '7', '21', '＜ 我 不 认 识 你 们 （ 路   1 3 : 2 5 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23339', '40', '7', '22', '当 那 日 必 有 许 多 人 对 我 说 ： ‘ 主 啊 ， 主 啊 ， 我 们 不 是 奉 你 的 名 传 道 ， 奉 你 的 名 赶 鬼 ， 奉 你 的 名 行 许 多 异 能 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23340', '40', '7', '23', '我 就 明 明 地 告 诉 他 们 说 ： ‘ 我 从 来 不 认 识 你 们 ， 你 们 这 些 作 恶 的 人 ， 离 开 我 去 吧 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23341', '40', '7', '24', '＜ 两 种 盖 房 子 的 人 （ 路   6 : 4 6 - 4 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23342', '40', '7', '25', '雨 淋 ， 水 冲 ， 风 吹 ， 撞 着 那 房 子 ， 房 子 总 不 倒 塌 ， 因 为 根 基 立 在 磐 石 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23343', '40', '7', '26', '凡 听 见 我 这 话 不 去 行 的 ， 好 比 一 个 无 知 的 人 ， 把 房 子 盖 在 沙 土 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23344', '40', '7', '27', '雨 淋 ， 水 冲 ， 风 吹 ， 撞 着 那 房 子 ， 房 子 就 倒 塌 了 ， 并 且 倒 塌 得 很 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23345', '40', '7', '28', '耶 稣 讲 完 了 这 些 话 ， 众 人 都 希 奇 他 的 教 训 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23346', '40', '7', '29', '因 为 他 教 训 他 们 ， 正 像 有 权 柄 的 人 ， 不 像 他 们 的 文 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23347', '40', '8', '1', '＜ 洁 净 长 大 痲 疯 的 人 （ 可   1 : 4 0 - 4 5 ； 路   5 : 1 2 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23348', '40', '8', '2', '有 一 个 长 大 痲 疯 的 来 拜 他 ， 说 ： “ 主 若 肯 ， 必 能 叫 我 洁 净 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23349', '40', '8', '3', '耶 稣 伸 手 摸 他 ， 说 ： “ 我 肯 ， 你 洁 净 了 吧 ！ ” 他 的 大 痲 疯 立 刻 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23350', '40', '8', '4', '耶 稣 对 他 说 ： “ 你 切 不 可 告 诉 人 ， 只 要 去 把 身 体 给 祭 司 察 看 ， 献 上 摩 西 所 吩 咐 的 礼 物 ， 对 众 人 作 证 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23351', '40', '8', '5', '＜ 治 好 百 夫 长 的 仆 人 （ 路   7 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23352', '40', '8', '6', '“ 主 啊 ， 我 的 仆 人 害 瘫 痪 病 ， 躺 在 家 里 ， 甚 是 疼 苦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23353', '40', '8', '7', '耶 稣 说 ： “ 我 去 医 治 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23354', '40', '8', '8', '百 夫 长 回 答 说 ： “ 主 啊 ， 你 到 我 舍 下 ， 我 不 敢 当 ； 只 要 你 说 一 句 话 ， 我 的 仆 人 就 必 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23355', '40', '8', '9', '因 为 我 在 人 的 权 下 ， 也 有 兵 在 我 以 下 ； 对 这 个 说 ： ‘ 去 ！ ’ 他 就 去 ； 对 那 个 说 ： ‘ 来 ！ ’ 他 就 来 ； 对 我 的 仆 人 说 ： ‘ 你 做 这 事 ！ ’ 他 就 去 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23356', '40', '8', '10', '耶 稣 听 见 就 希 奇 ， 对 跟 从 的 人 说 ： “ 我 实 在 告 诉 你 们 ， 这 么 大 的 信 心 ， 就 是 在 以 色 列 中 ， 我 也 没 有 遇 见 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23357', '40', '8', '11', '我 又 告 诉 你 们 ， 从 东 从 西 ， 将 有 许 多 人 来 ， 在 天 国 里 与 亚 伯 拉 罕 、 以 撒 、 雅 各 一 同 坐 席 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23358', '40', '8', '12', '惟 有 本 国 的 子 民 竟 被 赶 到 外 边 黑 暗 里 去 ， 在 那 里 必 要 哀 哭 切 齿 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23359', '40', '8', '13', '耶 稣 对 百 夫 长 说 ： “ 你 回 去 吧 ！ 照 你 的 信 心 ， 给 你 成 全 了 。 ” 那 时 ， 他 的 仆 人 就 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23360', '40', '8', '14', '＜ 治 好 许 多 病 人 （ 可   1 : 2 9 - 3 4 ； 路   4 : 3 8 - 4 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23361', '40', '8', '15', '耶 稣 把 她 的 手 一 摸 ， 热 就 退 了 ； 她 就 起 来 服 事 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23362', '40', '8', '16', '到 了 晚 上 ， 有 人 带 着 许 多 被 鬼 附 的 来 到 耶 稣 跟 前 ， 他 只 用 一 句 话 就 把 鬼 都 赶 出 去 ， 并 且 治 好 了 一 切 有 病 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23363', '40', '8', '17', '这 是 要 应 验 先 知 以 赛 亚 的 话 ， 说 ： 他 代 替 我 们 的 软 弱 ， 担 当 我 们 的 疾 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23364', '40', '8', '18', '＜ 要 跟 从 耶 稣 的 人 （ 路   9 : 5 7 - 6 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23365', '40', '8', '19', '有 一 个 文 士 来 ， 对 他 说 ： “ 夫 子 ， 你 无 论 往 哪 里 去 ， 我 要 跟 从 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23366', '40', '8', '20', '耶 稣 说 ： “ 狐 狸 有 洞 ， 天 空 的 飞 鸟 有 窝 ， 人 子 却 没 有 枕 头 的 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23367', '40', '8', '21', '又 有 一 个 门 徒 对 耶 稣 说 ： “ 主 啊 ， 容 我 先 回 去 埋 葬 我 的 父 亲 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23368', '40', '8', '22', '耶 稣 说 ： “ 任 凭 死 人 埋 葬 他 们 的 死 人 ； 你 跟 从 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23369', '40', '8', '23', '＜ 平 静 风 和 海 （ 可   4 : 3 5 - 4 1 ； 路   8 : 2 2 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23370', '40', '8', '24', '海 里 忽 然 起 了 暴 风 ， 甚 至 船 被 波 浪 掩 盖 ； 耶 稣 却 睡 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23371', '40', '8', '25', '门 徒 来 叫 醒 了 他 ， 说 ： “ 主 啊 ， 救 我 们 ， 我 们 丧 命 啦 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23372', '40', '8', '26', '耶 稣 说 ： “ 你 们 这 小 信 的 人 哪 ， 为 什 么 胆 怯 呢 ？ ” 于 是 起 来 ， 斥 责 风 和 海 ， 风 和 海 就 大 大 地 平 静 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23373', '40', '8', '27', '众 人 希 奇 ， 说 ： “ 这 是 怎 样 的 人 ？ 连 风 和 海 也 听 从 他 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23374', '40', '8', '28', '＜ 治 好 加 大 拉 被 鬼 附 的 人 （ 可   5 : 1 - 2 0 ； 路   8 : 2 6 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23375', '40', '8', '29', '他 们 喊 着 说 ： “ 神 的 儿 子 ， 我 们 与 你 有 什 么 相 干 ？ 时 候 还 没 有 到 ， 你 就 上 这 里 来 叫 我 们 受 苦 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23376', '40', '8', '30', '离 他 们 很 远 ， 有 一 大 群 猪 吃 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23377', '40', '8', '31', '鬼 就 央 求 耶 稣 ， 说 ： “ 若 把 我 们 赶 出 去 ， 就 打 发 我 们 进 入 猪 群 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23378', '40', '8', '32', '耶 稣 说 ： “ 去 吧 ！ ” 鬼 就 出 来 ， 进 入 猪 群 。 全 群 忽 然 闯 下 山 崖 ， 投 在 海 里 淹 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23379', '40', '8', '33', '放 猪 的 就 逃 跑 进 城 ， 将 这 一 切 事 和 被 鬼 附 的 人 所 遭 遇 的 都 告 诉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23380', '40', '8', '34', '合 城 的 人 都 出 来 迎 见 耶 稣 ， 既 见 了 就 央 求 他 离 开 他 们 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23381', '40', '9', '1', '＜ 治 好 瘫 痪 病 人 （ 可   2 : 1 - 1 2 ； 路   5 : 1 7 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23382', '40', '9', '2', '有 人 用 褥 子 抬 着 一 个 瘫 子 到 耶 稣 跟 前 来 。 耶 稣 见 他 们 的 信 心 ， 就 对 瘫 子 说 ： “ 小 子 ， 放 心 吧 ！ 你 的 罪 赦 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23383', '40', '9', '3', '有 几 个 文 士 心 里 说 ： “ 这 个 人 说 僭 妄 的 话 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23384', '40', '9', '4', '耶 稣 知 道 他 们 的 心 意 ， 就 说 ： “ 你 们 为 什 么 心 里 怀 着 恶 念 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23385', '40', '9', '5', '或 说 ‘ 你 的 罪 赦 了 ’ ， 或 说 ‘ 你 起 来 行 走 ’ ， 哪 一 样 容 易 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23386', '40', '9', '6', '但 要 叫 你 们 知 道 ， 人 子 在 地 上 有 赦 罪 的 权 柄 ” ； 就 对 瘫 子 说 ： “ 起 来 ！ 拿 你 的 褥 子 回 家 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23387', '40', '9', '7', '那 人 就 起 来 ， 回 家 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23388', '40', '9', '8', '众 人 看 见 都 惊 奇 ， 就 归 荣 耀 与 神 ， 因 为 他 将 这 样 的 权 柄 赐 给 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23389', '40', '9', '9', '＜ 呼 召 马 太 （ 可   2 : 1 3 - 1 7 ； 路   5 : 2 7 - 3 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23390', '40', '9', '10', '耶 稣 在 屋 里 坐 席 的 时 候 ， 有 好 些 税 吏 和 罪 人 来 ， 与 耶 稣 和 他 的 门 徒 一 同 坐 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23391', '40', '9', '11', '法 利 赛 人 看 见 ， 就 对 耶 稣 的 门 徒 说 ： “ 你 们 的 先 生 为 什 么 和 税 吏 并 罪 人 一 同 吃 饭 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23392', '40', '9', '12', '耶 稣 听 见 ， 就 说 ： “ 康 健 的 人 用 不 着 医 生 ， 有 病 的 人 才 用 得 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23393', '40', '9', '13', '经 上 说 ： ‘ 我 喜 爱 怜 恤 ， 不 喜 爱 祭 祀 。 ’ 这 句 话 的 意 思 ， 你 们 且 去 揣 摩 。 我 来 本 不 是 召 义 人 ， 乃 是 召 罪 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23394', '40', '9', '14', '＜ 禁 食 的 问 题 （ 可   2 : 1 8 - 2 2 ； 路   5 : 3 3 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23395', '40', '9', '15', '耶 稣 对 他 们 说 ： “ 新 郎 和 陪 伴 之 人 同 在 的 时 候 ， 陪 伴 之 人 岂 能 哀 恸 呢 ？ 但 日 子 将 到 ， 新 郎 要 离 开 他 们 ， 那 时 候 他 们 就 要 禁 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23396', '40', '9', '16', '没 有 人 把 新 布 补 在 旧 衣 服 上 ； 因 为 所 补 上 的 反 带 坏 了 那 衣 服 ， 破 的 就 更 大 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23397', '40', '9', '17', '也 没 有 人 把 新 酒 装 在 旧 皮 袋 里 ； 若 是 这 样 ， 皮 袋 就 裂 开 ， 酒 漏 出 来 ， 连 皮 袋 也 坏 了 。 惟 独 把 新 酒 装 在 新 皮 袋 里 ， 两 样 就 都 保 全 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23398', '40', '9', '18', '＜ 管 会 堂 者 的 女 儿 和 血 漏 的 女 人 （ 可   5 : 2 1 - 4 3 ； 路   8 : 4 0 - 5 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23399', '40', '9', '19', '耶 稣 便 起 来 跟 着 他 去 ； 门 徒 也 跟 了 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23400', '40', '9', '20', '有 一 个 女 人 ， 患 了 十 二 年 的 血 漏 ， 来 到 耶 稣 背 后 ， 摸 他 的 衣 裳 繸 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23401', '40', '9', '21', '因 为 她 心 里 说 ： “ 我 只 摸 他 的 衣 裳 ， 就 必 痊 愈 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23402', '40', '9', '22', '耶 稣 转 过 来 ， 看 见 她 ， 就 说 ： “ 女 儿 ， 放 心 ！ 你 的 信 救 了 你 。 ” 从 那 时 候 ， 女 人 就 痊 愈 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23403', '40', '9', '23', '耶 稣 到 了 管 会 堂 的 家 里 ， 看 见 有 吹 手 ， 又 有 许 多 人 乱 嚷 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23404', '40', '9', '24', '就 说 ： “ 退 去 吧 ！ 这 闺 女 不 是 死 了 ， 是 睡 着 了 。 ” 他 们 就 嗤 笑 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23405', '40', '9', '25', '众 人 既 被 撵 出 ， 耶 稣 就 进 去 ， 拉 着 闺 女 的 手 ， 闺 女 便 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23406', '40', '9', '26', '于 是 这 风 声 传 遍 了 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23407', '40', '9', '27', '＜ 两 个 瞎 子 得 医 治 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23408', '40', '9', '28', '耶 稣 进 了 房 子 ， 瞎 子 就 来 到 他 跟 前 。 耶 稣 说 ： “ 你 们 信 我 能 做 这 事 吗 ？ ” 他 们 说 ： “ 主 啊 ， 我 们 信 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23409', '40', '9', '29', '耶 稣 就 摸 他 们 的 眼 睛 ， 说 ： “ 照 着 你 们 的 信 给 你 们 成 全 了 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23410', '40', '9', '30', '他 们 的 眼 睛 就 开 了 。 耶 稣 切 切 地 嘱 咐 他 们 说 ： “ 你 们 要 小 心 ， 不 可 叫 人 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23411', '40', '9', '31', '他 们 出 去 ， 竟 把 他 的 名 声 传 遍 了 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23412', '40', '9', '32', '＜ 治 好 哑 巴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23413', '40', '9', '33', '鬼 被 赶 出 去 ， 哑 巴 就 说 出 话 来 。 众 人 都 希 奇 ， 说 ： “ 在 以 色 列 中 ， 从 来 没 有 见 过 这 样 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23414', '40', '9', '34', '法 利 赛 人 却 说 ： “ 他 是 靠 着 鬼 王 赶 鬼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23415', '40', '9', '35', '＜ 耶 稣 的 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23416', '40', '9', '36', '他 看 见 许 多 的 人 ， 就 怜 悯 他 们 ； 因 为 他 们 困 苦 流 离 ， 如 同 羊 没 有 牧 人 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23417', '40', '9', '37', '于 是 对 门 徒 说 ： “ 要 收 的 庄 稼 多 ， 做 工 的 人 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23418', '40', '9', '38', '所 以 ， 你 们 当 求 庄 稼 的 主 打 发 工 人 出 去 收 他 的 庄 稼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23419', '40', '10', '1', '＜ 十 二 使 徒 （ 可   3 : 1 3 - 1 9 ； 路   6 : 1 2 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23420', '40', '10', '2', '这 十 二 使 徒 的 名 ： 头 一 个 叫 西 门 （ 又 称 彼 得 ） ， 还 有 他 兄 弟 安 得 烈 ， 西 庇 太 的 儿 子 雅 各 和 雅 各 的 兄 弟 约 翰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23421', '40', '10', '3', '腓 力 和 巴 多 罗 买 ， 多 马 和 税 吏 马 太 ， 亚 勒 腓 的 儿 子 雅 各 ， 和 达 太 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23422', '40', '10', '4', '奋 锐 党 的 西 门 ， 还 有 卖 耶 稣 的 加 略 人 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23423', '40', '10', '5', '＜ 十 二 使 徒 的 使 命 （ 可   6 : 7 - 1 3 ； 路   9 : 1 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23424', '40', '10', '6', '宁 可 往 以 色 列 家 迷 失 的 羊 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23425', '40', '10', '7', '随 走 随 传 ， 说 ‘ 天 国 近 了 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23426', '40', '10', '8', '医 治 病 人 ， 叫 死 人 复 活 ， 叫 长 大 痲 疯 的 洁 净 ， 把 鬼 赶 出 去 。 你 们 白 白 地 得 来 ， 也 要 白 白 地 舍 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23427', '40', '10', '9', '腰 袋 里 不 要 带 金 银 铜 钱 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23428', '40', '10', '10', '行 路 不 要 带 口 袋 ； 不 要 带 两 件 褂 子 ， 也 不 要 带 鞋 和 柺 杖 。 因 为 工 人 得 饮 食 是 应 当 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23429', '40', '10', '11', '你 们 无 论 进 哪 一 城 ， 哪 一 村 ， 要 打 听 那 里 谁 是 好 人 ， 就 住 在 他 家 ， 直 住 到 走 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23430', '40', '10', '12', '进 他 家 里 去 ， 要 请 他 的 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23431', '40', '10', '13', '那 家 若 配 得 平 安 ， 你 们 所 求 的 平 安 就 必 临 到 那 家 ； 若 不 配 得 ， 你 们 所 求 的 平 安 仍 归 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23432', '40', '10', '14', '凡 不 接 待 你 们 、 不 听 你 们 话 的 人 ， 你 们 离 开 那 家 ， 或 是 那 城 的 时 候 ， 就 把 脚 上 的 尘 土 跺 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23433', '40', '10', '15', '我 实 在 告 诉 你 们 ， 当 审 判 的 日 子 ， 所 多 玛 和 蛾 摩 拉 所 受 的 ， 比 那 城 还 容 易 受 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23434', '40', '10', '16', '＜ 将 来 的 逼 迫 （ 可   1 3 : 9 - 1 3 ； 路   2 1 : 1 2 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23435', '40', '10', '17', '你 们 要 防 备 人 ； 因 为 他 们 要 把 你 们 交 给 公 会 ， 也 要 在 会 堂 里 鞭 打 你 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23436', '40', '10', '18', '并 且 你 们 要 为 我 的 缘 故 被 送 到 诸 侯 君 王 面 前 ， 对 他 们 和 外 邦 人 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23437', '40', '10', '19', '你 们 被 交 的 时 候 ， 不 要 思 虑 怎 样 说 话 ， 或 说 什 么 话 。 到 那 时 候 ， 必 赐 给 你 们 当 说 的 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23438', '40', '10', '20', '因 为 不 是 你 们 自 己 说 的 ， 乃 是 你 们 父 的 灵 在 你 们 里 头 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23439', '40', '10', '21', '弟 兄 要 把 弟 兄 ， 父 亲 要 把 儿 子 ， 送 到 死 地 ； 儿 女 要 与 父 母 为 敌 ， 害 死 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23440', '40', '10', '22', '并 且 你 们 要 为 我 的 名 被 众 人 恨 恶 。 惟 有 忍 耐 到 底 的 必 然 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23441', '40', '10', '23', '有 人 在 这 城 里 逼 迫 你 们 ， 就 逃 到 那 城 里 去 。 我 实 在 告 诉 你 们 ， 以 色 列 的 城 邑 ， 你 们 还 没 有 走 遍 ， 人 子 就 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23442', '40', '10', '24', '学 生 不 能 高 过 先 生 ； 仆 人 不 能 高 过 主 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23443', '40', '10', '25', '学 生 和 先 生 一 样 ， 仆 人 和 主 人 一 样 ， 也 就 罢 了 。 人 既 骂 家 主 是 别 西 卜 ｛ 别 西 卜 ： 是 鬼 王 的 名 ｝ ， 何 况 他 的 家 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23444', '40', '10', '26', '＜ 该 怕 的 是 谁 （ 路   1 2 : 2 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23445', '40', '10', '27', '我 在 暗 中 告 诉 你 们 的 ， 你 们 要 在 明 处 说 出 来 ； 你 们 耳 中 所 听 的 ， 要 在 房 上 宣 扬 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23446', '40', '10', '28', '那 杀 身 体 、 不 能 杀 灵 魂 的 ， 不 要 怕 他 们 ； 惟 有 能 把 身 体 和 灵 魂 都 灭 在 地 狱 里 的 ， 正 要 怕 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23447', '40', '10', '29', '两 个 麻 雀 不 是 卖 一 分 银 子 吗 ？ 若 是 你 们 的 父 不 许 ， 一 个 也 不 能 掉 在 地 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23448', '40', '10', '30', '就 是 你 们 的 头 发 也 都 被 数 过 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23449', '40', '10', '31', '所 以 ， 不 要 惧 怕 ， 你 们 比 许 多 麻 雀 还 贵 重 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23450', '40', '10', '32', '＜ 在 人 的 面 前 承 认 基 督 （ 路   1 2 : 8 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23451', '40', '10', '33', '凡 在 人 面 前 不 认 我 的 ， 我 在 我 天 上 的 父 面 前 也 必 不 认 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23452', '40', '10', '34', '＜ 不 是 和 平 ， 而 是 刀 剑 （ 路   1 2 : 5 1 - 5 3 ； 1 4 : 2 6 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23453', '40', '10', '35', '因 为 我 来 是 叫 人 与 父 亲 生 疏 ， 女 儿 与 母 亲 生 疏 ， 媳 妇 与 婆 婆 生 疏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23454', '40', '10', '36', '人 的 仇 敌 就 是 自 己 家 里 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23455', '40', '10', '37', '“ 爱 父 母 过 于 爱 我 的 ， 不 配 作 我 的 门 徒 ； 爱 儿 女 过 于 爱 我 的 ， 不 配 作 我 的 门 徒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23456', '40', '10', '38', '不 背 着 他 的 十 字 架 跟 从 我 的 ， 也 不 配 作 我 的 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23457', '40', '10', '39', '得 着 生 命 的 ， 将 要 失 丧 生 命 ； 为 我 失 丧 生 命 的 ， 将 要 得 着 生 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23458', '40', '10', '40', '＜ 论 报 赏 （ 可   9 : 4 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23459', '40', '10', '41', '人 因 为 先 知 的 名 接 待 先 知 ， 必 得 先 知 所 得 的 赏 赐 ； 人 因 为 义 人 的 名 接 待 义 人 ， 必 得 义 人 所 得 的 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23460', '40', '10', '42', '无 论 何 人 ， 因 为 门 徒 的 名 ， 只 把 一 杯 凉 水 给 这 小 子 里 的 一 个 喝 ， 我 实 在 告 诉 你 们 ， 这 人 不 能 不 得 赏 赐 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23461', '40', '11', '1', '耶 稣 吩 咐 完 了 十 二 个 门 徒 ， 就 离 开 那 里 ， 往 各 城 去 传 道 、 教 训 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23462', '40', '11', '2', '＜ 施 洗 约 翰 的 门 徒 来 见 耶 稣 （ 路   7 : 1 8 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23463', '40', '11', '3', '问 他 说 ： “ 那 将 要 来 的 是 你 吗 ？ 还 是 我 们 等 候 别 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23464', '40', '11', '4', '耶 稣 回 答 说 ： “ 你 们 去 ， 把 所 听 见 、 所 看 见 的 事 告 诉 约 翰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23465', '40', '11', '5', '就 是 瞎 子 看 见 ， 瘸 子 行 走 ， 长 大 痲 疯 的 洁 净 ， 聋 子 听 见 ， 死 人 复 活 ， 穷 人 有 福 音 传 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23466', '40', '11', '6', '凡 不 因 我 跌 倒 的 就 有 福 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23467', '40', '11', '7', '他 们 走 的 时 候 ， 耶 稣 就 对 众 人 讲 论 约 翰 说 ： “ 你 们 从 前 出 到 旷 野 是 要 看 什 么 呢 ？ 要 看 风 吹 动 的 芦 苇 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23468', '40', '11', '8', '你 们 出 去 到 底 是 要 看 什 么 ？ 要 看 穿 细 软 衣 服 的 人 吗 ？ 那 穿 细 软 衣 服 的 人 是 在 王 宫 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23469', '40', '11', '9', '你 们 出 去 究 竟 是 为 什 么 ？ 是 要 看 先 知 吗 ？ 我 告 诉 你 们 ， 是 的 ， 他 比 先 知 大 多 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23470', '40', '11', '10', '经 上 记 着 说 ： ‘ 我 要 差 遣 我 的 使 者 在 你 前 面 预 备 道 路 ’ ， 所 说 的 就 是 这 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23471', '40', '11', '11', '我 实 在 告 诉 你 们 ， 凡 妇 人 所 生 的 ， 没 有 一 个 兴 起 来 大 过 施 洗 约 翰 的 ； 然 而 天 国 里 最 小 的 比 他 还 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23472', '40', '11', '12', '从 施 洗 约 翰 的 时 候 到 如 今 ， 天 国 是 努 力 进 入 的 ， 努 力 的 人 就 得 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23473', '40', '11', '13', '因 为 众 先 知 和 律 法 说 预 言 ， 到 约 翰 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23474', '40', '11', '14', '你 们 若 肯 领 受 ， 这 人 就 是 那 应 当 来 的 以 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23475', '40', '11', '15', '有 耳 可 听 的 ， 就 应 当 听 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23476', '40', '11', '16', '我 可 用 什 么 比 这 世 代 呢 ？ 好 像 孩 童 坐 在 街 市 上 招 呼 同 伴 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23477', '40', '11', '17', '我 们 向 你 们 吹 笛 ， 你 们 不 跳 舞 ； 我 们 向 你 们 举 哀 ， 你 们 不 捶 胸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23478', '40', '11', '18', '约 翰 来 了 ， 也 不 吃 也 不 喝 ， 人 就 说 他 是 被 鬼 附 着 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23479', '40', '11', '19', '人 子 来 了 ， 也 吃 也 喝 ， 人 又 说 他 是 贪 食 好 酒 的 人 ， 是 税 吏 和 罪 人 的 朋 友 。 但 智 慧 之 子 总 以 智 慧 为 是 ｛ 有 古 卷 ： 但 智 慧 在 行 为 上 就 显 为 是 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23480', '40', '11', '20', '＜ 耶 稣 责 备 不 悔 改 的 城 （ 路   1 0 : 1 3 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23481', '40', '11', '21', '“ 哥 拉 汛 哪 ， 你 有 祸 了 ！ 伯 赛 大 啊 ， 你 有 祸 了 ！ 因 为 在 你 们 中 间 所 行 的 异 能 ， 若 行 在 泰 尔 、 西 顿 ， 他 们 早 已 披 麻 蒙 灰 悔 改 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23482', '40', '11', '22', '但 我 告 诉 你 们 ， 当 审 判 的 日 子 ， 泰 尔 、 西 顿 所 受 的 ， 比 你 们 还 容 易 受 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23483', '40', '11', '23', '迦 百 农 啊 ， 你 已 经 升 到 天 上 ｛ 或 译 ： 你 将 要 升 到 天 上 吗 ｝ ， 将 来 必 坠 落 阴 间 ； 因 为 在 你 那 里 所 行 的 异 能 ， 若 行 在 所 多 玛 ， 它 还 可 以 存 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23484', '40', '11', '24', '但 我 告 诉 你 们 ， 当 审 判 的 日 子 ， 所 多 玛 所 受 的 ， 比 你 还 容 易 受 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23485', '40', '11', '25', '＜ 到 我 这 里 来 （ 路   1 0 : 2 1 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23486', '40', '11', '26', '父 啊 ， 是 的 ， 因 为 你 的 美 意 本 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23487', '40', '11', '27', '一 切 所 有 的 ， 都 是 我 父 交 付 我 的 ； 除 了 父 ， 没 有 人 知 道 子 ； 除 了 子 和 子 所 愿 意 指 示 的 ， 没 有 人 知 道 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23488', '40', '11', '28', '凡 劳 苦 担 重 担 的 人 可 以 到 我 这 里 来 ， 我 就 使 你 们 得 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23489', '40', '11', '29', '我 心 里 柔 和 谦 卑 ， 你 们 当 负 我 的 轭 ， 学 我 的 样 式 ； 这 样 ， 你 们 心 里 就 必 得 享 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23490', '40', '11', '30', '因 为 我 的 轭 是 容 易 的 ， 我 的 担 子 是 轻 省 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23491', '40', '12', '1', '＜ 安 息 日 的 问 题 （ 可   2 : 2 3 - 2 8 ； 路   6 : 1 - 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23492', '40', '12', '2', '法 利 赛 人 看 见 ， 就 对 耶 稣 说 ： “ 看 哪 ， 你 的 门 徒 做 安 息 日 不 可 做 的 事 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23493', '40', '12', '3', '耶 稣 对 他 们 说 ： “ 经 上 记 着 大 卫 和 跟 从 他 的 人 饥 饿 之 时 所 做 的 事 ， 你 们 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23494', '40', '12', '4', '他 怎 么 进 了 神 的 殿 ， 吃 了 陈 设 饼 ， 这 饼 不 是 他 和 跟 从 他 的 人 可 以 吃 得 ， 惟 独 祭 司 才 可 以 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23495', '40', '12', '5', '再 者 ， 律 法 上 所 记 的 ， 当 安 息 日 ， 祭 司 在 殿 里 犯 了 安 息 日 还 是 没 有 罪 ， 你 们 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23496', '40', '12', '6', '但 我 告 诉 你 们 ， 在 这 里 有 一 人 比 殿 更 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23497', '40', '12', '7', '‘ 我 喜 爱 怜 恤 ， 不 喜 爱 祭 祀 。 ’ 你 们 若 明 白 这 话 的 意 思 ， 就 不 将 无 罪 的 当 作 有 罪 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23498', '40', '12', '8', '因 为 人 子 是 安 息 日 的 主 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23499', '40', '12', '9', '＜ 治 好 枯 干 了 一 只 手 的 人 （ 可   3 : 1 - 6 ； 路   6 : 6 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23500', '40', '12', '10', '那 里 有 一 个 人 枯 干 了 一 只 手 。 有 人 问 耶 稣 说 ： “ 安 息 日 治 病 可 以 不 可 以 ？ ” 意 思 是 要 控 告 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23501', '40', '12', '11', '耶 稣 说 ： “ 你 们 中 间 谁 有 一 只 羊 ， 当 安 息 日 掉 在 坑 里 ， 不 把 它 抓 住 ， 拉 上 来 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23502', '40', '12', '12', '人 比 羊 何 等 贵 重 呢 ！ 所 以 ， 在 安 息 日 做 善 事 是 可 以 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23503', '40', '12', '13', '于 是 对 那 人 说 ： “ 伸 出 手 来 ！ ” 他 把 手 一 伸 ， 手 就 复 了 原 ， 和 那 只 手 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23504', '40', '12', '14', '法 利 赛 人 出 去 ， 商 议 怎 样 可 以 除 灭 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23505', '40', '12', '15', '＜ 神 所 拣 选 的 仆 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23506', '40', '12', '16', '又 嘱 咐 他 们 ， 不 要 给 他 传 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23507', '40', '12', '17', '这 是 要 应 验 先 知 以 赛 亚 的 话 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23508', '40', '12', '18', '看 哪 ！ 我 的 仆 人 ， 我 所 拣 选 、 所 亲 爱 、 心 里 所 喜 悦 的 ， 我 要 将 我 的 灵 赐 给 他 ； 他 必 将 公 理 传 给 外 邦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23509', '40', '12', '19', '他 不 争 竞 ， 不 喧 嚷 ； 街 上 也 没 有 人 听 见 他 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23510', '40', '12', '20', '压 伤 的 芦 苇 ， 他 不 折 断 ； 将 残 的 灯 火 ， 他 不 吹 灭 ； 等 他 施 行 公 理 ， 叫 公 理 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23511', '40', '12', '21', '外 邦 人 都 要 仰 望 他 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23512', '40', '12', '22', '＜ 耶 稣 和 别 西 卜 （ 可   3 : 2 0 - 3 0 ； 路   1 1 : 1 4 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23513', '40', '12', '23', '众 人 都 惊 奇 ， 说 ： “ 这 不 是 大 卫 的 子 孙 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23514', '40', '12', '24', '但 法 利 赛 人 听 见 ， 就 说 ： “ 这 个 人 赶 鬼 ， 无 非 是 靠 着 鬼 王 别 西 卜 啊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23515', '40', '12', '25', '耶 稣 知 道 他 们 的 意 念 ， 就 对 他 们 说 ： “ 凡 一 国 自 相 纷 争 ， 就 成 为 荒 场 ； 一 城 一 家 自 相 纷 争 ， 必 站 立 不 住 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23516', '40', '12', '26', '若 撒 但 赶 逐 撒 但 ， 就 是 自 相 纷 争 ， 他 的 国 怎 能 站 得 住 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23517', '40', '12', '27', '我 若 靠 着 别 西 卜 赶 鬼 ， 你 们 的 子 弟 赶 鬼 又 靠 着 谁 呢 ？ 这 样 ， 他 们 就 要 断 定 你 们 的 是 非 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23518', '40', '12', '28', '我 若 靠 着 神 的 灵 赶 鬼 ， 这 就 是 神 的 国 临 到 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23519', '40', '12', '29', '人 怎 能 进 壮 士 家 里 ， 抢 夺 他 的 家 具 呢 ？ 除 非 先 捆 住 那 壮 士 ， 才 可 以 抢 夺 他 的 家 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23520', '40', '12', '30', '不 与 我 相 合 的 ， 就 是 敌 我 的 ； 不 同 我 收 聚 的 ， 就 是 分 散 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23521', '40', '12', '31', '所 以 我 告 诉 你 们 ： “ 人 一 切 的 罪 和 亵 渎 的 话 都 可 得 赦 免 ， 惟 独 亵 渎 圣 灵 ， 总 不 得 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23522', '40', '12', '32', '凡 说 话 干 犯 人 子 的 ， 还 可 得 赦 免 ； 惟 独 说 话 干 犯 圣 灵 的 ， 今 世 来 世 总 不 得 赦 免 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23523', '40', '12', '33', '＜ 树 和 果 子 （ 路   6 : 4 3 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23524', '40', '12', '34', '毒 蛇 的 种 类 ！ 你 们 既 是 恶 人 ， 怎 能 说 出 好 话 来 呢 ？ 因 为 心 里 所 充 满 的 ， 口 里 就 说 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23525', '40', '12', '35', '善 人 从 他 心 里 所 存 的 善 就 发 出 善 来 ； 恶 人 从 他 心 里 所 存 的 恶 就 发 出 恶 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23526', '40', '12', '36', '我 又 告 诉 你 们 ， 凡 人 所 说 的 闲 话 ， 当 审 判 的 日 子 ， 必 要 句 句 供 出 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23527', '40', '12', '37', '因 为 要 凭 你 的 话 定 你 为 义 ， 也 要 凭 你 的 话 定 你 有 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23528', '40', '12', '38', '＜ 要 求 神 迹 （ 可   8 : 1 1 - 1 2 ； 路   1 1 : 2 9 - 3 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23529', '40', '12', '39', '耶 稣 回 答 说 ： “ 一 个 邪 恶 淫 乱 的 世 代 求 看 神 迹 ， 除 了 先 知 约 拿 的 神 迹 以 外 ， 再 没 有 神 迹 给 他 们 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23530', '40', '12', '40', '约 拿 三 日 三 夜 在 大 鱼 肚 腹 中 ， 人 子 也 要 这 样 三 日 三 夜 在 地 里 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23531', '40', '12', '41', '当 审 判 的 时 候 ， 尼 尼 微 人 要 起 来 定 这 世 代 的 罪 ， 因 为 尼 尼 微 人 听 了 约 拿 所 传 的 就 悔 改 了 。 看 哪 ， 在 这 里 有 一 人 比 约 拿 更 大 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23532', '40', '12', '42', '当 审 判 的 时 候 ， 南 方 的 女 王 要 起 来 定 这 世 代 的 罪 ， 因 为 她 从 地 极 而 来 ， 要 听 所 罗 门 的 智 慧 话 。 看 哪 ， 在 这 里 有 一 人 比 所 罗 门 更 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23533', '40', '12', '43', '＜ 污 鬼 回 来 （ 路   1 1 : 2 4 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23534', '40', '12', '44', '于 是 说 ： ‘ 我 要 回 到 我 所 出 来 的 屋 里 去 。 ’ 到 了 ， 就 看 见 里 面 空 闲 ， 打 扫 干 净 ， 修 饰 好 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23535', '40', '12', '45', '便 去 另 带 了 七 个 比 自 己 更 恶 的 鬼 来 ， 都 进 去 住 在 那 里 。 那 人 末 后 的 景 况 比 先 前 更 不 好 了 。 这 邪 恶 的 世 代 也 要 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23536', '40', '12', '46', '＜ 耶 稣 的 母 亲 和 兄 弟 们 （ 可   3 : 3 1 - 3 5 ； 路   8 : 1 9 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23537', '40', '12', '47', '有 人 告 诉 他 说 ： “ 看 哪 ， 你 母 亲 和 你 弟 兄 站 在 外 边 ， 要 与 你 说 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23538', '40', '12', '48', '他 却 回 答 那 人 说 ： “ 谁 是 我 的 母 亲 ？ 谁 是 我 的 弟 兄 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23539', '40', '12', '49', '就 伸 手 指 着 门 徒 ， 说 ： “ 看 哪 ， 我 的 母 亲 ， 我 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23540', '40', '12', '50', '凡 遵 行 我 天 父 旨 意 的 人 ， 就 是 我 的 弟 兄 姊 妹 和 母 亲 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23541', '40', '13', '1', '＜ 撒 种 的 比 喻 （ 可   4 : 1 - 9 ； 路   8 : 4 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23542', '40', '13', '2', '有 许 多 人 到 他 那 里 聚 集 ， 他 只 得 上 船 坐 下 ， 众 人 都 站 在 岸 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23543', '40', '13', '3', '他 用 比 喻 对 他 们 讲 许 多 道 理 ， 说 ： “ 有 一 个 撒 种 的 出 去 撒 种 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23544', '40', '13', '4', '撒 的 时 候 ， 有 落 在 路 旁 的 ， 飞 鸟 来 吃 尽 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23545', '40', '13', '5', '有 落 在 土 浅 石 头 地 上 的 ， 土 既 不 深 ， 发 苗 最 快 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23546', '40', '13', '6', '日 头 出 来 一 晒 ， 因 为 没 有 根 ， 就 枯 干 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23547', '40', '13', '7', '有 落 在 荆 棘 里 的 ， 荆 棘 长 起 来 ， 把 它 挤 住 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23548', '40', '13', '8', '又 有 落 在 好 土 里 的 ， 就 结 实 ， 有 一 百 倍 的 ， 有 六 十 倍 的 ， 有 三 十 倍 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23549', '40', '13', '9', '有 耳 可 听 的 ， 就 应 当 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23550', '40', '13', '10', '＜ 用 比 喻 的 目 的 （ 可   4 : 1 0 - 1 2 ； 路   8 : 9 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23551', '40', '13', '11', '耶 稣 回 答 说 ： “ 因 为 天 国 的 奥 秘 只 叫 你 们 知 道 ， 不 叫 他 们 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23552', '40', '13', '12', '凡 有 的 ， 还 要 加 给 他 ， 叫 他 有 余 ； 凡 没 有 的 ， 连 他 所 有 的 ， 也 要 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23553', '40', '13', '13', '所 以 我 用 比 喻 对 他 们 讲 ， 是 因 他 们 看 也 看 不 见 ， 听 也 听 不 见 ， 也 不 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23554', '40', '13', '14', '在 他 们 身 上 ， 正 应 了 以 赛 亚 的 预 言 ， 说 ： 你 们 听 是 要 听 见 ， 却 不 明 白 ； 看 是 要 看 见 ， 却 不 晓 得 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23555', '40', '13', '15', '因 为 这 百 姓 油 蒙 了 心 ， 耳 朵 发 沉 ， 眼 睛 闭 着 ， 恐 怕 眼 睛 看 见 ， 耳 朵 听 见 ， 心 里 明 白 ， 回 转 过 来 ， 我 就 医 治 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23556', '40', '13', '16', '“ 但 你 们 的 眼 睛 是 有 福 的 ， 因 为 看 见 了 ； 你 们 的 耳 朵 也 是 有 福 的 ， 因 为 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23557', '40', '13', '17', '我 实 在 告 诉 你 们 ， 从 前 有 许 多 先 知 和 义 人 要 看 你 们 所 看 的 ， 却 没 有 看 见 ， 要 听 你 们 所 听 的 ， 却 没 有 听 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23558', '40', '13', '18', '＜ 解 明 撒 种 的 比 喻 （ 可   4 : 1 3 - 2 0 ； 路   8 : 1 1 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23559', '40', '13', '19', '凡 听 见 天 国 道 理 不 明 白 的 ， 那 恶 者 就 来 ， 把 所 撒 在 他 心 里 的 夺 了 去 ； 这 就 是 撒 在 路 旁 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23560', '40', '13', '20', '撒 在 石 头 地 上 的 ， 就 是 人 听 了 道 ， 当 下 欢 喜 领 受 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23561', '40', '13', '21', '只 因 心 里 没 有 根 ， 不 过 是 暂 时 的 ， 及 至 为 道 遭 了 患 难 ， 或 是 受 了 逼 迫 ， 立 刻 就 跌 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23562', '40', '13', '22', '撒 在 荆 棘 里 的 ， 就 是 人 听 了 道 ， 后 来 有 世 上 的 思 虑 、 钱 财 的 迷 惑 把 道 挤 住 了 ， 不 能 结 实 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23563', '40', '13', '23', '撒 在 好 地 上 的 ， 就 是 人 听 道 明 白 了 ， 后 来 结 实 ， 有 一 百 倍 的 ， 有 六 十 倍 的 ， 有 三 十 倍 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23564', '40', '13', '24', '＜ 稗 子 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23565', '40', '13', '25', '及 至 人 睡 觉 的 时 候 ， 有 仇 敌 来 ， 将 稗 子 撒 在 麦 子 里 就 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23566', '40', '13', '26', '到 长 苗 吐 穗 的 时 候 ， 稗 子 也 显 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23567', '40', '13', '27', '田 主 的 仆 人 来 告 诉 他 说 ： ‘ 主 啊 ， 你 不 是 撒 好 种 在 田 里 吗 ？ 从 哪 里 来 的 稗 子 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23568', '40', '13', '28', '主 人 说 ： ‘ 这 是 仇 敌 做 的 。 ’ 仆 人 说 ： ‘ 你 要 我 们 去 薅 出 来 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23569', '40', '13', '29', '主 人 说 ： ‘ 不 必 ， 恐 怕 薅 稗 子 ， 连 麦 子 也 拔 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23570', '40', '13', '30', '容 这 两 样 一 齐 长 ， 等 着 收 割 。 当 收 割 的 时 候 ， 我 要 对 收 割 的 人 说 ， 先 将 稗 子 薅 出 来 ， 捆 成 捆 ， 留 着 烧 ； 惟 有 麦 子 要 收 在 仓 里 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23571', '40', '13', '31', '＜ 芥 菜 种 和 面 酵 的 比 喻 （ 可   4 : 3 0 - 3 2 ； 路   1 3 : 1 8 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23572', '40', '13', '32', '这 原 是 百 种 里 最 小 的 ， 等 到 长 起 来 ， 却 比 各 样 的 菜 都 大 ， 且 成 了 树 ， 天 上 的 飞 鸟 来 宿 在 它 的 枝 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23573', '40', '13', '33', '他 又 对 他 们 讲 个 比 喻 说 ： “ 天 国 好 像 面 酵 ， 有 妇 人 拿 来 ， 藏 在 三 斗 面 里 ， 直 等 全 团 都 发 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23574', '40', '13', '34', '＜ 用 比 喻 的 原 因 （ 可   4 : 3 3 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23575', '40', '13', '35', '这 是 要 应 验 先 知 的 话 ， 说 ： 我 要 开 口 用 比 喻 ， 把 创 世 以 来 所 隐 藏 的 事 发 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23576', '40', '13', '36', '＜ 解 明 稗 子 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23577', '40', '13', '37', '他 回 答 说 ： “ 那 撒 好 种 的 就 是 人 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23578', '40', '13', '38', '田 地 就 是 世 界 ； 好 种 就 是 天 国 之 子 ； 稗 子 就 是 那 恶 者 之 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23579', '40', '13', '39', '撒 稗 子 的 仇 敌 就 是 魔 鬼 ； 收 割 的 时 候 就 是 世 界 的 末 了 ； 收 割 的 人 就 是 天 使 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23580', '40', '13', '40', '将 稗 子 薅 出 来 用 火 焚 烧 ， 世 界 的 末 了 也 要 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23581', '40', '13', '41', '人 子 要 差 遣 使 者 ， 把 一 切 叫 人 跌 倒 的 和 作 恶 的 ， 从 他 国 里 挑 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23582', '40', '13', '42', '丢 在 火 炉 里 ； 在 那 里 必 要 哀 哭 切 齿 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23583', '40', '13', '43', '那 时 ， 义 人 在 他 们 父 的 国 里 ， 要 发 出 光 来 ， 像 太 阳 一 样 。 有 耳 可 听 的 ， 就 应 当 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23584', '40', '13', '44', '＜ 藏 宝 、 寻 珠 、 撒 网 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23585', '40', '13', '45', '天 国 又 好 像 买 卖 人 寻 找 好 珠 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23586', '40', '13', '46', '遇 见 一 颗 重 价 的 珠 子 ， 就 去 变 卖 他 一 切 所 有 的 ， 买 了 这 颗 珠 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23587', '40', '13', '47', '天 国 又 好 像 网 撒 在 海 里 ， 聚 拢 各 样 水 族 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23588', '40', '13', '48', '网 既 满 了 ， 人 就 拉 上 岸 来 ， 坐 下 ， 拣 好 的 收 在 器 具 里 ， 将 不 好 的 丢 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23589', '40', '13', '49', '世 界 的 末 了 也 要 这 样 。 天 使 要 出 来 ， 从 义 人 中 把 恶 人 分 别 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23590', '40', '13', '50', '丢 在 火 炉 里 ； 在 那 里 必 要 哀 哭 切 齿 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23591', '40', '13', '51', '＜ 新 旧 的 东 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23592', '40', '13', '52', '他 说 ： “ 凡 文 士 受 教 作 天 国 的 门 徒 ， 就 像 一 个 家 主 从 他 库 里 拿 出 新 旧 的 东 西 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23593', '40', '13', '53', '＜ 拿 撒 勒 人 厌 弃 耶 稣 （ 可   6 : 1 - 6 ； 路   4 : 1 6 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23594', '40', '13', '54', '来 到 自 己 的 家 乡 ， 在 会 堂 里 教 训 人 ， 甚 至 他 们 都 希 奇 ， 说 ： “ 这 人 从 哪 里 有 这 等 智 慧 和 异 能 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23595', '40', '13', '55', '这 不 是 木 匠 的 儿 子 吗 ？ 他 母 亲 不 是 叫 马 利 亚 吗 ？ 他 弟 兄 们 不 是 叫 雅 各 、 约 西 ｛ 有 古 卷 ： 约 瑟 ｝ 、 西 门 、 犹 大 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23596', '40', '13', '56', '他 妹 妹 们 不 是 都 在 我 们 这 里 吗 ？ 这 人 从 哪 里 有 这 一 切 的 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23597', '40', '13', '57', '他 们 就 厌 弃 他 ｛ 厌 弃 他 ： 原 文 是 因 他 跌 倒 ｝ 。 耶 稣 对 他 们 说 ： “ 大 凡 先 知 ， 除 了 本 地 本 家 之 外 ， 没 有 不 被 人 尊 敬 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23598', '40', '13', '58', '耶 稣 因 为 他 们 不 信 ， 就 在 那 里 不 多 行 异 能 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23599', '40', '14', '1', '＜ 施 洗 约 翰 的 死 （ 可   6 : 1 4 - 2 9 ； 路   9 : 7 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23600', '40', '14', '2', '就 对 臣 仆 说 ： “ 这 是 施 洗 的 约 翰 从 死 里 复 活 ， 所 以 这 些 异 能 从 他 里 面 发 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23601', '40', '14', '3', '起 先 ， 希 律 为 他 兄 弟 腓 力 的 妻 子 希 罗 底 的 缘 故 ， 把 约 翰 拿 住 ， 锁 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23602', '40', '14', '4', '因 为 约 翰 曾 对 他 说 ： “ 你 娶 这 妇 人 是 不 合 理 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23603', '40', '14', '5', '希 律 就 想 要 杀 他 ， 只 是 怕 百 姓 ， 因 为 他 们 以 约 翰 为 先 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23604', '40', '14', '6', '到 了 希 律 的 生 日 ， 希 罗 底 的 女 儿 在 众 人 面 前 跳 舞 ， 使 希 律 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23605', '40', '14', '7', '希 律 就 起 誓 ， 应 许 随 她 所 求 的 给 她 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23606', '40', '14', '8', '女 儿 被 母 亲 所 使 ， 就 说 ： “ 请 把 施 洗 约 翰 的 头 放 在 盘 子 里 ， 拿 来 给 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23607', '40', '14', '9', '王 便 忧 愁 ， 但 因 他 所 起 的 誓 ， 又 因 同 席 的 人 ， 就 吩 咐 给 她 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23608', '40', '14', '10', '于 是 打 发 人 去 ， 在 监 里 斩 了 约 翰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23609', '40', '14', '11', '把 头 放 在 盘 子 里 ， 拿 来 给 了 女 子 ； 女 子 拿 去 给 她 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23610', '40', '14', '12', '约 翰 的 门 徒 来 ， 把 尸 首 领 去 埋 葬 了 ， 就 去 告 诉 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23611', '40', '14', '13', '＜ 耶 稣 给 五 千 人 吃 饱 （ 可   6 : 3 0 - 4 4 ； 路   9 : 1 0 - 1 7 ； 约   6 : 1 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23612', '40', '14', '14', '耶 稣 出 来 ， 见 有 许 多 的 人 ， 就 怜 悯 他 们 ， 治 好 了 他 们 的 病 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23613', '40', '14', '15', '天 将 晚 的 时 候 ， 门 徒 进 前 来 ， 说 ： “ 这 是 野 地 ， 时 候 已 经 过 了 ， 请 叫 众 人 散 开 ， 他 们 好 往 村 子 里 去 ， 自 己 买 吃 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23614', '40', '14', '16', '耶 稣 说 ： “ 不 用 他 们 去 ， 你 们 给 他 们 吃 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23615', '40', '14', '17', '门 徒 说 ： “ 我 们 这 里 只 有 五 个 饼 ， 两 条 鱼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23616', '40', '14', '18', '耶 稣 说 ： “ 拿 过 来 给 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23617', '40', '14', '19', '于 是 吩 咐 众 人 坐 在 草 地 上 ， 就 拿 着 这 五 个 饼 ， 两 条 鱼 ， 望 着 天 祝 福 ， 擘 开 饼 ， 递 给 门 徒 ， 门 徒 又 递 给 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23618', '40', '14', '20', '他 们 都 吃 ， 并 且 吃 饱 了 ； 把 剩 下 的 零 碎 收 拾 起 来 ， 装 满 了 十 二 个 篮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23619', '40', '14', '21', '吃 的 人 ， 除 了 妇 女 孩 子 ， 约 有 五 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23620', '40', '14', '22', '＜ 耶 稣 在 海 面 上 行 走 （ 可   6 : 4 5 - 5 2 ； 约   6 : 1 5 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23621', '40', '14', '23', '散 了 众 人 以 后 ， 他 就 独 自 上 山 去 祷 告 。 到 了 晚 上 ， 只 有 他 一 人 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23622', '40', '14', '24', '那 时 船 在 海 中 ， 因 风 不 顺 ， 被 浪 摇 撼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23623', '40', '14', '25', '夜 里 四 更 天 ， 耶 稣 在 海 面 上 走 ， 往 门 徒 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23624', '40', '14', '26', '门 徒 看 见 他 在 海 面 上 走 ， 就 惊 慌 了 ， 说 ： “ 是 个 鬼 怪 ！ ” 便 害 怕 ， 喊 叫 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23625', '40', '14', '27', '耶 稣 连 忙 对 他 们 说 ： “ 你 们 放 心 ， 是 我 ， 不 要 怕 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23626', '40', '14', '28', '彼 得 说 ： “ 主 ， 如 果 是 你 ， 请 叫 我 从 水 面 上 走 到 你 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23627', '40', '14', '29', '耶 稣 说 ： “ 你 来 吧 。 ” 彼 得 就 从 船 上 下 去 ， 在 水 面 上 走 ， 要 到 耶 稣 那 里 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23628', '40', '14', '30', '只 因 见 风 甚 大 ， 就 害 怕 ， 将 要 沉 下 去 ， 便 喊 着 说 ： “ 主 啊 ， 救 我 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23629', '40', '14', '31', '耶 稣 赶 紧 伸 手 拉 住 他 ， 说 ： “ 你 这 小 信 的 人 哪 ， 为 什 么 疑 惑 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23630', '40', '14', '32', '他 们 上 了 船 ， 风 就 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23631', '40', '14', '33', '在 船 上 的 人 都 拜 他 ， 说 ： “ 你 真 是 神 的 儿 子 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23632', '40', '14', '34', '＜ 治 好 革 尼 撒 勒 的 病 人 （ 可   6 : 5 3 - 5 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23633', '40', '14', '35', '那 里 的 人 一 认 出 是 耶 稣 ， 就 打 发 人 到 周 围 地 方 去 ， 把 所 有 的 病 人 带 到 他 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23634', '40', '14', '36', '只 求 耶 稣 准 他 们 摸 他 的 衣 裳 繸 子 ； 摸 着 的 人 就 都 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23635', '40', '15', '1', '＜ 古 人 的 传 统 （ 可   7 : 1 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23636', '40', '15', '2', '“ 你 的 门 徒 为 什 么 犯 古 人 的 遗 传 呢 ？ 因 为 吃 饭 的 时 候 ， 他 们 不 洗 手 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23637', '40', '15', '3', '耶 稣 回 答 说 ： “ 你 们 为 什 么 因 着 你 们 的 遗 传 犯 神 的 诫 命 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23638', '40', '15', '4', '神 说 ： ‘ 当 孝 敬 父 母 ’ ； 又 说 ： ‘ 咒 骂 父 母 的 ， 必 治 死 他 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23639', '40', '15', '5', '你 们 倒 说 ： ‘ 无 论 何 人 对 父 母 说 ： 我 所 当 奉 给 你 的 已 经 作 了 供 献 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23640', '40', '15', '6', '他 就 可 以 不 孝 敬 父 母 。 ’ 这 就 是 你 们 藉 着 遗 传 ， 废 了 神 的 诫 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23641', '40', '15', '7', '假 冒 为 善 的 人 哪 ， 以 赛 亚 指 着 你 们 说 的 预 言 是 不 错 的 。 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23642', '40', '15', '8', '这 百 姓 用 嘴 唇 尊 敬 我 ， 心 却 远 离 我 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23643', '40', '15', '9', '他 们 将 人 的 吩 咐 当 作 道 理 教 导 人 ， 所 以 拜 我 也 是 枉 然 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23644', '40', '15', '10', '耶 稣 就 叫 了 众 人 来 ， 对 他 们 说 ： “ 你 们 要 听 ， 也 要 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23645', '40', '15', '11', '入 口 的 不 能 污 秽 人 ， 出 口 的 乃 能 污 秽 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23646', '40', '15', '12', '当 时 ， 门 徒 进 前 来 对 他 说 ： “ 法 利 赛 人 听 见 这 话 ， 不 服 ｛ 原 文 是 跌 倒 ｝ ， 你 知 道 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23647', '40', '15', '13', '耶 稣 回 答 说 ： “ 凡 栽 种 的 物 ， 若 不 是 我 天 父 栽 种 的 ， 必 要 拔 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23648', '40', '15', '14', '任 凭 他 们 吧 ！ 他 们 是 瞎 眼 领 路 的 ； 若 是 瞎 子 领 瞎 子 ， 两 个 人 都 要 掉 在 坑 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23649', '40', '15', '15', '彼 得 对 耶 稣 说 ： “ 请 将 这 比 喻 讲 给 我 们 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23650', '40', '15', '16', '耶 稣 说 ： “ 你 们 到 如 今 还 不 明 白 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23651', '40', '15', '17', '岂 不 知 凡 入 口 的 ， 是 运 到 肚 子 里 ， 又 落 在 茅 厕 里 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23652', '40', '15', '18', '惟 独 出 口 的 ， 是 从 心 里 发 出 来 的 ， 这 才 污 秽 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23653', '40', '15', '19', '因 为 从 心 里 发 出 来 的 ， 有 恶 念 、 凶 杀 、 奸 淫 、 苟 合 、 偷 盗 、 妄 证 、 谤 讟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23654', '40', '15', '20', '这 都 是 污 秽 人 的 ； 至 于 不 洗 手 吃 饭 ， 那 却 不 污 秽 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23655', '40', '15', '21', '＜ 迦 南 妇 人 的 信 心 （ 可   7 : 2 4 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23656', '40', '15', '22', '有 一 个 迦 南 妇 人 ， 从 那 地 方 出 来 ， 喊 着 说 ： “ 主 啊 ， 大 卫 的 子 孙 ， 可 怜 我 ！ 我 女 儿 被 鬼 附 得 甚 苦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23657', '40', '15', '23', '耶 稣 却 一 言 不 答 。 门 徒 进 前 来 ， 求 他 说 ： “ 这 妇 人 在 我 们 后 头 喊 叫 ， 请 打 发 她 走 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23658', '40', '15', '24', '耶 稣 说 ： “ 我 奉 差 遣 不 过 是 到 以 色 列 家 迷 失 的 羊 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23659', '40', '15', '25', '那 妇 人 来 拜 他 ， 说 ： “ 主 啊 ， 帮 助 我 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23660', '40', '15', '26', '他 回 答 说 ： “ 不 好 拿 儿 女 的 饼 丢 给 狗 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23661', '40', '15', '27', '妇 人 说 ： “ 主 啊 ， 不 错 ； 但 是 狗 也 吃 它 主 人 桌 子 上 掉 下 来 的 碎 渣 儿 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23662', '40', '15', '28', '耶 稣 说 ： “ 妇 人 ， 你 的 信 心 是 大 的 ！ 照 你 所 要 的 ， 给 你 成 全 了 吧 。 ” 从 那 时 候 ， 她 女 儿 就 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23663', '40', '15', '29', '＜ 治 好 许 多 病 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23664', '40', '15', '30', '有 许 多 人 到 他 那 里 ， 带 着 瘸 子 、 瞎 子 、 哑 巴 、 有 残 疾 的 ， 和 好 些 别 的 病 人 ， 都 放 在 他 脚 前 ； 他 就 治 好 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23665', '40', '15', '31', '甚 至 众 人 都 希 奇 ； 因 为 看 见 哑 巴 说 话 ， 残 疾 的 痊 愈 ， 瘸 子 行 走 ， 瞎 子 看 见 ， 他 们 就 归 荣 耀 给 以 色 列 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23666', '40', '15', '32', '＜ 耶 稣 给 四 千 人 吃 饱 （ 可   8 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23667', '40', '15', '33', '门 徒 说 ： “ 我 们 在 这 野 地 ， 哪 里 有 这 么 多 的 饼 叫 这 许 多 人 吃 饱 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23668', '40', '15', '34', '耶 稣 说 ： “ 你 们 有 多 少 饼 ？ ” 他 们 说 ： “ 有 七 个 ， 还 有 几 条 小 鱼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23669', '40', '15', '35', '他 就 吩 咐 众 人 坐 在 地 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23670', '40', '15', '36', '拿 着 这 七 个 饼 和 几 条 鱼 ， 祝 谢 了 ， 擘 开 ， 递 给 门 徒 ； 门 徒 又 递 给 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23671', '40', '15', '37', '众 人 都 吃 ， 并 且 吃 饱 了 ， 收 拾 剩 下 的 零 碎 ， 装 满 了 七 个 筐 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23672', '40', '15', '38', '吃 的 人 ， 除 了 妇 女 孩 子 ， 共 有 四 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23673', '40', '15', '39', '耶 稣 叫 众 人 散 去 ， 就 上 船 ， 来 到 马 加 丹 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23674', '40', '16', '1', '＜ 求 主 显 个 神 迹 （ 可   8 : 1 1 - 1 3 ； 路   1 2 : 5 4 - 5 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23675', '40', '16', '2', '耶 稣 回 答 说 ： “ 晚 上 天 发 红 ， 你 们 就 说 ： ‘ 天 必 要 晴 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23676', '40', '16', '3', '早 晨 天 发 红 ， 又 发 黑 ， 你 们 就 说 ： ‘ 今 日 必 有 风 雨 。 ’ 你 们 知 道 分 辨 天 上 的 气 色 ， 倒 不 能 分 辨 这 时 候 的 神 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23677', '40', '16', '4', '一 个 邪 恶 淫 乱 的 世 代 求 神 迹 ， 除 了 约 拿 的 神 迹 以 外 ， 再 没 有 神 迹 给 他 看 。 ” 耶 稣 就 离 开 他 们 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23678', '40', '16', '5', '＜ 防 备 法 利 赛 人 和 撒 都 该 人 的 酵 （ 可   8 : 1 4 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23679', '40', '16', '6', '耶 稣 对 他 们 说 ： “ 你 们 要 谨 慎 ， 防 备 法 利 赛 人 和 撒 都 该 人 的 酵 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23680', '40', '16', '7', '门 徒 彼 此 议 论 说 ： “ 这 是 因 为 我 们 没 有 带 饼 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23681', '40', '16', '8', '耶 稣 看 出 来 ， 就 说 ： “ 你 们 这 小 信 的 人 ， 为 什 么 因 为 没 有 饼 彼 此 议 论 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23682', '40', '16', '9', '你 们 还 不 明 白 吗 ？ 不 记 得 那 五 个 饼 分 给 五 千 人 、 又 收 拾 了 多 少 篮 子 的 零 碎 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23683', '40', '16', '10', '也 不 记 得 那 七 个 饼 分 给 四 千 人 、 又 收 拾 了 多 少 筐 子 的 零 碎 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23684', '40', '16', '11', '我 对 你 们 说 ： ‘ 要 防 备 法 利 赛 人 和 撒 都 该 人 的 酵 ’ ， 这 话 不 是 指 着 饼 说 的 ， 你 们 怎 么 不 明 白 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23685', '40', '16', '12', '门 徒 这 才 晓 得 他 说 的 不 是 叫 他 们 防 备 饼 的 酵 ， 乃 是 防 备 法 利 赛 人 和 撒 都 该 人 的 教 训 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23686', '40', '16', '13', '＜ 彼 得 认 耶 稣 为 基 督 （ 可   8 : 2 7 - 3 0 ； 路   9 : 1 8 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23687', '40', '16', '14', '他 们 说 ： “ 有 人 说 是 施 洗 的 约 翰 ； 有 人 说 是 以 利 亚 ； 又 有 人 说 是 耶 利 米 或 是 先 知 里 的 一 位 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23688', '40', '16', '15', '耶 稣 说 ： “ 你 们 说 我 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23689', '40', '16', '16', '西 门 ． 彼 得 回 答 说 ： “ 你 是 基 督 ， 是 永 生 神 的 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23690', '40', '16', '17', '耶 稣 对 他 说 ： “ 西 门 ． 巴 ． 约 拿 ， 你 是 有 福 的 ！ 因 为 这 不 是 属 血 肉 的 指 示 你 的 ， 乃 是 我 在 天 上 的 父 指 示 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23691', '40', '16', '18', '我 还 告 诉 你 ， 你 是 彼 得 ， 我 要 把 我 的 教 会 建 造 在 这 磐 石 上 ； 阴 间 的 权 柄 ｛ 权 柄 ： 原 文 是 门 ｝ ， 不 能 胜 过 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23692', '40', '16', '19', '我 要 把 天 国 的 钥 匙 给 你 ， 凡 你 在 地 上 所 捆 绑 的 ， 在 天 上 也 要 捆 绑 ； 凡 你 在 地 上 所 释 放 的 ， 在 天 上 也 要 释 放 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23693', '40', '16', '20', '当 下 ， 耶 稣 嘱 咐 门 徒 ， 不 可 对 人 说 他 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23694', '40', '16', '21', '＜ 耶 稣 预 言 受 难 和 复 活 （ 可   8 : 3 1 - 9 : 1 ； 路   9 : 2 2 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23695', '40', '16', '22', '彼 得 就 拉 着 他 ， 劝 他 说 ： “ 主 啊 ， 万 不 可 如 此 ！ 这 事 必 不 临 到 你 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23696', '40', '16', '23', '耶 稣 转 过 来 ， 对 彼 得 说 ： “ 撒 但 ， 退 我 后 边 去 吧 ！ 你 是 绊 我 脚 的 ； 因 为 你 不 体 贴 神 的 意 思 ， 只 体 贴 人 的 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23697', '40', '16', '24', '于 是 耶 稣 对 门 徒 说 ： “ 若 有 人 要 跟 从 我 ， 就 当 舍 己 ， 背 起 他 的 十 字 架 来 跟 从 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23698', '40', '16', '25', '因 为 ， 凡 要 救 自 己 生 命 ｛ 生 命 ： 或 译 灵 魂 ； 下 同 ｝ 的 ， 必 丧 掉 生 命 ； 凡 为 我 丧 掉 生 命 的 ， 必 得 着 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23699', '40', '16', '26', '人 若 赚 得 全 世 界 ， 赔 上 自 己 的 生 命 ， 有 什 么 益 处 呢 ？ 人 还 能 拿 什 么 换 生 命 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23700', '40', '16', '27', '人 子 要 在 他 父 的 荣 耀 里 ， 同 着 众 使 者 降 临 ； 那 时 候 ， 他 要 照 各 人 的 行 为 报 应 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23701', '40', '16', '28', '我 实 在 告 诉 你 们 ， 站 在 这 里 的 ， 有 人 在 没 尝 死 味 以 前 必 看 见 人 子 降 临 在 他 的 国 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23702', '40', '17', '1', '＜ 耶 稣 改 变 形 像 （ 可   9 : 2 - 1 3 ； 路   9 : 2 8 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23703', '40', '17', '2', '就 在 他 们 面 前 变 了 形 像 ， 脸 面 明 亮 如 日 头 ， 衣 裳 洁 白 如 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23704', '40', '17', '3', '忽 然 ， 有 摩 西 、 以 利 亚 向 他 们 显 现 ， 同 耶 稣 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23705', '40', '17', '4', '彼 得 对 耶 稣 说 ： “ 主 啊 ， 我 们 在 这 里 真 好 ！ 你 若 愿 意 ， 我 就 在 这 里 搭 三 座 棚 ， 一 座 为 你 ， 一 座 为 摩 西 ， 一 座 为 以 利 亚 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23706', '40', '17', '5', '说 话 之 间 ， 忽 然 有 一 朵 光 明 的 云 彩 遮 盖 他 们 ， 且 有 声 音 从 云 彩 里 出 来 ， 说 ： “ 这 是 我 的 爱 子 ， 我 所 喜 悦 的 。 你 们 要 听 他 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23707', '40', '17', '6', '门 徒 听 见 ， 就 俯 伏 在 地 ， 极 其 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23708', '40', '17', '7', '耶 稣 进 前 来 ， 摸 他 们 ， 说 ： “ 起 来 ， 不 要 害 怕 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23709', '40', '17', '8', '他 们 举 目 不 见 一 人 ， 只 见 耶 稣 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23710', '40', '17', '9', '下 山 的 时 候 ， 耶 稣 吩 咐 他 们 说 ： “ 人 子 还 没 有 从 死 里 复 活 ， 你 们 不 要 将 所 看 见 的 告 诉 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23711', '40', '17', '10', '门 徒 问 耶 稣 说 ： “ 文 士 为 什 么 说 以 利 亚 必 须 先 来 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23712', '40', '17', '11', '耶 稣 回 答 说 ： “ 以 利 亚 固 然 先 来 ， 并 要 复 兴 万 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23713', '40', '17', '12', '只 是 我 告 诉 你 们 ， 以 利 亚 已 经 来 了 ， 人 却 不 认 识 他 ， 竟 任 意 待 他 。 人 子 也 将 要 这 样 受 他 们 的 害 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23714', '40', '17', '13', '门 徒 这 才 明 白 耶 稣 所 说 的 是 指 着 施 洗 的 约 翰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23715', '40', '17', '14', '＜ 治 好 被 鬼 附 身 的 孩 子 （ 可   9 : 1 4 - 2 9 ； 路   9 : 3 7 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23716', '40', '17', '15', '说 ： “ 主 啊 ， 怜 悯 我 的 儿 子 ！ 他 害 癫 痫 的 病 很 苦 ， 屡 次 跌 在 火 里 ， 屡 次 跌 在 水 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23717', '40', '17', '16', '我 带 他 到 你 门 徒 那 里 ， 他 们 却 不 能 医 治 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23718', '40', '17', '17', '耶 稣 说 ： “ 嗳 ！ 这 又 不 信 又 悖 谬 的 世 代 啊 ， 我 在 你 们 这 里 要 到 几 时 呢 ？ 我 忍 耐 你 们 要 到 几 时 呢 ？ 把 他 带 到 我 这 里 来 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23719', '40', '17', '18', '耶 稣 斥 责 那 鬼 ， 鬼 就 出 来 ； 从 此 孩 子 就 痊 愈 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23720', '40', '17', '19', '门 徒 暗 暗 地 到 耶 稣 跟 前 ， 说 ： “ 我 们 为 什 么 不 能 赶 出 那 鬼 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23721', '40', '17', '20', '耶 稣 说 ： “ 是 因 你 们 的 信 心 小 。 我 实 在 告 诉 你 们 ， 你 们 若 有 信 心 ， 像 一 粒 芥 菜 种 ， 就 是 对 这 座 山 说 ： ‘ 你 从 这 边 挪 到 那 边 ’ ， 它 也 必 挪 去 ； 并 且 你 们 没 有 一 件 不 能 做 的 事 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23722', '40', '17', '21', '至 于 这 一 类 的 鬼 ， 若 不 祷 告 、 禁 食 ， 他 就 不 出 来 ｛ 或 译 ： 不 能 赶 他 出 来 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23723', '40', '17', '22', '＜ 耶 稣 第 二 次 预 言 受 难 和 复 活 （ 可   9 : 3 0 - 3 2 ； 路   9 : 4 3 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23724', '40', '17', '23', '他 们 要 杀 害 他 ， 第 三 日 他 要 复 活 。 ” 门 徒 就 大 大 地 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23725', '40', '17', '24', '＜ 缴 纳 殿 税 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23726', '40', '17', '25', '彼 得 说 ： “ 纳 。 ” 他 进 了 屋 子 ， 耶 稣 先 向 他 说 ： “ 西 门 ， 你 的 意 思 如 何 ？ 世 上 的 君 王 向 谁 征 收 关 税 、 丁 税 ？ 是 向 自 己 的 儿 子 呢 ？ 是 向 外 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23727', '40', '17', '26', '彼 得 说 ： “ 是 向 外 人 。 ” 耶 稣 说 ： “ 既 然 如 此 ， 儿 子 就 可 以 免 税 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23728', '40', '17', '27', '但 恐 怕 触 犯 ｛ 触 犯 ： 原 文 是 绊 倒 ｝ 他 们 ， 你 且 往 海 边 去 钓 鱼 ， 把 先 钓 上 来 的 鱼 拿 起 来 ， 开 了 它 的 口 ， 必 得 一 块 钱 ， 可 以 拿 去 给 他 们 ， 作 你 我 的 税 银 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23729', '40', '18', '1', '＜ 天 国 里 最 伟 大 的 人 （ 可   9 : 3 3 - 3 7 ； 路   9 : 4 6 - 4 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23730', '40', '18', '2', '耶 稣 便 叫 一 个 小 孩 子 来 ， 使 他 站 在 他 们 当 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23731', '40', '18', '3', '说 ： “ 我 实 在 告 诉 你 们 ， 你 们 若 不 回 转 ， 变 成 小 孩 子 的 样 式 ， 断 不 得 进 天 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23732', '40', '18', '4', '所 以 ， 凡 自 己 谦 卑 像 这 小 孩 子 的 ， 他 在 天 国 里 就 是 最 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23733', '40', '18', '5', '凡 为 我 的 名 接 待 一 个 像 这 小 孩 子 的 ， 就 是 接 待 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23734', '40', '18', '6', '＜ 罪 的 诱 惑 （ 可   9 : 4 2 - 4 8 ； 路   1 7 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23735', '40', '18', '7', '这 世 界 有 祸 了 ， 因 为 将 人 绊 倒 ； 绊 倒 人 的 事 是 免 不 了 的 ， 但 那 绊 倒 人 的 有 祸 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23736', '40', '18', '8', '倘 若 你 一 只 手 ， 或 是 一 只 脚 ， 叫 你 跌 倒 ， 就 砍 下 来 丢 掉 。 你 缺 一 只 手 ， 或 是 一 只 脚 ， 进 入 永 生 ， 强 如 有 两 手 两 脚 被 丢 在 永 火 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23737', '40', '18', '9', '倘 若 你 一 只 眼 叫 你 跌 倒 ， 就 把 它 剜 出 来 丢 掉 。 你 只 有 一 只 眼 进 入 永 生 ， 强 如 有 两 只 眼 被 丢 在 地 狱 的 火 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23738', '40', '18', '10', '＜ 迷 羊 的 比 喻 （ 路   1 5 : 3 - 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23739', '40', '18', '11', '｛ 有 古 卷 加 ： 人 子 来 ， 为 要 拯 救 失 丧 的 人 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23740', '40', '18', '12', '一 个 人 若 有 一 百 只 羊 ， 一 只 走 迷 了 路 ， 你 们 的 意 思 如 何 ？ 他 岂 不 撇 下 这 九 十 九 只 ， 往 山 里 去 找 那 只 迷 路 的 羊 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23741', '40', '18', '13', '若 是 找 着 了 ， 我 实 在 告 诉 你 们 ， 他 为 这 一 只 羊 欢 喜 ， 比 为 那 没 有 迷 路 的 九 十 九 只 欢 喜 还 大 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23742', '40', '18', '14', '你 们 在 天 上 的 父 也 是 这 样 ， 不 愿 意 这 小 子 里 失 丧 一 个 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23743', '40', '18', '15', '＜ 如 何 对 待 犯 过 错 的 弟 兄 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23744', '40', '18', '16', '他 若 不 听 ， 你 就 另 外 带 一 两 个 人 同 去 ， 要 凭 两 三 个 人 的 口 作 见 证 ， 句 句 都 可 定 准 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23745', '40', '18', '17', '若 是 不 听 他 们 ， 就 告 诉 教 会 ； 若 是 不 听 教 会 ， 就 看 他 像 外 邦 人 和 税 吏 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23746', '40', '18', '18', '“ 我 实 在 告 诉 你 们 ， 凡 你 们 在 地 上 所 捆 绑 的 ， 在 天 上 也 要 捆 绑 ； 凡 你 们 在 地 上 所 释 放 的 ， 在 天 上 也 要 释 放 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23747', '40', '18', '19', '我 又 告 诉 你 们 ， 若 是 你 们 中 间 有 两 个 人 在 地 上 同 心 合 意 地 求 什 么 事 ， 我 在 天 上 的 父 必 为 他 们 成 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23748', '40', '18', '20', '因 为 无 论 在 哪 里 ， 有 两 三 个 人 奉 我 的 名 聚 会 ， 那 里 就 有 我 在 他 们 中 间 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23749', '40', '18', '21', '＜ 不 饶 恕 人 的 恶 仆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23750', '40', '18', '22', '耶 稣 说 ： “ 我 对 你 说 ， 不 是 到 七 次 ， 乃 是 到 七 十 个 七 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23751', '40', '18', '23', '天 国 好 像 一 个 王 要 和 他 仆 人 算 帐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23752', '40', '18', '24', '才 算 的 时 候 ， 有 人 带 了 一 个 欠 一 千 万 银 子 的 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23753', '40', '18', '25', '因 为 他 没 有 什 么 偿 还 之 物 ， 主 人 吩 咐 把 他 和 他 妻 子 儿 女 ， 并 一 切 所 有 的 都 卖 了 偿 还 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23754', '40', '18', '26', '那 仆 人 就 俯 伏 拜 他 ， 说 ： ‘ 主 啊 ， 宽 容 我 ， 将 来 我 都 要 还 清 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23755', '40', '18', '27', '那 仆 人 的 主 人 就 动 了 慈 心 ， 把 他 释 放 了 ， 并 且 免 了 他 的 债 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23756', '40', '18', '28', '“ 那 仆 人 出 来 ， 遇 见 他 的 一 个 同 伴 欠 他 十 两 银 子 ， 便 揪 着 他 ， 掐 住 他 的 喉 咙 ， 说 ： ‘ 你 把 所 欠 的 还 我 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23757', '40', '18', '29', '他 的 同 伴 就 俯 伏 央 求 他 ， 说 ： ‘ 宽 容 我 吧 ， 将 来 我 必 还 清 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23758', '40', '18', '30', '他 不 肯 ， 竟 去 把 他 下 在 监 里 ， 等 他 还 了 所 欠 的 债 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23759', '40', '18', '31', '众 同 伴 看 见 他 所 做 的 事 就 甚 忧 愁 ， 去 把 这 事 都 告 诉 了 主 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23760', '40', '18', '32', '于 是 主 人 叫 了 他 来 ， 对 他 说 ： ‘ 你 这 恶 奴 才 ！ 你 央 求 我 ， 我 就 把 你 所 欠 的 都 免 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23761', '40', '18', '33', '你 不 应 当 怜 恤 你 的 同 伴 ， 像 我 怜 恤 你 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23762', '40', '18', '34', '主 人 就 大 怒 ， 把 他 交 给 掌 刑 的 ， 等 他 还 清 了 所 欠 的 债 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23763', '40', '18', '35', '你 们 各 人 若 不 从 心 里 饶 恕 你 的 弟 兄 ， 我 天 父 也 要 这 样 待 你 们 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23764', '40', '19', '1', '＜ 休 妻 的 问 题 （ 可   1 0 : 1 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23765', '40', '19', '2', '有 许 多 人 跟 着 他 ， 他 就 在 那 里 把 他 们 的 病 人 治 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23766', '40', '19', '3', '有 法 利 赛 人 来 试 探 耶 稣 ， 说 ： “ 人 无 论 什 么 缘 故 都 可 以 休 妻 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23767', '40', '19', '4', '耶 稣 回 答 说 ： “ 那 起 初 造 人 的 ， 是 造 男 造 女 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23768', '40', '19', '5', '并 且 说 ： ‘ 因 此 ， 人 要 离 开 父 母 ， 与 妻 子 连 合 ， 二 人 成 为 一 体 。 ’ 这 经 你 们 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23769', '40', '19', '6', '既 然 如 此 ， 夫 妻 不 再 是 两 个 人 ， 乃 是 一 体 的 了 。 所 以 ， 神 配 合 的 ， 人 不 可 分 开 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23770', '40', '19', '7', '法 利 赛 人 说 ： “ 这 样 ， 摩 西 为 什 么 吩 咐 给 妻 子 休 书 ， 就 可 以 休 她 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23771', '40', '19', '8', '耶 稣 说 ： “ 摩 西 因 为 你 们 的 心 硬 ， 所 以 许 你 们 休 妻 ， 但 起 初 并 不 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23772', '40', '19', '9', '我 告 诉 你 们 ， 凡 休 妻 另 娶 的 ， 若 不 是 为 淫 乱 的 缘 故 ， 就 是 犯 奸 淫 了 ； 有 人 娶 那 被 休 的 妇 人 ， 也 是 犯 奸 淫 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23773', '40', '19', '10', '门 徒 对 耶 稣 说 ： “ 人 和 妻 子 既 是 这 样 ， 倒 不 如 不 娶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23774', '40', '19', '11', '耶 稣 说 ： “ 这 话 不 是 人 都 能 领 受 的 ， 惟 独 赐 给 谁 ， 谁 才 能 领 受 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23775', '40', '19', '12', '因 为 有 生 来 是 阉 人 ， 也 有 被 人 阉 的 ， 并 有 为 天 国 的 缘 故 自 阉 的 。 这 话 谁 能 领 受 就 可 以 领 受 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23776', '40', '19', '13', '＜ 耶 稣 为 小 孩 祝 福 （ 可   1 0 : 1 3 - 1 6 ； 路   1 8 : 1 5 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23777', '40', '19', '14', '耶 稣 说 ： “ 让 小 孩 子 到 我 这 里 来 ， 不 要 禁 止 他 们 ； 因 为 在 天 国 的 ， 正 是 这 样 的 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23778', '40', '19', '15', '耶 稣 给 他 们 按 手 ， 就 离 开 那 地 方 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23779', '40', '19', '16', '＜ 少 年 财 主 （ 可   1 0 : 1 7 - 3 1 ； 路   1 8 : 1 8 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23780', '40', '19', '17', '耶 稣 对 他 说 ： “ 你 为 什 么 以 善 事 问 我 呢 ？ 只 有 一 位 是 善 的 ｛ 有 古 卷 ： 你 为 什 么 称 我 是 良 善 的 ？ 除 了 神 以 外 ， 没 有 一 个 良 善 的 ｝ 。 你 若 要 进 入 永 生 ， 就 当 遵 守 诫 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23781', '40', '19', '18', '他 说 ： “ 什 么 诫 命 ？ ” 耶 稣 说 ： “ 就 是 不 可 杀 人 ； 不 可 奸 淫 ； 不 可 偷 盗 ； 不 可 作 假 见 证 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23782', '40', '19', '19', '当 孝 敬 父 母 ； 又 当 爱 人 如 己 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23783', '40', '19', '20', '那 少 年 人 说 ： “ 这 一 切 我 都 遵 守 了 ， 还 缺 少 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23784', '40', '19', '21', '耶 稣 说 ： “ 你 若 愿 意 作 完 全 人 ， 可 去 变 卖 你 所 有 的 ， 分 给 穷 人 ， 就 必 有 财 宝 在 天 上 ； 你 还 要 来 跟 从 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23785', '40', '19', '22', '那 少 年 人 听 见 这 话 ， 就 忧 忧 愁 愁 地 走 了 ， 因 为 他 的 产 业 很 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23786', '40', '19', '23', '耶 稣 对 门 徒 说 ： “ 我 实 在 告 诉 你 们 ， 财 主 进 天 国 是 难 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23787', '40', '19', '24', '我 又 告 诉 你 们 ， 骆 驼 穿 过 针 的 眼 ， 比 财 主 进 神 的 国 还 容 易 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23788', '40', '19', '25', '门 徒 听 见 这 话 ， 就 希 奇 得 很 ， 说 ： “ 这 样 谁 能 得 救 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23789', '40', '19', '26', '耶 稣 看 着 他 们 ， 说 ： “ 在 人 这 是 不 能 的 ， 在 神 凡 事 都 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23790', '40', '19', '27', '彼 得 就 对 他 说 ： “ 看 哪 ， 我 们 已 经 撇 下 所 有 的 跟 从 你 ， 将 来 我 们 要 得 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23791', '40', '19', '28', '耶 稣 说 ： “ 我 实 在 告 诉 你 们 ， 你 们 这 跟 从 我 的 人 ， 到 复 兴 的 时 候 ， 人 子 坐 在 他 荣 耀 的 宝 座 上 ， 你 们 也 要 坐 在 十 二 个 宝 座 上 ， 审 判 以 色 列 十 二 个 支 派 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23792', '40', '19', '29', '凡 为 我 的 名 撇 下 房 屋 ， 或 是 弟 兄 、 姊 妹 、 父 亲 、 母 亲 、 ｛ 有 古 卷 加 ： 妻 子 、 ｝ 儿 女 、 田 地 的 ， 必 要 得 着 百 倍 ， 并 且 承 受 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23793', '40', '19', '30', '然 而 ， 有 许 多 在 前 的 ， 将 要 在 后 ； 在 后 的 ， 将 要 在 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23794', '40', '20', '1', '＜ 葡 萄 园 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23795', '40', '20', '2', '和 工 人 讲 定 一 天 一 钱 银 子 ， 就 打 发 他 们 进 葡 萄 园 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23796', '40', '20', '3', '约 在 巳 初 出 去 ， 看 见 市 上 还 有 闲 站 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23797', '40', '20', '4', '就 对 他 们 说 ： ‘ 你 们 也 进 葡 萄 园 去 ， 所 当 给 的 ， 我 必 给 你 们 。 ’ 他 们 也 进 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23798', '40', '20', '5', '约 在 午 正 和 申 初 又 出 去 ， 也 是 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23799', '40', '20', '6', '约 在 酉 初 出 去 ， 看 见 还 有 人 站 在 那 里 ， 就 问 他 们 说 ： ‘ 你 们 为 什 么 整 天 在 这 里 闲 站 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23800', '40', '20', '7', '他 们 说 ： ‘ 因 为 没 有 人 雇 我 们 。 ’ 他 说 ： ‘ 你 们 也 进 葡 萄 园 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23801', '40', '20', '8', '到 了 晚 上 ， 园 主 对 管 事 的 说 ： ‘ 叫 工 人 都 来 ， 给 他 们 工 钱 ， 从 后 来 的 起 ， 到 先 来 的 为 止 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23802', '40', '20', '9', '约 在 酉 初 雇 的 人 来 了 ， 各 人 得 了 一 钱 银 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23803', '40', '20', '10', '及 至 那 先 雇 的 来 了 ， 他 们 以 为 必 要 多 得 ； 谁 知 也 是 各 得 一 钱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23804', '40', '20', '11', '他 们 得 了 ， 就 埋 怨 家 主 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23805', '40', '20', '12', '‘ 我 们 整 天 劳 苦 受 热 ， 那 后 来 的 只 做 了 一 小 时 ， 你 竟 叫 他 们 和 我 们 一 样 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23806', '40', '20', '13', '家 主 回 答 其 中 的 一 人 说 ： ‘ 朋 友 ， 我 不 亏 负 你 ， 你 与 我 讲 定 的 不 是 一 钱 银 子 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23807', '40', '20', '14', '拿 你 的 走 吧 ！ 我 给 那 后 来 的 和 给 你 一 样 ， 这 是 我 愿 意 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23808', '40', '20', '15', '我 的 东 西 难 道 不 可 随 我 的 意 思 用 吗 ？ 因 为 我 作 好 人 ， 你 就 红 了 眼 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23809', '40', '20', '16', '这 样 ， 那 在 后 的 ， 将 要 在 前 ； 在 前 的 ， 将 要 在 后 了 。 ｛ 有 古 卷 加 ： 因 为 被 召 的 人 多 ， 选 上 的 人 少 。 ｝ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23810', '40', '20', '17', '＜ 耶 稣 第 三 次 预 言 受 难 和 复 活 （ 可   1 0 : 3 2 - 3 4 ； 路   1 8 : 3 1 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23811', '40', '20', '18', '“ 看 哪 ， 我 们 上 耶 路 撒 冷 去 ， 人 子 要 被 交 给 祭 司 长 和 文 士 。 他 们 要 定 他 死 罪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23812', '40', '20', '19', '又 交 给 外 邦 人 ， 将 他 戏 弄 ， 鞭 打 ， 钉 在 十 字 架 上 ； 第 三 日 他 要 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23813', '40', '20', '20', '＜ 母 亲 的 请 求 （ 可   1 0 : 3 5 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23814', '40', '20', '21', '耶 稣 说 ： “ 你 要 什 么 呢 ？ ” 她 说 ： “ 愿 你 叫 我 这 两 个 儿 子 在 你 国 里 ， 一 个 坐 在 你 右 边 ， 一 个 坐 在 你 左 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23815', '40', '20', '22', '耶 稣 回 答 说 ： “ 你 们 不 知 道 所 求 的 是 什 么 ； 我 将 要 喝 的 杯 ， 你 们 能 喝 吗 ？ ” 他 们 说 ： “ 我 们 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23816', '40', '20', '23', '耶 稣 说 ： “ 我 所 喝 的 杯 ， 你 们 必 要 喝 ； 只 是 坐 在 我 的 左 右 ， 不 是 我 可 以 赐 的 ， 乃 是 我 父 为 谁 预 备 的 ， 就 赐 给 谁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23817', '40', '20', '24', '那 十 个 门 徒 听 见 ， 就 恼 怒 他 们 弟 兄 二 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23818', '40', '20', '25', '耶 稣 叫 了 他 们 来 ， 说 ： “ 你 们 知 道 外 邦 人 有 君 王 为 主 治 理 他 们 ， 有 大 臣 操 权 管 束 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23819', '40', '20', '26', '只 是 在 你 们 中 间 ， 不 可 这 样 ； 你 们 中 间 谁 愿 为 大 ， 就 必 作 你 们 的 用 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23820', '40', '20', '27', '谁 愿 为 首 ， 就 必 作 你 们 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23821', '40', '20', '28', '正 如 人 子 来 ， 不 是 要 受 人 的 服 事 ， 乃 是 要 服 事 人 ， 并 且 要 舍 命 ， 作 多 人 的 赎 价 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23822', '40', '20', '29', '＜ 治 好 两 个 瞎 子 （ 可   1 0 : 4 6 - 5 2 ； 路   1 8 : 3 5 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23823', '40', '20', '30', '有 两 个 瞎 子 坐 在 路 旁 ， 听 说 是 耶 稣 经 过 ， 就 喊 着 说 ： “ 主 啊 ， 大 卫 的 子 孙 ， 可 怜 我 们 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23824', '40', '20', '31', '众 人 责 备 他 们 ， 不 许 他 们 作 声 ； 他 们 却 越 发 喊 着 说 ： “ 主 啊 ， 大 卫 的 子 孙 ， 可 怜 我 们 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23825', '40', '20', '32', '耶 稣 就 站 住 ， 叫 他 们 来 ， 说 ： “ 要 我 为 你 们 做 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23826', '40', '20', '33', '他 们 说 ： “ 主 啊 ， 要 我 们 的 眼 睛 能 看 见 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23827', '40', '20', '34', '耶 稣 就 动 了 慈 心 ， 把 他 们 的 眼 睛 一 摸 ， 他 们 立 刻 看 见 ， 就 跟 从 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23828', '40', '21', '1', '＜ 光 荣 地 进 耶 路 撒 冷 （ 可   1 1 : 1 - 1 1 ； 路   1 9 : 2 8 - 4 0 ； 约   1 2 : 1 2 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23829', '40', '21', '2', '耶 稣 就 打 发 两 个 门 徒 ， 对 他 们 说 ： “ 你 们 往 对 面 村 子 里 去 ， 必 看 见 一 匹 驴 拴 在 那 里 ， 还 有 驴 驹 同 在 一 处 ； 你 们 解 开 ， 牵 到 我 这 里 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23830', '40', '21', '3', '若 有 人 对 你 们 说 什 么 ， 你 们 就 说 ： ‘ 主 要 用 它 。 ’ 那 人 必 立 时 让 你 们 牵 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23831', '40', '21', '4', '这 事 成 就 是 要 应 验 先 知 的 话 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23832', '40', '21', '5', '要 对 锡 安 的 居 民 ｛ 原 文 是 女 子 ｝ 说 ： 看 哪 ， 你 的 王 来 到 你 这 里 ， 是 温 柔 的 ， 又 骑 着 驴 ， 就 是 骑 着 驴 驹 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23833', '40', '21', '6', '门 徒 就 照 耶 稣 所 吩 咐 的 去 行 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23834', '40', '21', '7', '牵 了 驴 和 驴 驹 来 ， 把 自 己 的 衣 服 搭 在 上 面 ， 耶 稣 就 骑 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23835', '40', '21', '8', '众 人 多 半 把 衣 服 铺 在 路 上 ； 还 有 人 砍 下 树 枝 来 铺 在 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23836', '40', '21', '9', '前 行 后 随 的 众 人 喊 着 说 ： 和 散 那 ｛ 原 有 求 救 的 意 思 ， 在 此 是 称 颂 的 话 ｝ 归 于 大 卫 的 子 孙 ！ 奉 主 名 来 的 是 应 当 称 颂 的 ！ 高 高 在 上 和 散 那 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23837', '40', '21', '10', '耶 稣 既 进 了 耶 路 撒 冷 ， 合 城 都 惊 动 了 ， 说 ： “ 这 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23838', '40', '21', '11', '众 人 说 ： “ 这 是 加 利 利 拿 撒 勒 的 先 知 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23839', '40', '21', '12', '＜ 洁 净 圣 殿 （ 可   1 1 : 1 5 - 1 9 ； 路   1 9 : 4 5 - 4 8 ； 约   2 : 1 3 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23840', '40', '21', '13', '对 他 们 说 ： “ 经 上 记 着 说 ： 我 的 殿 必 称 为 祷 告 的 殿 ， 你 们 倒 使 它 成 为 贼 窝 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23841', '40', '21', '14', '在 殿 里 有 瞎 子 、 瘸 子 到 耶 稣 跟 前 ， 他 就 治 好 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23842', '40', '21', '15', '祭 司 长 和 文 士 看 见 耶 稣 所 行 的 奇 事 ， 又 见 小 孩 子 在 殿 里 喊 着 说 ： “ 和 散 那 归 于 大 卫 的 子 孙 ！ ” 就 甚 恼 怒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23843', '40', '21', '16', '对 他 说 ： “ 这 些 人 所 说 的 ， 你 听 见 了 吗 ？ ” 耶 稣 说 ： “ 是 的 。 经 上 说 ‘ 你 从 婴 孩 和 吃 奶 的 口 中 完 全 了 赞 美 ’ 的 话 ， 你 们 没 有 念 过 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23844', '40', '21', '17', '于 是 离 开 他 们 ， 出 城 到 伯 大 尼 去 ， 在 那 里 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23845', '40', '21', '18', '＜ 咒 诅 无 花 果 树 （ 可   1 1 : 1 2 - 1 4 , 2 0 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23846', '40', '21', '19', '看 见 路 旁 有 一 棵 无 花 果 树 ， 就 走 到 跟 前 ， 在 树 上 找 不 着 什 么 ， 不 过 有 叶 子 ， 就 对 树 说 ： “ 从 今 以 后 ， 你 永 不 结 果 子 。 ” 那 无 花 果 树 就 立 刻 枯 干 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23847', '40', '21', '20', '门 徒 看 见 了 ， 便 希 奇 说 ： “ 无 花 果 树 怎 么 立 刻 枯 干 了 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23848', '40', '21', '21', '耶 稣 回 答 说 ： “ 我 实 在 告 诉 你 们 ， 你 们 若 有 信 心 ， 不 疑 惑 ， 不 但 能 行 无 花 果 树 上 所 行 的 事 ， 就 是 对 这 座 山 说 ： ‘ 你 挪 开 此 地 ， 投 在 海 里 ！ ’ 也 必 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23849', '40', '21', '22', '你 们 祷 告 ， 无 论 求 什 么 ， 只 要 信 ， 就 必 得 着 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23850', '40', '21', '23', '＜ 质 问 耶 稣 的 权 柄 （ 可   1 1 : 2 7 - 3 3 ； 路   2 0 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23851', '40', '21', '24', '耶 稣 回 答 说 ： “ 我 也 要 问 你 们 一 句 话 ， 你 们 若 告 诉 我 ， 我 就 告 诉 你 们 我 仗 着 什 么 权 柄 做 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23852', '40', '21', '25', '约 翰 的 洗 礼 是 从 哪 里 来 的 ？ 是 从 天 上 来 的 ？ 是 从 人 间 来 的 呢 ？ ” 他 们 彼 此 商 议 说 ： “ 我 们 若 说 ‘ 从 天 上 来 ’ ， 他 必 对 我 们 说 ： ‘ 这 样 ， 你 们 为 什 么 不 信 他 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23853', '40', '21', '26', '若 说 ‘ 从 人 间 来 ’ ， 我 们 又 怕 百 姓 ， 因 为 他 们 都 以 约 翰 为 先 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23854', '40', '21', '27', '于 是 回 答 耶 稣 说 ： “ 我 们 不 知 道 。 ” 耶 稣 说 ： “ 我 也 不 告 诉 你 们 我 仗 着 什 么 权 柄 做 这 些 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23855', '40', '21', '28', '＜ 两 个 儿 子 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23856', '40', '21', '29', '他 回 答 说 ： ‘ 我 不 去 ’ ， 以 后 自 己 懊 悔 ， 就 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23857', '40', '21', '30', '又 来 对 小 儿 子 也 是 这 样 说 。 他 回 答 说 ： ‘ 父 啊 ， 我 去 ’ ， 他 却 不 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23858', '40', '21', '31', '你 们 想 ， 这 两 个 儿 子 是 哪 一 个 遵 行 父 命 呢 ？ ” 他 们 说 ： “ 大 儿 子 。 ” 耶 稣 说 ： “ 我 实 在 告 诉 你 们 ， 税 吏 和 娼 妓 倒 比 你 们 先 进 神 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23859', '40', '21', '32', '因 为 约 翰 遵 着 义 路 到 你 们 这 里 来 ， 你 们 却 不 信 他 ； 税 吏 和 娼 妓 倒 信 他 。 你 们 看 见 了 ， 后 来 还 是 不 懊 悔 去 信 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23860', '40', '21', '33', '＜ 凶 恶 园 户 的 比 喻 （ 可   1 2 : 1 - 1 2 ； 路   2 0 : 9 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23861', '40', '21', '34', '收 果 子 的 时 候 近 了 ， 就 打 发 仆 人 到 园 户 那 里 去 收 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23862', '40', '21', '35', '园 户 拿 住 仆 人 ， 打 了 一 个 ， 杀 了 一 个 ， 用 石 头 打 死 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23863', '40', '21', '36', '主 人 又 打 发 别 的 仆 人 去 ， 比 先 前 更 多 ； 园 户 还 是 照 样 待 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23864', '40', '21', '37', '后 来 打 发 他 的 儿 子 到 他 们 那 里 去 ， 意 思 说 ： ‘ 他 们 必 尊 敬 我 的 儿 子 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23865', '40', '21', '38', '不 料 ， 园 户 看 见 他 儿 子 ， 就 彼 此 说 ： ‘ 这 是 承 受 产 业 的 。 来 吧 ， 我 们 杀 他 ， 占 他 的 产 业 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23866', '40', '21', '39', '他 们 就 拿 住 他 ， 推 出 葡 萄 园 外 ， 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23867', '40', '21', '40', '园 主 来 的 时 候 要 怎 样 处 治 这 些 园 户 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23868', '40', '21', '41', '他 们 说 ： “ 要 下 毒 手 除 灭 那 些 恶 人 ， 将 葡 萄 园 另 租 给 那 按 着 时 候 交 果 子 的 园 户 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23869', '40', '21', '42', '耶 稣 说 ： “ 经 上 写 着 ： 匠 人 所 弃 的 石 头 已 作 了 房 角 的 头 块 石 头 。 这 是 主 所 做 的 ， 在 我 们 眼 中 看 为 希 奇 。 这 经 你 们 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23870', '40', '21', '43', '所 以 我 告 诉 你 们 ， 神 的 国 必 从 你 们 夺 去 ， 赐 给 那 能 结 果 子 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23871', '40', '21', '44', '谁 掉 在 这 石 头 上 ， 必 要 跌 碎 ； 这 石 头 掉 在 谁 的 身 上 ， 就 要 把 谁 砸 得 稀 烂 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23872', '40', '21', '45', '祭 司 长 和 法 利 赛 人 听 见 他 的 比 喻 ， 就 看 出 他 是 指 着 他 们 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23873', '40', '21', '46', '他 们 想 要 捉 拿 他 ， 只 是 怕 众 人 ， 因 为 众 人 以 他 为 先 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23874', '40', '22', '1', '＜ 喜 筵 的 比 喻 （ 路   1 4 : 1 5 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23875', '40', '22', '2', '“ 天 国 好 比 一 个 王 为 他 儿 子 摆 设 娶 亲 的 筵 席 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23876', '40', '22', '3', '就 打 发 仆 人 去 ， 请 那 些 被 召 的 人 来 赴 席 ， 他 们 却 不 肯 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23877', '40', '22', '4', '王 又 打 发 别 的 仆 人 ， 说 ： ‘ 你 们 告 诉 那 被 召 的 人 ， 我 的 筵 席 已 经 预 备 好 了 ， 牛 和 肥 畜 已 经 宰 了 ， 各 样 都 齐 备 ， 请 你 们 来 赴 席 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23878', '40', '22', '5', '那 些 人 不 理 就 走 了 ； 一 个 到 自 己 田 里 去 ； 一 个 做 买 卖 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23879', '40', '22', '6', '其 余 的 拿 住 仆 人 ， 凌 辱 他 们 ， 把 他 们 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23880', '40', '22', '7', '王 就 大 怒 ， 发 兵 除 灭 那 些 凶 手 ， 烧 毁 他 们 的 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23881', '40', '22', '8', '于 是 对 仆 人 说 ： ‘ 喜 筵 已 经 齐 备 ， 只 是 所 召 的 人 不 配 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23882', '40', '22', '9', '所 以 你 们 要 往 岔 路 口 上 去 ， 凡 遇 见 的 ， 都 召 来 赴 席 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23883', '40', '22', '10', '那 些 仆 人 就 出 去 ， 到 大 路 上 ， 凡 遇 见 的 ， 不 论 善 恶 都 召 聚 了 来 ， 筵 席 上 就 坐 满 了 客 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23884', '40', '22', '11', '王 进 来 观 看 宾 客 ， 见 那 里 有 一 个 没 有 穿 礼 服 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23885', '40', '22', '12', '就 对 他 说 ： ‘ 朋 友 ， 你 到 这 里 来 怎 么 不 穿 礼 服 呢 ？ ’ 那 人 无 言 可 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23886', '40', '22', '13', '于 是 王 对 使 唤 的 人 说 ： ‘ 捆 起 他 的 手 脚 来 ， 把 他 丢 在 外 边 的 黑 暗 里 ； 在 那 里 必 要 哀 哭 切 齿 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23887', '40', '22', '14', '因 为 被 召 的 人 多 ， 选 上 的 人 少 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23888', '40', '22', '15', '＜ 纳 税 给 凯 撒 的 问 题 （ 可   1 2 : 1 3 - 1 7 ； 路   2 0 : 2 0 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23889', '40', '22', '16', '就 打 发 他 们 的 门 徒 同 希 律 党 的 人 去 见 耶 稣 ， 说 ： “ 夫 子 ， 我 们 知 道 你 是 诚 实 人 ， 并 且 诚 诚 实 实 传 神 的 道 ， 什 么 人 你 都 不 徇 情 面 ， 因 为 你 不 看 人 的 外 貌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23890', '40', '22', '17', '请 告 诉 我 们 ， 你 的 意 见 如 何 ？ 纳 税 给 凯 撒 可 以 不 可 以 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23891', '40', '22', '18', '耶 稣 看 出 他 们 的 恶 意 ， 就 说 ： “ 假 冒 为 善 的 人 哪 ， 为 什 么 试 探 我 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23892', '40', '22', '19', '拿 一 个 上 税 的 钱 给 我 看 ！ ” 他 们 就 拿 一 个 银 钱 来 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23893', '40', '22', '20', '耶 稣 说 ： “ 这 像 和 这 号 是 谁 的 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23894', '40', '22', '21', '他 们 说 ： “ 是 凯 撒 的 。 ” 耶 稣 说 ： “ 这 样 ， 凯 撒 的 物 当 归 给 凯 撒 ； 神 的 物 当 归 给 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23895', '40', '22', '22', '他 们 听 见 就 希 奇 ， 离 开 他 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23896', '40', '22', '23', '＜ 复 活 的 问 题 （ 可   1 2 : 1 8 - 2 7 ； 路   2 0 : 2 7 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23897', '40', '22', '24', '“ 夫 子 ， 摩 西 说 ： ‘ 人 若 死 了 ， 没 有 孩 子 ， 他 兄 弟 当 娶 他 的 妻 ， 为 哥 哥 生 子 立 后 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23898', '40', '22', '25', '从 前 ， 在 我 们 这 里 有 弟 兄 七 人 ， 第 一 个 娶 了 妻 ， 死 了 ， 没 有 孩 子 ， 撇 下 妻 子 给 兄 弟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23899', '40', '22', '26', '第 二 、 第 三 、 直 到 第 七 个 ， 都 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23900', '40', '22', '27', '末 后 ， 妇 人 也 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23901', '40', '22', '28', '这 样 ， 当 复 活 的 时 候 ， 她 是 七 个 人 中 哪 一 个 的 妻 子 呢 ？ 因 为 他 们 都 娶 过 她 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23902', '40', '22', '29', '耶 稣 回 答 说 ： “ 你 们 错 了 ； 因 为 不 明 白 圣 经 ， 也 不 晓 得 神 的 大 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23903', '40', '22', '30', '当 复 活 的 时 候 ， 人 也 不 娶 也 不 嫁 ， 乃 像 天 上 的 使 者 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23904', '40', '22', '31', '论 到 死 人 复 活 ， 神 在 经 上 向 你 们 所 说 的 ， 你 们 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23905', '40', '22', '32', '他 说 ： ‘ 我 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 。 ’ 神 不 是 死 人 的 神 ， 乃 是 活 人 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23906', '40', '22', '33', '众 人 听 见 这 话 ， 就 希 奇 他 的 教 训 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23907', '40', '22', '34', '＜ 最 大 的 诫 命 （ 可   1 2 : 2 8 - 3 4 ； 路   1 0 : 2 5 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23908', '40', '22', '35', '内 中 有 一 个 人 是 律 法 师 ， 要 试 探 耶 稣 ， 就 问 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23909', '40', '22', '36', '“ 夫 子 ， 律 法 上 的 诫 命 ， 哪 一 条 是 最 大 的 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23910', '40', '22', '37', '耶 稣 对 他 说 ： “ 你 要 尽 心 、 尽 性 、 尽 意 爱 主 ─ ─ 你 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23911', '40', '22', '38', '这 是 诫 命 中 的 第 一 ， 且 是 最 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23912', '40', '22', '39', '其 次 也 相 仿 ， 就 是 要 爱 人 如 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23913', '40', '22', '40', '这 两 条 诫 命 是 律 法 和 先 知 一 切 道 理 的 总 纲 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23914', '40', '22', '41', '＜ 大 卫 子 孙 的 问 题 （ 可   1 2 : 3 5 - 3 7 ； 路   2 0 : 4 1 - 4 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23915', '40', '22', '42', '“ 论 到 基 督 ， 你 们 的 意 见 如 何 ？ 他 是 谁 的 子 孙 呢 ？ ” 他 们 回 答 说 ： “ 是 大 卫 的 子 孙 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23916', '40', '22', '43', '耶 稣 说 ： “ 这 样 ， 大 卫 被 圣 灵 感 动 ， 怎 么 还 称 他 为 主 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23917', '40', '22', '44', '主 对 我 主 说 ： 你 坐 在 我 的 右 边 ， 等 我 把 你 仇 敌 放 在 你 的 脚 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23918', '40', '22', '45', '大 卫 既 称 他 为 主 ， 他 怎 么 又 是 大 卫 的 子 孙 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23919', '40', '22', '46', '他 们 没 有 一 个 人 能 回 答 一 言 。 从 那 日 以 后 ， 也 没 有 人 敢 再 问 他 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23920', '40', '23', '1', '＜ 谴 责 文 士 和 法 利 赛 人 （ 可   1 2 : 3 8 - 4 0 ； 路   1 1 : 3 7 - 5 2 ； 2 0 : 4 5 - 4 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23921', '40', '23', '2', '说 ： “ 文 士 和 法 利 赛 人 坐 在 摩 西 的 位 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23922', '40', '23', '3', '凡 他 们 所 吩 咐 你 们 的 ， 你 们 都 要 谨 守 遵 行 。 但 不 要 效 法 他 们 的 行 为 ； 因 为 他 们 能 说 ， 不 能 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23923', '40', '23', '4', '他 们 把 难 担 的 重 担 捆 起 来 ， 搁 在 人 的 肩 上 ， 但 自 己 一 个 指 头 也 不 肯 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23924', '40', '23', '5', '他 们 一 切 所 做 的 事 都 是 要 叫 人 看 见 ， 所 以 将 佩 戴 的 经 文 做 宽 了 ， 衣 裳 的 繸 子 做 长 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23925', '40', '23', '6', '喜 爱 筵 席 上 的 首 座 ， 会 堂 里 的 高 位 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23926', '40', '23', '7', '又 喜 爱 人 在 街 市 上 问 他 安 ， 称 呼 他 拉 比 ｛ 拉 比 就 是 夫 子 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23927', '40', '23', '8', '但 你 们 不 要 受 拉 比 的 称 呼 ， 因 为 只 有 一 位 是 你 们 的 夫 子 ； 你 们 都 是 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23928', '40', '23', '9', '也 不 要 称 呼 地 上 的 人 为 父 ， 因 为 只 有 一 位 是 你 们 的 父 ， 就 是 在 天 上 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23929', '40', '23', '10', '也 不 要 受 师 尊 的 称 呼 ， 因 为 只 有 一 位 是 你 们 的 师 尊 ， 就 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23930', '40', '23', '11', '你 们 中 间 谁 为 大 ， 谁 就 要 作 你 们 的 用 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23931', '40', '23', '12', '凡 自 高 的 ， 必 降 为 卑 ； 自 卑 的 ， 必 升 为 高 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23932', '40', '23', '13', '“ 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 正 当 人 前 ， 把 天 国 的 门 关 了 ， 自 己 不 进 去 ， 正 要 进 去 的 人 ， 你 们 也 不 容 他 们 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23933', '40', '23', '14', '｛ 有 古 卷 加 ： 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 侵 吞 寡 妇 的 家 产 ， 假 意 做 很 长 的 祷 告 ， 所 以 要 受 更 重 的 刑 罚 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23934', '40', '23', '15', '“ 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 走 遍 洋 海 陆 地 ， 勾 引 一 个 人 入 教 ， 既 入 了 教 ， 却 使 他 作 地 狱 之 子 ， 比 你 们 还 加 倍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23935', '40', '23', '16', '“ 你 们 这 瞎 眼 领 路 的 有 祸 了 ！ 你 们 说 ： ‘ 凡 指 着 殿 起 誓 的 ， 这 算 不 得 什 么 ； 只 是 凡 指 着 殿 中 金 子 起 誓 的 ， 他 就 该 谨 守 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23936', '40', '23', '17', '你 们 这 无 知 瞎 眼 的 人 哪 ， 什 么 是 大 的 ？ 是 金 子 呢 ？ 还 是 叫 金 子 成 圣 的 殿 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23937', '40', '23', '18', '你 们 又 说 ： ‘ 凡 指 着 坛 起 誓 的 ， 这 算 不 得 什 么 ； 只 是 凡 指 着 坛 上 礼 物 起 誓 的 ， 他 就 该 谨 守 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23938', '40', '23', '19', '你 们 这 瞎 眼 的 人 哪 ， 什 么 是 大 的 ？ 是 礼 物 呢 ？ 还 是 叫 礼 物 成 圣 的 坛 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23939', '40', '23', '20', '所 以 ， 人 指 着 坛 起 誓 ， 就 是 指 着 坛 和 坛 上 一 切 所 有 的 起 誓 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23940', '40', '23', '21', '人 指 着 殿 起 誓 ， 就 是 指 着 殿 和 那 住 在 殿 里 的 起 誓 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23941', '40', '23', '22', '人 指 着 天 起 誓 ， 就 是 指 着 神 的 宝 座 和 那 坐 在 上 面 的 起 誓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23942', '40', '23', '23', '“ 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 将 薄 荷 、 茴 香 、 芹 菜 ， 献 上 十 分 之 一 ， 那 律 法 上 更 重 的 事 ， 就 是 公 义 、 怜 悯 、 信 实 ， 反 倒 不 行 了 。 这 更 重 的 是 你 们 当 行 的 ； 那 也 是 不 可 不 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23943', '40', '23', '24', '你 们 这 瞎 眼 领 路 的 ， 蠓 虫 你 们 就 滤 出 来 ， 骆 驼 你 们 倒 吞 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23944', '40', '23', '25', '“ 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 洗 净 杯 盘 的 外 面 ， 里 面 却 盛 满 了 勒 索 和 放 荡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23945', '40', '23', '26', '你 这 瞎 眼 的 法 利 赛 人 ， 先 洗 净 杯 盘 的 里 面 ， 好 叫 外 面 也 干 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23946', '40', '23', '27', '“ 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 好 像 粉 饰 的 坟 墓 ， 外 面 好 看 ， 里 面 却 装 满 了 死 人 的 骨 头 和 一 切 的 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23947', '40', '23', '28', '你 们 也 是 如 此 ， 在 人 前 ， 外 面 显 出 公 义 来 ， 里 面 却 装 满 了 假 善 和 不 法 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23948', '40', '23', '29', '“ 你 们 这 假 冒 为 善 的 文 士 和 法 利 赛 人 有 祸 了 ！ 因 为 你 们 建 造 先 知 的 坟 ， 修 饰 义 人 的 墓 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23949', '40', '23', '30', '‘ 若 是 我 们 在 我 们 祖 宗 的 时 候 ， 必 不 和 他 们 同 流 先 知 的 血 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23950', '40', '23', '31', '这 就 是 你 们 自 己 证 明 是 杀 害 先 知 者 的 子 孙 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23951', '40', '23', '32', '你 们 去 充 满 你 们 祖 宗 的 恶 贯 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23952', '40', '23', '33', '你 们 这 些 蛇 类 、 毒 蛇 之 种 啊 ， 怎 能 逃 脱 地 狱 的 刑 罚 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23953', '40', '23', '34', '所 以 我 差 遣 先 知 和 智 慧 人 并 文 士 到 你 们 这 里 来 ， 有 的 你 们 要 杀 害 ， 要 钉 十 字 架 ； 有 的 你 们 要 在 会 堂 里 鞭 打 ， 从 这 城 追 逼 到 那 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23954', '40', '23', '35', '叫 世 上 所 流 义 人 的 血 都 归 到 你 们 身 上 ， 从 义 人 亚 伯 的 血 起 ， 直 到 你 们 在 殿 和 坛 中 间 所 杀 的 巴 拉 加 的 儿 子 撒 迦 利 亚 的 血 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23955', '40', '23', '36', '我 实 在 告 诉 你 们 ， 这 一 切 的 罪 都 要 归 到 这 世 代 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23956', '40', '23', '37', '＜ 为 耶 路 撒 冷 哀 哭 （ 路   1 3 : 3 4 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23957', '40', '23', '38', '看 哪 ， 你 们 的 家 成 为 荒 场 留 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23958', '40', '23', '39', '我 告 诉 你 们 ， 从 今 以 后 ， 你 们 不 得 再 见 我 ， 直 等 到 你 们 说 ： ‘ 奉 主 名 来 的 是 应 当 称 颂 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23959', '40', '24', '1', '＜ 预 言 圣 殿 被 毁 （ 可   1 3 : 1 - 2 ； 路   2 1 : 5 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23960', '40', '24', '2', '耶 稣 对 他 们 说 ： “ 你 们 不 是 看 见 这 殿 宇 吗 ？ 我 实 在 告 诉 你 们 ， 将 来 在 这 里 没 有 一 块 石 头 留 在 石 头 上 ， 不 被 拆 毁 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23961', '40', '24', '3', '＜ 灾 难 的 起 头 （ 可   1 3 : 3 - 1 3 ； 路   2 1 : 7 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23962', '40', '24', '4', '耶 稣 回 答 说 ： “ 你 们 要 谨 慎 ， 免 得 有 人 迷 惑 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23963', '40', '24', '5', '因 为 将 来 有 好 些 人 冒 我 的 名 来 ， 说 ： ‘ 我 是 基 督 ’ ， 并 且 要 迷 惑 许 多 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23964', '40', '24', '6', '你 们 也 要 听 见 打 仗 和 打 仗 的 风 声 ， 总 不 要 惊 慌 ； 因 为 这 些 事 是 必 须 有 的 ， 只 是 末 期 还 没 有 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23965', '40', '24', '7', '民 要 攻 打 民 ， 国 要 攻 打 国 ； 多 处 必 有 饥 荒 、 地 震 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23966', '40', '24', '8', '这 都 是 灾 难 ｛ 灾 难 ： 原 文 是 生 产 之 难 ｝ 的 起 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23967', '40', '24', '9', '那 时 ， 人 要 把 你 们 陷 在 患 难 里 ， 也 要 杀 害 你 们 ； 你 们 又 要 为 我 的 名 被 万 民 恨 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23968', '40', '24', '10', '那 时 ， 必 有 许 多 人 跌 倒 ， 也 要 彼 此 陷 害 ， 彼 此 恨 恶 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23969', '40', '24', '11', '且 有 好 些 假 先 知 起 来 ， 迷 惑 多 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23970', '40', '24', '12', '只 因 不 法 的 事 增 多 ， 许 多 人 的 爱 心 才 渐 渐 冷 淡 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23971', '40', '24', '13', '惟 有 忍 耐 到 底 的 ， 必 然 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23972', '40', '24', '14', '这 天 国 的 福 音 要 传 遍 天 下 ， 对 万 民 作 见 证 ， 然 后 末 期 才 来 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23973', '40', '24', '15', '＜ 大 灾 难 （ 可   1 3 : 1 4 - 2 3 ； 路   2 1 : 2 0 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23974', '40', '24', '16', '那 时 ， 在 犹 太 的 ， 应 当 逃 到 山 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23975', '40', '24', '17', '在 房 上 的 ， 不 要 下 来 拿 家 里 的 东 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23976', '40', '24', '18', '在 田 里 的 ， 也 不 要 回 去 取 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23977', '40', '24', '19', '当 那 些 日 子 ， 怀 孕 的 和 奶 孩 子 的 有 祸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23978', '40', '24', '20', '你 们 应 当 祈 求 ， 叫 你 们 逃 走 的 时 候 ， 不 遇 见 冬 天 或 是 安 息 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23979', '40', '24', '21', '因 为 那 时 必 有 大 灾 难 ， 从 世 界 的 起 头 直 到 如 今 ， 没 有 这 样 的 灾 难 ， 后 来 也 必 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23980', '40', '24', '22', '若 不 减 少 那 日 子 ， 凡 有 血 气 的 总 没 有 一 个 得 救 的 ； 只 是 为 选 民 ， 那 日 子 必 减 少 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23981', '40', '24', '23', '那 时 ， 若 有 人 对 你 们 说 ： ‘ 基 督 在 这 里 ’ ， 或 说 ： ‘ 基 督 在 那 里 ’ ， 你 们 不 要 信 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23982', '40', '24', '24', '因 为 假 基 督 、 假 先 知 将 要 起 来 ， 显 大 神 迹 、 大 奇 事 ， 倘 若 能 行 ， 连 选 民 也 就 迷 惑 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23983', '40', '24', '25', '看 哪 ， 我 预 先 告 诉 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23984', '40', '24', '26', '若 有 人 对 你 们 说 ： ‘ 看 哪 ， 基 督 在 旷 野 里 ’ ， 你 们 不 要 出 去 ！ 或 说 ： ‘ 看 哪 ， 基 督 在 内 屋 中 ’ ， 你 们 不 要 信 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23985', '40', '24', '27', '闪 电 从 东 边 发 出 ， 直 照 到 西 边 。 人 子 降 临 也 要 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23986', '40', '24', '28', '尸 首 在 哪 里 ， 鹰 也 必 聚 在 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23987', '40', '24', '29', '＜ 人 子 的 降 临 （ 可   1 3 : 2 4 - 2 7 ； 路   2 1 : 2 5 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23988', '40', '24', '30', '那 时 ， 人 子 的 兆 头 要 显 在 天 上 ， 地 上 的 万 族 都 要 哀 哭 。 他 们 要 看 见 人 子 ， 有 能 力 ， 有 大 荣 耀 ， 驾 着 天 上 的 云 降 临 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23989', '40', '24', '31', '他 要 差 遣 使 者 ， 用 号 筒 的 大 声 ， 将 他 的 选 民 ， 从 四 方 ｛ 方 ： 原 文 是 风 ｝ ， 从 天 这 边 到 天 那 边 ， 都 招 聚 了 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23990', '40', '24', '32', '＜ 从 无 花 果 树 学 个 比 方 （ 可   1 3 : 2 8 - 3 1 ； 路   2 1 : 2 9 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23991', '40', '24', '33', '这 样 ， 你 们 看 见 这 一 切 的 事 ， 也 该 知 道 人 子 近 了 ， 正 在 门 口 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23992', '40', '24', '34', '我 实 在 告 诉 你 们 ， 这 世 代 还 没 有 过 去 ， 这 些 事 都 要 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23993', '40', '24', '35', '天 地 要 废 去 ， 我 的 话 却 不 能 废 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23994', '40', '24', '36', '＜ 那 日 那 时 没 有 人 知 道 （ 可   1 3 : 3 2 - 3 7 ； 路   1 7 : 2 6 - 3 0 , 3 4 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23995', '40', '24', '37', '挪 亚 的 日 子 怎 样 ， 人 子 降 临 也 要 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23996', '40', '24', '38', '当 洪 水 以 前 的 日 子 ， 人 照 常 吃 喝 嫁 娶 ， 直 到 挪 亚 进 方 舟 的 那 日 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23997', '40', '24', '39', '不 知 不 觉 洪 水 来 了 ， 把 他 们 全 都 冲 去 。 人 子 降 临 也 要 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23998', '40', '24', '40', '那 时 ， 两 个 人 在 田 里 ， 取 去 一 个 ， 撇 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('23999', '40', '24', '41', '两 个 女 人 推 磨 ， 取 去 一 个 ， 撇 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24000', '40', '24', '42', '所 以 ， 你 们 要 警 醒 ， 因 为 不 知 道 你 们 的 主 是 哪 一 天 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24001', '40', '24', '43', '家 主 若 知 道 几 更 天 有 贼 来 ， 就 必 警 醒 ， 不 容 人 挖 透 房 屋 ； 这 是 你 们 所 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24002', '40', '24', '44', '所 以 ， 你 们 也 要 预 备 ， 因 为 你 们 想 不 到 的 时 候 ， 人 子 就 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24003', '40', '24', '45', '＜ 忠 心 和 不 忠 心 的 仆 人 （ 路   1 2 : 4 1 - 4 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24004', '40', '24', '46', '主 人 来 到 ， 看 见 他 这 样 行 ， 那 仆 人 就 有 福 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24005', '40', '24', '47', '我 实 在 告 诉 你 们 ， 主 人 要 派 他 管 理 一 切 所 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24006', '40', '24', '48', '倘 若 那 恶 仆 心 里 说 ： ‘ 我 的 主 人 必 来 得 迟 ’ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24007', '40', '24', '49', '就 动 手 打 他 的 同 伴 ， 又 和 酒 醉 的 人 一 同 吃 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24008', '40', '24', '50', '在 想 不 到 的 日 子 ， 不 知 道 的 时 辰 ， 那 仆 人 的 主 人 要 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24009', '40', '24', '51', '重 重 地 处 治 他 ｛ 或 译 ： 把 他 腰 斩 了 ｝ ， 定 他 和 假 冒 为 善 的 人 同 罪 ； 在 那 里 必 要 哀 哭 切 齿 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24010', '40', '25', '1', '＜ 十 童 女 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24011', '40', '25', '2', '其 中 有 五 个 是 愚 拙 的 ， 五 个 是 聪 明 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24012', '40', '25', '3', '愚 拙 的 拿 着 灯 ， 却 不 预 备 油 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24013', '40', '25', '4', '聪 明 的 拿 着 灯 ， 又 预 备 油 在 器 皿 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24014', '40', '25', '5', '新 郎 迟 延 的 时 候 ， 她 们 都 打 盹 ， 睡 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24015', '40', '25', '6', '半 夜 有 人 喊 着 说 ： ‘ 新 郎 来 了 ， 你 们 出 来 迎 接 他 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24016', '40', '25', '7', '那 些 童 女 就 都 起 来 收 拾 灯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24017', '40', '25', '8', '愚 拙 的 对 聪 明 的 说 ： ‘ 请 分 点 油 给 我 们 ， 因 为 我 们 的 灯 要 灭 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24018', '40', '25', '9', '聪 明 的 回 答 说 ： ‘ 恐 怕 不 够 你 我 用 的 ； 不 如 你 们 自 己 到 卖 油 的 那 里 去 买 吧 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24019', '40', '25', '10', '她 们 去 买 的 时 候 ， 新 郎 到 了 。 那 预 备 好 了 的 ， 同 他 进 去 坐 席 ， 门 就 关 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24020', '40', '25', '11', '其 余 的 童 女 随 后 也 来 了 ， 说 ： ‘ 主 啊 ， 主 啊 ， 给 我 们 开 门 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24021', '40', '25', '12', '他 却 回 答 说 ： ‘ 我 实 在 告 诉 你 们 ， 我 不 认 识 你 们 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24022', '40', '25', '13', '所 以 ， 你 们 要 警 醒 ； 因 为 那 日 子 ， 那 时 辰 ， 你 们 不 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24023', '40', '25', '14', '＜ 按 才 干 接 受 托 付 的 比 喻 （ 路   1 9 : 1 1 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24024', '40', '25', '15', '按 着 各 人 的 才 干 给 他 们 银 子 ： 一 个 给 了 五 千 ， 一 个 给 了 二 千 ， 一 个 给 了 一 千 ， 就 往 外 国 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24025', '40', '25', '16', '那 领 五 千 的 随 即 拿 去 做 买 卖 ， 另 外 赚 了 五 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24026', '40', '25', '17', '那 领 二 千 的 也 照 样 另 赚 了 二 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24027', '40', '25', '18', '但 那 领 一 千 的 去 掘 开 地 ， 把 主 人 的 银 子 埋 藏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24028', '40', '25', '19', '过 了 许 久 ， 那 些 仆 人 的 主 人 来 了 ， 和 他 们 算 帐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24029', '40', '25', '20', '那 领 五 千 银 子 的 又 带 着 那 另 外 的 五 千 来 ， 说 ： ‘ 主 啊 ， 你 交 给 我 五 千 银 子 。 请 看 ， 我 又 赚 了 五 千 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24030', '40', '25', '21', '主 人 说 ： ‘ 好 ， 你 这 又 良 善 又 忠 心 的 仆 人 ， 你 在 不 多 的 事 上 有 忠 心 ， 我 要 把 许 多 事 派 你 管 理 ； 可 以 进 来 享 受 你 主 人 的 快 乐 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24031', '40', '25', '22', '那 领 二 千 的 也 来 ， 说 ： ‘ 主 啊 ， 你 交 给 我 二 千 银 子 。 请 看 ， 我 又 赚 了 二 千 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24032', '40', '25', '23', '主 人 说 ： ‘ 好 ， 你 这 又 良 善 又 忠 心 的 仆 人 ， 你 在 不 多 的 事 上 有 忠 心 ， 我 要 把 许 多 事 派 你 管 理 ； 可 以 进 来 享 受 你 主 人 的 快 乐 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24033', '40', '25', '24', '那 领 一 千 的 也 来 ， 说 ： ‘ 主 啊 ， 我 知 道 你 是 忍 心 的 人 ， 没 有 种 的 地 方 要 收 割 ， 没 有 散 的 地 方 要 聚 敛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24034', '40', '25', '25', '我 就 害 怕 ， 去 把 你 的 一 千 银 子 埋 藏 在 地 里 。 请 看 ， 你 的 原 银 子 在 这 里 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24035', '40', '25', '26', '主 人 回 答 说 ： ‘ 你 这 又 恶 又 懒 的 仆 人 ， 你 既 知 道 我 没 有 种 的 地 方 要 收 割 ， 没 有 散 的 地 方 要 聚 敛 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24036', '40', '25', '27', '就 当 把 我 的 银 子 放 给 兑 换 银 钱 的 人 ， 到 我 来 的 时 候 ， 可 以 连 本 带 利 收 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24037', '40', '25', '28', '夺 过 他 这 一 千 来 ， 给 那 有 一 万 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24038', '40', '25', '29', '因 为 凡 有 的 ， 还 要 加 给 他 ， 叫 他 有 余 ； 没 有 的 ， 连 他 所 有 的 也 要 夺 过 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24039', '40', '25', '30', '把 这 无 用 的 仆 人 丢 在 外 面 黑 暗 里 ； 在 那 里 必 要 哀 哭 切 齿 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24040', '40', '25', '31', '＜ 万 民 受 审 判 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24041', '40', '25', '32', '万 民 都 要 聚 集 在 他 面 前 。 他 要 把 他 们 分 别 出 来 ， 好 像 牧 羊 的 分 别 绵 羊 山 羊 一 般 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24042', '40', '25', '33', '把 绵 羊 安 置 在 右 边 ， 山 羊 在 左 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24043', '40', '25', '34', '于 是 王 要 向 那 右 边 的 说 ： ‘ 你 们 这 蒙 我 父 赐 福 的 ， 可 来 承 受 那 创 世 以 来 为 你 们 所 预 备 的 国 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24044', '40', '25', '35', '因 为 我 饿 了 ， 你 们 给 我 吃 ， 渴 了 ， 你 们 给 我 喝 ； 我 作 客 旅 ， 你 们 留 我 住 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24045', '40', '25', '36', '我 赤 身 露 体 ， 你 们 给 我 穿 ； 我 病 了 ， 你 们 看 顾 我 ； 我 在 监 里 ， 你 们 来 看 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24046', '40', '25', '37', '义 人 就 回 答 说 ： ‘ 主 啊 ， 我 们 什 么 时 候 见 你 饿 了 ， 给 你 吃 ， 渴 了 ， 给 你 喝 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24047', '40', '25', '38', '什 么 时 候 见 你 作 客 旅 ， 留 你 住 ， 或 是 赤 身 露 体 ， 给 你 穿 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24048', '40', '25', '39', '又 什 么 时 候 见 你 病 了 ， 或 是 在 监 里 ， 来 看 你 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24049', '40', '25', '40', '王 要 回 答 说 ： ‘ 我 实 在 告 诉 你 们 ， 这 些 事 你 们 既 做 在 我 这 弟 兄 中 一 个 最 小 的 身 上 ， 就 是 做 在 我 身 上 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24050', '40', '25', '41', '王 又 要 向 那 左 边 的 说 ： ‘ 你 们 这 被 咒 诅 的 人 ， 离 开 我 ！ 进 入 那 为 魔 鬼 和 他 的 使 者 所 预 备 的 永 火 里 去 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24051', '40', '25', '42', '因 为 我 饿 了 ， 你 们 不 给 我 吃 ， 渴 了 ， 你 们 不 给 我 喝 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24052', '40', '25', '43', '我 作 客 旅 ， 你 们 不 留 我 住 ； 我 赤 身 露 体 ， 你 们 不 给 我 穿 ； 我 病 了 ， 我 在 监 里 ， 你 们 不 来 看 顾 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24053', '40', '25', '44', '他 们 也 要 回 答 说 ： ‘ 主 啊 ， 我 们 什 么 时 候 见 你 饿 了 ， 或 渴 了 ， 或 作 客 旅 ， 或 赤 身 露 体 ， 或 病 了 ， 或 在 监 里 ， 不 伺 候 你 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24054', '40', '25', '45', '王 要 回 答 说 ： ‘ 我 实 在 告 诉 你 们 ， 这 些 事 你 们 既 不 做 在 我 这 弟 兄 中 一 个 最 小 的 身 上 ， 就 是 不 做 在 我 身 上 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24055', '40', '25', '46', '这 些 人 要 往 永 刑 里 去 ； 那 些 义 人 要 往 永 生 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24056', '40', '26', '1', '＜ 杀 害 耶 稣 的 阴 谋 （ 可   1 4 : 1 - 2 ； 路   2 2 : 1 - 2 ； 约   1 1 : 4 5 - 5 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24057', '40', '26', '2', '“ 你 们 知 道 ， 过 两 天 是 逾 越 节 ， 人 子 将 要 被 交 给 人 ， 钉 在 十 字 架 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24058', '40', '26', '3', '那 时 ， 祭 司 长 和 民 间 的 长 老 聚 集 在 大 祭 司 称 为 该 亚 法 的 院 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24059', '40', '26', '4', '大 家 商 议 要 用 诡 计 拿 住 耶 稣 ， 杀 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24060', '40', '26', '5', '只 是 说 ： “ 当 节 的 日 子 不 可 ， 恐 怕 民 间 生 乱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24061', '40', '26', '6', '＜ 在 伯 大 尼 受 膏 （ 可   1 4 : 3 - 9 ； 约   1 2 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24062', '40', '26', '7', '有 一 个 女 人 拿 着 一 玉 瓶 极 贵 的 香 膏 来 ， 趁 耶 稣 坐 席 的 时 候 ， 浇 在 他 的 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24063', '40', '26', '8', '门 徒 看 见 就 很 不 喜 悦 ， 说 ： “ 何 用 这 样 的 枉 费 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24064', '40', '26', '9', '这 香 膏 可 以 卖 许 多 钱 ， 赒 济 穷 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24065', '40', '26', '10', '耶 稣 看 出 他 们 的 意 思 ， 就 说 ： “ 为 什 么 难 为 这 女 人 呢 ？ 她 在 我 身 上 做 的 是 一 件 美 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24066', '40', '26', '11', '因 为 常 有 穷 人 和 你 们 同 在 ； 只 是 你 们 不 常 有 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24067', '40', '26', '12', '她 将 这 香 膏 浇 在 我 身 上 是 为 我 安 葬 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24068', '40', '26', '13', '我 实 在 告 诉 你 们 ， 普 天 之 下 ， 无 论 在 什 么 地 方 传 这 福 音 ， 也 要 述 说 这 女 人 所 行 的 ， 作 个 纪 念 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24069', '40', '26', '14', '＜ 犹 大 出 卖 耶 稣 （ 可   1 4 : 1 0 - 1 1 ； 路   2 2 : 3 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24070', '40', '26', '15', '“ 我 把 他 交 给 你 们 ， 你 们 愿 意 给 我 多 少 钱 ？ ” 他 们 就 给 了 他 三 十 块 钱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24071', '40', '26', '16', '从 那 时 候 ， 他 就 找 机 会 要 把 耶 稣 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24072', '40', '26', '17', '＜ 和 门 徒 同 度 逾 越 节 （ 可   1 4 : 1 2 - 2 1 ； 路   2 2 : 7 - 1 4 , 2 1 - 2 3 ； 约   1 3 : 2 1 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24073', '40', '26', '18', '耶 稣 说 ： “ 你 们 进 城 去 ， 到 某 人 那 里 ， 对 他 说 ： ‘ 夫 子 说 ： 我 的 时 候 快 到 了 ， 我 与 门 徒 要 在 你 家 里 守 逾 越 节 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24074', '40', '26', '19', '门 徒 遵 着 耶 稣 所 吩 咐 的 就 去 预 备 了 逾 越 节 的 筵 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24075', '40', '26', '20', '到 了 晚 上 ， 耶 稣 和 十 二 个 门 徒 坐 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24076', '40', '26', '21', '正 吃 的 时 候 ， 耶 稣 说 ： “ 我 实 在 告 诉 你 们 ， 你 们 中 间 有 一 个 人 要 卖 我 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24077', '40', '26', '22', '他 们 就 甚 忧 愁 ， 一 个 一 个 地 问 他 说 ： “ 主 ， 是 我 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24078', '40', '26', '23', '耶 稣 回 答 说 ： “ 同 我 蘸 手 在 盘 子 里 的 ， 就 是 他 要 卖 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24079', '40', '26', '24', '人 子 必 要 去 世 ， 正 如 经 上 指 着 他 所 写 的 ； 但 卖 人 子 的 人 有 祸 了 ！ 那 人 不 生 在 世 上 倒 好 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24080', '40', '26', '25', '卖 耶 稣 的 犹 大 问 他 说 ： “ 拉 比 ， 是 我 吗 ？ ” 耶 稣 说 ： “ 你 说 的 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24081', '40', '26', '26', '＜ 设 立 主 的 晚 餐 （ 可   1 4 : 2 2 - 2 6 ； 路   2 2 : 1 5 - 2 0 ； 林 前   1 1 : 2 3 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24082', '40', '26', '27', '又 拿 起 杯 来 ， 祝 谢 了 ， 递 给 他 们 ， 说 ： “ 你 们 都 喝 这 个 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24083', '40', '26', '28', '因 为 这 是 我 立 约 的 血 ， 为 多 人 流 出 来 ， 使 罪 得 赦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24084', '40', '26', '29', '但 我 告 诉 你 们 ， 从 今 以 后 ， 我 不 再 喝 这 葡 萄 汁 ， 直 到 我 在 我 父 的 国 里 同 你 们 喝 新 的 那 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24085', '40', '26', '30', '他 们 唱 了 诗 ， 就 出 来 往 橄 榄 山 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24086', '40', '26', '31', '＜ 预 言 彼 得 不 认 主 （ 可   1 4 : 2 7 - 3 1 ； 路   2 2 : 3 1 - 3 4 ； 约   1 3 : 3 6 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24087', '40', '26', '32', '但 我 复 活 以 后 ， 要 在 你 们 以 先 往 加 利 利 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24088', '40', '26', '33', '彼 得 说 ： “ 众 人 虽 然 为 你 的 缘 故 跌 倒 ， 我 却 永 不 跌 倒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24089', '40', '26', '34', '耶 稣 说 ： “ 我 实 在 告 诉 你 ， 今 夜 鸡 叫 以 先 ， 你 要 三 次 不 认 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24090', '40', '26', '35', '彼 得 说 ： “ 我 就 是 必 须 和 你 同 死 ， 也 总 不 能 不 认 你 。 ” 众 门 徒 都 是 这 样 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24091', '40', '26', '36', '＜ 在 客 西 马 尼 祷 告 （ 可   1 4 : 3 2 - 4 2 ； 路   2 2 : 3 9 - 4 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24092', '40', '26', '37', '于 是 带 着 彼 得 和 西 庇 太 的 两 个 儿 子 同 去 ， 就 忧 愁 起 来 ， 极 其 难 过 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24093', '40', '26', '38', '便 对 他 们 说 ： “ 我 心 里 甚 是 忧 伤 ， 几 乎 要 死 ； 你 们 在 这 里 等 候 ， 和 我 一 同 警 醒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24094', '40', '26', '39', '他 就 稍 往 前 走 ， 俯 伏 在 地 ， 祷 告 说 ： “ 我 父 啊 ， 倘 若 可 行 ， 求 你 叫 这 杯 离 开 我 。 然 而 ， 不 要 照 我 的 意 思 ， 只 要 照 你 的 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24095', '40', '26', '40', '来 到 门 徒 那 里 ， 见 他 们 睡 着 了 ， 就 对 彼 得 说 ： “ 怎 么 样 ？ 你 们 不 能 同 我 警 醒 片 时 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24096', '40', '26', '41', '总 要 警 醒 祷 告 ， 免 得 入 了 迷 惑 。 你 们 心 灵 固 然 愿 意 ， 肉 体 却 软 弱 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24097', '40', '26', '42', '第 二 次 又 去 祷 告 说 ： “ 我 父 啊 ， 这 杯 若 不 能 离 开 我 ， 必 要 我 喝 ， 就 愿 你 的 意 旨 成 全 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24098', '40', '26', '43', '又 来 ， 见 他 们 睡 着 了 ， 因 为 他 们 的 眼 睛 困 倦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24099', '40', '26', '44', '耶 稣 又 离 开 他 们 去 了 。 第 三 次 祷 告 ， 说 的 话 还 是 与 先 前 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24100', '40', '26', '45', '于 是 来 到 门 徒 那 里 ， 对 他 们 说 ： “ 现 在 你 们 仍 然 睡 觉 安 歇 吧 ｛ 吧 ： 或 译 吗 ？ ｝ ！ 时 候 到 了 ， 人 子 被 卖 在 罪 人 手 里 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24101', '40', '26', '46', '起 来 ！ 我 们 走 吧 。 看 哪 ， 卖 我 的 人 近 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24102', '40', '26', '47', '＜ 耶 稣 被 捕 （ 可   1 4 : 4 3 - 5 0 ； 路   2 2 : 4 7 - 5 3 ； 约   1 8 : 3 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24103', '40', '26', '48', '那 卖 耶 稣 的 给 了 他 们 一 个 暗 号 ， 说 ： “ 我 与 谁 亲 嘴 ， 谁 就 是 他 。 你 们 可 以 拿 住 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24104', '40', '26', '49', '犹 大 随 即 到 耶 稣 跟 前 ， 说 ： “ 请 拉 比 安 ” ， 就 与 他 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24105', '40', '26', '50', '耶 稣 对 他 说 ： “ 朋 友 ， 你 来 要 做 的 事 ， 就 做 吧 。 ” 于 是 那 些 人 上 前 ， 下 手 拿 住 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24106', '40', '26', '51', '有 跟 随 耶 稣 的 一 个 人 伸 手 拔 出 刀 来 ， 将 大 祭 司 的 仆 人 砍 了 一 刀 ， 削 掉 了 他 一 个 耳 朵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24107', '40', '26', '52', '耶 稣 对 他 说 ： “ 收 刀 入 鞘 吧 ！ 凡 动 刀 的 ， 必 死 在 刀 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24108', '40', '26', '53', '你 想 ， 我 不 能 求 我 父 现 在 为 我 差 遣 十 二 营 多 天 使 来 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24109', '40', '26', '54', '若 是 这 样 ， 经 上 所 说 ， 事 情 必 须 如 此 的 话 怎 么 应 验 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24110', '40', '26', '55', '当 时 ， 耶 稣 对 众 人 说 ： “ 你 们 带 着 刀 棒 出 来 拿 我 ， 如 同 拿 强 盗 吗 ？ 我 天 天 坐 在 殿 里 教 训 人 ， 你 们 并 没 有 拿 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24111', '40', '26', '56', '但 这 一 切 的 事 成 就 了 ， 为 要 应 验 先 知 书 上 的 话 。 ” 当 下 ， 门 徒 都 离 开 他 逃 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24112', '40', '26', '57', '＜ 耶 稣 在 公 会 里 受 审 （ 可   1 4 : 5 3 - 6 5 ； 路   2 2 : 5 4 - 5 5 , 6 3 - 7 1 ； 约   1 8 : 1 3 - 1 4 , 1 9 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24113', '40', '26', '58', '彼 得 远 远 地 跟 着 耶 稣 ， 直 到 大 祭 司 的 院 子 ， 进 到 里 面 ， 就 和 差 役 同 坐 ， 要 看 这 事 到 底 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24114', '40', '26', '59', '祭 司 长 和 全 公 会 寻 找 假 见 证 控 告 耶 稣 ， 要 治 死 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24115', '40', '26', '60', '虽 有 好 些 人 来 作 假 见 证 ， 总 得 不 着 实 据 。 末 后 有 两 个 人 前 来 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24116', '40', '26', '61', '“ 这 个 人 曾 说 ： ‘ 我 能 拆 毁 神 的 殿 ， 三 日 内 又 建 造 起 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24117', '40', '26', '62', '大 祭 司 就 站 起 来 ， 对 耶 稣 说 ： “ 你 什 么 都 不 回 答 吗 ？ 这 些 人 作 见 证 告 你 的 是 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24118', '40', '26', '63', '耶 稣 却 不 言 语 。 大 祭 司 对 他 说 ： “ 我 指 着 永 生 神 叫 你 起 誓 告 诉 我 们 ， 你 是 神 的 儿 子 基 督 不 是 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24119', '40', '26', '64', '耶 稣 对 他 说 ： “ 你 说 的 是 。 然 而 ， 我 告 诉 你 们 ， 后 来 你 们 要 看 见 人 子 坐 在 那 权 能 者 的 右 边 ， 驾 着 天 上 的 云 降 临 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24120', '40', '26', '65', '大 祭 司 就 撕 开 衣 服 ， 说 ： “ 他 说 了 僭 妄 的 话 ， 我 们 何 必 再 用 见 证 人 呢 ？ 这 僭 妄 的 话 ， 现 在 你 们 都 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24121', '40', '26', '66', '你 们 的 意 见 如 何 ？ ” 他 们 回 答 说 ： “ 他 是 该 死 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24122', '40', '26', '67', '他 们 就 吐 唾 沫 在 他 脸 上 ， 用 拳 头 打 他 ； 也 有 用 手 掌 打 他 的 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24123', '40', '26', '68', '“ 基 督 啊 ！ 你 是 先 知 ， 告 诉 我 们 打 你 的 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24124', '40', '26', '69', '＜ 彼 得 三 次 不 认 主 （ 可   1 4 : 6 6 - 7 2 ； 路   2 2 : 5 6 - 6 2 ； 约   1 8 : 1 5 - 1 8 , 2 5 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24125', '40', '26', '70', '彼 得 在 众 人 面 前 却 不 承 认 ， 说 ： “ 我 不 知 道 你 说 的 是 什 么 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24126', '40', '26', '71', '既 出 去 ， 到 了 门 口 ， 又 有 一 个 使 女 看 见 他 ， 就 对 那 里 的 人 说 ： “ 这 个 人 也 是 同 拿 撒 勒 人 耶 稣 一 伙 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24127', '40', '26', '72', '彼 得 又 不 承 认 ， 并 且 起 誓 说 ： “ 我 不 认 得 那 个 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24128', '40', '26', '73', '过 了 不 多 的 时 候 ， 旁 边 站 着 的 人 前 来 ， 对 彼 得 说 ： “ 你 真 是 他 们 一 党 的 ， 你 的 口 音 把 你 露 出 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24129', '40', '26', '74', '彼 得 就 发 咒 起 誓 地 说 ： “ 我 不 认 得 那 个 人 。 ” 立 时 ， 鸡 就 叫 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24130', '40', '26', '75', '彼 得 想 起 耶 稣 所 说 的 话 ： “ 鸡 叫 以 先 ， 你 要 三 次 不 认 我 。 ” 他 就 出 去 痛 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24131', '40', '27', '1', '＜ 耶 稣 被 交 给 彼 拉 多 （ 可   1 5 : 1 ； 路   2 3 : 1 - 2 ； 约   1 8 : 2 8 - 3 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24132', '40', '27', '2', '就 把 他 捆 绑 ， 解 去 ， 交 给 巡 抚 彼 拉 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24133', '40', '27', '3', '＜ 犹 大 的 死 （ 徒   1 : 1 8 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24134', '40', '27', '4', '“ 我 卖 了 无 辜 之 人 的 血 是 有 罪 了 。 ” 他 们 说 ： “ 那 与 我 们 有 什 么 相 干 ？ 你 自 己 承 当 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24135', '40', '27', '5', '犹 大 就 把 那 银 钱 丢 在 殿 里 ， 出 去 吊 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24136', '40', '27', '6', '祭 司 长 拾 起 银 钱 来 ， 说 ： “ 这 是 血 价 ， 不 可 放 在 库 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24137', '40', '27', '7', '他 们 商 议 ， 就 用 那 银 钱 买 了 窑 户 的 一 块 田 ， 为 要 埋 葬 外 乡 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24138', '40', '27', '8', '所 以 那 块 田 直 到 今 日 还 叫 做 “ 血 田 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24139', '40', '27', '9', '这 就 应 了 先 知 耶 利 米 的 话 ， 说 ： “ 他 们 用 那 三 十 块 钱 ， 就 是 被 估 定 之 人 的 价 钱 ， 是 以 色 列 人 中 所 估 定 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24140', '40', '27', '10', '买 了 窑 户 的 一 块 田 ； 这 是 照 着 主 所 吩 咐 我 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24141', '40', '27', '11', '＜ 耶 稣 在 彼 拉 多 面 前 受 审 （ 可   1 5 : 2 - 5 ； 路   2 3 : 3 - 5 ； 约   1 8 : 3 3 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24142', '40', '27', '12', '他 被 祭 司 长 和 长 老 控 告 的 时 候 ， 什 么 都 不 回 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24143', '40', '27', '13', '彼 拉 多 就 对 他 说 ： “ 他 们 作 见 证 告 你 这 么 多 的 事 ， 你 没 有 听 见 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24144', '40', '27', '14', '耶 稣 仍 不 回 答 ， 连 一 句 话 也 不 说 ， 以 致 巡 抚 甚 觉 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24145', '40', '27', '15', '＜ 耶 稣 被 判 死 刑 （ 可   1 5 : 6 - 1 5 ； 路   2 3 : 1 3 - 2 5 ； 约   1 8 : 3 9 - 1 9 : 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24146', '40', '27', '16', '当 时 有 一 个 出 名 的 囚 犯 叫 巴 拉 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24147', '40', '27', '17', '众 人 聚 集 的 时 候 ， 彼 拉 多 就 对 他 们 说 ： “ 你 们 要 我 释 放 哪 一 个 给 你 们 ？ 是 巴 拉 巴 呢 ？ 是 称 为 基 督 的 耶 稣 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24148', '40', '27', '18', '巡 抚 原 知 道 他 们 是 因 为 嫉 妒 才 把 他 解 了 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24149', '40', '27', '19', '正 坐 堂 的 时 候 ， 他 的 夫 人 打 发 人 来 说 ： “ 这 义 人 的 事 ， 你 一 点 不 可 管 ， 因 为 我 今 天 在 梦 中 为 他 受 了 许 多 的 苦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24150', '40', '27', '20', '祭 司 长 和 长 老 挑 唆 众 人 ， 求 释 放 巴 拉 巴 ， 除 灭 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24151', '40', '27', '21', '巡 抚 对 众 人 说 ： “ 这 两 个 人 ， 你 们 要 我 释 放 哪 一 个 给 你 们 呢 ？ ” 他 们 说 ： “ 巴 拉 巴 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24152', '40', '27', '22', '彼 拉 多 说 ： “ 这 样 ， 那 称 为 基 督 的 耶 稣 我 怎 么 办 他 呢 ？ ” 他 们 都 说 ： “ 把 他 钉 十 字 架 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24153', '40', '27', '23', '巡 抚 说 ： “ 为 什 么 呢 ？ 他 做 了 什 么 恶 事 呢 ？ ” 他 们 便 极 力 地 喊 着 说 ： “ 把 他 钉 十 字 架 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24154', '40', '27', '24', '彼 拉 多 见 说 也 无 济 于 事 ， 反 要 生 乱 ， 就 拿 水 在 众 人 面 前 洗 手 ， 说 ： “ 流 这 义 人 的 血 ， 罪 不 在 我 ， 你 们 承 当 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24155', '40', '27', '25', '众 人 都 回 答 说 ： “ 他 的 血 归 到 我 们 和 我 们 的 子 孙 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24156', '40', '27', '26', '于 是 彼 拉 多 释 放 巴 拉 巴 给 他 们 ， 把 耶 稣 鞭 打 了 ， 交 给 人 钉 十 字 架 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24157', '40', '27', '27', '＜ 兵 丁 戏 弄 耶 稣 （ 可   1 5 : 1 6 - 2 0 ； 约   1 9 : 2 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24158', '40', '27', '28', '他 们 给 他 脱 了 衣 服 ， 穿 上 一 件 朱 红 色 袍 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24159', '40', '27', '29', '用 荆 棘 编 做 冠 冕 ， 戴 在 他 头 上 ， 拿 一 根 苇 子 放 在 他 右 手 里 ， 跪 在 他 面 前 ， 戏 弄 他 ， 说 ： “ 恭 喜 ， 犹 太 人 的 王 啊 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24160', '40', '27', '30', '又 吐 唾 沫 在 他 脸 上 ， 拿 苇 子 打 他 的 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24161', '40', '27', '31', '戏 弄 完 了 ， 就 给 他 脱 了 袍 子 ， 仍 穿 上 他 自 己 的 衣 服 ， 带 他 出 去 ， 要 钉 十 字 架 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24162', '40', '27', '32', '＜ 耶 稣 被 钉 十 字 架 （ 可   1 5 : 2 1 - 3 2 ； 路   2 3 : 2 6 - 4 3 ； 约   1 9 : 1 7 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24163', '40', '27', '33', '到 了 一 个 地 方 名 叫 各 各 他 ， 意 思 就 是 “ 髑 髅 地 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24164', '40', '27', '34', '兵 丁 拿 苦 胆 调 和 的 酒 给 耶 稣 喝 。 他 尝 了 ， 就 不 肯 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24165', '40', '27', '35', '他 们 既 将 他 钉 在 十 字 架 上 ， 就 拈 阄 分 他 的 衣 服 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24166', '40', '27', '36', '又 坐 在 那 里 看 守 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24167', '40', '27', '37', '在 他 头 以 上 安 一 个 牌 子 ， 写 着 他 的 罪 状 ， 说 ： “ 这 是 犹 太 人 的 王 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24168', '40', '27', '38', '当 时 ， 有 两 个 强 盗 和 他 同 钉 十 字 架 ， 一 个 在 右 边 ， 一 个 在 左 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24169', '40', '27', '39', '从 那 里 经 过 的 人 讥 诮 他 ， 摇 着 头 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24170', '40', '27', '40', '“ 你 这 拆 毁 圣 殿 、 三 日 又 建 造 起 来 的 ， 可 以 救 自 己 吧 ！ 你 如 果 是 神 的 儿 子 ， 就 从 十 字 架 上 下 来 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24171', '40', '27', '41', '祭 司 长 和 文 士 并 长 老 也 是 这 样 戏 弄 他 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24172', '40', '27', '42', '“ 他 救 了 别 人 ， 不 能 救 自 己 。 他 是 以 色 列 的 王 ， 现 在 可 以 从 十 字 架 上 下 来 ， 我 们 就 信 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24173', '40', '27', '43', '他 倚 靠 神 ， 神 若 喜 悦 他 ， 现 在 可 以 救 他 ； 因 为 他 曾 说 ： ‘ 我 是 神 的 儿 子 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24174', '40', '27', '44', '那 和 他 同 钉 的 强 盗 也 是 这 样 地 讥 诮 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24175', '40', '27', '45', '＜ 耶 稣 的 死 （ 可   1 5 : 3 3 - 4 1 ； 路   2 3 : 4 4 - 4 9 ； 约   1 9 : 2 8 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24176', '40', '27', '46', '约 在 申 初 ， 耶 稣 大 声 喊 着 说 ： “ 以 利 ！ 以 利 ！ 拉 马 撒 巴 各 大 尼 ？ ” 就 是 说 ： “ 我 的 神 ！ 我 的 神 ！ 为 什 么 离 弃 我 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24177', '40', '27', '47', '站 在 那 里 的 人 ， 有 的 听 见 就 说 ： “ 这 个 人 呼 叫 以 利 亚 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24178', '40', '27', '48', '内 中 有 一 个 人 赶 紧 跑 去 ， 拿 海 绒 蘸 满 了 醋 ， 绑 在 苇 子 上 ， 送 给 他 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24179', '40', '27', '49', '其 余 的 人 说 ： “ 且 等 着 ， 看 以 利 亚 来 救 他 不 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24180', '40', '27', '50', '耶 稣 又 大 声 喊 叫 ， 气 就 断 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24181', '40', '27', '51', '忽 然 ， 殿 里 的 幔 子 从 上 到 下 裂 为 两 半 ， 地 也 震 动 ， 磐 石 也 崩 裂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24182', '40', '27', '52', '坟 墓 也 开 了 ， 已 睡 圣 徒 的 身 体 多 有 起 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24183', '40', '27', '53', '到 耶 稣 复 活 以 后 ， 他 们 从 坟 墓 里 出 来 ， 进 了 圣 城 ， 向 许 多 人 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24184', '40', '27', '54', '百 夫 长 和 一 同 看 守 耶 稣 的 人 看 见 地 震 并 所 经 历 的 事 ， 就 极 其 害 怕 ， 说 ： “ 这 真 是 神 的 儿 子 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24185', '40', '27', '55', '有 好 些 妇 女 在 那 里 ， 远 远 地 观 看 ； 她 们 是 从 加 利 利 跟 随 耶 稣 来 服 事 他 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24186', '40', '27', '56', '内 中 有 抹 大 拉 的 马 利 亚 ， 又 有 雅 各 和 约 西 的 母 亲 马 利 亚 ， 并 有 西 庇 太 两 个 儿 子 的 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24187', '40', '27', '57', '＜ 耶 稣 的 安 葬 （ 可   1 5 : 4 2 - 4 7 ； 路   2 3 : 5 0 - 5 6 ； 约   1 9 : 3 8 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24188', '40', '27', '58', '这 人 去 见 彼 拉 多 ， 求 耶 稣 的 身 体 ； 彼 拉 多 就 吩 咐 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24189', '40', '27', '59', '约 瑟 取 了 身 体 ， 用 干 净 细 麻 布 裹 好 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24190', '40', '27', '60', '安 放 在 自 己 的 新 坟 墓 里 ， 就 是 他 凿 在 磐 石 里 的 。 他 又 把 大 石 头 滚 到 墓 门 口 ， 就 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24191', '40', '27', '61', '有 抹 大 拉 的 马 利 亚 和 那 个 马 利 亚 在 那 里 ， 对 着 坟 墓 坐 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24192', '40', '27', '62', '＜ 封 石 妥 守 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24193', '40', '27', '63', '“ 大 人 ， 我 们 记 得 那 诱 惑 人 的 还 活 着 的 时 候 曾 说 ： ‘ 三 日 后 我 要 复 活 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24194', '40', '27', '64', '因 此 ， 请 吩 咐 人 将 坟 墓 把 守 妥 当 ， 直 到 第 三 日 ， 恐 怕 他 的 门 徒 来 ， 把 他 偷 了 去 ， 就 告 诉 百 姓 说 ： ‘ 他 从 死 里 复 活 了 。 ’ 这 样 ， 那 后 来 的 迷 惑 比 先 前 的 更 利 害 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24195', '40', '27', '65', '彼 拉 多 说 ： “ 你 们 有 看 守 的 兵 ， 去 吧 ！ 尽 你 们 所 能 的 把 守 妥 当 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24196', '40', '27', '66', '他 们 就 带 着 看 守 的 兵 同 去 ， 封 了 石 头 ， 将 坟 墓 把 守 妥 当 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24197', '40', '28', '1', '＜ 耶 稣 复 活 （ 可   1 6 : 1 - 1 0 ； 路   2 4 : 1 - 1 2 ； 约   2 0 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24198', '40', '28', '2', '忽 然 ， 地 大 震 动 ； 因 为 有 主 的 使 者 从 天 上 下 来 ， 把 石 头 滚 开 ， 坐 在 上 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24199', '40', '28', '3', '他 的 像 貌 如 同 闪 电 ， 衣 服 洁 白 如 雪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24200', '40', '28', '4', '看 守 的 人 就 因 他 吓 得 浑 身 乱 战 ， 甚 至 和 死 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24201', '40', '28', '5', '天 使 对 妇 女 说 ： “ 不 要 害 怕 ！ 我 知 道 你 们 是 寻 找 那 钉 十 字 架 的 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24202', '40', '28', '6', '他 不 在 这 里 ， 照 他 所 说 的 ， 已 经 复 活 了 。 你 们 来 看 安 放 主 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24203', '40', '28', '7', '快 去 告 诉 他 的 门 徒 ， 说 他 从 死 里 复 活 了 ， 并 且 在 你 们 以 先 往 加 利 利 去 ， 在 那 里 你 们 要 见 他 。 看 哪 ， 我 已 经 告 诉 你 们 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24204', '40', '28', '8', '妇 女 们 就 急 忙 离 开 坟 墓 ， 又 害 怕 ， 又 大 大 地 欢 喜 ， 跑 去 要 报 给 他 的 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24205', '40', '28', '9', '忽 然 ， 耶 稣 遇 见 她 们 ， 说 ： “ 愿 你 们 平 安 ！ ” 她 们 就 上 前 抱 住 他 的 脚 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24206', '40', '28', '10', '耶 稣 对 她 们 说 ： “ 不 要 害 怕 ！ 你 们 去 告 诉 我 的 弟 兄 ， 叫 他 们 往 加 利 利 去 ， 在 那 里 必 见 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24207', '40', '28', '11', '＜ 看 守 的 兵 报 告 祭 司 长 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24208', '40', '28', '12', '祭 司 长 和 长 老 聚 集 商 议 ， 就 拿 许 多 银 钱 给 兵 丁 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24209', '40', '28', '13', '“ 你 们 要 这 样 说 ： ‘ 夜 间 我 们 睡 觉 的 时 候 ， 他 的 门 徒 来 ， 把 他 偷 去 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24210', '40', '28', '14', '倘 若 这 话 被 巡 抚 听 见 ， 有 我 们 劝 他 ， 保 你 们 无 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24211', '40', '28', '15', '兵 丁 受 了 银 钱 ， 就 照 所 嘱 咐 他 们 的 去 行 。 这 话 就 传 说 在 犹 太 人 中 间 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24212', '40', '28', '16', '＜ 门 徒 奉 差 遣 （ 可   1 6 : 1 4 - 1 8 ； 路   2 4 : 3 6 - 4 9 ； 约   2 0 : 1 9 - 2 3 ； 徒   1 : 6 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24213', '40', '28', '17', '他 们 见 了 耶 稣 就 拜 他 ， 然 而 还 有 人 疑 惑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24214', '40', '28', '18', '耶 稣 进 前 来 ， 对 他 们 说 ： “ 天 上 地 下 所 有 的 权 柄 都 赐 给 我 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24215', '40', '28', '19', '所 以 ， 你 们 要 去 ， 使 万 民 作 我 的 门 徒 ， 奉 父 、 子 、 圣 灵 的 名 给 他 们 施 洗 ｛ 或 译 ： 给 他 们 施 洗 ， 归 于 父 、 子 、 圣 灵 的 名 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24216', '40', '28', '20', '凡 我 所 吩 咐 你 们 的 ， 都 教 训 他 们 遵 守 ， 我 就 常 与 你 们 同 在 ， 直 到 世 界 的 末 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24217', '41', '1', '1', '＜ 施 洗 约 翰 传 道 （ 太   3 : 1 - 1 2 ； 路   3 : 1 - 1 8 ； 约   1 : 1 9 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24218', '41', '1', '2', '正 如 先 知 以 赛 亚 ｛ 有 古 卷 没 有 以 赛 亚 三 个 字 ｝ 书 上 记 着 说 ： 看 哪 ， 我 要 差 遣 我 的 使 者 在 你 前 面 ， 预 备 道 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24219', '41', '1', '3', '在 旷 野 有 人 声 喊 着 说 ： 预 备 主 的 道 ， 修 直 他 的 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24220', '41', '1', '4', '照 这 话 ， 约 翰 来 了 ， 在 旷 野 施 洗 ， 传 悔 改 的 洗 礼 ， 使 罪 得 赦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24221', '41', '1', '5', '犹 太 全 地 和 耶 路 撒 冷 的 人 都 出 去 到 约 翰 那 里 ， 承 认 他 们 的 罪 ， 在 约 旦 河 里 受 他 的 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24222', '41', '1', '6', '约 翰 穿 骆 驼 毛 的 衣 服 ， 腰 束 皮 带 ， 吃 的 是 蝗 虫 、 野 蜜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24223', '41', '1', '7', '他 传 道 说 ： “ 有 一 位 在 我 以 后 来 的 ， 能 力 比 我 更 大 ， 我 就 是 弯 腰 给 他 解 鞋 带 也 是 不 配 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24224', '41', '1', '8', '我 是 用 水 给 你 们 施 洗 ， 他 却 要 用 圣 灵 给 你 们 施 洗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24225', '41', '1', '9', '＜ 耶 稣 受 洗 （ 太   3 : 1 3 - 1 7 ； 路   3 : 2 1 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24226', '41', '1', '10', '他 从 水 里 一 上 来 ， 就 看 见 天 裂 开 了 ， 圣 灵 仿 佛 鸽 子 ， 降 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24227', '41', '1', '11', '又 有 声 音 从 天 上 来 ， 说 ： “ 你 是 我 的 爱 子 ， 我 喜 悦 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24228', '41', '1', '12', '＜ 耶 稣 受 试 探 （ 太   4 : 1 - 1 1 ； 路   4 : 1 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24229', '41', '1', '13', '他 在 旷 野 四 十 天 ， 受 撒 但 的 试 探 ， 并 与 野 兽 同 在 一 处 ， 且 有 天 使 来 伺 候 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24230', '41', '1', '14', '＜ 开 始 在 加 利 利 传 道 （ 太   4 : 1 2 - 1 7 ； 路   4 : 1 4 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24231', '41', '1', '15', '说 ： “ 日 期 满 了 ， 神 的 国 近 了 。 你 们 当 悔 改 ， 信 福 音 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24232', '41', '1', '16', '＜ 呼 召 四 个 渔 夫 （ 太   4 : 1 8 - 2 2 ； 路   5 : 1 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24233', '41', '1', '17', '耶 稣 对 他 们 说 ： “ 来 跟 从 我 ， 我 要 叫 你 们 得 人 如 得 鱼 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24234', '41', '1', '18', '他 们 就 立 刻 舍 了 网 ， 跟 从 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24235', '41', '1', '19', '耶 稣 稍 往 前 走 ， 又 见 西 庇 太 的 儿 子 雅 各 和 雅 各 的 兄 弟 约 翰 在 船 上 补 网 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24236', '41', '1', '20', '耶 稣 随 即 招 呼 他 们 ， 他 们 就 把 父 亲 西 庇 太 和 雇 工 人 留 在 船 上 ， 跟 从 耶 稣 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24237', '41', '1', '21', '＜ 一 个 污 鬼 附 身 的 人 （ 路   4 : 3 1 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24238', '41', '1', '22', '众 人 很 希 奇 他 的 教 训 ； 因 为 他 教 训 他 们 ， 正 像 有 权 柄 的 人 ， 不 像 文 士 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24239', '41', '1', '23', '在 会 堂 里 ， 有 一 个 人 被 污 鬼 附 着 。 他 喊 叫 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24240', '41', '1', '24', '“ 拿 撒 勒 人 耶 稣 ， 我 们 与 你 有 什 么 相 干 ？ 你 来 灭 我 们 吗 ？ 我 知 道 你 是 谁 ， 乃 是 神 的 圣 者 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24241', '41', '1', '25', '耶 稣 责 备 他 说 ： “ 不 要 作 声 ！ 从 这 人 身 上 出 来 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24242', '41', '1', '26', '污 鬼 叫 那 人 抽 了 一 阵 疯 ， 大 声 喊 叫 ， 就 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24243', '41', '1', '27', '众 人 都 惊 讶 ， 以 致 彼 此 对 问 说 ： “ 这 是 什 么 事 ？ 是 个 新 道 理 啊 ！ 他 用 权 柄 吩 咐 污 鬼 ， 连 污 鬼 也 听 从 了 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24244', '41', '1', '28', '耶 稣 的 名 声 就 传 遍 了 加 利 利 的 四 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24245', '41', '1', '29', '＜ 治 好 许 多 病 人 （ 太   8 : 1 4 - 1 7 ； 路   4 : 3 8 - 4 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24246', '41', '1', '30', '西 门 的 岳 母 正 害 热 病 躺 着 ， 就 有 人 告 诉 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24247', '41', '1', '31', '耶 稣 进 前 拉 着 她 的 手 ， 扶 她 起 来 ， 热 就 退 了 ， 她 就 服 事 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24248', '41', '1', '32', '天 晚 日 落 的 时 候 ， 有 人 带 着 一 切 害 病 的 ， 和 被 鬼 附 的 ， 来 到 耶 稣 跟 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24249', '41', '1', '33', '合 城 的 人 都 聚 集 在 门 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24250', '41', '1', '34', '耶 稣 治 好 了 许 多 害 各 样 病 的 人 ， 又 赶 出 许 多 鬼 ， 不 许 鬼 说 话 ， 因 为 鬼 认 识 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24251', '41', '1', '35', '＜ 在 加 利 利 各 会 堂 传 道 （ 路   4 : 4 2 - 4 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24252', '41', '1', '36', '西 门 和 同 伴 追 了 他 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24253', '41', '1', '37', '遇 见 了 就 对 他 说 ： “ 众 人 都 找 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24254', '41', '1', '38', '耶 稣 对 他 们 说 ： “ 我 们 可 以 往 别 处 去 ， 到 邻 近 的 乡 村 ， 我 也 好 在 那 里 传 道 ， 因 为 我 是 为 这 事 出 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24255', '41', '1', '39', '于 是 在 加 利 利 全 地 ， 进 了 会 堂 ， 传 道 ， 赶 鬼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24256', '41', '1', '40', '＜ 洁 净 长 大 痲 疯 的 人 （ 太   8 : 1 - 4 ； 路   5 : 1 2 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24257', '41', '1', '41', '耶 稣 动 了 慈 心 ， 就 伸 手 摸 他 ， 说 ： “ 我 肯 ， 你 洁 净 了 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24258', '41', '1', '42', '大 痲 疯 即 时 离 开 他 ， 他 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24259', '41', '1', '43', '耶 稣 严 严 地 嘱 咐 他 ， 就 打 发 他 走 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24260', '41', '1', '44', '对 他 说 ： “ 你 要 谨 慎 ， 什 么 话 都 不 可 告 诉 人 ， 只 要 去 把 身 体 给 祭 司 察 看 ， 又 因 为 你 洁 净 了 ， 献 上 摩 西 所 吩 咐 的 礼 物 ， 对 众 人 作 证 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24261', '41', '1', '45', '那 人 出 去 ， 倒 说 许 多 的 话 ， 把 这 件 事 传 扬 开 了 ， 叫 耶 稣 以 后 不 得 再 明 明 地 进 城 ， 只 好 在 外 边 旷 野 地 方 。 人 从 各 处 都 就 了 他 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24262', '41', '2', '1', '＜ 治 好 瘫 痪 病 人 （ 太   9 : 1 - 8 ； 路   5 : 1 7 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24263', '41', '2', '2', '就 有 许 多 人 聚 集 ， 甚 至 连 门 前 都 没 有 空 地 ； 耶 稣 就 对 他 们 讲 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24264', '41', '2', '3', '有 人 带 着 一 个 瘫 子 来 见 耶 稣 ， 是 用 四 个 人 抬 来 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24265', '41', '2', '4', '因 为 人 多 ， 不 得 近 前 ， 就 把 耶 稣 所 在 的 房 子 ， 拆 了 房 顶 ， 既 拆 通 了 ， 就 把 瘫 子 连 所 躺 卧 的 褥 子 都 缒 下 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24266', '41', '2', '5', '耶 稣 见 他 们 的 信 心 ， 就 对 瘫 子 说 ： “ 小 子 ， 你 的 罪 赦 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24267', '41', '2', '6', '有 几 个 文 士 坐 在 那 里 ， 心 里 议 论 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24268', '41', '2', '7', '“ 这 个 人 为 什 么 这 样 说 呢 ？ 他 说 僭 妄 的 话 了 。 除 了 神 以 外 ， 谁 能 赦 罪 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24269', '41', '2', '8', '耶 稣 心 中 知 道 他 们 心 里 这 样 议 论 ， 就 说 ： “ 你 们 心 里 为 什 么 这 样 议 论 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24270', '41', '2', '9', '或 对 瘫 子 说 ‘ 你 的 罪 赦 了 ’ ， 或 说 ‘ 起 来 ！ 拿 你 的 褥 子 行 走 ’ ； 哪 一 样 容 易 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24271', '41', '2', '10', '但 要 叫 你 们 知 道 ， 人 子 在 地 上 有 赦 罪 的 权 柄 。 ” 就 对 瘫 子 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24272', '41', '2', '11', '“ 我 吩 咐 你 ， 起 来 ！ 拿 你 的 褥 子 回 家 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24273', '41', '2', '12', '那 人 就 起 来 ， 立 刻 拿 着 褥 子 ， 当 众 人 面 前 出 去 了 ， 以 致 众 人 都 惊 奇 ， 归 荣 耀 与 神 ， 说 ： “ 我 们 从 来 没 有 见 过 这 样 的 事 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24274', '41', '2', '13', '＜ 呼 召 利 未 （ 太   9 : 9 - 1 3 ； 路   5 : 2 7 - 3 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24275', '41', '2', '14', '耶 稣 经 过 的 时 候 ， 看 见 亚 勒 腓 的 儿 子 利 未 坐 在 税 关 上 ， 就 对 他 说 ： “ 你 跟 从 我 来 。 ” 他 就 起 来 ， 跟 从 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24276', '41', '2', '15', '耶 稣 在 利 未 家 里 坐 席 的 时 候 ， 有 好 些 税 吏 和 罪 人 与 耶 稣 并 门 徒 一 同 坐 席 ； 因 为 这 样 的 人 多 ， 他 们 也 跟 随 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24277', '41', '2', '16', '法 利 赛 人 中 的 文 士 ｛ 有 古 卷 ： 文 士 和 法 利 赛 人 ｝ 看 见 耶 稣 和 罪 人 并 税 吏 一 同 吃 饭 ， 就 对 他 门 徒 说 ： “ 他 和 税 吏 并 罪 人 一 同 吃 喝 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24278', '41', '2', '17', '耶 稣 听 见 ， 就 对 他 们 说 ： “ 康 健 的 人 用 不 着 医 生 ， 有 病 的 人 才 用 得 着 。 我 来 本 不 是 召 义 人 ， 乃 是 召 罪 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24279', '41', '2', '18', '＜ 禁 食 的 问 题 （ 太   9 : 1 4 - 1 7 ； 路   5 : 3 3 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24280', '41', '2', '19', '耶 稣 对 他 们 说 ： “ 新 郎 和 陪 伴 之 人 同 在 的 时 候 ， 陪 伴 之 人 岂 能 禁 食 呢 ？ 新 郎 还 同 在 ， 他 们 不 能 禁 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24281', '41', '2', '20', '但 日 子 将 到 ， 新 郎 要 离 开 他 们 ， 那 日 他 们 就 要 禁 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24282', '41', '2', '21', '没 有 人 把 新 布 缝 在 旧 衣 服 上 ， 恐 怕 所 补 上 的 新 布 带 坏 了 旧 衣 服 ， 破 的 就 更 大 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24283', '41', '2', '22', '也 没 有 人 把 新 酒 装 在 旧 皮 袋 里 ， 恐 怕 酒 把 皮 袋 裂 开 ， 酒 和 皮 袋 就 都 坏 了 ； 惟 把 新 酒 装 在 新 皮 袋 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24284', '41', '2', '23', '＜ 安 息 日 的 问 题 （ 太   1 2 : 1 - 8 ； 路   6 : 1 - 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24285', '41', '2', '24', '法 利 赛 人 对 耶 稣 说 ： “ 看 哪 ， 他 们 在 安 息 日 为 什 么 做 不 可 做 的 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24286', '41', '2', '25', '耶 稣 对 他 们 说 ： “ 经 上 记 着 大 卫 和 跟 从 他 的 人 缺 乏 饥 饿 之 时 所 做 的 事 ， 你 们 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24287', '41', '2', '26', '他 当 亚 比 亚 他 作 大 祭 司 的 时 候 ， 怎 么 进 了 神 的 殿 ， 吃 了 陈 设 饼 ， 又 给 跟 从 他 的 人 吃 。 这 饼 除 了 祭 司 以 外 ， 人 都 不 可 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24288', '41', '2', '27', '又 对 他 们 说 ： “ 安 息 日 是 为 人 设 立 的 ， 人 不 是 为 安 息 日 设 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24289', '41', '2', '28', '所 以 ， 人 子 也 是 安 息 日 的 主 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24290', '41', '3', '1', '＜ 治 好 枯 干 了 一 只 手 的 人 （ 太   1 2 : 9 - 1 4 ； 路   6 : 6 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24291', '41', '3', '2', '众 人 窥 探 耶 稣 ， 在 安 息 日 医 治 不 医 治 ， 意 思 是 要 控 告 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24292', '41', '3', '3', '耶 稣 对 那 枯 干 一 只 手 的 人 说 ： “ 起 来 ， 站 在 当 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24293', '41', '3', '4', '又 问 众 人 说 ： “ 在 安 息 日 行 善 行 恶 ， 救 命 害 命 ， 哪 样 是 可 以 的 呢 ？ ” 他 们 都 不 作 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24294', '41', '3', '5', '耶 稣 怒 目 周 围 看 他 们 ， 忧 愁 他 们 的 心 刚 硬 ， 就 对 那 人 说 ： “ 伸 出 手 来 ！ ” 他 把 手 一 伸 ， 手 就 复 了 原 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24295', '41', '3', '6', '法 利 赛 人 出 去 ， 同 希 律 一 党 的 人 商 议 怎 样 可 以 除 灭 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24296', '41', '3', '7', '＜ 海 边 的 群 众 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24297', '41', '3', '8', '还 有 许 多 人 听 见 他 所 做 的 大 事 ， 就 从 犹 太 、 耶 路 撒 冷 、 以 土 买 、 约 旦 河 外 ， 并 泰 尔 、 西 顿 的 四 方 来 到 他 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24298', '41', '3', '9', '他 因 为 人 多 ， 就 吩 咐 门 徒 叫 一 只 小 船 伺 候 着 ， 免 得 众 人 拥 挤 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24299', '41', '3', '10', '他 治 好 了 许 多 人 ， 所 以 凡 有 灾 病 的 ， 都 挤 进 来 要 摸 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24300', '41', '3', '11', '污 鬼 无 论 何 时 看 见 他 ， 就 俯 伏 在 他 面 前 ， 喊 着 说 ： “ 你 是 神 的 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24301', '41', '3', '12', '耶 稣 再 三 地 嘱 咐 他 们 ， 不 要 把 他 显 露 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24302', '41', '3', '13', '＜ 设 立 十 二 门 徒 （ 太   1 0 : 1 - 4 ； 路   6 : 1 2 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24303', '41', '3', '14', '他 就 设 立 十 二 个 人 ， 要 他 们 常 和 自 己 同 在 ， 也 要 差 他 们 去 传 道 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24304', '41', '3', '15', '并 给 他 们 权 柄 赶 鬼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24305', '41', '3', '16', '这 十 二 个 人 有 西 门 （ 耶 稣 又 给 他 起 名 叫 彼 得 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24306', '41', '3', '17', '还 有 西 庇 太 的 儿 子 雅 各 和 雅 各 的 兄 弟 约 翰 （ 又 给 这 两 个 人 起 名 叫 半 尼 其 ， 就 是 雷 子 的 意 思 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24307', '41', '3', '18', '又 有 安 得 烈 、 腓 力 、 巴 多 罗 买 、 马 太 、 多 马 、 亚 勒 腓 的 儿 子 雅 各 、 和 达 太 ， 并 奋 锐 党 的 西 门 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24308', '41', '3', '19', '还 有 卖 耶 稣 的 加 略 人 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24309', '41', '3', '20', '＜ 耶 稣 和 别 西 卜 （ 太   1 2 : 2 2 - 3 2 ； 路   1 1 : 1 4 - 2 3 ； 1 2 : 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24310', '41', '3', '21', '耶 稣 的 亲 属 听 见 ， 就 出 来 要 拉 住 他 ， 因 为 他 们 说 他 癫 狂 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24311', '41', '3', '22', '从 耶 路 撒 冷 下 来 的 文 士 说 ： “ 他 是 被 别 西 卜 附 着 ” ； 又 说 ： “ 他 是 靠 着 鬼 王 赶 鬼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24312', '41', '3', '23', '耶 稣 叫 他 们 来 ， 用 比 喻 对 他 们 说 ： “ 撒 但 怎 能 赶 出 撒 但 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24313', '41', '3', '24', '若 一 国 自 相 纷 争 ， 那 国 就 站 立 不 住 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24314', '41', '3', '25', '若 一 家 自 相 纷 争 ， 那 家 就 站 立 不 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24315', '41', '3', '26', '若 撒 但 自 相 攻 打 纷 争 ， 他 就 站 立 不 住 ， 必 要 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24316', '41', '3', '27', '没 有 人 能 进 壮 士 家 里 ， 抢 夺 他 的 家 具 ； 必 先 捆 住 那 壮 士 ， 才 可 以 抢 夺 他 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24317', '41', '3', '28', '我 实 在 告 诉 你 们 ， 世 人 一 切 的 罪 和 一 切 亵 渎 的 话 都 可 得 赦 免 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24318', '41', '3', '29', '凡 亵 渎 圣 灵 的 ， 却 永 不 得 赦 免 ， 乃 要 担 当 永 远 的 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24319', '41', '3', '30', '这 话 是 因 为 他 们 说 ： “ 他 是 被 污 鬼 附 着 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24320', '41', '3', '31', '＜ 耶 稣 的 母 亲 和 兄 弟 们 （ 太   1 2 : 4 6 - 5 0 ； 路   8 : 1 9 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24321', '41', '3', '32', '有 许 多 人 在 耶 稣 周 围 坐 着 ， 他 们 就 告 诉 他 说 ： “ 看 哪 ， 你 母 亲 和 你 弟 兄 在 外 边 找 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24322', '41', '3', '33', '耶 稣 回 答 说 ： “ 谁 是 我 的 母 亲 ？ 谁 是 我 的 弟 兄 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24323', '41', '3', '34', '就 四 面 观 看 那 周 围 坐 着 的 人 ， 说 ： “ 看 哪 ， 我 的 母 亲 ， 我 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24324', '41', '3', '35', '凡 遵 行 神 旨 意 的 人 就 是 我 的 弟 兄 姊 妹 和 母 亲 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24325', '41', '4', '1', '＜ 撒 种 的 比 喻 （ 太   1 3 : 1 - 9 ； 路   8 : 4 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24326', '41', '4', '2', '耶 稣 就 用 比 喻 教 训 他 们 许 多 道 理 。 在 教 训 之 间 ， 对 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24327', '41', '4', '3', '“ 你 们 听 啊 ！ 有 一 个 撒 种 的 出 去 撒 种 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24328', '41', '4', '4', '撒 的 时 候 ， 有 落 在 路 旁 的 ， 飞 鸟 来 吃 尽 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24329', '41', '4', '5', '有 落 在 土 浅 石 头 地 上 的 ， 土 既 不 深 ， 发 苗 最 快 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24330', '41', '4', '6', '日 头 出 来 一 晒 ， 因 为 没 有 根 ， 就 枯 干 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24331', '41', '4', '7', '有 落 在 荆 棘 里 的 ， 荆 棘 长 起 来 ， 把 它 挤 住 了 ， 就 不 结 实 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24332', '41', '4', '8', '又 有 落 在 好 土 里 的 ， 就 发 生 长 大 ， 结 实 有 三 十 倍 的 ， 有 六 十 倍 的 ， 有 一 百 倍 的 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24333', '41', '4', '9', '又 说 ： “ 有 耳 可 听 的 ， 就 应 当 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24334', '41', '4', '10', '＜ 用 比 喻 的 目 的 （ 太   1 3 : 1 0 - 1 7 ； 路   8 : 9 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24335', '41', '4', '11', '耶 稣 对 他 们 说 ： “ 神 国 的 奥 秘 只 叫 你 们 知 道 ， 若 是 对 外 人 讲 ， 凡 事 就 用 比 喻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24336', '41', '4', '12', '叫 他 们 看 是 看 见 ， 却 不 晓 得 ； 听 是 听 见 ， 却 不 明 白 ； 恐 怕 他 们 回 转 过 来 ， 就 得 赦 免 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24337', '41', '4', '13', '＜ 解 明 撒 种 的 比 喻 （ 太   1 3 : 1 8 - 2 3 ； 路   8 : 1 1 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24338', '41', '4', '14', '撒 种 之 人 所 撒 的 就 是 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24339', '41', '4', '15', '那 撒 在 路 旁 的 ， 就 是 人 听 了 道 ， 撒 但 立 刻 来 ， 把 撒 在 他 心 里 的 道 夺 了 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24340', '41', '4', '16', '那 撒 在 石 头 地 上 的 ， 就 是 人 听 了 道 ， 立 刻 欢 喜 领 受 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24341', '41', '4', '17', '但 他 心 里 没 有 根 ， 不 过 是 暂 时 的 ， 及 至 为 道 遭 了 患 难 ， 或 是 受 了 逼 迫 ， 立 刻 就 跌 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24342', '41', '4', '18', '还 有 那 撒 在 荆 棘 里 的 ， 就 是 人 听 了 道 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24343', '41', '4', '19', '后 来 有 世 上 的 思 虑 、 钱 财 的 迷 惑 ， 和 别 样 的 私 欲 进 来 ， 把 道 挤 住 了 ， 就 不 能 结 实 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24344', '41', '4', '20', '那 撒 在 好 地 上 的 ， 就 是 人 听 道 ， 又 领 受 ， 并 且 结 实 ， 有 三 十 倍 的 ， 有 六 十 倍 的 ， 有 一 百 倍 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24345', '41', '4', '21', '＜ 斗 底 下 的 灯 （ 路   8 : 1 6 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24346', '41', '4', '22', '因 为 掩 藏 的 事 ， 没 有 不 显 出 来 的 ； 隐 瞒 的 事 ， 没 有 不 露 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24347', '41', '4', '23', '有 耳 可 听 的 ， 就 应 当 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24348', '41', '4', '24', '又 说 ： “ 你 们 所 听 的 要 留 心 。 你 们 用 什 么 量 器 量 给 人 ， 也 必 用 什 么 量 器 量 给 你 们 ， 并 且 要 多 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24349', '41', '4', '25', '因 为 有 的 ， 还 要 给 他 ； 没 有 的 ， 连 他 所 有 的 也 要 夺 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24350', '41', '4', '26', '＜ 种 子 长 大 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24351', '41', '4', '27', '黑 夜 睡 觉 ， 白 日 起 来 ， 这 种 就 发 芽 渐 长 ， 那 人 却 不 晓 得 如 何 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24352', '41', '4', '28', '地 生 五 谷 是 出 于 自 然 的 ： 先 发 苗 ， 后 长 穗 ， 再 后 穗 上 结 成 饱 满 的 子 粒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24353', '41', '4', '29', '谷 既 熟 了 ， 就 用 镰 刀 去 割 ， 因 为 收 成 的 时 候 到 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24354', '41', '4', '30', '＜ 芥 菜 种 的 比 喻 （ 太   1 3 : 3 1 - 3 2 ； 路   1 3 : 1 8 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24355', '41', '4', '31', '好 像 一 粒 芥 菜 种 ， 种 在 地 里 的 时 候 ， 虽 比 地 上 的 百 种 都 小 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24356', '41', '4', '32', '但 种 上 以 后 ， 就 长 起 来 ， 比 各 样 的 菜 都 大 ， 又 长 出 大 枝 来 ， 甚 至 天 上 的 飞 鸟 可 以 宿 在 它 的 荫 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24357', '41', '4', '33', '＜ 耶 稣 用 比 喻 讲 道 （ 太   1 3 : 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24358', '41', '4', '34', '若 不 用 比 喻 ， 就 不 对 他 们 讲 ； 没 有 人 的 时 候 ， 就 把 一 切 的 道 讲 给 门 徒 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24359', '41', '4', '35', '＜ 平 静 风 和 海 （ 太   8 : 2 3 - 2 7 ； 路   8 : 2 2 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24360', '41', '4', '36', '门 徒 离 开 众 人 ， 耶 稣 仍 在 船 上 ， 他 们 就 把 他 一 同 带 去 ； 也 有 别 的 船 和 他 同 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24361', '41', '4', '37', '忽 然 起 了 暴 风 ， 波 浪 打 入 船 内 ， 甚 至 船 要 满 了 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24362', '41', '4', '38', '耶 稣 在 船 尾 上 ， 枕 着 枕 头 睡 觉 。 门 徒 叫 醒 了 他 ， 说 ： “ 夫 子 ！ 我 们 丧 命 ， 你 不 顾 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24363', '41', '4', '39', '耶 稣 醒 了 ， 斥 责 风 ， 向 海 说 ： “ 住 了 吧 ！ 静 了 吧 ！ ” 风 就 止 住 ， 大 大 地 平 静 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24364', '41', '4', '40', '耶 稣 对 他 们 说 ： “ 为 什 么 胆 怯 ？ 你 们 还 没 有 信 心 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24365', '41', '4', '41', '他 们 就 大 大 地 惧 怕 ， 彼 此 说 ： “ 这 到 底 是 谁 ， 连 风 和 海 也 听 从 他 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24366', '41', '5', '1', '＜ 治 好 格 拉 森 被 鬼 附 的 人 （ 太   8 : 2 8 - 3 4 ； 路   8 : 2 6 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24367', '41', '5', '2', '耶 稣 一 下 船 ， 就 有 一 个 被 污 鬼 附 着 的 人 从 坟 茔 里 出 来 迎 着 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24368', '41', '5', '3', '那 人 常 住 在 坟 茔 里 ， 没 有 人 能 捆 住 他 ， 就 是 用 铁 链 也 不 能 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24369', '41', '5', '4', '因 为 人 屡 次 用 脚 镣 和 铁 链 捆 锁 他 ， 铁 链 竟 被 他 挣 断 了 ， 脚 镣 也 被 他 弄 碎 了 ； 总 没 有 人 能 制 伏 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24370', '41', '5', '5', '他 昼 夜 常 在 坟 茔 里 和 山 中 喊 叫 ， 又 用 石 头 砍 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24371', '41', '5', '6', '他 远 远 地 看 见 耶 稣 ， 就 跑 过 去 拜 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24372', '41', '5', '7', '大 声 呼 叫 说 ： “ 至 高 神 的 儿 子 耶 稣 ， 我 与 你 有 什 么 相 干 ？ 我 指 着 神 恳 求 你 ， 不 要 叫 我 受 苦 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24373', '41', '5', '8', '是 因 耶 稣 曾 吩 咐 他 说 ： “ 污 鬼 啊 ， 从 这 人 身 上 出 来 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24374', '41', '5', '9', '耶 稣 问 他 说 ： “ 你 名 叫 什 么 ？ ” 回 答 说 ： “ 我 名 叫 ‘ 群 ’ ， 因 为 我 们 多 的 缘 故 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24375', '41', '5', '10', '就 再 三 地 求 耶 稣 ， 不 要 叫 他 们 离 开 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24376', '41', '5', '11', '在 那 里 山 坡 上 ， 有 一 大 群 猪 吃 食 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24377', '41', '5', '12', '鬼 就 央 求 耶 稣 说 ： “ 求 你 打 发 我 们 往 猪 群 里 ， 附 着 猪 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24378', '41', '5', '13', '耶 稣 准 了 他 们 ， 污 鬼 就 出 来 ， 进 入 猪 里 去 。 于 是 那 群 猪 闯 下 山 崖 ， 投 在 海 里 ， 淹 死 了 。 猪 的 数 目 约 有 二 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24379', '41', '5', '14', '放 猪 的 就 逃 跑 了 ， 去 告 诉 城 里 和 乡 下 的 人 。 众 人 就 来 ， 要 看 是 什 么 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24380', '41', '5', '15', '他 们 来 到 耶 稣 那 里 ， 看 见 那 被 鬼 附 着 的 人 ， 就 是 从 前 被 群 鬼 所 附 的 ， 坐 着 ， 穿 上 衣 服 ， 心 里 明 白 过 来 ， 他 们 就 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24381', '41', '5', '16', '看 见 这 事 的 ， 便 将 鬼 附 之 人 所 遇 见 的 和 那 群 猪 的 事 都 告 诉 了 众 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24382', '41', '5', '17', '众 人 就 央 求 耶 稣 离 开 他 们 的 境 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24383', '41', '5', '18', '耶 稣 上 船 的 时 候 ， 那 从 前 被 鬼 附 着 的 人 恳 求 和 耶 稣 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24384', '41', '5', '19', '耶 稣 不 许 ， 却 对 他 说 ： “ 你 回 家 去 ， 到 你 的 亲 属 那 里 ， 将 主 为 你 所 做 的 是 何 等 大 的 事 ， 是 怎 样 怜 悯 你 ， 都 告 诉 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24385', '41', '5', '20', '那 人 就 走 了 ， 在 低 加 坡 里 传 扬 耶 稣 为 他 做 了 何 等 大 的 事 ， 众 人 就 都 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24386', '41', '5', '21', '＜ 睚 鲁 的 女 儿 和 血 漏 的 女 人 （ 太   9 : 1 8 - 2 6 ； 路   8 : 4 0 - 5 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24387', '41', '5', '22', '有 一 个 管 会 堂 的 人 ， 名 叫 睚 鲁 ， 来 见 耶 稣 ， 就 俯 伏 在 他 脚 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24388', '41', '5', '23', '再 三 地 求 他 ， 说 ： “ 我 的 小 女 儿 快 要 死 了 ， 求 你 去 按 手 在 她 身 上 ， 使 她 痊 愈 ， 得 以 活 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24389', '41', '5', '24', '耶 稣 就 和 他 同 去 。 有 许 多 人 跟 随 拥 挤 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24390', '41', '5', '25', '有 一 个 女 人 ， 患 了 十 二 年 的 血 漏 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24391', '41', '5', '26', '在 好 些 医 生 手 里 受 了 许 多 的 苦 ， 又 花 尽 了 她 所 有 的 ， 一 点 也 不 见 好 ， 病 势 反 倒 更 重 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24392', '41', '5', '27', '她 听 见 耶 稣 的 事 ， 就 从 后 头 来 ， 杂 在 众 人 中 间 ， 摸 耶 稣 的 衣 裳 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24393', '41', '5', '28', '意 思 说 ： “ 我 只 摸 他 的 衣 裳 ， 就 必 痊 愈 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24394', '41', '5', '29', '于 是 她 血 漏 的 源 头 立 刻 干 了 ； 她 便 觉 得 身 上 的 灾 病 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24395', '41', '5', '30', '耶 稣 顿 时 心 里 觉 得 有 能 力 从 自 己 身 上 出 去 ， 就 在 众 人 中 间 转 过 来 ， 说 ： “ 谁 摸 我 的 衣 裳 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24396', '41', '5', '31', '门 徒 对 他 说 ： “ 你 看 众 人 拥 挤 你 ， 还 说 ‘ 谁 摸 我 ’ 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24397', '41', '5', '32', '耶 稣 周 围 观 看 ， 要 见 做 这 事 的 女 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24398', '41', '5', '33', '那 女 人 知 道 在 自 己 身 上 所 成 的 事 ， 就 恐 惧 战 兢 ， 来 俯 伏 在 耶 稣 跟 前 ， 将 实 情 全 告 诉 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24399', '41', '5', '34', '耶 稣 对 她 说 ： “ 女 儿 ， 你 的 信 救 了 你 ， 平 平 安 安 地 回 去 吧 ！ 你 的 灾 病 痊 愈 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24400', '41', '5', '35', '还 说 话 的 时 候 ， 有 人 从 管 会 堂 的 家 里 来 ， 说 ： “ 你 的 女 儿 死 了 ， 何 必 还 劳 动 先 生 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24401', '41', '5', '36', '耶 稣 听 见 所 说 的 话 ， 就 对 管 会 堂 的 说 ： “ 不 要 怕 ， 只 要 信 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24402', '41', '5', '37', '于 是 带 着 彼 得 、 雅 各 、 和 雅 各 的 兄 弟 约 翰 同 去 ， 不 许 别 人 跟 随 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24403', '41', '5', '38', '他 们 来 到 管 会 堂 的 家 里 ； 耶 稣 看 见 那 里 乱 嚷 ， 并 有 人 大 大 地 哭 泣 哀 号 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24404', '41', '5', '39', '进 到 里 面 ， 就 对 他 们 说 ： “ 为 什 么 乱 嚷 哭 泣 呢 ？ 孩 子 不 是 死 了 ， 是 睡 着 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24405', '41', '5', '40', '他 们 就 嗤 笑 耶 稣 。 耶 稣 把 他 们 都 撵 出 去 ， 就 带 着 孩 子 的 父 母 和 跟 随 的 人 进 了 孩 子 所 在 的 地 方 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24406', '41', '5', '41', '就 拉 着 孩 子 的 手 ， 对 她 说 ： “ 大 利 大 ， 古 米 ！ ” （ 翻 出 来 就 是 说 ： “ 闺 女 ， 我 吩 咐 你 起 来 ！ ” ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24407', '41', '5', '42', '那 闺 女 立 时 起 来 走 。 他 们 就 大 大 地 惊 奇 ； 闺 女 已 经 十 二 岁 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24408', '41', '5', '43', '耶 稣 切 切 地 嘱 咐 他 们 ， 不 要 叫 人 知 道 这 事 ， 又 吩 咐 给 她 东 西 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24409', '41', '6', '1', '＜ 拿 撒 勒 人 厌 弃 耶 稣 （ 太   1 3 : 5 3 - 5 8 ； 路   4 : 1 6 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24410', '41', '6', '2', '到 了 安 息 日 ， 他 在 会 堂 里 教 训 人 。 众 人 听 见 ， 就 甚 希 奇 ， 说 ： “ 这 人 从 哪 里 有 这 些 事 呢 ？ 所 赐 给 他 的 是 什 么 智 慧 ？ 他 手 所 做 的 是 何 等 的 异 能 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24411', '41', '6', '3', '这 不 是 那 木 匠 吗 ？ 不 是 马 利 亚 的 儿 子 雅 各 、 约 西 、 犹 大 、 西 门 的 长 兄 吗 ？ 他 妹 妹 们 不 也 是 在 我 们 这 里 吗 ？ ” 他 们 就 厌 弃 他 ｛ 厌 弃 他 ： 原 文 是 因 他 跌 倒 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24412', '41', '6', '4', '耶 稣 对 他 们 说 ： “ 大 凡 先 知 ， 除 了 本 地 、 亲 属 、 本 家 之 外 ， 没 有 不 被 人 尊 敬 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24413', '41', '6', '5', '耶 稣 就 在 那 里 不 得 行 什 么 异 能 ， 不 过 按 手 在 几 个 病 人 身 上 ， 治 好 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24414', '41', '6', '6', '他 也 诧 异 他 们 不 信 ， 就 往 周 围 乡 村 教 训 人 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24415', '41', '6', '7', '＜ 耶 稣 差 遣 十 二 门 徒 （ 太   1 0 : 5 - 1 5 ； 路   9 : 1 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24416', '41', '6', '8', '并 且 嘱 咐 他 们 ： “ 行 路 的 时 候 不 要 带 食 物 和 口 袋 ， 腰 袋 里 也 不 要 带 钱 ， 除 了 柺 杖 以 外 ， 什 么 都 不 要 带 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24417', '41', '6', '9', '只 要 穿 鞋 ， 也 不 要 穿 两 件 褂 子 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24418', '41', '6', '10', '又 对 他 们 说 ： “ 你 们 无 论 到 何 处 ， 进 了 人 的 家 ， 就 住 在 那 里 ， 直 到 离 开 那 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24419', '41', '6', '11', '何 处 的 人 不 接 待 你 们 ， 不 听 你 们 ， 你 们 离 开 那 里 的 时 候 ， 就 把 脚 上 的 尘 土 跺 下 去 ， 对 他 们 作 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24420', '41', '6', '12', '门 徒 就 出 去 传 道 ， 叫 人 悔 改 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24421', '41', '6', '13', '又 赶 出 许 多 的 鬼 ， 用 油 抹 了 许 多 病 人 ， 治 好 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24422', '41', '6', '14', '＜ 施 洗 约 翰 的 死 （ 太   1 4 : 1 - 1 2 ； 路   9 : 7 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24423', '41', '6', '15', '但 别 人 说 ： “ 是 以 利 亚 。 ” 又 有 人 说 ： “ 是 先 知 ， 正 像 先 知 中 的 一 位 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24424', '41', '6', '16', '希 律 听 见 却 说 ： “ 是 我 所 斩 的 约 翰 ， 他 复 活 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24425', '41', '6', '17', '先 是 希 律 为 他 兄 弟 腓 力 的 妻 子 希 罗 底 的 缘 故 ， 差 人 去 拿 住 约 翰 ， 锁 在 监 里 ， 因 为 希 律 已 经 娶 了 那 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24426', '41', '6', '18', '约 翰 曾 对 希 律 说 ： “ 你 娶 你 兄 弟 的 妻 子 是 不 合 理 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24427', '41', '6', '19', '于 是 希 罗 底 怀 恨 他 ， 想 要 杀 他 ， 只 是 不 能 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24428', '41', '6', '20', '因 为 希 律 知 道 约 翰 是 义 人 ， 是 圣 人 ， 所 以 敬 畏 他 ， 保 护 他 ， 听 他 讲 论 ， 就 多 照 着 行 ｛ 有 古 卷 ： 游 移 不 定 ｝ ， 并 且 乐 意 听 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24429', '41', '6', '21', '有 一 天 ， 恰 巧 是 希 律 的 生 日 ， 希 律 摆 设 筵 席 ， 请 了 大 臣 和 千 夫 长 ， 并 加 利 利 作 首 领 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24430', '41', '6', '22', '希 罗 底 的 女 儿 进 来 跳 舞 ， 使 希 律 和 同 席 的 人 都 欢 喜 。 王 就 对 女 子 说 ： “ 你 随 意 向 我 求 什 么 ， 我 必 给 你 ； ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24431', '41', '6', '23', '又 对 她 起 誓 说 ： “ 随 你 向 我 求 什 么 ， 就 是 我 国 的 一 半 ， 我 也 必 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24432', '41', '6', '24', '她 就 出 去 对 她 母 亲 说 ： “ 我 可 以 求 什 么 呢 ？ ” 她 母 亲 说 ： “ 施 洗 约 翰 的 头 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24433', '41', '6', '25', '她 就 急 忙 进 去 见 王 ， 求 他 说 ： “ 我 愿 王 立 时 把 施 洗 约 翰 的 头 放 在 盘 子 里 给 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24434', '41', '6', '26', '王 就 甚 忧 愁 ； 但 因 他 所 起 的 誓 ， 又 因 同 席 的 人 ， 就 不 肯 推 辞 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24435', '41', '6', '27', '随 即 差 一 个 护 卫 兵 ， 吩 咐 拿 约 翰 的 头 来 。 护 卫 兵 就 去 ， 在 监 里 斩 了 约 翰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24436', '41', '6', '28', '把 头 放 在 盘 子 里 ， 拿 来 给 女 子 ， 女 子 就 给 她 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24437', '41', '6', '29', '约 翰 的 门 徒 听 见 了 ， 就 来 把 他 的 尸 首 领 去 ， 葬 在 坟 墓 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24438', '41', '6', '30', '＜ 耶 稣 给 五 千 人 吃 饱 （ 太   1 4 : 1 3 - 2 1 ； 路   9 : 1 0 - 1 7 ； 约   6 : 1 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24439', '41', '6', '31', '他 就 说 ： “ 你 们 来 ， 同 我 暗 暗 地 到 旷 野 地 方 去 歇 一 歇 。 ” 这 是 因 为 来 往 的 人 多 ， 他 们 连 吃 饭 也 没 有 工 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24440', '41', '6', '32', '他 们 就 坐 船 ， 暗 暗 地 往 旷 野 地 方 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24441', '41', '6', '33', '众 人 看 见 他 们 去 ， 有 许 多 认 识 他 们 的 ， 就 从 各 城 步 行 ， 一 同 跑 到 那 里 ， 比 他 们 先 赶 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24442', '41', '6', '34', '耶 稣 出 来 ， 见 有 许 多 的 人 ， 就 怜 悯 他 们 ， 因 为 他 们 如 同 羊 没 有 牧 人 一 般 ， 于 是 开 口 教 训 他 们 许 多 道 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24443', '41', '6', '35', '天 已 经 晚 了 ， 门 徒 进 前 来 ， 说 ： “ 这 是 野 地 ， 天 已 经 晚 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24444', '41', '6', '36', '请 叫 众 人 散 开 ， 他 们 好 往 四 面 乡 村 里 去 ， 自 己 买 什 么 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24445', '41', '6', '37', '耶 稣 回 答 说 ： “ 你 们 给 他 们 吃 吧 。 ” 门 徒 说 ： “ 我 们 可 以 去 买 二 十 两 银 子 的 饼 给 他 们 吃 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24446', '41', '6', '38', '耶 稣 说 ： “ 你 们 有 多 少 饼 ， 可 以 去 看 看 。 ” 他 们 知 道 了 ， 就 说 ： “ 五 个 饼 ， 两 条 鱼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24447', '41', '6', '39', '耶 稣 吩 咐 他 们 ， 叫 众 人 一 帮 一 帮 地 坐 在 青 草 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24448', '41', '6', '40', '众 人 就 一 排 一 排 地 坐 下 ， 有 一 百 一 排 的 ， 有 五 十 一 排 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24449', '41', '6', '41', '耶 稣 拿 着 这 五 个 饼 ， 两 条 鱼 ， 望 着 天 祝 福 ， 擘 开 饼 ， 递 给 门 徒 ， 摆 在 众 人 面 前 ， 也 把 那 两 条 鱼 分 给 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24450', '41', '6', '42', '他 们 都 吃 ， 并 且 吃 饱 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24451', '41', '6', '43', '门 徒 就 把 碎 饼 碎 鱼 收 拾 起 来 ， 装 满 了 十 二 个 篮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24452', '41', '6', '44', '吃 饼 的 男 人 共 有 五 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24453', '41', '6', '45', '＜ 耶 稣 在 海 上 行 走 （ 太   1 4 : 2 2 - 3 3 ； 约   6 : 1 6 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24454', '41', '6', '46', '他 既 辞 别 了 他 们 ， 就 往 山 上 去 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24455', '41', '6', '47', '到 了 晚 上 ， 船 在 海 中 ， 耶 稣 独 自 在 岸 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24456', '41', '6', '48', '看 见 门 徒 因 风 不 顺 ， 摇 橹 甚 苦 。 夜 里 约 有 四 更 天 ， 就 在 海 面 上 走 ， 往 他 们 那 里 去 ， 意 思 要 走 过 他 们 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24457', '41', '6', '49', '但 门 徒 看 见 他 在 海 面 上 走 ， 以 为 是 鬼 怪 ， 就 喊 叫 起 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24458', '41', '6', '50', '因 为 他 们 都 看 见 了 他 ， 且 甚 惊 慌 。 耶 稣 连 忙 对 他 们 说 ： “ 你 们 放 心 ！ 是 我 ， 不 要 怕 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24459', '41', '6', '51', '于 是 到 他 们 那 里 ， 上 了 船 ， 风 就 住 了 ； 他 们 心 里 十 分 惊 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24460', '41', '6', '52', '这 是 因 为 他 们 不 明 白 那 分 饼 的 事 ， 心 里 还 是 愚 顽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24461', '41', '6', '53', '＜ 治 好 革 尼 撒 勒 的 病 人 （ 太   1 4 : 3 4 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24462', '41', '6', '54', '一 下 船 ， 众 人 认 得 是 耶 稣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24463', '41', '6', '55', '就 跑 遍 那 一 带 地 方 ， 听 见 他 在 何 处 ， 便 将 有 病 的 人 用 褥 子 抬 到 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24464', '41', '6', '56', '凡 耶 稣 所 到 的 地 方 ， 或 村 中 ， 或 城 里 ， 或 乡 间 ， 他 们 都 将 病 人 放 在 街 市 上 ， 求 耶 稣 只 容 他 们 摸 他 的 衣 裳 繸 子 ； 凡 摸 着 的 人 就 都 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24465', '41', '7', '1', '＜ 古 人 的 传 统 （ 太   1 5 : 1 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24466', '41', '7', '2', '他 们 曾 看 见 他 的 门 徒 中 有 人 用 俗 手 ， 就 是 没 有 洗 的 手 ， 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24467', '41', '7', '3', '（ 原 来 法 利 赛 人 和 犹 太 人 都 拘 守 古 人 的 遗 传 ， 若 不 仔 细 洗 手 就 不 吃 饭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24468', '41', '7', '4', '从 市 上 来 ， 若 不 洗 浴 也 不 吃 饭 ； 还 有 好 些 别 的 规 矩 ， 他 们 历 代 拘 守 ， 就 是 洗 杯 、 罐 、 铜 器 等 物 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24469', '41', '7', '5', '法 利 赛 人 和 文 士 问 他 说 ： “ 你 的 门 徒 为 什 么 不 照 古 人 的 遗 传 ， 用 俗 手 吃 饭 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24470', '41', '7', '6', '耶 稣 说 ： “ 以 赛 亚 指 着 你 们 假 冒 为 善 之 人 所 说 的 预 言 是 不 错 的 。 如 经 上 说 ： 这 百 姓 用 嘴 唇 尊 敬 我 ， 心 却 远 离 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24471', '41', '7', '7', '他 们 将 人 的 吩 咐 当 作 道 理 教 导 人 ， 所 以 拜 我 也 是 枉 然 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24472', '41', '7', '8', '你 们 是 离 弃 神 的 诫 命 ， 拘 守 人 的 遗 传 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24473', '41', '7', '9', '又 说 ： “ 你 们 诚 然 是 废 弃 神 的 诫 命 ， 要 守 自 己 的 遗 传 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24474', '41', '7', '10', '摩 西 说 ： ‘ 当 孝 敬 父 母 ’ ； 又 说 ： ‘ 咒 骂 父 母 的 ， 必 治 死 他 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24475', '41', '7', '11', '你 们 倒 说 ： ‘ 人 若 对 父 母 说 ： 我 所 当 奉 给 你 的 ， 已 经 作 了 各 耳 板 ’ （ 各 耳 板 就 是 供 献 的 意 思 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24476', '41', '7', '12', '以 后 你 们 就 不 容 他 再 奉 养 父 母 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24477', '41', '7', '13', '这 就 是 你 们 承 接 遗 传 ， 废 了 神 的 道 。 你 们 还 做 许 多 这 样 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24478', '41', '7', '14', '耶 稣 又 叫 众 人 来 ， 对 他 们 说 ： “ 你 们 都 要 听 我 的 话 ， 也 要 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24479', '41', '7', '15', '从 外 面 进 去 的 不 能 污 秽 人 ， 惟 有 从 里 面 出 来 的 乃 能 污 秽 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24480', '41', '7', '16', '｛ 有 古 卷 加 ： 有 耳 可 听 的 ， 就 应 当 听 ！ ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24481', '41', '7', '17', '耶 稣 离 开 众 人 ， 进 了 屋 子 ， 门 徒 就 问 他 这 比 喻 的 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24482', '41', '7', '18', '耶 稣 对 他 们 说 ： “ 你 们 也 是 这 样 不 明 白 吗 ？ 岂 不 晓 得 凡 从 外 面 进 入 的 ， 不 能 污 秽 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24483', '41', '7', '19', '因 为 不 是 入 他 的 心 ， 乃 是 入 他 的 肚 腹 ， 又 落 到 茅 厕 里 。 （ 这 是 说 ， 各 样 的 食 物 都 是 洁 净 的 ） ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24484', '41', '7', '20', '又 说 ： “ 从 人 里 面 出 来 的 ， 那 才 能 污 秽 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24485', '41', '7', '21', '因 为 从 里 面 ， 就 是 从 人 心 里 ， 发 出 恶 念 、 苟 合 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24486', '41', '7', '22', '偷 盗 、 凶 杀 、 奸 淫 、 贪 婪 、 邪 恶 、 诡 诈 、 淫 荡 、 嫉 妒 、 谤 讟 、 骄 傲 、 狂 妄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24487', '41', '7', '23', '这 一 切 的 恶 都 是 从 里 面 出 来 ， 且 能 污 秽 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24488', '41', '7', '24', '＜ 一 个 妇 人 的 信 心 （ 太   1 5 : 2 1 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24489', '41', '7', '25', '当 下 ， 有 一 个 妇 人 ， 她 的 小 女 儿 被 污 鬼 附 着 ， 听 见 耶 稣 的 事 ， 就 来 俯 伏 在 他 脚 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24490', '41', '7', '26', '这 妇 人 是 希 腊 人 ， 属 叙 利 腓 尼 基 族 。 她 求 耶 稣 赶 出 那 鬼 离 开 她 的 女 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24491', '41', '7', '27', '耶 稣 对 她 说 ： “ 让 儿 女 们 先 吃 饱 ， 不 好 拿 儿 女 的 饼 丢 给 狗 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24492', '41', '7', '28', '妇 人 回 答 说 ： “ 主 啊 ， 不 错 ； 但 是 狗 在 桌 子 底 下 也 吃 孩 子 们 的 碎 渣 儿 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24493', '41', '7', '29', '耶 稣 对 她 说 ： “ 因 这 句 话 ， 你 回 去 吧 ； 鬼 已 经 离 开 你 的 女 儿 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24494', '41', '7', '30', '她 就 回 家 去 ， 见 小 孩 子 躺 在 床 上 ， 鬼 已 经 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24495', '41', '7', '31', '＜ 耶 稣 治 好 耳 聋 舌 结 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24496', '41', '7', '32', '有 人 带 着 一 个 耳 聋 舌 结 的 人 来 见 耶 稣 ， 求 他 按 手 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24497', '41', '7', '33', '耶 稣 领 他 离 开 众 人 ， 到 一 边 去 ， 就 用 指 头 探 他 的 耳 朵 ， 吐 唾 沫 抹 他 的 舌 头 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24498', '41', '7', '34', '望 天 叹 息 ， 对 他 说 ： “ 以 法 大 ！ ” 就 是 说 ： “ 开 了 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24499', '41', '7', '35', '他 的 耳 朵 就 开 了 ， 舌 结 也 解 了 ， 说 话 也 清 楚 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24500', '41', '7', '36', '耶 稣 嘱 咐 他 们 不 要 告 诉 人 ； 但 他 越 发 嘱 咐 ， 他 们 越 发 传 扬 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24501', '41', '7', '37', '众 人 分 外 希 奇 ， 说 ： “ 他 所 做 的 事 都 好 ， 他 连 聋 子 也 叫 他 们 听 见 ， 哑 巴 也 叫 他 们 说 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24502', '41', '8', '1', '＜ 耶 稣 给 四 千 人 吃 饱 （ 太   1 5 : 3 2 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24503', '41', '8', '2', '“ 我 怜 悯 这 众 人 ； 因 为 他 们 同 我 在 这 里 已 经 三 天 ， 也 没 有 吃 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24504', '41', '8', '3', '我 若 打 发 他 们 饿 着 回 家 ， 就 必 在 路 上 困 乏 ， 因 为 其 中 有 从 远 处 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24505', '41', '8', '4', '门 徒 回 答 说 ： “ 在 这 野 地 ， 从 哪 里 能 得 饼 ， 叫 这 些 人 吃 饱 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24506', '41', '8', '5', '耶 稣 问 他 们 说 ： “ 你 们 有 多 少 饼 ？ ” 他 们 说 ： “ 七 个 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24507', '41', '8', '6', '他 吩 咐 众 人 坐 在 地 上 ， 就 拿 着 这 七 个 饼 祝 谢 了 ， 擘 开 ， 递 给 门 徒 ， 叫 他 们 摆 开 ， 门 徒 就 摆 在 众 人 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24508', '41', '8', '7', '又 有 几 条 小 鱼 ； 耶 稣 祝 了 福 ， 就 吩 咐 也 摆 在 众 人 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24509', '41', '8', '8', '众 人 都 吃 ， 并 且 吃 饱 了 ， 收 拾 剩 下 的 零 碎 ， 有 七 筐 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24510', '41', '8', '9', '人 数 约 有 四 千 。 耶 稣 打 发 他 们 走 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24511', '41', '8', '10', '随 即 同 门 徒 上 船 ， 来 到 大 玛 努 他 境 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24512', '41', '8', '11', '＜ 求 主 显 个 神 迹 （ 太   1 6 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24513', '41', '8', '12', '耶 稣 心 里 深 深 地 叹 息 ， 说 ： “ 这 世 代 为 什 么 求 神 迹 呢 ？ 我 实 在 告 诉 你 们 ， 没 有 神 迹 给 这 世 代 看 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24514', '41', '8', '13', '他 就 离 开 他 们 ， 又 上 船 往 海 那 边 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24515', '41', '8', '14', '＜ 防 备 法 利 赛 人 和 希 律 的 酵 （ 太   1 6 : 5 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24516', '41', '8', '15', '耶 稣 嘱 咐 他 们 说 ： “ 你 们 要 谨 慎 ， 防 备 法 利 赛 人 的 酵 和 希 律 的 酵 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24517', '41', '8', '16', '他 们 彼 此 议 论 说 ： “ 这 是 因 为 我 们 没 有 饼 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24518', '41', '8', '17', '耶 稣 看 出 来 ， 就 说 ： “ 你 们 为 什 么 因 为 没 有 饼 就 议 论 呢 ？ 你 们 还 不 省 悟 ， 还 不 明 白 吗 ？ 你 们 的 心 还 是 愚 顽 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24519', '41', '8', '18', '你 们 有 眼 睛 ， 看 不 见 吗 ？ 有 耳 朵 ， 听 不 见 吗 ？ 也 不 记 得 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24520', '41', '8', '19', '我 擘 开 那 五 个 饼 分 给 五 千 人 ， 你 们 收 拾 的 零 碎 装 满 了 多 少 篮 子 呢 ？ ” 他 们 说 ： “ 十 二 个 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24521', '41', '8', '20', '“ 又 擘 开 那 七 个 饼 分 给 四 千 人 ， 你 们 收 拾 的 零 碎 装 满 了 多 少 筐 子 呢 ？ ” 他 们 说 ： “ 七 个 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24522', '41', '8', '21', '耶 稣 说 ： “ 你 们 还 是 不 明 白 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24523', '41', '8', '22', '＜ 治 好 伯 赛 大 的 瞎 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24524', '41', '8', '23', '耶 稣 拉 着 瞎 子 的 手 ， 领 他 到 村 外 ， 就 吐 唾 沫 在 他 眼 睛 上 ， 按 手 在 他 身 上 ， 问 他 说 ： “ 你 看 见 什 么 了 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24525', '41', '8', '24', '他 就 抬 头 一 看 ， 说 ： “ 我 看 见 人 了 ； 他 们 好 像 树 木 ， 并 且 行 走 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24526', '41', '8', '25', '随 后 又 按 手 在 他 眼 睛 上 ， 他 定 睛 一 看 ， 就 复 了 原 ， 样 样 都 看 得 清 楚 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24527', '41', '8', '26', '耶 稣 打 发 他 回 家 ， 说 ： “ 连 这 村 子 你 也 不 要 进 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24528', '41', '8', '27', '＜ 彼 得 认 耶 稣 为 基 督 （ 太   1 6 : 1 3 - 2 0 ； 路   9 : 1 8 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24529', '41', '8', '28', '他 们 说 ： “ 有 人 说 是 施 洗 的 约 翰 ； 有 人 说 是 以 利 亚 ； 又 有 人 说 是 先 知 里 的 一 位 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24530', '41', '8', '29', '又 问 他 们 说 ： “ 你 们 说 我 是 谁 ？ ” 彼 得 回 答 说 ： “ 你 是 基 督 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24531', '41', '8', '30', '耶 稣 就 禁 戒 他 们 ， 不 要 告 诉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24532', '41', '8', '31', '＜ 耶 稣 预 言 受 难 和 复 活 （ 太   1 6 : 2 1 - 2 8 ； 路   9 : 2 2 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24533', '41', '8', '32', '耶 稣 明 明 地 说 这 话 ， 彼 得 就 拉 着 他 ， 劝 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24534', '41', '8', '33', '耶 稣 转 过 来 ， 看 着 门 徒 ， 就 责 备 彼 得 说 ： “ 撒 但 ， 退 我 后 边 去 吧 ！ 因 为 你 不 体 贴 神 的 意 思 ， 只 体 贴 人 的 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24535', '41', '8', '34', '于 是 叫 众 人 和 门 徒 来 ， 对 他 们 说 ： “ 若 有 人 要 跟 从 我 ， 就 当 舍 己 ， 背 起 他 的 十 字 架 来 跟 从 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24536', '41', '8', '35', '因 为 ， 凡 要 救 自 己 生 命 ｛ 或 译 ： 灵 魂 ； 下 同 ｝ 的 ， 必 丧 掉 生 命 ； 凡 为 我 和 福 音 丧 掉 生 命 的 ， 必 救 了 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24537', '41', '8', '36', '人 就 是 赚 得 全 世 界 ， 赔 上 自 己 的 生 命 ， 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24538', '41', '8', '37', '人 还 能 拿 什 么 换 生 命 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24539', '41', '8', '38', '凡 在 这 淫 乱 罪 恶 的 世 代 ， 把 我 和 我 的 道 当 作 可 耻 的 ， 人 子 在 他 父 的 荣 耀 里 ， 同 圣 天 使 降 临 的 时 候 ， 也 要 把 那 人 当 作 可 耻 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24540', '41', '9', '1', '耶 稣 又 对 他 们 说 ： “ 我 实 在 告 诉 你 们 ， 站 在 这 里 的 ， 有 人 在 没 尝 死 味 以 前 ， 必 要 看 见 神 的 国 大 有 能 力 临 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24541', '41', '9', '2', '＜ 耶 稣 改 变 形 像 （ 太   1 7 : 1 - 1 3 ； 路   9 : 2 8 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24542', '41', '9', '3', '衣 服 放 光 ， 极 其 洁 白 ， 地 上 漂 布 的 ， 没 有 一 个 能 漂 得 那 样 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24543', '41', '9', '4', '忽 然 ， 有 以 利 亚 同 摩 西 向 他 们 显 现 ， 并 且 和 耶 稣 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24544', '41', '9', '5', '彼 得 对 耶 稣 说 ： “ 拉 比 ｛ 就 是 夫 子 ｝ ， 我 们 在 这 里 真 好 ！ 可 以 搭 三 座 棚 ， 一 座 为 你 ， 一 座 为 摩 西 ， 一 座 为 以 利 亚 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24545', '41', '9', '6', '彼 得 不 知 道 说 什 么 才 好 ， 因 为 他 们 甚 是 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24546', '41', '9', '7', '有 一 朵 云 彩 来 遮 盖 他 们 ； 也 有 声 音 从 云 彩 里 出 来 ， 说 ： “ 这 是 我 的 爱 子 ， 你 们 要 听 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24547', '41', '9', '8', '门 徒 忽 然 周 围 一 看 ， 不 再 见 一 人 ， 只 见 耶 稣 同 他 们 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24548', '41', '9', '9', '下 山 的 时 候 ， 耶 稣 嘱 咐 他 们 说 ： “ 人 子 还 没 有 从 死 里 复 活 ， 你 们 不 要 将 所 看 见 的 告 诉 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24549', '41', '9', '10', '门 徒 将 这 话 存 记 在 心 ， 彼 此 议 论 “ 从 死 里 复 活 ” 是 什 么 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24550', '41', '9', '11', '他 们 就 问 耶 稣 说 ： “ 文 士 为 什 么 说 以 利 亚 必 须 先 来 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24551', '41', '9', '12', '耶 稣 说 ： “ 以 利 亚 固 然 先 来 复 兴 万 事 ； 经 上 不 是 指 着 人 子 说 ， 他 要 受 许 多 的 苦 被 人 轻 慢 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24552', '41', '9', '13', '我 告 诉 你 们 ， 以 利 亚 已 经 来 了 ， 他 们 也 任 意 待 他 ， 正 如 经 上 所 指 着 他 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24553', '41', '9', '14', '＜ 治 好 被 污 鬼 附 身 的 孩 子 （ 太   1 7 : 1 4 - 2 1 ； 路   9 : 3 7 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24554', '41', '9', '15', '众 人 一 见 耶 稣 ， 都 甚 希 奇 ， 就 跑 上 去 问 他 的 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24555', '41', '9', '16', '耶 稣 问 他 们 说 ： “ 你 们 和 他 们 辩 论 的 是 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24556', '41', '9', '17', '众 人 中 间 有 一 个 人 回 答 说 ： “ 夫 子 ， 我 带 了 我 的 儿 子 到 你 这 里 来 ， 他 被 哑 巴 鬼 附 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24557', '41', '9', '18', '无 论 在 哪 里 ， 鬼 捉 弄 他 ， 把 他 摔 倒 ， 他 就 口 中 流 沫 ， 咬 牙 切 齿 ， 身 体 枯 干 。 我 请 过 你 的 门 徒 把 鬼 赶 出 去 ， 他 们 却 是 不 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24558', '41', '9', '19', '耶 稣 说 ： “ 嗳 ！ 不 信 的 世 代 啊 ， 我 在 你 们 这 里 要 到 几 时 呢 ？ 我 忍 耐 你 们 要 到 几 时 呢 ？ 把 他 带 到 我 这 里 来 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24559', '41', '9', '20', '他 们 就 带 了 他 来 。 他 一 见 耶 稣 ， 鬼 便 叫 他 重 重 地 抽 疯 ， 倒 在 地 上 ， 翻 来 覆 去 ， 口 中 流 沫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24560', '41', '9', '21', '耶 稣 问 他 父 亲 说 ： “ 他 得 这 病 有 多 少 日 子 呢 ？ ” 回 答 说 ： “ 从 小 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24561', '41', '9', '22', '鬼 屡 次 把 他 扔 在 火 里 、 水 里 ， 要 灭 他 。 你 若 能 做 什 么 ， 求 你 怜 悯 我 们 ， 帮 助 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24562', '41', '9', '23', '耶 稣 对 他 说 ： “ 你 若 能 信 ， 在 信 的 人 ， 凡 事 都 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24563', '41', '9', '24', '孩 子 的 父 亲 立 时 喊 着 说 ｛ 有 古 卷 ： 立 时 流 泪 地 喊 着 说 ｝ ： “ 我 信 ！ 但 我 信 不 足 ， 求 主 帮 助 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24564', '41', '9', '25', '耶 稣 看 见 众 人 都 跑 上 来 ， 就 斥 责 那 污 鬼 ， 说 ： “ 你 这 聋 哑 的 鬼 ， 我 吩 咐 你 从 他 里 头 出 来 ， 再 不 要 进 去 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24565', '41', '9', '26', '那 鬼 喊 叫 ， 使 孩 子 大 大 地 抽 了 一 阵 疯 ， 就 出 来 了 。 孩 子 好 像 死 了 一 般 。 以 致 众 人 多 半 说 ： “ 他 是 死 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24566', '41', '9', '27', '但 耶 稣 拉 着 他 的 手 ， 扶 他 起 来 ， 他 就 站 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24567', '41', '9', '28', '耶 稣 进 了 屋 子 ， 门 徒 就 暗 暗 地 问 他 说 ： “ 我 们 为 什 么 不 能 赶 出 他 去 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24568', '41', '9', '29', '耶 稣 说 ： “ 非 用 祷 告 ｛ 有 古 卷 加 ： 禁 食 二 字 ｝ ， 这 一 类 的 鬼 总 不 能 出 来 ｛ 或 译 ： 不 能 赶 他 出 来 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24569', '41', '9', '30', '＜ 耶 稣 第 二 次 预 言 受 难 和 复 活 （ 太   1 7 : 2 2 - 2 3 ； 路   9 : 4 3 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24570', '41', '9', '31', '于 是 教 训 门 徒 ， 说 ： “ 人 子 将 要 被 交 在 人 手 里 ， 他 们 要 杀 害 他 ； 被 杀 以 后 ， 过 三 天 他 要 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24571', '41', '9', '32', '门 徒 却 不 明 白 这 话 ， 又 不 敢 问 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24572', '41', '9', '33', '＜ 谁 最 伟 大 （ 太   1 8 : 1 - 5 ； 路   9 : 4 6 - 4 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24573', '41', '9', '34', '门 徒 不 作 声 ， 因 为 他 们 在 路 上 彼 此 争 论 谁 为 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24574', '41', '9', '35', '耶 稣 坐 下 ， 叫 十 二 个 门 徒 来 ， 说 ： “ 若 有 人 愿 意 作 首 先 的 ， 他 必 作 众 人 末 后 的 ， 作 众 人 的 用 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24575', '41', '9', '36', '于 是 领 过 一 个 小 孩 子 来 ， 叫 他 站 在 门 徒 中 间 ， 又 抱 起 他 来 ， 对 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24576', '41', '9', '37', '“ 凡 为 我 名 接 待 一 个 像 这 小 孩 子 的 ， 就 是 接 待 我 ； 凡 接 待 我 的 ， 不 是 接 待 我 ， 乃 是 接 待 那 差 我 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24577', '41', '9', '38', '＜ 不 敌 挡 我 们 就 是 帮 助 我 们 （ 路   9 : 4 9 - 5 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24578', '41', '9', '39', '耶 稣 说 ： “ 不 要 禁 止 他 ； 因 为 没 有 人 奉 我 名 行 异 能 ， 反 倒 轻 易 毁 谤 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24579', '41', '9', '40', '不 敌 挡 我 们 的 ， 就 是 帮 助 我 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24580', '41', '9', '41', '凡 因 你 们 是 属 基 督 ， 给 你 们 一 杯 水 喝 的 ， 我 实 在 告 诉 你 们 ， 他 不 能 不 得 赏 赐 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24581', '41', '9', '42', '＜ 罪 的 诱 惑 （ 太   1 8 : 6 - 9 ； 路   1 7 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24582', '41', '9', '43', '倘 若 你 一 只 手 叫 你 跌 倒 ， 就 把 它 砍 下 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24583', '41', '9', '44', '你 缺 了 肢 体 进 入 永 生 ， 强 如 有 两 只 手 落 到 地 狱 ， 入 那 不 灭 的 火 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24584', '41', '9', '45', '倘 若 你 一 只 脚 叫 你 跌 倒 ， 就 把 它 砍 下 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24585', '41', '9', '46', '你 瘸 腿 进 入 永 生 ， 强 如 有 两 只 脚 被 丢 在 地 狱 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24586', '41', '9', '47', '倘 若 你 一 只 眼 叫 你 跌 倒 ， 就 去 掉 它 ； 你 只 有 一 只 眼 进 入 神 的 国 ， 强 如 有 两 只 眼 被 丢 在 地 狱 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24587', '41', '9', '48', '在 那 里 ， 虫 是 不 死 的 ， 火 是 不 灭 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24588', '41', '9', '49', '因 为 必 用 火 当 盐 腌 各 人 。 ｛ 有 古 卷 加 ： 凡 祭 物 必 用 盐 腌 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24589', '41', '9', '50', '盐 本 是 好 的 ， 若 失 了 味 ， 可 用 什 么 叫 它 再 咸 呢 ？ 你 们 里 头 应 当 有 盐 ， 彼 此 和 睦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24590', '41', '10', '1', '＜ 休 妻 的 问 题 （ 太   1 9 : 1 - 1 2 ； 路   1 6 : 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24591', '41', '10', '2', '有 法 利 赛 人 来 问 他 说 ： “ 人 休 妻 可 以 不 可 以 ？ ” 意 思 要 试 探 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24592', '41', '10', '3', '耶 稣 回 答 说 ： “ 摩 西 吩 咐 你 们 的 是 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24593', '41', '10', '4', '他 们 说 ： “ 摩 西 许 人 写 了 休 书 便 可 以 休 妻 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24594', '41', '10', '5', '耶 稣 说 ： “ 摩 西 因 为 你 们 的 心 硬 ， 所 以 写 这 条 例 给 你 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24595', '41', '10', '6', '但 从 起 初 创 造 的 时 候 ， 神 造 人 是 造 男 造 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24596', '41', '10', '7', '因 此 ， 人 要 离 开 父 母 ， 与 妻 子 连 合 ， 二 人 成 为 一 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24597', '41', '10', '8', '既 然 如 此 ， 夫 妻 不 再 是 两 个 人 ， 乃 是 一 体 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24598', '41', '10', '9', '所 以 ， 神 配 合 的 ， 人 不 可 分 开 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24599', '41', '10', '10', '到 了 屋 里 ， 门 徒 就 问 他 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24600', '41', '10', '11', '耶 稣 对 他 们 说 ： “ 凡 休 妻 另 娶 的 ， 就 是 犯 奸 淫 ， 辜 负 他 的 妻 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24601', '41', '10', '12', '妻 子 若 离 弃 丈 夫 另 嫁 ， 也 是 犯 奸 淫 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24602', '41', '10', '13', '＜ 耶 稣 为 小 孩 祝 福 （ 太   1 9 : 1 3 - 1 5 ； 路   1 8 : 1 5 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24603', '41', '10', '14', '耶 稣 看 见 就 恼 怒 ， 对 门 徒 说 ： “ 让 小 孩 子 到 我 这 里 来 ， 不 要 禁 止 他 们 ； 因 为 在 神 国 的 ， 正 是 这 样 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24604', '41', '10', '15', '我 实 在 告 诉 你 们 ， 凡 要 承 受 神 国 的 ， 若 不 像 小 孩 子 ， 断 不 能 进 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24605', '41', '10', '16', '于 是 抱 着 小 孩 子 ， 给 他 们 按 手 ， 为 他 们 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24606', '41', '10', '17', '＜ 财 主 寻 求 永 生 之 道 （ 太   1 9 : 1 6 - 3 0 ； 路   1 8 : 1 8 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24607', '41', '10', '18', '耶 稣 对 他 说 ： “ 你 为 什 么 称 我 是 良 善 的 ？ 除 了 神 一 位 之 外 ， 再 没 有 良 善 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24608', '41', '10', '19', '诫 命 你 是 晓 得 的 ： 不 可 杀 人 ； 不 可 奸 淫 ； 不 可 偷 盗 ； 不 可 作 假 见 证 ； 不 可 亏 负 人 ； 当 孝 敬 父 母 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24609', '41', '10', '20', '他 对 耶 稣 说 ： “ 夫 子 ， 这 一 切 我 从 小 都 遵 守 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24610', '41', '10', '21', '耶 稣 看 着 他 ， 就 爱 他 ， 对 他 说 ： “ 你 还 缺 少 一 件 ： 去 变 卖 你 所 有 的 ， 分 给 穷 人 ， 就 必 有 财 宝 在 天 上 ； 你 还 要 来 跟 从 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24611', '41', '10', '22', '他 听 见 这 话 ， 脸 上 就 变 了 色 ， 忧 忧 愁 愁 地 走 了 ， 因 为 他 的 产 业 很 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24612', '41', '10', '23', '耶 稣 周 围 一 看 ， 对 门 徒 说 ： “ 有 钱 财 的 人 进 神 的 国 是 何 等 地 难 哪 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24613', '41', '10', '24', '门 徒 希 奇 他 的 话 。 耶 稣 又 对 他 们 说 ： “ 小 子 ， 倚 靠 钱 财 的 人 进 神 的 国 是 何 等 地 难 哪 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24614', '41', '10', '25', '骆 驼 穿 过 针 的 眼 ， 比 财 主 进 神 的 国 还 容 易 呢 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24615', '41', '10', '26', '门 徒 就 分 外 希 奇 ， 对 他 说 ： “ 这 样 谁 能 得 救 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24616', '41', '10', '27', '耶 稣 看 着 他 们 ， 说 ： “ 在 人 是 不 能 ， 在 神 却 不 然 ， 因 为 神 凡 事 都 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24617', '41', '10', '28', '彼 得 就 对 他 说 ： “ 看 哪 ， 我 们 已 经 撇 下 所 有 的 跟 从 你 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24618', '41', '10', '29', '耶 稣 说 ： “ 我 实 在 告 诉 你 们 ， 人 为 我 和 福 音 撇 下 房 屋 ， 或 是 弟 兄 、 姊 妹 、 父 母 、 儿 女 、 田 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24619', '41', '10', '30', '没 有 不 在 今 世 得 百 倍 的 ， 就 是 房 屋 、 弟 兄 、 姊 妹 、 母 亲 、 儿 女 、 田 地 ， 并 且 要 受 逼 迫 ， 在 来 世 必 得 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24620', '41', '10', '31', '然 而 ， 有 许 多 在 前 的 ， 将 要 在 后 ， 在 后 的 ， 将 要 在 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24621', '41', '10', '32', '＜ 耶 稣 第 三 次 预 言 受 难 和 复 活 （ 太   2 0 : 1 7 - 1 9 ； 路   1 8 : 3 1 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24622', '41', '10', '33', '“ 看 哪 ， 我 们 上 耶 路 撒 冷 去 ， 人 子 将 要 被 交 给 祭 司 长 和 文 士 ， 他 们 要 定 他 死 罪 ， 交 给 外 邦 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24623', '41', '10', '34', '他 们 要 戏 弄 他 ， 吐 唾 沫 在 他 脸 上 ， 鞭 打 他 ， 杀 害 他 。 过 了 三 天 ， 他 要 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24624', '41', '10', '35', '＜ 雅 各 和 约 翰 的 要 求 （ 太   2 0 : 2 0 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24625', '41', '10', '36', '耶 稣 说 ： “ 要 我 给 你 们 做 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24626', '41', '10', '37', '他 们 说 ： “ 赐 我 们 在 你 的 荣 耀 里 ， 一 个 坐 在 你 右 边 ， 一 个 坐 在 你 左 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24627', '41', '10', '38', '耶 稣 说 ： “ 你 们 不 知 道 所 求 的 是 什 么 ， 我 所 喝 的 杯 ， 你 们 能 喝 吗 ？ 我 所 受 的 洗 ， 你 们 能 受 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24628', '41', '10', '39', '他 们 说 ： “ 我 们 能 。 ” 耶 稣 说 ： “ 我 所 喝 的 杯 ， 你 们 也 要 喝 ； 我 所 受 的 洗 ， 你 们 也 要 受 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24629', '41', '10', '40', '只 是 坐 在 我 的 左 右 ， 不 是 我 可 以 赐 的 ， 乃 是 为 谁 预 备 的 ， 就 赐 给 谁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24630', '41', '10', '41', '那 十 个 门 徒 听 见 ， 就 恼 怒 雅 各 、 约 翰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24631', '41', '10', '42', '耶 稣 叫 他 们 来 ， 对 他 们 说 ： “ 你 们 知 道 ， 外 邦 人 有 尊 为 君 王 的 ， 治 理 他 们 ， 有 大 臣 操 权 管 束 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24632', '41', '10', '43', '只 是 在 你 们 中 间 ， 不 是 这 样 。 你 们 中 间 ， 谁 愿 为 大 ， 就 必 作 你 们 的 用 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24633', '41', '10', '44', '在 你 们 中 间 ， 谁 愿 为 首 ， 就 必 作 众 人 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24634', '41', '10', '45', '因 为 人 子 来 ， 并 不 是 要 受 人 的 服 事 ， 乃 是 要 服 事 人 ， 并 且 要 舍 命 作 多 人 的 赎 价 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24635', '41', '10', '46', '＜ 治 好 瞎 子 巴 底 买 （ 太   2 0 : 2 9 - 3 4 ； 路   1 8 : 3 5 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24636', '41', '10', '47', '他 听 见 是 拿 撒 勒 的 耶 稣 ， 就 喊 着 说 ： “ 大 卫 的 子 孙 耶 稣 啊 ！ 可 怜 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24637', '41', '10', '48', '有 许 多 人 责 备 他 ， 不 许 他 作 声 。 他 却 越 发 大 声 喊 着 说 ： “ 大 卫 的 子 孙 哪 ， 可 怜 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24638', '41', '10', '49', '耶 稣 就 站 住 ， 说 ： “ 叫 过 他 来 。 ” 他 们 就 叫 那 瞎 子 ， 对 他 说 ： “ 放 心 ， 起 来 ！ 他 叫 你 啦 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24639', '41', '10', '50', '瞎 子 就 丢 下 衣 服 ， 跳 起 来 ， 走 到 耶 稣 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24640', '41', '10', '51', '耶 稣 说 ： “ 要 我 为 你 做 什 么 ？ ” 瞎 子 说 ： “ 拉 波 尼 ｛ 就 是 夫 子 ｝ ， 我 要 能 看 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24641', '41', '10', '52', '耶 稣 说 ： “ 你 去 吧 ！ 你 的 信 救 了 你 了 。 ” 瞎 子 立 刻 看 见 了 ， 就 在 路 上 跟 随 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24642', '41', '11', '1', '＜ 光 荣 地 进 耶 路 撒 冷 （ 太   2 1 : 1 - 1 1 ； 路   1 9 : 2 8 - 4 0 ； 约   1 2 : 1 2 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24643', '41', '11', '2', '对 他 们 说 ： “ 你 们 往 对 面 村 子 里 去 ， 一 进 去 的 时 候 ， 必 看 见 一 匹 驴 驹 拴 在 那 里 ， 是 从 来 没 有 人 骑 过 的 ， 可 以 解 开 ， 牵 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24644', '41', '11', '3', '若 有 人 对 你 们 说 ： ‘ 为 什 么 做 这 事 ？ ’ 你 们 就 说 ： ‘ 主 要 用 它 。 ’ 那 人 必 立 时 让 你 们 牵 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24645', '41', '11', '4', '他 们 去 了 ， 便 看 见 一 匹 驴 驹 拴 在 门 外 街 道 上 ， 就 把 它 解 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24646', '41', '11', '5', '在 那 里 站 着 的 人 ， 有 几 个 说 ： “ 你 们 解 驴 驹 做 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24647', '41', '11', '6', '门 徒 照 着 耶 稣 所 说 的 回 答 ， 那 些 人 就 任 凭 他 们 牵 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24648', '41', '11', '7', '他 们 把 驴 驹 牵 到 耶 稣 那 里 ， 把 自 己 的 衣 服 搭 在 上 面 ， 耶 稣 就 骑 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24649', '41', '11', '8', '有 许 多 人 把 衣 服 铺 在 路 上 ， 也 有 人 把 田 间 的 树 枝 砍 下 来 ， 铺 在 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24650', '41', '11', '9', '前 行 后 随 的 人 都 喊 着 说 ： 和 散 那 ｛ 和 散 那 ： 原 有 求 救 的 意 思 ， 在 此 乃 是 称 颂 的 话 ｝ ！ 奉 主 名 来 的 是 应 当 称 颂 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24651', '41', '11', '10', '那 将 要 来 的 我 祖 大 卫 之 国 是 应 当 称 颂 的 ！ 高 高 在 上 和 散 那 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24652', '41', '11', '11', '耶 稣 进 了 耶 路 撒 冷 ， 入 了 圣 殿 ， 周 围 看 了 各 样 物 件 。 天 色 已 晚 ， 就 和 十 二 个 门 徒 出 城 ， 往 伯 大 尼 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24653', '41', '11', '12', '＜ 咒 诅 无 花 果 树 （ 太   2 1 : 1 8 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24654', '41', '11', '13', '远 远 地 看 见 一 棵 无 花 果 树 ， 树 上 有 叶 子 ， 就 往 那 里 去 ， 或 者 在 树 上 可 以 找 着 什 么 。 到 了 树 下 ， 竟 找 不 着 什 么 ， 不 过 有 叶 子 ， 因 为 不 是 收 无 花 果 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24655', '41', '11', '14', '耶 稣 就 对 树 说 ： “ 从 今 以 后 ， 永 没 有 人 吃 你 的 果 子 。 ” 他 的 门 徒 也 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24656', '41', '11', '15', '＜ 洁 净 圣 殿 （ 太   2 1 : 1 2 - 1 7 ； 路   1 9 : 4 5 - 4 8 ； 约   2 : 1 3 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24657', '41', '11', '16', '也 不 许 人 拿 着 器 具 从 殿 里 经 过 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24658', '41', '11', '17', '便 教 训 他 们 说 ： “ 经 上 不 是 记 着 说 ： 我 的 殿 必 称 为 万 国 祷 告 的 殿 吗 ？ 你 们 倒 使 它 成 为 贼 窝 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24659', '41', '11', '18', '祭 司 长 和 文 士 听 见 这 话 ， 就 想 法 子 要 除 灭 耶 稣 ， 却 又 怕 他 ， 因 为 众 人 都 希 奇 他 的 教 训 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24660', '41', '11', '19', '每 天 晚 上 ， 耶 稣 出 城 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24661', '41', '11', '20', '＜ 从 无 花 果 树 得 教 训 （ 太   2 1 : 2 0 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24662', '41', '11', '21', '彼 得 想 起 耶 稣 的 话 来 ， 就 对 他 说 ： “ 拉 比 ， 请 看 ！ 你 所 咒 诅 的 无 花 果 树 已 经 枯 干 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24663', '41', '11', '22', '耶 稣 回 答 说 ： “ 你 们 当 信 服 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24664', '41', '11', '23', '我 实 在 告 诉 你 们 ， 无 论 何 人 对 这 座 山 说 ： ‘ 你 挪 开 此 地 ， 投 在 海 里 ！ ’ 他 若 心 里 不 疑 惑 ， 只 信 他 所 说 的 必 成 ， 就 必 给 他 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24665', '41', '11', '24', '所 以 我 告 诉 你 们 ， 凡 你 们 祷 告 祈 求 的 ， 无 论 是 什 么 ， 只 要 信 是 得 着 的 ， 就 必 得 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24666', '41', '11', '25', '你 们 站 着 祷 告 的 时 候 ， 若 想 起 有 人 得 罪 你 们 ， 就 当 饶 恕 他 ， 好 叫 你 们 在 天 上 的 父 也 饶 恕 你 们 的 过 犯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24667', '41', '11', '26', '你 们 若 不 饶 恕 人 ， 你 们 在 天 上 的 父 也 不 饶 恕 你 们 的 过 犯 。 ｛ 有 古 卷 无 此 节 ｝ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24668', '41', '11', '27', '＜ 质 问 耶 稣 的 权 柄 （ 太   2 1 : 2 3 - 2 7 ； 路   2 0 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24669', '41', '11', '28', '问 他 说 ： “ 你 仗 着 什 么 权 柄 做 这 些 事 ？ 给 你 这 权 柄 的 是 谁 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24670', '41', '11', '29', '耶 稣 对 他 们 说 ： “ 我 要 问 你 们 一 句 话 ， 你 们 回 答 我 ， 我 就 告 诉 你 们 我 仗 着 什 么 权 柄 做 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24671', '41', '11', '30', '约 翰 的 洗 礼 是 从 天 上 来 的 ？ 是 从 人 间 来 的 呢 ？ 你 们 可 以 回 答 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24672', '41', '11', '31', '他 们 彼 此 商 议 说 ： “ 我 们 若 说 ‘ 从 天 上 来 ’ ， 他 必 说 ： ‘ 这 样 ， 你 们 为 什 么 不 信 他 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24673', '41', '11', '32', '若 说 ‘ 从 人 间 来 ’ ， 却 又 怕 百 姓 ， 因 为 众 人 真 以 约 翰 为 先 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24674', '41', '11', '33', '于 是 回 答 耶 稣 说 ： “ 我 们 不 知 道 。 ” 耶 稣 说 ： “ 我 也 不 告 诉 你 们 我 仗 着 什 么 权 柄 做 这 些 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24675', '41', '12', '1', '＜ 凶 恶 园 户 的 比 喻 （ 太   2 1 : 3 3 - 4 6 ； 路   2 0 : 9 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24676', '41', '12', '2', '到 了 时 候 ， 打 发 一 个 仆 人 到 园 户 那 里 ， 要 从 园 户 收 葡 萄 园 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24677', '41', '12', '3', '园 户 拿 住 他 ， 打 了 他 ， 叫 他 空 手 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24678', '41', '12', '4', '再 打 发 一 个 仆 人 到 他 们 那 里 。 他 们 打 伤 他 的 头 ， 并 且 凌 辱 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24679', '41', '12', '5', '又 打 发 一 个 仆 人 去 ， 他 们 就 杀 了 他 。 后 又 打 发 好 些 仆 人 去 ， 有 被 他 们 打 的 ， 有 被 他 们 杀 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24680', '41', '12', '6', '园 主 还 有 一 位 是 他 的 爱 子 ， 末 后 又 打 发 他 去 ， 意 思 说 ： ‘ 他 们 必 尊 敬 我 的 儿 子 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24681', '41', '12', '7', '不 料 ， 那 些 园 户 彼 此 说 ： ‘ 这 是 承 受 产 业 的 。 来 吧 ， 我 们 杀 他 ， 产 业 就 归 我 们 了 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24682', '41', '12', '8', '于 是 拿 住 他 ， 杀 了 他 ， 把 他 丢 在 园 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24683', '41', '12', '9', '这 样 ， 葡 萄 园 的 主 人 要 怎 么 办 呢 ？ 他 要 来 除 灭 那 些 园 户 ， 将 葡 萄 园 转 给 别 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24684', '41', '12', '10', '经 上 写 着 说 ： 匠 人 所 弃 的 石 头 ， 已 作 了 房 角 的 头 块 石 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24685', '41', '12', '11', '这 是 主 所 做 的 ， 在 我 们 眼 中 看 为 希 奇 。 这 经 你 们 没 有 念 过 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24686', '41', '12', '12', '他 们 看 出 这 比 喻 是 指 着 他 们 说 的 ， 就 想 要 捉 拿 他 ， 只 是 惧 怕 百 姓 ， 于 是 离 开 他 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24687', '41', '12', '13', '＜ 纳 税 给 凯 撒 的 问 题 （ 太   2 2 : 1 5 - 2 2 ； 路   2 0 : 1 9 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24688', '41', '12', '14', '他 们 来 了 ， 就 对 他 说 ： “ 夫 子 ， 我 们 知 道 你 是 诚 实 的 ， 什 么 人 你 都 不 徇 情 面 ； 因 为 你 不 看 人 的 外 貌 ， 乃 是 诚 诚 实 实 传 神 的 道 。 纳 税 给 凯 撒 可 以 不 可 以 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24689', '41', '12', '15', '我 们 该 纳 不 该 纳 ？ ” 耶 稣 知 道 他 们 的 假 意 ， 就 对 他 们 说 ： “ 你 们 为 什 么 试 探 我 ？ 拿 一 个 银 钱 来 给 我 看 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24690', '41', '12', '16', '他 们 就 拿 了 来 。 耶 稣 说 ： “ 这 像 和 这 号 是 谁 的 ？ ” 他 们 说 ： “ 是 凯 撒 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24691', '41', '12', '17', '耶 稣 说 ： “ 凯 撒 的 物 当 归 给 凯 撒 ， 神 的 物 当 归 给 神 。 ” 他 们 就 很 希 奇 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24692', '41', '12', '18', '＜ 复 活 的 问 题 （ 太   2 2 : 2 3 - 3 3 ； 路   2 0 : 2 7 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24693', '41', '12', '19', '“ 夫 子 ， 摩 西 为 我 们 写 着 说 ： ‘ 人 若 死 了 ， 撇 下 妻 子 ， 没 有 孩 子 ， 他 兄 弟 当 娶 他 的 妻 ， 为 哥 哥 生 子 立 后 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24694', '41', '12', '20', '有 弟 兄 七 人 ， 第 一 个 娶 了 妻 ， 死 了 ， 没 有 留 下 孩 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24695', '41', '12', '21', '第 二 个 娶 了 她 ， 也 死 了 ， 没 有 留 下 孩 子 。 第 三 个 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24696', '41', '12', '22', '那 七 个 人 都 没 有 留 下 孩 子 ； 末 了 ， 那 妇 人 也 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24697', '41', '12', '23', '当 复 活 的 时 候 ， 她 是 哪 一 个 的 妻 子 呢 ？ 因 为 他 们 七 个 人 都 娶 过 她 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24698', '41', '12', '24', '耶 稣 说 ： “ 你 们 所 以 错 了 ， 岂 不 是 因 为 不 明 白 圣 经 ， 不 晓 得 神 的 大 能 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24699', '41', '12', '25', '人 从 死 里 复 活 ， 也 不 娶 也 不 嫁 ， 乃 像 天 上 的 使 者 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24700', '41', '12', '26', '论 到 死 人 复 活 ， 你 们 没 有 念 过 摩 西 的 书 荆 棘 篇 上 所 载 的 吗 ？ 神 对 摩 西 说 ： ‘ 我 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24701', '41', '12', '27', '神 不 是 死 人 的 神 ， 乃 是 活 人 的 神 。 你 们 是 大 错 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24702', '41', '12', '28', '＜ 最 大 的 诫 命 （ 太   2 2 : 3 4 - 4 0 ； 路   1 0 : 2 5 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24703', '41', '12', '29', '耶 稣 回 答 说 ： “ 第 一 要 紧 的 就 是 说 ： ‘ 以 色 列 啊 ， 你 要 听 ， 主 ─ ─ 我 们 神 是 独 一 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24704', '41', '12', '30', '你 要 尽 心 、 尽 性 、 尽 意 、 尽 力 爱 主 ─ ─ 你 的 神 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24705', '41', '12', '31', '其 次 就 是 说 ： ‘ 要 爱 人 如 己 。 ’ 再 没 有 比 这 两 条 诫 命 更 大 的 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24706', '41', '12', '32', '那 文 士 对 耶 稣 说 ： “ 夫 子 说 ， 神 是 一 位 ， 实 在 不 错 ； 除 了 他 以 外 ， 再 没 有 别 的 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24707', '41', '12', '33', '并 且 尽 心 、 尽 智 、 尽 力 爱 他 ， 又 爱 人 如 己 ， 就 比 一 切 燔 祭 和 各 样 祭 祀 好 的 多 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24708', '41', '12', '34', '耶 稣 见 他 回 答 的 有 智 慧 ， 就 对 他 说 ： “ 你 离 神 的 国 不 远 了 。 ” 从 此 以 后 ， 没 有 人 敢 再 问 他 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24709', '41', '12', '35', '＜ 大 卫 子 孙 的 问 题 （ 太   2 2 : 4 1 - 4 6 ； 路   2 0 : 4 1 - 4 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24710', '41', '12', '36', '大 卫 被 圣 灵 感 动 ， 说 ： 主 对 我 主 说 ， 你 坐 在 我 的 右 边 ， 等 我 使 你 仇 敌 作 你 的 脚 凳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24711', '41', '12', '37', '大 卫 既 自 己 称 他 为 主 ， 他 怎 么 又 是 大 卫 的 子 孙 呢 ？ ” 众 人 都 喜 欢 听 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24712', '41', '12', '38', '＜ 谴 责 文 士 （ 太   2 3 : 1 - 3 6 ； 路   2 0 : 4 5 - 4 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24713', '41', '12', '39', '又 喜 爱 会 堂 里 的 高 位 ， 筵 席 上 的 首 座 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24714', '41', '12', '40', '他 们 侵 吞 寡 妇 的 家 产 ， 假 意 作 很 长 的 祷 告 。 这 些 人 要 受 更 重 的 刑 罚 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24715', '41', '12', '41', '＜ 寡 妇 的 奉 献 （ 路   2 1 : 1 - 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24716', '41', '12', '42', '有 一 个 穷 寡 妇 来 ， 往 里 投 了 两 个 小 钱 ， 就 是 一 个 大 钱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24717', '41', '12', '43', '耶 稣 叫 门 徒 来 ， 说 ： “ 我 实 在 告 诉 你 们 ， 这 穷 寡 妇 投 入 库 里 的 ， 比 众 人 所 投 的 更 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24718', '41', '12', '44', '因 为 ， 他 们 都 是 自 己 有 余 ， 拿 出 来 投 在 里 头 ； 但 这 寡 妇 是 自 己 不 足 ， 把 她 一 切 养 生 的 都 投 上 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24719', '41', '13', '1', '＜ 预 言 圣 殿 被 毁 （ 太   2 4 : 1 - 2 ； 路   2 1 : 5 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24720', '41', '13', '2', '耶 稣 对 他 说 ： “ 你 看 见 这 大 殿 宇 吗 ？ 将 来 在 这 里 没 有 一 块 石 头 留 在 石 头 上 ， 不 被 拆 毁 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24721', '41', '13', '3', '＜ 灾 难 的 起 头 （ 太   2 4 : 3 - 1 4 ； 路   2 1 : 7 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24722', '41', '13', '4', '“ 请 告 诉 我 们 ， 什 么 时 候 有 这 些 事 呢 ？ 这 一 切 事 将 成 的 时 候 有 什 么 预 兆 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24723', '41', '13', '5', '耶 稣 说 ： “ 你 们 要 谨 慎 ， 免 得 有 人 迷 惑 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24724', '41', '13', '6', '将 来 有 好 些 人 冒 我 的 名 来 ， 说 ： ‘ 我 是 基 督 ’ ， 并 且 要 迷 惑 许 多 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24725', '41', '13', '7', '你 们 听 见 打 仗 和 打 仗 的 风 声 ， 不 要 惊 慌 。 这 些 事 是 必 须 有 的 ， 只 是 末 期 还 没 有 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24726', '41', '13', '8', '民 要 攻 打 民 ， 国 要 攻 打 国 ； 多 处 必 有 地 震 、 饥 荒 。 这 都 是 灾 难 ｛ 灾 难 ： 原 文 是 生 产 之 难 ｝ 的 起 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24727', '41', '13', '9', '但 你 们 要 谨 慎 ； 因 为 人 要 把 你 们 交 给 公 会 ， 并 且 你 们 在 会 堂 里 要 受 鞭 打 ， 又 为 我 的 缘 故 站 在 诸 侯 与 君 王 面 前 ， 对 他 们 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24728', '41', '13', '10', '然 而 ， 福 音 必 须 先 传 给 万 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24729', '41', '13', '11', '人 把 你 们 拉 去 交 官 的 时 候 ， 不 要 预 先 思 虑 说 什 么 ； 到 那 时 候 ， 赐 给 你 们 什 么 话 ， 你 们 就 说 什 么 ； 因 为 说 话 的 不 是 你 们 ， 乃 是 圣 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24730', '41', '13', '12', '弟 兄 要 把 弟 兄 ， 父 亲 要 把 儿 子 ， 送 到 死 地 ； 儿 女 要 起 来 与 父 母 为 敌 ， 害 死 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24731', '41', '13', '13', '并 且 你 们 要 为 我 的 名 被 众 人 恨 恶 。 惟 有 忍 耐 到 底 的 ， 必 然 得 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24732', '41', '13', '14', '＜ 大 灾 难 （ 太   2 4 : 1 5 - 2 8 ； 路   2 1 : 2 0 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24733', '41', '13', '15', '在 房 上 的 ， 不 要 下 来 ， 也 不 要 进 去 拿 家 里 的 东 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24734', '41', '13', '16', '在 田 里 的 ， 也 不 要 回 去 取 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24735', '41', '13', '17', '当 那 些 日 子 ， 怀 孕 的 和 奶 孩 子 的 有 祸 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24736', '41', '13', '18', '你 们 应 当 祈 求 ， 叫 这 些 事 不 在 冬 天 临 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24737', '41', '13', '19', '因 为 在 那 些 日 子 必 有 灾 难 ， 自 从 神 创 造 万 物 直 到 如 今 ， 并 没 有 这 样 的 灾 难 ， 后 来 也 必 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24738', '41', '13', '20', '若 不 是 主 减 少 那 日 子 ， 凡 有 血 气 的 ， 总 没 有 一 个 得 救 的 ； 只 是 为 主 的 选 民 ， 他 将 那 日 子 减 少 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24739', '41', '13', '21', '那 时 若 有 人 对 你 们 说 ： ‘ 看 哪 ， 基 督 在 这 里 ’ ， 或 说 ： ‘ 基 督 在 那 里 ’ ， 你 们 不 要 信 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24740', '41', '13', '22', '因 为 假 基 督 、 假 先 知 将 要 起 来 ， 显 神 迹 奇 事 ， 倘 若 能 行 ， 就 把 选 民 迷 惑 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24741', '41', '13', '23', '你 们 要 谨 慎 。 看 哪 ， 凡 事 我 都 预 先 告 诉 你 们 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24742', '41', '13', '24', '＜ 人 子 的 降 临 （ 太   2 4 : 2 9 - 3 1 ； 路   2 1 : 2 5 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24743', '41', '13', '25', '众 星 要 从 天 上 坠 落 ， 天 势 都 要 震 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24744', '41', '13', '26', '那 时 ， 他 们 ｛ 马 太 二 十 四 章 三 十 节 是 地 上 的 万 族 ｝ 要 看 见 人 子 有 大 能 力 、 大 荣 耀 ， 驾 云 降 临 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24745', '41', '13', '27', '他 要 差 遣 天 使 ， 把 他 的 选 民 ， 从 四 方 ｛ 方 ： 原 文 是 风 ｝ ， 从 地 极 直 到 天 边 ， 都 招 聚 了 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24746', '41', '13', '28', '＜ 从 无 花 果 树 学 个 比 方 （ 太   2 4 : 3 2 - 3 5 ； 路   2 1 : 2 9 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24747', '41', '13', '29', '这 样 ， 你 们 几 时 看 见 这 些 事 成 就 ， 也 该 知 道 人 子 ｛ 人 子 ： 或 译 神 的 国 ｝ 近 了 ， 正 在 门 口 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24748', '41', '13', '30', '我 实 在 告 诉 你 们 ， 这 世 代 还 没 有 过 去 ， 这 些 事 都 要 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24749', '41', '13', '31', '天 地 要 废 去 ， 我 的 话 却 不 能 废 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24750', '41', '13', '32', '＜ 那 日 那 时 没 有 人 知 道 （ 太   2 4 : 3 6 - 4 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24751', '41', '13', '33', '你 们 要 谨 慎 ， 警 醒 祈 祷 ， 因 为 你 们 不 晓 得 那 日 期 几 时 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24752', '41', '13', '34', '这 事 正 如 一 个 人 离 开 本 家 ， 寄 居 外 邦 ， 把 权 柄 交 给 仆 人 ， 分 派 各 人 当 做 的 工 ， 又 吩 咐 看 门 的 警 醒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24753', '41', '13', '35', '所 以 ， 你 们 要 警 醒 ； 因 为 你 们 不 知 道 家 主 什 么 时 候 来 ， 或 晚 上 ， 或 半 夜 ， 或 鸡 叫 ， 或 早 晨 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24754', '41', '13', '36', '恐 怕 他 忽 然 来 到 ， 看 见 你 们 睡 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24755', '41', '13', '37', '我 对 你 们 所 说 的 话 ， 也 是 对 众 人 说 ： 要 警 醒 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24756', '41', '14', '1', '＜ 杀 害 耶 稣 的 阴 谋 （ 太   2 6 : 1 - 5 ； 路   2 2 : 1 - 2 ； 约   1 1 : 4 5 - 5 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24757', '41', '14', '2', '只 是 说 ： “ 当 节 的 日 子 不 可 ， 恐 怕 百 姓 生 乱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24758', '41', '14', '3', '＜ 在 伯 大 尼 受 膏 （ 太   2 6 : 6 - 1 3 ； 约   1 2 : 1 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24759', '41', '14', '4', '有 几 个 人 心 中 很 不 喜 悦 ， 说 ： “ 何 用 这 样 枉 费 香 膏 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24760', '41', '14', '5', '这 香 膏 可 以 卖 三 十 多 两 银 子 赒 济 穷 人 。 ” 他 们 就 向 那 女 人 生 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24761', '41', '14', '6', '耶 稣 说 ： “ 由 她 吧 ！ 为 什 么 难 为 她 呢 ？ 她 在 我 身 上 做 的 是 一 件 美 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24762', '41', '14', '7', '因 为 常 有 穷 人 和 你 们 同 在 ， 要 向 他 们 行 善 随 时 都 可 以 ； 只 是 你 们 不 常 有 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24763', '41', '14', '8', '她 所 做 的 ， 是 尽 她 所 能 的 ； 她 是 为 我 安 葬 的 事 把 香 膏 预 先 浇 在 我 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24764', '41', '14', '9', '我 实 在 告 诉 你 们 ， 普 天 之 下 ， 无 论 在 什 么 地 方 传 这 福 音 ， 也 要 述 说 这 女 人 所 做 的 ， 以 为 记 念 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24765', '41', '14', '10', '＜ 犹 大 出 卖 耶 稣 （ 太   2 6 : 1 4 - 1 6 ； 路   2 2 : 3 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24766', '41', '14', '11', '他 们 听 见 就 欢 喜 ， 又 应 许 给 他 银 子 ； 他 就 寻 思 如 何 得 便 把 耶 稣 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24767', '41', '14', '12', '＜ 和 门 徒 同 度 逾 越 节 （ 太   2 6 : 1 7 - 2 5 ； 路   2 2 : 7 - 1 3 , 2 1 - 2 3 ； 约   1 3 : 2 1 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24768', '41', '14', '13', '耶 稣 就 打 发 两 个 门 徒 ， 对 他 们 说 ： “ 你 们 进 城 去 ， 必 有 人 拿 着 一 瓶 水 迎 面 而 来 ， 你 们 就 跟 着 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24769', '41', '14', '14', '他 进 哪 家 去 ， 你 们 就 对 那 家 的 主 人 说 ： ‘ 夫 子 说 ： 客 房 在 哪 里 ？ 我 与 门 徒 好 在 那 里 吃 逾 越 节 的 筵 席 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24770', '41', '14', '15', '他 必 指 给 你 们 摆 设 整 齐 的 一 间 大 楼 ， 你 们 就 在 那 里 为 我 们 预 备 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24771', '41', '14', '16', '门 徒 出 去 ， 进 了 城 ， 所 遇 见 的 正 如 耶 稣 所 说 的 。 他 们 就 预 备 了 逾 越 节 的 筵 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24772', '41', '14', '17', '到 了 晚 上 ， 耶 稣 和 十 二 个 门 徒 都 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24773', '41', '14', '18', '他 们 坐 席 正 吃 的 时 候 ， 耶 稣 说 ： “ 我 实 在 告 诉 你 们 ， 你 们 中 间 有 一 个 与 我 同 吃 的 人 要 卖 我 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24774', '41', '14', '19', '他 们 就 忧 愁 起 来 ， 一 个 一 个 地 问 他 说 ： “ 是 我 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24775', '41', '14', '20', '耶 稣 对 他 们 说 ： “ 是 十 二 个 门 徒 中 同 我 蘸 手 在 盘 子 里 的 那 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24776', '41', '14', '21', '人 子 必 要 去 世 ， 正 如 经 上 指 着 他 所 写 的 ； 但 卖 人 子 的 人 有 祸 了 ！ 那 人 不 生 在 世 上 倒 好 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24777', '41', '14', '22', '＜ 设 立 主 的 晚 餐 （ 太   2 6 : 2 6 - 3 0 ； 路   2 2 : 1 4 - 2 0 ； 林 前   1 1 : 2 3 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24778', '41', '14', '23', '又 拿 起 杯 来 ， 祝 谢 了 ， 递 给 他 们 ； 他 们 都 喝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24779', '41', '14', '24', '耶 稣 说 ： “ 这 是 我 立 约 的 血 ， 为 多 人 流 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24780', '41', '14', '25', '我 实 在 告 诉 你 们 ， 我 不 再 喝 这 葡 萄 汁 ， 直 到 我 在 神 的 国 里 喝 新 的 那 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24781', '41', '14', '26', '他 们 唱 了 诗 ， 就 出 来 ， 往 橄 榄 山 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24782', '41', '14', '27', '＜ 预 言 彼 得 不 认 主 （ 太   2 6 : 3 1 - 3 5 ； 路   2 2 : 3 1 - 3 4 ； 约   1 3 : 3 6 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24783', '41', '14', '28', '但 我 复 活 以 后 ， 要 在 你 们 以 先 往 加 利 利 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24784', '41', '14', '29', '彼 得 说 ： “ 众 人 虽 然 跌 倒 ， 我 总 不 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24785', '41', '14', '30', '耶 稣 对 他 说 ： “ 我 实 在 告 诉 你 ， 就 在 今 天 夜 里 ， 鸡 叫 两 遍 以 先 ， 你 要 三 次 不 认 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24786', '41', '14', '31', '彼 得 却 极 力 地 说 ： “ 我 就 是 必 须 和 你 同 死 ， 也 总 不 能 不 认 你 。 ” 众 门 徒 都 是 这 样 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24787', '41', '14', '32', '＜ 在 客 西 马 尼 祷 告 （ 太   2 6 : 3 6 - 4 6 ； 路   2 2 : 3 9 - 4 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24788', '41', '14', '33', '于 是 带 着 彼 得 、 雅 各 、 约 翰 同 去 ， 就 惊 恐 起 来 ， 极 其 难 过 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24789', '41', '14', '34', '对 他 们 说 ： “ 我 心 里 甚 是 忧 伤 ， 几 乎 要 死 ； 你 们 在 这 里 等 候 ， 警 醒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24790', '41', '14', '35', '他 就 稍 往 前 走 ， 俯 伏 在 地 ， 祷 告 说 ： “ 倘 若 可 行 ， 便 叫 那 时 候 过 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24791', '41', '14', '36', '他 说 ： “ 阿 爸 ！ 父 啊 ！ 在 你 凡 事 都 能 ； 求 你 将 这 杯 撤 去 。 然 而 ， 不 要 从 我 的 意 思 ， 只 要 从 你 的 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24792', '41', '14', '37', '耶 稣 回 来 ， 见 他 们 睡 着 了 ， 就 对 彼 得 说 ： “ 西 门 ， 你 睡 觉 吗 ？ 不 能 警 醒 片 时 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24793', '41', '14', '38', '总 要 警 醒 祷 告 ， 免 得 入 了 迷 惑 。 你 们 心 灵 固 然 愿 意 ， 肉 体 却 软 弱 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24794', '41', '14', '39', '耶 稣 又 去 祷 告 ， 说 的 话 还 是 与 先 前 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24795', '41', '14', '40', '又 来 见 他 们 睡 着 了 ， 因 为 他 们 的 眼 睛 甚 是 困 倦 ； 他 们 也 不 知 道 怎 么 回 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24796', '41', '14', '41', '第 三 次 来 ， 对 他 们 说 ： “ 现 在 你 们 仍 然 睡 觉 安 歇 吧 ｛ 吧 ： 或 译 吗 ？ ｝ ！ 够 了 ， 时 候 到 了 。 看 哪 ， 人 子 被 卖 在 罪 人 手 里 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24797', '41', '14', '42', '起 来 ！ 我 们 走 吧 。 看 哪 ， 那 卖 我 的 人 近 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24798', '41', '14', '43', '＜ 耶 稣 被 捕 （ 太   2 6 : 4 7 - 5 6 ； 路   2 2 : 4 7 - 5 3 ； 约   1 8 : 3 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24799', '41', '14', '44', '卖 耶 稣 的 人 曾 给 他 们 一 个 暗 号 ， 说 ： “ 我 与 谁 亲 嘴 ， 谁 就 是 他 。 你 们 把 他 拿 住 ， 牢 牢 靠 靠 地 带 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24800', '41', '14', '45', '犹 大 来 了 ， 随 即 到 耶 稣 跟 前 ， 说 ： “ 拉 比 ” ， 便 与 他 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24801', '41', '14', '46', '他 们 就 下 手 拿 住 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24802', '41', '14', '47', '旁 边 站 着 的 人 ， 有 一 个 拔 出 刀 来 ， 将 大 祭 司 的 仆 人 砍 了 一 刀 ， 削 掉 了 他 一 个 耳 朵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24803', '41', '14', '48', '耶 稣 对 他 们 说 ： “ 你 们 带 着 刀 棒 出 来 拿 我 ， 如 同 拿 强 盗 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24804', '41', '14', '49', '我 天 天 教 训 人 ， 同 你 们 在 殿 里 ， 你 们 并 没 有 拿 我 。 但 这 事 成 就 ， 为 要 应 验 经 上 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24805', '41', '14', '50', '门 徒 都 离 开 他 ， 逃 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24806', '41', '14', '51', '＜ 逃 走 的 少 年 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24807', '41', '14', '52', '他 却 丢 了 麻 布 ， 赤 身 逃 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24808', '41', '14', '53', '＜ 耶 稣 在 公 会 里 受 审 （ 太   2 6 : 5 7 - 6 8 ； 路   2 2 : 5 4 - 5 5 , 6 3 - 7 1 ； 约   1 8 : 1 3 - 1 4 , 1 9 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24809', '41', '14', '54', '彼 得 远 远 地 跟 着 耶 稣 ， 一 直 进 入 大 祭 司 的 院 里 ， 和 差 役 一 同 坐 在 火 光 里 烤 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24810', '41', '14', '55', '祭 司 长 和 全 公 会 寻 找 见 证 控 告 耶 稣 ， 要 治 死 他 ， 却 寻 不 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24811', '41', '14', '56', '因 为 有 好 些 人 作 假 见 证 告 他 ， 只 是 他 们 的 见 证 各 不 相 合 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24812', '41', '14', '57', '又 有 几 个 人 站 起 来 作 假 见 证 告 他 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24813', '41', '14', '58', '“ 我 们 听 见 他 说 ： ‘ 我 要 拆 毁 这 人 手 所 造 的 殿 ， 三 日 内 就 另 造 一 座 不 是 人 手 所 造 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24814', '41', '14', '59', '他 们 就 是 这 么 作 见 证 ， 也 是 各 不 相 合 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24815', '41', '14', '60', '大 祭 司 起 来 站 在 中 间 ， 问 耶 稣 说 ： “ 你 什 么 都 不 回 答 吗 ？ 这 些 人 作 见 证 告 你 的 是 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24816', '41', '14', '61', '耶 稣 却 不 言 语 ， 一 句 也 不 回 答 。 大 祭 司 又 问 他 说 ： “ 你 是 那 当 称 颂 者 的 儿 子 基 督 不 是 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24817', '41', '14', '62', '耶 稣 说 ： “ 我 是 。 你 们 必 看 见 人 子 坐 在 那 权 能 者 的 右 边 ， 驾 着 天 上 的 云 降 临 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24818', '41', '14', '63', '大 祭 司 就 撕 开 衣 服 ， 说 ： “ 我 们 何 必 再 用 见 证 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24819', '41', '14', '64', '你 们 已 经 听 见 他 这 僭 妄 的 话 了 。 你 们 的 意 见 如 何 ？ ” 他 们 都 定 他 该 死 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24820', '41', '14', '65', '就 有 人 吐 唾 沫 在 他 脸 上 ， 又 蒙 着 他 的 脸 ， 用 拳 头 打 他 ， 对 他 说 ： “ 你 说 预 言 吧 ！ ” 差 役 接 过 他 来 ， 用 手 掌 打 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24821', '41', '14', '66', '＜ 彼 得 三 次 不 认 主 （ 太   2 6 : 6 9 - 7 5 ； 路   2 2 : 5 6 - 6 2 ； 约   1 8 : 1 5 - 1 8 , 2 5 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24822', '41', '14', '67', '见 彼 得 烤 火 ， 就 看 着 他 ， 说 ： “ 你 素 来 也 是 同 拿 撒 勒 人 耶 稣 一 伙 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24823', '41', '14', '68', '彼 得 却 不 承 认 ， 说 ： “ 我 不 知 道 ， 也 不 明 白 你 说 的 是 什 么 。 ” 于 是 出 来 ， 到 了 前 院 ， 鸡 就 叫 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24824', '41', '14', '69', '那 使 女 看 见 他 ， 又 对 旁 边 站 着 的 人 说 ： “ 这 也 是 他 们 一 党 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24825', '41', '14', '70', '彼 得 又 不 承 认 。 过 了 不 多 的 时 候 ， 旁 边 站 着 的 人 又 对 彼 得 说 ： “ 你 真 是 他 们 一 党 的 ！ 因 为 你 是 加 利 利 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24826', '41', '14', '71', '彼 得 就 发 咒 起 誓 地 说 ： “ 我 不 认 得 你 们 说 的 这 个 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24827', '41', '14', '72', '立 时 鸡 叫 了 第 二 遍 。 彼 得 想 起 耶 稣 对 他 所 说 的 话 ： “ 鸡 叫 两 遍 以 先 ， 你 要 三 次 不 认 我 。 ” 思 想 起 来 ， 就 哭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24828', '41', '15', '1', '＜ 耶 稣 在 彼 拉 多 面 前 受 审 （ 太   2 7 : 1 - 2 , 1 1 - 1 4 ； 路   2 3 : 1 - 5 ； 约   1 8 : 2 8 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24829', '41', '15', '2', '彼 拉 多 问 他 说 ： “ 你 是 犹 太 人 的 王 吗 ？ ” 耶 稣 回 答 说 ： “ 你 说 的 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24830', '41', '15', '3', '祭 司 长 告 他 许 多 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24831', '41', '15', '4', '彼 拉 多 又 问 他 说 ： “ 你 看 ， 他 们 告 你 这 么 多 的 事 ， 你 什 么 都 不 回 答 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24832', '41', '15', '5', '耶 稣 仍 不 回 答 ， 以 致 彼 拉 多 觉 得 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24833', '41', '15', '6', '＜ 耶 稣 被 判 死 刑 （ 太   2 7 : 1 5 - 2 6 ； 路   2 3 : 1 3 - 2 5 ； 约   1 8 : 3 9 - 1 9 ： 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24834', '41', '15', '7', '有 一 个 人 名 叫 巴 拉 巴 ， 和 作 乱 的 人 一 同 捆 绑 。 他 们 作 乱 的 时 候 ， 曾 杀 过 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24835', '41', '15', '8', '众 人 上 去 求 巡 抚 ， 照 常 例 给 他 们 办 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24836', '41', '15', '9', '彼 拉 多 说 ： “ 你 们 要 我 释 放 犹 太 人 的 王 给 你 们 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24837', '41', '15', '10', '他 原 晓 得 ， 祭 司 长 是 因 为 嫉 妒 才 把 耶 稣 解 了 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24838', '41', '15', '11', '只 是 祭 司 长 挑 唆 众 人 ， 宁 可 释 放 巴 拉 巴 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24839', '41', '15', '12', '彼 拉 多 又 说 ： “ 那 么 样 ， 你 们 所 称 为 犹 太 人 的 王 ， 我 怎 么 办 他 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24840', '41', '15', '13', '他 们 又 喊 着 说 ： “ 把 他 钉 十 字 架 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24841', '41', '15', '14', '彼 拉 多 说 ： “ 为 什 么 呢 ？ 他 做 了 什 么 恶 事 呢 ？ ” 他 们 便 极 力 地 喊 着 说 ： “ 把 他 钉 十 字 架 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24842', '41', '15', '15', '彼 拉 多 要 叫 众 人 喜 悦 ， 就 释 放 巴 拉 巴 给 他 们 ， 将 耶 稣 鞭 打 了 ， 交 给 人 钉 十 字 架 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24843', '41', '15', '16', '＜ 兵 丁 戏 弄 耶 稣 （ 太   2 7 : 2 7 - 3 1 ； 约   1 9 : 2 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24844', '41', '15', '17', '他 们 给 他 穿 上 紫 袍 ， 又 用 荆 棘 编 做 冠 冕 给 他 戴 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24845', '41', '15', '18', '就 庆 贺 他 说 ： “ 恭 喜 ， 犹 太 人 的 王 啊 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24846', '41', '15', '19', '又 拿 一 根 苇 子 打 他 的 头 ， 吐 唾 沫 在 他 脸 上 ， 屈 膝 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24847', '41', '15', '20', '戏 弄 完 了 ， 就 给 他 脱 了 紫 袍 ， 仍 穿 上 他 自 己 的 衣 服 ， 带 他 出 去 ， 要 钉 十 字 架 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24848', '41', '15', '21', '＜ 耶 稣 被 钉 十 字 架 （ 太   2 7 : 3 2 - 4 4 ； 路   2 3 : 2 6 - 4 3 ； 约   1 9 : 1 7 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24849', '41', '15', '22', '他 们 带 耶 稣 到 了 各 各 他 地 方 （ 各 各 他 翻 出 来 就 是 髑 髅 地 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24850', '41', '15', '23', '拿 没 药 调 和 的 酒 给 耶 稣 ， 他 却 不 受 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24851', '41', '15', '24', '于 是 将 他 钉 在 十 字 架 上 ， 拈 阄 分 他 的 衣 服 ， 看 是 谁 得 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24852', '41', '15', '25', '钉 他 在 十 字 架 上 是 巳 初 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24853', '41', '15', '26', '在 上 面 有 他 的 罪 状 ， 写 的 是 ： “ 犹 太 人 的 王 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24854', '41', '15', '27', '他 们 又 把 两 个 强 盗 和 他 同 钉 十 字 架 ， 一 个 在 右 边 ， 一 个 在 左 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24855', '41', '15', '28', '｛ 有 古 卷 加 ： 这 就 应 了 经 上 的 话 说 ： 他 被 列 在 罪 犯 之 中 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24856', '41', '15', '29', '从 那 里 经 过 的 人 辱 骂 他 ， 摇 着 头 说 ： “ 咳 ！ 你 这 拆 毁 圣 殿 、 三 日 又 建 造 起 来 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24857', '41', '15', '30', '可 以 救 自 己 ， 从 十 字 架 上 下 来 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24858', '41', '15', '31', '祭 司 长 和 文 士 也 是 这 样 戏 弄 他 ， 彼 此 说 ： “ 他 救 了 别 人 ， 不 能 救 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24859', '41', '15', '32', '以 色 列 的 王 基 督 ， 现 在 可 以 从 十 字 架 上 下 来 ， 叫 我 们 看 见 ， 就 信 了 。 ” 那 和 他 同 钉 的 人 也 是 讥 诮 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24860', '41', '15', '33', '＜ 耶 稣 的 死 （ 太   2 7 : 4 5 - 5 6 ； 路   2 3 : 4 4 - 4 9 ； 约   1 9 : 2 8 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24861', '41', '15', '34', '申 初 的 时 候 ， 耶 稣 大 声 喊 着 说 ： “ 以 罗 伊 ！ 以 罗 伊 ！ 拉 马 撒 巴 各 大 尼 ？ ” （ 翻 出 来 就 是 ： 我 的 神 ！ 我 的 神 ！ 为 什 么 离 弃 我 ？ ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24862', '41', '15', '35', '旁 边 站 着 的 人 ， 有 的 听 见 就 说 ： “ 看 哪 ， 他 叫 以 利 亚 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24863', '41', '15', '36', '有 一 个 人 跑 去 ， 把 海 绒 蘸 满 了 醋 ， 绑 在 苇 子 上 ， 送 给 他 喝 ， 说 ： “ 且 等 着 ， 看 以 利 亚 来 不 来 把 他 取 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24864', '41', '15', '37', '耶 稣 大 声 喊 叫 ， 气 就 断 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24865', '41', '15', '38', '殿 里 的 幔 子 从 上 到 下 裂 为 两 半 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24866', '41', '15', '39', '对 面 站 着 的 百 夫 长 看 见 耶 稣 这 样 喊 叫 ｛ 有 古 卷 没 有 喊 叫 二 字 ｝ 断 气 ， 就 说 ： “ 这 人 真 是 神 的 儿 子 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24867', '41', '15', '40', '还 有 些 妇 女 远 远 地 观 看 ； 内 中 有 抹 大 拉 的 马 利 亚 ， 又 有 小 雅 各 和 约 西 的 母 亲 马 利 亚 ， 并 有 撒 罗 米 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24868', '41', '15', '41', '就 是 耶 稣 在 加 利 利 的 时 候 ， 跟 随 他 、 服 事 他 的 那 些 人 ， 还 有 同 耶 稣 上 耶 路 撒 冷 的 好 些 妇 女 在 那 里 观 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24869', '41', '15', '42', '＜ 耶 稣 的 安 葬 （ 太   2 7 : 5 7 - 6 1 ； 路   2 3 : 5 0 - 5 6 ； 约   1 9 : 3 8 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24870', '41', '15', '43', '有 亚 利 马 太 的 约 瑟 前 来 ， 他 是 尊 贵 的 议 士 ， 也 是 等 候 神 国 的 。 他 放 胆 进 去 见 彼 拉 多 ， 求 耶 稣 的 身 体 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24871', '41', '15', '44', '彼 拉 多 诧 异 耶 稣 已 经 死 了 ， 便 叫 百 夫 长 来 ， 问 他 耶 稣 死 了 久 不 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24872', '41', '15', '45', '既 从 百 夫 长 得 知 实 情 ， 就 把 耶 稣 的 尸 首 赐 给 约 瑟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24873', '41', '15', '46', '约 瑟 买 了 细 麻 布 ， 把 耶 稣 取 下 来 ， 用 细 麻 布 裹 好 ， 安 放 在 磐 石 中 凿 出 来 的 坟 墓 里 ， 又 滚 过 一 块 石 头 来 挡 住 墓 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24874', '41', '15', '47', '抹 大 拉 的 马 利 亚 和 约 西 的 母 亲 马 利 亚 都 看 见 安 放 他 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24875', '41', '16', '1', '＜ 耶 稣 复 活 （ 太   2 8 : 1 - 8 ； 路   2 4 : 1 - 1 2 ； 约   2 0 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24876', '41', '16', '2', '七 日 的 第 一 日 清 早 ， 出 太 阳 的 时 候 ， 她 们 来 到 坟 墓 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24877', '41', '16', '3', '彼 此 说 ： “ 谁 给 我 们 把 石 头 从 墓 门 滚 开 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24878', '41', '16', '4', '那 石 头 原 来 很 大 ， 她 们 抬 头 一 看 ， 却 见 石 头 已 经 滚 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24879', '41', '16', '5', '她 们 进 了 坟 墓 ， 看 见 一 个 少 年 人 坐 在 右 边 ， 穿 着 白 袍 ， 就 甚 惊 恐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24880', '41', '16', '6', '那 少 年 人 对 她 们 说 ： “ 不 要 惊 恐 ！ 你 们 寻 找 那 钉 十 字 架 的 拿 撒 勒 人 耶 稣 ， 他 已 经 复 活 了 ， 不 在 这 里 。 请 看 安 放 他 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24881', '41', '16', '7', '你 们 可 以 去 告 诉 他 的 门 徒 和 彼 得 ， 说 ： ‘ 他 在 你 们 以 先 往 加 利 利 去 。 在 那 里 你 们 要 见 他 ， 正 如 他 从 前 所 告 诉 你 们 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24882', '41', '16', '8', '她 们 就 出 来 ， 从 坟 墓 那 里 逃 跑 ， 又 发 抖 又 惊 奇 ， 什 么 也 不 告 诉 人 ， 因 为 她 们 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24883', '41', '16', '9', '＜ 向 抹 大 拉 的 马 利 亚 显 现 （ 太   2 8 : 9 - 1 0 ； 约   2 0 : 1 1 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24884', '41', '16', '10', '她 去 告 诉 那 向 来 跟 随 耶 稣 的 人 ； 那 时 他 们 正 哀 恸 哭 泣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24885', '41', '16', '11', '他 们 听 见 耶 稣 活 了 ， 被 马 利 亚 看 见 ， 却 是 不 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24886', '41', '16', '12', '＜ 向 两 个 门 徒 显 现 （ 路   2 4 : 1 3 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24887', '41', '16', '13', '他 们 就 去 告 诉 其 余 的 门 徒 ； 其 余 的 门 徒 也 是 不 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24888', '41', '16', '14', '＜ 门 徒 奉 差 遣 （ 太   2 8 : 1 6 - 2 0 ； 路   2 4 : 3 6 - 4 9 ； 约   2 0 : 1 9 - 2 3 ； 徒   1 : 6 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24889', '41', '16', '15', '他 又 对 他 们 说 ： “ 你 们 往 普 天 下 去 ， 传 福 音 给 万 民 ｛ 万 民 ： 原 文 是 凡 受 造 的 ｝ 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24890', '41', '16', '16', '信 而 受 洗 的 ， 必 然 得 救 ； 不 信 的 ， 必 被 定 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24891', '41', '16', '17', '信 的 人 必 有 神 迹 随 着 他 们 ， 就 是 奉 我 的 名 赶 鬼 ； 说 新 方 言 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24892', '41', '16', '18', '手 能 拿 蛇 ； 若 喝 了 什 么 毒 物 ， 也 必 不 受 害 ； 手 按 病 人 ， 病 人 就 必 好 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24893', '41', '16', '19', '＜ 耶 稣 升 天 （ 路   2 4 : 5 0 - 5 3 ； 徒   1 : 9 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24894', '41', '16', '20', '门 徒 出 去 ， 到 处 宣 传 福 音 。 主 和 他 们 同 工 ， 用 神 迹 随 着 ， 证 实 所 传 的 道 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24895', '42', '1', '1', '＜ 写 给 提 阿 非 罗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24896', '42', '1', '2', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24897', '42', '1', '3', '这 些 事 我 既 从 起 头 都 详 细 考 察 了 ， 就 定 意 要 按 着 次 序 写 给 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24898', '42', '1', '4', '使 你 知 道 所 学 之 道 都 是 确 实 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24899', '42', '1', '5', '＜ 预 言 施 洗 约 翰 的 诞 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24900', '42', '1', '6', '他 们 二 人 在 神 面 前 都 是 义 人 ， 遵 行 主 的 一 切 诫 命 礼 仪 ， 没 有 可 指 摘 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24901', '42', '1', '7', '只 是 没 有 孩 子 ； 因 为 伊 利 莎 白 不 生 育 ， 两 个 人 又 年 纪 老 迈 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24902', '42', '1', '8', '撒 迦 利 亚 按 班 次 在 神 面 前 供 祭 司 的 职 分 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24903', '42', '1', '9', '照 祭 司 的 规 矩 掣 签 ， 得 进 主 殿 烧 香 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24904', '42', '1', '10', '烧 香 的 时 候 ， 众 百 姓 在 外 面 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24905', '42', '1', '11', '有 主 的 使 者 站 在 香 坛 的 右 边 ， 向 他 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24906', '42', '1', '12', '撒 迦 利 亚 看 见 ， 就 惊 慌 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24907', '42', '1', '13', '天 使 对 他 说 ： “ 撒 迦 利 亚 ， 不 要 害 怕 ， 因 为 你 的 祈 祷 已 经 被 听 见 了 。 你 的 妻 子 伊 利 莎 白 要 给 你 生 一 个 儿 子 ， 你 要 给 他 起 名 叫 约 翰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24908', '42', '1', '14', '你 必 欢 喜 快 乐 ； 有 许 多 人 因 他 出 世 ， 也 必 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24909', '42', '1', '15', '他 在 主 面 前 将 要 为 大 ， 淡 酒 浓 酒 都 不 喝 ， 从 母 腹 里 就 被 圣 灵 充 满 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24910', '42', '1', '16', '他 要 使 许 多 以 色 列 人 回 转 ， 归 于 主 ─ ─ 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24911', '42', '1', '17', '他 必 有 以 利 亚 的 心 志 能 力 ， 行 在 主 的 前 面 ， 叫 为 父 的 心 转 向 儿 女 ， 叫 悖 逆 的 人 转 从 义 人 的 智 慧 ， 又 为 主 预 备 合 用 的 百 姓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24912', '42', '1', '18', '撒 迦 利 亚 对 天 使 说 ： “ 我 凭 着 什 么 可 知 道 这 事 呢 ？ 我 已 经 老 了 ， 我 的 妻 子 也 年 纪 老 迈 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24913', '42', '1', '19', '天 使 回 答 说 ： “ 我 是 站 在 神 面 前 的 加 百 列 ， 奉 差 而 来 对 你 说 话 ， 将 这 好 信 息 报 给 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24914', '42', '1', '20', '到 了 时 候 ， 这 话 必 然 应 验 ； 只 因 你 不 信 ， 你 必 哑 巴 ， 不 能 说 话 ， 直 到 这 事 成 就 的 日 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24915', '42', '1', '21', '百 姓 等 候 撒 迦 利 亚 ， 诧 异 他 许 久 在 殿 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24916', '42', '1', '22', '及 至 他 出 来 ， 不 能 和 他 们 说 话 ， 他 们 就 知 道 他 在 殿 里 见 了 异 象 ； 因 为 他 直 向 他 们 打 手 式 ， 竟 成 了 哑 巴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24917', '42', '1', '23', '他 供 职 的 日 子 已 满 ， 就 回 家 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24918', '42', '1', '24', '这 些 日 子 以 后 ， 他 的 妻 子 伊 利 莎 白 怀 了 孕 ， 就 隐 藏 了 五 个 月 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24919', '42', '1', '25', '说 ： “ 主 在 眷 顾 我 的 日 子 ， 这 样 看 待 我 ， 要 把 我 在 人 间 的 羞 耻 除 掉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24920', '42', '1', '26', '＜ 预 言 耶 稣 的 降 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24921', '42', '1', '27', '到 一 个 童 女 那 里 ， 是 已 经 许 配 大 卫 家 的 一 个 人 ， 名 叫 约 瑟 。 童 女 的 名 字 叫 马 利 亚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24922', '42', '1', '28', '天 使 进 去 ， 对 她 说 ： “ 蒙 大 恩 的 女 子 ， 我 问 你 安 ， 主 和 你 同 在 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24923', '42', '1', '29', '马 利 亚 因 这 话 就 很 惊 慌 ， 又 反 覆 思 想 这 样 问 安 是 什 么 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24924', '42', '1', '30', '天 使 对 她 说 ： “ 马 利 亚 ， 不 要 怕 ！ 你 在 神 面 前 已 经 蒙 恩 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24925', '42', '1', '31', '你 要 怀 孕 生 子 ， 可 以 给 他 起 名 叫 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24926', '42', '1', '32', '他 要 为 大 ， 称 为 至 高 者 的 儿 子 ； 主 神 要 把 他 祖 大 卫 的 位 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24927', '42', '1', '33', '他 要 作 雅 各 家 的 王 ， 直 到 永 远 ； 他 的 国 也 没 有 穷 尽 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24928', '42', '1', '34', '马 利 亚 对 天 使 说 ： “ 我 没 有 出 嫁 ， 怎 么 有 这 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24929', '42', '1', '35', '天 使 回 答 说 ： “ 圣 灵 要 临 到 你 身 上 ， 至 高 者 的 能 力 要 荫 庇 你 ， 因 此 所 要 生 的 圣 者 必 称 为 神 的 儿 子 ｛ 或 译 ： 所 要 生 的 ， 必 称 为 圣 ， 称 为 神 的 儿 子 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24930', '42', '1', '36', '况 且 你 的 亲 戚 伊 利 莎 白 ， 在 年 老 的 时 候 也 怀 了 男 胎 ， 就 是 那 素 来 称 为 不 生 育 的 ， 现 在 有 孕 六 个 月 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24931', '42', '1', '37', '因 为 ， 出 于 神 的 话 ， 没 有 一 句 不 带 能 力 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24932', '42', '1', '38', '马 利 亚 说 ： “ 我 是 主 的 使 女 ， 情 愿 照 你 的 话 成 就 在 我 身 上 。 ” 天 使 就 离 开 她 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24933', '42', '1', '39', '＜ 马 利 亚 访 问 伊 利 莎 白 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24934', '42', '1', '40', '进 了 撒 迦 利 亚 的 家 ， 问 伊 利 莎 白 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24935', '42', '1', '41', '伊 利 莎 白 一 听 马 利 亚 问 安 ， 所 怀 的 胎 就 在 腹 里 跳 动 。 伊 利 莎 白 且 被 圣 灵 充 满 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24936', '42', '1', '42', '高 声 喊 着 说 ： “ 你 在 妇 女 中 是 有 福 的 ！ 你 所 怀 的 胎 也 是 有 福 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24937', '42', '1', '43', '我 主 的 母 到 我 这 里 来 ， 这 是 从 哪 里 得 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24938', '42', '1', '44', '因 为 你 问 安 的 声 音 一 入 我 耳 ， 我 腹 里 的 胎 就 欢 喜 跳 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24939', '42', '1', '45', '这 相 信 的 女 子 是 有 福 的 ！ 因 为 主 对 她 所 说 的 话 都 要 应 验 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24940', '42', '1', '46', '＜ 马 利 亚 的 尊 主 颂 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24941', '42', '1', '47', '我 灵 以 神 我 的 救 主 为 乐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24942', '42', '1', '48', '因 为 他 顾 念 他 使 女 的 卑 微 ； 从 今 以 后 ， 万 代 要 称 我 有 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24943', '42', '1', '49', '那 有 权 能 的 ， 为 我 成 就 了 大 事 ； 他 的 名 为 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24944', '42', '1', '50', '他 怜 悯 敬 畏 他 的 人 ， 直 到 世 世 代 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24945', '42', '1', '51', '他 用 膀 臂 施 展 大 能 ； 那 狂 傲 的 人 正 心 里 妄 想 就 被 他 赶 散 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24946', '42', '1', '52', '他 叫 有 权 柄 的 失 位 ， 叫 卑 贱 的 升 高 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24947', '42', '1', '53', '叫 饥 饿 的 得 饱 美 食 ， 叫 富 足 的 空 手 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24948', '42', '1', '54', '他 扶 助 了 他 的 仆 人 以 色 列 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24949', '42', '1', '55', '为 要 记 念 亚 伯 拉 罕 和 他 的 后 裔 ， 施 怜 悯 直 到 永 远 ， 正 如 从 前 对 我 们 列 祖 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24950', '42', '1', '56', '马 利 亚 和 伊 利 莎 白 同 住 ， 约 有 三 个 月 ， 就 回 家 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24951', '42', '1', '57', '＜ 施 洗 约 翰 的 出 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24952', '42', '1', '58', '邻 里 亲 族 听 见 主 向 她 大 施 怜 悯 ， 就 和 她 一 同 欢 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24953', '42', '1', '59', '到 了 第 八 日 ， 他 们 来 要 给 孩 子 行 割 礼 ， 并 要 照 他 父 亲 的 名 字 叫 他 撒 迦 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24954', '42', '1', '60', '他 母 亲 说 ： “ 不 可 ！ 要 叫 他 约 翰 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24955', '42', '1', '61', '他 们 说 ： “ 你 亲 族 中 没 有 叫 这 名 字 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24956', '42', '1', '62', '他 们 就 向 他 父 亲 打 手 式 ， 问 他 要 叫 这 孩 子 什 么 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24957', '42', '1', '63', '他 要 了 一 块 写 字 的 板 ， 就 写 上 ， 说 ： “ 他 的 名 字 是 约 翰 。 ” 他 们 便 都 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24958', '42', '1', '64', '撒 迦 利 亚 的 口 立 时 开 了 ， 舌 头 也 舒 展 了 ， 就 说 出 话 来 ， 称 颂 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24959', '42', '1', '65', '周 围 居 住 的 人 都 惧 怕 ； 这 一 切 的 事 就 传 遍 了 犹 太 的 山 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24960', '42', '1', '66', '凡 听 见 的 人 都 将 这 事 放 在 心 里 ， 说 ： “ 这 个 孩 子 将 来 怎 么 样 呢 ？ 因 为 有 主 与 他 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24961', '42', '1', '67', '＜ 撒 迦 利 亚 的 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24962', '42', '1', '68', '主 ─ ─ 以 色 列 的 神 是 应 当 称 颂 的 ！ 因 他 眷 顾 他 的 百 姓 ， 为 他 们 施 行 救 赎 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24963', '42', '1', '69', '在 他 仆 人 大 卫 家 中 ， 为 我 们 兴 起 了 拯 救 的 角 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24964', '42', '1', '70', '正 如 主 藉 着 从 创 世 以 来 圣 先 知 的 口 所 说 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24965', '42', '1', '71', '拯 救 我 们 脱 离 仇 敌 和 一 切 恨 我 们 之 人 的 手 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24966', '42', '1', '72', '向 我 们 列 祖 施 怜 悯 ， 记 念 他 的 圣 约 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24967', '42', '1', '73', '就 是 他 对 我 们 祖 宗 亚 伯 拉 罕 所 起 的 誓 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24968', '42', '1', '74', '叫 我 们 既 从 仇 敌 手 中 被 救 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24969', '42', '1', '75', '就 可 以 终 身 在 他 面 前 ， 坦 然 无 惧 地 用 圣 洁 、 公 义 事 奉 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24970', '42', '1', '76', '孩 子 啊 ！ 你 要 称 为 至 高 者 的 先 知 ； 因 为 你 要 行 在 主 的 前 面 ， 预 备 他 的 道 路 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24971', '42', '1', '77', '叫 他 的 百 姓 因 罪 得 赦 ， 就 知 道 救 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24972', '42', '1', '78', '因 我 们 神 怜 悯 的 心 肠 ， 叫 清 晨 的 日 光 从 高 天 临 到 我 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24973', '42', '1', '79', '要 照 亮 坐 在 黑 暗 中 死 荫 里 的 人 ， 把 我 们 的 脚 引 到 平 安 的 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24974', '42', '1', '80', '那 孩 子 渐 渐 长 大 ， 心 灵 强 健 ， 住 在 旷 野 ， 直 到 他 显 明 在 以 色 列 人 面 前 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24975', '42', '2', '1', '＜ 耶 稣 降 生 （ 太   1 : 1 8 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24976', '42', '2', '2', '这 是 居 里 扭 作 叙 利 亚 巡 抚 的 时 候 ， 头 一 次 行 报 名 上 册 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24977', '42', '2', '3', '众 人 各 归 各 城 ， 报 名 上 册 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24978', '42', '2', '4', '约 瑟 也 从 加 利 利 的 拿 撒 勒 城 上 犹 太 去 ， 到 了 大 卫 的 城 ， 名 叫 伯 利 恒 ， 因 他 本 是 大 卫 一 族 一 家 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24979', '42', '2', '5', '要 和 他 所 聘 之 妻 马 利 亚 一 同 报 名 上 册 。 那 时 马 利 亚 的 身 孕 已 经 重 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24980', '42', '2', '6', '他 们 在 那 里 的 时 候 ， 马 利 亚 的 产 期 到 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24981', '42', '2', '7', '就 生 了 头 胎 的 儿 子 ， 用 布 包 起 来 ， 放 在 马 槽 里 ， 因 为 客 店 里 没 有 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24982', '42', '2', '8', '＜ 天 使 报 喜 讯 给 牧 羊 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24983', '42', '2', '9', '有 主 的 使 者 站 在 他 们 旁 边 ， 主 的 荣 光 四 面 照 着 他 们 ； 牧 羊 的 人 就 甚 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24984', '42', '2', '10', '那 天 使 对 他 们 说 ： “ 不 要 惧 怕 ！ 我 报 给 你 们 大 喜 的 信 息 ， 是 关 乎 万 民 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24985', '42', '2', '11', '因 今 天 在 大 卫 的 城 里 ， 为 你 们 生 了 救 主 ， 就 是 主 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24986', '42', '2', '12', '你 们 要 看 见 一 个 婴 孩 ， 包 着 布 ， 卧 在 马 槽 里 ， 那 就 是 记 号 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24987', '42', '2', '13', '忽 然 ， 有 一 大 队 天 兵 同 那 天 使 赞 美 神 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24988', '42', '2', '14', '在 至 高 之 处 荣 耀 归 与 神 ！ 在 地 上 平 安 归 与 他 所 喜 悦 的 人 ｛ 有 古 卷 ： 喜 悦 归 与 人 ｝ ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24989', '42', '2', '15', '众 天 使 离 开 他 们 ， 升 天 去 了 。 牧 羊 的 人 彼 此 说 ： “ 我 们 往 伯 利 恒 去 ， 看 看 所 成 的 事 ， 就 是 主 所 指 示 我 们 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24990', '42', '2', '16', '他 们 急 忙 去 了 ， 就 寻 见 马 利 亚 和 约 瑟 ， 又 有 那 婴 孩 卧 在 马 槽 里 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24991', '42', '2', '17', '既 然 看 见 ， 就 把 天 使 论 这 孩 子 的 话 传 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24992', '42', '2', '18', '凡 听 见 的 ， 就 诧 异 牧 羊 之 人 对 他 们 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24993', '42', '2', '19', '马 利 亚 却 把 这 一 切 的 事 存 在 心 里 ， 反 覆 思 想 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24994', '42', '2', '20', '牧 羊 的 人 回 去 了 ， 因 所 听 见 所 看 见 的 一 切 事 ， 正 如 天 使 向 他 们 所 说 的 ， 就 归 荣 耀 与 神 ， 赞 美 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24995', '42', '2', '21', '满 了 八 天 ， 就 给 孩 子 行 割 礼 ， 与 他 起 名 叫 耶 稣 ； 这 就 是 没 有 成 胎 以 前 ， 天 使 所 起 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24996', '42', '2', '22', '＜ 在 圣 殿 里 献 与 主 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24997', '42', '2', '23', '（ 正 如 主 的 律 法 上 所 记 ： “ 凡 头 生 的 男 子 必 称 圣 归 主 ； ” ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24998', '42', '2', '24', '又 要 照 主 的 律 法 上 所 说 ， 或 用 一 对 班 鸠 ， 或 用 两 只 雏 鸽 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('24999', '42', '2', '25', '在 耶 路 撒 冷 有 一 个 人 ， 名 叫 西 面 ； 这 人 又 公 义 又 虔 诚 ， 素 常 盼 望 以 色 列 的 安 慰 者 来 到 ， 又 有 圣 灵 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25000', '42', '2', '26', '他 得 了 圣 灵 的 启 示 ， 知 道 自 己 未 死 以 前 ， 必 看 见 主 所 立 的 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25001', '42', '2', '27', '他 受 了 圣 灵 的 感 动 ， 进 入 圣 殿 ， 正 遇 见 耶 稣 的 父 母 抱 着 孩 子 进 来 ， 要 照 律 法 的 规 矩 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25002', '42', '2', '28', '西 面 就 用 手 接 过 他 来 ， 称 颂 神 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25003', '42', '2', '29', '主 啊 ！ 如 今 可 以 照 你 的 话 ， 释 放 仆 人 安 然 去 世 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25004', '42', '2', '30', '因 为 我 的 眼 睛 已 经 看 见 你 的 救 恩 ─ ─');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25005', '42', '2', '31', '就 是 你 在 万 民 面 前 所 预 备 的 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25006', '42', '2', '32', '是 照 亮 外 邦 人 的 光 ， 又 是 你 民 以 色 列 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25007', '42', '2', '33', '孩 子 的 父 母 因 这 论 耶 稣 的 话 就 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25008', '42', '2', '34', '西 面 给 他 们 祝 福 ， 又 对 孩 子 的 母 亲 马 利 亚 说 ： “ 这 孩 子 被 立 ， 是 要 叫 以 色 列 中 许 多 人 跌 倒 ， 许 多 人 兴 起 ； 又 要 作 毁 谤 的 话 柄 ， 叫 许 多 人 心 里 的 意 念 显 露 出 来 ； 你 自 己 的 心 也 要 被 刀 刺 透 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25009', '42', '2', '35', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25010', '42', '2', '36', '又 有 女 先 知 ， 名 叫 亚 拿 ， 是 亚 设 支 派 法 内 力 的 女 儿 ， 年 纪 已 经 老 迈 ， 从 作 童 女 出 嫁 的 时 候 ， 同 丈 夫 住 了 七 年 就 寡 居 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25011', '42', '2', '37', '现 在 已 经 八 十 四 岁 ｛ 或 译 ： 就 寡 居 了 八 十 四 年 ｝ ， 并 不 离 开 圣 殿 ， 禁 食 祈 求 ， 昼 夜 事 奉 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25012', '42', '2', '38', '正 当 那 时 ， 她 进 前 来 称 谢 神 ， 将 孩 子 的 事 对 一 切 盼 望 耶 路 撒 冷 得 救 赎 的 人 讲 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25013', '42', '2', '39', '＜ 回 拿 撒 勒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25014', '42', '2', '40', '孩 子 渐 渐 长 大 ， 强 健 起 来 ， 充 满 智 慧 ， 又 有 神 的 恩 在 他 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25015', '42', '2', '41', '＜ 孩 童 耶 稣 在 圣 殿 里 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25016', '42', '2', '42', '当 他 十 二 岁 的 时 候 ， 他 们 按 着 节 期 的 规 矩 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25017', '42', '2', '43', '守 满 了 节 期 ， 他 们 回 去 ， 孩 童 耶 稣 仍 旧 在 耶 路 撒 冷 。 他 的 父 母 并 不 知 道 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25018', '42', '2', '44', '以 为 他 在 同 行 的 人 中 间 ， 走 了 一 天 的 路 程 ， 就 在 亲 族 和 熟 识 的 人 中 找 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25019', '42', '2', '45', '既 找 不 着 ， 就 回 耶 路 撒 冷 去 找 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25020', '42', '2', '46', '过 了 三 天 ， 就 遇 见 他 在 殿 里 ， 坐 在 教 师 中 间 ， 一 面 听 ， 一 面 问 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25021', '42', '2', '47', '凡 听 见 他 的 ， 都 希 奇 他 的 聪 明 和 他 的 应 对 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25022', '42', '2', '48', '他 父 母 看 见 就 很 希 奇 。 他 母 亲 对 他 说 ： “ 我 儿 ！ 为 什 么 向 我 们 这 样 行 呢 ？ 看 哪 ， 你 父 亲 和 我 伤 心 来 找 你 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25023', '42', '2', '49', '耶 稣 说 ： “ 为 什 么 找 我 呢 ？ 岂 不 知 我 应 当 以 我 父 的 事 为 念 吗 ｛ 或 译 ： 岂 不 知 我 应 当 在 我 父 的 家 里 吗 ｝ ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25024', '42', '2', '50', '他 所 说 的 这 话 ， 他 们 不 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25025', '42', '2', '51', '他 就 同 他 们 下 去 ， 回 到 拿 撒 勒 ， 并 且 顺 从 他 们 。 他 母 亲 把 这 一 切 的 事 都 存 在 心 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25026', '42', '2', '52', '耶 稣 的 智 慧 和 身 量 ｛ 或 译 ： 年 纪 ｝ ， 并 神 和 人 喜 爱 他 的 心 ， 都 一 齐 增 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25027', '42', '3', '1', '＜ 施 洗 约 翰 传 道 （ 太   3 : 1 - 1 2 ； 可   1 : 1 - 8 ； 约   1 : 1 9 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25028', '42', '3', '2', '亚 那 和 该 亚 法 作 大 祭 司 。 那 时 ， 撒 迦 利 亚 的 儿 子 约 翰 在 旷 野 里 ， 神 的 话 临 到 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25029', '42', '3', '3', '他 就 来 到 约 旦 河 一 带 地 方 ， 宣 讲 悔 改 的 洗 礼 ， 使 罪 得 赦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25030', '42', '3', '4', '正 如 先 知 以 赛 亚 书 上 所 记 的 话 ， 说 ： 在 旷 野 有 人 声 喊 着 说 ： 预 备 主 的 道 ， 修 直 他 的 路 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25031', '42', '3', '5', '一 切 山 洼 都 要 填 满 ； 大 小 山 冈 都 要 削 平 ！ 弯 弯 曲 曲 的 地 方 要 改 为 正 直 ； 高 高 低 低 的 道 路 要 改 为 平 坦 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25032', '42', '3', '6', '凡 有 血 气 的 ， 都 要 见 神 的 救 恩 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25033', '42', '3', '7', '约 翰 对 那 出 来 要 受 他 洗 的 众 人 说 ： “ 毒 蛇 的 种 类 ！ 谁 指 示 你 们 逃 避 将 来 的 忿 怒 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25034', '42', '3', '8', '你 们 要 结 出 果 子 来 ， 与 悔 改 的 心 相 称 。 不 要 自 己 心 里 说 ： ‘ 有 亚 伯 拉 罕 为 我 们 的 祖 宗 。 ’ 我 告 诉 你 们 ， 神 能 从 这 些 石 头 中 ， 给 亚 伯 拉 罕 兴 起 子 孙 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25035', '42', '3', '9', '现 在 斧 子 已 经 放 在 树 根 上 ， 凡 不 结 好 果 子 的 树 就 砍 下 来 ， 丢 在 火 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25036', '42', '3', '10', '众 人 问 他 说 ： “ 这 样 ， 我 们 当 做 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25037', '42', '3', '11', '约 翰 回 答 说 ： “ 有 两 件 衣 裳 的 ， 就 分 给 那 没 有 的 ； 有 食 物 的 ， 也 当 这 样 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25038', '42', '3', '12', '又 有 税 吏 来 要 受 洗 ， 问 他 说 ： “ 夫 子 ， 我 们 当 做 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25039', '42', '3', '13', '约 翰 说 ： “ 除 了 例 定 的 数 目 ， 不 要 多 取 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25040', '42', '3', '14', '又 有 兵 丁 问 他 说 ： “ 我 们 当 做 什 么 呢 ？ ” 约 翰 说 ： “ 不 要 以 强 暴 待 人 ， 也 不 要 讹 诈 人 ， 自 己 有 钱 粮 就 当 知 足 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25041', '42', '3', '15', '百 姓 指 望 基 督 来 的 时 候 ， 人 都 心 里 猜 疑 ， 或 者 约 翰 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25042', '42', '3', '16', '约 翰 说 ： “ 我 是 用 水 给 你 们 施 洗 ， 但 有 一 位 能 力 比 我 更 大 的 要 来 ， 我 就 是 给 他 解 鞋 带 也 不 配 。 他 要 用 圣 灵 与 火 给 你 们 施 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25043', '42', '3', '17', '他 手 里 拿 着 簸 箕 ， 要 扬 净 他 的 场 ， 把 麦 子 收 在 仓 里 ， 把 糠 用 不 灭 的 火 烧 尽 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25044', '42', '3', '18', '约 翰 又 用 许 多 别 的 话 劝 百 姓 ， 向 他 们 传 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25045', '42', '3', '19', '只 是 分 封 的 王 希 律 ， 因 他 兄 弟 之 妻 希 罗 底 的 缘 故 ， 并 因 他 所 行 的 一 切 恶 事 ， 受 了 约 翰 的 责 备 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25046', '42', '3', '20', '又 另 外 添 了 一 件 ， 就 是 把 约 翰 收 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25047', '42', '3', '21', '＜ 耶 稣 受 洗 （ 太   3 : 1 3 - 1 7 ； 可   1 : 9 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25048', '42', '3', '22', '圣 灵 降 临 在 他 身 上 ， 形 状 仿 佛 鸽 子 ； 又 有 声 音 从 天 上 来 ， 说 ： “ 你 是 我 的 爱 子 ， 我 喜 悦 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25049', '42', '3', '23', '＜ 耶 稣 的 家 谱 （ 太   1 : 1 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25050', '42', '3', '24', '希 里 是 玛 塔 的 儿 子 ； 玛 塔 是 利 未 的 儿 子 ； 利 未 是 麦 基 的 儿 子 ； 麦 基 是 雅 拿 的 儿 子 ； 雅 拿 是 约 瑟 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25051', '42', '3', '25', '约 瑟 是 玛 他 提 亚 的 儿 子 ； 玛 他 提 亚 是 亚 摩 斯 的 儿 子 ； 亚 摩 斯 是 拿 鸿 的 儿 子 ； 拿 鸿 是 以 斯 利 的 儿 子 ； 以 斯 利 是 拿 该 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25052', '42', '3', '26', '拿 该 是 玛 押 的 儿 子 ； 玛 押 是 玛 他 提 亚 的 儿 子 ； 玛 他 提 亚 是 西 美 的 儿 子 ； 西 美 是 约 瑟 的 儿 子 ； 约 瑟 是 犹 大 的 儿 子 ； 犹 大 是 约 亚 拿 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25053', '42', '3', '27', '约 亚 拿 是 利 撒 的 儿 子 ； 利 撒 是 所 罗 巴 伯 的 儿 子 ； 所 罗 巴 伯 是 撒 拉 铁 的 儿 子 ； 撒 拉 铁 是 尼 利 的 儿 子 ； 尼 利 是 麦 基 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25054', '42', '3', '28', '麦 基 是 亚 底 的 儿 子 ； 亚 底 是 哥 桑 的 儿 子 ； 哥 桑 是 以 摩 当 的 儿 子 ； 以 摩 当 是 珥 的 儿 子 ； 珥 是 约 细 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25055', '42', '3', '29', '约 细 是 以 利 以 谢 的 儿 子 ； 以 利 以 谢 是 约 令 的 儿 子 ； 约 令 是 玛 塔 的 儿 子 ； 玛 塔 是 利 未 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25056', '42', '3', '30', '利 未 是 西 缅 的 儿 子 ； 西 缅 是 犹 大 的 儿 子 ； 犹 大 是 约 瑟 的 儿 子 ； 约 瑟 是 约 南 的 儿 子 ； 约 南 是 以 利 亚 敬 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25057', '42', '3', '31', '以 利 亚 敬 是 米 利 亚 的 儿 子 ； 米 利 亚 是 买 南 的 儿 子 ； 买 南 是 玛 达 他 的 儿 子 ； 玛 达 他 是 拿 单 的 儿 子 ； 拿 单 是 大 卫 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25058', '42', '3', '32', '大 卫 是 耶 西 的 儿 子 ； 耶 西 是 俄 备 得 的 儿 子 ； 俄 备 得 是 波 阿 斯 的 儿 子 ； 波 阿 斯 是 撒 门 的 儿 子 ； 撒 门 是 拿 顺 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25059', '42', '3', '33', '拿 顺 是 亚 米 拿 达 的 儿 子 ； 亚 米 拿 达 是 亚 兰 的 儿 子 ； 亚 兰 是 希 斯 仑 的 儿 子 ； 希 斯 仑 是 法 勒 斯 的 儿 子 ； 法 勒 斯 是 犹 大 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25060', '42', '3', '34', '犹 大 是 雅 各 的 儿 子 ； 雅 各 是 以 撒 的 儿 子 ； 以 撒 是 亚 伯 拉 罕 的 儿 子 ； 亚 伯 拉 罕 是 他 拉 的 儿 子 ； 他 拉 是 拿 鹤 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25061', '42', '3', '35', '拿 鹤 是 西 鹿 的 儿 子 ； 西 鹿 是 拉 吴 的 儿 子 ； 拉 吴 是 法 勒 的 儿 子 ； 法 勒 是 希 伯 的 儿 子 ； 希 伯 是 沙 拉 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25062', '42', '3', '36', '沙 拉 是 该 南 的 儿 子 ； 该 南 是 亚 法 撒 的 儿 子 ； 亚 法 撒 是 闪 的 儿 子 ； 闪 是 挪 亚 的 儿 子 ； 挪 亚 是 拉 麦 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25063', '42', '3', '37', '拉 麦 是 玛 土 撒 拉 的 儿 子 ； 玛 土 撒 拉 是 以 诺 的 儿 子 ； 以 诺 是 雅 列 的 儿 子 ； 雅 列 是 玛 勒 列 的 儿 子 ； 玛 勒 列 是 该 南 的 儿 子 ； 该 南 是 以 挪 士 的 儿 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25064', '42', '3', '38', '以 挪 士 是 塞 特 的 儿 子 ； 塞 特 是 亚 当 的 儿 子 ； 亚 当 是 神 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25065', '42', '4', '1', '＜ 耶 稣 受 试 探 （ 太   4 : 1 - 1 1 ； 可   1 : 1 2 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25066', '42', '4', '2', '四 十 天 受 魔 鬼 的 试 探 。 那 些 日 子 没 有 吃 什 么 ； 日 子 满 了 ， 他 就 饿 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25067', '42', '4', '3', '魔 鬼 对 他 说 ： “ 你 若 是 神 的 儿 子 ， 可 以 吩 咐 这 块 石 头 变 成 食 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25068', '42', '4', '4', '耶 稣 回 答 说 ： “ 经 上 记 着 说 ： ‘ 人 活 着 不 是 单 靠 食 物 ， 乃 是 靠 神 口 里 所 出 的 一 切 话 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25069', '42', '4', '5', '魔 鬼 又 领 他 上 了 高 山 ， 霎 时 间 把 天 下 的 万 国 都 指 给 他 看 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25070', '42', '4', '6', '对 他 说 ： “ 这 一 切 权 柄 、 荣 华 ， 我 都 要 给 你 ， 因 为 这 原 是 交 付 我 的 ， 我 愿 意 给 谁 就 给 谁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25071', '42', '4', '7', '你 若 在 我 面 前 下 拜 ， 这 都 要 归 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25072', '42', '4', '8', '耶 稣 说 ： “ 经 上 记 着 说 ： 当 拜 主 ─ ─ 你 的 神 ， 单 要 事 奉 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25073', '42', '4', '9', '魔 鬼 又 领 他 到 耶 路 撒 冷 去 ， 叫 他 站 在 殿 顶 ｛ 顶 ： 原 文 是 翅 ｝ 上 ， 对 他 说 ： “ 你 若 是 神 的 儿 子 ， 可 以 从 这 里 跳 下 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25074', '42', '4', '10', '因 为 经 上 记 着 说 ： 主 要 为 你 吩 咐 他 的 使 者 保 护 你 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25075', '42', '4', '11', '他 们 要 用 手 托 着 你 ， 免 得 你 的 脚 碰 在 石 头 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25076', '42', '4', '12', '耶 稣 对 他 说 ： “ 经 上 说 ： ‘ 不 可 试 探 主 ─ ─ 你 的 神 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25077', '42', '4', '13', '魔 鬼 用 完 了 各 样 的 试 探 ， 就 暂 时 离 开 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25078', '42', '4', '14', '＜ 开 始 在 加 利 利 传 道 （ 太   4 : 1 2 - 1 7 ； 可   1 : 1 4 - 1 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25079', '42', '4', '15', '他 在 各 会 堂 里 教 训 人 ， 众 人 都 称 赞 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25080', '42', '4', '16', '＜ 拿 撒 勒 人 厌 弃 耶 稣 （ 太   1 3 : 5 3 - 5 8 ； 可   6 : 1 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25081', '42', '4', '17', '有 人 把 先 知 以 赛 亚 的 书 交 给 他 ， 他 就 打 开 ， 找 到 一 处 写 着 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25082', '42', '4', '18', '主 的 灵 在 我 身 上 ， 因 为 他 用 膏 膏 我 ， 叫 我 传 福 音 给 贫 穷 的 人 ； 差 遣 我 报 告 ： 被 掳 的 得 释 放 ， 瞎 眼 的 得 看 见 ， 叫 那 受 压 制 的 得 自 由 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25083', '42', '4', '19', '报 告 神 悦 纳 人 的 禧 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25084', '42', '4', '20', '于 是 把 书 卷 起 来 ， 交 还 执 事 ， 就 坐 下 。 会 堂 里 的 人 都 定 睛 看 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25085', '42', '4', '21', '耶 稣 对 他 们 说 ： “ 今 天 这 经 应 验 在 你 们 耳 中 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25086', '42', '4', '22', '众 人 都 称 赞 他 ， 并 希 奇 他 口 中 所 出 的 恩 言 ； 又 说 ： “ 这 不 是 约 瑟 的 儿 子 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25087', '42', '4', '23', '耶 稣 对 他 们 说 ： “ 你 们 必 引 这 俗 语 向 我 说 ： ‘ 医 生 ， 你 医 治 自 己 吧 ！ 我 们 听 见 你 在 迦 百 农 所 行 的 事 ， 也 当 行 在 你 自 己 家 乡 里 ’ ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25088', '42', '4', '24', '又 说 ： “ 我 实 在 告 诉 你 们 ， 没 有 先 知 在 自 己 家 乡 被 人 悦 纳 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25089', '42', '4', '25', '我 对 你 们 说 实 话 ， 当 以 利 亚 的 时 候 ， 天 闭 塞 了 三 年 零 六 个 月 ， 遍 地 有 大 饥 荒 ， 那 时 ， 以 色 列 中 有 许 多 寡 妇 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25090', '42', '4', '26', '以 利 亚 并 没 有 奉 差 往 她 们 一 个 人 那 里 去 ， 只 奉 差 往 西 顿 的 撒 勒 法 一 个 寡 妇 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25091', '42', '4', '27', '先 知 以 利 沙 的 时 候 ， 以 色 列 中 有 许 多 长 大 痲 疯 的 ， 但 内 中 除 了 叙 利 亚 国 的 乃 缦 ， 没 有 一 个 得 洁 净 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25092', '42', '4', '28', '会 堂 里 的 人 听 见 这 话 ， 都 怒 气 满 胸 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25093', '42', '4', '29', '就 起 来 撵 他 出 城 （ 他 们 的 城 造 在 山 上 ） ； 他 们 带 他 到 山 崖 ， 要 把 他 推 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25094', '42', '4', '30', '他 却 从 他 们 中 间 直 行 ， 过 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25095', '42', '4', '31', '＜ 一 个 污 鬼 附 身 的 人 （ 可   1 : 2 1 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25096', '42', '4', '32', '他 们 很 希 奇 他 的 教 训 ， 因 为 他 的 话 里 有 权 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25097', '42', '4', '33', '在 会 堂 里 有 一 个 人 ， 被 污 鬼 的 精 气 附 着 ， 大 声 喊 叫 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25098', '42', '4', '34', '“ 唉 ！ 拿 撒 勒 的 耶 稣 ， 我 们 与 你 有 什 么 相 干 ？ 你 来 灭 我 们 吗 ？ 我 知 道 你 是 谁 ， 乃 是 神 的 圣 者 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25099', '42', '4', '35', '耶 稣 责 备 他 说 ： “ 不 要 作 声 ， 从 这 人 身 上 出 来 吧 ！ ” 鬼 把 那 人 摔 倒 在 众 人 中 间 ， 就 出 来 了 ， 却 也 没 有 害 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25100', '42', '4', '36', '众 人 都 惊 讶 ， 彼 此 对 问 说 ： “ 这 是 什 么 道 理 呢 ？ 因 为 他 用 权 柄 能 力 吩 咐 污 鬼 ， 污 鬼 就 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25101', '42', '4', '37', '于 是 耶 稣 的 名 声 传 遍 了 周 围 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25102', '42', '4', '38', '＜ 治 好 许 多 病 人 （ 太   8 : 1 4 - 1 7 ； 可   1 : 2 9 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25103', '42', '4', '39', '耶 稣 站 在 她 旁 边 ， 斥 责 那 热 病 ， 热 就 退 了 。 她 立 刻 起 来 服 事 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25104', '42', '4', '40', '日 落 的 时 候 ， 凡 有 病 人 的 ， 不 论 害 什 么 病 ， 都 带 到 耶 稣 那 里 。 耶 稣 按 手 在 他 们 各 人 身 上 ， 医 好 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25105', '42', '4', '41', '又 有 鬼 从 好 些 人 身 上 出 来 ， 喊 着 说 ： “ 你 是 神 的 儿 子 。 ” 耶 稣 斥 责 他 们 ， 不 许 他 们 说 话 。 因 为 他 们 知 道 他 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25106', '42', '4', '42', '＜ 在 加 利 利 各 会 堂 传 道 （ 可   1 : 3 5 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25107', '42', '4', '43', '但 耶 稣 对 他 们 说 ： “ 我 也 必 须 在 别 城 传 神 国 的 福 音 ， 因 我 奉 差 原 是 为 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25108', '42', '4', '44', '于 是 耶 稣 在 加 利 利 的 各 会 堂 传 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25109', '42', '5', '1', '＜ 耶 稣 呼 召 头 几 个 门 徒 （ 太   4 : 1 8 - 2 2 ； 可   1 : 1 6 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25110', '42', '5', '2', '他 见 有 两 只 船 湾 在 湖 边 ； 打 鱼 的 人 却 离 开 船 洗 网 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25111', '42', '5', '3', '有 一 只 船 是 西 门 的 ， 耶 稣 就 上 去 ， 请 他 把 船 撑 开 ， 稍 微 离 岸 ， 就 坐 下 ， 从 船 上 教 训 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25112', '42', '5', '4', '讲 完 了 ， 对 西 门 说 ： “ 把 船 开 到 水 深 之 处 ， 下 网 打 鱼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25113', '42', '5', '5', '西 门 说 ： “ 夫 子 ， 我 们 整 夜 劳 力 ， 并 没 有 打 着 什 么 。 但 依 从 你 的 话 ， 我 就 下 网 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25114', '42', '5', '6', '他 们 下 了 网 ， 就 圈 住 许 多 鱼 ， 网 险 些 裂 开 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25115', '42', '5', '7', '便 招 呼 那 只 船 上 的 同 伴 来 帮 助 。 他 们 就 来 ， 把 鱼 装 满 了 两 只 船 ， 甚 至 船 要 沉 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25116', '42', '5', '8', '西 门 ． 彼 得 看 见 ， 就 俯 伏 在 耶 稣 膝 前 ， 说 ： “ 主 啊 ， 离 开 我 ， 我 是 个 罪 人 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25117', '42', '5', '9', '他 和 一 切 同 在 的 人 都 惊 讶 这 一 网 所 打 的 鱼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25118', '42', '5', '10', '他 的 伙 伴 西 庇 太 的 儿 子 雅 各 、 约 翰 ， 也 是 这 样 。 耶 稣 对 西 门 说 ： “ 不 要 怕 ！ 从 今 以 后 ， 你 要 得 人 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25119', '42', '5', '11', '他 们 把 两 只 船 拢 了 岸 ， 就 撇 下 所 有 的 ， 跟 从 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25120', '42', '5', '12', '＜ 洁 净 长 大 痲 疯 的 人 （ 太   8 : 1 - 4 ； 可   1 : 4 0 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25121', '42', '5', '13', '耶 稣 伸 手 摸 他 ， 说 ： “ 我 肯 ， 你 洁 净 了 吧 ！ ” 大 痲 疯 立 刻 就 离 了 他 的 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25122', '42', '5', '14', '耶 稣 嘱 咐 他 ： “ 你 切 不 可 告 诉 人 ， 只 要 去 把 身 体 给 祭 司 察 看 ， 又 要 为 你 得 了 洁 净 ， 照 摩 西 所 吩 咐 的 献 上 礼 物 ， 对 众 人 作 证 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25123', '42', '5', '15', '但 耶 稣 的 名 声 越 发 传 扬 出 去 。 有 极 多 的 人 聚 集 来 听 道 ， 也 指 望 医 治 他 们 的 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25124', '42', '5', '16', '耶 稣 却 退 到 旷 野 去 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25125', '42', '5', '17', '＜ 治 好 瘫 痪 病 人 （ 太   9 : 1 - 8 ； 可   2 : 1 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25126', '42', '5', '18', '有 人 用 褥 子 抬 着 一 个 瘫 子 ， 要 抬 进 去 放 在 耶 稣 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25127', '42', '5', '19', '却 因 人 多 ， 寻 不 出 法 子 抬 进 去 ， 就 上 了 房 顶 ， 从 瓦 间 把 他 连 褥 子 缒 到 当 中 ， 正 在 耶 稣 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25128', '42', '5', '20', '耶 稣 见 他 们 的 信 心 ， 就 对 瘫 子 说 ： “ 你 的 罪 赦 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25129', '42', '5', '21', '文 士 和 法 利 赛 人 就 议 论 说 ： “ 这 说 僭 妄 话 的 是 谁 ？ 除 了 神 以 外 ， 谁 能 赦 罪 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25130', '42', '5', '22', '耶 稣 知 道 他 们 所 议 论 的 ， 就 说 ： “ 你 们 心 里 议 论 的 是 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25131', '42', '5', '23', '或 说 ‘ 你 的 罪 赦 了 ’ ， 或 说 ‘ 你 起 来 行 走 ’ ， 哪 一 样 容 易 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25132', '42', '5', '24', '但 要 叫 你 们 知 道 ， 人 子 在 地 上 有 赦 罪 的 权 柄 。 ” 就 对 瘫 子 说 ： “ 我 吩 咐 你 ， 起 来 ， 拿 你 的 褥 子 回 家 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25133', '42', '5', '25', '那 人 当 众 人 面 前 立 刻 起 来 ， 拿 着 他 所 躺 卧 的 褥 子 回 家 去 ， 归 荣 耀 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25134', '42', '5', '26', '众 人 都 惊 奇 ， 也 归 荣 耀 与 神 ， 并 且 满 心 惧 怕 ， 说 ： “ 我 们 今 日 看 见 非 常 的 事 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25135', '42', '5', '27', '＜ 呼 召 利 未 （ 太   9 : 9 - 1 3 ； 可   2 : 1 3 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25136', '42', '5', '28', '他 就 撇 下 所 有 的 ， 起 来 ， 跟 从 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25137', '42', '5', '29', '利 未 在 自 己 家 里 为 耶 稣 大 摆 筵 席 ， 有 许 多 税 吏 和 别 人 与 他 们 一 同 坐 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25138', '42', '5', '30', '法 利 赛 人 和 文 士 就 向 耶 稣 的 门 徒 发 怨 言 说 ： “ 你 们 为 什 么 和 税 吏 并 罪 人 一 同 吃 喝 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25139', '42', '5', '31', '耶 稣 对 他 们 说 ： “ 无 病 的 人 用 不 着 医 生 ； 有 病 的 人 才 用 得 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25140', '42', '5', '32', '我 来 本 不 是 召 义 人 悔 改 ， 乃 是 召 罪 人 悔 改 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25141', '42', '5', '33', '＜ 禁 食 的 问 题 （ 太   9 : 1 4 - 1 7 ； 可   2 : 1 8 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25142', '42', '5', '34', '耶 稣 对 他 们 说 ： “ 新 郎 和 陪 伴 之 人 同 在 的 时 候 ， 岂 能 叫 陪 伴 之 人 禁 食 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25143', '42', '5', '35', '但 日 子 将 到 ， 新 郎 要 离 开 他 们 ， 那 日 他 们 就 要 禁 食 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25144', '42', '5', '36', '耶 稣 又 设 一 个 比 喻 ， 对 他 们 说 ： “ 没 有 人 把 新 衣 服 撕 下 一 块 来 补 在 旧 衣 服 上 ； 若 是 这 样 ， 就 把 新 的 撕 破 了 ， 并 且 所 撕 下 来 的 那 块 新 的 和 旧 的 也 不 相 称 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25145', '42', '5', '37', '也 没 有 人 把 新 酒 装 在 旧 皮 袋 里 ； 若 是 这 样 ， 新 酒 必 将 皮 袋 裂 开 ， 酒 便 漏 出 来 ， 皮 袋 也 就 坏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25146', '42', '5', '38', '但 新 酒 必 须 装 在 新 皮 袋 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25147', '42', '5', '39', '没 有 人 喝 了 陈 酒 又 想 喝 新 的 ； 他 总 说 陈 的 好 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25148', '42', '6', '1', '＜ 安 息 日 的 问 题 （ 太   1 2 : 1 - 8 ； 可   2 : 2 3 - 2 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25149', '42', '6', '2', '有 几 个 法 利 赛 人 说 ： “ 你 们 为 什 么 做 安 息 日 不 可 做 的 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25150', '42', '6', '3', '耶 稣 对 他 们 说 ： “ 经 上 记 着 大 卫 和 跟 从 他 的 人 饥 饿 之 时 所 做 的 事 ， 连 这 个 你 们 也 没 有 念 过 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25151', '42', '6', '4', '他 怎 么 进 了 神 的 殿 ， 拿 陈 设 饼 吃 ， 又 给 跟 从 的 人 吃 ？ 这 饼 除 了 祭 司 以 外 ， 别 人 都 不 可 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25152', '42', '6', '5', '又 对 他 们 说 ： “ 人 子 是 安 息 日 的 主 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25153', '42', '6', '6', '＜ 治 好 枯 干 了 一 只 手 的 人 （ 太   1 2 : 9 - 1 4 ； 可   3 : 1 - 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25154', '42', '6', '7', '文 士 和 法 利 赛 人 窥 探 耶 稣 ， 在 安 息 日 治 病 不 治 病 ， 要 得 把 柄 去 告 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25155', '42', '6', '8', '耶 稣 却 知 道 他 们 的 意 念 ， 就 对 那 枯 干 一 只 手 的 人 说 ： “ 起 来 ！ 站 在 当 中 。 ” 那 人 就 起 来 ， 站 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25156', '42', '6', '9', '耶 稣 对 他 们 说 ： “ 我 问 你 们 ， 在 安 息 日 行 善 行 恶 ， 救 命 害 命 ， 哪 样 是 可 以 的 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25157', '42', '6', '10', '他 就 周 围 看 着 他 们 众 人 ， 对 那 人 说 ： “ 伸 出 手 来 ！ ” 他 把 手 一 伸 ， 手 就 复 了 原 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25158', '42', '6', '11', '他 们 就 满 心 大 怒 ， 彼 此 商 议 怎 样 处 治 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25159', '42', '6', '12', '＜ 挑 选 十 二 门 徒 （ 太   1 0 : 1 - 4 ； 可   3 : 1 3 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25160', '42', '6', '13', '到 了 天 亮 ， 叫 他 的 门 徒 来 ， 就 从 他 们 中 间 挑 选 十 二 个 人 ， 称 他 们 为 使 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25161', '42', '6', '14', '这 十 二 个 人 有 西 门 （ 耶 稣 又 给 他 起 名 叫 彼 得 ） ， 还 有 他 兄 弟 安 得 烈 ， 又 有 雅 各 和 约 翰 ， 腓 力 和 巴 多 罗 买 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25162', '42', '6', '15', '马 太 和 多 马 ， 亚 勒 腓 的 儿 子 雅 各 和 奋 锐 党 的 西 门 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25163', '42', '6', '16', '雅 各 的 儿 子 ｛ 或 译 ： 兄 弟 ｝ 犹 大 ， 和 卖 主 的 加 略 人 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25164', '42', '6', '17', '＜ 向 群 众 传 道 （ 太   4 : 2 3 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25165', '42', '6', '18', '还 有 被 污 鬼 缠 磨 的 ， 也 得 了 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25166', '42', '6', '19', '众 人 都 想 要 摸 他 ； 因 为 有 能 力 从 他 身 上 发 出 来 ， 医 好 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25167', '42', '6', '20', '＜ 论 福 和 祸 （ 太   5 : 1 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25168', '42', '6', '21', '你 们 饥 饿 的 人 有 福 了 ！ 因 为 你 们 将 要 饱 足 。 你 们 哀 哭 的 人 有 福 了 ！ 因 为 你 们 将 要 喜 笑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25169', '42', '6', '22', '“ 人 为 人 子 恨 恶 你 们 ， 拒 绝 你 们 ， 辱 骂 你 们 ， 弃 掉 你 们 的 名 ， 以 为 是 恶 ， 你 们 就 有 福 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25170', '42', '6', '23', '当 那 日 ， 你 们 要 欢 喜 跳 跃 ， 因 为 你 们 在 天 上 的 赏 赐 是 大 的 。 他 们 的 祖 宗 待 先 知 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25171', '42', '6', '24', '但 你 们 富 足 的 人 有 祸 了 ！ 因 为 你 们 受 过 你 们 的 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25172', '42', '6', '25', '你 们 饱 足 的 人 有 祸 了 ！ 因 为 你 们 将 要 饥 饿 。 你 们 喜 笑 的 人 有 祸 了 ！ 因 为 你 们 将 要 哀 恸 哭 泣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25173', '42', '6', '26', '“ 人 都 说 你 们 好 的 时 候 ， 你 们 就 有 祸 了 ！ 因 为 他 们 的 祖 宗 待 假 先 知 也 是 这 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25174', '42', '6', '27', '＜ 论 爱 仇 敌 （ 太   5 : 3 8 - 4 8 ； 7 : 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25175', '42', '6', '28', '咒 诅 你 们 的 ， 要 为 他 祝 福 ！ 凌 辱 你 们 的 ， 要 为 他 祷 告 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25176', '42', '6', '29', '有 人 打 你 这 边 的 脸 ， 连 那 边 的 脸 也 由 他 打 。 有 人 夺 你 的 外 衣 ， 连 里 衣 也 由 他 拿 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25177', '42', '6', '30', '凡 求 你 的 ， 就 给 他 。 有 人 夺 你 的 东 西 去 ， 不 用 再 要 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25178', '42', '6', '31', '你 们 愿 意 人 怎 样 待 你 们 ， 你 们 也 要 怎 样 待 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25179', '42', '6', '32', '你 们 若 单 爱 那 爱 你 们 的 人 ， 有 什 么 可 酬 谢 的 呢 ？ 就 是 罪 人 也 爱 那 爱 他 们 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25180', '42', '6', '33', '你 们 若 善 待 那 善 待 你 们 的 人 ， 有 什 么 可 酬 谢 的 呢 ？ 就 是 罪 人 也 是 这 样 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25181', '42', '6', '34', '你 们 若 借 给 人 ， 指 望 从 他 收 回 ， 有 什 么 可 酬 谢 的 呢 ？ 就 是 罪 人 也 借 给 罪 人 ， 要 如 数 收 回 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25182', '42', '6', '35', '你 们 倒 要 爱 仇 敌 ， 也 要 善 待 他 们 ， 并 要 借 给 人 不 指 望 偿 还 ， 你 们 的 赏 赐 就 必 大 了 ， 你 们 也 必 作 至 高 者 的 儿 子 ； 因 为 他 恩 待 那 忘 恩 的 和 作 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25183', '42', '6', '36', '你 们 要 慈 悲 ， 像 你 们 的 父 慈 悲 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25184', '42', '6', '37', '＜ 不 要 论 断 人 （ 太   7 : 1 - 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25185', '42', '6', '38', '你 们 要 给 人 ， 就 必 有 给 你 们 的 ， 并 且 用 十 足 的 升 斗 ， 连 摇 带 按 ， 上 尖 下 流 地 倒 在 你 们 怀 里 ； 因 为 你 们 用 什 么 量 器 量 给 人 ， 也 必 用 什 么 量 器 量 给 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25186', '42', '6', '39', '耶 稣 又 用 比 喻 对 他 们 说 ： “ 瞎 子 岂 能 领 瞎 子 ， 两 个 人 不 是 都 要 掉 在 坑 里 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25187', '42', '6', '40', '学 生 不 能 高 过 先 生 ； 凡 学 成 了 的 不 过 和 先 生 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25188', '42', '6', '41', '为 什 么 看 见 你 弟 兄 眼 中 有 刺 ， 却 不 想 自 己 眼 中 有 梁 木 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25189', '42', '6', '42', '你 不 见 自 己 眼 中 有 梁 木 ， 怎 能 对 你 弟 兄 说 ： ‘ 容 我 去 掉 你 眼 中 的 刺 ’ 呢 ？ 你 这 假 冒 为 善 的 人 ！ 先 去 掉 自 己 眼 中 的 梁 木 ， 然 后 才 能 看 得 清 楚 ， 去 掉 你 弟 兄 眼 中 的 刺 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25190', '42', '6', '43', '＜ 树 和 果 子 （ 太   7 : 1 6 - 2 0 ； 1 2 : 3 3 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25191', '42', '6', '44', '凡 树 木 看 果 子 ， 就 可 以 认 出 它 来 。 人 不 是 从 荆 棘 上 摘 无 花 果 ， 也 不 是 从 蒺 藜 里 摘 葡 萄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25192', '42', '6', '45', '善 人 从 他 心 里 所 存 的 善 就 发 出 善 来 ； 恶 人 从 他 心 里 所 存 的 恶 就 发 出 恶 来 ； 因 为 心 里 所 充 满 的 ， 口 里 就 说 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25193', '42', '6', '46', '＜ 两 种 盖 房 子 的 人 （ 太   7 : 2 4 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25194', '42', '6', '47', '凡 到 我 这 里 来 ， 听 见 我 的 话 就 去 行 的 ， 我 要 告 诉 你 们 他 像 什 么 人 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25195', '42', '6', '48', '他 像 一 个 人 盖 房 子 ， 深 深 地 挖 地 ， 把 根 基 安 在 磐 石 上 ； 到 发 大 水 的 时 候 ， 水 冲 那 房 子 ， 房 子 总 不 能 摇 动 ， 因 为 根 基 立 在 磐 石 上 ｛ 有 古 卷 ： 因 为 盖 造 得 好 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25196', '42', '6', '49', '惟 有 听 见 不 去 行 的 ， 就 像 一 个 人 在 土 地 上 盖 房 子 ， 没 有 根 基 ； 水 一 冲 ， 随 即 倒 塌 了 ， 并 且 那 房 子 坏 的 很 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25197', '42', '7', '1', '＜ 治 好 百 夫 长 的 仆 人 （ 太   8 : 5 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25198', '42', '7', '2', '有 一 个 百 夫 长 所 宝 贵 的 仆 人 害 病 ， 快 要 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25199', '42', '7', '3', '百 夫 长 风 闻 耶 稣 的 事 ， 就 托 犹 太 人 的 几 个 长 老 去 求 耶 稣 来 救 他 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25200', '42', '7', '4', '他 们 到 了 耶 稣 那 里 ， 就 切 切 地 求 他 说 ： “ 你 给 他 行 这 事 是 他 所 配 得 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25201', '42', '7', '5', '因 为 他 爱 我 们 的 百 姓 ， 给 我 们 建 造 会 堂 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25202', '42', '7', '6', '耶 稣 就 和 他 们 同 去 。 离 那 家 不 远 ， 百 夫 长 托 几 个 朋 友 去 见 耶 稣 ， 对 他 说 ： “ 主 啊 ！ 不 要 劳 动 ； 因 你 到 我 舍 下 ， 我 不 敢 当 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25203', '42', '7', '7', '我 也 自 以 为 不 配 去 见 你 ， 只 要 你 说 一 句 话 ， 我 的 仆 人 就 必 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25204', '42', '7', '8', '因 为 我 在 人 的 权 下 ， 也 有 兵 在 我 以 下 ， 对 这 个 说 ： ‘ 去 ！ ’ 他 就 去 ； 对 那 个 说 ： ‘ 来 ！ ’ 他 就 来 ； 对 我 的 仆 人 说 ： ‘ 你 做 这 事 ！ ’ 他 就 去 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25205', '42', '7', '9', '耶 稣 听 见 这 话 ， 就 希 奇 他 ， 转 身 对 跟 随 的 众 人 说 ： “ 我 告 诉 你 们 ， 这 么 大 的 信 心 ， 就 是 在 以 色 列 中 ， 我 也 没 有 遇 见 过 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25206', '42', '7', '10', '那 托 来 的 人 回 到 百 夫 长 家 里 ， 看 见 仆 人 已 经 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25207', '42', '7', '11', '＜ 使 拿 因 城 寡 妇 之 子 复 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25208', '42', '7', '12', '将 近 城 门 ， 有 一 个 死 人 被 抬 出 来 。 这 人 是 他 母 亲 独 生 的 儿 子 ； 他 母 亲 又 是 寡 妇 。 有 城 里 的 许 多 人 同 着 寡 妇 送 殡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25209', '42', '7', '13', '主 看 见 那 寡 妇 ， 就 怜 悯 她 ， 对 她 说 ： “ 不 要 哭 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25210', '42', '7', '14', '于 是 进 前 按 着 杠 ， 抬 的 人 就 站 住 了 。 耶 稣 说 ： “ 少 年 人 ， 我 吩 咐 你 ， 起 来 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25211', '42', '7', '15', '那 死 人 就 坐 起 ， 并 且 说 话 。 耶 稣 便 把 他 交 给 他 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25212', '42', '7', '16', '众 人 都 惊 奇 ， 归 荣 耀 与 神 ， 说 ： “ 有 大 先 知 在 我 们 中 间 兴 起 来 了 ！ ” 又 说 ： “ 神 眷 顾 了 他 的 百 姓 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25213', '42', '7', '17', '他 这 事 的 风 声 就 传 遍 了 犹 太 和 周 围 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25214', '42', '7', '18', '＜ 施 洗 约 翰 的 门 徒 来 见 耶 稣 （ 太   1 1 : 2 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25215', '42', '7', '19', '他 便 叫 了 两 个 门 徒 来 ， 打 发 他 们 到 主 那 里 去 ， 说 ： “ 那 将 要 来 的 是 你 吗 ？ 还 是 我 们 等 候 别 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25216', '42', '7', '20', '那 两 个 人 来 到 耶 稣 那 里 ， 说 ： “ 施 洗 的 约 翰 打 发 我 们 来 问 你 ： ‘ 那 将 要 来 的 是 你 吗 ？ 还 是 我 们 等 候 别 人 呢 ？ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25217', '42', '7', '21', '正 当 那 时 候 ， 耶 稣 治 好 了 许 多 有 疾 病 的 ， 受 灾 患 的 ， 被 恶 鬼 附 着 的 ， 又 开 恩 叫 好 些 瞎 子 能 看 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25218', '42', '7', '22', '耶 稣 回 答 说 ： “ 你 们 去 ， 把 所 看 见 所 听 见 的 事 告 诉 约 翰 ， 就 是 瞎 子 看 见 ， 瘸 子 行 走 ， 长 大 痲 疯 的 洁 净 ， 聋 子 听 见 ， 死 人 复 活 ， 穷 人 有 福 音 传 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25219', '42', '7', '23', '凡 不 因 我 跌 倒 的 ， 就 有 福 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25220', '42', '7', '24', '约 翰 所 差 来 的 人 既 走 了 ， 耶 稣 就 对 众 人 讲 论 约 翰 说 ： “ 你 们 从 前 出 去 到 旷 野 ， 是 要 看 什 么 呢 ？ 要 看 风 吹 动 的 芦 苇 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25221', '42', '7', '25', '你 们 出 去 ， 到 底 是 要 看 什 么 ？ 要 看 穿 细 软 衣 服 的 人 吗 ？ 那 穿 华 丽 衣 服 、 宴 乐 度 日 的 人 是 在 王 宫 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25222', '42', '7', '26', '你 们 出 去 ， 究 竟 是 要 看 什 么 ？ 要 看 先 知 吗 ？ 我 告 诉 你 们 ， 是 的 ， 他 比 先 知 大 多 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25223', '42', '7', '27', '经 上 记 着 说 ： ‘ 我 要 差 遣 我 的 使 者 在 你 前 面 预 备 道 路 ’ ， 所 说 的 就 是 这 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25224', '42', '7', '28', '我 告 诉 你 们 ， 凡 妇 人 所 生 的 ， 没 有 一 个 大 过 约 翰 的 ； 然 而 神 国 里 最 小 的 比 他 还 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25225', '42', '7', '29', '众 百 姓 和 税 吏 既 受 过 约 翰 的 洗 ， 听 见 这 话 ， 就 以 神 为 义 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25226', '42', '7', '30', '但 法 利 赛 人 和 律 法 师 没 有 受 过 约 翰 的 洗 ， 竟 为 自 己 废 弃 了 神 的 旨 意 。 ｛ 2 9 - 3 0   两 节 或 译 ： 众 百 姓 和 税 吏 听 见 了 约 翰 的 话 ， 就 受 了 他 的 洗 ， 便 以 神 为 义 ； 但 法 利 赛 人 和 律 法 师 不 受 约 翰 的 洗 ， 竟 为 自 己 废 弃 了 神 的 旨 意 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25227', '42', '7', '31', '主 又 说 ： “ 这 样 ， 我 可 用 什 么 比 这 世 代 的 人 呢 ？ 他 们 好 像 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25228', '42', '7', '32', '好 像 孩 童 坐 在 街 市 上 ， 彼 此 呼 叫 说 ： 我 们 向 你 们 吹 笛 ， 你 们 不 跳 舞 ； 我 们 向 你 们 举 哀 ， 你 们 不 啼 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25229', '42', '7', '33', '施 洗 的 约 翰 来 ， 不 吃 饼 ， 不 喝 酒 ， 你 们 说 他 是 被 鬼 附 着 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25230', '42', '7', '34', '人 子 来 ， 也 吃 也 喝 ， 你 们 说 他 是 贪 食 好 酒 的 人 ， 是 税 吏 和 罪 人 的 朋 友 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25231', '42', '7', '35', '但 智 慧 之 子 都 以 智 慧 为 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25232', '42', '7', '36', '＜ 有 罪 的 女 人 得 蒙 赦 免 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25233', '42', '7', '37', '那 城 里 有 一 个 女 人 ， 是 个 罪 人 ， 知 道 耶 稣 在 法 利 赛 人 家 里 坐 席 ， 就 拿 着 盛 香 膏 的 玉 瓶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25234', '42', '7', '38', '站 在 耶 稣 背 后 ， 挨 着 他 的 脚 哭 ， 眼 泪 湿 了 耶 稣 的 脚 ， 就 用 自 己 的 头 发 擦 干 ， 又 用 嘴 连 连 亲 他 的 脚 ， 把 香 膏 抹 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25235', '42', '7', '39', '请 耶 稣 的 法 利 赛 人 看 见 这 事 ， 心 里 说 ： “ 这 人 若 是 先 知 ， 必 知 道 摸 他 的 是 谁 ， 是 个 怎 样 的 女 人 ； 乃 是 个 罪 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25236', '42', '7', '40', '耶 稣 对 他 说 ： “ 西 门 ！ 我 有 句 话 要 对 你 说 。 ” 西 门 说 ： “ 夫 子 ， 请 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25237', '42', '7', '41', '耶 稣 说 ： “ 一 个 债 主 有 两 个 人 欠 他 的 债 ； 一 个 欠 五 十 两 银 子 ， 一 个 欠 五 两 银 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25238', '42', '7', '42', '因 为 他 们 无 力 偿 还 ， 债 主 就 开 恩 免 了 他 们 两 个 人 的 债 。 这 两 个 人 哪 一 个 更 爱 他 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25239', '42', '7', '43', '西 门 回 答 说 ： “ 我 想 是 那 多 得 恩 免 的 人 。 ” 耶 稣 说 ： “ 你 断 的 不 错 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25240', '42', '7', '44', '于 是 转 过 来 向 着 那 女 人 ， 便 对 西 门 说 ： “ 你 看 见 这 女 人 吗 ？ 我 进 了 你 的 家 ， 你 没 有 给 我 水 洗 脚 ； 但 这 女 人 用 眼 泪 湿 了 我 的 脚 ， 用 头 发 擦 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25241', '42', '7', '45', '你 没 有 与 我 亲 嘴 ； 但 这 女 人 从 我 进 来 的 时 候 就 不 住 地 用 嘴 亲 我 的 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25242', '42', '7', '46', '你 没 有 用 油 抹 我 的 头 ； 但 这 女 人 用 香 膏 抹 我 的 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25243', '42', '7', '47', '所 以 我 告 诉 你 ， 她 许 多 的 罪 都 赦 免 了 ， 因 为 她 的 爱 多 ； 但 那 赦 免 少 的 ， 他 的 爱 就 少 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25244', '42', '7', '48', '于 是 对 那 女 人 说 ： “ 你 的 罪 赦 免 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25245', '42', '7', '49', '同 席 的 人 心 里 说 ： “ 这 是 什 么 人 ， 竟 赦 免 人 的 罪 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25246', '42', '7', '50', '耶 稣 对 那 女 人 说 ： “ 你 的 信 救 了 你 ； 平 平 安 安 回 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25247', '42', '8', '1', '＜ 跟 从 耶 稣 的 妇 女 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25248', '42', '8', '2', '还 有 被 恶 鬼 所 附 、 被 疾 病 所 累 、 已 经 治 好 的 几 个 妇 女 ， 内 中 有 称 为 抹 大 拉 的 马 利 亚 （ 曾 有 七 个 鬼 从 她 身 上 赶 出 来 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25249', '42', '8', '3', '又 有 希 律 的 家 宰 苦 撒 的 妻 子 约 亚 拿 ， 并 苏 撒 拿 ， 和 好 些 别 的 妇 女 ， 都 是 用 自 己 的 财 物 供 给 耶 稣 和 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25250', '42', '8', '4', '＜ 撒 种 的 比 喻 （ 太   1 3 : 1 - 9 ； 可   4 : 1 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25251', '42', '8', '5', '“ 有 一 个 撒 种 的 出 去 撒 种 。 撒 的 时 候 ， 有 落 在 路 旁 的 ， 被 人 践 踏 ， 天 上 的 飞 鸟 又 来 吃 尽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25252', '42', '8', '6', '有 落 在 磐 石 上 的 ， 一 出 来 就 枯 干 了 ， 因 为 得 不 着 滋 润 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25253', '42', '8', '7', '有 落 在 荆 棘 里 的 ， 荆 棘 一 同 生 长 ， 把 它 挤 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25254', '42', '8', '8', '又 有 落 在 好 土 里 的 ， 生 长 起 来 ， 结 实 百 倍 。 ” 耶 稣 说 了 这 些 话 ， 就 大 声 说 ： “ 有 耳 可 听 的 ， 就 应 当 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25255', '42', '8', '9', '＜ 用 比 喻 的 目 的 （ 太   1 3 : 1 0 - 1 7 ； 可   4 : 1 0 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25256', '42', '8', '10', '他 说 ： “ 神 国 的 奥 秘 只 叫 你 们 知 道 ； 至 于 别 人 ， 就 用 比 喻 ， 叫 他 们 看 也 看 不 见 ， 听 也 听 不 明 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25257', '42', '8', '11', '＜ 解 明 撒 种 的 比 喻 （ 太   1 3 : 1 8 - 2 3 ； 可   4 : 1 3 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25258', '42', '8', '12', '那 些 在 路 旁 的 ， 就 是 人 听 了 道 ， 随 后 魔 鬼 来 ， 从 他 们 心 里 把 道 夺 去 ， 恐 怕 他 们 信 了 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25259', '42', '8', '13', '那 些 在 磐 石 上 的 ， 就 是 人 听 道 ， 欢 喜 领 受 ， 但 心 中 没 有 根 ， 不 过 暂 时 相 信 ， 及 至 遇 见 试 炼 就 退 后 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25260', '42', '8', '14', '那 落 在 荆 棘 里 的 ， 就 是 人 听 了 道 ， 走 开 以 后 ， 被 今 生 的 思 虑 、 钱 财 、 宴 乐 挤 住 了 ， 便 结 不 出 成 熟 的 子 粒 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25261', '42', '8', '15', '那 落 在 好 土 里 的 ， 就 是 人 听 了 道 ， 持 守 在 诚 实 善 良 的 心 里 ， 并 且 忍 耐 着 结 实 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25262', '42', '8', '16', '＜ 器 皿 下 的 灯 （ 可   4 : 2 1 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25263', '42', '8', '17', '因 为 掩 藏 的 事 没 有 不 显 出 来 的 ； 隐 瞒 的 事 没 有 不 露 出 来 被 人 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25264', '42', '8', '18', '所 以 ， 你 们 应 当 小 心 怎 样 听 ； 因 为 凡 有 的 ， 还 要 加 给 他 ； 凡 没 有 的 ， 连 他 自 以 为 有 的 ， 也 要 夺 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25265', '42', '8', '19', '＜ 耶 稣 的 母 亲 和 兄 弟 们 （ 太   1 2 : 4 6 - 5 0 ； 可   3 : 3 1 - 3 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25266', '42', '8', '20', '有 人 告 诉 他 说 ： “ 你 母 亲 和 你 弟 兄 站 在 外 边 ， 要 见 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25267', '42', '8', '21', '耶 稣 回 答 说 ： “ 听 了 神 之 道 而 遵 行 的 人 就 是 我 的 母 亲 ， 我 的 弟 兄 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25268', '42', '8', '22', '＜ 平 静 风 浪 （ 太   8 : 2 3 - 2 7 ； 可   4 : 3 5 - 4 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25269', '42', '8', '23', '正 行 的 时 候 ， 耶 稣 睡 着 了 。 湖 上 忽 然 起 了 暴 风 ， 船 将 满 了 水 ， 甚 是 危 险 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25270', '42', '8', '24', '门 徒 来 叫 醒 了 他 ， 说 ： “ 夫 子 ！ 夫 子 ！ 我 们 丧 命 啦 ！ ” 耶 稣 醒 了 ， 斥 责 那 狂 风 大 浪 ； 风 浪 就 止 住 ， 平 静 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25271', '42', '8', '25', '耶 稣 对 他 们 说 ： “ 你 们 的 信 心 在 哪 里 呢 ？ ” 他 们 又 惧 怕 又 希 奇 ， 彼 此 说 ： “ 这 到 底 是 谁 ？ 他 吩 咐 风 和 水 ， 连 风 和 水 也 听 从 他 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25272', '42', '8', '26', '＜ 治 好 格 拉 森 被 鬼 附 的 人 （ 太   8 : 2 8 - 3 4 ； 可   5 : 1 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25273', '42', '8', '27', '耶 稣 上 了 岸 ， 就 有 城 里 一 个 被 鬼 附 着 的 人 迎 面 而 来 。 这 个 人 许 久 不 穿 衣 服 ， 不 住 房 子 ， 只 住 在 坟 茔 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25274', '42', '8', '28', '他 见 了 耶 稣 ， 就 俯 伏 在 他 面 前 ， 大 声 喊 叫 ， 说 ： “ 至 高 神 的 儿 子 耶 稣 ， 我 与 你 有 什 么 相 干 ？ 求 你 不 要 叫 我 受 苦 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25275', '42', '8', '29', '是 因 耶 稣 曾 吩 咐 污 鬼 从 那 人 身 上 出 来 。 原 来 这 鬼 屡 次 抓 住 他 ； 他 常 被 人 看 守 ， 又 被 铁 链 和 脚 镣 捆 锁 ， 他 竟 把 锁 炼 挣 断 ， 被 鬼 赶 到 旷 野 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25276', '42', '8', '30', '耶 稣 问 他 说 ： “ 你 名 叫 什 么 ？ ” 他 说 ： “ 我 名 叫 ‘ 群 ’ ” ； 这 是 因 为 附 着 他 的 鬼 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25277', '42', '8', '31', '鬼 就 央 求 耶 稣 ， 不 要 吩 咐 他 们 到 无 底 坑 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25278', '42', '8', '32', '那 里 有 一 大 群 猪 在 山 上 吃 食 。 鬼 央 求 耶 稣 ， 准 他 们 进 入 猪 里 去 。 耶 稣 准 了 他 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25279', '42', '8', '33', '鬼 就 从 那 人 出 来 ， 进 入 猪 里 去 。 于 是 那 群 猪 闯 下 山 崖 ， 投 在 湖 里 淹 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25280', '42', '8', '34', '放 猪 的 看 见 这 事 就 逃 跑 了 ， 去 告 诉 城 里 和 乡 下 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25281', '42', '8', '35', '众 人 出 来 要 看 是 什 么 事 ； 到 了 耶 稣 那 里 ， 看 见 鬼 所 离 开 的 那 人 ， 坐 在 耶 稣 脚 前 ， 穿 着 衣 服 ， 心 里 明 白 过 来 ， 他 们 就 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25282', '42', '8', '36', '看 见 这 事 的 便 将 被 鬼 附 着 的 人 怎 么 得 救 告 诉 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25283', '42', '8', '37', '格 拉 森 四 围 的 人 ， 因 为 害 怕 得 很 ， 都 求 耶 稣 离 开 他 们 ； 耶 稣 就 上 船 回 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25284', '42', '8', '38', '鬼 所 离 开 的 那 人 恳 求 和 耶 稣 同 在 ； 耶 稣 却 打 发 他 回 去 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25285', '42', '8', '39', '“ 你 回 家 去 ， 传 说 神 为 你 做 了 何 等 大 的 事 。 ” 他 就 去 ， 满 城 里 传 扬 耶 稣 为 他 做 了 何 等 大 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25286', '42', '8', '40', '＜ 睚 鲁 的 女 儿 和 血 漏 的 女 人 （ 太   9 : 1 8 - 2 6 ； 可   5 : 2 1 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25287', '42', '8', '41', '有 一 个 管 会 堂 的 ， 名 叫 睚 鲁 ， 来 俯 伏 在 耶 稣 脚 前 ， 求 耶 稣 到 他 家 里 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25288', '42', '8', '42', '因 他 有 一 个 独 生 女 儿 ， 约 有 十 二 岁 ， 快 要 死 了 。 耶 稣 去 的 时 候 ， 众 人 拥 挤 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25289', '42', '8', '43', '有 一 个 女 人 ， 患 了 十 二 年 的 血 漏 ， 在 医 生 手 里 花 尽 了 他 一 切 养 生 的 ， 并 没 有 一 人 能 医 好 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25290', '42', '8', '44', '她 来 到 耶 稣 背 后 ， 摸 他 的 衣 裳 繸 子 ， 血 漏 立 刻 就 止 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25291', '42', '8', '45', '耶 稣 说 ： “ 摸 我 的 是 谁 ？ ” 众 人 都 不 承 认 。 彼 得 和 同 行 的 人 都 说 ： “ 夫 子 ， 众 人 拥 拥 挤 挤 紧 靠 着 你 。 ｛ 有 古 卷 加 ： 你 还 问 摸 我 的 是 谁 吗 ？ ｝ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25292', '42', '8', '46', '耶 稣 说 ： “ 总 有 人 摸 我 ， 因 我 觉 得 有 能 力 从 我 身 上 出 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25293', '42', '8', '47', '那 女 人 知 道 不 能 隐 藏 ， 就 战 战 兢 兢 地 来 俯 伏 在 耶 稣 脚 前 ， 把 摸 他 的 缘 故 和 怎 样 立 刻 得 好 了 ， 当 着 众 人 都 说 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25294', '42', '8', '48', '耶 稣 对 他 说 ： “ 女 儿 ， 你 的 信 救 了 你 ； 平 平 安 安 地 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25295', '42', '8', '49', '还 说 话 的 时 候 ， 有 人 从 管 会 堂 的 家 里 来 ， 说 ： “ 你 的 女 儿 死 了 ， 不 要 劳 动 夫 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25296', '42', '8', '50', '耶 稣 听 见 就 对 他 说 ： “ 不 要 怕 ， 只 要 信 ！ 你 的 女 儿 就 必 得 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25297', '42', '8', '51', '耶 稣 到 了 他 的 家 ， 除 了 彼 得 、 约 翰 、 雅 各 ， 和 女 儿 的 父 母 ， 不 许 别 人 同 他 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25298', '42', '8', '52', '众 人 都 为 这 女 儿 哀 哭 捶 胸 。 耶 稣 说 ： “ 不 要 哭 ！ 她 不 是 死 了 ， 是 睡 着 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25299', '42', '8', '53', '他 们 晓 得 女 儿 已 经 死 了 ， 就 嗤 笑 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25300', '42', '8', '54', '耶 稣 拉 着 她 的 手 ， 呼 叫 说 ： “ 女 儿 ， 起 来 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25301', '42', '8', '55', '她 的 灵 魂 便 回 来 ， 她 就 立 刻 起 来 了 。 耶 稣 吩 咐 给 她 东 西 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25302', '42', '8', '56', '她 的 父 母 惊 奇 得 很 ； 耶 稣 嘱 咐 他 们 ， 不 要 把 所 做 的 事 告 诉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25303', '42', '9', '1', '＜ 耶 稣 差 遣 十 二 个 门 徒 （ 太   1 0 : 5 - 1 5 ； 可   6 : 7 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25304', '42', '9', '2', '又 差 遣 他 们 去 宣 传 神 国 的 道 ， 医 治 病 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25305', '42', '9', '3', '对 他 们 说 ： “ 行 路 的 时 候 ， 不 要 带 柺 杖 和 口 袋 ， 不 要 带 食 物 和 银 子 ， 也 不 要 带 两 件 褂 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25306', '42', '9', '4', '无 论 进 哪 一 家 ， 就 住 在 那 里 ， 也 从 那 里 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25307', '42', '9', '5', '凡 不 接 待 你 们 的 ， 你 们 离 开 那 城 的 时 候 ， 要 把 脚 上 的 尘 土 跺 下 去 ， 见 证 他 们 的 不 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25308', '42', '9', '6', '门 徒 就 出 去 ， 走 遍 各 乡 宣 传 福 音 ， 到 处 治 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25309', '42', '9', '7', '＜ 希 律 的 困 惑 （ 太   1 4 : 1 - 1 2 ； 可   6 : 1 4 - 2 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25310', '42', '9', '8', '又 有 人 说 ： “ 是 以 利 亚 显 现 ” ； 还 有 人 说 ： “ 是 古 时 的 一 个 先 知 又 活 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25311', '42', '9', '9', '希 律 说 ： “ 约 翰 我 已 经 斩 了 ， 这 却 是 什 么 人 ？ 我 竟 听 见 他 这 样 的 事 呢 ？ ” 就 想 要 见 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25312', '42', '9', '10', '＜ 耶 稣 给 五 千 人 吃 饱 （ 太   1 4 : 1 3 - 2 1 ； 可   6 : 3 0 - 4 4 ； 约   6 : 1 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25313', '42', '9', '11', '但 众 人 知 道 了 ， 就 跟 着 他 去 ； 耶 稣 便 接 待 他 们 ， 对 他 们 讲 论 神 国 的 道 ， 医 治 那 些 需 医 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25314', '42', '9', '12', '日 头 快 要 平 西 ， 十 二 个 门 徒 来 对 他 说 ： “ 请 叫 众 人 散 开 ， 他 们 好 往 四 面 乡 村 里 去 借 宿 找 吃 的 ， 因 为 我 们 这 里 是 野 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25315', '42', '9', '13', '耶 稣 说 ： “ 你 们 给 他 们 吃 吧 ！ ” 门 徒 说 ： “ 我 们 不 过 有 五 个 饼 ， 两 条 鱼 ， 若 不 去 为 这 许 多 人 买 食 物 就 不 够 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25316', '42', '9', '14', '那 时 ， 人 数 约 有 五 千 。 耶 稣 对 门 徒 说 ： “ 叫 他 们 一 排 一 排 地 坐 下 ， 每 排 大 约 五 十 个 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25317', '42', '9', '15', '门 徒 就 如 此 行 ， 叫 众 人 都 坐 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25318', '42', '9', '16', '耶 稣 拿 着 这 五 个 饼 ， 两 条 鱼 ， 望 着 天 祝 福 ， 擘 开 ， 递 给 门 徒 ， 摆 在 众 人 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25319', '42', '9', '17', '他 们 就 吃 ， 并 且 都 吃 饱 了 ； 把 剩 下 的 零 碎 收 拾 起 来 ， 装 满 了 十 二 篮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25320', '42', '9', '18', '＜ 彼 得 认 耶 稣 为 基 督 （ 太   1 6 : 1 3 - 1 9 ； 可   8 : 2 7 - 2 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25321', '42', '9', '19', '他 们 说 ： “ 有 人 说 是 施 洗 的 约 翰 ； 有 人 说 是 以 利 亚 ； 还 有 人 说 是 古 时 的 一 个 先 知 又 活 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25322', '42', '9', '20', '耶 稣 说 ： “ 你 们 说 我 是 谁 ？ ” 彼 得 回 答 说 ： “ 是 神 所 立 的 基 督 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25323', '42', '9', '21', '＜ 耶 稣 预 言 受 难 和 复 活 （ 太   1 6 : 2 0 - 2 8 ； 可   8 : 3 1 - 9 : 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25324', '42', '9', '22', '又 说 ： “ 人 子 必 须 受 许 多 的 苦 ， 被 长 老 、 祭 司 长 、 和 文 士 弃 绝 ， 并 且 被 杀 ， 第 三 日 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25325', '42', '9', '23', '耶 稣 又 对 众 人 说 ： “ 若 有 人 要 跟 从 我 ， 就 当 舍 己 ， 天 天 背 起 他 的 十 字 架 来 跟 从 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25326', '42', '9', '24', '因 为 ， 凡 要 救 自 己 生 命 ｛ 生 命 ： 或 译 灵 魂 ； 下 同 ｝ 的 ， 必 丧 掉 生 命 ； 凡 为 我 丧 掉 生 命 的 ， 必 救 了 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25327', '42', '9', '25', '人 若 赚 得 全 世 界 ， 却 丧 了 自 己 ， 赔 上 自 己 ， 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25328', '42', '9', '26', '凡 把 我 和 我 的 道 当 作 可 耻 的 ， 人 子 在 自 己 的 荣 耀 里 ， 并 天 父 与 圣 天 使 的 荣 耀 里 降 临 的 时 候 ， 也 要 把 那 人 当 作 可 耻 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25329', '42', '9', '27', '我 实 在 告 诉 你 们 ， 站 在 这 里 的 ， 有 人 在 没 尝 死 味 以 前 ， 必 看 见   神 的 国 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25330', '42', '9', '28', '＜ 耶 稣 改 变 形 像 （ 太   1 7 : 1 - 8 ； 可   9 : 2 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25331', '42', '9', '29', '正 祷 告 的 时 候 ， 他 的 面 貌 就 改 变 了 ， 衣 服 洁 白 放 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25332', '42', '9', '30', '忽 然 有 摩 西 、 以 利 亚 两 个 人 同 耶 稣 说 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25333', '42', '9', '31', '他 们 在 荣 光 里 显 现 ， 谈 论 耶 稣 去 世 的 事 ， 就 是 他 在 耶 路 撒 冷 将 要 成 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25334', '42', '9', '32', '彼 得 和 他 的 同 伴 都 打 盹 ， 既 清 醒 了 ， 就 看 见 耶 稣 的 荣 光 ， 并 同 他 站 着 的 那 两 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25335', '42', '9', '33', '二 人 正 要 和 耶 稣 分 离 的 时 候 ， 彼 得 对 耶 稣 说 ： “ 夫 子 ， 我 们 在 这 里 真 好 ！ 可 以 搭 三 座 棚 ， 一 座 为 你 ， 一 座 为 摩 西 ， 一 座 为 以 利 亚 。 ” 他 却 不 知 道 所 说 的 是 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25336', '42', '9', '34', '说 这 话 的 时 候 ， 有 一 朵 云 彩 来 遮 盖 他 们 ； 他 们 进 入 云 彩 里 就 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25337', '42', '9', '35', '有 声 音 从 云 彩 里 出 来 ， 说 ： “ 这 是 我 的 儿 子 ， 我 所 拣 选 的 ｛ 有 古 卷 ： 这 是 我 的 爱 子 ｝ ， 你 们 要 听 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25338', '42', '9', '36', '声 音 住 了 ， 只 见 耶 稣 一 人 在 那 里 。 当 那 些 日 子 ， 门 徒 不 提 所 看 见 的 事 ， 一 样 也 不 告 诉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25339', '42', '9', '37', '＜ 治 好 被 污 鬼 附 身 的 孩 子 （ 太   1 7 : 1 4 - 1 8 ； 可   9 : 1 4 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25340', '42', '9', '38', '其 中 有 一 人 喊 叫 说 ： “ 夫 子 ！ 求 你 看 顾 我 的 儿 子 ， 因 为 他 是 我 的 独 生 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25341', '42', '9', '39', '他 被 鬼 抓 住 就 忽 然 喊 叫 ； 鬼 又 叫 他 抽 疯 ， 口 中 流 沫 ， 并 且 重 重 地 伤 害 他 ， 难 以 离 开 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25342', '42', '9', '40', '我 求 过 你 的 门 徒 ， 把 鬼 赶 出 去 ， 他 们 却 是 不 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25343', '42', '9', '41', '耶 稣 说 ： “ 嗳 ！ 这 又 不 信 又 悖 谬 的 世 代 啊 ， 我 在 你 们 这 里 ， 忍 耐 你 们 要 到 几 时 呢 ？ 将 你 的 儿 子 带 到 这 里 来 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25344', '42', '9', '42', '正 来 的 时 候 ， 鬼 把 他 摔 倒 ， 叫 他 重 重 地 抽 疯 。 耶 稣 就 斥 责 那 污 鬼 ， 把 孩 子 治 好 了 ， 交 给 他 父 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25345', '42', '9', '43', '＜ 耶 稣 第 二 次 预 言 他 的 死 （ 太   1 7 : 2 2 - 2 3 ； 可   9 : 3 0 - 3 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25346', '42', '9', '44', '“ 你 们 要 把 这 些 话 存 在 耳 中 ， 因 为 人 子 将 要 被 交 在 人 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25347', '42', '9', '45', '他 们 不 明 白 这 话 ， 意 思 乃 是 隐 藏 的 ， 叫 他 们 不 能 明 白 ， 他 们 也 不 敢 问 这 话 的 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25348', '42', '9', '46', '＜ 谁 最 伟 大 （ 太   1 8 : 1 - 5 ； 可   9 : 3 3 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25349', '42', '9', '47', '耶 稣 看 出 他 们 心 中 的 议 论 ， 就 领 一 个 小 孩 子 来 ， 叫 他 站 在 自 己 旁 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25350', '42', '9', '48', '对 他 们 说 ： “ 凡 为 我 名 接 待 这 小 孩 子 的 ， 就 是 接 待 我 ； 凡 接 待 我 的 ， 就 是 接 待 那 差 我 来 的 。 你 们 中 间 最 小 的 ， 他 便 为 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25351', '42', '9', '49', '＜ 不 敌 挡 你 们 就 是 帮 助 你 们 （ 可   9 : 3 8 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25352', '42', '9', '50', '耶 稣 说 ： “ 不 要 禁 止 他 ； 因 为 不 敌 挡 你 们 的 ， 就 是 帮 助 你 们 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25353', '42', '9', '51', '＜ 不 接 待 主 的 村 庄 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25354', '42', '9', '52', '便 打 发 使 者 在 他 前 头 走 。 他 们 到 了 撒 马 利 亚 的 一 个 村 庄 ， 要 为 他 预 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25355', '42', '9', '53', '那 里 的 人 不 接 待 他 ， 因 他 面 向 耶 路 撒 冷 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25356', '42', '9', '54', '他 的 门 徒 雅 各 、 约 翰 看 见 了 ， 就 说 ： “ 主 啊 ， 你 要 我 们 吩 咐 火 从 天 上 降 下 来 烧 灭 他 们 ， 像 以 利 亚 所 做 的 ｛ 有 古 卷 没 有 像 以 利 亚 所 做 的 这 几 个 字 ｝ 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25357', '42', '9', '55', '耶 稣 转 身 责 备 两 个 门 徒 ， 说 ： “ 你 们 的 心 如 何 ， 你 们 并 不 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25358', '42', '9', '56', '人 子 来 不 是 要 灭 人 的 性 命 ｛ 性 命 或 译 ： 灵 魂 ； 下 同 ｝ ， 是 要 救 人 的 性 命 。 ” 说 着 就 往 别 的 村 庄 去 了 ｛ 有 古 卷 只 有 五 十 五 节 首 句 ， 五 十 六 节 末 句 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25359', '42', '9', '57', '＜ 要 跟 从 耶 稣 的 人 （ 太   8 : 1 9 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25360', '42', '9', '58', '耶 稣 说 ： “ 狐 狸 有 洞 ， 天 空 的 飞 鸟 有 窝 ， 只 是 人 子 没 有 枕 头 的 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25361', '42', '9', '59', '又 对 一 个 人 说 ： “ 跟 从 我 来 ！ ” 那 人 说 ： “ 主 ， 容 我 先 回 去 埋 葬 我 的 父 亲 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25362', '42', '9', '60', '耶 稣 说 ： “ 任 凭 死 人 埋 葬 他 们 的 死 人 ， 你 只 管 去 传 扬 神 国 的 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25363', '42', '9', '61', '又 有 一 人 说 ： “ 主 ， 我 要 跟 从 你 ， 但 容 我 先 去 辞 别 我 家 里 的 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25364', '42', '9', '62', '耶 稣 说 ： “ 手 扶 着 犁 向 后 看 的 ， 不 配 进 神 的 国 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25365', '42', '10', '1', '＜ 主 差 遣 七 十 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25366', '42', '10', '2', '就 对 他 们 说 ： “ 要 收 的 庄 稼 多 ， 做 工 的 人 少 。 所 以 ， 你 们 当 求 庄 稼 的 主 打 发 工 人 出 去 收 他 的 庄 稼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25367', '42', '10', '3', '你 们 去 吧 ！ 我 差 你 们 出 去 ， 如 同 羊 羔 进 入 狼 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25368', '42', '10', '4', '不 要 带 钱 囊 ， 不 要 带 口 袋 ， 不 要 带 鞋 ； 在 路 上 也 不 要 问 人 的 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25369', '42', '10', '5', '无 论 进 哪 一 家 ， 先 要 说 ： ‘ 愿 这 一 家 平 安 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25370', '42', '10', '6', '那 里 若 有 当 得 平 安 的 人 ｛ 当 得 平 安 的 人 ： 原 文 是 平 安 之 子 ｝ ， 你 们 所 求 的 平 安 就 必 临 到 那 家 ； 不 然 ， 就 归 与 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25371', '42', '10', '7', '你 们 要 住 在 那 家 ， 吃 喝 他 们 所 供 给 的 ， 因 为 工 人 得 工 价 是 应 当 的 ； 不 要 从 这 家 搬 到 那 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25372', '42', '10', '8', '无 论 进 哪 一 城 ， 人 若 接 待 你 们 ， 给 你 们 摆 上 什 么 ， 你 们 就 吃 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25373', '42', '10', '9', '要 医 治 那 城 里 的 病 人 ， 对 他 们 说 ： ‘ 神 的 国 临 近 你 们 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25374', '42', '10', '10', '无 论 进 哪 一 城 ， 人 若 不 接 待 你 们 ， 你 们 就 到 街 上 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25375', '42', '10', '11', '说 ： ‘ 就 是 你 们 城 里 的 尘 土 黏 在 我 们 的 脚 上 ， 我 们 也 当 着 你 们 擦 去 。 虽 然 如 此 ， 你 们 该 知 道 神 的 国 临 近 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25376', '42', '10', '12', '我 告 诉 你 们 ， 当 审 判 的 日 子 ， 所 多 玛 所 受 的 ， 比 那 城 还 容 易 受 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25377', '42', '10', '13', '＜ 不 悔 改 的 城 有 祸 了 （ 太   1 1 : 2 0 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25378', '42', '10', '14', '当 审 判 的 日 子 ， 泰 尔 、 西 顿 所 受 的 ， 比 你 们 还 容 易 受 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25379', '42', '10', '15', '迦 百 农 啊 ， 你 已 经 升 到 天 上 ｛ 或 译 ： 你 将 要 升 到 天 上 吗 ｝ ， 将 来 必 推 下 阴 间 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25380', '42', '10', '16', '又 对 门 徒 说 ： “ 听 从 你 们 的 就 是 听 从 我 ； 弃 绝 你 们 的 就 是 弃 绝 我 ； 弃 绝 我 的 就 是 弃 绝 那 差 我 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25381', '42', '10', '17', '＜ 七 十 个 人 回 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25382', '42', '10', '18', '耶 稣 对 他 们 说 ： “ 我 曾 看 见 撒 但 从 天 上 坠 落 ， 像 闪 电 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25383', '42', '10', '19', '我 已 经 给 你 们 权 柄 可 以 践 踏 蛇 和 蝎 子 ， 又 胜 过 仇 敌 一 切 的 能 力 ， 断 没 有 什 么 能 害 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25384', '42', '10', '20', '然 而 ， 不 要 因 鬼 服 了 你 们 就 欢 喜 ， 要 因 你 们 的 名 记 录 在 天 上 欢 喜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25385', '42', '10', '21', '＜ 耶 稣 的 欢 乐 （ 太   1 1 : 2 5 - 2 7 ； 1 3 : 1 6 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25386', '42', '10', '22', '一 切 所 有 的 都 是 我 父 交 付 我 的 ； 除 了 父 ， 没 有 人 知 道 子 是 谁 ； 除 了 子 和 子 所 愿 意 指 示 的 ， 没 有 人 知 道 父 是 谁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25387', '42', '10', '23', '耶 稣 转 身 暗 暗 地 对 门 徒 说 ： “ 看 见 你 们 所 看 见 的 ， 那 眼 睛 就 有 福 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25388', '42', '10', '24', '我 告 诉 你 们 ， 从 前 有 许 多 先 知 和 君 王 要 看 你 们 所 看 的 ， 却 没 有 看 见 ， 要 听 你 们 所 听 的 ， 却 没 有 听 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25389', '42', '10', '25', '＜ 好 撒 马 利 亚 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25390', '42', '10', '26', '耶 稣 对 他 说 ： “ 律 法 上 写 的 是 什 么 ？ 你 念 的 是 怎 样 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25391', '42', '10', '27', '他 回 答 说 ： “ 你 要 尽 心 、 尽 性 、 尽 力 、 尽 意 爱 主 ─ ─ 你 的 神 ； 又 要 爱 邻 舍 如 同 自 己 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25392', '42', '10', '28', '耶 稣 说 ： “ 你 回 答 的 是 ； 你 这 样 行 ， 就 必 得 永 生 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25393', '42', '10', '29', '那 人 要 显 明 自 己 有 理 ， 就 对 耶 稣 说 ： “ 谁 是 我 的 邻 舍 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25394', '42', '10', '30', '耶 稣 回 答 说 ： “ 有 一 个 人 从 耶 路 撒 冷 下 耶 利 哥 去 ， 落 在 强 盗 手 中 。 他 们 剥 去 他 的 衣 裳 ， 把 他 打 个 半 死 ， 就 丢 下 他 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25395', '42', '10', '31', '偶 然 有 一 个 祭 司 从 这 条 路 下 来 ， 看 见 他 就 从 那 边 过 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25396', '42', '10', '32', '又 有 一 个 利 未 人 来 到 这 地 方 ， 看 见 他 ， 也 照 样 从 那 边 过 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25397', '42', '10', '33', '惟 有 一 个 撒 马 利 亚 人 行 路 来 到 那 里 ， 看 见 他 就 动 了 慈 心 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25398', '42', '10', '34', '上 前 用 油 和 酒 倒 在 他 的 伤 处 ， 包 裹 好 了 ， 扶 他 骑 上 自 己 的 牲 口 ， 带 到 店 里 去 照 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25399', '42', '10', '35', '第 二 天 拿 出 二 钱 银 子 来 ， 交 给 店 主 ， 说 ： ‘ 你 且 照 应 他 ； 此 外 所 费 用 的 ， 我 回 来 必 还 你 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25400', '42', '10', '36', '你 想 ， 这 三 个 人 哪 一 个 是 落 在 强 盗 手 中 的 邻 舍 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25401', '42', '10', '37', '他 说 ： “ 是 怜 悯 他 的 。 ” 耶 稣 说 ： “ 你 去 照 样 行 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25402', '42', '10', '38', '＜ 耶 稣 探 望 马 大 和 马 利 亚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25403', '42', '10', '39', '她 有 一 个 妹 子 ， 名 叫 马 利 亚 ， 在 耶 稣 脚 前 坐 着 听 他 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25404', '42', '10', '40', '马 大 伺 候 的 事 多 ， 心 里 忙 乱 ， 就 进 前 来 ， 说 ： “ 主 啊 ， 我 的 妹 子 留 下 我 一 个 人 伺 候 ， 你 不 在 意 吗 ？ 请 吩 咐 她 来 帮 助 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25405', '42', '10', '41', '耶 稣 回 答 说 ： “ 马 大 ！ 马 大 ！ 你 为 许 多 的 事 思 虑 烦 扰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25406', '42', '10', '42', '但 是 不 可 少 的 只 有 一 件 ； 马 利 亚 已 经 选 择 那 上 好 的 福 分 ， 是 不 能 夺 去 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25407', '42', '11', '1', '＜ 祷 告 的 教 训 （ 太   6 : 9 - 1 3 ； 7 : 7 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25408', '42', '11', '2', '耶 稣 说 ： “ 你 们 祷 告 的 时 候 ， 要 说 ： 我 们 在 天 上 的 父 ｛ 有 古 卷 ： 父 啊 ｝ ： 愿 人 都 尊 你 的 名 为 圣 。 愿 你 的 国 降 临 ； 愿 你 的 旨 意 行 在 地 上 ， 如 同 行 在 天 上 ｛ 有 古 卷 没 有 愿 你 的 旨 意 … … ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25409', '42', '11', '3', '我 们 日 用 的 饮 食 ， 天 天 赐 给 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25410', '42', '11', '4', '赦 免 我 们 的 罪 ， 因 为 我 们 也 赦 免 凡 亏 欠 我 们 的 人 。 不 叫 我 们 遇 见 试 探 ； 救 我 们 脱 离 凶 恶 ｛ 有 古 卷 没 有 末 句 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25411', '42', '11', '5', '耶 稣 又 说 ： “ 你 们 中 间 谁 有 一 个 朋 友 半 夜 到 他 那 里 去 ， 说 ： ‘ 朋 友 ！ 请 借 给 我 三 个 饼 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25412', '42', '11', '6', '因 为 我 有 一 个 朋 友 行 路 ， 来 到 我 这 里 ， 我 没 有 什 么 给 他 摆 上 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25413', '42', '11', '7', '那 人 在 里 面 回 答 说 ： ‘ 不 要 搅 扰 我 ， 门 已 经 关 闭 ， 孩 子 们 也 同 我 在 床 上 了 ， 我 不 能 起 来 给 你 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25414', '42', '11', '8', '我 告 诉 你 们 ， 虽 不 因 他 是 朋 友 起 来 给 他 ， 但 因 他 情 词 迫 切 地 直 求 ， 就 必 起 来 照 他 所 需 用 的 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25415', '42', '11', '9', '我 又 告 诉 你 们 ， 你 们 祈 求 ， 就 给 你 们 ； 寻 找 ， 就 寻 见 ； 叩 门 ， 就 给 你 们 开 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25416', '42', '11', '10', '因 为 ， 凡 祈 求 的 ， 就 得 着 ； 寻 找 的 ， 就 寻 见 ； 叩 门 的 ， 就 给 他 开 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25417', '42', '11', '11', '你 们 中 间 作 父 亲 的 ， 谁 有 儿 子 求 饼 ， 反 给 他 石 头 呢 ？ 求 鱼 ， 反 拿 蛇 当 鱼 给 他 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25418', '42', '11', '12', '求 鸡 蛋 ， 反 给 他 蝎 子 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25419', '42', '11', '13', '你 们 虽 然 不 好 ， 尚 且 知 道 拿 好 东 西 给 儿 女 ； 何 况 天 父 ， 岂 不 更 将 圣 灵 给 求 他 的 人 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25420', '42', '11', '14', '＜ 耶 稣 和 别 西 卜 （ 太   1 2 : 2 2 - 3 0 ； 可   3 : 2 0 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25421', '42', '11', '15', '内 中 却 有 人 说 ： “ 他 是 靠 着 鬼 王 别 西 卜 赶 鬼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25422', '42', '11', '16', '又 有 人 试 探 耶 稣 ， 向 他 求 从 天 上 来 的 神 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25423', '42', '11', '17', '他 晓 得 他 们 的 意 念 ， 便 对 他 们 说 ： “ 凡 一 国 自 相 纷 争 ， 就 成 为 荒 场 ； 凡 一 家 自 相 纷 争 ， 就 必 败 落 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25424', '42', '11', '18', '若 撒 但 自 相 纷 争 ， 他 的 国 怎 能 站 得 住 呢 ？ 因 为 你 们 说 我 是 靠 着 别 西 卜 赶 鬼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25425', '42', '11', '19', '我 若 靠 着 别 西 卜 赶 鬼 ， 你 们 的 子 弟 赶 鬼 又 靠 着 谁 呢 ？ 这 样 ， 他 们 就 要 断 定 你 们 的 是 非 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25426', '42', '11', '20', '我 若 靠 着 神 的 能 力 赶 鬼 ， 这 就 是 神 的 国 临 到 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25427', '42', '11', '21', '壮 士 披 挂 整 齐 ， 看 守 自 己 的 住 宅 ， 他 所 有 的 都 平 安 无 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25428', '42', '11', '22', '但 有 一 个 比 他 更 壮 的 来 ， 胜 过 他 ， 就 夺 去 他 所 倚 靠 的 盔 甲 兵 器 ， 又 分 了 他 的 赃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25429', '42', '11', '23', '不 与 我 相 合 的 ， 就 是 敌 我 的 ； 不 同 我 收 聚 的 ， 就 是 分 散 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25430', '42', '11', '24', '＜ 污 鬼 回 来 （ 太   1 2 : 4 3 - 4 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25431', '42', '11', '25', '到 了 ， 就 看 见 里 面 打 扫 干 净 ， 修 饰 好 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25432', '42', '11', '26', '便 去 另 带 了 七 个 比 自 己 更 恶 的 鬼 来 ， 都 进 去 住 在 那 里 。 那 人 末 后 的 景 况 比 先 前 更 不 好 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25433', '42', '11', '27', '＜ 真 正 的 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25434', '42', '11', '28', '耶 稣 说 ： “ 是 ， 却 还 不 如 听 神 之 道 而 遵 守 的 人 有 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25435', '42', '11', '29', '＜ 求 神 迹 的 受 责 备 （ 太   1 2 : 3 8 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25436', '42', '11', '30', '约 拿 怎 样 为 尼 尼 微 人 成 了 神 迹 ， 人 子 也 要 照 样 为 这 世 代 的 人 成 了 神 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25437', '42', '11', '31', '当 审 判 的 时 候 ， 南 方 的 女 王 要 起 来 定 这 世 代 的 罪 ； 因 为 她 从 地 极 而 来 ， 要 听 所 罗 门 的 智 慧 话 。 看 哪 ！ 在 这 里 有 一 人 比 所 罗 门 更 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25438', '42', '11', '32', '当 审 判 的 时 候 ， 尼 尼 微 人 要 起 来 定 这 世 代 的 罪 ， 因 为 尼 尼 微 人 听 了 约 拿 所 传 的 就 悔 改 了 。 看 哪 ！ 在 这 里 有 一 人 比 约 拿 更 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25439', '42', '11', '33', '＜ 论 心 里 的 光 （ 太   5 : 1 5 ； 6 : 2 2 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25440', '42', '11', '34', '你 眼 睛 就 是 身 上 的 灯 。 你 的 眼 睛 若 了 亮 ， 全 身 就 光 明 ； 眼 睛 若 昏 花 ， 全 身 就 黑 暗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25441', '42', '11', '35', '所 以 ， 你 要 省 察 ， 恐 怕 你 里 头 的 光 或 者 黑 暗 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25442', '42', '11', '36', '若 是 你 全 身 光 明 ， 毫 无 黑 暗 ， 就 必 全 然 光 明 ， 如 同 灯 的 明 光 照 亮 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25443', '42', '11', '37', '＜ 谴 责 法 利 赛 人 和 文 士 （ 太   2 3 : 1 - 3 6 ； 可   1 2 : 3 8 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25444', '42', '11', '38', '这 法 利 赛 人 看 见 耶 稣 饭 前 不 洗 手 便 诧 异 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25445', '42', '11', '39', '主 对 他 说 ： “ 如 今 你 们 法 利 赛 人 洗 净 杯 盘 的 外 面 ， 你 们 里 面 却 满 了 勒 索 和 邪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25446', '42', '11', '40', '无 知 的 人 哪 ， 造 外 面 的 ， 不 也 造 里 面 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25447', '42', '11', '41', '只 要 把 里 面 的 施 舍 给 人 ， 凡 物 于 你 们 就 都 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25448', '42', '11', '42', '“ 你 们 法 利 赛 人 有 祸 了 ！ 因 为 你 们 将 薄 荷 、 芸 香 并 各 样 菜 蔬 献 上 十 分 之 一 ， 那 公 义 和 爱 神 的 事 反 倒 不 行 了 。 这 原 是 你 们 当 行 的 ； 那 也 是 不 可 不 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25449', '42', '11', '43', '你 们 法 利 赛 人 有 祸 了 ！ 因 为 你 们 喜 爱 会 堂 里 的 首 位 ， 又 喜 爱 人 在 街 市 上 问 你 们 的 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25450', '42', '11', '44', '你 们 有 祸 了 ！ 因 为 你 们 如 同 不 显 露 的 坟 墓 ， 走 在 上 面 的 人 并 不 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25451', '42', '11', '45', '律 法 师 中 有 一 个 回 答 耶 稣 说 ： “ 夫 子 ！ 你 这 样 说 也 把 我 们 糟 蹋 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25452', '42', '11', '46', '耶 稣 说 ： “ 你 们 律 法 师 也 有 祸 了 ！ 因 为 你 们 把 难 担 的 担 子 放 在 人 身 上 ， 自 己 一 个 指 头 却 不 肯 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25453', '42', '11', '47', '你 们 有 祸 了 ！ 因 为 你 们 修 造 先 知 的 坟 墓 ， 那 先 知 正 是 你 们 的 祖 宗 所 杀 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25454', '42', '11', '48', '可 见 你 们 祖 宗 所 做 的 事 ， 你 们 又 证 明 又 喜 欢 ； 因 为 他 们 杀 了 先 知 ， 你 们 修 造 先 知 的 坟 墓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25455', '42', '11', '49', '所 以 神 用 智 慧 ｛ 用 智 慧 ： 或 译 的 智 者 ｝ 曾 说 ： ‘ 我 要 差 遣 先 知 和 使 徒 到 他 们 那 里 去 ， 有 的 他 们 要 杀 害 ， 有 的 他 们 要 逼 迫 ’ ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25456', '42', '11', '50', '使 创 世 以 来 所 流 众 先 知 血 的 罪 都 要 问 在 这 世 代 的 人 身 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25457', '42', '11', '51', '就 是 从 亚 伯 的 血 起 ， 直 到 被 杀 在 坛 和 殿 中 间 撒 迦 利 亚 的 血 为 止 。 我 实 在 告 诉 你 们 ， 这 都 要 问 在 这 世 代 的 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25458', '42', '11', '52', '你 们 律 法 师 有 祸 了 ！ 因 为 你 们 把 知 识 的 钥 匙 夺 了 去 ， 自 己 不 进 去 ， 正 要 进 去 的 人 你 们 也 阻 挡 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25459', '42', '11', '53', '耶 稣 从 那 里 出 来 ， 文 士 和 法 利 赛 人 就 极 力 地 催 逼 他 ， 引 动 他 多 说 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25460', '42', '11', '54', '私 下 窥 听 ， 要 拿 他 的 话 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25461', '42', '12', '1', '＜ 防 备 假 冒 为 善 （ 太   1 0 : 2 6 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25462', '42', '12', '2', '掩 盖 的 事 没 有 不 露 出 来 的 ； 隐 藏 的 事 没 有 不 被 人 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25463', '42', '12', '3', '因 此 ， 你 们 在 暗 中 所 说 的 ， 将 要 在 明 处 被 人 听 见 ； 在 内 室 附 耳 所 说 的 ， 将 要 在 房 上 被 人 宣 扬 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25464', '42', '12', '4', '＜ 该 怕 的 是 谁 （ 太   1 0 : 2 8 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25465', '42', '12', '5', '我 要 指 示 你 们 当 怕 的 是 谁 ： 当 怕 那 杀 了 以 后 又 有 权 柄 丢 在 地 狱 里 的 。 我 实 在 告 诉 你 们 ， 正 要 怕 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25466', '42', '12', '6', '五 个 麻 雀 不 是 卖 二 分 银 子 吗 ？ 但 在 神 面 前 ， 一 个 也 不 忘 记 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25467', '42', '12', '7', '就 是 你 们 的 头 发 ， 也 都 被 数 过 了 。 不 要 惧 怕 ， 你 们 比 许 多 麻 雀 还 贵 重 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25468', '42', '12', '8', '＜ 在 人 的 面 前 承 认 基 督 （ 太   1 0 : 3 2 - 3 3 ； 1 2 : 3 2 ； 1 0 : 1 9 - 2 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25469', '42', '12', '9', '在 人 面 前 不 认 我 的 ， 人 子 在 神 的 使 者 面 前 也 必 不 认 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25470', '42', '12', '10', '凡 说 话 干 犯 人 子 的 ， 还 可 得 赦 免 ； 惟 独 亵 渎 圣 灵 的 ， 总 不 得 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25471', '42', '12', '11', '人 带 你 们 到 会 堂 ， 并 官 府 和 有 权 柄 的 人 面 前 ， 不 要 思 虑 怎 么 分 诉 ， 说 什 么 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25472', '42', '12', '12', '因 为 正 在 那 时 候 ， 圣 灵 要 指 教 你 们 当 说 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25473', '42', '12', '13', '＜ 无 知 财 主 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25474', '42', '12', '14', '耶 稣 说 ： “ 你 这 个 人 ！ 谁 立 我 作 你 们 断 事 的 官 ， 给 你 们 分 家 业 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25475', '42', '12', '15', '于 是 对 众 人 说 ： “ 你 们 要 谨 慎 自 守 ， 免 去 一 切 的 贪 心 ， 因 为 人 的 生 命 不 在 乎 家 道 丰 富 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25476', '42', '12', '16', '就 用 比 喻 对 他 们 说 ： “ 有 一 个 财 主 田 产 丰 盛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25477', '42', '12', '17', '自 己 心 里 思 想 说 ： ‘ 我 的 出 产 没 有 地 方 收 藏 ， 怎 么 办 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25478', '42', '12', '18', '又 说 ： ‘ 我 要 这 么 办 ： 要 把 我 的 仓 房 拆 了 ， 另 盖 更 大 的 ， 在 那 里 好 收 藏 我 一 切 的 粮 食 和 财 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25479', '42', '12', '19', '然 后 要 对 我 的 灵 魂 说 ： 灵 魂 哪 ， 你 有 许 多 财 物 积 存 ， 可 作 多 年 的 费 用 ， 只 管 安 安 逸 逸 地 吃 喝 快 乐 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25480', '42', '12', '20', '神 却 对 他 说 ： ‘ 无 知 的 人 哪 ， 今 夜 必 要 你 的 灵 魂 ； 你 所 预 备 的 要 归 谁 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25481', '42', '12', '21', '凡 为 自 己 积 财 ， 在 神 面 前 却 不 富 足 的 ， 也 是 这 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25482', '42', '12', '22', '＜ 不 要 忧 虑 （ 太   6 : 2 5 - 3 4 , 1 9 - 2 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25483', '42', '12', '23', '因 为 生 命 胜 于 饮 食 ， 身 体 胜 于 衣 裳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25484', '42', '12', '24', '你 想 乌 鸦 ， 也 不 种 也 不 收 ， 又 没 有 仓 又 没 有 库 ， 神 尚 且 养 活 它 。 你 们 比 飞 鸟 是 何 等 地 贵 重 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25485', '42', '12', '25', '你 们 哪 一 个 能 用 思 虑 使 寿 数 多 加 一 刻 呢 ｛ 或 译 ： 使 身 量 多 加 一 肘 呢 ｝ ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25486', '42', '12', '26', '这 最 小 的 事 ， 你 们 尚 且 不 能 做 ， 为 什 么 还 忧 虑 其 余 的 事 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25487', '42', '12', '27', '你 想 百 合 花 怎 么 长 起 来 ； 它 也 不 劳 苦 ， 也 不 纺 线 。 然 而 我 告 诉 你 们 ， 就 是 所 罗 门 极 荣 华 的 时 候 ， 他 所 穿 戴 的 ， 还 不 如 这 花 一 朵 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25488', '42', '12', '28', '你 们 这 小 信 的 人 哪 ， 野 地 里 的 草 今 天 还 在 ， 明 天 就 丢 在 炉 里 ， 神 还 给 它 这 样 的 妆 饰 ， 何 况 你 们 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25489', '42', '12', '29', '你 们 不 要 求 吃 什 么 ， 喝 什 么 ， 也 不 要 挂 心 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25490', '42', '12', '30', '这 都 是 外 邦 人 所 求 的 。 你 们 必 须 用 这 些 东 西 ， 你 们 的 父 是 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25491', '42', '12', '31', '你 们 只 要 求 他 的 国 ， 这 些 东 西 就 必 加 给 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25492', '42', '12', '32', '你 们 这 小 群 ， 不 要 惧 怕 ， 因 为 你 们 的 父 乐 意 把 国 赐 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25493', '42', '12', '33', '你 们 要 变 卖 所 有 的 赒 济 人 ， 为 自 己 预 备 永 不 坏 的 钱 囊 ， 用 不 尽 的 财 宝 在 天 上 ， 就 是 贼 不 能 近 、 虫 不 能 蛀 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25494', '42', '12', '34', '因 为 ， 你 们 的 财 宝 在 哪 里 ， 你 们 的 心 也 在 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25495', '42', '12', '35', '＜ 警 醒 的 仆 人 （ 太   2 4 : 4 5 - 5 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25496', '42', '12', '36', '自 己 好 像 仆 人 等 候 主 人 从 婚 姻 的 筵 席 上 回 来 。 他 来 到 ， 叩 门 ， 就 立 刻 给 他 开 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25497', '42', '12', '37', '主 人 来 了 ， 看 见 仆 人 警 醒 ， 那 仆 人 就 有 福 了 。 我 实 在 告 诉 你 们 ， 主 人 必 叫 他 们 坐 席 ， 自 己 束 上 带 ， 进 前 伺 候 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25498', '42', '12', '38', '或 是 二 更 天 来 ， 或 是 三 更 天 来 ， 看 见 仆 人 这 样 ， 那 仆 人 就 有 福 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25499', '42', '12', '39', '家 主 若 知 道 贼 什 么 时 候 来 ， 就 必 警 醒 ， 不 容 贼 挖 透 房 屋 ， 这 是 你 们 所 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25500', '42', '12', '40', '你 们 也 要 预 备 ； 因 为 你 们 想 不 到 的 时 候 ， 人 子 就 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25501', '42', '12', '41', '彼 得 说 ： “ 主 啊 ， 这 比 喻 是 为 我 们 说 的 呢 ？ 还 是 为 众 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25502', '42', '12', '42', '主 说 ： “ 谁 是 那 忠 心 有 见 识 的 管 家 ， 主 人 派 他 管 理 家 里 的 人 ， 按 时 分 粮 给 他 们 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25503', '42', '12', '43', '主 人 来 到 ， 看 见 仆 人 这 样 行 ， 那 仆 人 就 有 福 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25504', '42', '12', '44', '我 实 在 告 诉 你 们 ， 主 人 要 派 他 管 理 一 切 所 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25505', '42', '12', '45', '那 仆 人 若 心 里 说 ： ‘ 我 的 主 人 必 来 得 迟 ’ ， 就 动 手 打 仆 人 和 使 女 ， 并 且 吃 喝 醉 酒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25506', '42', '12', '46', '在 他 想 不 到 的 日 子 ， 不 知 道 的 时 辰 ， 那 仆 人 的 主 人 要 来 ， 重 重 地 处 治 他 ｛ 或 译 ： 把 他 腰 斩 了 ｝ ， 定 他 和 不 忠 心 的 人 同 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25507', '42', '12', '47', '仆 人 知 道 主 人 的 意 思 ， 却 不 预 备 ， 又 不 顺 他 的 意 思 行 ， 那 仆 人 必 多 受 责 打 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25508', '42', '12', '48', '惟 有 那 不 知 道 的 ， 做 了 当 受 责 打 的 事 ， 必 少 受 责 打 ； 因 为 多 给 谁 ， 就 向 谁 多 取 ； 多 托 谁 ， 就 向 谁 多 要 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25509', '42', '12', '49', '＜ 分 裂 的 原 因 （ 太   1 0 : 3 4 - 3 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25510', '42', '12', '50', '我 有 当 受 的 洗 还 没 有 成 就 ， 我 是 何 等 地 迫 切 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25511', '42', '12', '51', '你 们 以 为 我 来 ， 是 叫 地 上 太 平 吗 ？ 我 告 诉 你 们 ， 不 是 ， 乃 是 叫 人 纷 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25512', '42', '12', '52', '从 今 以 后 ， 一 家 五 个 人 将 要 纷 争 ： 三 个 人 和 两 个 人 相 争 ， 两 个 人 和 三 个 人 相 争 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25513', '42', '12', '53', '父 亲 和 儿 子 相 争 ， 儿 子 和 父 亲 相 争 ； 母 亲 和 女 儿 相 争 ， 女 儿 和 母 亲 相 争 ； 婆 婆 和 媳 妇 相 争 ， 媳 妇 和 婆 婆 相 争 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25514', '42', '12', '54', '＜ 分 辨 时 候 （ 太   1 6 : 2 - 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25515', '42', '12', '55', '起 了 南 风 ， 就 说 ： ‘ 将 要 燥 热 ’ ； 也 就 有 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25516', '42', '12', '56', '假 冒 为 善 的 人 哪 ， 你 们 知 道 分 辨 天 地 的 气 色 ， 怎 么 不 知 道 分 辨 这 时 候 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25517', '42', '12', '57', '＜ 同 对 头 和 解 （ 太   5 : 2 5 - 2 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25518', '42', '12', '58', '你 同 告 你 的 对 头 去 见 官 ， 还 在 路 上 ， 务 要 尽 力 地 和 他 了 结 ； 恐 怕 他 拉 你 到 官 面 前 ， 官 交 付 差 役 ， 差 役 把 你 下 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25519', '42', '12', '59', '我 告 诉 你 ， 若 有 半 文 钱 没 有 还 清 ， 你 断 不 能 从 那 里 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25520', '42', '13', '1', '＜ 悔 改 或 灭 亡 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25521', '42', '13', '2', '耶 稣 说 ： “ 你 们 以 为 这 些 加 利 利 人 比 众 加 利 利 人 更 有 罪 ， 所 以 受 这 害 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25522', '42', '13', '3', '我 告 诉 你 们 ， 不 是 的 ！ 你 们 若 不 悔 改 ， 都 要 如 此 灭 亡 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25523', '42', '13', '4', '从 前 西 罗 亚 楼 倒 塌 了 ， 压 死 十 八 个 人 ； 你 们 以 为 那 些 人 比 一 切 住 在 耶 路 撒 冷 的 人 更 有 罪 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25524', '42', '13', '5', '我 告 诉 你 们 ， 不 是 的 ！ 你 们 若 不 悔 改 ， 都 要 如 此 灭 亡 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25525', '42', '13', '6', '＜ 不 结 实 的 无 花 果 树 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25526', '42', '13', '7', '就 对 管 园 的 说 ： ‘ 看 哪 ， 我 这 三 年 来 到 这 无 花 果 树 前 找 果 子 ， 竟 找 不 着 。 把 它 砍 了 吧 ， 何 必 白 占 地 土 呢 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25527', '42', '13', '8', '管 园 的 说 ： ‘ 主 啊 ， 今 年 且 留 着 ， 等 我 周 围 掘 开 土 ， 加 上 粪 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25528', '42', '13', '9', '以 后 若 结 果 子 便 罢 ， 不 然 再 把 它 砍 了 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25529', '42', '13', '10', '＜ 安 息 日 治 好 驼 背 的 女 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25530', '42', '13', '11', '有 一 个 女 人 被 鬼 附 着 ， 病 了 十 八 年 ， 腰 弯 得 一 点 直 不 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25531', '42', '13', '12', '耶 稣 看 见 ， 便 叫 过 她 来 ， 对 她 说 ： “ 女 人 ， 你 脱 离 这 病 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25532', '42', '13', '13', '于 是 用 两 只 手 按 着 她 ； 她 立 刻 直 起 腰 来 ， 就 归 荣 耀 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25533', '42', '13', '14', '管 会 堂 的 因 为 耶 稣 在 安 息 日 治 病 ， 就 气 忿 忿 地 对 众 人 说 ： “ 有 六 日 应 当 做 工 ； 那 六 日 之 内 可 以 来 求 医 ， 在 安 息 日 却 不 可 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25534', '42', '13', '15', '主 说 ： “ 假 冒 为 善 的 人 哪 ， 难 道 你 们 各 人 在 安 息 日 不 解 开 槽 上 的 牛 、 驴 ， 牵 去 饮 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25535', '42', '13', '16', '况 且 这 女 人 本 是 亚 伯 拉 罕 的 后 裔 ， 被 撒 但 捆 绑 了 这 十 八 年 ， 不 当 在 安 息 日 解 开 她 的 绑 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25536', '42', '13', '17', '耶 稣 说 这 话 ， 他 的 敌 人 都 惭 愧 了 ； 众 人 因 他 所 行 一 切 荣 耀 的 事 ， 就 都 欢 喜 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25537', '42', '13', '18', '＜ 芥 菜 种 和 面 酵 的 比 喻 （ 太   1 3 : 3 1 - 3 3 ； 可   4 : 3 0 - 3 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25538', '42', '13', '19', '好 像 一 粒 芥 菜 种 ， 有 人 拿 去 种 在 园 子 里 ， 长 大 成 树 ， 天 上 的 飞 鸟 宿 在 它 的 枝 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25539', '42', '13', '20', '又 说 ： “ 我 拿 什 么 来 比 神 的 国 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25540', '42', '13', '21', '好 比 面 酵 ， 有 妇 人 拿 来 藏 在 三 斗 面 里 ， 直 等 全 团 都 发 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25541', '42', '13', '22', '＜ 当 进 窄 门 （ 太   7 : 1 3 - 1 4 , 2 1 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25542', '42', '13', '23', '有 一 个 人 问 他 说 ： “ 主 啊 ， 得 救 的 人 少 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25543', '42', '13', '24', '耶 稣 对 众 人 说 ： “ 你 们 要 努 力 进 窄 门 。 我 告 诉 你 们 ， 将 来 有 许 多 人 想 要 进 去 ， 却 是 不 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25544', '42', '13', '25', '及 至 家 主 起 来 关 了 门 ， 你 们 站 在 外 面 叩 门 ， 说 ： ‘ 主 啊 ， 给 我 们 开 门 ！ ’ 他 就 回 答 说 ： ‘ 我 不 认 识 你 们 ， 不 晓 得 你 们 是 哪 里 来 的 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25545', '42', '13', '26', '那 时 ， 你 们 要 说 ： ‘ 我 们 在 你 面 前 吃 过 喝 过 ， 你 也 在 我 们 的 街 上 教 训 过 人 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25546', '42', '13', '27', '他 要 说 ： ‘ 我 告 诉 你 们 ， 我 不 晓 得 你 们 是 哪 里 来 的 。 你 们 这 一 切 作 恶 的 人 ， 离 开 我 去 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25547', '42', '13', '28', '你 们 要 看 见 亚 伯 拉 罕 、 以 撒 、 雅 各 ， 和 众 先 知 都 在 神 的 国 里 ， 你 们 却 被 赶 到 外 面 ， 在 那 里 必 要 哀 哭 切 齿 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25548', '42', '13', '29', '从 东 、 从 西 、 从 南 、 从 北 将 有 人 来 ， 在 神 的 国 里 坐 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25549', '42', '13', '30', '只 是 有 在 后 的 ， 将 要 在 前 ； 有 在 前 的 ， 将 要 在 后 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25550', '42', '13', '31', '＜ 为 耶 路 撒 冷 哀 哭 （ 太   2 3 : 3 7 - 3 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25551', '42', '13', '32', '耶 稣 说 ： “ 你 们 去 告 诉 那 个 狐 狸 说 ： ‘ 今 天 、 明 天 我 赶 鬼 治 病 ， 第 三 天 我 的 事 就 成 全 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25552', '42', '13', '33', '虽 然 这 样 ， 今 天 、 明 天 、 后 天 ， 我 必 须 前 行 ， 因 为 先 知 在 耶 路 撒 冷 之 外 丧 命 是 不 能 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25553', '42', '13', '34', '耶 路 撒 冷 啊 ！ 耶 路 撒 冷 啊 ！ 你 常 杀 害 先 知 ， 又 用 石 头 打 死 那 奉 差 遣 到 你 这 里 来 的 人 。 我 多 次 愿 意 聚 集 你 的 儿 女 ， 好 像 母 鸡 把 小 鸡 聚 集 在 翅 膀 底 下 ； 只 是 你 们 不 愿 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25554', '42', '13', '35', '看 哪 ， 你 们 的 家 成 为 荒 场 留 给 你 们 。 我 告 诉 你 们 ， 从 今 以 后 你 们 不 得 再 见 我 ， 直 等 到 你 们 说 ： ‘ 奉 主 名 来 的 是 应 当 称 颂 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25555', '42', '14', '1', '＜ 在 安 息 日 治 好 臌 胀 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25556', '42', '14', '2', '在 他 面 前 有 一 个 患 水 臌 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25557', '42', '14', '3', '耶 稣 对 律 法 师 和 法 利 赛 人 说 ： “ 安 息 日 治 病 可 以 不 可 以 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25558', '42', '14', '4', '他 们 却 不 言 语 。 耶 稣 就 治 好 那 人 ， 叫 他 走 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25559', '42', '14', '5', '便 对 他 们 说 ： “ 你 们 中 间 谁 有 驴 或 有 牛 ， 在 安 息 日 掉 在 井 里 ， 不 立 时 拉 它 上 来 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25560', '42', '14', '6', '他 们 不 能 对 答 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25561', '42', '14', '7', '＜ 给 客 人 和 主 人 的 教 训 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25562', '42', '14', '8', '“ 你 被 人 请 去 赴 婚 姻 的 筵 席 ， 不 要 坐 在 首 位 上 ， 恐 怕 有 比 你 尊 贵 的 客 被 他 请 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25563', '42', '14', '9', '那 请 你 们 的 人 前 来 对 你 说 ： ‘ 让 座 给 这 一 位 吧 ！ ’ 你 就 羞 羞 惭 惭 地 退 到 末 位 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25564', '42', '14', '10', '你 被 请 的 时 候 ， 就 去 坐 在 末 位 上 ， 好 叫 那 请 你 的 人 来 对 你 说 ： ‘ 朋 友 ， 请 上 座 。 ’ 那 时 ， 你 在 同 席 的 人 面 前 就 有 光 彩 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25565', '42', '14', '11', '因 为 ， 凡 自 高 的 ， 必 降 为 卑 ； 自 卑 的 ， 必 升 为 高 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25566', '42', '14', '12', '耶 稣 又 对 请 他 的 人 说 ： “ 你 摆 设 午 饭 或 晚 饭 ， 不 要 请 你 的 朋 友 、 弟 兄 、 亲 属 ， 和 富 足 的 邻 舍 ， 恐 怕 他 们 也 请 你 ， 你 就 得 了 报 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25567', '42', '14', '13', '你 摆 设 筵 席 ， 倒 要 请 那 贫 穷 的 、 残 废 的 、 瘸 腿 的 、 瞎 眼 的 ， 你 就 有 福 了 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25568', '42', '14', '14', '因 为 他 们 没 有 什 么 可 报 答 你 。 到 义 人 复 活 的 时 候 ， 你 要 得 着 报 答 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25569', '42', '14', '15', '＜ 大 筵 席 的 比 喻 （ 太   2 2 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25570', '42', '14', '16', '耶 稣 对 他 说 ： “ 有 一 人 摆 设 大 筵 席 ， 请 了 许 多 客 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25571', '42', '14', '17', '到 了 坐 席 的 时 候 ， 打 发 仆 人 去 对 所 请 的 人 说 ： ‘ 请 来 吧 ！ 样 样 都 齐 备 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25572', '42', '14', '18', '众 人 一 口 同 音 地 推 辞 。 头 一 个 说 ： ‘ 我 买 了 一 块 地 ， 必 须 去 看 看 。 请 你 准 我 辞 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25573', '42', '14', '19', '又 有 一 个 说 ： ‘ 我 买 了 五 对 牛 ， 要 去 试 一 试 。 请 你 准 我 辞 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25574', '42', '14', '20', '又 有 一 个 说 ： ‘ 我 才 娶 了 妻 ， 所 以 不 能 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25575', '42', '14', '21', '那 仆 人 回 来 ， 把 这 事 都 告 诉 了 主 人 。 家 主 就 动 怒 ， 对 仆 人 说 ： ‘ 快 出 去 ， 到 城 里 大 街 小 巷 ， 领 那 贫 穷 的 、 残 废 的 、 瞎 眼 的 、 瘸 腿 的 来 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25576', '42', '14', '22', '仆 人 说 ： ‘ 主 啊 ， 你 所 吩 咐 的 已 经 办 了 ， 还 有 空 座 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25577', '42', '14', '23', '主 人 对 仆 人 说 ： ‘ 你 出 去 到 路 上 和 篱 笆 那 里 ， 勉 强 人 进 来 ， 坐 满 我 的 屋 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25578', '42', '14', '24', '我 告 诉 你 们 ， 先 前 所 请 的 人 没 有 一 个 得 尝 我 的 筵 席 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25579', '42', '14', '25', '＜ 作 门 徒 的 代 价 （ 太   1 0 : 3 7 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25580', '42', '14', '26', '“ 人 到 我 这 里 来 ， 若 不 爱 我 胜 过 爱 ｛ 爱 我 胜 过 爱 ： 原 文 是 恨 ｝ 自 己 的 父 母 、 妻 子 、 儿 女 、 弟 兄 、 姊 妹 ， 和 自 己 的 性 命 ， 就 不 能 作 我 的 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25581', '42', '14', '27', '凡 不 背 着 自 己 十 字 架 跟 从 我 的 ， 也 不 能 作 我 的 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25582', '42', '14', '28', '你 们 哪 一 个 要 盖 一 座 楼 ， 不 先 坐 下 算 计 花 费 ， 能 盖 成 不 能 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25583', '42', '14', '29', '恐 怕 安 了 地 基 ， 不 能 成 功 ， 看 见 的 人 都 笑 话 他 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25584', '42', '14', '30', '‘ 这 个 人 开 了 工 ， 却 不 能 完 工 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25585', '42', '14', '31', '或 是 一 个 王 出 去 和 别 的 王 打 仗 ， 岂 不 先 坐 下 酌 量 ， 能 用 一 万 兵 去 敌 那 领 二 万 兵 来 攻 打 他 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25586', '42', '14', '32', '若 是 不 能 ， 就 趁 敌 人 还 远 的 时 候 ， 派 使 者 去 求 和 息 的 条 款 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25587', '42', '14', '33', '这 样 ， 你 们 无 论 什 么 人 ， 若 不 撇 下 一 切 所 有 的 ， 就 不 能 作 我 的 门 徒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25588', '42', '14', '34', '＜ 失 味 的 盐 （ 太   5 : 1 3 ； 可   9 : 5 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25589', '42', '14', '35', '或 用 在 田 里 ， 或 堆 在 粪 里 ， 都 不 合 适 ， 只 好 丢 在 外 面 。 有 耳 可 听 的 ， 就 应 当 听 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25590', '42', '15', '1', '＜ 迷 羊 的 比 喻 （ 太   1 8 : 1 2 - 1 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25591', '42', '15', '2', '法 利 赛 人 和 文 士 私 下 议 论 说 ： “ 这 个 人 接 待 罪 人 ， 又 同 他 们 吃 饭 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25592', '42', '15', '3', '耶 稣 就 用 比 喻 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25593', '42', '15', '4', '“ 你 们 中 间 谁 有 一 百 只 羊 失 去 一 只 ， 不 把 这 九 十 九 只 撇 在 旷 野 、 去 找 那 失 去 的 羊 ， 直 到 找 着 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25594', '42', '15', '5', '找 着 了 ， 就 欢 欢 喜 喜 地 扛 在 肩 上 ， 回 到 家 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25595', '42', '15', '6', '就 请 朋 友 邻 舍 来 ， 对 他 们 说 ： ‘ 我 失 去 的 羊 已 经 找 着 了 ， 你 们 和 我 一 同 欢 喜 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25596', '42', '15', '7', '我 告 诉 你 们 ， 一 个 罪 人 悔 改 ， 在 天 上 也 要 这 样 为 他 欢 喜 ， 较 比 为 九 十 九 个 不 用 悔 改 的 义 人 欢 喜 更 大 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25597', '42', '15', '8', '＜ 失 钱 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25598', '42', '15', '9', '找 着 了 ， 就 请 朋 友 邻 舍 来 ， 对 他 们 说 ： ‘ 我 失 落 的 那 块 钱 已 经 找 着 了 ， 你 们 和 我 一 同 欢 喜 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25599', '42', '15', '10', '我 告 诉 你 们 ， 一 个 罪 人 悔 改 ， 在 神 的 使 者 面 前 也 是 这 样 为 他 欢 喜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25600', '42', '15', '11', '＜ 浪 子 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25601', '42', '15', '12', '小 儿 子 对 父 亲 说 ： ‘ 父 亲 ， 请 你 把 我 应 得 的 家 业 分 给 我 。 ’ 他 父 亲 就 把 产 业 分 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25602', '42', '15', '13', '过 了 不 多 几 日 ， 小 儿 子 就 把 他 一 切 所 有 的 都 收 拾 起 来 ， 往 远 方 去 了 。 在 那 里 任 意 放 荡 ， 浪 费 资 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25603', '42', '15', '14', '既 耗 尽 了 一 切 所 有 的 ， 又 遇 着 那 地 方 大 遭 饥 荒 ， 就 穷 苦 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25604', '42', '15', '15', '于 是 去 投 靠 那 地 方 的 一 个 人 ； 那 人 打 发 他 到 田 里 去 放 猪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25605', '42', '15', '16', '他 恨 不 得 拿 猪 所 吃 的 豆 荚 充 饥 ， 也 没 有 人 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25606', '42', '15', '17', '他 醒 悟 过 来 ， 就 说 ： ‘ 我 父 亲 有 多 少 的 雇 工 ， 口 粮 有 余 ， 我 倒 在 这 里 饿 死 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25607', '42', '15', '18', '我 要 起 来 ， 到 我 父 亲 那 里 去 ， 向 他 说 ： 父 亲 ！ 我 得 罪 了 天 ， 又 得 罪 了 你 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25608', '42', '15', '19', '从 今 以 后 ， 我 不 配 称 为 你 的 儿 子 ， 把 我 当 作 一 个 雇 工 吧 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25609', '42', '15', '20', '于 是 起 来 ， 往 他 父 亲 那 里 去 。 相 离 还 远 ， 他 父 亲 看 见 ， 就 动 了 慈 心 ， 跑 去 抱 着 他 的 颈 项 ， 连 连 与 他 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25610', '42', '15', '21', '儿 子 说 ： ‘ 父 亲 ！ 我 得 罪 了 天 ， 又 得 罪 了 你 ； 从 今 以 后 ， 我 不 配 称 为 你 的 儿 子 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25611', '42', '15', '22', '父 亲 却 吩 咐 仆 人 说 ： ‘ 把 那 上 好 的 袍 子 快 拿 出 来 给 他 穿 ； 把 戒 指 戴 在 他 指 头 上 ； 把 鞋 穿 在 他 脚 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25612', '42', '15', '23', '把 那 肥 牛 犊 牵 来 宰 了 ， 我 们 可 以 吃 喝 快 乐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25613', '42', '15', '24', '因 为 我 这 个 儿 子 是 死 而 复 活 ， 失 而 又 得 的 。 ’ 他 们 就 快 乐 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25614', '42', '15', '25', '那 时 ， 大 儿 子 正 在 田 里 。 他 回 来 ， 离 家 不 远 ， 听 见 作 乐 跳 舞 的 声 音 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25615', '42', '15', '26', '便 叫 过 一 个 仆 人 来 ， 问 是 什 么 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25616', '42', '15', '27', '仆 人 说 ： ‘ 你 兄 弟 来 了 ； 你 父 亲 因 为 得 他 无 灾 无 病 地 回 来 ， 把 肥 牛 犊 宰 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25617', '42', '15', '28', '大 儿 子 却 生 气 ， 不 肯 进 去 ； 他 父 亲 就 出 来 劝 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25618', '42', '15', '29', '他 对 父 亲 说 ： ‘ 我 服 事 你 这 多 年 ， 从 来 没 有 违 背 过 你 的 命 ， 你 并 没 有 给 我 一 只 山 羊 羔 ， 叫 我 和 朋 友 一 同 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25619', '42', '15', '30', '但 你 这 个 儿 子 和 娼 妓 吞 尽 了 你 的 产 业 ， 他 一 来 了 ， 你 倒 为 他 宰 了 肥 牛 犊 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25620', '42', '15', '31', '父 亲 对 他 说 ： ‘ 儿 啊 ！ 你 常 和 我 同 在 ， 我 一 切 所 有 的 都 是 你 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25621', '42', '15', '32', '只 是 你 这 个 兄 弟 是 死 而 复 活 、 失 而 又 得 的 ， 所 以 我 们 理 当 欢 喜 快 乐 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25622', '42', '16', '1', '＜ 不 义 的 管 家 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25623', '42', '16', '2', '主 人 叫 他 来 ， 对 他 说 ： ‘ 我 听 见 你 这 事 怎 么 样 呢 ？ 把 你 所 经 管 的 交 代 明 白 ， 因 你 不 能 再 作 我 的 管 家 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25624', '42', '16', '3', '那 管 家 心 里 说 ： ‘ 主 人 辞 我 ， 不 用 我 再 作 管 家 ， 我 将 来 做 什 么 ？ 锄 地 呢 ？ 无 力 ； 讨 饭 呢 ？ 怕 羞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25625', '42', '16', '4', '我 知 道 怎 么 行 ， 好 叫 人 在 我 不 作 管 家 之 后 ， 接 我 到 他 们 家 里 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25626', '42', '16', '5', '于 是 把 欠 他 主 人 债 的 ， 一 个 一 个 地 叫 了 来 ， 问 头 一 个 说 ： ‘ 你 欠 我 主 人 多 少 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25627', '42', '16', '6', '他 说 ： ‘ 一 百 篓 ｛ 每 篓 约 五 十 斤 ｝ 油 。 ’ 管 家 说 ： ‘ 拿 你 的 帐 ， 快 坐 下 ， 写 五 十 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25628', '42', '16', '7', '又 问 一 个 说 ： ‘ 你 欠 多 少 ？ ’ 他 说 ： ‘ 一 百 石 麦 子 。 ’ 管 家 说 ： ‘ 拿 你 的 帐 ， 写 八 十 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25629', '42', '16', '8', '主 人 就 夸 奖 这 不 义 的 管 家 做 事 聪 明 ； 因 为 今 世 之 子 ， 在 世 事 之 上 ， 较 比 光 明 之 子 更 加 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25630', '42', '16', '9', '我 又 告 诉 你 们 ， 要 藉 着 那 不 义 的 钱 财 结 交 朋 友 ， 到 了 钱 财 无 用 的 时 候 ， 他 们 可 以 接 你 们 到 永 存 的 帐 幕 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25631', '42', '16', '10', '人 在 最 小 的 事 上 忠 心 ， 在 大 事 上 也 忠 心 ； 在 最 小 的 事 上 不 义 ， 在 大 事 上 也 不 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25632', '42', '16', '11', '倘 若 你 们 在 不 义 的 钱 财 上 不 忠 心 ， 谁 还 把 那 真 实 的 钱 财 托 付 你 们 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25633', '42', '16', '12', '倘 若 你 们 在 别 人 的 东 西 上 不 忠 心 ， 谁 还 把 你 们 自 己 的 东 西 给 你 们 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25634', '42', '16', '13', '一 个 仆 人 不 能 事 奉 两 个 主 ； 不 是 恶 这 个 爱 那 个 ， 就 是 重 这 个 轻 那 个 。 你 们 不 能 又 事 奉 神 ， 又 事 奉 玛 门 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25635', '42', '16', '14', '＜ 律 法 和 神 的 国 （ 太   5 : 3 1 - 3 2 ； 1 1 : 1 2 - 1 3 ； 可   1 0 : 1 1 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25636', '42', '16', '15', '耶 稣 对 他 们 说 ： “ 你 们 是 在 人 面 前 自 称 为 义 的 ， 你 们 的 心 ， 神 却 知 道 ； 因 为 人 所 尊 贵 的 ， 是 神 看 为 可 憎 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25637', '42', '16', '16', '律 法 和 先 知 到 约 翰 为 止 ， 从 此 神 国 的 福 音 传 开 了 ， 人 人 努 力 要 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25638', '42', '16', '17', '天 地 废 去 较 比 律 法 的 一 点 一 画 落 空 还 容 易 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25639', '42', '16', '18', '凡 休 妻 另 娶 的 就 是 犯 奸 淫 ； 娶 被 休 之 妻 的 也 是 犯 奸 淫 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25640', '42', '16', '19', '＜ 财 主 和 拉 撒 路 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25641', '42', '16', '20', '又 有 一 个 讨 饭 的 ， 名 叫 拉 撒 路 ， 浑 身 生 疮 ， 被 人 放 在 财 主 门 口 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25642', '42', '16', '21', '要 得 财 主 桌 子 上 掉 下 来 的 零 碎 充 饥 ； 并 且 狗 来 舔 他 的 疮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25643', '42', '16', '22', '后 来 那 讨 饭 的 死 了 ， 被 天 使 带 去 放 在 亚 伯 拉 罕 的 怀 里 。 财 主 也 死 了 ， 并 且 埋 葬 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25644', '42', '16', '23', '他 在 阴 间 受 痛 苦 ， 举 目 远 远 地 望 见 亚 伯 拉 罕 ， 又 望 见 拉 撒 路 在 他 怀 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25645', '42', '16', '24', '就 喊 着 说 ： ‘ 我 祖 亚 伯 拉 罕 哪 ， 可 怜 我 吧 ！ 打 发 拉 撒 路 来 ， 用 指 头 尖 蘸 点 水 ， 凉 凉 我 的 舌 头 ； 因 为 我 在 这 火 焰 里 ， 极 其 痛 苦 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25646', '42', '16', '25', '亚 伯 拉 罕 说 ： ‘ 儿 啊 ， 你 该 回 想 你 生 前 享 过 福 ， 拉 撒 路 也 受 过 苦 ； 如 今 他 在 这 里 得 安 慰 ， 你 倒 受 痛 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25647', '42', '16', '26', '不 但 这 样 ， 并 且 在 你 我 之 间 ， 有 深 渊 限 定 ， 以 致 人 要 从 这 边 过 到 你 们 那 边 是 不 能 的 ； 要 从 那 边 过 到 我 们 这 边 也 是 不 能 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25648', '42', '16', '27', '财 主 说 ： ‘ 我 祖 啊 ！ 既 是 这 样 ， 求 你 打 发 拉 撒 路 到 我 父 家 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25649', '42', '16', '28', '因 为 我 还 有 五 个 弟 兄 ， 他 可 以 对 他 们 作 见 证 ， 免 得 他 们 也 来 到 这 痛 苦 的 地 方 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25650', '42', '16', '29', '亚 伯 拉 罕 说 ： ‘ 他 们 有 摩 西 和 先 知 的 话 可 以 听 从 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25651', '42', '16', '30', '他 说 ： ‘ 我 祖 亚 伯 拉 罕 哪 ， 不 是 的 ， 若 有 一 个 从 死 里 复 活 的 ， 到 他 们 那 里 去 的 ， 他 们 必 要 悔 改 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25652', '42', '16', '31', '亚 伯 拉 罕 说 ： ‘ 若 不 听 从 摩 西 和 先 知 的 话 ， 就 是 有 一 个 从 死 里 复 活 的 ， 他 们 也 是 不 听 劝 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25653', '42', '17', '1', '＜ 罪 ， 信 心 ， 仆 人 的 本 分 （ 太   1 8 : 6 - 7 , 2 1 - 2 2 ； 可   9 : 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25654', '42', '17', '2', '就 是 把 磨 石 拴 在 这 人 的 颈 项 上 ， 丢 在 海 里 ， 还 强 如 他 把 这 小 子 里 的 一 个 绊 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25655', '42', '17', '3', '你 们 要 谨 慎 ！ 若 是 你 的 弟 兄 得 罪 你 ， 就 劝 戒 他 ； 他 若 懊 悔 ， 就 饶 恕 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25656', '42', '17', '4', '倘 若 他 一 天 七 次 得 罪 你 ， 又 七 次 回 转 ， 说 ： ‘ 我 懊 悔 了 ’ ， 你 总 要 饶 恕 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25657', '42', '17', '5', '使 徒 对 主 说 ： “ 求 主 加 增 我 们 的 信 心 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25658', '42', '17', '6', '主 说 ： “ 你 们 若 有 信 心 像 一 粒 芥 菜 种 ， 就 是 对 这 棵 桑 树 说 ： ‘ 你 要 拔 起 根 来 ， 栽 在 海 里 ’ ， 它 也 必 听 从 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25659', '42', '17', '7', '你 们 谁 有 仆 人 耕 地 或 是 放 羊 ， 从 田 里 回 来 ， 就 对 他 说 ： ‘ 你 快 来 坐 下 吃 饭 ’ 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25660', '42', '17', '8', '岂 不 对 他 说 ： ‘ 你 给 我 预 备 晚 饭 ， 束 上 带 子 伺 候 我 ， 等 我 吃 喝 完 了 ， 你 才 可 以 吃 喝 ’ 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25661', '42', '17', '9', '仆 人 照 所 吩 咐 的 去 做 ， 主 人 还 谢 谢 他 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25662', '42', '17', '10', '这 样 ， 你 们 做 完 了 一 切 所 吩 咐 的 ， 只 当 说 ： ‘ 我 们 是 无 用 的 仆 人 ， 所 做 的 本 是 我 们 应 分 做 的 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25663', '42', '17', '11', '＜ 治 好 十 个 长 大 痲 疯 的 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25664', '42', '17', '12', '进 入 一 个 村 子 ， 有 十 个 长 大 痲 疯 的 ， 迎 面 而 来 ， 远 远 地 站 着 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25665', '42', '17', '13', '高 声 说 ： “ 耶 稣 ， 夫 子 ， 可 怜 我 们 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25666', '42', '17', '14', '耶 稣 看 见 ， 就 对 他 们 说 ： “ 你 们 去 把 身 体 给 祭 司 察 看 。 ” 他 们 去 的 时 候 就 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25667', '42', '17', '15', '内 中 有 一 个 见 自 己 已 经 好 了 ， 就 回 来 大 声 归 荣 耀 与 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25668', '42', '17', '16', '又 俯 伏 在 耶 稣 脚 前 感 谢 他 ； 这 人 是 撒 马 利 亚 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25669', '42', '17', '17', '耶 稣 说 ： “ 洁 净 了 的 不 是 十 个 人 吗 ？ 那 九 个 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25670', '42', '17', '18', '除 了 这 外 族 人 ， 再 没 有 别 人 回 来 归 荣 耀 与 神 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25671', '42', '17', '19', '就 对 那 人 说 ： “ 起 来 ， 走 吧 ！ 你 的 信 救 了 你 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25672', '42', '17', '20', '＜ 神 国 的 来 到 （ 太   2 4 : 2 3 - 2 8 , 3 7 - 4 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25673', '42', '17', '21', '人 也 不 得 说 ： ‘ 看 哪 ， 在 这 里 ！ 看 哪 ， 在 那 里 ！ ’ 因 为 神 的 国 就 在 你 们 心 里 ｛ 心 里 ： 或 译 中 间 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25674', '42', '17', '22', '他 又 对 门 徒 说 ： “ 日 子 将 到 ， 你 们 巴 不 得 看 见 人 子 的 一 个 日 子 ， 却 不 得 看 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25675', '42', '17', '23', '人 将 要 对 你 们 说 ： ‘ 看 哪 ， 在 那 里 ！ 看 哪 ， 在 这 里 ！ ’ 你 们 不 要 出 去 ， 也 不 要 跟 随 他 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25676', '42', '17', '24', '因 为 人 子 在 他 降 临 的 日 子 ， 好 像 闪 电 从 天 这 边 一 闪 直 照 到 天 那 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25677', '42', '17', '25', '只 是 他 必 须 先 受 许 多 苦 ， 又 被 这 世 代 弃 绝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25678', '42', '17', '26', '挪 亚 的 日 子 怎 样 ， 人 子 的 日 子 也 要 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25679', '42', '17', '27', '那 时 候 的 人 又 吃 又 喝 ， 又 娶 又 嫁 ， 到 挪 亚 进 方 舟 的 那 日 ， 洪 水 就 来 ， 把 他 们 全 都 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25680', '42', '17', '28', '又 好 像 罗 得 的 日 子 ； 人 又 吃 又 喝 ， 又 买 又 卖 ， 又 耕 种 又 盖 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25681', '42', '17', '29', '到 罗 得 出 所 多 玛 的 那 日 ， 就 有 火 与 硫 磺 从 天 上 降 下 来 ， 把 他 们 全 都 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25682', '42', '17', '30', '人 子 显 现 的 日 子 也 要 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25683', '42', '17', '31', '当 那 日 ， 人 在 房 上 ， 器 具 在 屋 里 ， 不 要 下 来 拿 ； 人 在 田 里 ， 也 不 要 回 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25684', '42', '17', '32', '你 们 要 回 想 罗 得 的 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25685', '42', '17', '33', '凡 想 要 保 全 生 命 的 ， 必 丧 掉 生 命 ； 凡 丧 掉 生 命 的 ， 必 救 活 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25686', '42', '17', '34', '我 对 你 们 说 ， 当 那 一 夜 ， 两 个 人 在 一 个 床 上 ， 要 取 去 一 个 ， 撇 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25687', '42', '17', '35', '两 个 女 人 一 同 推 磨 ， 要 取 去 一 个 ， 撇 下 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25688', '42', '17', '36', '｛ 有 古 卷 加 ： 两 个 人 在 田 里 ， 要 取 去 一 个 ， 撇 下 一 个 。 ｝ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25689', '42', '17', '37', '门 徒 说 ： “ 主 啊 ， 在 哪 里 有 这 事 呢 ？ ” 耶 稣 说 ： “ 尸 首 在 哪 里 ， 鹰 也 必 聚 在 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25690', '42', '18', '1', '＜ 寡 妇 和 法 官 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25691', '42', '18', '2', '说 ： “ 某 城 里 有 一 个 官 ， 不 惧 怕 神 ， 也 不 尊 重 世 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25692', '42', '18', '3', '那 城 里 有 个 寡 妇 ， 常 到 他 那 里 ， 说 ： ‘ 我 有 一 个 对 头 ， 求 你 给 我 伸 冤 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25693', '42', '18', '4', '他 多 日 不 准 ， 后 来 心 里 说 ： ‘ 我 虽 不 惧 怕 神 ， 也 不 尊 重 世 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25694', '42', '18', '5', '只 因 这 寡 妇 烦 扰 我 ， 我 就 给 她 伸 冤 吧 ， 免 得 她 常 来 缠 磨 我 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25695', '42', '18', '6', '主 说 ： “ 你 们 听 这 不 义 之 官 所 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25696', '42', '18', '7', '神 的 选 民 昼 夜 呼 吁 他 ， 他 纵 然 为 他 们 忍 了 多 时 ， 岂 不 终 久 给 他 们 伸 冤 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25697', '42', '18', '8', '我 告 诉 你 们 ， 要 快 快 地 给 他 们 伸 冤 了 。 然 而 ， 人 子 来 的 时 候 ， 遇 得 见 世 上 有 信 德 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25698', '42', '18', '9', '＜ 法 利 赛 人 和 税 吏 的 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25699', '42', '18', '10', '说 ： “ 有 两 个 人 上 殿 里 去 祷 告 ： 一 个 是 法 利 赛 人 ， 一 个 是 税 吏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25700', '42', '18', '11', '法 利 赛 人 站 着 ， 自 言 自 语 地 祷 告 说 ： ‘ 神 啊 ， 我 感 谢 你 ， 我 不 像 别 人 勒 索 、 不 义 、 奸 淫 ， 也 不 像 这 个 税 吏 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25701', '42', '18', '12', '我 一 个 礼 拜 禁 食 两 次 ， 凡 我 所 得 的 都 捐 上 十 分 之 一 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25702', '42', '18', '13', '那 税 吏 远 远 地 站 着 ， 连 举 目 望 天 也 不 敢 ， 只 捶 着 胸 说 ： ‘ 神 啊 ， 开 恩 可 怜 我 这 个 罪 人 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25703', '42', '18', '14', '我 告 诉 你 们 ， 这 人 回 家 去 比 那 人 倒 算 为 义 了 ； 因 为 ， 凡 自 高 的 ， 必 降 为 卑 ； 自 卑 的 ， 必 升 为 高 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25704', '42', '18', '15', '＜ 耶 稣 为 小 孩 祝 福 （ 太   1 9 : 1 3 - 1 5 ； 可   1 0 : 1 3 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25705', '42', '18', '16', '耶 稣 却 叫 他 们 来 ， 说 ： “ 让 小 孩 子 到 我 这 里 来 ， 不 要 禁 止 他 们 ， 因 为 在 神 国 的 正 是 这 样 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25706', '42', '18', '17', '我 实 在 告 诉 你 们 ， 凡 要 承 受 神 国 的 ， 若 不 像 小 孩 子 ， 断 不 能 进 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25707', '42', '18', '18', '＜ 富 足 的 官 寻 求 永 生 之 道 （ 太   1 9 : 1 6 - 3 0 ； 可   1 0 : 1 7 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25708', '42', '18', '19', '耶 稣 对 他 说 ： “ 你 为 什 么 称 我 是 良 善 的 ？ 除 了 神 一 位 之 外 ， 再 没 有 良 善 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25709', '42', '18', '20', '诫 命 你 是 晓 得 的 ： ‘ 不 可 奸 淫 ； 不 可 杀 人 ； 不 可 偷 盗 ； 不 可 作 假 见 证 ； 当 孝 敬 父 母 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25710', '42', '18', '21', '那 人 说 ： “ 这 一 切 我 从 小 都 遵 守 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25711', '42', '18', '22', '耶 稣 听 见 了 ， 就 说 ： “ 你 还 缺 少 一 件 ： 要 变 卖 你 一 切 所 有 的 ， 分 给 穷 人 ， 就 必 有 财 宝 在 天 上 ； 你 还 要 来 跟 从 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25712', '42', '18', '23', '他 听 见 这 话 ， 就 甚 忧 愁 ， 因 为 他 很 富 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25713', '42', '18', '24', '耶 稣 看 见 他 ， 就 说 ： “ 有 钱 财 的 人 进 神 的 国 是 何 等 的 难 哪 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25714', '42', '18', '25', '骆 驼 穿 过 针 的 眼 比 财 主 进 神 的 国 还 容 易 呢 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25715', '42', '18', '26', '听 见 的 人 说 ： “ 这 样 ， 谁 能 得 救 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25716', '42', '18', '27', '耶 稣 说 ： “ 在 人 所 不 能 的 事 ， 在 神 却 能 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25717', '42', '18', '28', '彼 得 说 ： “ 看 哪 ， 我 们 已 经 撇 下 自 己 所 有 的 跟 从 你 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25718', '42', '18', '29', '耶 稣 说 ： “ 我 实 在 告 诉 你 们 ， 人 为 神 的 国 撇 下 房 屋 ， 或 是 妻 子 、 弟 兄 、 父 母 、 儿 女 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25719', '42', '18', '30', '没 有 在 今 世 不 得 百 倍 ， 在 来 世 不 得 永 生 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25720', '42', '18', '31', '＜ 耶 稣 第 三 次 预 言 受 难 和 复 活 （ 太   2 0 : 1 7 - 1 9 ； 可   1 0 : 3 2 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25721', '42', '18', '32', '他 将 要 被 交 给 外 邦 人 ； 他 们 要 戏 弄 他 ， 凌 辱 他 ， 吐 唾 沫 在 他 脸 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25722', '42', '18', '33', '并 要 鞭 打 他 ， 杀 害 他 ； 第 三 日 他 要 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25723', '42', '18', '34', '这 些 事 门 徒 一 样 也 不 懂 得 ， 意 思 乃 是 隐 藏 的 ； 他 们 不 晓 得 所 说 的 是 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25724', '42', '18', '35', '＜ 治 好 耶 利 哥 的 瞎 子 （ 太   2 0 : 2 9 - 3 4 ； 可   1 0 : 4 6 - 5 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25725', '42', '18', '36', '听 见 许 多 人 经 过 ， 就 问 是 什 么 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25726', '42', '18', '37', '他 们 告 诉 他 ， 是 拿 撒 勒 人 耶 稣 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25727', '42', '18', '38', '他 就 呼 叫 说 ： “ 大 卫 的 子 孙 耶 稣 啊 ， 可 怜 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25728', '42', '18', '39', '在 前 头 走 的 人 就 责 备 他 ， 不 许 他 作 声 ； 他 却 越 发 喊 叫 说 ： “ 大 卫 的 子 孙 ， 可 怜 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25729', '42', '18', '40', '耶 稣 站 住 ， 吩 咐 把 他 领 过 来 ， 到 了 跟 前 ， 就 问 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25730', '42', '18', '41', '“ 你 要 我 为 你 做 什 么 ？ ” 他 说 ： “ 主 啊 ， 我 要 能 看 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25731', '42', '18', '42', '耶 稣 说 ： “ 你 可 以 看 见 ！ 你 的 信 救 了 你 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25732', '42', '18', '43', '瞎 子 立 刻 看 见 了 ， 就 跟 随 耶 稣 ， 一 路 归 荣 耀 与 神 。 众 人 看 见 这 事 ， 也 赞 美 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25733', '42', '19', '1', '＜ 耶 稣 和 撒 该 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25734', '42', '19', '2', '有 一 个 人 名 叫 撒 该 ， 作 税 吏 长 ， 是 个 财 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25735', '42', '19', '3', '他 要 看 看 耶 稣 是 怎 样 的 人 ； 只 因 人 多 ， 他 的 身 量 又 矮 ， 所 以 不 得 看 见 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25736', '42', '19', '4', '就 跑 到 前 头 ， 爬 上 桑 树 ， 要 看 耶 稣 ， 因 为 耶 稣 必 从 那 里 经 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25737', '42', '19', '5', '耶 稣 到 了 那 里 ， 抬 头 一 看 ， 对 他 说 ： “ 撒 该 ， 快 下 来 ！ 今 天 我 必 住 在 你 家 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25738', '42', '19', '6', '他 就 急 忙 下 来 ， 欢 欢 喜 喜 地 接 待 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25739', '42', '19', '7', '众 人 看 见 ， 都 私 下 议 论 说 ： “ 他 竟 到 罪 人 家 里 去 住 宿 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25740', '42', '19', '8', '撒 该 站 着 对 主 说 ： “ 主 啊 ， 我 把 所 有 的 一 半 给 穷 人 ； 我 若 讹 诈 了 谁 ， 就 还 他 四 倍 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25741', '42', '19', '9', '耶 稣 说 ： “ 今 天 救 恩 到 了 这 家 ， 因 为 他 也 是 亚 伯 拉 罕 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25742', '42', '19', '10', '人 子 来 ， 为 要 寻 找 、 拯 救 失 丧 的 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25743', '42', '19', '11', '＜ 十 锭 银 子 的 比 喻 （ 太   2 5 : 1 4 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25744', '42', '19', '12', '“ 有 一 个 贵 胄 往 远 方 去 ， 要 得 国 回 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25745', '42', '19', '13', '便 叫 了 他 的 十 个 仆 人 来 ， 交 给 他 们 十 锭 ｛ 锭 ： 原 文 是 弥 拿 ， 一 弥 拿 约 银 十 两 ｝ 银 子 ， 说 ： ‘ 你 们 去 做 生 意 ， 直 等 我 回 来 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25746', '42', '19', '14', '他 本 国 的 人 却 恨 他 ， 打 发 使 者 随 后 去 ， 说 ： ‘ 我 们 不 愿 意 这 个 人 作 我 们 的 王 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25747', '42', '19', '15', '他 既 得 国 回 来 ， 就 吩 咐 叫 那 领 银 子 的 仆 人 来 ， 要 知 道 他 们 做 生 意 赚 了 多 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25748', '42', '19', '16', '头 一 个 上 来 ， 说 ： ‘ 主 啊 ， 你 的 一 锭 银 子 已 经 赚 了 十 锭 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25749', '42', '19', '17', '主 人 说 ： ‘ 好 ！ 良 善 的 仆 人 ， 你 既 在 最 小 的 事 上 有 忠 心 ， 可 以 有 权 柄 管 十 座 城 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25750', '42', '19', '18', '第 二 个 来 ， 说 ： ‘ 主 啊 ， 你 的 一 锭 银 子 已 经 赚 了 五 锭 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25751', '42', '19', '19', '主 人 说 ： ‘ 你 也 可 以 管 五 座 城 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25752', '42', '19', '20', '又 有 一 个 来 说 ： ‘ 主 啊 ， 看 哪 ， 你 的 一 锭 银 子 在 这 里 ， 我 把 它 包 在 手 巾 里 存 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25753', '42', '19', '21', '我 原 是 怕 你 ， 因 为 你 是 严 厉 的 人 ； 没 有 放 下 的 ， 还 要 去 拿 ， 没 有 种 下 的 ， 还 要 去 收 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25754', '42', '19', '22', '主 人 对 他 说 ： ‘ 你 这 恶 仆 ， 我 要 凭 你 的 口 定 你 的 罪 。 你 既 知 道 我 是 严 厉 的 人 ， 没 有 放 下 的 ， 还 要 去 拿 ， 没 有 种 下 的 ， 还 要 去 收 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25755', '42', '19', '23', '为 什 么 不 把 我 的 银 子 交 给 银 行 ， 等 我 来 的 时 候 ， 连 本 带 利 都 可 以 要 回 来 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25756', '42', '19', '24', '就 对 旁 边 站 着 的 人 说 ： ‘ 夺 过 他 这 一 锭 来 ， 给 那 有 十 锭 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25757', '42', '19', '25', '他 们 说 ： ‘ 主 啊 ， 他 已 经 有 十 锭 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25758', '42', '19', '26', '主 人 说 ： ‘ 我 告 诉 你 们 ， 凡 有 的 ， 还 要 加 给 他 ； 没 有 的 ， 连 他 所 有 的 也 要 夺 过 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25759', '42', '19', '27', '至 于 我 那 些 仇 敌 ， 不 要 我 作 他 们 王 的 ， 把 他 们 拉 来 ， 在 我 面 前 杀 了 吧 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25760', '42', '19', '28', '＜ 光 荣 地 进 耶 路 撒 冷 （ 太   2 1 : 1 - 1 1 ； 可   1 1 : 1 - 1 1 ； 约   1 2 : 1 2 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25761', '42', '19', '29', '将 近 伯 法 其 和 伯 大 尼 ， 在 一 座 山 名 叫 橄 榄 山 那 里 ， 就 打 发 两 个 门 徒 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25762', '42', '19', '30', '“ 你 们 往 对 面 村 子 里 去 ， 进 去 的 时 候 ， 必 看 见 一 匹 驴 驹 拴 在 那 里 ， 是 从 来 没 有 人 骑 过 的 ， 可 以 解 开 牵 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25763', '42', '19', '31', '若 有 人 问 为 什 么 解 它 ， 你 们 就 说 ： ‘ 主 要 用 它 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25764', '42', '19', '32', '打 发 的 人 去 了 ， 所 遇 见 的 正 如 耶 稣 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25765', '42', '19', '33', '他 们 解 驴 驹 的 时 候 ， 主 人 问 他 们 说 ： “ 解 驴 驹 做 什 么 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25766', '42', '19', '34', '他 们 说 ： “ 主 要 用 它 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25767', '42', '19', '35', '他 们 牵 到 耶 稣 那 里 ， 把 自 己 的 衣 服 搭 在 上 面 ， 扶 着 耶 稣 骑 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25768', '42', '19', '36', '走 的 时 候 ， 众 人 把 衣 服 铺 在 路 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25769', '42', '19', '37', '将 近 耶 路 撒 冷 ， 正 下 橄 榄 山 的 时 候 ， 众 门 徒 因 所 见 过 的 一 切 异 能 ， 都 欢 乐 起 来 ， 大 声 赞 美 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25770', '42', '19', '38', '说 ： 奉 主 名 来 的 王 是 应 当 称 颂 的 ！ 在 天 上 有 和 平 ； 在 至 高 之 处 有 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25771', '42', '19', '39', '众 人 中 有 几 个 法 利 赛 人 对 耶 稣 说 ： “ 夫 子 ， 责 备 你 的 门 徒 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25772', '42', '19', '40', '耶 稣 说 ： “ 我 告 诉 你 们 ， 若 是 他 们 闭 口 不 说 ， 这 些 石 头 必 要 呼 叫 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25773', '42', '19', '41', '耶 稣 快 到 耶 路 撒 冷 ， 看 见 城 ， 就 为 它 哀 哭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25774', '42', '19', '42', '说 ： “ 巴 不 得 你 在 这 日 子 知 道 关 系 你 平 安 的 事 ； 无 奈 这 事 现 在 是 隐 藏 的 ， 叫 你 的 眼 看 不 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25775', '42', '19', '43', '因 为 日 子 将 到 ， 你 的 仇 敌 必 筑 起 土 垒 ， 周 围 环 绕 你 ， 四 面 困 住 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25776', '42', '19', '44', '并 要 扫 灭 你 和 你 里 头 的 儿 女 ， 连 一 块 石 头 也 不 留 在 石 头 上 ， 因 你 不 知 道 眷 顾 你 的 时 候 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25777', '42', '19', '45', '＜ 洁 净 圣 殿 （ 太   2 1 : 1 2 - 1 7 ； 可   1 1 : 1 5 - 1 9 ； 约   2 : 1 3 - 2 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25778', '42', '19', '46', '对 他 们 说 ： “ 经 上 说 ： 我 的 殿 必 作 祷 告 的 殿 ， 你 们 倒 使 它 成 为 贼 窝 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25779', '42', '19', '47', '耶 稣 天 天 在 殿 里 教 训 人 。 祭 司 长 和 文 士 与 百 姓 的 尊 长 都 想 要 杀 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25780', '42', '19', '48', '但 寻 不 出 法 子 来 ， 因 为 百 姓 都 侧 耳 听 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25781', '42', '20', '1', '＜ 质 问 耶 稣 的 权 柄 （ 太   2 1 : 2 3 - 2 7 ； 可   1 1 : 2 7 - 3 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25782', '42', '20', '2', '问 他 说 ： “ 你 告 诉 我 们 ， 你 仗 着 什 么 权 柄 做 这 些 事 ？ 给 你 这 权 柄 的 是 谁 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25783', '42', '20', '3', '耶 稣 回 答 说 ： “ 我 也 要 问 你 们 一 句 话 ， 你 们 且 告 诉 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25784', '42', '20', '4', '约 翰 的 洗 礼 是 从 天 上 来 的 ？ 是 从 人 间 来 的 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25785', '42', '20', '5', '他 们 彼 此 商 议 说 ： “ 我 们 若 说 ‘ 从 天 上 来 ’ ， 他 必 说 ： ‘ 你 们 为 什 么 不 信 他 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25786', '42', '20', '6', '若 说 ‘ 从 人 间 来 ’ ， 百 姓 都 要 用 石 头 打 死 我 们 ， 因 为 他 们 信 约 翰 是 先 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25787', '42', '20', '7', '于 是 回 答 说 ： “ 不 知 道 是 从 哪 里 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25788', '42', '20', '8', '耶 稣 说 ： “ 我 也 不 告 诉 你 们 ， 我 仗 着 什 么 权 柄 做 这 些 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25789', '42', '20', '9', '＜ 凶 恶 园 户 的 比 喻 （ 太   2 1 : 3 3 - 4 6 ； 可   1 2 : 1 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25790', '42', '20', '10', '到 了 时 候 ， 打 发 一 个 仆 人 到 园 户 那 里 去 ， 叫 他 们 把 园 中 当 纳 的 果 子 交 给 他 ； 园 户 竟 打 了 他 ， 叫 他 空 手 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25791', '42', '20', '11', '又 打 发 一 个 仆 人 去 ， 他 们 也 打 了 他 ， 并 且 凌 辱 他 ， 叫 他 空 手 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25792', '42', '20', '12', '又 打 发 第 三 个 仆 人 去 ， 他 们 也 打 伤 了 他 ， 把 他 推 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25793', '42', '20', '13', '园 主 说 ： ‘ 我 怎 么 办 呢 ？ 我 要 打 发 我 的 爱 子 去 ， 或 者 他 们 尊 敬 他 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25794', '42', '20', '14', '不 料 ， 园 户 看 见 他 ， 就 彼 此 商 量 说 ： ‘ 这 是 承 受 产 业 的 ， 我 们 杀 他 吧 ， 使 产 业 归 于 我 们 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25795', '42', '20', '15', '于 是 把 他 推 出 葡 萄 园 外 ， 杀 了 。 这 样 ， 葡 萄 园 的 主 人 要 怎 样 处 治 他 们 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25796', '42', '20', '16', '他 要 来 除 灭 这 些 园 户 ， 将 葡 萄 园 转 给 别 人 。 ” 听 见 的 人 说 ： “ 这 是 万 不 可 的 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25797', '42', '20', '17', '耶 稣 看 着 他 们 说 ： “ 经 上 记 着 ： 匠 人 所 弃 的 石 头 已 作 了 房 角 的 头 块 石 头 。 这 是 什 么 意 思 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25798', '42', '20', '18', '凡 掉 在 那 石 头 上 的 ， 必 要 跌 碎 ； 那 石 头 掉 在 谁 的 身 上 ， 就 要 把 谁 砸 得 稀 烂 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25799', '42', '20', '19', '＜ 纳 税 给 该 撒 的 问 题 （ 太   2 2 : 1 5 - 2 2 ； 可   1 2 : 1 3 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25800', '42', '20', '20', '于 是 窥 探 耶 稣 ， 打 发 奸 细 装 作 好 人 ， 要 在 他 的 话 上 得 把 柄 ， 好 将 他 交 在 巡 抚 的 政 权 之 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25801', '42', '20', '21', '奸 细 就 问 耶 稣 说 ： “ 夫 子 ， 我 们 晓 得 你 所 讲 所 传 都 是 正 道 ， 也 不 取 人 的 外 貌 ， 乃 是 诚 诚 实 实 传 神 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25802', '42', '20', '22', '我 们 纳 税 给 凯 撒 ， 可 以 不 可 以 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25803', '42', '20', '23', '耶 稣 看 出 他 们 的 诡 诈 ， 就 对 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25804', '42', '20', '24', '“ 拿 一 个 银 钱 来 给 我 看 。 这 像 和 这 号 是 谁 的 ？ ” 他 们 说 ： “ 是 凯 撒 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25805', '42', '20', '25', '耶 稣 说 ： “ 这 样 ， 凯 撒 的 物 当 归 给 凯 撒 ， 神 的 物 当 归 给 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25806', '42', '20', '26', '他 们 当 着 百 姓 ， 在 这 话 上 得 不 着 把 柄 ， 又 希 奇 他 的 应 对 ， 就 闭 口 无 言 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25807', '42', '20', '27', '＜ 复 活 的 问 题 （ 太   2 2 : 2 3 - 3 3 ； 可   1 2 : 1 8 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25808', '42', '20', '28', '“ 夫 子 ！ 摩 西 为 我 们 写 着 说 ： ‘ 人 若 有 妻 无 子 就 死 了 ， 他 兄 弟 当 娶 他 的 妻 ， 为 哥 哥 生 子 立 后 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25809', '42', '20', '29', '有 弟 兄 七 人 ， 第 一 个 娶 了 妻 ， 没 有 孩 子 死 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25810', '42', '20', '30', '第 二 个 、 第 三 个 也 娶 过 她 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25811', '42', '20', '31', '那 七 个 人 都 娶 过 她 ， 没 有 留 下 孩 子 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25812', '42', '20', '32', '后 来 妇 人 也 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25813', '42', '20', '33', '这 样 ， 当 复 活 的 时 候 ， 她 是 哪 一 个 的 妻 子 呢 ？ 因 为 他 们 七 个 人 都 娶 过 她 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25814', '42', '20', '34', '耶 稣 说 ： “ 这 世 界 的 人 有 娶 有 嫁 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25815', '42', '20', '35', '惟 有 算 为 配 得 那 世 界 ， 与 从 死 里 复 活 的 人 也 不 娶 也 不 嫁 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25816', '42', '20', '36', '因 为 他 们 不 能 再 死 ， 和 天 使 一 样 ； 既 是 复 活 的 人 ， 就 为 神 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25817', '42', '20', '37', '至 于 死 人 复 活 ， 摩 西 在 荆 棘 篇 上 ， 称 主 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 ， 就 指 示 明 白 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25818', '42', '20', '38', '神 原 不 是 死 人 的 神 ， 乃 是 活 人 的 神 ； 因 为 在 他 那 里 ｛ 那 里 ： 或 译 看 来 ｝ ， 人 都 是 活 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25819', '42', '20', '39', '有 几 个 文 士 说 ： “ 夫 子 ！ 你 说 得 好 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25820', '42', '20', '40', '以 后 他 们 不 敢 再 问 他 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25821', '42', '20', '41', '＜ 大 卫 子 孙 的 问 题 （ 太   2 2 : 4 1 - 4 6 ； 可   1 2 : 3 5 - 3 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25822', '42', '20', '42', '诗 篇 上 大 卫 自 己 说 ： 主 对 我 主 说 ： 你 坐 在 我 的 右 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25823', '42', '20', '43', '等 我 使 你 仇 敌 作 你 的 脚 凳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25824', '42', '20', '44', '大 卫 既 称 他 为 主 ， 他 怎 么 又 是 大 卫 的 子 孙 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25825', '42', '20', '45', '＜ 谴 责 文 士 （ 太   2 3 : 1 - 3 6 ； 可   1 2 : 3 8 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25826', '42', '20', '46', '“ 你 们 要 防 备 文 士 。 他 们 好 穿 长 衣 游 行 ， 喜 爱 人 在 街 市 上 问 他 们 安 ， 又 喜 爱 会 堂 里 的 高 位 ， 筵 席 上 的 首 座 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25827', '42', '20', '47', '他 们 侵 吞 寡 妇 的 家 产 ， 假 意 作 很 长 的 祷 告 。 这 些 人 要 受 更 重 的 刑 罚 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25828', '42', '21', '1', '＜ 寡 妇 的 奉 献 （ 可   1 2 : 4 1 - 4 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25829', '42', '21', '2', '又 见 一 个 穷 寡 妇 投 了 两 个 小 钱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25830', '42', '21', '3', '就 说 ： “ 我 实 在 告 诉 你 们 ， 这 穷 寡 妇 所 投 的 比 众 人 还 多 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25831', '42', '21', '4', '因 为 众 人 都 是 自 己 有 余 ， 拿 出 来 投 在 捐 项 里 ， 但 这 寡 妇 是 自 己 不 足 ， 把 她 一 切 养 生 的 都 投 上 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25832', '42', '21', '5', '＜ 预 言 圣 殿 被 毁 （ 太   2 4 : 1 - 2 ； 可   1 3 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25833', '42', '21', '6', '耶 稣 就 说 ： “ 论 到 你 们 所 看 见 的 这 一 切 ， 将 来 日 子 到 了 ， 在 这 里 没 有 一 块 石 头 留 在 石 头 上 ， 不 被 拆 毁 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25834', '42', '21', '7', '＜ 预 兆 和 逼 迫 （ 太   2 4 : 3 - 1 4 ； 可   1 3 : 3 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25835', '42', '21', '8', '耶 稣 说 ： “ 你 们 要 谨 慎 ， 不 要 受 迷 惑 ； 因 为 将 来 有 好 些 人 冒 我 的 名 来 ， 说 ： ‘ 我 是 基 督 ’ ， 又 说 ： ‘ 时 候 近 了 ’ ， 你 们 不 要 跟 从 他 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25836', '42', '21', '9', '你 们 听 见 打 仗 和 扰 乱 的 事 ， 不 要 惊 惶 ； 因 为 这 些 事 必 须 先 有 ， 只 是 末 期 不 能 立 时 就 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25837', '42', '21', '10', '当 时 ， 耶 稣 对 他 们 说 ： “ 民 要 攻 打 民 ， 国 要 攻 打 国 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25838', '42', '21', '11', '地 要 大 大 震 动 ， 多 处 必 有 饥 荒 、 瘟 疫 ， 又 有 可 怕 的 异 象 和 大 神 迹 从 天 上 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25839', '42', '21', '12', '但 这 一 切 的 事 以 先 ， 人 要 下 手 拿 住 你 们 ， 逼 迫 你 们 ， 把 你 们 交 给 会 堂 ， 并 且 收 在 监 里 ， 又 为 我 的 名 拉 你 们 到 君 王 诸 侯 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25840', '42', '21', '13', '但 这 些 事 终 必 为 你 们 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25841', '42', '21', '14', '所 以 ， 你 们 当 立 定 心 意 ， 不 要 预 先 思 想 怎 样 分 诉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25842', '42', '21', '15', '因 为 我 必 赐 你 们 口 才 、 智 慧 ， 是 你 们 一 切 敌 人 所 敌 不 住 、 驳 不 倒 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25843', '42', '21', '16', '连 你 们 的 父 母 、 弟 兄 、 亲 族 、 朋 友 也 要 把 你 们 交 官 ； 你 们 也 有 被 他 们 害 死 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25844', '42', '21', '17', '你 们 要 为 我 的 名 被 众 人 恨 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25845', '42', '21', '18', '然 而 ， 你 们 连 一 根 头 发 也 必 不 损 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25846', '42', '21', '19', '你 们 常 存 忍 耐 ， 就 必 保 全 灵 魂 ｛ 或 译 ： 必 得 生 命 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25847', '42', '21', '20', '＜ 预 言 耶 路 撒 冷 被 毁 （ 太   2 4 : 1 5 - 2 1 ； 可   1 3 : 1 4 - 1 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25848', '42', '21', '21', '那 时 ， 在 犹 太 的 应 当 逃 到 山 上 ； 在 城 里 的 应 当 出 来 ； 在 乡 下 的 不 要 进 城 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25849', '42', '21', '22', '因 为 这 是 报 应 的 日 子 ， 使 经 上 所 写 的 都 得 应 验 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25850', '42', '21', '23', '当 那 些 日 子 ， 怀 孕 的 和 奶 孩 子 的 有 祸 了 ！ 因 为 将 有 大 灾 难 降 在 这 地 方 ， 也 有 震 怒 临 到 这 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25851', '42', '21', '24', '他 们 要 倒 在 刀 下 ， 又 被 掳 到 各 国 去 。 耶 路 撒 冷 要 被 外 邦 人 践 踏 ， 直 到 外 邦 人 的 日 期 满 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25852', '42', '21', '25', '＜ 人 子 的 降 临 （ 太   2 4 : 2 9 - 3 1 ； 可   1 3 : 2 4 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25853', '42', '21', '26', '天 势 都 要 震 动 ， 人 想 起 那 将 要 临 到 世 界 的 事 ， 就 都 吓 得 魂 不 附 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25854', '42', '21', '27', '那 时 ， 他 们 要 看 见 人 子 有 能 力 ， 有 大 荣 耀 驾 云 降 临 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25855', '42', '21', '28', '一 有 这 些 事 ， 你 们 就 当 挺 身 昂 首 ， 因 为 你 们 得 赎 的 日 子 近 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25856', '42', '21', '29', '＜ 从 无 花 果 树 学 功 课 （ 太   2 4 : 3 2 - 3 5 ； 可   1 3 : 2 8 - 3 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25857', '42', '21', '30', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25858', '42', '21', '31', '这 样 ， 你 们 看 见 这 些 事 渐 渐 地 成 就 ， 也 该 晓 得 神 的 国 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25859', '42', '21', '32', '我 实 在 告 诉 你 们 ， 这 世 代 还 没 有 过 去 ， 这 些 事 都 要 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25860', '42', '21', '33', '天 地 要 废 去 ， 我 的 话 却 不 能 废 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25861', '42', '21', '34', '＜ 劝 告 门 徒 警 醒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25862', '42', '21', '35', '因 为 那 日 子 要 这 样 临 到 全 地 上 一 切 居 住 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25863', '42', '21', '36', '你 们 要 时 时 警 醒 ， 常 常 祈 求 ， 使 你 们 能 逃 避 这 一 切 要 来 的 事 ， 得 以 站 立 在 人 子 面 前 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25864', '42', '21', '37', '耶 稣 每 日 在 殿 里 教 训 人 ， 每 夜 出 城 在 一 座 山 ， 名 叫 橄 榄 山 住 宿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25865', '42', '21', '38', '众 百 姓 清 早 上 圣 殿 ， 到 耶 稣 那 里 ， 要 听 他 讲 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25866', '42', '22', '1', '＜ 杀 害 耶 稣 的 阴 谋 （ 太   2 6 : 1 - 5 ； 可   1 4 : 1 - 2 ； 约   1 1 : 4 5 - 5 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25867', '42', '22', '2', '祭 司 长 和 文 士 想 法 子 怎 么 才 能 杀 害 耶 稣 ， 是 因 他 们 惧 怕 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25868', '42', '22', '3', '这 时 ， 撒 但 入 了 那 称 为 加 略 人 犹 大 的 心 ； 他 本 是 十 二 门 徒 里 的 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25869', '42', '22', '4', '他 去 和 祭 司 长 并 守 殿 官 商 量 ， 怎 么 可 以 把 耶 稣 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25870', '42', '22', '5', '他 们 欢 喜 ， 就 约 定 给 他 银 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25871', '42', '22', '6', '他 应 允 了 ， 就 找 机 会 ， 要 趁 众 人 不 在 跟 前 的 时 候 把 耶 稣 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25872', '42', '22', '7', '＜ 预 备 逾 越 节 的 筵 席 （ 太   2 6 : 1 7 - 2 5 ； 可   1 4 : 1 2 - 2 1 ； 约   1 3 : 2 1 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25873', '42', '22', '8', '耶 稣 打 发 彼 得 、 约 翰 ， 说 ： “ 你 们 去 为 我 们 预 备 逾 越 节 的 筵 席 ， 好 叫 我 们 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25874', '42', '22', '9', '他 们 问 他 说 ： “ 要 我 们 在 哪 里 预 备 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25875', '42', '22', '10', '耶 稣 说 ： “ 你 们 进 了 城 ， 必 有 人 拿 着 一 瓶 水 迎 面 而 来 ， 你 们 就 跟 着 他 ， 到 他 所 进 的 房 子 里 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25876', '42', '22', '11', '对 那 家 的 主 人 说 ： ‘ 夫 子 说 ： 客 房 在 哪 里 ？ 我 与 门 徒 好 在 那 里 吃 逾 越 节 的 筵 席 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25877', '42', '22', '12', '他 必 指 给 你 们 摆 设 整 齐 的 一 间 大 楼 ， 你 们 就 在 那 里 预 备 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25878', '42', '22', '13', '他 们 去 了 ， 所 遇 见 的 正 如 耶 稣 所 说 的 ； 他 们 就 预 备 了 逾 越 节 的 筵 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25879', '42', '22', '14', '＜ 设 立 主 的 晚 餐 （ 太   2 6 : 2 6 - 3 0 ； 可   1 4 : 2 2 - 2 6 ； 林 前   1 1 : 2 3 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25880', '42', '22', '15', '耶 稣 对 他 们 说 ： “ 我 很 愿 意 在 受 害 以 先 和 你 们 吃 这 逾 越 节 的 筵 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25881', '42', '22', '16', '我 告 诉 你 们 ， 我 不 再 吃 这 筵 席 ， 直 到 成 就 在 神 的 国 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25882', '42', '22', '17', '耶 稣 接 过 杯 来 ， 祝 谢 了 ， 说 ： “ 你 们 拿 这 个 ， 大 家 分 着 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25883', '42', '22', '18', '我 告 诉 你 们 ， 从 今 以 后 ， 我 不 再 喝 这 葡 萄 汁 ， 直 等 神 的 国 来 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25884', '42', '22', '19', '又 拿 起 饼 来 ， 祝 谢 了 ， 就 擘 开 ， 递 给 他 们 ， 说 ： “ 这 是 我 的 身 体 ， 为 你 们 舍 的 ， 你 们 也 应 当 如 此 行 ， 为 的 是 记 念 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25885', '42', '22', '20', '饭 后 也 照 样 拿 起 杯 来 ， 说 ： “ 这 杯 是 用 我 血 所 立 的 新 约 ， 是 为 你 们 流 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25886', '42', '22', '21', '看 哪 ， 那 卖 我 之 人 的 手 与 我 一 同 在 桌 子 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25887', '42', '22', '22', '人 子 固 然 要 照 所 预 定 的 去 世 ， 但 卖 人 子 的 人 有 祸 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25888', '42', '22', '23', '他 们 就 彼 此 对 问 ， 是 哪 一 个 要 做 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25889', '42', '22', '24', '＜ 争 论 谁 为 大 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25890', '42', '22', '25', '耶 稣 说 ： “ 外 邦 人 有 君 王 为 主 治 理 他 们 ， 那 掌 权 管 他 们 的 称 为 恩 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25891', '42', '22', '26', '但 你 们 不 可 这 样 ； 你 们 里 头 为 大 的 ， 倒 要 像 年 幼 的 ， 为 首 领 的 ， 倒 要 像 服 事 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25892', '42', '22', '27', '是 谁 为 大 ？ 是 坐 席 的 呢 ？ 是 服 事 人 的 呢 ？ 不 是 坐 席 的 大 吗 ？ 然 而 ， 我 在 你 们 中 间 如 同 服 事 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25893', '42', '22', '28', '我 在 磨 炼 之 中 ， 常 和 我 同 在 的 就 是 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25894', '42', '22', '29', '我 将 国 赐 给 你 们 ， 正 如 我 父 赐 给 我 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25895', '42', '22', '30', '叫 你 们 在 我 国 里 ， 坐 在 我 的 席 上 吃 喝 ， 并 且 坐 在 宝 座 上 ， 审 判 以 色 列 十 二 个 支 派 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25896', '42', '22', '31', '＜ 预 言 彼 得 不 认 主 （ 太   2 6 : 3 1 - 3 5 ； 可   1 4 : 2 7 - 3 1 ； 约   1 3 : 3 6 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25897', '42', '22', '32', '但 我 已 经 为 你 祈 求 ， 叫 你 不 至 于 失 了 信 心 。 你 回 头 以 后 ， 要 坚 固 你 的 弟 兄 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25898', '42', '22', '33', '彼 得 说 ： “ 主 啊 ， 我 就 是 同 你 下 监 ， 同 你 受 死 ， 也 是 甘 心 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25899', '42', '22', '34', '耶 稣 说 ： “ 彼 得 ， 我 告 诉 你 ， 今 日 鸡 还 没 有 叫 ， 你 要 三 次 说 不 认 得 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25900', '42', '22', '35', '＜ 钱 囊 、 口 袋 、 刀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25901', '42', '22', '36', '耶 稣 说 ： “ 但 如 今 有 钱 囊 的 可 以 带 着 ， 有 口 袋 的 也 可 以 带 着 ， 没 有 刀 的 要 卖 衣 服 买 刀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25902', '42', '22', '37', '我 告 诉 你 们 ， 经 上 写 着 说 ： ‘ 他 被 列 在 罪 犯 之 中 。 ’ 这 话 必 应 验 在 我 身 上 ； 因 为 那 关 系 我 的 事 必 然 成 就 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25903', '42', '22', '38', '他 们 说 ： “ 主 啊 ， 请 看 ！ 这 里 有 两 把 刀 。 ” 耶 稣 说 ： “ 够 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25904', '42', '22', '39', '＜ 在 橄 榄 山 上 祷 告 （ 太   2 6 : 3 6 - 4 6 ； 可   1 4 : 3 2 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25905', '42', '22', '40', '到 了 那 地 方 ， 就 对 他 们 说 ： “ 你 们 要 祷 告 ， 免 得 入 了 迷 惑 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25906', '42', '22', '41', '于 是 离 开 他 们 约 有 扔 一 块 石 头 那 么 远 ， 跪 下 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25907', '42', '22', '42', '说 ： “ 父 啊 ！ 你 若 愿 意 ， 就 把 这 杯 撤 去 ； 然 而 ， 不 要 成 就 我 的 意 思 ， 只 要 成 就 你 的 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25908', '42', '22', '43', '有 一 位 天 使 从 天 上 显 现 ， 加 添 他 的 力 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25909', '42', '22', '44', '耶 稣 极 其 伤 痛 ， 祷 告 更 加 恳 切 ， 汗 珠 如 大 血 点 滴 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25910', '42', '22', '45', '祷 告 完 了 ， 就 起 来 ， 到 门 徒 那 里 ， 见 他 们 因 为 忧 愁 都 睡 着 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25911', '42', '22', '46', '就 对 他 们 说 ： “ 你 们 为 什 么 睡 觉 呢 ？ 起 来 祷 告 ， 免 得 入 了 迷 惑 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25912', '42', '22', '47', '＜ 耶 稣 被 捕 （ 太   2 6 : 4 7 - 5 6 ； 可   1 4 : 4 3 - 5 0 ； 约   1 8 : 3 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25913', '42', '22', '48', '耶 稣 对 他 说 ： “ 犹 大 ！ 你 用 亲 嘴 的 暗 号 卖 人 子 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25914', '42', '22', '49', '左 右 的 人 见 光 景 不 好 ， 就 说 ： “ 主 啊 ！ 我 们 拿 刀 砍 可 以 不 可 以 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25915', '42', '22', '50', '内 中 有 一 个 人 把 大 祭 司 的 仆 人 砍 了 一 刀 ， 削 掉 了 他 的 右 耳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25916', '42', '22', '51', '耶 稣 说 ： “ 到 了 这 个 地 步 ， 由 他 们 吧 ！ ” 就 摸 那 人 的 耳 朵 ， 把 他 治 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25917', '42', '22', '52', '耶 稣 对 那 些 来 拿 他 的 祭 司 长 和 守 殿 官 并 长 老 说 ： “ 你 们 带 着 刀 棒 出 来 拿 我 ， 如 同 拿 强 盗 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25918', '42', '22', '53', '我 天 天 同 你 们 在 殿 里 ， 你 们 不 下 手 拿 我 。 现 在 却 是 你 们 的 时 候 ， 黑 暗 掌 权 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25919', '42', '22', '54', '＜ 彼 得 三 次 不 认 主 （ 太   2 6 : 5 7 - 5 8 , 6 9 - 7 5 ； 可   1 4 : 5 3 - 5 4 , 6 6 - 7 2 ； 约   1 8 : 1 2 - 1 8 , 2 5 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25920', '42', '22', '55', '他 们 在 院 子 里 生 了 火 ， 一 同 坐 着 ； 彼 得 也 坐 在 他 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25921', '42', '22', '56', '有 一 个 使 女 看 见 彼 得 坐 在 火 光 里 ， 就 定 睛 看 他 ， 说 ： “ 这 个 人 素 来 也 是 同 那 人 一 伙 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25922', '42', '22', '57', '彼 得 却 不 承 认 ， 说 ： “ 女 子 ， 我 不 认 得 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25923', '42', '22', '58', '过 了 不 多 的 时 候 ， 又 有 一 个 人 看 见 他 ， 说 ： “ 你 也 是 他 们 一 党 的 。 ” 彼 得 说 ： “ 你 这 个 人 ！ 我 不 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25924', '42', '22', '59', '约 过 了 一 小 时 ， 又 有 一 个 人 极 力 地 说 ： “ 他 实 在 是 同 那 人 一 伙 的 ， 因 为 他 也 是 加 利 利 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25925', '42', '22', '60', '彼 得 说 ： “ 你 这 个 人 ！ 我 不 晓 得 你 说 的 是 什 么 ！ ” 正 说 话 之 间 ， 鸡 就 叫 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25926', '42', '22', '61', '主 转 过 身 来 看 彼 得 ， 彼 得 便 想 起 主 对 他 所 说 的 话 ： “ 今 日 鸡 叫 以 先 ， 你 要 三 次 不 认 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25927', '42', '22', '62', '他 就 出 去 痛 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25928', '42', '22', '63', '＜ 戏 弄 鞭 打 耶 稣 （ 太   2 6 : 6 7 - 6 8 ； 可   1 4 : 6 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25929', '42', '22', '64', '又 蒙 着 他 的 眼 ， 问 他 说 ： “ 你 是 先 知 ， 告 诉 我 们 打 你 的 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25930', '42', '22', '65', '他 们 还 用 许 多 别 的 话 辱 骂 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25931', '42', '22', '66', '＜ 耶 稣 在 公 会 里 受 审 （ 太   2 6 : 5 9 - 6 6 ； 可   1 4 : 5 5 - 6 4 ； 约   1 8 : 1 9 - 2 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25932', '42', '22', '67', '说 ： “ 你 若 是 基 督 ， 就 告 诉 我 们 。 ” 耶 稣 说 ： “ 我 若 告 诉 你 们 ， 你 们 也 不 信 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25933', '42', '22', '68', '我 若 问 你 们 ， 你 们 也 不 回 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25934', '42', '22', '69', '从 今 以 后 ， 人 子 要 坐 在 神 权 能 的 右 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25935', '42', '22', '70', '他 们 都 说 ： “ 这 样 ， 你 是 神 的 儿 子 吗 ？ ” 耶 稣 说 ： “ 你 们 所 说 的 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25936', '42', '22', '71', '他 们 说 ： “ 何 必 再 用 见 证 呢 ？ 他 亲 口 所 说 的 ， 我 们 都 亲 自 听 见 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25937', '42', '23', '1', '＜ 耶 稣 在 彼 拉 多 面 前 受 审 （ 太   2 7 : 1 - 2 , 1 1 - 1 4 ； 可   1 5 : 1 - 5 ； 约   1 8 : 2 8 - 3 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25938', '42', '23', '2', '就 告 他 说 ： “ 我 们 见 这 人 诱 惑 国 民 ， 禁 止 纳 税 给 凯 撒 ， 并 说 自 己 是 基 督 ， 是 王 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25939', '42', '23', '3', '彼 拉 多 问 耶 稣 说 ： “ 你 是 犹 太 人 的 王 吗 ？ ” 耶 稣 回 答 说 ： “ 你 说 的 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25940', '42', '23', '4', '彼 拉 多 对 祭 司 长 和 众 人 说 ： “ 我 查 不 出 这 人 有 什 么 罪 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25941', '42', '23', '5', '但 他 们 越 发 极 力 地 说 ： “ 他 煽 惑 百 姓 ， 在 犹 太 遍 地 传 道 ， 从 加 利 利 起 ， 直 到 这 里 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25942', '42', '23', '6', '＜ 希 律 藐 视 耶 稣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25943', '42', '23', '7', '既 晓 得 耶 稣 属 希 律 所 管 ， 就 把 他 送 到 希 律 那 里 去 。 那 时 希 律 正 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25944', '42', '23', '8', '希 律 看 见 耶 稣 ， 就 很 欢 喜 ； 因 为 听 见 过 他 的 事 ， 久 已 想 要 见 他 ， 并 且 指 望 看 他 行 一 件 神 迹 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25945', '42', '23', '9', '于 是 问 他 许 多 的 话 ， 耶 稣 却 一 言 不 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25946', '42', '23', '10', '祭 司 长 和 文 士 都 站 着 ， 极 力 地 告 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25947', '42', '23', '11', '希 律 和 他 的 兵 丁 就 藐 视 耶 稣 ， 戏 弄 他 ， 给 他 穿 上 华 丽 衣 服 ， 把 他 送 回 彼 拉 多 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25948', '42', '23', '12', '从 前 希 律 和 彼 拉 多 彼 此 有 仇 ， 在 那 一 天 就 成 了 朋 友 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25949', '42', '23', '13', '＜ 耶 稣 被 判 死 刑 （ 太   2 7 : 1 5 - 2 6 ； 可   1 5 : 6 - 1 5 ； 约   1 8 : 3 9 - 1 9 : 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25950', '42', '23', '14', '就 对 他 们 说 ： “ 你 们 解 这 人 到 我 这 里 ， 说 他 是 诱 惑 百 姓 的 。 看 哪 ， 我 也 曾 将 你 们 告 他 的 事 ， 在 你 们 面 前 审 问 他 ， 并 没 有 查 出 他 什 么 罪 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25951', '42', '23', '15', '就 是 希 律 也 是 如 此 ， 所 以 把 他 送 回 来 。 可 见 他 没 有 做 什 么 该 死 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25952', '42', '23', '16', '故 此 ， 我 要 责 打 他 ， 把 他 释 放 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25953', '42', '23', '17', '｛ 有 古 卷 加 ： 每 逢 这 节 期 ， 巡 抚 必 须 释 放 一 个 囚 犯 给 他 们 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25954', '42', '23', '18', '众 人 却 一 齐 喊 着 说 ： “ 除 掉 这 个 人 ！ 释 放 巴 拉 巴 给 我 们 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25955', '42', '23', '19', '这 巴 拉 巴 是 因 在 城 里 作 乱 杀 人 ， 下 在 监 里 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25956', '42', '23', '20', '彼 拉 多 愿 意 释 放 耶 稣 ， 就 又 劝 解 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25957', '42', '23', '21', '无 奈 他 们 喊 着 说 ： “ 钉 他 十 字 架 ！ 钉 他 十 字 架 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25958', '42', '23', '22', '彼 拉 多 第 三 次 对 他 们 说 ： “ 为 什 么 呢 ？ 这 人 做 了 什 么 恶 事 呢 ？ 我 并 没 有 查 出 他 什 么 该 死 的 罪 来 。 所 以 ， 我 要 责 打 他 ， 把 他 释 放 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25959', '42', '23', '23', '他 们 大 声 催 逼 彼 拉 多 ， 求 他 把 耶 稣 钉 在 十 字 架 上 。 他 们 的 声 音 就 得 了 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25960', '42', '23', '24', '彼 拉 多 这 才 照 他 们 所 求 的 定 案 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25961', '42', '23', '25', '把 他 们 所 求 的 那 作 乱 杀 人 、 下 在 监 里 的 释 放 了 ， 把 耶 稣 交 给 他 们 ， 任 凭 他 们 的 意 思 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25962', '42', '23', '26', '＜ 耶 稣 被 钉 十 字 架 （ 太   2 7 : 3 2 - 4 4 ； 可   1 5 : 2 1 - 3 2 ； 约   1 9 : 1 7 - 2 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25963', '42', '23', '27', '有 许 多 百 姓 跟 随 耶 稣 ， 内 中 有 好 些 妇 女 ； 妇 女 们 为 他 号 啕 痛 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25964', '42', '23', '28', '耶 稣 转 身 对 她 们 说 ： “ 耶 路 撒 冷 的 女 子 ， 不 要 为 我 哭 ， 当 为 自 己 和 自 己 的 儿 女 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25965', '42', '23', '29', '因 为 日 子 要 到 ， 人 必 说 ： ‘ 不 生 育 的 ， 和 未 曾 怀 胎 的 ， 未 曾 乳 养 婴 孩 的 ， 有 福 了 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25966', '42', '23', '30', '那 时 ， 人 要 向 大 山 说 ： 倒 在 我 们 身 上 ！ 向 小 山 说 ： 遮 盖 我 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25967', '42', '23', '31', '“ 这 些 事 既 行 在 有 汁 水 的 树 上 ， 那 枯 干 的 树 将 来 怎 么 样 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25968', '42', '23', '32', '又 有 两 个 犯 人 ， 和 耶 稣 一 同 带 来 处 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25969', '42', '23', '33', '到 了 一 个 地 方 ， 名 叫 “ 髑 髅 地 ” ， 就 在 那 里 把 耶 稣 钉 在 十 字 架 上 ， 又 钉 了 两 个 犯 人 ： 一 个 在 左 边 ， 一 个 在 右 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25970', '42', '23', '34', '当 下 耶 稣 说 ： “ 父 啊 ！ 赦 免 他 们 ； 因 为 他 们 所 做 的 ， 他 们 不 晓 得 。 ” 兵 丁 就 拈 阄 分 他 的 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25971', '42', '23', '35', '百 姓 站 在 那 里 观 看 。 官 府 也 嗤 笑 他 ， 说 ： “ 他 救 了 别 人 ； 他 若 是 基 督 ， 神 所 拣 选 的 ， 可 以 救 自 己 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25972', '42', '23', '36', '兵 丁 也 戏 弄 他 ， 上 前 拿 醋 送 给 他 喝 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25973', '42', '23', '37', '说 ： “ 你 若 是 犹 太 人 的 王 ， 可 以 救 自 己 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25974', '42', '23', '38', '在 耶 稣 以 上 有 一 个 牌 子 ｛ 有 古 卷 加 ： 用 希 腊 、 罗 马 、 希 伯 来 的 文 字 ｝ 写 着 ： “ 这 是 犹 太 人 的 王 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25975', '42', '23', '39', '那 同 钉 的 两 个 犯 人 有 一 个 讥 笑 他 ， 说 ： “ 你 不 是 基 督 吗 ？ 可 以 救 自 己 和 我 们 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25976', '42', '23', '40', '那 一 个 就 应 声 责 备 他 ， 说 ： “ 你 既 是 一 样 受 刑 的 ， 还 不 怕 神 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25977', '42', '23', '41', '我 们 是 应 该 的 ， 因 我 们 所 受 的 与 我 们 所 做 的 相 称 ， 但 这 个 人 没 有 做 过 一 件 不 好 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25978', '42', '23', '42', '就 说 ： “ 耶 稣 啊 ， 你 得 国 降 临 的 时 候 ， 求 你 记 念 我 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25979', '42', '23', '43', '耶 稣 对 他 说 ： “ 我 实 在 告 诉 你 ， 今 日 你 要 同 我 在 乐 园 里 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25980', '42', '23', '44', '＜ 耶 稣 的 死 （ 太   2 7 : 4 5 - 5 6 ； 可   1 5 : 3 3 - 4 1 ； 约   1 9 : 2 8 - 3 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25981', '42', '23', '45', '日 头 变 黑 了 ； 殿 里 的 幔 子 从 当 中 裂 为 两 半 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25982', '42', '23', '46', '耶 稣 大 声 喊 着 说 ： “ 父 啊 ！ 我 将 我 的 灵 魂 交 在 你 手 里 。 ” 说 了 这 话 ， 气 就 断 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25983', '42', '23', '47', '百 夫 长 看 见 所 成 的 事 ， 就 归 荣 耀 与 神 ， 说 ： “ 这 真 是 个 义 人 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25984', '42', '23', '48', '聚 集 观 看 的 众 人 见 了 这 所 成 的 事 都 捶 着 胸 回 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25985', '42', '23', '49', '还 有 一 切 与 耶 稣 熟 识 的 人 ， 和 从 加 利 利 跟 着 他 来 的 妇 女 们 ， 都 远 远 地 站 着 看 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25986', '42', '23', '50', '＜ 耶 稣 的 安 葬 （ 太   2 7 : 5 7 - 6 1 ； 可   1 5 : 4 2 - 4 7 ； 约   1 9 : 3 8 - 4 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25987', '42', '23', '51', '众 人 所 谋 所 为 ， 他 并 没 有 附 从 。 他 本 是 犹 太 、 亚 利 马 太 城 里 素 常 盼 望 神 国 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25988', '42', '23', '52', '这 人 去 见 彼 拉 多 ， 求 耶 稣 的 身 体 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25989', '42', '23', '53', '就 取 下 来 ， 用 细 麻 布 裹 好 ， 安 放 在 石 头 凿 成 的 坟 墓 里 ； 那 里 头 从 来 没 有 葬 过 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25990', '42', '23', '54', '那 日 是 预 备 日 ， 安 息 日 也 快 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25991', '42', '23', '55', '那 些 从 加 利 利 和 耶 稣 同 来 的 妇 女 跟 在 后 面 ， 看 见 了 坟 墓 和 他 的 身 体 怎 样 安 放 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25992', '42', '23', '56', '她 们 就 回 去 ， 预 备 了 香 料 香 膏 。 她 们 在 安 息 日 ， 便 遵 着 诫 命 安 息 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25993', '42', '24', '1', '＜ 耶 稣 复 活 （ 太   2 8 : 1 - 1 0 ； 可   1 6 : 1 - 8 ； 约   2 0 : 1 - 1 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25994', '42', '24', '2', '看 见 石 头 已 经 从 坟 墓 滚 开 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25995', '42', '24', '3', '她 们 就 进 去 ， 只 是 不 见 主 耶 稣 的 身 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25996', '42', '24', '4', '正 在 猜 疑 之 间 ， 忽 然 有 两 个 人 站 在 旁 边 ， 衣 服 放 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25997', '42', '24', '5', '妇 女 们 惊 怕 ， 将 脸 伏 地 。 那 两 个 人 就 对 她 们 说 ： “ 为 什 么 在 死 人 中 找 活 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25998', '42', '24', '6', '他 不 在 这 里 ， 已 经 复 活 了 。 当 记 念 他 还 在 加 利 利 的 时 候 怎 样 告 诉 你 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('25999', '42', '24', '7', '说 ： ‘ 人 子 必 须 被 交 在 罪 人 手 里 ， 钉 在 十 字 架 上 ， 第 三 日 复 活 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26000', '42', '24', '8', '她 们 就 想 起 耶 稣 的 话 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26001', '42', '24', '9', '便 从 坟 墓 那 里 回 去 ， 把 这 一 切 的 事 告 诉 十 一 个 使 徒 和 其 余 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26002', '42', '24', '10', '那 告 诉 使 徒 的 就 是 抹 大 拉 的 马 利 亚 和 约 亚 拿 ， 并 雅 各 的 母 亲 马 利 亚 ， 还 有 与 她 们 在 一 处 的 妇 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26003', '42', '24', '11', '她 们 这 些 话 ， 使 徒 以 为 是 胡 言 ， 就 不 相 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26004', '42', '24', '12', '彼 得 起 来 ， 跑 到 坟 墓 前 ， 低 头 往 里 看 ， 见 细 麻 布 独 在 一 处 ， 就 回 去 了 ， 心 里 希 奇 所 成 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26005', '42', '24', '13', '＜ 在 以 马 忤 斯 的 路 上 （ 可   1 6 : 1 2 - 1 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26006', '42', '24', '14', '他 们 彼 此 谈 论 所 遇 见 的 这 一 切 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26007', '42', '24', '15', '正 谈 论 相 问 的 时 候 ， 耶 稣 亲 自 就 近 他 们 ， 和 他 们 同 行 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26008', '42', '24', '16', '只 是 他 们 的 眼 睛 迷 糊 了 ， 不 认 识 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26009', '42', '24', '17', '耶 稣 对 他 们 说 ： “ 你 们 走 路 彼 此 谈 论 的 是 什 么 事 呢 ？ ” 他 们 就 站 住 ， 脸 上 带 着 愁 容 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26010', '42', '24', '18', '二 人 中 有 一 个 名 叫 革 流 巴 的 回 答 说 ： “ 你 在 耶 路 撒 冷 作 客 ， 还 不 知 道 这 几 天 在 那 里 所 出 的 事 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26011', '42', '24', '19', '耶 稣 说 ： “ 什 么 事 呢 ？ ” 他 们 说 ： “ 就 是 拿 撒 勒 人 耶 稣 的 事 。 他 是 个 先 知 ， 在 神 和 众 百 姓 面 前 ， 说 话 行 事 都 有 大 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26012', '42', '24', '20', '祭 司 长 和 我 们 的 官 府 竟 把 他 解 去 ， 定 了 死 罪 ， 钉 在 十 字 架 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26013', '42', '24', '21', '但 我 们 素 来 所 盼 望 、 要 赎 以 色 列 民 的 就 是 他 ！ 不 但 如 此 ， 而 且 这 事 成 就 ， 现 在 已 经 三 天 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26014', '42', '24', '22', '再 者 ， 我 们 中 间 有 几 个 妇 女 使 我 们 惊 奇 ； 她 们 清 早 到 了 坟 墓 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26015', '42', '24', '23', '不 见 他 的 身 体 ， 就 回 来 告 诉 我 们 ， 说 看 见 了 天 使 显 现 ， 说 他 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26016', '42', '24', '24', '又 有 我 们 的 几 个 人 往 坟 墓 那 里 去 ， 所 遇 见 的 正 如 妇 女 们 所 说 的 ， 只 是 没 有 看 见 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26017', '42', '24', '25', '耶 稣 对 他 们 说 ： “ 无 知 的 人 哪 ， 先 知 所 说 的 一 切 话 ， 你 们 的 心 信 得 太 迟 钝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26018', '42', '24', '26', '基 督 这 样 受 害 ， 又 进 入 他 的 荣 耀 ， 岂 不 是 应 当 的 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26019', '42', '24', '27', '于 是 从 摩 西 和 众 先 知 起 ， 凡 经 上 所 指 着 自 己 的 话 都 给 他 们 讲 解 明 白 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26020', '42', '24', '28', '将 近 他 们 所 去 的 村 子 ， 耶 稣 好 像 还 要 往 前 行 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26021', '42', '24', '29', '他 们 却 强 留 他 ， 说 ： “ 时 候 晚 了 ， 日 头 已 经 平 西 了 ， 请 你 同 我 们 住 下 吧 ！ ” 耶 稣 就 进 去 ， 要 同 他 们 住 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26022', '42', '24', '30', '到 了 坐 席 的 时 候 ， 耶 稣 拿 起 饼 来 ， 祝 谢 了 ， 擘 开 ， 递 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26023', '42', '24', '31', '他 们 的 眼 睛 明 亮 了 ， 这 才 认 出 他 来 。 忽 然 耶 稣 不 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26024', '42', '24', '32', '他 们 彼 此 说 ： “ 在 路 上 ， 他 和 我 们 说 话 ， 给 我 们 讲 解 圣 经 的 时 候 ， 我 们 的 心 岂 不 是 火 热 的 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26025', '42', '24', '33', '他 们 就 立 时 起 身 ， 回 耶 路 撒 冷 去 ， 正 遇 见 十 一 个 使 徒 和 他 们 的 同 人 聚 集 在 一 处 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26026', '42', '24', '34', '说 ： “ 主 果 然 复 活 ， 已 经 现 给 西 门 看 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26027', '42', '24', '35', '两 个 人 就 把 路 上 所 遇 见 ， 和 擘 饼 的 时 候 怎 么 被 他 们 认 出 来 的 事 ， 都 述 说 了 一 遍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26028', '42', '24', '36', '＜ 向 门 徒 显 现 （ 太   2 8 : 1 6 - 2 0 ； 可   1 6 : 1 4 - 1 8 ； 约   2 0 : 1 9 - 2 3 ； 徒   1 : 6 - 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26029', '42', '24', '37', '他 们 却 惊 慌 害 怕 ， 以 为 所 看 见 的 是 魂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26030', '42', '24', '38', '耶 稣 说 ： “ 你 们 为 什 么 愁 烦 ？ 为 什 么 心 里 起 疑 念 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26031', '42', '24', '39', '你 们 看 我 的 手 ， 我 的 脚 ， 就 知 道 实 在 是 我 了 。 摸 我 看 看 ！ 魂 无 骨 无 肉 ， 你 们 看 ， 我 是 有 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26032', '42', '24', '40', '说 了 这 话 ， 就 把 手 和 脚 给 他 们 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26033', '42', '24', '41', '他 们 正 喜 得 不 敢 信 ， 并 且 希 奇 ； 耶 稣 就 说 ： “ 你 们 这 里 有 什 么 吃 的 没 有 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26034', '42', '24', '42', '他 们 便 给 他 一 片 烧 鱼 。 ｛ 有 古 卷 加 ： 和 一 块 蜜 房 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26035', '42', '24', '43', '他 接 过 来 ， 在 他 们 面 前 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26036', '42', '24', '44', '耶 稣 对 他 们 说 ： “ 这 就 是 我 从 前 与 你 们 同 在 之 时 所 告 诉 你 们 的 话 说 ： 摩 西 的 律 法 、 先 知 的 书 ， 和 诗 篇 上 所 记 的 ， 凡 指 着 我 的 话 都 必 须 应 验 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26037', '42', '24', '45', '于 是 耶 稣 开 他 们 的 心 窍 ， 使 他 们 能 明 白 圣 经 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26038', '42', '24', '46', '又 对 他 们 说 ： “ 照 经 上 所 写 的 ， 基 督 必 受 害 ， 第 三 日 从 死 里 复 活 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26039', '42', '24', '47', '并 且 人 要 奉 他 的 名 传 悔 改 、 赦 罪 的 道 ， 从 耶 路 撒 冷 起 直 传 到 万 邦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26040', '42', '24', '48', '你 们 就 是 这 些 事 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26041', '42', '24', '49', '我 要 将 我 父 所 应 许 的 降 在 你 们 身 上 ， 你 们 要 在 城 里 等 候 ， 直 到 你 们 领 受 从 上 头 来 的 能 力 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26042', '42', '24', '50', '＜ 耶 稣 升 天 （ 可   1 6 : 1 9 - 2 0 ； 徒   1 : 9 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26043', '42', '24', '51', '正 祝 福 的 时 候 ， 他 就 离 开 他 们 ， 被 带 到 天 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26044', '42', '24', '52', '他 们 就 拜 他 ， 大 大 地 欢 喜 ， 回 耶 路 撒 冷 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26045', '42', '24', '53', '常 在 殿 里 称 颂 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26046', '43', '1', '1', '＜ 道 成 肉 身 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26047', '43', '1', '2', '这 道 太 初 与 神 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26048', '43', '1', '3', '万 物 是 藉 着 他 造 的 ； 凡 被 造 的 ， 没 有 一 样 不 是 藉 着 他 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26049', '43', '1', '4', '生 命 在 他 里 头 ， 这 生 命 就 是 人 的 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26050', '43', '1', '5', '光 照 在 黑 暗 里 ， 黑 暗 却 不 接 受 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26051', '43', '1', '6', '有 一 个 人 ， 是 从 神 那 里 差 来 的 ， 名 叫 约 翰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26052', '43', '1', '7', '这 人 来 ， 为 要 作 见 证 ， 就 是 为 光 作 见 证 ， 叫 众 人 因 他 可 以 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26053', '43', '1', '8', '他 不 是 那 光 ， 乃 是 要 为 光 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26054', '43', '1', '9', '那 光 是 真 光 ， 照 亮 一 切 生 在 世 上 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26055', '43', '1', '10', '他 在 世 界 ， 世 界 也 是 藉 着 他 造 的 ， 世 界 却 不 认 识 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26056', '43', '1', '11', '他 到 自 己 的 地 方 来 ， 自 己 的 人 倒 不 接 待 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26057', '43', '1', '12', '凡 接 待 他 的 ， 就 是 信 他 名 的 人 ， 他 就 赐 他 们 权 柄 作 神 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26058', '43', '1', '13', '这 等 人 不 是 从 血 气 生 的 ， 不 是 从 情 欲 生 的 ， 也 不 是 从 人 意 生 的 ， 乃 是 从 神 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26059', '43', '1', '14', '道 成 了 肉 身 ， 住 在 我 们 中 间 ， 充 充 满 满 地 有 恩 典 有 真 理 。 我 们 也 见 过 他 的 荣 光 ， 正 是 父 独 生 子 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26060', '43', '1', '15', '约 翰 为 他 作 见 证 ， 喊 着 说 ： “ 这 就 是 我 曾 说 ： ‘ 那 在 我 以 后 来 的 ， 反 成 了 在 我 以 前 的 ， 因 他 本 来 在 我 以 前 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26061', '43', '1', '16', '从 他 丰 满 的 恩 典 里 ， 我 们 都 领 受 了 ， 而 且 恩 上 加 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26062', '43', '1', '17', '律 法 本 是 藉 着 摩 西 传 的 ； 恩 典 和 真 理 都 是 由 耶 稣 基 督 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26063', '43', '1', '18', '从 来 没 有 人 看 见 神 ， 只 有 在 父 怀 里 的 独 生 子 将 他 表 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26064', '43', '1', '19', '＜ 施 洗 约 翰 的 见 证 （ 太   3 : 1 - 1 2 ； 可   1 : 1 - 8 ； 路   3 : 1 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26065', '43', '1', '20', '他 就 明 说 ， 并 不 隐 瞒 ， 明 说 ： “ 我 不 是 基 督 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26066', '43', '1', '21', '他 们 又 问 他 说 ： “ 这 样 ， 你 是 谁 呢 ？ 是 以 利 亚 吗 ？ ” 他 说 ： “ 我 不 是 。 ” “ 是 那 先 知 吗 ？ ” 他 回 答 说 ： “ 不 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26067', '43', '1', '22', '于 是 他 们 说 ： “ 你 到 底 是 谁 ， 叫 我 们 好 回 覆 差 我 们 来 的 人 。 你 自 己 说 ， 你 是 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26068', '43', '1', '23', '他 说 ： “ 我 就 是 那 在 旷 野 有 人 声 喊 着 说 ： ‘ 修 直 主 的 道 路 ’ ， 正 如 先 知 以 赛 亚 所 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26069', '43', '1', '24', '那 些 人 是 法 利 赛 人 差 来 的 ｛ 或 译 ： 那 差 来 的 是 法 利 赛 人 ｝ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26070', '43', '1', '25', '他 们 就 问 他 说 ： “ 你 既 不 是 基 督 ， 不 是 以 利 亚 ， 也 不 是 那 先 知 ， 为 什 么 施 洗 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26071', '43', '1', '26', '约 翰 回 答 说 ： “ 我 是 用 水 施 洗 ， 但 有 一 位 站 在 你 们 中 间 ， 是 你 们 不 认 识 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26072', '43', '1', '27', '就 是 那 在 我 以 后 来 的 ， 我 给 他 解 鞋 带 也 不 配 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26073', '43', '1', '28', '这 是 在 约 旦 河 外 伯 大 尼 ｛ 有 古 卷 ： 伯 大 巴 喇 ｝ ， 约 翰 施 洗 的 地 方 作 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26074', '43', '1', '29', '＜ 神 的 羔 羊 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26075', '43', '1', '30', '这 就 是 我 曾 说 ： ‘ 有 一 位 在 我 以 后 来 、 反 成 了 在 我 以 前 的 ， 因 他 本 来 在 我 以 前 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26076', '43', '1', '31', '我 先 前 不 认 识 他 ， 如 今 我 来 用 水 施 洗 ， 为 要 叫 他 显 明 给 以 色 列 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26077', '43', '1', '32', '约 翰 又 作 见 证 说 ： “ 我 曾 看 见 圣 灵 ， 仿 佛 鸽 子 从 天 降 下 ， 住 在 他 的 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26078', '43', '1', '33', '我 先 前 不 认 识 他 ， 只 是 那 差 我 来 用 水 施 洗 的 、 对 我 说 ： ‘ 你 看 见 圣 灵 降 下 来 ， 住 在 谁 的 身 上 ， 谁 就 是 用 圣 灵 施 洗 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26079', '43', '1', '34', '我 看 见 了 ， 就 证 明 这 是 神 的 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26080', '43', '1', '35', '＜ 初 次 选 召 门 徒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26081', '43', '1', '36', '他 见 耶 稣 行 走 ， 就 说 ： “ 看 哪 ， 这 是 神 的 羔 羊 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26082', '43', '1', '37', '两 个 门 徒 听 见 他 的 话 ， 就 跟 从 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26083', '43', '1', '38', '耶 稣 转 过 身 来 ， 看 见 他 们 跟 着 ， 就 问 他 们 说 ： “ 你 们 要 什 么 ？ ” 他 们 说 ： “ 拉 比 ， 在 哪 里 住 ？ ” （ 拉 比 翻 出 来 就 是 夫 子 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26084', '43', '1', '39', '耶 稣 说 ： “ 你 们 来 看 。 ” 他 们 就 去 看 他 在 哪 里 住 ， 这 一 天 便 与 他 同 住 ； 那 时 约 有 申 正 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26085', '43', '1', '40', '听 见 约 翰 的 话 跟 从 耶 稣 的 那 两 个 人 ， 一 个 是 西 门 ． 彼 得 的 兄 弟 安 得 烈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26086', '43', '1', '41', '他 先 找 着 自 己 的 哥 哥 西 门 ， 对 他 说 ： “ 我 们 遇 见 弥 赛 亚 了 。 ” （ 弥 赛 亚 翻 出 来 就 是 基 督 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26087', '43', '1', '42', '于 是 领 他 去 见 耶 稣 。 耶 稣 看 见 他 ， 说 ： “ 你 是 约 翰 的 儿 子 西 门 ｛ 约 翰 在 马 太 十 六 章 十 七 节 称 约 拿 ｝ ， 你 要 称 为 矶 法 。 ” （ 矶 法 翻 出 来 就 是 彼 得 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26088', '43', '1', '43', '＜ 呼 召 腓 力 和 拿 但 业 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26089', '43', '1', '44', '这 腓 力 是 伯 赛 大 人 ， 和 安 得 烈 、 彼 得 同 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26090', '43', '1', '45', '腓 力 找 着 拿 但 业 ， 对 他 说 ： “ 摩 西 在 律 法 上 所 写 的 和 众 先 知 所 记 的 那 一 位 ， 我 们 遇 见 了 ， 就 是 约 瑟 的 儿 子 拿 撒 勒 人 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26091', '43', '1', '46', '拿 但 业 对 他 说 ： “ 拿 撒 勒 还 能 出 什 么 好 的 吗 ？ ” 腓 力 说 ： “ 你 来 看 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26092', '43', '1', '47', '耶 稣 看 见 拿 但 业 来 ， 就 指 着 他 说 ： “ 看 哪 ， 这 是 个 真 以 色 列 人 ， 他 心 里 是 没 有 诡 诈 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26093', '43', '1', '48', '拿 但 业 对 耶 稣 说 ： “ 你 从 哪 里 知 道 我 呢 ？ ” 耶 稣 回 答 说 ： “ 腓 力 还 没 有 招 呼 你 ， 你 在 无 花 果 树 底 下 ， 我 就 看 见 你 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26094', '43', '1', '49', '拿 但 业 说 ： “ 拉 比 ， 你 是 神 的 儿 子 ， 你 是 以 色 列 的 王 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26095', '43', '1', '50', '耶 稣 对 他 说 ： “ 因 为 我 说 ‘ 在 无 花 果 树 底 下 看 见 你 ’ ， 你 就 信 吗 ？ 你 将 要 看 见 比 这 更 大 的 事 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26096', '43', '1', '51', '又 说 ： “ 我 实 实 在 在 地 告 诉 你 们 ， 你 们 将 要 看 见 天 开 了 ， 神 的 使 者 上 去 下 来 在 人 子 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26097', '43', '2', '1', '＜ 迦 拿 的 婚 礼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26098', '43', '2', '2', '耶 稣 和 他 的 门 徒 也 被 请 去 赴 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26099', '43', '2', '3', '酒 用 尽 了 ， 耶 稣 的 母 亲 对 他 说 ： “ 他 们 没 有 酒 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26100', '43', '2', '4', '耶 稣 说 ： “ 母 亲 ｛ 原 文 是 妇 人 ｝ ， 我 与 你 有 什 么 相 干 ？ 我 的 时 候 还 没 有 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26101', '43', '2', '5', '他 母 亲 对 用 人 说 ： “ 他 告 诉 你 们 什 么 ， 你 们 就 做 什 么 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26102', '43', '2', '6', '照 犹 太 人 洁 净 的 规 矩 ， 有 六 口 石 缸 摆 在 那 里 ， 每 口 可 以 盛 两 三 桶 水 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26103', '43', '2', '7', '耶 稣 对 用 人 说 ： “ 把 缸 倒 满 了 水 。 ” 他 们 就 倒 满 了 ， 直 到 缸 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26104', '43', '2', '8', '耶 稣 又 说 ： “ 现 在 可 以 舀 出 来 ， 送 给 管 筵 席 的 。 ” 他 们 就 送 了 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26105', '43', '2', '9', '管 筵 席 的 尝 了 那 水 变 的 酒 ， 并 不 知 道 是 哪 里 来 的 ， 只 有 舀 水 的 用 人 知 道 。 管 筵 席 的 便 叫 新 郎 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26106', '43', '2', '10', '对 他 说 ： “ 人 都 是 先 摆 上 好 酒 ， 等 客 喝 足 了 ， 才 摆 上 次 的 ， 你 倒 把 好 酒 留 到 如 今 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26107', '43', '2', '11', '这 是 耶 稣 所 行 的 头 一 件 神 迹 ， 是 在 加 利 利 的 迦 拿 行 的 ， 显 出 他 的 荣 耀 来 ； 他 的 门 徒 就 信 他 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26108', '43', '2', '12', '这 事 以 后 ， 耶 稣 与 他 的 母 亲 、 弟 兄 ， 和 门 徒 都 下 迦 百 农 去 ， 在 那 里 住 了 不 多 几 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26109', '43', '2', '13', '＜ 洁 净 圣 殿 （ 太   2 1 : 1 2 - 1 3 ； 可   1 1 : 1 5 - 1 7 ； 路   1 9 : 4 5 - 4 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26110', '43', '2', '14', '看 见 殿 里 有 卖 牛 、 羊 、 鸽 子 的 ， 并 有 兑 换 银 钱 的 人 坐 在 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26111', '43', '2', '15', '耶 稣 就 拿 绳 子 做 成 鞭 子 ， 把 牛 羊 都 赶 出 殿 去 ， 倒 出 兑 换 银 钱 之 人 的 银 钱 ， 推 翻 他 们 的 桌 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26112', '43', '2', '16', '又 对 卖 鸽 子 的 说 ： “ 把 这 些 东 西 拿 去 ！ 不 要 将 我 父 的 殿 当 作 买 卖 的 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26113', '43', '2', '17', '他 的 门 徒 就 想 起 经 上 记 着 说 ： “ 我 为 你 的 殿 心 里 焦 急 ， 如 同 火 烧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26114', '43', '2', '18', '因 此 犹 太 人 问 他 说 ： “ 你 既 做 这 些 事 ， 还 显 什 么 神 迹 给 我 们 看 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26115', '43', '2', '19', '耶 稣 回 答 说 ： “ 你 们 拆 毁 这 殿 ， 我 三 日 内 要 再 建 立 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26116', '43', '2', '20', '犹 太 人 便 说 ： “ 这 殿 是 四 十 六 年 才 造 成 的 ， 你 三 日 内 就 再 建 立 起 来 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26117', '43', '2', '21', '但 耶 稣 这 话 是 以 他 的 身 体 为 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26118', '43', '2', '22', '所 以 到 他 从 死 里 复 活 以 后 ， 门 徒 就 想 起 他 说 过 这 话 ， 便 信 了 圣 经 和 耶 稣 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26119', '43', '2', '23', '＜ 耶 稣 洞 悉 人 心 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26120', '43', '2', '24', '耶 稣 却 不 将 自 己 交 托 他 们 ； 因 为 他 知 道 万 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26121', '43', '2', '25', '也 用 不 着 谁 见 证 人 怎 样 ， 因 他 知 道 人 心 里 所 存 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26122', '43', '3', '1', '＜ 耶 稣 与 尼 哥 德 慕 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26123', '43', '3', '2', '这 人 夜 里 来 见 耶 稣 ， 说 ： “ 拉 比 ， 我 们 知 道 你 是 由 神 那 里 来 作 师 傅 的 ； 因 为 你 所 行 的 神 迹 ， 若 没 有 神 同 在 ， 无 人 能 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26124', '43', '3', '3', '耶 稣 回 答 说 ： “ 我 实 实 在 在 地 告 诉 你 ， 人 若 不 重 生 ， 就 不 能 见 神 的 国 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26125', '43', '3', '4', '尼 哥 德 慕 说 ： “ 人 已 经 老 了 ， 如 何 能 重 生 呢 ？ 岂 能 再 进 母 腹 生 出 来 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26126', '43', '3', '5', '耶 稣 说 ： “ 我 实 实 在 在 地 告 诉 你 ， 人 若 不 是 从 水 和 圣 灵 生 的 ， 就 不 能 进 神 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26127', '43', '3', '6', '从 肉 身 生 的 就 是 肉 身 ； 从 灵 生 的 就 是 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26128', '43', '3', '7', '我 说 ： ‘ 你 们 必 须 重 生 ’ ， 你 不 要 以 为 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26129', '43', '3', '8', '风 随 着 意 思 吹 ， 你 听 见 风 的 响 声 ， 却 不 晓 得 从 哪 里 来 ， 往 哪 里 去 ； 凡 从 圣 灵 生 的 ， 也 是 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26130', '43', '3', '9', '尼 哥 德 慕 问 他 说 ： “ 怎 能 有 这 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26131', '43', '3', '10', '耶 稣 回 答 说 ： “ 你 是 以 色 列 人 的 先 生 ， 还 不 明 白 这 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26132', '43', '3', '11', '我 实 实 在 在 地 告 诉 你 ， 我 们 所 说 的 是 我 们 知 道 的 ； 我 们 所 见 证 的 是 我 们 见 过 的 ； 你 们 却 不 领 受 我 们 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26133', '43', '3', '12', '我 对 你 们 说 地 上 的 事 ， 你 们 尚 且 不 信 ， 若 说 天 上 的 事 ， 如 何 能 信 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26134', '43', '3', '13', '除 了 从 天 降 下 、 仍 旧 在 天 的 人 子 ， 没 有 人 升 过 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26135', '43', '3', '14', '摩 西 在 旷 野 怎 样 举 蛇 ， 人 子 也 必 照 样 被 举 起 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26136', '43', '3', '15', '叫 一 切 信 他 的 都 得 永 生 ｛ 或 译 ： 叫 一 切 信 的 人 在 他 里 面 得 永 生 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26137', '43', '3', '16', '“ 神 爱 世 人 ， 甚 至 将 他 的 独 生 子 赐 给 他 们 ， 叫 一 切 信 他 的 ， 不 致 灭 亡 ， 反 得 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26138', '43', '3', '17', '因 为 神 差 他 的 儿 子 降 世 ， 不 是 要 定 世 人 的 罪 ｛ 或 译 ： 审 判 世 人 ； 下 同 ｝ ， 乃 是 要 叫 世 人 因 他 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26139', '43', '3', '18', '信 他 的 人 ， 不 被 定 罪 ； 不 信 的 人 ， 罪 已 经 定 了 ， 因 为 他 不 信 神 独 生 子 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26140', '43', '3', '19', '光 来 到 世 间 ， 世 人 因 自 己 的 行 为 是 恶 的 ， 不 爱 光 ， 倒 爱 黑 暗 ， 定 他 们 的 罪 就 是 在 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26141', '43', '3', '20', '凡 作 恶 的 便 恨 光 ， 并 不 来 就 光 ， 恐 怕 他 的 行 为 受 责 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26142', '43', '3', '21', '但 行 真 理 的 必 来 就 光 ， 要 显 明 他 所 行 的 是 靠 神 而 行 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26143', '43', '3', '22', '＜ 耶 稣 和 施 洗 约 翰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26144', '43', '3', '23', '约 翰 在 靠 近 撒 冷 的 哀 嫩 也 施 洗 ； 因 为 那 里 水 多 ， 众 人 都 去 受 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26145', '43', '3', '24', '（ 那 时 约 翰 还 没 有 下 在 监 里 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26146', '43', '3', '25', '约 翰 的 门 徒 和 一 个 犹 太 人 辩 论 洁 净 的 礼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26147', '43', '3', '26', '就 来 见 约 翰 ， 说 ： “ 拉 比 ， 从 前 同 你 在 约 旦 河 外 、 你 所 见 证 的 那 位 ， 现 在 施 洗 ， 众 人 都 往 他 那 里 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26148', '43', '3', '27', '约 翰 说 ： “ 若 不 是 从 天 上 赐 的 ， 人 就 不 能 得 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26149', '43', '3', '28', '我 曾 说 ： ‘ 我 不 是 基 督 ， 是 奉 差 遣 在 他 前 面 的 ’ ， 你 们 自 己 可 以 给 我 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26150', '43', '3', '29', '娶 新 妇 的 就 是 新 郎 ； 新 郎 的 朋 友 站 着 ， 听 见 新 郎 的 声 音 就 甚 喜 乐 。 故 此 ， 我 这 喜 乐 满 足 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26151', '43', '3', '30', '他 必 兴 旺 ， 我 必 衰 微 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26152', '43', '3', '31', '＜ 从 天 上 来 的 那 一 位 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26153', '43', '3', '32', '他 将 所 见 所 闻 的 见 证 出 来 ， 只 是 没 有 人 领 受 他 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26154', '43', '3', '33', '那 领 受 他 见 证 的 ， 就 印 上 印 ， 证 明 神 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26155', '43', '3', '34', '神 所 差 来 的 就 说 神 的 话 ， 因 为 神 赐 圣 灵 给 他 是 没 有 限 量 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26156', '43', '3', '35', '父 爱 子 ， 已 将 万 有 交 在 他 手 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26157', '43', '3', '36', '信 子 的 人 有 永 生 ； 不 信 子 的 人 得 不 着 永 生 ｛ 原 文 是 不 得 见 永 生 ｝ ， 神 的 震 怒 常 在 他 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26158', '43', '4', '1', '＜ 耶 稣 和 撒 马 利 亚 妇 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26159', '43', '4', '2', '（ 其 实 不 是 耶 稣 亲 自 施 洗 ， 乃 是 他 的 门 徒 施 洗 ， ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26160', '43', '4', '3', '他 就 离 了 犹 太 ， 又 往 加 利 利 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26161', '43', '4', '4', '必 须 经 过 撒 马 利 亚 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26162', '43', '4', '5', '于 是 到 了 撒 马 利 亚 的 一 座 城 ， 名 叫 叙 加 ， 靠 近 雅 各 给 他 儿 子 约 瑟 的 那 块 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26163', '43', '4', '6', '在 那 里 有 雅 各 井 ； 耶 稣 因 走 路 困 乏 ， 就 坐 在 井 旁 。 那 时 约 有 午 正 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26164', '43', '4', '7', '有 一 个 撒 马 利 亚 的 妇 人 来 打 水 。 耶 稣 对 她 说 ： “ 请 你 给 我 水 喝 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26165', '43', '4', '8', '（ 那 时 门 徒 进 城 买 食 物 去 了 。 〉');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26166', '43', '4', '9', '撒 马 利 亚 的 妇 人 对 他 说 ： “ 你 既 是 犹 太 人 ， 怎 么 向 我 一 个 撒 马 利 亚 妇 人 要 水 喝 呢 ？ ” 原 来 犹 太 人 和 撒 马 利 亚 人 没 有 来 往 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26167', '43', '4', '10', '耶 稣 回 答 说 ： “ 你 若 知 道 神 的 恩 赐 ， 和 对 你 说 ‘ 给 我 水 喝 ’ 的 是 谁 ， 你 必 早 求 他 ， 他 也 必 早 给 了 你 活 水 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26168', '43', '4', '11', '妇 人 说 ： “ 先 生 ， 没 有 打 水 的 器 具 ， 井 又 深 ， 你 从 哪 里 得 活 水 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26169', '43', '4', '12', '我 们 的 祖 宗 雅 各 将 这 井 留 给 我 们 ， 他 自 己 和 儿 子 并 牲 畜 也 都 喝 这 井 里 的 水 ， 难 道 你 比 他 还 大 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26170', '43', '4', '13', '耶 稣 回 答 说 ： “ 凡 喝 这 水 的 还 要 再 渴 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26171', '43', '4', '14', '人 若 喝 我 所 赐 的 水 就 永 远 不 渴 。 我 所 赐 的 水 要 在 他 里 头 成 为 泉 源 ， 直 涌 到 永 生 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26172', '43', '4', '15', '妇 人 说 ： “ 先 生 ， 请 把 这 水 赐 给 我 ， 叫 我 不 渴 ， 也 不 用 来 这 么 远 打 水 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26173', '43', '4', '16', '耶 稣 说 ： “ 你 去 叫 你 丈 夫 也 到 这 里 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26174', '43', '4', '17', '妇 人 说 ： “ 我 没 有 丈 夫 。 ” 耶 稣 说 ： “ 你 说 没 有 丈 夫 是 不 错 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26175', '43', '4', '18', '你 已 经 有 五 个 丈 夫 ， 你 现 在 有 的 并 不 是 你 的 丈 夫 。 你 这 话 是 真 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26176', '43', '4', '19', '妇 人 说 ： “ 先 生 ， 我 看 出 你 是 先 知 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26177', '43', '4', '20', '我 们 的 祖 宗 在 这 山 上 礼 拜 ， 你 们 倒 说 ， 应 当 礼 拜 的 地 方 是 在 耶 路 撒 冷 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26178', '43', '4', '21', '耶 稣 说 ： “ 妇 人 ， 你 当 信 我 。 时 候 将 到 ， 你 们 拜 父 ， 也 不 在 这 山 上 ， 也 不 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26179', '43', '4', '22', '你 们 所 拜 的 ， 你 们 不 知 道 ； 我 们 所 拜 的 ， 我 们 知 道 ， 因 为 救 恩 是 从 犹 太 人 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26180', '43', '4', '23', '时 候 将 到 ， 如 今 就 是 了 ， 那 真 正 拜 父 的 ， 要 用 心 灵 和 诚 实 拜 他 ， 因 为 父 要 这 样 的 人 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26181', '43', '4', '24', '神 是 个 灵 ｛ 或 无 个 字 ｝ ， 所 以 拜 他 的 必 须 用 心 灵 和 诚 实 拜 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26182', '43', '4', '25', '妇 人 说 ： “ 我 知 道 弥 赛 亚 （ 就 是 那 称 为 基 督 的 ） 要 来 ； 他 来 了 ， 必 将 一 切 的 事 都 告 诉 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26183', '43', '4', '26', '耶 稣 说 ： “ 这 和 你 说 话 的 就 是 他 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26184', '43', '4', '27', '当 下 门 徒 回 来 ， 就 希 奇 耶 稣 和 一 个 妇 人 说 话 ； 只 是 没 有 人 说 ： “ 你 是 要 什 么 ？ ” 或 说 ： “ 你 为 什 么 和 她 说 话 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26185', '43', '4', '28', '那 妇 人 就 留 下 水 罐 子 ， 往 城 里 去 ， 对 众 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26186', '43', '4', '29', '“ 你 们 来 看 ！ 有 一 个 人 将 我 素 来 所 行 的 一 切 事 都 给 我 说 出 来 了 ， 莫 非 这 就 是 基 督 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26187', '43', '4', '30', '众 人 就 出 城 ， 往 耶 稣 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26188', '43', '4', '31', '这 其 间 ， 门 徒 对 耶 稣 说 ： “ 拉 比 ， 请 吃 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26189', '43', '4', '32', '耶 稣 说 ： “ 我 有 食 物 吃 ， 是 你 们 不 知 道 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26190', '43', '4', '33', '门 徒 就 彼 此 对 问 说 ： “ 莫 非 有 人 拿 什 么 给 他 吃 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26191', '43', '4', '34', '耶 稣 说 ： “ 我 的 食 物 就 是 遵 行 差 我 来 者 的 旨 意 ， 做 成 他 的 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26192', '43', '4', '35', '你 们 岂 不 说 ‘ 到 收 割 的 时 候 还 有 四 个 月 ’ 吗 ？ 我 告 诉 你 们 ， 举 目 向 田 观 看 ， 庄 稼 已 经 熟 了 ｛ 原 文 是 发 白 ｝ ， 可 以 收 割 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26193', '43', '4', '36', '收 割 的 人 得 工 价 ， 积 蓄 五 谷 到 永 生 ， 叫 撒 种 的 和 收 割 的 一 同 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26194', '43', '4', '37', '俗 语 说 ： ‘ 那 人 撒 种 ， 这 人 收 割 ’ ， 这 话 可 见 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26195', '43', '4', '38', '我 差 你 们 去 收 你 们 所 没 有 劳 苦 的 ； 别 人 劳 苦 ， 你 们 享 受 他 们 所 劳 苦 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26196', '43', '4', '39', '那 城 里 有 好 些 撒 马 利 亚 人 信 了 耶 稣 ， 因 为 那 妇 人 作 见 证 说 ： “ 他 将 我 素 来 所 行 的 一 切 事 都 给 我 说 出 来 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26197', '43', '4', '40', '于 是 撒 马 利 亚 人 来 见 耶 稣 ， 求 他 在 他 们 那 里 住 下 ， 他 便 在 那 里 住 了 两 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26198', '43', '4', '41', '因 耶 稣 的 话 ， 信 的 人 就 更 多 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26199', '43', '4', '42', '便 对 妇 人 说 ： “ 现 在 我 们 信 ， 不 是 因 为 你 的 话 ， 是 我 们 亲 自 听 见 了 ， 知 道 这 真 是 救 世 主 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26200', '43', '4', '43', '＜ 耶 稣 治 好 大 臣 的 儿 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26201', '43', '4', '44', '因 为 耶 稣 自 己 作 过 见 证 说 ： “ 先 知 在 本 地 是 没 有 人 尊 敬 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26202', '43', '4', '45', '到 了 加 利 利 ， 加 利 利 人 既 然 看 见 他 在 耶 路 撒 冷 过 节 所 行 的 一 切 事 ， 就 接 待 他 ， 因 为 他 们 也 是 上 去 过 节 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26203', '43', '4', '46', '耶 稣 又 到 了 加 利 利 的 迦 拿 ， 就 是 他 从 前 变 水 为 酒 的 地 方 。 有 一 个 大 臣 ， 他 的 儿 子 在 迦 百 农 患 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26204', '43', '4', '47', '他 听 见 耶 稣 从 犹 太 到 了 加 利 利 ， 就 来 见 他 ， 求 他 下 去 医 治 他 的 儿 子 ， 因 为 他 儿 子 快 要 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26205', '43', '4', '48', '耶 稣 就 对 他 说 ： “ 若 不 看 见 神 迹 奇 事 ， 你 们 总 是 不 信 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26206', '43', '4', '49', '那 大 臣 说 ： “ 先 生 ， 求 你 趁 着 我 的 孩 子 还 没 有 死 就 下 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26207', '43', '4', '50', '耶 稣 对 他 说 ： “ 回 去 吧 ， 你 的 儿 子 活 了 ！ ” 那 人 信 耶 稣 所 说 的 话 就 回 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26208', '43', '4', '51', '正 下 去 的 时 候 ， 他 的 仆 人 迎 见 他 ， 说 他 的 儿 子 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26209', '43', '4', '52', '他 就 问 什 么 时 候 见 好 的 。 他 们 说 ： “ 昨 日 未 时 热 就 退 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26210', '43', '4', '53', '他 便 知 道 这 正 是 耶 稣 对 他 说 “ 你 儿 子 活 了 ” 的 时 候 ； 他 自 己 和 全 家 就 都 信 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26211', '43', '4', '54', '这 是 耶 稣 在 加 利 利 行 的 第 二 件 神 迹 ， 是 他 从 犹 太 回 去 以 后 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26212', '43', '5', '1', '＜ 在 毕 士 大 池 边 治 病 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26213', '43', '5', '2', '在 耶 路 撒 冷 ， 靠 近 羊 门 有 一 个 池 子 ， 希 伯 来 话 叫 作 毕 士 大 ， 旁 边 有 五 个 廊 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26214', '43', '5', '3', '里 面 躺 着 瞎 眼 的 、 瘸 腿 的 、 血 气 枯 干 的 许 多 病 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26215', '43', '5', '4', '｛ 有 古 卷 加 ： 等 候 水 动 ； 因 为 有 天 使 按 时 下 池 子 搅 动 那 水 ， 水 动 之 后 ， 谁 先 下 去 ， 无 论 害 什 么 病 就 痊 愈 了 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26216', '43', '5', '5', '在 那 里 有 一 个 人 ， 病 了 三 十 八 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26217', '43', '5', '6', '耶 稣 看 见 他 躺 着 ， 知 道 他 病 了 许 久 ， 就 问 他 说 ： “ 你 要 痊 愈 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26218', '43', '5', '7', '病 人 回 答 说 ： “ 先 生 ， 水 动 的 时 候 ， 没 有 人 把 我 放 在 池 子 里 ； 我 正 去 的 时 候 ， 就 有 别 人 比 我 先 下 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26219', '43', '5', '8', '耶 稣 对 他 说 ： “ 起 来 ， 拿 你 的 褥 子 走 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26220', '43', '5', '9', '那 人 立 刻 痊 愈 ， 就 拿 起 褥 子 来 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26221', '43', '5', '10', '那 天 是 安 息 日 ， 所 以 犹 太 人 对 那 医 好 的 人 说 ： “ 今 天 是 安 息 日 ， 你 拿 褥 子 是 不 可 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26222', '43', '5', '11', '他 却 回 答 说 ： “ 那 使 我 痊 愈 的 ， 对 我 说 ： ‘ 拿 你 的 褥 子 走 吧 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26223', '43', '5', '12', '他 们 问 他 说 ： “ 对 你 说 ‘ 拿 褥 子 走 ’ 的 是 什 么 人 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26224', '43', '5', '13', '那 医 好 的 人 不 知 道 是 谁 ； 因 为 那 里 的 人 多 ， 耶 稣 已 经 躲 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26225', '43', '5', '14', '后 来 耶 稣 在 殿 里 遇 见 他 ， 对 他 说 ： “ 你 已 经 痊 愈 了 ， 不 要 再 犯 罪 ， 恐 怕 你 遭 遇 的 更 加 利 害 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26226', '43', '5', '15', '那 人 就 去 告 诉 犹 太 人 ， 使 他 痊 愈 的 是 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26227', '43', '5', '16', '所 以 犹 太 人 逼 迫 耶 稣 ， 因 为 他 在 安 息 日 做 了 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26228', '43', '5', '17', '耶 稣 就 对 他 们 说 ： “ 我 父 做 事 直 到 如 今 ， 我 也 做 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26229', '43', '5', '18', '所 以 犹 太 人 越 发 想 要 杀 他 ； 因 他 不 但 犯 了 安 息 日 ， 并 且 称 神 为 他 的 父 ， 将 自 己 和 神 当 作 平 等 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26230', '43', '5', '19', '＜ 子 的 权 柄 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26231', '43', '5', '20', '父 爱 子 ， 将 自 己 所 做 的 一 切 事 指 给 他 看 ， 还 要 将 比 这 更 大 的 事 指 给 他 看 ， 叫 你 们 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26232', '43', '5', '21', '父 怎 样 叫 死 人 起 来 ， 使 他 们 活 着 ， 子 也 照 样 随 自 己 的 意 思 使 人 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26233', '43', '5', '22', '父 不 审 判 什 么 人 ， 乃 将 审 判 的 事 全 交 与 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26234', '43', '5', '23', '叫 人 都 尊 敬 子 如 同 尊 敬 父 一 样 。 不 尊 敬 子 的 ， 就 是 不 尊 敬 差 子 来 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26235', '43', '5', '24', '我 实 实 在 在 地 告 诉 你 们 ， 那 听 我 话 、 又 信 差 我 来 者 的 ， 就 有 永 生 ； 不 至 于 定 罪 ， 是 已 经 出 死 入 生 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26236', '43', '5', '25', '我 实 实 在 在 地 告 诉 你 们 ， 时 候 将 到 ， 现 在 就 是 了 ， 死 人 要 听 见 神 儿 子 的 声 音 ， 听 见 的 人 就 要 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26237', '43', '5', '26', '因 为 父 怎 样 在 自 己 有 生 命 ， 就 赐 给 他 儿 子 也 照 样 在 自 己 有 生 命 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26238', '43', '5', '27', '并 且 因 为 他 是 人 子 ， 就 赐 给 他 行 审 判 的 权 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26239', '43', '5', '28', '你 们 不 要 把 这 事 看 作 希 奇 。 时 候 要 到 ， 凡 在 坟 墓 里 的 ， 都 要 听 见 他 的 声 音 ， 就 出 来 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26240', '43', '5', '29', '行 善 的 ， 复 活 得 生 ； 作 恶 的 ， 复 活 定 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26241', '43', '5', '30', '“ 我 凭 着 自 己 不 能 做 什 么 ， 我 怎 么 听 见 就 怎 么 审 判 。 我 的 审 判 也 是 公 平 的 ； 因 为 我 不 求 自 己 的 意 思 ， 只 求 那 差 我 来 者 的 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26242', '43', '5', '31', '＜ 为 耶 稣 作 证 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26243', '43', '5', '32', '另 有 一 位 给 我 作 见 证 ， 我 也 知 道 他 给 我 作 的 见 证 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26244', '43', '5', '33', '你 们 曾 差 人 到 约 翰 那 里 ， 他 为 真 理 作 过 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26245', '43', '5', '34', '其 实 ， 我 所 受 的 见 证 不 是 从 人 来 的 ； 然 而 ， 我 说 这 些 话 ， 为 要 叫 你 们 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26246', '43', '5', '35', '约 翰 是 点 着 的 明 灯 ， 你 们 情 愿 暂 时 喜 欢 他 的 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26247', '43', '5', '36', '但 我 有 比 约 翰 更 大 的 见 证 ； 因 为 父 交 给 我 要 我 成 就 的 事 ， 就 是 我 所 做 的 事 ， 这 便 见 证 我 是 父 所 差 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26248', '43', '5', '37', '差 我 来 的 父 也 为 我 作 过 见 证 。 你 们 从 来 没 有 听 见 他 的 声 音 ， 也 没 有 看 见 他 的 形 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26249', '43', '5', '38', '你 们 并 没 有 他 的 道 存 在 心 里 ； 因 为 他 所 差 来 的 ， 你 们 不 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26250', '43', '5', '39', '你 们 查 考 圣 经 ｛ 或 译 ： 应 当 查 考 圣 经 ｝ ， 因 你 们 以 为 内 中 有 永 生 ； 给 我 作 见 证 的 就 是 这 经 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26251', '43', '5', '40', '然 而 ， 你 们 不 肯 到 我 这 里 来 得 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26252', '43', '5', '41', '“ 我 不 受 从 人 来 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26253', '43', '5', '42', '但 我 知 道 ， 你 们 心 里 没 有 神 的 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26254', '43', '5', '43', '我 奉 我 父 的 名 来 ， 你 们 并 不 接 待 我 ； 若 有 别 人 奉 自 己 的 名 来 ， 你 们 倒 要 接 待 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26255', '43', '5', '44', '你 们 互 相 受 荣 耀 ， 却 不 求 从 独 一 之 神 来 的 荣 耀 ， 怎 能 信 我 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26256', '43', '5', '45', '不 要 想 我 在 父 面 前 要 告 你 们 ； 有 一 位 告 你 们 的 ， 就 是 你 们 所 仰 赖 的 摩 西 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26257', '43', '5', '46', '你 们 如 果 信 摩 西 ， 也 必 信 我 ， 因 为 他 书 上 有 指 着 我 写 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26258', '43', '5', '47', '你 们 若 不 信 他 的 书 ， 怎 能 信 我 的 话 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26259', '43', '6', '1', '＜ 耶 稣 给 五 千 人 吃 饱 （ 太   1 4 : 1 3 - 2 1 ； 可   6 : 3 0 - 4 4 ； 路   9 : 1 0 - 1 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26260', '43', '6', '2', '有 许 多 人 因 为 看 见 他 在 病 人 身 上 所 行 的 神 迹 ， 就 跟 随 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26261', '43', '6', '3', '耶 稣 上 了 山 ， 和 门 徒 一 同 坐 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26262', '43', '6', '4', '那 时 犹 太 人 的 逾 越 节 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26263', '43', '6', '5', '耶 稣 举 目 看 见 许 多 人 来 ， 就 对 腓 力 说 ： “ 我 们 从 哪 里 买 饼 叫 这 些 人 吃 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26264', '43', '6', '6', '（ 他 说 这 话 是 要 试 验 腓 力 ； 他 自 己 原 知 道 要 怎 样 行 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26265', '43', '6', '7', '腓 力 回 答 说 ： “ 就 是 二 十 两 银 子 的 饼 ， 叫 他 们 各 人 吃 一 点 也 是 不 够 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26266', '43', '6', '8', '有 一 个 门 徒 ， 就 是 西 门 ． 彼 得 的 兄 弟 安 得 烈 ， 对 耶 稣 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26267', '43', '6', '9', '“ 在 这 里 有 一 个 孩 童 ， 带 着 五 个 大 麦 饼 、 两 条 鱼 ， 只 是 分 给 这 许 多 人 还 算 什 么 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26268', '43', '6', '10', '耶 稣 说 ： “ 你 们 叫 众 人 坐 下 。 ” 原 来 那 地 方 的 草 多 ， 众 人 就 坐 下 ， 数 目 约 有 五 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26269', '43', '6', '11', '耶 稣 拿 起 饼 来 ， 祝 谢 了 ， 就 分 给 那 坐 着 的 人 ； 分 鱼 也 是 这 样 ， 都 随 着 他 们 所 要 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26270', '43', '6', '12', '他 们 吃 饱 了 ， 耶 稣 对 门 徒 说 ： “ 把 剩 下 的 零 碎 收 拾 起 来 ， 免 得 有 糟 蹋 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26271', '43', '6', '13', '他 们 便 将 那 五 个 大 麦 饼 的 零 碎 ， 就 是 众 人 吃 了 剩 下 的 ， 收 拾 起 来 ， 装 满 了 十 二 个 篮 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26272', '43', '6', '14', '众 人 看 见 耶 稣 所 行 的 神 迹 ， 就 说 ： “ 这 真 是 那 要 到 世 间 来 的 先 知 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26273', '43', '6', '15', '耶 稣 既 知 道 众 人 要 来 强 逼 他 作 王 ， 就 独 自 又 退 到 山 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26274', '43', '6', '16', '＜ 耶 稣 在 海 面 上 行 走 （ 太   1 4 : 2 2 - 3 3 ； 可   6 : 4 5 - 5 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26275', '43', '6', '17', '上 了 船 ， 要 过 海 往 迦 百 农 去 。 天 已 经 黑 了 ， 耶 稣 还 没 有 来 到 他 们 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26276', '43', '6', '18', '忽 然 狂 风 大 作 ， 海 就 翻 腾 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26277', '43', '6', '19', '门 徒 摇 橹 ， 约 行 了 十 里 多 路 ， 看 见 耶 稣 在 海 面 上 走 ， 渐 渐 近 了 船 ， 他 们 就 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26278', '43', '6', '20', '耶 稣 对 他 们 说 ： “ 是 我 ， 不 要 怕 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26279', '43', '6', '21', '门 徒 就 喜 欢 接 他 上 船 ， 船 立 时 到 了 他 们 所 要 去 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26280', '43', '6', '22', '＜ 耶 稣 是 生 命 的 粮 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26281', '43', '6', '23', '然 而 ， 有 几 只 小 船 从 提 比 哩 亚 来 ， 靠 近 主 祝 谢 后 分 饼 给 人 吃 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26282', '43', '6', '24', '众 人 见 耶 稣 和 门 徒 都 不 在 那 里 ， 就 上 了 船 ， 往 迦 百 农 去 找 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26283', '43', '6', '25', '既 在 海 那 边 找 着 了 ， 就 对 他 说 ： “ 拉 比 ， 是 几 时 到 这 里 来 的 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26284', '43', '6', '26', '耶 稣 回 答 说 ： “ 我 实 实 在 在 地 告 诉 你 们 ， 你 们 找 我 ， 并 不 是 因 见 了 神 迹 ， 乃 是 因 吃 饼 得 饱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26285', '43', '6', '27', '不 要 为 那 必 坏 的 食 物 劳 力 ， 要 为 那 存 到 永 生 的 食 物 劳 力 ， 就 是 人 子 要 赐 给 你 们 的 ， 因 为 人 子 是 父 神 所 印 证 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26286', '43', '6', '28', '众 人 问 他 说 ： “ 我 们 当 行 什 么 才 算 做 神 的 工 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26287', '43', '6', '29', '耶 稣 回 答 说 ： “ 信 神 所 差 来 的 ， 这 就 是 做 神 的 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26288', '43', '6', '30', '他 们 又 说 ： “ 你 行 什 么 神 迹 ， 叫 我 们 看 见 就 信 你 ； 你 到 底 做 什 么 事 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26289', '43', '6', '31', '我 们 的 祖 宗 在 旷 野 吃 过 吗 哪 ， 如 经 上 写 着 说 ： ‘ 他 从 天 上 赐 下 粮 来 给 他 们 吃 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26290', '43', '6', '32', '耶 稣 说 ： “ 我 实 实 在 在 地 告 诉 你 们 ， 那 从 天 上 来 的 粮 不 是 摩 西 赐 给 你 们 的 ， 乃 是 我 父 将 天 上 来 的 真 粮 赐 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26291', '43', '6', '33', '因 为 神 的 粮 就 是 那 从 天 上 降 下 来 、 赐 生 命 给 世 界 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26292', '43', '6', '34', '他 们 说 ： “ 主 啊 ， 常 将 这 粮 赐 给 我 们 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26293', '43', '6', '35', '耶 稣 说 ： “ 我 就 是 生 命 的 粮 。 到 我 这 里 来 的 ， 必 定 不 饿 ； 信 我 的 ， 永 远 不 渴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26294', '43', '6', '36', '只 是 我 对 你 们 说 过 ， 你 们 已 经 看 见 我 ， 还 是 不 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26295', '43', '6', '37', '凡 父 所 赐 给 我 的 人 必 到 我 这 里 来 ； 到 我 这 里 来 的 ， 我 总 不 丢 弃 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26296', '43', '6', '38', '因 为 我 从 天 上 降 下 来 ， 不 是 要 按 自 己 的 意 思 行 ， 乃 是 要 按 那 差 我 来 者 的 意 思 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26297', '43', '6', '39', '差 我 来 者 的 意 思 就 是 ： 他 所 赐 给 我 的 ， 叫 我 一 个 也 不 失 落 ， 在 末 日 却 叫 他 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26298', '43', '6', '40', '因 为 我 父 的 意 思 是 叫 一 切 见 子 而 信 的 人 得 永 生 ， 并 且 在 末 日 我 要 叫 他 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26299', '43', '6', '41', '犹 太 人 因 为 耶 稣 说 “ 我 是 从 天 上 降 下 来 的 粮 ” ， 就 私 下 议 论 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26300', '43', '6', '42', '说 ： “ 这 不 是 约 瑟 的 儿 子 耶 稣 吗 ？ 他 的 父 母 我 们 岂 不 认 得 吗 ？ 他 如 今 怎 么 说 ‘ 我 是 从 天 上 降 下 来 的 ’ 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26301', '43', '6', '43', '耶 稣 回 答 说 ： “ 你 们 不 要 大 家 议 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26302', '43', '6', '44', '若 不 是 差 我 来 的 父 吸 引 人 ， 就 没 有 能 到 我 这 里 来 的 ； 到 我 这 里 来 的 ， 在 末 日 我 要 叫 他 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26303', '43', '6', '45', '在 先 知 书 上 写 着 说 ： ‘ 他 们 都 要 蒙 神 的 教 训 。 ’ 凡 听 见 父 之 教 训 又 学 习 的 ， 就 到 我 这 里 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26304', '43', '6', '46', '这 不 是 说 有 人 看 见 过 父 ， 惟 独 从 神 来 的 ， 他 看 见 过 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26305', '43', '6', '47', '我 实 实 在 在 地 告 诉 你 们 ， 信 的 人 有 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26306', '43', '6', '48', '我 就 是 生 命 的 粮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26307', '43', '6', '49', '你 们 的 祖 宗 在 旷 野 吃 过 吗 哪 ， 还 是 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26308', '43', '6', '50', '这 是 从 天 上 降 下 来 的 粮 ， 叫 人 吃 了 就 不 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26309', '43', '6', '51', '我 是 从 天 上 降 下 来 生 命 的 粮 ； 人 若 吃 这 粮 ， 就 必 永 远 活 着 。 我 所 要 赐 的 粮 就 是 我 的 肉 ， 为 世 人 之 生 命 所 赐 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26310', '43', '6', '52', '因 此 ， 犹 太 人 彼 此 争 论 说 ： “ 这 个 人 怎 能 把 他 的 肉 给 我 们 吃 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26311', '43', '6', '53', '耶 稣 说 ： “ 我 实 实 在 在 地 告 诉 你 们 ， 你 们 若 不 吃 人 子 的 肉 ， 不 喝 人 子 的 血 ， 就 没 有 生 命 在 你 们 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26312', '43', '6', '54', '吃 我 肉 、 喝 我 血 的 人 就 有 永 生 ， 在 末 日 我 要 叫 他 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26313', '43', '6', '55', '我 的 肉 真 是 可 吃 的 ， 我 的 血 真 是 可 喝 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26314', '43', '6', '56', '吃 我 肉 、 喝 我 血 的 人 常 在 我 里 面 ， 我 也 常 在 他 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26315', '43', '6', '57', '永 活 的 父 怎 样 差 我 来 ， 我 又 因 父 活 着 ； 照 样 ， 吃 我 肉 的 人 也 要 因 我 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26316', '43', '6', '58', '这 就 是 从 天 上 降 下 来 的 粮 。 吃 这 粮 的 人 就 永 远 活 着 ， 不 像 你 们 的 祖 宗 吃 过 吗 哪 还 是 死 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26317', '43', '6', '59', '这 些 话 是 耶 稣 在 迦 百 农 会 堂 里 教 训 人 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26318', '43', '6', '60', '＜ 永 生 的 话 语 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26319', '43', '6', '61', '耶 稣 心 里 知 道 门 徒 为 这 话 议 论 ， 就 对 他 们 说 ： “ 这 话 是 叫 你 们 厌 弃 ｛ 原 文 是 跌 倒 ｝ 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26320', '43', '6', '62', '倘 或 你 们 看 见 人 子 升 到 他 原 来 所 在 之 处 ， 怎 么 样 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26321', '43', '6', '63', '叫 人 活 着 的 乃 是 灵 ， 肉 体 是 无 益 的 。 我 对 你 们 所 说 的 话 就 是 灵 ， 就 是 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26322', '43', '6', '64', '只 是 你 们 中 间 有 不 信 的 人 。 ” 耶 稣 从 起 头 就 知 道 谁 不 信 他 ， 谁 要 卖 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26323', '43', '6', '65', '耶 稣 又 说 ： “ 所 以 我 对 你 们 说 过 ， 若 不 是 蒙 我 父 的 恩 赐 ， 没 有 人 能 到 我 这 里 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26324', '43', '6', '66', '从 此 ， 他 门 徒 中 多 有 退 去 的 ， 不 再 和 他 同 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26325', '43', '6', '67', '耶 稣 就 对 那 十 二 个 门 徒 说 ： “ 你 们 也 要 去 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26326', '43', '6', '68', '西 门 ． 彼 得 回 答 说 ： “ 主 啊 ， 你 有 永 生 之 道 ， 我 们 还 归 从 谁 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26327', '43', '6', '69', '我 们 已 经 信 了 ， 又 知 道 你 是 神 的 圣 者 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26328', '43', '6', '70', '耶 稣 说 ： “ 我 不 是 拣 选 了 你 们 十 二 个 门 徒 吗 ？ 但 你 们 中 间 有 一 个 是 魔 鬼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26329', '43', '6', '71', '耶 稣 这 话 是 指 着 加 略 人 西 门 的 儿 子 犹 大 说 的 ； 他 本 是 十 二 个 门 徒 里 的 一 个 ， 后 来 要 卖 耶 稣 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26330', '43', '7', '1', '＜ 耶 稣 的 兄 弟 不 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26331', '43', '7', '2', '当 时 犹 太 人 的 住 棚 节 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26332', '43', '7', '3', '耶 稣 的 弟 兄 就 对 他 说 ： “ 你 离 开 这 里 上 犹 太 去 吧 ， 叫 你 的 门 徒 也 看 见 你 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26333', '43', '7', '4', '人 要 显 扬 名 声 ， 没 有 在 暗 处 行 事 的 ； 你 如 果 行 这 些 事 ， 就 当 将 自 己 显 明 给 世 人 看 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26334', '43', '7', '5', '因 为 连 他 的 弟 兄 说 这 话 ， 是 因 为 不 信 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26335', '43', '7', '6', '耶 稣 就 对 他 们 说 ： “ 我 的 时 候 还 没 有 到 ； 你 们 的 时 候 常 是 方 便 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26336', '43', '7', '7', '世 人 不 能 恨 你 们 ， 却 是 恨 我 ， 因 为 我 指 证 他 们 所 做 的 事 是 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26337', '43', '7', '8', '你 们 上 去 过 节 吧 ， 我 现 在 不 上 去 过 这 节 ， 因 为 我 的 时 候 还 没 有 满 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26338', '43', '7', '9', '耶 稣 说 了 这 话 ， 仍 旧 住 在 加 利 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26339', '43', '7', '10', '＜ 耶 稣 过 住 棚 节 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26340', '43', '7', '11', '正 在 节 期 ， 犹 太 人 寻 找 耶 稣 ， 说 ： “ 他 在 哪 里 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26341', '43', '7', '12', '众 人 为 他 纷 纷 议 论 ， 有 的 说 ： “ 他 是 好 人 。 ” 有 的 说 ： “ 不 然 ， 他 是 迷 惑 众 人 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26342', '43', '7', '13', '只 是 没 有 人 明 明 地 讲 论 他 ， 因 为 怕 犹 太 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26343', '43', '7', '14', '到 了 节 期 ， 耶 稣 上 殿 里 去 教 训 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26344', '43', '7', '15', '犹 太 人 就 希 奇 ， 说 ： “ 这 个 人 没 有 学 过 ， 怎 么 明 白 书 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26345', '43', '7', '16', '耶 稣 说 ： “ 我 的 教 训 不 是 我 自 己 的 ， 乃 是 那 差 我 来 者 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26346', '43', '7', '17', '人 若 立 志 遵 着 他 的 旨 意 行 ， 就 必 晓 得 这 教 训 或 是 出 于 神 ， 或 是 我 凭 着 自 己 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26347', '43', '7', '18', '人 凭 着 自 己 说 ， 是 求 自 己 的 荣 耀 ； 惟 有 求 那 差 他 来 者 的 荣 耀 ， 这 人 是 真 的 ， 在 他 心 里 没 有 不 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26348', '43', '7', '19', '摩 西 岂 不 是 传 律 法 给 你 们 吗 ？ 你 们 却 没 有 一 个 人 守 律 法 。 为 什 么 想 要 杀 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26349', '43', '7', '20', '众 人 回 答 说 ： “ 你 是 被 鬼 附 着 了 ！ 谁 想 要 杀 你 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26350', '43', '7', '21', '耶 稣 说 ： “ 我 做 了 一 件 事 ， 你 们 都 以 为 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26351', '43', '7', '22', '摩 西 传 割 礼 给 你 们 （ 其 实 不 是 从 摩 西 起 的 ， 乃 是 从 祖 先 起 的 ） ， 因 此 你 们 也 在 安 息 日 给 人 行 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26352', '43', '7', '23', '人 若 在 安 息 日 受 割 礼 ， 免 得 违 背 摩 西 的 律 法 ， 我 在 安 息 日 叫 一 个 人 全 然 好 了 ， 你 们 就 向 我 生 气 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26353', '43', '7', '24', '不 可 按 外 貌 断 定 是 非 ， 总 要 按 公 平 断 定 是 非 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26354', '43', '7', '25', '＜ 这 是 基 督 吗 ? ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26355', '43', '7', '26', '你 看 他 还 明 明 地 讲 道 ， 他 们 也 不 向 他 说 什 么 ， 难 道 官 长 真 知 道 这 是 基 督 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26356', '43', '7', '27', '然 而 ， 我 们 知 道 这 个 人 从 哪 里 来 ； 只 是 基 督 来 的 时 候 ， 没 有 人 知 道 他 从 哪 里 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26357', '43', '7', '28', '那 时 ， 耶 稣 在 殿 里 教 训 人 ， 大 声 说 ： “ 你 们 也 知 道 我 ， 也 知 道 我 从 哪 里 来 ； 我 来 并 不 是 由 于 自 己 。 但 那 差 我 来 的 是 真 的 。 你 们 不 认 识 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26358', '43', '7', '29', '我 却 认 识 他 ； 因 为 我 是 从 他 来 的 ， 他 也 是 差 了 我 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26359', '43', '7', '30', '他 们 就 想 要 捉 拿 耶 稣 ； 只 是 没 有 人 下 手 ， 因 为 他 的 时 候 还 没 有 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26360', '43', '7', '31', '但 众 人 中 间 有 好 些 信 他 的 ， 说 ： “ 基 督 来 的 时 候 ， 他 所 行 的 神 迹 岂 能 比 这 人 所 行 的 更 多 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26361', '43', '7', '32', '＜ 差 役 捉 拿 耶 稣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26362', '43', '7', '33', '于 是 耶 稣 说 ： “ 我 还 有 不 多 的 时 候 和 你 们 同 在 ， 以 后 就 回 到 差 我 来 的 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26363', '43', '7', '34', '你 们 要 找 我 ， 却 找 不 着 ； 我 所 在 的 地 方 你 们 不 能 到 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26364', '43', '7', '35', '犹 太 人 就 彼 此 对 问 说 ： “ 这 人 要 往 哪 里 去 ， 叫 我 们 找 不 着 呢 ？ 难 道 他 要 往 散 住 希 腊 中 的 犹 太 人 那 里 去 教 训 希 腊 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26365', '43', '7', '36', '他 说 ： ‘ 你 们 要 找 我 ， 却 找 不 着 ； 我 所 在 的 地 方 ， 你 们 不 能 到 ’ ， 这 话 是 什 么 意 思 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26366', '43', '7', '37', '＜ 活 水 的 江 河 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26367', '43', '7', '38', '信 我 的 人 就 如 经 上 所 说 ： ‘ 从 他 腹 中 要 流 出 活 水 的 江 河 来 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26368', '43', '7', '39', '耶 稣 这 话 是 指 着 信 他 之 人 要 受 圣 灵 说 的 。 那 时 还 没 有 赐 下 圣 灵 来 ， 因 为 耶 稣 尚 未 得 着 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26369', '43', '7', '40', '＜ 群 众 因 耶 稣 而 纷 争 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26370', '43', '7', '41', '有 的 说 ： “ 这 是 基 督 。 ” 但 也 有 的 说 ： “ 基 督 岂 是 从 加 利 利 出 来 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26371', '43', '7', '42', '经 上 岂 不 是 说 ‘ 基 督 是 大 卫 的 后 裔 ， 从 大 卫 本 乡 伯 利 恒 出 来 的 ’ 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26372', '43', '7', '43', '于 是 众 人 因 着 耶 稣 起 了 纷 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26373', '43', '7', '44', '其 中 有 人 要 捉 拿 他 ， 只 是 无 人 下 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26374', '43', '7', '45', '＜ 犹 太 领 袖 的 不 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26375', '43', '7', '46', '差 役 回 答 说 ： “ 从 来 没 有 像 他 这 样 说 话 的 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26376', '43', '7', '47', '法 利 赛 人 说 ： “ 你 们 也 受 了 迷 惑 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26377', '43', '7', '48', '官 长 或 是 法 利 赛 人 岂 有 信 他 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26378', '43', '7', '49', '但 这 些 不 明 白 律 法 的 百 姓 是 被 咒 诅 的 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26379', '43', '7', '50', '内 中 有 尼 哥 德 慕 ， 就 是 从 前 去 见 耶 稣 的 ， 对 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26380', '43', '7', '51', '“ 不 先 听 本 人 的 口 供 ， 不 知 道 他 所 做 的 事 ， 难 道 我 们 的 律 法 还 定 他 的 罪 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26381', '43', '7', '52', '他 们 回 答 说 ： “ 你 也 是 出 于 加 利 利 吗 ？ 你 且 去 查 考 ， 就 可 知 道 加 利 利 没 有 出 过 先 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26382', '43', '8', '1', '＜ 行 淫 时 被 捉 的 女 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26383', '43', '8', '2', '清 早 又 回 到 殿 里 。 众 百 姓 都 到 他 那 里 去 ， 他 就 坐 下 ， 教 训 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26384', '43', '8', '3', '文 士 和 法 利 赛 人 带 着 一 个 行 淫 时 被 拿 的 妇 人 来 ， 叫 她 站 在 当 中 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26385', '43', '8', '4', '就 对 耶 稣 说 ： “ 夫 子 ， 这 妇 人 是 正 行 淫 之 时 被 拿 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26386', '43', '8', '5', '摩 西 在 律 法 上 吩 咐 我 们 把 这 样 的 妇 人 用 石 头 打 死 。 你 说 该 把 她 怎 么 样 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26387', '43', '8', '6', '他 们 说 这 话 ， 乃 试 探 耶 稣 ， 要 得 着 告 他 的 把 柄 。 耶 稣 却 弯 着 腰 ， 用 指 头 在 地 上 画 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26388', '43', '8', '7', '他 们 还 是 不 住 地 问 他 ， 耶 稣 就 直 起 腰 来 ， 对 他 们 说 ： “ 你 们 中 间 谁 是 没 有 罪 的 ， 谁 就 可 以 先 拿 石 头 打 她 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26389', '43', '8', '8', '于 是 又 弯 着 腰 ， 用 指 头 在 地 上 画 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26390', '43', '8', '9', '他 们 听 见 这 话 ， 就 从 老 到 少 ， 一 个 一 个 地 都 出 去 了 ， 只 剩 下 耶 稣 一 人 ， 还 有 那 妇 人 仍 然 站 在 当 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26391', '43', '8', '10', '耶 稣 就 直 起 腰 来 ， 对 她 说 ： “ 妇 人 ， 那 些 人 在 哪 里 呢 ？ 没 有 人 定 你 的 罪 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26392', '43', '8', '11', '她 说 ： “ 主 啊 ， 没 有 。 ” 耶 稣 说 ： “ 我 也 不 定 你 的 罪 。 去 吧 ， 从 此 不 要 再 犯 罪 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26393', '43', '8', '12', '＜ 耶 稣 是 世 界 的 光 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26394', '43', '8', '13', '法 利 赛 人 对 他 说 ： “ 你 是 为 自 己 作 见 证 ， 你 的 见 证 不 真 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26395', '43', '8', '14', '耶 稣 说 ： “ 我 虽 然 为 自 己 作 见 证 ， 我 的 见 证 还 是 真 的 ； 因 我 知 道 我 从 哪 里 来 ， 往 哪 里 去 ； 你 们 却 不 知 道 我 从 哪 里 来 ， 往 哪 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26396', '43', '8', '15', '你 们 是 以 外 貌 ｛ 原 文 是 凭 肉 身 ｝ 判 断 人 ， 我 却 不 判 断 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26397', '43', '8', '16', '就 是 判 断 人 ， 我 的 判 断 也 是 真 的 ； 因 为 不 是 我 独 自 在 这 里 ， 还 有 差 我 来 的 父 与 我 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26398', '43', '8', '17', '你 们 的 律 法 上 也 记 着 说 ： ‘ 两 个 人 的 见 证 是 真 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26399', '43', '8', '18', '我 是 为 自 己 作 见 证 ， 还 有 差 我 来 的 父 也 是 为 我 作 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26400', '43', '8', '19', '他 们 就 问 他 说 ： “ 你 的 父 在 哪 里 ？ ” 耶 稣 回 答 说 ： “ 你 们 不 认 识 我 ， 也 不 认 识 我 的 父 ； 若 是 认 识 我 ， 也 就 认 识 我 的 父 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26401', '43', '8', '20', '这 些 话 是 耶 稣 在 殿 里 的 库 房 、 教 训 人 时 所 说 的 ， 也 没 有 人 拿 他 ， 因 为 他 的 时 候 还 没 有 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26402', '43', '8', '21', '＜ 我 所 去 的 地 方 你 们 不 能 到 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26403', '43', '8', '22', '犹 太 人 说 ： “ 他 说 ‘ 我 所 去 的 地 方 ， 你 们 不 能 到 ’ ， 难 道 他 要 自 尽 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26404', '43', '8', '23', '耶 稣 对 他 们 说 ： “ 你 们 是 从 下 头 来 的 ， 我 是 从 上 头 来 的 ； 你 们 是 属 这 世 界 的 ， 我 不 是 属 这 世 界 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26405', '43', '8', '24', '所 以 我 对 你 们 说 ， 你 们 要 死 在 罪 中 。 你 们 若 不 信 我 是 基 督 ， 必 要 死 在 罪 中 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26406', '43', '8', '25', '他 们 就 问 他 说 ： “ 你 是 谁 ？ ” 耶 稣 对 他 们 说 ： “ 就 是 我 从 起 初 所 告 诉 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26407', '43', '8', '26', '我 有 许 多 事 讲 论 你 们 ， 判 断 你 们 ； 但 那 差 我 来 的 是 真 的 ， 我 在 他 那 里 所 听 见 的 ， 我 就 传 给 世 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26408', '43', '8', '27', '他 们 不 明 白 耶 稣 是 指 着 父 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26409', '43', '8', '28', '所 以 耶 稣 说 ： “ 你 们 举 起 人 子 以 后 ， 必 知 道 我 是 基 督 ， 并 且 知 道 我 没 有 一 件 事 是 凭 着 自 己 做 的 。 我 说 这 些 话 乃 是 照 着 父 所 教 训 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26410', '43', '8', '29', '那 差 我 来 的 是 与 我 同 在 ； 他 没 有 撇 下 我 独 自 在 这 里 ， 因 为 我 常 做 他 所 喜 悦 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26411', '43', '8', '30', '耶 稣 说 这 话 的 时 候 ， 就 有 许 多 人 信 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26412', '43', '8', '31', '＜ 真 理 必 使 你 们 得 自 由 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26413', '43', '8', '32', '你 们 必 晓 得 真 理 ， 真 理 必 叫 你 们 得 以 自 由 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26414', '43', '8', '33', '他 们 回 答 说 ： “ 我 们 是 亚 伯 拉 罕 的 后 裔 ， 从 来 没 有 作 过 谁 的 奴 仆 。 你 怎 么 说 ‘ 你 们 必 得 以 自 由 ’ 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26415', '43', '8', '34', '耶 稣 回 答 说 ： “ 我 实 实 在 在 地 告 诉 你 们 ， 所 有 犯 罪 的 就 是 罪 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26416', '43', '8', '35', '奴 仆 不 能 永 远 住 在 家 里 ； 儿 子 是 永 远 住 在 家 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26417', '43', '8', '36', '所 以 天 父 的 儿 子 若 叫 你 们 自 由 ， 你 们 就 真 自 由 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26418', '43', '8', '37', '我 知 道 你 们 是 亚 伯 拉 罕 的 子 孙 ， 你 们 却 想 要 杀 我 ， 因 为 你 们 心 里 容 不 下 我 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26419', '43', '8', '38', '我 所 说 的 是 在 我 父 那 里 看 见 的 ； 你 们 所 行 的 是 在 你 们 的 父 那 里 听 见 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26420', '43', '8', '39', '＜ 你 们 的 父 是 魔 鬼 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26421', '43', '8', '40', '我 将 在 神 那 里 所 听 见 的 真 理 告 诉 了 你 们 ， 现 在 你 们 却 想 要 杀 我 ， 这 不 是 亚 伯 拉 罕 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26422', '43', '8', '41', '你 们 是 行 你 们 父 所 行 的 事 。 ” 他 们 说 ： “ 我 们 不 是 从 淫 乱 生 的 ； 我 们 只 有 一 位 父 ， 就 是 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26423', '43', '8', '42', '耶 稣 说 ： “ 倘 若 神 是 你 们 的 父 ， 你 们 就 必 爱 我 ； 因 为 我 本 是 出 于 神 ， 也 是 从 神 而 来 ， 并 不 是 由 着 自 己 来 ， 乃 是 他 差 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26424', '43', '8', '43', '你 们 为 什 么 不 明 白 我 的 话 呢 ？ 无 非 是 因 你 们 不 能 听 我 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26425', '43', '8', '44', '你 们 是 出 于 你 们 的 父 魔 鬼 ， 你 们 父 的 私 欲 你 们 偏 要 行 。 他 从 起 初 是 杀 人 的 ， 不 守 真 理 ， 因 他 心 里 没 有 真 理 。 他 说 谎 是 出 于 自 己 ； 因 他 本 来 是 说 谎 的 ， 也 是 说 谎 之 人 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26426', '43', '8', '45', '我 将 真 理 告 诉 你 们 ， 你 们 就 因 此 不 信 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26427', '43', '8', '46', '你 们 中 间 谁 能 指 证 我 有 罪 呢 ？ 我 既 然 将 真 理 告 诉 你 们 ， 为 什 么 不 信 我 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26428', '43', '8', '47', '出 于 神 的 ， 必 听 神 的 话 ； 你 们 不 听 ， 因 为 你 们 不 是 出 于 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26429', '43', '8', '48', '＜ 还 没 有 亚 伯 拉 罕 就 有 了 我 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26430', '43', '8', '49', '耶 稣 说 ： “ 我 不 是 鬼 附 着 的 ； 我 尊 敬 我 的 父 ， 你 们 倒 轻 慢 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26431', '43', '8', '50', '我 不 求 自 己 的 荣 耀 ， 有 一 位 为 我 求 荣 耀 、 定 是 非 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26432', '43', '8', '51', '我 实 实 在 在 地 告 诉 你 们 ， 人 若 遵 守 我 的 道 ， 就 永 远 不 见 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26433', '43', '8', '52', '犹 太 人 对 他 说 ： “ 现 在 我 们 知 道 你 是 鬼 附 着 的 。 亚 伯 拉 罕 死 了 ， 众 先 知 也 死 了 ， 你 还 说 ： ‘ 人 若 遵 守 我 的 道 ， 就 永 远 不 尝 死 味 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26434', '43', '8', '53', '难 道 你 比 我 们 的 祖 宗 亚 伯 拉 罕 还 大 吗 ？ 他 死 了 ， 众 先 知 也 死 了 ， 你 将 自 己 当 作 什 么 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26435', '43', '8', '54', '耶 稣 回 答 说 ： “ 我 若 荣 耀 自 己 ， 我 的 荣 耀 就 算 不 得 什 么 ； 荣 耀 我 的 乃 是 我 的 父 ， 就 是 你 们 所 说 是 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26436', '43', '8', '55', '你 们 未 曾 认 识 他 ； 我 却 认 识 他 。 我 若 说 不 认 识 他 ， 我 就 是 说 谎 的 ， 像 你 们 一 样 ； 但 我 认 识 他 ， 也 遵 守 他 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26437', '43', '8', '56', '你 们 的 祖 宗 亚 伯 拉 罕 欢 欢 喜 喜 地 仰 望 我 的 日 子 ， 既 看 见 了 就 快 乐 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26438', '43', '8', '57', '犹 太 人 说 ： “ 你 还 没 有 五 十 岁 ， 岂 见 过 亚 伯 拉 罕 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26439', '43', '8', '58', '耶 稣 说 ： “ 我 实 实 在 在 地 告 诉 你 们 ， 还 没 有 亚 伯 拉 罕 就 有 了 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26440', '43', '8', '59', '于 是 他 们 拿 石 头 要 打 他 ； 耶 稣 却 躲 藏 ， 从 殿 里 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26441', '43', '9', '1', '＜ 治 好 生 来 瞎 眼 的 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26442', '43', '9', '2', '门 徒 问 耶 稣 说 ： “ 拉 比 ， 这 人 生 来 是 瞎 眼 的 ， 是 谁 犯 了 罪 ？ 是 这 人 呢 ？ 是 他 父 母 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26443', '43', '9', '3', '耶 稣 回 答 说 ： “ 也 不 是 这 人 犯 了 罪 ， 也 不 是 他 父 母 犯 了 罪 ， 是 要 在 他 身 上 显 出 神 的 作 为 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26444', '43', '9', '4', '趁 着 白 日 ， 我 们 必 须 做 那 差 我 来 者 的 工 ； 黑 夜 将 到 ， 就 没 有 人 能 做 工 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26445', '43', '9', '5', '我 在 世 上 的 时 候 ， 是 世 上 的 光 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26446', '43', '9', '6', '耶 稣 说 了 这 话 ， 就 吐 唾 沫 在 地 上 ， 用 唾 沫 和 泥 抹 在 瞎 子 的 眼 睛 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26447', '43', '9', '7', '对 他 说 ： “ 你 往 西 罗 亚 池 子 里 去 洗 （ 西 罗 亚 翻 出 来 就 是 “ 奉 差 遣 ” 。 ） 他 去 一 洗 ， 回 头 就 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26448', '43', '9', '8', '他 的 邻 舍 和 那 素 常 见 他 是 讨 饭 的 ， 就 说 ： “ 这 不 是 那 从 前 坐 着 讨 饭 的 人 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26449', '43', '9', '9', '有 人 说 ： “ 是 他 ” ； 又 有 人 说 ： “ 不 是 ， 却 是 像 他 。 ” 他 自 己 说 ： “ 是 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26450', '43', '9', '10', '他 们 对 他 说 ： “ 你 的 眼 睛 是 怎 么 开 的 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26451', '43', '9', '11', '他 回 答 说 ： “ 有 一 个 人 ， 名 叫 耶 稣 ， 他 和 泥 抹 我 的 眼 睛 ， 对 我 说 ： ‘ 你 往 西 罗 亚 池 子 去 洗 。 ’ 我 去 一 洗 ， 就 看 见 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26452', '43', '9', '12', '他 们 说 ： “ 那 个 人 在 哪 里 ？ ” 他 说 ： “ 我 不 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26453', '43', '9', '13', '＜ 法 利 赛 人 盘 问 医 治 的 事 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26454', '43', '9', '14', '耶 稣 和 泥 开 他 眼 睛 的 日 子 是 安 息 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26455', '43', '9', '15', '法 利 赛 人 也 问 他 是 怎 么 得 看 见 的 。 瞎 子 对 他 们 说 ： “ 他 把 泥 抹 在 我 的 眼 睛 上 ， 我 去 一 洗 ， 就 看 见 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26456', '43', '9', '16', '法 利 赛 人 中 有 的 说 ： “ 这 个 人 不 是 从 神 来 的 ， 因 为 他 不 守 安 息 日 。 ” 又 有 人 说 ： “ 一 个 罪 人 怎 能 行 这 样 的 神 迹 呢 ？ ” 他 们 就 起 了 纷 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26457', '43', '9', '17', '他 们 又 对 瞎 子 说 ： “ 他 既 然 开 了 你 的 眼 睛 ， 你 说 他 是 怎 样 的 人 呢 ？ ” 他 说 ： “ 是 个 先 知 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26458', '43', '9', '18', '犹 太 人 不 信 他 从 前 是 瞎 眼 ， 后 来 能 看 见 的 ， 等 到 叫 了 他 的 父 母 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26459', '43', '9', '19', '问 他 们 说 ： “ 这 是 你 们 的 儿 子 吗 ？ 你 们 说 他 生 来 是 瞎 眼 的 ， 如 今 怎 么 能 看 见 了 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26460', '43', '9', '20', '他 父 母 回 答 说 ： “ 他 是 我 们 的 儿 子 ， 生 来 就 瞎 眼 ， 这 是 我 们 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26461', '43', '9', '21', '至 于 他 如 今 怎 么 能 看 见 ， 我 们 却 不 知 道 ； 是 谁 开 了 他 的 眼 睛 ， 我 们 也 不 知 道 。 他 已 经 成 了 人 ， 你 们 问 他 吧 ， 他 自 己 必 能 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26462', '43', '9', '22', '他 父 母 说 这 话 ， 是 怕 犹 太 人 ； 因 为 犹 太 人 已 经 商 议 定 了 ， 若 有 认 耶 稣 是 基 督 的 ， 要 把 他 赶 出 会 堂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26463', '43', '9', '23', '因 此 他 父 母 说 ： “ 他 已 经 成 了 人 ， 你 们 问 他 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26464', '43', '9', '24', '所 以 法 利 赛 人 第 二 次 叫 了 那 从 前 瞎 眼 的 人 来 ， 对 他 说 ： “ 你 该 将 荣 耀 归 给 神 ， 我 们 知 道 这 人 是 个 罪 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26465', '43', '9', '25', '他 说 ： “ 他 是 个 罪 人 不 是 ， 我 不 知 道 ； 有 一 件 事 我 知 道 ， 从 前 我 是 眼 瞎 的 ， 如 今 能 看 见 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26466', '43', '9', '26', '他 们 就 问 他 说 ： “ 他 向 你 做 什 么 ？ 是 怎 么 开 了 你 的 眼 睛 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26467', '43', '9', '27', '他 回 答 说 ： “ 我 方 才 告 诉 你 们 ， 你 们 不 听 ， 为 什 么 又 要 听 呢 ？ 莫 非 你 们 也 要 作 他 的 门 徒 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26468', '43', '9', '28', '他 们 就 骂 他 说 ： “ 你 是 他 的 门 徒 ； 我 们 是 摩 西 的 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26469', '43', '9', '29', '神 对 摩 西 说 话 是 我 们 知 道 的 ； 只 是 这 个 人 ， 我 们 不 知 道 他 从 哪 里 来 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26470', '43', '9', '30', '那 人 回 答 说 ： “ 他 开 了 我 的 眼 睛 ， 你 们 竟 不 知 道 他 从 哪 里 来 ， 这 真 是 奇 怪 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26471', '43', '9', '31', '我 们 知 道 神 不 听 罪 人 ， 惟 有 敬 奉 神 、 遵 行 他 旨 意 的 ， 神 才 听 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26472', '43', '9', '32', '从 创 世 以 来 ， 未 曾 听 见 有 人 把 生 来 是 瞎 子 的 眼 睛 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26473', '43', '9', '33', '这 人 若 不 是 从 神 来 的 ， 什 么 也 不 能 做 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26474', '43', '9', '34', '他 们 回 答 说 ： “ 你 全 然 生 在 罪 孽 中 ， 还 要 教 训 我 们 吗 ？ ” 于 是 把 他 赶 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26475', '43', '9', '35', '＜ 灵 性 的 盲 目 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26476', '43', '9', '36', '他 回 答 说 ： “ 主 啊 ， 谁 是 神 的 儿 子 ， 叫 我 信 他 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26477', '43', '9', '37', '耶 稣 说 ： “ 你 已 经 看 见 他 ， 现 在 和 你 说 话 的 就 是 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26478', '43', '9', '38', '他 说 ： “ 主 啊 ， 我 信 ！ ” 就 拜 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26479', '43', '9', '39', '耶 稣 说 ： “ 我 为 审 判 到 这 世 上 来 ， 叫 不 能 看 见 的 ， 可 以 看 见 ； 能 看 见 的 ， 反 瞎 了 眼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26480', '43', '9', '40', '同 他 在 那 里 的 法 利 赛 人 听 见 这 话 ， 就 说 ： “ 难 道 我 们 也 瞎 了 眼 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26481', '43', '9', '41', '耶 稣 对 他 们 说 ： “ 你 们 若 瞎 了 眼 ， 就 没 有 罪 了 ； 但 如 今 你 们 说 ‘ 我 们 能 看 见 ’ ， 所 以 你 们 的 罪 还 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26482', '43', '10', '1', '＜ 羊 圈 的 比 喻 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26483', '43', '10', '2', '从 门 进 去 的 ， 才 是 羊 的 牧 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26484', '43', '10', '3', '看 门 的 就 给 他 开 门 ； 羊 也 听 他 的 声 音 。 他 按 著 名 叫 自 己 的 羊 ， 把 羊 领 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26485', '43', '10', '4', '既 放 出 自 己 的 羊 来 ， 就 在 前 头 走 ， 羊 也 跟 着 他 ， 因 为 认 得 他 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26486', '43', '10', '5', '羊 不 跟 着 生 人 ； 因 为 不 认 得 他 的 声 音 ， 必 要 逃 跑 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26487', '43', '10', '6', '耶 稣 将 这 比 喻 告 诉 他 们 ， 但 他 们 不 明 白 所 说 的 是 什 么 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26488', '43', '10', '7', '＜ 好 牧 人 耶 稣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26489', '43', '10', '8', '凡 在 我 以 先 来 的 都 是 贼 ， 是 强 盗 ； 羊 却 不 听 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26490', '43', '10', '9', '我 就 是 门 ； 凡 从 我 进 来 的 ， 必 然 得 救 ， 并 且 出 入 得 草 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26491', '43', '10', '10', '盗 贼 来 ， 无 非 要 偷 窃 ， 杀 害 ， 毁 坏 ； 我 来 了 ， 是 要 叫 羊 ｛ 或 译 ： 人 ｝ 得 生 命 ， 并 且 得 的 更 丰 盛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26492', '43', '10', '11', '我 是 好 牧 人 ； 好 牧 人 为 羊 舍 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26493', '43', '10', '12', '若 是 雇 工 ， 不 是 牧 人 ， 羊 也 不 是 他 自 己 的 ， 他 看 见 狼 来 ， 就 撇 下 羊 逃 走 ； 狼 抓 住 羊 ， 赶 散 了 羊 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26494', '43', '10', '13', '雇 工 逃 走 ， 因 他 是 雇 工 ， 并 不 顾 念 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26495', '43', '10', '14', '我 是 好 牧 人 ； 我 认 识 我 的 羊 ， 我 的 羊 也 认 识 我 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26496', '43', '10', '15', '正 如 父 认 识 我 ， 我 也 认 识 父 一 样 ； 并 且 我 为 羊 舍 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26497', '43', '10', '16', '我 另 外 有 羊 ， 不 是 这 圈 里 的 ； 我 必 须 领 他 们 来 ， 他 们 也 要 听 我 的 声 音 ， 并 且 要 合 成 一 群 ， 归 一 个 牧 人 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26498', '43', '10', '17', '我 父 爱 我 ； 因 我 将 命 舍 去 ， 好 再 取 回 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26499', '43', '10', '18', '没 有 人 夺 我 的 命 去 ， 是 我 自 己 舍 的 。 我 有 权 柄 舍 了 ， 也 有 权 柄 取 回 来 。 这 是 我 从 我 父 所 受 的 命 令 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26500', '43', '10', '19', '犹 太 人 为 这 些 话 又 起 了 纷 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26501', '43', '10', '20', '内 中 有 好 些 人 说 ： “ 他 是 被 鬼 附 着 ， 而 且 疯 了 ， 为 什 么 听 他 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26502', '43', '10', '21', '又 有 人 说 ： “ 这 不 是 鬼 附 之 人 所 说 的 话 。 鬼 岂 能 叫 瞎 子 的 眼 睛 开 了 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26503', '43', '10', '22', '＜ 被 犹 太 人 弃 绝 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26504', '43', '10', '23', '耶 稣 在 殿 里 所 罗 门 的 廊 下 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26505', '43', '10', '24', '犹 太 人 围 着 他 ， 说 ： “ 你 叫 我 们 犹 疑 不 定 到 几 时 呢 ？ 你 若 是 基 督 ， 就 明 明 地 告 诉 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26506', '43', '10', '25', '耶 稣 回 答 说 ： “ 我 已 经 告 诉 你 们 ， 你 们 不 信 。 我 奉 我 父 之 名 所 行 的 事 可 以 为 我 作 见 证 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26507', '43', '10', '26', '只 是 你 们 不 信 ， 因 为 你 们 不 是 我 的 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26508', '43', '10', '27', '我 的 羊 听 我 的 声 音 ， 我 也 认 识 他 们 ， 他 们 也 跟 着 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26509', '43', '10', '28', '我 又 赐 给 他 们 永 生 ； 他 们 永 不 灭 亡 ， 谁 也 不 能 从 我 手 里 把 他 们 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26510', '43', '10', '29', '我 父 把 羊 赐 给 我 ， 他 比 万 有 都 大 ， 谁 也 不 能 从 我 父 手 里 把 他 们 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26511', '43', '10', '30', '我 与 父 原 为 一 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26512', '43', '10', '31', '犹 太 人 又 拿 起 石 头 来 要 打 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26513', '43', '10', '32', '耶 稣 对 他 们 说 ： “ 我 从 父 显 出 许 多 善 事 给 你 们 看 ， 你 们 是 为 哪 一 件 拿 石 头 打 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26514', '43', '10', '33', '犹 太 人 回 答 说 ： “ 我 们 不 是 为 善 事 拿 石 头 打 你 ， 是 为 你 说 僭 妄 的 话 ； 又 为 你 是 个 人 ， 反 将 自 己 当 作 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26515', '43', '10', '34', '耶 稣 说 ： “ 你 们 的 律 法 上 岂 不 是 写 着 ‘ 我 曾 说 你 们 是 神 ’ 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26516', '43', '10', '35', '经 上 的 话 是 不 能 废 的 ； 若 那 些 承 受 神 道 的 人 尚 且 称 为 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26517', '43', '10', '36', '父 所 分 别 为 圣 、 又 差 到 世 间 来 的 ， 他 自 称 是 神 的 儿 子 ， 你 们 还 向 他 说 ‘ 你 说 僭 妄 的 话 ’ 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26518', '43', '10', '37', '我 若 不 行 我 父 的 事 ， 你 们 就 不 必 信 我 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26519', '43', '10', '38', '我 若 行 了 ， 你 们 纵 然 不 信 我 ， 也 当 信 这 些 事 ， 叫 你 们 又 知 道 又 明 白 父 在 我 里 面 ， 我 也 在 父 里 面 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26520', '43', '10', '39', '他 们 又 要 拿 他 ， 他 却 逃 出 他 们 的 手 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26521', '43', '10', '40', '耶 稣 又 往 约 旦 河 外 去 ， 到 了 约 翰 起 初 施 洗 的 地 方 ， 就 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26522', '43', '10', '41', '有 许 多 人 来 到 他 那 里 。 他 们 说 ： “ 约 翰 一 件 神 迹 没 有 行 过 ， 但 约 翰 指 着 这 人 所 说 的 一 切 话 都 是 真 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26523', '43', '10', '42', '在 那 里 ， 信 耶 稣 的 人 就 多 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26524', '43', '11', '1', '＜ 拉 撒 路 的 死 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26525', '43', '11', '2', '这 马 利 亚 就 是 那 用 香 膏 抹 主 ， 又 用 头 发 擦 他 脚 的 ； 患 病 的 拉 撒 路 是 她 的 兄 弟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26526', '43', '11', '3', '她 姊 妹 两 个 就 打 发 人 去 见 耶 稣 ， 说 ： “ 主 啊 ， 你 所 爱 的 人 病 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26527', '43', '11', '4', '耶 稣 听 见 ， 就 说 ： “ 这 病 不 至 于 死 ， 乃 是 为 神 的 荣 耀 ， 叫 神 的 儿 子 因 此 得 荣 耀 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26528', '43', '11', '5', '耶 稣 素 来 爱 马 大 和 她 妹 子 并 拉 撒 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26529', '43', '11', '6', '听 见 拉 撒 路 病 了 ， 就 在 所 居 之 地 仍 住 了 两 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26530', '43', '11', '7', '然 后 对 门 徒 说 ： “ 我 们 再 往 犹 太 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26531', '43', '11', '8', '门 徒 说 ： “ 拉 比 ， 犹 太 人 近 来 要 拿 石 头 打 你 ， 你 还 往 那 里 去 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26532', '43', '11', '9', '耶 稣 回 答 说 ： “ 白 日 不 是 有 十 二 小 时 吗 ？ 人 在 白 日 走 路 ， 就 不 至 跌 倒 ， 因 为 看 见 这 世 上 的 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26533', '43', '11', '10', '若 在 黑 夜 走 路 ， 就 必 跌 倒 ， 因 为 他 没 有 光 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26534', '43', '11', '11', '耶 稣 说 了 这 话 ， 随 后 对 他 们 说 ： “ 我 们 的 朋 友 拉 撒 路 睡 了 ， 我 去 叫 醒 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26535', '43', '11', '12', '门 徒 说 ： “ 主 啊 ， 他 若 睡 了 ， 就 必 好 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26536', '43', '11', '13', '耶 稣 这 话 是 指 着 他 死 说 的 ， 他 们 却 以 为 是 说 照 常 睡 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26537', '43', '11', '14', '耶 稣 就 明 明 地 告 诉 他 们 说 ： “ 拉 撒 路 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26538', '43', '11', '15', '我 没 有 在 那 里 就 欢 喜 ， 这 是 为 你 们 的 缘 故 ， 好 叫 你 们 相 信 。 如 今 我 们 可 以 往 他 那 里 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26539', '43', '11', '16', '多 马 ， 又 称 为 低 土 马 ， 就 对 那 同 作 门 徒 的 说 ： “ 我 们 也 去 和 他 同 死 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26540', '43', '11', '17', '＜ 复 活 在 我 ， 生 命 在 我 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26541', '43', '11', '18', '伯 大 尼 离 耶 路 撒 冷 不 远 ， 约 有 六 里 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26542', '43', '11', '19', '有 好 些 犹 太 人 来 看 马 大 和 马 利 亚 ， 要 为 她 们 的 兄 弟 安 慰 她 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26543', '43', '11', '20', '马 大 听 见 耶 稣 来 了 ， 就 出 去 迎 接 他 ； 马 利 亚 却 仍 然 坐 在 家 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26544', '43', '11', '21', '马 大 对 耶 稣 说 ： “ 主 啊 ， 你 若 早 在 这 里 ， 我 兄 弟 必 不 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26545', '43', '11', '22', '就 是 现 在 ， 我 也 知 道 ， 你 无 论 向 神 求 什 么 ， 神 也 必 赐 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26546', '43', '11', '23', '耶 稣 说 ： “ 你 兄 弟 必 然 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26547', '43', '11', '24', '马 大 说 ： “ 我 知 道 在 末 日 复 活 的 时 候 ， 他 必 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26548', '43', '11', '25', '耶 稣 对 她 说 ： “ 复 活 在 我 ， 生 命 也 在 我 。 信 我 的 人 虽 然 死 了 ， 也 必 复 活 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26549', '43', '11', '26', '凡 活 着 信 我 的 人 必 永 远 不 死 。 你 信 这 话 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26550', '43', '11', '27', '马 大 说 ： “ 主 啊 ， 是 的 ， 我 信 你 是 基 督 ， 是 神 的 儿 子 ， 就 是 那 要 临 到 世 界 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26551', '43', '11', '28', '＜ 耶 稣 哭 了 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26552', '43', '11', '29', '马 利 亚 听 见 了 ， 就 急 忙 起 来 ， 到 耶 稣 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26553', '43', '11', '30', '那 时 ， 耶 稣 还 没 有 进 村 子 ， 仍 在 马 大 迎 接 他 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26554', '43', '11', '31', '那 些 同 马 利 亚 在 家 里 安 慰 她 的 犹 太 人 ， 见 她 急 忙 起 来 出 去 ， 就 跟 着 她 ， 以 为 她 要 往 坟 墓 那 里 去 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26555', '43', '11', '32', '马 利 亚 到 了 耶 稣 那 里 ， 看 见 他 ， 就 俯 伏 在 他 脚 前 ， 说 ： “ 主 啊 ， 你 若 早 在 这 里 ， 我 兄 弟 必 不 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26556', '43', '11', '33', '耶 稣 看 见 她 哭 ， 并 看 见 与 她 同 来 的 犹 太 人 也 哭 ， 就 心 里 悲 叹 ， 又 甚 忧 愁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26557', '43', '11', '34', '便 说 ： “ 你 们 把 他 安 放 在 哪 里 ？ ” 他 们 回 答 说 ： “ 请 主 来 看 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26558', '43', '11', '35', '耶 稣 哭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26559', '43', '11', '36', '犹 太 人 就 说 ： “ 你 看 他 爱 这 人 是 何 等 恳 切 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26560', '43', '11', '37', '其 中 有 人 说 ： “ 他 既 然 开 了 瞎 子 的 眼 睛 ， 岂 不 能 叫 这 人 不 死 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26561', '43', '11', '38', '＜ 拉 撒 路 复 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26562', '43', '11', '39', '耶 稣 说 ： “ 你 们 把 石 头 挪 开 。 ” 那 死 人 的 姊 姊 马 大 对 他 说 ： “ 主 啊 ， 他 现 在 必 是 臭 了 ， 因 为 他 死 了 已 经 四 天 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26563', '43', '11', '40', '耶 稣 说 ： “ 我 不 是 对 你 说 过 ， 你 若 信 ， 就 必 看 见 神 的 荣 耀 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26564', '43', '11', '41', '他 们 就 把 石 头 挪 开 。 耶 稣 举 目 望 天 ， 说 ： “ 父 啊 ， 我 感 谢 你 ， 因 为 你 已 经 听 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26565', '43', '11', '42', '我 也 知 道 你 常 听 我 ， 但 我 说 这 话 是 为 周 围 站 着 的 众 人 ， 叫 他 们 信 是 你 差 了 我 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26566', '43', '11', '43', '说 了 这 话 ， 就 大 声 呼 叫 说 ： “ 拉 撒 路 出 来 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26567', '43', '11', '44', '那 死 人 就 出 来 了 ， 手 脚 裹 着 布 ， 脸 上 包 着 手 巾 。 耶 稣 对 他 们 说 ： “ 解 开 ， 叫 他 走 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26568', '43', '11', '45', '＜ 杀 害 耶 稣 的 阴 谋 （ 太   2 6 : 1 - 5 ； 可   1 4 : 1 - 2 ； 路   2 2 : 1 - 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26569', '43', '11', '46', '但 其 中 也 有 去 见 法 利 赛 人 的 ， 将 耶 稣 所 做 的 事 告 诉 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26570', '43', '11', '47', '祭 司 长 和 法 利 赛 人 聚 集 公 会 ， 说 ： “ 这 人 行 好 些 神 迹 ， 我 们 怎 么 办 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26571', '43', '11', '48', '若 这 样 由 着 他 ， 人 人 都 要 信 他 ， 罗 马 人 也 要 来 夺 我 们 的 地 土 和 我 们 的 百 姓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26572', '43', '11', '49', '内 中 有 一 个 人 ， 名 叫 该 亚 法 ， 本 年 作 大 祭 司 ， 对 他 们 说 ： “ 你 们 不 知 道 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26573', '43', '11', '50', '独 不 想 一 个 人 替 百 姓 死 ， 免 得 通 国 灭 亡 ， 就 是 你 们 的 益 处 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26574', '43', '11', '51', '他 这 话 不 是 出 于 自 己 ， 是 因 他 本 年 作 大 祭 司 ， 所 以 预 言 耶 稣 将 要 替 这 一 国 死 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26575', '43', '11', '52', '也 不 但 替 这 一 国 死 ， 并 要 将 神 四 散 的 子 民 都 聚 集 归 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26576', '43', '11', '53', '从 那 日 起 ， 他 们 就 商 议 要 杀 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26577', '43', '11', '54', '所 以 ， 耶 稣 不 再 显 然 行 在 犹 太 人 中 间 ， 就 离 开 那 里 往 靠 近 旷 野 的 地 方 去 ， 到 了 一 座 城 ， 名 叫 以 法 莲 ， 就 在 那 里 和 门 徒 同 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26578', '43', '11', '55', '犹 太 人 的 逾 越 节 近 了 ， 有 许 多 人 从 乡 下 上 耶 路 撒 冷 去 ， 要 在 节 前 洁 净 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26579', '43', '11', '56', '他 们 就 寻 找 耶 稣 ， 站 在 殿 里 彼 此 说 ： “ 你 们 的 意 思 如 何 ， 他 不 来 过 节 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26580', '43', '11', '57', '那 时 ， 祭 司 长 和 法 利 赛 人 早 已 吩 咐 说 ， 若 有 人 知 道 耶 稣 在 哪 里 ， 就 要 报 明 ， 好 去 拿 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26581', '43', '12', '1', '＜ 在 伯 大 尼 受 膏 （ 太   2 6 : 6 - 1 3 ； 可   1 4 : 3 - 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26582', '43', '12', '2', '有 人 在 那 里 给 耶 稣 预 备 筵 席 ； 马 大 伺 候 ， 拉 撒 路 也 在 那 同 耶 稣 坐 席 的 人 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26583', '43', '12', '3', '马 利 亚 就 拿 着 一 斤 极 贵 的 真 哪 哒 香 膏 ， 抹 耶 稣 的 脚 ， 又 用 自 己 头 发 去 擦 ， 屋 里 就 满 了 膏 的 香 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26584', '43', '12', '4', '有 一 个 门 徒 ， 就 是 那 将 要 卖 耶 稣 的 加 略 人 犹 大 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26585', '43', '12', '5', '说 ： “ 这 香 膏 为 什 么 不 卖 三 十 两 银 子 赒 济 穷 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26586', '43', '12', '6', '他 说 这 话 ， 并 不 是 挂 念 穷 人 ， 乃 因 他 是 个 贼 ， 又 带 着 钱 囊 ， 常 取 其 中 所 存 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26587', '43', '12', '7', '耶 稣 说 ： “ 由 她 吧 ！ 她 是 为 我 安 葬 之 日 存 留 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26588', '43', '12', '8', '因 为 常 有 穷 人 和 你 们 同 在 ， 只 是 你 们 不 常 有 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26589', '43', '12', '9', '＜ 杀 害 拉 撒 路 的 阴 谋 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26590', '43', '12', '10', '但 祭 司 长 商 议 连 拉 撒 路 也 要 杀 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26591', '43', '12', '11', '因 有 好 些 犹 太 人 为 拉 撒 路 的 缘 故 ， 回 去 信 了 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26592', '43', '12', '12', '＜ 光 荣 地 进 耶 路 撒 冷 （ 太   2 1 : 1 - 1 1 ； 可   1 1 : 1 - 1 1 ； 路   1 9 : 2 8 - 4 0 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26593', '43', '12', '13', '就 拿 着 棕 树 枝 出 去 迎 接 他 ， 喊 着 说 ： 和 散 那 ！ 奉 主 名 来 的 以 色 列 王 是 应 当 称 颂 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26594', '43', '12', '14', '耶 稣 得 了 一 个 驴 驹 ， 就 骑 上 ， 如 经 上 所 记 的 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26595', '43', '12', '15', '锡 安 的 民 ｛ 原 文 是 女 子 ｝ 哪 ， 不 要 惧 怕 ！ 你 的 王 骑 着 驴 驹 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26596', '43', '12', '16', '这 些 事 门 徒 起 先 不 明 白 ， 等 到 耶 稣 得 了 荣 耀 以 后 才 想 起 这 话 是 指 着 他 写 的 ， 并 且 众 人 果 然 向 他 这 样 行 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26597', '43', '12', '17', '当 耶 稣 呼 唤 拉 撒 路 ， 叫 他 从 死 复 活 出 坟 墓 的 时 候 ， 同 耶 稣 在 那 里 的 众 人 就 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26598', '43', '12', '18', '众 人 因 听 见 耶 稣 行 了 这 神 迹 ， 就 去 迎 接 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26599', '43', '12', '19', '法 利 赛 人 彼 此 说 ： “ 看 哪 ， 你 们 是 徒 劳 无 益 ， 世 人 都 随 从 他 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26600', '43', '12', '20', '＜ 希 腊 人 求 见 耶 稣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26601', '43', '12', '21', '他 们 来 见 加 利 利 伯 赛 大 的 腓 力 ， 求 他 说 ： “ 先 生 ， 我 们 愿 意 见 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26602', '43', '12', '22', '腓 力 去 告 诉 安 得 烈 ， 安 得 烈 同 腓 力 去 告 诉 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26603', '43', '12', '23', '耶 稣 说 ： “ 人 子 得 荣 耀 的 时 候 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26604', '43', '12', '24', '我 实 实 在 在 地 告 诉 你 们 ， 一 粒 麦 子 不 落 在 地 里 死 了 ， 仍 旧 是 一 粒 ， 若 是 死 了 ， 就 结 出 许 多 子 粒 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26605', '43', '12', '25', '爱 惜 自 己 生 命 的 ， 就 失 丧 生 命 ； 在 这 世 上 恨 恶 自 己 生 命 的 ， 就 要 保 守 生 命 到 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26606', '43', '12', '26', '若 有 人 服 事 我 ， 就 当 跟 从 我 ； 我 在 哪 里 ， 服 事 我 的 人 也 要 在 那 里 ； 若 有 人 服 事 我 ， 我 父 必 尊 重 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26607', '43', '12', '27', '＜ 人 子 必 须 被 举 起 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26608', '43', '12', '28', '父 啊 ， 愿 你 荣 耀 你 的 名 ！ ” 当 时 就 有 声 音 从 天 上 来 ， 说 ： “ 我 已 经 荣 耀 了 我 的 名 ， 还 要 再 荣 耀 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26609', '43', '12', '29', '站 在 旁 边 的 众 人 听 见 ， 就 说 ： “ 打 雷 了 。 ” 还 有 人 说 ： “ 有 天 使 对 他 说 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26610', '43', '12', '30', '耶 稣 说 ： “ 这 声 音 不 是 为 我 ， 是 为 你 们 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26611', '43', '12', '31', '现 在 这 世 界 受 审 判 ， 这 世 界 的 王 要 被 赶 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26612', '43', '12', '32', '我 若 从 地 上 被 举 起 来 ， 就 要 吸 引 万 人 来 归 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26613', '43', '12', '33', '耶 稣 这 话 原 是 指 着 自 己 将 要 怎 样 死 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26614', '43', '12', '34', '众 人 回 答 说 ： “ 我 们 听 见 律 法 上 有 话 说 ， 基 督 是 永 存 的 ， 你 怎 么 说 ‘ 人 子 必 须 被 举 起 来 ’ 呢 ？ 这 人 子 是 谁 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26615', '43', '12', '35', '耶 稣 对 他 们 说 ： “ 光 在 你 们 中 间 还 有 不 多 的 时 候 ， 应 当 趁 着 有 光 行 走 ， 免 得 黑 暗 临 到 你 们 ； 那 在 黑 暗 里 行 走 的 ， 不 知 道 往 何 处 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26616', '43', '12', '36', '你 们 应 当 趁 着 有 光 ， 信 从 这 光 ， 使 你 们 成 为 光 明 之 子 。 ” 耶 稣 说 了 这 话 ， 就 离 开 他 们 隐 藏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26617', '43', '12', '37', '＜ 犹 太 人 的 不 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26618', '43', '12', '38', '这 是 要 应 验 先 知 以 赛 亚 的 话 ， 说 ： 主 啊 ， 我 们 所 传 的 有 谁 信 呢 ？ 主 的 膀 臂 向 谁 显 露 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26619', '43', '12', '39', '他 们 所 以 不 能 信 ， 因 为 以 赛 亚 又 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26620', '43', '12', '40', '主 叫 他 们 瞎 了 眼 ， 硬 了 心 ， 免 得 他 们 眼 睛 看 见 ， 心 里 明 白 ， 回 转 过 来 ， 我 就 医 治 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26621', '43', '12', '41', '以 赛 亚 因 为 看 见 他 的 荣 耀 ， 就 指 着 他 说 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26622', '43', '12', '42', '虽 然 如 此 ， 官 长 中 却 有 好 些 信 他 的 ， 只 因 法 利 赛 人 的 缘 故 ， 就 不 承 认 ， 恐 怕 被 赶 出 会 堂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26623', '43', '12', '43', '这 是 因 他 们 爱 人 的 荣 耀 过 于 爱 神 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26624', '43', '12', '44', '＜ 耶 稣 的 话 要 审 判 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26625', '43', '12', '45', '人 看 见 我 ， 就 是 看 见 那 差 我 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26626', '43', '12', '46', '我 到 世 上 来 ， 乃 是 光 ， 叫 凡 信 我 的 ， 不 住 在 黑 暗 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26627', '43', '12', '47', '若 有 人 听 见 我 的 话 不 遵 守 ， 我 不 审 判 他 。 我 来 本 不 是 要 审 判 世 界 ， 乃 是 要 拯 救 世 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26628', '43', '12', '48', '弃 绝 我 、 不 领 受 我 话 的 人 ， 有 审 判 他 的 ─ ─ 就 是 我 所 讲 的 道 在 末 日 要 审 判 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26629', '43', '12', '49', '因 为 我 没 有 凭 着 自 己 讲 ， 惟 有 差 我 来 的 父 已 经 给 我 命 令 ， 叫 我 说 什 么 ， 讲 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26630', '43', '12', '50', '我 也 知 道 他 的 命 令 就 是 永 生 。 故 此 ， 我 所 讲 的 话 正 是 照 着 父 对 我 所 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26631', '43', '13', '1', '＜ 耶 稣 为 门 徒 洗 脚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26632', '43', '13', '2', '吃 晚 饭 的 时 候 ， 魔 鬼 已 将 卖 耶 稣 的 意 思 放 在 西 门 的 儿 子 加 略 人 犹 大 心 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26633', '43', '13', '3', '耶 稣 知 道 父 已 将 万 有 交 在 他 手 里 ， 且 知 道 自 己 是 从 神 出 来 的 ， 又 要 归 到 神 那 里 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26634', '43', '13', '4', '就 离 席 站 起 来 ， 脱 了 衣 服 ， 拿 一 条 手 巾 束 腰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26635', '43', '13', '5', '随 后 把 水 倒 在 盆 里 ， 就 洗 门 徒 的 脚 ， 并 用 自 己 所 束 的 手 巾 擦 干 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26636', '43', '13', '6', '挨 到 西 门 ． 彼 得 ， 彼 得 对 他 说 ： “ 主 啊 ， 你 洗 我 的 脚 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26637', '43', '13', '7', '耶 稣 回 答 说 ： “ 我 所 做 的 ， 你 如 今 不 知 道 ， 后 来 必 明 白 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26638', '43', '13', '8', '彼 得 说 ： “ 你 永 不 可 洗 我 的 脚 ！ ” 耶 稣 说 ： “ 我 若 不 洗 你 ， 你 就 与 我 无 分 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26639', '43', '13', '9', '西 门 ． 彼 得 说 ： “ 主 啊 ， 不 但 我 的 脚 ， 连 手 和 头 也 要 洗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26640', '43', '13', '10', '耶 稣 说 ： “ 凡 洗 过 澡 的 人 ， 只 要 把 脚 一 洗 ， 全 身 就 干 净 了 。 你 们 是 干 净 的 ， 然 而 不 都 是 干 净 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26641', '43', '13', '11', '耶 稣 原 知 道 要 卖 他 的 是 谁 ， 所 以 说 ： “ 你 们 不 都 是 干 净 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26642', '43', '13', '12', '耶 稣 洗 完 了 他 们 的 脚 ， 就 穿 上 衣 服 ， 又 坐 下 ， 对 他 们 说 ： “ 我 向 你 们 所 做 的 ， 你 们 明 白 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26643', '43', '13', '13', '你 们 称 呼 我 夫 子 ， 称 呼 我 主 ， 你 们 说 的 不 错 ， 我 本 来 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26644', '43', '13', '14', '我 是 你 们 的 主 ， 你 们 的 夫 子 ， 尚 且 洗 你 们 的 脚 ， 你 们 也 当 彼 此 洗 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26645', '43', '13', '15', '我 给 你 们 作 了 榜 样 ， 叫 你 们 照 着 我 向 你 们 所 做 的 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26646', '43', '13', '16', '我 实 实 在 在 地 告 诉 你 们 ， 仆 人 不 能 大 于 主 人 ， 差 人 也 不 能 大 于 差 他 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26647', '43', '13', '17', '你 们 既 知 道 这 事 ， 若 是 去 行 就 有 福 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26648', '43', '13', '18', '我 这 话 不 是 指 着 你 们 众 人 说 的 ， 我 知 道 我 所 拣 选 的 是 谁 。 现 在 要 应 验 经 上 的 话 ， 说 ： ‘ 同 我 吃 饭 的 人 用 脚 踢 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26649', '43', '13', '19', '如 今 事 情 还 没 有 成 就 ， 我 要 先 告 诉 你 们 ， 叫 你 们 到 事 情 成 就 的 时 候 可 以 信 我 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26650', '43', '13', '20', '我 实 实 在 在 地 告 诉 你 们 ， 有 人 接 待 我 所 差 遣 的 ， 就 是 接 待 我 ； 接 待 我 ， 就 是 接 待 那 差 遣 我 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26651', '43', '13', '21', '＜ 预 言 自 己 将 被 出 卖 （ 太   2 6 : 2 0 - 2 5 ； 可   1 4 : 1 7 - 2 1 ； 路   2 2 : 2 1 - 2 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26652', '43', '13', '22', '门 徒 彼 此 对 看 ， 猜 不 透 所 说 的 是 谁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26653', '43', '13', '23', '有 一 个 门 徒 ， 是 耶 稣 所 爱 的 ， 侧 身 挨 近 耶 稣 的 怀 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26654', '43', '13', '24', '西 门 ． 彼 得 点 头 对 他 说 ： “ 你 告 诉 我 们 ， 主 是 指 着 谁 说 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26655', '43', '13', '25', '那 门 徒 便 就 势 靠 着 耶 稣 的 胸 膛 ， 问 他 说 ： “ 主 啊 ， 是 谁 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26656', '43', '13', '26', '耶 稣 回 答 说 ： “ 我 蘸 一 点 饼 给 谁 ， 就 是 谁 。 ” 耶 稣 就 蘸 了 一 点 饼 ， 递 给 加 略 人 西 门 的 儿 子 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26657', '43', '13', '27', '他 吃 了 以 后 ， 撒 但 就 入 了 他 的 心 。 耶 稣 便 对 他 说 ： “ 你 所 做 的 ， 快 做 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26658', '43', '13', '28', '同 席 的 人 没 有 一 个 知 道 是 为 什 么 对 他 说 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26659', '43', '13', '29', '有 人 因 犹 大 带 着 钱 囊 ， 以 为 耶 稣 是 对 他 说 ： “ 你 去 买 我 们 过 节 所 应 用 的 东 西 ” ， 或 是 叫 他 拿 什 么 赒 济 穷 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26660', '43', '13', '30', '犹 大 受 了 那 点 饼 ， 立 刻 就 出 去 。 那 时 候 是 夜 间 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26661', '43', '13', '31', '＜ 新 的 命 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26662', '43', '13', '32', '神 要 因 自 己 荣 耀 人 子 ， 并 且 要 快 快 地 荣 耀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26663', '43', '13', '33', '小 子 们 ， 我 还 有 不 多 的 时 候 与 你 们 同 在 ； 后 来 你 们 要 找 我 ， 但 我 所 去 的 地 方 你 们 不 能 到 。 这 话 我 曾 对 犹 太 人 说 过 ， 如 今 也 照 样 对 你 们 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26664', '43', '13', '34', '我 赐 给 你 们 一 条 新 命 令 ， 乃 是 叫 你 们 彼 此 相 爱 ； 我 怎 样 爱 你 们 ， 你 们 也 要 怎 样 相 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26665', '43', '13', '35', '你 们 若 有 彼 此 相 爱 的 心 ， 众 人 因 此 就 认 出 你 们 是 我 的 门 徒 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26666', '43', '13', '36', '＜ 预 言 彼 得 不 认 主 （ 太   2 6 : 3 1 - 3 5 ； 可   1 4 : 2 7 - 3 1 ； 路   2 2 : 3 1 - 3 4 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26667', '43', '13', '37', '彼 得 说 ： “ 主 啊 ， 我 为 什 么 现 在 不 能 跟 你 去 ？ 我 愿 意 为 你 舍 命 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26668', '43', '13', '38', '耶 稣 说 ： “ 你 愿 意 为 我 舍 命 吗 ？ 我 实 实 在 在 地 告 诉 你 ， 鸡 叫 以 先 ， 你 要 三 次 不 认 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26669', '43', '14', '1', '＜ 耶 稣 是 道 路 、 真 理 、 生 命 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26670', '43', '14', '2', '在 我 父 的 家 里 有 许 多 住 处 ； 若 是 没 有 ， 我 就 早 已 告 诉 你 们 了 。 我 去 原 是 为 你 们 预 备 地 方 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26671', '43', '14', '3', '我 若 去 为 你 们 预 备 了 地 方 ， 就 必 再 来 接 你 们 到 我 那 里 去 ， 我 在 哪 里 ， 叫 你 们 也 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26672', '43', '14', '4', '我 往 哪 里 去 ， 你 们 知 道 ； 那 条 路 ， 你 们 也 知 道 ｛ 有 古 卷 ： 我 往 哪 里 去 ， 你 们 知 道 那 条 路 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26673', '43', '14', '5', '多 马 对 他 说 ： “ 主 啊 ， 我 们 不 知 道 你 往 哪 里 去 ， 怎 么 知 道 那 条 路 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26674', '43', '14', '6', '耶 稣 说 ： “ 我 就 是 道 路 、 真 理 、 生 命 ； 若 不 藉 着 我 ， 没 有 人 能 到 父 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26675', '43', '14', '7', '你 们 若 认 识 我 ， 也 就 认 识 我 的 父 。 从 今 以 后 ， 你 们 认 识 他 ， 并 且 已 经 看 见 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26676', '43', '14', '8', '腓 力 对 他 说 ： “ 求 主 将 父 显 给 我 们 看 ， 我 们 就 知 足 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26677', '43', '14', '9', '耶 稣 对 他 说 ： “ 腓 力 ， 我 与 你 们 同 在 这 样 长 久 ， 你 还 不 认 识 我 吗 ？ 人 看 见 了 我 ， 就 是 看 见 了 父 ； 你 怎 么 说 ‘ 将 父 显 给 我 们 看 ’ 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26678', '43', '14', '10', '我 在 父 里 面 ， 父 在 我 里 面 ， 你 不 信 吗 ？ 我 对 你 们 所 说 的 话 ， 不 是 凭 着 自 己 说 的 ， 乃 是 住 在 我 里 面 的 父 做 他 自 己 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26679', '43', '14', '11', '你 们 当 信 我 ， 我 在 父 里 面 ， 父 在 我 里 面 ； 即 或 不 信 ， 也 当 因 我 所 做 的 事 信 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26680', '43', '14', '12', '我 实 实 在 在 地 告 诉 你 们 ， 我 所 做 的 事 ， 信 我 的 人 也 要 做 ， 并 且 要 做 比 这 更 大 的 事 ， 因 为 我 往 父 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26681', '43', '14', '13', '你 们 奉 我 的 名 无 论 求 什 么 ， 我 必 成 就 ， 叫 父 因 儿 子 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26682', '43', '14', '14', '你 们 若 奉 我 的 名 求 什 么 ， 我 必 成 就 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26683', '43', '14', '15', '＜ 应 许 赐 圣 灵 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26684', '43', '14', '16', '我 要 求 父 ， 父 就 另 外 赐 给 你 们 一 位 保 惠 师 ｛ 或 译 ： 训 慰 师 ； 下 同 ｝ ， 叫 他 永 远 与 你 们 同 在 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26685', '43', '14', '17', '就 是 真 理 的 圣 灵 ， 乃 世 人 不 能 接 受 的 ； 因 为 不 见 他 ， 也 不 认 识 他 。 你 们 却 认 识 他 ， 因 他 常 与 你 们 同 在 ， 也 要 在 你 们 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26686', '43', '14', '18', '我 不 撇 下 你 们 为 孤 儿 ， 我 必 到 你 们 这 里 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26687', '43', '14', '19', '还 有 不 多 的 时 候 ， 世 人 不 再 看 见 我 ， 你 们 却 看 见 我 ； 因 为 我 活 着 ， 你 们 也 要 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26688', '43', '14', '20', '到 那 日 ， 你 们 就 知 道 我 在 父 里 面 ， 你 们 在 我 里 面 ， 我 也 在 你 们 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26689', '43', '14', '21', '有 了 我 的 命 令 又 遵 守 的 ， 这 人 就 是 爱 我 的 ； 爱 我 的 必 蒙 我 父 爱 他 ， 我 也 要 爱 他 ， 并 且 要 向 他 显 现 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26690', '43', '14', '22', '犹 大 （ 不 是 加 略 人 犹 大 ） 问 耶 稣 说 ： “ 主 啊 ， 为 什 么 要 向 我 们 显 现 ， 不 向 世 人 显 现 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26691', '43', '14', '23', '耶 稣 回 答 说 ： “ 人 若 爱 我 ， 就 必 遵 守 我 的 道 ； 我 父 也 必 爱 他 ， 并 且 我 们 要 到 他 那 里 去 ， 与 他 同 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26692', '43', '14', '24', '不 爱 我 的 人 就 不 遵 守 我 的 道 。 你 们 所 听 见 的 道 不 是 我 的 ， 乃 是 差 我 来 之 父 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26693', '43', '14', '25', '“ 我 还 与 你 们 同 住 的 时 候 ， 已 将 这 些 话 对 你 们 说 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26694', '43', '14', '26', '但 保 惠 师 ， 就 是 父 因 我 的 名 所 要 差 来 的 圣 灵 ， 他 要 将 一 切 的 事 指 教 你 们 ， 并 且 要 叫 你 们 想 起 我 对 你 们 所 说 的 一 切 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26695', '43', '14', '27', '我 留 下 平 安 给 你 们 ； 我 将 我 的 平 安 赐 给 你 们 。 我 所 赐 的 ， 不 像 世 人 所 赐 的 。 你 们 心 里 不 要 忧 愁 ， 也 不 要 胆 怯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26696', '43', '14', '28', '你 们 听 见 我 对 你 们 说 了 ， 我 去 还 要 到 你 们 这 里 来 。 你 们 若 爱 我 ， 因 我 到 父 那 里 去 ， 就 必 喜 乐 ， 因 为 父 是 比 我 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26697', '43', '14', '29', '现 在 事 情 还 没 有 成 就 ， 我 预 先 告 诉 你 们 ， 叫 你 们 到 事 情 成 就 的 时 候 就 可 以 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26698', '43', '14', '30', '以 后 我 不 再 和 你 们 多 说 话 ， 因 为 这 世 界 的 王 将 到 。 他 在 我 里 面 是 毫 无 所 有 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26699', '43', '14', '31', '但 要 叫 世 人 知 道 我 爱 父 ， 并 且 父 怎 样 吩 咐 我 ， 我 就 怎 样 行 。 起 来 ， 我 们 走 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26700', '43', '15', '1', '＜ 耶 稣 是 真 葡 萄 树 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26701', '43', '15', '2', '凡 属 我 不 结 果 子 的 枝 子 ， 他 就 剪 去 ； 凡 结 果 子 的 ， 他 就 修 理 干 净 ， 使 枝 子 结 果 子 更 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26702', '43', '15', '3', '现 在 你 们 因 我 讲 给 你 们 的 道 ， 已 经 干 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26703', '43', '15', '4', '你 们 要 常 在 我 里 面 ， 我 也 常 在 你 们 里 面 。 枝 子 若 不 常 在 葡 萄 树 上 ， 自 己 就 不 能 结 果 子 ； 你 们 若 不 常 在 我 里 面 ， 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26704', '43', '15', '5', '我 是 葡 萄 树 ， 你 们 是 枝 子 。 常 在 我 里 面 的 ， 我 也 常 在 他 里 面 ， 这 人 就 多 结 果 子 ； 因 为 离 了 我 ， 你 们 就 不 能 做 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26705', '43', '15', '6', '人 若 不 常 在 我 里 面 ， 就 像 枝 子 丢 在 外 面 枯 干 ， 人 拾 起 来 ， 扔 在 火 里 烧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26706', '43', '15', '7', '你 们 若 常 在 我 里 面 ， 我 的 话 也 常 在 你 们 里 面 ， 凡 你 们 所 愿 意 的 ， 祈 求 ， 就 给 你 们 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26707', '43', '15', '8', '你 们 多 结 果 子 ， 我 父 就 因 此 得 荣 耀 ， 你 们 也 就 是 我 的 门 徒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26708', '43', '15', '9', '我 爱 你 们 ， 正 如 父 爱 我 一 样 ； 你 们 要 常 在 我 的 爱 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26709', '43', '15', '10', '你 们 若 遵 守 我 的 命 令 ， 就 常 在 我 的 爱 里 ， 正 如 我 遵 守 了 我 父 的 命 令 ， 常 在 他 的 爱 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26710', '43', '15', '11', '“ 这 些 事 我 已 经 对 你 们 说 了 ， 是 要 叫 我 的 喜 乐 存 在 你 们 心 里 ， 并 叫 你 们 的 喜 乐 可 以 满 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26711', '43', '15', '12', '你 们 要 彼 此 相 爱 ， 像 我 爱 你 们 一 样 ； 这 就 是 我 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26712', '43', '15', '13', '人 为 朋 友 舍 命 ， 人 的 爱 心 没 有 比 这 个 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26713', '43', '15', '14', '你 们 若 遵 行 我 所 吩 咐 的 ， 就 是 我 的 朋 友 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26714', '43', '15', '15', '以 后 我 不 再 称 你 们 为 仆 人 ， 因 仆 人 不 知 道 主 人 所 做 的 事 。 我 乃 称 你 们 为 朋 友 ； 因 我 从 我 父 所 听 见 的 ， 已 经 都 告 诉 你 们 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26715', '43', '15', '16', '不 是 你 们 拣 选 了 我 ， 是 我 拣 选 了 你 们 ， 并 且 分 派 你 们 去 结 果 子 ， 叫 你 们 的 果 子 常 存 ， 使 你 们 奉 我 的 名 ， 无 论 向 父 求 什 么 ， 他 就 赐 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26716', '43', '15', '17', '我 这 样 吩 咐 你 们 ， 是 要 叫 你 们 彼 此 相 爱 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26717', '43', '15', '18', '＜ 世 人 的 憎 恨 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26718', '43', '15', '19', '你 们 若 属 世 界 ， 世 界 必 爱 属 自 己 的 ； 只 因 你 们 不 属 世 界 ， 乃 是 我 从 世 界 中 拣 选 了 你 们 ， 所 以 世 界 就 恨 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26719', '43', '15', '20', '你 们 要 记 念 我 从 前 对 你 们 所 说 的 话 ： ‘ 仆 人 不 能 大 于 主 人 。 ’ 他 们 若 逼 迫 了 我 ， 也 要 逼 迫 你 们 ； 若 遵 守 了 我 的 话 ， 也 要 遵 守 你 们 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26720', '43', '15', '21', '但 他 们 因 我 的 名 要 向 你 们 行 这 一 切 的 事 ， 因 为 他 们 不 认 识 那 差 我 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26721', '43', '15', '22', '我 若 没 有 来 教 训 他 们 ， 他 们 就 没 有 罪 ； 但 如 今 他 们 的 罪 无 可 推 诿 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26722', '43', '15', '23', '恨 我 的 ， 也 恨 我 的 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26723', '43', '15', '24', '我 若 没 有 在 他 们 中 间 行 过 别 人 未 曾 行 的 事 ， 他 们 就 没 有 罪 ； 但 如 今 连 我 与 我 的 父 ， 他 们 也 看 见 也 恨 恶 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26724', '43', '15', '25', '这 要 应 验 他 们 律 法 上 所 写 的 话 ， 说 ： ‘ 他 们 无 故 地 恨 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26725', '43', '15', '26', '但 我 要 从 父 那 里 差 保 惠 师 来 ， 就 是 从 父 出 来 真 理 的 圣 灵 ； 他 来 了 ， 就 要 为 我 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26726', '43', '15', '27', '你 们 也 要 作 见 证 ， 因 为 你 们 从 起 头 就 与 我 同 在 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26727', '43', '16', '1', '“ 我 已 将 这 些 事 告 诉 你 们 ， 使 你 们 不 至 于 跌 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26728', '43', '16', '2', '人 要 把 你 们 赶 出 会 堂 ， 并 且 时 候 将 到 ， 凡 杀 你 们 的 就 以 为 是 事 奉 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26729', '43', '16', '3', '他 们 这 样 行 ， 是 因 未 曾 认 识 父 ， 也 未 曾 认 识 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26730', '43', '16', '4', '我 将 这 事 告 诉 你 们 ， 是 叫 你 们 到 了 时 候 可 以 想 起 我 对 你 们 说 过 了 。 ” 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26731', '43', '16', '5', '现 今 我 往 差 我 来 的 父 那 里 去 ， 你 们 中 间 并 没 有 人 问 我 ： ‘ 你 往 哪 里 去 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26732', '43', '16', '6', '只 因 我 将 这 事 告 诉 你 们 ， 你 们 就 满 心 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26733', '43', '16', '7', '然 而 ， 我 将 真 情 告 诉 你 们 ， 我 去 是 与 你 们 有 益 的 ； 我 若 不 去 ， 保 惠 师 就 不 到 你 们 这 里 来 ； 我 若 去 ， 就 差 他 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26734', '43', '16', '8', '他 既 来 了 ， 就 要 叫 世 人 为 罪 、 为 义 、 为 审 判 ， 自 己 责 备 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26735', '43', '16', '9', '为 罪 ， 是 因 他 们 不 信 我 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26736', '43', '16', '10', '为 义 ， 是 因 我 往 父 那 里 去 ， 你 们 就 不 再 见 我 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26737', '43', '16', '11', '为 审 判 ， 是 因 这 世 界 的 王 受 了 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26738', '43', '16', '12', '“ 我 还 有 好 些 事 要 告 诉 你 们 ， 但 你 们 现 在 担 当 不 了 ｛ 或 译 ： 不 能 领 会 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26739', '43', '16', '13', '只 等 真 理 的 圣 灵 来 了 ， 他 要 引 导 你 们 明 白 ｛ 原 文 是 进 入 ｝ 一 切 的 真 理 ； 因 为 他 不 是 凭 自 己 说 的 ， 乃 是 把 他 所 听 见 的 都 说 出 来 ， 并 要 把 将 来 的 事 告 诉 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26740', '43', '16', '14', '他 要 荣 耀 我 ， 因 为 他 要 将 受 于 我 的 告 诉 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26741', '43', '16', '15', '凡 父 所 有 的 ， 都 是 我 的 ； 所 以 我 说 ， 他 要 将 受 于 我 的 告 诉 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26742', '43', '16', '16', '＜ 忧 愁 变 为 喜 乐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26743', '43', '16', '17', '有 几 个 门 徒 就 彼 此 说 ： “ 他 对 我 们 说 ： ‘ 等 不 多 时 ， 你 们 就 不 得 见 我 ； 再 等 不 多 时 ， 你 们 还 要 见 我 ’ ； 又 说 ： ‘ 因 我 往 父 那 里 去 。 ’ 这 是 什 么 意 思 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26744', '43', '16', '18', '门 徒 彼 此 说 ： “ 他 说 ‘ 等 不 多 时 ’ 到 底 是 什 么 意 思 呢 ？ 我 们 不 明 白 他 所 说 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26745', '43', '16', '19', '耶 稣 看 出 他 们 要 问 他 ， 就 说 ： “ 我 说 ‘ 等 不 多 时 ， 你 们 就 不 得 见 我 ； 再 等 不 多 时 ， 你 们 还 要 见 我 ’ ， 你 们 为 这 话 彼 此 相 问 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26746', '43', '16', '20', '我 实 实 在 在 地 告 诉 你 们 ， 你 们 将 要 痛 哭 、 哀 号 ， 世 人 倒 要 喜 乐 ； 你 们 将 要 忧 愁 ， 然 而 你 们 的 忧 愁 要 变 为 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26747', '43', '16', '21', '妇 人 生 产 的 时 候 就 忧 愁 ， 因 为 她 的 时 候 到 了 ； 既 生 了 孩 子 ， 就 不 再 记 念 那 苦 楚 ， 因 为 欢 喜 世 上 生 了 一 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26748', '43', '16', '22', '你 们 现 在 也 是 忧 愁 ， 但 我 要 再 见 你 们 ， 你 们 的 心 就 喜 乐 了 ； 这 喜 乐 也 没 有 人 能 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26749', '43', '16', '23', '到 那 日 ， 你 们 什 么 也 就 不 问 我 了 。 我 实 实 在 在 地 告 诉 你 们 ， 你 们 若 向 父 求 什 么 ， 他 必 因 我 的 名 赐 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26750', '43', '16', '24', '向 来 你 们 没 有 奉 我 的 名 求 什 么 ， 如 今 你 们 求 ， 就 必 得 着 ， 叫 你 们 的 喜 乐 可 以 满 足 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26751', '43', '16', '25', '＜ 我 已 经 胜 过 世 界 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26752', '43', '16', '26', '到 那 日 ， 你 们 要 奉 我 的 名 祈 求 ； 我 并 不 对 你 们 说 ， 我 要 为 你 们 求 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26753', '43', '16', '27', '父 自 己 爱 你 们 ； 因 为 你 们 已 经 爱 我 ， 又 信 我 是 从 父 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26754', '43', '16', '28', '我 从 父 出 来 ， 到 了 世 界 ； 我 又 离 开 世 界 ， 往 父 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26755', '43', '16', '29', '门 徒 说 ： “ 如 今 你 是 明 说 ， 并 不 用 比 喻 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26756', '43', '16', '30', '现 在 我 们 晓 得 你 凡 事 都 知 道 ， 也 不 用 人 问 你 ， 因 此 我 们 信 你 是 从 神 出 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26757', '43', '16', '31', '耶 稣 说 ： “ 现 在 你 们 信 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26758', '43', '16', '32', '看 哪 ， 时 候 将 到 ， 且 是 已 经 到 了 ， 你 们 要 分 散 ， 各 归 自 己 的 地 方 去 ， 留 下 我 独 自 一 人 ； 其 实 我 不 是 独 自 一 人 ， 因 为 有 父 与 我 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26759', '43', '16', '33', '我 将 这 些 事 告 诉 你 们 ， 是 要 叫 你 们 在 我 里 面 有 平 安 。 在 世 上 ， 你 们 有 苦 难 ； 但 你 们 可 以 放 心 ， 我 已 经 胜 了 世 界 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26760', '43', '17', '1', '＜ 耶 稣 的 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26761', '43', '17', '2', '正 如 你 曾 赐 给 他 权 柄 管 理 凡 有 血 气 的 ， 叫 他 将 永 生 赐 给 你 所 赐 给 他 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26762', '43', '17', '3', '认 识 你 ─ ─ 独 一 的 真 神 ， 并 且 认 识 你 所 差 来 的 耶 稣 基 督 ， 这 就 是 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26763', '43', '17', '4', '我 在 地 上 已 经 荣 耀 你 ， 你 所 托 付 我 的 事 ， 我 已 成 全 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26764', '43', '17', '5', '父 啊 ， 现 在 求 你 使 我 同 你 享 荣 耀 ， 就 是 未 有 世 界 以 先 ， 我 同 你 所 有 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26765', '43', '17', '6', '“ 你 从 世 上 赐 给 我 的 人 ， 我 已 将 你 的 名 显 明 与 他 们 。 他 们 本 是 你 的 ， 你 将 他 们 赐 给 我 ， 他 们 也 遵 守 了 你 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26766', '43', '17', '7', '如 今 他 们 知 道 ， 凡 你 所 赐 给 我 的 ， 都 是 从 你 那 里 来 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26767', '43', '17', '8', '因 为 你 所 赐 给 我 的 道 ， 我 已 经 赐 给 他 们 ， 他 们 也 领 受 了 ， 又 确 实 知 道 ， 我 是 从 你 出 来 的 ， 并 且 信 你 差 了 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26768', '43', '17', '9', '我 为 他 们 祈 求 ， 不 为 世 人 祈 求 ， 却 为 你 所 赐 给 我 的 人 祈 求 ， 因 他 们 本 是 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26769', '43', '17', '10', '凡 是 我 的 ， 都 是 你 的 ； 你 的 也 是 我 的 ， 并 且 我 因 他 们 得 了 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26770', '43', '17', '11', '从 今 以 后 ， 我 不 在 世 上 ， 他 们 却 在 世 上 ； 我 往 你 那 里 去 。 圣 父 啊 ， 求 你 因 你 所 赐 给 我 的 名 保 守 他 们 ， 叫 他 们 合 而 为 一 像 我 们 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26771', '43', '17', '12', '我 与 他 们 同 在 的 时 候 ， 因 你 所 赐 给 我 的 名 保 守 了 他 们 ， 我 也 护 卫 了 他 们 ； 其 中 除 了 那 灭 亡 之 子 ， 没 有 一 个 灭 亡 的 ， 好 叫 经 上 的 话 得 应 验 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26772', '43', '17', '13', '现 在 我 往 你 那 里 去 ， 我 还 在 世 上 说 这 话 ， 是 叫 他 们 心 里 充 满 我 的 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26773', '43', '17', '14', '我 已 将 你 的 道 赐 给 他 们 。 世 界 又 恨 他 们 ； 因 为 他 们 不 属 世 界 ， 正 如 我 不 属 世 界 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26774', '43', '17', '15', '我 不 求 你 叫 他 们 离 开 世 界 ， 只 求 你 保 守 他 们 脱 离 那 恶 者 ｛ 或 译 ： 脱 离 罪 恶 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26775', '43', '17', '16', '他 们 不 属 世 界 ， 正 如 我 不 属 世 界 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26776', '43', '17', '17', '求 你 用 真 理 使 他 们 成 圣 ； 你 的 道 就 是 真 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26777', '43', '17', '18', '你 怎 样 差 我 到 世 上 ， 我 也 照 样 差 他 们 到 世 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26778', '43', '17', '19', '我 为 他 们 的 缘 故 ， 自 己 分 别 为 圣 ， 叫 他 们 也 因 真 理 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26779', '43', '17', '20', '“ 我 不 但 为 这 些 人 祈 求 ， 也 为 那 些 因 他 们 的 话 信 我 的 人 祈 求 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26780', '43', '17', '21', '使 他 们 都 合 而 为 一 。 正 如 你 父 在 我 里 面 ， 我 在 你 里 面 ， 使 他 们 也 在 我 们 里 面 ， 叫 世 人 可 以 信 你 差 了 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26781', '43', '17', '22', '你 所 赐 给 我 的 荣 耀 ， 我 已 赐 给 他 们 ， 使 他 们 合 而 为 一 ， 像 我 们 合 而 为 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26782', '43', '17', '23', '我 在 他 们 里 面 ， 你 在 我 里 面 ， 使 他 们 完 完 全 全 地 合 而 为 一 ， 叫 世 人 知 道 你 差 了 我 来 ， 也 知 道 你 爱 他 们 如 同 爱 我 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26783', '43', '17', '24', '父 啊 ， 我 在 哪 里 ， 愿 你 所 赐 给 我 的 人 也 同 我 在 那 里 ， 叫 他 们 看 见 你 所 赐 给 我 的 荣 耀 ； 因 为 创 立 世 界 以 前 ， 你 已 经 爱 我 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26784', '43', '17', '25', '公 义 的 父 啊 ， 世 人 未 曾 认 识 你 ， 我 却 认 识 你 ； 这 些 人 也 知 道 你 差 了 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26785', '43', '17', '26', '我 已 将 你 的 名 指 示 他 们 ， 还 要 指 示 他 们 ， 使 你 所 爱 我 的 爱 在 他 们 里 面 ， 我 也 在 他 们 里 面 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26786', '43', '18', '1', '＜ 耶 稣 被 捕 （ 太   2 6 : 4 7 - 5 6 ； 可   1 4 : 4 3 - 5 0 ； 路   2 2 : 4 7 - 5 3 ） ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26787', '43', '18', '2', '卖 耶 稣 的 犹 大 也 知 道 那 地 方 ， 因 为 耶 稣 和 门 徒 屡 次 上 那 里 去 聚 集 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26788', '43', '18', '3', '犹 大 领 了 一 队 兵 ， 和 祭 司 长 并 法 利 赛 人 的 差 役 ， 拿 着 灯 笼 、 火 把 、 兵 器 ， 就 来 到 园 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26789', '43', '18', '4', '耶 稣 知 道 将 要 临 到 自 己 的 一 切 事 ， 就 出 来 对 他 们 说 ： “ 你 们 找 谁 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26790', '43', '18', '5', '他 们 回 答 说 ： “ 找 拿 撒 勒 人 耶 稣 。 ” 耶 稣 说 ： “ 我 就 是 ！ ” 卖 他 的 犹 大 也 同 他 们 站 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26791', '43', '18', '6', '耶 稣 一 说 “ 我 就 是 ” ， 他 们 就 退 后 倒 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26792', '43', '18', '7', '他 又 问 他 们 说 ： “ 你 们 找 谁 ？ ” 他 们 说 ： “ 找 拿 撒 勒 人 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26793', '43', '18', '8', '耶 稣 说 ： “ 我 已 经 告 诉 你 们 ， 我 就 是 。 你 们 若 找 我 ， 就 让 这 些 人 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26794', '43', '18', '9', '这 要 应 验 耶 稣 从 前 的 话 ， 说 ： “ 你 所 赐 给 我 的 人 ， 我 没 有 失 落 一 个 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26795', '43', '18', '10', '西 门 ． 彼 得 带 着 一 把 刀 ， 就 拔 出 来 ， 将 大 祭 司 的 仆 人 砍 了 一 刀 ， 削 掉 他 的 右 耳 ； 那 仆 人 名 叫 马 勒 古 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26796', '43', '18', '11', '耶 稣 就 对 彼 得 说 ： “ 收 刀 入 鞘 吧 ， 我 父 所 给 我 的 那 杯 ， 我 岂 可 不 喝 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26797', '43', '18', '12', '＜ 耶 稣 被 带 到 亚 那 面 前 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26798', '43', '18', '13', '先 带 到 亚 那 面 前 ， 因 为 亚 那 是 本 年 作 大 祭 司 该 亚 法 的 岳 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26799', '43', '18', '14', '这 该 亚 法 就 是 从 前 向 犹 太 人 发 议 论 说 “ 一 个 人 替 百 姓 死 是 有 益 的 ” 那 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26800', '43', '18', '15', '＜ 彼 得 不 认 耶 稣 （ 太   2 6 : 6 9 - 7 0 ； 可   1 4 : 6 6 - 6 8 ； 路   2 2 : 5 5 - 5 7 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26801', '43', '18', '16', '彼 得 却 站 在 门 外 。 大 祭 司 所 认 识 的 那 个 门 徒 出 来 ， 和 看 门 的 使 女 说 了 一 声 ， 就 领 彼 得 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26802', '43', '18', '17', '那 看 门 的 使 女 对 彼 得 说 ： “ 你 不 也 是 这 人 的 门 徒 吗 ？ ” 他 说 ： “ 我 不 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26803', '43', '18', '18', '仆 人 和 差 役 因 为 天 冷 ， 就 生 了 炭 火 ， 站 在 那 里 烤 火 ； 彼 得 也 同 他 们 站 着 烤 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26804', '43', '18', '19', '＜ 大 祭 司 盘 问 耶 稣 （ 太   2 6 : 5 9 - 6 6 ； 可   1 4 : 5 5 - 6 4 ； 路   2 2 : 6 6 - 7 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26805', '43', '18', '20', '耶 稣 回 答 说 ： “ 我 从 来 是 明 明 地 对 世 人 说 话 。 我 常 在 会 堂 和 殿 里 ， 就 是 犹 太 人 聚 集 的 地 方 教 训 人 ； 我 在 暗 地 里 并 没 有 说 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26806', '43', '18', '21', '你 为 什 么 问 我 呢 ？ 可 以 问 那 听 见 的 人 ， 我 对 他 们 说 的 是 什 么 ； 我 所 说 的 ， 他 们 都 知 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26807', '43', '18', '22', '耶 稣 说 了 这 话 ， 旁 边 站 着 的 一 个 差 役 用 手 掌 打 他 ， 说 ： “ 你 这 样 回 答 大 祭 司 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26808', '43', '18', '23', '耶 稣 说 ： “ 我 若 说 的 不 是 ， 你 可 以 指 证 那 不 是 ； 我 若 说 的 是 ， 你 为 什 么 打 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26809', '43', '18', '24', '亚 那 就 把 耶 稣 解 到 大 祭 司 该 亚 法 那 里 ， 仍 是 捆 着 解 去 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26810', '43', '18', '25', '＜ 彼 得 再 次 不 认 耶 稣 （ 太   2 6 : 7 1 - 7 5 ； 可   1 4 : 6 9 - 7 2 ； 路   2 2 : 5 8 - 6 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26811', '43', '18', '26', '有 大 祭 司 的 一 个 仆 人 ， 是 彼 得 削 掉 耳 朵 那 人 的 亲 属 ， 说 ： “ 我 不 是 看 见 你 同 他 在 园 子 里 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26812', '43', '18', '27', '彼 得 又 不 承 认 。 立 时 鸡 就 叫 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26813', '43', '18', '28', '＜ 耶 稣 在 彼 拉 多 面 前 受 审 （ 太   2 7 : 1 - 2 , 1 1 - 1 4 ； 可   1 5 : 1 - 5 ； 路   2 3 : 1 - 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26814', '43', '18', '29', '彼 拉 多 就 出 来 ， 到 他 们 那 里 ， 说 ： “ 你 们 告 这 人 是 为 什 么 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26815', '43', '18', '30', '他 们 回 答 说 ： “ 这 人 若 不 是 作 恶 的 ， 我 们 就 不 把 他 交 给 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26816', '43', '18', '31', '彼 拉 多 说 ： “ 你 们 自 己 带 他 去 ， 按 着 你 们 的 律 法 审 问 他 吧 。 ” 犹 太 人 说 ： “ 我 们 没 有 杀 人 的 权 柄 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26817', '43', '18', '32', '这 要 应 验 耶 稣 所 说 自 己 将 要 怎 样 死 的 话 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26818', '43', '18', '33', '彼 拉 多 又 进 了 衙 门 ， 叫 耶 稣 来 ， 对 他 说 ： “ 你 是 犹 太 人 的 王 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26819', '43', '18', '34', '耶 稣 回 答 说 ： “ 这 话 是 你 自 己 说 的 ， 还 是 别 人 论 我 对 你 说 的 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26820', '43', '18', '35', '彼 拉 多 说 ： “ 我 岂 是 犹 太 人 呢 ？ 你 本 国 的 人 和 祭 司 长 把 你 交 给 我 。 你 做 了 什 么 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26821', '43', '18', '36', '耶 稣 回 答 说 ： “ 我 的 国 不 属 这 世 界 ； 我 的 国 若 属 这 世 界 ， 我 的 臣 仆 必 要 争 战 ， 使 我 不 至 于 被 交 给 犹 太 人 。 只 是 我 的 国 不 属 这 世 界 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26822', '43', '18', '37', '彼 拉 多 就 对 他 说 ： “ 这 样 ， 你 是 王 吗 ？ ” 耶 稣 回 答 说 ： “ 你 说 我 是 王 。 我 为 此 而 生 ， 也 为 此 来 到 世 间 ， 特 为 给 真 理 作 见 证 。 凡 属 真 理 的 人 就 听 我 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26823', '43', '18', '38', '＜ 耶 稣 被 判 死 刑 （ 太   2 7 : 1 5 - 3 1 ； 可   1 5 : 6 - 2 0 ； 路   2 3 : 1 3 - 2 5 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26824', '43', '18', '39', '但 你 们 有 个 规 矩 ， 在 逾 越 节 要 我 给 你 们 释 放 一 个 人 ， 你 们 要 我 给 你 们 释 放 犹 太 人 的 王 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26825', '43', '18', '40', '他 们 又 喊 着 说 ： “ 不 要 这 人 ， 要 巴 拉 巴 ！ ” 这 巴 拉 巴 是 个 强 盗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26826', '43', '19', '1', '当 下 彼 拉 多 将 耶 稣 鞭 打 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26827', '43', '19', '2', '兵 丁 用 荆 棘 编 做 冠 冕 戴 在 他 头 上 ， 给 他 穿 上 紫 袍 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26828', '43', '19', '3', '又 挨 近 他 ， 说 ： “ 恭 喜 ， 犹 太 人 的 王 啊 ！ ” 他 们 就 用 手 掌 打 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26829', '43', '19', '4', '彼 拉 多 又 出 来 对 众 人 说 ： “ 我 带 他 出 来 见 你 们 ， 叫 你 们 知 道 我 查 不 出 他 有 什 么 罪 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26830', '43', '19', '5', '耶 稣 出 来 ， 戴 着 荆 棘 冠 冕 ， 穿 着 紫 袍 。 彼 拉 多 对 他 们 说 ： “ 你 们 看 这 个 人 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26831', '43', '19', '6', '祭 司 长 和 差 役 看 见 他 ， 就 喊 着 说 ： “ 钉 他 十 字 架 ！ 钉 他 十 字 架 ！ ” 彼 拉 多 说 ： “ 你 们 自 己 把 他 钉 十 字 架 吧 ！ 我 查 不 出 他 有 什 么 罪 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26832', '43', '19', '7', '犹 太 人 回 答 说 ： “ 我 们 有 律 法 ， 按 那 律 法 ， 他 是 该 死 的 ， 因 他 以 自 己 为 神 的 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26833', '43', '19', '8', '彼 拉 多 听 见 这 话 ， 越 发 害 怕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26834', '43', '19', '9', '又 进 衙 门 ， 对 耶 稣 说 ： “ 你 是 哪 里 来 的 ？ ” 耶 稣 却 不 回 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26835', '43', '19', '10', '彼 拉 多 说 ： “ 你 不 对 我 说 话 吗 ？ 你 岂 不 知 我 有 权 柄 释 放 你 ， 也 有 权 柄 把 你 钉 十 字 架 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26836', '43', '19', '11', '耶 稣 回 答 说 ： “ 若 不 是 从 上 头 赐 给 你 的 ， 你 就 毫 无 权 柄 办 我 。 所 以 ， 把 我 交 给 你 的 那 人 罪 更 重 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26837', '43', '19', '12', '从 此 ， 彼 拉 多 想 要 释 放 耶 稣 ， 无 奈 犹 太 人 喊 着 说 ： “ 你 若 释 放 这 个 人 ， 就 不 是 凯 撒 的 忠 臣 ｛ 原 文 是 朋 友 ｝ 。 凡 以 自 己 为 王 的 ， 就 是 背 叛 凯 撒 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26838', '43', '19', '13', '彼 拉 多 听 见 这 话 ， 就 带 耶 稣 出 来 ， 到 了 一 个 地 方 ， 名 叫 “ 铺 华 石 处 ” ， 希 伯 来 话 叫 厄 巴 大 ， 就 在 那 里 坐 堂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26839', '43', '19', '14', '那 日 是 预 备 逾 越 节 的 日 子 ， 约 有 午 正 。 彼 拉 多 对 犹 太 人 说 ： “ 看 哪 ， 这 是 你 们 的 王 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26840', '43', '19', '15', '他 们 喊 着 说 ： “ 除 掉 他 ！ 除 掉 他 ！ 钉 他 在 十 字 架 上 ！ ” 彼 拉 多 说 ： “ 我 可 以 把 你 们 的 王 钉 十 字 架 吗 ？ ” 祭 司 长 回 答 说 ： “ 除 了 凯 撒 ， 我 们 没 有 王 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26841', '43', '19', '16', '于 是 彼 拉 多 将 耶 稣 交 给 他 们 去 钉 十 字 架 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26842', '43', '19', '17', '＜ 耶 稣 被 钉 十 字 架 （ 太   2 7 : 3 2 - 4 4 ； 可   1 5 : 2 1 - 3 2 ； 路   2 3 : 2 6 - 4 3 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26843', '43', '19', '18', '他 们 就 在 那 里 钉 他 在 十 字 架 上 ， 还 有 两 个 人 和 他 一 同 钉 着 ， 一 边 一 个 ， 耶 稣 在 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26844', '43', '19', '19', '彼 拉 多 又 用 牌 子 写 了 一 个 名 号 ， 安 在 十 字 架 上 ， 写 的 是 ： “ 犹 太 人 的 王 ， 拿 撒 勒 人 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26845', '43', '19', '20', '有 许 多 犹 太 人 念 这 名 号 ； 因 为 耶 稣 被 钉 十 字 架 的 地 方 与 城 相 近 ， 并 且 是 用 希 伯 来 、 罗 马 、 希 腊 三 样 文 字 写 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26846', '43', '19', '21', '犹 太 人 的 祭 司 长 就 对 彼 拉 多 说 ： “ 不 要 写 ‘ 犹 太 人 的 王 ’ ， 要 写 ‘ 他 自 己 说 ： 我 是 犹 太 人 的 王 ’ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26847', '43', '19', '22', '彼 拉 多 说 ： “ 我 所 写 的 ， 我 已 经 写 上 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26848', '43', '19', '23', '兵 丁 既 然 将 耶 稣 钉 在 十 字 架 上 ， 就 拿 他 的 衣 服 分 为 四 分 ， 每 兵 一 分 ； 又 拿 他 的 里 衣 ， 这 件 里 衣 原 来 没 有 缝 儿 ， 是 上 下 一 片 织 成 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26849', '43', '19', '24', '他 们 就 彼 此 说 ： “ 我 们 不 要 撕 开 ， 只 要 拈 阄 ， 看 谁 得 着 。 ” 这 要 应 验 经 上 的 话 说 ： 他 们 分 了 我 的 外 衣 ， 为 我 的 里 衣 拈 阄 。 兵 丁 果 然 做 了 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26850', '43', '19', '25', '站 在 耶 稣 十 字 架 旁 边 的 ， 有 他 母 亲 与 他 母 亲 的 姊 妹 ， 并 革 罗 罢 的 妻 子 马 利 亚 ， 和 抹 大 拉 的 马 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26851', '43', '19', '26', '耶 稣 见 母 亲 和 他 所 爱 的 那 门 徒 站 在 旁 边 ， 就 对 他 母 亲 说 ： “ 母 亲 ｛ 原 文 是 妇 人 ｝ ， 看 ， 你 的 儿 子 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26852', '43', '19', '27', '又 对 那 门 徒 说 ： “ 看 ， 你 的 母 亲 ！ ” 从 此 ， 那 门 徒 就 接 她 到 自 己 家 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26853', '43', '19', '28', '＜ 耶 稣 的 死 （ 太   2 7 : 4 5 - 5 6 ； 可   1 5 : 3 3 - 4 1 ； 路   2 3 : 4 4 - 4 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26854', '43', '19', '29', '有 一 个 器 皿 盛 满 了 醋 ， 放 在 那 里 ； 他 们 就 拿 海 绒 蘸 满 了 醋 ， 绑 在 牛 膝 草 上 ， 送 到 他 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26855', '43', '19', '30', '耶 稣 尝 ｛ 原 文 是 受 ｝ 了 那 醋 ， 就 说 ： “ 成 了 ！ ” 便 低 下 头 ， 将 灵 魂 交 付 神 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26856', '43', '19', '31', '＜ 肋 旁 被 扎 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26857', '43', '19', '32', '于 是 兵 丁 来 ， 把 头 一 个 人 的 腿 ， 并 与 耶 稣 同 钉 第 二 个 人 的 腿 ， 都 打 断 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26858', '43', '19', '33', '只 是 来 到 耶 稣 那 里 ， 见 他 已 经 死 了 ， 就 不 打 断 他 的 腿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26859', '43', '19', '34', '惟 有 一 个 兵 拿 枪 扎 他 的 肋 旁 ， 随 即 有 血 和 水 流 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26860', '43', '19', '35', '看 见 这 事 的 那 人 就 作 见 证 ─ ─ 他 的 见 证 也 是 真 的 ， 并 且 他 知 道 自 己 所 说 的 是 真 的 ─ ─ 叫 你 们 也 可 以 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26861', '43', '19', '36', '这 些 事 成 了 ， 为 要 应 验 经 上 的 话 说 ： “ 他 的 骨 头 一 根 也 不 可 折 断 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26862', '43', '19', '37', '经 上 又 有 一 句 说 ： “ 他 们 要 仰 望 自 己 所 扎 的 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26863', '43', '19', '38', '＜ 耶 稣 的 安 葬 （ 太   2 7 : 5 7 - 6 1 ； 可   1 5 : 4 2 - 4 7 ； 路   2 3 : 5 0 - 5 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26864', '43', '19', '39', '又 有 尼 哥 德 慕 ， 就 是 先 前 夜 里 去 见 耶 稣 的 ， 带 着 没 药 和 沉 香 约 有 一 百 斤 前 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26865', '43', '19', '40', '他 们 就 照 犹 太 人 殡 葬 的 规 矩 ， 把 耶 稣 的 身 体 用 细 麻 布 加 上 香 料 裹 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26866', '43', '19', '41', '在 耶 稣 钉 十 字 架 的 地 方 有 一 个 园 子 ， 园 子 里 有 一 座 新 坟 墓 ， 是 从 来 没 有 葬 过 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26867', '43', '19', '42', '只 因 是 犹 太 人 的 预 备 日 ， 又 因 那 坟 墓 近 ， 他 们 就 把 耶 稣 安 放 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26868', '43', '20', '1', '＜ 耶 稣 复 活 （ 太   2 8 : 1 - 8 ； 可   1 6 : 1 - 8 ； 路   2 4 : 1 - 1 2 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26869', '43', '20', '2', '就 跑 来 见 西 门 ． 彼 得 和 耶 稣 所 爱 的 那 个 门 徒 ， 对 他 们 说 ： “ 有 人 把 主 从 坟 墓 里 挪 了 去 ， 我 们 不 知 道 放 在 哪 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26870', '43', '20', '3', '彼 得 和 那 门 徒 就 出 来 ， 往 坟 墓 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26871', '43', '20', '4', '两 个 人 同 跑 ， 那 门 徒 比 彼 得 跑 的 更 快 ， 先 到 了 坟 墓 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26872', '43', '20', '5', '低 头 往 里 看 ， 就 见 细 麻 布 还 放 在 那 里 ， 只 是 没 有 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26873', '43', '20', '6', '西 门 ． 彼 得 随 后 也 到 了 ， 进 坟 墓 里 去 ， 就 看 见 细 麻 布 还 放 在 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26874', '43', '20', '7', '又 看 见 耶 稣 的 裹 头 巾 没 有 和 细 麻 布 放 在 一 处 ， 是 另 在 一 处 卷 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26875', '43', '20', '8', '先 到 坟 墓 的 那 门 徒 也 进 去 ， 看 见 就 信 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26876', '43', '20', '9', '（ 因 为 他 们 还 不 明 白 圣 经 的 意 思 ， 就 是 耶 稣 必 要 从 死 里 复 活 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26877', '43', '20', '10', '于 是 两 个 门 徒 回 自 己 的 住 处 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26878', '43', '20', '11', '＜ 向 抹 大 拉 的 马 利 亚 显 现 （ 太   2 8 : 9 - 1 0 ； 可   1 6 : 9 - 1 1 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26879', '43', '20', '12', '就 见 两 个 天 使 ， 穿 着 白 衣 ， 在 安 放 耶 稣 身 体 的 地 方 坐 着 ， 一 个 在 头 ， 一 个 在 脚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26880', '43', '20', '13', '天 使 对 他 她 说 ： “ 妇 人 ， 你 为 什 么 哭 ？ ” 她 说 ： “ 因 为 有 人 把 我 主 挪 了 去 ， 我 不 知 道 放 在 哪 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26881', '43', '20', '14', '说 了 这 话 ， 就 转 过 身 来 ， 看 见 耶 稣 站 在 那 里 ， 却 不 知 道 是 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26882', '43', '20', '15', '耶 稣 问 她 说 ： “ 妇 人 ， 为 什 么 哭 ？ 你 找 谁 呢 ？ ” 马 利 亚 以 为 是 看 园 的 ， 就 对 他 说 ： “ 先 生 ， 若 是 你 把 他 移 了 去 ， 请 告 诉 我 ， 你 把 他 放 在 哪 里 ， 我 便 去 取 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26883', '43', '20', '16', '耶 稣 说 ： “ 马 利 亚 。 ” 马 利 亚 就 转 过 来 ， 用 希 伯 来 话 对 他 说 ： “ 拉 波 尼 ！ ” （ 拉 波 尼 就 是 夫 子 的 意 思 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26884', '43', '20', '17', '耶 稣 说 ： “ 不 要 摸 我 ， 因 我 还 没 有 升 上 去 见 我 的 父 。 你 往 我 弟 兄 那 里 去 ， 告 诉 他 们 说 ， 我 要 升 上 去 见 我 的 父 ， 也 是 你 们 的 父 ， 见 我 的 神 ， 也 是 你 们 的 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26885', '43', '20', '18', '抹 大 拉 的 马 利 亚 就 去 告 诉 门 徒 说 ： “ 我 已 经 看 见 了 主 。 ” 她 又 将 主 对 她 说 的 这 话 告 诉 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26886', '43', '20', '19', '＜ 向 门 徒 显 现 （ 太   2 8 : 1 6 - 2 0 ； 可   1 6 : 1 4 - 1 8 ； 路   2 4 : 3 6 - 4 9 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26887', '43', '20', '20', '说 了 这 话 ， 就 把 手 和 肋 旁 指 给 他 们 看 。 门 徒 看 见 主 ， 就 喜 乐 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26888', '43', '20', '21', '耶 稣 又 对 他 们 说 ： “ 愿 你 们 平 安 ！ 父 怎 样 差 遣 了 我 ， 我 也 照 样 差 遣 你 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26889', '43', '20', '22', '说 了 这 话 ， 就 向 他 们 吹 一 口 气 ， 说 ： “ 你 们 受 圣 灵 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26890', '43', '20', '23', '你 们 赦 免 谁 的 罪 ， 谁 的 罪 就 赦 免 了 ； 你 们 留 下 谁 的 罪 ， 谁 的 罪 就 留 下 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26891', '43', '20', '24', '＜ 耶 稣 和 多 马 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26892', '43', '20', '25', '那 些 门 徒 就 对 他 说 ： “ 我 们 已 经 看 见 主 了 。 ” 多 马 却 说 ： “ 我 非 看 见 他 手 上 的 钉 痕 ， 用 指 头 探 入 那 钉 痕 ， 又 用 手 探 入 他 的 肋 旁 ， 我 总 不 信 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26893', '43', '20', '26', '过 了 八 日 ， 门 徒 又 在 屋 里 ， 多 马 也 和 他 们 同 在 ， 门 都 关 了 。 耶 稣 来 ， 站 在 当 中 说 ： “ 愿 你 们 平 安 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26894', '43', '20', '27', '就 对 多 马 说 ： “ 伸 过 你 的 指 头 来 ， 摸 ｛ 原 文 是 看 ｝ 我 的 手 ； 伸 出 你 的 手 来 ， 探 入 我 的 肋 旁 。 不 要 疑 惑 ， 总 要 信 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26895', '43', '20', '28', '多 马 说 ： “ 我 的 主 ！ 我 的 神 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26896', '43', '20', '29', '耶 稣 对 他 说 ： “ 你 因 看 见 了 我 才 信 ； 那 没 有 看 见 就 信 的 有 福 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26897', '43', '20', '30', '＜ 本 书 的 目 的 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26898', '43', '20', '31', '但 记 这 些 事 要 叫 你 们 信 耶 稣 是 基 督 ， 是 神 的 儿 子 ， 并 且 叫 你 们 信 了 他 ， 就 可 以 因 他 的 名 得 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26899', '43', '21', '1', '＜ 耶 稣 向 七 个 门 徒 显 现 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26900', '43', '21', '2', '有 西 门 ． 彼 得 和 称 为 低 土 马 的 多 马 ， 并 加 利 利 的 迦 拿 人 拿 但 业 ， 还 有 西 庇 太 的 两 个 儿 子 ， 又 有 两 个 门 徒 ， 都 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26901', '43', '21', '3', '西 门 ． 彼 得 对 他 们 说 ： “ 我 打 鱼 去 。 ” 他 们 说 ： “ 我 们 也 和 你 同 去 。 ” 他 们 就 出 去 ， 上 了 船 ； 那 一 夜 并 没 有 打 着 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26902', '43', '21', '4', '天 将 亮 的 时 候 ， 耶 稣 站 在 岸 上 ， 门 徒 却 不 知 道 是 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26903', '43', '21', '5', '耶 稣 就 对 他 们 说 ： “ 小 子 ！ 你 们 有 吃 的 没 有 ？ ” 他 们 回 答 说 ： “ 没 有 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26904', '43', '21', '6', '耶 稣 说 ： “ 你 们 把 网 撒 在 船 的 右 边 ， 就 必 得 着 。 ” 他 们 便 撒 下 网 去 ， 竟 拉 不 上 来 了 ， 因 为 鱼 甚 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26905', '43', '21', '7', '耶 稣 所 爱 的 那 门 徒 对 彼 得 说 ： “ 是 主 ！ ” 那 时 西 门 ． 彼 得 赤 着 身 子 ， 一 听 见 是 主 ， 就 束 上 一 件 外 衣 ， 跳 在 海 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26906', '43', '21', '8', '其 余 的 门 徒 离 岸 不 远 ， 约 有 二 百 肘 ｛ 古 时 以 肘 为 尺 ， 一 肘 约 有 今 时 尺 半 ｝ ， 就 在 小 船 上 把 那 网 鱼 拉 过 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26907', '43', '21', '9', '他 们 上 了 岸 ， 就 看 见 那 里 有 炭 火 ， 上 面 有 鱼 ， 又 有 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26908', '43', '21', '10', '耶 稣 对 他 们 说 ： “ 把 刚 才 打 的 鱼 拿 几 条 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26909', '43', '21', '11', '西 门 ． 彼 得 就 去 ｛ 或 译 ： 上 船 ｝ ， 把 网 拉 到 岸 上 。 那 网 满 了 大 鱼 ， 共 一 百 五 十 三 条 ； 鱼 虽 这 样 多 ， 网 却 没 有 破 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26910', '43', '21', '12', '耶 稣 说 ： “ 你 们 来 吃 早 饭 。 ” 门 徒 中 没 有 一 个 敢 问 他 ： “ 你 是 谁 ？ ” 因 为 知 道 是 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26911', '43', '21', '13', '耶 稣 就 来 拿 饼 和 鱼 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26912', '43', '21', '14', '耶 稣 从 死 里 复 活 以 后 ， 向 门 徒 显 现 ， 这 是 第 三 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26913', '43', '21', '15', '＜ 耶 稣 和 彼 得 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26914', '43', '21', '16', '耶 稣 第 二 次 又 对 他 说 ： “ 约 翰 的 儿 子 西 门 ， 你 爱 我 吗 ？ ” 彼 得 说 ： “ 主 啊 ， 是 的 ， 你 知 道 我 爱 你 。 ” 耶 稣 说 ： “ 你 牧 养 我 的 羊 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26915', '43', '21', '17', '第 三 次 对 他 说 ： “ 约 翰 的 儿 子 西 门 ， 你 爱 我 吗 ？ ” 彼 得 因 为 耶 稣 第 三 次 对 他 说 “ 你 爱 我 吗 ” ， 就 忧 愁 ， 对 耶 稣 说 ： “ 主 啊 ， 你 是 无 所 不 知 的 ； 你 知 道 我 爱 你 。 ” 耶 稣 说 ： “ 你 喂 养 我 的 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26916', '43', '21', '18', '我 实 实 在 在 地 告 诉 你 ， 你 年 少 的 时 候 ， 自 己 束 上 带 子 ， 随 意 往 来 ； 但 年 老 的 时 候 ， 你 要 伸 出 手 来 ， 别 人 要 把 你 束 上 ， 带 你 到 不 愿 意 去 的 地 方 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26917', '43', '21', '19', '（ 耶 稣 说 这 话 是 指 着 彼 得 要 怎 样 死 ， 荣 耀 神 。 ） 说 了 这 话 ， 就 对 他 说 ： “ 你 跟 从 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26918', '43', '21', '20', '＜ 耶 稣 他 所 爱 的 那 门 徒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26919', '43', '21', '21', '彼 得 看 见 他 ， 就 问 耶 稣 说 ： “ 主 啊 ， 这 人 将 来 如 何 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26920', '43', '21', '22', '耶 稣 对 他 说 ： “ 我 若 要 他 等 到 我 来 的 时 候 ， 与 你 何 干 ？ 你 跟 从 我 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26921', '43', '21', '23', '于 是 这 话 传 在 弟 兄 中 间 ， 说 那 门 徒 不 死 。 其 实 ， 耶 稣 不 是 说 他 不 死 ， 乃 是 说 ： “ 我 若 要 他 等 到 我 来 的 时 候 ， 与 你 何 干 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26922', '43', '21', '24', '为 这 些 事 作 见 证 ， 并 且 记 载 这 些 事 的 就 是 这 门 徒 ； 我 们 也 知 道 他 的 见 证 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26923', '43', '21', '25', '耶 稣 所 行 的 事 还 有 许 多 ， 若 是 一 一 地 都 写 出 来 ， 我 想 ， 所 写 的 书 就 是 世 界 也 容 不 下 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26924', '44', '1', '1', '＜ 赐 圣 灵 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26925', '44', '1', '2', '直 到 他 藉 着 圣 灵 吩 咐 所 拣 选 的 使 徒 ， 以 后 被 接 上 升 的 日 子 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26926', '44', '1', '3', '他 受 害 之 后 ， 用 许 多 的 凭 据 将 自 己 活 活 地 显 给 使 徒 看 ， 四 十 天 之 久 向 他 们 显 现 ， 讲 说 神 国 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26927', '44', '1', '4', '耶 稣 和 他 们 聚 集 的 时 候 ， 嘱 咐 他 们 说 ： “ 不 要 离 开 耶 路 撒 冷 ， 要 等 候 父 所 应 许 的 ， 就 是 你 们 听 见 我 说 过 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26928', '44', '1', '5', '约 翰 是 用 水 施 洗 ， 但 不 多 几 日 ， 你 们 要 受 圣 灵 的 洗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26929', '44', '1', '6', '＜ 耶 稣 升 天 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26930', '44', '1', '7', '耶 稣 对 他 们 说 ： “ 父 凭 着 自 己 的 权 柄 所 定 的 时 候 、 日 期 ， 不 是 你 们 可 以 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26931', '44', '1', '8', '但 圣 灵 降 临 在 你 们 身 上 ， 你 们 就 必 得 着 能 力 ， 并 要 在 耶 路 撒 冷 、 犹 太 全 地 ， 和 撒 马 利 亚 ， 直 到 地 极 ， 作 我 的 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26932', '44', '1', '9', '说 了 这 话 ， 他 们 正 看 的 时 候 ， 他 就 被 取 上 升 ， 有 一 朵 云 彩 把 他 接 去 ， 便 看 不 见 他 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26933', '44', '1', '10', '当 他 往 上 去 ， 他 们 定 睛 望 天 的 时 候 ， 忽 然 有 两 个 人 身 穿 白 衣 ， 站 在 旁 边 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26934', '44', '1', '11', '“ 加 利 利 人 哪 ， 你 们 为 什 么 站 着 望 天 呢 ？ 这 离 开 你 们 被 接 升 天 的 耶 稣 ， 你 们 见 他 怎 样 往 天 上 去 ， 他 还 要 怎 样 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26935', '44', '1', '12', '＜ 接 替 犹 大 职 分 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26936', '44', '1', '13', '进 了 城 ， 就 上 了 所 住 的 一 间 楼 房 ； 在 那 里 有 彼 得 、 约 翰 、 雅 各 、 安 得 烈 、 腓 力 、 多 马 、 巴 多 罗 买 、 马 太 、 亚 勒 腓 的 儿 子 雅 各 、 奋 锐 党 的 西 门 ， 和 雅 各 的 儿 子 ｛ 或 译 ： 兄 弟 ｝ 犹 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26937', '44', '1', '14', '这 些 人 同 着 几 个 妇 人 和 耶 稣 的 母 亲 马 利 亚 ， 并 耶 稣 的 弟 兄 ， 都 同 心 合 意 地 恒 切 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26938', '44', '1', '15', '那 时 ， 有 许 多 人 聚 会 ， 约 有 一 百 二 十 名 ， 彼 得 就 在 弟 兄 中 间 站 起 来 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26939', '44', '1', '16', '“ 弟 兄 们 ！ 圣 灵 藉 大 卫 的 口 ， 在 圣 经 上 预 言 领 人 捉 拿 耶 稣 的 犹 大 ， 这 话 是 必 须 应 验 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26940', '44', '1', '17', '他 本 来 列 在 我 们 数 中 ， 并 且 在 使 徒 的 职 任 上 得 了 一 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26941', '44', '1', '18', '这 人 用 他 作 恶 的 工 价 买 了 一 块 田 ， 以 后 身 子 仆 倒 ， 肚 腹 崩 裂 ， 肠 子 都 流 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26942', '44', '1', '19', '住 在 耶 路 撒 冷 的 众 人 都 知 道 这 事 ， 所 以 按 着 他 们 那 里 的 话 给 那 块 田 起 名 叫 亚 革 大 马 ， 就 是 “ 血 田 ” 的 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26943', '44', '1', '20', '因 为 诗 篇 上 写 着 ， 说 ： 愿 他 的 住 处 变 为 荒 场 ， 无 人 在 内 居 住 ； 又 说 ： 愿 别 人 得 他 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26944', '44', '1', '21', '所 以 ， 主 耶 稣 在 我 们 中 间 始 终 出 入 的 时 候 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26945', '44', '1', '22', '就 是 从 约 翰 施 洗 起 ， 直 到 主 离 开 我 们 被 接 上 升 的 日 子 为 止 ， 必 须 从 那 常 与 我 们 作 伴 的 人 中 立 一 位 与 我 们 同 作 耶 稣 复 活 的 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26946', '44', '1', '23', '于 是 选 举 两 个 人 ， 就 是 那 叫 做 巴 撒 巴 ， 又 称 呼 犹 士 都 的 约 瑟 ， 和 马 提 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26947', '44', '1', '24', '众 人 就 祷 告 说 ： “ 主 啊 ， 你 知 道 万 人 的 心 ， 求 你 从 这 两 个 人 中 ， 指 明 你 所 拣 选 的 是 谁 ， 叫 他 得 这 使 徒 的 位 分 。 这 位 分 犹 大 已 经 丢 弃 ， 往 自 己 的 地 方 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26948', '44', '1', '25', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26949', '44', '1', '26', '于 是 众 人 为 他 们 摇 签 ， 摇 出 马 提 亚 来 ； 他 就 和 十 一 个 使 徒 同 列 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26950', '44', '2', '1', '＜ 圣 灵 降 临 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26951', '44', '2', '2', '忽 然 ， 从 天 上 有 响 声 下 来 ， 好 像 一 阵 大 风 吹 过 ， 充 满 了 他 们 所 坐 的 屋 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26952', '44', '2', '3', '又 有 舌 头 如 火 焰 显 现 出 来 ， 分 开 落 在 他 们 各 人 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26953', '44', '2', '4', '他 们 就 都 被 圣 灵 充 满 ， 按 着 圣 灵 所 赐 的 口 才 说 起 别 国 的 话 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26954', '44', '2', '5', '那 时 ， 有 虔 诚 的 犹 太 人 从 天 下 各 国 来 ， 住 在 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26955', '44', '2', '6', '这 声 音 一 响 ， 众 人 都 来 聚 集 ， 各 人 听 见 门 徒 用 众 人 的 乡 谈 说 话 ， 就 甚 纳 闷 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26956', '44', '2', '7', '都 惊 讶 希 奇 说 ： “ 看 哪 ， 这 说 话 的 不 都 是 加 利 利 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26957', '44', '2', '8', '我 们 各 人 怎 么 听 见 他 们 说 我 们 生 来 所 用 的 乡 谈 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26958', '44', '2', '9', '我 们 帕 提 亚 人 、 米 底 亚 人 、 以 拦 人 ， 和 住 在 美 索 不 达 米 亚 、 犹 太 、 加 帕 多 家 、 本 都 、 亚 细 亚 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26959', '44', '2', '10', '弗 吕 家 、 旁 非 利 亚 、 埃 及 的 人 ， 并 靠 近 古 利 奈 的 利 比 亚 一 带 地 方 的 人 ， 从 罗 马 来 的 客 旅 中 ， 或 是 犹 太 人 ， 或 是 进 犹 太 教 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26960', '44', '2', '11', '克 里 特 和 阿 拉 伯 人 ， 都 听 见 他 们 用 我 们 的 乡 谈 ， 讲 说 神 的 大 作 为 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26961', '44', '2', '12', '众 人 就 都 惊 讶 猜 疑 ， 彼 此 说 ： “ 这 是 什 么 意 思 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26962', '44', '2', '13', '还 有 人 讥 诮 说 ： “ 他 们 无 非 是 新 酒 灌 满 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26963', '44', '2', '14', '＜ 彼 得 在 五 旬 节 的 讲 论 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26964', '44', '2', '15', '你 们 想 这 些 人 是 醉 了 ； 其 实 不 是 醉 了 ， 因 为 时 候 刚 到 巳 初 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26965', '44', '2', '16', '这 正 是 先 知 约 珥 所 说 的 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26966', '44', '2', '17', '神 说 ： 在 末 后 的 日 子 ， 我 要 将 我 的 灵 浇 灌 凡 有 血 气 的 。 你 们 的 儿 女 要 说 预 言 ； 你 们 的 少 年 人 要 见 异 象 ； 老 年 人 要 做 异 梦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26967', '44', '2', '18', '在 那 些 日 子 ， 我 要 将 我 的 灵 浇 灌 我 的 仆 人 和 使 女 ， 他 们 就 要 说 预 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26968', '44', '2', '19', '在 天 上 ， 我 要 显 出 奇 事 ； 在 地 下 ， 我 要 显 出 神 迹 ； 有 血 ， 有 火 ， 有 烟 雾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26969', '44', '2', '20', '日 头 要 变 为 黑 暗 ， 月 亮 要 变 为 血 ； 这 都 在 主 大 而 明 显 的 日 子 未 到 以 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26970', '44', '2', '21', '到 那 时 候 ， 凡 求 告 主 名 的 ， 就 必 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26971', '44', '2', '22', '“ 以 色 列 人 哪 ， 请 听 我 的 话 ： 神 藉 着 拿 撒 勒 人 耶 稣 在 你 们 中 间 施 行 异 能 、 奇 事 、 神 迹 ， 将 他 证 明 出 来 ， 这 是 你 们 自 己 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26972', '44', '2', '23', '他 既 按 着 神 的 定 旨 先 见 被 交 与 人 ， 你 们 就 藉 着 无 法 之 人 的 手 ， 把 他 钉 在 十 字 架 上 ， 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26973', '44', '2', '24', '神 却 将 死 的 痛 苦 解 释 了 ， 叫 他 复 活 ， 因 为 他 原 不 能 被 死 拘 禁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26974', '44', '2', '25', '大 卫 指 着 他 说 ： “ 我 看 见 主 常 在 我 眼 前 ； 他 在 我 右 边 ， 叫 我 不 至 于 摇 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26975', '44', '2', '26', '所 以 ， 我 心 里 欢 喜 ， 我 的 灵 ｛ 原 文 是 舌 ｝ 快 乐 ； 并 且 我 的 肉 身 要 安 居 在 指 望 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26976', '44', '2', '27', '因 你 必 不 将 我 的 灵 魂 撇 在 阴 间 ， 也 不 叫 你 的 圣 者 见 朽 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26977', '44', '2', '28', '你 已 将 生 命 的 道 路 指 示 我 ， 必 叫 我 因 见 你 的 面 ｛ 或 译 ： 叫 我 在 你 面 前 ｝ 得 着 满 足 的 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26978', '44', '2', '29', '“ 弟 兄 们 ！ 先 祖 大 卫 的 事 ， 我 可 以 明 明 地 对 你 们 说 ： 他 死 了 ， 也 葬 埋 了 ， 并 且 他 的 坟 墓 直 到 今 日 还 在 我 们 这 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26979', '44', '2', '30', '大 卫 既 是 先 知 ， 又 晓 得 神 曾 向 他 起 誓 ， 要 从 他 的 后 裔 中 立 一 位 坐 在 他 的 宝 座 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26980', '44', '2', '31', '就 预 先 看 明 这 事 ， 讲 论 基 督 复 活 说 ： 他 的 灵 魂 不 撇 在 阴 间 ； 他 的 肉 身 也 不 见 朽 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26981', '44', '2', '32', '这 耶 稣 ， 神 已 经 叫 他 复 活 了 ， 我 们 都 为 这 事 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26982', '44', '2', '33', '他 既 被 神 的 右 手 高 举 ｛ 或 译 ： 他 既 高 举 在 神 的 右 边 ｝ ， 又 从 父 受 了 所 应 许 的 圣 灵 ， 就 把 你 们 所 看 见 所 听 见 的 ， 浇 灌 下 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26983', '44', '2', '34', '大 卫 并 没 有 升 到 天 上 ， 但 自 己 说 ： 主 对 我 主 说 ： 你 坐 在 我 的 右 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26984', '44', '2', '35', '等 我 使 你 仇 敌 作 你 的 脚 凳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26985', '44', '2', '36', '“ 故 此 ， 以 色 列 全 家 当 确 实 地 知 道 ， 你 们 钉 在 十 字 架 上 的 这 位 耶 稣 ， 神 已 经 立 他 为 主 ， 为 基 督 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26986', '44', '2', '37', '众 人 听 见 这 话 ， 觉 得 扎 心 ， 就 对 彼 得 和 其 余 的 使 徒 说 ： “ 弟 兄 们 ， 我 们 当 怎 样 行 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26987', '44', '2', '38', '彼 得 说 ： “ 你 们 各 人 要 悔 改 ， 奉 耶 稣 基 督 的 名 受 洗 ， 叫 你 们 的 罪 得 赦 ， 就 必 领 受 所 赐 的 圣 灵 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26988', '44', '2', '39', '因 为 这 应 许 是 给 你 们 和 你 们 的 儿 女 ， 并 一 切 在 远 方 的 人 ， 就 是 主 ─ ─ 我 们 神 所 召 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26989', '44', '2', '40', '彼 得 还 用 许 多 话 作 见 证 ， 劝 勉 他 们 说 ： “ 你 们 当 救 自 己 脱 离 这 弯 曲 的 世 代 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26990', '44', '2', '41', '于 是 领 受 他 话 的 人 就 受 了 洗 。 那 一 天 ， 门 徒 约 添 了 三 千 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26991', '44', '2', '42', '都 恒 心 遵 守 使 徒 的 教 训 ， 彼 此 交 接 ， 擘 饼 ， 祈 祷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26992', '44', '2', '43', '＜ 在 圣 徒 中 间 的 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26993', '44', '2', '44', '信 的 人 都 在 一 处 ， 凡 物 公 用 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26994', '44', '2', '45', '并 且 卖 了 田 产 、 家 业 ， 照 各 人 所 需 用 的 分 给 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26995', '44', '2', '46', '他 们 天 天 同 心 合 意 恒 切 地 在 殿 里 ， 且 在 家 中 擘 饼 ， 存 着 欢 喜 、 诚 实 的 心 用 饭 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26996', '44', '2', '47', '赞 美 神 ， 得 众 民 的 喜 爱 。 主 将 得 救 的 人 天 天 加 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26997', '44', '3', '1', '＜ 圣 殿 门 口 的 瘸 腿 者 得 医 治 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26998', '44', '3', '2', '有 一 个 人 ， 生 来 是 瘸 腿 的 ， 天 天 被 人 抬 来 ， 放 在 殿 的 一 个 门 口 （ 那 门 名 叫 美 门 ） ， 要 求 进 殿 的 人 赒 济 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('26999', '44', '3', '3', '他 看 见 彼 得 、 约 翰 将 要 进 殿 ， 就 求 他 们 赒 济 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27000', '44', '3', '4', '彼 得 、 约 翰 定 睛 看 他 ； 彼 得 说 ： “ 你 看 我 们 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27001', '44', '3', '5', '那 人 就 留 意 看 他 们 ， 指 望 得 着 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27002', '44', '3', '6', '彼 得 说 ： “ 金 银 我 都 没 有 ， 只 把 我 所 有 的 给 你 ： 我 奉 拿 撒 勒 人 耶 稣 基 督 的 名 ， 叫 你 起 来 行 走 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27003', '44', '3', '7', '于 是 拉 着 他 的 右 手 ， 扶 他 起 来 ； 他 的 脚 和 踝 子 骨 立 刻 健 壮 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27004', '44', '3', '8', '就 跳 起 来 ， 站 着 ， 又 行 走 ， 同 他 们 进 了 殿 ， 走 着 ， 跳 着 ， 赞 美 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27005', '44', '3', '9', '百 姓 都 看 见 他 行 走 ， 赞 美 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27006', '44', '3', '10', '认 得 他 是 那 素 常 坐 在 殿 的 美 门 口 求 赒 济 的 ， 就 因 他 所 遇 着 的 事 满 心 希 奇 、 惊 讶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27007', '44', '3', '11', '＜ 彼 得 在 所 罗 门 廊 下 的 讲 论 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27008', '44', '3', '12', '彼 得 看 见 ， 就 对 百 姓 说 ： “ 以 色 列 人 哪 ， 为 什 么 把 这 事 当 作 希 奇 呢 ？ 为 什 么 定 睛 看 我 们 ， 以 为 我 们 凭 自 己 的 能 力 和 虔 诚 使 这 人 行 走 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27009', '44', '3', '13', '亚 伯 拉 罕 、 以 撒 、 雅 各 的 神 ， 就 是 我 们 列 祖 的 神 ， 已 经 荣 耀 了 他 的 仆 人 ｛ 或 译 ： 儿 子 ｝ 耶 稣 ； 你 们 却 把 他 交 付 彼 拉 多 。 彼 拉 多 定 意 要 释 放 他 ， 你 们 竟 在 彼 拉 多 面 前 弃 绝 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27010', '44', '3', '14', '你 们 弃 绝 了 那 圣 洁 公 义 者 ， 反 求 着 释 放 一 个 凶 手 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27011', '44', '3', '15', '你 们 杀 了 那 生 命 的 主 ， 神 却 叫 他 从 死 里 复 活 了 ； 我 们 都 是 为 这 事 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27012', '44', '3', '16', '我 们 因 信 他 的 名 ， 他 的 名 便 叫 你 们 所 看 见 所 认 识 的 这 人 健 壮 了 ； 正 是 他 所 赐 的 信 心 ， 叫 这 人 在 你 们 众 人 面 前 全 然 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27013', '44', '3', '17', '弟 兄 们 ， 我 晓 得 你 们 做 这 事 是 出 于 不 知 ， 你 们 的 官 长 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27014', '44', '3', '18', '但 神 曾 藉 众 先 知 的 口 ， 预 言 基 督 将 要 受 害 ， 就 这 样 应 验 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27015', '44', '3', '19', '所 以 ， 你 们 当 悔 改 归 正 ， 使 你 们 的 罪 得 以 涂 抹 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27016', '44', '3', '20', '这 样 ， 那 安 舒 的 日 子 就 必 从 主 面 前 来 到 ； 主 也 必 差 遣 所 预 定 给 你 们 的 基 督 （ 耶 稣 ） 降 临 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27017', '44', '3', '21', '天 必 留 他 ， 等 到 万 物 复 兴 的 时 候 ， 就 是 神 从 创 世 以 来 、 藉 着 圣 先 知 的 口 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27018', '44', '3', '22', '摩 西 曾 说 ： ‘ 主 ─ ─ 神 要 从 你 们 弟 兄 中 间 给 你 们 兴 起 一 位 先 知 像 我 ， 凡 他 向 你 们 所 说 的 ， 你 们 都 要 听 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27019', '44', '3', '23', '凡 不 听 从 那 先 知 的 ， 必 要 从 民 中 全 然 灭 绝 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27020', '44', '3', '24', '从 撒 母 耳 以 来 的 众 先 知 ， 凡 说 预 言 的 ， 也 都 说 到 这 些 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27021', '44', '3', '25', '你 们 是 先 知 的 子 孙 ， 也 承 受 神 与 你 们 祖 宗 所 立 的 约 ， 就 是 对 亚 伯 拉 罕 说 ： ‘ 地 上 万 族 都 要 因 你 的 后 裔 得 福 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27022', '44', '3', '26', '神 既 兴 起 他 的 仆 人 ｛ 或 译 ： 儿 子 ｝ ， 就 先 差 他 到 你 们 这 里 来 ， 赐 福 给 你 们 ， 叫 你 们 各 人 回 转 ， 离 开 罪 恶 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27023', '44', '4', '1', '＜ 彼 得 、 约 翰 在 公 会 被 查 问 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27024', '44', '4', '2', '因 他 们 教 训 百 姓 ， 本 着 耶 稣 ， 传 说 死 人 复 活 ， 就 很 烦 恼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27025', '44', '4', '3', '于 是 下 手 拿 住 他 们 ； 因 为 天 已 经 晚 了 ， 就 把 他 们 押 到 第 二 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27026', '44', '4', '4', '但 听 道 之 人 有 许 多 信 的 ， 男 丁 数 目 约 到 五 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27027', '44', '4', '5', '第 二 天 ， 官 府 、 长 老 ， 和 文 士 在 耶 路 撒 冷 聚 会 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27028', '44', '4', '6', '又 有 大 祭 司 亚 那 和 该 亚 法 、 约 翰 、 亚 历 山 大 ， 并 大 祭 司 的 亲 族 都 在 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27029', '44', '4', '7', '叫 使 徒 站 在 当 中 ， 就 问 他 们 说 ： “ 你 们 用 什 么 能 力 ， 奉 谁 的 名 做 这 事 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27030', '44', '4', '8', '那 时 彼 得 被 圣 灵 充 满 ， 对 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27031', '44', '4', '9', '“ 治 民 的 官 府 和 长 老 啊 ， 倘 若 今 日 因 为 在 残 疾 人 身 上 所 行 的 善 事 查 问 我 们 他 是 怎 么 得 了 痊 愈 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27032', '44', '4', '10', '你 们 众 人 和 以 色 列 百 姓 都 当 知 道 ， 站 在 你 们 面 前 的 这 人 得 痊 愈 是 因 你 们 所 钉 十 字 架 、 神 叫 他 从 死 里 复 活 的 拿 撒 勒 人 耶 稣 基 督 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27033', '44', '4', '11', '他 是 你 们 匠 人 所 弃 的 石 头 ， 已 成 了 房 角 的 头 块 石 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27034', '44', '4', '12', '除 他 以 外 ， 别 无 拯 救 ； 因 为 在 天 下 人 间 ， 没 有 赐 下 别 的 名 ， 我 们 可 以 靠 着 得 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27035', '44', '4', '13', '他 们 见 彼 得 、 约 翰 的 胆 量 ， 又 看 出 他 们 原 是 没 有 学 问 的 小 民 ， 就 希 奇 ， 认 明 他 们 是 跟 过 耶 稣 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27036', '44', '4', '14', '又 看 见 那 治 好 了 的 人 和 他 们 一 同 站 着 ， 就 无 话 可 驳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27037', '44', '4', '15', '于 是 吩 咐 他 们 从 公 会 出 去 ， 就 彼 此 商 议 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27038', '44', '4', '16', '“ 我 们 当 怎 样 办 这 两 个 人 呢 ？ 因 为 他 们 诚 然 行 了 一 件 明 显 的 神 迹 ， 凡 住 耶 路 撒 冷 的 人 都 知 道 ， 我 们 也 不 能 说 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27039', '44', '4', '17', '惟 恐 这 事 越 发 传 扬 在 民 间 ， 我 们 必 须 恐 吓 他 们 ， 叫 他 们 不 再 奉 这 名 对 人 讲 论 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27040', '44', '4', '18', '于 是 叫 了 他 们 来 ， 禁 止 他 们 总 不 可 奉 耶 稣 的 名 讲 论 教 训 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27041', '44', '4', '19', '彼 得 、 约 翰 说 ： “ 听 从 你 们 ， 不 听 从 神 ， 这 在 神 面 前 合 理 不 合 理 ， 你 们 自 己 酌 量 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27042', '44', '4', '20', '我 们 所 看 见 所 听 见 的 ， 不 能 不 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27043', '44', '4', '21', '官 长 为 百 姓 的 缘 故 ， 想 不 出 法 子 刑 罚 他 们 ， 又 恐 吓 一 番 ， 把 他 们 释 放 了 。 这 是 因 众 人 为 所 行 的 奇 事 都 归 荣 耀 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27044', '44', '4', '22', '原 来 藉 着 神 迹 医 好 的 那 人 有 四 十 多 岁 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27045', '44', '4', '23', '＜ 门 徒 求 主 赐 胆 量 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27046', '44', '4', '24', '他 们 听 见 了 ， 就 同 心 合 意 地 高 声 向 神 说 ： “ 主 啊 ！ 你 是 造 天 、 地 、 海 ， 和 其 中 万 物 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27047', '44', '4', '25', '你 曾 藉 着 圣 灵 ， 托 你 仆 人 ─ ─ 我 们 祖 宗 大 卫 的 口 ， 说 ： 外 邦 为 什 么 争 闹 ？ 万 民 为 什 么 谋 算 虚 妄 的 事 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27048', '44', '4', '26', '世 上 的 君 王 一 齐 起 来 ， 臣 宰 也 聚 集 ， 要 敌 挡 主 ， 并 主 的 受 膏 者 ｛ 或 译 ： 基 督 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27049', '44', '4', '27', '希 律 和 本 丢 ． 彼 拉 多 ， 外 邦 人 和 以 色 列 民 ， 果 然 在 这 城 里 聚 集 ， 要 攻 打 你 所 膏 的 圣 仆 ｛ 仆 ： 或 译 子 ｝ 耶 稣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27050', '44', '4', '28', '成 就 你 手 和 你 意 旨 所 预 定 必 有 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27051', '44', '4', '29', '他 们 恐 吓 我 们 ， 现 在 求 主 鉴 察 ， 一 面 叫 你 仆 人 大 放 胆 量 讲 你 的 道 ， 一 面 伸 出 你 的 手 来 医 治 疾 病 ， 并 且 使 神 迹 奇 事 因 着 你 圣 仆 ｛ 仆 ： 或 译 子 ｝ 耶 稣 的 名 行 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27052', '44', '4', '30', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27053', '44', '4', '31', '祷 告 完 了 ， 聚 会 的 地 方 震 动 ， 他 们 就 都 被 圣 灵 充 满 ， 放 胆 讲 论 神 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27054', '44', '4', '32', '＜ 凡 物 公 用 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27055', '44', '4', '33', '使 徒 大 有 能 力 ， 见 证 主 耶 稣 复 活 ； 众 人 也 都 蒙 大 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27056', '44', '4', '34', '内 中 也 没 有 一 个 缺 乏 的 ； 因 为 人 人 将 田 产 房 屋 都 卖 了 ， 把 所 卖 的 价 银 拿 来 ， 放 在 使 徒 脚 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27057', '44', '4', '35', '照 各 人 所 需 用 的 ， 分 给 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27058', '44', '4', '36', '有 一 个 利 未 人 ， 生 在 塞 浦 路 斯 ， 名 叫 约 瑟 ， 使 徒 称 他 为 巴 拿 巴 （ 巴 拿 巴 翻 出 来 就 是 劝 慰 子 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27059', '44', '4', '37', '他 有 田 地 ， 也 卖 了 ， 把 价 银 拿 来 ， 放 在 使 徒 脚 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27060', '44', '5', '1', '＜ 亚 拿 尼 亚 和 撒 非 喇 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27061', '44', '5', '2', '把 价 银 私 自 留 下 几 分 ， 他 的 妻 子 也 知 道 ， 其 余 的 几 分 拿 来 放 在 使 徒 脚 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27062', '44', '5', '3', '彼 得 说 ： “ 亚 拿 尼 亚 ！ 为 什 么 撒 但 充 满 了 你 的 心 ， 叫 你 欺 哄 圣 灵 ， 把 田 地 的 价 银 私 自 留 下 几 分 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27063', '44', '5', '4', '田 地 还 没 有 卖 ， 不 是 你 自 己 的 吗 ？ 既 卖 了 ， 价 银 不 是 你 作 主 吗 ？ 你 怎 么 心 里 起 这 意 念 呢 ？ 你 不 是 欺 哄 人 ， 是 欺 哄 神 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27064', '44', '5', '5', '亚 拿 尼 亚 听 见 这 话 ， 就 仆 倒 ， 断 了 气 ； 听 见 的 人 都 甚 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27065', '44', '5', '6', '有 些 少 年 人 起 来 ， 把 他 包 裹 ， 抬 出 去 埋 葬 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27066', '44', '5', '7', '约 过 了 三 小 时 ， 他 的 妻 子 进 来 ， 还 不 知 道 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27067', '44', '5', '8', '彼 得 对 她 说 ： “ 你 告 诉 我 ， 你 们 卖 田 地 的 价 银 就 是 这 些 吗 ？ ” 她 说 ： “ 就 是 这 些 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27068', '44', '5', '9', '彼 得 说 ： “ 你 们 为 什 么 同 心 试 探 主 的 灵 呢 ？ 埋 葬 你 丈 夫 之 人 的 脚 已 到 门 口 ， 他 们 也 要 把 你 抬 出 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27069', '44', '5', '10', '妇 人 立 刻 仆 倒 在 彼 得 脚 前 ， 断 了 气 。 那 些 少 年 人 进 来 ， 见 她 已 经 死 了 ， 就 抬 出 去 ， 埋 在 她 丈 夫 旁 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27070', '44', '5', '11', '全 教 会 和 听 见 这 事 的 人 都 甚 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27071', '44', '5', '12', '＜ 主 藉 使 徒 行 了 许 多 神 迹 奇 事 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27072', '44', '5', '13', '其 余 的 人 没 有 一 个 敢 贴 近 他 们 ， 百 姓 却 尊 重 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27073', '44', '5', '14', '信 而 归 主 的 人 越 发 增 添 ， 连 男 带 女 很 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27074', '44', '5', '15', '甚 至 有 人 将 病 人 抬 到 街 上 ， 放 在 床 上 或 褥 子 上 ， 指 望 彼 得 过 来 的 时 候 ， 或 者 得 他 的 影 儿 照 在 什 么 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27075', '44', '5', '16', '还 有 许 多 人 带 着 病 人 和 被 污 鬼 缠 磨 的 ， 从 耶 路 撒 冷 四 围 的 城 邑 来 ， 全 都 得 了 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27076', '44', '5', '17', '＜ 使 徒 受 迫 害 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27077', '44', '5', '18', '就 下 手 拿 住 使 徒 ， 收 在 外 监 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27078', '44', '5', '19', '但 主 的 使 者 夜 间 开 了 监 门 ， 领 他 们 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27079', '44', '5', '20', '说 ： “ 你 们 去 站 在 殿 里 ， 把 这 生 命 的 道 都 讲 给 百 姓 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27080', '44', '5', '21', '使 徒 听 了 这 话 ， 天 将 亮 的 时 候 就 进 殿 里 去 教 训 人 。 大 祭 司 和 他 的 同 人 来 了 ， 叫 齐 公 会 的 人 和 以 色 列 族 的 众 长 老 ， 就 差 人 到 监 里 去 ， 要 把 使 徒 提 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27081', '44', '5', '22', '但 差 役 到 了 ， 不 见 他 们 在 监 里 ， 就 回 来 禀 报 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27082', '44', '5', '23', '“ 我 们 看 见 监 牢 关 得 极 妥 当 ， 看 守 的 人 也 站 在 门 外 ； 及 至 开 了 门 ， 里 面 一 个 人 都 不 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27083', '44', '5', '24', '守 殿 官 和 祭 司 长 听 见 这 话 ， 心 里 犯 难 ， 不 知 这 事 将 来 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27084', '44', '5', '25', '有 一 个 人 来 禀 报 说 ： “ 你 们 收 在 监 里 的 人 ， 现 在 站 在 殿 里 教 训 百 姓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27085', '44', '5', '26', '于 是 守 殿 官 和 差 役 去 带 使 徒 来 ， 并 没 有 用 强 暴 ， 因 为 怕 百 姓 用 石 头 打 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27086', '44', '5', '27', '带 到 了 ， 便 叫 使 徒 站 在 公 会 前 ； 大 祭 司 问 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27087', '44', '5', '28', '“ 我 们 不 是 严 严 地 禁 止 你 们 ， 不 可 奉 这 名 教 训 人 吗 ？ 你 们 倒 把 你 们 的 道 理 充 满 了 耶 路 撒 冷 ， 想 要 叫 这 人 的 血 归 到 我 们 身 上 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27088', '44', '5', '29', '彼 得 和 众 使 徒 回 答 说 ： “ 顺 从 神 ， 不 顺 从 人 ， 是 应 当 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27089', '44', '5', '30', '你 们 挂 在 木 头 上 杀 害 的 耶 稣 ， 我 们 祖 宗 的 神 已 经 叫 他 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27090', '44', '5', '31', '神 且 用 右 手 将 他 高 举 ｛ 或 译 ： 他 就 是 神 高 举 在 自 己 的 右 边 ｝ ， 叫 他 作 君 王 ， 作 救 主 ， 将 悔 改 的 心 和 赦 罪 的 恩 赐 给 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27091', '44', '5', '32', '我 们 为 这 事 作 见 证 ； 神 赐 给 顺 从 之 人 的 圣 灵 也 为 这 事 作 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27092', '44', '5', '33', '公 会 的 人 听 见 就 极 其 恼 怒 ， 想 要 杀 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27093', '44', '5', '34', '但 有 一 个 法 利 赛 人 ， 名 叫 迦 玛 列 ， 是 众 百 姓 所 敬 重 的 教 法 师 ， 在 公 会 中 站 起 来 ， 吩 咐 人 把 使 徒 暂 且 带 到 外 面 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27094', '44', '5', '35', '就 对 众 人 说 ： “ 以 色 列 人 哪 ， 论 到 这 些 人 ， 你 们 应 当 小 心 怎 样 办 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27095', '44', '5', '36', '从 前 杜 达 起 来 ， 自 夸 为 大 ； 附 从 他 的 人 约 有 四 百 ， 他 被 杀 后 ， 附 从 他 的 全 都 散 了 ， 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27096', '44', '5', '37', '此 后 ， 报 名 上 册 的 时 候 ， 又 有 加 利 利 的 犹 大 起 来 ， 引 诱 些 百 姓 跟 从 他 ； 他 也 灭 亡 ， 附 从 他 的 人 也 都 四 散 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27097', '44', '5', '38', '现 在 ， 我 劝 你 们 不 要 管 这 些 人 ， 任 凭 他 们 吧 ！ 他 们 所 谋 的 、 所 行 的 ， 若 是 出 于 人 ， 必 要 败 坏 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27098', '44', '5', '39', '若 是 出 于 神 ， 你 们 就 不 能 败 坏 他 们 ， 恐 怕 你 们 倒 是 攻 击 神 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27099', '44', '5', '40', '公 会 的 人 听 从 了 他 ， 便 叫 使 徒 来 ， 把 他 们 打 了 ， 又 吩 咐 他 们 不 可 奉 耶 稣 的 名 讲 道 ， 就 把 他 们 释 放 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27100', '44', '5', '41', '他 们 离 开 公 会 ， 心 里 欢 喜 ， 因 被 算 是 配 为 这 名 受 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27101', '44', '5', '42', '他 们 就 每 日 在 殿 里 、 在 家 里 不 住 地 教 训 人 ， 传 耶 稣 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27102', '44', '6', '1', '＜ 拣 选 七 人 办 理 供 给 的 事 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27103', '44', '6', '2', '十 二 使 徒 叫 众 门 徒 来 ， 对 他 们 说 ： “ 我 们 撇 下 神 的 道 去 管 理 饭 食 ， 原 是 不 合 宜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27104', '44', '6', '3', '所 以 弟 兄 们 ， 当 从 你 们 中 间 选 出 七 个 有 好 名 声 、 被 圣 灵 充 满 、 智 慧 充 足 的 人 ， 我 们 就 派 他 们 管 理 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27105', '44', '6', '4', '但 我 们 要 专 心 以 祈 祷 、 传 道 为 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27106', '44', '6', '5', '大 众 都 喜 悦 这 话 ， 就 拣 选 了 司 提 反 ， 乃 是 大 有 信 心 、 圣 灵 充 满 的 人 ， 又 拣 选 腓 利 、 伯 罗 哥 罗 、 尼 迦 挪 、 提 门 、 巴 米 拿 ， 并 进 犹 太 教 的 安 提 阿 人 尼 哥 拉 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27107', '44', '6', '6', '叫 他 们 站 在 使 徒 面 前 。 使 徒 祷 告 了 ， 就 按 手 在 他 们 头 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27108', '44', '6', '7', '神 的 道 兴 旺 起 来 ； 在 耶 路 撒 冷 门 徒 数 目 加 增 的 甚 多 ， 也 有 许 多 祭 司 信 从 了 这 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27109', '44', '6', '8', '＜ 司 提 反 被 捕 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27110', '44', '6', '9', '当 时 有 称 利 百 地 拿 会 堂 的 几 个 人 ， 并 有 古 利 奈 、 亚 历 山 大 、 基 利 家 、 亚 细 亚 各 处 会 堂 的 几 个 人 ， 都 起 来 和 司 提 反 辩 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27111', '44', '6', '10', '司 提 反 是 以 智 慧 和 圣 灵 说 话 ， 众 人 敌 挡 不 住 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27112', '44', '6', '11', '就 买 出 人 来 说 ： “ 我 们 听 见 他 说 谤 讟 摩 西 和 神 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27113', '44', '6', '12', '他 们 又 耸 动 了 百 姓 、 长 老 ， 并 文 士 ， 就 忽 然 来 捉 拿 他 ， 把 他 带 到 公 会 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27114', '44', '6', '13', '设 下 假 见 证 ， 说 ： “ 这 个 人 说 话 ， 不 住 地 糟 践 圣 所 和 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27115', '44', '6', '14', '我 们 曾 听 见 他 说 ， 这 拿 撒 勒 人 耶 稣 要 毁 坏 此 地 ， 也 要 改 变 摩 西 所 交 给 我 们 的 规 条 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27116', '44', '6', '15', '在 公 会 里 坐 着 的 人 都 定 睛 看 他 ， 见 他 的 面 貌 ， 好 像 天 使 的 面 貌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27117', '44', '7', '1', '＜ 司 提 反 当 众 申 诉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27118', '44', '7', '2', '司 提 反 说 ： “ 诸 位 父 兄 请 听 ！ 当 日 我 们 的 祖 宗 亚 伯 拉 罕 在 美 索 不 达 米 亚 还 未 住 哈 兰 的 时 候 ， 荣 耀 的 神 向 他 显 现 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27119', '44', '7', '3', '对 他 说 ： ‘ 你 要 离 开 本 地 和 亲 族 ， 往 我 所 要 指 示 你 的 地 方 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27120', '44', '7', '4', '他 就 离 开 迦 勒 底 人 之 地 ， 住 在 哈 兰 。 他 父 亲 死 了 以 后 ， 神 使 他 从 那 里 搬 到 你 们 现 在 所 住 之 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27121', '44', '7', '5', '在 这 地 方 ， 神 并 没 有 给 他 产 业 ， 连 立 足 之 地 也 没 有 给 他 ； 但 应 许 要 将 这 地 赐 给 他 和 他 的 后 裔 为 业 ； 那 时 他 还 没 有 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27122', '44', '7', '6', '神 说 ： ‘ 他 的 后 裔 必 寄 居 外 邦 ， 那 里 的 人 要 叫 他 们 作 奴 仆 ， 苦 待 他 们 四 百 年 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27123', '44', '7', '7', '神 又 说 ： ‘ 使 他 们 作 奴 仆 的 那 国 ， 我 要 惩 罚 。 以 后 他 们 要 出 来 ， 在 这 地 方 事 奉 我 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27124', '44', '7', '8', '神 又 赐 他 割 礼 的 约 。 于 是 亚 伯 拉 罕 生 了 以 撒 ， 第 八 日 给 他 行 了 割 礼 。 以 撒 生 雅 各 ； 雅 各 生 十 二 位 先 祖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27125', '44', '7', '9', '“ 先 祖 嫉 妒 约 瑟 ， 把 他 卖 到 埃 及 去 ； 神 却 与 他 同 在 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27126', '44', '7', '10', '救 他 脱 离 一 切 苦 难 ， 又 使 他 在 埃 及 王 法 老 面 前 得 恩 典 ， 有 智 慧 。 法 老 就 派 他 作 埃 及 国 的 宰 相 兼 管 全 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27127', '44', '7', '11', '后 来 埃 及 和 迦 南 全 地 遭 遇 饥 荒 ， 大 受 艰 难 ， 我 们 的 祖 宗 就 绝 了 粮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27128', '44', '7', '12', '雅 各 听 见 在 埃 及 有 粮 ， 就 打 发 我 们 的 祖 宗 初 次 往 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27129', '44', '7', '13', '第 二 次 约 瑟 与 弟 兄 们 相 认 ， 他 的 亲 族 也 被 法 老 知 道 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27130', '44', '7', '14', '约 瑟 就 打 发 弟 兄 请 父 亲 雅 各 和 全 家 七 十 五 个 人 都 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27131', '44', '7', '15', '于 是 雅 各 下 了 埃 及 ， 后 来 他 和 我 们 的 祖 宗 都 死 在 那 里 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27132', '44', '7', '16', '又 被 带 到 示 剑 ， 葬 于 亚 伯 拉 罕 在 示 剑 用 银 子 从 哈 抹 子 孙 买 来 的 坟 墓 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27133', '44', '7', '17', '“ 及 至 神 应 许 亚 伯 拉 罕 的 日 期 将 到 ， 以 色 列 民 在 埃 及 兴 盛 众 多 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27134', '44', '7', '18', '直 到 有 不 晓 得 约 瑟 的 新 王 兴 起 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27135', '44', '7', '19', '他 用 诡 计 待 我 们 的 宗 族 ， 苦 害 我 们 的 祖 宗 ， 叫 他 们 丢 弃 婴 孩 ， 使 婴 孩 不 能 存 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27136', '44', '7', '20', '那 时 ， 摩 西 生 下 来 ， 俊 美 非 凡 ， 在 他 父 亲 家 里 抚 养 了 三 个 月 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27137', '44', '7', '21', '他 被 丢 弃 的 时 候 ， 法 老 的 女 儿 拾 了 去 ， 养 为 自 己 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27138', '44', '7', '22', '摩 西 学 了 埃 及 人 一 切 的 学 问 ， 说 话 行 事 都 有 才 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27139', '44', '7', '23', '“ 他 将 到 四 十 岁 ， 心 中 起 意 去 看 望 他 的 弟 兄 以 色 列 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27140', '44', '7', '24', '到 了 那 里 ， 见 他 们 一 个 人 受 冤 屈 ， 就 护 庇 他 ， 为 那 受 欺 压 的 人 报 仇 ， 打 死 了 那 埃 及 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27141', '44', '7', '25', '他 以 为 弟 兄 必 明 白 神 是 藉 他 的 手 搭 救 他 们 ； 他 们 却 不 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27142', '44', '7', '26', '第 二 天 ， 遇 见 两 个 以 色 列 人 争 斗 ， 就 劝 他 们 和 睦 ， 说 ： ‘ 你 们 二 位 是 弟 兄 ， 为 什 么 彼 此 欺 负 呢 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27143', '44', '7', '27', '那 欺 负 邻 舍 的 把 他 推 开 ， 说 ： ‘ 谁 立 你 作 我 们 的 首 领 和 审 判 官 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27144', '44', '7', '28', '难 道 你 要 杀 我 ， 像 昨 天 杀 那 埃 及 人 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27145', '44', '7', '29', '摩 西 听 见 这 话 就 逃 走 了 ， 寄 居 于 米 甸 ； 在 那 里 生 了 两 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27146', '44', '7', '30', '“ 过 了 四 十 年 ， 在 西 奈 山 的 旷 野 ， 有 一 位 天 使 从 荆 棘 火 焰 中 向 摩 西 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27147', '44', '7', '31', '摩 西 见 了 那 异 象 ， 便 觉 希 奇 ， 正 进 前 观 看 的 时 候 ， 有 主 的 声 音 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27148', '44', '7', '32', '‘ 我 是 你 列 祖 的 神 ， 就 是 亚 伯 拉 罕 的 神 ， 以 撒 的 神 ， 雅 各 的 神 。 ’ 摩 西 战 战 兢 兢 ， 不 敢 观 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27149', '44', '7', '33', '主 对 他 说 ： ‘ 把 你 脚 上 的 鞋 脱 下 来 ， 因 为 你 所 站 之 地 是 圣 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27150', '44', '7', '34', '我 的 百 姓 在 埃 及 所 受 的 困 苦 ， 我 实 在 看 见 了 ， 他 们 悲 叹 的 声 音 ， 我 也 听 见 了 。 我 下 来 要 救 他 们 。 你 来 ！ 我 要 差 你 往 埃 及 去 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27151', '44', '7', '35', '这 摩 西 就 是 百 姓 弃 绝 说 ‘ 谁 立 你 作 我 们 的 首 领 和 审 判 官 ’ 的 ； 神 却 藉 那 在 荆 棘 中 显 现 之 使 者 的 手 差 派 他 作 首 领 、 作 救 赎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27152', '44', '7', '36', '这 人 领 百 姓 出 来 ， 在 埃 及 ， 在 红 海 ， 在 旷 野 ， 四 十 年 间 行 了 奇 事 神 迹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27153', '44', '7', '37', '那 曾 对 以 色 列 人 说 ‘ 神 要 从 你 们 弟 兄 中 间 给 你 们 兴 起 一 位 先 知 像 我 ’ 的 ， 就 是 这 位 摩 西 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27154', '44', '7', '38', '这 人 曾 在 旷 野 会 中 和 西 奈 山 上 ， 与 那 对 他 说 话 的 天 使 同 在 ， 又 与 我 们 的 祖 宗 同 在 ， 并 且 领 受 活 泼 的 圣 言 传 给 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27155', '44', '7', '39', '我 们 的 祖 宗 不 肯 听 从 ， 反 弃 绝 他 ， 心 里 归 向 埃 及 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27156', '44', '7', '40', '对 亚 伦 说 ： ‘ 你 且 为 我 们 造 些 神 像 ， 在 我 们 前 面 引 路 ； 因 为 领 我 们 出 埃 及 地 的 那 个 摩 西 ， 我 们 不 知 道 他 遭 了 什 么 事 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27157', '44', '7', '41', '那 时 ， 他 们 造 了 一 个 牛 犊 ， 又 拿 祭 物 献 给 那 像 ， 欢 喜 自 己 手 中 的 工 作 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27158', '44', '7', '42', '神 就 转 脸 不 顾 ， 任 凭 他 们 事 奉 天 上 的 日 月 星 辰 ， 正 如 先 知 书 上 所 写 的 说 ： 以 色 列 家 啊 ， 你 们 四 十 年 间 在 旷 野 ， 岂 是 将 牺 牲 和 祭 物 献 给 我 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27159', '44', '7', '43', '你 们 抬 着 摩 洛 的 帐 幕 和 理 番 神 的 星 ， 就 是 你 们 所 造 为 要 敬 拜 的 像 。 因 此 ， 我 要 把 你 们 迁 到 巴 比 伦 外 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27160', '44', '7', '44', '“ 我 们 的 祖 宗 在 旷 野 ， 有 法 柜 的 帐 幕 ， 是 神 吩 咐 摩 西 叫 他 照 所 看 见 的 样 式 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27161', '44', '7', '45', '这 帐 幕 ， 我 们 的 祖 宗 相 继 承 受 。 当 神 在 他 们 面 前 赶 出 外 邦 人 去 的 时 候 ， 他 们 同 约 书 亚 把 帐 幕 搬 进 承 受 为 业 之 地 ， 直 存 到 大 卫 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27162', '44', '7', '46', '大 卫 在 神 面 前 蒙 恩 ， 祈 求 为 雅 各 的 神 预 备 居 所 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27163', '44', '7', '47', '却 是 所 罗 门 为 神 造 成 殿 宇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27164', '44', '7', '48', '其 实 ， 至 高 者 并 不 住 人 手 所 造 的 ， 就 如 先 知 所 言 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27165', '44', '7', '49', '主 说 ： 天 是 我 的 座 位 ， 地 是 我 的 脚 凳 ； 你 们 要 为 我 造 何 等 的 殿 宇 ？ 哪 里 是 我 安 息 的 地 方 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27166', '44', '7', '50', '这 一 切 不 都 是 我 手 所 造 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27167', '44', '7', '51', '“ 你 们 这 硬 着 颈 项 、 心 与 耳 未 受 割 礼 的 人 ， 常 时 抗 拒 圣 灵 ！ 你 们 的 祖 宗 怎 样 ， 你 们 也 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27168', '44', '7', '52', '哪 一 个 先 知 不 是 你 们 祖 宗 逼 迫 呢 ？ 他 们 也 把 预 先 传 说 那 义 者 要 来 的 人 杀 了 ； 如 今 你 们 又 把 那 义 者 卖 了 ， 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27169', '44', '7', '53', '你 们 受 了 天 使 所 传 的 律 法 ， 竟 不 遵 守 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27170', '44', '7', '54', '＜ 众 人 用 石 头 打 死 司 提 反 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27171', '44', '7', '55', '但 司 提 反 被 圣 灵 充 满 ， 定 睛 望 天 ， 看 见 神 的 荣 耀 ， 又 看 见 耶 稣 站 在 神 的 右 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27172', '44', '7', '56', '就 说 ： “ 我 看 见 天 开 了 ， 人 子 站 在 神 的 右 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27173', '44', '7', '57', '众 人 大 声 喊 叫 ， 捂 着 耳 朵 ， 齐 心 拥 上 前 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27174', '44', '7', '58', '把 他 推 到 城 外 ， 用 石 头 打 他 。 作 见 证 的 人 把 衣 裳 放 在 一 个 少 年 人 名 叫 扫 罗 的 脚 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27175', '44', '7', '59', '他 们 正 用 石 头 打 的 时 候 ， 司 提 反 呼 吁 主 说 ： “ 求 主 耶 稣 接 收 我 的 灵 魂 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27176', '44', '7', '60', '又 跪 下 大 声 喊 着 说 ： “ 主 啊 ， 不 要 将 这 罪 归 于 他 们 ！ ” 说 了 这 话 ， 就 睡 了 。 扫 罗 也 喜 悦 他 被 害 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27177', '44', '8', '1', '＜ 扫 罗 逼 迫 教 会 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27178', '44', '8', '2', '有 虔 诚 的 人 把 司 提 反 埋 葬 了 ， 为 他 捶 胸 大 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27179', '44', '8', '3', '扫 罗 却 残 害 教 会 ， 进 各 人 的 家 ， 拉 着 男 女 下 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27180', '44', '8', '4', '＜ 福 音 传 到 撒 马 利 亚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27181', '44', '8', '5', '腓 利 下 撒 马 利 亚 城 去 ， 宣 讲 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27182', '44', '8', '6', '众 人 听 见 了 ， 又 看 见 腓 利 所 行 的 神 迹 ， 就 同 心 合 意 地 听 从 他 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27183', '44', '8', '7', '因 为 有 许 多 人 被 污 鬼 附 着 ， 那 些 鬼 大 声 呼 叫 ， 从 他 们 身 上 出 来 ； 还 有 许 多 瘫 痪 的 、 瘸 腿 的 ， 都 得 了 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27184', '44', '8', '8', '在 那 城 里 ， 就 大 有 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27185', '44', '8', '9', '有 一 个 人 ， 名 叫 西 门 ， 向 来 在 那 城 里 行 邪 术 ， 妄 自 尊 大 ， 使 撒 马 利 亚 的 百 姓 惊 奇 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27186', '44', '8', '10', '无 论 大 小 都 听 从 他 ， 说 ： “ 这 人 就 是 那 称 为 神 的 大 能 者 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27187', '44', '8', '11', '他 们 听 从 他 ， 因 他 久 用 邪 术 ， 使 他 们 惊 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27188', '44', '8', '12', '及 至 他 们 信 了 腓 利 所 传 神 国 的 福 音 和 耶 稣 基 督 的 名 ， 连 男 带 女 就 受 了 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27189', '44', '8', '13', '西 门 自 己 也 信 了 ； 既 受 了 洗 ， 就 常 与 腓 利 在 一 处 ， 看 见 他 所 行 的 神 迹 和 大 异 能 ， 就 甚 惊 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27190', '44', '8', '14', '使 徒 在 耶 路 撒 冷 听 见 撒 马 利 亚 人 领 受 了 神 的 道 ， 就 打 发 彼 得 、 约 翰 往 他 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27191', '44', '8', '15', '两 个 人 到 了 ， 就 为 他 们 祷 告 ， 要 叫 他 们 受 圣 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27192', '44', '8', '16', '因 为 圣 灵 还 没 有 降 在 他 们 一 个 人 身 上 ， 他 们 只 奉 主 耶 稣 的 名 受 了 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27193', '44', '8', '17', '于 是 使 徒 按 手 在 他 们 头 上 ， 他 们 就 受 了 圣 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27194', '44', '8', '18', '西 门 看 见 使 徒 按 手 ， 便 有 圣 灵 赐 下 ， 就 拿 钱 给 使 徒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27195', '44', '8', '19', '说 ： “ 把 这 权 柄 也 给 我 ， 叫 我 手 按 着 谁 ， 谁 就 可 以 受 圣 灵 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27196', '44', '8', '20', '彼 得 说 ： “ 你 的 银 子 和 你 一 同 灭 亡 吧 ！ 因 你 想 神 的 恩 赐 是 可 以 用 钱 买 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27197', '44', '8', '21', '你 在 这 道 上 无 分 无 关 ； 因 为 在 神 面 前 ， 你 的 心 不 正 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27198', '44', '8', '22', '你 当 懊 悔 你 这 罪 恶 ， 祈 求 主 ， 或 者 你 心 里 的 意 念 可 得 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27199', '44', '8', '23', '我 看 出 你 正 在 苦 胆 之 中 ， 被 罪 恶 捆 绑 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27200', '44', '8', '24', '西 门 说 ： “ 愿 你 们 为 我 求 主 ， 叫 你 们 所 说 的 ， 没 有 一 样 临 到 我 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27201', '44', '8', '25', '使 徒 既 证 明 主 道 ， 而 且 传 讲 ， 就 回 耶 路 撒 冷 去 ， 一 路 在 撒 马 利 亚 好 些 村 庄 传 扬 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27202', '44', '8', '26', '＜ 腓 利 和 衣 索 匹 亚 的 太 监 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27203', '44', '8', '27', '腓 利 就 起 身 去 了 ， 不 料 ， 有 一 个 衣 索 匹 亚 ｛ 就 是 古 实 ， 见 以 赛 亚 十 八 章 一 节 ｝ 人 ， 是 个 有 大 权 的 太 监 ， 在 衣 索 匹 亚 女 王 甘 大 基 的 手 下 总 管 银 库 ， 他 上 耶 路 撒 冷 礼 拜 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27204', '44', '8', '28', '现 在 回 来 ， 在 车 上 坐 着 ， 念 先 知 以 赛 亚 的 书 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27205', '44', '8', '29', '圣 灵 对 腓 利 说 ： “ 你 去 ！ 贴 近 那 车 走 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27206', '44', '8', '30', '腓 利 就 跑 到 太 监 那 里 ， 听 见 他 念 先 知 以 赛 亚 的 书 ， 便 问 他 说 ： “ 你 所 念 的 ， 你 明 白 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27207', '44', '8', '31', '他 说 ： “ 没 有 人 指 教 我 ， 怎 能 明 白 呢 ？ ” 于 是 请 腓 利 上 车 ， 与 他 同 坐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27208', '44', '8', '32', '他 所 念 的 那 段 经 ， 说 ： 他 像 羊 被 牵 到 宰 杀 之 地 ， 又 像 羊 羔 在 剪 毛 的 人 手 下 无 声 ； 他 也 是 这 样 不 开 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27209', '44', '8', '33', '他 卑 微 的 时 候 ， 人 不 按 公 义 审 判 他 ｛ 原 文 是 他 的 审 判 被 夺 去 ｝ ； 谁 能 述 说 他 的 世 代 ？ 因 为 他 的 生 命 从 地 上 夺 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27210', '44', '8', '34', '太 监 对 腓 利 说 ： “ 请 问 ， 先 知 说 这 话 是 指 着 谁 ？ 是 指 着 自 己 呢 ？ 是 指 着 别 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27211', '44', '8', '35', '腓 利 就 开 口 从 这 经 上 起 ， 对 他 传 讲 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27212', '44', '8', '36', '二 人 正 往 前 走 ， 到 了 有 水 的 地 方 ， 太 监 说 ： “ 看 哪 ， 这 里 有 水 ， 我 受 洗 有 什 么 妨 碍 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27213', '44', '8', '37', '｛ 有 古 卷 加 ： 腓 利 说 ： “ 你 若 是 一 心 相 信 ， 就 可 以 。 ” 他 回 答 说 ： “ 我 信 耶 稣 基 督 是 神 的 儿 子 。 ” ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27214', '44', '8', '38', '于 是 吩 咐 车 站 住 ， 腓 利 和 太 监 二 人 同 下 水 里 去 ， 腓 利 就 给 他 施 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27215', '44', '8', '39', '从 水 里 上 来 ， 主 的 灵 把 腓 利 提 了 去 ， 太 监 也 不 再 见 他 了 ， 就 欢 欢 喜 喜 地 走 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27216', '44', '8', '40', '后 来 有 人 在 亚 锁 都 遇 见 腓 利 ； 他 走 遍 那 地 方 ， 在 各 城 宣 传 福 音 ， 直 到 凯 撒 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27217', '44', '9', '1', '＜ 扫 罗 的 转 变 （ 2 2 : 6 - 1 6 ； 2 6 : 1 2 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27218', '44', '9', '2', '求 文 书 给 大 马 士 革 的 各 会 堂 ， 若 是 找 着 信 奉 这 道 的 人 ， 无 论 男 女 ， 都 准 他 捆 绑 带 到 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27219', '44', '9', '3', '扫 罗 行 路 ， 将 到 大 马 士 革 ， 忽 然 从 天 上 发 光 ， 四 面 照 着 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27220', '44', '9', '4', '他 就 仆 倒 在 地 ， 听 见 有 声 音 对 他 说 ： “ 扫 罗 ！ 扫 罗 ！ 你 为 什 么 逼 迫 我 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27221', '44', '9', '5', '他 说 ： “ 主 啊 ！ 你 是 谁 ？ ” 主 说 ： “ 我 就 是 你 所 逼 迫 的 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27222', '44', '9', '6', '起 来 ！ 进 城 去 ， 你 所 当 做 的 事 ， 必 有 人 告 诉 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27223', '44', '9', '7', '同 行 的 人 站 在 那 里 ， 说 不 出 话 来 ， 听 见 声 音 ， 却 看 不 见 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27224', '44', '9', '8', '扫 罗 从 地 上 起 来 ， 睁 开 眼 睛 ， 竟 不 能 看 见 什 么 。 有 人 拉 他 的 手 ， 领 他 进 了 大 马 士 革 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27225', '44', '9', '9', '三 日 不 能 看 见 ， 也 不 吃 也 不 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27226', '44', '9', '10', '当 下 ， 在 大 马 士 革 有 一 个 门 徒 ， 名 叫 亚 拿 尼 亚 。 主 在 异 象 中 对 他 说 ： “ 亚 拿 尼 亚 。 ” 他 说 ： “ 主 ， 我 在 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27227', '44', '9', '11', '主 对 他 说 ： “ 起 来 ！ 往 直 街 去 ， 在 犹 大 的 家 里 ， 访 问 一 个 大 数 人 ， 名 叫 扫 罗 。 他 正 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27228', '44', '9', '12', '又 看 见 了 一 个 人 ， 名 叫 亚 拿 尼 亚 ， 进 来 按 手 在 他 身 上 ， 叫 他 能 看 见 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27229', '44', '9', '13', '亚 拿 尼 亚 回 答 说 ： “ 主 啊 ， 我 听 见 许 多 人 说 ： 这 人 怎 样 在 耶 路 撒 冷 多 多 苦 害 你 的 圣 徒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27230', '44', '9', '14', '并 且 他 在 这 里 有 从 祭 司 长 得 来 的 权 柄 捆 绑 一 切 求 告 你 名 的 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27231', '44', '9', '15', '主 对 亚 拿 尼 亚 说 ： “ 你 只 管 去 ！ 他 是 我 所 拣 选 的 器 皿 ， 要 在 外 邦 人 和 君 王 ， 并 以 色 列 人 面 前 宣 扬 我 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27232', '44', '9', '16', '我 也 要 指 示 他 ， 为 我 的 名 必 须 受 许 多 的 苦 难 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27233', '44', '9', '17', '亚 拿 尼 亚 就 去 了 ， 进 入 那 家 ， 把 手 按 在 扫 罗 身 上 ， 说 ： “ 兄 弟 扫 罗 ， 在 你 来 的 路 上 向 你 显 现 的 主 ， 就 是 耶 稣 ， 打 发 我 来 ， 叫 你 能 看 见 ， 又 被 圣 灵 充 满 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27234', '44', '9', '18', '扫 罗 的 眼 睛 上 ， 好 像 有 鳞 立 刻 掉 下 来 ， 他 就 能 看 见 。 于 是 起 来 受 了 洗 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27235', '44', '9', '19', '吃 过 饭 就 健 壮 了 。 扫 罗 和 大 马 士 革 的 门 徒 同 住 了 些 日 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27236', '44', '9', '20', '＜ 扫 罗 在 大 马 士 革 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27237', '44', '9', '21', '凡 听 见 的 人 都 惊 奇 ， 说 ： “ 在 耶 路 撒 冷 残 害 求 告 这 名 的 ， 不 是 这 人 吗 ？ 并 且 他 到 这 里 来 ， 特 要 捆 绑 他 们 ， 带 到 祭 司 长 那 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27238', '44', '9', '22', '但 扫 罗 越 发 有 能 力 ， 驳 倒 住 大 马 士 革 的 犹 太 人 ， 证 明 耶 稣 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27239', '44', '9', '23', '＜ 未 受 犹 太 人 的 谋 害 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27240', '44', '9', '24', '但 他 们 的 计 谋 被 扫 罗 知 道 了 。 他 们 又 昼 夜 在 城 门 守 候 ， 要 杀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27241', '44', '9', '25', '他 的 门 徒 就 在 夜 间 用 筐 子 把 他 从 城 墙 上 缒 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27242', '44', '9', '26', '＜ 扫 罗 在 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27243', '44', '9', '27', '惟 有 巴 拿 巴 接 待 他 ， 领 去 见 使 徒 ， 把 他 在 路 上 怎 么 看 见 主 ， 主 怎 么 向 他 说 话 ， 他 在 大 马 士 革 怎 么 奉 耶 稣 的 名 放 胆 传 道 ， 都 述 说 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27244', '44', '9', '28', '于 是 扫 罗 在 耶 路 撒 冷 和 门 徒 出 入 来 往 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27245', '44', '9', '29', '奉 主 的 名 放 胆 传 道 ， 并 与 说 希 腊 话 的 犹 太 人 讲 论 辩 驳 ； 他 们 却 想 法 子 要 杀 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27246', '44', '9', '30', '弟 兄 们 知 道 了 就 送 他 下 凯 撒 利 亚 ， 打 发 他 往 大 数 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27247', '44', '9', '31', '那 时 ， 犹 太 、 加 利 利 、 撒 马 利 亚 各 处 的 教 会 都 得 平 安 ， 被 建 立 ； 凡 事 敬 畏 主 ， 蒙 圣 灵 的 安 慰 ， 人 数 就 增 多 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27248', '44', '9', '32', '＜ 以 尼 雅 得 医 治 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27249', '44', '9', '33', '遇 见 一 个 人 ， 名 叫 以 尼 雅 ， 得 了 瘫 痪 ， 在 褥 子 上 躺 卧 八 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27250', '44', '9', '34', '彼 得 对 他 说 ： “ 以 尼 雅 ， 耶 稣 基 督 医 好 你 了 ， 起 来 ！ 收 拾 你 的 褥 子 。 ” 他 就 立 刻 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27251', '44', '9', '35', '凡 住 吕 大 和 沙 仑 的 人 都 看 见 了 他 ， 就 归 服 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27252', '44', '9', '36', '＜ 多 加 复 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27253', '44', '9', '37', '当 时 ， 她 患 病 而 死 ， 有 人 把 她 洗 了 ， 停 在 楼 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27254', '44', '9', '38', '吕 大 原 与 约 帕 相 近 ； 门 徒 听 见 彼 得 在 那 里 ， 就 打 发 两 个 人 去 见 他 ， 央 求 他 说 ： “ 快 到 我 们 那 里 去 ， 不 要 耽 延 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27255', '44', '9', '39', '彼 得 就 起 身 和 他 们 同 去 ； 到 了 ， 便 有 人 领 他 上 楼 。 众 寡 妇 都 站 在 彼 得 旁 边 哭 ， 拿 多 加 与 她 们 同 在 时 所 做 的 里 衣 外 衣 给 他 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27256', '44', '9', '40', '彼 得 叫 她 们 都 出 去 ， 就 跪 下 祷 告 ， 转 身 对 着 死 人 说 ： “ 大 比 大 ， 起 来 ！ ” 她 就 睁 开 眼 睛 ， 见 了 彼 得 ， 便 坐 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27257', '44', '9', '41', '彼 得 伸 手 扶 她 起 来 ， 叫 众 圣 徒 和 寡 妇 进 去 ， 把 多 加 活 活 地 交 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27258', '44', '9', '42', '这 事 传 遍 了 约 帕 ， 就 有 许 多 人 信 了 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27259', '44', '9', '43', '此 后 ， 彼 得 在 约 帕 一 个 硝 皮 匠 西 门 的 家 里 住 了 多 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27260', '44', '10', '1', '＜ 彼 得 和 哥 尼 流 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27261', '44', '10', '2', '他 是 个 虔 诚 人 ， 他 和 全 家 都 敬 畏 神 ， 多 多 赒 济 百 姓 ， 常 常 祷 告 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27262', '44', '10', '3', '有 一 天 ， 约 在 申 初 ， 他 在 异 象 中 明 明 看 见 神 的 一 个 使 者 进 去 ， 到 他 那 里 ， 说 ： “ 哥 尼 流 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27263', '44', '10', '4', '哥 尼 流 定 睛 看 他 ， 惊 怕 说 ： “ 主 啊 ， 什 么 事 呢 ？ ” 天 使 说 ： “ 你 的 祷 告 和 你 的 赒 济 达 到 神 面 前 ， 已 蒙 记 念 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27264', '44', '10', '5', '现 在 你 当 打 发 人 往 约 帕 去 ， 请 那 称 呼 彼 得 的 西 门 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27265', '44', '10', '6', '他 住 在 海 边 一 个 硝 皮 匠 西 门 的 家 里 ， 房 子 在 海 边 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27266', '44', '10', '7', '向 他 说 话 的 天 使 去 后 ， 哥 尼 流 叫 了 两 个 家 人 和 常 伺 候 他 的 一 个 虔 诚 兵 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27267', '44', '10', '8', '把 这 事 都 述 说 给 他 们 听 ， 就 打 发 他 们 往 约 帕 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27268', '44', '10', '9', '第 二 天 ， 他 们 行 路 将 近 那 城 。 彼 得 约 在 午 正 ， 上 房 顶 去 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27269', '44', '10', '10', '觉 得 饿 了 ， 想 要 吃 。 那 家 的 人 正 预 备 饭 的 时 候 ， 彼 得 魂 游 象 外 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27270', '44', '10', '11', '看 见 天 开 了 ， 有 一 物 降 下 ， 好 像 一 块 大 布 ， 系 着 四 角 ， 缒 在 地 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27271', '44', '10', '12', '里 面 有 地 上 各 样 四 足 的 走 兽 和 昆 虫 ， 并 天 上 的 飞 鸟 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27272', '44', '10', '13', '又 有 声 音 向 他 说 ： “ 彼 得 ， 起 来 ， 宰 了 吃 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27273', '44', '10', '14', '彼 得 却 说 ： “ 主 啊 ， 这 是 不 可 的 ！ 凡 俗 物 和 不 洁 净 的 物 ， 我 从 来 没 有 吃 过 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27274', '44', '10', '15', '第 二 次 有 声 音 向 他 说 ： “ 神 所 洁 净 的 ， 你 不 可 当 作 俗 物 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27275', '44', '10', '16', '这 样 一 连 三 次 ， 那 物 随 即 收 回 天 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27276', '44', '10', '17', '彼 得 心 里 正 在 猜 疑 之 间 ， 不 知 所 看 见 的 异 象 是 什 么 意 思 。 哥 尼 流 所 差 来 的 人 已 经 访 问 到 西 门 的 家 ， 站 在 门 外 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27277', '44', '10', '18', '喊 着 问 ： “ 有 称 呼 彼 得 的 西 门 住 在 这 里 没 有 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27278', '44', '10', '19', '彼 得 还 思 想 那 异 象 的 时 候 ， 圣 灵 向 他 说 ： “ 有 三 个 人 来 找 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27279', '44', '10', '20', '起 来 ， 下 去 ， 和 他 们 同 往 ， 不 要 疑 惑 ， 因 为 是 我 差 他 们 来 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27280', '44', '10', '21', '于 是 彼 得 下 去 见 那 些 人 ， 说 ： “ 我 就 是 你 们 所 找 的 人 。 你 们 来 是 为 什 么 缘 故 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27281', '44', '10', '22', '他 们 说 ： “ 百 夫 长 哥 尼 流 是 个 义 人 ， 敬 畏 神 ， 为 犹 太 通 国 所 称 赞 。 他 蒙 一 位 圣 天 使 指 示 ， 叫 他 请 你 到 他 家 里 去 ， 听 你 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27282', '44', '10', '23', '彼 得 就 请 他 们 进 去 ， 住 了 一 宿 。 次 日 ， 起 身 和 他 们 同 去 ， 还 有 约 帕 的 几 个 弟 兄 同 着 他 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27283', '44', '10', '24', '又 次 日 ， 他 们 进 入 凯 撒 利 亚 ， 哥 尼 流 已 经 请 了 他 的 亲 属 密 友 等 候 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27284', '44', '10', '25', '彼 得 一 进 去 ， 哥 尼 流 就 迎 接 他 ， 俯 伏 在 他 脚 前 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27285', '44', '10', '26', '彼 得 却 拉 他 ， 说 ： “ 你 起 来 ， 我 也 是 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27286', '44', '10', '27', '彼 得 和 他 说 着 话 进 去 ， 见 有 好 些 人 在 那 里 聚 集 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27287', '44', '10', '28', '就 对 他 们 说 ： “ 你 们 知 道 ， 犹 太 人 和 别 国 的 人 亲 近 来 往 本 是 不 合 例 的 ， 但 神 已 经 指 示 我 ， 无 论 什 么 人 都 不 可 看 作 俗 而 不 洁 净 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27288', '44', '10', '29', '所 以 我 被 请 的 时 候 ， 就 不 推 辞 而 来 。 现 在 请 问 ： 你 们 叫 我 来 有 什 么 意 思 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27289', '44', '10', '30', '哥 尼 流 说 ： “ 前 四 天 ， 这 个 时 候 ， 我 在 家 中 守 着 申 初 的 祷 告 ， 忽 然 有 一 个 人 穿 着 光 明 的 衣 裳 ， 站 在 我 面 前 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27290', '44', '10', '31', '说 ： ‘ 哥 尼 流 ， 你 的 祷 告 已 蒙 垂 听 ， 你 的 赒 济 达 到 神 面 前 已 蒙 记 念 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27291', '44', '10', '32', '你 当 打 发 人 往 约 帕 去 ， 请 那 称 呼 彼 得 的 西 门 来 ， 他 住 在 海 边 一 个 硝 皮 匠 西 门 的 家 里 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27292', '44', '10', '33', '所 以 我 立 时 打 发 人 去 请 你 。 你 来 了 很 好 ； 现 今 我 们 都 在 神 面 前 ， 要 听 主 所 吩 咐 你 的 一 切 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27293', '44', '10', '34', '＜ 在 哥 尼 流 家 中 讲 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27294', '44', '10', '35', '原 来 ， 各 国 中 那 敬 畏 主 、 行 义 的 人 都 为 主 所 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27295', '44', '10', '36', '神 藉 着 耶 稣 基 督 （ 他 是 万 有 的 主 ） 传 和 平 的 福 音 ， 将 这 道 赐 给 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27296', '44', '10', '37', '这 话 在 约 翰 宣 传 洗 礼 以 后 ， 从 加 利 利 起 ， 传 遍 了 犹 太 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27297', '44', '10', '38', '神 怎 样 以 圣 灵 和 能 力 膏 拿 撒 勒 人 耶 稣 ， 这 都 是 你 们 知 道 的 。 他 周 流 四 方 ， 行 善 事 ， 医 好 凡 被 魔 鬼 压 制 的 人 ， 因 为 神 与 他 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27298', '44', '10', '39', '他 在 犹 太 人 之 地 ， 并 耶 路 撒 冷 所 行 的 一 切 事 ， 有 我 们 作 见 证 。 他 们 竟 把 他 挂 在 木 头 上 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27299', '44', '10', '40', '第 三 日 ， 神 叫 他 复 活 ， 显 现 出 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27300', '44', '10', '41', '不 是 显 现 给 众 人 看 ， 乃 是 显 现 给 神 预 先 所 拣 选 为 他 作 见 证 的 人 看 ， 就 是 我 们 这 些 在 他 从 死 里 复 活 以 后 和 他 同 吃 同 喝 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27301', '44', '10', '42', '他 吩 咐 我 们 传 道 给 众 人 ， 证 明 他 是 神 所 立 定 的 ， 要 作 审 判 活 人 、 死 人 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27302', '44', '10', '43', '众 先 知 也 为 他 作 见 证 说 ： ‘ 凡 信 他 的 人 必 因 他 的 名 得 蒙 赦 罪 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27303', '44', '10', '44', '＜ 外 邦 人 领 受 圣 灵 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27304', '44', '10', '45', '那 些 奉 割 礼 、 和 彼 得 同 来 的 信 徒 ， 见 圣 灵 的 恩 赐 也 浇 在 外 邦 人 身 上 ， 就 都 希 奇 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27305', '44', '10', '46', '因 听 见 他 们 说 方 言 ， 称 赞 神 为 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27306', '44', '10', '47', '于 是 彼 得 说 ： “ 这 些 人 既 受 了 圣 灵 ， 与 我 们 一 样 ， 谁 能 禁 止 用 水 给 他 们 施 洗 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27307', '44', '10', '48', '就 吩 咐 奉 耶 稣 基 督 的 名 给 他 们 施 洗 。 他 们 又 请 彼 得 住 了 几 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27308', '44', '11', '1', '＜ 向 耶 路 撒 冷 教 会 报 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27309', '44', '11', '2', '及 至 彼 得 上 了 耶 路 撒 冷 ， 那 些 奉 割 礼 的 门 徒 和 他 争 辩 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27310', '44', '11', '3', '“ 你 进 入 未 受 割 礼 之 人 的 家 和 他 们 一 同 吃 饭 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27311', '44', '11', '4', '彼 得 就 开 口 把 这 事 挨 次 给 他 们 讲 解 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27312', '44', '11', '5', '“ 我 在 约 帕 城 里 祷 告 的 时 候 ， 魂 游 象 外 ， 看 见 异 象 ， 有 一 物 降 下 ， 好 像 一 块 大 布 ， 系 着 四 角 ， 从 天 缒 下 ， 直 来 到 我 跟 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27313', '44', '11', '6', '我 定 睛 观 看 ， 见 内 中 有 地 上 四 足 的 牲 畜 和 野 兽 、 昆 虫 ， 并 天 上 的 飞 鸟 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27314', '44', '11', '7', '我 且 听 见 有 声 音 向 我 说 ： ‘ 彼 得 ， 起 来 ， 宰 了 吃 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27315', '44', '11', '8', '我 说 ： ‘ 主 啊 ， 这 是 不 可 的 ！ 凡 俗 而 不 洁 净 的 物 从 来 没 有 入 过 我 的 口 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27316', '44', '11', '9', '第 二 次 ， 有 声 音 从 天 上 说 ： ‘ 神 所 洁 净 的 ， 你 不 可 当 作 俗 物 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27317', '44', '11', '10', '这 样 一 连 三 次 ， 就 都 收 回 天 上 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27318', '44', '11', '11', '正 当 那 时 ， 有 三 个 人 站 在 我 们 所 住 的 房 门 前 ， 是 从 凯 撒 利 亚 差 来 见 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27319', '44', '11', '12', '圣 灵 吩 咐 我 和 他 们 同 去 ， 不 要 疑 惑 ｛ 或 译 ： 不 要 分 别 等 类 ｝ 。 同 着 我 去 的 ， 还 有 这 六 位 弟 兄 ， 我 们 都 进 了 那 人 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27320', '44', '11', '13', '那 人 就 告 诉 我 们 ， 他 如 何 看 见 一 位 天 使 站 在 他 屋 里 ， 说 ： ‘ 你 打 发 人 往 约 帕 去 ， 请 那 称 呼 彼 得 的 西 门 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27321', '44', '11', '14', '他 有 话 告 诉 你 ， 可 以 叫 你 和 你 的 全 家 得 救 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27322', '44', '11', '15', '我 一 开 讲 ， 圣 灵 便 降 在 他 们 身 上 ， 正 像 当 初 降 在 我 们 身 上 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27323', '44', '11', '16', '我 就 想 起 主 的 话 说 ： ‘ 约 翰 是 用 水 施 洗 ， 但 你 们 要 受 圣 灵 的 洗 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27324', '44', '11', '17', '神 既 然 给 他 们 恩 赐 ， 像 在 我 们 信 主 耶 稣 基 督 的 时 候 给 了 我 们 一 样 ； 我 是 谁 ， 能 拦 阻 神 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27325', '44', '11', '18', '众 人 听 见 这 话 ， 就 不 言 语 了 ， 只 归 荣 耀 与 神 ， 说 ： “ 这 样 看 来 ， 神 也 赐 恩 给 外 邦 人 ， 叫 他 们 悔 改 得 生 命 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27326', '44', '11', '19', '＜ 安 提 阿 的 教 会 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27327', '44', '11', '20', '但 内 中 有 塞 浦 路 斯 和 古 利 奈 人 ， 他 们 到 了 安 提 阿 也 向 希 腊 人 传 讲 主 耶 稣 ｛ 有 古 卷 ： 也 向 说 希 腊 话 的 犹 太 人 传 讲 主 耶 稣 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27328', '44', '11', '21', '主 与 他 们 同 在 ， 信 而 归 主 的 人 就 很 多 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27329', '44', '11', '22', '这 风 声 传 到 耶 路 撒 冷 教 会 人 的 耳 中 ， 他 们 就 打 发 巴 拿 巴 出 去 ， 走 到 安 提 阿 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27330', '44', '11', '23', '他 到 了 那 里 ， 看 见 神 所 赐 的 恩 就 欢 喜 ， 劝 勉 众 人 ， 立 定 心 志 ， 恒 久 靠 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27331', '44', '11', '24', '这 巴 拿 巴 原 是 个 好 人 ， 被 圣 灵 充 满 ， 大 有 信 心 。 于 是 有 许 多 人 归 服 了 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27332', '44', '11', '25', '他 又 往 大 数 去 找 扫 罗 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27333', '44', '11', '26', '找 着 了 ， 就 带 他 到 安 提 阿 去 。 他 们 足 有 一 年 的 工 夫 和 教 会 一 同 聚 集 ， 教 训 了 许 多 人 。 门 徒 称 为 “ 基 督 徒 ” 是 从 安 提 阿 起 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27334', '44', '11', '27', '当 那 些 日 子 ， 有 几 位 先 知 从 耶 路 撒 冷 下 到 安 提 阿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27335', '44', '11', '28', '内 中 有 一 位 ， 名 叫 亚 迦 布 ， 站 起 来 ， 藉 着 圣 灵 指 明 天 下 将 有 大 饥 荒 。 （ 这 事 到 克 劳 第 年 间 果 然 有 了 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27336', '44', '11', '29', '于 是 门 徒 定 意 照 各 人 的 力 量 捐 钱 ， 送 去 供 给 住 在 犹 太 的 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27337', '44', '11', '30', '他 们 就 这 样 行 ， 把 捐 项 托 巴 拿 巴 和 扫 罗 送 到 众 长 老 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27338', '44', '12', '1', '＜ 雅 各 被 杀 ， 彼 得 被 囚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27339', '44', '12', '2', '用 刀 杀 了 约 翰 的 哥 哥 雅 各 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27340', '44', '12', '3', '他 见 犹 太 人 喜 欢 这 事 ， 又 去 捉 拿 彼 得 。 那 时 正 是 除 酵 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27341', '44', '12', '4', '希 律 拿 了 彼 得 ， 收 在 监 里 ， 交 付 四 班 兵 丁 看 守 ， 每 班 四 个 人 ， 意 思 要 在 逾 越 节 后 把 他 提 出 来 ， 当 着 百 姓 办 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27342', '44', '12', '5', '于 是 彼 得 被 囚 在 监 里 ； 教 会 却 为 他 切 切 地 祷 告 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27343', '44', '12', '6', '＜ 彼 得 获 救 出 狱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27344', '44', '12', '7', '忽 然 ， 有 主 的 一 个 使 者 站 在 旁 边 ， 屋 里 有 光 照 耀 ， 天 使 拍 彼 得 的 肋 旁 ， 拍 醒 了 他 ， 说 ： “ 快 快 起 来 ！ ” 那 铁 链 就 从 他 手 上 脱 落 下 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27345', '44', '12', '8', '天 使 对 他 说 ： “ 束 上 带 子 ， 穿 上 鞋 。 ” 他 就 那 样 做 。 天 使 又 说 ： “ 披 上 外 衣 ， 跟 着 我 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27346', '44', '12', '9', '彼 得 就 出 来 跟 着 他 ， 不 知 道 天 使 所 做 是 真 的 ， 只 当 见 了 异 象 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27347', '44', '12', '10', '过 了 第 一 层 第 二 层 监 牢 ， 就 来 到 临 街 的 铁 门 ， 那 门 自 己 开 了 。 他 们 出 来 ， 走 过 一 条 街 ， 天 使 便 离 开 他 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27348', '44', '12', '11', '彼 得 醒 悟 过 来 ， 说 ： “ 我 现 在 真 知 道 主 差 遣 他 的 使 者 ， 救 我 脱 离 希 律 的 手 和 犹 太 百 姓 一 切 所 盼 望 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27349', '44', '12', '12', '想 了 一 想 ， 就 往 那 称 呼 马 可 的 约 翰 、 他 母 亲 马 利 亚 家 去 ， 在 那 里 有 好 些 人 聚 集 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27350', '44', '12', '13', '彼 得 敲 外 门 ， 有 一 个 使 女 ， 名 叫 罗 大 ， 出 来 探 听 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27351', '44', '12', '14', '听 得 是 彼 得 的 声 音 ， 就 欢 喜 的 顾 不 得 开 门 ， 跑 进 去 告 诉 众 人 说 ： “ 彼 得 站 在 门 外 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27352', '44', '12', '15', '他 们 说 ： “ 你 是 疯 了 ！ ” 使 女 极 力 地 说 ： “ 真 是 他 ！ ” 他 们 说 ： “ 必 是 他 的 天 使 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27353', '44', '12', '16', '彼 得 不 住 地 敲 门 。 他 们 开 了 门 ， 看 见 他 ， 就 甚 惊 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27354', '44', '12', '17', '彼 得 摆 手 ， 不 要 他 们 作 声 ， 就 告 诉 他 们 主 怎 样 领 他 出 监 ； 又 说 ： “ 你 们 把 这 事 告 诉 雅 各 和 众 弟 兄 。 ” 于 是 出 去 ， 往 别 处 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27355', '44', '12', '18', '到 了 天 亮 ， 兵 丁 扰 乱 得 很 ， 不 知 道 彼 得 往 哪 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27356', '44', '12', '19', '希 律 找 他 ， 找 不 着 ， 就 审 问 看 守 的 人 ， 吩 咐 把 他 们 拉 去 杀 了 。 后 来 希 律 离 开 犹 太 ， 下 凯 撒 利 亚 去 ， 住 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27357', '44', '12', '20', '＜ 希 律 的 死 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27358', '44', '12', '21', '希 律 在 所 定 的 日 子 ， 穿 上 朝 服 ， 坐 在 位 上 ， 对 他 们 讲 论 一 番 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27359', '44', '12', '22', '百 姓 喊 着 说 ： “ 这 是 神 的 声 音 ， 不 是 人 的 声 音 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27360', '44', '12', '23', '希 律 不 归 荣 耀 给 神 ， 所 以 主 的 使 者 立 刻 罚 他 ， 他 被 虫 所 咬 ， 气 就 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27361', '44', '12', '24', '神 的 道 日 见 兴 旺 ， 越 发 广 传 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27362', '44', '12', '25', '巴 拿 巴 和 扫 罗 办 完 了 他 们 供 给 的 事 ， 就 从 耶 路 撒 冷 回 来 ， 带 著 称 呼 马 可 的 约 翰 同 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27363', '44', '13', '1', '＜ 巴 拿 巴 和 扫 罗 奉 差 遣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27364', '44', '13', '2', '他 们 事 奉 主 、 禁 食 的 时 候 ， 圣 灵 说 ： “ 要 为 我 分 派 巴 拿 巴 和 扫 罗 ， 去 做 我 召 他 们 所 做 的 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27365', '44', '13', '3', '于 是 禁 食 祷 告 ， 按 手 在 他 们 头 上 ， 就 打 发 他 们 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27366', '44', '13', '4', '＜ 在 塞 浦 路 斯 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27367', '44', '13', '5', '到 了 撒 拉 米 ， 就 在 犹 太 人 各 会 堂 里 传 讲 神 的 道 ， 也 有 约 翰 作 他 们 的 帮 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27368', '44', '13', '6', '经 过 全 岛 ， 直 到 帕 弗 ， 在 那 里 遇 见 一 个 有 法 术 、 假 充 先 知 的 犹 太 人 ， 名 叫 巴 ． 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27369', '44', '13', '7', '这 人 常 和 方 伯 士 求 ． 保 罗 同 在 。 士 求 ． 保 罗 是 个 通 达 人 ， 他 请 了 巴 拿 巴 和 扫 罗 来 ， 要 听 神 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27370', '44', '13', '8', '只 是 那 行 法 术 的 以 吕 马 （ 这 名 翻 出 来 就 是 行 法 术 的 意 思 ） 敌 挡 使 徒 ， 要 叫 方 伯 不 信 真 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27371', '44', '13', '9', '扫 罗 又 名 保 罗 ， 被 圣 灵 充 满 ， 定 睛 看 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27372', '44', '13', '10', '说 ： “ 你 这 充 满 各 样 诡 诈 奸 恶 ， 魔 鬼 的 儿 子 ， 众 善 的 仇 敌 ， 你 混 乱 主 的 正 道 还 不 止 住 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27373', '44', '13', '11', '现 在 主 的 手 加 在 你 身 上 ， 你 要 瞎 眼 ， 暂 且 不 见 日 光 。 ” 他 的 眼 睛 立 刻 昏 蒙 黑 暗 ， 四 下 里 求 人 拉 着 手 领 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27374', '44', '13', '12', '方 伯 看 见 所 做 的 事 ， 很 希 奇 主 的 道 ， 就 信 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27375', '44', '13', '13', '＜ 在 彼 西 底 的 安 提 阿 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27376', '44', '13', '14', '他 们 离 了 别 加 往 前 行 ， 来 到 彼 西 底 的 安 提 阿 ， 在 安 息 日 进 会 堂 坐 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27377', '44', '13', '15', '读 完 了 律 法 和 先 知 的 书 ， 管 会 堂 的 叫 人 过 去 ， 对 他 们 说 ： “ 二 位 兄 台 ， 若 有 什 么 劝 勉 众 人 的 话 ， 请 说 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27378', '44', '13', '16', '保 罗 就 站 起 来 ， 举 手 ， 说 ： “ 以 色 列 人 和 一 切 敬 畏 神 的 人 ， 请 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27379', '44', '13', '17', '这 以 色 列 民 的 神 拣 选 了 我 们 的 祖 宗 ， 当 民 寄 居 埃 及 的 时 候 抬 举 他 们 ， 用 大 能 的 手 领 他 们 出 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27380', '44', '13', '18', '又 在 旷 野 容 忍 ｛ 或 译 ： 抚 养 ｝ 他 们 ， 约 有 四 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27381', '44', '13', '19', '既 灭 了 迦 南 地 七 族 的 人 ， 就 把 那 地 分 给 他 们 为 业 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27382', '44', '13', '20', '此 后 给 他 们 设 立 士 师 ， 约 有 四 百 五 十 年 ， 直 到 先 知 撒 母 耳 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27383', '44', '13', '21', '后 来 他 们 求 一 个 王 ， 神 就 将 便 雅 悯 支 派 中 基 士 的 儿 子 扫 罗 ， 给 他 们 作 王 四 十 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27384', '44', '13', '22', '既 废 了 扫 罗 ， 就 选 立 大 卫 作 他 们 的 王 ， 又 为 他 作 见 证 说 ： ‘ 我 寻 得 耶 西 的 儿 子 大 卫 ， 他 是 合 我 心 意 的 人 ， 凡 事 要 遵 行 我 的 旨 意 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27385', '44', '13', '23', '从 这 人 的 后 裔 中 ， 神 已 经 照 着 所 应 许 的 ， 为 以 色 列 人 立 了 一 位 救 主 ， 就 是 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27386', '44', '13', '24', '在 他 没 有 出 来 以 先 ， 约 翰 向 以 色 列 众 民 宣 讲 悔 改 的 洗 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27387', '44', '13', '25', '约 翰 将 行 尽 他 的 程 途 说 ： ‘ 你 们 以 为 我 是 谁 ？ 我 不 是 基 督 ； 只 是 有 一 位 在 我 以 后 来 的 ， 我 解 他 脚 上 的 鞋 带 也 是 不 配 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27388', '44', '13', '26', '“ 弟 兄 们 ， 亚 伯 拉 罕 的 子 孙 和 你 们 中 间 敬 畏 神 的 人 哪 ， 这 救 世 的 道 是 传 给 我 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27389', '44', '13', '27', '耶 路 撒 冷 居 住 的 人 和 他 们 的 官 长 ， 因 为 不 认 识 基 督 ， 也 不 明 白 每 安 息 日 所 读 众 先 知 的 书 ， 就 把 基 督 定 了 死 罪 ， 正 应 了 先 知 的 预 言 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27390', '44', '13', '28', '虽 然 查 不 出 他 有 当 死 的 罪 来 ， 还 是 求 彼 拉 多 杀 他 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27391', '44', '13', '29', '既 成 就 了 经 上 指 着 他 所 记 的 一 切 话 ， 就 把 他 从 木 头 上 取 下 来 ， 放 在 坟 墓 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27392', '44', '13', '30', '神 却 叫 他 从 死 里 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27393', '44', '13', '31', '那 从 加 利 利 同 他 上 耶 路 撒 冷 的 人 多 日 看 见 他 ， 这 些 人 如 今 在 民 间 是 他 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27394', '44', '13', '32', '我 们 也 报 好 信 息 给 你 们 ， 就 是 那 应 许 祖 宗 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27395', '44', '13', '33', '神 已 经 向 我 们 这 作 儿 女 的 应 验 ， 叫 耶 稣 复 活 了 。 正 如 诗 篇 第 二 篇 上 记 着 说 ： 你 是 我 的 儿 子 ， 我 今 日 生 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27396', '44', '13', '34', '论 到 神 叫 他 从 死 里 复 活 ， 不 再 归 于 朽 坏 ， 就 这 样 说 ： 我 必 将 所 应 许 大 卫 那 圣 洁 、 可 靠 的 恩 典 赐 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27397', '44', '13', '35', '又 有 一 篇 上 说 ： 你 必 不 叫 你 的 圣 者 见 朽 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27398', '44', '13', '36', '“ 大 卫 在 世 的 时 候 遵 行 了 神 的 旨 意 ， 就 睡 了 ｛ 或 译 ： 大 卫 按 神 的 旨 意 服 事 了 他 那 一 世 的 人 ， 就 睡 了 ｝ ， 归 到 他 祖 宗 那 里 ， 已 见 朽 坏 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27399', '44', '13', '37', '惟 独 神 所 复 活 的 ， 他 并 未 见 朽 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27400', '44', '13', '38', '所 以 ， 弟 兄 们 ， 你 们 当 晓 得 ： 赦 罪 的 道 是 由 这 人 传 给 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27401', '44', '13', '39', '你 们 靠 摩 西 的 律 法 ， 在 一 切 不 得 称 义 的 事 上 信 靠 这 人 ， 就 都 得 称 义 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27402', '44', '13', '40', '所 以 ， 你 们 务 要 小 心 ， 免 得 先 知 书 上 所 说 的 临 到 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27403', '44', '13', '41', '主 说 ： 你 们 这 轻 慢 的 人 要 观 看 ， 要 惊 奇 ， 要 灭 亡 ； 因 为 在 你 们 的 时 候 ， 我 行 一 件 事 ， 虽 有 人 告 诉 你 们 ， 你 们 总 是 不 信 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27404', '44', '13', '42', '他 们 出 会 堂 的 时 候 ， 众 人 请 他 们 到 下 安 息 日 再 讲 这 话 给 他 们 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27405', '44', '13', '43', '散 会 以 后 ， 犹 太 人 和 敬 虔 进 犹 太 教 的 人 多 有 跟 从 保 罗 、 巴 拿 巴 的 。 二 人 对 他 们 讲 道 ， 劝 他 们 务 要 恒 久 在 神 的 恩 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27406', '44', '13', '44', '到 下 安 息 日 ， 合 城 的 人 几 乎 都 来 聚 集 ， 要 听 神 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27407', '44', '13', '45', '但 犹 太 人 看 见 人 这 样 多 ， 就 满 心 嫉 妒 ， 硬 驳 保 罗 所 说 的 话 ， 并 且 毁 谤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27408', '44', '13', '46', '保 罗 和 巴 拿 巴 放 胆 说 ： “ 神 的 道 先 讲 给 你 们 原 是 应 当 的 ； 只 因 你 们 弃 绝 这 道 ， 断 定 自 己 不 配 得 永 生 ， 我 们 就 转 向 外 邦 人 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27409', '44', '13', '47', '因 为 主 曾 这 样 吩 咐 我 们 说 ： 我 已 经 立 你 作 外 邦 人 的 光 ， 叫 你 施 行 救 恩 ， 直 到 地 极 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27410', '44', '13', '48', '外 邦 人 听 见 这 话 ， 就 欢 喜 了 ， 赞 美 神 的 道 ； 凡 预 定 得 永 生 的 人 都 信 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27411', '44', '13', '49', '于 是 主 的 道 传 遍 了 那 一 带 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27412', '44', '13', '50', '但 犹 太 人 挑 唆 虔 敬 、 尊 贵 的 妇 女 和 城 内 有 名 望 的 人 ， 逼 迫 保 罗 、 巴 拿 巴 ， 将 他 们 赶 出 境 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27413', '44', '13', '51', '二 人 对 着 众 人 跺 下 脚 上 的 尘 土 ， 就 往 以 哥 念 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27414', '44', '13', '52', '门 徒 满 心 喜 乐 ， 又 被 圣 灵 充 满 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27415', '44', '14', '1', '＜ 在 以 哥 念 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27416', '44', '14', '2', '但 那 不 顺 从 的 犹 太 人 耸 动 外 邦 人 ， 叫 他 们 心 里 恼 恨 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27417', '44', '14', '3', '二 人 在 那 里 住 了 多 日 ， 倚 靠 主 放 胆 讲 道 ； 主 藉 他 们 的 手 施 行 神 迹 奇 事 ， 证 明 他 的 恩 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27418', '44', '14', '4', '城 里 的 众 人 就 分 了 党 ， 有 附 从 犹 太 人 的 ， 有 附 从 使 徒 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27419', '44', '14', '5', '那 时 ， 外 邦 人 和 犹 太 人 ， 并 他 们 的 官 长 ， 一 齐 拥 上 来 ， 要 凌 辱 使 徒 ， 用 石 头 打 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27420', '44', '14', '6', '使 徒 知 道 了 ， 就 逃 往 吕 高 尼 的 路 司 得 、 特 庇 两 个 城 和 周 围 地 方 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27421', '44', '14', '7', '在 那 里 传 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27422', '44', '14', '8', '＜ 在 路 司 得 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27423', '44', '14', '9', '他 听 保 罗 讲 道 ， 保 罗 定 睛 看 他 ， 见 他 有 信 心 ， 可 得 痊 愈 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27424', '44', '14', '10', '就 大 声 说 ： “ 你 起 来 ， 两 脚 站 直 ！ ” 那 人 就 跳 起 来 ， 而 且 行 走 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27425', '44', '14', '11', '众 人 看 见 保 罗 所 做 的 事 ， 就 用 吕 高 尼 的 话 大 声 说 ： “ 有 神 藉 着 人 形 降 临 在 我 们 中 间 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27426', '44', '14', '12', '于 是 称 巴 拿 巴 为 宙 斯 ， 称 保 罗 为 希 耳 米 ， 因 为 他 说 话 领 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27427', '44', '14', '13', '有 城 外 宙 斯 庙 的 祭 司 牵 着 牛 ， 拿 着 花 圈 ， 来 到 门 前 ， 要 同 众 人 向 使 徒 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27428', '44', '14', '14', '巴 拿 巴 、 保 罗 二 使 徒 听 见 ， 就 撕 开 衣 裳 ， 跳 进 众 人 中 间 ， 喊 着 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27429', '44', '14', '15', '“ 诸 君 ， 为 什 么 做 这 事 呢 ？ 我 们 也 是 人 ， 性 情 和 你 们 一 样 。 我 们 传 福 音 给 你 们 ， 是 叫 你 们 离 弃 这 些 虚 妄 ， 归 向 那 创 造 天 、 地 、 海 ， 和 其 中 万 物 的 永 生 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27430', '44', '14', '16', '他 在 从 前 的 世 代 ， 任 凭 万 国 各 行 其 道 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27431', '44', '14', '17', '然 而 为 自 己 未 尝 不 显 出 证 据 来 ， 就 如 常 施 恩 惠 ， 从 天 降 雨 ， 赏 赐 丰 年 ， 叫 你 们 饮 食 饱 足 ， 满 心 喜 乐 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27432', '44', '14', '18', '二 人 说 了 这 些 话 ， 仅 仅 地 拦 住 众 人 不 献 祭 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27433', '44', '14', '19', '但 有 些 犹 太 人 从 安 提 阿 和 以 哥 念 来 ， 挑 唆 众 人 ， 就 用 石 头 打 保 罗 ， 以 为 他 是 死 了 ， 便 拖 到 城 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27434', '44', '14', '20', '门 徒 正 围 着 他 ， 他 就 起 来 ， 走 进 城 去 。 第 二 天 ， 同 巴 拿 巴 往 特 庇 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27435', '44', '14', '21', '＜ 回 到 叙 利 亚 的 安 提 阿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27436', '44', '14', '22', '坚 固 门 徒 的 心 ， 劝 他 们 恒 守 所 信 的 道 ； 又 说 ： “ 我 们 进 入 神 的 国 ， 必 须 经 历 许 多 艰 难 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27437', '44', '14', '23', '二 人 在 各 教 会 中 选 立 了 长 老 ， 又 禁 食 祷 告 ， 就 把 他 们 交 托 所 信 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27438', '44', '14', '24', '二 人 经 过 彼 西 底 ， 来 到 旁 非 利 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27439', '44', '14', '25', '在 别 加 讲 了 道 ， 就 下 亚 大 利 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27440', '44', '14', '26', '从 那 里 坐 船 ， 往 安 提 阿 去 。 当 初 ， 他 们 被 众 人 所 托 、 蒙 神 之 恩 、 要 办 现 在 所 做 之 工 ， 就 是 在 这 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27441', '44', '14', '27', '到 了 那 里 ， 聚 集 了 会 众 ， 就 述 说 神 藉 他 们 所 行 的 一 切 事 ， 并 神 怎 样 为 外 邦 人 开 了 信 道 的 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27442', '44', '14', '28', '二 人 就 在 那 里 同 门 徒 住 了 多 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27443', '44', '15', '1', '＜ 耶 路 撒 冷 会 议 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27444', '44', '15', '2', '保 罗 、 巴 拿 巴 与 他 们 大 大 地 纷 争 辩 论 ； 众 门 徒 就 定 规 ， 叫 保 罗 、 巴 拿 巴 和 本 会 中 几 个 人 ， 为 所 辩 论 的 ， 上 耶 路 撒 冷 去 见 使 徒 和 长 老 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27445', '44', '15', '3', '于 是 教 会 送 他 们 起 行 。 他 们 经 过 腓 尼 基 、 撒 马 利 亚 ， 随 处 传 说 外 邦 人 归 主 的 事 ， 叫 众 弟 兄 都 甚 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27446', '44', '15', '4', '到 了 耶 路 撒 冷 ， 教 会 和 使 徒 并 长 老 都 接 待 他 们 ， 他 们 就 述 说 神 同 他 们 所 行 的 一 切 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27447', '44', '15', '5', '惟 有 几 个 信 徒 ， 是 法 利 赛 教 门 的 人 ， 起 来 说 ： “ 必 须 给 外 邦 人 行 割 礼 ， 吩 咐 他 们 遵 守 摩 西 的 律 法 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27448', '44', '15', '6', '使 徒 和 长 老 聚 会 商 议 这 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27449', '44', '15', '7', '辩 论 已 经 多 了 ， 彼 得 就 起 来 ， 说 ： “ 诸 位 弟 兄 ， 你 们 知 道 神 早 已 在 你 们 中 间 拣 选 了 我 ， 叫 外 邦 人 从 我 口 中 得 听 福 音 之 道 ， 而 且 相 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27450', '44', '15', '8', '知 道 人 心 的 神 也 为 他 们 作 了 见 证 ， 赐 圣 灵 给 他 们 ， 正 如 给 我 们 一 样 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27451', '44', '15', '9', '又 藉 着 信 洁 净 了 他 们 的 心 ， 并 不 分 他 们 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27452', '44', '15', '10', '现 在 为 什 么 试 探 神 ， 要 把 我 们 祖 宗 和 我 们 所 不 能 负 的 轭 放 在 门 徒 的 颈 项 上 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27453', '44', '15', '11', '我 们 得 救 乃 是 因 主 耶 稣 的 恩 ， 和 他 们 一 样 ， 这 是 我 们 所 信 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27454', '44', '15', '12', '众 人 都 默 默 无 声 ， 听 巴 拿 巴 和 保 罗 述 说 神 藉 他 们 在 外 邦 人 中 所 行 的 神 迹 奇 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27455', '44', '15', '13', '他 们 住 了 声 ， 雅 各 就 说 ： “ 诸 位 弟 兄 ， 请 听 我 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27456', '44', '15', '14', '方 才 西 门 述 说 神 当 初 怎 样 眷 顾 外 邦 人 ， 从 他 们 中 间 选 取 百 姓 归 于 自 己 的 名 下 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27457', '44', '15', '15', '众 先 知 的 话 也 与 这 意 思 相 合 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27458', '44', '15', '16', '正 如 经 上 所 写 的 ： 此 后 ， 我 要 回 来 ， 重 新 修 造 大 卫 倒 塌 的 帐 幕 ， 把 那 破 坏 的 重 新 修 造 建 立 起 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27459', '44', '15', '17', '叫 余 剩 的 人 ， 就 是 凡 称 为 我 名 下 的 外 邦 人 ， 都 寻 求 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27460', '44', '15', '18', '这 话 是 从 创 世 以 来 显 明 这 事 的 主 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27461', '44', '15', '19', '“ 所 以 据 我 的 意 见 ， 不 可 难 为 那 归 服 神 的 外 邦 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27462', '44', '15', '20', '只 要 写 信 ， 吩 咐 他 们 禁 戒 偶 像 的 污 秽 和 奸 淫 ， 并 勒 死 的 牲 畜 和 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27463', '44', '15', '21', '因 为 从 古 以 来 ， 摩 西 的 书 在 各 城 有 人 传 讲 ， 每 逢 安 息 日 ， 在 会 堂 里 诵 读 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27464', '44', '15', '22', '＜ 会 议 的 覆 函 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27465', '44', '15', '23', '于 是 写 信 交 付 他 们 ， 内 中 说 ： “ 使 徒 和 作 长 老 的 弟 兄 们 问 安 提 阿 、 叙 利 亚 、 基 利 家 外 邦 众 弟 兄 的 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27466', '44', '15', '24', '我 们 听 说 ， 有 几 个 人 从 我 们 这 里 出 去 ， 用 言 语 搅 扰 你 们 ， 惑 乱 你 们 的 心 。 ｛ 有 古 卷 加 ： 你 们 必 须 受 割 礼 ， 守 摩 西 的 律 法 。 ｝ 其 实 我 们 并 没 有 吩 咐 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27467', '44', '15', '25', '所 以 ， 我 们 同 心 定 意 ， 拣 选 几 个 人 ， 差 他 们 同 我 们 所 亲 爱 的 巴 拿 巴 和 保 罗 往 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27468', '44', '15', '26', '这 二 人 是 为 我 主 耶 稣 基 督 的 名 不 顾 性 命 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27469', '44', '15', '27', '我 们 就 差 了 犹 大 和 西 拉 ， 他 们 也 要 亲 口 诉 说 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27470', '44', '15', '28', '因 为 圣 灵 和 我 们 定 意 不 将 别 的 重 担 放 在 你 们 身 上 ， 惟 有 几 件 事 是 不 可 少 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27471', '44', '15', '29', '就 是 禁 戒 祭 偶 像 的 物 和 血 ， 并 勒 死 的 牲 畜 和 奸 淫 。 这 几 件 你 们 若 能 自 己 禁 戒 不 犯 就 好 了 。 愿 你 们 平 安 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27472', '44', '15', '30', '他 们 既 奉 了 差 遣 ， 就 下 安 提 阿 去 ， 聚 集 众 人 ， 交 付 书 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27473', '44', '15', '31', '众 人 念 了 ， 因 为 信 上 安 慰 的 话 就 欢 喜 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27474', '44', '15', '32', '犹 大 和 西 拉 也 是 先 知 ， 就 用 许 多 话 劝 勉 弟 兄 ， 坚 固 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27475', '44', '15', '33', '住 了 些 日 子 ， 弟 兄 们 打 发 他 们 平 平 安 安 地 回 到 差 遣 他 们 的 人 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27476', '44', '15', '34', '｛ 有 古 卷 加 ： 惟 有 西 拉 定 意 仍 住 在 那 里 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27477', '44', '15', '35', '但 保 罗 和 巴 拿 巴 仍 住 在 安 提 阿 ， 和 许 多 别 人 一 同 教 训 人 ， 传 主 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27478', '44', '15', '36', '＜ 保 罗 和 巴 拿 巴 分 手 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27479', '44', '15', '37', '巴 拿 巴 有 意 要 带 称 呼 马 可 的 约 翰 同 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27480', '44', '15', '38', '但 保 罗 因 为 马 可 从 前 在 旁 非 利 亚 离 开 他 们 ， 不 和 他 们 同 去 做 工 ， 就 以 为 不 可 带 他 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27481', '44', '15', '39', '于 是 二 人 起 了 争 论 ， 甚 至 彼 此 分 开 。 巴 拿 巴 带 着 马 可 ， 坐 船 往 塞 浦 路 斯 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27482', '44', '15', '40', '保 罗 拣 选 了 西 拉 ， 也 出 去 ， 蒙 弟 兄 们 把 他 交 于 主 的 恩 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27483', '44', '15', '41', '他 就 走 遍 叙 利 亚 、 基 利 家 ， 坚 固 众 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27484', '44', '16', '1', '＜ 提 摩 太 跟 保 罗 、 西 拉 同 工 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27485', '44', '16', '2', '路 司 得 和 以 哥 念 的 弟 兄 都 称 赞 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27486', '44', '16', '3', '保 罗 要 带 他 同 去 ， 只 因 那 些 地 方 的 犹 太 人 都 知 道 他 父 亲 是 希 腊 人 ， 就 给 他 行 了 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27487', '44', '16', '4', '他 们 经 过 各 城 ， 把 耶 路 撒 冷 使 徒 和 长 老 所 定 的 条 规 交 给 门 徒 遵 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27488', '44', '16', '5', '于 是 众 教 会 信 心 越 发 坚 固 ， 人 数 天 天 加 增 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27489', '44', '16', '6', '＜ 保 罗 看 见 马 其 顿 人 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27490', '44', '16', '7', '到 了 每 西 亚 的 边 界 ， 他 们 想 要 往 庇 推 尼 去 ， 耶 稣 的 灵 却 不 许 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27491', '44', '16', '8', '他 们 就 越 过 每 西 亚 ， 下 到 特 罗 亚 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27492', '44', '16', '9', '在 夜 间 有 异 象 现 与 保 罗 。 有 一 个 马 其 顿 人 站 着 求 他 说 ： “ 请 你 过 到 马 其 顿 来 帮 助 我 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27493', '44', '16', '10', '保 罗 既 看 见 这 异 象 ， 我 们 随 即 想 要 往 马 其 顿 去 ， 以 为 神 召 我 们 传 福 音 给 那 里 的 人 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27494', '44', '16', '11', '＜ 吕 底 亚 归 主 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27495', '44', '16', '12', '从 那 里 来 到 腓 立 比 ， 就 是 马 其 顿 这 一 方 的 头 一 个 城 ， 也 是 罗 马 的 驻 防 城 。 我 们 在 这 城 里 住 了 几 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27496', '44', '16', '13', '当 安 息 日 ， 我 们 出 城 门 ， 到 了 河 边 ， 知 道 那 里 有 一 个 祷 告 的 地 方 ， 我 们 就 坐 下 对 那 聚 会 的 妇 女 讲 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27497', '44', '16', '14', '有 一 个 卖 紫 色 布 疋 的 妇 人 ， 名 叫 吕 底 亚 ， 是 推 雅 推 喇 城 的 人 ， 素 来 敬 拜 神 。 她 听 见 了 ， 主 就 开 导 她 的 心 ， 叫 她 留 心 听 保 罗 所 讲 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27498', '44', '16', '15', '她 和 她 一 家 既 领 了 洗 ， 便 求 我 们 说 ： “ 你 们 若 以 为 我 是 真 信 主 的 ｛ 或 译 ： 你 们 若 以 为 我 是 忠 心 事 主 的 ｝ ， 请 到 我 家 里 来 住 ” ； 于 是 强 留 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27499', '44', '16', '16', '＜ 在 腓 立 比 被 囚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27500', '44', '16', '17', '她 跟 随 保 罗 和 我 们 ， 喊 着 说 ： “ 这 些 人 是 至 高 神 的 仆 人 ， 对 你 们 传 说 救 人 的 道 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27501', '44', '16', '18', '她 一 连 多 日 这 样 喊 叫 ， 保 罗 就 心 中 厌 烦 ， 转 身 对 那 鬼 说 ： “ 我 奉 耶 稣 基 督 的 名 ， 吩 咐 你 从 她 身 上 出 来 ！ ” 那 鬼 当 时 就 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27502', '44', '16', '19', '使 女 的 主 人 们 见 得 利 的 指 望 没 有 了 ， 便 揪 住 保 罗 和 西 拉 ， 拉 他 们 到 市 上 去 见 首 领 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27503', '44', '16', '20', '又 带 到 官 长 面 前 说 ： “ 这 些 人 原 是 犹 太 人 ， 竟 骚 扰 我 们 的 城 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27504', '44', '16', '21', '传 我 们 罗 马 人 所 不 可 受 不 可 行 的 规 矩 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27505', '44', '16', '22', '众 人 就 一 同 起 来 攻 击 他 们 。 官 长 吩 咐 剥 了 他 们 的 衣 裳 ， 用 棍 打 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27506', '44', '16', '23', '打 了 许 多 棍 ， 便 将 他 们 下 在 监 里 ， 嘱 咐 禁 卒 严 紧 看 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27507', '44', '16', '24', '禁 卒 领 了 这 样 的 命 ， 就 把 他 们 下 在 内 监 里 ， 两 脚 上 了 木 狗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27508', '44', '16', '25', '约 在 半 夜 ， 保 罗 和 西 拉 祷 告 ， 唱 诗 赞 美 神 ， 众 囚 犯 也 侧 耳 而 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27509', '44', '16', '26', '忽 然 ， 地 大 震 动 ， 甚 至 监 牢 的 地 基 都 摇 动 了 ， 监 门 立 刻 全 开 ， 众 囚 犯 的 锁 炼 也 都 松 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27510', '44', '16', '27', '禁 卒 一 醒 ， 看 见 监 门 全 开 ， 以 为 囚 犯 已 经 逃 走 ， 就 拔 刀 要 自 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27511', '44', '16', '28', '保 罗 大 声 呼 叫 说 ： “ 不 要 伤 害 自 己 ！ 我 们 都 在 这 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27512', '44', '16', '29', '禁 卒 叫 人 拿 灯 来 ， 就 跳 进 去 ， 战 战 兢 兢 地 俯 伏 在 保 罗 、 西 拉 面 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27513', '44', '16', '30', '又 领 他 们 出 来 ， 说 ： “ 二 位 先 生 ， 我 当 怎 样 行 才 可 以 得 救 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27514', '44', '16', '31', '他 们 说 ： “ 当 信 主 耶 稣 ， 你 和 你 一 家 都 必 得 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27515', '44', '16', '32', '他 们 就 把 主 的 道 讲 给 他 和 他 全 家 的 人 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27516', '44', '16', '33', '当 夜 ， 就 在 那 时 候 ， 禁 卒 把 他 们 带 去 ， 洗 他 们 的 伤 ； 他 和 属 乎 他 的 人 立 时 都 受 了 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27517', '44', '16', '34', '于 是 禁 卒 领 他 们 上 自 己 家 里 去 ， 给 他 们 摆 上 饭 。 他 和 全 家 ， 因 为 信 了 神 ， 都 很 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27518', '44', '16', '35', '到 了 天 亮 ， 官 长 打 发 差 役 来 ， 说 ： “ 释 放 那 两 个 人 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27519', '44', '16', '36', '禁 卒 就 把 这 话 告 诉 保 罗 说 ： “ 官 长 打 发 人 来 叫 释 放 你 们 ， 如 今 可 以 出 监 ， 平 平 安 安 地 去 吧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27520', '44', '16', '37', '保 罗 却 说 ： “ 我 们 是 罗 马 人 ， 并 没 有 定 罪 ， 他 们 就 在 众 人 面 前 打 了 我 们 ， 又 把 我 们 下 在 监 里 ， 现 在 要 私 下 撵 我 们 出 去 吗 ？ 这 是 不 行 的 。 叫 他 们 自 己 来 领 我 们 出 去 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27521', '44', '16', '38', '差 役 把 这 话 回 禀 官 长 。 官 长 听 见 他 们 是 罗 马 人 ， 就 害 怕 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27522', '44', '16', '39', '于 是 来 劝 他 们 ， 领 他 们 出 来 ， 请 他 们 离 开 那 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27523', '44', '16', '40', '二 人 出 了 监 ， 往 吕 底 亚 家 里 去 ， 见 了 弟 兄 们 ， 劝 慰 他 们 一 番 ， 就 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27524', '44', '17', '1', '＜ 帖 撒 罗 尼 迦 的 骚 动 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27525', '44', '17', '2', '保 罗 照 他 素 常 的 规 矩 进 去 ， 一 连 三 个 安 息 日 ， 本 着 圣 经 与 他 们 辩 论 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27526', '44', '17', '3', '讲 解 陈 明 基 督 必 须 受 害 ， 从 死 里 复 活 ； 又 说 ： “ 我 所 传 与 你 们 的 这 位 耶 稣 就 是 基 督 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27527', '44', '17', '4', '他 们 中 间 有 些 人 听 了 劝 ， 就 附 从 保 罗 和 西 拉 ， 并 有 许 多 虔 敬 的 希 腊 人 ， 尊 贵 的 妇 女 也 不 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27528', '44', '17', '5', '但 那 不 信 的 犹 太 人 心 里 嫉 妒 ， 招 聚 了 些 市 井 匪 类 ， 搭 伙 成 群 ， 耸 动 合 城 的 人 闯 进 耶 孙 的 家 ， 要 将 保 罗 、 西 拉 带 到 百 姓 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27529', '44', '17', '6', '找 不 着 他 们 ， 就 把 耶 孙 和 几 个 弟 兄 拉 到 地 方 官 那 里 ， 喊 叫 说 ： “ 那 搅 乱 天 下 的 也 到 这 里 来 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27530', '44', '17', '7', '耶 孙 收 留 他 们 。 这 些 人 都 违 背 凯 撒 的 命 令 ， 说 另 有 一 个 王 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27531', '44', '17', '8', '众 人 和 地 方 官 听 见 这 话 ， 就 惊 慌 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27532', '44', '17', '9', '于 是 取 了 耶 孙 和 其 余 之 人 的 保 状 ， 就 释 放 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27533', '44', '17', '10', '＜ 使 徒 们 在 庇 哩 亚 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27534', '44', '17', '11', '这 地 方 的 人 贤 于 帖 撒 罗 尼 迦 的 人 ， 甘 心 领 受 这 道 ， 天 天 考 查 圣 经 ， 要 晓 得 这 道 是 与 不 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27535', '44', '17', '12', '所 以 他 们 中 间 多 有 相 信 的 ， 又 有 希 腊 尊 贵 的 妇 女 ， 男 子 也 不 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27536', '44', '17', '13', '但 帖 撒 罗 尼 迦 的 犹 太 人 知 道 保 罗 又 在 庇 哩 亚 传 神 的 道 ， 也 就 往 那 里 去 ， 耸 动 搅 扰 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27537', '44', '17', '14', '当 时 弟 兄 们 便 打 发 保 罗 往 海 边 去 ， 西 拉 和 提 摩 太 仍 住 在 庇 哩 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27538', '44', '17', '15', '送 保 罗 的 人 带 他 到 了 雅 典 ， 既 领 了 保 罗 的 命 ， 叫 西 拉 和 提 摩 太 速 速 到 他 这 里 来 ， 就 回 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27539', '44', '17', '16', '＜ 保 罗 在 雅 典 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27540', '44', '17', '17', '于 是 在 会 堂 里 与 犹 太 人 和 虔 敬 的 人 ， 并 每 日 在 市 上 所 遇 见 的 人 ， 辩 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27541', '44', '17', '18', '还 有 伊 壁 鸠 鲁 和 斯 多 亚 两 门 的 学 士 ， 与 他 争 论 。 有 的 说 ： “ 这 胡 言 乱 语 的 要 说 什 么 ？ ” 有 的 说 ： “ 他 似 乎 是 传 说 外 邦 鬼 神 的 。 ” 这 话 是 因 保 罗 传 讲 耶 稣 与 复 活 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27542', '44', '17', '19', '他 们 就 把 他 带 到 亚 略 ． 巴 古 ， 说 ： “ 你 所 讲 的 这 新 道 ， 我 们 也 可 以 知 道 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27543', '44', '17', '20', '因 为 你 有 些 奇 怪 的 事 传 到 我 们 耳 中 ， 我 们 愿 意 知 道 这 些 事 是 什 么 意 思 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27544', '44', '17', '21', '（ 雅 典 人 和 住 在 那 里 的 客 人 都 不 顾 别 的 事 ， 只 将 新 闻 说 说 听 听 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27545', '44', '17', '22', '保 罗 站 在 亚 略 ． 巴 古 当 中 ， 说 ： “ 众 位 雅 典 人 哪 ， 我 看 你 们 凡 事 很 敬 畏 鬼 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27546', '44', '17', '23', '我 游 行 的 时 候 ， 观 看 你 们 所 敬 拜 的 ， 遇 见 一 座 坛 ， 上 面 写 着 ‘ 未 识 之 神 ’ 。 你 们 所 不 认 识 而 敬 拜 的 ， 我 现 在 告 诉 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27547', '44', '17', '24', '创 造 宇 宙 和 其 中 万 物 的 神 ， 既 是 天 地 的 主 ， 就 不 住 人 手 所 造 的 殿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27548', '44', '17', '25', '也 不 用 人 手 服 事 ， 好 像 缺 少 什 么 ； 自 己 倒 将 生 命 、 气 息 、 万 物 ， 赐 给 万 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27549', '44', '17', '26', '他 从 一 本 ｛ 本 ： 有 古 卷 是 血 脉 ｝ 造 出 万 族 的 人 ， 住 在 全 地 上 ， 并 且 预 先 定 准 他 们 的 年 限 和 所 住 的 疆 界 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27550', '44', '17', '27', '要 叫 他 们 寻 求 神 ， 或 者 可 以 揣 摩 而 得 ， 其 实 他 离 我 们 各 人 不 远 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27551', '44', '17', '28', '我 们 生 活 、 动 作 、 存 留 ， 都 在 乎 他 。 就 如 你 们 作 诗 的 ， 有 人 说 ： ‘ 我 们 也 是 他 所 生 的 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27552', '44', '17', '29', '我 们 既 是 神 所 生 的 ， 就 不 当 以 为 神 的 神 性 像 人 用 手 艺 、 心 思 所 雕 刻 的 金 、 银 、 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27553', '44', '17', '30', '世 人 蒙 昧 无 知 的 时 候 ， 神 并 不 监 察 ， 如 今 却 吩 咐 各 处 的 人 都 要 悔 改 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27554', '44', '17', '31', '因 为 他 已 经 定 了 日 子 ， 要 藉 着 他 所 设 立 的 人 按 公 义 审 判 天 下 ， 并 且 叫 他 从 死 里 复 活 ， 给 万 人 作 可 信 的 凭 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27555', '44', '17', '32', '众 人 听 见 从 死 里 复 活 的 话 ， 就 有 讥 诮 他 的 ； 又 有 人 说 ： “ 我 们 再 听 你 讲 这 个 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27556', '44', '17', '33', '于 是 保 罗 从 他 们 当 中 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27557', '44', '17', '34', '但 有 几 个 人 贴 近 他 ， 信 了 主 ， 其 中 有 亚 略 ． 巴 古 的 官 丢 尼 修 ， 并 一 个 妇 人 ， 名 叫 大 马 哩 ， 还 有 别 人 一 同 信 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27558', '44', '18', '1', '＜ 保 罗 在 哥 林 多 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27559', '44', '18', '2', '遇 见 一 个 犹 太 人 ， 名 叫 亚 居 拉 ， 他 生 在 本 都 ； 因 为 克 劳 第 命 犹 太 人 都 离 开 罗 马 ， 新 近 带 着 妻 百 基 拉 ， 从 意 大 利 来 。 保 罗 就 投 奔 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27560', '44', '18', '3', '他 们 本 是 制 造 帐 棚 为 业 。 保 罗 因 与 他 们 同 业 ， 就 和 他 们 同 住 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27561', '44', '18', '4', '每 逢 安 息 日 ， 保 罗 在 会 堂 里 辩 论 ， 劝 化 犹 太 人 和 希 腊 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27562', '44', '18', '5', '西 拉 和 提 摩 太 从 马 其 顿 来 的 时 候 ， 保 罗 为 道 迫 切 ， 向 犹 太 人 证 明 耶 稣 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27563', '44', '18', '6', '他 们 既 抗 拒 、 毁 谤 ， 保 罗 就 抖 着 衣 裳 ， 说 ： “ 你 们 的 罪 ｛ 原 文 是 血 ｝ 归 到 你 们 自 己 头 上 ， 与 我 无 干 ｛ 原 文 是 我 却 干 净 ｝ 。 从 今 以 后 ， 我 要 往 外 邦 人 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27564', '44', '18', '7', '于 是 离 开 那 里 ， 到 了 一 个 人 的 家 中 ； 这 人 名 叫 提 多 犹 士 都 ， 是 敬 拜 神 的 ， 他 的 家 靠 近 会 堂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27565', '44', '18', '8', '管 会 堂 的 基 利 司 布 和 全 家 都 信 了 主 ， 还 有 许 多 哥 林 多 人 听 了 ， 就 相 信 受 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27566', '44', '18', '9', '夜 间 ， 主 在 异 象 中 对 保 罗 说 ： “ 不 要 怕 ， 只 管 讲 ， 不 要 闭 口 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27567', '44', '18', '10', '有 我 与 你 同 在 ， 必 没 有 人 下 手 害 你 ， 因 为 在 这 城 里 我 有 许 多 的 百 姓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27568', '44', '18', '11', '保 罗 在 那 里 住 了 一 年 零 六 个 月 ， 将 神 的 道 教 训 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27569', '44', '18', '12', '到 迦 流 作 亚 该 亚 方 伯 的 时 候 ， 犹 太 人 同 心 起 来 攻 击 保 罗 ， 拉 他 到 公 堂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27570', '44', '18', '13', '说 ： “ 这 个 人 劝 人 不 按 着 律 法 敬 拜 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27571', '44', '18', '14', '保 罗 刚 要 开 口 ， 迦 流 就 对 犹 太 人 说 ： “ 你 们 这 些 犹 太 人 ！ 如 果 是 为 冤 枉 或 奸 恶 的 事 ， 我 理 当 耐 性 听 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27572', '44', '18', '15', '但 所 争 论 的 ， 若 是 关 乎 言 语 、 名 目 ， 和 你 们 的 律 法 ， 你 们 自 己 去 办 吧 ！ 这 样 的 事 我 不 愿 意 审 问 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27573', '44', '18', '16', '就 把 他 们 撵 出 公 堂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27574', '44', '18', '17', '众 人 便 揪 住 管 会 堂 的 所 提 尼 ， 在 堂 前 打 他 。 这 些 事 迦 流 都 不 管 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27575', '44', '18', '18', '＜ 保 罗 回 到 安 提 阿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27576', '44', '18', '19', '到 了 以 弗 所 ， 保 罗 就 把 他 们 留 在 那 里 ， 自 己 进 了 会 堂 ， 和 犹 太 人 辩 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27577', '44', '18', '20', '众 人 请 他 多 住 些 日 子 ， 他 却 不 允 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27578', '44', '18', '21', '就 辞 别 他 们 ， 说 ： “ 神 若 许 我 ， 我 还 要 回 到 你 们 这 里 ” ； 于 是 开 船 离 了 以 弗 所 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27579', '44', '18', '22', '在 凯 撒 利 亚 下 了 船 ， 就 上 耶 路 撒 冷 去 问 教 会 安 ， 随 后 下 安 提 阿 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27580', '44', '18', '23', '住 了 些 日 子 ， 又 离 开 那 里 ， 挨 次 经 过 加 拉 太 和 弗 吕 家 地 方 ， 坚 固 众 门 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27581', '44', '18', '24', '＜ 亚 波 罗 在 以 弗 所 讲 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27582', '44', '18', '25', '这 人 已 经 在 主 的 道 上 受 了 教 训 ， 心 里 火 热 ， 将 耶 稣 的 事 详 细 讲 论 教 训 人 ； 只 是 他 单 晓 得 约 翰 的 洗 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27583', '44', '18', '26', '他 在 会 堂 里 放 胆 讲 道 ； 百 基 拉 、 亚 居 拉 听 见 ， 就 接 他 来 ， 将 神 的 道 给 他 讲 解 更 加 详 细 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27584', '44', '18', '27', '他 想 要 往 亚 该 亚 去 ， 弟 兄 们 就 勉 励 他 ， 并 写 信 请 门 徒 接 待 他 ｛ 或 译 ： 弟 兄 们 就 写 信 劝 门 徒 接 待 他 ｝ 。 他 到 了 那 里 ， 多 帮 助 那 蒙 恩 信 主 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27585', '44', '18', '28', '在 众 人 面 前 极 有 能 力 驳 倒 犹 太 人 ， 引 圣 经 证 明 耶 稣 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27586', '44', '19', '1', '＜ 保 罗 在 以 弗 所 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27587', '44', '19', '2', '问 他 们 说 ： “ 你 们 信 的 时 候 受 了 圣 灵 没 有 ？ ” 他 们 回 答 说 ： “ 没 有 ， 也 未 曾 听 见 有 圣 灵 赐 下 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27588', '44', '19', '3', '保 罗 说 ： “ 这 样 ， 你 们 受 的 是 什 么 洗 呢 ？ ” 他 们 说 ： “ 是 约 翰 的 洗 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27589', '44', '19', '4', '保 罗 说 ： “ 约 翰 所 行 的 是 悔 改 的 洗 ， 告 诉 百 姓 当 信 那 在 他 以 后 要 来 的 ， 就 是 耶 稣 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27590', '44', '19', '5', '他 们 听 见 这 话 ， 就 奉 主 耶 稣 的 名 受 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27591', '44', '19', '6', '保 罗 按 手 在 他 们 头 上 ， 圣 灵 便 降 在 他 们 身 上 ， 他 们 就 说 方 言 ， 又 说 预 言 ｛ 或 译 ： 又 讲 道 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27592', '44', '19', '7', '一 共 约 有 十 二 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27593', '44', '19', '8', '保 罗 进 会 堂 ， 放 胆 讲 道 ， 一 连 三 个 月 ， 辩 论 神 国 的 事 ， 劝 化 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27594', '44', '19', '9', '后 来 ， 有 些 人 心 里 刚 硬 不 信 ， 在 众 人 面 前 毁 谤 这 道 ， 保 罗 就 离 开 他 们 ， 也 叫 门 徒 与 他 们 分 离 ， 便 在 推 喇 奴 的 学 房 天 天 辩 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27595', '44', '19', '10', '这 样 有 两 年 之 久 ， 叫 一 切 住 在 亚 细 亚 的 ， 无 论 是 犹 太 人 ， 是 希 腊 人 ， 都 听 见 主 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27596', '44', '19', '11', '＜ 士 基 瓦 的 儿 子 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27597', '44', '19', '12', '甚 至 有 人 从 保 罗 身 上 拿 手 巾 或 围 裙 放 在 病 人 身 上 ， 病 就 退 了 ， 恶 鬼 也 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27598', '44', '19', '13', '那 时 ， 有 几 个 游 行 各 处 、 念 咒 赶 鬼 的 犹 太 人 ， 向 那 被 恶 鬼 附 的 人 擅 自 称 主 耶 稣 的 名 ， 说 ： “ 我 奉 保 罗 所 传 的 耶 稣 勒 令 你 们 出 来 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27599', '44', '19', '14', '做 这 事 的 ， 有 犹 太 祭 司 长 士 基 瓦 的 七 个 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27600', '44', '19', '15', '恶 鬼 回 答 他 们 说 ： “ 耶 稣 我 认 识 ， 保 罗 我 也 知 道 。 你 们 却 是 谁 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27601', '44', '19', '16', '恶 鬼 所 附 的 人 就 跳 在 他 们 身 上 ， 胜 了 其 中 二 人 ， 制 伏 他 们 ， 叫 他 们 赤 着 身 子 受 了 伤 ， 从 那 房 子 里 逃 出 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27602', '44', '19', '17', '凡 住 在 以 弗 所 的 ， 无 论 是 犹 太 人 ， 是 希 腊 人 ， 都 知 道 这 事 ， 也 都 惧 怕 ； 主 耶 稣 的 名 从 此 就 尊 大 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27603', '44', '19', '18', '那 已 经 信 的 ， 多 有 人 来 承 认 诉 说 自 己 所 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27604', '44', '19', '19', '平 素 行 邪 术 的 ， 也 有 许 多 人 把 书 拿 来 ， 堆 积 在 众 人 面 前 焚 烧 。 他 们 算 计 书 价 ， 便 知 道 共 合 五 万 块 钱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27605', '44', '19', '20', '主 的 道 大 大 兴 旺 ， 而 且 得 胜 ， 就 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27606', '44', '19', '21', '＜ 以 弗 所 的 暴 动 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27607', '44', '19', '22', '于 是 从 帮 助 他 的 人 中 打 发 提 摩 太 、 以 拉 都 二 人 往 马 其 顿 去 ， 自 己 暂 时 等 在 亚 细 亚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27608', '44', '19', '23', '那 时 ， 因 为 这 道 起 的 扰 乱 不 小 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27609', '44', '19', '24', '有 一 个 银 匠 ， 名 叫 底 米 丢 ， 是 制 造 亚 底 米 神 银 龛 的 ， 他 使 这 样 手 艺 人 生 意 发 达 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27610', '44', '19', '25', '他 聚 集 他 们 和 同 行 的 工 人 ， 说 ： “ 众 位 ， 你 们 知 道 我 们 是 倚 靠 这 生 意 发 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27611', '44', '19', '26', '这 保 罗 不 但 在 以 弗 所 ， 也 几 乎 在 亚 细 亚 全 地 ， 引 诱 迷 惑 许 多 人 ， 说 ： ‘ 人 手 所 做 的 ， 不 是 神 。 ’ 这 是 你 们 所 看 见 所 听 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27612', '44', '19', '27', '这 样 ， 不 独 我 们 这 事 业 被 人 藐 视 ， 就 是 大 女 神 亚 底 米 的 庙 也 要 被 人 轻 忽 ， 连 亚 细 亚 全 地 和 普 天 下 所 敬 拜 的 大 女 神 之 威 荣 也 要 消 灭 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27613', '44', '19', '28', '众 人 听 见 ， 就 怒 气 填 胸 ， 喊 着 说 ： “ 大 哉 ， 以 弗 所 人 的 亚 底 米 啊 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27614', '44', '19', '29', '满 城 都 轰 动 起 来 。 众 人 拿 住 与 保 罗 同 行 的 马 其 顿 人 该 犹 和 亚 里 达 古 ， 齐 心 拥 进 戏 园 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27615', '44', '19', '30', '保 罗 想 要 进 去 ， 到 百 姓 那 里 ， 门 徒 却 不 许 他 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27616', '44', '19', '31', '还 有 亚 细 亚 几 位 首 领 ， 是 保 罗 的 朋 友 ， 打 发 人 来 劝 他 ， 不 要 冒 险 到 戏 园 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27617', '44', '19', '32', '聚 集 的 人 纷 纷 乱 乱 ， 有 喊 叫 这 个 的 ， 有 喊 叫 那 个 的 ， 大 半 不 知 道 是 为 什 么 聚 集 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27618', '44', '19', '33', '有 人 把 亚 历 山 大 从 众 人 中 带 出 来 ， 犹 太 人 推 他 往 前 ， 亚 历 山 大 就 摆 手 ， 要 向 百 姓 分 诉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27619', '44', '19', '34', '只 因 他 们 认 出 他 是 犹 太 人 ， 就 大 家 同 声 喊 着 说 ： “ 大 哉 ！ 以 弗 所 人 的 亚 底 米 啊 。 ” 如 此 约 有 两 小 时 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27620', '44', '19', '35', '那 城 里 的 书 记 安 抚 了 众 人 ， 就 说 ： “ 以 弗 所 人 哪 ， 谁 不 知 道 以 弗 所 人 的 城 是 看 守 大 亚 底 米 的 庙 和 从 宙 斯 那 里 落 下 来 的 像 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27621', '44', '19', '36', '这 事 既 是 驳 不 倒 的 ， 你 们 就 当 安 静 ， 不 可 造 次 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27622', '44', '19', '37', '你 们 把 这 些 人 带 来 ， 他 们 并 没 有 偷 窃 庙 中 之 物 ， 也 没 有 谤 讟 我 们 的 女 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27623', '44', '19', '38', '若 是 底 米 丢 和 他 同 行 的 人 有 控 告 人 的 事 ， 自 有 放 告 的 日 子 ｛ 或 译 ： 自 有 公 堂 ｝ ， 也 有 方 伯 可 以 彼 此 对 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27624', '44', '19', '39', '你 们 若 问 别 的 事 ， 就 可 以 照 常 例 聚 集 断 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27625', '44', '19', '40', '今 日 的 扰 乱 本 是 无 缘 无 故 ， 我 们 难 免 被 查 问 。 论 到 这 样 聚 众 ， 我 们 也 说 不 出 所 以 然 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27626', '44', '19', '41', '说 了 这 话 ， 便 叫 众 人 散 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27627', '44', '20', '1', '＜ 保 罗 再 访 问 马 其 顿 和 希 腊 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27628', '44', '20', '2', '走 遍 了 那 一 带 地 方 ， 用 许 多 话 劝 勉 门 徒 ｛ 或 译 ： 众 人 ｝ ， 然 后 来 到 希 腊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27629', '44', '20', '3', '在 那 里 住 了 三 个 月 ， 将 要 坐 船 往 叙 利 亚 去 ， 犹 太 人 设 计 要 害 他 ， 他 就 定 意 从 马 其 顿 回 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27630', '44', '20', '4', '同 他 到 亚 细 亚 去 的 ， 有 庇 哩 亚 人 毕 罗 斯 的 儿 子 所 巴 特 ， 帖 撒 罗 尼 迦 人 亚 里 达 古 和 西 公 都 ， 还 有 特 庇 人 该 犹 ， 并 提 摩 太 ， 又 有 亚 细 亚 人 推 基 古 和 特 罗 非 摩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27631', '44', '20', '5', '这 些 人 先 走 ， 在 特 罗 亚 等 候 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27632', '44', '20', '6', '过 了 除 酵 的 日 子 ， 我 们 从 腓 立 比 开 船 ， 五 天 到 了 特 罗 亚 ， 和 他 们 相 会 ， 在 那 里 住 了 七 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27633', '44', '20', '7', '＜ 保 罗 最 后 一 次 访 问 特 罗 亚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27634', '44', '20', '8', '我 们 聚 会 的 那 座 楼 上 ， 有 好 些 灯 烛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27635', '44', '20', '9', '有 一 个 少 年 人 ， 名 叫 犹 推 古 ， 坐 在 窗 台 上 ， 困 倦 沉 睡 。 保 罗 讲 了 多 时 ， 少 年 人 睡 熟 了 ， 就 从 三 层 楼 上 掉 下 去 ； 扶 起 他 来 ， 已 经 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27636', '44', '20', '10', '保 罗 下 去 ， 伏 在 他 身 上 ， 抱 着 他 ， 说 ： “ 你 们 不 要 发 慌 ， 他 的 灵 魂 还 在 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27637', '44', '20', '11', '保 罗 又 上 去 ， 擘 饼 ， 吃 了 ， 谈 论 许 久 ， 直 到 天 亮 ， 这 才 走 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27638', '44', '20', '12', '有 人 把 那 童 子 活 活 地 领 来 ， 得 的 安 慰 不 小 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27639', '44', '20', '13', '＜ 从 特 罗 亚 到 米 利 都 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27640', '44', '20', '14', '他 既 在 亚 朔 与 我 们 相 会 ， 我 们 就 接 他 上 船 ， 来 到 米 推 利 尼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27641', '44', '20', '15', '从 那 里 开 船 ， 次 日 到 了 基 阿 的 对 面 ； 又 次 日 ， 在 撒 摩 靠 岸 ； 又 次 日 ， 来 到 米 利 都 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27642', '44', '20', '16', '乃 因 保 罗 早 已 定 意 越 过 以 弗 所 ， 免 得 在 亚 细 亚 耽 延 ， 他 急 忙 前 走 ， 巴 不 得 赶 五 旬 节 能 到 耶 路 撒 冷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27643', '44', '20', '17', '＜ 保 罗 向 以 弗 所 长 老 发 表 谈 话 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27644', '44', '20', '18', '他 们 来 了 ， 保 罗 就 说 ： “ 你 们 知 道 ， 自 从 我 到 亚 细 亚 的 日 子 以 来 ， 在 你 们 中 间 始 终 为 人 如 何 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27645', '44', '20', '19', '服 事 主 ， 凡 事 谦 卑 ， 眼 中 流 泪 ， 又 因 犹 太 人 的 谋 害 ， 经 历 试 炼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27646', '44', '20', '20', '你 们 也 知 道 ， 凡 与 你 们 有 益 的 ， 我 没 有 一 样 避 讳 不 说 的 ， 或 在 众 人 面 前 ， 或 在 各 人 家 里 ， 我 都 教 导 你 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27647', '44', '20', '21', '又 对 犹 太 人 和 希 腊 人 证 明 当 向 神 悔 改 ， 信 靠 我 主 耶 稣 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27648', '44', '20', '22', '现 在 我 往 耶 路 撒 冷 去 ， 心 甚 迫 切 ｛ 原 文 是 心 被 捆 绑 ｝ ， 不 知 道 在 那 里 要 遇 见 什 么 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27649', '44', '20', '23', '但 知 道 圣 灵 在 各 城 里 向 我 指 证 ， 说 有 捆 锁 与 患 难 等 待 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27650', '44', '20', '24', '我 却 不 以 性 命 为 念 ， 也 不 看 为 宝 贵 ， 只 要 行 完 我 的 路 程 ， 成 就 我 从 主 耶 稣 所 领 受 的 职 事 ， 证 明 神 恩 惠 的 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27651', '44', '20', '25', '“ 我 素 常 在 你 们 中 间 来 往 ， 传 讲 神 国 的 道 ； 如 今 我 晓 得 ， 你 们 以 后 都 不 得 再 见 我 的 面 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27652', '44', '20', '26', '所 以 我 今 日 向 你 们 证 明 ， 你 们 中 间 无 论 何 人 死 亡 ， 罪 不 在 我 身 上 ｛ 原 文 是 我 于 众 人 的 血 是 洁 净 的 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27653', '44', '20', '27', '因 为 神 的 旨 意 ， 我 并 没 有 一 样 避 讳 不 传 给 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27654', '44', '20', '28', '圣 灵 立 你 们 作 全 群 的 监 督 ， 你 们 就 当 为 自 己 谨 慎 ， 也 为 全 群 谨 慎 ， 牧 养 神 的 教 会 ， 就 是 他 用 自 己 血 所 买 来 的 ｛ 或 译 ： 救 赎 的 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27655', '44', '20', '29', '我 知 道 ， 我 去 之 后 必 有 凶 暴 的 豺 狼 进 入 你 们 中 间 ， 不 爱 惜 羊 群 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27656', '44', '20', '30', '就 是 你 们 中 间 ， 也 必 有 人 起 来 说 悖 谬 的 话 ， 要 引 诱 门 徒 跟 从 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27657', '44', '20', '31', '所 以 你 们 应 当 警 醒 ， 记 念 我 三 年 之 久 昼 夜 不 住 地 流 泪 、 劝 戒 你 们 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27658', '44', '20', '32', '如 今 我 把 你 们 交 托 神 和 他 恩 惠 的 道 ； 这 道 能 建 立 你 们 ， 叫 你 们 和 一 切 成 圣 的 人 同 得 基 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27659', '44', '20', '33', '我 未 曾 贪 图 一 个 人 的 金 、 银 、 衣 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27660', '44', '20', '34', '我 这 两 只 手 常 供 给 我 和 同 人 的 需 用 ， 这 是 你 们 自 己 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27661', '44', '20', '35', '我 凡 事 给 你 们 作 榜 样 ， 叫 你 们 知 道 应 当 这 样 劳 苦 ， 扶 助 软 弱 的 人 ， 又 当 记 念 主 耶 稣 的 话 ， 说 ： ‘ 施 比 受 更 为 有 福 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27662', '44', '20', '36', '保 罗 说 完 了 这 话 ， 就 跪 下 同 众 人 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27663', '44', '20', '37', '众 人 痛 哭 ， 抱 着 保 罗 的 颈 项 ， 和 他 亲 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27664', '44', '20', '38', '叫 他 们 最 伤 心 的 ， 就 是 他 说 “ 以 后 不 能 再 见 我 的 面 ” 那 句 话 ， 于 是 送 他 上 船 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27665', '44', '21', '1', '＜ 保 罗 上 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27666', '44', '21', '2', '遇 见 一 只 船 要 往 腓 尼 基 去 ， 就 上 船 起 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27667', '44', '21', '3', '望 见 塞 浦 路 斯 ， 就 从 南 边 行 过 ， 往 叙 利 亚 去 ， 我 们 就 在 泰 尔 上 岸 ， 因 为 船 要 在 那 里 卸 货 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27668', '44', '21', '4', '找 着 了 门 徒 ， 就 在 那 里 住 了 七 天 。 他 们 被 圣 灵 感 动 ， 对 保 罗 说 ： “ 不 要 上 耶 路 撒 冷 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27669', '44', '21', '5', '过 了 这 几 天 ， 我 们 就 起 身 前 行 。 他 们 众 人 同 妻 子 儿 女 ， 送 我 们 到 城 外 ， 我 们 都 跪 在 岸 上 祷 告 ， 彼 此 辞 别 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27670', '44', '21', '6', '我 们 上 了 船 ， 他 们 就 回 家 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27671', '44', '21', '7', '我 们 从 泰 尔 行 尽 了 水 路 ， 来 到 多 利 买 ， 就 问 那 里 的 弟 兄 安 ， 和 他 们 同 住 了 一 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27672', '44', '21', '8', '第 二 天 ， 我 们 离 开 那 里 ， 来 到 凯 撒 利 亚 ， 就 进 了 传 福 音 的 腓 利 家 里 ， 和 他 同 住 。 他 是 那 七 个 执 事 里 的 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27673', '44', '21', '9', '他 有 四 个 女 儿 ， 都 是 处 女 ， 是 说 预 言 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27674', '44', '21', '10', '我 们 在 那 里 多 住 了 几 天 ， 有 一 个 先 知 ， 名 叫 亚 迦 布 ， 从 犹 太 下 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27675', '44', '21', '11', '到 了 我 们 这 里 ， 就 拿 保 罗 的 腰 带 捆 上 自 己 的 手 脚 ， 说 ： “ 圣 灵 说 ： 犹 太 人 在 耶 路 撒 冷 ， 要 如 此 捆 绑 这 腰 带 的 主 人 ， 把 他 交 在 外 邦 人 手 里 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27676', '44', '21', '12', '我 们 和 那 本 地 的 人 听 见 这 话 ， 都 苦 劝 保 罗 不 要 上 耶 路 撒 冷 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27677', '44', '21', '13', '保 罗 说 ： “ 你 们 为 什 么 这 样 痛 哭 ， 使 我 心 碎 呢 ？ 我 为 主 耶 稣 的 名 ， 不 但 被 人 捆 绑 ， 就 是 死 在 耶 路 撒 冷 也 是 愿 意 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27678', '44', '21', '14', '保 罗 既 不 听 劝 ， 我 们 便 住 了 口 ， 只 说 ： “ 愿 主 的 旨 意 成 就 ” ， 便 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27679', '44', '21', '15', '过 了 几 日 ， 我 们 收 拾 行 李 上 耶 路 撒 冷 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27680', '44', '21', '16', '有 凯 撒 利 亚 的 几 个 门 徒 和 我 们 同 去 ， 带 我 们 到 一 个 久 为 ｛ 久 为 ： 或 译 老 ｝ 门 徒 的 家 里 ， 叫 我 们 与 他 同 住 ； 他 名 叫 拿 孙 ， 是 塞 浦 路 斯 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27681', '44', '21', '17', '＜ 保 罗 访 问 雅 各 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27682', '44', '21', '18', '第 二 天 ， 保 罗 同 我 们 去 见 雅 各 ； 长 老 们 也 都 在 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27683', '44', '21', '19', '保 罗 问 了 他 们 安 ， 便 将 神 用 他 传 教 ， 在 外 邦 人 中 间 所 行 之 事 ， 一 一 地 述 说 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27684', '44', '21', '20', '他 们 听 见 ， 就 归 荣 耀 与 神 ， 对 保 罗 说 ： “ 兄 台 ， 你 看 犹 太 人 中 信 主 的 有 多 少 万 ， 并 且 都 为 律 法 热 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27685', '44', '21', '21', '他 们 听 见 人 说 ， 你 教 训 一 切 在 外 邦 的 犹 太 人 离 弃 摩 西 ， 对 他 们 说 ， 不 要 给 孩 子 行 割 礼 ， 也 不 要 遵 行 条 规 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27686', '44', '21', '22', '众 人 必 听 见 你 来 了 ， 这 可 怎 么 办 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27687', '44', '21', '23', '你 就 照 着 我 们 的 话 行 吧 ！ 我 们 这 里 有 四 个 人 ， 都 有 愿 在 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27688', '44', '21', '24', '你 带 他 们 去 ， 与 他 们 一 同 行 洁 净 的 礼 ， 替 他 们 拿 出 规 费 ， 叫 他 们 得 以 剃 头 。 这 样 ， 众 人 就 可 知 道 ， 先 前 所 听 见 你 的 事 都 是 虚 的 ； 并 可 知 道 ， 你 自 己 为 人 ， 循 规 蹈 矩 ， 遵 行 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27689', '44', '21', '25', '至 于 信 主 的 外 邦 人 ， 我 们 已 经 写 信 拟 定 ， 叫 他 们 谨 忌 那 祭 偶 像 之 物 ， 和 血 ， 并 勒 死 的 牲 畜 ， 与 奸 淫 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27690', '44', '21', '26', '于 是 保 罗 带 着 那 四 个 人 ， 第 二 天 与 他 们 一 同 行 了 洁 净 的 礼 ， 进 了 殿 ， 报 明 洁 净 的 日 期 满 足 ， 只 等 祭 司 为 他 们 各 人 献 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27691', '44', '21', '27', '＜ 保 罗 在 圣 殿 里 被 捕 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27692', '44', '21', '28', '喊 叫 说 ： “ 以 色 列 人 来 帮 助 ， 这 就 是 在 各 处 教 训 众 人 糟 践 我 们 百 姓 和 律 法 ， 并 这 地 方 的 。 他 又 带 着 希 腊 人 进 殿 ， 污 秽 了 这 圣 地 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27693', '44', '21', '29', '（ 这 话 是 因 他 们 曾 看 见 以 弗 所 人 特 罗 非 摩 同 保 罗 在 城 里 ， 以 为 保 罗 带 他 进 了 殿 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27694', '44', '21', '30', '合 城 都 震 动 ， 百 姓 一 齐 跑 来 ， 拿 住 保 罗 ， 拉 他 出 殿 ， 殿 门 立 刻 都 关 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27695', '44', '21', '31', '他 们 正 想 要 杀 他 ， 有 人 报 信 给 营 里 的 千 夫 长 说 ： “ 耶 路 撒 冷 合 城 都 乱 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27696', '44', '21', '32', '千 夫 长 立 时 带 着 兵 丁 和 几 个 百 夫 长 ， 跑 下 去 到 他 们 那 里 。 他 们 见 了 千 夫 长 和 兵 丁 ， 就 止 住 不 打 保 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27697', '44', '21', '33', '于 是 千 夫 长 上 前 拿 住 他 ， 吩 咐 用 两 条 铁 链 捆 锁 ； 又 问 他 是 什 么 人 ， 做 的 是 什 么 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27698', '44', '21', '34', '众 人 有 喊 叫 这 个 的 ， 有 喊 叫 那 个 的 ； 千 夫 长 因 为 这 样 乱 嚷 ， 得 不 着 实 情 ， 就 吩 咐 人 将 保 罗 带 进 营 楼 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27699', '44', '21', '35', '到 了 台 阶 上 ， 众 人 挤 得 凶 猛 ， 兵 丁 只 得 将 保 罗 抬 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27700', '44', '21', '36', '众 人 跟 在 后 面 ， 喊 着 说 ： “ 除 掉 他 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27701', '44', '21', '37', '＜ 保 罗 为 自 己 辩 护 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27702', '44', '21', '38', '你 莫 非 是 从 前 作 乱 、 带 领 四 千 凶 徒 往 旷 野 去 的 那 埃 及 人 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27703', '44', '21', '39', '保 罗 说 ： “ 我 本 是 犹 太 人 ， 生 在 基 利 家 的 大 数 ， 并 不 是 无 名 小 城 的 人 。 求 你 准 我 对 百 姓 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27704', '44', '21', '40', '千 夫 长 准 了 。 保 罗 就 站 在 台 阶 上 ， 向 百 姓 摆 手 ， 他 们 都 静 默 无 声 ， 保 罗 便 用 希 伯 来 话 对 他 们 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27705', '44', '22', '1', '“ 诸 位 父 兄 请 听 ， 我 现 在 对 你 们 分 诉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27706', '44', '22', '2', '众 人 听 他 说 的 是 希 伯 来 话 ， 就 更 加 安 静 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27707', '44', '22', '3', '保 罗 说 ： “ 我 原 是 犹 太 人 ， 生 在 基 利 家 的 大 数 ， 长 在 这 城 里 ， 在 迦 玛 列 门 下 ， 按 着 我 们 祖 宗 严 紧 的 律 法 受 教 ， 热 心 事 奉 神 ， 像 你 们 众 人 今 日 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27708', '44', '22', '4', '我 也 曾 逼 迫 奉 这 道 的 人 ， 直 到 死 地 ， 无 论 男 女 都 锁 拿 下 监 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27709', '44', '22', '5', '这 是 大 祭 司 和 众 长 老 都 可 以 给 我 作 见 证 的 。 我 又 领 了 他 们 达 与 弟 兄 的 书 信 ， 往 大 马 士 革 去 ， 要 把 在 那 里 奉 这 道 的 人 锁 拿 ， 带 到 耶 路 撒 冷 受 刑 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27710', '44', '22', '6', '＜ 保 罗 叙 述 归 主 的 经 过 （ 徒   9 : 1 - 1 9 ； 2 6 : 1 2 - 1 8 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27711', '44', '22', '7', '我 就 仆 倒 在 地 ， 听 见 有 声 音 对 我 说 ： ‘ 扫 罗 ！ 扫 罗 ！ 你 为 什 么 逼 迫 我 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27712', '44', '22', '8', '我 回 答 说 ： ‘ 主 啊 ， 你 是 谁 ？ ’ 他 说 ： ‘ 我 就 是 你 所 逼 迫 的 拿 撒 勒 人 耶 稣 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27713', '44', '22', '9', '与 我 同 行 的 人 看 见 了 那 光 ， 却 没 有 听 明 那 位 对 我 说 话 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27714', '44', '22', '10', '我 说 ： ‘ 主 啊 ， 我 当 做 什 么 ？ ’ 主 说 ： ‘ 起 来 ， 进 大 马 士 革 去 ， 在 那 里 ， 要 将 所 派 你 做 的 一 切 事 告 诉 你 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27715', '44', '22', '11', '我 因 那 光 的 荣 耀 不 能 看 见 ， 同 行 的 人 就 拉 着 我 手 进 了 大 马 士 革 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27716', '44', '22', '12', '那 里 有 一 个 人 ， 名 叫 亚 拿 尼 亚 ， 按 着 律 法 是 虔 诚 人 ， 为 一 切 住 在 那 里 的 犹 太 人 所 称 赞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27717', '44', '22', '13', '他 来 见 我 ， 站 在 旁 边 ， 对 我 说 ： ‘ 兄 弟 扫 罗 ， 你 可 以 看 见 。 ’ 我 当 时 往 上 一 看 ， 就 看 见 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27718', '44', '22', '14', '他 又 说 ： ‘ 我 们 祖 宗 的 神 拣 选 了 你 ， 叫 你 明 白 他 的 旨 意 ， 又 得 见 那 义 者 ， 听 他 口 中 所 出 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27719', '44', '22', '15', '因 为 你 要 将 所 看 见 的 ， 所 听 见 的 ， 对 着 万 人 为 他 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27720', '44', '22', '16', '现 在 你 为 什 么 耽 延 呢 ？ 起 来 ， 求 告 他 的 名 受 洗 ， 洗 去 你 的 罪 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27721', '44', '22', '17', '＜ 保 罗 奉 召 向 外 邦 人 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27722', '44', '22', '18', '看 见 主 向 我 说 ： ‘ 你 赶 紧 地 离 开 耶 路 撒 冷 ， 不 可 迟 延 ； 因 你 为 我 作 的 见 证 ， 这 里 的 人 必 不 领 受 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27723', '44', '22', '19', '我 就 说 ： ‘ 主 啊 ， 他 们 知 道 我 从 前 把 信 你 的 人 收 在 监 里 ， 又 在 各 会 堂 里 鞭 打 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27724', '44', '22', '20', '并 且 你 的 见 证 人 司 提 反 被 害 流 血 的 时 候 ， 我 也 站 在 旁 边 欢 喜 ； 又 看 守 害 死 他 之 人 的 衣 裳 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27725', '44', '22', '21', '主 向 我 说 ： ‘ 你 去 吧 ！ 我 要 差 你 远 远 地 往 外 邦 人 那 里 去 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27726', '44', '22', '22', '＜ 保 罗 与 长 官 交 涉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27727', '44', '22', '23', '众 人 喧 嚷 ， 摔 掉 衣 裳 ， 把 尘 土 向 空 中 扬 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27728', '44', '22', '24', '千 夫 长 就 吩 咐 将 保 罗 带 进 营 楼 去 ， 叫 人 用 鞭 子 拷 问 他 ， 要 知 道 他 们 向 他 这 样 喧 嚷 是 为 什 么 缘 故 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27729', '44', '22', '25', '刚 用 皮 条 捆 上 ， 保 罗 对 旁 边 站 着 的 百 夫 长 说 ： “ 人 是 罗 马 人 ， 又 没 有 定 罪 ， 你 们 就 鞭 打 他 ， 有 这 个 例 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27730', '44', '22', '26', '百 夫 长 听 见 这 话 ， 就 去 见 千 夫 长 ， 告 诉 他 说 ： “ 你 要 做 什 么 ？ 这 人 是 罗 马 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27731', '44', '22', '27', '千 夫 长 就 来 问 保 罗 说 ： “ 你 告 诉 我 ， 你 是 罗 马 人 吗 ？ ” 保 罗 说 ： “ 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27732', '44', '22', '28', '千 夫 长 说 ： “ 我 用 许 多 银 子 才 入 了 罗 马 的 民 籍 。 ” 保 罗 说 ： “ 我 生 来 就 是 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27733', '44', '22', '29', '于 是 那 些 要 拷 问 保 罗 的 人 就 离 开 他 去 了 。 千 夫 长 既 知 道 他 是 罗 马 人 ， 又 因 为 捆 绑 了 他 ， 也 害 怕 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27734', '44', '22', '30', '＜ 保 罗 在 公 会 前 申 诉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27735', '44', '23', '1', '保 罗 定 睛 看 着 公 会 的 人 ， 说 ： “ 弟 兄 们 ， 我 在 神 面 前 行 事 为 人 都 是 凭 着 良 心 ， 直 到 今 日 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27736', '44', '23', '2', '大 祭 司 亚 拿 尼 亚 就 吩 咐 旁 边 站 着 的 人 打 他 的 嘴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27737', '44', '23', '3', '保 罗 对 他 说 ： “ 你 这 粉 饰 的 墙 ， 神 要 打 你 ！ 你 坐 堂 为 的 是 按 律 法 审 问 我 ， 你 竟 违 背 律 法 ， 吩 咐 人 打 我 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27738', '44', '23', '4', '站 在 旁 边 的 人 说 ： “ 你 辱 骂 神 的 大 祭 司 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27739', '44', '23', '5', '保 罗 说 ： “ 弟 兄 们 ， 我 不 晓 得 他 是 大 祭 司 ； 经 上 记 着 说 ： ‘ 不 可 毁 谤 你 百 姓 的 官 长 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27740', '44', '23', '6', '保 罗 看 出 大 众 一 半 是 撒 都 该 人 ， 一 半 是 法 利 赛 人 ， 就 在 公 会 中 大 声 说 ： “ 弟 兄 们 ， 我 是 法 利 赛 人 ， 也 是 法 利 赛 人 的 子 孙 。 我 现 在 受 审 问 ， 是 为 盼 望 死 人 复 活 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27741', '44', '23', '7', '说 了 这 话 ， 法 利 赛 人 和 撒 都 该 人 就 争 论 起 来 ， 会 众 分 为 两 党 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27742', '44', '23', '8', '因 为 撒 都 该 人 说 ， 没 有 复 活 ， 也 没 有 天 使 和 鬼 魂 ； 法 利 赛 人 却 说 ， 两 样 都 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27743', '44', '23', '9', '于 是 大 大 地 喧 嚷 起 来 。 有 几 个 法 利 赛 党 的 文 士 站 起 来 争 辩 说 ： “ 我 们 看 不 出 这 人 有 什 么 恶 处 ， 倘 若 有 鬼 魂 或 是 天 使 对 他 说 过 话 ， 怎 么 样 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27744', '44', '23', '10', '那 时 大 起 争 吵 ， 千 夫 长 恐 怕 保 罗 被 他 们 扯 碎 了 ， 就 吩 咐 兵 丁 下 去 ， 把 他 从 众 人 当 中 抢 出 来 ， 带 进 营 楼 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27745', '44', '23', '11', '当 夜 ， 主 站 在 保 罗 旁 边 ， 说 ： “ 放 心 吧 ！ 你 怎 样 在 耶 路 撒 冷 为 我 作 见 证 ， 也 必 怎 样 在 罗 马 为 我 作 见 证 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27746', '44', '23', '12', '＜ 杀 害 保 罗 的 阴 谋 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27747', '44', '23', '13', '这 样 同 心 起 誓 的 有 四 十 多 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27748', '44', '23', '14', '他 们 来 见 祭 司 长 和 长 老 ， 说 ： “ 我 们 已 经 起 了 一 个 大 誓 ， 若 不 先 杀 保 罗 就 不 吃 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27749', '44', '23', '15', '现 在 你 们 和 公 会 要 知 会 千 夫 长 ， 叫 他 带 下 保 罗 到 你 们 这 里 来 ， 假 作 要 详 细 察 考 他 的 事 ； 我 们 已 经 预 备 好 了 ， 不 等 他 来 到 跟 前 就 杀 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27750', '44', '23', '16', '保 罗 的 外 甥 听 见 他 们 设 下 埋 伏 ， 就 来 到 营 楼 里 告 诉 保 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27751', '44', '23', '17', '保 罗 请 一 个 百 夫 长 来 ， 说 ： “ 你 领 这 少 年 人 去 见 千 夫 长 ， 他 有 事 告 诉 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27752', '44', '23', '18', '于 是 把 他 领 去 见 千 夫 长 ， 说 ： “ 被 囚 的 保 罗 请 我 到 他 那 里 ， 求 我 领 这 少 年 人 来 见 你 ； 他 有 事 告 诉 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27753', '44', '23', '19', '千 夫 长 就 拉 着 他 的 手 ， 走 到 一 旁 ， 私 下 问 他 说 ： “ 你 有 什 么 事 告 诉 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27754', '44', '23', '20', '他 说 ： “ 犹 太 人 已 经 约 定 ， 要 求 你 明 天 带 下 保 罗 到 公 会 里 去 ， 假 作 要 详 细 查 问 他 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27755', '44', '23', '21', '你 切 不 要 随 从 他 们 ； 因 为 他 们 有 四 十 多 人 埋 伏 ， 已 经 起 誓 说 ： 若 不 先 杀 保 罗 就 不 吃 不 喝 。 现 在 预 备 好 了 ， 只 等 你 应 允 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27756', '44', '23', '22', '于 是 千 夫 长 打 发 少 年 人 走 ， 嘱 咐 他 说 ： “ 不 要 告 诉 人 你 将 这 事 报 给 我 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27757', '44', '23', '23', '＜ 保 罗 被 解 交 腓 力 斯 巡 抚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27758', '44', '23', '24', '也 要 预 备 牲 口 叫 保 罗 骑 上 ， 护 送 到 巡 抚 腓 力 斯 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27759', '44', '23', '25', '千 夫 长 又 写 了 文 书 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27760', '44', '23', '26', '大 略 说 ： “ 克 劳 第 ． 吕 西 亚 ， 请 巡 抚 腓 力 斯 大 人 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27761', '44', '23', '27', '这 人 被 犹 太 人 拿 住 ， 将 要 杀 害 ， 我 得 知 他 是 罗 马 人 ， 就 带 兵 丁 下 去 救 他 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27762', '44', '23', '28', '因 要 知 道 他 们 告 他 的 缘 故 ， 我 就 带 他 下 到 他 们 的 公 会 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27763', '44', '23', '29', '便 查 知 他 被 告 是 因 他 们 律 法 的 辩 论 ， 并 没 有 什 么 该 死 该 绑 的 罪 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27764', '44', '23', '30', '后 来 有 人 把 要 害 他 的 计 谋 告 诉 我 ， 我 就 立 时 解 他 到 你 那 里 去 ， 又 吩 咐 告 他 的 人 在 你 面 前 告 他 。 ｛ 有 古 卷 加 ： 愿 你 平 安 ！ ｝ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27765', '44', '23', '31', '于 是 ， 兵 丁 照 所 吩 咐 他 们 的 ， 将 保 罗 夜 里 带 到 安 提 帕 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27766', '44', '23', '32', '第 二 天 ， 让 马 兵 护 送 ， 他 们 就 回 营 楼 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27767', '44', '23', '33', '马 兵 来 到 凯 撒 利 亚 ， 把 文 书 呈 给 巡 抚 ， 便 叫 保 罗 站 在 他 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27768', '44', '23', '34', '巡 抚 看 了 文 书 ， 问 保 罗 是 哪 省 的 人 ， 既 晓 得 他 是 基 利 家 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27769', '44', '23', '35', '就 说 ： “ 等 告 你 的 人 来 到 ， 我 要 细 听 你 的 事 ” ； 便 吩 咐 人 把 他 看 守 在 希 律 的 衙 门 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27770', '44', '24', '1', '＜ 犹 太 人 控 告 保 罗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27771', '44', '24', '2', '保 罗 被 提 了 来 ， 帖 士 罗 就 告 他 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27772', '44', '24', '3', '“ 腓 力 斯 大 人 ， 我 们 因 你 得 以 大 享 太 平 ， 并 且 这 一 国 的 弊 病 ， 因 着 你 的 先 见 得 以 更 正 了 ； 我 们 随 时 随 地 满 心 感 谢 不 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27773', '44', '24', '4', '惟 恐 多 说 ， 你 嫌 烦 絮 ， 只 求 你 宽 容 听 我 们 说 几 句 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27774', '44', '24', '5', '我 们 看 这 个 人 ， 如 同 瘟 疫 一 般 ， 是 鼓 动 普 天 下 众 犹 太 人 生 乱 的 ， 又 是 拿 撒 勒 教 党 里 的 一 个 头 目 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27775', '44', '24', '6', '连 圣 殿 他 也 想 要 污 秽 ； 我 们 把 他 捉 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27776', '44', '24', '7', '｛ 有 古 卷 加 ： 要 按 我 们 的 律 法 审 问 ， 不 料 千 夫 长 吕 西 亚 前 来 ， 甚 是 强 横 ， 从 我 们 手 中 把 他 夺 去 ， 吩 咐 告 他 的 人 到 你 这 里 来 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27777', '44', '24', '8', '你 自 己 究 问 他 ， 就 可 以 知 道 我 们 告 他 的 一 切 事 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27778', '44', '24', '9', '众 犹 太 人 也 随 着 告 他 说 ： “ 事 情 诚 然 是 这 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27779', '44', '24', '10', '＜ 保 罗 为 自 己 辩 护 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27780', '44', '24', '11', '你 查 问 就 可 以 知 道 ， 从 我 上 耶 路 撒 冷 礼 拜 到 今 日 不 过 有 十 二 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27781', '44', '24', '12', '他 们 并 没 有 看 见 我 在 殿 里 ， 或 是 在 会 堂 里 ， 或 是 在 城 里 ， 和 人 辩 论 ， 耸 动 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27782', '44', '24', '13', '他 们 现 在 所 告 我 的 事 并 不 能 对 你 证 实 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27783', '44', '24', '14', '但 有 一 件 事 ， 我 向 你 承 认 ， 就 是 他 们 所 称 为 异 端 的 道 ， 我 正 按 着 那 道 事 奉 我 祖 宗 的 神 ， 又 信 合 乎 律 法 的 和 先 知 书 上 一 切 所 记 载 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27784', '44', '24', '15', '并 且 靠 着 神 ， 盼 望 死 人 ， 无 论 善 恶 ， 都 要 复 活 ， 就 是 他 们 自 己 也 有 这 个 盼 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27785', '44', '24', '16', '我 因 此 自 己 勉 励 ， 对 神 对 人 ， 常 存 无 亏 的 良 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27786', '44', '24', '17', '过 了 几 年 ， 我 带 着 赒 济 本 国 的 捐 项 和 供 献 的 物 上 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27787', '44', '24', '18', '正 献 的 时 候 ， 他 们 看 见 我 在 殿 里 已 经 洁 净 了 ， 并 没 有 聚 众 ， 也 没 有 吵 嚷 ， 惟 有 几 个 从 亚 细 亚 来 的 犹 太 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27788', '44', '24', '19', '他 们 若 有 告 我 的 事 ， 就 应 当 到 你 面 前 来 告 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27789', '44', '24', '20', '即 或 不 然 ， 这 些 人 若 看 出 我 站 在 公 会 前 ， 有 妄 为 的 地 方 ， 他 们 自 己 也 可 以 说 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27790', '44', '24', '21', '纵 然 有 ， 也 不 过 一 句 话 ， 就 是 我 站 在 他 们 中 间 大 声 说 ： ‘ 我 今 日 在 你 们 面 前 受 审 ， 是 为 死 人 复 活 的 道 理 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27791', '44', '24', '22', '腓 力 斯 本 是 详 细 晓 得 这 道 ， 就 支 吾 他 们 说 ： “ 且 等 千 夫 长 吕 西 亚 下 来 ， 我 要 审 断 你 们 的 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27792', '44', '24', '23', '于 是 吩 咐 百 夫 长 看 守 保 罗 ， 并 且 宽 待 他 ， 也 不 拦 阻 他 的 亲 友 来 供 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27793', '44', '24', '24', '＜ 腓 力 斯 留 保 罗 在 监 里 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27794', '44', '24', '25', '保 罗 讲 论 公 义 、 节 制 ， 和 将 来 的 审 判 。 腓 力 斯 甚 觉 恐 惧 ， 说 ： “ 你 暂 且 去 吧 ， 等 我 得 便 再 叫 你 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27795', '44', '24', '26', '腓 力 斯 又 指 望 保 罗 送 他 银 钱 ， 所 以 屡 次 叫 他 来 ， 和 他 谈 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27796', '44', '24', '27', '过 了 两 年 ， 波 求 ． 非 斯 都 接 了 腓 力 斯 的 任 ； 腓 力 斯 要 讨 犹 太 人 的 喜 欢 ， 就 留 保 罗 在 监 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27797', '44', '25', '1', '＜ 保 罗 要 向 凯 撒 上 诉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27798', '44', '25', '2', '祭 司 长 和 犹 太 人 的 首 领 向 他 控 告 保 罗 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27799', '44', '25', '3', '又 央 告 他 ， 求 他 的 情 ， 将 保 罗 提 到 耶 路 撒 冷 来 ， 他 们 要 在 路 上 埋 伏 杀 害 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27800', '44', '25', '4', '非 斯 都 却 回 答 说 ： “ 保 罗 押 在 凯 撒 利 亚 ， 我 自 己 快 要 往 那 里 去 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27801', '44', '25', '5', '又 说 ： “ 你 们 中 间 有 权 势 的 人 与 我 一 同 下 去 ， 那 人 若 有 什 么 不 是 ， 就 可 以 告 他 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27802', '44', '25', '6', '非 斯 都 在 他 们 那 里 住 了 不 过 十 天 八 天 ， 就 下 凯 撒 利 亚 去 ； 第 二 天 坐 堂 ， 吩 咐 将 保 罗 提 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27803', '44', '25', '7', '保 罗 来 了 ， 那 些 从 耶 路 撒 冷 下 来 的 犹 太 人 周 围 站 着 ， 将 许 多 重 大 的 事 控 告 他 ， 都 是 不 能 证 实 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27804', '44', '25', '8', '保 罗 分 诉 说 ： “ 无 论 犹 太 人 的 律 法 ， 或 是 圣 殿 ， 或 是 凯 撒 ， 我 都 没 有 干 犯 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27805', '44', '25', '9', '但 非 斯 都 要 讨 犹 太 人 的 喜 欢 ， 就 问 保 罗 说 ： “ 你 愿 意 上 耶 路 撒 冷 去 ， 在 那 里 听 我 审 断 这 事 吗 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27806', '44', '25', '10', '保 罗 说 ： “ 我 站 在 凯 撒 的 堂 前 ， 这 就 是 我 应 当 受 审 的 地 方 。 我 向 犹 太 人 并 没 有 行 过 什 么 不 义 的 事 ， 这 也 是 你 明 明 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27807', '44', '25', '11', '我 若 行 了 不 义 的 事 ， 犯 了 什 么 该 死 的 罪 ， 就 是 死 ， 我 也 不 辞 。 他 们 所 告 我 的 事 若 都 不 实 ， 就 没 有 人 可 以 把 我 交 给 他 们 。 我 要 上 告 于 凯 撒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27808', '44', '25', '12', '非 斯 都 和 议 会 商 量 了 ， 就 说 ： “ 你 既 上 告 于 凯 撒 ， 可 以 往 凯 撒 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27809', '44', '25', '13', '＜ 保 罗 被 带 到 亚 基 帕 王 面 前 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27810', '44', '25', '14', '在 那 里 住 了 多 日 ， 非 斯 都 将 保 罗 的 事 告 诉 王 ， 说 ： “ 这 里 有 一 个 人 ， 是 腓 力 斯 留 在 监 里 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27811', '44', '25', '15', '我 在 耶 路 撒 冷 的 时 候 ， 祭 司 长 和 犹 太 的 长 老 将 他 的 事 禀 报 了 我 ， 求 我 定 他 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27812', '44', '25', '16', '我 对 他 们 说 ， 无 论 什 么 人 ， 被 告 还 没 有 和 原 告 对 质 ， 未 得 机 会 分 诉 所 告 他 的 事 ， 就 先 定 他 的 罪 ， 这 不 是 罗 马 人 的 条 例 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27813', '44', '25', '17', '及 至 他 们 都 来 到 这 里 ， 我 就 不 耽 延 ， 第 二 天 便 坐 堂 ， 吩 咐 把 那 人 提 上 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27814', '44', '25', '18', '告 他 的 人 站 着 告 他 ； 所 告 的 ， 并 没 有 我 所 逆 料 的 那 等 恶 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27815', '44', '25', '19', '不 过 是 有 几 样 辩 论 ， 为 他 们 自 己 敬 鬼 神 的 事 ， 又 为 一 个 人 名 叫 耶 稣 ， 是 已 经 死 了 ， 保 罗 却 说 他 是 活 着 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27816', '44', '25', '20', '这 些 事 当 怎 样 究 问 ， 我 心 里 作 难 ， 所 以 问 他 说 ： ‘ 你 愿 意 上 耶 路 撒 冷 去 ， 在 那 里 为 这 些 事 听 审 吗 ？ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27817', '44', '25', '21', '但 保 罗 求 我 留 下 他 ， 要 听 皇 上 审 断 ， 我 就 吩 咐 把 他 留 下 ， 等 我 解 他 到 凯 撒 那 里 去 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27818', '44', '25', '22', '亚 基 帕 对 非 斯 都 说 ： “ 我 自 己 也 愿 听 这 人 辩 论 。 ” 非 斯 都 说 ： “ 明 天 你 可 以 听 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27819', '44', '25', '23', '第 二 天 ， 亚 基 帕 和 百 妮 基 大 张 威 势 而 来 ， 同 着 众 千 夫 长 和 城 里 的 尊 贵 人 进 了 公 厅 。 非 斯 都 吩 咐 一 声 ， 就 有 人 将 保 罗 带 进 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27820', '44', '25', '24', '非 斯 都 说 ： “ 亚 基 帕 王 和 在 这 里 的 诸 位 啊 ， 你 们 看 这 人 ， 就 是 一 切 犹 太 人 ， 在 耶 路 撒 冷 和 这 里 ， 曾 向 我 恳 求 、 呼 叫 说 ： ‘ 不 可 容 他 再 活 着 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27821', '44', '25', '25', '但 我 查 明 他 没 有 犯 什 么 该 死 的 罪 ， 并 且 他 自 己 上 告 于 皇 帝 ， 所 以 我 定 意 把 他 解 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27822', '44', '25', '26', '论 到 这 人 ， 我 没 有 确 实 的 事 可 以 奏 明 主 上 。 因 此 ， 我 带 他 到 你 们 面 前 ， 也 特 意 带 他 到 你 亚 基 帕 王 面 前 ， 为 要 在 查 问 之 后 有 所 陈 奏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27823', '44', '25', '27', '据 我 看 来 ， 解 送 囚 犯 ， 不 指 明 他 的 罪 案 是 不 合 理 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27824', '44', '26', '1', '＜ 保 罗 在 亚 基 帕 王 面 前 申 辩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27825', '44', '26', '2', '“ 亚 基 帕 王 啊 ， 犹 太 人 所 告 我 的 一 切 事 ， 今 日 得 在 你 面 前 分 诉 ， 实 为 万 幸 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27826', '44', '26', '3', '更 可 幸 的 ， 是 你 熟 悉 犹 太 人 的 规 矩 和 他 们 的 辩 论 ； 所 以 求 你 耐 心 听 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27827', '44', '26', '4', '我 从 起 初 在 本 国 的 民 中 ， 并 在 耶 路 撒 冷 ， 自 幼 为 人 如 何 ， 犹 太 人 都 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27828', '44', '26', '5', '他 们 若 肯 作 见 证 就 晓 得 ， 我 从 起 初 是 按 着 我 们 教 中 最 严 紧 的 教 门 作 了 法 利 赛 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27829', '44', '26', '6', '现 在 我 站 在 这 里 受 审 ， 是 因 为 指 望 神 向 我 们 祖 宗 所 应 许 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27830', '44', '26', '7', '这 应 许 ， 我 们 十 二 个 支 派 ， 昼 夜 切 切 地 事 奉 神 ， 都 指 望 得 着 。 王 啊 ， 我 被 犹 太 人 控 告 ， 就 是 因 这 指 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27831', '44', '26', '8', '神 叫 死 人 复 活 ， 你 们 为 什 么 看 作 不 可 信 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27832', '44', '26', '9', '从 前 我 自 己 以 为 应 当 多 方 攻 击 拿 撒 勒 人 耶 稣 的 名 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27833', '44', '26', '10', '我 在 耶 路 撒 冷 也 曾 这 样 行 了 。 既 从 祭 司 长 得 了 权 柄 ， 我 就 把 许 多 圣 徒 囚 在 监 里 。 他 们 被 杀 ， 我 也 出 名 定 案 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27834', '44', '26', '11', '在 各 会 堂 ， 我 屡 次 用 刑 强 逼 他 们 说 亵 渎 的 话 ， 又 分 外 恼 恨 他 们 ， 甚 至 追 逼 他 们 ， 直 到 外 邦 的 城 邑 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27835', '44', '26', '12', '＜ 保 罗 叙 述 归 主 经 过 （ 徒   9 : 1 - 1 9 ； 2 2 : 6 - 1 6 ） ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27836', '44', '26', '13', '王 啊 ， 我 在 路 上 ， 晌 午 的 时 候 ， 看 见 从 天 发 光 ， 比 日 头 还 亮 ， 四 面 照 着 我 并 与 我 同 行 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27837', '44', '26', '14', '我 们 都 仆 倒 在 地 ， 我 就 听 见 有 声 音 用 希 伯 来 话 向 我 说 ： ‘ 扫 罗 ！ 扫 罗 ！ 为 什 么 逼 迫 我 ？ 你 用 脚 踢 刺 是 难 的 ！ ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27838', '44', '26', '15', '我 说 ： ‘ 主 啊 ， 你 是 谁 ？ ’ 主 说 ： ‘ 我 就 是 你 所 逼 迫 的 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27839', '44', '26', '16', '你 起 来 站 着 ， 我 特 意 向 你 显 现 ， 要 派 你 作 执 事 ， 作 见 证 ， 将 你 所 看 见 的 事 和 我 将 要 指 示 你 的 事 证 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27840', '44', '26', '17', '我 也 要 救 你 脱 离 百 姓 和 外 邦 人 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27841', '44', '26', '18', '我 差 你 到 他 们 那 里 去 ， 要 叫 他 们 的 眼 睛 得 开 ， 从 黑 暗 中 归 向 光 明 ， 从 撒 但 权 下 归 向 神 ； 又 因 信 我 ， 得 蒙 赦 罪 ， 和 一 切 成 圣 的 人 同 得 基 业 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27842', '44', '26', '19', '＜ 保 罗 向 犹 太 和 外 邦 人 作 见 证 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27843', '44', '26', '20', '先 在 大 马 士 革 ， 后 在 耶 路 撒 冷 和 犹 太 全 地 ， 以 及 外 邦 ， 劝 勉 他 们 应 当 悔 改 归 向 神 ， 行 事 与 悔 改 的 心 相 称 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27844', '44', '26', '21', '因 此 ， 犹 太 人 在 殿 里 拿 住 我 ， 想 要 杀 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27845', '44', '26', '22', '然 而 我 蒙 神 的 帮 助 ， 直 到 今 日 还 站 得 住 ， 对 着 尊 贵 、 卑 贱 、 老 幼 作 见 证 ； 所 讲 的 并 不 外 乎 众 先 知 和 摩 西 所 说 将 来 必 成 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27846', '44', '26', '23', '就 是 基 督 必 须 受 害 ， 并 且 因 从 死 里 复 活 ， 要 首 先 把 光 明 的 道 传 给 百 姓 和 外 邦 人 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27847', '44', '26', '24', '＜ 保 罗 恳 请 亚 基 帕 信 主 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27848', '44', '26', '25', '保 罗 说 ： “ 非 斯 都 大 人 ， 我 不 是 癫 狂 ， 我 说 的 乃 是 真 实 明 白 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27849', '44', '26', '26', '王 也 晓 得 这 些 事 ， 所 以 我 向 王 放 胆 直 言 ， 我 深 信 这 些 事 没 有 一 件 向 王 隐 藏 的 ， 因 都 不 是 在 背 地 里 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27850', '44', '26', '27', '亚 基 帕 王 啊 ， 你 信 先 知 吗 ？ 我 知 道 你 是 信 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27851', '44', '26', '28', '亚 基 帕 对 保 罗 说 ： “ 你 想 少 微 一 劝 ， 便 叫 我 作 基 督 徒 啊 ｛ 或 译 ： 你 这 样 劝 我 ， 几 乎 叫 我 作 基 督 徒 了 ｝ ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27852', '44', '26', '29', '保 罗 说 ： “ 无 论 是 少 劝 是 多 劝 ， 我 向 神 所 求 的 ， 不 但 你 一 个 人 ， 就 是 今 天 一 切 听 我 的 ， 都 要 像 我 一 样 ， 只 是 不 要 像 我 有 这 些 锁 炼 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27853', '44', '26', '30', '于 是 ， 王 和 巡 抚 并 百 妮 基 与 同 坐 的 人 都 起 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27854', '44', '26', '31', '退 到 里 面 ， 彼 此 谈 论 说 ： “ 这 人 并 没 有 犯 什 么 该 死 该 绑 的 罪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27855', '44', '26', '32', '亚 基 帕 又 对 非 斯 都 说 ： “ 这 人 若 没 有 上 告 于 凯 撒 ， 就 可 以 释 放 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27856', '44', '27', '1', '＜ 保 罗 坐 船 往 罗 马 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27857', '44', '27', '2', '有 一 只 亚 大 米 田 的 船 ， 要 沿 着 亚 细 亚 一 带 地 方 的 海 边 走 ， 我 们 就 上 了 那 船 开 行 ； 有 马 其 顿 的 帖 撒 罗 尼 迦 人 亚 里 达 古 和 我 们 同 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27858', '44', '27', '3', '第 二 天 ， 到 了 西 顿 ； 犹 流 宽 待 保 罗 ， 准 他 往 朋 友 那 里 去 ， 受 他 们 的 照 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27859', '44', '27', '4', '从 那 里 又 开 船 ， 因 为 风 不 顺 ， 就 贴 着 塞 浦 路 斯 背 风 岸 行 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27860', '44', '27', '5', '过 了 基 利 家 、 旁 非 利 亚 前 面 的 海 ， 就 到 了 吕 家 的 每 拉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27861', '44', '27', '6', '在 那 里 ， 百 夫 长 遇 见 一 只 亚 历 山 大 的 船 ， 要 往 意 大 利 去 ， 便 叫 我 们 上 了 那 船 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27862', '44', '27', '7', '一 连 多 日 ， 船 行 得 慢 ， 仅 仅 来 到 革 尼 土 的 对 面 。 因 为 被 风 拦 阻 ， 就 贴 着 克 里 特 背 风 岸 ， 从 撒 摩 尼 对 面 行 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27863', '44', '27', '8', '我 们 沿 岸 行 走 ， 仅 仅 来 到 一 个 地 方 ， 名 叫 佳 澳 ； 离 那 里 不 远 ， 有 拉 西 亚 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27864', '44', '27', '9', '走 的 日 子 多 了 ， 已 经 过 了 禁 食 的 节 期 ， 行 船 又 危 险 ， 保 罗 就 劝 众 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27865', '44', '27', '10', '“ 众 位 ， 我 看 这 次 行 船 ， 不 但 货 物 和 船 要 受 损 伤 ， 大 遭 破 坏 ， 连 我 们 的 性 命 也 难 保 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27866', '44', '27', '11', '但 百 夫 长 信 从 掌 船 的 和 船 主 ， 不 信 从 保 罗 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27867', '44', '27', '12', '且 因 在 这 海 口 过 冬 不 便 ， 船 上 的 人 就 多 半 说 ， 不 如 开 船 离 开 这 地 方 ， 或 者 能 到 菲 尼 基 过 冬 。 菲 尼 基 是 克 里 特 的 一 个 海 口 ， 一 面 朝 东 北 ， 一 面 朝 东 南 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27868', '44', '27', '13', '＜ 海 上 的 风 暴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27869', '44', '27', '14', '不 多 几 时 ， 狂 风 从 岛 上 扑 下 来 ； 那 风 名 叫 “ 友 拉 革 罗 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27870', '44', '27', '15', '船 被 风 抓 住 ， 敌 不 住 风 ， 我 们 就 任 风 刮 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27871', '44', '27', '16', '贴 着 一 个 小 岛 的 背 风 岸 奔 行 ， 那 岛 名 叫 高 大 ， 在 那 里 仅 仅 收 住 了 小 船 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27872', '44', '27', '17', '既 然 把 小 船 拉 上 来 ， 就 用 缆 索 捆 绑 船 底 ， 又 恐 怕 在 赛 耳 底 沙 滩 上 搁 了 浅 ， 就 落 下 篷 来 ， 任 船 飘 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27873', '44', '27', '18', '我 们 被 风 浪 逼 得 甚 急 ， 第 二 天 众 人 就 把 货 物 抛 在 海 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27874', '44', '27', '19', '到 第 三 天 ， 他 们 又 亲 手 把 船 上 的 器 具 抛 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27875', '44', '27', '20', '太 阳 和 星 辰 多 日 不 显 露 ， 又 有 狂 风 大 浪 催 逼 ， 我 们 得 救 的 指 望 就 都 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27876', '44', '27', '21', '众 人 多 日 没 有 吃 什 么 ， 保 罗 就 出 来 站 在 他 们 中 间 ， 说 ： “ 众 位 ， 你 们 本 该 听 我 的 话 ， 不 离 开 克 里 特 ， 免 得 遭 这 样 的 伤 损 破 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27877', '44', '27', '22', '现 在 我 还 劝 你 们 放 心 ， 你 们 的 性 命 一 个 也 不 失 丧 ， 惟 独 失 丧 这 船 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27878', '44', '27', '23', '因 我 所 属 所 事 奉 的 神 ， 他 的 使 者 昨 夜 站 在 我 旁 边 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27879', '44', '27', '24', '‘ 保 罗 ， 不 要 害 怕 ， 你 必 定 站 在 凯 撒 面 前 ， 并 且 与 你 同 船 的 人 ， 神 都 赐 给 你 了 。 ’');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27880', '44', '27', '25', '所 以 众 位 可 以 放 心 ， 我 信 神 他 怎 样 对 我 说 ， 事 情 也 要 怎 样 成 就 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27881', '44', '27', '26', '只 是 我 们 必 要 撞 在 一 个 岛 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27882', '44', '27', '27', '到 了 第 十 四 天 夜 间 ， 船 在 亚 得 里 亚 海 飘 来 飘 去 。 约 到 半 夜 ， 水 手 以 为 渐 近 旱 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27883', '44', '27', '28', '就 探 深 浅 ， 探 得 有 十 二 丈 ； 稍 往 前 行 ， 又 探 深 浅 ， 探 得 有 九 丈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27884', '44', '27', '29', '恐 怕 撞 在 石 头 上 ， 就 从 船 尾 抛 下 四 个 锚 ， 盼 望 天 亮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27885', '44', '27', '30', '水 手 想 要 逃 出 船 去 ， 把 小 船 放 在 海 里 ， 假 作 要 从 船 头 抛 锚 的 样 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27886', '44', '27', '31', '保 罗 对 百 夫 长 和 兵 丁 说 ： “ 这 些 人 若 不 等 在 船 上 ， 你 们 必 不 能 得 救 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27887', '44', '27', '32', '于 是 兵 丁 砍 断 小 船 的 绳 子 ， 由 它 飘 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27888', '44', '27', '33', '天 渐 亮 的 时 候 ， 保 罗 劝 众 人 都 吃 饭 ， 说 ： “ 你 们 悬 望 忍 饿 不 吃 什 么 ， 已 经 十 四 天 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27889', '44', '27', '34', '所 以 我 劝 你 们 吃 饭 ， 这 是 关 乎 你 们 救 命 的 事 ； 因 为 你 们 各 人 连 一 根 头 发 也 不 至 于 损 坏 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27890', '44', '27', '35', '保 罗 说 了 这 话 ， 就 拿 着 饼 ， 在 众 人 面 前 祝 谢 了 神 ， 擘 开 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27891', '44', '27', '36', '于 是 他 们 都 放 下 心 ， 也 就 吃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27892', '44', '27', '37', '我 们 在 船 上 的 共 有 二 百 七 十 六 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27893', '44', '27', '38', '他 们 吃 饱 了 ， 就 把 船 上 的 麦 子 抛 在 海 里 ， 为 要 叫 船 轻 一 点 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27894', '44', '27', '39', '＜ 船 搁 了 浅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27895', '44', '27', '40', '于 是 砍 断 缆 索 ， 弃 锚 在 海 里 ； 同 时 也 松 开 舵 绳 ， 拉 起 头 篷 ， 顺 着 风 向 岸 行 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27896', '44', '27', '41', '但 遇 着 两 水 夹 流 的 地 方 ， 就 把 船 搁 了 浅 ； 船 头 胶 住 不 动 ， 船 尾 被 浪 的 猛 力 冲 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27897', '44', '27', '42', '兵 丁 的 意 思 要 把 囚 犯 杀 了 ， 恐 怕 有 洑 水 脱 逃 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27898', '44', '27', '43', '但 百 夫 长 要 救 保 罗 ， 不 准 他 们 任 意 而 行 ， 就 吩 咐 会 洑 水 的 ， 跳 下 水 去 先 上 岸 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27899', '44', '27', '44', '其 余 的 人 可 以 用 板 子 或 船 上 的 零 碎 东 西 上 岸 。 这 样 ， 众 人 都 得 了 救 ， 上 了 岸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27900', '44', '28', '1', '＜ 保 罗 在 马 耳 他 岛 上 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27901', '44', '28', '2', '土 人 看 待 我 们 ， 有 非 常 的 情 分 ； 因 为 当 时 下 雨 ， 天 气 又 冷 ， 就 生 火 接 待 我 们 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27902', '44', '28', '3', '那 时 ， 保 罗 拾 起 一 捆 柴 ， 放 在 火 上 ， 有 一 条 毒 蛇 ， 因 为 热 了 出 来 ， 咬 住 他 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27903', '44', '28', '4', '土 人 看 见 那 毒 蛇 悬 在 他 手 上 ， 就 彼 此 说 ： “ 这 人 必 是 个 凶 手 ， 虽 然 从 海 里 救 上 来 ， 天 理 还 不 容 他 活 着 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27904', '44', '28', '5', '保 罗 竟 把 那 毒 蛇 甩 在 火 里 ， 并 没 有 受 伤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27905', '44', '28', '6', '土 人 想 他 必 要 肿 起 来 ， 或 是 忽 然 仆 倒 死 了 ； 看 了 多 时 ， 见 他 无 害 ， 就 转 念 ， 说 ： “ 他 是 个 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27906', '44', '28', '7', '离 那 地 方 不 远 ， 有 田 产 是 岛 长 部 百 流 的 ； 他 接 纳 我 们 ， 尽 情 款 待 三 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27907', '44', '28', '8', '当 时 ， 部 百 流 的 父 亲 患 热 病 和 痢 疾 躺 着 。 保 罗 进 去 ， 为 他 祷 告 ， 按 手 在 他 身 上 ， 治 好 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27908', '44', '28', '9', '从 此 ， 岛 上 其 余 的 病 人 也 来 ， 得 了 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27909', '44', '28', '10', '他 们 又 多 方 地 尊 敬 我 们 ； 到 了 开 船 的 时 候 ， 也 把 我 们 所 需 用 的 送 到 船 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27910', '44', '28', '11', '＜ 保 罗 抵 达 罗 马 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27911', '44', '28', '12', '到 了 叙 拉 古 ， 我 们 停 泊 三 日 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27912', '44', '28', '13', '又 从 那 里 绕 行 ， 来 到 利 基 翁 。 过 了 一 天 ， 起 了 南 风 ， 第 二 天 就 来 到 部 丢 利 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27913', '44', '28', '14', '在 那 里 遇 见 弟 兄 们 ， 请 我 们 与 他 们 同 住 了 七 天 。 这 样 ， 我 们 来 到 罗 马 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27914', '44', '28', '15', '那 里 的 弟 兄 们 一 听 见 我 们 的 信 息 就 出 来 ， 到 亚 比 乌 市 和 三 馆 地 方 迎 接 我 们 。 保 罗 见 了 他 们 ， 就 感 谢 神 ， 放 心 壮 胆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27915', '44', '28', '16', '进 了 罗 马 城 ， ｛ 有 古 卷 加 ： 百 夫 长 把 众 囚 犯 交 给 御 营 的 统 领 ， 惟 有 ｝ 保 罗 蒙 准 和 一 个 看 守 他 的 兵 另 住 在 一 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27916', '44', '28', '17', '＜ 保 罗 在 罗 马 传 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27917', '44', '28', '18', '他 们 审 问 了 我 ， 就 愿 意 释 放 我 ； 因 为 在 我 身 上 ， 并 没 有 该 死 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27918', '44', '28', '19', '无 奈 犹 太 人 不 服 ， 我 不 得 已 ， 只 好 上 告 于 凯 撒 ， 并 非 有 什 么 事 要 控 告 我 本 国 的 百 姓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27919', '44', '28', '20', '因 此 ， 我 请 你 们 来 见 面 说 话 ， 我 原 为 以 色 列 人 所 指 望 的 ， 被 这 链 子 捆 锁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27920', '44', '28', '21', '他 们 说 ： “ 我 们 并 没 有 接 着 从 犹 太 来 论 你 的 信 ， 也 没 有 弟 兄 到 这 里 来 报 给 我 们 说 你 有 什 么 不 好 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27921', '44', '28', '22', '但 我 们 愿 意 听 你 的 意 见 如 何 ； 因 为 这 教 门 ， 我 们 晓 得 是 到 处 被 毁 谤 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27922', '44', '28', '23', '他 们 和 保 罗 约 定 了 日 子 ， 就 有 许 多 人 到 他 的 寓 处 来 。 保 罗 从 早 到 晚 ， 对 他 们 讲 论 这 事 ， 证 明 神 国 的 道 ， 引 摩 西 的 律 法 和 先 知 的 书 ， 以 耶 稣 的 事 劝 勉 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27923', '44', '28', '24', '他 所 说 的 话 ， 有 信 的 ， 有 不 信 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27924', '44', '28', '25', '他 们 彼 此 不 合 ， 就 散 了 ； 未 散 以 先 ， 保 罗 说 了 一 句 话 ， 说 ： “ 圣 灵 藉 先 知 以 赛 亚 向 你 们 祖 宗 所 说 的 话 是 不 错 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27925', '44', '28', '26', '他 说 ： 你 去 告 诉 这 百 姓 说 ： 你 们 听 是 要 听 见 ， 却 不 明 白 ； 看 是 要 看 见 ， 却 不 晓 得 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27926', '44', '28', '27', '因 为 这 百 姓 油 蒙 了 心 ， 耳 朵 发 沉 ， 眼 睛 闭 着 ； 恐 怕 眼 睛 看 见 ， 耳 朵 听 见 ， 心 里 明 白 ， 回 转 过 来 ， 我 就 医 治 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27927', '44', '28', '28', '所 以 你 们 当 知 道 ， 神 这 救 恩 ， 如 今 传 给 外 邦 人 ， 他 们 也 必 听 受 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27928', '44', '28', '29', '｛ 有 古 卷 加 ： 保 罗 说 了 这 话 ， 犹 太 人 议 论 纷 纷 地 就 走 了 。 ｝');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27929', '44', '28', '30', '保 罗 在 自 己 所 租 的 房 子 里 住 了 足 足 两 年 。 凡 来 见 他 的 人 ， 他 全 都 接 待 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27930', '44', '28', '31', '放 胆 传 讲 神 国 的 道 ， 将 主 耶 稣 基 督 的 事 教 导 人 ， 并 没 有 人 禁 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27931', '45', '1', '1', '＜ 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27932', '45', '1', '2', '这 福 音 是 神 从 前 藉 众 先 知 在 圣 经 上 所 应 许 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27933', '45', '1', '3', '论 到 他 儿 子 ─ ─ 我 主 耶 稣 基 督 。 按 肉 体 说 ， 是 从 大 卫 后 裔 生 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27934', '45', '1', '4', '按 圣 善 的 灵 说 ， 因 从 死 里 复 活 ， 以 大 能 显 明 是 神 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27935', '45', '1', '5', '我 们 从 他 受 了 恩 惠 并 使 徒 的 职 分 ， 在 万 国 之 中 叫 人 为 他 的 名 信 服 真 道 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27936', '45', '1', '6', '其 中 也 有 你 们 这 蒙 召 属 耶 稣 基 督 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27937', '45', '1', '7', '我 写 信 给 你 们 在 罗 马 、 为 神 所 爱 、 奉 召 作 圣 徒 的 众 人 。 愿 恩 惠 、 平 安 从 我 们 的 父 神 并 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27938', '45', '1', '8', '＜ 保 罗 有 意 访 问 罗 马 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27939', '45', '1', '9', '我 在 他 儿 子 福 音 上 ， 用 心 灵 所 事 奉 的 神 可 以 见 证 ， 我 怎 样 不 住 地 提 到 你 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27940', '45', '1', '10', '在 祷 告 之 间 常 常 恳 求 ， 或 者 照 神 的 旨 意 ， 终 能 得 平 坦 的 道 路 往 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27941', '45', '1', '11', '因 为 我 切 切 地 想 见 你 们 ， 要 把 些 属 灵 的 恩 赐 分 给 你 们 ， 使 你 们 可 以 坚 固 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27942', '45', '1', '12', '这 样 ， 我 在 你 们 中 间 ， 因 你 与 我 彼 此 的 信 心 ， 就 可 以 同 得 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27943', '45', '1', '13', '弟 兄 们 ， 我 不 愿 意 你 们 不 知 道 ， 我 屡 次 定 意 往 你 们 那 里 去 ， 要 在 你 们 中 间 得 些 果 子 ， 如 同 在 其 余 的 外 邦 人 中 一 样 ； 只 是 到 如 今 仍 有 阻 隔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27944', '45', '1', '14', '无 论 是 希 腊 人 、 化 外 人 、 聪 明 人 、 愚 拙 人 ， 我 都 欠 他 们 的 债 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27945', '45', '1', '15', '所 以 情 愿 尽 我 的 力 量 ， 将 福 音 也 传 给 你 们 在 罗 马 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27946', '45', '1', '16', '＜ 福 音 是 神 的 大 能 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27947', '45', '1', '17', '因 为 神 的 义 正 在 这 福 音 上 显 明 出 来 ； 这 义 是 本 于 信 ， 以 至 于 信 。 如 经 上 所 记 ： “ 义 人 必 因 信 得 生 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27948', '45', '1', '18', '＜ 人 类 的 罪 恶 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27949', '45', '1', '19', '神 的 事 情 ， 人 所 能 知 道 的 ， 原 显 明 在 人 心 里 ， 因 为 神 已 经 给 他 们 显 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27950', '45', '1', '20', '自 从 造 天 地 以 来 ， 神 的 永 能 和 神 性 是 明 明 可 知 的 ， 虽 是 眼 不 能 见 ， 但 藉 着 所 造 之 物 就 可 以 晓 得 ， 叫 人 无 可 推 诿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27951', '45', '1', '21', '因 为 ， 他 们 虽 然 知 道 神 ， 却 不 当 作 神 荣 耀 他 ， 也 不 感 谢 他 。 他 们 的 思 念 变 为 虚 妄 ， 无 知 的 心 就 昏 暗 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27952', '45', '1', '22', '自 称 为 聪 明 ， 反 成 了 愚 拙 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27953', '45', '1', '23', '将 不 能 朽 坏 之 神 的 荣 耀 变 为 偶 像 ， 仿 佛 必 朽 坏 的 人 和 飞 禽 、 走 兽 、 昆 虫 的 样 式 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27954', '45', '1', '24', '所 以 ， 神 任 凭 他 们 逞 着 心 里 的 情 欲 行 污 秽 的 事 ， 以 致 彼 此 玷 辱 自 己 的 身 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27955', '45', '1', '25', '他 们 将 神 的 真 实 变 为 虚 谎 ， 去 敬 拜 事 奉 受 造 之 物 ， 不 敬 奉 那 造 物 的 主 ─ ─ 主 乃 是 可 称 颂 的 ， 直 到 永 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27956', '45', '1', '26', '因 此 ， 神 任 凭 他 们 放 纵 可 羞 耻 的 情 欲 。 他 们 的 女 人 把 顺 性 的 用 处 变 为 逆 性 的 用 处 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27957', '45', '1', '27', '男 人 也 是 如 此 ， 弃 了 女 人 顺 性 的 用 处 ， 欲 火 攻 心 ， 彼 此 贪 恋 ， 男 和 男 行 可 羞 耻 的 事 ， 就 在 自 己 身 上 受 这 妄 为 当 得 的 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27958', '45', '1', '28', '他 们 既 然 故 意 不 认 识 神 ， 神 就 任 凭 他 们 存 邪 僻 的 心 ， 行 那 些 不 合 理 的 事 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27959', '45', '1', '29', '装 满 了 各 样 不 义 、 邪 恶 、 贪 婪 、 恶 毒 ｛ 或 译 ： 阴 毒 ｝ ； 满 心 是 嫉 妒 、 凶 杀 、 争 竞 、 诡 诈 、 毒 恨 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27960', '45', '1', '30', '又 是 谗 毁 的 、 背 后 说 人 的 、 怨 恨 神 的 ｛ 或 译 ： 被 神 所 憎 恶 的 ｝ 、 侮 慢 人 的 、 狂 傲 的 、 自 夸 的 、 捏 造 恶 事 的 、 违 背 父 母 的 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27961', '45', '1', '31', '无 知 的 、 背 约 的 、 无 亲 情 的 、 不 怜 悯 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27962', '45', '1', '32', '他 们 虽 知 道 神 判 定 行 这 样 事 的 人 是 当 死 的 ， 然 而 他 们 不 但 自 己 去 行 ， 还 喜 欢 别 人 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27963', '45', '2', '1', '＜ 神 的 公 义 判 断 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27964', '45', '2', '2', '我 们 知 道 这 样 行 的 人 ， 神 必 照 真 理 审 判 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27965', '45', '2', '3', '你 这 人 哪 ， 你 论 断 行 这 样 事 的 人 ， 自 己 所 行 的 却 和 别 人 一 样 ， 你 以 为 能 逃 脱 神 的 审 判 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27966', '45', '2', '4', '还 是 你 藐 视 他 丰 富 的 恩 慈 、 宽 容 、 忍 耐 ， 不 晓 得 他 的 恩 慈 是 领 你 悔 改 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27967', '45', '2', '5', '你 竟 任 着 你 刚 硬 不 悔 改 的 心 ， 为 自 己 积 蓄 忿 怒 ， 以 致 神 震 怒 ， 显 他 公 义 审 判 的 日 子 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27968', '45', '2', '6', '他 必 照 各 人 的 行 为 报 应 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27969', '45', '2', '7', '凡 恒 心 行 善 、 寻 求 荣 耀 、 尊 贵 和 不 能 朽 坏 之 福 的 ， 就 以 永 生 报 应 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27970', '45', '2', '8', '惟 有 结 党 、 不 顺 从 真 理 、 反 顺 从 不 义 的 ， 就 以 忿 怒 、 恼 恨 报 应 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27971', '45', '2', '9', '将 患 难 、 困 苦 加 给 一 切 作 恶 的 人 ， 先 是 犹 太 人 ， 后 是 希 腊 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27972', '45', '2', '10', '却 将 荣 耀 、 尊 贵 、 平 安 加 给 一 切 行 善 的 人 ， 先 是 犹 太 人 ， 后 是 希 腊 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27973', '45', '2', '11', '因 为 神 不 偏 待 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27974', '45', '2', '12', '凡 没 有 律 法 犯 了 罪 的 ， 也 必 不 按 律 法 灭 亡 ； 凡 在 律 法 以 下 犯 了 罪 的 ， 也 必 按 律 法 受 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27975', '45', '2', '13', '（ 原 来 在 神 面 前 ， 不 是 听 律 法 的 为 义 ， 乃 是 行 律 法 的 称 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27976', '45', '2', '14', '没 有 律 法 的 外 邦 人 若 顺 着 本 性 行 律 法 上 的 事 ， 他 们 虽 然 没 有 律 法 ， 自 己 就 是 自 己 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27977', '45', '2', '15', '这 是 显 出 律 法 的 功 用 刻 在 他 们 心 里 ， 他 们 是 非 之 心 同 作 见 证 ， 并 且 他 们 的 思 念 互 相 较 量 ， 或 以 为 是 ， 或 以 为 非 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27978', '45', '2', '16', '就 在 神 藉 耶 稣 基 督 审 判 人 隐 秘 事 的 日 子 ， 照 着 我 的 福 音 所 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27979', '45', '2', '17', '＜ 犹 太 人 与 律 法 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27980', '45', '2', '18', '既 从 律 法 中 受 了 教 训 ， 就 晓 得 神 的 旨 意 ， 也 能 分 别 是 非 ｛ 或 译 ： 也 喜 爱 那 美 好 的 事 ｝ ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27981', '45', '2', '19', '又 深 信 自 己 是 给 瞎 子 领 路 的 ， 是 黑 暗 中 人 的 光 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27982', '45', '2', '20', '是 蠢 笨 人 的 师 傅 ， 是 小 孩 子 的 先 生 ， 在 律 法 上 有 知 识 和 真 理 的 模 范 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27983', '45', '2', '21', '你 既 是 教 导 别 人 ， 还 不 教 导 自 己 吗 ？ 你 讲 说 人 不 可 偷 窃 ， 自 己 还 偷 窃 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27984', '45', '2', '22', '你 说 人 不 可 奸 淫 ， 自 己 还 奸 淫 吗 ？ 你 厌 恶 偶 像 ， 自 己 还 偷 窃 庙 中 之 物 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27985', '45', '2', '23', '你 指 着 律 法 夸 口 ， 自 己 倒 犯 律 法 、 玷 辱 神 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27986', '45', '2', '24', '神 的 名 在 外 邦 人 中 ， 因 你 们 受 了 亵 渎 ， 正 如 经 上 所 记 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27987', '45', '2', '25', '你 若 是 行 律 法 的 ， 割 礼 固 然 于 你 有 益 ； 若 是 犯 律 法 的 ， 你 的 割 礼 就 算 不 得 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27988', '45', '2', '26', '所 以 那 未 受 割 礼 的 ， 若 遵 守 律 法 的 条 例 ， 他 虽 然 未 受 割 礼 ， 岂 不 算 是 有 割 礼 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27989', '45', '2', '27', '而 且 那 本 来 未 受 割 礼 的 ， 若 能 全 守 律 法 ， 岂 不 是 要 审 判 你 这 有 仪 文 和 割 礼 竟 犯 律 法 的 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27990', '45', '2', '28', '因 为 外 面 作 犹 太 人 的 ， 不 是 真 犹 太 人 ； 外 面 肉 身 的 割 礼 ， 也 不 是 真 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27991', '45', '2', '29', '惟 有 里 面 作 的 ， 才 是 真 犹 太 人 ； 真 割 礼 也 是 心 里 的 ， 在 乎 灵 ， 不 在 乎 仪 文 。 这 人 的 称 赞 不 是 从 人 来 的 ， 乃 是 从 神 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27992', '45', '3', '1', '这 样 说 来 ， 犹 太 人 有 什 么 长 处 ？ 割 礼 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27993', '45', '3', '2', '凡 事 大 有 好 处 ： 第 一 是 神 的 圣 言 交 托 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27994', '45', '3', '3', '即 便 有 不 信 的 ， 这 有 何 妨 呢 ？ 难 道 他 们 的 不 信 就 废 掉 神 的 信 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27995', '45', '3', '4', '断 乎 不 能 ！ 不 如 说 ， 神 是 真 实 的 ， 人 都 是 虚 谎 的 。 如 经 上 所 记 ： 你 责 备 人 的 时 候 ， 显 为 公 义 ； 被 人 议 论 的 时 候 ， 可 以 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27996', '45', '3', '5', '我 且 照 着 人 的 常 话 说 ， 我 们 的 不 义 若 显 出 神 的 义 来 ， 我 们 可 以 怎 么 说 呢 ？ 神 降 怒 ， 是 他 不 义 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27997', '45', '3', '6', '断 乎 不 是 ！ 若 是 这 样 ， 神 怎 能 审 判 世 界 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27998', '45', '3', '7', '若 神 的 真 实 ， 因 我 的 虚 谎 越 发 显 出 他 的 荣 耀 ， 为 什 么 我 还 受 审 判 ， 好 像 罪 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('27999', '45', '3', '8', '为 什 么 不 说 ， 我 们 可 以 作 恶 以 成 善 呢 ？ 这 是 毁 谤 我 们 的 人 说 我 们 有 这 话 。 这 等 人 定 罪 是 该 当 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28000', '45', '3', '9', '＜ 没 有 义 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28001', '45', '3', '10', '就 如 经 上 所 记 ： 没 有 义 人 ， 连 一 个 也 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28002', '45', '3', '11', '没 有 明 白 的 ； 没 有 寻 求 神 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28003', '45', '3', '12', '都 是 偏 离 正 路 ， 一 同 变 为 无 用 。 没 有 行 善 的 ， 连 一 个 也 没 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28004', '45', '3', '13', '他 们 的 喉 咙 是 敞 开 的 坟 墓 ； 他 们 用 舌 头 弄 诡 诈 ， 嘴 唇 里 有 虺 蛇 的 毒 气 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28005', '45', '3', '14', '满 口 是 咒 骂 苦 毒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28006', '45', '3', '15', '杀 人 流 血 ， 他 们 的 脚 飞 跑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28007', '45', '3', '16', '所 经 过 的 路 便 行 残 害 暴 虐 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28008', '45', '3', '17', '平 安 的 路 ， 他 们 未 曾 知 道 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28009', '45', '3', '18', '他 们 眼 中 不 怕 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28010', '45', '3', '19', '我 们 晓 得 律 法 上 的 话 都 是 对 律 法 以 下 之 人 说 的 ， 好 塞 住 各 人 的 口 ， 叫 普 世 的 人 都 伏 在 神 审 判 之 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28011', '45', '3', '20', '所 以 凡 有 血 气 的 ， 没 有 一 个 因 行 律 法 能 在 神 面 前 称 义 ， 因 为 律 法 本 是 叫 人 知 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28012', '45', '3', '21', '＜ 因 信 称 义 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28013', '45', '3', '22', '就 是 神 的 义 ， 因 信 耶 稣 基 督 加 给 一 切 相 信 的 人 ， 并 没 有 分 别 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28014', '45', '3', '23', '因 为 世 人 都 犯 了 罪 ， 亏 缺 了 神 的 荣 耀 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28015', '45', '3', '24', '如 今 却 蒙 神 的 恩 典 ， 因 基 督 耶 稣 的 救 赎 ， 就 白 白 地 称 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28016', '45', '3', '25', '神 设 立 耶 稣 作 挽 回 祭 ， 是 凭 着 耶 稣 的 血 ， 藉 着 人 的 信 ， 要 显 明 神 的 义 ； 因 为 他 用 忍 耐 的 心 宽 容 人 先 时 所 犯 的 罪 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28017', '45', '3', '26', '好 在 今 时 显 明 他 的 义 ， 使 人 知 道 他 自 己 为 义 ， 也 称 信 耶 稣 的 人 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28018', '45', '3', '27', '既 是 这 样 ， 哪 里 能 夸 口 呢 ？ 没 有 可 夸 的 了 。 用 何 法 没 有 的 呢 ？ 是 用 立 功 之 法 吗 ？ 不 是 ， 乃 用 信 主 之 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28019', '45', '3', '28', '所 以 ｛ 有 古 卷 ： 因 为 ｝ 我 们 看 定 了 ： 人 称 义 是 因 着 信 ， 不 在 乎 遵 行 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28020', '45', '3', '29', '难 道 神 只 作 犹 太 人 的 神 吗 ？ 不 也 是 作 外 邦 人 的 神 吗 ？ 是 的 ， 也 作 外 邦 人 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28021', '45', '3', '30', '神 既 是 一 位 ， 他 就 要 因 信 称 那 受 割 礼 的 为 义 ， 也 要 因 信 称 那 未 受 割 礼 的 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28022', '45', '3', '31', '这 样 ， 我 们 因 信 废 了 律 法 吗 ？ 断 乎 不 是 ！ 更 是 坚 固 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28023', '45', '4', '1', '＜ 以 亚 伯 拉 罕 为 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28024', '45', '4', '2', '倘 若 亚 伯 拉 罕 是 因 行 为 称 义 ， 就 有 可 夸 的 ； 只 是 在 神 面 前 并 无 可 夸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28025', '45', '4', '3', '经 上 说 什 么 呢 ？ 说 ： “ 亚 伯 拉 罕 信 神 ， 这 就 算 为 他 的 义 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28026', '45', '4', '4', '做 工 的 得 工 价 ， 不 算 恩 典 ， 乃 是 该 得 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28027', '45', '4', '5', '惟 有 不 做 工 的 ， 只 信 称 罪 人 为 义 的 神 ， 他 的 信 就 算 为 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28028', '45', '4', '6', '正 如 大 卫 称 那 在 行 为 以 外 蒙 神 算 为 义 的 人 是 有 福 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28029', '45', '4', '7', '他 说 ： 得 赦 免 其 过 、 遮 盖 其 罪 的 ， 这 人 是 有 福 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28030', '45', '4', '8', '主 不 算 为 有 罪 的 ， 这 人 是 有 福 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28031', '45', '4', '9', '如 此 看 来 ， 这 福 是 单 加 给 那 受 割 礼 的 人 吗 ？ 不 也 是 加 给 那 未 受 割 礼 的 人 吗 ？ 因 我 们 所 说 ， 亚 伯 拉 罕 的 信 ， 就 算 为 他 的 义 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28032', '45', '4', '10', '是 怎 么 算 的 呢 ？ 是 在 他 受 割 礼 的 时 候 呢 ？ 是 在 他 未 受 割 礼 的 时 候 呢 ？ 不 是 在 受 割 礼 的 时 候 ， 乃 是 在 未 受 割 礼 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28033', '45', '4', '11', '并 且 他 受 了 割 礼 的 记 号 ， 作 他 未 受 割 礼 的 时 候 因 信 称 义 的 印 证 ， 叫 他 作 一 切 未 受 割 礼 而 信 之 人 的 父 ， 使 他 们 也 算 为 义 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28034', '45', '4', '12', '又 作 受 割 礼 之 人 的 父 ， 就 是 那 些 不 但 受 割 礼 ， 并 且 按 我 们 的 祖 宗 亚 伯 拉 罕 未 受 割 礼 而 信 之 踪 迹 去 行 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28035', '45', '4', '13', '＜ 应 许 因 信 而 实 现 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28036', '45', '4', '14', '若 是 属 乎 律 法 的 人 才 得 为 后 嗣 ， 信 就 归 于 虚 空 ， 应 许 也 就 废 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28037', '45', '4', '15', '因 为 律 法 是 惹 动 忿 怒 的 ｛ 或 译 ： 叫 人 受 刑 的 ｝ ； 哪 里 没 有 律 法 ， 那 里 就 没 有 过 犯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28038', '45', '4', '16', '所 以 人 得 为 后 嗣 是 本 乎 信 ， 因 此 就 属 乎 恩 ， 叫 应 许 定 然 归 给 一 切 后 裔 ； 不 但 归 给 那 属 乎 律 法 的 ， 也 归 给 那 效 法 亚 伯 拉 罕 之 信 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28039', '45', '4', '17', '亚 伯 拉 罕 所 信 的 ， 是 那 叫 死 人 复 活 、 使 无 变 为 有 的 神 ， 他 在 主 面 前 作 我 们 世 人 的 父 。 如 经 上 所 记 ： “ 我 已 经 立 你 作 多 国 的 父 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28040', '45', '4', '18', '他 在 无 可 指 望 的 时 候 ， 因 信 仍 有 指 望 ， 就 得 以 作 多 国 的 父 ， 正 如 先 前 所 说 ： “ 你 的 后 裔 将 要 如 此 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28041', '45', '4', '19', '他 将 近 百 岁 的 时 候 ， 虽 然 想 到 自 己 的 身 体 如 同 已 死 ， 撒 拉 的 生 育 已 经 断 绝 ， 他 的 信 心 还 是 不 软 弱 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28042', '45', '4', '20', '并 且 仰 望 神 的 应 许 ， 总 没 有 因 不 信 心 里 起 疑 惑 ， 反 倒 因 信 心 里 得 坚 固 ， 将 荣 耀 归 给 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28043', '45', '4', '21', '且 满 心 相 信 神 所 应 许 的 必 能 做 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28044', '45', '4', '22', '所 以 ， 这 就 算 为 他 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28045', '45', '4', '23', '“ 算 为 他 义 ” 的 这 句 话 不 是 单 为 他 写 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28046', '45', '4', '24', '也 是 为 我 们 将 来 得 算 为 义 之 人 写 的 ， 就 是 我 们 这 信 神 使 我 们 的 主 耶 稣 从 死 里 复 活 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28047', '45', '4', '25', '耶 稣 被 交 给 人 ， 是 为 我 们 的 过 犯 ； 复 活 ， 是 为 叫 我 们 称 义 ｛ 或 译 ： 耶 稣 是 为 我 们 的 过 犯 交 付 了 ， 是 为 我 们 称 义 复 活 了 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28048', '45', '5', '1', '＜ 因 信 称 义 的 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28049', '45', '5', '2', '我 们 又 藉 着 他 ， 因 信 得 进 入 现 在 所 站 的 这 恩 典 中 ， 并 且 欢 欢 喜 喜 盼 望 神 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28050', '45', '5', '3', '不 但 如 此 ， 就 是 在 患 难 中 也 是 欢 欢 喜 喜 的 ； 因 为 知 道 患 难 生 忍 耐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28051', '45', '5', '4', '忍 耐 生 老 练 ， 老 练 生 盼 望 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28052', '45', '5', '5', '盼 望 不 至 于 羞 耻 ， 因 为 所 赐 给 我 们 的 圣 灵 将 神 的 爱 浇 灌 在 我 们 心 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28053', '45', '5', '6', '因 我 们 还 软 弱 的 时 候 ， 基 督 就 按 所 定 的 日 期 为 罪 人 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28054', '45', '5', '7', '为 义 人 死 ， 是 少 有 的 ； 为 仁 人 死 ， 或 者 有 敢 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28055', '45', '5', '8', '惟 有 基 督 在 我 们 还 作 罪 人 的 时 候 为 我 们 死 ， 神 的 爱 就 在 此 向 我 们 显 明 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28056', '45', '5', '9', '现 在 我 们 既 靠 着 他 的 血 称 义 ， 就 更 要 藉 着 他 免 去 神 的 忿 怒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28057', '45', '5', '10', '因 为 我 们 作 仇 敌 的 时 候 ， 且 藉 着 神 儿 子 的 死 ， 得 与 神 和 好 ； 既 已 和 好 ， 就 更 要 因 他 的 生 得 救 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28058', '45', '5', '11', '不 但 如 此 ， 我 们 既 藉 着 我 主 耶 稣 基 督 得 与 神 和 好 ， 也 就 藉 着 他 以 神 为 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28059', '45', '5', '12', '＜ 亚 当 和 基 督 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28060', '45', '5', '13', '没 有 律 法 之 先 ， 罪 已 经 在 世 上 ； 但 没 有 律 法 ， 罪 也 不 算 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28061', '45', '5', '14', '然 而 从 亚 当 到 摩 西 ， 死 就 作 了 王 ， 连 那 些 不 与 亚 当 犯 一 样 罪 过 的 ， 也 在 他 的 权 下 。 亚 当 乃 是 那 以 后 要 来 之 人 的 预 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28062', '45', '5', '15', '只 是 过 犯 不 如 恩 赐 ， 若 因 一 人 的 过 犯 ， 众 人 都 死 了 ， 何 况 神 的 恩 典 ， 与 那 因 耶 稣 基 督 一 人 恩 典 中 的 赏 赐 ， 岂 不 更 加 倍 地 临 到 众 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28063', '45', '5', '16', '因 一 人 犯 罪 就 定 罪 ， 也 不 如 恩 赐 ， 原 来 审 判 是 由 一 人 而 定 罪 ， 恩 赐 乃 是 由 许 多 过 犯 而 称 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28064', '45', '5', '17', '若 因 一 人 的 过 犯 ， 死 就 因 这 一 人 作 了 王 ， 何 况 那 些 受 洪 恩 又 蒙 所 赐 之 义 的 ， 岂 不 更 要 因 耶 稣 基 督 一 人 在 生 命 中 作 王 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28065', '45', '5', '18', '如 此 说 来 ， 因 一 次 的 过 犯 ， 众 人 都 被 定 罪 ； 照 样 ， 因 一 次 的 义 行 ， 众 人 也 就 被 称 义 得 生 命 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28066', '45', '5', '19', '因 一 人 的 悖 逆 ， 众 人 成 为 罪 人 ； 照 样 ， 因 一 人 的 顺 从 ， 众 人 也 成 为 义 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28067', '45', '5', '20', '律 法 本 是 外 添 的 ， 叫 过 犯 显 多 ； 只 是 罪 在 哪 里 显 多 ， 恩 典 就 更 显 多 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28068', '45', '5', '21', '就 如 罪 作 王 叫 人 死 ； 照 样 ， 恩 典 也 藉 着 义 作 王 ， 叫 人 因 我 们 的 主 耶 稣 基 督 得 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28069', '45', '6', '1', '＜ 在 罪 上 死 ， 在 基 督 里 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28070', '45', '6', '2', '断 乎 不 可 ！ 我 们 在 罪 上 死 了 的 人 岂 可 仍 在 罪 中 活 着 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28071', '45', '6', '3', '岂 不 知 我 们 这 受 洗 归 入 基 督 耶 稣 的 人 是 受 洗 归 入 他 的 死 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28072', '45', '6', '4', '所 以 ， 我 们 藉 着 洗 礼 归 入 死 ， 和 他 一 同 埋 葬 ， 原 是 叫 我 们 一 举 一 动 有 新 生 的 样 式 ， 像 基 督 藉 着 父 的 荣 耀 从 死 里 复 活 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28073', '45', '6', '5', '我 们 若 在 他 死 的 形 状 上 与 他 联 合 ， 也 要 在 他 复 活 的 形 状 上 与 他 联 合 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28074', '45', '6', '6', '因 为 知 道 我 们 的 旧 人 和 他 同 钉 十 字 架 ， 使 罪 身 灭 绝 ， 叫 我 们 不 再 作 罪 的 奴 仆 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28075', '45', '6', '7', '因 为 已 死 的 人 是 脱 离 了 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28076', '45', '6', '8', '我 们 若 是 与 基 督 同 死 ， 就 信 必 与 他 同 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28077', '45', '6', '9', '因 为 知 道 基 督 既 从 死 里 复 活 ， 就 不 再 死 ， 死 也 不 再 作 他 的 主 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28078', '45', '6', '10', '他 死 是 向 罪 死 了 ， 只 有 一 次 ； 他 活 是 向 神 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28079', '45', '6', '11', '这 样 ， 你 们 向 罪 也 当 看 自 己 是 死 的 ； 向 神 在 基 督 耶 稣 里 ， 却 当 看 自 己 是 活 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28080', '45', '6', '12', '所 以 ， 不 要 容 罪 在 你 们 必 死 的 身 上 作 王 ， 使 你 们 顺 从 身 子 的 私 欲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28081', '45', '6', '13', '也 不 要 将 你 们 的 肢 体 献 给 罪 作 不 义 的 器 具 ； 倒 要 像 从 死 里 复 活 的 人 ， 将 自 己 献 给 神 ， 并 将 肢 体 作 义 的 器 具 献 给 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28082', '45', '6', '14', '罪 必 不 能 作 你 们 的 主 ； 因 你 们 不 在 律 法 之 下 ， 乃 在 恩 典 之 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28083', '45', '6', '15', '＜ 义 的 奴 仆 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28084', '45', '6', '16', '岂 不 晓 得 你 们 献 上 自 己 作 奴 仆 ， 顺 从 谁 ， 就 作 谁 的 奴 仆 吗 ？ 或 作 罪 的 奴 仆 ， 以 至 于 死 ； 或 作 顺 命 的 奴 仆 ， 以 致 成 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28085', '45', '6', '17', '感 谢 神 ！ 因 为 你 们 从 前 虽 然 作 罪 的 奴 仆 ， 现 今 却 从 心 里 顺 服 了 所 传 给 你 们 道 理 的 模 范 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28086', '45', '6', '18', '你 们 既 从 罪 里 得 了 释 放 ， 就 作 了 义 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28087', '45', '6', '19', '我 因 你 们 肉 体 的 软 弱 ， 就 照 人 的 常 话 对 你 们 说 。 你 们 从 前 怎 样 将 肢 体 献 给 不 洁 不 法 作 奴 仆 ， 以 至 于 不 法 ； 现 今 也 要 照 样 将 肢 体 献 给 义 作 奴 仆 ， 以 至 于 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28088', '45', '6', '20', '因 为 你 们 作 罪 之 奴 仆 的 时 候 ， 就 不 被 义 约 束 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28089', '45', '6', '21', '你 们 现 今 所 看 为 羞 耻 的 事 ， 当 日 有 什 么 果 子 呢 ？ 那 些 事 的 结 局 就 是 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28090', '45', '6', '22', '但 现 今 ， 你 们 既 从 罪 里 得 了 释 放 ， 作 了 神 的 奴 仆 ， 就 有 成 圣 的 果 子 ， 那 结 局 就 是 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28091', '45', '6', '23', '因 为 罪 的 工 价 乃 是 死 ； 惟 有 神 的 恩 赐 ， 在 我 们 的 主 基 督 耶 稣 里 ， 乃 是 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28092', '45', '7', '1', '＜ 以 婚 姻 关 系 为 例 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28093', '45', '7', '2', '就 如 女 人 有 了 丈 夫 ， 丈 夫 还 活 着 ， 就 被 律 法 约 束 ； 丈 夫 若 死 了 ， 就 脱 离 了 丈 夫 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28094', '45', '7', '3', '所 以 丈 夫 活 着 ， 她 若 归 于 别 人 ， 便 叫 淫 妇 ； 丈 夫 若 死 了 ， 她 就 脱 离 了 丈 夫 的 律 法 ， 虽 然 归 于 别 人 ， 也 不 是 淫 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28095', '45', '7', '4', '我 的 弟 兄 们 ， 这 样 说 来 ， 你 们 藉 着 基 督 的 身 体 ， 在 律 法 上 也 是 死 了 ， 叫 你 们 归 于 别 人 ， 就 是 归 于 那 从 死 里 复 活 的 ， 叫 我 们 结 果 子 给 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28096', '45', '7', '5', '因 为 我 们 属 肉 体 的 时 候 ， 那 因 律 法 而 生 的 恶 欲 就 在 我 们 肢 体 中 发 动 ， 以 致 结 成 死 亡 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28097', '45', '7', '6', '但 我 们 既 然 在 捆 我 们 的 律 法 上 死 了 ， 现 今 就 脱 离 了 律 法 ， 叫 我 们 服 事 主 ， 要 按 着 心 灵 ｛ 心 灵 ： 或 译 圣 灵 ｝ 的 新 样 ， 不 按 着 仪 文 的 旧 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28098', '45', '7', '7', '＜ 内 在 的 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28099', '45', '7', '8', '然 而 ， 罪 趁 着 机 会 ， 就 藉 着 诫 命 叫 诸 般 的 贪 心 在 我 里 头 发 动 ； 因 为 没 有 律 法 ， 罪 是 死 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28100', '45', '7', '9', '我 以 前 没 有 律 法 是 活 着 的 ； 但 是 诫 命 来 到 ， 罪 又 活 了 ， 我 就 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28101', '45', '7', '10', '那 本 来 叫 人 活 的 诫 命 ， 反 倒 叫 我 死 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28102', '45', '7', '11', '因 为 罪 趁 着 机 会 ， 就 藉 着 诫 命 引 诱 我 ， 并 且 杀 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28103', '45', '7', '12', '这 样 看 来 ， 律 法 是 圣 洁 的 ， 诫 命 也 是 圣 洁 、 公 义 、 良 善 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28104', '45', '7', '13', '既 然 如 此 ， 那 良 善 的 是 叫 我 死 吗 ？ 断 乎 不 是 ！ 叫 我 死 的 乃 是 罪 。 但 罪 藉 着 那 良 善 的 叫 我 死 ， 就 显 出 真 是 罪 ， 叫 罪 因 着 诫 命 更 显 出 是 恶 极 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28105', '45', '7', '14', '我 们 原 晓 得 律 法 是 属 乎 灵 的 ， 但 我 是 属 乎 肉 体 的 ， 是 已 经 卖 给 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28106', '45', '7', '15', '因 为 我 所 做 的 ， 我 自 己 不 明 白 ； 我 所 愿 意 的 ， 我 并 不 做 ； 我 所 恨 恶 的 ， 我 倒 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28107', '45', '7', '16', '若 我 所 做 的 ， 是 我 所 不 愿 意 的 ， 我 就 应 承 律 法 是 善 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28108', '45', '7', '17', '既 是 这 样 ， 就 不 是 我 做 的 ， 乃 是 住 在 我 里 头 的 罪 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28109', '45', '7', '18', '我 也 知 道 ， 在 我 里 头 ， 就 是 我 肉 体 之 中 ， 没 有 良 善 。 因 为 ， 立 志 为 善 由 得 我 ， 只 是 行 出 来 由 不 得 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28110', '45', '7', '19', '故 此 ， 我 所 愿 意 的 善 ， 我 反 不 做 ； 我 所 不 愿 意 的 恶 ， 我 倒 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28111', '45', '7', '20', '若 我 去 做 所 不 愿 意 做 的 ， 就 不 是 我 做 的 ， 乃 是 住 在 我 里 头 的 罪 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28112', '45', '7', '21', '我 觉 得 有 个 律 ， 就 是 我 愿 意 为 善 的 时 候 ， 便 有 恶 与 我 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28113', '45', '7', '22', '因 为 按 着 我 里 面 的 意 思 ｛ 原 文 是 人 ｝ ， 我 是 喜 欢 神 的 律 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28114', '45', '7', '23', '但 我 觉 得 肢 体 中 另 有 个 律 和 我 心 中 的 律 交 战 ， 把 我 掳 去 ， 叫 我 附 从 那 肢 体 中 犯 罪 的 律 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28115', '45', '7', '24', '我 真 是 苦 啊 ！ 谁 能 救 我 脱 离 这 取 死 的 身 体 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28116', '45', '7', '25', '感 谢 神 ， 靠 着 我 们 的 主 耶 稣 基 督 就 能 脱 离 了 。 这 样 看 来 ， 我 以 内 心 顺 服 神 的 律 ， 我 肉 体 却 顺 服 罪 的 律 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28117', '45', '8', '1', '＜ 在 圣 灵 里 的 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28118', '45', '8', '2', '因 为 赐 生 命 圣 灵 的 律 ， 在 基 督 耶 稣 里 释 放 了 我 ， 使 我 脱 离 罪 和 死 的 律 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28119', '45', '8', '3', '律 法 既 因 肉 体 软 弱 ， 有 所 不 能 行 的 ， 神 就 差 遣 自 己 的 儿 子 ， 成 为 罪 身 的 形 状 ， 作 了 赎 罪 祭 ， 在 肉 体 中 定 了 罪 案 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28120', '45', '8', '4', '使 律 法 的 义 成 就 在 我 们 这 不 随 从 肉 体 、 只 随 从 圣 灵 的 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28121', '45', '8', '5', '因 为 ， 随 从 肉 体 的 人 体 贴 肉 体 的 事 ； 随 从 圣 灵 的 人 体 贴 圣 灵 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28122', '45', '8', '6', '体 贴 肉 体 的 ， 就 是 死 ； 体 贴 圣 灵 的 ， 乃 是 生 命 、 平 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28123', '45', '8', '7', '原 来 体 贴 肉 体 的 ， 就 是 与 神 为 仇 ； 因 为 不 服 神 的 律 法 ， 也 是 不 能 服 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28124', '45', '8', '8', '而 且 属 肉 体 的 人 不 能 得 神 的 喜 欢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28125', '45', '8', '9', '如 果 神 的 灵 住 在 你 们 心 里 ， 你 们 就 不 属 肉 体 ， 乃 属 圣 灵 了 。 人 若 没 有 基 督 的 灵 ， 就 不 是 属 基 督 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28126', '45', '8', '10', '基 督 若 在 你 们 心 里 ， 身 体 就 因 罪 而 死 ， 心 灵 却 因 义 而 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28127', '45', '8', '11', '然 而 ， 叫 耶 稣 从 死 里 复 活 者 的 灵 若 住 在 你 们 心 里 ， 那 叫 基 督 耶 稣 从 死 里 复 活 的 ， 也 必 藉 着 住 在 你 们 心 里 的 圣 灵 ， 使 你 们 必 死 的 身 体 又 活 过 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28128', '45', '8', '12', '弟 兄 们 ， 这 样 看 来 ， 我 们 并 不 是 欠 肉 体 的 债 去 顺 从 肉 体 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28129', '45', '8', '13', '你 们 若 顺 从 肉 体 活 着 ， 必 要 死 ； 若 靠 着 圣 灵 治 死 身 体 的 恶 行 ， 必 要 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28130', '45', '8', '14', '因 为 凡 被 神 的 灵 引 导 的 ， 都 是 神 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28131', '45', '8', '15', '你 们 所 受 的 ， 不 是 奴 仆 的 心 ， 仍 旧 害 怕 ； 所 受 的 ， 乃 是 儿 子 的 心 ， 因 此 我 们 呼 叫 ： “ 阿 爸 ！ 父 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28132', '45', '8', '16', '圣 灵 与 我 们 的 心 同 证 我 们 是 神 的 儿 女 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28133', '45', '8', '17', '既 是 儿 女 ， 便 是 后 嗣 ， 就 是 神 的 后 嗣 ， 和 基 督 同 作 后 嗣 。 如 果 我 们 和 他 一 同 受 苦 ， 也 必 和 他 一 同 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28134', '45', '8', '18', '＜ 将 来 的 荣 耀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28135', '45', '8', '19', '受 造 之 物 切 望 等 候 神 的 众 子 显 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28136', '45', '8', '20', '因 为 受 造 之 物 服 在 虚 空 之 下 ， 不 是 自 己 愿 意 ， 乃 是 因 那 叫 他 如 此 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28137', '45', '8', '21', '但 受 造 之 物 仍 然 指 望 脱 离 败 坏 的 辖 制 ， 得 享 ｛ 享 ： 原 文 是 入 ｝ 神 儿 女 自 由 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28138', '45', '8', '22', '我 们 知 道 ， 一 切 受 造 之 物 一 同 叹 息 ， 劳 苦 ， 直 到 如 今 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28139', '45', '8', '23', '不 但 如 此 ， 就 是 我 们 这 有 圣 灵 初 结 果 子 的 ， 也 是 自 己 心 里 叹 息 ， 等 候 得 着 儿 子 的 名 分 ， 乃 是 我 们 的 身 体 得 赎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28140', '45', '8', '24', '我 们 得 救 是 在 乎 盼 望 ； 只 是 所 见 的 盼 望 不 是 盼 望 ， 谁 还 盼 望 他 所 见 的 呢 ｛ 有 古 卷 ： 人 所 看 见 的 何 必 再 盼 望 呢 ｝ ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28141', '45', '8', '25', '但 我 们 若 盼 望 那 所 不 见 的 ， 就 必 忍 耐 等 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28142', '45', '8', '26', '况 且 ， 我 们 的 软 弱 有 圣 灵 帮 助 ； 我 们 本 不 晓 得 当 怎 样 祷 告 ， 只 是 圣 灵 亲 自 用 说 不 出 来 的 叹 息 替 我 们 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28143', '45', '8', '27', '鉴 察 人 心 的 ， 晓 得 圣 灵 的 意 思 ， 因 为 圣 灵 照 着 神 的 旨 意 替 圣 徒 祈 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28144', '45', '8', '28', '我 们 晓 得 万 事 都 互 相 效 力 ， 叫 爱 神 的 人 得 益 处 ， 就 是 按 他 旨 意 被 召 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28145', '45', '8', '29', '因 为 他 预 先 所 知 道 的 人 ， 就 预 先 定 下 效 法 他 儿 子 的 模 样 ， 使 他 儿 子 在 许 多 弟 兄 中 作 长 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28146', '45', '8', '30', '预 先 所 定 下 的 人 又 召 他 们 来 ； 所 召 来 的 人 又 称 他 们 为 义 ； 所 称 为 义 的 人 又 叫 他 们 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28147', '45', '8', '31', '＜ 神 的 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28148', '45', '8', '32', '神 既 不 爱 惜 自 己 的 儿 子 ， 为 我 们 众 人 舍 了 ， 岂 不 也 把 万 物 和 他 一 同 白 白 地 赐 给 我 们 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28149', '45', '8', '33', '谁 能 控 告 神 所 拣 选 的 人 呢 ？ 有 神 称 他 们 为 义 了 ｛ 或 译 ： 是 称 他 们 为 义 的 神 吗 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28150', '45', '8', '34', '谁 能 定 他 们 的 罪 呢 ？ 有 基 督 耶 稣 已 经 死 了 ， 而 且 从 死 里 复 活 ， 现 今 在 神 的 右 边 ， 也 替 我 们 祈 求 ｛ 有 基 督 … … 或 译 ： 是 已 经 死 了 ， 而 且 从 死 里 复 活 ， 现 今 在 神 的 右 边 ， 也 替 我 们 祈 求 的 基 督 耶 稣 吗 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28151', '45', '8', '35', '谁 能 使 我 们 与 基 督 的 爱 隔 绝 呢 ？ 难 道 是 患 难 吗 ？ 是 困 苦 吗 ？ 是 逼 迫 吗 ？ 是 饥 饿 吗 ？ 是 赤 身 露 体 吗 ？ 是 危 险 吗 ？ 是 刀 剑 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28152', '45', '8', '36', '如 经 上 所 记 ： 我 们 为 你 的 缘 故 终 日 被 杀 ； 人 看 我 们 如 将 宰 的 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28153', '45', '8', '37', '然 而 ， 靠 着 爱 我 们 的 主 ， 在 这 一 切 的 事 上 已 经 得 胜 有 余 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28154', '45', '8', '38', '因 为 我 深 信 无 论 是 死 ， 是 生 ， 是 天 使 ， 是 掌 权 的 ， 是 有 能 的 ， 是 现 在 的 事 ， 是 将 来 的 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28155', '45', '8', '39', '是 高 处 的 ， 是 低 处 的 ， 是 别 的 受 造 之 物 ， 都 不 能 叫 我 们 与 神 的 爱 隔 绝 ； 这 爱 是 在 我 们 的 主 基 督 耶 稣 里 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28156', '45', '9', '1', '＜ 神 拣 选 以 色 列 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28157', '45', '9', '2', '我 是 大 有 忧 愁 ， 心 里 时 常 伤 痛 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28158', '45', '9', '3', '为 我 弟 兄 ， 我 骨 肉 之 亲 ， 就 是 自 己 被 咒 诅 ， 与 基 督 分 离 ， 我 也 愿 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28159', '45', '9', '4', '他 们 是 以 色 列 人 ； 那 儿 子 的 名 分 、 荣 耀 、 诸 约 、 律 法 、 礼 仪 、 应 许 都 是 他 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28160', '45', '9', '5', '列 祖 就 是 他 们 的 祖 宗 ； 按 肉 体 说 ， 基 督 也 是 从 他 们 出 来 的 。 他 是 在 万 有 之 上 ， 永 远 可 称 颂 的 神 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28161', '45', '9', '6', '这 不 是 说 神 的 话 落 了 空 。 因 为 从 以 色 列 生 的 不 都 是 以 色 列 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28162', '45', '9', '7', '也 不 因 为 是 亚 伯 拉 罕 的 后 裔 就 都 作 他 的 儿 女 ； 惟 独 “ 从 以 撒 生 的 才 要 称 为 你 的 后 裔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28163', '45', '9', '8', '这 就 是 说 ， 肉 身 所 生 的 儿 女 不 是 神 的 儿 女 ， 惟 独 那 应 许 的 儿 女 才 算 是 后 裔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28164', '45', '9', '9', '因 为 所 应 许 的 话 是 这 样 说 ： “ 到 明 年 这 时 候 我 要 来 ， 撒 拉 必 生 一 个 儿 子 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28165', '45', '9', '10', '不 但 如 此 ， 还 有 利 百 加 ， 既 从 一 个 人 ， 就 是 从 我 们 的 祖 宗 以 撒 怀 了 孕 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28166', '45', '9', '11', '（ 双 子 还 没 有 生 下 来 ， 善 恶 还 没 有 做 出 来 ， 只 因 要 显 明 神 拣 选 人 的 旨 意 ， 不 在 乎 人 的 行 为 ， 乃 在 乎 召 人 的 主 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28167', '45', '9', '12', '神 就 对 利 百 加 说 ： “ 将 来 ， 大 的 要 服 事 小 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28168', '45', '9', '13', '正 如 经 上 所 记 ： 雅 各 是 我 所 爱 的 ； 以 扫 是 我 所 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28169', '45', '9', '14', '这 样 ， 我 们 可 说 什 么 呢 ？ 难 道 神 有 什 么 不 公 平 吗 ？ 断 乎 没 有 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28170', '45', '9', '15', '因 他 对 摩 西 说 ： 我 要 怜 悯 谁 就 怜 悯 谁 ， 要 恩 待 谁 就 恩 待 谁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28171', '45', '9', '16', '据 此 看 来 ， 这 不 在 乎 那 定 意 的 ， 也 不 在 乎 那 奔 跑 的 ， 只 在 乎 发 怜 悯 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28172', '45', '9', '17', '因 为 经 上 有 话 向 法 老 说 ： “ 我 将 你 兴 起 来 ， 特 要 在 你 身 上 彰 显 我 的 权 能 ， 并 要 使 我 的 名 传 遍 天 下 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28173', '45', '9', '18', '如 此 看 来 ， 神 要 怜 悯 谁 就 怜 悯 谁 ， 要 叫 谁 刚 硬 就 叫 谁 刚 硬 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28174', '45', '9', '19', '＜ 神 的 忿 怒 和 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28175', '45', '9', '20', '你 这 个 人 哪 ， 你 是 谁 ， 竟 敢 向 神 强 嘴 呢 ？ 受 造 之 物 岂 能 对 造 他 的 说 ： “ 你 为 什 么 这 样 造 我 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28176', '45', '9', '21', '窑 匠 难 道 没 有 权 柄 从 一 团 泥 里 拿 一 块 做 成 贵 重 的 器 皿 ， 又 拿 一 块 做 成 卑 贱 的 器 皿 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28177', '45', '9', '22', '倘 若 神 要 显 明 他 的 忿 怒 ， 彰 显 他 的 权 能 ， 就 多 多 忍 耐 宽 容 那 可 怒 、 预 备 遭 毁 灭 的 器 皿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28178', '45', '9', '23', '又 要 将 他 丰 盛 的 荣 耀 彰 显 在 那 蒙 怜 悯 、 早 预 备 得 荣 耀 的 器 皿 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28179', '45', '9', '24', '这 器 皿 就 是 我 们 被 神 所 召 的 ， 不 但 是 从 犹 太 人 中 ， 也 是 从 外 邦 人 中 。 这 有 什 么 不 可 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28180', '45', '9', '25', '就 像 神 在 何 西 阿 书 上 说 ： 那 本 来 不 是 我 子 民 的 ， 我 要 称 为 “ 我 的 子 民 ” ； 本 来 不 是 蒙 爱 的 ， 我 要 称 为 “ 蒙 爱 的 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28181', '45', '9', '26', '从 前 在 什 么 地 方 对 他 们 说 ： 你 们 不 是 我 的 子 民 ， 将 来 就 在 那 里 称 他 们 为 “ 永 生 神 的 儿 子 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28182', '45', '9', '27', '以 赛 亚 指 着 以 色 列 人 喊 着 说 ： “ 以 色 列 人 虽 多 如 海 沙 ， 得 救 的 不 过 是 剩 下 的 余 数 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28183', '45', '9', '28', '因 为 主 要 在 世 上 施 行 他 的 话 ， 叫 他 的 话 都 成 全 ， 速 速 地 完 结 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28184', '45', '9', '29', '又 如 以 赛 亚 先 前 说 过 ： 若 不 是 万 军 之 主 给 我 们 存 留 余 种 ， 我 们 早 已 像 所 多 玛 、 蛾 摩 拉 的 样 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28185', '45', '9', '30', '＜ 以 色 列 人 和 福 音 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28186', '45', '9', '31', '但 以 色 列 人 追 求 律 法 的 义 ， 反 得 不 着 律 法 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28187', '45', '9', '32', '这 是 什 么 缘 故 呢 ？ 是 因 为 他 们 不 凭 着 信 心 求 ， 只 凭 着 行 为 求 ； 他 们 正 跌 在 那 绊 脚 石 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28188', '45', '9', '33', '就 如 经 上 所 记 ： 我 在 锡 安 放 一 块 绊 脚 的 石 头 ， 跌 人 的 磐 石 ； 信 靠 他 的 人 必 不 至 于 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28189', '45', '10', '1', '弟 兄 们 ， 我 心 里 所 愿 的 ， 向 神 所 求 的 ， 是 要 以 色 列 人 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28190', '45', '10', '2', '我 可 以 证 明 ， 他 们 向 神 有 热 心 ， 但 不 是 按 着 真 知 识 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28191', '45', '10', '3', '因 为 不 知 道 神 的 义 ， 想 要 立 自 己 的 义 ， 就 不 服 神 的 义 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28192', '45', '10', '4', '律 法 的 总 结 就 是 基 督 ， 使 凡 信 他 的 都 得 着 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28193', '45', '10', '5', '＜ 求 告 主 名 的 必 要 得 救 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28194', '45', '10', '6', '惟 有 出 于 信 心 的 义 如 此 说 ： “ 你 不 要 心 里 说 ： 谁 要 升 到 天 上 去 呢 ？ （ 就 是 要 领 下 基 督 来 ； ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28195', '45', '10', '7', '谁 要 下 到 阴 间 去 呢 ？ （ 就 是 要 领 基 督 从 死 里 上 来 。 ） ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28196', '45', '10', '8', '他 到 底 怎 么 说 呢 ？ 他 说 ： 这 道 离 你 不 远 ， 正 在 你 口 里 ， 在 你 心 里 ─ ─ （ 就 是 我 们 所 传 信 主 的 道 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28197', '45', '10', '9', '你 若 口 里 认 耶 稣 为 主 ， 心 里 信 神 叫 他 从 死 里 复 活 ， 就 必 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28198', '45', '10', '10', '因 为 ， 人 心 里 相 信 就 可 以 称 义 ， 口 里 承 认 就 可 以 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28199', '45', '10', '11', '经 上 说 ： “ 凡 信 他 的 人 必 不 至 于 羞 愧 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28200', '45', '10', '12', '犹 太 人 和 希 腊 人 并 没 有 分 别 ， 因 为 众 人 同 有 一 位 主 ； 他 也 厚 待 一 切 求 告 他 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28201', '45', '10', '13', '因 为 “ 凡 求 告 主 名 的 就 必 得 救 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28202', '45', '10', '14', '然 而 ， 人 未 曾 信 他 ， 怎 能 求 他 呢 ？ 未 曾 听 见 他 ， 怎 能 信 他 呢 ？ 没 有 传 道 的 ， 怎 能 听 见 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28203', '45', '10', '15', '若 没 有 奉 差 遣 ， 怎 能 传 道 呢 ？ 如 经 上 所 记 ： “ 报 福 音 、 传 喜 信 的 人 ， 他 们 的 脚 踪 何 等 佳 美 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28204', '45', '10', '16', '只 是 人 没 有 都 听 从 福 音 ， 因 为 以 赛 亚 说 ： “ 主 啊 ， 我 们 所 传 的 有 谁 信 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28205', '45', '10', '17', '可 见 ， 信 道 是 从 听 道 来 的 ， 听 道 是 从 基 督 的 话 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28206', '45', '10', '18', '但 我 说 ， 人 没 有 听 见 吗 ？ 诚 然 听 见 了 。 他 们 的 声 音 传 遍 天 下 ； 他 们 的 言 语 传 到 地 极 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28207', '45', '10', '19', '我 再 说 ， 以 色 列 人 不 知 道 吗 ？ 先 有 摩 西 说 ： 我 要 用 那 不 成 子 民 的 惹 动 你 们 的 愤 恨 ； 我 要 用 那 无 知 的 民 触 动 你 们 的 怒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28208', '45', '10', '20', '又 有 以 赛 亚 放 胆 说 ： 没 有 寻 找 我 的 ， 我 叫 他 们 遇 见 ； 没 有 访 问 我 的 ， 我 向 他 们 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28209', '45', '10', '21', '至 于 以 色 列 人 ， 他 说 ： “ 我 整 天 伸 手 招 呼 那 悖 逆 顶 嘴 的 百 姓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28210', '45', '11', '1', '＜ 以 色 列 的 余 民 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28211', '45', '11', '2', '神 并 没 有 弃 绝 他 预 先 所 知 道 的 百 姓 。 你 们 岂 不 晓 得 经 上 论 到 以 利 亚 是 怎 么 说 的 呢 ？ 他 在 神 面 前 怎 样 控 告 以 色 列 人 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28212', '45', '11', '3', '“ 主 啊 ， 他 们 杀 了 你 的 先 知 ， 拆 了 你 的 祭 坛 ， 只 剩 下 我 一 个 人 ； 他 们 还 要 寻 索 我 的 命 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28213', '45', '11', '4', '神 的 回 话 是 怎 么 说 的 呢 ？ 他 说 ： “ 我 为 自 己 留 下 七 千 人 ， 是 未 曾 向 巴 力 屈 膝 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28214', '45', '11', '5', '如 今 也 是 这 样 ， 照 着 拣 选 的 恩 典 ， 还 有 所 留 的 余 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28215', '45', '11', '6', '既 是 出 于 恩 典 ， 就 不 在 乎 行 为 ； 不 然 ， 恩 典 就 不 是 恩 典 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28216', '45', '11', '7', '这 是 怎 么 样 呢 ？ 以 色 列 人 所 求 的 ， 他 们 没 有 得 着 。 惟 有 蒙 拣 选 的 人 得 着 了 ； 其 余 的 就 成 了 顽 梗 不 化 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28217', '45', '11', '8', '如 经 上 所 记 ： 神 给 他 们 昏 迷 的 心 ， 眼 睛 不 能 看 见 ， 耳 朵 不 能 听 见 ， 直 到 今 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28218', '45', '11', '9', '大 卫 也 说 ： 愿 他 们 的 筵 席 变 为 网 罗 ， 变 为 机 槛 ， 变 为 绊 脚 石 ， 作 他 们 的 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28219', '45', '11', '10', '愿 他 们 的 眼 睛 昏 蒙 ， 不 得 看 见 ； 愿 你 时 常 弯 下 他 们 的 腰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28220', '45', '11', '11', '＜ 外 邦 人 得 救 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28221', '45', '11', '12', '若 他 们 的 过 失 为 天 下 的 富 足 ， 他 们 的 缺 乏 为 外 邦 人 的 富 足 ， 何 况 他 们 的 丰 满 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28222', '45', '11', '13', '我 对 你 们 外 邦 人 说 这 话 ； 因 我 是 外 邦 人 的 使 徒 ， 所 以 敬 重 ｛ 原 文 是 荣 耀 ｝ 我 的 职 分 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28223', '45', '11', '14', '或 者 可 以 激 动 我 骨 肉 之 亲 发 愤 ， 好 救 他 们 一 些 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28224', '45', '11', '15', '若 他 们 被 丢 弃 ， 天 下 就 得 与 神 和 好 ， 他 们 被 收 纳 ， 岂 不 是 死 而 复 生 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28225', '45', '11', '16', '所 献 的 新 面 若 是 圣 洁 ， 全 团 也 就 圣 洁 了 ； 树 根 若 是 圣 洁 ， 树 枝 也 就 圣 洁 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28226', '45', '11', '17', '若 有 几 根 枝 子 被 折 下 来 ， 你 这 野 橄 榄 得 接 在 其 中 ， 一 同 得 着 橄 榄 根 的 肥 汁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28227', '45', '11', '18', '你 就 不 可 向 旧 枝 子 夸 口 ； 若 是 夸 口 ， 当 知 道 不 是 你 托 着 根 ， 乃 是 根 托 着 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28228', '45', '11', '19', '你 若 说 ， 那 枝 子 被 折 下 来 是 特 为 叫 我 接 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28229', '45', '11', '20', '不 错 ！ 他 们 因 为 不 信 ， 所 以 被 折 下 来 ； 你 因 为 信 ， 所 以 立 得 住 ； 你 不 可 自 高 ， 反 要 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28230', '45', '11', '21', '神 既 不 爱 惜 原 来 的 枝 子 ， 也 必 不 爱 惜 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28231', '45', '11', '22', '可 见 ， 神 的 恩 慈 和 严 厉 向 那 跌 倒 的 人 是 严 厉 的 ， 向 你 是 有 恩 慈 的 ， 只 要 你 长 久 在 他 的 恩 慈 里 ； 不 然 ， 你 也 要 被 砍 下 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28232', '45', '11', '23', '而 且 他 们 若 不 是 长 久 不 信 ， 仍 要 被 接 上 ， 因 为 神 能 够 把 他 们 重 新 接 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28233', '45', '11', '24', '你 是 从 那 天 生 的 野 橄 榄 上 砍 下 来 的 ， 尚 且 逆 着 性 得 接 在 好 橄 榄 上 ， 何 况 这 本 树 的 枝 子 ， 要 接 在 本 树 上 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28234', '45', '11', '25', '＜ 以 色 列 人 的 复 兴 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28235', '45', '11', '26', '于 是 以 色 列 全 家 都 要 得 救 。 如 经 上 所 记 ： 必 有 一 位 救 主 从 锡 安 出 来 ， 要 消 除 雅 各 家 的 一 切 罪 恶 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28236', '45', '11', '27', '又 说 ： 我 除 去 他 们 罪 的 时 候 ， 这 就 是 我 与 他 们 所 立 的 约 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28237', '45', '11', '28', '就 着 福 音 说 ， 他 们 为 你 们 的 缘 故 是 仇 敌 ； 就 着 拣 选 说 ， 他 们 为 列 祖 的 缘 故 是 蒙 爱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28238', '45', '11', '29', '因 为 神 的 恩 赐 和 选 召 是 没 有 后 悔 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28239', '45', '11', '30', '你 们 从 前 不 顺 服 神 ， 如 今 因 他 们 的 不 顺 服 ， 你 们 倒 蒙 了 怜 恤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28240', '45', '11', '31', '这 样 ， 他 们 也 是 不 顺 服 ， 叫 他 们 因 着 施 给 你 们 的 怜 恤 ， 现 在 也 就 蒙 怜 恤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28241', '45', '11', '32', '因 为 神 将 众 人 都 圈 在 不 顺 服 之 中 ， 特 意 要 怜 恤 众 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28242', '45', '11', '33', '深 哉 ， 神 丰 富 的 智 慧 和 知 识 ！ 他 的 判 断 何 其 难 测 ！ 他 的 踪 迹 何 其 难 寻 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28243', '45', '11', '34', '谁 知 道 主 的 心 ？ 谁 作 过 他 的 谋 士 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28244', '45', '11', '35', '谁 是 先 给 了 他 ， 使 他 后 来 偿 还 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28245', '45', '11', '36', '因 为 万 有 都 是 本 于 他 ， 倚 靠 他 ， 归 于 他 。 愿 荣 耀 归 给 他 ， 直 到 永 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28246', '45', '12', '1', '＜ 基 督 里 的 新 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28247', '45', '12', '2', '不 要 效 法 这 个 世 界 ， 只 要 心 意 更 新 而 变 化 ， 叫 你 们 察 验 何 为 神 的 善 良 、 纯 全 、 可 喜 悦 的 旨 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28248', '45', '12', '3', '我 凭 着 所 赐 我 的 恩 对 你 们 各 人 说 ： 不 要 看 自 己 过 于 所 当 看 的 ； 要 照 着 神 所 分 给 各 人 信 心 的 大 小 ， 看 得 合 乎 中 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28249', '45', '12', '4', '正 如 我 们 一 个 身 子 上 有 好 些 肢 体 ， 肢 体 也 不 都 是 一 样 的 用 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28250', '45', '12', '5', '我 们 这 许 多 人 ， 在 基 督 里 成 为 一 身 ， 互 相 联 络 作 肢 体 ， 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28251', '45', '12', '6', '按 我 们 所 得 的 恩 赐 ， 各 有 不 同 。 或 说 预 言 ， 就 当 照 着 信 心 的 程 度 说 预 言 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28252', '45', '12', '7', '或 作 执 事 ， 就 当 专 一 执 事 ； 或 作 教 导 的 ， 就 当 专 一 教 导 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28253', '45', '12', '8', '或 作 劝 化 的 ， 就 当 专 一 劝 化 ； 施 舍 的 ， 就 当 诚 实 ； 治 理 的 ， 就 当 殷 勤 ； 怜 悯 人 的 ， 就 当 甘 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28254', '45', '12', '9', '＜ 基 督 徒 的 生 活 守 则 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28255', '45', '12', '10', '爱 弟 兄 ， 要 彼 此 亲 热 ； 恭 敬 人 ， 要 彼 此 推 让 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28256', '45', '12', '11', '殷 勤 ， 不 可 懒 惰 ； 要 心 里 火 热 ， 常 常 服 事 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28257', '45', '12', '12', '在 指 望 中 要 喜 乐 ； 在 患 难 中 要 忍 耐 ； 祷 告 要 恒 切 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28258', '45', '12', '13', '圣 徒 缺 乏 ， 要 帮 补 ； 客 ， 要 一 味 地 款 待 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28259', '45', '12', '14', '逼 迫 你 们 的 ， 要 给 他 们 祝 福 ； 只 要 祝 福 ， 不 可 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28260', '45', '12', '15', '与 喜 乐 的 人 要 同 乐 ； 与 哀 哭 的 人 要 同 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28261', '45', '12', '16', '要 彼 此 同 心 ； 不 要 志 气 高 大 ， 倒 要 俯 就 卑 微 的 人 ｛ 人 ： 或 译 事 ｝ 。 不 要 自 以 为 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28262', '45', '12', '17', '不 要 以 恶 报 恶 ； 众 人 以 为 美 的 事 要 留 心 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28263', '45', '12', '18', '若 是 能 行 ， 总 要 尽 力 与 众 人 和 睦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28264', '45', '12', '19', '亲 爱 的 弟 兄 ， 不 要 自 己 伸 冤 ， 宁 可 让 步 ， 听 凭 主 怒 ｛ 或 译 ： 让 人 发 怒 ｝ ； 因 为 经 上 记 着 ： “ 主 说 ： ‘ 伸 冤 在 我 ， 我 必 报 应 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28265', '45', '12', '20', '所 以 ， “ 你 的 仇 敌 若 饿 了 ， 就 给 他 吃 ， 若 渴 了 ， 就 给 他 喝 ； 因 为 你 这 样 行 就 是 把 炭 火 堆 在 他 的 头 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28266', '45', '12', '21', '你 不 可 为 恶 所 胜 ， 反 要 以 善 胜 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28267', '45', '13', '1', '＜ 顺 服 掌 权 者 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28268', '45', '13', '2', '所 以 ， 抗 拒 掌 权 的 就 是 抗 拒 神 的 命 ； 抗 拒 的 必 自 取 刑 罚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28269', '45', '13', '3', '作 官 的 原 不 是 叫 行 善 的 惧 怕 ， 乃 是 叫 作 恶 的 惧 怕 。 你 愿 意 不 惧 怕 掌 权 的 吗 ？ 你 只 要 行 善 ， 就 可 得 他 的 称 赞 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28270', '45', '13', '4', '因 为 他 是 神 的 用 人 ， 是 与 你 有 益 的 。 你 若 作 恶 ， 却 当 惧 怕 ； 因 为 他 不 是 空 空 地 佩 剑 ； 他 是 神 的 用 人 ， 是 伸 冤 的 ， 刑 罚 那 作 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28271', '45', '13', '5', '所 以 ， 你 们 必 须 顺 服 ， 不 但 是 因 为 刑 罚 ， 也 是 因 为 良 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28272', '45', '13', '6', '你 们 纳 粮 ， 也 为 这 个 缘 故 ； 因 他 们 是 神 的 差 役 ， 常 常 特 管 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28273', '45', '13', '7', '凡 人 所 当 得 的 ， 就 给 他 。 当 得 粮 的 ， 给 他 纳 粮 ； 当 得 税 的 ， 给 他 上 税 ； 当 惧 怕 的 ， 惧 怕 他 ； 当 恭 敬 的 ， 恭 敬 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28274', '45', '13', '8', '＜ 相 爱 如 兄 弟 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28275', '45', '13', '9', '像 那 不 可 奸 淫 ， 不 可 杀 人 ， 不 可 偷 盗 ， 不 可 贪 婪 ， 或 有 别 的 诫 命 ， 都 包 在 爱 人 如 己 这 一 句 话 之 内 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28276', '45', '13', '10', '爱 是 不 加 害 与 人 的 ， 所 以 爱 就 完 全 了 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28277', '45', '13', '11', '＜ 白 昼 将 近 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28278', '45', '13', '12', '黑 夜 已 深 ， 白 昼 将 近 。 我 们 就 当 脱 去 暗 昧 的 行 为 ， 带 上 光 明 的 兵 器 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28279', '45', '13', '13', '行 事 为 人 要 端 正 ， 好 像 行 在 白 昼 。 不 可 荒 宴 醉 酒 ； 不 可 好 色 邪 荡 ； 不 可 争 竞 嫉 妒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28280', '45', '13', '14', '总 要 披 戴 主 耶 稣 基 督 ， 不 要 为 肉 体 安 排 ， 去 放 纵 私 欲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28281', '45', '14', '1', '＜ 不 可 论 断 弟 兄 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28282', '45', '14', '2', '有 人 信 百 物 都 可 吃 ； 但 那 软 弱 的 ， 只 吃 蔬 菜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28283', '45', '14', '3', '吃 的 人 不 可 轻 看 不 吃 的 人 ； 不 吃 的 人 不 可 论 断 吃 的 人 ； 因 为 神 已 经 收 纳 他 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28284', '45', '14', '4', '你 是 谁 ， 竟 论 断 别 人 的 仆 人 呢 ？ 他 或 站 住 或 跌 倒 ， 自 有 他 的 主 人 在 ； 而 且 他 也 必 要 站 住 ， 因 为 主 能 使 他 站 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28285', '45', '14', '5', '有 人 看 这 日 比 那 日 强 ； 有 人 看 日 日 都 是 一 样 。 只 是 各 人 心 里 要 意 见 坚 定 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28286', '45', '14', '6', '守 日 的 人 是 为 主 守 的 。 吃 的 人 是 为 主 吃 的 ， 因 他 感 谢 神 ； 不 吃 的 人 是 为 主 不 吃 的 ， 也 感 谢 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28287', '45', '14', '7', '我 们 没 有 一 个 人 为 自 己 活 ， 也 没 有 一 个 人 为 自 己 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28288', '45', '14', '8', '我 们 若 活 着 ， 是 为 主 而 活 ； 若 死 了 ， 是 为 主 而 死 。 所 以 ， 我 们 或 活 或 死 总 是 主 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28289', '45', '14', '9', '因 此 ， 基 督 死 了 ， 又 活 了 ， 为 要 作 死 人 并 活 人 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28290', '45', '14', '10', '你 这 个 人 ， 为 什 么 论 断 弟 兄 呢 ？ 又 为 什 么 轻 看 弟 兄 呢 ？ 因 我 们 都 要 站 在 神 的 台 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28291', '45', '14', '11', '经 上 写 着 ： 主 说 ： 我 凭 着 我 的 永 生 起 誓 ： 万 膝 必 向 我 跪 拜 ； 万 口 必 向 我 承 认 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28292', '45', '14', '12', '这 样 看 来 ， 我 们 各 人 必 要 将 自 己 的 事 在 神 面 前 说 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28293', '45', '14', '13', '＜ 不 可 使 弟 兄 跌 倒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28294', '45', '14', '14', '我 凭 着 主 耶 稣 确 知 深 信 ， 凡 物 本 来 没 有 不 洁 净 的 ； 惟 独 人 以 为 不 洁 净 的 ， 在 他 就 不 洁 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28295', '45', '14', '15', '你 若 因 食 物 叫 弟 兄 忧 愁 ， 就 不 是 按 着 爱 人 的 道 理 行 。 基 督 已 经 替 他 死 ， 你 不 可 因 你 的 食 物 叫 他 败 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28296', '45', '14', '16', '不 可 叫 你 的 善 被 人 毁 谤 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28297', '45', '14', '17', '因 为 神 的 国 不 在 乎 吃 喝 ， 只 在 乎 公 义 、 和 平 ， 并 圣 灵 中 的 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28298', '45', '14', '18', '在 这 几 样 上 服 事 基 督 的 ， 就 为 神 所 喜 悦 ， 又 为 人 所 称 许 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28299', '45', '14', '19', '所 以 ， 我 们 务 要 追 求 和 睦 的 事 与 彼 此 建 立 德 行 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28300', '45', '14', '20', '不 可 因 食 物 毁 坏 神 的 工 程 。 凡 物 固 然 洁 净 ， 但 有 人 因 食 物 叫 人 跌 倒 ， 就 是 他 的 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28301', '45', '14', '21', '无 论 是 吃 肉 是 喝 酒 ， 是 什 么 别 的 事 ， 叫 弟 兄 跌 倒 ， 一 概 不 做 才 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28302', '45', '14', '22', '你 有 信 心 ， 就 当 在 神 面 前 守 着 。 人 在 自 己 以 为 可 行 的 事 上 能 不 自 责 ， 就 有 福 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28303', '45', '14', '23', '若 有 疑 心 而 吃 的 ， 就 必 有 罪 ， 因 为 他 吃 不 是 出 于 信 心 。 凡 不 出 于 信 心 的 都 是 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28304', '45', '15', '1', '＜ 不 求 自 己 的 喜 悦 ， 要 叫 邻 舍 喜 悦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28305', '45', '15', '2', '我 们 各 人 务 要 叫 邻 舍 喜 悦 ， 使 他 得 益 处 ， 建 立 德 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28306', '45', '15', '3', '因 为 基 督 也 不 求 自 己 的 喜 悦 ， 如 经 上 所 记 ： “ 辱 骂 你 人 的 辱 骂 都 落 在 我 身 上 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28307', '45', '15', '4', '从 前 所 写 的 圣 经 都 是 为 教 训 我 们 写 的 ， 叫 我 们 因 圣 经 所 生 的 忍 耐 和 安 慰 可 以 得 着 盼 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28308', '45', '15', '5', '但 愿 赐 忍 耐 安 慰 的 神 叫 你 们 彼 此 同 心 ， 效 法 基 督 耶 稣 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28309', '45', '15', '6', '一 心 一 口 荣 耀 神 ─ ─ 我 们 主 耶 稣 基 督 的 父 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28310', '45', '15', '7', '＜ 神 的 福 音 一 视 同 仁 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28311', '45', '15', '8', '我 说 ， 基 督 是 为 神 真 理 作 了 受 割 礼 人 的 执 事 ， 要 证 实 所 应 许 列 祖 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28312', '45', '15', '9', '并 叫 外 邦 人 因 他 的 怜 悯 荣 耀 神 。 如 经 上 所 记 ： 因 此 ， 我 要 在 外 邦 中 称 赞 你 ， 歌 颂 你 的 名 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28313', '45', '15', '10', '又 说 ： 你 们 外 邦 人 当 与 主 的 百 姓 一 同 欢 乐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28314', '45', '15', '11', '又 说 ： 外 邦 啊 ， 你 们 当 赞 美 主 ！ 万 民 哪 ， 你 们 都 当 颂 赞 他 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28315', '45', '15', '12', '又 有 以 赛 亚 说 ： 将 来 有 耶 西 的 根 ， 就 是 那 兴 起 来 要 治 理 外 邦 的 ； 外 邦 人 要 仰 望 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28316', '45', '15', '13', '但 愿 使 人 有 盼 望 的 神 ， 因 信 将 诸 般 的 喜 乐 、 平 安 充 满 你 们 的 心 ， 使 你 们 藉 着 圣 灵 的 能 力 大 有 盼 望 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28317', '45', '15', '14', '＜ 保 罗 的 宣 教 使 命 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28318', '45', '15', '15', '但 我 稍 微 放 胆 写 信 给 你 们 ， 是 要 提 醒 你 们 的 记 性 ， 特 因 神 所 给 我 的 恩 典 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28319', '45', '15', '16', '使 我 为 外 邦 人 作 基 督 耶 稣 的 仆 役 ， 作 神 福 音 的 祭 司 ， 叫 所 献 上 的 外 邦 人 ， 因 着 圣 灵 成 为 圣 洁 ， 可 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28320', '45', '15', '17', '所 以 论 到 神 的 事 ， 我 在 基 督 耶 稣 里 有 可 夸 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28321', '45', '15', '18', '除 了 基 督 藉 我 做 的 那 些 事 ， 我 什 么 都 不 敢 提 ， 只 提 他 藉 我 言 语 作 为 ， 用 神 迹 奇 事 的 能 力 ， 并 圣 灵 的 能 力 ， 使 外 邦 人 顺 服 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28322', '45', '15', '19', '甚 至 我 从 耶 路 撒 冷 ， 直 转 到 以 利 哩 古 ， 到 处 传 了 基 督 的 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28323', '45', '15', '20', '我 立 了 志 向 ， 不 在 基 督 的 名 被 称 过 的 地 方 传 福 音 ， 免 得 建 造 在 别 人 的 根 基 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28324', '45', '15', '21', '就 如 经 上 所 记 ： 未 曾 闻 知 他 信 息 的 ， 将 要 看 见 ； 未 曾 听 过 的 ， 将 要 明 白 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28325', '45', '15', '22', '＜ 保 罗 计 划 访 问 罗 马 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28326', '45', '15', '23', '但 如 今 ， 在 这 里 再 没 有 可 传 的 地 方 ， 而 且 这 好 几 年 ， 我 切 心 想 望 到 西 班 牙 去 的 时 候 ， 可 以 到 你 们 那 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28327', '45', '15', '24', '盼 望 从 你 们 那 里 经 过 ， 得 见 你 们 ， 先 与 你 们 彼 此 交 往 ， 心 里 稍 微 满 足 ， 然 后 蒙 你 们 送 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28328', '45', '15', '25', '但 现 在 ， 我 往 耶 路 撒 冷 去 供 给 圣 徒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28329', '45', '15', '26', '因 为 马 其 顿 和 亚 该 亚 人 乐 意 凑 出 捐 项 给 耶 路 撒 冷 圣 徒 中 的 穷 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28330', '45', '15', '27', '这 固 然 是 他 们 乐 意 的 ， 其 实 也 算 是 所 欠 的 债 ； 因 外 邦 人 既 然 在 他 们 属 灵 的 好 处 上 有 分 ， 就 当 把 养 身 之 物 供 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28331', '45', '15', '28', '等 我 办 完 了 这 事 ， 把 这 善 果 向 他 们 交 付 明 白 ， 我 就 要 路 过 你 们 那 里 ， 往 西 班 牙 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28332', '45', '15', '29', '我 也 晓 得 ， 去 的 时 候 必 带 着 基 督 丰 盛 的 恩 典 而 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28333', '45', '15', '30', '弟 兄 们 ， 我 藉 着 我 们 主 耶 稣 基 督 ， 又 藉 着 圣 灵 的 爱 ， 劝 你 们 与 我 一 同 竭 力 ， 为 我 祈 求 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28334', '45', '15', '31', '叫 我 脱 离 在 犹 太 不 顺 从 的 人 ， 也 叫 我 为 耶 路 撒 冷 所 办 的 捐 项 可 蒙 圣 徒 悦 纳 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28335', '45', '15', '32', '并 叫 我 顺 着 神 的 旨 意 ， 欢 欢 喜 喜 地 到 你 们 那 里 ， 与 你 们 同 得 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28336', '45', '15', '33', '愿 赐 平 安 的 神 常 和 你 们 众 人 同 在 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28337', '45', '16', '1', '＜ 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28338', '45', '16', '2', '请 你 们 为 主 接 待 她 ， 合 乎 圣 徒 的 体 统 。 她 在 何 事 上 要 你 们 帮 助 ， 你 们 就 帮 助 她 ； 因 她 素 来 帮 助 许 多 人 ， 也 帮 助 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28339', '45', '16', '3', '问 百 基 拉 和 亚 居 拉 安 。 他 们 在 基 督 耶 稣 里 与 我 同 工 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28340', '45', '16', '4', '也 为 我 的 命 将 自 己 的 颈 项 置 之 度 外 。 不 但 我 感 谢 他 们 ， 就 是 外 邦 的 众 教 会 也 感 谢 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28341', '45', '16', '5', '又 问 在 他 们 家 中 的 教 会 安 。 问 我 所 亲 爱 的 以 拜 尼 土 安 ； 他 在 亚 细 亚 是 归 基 督 初 结 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28342', '45', '16', '6', '又 问 马 利 亚 安 ； 她 为 你 们 多 受 劳 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28343', '45', '16', '7', '又 问 我 亲 属 与 我 一 同 坐 监 的 安 多 尼 古 和 犹 尼 亚 安 ； 他 们 在 使 徒 中 是 有 名 望 的 ， 也 是 比 我 先 在 基 督 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28344', '45', '16', '8', '又 问 我 在 主 里 面 所 亲 爱 的 暗 伯 利 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28345', '45', '16', '9', '又 问 在 基 督 里 与 我 们 同 工 的 耳 巴 奴 ， 并 我 所 亲 爱 的 士 大 古 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28346', '45', '16', '10', '又 问 在 基 督 里 经 过 试 验 的 亚 比 利 安 。 问 亚 利 多 布 家 里 的 人 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28347', '45', '16', '11', '又 问 我 亲 属 希 罗 天 安 。 问 拿 其 数 家 在 主 里 的 人 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28348', '45', '16', '12', '又 问 为 主 劳 苦 的 土 非 拿 氏 和 土 富 撒 氏 安 。 问 可 亲 爱 为 主 多 受 劳 苦 的 彼 息 氏 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28349', '45', '16', '13', '又 问 在 主 蒙 拣 选 的 鲁 孚 和 他 母 亲 安 ； 他 的 母 亲 就 是 我 的 母 亲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28350', '45', '16', '14', '又 问 亚 逊 其 土 、 弗 勒 干 、 黑 米 、 八 罗 巴 、 黑 马 ， 并 与 他 们 在 一 处 的 弟 兄 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28351', '45', '16', '15', '又 问 非 罗 罗 古 和 犹 利 亚 ， 尼 利 亚 和 他 姊 妹 ， 同 阿 林 巴 并 与 他 们 在 一 处 的 众 圣 徒 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28352', '45', '16', '16', '你 们 亲 嘴 问 安 ， 彼 此 务 要 圣 洁 。 基 督 的 众 教 会 都 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28353', '45', '16', '17', '弟 兄 们 ， 那 些 离 间 你 们 、 叫 你 们 跌 倒 、 背 乎 所 学 之 道 的 人 ， 我 劝 你 们 要 留 意 躲 避 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28354', '45', '16', '18', '因 为 这 样 的 人 不 服 事 我 们 的 主 基 督 ， 只 服 事 自 己 的 肚 腹 ， 用 花 言 巧 语 诱 惑 那 些 老 实 人 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28355', '45', '16', '19', '你 们 的 顺 服 已 经 传 于 众 人 ， 所 以 我 为 你 们 欢 喜 ； 但 我 愿 意 你 们 在 善 上 聪 明 ， 在 恶 上 愚 拙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28356', '45', '16', '20', '赐 平 安 的 神 快 要 将 撒 但 践 踏 在 你 们 脚 下 。 愿 我 主 耶 稣 基 督 的 恩 常 和 你 们 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28357', '45', '16', '21', '与 我 同 工 的 提 摩 太 ， 和 我 的 亲 属 路 求 、 耶 孙 、 所 西 巴 德 ， 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28358', '45', '16', '22', '我 这 代 笔 写 信 的 德 提 ， 在 主 里 面 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28359', '45', '16', '23', '那 接 待 我 、 也 接 待 全 教 会 的 该 犹 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28360', '45', '16', '24', '城 内 管 银 库 的 以 拉 都 和 兄 弟 括 土 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28361', '45', '16', '25', '＜ 颂 赞 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28362', '45', '16', '26', '这 奥 秘 如 今 显 明 出 来 ， 而 且 按 着 永 生 神 的 命 ， 藉 众 先 知 的 书 指 示 万 国 的 民 ， 使 他 们 信 服 真 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28363', '45', '16', '27', '愿 荣 耀 ， 因 耶 稣 基 督 ， 归 与 独 一 全 智 的 神 ， 直 到 永 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28364', '46', '1', '1', '＜ 祝 福 和 感 谢 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28365', '46', '1', '2', '写 信 给 在 哥 林 多 神 的 教 会 ， 就 是 在 基 督 耶 稣 里 成 圣 、 蒙 召 作 圣 徒 的 ， 以 及 所 有 在 各 处 求 告 我 主 耶 稣 基 督 之 名 的 人 。 基 督 是 他 们 的 主 ， 也 是 我 们 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28366', '46', '1', '3', '愿 恩 惠 、 平 安 从 神 我 们 的 父 并 主 耶 稣 基 督 归 与 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28367', '46', '1', '4', '我 常 为 你 们 感 谢 我 的 神 ， 因 神 在 基 督 耶 稣 里 所 赐 给 你 们 的 恩 惠 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28368', '46', '1', '5', '又 因 你 们 在 他 里 面 凡 事 富 足 ， 口 才 、 知 识 都 全 备 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28369', '46', '1', '6', '正 如 我 为 基 督 作 的 见 证 ， 在 你 们 心 里 得 以 坚 固 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28370', '46', '1', '7', '以 致 你 们 在 恩 赐 上 没 有 一 样 不 及 人 的 ， 等 候 我 们 的 主 耶 稣 基 督 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28371', '46', '1', '8', '他 也 必 坚 固 你 们 到 底 ， 叫 你 们 在 我 们 主 耶 稣 基 督 的 日 子 无 可 责 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28372', '46', '1', '9', '神 是 信 实 的 ， 你 们 原 是 被 他 所 召 ， 好 与 他 儿 子 ─ ─ 我 们 的 主 耶 稣 基 督 一 同 得 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28373', '46', '1', '10', '＜ 在 教 会 中 有 纷 争 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28374', '46', '1', '11', '因 为 革 来 氏 家 里 的 人 曾 对 我 提 起 弟 兄 们 来 ， 说 你 们 中 间 有 纷 争 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28375', '46', '1', '12', '我 的 意 思 就 是 你 们 各 人 说 ： “ 我 是 属 保 罗 的 ” ； “ 我 是 属 亚 波 罗 的 ” ； “ 我 是 属 矶 法 的 ” ； “ 我 是 属 基 督 的 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28376', '46', '1', '13', '基 督 是 分 开 的 吗 ？ 保 罗 为 你 们 钉 了 十 字 架 吗 ？ 你 们 是 奉 保 罗 的 名 受 了 洗 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28377', '46', '1', '14', '我 感 谢 神 ， 除 了 基 利 司 布 并 该 犹 以 外 ， 我 没 有 给 你 们 一 个 人 施 洗 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28378', '46', '1', '15', '免 得 有 人 说 ， 你 们 是 奉 我 的 名 受 洗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28379', '46', '1', '16', '我 也 给 司 提 法 那 家 施 过 洗 ， 此 外 给 别 人 施 洗 没 有 ， 我 却 记 不 清 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28380', '46', '1', '17', '基 督 差 遣 我 ， 原 不 是 为 施 洗 ， 乃 是 为 传 福 音 ， 并 不 用 智 慧 的 言 语 ， 免 得 基 督 的 十 字 架 落 了 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28381', '46', '1', '18', '＜ 基 督 是 神 的 能 力 和 智 慧 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28382', '46', '1', '19', '就 如 经 上 所 记 ： 我 要 灭 绝 智 慧 人 的 智 慧 ， 废 弃 聪 明 人 的 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28383', '46', '1', '20', '智 慧 人 在 哪 里 ？ 文 士 在 哪 里 ？ 这 世 上 的 辩 士 在 哪 里 ？ 神 岂 不 是 叫 这 世 上 的 智 慧 变 成 愚 拙 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28384', '46', '1', '21', '世 人 凭 自 己 的 智 慧 ， 既 不 认 识 神 ， 神 就 乐 意 用 人 所 当 作 愚 拙 的 道 理 拯 救 那 些 信 的 人 ； 这 就 是 神 的 智 慧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28385', '46', '1', '22', '犹 太 人 是 要 神 迹 ， 希 腊 人 是 求 智 慧 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28386', '46', '1', '23', '我 们 却 是 传 钉 十 字 架 的 基 督 ， 在 犹 太 人 为 绊 脚 石 ， 在 外 邦 人 为 愚 拙 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28387', '46', '1', '24', '但 在 那 蒙 召 的 ， 无 论 是 犹 太 人 、 希 腊 人 ， 基 督 总 为 神 的 能 力 ， 神 的 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28388', '46', '1', '25', '因 神 的 愚 拙 总 比 人 智 慧 ， 神 的 软 弱 总 比 人 强 壮 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28389', '46', '1', '26', '弟 兄 们 哪 ， 可 见 你 们 蒙 召 的 ， 按 着 肉 体 有 智 慧 的 不 多 ， 有 能 力 的 不 多 ， 有 尊 贵 的 也 不 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28390', '46', '1', '27', '神 却 拣 选 了 世 上 愚 拙 的 ， 叫 有 智 慧 的 羞 愧 ； 又 拣 选 了 世 上 软 弱 的 ， 叫 那 强 壮 的 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28391', '46', '1', '28', '神 也 拣 选 了 世 上 卑 贱 的 ， 被 人 厌 恶 的 ， 以 及 那 无 有 的 ， 为 要 废 掉 那 有 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28392', '46', '1', '29', '使 一 切 有 血 气 的 ， 在 神 面 前 一 个 也 不 能 自 夸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28393', '46', '1', '30', '但 你 们 得 在 基 督 耶 稣 里 是 本 乎 神 ， 神 又 使 他 成 为 我 们 的 智 慧 、 公 义 、 圣 洁 、 救 赎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28394', '46', '1', '31', '如 经 上 所 记 ： “ 夸 口 的 ， 当 指 着 主 夸 口 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28395', '46', '2', '1', '＜ 传 扬 钉 十 字 架 的 基 督 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28396', '46', '2', '2', '因 为 我 曾 定 了 主 意 ， 在 你 们 中 间 不 知 道 别 的 ， 只 知 道 耶 稣 基 督 并 他 钉 十 字 架 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28397', '46', '2', '3', '我 在 你 们 那 里 ， 又 软 弱 ， 又 惧 怕 又 甚 战 兢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28398', '46', '2', '4', '我 说 的 话 、 讲 的 道 ， 不 是 用 智 慧 委 婉 的 言 语 ， 乃 是 用 圣 灵 和 大 能 的 明 证 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28399', '46', '2', '5', '叫 你 们 的 信 不 在 乎 人 的 智 慧 ， 只 在 乎 神 的 大 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28400', '46', '2', '6', '＜ 神 藉 着 圣 灵 启 示 我 们 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28401', '46', '2', '7', '我 们 讲 的 ， 乃 是 从 前 所 隐 藏 、 神 奥 秘 的 智 慧 ， 就 是 神 在 万 世 以 前 预 定 使 我 们 得 荣 耀 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28402', '46', '2', '8', '这 智 慧 世 上 有 权 有 位 的 人 没 有 一 个 知 道 的 ， 他 们 若 知 道 ， 就 不 把 荣 耀 的 主 钉 在 十 字 架 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28403', '46', '2', '9', '如 经 上 所 记 ： 神 为 爱 他 的 人 所 预 备 的 是 眼 睛 未 曾 看 见 ， 耳 朵 未 曾 听 见 ， 人 心 也 未 曾 想 到 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28404', '46', '2', '10', '只 有 神 藉 着 圣 灵 向 我 们 显 明 了 ， 因 为 圣 灵 参 透 万 事 ， 就 是 神 深 奥 的 事 也 参 透 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28405', '46', '2', '11', '除 了 在 人 里 头 的 灵 ， 谁 知 道 人 的 事 ？ 像 这 样 ， 除 了 神 的 灵 ， 也 没 有 人 知 道 神 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28406', '46', '2', '12', '我 们 所 领 受 的 ， 并 不 是 世 上 的 灵 ， 乃 是 从 神 来 的 灵 ， 叫 我 们 能 知 道 神 开 恩 赐 给 我 们 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28407', '46', '2', '13', '并 且 我 们 讲 说 这 些 事 ， 不 是 用 人 智 慧 所 指 教 的 言 语 ， 乃 是 用 圣 灵 所 指 教 的 言 语 ， 将 属 灵 的 话 解 释 属 灵 的 事 ｛ 或 译 ： 将 属 灵 的 事 讲 与 属 灵 的 人 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28408', '46', '2', '14', '然 而 ， 属 血 气 的 人 不 领 会 神 圣 灵 的 事 ， 反 倒 以 为 愚 拙 ， 并 且 不 能 知 道 ， 因 为 这 些 事 惟 有 属 灵 的 人 才 能 看 透 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28409', '46', '2', '15', '属 灵 的 人 能 看 透 万 事 ， 却 没 有 一 人 能 看 透 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28410', '46', '2', '16', '谁 曾 知 道 主 的 心 去 教 导 他 呢 ？ 但 我 们 是 有 基 督 的 心 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28411', '46', '3', '1', '＜ 神 的 同 工 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28412', '46', '3', '2', '我 是 用 奶 喂 你 们 ， 没 有 用 饭 喂 你 们 。 那 时 你 们 不 能 吃 ， 就 是 如 今 还 是 不 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28413', '46', '3', '3', '你 们 仍 是 属 肉 体 的 ， 因 为 在 你 们 中 间 有 嫉 妒 、 纷 争 ， 这 岂 不 是 属 乎 肉 体 、 照 着 世 人 的 样 子 行 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28414', '46', '3', '4', '有 说 ： “ 我 是 属 保 罗 的 ” ； 有 说 ： “ 我 是 属 亚 波 罗 的 。 ” 这 岂 不 是 你 们 和 世 人 一 样 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28415', '46', '3', '5', '亚 波 罗 算 什 么 ？ 保 罗 算 什 么 ？ 无 非 是 执 事 ， 照 主 所 赐 给 他 们 各 人 的 ， 引 导 你 们 相 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28416', '46', '3', '6', '我 栽 种 了 ， 亚 波 罗 浇 灌 了 ， 惟 有 神 叫 他 生 长 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28417', '46', '3', '7', '可 见 栽 种 的 ， 算 不 得 什 么 ， 浇 灌 的 ， 也 算 不 得 什 么 ； 只 在 那 叫 他 生 长 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28418', '46', '3', '8', '栽 种 的 和 浇 灌 的 ， 都 是 一 样 ， 但 将 来 各 人 要 照 自 己 的 工 夫 得 自 己 的 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28419', '46', '3', '9', '因 为 我 们 是 与 神 同 工 的 ； 你 们 是 神 所 耕 种 的 田 地 ， 所 建 造 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28420', '46', '3', '10', '我 照 神 所 给 我 的 恩 ， 好 像 一 个 聪 明 的 工 头 ， 立 好 了 根 基 ， 有 别 人 在 上 面 建 造 ； 只 是 各 人 要 谨 慎 怎 样 在 上 面 建 造 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28421', '46', '3', '11', '因 为 那 已 经 立 好 的 根 基 就 是 耶 稣 基 督 ， 此 外 没 有 人 能 立 别 的 根 基 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28422', '46', '3', '12', '若 有 人 用 金 、 银 、 宝 石 、 草 木 、 禾 秸 在 这 根 基 上 建 造 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28423', '46', '3', '13', '各 人 的 工 程 必 然 显 露 ， 因 为 那 日 子 要 将 它 表 明 出 来 ， 有 火 发 现 ； 这 火 要 试 验 各 人 的 工 程 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28424', '46', '3', '14', '人 在 那 根 基 上 所 建 造 的 工 程 若 存 得 住 ， 他 就 要 得 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28425', '46', '3', '15', '人 的 工 程 若 被 烧 了 ， 他 就 要 受 亏 损 ， 自 己 却 要 得 救 ； 虽 然 得 救 ， 乃 像 从 火 里 经 过 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28426', '46', '3', '16', '岂 不 知 你 们 是 神 的 殿 ， 神 的 灵 住 在 你 们 里 头 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28427', '46', '3', '17', '若 有 人 毁 坏 神 的 殿 ， 神 必 要 毁 坏 那 人 ； 因 为 神 的 殿 是 圣 的 ， 这 殿 就 是 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28428', '46', '3', '18', '人 不 可 自 欺 。 你 们 中 间 若 有 人 在 这 世 界 自 以 为 有 智 慧 ， 倒 不 如 变 作 愚 拙 ， 好 成 为 有 智 慧 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28429', '46', '3', '19', '因 这 世 界 的 智 慧 ， 在 神 看 是 愚 拙 。 如 经 上 记 着 说 ： “ 主 叫 有 智 慧 的 ， 中 了 自 己 的 诡 计 ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28430', '46', '3', '20', '又 说 ： “ 主 知 道 智 慧 人 的 意 念 是 虚 妄 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28431', '46', '3', '21', '所 以 无 论 谁 ， 都 不 可 拿 人 夸 口 ， 因 为 万 有 全 是 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28432', '46', '3', '22', '或 保 罗 ， 或 亚 波 罗 ， 或 矶 法 ， 或 世 界 ， 或 生 ， 或 死 ， 或 现 今 的 事 ， 或 将 来 的 事 ， 全 是 你 们 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28433', '46', '3', '23', '并 且 你 们 是 属 基 督 的 ， 基 督 又 是 属 神 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28434', '46', '4', '1', '＜ 使 徒 的 工 作 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28435', '46', '4', '2', '所 求 于 管 家 的 ， 是 要 他 有 忠 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28436', '46', '4', '3', '我 被 你 们 论 断 ， 或 被 别 人 论 断 ， 我 都 以 为 极 小 的 事 ； 连 我 自 己 也 不 论 断 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28437', '46', '4', '4', '我 虽 不 觉 得 自 己 有 错 ， 却 也 不 能 因 此 得 以 称 义 ； 但 判 断 我 的 乃 是 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28438', '46', '4', '5', '所 以 ， 时 候 未 到 ， 什 么 都 不 要 论 断 ， 只 等 主 来 ， 他 要 照 出 暗 中 的 隐 情 ， 显 明 人 心 的 意 念 。 那 时 ， 各 人 要 从 神 那 里 得 著 称 赞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28439', '46', '4', '6', '弟 兄 们 ， 我 为 你 们 的 缘 故 ， 拿 这 些 事 转 比 自 己 和 亚 波 罗 ， 叫 你 们 效 法 我 们 不 可 过 于 圣 经 所 记 ， 免 得 你 们 自 高 自 大 ， 贵 重 这 个 ， 轻 看 那 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28440', '46', '4', '7', '使 你 与 人 不 同 的 是 谁 呢 ？ 你 有 什 么 不 是 领 受 的 呢 ？ 若 是 领 受 的 ， 为 何 自 夸 ， 仿 佛 不 是 领 受 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28441', '46', '4', '8', '你 们 已 经 饱 足 了 ！ 已 经 丰 富 了 ！ 不 用 我 们 ， 自 己 就 作 王 了 ！ 我 愿 意 你 们 果 真 作 王 ， 叫 我 们 也 得 与 你 们 一 同 作 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28442', '46', '4', '9', '我 想 神 把 我 们 使 徒 明 明 列 在 末 后 ， 好 像 定 死 罪 的 囚 犯 ； 因 为 我 们 成 了 一 台 戏 ， 给 世 人 和 天 使 观 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28443', '46', '4', '10', '我 们 为 基 督 的 缘 故 算 是 愚 拙 的 ， 你 们 在 基 督 里 倒 是 聪 明 的 ； 我 们 软 弱 ， 你 们 倒 强 壮 ； 你 们 有 荣 耀 ， 我 们 倒 被 藐 视 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28444', '46', '4', '11', '直 到 如 今 ， 我 们 还 是 又 饥 又 渴 ， 又 赤 身 露 体 ， 又 挨 打 ， 又 没 有 一 定 的 住 处 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28445', '46', '4', '12', '并 且 劳 苦 ， 亲 手 做 工 。 被 人 咒 骂 ， 我 们 就 祝 福 ； 被 人 逼 迫 ， 我 们 就 忍 受 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28446', '46', '4', '13', '被 人 毁 谤 ， 我 们 就 善 劝 。 直 到 如 今 ， 人 还 把 我 们 看 作 世 界 上 的 污 秽 ， 万 物 中 的 渣 滓 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28447', '46', '4', '14', '我 写 这 话 ， 不 是 叫 你 们 羞 愧 ， 乃 是 警 戒 你 们 ， 好 像 我 所 亲 爱 的 儿 女 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28448', '46', '4', '15', '你 们 学 基 督 的 ， 师 傅 虽 有 一 万 ， 为 父 的 却 是 不 多 ， 因 我 在 基 督 耶 稣 里 用 福 音 生 了 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28449', '46', '4', '16', '所 以 ， 我 求 你 们 效 法 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28450', '46', '4', '17', '因 此 我 已 打 发 提 摩 太 到 你 们 那 里 去 。 他 在 主 里 面 ， 是 我 所 亲 爱 、 有 忠 心 的 儿 子 。 他 必 提 醒 你 们 ， 记 念 我 在 基 督 里 怎 样 行 事 ， 在 各 处 各 教 会 中 怎 样 教 导 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28451', '46', '4', '18', '有 些 人 自 高 自 大 ， 以 为 我 不 到 你 们 那 里 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28452', '46', '4', '19', '然 而 ， 主 若 许 我 ， 我 必 快 到 你 们 那 里 去 ， 并 且 我 所 要 知 道 的 ， 不 是 那 些 自 高 自 大 之 人 的 言 语 ， 乃 是 他 们 的 权 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28453', '46', '4', '20', '因 为 神 的 国 不 在 乎 言 语 ， 乃 在 乎 权 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28454', '46', '4', '21', '你 们 愿 意 怎 么 样 呢 ？ 是 愿 意 我 带 着 刑 杖 到 你 们 那 里 去 呢 ？ 还 是 要 我 存 慈 爱 温 柔 的 心 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28455', '46', '5', '1', '＜ 判 断 淫 乱 的 事 件 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28456', '46', '5', '2', '你 们 还 是 自 高 自 大 ， 并 不 哀 痛 ， 把 行 这 事 的 人 从 你 们 中 间 赶 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28457', '46', '5', '3', '我 身 子 虽 不 在 你 们 那 里 ， 心 却 在 你 们 那 里 ， 好 像 我 亲 自 与 你 们 同 在 ， 已 经 判 断 了 行 这 事 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28458', '46', '5', '4', '就 是 你 们 聚 会 的 时 候 ， 我 的 心 也 同 在 。 奉 我 们 主 耶 稣 的 名 ， 并 用 我 们 主 耶 稣 的 权 能 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28459', '46', '5', '5', '要 把 这 样 的 人 交 给 撒 但 ， 败 坏 他 的 肉 体 ， 使 他 的 灵 魂 在 主 耶 稣 的 日 子 可 以 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28460', '46', '5', '6', '你 们 这 自 夸 是 不 好 的 。 岂 不 知 一 点 面 酵 能 使 全 团 发 起 来 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28461', '46', '5', '7', '你 们 既 是 无 酵 的 面 ， 应 当 把 旧 酵 除 净 ， 好 使 你 们 成 为 新 团 ； 因 为 我 们 逾 越 节 的 羔 羊 基 督 已 经 被 杀 献 祭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28462', '46', '5', '8', '所 以 ， 我 们 守 这 节 不 可 用 旧 酵 ， 也 不 可 用 恶 毒 ｛ 或 译 ： 阴 毒 ｝ 、 邪 恶 的 酵 ， 只 用 诚 实 真 正 的 无 酵 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28463', '46', '5', '9', '我 先 前 写 信 给 你 们 说 ， 不 可 与 淫 乱 的 人 相 交 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28464', '46', '5', '10', '此 话 不 是 指 这 世 上 一 概 行 淫 乱 的 ， 或 贪 婪 的 ， 勒 索 的 ， 或 拜 偶 像 的 ； 若 是 这 样 ， 你 们 除 非 离 开 世 界 方 可 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28465', '46', '5', '11', '但 如 今 我 写 信 给 你 们 说 ， 若 有 称 为 弟 兄 是 行 淫 乱 的 ， 或 贪 婪 的 ， 或 拜 偶 像 的 ， 或 辱 骂 的 ， 或 醉 酒 的 ， 或 勒 索 的 ， 这 样 的 人 不 可 与 他 相 交 ， 就 是 与 他 吃 饭 都 不 可 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28466', '46', '5', '12', '因 为 审 判 教 外 的 人 与 我 何 干 ？ 教 内 的 人 岂 不 是 你 们 审 判 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28467', '46', '5', '13', '至 于 外 人 有 神 审 判 他 们 。 你 们 应 当 把 那 恶 人 从 你 们 中 间 赶 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28468', '46', '6', '1', '＜ 在 不 信 主 的 人 面 前 求 审 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28469', '46', '6', '2', '岂 不 知 圣 徒 要 审 判 世 界 吗 ？ 若 世 界 为 你 们 所 审 ， 难 道 你 们 不 配 审 判 这 最 小 的 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28470', '46', '6', '3', '岂 不 知 我 们 要 审 判 天 使 吗 ？ 何 况 今 生 的 事 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28471', '46', '6', '4', '既 是 这 样 ， 你 们 若 有 今 生 的 事 当 审 判 ， 是 派 教 会 所 轻 看 的 人 审 判 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28472', '46', '6', '5', '我 说 这 话 是 要 叫 你 们 羞 耻 。 难 道 你 们 中 间 没 有 一 个 智 慧 人 能 审 断 弟 兄 们 的 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28473', '46', '6', '6', '你 们 竟 是 弟 兄 与 弟 兄 告 状 ， 而 且 告 在 不 信 主 的 人 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28474', '46', '6', '7', '你 们 彼 此 告 状 ， 这 已 经 是 你 们 的 大 错 了 。 为 什 么 不 情 愿 受 欺 呢 ？ 为 什 么 不 情 愿 吃 亏 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28475', '46', '6', '8', '你 们 倒 是 欺 压 人 、 亏 负 人 ， 况 且 所 欺 压 所 亏 负 的 就 是 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28476', '46', '6', '9', '你 们 岂 不 知 不 义 的 人 不 能 承 受 神 的 国 吗 ？ 不 要 自 欺 ！ 无 论 是 淫 乱 的 、 拜 偶 像 的 、 奸 淫 的 、 作 娈 童 的 、 亲 男 色 的 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28477', '46', '6', '10', '偷 窃 的 、 贪 婪 的 、 醉 酒 的 、 辱 骂 的 、 勒 索 的 ， 都 不 能 承 受 神 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28478', '46', '6', '11', '你 们 中 间 也 有 人 从 前 是 这 样 ； 但 如 今 你 们 奉 主 耶 稣 基 督 的 名 ， 并 藉 着 我 们 神 的 灵 ， 已 经 洗 净 ， 成 圣 ， 称 义 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28479', '46', '6', '12', '＜ 在 身 子 上 荣 耀 神 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28480', '46', '6', '13', '食 物 是 为 肚 腹 ， 肚 腹 是 为 食 物 ； 但 神 要 叫 这 两 样 都 废 坏 。 身 子 不 是 为 淫 乱 ， 乃 是 为 主 ； 主 也 是 为 身 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28481', '46', '6', '14', '并 且 神 已 经 叫 主 复 活 ， 也 要 用 自 己 的 能 力 叫 我 们 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28482', '46', '6', '15', '岂 不 知 你 们 的 身 子 是 基 督 的 肢 体 吗 ？ 我 可 以 将 基 督 的 肢 体 作 为 娼 妓 的 肢 体 吗 ？ 断 乎 不 可 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28483', '46', '6', '16', '岂 不 知 与 娼 妓 联 合 的 ， 便 是 与 她 成 为 一 体 吗 ？ 因 为 主 说 ： “ 二 人 要 成 为 一 体 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28484', '46', '6', '17', '但 与 主 联 合 的 ， 便 是 与 主 成 为 一 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28485', '46', '6', '18', '你 们 要 逃 避 淫 行 。 人 所 犯 的 ， 无 论 什 么 罪 ， 都 在 身 子 以 外 ， 惟 有 行 淫 的 ， 是 得 罪 自 己 的 身 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28486', '46', '6', '19', '岂 不 知 你 们 的 身 子 就 是 圣 灵 的 殿 吗 ？ 这 圣 灵 是 从 神 而 来 ， 住 在 你 们 里 头 的 ； 并 且 你 们 不 是 自 己 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28487', '46', '6', '20', '因 为 你 们 是 重 价 买 来 的 。 所 以 ， 要 在 你 们 的 身 子 上 荣 耀 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28488', '46', '7', '1', '＜ 婚 姻 的 问 题 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28489', '46', '7', '2', '但 要 免 淫 乱 的 事 ， 男 子 当 各 有 自 己 的 妻 子 ； 女 子 也 当 各 有 自 己 的 丈 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28490', '46', '7', '3', '丈 夫 当 用 合 宜 之 分 待 妻 子 ； 妻 子 待 丈 夫 也 要 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28491', '46', '7', '4', '妻 子 没 有 权 柄 主 张 自 己 的 身 子 ， 乃 在 丈 夫 ； 丈 夫 也 没 有 权 柄 主 张 自 己 的 身 子 ， 乃 在 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28492', '46', '7', '5', '夫 妻 不 可 彼 此 亏 负 ， 除 非 两 相 情 愿 ， 暂 时 分 房 ， 为 要 专 心 祷 告 方 可 ； 以 后 仍 要 同 房 ， 免 得 撒 但 趁 着 你 们 情 不 自 禁 ， 引 诱 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28493', '46', '7', '6', '我 说 这 话 ， 原 是 准 你 们 的 ， 不 是 命 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28494', '46', '7', '7', '我 愿 意 众 人 像 我 一 样 ； 只 是 各 人 领 受 神 的 恩 赐 ， 一 个 是 这 样 ， 一 个 是 那 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28495', '46', '7', '8', '我 对 着 没 有 嫁 娶 的 和 寡 妇 说 ， 若 他 们 常 像 我 就 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28496', '46', '7', '9', '倘 若 自 己 禁 止 不 住 ， 就 可 以 嫁 娶 。 与 其 欲 火 攻 心 ， 倒 不 如 嫁 娶 为 妙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28497', '46', '7', '10', '至 于 那 已 经 嫁 娶 的 ， 我 吩 咐 他 们 ； 其 实 不 是 我 吩 咐 ， 乃 是 主 吩 咐 说 ： 妻 子 不 可 离 开 丈 夫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28498', '46', '7', '11', '若 是 离 开 了 ， 不 可 再 嫁 ， 或 是 仍 同 丈 夫 和 好 。 丈 夫 也 不 可 离 弃 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28499', '46', '7', '12', '我 对 其 余 的 人 说 （ 不 是 主 说 ） ： 倘 若 某 弟 兄 有 不 信 的 妻 子 ， 妻 子 也 情 愿 和 他 同 住 ， 他 就 不 要 离 弃 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28500', '46', '7', '13', '妻 子 有 不 信 的 丈 夫 ， 丈 夫 也 情 愿 和 她 同 住 ， 她 就 不 要 离 弃 丈 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28501', '46', '7', '14', '因 为 不 信 的 丈 夫 就 因 着 妻 子 成 了 圣 洁 ， 并 且 不 信 的 妻 子 就 因 着 丈 夫 ｛ 原 文 是 弟 兄 ｝ 成 了 圣 洁 。 不 然 ， 你 们 的 儿 女 就 不 洁 净 ， 但 如 今 他 们 是 圣 洁 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28502', '46', '7', '15', '倘 若 那 不 信 的 人 要 离 去 ， 就 由 他 离 去 吧 ！ 无 论 是 弟 兄 ， 是 姊 妹 ， 遇 着 这 样 的 事 都 不 必 拘 束 。 神 召 我 们 原 是 要 我 们 和 睦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28503', '46', '7', '16', '你 这 作 妻 子 的 ， 怎 么 知 道 不 能 救 你 的 丈 夫 呢 ？ 你 这 作 丈 夫 的 ， 怎 么 知 道 不 能 救 你 的 妻 子 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28504', '46', '7', '17', '＜ 照 主 分 给 各 人 的 去 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28505', '46', '7', '18', '有 人 已 受 割 礼 蒙 召 呢 ， 就 不 要 废 割 礼 ； 有 人 未 受 割 礼 蒙 召 呢 ， 就 不 要 受 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28506', '46', '7', '19', '受 割 礼 算 不 得 什 么 ， 不 受 割 礼 也 算 不 得 什 么 ， 只 要 守 神 的 诫 命 就 是 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28507', '46', '7', '20', '各 人 蒙 召 的 时 候 是 什 么 身 分 ， 仍 要 守 住 这 身 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28508', '46', '7', '21', '你 是 作 奴 隶 蒙 召 的 吗 ？ 不 要 因 此 忧 虑 ； 若 能 以 自 由 ， 就 求 自 由 更 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28509', '46', '7', '22', '因 为 作 奴 仆 蒙 召 于 主 的 ， 就 是 主 所 释 放 的 人 ； 作 自 由 之 人 蒙 召 的 ， 就 是 基 督 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28510', '46', '7', '23', '你 们 是 重 价 买 来 的 ， 不 要 作 人 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28511', '46', '7', '24', '弟 兄 们 ， 你 们 各 人 蒙 召 的 时 候 是 什 么 身 分 ， 仍 要 在 神 面 前 守 住 这 身 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28512', '46', '7', '25', '＜ 未 婚 和 寡 居 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28513', '46', '7', '26', '因 现 今 的 艰 难 ， 据 我 看 来 ， 人 不 如 守 素 安 常 才 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28514', '46', '7', '27', '你 有 妻 子 缠 着 呢 ， 就 不 要 求 脱 离 ； 你 没 有 妻 子 缠 着 呢 ， 就 不 要 求 妻 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28515', '46', '7', '28', '你 若 娶 妻 ， 并 不 是 犯 罪 ； 处 女 若 出 嫁 ， 也 不 是 犯 罪 。 然 而 这 等 人 肉 身 必 受 苦 难 ， 我 却 愿 意 你 们 免 这 苦 难 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28516', '46', '7', '29', '弟 兄 们 ， 我 对 你 们 说 ： 时 候 减 少 了 。 从 此 以 后 ， 那 有 妻 子 的 ， 要 像 没 有 妻 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28517', '46', '7', '30', '哀 哭 的 ， 要 像 不 哀 哭 ； 快 乐 的 ， 要 像 不 快 乐 ； 置 买 的 ， 要 像 无 有 所 得 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28518', '46', '7', '31', '用 世 物 的 ， 要 像 不 用 世 物 ， 因 为 这 世 界 的 样 子 将 要 过 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28519', '46', '7', '32', '我 愿 你 们 无 所 挂 虑 。 没 有 娶 妻 的 ， 是 为 主 的 事 挂 虑 ， 想 怎 样 叫 主 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28520', '46', '7', '33', '娶 了 妻 的 ， 是 为 世 上 的 事 挂 虑 ， 想 怎 样 叫 妻 子 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28521', '46', '7', '34', '妇 人 和 处 女 也 有 分 别 。 没 有 出 嫁 的 ， 是 为 主 的 事 挂 虑 ， 要 身 体 、 灵 魂 都 圣 洁 ； 已 经 出 嫁 的 ， 是 为 世 上 的 事 挂 虑 ， 想 怎 样 叫 丈 夫 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28522', '46', '7', '35', '我 说 这 话 是 为 你 们 的 益 处 ， 不 是 要 牢 笼 你 们 ， 乃 是 要 叫 你 们 行 合 宜 的 事 ， 得 以 殷 勤 服 事 主 ， 没 有 分 心 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28523', '46', '7', '36', '若 有 人 以 为 自 己 待 他 的 女 儿 不 合 宜 ， 女 儿 也 过 了 年 岁 ， 事 又 当 行 ， 他 就 可 随 意 办 理 ， 不 算 有 罪 ， 叫 二 人 成 亲 就 是 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28524', '46', '7', '37', '倘 若 人 心 里 坚 定 ， 没 有 不 得 已 的 事 ， 并 且 由 得 自 己 作 主 ， 心 里 又 决 定 了 留 下 女 儿 不 出 嫁 ， 如 此 行 也 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28525', '46', '7', '38', '这 样 看 来 ， 叫 自 己 的 女 儿 出 嫁 是 好 ， 不 叫 她 出 嫁 更 是 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28526', '46', '7', '39', '丈 夫 活 着 的 时 候 ， 妻 子 是 被 约 束 的 ； 丈 夫 若 死 了 ， 妻 子 就 可 以 自 由 ， 随 意 再 嫁 ， 只 是 要 嫁 这 在 主 里 面 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28527', '46', '7', '40', '然 而 按 我 的 意 见 ， 若 常 守 节 更 有 福 气 。 我 也 想 自 己 是 被 神 的 灵 感 动 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28528', '46', '8', '1', '＜ 祭 过 偶 像 的 食 物 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28529', '46', '8', '2', '若 有 人 以 为 自 己 知 道 什 么 ， 按 他 所 当 知 道 的 ， 他 仍 是 不 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28530', '46', '8', '3', '若 有 人 爱 神 ， 这 人 乃 是 神 所 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28531', '46', '8', '4', '论 到 吃 祭 偶 像 之 物 ， 我 们 知 道 偶 像 在 世 上 算 不 得 什 么 ， 也 知 道 神 只 有 一 位 ， 再 没 有 别 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28532', '46', '8', '5', '虽 有 称 为 神 的 ， 或 在 天 ， 或 在 地 ， 就 如 那 许 多 的 神 ， 许 多 的 主 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28533', '46', '8', '6', '然 而 我 们 只 有 一 位 神 ， 就 是 父 ─ ─ 万 物 都 本 于 他 ； 我 们 也 归 于 他 ─ ─ 并 有 一 位 主 ， 就 是 耶 稣 基 督 ─ ─ 万 物 都 是 藉 着 他 有 的 ； 我 们 也 是 藉 着 他 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28534', '46', '8', '7', '但 人 不 都 有 这 等 知 识 。 有 人 到 如 今 因 拜 惯 了 偶 像 ， 就 以 为 所 吃 的 是 祭 偶 像 之 物 。 他 们 的 良 心 既 然 软 弱 ， 也 就 污 秽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28535', '46', '8', '8', '其 实 食 物 不 能 叫 神 看 中 我 们 ， 因 为 我 们 不 吃 也 无 损 ， 吃 也 无 益 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28536', '46', '8', '9', '只 是 你 们 要 谨 慎 ， 恐 怕 你 们 这 自 由 竟 成 了 那 软 弱 人 的 绊 脚 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28537', '46', '8', '10', '若 有 人 见 你 这 有 知 识 的 ， 在 偶 像 的 庙 里 坐 席 ， 这 人 的 良 心 若 是 软 弱 ， 岂 不 放 胆 去 吃 那 祭 偶 像 之 物 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28538', '46', '8', '11', '因 此 ， 基 督 为 他 死 的 那 软 弱 弟 兄 ， 也 就 因 你 的 知 识 沉 沦 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28539', '46', '8', '12', '你 们 这 样 得 罪 弟 兄 们 ， 伤 了 他 们 软 弱 的 良 心 ， 就 是 得 罪 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28540', '46', '8', '13', '所 以 ， 食 物 若 叫 我 弟 兄 跌 倒 ， 我 就 永 远 不 吃 肉 ， 免 得 叫 我 弟 兄 跌 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28541', '46', '9', '1', '＜ 使 徒 的 权 利 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28542', '46', '9', '2', '假 若 在 别 人 ， 我 不 是 使 徒 ， 在 你 们 ， 我 总 是 使 徒 ， 因 为 你 们 在 主 里 正 是 我 作 使 徒 的 印 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28543', '46', '9', '3', '我 对 那 盘 问 我 的 人 就 是 这 样 分 诉 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28544', '46', '9', '4', '难 道 我 们 没 有 权 柄 靠 福 音 吃 喝 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28545', '46', '9', '5', '难 道 我 们 没 有 权 柄 娶 信 主 的 姊 妹 为 妻 ， 带 着 一 同 往 来 ， 仿 佛 其 余 的 使 徒 和 主 的 弟 兄 并 矶 法 一 样 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28546', '46', '9', '6', '独 有 我 与 巴 拿 巴 没 有 权 柄 不 做 工 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28547', '46', '9', '7', '有 谁 当 兵 自 备 粮 饷 呢 ？ 有 谁 栽 葡 萄 园 不 吃 园 里 的 果 子 呢 ？ 有 谁 牧 养 牛 羊 不 吃 牛 羊 的 奶 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28548', '46', '9', '8', '我 说 这 话 ， 岂 是 照 人 的 意 见 ； 律 法 不 也 是 这 样 说 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28549', '46', '9', '9', '就 如 摩 西 的 律 法 记 着 说 ： “ 牛 在 场 上 踹 谷 的 时 候 ， 不 可 笼 住 它 的 嘴 。 ” 难 道 神 所 挂 念 的 是 牛 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28550', '46', '9', '10', '不 全 是 为 我 们 说 的 吗 ？ 分 明 是 为 我 们 说 的 。 因 为 耕 种 的 当 存 着 指 望 去 耕 种 ； 打 场 的 也 当 存 得 粮 的 指 望 去 打 场 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28551', '46', '9', '11', '我 们 若 把 属 灵 的 种 子 撒 在 你 们 中 间 ， 就 是 从 你 们 收 割 奉 养 肉 身 之 物 ， 这 还 算 大 事 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28552', '46', '9', '12', '若 别 人 在 你 们 身 上 有 这 权 柄 ， 何 况 我 们 呢 ？ 然 而 ， 我 们 没 有 用 过 这 权 柄 ， 倒 凡 事 忍 受 ， 免 得 基 督 的 福 音 被 阻 隔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28553', '46', '9', '13', '你 们 岂 不 知 为 圣 事 劳 碌 的 就 吃 殿 中 的 物 吗 ？ 伺 候 祭 坛 的 就 分 领 坛 上 的 物 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28554', '46', '9', '14', '主 也 是 这 样 命 定 ， 叫 传 福 音 的 靠 着 福 音 养 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28555', '46', '9', '15', '但 这 权 柄 我 全 没 有 用 过 。 我 写 这 话 ， 并 非 要 你 们 这 样 待 我 ， 因 为 我 宁 可 死 也 不 叫 人 使 我 所 夸 的 落 了 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28556', '46', '9', '16', '我 传 福 音 原 没 有 可 夸 的 ， 因 为 我 是 不 得 已 的 。 若 不 传 福 音 ， 我 便 有 祸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28557', '46', '9', '17', '我 若 甘 心 做 这 事 ， 就 有 赏 赐 ； 若 不 甘 心 ， 责 任 却 已 经 托 付 我 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28558', '46', '9', '18', '既 是 这 样 ， 我 的 赏 赐 是 什 么 呢 ？ 就 是 我 传 福 音 的 时 候 叫 人 不 花 钱 得 福 音 ， 免 得 用 尽 我 传 福 音 的 权 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28559', '46', '9', '19', '我 虽 是 自 由 的 ， 无 人 辖 管 ； 然 而 我 甘 心 作 了 众 人 的 仆 人 ， 为 要 多 得 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28560', '46', '9', '20', '向 犹 太 人 ， 我 就 作 犹 太 人 ， 为 要 得 犹 太 人 ； 向 律 法 以 下 的 人 ， 我 虽 不 在 律 法 以 下 ， 还 是 作 律 法 以 下 的 人 ， 为 要 得 律 法 以 下 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28561', '46', '9', '21', '向 没 有 律 法 的 人 ， 我 就 作 没 有 律 法 的 人 ， 为 要 得 没 有 律 法 的 人 ； 其 实 我 在 神 面 前 ， 不 是 没 有 律 法 ； 在 基 督 面 前 ， 正 在 律 法 之 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28562', '46', '9', '22', '向 软 弱 的 人 ， 我 就 作 软 弱 的 人 ， 为 要 得 软 弱 的 人 。 向 什 么 样 的 人 ， 我 就 作 什 么 样 的 人 。 无 论 如 何 ， 总 要 救 些 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28563', '46', '9', '23', '凡 我 所 行 的 ， 都 是 为 福 音 的 缘 故 ， 为 要 与 人 同 得 这 福 音 的 好 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28564', '46', '9', '24', '岂 不 知 在 场 上 赛 跑 的 都 跑 ， 但 得 奖 赏 的 只 有 一 人 ？ 你 们 也 当 这 样 跑 ， 好 叫 你 们 得 着 奖 赏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28565', '46', '9', '25', '凡 较 力 争 胜 的 ， 诸 事 都 有 节 制 ， 他 们 不 过 是 要 得 能 坏 的 冠 冕 ； 我 们 却 是 要 得 不 能 坏 的 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28566', '46', '9', '26', '所 以 ， 我 奔 跑 不 像 无 定 向 的 ； 我 斗 拳 不 像 打 空 气 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28567', '46', '9', '27', '我 是 攻 克 己 身 ， 叫 身 服 我 ， 恐 怕 我 传 福 音 给 别 人 ， 自 己 反 被 弃 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28568', '46', '10', '1', '＜ 警 戒 拜 偶 像 的 事 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28569', '46', '10', '2', '都 在 云 里 、 海 里 受 洗 归 了 摩 西 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28570', '46', '10', '3', '并 且 都 吃 了 一 样 的 灵 食 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28571', '46', '10', '4', '也 都 喝 了 一 样 的 灵 水 。 所 喝 的 ， 是 出 于 随 着 他 们 的 灵 磐 石 ； 那 磐 石 就 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28572', '46', '10', '5', '但 他 们 中 间 多 半 是 神 不 喜 欢 的 人 ， 所 以 在 旷 野 倒 毙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28573', '46', '10', '6', '这 些 事 都 是 我 们 的 鉴 戒 ， 叫 我 们 不 要 贪 恋 恶 事 ， 像 他 们 那 样 贪 恋 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28574', '46', '10', '7', '也 不 要 拜 偶 像 ， 像 他 们 有 人 拜 的 。 如 经 上 所 记 ： “ 百 姓 坐 下 吃 喝 ， 起 来 玩 耍 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28575', '46', '10', '8', '我 们 也 不 要 行 奸 淫 ， 像 他 们 有 人 行 的 ， 一 天 就 倒 毙 了 二 万 三 千 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28576', '46', '10', '9', '也 不 要 试 探 主 ｛ 有 古 卷 ： 基 督 ｝ ， 像 他 们 有 人 试 探 的 ， 就 被 蛇 所 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28577', '46', '10', '10', '你 们 也 不 要 发 怨 言 ， 像 他 们 有 发 怨 言 的 ， 就 被 灭 命 的 所 灭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28578', '46', '10', '11', '他 们 遭 遇 这 些 事 都 要 作 为 鉴 戒 ， 并 且 写 在 经 上 ， 正 是 警 戒 我 们 这 末 世 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28579', '46', '10', '12', '所 以 ， 自 己 以 为 站 得 稳 的 ， 须 要 谨 慎 ， 免 得 跌 倒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28580', '46', '10', '13', '你 们 所 遇 见 的 试 探 ， 无 非 是 人 所 能 受 的 。 神 是 信 实 的 ， 必 不 叫 你 们 受 试 探 过 于 所 能 受 的 ； 在 受 试 探 的 时 候 ， 总 要 给 你 们 开 一 条 出 路 ， 叫 你 们 能 忍 受 得 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28581', '46', '10', '14', '我 所 亲 爱 的 弟 兄 啊 ， 你 们 要 逃 避 拜 偶 像 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28582', '46', '10', '15', '我 好 像 对 明 白 人 说 的 ， 你 们 要 审 察 我 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28583', '46', '10', '16', '我 们 所 祝 福 的 杯 ， 岂 不 是 同 领 基 督 的 血 吗 ？ 我 们 所 擘 开 的 饼 ， 岂 不 是 同 领 基 督 的 身 体 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28584', '46', '10', '17', '我 们 虽 多 ， 仍 是 一 个 饼 ， 一 个 身 体 ， 因 为 我 们 都 是 分 受 这 一 个 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28585', '46', '10', '18', '你 们 看 属 肉 体 的 以 色 列 人 ， 那 吃 祭 物 的 岂 不 是 在 祭 坛 上 有 分 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28586', '46', '10', '19', '我 是 怎 么 说 呢 ？ 岂 是 说 祭 偶 像 之 物 算 得 什 么 呢 ？ 或 说 偶 像 算 得 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28587', '46', '10', '20', '我 乃 是 说 ， 外 邦 人 所 献 的 祭 是 祭 鬼 ， 不 是 祭 神 。 我 不 愿 意 你 们 与 鬼 相 交 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28588', '46', '10', '21', '你 们 不 能 喝 主 的 杯 又 喝 鬼 的 杯 ， 不 能 吃 主 的 筵 席 又 吃 鬼 的 筵 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28589', '46', '10', '22', '我 们 可 惹 主 的 愤 恨 吗 ？ 我 们 比 他 还 有 能 力 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28590', '46', '10', '23', '＜ 凡 事 为 荣 耀 神 而 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28591', '46', '10', '24', '无 论 何 人 ， 不 要 求 自 己 的 益 处 ， 乃 要 求 别 人 的 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28592', '46', '10', '25', '凡 市 上 所 卖 的 ， 你 们 只 管 吃 ， 不 要 为 良 心 的 缘 故 问 什 么 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28593', '46', '10', '26', '因 为 地 和 其 中 所 充 满 的 都 属 乎 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28594', '46', '10', '27', '倘 有 一 个 不 信 的 人 请 你 们 赴 席 ， 你 们 若 愿 意 去 ， 凡 摆 在 你 们 面 前 的 ， 只 管 吃 ， 不 要 为 良 心 的 缘 故 问 什 么 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28595', '46', '10', '28', '若 有 人 对 你 们 说 ： “ 这 是 献 过 祭 的 物 ” ， 就 要 为 那 告 诉 你 们 的 人 ， 并 为 良 心 的 缘 故 不 吃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28596', '46', '10', '29', '我 说 的 良 心 不 是 你 的 ， 乃 是 他 的 。 我 这 自 由 为 什 么 被 别 人 的 良 心 论 断 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28597', '46', '10', '30', '我 若 谢 恩 而 吃 ， 为 什 么 因 我 谢 恩 的 物 被 人 毁 谤 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28598', '46', '10', '31', '所 以 ， 你 们 或 吃 或 喝 ， 无 论 做 什 么 ， 都 要 为 荣 耀 神 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28599', '46', '10', '32', '不 拘 是 犹 太 人 ， 是 希 腊 人 ， 是 神 的 教 会 ， 你 们 都 不 要 使 他 跌 倒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28600', '46', '10', '33', '就 好 像 我 凡 事 都 叫 众 人 喜 欢 ， 不 求 自 己 的 益 处 ， 只 求 众 人 的 益 处 ， 叫 他 们 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28601', '46', '11', '1', '你 们 该 效 法 我 ， 像 我 效 法 基 督 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28602', '46', '11', '2', '＜ 礼 拜 时 蒙 头 的 问 题 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28603', '46', '11', '3', '我 愿 意 你 们 知 道 ， 基 督 是 各 人 的 头 ； 男 人 是 女 人 的 头 ； 神 是 基 督 的 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28604', '46', '11', '4', '凡 男 人 祷 告 或 是 讲 道 ｛ 或 译 ： 说 预 言 ； 下 同 ｝ ， 若 蒙 着 头 ， 就 羞 辱 自 己 的 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28605', '46', '11', '5', '凡 女 人 祷 告 或 是 讲 道 ， 若 不 蒙 着 头 ， 就 羞 辱 自 己 的 头 ， 因 为 这 就 如 同 剃 了 头 发 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28606', '46', '11', '6', '女 人 若 不 蒙 着 头 ， 就 该 剪 了 头 发 ； 女 人 若 以 剪 发 、 剃 发 为 羞 愧 ， 就 该 蒙 着 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28607', '46', '11', '7', '男 人 本 不 该 蒙 着 头 ， 因 为 他 是 神 的 形 像 和 荣 耀 ； 但 女 人 是 男 人 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28608', '46', '11', '8', '起 初 ， 男 人 不 是 由 女 人 而 出 ， 女 人 乃 是 由 男 人 而 出 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28609', '46', '11', '9', '并 且 男 人 不 是 为 女 人 造 的 ， 女 人 乃 是 为 男 人 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28610', '46', '11', '10', '因 此 ， 女 人 为 天 使 的 缘 故 ， 应 当 在 头 上 有 服 权 柄 的 记 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28611', '46', '11', '11', '然 而 照 主 的 安 排 ， 女 也 不 是 无 男 ， 男 也 不 是 无 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28612', '46', '11', '12', '因 为 女 人 原 是 由 男 人 而 出 ， 男 人 也 是 由 女 人 而 出 ； 但 万 有 都 是 出 乎 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28613', '46', '11', '13', '你 们 自 己 审 察 ， 女 人 祷 告 神 ， 不 蒙 着 头 是 合 宜 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28614', '46', '11', '14', '你 们 的 本 性 不 也 指 示 你 们 ， 男 人 若 有 长 头 发 ， 便 是 他 的 羞 辱 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28615', '46', '11', '15', '但 女 人 有 长 头 发 ， 乃 是 她 的 荣 耀 ， 因 为 这 头 发 是 给 她 作 盖 头 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28616', '46', '11', '16', '若 有 人 想 要 辩 驳 ， 我 们 却 没 有 这 样 的 规 矩 ， 神 的 众 教 会 也 是 没 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28617', '46', '11', '17', '＜ 圣 餐 时 的 混 乱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28618', '46', '11', '18', '第 一 ， 我 听 说 ， 你 们 聚 会 的 时 候 彼 此 分 门 别 类 ， 我 也 稍 微 地 信 这 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28619', '46', '11', '19', '在 你 们 中 间 不 免 有 分 门 结 党 的 事 ， 好 叫 那 些 有 经 验 的 人 显 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28620', '46', '11', '20', '你 们 聚 会 的 时 候 ， 算 不 得 吃 主 的 晚 餐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28621', '46', '11', '21', '因 为 吃 的 时 候 ， 各 人 先 吃 自 己 的 饭 ， 甚 至 这 个 饥 饿 ， 那 个 酒 醉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28622', '46', '11', '22', '你 们 要 吃 喝 ， 难 道 没 有 家 吗 ？ 还 是 藐 视 神 的 教 会 ， 叫 那 没 有 的 羞 愧 呢 ？ 我 向 你 们 可 怎 么 说 呢 ？ 可 因 此 称 赞 你 们 吗 ？ 我 不 称 赞 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28623', '46', '11', '23', '＜ 圣 餐 的 设 立 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28624', '46', '11', '24', '祝 谢 了 ， 就 擘 开 ， 说 ： “ 这 是 我 的 身 体 ， 为 你 们 舍 ｛ 有 古 卷 ： 擘 开 ｝ 的 ， 你 们 应 当 如 此 行 ， 为 的 是 记 念 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28625', '46', '11', '25', '饭 后 ， 也 照 样 拿 起 杯 来 ， 说 ： “ 这 杯 是 用 我 的 血 所 立 的 新 约 ， 你 们 每 逢 喝 的 时 候 ， 要 如 此 行 ， 为 的 是 记 念 我 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28626', '46', '11', '26', '你 们 每 逢 吃 这 饼 ， 喝 这 杯 ， 是 表 明 主 的 死 ， 直 等 到 他 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28627', '46', '11', '27', '＜ 不 按 理 吃 主 的 晚 餐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28628', '46', '11', '28', '人 应 当 自 己 省 察 ， 然 后 吃 这 饼 、 喝 这 杯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28629', '46', '11', '29', '因 为 人 吃 喝 ， 若 不 分 辨 是 主 的 身 体 ， 就 是 吃 喝 自 己 的 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28630', '46', '11', '30', '因 此 ， 在 你 们 中 间 有 好 些 软 弱 的 与 患 病 的 ， 死 ｛ 原 文 是 睡 ｝ 的 也 不 少 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28631', '46', '11', '31', '我 们 若 是 先 分 辨 自 己 ， 就 不 至 于 受 审 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28632', '46', '11', '32', '我 们 受 审 的 时 候 ， 乃 是 被 主 惩 治 ， 免 得 我 们 和 世 人 一 同 定 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28633', '46', '11', '33', '所 以 我 弟 兄 们 ， 你 们 聚 会 吃 的 时 候 ， 要 彼 此 等 待 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28634', '46', '11', '34', '若 有 人 饥 饿 ， 可 以 在 家 里 先 吃 ， 免 得 你 们 聚 会 ， 自 己 取 罪 。 其 余 的 事 ， 我 来 的 时 候 再 安 排 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28635', '46', '12', '1', '＜ 属 灵 的 恩 赐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28636', '46', '12', '2', '你 们 作 外 邦 人 的 时 候 ， 随 事 被 牵 引 ， 受 迷 惑 ， 去 服 事 那 哑 巴 偶 像 ， 这 是 你 们 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28637', '46', '12', '3', '所 以 我 告 诉 你 们 ， 被 神 的 灵 感 动 的 ， 没 有 说 “ 耶 稣 是 可 咒 诅 ” 的 ； 若 不 是 被 圣 灵 感 动 的 ， 也 没 有 能 说 “ 耶 稣 是 主 ” 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28638', '46', '12', '4', '恩 赐 原 有 分 别 ， 圣 灵 却 是 一 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28639', '46', '12', '5', '职 事 也 有 分 别 ， 主 却 是 一 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28640', '46', '12', '6', '功 用 也 有 分 别 ， 神 却 是 一 位 ， 在 众 人 里 面 运 行 一 切 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28641', '46', '12', '7', '圣 灵 显 在 各 人 身 上 ， 是 叫 人 得 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28642', '46', '12', '8', '这 人 蒙 圣 灵 赐 他 智 慧 的 言 语 ， 那 人 也 蒙 这 位 圣 灵 赐 他 知 识 的 言 语 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28643', '46', '12', '9', '又 有 一 人 蒙 这 位 圣 灵 赐 他 信 心 ， 还 有 一 人 蒙 这 位 圣 灵 赐 他 医 病 的 恩 赐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28644', '46', '12', '10', '又 叫 一 人 能 行 异 能 ， 又 叫 一 人 能 作 先 知 ， 又 叫 一 人 能 辨 别 诸 灵 ， 又 叫 一 人 能 说 方 言 ， 又 叫 一 人 能 翻 方 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28645', '46', '12', '11', '这 一 切 都 是 这 位 圣 灵 所 运 行 、 随 己 意 分 给 各 人 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28646', '46', '12', '12', '＜ 一 个 身 体 有 许 多 肢 体 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28647', '46', '12', '13', '我 们 不 拘 是 犹 太 人 ， 是 希 腊 人 ， 是 为 奴 的 ， 是 自 主 的 ， 都 从 一 位 圣 灵 受 洗 ， 成 了 一 个 身 体 ， 饮 于 一 位 圣 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28648', '46', '12', '14', '身 子 原 不 是 一 个 肢 体 ， 乃 是 许 多 肢 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28649', '46', '12', '15', '设 若 脚 说 ： “ 我 不 是 手 ， 所 以 不 属 乎 身 子 ； ” 它 不 能 因 此 就 不 属 乎 身 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28650', '46', '12', '16', '设 若 耳 说 ： “ 我 不 是 眼 ， 所 以 不 属 乎 身 子 ； ” 它 不 能 因 此 就 不 属 乎 身 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28651', '46', '12', '17', '若 全 身 是 眼 ， 从 哪 里 听 声 呢 ？ 若 全 身 是 耳 ， 从 哪 里 闻 味 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28652', '46', '12', '18', '但 如 今 ， 神 随 自 己 的 意 思 把 肢 体 俱 各 安 排 在 身 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28653', '46', '12', '19', '若 都 是 一 个 肢 体 ， 身 子 在 哪 里 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28654', '46', '12', '20', '但 如 今 肢 体 是 多 的 ， 身 子 却 是 一 个 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28655', '46', '12', '21', '眼 不 能 对 手 说 ： “ 我 用 不 着 你 ； ” 头 也 不 能 对 脚 说 ： “ 我 用 不 着 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28656', '46', '12', '22', '不 但 如 此 ， 身 上 肢 体 人 以 为 软 弱 的 ， 更 是 不 可 少 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28657', '46', '12', '23', '身 上 肢 体 ， 我 们 看 为 不 体 面 的 ， 越 发 给 它 加 上 体 面 ； 不 俊 美 的 ， 越 发 得 着 俊 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28658', '46', '12', '24', '我 们 俊 美 的 肢 体 ， 自 然 用 不 着 装 饰 ； 但 神 配 搭 这 身 子 ， 把 加 倍 的 体 面 给 那 有 缺 欠 的 肢 体 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28659', '46', '12', '25', '免 得 身 上 分 门 别 类 ， 总 要 肢 体 彼 此 相 顾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28660', '46', '12', '26', '若 一 个 肢 体 受 苦 ， 所 有 的 肢 体 就 一 同 受 苦 ； 若 一 个 肢 体 得 荣 耀 ， 所 有 的 肢 体 就 一 同 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28661', '46', '12', '27', '你 们 就 是 基 督 的 身 子 ， 并 且 各 自 作 肢 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28662', '46', '12', '28', '神 在 教 会 所 设 立 的 ： 第 一 是 使 徒 ， 第 二 是 先 知 ， 第 三 是 教 师 ， 其 次 是 行 异 能 的 ， 再 次 是 得 恩 赐 医 病 的 ， 帮 助 人 的 ， 治 理 事 的 ， 说 方 言 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28663', '46', '12', '29', '岂 都 是 使 徒 吗 ？ 岂 都 是 先 知 吗 ？ 岂 都 是 教 师 吗 ？ 岂 都 是 行 异 能 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28664', '46', '12', '30', '岂 都 是 得 恩 赐 医 病 的 吗 ？ 岂 都 是 说 方 言 的 吗 ？ 岂 都 是 翻 方 言 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28665', '46', '12', '31', '你 们 要 切 切 地 求 那 更 大 的 恩 赐 。 我 现 今 把 最 妙 的 道 指 示 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28666', '46', '13', '1', '＜ 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28667', '46', '13', '2', '我 若 有 先 知 讲 道 之 能 ， 也 明 白 各 样 的 奥 秘 ， 各 样 的 知 识 ， 而 且 有 全 备 的 信 ， 叫 我 能 够 移 山 ， 却 没 有 爱 ， 我 就 算 不 得 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28668', '46', '13', '3', '我 若 将 所 有 的 赒 济 穷 人 ， 又 舍 己 身 叫 人 焚 烧 ， 却 没 有 爱 ， 仍 然 与 我 无 益 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28669', '46', '13', '4', '爱 是 恒 久 忍 耐 ， 又 有 恩 慈 ； 爱 是 不 嫉 妒 ； 爱 是 不 自 夸 ， 不 张 狂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28670', '46', '13', '5', '不 做 害 羞 的 事 ， 不 求 自 己 的 益 处 ， 不 轻 易 发 怒 ， 不 计 算 人 的 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28671', '46', '13', '6', '不 喜 欢 不 义 ， 只 喜 欢 真 理 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28672', '46', '13', '7', '凡 事 包 容 ， 凡 事 相 信 ， 凡 事 盼 望 ， 凡 事 忍 耐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28673', '46', '13', '8', '爱 是 永 不 止 息 。 先 知 讲 道 之 能 终 必 归 于 无 有 ； 说 方 言 之 能 终 必 停 止 ； 知 识 也 终 必 归 于 无 有 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28674', '46', '13', '9', '我 们 现 在 所 知 道 的 有 限 ， 先 知 所 讲 的 也 有 限 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28675', '46', '13', '10', '等 那 完 全 的 来 到 ， 这 有 限 的 必 归 于 无 有 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28676', '46', '13', '11', '我 作 孩 子 的 时 候 ， 话 语 像 孩 子 ， 心 思 像 孩 子 ， 意 念 像 孩 子 ， 既 成 了 人 ， 就 把 孩 子 的 事 丢 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28677', '46', '13', '12', '我 们 如 今 仿 佛 对 着 镜 子 观 看 ， 模 糊 不 清 ｛ 原 文 是 如 同 猜 谜 ｝ ， 到 那 时 就 要 面 对 面 了 。 我 如 今 所 知 道 的 有 限 ， 到 那 时 就 全 知 道 ， 如 同 主 知 道 我 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28678', '46', '13', '13', '如 今 常 存 的 有 信 ， 有 望 ， 有 爱 这 三 样 ， 其 中 最 大 的 是 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28679', '46', '14', '1', '＜ 说 方 言 和 作 先 知 讲 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28680', '46', '14', '2', '那 说 方 言 的 ， 原 不 是 对 人 说 ， 乃 是 对 神 说 ， 因 为 没 有 人 听 出 来 。 然 而 ， 他 在 心 灵 里 却 是 讲 说 各 样 的 奥 秘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28681', '46', '14', '3', '但 作 先 知 讲 道 的 ， 是 对 人 说 ， 要 造 就 、 安 慰 、 劝 勉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28682', '46', '14', '4', '说 方 言 的 ， 是 造 就 自 己 ； 作 先 知 讲 道 的 ， 乃 是 造 就 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28683', '46', '14', '5', '我 愿 意 你 们 都 说 方 言 ， 更 愿 意 你 们 作 先 知 讲 道 ； 因 为 说 方 言 的 ， 若 不 翻 出 来 ， 使 教 会 被 造 就 ， 那 作 先 知 讲 道 的 ， 就 比 他 强 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28684', '46', '14', '6', '弟 兄 们 ， 我 到 你 们 那 里 去 ， 若 只 说 方 言 ， 不 用 启 示 ， 或 知 识 ， 或 预 言 ， 或 教 训 ， 给 你 们 讲 解 ， 我 与 你 们 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28685', '46', '14', '7', '就 是 那 有 声 无 气 的 物 ， 或 箫 ， 或 琴 ， 若 发 出 来 的 声 音 没 有 分 别 ， 怎 能 知 道 所 吹 所 弹 的 是 什 么 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28686', '46', '14', '8', '若 吹 无 定 的 号 声 ， 谁 能 预 备 打 仗 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28687', '46', '14', '9', '你 们 也 是 如 此 。 舌 头 若 不 说 容 易 明 白 的 话 ， 怎 能 知 道 所 说 的 是 什 么 呢 ？ 这 就 是 向 空 说 话 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28688', '46', '14', '10', '世 上 的 声 音 ， 或 者 甚 多 ， 却 没 有 一 样 是 无 意 思 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28689', '46', '14', '11', '我 若 不 明 白 那 声 音 的 意 思 ， 这 说 话 的 人 必 以 我 为 化 外 之 人 ， 我 也 以 他 为 化 外 之 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28690', '46', '14', '12', '你 们 也 是 如 此 ， 既 是 切 慕 属 灵 的 恩 赐 ， 就 当 求 多 得 造 就 教 会 的 恩 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28691', '46', '14', '13', '所 以 那 说 方 言 的 ， 就 当 求 着 能 翻 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28692', '46', '14', '14', '我 若 用 方 言 祷 告 ， 是 我 的 灵 祷 告 ， 但 我 的 悟 性 没 有 果 效 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28693', '46', '14', '15', '这 却 怎 么 样 呢 ？ 我 要 用 灵 祷 告 ， 也 要 用 悟 性 祷 告 ； 我 要 用 灵 歌 唱 ， 也 要 用 悟 性 歌 唱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28694', '46', '14', '16', '不 然 ， 你 用 灵 祝 谢 ， 那 在 座 不 通 方 言 的 人 ， 既 然 不 明 白 你 的 话 ， 怎 能 在 你 感 谢 的 时 候 说 “ 阿 们 ” 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28695', '46', '14', '17', '你 感 谢 的 固 然 是 好 ， 无 奈 不 能 造 就 别 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28696', '46', '14', '18', '我 感 谢 神 ， 我 说 方 言 比 你 们 众 人 还 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28697', '46', '14', '19', '但 在 教 会 中 ， 宁 可 用 悟 性 说 五 句 教 导 人 的 话 ， 强 如 说 万 句 方 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28698', '46', '14', '20', '弟 兄 们 ， 在 心 志 上 不 要 作 小 孩 子 。 然 而 ， 在 恶 事 上 要 作 婴 孩 ， 在 心 志 上 总 要 作 大 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28699', '46', '14', '21', '律 法 上 记 着 ： 主 说 ： 我 要 用 外 邦 人 的 舌 头 和 外 邦 人 的 嘴 唇 向 这 百 姓 说 话 ； 虽 然 如 此 ， 他 们 还 是 不 听 从 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28700', '46', '14', '22', '这 样 看 来 ， 说 方 言 不 是 为 信 的 人 作 证 据 ， 乃 是 为 不 信 的 人 ； 作 先 知 讲 道 不 是 为 不 信 的 人 作 证 据 ， 乃 是 为 信 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28701', '46', '14', '23', '所 以 ， 全 教 会 聚 在 一 处 的 时 候 ， 若 都 说 方 言 ， 偶 然 有 不 通 方 言 的 ， 或 是 不 信 的 人 进 来 ， 岂 不 说 你 们 癫 狂 了 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28702', '46', '14', '24', '若 都 作 先 知 讲 道 ， 偶 然 有 不 信 的 ， 或 是 不 通 方 言 的 人 进 来 ， 就 被 众 人 劝 醒 ， 被 众 人 审 明 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28703', '46', '14', '25', '他 心 里 的 隐 情 显 露 出 来 ， 就 必 将 脸 伏 地 ， 敬 拜 神 ， 说 ： “ 神 真 是 在 你 们 中 间 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28704', '46', '14', '26', '＜ 凡 事 都 要 按 次 序 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28705', '46', '14', '27', '若 有 说 方 言 的 ， 只 好 两 个 人 ， 至 多 三 个 人 ， 且 要 轮 流 着 说 ， 也 要 一 个 人 翻 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28706', '46', '14', '28', '若 没 有 人 翻 ， 就 当 在 会 中 闭 口 ， 只 对 自 己 和 神 说 就 是 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28707', '46', '14', '29', '至 于 作 先 知 讲 道 的 ， 只 好 两 个 人 或 是 三 个 人 ， 其 余 的 就 当 慎 思 明 辨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28708', '46', '14', '30', '若 旁 边 坐 着 的 得 了 启 示 ， 那 先 说 话 的 就 当 闭 口 不 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28709', '46', '14', '31', '因 为 你 们 都 可 以 一 个 一 个 地 作 先 知 讲 道 ， 叫 众 人 学 道 理 ， 叫 众 人 得 劝 勉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28710', '46', '14', '32', '先 知 的 灵 原 是 顺 服 先 知 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28711', '46', '14', '33', '因 为 神 不 是 叫 人 混 乱 ， 乃 是 叫 人 安 静 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28712', '46', '14', '34', '妇 女 在 会 中 要 闭 口 不 言 ， 像 在 圣 徒 的 众 教 会 一 样 ， 因 为 不 准 她 们 说 话 。 她 们 总 要 顺 服 ， 正 如 律 法 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28713', '46', '14', '35', '她 们 若 要 学 什 么 ， 可 以 在 家 里 问 自 己 的 丈 夫 ， 因 为 妇 女 在 会 中 说 话 原 是 可 耻 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28714', '46', '14', '36', '神 的 道 理 岂 是 从 你 们 出 来 吗 ？ 岂 是 单 临 到 你 们 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28715', '46', '14', '37', '若 有 人 以 为 自 己 是 先 知 ， 或 是 属 灵 的 ， 就 该 知 道 ， 我 所 写 给 你 们 的 是 主 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28716', '46', '14', '38', '若 有 不 知 道 的 ， 就 由 他 不 知 道 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28717', '46', '14', '39', '所 以 我 弟 兄 们 ， 你 们 要 切 慕 作 先 知 讲 道 ， 也 不 要 禁 止 说 方 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28718', '46', '14', '40', '凡 事 都 要 规 规 矩 矩 地 按 着 次 序 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28719', '46', '15', '1', '＜ 基 督 的 复 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28720', '46', '15', '2', '并 且 你 们 若 不 是 徒 然 相 信 ， 能 以 持 守 我 所 传 给 你 们 的 ， 就 必 因 这 福 音 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28721', '46', '15', '3', '我 当 日 所 领 受 又 传 给 你 们 的 ： 第 一 ， 就 是 基 督 照 圣 经 所 说 ， 为 我 们 的 罪 死 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28722', '46', '15', '4', '而 且 埋 葬 了 ； 又 照 圣 经 所 说 ， 第 三 天 复 活 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28723', '46', '15', '5', '并 且 显 给 矶 法 看 ， 然 后 显 给 十 二 使 徒 看 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28724', '46', '15', '6', '后 来 一 时 显 给 五 百 多 弟 兄 看 ， 其 中 一 大 半 到 如 今 还 在 ， 却 也 有 已 经 睡 了 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28725', '46', '15', '7', '以 后 显 给 雅 各 看 ， 再 显 给 众 使 徒 看 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28726', '46', '15', '8', '末 了 也 显 给 我 看 ； 我 如 同 未 到 产 期 而 生 的 人 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28727', '46', '15', '9', '我 原 是 使 徒 中 最 小 的 ， 不 配 称 为 使 徒 ， 因 为 我 从 前 逼 迫 神 的 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28728', '46', '15', '10', '然 而 ， 我 今 日 成 了 何 等 人 ， 是 蒙 神 的 恩 才 成 的 ， 并 且 他 所 赐 我 的 恩 不 是 徒 然 的 。 我 比 众 使 徒 格 外 劳 苦 ； 这 原 不 是 我 ， 乃 是 神 的 恩 与 我 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28729', '46', '15', '11', '不 拘 是 我 ， 是 众 使 徒 ， 我 们 如 此 传 ， 你 们 也 如 此 信 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28730', '46', '15', '12', '＜ 死 人 的 复 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28731', '46', '15', '13', '若 没 有 死 人 复 活 的 事 ， 基 督 也 就 没 有 复 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28732', '46', '15', '14', '若 基 督 没 有 复 活 ， 我 们 所 传 的 便 是 枉 然 ， 你 们 所 信 的 也 是 枉 然 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28733', '46', '15', '15', '并 且 明 显 我 们 是 为 神 妄 作 见 证 的 ， 因 我 们 见 证 神 是 叫 基 督 复 活 了 。 若 死 人 真 不 复 活 ， 神 也 就 没 有 叫 基 督 复 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28734', '46', '15', '16', '因 为 死 人 若 不 复 活 ， 基 督 也 就 没 有 复 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28735', '46', '15', '17', '基 督 若 没 有 复 活 ， 你 们 的 信 便 是 徒 然 ， 你 们 仍 在 罪 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28736', '46', '15', '18', '就 是 在 基 督 里 睡 了 的 人 也 灭 亡 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28737', '46', '15', '19', '我 们 若 靠 基 督 只 在 今 生 有 指 望 ， 就 算 比 众 人 更 可 怜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28738', '46', '15', '20', '但 基 督 已 经 从 死 里 复 活 ， 成 为 睡 了 之 人 初 熟 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28739', '46', '15', '21', '死 既 是 因 一 人 而 来 ， 死 人 复 活 也 是 因 一 人 而 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28740', '46', '15', '22', '在 亚 当 里 众 人 都 死 了 ； 照 样 ， 在 基 督 里 众 人 也 都 要 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28741', '46', '15', '23', '但 各 人 是 按 着 自 己 的 次 序 复 活 ： 初 熟 的 果 子 是 基 督 ； 以 后 ， 在 他 来 的 时 候 ， 是 那 些 属 基 督 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28742', '46', '15', '24', '再 后 ， 末 期 到 了 ， 那 时 基 督 既 将 一 切 执 政 的 、 掌 权 的 、 有 能 的 都 毁 灭 了 ， 就 把 国 交 与 父 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28743', '46', '15', '25', '因 为 基 督 必 要 作 王 ， 等 神 把 一 切 仇 敌 都 放 在 他 的 脚 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28744', '46', '15', '26', '尽 末 了 所 毁 灭 的 仇 敌 就 是 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28745', '46', '15', '27', '因 为 经 上 说 ： “ 神 叫 万 物 都 服 在 他 的 脚 下 。 ” 既 说 万 物 都 服 了 他 ， 明 显 那 叫 万 物 服 他 的 ， 不 在 其 内 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28746', '46', '15', '28', '万 物 既 服 了 他 ， 那 时 子 也 要 自 己 服 那 叫 万 物 服 他 的 ， 叫 神 在 万 物 之 上 ， 为 万 物 之 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28747', '46', '15', '29', '不 然 ， 那 些 为 死 人 受 洗 的 ， 将 来 怎 样 呢 ？ 若 死 人 总 不 复 活 ， 因 何 为 他 们 受 洗 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28748', '46', '15', '30', '我 们 又 因 何 时 刻 冒 险 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28749', '46', '15', '31', '弟 兄 们 ， 我 在 我 主 基 督 耶 稣 里 ， 指 着 你 们 所 夸 的 口 极 力 地 说 ， 我 是 天 天 冒 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28750', '46', '15', '32', '我 若 当 日 像 寻 常 人 ， 在 以 弗 所 同 野 兽 战 斗 ， 那 于 我 有 什 么 益 处 呢 ？ 若 死 人 不 复 活 ， 我 们 就 吃 吃 喝 喝 吧 ！ 因 为 明 天 要 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28751', '46', '15', '33', '你 们 不 要 自 欺 ； 滥 交 是 败 坏 善 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28752', '46', '15', '34', '你 们 要 醒 悟 为 善 ， 不 要 犯 罪 ， 因 为 有 人 不 认 识 神 。 我 说 这 话 是 要 叫 你 们 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28753', '46', '15', '35', '＜ 复 活 的 身 体 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28754', '46', '15', '36', '无 知 的 人 哪 ， 你 所 种 的 ， 若 不 死 就 不 能 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28755', '46', '15', '37', '并 且 你 所 种 的 不 是 那 将 来 的 形 体 ， 不 过 是 子 粒 ， 即 如 麦 子 ， 或 是 别 样 的 谷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28756', '46', '15', '38', '但 神 随 自 己 的 意 思 给 他 一 个 形 体 ， 并 叫 各 等 子 粒 各 有 自 己 的 形 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28757', '46', '15', '39', '凡 肉 体 各 有 不 同 ： 人 是 一 样 ， 兽 又 是 一 样 ， 鸟 又 是 一 样 ， 鱼 又 是 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28758', '46', '15', '40', '有 天 上 的 形 体 ， 也 有 地 上 的 形 体 ； 但 天 上 形 体 的 荣 光 是 一 样 ， 地 上 形 体 的 荣 光 又 是 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28759', '46', '15', '41', '日 有 日 的 荣 光 ， 月 有 月 的 荣 光 ， 星 有 星 的 荣 光 ； 这 星 和 那 星 的 荣 光 也 有 分 别 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28760', '46', '15', '42', '死 人 复 活 也 是 这 样 ： 所 种 的 是 必 朽 坏 的 ， 复 活 的 是 不 朽 坏 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28761', '46', '15', '43', '所 种 的 是 羞 辱 的 ， 复 活 的 是 荣 耀 的 ； 所 种 的 是 软 弱 的 ， 复 活 的 是 强 壮 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28762', '46', '15', '44', '所 种 的 是 血 气 的 身 体 ， 复 活 的 是 灵 性 的 身 体 。 若 有 血 气 的 身 体 ， 也 必 有 灵 性 的 身 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28763', '46', '15', '45', '经 上 也 是 这 样 记 着 说 ： “ 首 先 的 人 亚 当 成 了 有 灵 ｛ 灵 ： 或 译 血 气 ｝ 的 活 人 ” ； 末 后 的 亚 当 成 了 叫 人 活 的 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28764', '46', '15', '46', '但 属 灵 的 不 在 先 ， 属 血 气 的 在 先 ， 以 后 才 有 属 灵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28765', '46', '15', '47', '头 一 个 人 是 出 于 地 ， 乃 属 土 ； 第 二 个 人 是 出 于 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28766', '46', '15', '48', '那 属 土 的 怎 样 ， 凡 属 土 的 也 就 怎 样 ； 属 天 的 怎 样 ， 凡 属 天 的 也 就 怎 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28767', '46', '15', '49', '我 们 既 有 属 土 的 形 状 ， 将 来 也 必 有 属 天 的 形 状 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28768', '46', '15', '50', '弟 兄 们 ， 我 告 诉 你 们 说 ， 血 肉 之 体 不 能 承 受 神 的 国 ， 必 朽 坏 的 不 能 承 受 不 朽 坏 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28769', '46', '15', '51', '我 如 今 把 一 件 奥 秘 的 事 告 诉 你 们 ： 我 们 不 是 都 要 睡 觉 ， 乃 是 都 要 改 变 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28770', '46', '15', '52', '就 在 一 霎 时 ， 眨 眼 之 间 ， 号 筒 末 次 吹 响 的 时 候 。 因 号 筒 要 响 ， 死 人 要 复 活 成 为 不 朽 坏 的 ， 我 们 也 要 改 变 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28771', '46', '15', '53', '这 必 朽 坏 的 总 要 变 成 ｛ 变 成 ： 原 文 是 穿 ； 下 同 ｝ 不 朽 坏 的 ， 这 必 死 的 总 要 变 成 不 死 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28772', '46', '15', '54', '这 必 朽 坏 的 既 变 成 不 朽 坏 的 ， 这 必 死 的 既 变 成 不 死 的 ， 那 时 经 上 所 记 “ 死 被 得 胜 吞 灭 ” 的 话 就 应 验 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28773', '46', '15', '55', '死 啊 ！ 你 得 胜 的 权 势 在 哪 里 ？ 死 啊 ！ 你 的 毒 钩 在 哪 里 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28774', '46', '15', '56', '死 的 毒 钩 就 是 罪 ， 罪 的 权 势 就 是 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28775', '46', '15', '57', '感 谢 神 ， 使 我 们 藉 着 我 们 的 主 耶 稣 基 督 得 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28776', '46', '15', '58', '所 以 ， 我 亲 爱 的 弟 兄 们 ， 你 们 务 要 坚 固 ， 不 可 摇 动 ， 常 常 竭 力 多 做 主 工 ； 因 为 知 道 ， 你 们 的 劳 苦 在 主 里 面 不 是 徒 然 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28777', '46', '16', '1', '＜ 捐 助 圣 徒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28778', '46', '16', '2', '每 逢 七 日 的 第 一 日 ， 各 人 要 照 自 己 的 进 项 抽 出 来 留 着 ， 免 得 我 来 的 时 候 现 凑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28779', '46', '16', '3', '及 至 我 来 到 了 ， 你 们 写 信 举 荐 谁 ， 我 就 打 发 他 们 ， 把 你 们 的 捐 资 送 到 耶 路 撒 冷 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28780', '46', '16', '4', '若 我 也 该 去 ， 他 们 可 以 和 我 同 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28781', '46', '16', '5', '＜ 行 程 的 计 划 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28782', '46', '16', '6', '或 者 和 你 们 同 住 几 时 ， 或 者 也 过 冬 。 无 论 我 往 哪 里 去 ， 你 们 就 可 以 给 我 送 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28783', '46', '16', '7', '我 如 今 不 愿 意 路 过 见 你 们 ； 主 若 许 我 ， 我 就 指 望 和 你 们 同 住 几 时 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28784', '46', '16', '8', '但 我 要 仍 旧 住 在 以 弗 所 ， 直 等 到 五 旬 节 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28785', '46', '16', '9', '因 为 有 宽 大 又 有 功 效 的 门 为 我 开 了 ， 并 且 反 对 的 人 也 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28786', '46', '16', '10', '若 是 提 摩 太 来 到 ， 你 们 要 留 心 ， 叫 他 在 你 们 那 里 无 所 惧 怕 ； 因 为 他 劳 力 做 主 的 工 ， 像 我 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28787', '46', '16', '11', '所 以 ， 无 论 谁 都 不 可 藐 视 他 ， 只 要 送 他 平 安 前 行 ， 叫 他 到 我 这 里 来 ， 因 我 指 望 他 和 弟 兄 们 同 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28788', '46', '16', '12', '至 于 兄 弟 亚 波 罗 ， 我 再 三 地 劝 他 同 弟 兄 们 到 你 们 那 里 去 ； 但 这 时 他 决 不 愿 意 去 ， 几 时 有 了 机 会 他 必 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28789', '46', '16', '13', '＜ 请 求 和 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28790', '46', '16', '14', '凡 你 们 所 做 的 都 要 凭 爱 心 而 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28791', '46', '16', '15', '弟 兄 们 ， 你 们 晓 得 司 提 法 那 一 家 ， 是 亚 该 亚 初 结 的 果 子 ， 并 且 他 们 专 以 服 事 圣 徒 为 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28792', '46', '16', '16', '我 劝 你 们 顺 服 这 样 的 人 ， 并 一 切 同 工 同 劳 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28793', '46', '16', '17', '司 提 法 那 和 福 徒 拿 都 ， 并 亚 该 古 到 这 里 来 ， 我 很 喜 欢 ； 因 为 你 们 待 我 有 不 及 之 处 ， 他 们 补 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28794', '46', '16', '18', '他 们 叫 我 和 你 们 心 里 都 快 活 。 这 样 的 人 ， 你 们 务 要 敬 重 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28795', '46', '16', '19', '亚 细 亚 的 众 教 会 问 你 们 安 。 亚 居 拉 和 百 基 拉 并 在 他 们 家 里 的 教 会 ， 因 主 多 多 地 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28796', '46', '16', '20', '众 弟 兄 都 问 你 们 安 。 你 们 要 亲 嘴 问 安 ， 彼 此 务 要 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28797', '46', '16', '21', '我 ─ ─ 保 罗 亲 笔 问 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28798', '46', '16', '22', '若 有 人 不 爱 主 ， 这 人 可 诅 可 咒 。 主 必 要 来 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28799', '46', '16', '23', '愿 主 耶 稣 基 督 的 恩 常 与 你 们 众 人 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28800', '46', '16', '24', '我 在 基 督 耶 稣 里 的 爱 与 你 们 众 人 同 在 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28801', '47', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28802', '47', '1', '2', '愿 恩 惠 、 平 安 从 神 我 们 的 父 和 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28803', '47', '1', '3', '＜ 保 罗 受 患 难 后 的 感 恩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28804', '47', '1', '4', '我 们 在 一 切 患 难 中 ， 他 就 安 慰 我 们 ， 叫 我 们 能 用 神 所 赐 的 安 慰 去 安 慰 那 遭 各 样 患 难 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28805', '47', '1', '5', '我 们 既 多 受 基 督 的 苦 楚 ， 就 靠 基 督 多 得 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28806', '47', '1', '6', '我 们 受 患 难 呢 ， 是 为 叫 你 们 得 安 慰 ， 得 拯 救 ； 我 们 得 安 慰 呢 ， 也 是 为 叫 你 们 得 安 慰 ； 这 安 慰 能 叫 你 们 忍 受 我 们 所 受 的 那 样 苦 楚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28807', '47', '1', '7', '我 们 为 你 们 所 存 的 盼 望 是 确 定 的 ， 因 为 知 道 你 们 既 是 同 受 苦 楚 ， 也 必 同 得 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28808', '47', '1', '8', '弟 兄 们 ， 我 们 不 要 你 们 不 晓 得 ， 我 们 从 前 在 亚 细 亚 遭 遇 苦 难 ， 被 压 太 重 ， 力 不 能 胜 ， 甚 至 连 活 命 的 指 望 都 绝 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28809', '47', '1', '9', '自 己 心 里 也 断 定 是 必 死 的 ， 叫 我 们 不 靠 自 己 ， 只 靠 叫 死 人 复 活 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28810', '47', '1', '10', '他 曾 救 我 们 脱 离 那 极 大 的 死 亡 ， 现 在 仍 要 救 我 们 ， 并 且 我 们 指 望 他 将 来 还 要 救 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28811', '47', '1', '11', '你 们 以 祈 祷 帮 助 我 们 ， 好 叫 许 多 人 为 我 们 谢 恩 ， 就 是 为 我 们 因 许 多 人 所 得 的 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28812', '47', '1', '12', '＜ 保 罗 延 期 访 问 哥 林 多 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28813', '47', '1', '13', '我 们 现 在 写 给 你 们 的 话 ， 并 不 外 乎 你 们 所 念 的 、 所 认 识 的 ， 我 也 盼 望 你 们 到 底 还 是 要 认 识 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28814', '47', '1', '14', '正 如 你 们 已 经 有 几 分 认 识 我 们 ， 以 我 们 夸 口 ， 好 像 我 们 在 我 们 主 耶 稣 的 日 子 以 你 们 夸 口 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28815', '47', '1', '15', '我 既 然 这 样 深 信 ， 就 早 有 意 到 你 们 那 里 去 ， 叫 你 们 再 得 益 处 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28816', '47', '1', '16', '也 要 从 你 们 那 里 经 过 ， 往 马 其 顿 去 ， 再 从 马 其 顿 回 到 你 们 那 里 ， 叫 你 们 给 我 送 行 往 犹 太 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28817', '47', '1', '17', '我 有 此 意 ， 岂 是 反 覆 不 定 吗 ？ 我 所 起 的 意 ， 岂 是 从 情 欲 起 的 ， 叫 我 忽 是 忽 非 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28818', '47', '1', '18', '我 指 着 信 实 的 神 说 ， 我 们 向 你 们 所 传 的 道 ， 并 没 有 是 而 又 非 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28819', '47', '1', '19', '因 为 我 和 西 拉 并 提 摩 太 ， 在 你 们 中 间 所 传 神 的 儿 子 耶 稣 基 督 ， 总 没 有 是 而 又 非 的 ， 在 他 只 有 一 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28820', '47', '1', '20', '神 的 应 许 ， 不 论 有 多 少 ， 在 基 督 都 是 是 的 。 所 以 藉 着 他 也 都 是 实 在 ｛ 实 在 ： 原 文 是 阿 们 ｝ 的 ， 叫 神 因 我 们 得 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28821', '47', '1', '21', '那 在 基 督 里 坚 固 我 们 和 你 们 ， 并 且 膏 我 们 的 就 是 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28822', '47', '1', '22', '他 又 用 印 印 了 我 们 ， 并 赐 圣 灵 在 我 们 心 里 作 凭 据 ｛ 原 文 是 质 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28823', '47', '1', '23', '我 呼 吁 神 给 我 的 心 作 见 证 ， 我 没 有 往 哥 林 多 去 是 为 要 宽 容 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28824', '47', '1', '24', '我 们 并 不 是 辖 管 你 们 的 信 心 ， 乃 是 帮 助 你 们 的 快 乐 ， 因 为 你 们 凭 信 才 站 立 得 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28825', '47', '2', '1', '我 自 己 定 了 主 意 再 到 你 们 那 里 去 ， 必 须 大 家 没 有 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28826', '47', '2', '2', '倘 若 我 叫 你 们 忧 愁 ， 除 了 我 叫 那 忧 愁 的 人 以 外 ， 谁 能 叫 我 快 乐 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28827', '47', '2', '3', '我 曾 把 这 事 写 给 你 们 ， 恐 怕 我 到 的 时 候 ， 应 该 叫 我 快 乐 的 那 些 人 ， 反 倒 叫 我 忧 愁 。 我 也 深 信 ， 你 们 众 人 都 以 我 的 快 乐 为 自 己 的 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28828', '47', '2', '4', '我 先 前 心 里 难 过 痛 苦 ， 多 多 地 流 泪 ， 写 信 给 你 们 ， 不 是 叫 你 们 忧 愁 ， 乃 是 叫 你 们 知 道 我 格 外 地 疼 爱 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28829', '47', '2', '5', '＜ 赦 免 犯 过 失 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28830', '47', '2', '6', '这 样 的 人 受 了 众 人 的 责 罚 也 就 够 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28831', '47', '2', '7', '倒 不 如 赦 免 他 ， 安 慰 他 ， 免 得 他 忧 愁 太 过 ， 甚 至 沉 沦 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28832', '47', '2', '8', '所 以 我 劝 你 们 ， 要 向 他 显 出 坚 定 不 移 的 爱 心 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28833', '47', '2', '9', '为 此 我 先 前 也 写 信 给 你 们 ， 要 试 验 你 们 ， 看 你 们 凡 事 顺 从 不 顺 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28834', '47', '2', '10', '你 们 赦 免 谁 ， 我 也 赦 免 谁 。 我 若 有 所 赦 免 的 ， 是 在 基 督 面 前 为 你 们 赦 免 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28835', '47', '2', '11', '免 得 撒 但 趁 着 机 会 胜 过 我 们 ， 因 我 们 并 非 不 晓 得 他 的 诡 计 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28836', '47', '2', '12', '＜ 保 罗 的 忧 愁 和 安 慰 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28837', '47', '2', '13', '那 时 ， 因 为 没 有 遇 见 兄 弟 提 多 ， 我 心 里 不 安 ， 便 辞 别 那 里 的 人 往 马 其 顿 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28838', '47', '2', '14', '感 谢 神 ！ 常 率 领 我 们 在 基 督 里 夸 胜 ， 并 藉 着 我 们 在 各 处 显 扬 那 因 认 识 基 督 而 有 的 香 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28839', '47', '2', '15', '因 为 我 们 在 神 面 前 ， 无 论 在 得 救 的 人 身 上 或 灭 亡 的 人 身 上 ， 都 有 基 督 馨 香 之 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28840', '47', '2', '16', '在 这 等 人 ， 就 作 了 死 的 香 气 叫 他 死 ； 在 那 等 人 ， 就 作 了 活 的 香 气 叫 他 活 。 这 事 谁 能 当 得 起 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28841', '47', '2', '17', '我 们 不 像 那 许 多 人 ， 为 利 混 乱 神 的 道 ； 乃 是 由 于 诚 实 ， 由 于 神 ， 在 神 面 前 凭 着 基 督 讲 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28842', '47', '3', '1', '＜ 新 约 的 执 事 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28843', '47', '3', '2', '你 们 就 是 我 们 的 荐 信 ， 写 在 我 们 的 心 里 ， 被 众 人 所 知 道 所 念 诵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28844', '47', '3', '3', '你 们 明 显 是 基 督 的 信 ， 藉 着 我 们 修 成 的 。 不 是 用 墨 写 的 ， 乃 是 用 永 生 神 的 灵 写 的 ； 不 是 写 在 石 版 上 ， 乃 是 写 在 心 版 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28845', '47', '3', '4', '我 们 因 基 督 ， 所 以 在 神 面 前 才 有 这 样 的 信 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28846', '47', '3', '5', '并 不 是 我 们 凭 自 己 能 承 担 什 么 事 ； 我 们 所 能 承 担 的 ， 乃 是 出 于 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28847', '47', '3', '6', '他 叫 我 们 能 承 当 这 新 约 的 执 事 ， 不 是 凭 着 字 句 ， 乃 是 凭 着 精 意 ； 因 为 那 字 句 是 叫 人 死 ， 精 意 ｛ 或 译 ： 圣 灵 ｝ 是 叫 人 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28848', '47', '3', '7', '那 用 字 刻 在 石 头 上 属 死 的 职 事 尚 且 有 荣 光 ， 甚 至 以 色 列 人 因 摩 西 面 上 的 荣 光 ， 不 能 定 睛 看 他 的 脸 ； 这 荣 光 原 是 渐 渐 退 去 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28849', '47', '3', '8', '何 况 那 属 灵 的 职 事 岂 不 更 有 荣 光 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28850', '47', '3', '9', '若 是 定 罪 的 职 事 有 荣 光 ， 那 称 义 的 职 事 荣 光 就 越 发 大 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28851', '47', '3', '10', '那 从 前 有 荣 光 的 ， 因 这 极 大 的 荣 光 就 算 不 得 有 荣 光 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28852', '47', '3', '11', '若 那 废 掉 的 有 荣 光 ， 这 长 存 的 就 更 有 荣 光 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28853', '47', '3', '12', '我 们 既 有 这 样 的 盼 望 ， 就 大 胆 讲 说 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28854', '47', '3', '13', '不 像 摩 西 将 帕 子 蒙 在 脸 上 ， 叫 以 色 列 人 不 能 定 睛 看 到 那 将 废 者 的 结 局 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28855', '47', '3', '14', '但 他 们 的 心 地 刚 硬 ， 直 到 今 日 诵 读 旧 约 的 时 候 ， 这 帕 子 还 没 有 揭 去 。 这 帕 子 在 基 督 里 已 经 废 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28856', '47', '3', '15', '然 而 直 到 今 日 ， 每 逢 诵 读 摩 西 书 的 时 候 ， 帕 子 还 在 他 们 心 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28857', '47', '3', '16', '但 他 们 的 心 几 时 归 向 主 ， 帕 子 就 几 时 除 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28858', '47', '3', '17', '主 就 是 那 灵 ； 主 的 灵 在 哪 里 ， 那 里 就 得 以 自 由 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28859', '47', '3', '18', '我 们 众 人 既 然 敞 着 脸 得 以 看 见 主 的 荣 光 ， 好 像 从 镜 子 里 返 照 ， 就 变 成 主 的 形 状 ， 荣 上 加 荣 ， 如 同 从 主 的 灵 变 成 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28860', '47', '4', '1', '＜ 在 瓦 器 里 的 宝 贝 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28861', '47', '4', '2', '乃 将 那 些 暗 昧 可 耻 的 事 弃 绝 了 ； 不 行 诡 诈 ， 不 谬 讲 神 的 道 理 ， 只 将 真 理 表 明 出 来 ， 好 在 神 面 前 把 自 己 荐 与 各 人 的 良 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28862', '47', '4', '3', '如 果 我 们 的 福 音 蒙 蔽 ， 就 是 蒙 蔽 在 灭 亡 的 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28863', '47', '4', '4', '此 等 不 信 之 人 被 这 世 界 的 神 弄 瞎 了 心 眼 ， 不 叫 基 督 荣 耀 福 音 的 光 照 着 他 们 。 基 督 本 是 神 的 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28864', '47', '4', '5', '我 们 原 不 是 传 自 己 ， 乃 是 传 基 督 耶 稣 为 主 ， 并 且 自 己 因 耶 稣 作 你 们 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28865', '47', '4', '6', '那 吩 咐 光 从 黑 暗 里 照 出 来 的 神 ， 已 经 照 在 我 们 心 里 ， 叫 我 们 得 知 神 荣 耀 的 光 显 在 耶 稣 基 督 的 面 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28866', '47', '4', '7', '我 们 有 这 宝 贝 放 在 瓦 器 里 ， 要 显 明 这 莫 大 的 能 力 是 出 于 神 ， 不 是 出 于 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28867', '47', '4', '8', '我 们 四 面 受 敌 ， 却 不 被 困 住 ； 心 里 作 难 ， 却 不 至 失 望 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28868', '47', '4', '9', '遭 逼 迫 ， 却 不 被 丢 弃 ； 打 倒 了 ， 却 不 至 死 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28869', '47', '4', '10', '身 上 常 带 着 耶 稣 的 死 ， 使 耶 稣 的 生 也 显 明 在 我 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28870', '47', '4', '11', '因 为 我 们 这 活 着 的 人 是 常 为 耶 稣 被 交 于 死 地 ， 使 耶 稣 的 生 在 我 们 这 必 死 的 身 上 显 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28871', '47', '4', '12', '这 样 看 来 ， 死 是 在 我 们 身 上 发 动 ， 生 却 在 你 们 身 上 发 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28872', '47', '4', '13', '但 我 们 既 有 信 心 ， 正 如 经 上 记 着 说 ： “ 我 因 信 ， 所 以 如 此 说 话 。 ” 我 们 也 信 ， 所 以 也 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28873', '47', '4', '14', '自 己 知 道 那 叫 主 耶 稣 复 活 的 ， 也 必 叫 我 们 与 耶 稣 一 同 复 活 ， 并 且 叫 我 们 与 你 们 一 同 站 在 他 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28874', '47', '4', '15', '凡 事 都 是 为 你 们 ， 好 叫 恩 惠 因 人 多 越 发 加 增 ， 感 谢 格 外 显 多 ， 以 致 荣 耀 归 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28875', '47', '4', '16', '＜ 靠 信 心 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28876', '47', '4', '17', '我 们 这 至 暂 至 轻 的 苦 楚 ， 要 为 我 们 成 就 极 重 无 比 、 永 远 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28877', '47', '4', '18', '原 来 我 们 不 是 顾 念 所 见 的 ， 乃 是 顾 念 所 不 见 的 ； 因 为 所 见 的 是 暂 时 的 ， 所 不 见 的 是 永 远 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28878', '47', '5', '1', '我 们 原 知 道 ， 我 们 这 地 上 的 帐 棚 若 拆 毁 了 ， 必 得 神 所 造 ， 不 是 人 手 所 造 ， 在 天 上 永 存 的 房 屋 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28879', '47', '5', '2', '我 们 在 这 帐 棚 里 叹 息 ， 深 想 得 那 从 天 上 来 的 房 屋 ， 好 像 穿 上 衣 服 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28880', '47', '5', '3', '倘 若 穿 上 ， 被 遇 见 的 时 候 就 不 至 于 赤 身 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28881', '47', '5', '4', '我 们 在 这 帐 棚 里 叹 息 劳 苦 ， 并 非 愿 意 脱 下 这 个 ， 乃 是 愿 意 穿 上 那 个 ， 好 叫 这 必 死 的 被 生 命 吞 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28882', '47', '5', '5', '为 此 ， 培 植 我 们 的 就 是 神 ， 他 又 赐 给 我 们 圣 灵 作 凭 据 ｛ 原 文 是 质 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28883', '47', '5', '6', '所 以 ， 我 们 时 常 坦 然 无 惧 ， 并 且 晓 得 我 们 住 在 身 内 ， 便 与 主 相 离 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28884', '47', '5', '7', '因 我 们 行 事 为 人 是 凭 着 信 心 ， 不 是 凭 着 眼 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28885', '47', '5', '8', '我 们 坦 然 无 惧 ， 是 更 愿 意 离 开 身 体 与 主 同 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28886', '47', '5', '9', '所 以 ， 无 论 是 住 在 身 内 ， 离 开 身 外 ， 我 们 立 了 志 向 ， 要 得 主 的 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28887', '47', '5', '10', '因 为 我 们 众 人 必 要 在 基 督 台 前 显 露 出 来 ， 叫 各 人 按 着 本 身 所 行 的 ， 或 善 或 恶 受 报 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28888', '47', '5', '11', '＜ 劝 人 与 神 和 好 的 职 分 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28889', '47', '5', '12', '我 们 不 是 向 你 们 再 举 荐 自 己 ， 乃 是 叫 你 们 因 我 们 有 可 夸 之 处 ， 好 对 那 凭 外 貌 不 凭 内 心 夸 口 的 人 ， 有 言 可 答 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28890', '47', '5', '13', '我 们 若 果 颠 狂 ， 是 为 神 ； 若 果 谨 守 ， 是 为 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28891', '47', '5', '14', '原 来 基 督 的 爱 激 励 我 们 ； 因 我 们 想 ， 一 人 既 替 众 人 死 ， 众 人 就 都 死 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28892', '47', '5', '15', '并 且 他 替 众 人 死 ， 是 叫 那 些 活 着 的 人 不 再 为 自 己 活 ， 乃 为 替 他 们 死 而 复 活 的 主 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28893', '47', '5', '16', '所 以 ， 我 们 从 今 以 后 ， 不 凭 着 外 貌 ｛ 原 文 是 肉 体 ； 本 节 同 ｝ 认 人 了 。 虽 然 凭 着 外 貌 认 过 基 督 ， 如 今 却 不 再 这 样 认 他 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28894', '47', '5', '17', '若 有 人 在 基 督 里 ， 他 就 是 新 造 的 人 ， 旧 事 已 过 ， 都 变 成 新 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28895', '47', '5', '18', '一 切 都 是 出 于 神 ； 他 藉 着 基 督 使 我 们 与 他 和 好 ， 又 将 劝 人 与 他 和 好 的 职 分 赐 给 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28896', '47', '5', '19', '这 就 是 神 在 基 督 里 ， 叫 世 人 与 自 己 和 好 ， 不 将 他 们 的 过 犯 归 到 他 们 身 上 ， 并 且 将 这 和 好 的 道 理 托 付 了 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28897', '47', '5', '20', '所 以 ， 我 们 作 基 督 的 使 者 ， 就 好 像 神 藉 我 们 劝 你 们 一 般 。 我 们 替 基 督 求 你 们 与 神 和 好 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28898', '47', '5', '21', '神 使 那 无 罪 ｛ 无 罪 ： 原 文 是 不 知 罪 ｝ 的 ， 替 我 们 成 为 罪 ， 好 叫 我 们 在 他 里 面 成 为 神 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28899', '47', '6', '1', '我 们 与 神 同 工 的 ， 也 劝 你 们 不 可 徒 受 他 的 恩 典 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28900', '47', '6', '2', '因 为 他 说 ： “ 在 悦 纳 的 时 候 ， 我 应 允 了 你 ； 在 拯 救 的 日 子 ， 我 搭 救 了 你 。 ” 看 哪 ！ 现 在 正 是 悦 纳 的 时 候 ； 现 在 正 是 拯 救 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28901', '47', '6', '3', '我 们 凡 事 都 不 叫 人 有 妨 碍 ， 免 得 这 职 分 被 人 毁 谤 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28902', '47', '6', '4', '反 倒 在 各 样 的 事 上 表 明 自 己 是 神 的 用 人 ， 就 如 在 许 多 的 忍 耐 、 患 难 、 穷 乏 、 困 苦 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28903', '47', '6', '5', '鞭 打 、 监 禁 、 扰 乱 、 勤 劳 、 警 醒 、 不 食 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28904', '47', '6', '6', '廉 洁 、 知 识 、 恒 忍 、 恩 慈 、 圣 灵 的 感 化 、 无 伪 的 爱 心 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28905', '47', '6', '7', '真 实 的 道 理 、 神 的 大 能 ； 仁 义 的 兵 器 在 左 在 右 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28906', '47', '6', '8', '荣 耀 、 羞 辱 ， 恶 名 、 美 名 ； 似 乎 是 诱 惑 人 的 ， 却 是 诚 实 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28907', '47', '6', '9', '似 乎 不 为 人 所 知 ， 却 是 人 所 共 知 的 ； 似 乎 要 死 ， 却 是 活 着 的 ； 似 乎 受 责 罚 ， 却 是 不 至 丧 命 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28908', '47', '6', '10', '似 乎 忧 愁 ， 却 是 常 常 快 乐 的 ； 似 乎 贫 穷 ， 却 是 叫 许 多 人 富 足 的 ； 似 乎 一 无 所 有 ， 却 是 样 样 都 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28909', '47', '6', '11', '哥 林 多 人 哪 ， 我 们 向 你 们 ， 口 是 张 开 的 ， 心 是 宽 宏 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28910', '47', '6', '12', '你 们 狭 窄 ， 原 不 在 乎 我 们 ， 是 在 乎 自 己 的 心 肠 狭 窄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28911', '47', '6', '13', '你 们 也 要 照 样 用 宽 宏 的 心 报 答 我 。 我 这 话 正 像 对 自 己 的 孩 子 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28912', '47', '6', '14', '＜ 永 生 神 的 殿 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28913', '47', '6', '15', '基 督 和 彼 列 ｛ 彼 列 就 是 撒 但 的 别 名 ｝ 有 什 么 相 和 呢 ？ 信 主 的 和 不 信 主 的 有 什 么 相 干 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28914', '47', '6', '16', '神 的 殿 和 偶 像 有 什 么 相 同 呢 ？ 因 为 我 们 是 永 生 神 的 殿 ， 就 如 神 曾 说 ： 我 要 在 他 们 中 间 居 住 ， 在 他 们 中 间 来 往 ； 我 要 作 他 们 的 神 ； 他 们 要 作 我 的 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28915', '47', '6', '17', '又 说 ： 你 们 务 要 从 他 们 中 间 出 来 ， 与 他 们 分 别 ； 不 要 沾 不 洁 净 的 物 ， 我 就 收 纳 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28916', '47', '6', '18', '我 要 作 你 们 的 父 ； 你 们 要 作 我 的 儿 女 。 这 是 全 能 的 主 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28917', '47', '7', '1', '亲 爱 的 弟 兄 啊 ， 我 们 既 有 这 等 应 许 ， 就 当 洁 净 自 己 ， 除 去 身 体 、 灵 魂 一 切 的 污 秽 ， 敬 畏 神 ， 得 以 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28918', '47', '7', '2', '＜ 保 罗 为 教 会 悔 改 而 欢 乐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28919', '47', '7', '3', '我 说 这 话 ， 不 是 要 定 你 们 的 罪 。 我 已 经 说 过 ， 你 们 常 在 我 们 心 里 ， 情 愿 与 你 们 同 生 同 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28920', '47', '7', '4', '我 大 大 地 放 胆 ， 向 你 们 说 话 ； 我 因 你 们 多 多 夸 口 ， 满 得 安 慰 ； 我 们 在 一 切 患 难 中 分 外 地 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28921', '47', '7', '5', '我 们 从 前 就 是 到 了 马 其 顿 的 时 候 ， 身 体 也 不 得 安 宁 ， 周 围 遭 患 难 ， 外 有 争 战 ， 内 有 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28922', '47', '7', '6', '但 那 安 慰 丧 气 之 人 的 神 藉 着 提 多 来 安 慰 了 我 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28923', '47', '7', '7', '不 但 藉 着 他 来 ， 也 藉 着 他 从 你 们 所 得 的 安 慰 ， 安 慰 了 我 们 ； 因 他 把 你 们 的 想 念 、 哀 恸 ， 和 向 我 的 热 心 ， 都 告 诉 了 我 ， 叫 我 更 加 欢 喜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28924', '47', '7', '8', '我 先 前 写 信 叫 你 们 忧 愁 ， 我 后 来 虽 然 懊 悔 ， 如 今 却 不 懊 悔 ； 因 我 知 道 ， 那 信 叫 你 们 忧 愁 不 过 是 暂 时 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28925', '47', '7', '9', '如 今 我 欢 喜 ， 不 是 因 你 们 忧 愁 ， 是 因 你 们 从 忧 愁 中 生 出 懊 悔 来 。 你 们 依 着 神 的 意 思 忧 愁 ， 凡 事 就 不 至 于 因 我 们 受 亏 损 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28926', '47', '7', '10', '因 为 依 着 神 的 意 思 忧 愁 ， 就 生 出 没 有 后 悔 的 懊 悔 来 ， 以 致 得 救 ； 但 世 俗 的 忧 愁 是 叫 人 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28927', '47', '7', '11', '你 看 ， 你 们 依 着 神 的 意 思 忧 愁 ， 从 此 就 生 出 何 等 的 殷 勤 、 自 诉 、 自 恨 、 恐 惧 、 想 念 、 热 心 、 责 罚 ｛ 或 译 ： 自 责 ｝ 。 在 这 一 切 事 上 ， 你 们 都 表 明 自 己 是 洁 净 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28928', '47', '7', '12', '我 虽 然 从 前 写 信 给 你 们 ， 却 不 是 为 那 亏 负 人 的 ， 也 不 是 为 那 受 人 亏 负 的 ， 乃 要 在 神 面 前 把 你 们 顾 念 我 们 的 热 心 表 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28929', '47', '7', '13', '故 此 ， 我 们 得 了 安 慰 。 并 且 在 安 慰 之 中 ， 因 你 们 众 人 使 提 多 心 里 畅 快 欢 喜 ， 我 们 就 更 加 欢 喜 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28930', '47', '7', '14', '我 若 对 提 多 夸 奖 了 你 们 什 么 ， 也 觉 得 没 有 惭 愧 ； 因 我 对 提 多 夸 奖 你 们 的 话 成 了 真 的 ， 正 如 我 对 你 们 所 说 的 话 也 都 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28931', '47', '7', '15', '并 且 提 多 想 起 你 们 众 人 的 顺 服 ， 是 怎 样 恐 惧 战 兢 地 接 待 他 ， 他 爱 你 们 的 心 肠 就 越 发 热 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28932', '47', '7', '16', '我 如 今 欢 喜 ， 能 在 凡 事 上 为 你 们 放 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28933', '47', '8', '1', '＜ 慷 慨 的 捐 助 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28934', '47', '8', '2', '就 是 他 们 在 患 难 中 受 大 试 炼 的 时 候 ， 仍 有 满 足 的 快 乐 ， 在 极 穷 之 间 还 格 外 显 出 他 们 乐 捐 的 厚 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28935', '47', '8', '3', '我 可 以 证 明 ， 他 们 是 按 着 力 量 ， 而 且 也 过 了 力 量 ， 自 己 甘 心 乐 意 地 捐 助 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28936', '47', '8', '4', '再 三 地 求 我 们 ， 准 他 们 在 这 供 给 圣 徒 的 恩 情 上 有 分 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28937', '47', '8', '5', '并 且 他 们 所 做 的 ， 不 但 照 我 们 所 想 望 的 ， 更 照 神 的 旨 意 先 把 自 己 献 给 主 ， 又 归 附 了 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28938', '47', '8', '6', '因 此 我 劝 提 多 ， 既 然 在 你 们 中 间 开 办 这 慈 惠 的 事 ， 就 当 办 成 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28939', '47', '8', '7', '你 们 既 然 在 信 心 、 口 才 、 知 识 、 热 心 ， 和 待 我 们 的 爱 心 上 ， 都 格 外 显 出 满 足 来 ， 就 当 在 这 慈 惠 的 事 上 也 格 外 显 出 满 足 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28940', '47', '8', '8', '我 说 这 话 ， 不 是 吩 咐 你 们 ， 乃 是 藉 着 别 人 的 热 心 试 验 你 们 爱 心 的 实 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28941', '47', '8', '9', '你 们 知 道 我 们 主 耶 稣 基 督 的 恩 典 ： 他 本 来 富 足 ， 却 为 你 们 成 了 贫 穷 ， 叫 你 们 因 他 的 贫 穷 ， 可 以 成 为 富 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28942', '47', '8', '10', '我 在 这 事 上 把 我 的 意 见 告 诉 你 们 ， 是 与 你 们 有 益 ； 因 为 你 们 下 手 办 这 事 ， 而 且 起 此 心 意 ， 已 经 有 一 年 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28943', '47', '8', '11', '如 今 就 当 办 成 这 事 。 既 有 愿 做 的 心 ， 也 当 照 你 们 所 有 的 去 办 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28944', '47', '8', '12', '因 为 人 若 有 愿 做 的 心 ， 必 蒙 悦 纳 ， 乃 是 照 他 所 有 的 ， 并 不 是 照 他 所 无 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28945', '47', '8', '13', '我 原 不 是 要 别 人 轻 省 ， 你 们 受 累 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28946', '47', '8', '14', '乃 要 均 平 ， 就 是 要 你 们 的 富 余 ， 现 在 可 以 补 他 们 的 不 足 ， 使 他 们 的 富 余 ， 将 来 也 可 以 补 你 们 的 不 足 ， 这 就 均 平 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28947', '47', '8', '15', '如 经 上 所 记 ： 多 收 的 也 没 有 余 ； 少 收 的 也 没 有 缺 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28948', '47', '8', '16', '＜ 提 多 和 他 的 同 工 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28949', '47', '8', '17', '他 固 然 是 听 了 我 的 劝 ， 但 自 己 更 是 热 心 ， 情 愿 往 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28950', '47', '8', '18', '我 们 还 打 发 一 位 兄 弟 和 他 同 去 ， 这 人 在 福 音 上 得 了 众 教 会 的 称 赞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28951', '47', '8', '19', '不 但 这 样 ， 他 也 被 众 教 会 挑 选 ， 和 我 们 同 行 ， 把 所 托 与 我 们 的 这 捐 赀 送 到 了 ， 可 以 荣 耀 主 ， 又 表 明 我 们 乐 意 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28952', '47', '8', '20', '这 就 免 得 有 人 因 我 们 收 的 捐 银 很 多 ， 就 挑 我 们 的 不 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28953', '47', '8', '21', '我 们 留 心 行 光 明 的 事 ， 不 但 在 主 面 前 ， 就 在 人 面 前 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28954', '47', '8', '22', '我 们 又 打 发 一 位 兄 弟 同 去 ； 这 人 的 热 心 ， 我 们 在 许 多 事 上 屡 次 试 验 过 。 现 在 他 因 为 深 信 你 们 ， 就 更 加 热 心 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28955', '47', '8', '23', '论 到 提 多 ， 他 是 我 的 同 伴 ， 一 同 为 你 们 劳 碌 的 。 论 到 那 两 位 兄 弟 ， 他 们 是 众 教 会 的 使 者 ， 是 基 督 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28956', '47', '8', '24', '所 以 ， 你 们 务 要 在 众 教 会 面 前 显 明 你 们 爱 心 的 凭 据 ， 并 我 所 夸 奖 你 们 的 凭 据 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28957', '47', '9', '1', '＜ 帮 助 圣 徒 的 捐 款 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28958', '47', '9', '2', '因 为 我 知 道 你 们 乐 意 的 心 ， 常 对 马 其 顿 人 夸 奖 你 们 ， 说 亚 该 亚 人 预 备 好 了 ， 已 经 有 一 年 了 ； 并 且 你 们 的 热 心 激 动 了 许 多 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28959', '47', '9', '3', '但 我 打 发 那 几 位 弟 兄 去 ， 要 叫 你 们 照 我 的 话 预 备 妥 当 ， 免 得 我 们 在 这 事 上 夸 奖 你 们 的 话 落 了 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28960', '47', '9', '4', '万 一 有 马 其 顿 人 与 我 同 去 ， 见 你 们 没 有 预 备 ， 就 叫 我 们 所 确 信 的 ， 反 成 了 羞 愧 ； 你 们 羞 愧 ， 更 不 用 说 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28961', '47', '9', '5', '因 此 ， 我 想 不 得 不 求 那 几 位 弟 兄 先 到 你 们 那 里 去 ， 把 从 前 所 应 许 的 捐 赀 预 备 妥 当 ， 就 显 出 你 们 所 捐 的 是 出 于 乐 意 ， 不 是 出 于 勉 强 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28962', '47', '9', '6', '“ 少 种 的 少 收 ， 多 种 的 多 收 ” ， 这 话 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28963', '47', '9', '7', '各 人 要 随 本 心 所 酌 定 的 ， 不 要 作 难 ， 不 要 勉 强 ， 因 为 捐 得 乐 意 的 人 是 神 所 喜 爱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28964', '47', '9', '8', '神 能 将 各 样 的 恩 惠 多 多 地 加 给 你 们 ， 使 你 们 凡 事 常 常 充 足 ， 能 多 行 各 样 善 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28965', '47', '9', '9', '如 经 上 所 记 ： 他 施 舍 钱 财 ， 赒 济 贫 穷 ； 他 的 仁 义 存 到 永 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28966', '47', '9', '10', '那 赐 种 给 撒 种 的 ， 赐 粮 给 人 吃 的 ， 必 多 多 加 给 你 们 种 地 的 种 子 ， 又 增 添 你 们 仁 义 的 果 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28967', '47', '9', '11', '叫 你 们 凡 事 富 足 ， 可 以 多 多 施 舍 ， 就 藉 着 我 们 使 感 谢 归 于 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28968', '47', '9', '12', '因 为 办 这 供 给 的 事 ， 不 但 补 圣 徒 的 缺 乏 ， 而 且 叫 许 多 人 越 发 感 谢 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28969', '47', '9', '13', '他 们 从 这 供 给 的 事 上 得 了 凭 据 ， 知 道 你 们 承 认 基 督 顺 服 他 的 福 音 ， 多 多 地 捐 钱 给 他 们 和 众 人 ， 便 将 荣 耀 归 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28970', '47', '9', '14', '他 们 也 因 神 极 大 的 恩 赐 显 在 你 们 心 里 ， 就 切 切 地 想 念 你 们 ， 为 你 们 祈 祷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28971', '47', '9', '15', '感 谢 神 ， 因 他 有 说 不 尽 的 恩 赐 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28972', '47', '10', '1', '＜ 保 罗 为 他 的 工 作 辩 护 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28973', '47', '10', '2', '有 人 以 为 我 是 凭 着 血 气 行 事 ， 我 也 以 为 必 须 用 勇 敢 待 这 等 人 ； 求 你 们 不 要 叫 我 在 你 们 那 里 的 时 候 ， 有 这 样 的 勇 敢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28974', '47', '10', '3', '因 为 我 们 虽 然 在 血 气 中 行 事 ， 却 不 凭 着 血 气 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28975', '47', '10', '4', '我 们 争 战 的 兵 器 本 不 是 属 血 气 的 ， 乃 是 在 神 面 前 有 能 力 ， 可 以 攻 破 坚 固 的 营 垒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28976', '47', '10', '5', '将 各 样 的 计 谋 ， 各 样 拦 阻 人 认 识 神 的 那 些 自 高 之 事 ， 一 概 攻 破 了 ， 又 将 人 所 有 的 心 意 夺 回 ， 使 他 都 顺 服 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28977', '47', '10', '6', '并 且 我 已 经 预 备 好 了 ， 等 你 们 十 分 顺 服 的 时 候 ， 要 责 罚 那 一 切 不 顺 服 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28978', '47', '10', '7', '你 们 是 看 眼 前 的 吗 ？ 倘 若 有 人 自 信 是 属 基 督 的 ， 他 要 再 想 想 ， 他 如 何 属 基 督 ， 我 们 也 是 如 何 属 基 督 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28979', '47', '10', '8', '主 赐 给 我 们 权 柄 ， 是 要 造 就 你 们 ， 并 不 是 要 败 坏 你 们 ； 我 就 是 为 这 权 柄 稍 微 夸 口 ， 也 不 至 于 惭 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28980', '47', '10', '9', '我 说 这 话 ， 免 得 你 们 以 为 我 写 信 是 要 威 吓 你 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28981', '47', '10', '10', '因 为 有 人 说 ： “ 他 的 信 又 沉 重 又 厉 害 ， 及 至 见 面 ， 却 是 气 貌 不 扬 ， 言 语 粗 俗 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28982', '47', '10', '11', '这 等 人 当 想 ， 我 们 不 在 那 里 的 时 候 ， 信 上 的 言 语 如 何 ， 见 面 的 时 候 ， 行 事 也 必 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28983', '47', '10', '12', '因 为 我 们 不 敢 将 自 己 和 那 自 荐 的 人 同 列 相 比 。 他 们 用 自 己 度 量 自 己 ， 用 自 己 比 较 自 己 ， 乃 是 不 通 达 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28984', '47', '10', '13', '我 们 不 愿 意 分 外 夸 口 ， 只 要 照 神 所 量 给 我 们 的 界 限 构 到 你 们 那 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28985', '47', '10', '14', '我 们 并 非 过 了 自 己 的 界 限 ， 好 像 构 不 到 你 们 那 里 ； 因 为 我 们 早 到 你 们 那 里 ， 传 了 基 督 的 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28986', '47', '10', '15', '＜ 当 指 着 主 夸 口 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28987', '47', '10', '16', '得 以 将 福 音 传 到 你 们 以 外 的 地 方 ； 并 不 是 在 别 人 界 限 之 内 ， 藉 着 他 现 成 的 事 夸 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28988', '47', '10', '17', '但 夸 口 的 ， 当 指 着 主 夸 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28989', '47', '10', '18', '因 为 蒙 悦 纳 的 ， 不 是 自 己 称 许 的 ， 乃 是 主 所 称 许 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28990', '47', '11', '1', '＜ 保 罗 和 假 使 徒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28991', '47', '11', '2', '我 为 你 们 起 的 愤 恨 ， 原 是 神 那 样 的 愤 恨 。 因 为 我 曾 把 你 们 许 配 一 个 丈 夫 ， 要 把 你 们 如 同 贞 洁 的 童 女 ， 献 给 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28992', '47', '11', '3', '我 只 怕 你 们 的 心 或 偏 于 邪 ， 失 去 那 向 基 督 所 存 纯 一 清 洁 的 心 ， 就 像 蛇 用 诡 诈 诱 惑 了 夏 娃 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28993', '47', '11', '4', '假 如 有 人 来 另 传 一 个 耶 稣 ， 不 是 我 们 所 传 过 的 ； 或 者 你 们 另 受 一 个 灵 ， 不 是 你 们 所 受 过 的 ； 或 者 另 得 一 个 福 音 ， 不 是 你 们 所 得 过 的 ； 你 们 容 让 他 也 就 罢 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28994', '47', '11', '5', '但 我 想 ， 我 一 点 不 在 那 些 最 大 的 使 徒 以 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28995', '47', '11', '6', '我 的 言 语 虽 然 粗 俗 ， 我 的 知 识 却 不 粗 俗 。 这 是 我 们 在 凡 事 上 向 你 们 众 人 显 明 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28996', '47', '11', '7', '我 因 为 白 白 传 神 的 福 音 给 你 们 ， 就 自 居 卑 微 ， 叫 你 们 高 升 ， 这 算 是 我 犯 罪 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28997', '47', '11', '8', '我 亏 负 了 别 的 教 会 ， 向 他 们 取 了 工 价 来 给 你 们 效 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28998', '47', '11', '9', '我 在 你 们 那 里 缺 乏 的 时 候 ， 并 没 有 累 着 你 们 一 个 人 ； 因 我 所 缺 乏 的 ， 那 从 马 其 顿 来 的 弟 兄 们 都 补 足 了 。 我 向 来 凡 事 谨 守 ， 后 来 也 必 谨 守 ， 总 不 至 于 累 着 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('28999', '47', '11', '10', '既 有 基 督 的 诚 实 在 我 里 面 ， 就 无 人 能 在 亚 该 亚 一 带 地 方 阻 挡 我 这 自 夸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29000', '47', '11', '11', '为 什 么 呢 ？ 是 因 我 不 爱 你 们 吗 ？ 这 有 神 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29001', '47', '11', '12', '我 现 在 所 做 的 ， 后 来 还 要 做 ， 为 要 断 绝 那 些 寻 机 会 人 的 机 会 ， 使 他 们 在 所 夸 的 事 上 也 不 过 与 我 们 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29002', '47', '11', '13', '那 等 人 是 假 使 徒 ， 行 事 诡 诈 ， 装 作 基 督 使 徒 的 模 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29003', '47', '11', '14', '这 也 不 足 为 怪 ， 因 为 连 撒 但 也 装 作 光 明 的 天 使 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29004', '47', '11', '15', '所 以 他 的 差 役 ， 若 装 作 仁 义 的 差 役 ， 也 不 算 希 奇 。 他 们 的 结 局 必 然 照 着 他 们 的 行 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29005', '47', '11', '16', '＜ 保 罗 作 使 徒 所 受 的 患 难 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29006', '47', '11', '17', '我 说 的 话 不 是 奉 主 命 说 的 ， 乃 是 像 愚 妄 人 放 胆 自 夸 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29007', '47', '11', '18', '既 有 好 些 人 凭 着 血 气 自 夸 ， 我 也 要 自 夸 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29008', '47', '11', '19', '你 们 既 是 精 明 人 ， 就 能 甘 心 忍 耐 愚 妄 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29009', '47', '11', '20', '假 若 有 人 强 你 们 作 奴 仆 ， 或 侵 吞 你 们 ， 或 掳 掠 你 们 ， 或 侮 慢 你 们 ， 或 打 你 们 的 脸 ， 你 们 都 能 忍 耐 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29010', '47', '11', '21', '我 说 这 话 是 羞 辱 自 己 ， 好 像 我 们 从 前 是 软 弱 的 。 然 而 ， 人 在 何 事 上 勇 敢 ， （ 我 说 句 愚 妄 话 ， ） 我 也 勇 敢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29011', '47', '11', '22', '他 们 是 希 伯 来 人 吗 ？ 我 也 是 。 他 们 是 以 色 列 人 吗 ？ 我 也 是 。 他 们 是 亚 伯 拉 罕 的 后 裔 吗 ？ 我 也 是 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29012', '47', '11', '23', '他 们 是 基 督 的 仆 人 吗 ？ （ 我 说 句 狂 话 ， ） 我 更 是 。 我 比 他 们 多 受 劳 苦 ， 多 下 监 牢 ， 受 鞭 打 是 过 重 的 ， 冒 死 是 屡 次 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29013', '47', '11', '24', '被 犹 太 人 鞭 打 五 次 ， 每 次 四 十 减 去 一 下 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29014', '47', '11', '25', '被 棍 打 了 三 次 ； 被 石 头 打 了 一 次 ； 遇 着 船 坏 三 次 ， 一 昼 一 夜 在 深 海 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29015', '47', '11', '26', '又 屡 次 行 远 路 ， 遭 江 河 的 危 险 、 盗 贼 的 危 险 、 同 族 的 危 险 、 外 邦 人 的 危 险 、 城 里 的 危 险 、 旷 野 的 危 险 、 海 中 的 危 险 、 假 弟 兄 的 危 险 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29016', '47', '11', '27', '受 劳 碌 、 受 困 苦 ， 多 次 不 得 睡 ， 又 饥 又 渴 ， 多 次 不 得 食 ， 受 寒 冷 ， 赤 身 露 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29017', '47', '11', '28', '除 了 这 外 面 的 事 ， 还 有 为 众 教 会 挂 心 的 事 ， 天 天 压 在 我 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29018', '47', '11', '29', '有 谁 软 弱 ， 我 不 软 弱 呢 ？ 有 谁 跌 倒 ， 我 不 焦 急 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29019', '47', '11', '30', '我 若 必 须 自 夸 ， 就 夸 那 关 乎 我 软 弱 的 事 便 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29020', '47', '11', '31', '那 永 远 可 称 颂 之 主 耶 稣 的 父 神 知 道 我 不 说 谎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29021', '47', '11', '32', '在 大 马 士 革 的 亚 哩 达 王 手 下 的 提 督 把 守 大 马 士 革 城 ， 要 捉 拿 我 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29022', '47', '11', '33', '我 就 从 窗 户 中 ， 在 筐 子 里 ， 从 城 墙 上 被 人 缒 下 去 ， 脱 离 了 他 的 手 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29023', '47', '12', '1', '＜ 异 象 和 启 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29024', '47', '12', '2', '我 认 得 一 个 在 基 督 里 的 人 ， 他 前 十 四 年 被 提 到 第 三 层 天 上 去 ； （ 或 在 身 内 ， 我 不 知 道 ； 或 在 身 外 ， 我 也 不 知 道 ； 只 有 神 知 道 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29025', '47', '12', '3', '我 认 得 这 人 ； （ 或 在 身 内 ， 或 在 身 外 ， 我 都 不 知 道 ， 只 有 神 知 道 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29026', '47', '12', '4', '他 被 提 到 乐 园 里 ， 听 见 隐 秘 的 言 语 ， 是 人 不 可 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29027', '47', '12', '5', '为 这 人 ， 我 要 夸 口 ； 但 是 为 我 自 己 ， 除 了 我 的 软 弱 以 外 ， 我 并 不 夸 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29028', '47', '12', '6', '我 就 是 愿 意 夸 口 也 不 算 狂 ， 因 为 我 必 说 实 话 ； 只 是 我 禁 止 不 说 ， 恐 怕 有 人 把 我 看 高 了 ， 过 于 他 在 我 身 上 所 看 见 、 所 听 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29029', '47', '12', '7', '又 恐 怕 我 因 所 得 的 启 示 甚 大 ， 就 过 于 自 高 ， 所 以 有 一 根 刺 加 在 我 肉 体 上 ， 就 是 撒 但 的 差 役 要 攻 击 我 ， 免 得 我 过 于 自 高 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29030', '47', '12', '8', '为 这 事 ， 我 三 次 求 过 主 ， 叫 这 刺 离 开 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29031', '47', '12', '9', '他 对 我 说 ： “ 我 的 恩 典 够 你 用 的 ， 因 为 我 的 能 力 是 在 人 的 软 弱 上 显 得 完 全 。 ” 所 以 ， 我 更 喜 欢 夸 自 己 的 软 弱 ， 好 叫 基 督 的 能 力 覆 庇 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29032', '47', '12', '10', '我 为 基 督 的 缘 故 ， 就 以 软 弱 、 凌 辱 、 急 难 、 逼 迫 、 困 苦 为 可 喜 乐 的 ； 因 我 什 么 时 候 软 弱 ， 什 么 时 候 就 刚 强 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29033', '47', '12', '11', '＜ 保 罗 关 心 哥 林 多 教 会 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29034', '47', '12', '12', '我 在 你 们 中 间 ， 用 百 般 的 忍 耐 ， 藉 着 神 迹 、 奇 事 、 异 能 显 出 使 徒 的 凭 据 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29035', '47', '12', '13', '除 了 我 不 累 着 你 们 这 一 件 事 ， 你 们 还 有 什 么 事 不 及 别 的 教 会 呢 ？ 这 不 公 之 处 ， 求 你 们 饶 恕 我 吧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29036', '47', '12', '14', '如 今 ， 我 打 算 第 三 次 到 你 们 那 里 去 ， 也 必 不 累 着 你 们 ； 因 我 所 求 的 是 你 们 ， 不 是 你 们 的 财 物 。 儿 女 不 该 为 父 母 积 财 ， 父 母 该 为 儿 女 积 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29037', '47', '12', '15', '我 也 甘 心 乐 意 为 你 们 的 灵 魂 费 财 费 力 。 难 道 我 越 发 爱 你 们 ， 就 越 发 少 得 你 们 的 爱 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29038', '47', '12', '16', '罢 了 ， 我 自 己 并 没 有 累 着 你 们 ， 你 们 却 有 人 说 ， 我 是 诡 诈 ， 用 心 计 牢 笼 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29039', '47', '12', '17', '我 所 差 到 你 们 那 里 去 的 人 ， 我 藉 着 他 们 一 个 人 占 过 你 们 的 便 宜 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29040', '47', '12', '18', '我 劝 了 提 多 到 你 们 那 里 去 ， 又 差 那 位 兄 弟 与 他 同 去 。 提 多 占 过 你 们 的 便 宜 吗 ？ 我 们 行 事 ， 不 同 是 一 个 心 灵 ｛ 或 译 ： 圣 灵 ｝ 吗 ？ 不 同 是 一 个 脚 踪 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29041', '47', '12', '19', '你 们 到 如 今 ， 还 想 我 们 是 向 你 们 分 诉 ； 我 们 本 是 在 基 督 里 当 神 面 前 说 话 。 亲 爱 的 弟 兄 啊 ， 一 切 的 事 都 是 为 造 就 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29042', '47', '12', '20', '我 怕 我 再 来 的 时 候 ， 见 你 们 不 合 我 所 想 望 的 ， 你 们 见 我 也 不 合 你 们 所 想 望 的 ； 又 怕 有 纷 争 、 嫉 妒 、 恼 怒 、 结 党 、 毁 谤 、 谗 言 、 狂 傲 、 混 乱 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29043', '47', '12', '21', '且 怕 我 来 的 时 候 ， 我 的 神 叫 我 在 你 们 面 前 惭 愧 ， 又 因 许 多 人 从 前 犯 罪 ， 行 污 秽 、 奸 淫 、 邪 荡 的 事 不 肯 悔 改 ， 我 就 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29044', '47', '13', '1', '＜ 警 告 和 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29045', '47', '13', '2', '我 从 前 说 过 ， 如 今 不 在 你 们 那 里 又 说 ， 正 如 我 第 二 次 见 你 们 的 时 候 所 说 的 一 样 ， 就 是 对 那 犯 了 罪 的 和 其 余 的 人 说 ： “ 我 若 再 来 ， 必 不 宽 容 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29046', '47', '13', '3', '你 们 既 然 寻 求 基 督 在 我 里 面 说 话 的 凭 据 ， 我 必 不 宽 容 。 因 为 ， 基 督 在 你 们 身 上 不 是 软 弱 的 ， 在 你 们 里 面 是 有 大 能 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29047', '47', '13', '4', '他 因 软 弱 被 钉 在 十 字 架 上 ， 却 因 神 的 大 能 仍 然 活 着 。 我 们 也 是 这 样 同 他 软 弱 ， 但 因 神 向 你 们 所 显 的 大 能 ， 也 必 与 他 同 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29048', '47', '13', '5', '你 们 总 要 自 己 省 察 有 信 心 没 有 ， 也 要 自 己 试 验 。 岂 不 知 你 们 若 不 是 可 弃 绝 的 ， 就 有 耶 稣 基 督 在 你 们 心 里 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29049', '47', '13', '6', '我 却 盼 望 你 们 晓 得 ， 我 们 不 是 可 弃 绝 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29050', '47', '13', '7', '我 们 求 神 ， 叫 你 们 一 件 恶 事 都 不 做 ； 这 不 是 要 显 明 我 们 是 蒙 悦 纳 的 ， 是 要 你 们 行 事 端 正 ， 任 凭 人 看 我 们 是 被 弃 绝 的 吧 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29051', '47', '13', '8', '我 们 凡 事 不 能 敌 挡 真 理 ， 只 能 扶 助 真 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29052', '47', '13', '9', '即 使 我 们 软 弱 ， 你 们 刚 强 ， 我 们 也 欢 喜 ； 并 且 我 们 所 求 的 ， 就 是 你 们 作 完 全 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29053', '47', '13', '10', '所 以 ， 我 不 在 你 们 那 里 的 时 候 ， 把 这 话 写 给 你 们 ， 好 叫 我 见 你 们 的 时 候 ， 不 用 照 主 所 给 我 的 权 柄 严 厉 地 待 你 们 。 这 权 柄 原 是 为 造 就 人 ， 并 不 是 为 败 坏 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29054', '47', '13', '11', '还 有 末 了 的 话 ： 愿 弟 兄 们 都 喜 乐 。 要 作 完 全 人 ； 要 受 安 慰 ； 要 同 心 合 意 ； 要 彼 此 和 睦 。 如 此 ， 仁 爱 和 平 的 神 必 常 与 你 们 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29055', '47', '13', '12', '你 们 亲 嘴 问 安 ， 彼 此 务 要 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29056', '47', '13', '13', '众 圣 徒 都 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29057', '47', '13', '14', '愿 主 耶 稣 基 督 的 恩 惠 、 神 的 慈 爱 、 圣 灵 的 感 动 常 与 你 们 众 人 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29058', '48', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29059', '48', '1', '2', '和 一 切 与 我 同 在 的 众 弟 兄 ， 写 信 给 加 拉 太 的 各 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29060', '48', '1', '3', '愿 恩 惠 、 平 安 从 父 神 与 我 们 的 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29061', '48', '1', '4', '基 督 照 我 们 父 神 的 旨 意 ， 为 我 们 的 罪 舍 己 ， 要 救 我 们 脱 离 这 罪 恶 的 世 代 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29062', '48', '1', '5', '但 愿 荣 耀 归 于 神 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29063', '48', '1', '6', '＜ 没 有 别 的 福 音 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29064', '48', '1', '7', '那 并 不 是 福 音 ， 不 过 有 些 人 搅 扰 你 们 ， 要 把 基 督 的 福 音 更 改 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29065', '48', '1', '8', '但 无 论 是 我 们 ， 是 天 上 来 的 使 者 ， 若 传 福 音 给 你 们 ， 与 我 们 所 传 给 你 们 的 不 同 ， 他 就 应 当 被 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29066', '48', '1', '9', '我 们 已 经 说 了 ， 现 在 又 说 ， 若 有 人 传 福 音 给 你 们 ， 与 你 们 所 领 受 的 不 同 ， 他 就 应 当 被 咒 诅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29067', '48', '1', '10', '我 现 在 是 要 得 人 的 心 呢 ？ 还 是 要 得 神 的 心 呢 ？ 我 岂 是 讨 人 的 喜 欢 吗 ？ 若 仍 旧 讨 人 的 喜 欢 ， 我 就 不 是 基 督 的 仆 人 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29068', '48', '1', '11', '＜ 保 罗 怎 样 成 为 使 徒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29069', '48', '1', '12', '因 为 我 不 是 从 人 领 受 的 ， 也 不 是 人 教 导 我 的 ， 乃 是 从 耶 稣 基 督 启 示 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29070', '48', '1', '13', '你 们 听 见 我 从 前 在 犹 太 教 中 所 行 的 事 ， 怎 样 极 力 逼 迫 残 害 神 的 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29071', '48', '1', '14', '我 又 在 犹 太 教 中 ， 比 我 本 国 许 多 同 岁 的 人 更 有 长 进 ， 为 我 祖 宗 的 遗 传 更 加 热 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29072', '48', '1', '15', '然 而 ， 那 把 我 从 母 腹 里 分 别 出 来 、 又 施 恩 召 我 的 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29073', '48', '1', '16', '既 然 乐 意 将 他 儿 子 启 示 在 我 心 里 ， 叫 我 把 他 传 在 外 邦 人 中 ， 我 就 没 有 与 属 血 气 的 人 商 量 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29074', '48', '1', '17', '也 没 有 上 耶 路 撒 冷 去 见 那 些 比 我 先 作 使 徒 的 ， 惟 独 往 阿 拉 伯 去 ， 后 又 回 到 大 马 士 革 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29075', '48', '1', '18', '过 了 三 年 ， 才 上 耶 路 撒 冷 去 见 矶 法 ， 和 他 同 住 了 十 五 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29076', '48', '1', '19', '至 于 别 的 使 徒 ， 除 了 主 的 兄 弟 雅 各 ， 我 都 没 有 看 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29077', '48', '1', '20', '我 写 给 你 们 的 不 是 谎 话 ， 这 是 我 在 神 面 前 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29078', '48', '1', '21', '以 后 我 到 了 叙 利 亚 和 基 利 家 境 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29079', '48', '1', '22', '那 时 ， 犹 太 信 基 督 的 各 教 会 都 没 有 见 过 我 的 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29080', '48', '1', '23', '不 过 听 说 那 从 前 逼 迫 我 们 的 ， 现 在 传 扬 他 原 先 所 残 害 的 真 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29081', '48', '1', '24', '他 们 就 为 我 的 缘 故 ， 归 荣 耀 给 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29082', '48', '2', '1', '＜ 保 罗 被 其 他 的 使 徒 接 纳 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29083', '48', '2', '2', '我 是 奉 启 示 上 去 的 ， 把 我 在 外 邦 人 中 所 传 的 福 音 对 弟 兄 们 陈 说 ； 却 是 背 地 里 对 那 有 名 望 之 人 说 的 ， 惟 恐 我 现 在 ， 或 是 从 前 ， 徒 然 奔 跑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29084', '48', '2', '3', '但 与 我 同 去 的 提 多 ， 虽 是 希 腊 人 ， 也 没 有 勉 强 他 受 割 礼 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29085', '48', '2', '4', '因 为 有 偷 着 引 进 来 的 假 弟 兄 ， 私 下 窥 探 我 们 在 基 督 耶 稣 里 的 自 由 ， 要 叫 我 们 作 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29086', '48', '2', '5', '我 们 就 是 一 刻 的 工 夫 也 没 有 容 让 顺 服 他 们 ， 为 要 叫 福 音 的 真 理 仍 存 在 你 们 中 间 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29087', '48', '2', '6', '至 于 那 些 有 名 望 的 ， 不 论 他 是 何 等 人 ， 都 与 我 无 干 。 神 不 以 外 貌 取 人 。 那 些 有 名 望 的 ， 并 没 有 加 增 我 什 么 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29088', '48', '2', '7', '反 倒 看 见 了 主 托 我 传 福 音 给 那 未 受 割 礼 的 人 ， 正 如 托 彼 得 传 福 音 给 那 受 割 礼 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29089', '48', '2', '8', '（ 那 感 动 彼 得 、 叫 他 为 受 割 礼 之 人 作 使 徒 的 ， 也 感 动 我 ， 叫 我 为 外 邦 人 作 使 徒 ； ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29090', '48', '2', '9', '又 知 道 所 赐 给 我 的 恩 典 ， 那 称 为 教 会 柱 石 的 雅 各 、 矶 法 、 约 翰 ， 就 向 我 和 巴 拿 巴 用 右 手 行 相 交 之 礼 ， 叫 我 们 往 外 邦 人 那 里 去 ， 他 们 往 受 割 礼 的 人 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29091', '48', '2', '10', '只 是 愿 意 我 们 记 念 穷 人 ； 这 也 是 我 本 来 热 心 去 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29092', '48', '2', '11', '＜ 保 罗 在 安 提 阿 责 备 彼 得 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29093', '48', '2', '12', '从 雅 各 那 里 来 的 人 未 到 以 先 ， 他 和 外 邦 人 一 同 吃 饭 ， 及 至 他 们 来 到 ， 他 因 怕 奉 割 礼 的 人 ， 就 退 去 与 外 邦 人 隔 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29094', '48', '2', '13', '其 余 的 犹 太 人 也 都 随 着 他 装 假 ， 甚 至 连 巴 拿 巴 也 随 伙 装 假 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29095', '48', '2', '14', '但 我 一 看 见 他 们 行 的 不 正 ， 与 福 音 的 真 理 不 合 ， 就 在 众 人 面 前 对 矶 法 说 ： “ 你 既 是 犹 太 人 ， 若 随 外 邦 人 行 事 ， 不 随 犹 太 人 行 事 ， 怎 么 还 勉 强 外 邦 人 随 犹 太 人 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29096', '48', '2', '15', '＜ 犹 太 人 和 外 邦 人 都 因 信 得 救 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29097', '48', '2', '16', '既 知 道 人 称 义 不 是 因 行 律 法 ， 乃 是 因 信 耶 稣 基 督 ， 连 我 们 也 信 了 基 督 耶 稣 ， 使 我 们 因 信 基 督 称 义 ， 不 因 行 律 法 称 义 ； 因 为 凡 有 血 气 的 ， 没 有 一 人 因 行 律 法 称 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29098', '48', '2', '17', '我 们 若 求 在 基 督 里 称 义 ， 却 仍 旧 是 罪 人 ， 难 道 基 督 是 叫 人 犯 罪 的 吗 ？ 断 乎 不 是 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29099', '48', '2', '18', '我 素 来 所 拆 毁 的 ， 若 重 新 建 造 ， 这 就 证 明 自 己 是 犯 罪 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29100', '48', '2', '19', '我 因 律 法 ， 就 向 律 法 死 了 ， 叫 我 可 以 向 神 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29101', '48', '2', '20', '我 已 经 与 基 督 同 钉 十 字 架 ， 现 在 活 着 的 不 再 是 我 ， 乃 是 基 督 在 我 里 面 活 着 ； 并 且 我 如 今 在 肉 身 活 着 ， 是 因 信 神 的 儿 子 而 活 ； 他 是 爱 我 ， 为 我 舍 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29102', '48', '2', '21', '我 不 废 掉 神 的 恩 ； 义 若 是 藉 着 律 法 得 的 ， 基 督 就 是 徒 然 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29103', '48', '3', '1', '＜ 律 法 和 信 心 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29104', '48', '3', '2', '我 只 要 问 你 们 这 一 件 ： 你 们 受 了 圣 灵 ， 是 因 行 律 法 呢 ？ 是 因 听 信 福 音 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29105', '48', '3', '3', '你 们 既 靠 圣 灵 入 门 ， 如 今 还 靠 肉 身 成 全 吗 ？ 你 们 是 这 样 的 无 知 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29106', '48', '3', '4', '你 们 受 苦 如 此 之 多 ， 都 是 徒 然 的 吗 ？ 难 道 果 真 是 徒 然 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29107', '48', '3', '5', '那 赐 给 你 们 圣 灵 ， 又 在 你 们 中 间 行 异 能 的 ， 是 因 你 们 行 律 法 呢 ？ 是 因 你 们 听 信 福 音 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29108', '48', '3', '6', '正 如 “ 亚 伯 拉 罕 信 神 ， 这 就 算 为 他 的 义 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29109', '48', '3', '7', '所 以 ， 你 们 要 知 道 ： 那 以 信 为 本 的 人 ， 就 是 亚 伯 拉 罕 的 子 孙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29110', '48', '3', '8', '并 且 圣 经 既 然 预 先 看 明 ， 神 要 叫 外 邦 人 因 信 称 义 ， 就 早 已 传 福 音 给 亚 伯 拉 罕 ， 说 ： “ 万 国 都 必 因 你 得 福 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29111', '48', '3', '9', '可 见 那 以 信 为 本 的 人 和 有 信 心 的 亚 伯 拉 罕 一 同 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29112', '48', '3', '10', '凡 以 行 律 法 为 本 的 ， 都 是 被 咒 诅 的 ； 因 为 经 上 记 着 ： “ 凡 不 常 照 律 法 书 上 所 记 一 切 之 事 去 行 的 ， 就 被 咒 诅 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29113', '48', '3', '11', '没 有 一 个 人 靠 着 律 法 在 神 面 前 称 义 ， 这 是 明 显 的 ； 因 为 经 上 说 ： “ 义 人 必 因 信 得 生 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29114', '48', '3', '12', '律 法 原 不 本 乎 信 ， 只 说 ： “ 行 这 些 事 的 ， 就 必 因 此 活 着 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29115', '48', '3', '13', '基 督 既 为 我 们 受 ｛ 原 文 是 成 ｝ 了 咒 诅 ， 就 赎 出 我 们 脱 离 律 法 的 咒 诅 ； 因 为 经 上 记 着 ： “ 凡 挂 在 木 头 上 都 是 被 咒 诅 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29116', '48', '3', '14', '这 便 叫 亚 伯 拉 罕 的 福 ， 因 基 督 耶 稣 可 以 临 到 外 邦 人 ， 使 我 们 因 信 得 着 所 应 许 的 圣 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29117', '48', '3', '15', '＜ 律 法 和 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29118', '48', '3', '16', '所 应 许 的 原 是 向 亚 伯 拉 罕 和 他 子 孙 说 的 。 神 并 不 是 说 “ 众 子 孙 ” ， 指 着 许 多 人 ， 乃 是 说 “ 你 那 一 个 子 孙 ” ， 指 着 一 个 人 ， 就 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29119', '48', '3', '17', '我 是 这 么 说 ， 神 预 先 所 立 的 约 ， 不 能 被 那 四 百 三 十 年 以 后 的 律 法 废 掉 ， 叫 应 许 归 于 虚 空 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29120', '48', '3', '18', '因 为 承 受 产 业 ， 若 本 乎 律 法 ， 就 不 本 乎 应 许 ； 但 神 是 凭 着 应 许 把 产 业 赐 给 亚 伯 拉 罕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29121', '48', '3', '19', '这 样 说 来 ， 律 法 是 为 什 么 有 的 呢 ？ 原 是 为 过 犯 添 上 的 ， 等 候 那 蒙 应 许 的 子 孙 来 到 ， 并 且 是 藉 天 使 经 中 保 之 手 设 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29122', '48', '3', '20', '但 中 保 本 不 是 为 一 面 作 的 ； 神 却 是 一 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29123', '48', '3', '21', '＜ 奴 仆 和 儿 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29124', '48', '3', '22', '但 圣 经 把 众 人 都 圈 在 罪 里 ， 使 所 应 许 的 福 因 信 耶 稣 基 督 ， 归 给 那 信 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29125', '48', '3', '23', '但 这 因 信 得 救 的 理 还 未 来 以 先 ， 我 们 被 看 守 在 律 法 之 下 ， 直 圈 到 那 将 来 的 真 道 显 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29126', '48', '3', '24', '这 样 ， 律 法 是 我 们 训 蒙 的 师 傅 ， 引 我 们 到 基 督 那 里 ， 使 我 们 因 信 称 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29127', '48', '3', '25', '但 这 因 信 得 救 的 理 既 然 来 到 ， 我 们 从 此 就 不 在 师 傅 的 手 下 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29128', '48', '3', '26', '所 以 ， 你 们 因 信 基 督 耶 稣 都 是 神 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29129', '48', '3', '27', '你 们 受 洗 归 入 基 督 的 都 是 披 戴 基 督 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29130', '48', '3', '28', '并 不 分 犹 太 人 、 希 腊 人 ， 自 主 的 、 为 奴 的 ， 或 男 或 女 ， 因 为 你 们 在 基 督 耶 稣 里 都 成 为 一 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29131', '48', '3', '29', '你 们 既 属 乎 基 督 ， 就 是 亚 伯 拉 罕 的 后 裔 ， 是 照 着 应 许 承 受 产 业 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29132', '48', '4', '1', '我 说 那 承 受 产 业 的 ， 虽 然 是 全 业 的 主 人 ， 但 为 孩 童 的 时 候 却 与 奴 仆 毫 无 分 别 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29133', '48', '4', '2', '乃 在 师 傅 和 管 家 的 手 下 ， 直 等 他 父 亲 预 定 的 时 候 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29134', '48', '4', '3', '我 们 为 孩 童 的 时 候 ， 受 管 于 世 俗 小 学 之 下 ， 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29135', '48', '4', '4', '及 至 时 候 满 足 ， 神 就 差 遣 他 的 儿 子 ， 为 女 子 所 生 ， 且 生 在 律 法 以 下 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29136', '48', '4', '5', '要 把 律 法 以 下 的 人 赎 出 来 ， 叫 我 们 得 着 儿 子 的 名 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29137', '48', '4', '6', '你 们 既 为 儿 子 ， 神 就 差 他 儿 子 的 灵 进 入 你 们 ｛ 原 文 是 我 们 ｝ 的 心 ， 呼 叫 ： “ 阿 爸 ！ 父 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29138', '48', '4', '7', '可 见 ， 从 此 以 后 ， 你 不 是 奴 仆 ， 乃 是 儿 子 了 ； 既 是 儿 子 ， 就 靠 着 神 为 后 嗣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29139', '48', '4', '8', '＜ 保 罗 关 怀 加 拉 太 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29140', '48', '4', '9', '现 在 你 们 既 然 认 识 神 ， 更 可 说 是 被 神 所 认 识 的 ， 怎 么 还 要 归 回 那 懦 弱 无 用 的 小 学 ， 情 愿 再 给 他 作 奴 仆 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29141', '48', '4', '10', '你 们 谨 守 日 子 、 月 份 、 节 期 、 年 份 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29142', '48', '4', '11', '我 为 你 们 害 怕 ， 惟 恐 我 在 你 们 身 上 是 枉 费 了 工 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29143', '48', '4', '12', '弟 兄 们 ， 我 劝 你 们 要 像 我 一 样 ， 因 为 我 也 像 你 们 一 样 。 你 们 一 点 没 有 亏 负 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29144', '48', '4', '13', '你 们 知 道 我 头 一 次 传 福 音 给 你 们 ， 是 因 为 身 体 有 疾 病 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29145', '48', '4', '14', '你 们 为 我 身 体 的 缘 故 受 试 炼 ， 没 有 轻 看 我 ， 也 没 有 厌 弃 我 ， 反 倒 接 待 我 ， 如 同 神 的 使 者 ， 如 同 基 督 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29146', '48', '4', '15', '你 们 当 日 所 夸 的 福 气 在 哪 里 呢 ？ 那 时 你 们 若 能 行 ， 就 是 把 自 己 的 眼 睛 剜 出 来 给 我 ， 也 都 情 愿 。 这 是 我 可 以 给 你 们 作 见 证 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29147', '48', '4', '16', '如 今 我 将 真 理 告 诉 你 们 ， 就 成 了 你 们 的 仇 敌 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29148', '48', '4', '17', '那 些 人 热 心 待 你 们 ， 却 不 是 好 意 ， 是 要 离 间 你 们 ｛ 原 文 是 把 你 们 关 在 外 面 ｝ ， 叫 你 们 热 心 待 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29149', '48', '4', '18', '在 善 事 上 ， 常 用 热 心 待 人 原 是 好 的 ， 却 不 单 我 与 你 们 同 在 的 时 候 才 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29150', '48', '4', '19', '我 小 子 啊 ， 我 为 你 们 再 受 生 产 之 苦 ， 直 等 到 基 督 成 形 在 你 们 心 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29151', '48', '4', '20', '我 巴 不 得 现 今 在 你 们 那 里 ， 改 换 口 气 ， 因 我 为 你 们 心 里 作 难 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29152', '48', '4', '21', '＜ 夏 甲 和 撒 拉 的 例 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29153', '48', '4', '22', '因 为 律 法 上 记 着 ， 亚 伯 拉 罕 有 两 个 儿 子 ， 一 个 是 使 女 生 的 ， 一 个 是 自 主 之 妇 人 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29154', '48', '4', '23', '然 而 ， 那 使 女 所 生 的 是 按 着 血 气 生 的 ； 那 自 主 之 妇 人 所 生 的 是 凭 着 应 许 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29155', '48', '4', '24', '这 都 是 比 方 ： 那 两 个 妇 人 就 是 两 约 。 一 约 是 出 于 西 奈 山 ， 生 子 为 奴 ， 乃 是 夏 甲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29156', '48', '4', '25', '这 夏 甲 二 字 是 指 着 阿 拉 伯 的 西 奈 山 ， 与 现 在 的 耶 路 撒 冷 同 类 ， 因 耶 路 撒 冷 和 她 的 儿 女 都 是 为 奴 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29157', '48', '4', '26', '但 那 在 上 的 耶 路 撒 冷 是 自 主 的 ， 她 是 我 们 的 母 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29158', '48', '4', '27', '因 为 经 上 记 着 ： 不 怀 孕 、 不 生 养 的 ， 你 要 欢 乐 ； 未 曾 经 过 产 难 的 ， 你 要 高 声 欢 呼 ； 因 为 没 有 丈 夫 的 ， 比 有 丈 夫 的 儿 女 更 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29159', '48', '4', '28', '弟 兄 们 ， 我 们 是 凭 着 应 许 作 儿 女 ， 如 同 以 撒 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29160', '48', '4', '29', '当 时 ， 那 按 着 血 气 生 的 逼 迫 了 那 按 着 圣 灵 生 的 ， 现 在 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29161', '48', '4', '30', '然 而 经 上 是 怎 么 说 的 呢 ？ 是 说 ： “ 把 使 女 和 她 儿 子 赶 出 去 ！ 因 为 使 女 的 儿 子 不 可 与 自 主 妇 人 的 儿 子 一 同 承 受 产 业 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29162', '48', '4', '31', '弟 兄 们 ， 这 样 看 来 ， 我 们 不 是 使 女 的 儿 女 ， 乃 是 自 主 妇 人 的 儿 女 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29163', '48', '5', '1', '基 督 释 放 了 我 们 ， 叫 我 们 得 以 自 由 。 所 以 要 站 立 得 稳 ， 不 要 再 被 奴 仆 的 轭 挟 制 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29164', '48', '5', '2', '＜ 基 督 徒 的 自 由 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29165', '48', '5', '3', '我 再 指 着 凡 受 割 礼 的 人 确 实 地 说 ， 他 是 欠 着 行 全 律 法 的 债 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29166', '48', '5', '4', '你 们 这 要 靠 律 法 称 义 的 ， 是 与 基 督 隔 绝 ， 从 恩 典 中 坠 落 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29167', '48', '5', '5', '我 们 靠 着 圣 灵 ， 凭 着 信 心 ， 等 候 所 盼 望 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29168', '48', '5', '6', '原 来 在 基 督 耶 稣 里 ， 受 割 礼 不 受 割 礼 全 无 功 效 ， 惟 独 使 人 生 发 仁 爱 的 信 心 才 有 功 效 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29169', '48', '5', '7', '你 们 向 来 跑 得 好 ， 有 谁 拦 阻 你 们 ， 叫 你 们 不 顺 从 真 理 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29170', '48', '5', '8', '这 样 的 劝 导 不 是 出 于 那 召 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29171', '48', '5', '9', '一 点 面 酵 能 使 全 团 都 发 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29172', '48', '5', '10', '我 在 主 里 很 信 你 们 必 不 怀 别 样 的 心 ； 但 搅 扰 你 们 的 ， 无 论 是 谁 ， 必 担 当 他 的 罪 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29173', '48', '5', '11', '弟 兄 们 ， 我 若 仍 旧 传 割 礼 ， 为 什 么 还 受 逼 迫 呢 ？ 若 是 这 样 ， 那 十 字 架 讨 厌 的 地 方 就 没 有 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29174', '48', '5', '12', '恨 不 得 那 搅 乱 你 们 的 人 把 自 己 割 绝 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29175', '48', '5', '13', '弟 兄 们 ， 你 们 蒙 召 是 要 得 自 由 ， 只 是 不 可 将 你 们 的 自 由 当 作 放 纵 情 欲 的 机 会 ， 总 要 用 爱 心 互 相 服 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29176', '48', '5', '14', '因 为 全 律 法 都 包 在 “ 爱 人 如 己 ” 这 一 句 话 之 内 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29177', '48', '5', '15', '你 们 要 谨 慎 ， 若 相 咬 相 吞 ， 只 怕 要 彼 此 消 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29178', '48', '5', '16', '＜ 圣 灵 的 果 子 和 肉 体 的 恶 行 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29179', '48', '5', '17', '因 为 情 欲 和 圣 灵 相 争 ， 圣 灵 和 情 欲 相 争 ， 这 两 个 是 彼 此 相 敌 ， 使 你 们 不 能 做 所 愿 意 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29180', '48', '5', '18', '但 你 们 若 被 圣 灵 引 导 ， 就 不 在 律 法 以 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29181', '48', '5', '19', '情 欲 的 事 都 是 显 而 易 见 的 ， 就 如 奸 淫 、 污 秽 、 邪 荡 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29182', '48', '5', '20', '拜 偶 像 、 邪 术 、 仇 恨 、 争 竞 、 忌 恨 、 恼 怒 、 结 党 、 纷 争 、 异 端 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29183', '48', '5', '21', '嫉 妒 ｛ 有 古 卷 加 ： 凶 杀 二 字 ｝ 、 醉 酒 、 荒 宴 等 类 。 我 从 前 告 诉 你 们 ， 现 在 又 告 诉 你 们 ， 行 这 样 事 的 人 必 不 能 承 受 神 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29184', '48', '5', '22', '圣 灵 所 结 的 果 子 ， 就 是 仁 爱 、 喜 乐 、 和 平 、 忍 耐 、 恩 慈 、 良 善 、 信 实 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29185', '48', '5', '23', '温 柔 、 节 制 。 这 样 的 事 没 有 律 法 禁 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29186', '48', '5', '24', '凡 属 基 督 耶 稣 的 人 ， 是 已 经 把 肉 体 连 肉 体 的 邪 情 私 欲 同 钉 在 十 字 架 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29187', '48', '5', '25', '我 们 若 是 靠 圣 灵 得 生 ， 就 当 靠 圣 灵 行 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29188', '48', '5', '26', '不 要 贪 图 虚 名 ， 彼 此 惹 气 ， 互 相 嫉 妒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29189', '48', '6', '1', '＜ 各 人 的 重 担 要 互 相 担 当 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29190', '48', '6', '2', '你 们 各 人 的 重 担 要 互 相 担 当 ， 如 此 ， 就 完 全 了 基 督 的 律 法 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29191', '48', '6', '3', '人 若 无 有 ， 自 己 还 以 为 有 ， 就 是 自 欺 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29192', '48', '6', '4', '各 人 应 当 察 验 自 己 的 行 为 ； 这 样 ， 他 所 夸 的 就 专 在 自 己 ， 不 在 别 人 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29193', '48', '6', '5', '因 为 各 人 必 担 当 自 己 的 担 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29194', '48', '6', '6', '在 道 理 上 受 教 的 ， 当 把 一 切 需 用 的 供 给 施 教 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29195', '48', '6', '7', '不 要 自 欺 ， 神 是 轻 慢 不 得 的 。 人 种 的 是 什 么 ， 收 的 也 是 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29196', '48', '6', '8', '顺 着 情 欲 撒 种 的 ， 必 从 情 欲 收 败 坏 ； 顺 着 圣 灵 撒 种 的 ， 必 从 圣 灵 收 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29197', '48', '6', '9', '我 们 行 善 ， 不 可 丧 志 ； 若 不 灰 心 ， 到 了 时 候 就 要 收 成 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29198', '48', '6', '10', '所 以 ， 有 了 机 会 就 当 向 众 人 行 善 ， 向 信 徒 一 家 的 人 更 当 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29199', '48', '6', '11', '＜ 警 告 和 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29200', '48', '6', '12', '凡 希 图 外 貌 体 面 的 人 都 勉 强 你 们 受 割 礼 ， 无 非 是 怕 自 己 为 基 督 的 十 字 架 受 逼 迫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29201', '48', '6', '13', '他 们 那 些 受 割 礼 的 ， 连 自 己 也 不 守 律 法 ； 他 们 愿 意 你 们 受 割 礼 ， 不 过 要 藉 着 你 们 的 肉 体 夸 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29202', '48', '6', '14', '但 我 断 不 以 别 的 夸 口 ， 只 夸 我 们 主 耶 稣 基 督 的 十 字 架 ； 因 这 十 字 架 ， 就 我 而 论 ， 世 界 已 经 钉 在 十 字 架 上 ； 就 世 界 而 论 ， 我 已 经 钉 在 十 字 架 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29203', '48', '6', '15', '受 割 礼 不 受 割 礼 都 无 关 紧 要 ， 要 紧 的 就 是 作 新 造 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29204', '48', '6', '16', '凡 照 此 理 而 行 的 ， 愿 平 安 、 怜 悯 加 给 他 们 ， 和 神 的 以 色 列 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29205', '48', '6', '17', '从 今 以 后 ， 人 都 不 要 搅 扰 我 ， 因 为 我 身 上 带 着 耶 稣 的 印 记 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29206', '48', '6', '18', '弟 兄 们 ， 愿 我 主 耶 稣 基 督 的 恩 常 在 你 们 心 里 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29207', '49', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29208', '49', '1', '2', '愿 恩 惠 、 平 安 从 神 我 们 的 父 和 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29209', '49', '1', '3', '＜ 基 督 里 的 属 灵 福 气 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29210', '49', '1', '4', '就 如 神 从 创 立 世 界 以 前 ， 在 基 督 里 拣 选 了 我 们 ， 使 我 们 在 他 面 前 成 为 圣 洁 ， 无 有 瑕 疵 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29211', '49', '1', '5', '又 因 爱 我 们 ， 就 按 着 自 己 的 意 旨 所 喜 悦 的 ， 预 定 我 们 藉 着 耶 稣 基 督 得 儿 子 的 名 分 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29212', '49', '1', '6', '使 他 荣 耀 的 恩 典 得 著 称 赞 ； 这 恩 典 是 他 在 爱 子 里 所 赐 给 我 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29213', '49', '1', '7', '我 们 藉 这 爱 子 的 血 得 蒙 救 赎 ， 过 犯 得 以 赦 免 ， 乃 是 照 他 丰 富 的 恩 典 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29214', '49', '1', '8', '这 恩 典 是 神 用 诸 般 智 慧 聪 明 ， 充 充 足 足 赏 给 我 们 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29215', '49', '1', '9', '都 是 照 他 自 己 所 预 定 的 美 意 ， 叫 我 们 知 道 他 旨 意 的 奥 秘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29216', '49', '1', '10', '要 照 所 安 排 的 ， 在 日 期 满 足 的 时 候 ， 使 天 上 、 地 上 、 一 切 所 有 的 都 在 基 督 里 面 同 归 于 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29217', '49', '1', '11', '我 们 也 在 他 里 面 得 ｛ 得 ： 或 译 成 ｝ 了 基 业 ； 这 原 是 那 位 随 己 意 行 、 做 万 事 的 ， 照 着 他 旨 意 所 预 定 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29218', '49', '1', '12', '叫 他 的 荣 耀 从 我 们 这 首 先 在 基 督 里 有 盼 望 的 人 可 以 得 著 称 赞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29219', '49', '1', '13', '你 们 既 听 见 真 理 的 道 ， 就 是 那 叫 你 们 得 救 的 福 音 ， 也 信 了 基 督 ， 既 然 信 他 ， 就 受 了 所 应 许 的 圣 灵 为 印 记 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29220', '49', '1', '14', '这 圣 灵 是 我 们 得 基 业 的 凭 据 ｛ 原 文 是 质 ｝ ， 直 等 到 神 之 民 ｛ 民 ： 原 文 是 产 业 ｝ 被 赎 ， 使 他 的 荣 耀 得 著 称 赞 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29221', '49', '1', '15', '＜ 保 罗 的 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29222', '49', '1', '16', '就 为 你 们 不 住 地 感 谢 神 。 祷 告 的 时 候 ， 常 提 到 你 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29223', '49', '1', '17', '求 我 们 主 耶 稣 基 督 的 神 ， 荣 耀 的 父 ， 将 那 赐 人 智 慧 和 启 示 的 灵 赏 给 你 们 ， 使 你 们 真 知 道 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29224', '49', '1', '18', '并 且 照 明 你 们 心 中 的 眼 睛 ， 使 你 们 知 道 他 的 恩 召 有 何 等 指 望 ， 他 在 圣 徒 中 得 的 基 业 有 何 等 丰 盛 的 荣 耀 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29225', '49', '1', '19', '并 知 道 他 向 我 们 这 信 的 人 所 显 的 能 力 是 何 等 浩 大 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29226', '49', '1', '20', '就 是 照 他 在 基 督 身 上 所 运 行 的 大 能 大 力 ， 使 他 从 死 里 复 活 ， 叫 他 在 天 上 坐 在 自 己 的 右 边 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29227', '49', '1', '21', '远 超 过 一 切 执 政 的 、 掌 权 的 、 有 能 的 、 主 治 的 ， 和 一 切 有 名 的 ； 不 但 是 今 世 的 ， 连 来 世 的 也 都 超 过 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29228', '49', '1', '22', '又 将 万 有 服 在 他 的 脚 下 ， 使 他 为 教 会 作 万 有 之 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29229', '49', '1', '23', '教 会 是 他 的 身 体 ， 是 那 充 满 万 有 者 所 充 满 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29230', '49', '2', '1', '＜ 出 死 入 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29231', '49', '2', '2', '那 时 ， 你 们 在 其 中 行 事 为 人 ， 随 从 今 世 的 风 俗 ， 顺 服 空 中 掌 权 者 的 首 领 ， 就 是 现 今 在 悖 逆 之 子 心 中 运 行 的 邪 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29232', '49', '2', '3', '我 们 从 前 也 都 在 他 们 中 间 ， 放 纵 肉 体 的 私 欲 ， 随 着 肉 体 和 心 中 所 喜 好 的 去 行 ， 本 为 可 怒 之 子 ， 和 别 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29233', '49', '2', '4', '然 而 ， 神 既 有 丰 富 的 怜 悯 ， 因 他 爱 我 们 的 大 爱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29234', '49', '2', '5', '当 我 们 死 在 过 犯 中 的 时 候 ， 便 叫 我 们 与 基 督 一 同 活 过 来 。 你 们 得 救 是 本 乎 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29235', '49', '2', '6', '他 又 叫 我 们 与 基 督 耶 稣 一 同 复 活 ， 一 同 坐 在 天 上 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29236', '49', '2', '7', '要 将 他 极 丰 富 的 恩 典 ， 就 是 他 在 基 督 耶 稣 里 向 我 们 所 施 的 恩 慈 ， 显 明 给 后 来 的 世 代 看 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29237', '49', '2', '8', '你 们 得 救 是 本 乎 恩 ， 也 因 着 信 ； 这 并 不 是 出 于 自 己 ， 乃 是 神 所 赐 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29238', '49', '2', '9', '也 不 是 出 于 行 为 ， 免 得 有 人 自 夸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29239', '49', '2', '10', '我 们 原 是 他 的 工 作 ， 在 基 督 耶 稣 里 造 成 的 ， 为 要 叫 我 们 行 善 ， 就 是 神 所 预 备 叫 我 们 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29240', '49', '2', '11', '＜ 在 基 督 里 合 一 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29241', '49', '2', '12', '那 时 ， 你 们 与 基 督 无 关 ， 在 以 色 列 国 民 以 外 ， 在 所 应 许 的 诸 约 上 是 局 外 人 ， 并 且 活 在 世 上 没 有 指 望 ， 没 有 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29242', '49', '2', '13', '你 们 从 前 远 离 神 的 人 ， 如 今 却 在 基 督 耶 稣 里 ， 靠 着 他 的 血 ， 已 经 得 亲 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29243', '49', '2', '14', '因 他 使 我 们 和 睦 ｛ 原 文 是 因 他 是 我 们 的 和 睦 ｝ ， 将 两 下 合 而 为 一 ， 拆 毁 了 中 间 隔 断 的 墙 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29244', '49', '2', '15', '而 且 以 自 己 的 身 体 废 掉 冤 仇 ， 就 是 那 记 在 律 法 上 的 规 条 ， 为 要 将 两 下 藉 着 自 己 造 成 一 个 新 人 ， 如 此 便 成 就 了 和 睦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29245', '49', '2', '16', '既 在 十 字 架 上 灭 了 冤 仇 ， 便 藉 这 十 字 架 使 两 下 归 为 一 体 ， 与 神 和 好 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29246', '49', '2', '17', '并 且 来 传 和 平 的 福 音 给 你 们 远 处 的 人 ， 也 给 那 近 处 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29247', '49', '2', '18', '因 为 我 们 两 下 藉 着 他 被 一 个 圣 灵 所 感 ， 得 以 进 到 父 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29248', '49', '2', '19', '这 样 ， 你 们 不 再 作 外 人 和 客 旅 ， 是 与 圣 徒 同 国 ， 是 神 家 里 的 人 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29249', '49', '2', '20', '并 且 被 建 造 在 使 徒 和 先 知 的 根 基 上 ， 有 基 督 耶 稣 自 己 为 房 角 石 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29250', '49', '2', '21', '各 ｛ 或 译 ： 全 ｝ 房 靠 他 联 络 得 合 式 ， 渐 渐 成 为 主 的 圣 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29251', '49', '2', '22', '你 们 也 靠 他 同 被 建 造 ， 成 为 神 藉 着 圣 灵 居 住 的 所 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29252', '49', '3', '1', '＜ 保 罗 奉 差 向 外 邦 人 传 福 音 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29253', '49', '3', '2', '谅 必 你 们 曾 听 见 神 赐 恩 给 我 ， 将 关 切 你 们 的 职 分 托 付 我 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29254', '49', '3', '3', '用 启 示 使 我 知 道 福 音 的 奥 秘 ， 正 如 我 以 前 略 略 写 过 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29255', '49', '3', '4', '你 们 念 了 ， 就 能 晓 得 我 深 知 基 督 的 奥 秘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29256', '49', '3', '5', '这 奥 秘 在 以 前 的 世 代 没 有 叫 人 知 道 ， 像 如 今 藉 着 圣 灵 启 示 他 的 圣 使 徒 和 先 知 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29257', '49', '3', '6', '这 奥 秘 就 是 外 邦 人 在 基 督 耶 稣 里 ， 藉 着 福 音 ， 得 以 同 为 后 嗣 ， 同 为 一 体 ， 同 蒙 应 许 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29258', '49', '3', '7', '我 作 了 这 福 音 的 执 事 ， 是 照 神 的 恩 赐 ， 这 恩 赐 是 照 他 运 行 的 大 能 赐 给 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29259', '49', '3', '8', '我 本 来 比 众 圣 徒 中 最 小 的 还 小 ， 然 而 他 还 赐 我 这 恩 典 ， 叫 我 把 基 督 那 测 不 透 的 丰 富 传 给 外 邦 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29260', '49', '3', '9', '又 使 众 人 都 明 白 ， 这 历 代 以 来 隐 藏 在 创 造 万 物 之 神 里 的 奥 秘 是 如 何 安 排 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29261', '49', '3', '10', '为 要 藉 着 教 会 使 天 上 执 政 的 、 掌 权 的 ， 现 在 得 知 神 百 般 的 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29262', '49', '3', '11', '这 是 照 神 从 万 世 以 前 ， 在 我 们 主 基 督 耶 稣 里 所 定 的 旨 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29263', '49', '3', '12', '我 们 因 信 耶 稣 ， 就 在 他 里 面 放 胆 无 惧 ， 笃 信 不 疑 地 来 到 神 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29264', '49', '3', '13', '所 以 ， 我 求 你 们 不 要 因 我 为 你 们 所 受 的 患 难 丧 胆 ， 这 原 是 你 们 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29265', '49', '3', '14', '＜ 明 白 基 督 的 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29266', '49', '3', '15', '（ 天 上 地 上 的 各 ｛ 或 译 ： 全 ｝ 家 ， 都 是 从 他 得 名 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29267', '49', '3', '16', '求 他 按 着 他 丰 盛 的 荣 耀 ， 藉 着 他 的 灵 ， 叫 你 们 心 里 的 力 量 刚 强 起 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29268', '49', '3', '17', '使 基 督 因 你 们 的 信 ， 住 在 你 们 心 里 ， 叫 你 们 的 爱 心 有 根 有 基 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29269', '49', '3', '18', '能 以 和 众 圣 徒 一 同 明 白 基 督 的 爱 是 何 等 长 阔 高 深 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29270', '49', '3', '19', '并 知 道 这 爱 是 过 于 人 所 能 测 度 的 ， 便 叫 神 一 切 所 充 满 的 ， 充 满 了 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29271', '49', '3', '20', '神 能 照 着 运 行 在 我 们 心 里 的 大 力 充 充 足 足 地 成 就 一 切 ， 超 过 我 们 所 求 所 想 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29272', '49', '3', '21', '但 愿 他 在 教 会 中 ， 并 在 基 督 耶 稣 里 ， 得 着 荣 耀 ， 直 到 世 世 代 代 ， 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29273', '49', '4', '1', '＜ 身 体 的 合 一 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29274', '49', '4', '2', '凡 事 谦 虚 、 温 柔 、 忍 耐 ， 用 爱 心 互 相 宽 容 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29275', '49', '4', '3', '用 和 平 彼 此 联 络 ， 竭 力 保 守 圣 灵 所 赐 合 而 为 一 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29276', '49', '4', '4', '身 体 只 有 一 个 ， 圣 灵 只 有 一 个 ， 正 如 你 们 蒙 召 同 有 一 个 指 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29277', '49', '4', '5', '一 主 ， 一 信 ， 一 洗 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29278', '49', '4', '6', '一 神 ， 就 是 众 人 的 父 ， 超 乎 众 人 之 上 ， 贯 乎 众 人 之 中 ， 也 住 在 众 人 之 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29279', '49', '4', '7', '我 们 各 人 蒙 恩 ， 都 是 照 基 督 所 量 给 各 人 的 恩 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29280', '49', '4', '8', '所 以 经 上 说 ： 他 升 上 高 天 的 时 候 ， 掳 掠 了 仇 敌 ， 将 各 样 的 恩 赐 赏 给 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29281', '49', '4', '9', '（ 既 说 升 上 ， 岂 不 是 先 降 在 地 下 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29282', '49', '4', '10', '那 降 下 的 ， 就 是 远 升 诸 天 之 上 要 充 满 万 有 的 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29283', '49', '4', '11', '他 所 赐 的 ， 有 使 徒 ， 有 先 知 ， 有 传 福 音 的 ， 有 牧 师 和 教 师 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29284', '49', '4', '12', '为 要 成 全 圣 徒 ， 各 尽 其 职 ， 建 立 基 督 的 身 体 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29285', '49', '4', '13', '直 等 到 我 们 众 人 在 真 道 上 同 归 于 一 ， 认 识 神 的 儿 子 ， 得 以 长 大 成 人 ， 满 有 基 督 长 成 的 身 量 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29286', '49', '4', '14', '使 我 们 不 再 作 小 孩 子 ， 中 了 人 的 诡 计 和 欺 骗 的 法 术 ， 被 一 切 异 教 之 风 摇 动 ， 飘 来 飘 去 ， 就 随 从 各 样 的 异 端 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29287', '49', '4', '15', '惟 用 爱 心 说 诚 实 话 ， 凡 事 长 进 ， 连 于 元 首 基 督 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29288', '49', '4', '16', '全 身 都 靠 他 联 络 得 合 式 ， 百 节 各 按 各 职 ， 照 着 各 体 的 功 用 彼 此 相 助 ， 便 叫 身 体 渐 渐 增 长 ， 在 爱 中 建 立 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29289', '49', '4', '17', '＜ 旧 人 和 新 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29290', '49', '4', '18', '他 们 心 地 昏 昧 ， 与 神 所 赐 的 生 命 隔 绝 了 ， 都 因 自 己 无 知 ， 心 里 刚 硬 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29291', '49', '4', '19', '良 心 既 然 丧 尽 ， 就 放 纵 私 欲 ， 贪 行 种 种 的 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29292', '49', '4', '20', '你 们 学 了 基 督 ， 却 不 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29293', '49', '4', '21', '如 果 你 们 听 过 他 的 道 ， 领 了 他 的 教 ， 学 了 他 的 真 理 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29294', '49', '4', '22', '就 要 脱 去 你 们 从 前 行 为 上 的 旧 人 ， 这 旧 人 是 因 私 欲 的 迷 惑 渐 渐 变 坏 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29295', '49', '4', '23', '又 要 将 你 们 的 心 志 改 换 一 新 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29296', '49', '4', '24', '并 且 穿 上 新 人 ； 这 新 人 是 照 着 神 的 形 像 造 的 ， 有 真 理 的 仁 义 和 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29297', '49', '4', '25', '＜ 新 生 活 的 守 则 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29298', '49', '4', '26', '生 气 却 不 要 犯 罪 ； 不 可 含 怒 到 日 落 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29299', '49', '4', '27', '也 不 可 给 魔 鬼 留 地 步 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29300', '49', '4', '28', '从 前 偷 窃 的 ， 不 要 再 偷 ； 总 要 劳 力 ， 亲 手 做 正 经 事 ， 就 可 有 余 分 给 那 缺 少 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29301', '49', '4', '29', '污 秽 的 言 语 一 句 不 可 出 口 ， 只 要 随 事 说 造 就 人 的 好 话 ， 叫 听 见 的 人 得 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29302', '49', '4', '30', '不 要 叫 神 的 圣 灵 担 忧 ； 你 们 原 是 受 了 他 的 印 记 ， 等 候 得 赎 的 日 子 来 到 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29303', '49', '4', '31', '一 切 苦 毒 、 恼 恨 、 忿 怒 、 嚷 闹 、 毁 谤 ， 并 一 切 的 恶 毒 ｛ 或 译 ： 阴 毒 ｝ ， 都 当 从 你 们 中 间 除 掉 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29304', '49', '4', '32', '并 要 以 恩 慈 相 待 ， 存 怜 悯 的 心 ， 彼 此 饶 恕 ， 正 如 神 在 基 督 里 饶 恕 了 你 们 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29305', '49', '5', '1', '所 以 ， 你 们 该 效 法 神 ， 好 像 蒙 慈 爱 的 儿 女 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29306', '49', '5', '2', '也 要 凭 爱 心 行 事 ， 正 如 基 督 爱 我 们 ， 为 我 们 舍 了 自 己 ， 当 作 馨 香 的 供 物 和 祭 物 ， 献 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29307', '49', '5', '3', '至 于 淫 乱 并 一 切 污 秽 ， 或 是 贪 婪 ， 在 你 们 中 间 连 提 都 不 可 ， 方 合 圣 徒 的 体 统 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29308', '49', '5', '4', '淫 词 、 妄 语 ， 和 戏 笑 的 话 都 不 相 宜 ； 总 要 说 感 谢 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29309', '49', '5', '5', '因 为 你 们 确 实 地 知 道 ， 无 论 是 淫 乱 的 ， 是 污 秽 的 ， 是 有 贪 心 的 ， 在 基 督 和 神 的 国 里 都 是 无 分 的 。 有 贪 心 的 ， 就 与 拜 偶 像 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29310', '49', '5', '6', '＜ 行 事 为 人 当 像 光 明 的 子 女 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29311', '49', '5', '7', '所 以 ， 你 们 不 要 与 他 们 同 伙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29312', '49', '5', '8', '从 前 你 们 是 暗 昧 的 ， 但 如 今 在 主 里 面 是 光 明 的 ， 行 事 为 人 就 当 像 光 明 的 子 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29313', '49', '5', '9', '光 明 所 结 的 果 子 就 是 一 切 良 善 、 公 义 、 诚 实 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29314', '49', '5', '10', '总 要 察 验 何 为 主 所 喜 悦 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29315', '49', '5', '11', '那 暗 昧 无 益 的 事 ， 不 要 与 人 同 行 ， 倒 要 责 备 行 这 事 的 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29316', '49', '5', '12', '因 为 他 们 暗 中 所 行 的 ， 就 是 提 起 来 也 是 可 耻 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29317', '49', '5', '13', '凡 事 受 了 责 备 ， 就 被 光 显 明 出 来 ， 因 为 一 切 能 显 明 的 就 是 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29318', '49', '5', '14', '所 以 主 说 ： 你 这 睡 着 的 人 当 醒 过 来 ， 从 死 里 复 活 ！ 基 督 就 要 光 照 你 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29319', '49', '5', '15', '你 们 要 谨 慎 行 事 ， 不 要 像 愚 昧 人 ， 当 像 智 慧 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29320', '49', '5', '16', '要 爱 惜 光 阴 ， 因 为 现 今 的 世 代 邪 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29321', '49', '5', '17', '不 要 作 糊 涂 人 ， 要 明 白 主 的 旨 意 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29322', '49', '5', '18', '不 要 醉 酒 ， 酒 能 使 人 放 荡 ； 乃 要 被 圣 灵 充 满 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29323', '49', '5', '19', '当 用 诗 章 、 颂 词 、 灵 歌 彼 此 对 说 ， 口 唱 心 和 地 赞 美 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29324', '49', '5', '20', '凡 事 要 奉 我 们 主 耶 稣 基 督 的 名 常 常 感 谢 父 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29325', '49', '5', '21', '又 当 存 敬 畏 基 督 的 心 ， 彼 此 顺 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29326', '49', '5', '22', '＜ 丈 夫 和 妻 子 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29327', '49', '5', '23', '因 为 丈 夫 是 妻 子 的 头 ， 如 同 基 督 是 教 会 的 头 ； 他 又 是 教 会 全 体 的 救 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29328', '49', '5', '24', '教 会 怎 样 顺 服 基 督 ， 妻 子 也 要 怎 样 凡 事 顺 服 丈 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29329', '49', '5', '25', '你 们 作 丈 夫 的 ， 要 爱 你 们 的 妻 子 ， 正 如 基 督 爱 教 会 ， 为 教 会 舍 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29330', '49', '5', '26', '要 用 水 藉 着 道 把 教 会 洗 净 ， 成 为 圣 洁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29331', '49', '5', '27', '可 以 献 给 自 己 ， 作 个 荣 耀 的 教 会 ， 毫 无 玷 污 、 皱 纹 等 类 的 病 ， 乃 是 圣 洁 没 有 瑕 疵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29332', '49', '5', '28', '丈 夫 也 当 照 样 爱 妻 子 ， 如 同 爱 自 己 的 身 子 ； 爱 妻 子 便 是 爱 自 己 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29333', '49', '5', '29', '从 来 没 有 人 恨 恶 自 己 的 身 子 ， 总 是 保 养 顾 惜 ， 正 像 基 督 待 教 会 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29334', '49', '5', '30', '因 我 们 是 他 身 上 的 肢 体 ｛ 有 古 卷 加 ： 就 是 他 的 骨 他 的 肉 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29335', '49', '5', '31', '为 这 个 缘 故 ， 人 要 离 开 父 母 ， 与 妻 子 连 合 ， 二 人 成 为 一 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29336', '49', '5', '32', '这 是 极 大 的 奥 秘 ， 但 我 是 指 着 基 督 和 教 会 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29337', '49', '5', '33', '然 而 ， 你 们 各 人 都 当 爱 妻 子 ， 如 同 爱 自 己 一 样 。 妻 子 也 当 敬 重 她 的 丈 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29338', '49', '6', '1', '＜ 儿 女 和 父 母 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29339', '49', '6', '2', '“ 要 孝 敬 父 母 ， 使 你 得 福 ， 在 世 长 寿 。 ” 这 是 第 一 条 带 应 许 的 诫 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29340', '49', '6', '3', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29341', '49', '6', '4', '你 们 作 父 亲 的 ， 不 要 惹 儿 女 的 气 ， 只 要 照 着 主 的 教 训 和 警 戒 养 育 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29342', '49', '6', '5', '＜ 仆 人 和 主 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29343', '49', '6', '6', '不 要 只 在 眼 前 事 奉 ， 像 是 讨 人 喜 欢 的 ， 要 像 基 督 的 仆 人 ， 从 心 里 遵 行 神 的 旨 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29344', '49', '6', '7', '甘 心 事 奉 ， 好 像 服 事 主 ， 不 像 服 事 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29345', '49', '6', '8', '因 为 晓 得 各 人 所 行 的 善 事 ， 不 论 是 为 奴 的 ， 是 自 主 的 ， 都 必 按 所 行 的 得 主 的 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29346', '49', '6', '9', '你 们 作 主 人 的 ， 待 仆 人 也 是 一 理 ， 不 要 威 吓 他 们 。 因 为 知 道 ， 他 们 和 你 们 同 有 一 位 主 在 天 上 ； 他 并 不 偏 待 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29347', '49', '6', '10', '＜ 与 邪 恶 争 战 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29348', '49', '6', '11', '要 穿 戴 神 所 赐 的 全 副 军 装 ， 就 能 抵 挡 魔 鬼 的 诡 计 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29349', '49', '6', '12', '因 我 们 并 不 是 与 属 血 气 的 争 战 ｛ 原 文 是 摔 跤 ； 下 同 ｝ ， 乃 是 与 那 些 执 政 的 、 掌 权 的 、 管 辖 这 幽 暗 世 界 的 ， 以 及 天 空 属 灵 气 的 恶 魔 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29350', '49', '6', '13', '所 以 ， 要 拿 起 神 所 赐 的 全 副 军 装 ， 好 在 磨 难 的 日 子 抵 挡 仇 敌 ， 并 且 成 就 了 一 切 ， 还 能 站 立 得 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29351', '49', '6', '14', '所 以 要 站 稳 了 ， 用 真 理 当 作 带 子 束 腰 ， 用 公 义 当 作 护 心 镜 遮 胸 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29352', '49', '6', '15', '又 用 平 安 的 福 音 当 作 预 备 走 路 的 鞋 穿 在 脚 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29353', '49', '6', '16', '此 外 ， 又 拿 着 信 德 当 作 盾 牌 ， 可 以 灭 尽 那 恶 者 一 切 的 火 箭 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29354', '49', '6', '17', '并 戴 上 救 恩 的 头 盔 ， 拿 着 圣 灵 的 宝 剑 ， 就 是 神 的 道 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29355', '49', '6', '18', '靠 着 圣 灵 ， 随 时 多 方 祷 告 祈 求 ； 并 要 在 此 警 醒 不 倦 ， 为 众 圣 徒 祈 求 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29356', '49', '6', '19', '也 为 我 祈 求 ， 使 我 得 着 口 才 ， 能 以 放 胆 开 口 讲 明 福 音 的 奥 秘 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29357', '49', '6', '20', '（ 我 为 这 福 音 的 奥 秘 作 了 带 锁 炼 的 使 者 ， ） 并 使 我 照 着 当 尽 的 本 分 放 胆 讲 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29358', '49', '6', '21', '＜ 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29359', '49', '6', '22', '我 特 意 打 发 他 到 你 们 那 里 去 ， 好 叫 你 们 知 道 我 们 的 光 景 ， 又 叫 他 安 慰 你 们 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29360', '49', '6', '23', '愿 平 安 、 仁 爱 、 信 心 从 父 神 和 主 耶 稣 基 督 归 与 弟 兄 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29361', '49', '6', '24', '并 愿 所 有 诚 心 爱 我 们 主 耶 稣 基 督 的 人 都 蒙 恩 惠 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29362', '50', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29363', '50', '1', '2', '愿 恩 惠 、 平 安 从 神 我 们 的 父 并 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29364', '50', '1', '3', '＜ 保 罗 为 腓 立 比 信 徒 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29365', '50', '1', '4', '每 逢 为 你 们 众 人 祈 求 的 时 候 ， 常 是 欢 欢 喜 喜 地 祈 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29366', '50', '1', '5', '因 为 从 头 一 天 直 到 如 今 ， 你 们 是 同 心 合 意 地 兴 旺 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29367', '50', '1', '6', '我 深 信 那 在 你 们 心 里 动 了 善 工 的 ， 必 成 全 这 工 ， 直 到 耶 稣 基 督 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29368', '50', '1', '7', '我 为 你 们 众 人 有 这 样 的 意 念 ， 原 是 应 当 的 ； 因 你 们 常 在 我 心 里 ， 无 论 我 是 在 捆 锁 之 中 ， 是 辩 明 证 实 福 音 的 时 候 ， 你 们 都 与 我 一 同 得 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29369', '50', '1', '8', '我 体 会 基 督 耶 稣 的 心 肠 ， 切 切 地 想 念 你 们 众 人 ； 这 是 神 可 以 给 我 作 见 证 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29370', '50', '1', '9', '我 所 祷 告 的 ， 就 是 要 你 们 的 爱 心 在 知 识 和 各 样 见 识 上 多 而 又 多 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29371', '50', '1', '10', '使 你 们 能 分 别 是 非 ｛ 或 译 ： 喜 爱 那 美 好 的 事 ｝ ， 作 诚 实 无 过 的 人 ， 直 到 基 督 的 日 子 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29372', '50', '1', '11', '并 靠 着 耶 稣 基 督 结 满 了 仁 义 的 果 子 ， 叫 荣 耀 称 赞 归 与 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29373', '50', '1', '12', '＜ 我 活 着 就 是 基 督 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29374', '50', '1', '13', '以 致 我 受 的 捆 锁 在 御 营 全 军 和 其 余 的 人 中 ， 已 经 显 明 是 为 基 督 的 缘 故 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29375', '50', '1', '14', '并 且 那 在 主 里 的 弟 兄 多 半 因 我 受 的 捆 锁 就 笃 信 不 疑 ， 越 发 放 胆 传 神 的 道 ， 无 所 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29376', '50', '1', '15', '有 的 传 基 督 是 出 于 嫉 妒 纷 争 ， 也 有 的 是 出 于 好 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29377', '50', '1', '16', '这 一 等 是 出 于 爱 心 ， 知 道 我 是 为 辩 明 福 音 设 立 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29378', '50', '1', '17', '那 一 等 传 基 督 是 出 于 结 党 ， 并 不 诚 实 ， 意 思 要 加 增 我 捆 锁 的 苦 楚 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29379', '50', '1', '18', '这 有 何 妨 呢 ？ 或 是 假 意 ， 或 是 真 心 ， 无 论 怎 样 ， 基 督 究 竟 被 传 开 了 。 为 此 ， 我 就 欢 喜 ， 并 且 还 要 欢 喜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29380', '50', '1', '19', '因 为 我 知 道 ， 这 事 藉 着 你 们 的 祈 祷 和 耶 稣 基 督 之 灵 的 帮 助 ， 终 必 叫 我 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29381', '50', '1', '20', '照 着 我 所 切 慕 、 所 盼 望 的 ， 没 有 一 事 叫 我 羞 愧 。 只 要 凡 事 放 胆 ， 无 论 是 生 是 死 ， 总 叫 基 督 在 我 身 上 照 常 显 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29382', '50', '1', '21', '因 我 活 着 就 是 基 督 ， 我 死 了 就 有 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29383', '50', '1', '22', '但 我 在 肉 身 活 着 ， 若 成 就 我 工 夫 的 果 子 ， 我 就 不 知 道 该 挑 选 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29384', '50', '1', '23', '我 正 在 两 难 之 间 ， 情 愿 离 世 与 基 督 同 在 ， 因 为 这 是 好 得 无 比 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29385', '50', '1', '24', '然 而 ， 我 在 肉 身 活 着 ， 为 你 们 更 是 要 紧 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29386', '50', '1', '25', '我 既 然 这 样 深 信 ， 就 知 道 仍 要 住 在 世 间 ， 且 与 你 们 众 人 同 住 ， 使 你 们 在 所 信 的 道 上 又 长 进 又 喜 乐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29387', '50', '1', '26', '叫 你 们 在 基 督 耶 稣 里 的 欢 乐 ， 因 我 再 到 你 们 那 里 去 ， 就 越 发 加 增 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29388', '50', '1', '27', '只 要 你 们 行 事 为 人 与 基 督 的 福 音 相 称 ， 叫 我 或 来 见 你 们 ， 或 不 在 你 们 那 里 ， 可 以 听 见 你 们 的 景 况 ， 知 道 你 们 同 有 一 个 心 志 ， 站 立 得 稳 ， 为 所 信 的 福 音 齐 心 努 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29389', '50', '1', '28', '凡 事 不 怕 敌 人 的 惊 吓 ， 这 是 证 明 他 们 沉 沦 ， 你 们 得 救 都 是 出 于 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29390', '50', '1', '29', '因 为 你 们 蒙 恩 ， 不 但 得 以 信 服 基 督 ， 并 要 为 他 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29391', '50', '1', '30', '你 们 的 争 战 ， 就 与 你 们 在 我 身 上 从 前 所 看 见 、 现 在 所 听 见 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29392', '50', '2', '1', '＜ 以 基 督 的 心 为 心 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29393', '50', '2', '2', '你 们 就 要 意 念 相 同 ， 爱 心 相 同 ， 有 一 样 的 心 思 ， 有 一 样 的 意 念 ， 使 我 的 喜 乐 可 以 满 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29394', '50', '2', '3', '凡 事 不 可 结 党 ， 不 可 贪 图 虚 浮 的 荣 耀 ； 只 要 存 心 谦 卑 ， 各 人 看 别 人 比 自 己 强 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29395', '50', '2', '4', '各 人 不 要 单 顾 自 己 的 事 ， 也 要 顾 别 人 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29396', '50', '2', '5', '你 们 当 以 基 督 耶 稣 的 心 为 心 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29397', '50', '2', '6', '他 本 有 神 的 形 像 ， 不 以 自 己 与 神 同 等 为 强 夺 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29398', '50', '2', '7', '反 倒 虚 己 ， 取 了 奴 仆 的 形 像 ， 成 为 人 的 样 式 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29399', '50', '2', '8', '既 有 人 的 样 子 ， 就 自 己 卑 微 ， 存 心 顺 服 ， 以 至 于 死 ， 且 死 在 十 字 架 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29400', '50', '2', '9', '所 以 ， 神 将 他 升 为 至 高 ， 又 赐 给 他 那 超 乎 万 名 之 上 的 名 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29401', '50', '2', '10', '叫 一 切 在 天 上 的 、 地 上 的 ， 和 地 底 下 的 ， 因 耶 稣 的 名 无 不 屈 膝 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29402', '50', '2', '11', '无 不 口 称 “ 耶 稣 基 督 为 主 ” ， 使 荣 耀 归 与 父 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29403', '50', '2', '12', '＜ 在 这 世 上 像 明 光 照 耀 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29404', '50', '2', '13', '因 为 你 们 立 志 行 事 都 是 神 在 你 们 心 里 运 行 ， 为 要 成 就 他 的 美 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29405', '50', '2', '14', '凡 所 行 的 ， 都 不 要 发 怨 言 ， 起 争 论 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29406', '50', '2', '15', '使 你 们 无 可 指 摘 ， 诚 实 无 伪 ， 在 这 弯 曲 悖 谬 的 世 代 作 神 无 瑕 疵 的 儿 女 。 你 们 显 在 这 世 代 中 ， 好 像 明 光 照 耀 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29407', '50', '2', '16', '将 生 命 的 道 表 明 出 来 ， 叫 我 在 基 督 的 日 子 好 夸 我 没 有 空 跑 ， 也 没 有 徒 劳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29408', '50', '2', '17', '我 以 你 们 的 信 心 为 供 献 的 祭 物 ， 我 若 被 浇 奠 在 其 上 ， 也 是 喜 乐 ， 并 且 与 你 们 众 人 一 同 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29409', '50', '2', '18', '你 们 也 要 照 样 喜 乐 ， 并 且 与 我 一 同 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29410', '50', '2', '19', '＜ 提 摩 太 和 以 巴 弗 提 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29411', '50', '2', '20', '因 为 我 没 有 别 人 与 我 同 心 ， 实 在 挂 念 你 们 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29412', '50', '2', '21', '别 人 都 求 自 己 的 事 ， 并 不 求 耶 稣 基 督 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29413', '50', '2', '22', '但 你 们 知 道 提 摩 太 的 明 证 ； 他 兴 旺 福 音 ， 与 我 同 劳 ， 待 我 像 儿 子 待 父 亲 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29414', '50', '2', '23', '所 以 ， 我 一 看 出 我 的 事 要 怎 样 了 结 ， 就 盼 望 立 刻 打 发 他 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29415', '50', '2', '24', '但 我 靠 着 主 自 信 我 也 必 快 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29416', '50', '2', '25', '然 而 ， 我 想 必 须 打 发 以 巴 弗 提 到 你 们 那 里 去 。 他 是 我 的 兄 弟 ， 与 我 一 同 做 工 ， 一 同 当 兵 ， 是 你 们 所 差 遣 的 ， 也 是 供 给 我 需 用 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29417', '50', '2', '26', '他 很 想 念 你 们 众 人 ， 并 且 极 其 难 过 ， 因 为 你 们 听 见 他 病 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29418', '50', '2', '27', '他 实 在 是 病 了 ， 几 乎 要 死 ； 然 而 神 怜 恤 他 ， 不 但 怜 恤 他 ， 也 怜 恤 我 ， 免 得 我 忧 上 加 忧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29419', '50', '2', '28', '所 以 我 越 发 急 速 打 发 他 去 ， 叫 你 们 再 见 他 ， 就 可 以 喜 乐 ， 我 也 可 以 少 些 忧 愁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29420', '50', '2', '29', '故 此 ， 你 们 要 在 主 里 欢 欢 乐 乐 地 接 待 他 ， 而 且 要 尊 重 这 样 的 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29421', '50', '2', '30', '因 他 为 做 基 督 的 工 夫 ， 几 乎 至 死 ， 不 顾 性 命 ， 要 补 足 你 们 供 给 我 的 不 及 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29422', '50', '3', '1', '＜ 真 正 的 义 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29423', '50', '3', '2', '应 当 防 备 犬 类 ， 防 备 作 恶 的 ， 防 备 妄 自 行 割 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29424', '50', '3', '3', '因 为 真 受 割 礼 的 ， 乃 是 我 们 这 以 神 的 灵 敬 拜 、 在 基 督 耶 稣 里 夸 口 、 不 靠 着 肉 体 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29425', '50', '3', '4', '其 实 ， 我 也 可 以 靠 肉 体 ； 若 是 别 人 想 他 可 以 靠 肉 体 ， 我 更 可 以 靠 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29426', '50', '3', '5', '我 第 八 天 受 割 礼 ； 我 是 以 色 列 族 、 便 雅 悯 支 派 的 人 ， 是 希 伯 来 人 所 生 的 希 伯 来 人 。 就 律 法 说 ， 我 是 法 利 赛 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29427', '50', '3', '6', '就 热 心 说 ， 我 是 逼 迫 教 会 的 ； 就 律 法 上 的 义 说 ， 我 是 无 可 指 摘 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29428', '50', '3', '7', '只 是 我 先 前 以 为 与 我 有 益 的 ， 我 现 在 因 基 督 都 当 作 有 损 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29429', '50', '3', '8', '不 但 如 此 ， 我 也 将 万 事 当 作 有 损 的 ， 因 我 以 认 识 我 主 基 督 耶 稣 为 至 宝 。 我 为 他 已 经 丢 弃 万 事 ， 看 作 粪 土 ， 为 要 得 着 基 督 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29430', '50', '3', '9', '并 且 得 以 在 他 里 面 ， 不 是 有 自 己 因 律 法 而 得 的 义 ， 乃 是 有 信 基 督 的 义 ， 就 是 因 信 神 而 来 的 义 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29431', '50', '3', '10', '使 我 认 识 基 督 ， 晓 得 他 复 活 的 大 能 ， 并 且 晓 得 和 他 一 同 受 苦 ， 效 法 他 的 死 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29432', '50', '3', '11', '或 者 我 也 得 以 从 死 里 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29433', '50', '3', '12', '＜ 向 着 标 竿 直 跑 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29434', '50', '3', '13', '弟 兄 们 ， 我 不 是 以 为 自 己 已 经 得 着 了 ； 我 只 有 一 件 事 ， 就 是 忘 记 背 后 ， 努 力 面 前 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29435', '50', '3', '14', '向 着 标 竿 直 跑 ， 要 得 神 在 基 督 耶 稣 里 从 上 面 召 我 来 得 的 奖 赏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29436', '50', '3', '15', '所 以 我 们 中 间 ， 凡 是 完 全 人 总 要 存 这 样 的 心 ； 若 在 什 么 事 上 存 别 样 的 心 ， 神 也 必 以 此 指 示 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29437', '50', '3', '16', '然 而 ， 我 们 到 了 什 么 地 步 ， 就 当 照 着 什 么 地 步 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29438', '50', '3', '17', '弟 兄 们 ， 你 们 要 一 同 效 法 我 ， 也 当 留 意 看 那 些 照 我 们 榜 样 行 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29439', '50', '3', '18', '因 为 有 许 多 人 行 事 是 基 督 十 字 架 的 仇 敌 。 我 屡 次 告 诉 你 们 ， 现 在 又 流 泪 地 告 诉 你 们 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29440', '50', '3', '19', '他 们 的 结 局 就 是 沉 沦 ； 他 们 的 神 就 是 自 己 的 肚 腹 。 他 们 以 自 己 的 羞 辱 为 荣 耀 ， 专 以 地 上 的 事 为 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29441', '50', '3', '20', '我 们 却 是 天 上 的 国 民 ， 并 且 等 候 救 主 ， 就 是 主 耶 稣 基 督 从 天 上 降 临 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29442', '50', '3', '21', '他 要 按 着 那 能 叫 万 有 归 服 自 己 的 大 能 ， 将 我 们 这 卑 贱 的 身 体 改 变 形 状 ， 和 他 自 己 荣 耀 的 身 体 相 似 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29443', '50', '4', '1', '我 所 亲 爱 、 所 想 念 的 弟 兄 们 ， 你 们 就 是 我 的 喜 乐 ， 我 的 冠 冕 。 我 亲 爱 的 弟 兄 ， 你 们 应 当 靠 主 站 立 得 稳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29444', '50', '4', '2', '＜ 保 罗 的 劝 导 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29445', '50', '4', '3', '我 也 求 你 这 真 实 同 负 一 轭 的 ， 帮 助 这 两 个 女 人 ， 因 为 她 们 在 福 音 上 曾 与 我 一 同 劳 苦 ； 还 有 革 利 免 ， 并 其 余 和 我 一 同 做 工 的 ， 他 们 的 名 字 都 在 生 命 册 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29446', '50', '4', '4', '你 们 要 靠 主 常 常 喜 乐 。 我 再 说 ， 你 们 要 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29447', '50', '4', '5', '当 叫 众 人 知 道 你 们 谦 让 的 心 。 主 已 经 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29448', '50', '4', '6', '应 当 一 无 挂 虑 ， 只 要 凡 事 藉 着 祷 告 、 祈 求 ， 和 感 谢 ， 将 你 们 所 要 的 告 诉 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29449', '50', '4', '7', '神 所 赐 、 出 人 意 外 的 平 安 必 在 基 督 耶 稣 里 保 守 你 们 的 心 怀 意 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29450', '50', '4', '8', '弟 兄 们 ， 我 还 有 未 尽 的 话 ： 凡 是 真 实 的 、 可 敬 的 、 公 义 的 、 清 洁 的 、 可 爱 的 、 有 美 名 的 ， 若 有 什 么 德 行 ， 若 有 什 么 称 赞 ， 这 些 事 你 们 都 要 思 念 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29451', '50', '4', '9', '你 们 在 我 身 上 所 学 习 的 ， 所 领 受 的 ， 所 听 见 的 ， 所 看 见 的 ， 这 些 事 你 们 都 要 去 行 ， 赐 平 安 的 神 就 必 与 你 们 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29452', '50', '4', '10', '＜ 为 馈 送 而 致 谢 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29453', '50', '4', '11', '我 并 不 是 因 缺 乏 说 这 话 ； 我 无 论 在 什 么 景 况 都 可 以 知 足 ， 这 是 我 已 经 学 会 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29454', '50', '4', '12', '我 知 道 怎 样 处 卑 贱 ， 也 知 道 怎 样 处 丰 富 ； 或 饱 足 ， 或 饥 饿 ； 或 有 余 ， 或 缺 乏 ， 随 事 随 在 ， 我 都 得 了 秘 诀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29455', '50', '4', '13', '我 靠 着 那 加 给 我 力 量 的 ， 凡 事 都 能 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29456', '50', '4', '14', '然 而 ， 你 们 和 我 同 受 患 难 原 是 美 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29457', '50', '4', '15', '腓 立 比 人 哪 ， 你 们 也 知 道 我 初 传 福 音 离 了 马 其 顿 的 时 候 ， 论 到 授 受 的 事 ， 除 了 你 们 以 外 ， 并 没 有 别 的 教 会 供 给 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29458', '50', '4', '16', '就 是 我 在 帖 撒 罗 尼 迦 ， 你 们 也 一 次 两 次 地 打 发 人 供 给 我 的 需 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29459', '50', '4', '17', '我 并 不 求 什 么 馈 送 ， 所 求 的 就 是 你 们 的 果 子 渐 渐 增 多 ， 归 在 你 们 的 帐 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29460', '50', '4', '18', '但 我 样 样 都 有 ， 并 且 有 余 。 我 已 经 充 足 ， 因 我 从 以 巴 弗 提 受 了 你 们 的 馈 送 ， 当 作 极 美 的 香 气 ， 为 神 所 收 纳 、 所 喜 悦 的 祭 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29461', '50', '4', '19', '我 的 神 必 照 他 荣 耀 的 丰 富 ， 在 基 督 耶 稣 里 ， 使 你 们 一 切 所 需 用 的 都 充 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29462', '50', '4', '20', '愿 荣 耀 归 给 我 们 的 父 神 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29463', '50', '4', '21', '＜ 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29464', '50', '4', '22', '众 圣 徒 都 问 你 们 安 。 在 凯 撒 家 里 的 人 特 特 地 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29465', '50', '4', '23', '愿 主 耶 稣 基 督 的 恩 常 在 你 们 心 里 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29466', '51', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29467', '51', '1', '2', '写 信 给 歌 罗 西 的 圣 徒 ， 在 基 督 里 有 忠 心 的 弟 兄 。 愿 恩 惠 、 平 安 从 神 我 们 的 父 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29468', '51', '1', '3', '＜ 为 信 徒 感 谢 神 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29469', '51', '1', '4', '因 听 见 你 们 在 基 督 耶 稣 里 的 信 心 ， 并 向 众 圣 徒 的 爱 心 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29470', '51', '1', '5', '是 为 那 给 你 们 存 在 天 上 的 盼 望 ； 这 盼 望 就 是 你 们 从 前 在 福 音 真 理 的 道 上 所 听 见 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29471', '51', '1', '6', '这 福 音 传 到 你 们 那 里 ， 也 传 到 普 天 之 下 ， 并 且 结 果 ， 增 长 ， 如 同 在 你 们 中 间 ， 自 从 你 们 听 见 福 音 ， 真 知 道 神 恩 惠 的 日 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29472', '51', '1', '7', '正 如 你 们 从 我 们 所 亲 爱 、 一 同 作 仆 人 的 以 巴 弗 所 学 的 。 他 为 我 们 ｛ 有 古 卷 ： 你 们 ｝ 作 了 基 督 忠 心 的 执 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29473', '51', '1', '8', '也 把 你 们 因 圣 灵 所 存 的 爱 心 告 诉 了 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29474', '51', '1', '9', '＜ 基 督 的 位 格 和 工 作 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29475', '51', '1', '10', '好 叫 你 们 行 事 为 人 对 得 起 主 ， 凡 事 蒙 他 喜 悦 ， 在 一 切 善 事 上 结 果 子 ， 渐 渐 地 多 知 道 神 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29476', '51', '1', '11', '照 他 荣 耀 的 权 能 ， 得 以 在 各 样 的 力 上 加 力 ， 好 叫 你 们 凡 事 欢 欢 喜 喜 地 忍 耐 宽 容 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29477', '51', '1', '12', '又 感 谢 父 ， 叫 我 们 能 与 众 圣 徒 在 光 明 中 同 得 基 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29478', '51', '1', '13', '他 救 了 我 们 脱 离 黑 暗 的 权 势 ， 把 我 们 迁 到 他 爱 子 的 国 里 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29479', '51', '1', '14', '我 们 在 爱 子 里 得 蒙 救 赎 ， 罪 过 得 以 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29480', '51', '1', '15', '爱 子 是 那 不 能 看 见 之 神 的 像 ， 是 首 生 的 ， 在 一 切 被 造 的 以 先 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29481', '51', '1', '16', '因 为 万 有 都 是 靠 他 造 的 ， 无 论 是 天 上 的 ， 地 上 的 ； 能 看 见 的 ， 不 能 看 见 的 ； 或 是 有 位 的 ， 主 治 的 ， 执 政 的 ， 掌 权 的 ； 一 概 都 是 藉 着 他 造 的 ， 又 是 为 他 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29482', '51', '1', '17', '他 在 万 有 之 先 ； 万 有 也 靠 他 而 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29483', '51', '1', '18', '他 也 是 教 会 全 体 之 首 。 他 是 元 始 ， 是 从 死 里 首 先 复 生 的 ， 使 他 可 以 在 凡 事 上 居 首 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29484', '51', '1', '19', '因 为 父 喜 欢 叫 一 切 的 丰 盛 在 他 里 面 居 住 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29485', '51', '1', '20', '既 然 藉 着 他 在 十 字 架 上 所 流 的 血 成 就 了 和 平 ， 便 藉 着 他 叫 万 有 ─ ─ 无 论 是 地 上 的 、 天 上 的 ─ ─ 都 与 自 己 和 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29486', '51', '1', '21', '你 们 从 前 与 神 隔 绝 ， 因 着 恶 行 ， 心 里 与 他 为 敌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29487', '51', '1', '22', '但 如 今 他 藉 着 基 督 的 肉 身 受 死 ， 叫 你 们 与 自 己 和 好 ， 都 成 了 圣 洁 ， 没 有 瑕 疵 ， 无 可 责 备 ， 把 你 们 引 到 自 己 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29488', '51', '1', '23', '只 要 你 们 在 所 信 的 道 上 恒 心 ， 根 基 稳 固 ， 坚 定 不 移 ， 不 至 被 引 动 失 去 ｛ 原 文 是 离 开 ｝ 福 音 的 盼 望 。 这 福 音 就 是 你 们 所 听 过 的 ， 也 是 传 与 普 天 下 万 人 听 的 ｛ 原 文 是 凡 受 造 的 ｝ ， 我 ─ ─ 保 罗 也 作 了 这 福 音 的 执 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29489', '51', '1', '24', '＜ 保 罗 为 教 会 的 工 作 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29490', '51', '1', '25', '我 照 神 为 你 们 所 赐 我 的 职 分 作 了 教 会 的 执 事 ， 要 把 神 的 道 理 传 得 全 备 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29491', '51', '1', '26', '这 道 理 就 是 历 世 历 代 所 隐 藏 的 奥 秘 ； 但 如 今 向 他 的 圣 徒 显 明 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29492', '51', '1', '27', '神 愿 意 叫 他 们 知 道 ， 这 奥 秘 在 外 邦 人 中 有 何 等 丰 盛 的 荣 耀 ， 就 是 基 督 在 你 们 心 里 成 了 有 荣 耀 的 盼 望 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29493', '51', '1', '28', '我 们 传 扬 他 ， 是 用 诸 般 的 智 慧 ， 劝 戒 各 人 ， 教 导 各 人 ， 要 把 各 人 在 基 督 里 完 完 全 全 地 引 到 神 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29494', '51', '1', '29', '我 也 为 此 劳 苦 ， 照 着 他 在 我 里 面 运 用 的 大 能 尽 心 竭 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29495', '51', '2', '1', '我 愿 意 你 们 晓 得 ， 我 为 你 们 和 老 底 嘉 人 ， 并 一 切 没 有 与 我 亲 自 见 面 的 人 ， 是 何 等 地 尽 心 竭 力 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29496', '51', '2', '2', '要 叫 他 们 的 心 得 安 慰 ， 因 爱 心 互 相 联 络 ， 以 致 丰 丰 足 足 在 悟 性 中 有 充 足 的 信 心 ， 使 他 们 真 知 神 的 奥 秘 ， 就 是 基 督 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29497', '51', '2', '3', '所 积 蓄 的 一 切 智 慧 知 识 ， 都 在 他 里 面 藏 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29498', '51', '2', '4', '我 说 这 话 ， 免 得 有 人 用 花 言 巧 语 迷 惑 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29499', '51', '2', '5', '我 身 子 虽 与 你 们 相 离 ， 心 却 与 你 们 同 在 ， 见 你 们 循 规 蹈 矩 ， 信 基 督 的 心 也 坚 固 ， 我 就 欢 喜 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29500', '51', '2', '6', '＜ 基 督 里 生 命 的 丰 盛 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29501', '51', '2', '7', '在 他 里 面 生 根 建 造 ， 信 心 坚 固 ， 正 如 你 们 所 领 的 教 训 ， 感 谢 的 心 也 更 增 长 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29502', '51', '2', '8', '你 们 要 谨 慎 ， 恐 怕 有 人 用 他 的 理 学 和 虚 空 的 妄 言 ， 不 照 着 基 督 ， 乃 照 人 间 的 遗 传 和 世 上 的 小 学 就 把 你 们 掳 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29503', '51', '2', '9', '因 为 神 本 性 一 切 的 丰 盛 都 有 形 有 体 地 居 住 在 基 督 里 面 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29504', '51', '2', '10', '你 们 在 他 里 面 也 得 了 丰 盛 。 他 是 各 样 执 政 掌 权 者 的 元 首 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29505', '51', '2', '11', '你 们 在 他 里 面 也 受 了 不 是 人 手 所 行 的 割 礼 ， 乃 是 基 督 使 你 们 脱 去 肉 体 情 欲 的 割 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29506', '51', '2', '12', '你 们 既 受 洗 与 他 一 同 埋 葬 ， 也 就 在 此 与 他 一 同 复 活 ， 都 因 信 那 叫 他 从 死 里 复 活 神 的 功 用 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29507', '51', '2', '13', '你 们 从 前 在 过 犯 和 未 受 割 礼 的 肉 体 中 死 了 ， 神 赦 免 了 你 们 ｛ 或 译 ： 我 们 ｝ 一 切 过 犯 ， 便 叫 你 们 与 基 督 一 同 活 过 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29508', '51', '2', '14', '又 涂 抹 了 在 律 例 上 所 写 、 攻 击 我 们 、 有 碍 于 我 们 的 字 据 ， 把 它 撤 去 ， 钉 在 十 字 架 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29509', '51', '2', '15', '既 将 一 切 执 政 的 、 掌 权 的 掳 来 ， 明 显 给 众 人 看 ， 就 仗 着 十 字 架 夸 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29510', '51', '2', '16', '所 以 ， 不 拘 在 饮 食 上 ， 或 节 期 、 月 朔 、 安 息 日 都 不 可 让 人 论 断 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29511', '51', '2', '17', '这 些 原 是 后 事 的 影 儿 ； 那 形 体 却 是 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29512', '51', '2', '18', '不 可 让 人 因 着 故 意 谦 虚 和 敬 拜 天 使 ， 就 夺 去 你 们 的 奖 赏 。 这 等 人 拘 泥 在 所 见 过 的 ｛ 有 古 卷 ： 这 等 人 窥 察 所 没 有 见 过 的 ｝ ， 随 着 自 己 的 欲 心 ， 无 故 地 自 高 自 大 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29513', '51', '2', '19', '不 持 定 元 首 。 全 身 既 然 靠 着 他 ， 筋 节 得 以 相 助 联 络 ， 就 因 神 大 得 长 进 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29514', '51', '2', '20', '＜ 基 督 里 的 新 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29515', '51', '2', '21', '');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29516', '51', '2', '22', '这 都 是 照 人 所 吩 咐 、 所 教 导 的 。 说 到 这 一 切 ， 正 用 的 时 候 就 都 败 坏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29517', '51', '2', '23', '这 些 规 条 使 人 徒 有 智 慧 之 名 ， 用 私 意 崇 拜 ， 自 表 谦 卑 ， 苦 待 己 身 ， 其 实 在 克 制 肉 体 的 情 欲 上 是 毫 无 功 效 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29518', '51', '3', '1', '所 以 ， 你 们 若 真 与 基 督 一 同 复 活 ， 就 当 求 在 上 面 的 事 ； 那 里 有 基 督 坐 在 神 的 右 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29519', '51', '3', '2', '你 们 要 思 念 上 面 的 事 ， 不 要 思 念 地 上 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29520', '51', '3', '3', '因 为 你 们 已 经 死 了 ， 你 们 的 生 命 与 基 督 一 同 藏 在 神 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29521', '51', '3', '4', '基 督 是 我 们 的 生 命 ， 他 显 现 的 时 候 ， 你 们 也 要 与 他 一 同 显 现 在 荣 耀 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29522', '51', '3', '5', '所 以 ， 要 治 死 你 们 在 地 上 的 肢 体 ， 就 如 淫 乱 、 污 秽 、 邪 情 、 恶 欲 ， 和 贪 婪 （ 贪 婪 就 与 拜 偶 像 一 样 ） 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29523', '51', '3', '6', '因 这 些 事 ， 神 的 忿 怒 必 临 到 那 悖 逆 之 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29524', '51', '3', '7', '当 你 们 在 这 些 事 中 活 着 的 时 候 ， 也 曾 这 样 行 过 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29525', '51', '3', '8', '但 现 在 你 们 要 弃 绝 这 一 切 的 事 ， 以 及 恼 恨 、 忿 怒 、 恶 毒 ｛ 或 译 ： 阴 毒 ｝ 、 毁 谤 ， 并 口 中 污 秽 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29526', '51', '3', '9', '不 要 彼 此 说 谎 ； 因 你 们 已 经 脱 去 旧 人 和 旧 人 的 行 为 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29527', '51', '3', '10', '穿 上 了 新 人 。 这 新 人 在 知 识 上 渐 渐 更 新 ， 正 如 造 他 主 的 形 像 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29528', '51', '3', '11', '在 此 并 不 分 希 腊 人 、 犹 太 人 ， 受 割 礼 的 、 未 受 割 礼 的 ， 化 外 人 、 西 古 提 人 ， 为 奴 的 、 自 主 的 ， 惟 有 基 督 是 包 括 一 切 ， 又 住 在 各 人 之 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29529', '51', '3', '12', '所 以 ， 你 们 既 是 神 的 选 民 ， 圣 洁 蒙 爱 的 人 ， 就 要 存 ｛ 原 文 是 穿 ； 下 同 ｝ 怜 悯 、 恩 慈 、 谦 虚 、 温 柔 、 忍 耐 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29530', '51', '3', '13', '倘 若 这 人 与 那 人 有 嫌 隙 ， 总 要 彼 此 包 容 ， 彼 此 饶 恕 ； 主 怎 样 饶 恕 了 你 们 ， 你 们 也 要 怎 样 饶 恕 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29531', '51', '3', '14', '在 这 一 切 之 外 ， 要 存 着 爱 心 ， 爱 心 就 是 联 络 全 德 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29532', '51', '3', '15', '又 要 叫 基 督 的 平 安 在 你 们 心 里 作 主 ； 你 们 也 为 此 蒙 召 ， 归 为 一 体 ； 且 要 存 感 谢 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29533', '51', '3', '16', '当 用 各 样 的 智 慧 ， 把 基 督 的 道 理 丰 丰 富 富 地 存 在 心 里 ｛ 或 译 ： 当 把 基 督 的 道 理 丰 丰 富 富 地 存 在 心 里 ， 以 各 样 的 智 慧 ｝ ， 用 诗 章 、 颂 词 、 灵 歌 ， 彼 此 教 导 ， 互 相 劝 戒 ， 心 被 恩 感 ， 歌 颂 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29534', '51', '3', '17', '无 论 做 什 么 ， 或 说 话 或 行 事 ， 都 要 奉 主 耶 稣 的 名 ， 藉 着 他 感 谢 父 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29535', '51', '3', '18', '＜ 新 生 活 的 本 分 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29536', '51', '3', '19', '你 们 作 丈 夫 的 ， 要 爱 你 们 的 妻 子 ， 不 可 苦 待 她 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29537', '51', '3', '20', '你 们 作 儿 女 的 ， 要 凡 事 听 从 父 母 ， 因 为 这 是 主 所 喜 悦 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29538', '51', '3', '21', '你 们 作 父 亲 的 ， 不 要 惹 儿 女 的 气 ， 恐 怕 他 们 失 了 志 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29539', '51', '3', '22', '你 们 作 仆 人 的 ， 要 凡 事 听 从 你 们 肉 身 的 主 人 ， 不 要 只 在 眼 前 事 奉 ， 像 是 讨 人 喜 欢 的 ， 总 要 存 心 诚 实 敬 畏 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29540', '51', '3', '23', '无 论 做 什 么 ， 都 要 从 心 里 做 ， 像 是 给 主 做 的 ， 不 是 给 人 做 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29541', '51', '3', '24', '因 你 们 知 道 从 主 那 里 必 得 着 基 业 为 赏 赐 ； 你 们 所 事 奉 的 乃 是 主 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29542', '51', '3', '25', '那 行 不 义 的 必 受 不 义 的 报 应 ； 主 并 不 偏 待 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29543', '51', '4', '1', '你 们 作 主 人 的 ， 要 公 公 平 平 地 待 仆 人 ， 因 为 知 道 你 们 也 有 一 位 主 在 天 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29544', '51', '4', '2', '＜ 劝 导 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29545', '51', '4', '3', '也 要 为 我 们 祷 告 ， 求 神 给 我 们 开 传 道 的 门 ， 能 以 讲 基 督 的 奥 秘 （ 我 为 此 被 捆 锁 ） ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29546', '51', '4', '4', '叫 我 按 着 所 该 说 的 话 将 这 奥 秘 发 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29547', '51', '4', '5', '你 们 要 爱 惜 光 阴 ， 用 智 慧 与 外 人 交 往 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29548', '51', '4', '6', '你 们 的 言 语 要 常 常 带 着 和 气 ， 好 像 用 盐 调 和 ， 就 可 知 道 该 怎 样 回 答 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29549', '51', '4', '7', '＜ 最 后 的 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29550', '51', '4', '8', '我 特 意 打 发 他 到 你 们 那 里 去 ， 好 叫 你 们 知 道 我 们 的 光 景 ， 又 叫 他 安 慰 你 们 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29551', '51', '4', '9', '我 又 打 发 一 位 亲 爱 忠 心 的 兄 弟 阿 尼 西 谋 同 去 ； 他 也 是 你 们 那 里 的 人 。 他 们 要 把 这 里 一 切 的 事 都 告 诉 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29552', '51', '4', '10', '与 我 一 同 坐 监 的 亚 里 达 古 问 你 们 安 。 巴 拿 巴 的 表 弟 马 可 也 问 你 们 安 。 （ 说 到 这 马 可 ， 你 们 已 经 受 了 吩 咐 ； 他 若 到 了 你 们 那 里 ， 你 们 就 接 待 他 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29553', '51', '4', '11', '耶 数 又 称 为 犹 士 都 ， 也 问 你 们 安 。 奉 割 礼 的 人 中 ， 只 有 这 三 个 人 是 为 神 的 国 与 我 一 同 做 工 的 ， 也 是 叫 我 心 里 得 安 慰 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29554', '51', '4', '12', '有 你 们 那 里 的 人 ， 作 基 督 耶 稣 仆 人 的 以 巴 弗 问 你 们 安 。 他 在 祷 告 之 间 ， 常 为 你 们 竭 力 地 祈 求 ， 愿 你 们 在 神 一 切 的 旨 意 上 得 以 完 全 ， 信 心 充 足 ， 能 站 立 得 稳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29555', '51', '4', '13', '他 为 你 们 和 老 底 嘉 并 希 拉 坡 里 的 弟 兄 多 多 地 劳 苦 ， 这 是 我 可 以 给 他 作 见 证 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29556', '51', '4', '14', '所 亲 爱 的 医 生 路 加 和 底 马 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29557', '51', '4', '15', '请 问 老 底 嘉 的 弟 兄 和 宁 法 ， 并 她 家 里 的 教 会 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29558', '51', '4', '16', '你 们 念 了 这 书 信 ， 便 交 给 老 底 嘉 的 教 会 ， 叫 他 们 也 念 ； 你 们 也 要 念 从 老 底 嘉 来 的 书 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29559', '51', '4', '17', '要 对 亚 基 布 说 ： “ 务 要 谨 慎 ， 尽 你 从 主 所 受 的 职 分 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29560', '51', '4', '18', '我 ─ ─ 保 罗 亲 笔 问 你 们 安 。 你 们 要 记 念 我 的 捆 锁 。 愿 恩 惠 常 与 你 们 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29561', '52', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29562', '52', '1', '2', '＜ 帖 撒 罗 尼 迦 信 徒 的 信 心 和 榜 样 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29563', '52', '1', '3', '在 神 ─ ─ 我 们 的 父 面 前 ， 不 住 地 记 念 你 们 因 信 心 所 做 的 工 夫 ， 因 爱 心 所 受 的 劳 苦 ， 因 盼 望 我 们 主 耶 稣 基 督 所 存 的 忍 耐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29564', '52', '1', '4', '被 神 所 爱 的 弟 兄 啊 ， 我 知 道 你 们 是 蒙 拣 选 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29565', '52', '1', '5', '因 为 我 们 的 福 音 传 到 你 们 那 里 ， 不 独 在 乎 言 语 ， 也 在 乎 权 能 和 圣 灵 ， 并 充 足 的 信 心 。 正 如 你 们 知 道 ， 我 们 在 你 们 那 里 ， 为 你 们 的 缘 故 是 怎 样 为 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29566', '52', '1', '6', '并 且 你 们 在 大 难 之 中 ， 蒙 了 圣 灵 所 赐 的 喜 乐 ， 领 受 真 道 就 效 法 我 们 ， 也 效 法 了 主 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29567', '52', '1', '7', '甚 至 你 们 作 了 马 其 顿 和 亚 该 亚 所 有 信 主 之 人 的 榜 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29568', '52', '1', '8', '因 为 主 的 道 从 你 们 那 里 已 经 传 扬 出 来 。 你 们 向 神 的 信 心 不 但 在 马 其 顿 和 亚 该 亚 ， 就 是 在 各 处 也 都 传 开 了 ， 所 以 不 用 我 们 说 什 么 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29569', '52', '1', '9', '因 为 他 们 自 己 已 经 报 明 我 们 是 怎 样 进 到 你 们 那 里 ， 你 们 是 怎 样 离 弃 偶 像 ， 归 向 神 ， 要 服 事 那 又 真 又 活 的 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29570', '52', '1', '10', '等 候 他 儿 子 从 天 降 临 ， 就 是 他 从 死 里 复 活 的 ─ ─ 那 位 救 我 们 脱 离 将 来 忿 怒 的 耶 稣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29571', '52', '2', '1', '＜ 保 罗 在 帖 撒 罗 尼 迦 工 作 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29572', '52', '2', '2', '我 们 从 前 在 腓 立 比 被 害 受 辱 ， 这 是 你 们 知 道 的 ； 然 而 还 是 靠 我 们 的 神 放 开 胆 量 ， 在 大 争 战 中 把 神 的 福 音 传 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29573', '52', '2', '3', '我 们 的 劝 勉 不 是 出 于 错 误 ， 不 是 出 于 污 秽 ， 也 不 是 用 诡 诈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29574', '52', '2', '4', '但 神 既 然 验 中 了 我 们 ， 把 福 音 托 付 我 们 ， 我 们 就 照 样 讲 ， 不 是 要 讨 人 喜 欢 ， 乃 是 要 讨 那 察 验 我 们 心 的 神 喜 欢 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29575', '52', '2', '5', '因 为 我 们 从 来 没 有 用 过 谄 媚 的 话 ， 这 是 你 们 知 道 的 ； 也 没 有 藏 着 贪 心 ， 这 是 神 可 以 作 见 证 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29576', '52', '2', '6', '我 们 作 基 督 的 使 徒 ， 虽 然 可 以 叫 人 尊 重 ， 却 没 有 向 你 们 或 向 别 人 求 荣 耀 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29577', '52', '2', '7', '只 在 你 们 中 间 存 心 温 柔 ， 如 同 母 亲 乳 养 自 己 的 孩 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29578', '52', '2', '8', '我 们 既 是 这 样 爱 你 们 ， 不 但 愿 意 将 神 的 福 音 给 你 们 ， 连 自 己 的 性 命 也 愿 意 给 你 们 ， 因 你 们 是 我 们 所 疼 爱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29579', '52', '2', '9', '弟 兄 们 ， 你 们 记 念 我 们 的 辛 苦 劳 碌 ， 昼 夜 做 工 ， 传 神 的 福 音 给 你 们 ， 免 得 叫 你 们 一 人 受 累 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29580', '52', '2', '10', '我 们 向 你 们 信 主 的 人 ， 是 何 等 圣 洁 、 公 义 、 无 可 指 摘 ， 有 你 们 作 见 证 ， 也 有 神 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29581', '52', '2', '11', '你 们 也 晓 得 ， 我 们 怎 样 劝 勉 你 们 ， 安 慰 你 们 ， 嘱 咐 你 们 各 人 ， 好 像 父 亲 待 自 己 的 儿 女 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29582', '52', '2', '12', '要 叫 你 们 行 事 对 得 起 那 召 你 们 进 他 国 、 得 他 荣 耀 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29583', '52', '2', '13', '为 此 ， 我 们 也 不 住 地 感 谢 神 ， 因 你 们 听 见 我 们 所 传 神 的 道 就 领 受 了 ； 不 以 为 是 人 的 道 ， 乃 以 为 是 神 的 道 。 这 道 实 在 是 神 的 ， 并 且 运 行 在 你 们 信 主 的 人 心 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29584', '52', '2', '14', '弟 兄 们 ， 你 们 曾 效 法 犹 太 中 在 基 督 耶 稣 里 神 的 各 教 会 ； 因 为 你 们 也 受 了 本 地 人 的 苦 害 ， 像 他 们 受 了 犹 太 人 的 苦 害 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29585', '52', '2', '15', '这 犹 太 人 杀 了 主 耶 稣 和 先 知 ， 又 把 我 们 赶 出 去 。 他 们 不 得 神 的 喜 悦 ， 且 与 众 人 为 敌 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29586', '52', '2', '16', '不 许 我 们 传 道 给 外 邦 人 使 外 邦 人 得 救 ， 常 常 充 满 自 己 的 罪 恶 。 神 的 忿 怒 临 在 他 们 身 上 已 经 到 了 极 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29587', '52', '2', '17', '＜ 保 罗 希 望 再 访 问 帖 撒 罗 尼 迦 教 会 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29588', '52', '2', '18', '所 以 我 们 有 意 到 你 们 那 里 ； 我 ─ ─ 保 罗 有 一 两 次 要 去 ， 只 是 撒 但 阻 挡 了 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29589', '52', '2', '19', '我 们 的 盼 望 和 喜 乐 ， 并 所 夸 的 冠 冕 是 什 么 呢 ？ 岂 不 是 我 们 主 耶 稣 来 的 时 候 、 你 们 在 他 面 前 站 立 得 住 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29590', '52', '2', '20', '因 为 你 们 就 是 我 们 的 荣 耀 ， 我 们 的 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29591', '52', '3', '1', '我 们 既 不 能 再 忍 ， 就 愿 意 独 自 等 在 雅 典 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29592', '52', '3', '2', '打 发 我 们 的 兄 弟 在 基 督 福 音 上 作 神 执 事 的 ｛ 作 神 执 事 的 ： 有 古 卷 是 与 神 同 工 的 ｝ 提 摩 太 前 去 ， 坚 固 你 们 ， 并 在 你 们 所 信 的 道 上 劝 慰 你 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29593', '52', '3', '3', '免 得 有 人 被 诸 般 患 难 摇 动 。 因 为 你 们 自 己 知 道 ， 我 们 受 患 难 原 是 命 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29594', '52', '3', '4', '我 们 在 你 们 那 里 的 时 候 ， 预 先 告 诉 你 们 ， 我 们 必 受 患 难 ， 以 后 果 然 应 验 了 ， 你 们 也 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29595', '52', '3', '5', '为 此 ， 我 既 不 能 再 忍 ， 就 打 发 人 去 ， 要 晓 得 你 们 的 信 心 如 何 ， 恐 怕 那 诱 惑 人 的 到 底 诱 惑 了 你 们 ， 叫 我 们 的 劳 苦 归 于 徒 然 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29596', '52', '3', '6', '但 提 摩 太 刚 才 从 你 们 那 里 回 来 ， 将 你 们 信 心 和 爱 心 的 好 消 息 报 给 我 们 ， 又 说 你 们 常 常 记 念 我 们 ， 切 切 地 想 见 我 们 ， 如 同 我 们 想 见 你 们 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29597', '52', '3', '7', '所 以 ， 弟 兄 们 ， 我 们 在 一 切 困 苦 患 难 之 中 ， 因 着 你 们 的 信 心 就 得 了 安 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29598', '52', '3', '8', '你 们 若 靠 主 站 立 得 稳 ， 我 们 就 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29599', '52', '3', '9', '我 们 在 神 面 前 ， 因 着 你 们 甚 是 喜 乐 ； 为 这 一 切 喜 乐 ， 可 用 何 等 的 感 谢 为 你 们 报 答 神 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29600', '52', '3', '10', '我 们 昼 夜 切 切 地 祈 求 ， 要 见 你 们 的 面 ， 补 满 你 们 信 心 的 不 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29601', '52', '3', '11', '愿 神 ─ ─ 我 们 的 父 和 我 们 的 主 耶 稣 一 直 引 领 我 们 到 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29602', '52', '3', '12', '又 愿 主 叫 你 们 彼 此 相 爱 的 心 ， 并 爱 众 人 的 心 都 能 增 长 ， 充 足 ， 如 同 我 们 爱 你 们 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29603', '52', '3', '13', '好 使 你 们 当 我 们 主 耶 稣 同 他 众 圣 徒 来 的 时 候 ， 在 我 们 父 神 面 前 ， 心 里 坚 固 ， 成 为 圣 洁 ， 无 可 责 备 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29604', '52', '4', '1', '＜ 神 所 悦 纳 的 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29605', '52', '4', '2', '你 们 原 晓 得 ， 我 们 凭 主 耶 稣 传 给 你 们 什 么 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29606', '52', '4', '3', '神 的 旨 意 就 是 要 你 们 成 为 圣 洁 ， 远 避 淫 行 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29607', '52', '4', '4', '要 你 们 各 人 晓 得 怎 样 用 圣 洁 、 尊 贵 守 着 自 己 的 身 体 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29608', '52', '4', '5', '不 放 纵 私 欲 的 邪 情 ， 像 那 不 认 识 神 的 外 邦 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29609', '52', '4', '6', '不 要 一 个 人 在 这 事 上 越 分 ， 欺 负 他 的 弟 兄 ； 因 为 这 一 类 的 事 ， 主 必 报 应 ， 正 如 我 预 先 对 你 们 说 过 、 又 切 切 嘱 咐 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29610', '52', '4', '7', '神 召 我 们 ， 本 不 是 要 我 们 沾 染 污 秽 ， 乃 是 要 我 们 成 为 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29611', '52', '4', '8', '所 以 ， 那 弃 绝 的 ， 不 是 弃 绝 人 ， 乃 是 弃 绝 那 赐 圣 灵 给 你 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29612', '52', '4', '9', '论 到 弟 兄 们 相 爱 ， 不 用 人 写 信 给 你 们 ； 因 为 你 们 自 己 蒙 了 神 的 教 训 ， 叫 你 们 彼 此 相 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29613', '52', '4', '10', '你 们 向 马 其 顿 全 地 的 众 弟 兄 固 然 是 这 样 行 ， 但 我 劝 弟 兄 们 要 更 加 勉 励 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29614', '52', '4', '11', '又 要 立 志 作 安 静 人 ， 办 自 己 的 事 ， 亲 手 做 工 ， 正 如 我 们 从 前 所 吩 咐 你 们 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29615', '52', '4', '12', '叫 你 们 可 以 向 外 人 行 事 端 正 ， 自 己 也 就 没 有 什 么 缺 乏 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29616', '52', '4', '13', '＜ 主 的 降 临 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29617', '52', '4', '14', '我 们 若 信 耶 稣 死 而 复 活 了 ， 那 已 经 在 耶 稣 里 睡 了 的 人 ， 神 也 必 将 他 们 与 耶 稣 一 同 带 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29618', '52', '4', '15', '我 们 现 在 照 主 的 话 告 诉 你 们 一 件 事 ： 我 们 这 活 着 还 存 留 到 主 降 临 的 人 ， 断 不 能 在 那 已 经 睡 了 的 人 之 先 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29619', '52', '4', '16', '因 为 主 必 亲 自 从 天 降 临 ， 有 呼 叫 的 声 音 和 天 使 长 的 声 音 ， 又 有 神 的 号 吹 响 ； 那 在 基 督 里 死 了 的 人 必 先 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29620', '52', '4', '17', '以 后 我 们 这 活 着 还 存 留 的 人 必 和 他 们 一 同 被 提 到 云 里 ， 在 空 中 与 主 相 遇 。 这 样 ， 我 们 就 要 和 主 永 远 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29621', '52', '4', '18', '所 以 ， 你 们 当 用 这 些 话 彼 此 劝 慰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29622', '52', '5', '1', '弟 兄 们 ， 论 到 时 候 、 日 期 ， 不 用 写 信 给 你 们 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29623', '52', '5', '2', '因 为 你 们 自 己 明 明 晓 得 ， 主 的 日 子 来 到 ， 好 像 夜 间 的 贼 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29624', '52', '5', '3', '人 正 说 “ 平 安 稳 妥 ” 的 时 候 ， 灾 祸 忽 然 临 到 他 们 ， 如 同 产 难 临 到 怀 胎 的 妇 人 一 样 ， 他 们 绝 不 能 逃 脱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29625', '52', '5', '4', '弟 兄 们 ， 你 们 却 不 在 黑 暗 里 ， 叫 那 日 子 临 到 你 们 像 贼 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29626', '52', '5', '5', '你 们 都 是 光 明 之 子 ， 都 是 白 昼 之 子 。 我 们 不 是 属 黑 夜 的 ， 也 不 是 属 幽 暗 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29627', '52', '5', '6', '所 以 ， 我 们 不 要 睡 觉 像 别 人 一 样 ， 总 要 警 醒 谨 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29628', '52', '5', '7', '因 为 睡 了 的 人 是 在 夜 间 睡 ， 醉 了 的 人 是 在 夜 间 醉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29629', '52', '5', '8', '但 我 们 既 然 属 乎 白 昼 ， 就 应 当 谨 守 ， 把 信 和 爱 当 作 护 心 镜 遮 胸 ， 把 得 救 的 盼 望 当 作 头 盔 戴 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29630', '52', '5', '9', '因 为 神 不 是 预 定 我 们 受 刑 ， 乃 是 预 定 我 们 藉 着 我 们 主 耶 稣 基 督 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29631', '52', '5', '10', '他 替 我 们 死 ， 叫 我 们 无 论 醒 着 ， 睡 着 ， 都 与 他 同 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29632', '52', '5', '11', '所 以 ， 你 们 该 彼 此 劝 慰 ， 互 相 建 立 ， 正 如 你 们 素 常 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29633', '52', '5', '12', '＜ 最 后 的 劝 勉 与 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29634', '52', '5', '13', '又 因 他 们 所 做 的 工 ， 用 爱 心 格 外 尊 重 他 们 。 你 们 也 要 彼 此 和 睦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29635', '52', '5', '14', '我 们 又 劝 弟 兄 们 ， 要 警 戒 不 守 规 矩 的 人 ， 勉 励 灰 心 的 人 ， 扶 助 软 弱 的 人 ， 也 要 向 众 人 忍 耐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29636', '52', '5', '15', '你 们 要 谨 慎 ， 无 论 是 谁 都 不 可 以 恶 报 恶 ； 或 是 彼 此 相 待 ， 或 是 待 众 人 ， 常 要 追 求 良 善 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29637', '52', '5', '16', '要 常 常 喜 乐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29638', '52', '5', '17', '不 住 地 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29639', '52', '5', '18', '凡 事 谢 恩 ； 因 为 这 是 神 在 基 督 耶 稣 里 向 你 们 所 定 的 旨 意 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29640', '52', '5', '19', '不 要 消 灭 圣 灵 的 感 动 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29641', '52', '5', '20', '不 要 藐 视 先 知 的 讲 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29642', '52', '5', '21', '但 要 凡 事 察 验 ； 善 美 的 要 持 守 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29643', '52', '5', '22', '各 样 的 恶 事 要 禁 戒 不 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29644', '52', '5', '23', '愿 赐 平 安 的 神 亲 自 使 你 们 全 然 成 圣 ！ 又 愿 你 们 的 灵 与 魂 与 身 子 得 蒙 保 守 ， 在 我 们 主 耶 稣 基 督 降 临 的 时 候 ， 完 全 无 可 指 摘 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29645', '52', '5', '24', '那 召 你 们 的 本 是 信 实 的 ， 他 必 成 就 这 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29646', '52', '5', '25', '请 弟 兄 们 为 我 们 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29647', '52', '5', '26', '与 众 弟 兄 亲 嘴 问 安 ， 务 要 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29648', '52', '5', '27', '我 指 着 主 嘱 咐 你 们 ， 要 把 这 信 念 给 众 弟 兄 听 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29649', '52', '5', '28', '愿 我 主 耶 稣 基 督 的 恩 常 与 你 们 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29650', '53', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29651', '53', '1', '2', '愿 恩 惠 、 平 安 从 父 神 和 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29652', '53', '1', '3', '＜ 基 督 再 来 时 的 审 判 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29653', '53', '1', '4', '甚 至 我 们 在 神 的 各 教 会 里 为 你 们 夸 口 ， 都 因 你 们 在 所 受 的 一 切 逼 迫 患 难 中 ， 仍 旧 存 忍 耐 和 信 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29654', '53', '1', '5', '这 正 是 神 公 义 判 断 的 明 证 ， 叫 你 们 可 算 配 得 神 的 国 ； 你 们 就 是 为 这 国 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29655', '53', '1', '6', '神 既 是 公 义 的 ， 就 必 将 患 难 报 应 那 加 患 难 给 你 们 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29656', '53', '1', '7', '也 必 使 你 们 这 受 患 难 的 人 与 我 们 同 得 平 安 。 那 时 ， 主 耶 稣 同 他 有 能 力 的 天 使 从 天 上 在 火 焰 中 显 现 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29657', '53', '1', '8', '要 报 应 那 不 认 识 神 和 那 不 听 从 我 主 耶 稣 福 音 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29658', '53', '1', '9', '他 们 要 受 刑 罚 ， 就 是 永 远 沉 沦 ， 离 开 主 的 面 和 他 权 能 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29659', '53', '1', '10', '这 正 是 主 降 临 、 要 在 他 圣 徒 的 身 上 得 荣 耀 、 又 在 一 切 信 的 人 身 上 显 为 希 奇 的 那 日 子 。 我 们 对 你 们 作 的 见 证 ， 你 们 也 信 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29660', '53', '1', '11', '因 此 ， 我 们 常 为 你 们 祷 告 ， 愿 我 们 的 神 看 你 们 配 得 过 所 蒙 的 召 ， 又 用 大 能 成 就 你 们 一 切 所 羡 慕 的 良 善 和 一 切 因 信 心 所 做 的 工 夫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29661', '53', '1', '12', '叫 我 们 主 耶 稣 的 名 在 你 们 身 上 得 荣 耀 ， 你 们 也 在 他 身 上 得 荣 耀 ， 都 照 着 我 们 的 神 并 主 耶 稣 基 督 的 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29662', '53', '2', '1', '＜ 不 法 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29663', '53', '2', '2', '我 劝 你 们 ： 无 论 有 灵 、 有 言 语 、 有 冒 我 名 的 书 信 ， 说 主 的 日 子 现 在 ｛ 现 在 ： 或 译 就 ｝ 到 了 ， 不 要 轻 易 动 心 ， 也 不 要 惊 慌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29664', '53', '2', '3', '人 不 拘 用 什 么 法 子 ， 你 们 总 不 要 被 他 诱 惑 ； 因 为 那 日 子 以 前 ， 必 有 离 道 反 教 的 事 ， 并 有 那 大 罪 人 ， 就 是 沉 沦 之 子 ， 显 露 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29665', '53', '2', '4', '他 是 抵 挡 主 ， 高 抬 自 己 ， 超 过 一 切 称 为 神 的 和 一 切 受 人 敬 拜 的 ， 甚 至 坐 在 神 的 殿 里 ， 自 称 是 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29666', '53', '2', '5', '我 还 在 你 们 那 里 的 时 候 ， 曾 把 这 些 事 告 诉 你 们 ， 你 们 不 记 得 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29667', '53', '2', '6', '现 在 你 们 也 知 道 ， 那 拦 阻 他 的 是 什 么 ， 是 叫 他 到 了 的 时 候 才 可 以 显 露 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29668', '53', '2', '7', '因 为 那 不 法 的 隐 意 已 经 发 动 ， 只 是 现 在 有 一 个 拦 阻 的 ， 等 到 那 拦 阻 的 被 除 去 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29669', '53', '2', '8', '那 时 这 不 法 的 人 必 显 露 出 来 。 主 耶 稣 要 用 口 中 的 气 灭 绝 他 ， 用 降 临 的 荣 光 废 掉 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29670', '53', '2', '9', '这 不 法 的 人 来 ， 是 照 撒 但 的 运 动 ， 行 各 样 的 异 能 、 神 迹 ， 和 一 切 虚 假 的 奇 事 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29671', '53', '2', '10', '并 且 在 那 沉 沦 的 人 身 上 行 各 样 出 于 不 义 的 诡 诈 ； 因 他 们 不 领 受 爱 真 理 的 心 ， 使 他 们 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29672', '53', '2', '11', '故 此 ， 神 就 给 他 们 一 个 生 发 错 误 的 心 ， 叫 他 们 信 从 虚 谎 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29673', '53', '2', '12', '使 一 切 不 信 真 理 、 倒 喜 爱 不 义 的 人 都 被 定 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29674', '53', '2', '13', '＜ 被 拣 选 接 受 救 恩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29675', '53', '2', '14', '神 藉 我 们 所 传 的 福 音 召 你 们 到 这 地 步 ， 好 得 着 我 们 主 耶 稣 基 督 的 荣 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29676', '53', '2', '15', '所 以 ， 弟 兄 们 ， 你 们 要 站 立 得 稳 ， 凡 所 领 受 的 教 训 ， 不 拘 是 我 们 口 传 的 ， 是 信 上 写 的 ， 都 要 坚 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29677', '53', '2', '16', '但 愿 我 们 主 耶 稣 基 督 和 那 爱 我 们 、 开 恩 将 永 远 的 安 慰 并 美 好 的 盼 望 赐 给 我 们 的 父 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29678', '53', '2', '17', '安 慰 你 们 的 心 ， 并 且 在 一 切 善 行 善 言 上 坚 固 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29679', '53', '3', '1', '＜ 请 为 我 们 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29680', '53', '3', '2', '也 叫 我 们 脱 离 无 理 之 恶 人 的 手 ； 因 为 人 不 都 是 有 信 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29681', '53', '3', '3', '但 主 是 信 实 的 ， 要 坚 固 你 们 ， 保 护 你 们 脱 离 那 恶 者 ｛ 或 译 ： 脱 离 凶 恶 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29682', '53', '3', '4', '我 们 靠 主 深 信 ， 你 们 现 在 是 遵 行 我 们 所 吩 咐 的 ， 后 来 也 必 要 遵 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29683', '53', '3', '5', '愿 主 引 导 你 们 的 心 ， 叫 你 们 爱 神 ， 并 学 基 督 的 忍 耐 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29684', '53', '3', '6', '＜ 警 戒 懒 惰 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29685', '53', '3', '7', '你 们 自 己 原 知 道 应 当 怎 样 效 法 我 们 。 因 为 我 们 在 你 们 中 间 ， 未 尝 不 按 规 矩 而 行 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29686', '53', '3', '8', '也 未 尝 白 吃 人 的 饭 ， 倒 是 辛 苦 劳 碌 ， 昼 夜 做 工 ， 免 得 叫 你 们 一 人 受 累 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29687', '53', '3', '9', '这 并 不 是 因 我 们 没 有 权 柄 ， 乃 是 要 给 你 们 作 榜 样 ， 叫 你 们 效 法 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29688', '53', '3', '10', '我 们 在 你 们 那 里 的 时 候 ， 曾 吩 咐 你 们 说 ， 若 有 人 不 肯 做 工 ， 就 不 可 吃 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29689', '53', '3', '11', '因 我 们 听 说 ， 在 你 们 中 间 有 人 不 按 规 矩 而 行 ， 什 么 工 都 不 做 ， 反 倒 专 管 闲 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29690', '53', '3', '12', '我 们 靠 主 耶 稣 基 督 吩 咐 、 劝 戒 这 样 的 人 ， 要 安 静 做 工 ， 吃 自 己 的 饭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29691', '53', '3', '13', '弟 兄 们 ， 你 们 行 善 不 可 丧 志 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29692', '53', '3', '14', '若 有 人 不 听 从 我 们 这 信 上 的 话 ， 要 记 下 他 ， 不 和 他 交 往 ， 叫 他 自 觉 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29693', '53', '3', '15', '但 不 要 以 他 为 仇 人 ， 要 劝 他 如 弟 兄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29694', '53', '3', '16', '＜ 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29695', '53', '3', '17', '我 ─ ─ 保 罗 亲 笔 问 你 们 安 。 凡 我 的 信 都 以 此 为 记 ， 我 的 笔 迹 就 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29696', '53', '3', '18', '愿 我 们 主 耶 稣 基 督 的 恩 常 与 你 们 众 人 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29697', '54', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29698', '54', '1', '2', '写 信 给 那 因 信 主 作 我 真 儿 子 的 提 摩 太 。 愿 恩 惠 、 怜 悯 、 平 安 从 父 神 和 我 们 主 基 督 耶 稣 归 与 你 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29699', '54', '1', '3', '＜ 警 告 虚 伪 的 道 理 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29700', '54', '1', '4', '也 不 可 听 从 荒 渺 无 凭 的 话 语 和 无 穷 的 家 谱 ； 这 等 事 只 生 辩 论 ， 并 不 发 明 神 在 信 上 所 立 的 章 程 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29701', '54', '1', '5', '但 命 令 的 总 归 就 是 爱 ； 这 爱 是 从 清 洁 的 心 和 无 亏 的 良 心 ， 无 伪 的 信 心 生 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29702', '54', '1', '6', '有 人 偏 离 这 些 ， 反 去 讲 虚 浮 的 话 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29703', '54', '1', '7', '想 要 作 教 法 师 ， 却 不 明 白 自 己 所 讲 说 的 所 论 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29704', '54', '1', '8', '我 们 知 道 律 法 原 是 好 的 ， 只 要 人 用 得 合 宜 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29705', '54', '1', '9', '因 为 律 法 不 是 为 义 人 设 立 的 ， 乃 是 为 不 法 和 不 服 的 ， 不 虔 诚 和 犯 罪 的 ， 不 圣 洁 和 恋 世 俗 的 ， 弑 父 母 和 杀 人 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29706', '54', '1', '10', '行 淫 和 亲 男 色 的 ， 抢 人 口 和 说 谎 话 的 ， 并 起 假 誓 的 ， 或 是 为 别 样 敌 正 道 的 事 设 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29707', '54', '1', '11', '这 是 照 着 可 称 颂 之 神 交 托 我 荣 耀 福 音 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29708', '54', '1', '12', '＜ 感 谢 神 的 怜 悯 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29709', '54', '1', '13', '我 从 前 是 亵 渎 神 的 ， 逼 迫 人 的 ， 侮 慢 人 的 ； 然 而 我 还 蒙 了 怜 悯 ， 因 我 是 不 信 不 明 白 的 时 候 而 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29710', '54', '1', '14', '并 且 我 主 的 恩 是 格 外 丰 盛 ， 使 我 在 基 督 耶 稣 里 有 信 心 和 爱 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29711', '54', '1', '15', '“ 基 督 耶 稣 降 世 ， 为 要 拯 救 罪 人 。 ” 这 话 是 可 信 的 ， 是 十 分 可 佩 服 的 。 在 罪 人 中 我 是 个 罪 魁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29712', '54', '1', '16', '然 而 ， 我 蒙 了 怜 悯 ， 是 因 耶 稣 基 督 要 在 我 这 罪 魁 身 上 显 明 他 一 切 的 忍 耐 ， 给 后 来 信 他 得 永 生 的 人 作 榜 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29713', '54', '1', '17', '但 愿 尊 贵 、 荣 耀 归 与 那 不 能 朽 坏 、 不 能 看 见 、 永 世 的 君 王 、 独 一 的 神 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29714', '54', '1', '18', '我 儿 提 摩 太 啊 ， 我 照 从 前 指 着 你 的 预 言 ， 将 这 命 令 交 托 你 ， 叫 你 因 此 可 以 打 那 美 好 的 仗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29715', '54', '1', '19', '常 存 信 心 和 无 亏 的 良 心 。 有 人 丢 弃 良 心 ， 就 在 真 道 上 如 同 船 破 坏 了 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29716', '54', '1', '20', '其 中 有 许 米 乃 和 亚 历 山 大 ； 我 已 经 把 他 们 交 给 撒 但 ， 使 他 们 受 责 罚 就 不 再 谤 渎 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29717', '54', '2', '1', '＜ 有 关 祷 告 的 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29718', '54', '2', '2', '为 君 王 和 一 切 在 位 的 ， 也 该 如 此 ， 使 我 们 可 以 敬 虔 、 端 正 、 平 安 无 事 地 度 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29719', '54', '2', '3', '这 是 好 的 ， 在 神 我 们 救 主 面 前 可 蒙 悦 纳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29720', '54', '2', '4', '他 愿 意 万 人 得 救 ， 明 白 真 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29721', '54', '2', '5', '因 为 只 有 一 位 神 ， 在 神 和 人 中 间 ， 只 有 一 位 中 保 ， 乃 是 降 世 为 人 的 基 督 耶 稣 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29722', '54', '2', '6', '他 舍 自 己 作 万 人 的 赎 价 ， 到 了 时 候 ， 这 事 必 证 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29723', '54', '2', '7', '我 为 此 奉 派 作 传 道 的 ， 作 使 徒 ， 作 外 邦 人 的 师 傅 ， 教 导 他 们 相 信 ， 学 习 真 道 。 我 说 的 是 真 话 ， 并 不 是 谎 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29724', '54', '2', '8', '我 愿 男 人 无 忿 怒 ， 无 争 论 ｛ 或 译 ： 疑 惑 ｝ ， 举 起 圣 洁 的 手 ， 随 处 祷 告 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29725', '54', '2', '9', '又 愿 女 人 廉 耻 、 自 守 ， 以 正 派 衣 裳 为 妆 饰 ， 不 以 编 发 、 黄 金 、 珍 珠 ， 和 贵 价 的 衣 裳 为 妆 饰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29726', '54', '2', '10', '只 要 有 善 行 ， 这 才 与 自 称 是 敬 神 的 女 人 相 宜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29727', '54', '2', '11', '女 人 要 沉 静 学 道 ， 一 味 地 顺 服 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29728', '54', '2', '12', '我 不 许 女 人 讲 道 ， 也 不 许 她 辖 管 男 人 ， 只 要 沉 静 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29729', '54', '2', '13', '因 为 先 造 的 是 亚 当 ， 后 造 的 是 夏 娃 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29730', '54', '2', '14', '且 不 是 亚 当 被 引 诱 ， 乃 是 女 人 被 引 诱 ， 陷 在 罪 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29731', '54', '2', '15', '然 而 ， 女 人 若 常 存 信 心 、 爱 心 ， 又 圣 洁 自 守 ， 就 必 在 生 产 上 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29732', '54', '3', '1', '＜ 监 督 的 资 格 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29733', '54', '3', '2', '作 监 督 的 ， 必 须 无 可 指 责 ， 只 作 一 个 妇 人 的 丈 夫 ， 有 节 制 ， 自 守 ， 端 正 ， 乐 意 接 待 远 人 ， 善 于 教 导 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29734', '54', '3', '3', '不 因 酒 滋 事 ， 不 打 人 ， 只 要 温 和 ， 不 争 竞 ， 不 贪 财 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29735', '54', '3', '4', '好 好 管 理 自 己 的 家 ， 使 儿 女 凡 事 端 庄 顺 服 ｛ 或 译 ： 端 端 庄 庄 地 使 儿 女 顺 服 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29736', '54', '3', '5', '人 若 不 知 道 管 理 自 己 的 家 ， 焉 能 照 管 神 的 教 会 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29737', '54', '3', '6', '初 入 教 的 不 可 作 监 督 ， 恐 怕 他 自 高 自 大 ， 就 落 在 魔 鬼 所 受 的 刑 罚 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29738', '54', '3', '7', '监 督 也 必 须 在 教 外 有 好 名 声 ， 恐 怕 被 人 毁 谤 ， 落 在 魔 鬼 的 网 罗 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29739', '54', '3', '8', '＜ 执 事 的 资 格 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29740', '54', '3', '9', '要 存 清 洁 的 良 心 ， 固 守 真 道 的 奥 秘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29741', '54', '3', '10', '这 等 人 也 要 先 受 试 验 ， 若 没 有 可 责 之 处 ， 然 后 叫 他 们 作 执 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29742', '54', '3', '11', '女 执 事 ｛ 原 文 是 女 人 ｝ 也 是 如 此 ： 必 须 端 庄 ， 不 说 谗 言 ， 有 节 制 ， 凡 事 忠 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29743', '54', '3', '12', '执 事 只 要 作 一 个 妇 人 的 丈 夫 ， 好 好 管 理 儿 女 和 自 己 的 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29744', '54', '3', '13', '因 为 善 作 执 事 的 ， 自 己 就 得 到 美 好 的 地 步 ， 并 且 在 基 督 耶 稣 里 的 真 道 上 大 有 胆 量 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29745', '54', '3', '14', '＜ 敬 虔 的 奥 秘 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29746', '54', '3', '15', '倘 若 我 耽 延 日 久 ， 你 也 可 以 知 道 在 神 的 家 中 当 怎 样 行 。 这 家 就 是 永 生 神 的 教 会 ， 真 理 的 柱 石 和 根 基 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29747', '54', '3', '16', '大 哉 ， 敬 虔 的 奥 秘 ， 无 人 不 以 为 然 ！ 就 是 神 在 肉 身 显 现 ， 被 圣 灵 称 义 ｛ 或 译 ： 在 灵 性 称 义 ｝ ， 被 天 使 看 见 ， 被 传 于 外 邦 ， 被 世 人 信 服 ， 被 接 在 荣 耀 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29748', '54', '4', '1', '＜ 预 言 有 人 离 弃 真 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29749', '54', '4', '2', '这 是 因 为 说 谎 之 人 的 假 冒 ； 这 等 人 的 良 心 如 同 被 热 铁 烙 惯 了 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29750', '54', '4', '3', '他 们 禁 止 嫁 娶 ， 又 禁 戒 食 物 ｛ 或 译 ： 又 叫 人 戒 荤 ｝ ， 就 是 神 所 造 、 叫 那 信 而 明 白 真 道 的 人 感 谢 着 领 受 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29751', '54', '4', '4', '凡 神 所 造 的 物 都 是 好 的 ， 若 感 谢 着 领 受 ， 就 没 有 一 样 可 弃 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29752', '54', '4', '5', '都 因 神 的 道 和 人 的 祈 求 成 为 圣 洁 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29753', '54', '4', '6', '＜ 基 督 耶 稣 的 好 执 事 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29754', '54', '4', '7', '只 是 要 弃 绝 那 世 俗 的 言 语 和 老 妇 荒 渺 的 话 ， 在 敬 虔 上 操 练 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29755', '54', '4', '8', '“ 操 练 身 体 ， 益 处 还 少 ； 惟 独 敬 虔 ， 凡 事 都 有 益 处 ， 因 有 今 生 和 来 生 的 应 许 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29756', '54', '4', '9', '这 话 是 可 信 的 ， 是 十 分 可 佩 服 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29757', '54', '4', '10', '我 们 劳 苦 努 力 ， 正 是 为 此 ， 因 我 们 的 指 望 在 乎 永 生 的 神 ； 他 是 万 人 的 救 主 ， 更 是 信 徒 的 救 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29758', '54', '4', '11', '这 些 事 ， 你 要 吩 咐 人 ， 也 要 教 导 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29759', '54', '4', '12', '不 可 叫 人 小 看 你 年 轻 ， 总 要 在 言 语 、 行 为 、 爱 心 、 信 心 、 清 洁 上 ， 都 作 信 徒 的 榜 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29760', '54', '4', '13', '你 要 以 宣 读 、 劝 勉 、 教 导 为 念 ， 直 等 到 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29761', '54', '4', '14', '你 不 要 轻 忽 所 得 的 恩 赐 ， 就 是 从 前 藉 着 预 言 、 在 众 长 老 按 手 的 时 候 赐 给 你 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29762', '54', '4', '15', '这 些 事 你 要 殷 勤 去 做 ， 并 要 在 此 专 心 ， 使 众 人 看 出 你 的 长 进 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29763', '54', '4', '16', '你 要 谨 慎 自 己 和 自 己 的 教 训 ， 要 在 这 些 事 上 恒 心 ； 因 为 这 样 行 ， 又 能 救 自 己 ， 又 能 救 听 你 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29764', '54', '5', '1', '＜ 对 别 人 的 本 分 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29765', '54', '5', '2', '劝 老 年 妇 女 如 同 母 亲 ； 劝 少 年 妇 女 如 同 姊 妹 ； 总 要 清 清 洁 洁 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29766', '54', '5', '3', '要 尊 敬 那 真 为 寡 妇 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29767', '54', '5', '4', '若 寡 妇 有 儿 女 ， 或 有 孙 子 孙 女 ， 便 叫 他 们 先 在 自 己 家 中 学 着 行 孝 ， 报 答 亲 恩 ， 因 为 这 在 神 面 前 是 可 悦 纳 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29768', '54', '5', '5', '那 独 居 无 靠 、 真 为 寡 妇 的 ， 是 仰 赖 神 ， 昼 夜 不 住 地 祈 求 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29769', '54', '5', '6', '但 那 好 宴 乐 的 寡 妇 正 活 着 的 时 候 也 是 死 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29770', '54', '5', '7', '这 些 事 你 要 嘱 咐 她 们 ， 叫 她 们 无 可 指 责 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29771', '54', '5', '8', '人 若 不 看 顾 亲 属 ， 就 是 背 了 真 道 ， 比 不 信 的 人 还 不 好 ， 不 看 顾 自 己 家 里 的 人 ， 更 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29772', '54', '5', '9', '寡 妇 记 在 册 子 上 ， 必 须 年 纪 到 六 十 岁 ， 从 来 只 作 一 个 丈 夫 的 妻 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29773', '54', '5', '10', '又 有 行 善 的 名 声 ， 就 如 养 育 儿 女 ， 接 待 远 人 ， 洗 圣 徒 的 脚 ， 救 济 遭 难 的 人 ， 竭 力 行 各 样 善 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29774', '54', '5', '11', '至 于 年 轻 的 寡 妇 ， 就 可 以 辞 她 ； 因 为 她 们 的 情 欲 发 动 ， 违 背 基 督 的 时 候 就 想 要 嫁 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29775', '54', '5', '12', '她 们 被 定 罪 ， 是 因 废 弃 了 当 初 所 许 的 愿 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29776', '54', '5', '13', '并 且 她 们 又 习 惯 懒 惰 ， 挨 家 闲 游 ； 不 但 是 懒 惰 ， 又 说 长 道 短 ， 好 管 闲 事 ， 说 些 不 当 说 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29777', '54', '5', '14', '所 以 我 愿 意 年 轻 的 寡 妇 嫁 人 ， 生 养 儿 女 ， 治 理 家 务 ， 不 给 敌 人 辱 骂 的 把 柄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29778', '54', '5', '15', '因 为 已 经 有 转 去 随 从 撒 但 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29779', '54', '5', '16', '信 主 的 妇 女 ， 若 家 中 有 寡 妇 ， 自 己 就 当 救 济 她 们 ， 不 可 累 着 教 会 ， 好 使 教 会 能 救 济 那 真 无 倚 靠 的 寡 妇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29780', '54', '5', '17', '那 善 于 管 理 教 会 的 长 老 ， 当 以 为 配 受 加 倍 的 敬 奉 ； 那 劳 苦 传 道 教 导 人 的 ， 更 当 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29781', '54', '5', '18', '因 为 经 上 说 ： “ 牛 在 场 上 踹 谷 的 时 候 ， 不 可 笼 住 它 的 嘴 ” ； 又 说 ： “ 工 人 得 工 价 是 应 当 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29782', '54', '5', '19', '控 告 长 老 的 呈 子 ， 非 有 两 三 个 见 证 就 不 要 收 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29783', '54', '5', '20', '犯 罪 的 人 ， 当 在 众 人 面 前 责 备 他 ， 叫 其 余 的 人 也 可 以 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29784', '54', '5', '21', '我 在 神 和 基 督 耶 稣 并 蒙 拣 选 的 天 使 面 前 嘱 咐 你 ： 要 遵 守 这 些 话 ， 不 可 存 成 见 ， 行 事 也 不 可 有 偏 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29785', '54', '5', '22', '给 人 行 按 手 的 礼 ， 不 可 急 促 ； 不 要 在 别 人 的 罪 上 有 分 ， 要 保 守 自 己 清 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29786', '54', '5', '23', '因 你 胃 口 不 清 ， 屡 次 患 病 ， 再 不 要 照 常 喝 水 ， 可 以 稍 微 用 点 酒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29787', '54', '5', '24', '有 些 人 的 罪 是 明 显 的 ， 如 同 先 到 审 判 案 前 ； 有 些 人 的 罪 是 随 后 跟 了 去 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29788', '54', '5', '25', '这 样 ， 善 行 也 有 明 显 的 ， 那 不 明 显 的 也 不 能 隐 藏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29789', '54', '6', '1', '凡 在 轭 下 作 仆 人 的 ， 当 以 自 己 主 人 配 受 十 分 的 恭 敬 ， 免 得 神 的 名 和 道 理 被 人 亵 渎 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29790', '54', '6', '2', '仆 人 有 信 道 的 主 人 ， 不 可 因 为 与 他 是 弟 兄 就 轻 看 他 ； 更 要 加 意 服 事 他 ； 因 为 得 服 事 之 益 处 的 ， 是 信 道 蒙 爱 的 。 你 要 以 此 教 训 人 ， 劝 勉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29791', '54', '6', '3', '＜ 假 道 理 和 真 财 富 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29792', '54', '6', '4', '他 是 自 高 自 大 ， 一 无 所 知 ， 专 好 问 难 ， 争 辩 言 词 ， 从 此 就 生 出 嫉 妒 、 纷 争 、 毁 谤 、 妄 疑 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29793', '54', '6', '5', '并 那 坏 了 心 术 、 失 丧 真 理 之 人 的 争 竞 。 他 们 以 敬 虔 为 得 利 的 门 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29794', '54', '6', '6', '然 而 ， 敬 虔 加 上 知 足 的 心 便 是 大 利 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29795', '54', '6', '7', '因 为 我 们 没 有 带 什 么 到 世 上 来 ， 也 不 能 带 什 么 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29796', '54', '6', '8', '只 要 有 衣 有 食 ， 就 当 知 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29797', '54', '6', '9', '但 那 些 想 要 发 财 的 人 ， 就 陷 在 迷 惑 、 落 在 网 罗 和 许 多 无 知 有 害 的 私 欲 里 ， 叫 人 沉 在 败 坏 和 灭 亡 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29798', '54', '6', '10', '贪 财 是 万 恶 之 根 。 有 人 贪 恋 钱 财 ， 就 被 引 诱 离 了 真 道 ， 用 许 多 愁 苦 把 自 己 刺 透 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29799', '54', '6', '11', '＜ 美 好 的 仗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29800', '54', '6', '12', '你 要 为 真 道 打 那 美 好 的 仗 ， 持 定 永 生 。 你 为 此 被 召 ， 也 在 许 多 见 证 人 面 前 ， 已 经 作 了 那 美 好 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29801', '54', '6', '13', '我 在 叫 万 物 生 活 的 神 面 前 ， 并 在 向 本 丢 ． 彼 拉 多 作 过 那 美 好 见 证 的 基 督 耶 稣 面 前 嘱 咐 你 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29802', '54', '6', '14', '要 守 这 命 令 ， 毫 不 玷 污 ， 无 可 指 责 ， 直 到 我 们 的 主 耶 稣 基 督 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29803', '54', '6', '15', '到 了 日 期 ， 那 可 称 颂 、 独 有 权 能 的 万 王 之 王 、 万 主 之 主 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29804', '54', '6', '16', '就 是 那 独 一 不 死 、 住 在 人 不 能 靠 近 的 光 里 ， 是 人 未 曾 看 见 、 也 是 不 能 看 见 的 ， 要 将 他 显 明 出 来 。 但 愿 尊 贵 和 永 远 的 权 能 都 归 给 他 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29805', '54', '6', '17', '你 要 嘱 咐 那 些 今 世 富 足 的 人 ， 不 要 自 高 ， 也 不 要 倚 靠 无 定 的 钱 财 ； 只 要 倚 靠 那 厚 赐 百 物 给 我 们 享 受 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29806', '54', '6', '18', '又 要 嘱 咐 他 们 行 善 ， 在 好 事 上 富 足 ， 甘 心 施 舍 ， 乐 意 供 给 ｛ 或 译 ： 体 贴 ｝ 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29807', '54', '6', '19', '为 自 己 积 成 美 好 的 根 基 ， 预 备 将 来 ， 叫 他 们 持 定 那 真 正 的 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29808', '54', '6', '20', '提 摩 太 啊 ， 你 要 保 守 所 托 付 你 的 ， 躲 避 世 俗 的 虚 谈 和 那 敌 真 道 、 似 是 而 非 的 学 问 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29809', '54', '6', '21', '已 经 有 人 自 称 有 这 学 问 ， 就 偏 离 了 真 道 。 愿 恩 惠 常 与 你 们 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29810', '55', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29811', '55', '1', '2', '写 信 给 我 亲 爱 的 儿 子 提 摩 太 。 愿 恩 惠 、 怜 悯 、 平 安 从 父 神 和 我 们 主 基 督 耶 稣 归 与 你 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29812', '55', '1', '3', '＜ 忠 于 福 音 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29813', '55', '1', '4', '记 念 你 的 眼 泪 ， 昼 夜 切 切 地 想 要 见 你 ， 好 叫 我 满 心 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29814', '55', '1', '5', '想 到 你 心 里 无 伪 之 信 ， 这 信 是 先 在 你 外 祖 母 罗 以 和 你 母 亲 友 妮 基 心 里 的 ， 我 深 信 也 在 你 的 心 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29815', '55', '1', '6', '为 此 我 提 醒 你 ， 使 你 将 神 藉 我 按 手 所 给 你 的 恩 赐 再 如 火 挑 旺 起 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29816', '55', '1', '7', '因 为 神 赐 给 我 们 ， 不 是 胆 怯 的 心 ， 乃 是 刚 强 、 仁 爱 、 谨 守 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29817', '55', '1', '8', '你 不 要 以 给 我 们 的 主 作 见 证 为 耻 ， 也 不 要 以 我 这 为 主 被 囚 的 为 耻 ； 总 要 按 神 的 能 力 ， 与 我 为 福 音 同 受 苦 难 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29818', '55', '1', '9', '神 救 了 我 们 ， 以 圣 召 召 我 们 ， 不 是 按 我 们 的 行 为 ， 乃 是 按 他 的 旨 意 和 恩 典 ； 这 恩 典 是 万 古 之 先 ， 在 基 督 耶 稣 里 赐 给 我 们 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29819', '55', '1', '10', '但 如 今 藉 着 我 们 救 主 基 督 耶 稣 的 显 现 才 表 明 出 来 了 。 他 已 经 把 死 废 去 ， 藉 着 福 音 ， 将 不 能 坏 的 生 命 彰 显 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29820', '55', '1', '11', '我 为 这 福 音 奉 派 作 传 道 的 ， 作 使 徒 ， 作 师 傅 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29821', '55', '1', '12', '为 这 缘 故 ， 我 也 受 这 些 苦 难 。 然 而 我 不 以 为 耻 ； 因 为 知 道 我 所 信 的 是 谁 ， 也 深 信 他 能 保 全 我 所 交 付 他 的 ｛ 或 译 ： 他 所 交 托 我 的 ｝ ， 直 到 那 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29822', '55', '1', '13', '你 从 我 听 的 那 纯 正 话 语 的 规 模 ， 要 用 在 基 督 耶 稣 里 的 信 心 和 爱 心 ， 常 常 守 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29823', '55', '1', '14', '从 前 所 交 托 你 的 善 道 ， 你 要 靠 着 那 住 在 我 们 里 面 的 圣 灵 牢 牢 地 守 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29824', '55', '1', '15', '凡 在 亚 细 亚 的 人 都 离 弃 我 ， 这 是 你 知 道 的 ， 其 中 有 腓 吉 路 和 黑 摩 其 尼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29825', '55', '1', '16', '愿 主 怜 悯 阿 尼 色 弗 一 家 的 人 ； 因 他 屡 次 使 我 畅 快 ， 不 以 我 的 锁 炼 为 耻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29826', '55', '1', '17', '反 倒 在 罗 马 的 时 候 ， 殷 勤 地 找 我 ， 并 且 找 着 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29827', '55', '1', '18', '愿 主 使 他 在 那 日 得 主 的 怜 悯 。 他 在 以 弗 所 怎 样 多 多 地 服 事 我 ， 是 你 明 明 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29828', '55', '2', '1', '＜ 基 督 耶 稣 的 精 兵 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29829', '55', '2', '2', '你 在 许 多 见 证 人 面 前 听 见 我 所 教 训 的 ， 也 要 交 托 那 忠 心 能 教 导 别 人 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29830', '55', '2', '3', '你 要 和 我 同 受 苦 难 ， 好 像 基 督 耶 稣 的 精 兵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29831', '55', '2', '4', '凡 在 军 中 当 兵 的 ， 不 将 世 务 缠 身 ， 好 叫 那 招 他 当 兵 的 人 喜 悦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29832', '55', '2', '5', '人 若 在 场 上 比 武 ， 非 按 规 矩 ， 就 不 能 得 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29833', '55', '2', '6', '劳 力 的 农 夫 理 当 先 得 粮 食 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29834', '55', '2', '7', '我 所 说 的 话 ， 你 要 思 想 ， 因 为 凡 事 主 必 给 你 聪 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29835', '55', '2', '8', '你 要 记 念 耶 稣 基 督 乃 是 大 卫 的 后 裔 ， 他 从 死 里 复 活 ， 正 合 乎 我 所 传 的 福 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29836', '55', '2', '9', '我 为 这 福 音 受 苦 难 ， 甚 至 被 捆 绑 ， 像 犯 人 一 样 。 然 而 神 的 道 却 不 被 捆 绑 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29837', '55', '2', '10', '所 以 ， 我 为 选 民 凡 事 忍 耐 ， 叫 他 们 也 可 以 得 着 那 在 基 督 耶 稣 里 的 救 恩 和 永 远 的 荣 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29838', '55', '2', '11', '有 可 信 的 话 说 ： 我 们 若 与 基 督 同 死 ， 也 必 与 他 同 活 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29839', '55', '2', '12', '我 们 若 能 忍 耐 ， 也 必 和 他 一 同 作 王 。 我 们 若 不 认 他 ， 他 也 必 不 认 我 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29840', '55', '2', '13', '我 们 纵 然 失 信 ， 他 仍 是 可 信 的 ， 因 为 他 不 能 背 乎 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29841', '55', '2', '14', '＜ 无 愧 的 工 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29842', '55', '2', '15', '你 当 竭 力 在 神 面 前 得 蒙 喜 悦 ， 作 无 愧 的 工 人 ， 按 着 正 意 分 解 真 理 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29843', '55', '2', '16', '但 要 远 避 世 俗 的 虚 谈 ， 因 为 这 等 人 必 进 到 更 不 敬 虔 的 地 步 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29844', '55', '2', '17', '他 们 的 话 如 同 毒 疮 ， 越 烂 越 大 ； 其 中 有 许 米 乃 和 腓 理 徒 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29845', '55', '2', '18', '他 们 偏 离 了 真 道 ， 说 复 活 的 事 已 过 ， 就 败 坏 好 些 人 的 信 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29846', '55', '2', '19', '然 而 ， 神 坚 固 的 根 基 立 住 了 ； 上 面 有 这 印 记 说 ： “ 主 认 识 谁 是 他 的 人 ” ； 又 说 ： “ 凡 称 呼 主 名 的 人 总 要 离 开 不 义 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29847', '55', '2', '20', '在 大 户 人 家 ， 不 但 有 金 器 银 器 ， 也 有 木 器 瓦 器 ； 有 作 为 贵 重 的 ， 有 作 为 卑 贱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29848', '55', '2', '21', '人 若 自 洁 ， 脱 离 卑 贱 的 事 ， 就 必 作 贵 重 的 器 皿 ， 成 为 圣 洁 ， 合 乎 主 用 ， 预 备 行 各 样 的 善 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29849', '55', '2', '22', '你 要 逃 避 少 年 的 私 欲 ， 同 那 清 心 祷 告 主 的 人 追 求 公 义 、 信 德 、 仁 爱 、 和 平 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29850', '55', '2', '23', '惟 有 那 愚 拙 无 学 问 的 辩 论 ， 总 要 弃 绝 ， 因 为 知 道 这 等 事 是 起 争 竞 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29851', '55', '2', '24', '然 而 主 的 仆 人 不 可 争 竞 ， 只 要 温 温 和 和 地 待 众 人 ， 善 于 教 导 ， 存 心 忍 耐 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29852', '55', '2', '25', '用 温 柔 劝 戒 那 抵 挡 的 人 ； 或 者 神 给 他 们 悔 改 的 心 ， 可 以 明 白 真 道 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29853', '55', '2', '26', '叫 他 们 这 已 经 被 魔 鬼 任 意 掳 去 的 ， 可 以 醒 悟 ， 脱 离 他 的 网 罗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29854', '55', '3', '1', '＜ 末 世 的 人 性 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29855', '55', '3', '2', '因 为 那 时 ， 人 要 专 顾 自 己 ， 贪 爱 钱 财 ， 自 夸 ， 狂 傲 ， 谤 讟 ， 背 父 母 ， 忘 恩 负 义 ， 心 不 圣 洁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29856', '55', '3', '3', '无 亲 情 ， 不 解 怨 ， 好 说 谗 言 ， 不 能 自 约 ， 性 情 凶 暴 ， 不 爱 良 善 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29857', '55', '3', '4', '卖 主 卖 友 ， 任 意 妄 为 ， 自 高 自 大 ， 爱 宴 乐 ， 不 爱 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29858', '55', '3', '5', '有 敬 虔 的 外 貌 ， 却 背 了 敬 虔 的 实 意 ； 这 等 人 你 要 躲 开 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29859', '55', '3', '6', '那 偷 进 人 家 、 牢 笼 无 知 妇 女 的 ， 正 是 这 等 人 。 这 些 妇 女 担 负 罪 恶 ， 被 各 样 的 私 欲 引 诱 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29860', '55', '3', '7', '常 常 学 习 ， 终 久 不 能 明 白 真 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29861', '55', '3', '8', '从 前 雅 尼 和 佯 庇 怎 样 敌 挡 摩 西 ， 这 等 人 也 怎 样 敌 挡 真 道 。 他 们 的 心 地 坏 了 ， 在 真 道 上 是 可 废 弃 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29862', '55', '3', '9', '然 而 他 们 不 能 再 这 样 敌 挡 ； 因 为 他 们 的 愚 昧 必 在 众 人 面 前 显 露 出 来 ， 像 那 二 人 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29863', '55', '3', '10', '＜ 对 提 摩 太 的 最 后 指 示 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29864', '55', '3', '11', '以 及 我 在 安 提 阿 、 以 哥 念 、 路 司 得 所 遭 遇 的 逼 迫 、 苦 难 。 我 所 忍 受 是 何 等 的 逼 迫 ； 但 从 这 一 切 苦 难 中 ， 主 都 把 我 救 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29865', '55', '3', '12', '不 但 如 此 ， 凡 立 志 在 基 督 耶 稣 里 敬 虔 度 日 的 也 都 要 受 逼 迫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29866', '55', '3', '13', '只 是 作 恶 的 和 迷 惑 人 的 ， 必 越 久 越 恶 ， 他 欺 哄 人 ， 也 被 人 欺 哄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29867', '55', '3', '14', '但 你 所 学 习 的 ， 所 确 信 的 ， 要 存 在 心 里 ； 因 为 你 知 道 是 跟 谁 学 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29868', '55', '3', '15', '并 且 知 道 你 是 从 小 明 白 圣 经 ， 这 圣 经 能 使 你 因 信 基 督 耶 稣 ， 有 得 救 的 智 慧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29869', '55', '3', '16', '圣 经 都 是 神 所 默 示 的 ｛ 或 译 ： 凡 神 所 默 示 的 圣 经 ｝ ， 于 教 训 、 督 责 、 使 人 归 正 、 教 导 人 学 义 都 是 有 益 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29870', '55', '3', '17', '叫 属 神 的 人 得 以 完 全 ， 预 备 行 各 样 的 善 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29871', '55', '4', '1', '我 在 神 面 前 ， 并 在 将 来 审 判 活 人 死 人 的 基 督 耶 稣 面 前 ， 凭 着 他 的 显 现 和 他 的 国 度 嘱 咐 你 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29872', '55', '4', '2', '务 要 传 道 ， 无 论 得 时 不 得 时 ， 总 要 专 心 ， 并 用 百 般 的 忍 耐 、 各 样 的 教 训 责 备 人 ， 警 戒 人 ， 劝 勉 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29873', '55', '4', '3', '因 为 时 候 要 到 ， 人 必 厌 烦 纯 正 的 道 理 ， 耳 朵 发 痒 ， 就 随 从 自 己 的 情 欲 增 添 好 些 师 傅 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29874', '55', '4', '4', '并 且 掩 耳 不 听 真 道 ， 偏 向 荒 渺 的 言 语 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29875', '55', '4', '5', '你 却 要 凡 事 谨 慎 ， 忍 受 苦 难 ， 做 传 道 的 工 夫 ， 尽 你 的 职 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29876', '55', '4', '6', '我 现 在 被 浇 奠 ， 我 离 世 的 时 候 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29877', '55', '4', '7', '那 美 好 的 仗 我 已 经 打 过 了 ， 当 跑 的 路 我 已 经 跑 尽 了 ， 所 信 的 道 我 已 经 守 住 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29878', '55', '4', '8', '从 此 以 后 ， 有 公 义 的 冠 冕 为 我 存 留 ， 就 是 按 着 公 义 审 判 的 主 到 了 那 日 要 赐 给 我 的 ； 不 但 赐 给 我 ， 也 赐 给 凡 爱 慕 他 显 现 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29879', '55', '4', '9', '＜ 私 事 的 嘱 咐 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29880', '55', '4', '10', '因 为 底 马 贪 爱 现 今 的 世 界 ， 就 离 弃 我 往 帖 撒 罗 尼 迦 去 了 ； 革 勒 士 往 加 拉 太 去 ； 提 多 往 挞 马 太 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29881', '55', '4', '11', '独 有 路 加 在 我 这 里 。 你 来 的 时 候 ， 要 把 马 可 带 来 ， 因 为 他 在 传 道 ｛ 或 译 ： 服 事 我 ｝ 的 事 上 于 我 有 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29882', '55', '4', '12', '我 已 经 打 发 推 基 古 往 以 弗 所 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29883', '55', '4', '13', '我 在 特 罗 亚 留 于 加 布 的 那 件 外 衣 ， 你 来 的 时 候 可 以 带 来 ， 那 些 书 也 要 带 来 ， 更 要 紧 的 是 那 些 皮 卷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29884', '55', '4', '14', '铜 匠 亚 历 山 大 多 多 地 害 我 ； 主 必 照 他 所 行 的 报 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29885', '55', '4', '15', '你 也 要 防 备 他 ， 因 为 他 极 力 敌 挡 了 我 们 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29886', '55', '4', '16', '我 初 次 申 诉 ， 没 有 人 前 来 帮 助 ， 竟 都 离 弃 我 ； 但 愿 这 罪 不 归 与 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29887', '55', '4', '17', '惟 有 主 站 在 我 旁 边 ， 加 给 我 力 量 ， 使 福 音 被 我 尽 都 传 明 ， 叫 外 邦 人 都 听 见 ； 我 也 从 狮 子 口 里 被 救 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29888', '55', '4', '18', '主 必 救 我 脱 离 诸 般 的 凶 恶 ， 也 必 救 我 进 他 的 天 国 。 愿 荣 耀 归 给 他 ， 直 到 永 永 远 远 。 阿 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29889', '55', '4', '19', '＜ 问 候 与 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29890', '55', '4', '20', '以 拉 都 在 哥 林 多 住 下 了 。 特 罗 非 摩 病 了 ， 我 就 留 他 在 米 利 都 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29891', '55', '4', '21', '你 要 赶 紧 在 冬 天 以 前 到 我 这 里 来 。 有 友 布 罗 、 布 田 、 利 奴 、 革 老 底 亚 ， 和 众 弟 兄 都 问 你 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29892', '55', '4', '22', '愿 主 与 你 的 灵 同 在 ！ 愿 恩 惠 常 与 你 们 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29893', '56', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29894', '56', '1', '2', '盼 望 那 无 谎 言 的 神 在 万 古 之 先 所 应 许 的 永 生 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29895', '56', '1', '3', '到 了 日 期 ， 藉 着 传 扬 的 工 夫 把 他 的 道 显 明 了 ； 这 传 扬 的 责 任 是 按 着 神 ─ ─ 我 们 救 主 的 命 令 交 托 了 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29896', '56', '1', '4', '现 在 写 信 给 提 多 ， 就 是 照 着 我 们 共 信 之 道 作 我 真 儿 子 的 。 愿 恩 惠 、 平 安 从 父 神 和 我 们 的 救 主 基 督 耶 稣 归 与 你 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29897', '56', '1', '5', '＜ 提 多 在 克 里 特 的 工 作 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29898', '56', '1', '6', '若 有 无 可 指 责 的 人 ， 只 作 一 个 妇 人 的 丈 夫 ， 儿 女 也 是 信 主 的 ， 没 有 人 告 他 们 是 放 荡 不 服 约 束 的 ， 就 可 以 设 立 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29899', '56', '1', '7', '监 督 既 是 神 的 管 家 ， 必 须 无 可 指 责 ， 不 任 性 ， 不 暴 躁 ， 不 因 酒 滋 事 ， 不 打 人 ， 不 贪 无 义 之 财 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29900', '56', '1', '8', '乐 意 接 待 远 人 ， 好 善 ， 庄 重 ， 公 平 ， 圣 洁 自 持 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29901', '56', '1', '9', '坚 守 所 教 真 实 的 道 理 ， 就 能 将 纯 正 的 教 训 劝 化 人 ， 又 能 把 争 辩 的 人 驳 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29902', '56', '1', '10', '因 为 有 许 多 人 不 服 约 束 ， 说 虚 空 话 欺 哄 人 ； 那 奉 割 礼 的 更 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29903', '56', '1', '11', '这 些 人 的 口 总 要 堵 住 。 他 们 因 贪 不 义 之 财 ， 将 不 该 教 导 的 教 导 人 ， 败 坏 人 的 全 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29904', '56', '1', '12', '有 克 里 特 人 中 的 一 个 本 地 先 知 说 ： “ 克 里 特 人 常 说 谎 话 ， 乃 是 恶 兽 ， 又 馋 又 懒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29905', '56', '1', '13', '这 个 见 证 是 真 的 。 所 以 ， 你 要 严 严 地 责 备 他 们 ， 使 他 们 在 真 道 上 纯 全 无 疵 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29906', '56', '1', '14', '不 听 犹 太 人 荒 渺 的 言 语 和 离 弃 真 道 之 人 的 诫 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29907', '56', '1', '15', '在 洁 净 的 人 ， 凡 物 都 洁 净 ； 在 污 秽 不 信 的 人 ， 什 么 都 不 洁 净 ， 连 心 地 和 天 良 也 都 污 秽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29908', '56', '1', '16', '他 们 说 是 认 识 神 ， 行 事 却 和 他 相 背 ； 本 是 可 憎 恶 的 ， 是 悖 逆 的 ， 在 各 样 善 事 上 是 可 废 弃 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29909', '56', '2', '1', '＜ 纯 正 的 道 理 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29910', '56', '2', '2', '劝 老 年 人 要 有 节 制 、 端 庄 、 自 守 ， 在 信 心 、 爱 心 、 忍 耐 上 都 要 纯 全 无 疵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29911', '56', '2', '3', '又 劝 老 年 妇 人 ， 举 止 行 动 要 恭 敬 ， 不 说 谗 言 ， 不 给 酒 作 奴 仆 ， 用 善 道 教 训 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29912', '56', '2', '4', '好 指 教 少 年 妇 人 ， 爱 丈 夫 ， 爱 儿 女 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29913', '56', '2', '5', '谨 守 ， 贞 洁 ， 料 理 家 务 ， 待 人 有 恩 ， 顺 服 自 己 的 丈 夫 ， 免 得 神 的 道 理 被 毁 谤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29914', '56', '2', '6', '又 劝 少 年 人 要 谨 守 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29915', '56', '2', '7', '你 自 己 凡 事 要 显 出 善 行 的 榜 样 ； 在 教 训 上 要 正 直 、 端 庄 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29916', '56', '2', '8', '言 语 纯 全 ， 无 可 指 责 ， 叫 那 反 对 的 人 ， 既 无 处 可 说 我 们 的 不 是 ， 便 自 觉 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29917', '56', '2', '9', '劝 仆 人 要 顺 服 自 己 的 主 人 ， 凡 事 讨 他 的 喜 欢 ， 不 可 顶 撞 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29918', '56', '2', '10', '不 可 私 拿 东 西 ， 要 显 为 忠 诚 ， 以 致 凡 事 尊 荣 我 们 救 主 ─ ─ 神 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29919', '56', '2', '11', '因 为 神 救 众 人 的 恩 典 已 经 显 明 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29920', '56', '2', '12', '教 训 我 们 除 去 不 敬 虔 的 心 和 世 俗 的 情 欲 ， 在 今 世 自 守 、 公 义 、 敬 虔 度 日 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29921', '56', '2', '13', '等 候 所 盼 望 的 福 ， 并 等 候 至 大 的 神 和 我 们 ｛ 或 译 ： 神 ─ ─ 我 们 ｝ 救 主 耶 稣 基 督 的 荣 耀 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29922', '56', '2', '14', '他 为 我 们 舍 了 自 己 ， 要 赎 我 们 脱 离 一 切 罪 恶 ， 又 洁 净 我 们 ， 特 作 自 己 的 子 民 ， 热 心 为 善 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29923', '56', '2', '15', '这 些 事 你 要 讲 明 ， 劝 戒 人 ， 用 各 等 权 柄 责 备 人 ； 不 可 叫 人 轻 看 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29924', '56', '3', '1', '＜ 热 心 行 善 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29925', '56', '3', '2', '不 要 毁 谤 ， 不 要 争 竞 ， 总 要 和 平 ， 向 众 人 大 显 温 柔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29926', '56', '3', '3', '我 们 从 前 也 是 无 知 、 悖 逆 、 受 迷 惑 、 服 事 各 样 私 欲 ， 和 宴 乐 ， 常 存 恶 毒 ｛ 或 译 ： 阴 毒 ｝ 嫉 妒 的 心 ， 是 可 恨 的 ， 又 是 彼 此 相 恨 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29927', '56', '3', '4', '但 到 了 神 ─ ─ 我 们 救 主 的 恩 慈 和 他 向 人 所 施 的 慈 爱 显 明 的 时 候 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29928', '56', '3', '5', '他 便 救 了 我 们 ； 并 不 是 因 我 们 自 己 所 行 的 义 ， 乃 是 照 他 的 怜 悯 ， 藉 着 重 生 的 洗 和 圣 灵 的 更 新 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29929', '56', '3', '6', '圣 灵 就 是 神 藉 着 耶 稣 基 督 ─ ─ 我 们 救 主 厚 厚 浇 灌 在 我 们 身 上 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29930', '56', '3', '7', '好 叫 我 们 因 他 的 恩 得 称 为 义 ， 可 以 凭 着 永 生 的 盼 望 成 为 后 嗣 ｛ 或 译 ： 可 以 凭 着 盼 望 承 受 永 生 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29931', '56', '3', '8', '这 话 是 可 信 的 。 我 也 愿 你 把 这 些 事 切 切 实 实 地 讲 明 ， 使 那 些 已 信 神 的 人 留 心 做 正 经 事 业 ｛ 或 译 ： 留 心 行 善 ｝ 。 这 都 是 美 事 ， 并 且 与 人 有 益 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29932', '56', '3', '9', '要 远 避 无 知 的 辩 论 和 家 谱 的 空 谈 ， 以 及 纷 争 ， 并 因 律 法 而 起 的 争 竞 ， 因 为 这 都 是 虚 妄 无 益 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29933', '56', '3', '10', '分 门 结 党 的 人 ， 警 戒 过 一 两 次 ， 就 要 弃 绝 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29934', '56', '3', '11', '因 为 知 道 这 等 人 已 经 背 道 ， 犯 了 罪 ， 自 己 明 知 不 是 ， 还 是 去 做 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29935', '56', '3', '12', '＜ 个 人 的 指 示 和 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29936', '56', '3', '13', '你 要 赶 紧 给 律 师 西 纳 和 亚 波 罗 送 行 ， 叫 他 们 没 有 缺 乏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29937', '56', '3', '14', '并 且 我 们 的 人 要 学 习 正 经 事 业 ｛ 或 译 ： 要 学 习 行 善 ｝ ， 预 备 所 需 用 的 ， 免 得 不 结 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29938', '56', '3', '15', '同 我 在 一 处 的 人 都 问 你 安 。 请 代 问 那 些 因 有 信 心 爱 我 们 的 人 安 。 愿 恩 惠 常 与 你 们 众 人 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29939', '57', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29940', '57', '1', '2', '和 妹 子 亚 腓 亚 并 与 我 们 同 当 兵 的 亚 基 布 ， 以 及 在 你 家 的 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29941', '57', '1', '3', '愿 恩 惠 、 平 安 从 神 我 们 的 父 和 主 耶 稣 基 督 归 与 你 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29942', '57', '1', '4', '＜ 腓 利 门 的 爱 心 和 信 心 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29943', '57', '1', '5', '因 听 说 你 的 爱 心 并 你 向 主 耶 稣 和 众 圣 徒 的 信 心 ｛ 或 译 ： 因 听 说 你 向 主 耶 稣 和 众 圣 徒 有 爱 心 有 信 心 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29944', '57', '1', '6', '愿 你 与 人 所 同 有 的 信 心 显 出 功 效 ， 使 人 知 道 你 们 各 样 善 事 都 是 为 基 督 做 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29945', '57', '1', '7', '兄 弟 啊 ， 我 为 你 的 爱 心 ， 大 有 快 乐 ， 大 得 安 慰 ， 因 众 圣 徒 的 心 从 你 得 了 畅 快 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29946', '57', '1', '8', '＜ 保 罗 为 阿 尼 西 谋 请 求 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29947', '57', '1', '9', '然 而 像 我 这 有 年 纪 的 保 罗 ， 现 在 又 是 为 基 督 耶 稣 被 囚 的 ， 宁 可 凭 着 爱 心 求 你 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29948', '57', '1', '10', '就 是 为 我 在 捆 锁 中 所 生 的 儿 子 阿 尼 西 谋 ｛ 就 是 有 益 处 的 意 思 ｝ 求 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29949', '57', '1', '11', '他 从 前 与 你 没 有 益 处 ， 但 如 今 与 你 我 都 有 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29950', '57', '1', '12', '我 现 在 打 发 他 亲 自 回 你 那 里 去 ； 他 是 我 心 上 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29951', '57', '1', '13', '我 本 来 有 意 将 他 留 下 ， 在 我 为 福 音 所 受 的 捆 锁 中 替 你 伺 候 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29952', '57', '1', '14', '但 不 知 道 你 的 意 思 ， 我 就 不 愿 意 这 样 行 ， 叫 你 的 善 行 不 是 出 于 勉 强 ， 乃 是 出 于 甘 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29953', '57', '1', '15', '他 暂 时 离 开 你 ， 或 者 是 叫 你 永 远 得 着 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29954', '57', '1', '16', '不 再 是 奴 仆 ， 乃 是 高 过 奴 仆 ， 是 亲 爱 的 兄 弟 。 在 我 实 在 是 如 此 ， 何 况 在 你 呢 ！ 这 也 不 拘 是 按 肉 体 说 ， 是 按 主 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29955', '57', '1', '17', '你 若 以 我 为 同 伴 ， 就 收 纳 他 ， 如 同 收 纳 我 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29956', '57', '1', '18', '他 若 亏 负 你 ， 或 欠 你 什 么 ， 都 归 在 我 的 帐 上 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29957', '57', '1', '19', '我 必 偿 还 ， 这 是 我 ─ ─ 保 罗 亲 笔 写 的 。 我 并 不 用 对 你 说 ， 连 你 自 己 也 是 亏 欠 于 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29958', '57', '1', '20', '兄 弟 啊 ， 望 你 使 我 在 主 里 因 你 得 快 乐 ｛ 或 译 ： 益 处 ｝ ， 并 望 你 使 我 的 心 在 基 督 里 得 畅 快 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29959', '57', '1', '21', '我 写 信 给 你 ， 深 信 你 必 顺 服 ， 知 道 你 所 要 行 的 必 过 于 我 所 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29960', '57', '1', '22', '此 外 你 还 要 给 我 预 备 住 处 ； 因 为 我 盼 望 藉 着 你 们 的 祷 告 ， 必 蒙 恩 到 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29961', '57', '1', '23', '＜ 最 后 的 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29962', '57', '1', '24', '与 我 同 工 的 马 可 、 亚 里 达 古 、 底 马 、 路 加 也 都 问 你 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29963', '57', '1', '25', '愿 我 们 主 耶 稣 基 督 的 恩 常 在 你 的 心 里 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29964', '58', '1', '1', '＜ 神 藉 着 他 儿 子 说 话 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29965', '58', '1', '2', '就 在 这 末 世 藉 着 他 儿 子 晓 谕 我 们 ； 又 早 已 立 他 为 承 受 万 有 的 ， 也 曾 藉 着 他 创 造 诸 世 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29966', '58', '1', '3', '他 是 神 荣 耀 所 发 的 光 辉 ， 是 神 本 体 的 真 相 ， 常 用 他 权 能 的 命 令 托 住 万 有 。 他 洗 净 了 人 的 罪 ， 就 坐 在 高 天 至 大 者 的 右 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29967', '58', '1', '4', '他 所 承 受 的 名 ， 既 比 天 使 的 名 更 尊 贵 ， 就 远 超 过 天 使 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29968', '58', '1', '5', '＜ 儿 子 远 超 过 天 使 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29969', '58', '1', '6', '再 者 ， 神 使 长 子 到 世 上 来 的 时 候 ｛ 或 译 ： 神 再 使 长 子 到 世 上 来 的 时 候 ｝ ， 就 说 ： 神 的 使 者 都 要 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29970', '58', '1', '7', '论 到 使 者 ， 又 说 ： 神 以 风 为 使 者 ， 以 火 焰 为 仆 役 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29971', '58', '1', '8', '论 到 子 却 说 ： 神 啊 ， 你 的 宝 座 是 永 永 远 远 的 ； 你 的 国 权 是 正 直 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29972', '58', '1', '9', '你 喜 爱 公 义 ， 恨 恶 罪 恶 ； 所 以 神 ， 就 是 你 的 神 ， 用 喜 乐 油 膏 你 ， 胜 过 膏 你 的 同 伴 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29973', '58', '1', '10', '又 说 ： 主 啊 ， 你 起 初 立 了 地 的 根 基 ； 天 也 是 你 手 所 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29974', '58', '1', '11', '天 地 都 要 灭 没 ， 你 却 要 长 存 。 天 地 都 要 像 衣 服 渐 渐 旧 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29975', '58', '1', '12', '你 要 将 天 地 卷 起 来 ， 像 一 件 外 衣 ， 天 地 就 都 改 变 了 。 惟 有 你 永 不 改 变 ； 你 的 年 数 没 有 穷 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29976', '58', '1', '13', '所 有 的 天 使 ， 神 从 来 对 哪 一 个 说 ： 你 坐 在 我 的 右 边 ， 等 我 使 你 仇 敌 作 你 的 脚 凳 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29977', '58', '1', '14', '天 使 岂 不 都 是 服 役 的 灵 、 奉 差 遣 为 那 将 要 承 受 救 恩 的 人 效 力 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29978', '58', '2', '1', '＜ 这 么 大 的 救 恩 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29979', '58', '2', '2', '那 藉 着 天 使 所 传 的 话 既 是 确 定 的 ； 凡 干 犯 悖 逆 的 都 受 了 该 受 的 报 应 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29980', '58', '2', '3', '我 们 若 忽 略 这 么 大 的 救 恩 ， 怎 能 逃 罪 呢 ？ 这 救 恩 起 先 是 主 亲 自 讲 的 ， 后 来 是 听 见 的 人 给 我 们 证 实 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29981', '58', '2', '4', '神 又 按 自 己 的 旨 意 ， 用 神 迹 、 奇 事 和 百 般 的 异 能 ， 并 圣 灵 的 恩 赐 ， 同 他 们 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29982', '58', '2', '5', '＜ 救 恩 的 元 帅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29983', '58', '2', '6', '但 有 人 在 经 上 某 处 证 明 说 ： 人 算 什 么 ， 你 竟 顾 念 他 ？ 世 人 算 什 么 ， 你 竟 眷 顾 他 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29984', '58', '2', '7', '你 叫 他 比 天 使 微 小 一 点 ｛ 或 译 ： 你 叫 他 暂 时 比 天 使 小 ｝ ， 赐 他 荣 耀 尊 贵 为 冠 冕 ， 并 将 你 手 所 造 的 都 派 他 管 理 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29985', '58', '2', '8', '叫 万 物 都 服 在 他 的 脚 下 。 既 叫 万 物 都 服 他 ， 就 没 有 剩 下 一 样 不 服 他 的 。 只 是 如 今 我 们 还 不 见 万 物 都 服 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29986', '58', '2', '9', '惟 独 见 那 成 为 比 天 使 小 一 点 的 耶 稣 ｛ 或 译 ： 惟 独 见 耶 稣 暂 时 比 天 使 小 ｝ ； 因 为 受 死 的 苦 ， 就 得 了 尊 贵 荣 耀 为 冠 冕 ， 叫 他 因 着 神 的 恩 ， 为 人 人 尝 了 死 味 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29987', '58', '2', '10', '原 来 那 为 万 物 所 属 、 为 万 物 所 本 的 ， 要 领 许 多 的 儿 子 进 荣 耀 里 去 ， 使 救 他 们 的 元 帅 ， 因 受 苦 难 得 以 完 全 ， 本 是 合 宜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29988', '58', '2', '11', '因 那 使 人 成 圣 的 和 那 些 得 以 成 圣 的 ， 都 是 出 于 一 。 所 以 ， 他 称 他 们 为 弟 兄 也 不 以 为 耻 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29989', '58', '2', '12', '说 ： 我 要 将 你 的 名 传 与 我 的 弟 兄 ， 在 会 中 我 要 颂 扬 你 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29990', '58', '2', '13', '又 说 ： 我 要 倚 赖 他 ； 又 说 ： 看 哪 ， 我 与 神 所 给 我 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29991', '58', '2', '14', '儿 女 既 同 有 血 肉 之 体 ， 他 也 照 样 亲 自 成 了 血 肉 之 体 ， 特 要 藉 着 死 败 坏 那 掌 死 权 的 ， 就 是 魔 鬼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29992', '58', '2', '15', '并 要 释 放 那 些 一 生 因 怕 死 而 为 奴 仆 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29993', '58', '2', '16', '他 并 不 救 拔 天 使 ， 乃 是 救 拔 亚 伯 拉 罕 的 后 裔 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29994', '58', '2', '17', '所 以 ， 他 凡 事 该 与 他 的 弟 兄 相 同 ， 为 要 在 神 的 事 上 成 为 慈 悲 忠 信 的 大 祭 司 ， 为 百 姓 的 罪 献 上 挽 回 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29995', '58', '2', '18', '他 自 己 既 然 被 试 探 而 受 苦 ， 就 能 搭 救 被 试 探 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29996', '58', '3', '1', '＜ 耶 稣 超 越 摩 西 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29997', '58', '3', '2', '他 为 那 设 立 他 的 尽 忠 ， 如 同 摩 西 在 神 的 全 家 尽 忠 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29998', '58', '3', '3', '他 比 摩 西 算 是 更 配 多 得 荣 耀 ， 好 像 建 造 房 屋 的 比 房 屋 更 尊 荣 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('29999', '58', '3', '4', '因 为 房 屋 都 必 有 人 建 造 ， 但 建 造 万 物 的 就 是 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30000', '58', '3', '5', '摩 西 为 仆 人 ， 在 神 的 全 家 诚 然 尽 忠 ， 为 要 证 明 将 来 必 传 说 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30001', '58', '3', '6', '但 基 督 为 儿 子 ， 治 理 神 的 家 ； 我 们 若 将 可 夸 的 盼 望 和 胆 量 坚 持 到 底 ， 便 是 他 的 家 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30002', '58', '3', '7', '＜ 神 子 民 的 安 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30003', '58', '3', '8', '就 不 可 硬 着 心 ， 像 在 旷 野 惹 他 发 怒 、 试 探 他 的 时 候 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30004', '58', '3', '9', '在 那 里 ， 你 们 的 祖 宗 试 我 探 我 ， 并 且 观 看 我 的 作 为 有 四 十 年 之 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30005', '58', '3', '10', '所 以 ， 我 厌 烦 那 世 代 的 人 ， 说 ： 他 们 心 里 常 常 迷 糊 ， 竟 不 晓 得 我 的 作 为 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30006', '58', '3', '11', '我 就 在 怒 中 起 誓 说 ： 他 们 断 不 可 进 入 我 的 安 息 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30007', '58', '3', '12', '弟 兄 们 ， 你 们 要 谨 慎 ， 免 得 你 们 中 间 或 有 人 存 着 不 信 的 恶 心 ， 把 永 生 神 离 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30008', '58', '3', '13', '总 要 趁 着 还 有 今 日 ， 天 天 彼 此 相 劝 ， 免 得 你 们 中 间 有 人 被 罪 迷 惑 ， 心 里 就 刚 硬 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30009', '58', '3', '14', '我 们 若 将 起 初 确 实 的 信 心 坚 持 到 底 ， 就 在 基 督 里 有 分 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30010', '58', '3', '15', '经 上 说 ： “ 你 们 今 日 若 听 他 的 话 ， 就 不 可 硬 着 心 ， 像 惹 他 发 怒 的 日 子 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30011', '58', '3', '16', '那 时 ， 听 见 他 话 惹 他 发 怒 的 是 谁 呢 ？ 岂 不 是 跟 着 摩 西 从 埃 及 出 来 的 众 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30012', '58', '3', '17', '神 四 十 年 之 久 ， 又 厌 烦 谁 呢 ？ 岂 不 是 那 些 犯 罪 、 尸 首 倒 在 旷 野 的 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30013', '58', '3', '18', '又 向 谁 起 誓 ， 不 容 他 们 进 入 他 的 安 息 呢 ？ 岂 不 是 向 那 些 不 信 从 的 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30014', '58', '3', '19', '这 样 看 来 ， 他 们 不 能 进 入 安 息 是 因 为 不 信 的 缘 故 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30015', '58', '4', '1', '我 们 既 蒙 留 下 ， 有 进 入 他 安 息 的 应 许 ， 就 当 畏 惧 ， 免 得 我 们 ｛ 原 文 是 你 们 ｝ 中 间 或 有 人 似 乎 是 赶 不 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30016', '58', '4', '2', '因 为 有 福 音 传 给 我 们 ， 像 传 给 他 们 一 样 ； 只 是 所 听 见 的 道 与 他 们 无 益 ， 因 为 他 们 没 有 信 心 与 所 听 见 的 道 调 和 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30017', '58', '4', '3', '但 我 们 已 经 相 信 的 人 得 以 进 入 那 安 息 ， 正 如 神 所 说 ： “ 我 在 怒 中 起 誓 说 ： ‘ 他 们 断 不 可 进 入 我 的 安 息 ！ ’ ” 其 实 造 物 之 工 ， 从 创 世 以 来 已 经 成 全 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30018', '58', '4', '4', '论 到 第 七 日 ， 有 一 处 说 ： “ 到 第 七 日 ， 神 就 歇 了 他 一 切 的 工 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30019', '58', '4', '5', '又 有 一 处 说 ： “ 他 们 断 不 可 进 入 我 的 安 息 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30020', '58', '4', '6', '既 有 必 进 安 息 的 人 ， 那 先 前 听 见 福 音 的 ， 因 为 不 信 从 ， 不 得 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30021', '58', '4', '7', '所 以 过 了 多 年 ， 就 在 大 卫 的 书 上 ， 又 限 定 一 日 ， 如 以 上 所 引 的 说 ： “ 你 们 今 日 若 听 他 的 话 ， 就 不 可 硬 着 心 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30022', '58', '4', '8', '若 是 约 书 亚 已 叫 他 们 享 了 安 息 ， 后 来 神 就 不 再 提 别 的 日 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30023', '58', '4', '9', '这 样 看 来 ， 必 另 有 一 安 息 日 的 安 息 为 神 的 子 民 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30024', '58', '4', '10', '因 为 那 进 入 安 息 的 ， 乃 是 歇 了 自 己 的 工 ， 正 如 神 歇 了 他 的 工 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30025', '58', '4', '11', '所 以 ， 我 们 务 必 竭 力 进 入 那 安 息 ， 免 得 有 人 学 那 不 信 从 的 样 子 跌 倒 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30026', '58', '4', '12', '神 的 道 是 活 泼 的 ， 是 有 功 效 的 ， 比 一 切 两 刃 的 剑 更 快 ， 甚 至 魂 与 灵 ， 骨 节 与 骨 髓 ， 都 能 刺 入 、 剖 开 ， 连 心 中 的 思 念 和 主 意 都 能 辨 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30027', '58', '4', '13', '并 且 被 造 的 没 有 一 样 在 他 面 前 不 显 然 的 ； 原 来 万 物 在 那 与 我 们 有 关 系 的 主 眼 前 ， 都 是 赤 露 敞 开 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30028', '58', '4', '14', '＜ 大 祭 司 耶 稣 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30029', '58', '4', '15', '因 我 们 的 大 祭 司 并 非 不 能 体 恤 我 们 的 软 弱 。 他 也 曾 凡 事 受 过 试 探 ， 与 我 们 一 样 ， 只 是 他 没 有 犯 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30030', '58', '4', '16', '所 以 ， 我 们 只 管 坦 然 无 惧 地 来 到 施 恩 的 宝 座 前 ， 为 要 得 怜 恤 ， 蒙 恩 惠 ， 作 随 时 的 帮 助 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30031', '58', '5', '1', '凡 从 人 间 挑 选 的 大 祭 司 ， 是 奉 派 替 人 办 理 属 神 的 事 ， 为 要 献 上 礼 物 和 赎 罪 祭 ｛ 或 译 ： 要 为 罪 献 上 礼 物 和 祭 物 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30032', '58', '5', '2', '他 能 体 谅 那 愚 蒙 的 和 失 迷 的 人 ， 因 为 他 自 己 也 是 被 软 弱 所 困 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30033', '58', '5', '3', '故 此 ， 他 理 当 为 百 姓 和 自 己 献 祭 赎 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30034', '58', '5', '4', '这 大 祭 司 的 尊 荣 ， 没 有 人 自 取 。 惟 要 蒙 神 所 召 ， 像 亚 伦 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30035', '58', '5', '5', '如 此 ， 基 督 也 不 是 自 取 荣 耀 作 大 祭 司 ， 乃 是 在 乎 向 他 说 “ 你 是 我 的 儿 子 ， 我 今 日 生 你 ” 的 那 一 位 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30036', '58', '5', '6', '就 如 经 上 又 有 一 处 说 ： “ 你 是 照 着 麦 基 洗 德 的 等 次 永 远 为 祭 司 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30037', '58', '5', '7', '基 督 在 肉 体 的 时 候 ， 既 大 声 哀 哭 ， 流 泪 祷 告 ， 恳 求 那 能 救 他 免 死 的 主 ， 就 因 他 的 虔 诚 蒙 了 应 允 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30038', '58', '5', '8', '他 虽 然 为 儿 子 ， 还 是 因 所 受 的 苦 难 学 了 顺 从 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30039', '58', '5', '9', '他 既 得 以 完 全 ， 就 为 凡 顺 从 他 的 人 成 了 永 远 得 救 的 根 源 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30040', '58', '5', '10', '并 蒙 神 照 着 麦 基 洗 德 的 等 次 称 他 为 大 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30041', '58', '5', '11', '＜ 警 戒 叛 道 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30042', '58', '5', '12', '看 你 们 学 习 的 工 夫 ， 本 该 作 师 傅 ， 谁 知 还 得 有 人 将 神 圣 言 小 学 的 开 端 另 教 导 你 们 ， 并 且 成 了 那 必 须 吃 奶 、 不 能 吃 干 粮 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30043', '58', '5', '13', '凡 只 能 吃 奶 的 都 不 熟 练 仁 义 的 道 理 ， 因 为 他 是 婴 孩 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30044', '58', '5', '14', '惟 独 长 大 成 人 的 才 能 吃 干 粮 ； 他 们 的 心 窍 习 练 得 通 达 ， 就 能 分 辨 好 歹 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30045', '58', '6', '1', '所 以 ， 我 们 应 当 离 开 基 督 道 理 的 开 端 ， 竭 力 进 到 完 全 的 地 步 ， 不 必 再 立 根 基 ， 就 如 那 懊 悔 死 行 、 信 靠 神 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30046', '58', '6', '2', '各 样 洗 礼 、 按 手 之 礼 、 死 人 复 活 ， 以 及 永 远 审 判 各 等 教 训 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30047', '58', '6', '3', '神 若 许 我 们 ， 我 们 必 如 此 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30048', '58', '6', '4', '论 到 那 些 已 经 蒙 了 光 照 、 尝 过 天 恩 的 滋 味 、 又 于 圣 灵 有 分 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30049', '58', '6', '5', '并 尝 过 神 善 道 的 滋 味 、 觉 悟 来 世 权 能 的 人 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30050', '58', '6', '6', '若 是 离 弃 道 理 ， 就 不 能 叫 他 们 重 新 懊 悔 了 。 因 为 他 们 把 神 的 儿 子 重 钉 十 字 架 ， 明 明 地 羞 辱 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30051', '58', '6', '7', '就 如 一 块 田 地 ， 吃 过 屡 次 下 的 雨 水 ， 生 长 菜 蔬 ， 合 乎 耕 种 的 人 用 ， 就 从 神 得 福 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30052', '58', '6', '8', '若 长 荆 棘 和 蒺 藜 ， 必 被 废 弃 ， 近 于 咒 诅 ， 结 局 就 是 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30053', '58', '6', '9', '亲 爱 的 弟 兄 们 ， 我 们 虽 是 这 样 说 ， 却 深 信 你 们 的 行 为 强 过 这 些 ， 而 且 近 乎 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30054', '58', '6', '10', '因 为 神 并 非 不 公 义 ， 竟 忘 记 你 们 所 做 的 工 和 你 们 为 他 名 所 显 的 爱 心 ， 就 是 先 前 伺 候 圣 徒 ， 如 今 还 是 伺 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30055', '58', '6', '11', '我 们 愿 你 们 各 人 都 显 出 这 样 的 殷 勤 ， 使 你 们 有 满 足 的 指 望 ， 一 直 到 底 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30056', '58', '6', '12', '并 且 不 懈 怠 ， 总 要 效 法 那 些 凭 信 心 和 忍 耐 承 受 应 许 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30057', '58', '6', '13', '＜ 神 确 切 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30058', '58', '6', '14', '“ 论 福 ， 我 必 赐 大 福 给 你 ； 论 子 孙 ， 我 必 叫 你 的 子 孙 多 起 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30059', '58', '6', '15', '这 样 ， 亚 伯 拉 罕 既 恒 久 忍 耐 ， 就 得 了 所 应 许 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30060', '58', '6', '16', '人 都 是 指 着 比 自 己 大 的 起 誓 ， 并 且 以 起 誓 为 实 据 ， 了 结 各 样 的 争 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30061', '58', '6', '17', '照 样 ， 神 愿 意 为 那 承 受 应 许 的 人 格 外 显 明 他 的 旨 意 是 不 更 改 的 ， 就 起 誓 为 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30062', '58', '6', '18', '藉 这 两 件 不 更 改 的 事 ， 神 决 不 能 说 谎 ， 好 叫 我 们 这 逃 往 避 难 所 、 持 定 摆 在 我 们 前 头 指 望 的 人 可 以 大 得 勉 励 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30063', '58', '6', '19', '我 们 有 这 指 望 ， 如 同 灵 魂 的 锚 ， 又 坚 固 又 牢 靠 ， 且 通 入 幔 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30064', '58', '6', '20', '作 先 锋 的 耶 稣 ， 既 照 着 麦 基 洗 德 的 等 次 成 了 永 远 的 大 祭 司 ， 就 为 我 们 进 入 幔 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30065', '58', '7', '1', '＜ 麦 基 洗 德 的 祭 司 等 次 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30066', '58', '7', '2', '亚 伯 拉 罕 也 将 自 己 所 得 来 的 ， 取 十 分 之 一 给 他 。 他 头 一 个 名 翻 出 来 就 是 仁 义 王 ， 他 又 名 撒 冷 王 ， 就 是 平 安 王 的 意 思 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30067', '58', '7', '3', '他 无 父 ， 无 母 ， 无 族 谱 ， 无 生 之 始 ， 无 命 之 终 ， 乃 是 与 神 的 儿 子 相 似 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30068', '58', '7', '4', '你 们 想 一 想 ， 先 祖 亚 伯 拉 罕 将 自 己 所 掳 来 上 等 之 物 取 十 分 之 一 给 他 ， 这 人 是 何 等 尊 贵 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30069', '58', '7', '5', '那 得 祭 司 职 任 的 利 未 子 孙 ， 领 命 照 例 向 百 姓 取 十 分 之 一 ， 这 百 姓 是 自 己 的 弟 兄 ， 虽 是 从 亚 伯 拉 罕 身 ｛ 原 文 是 腰 ｝ 中 生 的 ， 还 是 照 例 取 十 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30070', '58', '7', '6', '独 有 麦 基 洗 德 ， 不 与 他 们 同 谱 ， 倒 收 纳 亚 伯 拉 罕 的 十 分 之 一 ， 为 那 蒙 应 许 的 亚 伯 拉 罕 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30071', '58', '7', '7', '从 来 位 分 大 的 给 位 分 小 的 祝 福 ， 这 是 驳 不 倒 的 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30072', '58', '7', '8', '在 这 里 收 十 分 之 一 的 都 是 必 死 的 人 ； 但 在 那 里 收 十 分 之 一 的 ， 有 为 他 作 见 证 的 说 ， 他 是 活 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30073', '58', '7', '9', '并 且 可 说 那 受 十 分 之 一 的 利 未 ， 也 是 藉 着 亚 伯 拉 罕 纳 了 十 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30074', '58', '7', '10', '因 为 麦 基 洗 德 迎 接 亚 伯 拉 罕 的 时 候 ， 利 未 已 经 在 他 先 祖 的 身 ｛ 原 文 是 腰 ｝ 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30075', '58', '7', '11', '从 前 百 姓 在 利 未 人 祭 司 职 任 以 下 受 律 法 ， 倘 若 藉 这 职 任 能 得 完 全 ， 又 何 用 另 外 兴 起 一 位 祭 司 ， 照 麦 基 洗 德 的 等 次 ， 不 照 亚 伦 的 等 次 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30076', '58', '7', '12', '祭 司 的 职 任 既 已 更 改 ， 律 法 也 必 须 更 改 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30077', '58', '7', '13', '因 为 这 话 所 指 的 人 本 属 别 的 支 派 ， 那 支 派 里 从 来 没 有 一 人 伺 候 祭 坛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30078', '58', '7', '14', '我 们 的 主 分 明 是 从 犹 大 出 来 的 ； 但 这 支 派 ， 摩 西 并 没 有 提 到 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30079', '58', '7', '15', '倘 若 照 麦 基 洗 德 的 样 式 ， 另 外 兴 起 一 位 祭 司 来 ， 我 的 话 更 是 显 而 易 见 的 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30080', '58', '7', '16', '他 成 为 祭 司 ， 并 不 是 照 属 肉 体 的 条 例 ， 乃 是 照 无 穷 ｛ 原 文 是 不 能 毁 坏 ｝ 之 生 命 的 大 能 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30081', '58', '7', '17', '因 为 有 给 他 作 见 证 的 说 ： “ 你 是 照 着 麦 基 洗 德 的 等 次 永 远 为 祭 司 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30082', '58', '7', '18', '先 前 的 条 例 ， 因 软 弱 无 益 ， 所 以 废 掉 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30083', '58', '7', '19', '（ 律 法 原 来 一 无 所 成 ） 就 引 进 了 更 美 的 指 望 ； 靠 这 指 望 ， 我 们 便 可 以 进 到 神 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30084', '58', '7', '20', '再 者 ， 耶 稣 为 祭 司 ， 并 不 是 不 起 誓 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30085', '58', '7', '21', '至 于 那 些 祭 司 ， 原 不 是 起 誓 立 的 ， 只 有 耶 稣 是 起 誓 立 的 ； 因 为 那 立 他 的 对 他 说 ： “ 主 起 了 誓 ， 决 不 后 悔 ， 你 是 永 远 为 祭 司 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30086', '58', '7', '22', '既 是 起 誓 立 的 ， 耶 稣 就 作 了 更 美 之 约 的 中 保 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30087', '58', '7', '23', '那 些 成 为 祭 司 的 ， 数 目 本 来 多 ， 是 因 为 有 死 阻 隔 ， 不 能 长 久 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30088', '58', '7', '24', '这 位 既 是 永 远 常 存 的 ， 他 祭 司 的 职 任 就 长 久 不 更 换 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30089', '58', '7', '25', '凡 靠 着 他 进 到 神 面 前 的 人 ， 他 都 能 拯 救 到 底 ； 因 为 他 是 长 远 活 着 ， 替 他 们 祈 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30090', '58', '7', '26', '像 这 样 圣 洁 、 无 邪 恶 、 无 玷 污 、 远 离 罪 人 、 高 过 诸 天 的 大 祭 司 ， 原 是 与 我 们 合 宜 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30091', '58', '7', '27', '他 不 像 那 些 大 祭 司 ， 每 日 必 须 先 为 自 己 的 罪 ， 后 为 百 姓 的 罪 献 祭 ； 因 为 他 只 一 次 将 自 己 献 上 ， 就 把 这 事 成 全 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30092', '58', '7', '28', '律 法 本 是 立 软 弱 的 人 为 大 祭 司 ； 但 在 律 法 以 后 起 誓 的 话 ， 是 立 儿 子 为 大 祭 司 ， 乃 是 成 全 到 永 远 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30093', '58', '8', '1', '＜ 更 美 之 约 的 大 祭 司 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30094', '58', '8', '2', '在 圣 所 ， 就 是 真 帐 幕 里 ， 作 执 事 ； 这 帐 幕 是 主 所 支 的 ， 不 是 人 所 支 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30095', '58', '8', '3', '凡 大 祭 司 都 是 为 献 礼 物 和 祭 物 设 立 的 ， 所 以 这 位 大 祭 司 也 必 须 有 所 献 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30096', '58', '8', '4', '他 若 在 地 上 ， 必 不 得 为 祭 司 ， 因 为 已 经 有 照 律 法 献 礼 物 的 祭 司 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30097', '58', '8', '5', '他 们 供 奉 的 事 本 是 天 上 事 的 形 状 和 影 像 ， 正 如 摩 西 将 要 造 帐 幕 的 时 候 ， 蒙 神 警 戒 他 ， 说 ： “ 你 要 谨 慎 ， 作 各 样 的 物 件 都 要 照 着 在 山 上 指 示 你 的 样 式 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30098', '58', '8', '6', '如 今 耶 稣 所 得 的 职 任 是 更 美 的 ， 正 如 他 作 更 美 之 约 的 中 保 ； 这 约 原 是 凭 更 美 之 应 许 立 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30099', '58', '8', '7', '那 前 约 若 没 有 瑕 疵 ， 就 无 处 寻 求 后 约 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30100', '58', '8', '8', '所 以 主 指 责 他 的 百 姓 说 ｛ 或 译 ： 所 以 主 指 前 约 的 缺 欠 说 ｝ ： 日 子 将 到 ， 我 要 与 以 色 列 家 和 犹 大 家 另 立 新 约 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30101', '58', '8', '9', '不 像 我 拉 着 他 们 祖 宗 的 手 ， 领 他 们 出 埃 及 的 时 候 ， 与 他 们 所 立 的 约 。 因 为 他 们 不 恒 心 守 我 的 约 ， 我 也 不 理 他 们 。 这 是 主 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30102', '58', '8', '10', '主 又 说 ： 那 些 日 子 以 后 ， 我 与 以 色 列 家 所 立 的 约 乃 是 这 样 ： 我 要 将 我 的 律 法 放 在 他 们 里 面 ， 写 在 他 们 心 上 ； 我 要 作 他 们 的 神 ； 他 们 要 作 我 的 子 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30103', '58', '8', '11', '他 们 不 用 各 人 教 导 自 己 的 乡 邻 和 自 己 的 弟 兄 ， 说 ： 你 该 认 识 主 ； 因 为 他 们 从 最 小 的 到 至 大 的 ， 都 必 认 识 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30104', '58', '8', '12', '我 要 宽 恕 他 们 的 不 义 ， 不 再 记 念 他 们 的 罪 愆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30105', '58', '8', '13', '既 说 新 约 ， 就 以 前 约 为 旧 了 ； 但 那 渐 旧 渐 衰 的 ， 就 必 快 归 无 有 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30106', '58', '9', '1', '＜ 地 上 和 天 上 的 圣 所 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30107', '58', '9', '2', '因 为 有 预 备 的 帐 幕 ， 头 一 层 叫 作 圣 所 ， 里 面 有 灯 台 、 桌 子 ， 和 陈 设 饼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30108', '58', '9', '3', '第 二 幔 子 后 又 有 一 层 帐 幕 ， 叫 作 至 圣 所 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30109', '58', '9', '4', '有 金 香 炉 ｛ 炉 ： 或 译 坛 ｝ ， 有 包 金 的 约 柜 ， 柜 里 有 盛 吗 哪 的 金 罐 和 亚 伦 发 过 芽 的 杖 ， 并 两 块 约 版 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30110', '58', '9', '5', '柜 上 面 有 荣 耀 基 路 伯 的 影 罩 着 施 恩 ｛ 施 恩 ： 原 文 是 蔽 罪 ｝ 座 。 这 几 件 我 现 在 不 能 一 一 细 说 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30111', '58', '9', '6', '这 些 物 件 既 如 此 预 备 齐 了 ， 众 祭 司 就 常 进 头 一 层 帐 幕 ， 行 拜 神 的 礼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30112', '58', '9', '7', '至 于 第 二 层 帐 幕 ， 惟 有 大 祭 司 一 年 一 次 独 自 进 去 ， 没 有 不 带 着 血 为 自 己 和 百 姓 的 过 错 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30113', '58', '9', '8', '圣 灵 用 此 指 明 ， 头 一 层 帐 幕 仍 存 的 时 候 ， 进 入 至 圣 所 的 路 还 未 显 明 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30114', '58', '9', '9', '那 头 一 层 帐 幕 作 现 今 的 一 个 表 样 ， 所 献 的 礼 物 和 祭 物 ， 就 着 良 心 说 ， 都 不 能 叫 礼 拜 的 人 得 以 完 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30115', '58', '9', '10', '这 些 事 ， 连 那 饮 食 和 诸 般 洗 濯 的 规 矩 ， 都 不 过 是 属 肉 体 的 条 例 ， 命 定 到 振 兴 的 时 候 为 止 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30116', '58', '9', '11', '但 现 在 基 督 已 经 来 到 ， 作 了 将 来 美 事 的 大 祭 司 ， 经 过 那 更 大 更 全 备 的 帐 幕 ， 不 是 人 手 所 造 ， 也 不 是 属 乎 这 世 界 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30117', '58', '9', '12', '并 且 不 用 山 羊 和 牛 犊 的 血 ， 乃 用 自 己 的 血 ， 只 一 次 进 入 圣 所 ， 成 了 永 远 赎 罪 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30118', '58', '9', '13', '若 山 羊 和 公 牛 的 血 ， 并 母 牛 犊 的 灰 ， 洒 在 不 洁 的 人 身 上 ， 尚 且 叫 人 成 圣 ， 身 体 洁 净 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30119', '58', '9', '14', '何 况 基 督 藉 着 永 远 的 灵 ， 将 自 己 无 瑕 无 疵 献 给 神 ， 他 的 血 岂 不 更 能 洗 净 你 们 的 心 ｛ 原 文 是 良 心 ｝ ， 除 去 你 们 的 死 行 ， 使 你 们 事 奉 那 永 生 神 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30120', '58', '9', '15', '为 此 ， 他 作 了 新 约 的 中 保 ， 既 然 受 死 赎 了 人 在 前 约 之 时 所 犯 的 罪 过 ， 便 叫 蒙 召 之 人 得 着 所 应 许 永 远 的 产 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30121', '58', '9', '16', '凡 有 遗 命 必 须 等 到 留 遗 命 ｛ 遗 命 ： 原 文 与 约 字 同 ｝ 的 人 死 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30122', '58', '9', '17', '因 为 人 死 了 ， 遗 命 才 有 效 力 ， 若 留 遗 命 的 尚 在 ， 那 遗 命 还 有 用 处 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30123', '58', '9', '18', '所 以 ， 前 约 也 不 是 不 用 血 立 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30124', '58', '9', '19', '因 为 摩 西 当 日 照 着 律 法 将 各 样 诫 命 传 给 众 百 姓 ， 就 拿 朱 红 色 绒 和 牛 膝 草 ， 把 牛 犊 山 羊 的 血 和 水 洒 在 书 上 ， 又 洒 在 众 百 姓 身 上 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30125', '58', '9', '20', '“ 这 血 就 是 神 与 你 们 立 约 的 凭 据 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30126', '58', '9', '21', '他 又 照 样 把 血 洒 在 帐 幕 和 各 样 器 皿 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30127', '58', '9', '22', '按 着 律 法 ， 凡 物 差 不 多 都 是 用 血 洁 净 的 ； 若 不 流 血 ， 罪 就 不 得 赦 免 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30128', '58', '9', '23', '＜ 基 督 献 己 为 祭 除 掉 了 罪 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30129', '58', '9', '24', '因 为 基 督 并 不 是 进 了 人 手 所 造 的 圣 所 （ 这 不 过 是 真 圣 所 的 影 像 ） ， 乃 是 进 了 天 堂 ， 如 今 为 我 们 显 在 神 面 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30130', '58', '9', '25', '也 不 是 多 次 将 自 己 献 上 ， 像 那 大 祭 司 每 年 带 着 牛 羊 的 血 ｛ 牛 羊 的 血 ： 原 文 作 不 是 自 己 的 血 ｝ 进 入 圣 所 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30131', '58', '9', '26', '如 果 这 样 ， 他 从 创 世 以 来 ， 就 必 多 次 受 苦 了 。 但 如 今 在 这 末 世 显 现 一 次 ， 把 自 己 献 为 祭 ， 好 除 掉 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30132', '58', '9', '27', '按 着 定 命 ， 人 人 都 有 一 死 ， 死 后 且 有 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30133', '58', '9', '28', '像 这 样 ， 基 督 既 然 一 次 被 献 ， 担 当 了 多 人 的 罪 ， 将 来 要 向 那 等 候 他 的 人 第 二 次 显 现 ， 并 与 罪 无 关 ， 乃 是 为 拯 救 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30134', '58', '10', '1', '律 法 既 是 将 来 美 事 的 影 儿 ， 不 是 本 物 的 真 像 ， 总 不 能 藉 着 每 年 常 献 一 样 的 祭 物 叫 那 近 前 来 的 人 得 以 完 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30135', '58', '10', '2', '若 不 然 ， 献 祭 的 事 岂 不 早 已 止 住 了 吗 ？ 因 为 礼 拜 的 人 ， 良 心 既 被 洁 净 ， 就 不 再 觉 得 有 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30136', '58', '10', '3', '但 这 些 祭 物 是 叫 人 每 年 想 起 罪 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30137', '58', '10', '4', '因 为 公 牛 和 山 羊 的 血 ， 断 不 能 除 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30138', '58', '10', '5', '所 以 基 督 到 世 上 来 的 时 候 ， 就 说 ： 神 啊 ， 祭 物 和 礼 物 是 你 不 愿 意 的 ； 你 曾 给 我 预 备 了 身 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30139', '58', '10', '6', '燔 祭 和 赎 罪 祭 是 你 不 喜 欢 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30140', '58', '10', '7', '那 时 我 说 ： 神 啊 ， 我 来 了 ， 为 要 照 你 的 旨 意 行 ； 我 的 事 在 经 卷 上 已 经 记 载 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30141', '58', '10', '8', '以 上 说 ： “ 祭 物 和 礼 物 ， 燔 祭 和 赎 罪 祭 ， 是 你 不 愿 意 的 ， 也 是 你 不 喜 欢 的 （ 这 都 是 按 着 律 法 献 的 ） ” ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30142', '58', '10', '9', '后 又 说 ： “ 我 来 了 为 要 照 你 的 旨 意 行 ” ； 可 见 他 是 除 去 在 先 的 ， 为 要 立 定 在 后 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30143', '58', '10', '10', '我 们 凭 这 旨 意 ， 靠 耶 稣 基 督 ， 只 一 次 献 上 他 的 身 体 ， 就 得 以 成 圣 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30144', '58', '10', '11', '凡 祭 司 天 天 站 着 事 奉 神 ， 屡 次 献 上 一 样 的 祭 物 ， 这 祭 物 永 不 能 除 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30145', '58', '10', '12', '但 基 督 献 了 一 次 永 远 的 赎 罪 祭 ， 就 在 神 的 右 边 坐 下 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30146', '58', '10', '13', '从 此 ， 等 候 他 仇 敌 成 了 他 的 脚 凳 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30147', '58', '10', '14', '因 为 他 一 次 献 祭 ， 便 叫 那 得 以 成 圣 的 人 永 远 完 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30148', '58', '10', '15', '圣 灵 也 对 我 们 作 见 证 ； 因 为 他 既 已 说 过 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30149', '58', '10', '16', '主 说 ： 那 些 日 子 以 后 ， 我 与 他 们 所 立 的 约 乃 是 这 样 ： 我 要 将 我 的 律 法 写 在 他 们 心 上 ， 又 要 放 在 他 们 的 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30150', '58', '10', '17', '以 后 就 说 ： 我 不 再 记 念 他 们 的 罪 愆 和 他 们 的 过 犯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30151', '58', '10', '18', '这 些 罪 过 既 已 赦 免 ， 就 不 用 再 为 罪 献 祭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30152', '58', '10', '19', '＜ 劝 勉 和 警 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30153', '58', '10', '20', '是 藉 着 他 给 我 们 开 了 一 条 又 新 又 活 的 路 ， 从 幔 子 经 过 ， 这 幔 子 就 是 他 的 身 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30154', '58', '10', '21', '又 有 一 位 大 祭 司 治 理 神 的 家 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30155', '58', '10', '22', '并 我 们 心 中 天 良 的 亏 欠 已 经 洒 去 ， 身 体 用 清 水 洗 净 了 ， 就 当 存 着 诚 心 和 充 足 的 信 心 来 到 神 面 前 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30156', '58', '10', '23', '也 要 坚 守 我 们 所 承 认 的 指 望 ， 不 至 摇 动 ， 因 为 那 应 许 我 们 的 是 信 实 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30157', '58', '10', '24', '又 要 彼 此 相 顾 ， 激 发 爱 心 ， 勉 励 行 善 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30158', '58', '10', '25', '你 们 不 可 停 止 聚 会 ， 好 像 那 些 停 止 惯 了 的 人 ， 倒 要 彼 此 劝 勉 ， 既 知 道 ｛ 原 文 是 看 见 ｝ 那 日 子 临 近 ， 就 更 当 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30159', '58', '10', '26', '因 为 我 们 得 知 真 道 以 后 ， 若 故 意 犯 罪 ， 赎 罪 的 祭 就 再 没 有 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30160', '58', '10', '27', '惟 有 战 惧 等 候 审 判 和 那 烧 灭 众 敌 人 的 烈 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30161', '58', '10', '28', '人 干 犯 摩 西 的 律 法 ， 凭 两 三 个 见 证 人 ， 尚 且 不 得 怜 恤 而 死 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30162', '58', '10', '29', '何 况 人 践 踏 神 的 儿 子 ， 将 那 使 他 成 圣 之 约 的 血 当 作 平 常 ， 又 亵 慢 施 恩 的 圣 灵 ， 你 们 想 ， 他 要 受 的 刑 罚 该 怎 样 加 重 呢 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30163', '58', '10', '30', '因 为 我 们 知 道 谁 说 ： “ 伸 冤 在 我 ， 我 必 报 应 ” ； 又 说 ： “ 主 要 审 判 他 的 百 姓 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30164', '58', '10', '31', '落 在 永 生 神 的 手 里 ， 真 是 可 怕 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30165', '58', '10', '32', '你 们 要 追 念 往 日 ， 蒙 了 光 照 以 后 所 忍 受 大 争 战 的 各 样 苦 难 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30166', '58', '10', '33', '一 面 被 毁 谤 ， 遭 患 难 ， 成 了 戏 景 ， 叫 众 人 观 看 ； 一 面 陪 伴 那 些 受 这 样 苦 难 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30167', '58', '10', '34', '因 为 你 们 体 恤 了 那 些 被 捆 锁 的 人 ， 并 且 你 们 的 家 业 被 人 抢 去 ， 也 甘 心 忍 受 ， 知 道 自 己 有 更 美 长 存 的 家 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30168', '58', '10', '35', '所 以 ， 你 们 不 可 丢 弃 勇 敢 的 心 ； 存 这 样 的 心 必 得 大 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30169', '58', '10', '36', '你 们 必 须 忍 耐 ， 使 你 们 行 完 了 神 的 旨 意 ， 就 可 以 得 着 所 应 许 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30170', '58', '10', '37', '因 为 还 有 一 点 点 时 候 ， 那 要 来 的 就 来 ， 并 不 迟 延 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30171', '58', '10', '38', '只 是 义 人 ｛ 有 古 卷 ： 我 的 义 人 ｝ 必 因 信 得 生 。 他 若 退 后 ， 我 心 里 就 不 喜 欢 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30172', '58', '10', '39', '我 们 却 不 是 退 后 入 沉 沦 的 那 等 人 ， 乃 是 有 信 心 以 致 灵 魂 得 救 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30173', '58', '11', '1', '＜ 论 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30174', '58', '11', '2', '古 人 在 这 信 上 得 了 美 好 的 证 据 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30175', '58', '11', '3', '我 们 因 着 信 ， 就 知 道 诸 世 界 是 藉 神 话 造 成 的 ； 这 样 ， 所 看 见 的 ， 并 不 是 从 显 然 之 物 造 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30176', '58', '11', '4', '亚 伯 因 着 信 ， 献 祭 与 神 ， 比 该 隐 所 献 的 更 美 ， 因 此 便 得 了 称 义 的 见 证 ， 就 是 神 指 他 礼 物 作 的 见 证 。 他 虽 然 死 了 ， 却 因 这 信 ， 仍 旧 说 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30177', '58', '11', '5', '以 诺 因 着 信 ， 被 接 去 ， 不 至 于 见 死 ， 人 也 找 不 着 他 ， 因 为 神 已 经 把 他 接 去 了 ； 只 是 他 被 接 去 以 先 ， 已 经 得 了 神 喜 悦 他 的 明 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30178', '58', '11', '6', '人 非 有 信 ， 就 不 能 得 神 的 喜 悦 ； 因 为 到 神 面 前 来 的 人 必 须 信 有 神 ， 且 信 他 赏 赐 那 寻 求 他 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30179', '58', '11', '7', '挪 亚 因 着 信 ， 既 蒙 神 指 示 他 未 见 的 事 ， 动 了 敬 畏 的 心 ， 预 备 了 一 只 方 舟 ， 使 他 全 家 得 救 。 因 此 就 定 了 那 世 代 的 罪 ， 自 己 也 承 受 了 那 从 信 而 来 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30180', '58', '11', '8', '亚 伯 拉 罕 因 着 信 ， 蒙 召 的 时 候 就 遵 命 出 去 ， 往 将 来 要 得 为 业 的 地 方 去 ； 出 去 的 时 候 ， 还 不 知 往 哪 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30181', '58', '11', '9', '他 因 着 信 ， 就 在 所 应 许 之 地 作 客 ， 好 像 在 异 地 居 住 帐 棚 ， 与 那 同 蒙 一 个 应 许 的 以 撒 、 雅 各 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30182', '58', '11', '10', '因 为 他 等 候 那 座 有 根 基 的 城 ， 就 是 神 所 经 营 所 建 造 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30183', '58', '11', '11', '因 着 信 ， 连 撒 拉 自 己 ， 虽 然 过 了 生 育 的 岁 数 ， 还 能 怀 孕 ， 因 她 以 为 那 应 许 她 的 是 可 信 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30184', '58', '11', '12', '所 以 从 一 个 仿 佛 已 死 的 人 就 生 出 子 孙 ， 如 同 天 上 的 星 那 样 众 多 ， 海 边 的 沙 那 样 无 数 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30185', '58', '11', '13', '这 些 人 都 是 存 着 信 心 死 的 ， 并 没 有 得 着 所 应 许 的 ； 却 从 远 处 望 见 ， 且 欢 喜 迎 接 ， 又 承 认 自 己 在 世 上 是 客 旅 ， 是 寄 居 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30186', '58', '11', '14', '说 这 样 话 的 人 是 表 明 自 己 要 找 一 个 家 乡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30187', '58', '11', '15', '他 们 若 想 念 所 离 开 的 家 乡 ， 还 有 可 以 回 去 的 机 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30188', '58', '11', '16', '他 们 却 羡 慕 一 个 更 美 的 家 乡 ， 就 是 在 天 上 的 。 所 以 神 被 称 为 他 们 的 神 ， 并 不 以 为 耻 ， 因 为 他 已 经 给 他 们 预 备 了 一 座 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30189', '58', '11', '17', '亚 伯 拉 罕 因 着 信 ， 被 试 验 的 时 候 ， 就 把 以 撒 献 上 ； 这 便 是 那 欢 喜 领 受 应 许 的 ， 将 自 己 独 生 的 儿 子 献 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30190', '58', '11', '18', '论 到 这 儿 子 ， 曾 有 话 说 ： “ 从 以 撒 生 的 才 要 称 为 你 的 后 裔 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30191', '58', '11', '19', '他 以 为 神 还 能 叫 人 从 死 里 复 活 ； 他 也 仿 佛 从 死 中 得 回 他 的 儿 子 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30192', '58', '11', '20', '以 撒 因 着 信 ， 就 指 着 将 来 的 事 给 雅 各 、 以 扫 祝 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30193', '58', '11', '21', '雅 各 因 着 信 ， 临 死 的 时 候 ， 给 约 瑟 的 两 个 儿 子 各 自 祝 福 ， 扶 着 杖 头 敬 拜 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30194', '58', '11', '22', '约 瑟 因 着 信 ， 临 终 的 时 候 ， 提 到 以 色 列 族 将 来 要 出 埃 及 ， 并 为 自 己 的 骸 骨 留 下 遗 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30195', '58', '11', '23', '摩 西 生 下 来 ， 他 的 父 母 见 他 是 个 俊 美 的 孩 子 ， 就 因 着 信 ， 把 他 藏 了 三 个 月 ， 并 不 怕 王 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30196', '58', '11', '24', '摩 西 因 着 信 ， 长 大 了 就 不 肯 称 为 法 老 女 儿 之 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30197', '58', '11', '25', '他 宁 可 和 神 的 百 姓 同 受 苦 害 ， 也 不 愿 暂 时 享 受 罪 中 之 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30198', '58', '11', '26', '他 看 为 基 督 受 的 凌 辱 比 埃 及 的 财 物 更 宝 贵 ， 因 他 想 望 所 要 得 的 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30199', '58', '11', '27', '他 因 着 信 ， 就 离 开 埃 及 ， 不 怕 王 怒 ； 因 为 他 恒 心 忍 耐 ， 如 同 看 见 那 不 能 看 见 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30200', '58', '11', '28', '他 因 着 信 ， 就 守 ｛ 或 译 ： 立 ｝ 逾 越 节 ， 行 洒 血 的 礼 ， 免 得 那 灭 长 子 的 临 近 以 色 列 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30201', '58', '11', '29', '他 们 因 着 信 ， 过 红 海 如 行 干 地 ； 埃 及 人 试 着 要 过 去 ， 就 被 吞 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30202', '58', '11', '30', '以 色 列 人 因 着 信 ， 围 绕 耶 利 哥 城 七 日 ， 城 墙 就 倒 塌 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30203', '58', '11', '31', '妓 女 喇 合 因 着 信 ， 曾 和 和 平 平 地 接 待 探 子 ， 就 不 与 那 些 不 顺 从 的 人 一 同 灭 亡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30204', '58', '11', '32', '我 又 何 必 再 说 呢 ？ 若 要 一 一 细 说 ， 基 甸 、 巴 拉 、 参 孙 、 耶 弗 他 、 大 卫 、 撒 母 耳 ， 和 众 先 知 的 事 ， 时 候 就 不 够 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30205', '58', '11', '33', '他 们 因 着 信 ， 制 伏 了 敌 国 ， 行 了 公 义 ， 得 了 应 许 ， 堵 了 狮 子 的 口 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30206', '58', '11', '34', '灭 了 烈 火 的 猛 势 ， 脱 了 刀 剑 的 锋 刃 ； 软 弱 变 为 刚 强 ， 争 战 显 出 勇 敢 ， 打 退 外 邦 的 全 军 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30207', '58', '11', '35', '有 妇 人 得 自 己 的 死 人 复 活 。 又 有 人 忍 受 严 刑 ， 不 肯 苟 且 得 释 放 ｛ 原 文 是 赎 ｝ ， 为 要 得 着 更 美 的 复 活 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30208', '58', '11', '36', '又 有 人 忍 受 戏 弄 、 鞭 打 、 捆 锁 、 监 禁 、 各 等 的 磨 炼 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30209', '58', '11', '37', '被 石 头 打 死 ， 被 锯 锯 死 ， 受 试 探 ， 被 刀 杀 ， 披 着 绵 羊 、 山 羊 的 皮 各 处 奔 跑 ， 受 穷 乏 、 患 难 、 苦 害 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30210', '58', '11', '38', '在 旷 野 、 山 岭 、 山 洞 、 地 穴 ， 飘 流 无 定 ， 本 是 世 界 不 配 有 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30211', '58', '11', '39', '这 些 人 都 是 因 信 得 了 美 好 的 证 据 ， 却 仍 未 得 着 所 应 许 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30212', '58', '11', '40', '因 为 神 给 我 们 预 备 了 更 美 的 事 ， 叫 他 们 若 不 与 我 们 同 得 ， 就 不 能 完 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30213', '58', '12', '1', '＜ 主 的 管 教 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30214', '58', '12', '2', '仰 望 为 我 们 信 心 创 始 成 终 的 耶 稣 ｛ 或 译 ： 仰 望 那 将 真 道 创 始 成 终 的 耶 稣 ｝ 。 他 因 那 摆 在 前 面 的 喜 乐 ， 就 轻 看 羞 辱 ， 忍 受 了 十 字 架 的 苦 难 ， 便 坐 在 神 宝 座 的 右 边 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30215', '58', '12', '3', '那 忍 受 罪 人 这 样 顶 撞 的 ， 你 们 要 思 想 ， 免 得 疲 倦 灰 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30216', '58', '12', '4', '你 们 与 罪 恶 相 争 ， 还 没 有 抵 挡 到 流 血 的 地 步 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30217', '58', '12', '5', '你 们 又 忘 了 那 劝 你 们 如 同 劝 儿 子 的 话 ， 说 ： 我 儿 ， 你 不 可 轻 看 主 的 管 教 ， 被 他 责 备 的 时 候 也 不 可 灰 心 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30218', '58', '12', '6', '因 为 主 所 爱 的 ， 他 必 管 教 ， 又 鞭 打 凡 所 收 纳 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30219', '58', '12', '7', '你 们 所 忍 受 的 ， 是 神 管 教 你 们 ， 待 你 们 如 同 待 儿 子 。 焉 有 儿 子 不 被 父 亲 管 教 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30220', '58', '12', '8', '管 教 原 是 众 子 所 共 受 的 。 你 们 若 不 受 管 教 ， 就 是 私 子 ， 不 是 儿 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30221', '58', '12', '9', '再 者 ， 我 们 曾 有 生 身 的 父 管 教 我 们 ， 我 们 尚 且 敬 重 他 ， 何 况 万 灵 的 父 ， 我 们 岂 不 更 当 顺 服 他 得 生 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30222', '58', '12', '10', '生 身 的 父 都 是 暂 随 己 意 管 教 我 们 ； 惟 有 万 灵 的 父 管 教 我 们 ， 是 要 我 们 得 益 处 ， 使 我 们 在 他 的 圣 洁 上 有 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30223', '58', '12', '11', '凡 管 教 的 事 ， 当 时 不 觉 得 快 乐 ， 反 觉 得 愁 苦 ； 后 来 却 为 那 经 练 过 的 人 结 出 平 安 的 果 子 ， 就 是 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30224', '58', '12', '12', '所 以 ， 你 们 要 把 下 垂 的 手 、 发 酸 的 腿 挺 起 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30225', '58', '12', '13', '也 要 为 自 己 的 脚 ， 把 道 路 修 直 了 ， 使 瘸 子 不 致 歪 脚 ｛ 或 译 ： 差 路 ｝ ， 反 得 痊 愈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30226', '58', '12', '14', '＜ 警 告 弃 绝 神 恩 典 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30227', '58', '12', '15', '又 要 谨 慎 ， 恐 怕 有 人 失 了 神 的 恩 ； 恐 怕 有 毒 根 生 出 来 扰 乱 你 们 ， 因 此 叫 众 人 沾 染 污 秽 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30228', '58', '12', '16', '恐 怕 有 淫 乱 的 ， 有 贪 恋 世 俗 如 以 扫 的 ， 他 因 一 点 食 物 把 自 己 长 子 的 名 分 卖 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30229', '58', '12', '17', '后 来 想 要 承 受 父 所 祝 的 福 ， 竟 被 弃 绝 ， 虽 然 号 哭 切 求 ， 却 得 不 着 门 路 使 他 父 亲 的 心 意 回 转 。 这 是 你 们 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30230', '58', '12', '18', '你 们 原 不 是 来 到 那 能 摸 的 山 ； 此 山 有 火 焰 、 密 云 、 黑 暗 、 暴 风 、');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30231', '58', '12', '19', '角 声 与 说 话 的 声 音 。 那 些 听 见 这 声 音 的 ， 都 求 不 要 再 向 他 们 说 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30232', '58', '12', '20', '因 为 他 们 当 不 起 所 命 他 们 的 话 ， 说 ： “ 靠 近 这 山 的 ， 即 便 是 走 兽 ， 也 要 用 石 头 打 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30233', '58', '12', '21', '所 见 的 极 其 可 怕 ， 甚 至 摩 西 说 ： “ 我 甚 是 恐 惧 战 兢 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30234', '58', '12', '22', '你 们 乃 是 来 到 锡 安 山 ， 永 生 神 的 城 邑 ， 就 是 天 上 的 耶 路 撒 冷 。 那 里 有 千 万 的 天 使 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30235', '58', '12', '23', '有 名 录 在 天 上 诸 长 子 之 会 所 共 聚 的 总 会 ， 有 审 判 众 人 的 神 和 被 成 全 之 义 人 的 灵 魂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30236', '58', '12', '24', '并 新 约 的 中 保 耶 稣 ， 以 及 所 洒 的 血 ； 这 血 所 说 的 比 亚 伯 的 血 所 说 的 更 美 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30237', '58', '12', '25', '你 们 总 要 谨 慎 ， 不 可 弃 绝 那 向 你 们 说 话 的 。 因 为 ， 那 些 弃 绝 在 地 上 警 戒 他 们 的 尚 且 不 能 逃 罪 ， 何 况 我 们 违 背 那 从 天 上 警 戒 我 们 的 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30238', '58', '12', '26', '当 时 他 的 声 音 震 动 了 地 ， 但 如 今 他 应 许 说 ： “ 再 一 次 我 不 单 要 震 动 地 ， 还 要 震 动 天 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30239', '58', '12', '27', '这 再 一 次 的 话 ， 是 指 明 被 震 动 的 ， 就 是 受 造 之 物 都 要 挪 去 ， 使 那 不 被 震 动 的 常 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30240', '58', '12', '28', '所 以 我 们 既 得 了 不 能 震 动 的 国 ， 就 当 感 恩 ， 照 神 所 喜 悦 的 ， 用 虔 诚 、 敬 畏 的 心 事 奉 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30241', '58', '12', '29', '因 为 我 们 的 神 乃 是 烈 火 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30242', '58', '13', '1', '＜ 蒙 神 悦 纳 的 服 务 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30243', '58', '13', '2', '不 可 忘 记 用 爱 心 接 待 客 旅 ； 因 为 曾 有 接 待 客 旅 的 ， 不 知 不 觉 就 接 待 了 天 使 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30244', '58', '13', '3', '你 们 要 记 念 被 捆 绑 的 人 ， 好 像 与 他 们 同 受 捆 绑 ； 也 要 记 念 遭 苦 害 的 人 ， 想 到 自 己 也 在 肉 身 之 内 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30245', '58', '13', '4', '婚 姻 ， 人 人 都 当 尊 重 ， 床 也 不 可 污 秽 ； 因 为 苟 合 行 淫 的 人 ， 神 必 要 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30246', '58', '13', '5', '你 们 存 心 不 可 贪 爱 钱 财 ， 要 以 自 己 所 有 的 为 足 ； 因 为 主 曾 说 ： “ 我 总 不 撇 下 你 ， 也 不 丢 弃 你 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30247', '58', '13', '6', '所 以 我 们 可 以 放 胆 说 ： 主 是 帮 助 我 的 ， 我 必 不 惧 怕 ； 人 能 把 我 怎 么 样 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30248', '58', '13', '7', '从 前 引 导 你 们 、 传 神 之 道 给 你 们 的 人 ， 你 们 要 想 念 他 们 ， 效 法 他 们 的 信 心 ， 留 心 看 他 们 为 人 的 结 局 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30249', '58', '13', '8', '耶 稣 基 督 昨 日 、 今 日 、 一 直 到 永 远 ， 是 一 样 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30250', '58', '13', '9', '你 们 不 要 被 那 诸 般 怪 异 的 教 训 勾 引 了 去 ； 因 为 人 心 靠 恩 得 坚 固 才 是 好 的 ， 并 不 是 靠 饮 食 。 那 在 饮 食 上 专 心 的 从 来 没 有 得 着 益 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30251', '58', '13', '10', '我 们 有 一 祭 坛 ， 上 面 的 祭 物 是 那 些 在 帐 幕 中 供 职 的 人 不 可 同 吃 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30252', '58', '13', '11', '原 来 牲 畜 的 血 被 大 祭 司 带 入 圣 所 作 赎 罪 祭 ； 牲 畜 的 身 子 被 烧 在 营 外 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30253', '58', '13', '12', '所 以 ， 耶 稣 要 用 自 己 的 血 叫 百 姓 成 圣 ， 也 就 在 城 门 外 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30254', '58', '13', '13', '这 样 ， 我 们 也 当 出 到 营 外 ， 就 了 他 去 ， 忍 受 他 所 受 的 凌 辱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30255', '58', '13', '14', '我 们 在 这 里 本 没 有 常 存 的 城 ， 乃 是 寻 求 那 将 来 的 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30256', '58', '13', '15', '我 们 应 当 靠 着 耶 稣 ， 常 常 以 颂 赞 为 祭 献 给 神 ， 这 就 是 那 承 认 主 名 之 人 嘴 唇 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30257', '58', '13', '16', '只 是 不 可 忘 记 行 善 和 捐 输 的 事 ， 因 为 这 样 的 祭 是 神 所 喜 悦 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30258', '58', '13', '17', '你 们 要 依 从 那 些 引 导 你 们 的 ， 且 要 顺 服 ； 因 他 们 为 你 们 的 灵 魂 时 刻 警 醒 ， 好 像 那 将 来 交 帐 的 人 。 你 们 要 使 他 们 交 的 时 候 有 快 乐 ， 不 致 忧 愁 ； 若 忧 愁 就 与 你 们 无 益 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30259', '58', '13', '18', '请 你 们 为 我 们 祷 告 ， 因 我 们 自 觉 良 心 无 亏 ， 愿 意 凡 事 按 正 道 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30260', '58', '13', '19', '我 更 求 你 们 为 我 祷 告 ， 使 我 快 些 回 到 你 们 那 里 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30261', '58', '13', '20', '＜ 祝 福 和 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30262', '58', '13', '21', '在 各 样 善 事 上 成 全 你 们 ， 叫 你 们 遵 行 他 的 旨 意 ； 又 藉 着 耶 稣 基 督 在 你 们 心 里 行 他 所 喜 悦 的 事 。 愿 荣 耀 归 给 他 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30263', '58', '13', '22', '弟 兄 们 ， 我 略 略 写 信 给 你 们 ， 望 你 们 听 我 劝 勉 的 话 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30264', '58', '13', '23', '你 们 该 知 道 ， 我 们 的 兄 弟 提 摩 太 已 经 释 放 了 ； 他 若 快 来 ， 我 必 同 他 去 见 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30265', '58', '13', '24', '请 你 们 问 引 导 你 们 的 诸 位 和 众 圣 徒 安 。 从 意 大 利 来 的 人 也 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30266', '58', '13', '25', '愿 恩 惠 常 与 你 们 众 人 同 在 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30267', '59', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30268', '59', '1', '2', '＜ 信 心 和 智 慧 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30269', '59', '1', '3', '因 为 知 道 你 们 的 信 心 经 过 试 验 ， 就 生 忍 耐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30270', '59', '1', '4', '但 忍 耐 也 当 成 功 ， 使 你 们 成 全 、 完 备 ， 毫 无 缺 欠 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30271', '59', '1', '5', '你 们 中 间 若 有 缺 少 智 慧 的 ， 应 当 求 那 厚 赐 与 众 人 、 也 不 斥 责 人 的 神 ， 主 就 必 赐 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30272', '59', '1', '6', '只 要 凭 着 信 心 求 ， 一 点 不 疑 惑 ； 因 为 那 疑 惑 的 人 ， 就 像 海 中 的 波 浪 ， 被 风 吹 动 翻 腾 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30273', '59', '1', '7', '这 样 的 人 不 要 想 从 主 那 里 得 什 么 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30274', '59', '1', '8', '心 怀 二 意 的 人 ， 在 他 一 切 所 行 的 路 上 都 没 有 定 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30275', '59', '1', '9', '＜ 贫 穷 和 富 有 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30276', '59', '1', '10', '富 足 的 降 卑 ， 也 该 如 此 ； 因 为 他 必 要 过 去 ， 如 同 草 上 的 花 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30277', '59', '1', '11', '太 阳 出 来 ， 热 风 刮 起 ， 草 就 枯 干 ， 花 也 凋 谢 ， 美 容 就 消 没 了 ； 那 富 足 的 人 ， 在 他 所 行 的 事 上 也 要 这 样 衰 残 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30278', '59', '1', '12', '＜ 考 验 和 试 探 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30279', '59', '1', '13', '人 被 试 探 ， 不 可 说 ： “ 我 是 被 神 试 探 ” ； 因 为 神 不 能 被 恶 试 探 ， 他 也 不 试 探 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30280', '59', '1', '14', '但 各 人 被 试 探 ， 乃 是 被 自 己 的 私 欲 牵 引 诱 惑 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30281', '59', '1', '15', '私 欲 既 怀 了 胎 ， 就 生 出 罪 来 ； 罪 既 长 成 ， 就 生 出 死 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30282', '59', '1', '16', '我 亲 爱 的 弟 兄 们 ， 不 要 看 错 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30283', '59', '1', '17', '各 样 美 善 的 恩 赐 和 各 样 全 备 的 赏 赐 都 是 从 上 头 来 的 ， 从 众 光 之 父 那 里 降 下 来 的 ； 在 他 并 没 有 改 变 ， 也 没 有 转 动 的 影 儿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30284', '59', '1', '18', '他 按 自 己 的 旨 意 ， 用 真 道 生 了 我 们 ， 叫 我 们 在 他 所 造 的 万 物 中 好 像 初 熟 的 果 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30285', '59', '1', '19', '＜ 听 道 和 行 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30286', '59', '1', '20', '因 为 人 的 怒 气 并 不 成 就 神 的 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30287', '59', '1', '21', '所 以 ， 你 们 要 脱 去 一 切 的 污 秽 和 盈 余 的 邪 恶 ， 存 温 柔 的 心 领 受 那 所 栽 种 的 道 ， 就 是 能 救 你 们 灵 魂 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30288', '59', '1', '22', '只 是 你 们 要 行 道 ， 不 要 单 单 听 道 ， 自 己 欺 哄 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30289', '59', '1', '23', '因 为 听 道 而 不 行 道 的 ， 就 像 人 对 着 镜 子 看 自 己 本 来 的 面 目 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30290', '59', '1', '24', '看 见 ， 走 后 ， 随 即 忘 了 他 的 相 貌 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30291', '59', '1', '25', '惟 有 详 细 察 看 那 全 备 、 使 人 自 由 之 律 法 的 ， 并 且 时 常 如 此 ， 这 人 既 不 是 听 了 就 忘 ， 乃 是 实 在 行 出 来 ， 就 在 他 所 行 的 事 上 必 然 得 福 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30292', '59', '1', '26', '若 有 人 自 以 为 虔 诚 ， 却 不 勒 住 他 的 舌 头 ， 反 欺 哄 自 己 的 心 ， 这 人 的 虔 诚 是 虚 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30293', '59', '1', '27', '在 神 我 们 的 父 面 前 ， 那 清 洁 没 有 玷 污 的 虔 诚 ， 就 是 看 顾 在 患 难 中 的 孤 儿 寡 妇 ， 并 且 保 守 自 己 不 沾 染 世 俗 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30294', '59', '2', '1', '＜ 警 告 偏 私 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30295', '59', '2', '2', '若 有 一 个 人 带 着 金 戒 指 ， 穿 着 华 美 衣 服 ， 进 你 们 的 会 堂 去 ； 又 有 一 个 穷 人 穿 着 肮 脏 衣 服 也 进 去 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30296', '59', '2', '3', '你 们 就 重 看 那 穿 华 美 衣 服 的 人 ， 说 ： “ 请 坐 在 这 好 位 上 ” ； 又 对 那 穷 人 说 ： “ 你 站 在 那 里 ” ， 或 “ 坐 在 我 脚 凳 下 边 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30297', '59', '2', '4', '这 岂 不 是 你 们 偏 心 待 人 ， 用 恶 意 断 定 人 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30298', '59', '2', '5', '我 亲 爱 的 弟 兄 们 ， 请 听 ， 神 岂 不 是 拣 选 了 世 上 的 贫 穷 人 ， 叫 他 们 在 信 上 富 足 ， 并 承 受 他 所 应 许 给 那 些 爱 他 之 人 的 国 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30299', '59', '2', '6', '你 们 反 倒 羞 辱 贫 穷 人 。 那 富 足 人 岂 不 是 欺 压 你 们 、 拉 你 们 到 公 堂 去 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30300', '59', '2', '7', '他 们 不 是 亵 渎 你 们 所 敬 奉 ｛ 所 敬 奉 ： 或 译 被 称 ｝ 的 尊 名 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30301', '59', '2', '8', '经 上 记 着 说 ： “ 要 爱 人 如 己 。 ” 你 们 若 全 守 这 至 尊 的 律 法 才 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30302', '59', '2', '9', '但 你 们 若 按 外 貌 待 人 ， 便 是 犯 罪 ， 被 律 法 定 为 犯 法 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30303', '59', '2', '10', '因 为 凡 遵 守 全 律 法 的 ， 只 在 一 条 上 跌 倒 ， 他 就 是 犯 了 众 条 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30304', '59', '2', '11', '原 来 那 说 “ 不 可 奸 淫 ” 的 ， 也 说 “ 不 可 杀 人 ” ； 你 就 是 不 奸 淫 ， 却 杀 人 ， 仍 是 成 了 犯 律 法 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30305', '59', '2', '12', '你 们 既 然 要 按 使 人 自 由 的 律 法 受 审 判 ， 就 该 照 这 律 法 说 话 行 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30306', '59', '2', '13', '因 为 那 不 怜 悯 人 的 ， 也 要 受 无 怜 悯 的 审 判 ； 怜 悯 原 是 向 审 判 夸 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30307', '59', '2', '14', '我 的 弟 兄 们 ， 若 有 人 说 自 己 有 信 心 ， 却 没 有 行 为 ， 有 什 么 益 处 呢 ？ 这 信 心 能 救 他 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30308', '59', '2', '15', '若 是 弟 兄 或 是 姊 妹 ， 赤 身 露 体 ， 又 缺 了 日 用 的 饮 食 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30309', '59', '2', '16', '你 们 中 间 有 人 对 他 们 说 ： “ 平 平 安 安 地 去 吧 ！ 愿 你 们 穿 得 暖 ， 吃 得 饱 ” ， 却 不 给 他 们 身 体 所 需 用 的 ， 这 有 什 么 益 处 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30310', '59', '2', '17', '这 样 ， 信 心 若 没 有 行 为 就 是 死 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30311', '59', '2', '18', '必 有 人 说 ： “ 你 有 信 心 ， 我 有 行 为 ； 你 将 你 没 有 行 为 的 信 心 指 给 我 看 ， 我 便 藉 着 我 的 行 为 ， 将 我 的 信 心 指 给 你 看 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30312', '59', '2', '19', '你 信 神 只 有 一 位 ， 你 信 的 不 错 ； 鬼 魔 也 信 ， 却 是 战 惊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30313', '59', '2', '20', '虚 浮 的 人 哪 ， 你 愿 意 知 道 没 有 行 为 的 信 心 是 死 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30314', '59', '2', '21', '我 们 的 祖 宗 亚 伯 拉 罕 把 他 儿 子 以 撒 献 在 坛 上 ， 岂 不 是 因 行 为 称 义 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30315', '59', '2', '22', '可 见 ， 信 心 是 与 他 的 行 为 并 行 ， 而 且 信 心 因 着 行 为 才 得 成 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30316', '59', '2', '23', '这 就 应 验 经 上 所 说 ： “ 亚 伯 拉 罕 信 神 ， 这 就 算 为 他 的 义 。 ” 他 又 得 称 为 神 的 朋 友 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30317', '59', '2', '24', '这 样 看 来 ， 人 称 义 是 因 着 行 为 ， 不 是 单 因 着 信 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30318', '59', '2', '25', '妓 女 喇 合 接 待 使 者 ， 又 放 他 们 从 别 的 路 上 出 去 ， 不 也 是 一 样 因 行 为 称 义 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30319', '59', '2', '26', '身 体 没 有 灵 魂 是 死 的 ， 信 心 没 有 行 为 也 是 死 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30320', '59', '3', '1', '＜ 论 舌 头 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30321', '59', '3', '2', '原 来 我 们 在 许 多 事 上 都 有 过 失 ； 若 有 人 在 话 语 上 没 有 过 失 ， 他 就 是 完 全 人 ， 也 能 勒 住 自 己 的 全 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30322', '59', '3', '3', '我 们 若 把 嚼 环 放 在 马 嘴 里 ， 叫 它 顺 服 ， 就 能 调 动 它 的 全 身 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30323', '59', '3', '4', '看 哪 ， 船 只 虽 然 甚 大 ， 又 被 大 风 催 逼 ， 只 用 小 小 的 舵 ， 就 随 着 掌 舵 的 意 思 转 动 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30324', '59', '3', '5', '这 样 ， 舌 头 在 百 体 里 也 是 最 小 的 ， 却 能 说 大 话 。 看 哪 ， 最 小 的 火 能 点 着 最 大 的 树 林 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30325', '59', '3', '6', '舌 头 就 是 火 ， 在 我 们 百 体 中 ， 舌 头 是 个 罪 恶 的 世 界 ， 能 污 秽 全 身 ， 也 能 把 生 命 的 轮 子 点 起 来 ， 并 且 是 从 地 狱 里 点 着 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30326', '59', '3', '7', '各 类 的 走 兽 、 飞 禽 、 昆 虫 、 水 族 ， 本 来 都 可 以 制 伏 ， 也 已 经 被 人 制 伏 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30327', '59', '3', '8', '惟 独 舌 头 没 有 人 能 制 伏 ， 是 不 止 息 的 恶 物 ， 满 了 害 死 人 的 毒 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30328', '59', '3', '9', '我 们 用 舌 头 颂 赞 那 为 主 、 为 父 的 ， 又 用 舌 头 咒 诅 那 照 着 神 形 像 被 造 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30329', '59', '3', '10', '颂 赞 和 咒 诅 从 一 个 口 里 出 来 ！ 我 的 弟 兄 们 ， 这 是 不 应 当 的 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30330', '59', '3', '11', '泉 源 从 一 个 眼 里 能 发 出 甜 苦 两 样 的 水 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30331', '59', '3', '12', '我 的 弟 兄 们 ， 无 花 果 树 能 生 橄 榄 吗 ？ 葡 萄 树 能 结 无 花 果 吗 ？ 咸 水 里 也 不 能 发 出 甜 水 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30332', '59', '3', '13', '＜ 论 从 上 头 来 的 智 慧 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30333', '59', '3', '14', '你 们 心 里 若 怀 着 苦 毒 的 嫉 妒 和 纷 争 ， 就 不 可 自 夸 ， 也 不 可 说 谎 话 抵 挡 真 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30334', '59', '3', '15', '这 样 的 智 慧 不 是 从 上 头 来 的 ， 乃 是 属 地 的 ， 属 情 欲 的 ， 属 鬼 魔 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30335', '59', '3', '16', '在 何 处 有 嫉 妒 、 纷 争 ， 就 在 何 处 有 扰 乱 和 各 样 的 坏 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30336', '59', '3', '17', '惟 独 从 上 头 来 的 智 慧 ， 先 是 清 洁 ， 后 是 和 平 ， 温 良 柔 顺 ， 满 有 怜 悯 ， 多 结 善 果 ， 没 有 偏 见 ， 没 有 假 冒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30337', '59', '3', '18', '并 且 使 人 和 平 的 ， 是 用 和 平 所 栽 种 的 义 果 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30338', '59', '4', '1', '＜ 与 世 俗 为 友 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30339', '59', '4', '2', '你 们 贪 恋 ， 还 是 得 不 着 ； 你 们 杀 害 嫉 妒 ， 又 斗 殴 争 战 ， 也 不 能 得 。 你 们 得 不 着 ， 是 因 为 你 们 不 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30340', '59', '4', '3', '你 们 求 也 得 不 着 ， 是 因 为 你 们 妄 求 ， 要 浪 费 在 你 们 的 宴 乐 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30341', '59', '4', '4', '你 们 这 些 淫 乱 的 人 ｛ 原 文 是 淫 妇 ｝ 哪 ， 岂 不 知 与 世 俗 为 友 就 是 与 神 为 敌 吗 ？ 所 以 凡 想 要 与 世 俗 为 友 的 ， 就 是 与 神 为 敌 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30342', '59', '4', '5', '你 们 想 经 上 所 说 是 徒 然 的 吗 ？ 神 所 赐 、 住 在 我 们 里 面 的 灵 ， 是 恋 爱 至 于 嫉 妒 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30343', '59', '4', '6', '但 他 赐 更 多 的 恩 典 ， 所 以 经 上 说 ： 神 阻 挡 骄 傲 的 人 ， 赐 恩 给 谦 卑 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30344', '59', '4', '7', '故 此 ， 你 们 要 顺 服 神 。 务 要 抵 挡 魔 鬼 ， 魔 鬼 就 必 离 开 你 们 逃 跑 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30345', '59', '4', '8', '你 们 亲 近 神 ， 神 就 必 亲 近 你 们 。 有 罪 的 人 哪 ， 要 洁 净 你 们 的 手 ！ 心 怀 二 意 的 人 哪 ， 要 清 洁 你 们 的 心 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30346', '59', '4', '9', '你 们 要 愁 苦 、 悲 哀 、 哭 泣 ， 将 喜 笑 变 作 悲 哀 ， 欢 乐 变 作 愁 闷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30347', '59', '4', '10', '务 要 在 主 面 前 自 卑 ， 主 就 必 叫 你 们 升 高 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30348', '59', '4', '11', '＜ 论 断 弟 兄 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30349', '59', '4', '12', '设 立 律 法 和 判 断 人 的 ， 只 有 一 位 ， 就 是 那 能 救 人 也 能 灭 人 的 。 你 是 谁 ， 竟 敢 论 断 别 人 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30350', '59', '4', '13', '＜ 警 戒 自 夸 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30351', '59', '4', '14', '其 实 明 天 如 何 ， 你 们 还 不 知 道 。 你 们 的 生 命 是 什 么 呢 ？ 你 们 原 来 是 一 片 云 雾 ， 出 现 少 时 就 不 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30352', '59', '4', '15', '你 们 只 当 说 ： “ 主 若 愿 意 ， 我 们 就 可 以 活 着 ， 也 可 以 做 这 事 ， 或 做 那 事 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30353', '59', '4', '16', '现 今 你 们 竟 以 张 狂 夸 口 ； 凡 这 样 夸 口 都 是 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30354', '59', '4', '17', '人 若 知 道 行 善 ， 却 不 去 行 ， 这 就 是 他 的 罪 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30355', '59', '5', '1', '＜ 警 告 富 足 的 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30356', '59', '5', '2', '你 们 的 财 物 坏 了 ， 衣 服 也 被 虫 子 咬 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30357', '59', '5', '3', '你 们 的 金 银 都 长 了 锈 ； 那 锈 要 证 明 你 们 的 不 是 ， 又 要 吃 你 们 的 肉 ， 如 同 火 烧 。 你 们 在 这 末 世 只 知 积 攒 钱 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30358', '59', '5', '4', '工 人 给 你 们 收 割 庄 稼 ， 你 们 亏 欠 他 们 的 工 钱 ， 这 工 钱 有 声 音 呼 叫 ， 并 且 那 收 割 之 人 的 冤 声 已 经 入 了 万 军 之 主 的 耳 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30359', '59', '5', '5', '你 们 在 世 上 享 美 福 ， 好 宴 乐 ， 当 宰 杀 的 日 子 竟 娇 养 你 们 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30360', '59', '5', '6', '你 们 定 了 义 人 的 罪 ， 把 他 杀 害 ， 他 也 不 抵 挡 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30361', '59', '5', '7', '＜ 忍 耐 和 祷 告 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30362', '59', '5', '8', '你 们 也 当 忍 耐 ， 坚 固 你 们 的 心 ， 因 为 主 来 的 日 子 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30363', '59', '5', '9', '弟 兄 们 ， 你 们 不 要 彼 此 埋 怨 ， 免 得 受 审 判 。 看 哪 ， 审 判 的 主 站 在 门 前 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30364', '59', '5', '10', '弟 兄 们 ， 你 们 要 把 那 先 前 奉 主 名 说 话 的 众 先 知 当 作 能 受 苦 能 忍 耐 的 榜 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30365', '59', '5', '11', '那 先 前 忍 耐 的 人 ， 我 们 称 他 们 是 有 福 的 。 你 们 听 见 过 约 伯 的 忍 耐 ， 也 知 道 主 给 他 的 结 局 ， 明 显 主 是 满 心 怜 悯 ， 大 有 慈 悲 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30366', '59', '5', '12', '我 的 弟 兄 们 ， 最 要 紧 的 是 不 可 起 誓 ； 不 可 指 着 天 起 誓 ， 也 不 可 指 着 地 起 誓 ， 无 论 何 誓 都 不 可 起 。 你 们 说 话 ， 是 ， 就 说 是 ； 不 是 ， 就 说 不 是 ， 免 得 你 们 落 在 审 判 之 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30367', '59', '5', '13', '你 们 中 间 有 受 苦 的 呢 ， 他 就 该 祷 告 ； 有 喜 乐 的 呢 ， 他 就 该 歌 颂 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30368', '59', '5', '14', '你 们 中 间 有 病 了 的 呢 ， 他 就 该 请 教 会 的 长 老 来 ； 他 们 可 以 奉 主 的 名 用 油 抹 他 ， 为 他 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30369', '59', '5', '15', '出 于 信 心 的 祈 祷 要 救 那 病 人 ， 主 必 叫 他 起 来 ； 他 若 犯 了 罪 ， 也 必 蒙 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30370', '59', '5', '16', '所 以 你 们 要 彼 此 认 罪 ， 互 相 代 求 ， 使 你 们 可 以 得 医 治 。 义 人 祈 祷 所 发 的 力 量 是 大 有 功 效 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30371', '59', '5', '17', '以 利 亚 与 我 们 是 一 样 性 情 的 人 ， 他 恳 切 祷 告 ， 求 不 要 下 雨 ， 雨 就 三 年 零 六 个 月 不 下 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30372', '59', '5', '18', '他 又 祷 告 ， 天 就 降 下 雨 来 ， 地 也 生 出 土 产 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30373', '59', '5', '19', '我 的 弟 兄 们 ， 你 们 中 间 若 有 失 迷 真 道 的 ， 有 人 使 他 回 转 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30374', '59', '5', '20', '这 人 该 知 道 ： 叫 一 个 罪 人 从 迷 路 上 转 回 便 是 救 一 个 灵 魂 不 死 ， 并 且 遮 盖 许 多 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30375', '60', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30376', '60', '1', '2', '就 是 照 父 神 的 先 见 被 拣 选 ， 藉 着 圣 灵 得 成 圣 洁 ， 以 致 顺 服 耶 稣 基 督 ， 又 蒙 他 血 所 洒 的 人 。 愿 恩 惠 、 平 安 多 多 地 加 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30377', '60', '1', '3', '＜ 活 的 盼 望 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30378', '60', '1', '4', '可 以 得 着 不 能 朽 坏 、 不 能 玷 污 、 不 能 衰 残 、 为 你 们 存 留 在 天 上 的 基 业 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30379', '60', '1', '5', '你 们 这 因 信 蒙 神 能 力 保 守 的 人 ， 必 能 得 着 所 预 备 、 到 末 世 要 显 现 的 救 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30380', '60', '1', '6', '因 此 ， 你 们 是 大 有 喜 乐 ； 但 如 今 ， 在 百 般 的 试 炼 中 暂 时 忧 愁 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30381', '60', '1', '7', '叫 你 们 的 信 心 既 被 试 验 ， 就 比 那 被 火 试 验 仍 然 能 坏 的 金 子 更 显 宝 贵 ， 可 以 在 耶 稣 基 督 显 现 的 时 候 得 著 称 赞 、 荣 耀 、 尊 贵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30382', '60', '1', '8', '你 们 虽 然 没 有 见 过 他 ， 却 是 爱 他 ； 如 今 虽 不 得 看 见 ， 却 因 信 他 就 有 说 不 出 来 、 满 有 荣 光 的 大 喜 乐 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30383', '60', '1', '9', '并 且 得 着 你 们 信 心 的 果 效 ， 就 是 灵 魂 的 救 恩 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30384', '60', '1', '10', '论 到 这 救 恩 ， 那 预 先 说 你 们 要 得 恩 典 的 众 先 知 早 已 详 细 地 寻 求 考 察 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30385', '60', '1', '11', '就 是 考 察 在 他 们 心 里 基 督 的 灵 ， 预 先 证 明 基 督 受 苦 难 ， 后 来 得 荣 耀 ， 是 指 着 什 么 时 候 ， 并 怎 样 的 时 候 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30386', '60', '1', '12', '他 们 得 了 启 示 ， 知 道 他 们 所 传 讲 ｛ 原 文 是 服 事 ｝ 的 一 切 事 ， 不 是 为 自 己 ， 乃 是 为 你 们 。 那 靠 着 从 天 上 差 来 的 圣 灵 传 福 音 给 你 们 的 人 ， 现 在 将 这 些 事 报 给 你 们 ； 天 使 也 愿 意 详 细 察 看 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30387', '60', '1', '13', '＜ 应 当 过 圣 洁 的 生 活 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30388', '60', '1', '14', '你 们 既 作 顺 命 的 儿 女 ， 就 不 要 效 法 从 前 蒙 昧 无 知 的 时 候 那 放 纵 私 欲 的 样 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30389', '60', '1', '15', '那 召 你 们 的 既 是 圣 洁 ， 你 们 在 一 切 所 行 的 事 上 也 要 圣 洁 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30390', '60', '1', '16', '因 为 经 上 记 着 说 ： “ 你 们 要 圣 洁 ， 因 为 我 是 圣 洁 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30391', '60', '1', '17', '你 们 既 称 那 不 偏 待 人 、 按 各 人 行 为 审 判 人 的 主 为 父 ， 就 当 存 敬 畏 的 心 度 你 们 在 世 寄 居 的 日 子 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30392', '60', '1', '18', '知 道 你 们 得 赎 ， 脱 去 你 们 祖 宗 所 传 流 虚 妄 的 行 为 ， 不 是 凭 着 能 坏 的 金 银 等 物 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30393', '60', '1', '19', '乃 是 凭 着 基 督 的 宝 血 ， 如 同 无 瑕 疵 、 无 玷 污 的 羔 羊 之 血 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30394', '60', '1', '20', '基 督 在 创 世 以 前 是 预 先 被 神 知 道 的 ， 却 在 这 末 世 才 为 你 们 显 现 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30395', '60', '1', '21', '你 们 也 因 着 他 ， 信 那 叫 他 从 死 里 复 活 、 又 给 他 荣 耀 的 神 ， 叫 你 们 的 信 心 和 盼 望 都 在 于 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30396', '60', '1', '22', '你 们 既 因 顺 从 真 理 ， 洁 净 了 自 己 的 心 ， 以 致 爱 弟 兄 没 有 虚 假 ， 就 当 从 心 里 ｛ 从 心 里 ： 有 古 卷 是 从 清 洁 的 心 ｝ 彼 此 切 实 相 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30397', '60', '1', '23', '你 们 蒙 了 重 生 ， 不 是 由 于 能 坏 的 种 子 ， 乃 是 由 于 不 能 坏 的 种 子 ， 是 藉 着 神 活 泼 常 存 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30398', '60', '1', '24', '因 为 凡 有 血 气 的 ， 尽 都 如 草 ； 他 的 美 荣 都 像 草 上 的 花 。 草 必 枯 干 ， 花 必 凋 谢 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30399', '60', '1', '25', '惟 有 主 的 道 是 永 存 的 。 所 传 给 你 们 的 福 音 就 是 这 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30400', '60', '2', '1', '＜ 活 石 和 圣 洁 的 国 度 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30401', '60', '2', '2', '就 要 爱 慕 那 纯 净 的 灵 奶 ， 像 才 生 的 婴 孩 爱 慕 奶 一 样 ， 叫 你 们 因 此 渐 长 ， 以 致 得 救 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30402', '60', '2', '3', '你 们 若 尝 过 主 恩 的 滋 味 ， 就 必 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30403', '60', '2', '4', '主 乃 活 石 ， 固 然 是 被 人 所 弃 的 ， 却 是 被 神 所 拣 选 、 所 宝 贵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30404', '60', '2', '5', '你 们 来 到 主 面 前 ， 也 就 像 活 石 ， 被 建 造 成 为 灵 宫 ， 作 圣 洁 的 祭 司 ， 藉 着 耶 稣 基 督 奉 献 神 所 悦 纳 的 灵 祭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30405', '60', '2', '6', '因 为 经 上 说 ： 看 哪 ， 我 把 所 拣 选 、 所 宝 贵 的 房 角 石 安 放 在 锡 安 ； 信 靠 他 的 人 必 不 至 于 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30406', '60', '2', '7', '所 以 ， 他 在 你 们 信 的 人 就 为 宝 贵 ， 在 那 不 信 的 人 有 话 说 ： 匠 人 所 弃 的 石 头 已 作 了 房 角 的 头 块 石 头 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30407', '60', '2', '8', '又 说 ： 作 了 绊 脚 的 石 头 ， 跌 人 的 磐 石 。 他 们 既 不 顺 从 ， 就 在 道 理 上 绊 跌 ｛ 或 译 ： 他 们 绊 跌 都 因 不 顺 从 道 理 ｝ ； 他 们 这 样 绊 跌 也 是 预 定 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30408', '60', '2', '9', '惟 有 你 们 是 被 拣 选 的 族 类 ， 是 有 君 尊 的 祭 司 ， 是 圣 洁 的 国 度 ， 是 属 神 的 子 民 ， 要 叫 你 们 宣 扬 那 召 你 们 出 黑 暗 入 奇 妙 光 明 者 的 美 德 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30409', '60', '2', '10', '你 们 从 前 算 不 得 子 民 ， 现 在 却 作 了 神 的 子 民 ； 从 前 未 曾 蒙 怜 恤 ， 现 在 却 蒙 了 怜 恤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30410', '60', '2', '11', '＜ 作 神 的 仆 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30411', '60', '2', '12', '你 们 在 外 邦 人 中 ， 应 当 品 行 端 正 ， 叫 那 些 毁 谤 你 们 是 作 恶 的 ， 因 看 见 你 们 的 好 行 为 ， 便 在 鉴 察 ｛ 或 译 ： 眷 顾 ｝ 的 日 子 归 荣 耀 给 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30412', '60', '2', '13', '你 们 为 主 的 缘 故 ， 要 顺 服 人 的 一 切 制 度 ， 或 是 在 上 的 君 王 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30413', '60', '2', '14', '或 是 君 王 所 派 罚 恶 赏 善 的 臣 宰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30414', '60', '2', '15', '因 为 神 的 旨 意 原 是 要 你 们 行 善 ， 可 以 堵 住 那 糊 涂 无 知 人 的 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30415', '60', '2', '16', '你 们 虽 是 自 由 的 ， 却 不 可 藉 着 自 由 遮 盖 恶 毒 ｛ 或 译 ： 阴 毒 ｝ ， 总 要 作 神 的 仆 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30416', '60', '2', '17', '务 要 尊 敬 众 人 ， 亲 爱 教 中 的 弟 兄 ， 敬 畏 神 ， 尊 敬 君 王 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30417', '60', '2', '18', '＜ 基 督 受 苦 的 榜 样 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30418', '60', '2', '19', '倘 若 人 为 叫 良 心 对 得 住 神 ， 就 忍 受 冤 屈 的 苦 楚 ， 这 是 可 喜 爱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30419', '60', '2', '20', '你 们 若 因 犯 罪 受 责 打 ， 能 忍 耐 ， 有 什 么 可 夸 的 呢 ？ 但 你 们 若 因 行 善 受 苦 ， 能 忍 耐 ， 这 在 神 看 是 可 喜 爱 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30420', '60', '2', '21', '你 们 蒙 召 原 是 为 此 ； 因 基 督 也 为 你 们 受 过 苦 ， 给 你 们 留 下 榜 样 ， 叫 你 们 跟 随 他 的 脚 踪 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30421', '60', '2', '22', '他 并 没 有 犯 罪 ， 口 里 也 没 有 诡 诈 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30422', '60', '2', '23', '他 被 骂 不 还 口 ； 受 害 不 说 威 吓 的 话 ， 只 将 自 己 交 托 那 按 公 义 审 判 人 的 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30423', '60', '2', '24', '他 被 挂 在 木 头 上 ， 亲 身 担 当 了 我 们 的 罪 ， 使 我 们 既 然 在 罪 上 死 ， 就 得 以 在 义 上 活 。 因 他 受 的 鞭 伤 ， 你 们 便 得 了 医 治 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30424', '60', '2', '25', '你 们 从 前 好 像 迷 路 的 羊 ， 如 今 却 归 到 你 们 灵 魂 的 牧 人 监 督 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30425', '60', '3', '1', '＜ 妻 子 和 丈 夫 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30426', '60', '3', '2', '这 正 是 因 看 见 你 们 有 贞 洁 的 品 行 和 敬 畏 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30427', '60', '3', '3', '你 们 不 要 以 外 面 的 辫 头 发 ， 戴 金 饰 ， 穿 美 衣 为 妆 饰 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30428', '60', '3', '4', '只 要 以 里 面 存 着 长 久 温 柔 、 安 静 的 心 为 妆 饰 ； 这 在 神 面 前 是 极 宝 贵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30429', '60', '3', '5', '因 为 古 时 仰 赖 神 的 圣 洁 妇 人 正 是 以 此 为 妆 饰 ， 顺 服 自 己 的 丈 夫 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30430', '60', '3', '6', '就 如 撒 拉 听 从 亚 伯 拉 罕 ， 称 他 为 主 。 你 们 若 行 善 ， 不 因 恐 吓 而 害 怕 ， 便 是 撒 拉 的 女 儿 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30431', '60', '3', '7', '你 们 作 丈 夫 的 也 要 按 情 理 ｛ 原 文 是 知 识 ｝ 和 妻 子 同 住 ； 因 她 比 你 软 弱 ｛ 比 你 软 弱 ： 原 文 作 是 软 弱 的 器 皿 ｝ ， 与 你 一 同 承 受 生 命 之 恩 的 ， 所 以 要 敬 重 她 。 这 样 ， 便 叫 你 们 的 祷 告 没 有 阻 碍 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30432', '60', '3', '8', '＜ 为 义 受 苦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30433', '60', '3', '9', '不 以 恶 报 恶 ， 以 辱 骂 还 辱 骂 ， 倒 要 祝 福 ； 因 你 们 是 为 此 蒙 召 ， 好 叫 你 们 承 受 福 气 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30434', '60', '3', '10', '因 为 经 上 说 ： 人 若 爱 生 命 ， 愿 享 美 福 ， 须 要 禁 止 舌 头 不 出 恶 言 ， 嘴 唇 不 说 诡 诈 的 话 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30435', '60', '3', '11', '也 要 离 恶 行 善 ， 寻 求 和 睦 ， 一 心 追 赶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30436', '60', '3', '12', '因 为 ， 主 的 眼 看 顾 义 人 ； 主 的 耳 听 他 们 的 祈 祷 。 惟 有 行 恶 的 人 ， 主 向 他 们 变 脸 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30437', '60', '3', '13', '你 们 若 是 热 心 行 善 ， 有 谁 害 你 们 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30438', '60', '3', '14', '你 们 就 是 为 义 受 苦 ， 也 是 有 福 的 。 不 要 怕 人 的 威 吓 ｛ 的 威 吓 ： 或 译 所 怕 的 ｝ ， 也 不 要 惊 慌 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30439', '60', '3', '15', '只 要 心 里 尊 主 基 督 为 圣 。 有 人 问 你 们 心 中 盼 望 的 缘 由 ， 就 要 常 作 准 备 ， 以 温 柔 、 敬 畏 的 心 回 答 各 人 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30440', '60', '3', '16', '存 着 无 亏 的 良 心 ， 叫 你 们 在 何 事 上 被 毁 谤 ， 就 在 何 事 上 可 以 叫 那 诬 赖 你 们 在 基 督 里 有 好 品 行 的 人 自 觉 羞 愧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30441', '60', '3', '17', '神 的 旨 意 若 是 叫 你 们 因 行 善 受 苦 ， 总 强 如 因 行 恶 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30442', '60', '3', '18', '因 基 督 也 曾 一 次 为 罪 受 苦 ｛ 有 古 卷 ： 受 死 ｝ ， 就 是 义 的 代 替 不 义 的 ， 为 要 引 我 们 到 神 面 前 。 按 着 肉 体 说 ， 他 被 治 死 ； 按 着 灵 性 说 ， 他 复 活 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30443', '60', '3', '19', '他 藉 这 灵 曾 去 传 道 给 那 些 在 监 狱 里 的 灵 听 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30444', '60', '3', '20', '就 是 那 从 前 在 挪 亚 预 备 方 舟 、 神 容 忍 等 待 的 时 候 ， 不 信 从 的 人 。 当 时 进 入 方 舟 ， 藉 着 水 得 救 的 不 多 ， 只 有 八 个 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30445', '60', '3', '21', '这 水 所 表 明 的 洗 礼 ， 现 在 藉 着 耶 稣 基 督 复 活 也 拯 救 你 们 ； 这 洗 礼 本 不 在 乎 除 掉 肉 体 的 污 秽 ， 只 求 在 神 面 前 有 无 亏 的 良 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30446', '60', '3', '22', '耶 稣 已 经 进 入 天 堂 ， 在 神 的 右 边 ； 众 天 使 和 有 权 柄 的 ， 并 有 能 力 的 ， 都 服 从 了 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30447', '60', '4', '1', '＜ 神 恩 赐 的 好 管 家 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30448', '60', '4', '2', '你 们 存 这 样 的 心 ， 从 今 以 后 就 可 以 不 从 人 的 情 欲 ， 只 从 神 的 旨 意 在 世 度 余 下 的 光 阴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30449', '60', '4', '3', '因 为 往 日 随 从 外 邦 人 的 心 意 行 邪 淫 、 恶 欲 、 醉 酒 、 荒 宴 、 群 饮 ， 并 可 恶 拜 偶 像 的 事 ， 时 候 已 经 够 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30450', '60', '4', '4', '他 们 在 这 些 事 上 ， 见 你 们 不 与 他 们 同 奔 那 放 荡 无 度 的 路 ， 就 以 为 怪 ， 毁 谤 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30451', '60', '4', '5', '他 们 必 在 那 将 要 审 判 活 人 死 人 的 主 面 前 交 帐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30452', '60', '4', '6', '为 此 ， 就 是 死 人 也 曾 有 福 音 传 给 他 们 ， 要 叫 他 们 的 肉 体 按 着 人 受 审 判 ， 他 们 的 灵 性 却 靠 神 活 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30453', '60', '4', '7', '万 物 的 结 局 近 了 。 所 以 ， 你 们 要 谨 慎 自 守 ， 警 醒 祷 告 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30454', '60', '4', '8', '最 要 紧 的 是 彼 此 切 实 相 爱 ， 因 为 爱 能 遮 掩 许 多 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30455', '60', '4', '9', '你 们 要 互 相 款 待 ， 不 发 怨 言 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30456', '60', '4', '10', '各 人 要 照 所 得 的 恩 赐 彼 此 服 事 ， 作 神 百 般 恩 赐 的 好 管 家 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30457', '60', '4', '11', '若 有 讲 道 的 ， 要 按 着 神 的 圣 言 讲 ； 若 有 服 事 人 的 ， 要 按 着 神 所 赐 的 力 量 服 事 ， 叫 神 在 凡 事 上 因 耶 稣 基 督 得 荣 耀 。 原 来 荣 耀 、 权 能 都 是 他 的 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30458', '60', '4', '12', '＜ 为 作 基 督 徒 受 苦 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30459', '60', '4', '13', '倒 要 欢 喜 ； 因 为 你 们 是 与 基 督 一 同 受 苦 ， 使 你 们 在 他 荣 耀 显 现 的 时 候 ， 也 可 以 欢 喜 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30460', '60', '4', '14', '你 们 若 为 基 督 的 名 受 辱 骂 ， 便 是 有 福 的 ； 因 为 神 荣 耀 的 灵 常 住 在 你 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30461', '60', '4', '15', '你 们 中 间 却 不 可 有 人 因 为 杀 人 、 偷 窃 、 作 恶 、 好 管 闲 事 而 受 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30462', '60', '4', '16', '若 为 作 基 督 徒 受 苦 ， 却 不 要 羞 耻 ， 倒 要 因 这 名 归 荣 耀 给 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30463', '60', '4', '17', '因 为 时 候 到 了 ， 审 判 要 从 神 的 家 起 首 。 若 是 先 从 我 们 起 首 ， 那 不 信 从 神 福 音 的 人 将 有 何 等 的 结 局 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30464', '60', '4', '18', '若 是 义 人 仅 仅 得 救 ， 那 不 虔 敬 和 犯 罪 的 人 将 有 何 地 可 站 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30465', '60', '4', '19', '所 以 ， 那 照 神 旨 意 受 苦 的 人 要 一 心 为 善 ， 将 自 己 灵 魂 交 与 那 信 实 的 造 化 之 主 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30466', '60', '5', '1', '＜ 照 管 神 的 羊 群 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30467', '60', '5', '2', '务 要 牧 养 在 你 们 中 间 神 的 群 羊 ， 按 着 神 旨 意 照 管 他 们 ； 不 是 出 于 勉 强 ， 乃 是 出 于 甘 心 ； 也 不 是 因 为 贪 财 ， 乃 是 出 于 乐 意 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30468', '60', '5', '3', '也 不 是 辖 制 所 托 付 你 们 的 ， 乃 是 作 群 羊 的 榜 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30469', '60', '5', '4', '到 了 牧 长 显 现 的 时 候 ， 你 们 必 得 那 永 不 衰 残 的 荣 耀 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30470', '60', '5', '5', '你 们 年 幼 的 ， 也 要 顺 服 年 长 的 。 就 是 你 们 众 人 也 都 要 以 谦 卑 束 腰 ， 彼 此 顺 服 ； 因 为 神 阻 挡 骄 傲 的 人 ， 赐 恩 给 谦 卑 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30471', '60', '5', '6', '所 以 ， 你 们 要 自 卑 ， 服 在 神 大 能 的 手 下 ， 到 了 时 候 ， 他 必 叫 你 们 升 高 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30472', '60', '5', '7', '你 们 要 将 一 切 的 忧 虑 卸 给 神 ， 因 为 他 顾 念 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30473', '60', '5', '8', '务 要 谨 守 ， 警 醒 。 因 为 你 们 的 仇 敌 魔 鬼 ， 如 同 吼 叫 的 狮 子 ， 遍 地 游 行 ， 寻 找 可 吞 吃 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30474', '60', '5', '9', '你 们 要 用 坚 固 的 信 心 抵 挡 他 ， 因 为 知 道 你 们 在 世 上 的 众 弟 兄 也 是 经 历 这 样 的 苦 难 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30475', '60', '5', '10', '那 赐 诸 般 恩 典 的 神 曾 在 基 督 里 召 你 们 ， 得 享 他 永 远 的 荣 耀 ， 等 你 们 暂 受 苦 难 之 后 ， 必 要 亲 自 成 全 你 们 ， 坚 固 你 们 ， 赐 力 量 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30476', '60', '5', '11', '愿 权 能 归 给 他 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30477', '60', '5', '12', '＜ 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30478', '60', '5', '13', '在 巴 比 伦 与 你 们 同 蒙 拣 选 的 教 会 问 你 们 安 。 我 儿 子 马 可 也 问 你 们 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30479', '60', '5', '14', '你 们 要 用 爱 心 彼 此 亲 嘴 问 安 。 愿 平 安 归 与 你 们 凡 在 基 督 里 的 人 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30480', '61', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30481', '61', '1', '2', '愿 恩 惠 、 平 安 ， 因 你 们 认 识 神 和 我 们 主 耶 稣 ， 多 多 地 加 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30482', '61', '1', '3', '＜ 信 徒 所 蒙 的 恩 召 和 拣 选 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30483', '61', '1', '4', '因 此 ， 他 已 将 又 宝 贵 又 极 大 的 应 许 赐 给 我 们 ， 叫 我 们 既 脱 离 世 上 从 情 欲 来 的 败 坏 ， 就 得 与 神 的 性 情 有 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30484', '61', '1', '5', '正 因 这 缘 故 ， 你 们 要 分 外 地 殷 勤 ； 有 了 信 心 ， 又 要 加 上 德 行 ； 有 了 德 行 ， 又 要 加 上 知 识 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30485', '61', '1', '6', '有 了 知 识 ， 又 要 加 上 节 制 ； 有 了 节 制 ， 又 要 加 上 忍 耐 ； 有 了 忍 耐 ， 又 要 加 上 虔 敬 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30486', '61', '1', '7', '有 了 虔 敬 ， 又 要 加 上 爱 弟 兄 的 心 ； 有 了 爱 弟 兄 的 心 ， 又 要 加 上 爱 众 人 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30487', '61', '1', '8', '你 们 若 充 充 足 足 地 有 这 几 样 ， 就 必 使 你 们 在 认 识 我 们 的 主 耶 稣 基 督 上 不 至 于 闲 懒 不 结 果 子 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30488', '61', '1', '9', '人 若 没 有 这 几 样 ， 就 是 眼 瞎 ， 只 看 见 近 处 的 ， 忘 了 他 旧 日 的 罪 已 经 得 了 洁 净 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30489', '61', '1', '10', '所 以 弟 兄 们 ， 应 当 更 加 殷 勤 ， 使 你 们 所 蒙 的 恩 召 和 拣 选 坚 定 不 移 。 你 们 若 行 这 几 样 ， 就 永 不 失 脚 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30490', '61', '1', '11', '这 样 ， 必 叫 你 们 丰 丰 富 富 地 得 以 进 入 我 们 主 ─ ─ 救 主 耶 稣 基 督 永 远 的 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30491', '61', '1', '12', '你 们 虽 然 晓 得 这 些 事 ， 并 且 在 你 们 已 有 的 真 道 上 坚 固 ， 我 却 要 将 这 些 事 常 常 提 醒 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30492', '61', '1', '13', '我 以 为 应 当 趁 我 还 在 这 帐 棚 的 时 候 提 醒 你 们 ， 激 发 你 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30493', '61', '1', '14', '因 为 知 道 我 脱 离 这 帐 棚 的 时 候 快 到 了 ， 正 如 我 们 主 耶 稣 基 督 所 指 示 我 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30494', '61', '1', '15', '并 且 ， 我 要 尽 心 竭 力 ， 使 你 们 在 我 去 世 以 后 时 常 记 念 这 些 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30495', '61', '1', '16', '＜ 基 督 的 荣 耀 和 先 知 的 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30496', '61', '1', '17', '他 从 父 神 得 尊 贵 荣 耀 的 时 候 ， 从 极 大 荣 光 之 中 有 声 音 出 来 ， 向 他 说 ： “ 这 是 我 的 爱 子 ， 我 所 喜 悦 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30497', '61', '1', '18', '我 们 同 他 在 圣 山 的 时 候 ， 亲 自 听 见 这 声 音 从 天 上 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30498', '61', '1', '19', '我 们 并 有 先 知 更 确 的 预 言 ， 如 同 灯 照 在 暗 处 。 你 们 在 这 预 言 上 留 意 ， 直 等 到 天 发 亮 ， 晨 星 在 你 们 心 里 出 现 的 时 候 ， 才 是 好 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30499', '61', '1', '20', '第 一 要 紧 的 ， 该 知 道 经 上 所 有 的 预 言 没 有 可 随 私 意 解 说 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30500', '61', '1', '21', '因 为 预 言 从 来 没 有 出 于 人 意 的 ， 乃 是 人 被 圣 灵 感 动 ， 说 出 神 的 话 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30501', '61', '2', '1', '＜ 假 先 知 和 假 师 傅 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30502', '61', '2', '2', '将 有 许 多 人 随 从 他 们 邪 淫 的 行 为 ， 便 叫 真 道 因 他 们 的 缘 故 被 毁 谤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30503', '61', '2', '3', '他 们 因 有 贪 心 ， 要 用 捏 造 的 言 语 在 你 们 身 上 取 利 。 他 们 的 刑 罚 ， 自 古 以 来 并 不 迟 延 ； 他 们 的 灭 亡 也 必 速 速 来 到 ｛ 原 文 是 也 不 打 盹 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30504', '61', '2', '4', '就 是 天 使 犯 了 罪 ， 神 也 没 有 宽 容 ， 曾 把 他 们 丢 在 地 狱 ， 交 在 黑 暗 坑 中 ， 等 候 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30505', '61', '2', '5', '神 也 没 有 宽 容 上 古 的 世 代 ， 曾 叫 洪 水 临 到 那 不 敬 虔 的 世 代 ， 却 保 护 了 传 义 道 的 挪 亚 一 家 八 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30506', '61', '2', '6', '又 判 定 所 多 玛 、 蛾 摩 拉 ， 将 二 城 倾 覆 ， 焚 烧 成 灰 ， 作 为 后 世 不 敬 虔 人 的 鉴 戒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30507', '61', '2', '7', '只 搭 救 了 那 常 为 恶 人 淫 行 忧 伤 的 义 人 罗 得 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30508', '61', '2', '8', '（ 因 为 那 义 人 住 在 他 们 中 间 ， 看 见 听 见 他 们 不 法 的 事 ， 他 的 义 心 就 天 天 伤 痛 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30509', '61', '2', '9', '主 知 道 搭 救 敬 虔 的 人 脱 离 试 探 ， 把 不 义 的 人 留 在 刑 罚 之 下 ， 等 候 审 判 的 日 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30510', '61', '2', '10', '那 些 随 肉 身 、 纵 污 秽 的 情 欲 、 轻 慢 主 治 之 人 的 ， 更 是 如 此 。 他 们 胆 大 任 性 ， 毁 谤 在 尊 位 的 ， 也 不 知 惧 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30511', '61', '2', '11', '就 是 天 使 ， 虽 然 力 量 权 能 更 大 ， 还 不 用 毁 谤 的 话 在 主 面 前 告 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30512', '61', '2', '12', '但 这 些 人 好 像 没 有 灵 性 ， 生 来 就 是 畜 类 ， 以 备 捉 拿 宰 杀 的 。 他 们 毁 谤 所 不 晓 得 的 事 ， 正 在 败 坏 人 的 时 候 ， 自 己 必 遭 遇 败 坏 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30513', '61', '2', '13', '行 的 不 义 ， 就 得 了 不 义 的 工 价 。 这 些 人 喜 爱 白 昼 宴 乐 ， 他 们 已 被 玷 污 ， 又 有 瑕 疵 ， 正 与 你 们 一 同 坐 席 ， 就 以 自 己 的 诡 诈 为 快 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30514', '61', '2', '14', '他 们 满 眼 是 淫 色 ｛ 原 文 是 淫 妇 ｝ ， 止 不 住 犯 罪 ， 引 诱 那 心 不 坚 固 的 人 ， 心 中 习 惯 了 贪 婪 ， 正 是 被 咒 诅 的 种 类 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30515', '61', '2', '15', '他 们 离 弃 正 路 ， 就 走 差 了 ， 随 从 比 珥 之 子 巴 兰 的 路 。 巴 兰 就 是 那 贪 爱 不 义 之 工 价 的 先 知 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30516', '61', '2', '16', '他 却 为 自 己 的 过 犯 受 了 责 备 ； 那 不 能 说 话 的 驴 以 人 言 拦 阻 先 知 的 狂 妄 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30517', '61', '2', '17', '这 些 人 是 无 水 的 井 ， 是 狂 风 催 逼 的 雾 气 ， 有 墨 黑 的 幽 暗 为 他 们 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30518', '61', '2', '18', '他 们 说 虚 妄 矜 夸 的 大 话 ， 用 肉 身 的 情 欲 和 邪 淫 的 事 引 诱 那 些 刚 才 脱 离 妄 行 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30519', '61', '2', '19', '他 们 应 许 人 得 以 自 由 ， 自 己 却 作 败 坏 的 奴 仆 ， 因 为 人 被 谁 制 伏 就 是 谁 的 奴 仆 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30520', '61', '2', '20', '倘 若 他 们 因 认 识 主 ─ ─ 救 主 耶 稣 基 督 ， 得 以 脱 离 世 上 的 污 秽 ， 后 来 又 在 其 中 被 缠 住 、 制 伏 ， 他 们 末 后 的 景 况 就 比 先 前 更 不 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30521', '61', '2', '21', '他 们 晓 得 义 路 ， 竟 背 弃 了 传 给 他 们 的 圣 命 ， 倒 不 如 不 晓 得 为 妙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30522', '61', '2', '22', '俗 语 说 得 真 不 错 ： 狗 所 吐 的 ， 它 转 过 来 又 吃 ； 猪 洗 净 了 又 回 到 泥 里 去 滚 ； 这 话 在 他 们 身 上 正 合 式 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30523', '61', '3', '1', '＜ 主 再 来 的 应 许 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30524', '61', '3', '2', '叫 你 们 记 念 圣 先 知 预 先 所 说 的 话 和 主 救 主 的 命 令 ， 就 是 使 徒 所 传 给 你 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30525', '61', '3', '3', '第 一 要 紧 的 ， 该 知 道 在 末 世 必 有 好 讥 诮 的 人 随 从 自 己 的 私 欲 出 来 讥 诮 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30526', '61', '3', '4', '“ 主 要 降 临 的 应 许 在 哪 里 呢 ？ 因 为 从 列 祖 睡 了 以 来 ， 万 物 与 起 初 创 造 的 时 候 仍 是 一 样 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30527', '61', '3', '5', '他 们 故 意 忘 记 ， 从 太 古 ， 凭 神 的 命 有 了 天 ， 并 从 水 而 出 、 藉 水 而 成 的 地 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30528', '61', '3', '6', '故 此 ， 当 时 的 世 界 被 水 淹 没 就 消 灭 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30529', '61', '3', '7', '但 现 在 的 天 地 还 是 凭 着 那 命 存 留 ， 直 留 到 不 敬 虔 之 人 受 审 判 遭 沉 沦 的 日 子 ， 用 火 焚 烧 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30530', '61', '3', '8', '亲 爱 的 弟 兄 啊 ， 有 一 件 事 你 们 不 可 忘 记 ， 就 是 主 看 一 日 如 千 年 ， 千 年 如 一 日 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30531', '61', '3', '9', '主 所 应 许 的 尚 未 成 就 ， 有 人 以 为 他 是 耽 延 ， 其 实 不 是 耽 延 ， 乃 是 宽 容 你 们 ， 不 愿 有 一 人 沉 沦 ， 乃 愿 人 人 都 悔 改 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30532', '61', '3', '10', '但 主 的 日 子 要 像 贼 来 到 一 样 。 那 日 ， 天 必 大 有 响 声 废 去 ， 有 形 质 的 都 要 被 烈 火 销 化 ， 地 和 其 上 的 物 都 要 烧 尽 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30533', '61', '3', '11', '这 一 切 既 然 都 要 如 此 销 化 ， 你 们 为 人 该 当 怎 样 圣 洁 ， 怎 样 敬 虔 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30534', '61', '3', '12', '切 切 仰 望 神 的 日 子 来 到 。 在 那 日 ， 天 被 火 烧 就 销 化 了 ， 有 形 质 的 都 要 被 烈 火 镕 化 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30535', '61', '3', '13', '但 我 们 照 他 的 应 许 ， 盼 望 新 天 新 地 ， 有 义 居 在 其 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30536', '61', '3', '14', '亲 爱 的 弟 兄 啊 ， 你 们 既 盼 望 这 些 事 ， 就 当 殷 勤 ， 使 自 己 没 有 玷 污 ， 无 可 指 摘 ， 安 然 见 主 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30537', '61', '3', '15', '并 且 要 以 我 主 长 久 忍 耐 为 得 救 的 因 由 ， 就 如 我 们 所 亲 爱 的 兄 弟 保 罗 ， 照 着 所 赐 给 他 的 智 慧 写 了 信 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30538', '61', '3', '16', '他 一 切 的 信 上 也 都 是 讲 论 这 事 。 信 中 有 些 难 明 白 的 ， 那 无 学 问 、 不 坚 固 的 人 强 解 ， 如 强 解 别 的 经 书 一 样 ， 就 自 取 沉 沦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30539', '61', '3', '17', '亲 爱 的 弟 兄 啊 ， 你 们 既 然 预 先 知 道 这 事 ， 就 当 防 备 ， 恐 怕 被 恶 人 的 错 谬 诱 惑 ， 就 从 自 己 坚 固 的 地 步 上 坠 落 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30540', '61', '3', '18', '你 们 却 要 在 我 们 主 ─ ─ 救 主 耶 稣 基 督 的 恩 典 和 知 识 上 有 长 进 。 愿 荣 耀 归 给 他 ， 从 今 直 到 永 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30541', '62', '1', '1', '＜ 生 命 之 道 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30542', '62', '1', '2', '（ 这 生 命 已 经 显 现 出 来 ， 我 们 也 看 见 过 ， 现 在 又 作 见 证 ， 将 原 与 父 同 在 、 且 显 现 与 我 们 那 永 远 的 生 命 传 给 你 们 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30543', '62', '1', '3', '我 们 将 所 看 见 、 所 听 见 的 传 给 你 们 ， 使 你 们 与 我 们 相 交 。 我 们 乃 是 与 父 并 他 儿 子 耶 稣 基 督 相 交 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30544', '62', '1', '4', '我 们 将 这 些 话 写 给 你 们 ， 使 你 们 ｛ 有 古 卷 ： 我 们 ｝ 的 喜 乐 充 足 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30545', '62', '1', '5', '＜ 神 就 是 光 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30546', '62', '1', '6', '我 们 若 说 是 与 神 相 交 ， 却 仍 在 黑 暗 里 行 ， 就 是 说 谎 话 ， 不 行 真 理 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30547', '62', '1', '7', '我 们 若 在 光 明 中 行 ， 如 同 神 在 光 明 中 ， 就 彼 此 相 交 ， 他 儿 子 耶 稣 的 血 也 洗 净 我 们 一 切 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30548', '62', '1', '8', '我 们 若 说 自 己 无 罪 ， 便 是 自 欺 ， 真 理 不 在 我 们 心 里 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30549', '62', '1', '9', '我 们 若 认 自 己 的 罪 ， 神 是 信 实 的 ， 是 公 义 的 ， 必 要 赦 免 我 们 的 罪 ， 洗 净 我 们 一 切 的 不 义 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30550', '62', '1', '10', '我 们 若 说 自 己 没 有 犯 过 罪 ， 便 是 以 神 为 说 谎 的 ， 他 的 道 也 不 在 我 们 心 里 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30551', '62', '2', '1', '＜ 我 们 的 中 保 基 督 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30552', '62', '2', '2', '他 为 我 们 的 罪 作 了 挽 回 祭 ， 不 是 单 为 我 们 的 罪 ， 也 是 为 普 天 下 人 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30553', '62', '2', '3', '我 们 若 遵 守 他 的 诫 命 ， 就 晓 得 是 认 识 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30554', '62', '2', '4', '人 若 说 “ 我 认 识 他 ” ， 却 不 遵 守 他 的 诫 命 ， 便 是 说 谎 话 的 ， 真 理 也 不 在 他 心 里 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30555', '62', '2', '5', '凡 遵 守 主 道 的 ， 爱 神 的 心 在 他 里 面 实 在 是 完 全 的 。 从 此 ， 我 们 知 道 我 们 是 在 主 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30556', '62', '2', '6', '人 若 说 他 住 在 主 里 面 ， 就 该 自 己 照 主 所 行 的 去 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30557', '62', '2', '7', '＜ 新 命 令 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30558', '62', '2', '8', '再 者 ， 我 写 给 你 们 的 ， 是 一 条 新 命 令 ， 在 主 是 真 的 ， 在 你 们 也 是 真 的 ； 因 为 黑 暗 渐 渐 过 去 ， 真 光 已 经 照 耀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30559', '62', '2', '9', '人 若 说 自 己 在 光 明 中 ， 却 恨 他 的 弟 兄 ， 他 到 如 今 还 是 在 黑 暗 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30560', '62', '2', '10', '爱 弟 兄 的 ， 就 是 住 在 光 明 中 ， 在 他 并 没 有 绊 跌 的 缘 由 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30561', '62', '2', '11', '惟 独 恨 弟 兄 的 ， 是 在 黑 暗 里 ， 且 在 黑 暗 里 行 ， 也 不 知 道 往 哪 里 去 ， 因 为 黑 暗 叫 他 眼 睛 瞎 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30562', '62', '2', '12', '小 子 们 哪 ， 我 写 信 给 你 们 ， 因 为 你 们 的 罪 藉 着 主 名 得 了 赦 免 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30563', '62', '2', '13', '父 老 啊 ， 我 写 信 给 你 们 ， 因 为 你 们 认 识 那 从 起 初 原 有 的 。 少 年 人 哪 ， 我 写 信 给 你 们 ， 因 为 你 们 胜 了 那 恶 者 。 小 子 们 哪 ， 我 曾 写 信 给 你 们 ， 因 为 你 们 认 识 父 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30564', '62', '2', '14', '父 老 啊 ， 我 曾 写 信 给 你 们 ， 因 为 你 们 认 识 那 从 起 初 原 有 的 。 少 年 人 哪 ， 我 曾 写 信 给 你 们 ； 因 为 你 们 刚 强 ， 神 的 道 常 存 在 你 们 心 里 ； 你 们 也 胜 了 那 恶 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30565', '62', '2', '15', '不 要 爱 世 界 和 世 界 上 的 事 。 人 若 爱 世 界 ， 爱 父 的 心 就 不 在 他 里 面 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30566', '62', '2', '16', '因 为 ， 凡 世 界 上 的 事 ， 就 像 肉 体 的 情 欲 、 眼 目 的 情 欲 ， 并 今 生 的 骄 傲 ， 都 不 是 从 父 来 的 ， 乃 是 从 世 界 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30567', '62', '2', '17', '这 世 界 和 其 上 的 情 欲 都 要 过 去 ， 惟 独 遵 行 神 旨 意 的 ， 是 永 远 常 存 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30568', '62', '2', '18', '＜ 敌 基 督 者 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30569', '62', '2', '19', '他 们 从 我 们 中 间 出 去 ， 却 不 是 属 我 们 的 ； 若 是 属 我 们 的 ， 就 必 仍 旧 与 我 们 同 在 ； 他 们 出 去 ， 显 明 都 不 是 属 我 们 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30570', '62', '2', '20', '你 们 从 那 圣 者 受 了 恩 膏 ， 并 且 知 道 这 一 切 的 事 ｛ 或 译 ： 都 有 知 识 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30571', '62', '2', '21', '我 写 信 给 你 们 ， 不 是 因 你 们 不 知 道 真 理 ， 正 是 因 你 们 知 道 ， 并 且 知 道 没 有 虚 谎 是 从 真 理 出 来 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30572', '62', '2', '22', '谁 是 说 谎 话 的 呢 ？ 不 是 那 不 认 耶 稣 为 基 督 的 吗 ？ 不 认 父 与 子 的 ， 这 就 是 敌 基 督 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30573', '62', '2', '23', '凡 不 认 子 的 ， 就 没 有 父 ； 认 子 的 ， 连 父 也 有 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30574', '62', '2', '24', '论 到 你 们 ， 务 要 将 那 从 起 初 所 听 见 的 ， 常 存 在 心 里 。 若 将 从 起 初 所 听 见 的 存 在 心 里 ， 你 们 就 必 住 在 子 里 面 ， 也 必 住 在 父 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30575', '62', '2', '25', '主 所 应 许 我 们 的 就 是 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30576', '62', '2', '26', '我 将 这 些 话 写 给 你 们 ， 是 指 着 那 引 诱 你 们 的 人 说 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30577', '62', '2', '27', '你 们 从 主 所 受 的 恩 膏 常 存 在 你 们 心 里 ， 并 不 用 人 教 训 你 们 ， 自 有 主 的 恩 膏 在 凡 事 上 教 训 你 们 。 这 恩 膏 是 真 的 ， 不 是 假 的 ； 你 们 要 按 这 恩 膏 的 教 训 住 在 主 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30578', '62', '2', '28', '＜ 神 的 儿 女 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30579', '62', '2', '29', '你 们 若 知 道 他 是 公 义 的 ， 就 知 道 凡 行 公 义 之 人 都 是 他 所 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30580', '62', '3', '1', '你 看 父 赐 给 我 们 是 何 等 的 慈 爱 ， 使 我 们 得 称 为 神 的 儿 女 ； 我 们 也 真 是 他 的 儿 女 。 世 人 所 以 不 认 识 我 们 ， 是 因 未 曾 认 识 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30581', '62', '3', '2', '亲 爱 的 弟 兄 啊 ， 我 们 现 在 是 神 的 儿 女 ， 将 来 如 何 ， 还 未 显 明 ； 但 我 们 知 道 ， 主 若 显 现 ， 我 们 必 要 像 他 ， 因 为 必 得 见 他 的 真 体 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30582', '62', '3', '3', '凡 向 他 有 这 指 望 的 ， 就 洁 净 自 己 ， 像 他 洁 净 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30583', '62', '3', '4', '凡 犯 罪 的 ， 就 是 违 背 律 法 ； 违 背 律 法 就 是 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30584', '62', '3', '5', '你 们 知 道 主 曾 显 现 ， 是 要 除 掉 人 的 罪 ， 在 他 并 没 有 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30585', '62', '3', '6', '凡 住 在 他 里 面 的 ， 就 不 犯 罪 ； 凡 犯 罪 的 ， 是 未 曾 看 见 他 ， 也 未 曾 认 识 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30586', '62', '3', '7', '小 子 们 哪 ， 不 要 被 人 诱 惑 。 行 义 的 才 是 义 人 ， 正 如 主 是 义 的 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30587', '62', '3', '8', '犯 罪 的 是 属 魔 鬼 ， 因 为 魔 鬼 从 起 初 就 犯 罪 。 神 的 儿 子 显 现 出 来 ， 为 要 除 灭 魔 鬼 的 作 为 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30588', '62', '3', '9', '凡 从 神 生 的 ， 就 不 犯 罪 ， 因 神 的 道 ｛ 原 文 是 种 ｝ 存 在 他 心 里 ； 他 也 不 能 犯 罪 ， 因 为 他 是 由 神 生 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30589', '62', '3', '10', '从 此 就 显 出 谁 是 神 的 儿 女 ， 谁 是 魔 鬼 的 儿 女 。 凡 不 行 义 的 就 不 属 神 ， 不 爱 弟 兄 的 也 是 如 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30590', '62', '3', '11', '＜ 彼 此 相 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30591', '62', '3', '12', '不 可 像 该 隐 ； 他 是 属 那 恶 者 ， 杀 了 他 的 兄 弟 。 为 什 么 杀 了 他 呢 ？ 因 自 己 的 行 为 是 恶 的 ， 兄 弟 的 行 为 是 善 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30592', '62', '3', '13', '弟 兄 们 ， 世 人 若 恨 你 们 ， 不 要 以 为 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30593', '62', '3', '14', '我 们 因 为 爱 弟 兄 ， 就 晓 得 是 已 经 出 死 入 生 了 。 没 有 爱 心 的 ， 仍 住 在 死 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30594', '62', '3', '15', '凡 恨 他 弟 兄 的 ， 就 是 杀 人 的 ； 你 们 晓 得 凡 杀 人 的 ， 没 有 永 生 存 在 他 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30595', '62', '3', '16', '主 为 我 们 舍 命 ， 我 们 从 此 就 知 道 何 为 爱 ； 我 们 也 当 为 弟 兄 舍 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30596', '62', '3', '17', '凡 有 世 上 财 物 的 ， 看 见 弟 兄 穷 乏 ， 却 塞 住 怜 恤 的 心 ， 爱 神 的 心 怎 能 存 在 他 里 面 呢 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30597', '62', '3', '18', '小 子 们 哪 ， 我 们 相 爱 ， 不 要 只 在 言 语 和 舌 头 上 ， 总 要 在 行 为 和 诚 实 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30598', '62', '3', '19', '＜ 在 神 面 前 安 稳 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30599', '62', '3', '20', '我 们 的 心 若 责 备 我 们 ， 神 比 我 们 的 心 大 ， 一 切 事 没 有 不 知 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30600', '62', '3', '21', '亲 爱 的 弟 兄 啊 ， 我 们 的 心 若 不 责 备 我 们 ， 就 可 以 向 神 坦 然 无 惧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30601', '62', '3', '22', '并 且 我 们 一 切 所 求 的 ， 就 从 他 得 着 ； 因 为 我 们 遵 守 他 的 命 令 ， 行 他 所 喜 悦 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30602', '62', '3', '23', '神 的 命 令 就 是 叫 我 们 信 他 儿 子 耶 稣 基 督 的 名 ， 且 照 他 所 赐 给 我 们 的 命 令 彼 此 相 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30603', '62', '3', '24', '遵 守 神 命 令 的 ， 就 住 在 神 里 面 ， 神 也 住 在 他 里 面 。 我 们 所 以 知 道 神 住 在 我 们 里 面 是 因 他 所 赐 给 我 们 的 圣 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30604', '62', '4', '1', '＜ 神 的 灵 和 敌 基 督 者 的 灵 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30605', '62', '4', '2', '凡 灵 认 耶 稣 基 督 是 成 了 肉 身 来 的 ， 就 是 出 于 神 的 ； 从 此 你 们 可 以 认 出 神 的 灵 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30606', '62', '4', '3', '凡 灵 不 认 耶 稣 ， 就 不 是 出 于 神 ， 这 是 那 敌 基 督 者 的 灵 。 你 们 从 前 听 见 他 要 来 ， 现 在 已 经 在 世 上 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30607', '62', '4', '4', '小 子 们 哪 ， 你 们 是 属 神 的 ， 并 且 胜 了 他 们 ； 因 为 那 在 你 们 里 面 的 ， 比 那 在 世 界 上 的 更 大 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30608', '62', '4', '5', '他 们 是 属 世 界 的 ， 所 以 论 世 界 的 事 ， 世 人 也 听 从 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30609', '62', '4', '6', '我 们 是 属 神 的 ， 认 识 神 的 就 听 从 我 们 ； 不 属 神 的 就 不 听 从 我 们 。 从 此 我 们 可 以 认 出 真 理 的 灵 和 谬 妄 的 灵 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30610', '62', '4', '7', '＜ 神 就 是 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30611', '62', '4', '8', '没 有 爱 心 的 ， 就 不 认 识 神 ， 因 为 神 就 是 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30612', '62', '4', '9', '神 差 他 独 生 子 到 世 间 来 ， 使 我 们 藉 着 他 得 生 ， 神 爱 我 们 的 心 在 此 就 显 明 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30613', '62', '4', '10', '不 是 我 们 爱 神 ， 乃 是 神 爱 我 们 ， 差 他 的 儿 子 为 我 们 的 罪 作 了 挽 回 祭 ， 这 就 是 爱 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30614', '62', '4', '11', '亲 爱 的 弟 兄 啊 ， 神 既 是 这 样 爱 我 们 ， 我 们 也 当 彼 此 相 爱 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30615', '62', '4', '12', '从 来 没 有 人 见 过 神 ， 我 们 若 彼 此 相 爱 ， 神 就 住 在 我 们 里 面 ， 爱 他 的 心 在 我 们 里 面 得 以 完 全 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30616', '62', '4', '13', '神 将 他 的 灵 赐 给 我 们 ， 从 此 就 知 道 我 们 是 住 在 他 里 面 ， 他 也 住 在 我 们 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30617', '62', '4', '14', '父 差 子 作 世 人 的 救 主 ； 这 是 我 们 所 看 见 且 作 见 证 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30618', '62', '4', '15', '凡 认 耶 稣 为 神 儿 子 的 ， 神 就 住 在 他 里 面 ， 他 也 住 在 神 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30619', '62', '4', '16', '神 爱 我 们 的 心 ， 我 们 也 知 道 也 信 。 神 就 是 爱 ； 住 在 爱 里 面 的 ， 就 是 住 在 神 里 面 ， 神 也 住 在 他 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30620', '62', '4', '17', '这 样 ， 爱 在 我 们 里 面 得 以 完 全 ， 我 们 就 可 以 在 审 判 的 日 子 坦 然 无 惧 。 因 为 他 如 何 ， 我 们 在 这 世 上 也 如 何 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30621', '62', '4', '18', '爱 里 没 有 惧 怕 ； 爱 既 完 全 ， 就 把 惧 怕 除 去 。 因 为 惧 怕 里 含 着 刑 罚 ， 惧 怕 的 人 在 爱 里 未 得 完 全 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30622', '62', '4', '19', '我 们 爱 ， 因 为 神 先 爱 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30623', '62', '4', '20', '人 若 说 “ 我 爱 神 ” ， 却 恨 他 的 弟 兄 ， 就 是 说 谎 话 的 ； 不 爱 他 所 看 见 的 弟 兄 ， 就 不 能 爱 没 有 看 见 的 神 ｛ 有 古 卷 ： 怎 能 爱 没 有 看 见 的 神 呢 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30624', '62', '4', '21', '爱 神 的 ， 也 当 爱 弟 兄 ， 这 是 我 们 从 神 所 受 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30625', '62', '5', '1', '＜ 胜 了 世 界 的 就 是 信 心 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30626', '62', '5', '2', '我 们 若 爱 神 ， 又 遵 守 他 的 诫 命 ， 从 此 就 知 道 我 们 爱 神 的 儿 女 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30627', '62', '5', '3', '我 们 遵 守 神 的 诫 命 ， 这 就 是 爱 他 了 ， 并 且 他 的 诫 命 不 是 难 守 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30628', '62', '5', '4', '因 为 凡 从 神 生 的 ， 就 胜 过 世 界 ； 使 我 们 胜 了 世 界 的 ， 就 是 我 们 的 信 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30629', '62', '5', '5', '胜 过 世 界 的 是 谁 呢 ？ 不 是 那 信 耶 稣 是 神 儿 子 的 吗 ？');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30630', '62', '5', '6', '＜ 神 为 祂 儿 子 作 的 见 证 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30631', '62', '5', '7', '并 且 有 圣 灵 作 见 证 ， 因 为 圣 灵 就 是 真 理 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30632', '62', '5', '8', '作 见 证 的 原 来 有 三 ： 就 是 圣 灵 、 水 ， 与 血 ， 这 三 样 也 都 归 于 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30633', '62', '5', '9', '我 们 既 领 受 人 的 见 证 ， 神 的 见 证 更 该 领 受 ｛ 该 领 受 ： 原 文 是 大 ｝ 了 ， 因 神 的 见 证 是 为 他 儿 子 作 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30634', '62', '5', '10', '信 神 儿 子 的 ， 就 有 这 见 证 在 他 心 里 ； 不 信 神 的 ， 就 是 将 神 当 作 说 谎 的 ， 因 不 信 神 为 他 儿 子 作 的 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30635', '62', '5', '11', '这 见 证 就 是 神 赐 给 我 们 永 生 ； 这 永 生 也 是 在 他 儿 子 里 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30636', '62', '5', '12', '人 有 了 神 的 儿 子 就 有 生 命 ， 没 有 神 的 儿 子 就 没 有 生 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30637', '62', '5', '13', '＜ 知 道 自 己 有 永 生 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30638', '62', '5', '14', '我 们 若 照 他 的 旨 意 求 什 么 ， 他 就 听 我 们 ， 这 是 我 们 向 他 所 存 坦 然 无 惧 的 心 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30639', '62', '5', '15', '既 然 知 道 他 听 我 们 一 切 所 求 的 ， 就 知 道 我 们 所 求 于 他 的 ， 无 不 得 着 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30640', '62', '5', '16', '人 若 看 见 弟 兄 犯 了 不 至 于 死 的 罪 ， 就 当 为 他 祈 求 ， 神 必 将 生 命 赐 给 他 ； 有 至 于 死 的 罪 ， 我 不 说 当 为 这 罪 祈 求 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30641', '62', '5', '17', '凡 不 义 的 事 都 是 罪 ， 也 有 不 至 于 死 的 罪 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30642', '62', '5', '18', '我 们 知 道 凡 从 神 生 的 ， 必 不 犯 罪 ， 从 神 生 的 ， 必 保 守 自 己 ｛ 有 古 卷 ： 那 从 神 生 的 必 保 护 他 ｝ ， 那 恶 者 也 就 无 法 害 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30643', '62', '5', '19', '我 们 知 道 ， 我 们 是 属 神 的 ， 全 世 界 都 卧 在 那 恶 者 手 下 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30644', '62', '5', '20', '我 们 也 知 道 ， 神 的 儿 子 已 经 来 到 ， 且 将 智 慧 赐 给 我 们 ， 使 我 们 认 识 那 位 真 实 的 ， 我 们 也 在 那 位 真 实 的 里 面 ， 就 是 在 他 儿 子 耶 稣 基 督 里 面 。 这 是 真 神 ， 也 是 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30645', '62', '5', '21', '小 子 们 哪 ， 你 们 要 自 守 ， 远 避 偶 像 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30646', '63', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30647', '63', '1', '2', '爱 你 们 是 为 真 理 的 缘 故 ， 这 真 理 存 在 我 们 里 面 ， 也 必 永 远 与 我 们 同 在 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30648', '63', '1', '3', '恩 惠 、 怜 悯 、 平 安 从 父 神 和 他 儿 子 耶 稣 基 督 在 真 理 和 爱 心 上 必 常 与 我 们 同 在 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30649', '63', '1', '4', '＜ 真 理 和 爱 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30650', '63', '1', '5', '太 太 啊 ， 我 现 在 劝 你 ， 我 们 大 家 要 彼 此 相 爱 。 这 并 不 是 我 写 一 条 新 命 令 给 你 ， 乃 是 我 们 从 起 初 所 受 的 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30651', '63', '1', '6', '我 们 若 照 他 的 命 令 行 ， 这 就 是 爱 。 你 们 从 起 初 所 听 见 当 行 的 ， 就 是 这 命 令 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30652', '63', '1', '7', '因 为 世 上 有 许 多 迷 惑 人 的 出 来 ， 他 们 不 认 耶 稣 基 督 是 成 了 肉 身 来 的 ； 这 就 是 那 迷 惑 人 、 敌 基 督 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30653', '63', '1', '8', '你 们 要 小 心 ， 不 要 失 去 你 们 ｛ 有 古 卷 ： 我 们 ｝ 所 做 的 工 ， 乃 要 得 着 满 足 的 赏 赐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30654', '63', '1', '9', '凡 越 过 基 督 的 教 训 不 常 守 着 的 ， 就 没 有 神 ； 常 守 这 教 训 的 ， 就 有 父 又 有 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30655', '63', '1', '10', '若 有 人 到 你 们 那 里 ， 不 是 传 这 教 训 ， 不 要 接 他 到 家 里 ， 也 不 要 问 他 的 安 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30656', '63', '1', '11', '因 为 问 他 安 的 ， 就 在 他 的 恶 行 上 有 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30657', '63', '1', '12', '＜ 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30658', '63', '1', '13', '你 那 蒙 拣 选 之 姊 妹 的 儿 女 都 问 你 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30659', '64', '1', '1', '＜ 问 候 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30660', '64', '1', '2', '亲 爱 的 兄 弟 啊 ， 我 愿 你 凡 事 兴 盛 ， 身 体 健 壮 ， 正 如 你 的 灵 魂 兴 盛 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30661', '64', '1', '3', '有 弟 兄 来 证 明 你 心 里 存 的 真 理 ， 正 如 你 按 真 理 而 行 ， 我 就 甚 喜 乐 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30662', '64', '1', '4', '我 听 见 我 的 儿 女 们 按 真 理 而 行 ， 我 的 喜 乐 就 没 有 比 这 个 大 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30663', '64', '1', '5', '＜ 合 作 和 反 对 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30664', '64', '1', '6', '他 们 在 教 会 面 前 证 明 了 你 的 爱 ； 你 若 配 得 过 神 ， 帮 助 他 们 往 前 行 ， 这 就 好 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30665', '64', '1', '7', '因 他 们 是 为 主 的 名 ｛ 古 文 是 那 名 ｝ 出 外 ， 对 于 外 邦 人 一 无 所 取 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30666', '64', '1', '8', '所 以 我 们 应 该 接 待 这 样 的 人 ， 叫 我 们 与 他 们 一 同 为 真 理 做 工 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30667', '64', '1', '9', '我 曾 略 略 地 写 信 给 教 会 ， 但 那 在 教 会 中 好 为 首 的 丢 特 腓 不 接 待 我 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30668', '64', '1', '10', '所 以 我 若 去 ， 必 要 提 说 他 所 行 的 事 ， 就 是 他 用 恶 言 妄 论 我 们 。 还 不 以 此 为 足 ， 他 自 己 不 接 待 弟 兄 ， 有 人 愿 意 接 待 ， 他 也 禁 止 ， 并 且 将 接 待 弟 兄 的 人 赶 出 教 会 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30669', '64', '1', '11', '亲 爱 的 兄 弟 啊 ， 不 要 效 法 恶 ， 只 要 效 法 善 。 行 善 的 属 乎 神 ； 行 恶 的 未 曾 见 过 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30670', '64', '1', '12', '低 米 丢 行 善 ， 有 众 人 给 他 作 见 证 ， 又 有 真 理 给 他 作 见 证 ， 就 是 我 们 也 给 他 作 见 证 。 你 也 知 道 我 们 的 见 证 是 真 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30671', '64', '1', '13', '＜ 问 安 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30672', '64', '1', '14', '但 盼 望 快 快 地 见 你 ， 我 们 就 当 面 谈 论 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30673', '64', '1', '15', '愿 你 平 安 。 众 位 朋 友 都 问 你 安 。 请 你 替 我 按 着 姓 名 问 众 位 朋 友 安 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30674', '65', '1', '1', '耶 稣 基 督 的 仆 人 ， 雅 各 的 弟 兄 犹 大 ， 写 信 给 那 被 召 、 在 父 神 里 蒙 爱 、 为 耶 稣 基 督 保 守 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30675', '65', '1', '2', '愿 怜 恤 、 平 安 、 慈 爱 多 多 地 加 给 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30676', '65', '1', '3', '＜ 假 教 师 受 刑 罚 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30677', '65', '1', '4', '因 为 有 些 人 偷 着 进 来 ， 就 是 自 古 被 定 受 刑 罚 的 ， 是 不 虔 诚 的 ， 将 我 们 神 的 恩 变 作 放 纵 情 欲 的 机 会 ， 并 且 不 认 独 一 的 主 宰 ─ ─ 我 们 ｛ 或 译 ： 和 我 们 ｝ 主 耶 稣 基 督 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30678', '65', '1', '5', '从 前 主 救 了 他 的 百 姓 出 埃 及 地 ， 后 来 就 把 那 些 不 信 的 灭 绝 了 。 这 一 切 的 事 ， 你 们 虽 然 都 知 道 ， 我 却 仍 要 提 醒 你 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30679', '65', '1', '6', '又 有 不 守 本 位 、 离 开 自 己 住 处 的 天 使 ， 主 用 锁 炼 把 他 们 永 远 拘 留 在 黑 暗 里 ， 等 候 大 日 的 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30680', '65', '1', '7', '又 如 所 多 玛 、 蛾 摩 拉 和 周 围 城 邑 的 人 ， 也 照 他 们 一 味 地 行 淫 ， 随 从 逆 性 的 情 欲 ， 就 受 永 火 的 刑 罚 ， 作 为 鉴 戒 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30681', '65', '1', '8', '这 些 做 梦 的 人 也 像 他 们 污 秽 身 体 ， 轻 慢 主 治 的 ， 毁 谤 在 尊 位 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30682', '65', '1', '9', '天 使 长 米 迦 勒 为 摩 西 的 尸 首 与 魔 鬼 争 辩 的 时 候 ， 尚 且 不 敢 用 毁 谤 的 话 罪 责 他 ， 只 说 ： “ 主 责 备 你 吧 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30683', '65', '1', '10', '但 这 些 人 毁 谤 他 们 所 不 知 道 的 。 他 们 本 性 所 知 道 的 事 与 那 没 有 灵 性 的 畜 类 一 样 ， 在 这 事 上 竟 败 坏 了 自 己 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30684', '65', '1', '11', '他 们 有 祸 了 ！ 因 为 走 了 该 隐 的 道 路 ， 又 为 利 往 巴 兰 的 错 谬 里 直 奔 ， 并 在 可 拉 的 背 叛 中 灭 亡 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30685', '65', '1', '12', '这 样 的 人 在 你 们 的 爱 席 上 与 你 们 同 吃 的 时 候 ， 正 是 礁 石 ｛ 或 译 ： 玷 污 ｝ 。 他 们 作 牧 人 ， 只 知 喂 养 自 己 ， 无 所 惧 怕 ； 是 没 有 雨 的 云 彩 ， 被 风 飘 荡 ； 是 秋 天 没 有 果 子 的 树 ， 死 而 又 死 ， 连 根 被 拔 出 来 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30686', '65', '1', '13', '是 海 里 的 狂 浪 ， 涌 出 自 己 可 耻 的 沫 子 来 ； 是 流 荡 的 星 ， 有 墨 黑 的 幽 暗 为 他 们 永 远 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30687', '65', '1', '14', '亚 当 的 七 世 孙 以 诺 ， 曾 预 言 这 些 人 说 ： “ 看 哪 ， 主 带 着 他 的 千 万 圣 者 降 临 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30688', '65', '1', '15', '要 在 众 人 身 上 行 审 判 ， 证 实 那 一 切 不 敬 虔 的 人 所 妄 行 一 切 不 敬 虔 的 事 ， 又 证 实 不 敬 虔 之 罪 人 所 说 顶 撞 他 的 刚 愎 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30689', '65', '1', '16', '这 些 人 是 私 下 议 论 ， 常 发 怨 言 的 ， 随 从 自 己 的 情 欲 而 行 ， 口 中 说 夸 大 的 话 ， 为 得 便 宜 谄 媚 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30690', '65', '1', '17', '＜ 警 告 和 劝 勉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30691', '65', '1', '18', '他 们 曾 对 你 们 说 过 ， 末 世 必 有 好 讥 诮 的 人 随 从 自 己 不 敬 虔 的 私 欲 而 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30692', '65', '1', '19', '这 就 是 那 些 引 人 结 党 、 属 乎 血 气 、 没 有 圣 灵 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30693', '65', '1', '20', '亲 爱 的 弟 兄 啊 ， 你 们 却 要 在 至 圣 的 真 道 上 造 就 自 己 ， 在 圣 灵 里 祷 告 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30694', '65', '1', '21', '保 守 自 己 常 在 神 的 爱 中 ， 仰 望 我 们 主 耶 稣 基 督 的 怜 悯 ， 直 到 永 生 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30695', '65', '1', '22', '有 些 人 存 疑 心 ， 你 们 要 怜 悯 他 们 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30696', '65', '1', '23', '有 些 人 你 们 要 从 火 中 抢 出 来 ， 搭 救 他 们 ； 有 些 人 你 们 要 存 惧 怕 的 心 怜 悯 他 们 ， 连 那 被 情 欲 沾 染 的 衣 服 也 当 厌 恶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30697', '65', '1', '24', '＜ 祝 福 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30698', '65', '1', '25', '愿 荣 耀 、 威 严 、 能 力 、 权 柄 ， 因 我 们 的 主 耶 稣 基 督 归 与 他 ， 从 万 古 以 前 并 现 今 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30699', '66', '1', '1', '＜ 引 言 和 致 意 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30700', '66', '1', '2', '约 翰 便 将 神 的 道 和 耶 稣 基 督 的 见 证 ， 凡 自 己 所 看 见 的 都 证 明 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30701', '66', '1', '3', '念 这 书 上 预 言 的 和 那 些 听 见 又 遵 守 其 中 所 记 载 的 ， 都 是 有 福 的 ， 因 为 日 期 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30702', '66', '1', '4', '约 翰 写 信 给 亚 细 亚 的 七 个 教 会 。 但 愿 从 那 昔 在 、 今 在 、 以 后 永 在 的 神 ， 和 他 宝 座 前 的 七 灵 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30703', '66', '1', '5', '并 那 诚 实 作 见 证 的 、 从 死 里 首 先 复 活 、 为 世 上 君 王 元 首 的 耶 稣 基 督 ， 有 恩 惠 、 平 安 归 与 你 们 ！ 他 爱 我 们 ， 用 自 己 的 血 使 我 们 脱 离 ｛ 有 古 卷 ： 洗 去 ｝ 罪 恶 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30704', '66', '1', '6', '又 使 我 们 成 为 国 民 ， 作 他 父 神 的 祭 司 。 但 愿 荣 耀 、 权 能 归 给 他 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30705', '66', '1', '7', '看 哪 ， 他 驾 云 降 临 ！ 众 目 要 看 见 他 ， 连 刺 他 的 人 也 要 看 见 他 ； 地 上 的 万 族 都 要 因 他 哀 哭 。 这 话 是 真 实 的 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30706', '66', '1', '8', '主 神 说 ： “ 我 是 阿 拉 法 ， 我 是 俄 梅 戛 ｛ 阿 拉 法 ， 俄 梅 戛 ： 是 希 腊 字 母 首 末 二 字 ｝ ， 是 昔 在 、 今 在 、 以 后 永 在 的 全 能 者 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30707', '66', '1', '9', '＜ 基 督 的 异 象 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30708', '66', '1', '10', '当 主 日 ， 我 被 圣 灵 感 动 ， 听 见 在 我 后 面 有 大 声 音 如 吹 号 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30709', '66', '1', '11', '“ 你 所 看 见 的 当 写 在 书 上 ， 达 与 以 弗 所 、 士 每 拿 、 别 迦 摩 、 推 雅 推 喇 、 撒 狄 、 非 拉 铁 非 、 老 底 嘉 那 七 个 教 会 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30710', '66', '1', '12', '我 转 过 身 来 ， 要 看 是 谁 发 声 与 我 说 话 ； 既 转 过 来 ， 就 看 见 七 个 金 灯 台 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30711', '66', '1', '13', '灯 台 中 间 有 一 位 好 像 人 子 ， 身 穿 长 衣 ， 直 垂 到 脚 ， 胸 间 束 着 金 带 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30712', '66', '1', '14', '他 的 头 与 发 皆 白 ， 如 白 羊 毛 ， 如 雪 ； 眼 目 如 同 火 焰 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30713', '66', '1', '15', '脚 好 像 在 炉 中 锻 炼 光 明 的 铜 ； 声 音 如 同 众 水 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30714', '66', '1', '16', '他 右 手 拿 着 七 星 ， 从 他 口 中 出 来 一 把 两 刃 的 利 剑 ； 面 貌 如 同 烈 日 放 光 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30715', '66', '1', '17', '我 一 看 见 ， 就 仆 倒 在 他 脚 前 ， 像 死 了 一 样 。 他 用 右 手 按 着 我 ， 说 ： “ 不 要 惧 怕 ！ 我 是 首 先 的 ， 我 是 末 后 的 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30716', '66', '1', '18', '又 是 那 存 活 的 ； 我 曾 死 过 ， 现 在 又 活 了 ， 直 活 到 永 永 远 远 ； 并 且 拿 着 死 亡 和 阴 间 的 钥 匙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30717', '66', '1', '19', '所 以 你 要 把 所 看 见 的 ， 和 现 在 的 事 ， 并 将 来 必 成 的 事 ， 都 写 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30718', '66', '1', '20', '论 到 你 所 看 见 、 在 我 右 手 中 的 七 星 和 七 个 金 灯 台 的 奥 秘 ， 那 七 星 就 是 七 个 教 会 的 使 者 ， 七 灯 台 就 是 七 个 教 会 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30719', '66', '2', '1', '＜ 给 以 弗 所 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30720', '66', '2', '2', '我 知 道 你 的 行 为 、 劳 碌 、 忍 耐 ， 也 知 道 你 不 能 容 忍 恶 人 。 你 也 曾 试 验 那 自 称 为 使 徒 却 不 是 使 徒 的 ， 看 出 他 们 是 假 的 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30721', '66', '2', '3', '你 也 能 忍 耐 ， 曾 为 我 的 名 劳 苦 ， 并 不 乏 倦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30722', '66', '2', '4', '然 而 有 一 件 事 我 要 责 备 你 ， 就 是 你 把 起 初 的 爱 心 离 弃 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30723', '66', '2', '5', '所 以 ， 应 当 回 想 你 是 从 哪 里 坠 落 的 ， 并 要 悔 改 ， 行 起 初 所 行 的 事 。 你 若 不 悔 改 ， 我 就 临 到 你 那 里 ， 把 你 的 灯 台 从 原 处 挪 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30724', '66', '2', '6', '然 而 你 还 有 一 件 可 取 的 事 ， 就 是 你 恨 恶 尼 哥 拉 一 党 人 的 行 为 ， 这 也 是 我 所 恨 恶 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30725', '66', '2', '7', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ 得 胜 的 ， 我 必 将 神 乐 园 中 生 命 树 的 果 子 赐 给 他 吃 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30726', '66', '2', '8', '＜ 给 示 每 拿 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30727', '66', '2', '9', '我 知 道 你 的 患 难 ， 你 的 贫 穷 （ 你 却 是 富 足 的 ） ， 也 知 道 那 自 称 是 犹 太 人 所 说 的 毁 谤 话 ， 其 实 他 们 不 是 犹 太 人 ， 乃 是 撒 但 一 会 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30728', '66', '2', '10', '你 将 要 受 的 苦 你 不 用 怕 。 魔 鬼 要 把 你 们 中 间 几 个 人 下 在 监 里 ， 叫 你 们 被 试 炼 ， 你 们 必 受 患 难 十 日 。 你 务 要 至 死 忠 心 ， 我 就 赐 给 你 那 生 命 的 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30729', '66', '2', '11', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ 得 胜 的 ， 必 不 受 第 二 次 死 的 害 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30730', '66', '2', '12', '＜ 给 迦 摩 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30731', '66', '2', '13', '我 知 道 你 的 居 所 ， 就 是 有 撒 但 座 位 之 处 ； 当 我 忠 心 的 见 证 人 安 提 帕 在 你 们 中 间 、 撒 但 所 住 的 地 方 被 杀 之 时 ， 你 还 坚 守 我 的 名 ， 没 有 弃 绝 我 的 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30732', '66', '2', '14', '然 而 ， 有 几 件 事 我 要 责 备 你 ： 因 为 在 你 那 里 有 人 服 从 了 巴 兰 的 教 训 ； 这 巴 兰 曾 教 导 巴 勒 将 绊 脚 石 放 在 以 色 列 人 面 前 ， 叫 他 们 吃 祭 偶 像 之 物 ， 行 奸 淫 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30733', '66', '2', '15', '你 那 里 也 有 人 照 样 服 从 了 尼 哥 拉 一 党 人 的 教 训 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30734', '66', '2', '16', '所 以 ， 你 当 悔 改 ； 若 不 悔 改 ， 我 就 快 临 到 你 那 里 ， 用 我 口 中 的 剑 攻 击 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30735', '66', '2', '17', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ 得 胜 的 ， 我 必 将 那 隐 藏 的 吗 哪 赐 给 他 ， 并 赐 他 一 块 白 石 ， 石 上 写 着 新 名 ； 除 了 那 领 受 的 以 外 ， 没 有 人 能 认 识 。 ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30736', '66', '2', '18', '＜ 给 推 雅 推 喇 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30737', '66', '2', '19', '我 知 道 你 的 行 为 、 爱 心 、 信 心 、 勤 劳 、 忍 耐 ， 又 知 道 你 末 后 所 行 的 善 事 ， 比 起 初 所 行 的 更 多 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30738', '66', '2', '20', '然 而 ， 有 一 件 事 我 要 责 备 你 ， 就 是 你 容 让 那 自 称 是 先 知 的 妇 人 耶 洗 别 教 导 我 的 仆 人 ， 引 诱 他 们 行 奸 淫 ， 吃 祭 偶 像 之 物 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30739', '66', '2', '21', '我 曾 给 她 悔 改 的 机 会 ， 她 却 不 肯 悔 改 她 的 淫 行 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30740', '66', '2', '22', '看 哪 ， 我 要 叫 她 病 卧 在 床 。 那 些 与 她 行 淫 的 人 ， 若 不 悔 改 所 行 的 ， 我 也 要 叫 他 们 同 受 大 患 难 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30741', '66', '2', '23', '我 又 要 杀 死 她 的 党 类 ｛ 原 文 是 儿 女 ｝ ， 叫 众 教 会 知 道 ， 我 是 那 察 看 人 肺 腑 心 肠 的 ， 并 要 照 你 们 的 行 为 报 应 你 们 各 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30742', '66', '2', '24', '至 于 你 们 推 雅 推 喇 其 余 的 人 ， 就 是 一 切 不 从 那 教 训 、 不 晓 得 他 们 素 常 所 说 撒 但 深 奥 之 理 的 人 ， 我 告 诉 你 们 ， 我 不 将 别 的 担 子 放 在 你 们 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30743', '66', '2', '25', '但 你 们 已 经 有 的 ， 总 要 持 守 ， 直 等 到 我 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30744', '66', '2', '26', '那 得 胜 又 遵 守 我 命 令 到 底 的 ， 我 要 赐 给 他 权 柄 制 伏 列 国 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30745', '66', '2', '27', '他 必 用 铁 杖 辖 管 ｛ 辖 管 ： 原 文 是 牧 ｝ 他 们 ， 将 他 们 如 同 窑 户 的 瓦 器 打 得 粉 碎 ， 像 我 从 我 父 领 受 的 权 柄 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30746', '66', '2', '28', '我 又 要 把 晨 星 赐 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30747', '66', '2', '29', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30748', '66', '3', '1', '＜ 给 撒 狄 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30749', '66', '3', '2', '你 要 警 醒 ， 坚 固 那 剩 下 将 要 衰 微 ｛ 原 文 是 死 ｝ 的 ； 因 我 见 你 的 行 为 ， 在 我 神 面 前 ， 没 有 一 样 是 完 全 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30750', '66', '3', '3', '所 以 要 回 想 你 是 怎 样 领 受 、 怎 样 听 见 的 ， 又 要 遵 守 ， 并 要 悔 改 。 若 不 警 醒 ， 我 必 临 到 你 那 里 ， 如 同 贼 一 样 。 我 几 时 临 到 ， 你 也 决 不 能 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30751', '66', '3', '4', '然 而 在 撒 狄 ， 你 还 有 几 名 是 未 曾 污 秽 自 己 衣 服 的 ， 他 们 要 穿 白 衣 与 我 同 行 ， 因 为 他 们 是 配 得 过 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30752', '66', '3', '5', '凡 得 胜 的 必 这 样 穿 白 衣 ， 我 也 必 不 从 生 命 册 上 涂 抹 他 的 名 ； 且 要 在 我 父 面 前 ， 和 我 父 众 使 者 面 前 ， 认 他 的 名 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30753', '66', '3', '6', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30754', '66', '3', '7', '＜ 给 非 拉 铁 非 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30755', '66', '3', '8', '我 知 道 你 的 行 为 ， 你 略 有 一 点 力 量 ， 也 曾 遵 守 我 的 道 ， 没 有 弃 绝 我 的 名 。 看 哪 ， 我 在 你 面 前 给 你 一 个 敞 开 的 门 ， 是 无 人 能 关 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30756', '66', '3', '9', '那 撒 但 一 会 的 ， 自 称 是 犹 太 人 ， 其 实 不 是 犹 太 人 ， 乃 是 说 谎 话 的 ， 我 要 使 他 们 来 ， 在 你 脚 前 下 拜 ， 也 使 他 们 知 道 我 是 已 经 爱 你 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30757', '66', '3', '10', '你 既 遵 守 我 忍 耐 的 道 ， 我 必 在 普 天 下 人 受 试 炼 的 时 候 ， 保 守 你 免 去 你 的 试 炼 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30758', '66', '3', '11', '我 必 快 来 ， 你 要 持 守 你 所 有 的 ， 免 得 人 夺 去 你 的 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30759', '66', '3', '12', '得 胜 的 ， 我 要 叫 他 在 我 神 殿 中 作 柱 子 ， 他 也 必 不 再 从 那 里 出 去 。 我 又 要 将 我 神 的 名 和 我 神 城 的 名 ｛ 这 城 就 是 从 天 上 、 从 我 神 那 里 降 下 来 的 新 耶 路 撒 冷 ｝ ， 并 我 的 新 名 ， 都 写 在 他 上 面 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30760', '66', '3', '13', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30761', '66', '3', '14', '＜ 给 老 底 嘉 教 会 的 信 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30762', '66', '3', '15', '我 知 道 你 的 行 为 ， 你 也 不 冷 也 不 热 ； 我 巴 不 得 你 或 冷 或 热 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30763', '66', '3', '16', '你 既 如 温 水 ， 也 不 冷 也 不 热 ， 所 以 我 必 从 我 口 中 把 你 吐 出 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30764', '66', '3', '17', '你 说 ： 我 是 富 足 ， 已 经 发 了 财 ， 一 样 都 不 缺 ； 却 不 知 道 你 是 那 困 苦 、 可 怜 、 贫 穷 、 瞎 眼 、 赤 身 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30765', '66', '3', '18', '我 劝 你 向 我 买 火 炼 的 金 子 ， 叫 你 富 足 ； 又 买 白 衣 穿 上 ， 叫 你 赤 身 的 羞 耻 不 露 出 来 ； 又 买 眼 药 擦 你 的 眼 睛 ， 使 你 能 看 见 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30766', '66', '3', '19', '凡 我 所 疼 爱 的 ， 我 就 责 备 管 教 他 ； 所 以 你 要 发 热 心 ， 也 要 悔 改 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30767', '66', '3', '20', '看 哪 ， 我 站 在 门 外 叩 门 ， 若 有 听 见 我 声 音 就 开 门 的 ， 我 要 进 到 他 那 里 去 ， 我 与 他 ， 他 与 我 一 同 坐 席 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30768', '66', '3', '21', '得 胜 的 ， 我 要 赐 他 在 我 宝 座 上 与 我 同 坐 ， 就 如 我 得 了 胜 ， 在 我 父 的 宝 座 上 与 他 同 坐 一 般 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30769', '66', '3', '22', '圣 灵 向 众 教 会 所 说 的 话 ， 凡 有 耳 的 ， 就 应 当 听 ！ ’ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30770', '66', '4', '1', '＜ 天 上 的 敬 拜 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30771', '66', '4', '2', '我 立 刻 被 圣 灵 感 动 ， 见 有 一 个 宝 座 安 置 在 天 上 ， 又 有 一 位 坐 在 宝 座 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30772', '66', '4', '3', '看 那 坐 着 的 ， 好 像 碧 玉 和 红 宝 石 ； 又 有 虹 围 着 宝 座 ， 好 像 绿 宝 石 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30773', '66', '4', '4', '宝 座 的 周 围 又 有 二 十 四 个 座 位 ； 其 上 坐 着 二 十 四 位 长 老 ， 身 穿 白 衣 ， 头 上 戴 着 金 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30774', '66', '4', '5', '有 闪 电 、 声 音 、 雷 轰 从 宝 座 中 发 出 ； 又 有 七 盏 火 灯 在 宝 座 前 点 着 ； 这 七 灯 就 是 神 的 七 灵 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30775', '66', '4', '6', '宝 座 前 好 像 一 个 玻 璃 海 ， 如 同 水 晶 。 宝 座 中 和 宝 座 周 围 有 四 个 活 物 ， 前 后 遍 体 都 满 了 眼 睛 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30776', '66', '4', '7', '第 一 个 活 物 像 狮 子 ， 第 二 个 像 牛 犊 ， 第 三 个 脸 面 像 人 ， 第 四 个 像 飞 鹰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30777', '66', '4', '8', '四 活 物 各 有 六 个 翅 膀 ， 遍 体 内 外 都 满 了 眼 睛 。 他 们 昼 夜 不 住 地 说 ： 圣 哉 ！ 圣 哉 ！ 圣 哉 ！ 主 神 是 昔 在 、 今 在 、 以 后 永 在 的 全 能 者 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30778', '66', '4', '9', '每 逢 四 活 物 将 荣 耀 、 尊 贵 、 感 谢 归 给 那 坐 在 宝 座 上 、 活 到 永 永 远 远 者 的 时 候 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30779', '66', '4', '10', '那 二 十 四 位 长 老 就 俯 伏 在 坐 宝 座 的 面 前 敬 拜 那 活 到 永 永 远 远 的 ， 又 把 他 们 的 冠 冕 放 在 宝 座 前 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30780', '66', '4', '11', '我 们 的 主 ， 我 们 的 神 ， 你 是 配 得 荣 耀 、 尊 贵 、 权 柄 的 ； 因 为 你 创 造 了 万 物 ， 并 且 万 物 是 因 你 的 旨 意 被 创 造 而 有 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30781', '66', '5', '1', '＜ 书 卷 和 羔 羊 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30782', '66', '5', '2', '我 又 看 见 一 位 大 力 的 天 使 大 声 宣 传 说 ： “ 有 谁 配 展 开 那 书 卷 ， 揭 开 那 七 印 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30783', '66', '5', '3', '在 天 上 、 地 上 、 地 底 下 ， 没 有 能 展 开 、 能 观 看 那 书 卷 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30784', '66', '5', '4', '因 为 没 有 配 展 开 、 配 观 看 那 书 卷 的 ， 我 就 大 哭 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30785', '66', '5', '5', '长 老 中 有 一 位 对 我 说 ： “ 不 要 哭 ！ 看 哪 ， 犹 大 支 派 中 的 狮 子 ， 大 卫 的 根 ， 他 已 得 胜 ， 能 以 展 开 那 书 卷 ， 揭 开 那 七 印 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30786', '66', '5', '6', '我 又 看 见 宝 座 与 四 活 物 ， 并 长 老 之 中 有 羔 羊 站 立 ， 像 是 被 杀 过 的 ， 有 七 角 七 眼 ， 就 是 神 的 七 灵 ， 奉 差 遣 往 普 天 下 去 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30787', '66', '5', '7', '这 羔 羊 前 来 ， 从 坐 宝 座 的 右 手 里 拿 了 书 卷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30788', '66', '5', '8', '他 既 拿 了 书 卷 ， 四 活 物 和 二 十 四 位 长 老 就 俯 伏 在 羔 羊 面 前 ， 各 拿 着 琴 和 盛 满 了 香 的 金 炉 ； 这 香 就 是 众 圣 徒 的 祈 祷 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30789', '66', '5', '9', '他 们 唱 新 歌 ， 说 ： 你 配 拿 书 卷 ， 配 揭 开 七 印 ； 因 为 你 曾 被 杀 ， 用 自 己 的 血 从 各 族 、 各 方 、 各 民 、 各 国 中 买 了 人 来 ， 叫 他 们 归 于 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30790', '66', '5', '10', '又 叫 他 们 成 为 国 民 ， 作 祭 司 归 于 神 ， 在 地 上 执 掌 王 权 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30791', '66', '5', '11', '我 又 看 见 且 听 见 ， 宝 座 与 活 物 并 长 老 的 周 围 有 许 多 天 使 的 声 音 ； 他 们 的 数 目 有 千 千 万 万 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30792', '66', '5', '12', '大 声 说 ： 曾 被 杀 的 羔 羊 是 配 得 权 柄 、 丰 富 、 智 慧 、 能 力 、 尊 贵 、 荣 耀 、 颂 赞 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30793', '66', '5', '13', '我 又 听 见 在 天 上 、 地 上 、 地 底 下 、 沧 海 里 ， 和 天 地 间 一 切 所 有 被 造 之 物 ， 都 说 ： 但 愿 颂 赞 、 尊 贵 、 荣 耀 、 权 势 都 归 给 坐 宝 座 的 和 羔 羊 ， 直 到 永 永 远 远 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30794', '66', '5', '14', '四 活 物 就 说 ： “ 阿 们 ！ ” 众 长 老 也 俯 伏 敬 拜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30795', '66', '6', '1', '＜ 揭 开 封 严 的 印 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30796', '66', '6', '2', '我 就 观 看 ， 见 有 一 匹 白 马 ； 骑 在 马 上 的 ， 拿 着 弓 ， 并 有 冠 冕 赐 给 他 。 他 便 出 来 ， 胜 了 又 要 胜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30797', '66', '6', '3', '揭 开 第 二 印 的 时 候 ， 我 听 见 第 二 个 活 物 说 ： “ 你 来 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30798', '66', '6', '4', '就 另 有 一 匹 马 出 来 ， 是 红 的 ， 有 权 柄 给 了 那 骑 马 的 ， 可 以 从 地 上 夺 去 太 平 ， 使 人 彼 此 相 杀 ； 又 有 一 把 大 刀 赐 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30799', '66', '6', '5', '揭 开 第 三 印 的 时 候 ， 我 听 见 第 三 个 活 物 说 ： “ 你 来 ！ ” 我 就 观 看 ， 见 有 一 匹 黑 马 ； 骑 在 马 上 的 ， 手 里 拿 着 天 平 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30800', '66', '6', '6', '我 听 见 在 四 活 物 中 似 乎 有 声 音 说 ： “ 一 钱 银 子 买 一 升 麦 子 ， 一 钱 银 子 买 三 升 大 麦 ； 油 和 酒 不 可 糟 蹋 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30801', '66', '6', '7', '揭 开 第 四 印 的 时 候 ， 我 听 见 第 四 个 活 物 说 ： “ 你 来 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30802', '66', '6', '8', '我 就 观 看 ， 见 有 一 匹 灰 色 马 ； 骑 在 马 上 的 ， 名 字 叫 作 死 ， 阴 府 也 随 着 他 ； 有 权 柄 赐 给 他 们 ， 可 以 用 刀 剑 、 饥 荒 、 瘟 疫 ｛ 或 译 ： 死 亡 ｝ 、 野 兽 ， 杀 害 地 上 四 分 之 一 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30803', '66', '6', '9', '揭 开 第 五 印 的 时 候 ， 我 看 见 在 祭 坛 底 下 ， 有 为 神 的 道 、 并 为 作 见 证 被 杀 之 人 的 灵 魂 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30804', '66', '6', '10', '大 声 喊 着 说 ： “ 圣 洁 真 实 的 主 啊 ， 你 不 审 判 住 在 地 上 的 人 ， 给 我 们 伸 流 血 的 冤 ， 要 等 到 几 时 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30805', '66', '6', '11', '于 是 有 白 衣 赐 给 他 们 各 人 ； 又 有 话 对 他 们 说 ， 还 要 安 息 片 时 ， 等 着 一 同 作 仆 人 的 和 他 们 的 弟 兄 也 像 他 们 被 杀 ， 满 足 了 数 目 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30806', '66', '6', '12', '揭 开 第 六 印 的 时 候 ， 我 又 看 见 地 大 震 动 ， 日 头 变 黑 像 毛 布 ， 满 月 变 红 像 血 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30807', '66', '6', '13', '天 上 的 星 辰 坠 落 于 地 ， 如 同 无 花 果 树 被 大 风 摇 动 ， 落 下 未 熟 的 果 子 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30808', '66', '6', '14', '天 就 挪 移 ， 好 像 书 卷 被 卷 起 来 ； 山 岭 海 岛 都 被 挪 移 离 开 本 位 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30809', '66', '6', '15', '地 上 的 君 王 、 臣 宰 、 将 军 、 富 户 、 壮 士 ， 和 一 切 为 奴 的 、 自 主 的 ， 都 藏 在 山 洞 和 岩 石 穴 里 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30810', '66', '6', '16', '向 山 和 岩 石 说 ： “ 倒 在 我 们 身 上 吧 ！ 把 我 们 藏 起 来 ， 躲 避 坐 宝 座 者 的 面 目 和 羔 羊 的 忿 怒 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30811', '66', '6', '17', '因 为 他 们 忿 怒 的 大 日 到 了 ， 谁 能 站 得 住 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30812', '66', '7', '1', '＜ 以 色 列 人 十 四 万 四 千 被 印 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30813', '66', '7', '2', '我 又 看 见 另 有 一 位 天 使 ， 从 日 出 之 地 上 来 ， 拿 着 永 生 神 的 印 。 他 就 向 那 得 着 权 柄 能 伤 害 地 和 海 的 四 位 天 使 大 声 喊 着 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30814', '66', '7', '3', '“ 地 与 海 并 树 木 ， 你 们 不 可 伤 害 ， 等 我 们 印 了 我 们 神 众 仆 人 的 额 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30815', '66', '7', '4', '我 听 见 以 色 列 人 各 支 派 中 受 印 的 数 目 有 十 四 万 四 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30816', '66', '7', '5', '犹 大 支 派 中 受 印 的 有 一 万 二 千 ； 吕 便 支 派 中 有 一 万 二 千 ； 迦 得 支 派 中 有 一 万 二 千 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30817', '66', '7', '6', '亚 设 支 派 中 有 一 万 二 千 ； 拿 弗 他 利 支 派 中 有 一 万 二 千 ； 玛 拿 西 支 派 中 有 一 万 二 千 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30818', '66', '7', '7', '西 缅 支 派 中 有 一 万 二 千 ； 利 未 支 派 中 有 一 万 二 千 ； 以 萨 迦 支 派 中 有 一 万 二 千 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30819', '66', '7', '8', '西 布 伦 支 派 中 有 一 万 二 千 ； 约 瑟 支 派 中 有 一 万 二 千 ； 便 雅 悯 支 派 中 受 印 的 有 一 万 二 千 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30820', '66', '7', '9', '＜ 无 数 的 人 从 各 国 各 族 而 来 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30821', '66', '7', '10', '大 声 喊 着 说 ： “ 愿 救 恩 归 与 坐 在 宝 座 上 我 们 的 神 ， 也 归 与 羔 羊 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30822', '66', '7', '11', '众 天 使 都 站 在 宝 座 和 众 长 老 并 四 活 物 的 周 围 ， 在 宝 座 前 ， 面 伏 于 地 ， 敬 拜 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30823', '66', '7', '12', '说 ： 阿 们 ！ 颂 赞 、 荣 耀 、 智 慧 、 感 谢 、 尊 贵 、 权 柄 、 大 力 都 归 与 我 们 的 神 ， 直 到 永 永 远 远 。 阿 们 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30824', '66', '7', '13', '长 老 中 有 一 位 问 我 说 ： “ 这 些 穿 白 衣 的 是 谁 ？ 是 从 哪 里 来 的 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30825', '66', '7', '14', '我 对 他 说 ： “ 我 主 ， 你 知 道 。 ” 他 向 我 说 ： “ 这 些 人 是 从 大 患 难 中 出 来 的 ， 曾 用 羔 羊 的 血 把 衣 裳 洗 白 净 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30826', '66', '7', '15', '所 以 ， 他 们 在 神 宝 座 前 ， 昼 夜 在 他 殿 中 事 奉 他 。 坐 宝 座 的 要 用 帐 幕 覆 庇 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30827', '66', '7', '16', '他 们 不 再 饥 ， 不 再 渴 ； 日 头 和 炎 热 也 必 不 伤 害 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30828', '66', '7', '17', '因 为 宝 座 中 的 羔 羊 必 牧 养 他 们 ， 领 他 们 到 生 命 水 的 泉 源 ； 神 也 必 擦 去 他 们 一 切 的 眼 泪 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30829', '66', '8', '1', '＜ 第 七 印 和 香 炉 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30830', '66', '8', '2', '我 看 见 那 站 在 神 面 前 的 七 位 天 使 ， 有 七 枝 号 赐 给 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30831', '66', '8', '3', '另 有 一 位 天 使 ， 拿 着 金 香 炉 来 ， 站 在 祭 坛 旁 边 。 有 许 多 香 赐 给 他 ， 要 和 众 圣 徒 的 祈 祷 一 同 献 在 宝 座 前 的 金 坛 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30832', '66', '8', '4', '那 香 的 烟 和 众 圣 徒 的 祈 祷 从 天 使 的 手 中 一 同 升 到 神 面 前 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30833', '66', '8', '5', '天 使 拿 着 香 炉 ， 盛 满 了 坛 上 的 火 ， 倒 在 地 上 ； 随 有 雷 轰 、 大 声 、 闪 电 、 地 震 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30834', '66', '8', '6', '＜ 七 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30835', '66', '8', '7', '第 一 位 天 使 吹 号 ， 就 有 雹 子 与 火 搀 着 血 丢 在 地 上 ； 地 的 三 分 之 一 和 树 的 三 分 之 一 被 烧 了 ， 一 切 的 青 草 也 被 烧 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30836', '66', '8', '8', '第 二 位 天 使 吹 号 ， 就 有 仿 佛 火 烧 着 的 大 山 扔 在 海 中 ； 海 的 三 分 之 一 变 成 血 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30837', '66', '8', '9', '海 中 的 活 物 死 了 三 分 之 一 ， 船 只 也 坏 了 三 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30838', '66', '8', '10', '第 三 位 天 使 吹 号 ， 就 有 烧 着 的 大 星 ， 好 像 火 把 从 天 上 落 下 来 ， 落 在 江 河 的 三 分 之 一 和 众 水 的 泉 源 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30839', '66', '8', '11', '（ 这 星 名 叫 “ 茵 蔯 ” 。 ） 众 水 的 三 分 之 一 变 为 茵 蔯 ， 因 水 变 苦 ， 就 死 了 许 多 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30840', '66', '8', '12', '第 四 位 天 使 吹 号 ， 日 头 的 三 分 之 一 、 月 亮 的 三 分 之 一 、 星 辰 的 三 分 之 一 都 被 击 打 ， 以 致 日 月 星 的 三 分 之 一 黑 暗 了 ， 白 昼 的 三 分 之 一 没 有 光 ， 黑 夜 也 是 这 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30841', '66', '8', '13', '我 又 看 见 一 个 鹰 飞 在 空 中 ， 并 听 见 它 大 声 说 ： “ 三 位 天 使 要 吹 那 其 余 的 号 。 你 们 住 在 地 上 的 民 ， 祸 哉 ！ 祸 哉 ！ 祸 哉 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30842', '66', '9', '1', '第 五 位 天 使 吹 号 ， 我 就 看 见 一 个 星 从 天 落 到 地 上 ， 有 无 底 坑 的 钥 匙 赐 给 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30843', '66', '9', '2', '它 开 了 无 底 坑 ， 便 有 烟 从 坑 里 往 上 冒 ， 好 像 大 火 炉 的 烟 ； 日 头 和 天 空 都 因 这 烟 昏 暗 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30844', '66', '9', '3', '有 蝗 虫 从 烟 中 出 来 ， 飞 到 地 上 ； 有 能 力 赐 给 它 们 ， 好 像 地 上 蝎 子 的 能 力 一 样 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30845', '66', '9', '4', '并 且 吩 咐 它 们 说 ， 不 可 伤 害 地 上 的 草 和 各 样 青 物 ， 并 一 切 树 木 ， 惟 独 要 伤 害 额 上 没 有 神 印 记 的 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30846', '66', '9', '5', '但 不 许 蝗 虫 害 死 他 们 ， 只 叫 他 们 受 痛 苦 五 个 月 。 这 痛 苦 就 像 蝎 子 螫 人 的 痛 苦 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30847', '66', '9', '6', '在 那 些 日 子 ， 人 要 求 死 ， 决 不 得 死 ； 愿 意 死 ， 死 却 远 避 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30848', '66', '9', '7', '蝗 虫 的 形 状 ， 好 像 预 备 出 战 的 马 一 样 ， 头 上 戴 的 好 像 金 冠 冕 ， 脸 面 好 像 男 人 的 脸 面 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30849', '66', '9', '8', '头 发 像 女 人 的 头 发 ， 牙 齿 像 狮 子 的 牙 齿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30850', '66', '9', '9', '胸 前 有 甲 ， 好 像 铁 甲 。 它 们 翅 膀 的 声 音 ， 好 像 许 多 车 马 奔 跑 上 阵 的 声 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30851', '66', '9', '10', '有 尾 巴 像 蝎 子 ， 尾 巴 上 的 毒 钩 能 伤 人 五 个 月 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30852', '66', '9', '11', '有 无 底 坑 的 使 者 作 它 们 的 王 ， 按 着 希 伯 来 话 ， 名 叫 亚 巴 顿 ， 希 腊 话 ， 名 叫 亚 玻 伦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30853', '66', '9', '12', '第 一 样 灾 祸 过 去 了 ， 还 有 两 样 灾 祸 要 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30854', '66', '9', '13', '第 六 位 天 使 吹 号 ， 我 就 听 见 有 声 音 从 神 面 前 金 坛 的 四 角 出 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30855', '66', '9', '14', '吩 咐 那 吹 号 的 第 六 位 天 使 ， 说 ： “ 把 那 捆 绑 在 幼 发 拉 底 大 河 的 四 个 使 者 释 放 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30856', '66', '9', '15', '那 四 个 使 者 就 被 释 放 ； 他 们 原 是 预 备 好 了 ， 到 某 年 某 月 某 日 某 时 ， 要 杀 人 的 三 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30857', '66', '9', '16', '马 军 有 二 万 万 ； 他 们 的 数 目 我 听 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30858', '66', '9', '17', '我 在 异 象 中 看 见 那 些 马 和 骑 马 的 ， 骑 马 的 胸 前 有 甲 如 火 ， 与 紫 玛 瑙 并 硫 磺 。 马 的 头 好 像 狮 子 头 ， 有 火 、 有 烟 、 有 硫 磺 从 马 的 口 中 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30859', '66', '9', '18', '口 中 所 出 来 的 火 与 烟 并 硫 磺 ， 这 三 样 灾 杀 了 人 的 三 分 之 一 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30860', '66', '9', '19', '这 马 的 能 力 是 在 口 里 和 尾 巴 上 ； 因 这 尾 巴 像 蛇 ， 并 且 有 头 用 以 害 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30861', '66', '9', '20', '其 余 未 曾 被 这 些 灾 所 杀 的 人 仍 旧 不 悔 改 自 己 手 所 做 的 ， 还 是 去 拜 鬼 魔 和 那 些 不 能 看 、 不 能 听 、 不 能 走 ， 金 、 银 、 铜 、 木 、 石 的 偶 像 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30862', '66', '9', '21', '又 不 悔 改 他 们 那 些 凶 杀 、 邪 术 、 奸 淫 、 偷 窃 的 事 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30863', '66', '10', '1', '＜ 天 使 和 小 书 卷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30864', '66', '10', '2', '他 手 里 拿 着 小 书 卷 ， 是 展 开 的 。 他 右 脚 踏 海 ， 左 脚 踏 地 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30865', '66', '10', '3', '大 声 呼 喊 ， 好 像 狮 子 吼 叫 。 呼 喊 完 了 ， 就 有 七 雷 发 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30866', '66', '10', '4', '七 雷 发 声 之 后 ， 我 正 要 写 出 来 ， 就 听 见 从 天 上 有 声 音 说 ： “ 七 雷 所 说 的 ， 你 要 封 上 ， 不 可 写 出 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30867', '66', '10', '5', '我 所 看 见 的 那 踏 海 踏 地 的 天 使 向 天 举 起 右 手 来 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30868', '66', '10', '6', '指 着 那 创 造 天 和 天 上 之 物 ， 地 和 地 上 之 物 ， 海 和 海 中 之 物 ， 直 活 到 永 永 远 远 的 ， 起 誓 说 ： “ 不 再 有 时 日 了 ｛ 或 译 ： 不 再 耽 延 了 ｝ 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30869', '66', '10', '7', '但 在 第 七 位 天 使 吹 号 发 声 的 时 候 ， 神 的 奥 秘 就 成 全 了 ， 正 如 神 所 传 给 他 仆 人 众 先 知 的 佳 音 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30870', '66', '10', '8', '我 先 前 从 天 上 所 听 见 的 那 声 音 又 吩 咐 我 说 ： “ 你 去 ， 把 那 踏 海 踏 地 之 天 使 手 中 展 开 的 小 书 卷 取 过 来 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30871', '66', '10', '9', '我 就 走 到 天 使 那 里 ， 对 他 说 ： “ 请 你 把 小 书 卷 给 我 。 ” 他 对 我 说 ： “ 你 拿 着 吃 尽 了 ， 便 叫 你 肚 子 发 苦 ， 然 而 在 你 口 中 要 甜 如 蜜 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30872', '66', '10', '10', '我 从 天 使 手 中 把 小 书 卷 接 过 来 ， 吃 尽 了 ， 在 我 口 中 果 然 甜 如 蜜 ， 吃 了 以 后 ， 肚 子 觉 得 发 苦 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30873', '66', '10', '11', '天 使 ｛ 原 文 是 他 们 ｝ 对 我 说 ： “ 你 必 指 着 多 民 、 多 国 、 多 方 、 多 王 再 说 预 言 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30874', '66', '11', '1', '＜ 两 个 见 证 人 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30875', '66', '11', '2', '只 是 殿 外 的 院 子 要 留 下 不 用 量 ， 因 为 这 是 给 了 外 邦 人 的 ； 他 们 要 践 踏 圣 城 四 十 二 个 月 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30876', '66', '11', '3', '我 要 使 我 那 两 个 见 证 人 ， 穿 着 毛 衣 ， 传 道 一 千 二 百 六 十 天 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30877', '66', '11', '4', '他 们 就 是 那 两 棵 橄 榄 树 ， 两 个 灯 台 ， 立 在 世 界 之 主 面 前 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30878', '66', '11', '5', '若 有 人 想 要 害 他 们 ， 就 有 火 从 他 们 口 中 出 来 ， 烧 灭 仇 敌 。 凡 想 要 害 他 们 的 都 必 这 样 被 杀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30879', '66', '11', '6', '这 二 人 有 权 柄 ， 在 他 们 传 道 的 日 子 叫 天 闭 塞 不 下 雨 ； 又 有 权 柄 叫 水 变 为 血 ， 并 且 能 随 时 随 意 用 各 样 的 灾 殃 攻 击 世 界 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30880', '66', '11', '7', '他 们 作 完 见 证 的 时 候 ， 那 从 无 底 坑 里 上 来 的 兽 必 与 他 们 交 战 ， 并 且 得 胜 ， 把 他 们 杀 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30881', '66', '11', '8', '他 们 的 尸 首 就 倒 在 大 城 里 的 街 上 ； 这 城 按 着 灵 意 叫 所 多 玛 ， 又 叫 埃 及 ， 就 是 他 们 的 主 钉 十 字 架 之 处 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30882', '66', '11', '9', '从 各 民 、 各 族 、 各 方 、 各 国 中 ， 有 人 观 看 他 们 的 尸 首 三 天 半 ， 又 不 许 把 尸 首 放 在 坟 墓 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30883', '66', '11', '10', '住 在 地 上 的 人 就 为 他 们 欢 喜 快 乐 ， 互 相 馈 送 礼 物 ， 因 这 两 位 先 知 曾 叫 住 在 地 上 的 人 受 痛 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30884', '66', '11', '11', '过 了 这 三 天 半 ， 有 生 气 从 神 那 里 进 入 他 们 里 面 ， 他 们 就 站 起 来 ； 看 见 他 们 的 人 甚 是 害 怕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30885', '66', '11', '12', '两 位 先 知 听 见 有 大 声 音 从 天 上 来 ， 对 他 们 说 ： “ 上 到 这 里 来 。 ” 他 们 就 驾 着 云 上 了 天 ， 他 们 的 仇 敌 也 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30886', '66', '11', '13', '正 在 那 时 候 ， 地 大 震 动 ， 城 就 倒 塌 了 十 分 之 一 ， 因 地 震 而 死 的 有 七 千 人 ； 其 余 的 都 恐 惧 ， 归 荣 耀 给 天 上 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30887', '66', '11', '14', '第 二 样 灾 祸 过 去 ， 第 三 样 灾 祸 快 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30888', '66', '11', '15', '＜ 第 七 号 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30889', '66', '11', '16', '在 神 面 前 ， 坐 在 自 己 位 上 的 二 十 四 位 长 老 ， 就 面 伏 于 地 ， 敬 拜 神 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30890', '66', '11', '17', '说 ： 昔 在 、 今 在 的 主 神 ─ ─ 全 能 者 啊 ， 我 们 感 谢 你 ！ 因 你 执 掌 大 权 作 王 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30891', '66', '11', '18', '外 邦 发 怒 ， 你 的 忿 怒 也 临 到 了 ； 审 判 死 人 的 时 候 也 到 了 。 你 的 仆 人 众 先 知 和 众 圣 徒 ， 凡 敬 畏 你 名 的 人 ， 连 大 带 小 得 赏 赐 的 时 候 也 到 了 。 你 败 坏 那 些 败 坏 世 界 之 人 的 时 候 也 就 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30892', '66', '11', '19', '当 时 ， 神 天 上 的 殿 开 了 ， 在 他 殿 中 现 出 他 的 约 柜 。 随 后 有 闪 电 、 声 音 、 雷 轰 、 地 震 、 大 雹 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30893', '66', '12', '1', '＜ 妇 人 和 龙 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30894', '66', '12', '2', '她 怀 了 孕 ， 在 生 产 的 艰 难 中 疼 痛 呼 叫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30895', '66', '12', '3', '天 上 又 现 出 异 象 来 ： 有 一 条 大 红 龙 ， 七 头 十 角 ； 七 头 上 戴 着 七 个 冠 冕 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30896', '66', '12', '4', '它 的 尾 巴 拖 拉 着 天 上 星 辰 的 三 分 之 一 ， 摔 在 地 上 。 龙 就 站 在 那 将 要 生 产 的 妇 人 面 前 ， 等 她 生 产 之 后 ， 要 吞 吃 她 的 孩 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30897', '66', '12', '5', '妇 人 生 了 一 个 男 孩 子 ， 是 将 来 要 用 铁 杖 辖 管 ｛ 辖 管 ： 原 文 是 牧 ｝ 万 国 的 ； 她 的 孩 子 被 提 到 神 宝 座 那 里 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30898', '66', '12', '6', '妇 人 就 逃 到 旷 野 ， 在 那 里 有 神 给 她 预 备 的 地 方 ， 使 她 被 养 活 一 千 二 百 六 十 天 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30899', '66', '12', '7', '在 天 上 就 有 了 争 战 。 米 迦 勒 同 他 的 使 者 与 龙 争 战 ， 龙 也 同 它 的 使 者 去 争 战 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30900', '66', '12', '8', '并 没 有 得 胜 ， 天 上 再 没 有 它 们 的 地 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30901', '66', '12', '9', '大 龙 就 是 那 古 蛇 ， 名 叫 魔 鬼 ， 又 叫 撒 但 ， 是 迷 惑 普 天 下 的 。 它 被 摔 在 地 上 ， 它 的 使 者 也 一 同 被 摔 下 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30902', '66', '12', '10', '我 听 见 在 天 上 有 大 声 音 说 ： “ 我 神 的 救 恩 、 能 力 、 国 度 ， 并 他 基 督 的 权 柄 ， 现 在 都 来 到 了 ！ 因 为 那 在 我 们 神 面 前 昼 夜 控 告 我 们 弟 兄 的 ， 已 经 被 摔 下 去 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30903', '66', '12', '11', '弟 兄 胜 过 它 ， 是 因 羔 羊 的 血 和 自 己 所 见 证 的 道 。 他 们 虽 至 于 死 ， 也 不 爱 惜 性 命 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30904', '66', '12', '12', '所 以 ， 诸 天 和 住 在 其 中 的 ， 你 们 都 快 乐 吧 ！ 只 是 地 与 海 有 祸 了 ！ 因 为 魔 鬼 知 道 自 己 的 时 候 不 多 ， 就 气 忿 忿 地 下 到 你 们 那 里 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30905', '66', '12', '13', '龙 见 自 己 被 摔 在 地 上 ， 就 逼 迫 那 生 男 孩 子 的 妇 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30906', '66', '12', '14', '于 是 有 大 鹰 的 两 个 翅 膀 赐 给 妇 人 ， 叫 她 能 飞 到 旷 野 ， 到 自 己 的 地 方 ， 躲 避 那 蛇 ； 她 在 那 里 被 养 活 一 载 二 载 半 载 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30907', '66', '12', '15', '蛇 就 在 妇 人 身 后 ， 从 口 中 吐 出 水 来 ， 像 河 一 样 ， 要 将 妇 人 冲 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30908', '66', '12', '16', '地 却 帮 助 妇 人 ， 开 口 吞 了 从 龙 口 吐 出 来 的 水 ｛ 原 文 是 河 ｝ 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30909', '66', '12', '17', '龙 向 妇 人 发 怒 ， 去 与 她 其 余 的 儿 女 争 战 ， 这 儿 女 就 是 那 守 神 诫 命 、 为 耶 稣 作 见 证 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30910', '66', '12', '18', '那 时 龙 就 站 在 海 边 的 沙 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30911', '66', '13', '1', '＜ 两 个 兽 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30912', '66', '13', '2', '我 所 看 见 的 兽 ， 形 状 像 豹 ， 脚 像 熊 的 脚 ， 口 像 狮 子 的 口 。 那 龙 将 自 己 的 能 力 、 座 位 ， 和 大 权 柄 都 给 了 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30913', '66', '13', '3', '我 看 见 兽 的 七 头 中 ， 有 一 个 似 乎 受 了 死 伤 ， 那 死 伤 却 医 好 了 。 全 地 的 人 都 希 奇 跟 从 那 兽 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30914', '66', '13', '4', '又 拜 那 龙 ─ ─ 因 为 它 将 自 己 的 权 柄 给 了 兽 ， 也 拜 兽 ， 说 ： “ 谁 能 比 这 兽 ， 谁 能 与 它 交 战 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30915', '66', '13', '5', '又 赐 给 它 说 夸 大 亵 渎 话 的 口 ， 又 有 权 柄 赐 给 它 ， 可 以 任 意 而 行 四 十 二 个 月 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30916', '66', '13', '6', '兽 就 开 口 向 神 说 亵 渎 的 话 ， 亵 渎 神 的 名 并 他 的 帐 幕 ， 以 及 那 些 住 在 天 上 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30917', '66', '13', '7', '又 任 凭 它 与 圣 徒 争 战 ， 并 且 得 胜 ； 也 把 权 柄 赐 给 它 ， 制 伏 各 族 、 各 民 、 各 方 、 各 国 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30918', '66', '13', '8', '凡 住 在 地 上 、 名 字 从 创 世 以 来 没 有 记 在 被 杀 之 羔 羊 生 命 册 上 的 人 ， 都 要 拜 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30919', '66', '13', '9', '凡 有 耳 的 ， 就 应 当 听 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30920', '66', '13', '10', '掳 掠 人 的 ， 必 被 掳 掠 ； 用 刀 杀 人 的 ， 必 被 刀 杀 。 圣 徒 的 忍 耐 和 信 心 就 是 在 此 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30921', '66', '13', '11', '我 又 看 见 另 有 一 个 兽 从 地 中 上 来 ， 有 两 角 如 同 羊 羔 ， 说 话 好 像 龙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30922', '66', '13', '12', '它 在 头 一 个 兽 面 前 ， 施 行 头 一 个 兽 所 有 的 权 柄 ， 并 且 叫 地 和 住 在 地 上 的 人 拜 那 死 伤 医 好 的 头 一 个 兽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30923', '66', '13', '13', '又 行 大 奇 事 ， 甚 至 在 人 面 前 ， 叫 火 从 天 降 在 地 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30924', '66', '13', '14', '它 因 赐 给 它 权 柄 在 兽 面 前 能 行 奇 事 ， 就 迷 惑 住 在 地 上 的 人 ， 说 ： “ 要 给 那 受 刀 伤 还 活 着 的 兽 作 个 像 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30925', '66', '13', '15', '又 有 权 柄 赐 给 它 ， 叫 兽 像 有 生 气 ， 并 且 能 说 话 ， 又 叫 所 有 不 拜 兽 像 的 人 都 被 杀 害 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30926', '66', '13', '16', '它 又 叫 众 人 ， 无 论 大 小 、 贫 富 、 自 主 的 、 为 奴 的 ， 都 在 右 手 上 或 是 在 额 上 受 一 个 印 记 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30927', '66', '13', '17', '除 了 那 受 印 记 、 有 了 兽 名 或 有 兽 名 数 目 的 ， 都 不 得 做 买 卖 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30928', '66', '13', '18', '在 这 里 有 智 慧 ： 凡 有 聪 明 的 ， 可 以 算 计 兽 的 数 目 ； 因 为 这 是 人 的 数 目 ， 它 的 数 目 是 六 百 六 十 六 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30929', '66', '14', '1', '＜ 十 四 万 四 千 人 的 歌 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30930', '66', '14', '2', '我 听 见 从 天 上 有 声 音 ， 像 众 水 的 声 音 和 大 雷 的 声 音 ， 并 且 我 所 听 见 的 好 像 弹 琴 的 所 弹 的 琴 声 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30931', '66', '14', '3', '他 们 在 宝 座 前 ， 并 在 四 活 物 和 众 长 老 前 唱 歌 ， 仿 佛 是 新 歌 ； 除 了 从 地 上 买 来 的 那 十 四 万 四 千 人 以 外 ， 没 有 人 能 学 这 歌 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30932', '66', '14', '4', '这 些 人 未 曾 沾 染 妇 女 ， 他 们 原 是 童 身 。 羔 羊 无 论 往 哪 里 去 ， 他 们 都 跟 随 他 。 他 们 是 从 人 间 买 来 的 ， 作 初 熟 的 果 子 归 与 神 和 羔 羊 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30933', '66', '14', '5', '在 他 们 口 中 察 不 出 谎 言 来 ； 他 们 是 没 有 瑕 疵 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30934', '66', '14', '6', '＜ 三 位 天 使 的 信 息 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30935', '66', '14', '7', '他 大 声 说 ： “ 应 当 敬 畏 神 ， 将 荣 耀 归 给 他 ！ 因 他 施 行 审 判 的 时 候 已 经 到 了 。 应 当 敬 拜 那 创 造 天 地 海 和 众 水 泉 源 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30936', '66', '14', '8', '又 有 第 二 位 天 使 接 着 说 ： “ 叫 万 民 喝 邪 淫 、 大 怒 之 酒 的 巴 比 伦 大 城 倾 倒 了 ！ 倾 倒 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30937', '66', '14', '9', '又 有 第 三 位 天 使 接 着 他 们 ， 大 声 说 ： “ 若 有 人 拜 兽 和 兽 像 ， 在 额 上 或 在 手 上 受 了 印 记 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30938', '66', '14', '10', '这 人 也 必 喝 神 大 怒 的 酒 ； 此 酒 斟 在 神 忿 怒 的 杯 中 纯 一 不 杂 。 他 要 在 圣 天 使 和 羔 羊 面 前 ， 在 火 与 硫 磺 之 中 受 痛 苦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30939', '66', '14', '11', '他 受 痛 苦 的 烟 往 上 冒 ， 直 到 永 永 远 远 。 那 些 拜 兽 和 兽 像 ， 受 它 名 之 印 记 的 ， 昼 夜 不 得 安 宁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30940', '66', '14', '12', '圣 徒 的 忍 耐 就 在 此 ； 他 们 是 守 神 诫 命 和 耶 稣 真 道 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30941', '66', '14', '13', '我 听 见 从 天 上 有 声 音 说 ： “ 你 要 写 下 ： 从 今 以 后 ， 在 主 里 面 而 死 的 人 有 福 了 ！ ” 圣 灵 说 ： “ 是 的 ， 他 们 息 了 自 己 的 劳 苦 ， 做 工 的 果 效 也 随 着 他 们 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30942', '66', '14', '14', '＜ 地 上 的 收 割 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30943', '66', '14', '15', '又 有 一 位 天 使 从 殿 中 出 来 ， 向 那 坐 在 云 上 的 大 声 喊 着 说 ： “ 伸 出 你 的 镰 刀 来 收 割 ； 因 为 收 割 的 时 候 已 经 到 了 ， 地 上 的 庄 稼 已 经 熟 透 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30944', '66', '14', '16', '那 坐 在 云 上 的 ， 就 把 镰 刀 扔 在 地 上 ， 地 上 的 庄 稼 就 被 收 割 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30945', '66', '14', '17', '又 有 一 位 天 使 从 天 上 的 殿 中 出 来 ， 他 也 拿 着 快 镰 刀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30946', '66', '14', '18', '又 有 一 位 天 使 从 祭 坛 中 出 来 ， 是 有 权 柄 管 火 的 ， 向 拿 着 快 镰 刀 的 大 声 喊 着 说 ： “ 伸 出 快 镰 刀 来 ， 收 取 地 上 葡 萄 树 的 果 子 ， 因 为 葡 萄 熟 透 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30947', '66', '14', '19', '那 天 使 就 把 镰 刀 扔 在 地 上 ， 收 取 了 地 上 的 葡 萄 ， 丢 在 神 忿 怒 的 大 酒 醡 中 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30948', '66', '14', '20', '那 酒 醡 踹 在 城 外 ， 就 有 血 从 酒 醡 里 流 出 来 ， 高 到 马 的 嚼 环 ， 远 有 六 百 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30949', '66', '15', '1', '＜ 七 位 天 使 掌 管 最 后 的 灾 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30950', '66', '15', '2', '我 看 见 仿 佛 有 玻 璃 海 ， 其 中 有 火 搀 杂 。 又 看 见 那 些 胜 了 兽 和 兽 的 像 并 它 名 字 数 目 的 人 ， 都 站 在 玻 璃 海 上 ， 拿 着 神 的 琴 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30951', '66', '15', '3', '唱 神 仆 人 摩 西 的 歌 和 羔 羊 的 歌 ， 说 ： 主 神 ─ ─ 全 能 者 啊 ， 你 的 作 为 大 哉 ！ 奇 哉 ！ 万 世 ｛ 或 译 ： 国 ｝ 之 王 啊 ， 你 的 道 途 义 哉 ！ 诚 哉 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30952', '66', '15', '4', '主 啊 ， 谁 敢 不 敬 畏 你 ， 不 将 荣 耀 归 与 你 的 名 呢 ？ 因 为 独 有 你 是 圣 的 。 万 民 都 要 来 在 你 面 前 敬 拜 ， 因 你 公 义 的 作 为 已 经 显 出 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30953', '66', '15', '5', '此 后 ， 我 看 见 在 天 上 那 存 法 柜 的 殿 开 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30954', '66', '15', '6', '那 掌 管 七 灾 的 七 位 天 使 从 殿 中 出 来 ， 穿 着 洁 白 光 明 的 细 麻 衣 ｛ 细 麻 衣 ： 有 古 卷 是 宝 石 ｝ ， 胸 间 束 着 金 带 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30955', '66', '15', '7', '四 活 物 中 有 一 个 把 盛 满 了 活 到 永 永 远 远 之 神 大 怒 的 七 个 金 碗 给 了 那 七 位 天 使 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30956', '66', '15', '8', '因 神 的 荣 耀 和 能 力 ， 殿 中 充 满 了 烟 。 于 是 没 有 人 能 以 进 殿 ， 直 等 到 那 七 位 天 使 所 降 的 七 灾 完 毕 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30957', '66', '16', '1', '＜ 神 大 怒 的 碗 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30958', '66', '16', '2', '第 一 位 天 使 便 去 ， 把 碗 倒 在 地 上 ， 就 有 恶 而 且 毒 的 疮 生 在 那 些 有 兽 印 记 、 拜 兽 像 的 人 身 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30959', '66', '16', '3', '第 二 位 天 使 把 碗 倒 在 海 里 ， 海 就 变 成 血 ， 好 像 死 人 的 血 ， 海 中 的 活 物 都 死 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30960', '66', '16', '4', '第 三 位 天 使 把 碗 倒 在 江 河 与 众 水 的 泉 源 里 ， 水 就 变 成 血 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30961', '66', '16', '5', '我 听 见 掌 管 众 水 的 天 使 说 ： 昔 在 、 今 在 的 圣 者 啊 ， 你 这 样 判 断 是 公 义 的 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30962', '66', '16', '6', '他 们 曾 流 圣 徒 与 先 知 的 血 ， 现 在 你 给 他 们 血 喝 ； 这 是 他 们 所 该 受 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30963', '66', '16', '7', '我 又 听 见 祭 坛 中 有 声 音 说 ： 是 的 ， 主 神 ─ ─ 全 能 者 啊 ， 你 的 判 断 义 哉 ！ 诚 哉 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30964', '66', '16', '8', '第 四 位 天 使 把 碗 倒 在 日 头 上 ， 叫 日 头 能 用 火 烤 人 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30965', '66', '16', '9', '人 被 大 热 所 烤 ， 就 亵 渎 那 有 权 掌 管 这 些 灾 的 神 之 名 ， 并 不 悔 改 将 荣 耀 归 给 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30966', '66', '16', '10', '第 五 位 天 使 把 碗 倒 在 兽 的 座 位 上 ， 兽 的 国 就 黑 暗 了 。 人 因 疼 痛 就 咬 自 己 的 舌 头 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30967', '66', '16', '11', '又 因 所 受 的 疼 痛 ， 和 生 的 疮 ， 就 亵 渎 天 上 的 神 ， 并 不 悔 改 所 行 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30968', '66', '16', '12', '第 六 位 天 使 把 碗 倒 在 幼 发 拉 底 大 河 上 ， 河 水 就 干 了 ， 要 给 那 从 日 出 之 地 所 来 的 众 王 预 备 道 路 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30969', '66', '16', '13', '我 又 看 见 三 个 污 秽 的 灵 ， 好 像 青 蛙 ， 从 龙 口 、 兽 口 并 假 先 知 的 口 中 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30970', '66', '16', '14', '他 们 本 是 鬼 魔 的 灵 ， 施 行 奇 事 ， 出 去 到 普 天 下 众 王 那 里 ， 叫 他 们 在 神 全 能 者 的 大 日 聚 集 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30971', '66', '16', '15', '（ 看 哪 ， 我 来 像 贼 一 样 。 那 警 醒 、 看 守 衣 服 、 免 得 赤 身 而 行 、 叫 人 见 他 羞 耻 的 有 福 了 ！ ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30972', '66', '16', '16', '那 三 个 鬼 魔 便 叫 众 王 聚 集 在 一 处 ， 希 伯 来 话 叫 作 哈 米 吉 多 顿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30973', '66', '16', '17', '第 七 位 天 使 把 碗 倒 在 空 中 ， 就 有 大 声 音 从 殿 中 的 宝 座 上 出 来 ， 说 ： “ 成 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30974', '66', '16', '18', '又 有 闪 电 、 声 音 、 雷 轰 、 大 地 震 ， 自 从 地 上 有 人 以 来 ， 没 有 这 样 大 、 这 样 厉 害 的 地 震 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30975', '66', '16', '19', '那 大 城 裂 为 三 段 ， 列 国 的 城 也 都 倒 塌 了 ； 神 也 想 起 巴 比 伦 大 城 来 ， 要 把 那 盛 自 己 烈 怒 的 酒 杯 递 给 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30976', '66', '16', '20', '各 海 岛 都 逃 避 了 ， 众 山 也 不 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30977', '66', '16', '21', '又 有 大 雹 子 从 天 落 在 人 身 上 ， 每 一 个 约 重 一 他 连 得 ｛ 一 他 连 得 约 有 九 十 斤 ｝ 。 为 这 雹 子 的 灾 极 大 ， 人 就 亵 渎 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30978', '66', '17', '1', '＜ 大 淫 妇 和 兽 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30979', '66', '17', '2', '地 上 的 君 王 与 她 行 淫 ， 住 在 地 上 的 人 喝 醉 了 她 淫 乱 的 酒 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30980', '66', '17', '3', '我 被 圣 灵 感 动 ， 天 使 带 我 到 旷 野 去 ， 我 就 看 见 一 个 女 人 骑 在 朱 红 色 的 兽 上 ； 那 兽 有 七 头 十 角 ， 遍 体 有 亵 渎 的 名 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30981', '66', '17', '4', '那 女 人 穿 着 紫 色 和 朱 红 色 的 衣 服 ， 用 金 子 、 宝 石 、 珍 珠 为 妆 饰 ； 手 拿 金 杯 ， 杯 中 盛 满 了 可 憎 之 物 ， 就 是 她 淫 乱 的 污 秽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30982', '66', '17', '5', '在 她 额 上 有 名 写 着 说 ： “ 奥 秘 哉 ！ 大 巴 比 伦 ， 作 世 上 的 淫 妇 和 一 切 可 憎 之 物 的 母 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30983', '66', '17', '6', '我 又 看 见 那 女 人 喝 醉 了 圣 徒 的 血 和 为 耶 稣 作 见 证 之 人 的 血 。 我 看 见 她 ， 就 大 大 地 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30984', '66', '17', '7', '天 使 对 我 说 ： “ 你 为 什 么 希 奇 呢 ？ 我 要 将 这 女 人 和 驮 着 她 的 那 七 头 十 角 兽 的 奥 秘 告 诉 你 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30985', '66', '17', '8', '你 所 看 见 的 兽 ， 先 前 有 ， 如 今 没 有 ， 将 要 从 无 底 坑 里 上 来 ， 又 要 归 于 沉 沦 。 凡 住 在 地 上 、 名 字 从 创 世 以 来 没 有 记 在 生 命 册 上 的 ， 见 先 前 有 、 如 今 没 有 、 以 后 再 有 的 兽 ， 就 必 希 奇 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30986', '66', '17', '9', '智 慧 的 心 在 此 可 以 思 想 。 那 七 头 就 是 女 人 所 坐 的 七 座 山 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30987', '66', '17', '10', '又 是 七 位 王 ； 五 位 已 经 倾 倒 了 ， 一 位 还 在 ， 一 位 还 没 有 来 到 ； 他 来 的 时 候 ， 必 须 暂 时 存 留 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30988', '66', '17', '11', '那 先 前 有 如 今 没 有 的 兽 ， 就 是 第 八 位 ； 他 也 和 那 七 位 同 列 ， 并 且 归 于 沉 沦 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30989', '66', '17', '12', '你 所 看 见 的 那 十 角 就 是 十 王 ； 他 们 还 没 有 得 国 ， 但 他 们 一 时 之 间 要 和 兽 同 得 权 柄 ， 与 王 一 样 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30990', '66', '17', '13', '他 们 同 心 合 意 将 自 己 的 能 力 、 权 柄 给 那 兽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30991', '66', '17', '14', '他 们 与 羔 羊 争 战 ， 羔 羊 必 胜 过 他 们 ， 因 为 羔 羊 是 万 主 之 主 、 万 王 之 王 。 同 着 羔 羊 的 ， 就 是 蒙 召 、 被 选 、 有 忠 心 的 ， 也 必 得 胜 ” 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30992', '66', '17', '15', '天 使 又 对 我 说   ： “ 你 所 看 见 那 淫 妇 坐 的 众 水 ， 就 是 多 民 、 多 人 、 多 国 、 多 方 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30993', '66', '17', '16', '你 所 看 见 的 那 十 角 与 兽 必 恨 这 淫 妇 ， 使 她 冷 落 赤 身 ， 又 要 吃 她 的 肉 ， 用 火 将 她 烧 尽 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30994', '66', '17', '17', '因 为 神 使 诸 王 同 心 合 意 ， 遵 行 他 的 旨 意 ， 把 自 己 的 国 给 那 兽 ， 直 等 到 神 的 话 都 应 验 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30995', '66', '17', '18', '你 所 看 见 的 那 女 人 就 是 管 辖 地 上 众 王 的 大 城 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30996', '66', '18', '1', '＜ 巴 比 伦 倾 倒 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30997', '66', '18', '2', '他 大 声 喊 着 说 ： 巴 比 伦 大 城 倾 倒 了 ！ 倾 倒 了 ！ 成 了 鬼 魔 的 住 处 和 各 样 污 秽 之 灵 的 巢 穴 ｛ 或 译 ： 牢 狱 ； 下 同 ｝ ， 并 各 样 污 秽 可 憎 之 雀 鸟 的 巢 穴 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30998', '66', '18', '3', '因 为 列 国 都 被 她 邪 淫 大 怒 的 酒 倾 倒 了 。 地 上 的 君 王 与 她 行 淫 ； 地 上 的 客 商 因 她 奢 华 太 过 就 发 了 财 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('30999', '66', '18', '4', '我 又 听 见 从 天 上 有 声 音 说 ： 我 的 民 哪 ， 你 们 要 从 那 城 出 来 ， 免 得 与 她 一 同 有 罪 ， 受 她 所 受 的 灾 殃 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31000', '66', '18', '5', '因 她 的 罪 恶 滔 天 ； 她 的 不 义 ， 神 已 经 想 起 来 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31001', '66', '18', '6', '她 怎 样 待 人 ， 也 要 怎 样 待 她 ， 按 她 所 行 的 加 倍 地 报 应 她 ； 用 她 调 酒 的 杯 加 倍 地 调 给 她 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31002', '66', '18', '7', '她 怎 样 荣 耀 自 己 ， 怎 样 奢 华 ， 也 当 叫 她 照 样 痛 苦 悲 哀 ， 因 她 心 里 说 ： 我 坐 了 皇 后 的 位 ， 并 不 是 寡 妇 ， 决 不 至 于 悲 哀 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31003', '66', '18', '8', '所 以 在 一 天 之 内 ， 她 的 灾 殃 要 一 齐 来 到 ， 就 是 死 亡 、 悲 哀 、 饥 荒 。 她 又 要 被 火 烧 尽 了 ， 因 为 审 判 她 的 主 神 大 有 能 力 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31004', '66', '18', '9', '地 上 的 君 王 ， 素 来 与 她 行 淫 、 一 同 奢 华 的 ， 看 见 烧 她 的 烟 ， 就 必 为 她 哭 泣 哀 号 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31005', '66', '18', '10', '因 怕 她 的 痛 苦 ， 就 远 远 地 站 着 说 ： 哀 哉 ！ 哀 哉 ！ 巴 比 伦 大 城 ， 坚 固 的 城 啊 ， 一 时 之 间 你 的 刑 罚 就 来 到 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31006', '66', '18', '11', '地 上 的 客 商 也 都 为 她 哭 泣 悲 哀 ， 因 为 没 有 人 再 买 他 们 的 货 物 了 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31007', '66', '18', '12', '这 货 物 就 是 金 、 银 、 宝 石 、 珍 珠 、 细 麻 布 、 紫 色 料 、 绸 子 、 朱 红 色 料 、 各 样 香 木 、 各 样 象 牙 的 器 皿 、 各 样 极 宝 贵 的 木 头 ， 和 铜 、 铁 、 汉 白 玉 的 器 皿 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31008', '66', '18', '13', '并 肉 桂 、 豆 蔻 、 香 料 、 香 膏 、 乳 香 、 酒 、 油 、 细 面 、 麦 子 、 牛 、 羊 、 车 、 马 ， 和 奴 仆 、 人 口 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31009', '66', '18', '14', '巴 比 伦 哪 ， 你 所 贪 爱 的 果 子 离 开 了 你 ； 你 一 切 的 珍 馐 美 味 和 华 美 的 物 件 也 从 你 中 间 毁 灭 ， 决 不 能 再 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31010', '66', '18', '15', '贩 卖 这 些 货 物 、 藉 着 她 发 了 财 的 客 商 ， 因 怕 她 的 痛 苦 ， 就 远 远 地 站 着 哭 泣 悲 哀 ， 说 ：');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31011', '66', '18', '16', '哀 哉 ！ 哀 哉 ！ 这 大 城 啊 ， 素 常 穿 着 细 麻 、 紫 色 、 朱 红 色 的 衣 服 ， 又 用 金 子 、 宝 石 ， 和 珍 珠 为 妆 饰 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31012', '66', '18', '17', '一 时 之 间 ， 这 么 大 的 富 厚 就 归 于 无 有 了 。 凡 船 主 和 坐 船 往 各 处 去 的 ， 并 众 水 手 ， 连 所 有 靠 海 为 业 的 ， 都 远 远 地 站 着 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31013', '66', '18', '18', '看 见 烧 她 的 烟 ， 就 喊 着 说 ： “ 有 何 城 能 比 这 大 城 呢 ？ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31014', '66', '18', '19', '他 们 又 把 尘 土 撒 在 头 上 ， 哭 泣 悲 哀 ， 喊 着 说 ： 哀 哉 ！ 哀 哉 ！ 这 大 城 啊 。 凡 有 船 在 海 中 的 ， 都 因 她 的 珍 宝 成 了 富 足 ！ 她 在 一 时 之 间 就 成 了 荒 场 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31015', '66', '18', '20', '天 哪 ， 众 圣 徒 、 众 使 徒 、 众 先 知 啊 ， 你 们 都 要 因 她 欢 喜 ， 因 为 神 已 经 在 她 身 上 伸 了 你 们 的 冤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31016', '66', '18', '21', '有 一 位 大 力 的 天 使 举 起 一 块 石 头 ， 好 像 大 磨 石 ， 扔 在 海 里 ， 说 ： 巴 比 伦 大 城 也 必 这 样 猛 力 地 被 扔 下 去 ， 决 不 能 再 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31017', '66', '18', '22', '弹 琴 、 作 乐 、 吹 笛 、 吹 号 的 声 音 ， 在 你 中 间 决 不 能 再 听 见 ； 各 行 手 艺 人 在 你 中 间 决 不 能 再 遇 见 ； 推 磨 的 声 音 在 你 中 间 决 不 能 再 听 见 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31018', '66', '18', '23', '灯 光 在 你 中 间 决 不 能 再 照 耀 ； 新 郎 和 新 妇 的 声 音 ， 在 你 中 间 决 不 能 再 听 见 。 你 的 客 商 原 来 是 地 上 的 尊 贵 人 ； 万 国 也 被 你 的 邪 术 迷 惑 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31019', '66', '18', '24', '先 知 和 圣 徒 ， 并 地 上 一 切 被 杀 之 人 的 血 ， 都 在 这 城 里 看 见 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31020', '66', '19', '1', '此 后 ， 我 听 见 好 像 群 众 在 天 上 大 声 说 ： 哈 利 路 亚 ｛ 就 是 要 赞 美 耶 和 华 的 意 思 ｝ ！ 救 恩 、 荣 耀 、 权 能 都 属 乎 我 们 的 神 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31021', '66', '19', '2', '他 的 判 断 是 真 实 公 义 的 ； 因 他 判 断 了 那 用 淫 行 败 坏 世 界 的 大 淫 妇 ， 并 且 向 淫 妇 讨 流 仆 人 血 的 罪 ， 给 他 们 伸 冤 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31022', '66', '19', '3', '又 说 ： 哈 利 路 亚 ！ 烧 淫 妇 的 烟 往 上 冒 ， 直 到 永 永 远 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31023', '66', '19', '4', '那 二 十 四 位 长 老 与 四 活 物 就 俯 伏 敬 拜 坐 宝 座 的 神 ， 说 ： 阿 们 ！ 哈 利 路 亚 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31024', '66', '19', '5', '＜ 羔 羊 的 婚 筵 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31025', '66', '19', '6', '我 听 见 好 像 群 众 的 声 音 ， 众 水 的 声 音 ， 大 雷 的 声 音 ， 说 ： 哈 利 路 亚 ！ 因 为 主 ─ ─ 我 们 的 神 、 全 能 者 作 王 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31026', '66', '19', '7', '我 们 要 欢 喜 快 乐 ， 将 荣 耀 归 给 他 。 因 为 ， 羔 羊 婚 娶 的 时 候 到 了 ； 新 妇 也 自 己 预 备 好 了 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31027', '66', '19', '8', '就 蒙 恩 得 穿 光 明 洁 白 的 细 麻 衣 。 （ 这 细 麻 衣 就 是 圣 徒 所 行 的 义 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31028', '66', '19', '9', '天 使 吩 咐 我 说 ： “ 你 要 写 上 ： 凡 被 请 赴 羔 羊 之 婚 筵 的 有 福 了 ！ ” 又 对 我 说 ： “ 这 是 神 真 实 的 话 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31029', '66', '19', '10', '我 就 俯 伏 在 他 脚 前 要 拜 他 。 他 说 ： “ 千 万 不 可 ！ 我 和 你 ， 并 你 那 些 为 耶 稣 作 见 证 的 弟 兄 同 是 作 仆 人 的 ， 你 要 敬 拜 神 。 ” 因 为 预 言 中 的 灵 意 乃 是 为 耶 稣 作 见 证 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31030', '66', '19', '11', '＜ 骑 白 马 者 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31031', '66', '19', '12', '他 的 眼 睛 如 火 焰 ， 他 头 上 戴 着 许 多 冠 冕 ； 又 有 写 着 的 名 字 ， 除 了 他 自 己 没 有 人 知 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31032', '66', '19', '13', '他 穿 着 溅 了 血 的 衣 服 ； 他 的 名 称 为 神 之 道 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31033', '66', '19', '14', '在 天 上 的 众 军 骑 着 白 马 ， 穿 着 细 麻 衣 ， 又 白 又 洁 ， 跟 随 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31034', '66', '19', '15', '有 利 剑 从 他 口 中 出 来 ， 可 以 击 杀 列 国 。 他 必 用 铁 杖 辖 管 ｛ 辖 管 ： 原 文 是 牧 ｝ 他 们 ， 并 要 踹 全 能 神 烈 怒 的 酒 醡 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31035', '66', '19', '16', '在 他 衣 服 和 大 腿 上 有 名 写 着 说 ： “ 万 王 之 王 ， 万 主 之 主 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31036', '66', '19', '17', '我 又 看 见 一 位 天 使 站 在 日 头 中 ， 向 天 空 所 飞 的 鸟 大 声 喊 着 说 ： “ 你 们 聚 集 来 赴 神 的 大 筵 席 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31037', '66', '19', '18', '可 以 吃 君 王 与 将 军 的 肉 ， 壮 士 与 马 和 骑 马 者 的 肉 ， 并 一 切 自 主 的 为 奴 的 ， 以 及 大 小 人 民 的 肉 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31038', '66', '19', '19', '我 看 见 那 兽 和 地 上 的 君 王 ， 并 他 们 的 众 军 都 聚 集 ， 要 与 骑 白 马 的 并 他 的 军 兵 争 战 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31039', '66', '19', '20', '那 兽 被 擒 拿 ； 那 在 兽 面 前 曾 行 奇 事 、 迷 惑 受 兽 印 记 和 拜 兽 像 之 人 的 假 先 知 ， 也 与 兽 同 被 擒 拿 。 他 们 两 个 就 活 活 地 被 扔 在 烧 着 硫 磺 的 火 湖 里 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31040', '66', '19', '21', '其 余 的 被 骑 白 马 者 口 中 出 来 的 剑 杀 了 ； 飞 鸟 都 吃 饱 了 他 们 的 肉 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31041', '66', '20', '1', '＜ 一 千 年 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31042', '66', '20', '2', '他 捉 住 那 龙 ， 就 是 古 蛇 ， 又 叫 魔 鬼 ， 也 叫 撒 但 ， 把 它 捆 绑 一 千 年 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31043', '66', '20', '3', '扔 在 无 底 坑 里 ， 将 无 底 坑 关 闭 ， 用 印 封 上 ， 使 它 不 得 再 迷 惑 列 国 。 等 到 那 一 千 年 完 了 ， 以 后 必 须 暂 时 释 放 它 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31044', '66', '20', '4', '我 又 看 见 几 个 宝 座 ， 也 有 坐 在 上 面 的 ， 并 有 审 判 的 权 柄 赐 给 他 们 。 我 又 看 见 那 些 因 为 给 耶 稣 作 见 证 ， 并 为 神 之 道 被 斩 者 的 灵 魂 ， 和 那 没 有 拜 过 兽 与 兽 像 ， 也 没 有 在 额 上 和 手 上 受 过 他 印 记 之 人 的 灵 魂 ， 他 们 都 复 活 了 ， 与 基 督 一 同 作 王 一 千 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31045', '66', '20', '5', '这 是 头 一 次 的 复 活 。 （ 其 余 的 死 人 还 没 有 复 活 ， 直 等 那 一 千 年 完 了 。 ）');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31046', '66', '20', '6', '在 头 一 次 复 活 有 分 的 有 福 了 ， 圣 洁 了 ！ 第 二 次 的 死 在 他 们 身 上 没 有 权 柄 。 他 们 必 作 神 和 基 督 的 祭 司 ， 并 要 与 基 督 一 同 作 王 一 千 年 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31047', '66', '20', '7', '＜ 击 败 撒 但 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31048', '66', '20', '8', '出 来 要 迷 惑 地 上 四 方 ｛ 原 文 是 角 ｝ 的 列 国 ， 就 是 歌 革 和 玛 各 ， 叫 他 们 聚 集 争 战 。 他 们 的 人 数 多 如 海 沙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31049', '66', '20', '9', '他 们 上 来 遍 满 了 全 地 ， 围 住 圣 徒 的 营 与 蒙 爱 的 城 ， 就 有 火 从 天 降 下 ， 烧 灭 了 他 们 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31050', '66', '20', '10', '那 迷 惑 他 们 的 魔 鬼 被 扔 在 硫 磺 的 火 湖 里 ， 就 是 兽 和 假 先 知 所 在 的 地 方 。 他 们 必 昼 夜 受 痛 苦 ， 直 到 永 永 远 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31051', '66', '20', '11', '＜ 末 日 的 审 判 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31052', '66', '20', '12', '我 又 看 见 死 了 的 人 ， 无 论 大 小 ， 都 站 在 宝 座 前 。 案 卷 展 开 了 ， 并 且 另 有 一 卷 展 开 ， 就 是 生 命 册 。 死 了 的 人 都 凭 着 这 些 案 卷 所 记 载 的 ， 照 他 们 所 行 的 受 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31053', '66', '20', '13', '于 是 海 交 出 其 中 的 死 人 ； 死 亡 和 阴 间 也 交 出 其 中 的 死 人 ； 他 们 都 照 各 人 所 行 的 受 审 判 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31054', '66', '20', '14', '死 亡 和 阴 间 也 被 扔 在 火 湖 里 ； 这 火 湖 就 是 第 二 次 的 死 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31055', '66', '20', '15', '若 有 人 名 字 没 记 在 生 命 册 上 ， 他 就 被 扔 在 火 湖 里 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31056', '66', '21', '1', '＜ 新 天 新 地 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31057', '66', '21', '2', '我 又 看 见 圣 城 新 耶 路 撒 冷 由 神 那 里 从 天 而 降 ， 预 备 好 了 ， 就 如 新 妇 妆 饰 整 齐 ， 等 候 丈 夫 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31058', '66', '21', '3', '我 听 见 有 大 声 音 从 宝 座 出 来 说 ： “ 看 哪 ， 神 的 帐 幕 在 人 间 。 他 要 与 人 同 住 ， 他 们 要 作 他 的 子 民 。 神 要 亲 自 与 他 们 同 在 ， 作 他 们 的 神 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31059', '66', '21', '4', '神 要 擦 去 他 们 一 切 的 眼 泪 ； 不 再 有 死 亡 ， 也 不 再 有 悲 哀 、 哭 号 、 疼 痛 ， 因 为 以 前 的 事 都 过 去 了 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31060', '66', '21', '5', '坐 宝 座 的 说 ： “ 看 哪 ， 我 将 一 切 都 更 新 了 ！ ” 又 说 ： “ 你 要 写 上 ； 因 这 些 话 是 可 信 的 ， 是 真 实 的 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31061', '66', '21', '6', '他 又 对 我 说 ： “ 都 成 了 ！ 我 是 阿 拉 法 ， 我 是 俄 梅 戛 ； 我 是 初 ， 我 是 终 。 我 要 将 生 命 泉 的 水 白 白 赐 给 那 口 渴 的 人 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31062', '66', '21', '7', '得 胜 的 ， 必 承 受 这 些 为 业 ： 我 要 作 他 的 神 ， 他 要 作 我 的 儿 子 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31063', '66', '21', '8', '惟 有 胆 怯 的 、 不 信 的 、 可 憎 的 、 杀 人 的 、 淫 乱 的 、 行 邪 术 的 、 拜 偶 像 的 ， 和 一 切 说 谎 话 的 ， 他 们 的 分 就 在 烧 着 硫 磺 的 火 湖 里 ； 这 是 第 二 次 的 死 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31064', '66', '21', '9', '＜ 新 耶 路 撒 冷 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31065', '66', '21', '10', '我 被 圣 灵 感 动 ， 天 使 就 带 我 到 一 座 高 大 的 山 ， 将 那 由 神 那 里 、 从 天 而 降 的 圣 城 耶 路 撒 冷 指 示 我 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31066', '66', '21', '11', '城 中 有 神 的 荣 耀 ； 城 的 光 辉 如 同 极 贵 的 宝 石 ， 好 像 碧 玉 ， 明 如 水 晶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31067', '66', '21', '12', '有 高 大 的 墙 ， 有 十 二 个 门 ， 门 上 有 十 二 位 天 使 ， 门 上 又 写 着 以 色 列 十 二 个 支 派 的 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31068', '66', '21', '13', '东 边 有 三 门 ， 北 边 有 三 门 ， 南 边 有 三 门 ， 西 边 有 三 门 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31069', '66', '21', '14', '城 墙 有 十 二 根 基 ， 根 基 上 有 羔 羊 十 二 使 徒 的 名 字 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31070', '66', '21', '15', '对 我 说 话 的 ， 拿 着 金 苇 子 当 尺 ， 要 量 那 城 和 城 门 城 墙 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31071', '66', '21', '16', '城 是 四 方 的 ， 长 宽 一 样 。 天 使 用 苇 子 量 那 城 ， 共 有 四 千 里 ， 长 、 宽 、 高 都 是 一 样 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31072', '66', '21', '17', '又 量 了 城 墙 ， 按 着 人 的 尺 寸 ， 就 是 天 使 的 尺 寸 ， 共 有 一 百 四 十 四 肘 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31073', '66', '21', '18', '墙 是 碧 玉 造 的 ； 城 是 精 金 的 ， 如 同 明 净 的 玻 璃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31074', '66', '21', '19', '城 墙 的 根 基 是 用 各 样 宝 石 修 饰 的 ： 第 一 根 基 是 碧 玉 ； 第 二 是 蓝 宝 石 ； 第 三 是 绿 玛 瑙 ； 第 四 是 绿 宝 石 ；');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31075', '66', '21', '20', '第 五 是 红 玛 瑙 ； 第 六 是 红 宝 石 ； 第 七 是 黄 璧 玺 ； 第 八 是 水 苍 玉 ； 第 九 是 红 璧 玺 ； 第 十 是 翡 翠 ； 第 十 一 是 紫 玛 瑙 ； 第 十 二 是 紫 晶 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31076', '66', '21', '21', '十 二 个 门 是 十 二 颗 珍 珠 ， 每 门 是 一 颗 珍 珠 。 城 内 的 街 道 是 精 金 ， 好 像 明 透 的 玻 璃 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31077', '66', '21', '22', '我 未 见 城 内 有 殿 ， 因 主 神 ─ ─ 全 能 者 和 羔 羊 为 城 的 殿 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31078', '66', '21', '23', '那 城 内 又 不 用 日 月 光 照 ； 因 有 神 的 荣 耀 光 照 ， 又 有 羔 羊 为 城 的 灯 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31079', '66', '21', '24', '列 国 要 在 城 的 光 里 行 走 ； 地 上 的 君 王 必 将 自 己 的 荣 耀 归 与 那 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31080', '66', '21', '25', '城 门 白 昼 总 不 关 闭 ， 在 那 里 原 没 有 黑 夜 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31081', '66', '21', '26', '人 必 将 列 国 的 荣 耀 、 尊 贵 归 与 那 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31082', '66', '21', '27', '凡 不 洁 净 的 ， 并 那 行 可 憎 与 虚 谎 之 事 的 ， 总 不 得 进 那 城 ； 只 有 名 字 写 在 羔 羊 生 命 册 上 的 才 得 进 去 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31083', '66', '22', '1', '天 使 又 指 示 我 在 城 内 街 道 当 中 一 道 生 命 水 的 河 ， 明 亮 如 水 晶 ， 从 神 和 羔 羊 的 宝 座 流 出 来 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31084', '66', '22', '2', '在 河 这 边 与 那 边 有 生 命 树 ， 结 十 二 样 ｛ 或 译 ： 回 ｝ 果 子 ， 每 月 都 结 果 子 ； 树 上 的 叶 子 乃 为 医 治 万 民 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31085', '66', '22', '3', '以 后 再 没 有 咒 诅 ； 在 城 里 有 神 和 羔 羊 的 宝 座 ； 他 的 仆 人 都 要 事 奉 他 ，');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31086', '66', '22', '4', '也 要 见 他 的 面 。 他 的 名 字 必 写 在 他 们 的 额 上 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31087', '66', '22', '5', '不 再 有 黑 夜 ； 他 们 也 不 用 灯 光 、 日 光 ， 因 为 主 神 要 光 照 他 们 。 他 们 要 作 王 ， 直 到 永 永 远 远 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31088', '66', '22', '6', '＜ 基 督 再 临 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31089', '66', '22', '7', '“ 看 哪 ， 我 必 快 来 ！ 凡 遵 守 这 书 上 预 言 的 有 福 了 ！ ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31090', '66', '22', '8', '这 些 事 是 我 ─ ─ 约 翰 所 听 见 、 所 看 见 的 ； 我 既 听 见 、 看 见 了 ， 就 在 指 示 我 的 天 使 脚 前 俯 伏 要 拜 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31091', '66', '22', '9', '他 对 我 说 ： “ 千 万 不 可 ！ 我 与 你 和 你 的 弟 兄 众 先 知 ， 并 那 些 守 这 书 上 言 语 的 人 ， 同 是 作 仆 人 的 。 你 要 敬 拜 神 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31092', '66', '22', '10', '他 又 对 我 说 ： “ 不 可 封 了 这 书 上 的 预 言 ， 因 为 日 期 近 了 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31093', '66', '22', '11', '不 义 的 ， 叫 他 仍 旧 不 义 ； 污 秽 的 ， 叫 他 仍 旧 污 秽 ； 为 义 的 ， 叫 他 仍 旧 为 义 ； 圣 洁 的 ， 叫 他 仍 旧 圣 洁 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31094', '66', '22', '12', '“ 看 哪 ， 我 必 快 来 ！ 赏 罚 在 我 ， 要 照 各 人 所 行 的 报 应 他 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31095', '66', '22', '13', '我 是 阿 拉 法 ， 我 是 俄 梅 戛 ； 我 是 首 先 的 ， 我 是 末 后 的 ； 我 是 初 ， 我 是 终 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31096', '66', '22', '14', '那 些 洗 净 自 己 衣 服 的 有 福 了 ！ 可 得 权 柄 能 到 生 命 树 那 里 ， 也 能 从 门 进 城 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31097', '66', '22', '15', '城 外 有 那 些 犬 类 、 行 邪 术 的 、 淫 乱 的 、 杀 人 的 、 拜 偶 像 的 ， 并 一 切 喜 好 说 谎 言 、 编 造 虚 谎 的 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31098', '66', '22', '16', '“ 我 ─ ─ 耶 稣 差 遣 我 的 使 者 为 众 教 会 将 这 些 事 向 你 们 证 明 。 我 是 大 卫 的 根 ， 又 是 他 的 后 裔 。 我 是 明 亮 的 晨 星 。 ”');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31099', '66', '22', '17', '圣 灵 和 新 妇 都 说 ： “ 来 ！ ” 听 见 的 人 也 该 说 ： “ 来 ！ ” 口 渴 的 人 也 当 来 ； 愿 意 的 ， 都 可 以 白 白 取 生 命 的 水 喝 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31100', '66', '22', '18', '＜ 警 戒 增 减 这 书 上 的 预 言 ＞ 
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31101', '66', '22', '19', '这 书 上 的 预 言 ， 若 有 人 删 去 什 么 ， 神 必 从 这 书 上 所 写 的 生 命 树 和 圣 城 删 去 他 的 分 。');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31102', '66', '22', '20', '证 明 这 事 的 说 ： “ 是 了 ， 我 必 快 来 ！ ” 阿 们 ！ 主 耶 稣 啊 ， 我 愿 你 来 ！');
INSERT INTO `bible_verses_chinese_union_simp` VALUES ('31103', '66', '22', '21', '愿 主 耶 稣 的 恩 惠 常 与 众 圣 徒 同 在 。 阿 们 ！');